window.TURATH_DATA.hadith.push(...[{"num":5735,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْمُزَابَنَةِ وَالْمُحَاقَلَةِ وَالْمُزَابَنَةُ اشْتِرَاءُ الثَّمَرِ بِالتَّمْرِ فِي رُءُوسِ النَّخْلِ وَالْمُحَاقَلَةُ كِرَاءُ الأَرْضِ بِالْحِنْطَةِ."],"takhrij":"متفق عليه: رواه مالك في البيوع (24) عن داود بن الحصين، عن أبي سفيان مولى ابن أبي أحمد، عن أبي سعيد الخدري فذكره.","grade":"متفق عليه","chapter_ar":"باب في النهي عن بيع المزابنة والمحاقلة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by Malik (24), al-Bukhari (2186), and Muslim (1546).","chapter_en":"The Prohibition of al-Muzabanah and al-Muhaqalah","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":19,"content":{"translation":{"en":["Abu Saeed al-Khudri reported that the Messenger of Allah ﷺ forbade al-muzabanah and al-muhaqalah. Al-muzabanah is buying fruit on the trees in exchange for dried dates. Al-muhaqalah is renting land in exchange for wheat."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":24,"lafz":true},{"key":"bukhari","label":"البخاري","number":2186},{"key":"muslim","label":"مسلم","number":1546}],"full":1,"dr":1,"rep":[5554]},{"num":5736,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُحَاقَلَةِ وَالْمُزَابَنَةِ."],"takhrij":"صحيح: رواه البخاري في البيوع (2187) عن مسدد، حدثنا أبو معاوية، عن الشيباني، عن عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب في النهي عن بيع المزابنة والمحاقلة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by al-Bukhari (2187).","chapter_en":"The Prohibition of al-Muzabanah and al-Muhaqalah","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":19,"content":{"translation":{"en":["Ibn Abbas reported: The Prophet ﷺ forbade al-muhaqalah and al-muzabanah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2187,"lafz":true}],"full":1},{"num":5737,"demo":false,"sanad":"","matn":["عَنْ جابر بْنِ عَبْدِ اللَّهِ أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنِ الْمُزَابَنَةِ وَالْحُقُولِ، فَقَالَ جَابِرُ بْنُ عَبْدِ اللَّهِ: الْمُزَابَنَةُ الثَّمَرُ بِالتَّمْرِ. وَالْحُقُولُ كِرَاءُ الأَرْضِ."],"takhrij":"صحيح: رواه مسلم في البيوع (1536/103) عن الحسن الحلواني، حدثنا أبو توبة، حدثنا معاوية، عن يحيى بن أبي كثير، أن يزيد بن نُعيم أخبره أن جابر بن عبدالله أخبره فذكره.قال ابن شهاب: وحدثني سالم بن عبد الله بن عمر، عن أبيه، عن النبي صلى الله عليه وسلم مثله سواء.","grade":"صحيح","chapter_ar":"باب في النهي عن بيع المزابنة والمحاقلة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1536, no. 103).","chapter_en":"The Prohibition of al-Muzabanah and al-Muhaqalah","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":19,"content":{"translation":{"en":["Jabir ibn Abdullah reported that he heard the Messenger of Allah ﷺ forbid al-muzabanah and al-haqul. Jabir said: al-muzabanah is fruit for dates, and al-haqul means renting land."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1536,"lafz":true,"n":3932}],"full":1},{"num":5738,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْمُحَاقَلَةِ وَالْمُزَابَنَةِ وَالْمُخَابَرَةِ وَأَنْ تُشْتَرَى النَّخْلُ حَتَّى تُشْقِهَ - وَالإِشْقَاهُ أَنْ يَحْمَرَّ أَوْ يَصْفَرَّ أَوْ يُؤْكَلَ مِنْهُ شَىْءٌ - وَالْمُحَاقَلَةُ أَنْ يُبَاعَ الْحَقْلُ بِكَيْلٍ مِنَ الطَّعَامِ مَعْلُومٍ وَالْمُزَابَنَةُ أَنْ يُبَاعَ النَّخْلُ بِأَوْسَاقٍ مِنَ التَّمْرِ وَالْمُخَابَرَةُ الثُّلُثُ وَالرُّبُعُ وَأَشْبَاهُ ذَلِكَ."],"takhrij":"صحيح: رواه مسلم (1536: 83) من طرق عن زكريا بن عدي، أخبرنا عبيدالله، عن زيد بن أبى أنيسة، حدثنا أبو الوليد المكي -وهو جالس عند عطاء بن أبى رباح- عن جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب في النهي عن بيع المزابنة والمحاقلة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1536, no. 83).","chapter_en":"The Prohibition of al-Muzabanah and al-Muhaqalah","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":19,"content":{"translation":{"en":["Jabir ibn Abdullah reported that the Messenger of Allah ﷺ forbade al-muhaqalah, al-muzabanah, and al-mukhabarah, and that palm trees should not be sold until their fruit becomes sound. Becoming sound means that it turns red or yellow, or that some of it is edible. Al-muhaqalah is selling a field for a known measured amount of food. Al-muzabanah is selling date palms for fixed measures of dates. Al-mukhabarah is an arrangement involving one-third, one-fourth, and similar shares."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1536,"lafz":true,"n":3911}],"full":1,"dr":1},{"num":5739,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُحَاقَلَةِ وَالْمُزَابَنَةِ."],"takhrij":"صحيح: رواه مسلم في البيوع (1545) عن قتيبة بن سعيد، حدثنا يعقوب (يعني ابن عبد الرحمن القاري)، عن سهيل بن أبي صـالح، عن أبيه، عن أبي هريرة.","grade":"صحيح","chapter_ar":"باب في النهي عن بيع المزابنة والمحاقلة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1545).","chapter_en":"The Prohibition of al-Muzabanah and al-Muhaqalah","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":19,"content":{"translation":{"en":["Abu Hurayrah reported: The Messenger of Allah ﷺ forbade al-muhaqalah and al-muzabanah."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1545,"lafz":true}],"full":1,"rep":[5546]},{"num":5740,"demo":false,"sanad":"","matn":["عَنْ رَافِعِ بْنِ خَدِيجٍ، قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُحَاقَلَةِ وَالْمُزَابَنَةِ."],"takhrij":"حسن: رواه أبو داود (3400)، وابن ماجه (2267)، والنسائي (3890) كلهم من حديث أبي الأحوص، عن طارق بن عبدالرحمن، عن سعيد بن المسيب، عن رافع بن خديج فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الرخصة في بيع العرايا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3400), Ibn Mājah (2267), and al-Nasāʾī (3890).","chapter_en":"What has come regarding the concession for selling the araya","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":20,"content":{"translation":{"en":["Rāfiʿ ibn Khadīj reported: The Messenger of Allah ﷺ prohibited muḥāqalah and muzābanah."]},"buhuth":{"en":["They also added after the statement that the Messenger of Allah ﷺ prohibited muḥāqalah and muzābanah:","“Only three types of people cultivate land: a man who owns land and cultivates it; a man who has been granted land and cultivates what he was granted; and a man who rents land for gold or silver.”","The correct view is that this statement is an explanation from Saʿīd ibn al-Musayyib."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3400,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2267},{"key":"nasai","label":"النسائي","number":3890,"n":3802}],"full":1,"dr":1},{"num":5741,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ ثَابِتٍ رَضِيَ اللَّهُ عَنْهُمْ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَرْخَصَ لِصَاحِبِ الْعَرِيَّةِ أَنْ يَبِيعَهَا بِخَرْصِهَا."],"takhrij":"متفق عليه: رواه مالك في البيوع (14) عن نافع، عن عبد الله بن عمر، عن زيد بن ثابت فذكره. ورواه البخاري في البيوع (2188) ومسلم في البيوع (1539: 60) كلاهما من طريق مالك به مثله، وزاد مسلم: \"من التمر\".","grade":"متفق عليه","chapter_ar":"باب ما جاء في الرخصة في بيع العرايا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (14), al-Bukhari (2188), and Muslim (1539/60). Muslim added: “for dates.”","chapter_en":"What has come regarding the concession for selling the araya","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":20,"content":{"translation":{"en":["Zayd ibn Thabit reported that the Messenger of Allah ﷺ gave permission to the owner of an ariyah to sell it according to its estimated measure."]},"buhuth":{"en":["Al-Bukhari also narrated through another chain with the wording: “The Messenger of Allah ﷺ allowed the araya to be sold according to their estimated measure by dry measure.”","Musa ibn ‘Uqbah said: “Araya are specific palm trees; one comes to buy them.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":14},{"key":"bukhari","label":"البخاري","number":2188,"lafz":true},{"key":"muslim","label":"مسلم","number":60},{"key":"muslim","label":"مسلم في البيوع","number":1539,"n":3879}],"full":1,"dr":1},{"num":5742,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ ثَابِتٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَخَّصَ فِي بَيْعِ الْعَرَايَا أَنْ تُبَاعَ بِخَرْصِهَا، وَلَمْ يُرَخِّصْ فِي غَيْرِ ذَلِكَ."],"takhrij":"صحيح: رواه الإمام أحمد (21581)، والدارمي (2600)، وابن حبان (5009) كلهم من حديث الأوزاعي، عن الزهري، عن سالم، عن أبيه، عن زيد بن ثابت فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الرخصة في بيع العرايا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (21581), al-Darimi (2600), and Ibn Hibban (5009).","chapter_en":"What has come regarding the concession for selling the araya","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":20,"content":{"translation":{"en":["Zayd ibn Thabit reported that the Messenger of Allah ﷺ permitted the sale of the araya according to estimate, and he did not permit that in anything else."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":21581,"lafz":true},{"key":"darimi","label":"الدارمي","number":2600},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":5621,"n":5617},{"key":"ibnhibban","label":"ابن حبان","number":5009}],"full":1,"dr":1},{"num":5743,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُحَاقَلَةِ، وَالْمُزَابَنَةِ، وَالْمُعَاوَمَةِ، وَالْمُخَابَرَةِ، وَعَنِ الثُّنْيَا، وَرَخَّصَ فِي الْعَرَايَا."],"takhrij":"صحيح: رواه مسلم في البيوع (1536: 85) من طرق عن حماد بن زيد، حدثنا أيوب، عن أبي الزبير، وسعيد بن ميناء، عن جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الرخصة في بيع العرايا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1536/85).","chapter_en":"What has come regarding the concession for selling the araya","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":20,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The Messenger of Allah ﷺ forbade selling standing crops for a measured amount of grain, the sale of fresh produce for dried produce by estimate, multi-year fruit sales, sharecropping, and undefined exceptions in a sale, but he allowed the araya."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":85,"lafz":true},{"key":"muslim","label":"مسلم في البيوع","number":1536,"n":3913}],"full":1,"dr":1},{"num":5744,"demo":false,"sanad":"","matn":["عن سهل بْنِ أَبِي حَثْمَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ بَيْعِ الثَّمَرِ بِالتَّمْرِ وَقَالَ ذَلِكَ الرِّبَا تِلْكَ الْمُزَابَنَةُ. إِلاَّ أَنَّهُ رَخَّصَ فِي بَيْعِ الْعَرِيَّةِ النَّخْلَةِ وَالنَّخْلَتَيْنِ يَأْخُذُهَا أَهْلُ الْبَيْتِ بِخَرْصِهَا تَمْرًا يَأْكُلُونَهَا رُطَبًا."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2191)، ومسلم في البيوع (1540: 67) كلاهما من طريق يحيى بن سعيد (هو الأنصاري)، عن بُشير بن يسار، عن بعض أصحـاب رسول الله صلى الله عليه وسلم من أهل دارهم، منهم سهل بن أبى حثمة فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الرخصة في بيع العرايا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2191) and Muslim (1540/67). The wording is Muslim’s.","chapter_en":"What has come regarding the concession for selling the araya","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":20,"content":{"translation":{"en":["Sahl ibn Abi Hathmah reported that the Messenger of Allah ﷺ forbade selling fresh dates for dried dates and said: “That is usury; that is the forbidden exchange.” But he permitted the sale of an ariyah: one or two palm trees whose estimated amount is taken in dried dates by a household so they may eat them fresh."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2191,"lafz":true},{"key":"muslim","label":"مسلم","number":67},{"key":"muslim","label":"مسلم في البيوع","number":1540}],"full":1},{"num":5745,"demo":false,"sanad":"","matn":["عن رافـع بن خديـج، وسهـل بن أبي حثمـة حدثا أن رسول الله صلى الله عليه وسلم نهى عن المزابنة، بيع الثمر بالتمر إلا أصحاب العرايا، فإنه أذن لهم."],"takhrij":"متفق عليه: رواه البخاري في المساقاة (2383، 2384)، ومسلم في البيوع (1540: 70) كلاهما من حديث أبي أسامة قال: أخبرني الوليد بن كثير قال: أخبرني بُشير بن يسار مولى بني حارثة أن رافع بن خديج وسهل بن أبي حثمة حدثاه فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الرخصة في بيع العرايا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari in the chapter of irrigation-share contracts (2383, 2384) and Muslim in sales (1540/70).","chapter_en":"What has come regarding the concession for selling the araya","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":20,"content":{"translation":{"en":["Rafi‘ ibn Khadij and Sahl ibn Abi Hathmah reported that the Messenger of Allah ﷺ forbade the sale of fruit for dried dates, except for the people of the araya, for he gave them permission."]},"buhuth":{"en":["His statement “ariyah” and “araya” refers to the sale of the fruit of specific palm trees, after its ripeness has appeared, estimated against dried dates measured on the ground. The Lawgiver exempted it from the general prohibition because people needed it. It is called ariyah because it was excluded from the general ruling of prohibition. The word carries the sense of “set apart.”","The forms of this transaction are many. Among what Ibn Hajar mentioned in al-Fath are:","One form is that a man says to the owner of an orchard: Sell me the fruit of certain named palm trees for an estimated amount of dried dates. The amount is estimated, the sale is concluded, the dried dates are received from him, and the trees are handed over by making them available.","Another form is that the orchard owner gifts a man certain palm trees, or the fruit of certain palm trees, from his orchard, then becomes inconvenienced by his repeated entry. So he estimates them and buys back their fresh fruit for the amount of dried dates corresponding to the estimate, paid immediately.","Another form is that a man sells the dates of his orchard after ripeness has appeared, but excludes certain known palm trees for himself and his family. These are the ones exempted from estimation in charity. So needy people who have no cash, but do have surplus dried dates for food, were allowed to buy the fresh fruit of those trees with dried dates according to estimate."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري في المساقاة","number":2384,"lafz":true},{"key":"muslim","label":"مسلم في البيوع","number":70},{"key":"bukhari","label":"البخاري في المساقاه","number":2383},{"key":"muslim","label":"مسلم في البيوع","number":1540,"n":3891}],"full":1,"dr":1},{"num":5746,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَخَّصَ فِي بَيْعِ الْعَرَايَا بِخَرْصِهَا فِيمَا دُونَ خَمْسَةِ أَوْسُقٍ أَوْ فِي خَمْسَةِ -"],"takhrij":"متفق عليه: رواه مالك في البيوع (14) عن داود بن الحصين، عن أبي سفيان مولى ابن أبي أحمد، عن أبي هريرة فذكره. ورواه البخاري في البيوع (2190)، ومسلم في البيوع (1541) كلاهما من طريق مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب جواز العرايا فيما دون خمسة أوسق","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (14), al-Bukhari (2190), and Muslim (1541).","chapter_en":"The permissibility of araya in amounts under five wasqs","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":21,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ permitted the sale of the araya according to estimate in amounts less than five wasqs, or up to five wasqs."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":14,"lafz":true},{"key":"bukhari","label":"البخاري","number":2190,"n":2382},{"key":"muslim","label":"مسلم","number":1541}],"full":1,"dr":1},{"num":5747,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ أَذِنَ لِأَصْحَابِ الْعَرَايَا أَنْ يَبِيعُوهَا بِخَرْصِهَا، يَقُولُ: الْوَسْقَ، وَالْوَسْقَيْنِ، وَالثَّلَاثَةَ، وَالْأَرْبَعَةَ."],"takhrij":"حسن: رواه الإمام أحمد (14868)، وأبو يعـلى (1780)، وصحّحه ابن حبان (5008)، وابن خزيمة (2469) كلهم من حديث محمد بن إسحاق قال: حدثني محمد بن يحيى بن حبان، عن عمه واسع بن حَبان، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب جواز العرايا فيما دون خمسة أوسق","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (14868), Abu Ya‘la (1780), and authenticated by Ibn Hibban (5008) and Ibn Khuzaymah (2469).","chapter_en":"The permissibility of araya in amounts under five wasqs","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":21,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah al-Ansari said: I heard the Messenger of Allah ﷺ, when he permitted the people of the araya to sell them by estimate, say: “One wasq, two wasqs, three, and four.”"]},"buhuth":{"en":["A wasq is sixty sa‘s. A sa‘ is five and one-third Iraqi pounds. The total comes to three hundred sa‘s, which is approximately 700 kilograms today."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":14868,"lafz":true},{"key":"sh12520","label":"أبو يعلى","number":1780},{"key":"ibnhibban","label":"صححه ابن حبان","number":5008},{"key":"ibnkhuzaymah","label":"ابن خزيمة","number":2469}],"full":1,"dr":1},{"num":5748,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ أَبِي عَيَّاشٍ أَنَّهُ سَأَلَ سَعْدَ بْنَ أَبِي وَقَّاصٍ عَنِ الْبَيْضَاءِ بِالسُّلْتِ، فَقَالَ لَهُ سَعْدٌ: أيتهما أَفْضَلُ؟ قَالَ: الْبَيْضَاءُ. فَنَهَاهُ عَنْ ذَلِكَ. وَقَالَ سعد: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُسْأَلُ عَنْ اشتراء التَّمْرِ بِالرُّطَبِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيَنْقُصُ الرُّطَبُ إِذَا يَبِسَ؟ فَقَالُوا: نَعَمْ، فنهى عَنْ ذَلِكَ."],"takhrij":"حسن: رواه مالك في البيوع (22) عن عبد الله بن يزيد أن زيدا أبا عياش أخبره فذكره.","grade":"حسن","chapter_ar":"باب النهي عن بيع الرطب بالتمر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Malik (22), Abu Dawud (3359), al-Tirmidhi (1225), al-Nasa’i (4549), and Ibn Majah (2264).","chapter_en":"The prohibition of selling fresh dates for dried dates","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":22,"content":{"translation":{"en":["Zayd Abu ‘Ayyash asked Sa‘d ibn Abi Waqqas about trading white grain for sult grain. Sa‘d said to him: “Which of them is better?” He replied: “The white one.” So Sa‘d forbade him from that. Sa‘d then said: I heard the Messenger of Allah ﷺ being asked about buying dried dates with fresh dates, and the Messenger of Allah ﷺ said: “Do the fresh dates decrease when they dry?” They said: “Yes.” So he forbade that."]},"buhuth":{"en":["“Al-bayda” is a type of wheat that is white in color. “Al-sult” is another type, different from wheat, with finer grain. Some said that “al-bayda” here means the fresh form of sult, and that fits the meaning of the hadith better, since it is compared to fresh dates versus dried dates. If the category were different, the comparison would not hold."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":22,"lafz":true},{"key":"abudawud","label":"أبو داود","number":3359},{"key":"tirmidhi","label":"الترمذي","number":1225},{"key":"nasai","label":"النسائي","number":4549},{"key":"ibnmajah","label":"ابن ماجه","number":2264}],"full":1,"dr":1},{"num":5749,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ بَيْعِ الثِّمَارِ حَتَّى يَبْدُوَ صَلاَحُهَا، نَهَى الْبَائِعَ والمشتري."],"takhrij":"متفق عليه: رواه مالك في البيوع (10) عن نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (10), al-Bukhari (2194), and Muslim (1534/49).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Ibn ‘Umar reported that the Messenger of Allah ﷺ forbade selling fruits until their ripeness appears. He forbade both the seller and the buyer."]},"buhuth":{"en":["Al-Bukhari (1486) added: “When he was asked about their ripeness, he said: ‘Until their blight is gone.’”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":10,"lafz":true},{"key":"bukhari","label":"البخاري","number":2194},{"key":"muslim","label":"مسلم","number":49}],"full":1,"dr":1},{"num":5750,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ بَيْعِ النَّخْلِ حَتَّى يَزْهُوَ وَعَنِ السُّنْبُلِ حَتَّى يَبْيَضَّ وَيَأْمَنَ الْعَاهَةَ نَهَى الْبَائِعَ وَالْمُشْتَرِيَ."],"takhrij":"صحيح: رواه مسلم في البيوع (1535) من طرق عن إسماعيل، عن أيوب، عن نافع، عن ابن عمر فذكره. ومن هذا الوجه رواه كل من أبي داود (3368)، والترمذي (1226)، والنسائي (4551).","grade":"صحيح","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1535).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Ibn ‘Umar reported that the Messenger of Allah ﷺ forbade selling dates on the palm until they show ripeness, and grain in the ear until it turns white and is safe from blight. He forbade both the seller and the buyer."]},"buhuth":{"en":["Ripeness in dates means that they turn red or yellow. That is a sign that they have ripened and evidence that they are safe from damage.","His statement regarding grain “until it turns white” apparently refers to selling grain while still in the ear once it hardens and whitens."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1535,"lafz":true},{"key":"abudawud","label":"من هذا الوجه رواه كل من ابي داود","number":3368},{"key":"tirmidhi","label":"الترمذي","number":1226},{"key":"nasai","label":"النسائي","number":4551,"n":4551}],"full":1,"dr":1},{"num":5751,"demo":false,"sanad":"","matn":["عَنْ عُثْمَانَ بْنِ عَبْدِ اللَّهِ بْنِ سُرَاقَةَ قَالَ: كُنَّا فِي سَفَرٍ وَمَعَنَا ابْنُ عُمَرَ فَسَأَلْتُهُ، فَقَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يُسَبِّحُ فِي السَّفَرِ قَبْلَ الصَّلَاةِ وَلَا بَعْدَهَا قَالَ: وَسَأَلْتُ ابْنَ عُمَرَ عَنْ بَيْعِ الثِّمَارِ، فَقَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعِ الثِّمَارِ حَتَّى تَذْهَبَ الْعَاهَةُ، قُلْتُ: أَبَا عَبْدِ الرَّحْمَنِ وَمَا تَذْهَبُ الْعَاهَةُ، مَا الْعَاهَةُ؟ قَالَ: طُلُوعُ الثُّرَيَّا."],"takhrij":"صحيح: رواه الإمام أحمد (5012، 5015)، والطبراني في الكبير (13287)، والبيهقي (5/300) كلهم من طريق ابن أبي ذئب، عن عثمان بن عبد الله بن سراقة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (5012, 5015), al-Tabarani in al-Kabir (13287), and al-Bayhaqi (5/300).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["‘Uthman ibn ‘Abd Allah ibn Suraqah said: We were on a journey with Ibn ‘Umar, and I asked him. He said: I saw the Messenger of Allah ﷺ not perform voluntary prayer before the prescribed prayer while traveling, nor after it. He said: And I asked Ibn ‘Umar about selling fruits, so he said: The Messenger of Allah ﷺ forbade selling fruits until the blight is gone. I said: O Abu ‘Abd al-Rahman, what does it mean for the blight to be gone? What is the blight? He said: The rising of the Pleiades."]},"buhuth":{"en":["The rising of the Pleiades is a sign that the blight affecting fruits has passed. The same will also come from Zayd ibn Thabit."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":5015,"lafz":true,"n":5012},{"key":"mujamkabir","label":"الطبراني في الكبير","number":13287},{"key":"kubrabayhaqi","label":"البيهقي","number":300},{"key":"ahmad","label":"مسند الإمام أحمد","number":5012,"n":5012}],"full":1,"dr":1},{"num":5752,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ بَيْعِ ثَمَرِ النَّخْلِ حَتَّى تَزْهُوَ. فَقُلْنَا لأَنَسٍ مَا زَهْوُهَا قَالَ تَحْمَرُّ وَتَصْفَرُّ. أَرَأَيْتَكَ إِنْ مَنَعَ اللَّهُ الثَّمَرَةَ بِمَ تَسْتَحِلُّ مَالَ أَخِيكَ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2208)، ومسلم في المساقاة (1555) كلاهما عن قتيبة، حدثنا إسماعيل بن جعفر، عن حميد، عن أنس فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2208) and Muslim (1555). The wording is Muslim’s.","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Anas ibn Malik reported that the Prophet ﷺ forbade selling the fruit of date palms until it shows ripeness. We asked Anas: What is its ripeness? He said: It turns red and yellow. “If Allah withholds the fruit, then by what right would one of you take his brother’s wealth?”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2208,"lafz":true},{"key":"muslim","label":"مسلم","number":1555}],"full":1},{"num":5753,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ بَيْعِ الثِّمَارِ حَتَّى تُزهِيَ. فَقِيلَ لَهُ: يَا رَسُولَ اللَّهِ، وَمَا تُزْهِي؟. فَقَالَ: حِينَ تَحْمَرَّ. وَقَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَرَأَيْتَ إِذَا مَنَعَ اللَّهُ الثَّمَرَةَ فبم يَأْخُذُ أَحَدُكُمْ مَالَ أَخِيهِ."],"takhrij":"متفق عليه: رواه مالك في البيوع (11) عن حميد الطويل، عن أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (11), al-Bukhari (2198), and Muslim (1555).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Anas ibn Malik reported that the Messenger of Allah ﷺ forbade selling fruits until they show ripeness. It was said to him: O Messenger of Allah ﷺ, what is their ripeness? He said: “When they turn red.” And the Messenger of Allah ﷺ said: “If Allah withholds the fruit, then by what right would one of you take his brother’s wealth?”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":11,"lafz":true},{"key":"bukhari","label":"البخاري","number":2198},{"key":"muslim","label":"مسلم","number":1555}],"full":1,"dr":1},{"num":5754,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ يَقُولُ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَوْ بِعْتَ مِنْ أَخِيكَ ثَمَرًا فَأَصَابَتْهُ جَائِحَةٌ فَلاَ يَحِلُّ لَكَ أَنْ تَأْخُذَ مِنْهُ شَيْئًا بِمَ تَأْخُذُ مَالَ أَخِيكَ بِغَيْرِ حَقٍّ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1554) عن أبي الطاهر، أخبرنا ابن وهب، عن ابن جريج، أن أبا الزبير أخبره عن جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1554).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The Messenger of Allah ﷺ said: “If you sold fruit to your brother and then a calamity struck it, it is not lawful for you to take anything from him. By what right would you take your brother’s wealth without due right?”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1554,"lafz":true}],"full":1,"dr":1},{"num":5755,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أن تباع الثَّمَرَةِ حَتَّى تُشْقِحَ.قـــال: فَقُلْتُ لسعيـــد: وَمَا تُشْقِحُ؟ قــال: تَحْمَارُّ، وَتَصْفَارُّ، وَيُؤْكَلُ مِنْهَا."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2196)، ومسلم في البيوع (1536: 84) من طريق سليم بن حيان، حدثنا سعيد بن ميناء قال: سمعت جابر بن عبد الله قال فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2196) and Muslim (1536/84).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The Prophet ﷺ forbade fruit from being sold until it ripens. I said to Sa‘id: What does ripening mean? He said: It becomes red, becomes yellow, and some of it is eaten."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2196,"lafz":true},{"key":"muslim","label":"مسلم","number":84},{"key":"muslim","label":"مسلم في البيوع","number":1536,"n":3912}],"full":1},{"num":5756,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعِ الثَّمَرِ حَتَّى يَطِيبَ، وَلاَ يُبَاعُ شَىْءٌ مِنْهُ إِلاَّ بِالدِّينَارِ وَالدِّرْهَمِ إِلاَّ الْعَرَايَا."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2189) من طريق ابن جريج، عن عطاء، وأبي الزبير، عن جابر فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2189) and Muslim (1536/53). In another wording: The Messenger of Allah ﷺ forbade selling fruit until its ripeness appears.","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The Prophet ﷺ forbade selling fruit until it becomes wholesome, and nothing from it is to be sold except for gold and silver, except in the case of the araya."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2189,"lafz":true},{"key":"muslim","label":"مسلم","number":53}],"full":1,"dr":1},{"num":5757,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ تَبْتَاعُوا الثِّمَارَ حَتَّى يَبْدُوَ صَلاَحُهَا."],"takhrij":"صحيح: رواه مسلم في البيوع (1538) عن أبي كريب محمد بن العلاء، حدثنا محمد بن فضيل، عن أبيه، عن ابن أبي نُعم، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1538). Another chain adds: “And do not buy fruit with dried dates.”","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Do not buy fruits until their ripeness appears.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1538,"lafz":true}],"full":1,"dr":1},{"num":5758,"demo":false,"sanad":"","matn":["عَنْ أَبِي الْبَخْتَرِيِّ، قَالَ سَأَلْتُ ابْنَ عَبَّاسٍ عَنْ بَيْعِ النَّخْلِ، فَقَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعِ النَّخْلِ حَتَّى يَأْكُلَ مِنْهُ أَوْ يُؤْكَلَ وَحَتَّى يُوزَنَ. قَالَ فَقُلْتُ مَا يُوزَنُ فَقَالَ رَجُلٌ عِنْدَهُ حَتَّى يَحْزَرَ."],"takhrij":"متفق عليه: رواه البخاري في السلم (2246)، ومسلم في البيوع (1537) كلاهما من طريق شعبة، أخبرنا عمرو بن مرة قال: سمعت أبا البختري الطائي فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2246) and Muslim (1537). The wording is Muslim’s.","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Abu al-Bakhtari said: I asked Ibn ‘Abbas about selling date palms, and he said: The Messenger of Allah ﷺ forbade selling the dates on the palm until one may eat from them, or they are eaten, and until they are weighed. I said: What does “weighed” mean? A man beside him said: Until they can be estimated."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2246,"lafz":true},{"key":"muslim","label":"مسلم","number":1537}],"full":1,"dr":1},{"num":5759,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ كَانَ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يُبَاعُ الثَّمَرُ حَتَّى يُطْعَمَ."],"takhrij":"صحيح: رواه أحمد (2247)، والطبراني في الكبير (1187، 1188)، وصحّحه ابن حبان (4988) كلهم من طريق عمرو بن دينار، عن طاوس، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (2247), al-Tabarani in al-Kabir (1187, 1188), and authenticated by Ibn Hibban (4988).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Ibn ‘Abbas used to say: The Messenger of Allah ﷺ said: “Fruit is not to be sold until it can be eaten.”"]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":1187},{"key":"ibnhibban","label":"صححه ابن حبان","number":4988},{"key":"ahmad","label":"مسند الإمام أحمد","number":2247,"n":2247,"lafz":true},{"key":"mujamkabir","label":"الطبراني في الكبير","number":1188}],"full":1,"dr":1},{"num":5760,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بن ثَابِتٍ قَالَ: كَانَ النَّاسُ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَبَايَعُونَ الثِّمَارَ، فَإِذَا جذ النَّاسُ وَحَضَرَ تَقَاضِيهِمْ قَالَ الْمُبْتَاعُ: إِنَّهُ أَصَابَ الثَّمَرَ الدُّمَانُ، أَصَابَهُ مرض، أَصَابَهُ قُشَامٌ –عَاهَاتٌ يَحْتَجُّونَ بِهَا-، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا كَثُرَتْ عِنْدَهُ الْخُصُومَةُ فِي ذَلِكَ: فَأَمَّا لَا فَلَا تتبايعوا حَتَّى يَبْدُوَ صَلَاحُ الثَّمَرِ كَالْمَشُورَةِ يُشِيرُ بِهَا لِكَثْرَةِ خُصُومَتِهِمْ."],"takhrij":"صحيح: رواه أبو داود (3372)، وأحمد (216662)، والبيهقي (5/301-302) كلهم من حديث يونس بن محمد قال: سألت أبا الزناد عن بيع الثمر قبل أن يبدو صلاحه، وما ذكر في ذلك، فقال: كان عروة بن الزبير يحدث عن سهل بن أبي حثمة، عن زيد بن ثابت قال فذكر الحديث نحوه. هكذا قال أبو داود.","grade":"صحيح","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (3372), Ahmad (21662), and al-Bayhaqi (5/301-302).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Zayd ibn Thabit said: In the time of the Messenger of Allah ﷺ, people used to buy and sell fruits. When the people harvested them and the time for settlement came, the buyer would say: The fruit was struck by blight, or disease, or damage — defects they used as excuses. So when disputes over that became frequent before him, the Messenger of Allah ﷺ said: “Then, if you insist, do not trade in fruits until their ripeness appears,” as advice from him because of how much they were disputing."]},"buhuth":{"en":["“Jadhdha” means the people cut the fruit from the date palms. “Jadhadh” means harvesting the date fruit by cutting and taking it from the tree.","“Al-daman” was explained as damage to the flower cluster, its decay, and blackening.","“Qusham” was explained in one narration as something that affects it so that it never becomes ripe. It was also said to mean that the fruit decreases before becoming firm unripe dates.","The phrase “fa imma la” means: if you do not do such-and-such, then do this instead.","The mention of the rising of the Pleiades means at dawn at the beginning of summer, when the heat intensifies in the Hijaz. What really matters is ripeness, and the rising of the Pleiades is simply a sign for it."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3372,"lafz":true},{"key":"ahmad","label":"أحمد","number":21662},{"key":"kubrabayhaqi","label":"البيهقي","number":301},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":10605,"n":10694},{"key":"ahmad","label":"احمد","number":216662}],"full":1,"dr":1},{"num":5761,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا تَبِيعُوا ثِمَارَكُمْ حَتَّى يَبْدُوَ صَلَاحُهَا، وَتَنْجُوَ مِنَ الْعَاهَةِ."],"takhrij":"حسن: رواه الإمام أحمد (24407) والحارث في مسنده –\"بغية الباحث\" (ص 470)- من حديث عبد الرحمن بن أبي الرجال، عن أبيه، عن عمرة، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (24407) and al-Harith in his Musnad, Bughyat al-Bahith (p. 470).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["The Mother of the Believers, ‘A’ishah, reported that the Prophet ﷺ said: “Do not sell your fruits until their ripeness appears and they are safe from blight.”"]},"buhuth":{"en":["Understanding of this chapter:","The scholars act upon this and do not allow selling fruits before signs of ripeness appear, for the reason mentioned in the hadiths.","But if someone sells them on condition that they be cut immediately, then it is permissible by agreement of the scholars, because cutting removes the risk of destruction by blight or defect. In that case, the reason for the prohibition is no longer present.","The appearance of ripeness differs according to the type of fruit. In fresh dates, it is when they become unripe ripe dates and signs of red or black dots appear. In peaches, pears, apricots, and apples, it is when they become good enough to eat. In melons, it is when signs of ripeness appear. In cucumbers and eggplants, it is when they are usually ready to be picked.","The rising of the star — meaning the Pleiades — is a sign of the beginning of summer and the start of fruit ripening. What really matters is ripeness itself, and the rising of the star is only a sign of it, as came in the hadith: “until the yellow becomes distinct from the red.”","If ripeness appears in part of the crop, then selling all of it is allowed if it is all one kind. If the kinds differ, then each kind is judged by the appearance of ripeness in itself, unless cutting is stipulated for what has not yet ripened, in which case selling everything is allowed.","Likewise, it is not allowed to sell crops before the grain hardens in the ear, as came in the hadith of Ibn Umar."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":24407,"lafz":true},{"key":"sh13160","label":"الحارث في مسنده “بغية الباحث”","number":470}],"full":1,"dr":1},{"num":5762,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بوضع الجوائح."],"takhrij":"صحيح: رواه مسلم في المساقاة (1554: 17) من طريق سفيان بن عيينة، عن حميد الأعرج، عن سليمان بن عتيق، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في وضع الجائحة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1554/17). Al-Shafi‘i also narrated it in al-Umm (3/56), and in it is: “The Messenger of Allah ﷺ forbade selling for future years and ordered remission in cases of blight.”","chapter_en":"What has come regarding remission in the case of a blight or calamity","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":24,"content":{"translation":{"en":["Jabir reported that the Prophet ﷺ ordered that losses caused by blight be remitted."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":17,"lafz":true},{"key":"sh1655","label":". ورواه الشافعي في الأم","number":56,"n":163},{"key":"muslim","label":"مسلم في المساقاه","number":1554,"n":3969}],"full":1,"dr":1},{"num":5763,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ بَيْعِ السِّنِينَ وَوَضَعَ الْجَوَائِحَ."],"takhrij":"صحيح: رواه أبو داود (3374) عـن أحمد بن حنبل ويحيى بن معين قالا: حدثنا سفيان، عن حميدالأعرج، عن سليمان بن عتيق، عن جابر بن عبدالله فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في وضع الجائحة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3374).","chapter_en":"What has come regarding remission in the case of a blight or calamity","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":24,"content":{"translation":{"en":["Jabir reported that the Prophet ﷺ forbade selling fruit for future years and ruled that losses caused by blight be remitted."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3374,"lafz":true}],"full":1,"dr":1},{"num":5764,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَوْ بِعْتَ مِنْ أَخِيكَ ثَمَرًا فَأَصَابَتْهُ جَائِحَةٌ فَلاَ يَحِلُّ لَكَ أَنْ تَأْخُذَ مِنْهُ شَيْئًا بِمَ تَأْخُذُ مَالَ أَخِيكَ بِغَيْرِ حَقٍّ."],"takhrij":"صحيح رواه مسلم في المساقاة (1554: 14) عن أبي الطاهر، أخبرنا ابن وهب، عن ابن جريج أن أبا الزبير أخبره عن جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في وضع الجائحة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1554/14).","chapter_en":"What has come regarding remission in the case of a blight or calamity","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":24,"content":{"translation":{"en":["Jabir ibn Abd Allah said: The Messenger of Allah ﷺ said, “If you sold fruit to your brother and then it was struck by a calamity, it is not lawful for you to take anything from him. With what right would you take your brother’s wealth without right?”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":14,"lafz":true},{"key":"muslim","label":"صحيح رواه مسلم في المساقاه","number":1554}],"full":1},{"num":5765,"demo":false,"sanad":"","matn":["عَنْ أَبِي، سَعِيدٍ الْخُدْرِيِّ قَالَ أُصِيبَ رَجُلٌ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي ثِمَارٍ ابْتَاعَهَا فَكَثُرَ دَيْنُهُ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَصَدَّقُوا عَلَيْهِ. فَتَصَدَّقَ النَّاسُ عَلَيْهِ فَلَمْ يَبْلُغْ ذَلِكَ وَفَاءَ دَيْنِهِ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِغُرَمَائِهِ خُذُوا مَا وَجَدْتُمْ وَلَيْسَ لَكُمْ إِلاَّ ذَلِكَ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1556) عن قتيبة بن سعيد، حدثنا الليث، عن بكير، عن عياض بن عبد الله ، عن أبي سعيد الخدري فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في وضع الجائحة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1556).","chapter_en":"What has come regarding remission in the case of a blight or calamity","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":24,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī reported: A man during the lifetime of the Messenger of Allah ﷺ suffered a loss in fruits that he had purchased, and his debts became numerous. The Messenger of Allah ﷺ said: “Give charity to him.” The people gave charity to him, but it was not enough to repay his debt fully. The Messenger of Allah ﷺ then said to his creditors: “Take whatever you find, and you are entitled to nothing beyond that.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1556,"lafz":true}],"full":1,"dr":1,"rep":[4254,5634,12484]},{"num":5766,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعِ الْحَصَاةِ وَعَنْ بَيْعِ الْغَرَرِ."],"takhrij":"صحيح: رواه مسلم في البيوع (1513) من طرق عن عبيدالله، حدثني أبو الزناد، عن الأعرج، عن أبي هريرة قال فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع الغرر، وبيع الحصاة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1513).","chapter_en":"The prohibition of uncertain sales and pebble sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":25,"content":{"translation":{"en":["Abū Hurayrah reported: The Messenger of Allah ﷺ prohibited the pebble sale and transactions involving excessive uncertainty."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1513,"lafz":true}],"full":1,"dr":1},{"num":5767,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ، قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعِ الْغَرَرِ."],"takhrij":"حسن: رواه الإمام أحمـد (6307) عن يعلى ومحمد قالا: حدثنا محمد -يعني ابن إسحاق-، حدثني نافع، عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب النهي عن بيع الغرر، وبيع الحصاة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6307) and Ibn Hibban in his Sahih (4972).","chapter_en":"The prohibition of uncertain sales and pebble sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":25,"content":{"translation":{"en":["Ibn Umar said: The Messenger of Allah ﷺ forbade uncertain sale."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":6307,"lafz":true},{"key":"ibnhibban","label":"ابن حبان في صحيحه","number":4972},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1932,"n":1929}],"full":1,"dr":1},{"num":5768,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ بَيْعِ حَبَلِ الْحَبَلَةِ، وَكَانَ بَيْعًا يَتَبَايَعُهُ أَهْلُ الْجَاهِلِيَّةِ، كَانَ الرَّجُلُ يَبْتَاعُ الْجَزُورَ إِلَى أَنْ تُنْتَجَ النَّاقَةُ، ثُمَّ تُنْتَجُ الَّتِي فِي بَطْنِهَا."],"takhrij":"متفق عليه: رواه مـالك في البيوع (62) عن نافـع، عن عبد الله بن عمر فذكره. ورواه البخاري في البيوع (2143) من طريق مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع حبل الحبلة، والمضامين، والملاقيح","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (62), al-Bukhari (2143), and Muslim (1514).","chapter_en":"The prohibition of selling habal al-habalah, unborn offspring, and what is still in the wombs","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":26,"content":{"translation":{"en":["Abd Allah ibn Umar reported that the Messenger of Allah ﷺ forbade the sale of habal al-habalah. This was a sale practiced by the people of the pre-Islamic era: a man would buy a camel on delayed terms until a she-camel gave birth, and then until the one in her womb gave birth."]},"buhuth":{"en":["Explanation: Al-Nawawi said that scholars differed over what exactly is meant by habal al-habalah. Some said it means a sale with payment delayed until the she-camel gives birth and then its offspring gives birth. Others said it means selling the offspring of a pregnant she-camel immediately, and this is closer to the language. Ibn al-Athir said the first “habal” refers to the pregnancy in the bellies of the camels, and the second to the pregnancy of what is in those bellies. It was forbidden for two reasons: first, because it is uncertainty and the sale of something not yet created; second, because it may also refer to an unknown time limit, and that is invalid."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":62},{"key":"bukhari","label":"البخاري","number":2143,"lafz":true},{"key":"muslim","label":"مسلم","number":1514}],"full":1,"dr":1},{"num":5769,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، عـن النبي صلى الله عليه وسلم أنه قال: في السلف في حبل الحبل ربا."],"takhrij":"صحيح: رواه النسائي (4622)، وأحمد (2145) كلاهما من حديث محمد بن جعفر، حدثنا شعبة، عن أيوب، عن سعيد بن جبير، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع حبل الحبلة، والمضامين، والملاقيح","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (4622) and Ahmad (2145).","chapter_en":"The prohibition of selling habal al-habalah, unborn offspring, and what is still in the wombs","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":26,"content":{"translation":{"en":["Abd Allah ibn Abbas reported that the Prophet ﷺ said: “There is usury in an advance sale involving habal al-habal.”"]},"buhuth":{"en":["Explanation: Here, salaf means that the buyer pays the price in advance to a man who has a pregnant she-camel and says: when this camel gives birth, and then the one in her womb gives birth, I have bought that offspring from you for this price. This resembles usury in the sense that it is forbidden like usury, because the seller is selling what he does not possess and cannot deliver, so it contains uncertainty."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4622,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":2145,"n":2145}],"full":1,"dr":1},{"num":5770,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ، عَبْدِ اللَّهِ قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُحَاقَلَةِ وَالْمُزَابَنَةِ وَالْمُعَاوَمَةِ وَالْمُخَابَرَةِ - قَالَ أَحَدُهُمَا بَيْعُ السِّنِينَ هِيَ الْمُعَاوَمَةُ - وَعَنِ الثُّنْيَا وَرَخَّصَ فِي الْعَرَايَا."],"takhrij":"صحيح: رواه مسلم في البيوع (1536: 85) من طريق حماد بن زيد، حدثنا أيوب، عن أبي الزبير وسعيد بن ميناء، عن جابر بن عبد الله قال فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع المعاومة والسنين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1536/85). In another chain (1536/86), the wording is: “The Messenger of Allah ﷺ forbade renting land, selling it for years, and selling dates until they become ripe.”","chapter_en":"The prohibition of multi-year fruit sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":27,"content":{"translation":{"en":["Jabir ibn Abd Allah said: The Messenger of Allah ﷺ forbade selling standing crops for a measured amount of grain, fresh produce for dried produce by estimate, multi-year fruit sales, sharecropping, and undefined exceptions, and he allowed the araya. One of the narrators said: selling for years is the same as multi-year sale."]},"buhuth":{"en":["“Selling for years” means selling the fruit of a date palm for two or three years ahead. It is invalid by consensus because it is selling something that does not yet exist at the time of contract, and it contains uncertainty, ignorance, and inability to deliver if blight strikes."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":85,"lafz":true},{"key":"muslim","label":"مسلم في البيوع","number":1536,"n":3913}],"full":1,"dr":1,"rep":[5882]},{"num":5771,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْمُلاَمَسَةِ وَالْمُنَابَذَةِ."],"takhrij":"متفق عليه: رواه مالك في البيوع (76) عن محمد بن يحيى بن حَبان، عن أبي الزناد، عن الأعرج، عن أبي هريرة. ورواه البخاري في البيوع (2146)، ومسلم في البيوع (1511) كلاهما من طريق مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الملامسة والمنابذة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (76), al-Bukhari (2146), and Muslim (1511).","chapter_en":"The prohibition of touch-sale and throw-sale","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":28,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ forbade touch-sale and throw-sale."]},"buhuth":{"en":["Al-Bukhari (368) and Muslim also narrated through another chain with the wording: “The Prophet ﷺ forbade two sales: touching and throwing, and he also forbade wrapping oneself tightly in one garment and sitting with one garment wrapped around the body.” Another wording says: “He forbade the two sales of touch-sale and throw-sale.”","Explanation: Touch-sale means that each of the two parties merely touches the other’s garment without careful inspection. Throw-sale means that each one throws his garment to the other, and neither one examines the other’s item."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":76},{"key":"bukhari","label":"البخاري","number":2146,"lafz":true},{"key":"muslim","label":"مسلم","number":1511}],"full":1,"dr":1},{"num":5772,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: نَهَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعَتَيْنِ وَلِبْسَتَيْنِ: نَهَى عَنِ الْمُلاَمَسَةِ وَالْمُنَابَذَةِ فِي الْبَيْعِ. وَالْمُلاَمَسَةُ: لَمْسُ الرَّجُلِ ثَوْبَ الآخَرِ بِيَدِهِ بِاللَّيْلِ أَوْ بِالنَّهَارِ، وَلاَ يَقْلِبُهُ إِلاَّ بِذَلِكَ. وَالْمُنَابَذَةُ: أَنْ يَنْبِذَ الرَّجُلُ إِلَى الرَّجُلِ بِثَوْبِهِ، وَيَنْبِذَ الآخَرُ إِلَيْهِ ثَوْبَهُ، وَيَكُونُ ذَلِكَ بَيْعَهُمَا مِنْ غَيْرِ نَظَرٍ وَلاَ تَرَاضٍ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5820)، ومسلم في البيوع (1512) كلاهما من طريق يونس، عن ابن شهاب (الزهري)، أخبرني عامر بن سعد بن أبي وقاص، أن أبا سعيد الخدري قال فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الملامسة والمنابذة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5820) and Muslim (1512). The wording is Muslim’s.","chapter_en":"The prohibition of touch-sale and throw-sale","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":28,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: The Messenger of Allah ﷺ forbade us from two sales and two styles of dress. He forbade touch-sale and throw-sale in transactions. Touch-sale is when a man touches the garment of another with his hand at night or day and does not inspect it except by that. Throw-sale is when one man throws his garment to another, and the other throws his garment to him, and that becomes their sale without inspection and without mutual satisfaction."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5820,"lafz":true},{"key":"muslim","label":"مسلم","number":1512}],"full":1,"dr":1},{"num":5773,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُحَاقَلَةِ، وَالْمُخَاضَرَةِ، وَالْمُلاَمَسَةِ، وَالْمُنَابَذَةِ، وَالْمُزَابَنَةِ."],"takhrij":"صحيح: رواه البخاري في البيوع (2207) عن إسحاق بن وهب، حدثنا عمر بن يونس قال: حدثنا أبي قال: حدثني إسحاق بن أبي طلحة الأنصاري، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع الملامسة والمنابذة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2207).","chapter_en":"The prohibition of touch-sale and throw-sale","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":28,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ forbade selling standing crops for a measured amount of grain, selling green produce before ripeness, touch-sale, throw-sale, and fresh produce for dried produce by estimate."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2207,"lafz":true}],"full":1,"dr":1},{"num":5774,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ يَقُولُ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعِ الصُّبْرَةِ مِنَ التَّمْرِ لاَ يُعْلَمُ مَكِيلَتُهَا بِالْكَيْلِ الْمُسَمَّى مِنَ التَّمْرِ."],"takhrij":"صحيح: رواه مسلم في البيوع (1530) عن أبي الطاهر أحمد بن عمرو بن سرح، أخبرنا ابن وهب، حدثني ابن جريج، أن أبا الزبير أخبره أنه سمع جابر بن عبد الله يقول فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع صبرة التمر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1530).","chapter_en":"The prohibition of selling a heap of dates","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":29,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported: “The Messenger of Allah ﷺ prohibited selling a heap of dates whose measure is unknown in exchange for a specified measured quantity of dates.”"]},"buhuth":{"en":["Al-Nasāʾī (4548) narrated through another route:","“A heap of food is not to be sold for another heap of food, nor is a heap of food to be sold for a specified measured quantity of food.”","A ṣubrah is a pile or heap. To purchase something ṣubrah means to buy it without weighing or measuring it."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1530,"lafz":true}],"full":1,"dr":1},{"num":5775,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ عَامَ الْفَتْحِ، وَهُوَ بِمَكَّةَ إِنَّ اللَّهَ وَرَسُولَهُ حَرَّمَ بَيْعَ الْخَمْرِ وَالْمَيْتَةِ وَالْخِنْزِيرِ وَالأَصْنَامِ. فَقِيلَ يَا رَسُولَ اللَّهِ، أَرَأَيْتَ شُحُومَ الْمَيْتَةِ فَإِنَّهَا يُطْلَى بِهَا السُّفُنُ، وَيُدْهَنُ بِهَا الْجُلُودُ، وَيَسْتَصْبِحُ بِهَا النَّاسُ. فَقَالَ لاَ، هُوَ حَرَامٌ. ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ ذَلِكَ قَاتَلَ اللَّهُ الْيَهُودَ، إِنَّ اللَّهَ لَمَّا حَرَّمَ شُحُومَهَا جَمَلُوهُ ثُمَّ بَاعُوهُ فَأَكَلُوا ثَمَنَهُ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2236)، ومسلم في المساقاة (1581) كلاهما عن قتيبة بن سعيد، حدثنا الليث، عن يزيد بن أبي حبيب، عن عطاء بن أبي رباح، عن جابر بن عبد الله فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2236) and Muslim (1581).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Jabir ibn Abd Allah reported that he heard the Messenger of Allah ﷺ say in Makkah during the Year of the Conquest: “Allah and His Messenger have forbidden the sale of wine, carrion, pork, and idols.” It was said: O Messenger of Allah ﷺ, what about the fat of carrion, for ships are coated with it, skins are greased with it, and people use it for lamps? He said: “No, it is forbidden.” Then the Messenger of Allah ﷺ said: “May Allah destroy the Jews. When Allah forbade their fats, they melted them, then sold them, and consumed their price.”"]},"intro":{"ar":["قال اللّه تعالى: ( حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنزِيرِ وَمَا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ وَالْمُنْخَنِقَةُ وَالْمَوْقُوذَةُ وَالْمُتَرَدِّيَةُ وَالنَّطِيحَةُ وَمَا أَكَلَ السَّبُعُ إِلَّا مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى النُّصُبِ وَأَن تَسْتَقْسِمُوا بِالْأَزْلَامِ ذَلِكُمْ فِسْقٌ ۗ الْيَوْمَ يَئِسَ الَّذِينَ كَفَرُوا مِن دِينِكُمْ فَلَا تَخْشَوْهُمْ وَاخْشَوْنِ ۚ الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الْإِسْلَامَ دِينًا ۚ فَمَنِ اضْطُرَّ فِي مَخْمَصَةٍ غَيْرَ مُتَجَانِفٍ لِإِثْمٍ فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ )","[سورة المائدة: ٣]"],"en":["Allah the Exalted said: “Forbidden to you are carrion, blood, the flesh of swine, that which has been dedicated to other than Allah, the strangled animal, the beaten animal, the fallen animal, the gored animal, and that which has been eaten by a beast — except what you are able to slaughter properly — and that which is sacrificed on stone altars, and that you seek decision by divining arrows. That is grave disobedience. Today those who disbelieve have despaired of your religion, so do not fear them, but fear Me. Today I have perfected for you your religion, completed My favor upon you, and chosen submission to Allah as your religion. But whoever is forced by severe hunger, without inclining to sin, then indeed Allah is Forgiving and Merciful.”","[Surat al-Ma’idah: 3]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2236,"lafz":true},{"key":"muslim","label":"مسلم","number":1581}],"full":1,"rep":[9177,12319]},{"num":5776,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا يَقُولُ بَلَغَ عُمَرَ أَنَّ فُلاَنًا بَاعَ خَمْرًا فَقَالَ قَاتَلَ اللَّهُ فُلاَنًا، أَلَمْ يَعْلَمْ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ قَاتَلَ اللَّهُ الْيَهُودَ، حُرِّمَتْ عَلَيْهِمُ الشُّحُومُ فَجَمَلُوهَا فَبَاعُوهَا."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2223)، ومسلم في المساقاة (1582) من طريق سفيان بن عيينة، حدثنا عمرو بن دينار، أخبرني طاوس، أنه سمع ابن عباس يقول فذكره. واللفظ للبخاري، وجاء فلان مصرحا باسمه عند مسلم أنه سمرة بن جندب رضي الله عنه.","grade":"متفق عليه","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2223) and Muslim (1582). This wording is from al-Bukhari.","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Ibn Abbas said: Umar was informed that a certain man had sold wine, so he said: May Allah destroy that man. Does he not know that the Messenger of Allah ﷺ said: “May Allah destroy the Jews. Fat was forbidden to them, so they melted it and sold it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2223,"lafz":true},{"key":"muslim","label":"مسلم","number":1582}],"full":1,"dr":1,"rep":[12321]},{"num":5777,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسًا عِنْدَ الرُّكْنِ - قَالَ - فَرَفَعَ بَصَرَهُ إِلَى السَّمَاءِ فَضَحِكَ فَقَالَ لَعَنَ اللَّهُ الْيَهُودَ. ثَلاَثًا إِنَّ اللَّهَ حَرَّمَ عَلَيْهِمُ الشُّحُومَ فَبَاعُوهَا وَأَكَلُوا أَثْمَانَهَا وَإِنَّ اللَّهَ إِذَا حَرَّمَ عَلَى قَوْمٍ أَكْلَ شَىْءٍ حَرَّمَ عَلَيْهِمْ ثَمَنَهُ."],"takhrij":"صحيح: رواه أبو داود (3488)، وأحمد (2221)، وابن حبان (4938)، والبيهقي (6/13) كلهم من طريق خالد الحذاء، عن بركة أبي الوليد، أخبرنا ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3488), Ahmad (2221), Ibn Hibban (4938), and al-Bayhaqi (6/13).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Ibn Abbas said: I saw the Messenger of Allah ﷺ sitting by the corner of the Ka‘bah. He raised his sight to the sky and smiled, then said: “May Allah curse the Jews three times. Allah forbade fat to them, but they sold it and consumed its price. When Allah forbids a people from eating something, He forbids them from taking its price as well.”"]},"buhuth":{"en":["Explanation: His statement, “When Allah forbids a people from eating something, He forbids them from taking its price as well,” is not taken in a fully unrestricted sense. The scholars agreed that some things may not be eaten but may still be sold, such as human beings, donkeys, and similar matters. People also traded manure for farming use throughout the ages. See al-Minnah al-Kubra (5/228) for more detail."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3488,"lafz":true},{"key":"ibnhibban","label":"ابن حبان","number":4938},{"key":"kubrabayhaqi","label":"البيهقي","number":13},{"key":"ahmad","label":"مسند الإمام أحمد","number":2221,"n":2221},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":11051,"n":11145}],"full":1,"dr":1},{"num":5778,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ أَهْدَى رَجُلٌ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَاوِيَةَ خَمْرٍ فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَا عَلِمْتَ أَنَّ اللَّهَ حَرَّمَهَا. قَالَ لاَ. فَسَارَّهُ رَجُلٌ إِلَى جَنْبِهِ. فَقَالَ لَهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَ سَارَرْتَهُ. فَقَالَ أَمَرْتُهُ أَنْ يَبِيعَهَا. فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ الَّذِي حَرَّمَ شُرْبَهَا حَرَّمَ بَيْعَهَا. فَفَتَحَ الرَّجُلُ الْمَزَادَتَيْنِ حَتَّى ذَهَبَ مَا فِيهِمَا."],"takhrij":"صحيح: رواه مالك في الأشربة (12) عن زيد بن اسلم، عن ابن وَعْلة المصـري، أنه سأل عبد الله بن عباس عما يُعصر من العنب، فقـال ابن عباس فذكره. ورواه مسلم في المساقاة (1579) من طريق مالك وغيره، عن زيد بن أسلم به.","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (12) and Muslim (1579).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Ibn Abbas said: A man gave the Messenger of Allah ﷺ a wineskin of wine. The Messenger of Allah ﷺ said to him: “Did you not know that Allah has forbidden it?” He said: No. A man next to him whispered to him, and the Prophet ﷺ said: “What did you whisper to him?” He said: I told him to sell it. The Messenger of Allah ﷺ said: “The One who forbade drinking it also forbade selling it.” So the man opened the two skins until all that was in them was poured out."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":12,"lafz":true},{"key":"muslim","label":"مسلم","number":1579}],"full":1,"dr":1},{"num":5779,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَتَانِي جِبْرِيلُ، فَقَالَ: يَا مُحَمَّدُ، إِنَّ اللَّهَ عَزَّ وَجَلَّ لَعَنَ الْخَمْرَ، وَعَاصِرَهَا، وَمُعْتَصِرَهَا، وَشَارِبَهَا، وَحَامِلَهَا، وَالْمَحْمُولَةَ إِلَيْهِ، وَبَائِعَهَا، وَمُبْتَاعَهَا، وَسَاقِيَهَا، وَمُسْتَقِيَهَا."],"takhrij":"حسن: رواه أحمد (2897)، والطبراني في الكبير 12976)، وابن حبان (5356)، والحاكم (2/31) كلهم من طرق عن مالك بن خير الزيادي، أن مالك بن سعد التجيبي حدثه، أنه سمع ابن عباس يقول فذكره.","grade":"حسن","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (2897), al-Tabarani in al-Kabir (12976), Ibn Hibban (5356), and al-Hakim (2/31).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Ibn Abbas said: I heard the Messenger of Allah ﷺ say: “Gabriel came to me and said: O Muhammad, Allah has cursed wine, the one who presses it, the one for whom it is pressed, the one who drinks it, the one who carries it, the one to whom it is carried, the one who sells it, the one who buys it, the one who serves it, and the one who asks for it to be served.”"]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":12976},{"key":"ibnhibban","label":"ابن حبان","number":5356},{"key":"ahmad","label":"مسند الإمام أحمد","number":2897,"n":2897,"lafz":true},{"key":"hakim","label":"المستدرك على الصحيحين","number":2234,"n":2226}],"full":1,"dr":1},{"num":5780,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ اللَّهَ حَرَّمَ عَلَيْكُمِ الْخَمْرَ، وَالْمَيْسِرَ، وَالْكُوبَةَ، وَقَالَ: كُلُّ مُسْكِرٍ حَرَامٌ."],"takhrij":"صحيح: رواه الإمام أحمد (2625)، والطحاوي في شرحه (4/216)، والبيهقي (10/221) كلهم من حديث عبد الله بن عمرو، عن عبد الكريم، عن قيس بن حَبْتر، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (2625), al-Tahawi in his commentary (4/216), and al-Bayhaqi (10/221).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Ibn Abbas reported that the Messenger of Allah ﷺ said: “Allah has forbidden for you wine, gambling, and the drum.” And he said: “Every intoxicant is forbidden.”"]},"buhuth":{"en":["Explanation: The word used here has been explained as backgammon, and it has also been explained as a drum, and others said it means a stringed musical instrument. This is mentioned in al-Nihayah."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":2625,"lafz":true},{"key":"sh21108","label":"الطحاوي في شرحه","number":4},{"key":"kubrabayhaqi","label":"البيهقي","number":10},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":20943,"n":21101}],"full":1,"dr":1},{"num":5781,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ قَاتَلَ اللَّهُ يَهُودًا حُرِّمَتْ عَلَيْهِمُ الشُّحُومُ فَبَاعُوهَا، وَأَكَلُوا أَثْمَانَهَا."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2224)، ومسلم في المساقاة (1583) من طريق يونس (هو: ابن يزيد الأيلي)، عن ابن شهاب، سمعت سعيد بن المسيب، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2224) and Muslim (1583).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “May Allah destroy the Jews. Fat was forbidden to them, yet they sold it and consumed its price.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2224,"lafz":true},{"key":"muslim","label":"مسلم","number":1583}],"full":1,"dr":1},{"num":5782,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِنَّ اللَّهَ حَرَّمَ الْخَمْرَ وَثَمَنَهَا وَحَرَّمَ الْمَيْتَةَ وَثَمَنَهَا وَحَرَّمَ الْخِنْزِيرَ وَثَمَنَهُ."],"takhrij":"حسن: رواه أبو داود (3485) عن أحمد بن صالح، حدثنا عبد الله بن وهب، حدثنا معاوية بن صالح، عن عبدالوهاب بن بخت، عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره. ورواه البيهقي (6/12) من طريق أبي داود.","grade":"حسن","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3485).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Allah has forbidden wine and its price, carrion and its price, and pork and its price.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3485,"lafz":true}],"full":1,"dr":1},{"num":5783,"demo":false,"sanad":"","matn":["عَنْ عَوْنِ بْنِ أَبِي جُحَيْفَةَ قَالَ: رَأَيْتُ أَبِي اشْتَرَى حَجَّامًا، فَأَمَرَ بمحاجمه، فكسرت، فَسَأَلْتُهُ عَنْ ذَلِكَ، فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ ثَمَنِ الدَّمِ، وَثَمَنِ الْكَلْبِ، وَكَسْبِ الأَمَةِ. وَلَعَنَ الْوَاشِمَةَ وَالْمُسْتَوْشِمَةَ، وَآكِلَ الرِّبَا ومؤكله، وَلَعَنَ الْمُصَوِّرَ."],"takhrij":"صحيح: رواه البخاري في البيوع (2238) عن حجاج بن منهال، حدثنا شعبة قال: أخبرني عون أبي جحيفة فذكره.","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2238).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Awn ibn Abi Juhayfah said: I saw my father buy a cupper, then he ordered that his instruments be broken. I asked him about that, and he said: The Messenger of Allah ﷺ forbade the price of blood, the price of a dog, and the earnings of a slave woman. He also cursed the woman who tattoos and the one who seeks tattooing, the one who consumes usury and the one who pays it, and he cursed the image-maker."]},"buhuth":{"ar":["قوله:  نهى عن ثمن الدم  قيل: معناه أجرة الحجامة، والصحيح هو بيع الدم نفسه؛ لأن أهل الجاهلية كانوا يجمدون الدم ويأكلونه، كما هو موجود إلى الآن في بعض المجتمعات الوثنية، وأما أجرة الحجامة فليست حراما، وأكثر ما قيل فيها إنها مكروهة."],"en":["Explanation: His saying, “He forbade the price of blood,” has been explained by some as the fee of cupping, but the sounder meaning is the sale of blood itself, because the people of the pre-Islamic period used to congeal blood and eat it. As for the wage of cupping, it is not forbidden; at most some scholars considered it disliked."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2238,"lafz":true}],"full":1},{"num":5784,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ لَمَّا أُنْزِلَتِ الآيَاتُ مِنْ آخِرِ سُورَةِ الْبَقَرَةِ فِي الرِّبَا - قَالَتْ - خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْمَسْجِدِ فَحَرَّمَ التِّجَارَةَ فِي الْخَمْرِ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2226)، ومسلم في المساقاة (1580) من طريق الأعمش، عن أبي الضحى مسلم (هو ابن صَبيح)، عن مسروق، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2226) and Muslim (1580). This wording is from Muslim.","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Aishah said: When the verses at the end of Surat al-Baqarah concerning usury were revealed, the Messenger of Allah ﷺ went out to the mosque and forbade trade in wine."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2226,"lafz":true},{"key":"muslim","label":"مسلم","number":1580,"n":4047}],"full":1,"dr":1},{"num":5785,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ بِالْمَدِينَةِ قَالَ يَا أَيُّهَا النَّاسُ إِنَّ اللَّهَ تَعَالَى يُعَرِّضُ بِالْخَمْرِ وَلَعَلَّ اللَّهَ سَيُنْزِلُ فِيهَا أَمْرًا فَمَنْ كَانَ عِنْدَهُ مِنْهَا شَىْءٌ فَلْيَبِعْهُ وَلْيَنْتَفِعْ بِهِ. قَالَ فَمَا لَبِثْنَا إِلاَّ يَسِيرًا حَتَّى قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ اللَّهَ تَعَالَى حَرَّمَ الْخَمْرَ فَمَنْ أَدْرَكَتْهُ هَذِهِ الآيَةُ وَعِنْدَهُ مِنْهَا شَىْءٌ فَلاَ يَشْرَبْ وَلاَ يَبِعْ. قَالَ فَاسْتَقْبَلَ النَّاسُ بِمَا كَانَ عِنْدَهُ مِنْهَا فِي طَرِيقِ الْمَدِينَةِ فَسَفَكُوهَا."],"takhrij":"صحيح: رواه مسلم في المساقاة (1578) عن عبيدالله بن عمر القواريري، حدثنا عبدالأعلى بن عبدالأعلى أبو همام، حدثنا سعيد الجريري، عن أبي نضرة، عن أبي سعيد الخدري قال فذكره.","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1578).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: I heard the Messenger of Allah ﷺ giving a sermon in Madinah and saying: “O people, Allah is indicating that wine will be forbidden, and perhaps Allah will soon reveal a command about it. Whoever has any of it should sell it and benefit from it.” We only waited a short while before the Prophet ﷺ said: “Allah has now forbidden wine. Whoever is reached by this verse while he still has any of it should neither drink it nor sell it.” The people then took what they had of it to the streets of Madinah and poured it out."]},"buhuth":{"en":["Explanation: His statement, “Allah is indicating concerning wine,” means He was hinting at its prohibition before the final explicit ruling. The verse referred to is: “They ask you about wine and gambling. Say: in them is great sin and some benefit for people, but their sin is greater than their benefit.”","[Surat al-Baqarah: 219]","And his saying, “Whoever is reached by this verse,” refers to the verse: “O you who believe, indeed wine, gambling, sacrificial stones, and divining arrows are filth from the work of Satan, so avoid them that you may succeed.”","[Surat al-Ma’idah: 90]"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1578,"lafz":true}],"full":1,"dr":1,"rep":[7442]},{"num":5786,"demo":false,"sanad":"","matn":["عَنْ عبدالرحمن بن غَنْمٍ أَنَّ الدَّارِيَّ كَانَ يُهْدِي لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُلَّ عَامٍ رَاوِيَةً خَمْرٍ، فَلَمَّا كَانَ عَامَ حُرِّمَتْ جَاءَ بِرَاوِيَةٍ، فَلَمَّا نَظَرَ إليـــه نبي اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ضَحِكَ، قَالَ: هَلْ شَعَرْتَ أَنَّهَا قَدْ حُرِّمَتْ بَعْدَكَ؟. قَالَ: يَا رَسُولَ اللَّهِ، أَفَلَا أَبِيعُهَا فانتفع بِثَمَنِهَا؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : لَعَنَ اللَّهُ الْيَهُودَ، انْطَلَقُوا إِلَى مَا حُرِّمَ عَلَيْهِمْ مِنْ شُحُومِ الْبَقَرِ وَالْغَنَمِ، فَأَذَابُوهُ، فَجَعَلُوهُ ثَمَنًا لَهُ، فَبَاعُوا بِهِ مَا يَأْكُلُونَ، وَإِنَّ الْخَمْرَ حَرَامٌ، وَثَمَنَهَا حَرَامٌ، وَإِنَّ الْخَمْرَ حَرَامٌ، وَثَمَنَهَا حَرَامٌ، وَإِنَّ الْخَمْرَ حَرَامٌ، وَثَمَنَهَا حَرَامٌ."],"takhrij":"حسن: رواه أحمد (17995) عن روح، حدثنا عبدالحميد بن بهرام قال: سمعت شهر بن حوشب قال: حدثني عبد الرحمن بن غَنْم فذكره.","grade":"حسن","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (17995).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Abd al-Rahman ibn Ghanm reported that al-Dari used to gift the Messenger of Allah ﷺ a skin of wine every year. When the year came in which it was forbidden, he brought one again. When the Prophet ﷺ saw it, he smiled and said: “Did you realize that it has been forbidden after your last visit?” He said: O Messenger of Allah ﷺ, may I not sell it and benefit from its price? The Messenger of Allah ﷺ said: “May Allah curse the Jews. They went to the fats of cattle and sheep that had been forbidden to them, melted them down, turned them into a saleable commodity, and used the money to buy what they ate. Wine is forbidden, and its price is forbidden.” He repeated that three times."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":17995,"n":17995,"lafz":true}],"full":1,"dr":1},{"num":5787,"demo":false,"sanad":"","matn":["عن عَامِرِ بن رَبِيعَةَ عَنْ أَبِيهِ، أَنَّ رَجُلًا، مِنْ ثَقِيفٍ يُكْنَى أَبَا تَمَامٍ أَهْدَى إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَاوِيَةَ خَمْرٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّهَا قَدْ حُرِّمَتْ يَا أَبَا تَمَامٍ، فَقَالَ لَهُ: يَا رَسُولَ اللَّهِ، فأَسْتَنْفِقُ ثَمَنَهَا؟ فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الَّذِي حَرَّمَ شُرْبَهَا حَرَّمَ ثَمَنَهَا."],"takhrij":"صحيح: رواه الطبراني في الأوسط (439) عن أحمد بن خليد، قال: حدثنا عبد الله بن جعفر الرقي، قال: حدثنا عبيد الله بن عمرو، عن زيد بن أبي أنيسة، عن أبي بكر بن حفص، عن عبد الله بن عامر بن ربيعة، عن أبيه، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tabarani in al-Awsat (439).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Amir ibn Rabi‘ah reported that a man from Thaqif, known as Abu Tammam, gave the Messenger of Allah ﷺ a skin of wine. The Messenger of Allah ﷺ said: “It has indeed been forbidden, O Abu Tammam.” He said: O Messenger of Allah ﷺ, may I at least spend its price? The Prophet ﷺ said: “The One who forbade drinking it also forbade its price.”"]}},"tuhfa":{},"refs":[{"key":"sh28171","label":"الطبراني في الأوسط","number":439,"lafz":true,"n":434},{"key":"sh28171","label":"المعجم الأوسط للطبراني","number":436,"n":434}],"full":1,"dr":1},{"num":5788,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ الْفَتْحِ، وَهُوَ بِمَكَّةَ يَقُولُ: إِنَّ اللَّهَ وَرَسُولَهُ حَرَّمَ بَيْعَ الْخَمْرِ وَالْمَيْتَةَ وَالْخِنْزِيرَ، فَقِيلَ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ شُحُومَ الْمَيْتَةِ؟ فَإِنَّهُ يُدْهَنُ بِهَا السُّفُنُ، وَيُدْهَنُ بِهَا الْجُلُودُ، وَيَسْتَصْبِحُ بِهَا النَّاسُ؟ فَقَالَ: لَا، هِيَ حَرَامٌ، ثُمَّ قَالَ: قَاتَلَ اللَّهُ الْيَهُودَ، إِنَّ اللَّهَ لَمَّا حَرَّمَ عَلَيْهِمُ الشُّحُومَ، جَمَلُوهَا، ثُمَّ بَاعُوهَا، وَأَكَلُوا أَثْمَانَهَا."],"takhrij":"حسن: رواه أحمد (6997)، والبيهقي (9/355) كلاهما من حديث أسامة بن زيد، عن عمرو بن شعيب بإسناده مثله.","grade":"حسن","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6997) and al-Bayhaqi (9/355).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Amr ibn Shu‘ayb, from his father, from his grandfather, said: I heard the Prophet ﷺ say in Makkah during the Year of the Conquest: “Allah and His Messenger have forbidden the sale of wine, carrion, and pork.” It was said: O Messenger of Allah ﷺ, what about the fat of carrion, for ships are coated with it, skins are greased with it, and people use it for lamps? He said: “No, it is forbidden.” Then he said: “May Allah destroy the Jews. When Allah forbade fat to them, they melted it, sold it, and consumed its price.”"]}},"tuhfa":{},"refs":[{"key":"kubrabayhaqi","label":"البيهقي","number":9},{"key":"ahmad","label":"مسند الإمام أحمد","number":6997,"n":6997,"lafz":true}],"full":1,"dr":1},{"num":5789,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الْوَاحِدِ الْبُنَانِيِّ قَالَ: كُنْتُ مَعَ ابْنِ عُمَرَ فَجَاءَهُ رَجُلٌ فَقَالَ: يَا أَبَا عَبْدِ الرَّحْمَنِ إِنِّي أَشْتَرِي هَذِهِ الْحِيطَانَ تَكُونُ فِيهَا الْأَعْنَابُ، وَلَا نَسْتَطِيعُ أَنْ نَبِيعَهَا كُلَّهَا عِنَبًا حَتَّى نَعْصِرَهُ، قَالَ: فَعَنْ ثَمَنِ الْخَمْرِ تَسْأَلُنِي؟ سَأُحَدِّثُكَ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، كُنَّا جُلُوسًا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ رَفَعَ رَأْسَهُ إِلَى السَّمَاءِ ثُمَّ أَكَبَّ، وَنَكَتَ فِي الْأَرْضِ وَقَالَ: الْوَيْلُ لِبَنِي إِسْرَائِيلَ فَقَالَ لَهُ عُمَرُ: يَا نَبِيَّ اللَّهِ، لَقَدْ أَفْزَعَنَا قَوْلُكَ لِبَنِي إِسْرَائِيلَ فَقَالَ: لَيْسَ عَلَيْكُمْ مِنْ ذَلِكَ بَأْسٌ، إِنَّهُمْ لَمَّا حُرِّمَتْ عَلَيْهِمُ الشُّحُومُ، فَتَوَاطَئُوهُ، فَيَبِيعُونَهُ، فَيَأْكُلُونَ ثَمَنَهُ، وَكَذَلِكَ ثَمَنُ الْخَمْرِ عَلَيْكُمْ حَرَامٌ."],"takhrij":"حسن: رواه أحمد (5982) عن عبد الصمد، حدثني أبي، ثنا عبد العزيز بن صهيب، عن عبدالواحد البناني قال فذكره.","grade":"حسن","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (5982).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Abd al-Wahid al-Banani said: I was with Ibn Umar when a man came to him and said: O Abu Abd al-Rahman, I buy vineyards with grapes on them, and we cannot sell all of them as grapes until we press them. He said: Are you asking me about the price of wine? I will tell you a hadith I heard from the Messenger of Allah ﷺ. We were sitting with the Prophet ﷺ when he raised his head to the sky, then lowered it and scratched the ground and said: “Woe to the Children of Israel.” Umar said: O Prophet ﷺ of Allah, your statement about the Children of Israel has alarmed us. He said: “That is not your issue. When fat was forbidden to them, they manipulated it, sold it, and consumed its price. Likewise, the price of wine is forbidden for you.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":5982,"n":5982,"lafz":true}],"full":1,"dr":1},{"num":5790,"demo":false,"sanad":"","matn":["عن ابْنِ عُمَرَ يَقُولُ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لُعِنَتِ الْخَمْرُ عَلَى عَشَرَةِ أَوْجُهٍ بِعَيْنِهَا وَعَاصِرِهَا وَمُعْتَصِرِهَا وَبَائِعِهَا وَمُبْتَاعِهَا وَحَامِلِهَا وَالْمَحْمُولَةِ إِلَيْهِ وَآكِلِ ثَمَنِهَا وَشَارِبِهَا وَسَاقِيهَا."],"takhrij":"حسن: رواه أبو داود (3674)، وابن ماجه (3380)، وأحمد (4787)، وابن أبي شيبة (6/447)، والبيهقي (5/327) كلهم من طريق عبد العزيز بن عمر بن عبد العزيز، عن عبد الرحمن بن عبد الله الغافقي وأبي طعمة مولاهم أنهما سمعا ابن عمر يقول فذكره.","grade":"حسن","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3674), Ibn Majah (3380), Ahmad (4787), and Ibn Abi Shaybah (6/447).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Abd Allah ibn Umar reported that the Messenger of Allah ﷺ said: “Wine has been cursed in ten ways: in itself, the one who presses it, the one for whom it is pressed, the one who sells it, the one who buys it, the one who carries it, the one to whom it is carried, the one who consumes its price, the one who drinks it, and the one who serves it.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3674,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":3380},{"key":"sh9944","label":"ابن أبي شيبة","number":6},{"key":"ahmad","label":"مسند الإمام أحمد","number":4787,"n":4787},{"key":"sh9944","label":"المصنف لابن أبي شيبة","number":21625,"n":21608}],"full":1,"dr":1,"rep":[7584]},{"num":5791,"demo":false,"sanad":"","matn":["عن عَبْدِ الرَّحْمَنِ بن شريح الخولاني أَنَّهُ كَانَ لَهُ عَمٌّ يَبِيعُ الْخَمْرَ وَكَانَ يَتَصَدَّقُ بِثَمَنِهِ فَنَهَيْتُهُ عَنْهَا فَلَمْ يَنْتَهِ فَقَدِمْتُ الْمَدِينَةَ فَلَقِيتُ ابْنَ عَبَّاسٍ، فَسَأَلْتُهُ عَنِ الْخَمْرِ وَثَمَنِهَا فَقَالَ: هِيَ حَرَامٌ وَثَمَنُهَا حَرَامٌ، ثُمَّ قَالَ: يَا مَعْشَرَ أُمَّةِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّهُ لَوْ كَانَ كِتَابٌ بَعْدَ كِتَابِكُمْ أَوْ نَبِيٌّ بَعْدَ نَبِيِّكُمْ لَأُنْزِلَ فِيكُمْ كَمَا أُنْزِلَ فِيمَنْ كَانَ قَبْلَكُمْ، وَلَكِنْ أُخِّرَ ذَلِكَ مِنْ أَمْرِكُمْ إِلَى يَوْمِ الْقِيَامَةِ وَلَعَمْرِي لَهُوَ أَشَدُّ عَلَيْكُمْ.","قال: ثم لقيت عبد الله بن عمر، فسألته عن ثمن الخمر، فقال: سأخبرك عن الخمر: أني كنت عند رسول الله صلى الله عليه وسلم  في المسجد، فبينما هو محتبي حل حبوته، ثم قال: من كان عنده من الخمر شيء فليؤذني به. فجعل الناس يأتونه، فيقول أحدهم: عندي راوية خمر، ويقول الآخر: عندي راوية، و يقول الآخر: عندي زق، أو ما شاء الله أن يكون عنده، فقال رسول الله صلى الله عليه وسلم : اجمعوه ببقيع كذا و كذا ثم آذنوني، ففعلوا، ثم آذنوه. قال: فقمت، فمشيت -و هو متكئ علي-، فلحقنا أبو بكر رضي الله عنه، فأخذني رسول الله صلى الله عليه وسلم ، فجعلني عن يساره، وجعل أبا بكر مكاني، ثم لحقنا عمر، فأخذني، وجعلني عن يساره، فمشى بينهما حتى إذا وقف على الخمر قال للناس: أتعرفون هذه؟ قالوا: نعم يا رسول الله، هذه الخمر. قال: صدقتم. ثم قال: إن الله تعالى لعن الخمر، وعاصرها، ومعتصرها، وشاربها، وساقيها، وحاملها، والمحمولة إليه، وبائعها، ومشتريها، وآكل ثمنها. ثم دعا بسكين، فقال: اشحذوها. ففعلوا، ثم أخذها رسول الله صلى الله عليه وسلم  يخرق بها الزقاق. فقال الناس: إن في هذه الزقاق لمنفعة، فقال: أجل، و لكن إنما أفعل غضبا لله لما فيها من سخطه. فقال عمر: أنا أكفيك يا رسول الله. قال: لا. و بعضهم يزيد على بعض في الحديث."],"takhrij":"صحيح: رواه الحاكم (4/144-145) عن أبي العباس محمد بن يعقوب، أنبأ محمد بن عبد الله بن عبدالحكم، أنبأ ابن وهب، أخبرني عبد الرحمن بن شريح الخولاني قال:فذكره.","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Hakim (7228).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Abd al-Rahman ibn Shurayh al-Khawlani said: I had an uncle who sold wine, and he used to give its price in charity. I forbade him from that, but he did not stop. Then I came to Madinah and met Ibn Abbas and asked him about wine and its price. He said: It is forbidden, and its price is forbidden. Then he said: O nation of Muhammad, if there had been another scripture after your scripture, or another prophet after your prophet, something like what was sent down upon those before you would have been sent down upon you. But there is no scripture after your scripture and no prophet after your prophet. Then I met Abd Allah ibn Umar and asked him about the price of wine. He said: I will tell you about wine. I was with the Messenger of Allah ﷺ in the mosque. While he was sitting with his knees drawn up, he untied his posture and said: “Whoever has any wine should inform me of it.” People began coming to him. One said: I have a skin of wine. Another said: I have a container. Another said: I have a wineskin, or whatever Allah willed one of them to have. The Messenger of Allah ﷺ said: “Gather it in such-and-such place in the cemetery area, then inform me.” They did that and then informed him. I stood and walked while he was leaning on me. Abu Bakr joined us, so the Messenger of Allah ﷺ moved me to his left and put Abu Bakr in my place. Then Umar joined us, so he moved me to his left, and he walked between them until he stopped at the wine and said to the people: “Do you know what this is?” They said: Yes, O Messenger of Allah ﷺ, this is wine. He said: “You have spoken the truth.” Then he said: “Allah has cursed wine, the one who presses it, the one for whom it is pressed, the one who drinks it, the one who serves it, the one who carries it, the one to whom it is carried, the one who sells it, the one who buys it, and the one who consumes its price.” Then he asked for a knife and said: “Sharpen it.” They did so, and the Messenger of Allah ﷺ began cutting the wineskins open with it. The people said: There is some use in these skins. He said: “Yes, but I am only doing this out of anger for Allah because of what they contain of His displeasure.” Umar said: I will take care of it for you, O Messenger of Allah ﷺ. He said: “No.” Some narrators add more than others in this hadith."]}},"tuhfa":{},"refs":[{"key":"hakim","label":"المستدرك على الصحيحين","number":7228,"n":7231,"lafz":true}],"full":1,"dr":1},{"num":5792,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ لَعَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْخَمْرِ عَشَرَةً عَاصِرَهَا وَمُعْتَصِرَهَا وَشَارِبَهَا وَحَامِلَهَا وَالْمَحْمُولَةَ إِلَيْهِ وَسَاقِيَهَا وَبَائِعَهَا وَآكِلَ ثَمَنِهَا وَالْمُشْتَرِيَ لَهَا وَالْمُشْتَرَاةَ لَهُ."],"takhrij":"حسن: رواه الترمذي (1295)، وابن ماجه (3381) كلاهما من حديث أبي عاصم، عن شبيب بن بشر، عن أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1295) and Ibn Majah (3381). Al-Tirmidhi said: “This is a singularly transmitted hadith.”","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ cursed ten connected to wine: the one who presses it, the one for whom it is pressed, the one who drinks it, the one who carries it, the one to whom it is carried, the one who serves it, the one who sells it, the one who consumes its price, the one who buys it, and the one for whom it is bought."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1295,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":3381}],"full":1,"dr":1,"rep":[7585]},{"num":5793,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: لَمَّا حُرِّمَتِ الْخَمْرُ قَالَ: إِنِّي يَوْمَئِذٍ لَأَسْقِيهِمْ لَأَسْقِي أَحَدَ عَشَرَ رَجُلًا، فَأَمَرُونِي، فَكَفَأْتُهَا، وَكَفَأَ النَّاسُ آنِيَتَهُمْ بِمَا فِيهَا حَتَّى كَادَتِ السِّكَكُ أَنْ تُمْتَنَعَ مِنْ رِيحِهَا.","قال أنس: وما خمرهم يومئذ إلا البسر والتمر مخلوطين.","قال: فجاء رجل إلى النبي صلى الله عليه وسلم ، فقال: إنه كان عندي مال يتيم فاشتريت به خمرا، أفتأذن لي أن أبيعه، فأرد على اليتيم ماله، فقال النبي صلى الله عليه وسلم : قاتل الله اليهود، حرمت عليهم الثروب، فباعوها، وأكلوا أثمانها. ولم يأذن لهم النبي صلى الله عليه وسلم  في بيع الخمر."],"takhrij":"صحيح: رواه أحمد (13275) عن عبدالرزاق– وهو في مصنفه (16970)- قال: أخبرنا معمر، عن ثابت وقتادة، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (13275), Abd al-Razzaq in his Musannaf (16970), and Ibn Hibban (4945).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Anas said: When wine was forbidden, I was at that time serving it to them, serving eleven men. So I overturned it, and the people overturned their vessels with what was in them, until the streets almost became filled with its smell. Anas said: Their wine that day was only a mixture of unripe dates and dried dates. Then a man came to the Prophet ﷺ and said: I had the wealth of an orphan, and I bought wine with it. Will you allow me to sell it so that I may return the orphan’s money? The Prophet ﷺ said: “May Allah destroy the Jews. Fat was forbidden to them, but they sold it and made its price lawful for themselves.” And the Prophet ﷺ did not permit them to sell wine."]},"buhuth":{"en":["Explanation: The word “al-thurub” refers to thin fat."]}},"tuhfa":{},"refs":[{"key":"abdrazzaq","label":"عبد الرزاق في مصنفه","number":16970},{"key":"ibnhibban","label":"ابن حبان","number":4945},{"key":"ahmad","label":"مسند الإمام أحمد","number":13275,"n":13275,"lafz":true}],"full":1,"dr":1},{"num":5794,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ أَبَا طَلْحَةَ سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ أَيْتَامٍ وَرِثُوا خَمْرًا، فَقَالَ: أَهْرِقْهَا قَالَ: أَفَلَا نَجْعَلُهَا خَلًّا؟ قَالَ: لَا."],"takhrij":"حسن: رواه أبو داود (3675)، والترمذي (1293) معلقا، وأحمد (12189)، والطحاوي في مشكله (3337)، والبيهقي (6/37) كلهم من حديث سفيان الثوري، عن السدي، عن أبي هبيرة، عن أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3675), al-Tirmidhi (1293, suspended), Ahmad (12189), and al-Tahawi in Mushkil al-Athar (3337).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Anas ibn Malik reported that Abu Talhah asked the Prophet ﷺ about orphans who had inherited wine. He said, “Pour it out.” He asked, “May we not turn it into vinegar?” He said, “No.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3675,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1293},{"key":"sh22547","label":"الطحاوي في مشكل الآثار","number":3337},{"key":"ahmad","label":"مسند الإمام أحمد","number":12189,"n":12189}],"full":1,"dr":1},{"num":5795,"demo":false,"sanad":"","matn":["عَنْ أُسَامَةَ بْنِ زَيْدٍ رضي الله عنهما قَالَ: دَخَلْنَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  نَعُودُهُ وَهُوَ مَرِيضٌ فَوَجَدْنَاهُ نَائِمًا قَدْ غَطَّى وَجْهَهُ بِبُرْدٍ عَدَنِيٍّ فَكَشَفَ عَنْ وَجْهِهِ ثُمَّ قَالَ: لَعَنَ اللَّهُ الْيَهُودَ يُحَرِّمُونَ شُحُومَ الْغَنَمِ وَيَأْكُلُونَ أَثْمَانَهَا."],"takhrij":"صحيح: رواه الحارث بن أبي أسامة –بغية الباحث (433)-، وأبو نعيم في معرفة الصحابة (2/183-184)، والحاكم (4/194) كلهم من حديث الأعمش، عن جامع بن شداد، عن كلثوم الخزاعي، عن أسامة فذكره.","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Harith ibn Abi Usamah in Bughyat al-Bahith (433), and Abu Nu‘aym in Ma‘rifat al-Sahabah (2/183–184).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Usamah ibn Zayd said: We entered upon the Messenger of Allah ﷺ to visit him while he was ill. We found him sleeping, with his face covered by an Adeni cloak. He uncovered his face and then said, “May Allah curse the Jews. They make the fat of sheep unlawful, yet they consume its price.”"]}},"tuhfa":{},"refs":[{"key":"sh13160","label":"الحارث بن أبي أسامة -بغية الباحث","number":433,"lafz":true},{"key":"sh10490","label":"أبو نعيم في معرفة الصحابة","number":2}],"full":1,"dr":1},{"num":5796,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَسْعُودٍ الأَنْصَارِيِّ ـ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ ثَمَنِ الْكَلْبِ وَمَهْرِ الْبَغِيِّ وَحُلْوَانِ الْكَاهِنِ."],"takhrij":"متفق عليه: رواه مالك في البيوع (68) عن ابن شهاب، عن أبي بكر بن عبد الرحمن بن الحارث بن هشام، عن أبي مسعود الأنصاري فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن ثمن الكلب، ومهر البغي، وحلوان الكاهن، وأجر الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (68), al-Bukhari (2237), and Muslim (1567: 39).","chapter_en":"The prohibition of taking the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the wage of a cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":31,"content":{"translation":{"en":["Abu Mas‘ud al-Ansari reported that the Messenger of Allah ﷺ forbade the price of a dog, the payment given to a prostitute, and the fee of a fortune-teller."]},"buhuth":{"en":["Explanation: “The fee of a fortune-teller” refers to money taken easily and wrongfully, without lawful effort. By analogy, this includes any unlawful payment taken without right."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":68,"lafz":true},{"key":"bukhari","label":"البخاري","number":2237},{"key":"muslim","label":"مسلم","number":1567}],"full":1,"dr":1,"rep":[12882]},{"num":5797,"demo":false,"sanad":"","matn":["عَنْ رَافِعِ بْنِ خَدِيجٍ، قَالَ سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ شَرُّ الْكَسْبِ مَهْرُ الْبَغِيِّ وَثَمَنُ الْكَلْبِ وَكَسْبُ الْحَجَّامِ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1568) عن محمد بن حاتم، حدثنا يحيى بن سعيد القطان، عن محمد بن يوسف قال: سمعت السائب بن يزيد يحدث عن رافع بن خديج قال:فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن ثمن الكلب، ومهر البغي، وحلوان الكاهن، وأجر الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1568). In another wording: “The price of a dog is filthy, the payment of a prostitute is filthy, and the earnings of a cupper are filthy.”","chapter_en":"The prohibition of taking the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the wage of a cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":31,"content":{"translation":{"en":["Rafi‘ ibn Khadij reported that he heard the Messenger of Allah ﷺ say, “The worst earnings are the payment of a prostitute, the price of a dog, and the earnings of a cupper.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1568,"lafz":true}],"full":1,"dr":1,"rep":[5831]},{"num":5798,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ، قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ثَمَنِ الْكَلْبِ وَإِنْ جَاءَ يَطْلُبُ ثَمَنَ الْكَلْبِ فَامْلأْ كَفَّهُ تُرَابًا."],"takhrij":"صحيح: رواه أبو داود (3482) عن الربيع بن نافع أبي توبة، حدثنا عبيدالله –يعني ابن عمرو-، عن عبد الكريم، عن قيس بن حَبْتَر، عن عبد الله بن عباس فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن ثمن الكلب، ومهر البغي، وحلوان الكاهن، وأجر الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3482), Ahmad (2626, 2512), and al-Bayhaqi (6/6).","chapter_en":"The prohibition of taking the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the wage of a cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":31,"content":{"translation":{"en":["Abdullah ibn Abbas said: The Messenger of Allah ﷺ forbade the price of a dog, and if its owner comes demanding its price, then fill his hands with dust."]},"buhuth":{"en":["In another wording: “The Messenger of Allah ﷺ forbade the price of wine, the payment of a prostitute, and the price of a dog.” He said: “If its owner comes asking for its price, then fill his hands with dust.”","Explanation: The mention of dust means disappointment and deprivation."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3482,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":6},{"key":"ahmad","label":"مسند الإمام أحمد","number":2626,"n":2626}],"full":1,"dr":1},{"num":5799,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ كَسْبِ الإِمَاءِ."],"takhrij":"صحيح: رواه البخاري في الإجارة (2283) عن مسلم بن إبراهيم، حدثنا شعبة، عن محمد بن جحادة، عن أبي حازم، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن ثمن الكلب، ومهر البغي، وحلوان الكاهن، وأجر الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2283).","chapter_en":"The prohibition of taking the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the wage of a cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":31,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ forbade the earnings of slave women."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2283,"lafz":true}],"full":1,"dr":1,"rep":[12881]},{"num":5800,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ يَحِلُّ ثَمَنُ الْكَلْبِ، وَلاَ حُلْوَانُ الْكَاهِنِ، وَلاَ مَهْرُ الْبَغِيِّ."],"takhrij":"صحيح: رواه أبو داود (3484)، والنسائي (4293)، والبيهقي (6/6) كلهم من حديث ابن وهب قال: أنبأنا معروف بن سويد الجذامي أن علي بن رباح اللخمى حدثه، أنه سمع أبا هريرة يقول فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن ثمن الكلب، ومهر البغي، وحلوان الكاهن، وأجر الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3484), al-Nasa’i (4293), and al-Bayhaqi (6/6).","chapter_en":"The prohibition of taking the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the wage of a cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":31,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said, “The price of a dog, the fee of a fortune-teller, and the payment of a prostitute are not lawful.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3484,"lafz":true},{"key":"nasai","label":"النسائي","number":4293,"n":4293},{"key":"kubrabayhaqi","label":"البيهقي","number":6},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":11010,"n":11104}],"full":1,"dr":1},{"num":5801,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ نَهَى عَنْ ثَمَنِ الْكَلْبِ، وَمَهْرِ الْبَغِيِّ، وَعَسْبِ الْفَحْلِ."],"takhrij":"صحيح: رواه أحمد (10489، 10490)، وابن حبان (4941) كلاهما من طرق عن عطاء بن أبي رباح، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن ثمن الكلب، ومهر البغي، وحلوان الكاهن، وأجر الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (10490, 10489) and Ibn Hibban (4941).","chapter_en":"The prohibition of taking the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the wage of a cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":31,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ forbade the price of a dog, the payment of a prostitute, and the fee taken for the stud service of a male animal."]},"buhuth":{"en":["In another narration there is an added wording: “the price of a cat.” In another: “the earnings of a cupper.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"ابن حبان","number":4941,"n":1921},{"key":"ahmad","label":"مسند الإمام أحمد","number":10490,"n":10489,"lafz":true},{"key":"ahmad","label":"احمد","number":10489}],"full":1,"dr":1},{"num":5802,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ثَمَنِ الْكَلْبِ وَعَسْبِ الْفَحْلِ."],"takhrij":"صحيح: رواه ابن ماجه (2160)، والنسائي (4675) كلاهما من حديث محمد بن فضيل، حدثنا الأعمش، عن أبي حازم، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن ثمن الكلب، ومهر البغي، وحلوان الكاهن، وأجر الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2160) and al-Nasa’i (4675).","chapter_en":"The prohibition of taking the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the wage of a cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":31,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ forbade the price of a dog and the fee for the stud service of a male animal."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2160,"lafz":true},{"key":"nasai","label":"النسائي","number":4675}],"full":1,"dr":1,"rep":[5843]},{"num":5803,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ: أنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ ثَمَنِ الْكَلْبِ، وَكَسْبِ الزَّمَّارَةِ."],"takhrij":"صحيح: رواه البغوي في شرح السنة (2038)، والبيهقي (6/126) كلاهما من حديث هشام بن حسان، عن ابن سيرين، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن ثمن الكلب، ومهر البغي، وحلوان الكاهن، وأجر الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Baghawi in Sharh al-Sunnah (2038) and al-Bayhaqi (6/126).","chapter_en":"The prohibition of taking the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the wage of a cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":31,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ forbade the price of a dog and the earnings of the woman who plays the pipe."]},"buhuth":{"en":["Explanation: “The earnings of the pipe-player” has been explained as the payment of a prostitute, and it has also been explained as the earnings of a woman who sings with an instrument."]}},"tuhfa":{},"refs":[{"key":"sharhsunna","label":"البغوي في شرح السنة","number":2038,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":6}],"full":1,"dr":1},{"num":5804,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَنْ كَسْبِ الْأَمَةِ، إِلَّا أَنْ يَكُونَ لَهَا عَمَلٌ وَاصِبٌ، أَوْ كَسْبٌ يُعْرَفُ."],"takhrij":"حسن: رواه الطحاوي في شرحه (1/256)، والبيهقي (8/8) كلاهما من حديث ابن وهب، أخبرني مسلم بن خالد، عن العلاء بن عبد الرحمن، عن أبيه، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب النهي عن ثمن الكلب، ومهر البغي، وحلوان الكاهن، وأجر الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tahawi (1/256) and al-Bayhaqi (8/8).","chapter_en":"The prohibition of taking the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the wage of a cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":31,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ forbade the earnings of a slave woman unless she had a respectable occupation or a known lawful trade."]},"buhuth":{"en":["Explanation: This shows that the forbidden earning here is unlawful earning. If she works in a permissible trade such as spinning, sewing, and similar work, then there is no problem."]}},"tuhfa":{},"refs":[{"key":"sh21108","label":"الطحاوي","number":1,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":8},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":15784,"n":15942}],"full":1,"dr":1},{"num":5805,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو قَالَ: نَهَى عَنْ ثَمَنِ الْكَلْبِ، وَمَهْرِ الْبَغِيِّ، وَأَجْرِ الْكَاهِنِ، وَكَسْبِ الْحَجَّامِ."],"takhrij":"صحيح: رواه الحاكم (2/33)، وعنه البيهقي (6/6) من حديث هشيم، ثنا حصين، عن مجاهد، عن عبد الله بن عمرو فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن ثمن الكلب، ومهر البغي، وحلوان الكاهن، وأجر الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Hakim (2243). The earnings of a cupper are not considered unlawful; rather, this is understood as dislike, not prohibition.","chapter_en":"The prohibition of taking the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the wage of a cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":31,"content":{"translation":{"en":["Abdullah ibn Amr said: The Prophet ﷺ forbade the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the earnings of a cupper."]}},"tuhfa":{},"refs":[{"key":"hakim","label":"المستدرك على الصحيحين","number":2243,"n":2235,"lafz":true}],"full":1,"dr":1},{"num":5806,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ خَمْسٌ مِنَ الدَّوَابِّ لَيْسَ عَلَى الْمُحْرِمِ فِي قَتْلِهِنَّ جُنَاحٌ الْغُرَابُ وَالْحِدَأَةُ وَالْعَقْرَبُ وَالْفَارَةُ وَالْكَلْبُ الْعَقُورُ."],"takhrij":"متفق عليه: رواه مالك في الحج (88) عن نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب الأمر بقتل الكلاب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (88), al-Bukhari (1826), and Muslim (1199: 76).","chapter_en":"The command to kill dogs","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":32,"content":{"translation":{"en":["Ibn Umar reported that the Messenger of Allah ﷺ said: “There is no sin upon a person in ihram in killing five harmful creatures: the crow, the kite, the scorpion, the rat, and the vicious dog.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":88,"lafz":true},{"key":"bukhari","label":"البخاري","number":1826},{"key":"muslim","label":"مسلم","number":1199,"n":2872}],"full":1,"dr":1,"rep":[4842]},{"num":5807,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِقَتْلِ الْكِلاَبِ."],"takhrij":"متفق عليه: رواه مالك في الاستئذان (14) عن نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب الأمر بقتل الكلاب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (14), al-Bukhari (3323), and Muslim (1570: 43).","chapter_en":"The command to kill dogs","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":32,"content":{"translation":{"en":["Abdullah ibn Umar reported that the Messenger of Allah ﷺ ordered that dogs be killed."]},"buhuth":{"en":["Muslim also narrates from another route: The Messenger of Allah ﷺ used to command the killing of dogs, so we would go through Madinah and its outskirts and would not leave any dog without killing it, until we even killed the dog belonging to a woman from the desert that followed her."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":14,"lafz":true,"n":21},{"key":"bukhari","label":"البخاري","number":3323},{"key":"muslim","label":"مسلم","number":1570}],"full":1,"dr":1},{"num":5808,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ أَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَتْلِ الْكِلاَبِ فَأَرْسَلَ فِي أَقْطَارِ الْمَدِينَةِ أَنْ تُقْتَلَ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1570: 44) عن أبي بكر بن أبي شيبة، حدثنا أبو أسامة، عن عبيدالله، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب الأمر بقتل الكلاب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1570: 44).","chapter_en":"The command to kill dogs","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":32,"content":{"translation":{"en":["Ibn Umar said: The Messenger of Allah ﷺ ordered dogs to be killed, and messengers were sent throughout the outskirts of Madinah for that."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1570,"lafz":true,"n":4017}],"full":1},{"num":5809,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِقَتْلِ الْكِلاَبِ إِلاَّ كَلْبَ صَيْدٍ أَوْ كَلْبَ غَنَمٍ أَوْ مَاشِيَةٍ. فَقِيلَ لاِبْنِ عُمَرَ إِنَّ أَبَا هُرَيْرَةَ يَقُولُ أَوْ كَلْبَ زَرْعٍ. فَقَالَ ابْنُ عُمَرَ إِنَّ لأَبِي هُرَيْرَةَ زَرْعًا."],"takhrij":"صحيح: رواه مسلم في المساقاة (1571) عن يحيى بن يحيى (هو النيسابوري)، أخبرنا حماد بن زيد، عن عمرو بن دينار، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب الأمر بقتل الكلاب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1571).","chapter_en":"The command to kill dogs","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":32,"content":{"translation":{"en":["Ibn Umar reported that the Messenger of Allah ﷺ ordered dogs to be killed except a hunting dog, or a dog for sheep, or livestock. It was said to Ibn Umar: Abu Hurayrah says, “or a dog for crops.” Ibn Umar replied: Abu Hurayrah had crops."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1571,"lafz":true}],"full":1},{"num":5810,"demo":false,"sanad":"","matn":["عن جابر قَالَ: أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَتْلِ الْكِلاَبِ حَتَّى إِنَّ الْمَرْأَةَ تَقْدَمُ مِنَ الْبَادِيَةِ بِكَلْبِهَا فَنَقْتُلُهُ ثُمَّ نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ قَتْلِهَا وَقَالَ عَلَيْكُمْ بِالأَسْوَدِ الْبَهِيمِ ذِي النُّقْطَتَيْنِ فَإِنَّهُ شَيْطَانٌ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1572) من طريق روح بن عبادة، حدثنا ابن جريج، أخبرني أبو الزبير، أنه سمع جابر بن عبد الله يقول فذكره.","grade":"صحيح","chapter_ar":"باب الأمر بقتل الكلاب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1572).","chapter_en":"The command to kill dogs","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":32,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ commanded us to kill dogs, to the point that if a woman came from the desert with her dog, we would kill it. Then the Prophet ﷺ forbade killing them and said: “Kill the pure black one with the two spots, for it is a devil.”"]},"buhuth":{"en":["Explanation: “The one with the two spots” means the dog that has two markings above its eyes."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1572,"lafz":true}],"full":1,"dr":1},{"num":5811,"demo":false,"sanad":"","matn":["عَنِ ابْنِ الْمُغَفَّلِ، قَالَ أَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَتْلِ الْكِلاَبِ ثُمَّ قَالَ مَا بَالُهُمْ وَبَالُ الْكِلاَبِ. ثُمَّ رَخَّصَ فِي كَلْبِ الصَّيْدِ وَكَلْبِ الْغَنَمِ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1573) عـن عبيد الله بن معاذ، حدثنا أبي، حدثنا شعبة، عن أبي التياح، سمع مطرف بن عبد الله، عن ابن المغفل فذكره.","grade":"صحيح","chapter_ar":"باب الأمر بقتل الكلاب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1573).","chapter_en":"The command to kill dogs","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":32,"content":{"translation":{"en":["Ibn al-Mughaffal said: The Messenger of Allah ﷺ ordered that dogs be killed, then he said: “What is the matter with them and with dogs?” Then he allowed hunting dogs and dogs for sheep."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1573,"lafz":true}],"full":1},{"num":5812,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنِ اتَّخَذَ كَلْبًا إِلاَّ كَلْبَ مَاشِيَةٍ أَوْ صَيْدٍ أَوْ زَرْعٍ انْتَقَصَ مِنْ أَجْرِهِ كُلَّ يَوْمٍ قِيرَاطٌ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1575: 58) عن عبد بن حميد، حدثنا عبدالرزاق، أخبرنا معمر، عن الزهري، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب تحريم اقتناء الكلب إلا كلب ماشية أو صيد أو زرع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1575: 58).","chapter_en":"The prohibition of keeping a dog except for livestock, hunting, or crops","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":33,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Whoever keeps a dog, except a dog for livestock, hunting, or crops, will have a qirat deducted from his reward every day.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1575,"lafz":true,"n":4031}],"full":1,"dr":1},{"num":5813,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ أَمْسَكَ كَلْبًا فَإِنَّهُ يَنْقُصُ كُلَّ يَوْمٍ مِنْ عَمَلِهِ قِيرَاطٌ، إِلاَّ كَلْبَ حَرْثٍ أَوْ مَاشِيَةٍ.","قال ابن سيرين وأبو صالح، عن أبي هريرة، عن النبي صلى الله عليه وسلم : إلا كلب غنم، أو حرث، أو صيد.","وقال أبو حازم، عـن أبي هريرة، عن النبي صلى الله عليه وسلم : كلب صيد أو ماشية."],"takhrij":"متفق عليه: رواه البخاري في الحرث والمزارعة (2322)، ومسلم في المساقاة (1575: 59) كلاهما من حديث هشام الدستوائي، حدثنا يحيى بن أبي كثير، عن أبي سلمة، عن أبي هريرة فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب تحريم اقتناء الكلب إلا كلب ماشية أو صيد أو زرع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2322) and Muslim (1575: 59). This wording is from al-Bukhari.","chapter_en":"The prohibition of keeping a dog except for livestock, hunting, or crops","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":33,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Whoever keeps a dog will have a qirat deducted from his deeds every day, except a dog for farming or livestock.” Ibn Sirin and Abu Salih narrated from Abu Hurayrah from the Prophet ﷺ: “except a dog for sheep, farming, or hunting.”","Abu Hazim narrated from Abu Hurayrah from the Prophet ﷺ: “a hunting dog or a dog for livestock.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2322,"lafz":true},{"key":"muslim","label":"مسلم","number":1575}],"full":1,"dr":1},{"num":5814,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ أن رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنِ اقْتَنَى كَلْبًا إِلاَّ كَلْبًا ضاريا، أَوْ كَلْبَ مَاشِيَةٍ، نَقَصَ مِنْ عَمَلِهِ كُلَّ يَوْمٍ قِيرَاطَانِ."],"takhrij":"متفق عليه: رواه مالك في الاستئذان (13) عن نافع، عن عبد الله بن عمر فذكره. ورواه البخاري في الذبائح (5482)، ومسلم في المساقاة (1574) كلاهما من طريق مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب تحريم اقتناء الكلب إلا كلب ماشية أو صيد أو زرع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (13), al-Bukhari (5482), and Muslim (1574).","chapter_en":"The prohibition of keeping a dog except for livestock, hunting, or crops","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":33,"content":{"translation":{"en":["Ibn Umar reported that the Messenger of Allah ﷺ said: “Whoever keeps a dog, except a trained hunting dog or a dog for livestock, will have two qirats deducted from his deeds every day.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":13,"lafz":true},{"key":"bukhari","label":"البخاري","number":5482},{"key":"muslim","label":"مسلم","number":1574,"n":4027}],"full":1},{"num":5815,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنِ اقْتَنَى كَلْبًا إِلاَّ كَلْبَ مَاشِيَةٍ أَوْ ضَارِي نَقَصَ مِنْ عَمَلِهِ كُلَّ يَوْمٍ قِيرَاطَانِ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1574: 54) عن إسحاق بن إبراهيم، أخبرنا وكيع، حدثنا حنظلة بن أبي سفيان، عن سالم، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب تحريم اقتناء الكلب إلا كلب ماشية أو صيد أو زرع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1574: 54).","chapter_en":"The prohibition of keeping a dog except for livestock, hunting, or crops","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":33,"content":{"translation":{"en":["Ibn Umar reported that the Messenger of Allah ﷺ said: “Whoever keeps a dog, except a trained hunting dog or a dog for livestock, will have two qirats deducted from his deeds every day.”"]},"buhuth":{"en":["The trained dog means the dog trained for hunting."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1574,"lafz":true}],"full":1,"dr":1},{"num":5816,"demo":false,"sanad":"","matn":["عن ابْنِ عُمَرَ يُحَدِّثُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنِ اتَّخَذَ كَلْبًا إِلاَّ كَلْبَ زَرْعٍ أَوْ غَنَمٍ أَوْ صَيْدٍ يَنْقُصُ مِنْ أَجْرِهِ كُلَّ يَوْمٍ قِيرَاطٌ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1574: 56) من طـرق عـن محمد بن جعفر، حدثنا شعبة، عن قتادة، عن أبي الحكم قـال: سمعت ابن عمر يحدث فذكره.","grade":"صحيح","chapter_ar":"باب تحريم اقتناء الكلب إلا كلب ماشية أو صيد أو زرع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1574: 56).","chapter_en":"The prohibition of keeping a dog except for livestock, hunting, or crops","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":33,"content":{"translation":{"en":["Ibn Umar narrated from the Prophet ﷺ: “Whoever keeps a dog, except a dog for crops, sheep, or hunting, will have a qirat deducted from his reward every day.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1574,"lafz":true,"n":4029}],"full":1,"dr":1},{"num":5817,"demo":false,"sanad":"","matn":["عَنْ سُفْيَانَ بن أَبِي زُهَيْرٍ - وهو رَجُلٌ من ازد شَنُوءَةَ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - وَهُوَ يُحَدِّثُ نَاسًا مَعَهُ عِنْدَ بَابِ الْمَسْجِدِ، فَقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنِ اقْتَنَى كَلْبًا لاَ يُغْنِي عَنْهُ زَرْعًا، وَلاَ ضَرْعًا، نَقَصَ مِنْ عَمَلِهِ كُلَّ يَوْمٍ قِيرَاطٌ.","قال: أنت سمعت هذا من رسول الله صلى الله عليه وسلم ؟ فقـال: أي، ورب هذا المسجد."],"takhrij":"متفق عليه: رواه مالك في الاستئذان (12) عن يزيد بن خصيفة، أن السائب بن يزيد أخبره، أنه سمع سفيان بن أبي زهير فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم اقتناء الكلب إلا كلب ماشية أو صيد أو زرع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (12), al-Bukhari (2323), and Muslim (1576).","chapter_en":"The prohibition of keeping a dog except for livestock, hunting, or crops","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":33,"content":{"translation":{"en":["Sufyan ibn Abi Zuhayr, one of the Companions of the Messenger of Allah ﷺ from Azd Shanu’ah, was speaking to some people near the mosque door and said: I heard the Messenger of Allah ﷺ say: “Whoever keeps a dog that serves neither crops nor livestock will have a qirat deducted from his deeds every day.” They said: Did you hear this from the Messenger of Allah ﷺ? He said: Yes, by the Lord of this mosque."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":12,"lafz":true},{"key":"bukhari","label":"البخاري","number":2323},{"key":"muslim","label":"مسلم","number":1576}],"full":1,"dr":1},{"num":5818,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ، قَالَ إِنِّي لَمِمَّنْ يَرْفَعُ أَغْصَانَ الشَّجَرَةِ عَنْ وَجْهِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَخْطُبُ فَقَالَ لَوْلاَ أَنَّ الْكِلاَبَ أُمَّةٌ مِنَ الأُمَمِ لأَمَرْتُ بِقَتْلِهَا فَاقْتُلُوا مِنْهَا كُلَّ أَسْوَدَ بَهِيمٍ وَمَا مِنْ أَهْلِ بَيْتٍ يَرْتَبِطُونَ كَلْبًا إِلاَّ نَقَصَ مِنْ عَمَلِهِمْ كُلَّ يَوْمٍ قِيرَاطٌ إِلاَّ كَلْبَ صَيْدٍ أَوْ كَلْبَ حَرْثٍ أَوْ كَلْبَ غَنَمٍ."],"takhrij":"صحيح: رواه أبو داود (2845)، والترمذي (1486)، والنسائي (4280)، وابن ماجه (3205)، وصحّحه ابن حبان (5657) كلهم من حديث يونس بن عبيد، عن الحسن، عن عبد الله بن المغفل قال فذكر الحديث، إلا أن البعض اختصره.","grade":"صحيح","chapter_ar":"باب تحريم اقتناء الكلب إلا كلب ماشية أو صيد أو زرع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2845), al-Tirmidhi (1486), al-Nasa’i (4280), and Ibn Majah (3205).","chapter_en":"The prohibition of keeping a dog except for livestock, hunting, or crops","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":33,"content":{"translation":{"en":["Abdullah ibn Mughaffal said: I was among those who used to lift tree branches away from the face of the Messenger of Allah ﷺ while he was giving a sermon. He said: “Were it not that dogs are a community among the communities, I would have commanded that they all be killed. So kill every completely black dog. No household keeps a dog except that a qirat is deducted from their deeds every day, except for a hunting dog, a farming dog, or a dog for sheep.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2845,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1486,"n":1489},{"key":"nasai","label":"النسائي","number":4280},{"key":"ibnmajah","label":"ابن ماجه","number":3205},{"key":"ibnhibban","label":"ابن حبان","number":5657}],"full":1,"dr":1},{"num":5819,"demo":false,"sanad":"","matn":["عَنْ أَبِي الزُّبَيْرِ، قَالَ سَأَلْتُ جَابِرًا عَنْ ثَمَنِ الْكَلْبِ، وَالسِّنَّوْرِ، قَالَ زَجَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1569) عن سلمة بن شبيب، حدثنا الحسن بن أعين، حدثنا معقل، عن أبي الزبير فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن ثمن السنور والكلب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1569).","chapter_en":"The prohibition of the price of a cat and a dog","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":34,"content":{"translation":{"en":["Abu al-Zubayr said: I asked Jabir about the price of a dog and a cat. He said: The Prophet ﷺ strongly forbade that."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1569,"lafz":true}],"full":1,"dr":1},{"num":5820,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : وَالَّذِي نَفْسِي بِيَدِهِ لَيُوشِكَنَّ أَنْ يَنْزِلَ فِيكُمُ ابْنُ مَرْيَمَ حَكَمًا مُقْسِطًا، فَيَكْسِرَ الصَّلِيبَ، وَيَقْتُلَ الْخِنْزِيرَ، وَيَضَعَ الْجِزْيَةَ، وَيَفِيضَ الْمَالُ حَتَّى لاَ يَقْبَلَهُ أَحَدٌ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2222)، ومسلم في الإيمان (155) كلاهما عن قتيبة بن سعيد، حدثنا الليث، عن ابن شهاب، عن ابن المسيب، أنه سمع أبا هريرة يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في قتل الخنزير","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2222) and Muslim (155).","chapter_en":"What has come regarding killing the pig","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":35,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “By the One in Whose hand is my soul, the son of Mary will soon descend among you as a just ruler. He will break the cross, kill the pig, abolish the tribute-tax, and wealth will become so abundant that no one will accept it.”"]},"buhuth":{"en":["Explanation: “He will abolish the tribute-tax” means that only Islam will be accepted then."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2222,"lafz":true},{"key":"muslim","label":"مسلم","number":155}],"full":1,"dr":1,"rep":[8186]},{"num":5821,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ قَالَ اللَّهُ ثَلاَثَةٌ أَنَا خَصْمُهُمْ يَوْمَ الْقِيَامَةِ، رَجُلٌ أَعْطَى بِي ثُمَّ غَدَرَ، وَرَجُلٌ بَاعَ حُرًّا فَأَكَلَ ثَمَنَهُ، وَرَجُلٌ اسْتَأْجَرَ أَجِيرًا فَاسْتَوْفَى مِنْهُ، وَلَمْ يُعْطِ أَجْرَهُ."],"takhrij":"صحيح: رواه البخاري في البيوع (2227) عن بشر بن مرحوم، حدثنا يحيى بن سليم، عن إسماعيل بن أمية، عـن سعيد بن أبي سعيد، عن أبي هـريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع الإنسان الحر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2227).","chapter_en":"The prohibition of selling a free person","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":36,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: Allah said: “There are three whose opponent I will be on the Day of Resurrection: a man who gives a pledge by Me and then betrays it, a man who sells a free person and consumes his price, and a man who hires a laborer, takes his full work, and does not give him his wage.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2227,"lafz":true}],"full":1,"dr":1},{"num":5822,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ أَبِي الْحَسَنِ، قَالَ كُنْتُ عِنْدَ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا إِذْ أَتَاهُ رَجُلٌ فَقَالَ يَا أَبَا عَبَّاسٍ إِنِّي إِنْسَانٌ، إِنَّمَا مَعِيشَتِي مِنْ صَنْعَةِ يَدِي، وَإِنِّي أَصْنَعُ هَذِهِ التَّصَاوِيرَ. فَقَالَ ابْنُ عَبَّاسٍ لاَ أُحَدِّثُكَ إِلاَّ مَا سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ سَمِعْتُهُ يَقُولُ مَنْ صَوَّرَ صُورَةً فَإِنَّ اللَّهَ مُعَذِّبُهُ، حَتَّى يَنْفُخَ فِيهَا الرُّوحَ، وَلَيْسَ بِنَافِخٍ فِيهَا أَبَدًا. فَرَبَا الرَّجُلُ رَبْوَةً شَدِيدَةً وَاصْفَرَّ وَجْهُهُ. فَقَالَ وَيْحَكَ إِنْ أَبَيْتَ إِلاَّ أَنْ تَصْنَعَ، فَعَلَيْكَ بِهَذَا الشَّجَرِ، كُلِّ شَىْءٍ لَيْسَ فِيهِ رُوحٌ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2225)، ومسلم في اللباس والزينة (2110: 99) من طريق سعيد بن أبي الحسن به. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب تحريم بيع الصور التي فيها روح","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2225) and Muslim (2110/99). This is the wording of al-Bukhārī.","chapter_en":"The prohibition of selling images of animate beings","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":37,"content":{"translation":{"en":["Saʿīd ibn Abī al-Ḥasan reported: I was with Ibn ʿAbbās, may Allah be pleased with them both, when a man came to him and said: “O Abū ʿAbbās, I am a man whose livelihood comes only from the work of my hands, and I make these images.” Ibn ʿAbbās said: “I will tell you only what I heard the Messenger of Allah ﷺ say: ‘Whoever makes an image, Allah will punish him until he breathes a soul into it, and he will never be able to breathe a soul into it.’” The man became extremely distressed and his face turned pale. Ibn ʿAbbās said: “Woe to you! If you insist on making something, then make trees and everything that does not possess a soul.”"]},"buhuth":{"en":["The directly attributed wording in Muslim states:","“Every image-maker will be in the Fire. For every image he made, a soul will be created which will punish him in Hell.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2225,"lafz":true},{"key":"muslim","label":"مسلم","number":2110}],"full":1,"dr":1,"rep":[15624]},{"num":5823,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ يُمْنَعُ فَضْلُ الْمَاءِ لِيُمْنَعَ بِهِ الْكَلأُ."],"takhrij":"متفق عليه: رواه مالك في الأقضية (29) عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره. ورواه البخاري في المساقاة (2353)، ومسلم في المساقاة (1566: 36) كلاهما من طريق مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب النهي عن فضل الماء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (29), al-Bukhari (2353), and Muslim (1566: 36).","chapter_en":"The prohibition regarding surplus water","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":38,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Surplus water must not be withheld in order to prevent access to pasture.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":29},{"key":"bukhari","label":"البخاري","number":2353,"lafz":true},{"key":"muslim","label":"مسلم","number":1566}],"full":1,"dr":1},{"num":5824,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعِ فَضْلِ الْمَاءِ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1565) من طريق وكيع ويحيى بن سعيد، كلاهما عن ابن جريج، عن أبي الزبير، عن جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن فضل الماء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1565).","chapter_en":"The prohibition regarding surplus water","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":38,"content":{"translation":{"en":["Jabir ibn Abd Allah said: The Messenger of Allah ﷺ forbade selling surplus water."]},"buhuth":{"en":["In another wording: “The Messenger of Allah ﷺ forbade selling the stud service of a camel, and selling water and land for cultivation.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1565,"lafz":true}],"full":1,"dr":1},{"num":5825,"demo":false,"sanad":"","matn":["عن إياس بن عبدالمزني –وكان من أصحاب النبي صلى الله عليه وسلم - قال: نهى رسول الله صلى الله عليه وسلم  عن بيع فضل الماء."],"takhrij":"صحيح: رواه أبو داود (3478)، والترمذي (1271)، والنسائي (4662)، وابن ماجه (2471)، والدارمي (2654)، وصحّحه ابن حبان (4952)، والحاكم (2/61)، وابن الجارود (594) كلهم من حديث عمرو بن دينار، عن أبي المنهال قال: سمعت إياس بن عبدٍ المزني فذكره. وإسناده صحيح","grade":"صحيح","chapter_ar":"باب النهي عن فضل الماء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3478), al-Tirmidhi (1271), al-Nasa’i (4662), Ibn Majah (2471), and al-Darimi (2654).","chapter_en":"The prohibition regarding surplus water","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":38,"content":{"translation":{"en":["Iyas ibn Abd al-Muzani, who was one of the Companions of the Prophet ﷺ, said: The Messenger of Allah ﷺ forbade selling surplus water."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3478,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1271},{"key":"nasai","label":"النسائي","number":4662},{"key":"ibnmajah","label":"ابن ماجه","number":2471,"n":2477},{"key":"darimi","label":"الدارمي","number":2654},{"key":"ibnhibban","label":"ابن حبان","number":4952},{"key":"sh13071","label":"ابن الجارود","number":594}],"full":1,"dr":1},{"num":5826,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنْ يُمْنَعَ نَقْعُ الْبِئْرِ، يَعْنِي فَضْلَ الْمَاءِ."],"takhrij":"حسن: رواه أحمد (26311)، وابن حبان (4955) كلاهما من حديث محمد بن إسحاق قال: حدثني أبو الرجال محمد بن عبد الرحمن بن حارثة الأنصاري، عن أمه عمرة بنت عبد الرحمن، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب النهي عن فضل الماء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (26311) and Ibn Hibban (4955).","chapter_en":"The prohibition regarding surplus water","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":38,"content":{"translation":{"en":["Aishah said: The Messenger of Allah ﷺ forbade preventing the use of the remaining water of a well, meaning its surplus water."]},"buhuth":{"en":["Explanation: “The remaining water of the well” means the water left after the owner has taken what he needs."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":26311,"n":26074,"lafz":true},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2371,"n":2368},{"key":"ibnhibban","label":"ابن حبان","number":4955}],"full":1,"dr":1},{"num":5827,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ثَلاَثٌ لاَ يُكَلِّمُهُمُ اللَّهُ يَوْمَ الْقِيَامَةِ، وَلاَ يَنْظُرُ إِلَيْهِمْ، وَلاَ يُزَكِّيهِمْ، وَلَهُمْ عَذَابٌ أَلِيمٌ: رَجُلٌ عَلَى فَضْلِ مَاءٍ بِالْفَلاَةِ يَمْنَعُهُ مِنِ ابْنِ السَّبِيلِ، وَرَجُلٌ بَايَعَ رَجُلاً بِسِلْعَةٍ بَعْدَ الْعَصْرِ فَحَلَفَ لَهُ بِاللَّهِ لأَخَذَهَا بِكَذَا وَكَذَا فَصَدَّقَهُ وَهُوَ عَلَى غَيْرِ ذَلِكَ، وَرَجُلٌ بَايَعَ إِمَامًا لاَ يُبَايِعُهُ إِلاَّ لِدُنْيَا، فَإِنْ أَعْطَاهُ مِنْهَا وفَّى، وَإِنْ لَمْ يُعْطِهِ مِنْهَا لَمْ يفِ."],"takhrij":"متفق عليه: رواه البخاري في المساقاة (2358)، ومسلم في الإيمان (108) كلاهما من حديث الأعمش، عن أبي صالح، عن أبي هريرة فذكر الحديث. واللفظ لمسلم. ولفظ البخاري نحوه، وزاد فيه: ثم قرأ هذه الآية إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ وَأَيْمَانِهِمْ ثَمَنًا قَلِيلًا [سورة آل عمران: ٧٧].","grade":"متفق عليه","chapter_ar":"باب إثم من منع ابن السبيل من الماء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2358) and Muslim (108). This is Muslim’s wording.","chapter_en":"The sin of preventing a traveler from water","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":39,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “There are three whom Allah will neither speak to on the Day of Resurrection, nor look at, nor purify, and they will have a painful punishment: a man who has surplus water in the open desert and withholds it from a traveler; a man who sells merchandise to another man after ʿAṣr and swears by Allah that he had been offered such-and-such for it, so the buyer believes him although he is lying; and a man who pledges allegiance to a ruler only for worldly gain—if the ruler gives him something from it, he remains faithful, but if he does not give him anything from it, he does not remain faithful.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2358,"lafz":true},{"key":"muslim","label":"مسلم","number":108}],"full":1},{"num":5828,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ ثَلاَثَةٌ لاَ يُكَلِّمُهُمُ اللَّهُ يَوْمَ الْقِيَامَةِ وَلاَ يَنْظُرُ إِلَيْهِمْ رَجُلٌ حَلَفَ عَلَى سِلْعَةٍ لَقَدْ أَعْطَى بِهَا أَكْثَرَ مِمَّا أَعْطَى وَهْوَ كَاذِبٌ، وَرَجُلٌ حَلَفَ عَلَى يَمِينٍ كَاذِبَةٍ بَعْدَ الْعَصْرِ لِيَقْتَطِعَ بِهَا مَالَ امْرِئٍ مُسْلِمٍ، وَرَجُلٌ مَنَعَ فَضْلَ مَاءٍ فَيَقُولُ اللَّهُ يَوْمَ الْقِيَامَةِ، الْيَوْمَ أَمْنَعُكَ فَضْلِي، كَمَا مَنَعْتَ فَضْلَ مَا لَمْ تَعْمَلْ يَدَاكَ."],"takhrij":"صحيح: رواه البخاري في المساقاة (2369)، وفي التوحيد (7446) عن عبد الله بن محمد، حدثنا سفيان، عن عمرو، عن أبي صالح السمان، عن أبي هريرة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب إثم من منع ابن السبيل من الماء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (7446, 2369).","chapter_en":"The sin of preventing a traveler from water","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":39,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ said: “There are three whom Allah will neither speak to on the Day of Resurrection nor look at: a man who swears concerning merchandise that he was offered more for it than he actually was, while he is lying; a man who swears a false oath after ʿAṣr in order to wrongfully take the wealth of a Muslim; and a man who withholds surplus water. Allah will say: ‘Today I will withhold My bounty from you, just as you withheld the surplus of that which your own hands did not produce.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7446},{"key":"bukhari","label":"البخاري في المساقاه","number":2369,"lafz":true}],"full":1,"dr":1},{"num":5829,"demo":false,"sanad":"","matn":["عَنْ أَبِي خداش حبان بن زَيْدٍ الشرعبى، عَنْ رَجُلٍ من قَرْنٍ، -وَفِي رِوَايَةِ: عَنْ رَجُلٍ مِنَ الْمُهَاجِرِينَ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: غَزَوْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَلاَثًا أَسْمَعُهُ يَقُولُ: الْمُسْلِمُونَ شُرَكَاءُ فِي ثَلاَثٍ: فِي الكلأ، وَالْمَاءِ، وَالنَّارِ."],"takhrij":"صحيح: رواه أبو داود (3477) من وجهين: عن على بن الجعد اللؤلؤى، حدثنا حريز بن عثمان، عن حبان بن زيد الشُّرعبى، عن رجل من قرن.","grade":"صحيح","chapter_ar":"باب المسلمون شركاء في ثلاثة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3477).","chapter_en":"Muslims are partners in three things","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":40,"content":{"translation":{"en":["Abu Khidash Hibban ibn Zayd al-Shara‘bi narrated from a man of Qaran — and in another narration, from a man among the Emigrants from the Companions of the Prophet ﷺ — who said: I went on three expeditions with the Prophet ﷺ, and I heard him say: “Muslims are partners in three things: pasture, water, and fire.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3477,"lafz":true}],"full":1,"dr":1},{"num":5830,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ ثَلاَثٌ لاَ يُمْنَعْنَ الْمَاءُ وَالْكَلأُ وَالنَّارُ."],"takhrij":"صحيح: رواه ابن ماجه (2473) عن محمد بن عبد الله بن يزيد قال: حدثنا سفيان، عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب المسلمون شركاء في ثلاثة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (2473).","chapter_en":"Muslims are partners in three things","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":40,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “Three things are not to be withheld: water, pasture, and fire.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2473,"lafz":true}],"full":1,"dr":1},{"num":5831,"demo":false,"sanad":"","matn":["عَنْ رَافِعِ بْنِ خَدِيجٍ، قَالَ سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ شَرُّ الْكَسْبِ مَهْرُ الْبَغِيِّ وَثَمَنُ الْكَلْبِ وَكَسْبُ الْحَجَّامِ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1568: 40) عن محمد بن حاتم، حدثنا يحيى بن سعيد القطان، عن محمد بن يوسف، سمعت السائب بن يزيد يحدث عن رافع بن خديج قال:فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في النهي عن كسب الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1568: 40). He also narrated it (41) through another route with the wording: “The price of a dog is vile, the payment of a prostitute is vile, and the earnings of a cupper are vile.”","chapter_en":"What has been narrated regarding the discouragement of the cupper’s earnings","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":41,"content":{"translation":{"en":["Rafi‘ ibn Khadij said: I heard the Prophet ﷺ say, “The worst earnings are the payment of a prostitute, the price of a dog, and the earnings of a cupper.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":40,"lafz":true},{"key":"muslim","label":"مسلم في المساقاه","number":1568}],"full":1,"dr":1,"rep":[5797]},{"num":5832,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَسْعُودٍ، عُقْبَةَ بْنِ عَمْرٍو قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ كَسْبِ الْحَجَّامِ."],"takhrij":"حسن: رواه ابن ماجه (2165) عن هشام بن عمار قال: حدثنا يحيى بن حمزة قال: حدثني الأوزاعي، عن الزهري، عن أبي بكر بن عبد الرحمن بن الحارث بن هشام، عن أبي مسعود عقبة بن عمرو فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في النهي عن كسب الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2165).","chapter_en":"What has been narrated regarding the discouragement of the cupper’s earnings","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":41,"content":{"translation":{"en":["Abu Mas‘ud ‘Uqbah ibn ‘Amr said: The Messenger of Allah ﷺ forbade the earnings of a cupper."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2165,"lafz":true}],"full":1,"dr":1},{"num":5833,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَنْ كَسْبِ الْحَجَّامِ، فَقَالَ - أَحْسَبُهُ قَالَ -: اعْلِفْهُ نَاضِحَكُمْ."],"takhrij":"صحيح: رواه أحمد (14290، 15079)، وأبو يعلى (2114) كلاهما من حديث سفيان بن عيينة، عن أبي الزبير، سمع جابرا يقول: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في النهي عن كسب الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (15079, 14290) and Abu Ya‘la (2114).","chapter_en":"What has been narrated regarding the discouragement of the cupper’s earnings","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":41,"content":{"translation":{"en":["Jabir reported that the Prophet ﷺ was asked about the earnings of a cupper, and he said, “Feed it to your water-carrying camel.”"]},"buhuth":{"en":["The word nadih means a camel used for drawing water."]}},"tuhfa":{},"refs":[{"key":"sh12520","label":"أبو يعلى","number":2114},{"key":"ahmad","label":"مسند الإمام أحمد","number":15079,"n":15079,"lafz":true},{"key":"ahmad","label":"احمد","number":14290}],"full":1,"dr":1},{"num":5834,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ حَجَمَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَبُو طَيْبَةَ، فَأَمَرَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِصَاعٍ مِنْ تَمْرٍ، وَأَمَرَ أَهْلَهُ أَنْ يُخَفِّفُوا عَنْهُ مِنْ خَرَاجِهِ."],"takhrij":"متفق عليه: رواه مالك في الاستئذان (26) عن حميد الطويل، عن أنس بن مالك فذكره. ورواه البخاري في الطب (5696)، ومسلم في المساقاة (1577: 62) من وجه آخر عن حميد الطويل، عن أنس رضي الله عنه أنه سئل عن أجر الحجام؟ فقــــــــال: احتجم رسول الله صلى الله عليه وسلم ، حجمه أبو طيبة، وأعطاه صاعين من طعام، وكلم مواليه، فخَفَّفُوا عنه، وقال: إن أمثل ما تداويتم به الحجامة، والقُسْط البحري.واللفظ البخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في جواز إعطاء الأجرة للحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (26) and al-Bukhari (2210). Muslim (1577: 62) also narrated through another route from Anas that he was asked about the wage of a cupper, so he said: The Messenger of Allah ﷺ had cupping done by Abu Taybah, and he gave him two sa‘s of food, and he spoke to his masters so they reduced his burden. He also said: “Among the best remedies you use are cupping and sea costus.” This wording is from al-Bukhari.","chapter_en":"What has been narrated regarding the permissibility of paying the cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":42,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ had cupping done, and Abu Taybah cupped him. The Messenger of Allah ﷺ ordered that he be given a sa‘ of dates, and he told his family to reduce his tax burden."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":26},{"key":"bukhari","label":"البخاري","number":2210},{"key":"muslim","label":". ورواه مسلم","number":62},{"key":"bukhari","label":"البخاري في الطب","number":5696,"lafz":true},{"key":"muslim","label":"مسلم في المساقاه","number":1577}],"full":1,"dr":1},{"num":5835,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ حَجَمَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَبْدٌ لِبَنِي بَيَاضَةَ فَأَعْطَاهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَجْرَهُ وَكَلَّمَ سَيِّدَهُ فَخَفَّفَ عَنْهُ مِنْ ضَرِيبَتِهِ وَلَوْ كَانَ سُحْتًا لَمْ يُعْطِهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"متفق عليه: رواه مسلم في المساقاة (1202: 66) من طريق عبدالرزاق أخبرنا معمر، عن عاصم، عن الشعبي، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في جواز إعطاء الأجرة للحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1202: 66). Al-Bukhari (2103) narrated it with the wording: “The Prophet ﷺ had cupping done and gave the one who cupped him payment. If it had been unlawful, he would not have given it.”","chapter_en":"What has been narrated regarding the permissibility of paying the cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":42,"content":{"translation":{"en":["Ibn ‘Abbas said: A slave belonging to Banu Bayadah cupped the Prophet ﷺ, so the Prophet ﷺ gave him his wage and spoke to his master, who then reduced his levy. If it had been unlawful, the Prophet ﷺ would not have given it to him."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":66,"lafz":true},{"key":"bukhari","label":"البخاري","number":2103},{"key":"muslim","label":"مسلم في المساقاه","number":1202,"n":4042}],"full":1,"dr":1},{"num":5836,"demo":false,"sanad":"","matn":["عَنْ محيصة أنه سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ كَسْبِ حَجَّامٍ لَهُ، فَنَهَاهُ عَنْهُ. فَلَمْ يَزَلْ بِهِ يُكَلِّمُهُ حَتَّى قَالَ: اعْلِفْهُ نَاضِحَكَ، وَأَطْعِمْهُ رَقِيقَكَ."],"takhrij":"صحيح: رواه أحمد (23693)، والشافعي في المسند (2/166)، والحميدي (878)، والبيهـقي (9/337)، كلهـم من حديث سفيان، عـن الزهري، عن حرام بن سعد بن محيصة، عن أبيه، عن محيصـة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في جواز إعطاء الأجرة للحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (23693), al-Shafi‘i in al-Musnad (2/166), al-Humaydi (878), and al-Bayhaqi (9/337).","chapter_en":"What has been narrated regarding the permissibility of paying the cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":42,"content":{"translation":{"en":["Muhayyisah asked the Prophet ﷺ about the earnings of a cupper he had. He discouraged him from it. Muhayyisah kept speaking to him until he said, “Feed it to your camel and feed it to your servants.”"]}},"tuhfa":{},"refs":[{"key":"الشافعی/المسند","label":"الشافعي في المسند","number":2},{"key":"humaydi","label":"الحميدي","number":878},{"key":"kubrabayhaqi","label":"البيهقي","number":9},{"key":"ahmad","label":"مسند الإمام أحمد","number":23693,"n":23693,"lafz":true}],"full":1,"dr":1},{"num":5837,"demo":false,"sanad":"","matn":["عَنْ مُحَيِّصَةَ بْنِ مَسْعُودٍ الْأَنْصَارِيِّ: أَنَّهُ كَانَ لَهُ غُلَامٌ حَجَّامٌ يُقَالُ لَهُ: نَافِعٌ أَبُو طَيِّبَةَ، فَانْطَلَقَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْأَلُهُ عَنْ خَرَاجِهِ، فَقَالَ: لَا تَقْرَبْهُ فَرَدَّدَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: اعْلِفْ بِهِ النَّاضِحَ، وَاجْعَلْهُ فِي كِرْشِهِ."],"takhrij":"حسن: رواه الإمام أحمد (23689) والطبراني في الكبير (20/312) والبخاري في التاريخ الكبير (8/53-54) والبيهقي (9/337) كلهم من طريق الليث، قال: حدثني يزيد بن أبي حبيب، عن أبي عفير الأنصاري، عن محمد بن سهل بن أبي حثمة، عن محيصة بن مسعود فذكره. واللفظ لأحمد.","grade":"حسن","chapter_ar":"باب ما جاء في جواز إعطاء الأجرة للحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (23689), al-Tabarani in al-Kabir (20/312), and al-Bukhari in al-Tarikh al-Kabir (8/53–54).","chapter_en":"What has been narrated regarding the permissibility of paying the cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":42,"content":{"translation":{"en":["Muhayyisah ibn Mas‘ud al-Ansari had a slave cupper named Nafi‘ Abu Taybah. He went to the Messenger of Allah ﷺ to ask him about his earnings. He said, “Do not use it.” He kept repeating the question to the Messenger of Allah ﷺ, so he said, “Feed it to the water-carrying camel and put it into its fodder.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":23689,"lafz":true},{"key":"mujamkabir","label":"الطبراني في الكبير","number":20},{"key":"tarikhbukhari","label":"البخاري في التاريخ الكبير","number":8}],"full":1,"dr":1},{"num":5838,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ، قَالَ: احْتَجَمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَمَرَنِي أَنْ أُعْطِيَ الْحَجَّامَ أَجْرَهُ."],"takhrij":"حسن: رواه أبو داود الطيالسي (148) عن ورقاء، عن عبد الأعلى، عن أبي جميلة، عن علي فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في جواز إعطاء الأجرة للحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud al-Tayalisi (148), Ibn Majah (2163), Ahmad (692), and al-Bayhaqi (9/338).","chapter_en":"What has been narrated regarding the permissibility of paying the cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":42,"content":{"translation":{"en":["‘Ali said: The Messenger of Allah ﷺ had cupping done and ordered me to give the cupper his wage."]}},"tuhfa":{},"refs":[{"key":"tayalisi","label":"أبو داود الطيالسي","number":148,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2163},{"key":"kubrabayhaqi","label":"البيهقي","number":9},{"key":"ahmad","label":"مسند الإمام أحمد","number":692,"n":692}],"full":1,"dr":1},{"num":5839,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: دَعَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَبَا طَيْبَةَ فَحَجَمَهُ، قَالَ: فَسَأَلَهُ: كَمْ ضَرِيبَتُكَ؟ قَالَ: ثَلَاثَةُ آصُعٍ، قَالَ: فَوَضَعَ عَنْهُ صَاعًا."],"takhrij":"صحيح: رواه أحمد (14809)، وأبو يعلى(1777)، كلاهما من طريق أبي عوانة، حدثنا أبو بشر جعفر بن أبي وحشية، عن سليمان بن قيس، عن جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في جواز إعطاء الأجرة للحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (14809) and Abu Ya‘la (1777). Ibn Hibban also narrated it in his Sahih (3536) through another route from Jabir ibn ‘Abd Allah, stating that the Prophet ﷺ told Abu Taybah to come to him at sunset. He ordered him to place the cupping instruments at the time the fasting person breaks the fast, and he cupped him. Then he asked, “How much is your tax?” He replied, “Two sa‘s,” so the Prophet ﷺ reduced it by one sa‘.","chapter_en":"What has been narrated regarding the permissibility of paying the cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":42,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The Prophet ﷺ called Abu Taybah and he cupped him. Then he asked him, “How much is your levy?” He replied, “Three sa‘s.” So he reduced it for him by one sa‘."]}},"tuhfa":{},"refs":[{"key":"sh12520","label":"أبو يعلى","number":1777},{"key":"ibnhibban","label":". ورواه ابن حبان في صحيحه","number":3536},{"key":"ahmad","label":"مسند الإمام أحمد","number":14809,"n":14809,"lafz":true}],"full":1,"dr":1},{"num":5840,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ عَسْبِ الْفَحْلِ."],"takhrij":"صحيح: رواه البخاري في الإجارة (2284) عن مسدد، حدثنا عبد الوارث وإسماعيل ابن إبراهيم، عـن علي بن الحكم، عن نافـع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع عسب الفحل وضرابه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2284).","chapter_en":"The prohibition of selling the stud service of a male animal","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":43,"content":{"translation":{"en":["Ibn ‘Umar said: The Prophet ﷺ forbade taking payment for the stud service of a male animal."]},"buhuth":{"en":["Explanation: The male animal here means the male of any animal, whether a horse, camel, goat, or otherwise. Its stud service refers to its mating service."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2284,"lafz":true}],"full":1,"dr":1},{"num":5841,"demo":false,"sanad":"","matn":["عن جابر قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعِ ضِرَابِ الْجَمَلِ وَعَنْ بَيْعِ الْمَاءِ وَالأَرْضِ لِتُحْرَثَ. فَعَنْ ذَلِكَ نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1565: 35) عن إسحاق بن إبراهيم، أخبرنا روح بن عبادة، حدثنا ابن جريج، أخبرني أبو الزبير، أنه سمع جابر بن عبد الله يقول فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع عسب الفحل وضرابه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1565: 35).","chapter_en":"The prohibition of selling the stud service of a male animal","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":43,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The Messenger of Allah ﷺ forbade selling the mating service of a camel, and selling water and land for cultivation. It was this that the Prophet ﷺ forbade."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":35,"lafz":true},{"key":"muslim","label":"مسلم في المساقاه","number":1565,"n":4005}],"full":1},{"num":5842,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ كَسْبِ الْحَجَّامِ، وَكَسْبِ الْبَغِيِّ، وَثَمَنِ الْكَلْبِ . قَالَ: وَعَسْبِ الْفَحْلِ."],"takhrij":"حسن: رواه النسائي (4673)، وأحمد (7976) كلاهما من حديث محمد بن جعفر، حدثنا شعبة، عن المغيرة (وهو ابن مقسم الضبي)، قال: سمعت عبد الرحمن بن أبي نُعم قال: سمعت أبا هريرة يقول فذكره. واللفظ لأحمد. والنسائي لم يذكر كسب البغي.","grade":"حسن","chapter_ar":"باب النهي عن بيع عسب الفحل وضرابه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4673) and Ahmad (7976). This wording is from Ahmad.","chapter_en":"The prohibition of selling the stud service of a male animal","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":43,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ forbade the earnings of a cupper, the earnings of a prostitute, the price of a dog, and payment for the stud service of a male animal."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4673,"lafz":true,"n":4675},{"key":"ahmad","label":"مسند الإمام أحمد","number":7976,"n":7976}],"full":1,"dr":1},{"num":5843,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ثَمَنِ الْكَلْبِ وَعَسْبِ الْفَحْلِ."],"takhrij":"صحيح: رواه ابن ماجه (2160)، والنسائي (4675)، والدارمي (2665) كلهم من طريق ابن فضيل، عن الأعمش، عن أبي حازم، عن أبي هريرة فذكره، إلا أنه سقط \"أبو هريرة\" في سنن النسائي المطبوعة، وثبت ذلك في الكبرى (6226)، وكذا ذكره أيضا المزي في التحفة (10/84 ح 13407)، وهو كذلك في المصادر الأخرى. ولفظ النسائي: عسب التيس.","grade":"صحيح","chapter_ar":"باب النهي عن بيع عسب الفحل وضرابه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2160), al-Nasa’i (4675), and al-Darimi (2665).","chapter_en":"The prohibition of selling the stud service of a male animal","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":43,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ forbade the price of a dog and payment for the stud service of a male animal."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2160,"lafz":true},{"key":"nasai","label":"النسائي","number":4675},{"key":"darimi","label":"الدارمي","number":2665,"n":2542}],"full":1,"dr":1,"rep":[5802]},{"num":5844,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ عَسْبِ الْفَحْلِ."],"takhrij":"حسن: رواه النسائي (4674)، والدارقطني (4713)، والبيهقي (5/339)، كلهم من طريق سفيان، عن هشام، عن ابن أبي نُعم، عن أبي سعيد الخدري فذكره.","grade":"حسن","chapter_ar":"باب النهي عن بيع عسب الفحل وضرابه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4674), al-Daraqutni (4713), and al-Bayhaqi (5/339).","chapter_en":"The prohibition of selling the stud service of a male animal","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":43,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: The Messenger of Allah ﷺ forbade payment for the stud service of a male animal."]},"buhuth":{"en":["Explanation: This means taking payment for the animal’s mating service, and it is prohibited by consensus. But lending the male animal for breeding without payment is permissible. It is authentically reported: “Among the rights of camels is lending their male for breeding,” and in another wording: “Allowing the use of their male for mating.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4674,"lafz":true,"n":4674},{"key":"sh9771","label":"الدارقطني","number":4713},{"key":"kubrabayhaqi","label":"البيهقي","number":5},{"key":"sh9771","label":"سنن الدارقطني","number":2839,"n":2848},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":10854,"n":10948}],"full":1,"dr":1},{"num":5845,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَجُلاً، مِنْ كِلاَبٍ سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ عَسْبِ الْفَحْلِ فَنَهَاهُ فَقَالَ يَا رَسُولَ اللَّهِ إِنَّا نُطْرِقُ الْفَحْلَ فَنُكْرَمُ. فَرَخَّصَ لَهُ فِي الْكَرَامَةِ."],"takhrij":"صحيح: رواه الترمذي (1274)، والنسائي (4672)، والبيهقي (5/339) كلهم من حديث إبراهيم بن حميد الرؤاسي، حدثنا هشام بن عروة، عن محمد بن إبراهيم التيمي، عن أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء من الرخصة في ذلك","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1274), who graded it Hasan, al-Nasa’i (4672), and al-Bayhaqi (5/339).","chapter_en":"What has been narrated regarding a concession in that","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":44,"content":{"translation":{"en":["Anas ibn Malik reported that a man from Banu Kilab asked the Prophet ﷺ about payment for the stud service of a male animal, and he forbade it. The man said, “O Messenger of Allah ﷺ, we lend out the male animal, and then we are given a gift.” So he allowed him to accept a gift given out of generosity."]},"buhuth":{"en":["Explanation: This means that if the borrower later gives the owner a gift without any prior condition, there is no harm in accepting it."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1274,"lafz":true},{"key":"nasai","label":"النسائي","number":4672},{"key":"kubrabayhaqi","label":"البيهقي","number":5}],"full":1,"dr":1},{"num":5846,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنِ ابْتَاعَ طَعَامًا فَلاَ يَبِيعُهُ حَتَّى يَسْتَوْفِيَهُ."],"takhrij":"متفق عليه: رواه مالك في البيوع (40) عـن نافع، عن عبـد الله بن عمر فذكره. ورواه البخاري في البيوع (2126)، ومسلم في البيوع (1526) كلاهما من طريق مالك، به مثله.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع ما لم يقبض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (40), al-Bukhari (2126), and Muslim (1526).","chapter_en":"The prohibition of selling what has not yet been received","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":45,"content":{"translation":{"en":["Ibn ‘Umar reported that the Messenger of Allah ﷺ said: “Whoever buys food should not sell it until he has fully taken possession of it.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":40},{"key":"bukhari","label":"البخاري","number":2126,"lafz":true},{"key":"muslim","label":"مسلم","number":1526}],"full":1},{"num":5847,"demo":false,"sanad":"","matn":["عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، قَالَ كُنَّا فِي زَمَانِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَبْتَاعُ الطَّعَامَ فَيَبْعَثُ عَلَيْنَا مَنْ يَأْمُرُنَا بِانْتِقَالِهِ مِنَ الْمَكَانِ الَّذِي ابْتَعْنَاهُ فِيهِ إِلَى مَكَانٍ سِوَاهُ قَبْلَ أَنْ نَبِيعَهُ."],"takhrij":"متفق عليه: رواه مالك في البيوع (42) عن نافع، عن عبدالله بن عمر فذكره. ورواه مسلم في البيوع (1527: 33) من طريق مالك، به مثله.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع ما لم يقبض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (42) and Muslim (1527: 33).","chapter_en":"The prohibition of selling what has not yet been received","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":45,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar said: During the time of the Messenger of Allah ﷺ, we used to buy food, and someone would be sent to us ordering us to move it from the place where we bought it to another place before selling it."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":42,"lafz":true},{"key":"muslim","label":"مسلم","number":33},{"key":"muslim","label":"مسلم في البيوع","number":1527}],"full":1,"dr":1},{"num":5848,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ كَانُوا يَبْتَاعُونَ الطَّعَامَ فِي أَعْلَى السُّوقِ فَيَبِيعُونَهُ فِي مَكَانِهِمْ، فَنَهَاهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَبِيعُوهُ فِي مَكَانِهِ حَتَّى يَنْقُلُوهُ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2167) عن مسدد، حدثنا يحيى (بن سعيد القطان) عن عبيدالله قال: حدثني نافع، عن عبد الله فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع ما لم يقبض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2167) and Muslim (1526).","chapter_en":"The prohibition of selling what has not yet been received","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":45,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar said: People used to buy food at the upper end of the market and sell it in the same place, so the Messenger of Allah ﷺ forbade them from selling it there until they had moved it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2167,"lafz":true},{"key":"muslim","label":"مسلم","number":1526}],"full":1,"dr":1},{"num":5849,"demo":false,"sanad":"","matn":["عن ابن عمر أنهم كانوا يُضْربون على عهد رسول الله صلى الله عليه وسلم  إذا اشتروا طعاما جزافا، أن يبيعوه في مكانهم حتى يؤووه إلى رحالهم."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6852) ومسلم في البيوع (1527: 37) كلاهما من حديث عبدالأعلى، حدثنا معمر، عن الزهري، عن سالم، عن ابن عمر، فذكره، واللفظ للبخاري، ولفظ مسلم نحوه.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع ما لم يقبض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6852) and Muslim (1527: 37). This wording is from al-Bukhari.","chapter_en":"The prohibition of selling what has not yet been received","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":45,"content":{"translation":{"en":["Ibn ‘Umar said that during the time of the Messenger of Allah ﷺ, people would be disciplined if they bought food without measuring it and then sold it in the same place before taking it to their residences."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6852,"lafz":true},{"key":"muslim","label":"مسلم","number":37},{"key":"muslim","label":"مسلم في البيوع","number":1527}],"full":1,"rep":[7026]},{"num":5850,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بن ثَابِتٍ قَالَ: نَهَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تُبَاعَ السِّلَعُ حَيْثُ تُبْتَاعُ، حَتَّى يَحُوزَهَا التُّجَّارُ إِلَى رِحَالِهِمْ."],"takhrij":"حسن: رواه أبو داود (3499)، وأحمد (21668)، والدارقطني (2831)، والبيهقي (5/314) كلهم من طريق محمد بن إسحاق، حدثني أبو الزناد، عن عبيد بن حنين، عن عبد الله بن عمر قال: قدم رجل من أهل الشام بزيت، فساومته فيمن ساومه من التجار، حتى ابتعته منه، فقام إليَّ رجل، فربَّحني فيه حتى أرضاني، قال: فأخذت بيده لأضرب عليها، فأخذ رجل بذراعي من خلفي، فالتفت إليه فإذا هو زيد بن ثابت فقال فذكره.","grade":"حسن","chapter_ar":"باب النهي عن بيع ما لم يقبض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3499), Ahmad (21668), al-Daraqutni (2831), and al-Bayhaqi (5/314).","chapter_en":"The prohibition of selling what has not yet been received","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":45,"content":{"translation":{"en":["Zayd ibn Thabit said: The Messenger of Allah ﷺ forbade goods from being sold in the place where they were bought until the traders had transferred them to their own premises."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3499,"lafz":true},{"key":"sh9771","label":"الدارقطني","number":2831},{"key":"kubrabayhaqi","label":"البيهقي","number":5},{"key":"ahmad","label":"مسند الإمام أحمد","number":21668,"n":21614}],"full":1,"dr":1},{"num":5851,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنِ ابْتَاعَ طَعَامًا فَلاَ يَبِعْهُ حَتَّى يَسْتَوْفِيَهُ.","قال ابن عباس: وأحسب كل شيء مثله."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2135)، ومسلم في البيوع (1525: 29)، كلاهما من طريق عمرو بن دينار، سمع طاوسا يقول: سمعت ابن عباس يقول فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع ما لم يقبض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2135) and Muslim (1525: 29). This wording is from Muslim. In another narration: “Whoever buys food should not sell it until he has measured it.” I asked Ibn ‘Abbas, “Why?” He said: “Do you not see that they exchange gold while the food remains deferred?”","chapter_en":"The prohibition of selling what has not yet been received","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":45,"content":{"translation":{"en":["Ibn ‘Abbas reported that the Messenger of Allah ﷺ said: “Whoever buys food should not sell it until he has fully taken possession of it.” Ibn ‘Abbas said: I think everything is similar to this."]},"buhuth":{"en":["Meaning: postponed."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2135,"lafz":true,"n":2136},{"key":"muslim","label":"مسلم","number":29},{"key":"muslim","label":"مسلم في البيوع","number":1525}],"full":1,"dr":1},{"num":5852,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: كان رسول الله يقول: إذا ابتعت طعاما فلا تبعه حتى تستوفيه."],"takhrij":"صحيح: رواه مسلم في البيوع (1529) عن إسحاق بن إبراهيم، أخبرنا روح، حدثنا ابن جريج، حدثني أبو الزبير أنه سمع جابر بن عبدالله يقول فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع ما لم يقبض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1529).","chapter_en":"The prohibition of selling what has not yet been received","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":45,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ used to say, “If you buy food, do not sell it until you have fully taken possession of it.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1529,"lafz":true}],"full":1},{"num":5853,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّهُ قَالَ لِمَرْوَانَ أَحْلَلْتَ بَيْعَ الرِّبَا. فَقَالَ مَرْوَانُ مَا فَعَلْتُ. فَقَالَ أَبُو هُرَيْرَةَ أَحْلَلْتَ بَيْعَ الصِّكَاكِ وَقَدْ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعِ الطَّعَامِ حَتَّى يُسْتَوْفَى. قَالَ فَخَطَبَ مَرْوَانُ النَّاسَ فَنَهَى عَنْ بَيْعِهَا. قَالَ سُلَيْمَانُ فَنَظَرْتُ إِلَى حَرَسٍ يَأْخُذُونَهَا مِنْ أَيْدِي النَّاسِ."],"takhrij":"صحيح: رواه مسلم في البيوع (1528) عن إسحاق بن إبراهيم، أخبرنا عبد الله بن الحارث المخزومي، حدثنا الضحاك بن عثمان، عن بكير بن عبد الله الأشج، عن سليمان بن يسار، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع ما لم يقبض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1528). In another wording: “Whoever buys food should not sell it until he measures it.”","chapter_en":"The prohibition of selling what has not yet been received","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":45,"content":{"translation":{"en":["Abu Hurayrah said to Marwan: You have made usury lawful. Marwan said: I have not done that. Abu Hurayrah said: You have made the sale of vouchers lawful, while the Messenger of Allah ﷺ forbade selling food until it is fully received. So Marwan addressed the people and forbade their sale. Sulayman said: I then saw the guards taking them out of people’s hands."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1528,"lafz":true,"n":3849}],"full":1,"dr":1},{"num":5854,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعِ الطَّعَامِ حَتَّى يَجْرِيَ فِيهِ الصَّاعَانِ فَيَكُونَ لِلْبَائِعِ الزِّيَادَةُ وَعَلَيْهِ النُّقْصَانُ."],"takhrij":"حسن: رواه البزار -كشف الأستار (1265)-، والبيهقي (5/316) كلاهما من حديث مسلم بن أبي مسلم الجرمي، حدثنا مخلد بن حسين، عن هشام، عن محمد بن سيرين، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب النهي عن بيع ما لم يقبض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzar in Kashf al-Astar (1265) and al-Bayhaqi (5/316).","chapter_en":"The prohibition of selling what has not yet been received","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":45,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ forbade selling food until two separate measurements had been applied to it, so that the seller would bear any shortage and be entitled to any excess."]}},"tuhfa":{},"refs":[{"key":"sh12862","label":"البزار -كشف الأستار","number":1265,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":5},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":10701,"n":10791}],"full":1,"dr":1},{"num":5855,"demo":false,"sanad":"","matn":["عَنْ حَكِيمِ بْنِ حِزَامٍ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، إِنِّي رَجُلٌ أَشْتَرِي بيوعا، فَمَا يَحِلُّ مِنْهَا وَمَا يَحْرُمُ؟ قَالَ: يَا ابْنَ أَخِي، إِذَا اشتريت بَيْعًا فَلَا تَبِعْهُ حَتَّى تَقْبِضَهُ."],"takhrij":"حسن: رواه ابن الجارود في المنتقى (602)، وابن حبان (4983)، والدارقطني (2822)، كلهم من طرق عن همام بن يحيى قال: حدثنا يحيى بن أبي كثير، حدثنا يعلى بن حكيم قال: ثنا يوسف بن ماهك، عن عبد الله بن عصمة، عن حكيم بن حزام فذكره. واللفظ لابن الجارود، ولفظهما نحوه.","grade":"حسن","chapter_ar":"باب النهي عن بيع ما لم يقبض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn al-Jarud in al-Muntaqa (602), Ibn Hibban (4983), and al-Daraqutni (2822). This wording is from Ibn al-Jarud.","chapter_en":"The prohibition of selling what has not yet been received","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":45,"content":{"translation":{"en":["Hakim ibn Hizam said: I said, “O Messenger of Allah ﷺ, I am a man who buys goods, so what of that is lawful and what is unlawful?” He said, “My nephew, if you buy something, do not sell it until you have taken possession of it.”"]}},"tuhfa":{},"refs":[{"key":"sh13071","label":"ابن الجارود في المنتقى","number":602,"lafz":true,"n":627},{"key":"ibnhibban","label":"ابن حبان","number":4983},{"key":"sh9771","label":"الدارقطني","number":2822}],"full":1,"dr":1},{"num":5856,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن عمرو بْنِ الْعَاصِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ يَحِلُّ سَلَفٌ وَبَيْعٌ وَلاَ شَرْطَانِ فِي بَيْعٍ وَلاَ رِبْحُ مَا لَمْ يُضْمَنْ وَلاَ بَيْعُ مَا لَيْسَ عِنْدَكَ."],"takhrij":"حسن: رواه أبو داود (3504)، والترمذي (1234)، والنسائي (4611)، وابن ماجه (2188)، وصحّحه الحاكم (2/17) كلهم من حديث عمرو بن شعيب، عن أبيه، عن جده فذكره. ومنهم من اختصره.","grade":"حسن","chapter_ar":"باب النهي عن بيع ما لم يقبض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3504), al-Tirmidhi (1234), and al-Nasa’i (4611). Al-Tirmidhi said: Hasan Sahih.","chapter_en":"The prohibition of selling what has not yet been received","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":45,"content":{"translation":{"en":["‘Abd Allah ibn ‘Amr said: The Messenger of Allah ﷺ said, “It is not lawful to combine a loan and a sale, nor two conditions in one sale, nor profit from what one has not guaranteed, nor the sale of what is not in your possession.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3504,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1234},{"key":"nasai","label":"النسائي","number":4611,"n":4611},{"key":"ibnmajah","label":"ابن ماجه","number":2188}],"full":1,"dr":1},{"num":5857,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ أَنَّهُ كَانَ يَسِيرُ عَلَى جَمَلٍ لَهُ قَدْ أَعْيَا فَأَرَادَ أَنْ يُسَيِّبَهُ قَالَ فَلَحِقَنِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَدَعَا لِي وَضَرَبَهُ فَسَارَ سَيْرًا لَمْ يَسِرْ مِثْلَهُ قَالَ بِعْنِيهِ بِوُقِيَّةٍ. قُلْتُ لاَ. ثُمَّ قَالَ بِعْنِيهِ. فَبِعْتُهُ بِوُقِيَّةٍ وَاسْتَثْنَيْتُ عَلَيْهِ حُمْلاَنَهُ إِلَى أَهْلِي فَلَمَّا بَلَغْتُ أَتَيْتُهُ بِالْجَمَلِ فَنَقَدَنِي ثَمَنَهُ ثُمَّ رَجَعْتُ فَأَرْسَلَ فِي أَثَرِي فَقَالَ أَتُرَانِي مَاكَسْتُكَ لآخُذَ جَمَلَكَ خُذْ جَمَلَكَ وَدَرَاهِمَكَ فَهُوَ لَكَ."],"takhrij":"متفق عليه: رواه البخاري في الشروط (2718)، ومسلم في المساقاة (715: 109) من طريق زكريا قال: سمعت عامراً (هو الشعبي)، يقول: حدثني جابر بن عبد الله فذكره.","grade":"متفق عليه","chapter_ar":"باب جواز بعض الشروط في البيع إذا لم تكن منافية للبيع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2718) and Muslim (715: 109). This wording is from Muslim.","chapter_en":"The permissibility of some conditions in a sale when they do not contradict the sale","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":46,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: I was traveling on a camel that had become exhausted, and I wanted to let it go. Then the Prophet ﷺ caught up with me, supplicated for me, and struck it, so it moved in a way it had never moved before. He said, “Sell it to me for one uqiyyah.” I said, “No.” Then he said again, “Sell it to me.” So I sold it to him for one uqiyyah, on the condition that I could ride it back to my family. When I arrived, I brought him the camel, and he paid me its price. Then I turned back, and he sent after me, saying, “Did you think I bargained with you just to take your camel? Take your camel and your money, for it is yours.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2718,"lafz":true},{"key":"muslim","label":"مسلم","number":109},{"key":"muslim","label":"مسلم في المساقاه","number":715,"n":4098}],"full":1,"dr":1},{"num":5858,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ جَاءَتْنِي بَرِيرَةُ فَقَالَتْ كَاتَبْتُ أَهْلِي عَلَى تِسْعِ أَوَاقٍ فِي كُلِّ عَامٍ وَقِيَّةٌ، فَأَعِينِينِي. فَقُلْتُ إِنْ أَحَبَّ أَهْلُكِ أَنْ أَعُدَّهَا لَهُمْ وَيَكُونَ وَلاَؤُكِ لِي فَعَلْتُ. فَذَهَبَتْ بَرِيرَةُ إِلَى أَهْلِهَا، فَقَالَتْ لَهُمْ فَأَبَوْا عَلَيْهَا، فَجَاءَتْ مِنْ عِنْدِهِمْ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسٌ، فَقَالَتْ إِنِّي قَدْ عَرَضْتُ ذَلِكَ عَلَيْهِمْ فَأَبَوْا، إِلاَّ أَنْ يَكُونَ الْوَلاَءُ لَهُمْ. فَسَمِعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَتْ عَائِشَةُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ خُذِيهَا وَاشْتَرِطِي لَهُمُ الْوَلاَءَ، فَإِنَّمَا الْوَلاَءُ لِمَنْ أَعْتَقَ. فَفَعَلَتْ عَائِشَةُ ثُمَّ قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي النَّاسِ، فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ أَمَّا بَعْدُ مَا بَالُ رِجَالٍ يَشْتَرِطُونَ شُرُوطًا لَيْسَتْ فِي كِتَابِ اللَّهِ، مَا كَانَ مِنْ شَرْطٍ لَيْسَ فِي كِتَابِ اللَّهِ فَهُوَ بَاطِلٌ وَإِنْ كَانَ مِائَةَ شَرْطٍ، قَضَاءُ اللَّهِ أَحَقُّ، وَشَرْطُ اللَّهِ أَوْثَقُ، وَإِنَّمَا الْوَلاَءُ لِمَنْ أَعْتَقَ."],"takhrij":"متفق عليه: رواه مالك في العتق والولاء (17) عن هشام بن عروة، عن أبيه، عن عائشة فذكرته. ورواه البخاري في البيوع (2168) من طريق مالك، به. ورواه مسلم في العتق (1504) من وجه آخر عن هشام، به، ومن طرق أخرى عن عائشة.","grade":"متفق عليه","chapter_ar":"باب من اشترط شرطًا ليس في كتاب الله فالبيع صحيح، والشرط فاسد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (17), al-Bukhari (2168), and Muslim (1504).","chapter_en":"Whoever makes a condition not found in the Book of Allah, the sale is valid but the condition is invalid","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":47,"content":{"translation":{"en":["Aishah said: Barirah came to me and said: I have made an agreement with my family for nine uqiyyahs, one uqiyyah each year, so help me. I said: If your family would like me to pay it all to them and your right of wala’ (patronage) becomes mine, I will do so. Barirah went to her family and told them, but they refused unless the wala’ (patronage) remained theirs. She came back while the Messenger of Allah ﷺ was sitting there and said: I presented that to them, but they refused unless the wala’ (patronage) remains theirs. The Prophet ﷺ heard this, and Aishah informed him, so he said: “Take her and stipulate the wala’ (patronage) for them, for the wala’ belongs only to the one who frees.” So Aishah did that. Then the Messenger of Allah ﷺ stood before the people, praised Allah, and said: “What is the matter with people who stipulate conditions not found in the Book of Allah? Any condition not found in the Book of Allah is invalid, even if there are a hundred conditions. The decree of Allah has more right, and the condition of Allah is firmer. The right of wala’ (patronage) belongs only to the one who frees.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":17},{"key":"bukhari","label":"البخاري","number":2168,"lafz":true},{"key":"muslim","label":"مسلم","number":1504}],"full":1,"dr":1},{"num":5859,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ أَرَادَتْ عَائِشَةُ أَنْ تَشْتَرِيَ، جَارِيَةً تُعْتِقُهَا فَأَبَى أَهْلُهَا إِلاَّ أَنْ يَكُونَ لَهُمُ الْوَلاَءُ فَذَكَرَتْ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لاَ يَمْنَعُكِ ذَلِكِ فَإِنَّمَا الْوَلاَءُ لِمَنْ أَعْتَقَ."],"takhrij":"صحيح: رواه مسلم في العتق (1505) عن أبي بكر بن أبي شيبة، حدثنا خالد بن مخلد، عن سليمان بن بلال، حدثني سهيل بن أبي صالح، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب من اشترط شرطًا ليس في كتاب الله فالبيع صحيح، والشرط فاسد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1505).","chapter_en":"Whoever makes a condition not found in the Book of Allah, the sale is valid but the condition is invalid","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":47,"content":{"translation":{"en":["Abu Hurayrah said: Aishah wanted to buy a slave girl in order to free her, but her owners refused unless the wala’ (patronage) would remain theirs. She mentioned that to the Messenger of Allah ﷺ, and he said: “Do not let that prevent you, for the wala’ (patronage) belongs only to the one who frees.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1505,"lafz":true}],"full":1,"rep":[6150]},{"num":5860,"demo":false,"sanad":"","matn":["عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ يَبِعْ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ."],"takhrij":"متفق عليه: رواه مالك في البيوع (95) عن نافع، عن عبد الله بن عمر.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الرجل على بيع أخيه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (95), al-Bukhari (2139), and Muslim (1412).","chapter_en":"The prohibition of a man selling over the sale of his brother","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":48,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar reported that the Messenger of Allah ﷺ said: “None of you should sell over the sale of another.”"]},"buhuth":{"en":["Additional wording: Abu Dawud adds: “except with his permission.” Al-Nasa’i’s wording is: “until he buys it or leaves it.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":95,"lafz":true,"n":229},{"key":"bukhari","label":"البخاري","number":2139},{"key":"muslim","label":"مسلم","number":1412,"n":3811}],"full":1,"dr":1},{"num":5861,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَبِيعَ حَاضِرٌ لِبَادٍ، وَلاَ تَنَاجَشُوا، وَلاَ يَبِيعُ الرَّجُلُ عَلَى بَيْعِ أَخِيهِ وَلاَ يَخْطُبُ عَلَى خِطْبَةِ أَخِيهِ، وَلاَ تَسْأَلُ الْمَرْأَةُ طَلاَقَ أُخْتِهَا لِتَكْفَأَ مَا فِي إِنَائِهَا."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2140)، ومسلم في البيوع (1413) كلاهما من حديث سفيان بن عيينة، عن الزهري، عن سعيد بن المسيب، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الرجل على بيع أخيه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2140) and Muslim (1413).","chapter_en":"The prohibition of a man selling over the sale of his brother","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":48,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ forbade a town-dweller from selling on behalf of a desert-dweller, forbade artificial bidding, forbade a man from selling over the sale of his brother, forbade proposing over the proposal of his brother, and forbade a woman from asking for her sister to be divorced so that she may take what is in her vessel."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2140,"lafz":true},{"key":"muslim","label":"مسلم","number":1413}],"full":1},{"num":5862,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ يَسُمِ الْمُسْلِمُ عَلَى سَوْمِ أَخِيهِ."],"takhrij":"صحيح: رواه مسلم في البيوع (1515: 9) من طريق إسماعيل بن جعفر، عن العلاء، عن أبيه، عن أبي هريرة.","grade":"صحيح","chapter_ar":"باب النهي عن بيع الرجل على بيع أخيه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1515: 9).","chapter_en":"The prohibition of a man selling over the sale of his brother","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":48,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “A Muslim must not outbid his brother in a transaction.”"]},"buhuth":{"en":["Explanation: This means that when a seller and buyer have already agreed on a sale but have not yet concluded it, a third person must not step in to raise the price or spoil the sale. Open bidding in a public auction is not included in this prohibition."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":9,"lafz":true,"n":172},{"key":"muslim","label":"مسلم في البيوع","number":1515}],"full":1,"dr":1},{"num":5863,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ شُمَاسَةَ، أَنَّهُ سَمِعَ عُقْبَةَ بْنَ عَامِرٍ، عَلَى الْمِنْبَرِ يَقُولُ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ الْمُؤْمِنُ أَخُو الْمُؤْمِنِ فَلاَ يَحِلُّ لِلْمُؤْمِنِ أَنْ يَبْتَاعَ عَلَى بَيْعِ أَخِيهِ وَلاَ يَخْطُبَ عَلَى خِطْبَةِ أَخِيهِ حَتَّى يَذَرَ."],"takhrij":"صحيح: رواه مسلم في النكاح (1414: 56) عن أبي الطاهر، أخبرنا عبد الله بن وهب، عن الليث وغيره، عن يزيد بن أبي حبيب، عن عبد الرحمن بن شماسة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع الرجل على بيع أخيه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1414: 56).","chapter_en":"The prohibition of a man selling over the sale of his brother","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":48,"content":{"translation":{"en":["‘Abd al-Rahman ibn Shumasah said that he heard ‘Uqbah ibn ‘Amir say on the pulpit: The Messenger of Allah ﷺ said: “The believer is the brother of the believer. It is not lawful for a believer to outbid his brother in a sale or propose over his proposal until he leaves it.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1414,"lafz":true}],"full":1},{"num":5864,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، نَهَى أَنْ يَخْطُبَ الرَّجُلُ عَلَى خِطْبَةِ أَخِيهِ، أَوْ يَبْتَاعَ عَلَى بَيْعِهِ."],"takhrij":"حسن: رواه أحمد (20115) عن سليمان بن داود الطيالسي، حدثني عمران، عن قتادة، عن الحسن، عن سمرة بن جندب فذكره.","grade":"حسن","chapter_ar":"باب النهي عن بيع الرجل على بيع أخيه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (20115).","chapter_en":"The prohibition of a man selling over the sale of his brother","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":48,"content":{"translation":{"en":["Samurah ibn Jundub reported that the Messenger of Allah ﷺ forbade a man from proposing over the proposal of his brother or buying over his sale."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":20115,"n":20115,"lafz":true}],"full":1,"dr":1},{"num":5865,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، يَبْلُغُ بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ يَبِعْ حَاضِرٌ لِبَادٍ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2140)، ومسلم في البيوع (1520) كلاهما من طريق سفيان، عن الزهري، عن سعيد بن المسيب، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الحاضر للبادي","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2140) and Muslim (1520). This wording is from Muslim.","chapter_en":"The prohibition of a town-dweller selling for a desert-dweller","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":49,"content":{"translation":{"en":["Abu Hurayrah, tracing it to the Prophet ﷺ, said: “A town-dweller must not sell on behalf of a desert-dweller.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2140,"lafz":true,"n":2369},{"key":"muslim","label":"مسلم","number":1520}],"full":1,"dr":1},{"num":5866,"demo":false,"sanad":"","matn":["عن طاوس عَنْ أَبِيهِ، عَنِ ابْنِ عَبَّاسٍ، قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تُتَلَقَّى الرُّكْبَانُ وَأَنْ يَبِيعَ حَاضِرٌ لِبَادٍ. قَالَ فَقُلْتُ لاِبْنِ عَبَّاسٍ مَا قَوْلُهُ حَاضِرٌ لِبَادٍ قَالَ لاَ يَكُنْ لَهُ سِمْسَارًا."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2158)، ومسلم في البيوع (1521) كلاهما من طريق معمر، عن عبد الله بن طاوس، عن أبيه، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الحاضر للبادي","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2158) and Muslim (1521).","chapter_en":"The prohibition of a town-dweller selling for a desert-dweller","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":49,"content":{"translation":{"en":["Tawus narrated from Ibn ‘Abbas that the Messenger of Allah ﷺ forbade meeting traders outside the market and forbade a town-dweller from selling for a desert-dweller. I said to Ibn ‘Abbas: What does “a town-dweller selling for a desert-dweller” mean? He said: He must not act as a broker for him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2158,"lafz":true},{"key":"muslim","label":"مسلم","number":1521}],"full":1},{"num":5867,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ نُهِينَا أَنْ يَبِيعَ حَاضِرٌ لِبَادٍ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2161)، ومسلم في البيوع (1523: 22) كلاهما عن محمد بن المثنى، حدثنا معاذ، حدثنا ابن عون، عن محمد قال: قال أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الحاضر للبادي","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2161) and Muslim (1523: 22). Muslim also narrated through another route with the addition: “even if he is his brother or his father.”","chapter_en":"The prohibition of a town-dweller selling for a desert-dweller","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":49,"content":{"translation":{"en":["Anas ibn Malik said: We were forbidden from a town-dweller selling on behalf of a desert-dweller."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2161,"lafz":true},{"key":"muslim","label":"مسلم","number":22},{"key":"muslim","label":"مسلم في البيوع","number":1523}],"full":1,"dr":1},{"num":5868,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَبِيعَ حَاضِرٌ لِبَادٍ."],"takhrij":"صحيح: رواه البخاري في البيوع (2159) عن عبد الله بن صبَّاح، حدثنا أبو علي الحنفي، عن عبد الرحمن بن عبد الله بن دينار قال: حدثني أبي، عن عبد الله بن عمر فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع الحاضر للبادي","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2159).","chapter_en":"The prohibition of a town-dweller selling for a desert-dweller","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":49,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ forbade a town-dweller from selling on behalf of a desert-dweller."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2159,"lafz":true}],"full":1},{"num":5869,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ يَبِعْ حَاضِرٌ لِبَادٍ دَعُوا النَّاسَ يَرْزُقِ اللَّهُ بَعْضَهُمْ مِنْ بَعْضٍ."],"takhrij":"صحيح: رواه مسلم في البيوع (1522) من طريقين، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع الحاضر للبادي","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1522).","chapter_en":"The prohibition of a town-dweller selling for a desert-dweller","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":49,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said: “A town-dweller must not sell on behalf of a desert-dweller. Leave the people so that Allah may provide some of them through others.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1522,"lafz":true}],"full":1},{"num":5870,"demo":false,"sanad":"","matn":["عن طَلْحَةَ بن عبيد اللَّهِ قـال إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يَبِيعَ حَاضِرٌ لِبَادٍ."],"takhrij":"حسن: رواه أبو داود (3441) عن موسى بن إسماعيل، حدثنا حماد، عن محمد بن إسحاق، عن سالم المكي، أن أعرابيا حدثه أنه قدم بحلوبة له على عهد رسول الله صلى الله عليه وسلم ، فنـزل على طلحة بن عبيدالله، فقال: إن النبي صلى الله عليه وسلم  نهى أن يبيع حاضر لباد، ولكن اذهب إلى السوق، فانظر من يبايعك؟ فشاورني حتى آمرك أو أنهاك.","grade":"حسن","chapter_ar":"باب النهي عن بيع الحاضر للبادي","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3441) and Ahmad (1404).","chapter_en":"The prohibition of a town-dweller selling for a desert-dweller","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":49,"content":{"translation":{"en":["Talhah ibn ‘Ubayd Allah said: The Prophet ﷺ forbade a town-dweller from selling on behalf of a desert-dweller."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3441,"lafz":true},{"key":"ahmad","label":"الإمام أحمد","number":1404}],"full":1,"dr":1},{"num":5871,"demo":false,"sanad":"","matn":["عَنْ ابْنِ مَسْعُودٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ نَهَى عَنْ تَلَقِّي الْبُيُوعِ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2164)، ومسلم في البيوع (1518) كلاهما من طريق التيمي، عن أبي عثمان، عن ابن مسعود به. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن تلقي الركبان والجلب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2164) and Muslim (1518). This wording is from Muslim.","chapter_en":"The prohibition of meeting caravans before they reach the market and intercepting incoming goods","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":50,"content":{"translation":{"en":["Ibn Mas‘ud reported that the Prophet ﷺ forbade intercepting traders before they reached the market."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2164,"lafz":true,"n":2197},{"key":"muslim","label":"مسلم","number":1518}],"full":1,"dr":1},{"num":5872,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ يَبِيعُ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ، وَلاَ تَلَقَّوُا السِّلَعَ حَتَّى يُهْبَطَ بِهَا إِلَى السُّوقِ."],"takhrij":"متفق عليه: رواه البخاري (2165) عن عبد الله بن يوسف، أخبرنا مالك، عن نافع، عن عبد الله بن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن تلقي الركبان والجلب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by al-Bukhari (2165), and Muslim (1517) with the wording: “The Messenger of Allah ﷺ forbade that goods be met before they reach the markets.”","chapter_en":"The prohibition of meeting caravans before they reach the market and intercepting incoming goods","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":50,"content":{"translation":{"en":["Abdullah ibn Umar reported that the Messenger of Allah ﷺ, said: “None of you should sell over the sale of another, and do not go out to meet goods before they are brought down into the market.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2165,"lafz":true},{"key":"muslim","label":"مسلم","number":1517}],"full":1,"dr":1},{"num":5873,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُتَلَقَّى الْجَلَبُ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2162) من طريق سعيد بن أبي سعيد، ومسلم في البيوع (1519: 16) من طريق ابن سيرين، كلاهما عن أبي هريرة. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن تلقي الركبان والجلب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by al-Bukhari (2162) and Muslim (1519:16). The wording is that of Muslim.","chapter_en":"The prohibition of meeting caravans before they reach the market and intercepting incoming goods","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":50,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ, forbade going out to meet incoming merchandise before it reached the market."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2162,"lafz":true,"n":2140},{"key":"muslim","label":"مسلم","number":16,"n":97},{"key":"muslim","label":"مسلم في البيوع","number":1519}],"full":1},{"num":5874,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ يُتَلَقَّى الرُّكْبَانُ لِبَيْعٍ وَلاَ يَبِعْ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ وَلاَ تَنَاجَشُوا وَلاَ يَبِعْ حَاضِرٌ لِبَادٍ وَلاَ تُصَرُّوا الإِبِلَ وَالْغَنَمَ فَمَنِ ابْتَاعَهَا بَعْدَ ذَلِكَ فَهُوَ بِخَيْرِ النَّظَرَيْنِ بَعْدَ أَنْ يَحْلُبَهَا فَإِنْ رَضِيَهَا أَمْسَكَهَا وَإِنْ سَخِطَهَا رَدَّهَا وَصَاعًا مِنْ تَمْرٍ."],"takhrij":"متفق عليه: رواه مالك في البيوع (96) عن أبي الزناد، عن الأعرج، عن أبي هريرة.","grade":"متفق عليه","chapter_ar":"باب النهي عن تلقي الركبان والجلب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by Malik (96), al-Bukhari (2150), and Muslim (1515:11).","chapter_en":"The prohibition of meeting caravans before they reach the market and intercepting incoming goods","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":50,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ, said: “Do not meet riders bringing goods for sale before they arrive, and none of you should sell over the sale of another, and do not engage in artificial bidding, and a town-dweller must not sell on behalf of a desert-dweller, and do not withhold the milk of camels and sheep. Whoever buys one of them after that has the choice between two matters after milking it: if he is pleased with it, he may keep it; and if he is displeased with it, he may return it along with a sa‘ of dates.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":96,"lafz":true},{"key":"bukhari","label":"البخاري","number":2150},{"key":"muslim","label":"مسلم","number":11}],"full":1,"dr":1,"rep":[5883]},{"num":5875,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ تَلَقَّوُا الْجَلَبَ، فَمَنْ تَلَقَّاهُ فَاشْتَرَى مِنْهُ، فَإِذَا أَتَى سَيِّدُهُ السُّوقَ فَهُوَ بِالْخِيَارِ."],"takhrij":"صحيح: رواه مسلم في البيوع (1519: 17) عن ابن أبى عمر، حدثنا هشام بن سليمان، عن ابن جريج، أخبرني هشام القردوسي، عن ابن سيرين قال: سمعت أبا هريرة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب النهي عن تلقي الركبان والجلب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1519:17).","chapter_en":"The prohibition of meeting caravans before they reach the market and intercepting incoming goods","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":50,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ, said: “Do not meet incoming goods before they reach the market. Whoever meets them and buys from them, then when their owner reaches the market, he has the choice.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":17,"lafz":true},{"key":"muslim","label":"مسلم في البيوع","number":1519,"n":3823}],"full":1},{"num":5876,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ، أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، نَهَى أَنْ تُتَلَقَّى الْأَجْلَابُ، حَتَّى تَبْلُغَ الْأَسْوَاقَ، أَوْ يَبِيعَ حَاضِرٌ لِبَادٍ."],"takhrij":"حسن: رواه أحمد (20119)، والطبراني في الكبير (6929)، كلاهما من حديث علي بن عبد الله (المديني)، حدثنا معاذ، حدثني أبي، عن مطر، عن الحسن، عن سمرة قال:فذكره.","grade":"حسن","chapter_ar":"باب النهي عن تلقي الركبان والجلب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Sound. Narrated by Ahmad (20119) and al-Tabarani in al-Kabir (6929).","chapter_en":"The prohibition of meeting caravans before they reach the market and intercepting incoming goods","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":50,"content":{"translation":{"en":["Samurah reported that the Prophet of Allah ﷺ, forbade that incoming merchandise be met before it reached the markets, or that a town-dweller sell on behalf of a desert-dweller."]},"buhuth":{"en":["Meaning of this hadith: It was the custom of the Arabs to go out and meet the caravans before they entered the town and learned the market price. They would tell them that prices had fallen, that the market was weak, and that demand was low, then buy their goods from them at a reduced price. This resembles deception, so the Messenger of Allah ﷺ, forbade it. He gave the seller the option, so whoever was deceived in this way has the right to choose, and the apparent meaning of the hadith indicates this. Some scholars said that the seller only has this option if the one who met him bought the goods for less than the normal price. But if he bought them for their usual market value, then the seller has no option in that case."]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":6929},{"key":"ahmad","label":"مسند الإمام أحمد","number":20119,"n":20119,"lafz":true}],"full":1,"dr":1},{"num":5877,"demo":false,"sanad":"","matn":["عن معمر قَالَ: قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنِ احْتَكَرَ فَهُوَ خَاطِئٌ. فَقِيلَ لِسَعِيدٍ فَإِنَّكَ تَحْتَكِرُ قَالَ سَعِيدٌ إِنَّ مَعْمَرًا الَّذِي كَانَ يُحَدِّثُ هَذَا الْحَدِيثَ كَانَ يَحْتَكِرُ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1605: 129) عن عبد الله بن مسلمة بن قعنب، حدثنا سليمان (يعنى ابن بلال)، عن يحيى (وهو ابن سعيد) قال: كان سعيد بن المسيب يحدث أن معمرا قال فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الاحتكار","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1605:129).","chapter_en":"What Has Been Narrated Regarding Hoarding","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":51,"content":{"translation":{"en":["Ma‘mar reported that the Messenger of Allah ﷺ, said: “Whoever hoards is sinful.” It was said to Sa‘id: Then do you hoard? Sa‘id said: Ma‘mar, who used to narrate this hadith, also used to hoard."]},"buhuth":{"en":["The fact that a Companion may narrate a hadith and then appear to act contrary to it, and likewise a Successor may narrate it and then act differently, and even use the Companion’s differing practice as evidence, all of this suggests, as al-Bayhaqi said (5/30): “That the two of them hoarded in a manner other than the kind that was forbidden.”","Al-Khattabi said: “Although the hadith came in general wording, the narrator’s own hoarding indicates that it applies only to certain things or certain situations, because it is not to be assumed that a Companion would narrate a hadith and then oppose it. Likewise, Sa‘id ibn al-Musayyib, due to his virtue and knowledge, would not be expected to narrate a hadith and then oppose it, except that the hadith is to be understood as applying to some things and not others. It is reported that he used to hoard oil.” End quote. The discussion of the scholars on this issue will come later at the end of the chapter."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":129,"lafz":true},{"key":"muslim","label":"مسلم في المساقاه","number":1605}],"full":1,"dr":1},{"num":5878,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَبِيعُ نَخْلَ بَنِي النَّضِيرِ، وَيَحْبِسُ لأَهْلِهِ قُوتَ سَنَتِهِمْ."],"takhrij":"متفق عليه: رواه البخاري في النفقات (5357) ومسلم في الجهاد (1757) كلاهما من حديث ابن عيينة قال: قال لي معمر: قال لي الثوري: هل سمعت في رجل يجمع لأهله قوت سنتهم أو بعض السنة؟ قال معمر: فلم يحضرني، ثم ذكرت حديثا حدثناه ابن شهاب الزهري، عن مالك بن أوس، عن عمر فذكره. والسياق للبخاري، وسياق مسلم نحوه، وحبس الطعام للأهل لا يسمى احتكارا.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الاحتكار","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by al-Bukhari (5357) and Muslim (1757). The wording here is that of al-Bukhari. Storing food for one’s family is not called hoarding.","chapter_en":"What Has Been Narrated Regarding Hoarding","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":51,"content":{"translation":{"en":["Umar ibn al-Khattab reported that the Prophet ﷺ, used to sell the date-palms of Banu al-Nadir and store for his family their provisions for a year."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5357,"lafz":true},{"key":"muslim","label":"مسلم","number":1757}],"full":1,"dr":1},{"num":5879,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر أن رسول الله صلى الله عليه وسلم  نهى عن النجش."],"takhrij":"متفق عليه: رواه مـالك في البيوع (97) عن نافع، عن عبد الله بن عمـر فذكره. ورواه البخاري في البيوع (2142)، ومسلم في البيوع (1516) كلاهما من طريق مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب النهي عن النَجْش","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by Malik (97), al-Bukhari (2142), and Muslim (1516).","chapter_en":"The Prohibition of Artificial Bidding","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":52,"content":{"translation":{"en":["Abdullah ibn Umar reported that the Messenger of Allah ﷺ, forbade artificial bidding."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":97,"lafz":true,"n":160},{"key":"bukhari","label":"البخاري","number":2142,"n":2143},{"key":"muslim","label":"مسلم","number":1516}],"full":1},{"num":5880,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن أَبِي أَوْفَى قَالَ: أَقَامَ رَجُلٌ سِلْعَتَهُ، فَحَلَفَ بِاللَّهِ: لَقَدْ أعطى بِهَا مَا لَمْ يُعْطَهَا، فَنَزَلَتْ ﴿إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ وَأَيْمَانِهِمْ ثَمَنًا قَلِيلًا﴾ [سورة آلِ عِمْرَانَ: ٧٧]. وَقَالَ ابْنُ أَبِي أَوْفَى: النَّاجِشُ آكِلُ رِبًا خَائِنٌ."],"takhrij":"صحيح: رواه البخاري في الشهادات (2675) عن إسحاق، أخبرنا يزيد بن هارون، أخبرنا العوام ، حدثني إبراهيم أبو إسماعيل السكسكي، سمع عبد الله بن أبي أوفى يقول فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن النَجْش","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by al-Bukhari (2675).","chapter_en":"The Prohibition of Artificial Bidding","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":52,"content":{"translation":{"en":["Abdullah ibn Abi Awfa said: A man displayed his goods and swore by Allah that he had been offered for them what in fact he had not been offered, so the verse was revealed: “Indeed, those who exchange the covenant of Allah and their oaths for a small price…” [Surah Al Imran: 77]. Ibn Abi Awfa said: The one who engages in artificial bidding is a devourer of usury and a traitor."]},"buhuth":{"en":["In Arabic, najsh means frightening game and stirring it from its place so that it may be hunted. It is said: “I stirred up the game.”","Malik said after this hadith: “Najsh is when a person offers more for an item than its value, while not actually intending to buy it, so that others follow his lead.”","Al-Tirmidhi said: “Najsh is when a man comes to the seller of a commodity and offers more than the item is worth while the real buyer is present, intending to deceive the buyer, not intending to purchase it himself, but only to trick the buyer by the false offer.” End quote.","As for the ruling on najsh, al-Shafi‘i said: “The one who practices najsh is sinful in what he does, but the sale itself remains valid, because the seller is not the one who committed the najsh.” This was mentioned by al-Tirmidhi."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2675,"lafz":true}],"full":1,"dr":1},{"num":5881,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ تَنَاجَشُوا."],"takhrij":"صحيح: رواه أبو داود (3438) عن أحمد بن عمرو بن السرح، حدثنا سفيان، عن الزهري، عن سعيد بن المسيب، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن النَجْش","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Abu Dawud (3438), al-Tirmidhi (1304), al-Nasa’i (4506), and Ibn Majah (2174).","chapter_en":"The Prohibition of Artificial Bidding","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":52,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ, said: “Do not engage in artificial bidding.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3438,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1304},{"key":"nasai","label":"النسائي","number":4506},{"key":"ibnmajah","label":"ابن ماجه","number":2174,"n":2215}],"full":1,"dr":1},{"num":5882,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ، عَبْدِ اللَّهِ قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُحَاقَلَةِ وَالْمُزَابَنَةِ وَالْمُعَاوَمَةِ وَالْمُخَابَرَةِ - قَالَ أَحَدُهُمَا بَيْعُ السِّنِينَ هِيَ الْمُعَاوَمَةُ - وَعَنِ الثُّنْيَا وَرَخَّصَ فِي الْعَرَايَا."],"takhrij":"صحيح: رواه مسلم في البيوع (1536: 85) من طريق حماد بن زيد، حدثنا أيوب، عن أبى الزبير وسعيد بن ميناء، عن جابر بن عبد الله، فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الاستثناء في عقد البيع شيئا مجهولا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1536:85).","chapter_en":"The Prohibition of Making an Unspecified Exception in a Sale Contract","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":53,"content":{"translation":{"en":["Jabir ibn Abdullah said: The Messenger of Allah ﷺ, forbade muhaqalah, muzabanah, mu‘awamah, and mukhabarah — one of the narrators said: “Selling for coming years is what mu‘awamah means” — and he also forbade an unspecified exception, while permitting ‘araya sales."]},"buhuth":{"en":["It was also narrated by Abu Dawud (3405) and al-Tirmidhi (1290), and they added: “And the exception is forbidden unless it is specified.”","The forbidden form of exception in a sale is when a person sells the fruit of his orchard but excludes from it an unknown portion. But if he excludes a known and specified portion, then the sale is valid."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":85,"lafz":true},{"key":"muslim","label":"مسلم في البيوع","number":1536,"n":3913}],"full":1,"dr":1,"rep":[5770]},{"num":5883,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ يُتَلَقَّى الرُّكْبَانُ لِبَيْعٍ وَلاَ يَبِعْ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ وَلاَ تَنَاجَشُوا وَلاَ يَبِعْ حَاضِرٌ لِبَادٍ وَلاَ تُصَرُّوا الإِبِلَ وَالْغَنَمَ فَمَنِ ابْتَاعَهَا بَعْدَ ذَلِكَ فَهُوَ بِخَيْرِ النَّظَرَيْنِ بَعْدَ أَنْ يَحْلُبَهَا فَإِنْ رَضِيَهَا أَمْسَكَهَا وَإِنْ سَخِطَهَا رَدَّهَا وَصَاعًا مِنْ تَمْرٍ."],"takhrij":"متفق عليه: رواه مالك في البيوع (96) عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره. ورواه البخاري في البيوع (2150)، ومسلم في البيوع (1515: 11)، كلاهما كم طريق مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع المصَرَّاة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by Malik (96), al-Bukhari (2150), and Muslim (1515:11).","chapter_en":"The Prohibition of Selling an Animal Whose Milk Has Been Withheld","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":54,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ, said: “Do not meet riders bringing goods for sale before they arrive, and none of you should sell over the sale of another, and do not engage in artificial bidding, and a town-dweller must not sell on behalf of a desert-dweller, and do not withhold the milk of camels and sheep. Whoever buys such an animal after that has the choice of two options after milking it: if he is pleased with it, he may keep it, and if he is displeased with it, he may return it along with a sa‘ of dates.”"]},"buhuth":{"en":["Muslim also narrated it (1524:28) through another chain with the wording: “If one of you buys a milk-withheld she-camel or a milk-withheld sheep, then after milking it he has the choice of two options: he may keep it, or else he should return it along with a sa‘ of dates.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":96,"lafz":true},{"key":"bukhari","label":"البخاري","number":2150},{"key":"muslim","label":"مسلم","number":11},{"key":"muslim","label":"مسلم في البيوع","number":1515,"n":3815}],"full":1,"dr":1,"rep":[5874]},{"num":5884,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنِ ابْتَاعَ شَاةً مُصَرَّاةً فَهُوَ فِيهَا بِالْخِيَارِ ثَلاَثَةَ أَيَّامٍ إِنْ شَاءَ أَمْسَكَهَا وَإِنْ شَاءَ رَدَّهَا وَرَدَّ مَعَهَا صَاعًا مِنْ تَمْرٍ."],"takhrij":"صحيح: رواه مسلم في البيوع (1524: 24) عن قتيبة بن سعيد، حدثنا يعقوب بن عبدالرحمن القاري، عن سهيل، عن أبيه، عن أبي هريرة.","grade":"صحيح","chapter_ar":"باب النهي عن بيع المصَرَّاة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1524:24). In another narration: “If he returns it, he returns with it a sa‘ of food, not brown wheat.”","chapter_en":"The Prohibition of Selling an Animal Whose Milk Has Been Withheld","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":54,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ, said: “Whoever buys a milk-withheld sheep has the option for three days: if he wishes, he may keep it; and if he wishes, he may return it and return with it a sa‘ of dates.”"]},"buhuth":{"en":["And in another wording: “Whoever buys a milk-withheld sheep has the choice of two options: if he wishes, he may keep it; and if he wishes, he may return it along with a sa‘ of dates, not brown wheat.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":24,"lafz":true},{"key":"muslim","label":"مسلم في البيوع","number":1524,"n":3831}],"full":1,"dr":1},{"num":5885,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا بَاعَ أَحَدُكُمُ الشَّاةَ - أَوِ اللِّقْحَةَ - فَلَا يُحَفِّلْهَا."],"takhrij":"صحيح: رواه النسائي (4486)، وأحمد (7699)، وابن حبان (4969) من حديث عبدالرزاق –وهو في مصنفه (14864)-: أخبرنا معمر، عن يحيى بن أبي كثير، أخبرني أبو كثير، أنه سمع أبا هريرة فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب النهي عن بيع المصَرَّاة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasāʾī (4486), Aḥmad (7699), and Ibn Ḥibbān (4969).","chapter_en":"The Prohibition of Selling an Animal Whose Milk Has Been Withheld","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":54,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “When one of you sells a sheep or a milch-camel, he must not withhold its milk in the udder in order to make it appear to contain more milk.”"]},"buhuth":{"en":["The majority of the scholars, including Mālik, al-Shāfiʿī, Aḥmad, and others, held that the buyer returns one ṣāʿ of dates along with the animal, whether the amount of milk consumed was small or large.","The scholars of Iraq disagreed and said that this conflicts with clear analogy. They held that if the consumed item has an equivalent, its equivalent should be returned, and if it has no equivalent, its value should be returned. As for requiring compensation with a different type of commodity, they regarded that as contrary to the general legal principles.","The majority responded that this ruling prevents dispute and contention.","The matter is discussed in detail in al-Minnah al-Kubrā (5/125)."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4486,"lafz":true,"n":4486},{"key":"ibnhibban","label":"ابن حبان","number":4969},{"key":"ahmad","label":"مسند الإمام أحمد","number":7699,"n":7699}],"full":1,"dr":1},{"num":5886,"demo":false,"sanad":"","matn":["عَنْ رجلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، عن النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: لَا يُتَلَقَّى جَلَبٌ، وَلَا يَبِعْ حَاضِرٌ لِبَادٍ، وَمَنْ اشْتَرَى شاةً مُصَرّاة أَوْ نَاقَةً -قَالَ شُعْبَةُ: إِنَّمَا قَالَ: نَاقَةً مَرَّةً وَاحِدَةً- فَهُوَ فِيهَا بِآخِرِ النَّظَرَيْنِ إِذَا هُوَ حَلَبَ، إِنْ رَدَّهَا ردّ مَعَهَا صَاعًا مِنْ طَعَامٍ.","قال الحكم: أو قال: صاعا من تمر."],"takhrij":"صحيح: رواه أحمد (18819)، والبيهقي (5/319) كلاهما من حـديث شعبة، عن الحكم، عن عبد الرحمن بن أبي ليلى، عن رجل من أصحاب النبي صلى الله عليه وسلم  فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع المصَرَّاة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (18819) and al-Bayhaqi (5/319).","chapter_en":"The Prohibition of Selling an Animal Whose Milk Has Been Withheld","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":54,"content":{"translation":{"en":["A man from the Companions of the Prophet ﷺ, narrated from the Prophet that he said: “Incoming goods are not to be met before they reach the market, and a town-dweller must not sell on behalf of a desert-dweller. Whoever buys a milk-withheld sheep or a camel — Shu‘bah said: he only said ‘camel’ one time — then after he milks it, he has the choice of two options. If he returns it, he returns with it one sa‘ of food.” Al-Hakam said: Or he said: “One sa‘ of dates.”"]},"buhuth":{"en":["His statement, “a sa‘ of food, or a sa‘ of dates,” is uncertainty from one of the narrators, not that the buyer is given a choice between the two, so that the wording remains consistent with the firmly established narrations."]}},"tuhfa":{},"refs":[{"key":"kubrabayhaqi","label":"البيهقي","number":319},{"key":"ahmad","label":"مسند الإمام أحمد","number":18819,"n":18819,"lafz":true}],"full":1,"dr":1},{"num":5887,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ مَنِ اشْتَرَى شَاةً مُحَفَّلَةً، فَرَدَّهَا فَلْيَرُدَّ مَعَهَا صَاعًا. وَنَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تُلَقَّى الْبُيُوعُ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2149) عن مسدّد، حدثنا معتمر بن سليمان التيمي، سعمت أبي، حدثنا أبو عثمان (النهدي)، عن عبد الله بن مسعود فذكره. هكذا الجزء الأول موقوفا، والجزء الثاني مرفوعا.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع المصَرَّاة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2149) and Muslim (1518).","chapter_en":"The Prohibition of Selling an Animal Whose Milk Has Been Withheld","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":54,"content":{"translation":{"en":["Abdullah ibn Mas‘ud said: Whoever buys a milk-filled sheep and then returns it should return with it one sa‘ of dates. And the Prophet ﷺ, forbade going out to meet goods before they reached the market."]},"buhuth":{"en":["His statement, “Do not perform tasriyah,” with the letter ta pronounced with ḍammah and the letter ṣad with fatḥah, has a known linguistic meaning. It proves that tasriyah is forbidden, whether it is done for the purpose of sale or not, because it involves harming the animal, and that is prohibited. If someone sells after performing tasriyah, he has committed two wrongs: harming the animal and deceiving the buyer. The wording, “Do not perform tasriyah on camels and sheep for sale,” refers to the most common case. Some said the prohibition is specific to sale, and that doing so for a purpose other than sale would be allowed.","His statement, “If he is pleased with it, he may keep it,” indicates that the sale remains valid despite tasriyah if the buyer accepts it.","And his statement, “and a sa‘ of dates,” means that he returns one sa‘ of dates along with it.","The scholars and the linguists differed regarding the derivation of the word musarrah.","Al-Shafi‘i said: Tasriyah is when the teats of a she-camel or sheep are tied and it is left unmilked for two or three days until the milk gathers. Then the buyer sees much milk and increases the price because of what he sees of its abundance. When he milks it once or twice after that, he realizes that this is not its normal milk production, and this is deception of the buyer.","Abu ‘Ubayd said: “The word musarrah means a she-camel, cow, or sheep whose milk has been collected in its udder, meaning it has been held there and gathered for days without being milked. The root meaning of tasriyah is to hold back and collect water. One says: I collected and held back the water.","Tasriyah is forbidden because it involves cheating and deception, due to the Prophet’s statement: ‘Do not withhold the milk of camels and sheep.’","The hadith of Abu Hurayrah is authentic according to the scholars of hadith. A number of narrators reported it from him, including Musa ibn Yasar, Abu Salih, Hammam ibn Munabbih, Muhammad ibn Sirin, and Muhammad ibn Ziyad, through authentic chains, as Ibn Abd al-Barr said in al-Tamhid (18/203).","Ibn Mas‘ud also gave legal verdicts according to it, as al-Bukhari mentioned after the hadith of Abu Hurayrah.","And Umar ibn al-Khattab referred back to Ḥamal ibn Malik and others concerning the blood money for the fetus, just as Zayd ibn Thabit and others referred back to a woman from the Ansar concerning the falling of the farewell circumambulation from a menstruating woman.” End quote. Majmu‘ al-Fatawa (4/532).","Shaykh Muhammad Anwar Shah al-Kashmiri said: “This hadith stands as proof against us. Some Hanafis answered it by saying that if a hadith is narrated by someone who was not a jurist, and it conflicts with analogy, then the hadith is set aside and analogy is acted upon. Since the hadith of Abu Hurayrah conflicted with analogy, and was narrated by someone they claimed was not a jurist, they turned to analogy and acted by it.","He then said: This answer is invalid and should not be paid attention to. It has long been used by opponents as a point of criticism. Because of this, it became famous that the Hanafis give precedence to opinion over hadith, though they are far above saying such a thing. In truth, this principle is not authentically reported from Abu Hanifah or any of his companions.","Then he said: In summary, this answer is more deserving of being omitted from books altogether, even if some have mentioned it. And who would dare speak of Abu Hurayrah by saying he was not a jurist? Even if we granted that, the same hadith is also narrated by one who is more learned in jurisprudence, namely Ibn Mas‘ud, and then the same problem returns.” End quote. Fayd al-Bari (3/229).","Add to this that Abu Hurayrah was not alone in narrating this hadith, just as he was not alone in most of his narrations according to my study. Even if there is some discussion regarding the other reports, the foundation shows that this hadith came through multiple routes. Abu Hurayrah was one of those who preserved hadith exactly as he heard it, while others may not have preserved it with the same precision."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2149,"lafz":true},{"key":"muslim","label":"مسلم","number":1518}],"full":1,"dr":1},{"num":5888,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ نَهَى عَنْ بَيْعِ الْحَيَوَانِ بِالْحَيَوَانِ نَسِيئَةً."],"takhrij":"صحيح: رواه عبد الرزاق (1433) قال: أخبرنا معمر، عن يحيى بن أبي كثير، عن عكرمة، عن ابن عباس قال فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع الحيوان بالحيوان نسيئة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abd al-Razzaq (14133), Ibn al-Jarud in al-Muntaqa (610), and al-Bayhaqi (5/288–289).","chapter_en":"The Prohibition of Selling an Animal for Another Animal on Deferred Terms","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":55,"content":{"translation":{"en":["Ibn Abbas reported from the Prophet ﷺ, that he forbade selling an animal for another animal on delayed payment terms."]}},"tuhfa":{},"refs":[{"key":"abdrazzaq","label":"عبد الرزاق","number":14133,"lafz":true},{"key":"sh13071","label":"ابن الجارود في المنتقى","number":610},{"key":"kubrabayhaqi","label":"البيهقي","number":289},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":10532,"n":10621},{"key":"abdrazzaq","label":"عبد الرزاق","number":1433}],"full":1,"dr":1},{"num":5889,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ بَيْعِ الْحَيَوَانِ بِالْحَيَوَانِ نَسِيئَةً."],"takhrij":"صحيح: رواه أبو داود (3356)، والترمذي (1237)، والنسائي (4620)، وابن ماجه (2270)، وأحمد (20143)، والطحاوي في شرحه (5616)، وابن الجارود (611)، والبيهقي (5/288) كلهم من طرق عن قتادة، عن الحسن، عن سمرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع الحيوان بالحيوان نسيئة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3356), al-Tirmidhi (1237), al-Nasa’i (4620), Ibn Majah (2270), and Ahmad (20143).","chapter_en":"The Prohibition of Selling an Animal for Another Animal on Deferred Terms","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":55,"content":{"translation":{"en":["Samurah ibn Jundub reported that the Prophet ﷺ, forbade selling an animal for another animal on deferred terms."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3356,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1237},{"key":"nasai","label":"النسائي","number":4620,"n":4620},{"key":"ibnmajah","label":"ابن ماجه","number":2270},{"key":"ahmad","label":"مسند الإمام أحمد","number":20143,"n":20264},{"key":"sh13071","label":"ابن الجارود","number":611,"n":638}],"full":1,"dr":1},{"num":5890,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ، أَنَّهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعِ الْحَيَوَانِ بِالْحَيَوَانِ نَسِيئَةً: اثْنَيْنِ بِوَاحِدٍ، وَلَا بَأْسَ بِهِ يَدًا بِيَدٍ."],"takhrij":"حسن: رواه الترمذي (1238)، وابن ماجه (2271)، وأحمد (14331)، كلهم من طريق حجاج، عن أبي الزبير، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب النهي عن بيع الحيوان بالحيوان نسيئة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1238), Ibn Majah (2271), and Ahmad (14331). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"The Prohibition of Selling an Animal for Another Animal on Deferred Terms","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":55,"content":{"translation":{"en":["Jabir ibn Abdullah said: The Messenger of Allah ﷺ, forbade selling an animal for another animal on delayed terms, two for one, but there is no harm in it when it is hand to hand."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1238,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2271},{"key":"ahmad","label":"مسند الإمام أحمد","number":14331,"n":14331}],"full":1,"dr":1},{"num":5891,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَهُ أَنْ يُجَهِّزَ جَيْشًا فَنَفِدَتِ الإِبِلُ فَأَمَرَهُ أَنْ يَأْخُذَ فِي قِلاَصِ الصَّدَقَةِ فَكَانَ يَأْخُذُ الْبَعِيرَ بِالْبَعِيرَيْنِ إِلَى إِبِلِ الصَّدَقَةِ."],"takhrij":"حسن: رواه أبو داود (3357)، والدارقطني (3054)، والحاكم (2/56-57)، والبيهقي (5/287-289) كلهم من طريق حماد بن سلمة، عن محمد بن إسحاق، عن يزيد بن أبى حبيب، عن مسلم بن جبير، عن أبى سفيان، عن عمرو بن حريش، عن عبد الله بن عمرو فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الرخصة في ذلك","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3357), al-Daraqutni (3054), al-Hakim (2/56–57), and al-Bayhaqi (5/287–289).","chapter_en":"What has been reported regarding the concession in that","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":56,"content":{"translation":{"en":["Abdullah ibn Amr reported that the Messenger of Allah ﷺ, ordered him to equip an army. The camels ran short, so he ordered him to take from the young she-camels of the charity camels. Thus he would take one camel in exchange for two camels, to be delivered from the charity camels."]},"buhuth":{"en":["And qilas is the plural of qalus, which is a young she-camel."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3357,"lafz":true},{"key":"sh9771","label":"الدار قطني","number":3054},{"key":"hakim","label":"الحاكم","number":57},{"key":"kubrabayhaqi","label":"البيهقي","number":289}],"full":1,"dr":1},{"num":5892,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ جَاءَ عَبْدٌ فَبَايَعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْهِجْرَةِ وَلَمْ يَشْعُرْ أَنَّهُ عَبْدٌ فَجَاءَ سَيِّدُهُ يُرِيدُهُ فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِعْنِيهِ. فَاشْتَرَاهُ بِعَبْدَيْنِ أَسْوَدَيْنِ ثُمَّ لَمْ يُبَايِعْ أَحَدًا بَعْدُ حَتَّى يَسْأَلَهُ أَعَبْدٌ هُوَ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1602) من طرق عن ليث، عن أبي الزبير، عن جابر بن عبدالله قال: فذكره.","grade":"صحيح","chapter_ar":"باب جواز التفاضل في بيع العبيد والإماء إذا كان يدا بيد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1602).","chapter_en":"The permissibility of disparity in selling male and female slaves when it is hand to hand","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":57,"content":{"translation":{"en":["Jabir ibn Abdullah said: A slave came and pledged allegiance to the Prophet ﷺ, for migration, and he did not realize that he was a slave. Then his master came wanting him back, so the Prophet said to him, “Sell him to me.” He bought him for two black slaves. After that, he would not take anyone’s pledge until he asked, “Is he a slave?”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1602,"lafz":true}],"full":1,"rep":[7653]},{"num":5893,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ وَقَعَ فِي سَهْمِ دِحْيَةَ جَارِيَةٌ جَمِيلَةٌ فَاشْتَرَاهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِسَبْعَةِ أَرْؤُسٍ ثُمَّ دَفَعَهَا إِلَى أُمِّ سُلَيْمٍ تَصْنَعُهَا وَتُهَيِّئُهَا قَالَ حَمَّادٌ وَأَحْسِبُهُ قَالَ وَتَعْتَدُّ فِي بَيْتِهَا صَفِيَّةُ بِنْتُ حُيَىٍّ."],"takhrij":"صحيح: رواه مسلم في النكاح (1365: 87) عن أبي بكر بن أبى شيبة قال: حدثنا عفان، حدثنا حماد بن سلمة، حدثنا ثابت، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب جواز التفاضل في بيع العبيد والإماء إذا كان يدا بيد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1365:87), Abu Dawud (2997), Ibn Majah (2272), and al-Bayhaqi (6/304).","chapter_en":"The permissibility of disparity in selling male and female slaves when it is hand to hand","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":57,"content":{"translation":{"en":["Anas ibn Malik said: A beautiful slave-girl fell into the share of Dihyah. The Messenger of Allah ﷺ, bought her for seven slaves, then handed her over to Umm Sulaym to prepare and adorn her. He said: I think he also said: and to let her complete her waiting period in her house. She was Safiyyah bint Huyayy."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":87,"lafz":true},{"key":"abudawud","label":"أبو داود","number":2997},{"key":"ibnmajah","label":"ابن ماجه","number":2272},{"key":"kubrabayhaqi","label":"البيهقي","number":304},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":12756,"n":12882},{"key":"muslim","label":"مسلم في النكاح","number":1365,"n":3500}],"full":1,"dr":1},{"num":5894,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ بَيْعِ الشَّاةِ بِاللَّحْمِ."],"takhrij":"صحيح: رواه الحاكم (2/35)، والبيهقي 5/296) كلاهما من حديث إبراهيم بن طهمان، عن الحجاج بن الحجاج الباهلي، عن قتادة، عن الحسن، عن سمرة بن جندب قال:فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع اللحم بالحيوان","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Hakim (2/35) and al-Bayhaqi (5/296).","chapter_en":"The prohibition of selling meat for a live animal","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":58,"content":{"translation":{"en":["Samurah reported that the Prophet ﷺ, forbade selling a sheep for meat."]}},"tuhfa":{},"refs":[{"key":"hakim","label":"المستدرك على الصحيحين","number":2251,"n":2243,"lafz":true}],"full":1,"dr":1},{"num":5895,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ بْنِ مَالِكٍ قَالَ: قَالَ النَّاسُ: يَا رَسُولَ اللَّهِ، غَلاَ السِّعْرُ؛ فَسَعِّرْ لَنَا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنَّ اللَّهَ هُوَ الْمُسَعِّرُ الْقَابِضُ الْبَاسِطُ الرزاق، وَإِنِّي لأَرْجُو أَنْ أَلْقَى اللَّهَ، وَلَيْسَ أَحَدٌ مِنْكُمْ يُطَالِبُنِي بِمَظْلَمَةٍ فِي دَمٍ وَلاَ مَالٍ."],"takhrij":"صحيح: أخرجه أبو داود (3451)، والترمذي (1314)، وابن ماجه (2200)، وأحمد (1259، 14057) كلهم من طريق حماد بن سلمة، عن قتادة وثابت وحميد، عن أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في التسعير","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3451), al-Tirmidhi (1314), Ibn Majah (2200), and Ahmad (12591, 14057).","chapter_en":"What has been reported regarding price-fixing","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":59,"content":{"translation":{"en":["Anas said: The people said, “O Messenger of Allah ﷺ, prices have risen, so fix prices for us.” The Messenger of Allah ﷺ, said: “Allah is the One who fixes prices, who withholds, who gives abundantly, and who provides. I truly hope to meet Allah while none of you has any claim against me for an injustice in blood or wealth.”"]},"buhuth":{"en":["Al-Tirmidhi said: “Hasan Sahih.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3451,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1314},{"key":"ibnmajah","label":"ابن ماجه","number":2200},{"key":"ahmad","label":"مسند الإمام أحمد","number":14057,"n":14057},{"key":"ahmad","label":"احمد","number":1259}],"full":1,"dr":1},{"num":5896,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَجُلاً، جَاءَ فَقَالَ يَا رَسُولَ اللَّهِ سَعِّرْ. فَقَالَ بَلْ أَدْعُو. ثُمَّ جَاءَهُ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ سَعِّرْ فَقَالَ بَلِ اللَّهُ يَخْفِضُ وَيَرْفَعُ وَإِنِّي لأَرْجُو أَنْ أَلْقَى اللَّهَ وَلَيْسَ لأَحَدٍ عِنْدِي مَظْلَمَةٌ."],"takhrij":"صحيح: رواه أبو داود (3450)، وأحمد (8448، 8852)، والبيهقي (6/29) كلهم من طرق عن العلاء بن عبد الرحمن، عن أبيه، عن أبي هريرة فذكره. واللفظ لأبي داود، ولفظهم قريب منه. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في التسعير","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3450), Ahmad (8448, 8852), and al-Bayhaqi (6/29).","chapter_en":"What has been reported regarding price-fixing","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":59,"content":{"translation":{"en":["Abu Hurayrah reported that a man came and said, “O Messenger of Allah ﷺ, fix prices.” He said, “Rather, I will supplicate.” Then another man came and said, “O Messenger of Allah ﷺ, fix prices.” He said, “Rather, Allah lowers and raises, and I hope to meet Allah while no one has any claim of injustice against me.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3450,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":29},{"key":"ahmad","label":"مسند الإمام أحمد","number":8852,"n":8852},{"key":"ahmad","label":"احمد","number":8448}],"full":1},{"num":5897,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، قَالَ غَلاَ السِّعْرُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا لَوْ قَوَّمْتَ يَا رَسُولَ اللَّهِ قَالَ إِنِّي لأَرْجُو أَنْ أُفَارِقَكُمْ وَلاَ يَطْلُبَنِي أَحَدٌ مِنْكُمْ بِمَظْلَمَةٍ ظَلَمْتُهُ."],"takhrij":"صحيح: رواه ابن ماجه (2201)، والإمام أحمد (11809)، والطبراني في الأوسط (5952) كلهم من طرق عن أبي نضرة، عن أبي سعيد فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في التسعير","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2201), Ahmad (11809), and al-Tabarani in al-Awsat (5952).","chapter_en":"What has been reported regarding price-fixing","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":59,"content":{"translation":{"en":["Abu Sa‘id said: Prices rose during the time of the Messenger of Allah ﷺ, so they said, “If only you would set prices, O Messenger of Allah ﷺ.” He said: “I truly hope to leave you while none of you seeks from me redress for any injustice I committed against him.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2201,"lafz":true},{"key":"ahmad","label":"الإمام أحمد","number":11809},{"key":"sh28171","label":"الطبراني في الأوسط","number":5952}],"full":1,"dr":1},{"num":5898,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّ يَهُودِيًّا قَدِمَ زَمَنَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِثَلَاثِينَ حِمْلِ شَعِيرٍ، وَتَمْرٍ، فَسَعَّرَ مُدًّا بِمُدِّ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بدرهم، وَلَيْسَ فِي النَّاسِ يَوْمَئِذٍ طَعَامٌ غَيْرُهُ، وَكَانَ قَدْ أَصَابَ النَّاسَ قَبْلَ ذَلِكَ جُوعٌ، لَا يَجِدُونَ فِيهِ طَعَامًا، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، النَّاسُ يَشْكُونَ إِلَيْهِ غَلَاءَ السِّعْرِ، فَصَعِدَ الْمِنْبَرَ، فَحَمِدَ اللَّهَ، وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: لأَلْقَيَنَّ اللهَ مِنْ قَبْلِ أَنْ أُعْطِيَ أَحَدًا مِنْ مَالِ أَحَدٍ مِنْ غَيْرِ طِيبِ نَفْسٍ، إِنَّمَا الْبَيْعُ عَنْ تَرَاضٍ، وَلَكِنَّ فِي بُيُوعِكُمْ خِصَالًا أَذْكُرُهَا لَكُمْ، لَا تَضَاغَنُوا، وَلَا تَنَاجَشُوا، وَلَا تَحَاسَدُوا، وَلَا يَسُومُ الرَّجُلُ، عَلَى سَوْمِ أَخِيهِ، وَلَا يَبِيعَنَّ حَاضِرٌ لِبَادٍ، وَالْبَيْعُ عَنْ تَرَاضٍ، وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا."],"takhrij":"حسن: رواه ابن حبان (4967)، وأبو يعلى (1354)، والبيهقي (6/17)، وابن ماجه (2185) كلهم من طريق عبد العزيز بن محمد الدراوردي، عن داود بن صالح التمار، عن أبيه، عن أبي سعيد الخدري فذكره. واللفظ لابن حبان. واختصره أبو يعلى والبيهقي، واكتفى ابن ماجه بقوله: إنما البيع عن تراض.","grade":"حسن","chapter_ar":"باب ما جاء في التسعير","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Hibban (4967), Abu Ya‘la (1354), and al-Bayhaqi (6/17). The wording is that of Ibn Hibban.","chapter_en":"What has been reported regarding price-fixing","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":59,"content":{"translation":{"en":["Abu Sa‘id al-Khudri reported that during the time of the Prophet ﷺ, a Jew came with thirty loads of barley and dates, and he priced them at one mudd by the mudd of the Prophet, ﷺ. On that day the people had no food other than that, and before that they had been struck by hunger and could not find food. So the people came to the Prophet complaining to him about the high prices. He ascended the pulpit, praised Allah and glorified Him, then said: “I will not meet Allah after having given anyone the wealth of another person without his willing consent. Trade is only by mutual agreement. But in your sales there are practices that I will mention to you: do not nurse grudges, do not practice najsh, do not envy one another, let no man bargain over the bargain of his brother, let not a town-dweller sell for a desert-dweller, and trade is only by mutual consent. Be servants of Allah, brothers to one another.”"]}},"tuhfa":{},"refs":[{"key":"sh12520","label":"أبو يعلى","number":1354},{"key":"kubrabayhaqi","label":"البيهقي","number":17},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1930,"n":1927},{"key":"ibnhibban","label":"ابن حبان","number":4967,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2185}],"full":1,"dr":1},{"num":5899,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعَتَيْنِ فِي بَيْعَةٍ."],"takhrij":"حسن: رواه الترمذي (1231)، والنسائي (4632)، وأحمد (9584)، وصحّحه ابن حبان (4973)، والبيهقي (5/343)، وابن الجارود (600) كلهم من طرق عن محمد بن عمرو قال: حدثنا أبو سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب فيمن باع بيعتين في بيعة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1231), al-Nasa’i (4632), Ahmad (9584), authenticated by Ibn Hibban (4973), and al-Bayhaqi (5/343). In another narration: “Whoever conducts two sales in one sale will have either the lesser of the two prices or usury.” Narrated by Abu Dawud (3461), Ibn Hibban (4974), and al-Hakim (2/45), who said: “Authentic according to the conditions of Muslim.”","chapter_en":"Concerning one who conducts two sales in one sale","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":60,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ, forbade two sales in one sale."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1231,"lafz":true},{"key":"nasai","label":"النسائي","number":4632,"n":4632},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":4973},{"key":"kubrabayhaqi","label":"البيهقي","number":343},{"key":"abudawud","label":"أبو داود","number":3461,"n":3369},{"key":"ibnhibban","label":"ابن حبان","number":4974,"n":1894},{"key":"hakim","label":"الحاكم","number":45},{"key":"ahmad","label":"مسند الإمام أحمد","number":9584,"n":9584},{"key":"sh13071","label":"ابن الجارود","number":600}],"full":1,"dr":1},{"num":5900,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر قـال: قـال رسول الله صلى الله عليه وسلم : لا تبع بيعتين في بيعة."],"takhrij":"صحيح: رواه الترمذي (1309)، وابن ماجه (2404)، وأحمد (5395)، وابن الجارود (599)، والبيهقي (6/77) كلهم من طرق عن هشيم بن بشير، حدثنا يونس بن عبيد، عن نافع، عن ابن عمر فذكره في حديث أوله: مطل الغني ظلم، وإذا أحلت على ملأ فاتبعه. وابن ماجه لم يذكر إلا أول الحديث.","grade":"صحيح","chapter_ar":"باب فيمن باع بيعتين في بيعة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1309), Ibn Majah (2404), Ahmad (5395), Ibn al-Jarud (599), and al-Bayhaqi (6/77).","chapter_en":"Concerning one who conducts two sales in one sale","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":60,"content":{"translation":{"en":["Abdullah ibn Umar said: The Messenger of Allah ﷺ said: “Delay in payment by a wealthy person is injustice. If you are referred for payment to a solvent person, accept the transfer, and do not conduct two sales in one sale.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1309,"lafz":true,"n":1402},{"key":"ibnmajah","label":"ابن ماجه","number":2404,"n":2443},{"key":"sh13071","label":"ابن الجارود","number":599},{"key":"kubrabayhaqi","label":"البيهقي","number":6},{"key":"ahmad","label":"مسند الإمام أحمد","number":5395,"n":5425},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":11390,"n":11494}],"full":1,"dr":1},{"num":5901,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ إِذَا تَبَايَعْتُمْ بِالْعِينَةِ وَأَخَذْتُمْ أَذْنَابَ الْبَقَرِ وَرَضِيتُمْ بِالزَّرْعِ وَتَرَكْتُمُ الْجِهَادَ سَلَّطَ اللَّهُ عَلَيْكُمْ ذُلاًّ لاَ يَنْزِعُهُ حَتَّى تَرْجِعُوا إِلَى دِينِكُمْ."],"takhrij":"حسن: رواه أبو داود (3462)، والبيهقي في الكبرى (5/316) كلاهما من حديث حيوة بن شريح، عن إسحاق أبى عبد الرحمن، أن عطاء الخراسإني حدثه أن نافعا حدثه به.","grade":"حسن","chapter_ar":"باب ماجاء في النهي عن بيع العينة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3462) and al-Bayhaqi in al-Kubra (5/316).","chapter_en":"What has been reported regarding the prohibition of the ‘inah sale","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":61,"content":{"translation":{"en":["Ibn Umar said: I heard the Messenger of Allah ﷺ, say: “When you deal by ‘inah, hold onto the tails of cattle, become content with farming, and abandon jihad, Allah will place humiliation upon you, and He will not remove it until you return to your religion.”"]},"buhuth":{"en":["‘Inah — with the letter ‘ayn pronounced with kasrah — is when someone sells an item to another for a deferred price and delivers it to the buyer, then buys it back before receiving the deferred payment for a lower price, taking that lower price in cash.","But if three parties are involved, then it is no longer the ‘inah sale. Its form is that a man buys a commodity from the seller on deferred payment and takes possession of it, then sells it to a third person, other than the original seller, for less than what he bought it for, taking cash. This is permissible by agreement of the scholars because all the conditions of sale are fulfilled in it."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3462,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي في الكبرى","number":316},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":10703,"n":10793}],"full":1,"dr":1},{"num":5902,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعِ الْمَغَانِمِ حَتَّى تُقْسَمَ، وَعَنِ الْحَبَالَى أَنْ يُوطأنَ حَتَّى يَضَعْنَ مَا فِي بُطُونِهِنَّ، وَعَنْ لَحْمِ كُلِّ ذِي نَابٍ مِنَ السِّبَاعِ."],"takhrij":"حسن: رواه النسائي (4645) عن أحمد بن حفص بن عبد الله قال: حدثني أبي قال: حدثني إبراهيم، عن يحيى بن سعيد، عن عمرو بن شعيب، عن عبد الله بن أبي نجيح، عن مجاهد، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب النهي عن بيع المغانم حتى تقسم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4645), al-Daraqutni (3/68–69), and al-Hakim (2/137).","chapter_en":"The prohibition of selling war booty before it is divided","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":64,"content":{"translation":{"en":["Ibn Abbas said: The Messenger of Allah ﷺ, forbade the sale of war booty before it is divided, and forbade pregnant women from being approached sexually until they deliver what is in their wombs, and forbade the meat of every beast with fangs."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4645,"lafz":true,"n":4645},{"key":"sh9771","label":"الدار قطني","number":69},{"key":"sh9771","label":"سنن الدارقطني","number":3051,"n":3064},{"key":"hakim","label":"المستدرك على الصحيحين","number":2611,"n":2597}],"full":1,"dr":1,"rep":[6493]},{"num":5903,"demo":false,"sanad":"","matn":["عَنْ رُوَيْفِعِ بْنِ ثَابِتٍ قَالَ: أَمَا إِنِّي لاَ أَقُولُ لَكُمْ إِلاَّ مَا سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ يَوْمَ حُنَيْنٍ قَالَ: لاَ يَحِلُّ لاِمْرِئٍ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ أَنْ يَسْقِيَ مَاءَهُ زَرْعَ غَيْرِهِ. يَعْنِي إِتْيَانَ الْحَبَالَى. وَلاَ يَحِلُّ لاِمْرِئٍ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ أَنْ يَقَعَ عَلَى امْرَأَةٍ مِنَ السبي حَتَّى يَسْتَبْرِئَهَا، وَلاَ يَحِلُّ لاِمْرِئٍ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ أَنْ يَبِيعَ مَغْنَمًا حَتَّى يُقْسم."],"takhrij":"حسن: رواه أبو داود (2158، 2708)، وأحمد (16997)، والدارمي (2520) كلهم من حديث ابن إسحاق قال: حدثني يزيد بن أبي حبيب، عن أبي مرزوق مولى تجيب، عن حنش الصنعاني، عن رويفع بن ثابت فذكره.","grade":"حسن","chapter_ar":"باب النهي عن بيع المغانم حتى تقسم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2158, 2708), Ahmad (16997), and al-Darimi (2520).","chapter_en":"The prohibition of selling war booty before it is divided","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":64,"content":{"translation":{"en":["Ruwayfi‘ ibn Thabit said: I will only tell you what I heard the Messenger of Allah ﷺ, say on the day of Hunayn. He said: “It is not lawful for a man who believes in Allah and the Last Day to pour his water upon the crop of another,” meaning intercourse with pregnant captive women. “And it is not lawful for a man who believes in Allah and the Last Day to have relations with a captive woman until she is cleared by waiting, and it is not lawful for a man who believes in Allah and the Last Day to sell war booty until it has been divided.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2708,"lafz":true},{"key":"darimi","label":"الدارمي","number":2520},{"key":"ahmad","label":"مسند الإمام أحمد","number":16997,"n":16997},{"key":"abudawud","label":"ابو داود","number":2158}],"full":1,"dr":1},{"num":5904,"demo":false,"sanad":"","matn":["عَنْ أَبِي أَيُّوبَ، قَالَ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ مَنْ فَرَّقَ بَيْنَ الْوَالِدَةِ وَوَلَدِهَا فَرَّقَ اللَّهُ بَيْنَهُ وَبَيْنَ أَحِبَّتِهِ يَوْمَ الْقِيَامَةِ."],"takhrij":"حسن: رواه الترمذي (1283)، والدارقطني (3/67)، والحاكم (2/55)، والبيهقي (9/126)، وأحمد (23499)، كلهم من طريق عبدالله بن وهب قال: أخبرني حيي بن عبدالله، عن أبي عبدالرحمن الحبلي، عن أبي أيوب فذكره. وعند أحمد قصة.","grade":"حسن","chapter_ar":"باب كراهية التفريق بين الوالدة وولدها الصغير وبين الأخوين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1283), who graded it hasan, al-Daraqutni (3/67), al-Hakim (2/55), and Ahmad (23499).","chapter_en":"The dislike of separating a mother from her young child and separating two siblings","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":66,"content":{"translation":{"en":["Abu Ayyub said: I heard the Messenger of Allah ﷺ, say: “Whoever separates a mother from her child, Allah will separate him from his loved ones on the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1283,"lafz":true},{"key":"sh9771","label":"الدار قطني","number":67},{"key":"hakim","label":"الحاكم","number":55},{"key":"sh9771","label":"سنن الدارقطني","number":3047,"n":3060},{"key":"ahmad","label":"مسند الإمام أحمد","number":23499,"n":23499}],"full":1,"dr":1},{"num":5905,"demo":false,"sanad":"","matn":["عَنْ علي بن أَبِي طَالِبٍ قَالَ: قدمَ عَلَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سبيٌ، فَأَمَرَنِي بِبَيْعِ أَخَوَيْنِ، فَبِعْتُهُمَا، وفَرَّقْتُ بَيْنَهُمَا، ثُمَّ أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَأَخْبَرْتُهُ فَقَالَ: أَدْرِكْهُمَا، فَارْتَجِعْهُمَا، وبِعْهُما جَمِيعًا، وَلَا تفرِّقْ بَيْنَهُمَا."],"takhrij":"حسن: رواه الدارقطني (3040)، و الحاكم (2/54)، والبيهقي (9/127) كلهم من طرق عن عبد الوهاب بن عطاء الخفاف، عن شعبة بن الحجاج، عن الحكم بن عتيبة، عن عبد الرحمن بن أبي ليلى، عن علي بن أبي طالب قال: فذكره. وإسناده حسن من أجل عبدالوهاب بن عطاء الخفاف فإنه حسن الحديث إذا لم يأت بما ينكر عليه.","grade":"حسن","chapter_ar":"باب كراهية التفريق بين الوالدة وولدها الصغير وبين الأخوين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Daraqutni (3040), al-Hakim (2/54), and al-Bayhaqi (9/127).","chapter_en":"The dislike of separating a mother from her young child and separating two siblings","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":66,"content":{"translation":{"en":["Ali ibn Abi Talib said: Some captives were brought to the Prophet ﷺ, and he ordered me to sell two brothers. So I sold them and separated them. Then I came to the Prophet and informed him, and he said: “Catch up with them, take them back, sell them together, and do not separate them.”"]}},"tuhfa":{},"refs":[{"key":"sh9771","label":"الدار قطني","number":3040,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":127},{"key":"hakim","label":"المستدرك على الصحيحين","number":2331,"n":2322}],"full":1,"dr":1},{"num":5906,"demo":false,"sanad":"","matn":["بْنُ سَلَمَةَ، حَدَّثَنِي أَبِي قَالَ، غَزَوْنَا فَزَارَةَ وَعَلَيْنَا أَبُو بَكْرٍ أَمَّرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَيْنَا فَلَمَّا كَانَ بَيْنَنَا وَبَيْنَ الْمَاءِ سَاعَةٌ أَمَرَنَا أَبُو بَكْرٍ فَعَرَّسْنَا ثُمَّ شَنَّ الْغَارَةَ فَوَرَدَ الْمَاءَ فَقَتَلَ مَنْ قَتَلَ عَلَيْهِ وَسَبَى وَأَنْظُرُ إِلَى عُنُقٍ مِنَ النَّاسِ فِيهِمُ الذَّرَارِيُّ فَخَشِيتُ أَنْ يَسْبِقُونِي إِلَى الْجَبَلِ فَرَمَيْتُ بِسَهْمٍ بَيْنَهُمْ وَبَيْنَ الْجَبَلِ فَلَمَّا رَأَوُا السَّهْمَ وَقَفُوا فَجِئْتُ بِهِمْ أَسُوقُهُمْ وَفِيهِمُ امْرَأَةٌ مِنْ بَنِي فَزَارَةَ عَلَيْهَا قِشْعٌ مِنْ أَدَمٍ - قَالَ الْقِشْعُ النِّطَعُ - مَعَهَا ابْنَةٌ لَهَا مِنْ أَحْسَنِ الْعَرَبِ فَسُقْتُهُمْ حَتَّى أَتَيْتُ بِهِمْ أَبَا بَكْرٍ فَنَفَّلَنِي أَبُو بَكْرٍ ابْنَتَهَا فَقَدِمْنَا الْمَدِينَةَ وَمَا كَشَفْتُ لَهَا ثَوْبًا فَلَقِيَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي السُّوقِ فَقَالَ يَا سَلَمَةُ هَبْ لِي الْمَرْأَةَ. فَقُلْتُ يَا رَسُولَ اللَّهِ وَاللَّهِ لَقَدْ أَعْجَبَتْنِي وَمَا كَشَفْتُ لَهَا ثَوْبًا ثُمَّ لَقِيَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْغَدِ فِي السُّوقِ فَقَالَ لِي يَا سَلَمَةُ هَبْ لِي الْمَرْأَةَ لِلَّهِ أَبُوكَ. فَقُلْتُ هِيَ لَكَ يَا رَسُولَ اللَّهِ فَوَاللَّهِ مَا كَشَفْتُ لَهَا ثَوْبًا فَبَعَثَ بِهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى أَهْلِ مَكَّةَ فَفَدَى بِهَا نَاسًا مِنَ الْمُسْلِمِينَ كَانُوا أُسِرُوا بِمَكَّةَ."],"takhrij":"صحيح: رواه مسلم في الجهاد (1755) عن زهير بن حرب، حـدثنا عمر بن يونس، حدثنا عكرمة بن عمار، حدثني إياس بن سلمة، حدثني أبى (سلمة بن الأكوع ) قال فذكره.","grade":"صحيح","chapter_ar":"باب جواز التفريق بين الوالدة وولدها الكبير في البيع والهبة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1755).","chapter_en":"The permissibility of separating a mother from her grown child in sale and gift","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":67,"content":{"translation":{"en":["Salamah ibn al-Akwa‘ said: We fought against Fazarah with Abu Bakr over us, appointed over us by the Messenger of Allah, ﷺ. When there remained about an hour between us and the water, Abu Bakr ordered us, so we halted in the latter part of the night. Then he launched the raid, and we reached the water. Some were killed there, and some were taken captive. I saw a group of people among whom were children, and I feared they would reach the mountain before me, so I shot an arrow between them and the mountain. When they saw the arrow, they stopped. I came to them driving them along, and among them was a woman from Banu Fazarah wearing a leather covering — he said: al-qash‘ means a leather sheet — and with her was a daughter of hers who was among the most beautiful of the Arabs. I drove them until I brought them to Abu Bakr, and Abu Bakr gave me her daughter as an extra share. We then came to Madinah, and I had not had intercourse with her. Then the Messenger of Allah ﷺ, met me in the marketplace and said: “O Salamah, give me the woman.” I said: O Messenger of Allah ﷺ, by Allah, she pleased me, and I have not had intercourse with her. Then the Messenger of Allah ﷺ met me the next day in the market and said to me: “O Salamah, give me the woman. May your father be honored.” So I said: She is yours, O Messenger of Allah ﷺ. By Allah, I had not had intercourse with her. Then the Messenger of Allah ﷺ sent her to the people of Makkah, and by her he ransomed some Muslims who had been captured in Makkah."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1755,"lafz":true}],"full":1,"dr":1,"rep":[8006,9086]},{"num":5907,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيمَا رَوَى عَنِ اللَّهِ، تَبَارَكَ وَتَعَالَى أَنَّهُ قَالَ يَا عِبَادِي إِنِّي حَرَّمْتُ الظُّلْمَ عَلَى نَفْسِي وَجَعَلْتُهُ بَيْنَكُمْ مُحَرَّمًا فَلاَ تَظَالَمُوا يَا عِبَادِي كُلُّكُمْ ضَالٌّ إِلاَّ مَنْ هَدَيْتُهُ فَاسْتَهْدُونِي أَهْدِكُمْ يَا عِبَادِي كُلُّكُمْ جَائِعٌ إِلاَّ مَنْ أَطْعَمْتُهُ فَاسْتَطْعِمُونِي أُطْعِمْكُمْ يَا عِبَادِي كُلُّكُمْ عَارٍ إِلاَّ مَنْ كَسَوْتُهُ فَاسْتَكْسُونِي أَكْسُكُمْ يَا عِبَادِي إِنَّكُمْ تُخْطِئُونَ بِاللَّيْلِ وَالنَّهَارِ وَأَنَا أَغْفِرُ الذُّنُوبَ جَمِيعًا فَاسْتَغْفِرُونِي أَغْفِرْ لَكُمْ يَا عِبَادِي إِنَّكُمْ لَنْ تَبْلُغُوا ضَرِّي فَتَضُرُّونِي وَلَنْ تَبْلُغُوا نَفْعِي فَتَنْفَعُونِي يَا عِبَادِي لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ كَانُوا عَلَى أَتْقَى قَلْبِ رَجُلٍ وَاحِدٍ مِنْكُمْ مَا زَادَ ذَلِكَ فِي مُلْكِي شَيْئًا يَا عِبَادِي لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ كَانُوا عَلَى أَفْجَرِ قَلْبِ رَجُلٍ وَاحِدٍ مَا نَقَصَ ذَلِكَ مِنْ مُلْكِي شَيْئًا يَا عِبَادِي لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ قَامُوا فِي صَعِيدٍ وَاحِدٍ فَسَأَلُونِي فَأَعْطَيْتُ كُلَّ إِنْسَانٍ مَسْأَلَتَهُ مَا نَقَصَ ذَلِكَ مِمَّا عِنْدِي إِلاَّ كَمَا يَنْقُصُ الْمِخْيَطُ إِذَا أُدْخِلَ الْبَحْرَ يَا عِبَادِي إِنَّمَا هِيَ أَعْمَالُكُمْ أُحْصِيهَا لَكُمْ ثُمَّ أُوَفِّيكُمْ إِيَّاهَا فَمَنْ وَجَدَ خَيْرًا فَلْيَحْمَدِ اللَّهَ وَمَنْ وَجَدَ غَيْرَ ذَلِكَ فَلاَ يَلُومَنَّ إِلاَّ نَفْسَهُ.","قال سعيد: كان أبو إدريس الخولاني إذا حدث بهذا الحديث جثا على ركبتيه."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2577) عن عبد الله بن عبد الرحمن بن بهرام الدارمي، حدثنا مروان (يعني ابن محمد الدمشقي)، حدثنا سعيد بن عبد العزيز، عن ربيعة بن يزيد، عن أبى إدريس الخولاني، عن أبي ذر فذكره.","grade":"صحيح","chapter_ar":"باب ماجاء في تحريم الظلم، وإن الله حرم الظلم على نفسه.","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2577).","chapter_en":"What has been reported concerning the prohibition of injustice, and that Allah has forbidden injustice for Himself","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abū Dharr reported from the Prophet ﷺ concerning what he narrated from Allah, Blessed and Exalted, that He said: “O My servants, I have forbidden injustice for Myself and have made it forbidden among you, so do not wrong one another. O My servants, all of you are astray except those whom I guide, so ask Me for guidance and I will guide you. O My servants, all of you are hungry except those whom I feed, so ask Me for food and I will feed you. O My servants, all of you are unclothed except those whom I clothe, so ask Me for clothing and I will clothe you. O My servants, you commit sins by night and by day, and I forgive all sins, so seek My forgiveness and I will forgive you. O My servants, you can never attain the ability to harm Me so as to harm Me, nor can you attain the ability to benefit Me so as to benefit Me. O My servants, if the first of you and the last of you, the human beings among you and the jinn among you, were all as righteous as the most righteous heart of one man among you, that would not increase My dominion in the least. O My servants, if the first of you and the last of you, the human beings among you and the jinn among you, were all as wicked as the most wicked heart of one man among you, that would not diminish My dominion in the least. O My servants, if the first of you and the last of you, the human beings among you and the jinn among you, all stood together on one plain and asked of Me, and I gave every person what he asked for, that would diminish what I possess no more than a needle diminishes the sea when it is dipped into it. O My servants, they are only your deeds. I record them for you and then repay you for them in full. Whoever finds good, let him praise Allah, and whoever finds other than that, let him blame no one but himself.” Saʿīd said: Whenever Abū Idrīs al-Khawlānī narrated this hadith, he would kneel down."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2577,"lafz":true}],"full":1,"rep":[14894]},{"num":5908,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إن الظُّلْمُ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ."],"takhrij":"متفق عليه: رواه البخاري في المظالم (2447)، ومسلم في البر والصلة (2579) كلاهما من حديث عبد العزيز بن الماجشون، عن عبد الله بن دينار، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب الظلم ظلمات يوم القيامة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2447) and Muslim (2579).","chapter_en":"Injustice will be darknesses on the Day of Resurrection","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Abdullah ibn Umar said: The Messenger of Allah ﷺ said: “Indeed, injustice will be darknesses on the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2447,"lafz":true,"n":2562},{"key":"muslim","label":"مسلم","number":2579}],"full":1},{"num":5909,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ اتَّقُوا الظُّلْمَ فَإِنَّ الظُّلْمَ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ وَاتَّقُوا الشُّحَّ فَإِنَّ الشُّحَّ أَهْلَكَ مَنْ كَانَ قَبْلَكُمْ حَمَلَهُمْ عَلَى أَنْ سَفَكُوا دِمَاءَهُمْ وَاسْتَحَلُّوا مَحَارِمَهُمْ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2578) عن عبدالله بن مسلمة بن قعنب، حدثنا داود (يعنى ابن قيس)، عن عبيدالله بن مقسم، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب الظلم ظلمات يوم القيامة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2578).","chapter_en":"Injustice will be darknesses on the Day of Resurrection","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Jabir reported that the Messenger of Allah ﷺ said: “Beware of injustice, for injustice will be darknesses on the Day of Resurrection. And beware of greed, for greed destroyed those before you. It drove them to shed their blood and make lawful their sacred things.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2578,"lafz":true}],"full":1,"rep":[12734,13524,14895,14991]},{"num":5910,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِيَّاكُمْ وَالظُّلْمَ، فَإِنَّ الظُّلْمَ ظُلُمَاتٌ عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ، وَإِيَّاكُمْ وَالْفُحْشَ، فَإِنَّ اللَّهَ لَا يُحِبُّ الْفُحْشَ وَالتَّفَحُّشَ، وَإِيَّاكُمْ وَالشُّحَّ، فَإِنَّهُ دَعَا مَنْ قَبْلَكُمْ فَاسْتَحَلُّوا مَحَارِمَهُمْ، وَسَفَكُوا دِمَاءَهُمْ، وَقَطَّعُوا أَرْحَامَهُمْ."],"takhrij":"حسن: رواه أحمد (9570)، وصحّحه ابن حبان (6248)، والحاكم (1/12) كلهم من طريق محمد بن عجلان، عن سعيد بن أبي سعيد المقبري، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب الظلم ظلمات يوم القيامة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (9569, 9570), authenticated by Ibn Hibban (6248), and al-Hakim (1/12).","chapter_en":"Injustice will be darknesses on the Day of Resurrection","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Beware of injustice, for injustice will be darknesses before Allah on the Day of Resurrection. Beware of obscenity, for Allah does not love obscenity and shamelessness. And beware of greed, for it led those before you to make sacred things lawful, shed blood, and cut off family ties.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"صحّحه ابن حبان","number":6248},{"key":"hakim","label":"الحاكم","number":12},{"key":"ahmad","label":"مسند الإمام أحمد","number":9569,"n":9569},{"key":"ahmad","label":"احمد","number":9570,"lafz":true,"n":9569}],"full":1,"dr":1},{"num":5911,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: إِيَّاكُمْ وَالظُّلْمَ فَإِنَّ الظُّلْمَ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ، وَإِيَّاكُمْ وَالْفُحْشَ، فَإِنَّ اللَّهَ لَا يُحِبُّ الْفُحْشَ، وَلَا التَّفَحُّشَ، وَإِيَّاكُمْ وَالشُّحَّ، فَإِنَّمَا أَهْلَكَ مَنْ كَانَ قَبْلَكُمُ الشُّحُّ، أَمَرَهُمْ بِالْقَطِيعَةِ فَقَطَعُوا أَرْحَامَهُمْ، وَأَمَرَهُمْ بِالْفُجُورِ فَفَجَرُوا، وَأَمَرَهُمْ بِالْبُخْلِ فَبَخِلُوا، فَقَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، فَأَيُّ الإِسْلَامِ أَفْضَلُ؟ قَالَ: أَنْ يَسْلَمَ الْمُسْلِمُونَ مِنْ لِسَانِكَ وَيَدِكَ، قَالَ: يَا رَسُولَ اللَّهِ، فَأَيُّ الْهِجْرَةِ أَفْضَلُ؟ قَالَ: أَنْ تَهْجُرَ مَا كَرِهَ رَبُّكَ، قَالَ: وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْهِجْرَةُ هِجْرَتَانِ، هِجْرَةُ الْحَاضِرِ، وَهِجْرَةُ الْبَادِي، أَمَّا الْبَادِي، فَيُجِيبُ إِذَا دُعِيَ، وَيُطِيعُ إِذَا أُمِرَ، وَأَمَّا الْحَاضِرُ، فَهُوَ أَعْظَمُهُمَا بَلِيَّةً، وَأَعْظَمُهُمَا أَجْرًا."],"takhrij":"صحيح: رواه أحمد (6837)، وصحّحه ابن حبان (5176)، والحاكم (1/11) كلهم من حديث شعبة، عن عمرو بن مرة، عن عبد الله بن الحارث، عن أبي كثير الزبيدي، عن عبدالله بن عمرو فذكره.","grade":"صحيح","chapter_ar":"باب الظلم ظلمات يوم القيامة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (6837), authenticated by Ibn Hibban (5176), and al-Hakim (1/11).","chapter_en":"Injustice will be darknesses on the Day of Resurrection","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Abdullah ibn Amr reported that the Messenger of Allah ﷺ said: “Beware of injustice, for injustice will be darknesses on the Day of Resurrection. Beware of obscenity, for Allah does not love obscenity or shameless conduct. Beware of greed, for greed is what destroyed those before you. It commanded them to sever ties, so they severed their family ties. It commanded them to commit immorality, so they committed immorality. It commanded them to be miserly, so they became miserly.” Then a man said: O Messenger of Allah ﷺ, which form of Islam is best? He said: “That the Muslims are safe from your tongue and your hand.” He said: O Messenger of Allah ﷺ, then which migration is best? He said: “That you abandon what your Lord dislikes.” And the Messenger of Allah ﷺ said: “Migration is of two kinds: the migration of the town-dweller and the migration of the desert-dweller. As for the desert-dweller, he responds when called and obeys when commanded. As for the town-dweller, his trial is greater of the two, and his reward is greater of the two.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"صحّحه ابن حبان","number":5176,"lafz":true},{"key":"hakim","label":"الحاكم","number":11},{"key":"ahmad","label":"مسند الإمام أحمد","number":6837,"n":6837},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1968,"n":1965}],"full":1,"dr":1},{"num":5912,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ مُعَاذًا إِلَى الْيَمَنِ، فَقَالَ اتَّقِ دَعْوَةَ الْمَظْلُومِ، فَإِنَّهَا لَيْسَ بَيْنَهَا وَبَيْنَ اللَّهِ حِجَابٌ."],"takhrij":"متفق عليه: رواه البخاري في المظالم (2448)، ومسلم في الإيمان (19) كلاهما من حديث وكيع، حدثنا زكريا بن إسحاق المكي، عن يحيى بن عبدالله ابن صيفي، عن أبي معبد مولى ابن عباس، عن ابن عباس فذكره. هكذا ذكره البخاري مختصرا، وسبق ذكره في كتاب الإيمان مفصلا.","grade":"متفق عليه","chapter_ar":"باب الاتقاء من دعوة المظلوم","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2448) and Muslim (19).","chapter_en":"Guarding oneself against the supplication of the one who has been wronged","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Abdullah ibn Abbas reported that the Prophet ﷺ sent Muadh to Yemen and said: “Beware of the supplication of the one who has been wronged, for there is no barrier between it and Allah.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2448,"lafz":true},{"key":"muslim","label":"مسلم","number":19}],"full":1,"rep":[10944]},{"num":5913,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ زَيْدٍ بن نُفَيْلٍ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ أَخَذَ شِبْرًا مِنَ الأَرْضِ ظُلْمًا طُوِّقَهُ إِلَى سَبْعِ أَرَضِينَ."],"takhrij":"متفق عليه: رواه البخاري في بدء الخلق (3198)، ومسلم في المساقاة (1610: 139) كلاهما من حديث هشام بن عروة، عن أبيه أن أروى بنت أويس ادعت على سعيد بن زيد أنه أخذ شيئا من أرضها، فخاصمته إلى مروان بن الحكم، فقال سعيد: أنا كنت آخذ من أرضها شيئا بعد الذي سمعت من رسول الله صلى الله عليه وسلم . قال: وما سمعت من رسول الله صلى الله عليه وسلم ؟ قال: سمعت رسول الله صلى الله عليه وسلم  يقول فذكر الحديث. فقال له مروان: لا أسألك بينة بعد هذا. فقال: اللهم إن كانت كاذبة فعم بصرها واقتلها في أرضها. قال: فما ماتت حتى ذهب بصرها، ثم بينا هي تمشى في أرضها إذ وقعت في حفرة فماتت.","grade":"متفق عليه","chapter_ar":"باب إثم من ظلم شيئا من الأرض","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3198) and Muslim (1610:139).","chapter_en":"The sin of one who wrongfully takes any part of land","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Sa‘id ibn Zayd ibn Nufayl said: I heard the Messenger of Allah ﷺ say: “Whoever takes a handspan of land wrongfully will be encircled with it down to seven earths.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3198,"lafz":true},{"key":"muslim","label":"مسلم","number":139},{"key":"muslim","label":"مسلم في المساقاه","number":1610,"n":4134}],"full":1,"dr":1},{"num":5914,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ يَأْخُذُ أَحَدٌ شِبْرًا مِنَ الأَرْضِ بِغَيْرِ حَقِّهِ إِلاَّ طَوَّقَهُ اللَّهُ إِلَى سَبْعِ أَرَضِينَ يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1611) عن زهير بن حرب، حدثنا جرير، عن سهيل، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب إثم من ظلم شيئا من الأرض","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1611).","chapter_en":"The sin of one who wrongfully takes any part of land","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “No one takes a handspan of land without right except that Allah will encircle him with it down to seven earths on the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1611,"lafz":true}],"full":1,"rep":[8205]},{"num":5915,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : مَنْ ظَلَمَ قِيدَ شِبْرٍ مِنَ الأَرْضِ طُوِّقَهُ مِنْ سَبْعِ أَرَضِينَ."],"takhrij":"متفق عليه: رواه البخاري في المظالم (2453)، ومسلم في المساقاة (1612) كلاهما من حديث يحيى بن أبي كثير قال: حدثني محمد بن إبراهيم، أن أبا سلمة حدثه: أنه كانت بينه وبين أناس خصومة، فذكر ذلك لعائشة، فقالت: يا أبا سلمة، اجتنب الأرض؛ فإن النبي صلى الله عليه وسلم  قال فذكرت الحديث.","grade":"متفق عليه","chapter_ar":"باب إثم من ظلم شيئا من الأرض","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2453) and Muslim (1612).","chapter_en":"The sin of one who wrongfully takes any part of land","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["The Mother of the Believers, Aishah, said: The Messenger of Allah ﷺ said: “Whoever wrongfully takes even the measure of a handspan of land will be encircled with it from seven earths.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2453,"lafz":true},{"key":"muslim","label":"مسلم","number":1612}],"full":1},{"num":5916,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : مَنْ أَخَذَ مِنَ الأَرْضِ شَيْئًا بِغَيْرِ حَقٍّ، خُسِفَ بِهِ يَوْمَ الْقِيَامَةِ إِلَى سَبْعِ أَرَضِينَ."],"takhrij":"صحيح: رواه البخاري في المظالم (2454) عن مسلم بن إبراهيم، حدثنا عبد الله بن المبارك، حدثنا موسى بن عقبة، عن سالم، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب إثم من ظلم شيئا من الأرض","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2454).","chapter_en":"The sin of one who wrongfully takes any part of land","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Ibn Umar said: The Prophet ﷺ said: “Whoever takes anything from land without right will be sunk with it on the Day of Resurrection down to seven earths.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2454,"lafz":true}],"full":1,"dr":1},{"num":5917,"demo":false,"sanad":"","matn":["عن يَعْلَى بْنِ مرة الثقفي يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ أَخَذَ أَرْضًا بِغَيْرِ حَقٍّ، كُلِّفَ أَنْ يَحْمِلَ تُرَابَهَا إِلَى الْمَحْشَرِ."],"takhrij":"حسن: رواه أحمد (17558) عن إسماعيل بن محمد (وهو أبو إبراهيم المعقب)، حدثنا مروان يعني الفزاري، حدثنا أبو يعفور، عن أبي ثابت قال: سمعت يعلى بن مرة فذكره.","grade":"حسن","chapter_ar":"باب إثم من ظلم شيئا من الأرض","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (17558).","chapter_en":"The sin of one who wrongfully takes any part of land","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Ya‘la ibn Murrah al-Thaqafi said: I heard the Messenger of Allah ﷺ say: “Whoever takes land without right will be burdened with carrying its soil to the place of gathering.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":17558,"n":17558,"lafz":true}],"full":1,"dr":1},{"num":5918,"demo":false,"sanad":"","matn":["عَنْ أَبِي الطُّفَيْلِ، قَالَ قُلْنَا لِعَلِيِّ بْنِ أَبِي طَالِبٍ أَخْبِرْنَا بِشَىْءٍ، أَسَرَّهُ إِلَيْكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ مَا أَسَرَّ إِلَىَّ شَيْئًا كَتَمَهُ النَّاسَ وَلَكِنِّي سَمِعْتُهُ يَقُولُ لَعَنَ اللَّهُ مَنْ ذَبَحَ لِغَيْرِ اللَّهِ وَلَعَنَ اللَّهُ مَنْ آوَى مُحْدِثًا وَلَعَنَ اللَّهُ مَنْ لَعَنَ وَالِدَيْهِ وَلَعَنَ اللَّهُ مَنْ غَيَّرَ الْمَنَارَ."],"takhrij":"صحيح: رواه مسلم في كتاب الأضاحي (1978: 44) عن أبي بكر بن أبى شيبة، حدثنا أبو خالد الأحمر سليمان بن حيان، عن منصور بن حيان، عن أبي الطفيل فذكره.","grade":"صحيح","chapter_ar":"باب إثم من ظلم شيئا من الأرض","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1978:44).","chapter_en":"The sin of one who wrongfully takes any part of land","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abu al-Tufayl said: We said to Ali ibn Abi Talib: Tell us something the Messenger of Allah ﷺ, confided to you privately. He said: He did not confide to me anything that he concealed from the people, but I heard him say: “May Allah curse the one who sacrifices for other than Allah. May Allah curse the one who shelters an offender. May Allah curse the one who curses his parents. May Allah curse the one who changes boundary markers.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":44,"lafz":true},{"key":"muslim","label":"مسلم في كتاب الاضاحي","number":1978,"n":5125}],"full":1,"dr":1},{"num":5919,"demo":false,"sanad":"","matn":["عَنِ الْحَارِثِ بْنِ الْبَرْصَاءِ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَمْشِي بَيْنَ جَمْرَتَيْنِ مِنَ الْجِمَارِ يَقُولُ: مَنْ أَخَذَ شِبْرًا مِنْ مَالِ امْرِئٍ مُسْلِمٍ بِيَمِينٍ فَاجِرَةٍ، فَلْيَتَبَوَّأْ بَيْتًا مِنَ النَّارِ."],"takhrij":"صحيح: رواه ابن حبان في صحيحه (5165) عن محمد بن الحسين بن مكرم قال: حدثنا عمرو بن علي الفلاس قال: حدثنا عمر بن عبدالوهاب الرياحي قال: حدثنا يزيد بن زريع، حدثنا روح بن القاسم، عـن إسماعيل بن أمية، عن عمر بن عطاء، عن عبيد بن جريج، عن الحارث بن البرصاء فذكره.","grade":"صحيح","chapter_ar":"باب إثم من ظلم شيئا من الأرض","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Hibban in his Sahih (5165).","chapter_en":"The sin of one who wrongfully takes any part of land","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Al-Harith ibn al-Barsa’ said: I heard the Messenger of Allah ﷺ, while walking between two of the Jamarat, saying: “Whoever takes a handspan of a Muslim man’s property by a sinful oath, let him prepare for himself a house in the Fire.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"ابن حبان في صحيحه","number":5165,"lafz":true},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2825,"n":2822}],"full":1,"dr":1,"rep":[7073]},{"num":5920,"demo":false,"sanad":"","matn":["عَنْ وَائِلِ بْنِ حُجْرٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : مَنْ غَصَبَ رَجُلًا أَرْضًا ظُلْمًا، لقيَ اللَّهَ وَهُوَ عَلَيْهِ غَضْبَانُ."],"takhrij":"حسن: رواه الطبراني في الكبير (22/18) عن طالب بن قرة الأدني، حدثنا محمد بن عيسى الطبّاع- وعن الحسين بن إسحاق التستري، حدثنا يحيى الحماني- كلاهما (محمد بن عيسى الطباع ويحيى الحماني)، عن أبي عوانة، عن عبدالملك بن عمير، عن علقمة بن وائل، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب إثم من ظلم شيئا من الأرض","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (22/18).","chapter_en":"The sin of one who wrongfully takes any part of land","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Wa’il ibn Hujr said: The Messenger of Allah ﷺ said: “Whoever usurps a man’s land unjustly will meet Allah while He is angry with him.”"]},"buhuth":{"en":["Understanding of the hadith:","Each person’s reckoning will be according to his crime. Some will be encircled with the like of what they took from the land, some will be made to carry its soil to the gathering place, some will be punished by entering the Fire, and some will be punished by Allah’s anger against them. The Prophet ﷺ explained these different forms of punishment at different times."]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":18,"lafz":true}],"full":1,"dr":1},{"num":5921,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوَّلُ مَا يُقْضَى بَيْنَ النَّاسِ بِالدِّمَاءِ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6533)، ومسلم في القسامة (1678) كلاهما من حديث الأعمش، حدثني شقيق، قال: سمعت عبد الله فذكره.","grade":"متفق عليه","chapter_ar":"باب قصاص المظالم يوم القيامة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6533) and Muslim (1678).","chapter_en":"Retribution for injustices on the Day of Resurrection","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abdullah ibn Mas‘ud said: The Prophet ﷺ said: “The first matter to be judged among the people will be bloodshed.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6533,"lafz":true},{"key":"muslim","label":"مسلم","number":1678}],"full":1},{"num":5922,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِذَا خَلَصَ الْمُؤْمِنُونَ مِنَ النَّارِ حُبِسُوا بِقَنْطَرَةٍ بَيْنَ الْجَنَّةِ وَالنَّارِ، فَيَتَقَاصُّونَ مَظَالِمَ كَانَتْ بَيْنَهُمْ فِي الدُّنْيَا، حَتَّى إِذَا نُقُّوا وَهُذِّبُوا أُذِنَ لَهُمْ بِدُخُولِ الْجَنَّةِ، فَوَالَّذِي نَفْسُ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ لأَحَدُهُمْ بِمَسْكَنِهِ فِي الْجَنَّةِ أَدَلُّ بِمَنْزِلِهِ كَانَ فِي الدُّنْيَا."],"takhrij":"صحيح: رواه البخاري في المظالم (2440) عن إسحاق بن إبراهيم، أخبرنا معاذ بن هشام، حدثني أبي، عن قتادة، عن أبي المتوكل الناجي، عن أبي سعيد الخدري فذكره.","grade":"صحيح","chapter_ar":"باب قصاص المظالم يوم القيامة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2440).","chapter_en":"Retribution for injustices on the Day of Resurrection","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abu Sa‘id al-Khudri reported that the Messenger of Allah ﷺ said: “When the believers are delivered from the Fire, they will be stopped at a bridge between Paradise and the Fire, and they will settle the injustices that existed among them in the world. When they have been purified and refined, permission will be given to them to enter Paradise. By the One in whose hand is the soul of Muhammad, one of them will know his dwelling in Paradise better than he knew his home in the world.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2440,"lafz":true}],"full":1},{"num":5923,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ كَانَتْ لَهُ مَظْلَمَةٌ لأَحَدٍ مِنْ عِرْضِهِ أَوْ شَىْءٍ فَلْيَتَحَلَّلْهُ مِنْهُ الْيَوْمَ، قَبْلَ أَنْ لاَ يَكُونَ دِينَارٌ وَلاَ دِرْهَمٌ، إِنْ كَانَ لَهُ عَمَلٌ صَالِحٌ أُخِذَ مِنْهُ بِقَدْرِ مَظْلَمَتِهِ، وَإِنْ لَمْ تَكُنْ لَهُ حَسَنَاتٌ أُخِذَ مِنْ سَيِّئَاتِ صَاحِبِهِ فَحُمِلَ عَلَيْهِ."],"takhrij":"صحيح: رواه البخاري في المظالم (2449) عن آدم بن أبي إياس، حدثنا ابن أبي ذئب، حدثنا سعيد المقبري، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ماجاء في أخذ حسنات الظالم، وإعطائها للمظلوم يوم القيامة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2449).","chapter_en":"What has been reported about taking the oppressor’s good deeds and giving them to the oppressed on the Day of Resurrection","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Whoever has wronged someone with regard to his honor or anything else should seek his pardon today, before there will be neither dinar nor dirham. If he has righteous deeds, some of them will be taken from him according to the measure of his wrong. If he has no good deeds, sins from the wronged person will be taken and loaded upon him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2449,"lafz":true}],"full":1,"dr":1},{"num":5924,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ أَتَدْرُونَ مَا الْمُفْلِسُ. قَالُوا الْمُفْلِسُ فِينَا مَنْ لاَ دِرْهَمَ لَهُ وَلاَ مَتَاعَ. فَقَالَ إِنَّ الْمُفْلِسَ مِنْ أُمَّتِي يَأْتِي يَوْمَ الْقِيَامَةِ بِصَلاَةٍ وَصِيَامٍ وَزَكَاةٍ وَيَأْتِي قَدْ شَتَمَ هَذَا وَقَذَفَ هَذَا وَأَكَلَ مَالَ هَذَا وَسَفَكَ دَمَ هَذَا وَضَرَبَ هَذَا فَيُعْطَى هَذَا مِنْ حَسَنَاتِهِ وَهَذَا مِنْ حَسَنَاتِهِ فَإِنْ فَنِيَتْ حَسَنَاتُهُ قَبْلَ أَنْ يُقْضَى مَا عَلَيْهِ أُخِذَ مِنْ خَطَايَاهُمْ فَطُرِحَتْ عَلَيْهِ ثُمَّ طُرِحَ فِي النَّارِ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2581) من طرق عن إسماعيل بن جعفر، عن العلاء، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ماجاء في أخذ حسنات الظالم، وإعطائها للمظلوم يوم القيامة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2581).","chapter_en":"What has been reported about taking the oppressor’s good deeds and giving them to the oppressed on the Day of Resurrection","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Do you know who the bankrupt one is?” They said: The bankrupt among us is the one who has neither money nor goods. He said: “The bankrupt one from my nation is the one who comes on the Day of Resurrection with prayer, fasting, and zakah, but he comes having insulted this one, slandered this one, consumed the wealth of this one, shed the blood of this one, and struck this one. So this one will be given from his good deeds, and that one will be given from his good deeds. If his good deeds run out before what he owes is settled, some of their sins will be taken and cast upon him, then he will be thrown into the Fire.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2581,"lafz":true}],"full":1,"rep":[12735,12981,14897,16221]},{"num":5925,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَتُؤَدُّنَّ الْحُقُوقَ إِلَى أَهْلِهَا يَوْمَ الْقِيَامَةِ حَتَّى يُقَادَ لِلشَّاةِ الْجَلْحَاءِ مِنَ الشَّاةِ الْقَرْنَاءِ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2582) من طرق عن إسماعيل (ابن جعفر)، عن العلاء، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ماجاء في أخذ حسنات الظالم، وإعطائها للمظلوم يوم القيامة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2582).","chapter_en":"What has been reported about taking the oppressor’s good deeds and giving them to the oppressed on the Day of Resurrection","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Rights will surely be returned to their owners on the Day of Resurrection, until retaliation will be taken for the hornless sheep against the horned sheep.”"]},"buhuth":{"en":["The hornless sheep is the one with no horns. The retaliation between the horned and hornless sheep is not a matter of moral accountability, because animals are not legally accountable; rather, it is a form of exact compensation. It clearly shows that animals will be gathered on the Day of Resurrection, and this is indicated by the verse: “And when the wild beasts are gathered.” [Surat al-Takwir: 5]","But the scholars said that being gathered on the Day of Resurrection does not necessarily mean reward, punishment, or moral accountability. Al-Nawawi mentioned this briefly. It also shows Allah’s power: if He gathers animals on the Day of Resurrection, even though they are not morally accountable, then how could He not gather human beings?"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2582,"lafz":true}],"full":1,"dr":1,"rep":[16226]},{"num":5926,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ الشَّيْطَانَ قَدْ يَئِسَ أَنْ تُعْبَدَ الْأَصْنَامُ فِي أَرْضِ الْعَرَبِ، وَلَكِنَّهُ سَيَرْضَى مِنْكُمْ بِدُونِ ذَلِكَ بِالْمُحَقِّرَاتِ، وَهِيَ: الْمُوبِقَاتُ يَوْمَ الْقِيَامَةِ، اتَّقُوا الْمَظَالِمَ مَا اسْتَطَعْتُمْ، فَإِنَّ الْعَبْدَ يَجِيءُ بِالْحَسَنَاتِ يَوْمَ الْقِيَامَةِ يَرَى أَنَّهُ سَتُنْجِيهِ، فَمَا زَالَ عَبْدٌ يَقُومُ فَيَقُولُ: يَا رَبِّ ظَلَمَنِي عَبْدُكَ مَظْلَمَةً، فَيَقُولُ امْحُوا مِنْ حَسَنَاتِهِ، مَا يَزَالُ كَذَلِكَ، حَتَّى مَا يَبْقَى لَهُ حَسَنَةٌ مِنَ الذُّنُوبِ، وَإِنَّ مِثْلَ ذَلِكَ كَسَفْرٍ نَزَلُوا بِفَلَاةٍ مِنَ الْأَرْضِ، لَيْسَ مَعَهُمْ حَطَبٌ، فَتَفَرَّقَ الْقَوْمُ لِيَحْتَطِبُوا، فَلَمْ يَلْبَثُوا أَنْ حَطَبُوا، فَأَعْظَمُوا النَّارَ، وَطَبَخُوا مَا أَرَادُوا، وَكَذَلِكَ الذُّنُوبُ."],"takhrij":"حسن: رواه أبو يعلى (5122) عن محمد بن أبي بكر، عن محمد بن دينار، عن إبراهيم الهجري، عن أبي الأحوص. قال أبو يعلى: أحسبه عن ابن مسعود فذكره.","grade":"حسن","chapter_ar":"باب ماجاء في أخذ حسنات الظالم، وإعطائها للمظلوم يوم القيامة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Ya‘la (5122) and Ahmad (3818).","chapter_en":"What has been reported about taking the oppressor’s good deeds and giving them to the oppressed on the Day of Resurrection","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abdullah reported from the Prophet ﷺ that he said: “Satan has despaired of idols being worshipped in the land of the Arabs, but he will be content with lesser things from you, and they are the destructive sins on the Day of Resurrection. Avoid injustices as much as you can, for a servant will come on the Day of Resurrection with good deeds, thinking they will save him. Then one servant after another will stand and say: My Lord, Your servant wronged me. So it will be said: Wipe away from his good deeds. This will continue until not a single good deed remains for him because of those sins. The likeness of that is like travelers who stopped in a barren land with no firewood. The people dispersed to gather wood, and before long they had gathered enough, made a great fire, and cooked what they wished. That is how sins are.”"]}},"tuhfa":{},"refs":[{"key":"sh12520","label":"أبو يعلى","number":5122,"lafz":true},{"key":"ahmad","label":"الإمام أحمد","number":3818}],"full":1,"dr":1},{"num":5927,"demo":false,"sanad":"","matn":["عن أبي موسى قال: قال رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إن الله ليملي للظالم حتى إذا أخذه لم يُفْلِته. قال: ثم قرأ: ﴿وَكَذَلِكَ أَخْذُ رَبِّكَ إِذَا أَخَذَ الْقُرَى وَهِيَ ظَالِمَةٌ إِنَّ أَخْذَهُ أَلِيمٌ شَدِيدٌ﴾ [سورة هود: 102]."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4686)، ومسلم في البر والصلة (2583) كلاهما من حديث أبي معاوية، حدثنا بُريد بن أبي بردة، عن أبي بردة، عن أبي موسى قال:فذكره.","grade":"متفق عليه","chapter_ar":"باب إن الله يُملي الظالم ليرجع من ظلمه","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4686) and Muslim (2583).","chapter_en":"Allah gives respite to the wrongdoer so that he may return from his wrongdoing","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abu Musa said: The Messenger of Allah ﷺ said: “Indeed, Allah gives respite to the wrongdoer, but when He seizes him, He does not let him escape.” Then he recited: “And thus is the seizure of your Lord when He seizes the towns while they are committing wrong. Indeed, His seizure is painful and severe.” [Surat Hud: 102]"]},"intro":{"ar":["قال اللّه تعالى: (وَلَا تَحْسَبَنَّ اللَّهَ غَافِلًا عَمَّا يَعْمَلُ الظَّالِمُونَ إِنَّمَا يُؤَخِّرُهُمْ لِيَوْمٍ تَشْخَصُ فِيهِ الْأَبْصَارُ مُهْطِعِينَ مُقْنِعِي رُءُوسِهِمْ لَا يَرْتَدُّ إِلَيْهِمْ طَرْفُهُمْ وَأَفْئِدَتُهُمْ هَوَاءٌ) [سورة إبراهيم: ٤٢-٤٣]."],"en":["Allah the Exalted said: “Do not think that Allah is unaware of what the wrongdoers do. He only delays them until a Day when eyes will stare in horror, rushing forward, with heads raised up, their gaze not returning to them, and their hearts empty.” [Surat Ibrahim: 42–43]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4686,"lafz":true},{"key":"muslim","label":"مسلم","number":2583}],"full":1,"rep":[13609]},{"num":5928,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن عُمَرَ أخبر رَضِيَ اللَّهُ عَنْهُمَا أَخْبَرَهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ الْمُسْلِمُ أَخُو الْمُسْلِمِ، لاَ يَظْلِمُهُ وَلاَ يُسْلِمُهُ، وَمَنْ كَانَ فِي حَاجَةِ أَخِيهِ كَانَ اللَّهُ فِي حَاجَتِهِ، وَمَنْ فَرَّجَ عَنْ مُسْلِمٍ كُرْبَةً فَرَّجَ اللَّهُ عَنْهُ كُرْبَةً مِنْ كُرُبَاتِ يَوْمِ الْقِيَامَةِ، وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللَّهُ يَوْمَ الْقِيَامَةِ."],"takhrij":"متفق عليه: رواه البخاري في المظالم (2442)، ومسلم في البر والصلة (2580) كلاهما من حديث الليث، عن عقيل، عن ابن شهاب، أن سالما أخبره أن عبدالله بن عمر قال:فذكره.","grade":"متفق عليه","chapter_ar":"باب لا يظلم المسلم المسلم","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2442) and Muslim (2580).","chapter_en":"A Muslim does not wrong another Muslim","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Abdullah ibn Umar reported that the Messenger of Allah ﷺ said: “The Muslim is the brother of the Muslim. He does not wrong him, nor does he abandon him. Whoever is engaged in fulfilling his brother’s need, Allah will fulfill his need. Whoever relieves a Muslim of a hardship, Allah will relieve him of a hardship from the hardships of the Day of Resurrection. Whoever conceals a Muslim, Allah will conceal him on the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2442,"lafz":true},{"key":"muslim","label":"مسلم","number":2580}],"full":1,"dr":1},{"num":5929,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ انْصُرْ أَخَاكَ ظَالِمًا أَوْ مَظْلُومًا. قَالُوا يَا رَسُولَ اللَّهِ هَذَا نَنْصُرُهُ مَظْلُومًا، فَكَيْفَ نَنْصُرُهُ ظَالِمًا قَالَ تَأْخُذُ فَوْقَ يَدَيْهِ."],"takhrij":"صحيح: رواه البخاري في المظالم (2444) عن مسدد، حدثنا معتمر، عن حميد، عن أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب نصر المسلم ظالما أو مظلوما.","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2444).","chapter_en":"Helping a Muslim whether he is the wrongdoer or the one wronged","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ said, “Help your brother whether he is a wrongdoer or one who has been wronged.” They said: O Messenger of Allah ﷺ, we understand helping him when he is wronged, but how do we help him when he is the wrongdoer? He said, “By restraining his hands.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2444,"lafz":true}],"full":1,"rep":[13346]},{"num":5930,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ اقْتَتَلَ غُلاَمَانِ غُلاَمٌ مِنَ الْمُهَاجِرِينَ وَغُلاَمٌ مِنَ الأَنْصَارِ فَنَادَى الْمُهَاجِرُ أَوِ الْمُهَاجِرُونَ يَا لَلْمُهَاجِرِينَ. وَنَادَى الأَنْصَارِيُّ يَا لَلأَنْصَارِ. فَخَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ مَا هَذَا دَعْوَى أَهْلِ الْجَاهِلِيَّةِ. قَالُوا لاَ يَا رَسُولَ اللَّهِ إِلاَّ أَنَّ غُلاَمَيْنِ اقْتَتَلاَ فَكَسَعَ أَحَدُهُمَا الآخَرَ قَالَ فَلاَ بَأْسَ وَلْيَنْصُرِ الرَّجُلُ أَخَاهُ ظَالِمًا أَوْ مَظْلُومًا إِنْ كَانَ ظَالِمًا فَلْيَنْهَهُ فَإِنَّهُ لَهُ نَصْرٌ وَإِنْ كَانَ مَظْلُومًا فَلْيَنْصُرْهُ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2584) عن أحمد بن عبد الله بن يونس، حدثنا زهير، حدثنا أبو الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب نصر المسلم ظالما أو مظلوما.","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2584).","chapter_en":"Helping a Muslim whether he is the wrongdoer or the one wronged","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Jabir said: Two boys fought, one from the Emigrants and one from the Helpers. The Emigrant, or the Emigrants, called out, “O Emigrants!” and the Helper called out, “O Helpers!” The Messenger of Allah ﷺ came out and said: “What is this call of the people of the age of ignorance?” They said: Nothing, O Messenger of Allah ﷺ, except that two boys fought and one of them struck the other on his backside. He said: “There is no harm, but let a man help his brother whether he is a wrongdoer or one who has been wronged. If he is a wrongdoer, then let him stop him, for that is helping him. And if he is wronged, then let him support him.”"]},"buhuth":{"en":["His saying, “kas‘a,” means he struck his backside. And his saying, “There is no harm,” means that nothing harmful resulted from this incident of the kind I had feared."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2584,"lafz":true}],"full":1,"dr":1,"rep":[15015]},{"num":5931,"demo":false,"sanad":"","matn":["عن ابْنِ عُمَرَ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: انْصُرْ أَخَاكَ ظَالِمًا، أَوْ مَظْلُومًا قِيلَ: يَا رَسُولَ اللَّهِ، هَذَا نَصْرُهُ مَظْلُومًا، فَكَيْفَ أَنْصُرُهُ ظَالِمًا؟ قَالَ: تُمْسِكُهُ مِنَ الظُّلْمِ، فَذَاكَ نَصْرُكَ إِيَّاهُ."],"takhrij":"حسن: رواه ابن حبان في صحيحه (5166) عن الحسن بن سفيان، حدثنا محفوظ بن أبي توبة، حدثنا علي بن عياش، حدثنا أبو إسحاق الفزاري، عن عاصم بن محمد بن زيد العمري، عن أبيه قال: سمعت ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب نصر المسلم ظالما أو مظلوما.","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Ḥibbān in his Ṣaḥīḥ (5166).","chapter_en":"Helping a Muslim whether he is the wrongdoer or the one wronged","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿUmar reported that the Messenger of Allah ﷺ said: “Help your brother whether he is a wrongdoer or one who has been wronged.” It was asked: “O Messenger of Allah ﷺ, we understand helping him when he has been wronged, but how do we help him when he is a wrongdoer?” He replied: “You restrain him from injustice; that is how you help him.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"ابن حبان في صحيحه","number":5166,"lafz":true},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1401,"n":1398}],"full":1,"dr":1},{"num":5932,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ أَمَرَنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِسَبْعٍ، وَنَهَانَا عَنْ سَبْعٍ أَمَرَنَا بِاتِّبَاعِ الْجَنَائِزِ، وَعِيَادَةِ الْمَرِيضِ، وَإِجَابَةِ الدَّاعِي، وَنَصْرِ الْمَظْلُومِ، وَإِبْرَارِ الْقَسَمِ، وَرَدِّ السَّلاَمِ، وَتَشْمِيتِ الْعَاطِسِ. وَنَهَانَا عَنْ آنِيَةِ الْفِضَّةِ، وَخَاتَمِ الذَّهَبِ، وَالْحَرِيرِ، وَالدِّيبَاجِ، وَالْقَسِّيِّ، وَالإِسْتَبْرَقِ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1239)، ومسلم في الأشربة (2066) كلاهما من حديث شعبة، عن أشعث بن سليم قال: سمعت معاوية بن سويد بن مقرن، عن البراء فذكره. واللفظ للبخاري. ورواه مسلم من أوجه أخرى عن أشعث، ولم يذكر لفظ شعبة، وإنما أحال على غيره، وهو نحوه، والسابع عنده هو المياثر، وهو جمع مئثرة –بكسر الميم-، وهو وطاء كانت النساء يصنعنه لأزواجهن على السروج، وكان من مراكب العجم، ويكون من الحرير، ويكون من الصوف وغيره، فإذا كان من الحرير فيكون منهيا عنه.","grade":"متفق عليه","chapter_ar":"باب نصر المظلوم","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1239) and Muslim (2066). The wording is that of al-Bukhari.","chapter_en":"Supporting the oppressed","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Al-Bara’ said: The Prophet ﷺ commanded us to do seven things and forbade us from seven things. He commanded us to follow funeral processions, visit the sick, respond to invitations, support the oppressed, fulfill oaths, return greetings of peace, and say “May Allah have mercy on you” to the one who sneezes. And he forbade us from seven things: silver vessels, gold rings, silk, brocade, qassiyy cloth, and istabraq."]},"buhuth":{"en":["The seventh item in his version is “al-mayathir,” the plural of “mitharah,” with a kasrah on the mim. It is a cushion women used to make for their husbands on saddles, and it was from the riding gear of the non-Arabs. It could be made of silk, or of wool and other materials. If it was made of silk, then it was prohibited.","And “al-qassiyy,” with a fathah on the qaf, are garments striped with silk, made in al-Qass, a place in Egypt."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1239,"lafz":true},{"key":"muslim","label":"مسلم","number":2066}],"full":1,"dr":1,"rep":[3454,3666]},{"num":5933,"demo":false,"sanad":"","matn":["أَنَّ ثَابِتًا، مَوْلَى عُمَرَ بْنِ عَبْدِ الرَّحْمَنِ أَخْبَرَهُ أَنَّهُ، لَمَّا كَانَ بَيْنَ عَبْدِ اللَّهِ بْنِ عَمْرٍو وَبَيْنَ عَنْبَسَةَ بْنِ أَبِي سُفْيَانَ مَا كَانَ تَيَسَّرُوا لِلْقِتَالِ فَرَكِبَ خَالِدُ بْنُ الْعَاصِ إِلَى عَبْدِ اللَّهِ بْنِ عَمْرٍو فَوَعَظَهُ خَالِدٌ فَقَالَ عَبْدُ اللَّهِ بْنُ عَمْرٍو أَمَا عَلِمْتَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ قُتِلَ دُونَ مَالِهِ فَهُوَ شَهِيدٌ."],"takhrij":"متفق عليه: رواه مسلم في الإيمان (141) من حديث عبد الرزاق، أخبرنا ابن جريج قال: أخبرني سليمان الأحول أن ثابتا مولى عمر بن عبدالرحمن قال: فذكره، واللفظ له.","grade":"متفق عليه","chapter_ar":"باب من قاتل دون ماله فهو شهيد","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (141), and this is his wording. Also narrated by al-Bukhari (2480).","chapter_en":"Whoever is killed defending his wealth is a martyr","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Thabit, the freedman of Umar ibn Abd al-Rahman, said: When the dispute occurred between Abdullah ibn Amr and Anbasah ibn Abi Sufyan, they prepared themselves for fighting. Khalid ibn al-As rode to Abdullah ibn Amr and admonished him. Abdullah ibn Amr said: Do you not know that the Messenger of Allah ﷺ said, “Whoever is killed defending his wealth is a martyr”?"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":141,"lafz":true},{"key":"bukhari","label":"اللفظ له. ورواه البخاري","number":2480}],"full":1,"dr":1},{"num":5934,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ حَلَفَ عَلَى يَمِينِ صَبْرٍ يَقْتَطِعُ بِهَا مَالَ امْرِئٍ مُسْلِمٍ هُوَ فِيهَا فَاجِرٌ لَقِيَ اللَّهَ وَهُوَ عَلَيْهِ غَضْبَانُ. قَالَ فَدَخَلَ الأَشْعَثُ بْنُ قَيْسٍ فَقَالَ مَا يُحَدِّثُكُمْ أَبُو عَبْدِ الرَّحْمَنِ قَالُوا كَذَا وَكَذَا. قَالَ صَدَقَ أَبُو عَبْدِ الرَّحْمَنِ فِيَّ نَزَلَتْ كَانَ بَيْنِي وَبَيْنَ رَجُلٍ أَرْضٌ بِالْيَمَنِ فَخَاصَمْتُهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ هَلْ لَكَ بَيِّنَةٌ. فَقُلْتُ لاَ. قَالَ فَيَمِينُهُ. قُلْتُ إِذًا يَحْلِفُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ ذَلِكَ مَنْ حَلَفَ عَلَى يَمِينِ صَبْرٍ يَقْتَطِعُ بِهَا مَالَ امْرِئٍ مُسْلِمٍ هُوَ فِيهَا فَاجِرٌ لَقِيَ اللَّهَ وَهُوَ عَلَيْهِ غَضْبَانُ. فَنَزَلَتْ ﴿إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ وَأَيْمَانِهِمْ ثَمَنًا قَلِيلاً﴾ [سورة آل عمران: 77]} إِلَى آخِرِ الآيَةِ."],"takhrij":"متفق عليه: رواه البخاري في المساقاة (2356)، ومسلم في الإيمان (138) كلاهما من حديث الأعمش، عن أبي وائل، عن عبد الله بن مسعود فذكر مثله. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب وعيد من اقتطع حقه بيمين فاجرة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2356) and Muslim (138). The wording is that of Muslim.","chapter_en":"The warning against one who seizes another’s right with a sinful oath","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abdullah ibn Mas‘ud reported that the Messenger of Allah ﷺ said: “Whoever swears a binding oath in order to seize the wealth of a Muslim while he is sinful in that oath will meet Allah while He is angry with him.” Then al-Ash‘ath ibn Qays entered and said: What is Abu Abd al-Rahman narrating to you? They said: Such-and-such. He said: Abu Abd al-Rahman has spoken the truth. It was concerning me that this verse was revealed. There was a dispute between me and another man over land in Yemen, and I took the matter to the Prophet ﷺ. He said: “Do you have proof?” I said: No. He said: “Then his oath.” I said: Then he will simply swear. At that point the Messenger of Allah ﷺ said: “Whoever swears a binding oath to seize the wealth of a Muslim while he is sinful in it will meet Allah while He is angry with him.” Then the verse was revealed: “Indeed, those who exchange the covenant of Allah and their oaths for a small price…” [Aal Imran: 77] to the end of the verse."]},"buhuth":{"en":["In a narration in al-Bukhari (2516): “Your two witnesses, or else his oath.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2356,"lafz":true},{"key":"muslim","label":"مسلم","number":138}],"full":1,"dr":1},{"num":5935,"demo":false,"sanad":"","matn":["عَنْ وَائِلِ بْنِ حُجْرٍ، عَنْ أَبِيهِ قَالَ: جَاءَ رَجُلٌ مِنْ حَضْرَمَوْتَ، وَرَجُلٌ مِنْ كِنْدَةَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَقَالَ الْحَضْرَمِيُّ: يَا رَسُولَ اللَّهِ، إِنَّ هَذَا قَدْ غَلَبَنِي عَلَى أَرْضٍ لِي كَانَتْ لأَبِي. فَقَالَ الْكِنْدِيُّ: هِيَ أَرْضِي فِي يَدِي أَزْرَعُهَا لَيْسَ لَهُ فِيهَا حَقٌّ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلْحَضْرَمِيِّ: أَلَكَ بَيِّنَةٌ؟. قَالَ: لاَ. قَالَ: فَلَكَ يَمِينُهُ. قَالَ: يَا رَسُولَ اللَّهِ، إِنَّ الرَّجُلَ فَاجِرٌ لاَ يُبَالِي عَلَى مَا حَلَفَ عَلَيْهِ، وَلَيْسَ يَتَوَرَّعُ مِنْ شيء. فَقَالَ: لَيْسَ لَكَ منـه إِلاَّ ذَلِكَ. فَانْطَلَقَ لِيَحْلِفَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا أَدْبَرَ: أَمَا لَئِنْ حَلَفَ عَلَى مَالِهِ لِيَأْكُلَهُ ظُلْمًا لَيَلْقَيَنَّ اللَّهَ وَهُوَ عَنْهُ مُعْرِضٌ."],"takhrij":"صحيح: رواه مسلم في الإيمان (139) من طرق عن أبي الأحوص، عن سماك، عن علقمة بن وائل، عن أبيه وائل بن حجر فذكره.","grade":"صحيح","chapter_ar":"باب وعيد من اقتطع حقه بيمين فاجرة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (139).","chapter_en":"The warning against one who seizes another’s right with a sinful oath","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Wa’il ibn Hujr, from his father, said: A man from Hadramawt and a man from Kindah came to the Prophet ﷺ. The Hadrami said: O Messenger of Allah ﷺ, this man has taken land from me that belonged to my father. The Kindi said: It is my land, it is in my possession, and I cultivate it. He has no right to it. The Messenger of Allah ﷺ said to the Hadrami: “Do you have proof?” He said: No. He said: “Then you have his oath.” He said: O Messenger of Allah ﷺ, the man is wicked. He does not care what he swears to, and he refrains from nothing. He said: “You have nothing from him except that.” As the man went away to swear, the Messenger of Allah ﷺ said when he turned away: “If he swears in order to consume that wealth unjustly, he will surely meet Allah while Allah is turned away from him.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":139,"lafz":true}],"full":1,"dr":1},{"num":5936,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنِ اقْتَطَعَ حَقَّ امْرِئٍ مُسْلِمٍ بِيَمِينِهِ فَقَدْ أَوْجَبَ اللَّهُ لَهُ النَّارَ وَحَرَّمَ عَلَيْهِ الْجَنَّةَ. فَقَالَ لَهُ رَجُلٌ وَإِنْ كَانَ شَيْئًا يَسِيرًا يَا رَسُولَ اللَّهِ قَالَ وَإِنْ قَضِيبًا مِنْ أَرَاكٍ."],"takhrij":"صحيح: رواه مسلم في الإيمان (137) من طرق عن إسماعيل بن جعفر قال: أخبرنا العلاء (وهو ابن عبد الرحمن مولى الحرقة)، عن معبد بن كعب السلمي، عن أخيه عبد الله بن كعب، عن أبي أمامة فذكر مثله.","grade":"صحيح","chapter_ar":"باب وعيد من اقتطع حقه بيمين فاجرة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (137).","chapter_en":"The warning against one who seizes another’s right with a sinful oath","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Umamah reported that the Messenger of Allah ﷺ said: “Whoever seizes the right of a Muslim by means of his oath, Allah has made the Fire obligatory for him and has forbidden Paradise for him.” A man said: Even if it is something small, O Messenger of Allah ﷺ? He said: “Even if it is a twig from an arak tree.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":137,"lafz":true}],"full":1},{"num":5937,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن يَزِيدَ قَالَ: نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ النُّهْبَى وَالْمُثْلَةِ."],"takhrij":"صحيح: رواه البخاري في المظالم (2474)، عن آدم بن أبي إياس، حدثنا شعبة، حدثنا عدي بن ثابت، سمعت عبد الله بن يزيد الأنصاري وهو جده أبو أمه قال فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن النُّهبى","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2474).","chapter_en":"The prohibition of plunder","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Abdullah ibn Yazid said: The Prophet ﷺ forbade plunder and mutilation."]},"buhuth":{"en":["“Al-nuhba” means taking wealth by force."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2474,"lafz":true}],"full":1,"dr":1},{"num":5938,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ جَلَبَ وَلاَ جَنَبَ وَلاَ شِغَارَ فِي الإِسْلاَمِ وَمَنِ انْتَهَبَ نُهْبَةً فَلَيْسَ مِنَّا."],"takhrij":"صحيح: رواه أبو داود (2581)، والترمذي (1123)، والنسائي (6/111)، وابن ماجه (3937)، وصحّحه ابن حبان (3267، 5170)، وأحمد (19946) كلهم من حديث حميد الطويل، عن الحسن، عن عمران بن حصين فذكره، واختصره البعض.","grade":"صحيح","chapter_ar":"باب النهي عن النُّهبى","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (2581), al-Tirmidhī (1123), and al-Nasāʾī (6/111).","chapter_en":"The prohibition of plunder","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn reported that the Prophet ﷺ said: “There is no jalab, no janab, and no shighār in Islam. Whoever forcibly seizes property as plunder is not one of us.”"]},"buhuth":{"en":["Al-Tirmidhī said: “Hasan Sahih.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2581,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1123},{"key":"nasai","label":"النسائي","number":6},{"key":"ibnmajah","label":"ابن ماجه","number":3937},{"key":"ibnhibban","label":"ابن حبان","number":3267},{"key":"ibnhibban","label":"ابن حبان","number":5170},{"key":"ahmad","label":"احمد","number":19946}],"full":1,"dr":1},{"num":5939,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِنَّ أَبْغَضَ الرِّجَالِ إِلَى اللَّهِ الأَلَدُّ الْخَصِمُ."],"takhrij":"متفق عليه: رواه البخاري في المظالم (2457)، ومسلم في العلم (2668) كلاهما عن ابن جريج، عن ابن أبي مليكة، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الألد الخصم","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2457) and Muslim (2668).","chapter_en":"What has been reported concerning the stubborn disputant","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Aishah said: The Messenger of Allah ﷺ said: “Indeed, the most hated of men to Allah is the stubborn, fiercely argumentative opponent.”"]},"buhuth":{"en":["His saying, “al-aladd,” means one who is severe in argument and dispute. It is taken from the two sides of a valley, because whenever a proof is brought against him, he turns to another side."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2457,"lafz":true},{"key":"muslim","label":"مسلم","number":2668},{"key":"sh13039","label":"الصمت وآداب اللسان","number":157,"n":155}],"full":1,"dr":1},{"num":5940,"demo":false,"sanad":"","matn":["عن سُوَيْدِ بْنِ غفلة قَالَ لَقِيتُ أُبَىَّ بْنَ كَعْبٍ رَضِيَ اللَّهُ عَنْهُ فَقَالَ أَخَذْتُ صُرَّةً مِائَةَ دِينَارٍ فَأَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ عَرِّفْهَا حَوْلاً. فَعَرَّفْتُهَا حَوْلَهَا فَلَمْ أَجِدْ مَنْ يَعْرِفُهَا، ثُمَّ أَتَيْتُهُ فَقَالَ عَرِّفْهَا حَوْلاً فَعَرَّفْتُهَا فَلَمْ أَجِدْ، ثُمَّ أَتَيْتُهُ ثَلاَثًا فَقَالَ احْفَظْ وِعَاءَهَا وَعَدَدَهَا وَوِكَاءَهَا، فَإِنْ جَاءَ صَاحِبُهَا، وَإِلاَّ فَاسْتَمْتِعْ بِهَا. فَاسْتَمْتَعْتُ فَلَقِيتُهُ بَعْدُ بِمَكَّةَ فَقَالَ لاَ أَدْرِي ثَلاَثَةَ أَحْوَالٍ أَوْ حَوْلاً وَاحِدًا."],"takhrij":"متفق عليه: رواه البخاري في اللقطة (2426)، ومسلم في اللقطة (1723) كلاهما عن محمد بن بشار، حدثنا غندر، حدثنا شعبة، عن سلمة بن كهيل قال: سمعت سويد بن غفلة قال: خرجت أنا وزيد بن صوحان وسلمان بن ربيعة غازين، فوجدت سوطا، فأخذته، فقالا لي: دعه. فقلت: لا، ولكني أعرفه، فإن جاء صاحبه وإلا استمتعت به. قال: فأبيت عليهما، فلما رجعنا من غزاتنا قضي لي أني حججت، فأتيت المدينة، فلقيت أبى بن كعب، فأخبرته بشأن السوط وبقولهما، فقال: إني وجدت صرة فذكر الحديث، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب التعريف باللقطة حولا واحدا","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2426) and Muslim (1723). The wording is that of Muslim. In Sahih Muslim it says: “Announce it for one year.”","chapter_en":"Announcing lost property for one full year","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Suwayd ibn Ghafalah said: I met Ubayy ibn Ka‘b, and he said: I found a purse containing one hundred dinars, so I went to the Prophet ﷺ, and he said, “Announce it for one year.” So I announced it for one year, but I did not find anyone who recognized it. Then I came to him again, and he said, “Announce it for one year.” So I announced it, but I did not find anyone. Then I came to him a third time, and he said, “Preserve its container, its amount, and its tying string. If its owner comes, then return it to him. Otherwise, make use of it.” So I made use of it. Later I met him in Makkah, and he said: I do not know whether it was for three years or for one year only."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2426,"lafz":true},{"key":"muslim","label":"مسلم","number":1723}],"full":1,"dr":1},{"num":5941,"demo":false,"sanad":"","matn":["عَنْ سُفْيَانَ بن عَبْدِ اللَّهِ بن رَبِيعَةَ الثقفي أَنَّهُ وجدَ عَيْبَةً فَأَتَى بِهَا عُمَرَ بْنَ الْخَطَّابِ فَقَالَ: عرِّفْها سنةً، فإنْ عُرِفَتْ فَذَاكَ، وَإِلَّا فَهِيَ لَكَ، فَلَمْ تُعرَفْ، فَلَقِيَهُ فِي الْعَامِ الْمُقْبِلِ فِي الْمَوْسِمِ فَذَكَرَهَا لَهُ، فَقَالَ عُمَرُ: هِيَ لَكَ، فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَنَا بِذَلِكَ، قَالَ: لَا حَاجَةَ لِي بِهَا، فَقَبَضَهَا عمرُ، فَجَعَلَهَا فِي بَيْتِ الْمَالِ."],"takhrij":"حسن: رواه الدارمي (2641)، والطحاوي في شرح المشكل (4695)، والبيهقي (6/187) كلهم من طريق أبي أسامة، عن الوليد بن كثير قال: حدثني عمرو بن شعيب، عن عمرو وعاصم ابنَيْ سفيان بن عبد الله، عن أبيهما قال: فذكره.","grade":"حسن","chapter_ar":"باب التعريف باللقطة حولا واحدا","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Hasan: Narrated by al-Darimi (2641), al-Tahawi in Sharh Mushkil al-Athar (4695), and al-Bayhaqi (6/187).","chapter_en":"Announcing lost property for one full year","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Sufyan ibn Abd Allah ibn Rabi‘ah al-Thaqafi found a pouch and brought it to Umar ibn al-Khattab. Umar said: Announce it for one year. If it is recognized, then that is that. Otherwise, it is yours. It was not recognized, and he met him in the following year during the pilgrimage season and mentioned it to him. Umar said: It is yours, for the Messenger of Allah ﷺ, commanded us to do that. He said: I have no need of it. So Umar took it and placed it in the public treasury."]},"buhuth":{"en":["His statement, “al-‘aybah,” means a container made of leather in which belongings are kept."]}},"tuhfa":{},"refs":[{"key":"sh22547","label":"الطحاوي في شرح المشكل","number":4695},{"key":"kubrabayhaqi","label":"البيهقي","number":187},{"key":"darimi","label":"سنن الدارمي","number":2519,"n":2519,"lafz":true},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":12059,"n":12171},{"key":"darimi","label":"الدارمي","number":2641,"n":2519}],"full":1,"dr":1},{"num":5942,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ، أَخْبَرَهُ أَنَّ عَلِيَّ بْنَ أَبِي طَالِبٍ دَخَلَ عَلَى فَاطِمَةَ وَحَسَنٌ وَحُسَيْنٌ يَبْكِيَانِ فَقَالَ مَا يُبْكِيهِمَا قَالَتِ الْجُوعُ فَخَرَجَ عَلِيٌّ فَوَجَدَ دِينَارًا بِالسُّوقِ فَجَاءَ إِلَى فَاطِمَةَ فَأَخْبَرَهَا فَقَالَتِ اذْهَبْ إِلَى فُلاَنٍ الْيَهُودِيِّ فَخُذْ دَقِيقًا فَجَاءَ الْيَهُودِيَّ فَاشْتَرَى بِهِ دَقِيقًا فَقَالَ الْيَهُودِيُّ أَنْتَ خَتَنُ هَذَا الَّذِي يَزْعُمُ أَنَّهُ رَسُولُ اللَّهِ قَالَ نَعَمْ. قَالَ فَخُذْ دِينَارَكَ وَلَكَ الدَّقِيقُ. فَخَرَجَ عَلِيٌّ حَتَّى جَاءَ فَاطِمَةَ فَأَخْبَرَهَا فَقَالَتِ اذْهَبْ إِلَى فُلاَنٍ الْجَزَّارِ فَخُذْ لَنَا بِدِرْهَمٍ لَحْمًا فَذَهَبَ فَرَهَنَ الدِّينَارَ بِدِرْهَمِ لَحْمٍ فَجَاءَ بِهِ فَعَجَنَتْ وَنَصَبَتْ وَخَبَزَتْ وَأَرْسَلَتْ إِلَى أَبِيهَا فَجَاءَهُمْ فَقَالَتْ يَا رَسُولَ اللَّهِ أَذْكُرُ لَكَ فَإِنْ رَأَيْتَهُ لَنَا حَلاَلاً أَكَلْنَاهُ وَأَكَلْتَ مَعَنَا مِنْ شَأْنِهِ كَذَا وَكَذَا. فَقَالَ كُلُوا بِاسْمِ اللَّهِ. فَأَكَلُوا فَبَيْنَمَا هُمْ مَكَانَهُمْ إِذَا غُلاَمٌ يَنْشُدُ اللَّهَ وَالإِسْلاَمَ الدِّينَارَ فَأَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَدُعِيَ لَهُ فَسَأَلَهُ. فَقَالَ سَقَطَ مِنِّي فِي السُّوقِ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَا عَلِيُّ اذْهَبْ إِلَى الْجَزَّارِ فَقُلْ لَهُ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ لَكَ أَرْسِلْ إِلَىَّ بِالدِّينَارِ وَدِرْهَمُكَ عَلَىَّ. فَأَرْسَلَ بِهِ فَدَفَعَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَيْهِ."],"takhrij":"حسن: رواه أبو داود (1716) عن جعفر بن مسافر التنيسى، حدثنا ابن أبى فديك، حدثنا موسى بن يعقوب الزمعي، عن أبي حازم، عن سهل بن سعد أخبره فذكره.","grade":"حسن","chapter_ar":"باب جواز الأكل قبل التعريف للحاجة","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1716).","chapter_en":"The permissibility of eating from it before announcement in a case of need","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Sahl ibn Sa‘d reported that Ali ibn Abi Talib entered upon Fatimah while Hasan and Husayn were crying. He said: What is making them cry? She said: Hunger. So Ali went out and found a dinar in the marketplace. He came to Fatimah and told her. She said: Go to that Jewish man and get us some flour. So he went to the Jew and bought flour with it. The Jew said: Are you the son-in-law of the one who claims that he is the Messenger of Allah ﷺ? He said: Yes. He said: Take back your dinar, and keep the flour. Then Ali returned and brought it to Fatimah and told her. She said: Go to that butcher and get a dirham’s worth of meat. So he went and pawned the dinar for a dirham’s worth of meat, then brought it. She kneaded, set up the cooking pot, baked, and sent for her father. He came to them, and she said: O Messenger of Allah ﷺ, I will tell you about it, and if you see it as lawful for us, we will eat it and you will eat also. She told him what had happened. He said: “Eat in the name of Allah.” So they ate from it. While they were there, a young man came calling out by Allah and by Islam for the lost dinar. The Messenger of Allah ﷺ ordered that he be brought, and he asked him. The boy said: It fell from me in the marketplace. The Prophet ﷺ said: “O Ali, go to the butcher and say to him: The Messenger of Allah ﷺ says to you: Send me the dinar, and your dirham is due from me.” So he sent it, and the Messenger of Allah ﷺ handed it to him."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1716,"lafz":true}],"full":1,"dr":1},{"num":5943,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ خَالِدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَهُ عَنِ اللُّقَطَةِ، فَقَالَ اعْرِفْ عِفَاصَهَا وَوِكَاءَهَا، ثُمَّ عَرِّفْهَا سَنَةً، فَإِنْ جَاءَ صَاحِبُهَا وَإِلاَّ فَشَأْنَكَ بِهَا. قَالَ فَضَالَّةُ الْغَنَمِ قَالَ هِيَ لَكَ أَوْ لأَخِيكَ أَوْ لِلذِّئْبِ. قَالَ فَضَالَّةُ الإِبِلِ قَالَ مَالَكَ وَلَهَا مَعَهَا سِقَاؤُهَا وَحِذَاؤُهَا، تَرِدُ الْمَاءَ وَتَأْكُلُ الشَّجَرَ، حَتَّى يَلْقَاهَا رَبُّهَا."],"takhrij":"متفق عليه: رواه مالك في الأقضية (48) عن ربيعة بن أبي عبد الرحمن، عن يزيد مولى المنبعث، عن زيد بن خالد الجهني فذكره.","grade":"متفق عليه","chapter_ar":"باب ضالة الإبل والغنم","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (48), al-Bukhari (2372), and Muslim (1722).","chapter_en":"Stray camels and sheep","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Zayd ibn Khalid al-Juhani said: A man came to the Messenger of Allah ﷺ, and asked him about lost property. He said: “Recognize its container and its tying string, then announce it for a year. If its owner comes, then return it. Otherwise, it is yours to deal with.” He said: What about stray sheep, O Messenger of Allah ﷺ? He said: “It is for you, or for your brother, or for the wolf.” He said: What about stray camels? He said: “What have you to do with them? They have their water supply and their feet. They can reach water and eat from the trees until their owner finds them.”"]},"buhuth":{"en":["“Al-‘ifas” is the container in which money is kept, whether made of leather, cloth, or something else. For this reason, the leather covering placed over the mouth of a bottle is also called ‘ifas. “Al-wika’” is the string by which the container is tied.","His statement, “It has its water supply and its feet,” means by “water supply” that when it reaches water, it drinks enough to satisfy its thirst, and it is among the animals that can go the longest without water because of how much it can carry. By “feet,” he meant its hooves, by which it is able to travel, cross vast lands, and reach distant watering places. See Sharh al-Sunnah (8/210)."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":48,"lafz":true},{"key":"bukhari","label":"البخاري","number":2372},{"key":"muslim","label":"مسلم","number":1722}],"full":1,"dr":1},{"num":5944,"demo":false,"sanad":"","matn":["عن زَيْدِ بن خَالِدٍ الْجُهَنِيِّ صاحب رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ اللُّقَطَةِ الذَّهَبِ أَوِ الْوَرِقِ فَقَالَ اعْرِفْ وِكَاءَهَا وَعِفَاصَهَا ثُمَّ عَرِّفْهَا سَنَةً فَإِنْ لَمْ تَعْرِفْ فَاسْتَنْفِقْهَا وَلْتَكُنْ وَدِيعَةً عِنْدَكَ فَإِنْ جَاءَ طَالِبُهَا يَوْمًا مِنَ الدَّهْرِ فَأَدِّهَا إِلَيْهِ. وَسَأَلَهُ عَنْ ضَالَّةِ الإِبِلِ فَقَالَ مَا لَكَ وَلَهَا دَعْهَا فَإِنَّ مَعَهَا حِذَاءَهَا وَسِقَاءَهَا تَرِدُ الْمَاءَ وَتَأْكُلُ الشَّجَرَ حَتَّى يَجِدَهَا رَبُّهَا. وَسَأَلَهُ عَنِ الشَّاةِ فَقَالَ خُذْهَا فَإِنَّمَا هِيَ لَكَ أَوْ لأَخِيكَ أَوْ لِلذِّئْبِ."],"takhrij":"صحيح: رواه مسلم في اللقطة (1722: 5) عن عبد الله بن مسلمة بن قعنب، حدثنا سليمان (يعنى ابن بلال)، عن يحيى بن سعيد، عن يزيد مولى المنبعث، أنه سمع زيد بن خالد الجهني فذكره.","grade":"صحيح","chapter_ar":"باب ضالة الإبل والغنم","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1722:5).","chapter_en":"Stray camels and sheep","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Zayd ibn Khalid al-Juhani, a Companion of the Messenger of Allah ﷺ said: The Messenger of Allah ﷺ was asked about lost gold or silver. He said: “Recognize its tying string and its container, then announce it for a year. If it is not recognized, then spend it, but let it remain as a trust with you. If its claimant comes one day, then return it to him.” He was asked about stray camels, and he said: “What have you to do with them? Leave them, for they have their feet and their water supply. They can reach water and eat from the trees until their owner finds them.” He was asked about sheep, and he said: “Take it, for it is only for you, or for your brother, or for the wolf.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":5,"lafz":true},{"key":"muslim","label":"مسلم في اللقطه","number":1722,"n":4502}],"full":1,"dr":1},{"num":5945,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ، أَنَّ رَجُلاً، سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ اللُّقَطَةِ فَقَالَ عَرِّفْهَا سَنَةً ثُمَّ اعْرِفْ وِكَاءَهَا وَعِفَاصَهَا ثُمَّ اسْتَنْفِقْ بِهَا فَإِنْ جَاءَ رَبُّهَا فَأَدِّهَا إِلَيْهِ. فَقَالَ يَا رَسُولَ اللَّهِ فَضَالَّةُ الْغَنَمِ فَقَالَ خُذْهَا فَإِنَّمَا هِيَ لَكَ أَوْ لأَخِيكَ أَوْ لِلذِّئْبِ. قَالَ يَا رَسُولَ اللَّهِ فَضَالَّةُ الإِبِلِ فَغَضِبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى احْمَرَّتْ وَجْنَتَاهُ - أَوِ احْمَرَّ وَجْهُهُ - وَقَالَ مَا لَكَ وَلَهَا مَعَهَا حِذَاؤُهَا وَسِقَاؤُهَا حَتَّى يَأْتِيَهَا رَبُّهَا."],"takhrij":"صحيح: رواه أبو داود (1704)، والترمذي (1373) كلاهما عن قتيبة بن سعيد، حدثنا إسماعيل بن جعفر، عن ربيعة بن أبي عبد الرحمن، عن يزيد مولى المنبعث، عن زيد بن خالد الجهني فذكره.","grade":"صحيح","chapter_ar":"باب ضالة الإبل والغنم","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1704) and al-Tirmidhi (1373).","chapter_en":"Stray camels and sheep","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Zayd ibn Khalid al-Juhani reported that a man asked the Messenger of Allah ﷺ, about lost property. He said: “Announce it for one year, then remember its tying string and its container, then spend it. If its owner comes, then give it to him.” He said: O Messenger of Allah ﷺ, what about stray sheep? He said: “Take it, for it is only for you, or for your brother, or for the wolf.” He said: O Messenger of Allah ﷺ, what about stray camels? The Messenger of Allah ﷺ became angry until his cheeks became red—or his face became red—and he said: “What have you to do with them? They have their feet and their water supply until their owner comes to them.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1704,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1373,"n":1372}],"full":1,"dr":1},{"num":5946,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن عمرو بْنِ الْعَاصِ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ سُئِلَ عَنِ الثَّمَرِ الْمُعَلَّقِ فَقَالَ مَنْ أَصَابَ بِفِيهِ مِنْ ذِي حَاجَةٍ غَيْرَ مُتَّخِذٍ خُبْنَةً فَلاَ شَىْءَ عَلَيْهِ وَمَنْ خَرَجَ بِشَىْءٍ مِنْهُ فَعَلَيْهِ غَرَامَةُ مِثْلَيْهِ وَالْعُقُوبَةُ وَمَنْ سَرَقَ مِنْهُ شَيْئًا بَعْدَ أَنْ يُئْوِيَهُ الْجَرِينُ فَبَلَغَ ثَمَنَ الْمِجَنِّ فَعَلَيْهِ الْقَطْعُ. وَذَكَرَ فِي ضَالَّةِ الإِبِلِ وَالْغَنَمِ كَمَا ذَكَرَهُ غَيْرُهُ.","قال: وسئل عن اللقطة، فقال: ما كان منها في طريق الميتاء أو القرية الجامعة فعرفها سنة، فإن جاء طالبها فادفعها إليه، وإن لم يأت فهي لك، وما كان في الخراب يعنى ففيها وفي الركاز الخمس."],"takhrij":"حسن: رواه أبو داود (1710)، والترمذي (1288)، والنسائي (4958)، وابن ماجه (2596) كلهم عن قتيبة بن سعيد، حدثنا الليث، عن ابن عجلان، عن عمرو بن شعيب، عن أبيه، عن جده عبد الله بن عمرو بن العاص فذكر الحديث، إلا ابن ماجه فرواه من وجه آخر عن الوليد بن كثير، عن عمرو بن شعيب، واللفظ لأبي داود، وعند الآخرين مختصرا.","grade":"حسن","chapter_ar":"باب ضالة الإبل والغنم","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1710), al-Tirmidhi (1288), al-Nasa’i (4958), and Ibn Majah (2596). The wording is that of Abu Dawud.","chapter_en":"Stray camels and sheep","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Abdullah ibn Amr ibn al-As reported that the Messenger of Allah ﷺ was asked about fruit hanging on the trees. He said: “Whoever takes some with his mouth out of need, without taking any away in his garment, there is nothing due on him. But whoever takes some away, then upon him is double compensation and punishment. And whoever steals from it after it has been gathered in the storage place, and its value reaches the price of a shield, then the prescribed punishment of cutting applies.” He also mentioned the ruling of stray camels and sheep as others have mentioned. He said: And he was asked about lost property, and he said: “Whatever of it is found on a traveled road or in a settled village, announce it for a year. If its claimant comes, then hand it to him. If he does not come, then it is yours. But what is found in ruins, then regarding it and buried treasure one-fifth is due.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1710,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1288},{"key":"nasai","label":"النسائي","number":4958},{"key":"ibnmajah","label":"ابن ماجه","number":2596}],"full":1,"dr":1,"rep":[6988]},{"num":5947,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ: سَمِعْتُ رَجُلًا مِنْ مُزَيْنَةَ يَسْأَلُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: يَا رَسُولَ اللَّهِ، جِئْتُ أَسْأَلُكَ عَنِ الضَّالَّةِ مِنَ الْإِبِلِ؟ قَالَ: مَعَهَا حِذَاؤُهَا، وَسِقَاؤُهَا، تَأْكُلُ الشَّجَرَ، وَتَرِدُ الْمَاءَ، فَدَعْهَا حَتَّى يَأْتِيَهَا بَاغِيهَا قَالَ: الضَّالَّةُ مِنَ الْغَنَمِ؟ قَالَ: لَكَ أَوْ لِأَخِيكَ، أَوْ لِلذِّئْبِ، تَجْمَعُهَا حَتَّى يَأْتِيَهَا بَاغِيهَا قَالَ: الْحَرِيسَةُ الَّتِي تُوجَدُ فِي مَرَاتِعِهَا؟ قَالَ: فِيهَا ثَمَنُهَا مَرَّتَيْنِ، وَضَرْبُ نَكَالٍ، وَمَا أُخِذَ مِنْ عَطَنِهِ فَفِيهِ الْقَطْعُ، إِذَا بَلَغَ مَا يُؤْخَذُ مِنْ ذَلِكَ ثَمَنَ الْمِجَنِّ قَالَ: يَا رَسُولَ اللَّهِ، فَالثِّمَارُ، وَمَا أُخِذَ مِنْهَا فِي أَكْمَامِهَا؟ قَالَ: مَنْ أَخَذَ بِفَمِهِ، وَلَمْ يَتَّخِذْ خُبْنَةً، فَلَيْسَ عَلَيْهِ شَيْءٌ، وَمَنِ احْتَمَلَ، فَعَلَيْهِ ثَمَنُهُ مَرَّتَيْنِ وَضَرْبًا وَنَكَالًا، وَمَا أَخَذَ مِنْ أَجْرَانِهِ، فَفِيهِ الْقَطْعُ، إِذَا بَلَغَ مَا يُؤْخَذُ مِنْ ذَلِكَ ثَمَنَ الْمِجَنِّ قَالَ: يَا رَسُولَ اللَّهِ، وَاللُّقَطَةُ نَجِدُهَا فِي سَبِيلِ الْعَامِرَةِ؟ قَالَ: عَرِّفْهَا حَوْلًا، فَإِنْ وُجِدَ بَاغِيهَا، فَأَدِّهَا إِلَيْهِ، وَإِلَّا فَهِيَ لَكَ، قَالَ: مَا يُوجَدُ فِي الْخَرِبِ الْعَادِيِّ؟ قَالَ: فِيهِ وَفِي الرِّكَازِ الْخُمُسُ."],"takhrij":"حسن: رواه الإمام أحمد (6683) عن يعلى، حدثنا محمد بن إسحاق، عن عمرو بن شعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب ضالة الإبل والغنم","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (6683).","chapter_en":"Stray camels and sheep","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Amr ibn Shu‘ayb, from his father, from his grandfather, said: I heard a man from Muzaynah asking the Messenger of Allah ﷺ. He said: O Messenger of Allah ﷺ, I have come to ask you about stray camels. He said: “They have their feet and their water supply. They eat from the trees and go to water, so leave them until the one seeking them comes.” He said: What about stray sheep? He said: “It is for you, or for your brother, or for the wolf. Gather it until the one seeking it comes.” He said: What about livestock taken from their grazing places? He said: “For that there is double its value and a disciplinary punishment. And what is taken from its enclosure is subject to cutting off the hand if what is taken reaches the value of a shield.” He said: O Messenger of Allah ﷺ, what about fruits, and what is taken from them while still attached? He said: “Whoever takes with his mouth and does not carry anything away in his garment, there is nothing due on him. Whoever carries some away, then upon him is double its value and a disciplinary punishment. And what is taken from the drying area is subject to cutting off the hand if what is taken reaches the value of a shield.” He said: O Messenger of Allah ﷺ, what about lost property that we find on inhabited roads? He said: “Announce it for one year. If the one seeking it comes, then return it to him. Otherwise, it is yours.” He said: What about what is found in ancient ruins? He said: “Regarding it and buried treasure, one-fifth is due.”"]},"buhuth":{"en":["His statement, “livestock taken from its pasture,” is referred to in Sharh al-Sunnah as “the guarded animal of the mountain.”","Al-Baghawi said: “What is meant by the guarded animal of the mountain is cattle, sheep, or camels taken from the grazing place. It is said: a man ‘ihtarasa’ when he took a sheep from the pasture. The imposition of double the value appears to be by way of threat and deterrence; otherwise, a damaged item is not usually compensated by more than its equivalent value. Umar ibn al-Khattab judged by this, and Ahmad ibn Hanbal held this view. It has also been said that in the early period of Islam, some financial punishments were imposed and were later abrogated. And Allah knows best.” End quote."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":6683,"lafz":true}],"full":1,"dr":1},{"num":5948,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَسُئِلَ عَنْ ضَالَّةِ الْغَنَمِ، فَقَالَ: هِيَ لَكَ أَوْ لأَخِيكَ أَوْ لِلذِّئْبِ، وَسُئِلَ عَنْ ضَالَّةِ الإِبِلِ، فَقَالَ: مَالَكَ وَلَهَا، وَمَعَهَا سِقَاؤُهَا أَوْ سِقَاؤُهُ وَحِذَاؤُهُ، دَعْهُ حَتَّى يَجِدَهُ رَبُّهُ."],"takhrij":"حسن: رواه البزار –كشف الأستار (1364)- عن محمد بن مسكين، ثنا سعيد بن أبي مريم، ثنا يحيى بن أيوب، عن ابن عجلان، عن القعقاع بن حكيم، عن أبي صالح، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ضالة الإبل والغنم","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzar in Kashf al-Astar (1364).","chapter_en":"Stray camels and sheep","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ was asked about stray sheep, and he said: “It is for you, or for your brother, or for the wolf.” And he was asked about stray camels, and he said: “What have you to do with them? They have their water supply—or its water supply—and their feet. Leave it until its owner finds it.”"]}},"tuhfa":{},"refs":[{"key":"sh12862","label":"البزار - كشف الأستار","number":1364,"lafz":true}],"full":1,"dr":1},{"num":5949,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ ضَالَّةُ الإِبِلِ الْمَكْتُومَةِ غَرَامَتُهَا وَمِثْلُهَا مَعَهَا."],"takhrij":"حسن: رواه أبو داود (1718) عن مخلد بن خالد، حدثنا عبدالرزاق- وهو في مصنفه (18599)- أخبرنا معمر، عن عمرو بن مسلم، عن عكرمة، أحسبه عن أبى هريرة فذكره.","grade":"حسن","chapter_ar":"باب الترهيب من كتم اللقطة وتغييبها","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1718) and Abd al-Razzaq in his Musannaf (18599).","chapter_en":"The warning against concealing found property and hiding it","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “A concealed stray camel requires compensation for it and another like it.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1718,"lafz":true},{"key":"abdrazzaq","label":"عبد الرزاق في مصنفه","number":18599}],"full":1,"dr":1},{"num":5950,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: لما فتح الله على رسوله مكة، فقام في الناس، فحمد الله، وأثنى عليه، ثم قال: ولا تحل ساقطتها إلا لمنشد."],"takhrij":"متفق عليه: رواه البخاري في اللقطة (2434)، ومسلم في الحج (1355)، كلاهما من حديث الوليد بن مسلم، حدثنا الأوزاعي قال: حدثني يحيى بن أبي كثير قال: حدثني أبو سلمة بن عبد الرحمن قال: حدثني أبو هريرة فذكره في حديث طويل.","grade":"متفق عليه","chapter_ar":"باب لا تحل لقطة مكة إلا لمنشد","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2434) and Muslim (1355).","chapter_en":"Lost property of Makkah is not lawful except for one who publicly announces it","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah said: When Allah granted His Messenger the conquest of Makkah, he stood among the people, praised Allah, and glorified Him, then said: “Its lost property is not lawful except for one who announces it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2434,"lafz":true},{"key":"muslim","label":"مسلم","number":1355}],"full":1},{"num":5951,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ فَتْحِ مَكَّةَ إِنَّ هَذَا الْبَلَدَ حَرَّمَهُ اللَّهُ، لاَ يُعْضَدُ شَوْكُهُ، وَلاَ يُنَفَّرُ صَيْدُهُ، وَلاَ يَلْتَقِطُ لُقَطَتَهُ إِلاَّ مَنْ عَرَّفَهَا."],"takhrij":"متفق عليه: رواه البخاري في الحج (1587) ومسلم في الحج (1353) كلاهما من حديث جـرير بن عبد الحميد، عـن منصور، عن مجاهد، عن طاوس، عن ابن عباس فذكره. واللفظ للبخاري، وسياق مسلم أطول.","grade":"متفق عليه","chapter_ar":"باب لا تحل لقطة مكة إلا لمنشد","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1587) and Muslim (1353). The wording is that of al-Bukhari.","chapter_en":"Lost property of Makkah is not lawful except for one who publicly announces it","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn Abbas said: The Messenger of Allah ﷺ said on the day of the conquest of Makkah: “Indeed, Allah has made this town sacred. Its thorns are not to be cut, its game is not to be driven away, and its lost property is not to be picked up except by one who will announce it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1587,"lafz":true},{"key":"muslim","label":"مسلم","number":1353}],"full":1},{"num":5952,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ عُثْمَانَ التَّيْمِيِّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لُقَطَةِ الْحَاجِّ."],"takhrij":"صحيح: رواه مسلم في اللقطة (1724) من طرق عن عبد الله بن وهب، أخبرني عمرو بن الحارث، عن بكير بن عبد الله بن الأشج، عن يحيى بن عبدالله بن عبد الرحمن بن حاطب، عن عبد الرحمن بن عثمان فذكره.","grade":"صحيح","chapter_ar":"باب لا تحل لقطة مكة إلا لمنشد","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1724).","chapter_en":"Lost property of Makkah is not lawful except for one who publicly announces it","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abd al-Rahman ibn Uthman al-Taymi reported that the Messenger of Allah ﷺ forbade taking the lost property of pilgrims."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1724,"lafz":true}],"full":1,"dr":1},{"num":5953,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ بن أَبِي طَالِبٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  لاَ يُخْتَلَى خَلاَهَا، وَلاَ يُنَفَّرُ صَيْدُهَا، وَلاَ تُلْتَقَطُ لُقَطَتُهَا إِلاَّ لِمَنْ أَشَادَ بِهَا."],"takhrij":"حسن: رواه أبوداود (2035) عن ابن المثنى، حدثنا عبد الصمد، حدثنا همام ، حدثنا قتادة ، عن أبي حسان، عن علي - في هذه القصة (يعني تحريم المدينة) قال: فذكره.","grade":"حسن","chapter_ar":"باب لا تحل لقطة المدينة إلا لمنشد","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2035).","chapter_en":"Lost property of Madinah is not lawful except for one who publicly announces it","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Ali ibn Abi Talib reported from the Prophet ﷺ that he said: “Its fresh herbage is not to be cut, its game is not to be driven away, and its lost property is not to be picked up except by one who publicizes it.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2035,"lafz":true}],"full":1,"dr":1},{"num":5954,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ مَرَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِتَمْرَةٍ فِي الطَّرِيقِ قَالَ لَوْلاَ أَنِّي أَخَافُ أَنْ تَكُونَ مِنَ الصَّدَقَةِ لأَكَلْتُهَا."],"takhrij":"متفق عليه: رواه البخاري في اللقطة (2431)، ومسلم في الزكاة (1071) كلاهما من حديث سفيان، عن منصور، عن طلحة بن مصرف، عن أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في قليل اللقطة","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2431) and Muslim (1071).","chapter_en":"What has been reported regarding insignificant found items","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Anas said: The Prophet ﷺ passed by a date lying on the road and said: “Were it not that I fear it might be from charity, I would have eaten it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2431,"lafz":true},{"key":"muslim","label":"مسلم","number":1071}],"full":1},{"num":5955,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِنِّي لأَنْقَلِبُ إِلَى أَهْلِي، فَأَجِدُ التَّمْرَةَ سَاقِطَةً عَلَى فِرَاشِي فَأَرْفَعُهَا لآكُلَهَا، ثُمَّ أَخْشَى أَنْ تَكُونَ صَدَقَةً فَأُلْفِيَهَا."],"takhrij":"متفق عليه: رواه البخاري في اللقطة (2432)، ومسلم في الزكاة (1070: 163) كلاهما من حديث معمر، عن همام بن منبه، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في قليل اللقطة","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2432) and Muslim (1070:163).","chapter_en":"What has been reported regarding insignificant found items","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “I return to my family and find a date fallen on my bed. I pick it up to eat it, then I fear it may be from charity, so I throw it away.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2432,"lafz":true},{"key":"muslim","label":"مسلم","number":163},{"key":"muslim","label":"مسلم في الزكاه","number":1070}],"full":1,"dr":1},{"num":5956,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ خَالِدٍ، الْجُهَنِيِّ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ مَنْ آوَى ضَالَّةً فَهُوَ ضَالٌّ مَا لَمْ يُعَرِّفْهَا."],"takhrij":"صحيح: رواه مسلم في اللقطة (1725) من طرق عن عبد الله بن وهب ، أخبرني عمرو بن الحارث، عن بكر بن سوادة، عن أبي سالم الجيشاني، عن زيد بن خالد الجهني قال:فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من أخذ ضالة المسلم بدون التعريف","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1725).","chapter_en":"The warning against taking a Muslim’s lost property without announcing it","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Zayd ibn Khalid al-Juhani reported that the Messenger of Allah ﷺ said: “Whoever takes possession of lost property is astray so long as he does not announce it.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1725,"lafz":true}],"full":1},{"num":5957,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ يَحْلُبَنَّ أَحَدٌ مَاشِيَةَ امْرِئٍ بِغَيْرِ إِذْنِهِ، أَيُحِبُّ أَحَدُكُمْ أَنْ تُؤْتَى مَشْرُبَتُهُ فَتُكْسَرَ خِزَانَتُهُ، فَيُنْتَقَلَ طَعَامُهُ فَإِنَّمَا تَخْزُنُ لَهُمْ ضُرُوعُ مَوَاشِيهِمْ أَطْعِمَاتِهِمْ، فَلاَ يَحْلُبَنَّ أَحَدٌ مَاشِيَةَ أَحَدٍ إِلاَّ بِإِذْنِهِ."],"takhrij":"متفق عليه: رواه مالك في الاستئذان (17) عن نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب الترهيب من أخذ ضالة المسلم بدون التعريف","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (17), al-Bukhari (2435), and Muslim (1726).","chapter_en":"The warning against taking a Muslim’s lost property without announcing it","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Abdullah ibn Umar said: The Messenger of Allah ﷺ said: “Let none of you milk another man’s livestock without his permission. Would one of you like that someone come to his pantry, break open his storage place, and take away his food? Indeed, the udders of their animals store their food for them, so no one should milk another’s livestock except with his permission.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":17,"lafz":true},{"key":"bukhari","label":"البخاري","number":2435},{"key":"muslim","label":"مسلم","number":1726}],"full":1,"dr":1,"rep":[5485]},{"num":5958,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن الشِّخِّيرِ عَنْ أَبِيهِ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ضَالَّةُ الْمُسْلِمِ حَرَقُ النَّارِ."],"takhrij":"صحيح: رواه ابن ماجه (2502)، وأحمد (16314)، وابن حبان (4888)، والبيهقي (6/191)، والبغوي في شرحه (2209) كلهم من حديث يحيى بن سعيد، عن حميد الطويل، عن الحسن، عن مطرف بن عبد الله بن الشخير، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من أخذ ضالة المسلم بدون التعريف","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2502), Ahmad (16314), Ibn Hibban (4888), and al-Bayhaqi (6/191).","chapter_en":"The warning against taking a Muslim’s lost property without announcing it","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Abdullah ibn al-Shikhkhir said: The Messenger of Allah ﷺ said: “Taking a Muslim’s stray animal for oneself leads to the Fire.”"]},"buhuth":{"en":["His statement, “the burning of the Fire,” means that it becomes a cause for entering the Fire if he takes ownership of it and does not announce it."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2502,"lafz":true},{"key":"ibnhibban","label":"ابن حبان","number":4888,"n":2979},{"key":"kubrabayhaqi","label":"البيهقي","number":191},{"key":"ahmad","label":"مسند الإمام أحمد","number":16314,"n":16289}],"full":1,"dr":1},{"num":5959,"demo":false,"sanad":"","matn":["عن الجارود العبدي قَالَ: بَيْنَمَا نَحْنُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَعْضِ أَسْفَارِهِ وَفِي الظَّهْرِ قِلَّةٌ، إِذْ تَذَاكَرَ الْقَوْمُ الظَّهْرَ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، قَدْ عَلِمْتُ مَا يَكْفِينَا مِنَ الظَّهْرِ، فَقَالَ: وَمَا يَكْفِينَا؟ قُلْتُ: ذَوْدٌ نَأْتِي عَلَيْهِنَّ فِي جُرُفٍ فَنَسْتَمْتِعُ بِظُهُورِهِمْ، قَالَ: لَا، ضَالَّةُ الْمُسْلِمُ حَرَقُ النَّارِ، فَلَا تَقْرَبَنَّهَا، ضَالَّةُ الْمُسْلِمِ حَرَقُ النَّارِ، فَلَا تَقْرَبَنَّهَا، ضَالَّةُ الْمُسْلِمِ حَرَقُ النَّارِ، فَلَا تَقْرَبَنَّهَا، وَقَالَ فِي اللُّقَطَةِ: الضَّالَّةُ تَجِدُهَا فَانْشُدَنَّهَا، وَلَا تَكْتُمْ، وَلَا تُغَيِّبْ، فَإِنْ عُرِفَتْ فَأَدِّهَا، وَإِلَّا فَمَالُ اللهِ يُؤْتِيهِ مَنْ يَشَاءُ."],"takhrij":"حسن: رواه الإمام أحمد (20754) عن إسماعيل، أخبرنا سعيد الجريري، عن أبي العلاء بن الشخير، عن مطرف، قال: حديثان بلغاني عن رسول الله صلى الله عليه وسلم  قد عرفت أن قد صدَّقتهما، لا أدري أيهما قبل صاحبه؟ حدثنا أبو مسلم الجذمي جذيمة عبد القيس، حدثنا الجارود فذكره.","grade":"حسن","chapter_ar":"باب الترهيب من أخذ ضالة المسلم بدون التعريف","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (20754), al-Tabarani in al-Kabir (2/298), al-Darimi (2644, 2643), and Ibn Hibban (4887).","chapter_en":"The warning against taking a Muslim’s lost property without announcing it","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Jarud al-Abdi said: While we were with the Messenger of Allah ﷺ, on one of his journeys, our riding animals had become few. The people discussed the matter of mounts, so I said: O Messenger of Allah ﷺ, you know what would suffice us in mounts. He said: “And what would suffice us?” I said: A small group of animals that we pass by at al-Jurf, and we benefit from riding them. He said: “No. Taking a Muslim’s stray animal for oneself leads to the Fire, so do not go near it. Taking a Muslim’s stray animal for oneself leads to the Fire, so do not go near it. Taking a Muslim’s stray animal for oneself leads to the Fire, so do not go near it.” And regarding found property he said: “If you find lost property, then announce it. Do not conceal it and do not hide it. If it is recognized, then return it. Otherwise, it is the wealth of Allah which He gives to whom He wills.”"]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":298},{"key":"darimi","label":"الدارمي","number":2644},{"key":"ibnhibban","label":"ابن حبان","number":4887},{"key":"ahmad","label":"مسند الإمام أحمد","number":20754,"n":20754,"lafz":true}],"full":1,"dr":1},{"num":5960,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَنِ اللُّقَطَةِ، فَقَالَ: تُعَرَّفْ وَلا تُغَيَّبْ وَلا تُكْتَمْ، فَإِنْ جَاءَ صَاحِبُهَا، وَإِلَّا فَهُوَ مَالُ اللَّهِ يُؤْتِيهِ مَنْ يَشَاءُ."],"takhrij":"صحيح: رواه البزار- كشف الأستار (1367)- عن محمد بن معمر، ثنا الحجاج، ثنا حماد (يعني ابن سلمة)، عن سعيد الجريري، عن أبي العلاء، عن مطرف، عن أبي هريرة قال:فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من أخذ ضالة المسلم بدون التعريف","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bazzar in Kashf al-Astar (1367).","chapter_en":"The warning against taking a Muslim’s lost property without announcing it","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ was asked about found property, and he said: “It is to be announced. It is not to be hidden, nor concealed. If its owner comes, then return it. Otherwise, it is the wealth of Allah that He gives to whom He wills.”"]}},"tuhfa":{},"refs":[{"key":"sh12862","label":"البزار - كشف الأستار","number":1367,"lafz":true}],"full":1,"dr":1},{"num":5961,"demo":false,"sanad":"","matn":["عَنْ عِيَاضِ بْنِ حِمَارٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ وَجَدَ لُقَطَةً فَلْيُشْهِدْ ذَا عَدْلٍ - أَوْ ذَوَىْ عَدْلٍ - وَلاَ يَكْتُمْ وَلاَ يُغَيِّبْ فَإِنْ وَجَدَ صَاحِبَهَا فَلْيَرُدَّهَا عَلَيْهِ وَإِلاَّ فَهُوَ مَالُ اللَّهِ عَزَّ وَجَلَّ يُؤْتِيهِ مَنْ يَشَاءُ."],"takhrij":"صحيح: رواه أبو داود (1709)، وابن ماجه (2505)، وأحمد (17481)، وابن حبان (4894)، والبيهقي (6/187) كلهم من طريق خالد الحذاء، عن أبي العلاء، عن مطرف (يعنى ابن عبد الله)، عن عياض بن حمار قال فذكره. وأبو العلاء هو يزيد بن عبد الله بن الشخير.","grade":"صحيح","chapter_ar":"باب جواز أخذ ضالة المسلم للتعريف بها ثم تملكها","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1709), Ibn Majah (2505), Ahmad (17481), and Ibn Hibban (4894).","chapter_en":"The permissibility of taking a Muslim’s lost property in order to announce it, then owning it afterward","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Iyad ibn Himar said: The Messenger of Allah ﷺ said: “Whoever finds lost property should have one just person, or two just people, bear witness to it. He should neither conceal it nor hide it. If he finds its owner, he must return it to him. Otherwise, it is the wealth of Allah which He gives to whom He wills.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1709,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2505},{"key":"ibnhibban","label":"ابن حبان","number":4894},{"key":"ahmad","label":"مسند الإمام أحمد","number":17481,"n":17481}],"full":1,"dr":1},{"num":5962,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّهَا قَالَتْ لِعُرْوَةَ ابْنَ أُخْتِي، إِنْ كُنَّا لَنَنْظُرُ إِلَى الْهِلاَلِ ثُمَّ الْهِلاَلِ، ثَلاَثَةَ أَهِلَّةٍ فِي شَهْرَيْنِ، وَمَا أُوقِدَتْ فِي أَبْيَاتِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَارٌ. فَقُلْتُ يَا خَالَةُ مَا كَانَ يُعِيشُكُمْ قَالَتِ الأَسْوَدَانِ التَّمْرُ وَالْمَاءُ، إِلاَّ أَنَّهُ قَدْ كَانَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جِيرَانٌ مِنَ الأَنْصَارِ كَانَتْ لَهُمْ مَنَائِحُ، وَكَانُوا يَمْنَحُونَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ أَلْبَانِهِمْ، فَيَسْقِينَا."],"takhrij":"متفق عليه: رواه البخاري في الهبة (2567)، ومسلم في الزهد (2972) كلاهما من حديث عبد العزيز بن أبي حازم، عن أبيه، عن يزيد بن رومان، عن عروة، عن عائشة قالت:فذكرته.","grade":"متفق عليه","chapter_ar":"باب الترغيب في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2567) and Muslim (2972).","chapter_en":"Encouragement to Give Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿĀʾishah said to ʿUrwah: “O son of my sister, we would indeed look at the new moon, then the next new moon, then the next—three new moons in two months—while no fire was kindled in the houses of the Messenger of Allāh ﷺ.” I said, “O aunt, what sustained you?” She replied, “The two black things: dates and water. Except that the Messenger of Allāh ﷺ had neighbors from among the Anṣār who owned milch animals that they lent for their milk, and they would give the Messenger of Allāh ﷺ some of their milk, and he would give it to us to drink.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2567,"lafz":true},{"key":"muslim","label":"مسلم","number":2972}],"full":1},{"num":5963,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ يَا نِسَاءَ الْمُسْلِمَاتِ لاَ تَحْقِرَنَّ جَارَةٌ لِجَارَتِهَا وَلَوْ فِرْسِنَ شَاةٍ."],"takhrij":"متفق عليه: رواه البخاري في كتاب الأدب (6017)، ومسلم في الزكاة (1030) كلاهما من حديث الليث بن سعد، عن سعيد بن أبي سعيد، عن أبيه، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب الترغيب في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6017) and Muslim (1030).","chapter_en":"Encouragement to Give Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ said: “O Muslim women, no woman should consider insignificant a gift to her neighbor, even if it is only the hoof of a sheep.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6017,"lafz":true},{"key":"muslim","label":"مسلم","number":1030}],"full":1,"rep":[14166]},{"num":5964,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: تَهَادُوا تَحَابُّوا."],"takhrij":"حسن: رواه البخاري في الأدب المفرد (594)، والدولابي في الكنى (1/150)، والبيهقي (6/169) كلهم من طريق ضِمام بن إسماعيل، عن موسى بن وردان، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب الترغيب في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bukhārī in al-Adab al-Mufrad (594), al-Dūlābī in al-Kunā (1/150), and al-Bayhaqī (6/169).","chapter_en":"Encouragement to Give Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ said: “Exchange gifts, and you will love one another.”"]}},"tuhfa":{},"refs":[{"key":"adab","label":"البخاري في الأدب المفرد","number":594,"lafz":true},{"key":"rb341","label":"الدولابي في الكنى","number":150},{"key":"kubrabayhaqi","label":"البيهقي","number":169,"n":156},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":11946,"n":12057}],"full":1,"dr":1},{"num":5965,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَوْ دُعِيتُ إِلَى ذِرَاعٍ أَوْ كُرَاعٍ لأَجَبْتُ، وَلَوْ أُهْدِيَ إِلَىَّ ذِرَاعٌ أَوْ كُرَاعٌ لَقَبِلْتُ."],"takhrij":"صحيح: رواه البخاري في الهبة (2568) عن محمد بن بشار، حدثنا ابن أبي عدي، عن شعبة، عن سليمان، عن أبي حازم، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب قبول القليل من الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (2568).","chapter_en":"Accepting Even a Small Gift","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ said: “If I were invited to a meal consisting of a foreleg or a lower leg, I would accept the invitation; and if a foreleg or a lower leg were given to me as a gift, I would accept it.”"]},"buhuth":{"en":["His saying, “kurāʿ”, refers in a human being to the portion below the knee down to the ankle, and in cattle and sheep to the thin lower part of the leg that has little flesh upon it. It is what is commonly known today as the feet or lower part of the leg."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2568,"lafz":true}],"full":1,"dr":1,"rep":[9586,13101]},{"num":5966,"demo":false,"sanad":"","matn":["عَنْ أنس بْنِ مَالِكٍ قَالَ: أَنْفَجْنَا أَرْنَبًا بِمَرِّ الظَّهْرَانِ، فَسَعَى الْقَوْمُ، فَلَغَبُوا، فَأَدْرَكْتُهَا، فَأَخَذْتُهَا، فَأَتَيْتُ بِهَا أَبَا طَلْحَةَ، فَذَبَحَهَا، وَبَعَثَ بِهَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِوَرِكِهَا أوفخذيها. -قَالَ: فَخِذَيْهَا، لاَ شَكَّ فِيهِ- فَقَبِلَهُ. قُلْتُ: وَأَكَلَ مِنْهُ؟ قَالَ: وَأَكَلَ مِنْهُ، ثُمَّ قـال بعدُ: قَبِله. (أي لَمْ يأكل مِنْهُ)."],"takhrij":"متفق عليه: رواه البخاري في الهبة (2572)، ومسلم في كتاب الصيد (1953) كلاهما من حديث شعبة، عن هشام بن زيد بن أنس بن مالك، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب قبول هدايا المسلمين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2572) and Muslim (1953). The wording is that of al-Bukhārī.","chapter_en":"Accepting the Gifts of Muslims","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Anas ibn Mālik said: “We startled a rabbit at Marr al-Ẓahrān, and the people ran after it until they became exhausted. I caught up with it and seized it, then brought it to Abū Ṭalḥah. He slaughtered it and sent its hips—or its two thighs—to the Messenger of Allāh ﷺ.” He later said: “Its two thighs, without doubt.” The Prophet ﷺ accepted it. I asked, “Did he eat from it?” He replied, “He ate from it,” but afterward he said, “He accepted it,” meaning that he did not eat from it."]},"buhuth":{"en":["His statement, “لغبوا” means: they became tired."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2572,"lafz":true},{"key":"muslim","label":"مسلم","number":1953}],"full":1,"dr":1},{"num":5967,"demo":false,"sanad":"","matn":["عَنِ الصَّعْبِ بْنِ جَثَّامَةَ رَضِيَ اللَّهُ عَنْهُمْ أَنَّهُ أَهْدَى لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِمَارًا وَحْشِيًّا وَهْوَ بِالأَبْوَاءِ أَوْ بِوَدَّانَ فَرَدَّ عَلَيْهِ، فَلَمَّا رَأَى مَا فِي وَجْهِهِ قَالَ أَمَا إِنَّا لَمْ نَرُدَّهُ عَلَيْكَ إِلاَّ أَنَّا حُرُمٌ."],"takhrij":"متفق عليه: رواه مالك في الموطأ عن ابن شهاب، عن عبيدالله بن عبد الله بن عتبة بن مسعود، عن عبد الله بن عباس، عن الصعب بن جثامة فذكره.","grade":"متفق عليه","chapter_ar":"باب قبول هدايا المسلمين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik, al-Bukhārī (2573), and Muslim (1192).","chapter_en":"Accepting the Gifts of Muslims","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Al-Ṣaʿb ibn Jaththāmah reported that he presented the Messenger of Allāh ﷺ with a wild donkey while he was at al-Abwāʾ or Waddān. The Prophet ﷺ returned it to him. When he saw the expression on his face, he said: “We only returned it to you because we are in the state of iḥrām.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2573,"lafz":true},{"key":"muslim","label":"مسلم","number":1192,"n":2845}],"full":1,"dr":1},{"num":5968,"demo":false,"sanad":"","matn":["عَنْ الْمُغِيرَةِ بن شُعْبَةَ: أَهْدَى دِحْيَةُ الْكَلْبِيُّ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خُفَّيْنِ فَلَبِسَهُمَا."],"takhrij":"صحيح: رواه الترمذي في السنن (1769) وفي الشمائل (70) وأبو الشيخ في أخلاق النبي صلى الله عليه وسلم  (ص: 116) كلاهما من طريق الحسن بن عياش، عن أبي إسحاق وهو الشيباني، عن عامر الشعبي، عن المغيرة بن شعبة: فذكره.","grade":"صحيح","chapter_ar":"باب قبول هدايا المسلمين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Tirmidhī (1769), in al-Shamāʾil (70), and Abū al-Shaykh in Akhlāq al-Nabī ﷺ (p. 116).","chapter_en":"Accepting the Gifts of Muslims","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah reported: Diḥyah al-Kalbī presented the Messenger of Allāh ﷺ with a pair of leather socks, and he wore them."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1769,"lafz":true},{"key":"shamail","label":"وفي الشمائل","number":70,"n":73},{"key":"rb501","label":"أبو الشيخ في أخلاق النبي ﷺ","number":116}],"full":1,"dr":1},{"num":5969,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ قَالَ: فَقَالَ رَجُلٌ عِنْدَ الْمُغِيرَةِ بْنِ شُعْبَةَ: يَا مُغِيرَةُ وَمَنْ أَيْنَ كَانَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خُفَّانِ؟ قَالَ: فَقَالَ الْمُغِيرَةُ: أَهْدَاهُمَا إِلَيْهِ النَّجَاشِيُّ."],"takhrij":"صحيح: رواه البيهقي (1/283) عن أبي عبد الله الحاكم، عن أبي العباس محمد بن يعقوب، عن العباس بن محمد الدوري، عن عمر بن حفص بن غياث، عن أبي إسحاق الشيباني، عن الشعبي، عن المغيرة بن شعبة، فذكره.","grade":"صحيح","chapter_ar":"باب قبول هدايا المسلمين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bayhaqī (1/283).","chapter_en":"Accepting the Gifts of Muslims","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah reported that the Messenger of Allāh ﷺ performed ablution and wiped over his leather socks. A man who was with al-Mughīrah ibn Shuʿbah said, “O Mughīrah, from where did the Prophet ﷺ obtain the two leather socks?” Al-Mughīrah replied, “The Negus presented them to him as a gift.”"]}},"tuhfa":{},"refs":[{"key":"kubrabayhaqi","label":"البيهقي","number":283,"lafz":true},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":1346,"n":1359}],"full":1,"dr":1},{"num":5970,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الحصيب: أَنَّ النَّجَاشِيَّ أَهْدَى لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خُفَّيْنِ أَسْوَدَيْنِ سَاذَجَيْنِ، فَلَبِسَهُمَا، ثُمَّ تَوَضَّأَ وَمَسَحَ عَلَيْهِمَا."],"takhrij":"حسن: رواه أبو داود (155) والترمذي (2820) وفي الشمائل (69) وابن ماجه (549)، (3620) وأحمد (22981) كلهم من طريق وكيع، حدثنا دلهم بن صالح الكندي، عن حجير بن عبدالله الكندي، عن عبدالله بن بريدة بن الحصيب، عن أبيه، فذكره.","grade":"حسن","chapter_ar":"باب قبول هدايا المسلمين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (155), al-Tirmidhī (2820), in al-Shamāʾil (69), Ibn Mājah (3620), (549), and Aḥmad (22981).","chapter_en":"Accepting the Gifts of Muslims","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Buraydah ibn al-Ḥuṣayb reported that the Negus presented the Prophet ﷺ with a pair of plain black leather socks. He put them on, then performed ablution and wiped over them."]},"buhuth":{"en":["Regarding the expression “plain black” (ساذجين): sādhaj, with either a fatḥah or kasrah on the dhāl, means something pure and unmixed, without decoration or patterns."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":155,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":2820},{"key":"shamail","label":"وفي الشمائل","number":69,"n":72},{"key":"ibnmajah","label":"ابن ماجه","number":3620},{"key":"ahmad","label":"مسند الإمام أحمد","number":22981,"n":22981},{"key":"ibnmajah","label":"ابن ماجه","number":549}],"full":1,"dr":1},{"num":5971,"demo":false,"sanad":"","matn":["عَنْ أُسَامَةَ بن زَيْدٍ، قَالَ: كَسَانِي رَسُولُ قُبْطِيَّة كثيقة مِمَّا أَهْدَاهَا لَهُ دِحْيَةُ الْكَلْبِيُّ، فَكَسَوْتُهَا امْرَأَتِي، فَقَالَ: مَا لَكَ لَمْ تَلْبَسِ الْقُبْطِيَّةَ؟ قُلْتُ: كَسَوْتُهَا امْرَأَتِي، فَقَالَ: مُرْهَا فَلْتَجْعَلْ تَحْتَهَا غِلَالَةً، فَإِنِّي أَخَافُ أَنْ تَصِفَ عِظَامَهَا."],"takhrij":"حسن: رواه أحمد (21786) ، (21788) والبيهقي (2/234) والضياء في المختارة (1365-1366) من طريق عبدالله بن محمد بن عقيل، عن محمد بن أسامة بن زيد، عن أبيه، قال: فذكره.","grade":"حسن","chapter_ar":"باب قبول هدايا المسلمين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (21788, 21786), al-Bayhaqī (2/234), and al-Ḍiyāʾ in al-Mukhtārah (1365–1366).","chapter_en":"Accepting the Gifts of Muslims","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Usāmah ibn Zayd said: “The Messenger of Allāh ﷺ clothed me in a thick Qibṭiyyah garment from among those that Diḥyah al-Kalbī had presented to him. I gave it to my wife to wear. He said, ‘Why have you not worn the Qibṭiyyah?’ I replied, ‘I gave it to my wife to wear.’ He said: ‘Tell her to wear an undergarment beneath it, for I fear that it may reveal the shape of her bones.’”"]},"buhuth":{"en":["His saying, “al-Qibṭiyyah” refers to garments of fine linen that were manufactured in Egypt. They are attributed to the Copts in this irregular linguistic form in order to distinguish the garment from a person of Coptic origin.","His saying, “ghilālah” refers to a thin garment worn underneath an outer garment."]}},"tuhfa":{},"refs":[{"key":"kubrabayhaqi","label":"البيهقي","number":234},{"key":"sh10480","label":"الضياء في المختارة","number":1366,"n":1367},{"key":"ahmad","label":"مسند الإمام أحمد","number":21788,"n":21788,"lafz":true},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":3262,"n":3275},{"key":"ahmad","label":"احمد","number":21786,"n":21788},{"key":"sh10480","label":"الضياء في المختاره","number":1365,"n":1367}],"full":1,"dr":1},{"num":5972,"demo":false,"sanad":"","matn":["عَنْ الْعَبَّاسِ بن عبدالمطلب قَالَ: شَهِدْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ حُنَيْنٍ، فَلَزِمْتُ أَنَا وَأَبُو سُفْيَانَ بْنُ الْحَارِثِ بْنِ عبـــــدالمطلب رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَلَمْ نُفَارِقْهُ، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى بَغْلَةٍ لَهُ بَيْضَاءَ أَهْدَاهَا لَهُ فَرْوَةُ بْنُ نُفَاثَةَ الجذامى...فَذَكَرَ الْحَدِيثَ."],"takhrij":"صحيح: رواه مسلم في الجهاد والسير (1775/76) عن أبي الطاهر أحمد بن عمرو بن سرح، أخبرنا ابن وهب، أخبرني يونس، عن ابن شهاب، قال: حدثني كثير بن عباس بن عبد المطلب، قال: قال عباس: فذكره.","grade":"صحيح","chapter_ar":"باب قبول هدايا المسلمين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1775/76).","chapter_en":"Accepting the Gifts of Muslims","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Al-ʿAbbās ibn ʿAbd al-Muṭṭalib said: “I was present with the Messenger of Allāh ﷺ on the Day of Ḥunayn. Abū Sufyān ibn al-Ḥārith ibn ʿAbd al-Muṭṭalib and I remained close beside the Messenger of Allāh ﷺ and did not leave him. The Messenger of Allāh ﷺ was riding a white mule that Farwah ibn Nufāthah al-Judhāmī had presented to him as a gift…” Then he mentioned the rest of the hadith."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":76,"lafz":true}],"full":1,"dr":1},{"num":5973,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: كَسَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حُلَّةً مِنْ حُلَلِ السِّيَرَاءِ أَهْدَاهَا لَهُ فَيْرُوزُ، فَلَبِسْتُ الْإِزَارَ فَأَغْرَقَنِي طُولًا وَعَرْضًا، فَسَحَبْتُهُ وَلَبِسْتُ الرِّدَاءَ، فَتَقَنَّعْتُ بِهِ، فَأَخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِعَاتِقِي فَقَالَ: يَا عَبْدَ اللَّهِ بْنَ عُمَرَ، ارْفَعِ الْإِزَارَ، فَإِنَّ مَا مَسَّتِ الْأَرْضُ مِنَ الْإِزَارِ إِلَى مَا أَسْفَلَ مِنَ الْكَعْبَيْنِ فِي النَّارِ قَالَ عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ: فَلَمْ أَرَ إِنْسَانًا قَطُّ أَشَدَّ تَشْمِيرًا مِنْ عَبْدِ اللَّهِ بْنِ عُمَرَ."],"takhrij":"حسن: رواه أحمد (5713) وأبو يعلى (5714) من طريقين، عن عبيدالله بن عمر، عن عبدالله بن محمد بن عقيل، عن ابن عمر، فذكره.","grade":"حسن","chapter_ar":"باب قبول هدايا المسلمين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (5713) and Abū Yaʿlā (5714).","chapter_en":"Accepting the Gifts of Muslims","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿUmar said: “The Messenger of Allāh ﷺ clothed me in one of the siyarāʾ garments that Fayrūz had presented to him. I put on the lower garment, but it overwhelmed me in both length and width, so I dragged it. I then put on the upper garment and wrapped it around myself. The Messenger of Allāh ﷺ took hold of my shoulder and said: ‘O ʿAbdullāh, raise your lower garment, for whatever part of the garment touches the ground below the ankles is in the Fire.’” ʿAbdullāh ibn Muḥammad said: “I never saw anyone who kept his garment raised more strictly than ʿAbdullāh ibn ʿUmar.”"]}},"tuhfa":{},"refs":[{"key":"sh12520","label":"أبو يعلى","number":5714},{"key":"ahmad","label":"مسند الإمام أحمد","number":5713,"n":5713,"lafz":true}],"full":1,"dr":1,"rep":[15369]},{"num":5974,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن بُسْرٍ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْبَلُ الْهَدِيَّةَ، وَلَا يَقْبَلُ الصَّدَقَةَ."],"takhrij":"حسن: رواه أحمد (17688) عن هشام بن سعيد، حدثني الحسن بن أيوب الحضرمي، حدثني عبد الله بن بسر، فذكره.","grade":"حسن","chapter_ar":"باب قبول هدايا المسلمين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (17688).","chapter_en":"Accepting the Gifts of Muslims","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullāh ibn Busr said: “The Messenger of Allāh ﷺ would accept gifts, but he would not accept charity.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":17688,"n":17688,"lafz":true}],"full":1,"dr":1},{"num":5975,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن مَسْعُودٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَجِيبُوا الدَّاعِيَ، وَلَا تَرُدُّوا الْهَدِيَّةَ، وَلَا تَضْرِبُوا الْمُسْلِمِينَ."],"takhrij":"صحيح: رواه أحمد (3838) والبخاري في الأدب المفرد (157) والبزار –كشف الأستار (1243) والطبراني في الكبير (10/242) وصحّحه ابن حبان (5603) كلهم من طرق عن الأعمش، عن شقيق، عن عبدالله، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب قبول هدايا المسلمين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (3838), al-Bukhārī in al-Adab al-Mufrad (157), and al-Bazzār in Kashf al-Astār (1243).","chapter_en":"Accepting the Gifts of Muslims","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Ibn Masʿūd reported that the Messenger of Allāh ﷺ said: “Respond to the one who invites you, do not reject a gift, and do not strike the Muslims.”"]}},"tuhfa":{},"refs":[{"key":"adab","label":"البخاري في الأدب المفرد","number":157},{"key":"sh12862","label":"البزار - كشف الأستار","number":1243},{"key":"ahmad","label":"مسند الإمام أحمد","number":3838,"n":3838,"lafz":true},{"key":"ibnhibban","label":"ابن حبان","number":5603}],"full":1},{"num":5976,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ: أَنَّ النَّاسَ كَانُوا يَتَحَرَّوْنَ بِهَدَايَاهُمْ يَوْمَ عَائِشَةَ. يَبْتَغُونَ بِذَلِكَ مَرْضَاةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ."],"takhrij":"متفق عليه: رواه البخاري في الهبة (2574)، ومسلم في كتاب فضائل الصحابة (2441) كلاهما من حديث عبدة، حدثنا هشام، عن أبيه، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب من تحرى وجود النبي ﷺ عند بعض نسائه دون بعض لتقديم الهدايا له لا يخالف العدل","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2574) and Muslim (2441).","chapter_en":"Those Who Sought the Time When the Prophet ﷺ Was with Certain Wives Rather Than Others in Order to Present Their Gifts to Him — This Does Not Contradict Justice","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿĀʾishah reported that the people used to deliberately choose ʿĀʾishah’s day to present their gifts, seeking thereby to please the Messenger of Allāh ﷺ."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2574,"lafz":true},{"key":"muslim","label":"مسلم","number":2441}],"full":1},{"num":5977,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ نِسَاءَ، رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُنَّ حِزْبَيْنِ فَحِزْبٌ فِيهِ عَائِشَةُ وَحَفْصَةُ وَصَفِيَّةُ وَسَوْدَةُ، وَالْحِزْبُ الآخَرُ أُمُّ سَلَمَةَ وَسَائِرُ نِسَاءِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ الْمُسْلِمُونَ قَدْ عَلِمُوا حُبَّ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَائِشَةَ، فَإِذَا كَانَتْ عِنْدَ أَحَدِهِمْ هَدِيَّةٌ يُرِيدُ أَنْ يُهْدِيَهَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَّرَهَا، حَتَّى إِذَا كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَيْتِ عَائِشَةَ بَعَثَ صَاحِبُ الْهَدِيَّةِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَيْتِ عَائِشَةَ، فَكَلَّمَ حِزْبُ أُمِّ سَلَمَةَ، فَقُلْنَ لَهَا كَلِّمِي رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُكَلِّمُ النَّاسَ، فَيَقُولُ مَنْ أَرَادَ أَنْ يُهْدِيَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَدِيَّةً فَلْيُهْدِهِ إِلَيْهِ حَيْثُ كَانَ مِنْ بُيُوتِ نِسَائِهِ، فَكَلَّمَتْهُ أُمُّ سَلَمَةَ بِمَا قُلْنَ، فَلَمْ يَقُلْ لَهَا شَيْئًا، فَسَأَلْنَهَا. فَقَالَتْ مَا قَالَ لِي شَيْئًا. فَقُلْنَ لَهَا فَكَلِّمِيهِ. قَالَتْ فَكَلَّمَتْهُ حِينَ دَارَ إِلَيْهَا أَيْضًا، فَلَمْ يَقُلْ لَهَا شَيْئًا، فَسَأَلْنَهَا. فَقَالَتْ مَا قَالَ لِي شَيْئًا. فَقُلْنَ لَهَا كَلِّمِيهِ حَتَّى يُكَلِّمَكِ. فَدَارَ إِلَيْهَا فَكَلَّمَتْهُ. فَقَالَ لَهَا لاَ تُؤْذِينِي فِي عَائِشَةَ، فَإِنَّ الْوَحْىَ لَمْ يَأْتِنِي، وَأَنَا فِي ثَوْبِ امْرَأَةٍ إِلاَّ عَائِشَةَ. قَالَتْ فَقَالَتْ أَتُوبُ إِلَى اللَّهِ مِنْ أَذَاكَ يَا رَسُولَ اللَّهِ. ثُمَّ إِنَّهُنَّ دَعَوْنَ فَاطِمَةَ بِنْتَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَرْسَلْنَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَقُولُ إِنَّ نِسَاءَكَ يَنْشُدْنَكَ اللَّهَ الْعَدْلَ فِي بِنْتِ أَبِي بَكْرٍ. فَكَلَّمَتْهُ. فَقَالَ يَا بُنَيَّةُ، أَلاَ تُحِبِّينَ مَا أُحِبُّ. قَالَتْ بَلَى. فَرَجَعَتْ إِلَيْهِنَّ، فَأَخْبَرَتْهُنَّ. فَقُلْنَ ارْجِعِي إِلَيْهِ. فَأَبَتْ أَنْ تَرْجِعَ، فَأَرْسَلْنَ زَيْنَبَ بِنْتَ جَحْشٍ، فَأَتَتْهُ فَأَغْلَظَتْ، وَقَالَتْ إِنَّ نِسَاءَكَ يَنْشُدْنَكَ اللَّهَ الْعَدْلَ فِي بِنْتِ ابْنِ أَبِي قُحَافَةَ. فَرَفَعَتْ صَوْتَهَا، حَتَّى تَنَاوَلَتْ عَائِشَةَ. وَهْىَ قَاعِدَةٌ، فَسَبَّتْهَا حَتَّى إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيَنْظُرُ إِلَى عَائِشَةَ هَلْ تَكَلَّمُ قَالَ فَتَكَلَّمَتْ عَائِشَةُ تَرُدُّ عَلَى زَيْنَبَ، حَتَّى أَسْكَتَتْهَا. قَالَتْ فَنَظَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى عَائِشَةَ، وَقَالَ إِنَّهَا بِنْتُ أَبِي بَكْرٍ."],"takhrij":"متفق عليه: رواه البخاري في الهبة (2581)، عن إسماعيل قال: حدثني أخي، عن سليمان، عن هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب من تحرى وجود النبي ﷺ عند بعض نسائه دون بعض لتقديم الهدايا له لا يخالف العدل","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2581) and Muslim (2442).","chapter_en":"Those Who Sought the Time When the Prophet ﷺ Was with Certain Wives Rather Than Others in Order to Present Their Gifts to Him — This Does Not Contradict Justice","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿĀʾishah said: “The wives of the Messenger of Allāh ﷺ were divided into two groups. One group consisted of ʿĀʾishah, Ḥafṣah, Ṣafiyyah, and Sawdah, while the other group consisted of Umm Salamah and the rest of the wives of the Messenger of Allāh ﷺ. “The Muslims knew of the Messenger of Allāh’s ﷺ love for ʿĀʾishah. So whenever one of them had a gift that he wished to present to the Messenger of Allāh ﷺ, he would delay it until the Messenger of Allāh ﷺ was in ʿĀʾishah’s house; then the owner of the gift would send it to the Messenger of Allāh ﷺ while he was in ʿĀʾishah’s house. “The group of Umm Salamah discussed the matter and said to her, ‘Speak to the Messenger of Allāh ﷺ and ask him to tell the people: Whoever wishes to present a gift to the Messenger of Allāh ﷺ should present it to him wherever he happens to be among the houses of his wives.’ “Umm Salamah spoke to him about what they had said, but he said nothing to her. They asked her what had happened, and she said, ‘He said nothing to me.’ They said, ‘Then speak to him again.’ She said, ‘I spoke to him again when my turn came, but he said nothing to me.’ They asked her, and she replied, ‘He said nothing to me.’ They said, ‘Keep speaking to him until he answers you.’ “When her turn came again, she spoke to him. He said to her: ‘Do not hurt me regarding ʿĀʾishah, for revelation never came to me while I was under the covering of any woman except ʿĀʾishah.’ “She said, ‘I repent to Allāh for causing you hurt, O Messenger of Allāh.’ “Then they called Fāṭimah, the daughter of the Messenger of Allāh ﷺ, and sent her to the Messenger of Allāh ﷺ saying, ‘Your wives adjure you to observe justice regarding the daughter of Abū Bakr.’ She spoke to him, and he said: ‘O my daughter, do you not love what I love?’ She replied, ‘Yes.’ She returned to them and informed them. They said, ‘Go back to him,’ but she refused to return. “They then sent Zaynab bint Jaḥsh. She came to him and spoke harshly, saying, ‘Your wives adjure you by Allāh to observe justice regarding the daughter of Ibn Abī Quḥāfah.’ She raised her voice until she turned upon ʿĀʾishah, who was sitting there, and insulted her. The Messenger of Allāh ﷺ kept looking at ʿĀʾishah to see whether she would respond. “ʿĀʾishah then spoke and replied to Zaynab until she silenced her. The Prophet ﷺ looked at ʿĀʾishah and said: ‘Indeed, she is the daughter of Abū Bakr.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2581,"lafz":true},{"key":"muslim","label":"مسلم","number":2442}],"full":1,"dr":1,"rep":[6398]},{"num":5978,"demo":false,"sanad":"","matn":["عَنْ أنس قَالَ: إن النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ لاَ يرُدُّ الطِّيبَ."],"takhrij":"صحيح: رواه البخاري في الهبة (2582) عن أبي معمر، حدثنا عبدالوارث، حدثنا عزرة بن ثابت الأنصاري قال: حدثني ثمامة بن عبد الله قال: دخلت عليه فناولني طيبا. قال: كان أنس لا يرد الطيب. قال: وزعم أنس أن النبي صلى الله عليه وسلم  كان لا يردُّ الطيبَ.","grade":"صحيح","chapter_ar":"باب ما لا يرد من الهدية","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (2582).","chapter_en":"Gifts That Should Not Be Refused","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Anas said: “The Prophet ﷺ would not refuse perfume.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2582,"lafz":true}],"full":1},{"num":5979,"demo":false,"sanad":"","matn":["عن مُسْلِمِ بن جُنْدُبٍ أَنَّهُ: دَخَلَ مَعَ عَبْدِ الله بن عُمَرَ عَلَى ابْنِ مُطِيعٍ ، فَقَالَ: السَّلامُ عَلَيْكَ، فَقَالَ: وَعَلَيْكَ السَّلامُ وَرَحْمَةُ الله، وَمَرْحَبًا وَأَهْلا بِأَبِي عَبْدِالرَّحْمَنِ ضَعُوا لَهُ وِسَادَةً ، فَقَالَ ابْنُ عُمَرَ: لَوْلا أَنِّي سَمِعْتُ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  يَقُولُ: ثَلاثٌ لا تُرَدُّ: اللَّبَنُ ، وَلا الْوِسَادَةُ ، وَلا الدُّهْنُ. مَا جَلَسْتُ عَلَيْهَا."],"takhrij":"حسن: رواه الترمذي (2790)، والطبراني في الكبير (12/336) –والسياق له-، والبيهقي في الشعب (5677) كلهم من طريق ابن أبي فُديك، حدثني عبدالله بن مسلم بن جندب، عن أبيه قال: فذكره.","grade":"حسن","chapter_ar":"باب ما لا يرد من الهدية","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2790), al-Ṭabarānī (12/336)—whose wording this is—and al-Bayhaqī in al-Shuʿab (5677).","chapter_en":"Gifts That Should Not Be Refused","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Muslim ibn Jundub reported that he entered with ʿAbdullāh ibn ʿUmar upon Ibn Muṭīʿ. Ibn ʿUmar said, “Peace be upon you.” He replied, “And upon you be peace and the mercy of Allāh. Welcome, and greetings to Abū ʿAbd al-Raḥmān. Place a cushion for him.” Ibn ʿUmar said: “Had I not heard the Messenger of Allāh ﷺ say, ‘Three things are not to be refused: milk, a cushion, and scented oil,’ I would not have sat upon it.”"]},"buhuth":{"en":["His saying, “al-duhn” here means perfume or scented oil."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":2790,"lafz":true},{"key":"mujamkabir","label":"الطبراني","number":336},{"key":"shuabiman","label":"البيهقي في الشعب","number":5677},{"key":"kubrabayhaqi","label":"البيهقي في الشعب","number":5677}],"full":1,"dr":1},{"num":5980,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْبَلُ الْهَدِيَّةَ، ويُثِيب عَلَيْهَا."],"takhrij":"صحيح: رواه البخاري في الهبة (2585) عن مسدد، حدثنا عيسى بن يونس، عن هشام، عن أبيه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب المكافأة في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (2585).","chapter_en":"Giving Something in Return for a Gift","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["ʿĀʾishah, the wife of the Prophet ﷺ, said: “The Messenger of Allāh ﷺ would accept gifts and give something in return for them.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2585,"lafz":true}],"full":1,"dr":1,"rep":[4272]},{"num":5981,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ: أَنَّ أَعْرَابِيًّا وَهَبَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هِبَةً، فَأَثَابَهُ عَلَيْهَا، قَالَ: رَضِيتَ؟ قَالَ: لَا. قَالَ: فَزَادَهُ، قَالَ: رَضِيتَ؟ قَالَ: لَا. قَالَ: فَزَادَهُ، قَالَ: رَضِيتَ؟ قَالَ: نَعَمْ. قَالَ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَقَدْ هَمَمْتُ أَنْ لَا أَتَّهِبَ هِبَةً إِلا مِنْ قُرَشِيٍّ، أَوْ أَنْصَارِيٍّ، أَوْ ثَقَفِيٍّ."],"takhrij":"صحيح: رواه أحمد (2687)، والطبراني في الكبير (10897)، والبزار-كشف الأستار (1938)-، كلهم من طريق يونس قال: حدثنا حماد بن زيد، عن عمرو بن دينار، عن طاوس، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ترك النبي ﷺ قبول الهدية إلا عن قبائل معروفة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (2687), al-Ṭabarānī in al-Kabīr (10897), and al-Bazzār in Kashf al-Astār (1938).","chapter_en":"The Prophet ﷺ Refraining from Accepting Gifts Except from Certain Well-Known Tribes","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbās reported that a Bedouin gave the Prophet ﷺ a gift, and the Prophet ﷺ gave him something in return. He asked, “Are you satisfied?” The man replied, “No.” So he gave him more and asked, “Are you satisfied?” He replied, “No.” So he gave him still more and asked, “Are you satisfied?” He replied, “Yes.” The Messenger of Allāh ﷺ then said: “I had considered not accepting a gift except from a Qurashī, an Anṣārī, or a Thaqafī.”"]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":10897},{"key":"sh12862","label":"البزار - كشف الأستار","number":1938},{"key":"ahmad","label":"مسند الإمام أحمد","number":2687,"n":2687,"lafz":true}],"full":1,"dr":1},{"num":5982,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ أَهْدَى رَجُلٌ مِنْ بَنِي فَزَارَةَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَاقَةً مِنْ إِبِلِهِ الَّتِي كَانُوا أَصَابُوا بِالْغَابَةِ فَعَوَّضَهُ مِنْهَا بَعْضَ الْعِوَضِ فَتَسَخَّطَهُ فَسَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى هَذَا الْمِنْبَرِ يَقُولُ إِنَّ رِجَالاً مِنَ الْعَرَبِ يُهْدِي أَحَدُهُمُ الْهَدِيَّةَ فَأُعَوِّضُهُ مِنْهَا بِقَدْرِ مَا عِنْدِي ثُمَّ يَتَسَخَّطُهُ فَيَظَلُّ يَتَسَخَّطُ فِيهِ عَلَىَّ وَايْمُ اللَّهِ لاَ أَقْبَلُ بَعْدَ مَقَامِي هَذَا مِنْ رَجُلٍ مِنَ الْعَرَبِ هَدِيَّةً إِلاَّ مِنْ قُرَشِيٍّ أَوْ أَنْصَارِيٍّ أَوْ ثَقَفِيٍّ أَوْ دَوْسِيٍّ."],"takhrij":"حسن: رواه الترمذي (3946) عن محمد بن إسماعيل، حدثنا أحمد بن خالد الحمصي، حدثنا محمد بن إسحاق، عن سعيد بن أبي سعيد المقبري، عن أبيه، عن أبي هريرة فذكره. وهو في الأدب المفرد (596) من هذا الوجه.","grade":"حسن","chapter_ar":"باب ترك النبي ﷺ قبول الهدية إلا عن قبائل معروفة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3946), al-Bukhārī in al-Adab al-Mufrad (596), and Abū Dāwūd (3537).","chapter_en":"The Prophet ﷺ Refraining from Accepting Gifts Except from Certain Well-Known Tribes","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abū Hurayrah said: “A man from Banū Fazārah presented the Prophet ﷺ with a she-camel from among the camels they had acquired at al-Ghābah. The Prophet ﷺ compensated him for it with something, but the man was displeased with the compensation. “I then heard the Messenger of Allāh ﷺ say from this pulpit: ‘There are men among the Arabs, one of whom gives me a gift, and I compensate him according to what I have available, yet afterward he becomes displeased with it and continues expressing his dissatisfaction toward me. By Allāh, after this occasion of mine, I will not accept a gift from any Arab man except a Qurashī, an Anṣārī, a Thaqafī, or a Dawsī.’”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":3946,"lafz":true},{"key":"adab","label":"البخاري في الأدب المفرد","number":596},{"key":"abudawud","label":"أبو داود","number":3537}],"full":1,"dr":1},{"num":5983,"demo":false,"sanad":"","matn":["عَنِ النُّعْمَانِ بْنِ بَشِيرٍ، أَنَّهُ قَالَ إِنَّ أَبَاهُ أَتَى بِهِ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ إِنِّي نَحَلْتُ ابْنِي هَذَا غُلاَمًا كَانَ لِي. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَكُلَّ وَلَدِكَ نَحَلْتَهُ مِثْلَ هَذَا. فَقَالَ لاَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"متفق عليه: رواه مالك في الأقضية (41) عن ابن شهاب، عن حميد بن عبد الرحمن بن عوف ومحمد بن النعمان بن بشير، أنهما حدثاه عن النعمان بن بشير فذكره. ورواه البخاري في الهبة (2586)، ومسلم في الهبات (1623) كلاهما من طريق مالك.","grade":"متفق عليه","chapter_ar":"باب العدل بين الأولاد في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (41), al-Bukhārī (2586), and Muslim (1623).","chapter_en":"Justice Between One’s Children in Giving Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr reported that his father, Bashīr, brought him to the Prophet ﷺ and said, “I have given this son of mine a slave who belonged to me.” The Messenger of Allāh ﷺ asked: “Have you given every one of your children something like this?” He replied, “No.” The Messenger of Allāh ﷺ said: “Then take it back.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":41,"lafz":true},{"key":"bukhari","label":"البخاري","number":2586},{"key":"muslim","label":"مسلم","number":1623}],"full":1},{"num":5984,"demo":false,"sanad":"","matn":["عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ سَأَلَتْ أُمِّي أَبِي بَعْضَ الْمَوْهِبَةِ لِي مِنْ مَالِهِ، ثُمَّ بَدَا لَهُ فَوَهَبَهَا لِي فَقَالَتْ لاَ أَرْضَى حَتَّى تُشْهِدَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَأَخَذَ بِيَدِي وَأَنَا غُلاَمٌ، فَأَتَى بِيَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ إِنَّ أُمَّهُ بِنْتَ رَوَاحَةَ سَأَلَتْنِي بَعْضَ الْمَوْهِبَةِ لِهَذَا، قَالَ أَلَكَ وَلَدٌ سِوَاهُ. قَالَ نَعَمْ. قَالَ فَأُرَاهُ قَالَ لاَ تُشْهِدْنِي عَلَى جَوْرٍ."],"takhrij":"متفق عليه: رواه البخاري في الشهادات (2650)، ومسلم في الهبات (1623: 14) كلاهما من حديث أبي حيان التيمي، عن الشعبي، عن النعمان بن بشير فذكره، واللفظ للبخاري. ولفظ مسلم: أكلهم وهبت له مثل هذا؟. قال:لا. قال: فلا تشهدني إذا، فإني لا أشهد على جور.","grade":"متفق عليه","chapter_ar":"باب العدل بين الأولاد في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2650) and Muslim (1623:14). The wording is that of al-Bukhārī.","chapter_en":"Justice Between One’s Children in Giving Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr said: “My mother asked my father to give me a gift from his property. After some time he decided to do so and gave it to me. She said, ‘I will not be satisfied until you make the Prophet ﷺ a witness to it.’ “So he took me by the hand while I was still a boy and brought me to the Prophet ﷺ. He said, ‘His mother, the daughter of Rawāḥah, asked me to give this child a gift.’ “He asked: ‘Do you have any other children besides him?’ “He replied, ‘Yes.’ “He said—and I believe these were his words—‘Do not make me a witness to injustice.’”"]},"buhuth":{"en":["The wording of Muslim is: “Have you given all of them the same as you gave him?” He replied, “No.” He said: “Then do not make me a witness, for I do not bear witness to injustice.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2650,"lafz":true},{"key":"muslim","label":"مسلم","number":14},{"key":"muslim","label":"مسلم في الهبات","number":1623}],"full":1,"dr":1,"rep":[6751]},{"num":5985,"demo":false,"sanad":"","matn":["عن النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا وَهُوَ عَلَى الْمِنْبَرِ يَقُولُ أَعْطَانِي أَبِي عَطِيَّةً، فَقَالَتْ عَمْرَةُ بِنْتُ رَوَاحَةَ لاَ أَرْضَى حَتَّى تُشْهِدَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَأَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ إِنِّي أَعْطَيْتُ ابْنِي مِنْ عَمْرَةَ بِنْتِ رَوَاحَةَ عَطِيَّةً، فَأَمَرَتْنِي أَنْ أُشْهِدَكَ يَا رَسُولَ اللَّهِ. قَالَ أَعْطَيْتَ سَائِرَ وَلَدِكَ مِثْلَ هَذَا. قَالَ لاَ. قَالَ فَاتَّقُوا اللَّهَ، وَاعْدِلُوا بَيْنَ أَوْلاَدِكُمْ. قَالَ فَرَجَعَ فَرَدَّ عَطِيَّتَهُ."],"takhrij":"متفق عليه: رواه البخاري في الهبة (2587)، ومسلم في الهبات (1623: 13) كلاهما من حديث حصين، عن عامر الشعبي قال: سمعت النعمان بن بشير فذكره.","grade":"متفق عليه","chapter_ar":"باب العدل بين الأولاد في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2587) and Muslim (1623:13).","chapter_en":"Justice Between One’s Children in Giving Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr said while standing upon the pulpit: “My father gave me a gift. My mother, ʿAmrah bint Rawāḥah, said, ‘I will not be satisfied until you make the Messenger of Allāh ﷺ a witness.’ “So he went to the Messenger of Allāh ﷺ and said, ‘I have given this son of mine, from ʿAmrah bint Rawāḥah, a gift, and she instructed me to make you a witness to it, O Messenger of Allāh.’ “He asked: ‘Have you given the rest of your children the same as this?’ “He replied, ‘No.’ “He said: ‘Then fear Allāh and be just between your children.’ “So he returned and took back his gift.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2587,"lafz":true},{"key":"muslim","label":"مسلم","number":13},{"key":"muslim","label":"مسلم في الهبات","number":1623}],"full":1},{"num":5986,"demo":false,"sanad":"","matn":["عَنِ النُّعْمَانِ بْنِ بَشِيرٍ، قَالَ نَحَلَنِي أَبِي نُحْلاً ثُمَّ أَتَى بِي إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيُشْهِدَهُ فَقَالَ أَكُلَّ وَلَدِكَ أَعْطَيْتَهُ هَذَا. قَالَ لاَ. قَالَ أَلَيْسَ تُرِيدُ مِنْهُمُ الْبِرَّ مِثْلَ مَا تُرِيدُ مِنْ ذَا. قَالَ بَلَى. قَالَ فَإِنِّي لاَ أَشْهَدُ."],"takhrij":"صحيح: رواه مسلم في الهبات (1623: 18) عن أحمد بن عثمان النوفلي، حدثنا أزهر، حدثنا ابن عون، عن الشعبي، عن النعمان بن بشير فذكره.","grade":"صحيح","chapter_ar":"باب العدل بين الأولاد في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1623:18).","chapter_en":"Justice Between One’s Children in Giving Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr said: “My father gave me a gift, then brought me to the Messenger of Allāh ﷺ to make him a witness to it. He asked: ‘Have you given this to every one of your children?’ He replied, ‘No.’ He said: ‘Do you not desire dutifulness from all of them just as you desire it from this one?’ He replied, ‘Yes.’ He said: ‘Then I will not bear witness to it.’”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":18,"lafz":true},{"key":"muslim","label":"مسلم في الهبات","number":1623,"n":4186}],"full":1,"dr":1},{"num":5987,"demo":false,"sanad":"","matn":["عَنِ النُّعْمَانِ بْنِ بَشِيرٍ، قَالَ انْطَلَقَ بِي أَبِي يَحْمِلُنِي إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ يَا رَسُولَ اللَّهِ اشْهَدْ أَنِّي قَدْ نَحَلْتُ النُّعْمَانَ كَذَا وَكَذَا مِنْ مَالِي. فَقَالَ أَكُلَّ بَنِيكَ قَدْ نَحَلْتَ مِثْلَ مَا نَحَلْتَ النُّعْمَانَ. قَالَ لاَ. قَالَ فَأَشْهِدْ عَلَى هَذَا غَيْرِي - ثُمَّ قَالَ - أَيَسُرُّكَ أَنْ يَكُونُوا إِلَيْكَ فِي الْبِرِّ سَوَاءً. قَالَ بَلَى. قَالَ فَلاَ إِذًا."],"takhrij":"صحيح: رواه مسلم في الهبات (1623: 17) من طرق عن ابن علية قال: حدثنا إسماعيل بن إبراهيم، عن داود بن أبي هند، عن الشعبي، عن النعمان بن بشير فذكره.","grade":"صحيح","chapter_ar":"باب العدل بين الأولاد في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1623:17).","chapter_en":"Justice Between One’s Children in Giving Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr said: “My father carried me to the Messenger of Allāh ﷺ and said, ‘O Messenger of Allāh, bear witness that I have given al-Nuʿmān such-and-such from my property.’ “He asked: ‘Have you given all your sons the same as you have given al-Nuʿmān?’ “He replied, ‘No.’ “He said: ‘Then make someone other than me a witness to this.’ Then he said: ‘Would it please you for them all to be equally dutiful toward you?’ “He replied, ‘Yes.’ “He said: ‘Then do not do this.’”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":17,"lafz":true},{"key":"muslim","label":"مسلم في الهبات","number":1623,"n":4185}],"full":1},{"num":5988,"demo":false,"sanad":"","matn":["عن النُّعْمَانِ بْنِ بَشِيرٍ قَالَ وَقَدْ أَعْطَاهُ أَبُوهُ غُلاَمًا فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا هَذَا الْغُلاَمُ. قَالَ أَعْطَانِيهِ أَبِي. قَالَ فَكُلَّ إِخْوَتِهِ أَعْطَيْتَهُ كَمَا أَعْطَيْتَ هَذَا. قَالَ لاَ. قَالَ فَرُدَّهُ."],"takhrij":"صحيح: رواه مسلم في الهبات (1623: 12) عن قتيبة بن سعيد، حدثنا جرير، عن هشام بن عروة، عن أبيه قال: حدثنا النعمان بن بشير قال: وقد أعطاه أبوه غلاما فذكره.","grade":"صحيح","chapter_ar":"باب العدل بين الأولاد في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1623:12).","chapter_en":"Justice Between One’s Children in Giving Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr reported that his father gave him a slave. The Prophet ﷺ asked: “What is this slave?” He replied, “My father gave him to me.” He asked his father: “Have you given all his brothers the same as you have given him?” He replied, “No.” He said: “Then take him back.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":12,"lafz":true},{"key":"muslim","label":"مسلم في الهبات","number":1623,"n":4180}],"full":1},{"num":5989,"demo":false,"sanad":"","matn":["عَنِ النُّعْمَانِ بْنِ بَشِيرٍ، قَالَ أَنْحَلَنِي أَبِي نُحْلاً - قَالَ إِسْمَاعِيلُ بْنُ سَالِمٍ مِنْ بَيْنِ الْقَوْمِ نِحْلَةً غُلاَمًا لَهُ - قَالَ فَقَالَتْ لَهُ أُمِّي عَمْرَةُ بِنْتُ رَوَاحَةَ إِيتِ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَشْهِدْهُ فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَشْهَدَهُ فَذَكَرَ ذَلِكَ لَهُ فَقَالَ إِنِّي نَحَلْتُ ابْنِي النُّعْمَانَ نُحْلاً وَإِنَّ عَمْرَةَ سَأَلَتْنِي أَنْ أُشْهِدَكَ عَلَى ذَلِكَ قَالَ فَقَالَ أَلَكَ وَلَدٌ سِوَاهُ. قَالَ قُلْتُ نَعَمْ. قَالَ فَكُلَّهُمْ أَعْطَيْتَ مِثْلَ مَا أَعْطَيْتَ النُّعْمَانَ. قَالَ لاَ قَالَ فَقَالَ بَعْضُ هَؤُلاَءِ الْمُحَدِّثِينَ هَذَا جَوْرٌ. وَقَالَ بَعْضُهُمْ هَذَا تَلْجِئَةٌ فَأَشْهِدْ عَلَى هَذَا غَيْرِي. قَالَ مُغِيرَةُ فِي حَدِيثِهِ أَلَيْسَ يَسُرُّكَ أَنْ يَكُونُوا لَكَ فِي الْبِرِّ وَاللُّطْفِ سَوَاءً. قَالَ نَعَمْ. قَالَ فَأَشْهِدْ عَلَى هَذَا غَيْرِي. وَذَكَرَ مُجَالِدٌ فِي حَدِيثِهِ إِنَّ لَهُمْ عَلَيْكَ مِنَ الْحَقِّ أَنْ تَعْدِلَ بَيْنَهُمْ كَمَا أَنَّ لَكَ عَلَيْهِمْ مِنَ الْحَقِّ أَنْ يَبَرُّوكَ."],"takhrij":"صحيح: رواه أحمد (18378) عن هشيم، أخبرنا سيار (أبو الحكم)، ومغيرة (ابن مقسم الضبي) وداود (بن أبي هند)، وإسمـاعيل (ابن سالم الأسدي)، ومجالد (ابن سعيد)، كلهم عن الشعبي، عن النعمـان بن بشير فذكره.","grade":"صحيح","chapter_ar":"باب العدل بين الأولاد في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (18378) and Abū Dāwūd (3542).","chapter_en":"Justice Between One’s Children in Giving Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr said: “My father gave me a gift.” Ismāʿīl ibn Sālim, among the narrators, said: “He gave him a slave.” He continued: “My mother, ʿAmrah bint Rawāḥah, said to him, ‘Go to the Prophet ﷺ and make him a witness.’ So he went to the Prophet ﷺ and mentioned the matter to him, saying, ‘I have given my son al-Nuʿmān a gift, and ʿAmrah asked me to make you a witness to it.’ “He asked: ‘Do you have any child besides him?’ “He replied, ‘Yes.’ “He asked: ‘Have you given all of them the same as you gave al-Nuʿmān?’ “He replied, ‘No.’” Some of the narrators transmitted: “This is injustice.” Others transmitted: “This is coercion, so make someone other than me a witness to it.” In Mughīrah’s narration, he said: “Would it not please you for them all to be equal toward you in dutifulness and kindness?” He replied, “Yes.” He said: “Then make someone other than me a witness to this.” Mujālid mentioned in his narration: “They have a right over you that you deal justly between them, just as you have a right over them that they be dutiful to you.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3542},{"key":"ahmad","label":"مسند الإمام أحمد","number":18378,"n":18378,"lafz":true}],"full":1,"dr":1},{"num":5990,"demo":false,"sanad":"","matn":["عن النُّعْمَانِ بْنِ بَشِيرٍ يَقُولُ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اعْدِلُوا بَيْنَ أَوْلاَدِكُمْ اعْدِلُوا بَيْنَ أَبْنَائِكُمْ."],"takhrij":"حسن: رواه أبو داود (3544)، والنسائي (3687)، وأحمد (18422)، كلهم من طريق حماد بن زيد، عن حاجب بن المفضل بن المهلب، عن أبيه، قال: سمعت النعمان بن بشير فذكره.","grade":"حسن","chapter_ar":"باب العدل بين الأولاد في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3544), al-Nasāʾī (3687), and Aḥmad (18422).","chapter_en":"Justice Between One’s Children in Giving Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr reported that the Messenger of Allāh ﷺ said: “Be just between your children; be just between your sons.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3544,"lafz":true},{"key":"nasai","label":"النسائي","number":3687,"n":3687},{"key":"ahmad","label":"مسند الإمام أحمد","number":18422,"n":18422}],"full":1,"dr":1},{"num":5991,"demo":false,"sanad":"","matn":["عن النُّعْمَانِ بْنِ بَشِيرٍ وَهُوَ يَخْطُبُ، يَقُولُ: انْطَلَقَ بِي أَبِي إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيُشْهِدَهُ عَلَى عَطِيَّةٍ أَعْطَانِيهَا، فَقَالَ: هَلْ لَكَ بَنُونَ سِوَاهُ؟ قَالَ: نَعَمْ، قَالَ: سَوِّ بَيْنَهُمْ."],"takhrij":"صحيح: رواه النسائي (3687)، وأحمد (18359)، وصحّحه ابن حبان (5098) كلهم من حديث فطر بن خليفة، عن أبي الضحى مسلم بن صبيح قال: سمعت النعمان بن بشير يقول فذكر الحديث.","grade":"صحيح","chapter_ar":"باب العدل بين الأولاد في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Nasāʾī (3687) and Aḥmad (18359), and authenticated by Ibn Ḥibbān (5098).","chapter_en":"Justice Between One’s Children in Giving Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr said while delivering a sermon: “My father took me to the Messenger of Allāh ﷺ to make him a witness to a gift that he had given me. “He asked: ‘Do you have sons besides him?’ “He replied, ‘Yes.’ “He said: ‘Treat them equally.’”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3687,"n":3686},{"key":"ibnhibban","label":"صححه ابن حبان","number":5098,"lafz":true,"n":1500},{"key":"ahmad","label":"مسند الإمام أحمد","number":18359,"n":18359},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1503,"n":1500}],"full":1,"dr":1},{"num":5992,"demo":false,"sanad":"","matn":["عن النُّعْمَانِ بْنِ بَشِيرٍ قَالَ: إِنَّ وَالِدِي بَشِيرَ بْنَ سَعْدٍ، أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّ عَمْرَةَ بِنْتَ رَوَاحَةَ نُفِسَتْ بِغُلَامٍ، وَإِنِّي سَمَّيْتُهُ نُعْمَانَ، وَإِنَّهَا أَبَتْ أَنْ تُرَبِّيَهُ حَتَّى جَعَلْتُ لَهُ حَدِيقَةً لِي، هِيَ أَفْضَلُ مَالِي، وَإِنَّهَا قَالَتْ: أَشْهِدِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى ذَلِكَ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَلْ لَكَ وَلَدٌ غَيْرُهُ؟ قَالَ: نَعَمْ، قَالَ: لَا تُشْهِدْنِي إِلَاّ عَلَى عَدْلٍ، فَإِنِّي لَا أَشْهَدُ عَلَى جَوْرٍ."],"takhrij":"حسن: رواه ابن حبان (5107) عن عمر بن محمد الهمداني قال: حدثنا محمد بن عبدالأعلى قال: حدثنا معتمر بن سليمان قال: قرأت على الفضيل، عن أبي حريز، أن عامرا حدثه أن النعمان بن بشير قال فذكره.","grade":"حسن","chapter_ar":"باب العدل بين الأولاد في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Ḥibbān (5107).","chapter_en":"Justice Between One’s Children in Giving Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr said: “My father, Bashīr ibn Saʿd, came to the Messenger of Allāh ﷺ and said, ‘O Messenger of Allāh, ʿAmrah bint Rawāḥah gave birth to a boy, whom I named al-Nuʿmān. She refused to nurse and raise him until I assigned to him a garden of mine, which was my finest property, and she said: Make the Prophet ﷺ a witness to it.’ “The Prophet ﷺ asked him: ‘Do you have any other children?’ “He replied, ‘Yes.’ “He said: ‘Do not make me a witness except to something just, for I do not bear witness to injustice.’”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1511,"n":1508},{"key":"ibnhibban","label":"ابن حبان","number":5107,"lafz":true}],"full":1,"dr":1},{"num":5993,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ قَالَتِ امْرَأَةُ بَشِيرٍ انْحَلِ ابْنِي غُلاَمَكَ وَأَشْهِدْ لِي رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَأَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ إِنَّ ابْنَةَ فُلاَنٍ سَأَلَتْنِي أَنْ أَنْحَلَ ابْنَهَا غُلاَمِي وَقَالَتْ أَشْهِدْ لِي رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ أَلَهُ إِخْوَةٌ. قَالَ نَعَمْ. قَالَ أَفَكُلَّهُمْ أَعْطَيْتَ مِثْلَ مَا أَعْطَيْتَهُ. قَالَ لاَ. قَالَ فَلَيْسَ يَصْلُحُ هَذَا. وَإِنِّي لاَ أَشْهَدُ إِلاَّ عَلَى حَقٍّ."],"takhrij":"صحيح: رواه مسلم في الهبات (1624) عن أحمد بن عبد الله بن يونس، حدثنا زهير، حدثنا أبو الزبير، عن جابر قال فذكره.","grade":"صحيح","chapter_ar":"باب العدل بين الأولاد في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1624).","chapter_en":"Justice Between One’s Children in Giving Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported that Bashīr’s wife said: “Give my son your slave as a gift and make the Messenger of Allāh ﷺ a witness for me.” So he went to the Messenger of Allāh ﷺ and said: “The daughter of so-and-so asked me to give her son my slave, and she said, ‘Make the Messenger of Allāh ﷺ a witness for me.’” He asked: “Does he have brothers?” He replied, “Yes.” He asked: “Have you given all of them the same as you gave him?” He replied, “No.” He said: “This is not right, and I bear witness only to what is right.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1624,"lafz":true}],"full":1,"dr":1},{"num":5994,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، عن رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْعَائِدُ فِي هِبَتِهِ كَالْكَلْبِ يقيئ، ثُمَّ يَعُودُ فِي قَيْئِهِ."],"takhrij":"متفق عليه: رواه البخاري في الهبة (2589)، ومسلم في الهبات (1622: 8) كلاهما من حديث وهيب، حدثنا عبد الله بن طاوس، عن أبيه، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن الرجوع في الهبة إلا للوالد","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2589) and Muslim (1622:8).","chapter_en":"The Prohibition of Taking Back a Gift, Except for a Parent","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās reported that the Messenger of Allāh ﷺ said: “The one who takes back his gift is like a dog that vomits and then returns to its vomit.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2589,"lafz":true},{"key":"muslim","label":"مسلم","number":8},{"key":"muslim","label":"مسلم في الهبات","number":1622,"n":4176}],"full":1,"dr":1},{"num":5995,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، وَابْنِ، عَبَّاسٍ قَالاَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ يَحِلُّ لأَحَدٍ أَنْ يُعْطِيَ الْعَطِيَّةَ فَيَرْجِعَ فِيهَا إِلاَّ الْوَالِدَ فِيمَا يُعْطِي وَلَدَهُ وَمَثَلُ الَّذِي يُعْطِي الْعَطِيَّةَ فَيَرْجِعُ فِيهَا كَالْكَلْبِ يَأْكُلُ حَتَّى إِذَا شَبِعَ قَاءَ ثُمَّ عَادَ فَرَجَعَ فِي قَيْئِهِ."],"takhrij":"حسن: رواه أبو داود (3539)، والترمذي (2133)، والنسائي (3690)، وابن ماجه (2377)، وأحمد (2119، 2120)، وصحّحه ابن حبان (5123)، والحـاكم (2/46)، والبيهقي (6/179)، كلهم من طـريق حسين المعلم، عن عمرو بن شعيب، عن طاوس، عن ابن عباس وابن عمر فذكره.","grade":"حسن","chapter_ar":"باب النهي عن الرجوع في الهبة إلا للوالد","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3539), al-Tirmidhī (2133), al-Nasāʾī (3690), and Ibn Mājah (2377).","chapter_en":"The Prohibition of Taking Back a Gift, Except for a Parent","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿUmar and Ibn ʿAbbās reported that the Messenger of Allāh ﷺ said: “It is not proper for anyone to give a gift and then take it back, except a parent regarding what he gives to his child. The example of one who gives a gift and then takes it back is like a dog that eats until it is full, then vomits, and afterward returns to its vomit.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3539,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":2133},{"key":"nasai","label":"النسائي","number":3690,"n":3703},{"key":"ibnmajah","label":"ابن ماجه","number":2377},{"key":"ahmad","label":"احمد","number":2119},{"key":"ahmad","label":"احمد","number":2120},{"key":"ibnhibban","label":"ابن حبان","number":5123}],"full":1,"dr":1},{"num":5996,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ مَثَلَ الَّذِي يَعُودُ فِي عَطِيَّتِهِ كَمَثَلِ الْكَلْبِ أَكَلَ حَتَّى إِذَا شَبِعَ قَاءَ ثُمَّ عَادَ فِي قَيْئِهِ فَأَكَلَهُ."],"takhrij":"صحيح: رواه ابن ماجه (2384) عن أبي بكر بن أبي شيبة (وهو في مصنفه 6/477) قال: حدثنا أبو أسامة، عن عوف، عن خلاس، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الرجوع في الهبة إلا للوالد","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Mājah (2384) and Imām Aḥmad (10382, 10381, 7524).","chapter_en":"The Prohibition of Taking Back a Gift, Except for a Parent","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allāh ﷺ said: “The example of one who takes back his gift is like a dog that eats until it is full, then vomits, and afterward returns to its vomit and eats it.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2384,"lafz":true},{"key":"ahmad","label":"الإمام أحمد","number":10382,"n":10381}],"full":1,"dr":1},{"num":5997,"demo":false,"sanad":"","matn":["عن عَمْرِو بْنِ شُعَيْبٍ حَدَّثَهُ عَنْ أَبِيهِ، عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَثَلُ الَّذِي يَسْتَرِدُّ مَا وَهَبَ كَمَثَلِ الْكَلْبِ يَقِيءُ فَيَأْكُلُ قَيْئَهُ فَإِذَا اسْتَرَدَّ الْوَاهِبُ فَلْيُوَقَّفْ فَلْيُعَرَّفْ بِمَا اسْتَرَدَّ ثُمَّ لِيُدْفَعْ إِلَيْهِ مَا وَهَبَ."],"takhrij":"حسن: رواه أبو داود (3540) عن سليمان بن داود المهري، أخبرنا ابن وهب، أخبرني أسامة بن زيد، عن عمرو بن شعيب فذكره.","grade":"حسن","chapter_ar":"باب النهي عن الرجوع في الهبة إلا للوالد","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3540) and Aḥmad (6629).","chapter_en":"The Prohibition of Taking Back a Gift, Except for a Parent","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr reported that the Messenger of Allāh ﷺ said: “The example of one who reclaims what he has given is like a dog that vomits and then eats its vomit. If the giver seeks to reclaim it, he should be stopped and made aware of what it is that he is reclaiming, then what he gave may be returned to him.”"]},"buhuth":{"en":["His saying, “If the giver seeks to reclaim it,” means after he has heard the comparison with a dog returning to its vomit. The giver has a stronger claim to his gift so long as he has not received compensation for it, but he is likened to a dog returning to its vomit. If he wishes, he may reclaim it, and if he wishes, he may leave it. Thus, the hadith contains a severe deterrent and warning against taking back a gift."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3540,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":6629,"n":6629}],"full":1,"dr":1},{"num":5998,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يَرْجِعُ فِي هِبَتِهِ إِلَّا الْوَالِدُ مِنْ وَلَدِهِ، وَالْعَائِدُ فِي هِبَتِهِ كَالْعَائِدِ فِي قَيْئِهِ."],"takhrij":"حسن: رواه النسائي (3689)، والدارقطني (3/43)، والبيهقي (6/179)، وأحمد (6705) كلهم من طرق عن عامر الأحول، عن عمرو بن شعيب بإسناده مثله.","grade":"حسن","chapter_ar":"باب النهي عن الرجوع في الهبة إلا للوالد","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasāʾī (3689), al-Dāraquṭnī (3/43), al-Bayhaqī (6/179), and Aḥmad (6705).","chapter_en":"The Prohibition of Taking Back a Gift, Except for a Parent","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ reported that the Messenger of Allāh ﷺ said: “No one may take back his gift except a parent from his child. The one who takes back his gift is like one who returns to his vomit.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3689,"lafz":true,"n":3689},{"key":"sh9771","label":"الدارقطني","number":43},{"key":"kubrabayhaqi","label":"البيهقي","number":179},{"key":"sh9771","label":"سنن الدارقطني","number":2968,"n":2980},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":12013,"n":12125},{"key":"ahmad","label":"مسند الإمام أحمد","number":6705,"n":6705}],"full":1,"dr":1},{"num":5999,"demo":false,"sanad":"","matn":["عَنْ أَبِي حُمَيْدٍ السَّاعِدِيِّ قَالَ: اسْتَعْمَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلاً مِنَ الأَسْدِ يُقَالُ لَهُ: ابْنُ اللُّتْبِيَّةِ -، فَلَمَّا قَدِمَ قَالَ: هَذَا لَكُمْ، وَهَذَا لِي، أُهْدِيَ لِي. قَالَ: فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْمِنْبَرِ، فَحَمِدَ اللَّهَ، وَأَثْنَى عَلَيْهِ وَقَالَ: مَا بَالُ عَامِلٍ أَبْعَثُهُ، فَيَقُولُ: هَذَا لَكُمْ، وَهَذَا أُهْدِيَ لِي، أَفَلاَ قَعَدَ فِي بَيْتِ أَبِيهِ أَوْ فِي بَيْتِ أُمِّهِ حَتَّى يَنْظُرَ أَيُهْدَى إِلَيْهِ. أَمْ لاَ! وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ لاَ يَنَالُ أَحَدٌ مِنْكُمْ مِنْهَا شَيْئًا إِلاَّ جـاء بِهِ يَوْمَ الْقِيَامَةِ يَحْمِلُهُ عَلَى عُنُقِهِ، بَعِيرٌ لَهُ رُغَاءٌ، أَوْ بَقَرَةٌ لهـا خُوَارٌ، أَوْ شَاةٌ تَيْعِرُ."],"takhrij":"متفق عليه: رواه البخاري في الأيمان والنذور (6636)، ومسلم في كتاب الإمارة (1832) كلاهما من حديث الزهري، عن عروة، عن أبي حميد الساعدي قال فذكره.","grade":"متفق عليه","chapter_ar":"باب من يحرم عليه قبول الهدية","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6636) and Muslim (1832).","chapter_en":"Those for Whom It Is Forbidden to Accept Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Abū Ḥumayd al-Sāʿidī said: “The Messenger of Allāh ﷺ appointed a man from al-Asd, called Ibn al-Lutbiyyah, to collect revenues. When he returned, he said, ‘This is for you, and this is for me; it was given to me as a gift.’ “The Messenger of Allāh ﷺ then stood upon the pulpit, praised Allāh and extolled Him, and said: “‘What is the matter with an official whom I appoint, who then says: “This is for you, and this was given to me as a gift”? Why did he not sit in the house of his father or the house of his mother and see whether gifts would be given to him or not? “‘By the One in Whose hand is the soul of Muḥammad, none of you takes anything from it unlawfully except that he will come carrying it upon his neck on the Day of Resurrection: a camel groaning, a cow lowing, or a sheep bleating.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6636,"lafz":true},{"key":"muslim","label":"مسلم","number":1832}],"full":1},{"num":6000,"demo":false,"sanad":"","matn":["عن عُمَرَ بن الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ يَقُولُ حَمَلْتُ عَلَى فَرَسٍ فِي سَبِيلِ اللَّهِ، فَأَضَاعَهُ الَّذِي كَانَ عِنْدَهُ، فَأَرَدْتُ أَنْ أَشْتَرِيَهُ مِنْهُ، وَظَنَنْتُ أَنَّهُ بَائِعُهُ بِرُخْصٍ، فَسَأَلْتُ عَنْ ذَلِكَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لاَ تَشْتَرِهِ، وَإِنْ أَعْطَاكَهُ بِدِرْهَمٍ وَاحِدٍ، فَإِنَّ الْعَائِدَ فِي صَدَقَتِهِ كَالْكَلْبِ يَعُودُ فِي قَيْئِهِ."],"takhrij":"متفق عليه: رواه مالك في الزكاة (50) عن زيد بن أسلم، عن أبيه، سمعت عمر بن الخطاب فذكره.","grade":"متفق عليه","chapter_ar":"باب من يحرم عليه قبول الهدية","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (50), al-Bukhārī (2623), and Muslim (1620).","chapter_en":"Those for Whom It Is Forbidden to Accept Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["ʿUmar ibn al-Khaṭṭāb said: “I gave a horse for use in the cause of Allāh, but the man who had it neglected it. I wanted to buy it back from him, thinking that he would sell it cheaply. So I asked the Prophet ﷺ about it, and he said: “‘Do not buy it, even if he offers it to you for a single dirham, for the one who takes back his charity is like a dog returning to its vomit.’”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":50,"lafz":true},{"key":"bukhari","label":"البخاري","number":2623},{"key":"muslim","label":"مسلم","number":1620}],"full":1,"dr":1},{"num":6001,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ شَفَعَ لأَخِيهِ بِشَفَاعَةٍ فَأَهْدَى لَهُ هَدِيَّةً عَلَيْهَا فَقَبِلَهَا فَقَدْ أَتَى بَابًا عَظِيمًا مِنْ أَبْوَابِ الرِّبَا."],"takhrij":"حسن: رواه أبو داود (3541) عن أحمد بن عمرو بن السرح، حدثنا ابن وهب، عن عمر بن مالك، عن عبيد بن أبي جعفر، عن خالد بن أبي عمران، عن القاسم، عن أبي أمامة قال: فذكره.","grade":"حسن","chapter_ar":"باب من يحرم عليه قبول الهدية","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3541).","chapter_en":"Those for Whom It Is Forbidden to Accept Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Abū Umāmah reported that the Prophet ﷺ said: “Whoever intercedes on behalf of his brother, and a gift is then given to him because of that intercession and he accepts it, has entered through a great door of the doors of usury.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3541,"lafz":true}],"full":1,"dr":1},{"num":6002,"demo":false,"sanad":"","matn":["عن جابر قَالَ: قَالَ قَالَ لِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَوْ جَاءَ مَالُ الْبَحْرَيْنِ أَعْطَيْتُكَ هَكَذَا ثَلاَثًا. فَلَمْ يَقْدَمْ حَتَّى تُوُفِّيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَمَرَ أَبُو بَكْرٍ مُنَادِيًا فَنَادَى مَنْ كَانَ لَهُ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِدَةٌ أَوْ دَيْنٌ فَلْيَأْتِنَا. فَأَتَيْتُهُ فَقُلْتُ إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَدَنِي. فَحَثَى لِي ثَلاَثًا."],"takhrij":"متفق عليه: رواه البخاري في الهبة (2598)، ومسلم في الفضائل (2314)، كلاهما من حديث سفيان بن عيينة، عن محمد بن المنكدر يقول: سمعت جابرا يقول فذكره.","grade":"متفق عليه","chapter_ar":"باب إذا وهب هبة أو وعد ثم مات قبل الوفاء به يجوز لمن بعده أن يفيه","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2598) and Muslim (2314).","chapter_en":"If Someone Gives or Promises a Gift and Then Dies Before Fulfilling It, It Is Permissible for Those After Him to Fulfill It","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Jābir said: “The Messenger of Allāh ﷺ said to me: ‘If the wealth of Bahrain arrives, I will give you like this,’ and he gestured three times. “But the wealth did not arrive until after the Prophet ﷺ had died. Abū Bakr then ordered a caller to announce: ‘Whoever has a promise or debt owed to him by the Prophet ﷺ should come to us.’ “So I went to him and said, ‘The Prophet ﷺ made me a promise.’ Abū Bakr then scooped out three handfuls for me.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2598,"lafz":true},{"key":"muslim","label":"مسلم","number":2314}],"full":1,"dr":1},{"num":6003,"demo":false,"sanad":"","matn":["عَنِ الْمِسْوَرِ بْنِ مَخْرَمَةَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ قَسَمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَقْبِيَةً، وَلَمْ يُعْطِ مَخْرَمَةَ مِنْهَا شَيْئًا، فَقَالَ مَخْرَمَةُ يَا بُنَىَّ انْطَلِقْ بِنَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَانْطَلَقْتُ مَعَهُ، فَقَالَ ادْخُلْ فَادْعُهُ لِي. قَالَ فَدَعَوْتُهُ لَهُ فَخَرَجَ إِلَيْهِ، وَعَلَيْهِ قَبَاءٌ مِنْهَا، فَقَالَ خَبَأْنَا هَذَا لَكَ. قَالَ فَنَظَرَ إِلَيْهِ، فَقَالَ رَضِيَ مَخْرَمَةُ."],"takhrij":"متفق عليه: رواه البخاري في الهبة (2599)، ومسلم في الزكاة (1058) كلاهما عن قتيبة بن سعيد، حدثنا الليث، عن ابن أبي مليكة، عن المسور بن مخرمة فذكره.","grade":"متفق عليه","chapter_ar":"باب يجوز للإمام أن يخبئ هدية لمن غاب ولم يحضر القسمة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2599) and Muslim (1058).","chapter_en":"It Is Permissible for the Leader to Reserve a Gift for One Who Is Absent and Did Not Attend the Distribution","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Al-Miswar ibn Makhramah said: “The Messenger of Allāh ﷺ distributed some cloaks but did not give Makhramah anything from them. Makhramah said, ‘My son, come with me to the Messenger of Allāh ﷺ.’ “So I went with him. He said to me, ‘Go inside and call him for me.’ “I called him, and he came out wearing one of the cloaks. He said: ‘We reserved this one for you.’ “Makhramah looked at it, and the Prophet ﷺ said: ‘Makhramah is pleased.’”"]},"buhuth":{"en":["In another narration in al-Bukhārī: “There was some severity in his character.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2599,"lafz":true},{"key":"muslim","label":"مسلم","number":1058}],"full":1,"dr":1},{"num":6004,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ أَنَّهُ كَانَ فِي سَفَرٍ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَكَانَ عَلَى بكرٍ صعبٍ لِعُمَرَ. فَكَانَ يَتَقَدَّمُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَيَقُولُ أَبُوهُ: يَا عَبْدَ اللَّهِ، لاَ يَتَقَدَّمِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَحَدٌ. فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : بِعْنِيهِ. فَقَالَ عُمَرُ: هُوَ لَكَ، فَاشْتَرَاهُ، ثُمَّ قَالَ لِعَبْدِ اللَّهِ: هُوَ لَكَ يَا عَبْدَ اللَّهِ، فَاصْنَعْ بِهِ مَا شِئْتَ."],"takhrij":"صحيح: أخرجه البخاري في الهبة (2610) عن عبد الله بن محمد، حدثنا ابن عيينة، عن عمرو، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب من وهب شيئًا وهو في تصرف الموهوب له فهو جائز","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (2610).","chapter_en":"If Someone Gives Something That Is Already in the Possession of the Recipient, the Gift Is Valid","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Ibn ʿUmar reported that he was traveling with the Messenger of Allāh ﷺ while riding a difficult young camel belonging to ʿUmar. The camel would move ahead of the Prophet ﷺ, so his father would say: “O ʿAbdullāh, no one should ride ahead of the Prophet ﷺ.” The Prophet ﷺ then said to ʿUmar: “Sell it to me.” ʿUmar replied, “It is yours.” The Prophet ﷺ purchased it and then said to ʿAbdullāh: “It is yours, O ʿAbdullāh, so do with it whatever you wish.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2610,"lafz":true}],"full":1},{"num":6005,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ أَهْدَى إِلَىَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حُلَّةً سِيَرَاءَ فَلَبِسْتُهَا، فَرَأَيْتُ الْغَضَبَ فِي وَجْهِهِ، فَشَقَقْتُهَا بَيْنَ نِسَائِي."],"takhrij":"متفق عليه: رواه البخاري في الهبة (2614)، ومسلم في اللباس (2071: 19) كلاهما من حديث شعبة، أخبرني عبد الملك بن ميسرة قال: سمعت زيد بن وهب، عن علي فذكره.","grade":"متفق عليه","chapter_ar":"باب هدية يكره استعمالها","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2614) and Muslim (2071:19).","chapter_en":"A Gift Whose Use Is Disliked","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib said: “The Messenger of Allāh ﷺ presented me with a siyarāʾ garment. I wore it, but I saw anger on his face, so I tore it up and distributed it among my women.”"]},"buhuth":{"en":["In another narration, he ﷺ said: “I did not send it to you so that you would wear it. I only sent it to you so that you would cut it into head-coverings for the women.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2614,"lafz":true},{"key":"muslim","label":"مسلم","number":19},{"key":"muslim","label":"مسلم في اللباس","number":2071}],"full":1,"dr":1},{"num":6006,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ رَأَى عُمَرُ عُطَارِدًا التَّمِيمِيَّ يُقِيمُ بِالسُّوقِ حُلَّةً سِيَرَاءَ - وَكَانَ رَجُلاً يَغْشَى الْمُلُوكَ وَيُصِيبُ مِنْهُمْ - فَقَالَ عُمَرُ يَا رَسُولَ اللَّهِ إِنِّي رَأَيْتُ عُطَارِدًا يُقِيمُ فِي السُّوقِ حُلَّةً سِيَرَاءَ فَلَوِ اشْتَرَيْتَهَا فَلَبِسْتَهَا لِوُفُودِ الْعَرَبِ إِذَا قَدِمُوا عَلَيْكَ - وَأَظُنُّهُ قَالَ وَلَبِسْتَهَا يَوْمَ الْجُمُعَةِ - فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّمَا يَلْبَسُ الْحَرِيرَ فِي الدُّنْيَا مَنْ لاَ خَلاَقَ لَهُ فِي الآخِرَةِ. فَلَمَّا كَانَ بَعْدَ ذَلِكَ أُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِحُلَلٍ سِيَرَاءَ فَبَعَثَ إِلَى عُمَرَ بِحُلَّةٍ وَبَعَثَ إِلَى أُسَامَةَ بْنِ زَيْدٍ بِحُلَّةٍ وَأَعْطَى عَلِيَّ بْنَ أَبِي طَالِبٍ حُلَّةً وَقَالَ شَقِّقْهَا خُمُرًا بَيْنَ نِسَائِكَ. قَالَ فَجَاءَ عُمَرُ بِحُلَّتِهِ يَحْمِلُهَا فَقَالَ يَا رَسُولَ اللَّهِ بَعَثْتَ إِلَىَّ بِهَذِهِ وَقَدْ قُلْتَ بِالأَمْسِ فِي حُلَّةِ عُطَارِدٍ مَا قُلْتَ فَقَالَ إِنِّي لَمْ أَبْعَثْ بِهَا إِلَيْكَ لِتَلْبَسَهَا وَلَكِنِّي بَعَثْتُ بِهَا إِلَيْكَ لِتُصِيبَ بِهَا. وَأَمَّا أُسَامَةُ فَرَاحَ فِي حُلَّتِهِ فَنَظَرَ إِلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَظَرًا عَرَفَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ أَنْكَرَ مَا صَنَعَ فَقَالَ يَا رَسُولَ اللَّهِ مَا تَنْظُرُ إِلَىَّ فَأَنْتَ بَعَثْتَ إِلَىَّ بِهَا فَقَالَ إِنِّي لَمْ أَبْعَثْ إِلَيْكَ لِتَلْبَسَهَا وَلَكِنِّي بَعَثْتُ بِهَا إِلَيْكَ لِتُشَقِّقَهَا خُمُرًا بَيْنَ نِسَائِكَ."],"takhrij":"صحيح: رواه مسلم في اللباس (2068: 7) عن شيبان بن فروخ، حدثنا جرير بن حازم، حدثنا نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب هدية يكره استعمالها","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2068:7).","chapter_en":"A Gift Whose Use Is Disliked","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar said: “ʿUmar saw ʿUṭārid al-Tamīmī displaying a siyarāʾ garment in the marketplace. He was a man who used to frequent kings and receive things from them. “ʿUmar said: ‘O Messenger of Allāh, I saw ʿUṭārid displaying a siyarāʾ garment in the marketplace. If only you would buy it and wear it when Arab delegations come to you.’ And I think he also said: ‘And wear it on Fridays.’ “The Messenger of Allāh ﷺ said to him: ‘Silk in this world is worn only by one who has no share in the Hereafter.’ “Later, some siyarāʾ garments were brought to the Messenger of Allāh ﷺ. He sent one garment to ʿUmar, one to Usāmah ibn Zayd, and gave one to ʿAlī ibn Abī Ṭālib, saying: ‘Cut it into head-coverings for your women.’ “ʿUmar came carrying his garment and said: ‘O Messenger of Allāh, you sent this to me, although yesterday you said what you said regarding ʿUṭārid’s garment.’ “He replied: ‘I did not send it to you so that you would wear it. I sent it to you so that you might derive benefit from it.’ “As for Usāmah, he went out wearing his garment. The Messenger of Allāh ﷺ looked at him in such a way that Usāmah realized that the Messenger of Allāh ﷺ disapproved of what he had done. “He said: ‘O Messenger of Allāh, why are you looking at me? You are the one who sent it to me.’ “He replied: ‘I did not send it to you so that you would wear it. I sent it to you so that you would cut it into head-coverings for your women.’”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":7,"lafz":true},{"key":"muslim","label":"مسلم في اللباس","number":2068,"n":5403}],"full":1},{"num":6007,"demo":false,"sanad":"","matn":["عَنْ عِيَاضِ بْنِ حِمَارٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَهْدَيْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَاقَةً أَوْ هَدِيَّةً، فَقَالَ: أَسْلَمْتَ؟ قُلْتُ: لَا، قَالَ: إِنِّي نُهِيتُ عَنْ زَبْدِ الْمُشْرِكِينَ."],"takhrij":"حسن: رواه أبو داود (3057) والترمذي (1577) والبيهقي (9/216) كلهم من طريق أبي داود الطيالسي، وهو في مسنده (1179) – قال: حدثنا عمران، عن قتادة، عن يزيد بن عبدالله، عن عياض بن حمار، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في رد هدية المشركين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3057), al-Tirmidhī (1577), and al-Bayhaqī (9/216). Al-Tirmidhī said: “Hasan Sahih.”","chapter_en":"What Has Been Reported Concerning Refusing the Gifts of Polytheists","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["ʿIyāḍ ibn Ḥimār said: “I presented the Messenger of Allāh ﷺ with a she-camel—or he said: a gift. He asked: ‘Have you embraced Islām?’ “I replied, ‘No.’ “He said: ‘I have been prohibited from accepting the gifts of the polytheists.’”"]},"buhuth":{"en":["His saying, “zabd al-mushrikīn”: zabd, with a sākin bāʾ, means assistance or a gift. The Arabs call a gift zabd. See: al-Nihāyah."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3057,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1577},{"key":"kubrabayhaqi","label":"البيهقي","number":216},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":18793,"n":18951}],"full":1,"dr":1},{"num":6008,"demo":false,"sanad":"","matn":["عُبَيْدُ اللَّهِ بْنُ الْمُغِيرَةِ، عَنْ عِرَاكِ بْنِ مَالِكٍ، أَنَّ حَكِيمَ بْنَ حِزَامٍ، قَالَ: كَانَ مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَحَبَّ رَجُلٍ فِي النَّاسِ إِلَيَّ فِي الْجَاهِلِيَّةِ، فَلَمَّا تَنَبَّأَ، وَخَرَجَ إِلَى الْمَدِينَةِ، شَهِدَ حَكِيمُ بْنُ حِزَامٍ الْمَوْسِمَ وَهُوَ كَافِرٌ، فَوَجَدَ حُلَّةً لِذِي يَزَنَ تُبَاعُ، فَاشْتَرَاهَا بِخَمْسِينَ دِينَارًا، لِيُهْدِيَهَا لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَدِمَ بِهَا عَلَيْهِ الْمَدِينَةَ، فَأَرَادَهُ عَلَى قَبْضِهَا هَدِيَّةً فَأَبَى، قَالَ عُبَيْدُ اللَّهِ: حَسِبْتُ أَنَّهُ قَالَ: إِنَّا لَا نَقْبَلُ شَيْئًا مِنَ الْمُشْرِكِينَ، وَلَكِنْ إِنْ شِئْتَ أَخَذْنَاهَا بِالثَّمَنِ، فَأَعْطَيْتُهُ حِينَ أَبَى عَلَيَّ الْهَدِيَّةَ."],"takhrij":"حسن: رواه أحمد (15323) عن عتاب بن زياد، حدثنا عبد الله (يعني: ابن المبارك)، أخبرنا ليث بن سعد، حدثني عبيد الله بن المغيرة، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في رد هدية المشركين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (15323).","chapter_en":"What Has Been Reported Concerning Refusing the Gifts of Polytheists","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["ʿUbaydullāh ibn al-Mughīrah reported from ʿIrāk ibn Mālik that Ḥakīm ibn Ḥizām said: “Muḥammad ﷺ was the most beloved of all people to me during the time of Jāhiliyyah. When he became a Prophet and departed for Madīnah, I attended the pilgrimage season while still an unbeliever. “I found a garment that had belonged to Dhū Yazan being offered for sale, so I purchased it for fifty dinars in order to give it as a gift to the Messenger of Allāh ﷺ. “I brought it to him in Madīnah and wanted him to accept it as a gift, but he refused.” ʿUbaydullāh said: “I think he said: ‘We do not accept anything from the polytheists, but if you wish, we will take it for its price.’ So I gave it to him after he refused to accept it from me as a gift.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":15323,"n":15323,"lafz":true}],"full":1,"dr":1},{"num":6009,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ أَنَّهُ أُهْدِيَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جُبَّةٌ مِنْ سُنْدُسٍ وَكَانَ يَنْهَى عَنِ الْحَرِيرِ فَعَجِبَ النَّاسُ مِنْهَا فَقَالَ وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ إِنَّ مَنَادِيلَ سَعْدِ بْنِ مُعَاذٍ فِي الْجَنَّةِ أَحْسَنُ مِنْ هَذَا."],"takhrij":"متفق عليه: رواه البخاري في الهبة (2615)، ومسلم في فضائل الصحابة (2469) كلاهما من حديث يونس بن محمد، حدثنا شيبان، عن قتادة، حدثنا أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في قبول هدية المشركين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2615) and Muslim (2469).","chapter_en":"What Has Been Reported Concerning Accepting the Gifts of Polytheists","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Anas ibn Mālik said: “A robe of fine silk was presented to the Messenger of Allāh ﷺ, while he used to forbid silk. The people were amazed by it, so he said: ‘By the One in Whose hand is the soul of Muḥammad, the handkerchiefs of Saʿd ibn Muʿādh in Paradise are finer than this.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2615,"lafz":true},{"key":"muslim","label":"مسلم","number":2469}],"full":1,"dr":1},{"num":6010,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ يَهُودِيَّةً، أَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشَاةٍ مَسْمُومَةٍ، فَأَكَلَ مِنْهَا فَجِيءَ بِهَا فَقِيلَ أَلاَ نَقْتُلُهَا. قَالَ لاَ. فَمَا زِلْتُ أَعْرِفُهَا فِي لَهَوَاتِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"متفق عليه: رواه البخاري في الهبة (2617)، ومسلم في السلام (2190) كلاهما من حديث خالد بن الحارث، حدثنا شعبة، عن هشام بن زيد، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في قبول هدية المشركين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2617) and Muslim (2190).","chapter_en":"What Has Been Reported Concerning Accepting the Gifts of Polytheists","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Anas reported that a Jewish woman brought the Prophet ﷺ a poisoned sheep, and he ate from it. She was brought before him, and it was said, “Should we not kill her?” He replied: “No.” Anas said: “I continued to recognize the effects of it in the soft tissues of the mouth and throat of the Messenger of Allāh ﷺ.”"]},"buhuth":{"en":["His saying, “lahawāt” is the plural of lahāh. It refers to the roof of the mouth or the fleshy part overlooking the throat. It has also been said to mean the furthest part of the throat, or that which becomes visible inside the mouth when a person smiles."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2617,"lafz":true},{"key":"muslim","label":"مسلم","number":2190}],"full":1,"dr":1},{"num":6011,"demo":false,"sanad":"","matn":["عَنْ أَبِي حُمَيْدٍ السَّاعِدِيِّ، قَالَ: أهدى مَلِكُ أَيْلَةَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَغْلَةً بَيْضَاءَ، وَكَسَاهُ بُرْدًا، وَكَتَبَ لَهُ بِبَحْرِهِمْ."],"takhrij":"متفق عليه: رواه البخاري في الزكاة (1481)، ومسلم في الفضائل (1392/11) كلاهما من حديث عمرو بن يحيى، عن عباس بن سهل بن سعد الساعدي، عن أبي حميد الساعدي، فذكره في حديث طويل، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في قبول هدية المشركين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1481) and Muslim (1392/11). The wording is that of al-Bukhārī.","chapter_en":"What Has Been Reported Concerning Accepting the Gifts of Polytheists","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Abū Ḥumayd al-Sāʿidī said: “The ruler of Aylah presented the Prophet ﷺ with a white mule and clothed him in a mantle, and the Prophet ﷺ wrote for him concerning their coastal territory.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1481,"lafz":true},{"key":"muslim","label":"مسلم","number":11}],"full":1},{"num":6012,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الحصيب قَالَ: أَهْدَى أَمِيرُ الْقِبْطِ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَارِيَتَيْنِ أُخْتَيْنِ قبطيتين، وَبَغْلَةً، فَأَمَّا الْبَغْلَةُ فَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَرْكَبُهَا، وَأَمَّا إِحْدَى الْجَارِيَتَيْنِ فَتَسَرَّاهَا، فَوَلَدَتْ لَهُ إِبْرَاهِيمَ، وَأَمَّا الْأُخْرَى فَأَعْطَاهَا حَسَّانَ بْنَ ثَابِتٍ الْأَنْصَارِيَّ."],"takhrij":"حسن: رواه الحارث بن أبي أسامة في مسنده (452- بغية الباحث)، والطحاوي في شرح المشكل (2569)، والطبراني في الأوسط (2059/مجمع البحرين) من طرق عن حاتم بن إسماعيل، عن بشير بن المهاجر، عن عبدالله بن بريدة، عن أبيه، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في قبول هدية المشركين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ḥārith ibn Abī Usāmah in his Musnad (452 — Bughyat al-Bāḥith) and al-Ṭaḥāwī in Sharḥ al-Mushkil (2569).","chapter_en":"What Has Been Reported Concerning Accepting the Gifts of Polytheists","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Buraydah ibn al-Ḥuṣayb said: “The ruler of the Copts presented the Messenger of Allāh ﷺ with two Coptic slave women who were sisters, together with a mule. As for the mule, the Messenger of Allāh ﷺ used to ride it. As for one of the two women, he took her as a concubine, and she bore him Ibrāhīm. The other he gave to Ḥassān ibn Thābit al-Anṣārī.”"]}},"tuhfa":{},"refs":[{"key":"sh13160","label":"الحارث بن أبي أسامة في مسنده","number":452,"lafz":true},{"key":"sh22547","label":"الطحاوي في شرح المشكل","number":2569}],"full":1,"dr":1,"rep":[9419]},{"num":6013,"demo":false,"sanad":"","matn":["عن عبدالرحمن بن عبد القاري أن رسول الله صلى الله عليه وسلم  بعث حاطب بن أبي بلتعة إلى المقوقس صاحب الإسكندرية، يعني بكتابه معه إليه، فقَبَّلَ كتابَه، وأكرم حاطبا، وأحسن نزله، ثم سرحه إلى رسول الله صلى الله عليه وسلم ، وأهدى له مع حاطب كسوة وبغلة شهباء بسرجها وجاريتين، إحداهما أم إبراهيم، وأما الأخرى فوهبها لجهم بن قيس العبدري، وهي أم زكريا بن جهم الذي كان خليفة عمرو بن العاص على مصر."],"takhrij":"صحيح: رواه الطحاوي في شرح المشكل (2570)، (4349) عن يونس بن عبد الأعلى، حدثنا عبدالله بن وهب، أخبرني يونس بن يزيد، عن ابن شهاب، قال: حدثني عبد الرحمن بن عبد القاري، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في قبول هدية المشركين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Ṭaḥāwī in Sharḥ al-Mushkil (4349, 2570).","chapter_en":"What Has Been Reported Concerning Accepting the Gifts of Polytheists","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn ʿAbd al-Qārī reported that the Messenger of Allāh ﷺ sent Ḥāṭib ibn Abī Baltaʿah to al-Muqawqis, the ruler of Alexandria, carrying his letter to him. Al-Muqawqis received his letter respectfully, honored Ḥāṭib, provided him with excellent hospitality, and then sent him back to the Messenger of Allāh ﷺ. With Ḥāṭib he sent gifts for the Prophet ﷺ consisting of clothing, a grayish-white mule with its saddle, and two slave women. One of them was the mother of Ibrāhīm. As for the other, he gave her to Jahm ibn Qays al-ʿAbdarī. She was the mother of Zakariyyā ibn Jahm, who served as the deputy of ʿAmr ibn al-ʿĀṣ over Egypt."]},"buhuth":{"en":["His statement, “As for the other, he gave her to Jahm ibn Qays al-ʿAbdarī,” conflicts with what appears in the hadith of Buraydah: “As for the other, he gave her to Ḥassān ibn Thābit.” What appears in the hadith of Buraydah is more authentic, and it is possible that the contradictory wording arose from an error by one of the narrators."]}},"tuhfa":{},"refs":[{"key":"sh22547","label":"الطحاوي في شرح المشكل","number":4349,"lafz":true}],"full":1,"dr":1},{"num":6014,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ أَنَّ عُمَرَ بْنَ الْخَطَّابِ رَأَى حُلَّةَ سِيَرَاءَ عِنْدَ بَابِ الْمَسْجِدِ، فَقَالَ: يَا رَسُولَ اللَّهِ، لَوِ اشْتَرَيْتَ هَذِهِ، فَلَبِسْتَهَا يَوْمَ الْجُمُعَةِ، وَلِلْوَفْدِ إِذَا قَدِمُوا عَلَيْكَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنَّمَا يَلْبَسُ هَذِهِ مَنْ لاَ خَلاَقَ لَهُ فِي الآخِرَةِ. ثُمَّ جَاءَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْهَا حُلَلٌ، فَأَعْطَى عُمَرَ بْنَ الْخَطَّابِ مِنْهَا حُلَّةً، فَقَالَ عُمَرُ: يَا رَسُولَ اللَّهِ، كَسَوْتَنِيهَا. وَقَدْ قُلْتَ فِي حُلَّةِ عُطَارِدٍ مَا قُلْتَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنِّي لَمْ أَكْسُكَهَا لِتَلْبَسَهَا. فَكَسَاهَا عُمَرُ بْنُ الْخَطَّابِ أَخًا لَهُ بِمَكَّةَ مُشْرِكًا."],"takhrij":"متفق عليه: رواه مالك عن نافع، عن عبد الله بن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب الهدية للمشركين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (1637), al-Bukhārī (886), and Muslim (2068).","chapter_en":"Giving Gifts to Polytheists","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Ibn ʿUmar reported that ʿUmar ibn al-Khaṭṭāb saw a siyarāʾ garment by the door of the mosque and said, “O Messenger of Allāh, if only you would buy this and wear it on Friday and when delegations come to you.” The Messenger of Allāh ﷺ said: “This is worn only by one who has no share in the Hereafter.” Later, some garments of that kind were brought to the Messenger of Allāh ﷺ, and he gave one of them to ʿUmar ibn al-Khaṭṭāb. ʿUmar said, “O Messenger of Allāh, you have clothed me in this even though you said what you said about the garment of ʿUṭārid.” The Messenger of Allāh ﷺ said: “I did not give it to you so that you would wear it.” So ʿUmar ibn al-Khaṭṭāb gave it to a polytheist brother of his in Makkah."]},"intro":{"ar":["قال اللّٰه تعالى: ﴿لَا يَنْهَاكُمُ اللّٰهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُمْ مِنْ دِيَارِكُمْ أَنْ تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ إِنَّ اللّٰهَ يُحِبُّ الْمُقْسِطِينَ﴾ [سورة الممتحنة: ٨]."],"en":["Allāh Most High says: “Allāh does not forbid you from dealing kindly and justly with those who did not fight you because of religion and did not expel you from your homes. Indeed, Allāh loves those who act justly.”","[Surat al-Mumtaḥanah: 8]"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":1637,"lafz":true,"n":1669},{"key":"bukhari","label":"البخاري","number":886},{"key":"muslim","label":"مسلم","number":2068}],"full":1,"dr":1},{"num":6015,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ قَالَتْ: قَدِمَتْ عَلَىَّ أُمِّي، وهي مُشْرِكَةٌ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : فَاسْتَفْتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، قُلْتُ: وهي رَاغِبَةٌ، أَفَأَصِلُ أُمِّي؟ قَالَ: نَعَمْ صِلي أُمَّكِ."],"takhrij":"متفق عليه: رواه البخاري في الهبة (2620)، ومسلم في الزكاة (1003) كلاهما من حديث أبي أسامة، عن هشام، عن أبيه، عن أسماء بنت أبي بكر فذكرته.","grade":"متفق عليه","chapter_ar":"باب الهدية للمشركين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2620) and Muslim (1003).","chapter_en":"Giving Gifts to Polytheists","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Asmāʾ bint Abī Bakr said: “My mother came to me while she was still a polytheist during the lifetime of the Messenger of Allāh ﷺ. I asked the Messenger of Allāh ﷺ for a ruling and said, ‘She has come seeking my favor; should I maintain ties with my mother?’ He said: ‘Yes, maintain ties with your mother.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2620,"lafz":true},{"key":"muslim","label":"مسلم","number":1003,"n":2325}],"full":1},{"num":6016,"demo":false,"sanad":"","matn":["بْنُ أَيْمَنَ، قَالَ حَدَّثَنِي أَبِي قَالَ، دَخَلْتُ عَلَى عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا وَعَلَيْهَا دِرْعُ قِطْرٍ ثَمَنُ خَمْسَةِ دَرَاهِمَ، فَقَالَتِ ارْفَعْ بَصَرَكَ إِلَى جَارِيَتِي، انْظُرْ إِلَيْهَا فَإِنَّهَا تُزْهَى أَنْ تَلْبَسَهُ فِي الْبَيْتِ، وَقَدْ كَانَ لِي مِنْهُنَّ دِرْعٌ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَمَا كَانَتِ امْرَأَةٌ تُقَيَّنُ بِالْمَدِينَةِ إِلاَّ أَرْسَلَتْ إِلَىَّ تَسْتَعِيرُهُ."],"takhrij":"صحيح: رواه البخاري في الهبة (2628) عن أبي نعيم، حدثنا عبدالواحد بن أيمن، حدثني أبي قال: دخلت على عائشة فذكره.","grade":"صحيح","chapter_ar":"باب استعارة الملابس للعروس عند البناء","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (2628).","chapter_en":"Borrowing Clothes for a Bride at the Time of Consummation","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["Ayman al-Ḥabashī al-Makkī said: “I entered upon ʿĀʾishah while she was wearing a striped garment worth five dirhams. She said, ‘Raise your gaze toward my slave girl and look at her, for she is too proud to wear it in the house. I had a garment like it during the time of the Messenger of Allāh ﷺ, and whenever any woman in Madīnah was being prepared and adorned as a bride, she would send to me asking to borrow it.’”"]},"buhuth":{"en":["His saying, “تزهى” means that pride or conceit enters a person.","His saying, “تُقيَّن” means “to be adorned,” from the expression qāna al-shayʾ, meaning to improve or beautify something.","This indicates that lending clothes to a bride was a customary practice, encouraged and accepted, and was not regarded as something shameful or objectionable."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2628,"lafz":true}],"full":1,"dr":1},{"num":6017,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ قَضَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْعُمْرَى أَنَّهَا لِمَنْ وُهِبَتْ لَهُ."],"takhrij":"متفق عليه: رواه البخاري في الهبة (2625)، ومسلم في الهبات (1625: 25) كلاهما من حديث يحيى بن أبي كثير، عن أبي سلمة بن عبد الرحمن، عن جابر بن عبد الله قال:فذكره.","grade":"متفق عليه","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2625) and Muslim (1625:25).","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Jābir said: “The Prophet ﷺ ruled concerning ʿumrā that it belongs to the person to whom it was given.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2625,"lafz":true},{"key":"muslim","label":"مسلم","number":25},{"key":"muslim","label":"مسلم في الهبات","number":1625}],"full":1},{"num":6018,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ الْعُمْرَى جَائِزَةٌ."],"takhrij":"متفق عليه: رواه مسلم في الهبات (1625: 30) من حديث شعبة، والبخاري (2226) من حديث همام، كلاهما عن قتادة، يحدث عن عطاء، عن جابر. فذكره.","grade":"متفق عليه","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (1625:30) and al-Bukhārī (2626).","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Jābir reported that the Prophet ﷺ said: “ʿUmrā is valid.”"]},"buhuth":{"en":["His saying, “valid” means that it is legally effective and remains the property of the one to whom the ʿumrā was granted, and then of his heirs after him."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":30,"lafz":true,"n":256},{"key":"bukhari","label":"البخاري","number":2626},{"key":"muslim","label":"مسلم في الهبات","number":1625,"n":4200},{"key":"bukhari","label":"البخاري","number":2226,"n":2236}],"full":1,"dr":1},{"num":6019,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ أَيُّمَا رَجُلٍ أُعْمِرَ عُمْرَى لَهُ وَلِعَقِبِهِ فَإِنَّهَا لِلَّذِي أُعْطِيَهَا لاَ تَرْجِعُ إِلَى الَّذِي أَعْطَاهَا لأَنَّهُ أَعْطَى عَطَاءً وَقَعَتْ فِيهِ الْمَوَارِيثُ."],"takhrij":"صحيح: رواه مالك في الأقضية (45) عن ابن شهاب، عن أبي سلمة بن عبد الرحمن، عن جابر فذكره. ورواه مسلم في الهبات (1625) من هذا الطريق.","grade":"صحيح","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Mālik (45) and Muslim (1625).","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported that the Messenger of Allāh ﷺ said: “Any man who grants an ʿumrā to another person and to his descendants, it belongs to the one to whom it was given. It does not return to the one who gave it, because he has made a gift in which inheritance has taken effect.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":45},{"key":"muslim","label":"مسلم","number":1625,"lafz":true}],"full":1},{"num":6020,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ الأنصاري أَخْبَرَهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ أَيُّمَا رَجُلٍ أَعْمَرَ رَجُلاً عُمْرَى لَهُ وَلِعَقِبِهِ فَقَالَ قَدْ أَعْطَيْتُكَهَا وَعَقِبَكَ مَا بَقِيَ مِنْكُمْ أَحَدٌ. فَإِنَّهَا لِمَنْ أُعْطِيَهَا. وَإِنَّهَا لاَ تَرْجِعُ إِلَى صَاحِبِهَا مِنْ أَجْلِ أَنَّهُ أَعْطَى عَطَاءً وَقَعَتْ فِيهِ الْمَوَارِيثُ."],"takhrij":"صحيح: رواه مسلم في الهبات (1625: 22) عن عبد الرحمن بن بشر العبدي، أخبرنا عبد الرزاق، أخبرنا ابن جريج، أخبرني ابن شهاب عن العُمْرَى وسُنَّتِها، عن حديث أبي سلمة بن عبد الرحمن، عن جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1625:22).","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh al-Anṣārī reported that the Messenger of Allāh ﷺ said: “Any man who grants another man an ʿumrā for himself and his descendants, saying, ‘I have given it to you and to your descendants for as long as any of you remains,’ then it belongs to the one to whom it was given and does not return to its original owner, because he gave a gift in which inheritance has taken effect.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":22,"lafz":true},{"key":"muslim","label":"مسلم في الهبات","number":1625,"n":4190}],"full":1},{"num":6021,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَمْسِكُوا عَلَيْكُمْ أَمْوَالَكُمْ، لَا تُعْطُوهَا أَحَدًا، فَمَنْ أُعْمِرَ شَيْئًا، فَهُوَ لَهُ."],"takhrij":"صحيح: رواه الإمام أحمد (14126) عن عبد الرزاق، أنا سفيان، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (14126), and Muslim (1625:27) in an abbreviated form.","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said that the Messenger of Allāh ﷺ said: “Keep possession of your wealth and do not give it away. Whoever grants something as an ʿumrā, then it belongs to the one to whom it was granted.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":14126,"lafz":true},{"key":"muslim","label":"مسلم","number":27}],"full":1,"dr":1},{"num":6022,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمْسِكُوا عَلَيْكُمْ أَمْوَالَكُمْ وَلاَ تُفْسِدُوهَا فَإِنَّهُ مَنْ أَعْمَرَ عُمْرَى فَهِيَ لِلَّذِي أُعْمِرَهَا حَيًّا وَمَيِّتًا وَلِعَقِبِهِ."],"takhrij":"صحيح: رواه مسلم في الهبات (1625: 26) عن يحيى بن يحيى، أخبرنا أبو خيثمة، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1625:26).","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said that the Messenger of Allāh ﷺ said: “Keep your wealth and do not dispose of it in a way that causes you to lose it. For whoever is granted an ʿumrā, it belongs to the person to whom it was granted during his lifetime and after his death, and then to his descendants.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":26,"lafz":true},{"key":"muslim","label":"مسلم في الهبات","number":1625,"n":4196}],"full":1,"dr":1},{"num":6023,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، - وَهُوَ ابْنُ عَبْدِ اللَّهِ - أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى فِيمَنْ أُعْمِرَ عُمْرَى لَهُ وَلِعَقِبِهِ فَهِيَ لَهُ بَتْلَةً لاَ يَجُوزُ لِلْمُعْطِي فِيهَا شَرْطٌ وَلاَ ثُنْيَا."],"takhrij":"صحيح: رواه مسلم في الهبات (1625: 24) عن محمد بن رافع، عن ابن أبي فديك، عن ابن أبي ذئب، عن ابن شهاب، عن أبي سلمة بن عبدالرحمن، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1625:24).","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported that the Messenger of Allāh ﷺ ruled that when a person is granted an ʿumrā for himself and his descendants, it belongs to him absolutely, and the giver may not attach any condition or exception to it."]},"buhuth":{"en":["His saying, “batlah” means an irrevocable gift that has taken effect and does not return to the giver."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":24,"lafz":true},{"key":"muslim","label":"مسلم في الهبات","number":1625,"n":4192}],"full":1,"dr":1},{"num":6024,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّهُ قَالَ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ مَنْ أَعْمَرَ رَجُلاً عُمْرَى لَهُ وَلِعَقِبِهِ فَقَدْ قَطَعَ قَوْلُهُ حَقَّهُ فِيهَا وَهِيَ لِمَنْ أُعْمِرَ وَلِعَقِبِهِ."],"takhrij":"صحيح: رواه مسلم في الهبات (1625: 21) من طرق عن الليث، عن ابن شهاب، عن أبي سلمة، عن جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1625:21).","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: “I heard the Messenger of Allāh ﷺ say: ‘Whoever grants a man an ʿumrā for himself and his descendants has, by his own statement, cut off his own right to it. It belongs to the one to whom it was granted and to his descendants.’”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":21,"lafz":true},{"key":"muslim","label":"مسلم في الهبات","number":1625,"n":4189}],"full":1},{"num":6025,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ أَعْمَرَتِ امْرَأَةٌ بِالْمَدِينَةِ حَائِطًا لَهَا ابْنًا لَهَا ثُمَّ تُوُفِّيَ وَتُوُفِّيَتْ بَعْدَهُ وَتَرَكَتْ وَلَدًا وَلَهُ إِخْوَةٌ بَنُونَ لِلْمُعْمِرَةِ فَقَالَ وَلَدُ الْمُعْمِرَةِ رَجَعَ الْحَائِطُ إِلَيْنَا وَقَالَ بَنُو الْمُعْمَرِ بَلْ كَانَ لأَبِينَا حَيَاتَهُ وَمَوْتَهُ. فَاخْتَصَمُوا إِلَى طَارِقٍ مَوْلَى عُثْمَانَ فَدَعَا جَابِرًا فَشَهِدَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْعُمْرَى لِصَاحِبِهَا فَقَضَى بِذَلِكَ طَارِقٌ ثُمَّ كَتَبَ إِلَى عَبْدِ الْمَلِكِ فَأَخْبَرَهُ ذَلِكَ وَأَخْبَرَهُ بِشَهَادَةِ جَابِرٍ فَقَالَ عَبْدُ الْمَلِكِ صَدَقَ جَابِرٌ. فَأَمْضَى ذَلِكَ طَارِقٌ. فَإِنَّ ذَلِكَ الْحَائِطَ لِبَنِي الْمُعْمَرِ حَتَّى الْيَوْمِ."],"takhrij":"صحيح: رواه مسلم في الهبات (1625: 28) من طرق عن عبدالرزاق، أخبرنا ابن جريج، أخبرني أبو الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1625:28).","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: “A woman in Madīnah granted a garden of hers as an ʿumrā to one of her sons. He later died leaving children, and she died after him. The deceased grantee also had brothers who were sons of the woman who had made the grant. “The brothers of the deceased grantee said, ‘The garden has returned to us.’ “The sons of the man who had received the ʿumrā said, ‘Rather, it belonged to our father during his life and after his death.’ “They brought their dispute before Ṭāriq, the freedman of ʿUthmān. He summoned Jābir, who testified concerning the ruling of the Messenger of Allāh ﷺ that the ʿumrā belongs to its recipient. “Ṭāriq ruled accordingly, then wrote to ʿAbd al-Malik informing him of the case and of Jābir’s testimony. ʿAbd al-Malik said, ‘Jābir has spoken the truth.’ “Ṭāriq therefore upheld the ruling, and that garden has remained with the descendants of the recipient of the ʿumrā until today.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":28,"lafz":true},{"key":"muslim","label":"مسلم في الهبات","number":1625,"n":4198}],"full":1},{"num":6026,"demo":false,"sanad":"","matn":["عَنْ سُلَيْمَانَ بْنِ يَسَارٍ، أَنَّ طَارِقًا، قَضَى بِالْعُمْرَى لِلْوَارِثِ لِقَوْلِ جَابِرِ بْنِ عَبْدِ اللَّهِ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه مسلم في الهبات (1625: 29) عن أبي بكر بن أبي شيبة وإسحاق بن إبراهيم كلاهما عن سفيان بن عيينة، عن عمرو، عن سليمان بن يسار فذكره.","grade":"صحيح","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1625:29).","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Sulaymān ibn Yasār reported that Ṭāriq ruled that an ʿumrā passes to the heir, based on what Jābir ibn ʿAbdullāh narrated from the Messenger of Allāh ﷺ."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":29,"lafz":true},{"key":"muslim","label":"مسلم في الهبات","number":1625,"n":4199}],"full":1},{"num":6027,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ الْعُمْرَى مِيرَاثٌ لأَهْلِهَا."],"takhrij":"صحيح: رواه مسلم في الهبات (1625: 31) عن يحيى بن حبيب الحارثي، حدثنا خالد (يعنى ابن الحارث)، حدثنا سعيد، عن قتادة، عن عطاء، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1625:31).","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Jābir reported that the Prophet ﷺ said: “ʿUmrā is an inheritance for its people.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":31,"lafz":true,"n":158},{"key":"muslim","label":"مسلم في الهبات","number":1625,"n":4201}],"full":1},{"num":6028,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ تُرْقِبُوا وَلاَ تُعْمِرُوا فَمَنْ أُرْقِبَ شَيْئًا أَوْ أُعُمِرَهُ فَهُوَ لِوَرَثَتِهِ."],"takhrij":"صحيح: رواه أبو داود (3556)، والنسائي (3731)، والبيهقي في الكبرى (6/175)، والصغرى (2208) كلهم من حديث سفيان بن عيينة، عن ابن جريج، عن عطاء، عن جابر فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (3556), al-Nasāʾī (3731), and al-Bayhaqī in al-Kubrā (6/175).","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported that the Prophet ﷺ said: “Do not make grants by way of ruqbā, and do not make grants by way of ʿumrā. Whoever grants something as a ruqbā or an ʿumrā, it belongs to the heirs of the one to whom it was granted.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3556,"lafz":true},{"key":"nasai","label":"النسائي","number":3731,"n":3731},{"key":"kubrabayhaqi","label":"البيهقي في الكبرى","number":175}],"full":1,"dr":1},{"num":6029,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ الْعُمْرَى جَائِزَةٌ."],"takhrij":"متفق عليه: رواه البخاري في الهبة (2626)، ومسلم في الهبات (1626) كلاهما من حديث قتادة قال: حدثني النضر بن أنس، عن بشير بن نهيك، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2626) and Muslim (1626).","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ said: “ʿUmrā is valid.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2626,"lafz":true},{"key":"muslim","label":"مسلم","number":1626}],"full":1,"dr":1},{"num":6030,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ إِنَّمَا الْعُمْرَى الَّتِي أَجَازَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَقُولَ هِيَ لَكَ وَلِعَقِبِكَ. فَأَمَّا إِذَا قَالَ هِيَ لَكَ مَا عِشْتَ. فَإِنَّهَا تَرْجِعُ إِلَى صَاحِبِهَا. قَالَ مَعْمَرٌ وَكَانَ الزُّهْرِيُّ يُفْتِي بِهِ."],"takhrij":"صحيح: رواه مسلم في الهبات (1625: 23) من طرق عن عبدالرزاق، أخبرنا معمر، عن الزهري، عن أبي سلمة، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب من قال: هي ترجع إلى الواهب إذا لم يقل: هي لك ولعقبك","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1625:23).","chapter_en":"The View That It Returns to the Giver If He Does Not Say, “It Is Yours and Your Descendants’”","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":20,"content":{"translation":{"en":["Jābir said: “The ʿumrā that the Messenger of Allāh ﷺ declared valid is when a person says, ‘It is yours and belongs to your descendants.’ But if he says, ‘It is yours for as long as you live,’ then it returns to its original owner.” Maʿmar said: “Al-Zuhrī used to issue legal rulings according to this.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":23,"lafz":true},{"key":"muslim","label":"مسلم في الهبات","number":1625,"n":4191}],"full":1,"dr":1},{"num":6031,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ قَالَ رَسُولُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْعُمْرَى جَائِزَةٌ لأَهْلِهَا وَالرُّقْبَى جَائِزَةٌ لأَهْلِهَا."],"takhrij":"صحيح: رواه أبو داود (3558)، والترمذي (1351)، وابن ماجه (2383)، والنسائي (3739) كلهم من حديث داود بن أبي هند، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الرقبى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (3558), al-Tirmidhī (1351), who graded it Hasan, Ibn Mājah (2383), and al-Nasāʾī (3739).","chapter_en":"What Has Been Reported Concerning Ruqbā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Jābir reported that the Messenger of Allāh ﷺ said: “ʿUmrā is valid for its recipients, and ruqbā is valid for its recipients.”"]},"buhuth":{"en":["Ruqbā is when a person grants property on the condition that whichever of the two parties dies first, the property will belong to the other. Thus each of them waits for and watches for the death of the other."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3558,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1351},{"key":"ibnmajah","label":"ابن ماجه","number":2383},{"key":"nasai","label":"النسائي","number":3739,"n":3739}],"full":1,"dr":1},{"num":6032,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ ثَابِتٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ أَعْمَرَ شَيْئًا فَهُوَ لِمُعْمَرِهِ مَحْيَاهُ وَمَمَاتَهُ وَلاَ تُرْقِبُوا فَمَنْ أَرْقَبَ شَيئًا فَهُوَ سَبِيلُهُ."],"takhrij":"حسن: رواه أبو داود (3559) عن عبد الله بن محمد النفيلي قال: قرأت على معقل، عن عمرو بن دينار، عن طاوس، عن حُجر، عن زيد بن ثابت قال فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الرقبى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3559), al-Nasāʾī (3718), Ibn Mājah (2381), and Aḥmad (21586).","chapter_en":"What Has Been Reported Concerning Ruqbā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Zayd ibn Thābit reported that the Messenger of Allāh ﷺ said: “Whoever grants something as an ʿumrā, it belongs to the one to whom it was granted during his life and after his death. And do not make ruqbā grants; whoever grants something as a ruqbā, then it follows that course.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3559,"lafz":true},{"key":"nasai","label":"النسائي","number":3718,"n":3723},{"key":"ibnmajah","label":"ابن ماجه","number":2381},{"key":"ahmad","label":"أحمد","number":21586,"n":21651}],"full":1,"dr":1},{"num":6033,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الرُّقْبَى وَقَالَ: مَنْ أُرْقِبَ فَهُوَ لَهُ."],"takhrij":"صحيح: رواه النسائي (3734) -واللفظ له-، وأحمد (4801) كلاهما من حديث وكيع، عن يزيد بن زياد بن أبي الجعد، عن حبيب بن أبي ثابت، سمعت ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الرقبى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Nasāʾī (3734)—and this is his wording—and Aḥmad (4801).","chapter_en":"What Has Been Reported Concerning Ruqbā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Ibn ʿUmar said: “The Messenger of Allāh ﷺ prohibited ruqbā and said: ‘Whoever grants something as a ruqbā, then it belongs to the one to whom it was granted.’”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3734,"lafz":true,"n":3734},{"key":"ahmad","label":"مسند الإمام أحمد","number":4801,"n":4801}],"full":1,"dr":1},{"num":6034,"demo":false,"sanad":"","matn":["عن جابر بْنِ عبدالله رَضِيَ اللَّهُ عَنْهُمَا يَقُولُ مَرِضْتُ فَعَادَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبُو بَكْرٍ وَهُمَا مَاشِيَانِ، فَأَتَانِي وَقَدْ أُغْمِيَ عَلَىَّ فَتَوَضَّأَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَبَّ عَلَىَّ وَضُوءَهُ فَأَفَقْتُ. فَقُلْتُ يَا رَسُولَ اللَّهِ كَيْفَ أَصْنَعُ فِي مَالِي، كَيْفَ أَقْضِي فِي مَالِي فَلَمْ يُجِبْنِي بِشَىْءٍ حَتَّى نَزَلَتْ آيَةُ الْمَوَارِيثِ."],"takhrij":"متفق عليه: رواه البخاري في الفرائض (6723)، ومسلم في الفرائض (1616) كلاهما من حديث سفيان، عن محمد بن المنكدر سمع جابر بن عبدالله فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في نزول آية الميراث","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (6723) and Muslim (1616).","chapter_en":"What has been narrated regarding the revelation of the verse of inheritance","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Jabir ibn ‘Abdullah said: I became ill, and the Messenger of Allah ﷺ and Abu Bakr came walking to visit me. He came to me while I was unconscious. The Messenger of Allah ﷺ performed ablution, then poured some of his ablution water over me, and I regained consciousness. I said, “O Messenger of Allah ﷺ, what should I do regarding my wealth? How should I dispose of my wealth?” He did not answer me at all until the verse of inheritance was revealed."]},"intro":{"ar":["قال اللّٰه تعالى:","يُوصِيكُمُ ٱللَّهُ فِيٓ أَوْلَٰدِكُمْ ۖ لِلذَّكَرِ مِثْلُ حَظِّ ٱلْأُنثَيَيْنِ ۚ فَإِن كُنَّ نِسَآءً فَوْقَ ٱثْنَتَيْنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَ ۖ وَإِن كَانَتْ وَٰحِدَةً فَلَهَا ٱلنِّصْفُ ۚ وَلِأَبَوَيْهِ لِكُلِّ وَٰحِدٍ مِّنْهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُ وَلَدٌ ۚ فَإِن لَّمْ يَكُن لَّهُ وَلَدٌ وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُ ۚ فَإِن كَانَ لَهُۥٓ إِخْوَةٌ فَلِأُمِّهِ ٱلسُّدُسُ ۚ مِنۢ بَعْدِ وَصِيَّةٍ يُوصِي بِهَآ أَوْ دَيْنٍ ۗ ءَابَآؤُكُمْ وَأَبْنَآؤُكُمْ لَا تَدْرُونَ أَيُّهُمْ أَقْرَبُ لَكُمْ نَفْعًا ۚ فَرِيضَةً مِّنَ ٱللَّهِ ۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا ۝ وَلَكُمْ نِصْفُ مَا تَرَكَ أَزْوَٰجُكُمْ إِن لَّمْ يَكُن لَّهُنَّ وَلَدٌ ۚ فَإِن كَانَ لَهُنَّ وَلَدٌ فَلَكُمُ ٱلرُّبُعُ مِمَّا تَرَكْنَ مِنۢ بَعْدِ وَصِيَّةٍ يُوصِينَ بِهَآ أَوْ دَيْنٍ ۚ وَلَهُنَّ ٱلرُّبُعُ مِمَّا تَرَكْتُمْ إِن لَّمْ يَكُن لَّكُمْ وَلَدٌ ۚ فَإِن كَانَ لَكُمْ وَلَدٌ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكْتُم مِّنۢ بَعْدِ وَصِيَّةٍ تُوصُونَ بِهَآ أَوْ دَيْنٍ ۗ وَإِن كَانَ رَجُلٌ يُورَثُ كَلَٰلَةً أَوِ ٱمْرَأَةٌ وَلَهُۥٓ أَخٌ أَوْ أُخْتٌ فَلِكُلِّ وَٰحِدٍ مِّنْهُمَا ٱلسُّدُسُ ۚ فَإِن كَانُوٓا۟ أَكْثَرَ مِن ذَٰلِكَ فَهُمْ شُرَكَآءُ فِي ٱلثُّلُثِ مِنۢ بَعْدِ وَصِيَّةٍ يُوصَىٰ بِهَآ أَوْ دَيْنٍ غَيْرَ مُضَآرٍّ ۚ وَصِيَّةً مِّنَ ٱللَّهِ ۗ وَٱللَّهُ عَلِيمٌ حَلِيمٌ","[سورة النساء: ١١-١٢]"],"en":["Allah the Most High said:","“Allah instructs you concerning your children: for the male is the portion of two females. But if there are only daughters, two or more, then for them is two-thirds of what he leaves. If there is only one, then for her is half. And for his parents, for each one of them is one-sixth of what he leaves if he had a child. But if he had no child and his parents inherit from him, then for his mother is one-third. But if he had siblings, then for his mother is one-sixth, after any bequest he may have made or debt. Your parents and your children—you do not know which of them are nearest to you in benefit. This is an obligation from Allah. Indeed, Allah is All-Knowing, All-Wise. And for you is half of what your wives leave if they have no child. But if they have a child, then for you is one-fourth of what they leave, after any bequest they may have made or debt. And for them is one-fourth of what you leave if you have no child. But if you have a child, then for them is one-eighth of what you leave, after any bequest you may have made or debt. And if a man or a woman leaves neither ascendants nor descendants, but has a brother or a sister, then for each one of them is one-sixth. But if they are more than that, then they share in one-third, after any bequest that may have been made or debt, without causing harm. This is an instruction from Allah, and Allah is All-Knowing, Forbearing.”","[Surat al-Nisa’: 11–12]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6723,"lafz":true},{"key":"muslim","label":"مسلم","number":1616}],"full":1},{"num":6035,"demo":false,"sanad":"","matn":["عَنْ مَعْدَانَ بْنِ أَبِي طَلْحَةَ، أَنَّ عُمَرَ بْنَ الْخَطَّابِ، خَطَبَ يَوْمَ الْجُمُعَةِ فَذَكَرَ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَذَكَرَ أَبَا بَكْرٍ قَالَ إِنِّي رَأَيْتُ كَأَنَّ دِيكًا نَقَرَنِي ثَلاَثَ نَقَرَاتٍ وَإِنِّي لاَ أُرَاهُ إِلاَّ حُضُورَ أَجَلِي وَإِنَّ أَقْوَامًا يَأْمُرُونَنِي أَنْ أَسْتَخْلِفَ وَإِنَّ اللَّهَ لَمْ يَكُنْ لِيُضَيِّعَ دِينَهُ وَلاَ خِلاَفَتَهُ وَلاَ الَّذِي بَعَثَ بِهِ نَبِيَّهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَإِنْ عَجِلَ بِي أَمْرٌ فَالْخِلاَفَةُ شُورَى بَيْنَ هَؤُلاَءِ السِّتَّةِ الَّذِينَ تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ عَنْهُمْ رَاضٍ وَإِنِّي قَدْ عَلِمْتُ أَنَّ أَقْوَامًا يَطْعَنُونَ فِي هَذَا الأَمْرِ أَنَا ضَرَبْتُهُمْ بِيَدِي هَذِهِ عَلَى الإِسْلاَمِ فَإِنْ فَعَلُوا ذَلِكَ فَأُولَئِكَ أَعْدَاءُ اللَّهِ الْكَفَرَةُ الضُّلاَّلُ ثُمَّ إِنِّي لاَ أَدَعُ بَعْدِي شَيْئًا أَهَمَّ عِنْدِي مِنَ الْكَلاَلَةِ مَا رَاجَعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي شَىْءٍ مَا رَاجَعْتُهُ فِي الْكَلاَلَةِ وَمَا أَغْلَظَ لِي فِي شَىْءٍ مَا أَغْلَظَ لِي فِيهِ حَتَّى طَعَنَ بِإِصْبَعِهِ فِي صَدْرِي فَقَالَ يَا عُمَرُ أَلاَ تَكْفِيكَ آيَةُ الصَّيْفِ الَّتِي فِي آخِرِ سُورَةِ النِّسَاءِ. وَإِنِّي إِنْ أَعِشْ أَقْضِ فِيهَا بِقَضِيَّةٍ يَقْضِي بِهَا مَنْ يَقْرَأُ الْقُرْآنَ وَمَنْ لاَ يَقْرَأُ الْقُرْآنَ ثُمَّ قَالَ اللَّهُمَّ إِنِّي أُشْهِدُكَ عَلَى أُمَرَاءِ الأَمْصَارِ وَإِنِّي إِنَّمَا بَعَثْتُهُمْ عَلَيْهِمْ لِيَعْدِلُوا عَلَيْهِمْ وَلِيُعَلِّمُوا النَّاسَ دِينَهُمْ وَسُنَّةَ نَبِيِّهِمْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَيَقْسِمُوا فِيهِمْ فَيْئَهُمْ وَيَرْفَعُوا إِلَىَّ مَا أَشْكَلَ عَلَيْهِمْ مِنْ أَمْرِهِمْ ثُمَّ إِنَّكُمْ أَيُّهَا النَّاسُ تَأْكُلُونَ شَجَرَتَيْنِ لاَ أَرَاهُمَا إِلاَّ خَبِيثَتَيْنِ هَذَا الْبَصَلَ وَالثُّومَ لَقَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا وَجَدَ رِيحَهُمَا مِنَ الرَّجُلِ فِي الْمَسْجِدِ أَمَرَ بِهِ فَأُخْرِجَ إِلَى الْبَقِيعِ فَمَنْ أَكَلَهُمَا فَلْيُمِتْهُمَا طَبْخًا."],"takhrij":"صحيح: رواه مسلم في المساجد (567) عن محمد بن المثنى، حدثنا يحيى بن سعيد، حدثنا هشام، حدثنا قتادة، عن سالم بن أبي الجعد، عن معدان بن أبي طلحة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الكلالة","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (567).","chapter_en":"What has been narrated regarding al-kalalah","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Maʿdān ibn Abī Ṭalḥah reported that ʿUmar ibn al-Khaṭṭāb delivered a sermon on Friday. He mentioned the Prophet of Allah ﷺ and Abū Bakr, then said: “I saw in a dream as though a rooster pecked me three times, and I understand this to mean that my death is near. Some people are urging me to appoint a successor, but Allah will not allow His religion, His caliphate, or that with which He sent His Prophet ﷺ to be lost. If death overtakes me soon, then the caliphate is to be decided by consultation among these six men with whom the Messenger of Allah ﷺ was pleased when he died. I know that some people will criticize this matter—people whom I struck with this very hand for the sake of Islam. If they do so, then they are the enemies of Allah, disbelievers and misguided. I leave behind nothing that concerns me more than the matter of kalālah. I never repeatedly questioned the Messenger of Allah ﷺ about anything as much as I questioned him about kalālah, and he was never as stern with me concerning anything as he was concerning it, until he poked me in the chest with his finger and said: ‘O ʿUmar, is the summer verse at the end of Sūrat al-Nisāʾ not sufficient for you?’ If I live, I will issue a ruling concerning it by which both the one who reads the Qurʾān and the one who does not read it will be able to judge.” Then he said: “O Allah, I call You to witness concerning the governors of the provinces. I sent them over the people only so that they would deal justly with them, teach them their religion and the Sunnah of their Prophet ﷺ, distribute their public wealth among them, and refer back to me whatever matters were unclear to them. O people, you eat two plants that I consider foul: onions and garlic. I saw the Messenger of Allah ﷺ, when he detected their smell from a man in the mosque, order that he be taken out to al-Baqīʿ. Whoever eats them should remove their odor by cooking them.”"]},"buhuth":{"en":["“The summer verse” means the verse that was revealed during the summer.","Al-Wāḥidī said: Allah revealed two verses concerning kalālah: one in winter, which is near the beginning of Sūrat al-Nisāʾ, and the other in summer, which is at its end."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":567,"lafz":true}],"full":1,"dr":1},{"num":6036,"demo":false,"sanad":"","matn":["عن عُمَرَ بن الْخَطَّابِ سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْكَلاَلَةِ فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَكْفِيكَ مِنْ ذَلِكَ الآيَةُ الَّتِي أُنْزِلَتْ فِي الصَّيْفِ آخِرَ سُورَةِ النِّسَاءِ."],"takhrij":"صحيح:  رواه مالك في الفرائض (7) عن زيد بن أسلم أن عمر بن الخطاب سأل رسول الله صلى الله عليه وسلم  فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الكلالة","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (7).","chapter_en":"What has been narrated regarding al-kalalah","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["‘Umar ibn al-Khattab narrated that he asked the Messenger of Allah ﷺ about al-kalalah, so the Messenger of Allah ﷺ said to him: “The verse that was revealed in the summer at the end of Surat al-Nisa’ is sufficient for you concerning that.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":7,"lafz":true}],"full":1},{"num":6037,"demo":false,"sanad":"","matn":["عَنْ الْبَرَاءِ قَالَ: آخِرُ سُورَةٍ نَزَلَتْ: (بَرَاءَةَ). وَآخِرُ آيَةٍ نَزَلَتْ: يَسْتَفْتُونَكَ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4605)، ومسلم في الفرائض (1618) كلاهما من حديث شعبة، عن أبي إسحاق، سمعت البراء فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الكلالة","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (4605) and Muslim (1618).","chapter_en":"What has been narrated regarding al-kalalah","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Al-Bara’ said: The last surah to be revealed was Bara’ah, and the last verse to be revealed was: “They ask you for a legal ruling…”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4605,"lafz":true},{"key":"muslim","label":"مسلم","number":1618}],"full":1},{"num":6038,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ، قَالَ جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ يَا رَسُولَ اللَّهِ يَسْتَفْتُونَكَ فِي الْكَلاَلَةِ فَمَا الْكَلاَلَةُ قَالَ تُجْزِيكَ آيَةُ الصَّيْفِ."],"takhrij":"حسن: رواه أبو داود (2889)، والترمذي (3042)، وأحمد (18589) كلهم من حديث أبي بكر بن عياش، عن أبي إسحاق، عن البراء فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الكلالة","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (2889), al-Tirmidhi (3042), and Ahmad (18607, 18589).","chapter_en":"What has been narrated regarding al-kalalah","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Al-Bara’ ibn ‘Azib said: A man came to the Prophet ﷺ and said, “O Messenger of Allah ﷺ, they ask you for a ruling concerning al-kalalah—what is al-kalalah?” He said: “The summer verse is sufficient for you.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2889,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":3042},{"key":"ahmad","label":"مسند الإمام أحمد","number":18607,"n":18647},{"key":"ahmad","label":"احمد","number":18589,"n":18647}],"full":1,"dr":1},{"num":6039,"demo":false,"sanad":"","matn":["عن جابر قال: اشتكيت وعندي سبع أخوات، فدخل علي رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فنفخ في وجهي، فأفقت، فقلت: يا رسول الله، ألا أوصي لأخواتي بالثلث؟ قال: أحسن. قلت: الشطر؟ قال: أحسن. ثم خرج، وتركني. فقال: يا جابر، لا أُراك ميتا من وجعك هذا، وإن الله قد أنزل، فبين لأخواتك، فجعل لهن الثلثين. قال: فكان جابر يقول: أنزلت هذه الآية في: ﴿يَسْتَفْتُونَكَ قُلِ اللَّهُ يُفْتِيكُمْ فِي الْكَلَالَةِ إِنِ امْرُؤٌ هَلَكَ لَيْسَ لَهُ وَلَدٌ وَلَهُ أُخْتٌ فَلَهَا نِصْفُ مَا تَرَكَ وَهُوَ يَرِثُهَا إِنْ لَمْ يَكُنْ لَهَا وَلَدٌ فَإِنْ كَانَتَا اثْنَتَيْنِ فَلَهُمَا الثُّلُثَانِ مِمَّا تَرَكَ وَإِنْ كَانُوا إِخْوَةً رِجَالًا وَنِسَاءً فَلِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ يُبَيِّنُ اللَّهُ لَكُمْ أَنْ تَضِلُّوا وَاللَّهُ بِكُلِّ شَيْءٍ عَلِيمٌ﴾ [النساء:١٧٦]"],"takhrij":"صحيح: رواه أبو داود (2887) عن عثمان بن أبي شيبة، حدثنا كثير بن هشام، حدثنا هشام -يعنى الدستوائي-، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الكلالة","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2887).","chapter_en":"What has been narrated regarding al-kalalah","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Jabir said: I fell ill, and I had seven sisters. The Messenger of Allah ﷺ came to me and blew on my face, so I regained consciousness. I said, “O Messenger of Allah ﷺ, should I make a bequest of one-third for my sisters?” He said: “Do good.” I said: “Half?” He said: “Do good.” Then he left me and said: “O Jabir, I do not think you will die from this illness of yours, and Allah has revealed and clarified the matter of your sisters, making for them two-thirds.” Jabir used to say: This verse was revealed concerning me: “They ask you for a legal ruling. Say: Allah gives you a ruling concerning one who leaves neither ascendants nor descendants. If a man dies leaving no child but has a sister, then for her is half of what he left. And he inherits from her if she has no child. But if there are two sisters, then for them is two-thirds of what he left. And if they are siblings, men and women, then for the male is the share of two females. Allah makes this clear to you so that you do not go astray, and Allah is Knowing of all things.” [Surat al-Nisa’: 176]"]},"buhuth":{"en":["Al-kalalah: Most of the Companions said it refers to the one who leaves neither child nor parent. It was also said: the one who leaves no child."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2887,"lafz":true}],"full":1,"dr":1},{"num":6040,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس قال: قال رسول الله صلى الله عليه وسلم  قال: ألحقوا الفرائض بأهلها، فما بقي فهو لأولى رجل ذكر."],"takhrij":"متفق عليه: رواه البخاري في الفرائض (6732)، ومسلم في الفرائض (1615) كلاهمـا من حديث وهيب، عن ابن طاوس، عن أبيه، عن عبد الله ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب في ميراث العصبة","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6732) and Muslim (1615).","chapter_en":"Regarding the inheritance of agnatic heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās reported that the Messenger of Allah ﷺ said: “Give the prescribed shares to those who are entitled to them, and whatever remains goes to the nearest male relative.”"]},"buhuth":{"en":["“Give the prescribed shares to those entitled to them” means: give the holders of the fixed inheritance shares their allotted portions.","“The nearest male relative” means the male relative who is closest in lineage."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6732,"lafz":true},{"key":"muslim","label":"مسلم","number":1615}],"full":1,"dr":1},{"num":6041,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اقْسِمُوا الْمَالَ بَيْنَ أَهْلِ الْفَرَائِضِ عَلَى كِتَابِ اللَّهِ فَمَا تَرَكَتِ الْفَرَائِضُ فَلأَوْلَى رَجُلٍ ذَكَرٍ."],"takhrij":"صحيح: رواه مسلم في الفرائض (1615: 4) من طرق عن عبدالرزاق، أخبرنا معمر، عن ابن طاوس، عن أبيه، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب في ميراث العصبة","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1615/4).","chapter_en":"Regarding the inheritance of agnatic heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["‘Abdullah ibn ‘Abbas said: The Messenger of Allah ﷺ said: “Distribute the wealth among those entitled to the fixed shares according to the Book of Allah, and whatever the fixed shares leave, it goes to the nearest male agnatic heir.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":4,"lafz":true},{"key":"muslim","label":"مسلم في الفرائض","number":1615,"n":4143}],"full":1},{"num":6042,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّهُ قَالَ قَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي جَنِينِ امْرَأَةٍ مِنْ بَنِي لَحْيَانَ سَقَطَ مَيِّتًا بِغُرَّةٍ عَبْدٍ أَوْ أَمَةٍ. ثُمَّ إِنَّ الْمَرْأَةَ الَّتِي قَضَى عَلَيْهَا بِالْغُرَّةِ تُوُفِّيَتْ، فَقَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِأَنَّ مِيرَاثَهَا لِبَنِيهَا وَزَوْجِهَا، وَأَنَّ الْعَقْلَ عَلَى عَصَبَتِهَا."],"takhrij":"متفق عليه: رواه البخاري في الفرائض (6740)، ومسلم في القسامة (1681: 35) كلاهما عن قتيبة بن سعيد، حدثنا الليث، عن ابن شهاب، عن ابن المسيب، عن أبى هريرة فذكره. ورواه مالك مختصرا موصولا ومرسلا.","grade":"متفق عليه","chapter_ar":"باب ما جاء أن الأموال للورثة، والعقل على العصبة","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (6740) and Muslim (1681/35).","chapter_en":"What has been narrated that wealth belongs to the heirs, while blood-money liability is upon the agnatic relatives","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ ruled concerning the fetus of a woman from Banu Lihyan that was miscarried dead that its compensation was a male or female slave. Then the woman against whom the compensation had been ruled died, so the Messenger of Allah ﷺ ruled that her inheritance belonged to her children and her husband, while the blood-money liability was upon her agnatic relatives."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6740,"lafz":true},{"key":"muslim","label":"مسلم","number":35},{"key":"muslim","label":"مسلم في القسامه","number":1681,"n":4390}],"full":1,"dr":1},{"num":6043,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُؤْتَى بِالرَّجُلِ الميت عَلَيْهِ الدَّيْنُ، فَيَسْأَلُ: هَلْ تَرَكَ لِدَيْنِهِ من قضاء؟. فَإِنْ حُدِّثَ أَنَّهُ تَرَكَ وَفَاءً صَلَّى عَلَيْهِ، وَإِلاَّ قَالَ: صَلُّوا عَلَى صَاحِبِكُمْ. فَلَمَّا فَتَحَ اللَّهُ عَلَيْهِ الْفُتُوحَ قَالَ: أَنَا أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ، فَمَنْ تُوُفِّيَ وَعَلَيْهِ دَيْنٌ فعلي قَضَاؤُهُ، وَمَنْ تَرَكَ مَالاً فهو لورثته."],"takhrij":"متفق عليه: رواه البخاري في الكفالة (2298)، ومسلم في الفرائض (1619) كلاهما من حديث الليث، عن عقيل، عن ابن شهاب، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب من ترك مالا فهو لورثته","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2298) and Muslim (1619).","chapter_en":"Whoever leaves wealth, it belongs to his heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah narrated that when a deceased man who owed debt was brought to the Messenger of Allah ﷺ, he would ask: “Has he left anything with which his debt can be paid?” If he was told that he had left enough to repay it, he would pray over him. Otherwise, he would say: “Pray over your companion.” Then when Allah granted him conquests, he said: “I am closer to the believers than their own selves. So whoever dies owing a debt, its repayment is upon me; and whoever leaves wealth, it belongs to his heirs.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2298,"lafz":true},{"key":"muslim","label":"مسلم","number":1619}],"full":1,"dr":1},{"num":6044,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ تَرَكَ مَالاً فَلِوَرَثَتِهِ، وَمَنْ تَرَكَ كَلاًّ فَإِلَيْنَا. وَفِي رِوَايَةِ: وَمَنْ تَرَكَ كَلاًّ وليتُه."],"takhrij":"متفق عليه: رواه البخاري في الاستقراض (2398)، ومسلم في الفرائض (1619: 17) كلاهما من شعبة، عن عدي، أنه سمع أبا حازم، عن أبي هـريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب من ترك مالا فهو لورثته","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2398) and Muslim (1619/17).","chapter_en":"Whoever leaves wealth, it belongs to his heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “Whoever leaves behind wealth, it belongs to his heirs; and whoever leaves behind dependents with no one to provide for them, then they are for us.” In another wording: “And whoever leaves behind dependents, then they are upon me.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2398,"lafz":true},{"key":"muslim","label":"مسلم","number":17},{"key":"muslim","label":"مسلم في الفرائض","number":1619,"n":4161}],"full":1},{"num":6045,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَا مِنْ مُؤْمِنٍ إِلاَّ وَأَنَا أَوْلَى بِهِ فِي الدُّنْيَا وَالآخِرَةِ اقْرَءُوا إِنْ شِئْتُمْ ﴿النَّبِيُّ أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ﴾ [سورة الأحزاب: 6]} فَأَيُّمَا مُؤْمِنٍ مَاتَ وَتَرَكَ مَالاً فَلْيَرِثْهُ عَصَبَتُهُ مَنْ كَانُوا، وَمَنْ تَرَكَ دَيْنًا أَوْ ضَيَاعًا فَلْيَأْتِنِي فَأَنَا مَوْلاَهُ."],"takhrij":"صحيح: رواه البخاري في الاستقراض (2399) عن عبد الله بن محمد، حدثنا أبو عامر، حدثنا فُليح، عن أبي حازم، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب من ترك مالا فهو لورثته","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2399).","chapter_en":"Whoever leaves wealth, it belongs to his heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said: “There is no believer except that I am closer to him in this world and the Hereafter. Recite, if you wish: ‘The Prophet is closer to the believers than their own selves’ [Surat al-Ahzab: 6]. So whichever believer dies and leaves wealth, let his relatives inherit him, whoever they may be. And whoever leaves behind debt or dependents in need, let them come to me, for I am his guardian.”"]},"buhuth":{"en":["His statement, “let his ‘asabah inherit him,” means his heirs generally, not only those who inherit through agnatic succession in the technical sense.","What is meant by ‘asabah here is a man’s relatives on the father’s side, those connected to the deceased through a male ancestor, near or far. They are called that because they surround and support him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2399,"lafz":true}],"full":1,"dr":1},{"num":6046,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَا أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ، فَمَنْ مَاتَ وَتَرَكَ مَالاً فَمَالُهُ لِمَوَالِي الْعَصَبَةِ، وَمَنْ تَرَكَ كَلاًّ أَوْ ضَيَاعًا، فَأَنَا وَلِيُّهُ فَلأُدْعَى لَهُ."],"takhrij":"صحيح: رواه البخاري في الفرائض (6745) عن محمود، أخبرنا عبيدالله، عن إسرائيل، عن أبي حصين، عن أبي صالح، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب من ترك مالا فهو لورثته","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6745).","chapter_en":"Whoever leaves wealth, it belongs to his heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “I am closer to the believers than their own selves. So whoever dies and leaves wealth, then his wealth belongs to his agnatic heirs. And whoever leaves behind dependents or helpless family members, then I am his guardian, so let me be called for him.”"]},"buhuth":{"en":["His statement, “dependents,” means needy people left behind with nothing, and I take charge of them and provide for them."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6745,"lafz":true}],"full":1,"dr":1,"rep":[13037]},{"num":6047,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ إِنْ عَلَى الأَرْضِ مِنْ مُؤْمِنٍ إِلاَّ أَنَا أَوْلَى النَّاسِ بِهِ فَأَيُّكُمْ مَا تَرَكَ دَيْنًا أَوْ ضَيَاعًا فَأَنَا مَوْلاَهُ وَأَيُّكُمْ تَرَكَ مَالاً فَإِلَى الْعَصَبَةِ مَنْ كَانَ."],"takhrij":"صحيح: رواه مسلم في الفرائض (1619: 15) عن محمد بن رافع، حدثنا شبابة قال: حدثني ورقاء، عن أبي الـزناد، عن الأعـرج، عن أبى هريرة فذكره.","grade":"صحيح","chapter_ar":"باب من ترك مالا فهو لورثته","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1619/15).","chapter_en":"Whoever leaves wealth, it belongs to his heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “By the One in whose hand is Muhammad’s soul, there is no believer on the face of the earth except that I am the closest of people to him. So whichever of you leaves behind debt or dependents, then I am his guardian; and whichever of you leaves behind wealth, then it goes to his agnatic heirs, whoever they may be.”"]},"buhuth":{"en":["His statement, “there is no believer on the earth,” means: there is not on the earth any believer. The particle here is used in the sense of negation, and “min” is added to emphasize universality.","And “dependents” means children or family members in need who have nothing."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":15,"lafz":true},{"key":"muslim","label":"مسلم في الفرائض","number":1619,"n":4159}],"full":1,"dr":1,"rep":[13039]},{"num":6048,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَنَا أَوْلَى النَّاسِ بِالْمُؤْمِنِينَ فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ، فَأَيُّكُمْ مَا تَرَكَ دَيْنًا أَوْ ضَيْعَةً فَادْعُونِي، فَأَنَا وليُّه، وَأَيُّكُمْ مَا تَرَكَ مَالاً فَلْيُؤْثَرْ بِمَالِهِ عَصَبَتُهُ مَنْ كَانَ."],"takhrij":"صحيح: رواه مسلم في الفرائض (1619: 16) عن محمد بن رافع، حدثنا عبدالرزاق، أخبرنا معمر، عن همام بن منبه قال: هذا ما حدثنا أبو هريرة عن رسول الله صلى الله عليه وسلم ، فذكر أحاديث، منها هذا.","grade":"صحيح","chapter_ar":"باب من ترك مالا فهو لورثته","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1619/16).","chapter_en":"Whoever leaves wealth, it belongs to his heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “I am the closest of people to the believers according to the Book of Allah, Mighty and Majestic. So whichever of you leaves behind debt or needy dependents, call me, for I am his guardian. And whichever of you leaves wealth, let his agnatic heirs inherit his wealth, whoever they may be.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":16,"lafz":true},{"key":"muslim","label":"مسلم في الفرائض","number":1619,"n":4160}],"full":1,"rep":[13038]},{"num":6049,"demo":false,"sanad":"","matn":["عَنْ جابر قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَنَا أَوْلَى بِكُلِّ مُؤْمِنٍ مِنْ نَفْسِهِ، مَنْ تَرَكَ مَالاً فَلأَهْلِهِ، وَمَنْ تَرَكَ دَيْنًا أَوْ ضَيَاعًا فإلَيَّ وعلَيَّ."],"takhrij":"صحيح: رواه مسلم في الجمعة (867/43) عن محمد بن المثنى، حدثنا عبدالوهاب بن عبد المجيد، عن جعفر بن محمد، عن أبيه، عن جابر بن عبدالله، فذكره في آخر حديث طويل.","grade":"صحيح","chapter_ar":"باب من ترك مالا فهو لورثته","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (867/43).","chapter_en":"Whoever leaves wealth, it belongs to his heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said: “I am closer to every believer than his own self. Whoever leaves behind wealth, it is for his family; and whoever leaves behind debt or dependents, then it is upon me and for me to take care of.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":43,"lafz":true}],"full":1,"dr":1},{"num":6050,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ فَاطِمَةَ ـ عَلَيْهَا السَّلاَمُ ـ بِنْتَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَرْسَلَتْ إِلَى أَبِي بَكْرٍ تَسْأَلُهُ مِيرَاثَهَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِمَّا أَفَاءَ اللَّهُ عَلَيْهِ بِالْمَدِينَةِ وَفَدَكَ، وَمَا بَقِيَ مِنْ خُمُسِ خَيْبَرَ، فَقَالَ أَبُو بَكْرٍ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ نُورَثُ، مَا تَرَكْنَا صَدَقَةٌ، إِنَّمَا يَأْكُلُ آلُ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي هَذَا الْمَالِ. وَإِنِّي وَاللَّهِ لاَ أُغَيِّرُ شَيْئًا مِنْ صَدَقَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ حَالِهَا الَّتِي كَانَ عَلَيْهَا فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلأَعْمَلَنَّ فِيهَا بِمَا عَمِلَ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَبَى أَبُو بَكْرٍ أَنْ يَدْفَعَ إِلَى فَاطِمَةَ مِنْهَا شَيْئًا فَوَجَدَتْ فَاطِمَةُ عَلَى أَبِي بَكْرٍ فِي ذَلِكَ فَهَجَرَتْهُ، فَلَمْ تُكَلِّمْهُ حَتَّى تُوُفِّيَتْ، وَعَاشَتْ بَعْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سِتَّةَ أَشْهُرٍ، فَلَمَّا تُوُفِّيَتْ، دَفَنَهَا زَوْجُهَا عَلِيٌّ لَيْلاً، وَلَمْ يُؤْذِنْ بِهَا أَبَا بَكْرٍ وَصَلَّى عَلَيْهَا، وَكَانَ لِعَلِيٍّ مِنَ النَّاسِ وَجْهٌ حَيَاةَ فَاطِمَةَ، فَلَمَّا تُوُفِّيَتِ اسْتَنْكَرَ عَلِيٌّ وُجُوهَ النَّاسِ، فَالْتَمَسَ مُصَالَحَةَ أَبِي بَكْرٍ وَمُبَايَعَتَهُ، وَلَمْ يَكُنْ يُبَايِعُ تِلْكَ الأَشْهُرَ، فَأَرْسَلَ إِلَى أَبِي بَكْرٍ أَنِ ائْتِنَا، وَلاَ يَأْتِنَا أَحَدٌ مَعَكَ، كَرَاهِيَةً لِمَحْضَرِ عُمَرَ. فَقَالَ عُمَرُ لاَ وَاللَّهِ لاَ تَدْخُلُ عَلَيْهِمْ وَحْدَكَ. فَقَالَ أَبُو بَكْرٍ وَمَا عَسَيْتَهُمْ أَنْ يَفْعَلُوا بِي، وَاللَّهِ لآتِيَنَّهُمْ. فَدَخَلَ عَلَيْهِمْ أَبُو بَكْرٍ، فَتَشَهَّدَ عَلِيٌّ فَقَالَ إِنَّا قَدْ عَرَفْنَا فَضْلَكَ، وَمَا أَعْطَاكَ، اللَّهُ وَلَمْ نَنْفَسْ عَلَيْكَ خَيْرًا سَاقَهُ اللَّهُ إِلَيْكَ، وَلَكِنَّكَ اسْتَبْدَدْتَ عَلَيْنَا بِالأَمْرِ، وَكُنَّا نَرَى لِقَرَابَتِنَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَصِيبًا. حَتَّى فَاضَتْ عَيْنَا أَبِي بَكْرٍ، فَلَمَّا تَكَلَّمَ أَبُو بَكْرٍ قَالَ وَالَّذِي نَفْسِي بِيَدِهِ لَقَرَابَةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَحَبُّ إِلَىَّ أَنْ أَصِلَ مِنْ قَرَابَتِي، وَأَمَّا الَّذِي شَجَرَ بَيْنِي وَبَيْنَكُمْ مِنْ هَذِهِ الأَمْوَالِ، فَلَمْ آلُ فِيهَا عَنِ الْخَيْرِ، وَلَمْ أَتْرُكْ أَمْرًا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصْنَعُهُ فِيهَا إِلاَّ صَنَعْتُهُ. فَقَالَ عَلِيٌّ لأَبِي بَكْرٍ مَوْعِدُكَ الْعَشِيَّةُ لِلْبَيْعَةِ. فَلَمَّا صَلَّى أَبُو بَكْرٍ الظُّهْرَ رَقِيَ عَلَى الْمِنْبَرِ، فَتَشَهَّدَ وَذَكَرَ شَأْنَ عَلِيٍّ، وَتَخَلُّفَهُ عَنِ الْبَيْعَةِ، وَعُذْرَهُ بِالَّذِي اعْتَذَرَ إِلَيْهِ، ثُمَّ اسْتَغْفَرَ، وَتَشَهَّدَ عَلِيٌّ فَعَظَّمَ حَقَّ أَبِي بَكْرٍ، وَحَدَّثَ أَنَّهُ لَمْ يَحْمِلْهُ عَلَى الَّذِي صَنَعَ نَفَاسَةً عَلَى أَبِي بَكْرٍ، وَلاَ إِنْكَارًا لِلَّذِي فَضَّلَهُ اللَّهُ بِهِ، وَلَكِنَّا نَرَى لَنَا فِي هَذَا الأَمْرِ نَصِيبًا، فَاسْتَبَدَّ عَلَيْنَا، فَوَجَدْنَا فِي أَنْفُسِنَا، فَسُرَّ بِذَلِكَ الْمُسْلِمُونَ وَقَالُوا أَصَبْتَ. وَكَانَ الْمُسْلِمُونَ إِلَى عَلِيٍّ قَرِيبًا، حِينَ رَاجَعَ الأَمْرَ الْمَعْرُوفَ."],"takhrij":"صحيح: رواه البخاري في المغازي (4240، 4241) عن يحيى بن بكير، حدثنا الليث، عن عقيل، عن ابن شهاب، عن عروة، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب قول النبي ﷺ:  لا نورث ما تركنا صدقة ","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4240, 4241).","chapter_en":"The statement of the Prophet ﷺ: “We are not inherited from; whatever we leave is charity.”","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["‘A’ishah narrated that Fatimah, may Allah be pleased with her, the daughter of the Prophet ﷺ, sent to Abu Bakr asking for her inheritance from the Messenger of Allah ﷺ from what Allah had given him in Madinah, Fadak, and what remained from the fifth of Khaybar. Abu Bakr said: “The Messenger of Allah ﷺ said: ‘We are not inherited from; whatever we leave is charity. The family of Muhammad ﷺ only eat from this wealth.’ By Allah, I will not change anything from the charity of the Messenger of Allah ﷺ from the state it was in during the lifetime of the Messenger of Allah ﷺ, and I will certainly act concerning it as the Messenger of Allah ﷺ acted.” So Abu Bakr refused to hand any of it over to Fatimah. Fatimah felt upset with Abu Bakr over that and kept away from him, and did not speak to him until she died. She lived six months after the Prophet ﷺ. When she died, her husband ‘Ali buried her at night and did not inform Abu Bakr, and he prayed over her. ‘Ali had standing among the people while Fatimah was alive, but when she died, ‘Ali noticed a change in the people’s attitude, so he sought reconciliation with Abu Bakr and to give him the pledge, and he had not done so during those months. He sent to Abu Bakr, “Come to us, but do not bring anyone with you,” because he disliked the presence of ‘Umar. ‘Umar said, “No, by Allah, you should not enter upon them alone.” Abu Bakr said, “What could they possibly do to me? By Allah, I will go to them.” So Abu Bakr entered. ‘Ali recited the testimony and said: “We do recognize your virtue and what Allah has given you, and we do not envy you for any good Allah has brought to you. But you acted independently regarding this matter, while we believed that because of our kinship to the Messenger of Allah ﷺ we had a share in it.” At that Abu Bakr’s eyes overflowed with tears. Then Abu Bakr spoke and said: “By the One in whose hand is my soul, maintaining the kinship of the Messenger of Allah ﷺ is more beloved to me than maintaining my own kinship. As for what arose between me and you regarding these properties, I have not withheld any good in them, nor did I abandon anything I saw the Messenger of Allah ﷺ doing concerning them except that I did the same.” Then ‘Ali said to Abu Bakr: “Your appointment with us for the pledge is this evening.” After Abu Bakr prayed Zuhr, he ascended the pulpit, recited the testimony, mentioned the matter of ‘Ali and his delay in the pledge, and accepted his excuse, then sought forgiveness. ‘Ali also recited the testimony, magnified the right of Abu Bakr, and said that what had prevented him was not jealousy toward Abu Bakr, nor denial of what Allah had granted him, but rather that we believed we had a share in this matter, and it had been decided without us, so we felt something in ourselves. The Muslims were pleased with that and said: “You have done right.” And the Muslims drew close again to ‘Ali when he returned to the matter in the proper way."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4240,"lafz":true},{"key":"bukhari","label":"البخاري في المغازي","number":4241}],"full":1},{"num":6051,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ يَقْتَسِمُ وَرَثَتِي دَنَانِيرَ مَا تَرَكْتُ بَعْدَ نَفَقَةِ نِسَائِي وَمُؤْنَةِ عَامِلِي فَهُوَ صَدَقَةٌ."],"takhrij":"متفق عليه: رواه مالك في الكلام والغيبة والتقى (28) عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره. ورواه البخاري في الفرائض (6729)، ومسلم في الجهاد والسير (1760) كلاهما من هذا الوجه.","grade":"متفق عليه","chapter_ar":"باب قول النبي ﷺ:  لا نورث ما تركنا صدقة ","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (28), al-Bukhari (6729), and Muslim (1760).","chapter_en":"The statement of the Prophet ﷺ: “We are not inherited from; whatever we leave is charity.”","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “My heirs do not divide dinars. Whatever I leave after the maintenance of my wives and the expenses of my worker is charity.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":28,"lafz":true},{"key":"bukhari","label":"البخاري","number":6729},{"key":"muslim","label":"مسلم","number":1760}],"full":1,"rep":[9386,12706]},{"num":6052,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ جَاءَتْ فَاطِمَةُ إِلَى أَبِي بَكْرٍ فَقَالَتْ مَنْ يَرِثُكَ قَالَ أَهْلِي وَوَلَدِي. قَالَتْ فَمَا لِي لاَ أَرِثُ أَبِي فَقَالَ أَبُو بَكْرٍ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ لاَ نُورَثُ. وَلَكِنِّي أَعُولُ مَنْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعُولُهُ وَأُنْفِقُ عَلَى مَنْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُنْفِقُ عَلَيْهِ."],"takhrij":"حسن: رواه الترمذي (1608) عن محمد بن المثنى قال: حدثنا أبو الوليد قال: حدثنا حماد بن سلمة، عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب قول النبي ﷺ:  لا نورث ما تركنا صدقة ","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: narrated by al-Tirmidhi (1608), who graded it Hasan.","chapter_en":"The statement of the Prophet ﷺ: “We are not inherited from; whatever we leave is charity.”","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah said: Fatimah came to Abu Bakr and said, “Who will inherit from you?” He said, “My family and my children.” She said, “Then why do I not inherit from my father?” Abu Bakr said, “I heard the Messenger of Allah ﷺ say: ‘We are not inherited from.’ But I do support those whom the Messenger of Allah ﷺ used to support, and I spend on those upon whom the Messenger of Allah ﷺ used to spend.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1608,"lafz":true}],"full":1,"dr":1},{"num":6053,"demo":false,"sanad":"","matn":["عَنْ مَالِكِ بن أَوْسٍ بْنِ الْحَدَثَانِ النصري قَالَ: إن عُمَرَ بْنُ الْخَطَّابِ دَعَاهُ، فَانْطَلَقْتُ حَتَّى دَخَلْتُ عَلَيْهِ، فَأَتَاهُ حَاجِبُهُ يَرْفَأُ، فَقَالَ: هَلْ لَكَ فِي عُثْمَانَ وَعَبْدِ الرَّحْمَنِ وَالزُّبَيْرِ وَسَعْدٍ؟ قَالَ: نَعَمْ. فَأَذِنَ لَهُمْ، ثُمَّ قَالَ: هَلْ لَكَ فِي عَلِيٍّ وَعَبَّاسٍ؟ قَالَ: نَعَمْ. قَالَ عَبَّاسٌ: يَا أَمِيرَ الْمُؤْمِنِينَ، اقْضِ بَيْنِي وَبَيْنَ هَذَا. قَالَ: أَنْشُدُكُمْ بِاللَّهِ الَّذِي بِإِذْنِهِ تَقُومُ السَّمَاءُ وَالأَرْضُ هَلْ تَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ نُورَثُ مَا تَرَكْنَا صَدَقَةٌ؟ يُرِيدُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَفْسَهُ. فَقَالَ الرَّهْطُ: قَدْ قَالَ ذَلِكَ. فَأَقْبَلَ عَلَى عَليٍّ وَعَبَّاسٍ، فَقَالَ: هَلْ تَعْلَمَانِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ ذَلِكَ؟ قَالاَ: قَدْ قَالَ ذَلِكَ. قَالَ عُمَرُ: فَإِنِّي أُحَدِّثُكُمْ عَنْ هَذَا الأَمْرِ، إِنَّ اللَّهَ قَدْ كَانَ خَصَّ رَسُولَهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي هَذَا الفيء بشيء لَمْ يُعْطِهِ أَحَدًا غَيْرَهُ، فَقَالَ عَزَّ وَجَلَّ: مَا أَفَاءَ اللَّهُ عَلَى رَسُولِهِ إِلَى قَوْلِهِ قَدِيرٌ [سورة الْحَشْرِ: ٦] فَكَانَتْ خَالِصَةً لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَاللَّهِ مَا احْتَازَهَا دُونَكُمْ، وَلاَ أستأثر بِهَا عَلَيْكُمْ، لَقَدْ أعطاكموها وَبَثَّهَا فِيكُمْ، حَتَّى بَقِيَ مِنْهَا هَذَا الْمَالُ، فَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُنْفِقُ عَلَى أَهْلِهِ مِنْ هَذَا الْمَالِ نَفَقَةَ سَنَتِهِ، ثُمَّ يَأْخُذُ مَا بَقِيَ، فَيَجْعَلُهُ مَجْعَلَ مَالِ اللَّهِ، فَعَمِلَ بذاك رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَيَاتَهُ، أَنْشُدُكُمْ بِاللَّهِ هَلْ تَعْلَمُونَ ذَلِكَ؟ قَالُوا: نَعَمْ، ثُمَّ قَالَ لِعَلِيٍّ وَعَبَّاسٍ: أَنْشُدُكُمَا بِاللَّهِ هَلْ تَعْلَمَانِ ذَلِكَ؟ قَالاَ: نَعَمْ. فَتَوَفَّى اللَّهُ نَبِيَّهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَقَالَ أَبُو بَكْرٍ: أَنَا وَلِيُّ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَقَبَضَهَا، فَعَمِلَ بِمَا عَمِلَ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، ثُمَّ تَوَفَّى اللَّهُ أَبَا بَكْرٍ، فَقُلْتُ: أَنَا وَلِيُّ وَلِيِّ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَقَبَضْتُهَا سَنَتَيْنِ أَعْمَلُ فِيهَا مَا عَمِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبُو بَكْرٍ، ثُمَّ جِئْتُمَانِي، وكَلِمَتُكما وَاحِدَةٌ، وَأَمْرُكُمَا جَمِيعٌ، جِئْتَنِي تَسْأَلُنِي نَصِيبَكَ مِنِ ابْنِ أَخِيكَ، وَأَتَانِي هَذَا يَسْأَلُنِي نَصِيبَ امْرَأَتِهِ مِنْ أَبِيهَا، فَقُلْتُ: إِنْ شِئْتُمَا دَفَعْتُهَا إِلَيْكُمَا بِذَلِكَ، فتَلْتَمِسان مِنِّي قَضَاءً غَيْرَ ذَلِكَ، فَوَاللَّهِ الَّذِي بِإِذْنِهِ تَقُومُ السَّمَاءُ وَالأَرْضُ لاَ أَقْضِي فِيهَا قَضَاءً غَيْرَ ذَلِكَ حَتَّى تَقُومَ السَّاعَةُ، فَإِنْ عَجَزْتُمَا فَادْفَعَاهَا إِلَى، فَأَنَا أَكْفِيكُمَاهَا\"."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4033)، وفي الفرائض (6728)، ومسلم في الجهاد والسير (1757: 49) كلاهما من حديث الزهري قال: أخبرني مالك بن أوس بن الحـدثان فـذكره. واللفظ للبخاري. ولفـظ مسلم نحوه.","grade":"متفق عليه","chapter_ar":"باب قول النبي ﷺ:  لا نورث ما تركنا صدقة ","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4033, 6728) and Muslim (1757/49). This is the wording of al-Bukhārī.","chapter_en":"The statement of the Prophet ﷺ: “We are not inherited from; whatever we leave is charity.”","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Mālik ibn Aws ibn al-Ḥadathān al-Naṣrī reported: ʿUmar ibn al-Khaṭṭāb sent for him, so I went and entered upon him. His doorkeeper Yarfaʾ came and said: “Will you admit ʿUthmān, ʿAbd al-Raḥmān, al-Zubayr, and Saʿd?” He replied: “Yes.” So he admitted them. Then he said: “Will you admit ʿAlī and al-ʿAbbās?” He replied: “Yes.” Al-ʿAbbās said: “O Commander of the Believers, judge between me and this man.” ʿUmar said: “I adjure you by Allah, by whose permission the heaven and earth stand: do you know that the Messenger of Allah ﷺ said: ‘We prophets are not inherited from; whatever we leave is charity’?” The group replied: “Yes, he said that.” Then he turned to ʿAlī and al-ʿAbbās and asked: “Do you both know that the Messenger of Allah ﷺ said this?” They replied: “Yes, he said it.” ʿUmar said: “I will explain this matter to you. Allah singled out His Messenger ﷺ concerning this fayʾ with something He did not grant to anyone else.” Then he recited: “And whatever Allah restored to His Messenger from them—you did not spur any horses or camels against it; rather, Allah gives His messengers authority over whom He wills, and Allah is over all things powerful.” [Surah al-Ḥashr 59:6] “So it belonged exclusively to the Messenger of Allah ﷺ. By Allah, he did not keep it from you, nor did he prefer himself over you with it. Rather, he distributed it among you until only this property remained. The Prophet ﷺ would spend from this property on his family for their yearly maintenance, then take whatever remained and place it where the wealth of Allah was to be placed. The Messenger of Allah ﷺ did this throughout his lifetime. I adjure you by Allah, do you know this?” They replied: “Yes.” Then he said to ʿAlī and al-ʿAbbās: “I adjure you both by Allah, do you know this?” They replied: “Yes.” Then Allah took His Prophet ﷺ, and Abū Bakr said: ‘I am the successor responsible for the property of the Messenger of Allah ﷺ.’ He took possession of it and dealt with it just as the Messenger of Allah ﷺ had dealt with it. Then Allah took Abū Bakr, and I said: ‘I am the successor of the successor of the Messenger of Allah ﷺ.’ I took possession of it for two years and administered it as the Messenger of Allah ﷺ and Abū Bakr had done. Then you both came to me with the same claim and a united matter. You came asking for your share from your nephew, while this man came asking for his wife’s share from her father. I said: ‘If you wish, I will hand it over to you on that condition.’ Are you now asking me for some judgment other than that? By Allah, by whose permission the heaven and earth stand, I will not issue any ruling concerning it other than this until the Hour is established. If you are unable to administer it, then return it to me and I will take care of it for you.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4033,"lafz":true},{"key":"muslim","label":"مسلم","number":1757}],"full":1},{"num":6054,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّهَا قَالَتْ إِنَّ أَزْوَاجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَرَدْنَ أَنْ يَبْعَثْنَ عُثْمَانَ بْنَ عَفَّانَ إِلَى أَبِي بَكْرٍ فَيَسْأَلْنَهُ مِيرَاثَهُنَّ مِنَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ عَائِشَةُ لَهُنَّ أَلَيْسَ قَدْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ نُورَثُ مَا تَرَكْنَا فَهُوَ صَدَقَةٌ."],"takhrij":"متفق عليه: رواه مالك في الكلام والغيبة والتقى (27) عن ابن شهاب، عن عروة بن الزبير، عن عائشة فذكرته. ورواه البخاري في الفرائض (6730)، ومسلم في الجهاد والسير (1758) كلاهما من هذا الوجه.","grade":"متفق عليه","chapter_ar":"باب قول النبي ﷺ:  لا نورث ما تركنا صدقة ","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (27), al-Bukhari (6730), and Muslim (1758).","chapter_en":"The statement of the Prophet ﷺ: “We are not inherited from; whatever we leave is charity.”","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["‘A’ishah narrated that when the Messenger of Allah ﷺ died, the wives of the Prophet ﷺ wanted to send ‘Uthman ibn ‘Affan to Abu Bakr al-Siddiq to ask him for their inheritance from the Messenger of Allah ﷺ. ‘A’ishah said to them: “Did not the Messenger of Allah ﷺ say: ‘We are not inherited from; whatever we leave is charity’?”"]},"buhuth":{"en":["And Abu Dawud (2977) narrated through another route that ‘A’ishah said: “Will you not fear Allah? Did you not hear the Messenger of Allah ﷺ say: ‘We are not inherited from; whatever we leave is charity. This wealth is only for the family of Muhammad—for their emergent needs and their guests—and when I die it goes to the one in authority after me.’”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":27,"lafz":true},{"key":"bukhari","label":"البخاري","number":6730},{"key":"muslim","label":"مسلم","number":1758}],"full":1,"dr":1,"rep":[12705]},{"num":6055,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: لَمَّا قُبِضَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَاسْتُخْلِفَ أَبُو بَكْرٍ، خَاصَمَ الْعَبَّاسُ عَلِيًّا فِي أَشْيَاءَ تَرَكَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ أَبُو بَكْرٍ: شَيْءٌ تَرَكَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمْ يُحَرِّكْهُ فَلا أُحَرِّكُهُ. فَلَمَّا اسْتُخْلِفَ عُمَرُ اخْتَصَمَا إِلَيْهِ، فَقَالَ: شَيْءٌ لَمْ يُحَرِّكْهُ أَبُو بَكْرٍ فَلَسْتُ أُحَرِّكُهُ، قَالَ: فَلَمَّا اسْتُخْلِفَ عُثْمَانُ اخْتَصَمَا إِلَيْهِ، قَالَ: فَأَسْكَتَ عُثْمَانُ وَنَكَّسَ رَأْسَهُ، قَالَ ابْنُ عَبَّاسٍ: فَخَشِيتُ أَنْ يَأْخُذَهُ، فَضَرَبْتُ بِيَدِي بَيْنَ كَتِفَيِ الْعَبَّاسِ، فَقُلْتُ: يَا أَبَتِ، أَقْسَمْتُ عَلَيْكَ إِلَّا سَلَّمْتَهُ لِعَلِيٍّ، قَالَ: فَسَلَّمَهُ لَهُ."],"takhrij":"صحيح: رواه أحمد (77) عن يحيى بن حماد، حدثنا أبو عوانة، عن الأعمش، عن إسماعيل بن رجاء، عن عمير مولى العباس، عن ابن عباس فذكره. ورواه أبو يعلى (26) عن أبي خيثمة، حدثنا يحيى بن حماد بإسناده مختصرا.","grade":"صحيح","chapter_ar":"باب قول النبي ﷺ:  لا نورث ما تركنا صدقة ","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (77) and Abu Ya‘la (26).","chapter_en":"The statement of the Prophet ﷺ: “We are not inherited from; whatever we leave is charity.”","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Ibn ‘Abbas said: When the Messenger of Allah ﷺ passed away and Abu Bakr became caliph, al-‘Abbas and ‘Ali disputed concerning certain things the Messenger of Allah ﷺ had left. Abu Bakr said, “Anything the Messenger of Allah ﷺ left without changing, I will not change.” Then when ‘Umar became caliph, they brought their dispute to him, and he said, “Anything Abu Bakr did not alter, I will not alter.” Then when ‘Uthman became caliph, they brought the dispute to him. ‘Uthman remained silent and lowered his head. Ibn ‘Abbas said: I feared that he might decide to take it, so I struck al-‘Abbas between his shoulders with my hand and said, “O my father, I adjure you that you hand it over to ‘Ali.” So he handed it over to him."]}},"tuhfa":{},"refs":[{"key":"sh12520","label":"أبو يعلى","number":26},{"key":"ahmad","label":"مسند الإمام أحمد","number":77,"n":77,"lafz":true}],"full":1,"dr":1},{"num":6056,"demo":false,"sanad":"","matn":["عن هزيل بن شُرَحْبِيلَ قَالَ سُئِلَ أَبُو مُوسَى عَنِ ابْنَةٍ وَابْنَةِ ابْنٍ وَأُخْتٍ، فَقَالَ لِلاِبْنَةِ النِّصْفُ وَلِلأُخْتِ النِّصْفُ، وَأْتِ ابْنَ مَسْعُودٍ فَسَيُتَابِعُنِي. فَسُئِلَ ابْنُ مَسْعُودٍ وَأُخْبِرَ بِقَوْلِ أَبِي مُوسَى، فَقَالَ لَقَدْ ضَلَلْتُ إِذًا وَمَا أَنَا مِنَ الْمُهْتَدِينَ،، أَقْضِي فِيهَا بِمَا قَضَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلاِبْنَةِ النِّصْفُ، وَلاِبْنَةِ ابْنٍ السُّدُسُ تَكْمِلَةَ الثُّلُثَيْنِ، وَمَا بَقِيَ فَلِلأُخْتِ. فَأَتَيْنَا أَبَا مُوسَى فَأَخْبَرْنَاهُ بِقَوْلِ ابْنِ مَسْعُودٍ، فَقَالَ لاَ تَسْأَلُونِي مَا دَامَ هَذَا الْحَبْرُ فِيكُمْ."],"takhrij":"صحيح: رواه البخاري في الفرائض (6736) عن آدم، حدثنا شعبة، حدثنا أبو قيس، سمعت هزيل بن شرحبيل قال فذكره.","grade":"صحيح","chapter_ar":"باب ميراث الأخوات مع البنات عصبة","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6736).","chapter_en":"The inheritance of sisters together with daughters as residuary heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Huzayl ibn Shurahbil said: Abu Musa was asked about a daughter, a son’s daughter, and a sister. He said: “The daughter gets one-half, and the sister gets one-half. Go to Ibn Mas‘ud, and he will follow me.” Ibn Mas‘ud was then asked and was informed of Abu Musa’s answer. He said: “Then I would have gone astray and would not be among the rightly guided. I will judge in it as the Prophet ﷺ judged: the daughter gets one-half, the son’s daughter gets one-sixth completing two-thirds, and whatever remains goes to the sister.” So we went to Abu Musa and informed him of Ibn Mas‘ud’s statement, and he said: “Do not ask me while this learned man is among you.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6736,"lafz":true}],"full":1,"dr":1,"rep":[12239]},{"num":6057,"demo":false,"sanad":"","matn":["عَنِ الأَسْوَدِ، قَالَ قَضَى فِينَا مُعَاذُ بْنُ جَبَلٍ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ النِّصْفُ لِلاِبْنَةِ وَالنِّصْفُ لِلأُخْتِ."],"takhrij":"صحيح: رواه البخاري في الفرائض (6741) عن بشر بن خالد، حدثنا محمد بن جعفر، عن شعبة، عن سليمان، عن إبراهيم، عن الأسود فذكره.","grade":"صحيح","chapter_ar":"باب ميراث الأخوات مع البنات عصبة","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6741).","chapter_en":"The inheritance of sisters together with daughters as residuary heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Aswad ibn Yazid said: Mu‘adh ibn Jabal judged among us during the lifetime of the Messenger of Allah ﷺ that one-half was for the daughter and one-half was for the sister."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6741,"lafz":true}],"full":1,"dr":1},{"num":6058,"demo":false,"sanad":"","matn":["عَنِ الأَسْوَدِ بْنِ يَزِيدَ، قَالَ أَتَانَا مُعَاذُ بْنُ جَبَلٍ بِالْيَمَنِ مُعَلِّمًا وَأَمِيرًا، فَسَأَلْنَاهُ عَنْ رَجُلٍ، تُوُفِّيَ وَتَرَكَ ابْنَتَهُ وَأُخْتَهُ، فَأَعْطَى الاِبْنَةَ النِّصْفَ وَالأُخْتَ النِّصْفَ."],"takhrij":"صحيح: رواه البخاري في الفرائض (6734) عن محمود، حدثنا أبو النضر، حدثنا أبو معاوية شيبان، عن أشعث، عن الأسود فذكره.","grade":"صحيح","chapter_ar":"باب ميراث الأخوات مع البنات عصبة","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6734).","chapter_en":"The inheritance of sisters together with daughters as residuary heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Aswad ibn Yazid said: Mu‘adh ibn Jabal came to us in Yemen as a teacher and a governor. We asked him about a man who died and left behind a daughter and a sister, so he gave the daughter one-half and the sister one-half."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6734,"lafz":true}],"full":1,"dr":1,"rep":[12238]},{"num":6059,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ ـ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَجُلاً، لاَعَنَ امْرَأَتَهُ فِي زَمَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَانْتَفَى مِنْ وَلَدِهَا فَفَرَّقَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَهُمَا، وَأَلْحَقَ الْوَلَدَ بِالْمَرْأَةِ."],"takhrij":"متفق عليه: رواه مالك في الـطلاق (40) قال: حـدثني نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب ميراث ابن الملاعنة وولد الزنا","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (40), al-Bukhari (6749), and Muslim (1494).","chapter_en":"The inheritance of the child of mutual imprecation and the child of fornication","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ibn ‘Umar narrated that a man performed li‘ān with his wife during the time of the Prophet ﷺ and denied her child, so the Prophet ﷺ separated them and attributed the child to the woman."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":40,"lafz":true},{"key":"bukhari","label":"البخاري","number":6749,"n":6748},{"key":"muslim","label":"مسلم","number":1494}],"full":1,"dr":1},{"num":6060,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده، عن النبي صلى الله عليه وسلم  قال: ميراث ابن الملاعنة لأمه، ولورثتها من بعدها."],"takhrij":"حسن: رواه أبو داود (2908) عن موسى بن عامر، حدثنا الوليد، أخبرني عيسى أبو محمد، عن العلاء بن الحارث، عن عمرو بن شعيب فذكره.","grade":"حسن","chapter_ar":"باب ميراث ابن الملاعنة وولد الزنا","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2908).","chapter_en":"The inheritance of the child of mutual imprecation and the child of fornication","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["‘Abd Allah ibn ‘Amr ibn al-‘As narrated from the Prophet ﷺ that he said: “The inheritance of the child of li‘ān belongs to his mother and to her heirs after her.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2908,"lafz":true}],"full":1,"dr":1},{"num":6061,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كُلَّ مُسْتَلْحَقٍ اسْتُلْحِقَ بَعْدَ أَبِيهِ الَّذِي يُدْعَى لَهُ، ادَّعَاهُ وَرَثَتُهُ من بَعْدِهِ، فَقَضَى أَنَّ مَنْ كَانَ مِنْ أَمَةٍ يَمْلِكُهَا يَوْمَ أَصَابَهَا فَقَدْ لَحِقَ بِمَنِ اسْتَلْحَقَهُ، وَلَيْسَ لَهُ فِيمَا قُسِمَ قَبْلَهُ مِنَ الْمِيرَاثِ شيء، وَمَا أَدْرَكَ مِنْ مِيرَاثٍ لَمْ يُقْسَمْ فَلَهُ نَصِيبُهُ، وَلاَ يُلْحَقُ إِذَا كَانَ أَبُوهُ الَّذِي يُدْعَى لَهُ أَنْكَرَهُ. وَإِنْ كَانَ مِنْ أَمَةٍ لاَ يَمْلِكْهَا، أَوْ مِنْ حُرَّةٍ عَاهَرَ بِهَا فَإِنَّهُ لاَ يُلْحَقُ، وَلاَ يُورَثُ. وَإِنْ كَانَ الَّذِي يُدْعَى لَهُ هُوَ ادَّعَاهُ فَهُوَ وَلَدُ زنا، لأهل أمه مِنْ كَانُوا، حُرَّةٍ أَوْ أَمَةٍ.","قال محمد بن راشد: يعني بذلك ما قسم في الجاهلية قبل الإسلام."],"takhrij":"حسن: رواه أبو داود (2265)، وابن ماجه (2746)، وأحمد (7042)، والحاكم (4/342)، والبيهقي (6/260)، والدارمي (3154) كلهم من حديث محمد بن راشد، عن سليمان بن موسى، عن عمرو بن شعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب ميراث ابن الملاعنة وولد الزنا","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2265), Ibn Majah (2746), Ahmad (7042), al-Hakim (4/342), and al-Bayhaqi (6/260).","chapter_en":"The inheritance of the child of mutual imprecation and the child of fornication","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["‘Amr ibn Shu‘ayb narrated from his father, from his grandfather, that the Messenger of Allah ﷺ said: “Any claimed child who is claimed after the death of the man to whom he is attributed, and whose heirs claim him afterward: it is ruled that if he was born from a slave woman whom that man owned on the day he had relations with her, then he is joined to the one who claimed him. But he has no share in any inheritance that was already divided before that, while whatever inheritance he reaches before division, he receives his share of it. He is not joined to him if the father to whom he is attributed had denied him. And if he was from a slave woman he did not own, or from a free woman with whom he committed fornication, then he is not joined to him and does not inherit. And if the man to whom he is attributed himself claims him in such a case, then he is a child of fornication, belonging to the family of his mother, whether she was free or a slave.” Muhammad ibn Rashid said: This refers to what had been divided in the pre-Islamic period before Islam."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2265,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2746},{"key":"hakim","label":"الحاكم","number":342},{"key":"kubrabayhaqi","label":"البيهقي","number":260},{"key":"ahmad","label":"مسند الإمام أحمد","number":7042,"n":7042},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":12504,"n":12627},{"key":"darimi","label":"الدارمي","number":3154,"n":3022}],"full":1,"dr":1},{"num":6062,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ أَيُّمَا رَجُلٍ عَاهَرَ بِحُرَّةٍ أَوْ أَمَةٍ فَالْوَلَدُ وَلَدُ زِنَا لاَ يَرِثُ وَلاَ يُورَثُ."],"takhrij":"حسن: رواه الترمذي (2113) عن قتيبة، حدثنا ابن لهيعة، عن عمرو بن شعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب ميراث ابن الملاعنة وولد الزنا","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (2113) and Ibn Majah (2745).","chapter_en":"The inheritance of the child of mutual imprecation and the child of fornication","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["‘Amr ibn Shu‘ayb narrated from his father, from his grandfather, that the Messenger of Allah ﷺ said: “Any man who fornicates with a free woman or a slave woman, then the child is a child of fornication: he neither inherits nor is inherited from.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":2113,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2745}],"full":1,"dr":1},{"num":6063,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أن رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّمَا الْوَلاَءُ لِمَنْ أَعْتَقَ."],"takhrij":"متفق عليه: رواه البخاري في المكاتب (2561)، ومسلم في العتق (1504: 6) كلاهما عن قتيبة بن سعيد، حدثنا الليث، عن ابن شهاب، عن عروة أن عائشة أخبرته فذكرته في حديث طويل. انظر كتاب العتق.","grade":"متفق عليه","chapter_ar":"باب الميراث بالولاء","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2561) and Muslim (1504/6).","chapter_en":"Inheritance through wala’","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["‘A’ishah narrated that the Messenger of Allah ﷺ said: “Wala’ belongs only to the one who emancipates.”"]},"buhuth":{"en":["His statement, “Wala’ belongs only to the one who emancipates,” means that whoever frees his slave has the right to inherit from him if the freed person has no heir, and he is treated as his agnatic heir if the legal heirs do not encompass all of his estate."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2561,"lafz":true,"n":2269},{"key":"muslim","label":"مسلم","number":6,"n":3},{"key":"muslim","label":"مسلم في العتق","number":1504,"n":3779}],"full":1,"dr":1},{"num":6064,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَوْلَى الْقَوْمِ مِنْ أَنْفُسِهِمْ. أَوْ كَمَا قَالَ."],"takhrij":"متفق عليه: رواه البخاري في الفرائض (6761) عن آدم، حدثنا شعبة، حدثنا معاوية بن قرة، وقتادة، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب الميراث بالولاء","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6761). Muslim also narrated it through another route (1059/133) with the wording: The Messenger of Allah ﷺ gathered the Ansar and said, “Is there anyone among you who is not from you?” They said, “No, except a son of our sister.” So the Messenger of Allah ﷺ said, “The son of a people’s sister is one of them.” Then he mentioned the rest of the hadith concerning the virtues of the Ansar.","chapter_en":"Inheritance through wala’","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Anas narrated from the Prophet ﷺ that he said: “The freedman of a people is one of them,” or words to that effect."]},"buhuth":{"en":["And his statement, “the freedman of a people,” means their emancipated slave: he is affiliated with them and they inherit from him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6761,"lafz":true},{"key":"muslim","label":"مسلم","number":133}],"full":1,"dr":1},{"num":6065,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ تَزَوَّجَ رِئَابُ بْنُ حُذَيْفَةَ بْنِ سُعَيْدِ بْنِ سَهْمٍ أُمَّ وَائِلٍ بِنْتَ مَعْمَرٍ الْجُمَحِيَّةَ فَوَلَدَتْ لَهُ ثَلاَثَةً فَتُوُفِّيَتْ أُمُّهُمْ فَوَرِثَهَا بَنُوهَا رِبَاعًا وَوَلاَءَ مَوَالِيهَا فَخَرَجَ بِهِمْ عَمْرُو بْنُ الْعَاصِ مَعَهُ إِلَى الشَّامِ فَمَاتُوا فِي طَاعُونِ عَمْوَاسَ فَوَرِثَهُمْ عَمْرٌو وَكَانَ عَصَبَتَهُمْ فَلَمَّا رَجَعَ عَمْرُو بْنُ الْعَاصِ جَاءَ بَنُو مَعْمَرٍ يُخَاصِمُونَهُ فِي وَلاَءِ أُخْتِهِمْ إِلَى عُمَرَ فَقَالَ عُمَرُ أَقْضِي بَيْنَكُمْ بِمَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَمِعْتُهُ يَقُولُ مَا أَحْرَزَ الْوَلَدُ أَوِ الْوَالِدُ فَهُوَ لِعَصَبَتِهِ مَنْ كَانَ. قَالَ فَقَضَى لَنَا بِهِ وَكَتَبَ لَنَا بِهِ كِتَابًا فِيهِ شَهَادَةُ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ وَزَيْدِ بْنِ ثَابِتٍ وَآخَرَ حَتَّى إِذَا اسْتُخْلِفَ عَبْدُ الْمَلِكِ بْنُ مَرْوَانَ تُوُفِّيَ مَوْلًى لَهَا وَتَرَكَ أَلْفَىْ دِينَارٍ فَبَلَغَنِي أَنَّ ذَلِكَ الْقَضَاءَ قَدْ غُيِّرَ فَخَاصَمُوهُ إِلَى هِشَامِ بْنِ إِسْمَاعِيلَ فَرَفَعَنَا إِلَى عَبْدِ الْمَلِكِ فَأَتَيْنَاهُ بِكِتَابِ عُمَرَ فَقَالَ إِنْ كُنْتُ لأَرَى أَنَّ هَذَا مِنَ الْقَضَاءِ الَّذِي لاَ يُشَكُّ فِيهِ وَمَا كُنْتُ أَرَى أَنَّ أَمْرَ أَهْلِ الْمَدِينَةِ بَلَغَ هَذَا أَنْ يَشُكُّوا فِي هَذَا الْقَضَاءِ. فَقَضَى لَنَا بِهِ فَلَمْ نَزَلْ فِيهِ بَعْدُ."],"takhrij":"حسن: رواه أبو داود (2917)، وابن ماجه (2732) –واللفظ له- كلاهما من حديث حسين المعلم، حدثنا عمرو بن شعيب بإسناده.","grade":"حسن","chapter_ar":"باب الميراث بالولاء","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2917) and Ibn Majah (2732), with the wording being Ibn Majah’s.","chapter_en":"Inheritance through wala’","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["‘Amr ibn Shu‘ayb narrated from his father, from his grandfather, who said: Ri’ab ibn Hudhayfah ibn Sa‘id ibn Sahm married Umm Wa’il bint Ma‘mar al-Jumahiyyah, and she bore him three children. Then their mother died, so her sons inherited her homes and the wala’ of her freed slaves. ‘Amr ibn al-‘As took them with him to Syria, and they died in the plague of ‘Amwas, so ‘Amr inherited from them, as he was their agnatic relative. When ‘Amr ibn al-‘As returned, the sons of Ma‘mar came disputing with him before ‘Umar regarding the wala’ of their sister. ‘Amr said: “I will judge between you according to what I heard from the Messenger of Allah ﷺ. I heard him say: ‘Whatever is secured by the child and the parent belongs to his agnatic heirs, whoever they may be.’” He said: So he judged in our favor and wrote us a document to that effect, bearing the testimony of ‘Abd al-Rahman ibn ‘Awf, Zayd ibn Thabit, and another. Then when ‘Abd al-Malik ibn Marwan became caliph, one of her freed slaves died and left two thousand dinars, and I was informed that that judgment had been altered. So they brought the dispute to Hisham ibn Isma‘il, and we raised it to ‘Abd al-Malik. We brought him ‘Umar’s written document, and he said: “I had considered this to be among the rulings about which there is no doubt, and I never thought the matter of the people of Madinah had reached the point that they would doubt this ruling.” So he judged in our favor, and it remained so afterward."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2917,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2732}],"full":1,"dr":1},{"num":6066,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بْنِ الْخَطَّابِ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يَرِثُ الْوَلَاءَ مَنْ وَرِثَ الْمَالَ مِنْ وَالِدٍ، أَوْ وَلَدٍ."],"takhrij":"حسن: رواه أحمد (324) عن عبد الله بن يزيد، حدثنا ابن لهيعة، عن عمرو بن شعيب، عن أبيه، عن جده، عن عمر بن الخطاب فذكره.","grade":"حسن","chapter_ar":"باب الميراث بالولاء","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (324).","chapter_en":"Inheritance through wala’","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["‘Umar ibn al-Khattab said: I heard the Messenger of Allah ﷺ say: “The wala’ is inherited by whoever inherits the wealth through a parent or a child.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":324,"n":324,"lafz":true}],"full":1,"dr":1},{"num":6067,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ: نَهَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعِ الْوَلاَءِ، وَعَنْ هِبَتِهِ."],"takhrij":"متفق عليه: رواه مالك في العتق (20) عن عبد الله بن دينار، عن ابن عمر فذكره. ورواه البخاري في العتق (2535)، وفي الفرائض (6756)، ومسلم في العتق (1506) كلاهما من أوجه أخرى عن عبد الله بن دينار.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الولاء وهبته","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (20), al-Bukhari (2535, 6756), and Muslim (1506).","chapter_en":"The prohibition of selling wala’ or giving it away","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar narrated: The Messenger of Allah ﷺ forbade selling wala’ and forbade giving it away as a gift."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":20,"lafz":true},{"key":"bukhari","label":"البخاري","number":2535},{"key":"muslim","label":"مسلم","number":1506}],"full":1,"dr":1},{"num":6068,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْوَلَاءُ لُحْمَةٌ كَلُحْمَةِ النَّسَبِ، لَا يُبَاعُ، وَلَا يُوهَبُ."],"takhrij":"صحيح: رواه ابن حبان (4950) عن أبي يعلى قال: قرئ على بشر بن الوليد، عن يعقوب بن إبراهيم، عن عبيدالله بن عمر، عن عبد الله بن دينار، عن ابن عمر فذكر الحديث.","grade":"صحيح","chapter_ar":"باب النهي عن بيع الولاء وهبته","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Hibban (4950).","chapter_en":"The prohibition of selling wala’ or giving it away","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ said, “Wala’ is a bond like the bond of lineage: it is neither sold nor given away.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1896,"n":1893},{"key":"ibnhibban","label":"ابن حبان","number":4950,"lafz":true}],"full":1,"dr":1,"rep":[6153]},{"num":6069,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ مَوْلًى، لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَعَ مِنْ نَخْلَةٍ فَمَاتَ وَتَرَكَ مَالاً وَلَمْ يَتْرُكْ وَلَدًا وَلاَ حَمِيمًا فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَعْطُوا مِيرَاثَهُ رَجُلاً مِنْ أَهْلِ قَرْيَتِهِ."],"takhrij":"حسن: رواه أبو داود (2902)، والترمذي (2105)، وابن ماجه (2733) كلهم من حديث عبد الرحمن بن الأصبهاني، عن مجاهد بن وردان، عن عروة بن الزبير، عن عائشة قالت: فذكرته.","grade":"حسن","chapter_ar":"باب من مات، وليس له وارث، ولا ذو رحم","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2902), al-Tirmidhi (2105), who graded it Hasan, and Ibn Majah (2733).","chapter_en":"One who dies leaving neither an heir nor a relative","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["‘A’ishah narrated that a freedman of the Prophet ﷺ fell from a palm tree and died, leaving wealth behind, but leaving neither a child nor a close relative. So the Prophet ﷺ said: “Give his inheritance to a man from the people of his village.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2902,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":2105},{"key":"ibnmajah","label":"ابن ماجه","number":2733}],"full":1,"dr":1},{"num":6070,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاس ٍ رَضِيَ اللَّهُ عَنْهُمَا {وَلِكُلٍّ جَعَلْنَا مَوَالِيَ} قَالَ وَرَثَةً. {وَالَّذِينَ عَاقَدَتْ أَيْمَانُكُمْ} كَانَ الْمُهَاجِرُونَ لَمَّا قَدِمُوا الْمَدِينَةَ يَرِثُ الْمُهَاجِرُ الأَنْصَارِيَّ دُونَ ذَوِي رَحِمِهِ لِلأُخُوَّةِ الَّتِي آخَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَهُمْ فَلَمَّا نَزَلَتْ {وَلِكُلٍّ جَعَلْنَا مَوَالِيَ} نُسِخَتْ، ثُمَّ قَالَ {وَالَّذِينَ عَاقَدَتْ أَيْمَانُكُمْ } مِنَ النَّصْرِ، وَالرِّفَادَةِ وَالنَّصِيحَةِ، وَقَدْ ذَهَبَ الْمِيرَاثُ وَيُوصِي لَهُ."],"takhrij":"صحيح: رواه البخاري في التفسير (4580) عن الصلت بن محمد، حدثنا أبو أسامة، عن إدريس، عن طلحة بن مصرف، عن سعيد بن جبير، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب نسخ ميراث العقد والحلف بميراث الرحم","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4580).","chapter_en":"The abrogation of inheritance by pact and oath, replaced by inheritance through kinship","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Ibn ‘Abbas said regarding the verse: “And for all We have appointed heirs” — meaning: inheritors. And regarding “and those with whom your right hands have made a pact”: when the Emigrants first came to Madinah, the Emigrant used to inherit from the Helper instead of his blood relatives, because of the brotherhood which the Prophet ﷺ established between them. But when the verse “And for all We have appointed heirs” was revealed, that was abrogated. Then he said that “and those with whom your right hands have made a pact” remained in terms of support, assistance, and sincere counsel, while inheritance had ended, though a bequest may still be made to him."]},"buhuth":{"en":["Meaning of the verse “and those with whom your right hands have made a pact”: those with whom you entered into binding alliances by solemn oaths. So give them their due in support, hospitality, and sincere loyalty, as you promised them. This existed at the beginning of Islam, then inheritance through that pact was later abrogated."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4580,"lafz":true}],"full":1,"dr":1},{"num":6071,"demo":false,"sanad":"","matn":["عن ابن عباس قال: ﴿وَالَّذِينَ عَقَدَتْ أَيْمَانُكُمْ فَآتُوهُمْ نَصِيبَهُمْ﴾ [النساء:: ٣٣] كان الرجل يحالف الرجل ليس بينهما نسب، فيرث أحدهما الآخر، فنسخ ذلك الأنفال. قال تعالى: ﴿وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ﴾ [الأنفال: ٧٥]."],"takhrij":"حسن: رواه أبو داود (2921) عن أحمد بن محمد بن ثابت، حدثني علي بن حسين، عن أبيه، عن يزيد النحوي، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب نسخ ميراث العقد والحلف بميراث الرحم","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2921).","chapter_en":"The abrogation of inheritance by pact and oath, replaced by inheritance through kinship","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Ibn ‘Abbas said regarding the verse: “And those with whom your right hands have made a pact, give them their share” [Surat al-Nisa’: 33]: a man used to enter an alliance with another man with no blood relationship between them, and one of them would inherit from the other. This was then abrogated by the verse in Surat al-Anfal: “And blood relatives are nearer to one another” [Surat al-Anfal: 75]."]},"buhuth":{"en":["So what was abrogated was inheritance through alliance. As for forming pacts for obedience to Allah, helping the oppressed, and brotherhood for Allah’s sake, that remains encouraged, and many hadiths command it."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2921,"lafz":true}],"full":1,"dr":1},{"num":6072,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ ابْنُ أُخْتِ الْقَوْمِ مِنْهُمْ. أَوْ مِنْ أَنْفُسِهِمْ."],"takhrij":"متفق عليه: رواه البخاري في الفرائض (6762) عن أبي الوليد، حدثنا شعبة، عن قتادة، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب نسخ ميراث العقد والحلف بميراث الرحم","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6762). Muslim (1059) also narrated through another chain that the Messenger of Allah ﷺ gathered the Ansar and said: “Is there anyone among you who is not from you?” They said: “No, except the son of our sister.” So the Messenger of Allah ﷺ said: “The son of a people’s sister is one of them.” Then he mentioned the virtues of the Ansar, and that appears in its proper place.","chapter_en":"The abrogation of inheritance by pact and oath, replaced by inheritance through kinship","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Anas ibn Malik narrated from the Prophet ﷺ that he said: “The son of a people’s sister is one of them,” or “from their own selves.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6762,"lafz":true},{"key":"muslim","label":"مسلم","number":1059}],"full":1,"dr":1},{"num":6073,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ابْنُ أُخْتِ الْقَوْمِ مِنْهُمْ."],"takhrij":"حسن: رواه أبو داود (5122) عن أبي بكر بن أبى شيبة، حدثنا أبو أسامة، عن عوف، عن زياد بن مخراق، عن أبى كنانة، عن أبي موسى فذكره.","grade":"حسن","chapter_ar":"باب نسخ ميراث العقد والحلف بميراث الرحم","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (5122) and Ahmad (19541).","chapter_en":"The abrogation of inheritance by pact and oath, replaced by inheritance through kinship","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Abu Musa al-Ash‘ari said: The Messenger of Allah ﷺ said, “The son of a people’s sister is one of them.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":5122,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":19541,"n":19541}],"full":1,"dr":1},{"num":6074,"demo":false,"sanad":"","matn":["عن جبير بن مطعم قال: قال النبي صلى الله عليه وسلم : ابن الأخت منهم."],"takhrij":"حسن: رواه الطبراني (2/142) عن محمد بن مندة الأصبهاني، ثنا أبو كريب، ثنا زكريا بن عدي، عن حاتم بن إسماعيل، عن الجُعيد بن عبدالرحمن، عن يزيد بن خصيفة، عن نافع بن جبير، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب نسخ ميراث العقد والحلف بميراث الرحم","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani (2/142).","chapter_en":"The abrogation of inheritance by pact and oath, replaced by inheritance through kinship","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Jubayr ibn Mut‘im said: The Prophet ﷺ said, “The sister’s son is one of them.”"]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني","number":2,"lafz":true}],"full":1,"dr":1},{"num":6075,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ، قَالَ كَتَبَ عُمَرُ بْنُ الْخَطَّابِ إِلَى أَبِي عُبَيْدَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ اللَّهُ وَرَسُولُهُ مَوْلَى مَنْ لاَ مَوْلَى لَهُ وَالْخَالُ وَارِثُ مَنْ لاَ وَارِثَ لَهُ."],"takhrij":"حسن: رواه الترمذي (2103)، وابن ماجه (2737) كلاهما من حديث سفيان الثوري، عن عبد الرحمن بن الحارث بن عياش بن أبي ربيعة، عن حكيم بن حكيم بن عباد بن حتيف، عن أبي أمامة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في ميراث الخال","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (2103), Ibn Majah (2737), and Ahmad (189). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"What has been reported regarding the inheritance of the maternal uncle","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Abu Umamah ibn Sahl ibn Hunayf said: ‘Umar ibn al-Khattab wrote to Abu ‘Ubaydah that the Messenger of Allah ﷺ said, “Allah and His Messenger are the guardians of the one who has no guardian, and the maternal uncle is the heir of the one who has no heir.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":2103,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2737},{"key":"ahmad","label":"مسند الإمام أحمد","number":189,"n":189}],"full":1,"dr":1},{"num":6076,"demo":false,"sanad":"","matn":["عَنِ الْمِقْدَامِ الْكِنْدِيِّ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَا أَوْلَى بِكُلِّ مُؤْمِنٍ مِنْ نَفْسِهِ فَمَنْ تَرَكَ دَيْنًا أَوْ ضَيْعَةً فَإِلَىَّ وَمَنْ تَرَكَ مَالاً فَلِوَرَثَتِهِ وَأَنَا مَوْلَى مَنْ لاَ مَوْلَى لَهُ أَرِثُ مَالَهُ وَأَفُكُّ عَانَهُ وَالْخَالُ مَوْلَى مَنْ لاَ مَوْلَى لَهُ يَرِثُ مَالَهُ وَيَفُكُّ عَانَهُ."],"takhrij":"حسن: رواه أبو داود (2900)، وابن ماجه (2634) كلاهما من حديث حماد بن زيد، عن بديل بن ميسرة، عن على بن أبى طلحة، عن راشد بن سعد، عن أبي عامر الهوزني، عن المقدام الشامي فذكره. واللفظ لأبي داود، واختصره ابن ماجه.","grade":"حسن","chapter_ar":"باب ما جاء في ميراث الخال","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2900) and Ibn Majah (2634). The wording is Abu Dawud’s.","chapter_en":"What has been reported regarding the inheritance of the maternal uncle","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Al-Miqdam al-Kindi said: The Messenger of Allah ﷺ said, “I am closer to every believer than his own self. Whoever leaves behind debt or needy dependents, then it is for me to take care of. Whoever leaves behind wealth, it belongs to his heirs. And I am the guardian of the one who has no guardian: I inherit his wealth and free his captive. And the maternal uncle is the guardian of the one who has no guardian: he inherits his wealth and frees his captive.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2900,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2634}],"full":1,"dr":1},{"num":6077,"demo":false,"sanad":"","matn":["عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ يَرِثُ الْمُسْلِمُ الْكَافِرَ، وَلاَ الْكَافِرُ الْمُسْلِمَ."],"takhrij":"متفق عليه: رواه البخاري في الفرائض (6764) من طريق ابن جريج، ومسلم في الفرائض (1614) من حديث ابن عيينة، كلاهما عن ابن شهاب، عن علي بن حسين، عن عمرو بن عثمان، عن أسامة بن زيد فذكره.","grade":"متفق عليه","chapter_ar":"باب لا يرث المسلم الكافر، ولا الكافر المسلم","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6764) and Muslim (1614).","chapter_en":"A Muslim does not inherit from a disbeliever, nor does a disbeliever inherit from a Muslim","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Usamah ibn Zayd narrated that the Prophet ﷺ said: “A Muslim does not inherit from a disbeliever, nor does a disbeliever inherit from a Muslim.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6764,"lafz":true},{"key":"muslim","label":"مسلم","number":1614}],"full":1,"dr":1},{"num":6078,"demo":false,"sanad":"","matn":["عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ قَالَ يَا رَسُولَ اللَّهِ، أَيْنَ تَنْزِلُ فِي دَارِكَ بِمَكَّةَ. فَقَالَ وَهَلْ تَرَكَ عَقِيلٌ مِنْ رِبَاعٍ أَوْ دُورٍ. وَكَانَ عَقِيلٌ وَرِثَ أَبَا طَالِبٍ هُوَ وَطَالِبٌ وَلَمْ يَرِثْهُ جَعْفَرٌ وَلاَ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُمَا شَيْئًا لأَنَّهُمَا كَانَا مُسْلِمَيْنِ، وَكَانَ عَقِيلٌ وَطَالِبٌ كَافِرَيْنِ، فَكَانَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ يَقُولُ لاَ يَرِثُ الْمُؤْمِنُ الْكَافِرَ.","قَالَ ابْنُ شِهَابٍ: وَكَانُوا يتأولون قول اللَّهِ تَعَالَى: ﴿إِنَّ الَّذِينَ آمَنُوا وَهَاجَرُوا وَجَاهَدُوا بِأَمْوَالِهِمْ وَأَنْفُسِهِمْ فِي سَبِيلِ اللَّهِ وَالَّذِينَ آوَوْا وَنَصَرُوا أُولَئِكَ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ﴾ [سورة الأَنْفَالِ: ٧٢]."],"takhrij":"متفق عليه: رواه البخاري في الحج (1588)، ومسلم في الحج (1351) كلاهما من حديث ابن وهب، عن يونس، عن ابن شهاب، عن علي بن حسين، عن عمرو بن عثمان، عن أسامة بن زيد فذكره.","grade":"متفق عليه","chapter_ar":"باب لا يرث المسلم الكافر، ولا الكافر المسلم","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1588) and Muslim (1351).","chapter_en":"A Muslim does not inherit from a disbeliever, nor does a disbeliever inherit from a Muslim","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Usamah ibn Zayd said: I said, “O Messenger of Allah ﷺ, where will you stay in your house in Makkah?” He said, “Has ‘Aqil left us any houses or dwellings?” ‘Aqil and Talib had inherited from Abu Talib, while Ja‘far and ‘Ali inherited nothing from him because they were Muslims, whereas ‘Aqil and Talib were disbelievers. So ‘Umar ibn al-Khattab used to say: “A believer does not inherit from a disbeliever.” Ibn Shihab said: They used to understand this in light of the saying of Allah the Exalted: ‘Indeed, those who believed and emigrated and strove with their wealth and their lives in the path of Allah, and those who gave shelter and support—those are allies of one another’ [Surat al-Anfal: 72]."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1588,"lafz":true},{"key":"muslim","label":"مسلم","number":1351}],"full":1,"dr":1},{"num":6079,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ عَبْدِ اللَّهِ بْنِ عَمْرٍو، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ يَتَوَارَثُ أَهْلُ مِلَّتَيْنِ شَتَّى."],"takhrij":"حسن: رواه أبو داود (2911) عن موسى بن إسماعيل، حدثنا حماد، عن حبيب المعلم، عن عمرو بن شعيب بإسناده.","grade":"حسن","chapter_ar":"باب ما جاء أن أهل ملتين لا يتوارثان","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2911), Ahmad (6664), and al-Bayhaqi (6/218).","chapter_en":"What has been reported that the followers of two different religions do not inherit from one another","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["‘Abd Allah ibn ‘Amr said: The Messenger of Allah ﷺ said, “The followers of two different religions do not inherit from one another.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2911,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":218},{"key":"ahmad","label":"مسند الإمام أحمد","number":6664,"n":6664}],"full":1,"dr":1},{"num":6080,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّهَا قَالَتْ: وَجَدْتُ فِي قَائِمِ سَيْفِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كِتَابًا: إِنَّ أَشَدَّ النَّاسِ عُتُوًّا مَنْ ضَرَبَ غَيْرَ ضَارِبِهِ، وَرَجُلٌ قَتَلَ غَيْرَ قَاتِلِهِ، وَرَجُلٌ تَوَلَّى غَيْرَ أَهْلِ نِعْمَتِهِ، فَمَنْ فَعَلَ ذَلِكَ فَقَدْ كَفَرَ بِاللَّهِ وَرَسُولِهِ لَا يَقْبَلُ اللَّهُ مِنْهُ صَرْفًا وَلَا عَدْلًا، وَفِي الْأَجْرِ الْمُؤْمِنُونَ تَكَافَأُ دِمَاؤُهُمْ وَيَسْعَى بِذِمَّتِهِمْ أَدْنَاهُمْ. لَا يُقْتَلُ مُسْلِمٌ بِكَافِرٍ وَلَا ذُو عَهْدٍ فِي عَهْدِهِ، وَلَا يَتَوَارَثُ أَهْلُ مِلَّتَيْنِ، وَلَا تُنْكَحُ الْمَرْأَةُ عَلَى عَمَّتِهَا وَلَا عَلَى خَالَتِهَا، وَلَا صَلَاةَ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ، وَلَا تُسَافِرُ امْرَأَةٌ ثَلَاثَ لَيَالٍ مَعَ غَيْرِ ذِي مَحْرَمٍ."],"takhrij":"حسن: رواه أبو يعلى (4757) عن أبي خيثمة، حدثنا عبيدالله بن عبدالمجيد، حدثنا عبيدالله بن عبدالرحمن بن موهب، قال: سمعت مالك بن محمد بن عبدالرحمن، قال: سمعت عمرة بنت عبدالرحمن، تحدث عن عائشة، فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء أن أهل ملتين لا يتوارثان","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Ya‘la (4757), al-Daraqutni (3/131), and al-Bayhaqi (8/29–30).","chapter_en":"What has been reported that the followers of two different religions do not inherit from one another","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["‘A’ishah said: I found a written statement in the hilt of the sword of the Messenger of Allah ﷺ: “The most rebellious of people are: a man who strikes someone other than the one who struck him, a man who kills someone other than his killer, and a man who affiliates himself with people other than those to whom he owes his bond of loyalty. Whoever does that has disbelieved in Allah and His Messenger. Allah will accept from him neither obligatory nor voluntary deeds. As for retaliation, the blood of the believers is equal, and the least of them may extend protection on behalf of them. A Muslim is not to be killed for a disbeliever, nor a person under covenant while his covenant remains in force. The followers of two different religions do not inherit from one another. A woman may not be married together with her paternal aunt or her maternal aunt. There is no prayer after the afternoon prayer until the sun sets. And a woman must not travel for three nights except with a male guardian.”"]}},"tuhfa":{},"refs":[{"key":"sh12520","label":"أبو يعلى","number":4757,"lafz":true},{"key":"sh9771","label":"الدارقطني","number":131},{"key":"kubrabayhaqi","label":"البيهقي","number":8}],"full":1,"dr":1,"rep":[6451,6857]},{"num":6081,"demo":false,"sanad":"","matn":["عن عمر قال: قال رسول الله صلى الله عليه وسلم : ليس للقاتل شيء."],"takhrij":"حسن: رواه مالك (2/867) عن يحيى بن سعيد، عن عمرو بن شعيب أن رجلا من بني مُدْلج، يقال له: قتادة، حذف ابنه بسيف، فأصاب ساقه، فنـزي في جرحه، فمات، فقدم سراقة بن جعشم على عمر بن الخطاب، فذكر ذلك له، فقال عمر بن الخطاب: اعْدُد لي على ماء قديد عشرين ومائة بعير حتى أقدم عليك، فلما قدم عليه عمر أخذ من تلك الإبل ثلاثين حقة، وثلاثين جذعة، وأربعين خلفة، ثم قال: أين أخو المقتول؟ فقال: ها أنا ذا. فقال: خذها؛ فإن رسول الله صلى الله عليه وسلم  قال فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء أن القاتل لا يرث","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Malik (2/867).","chapter_en":"What has been reported that the killer does not inherit","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["‘Umar said: The Messenger of Allah ﷺ said, “The killer gets nothing.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":2,"lafz":true}],"full":1,"dr":1},{"num":6082,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ كَانَ الْمَالُ لِلْوَلَدِ، وَكَانَتِ الْوَصِيَّةُ لِلْوَالِدَيْنِ، فَنَسَخَ اللَّهُ مِنْ ذَلِكَ مَا أَحَبَّ، فَجَعَلَ لِلذَّكَرِ مِثْلَ حَظِّ الأُنْثَيَيْنِ، وَجَعَلَ لِلأَبَوَيْنِ لِكُلِّ وَاحِدٍ مِنْهُمَا السُّدُسُ، وَجَعَلَ لِلْمَرْأَةِ الثُّمُنَ وَالرُّبُعَ، وَلِلزَّوْجِ الشَّطْرَ وَالرُّبُعَ."],"takhrij":"صحيح: أخرجه البخاري في الفرائض (6739) عن محمد بن يوسف، عن ورقاء، عن ابن أبي نجيح، عن عطاء، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ميراث الأب والأم","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6739).","chapter_en":"The inheritance of the father and the mother","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["Ibn ‘Abbas said: Wealth used to go to the children, and the bequest was for the parents. Then Allah abrogated from that whatever He willed. So He made for the male the share of two females, made for each of the parents one-sixth, made for the wife one-eighth or one-fourth, and for the husband one-half or one-fourth."]},"intro":{"ar":["قال اللّٰه تعالى:","﴿ وَلِأَبَوَيْهِ لِكُلِّ وَاحِدٍ مِنْهُمَا السُّدُسُ مِمَّا تَرَكَ إِنْ كَانَ لَهُ وَلَدٌ ۚ فَإِنْ لَمْ يَكُنْ لَهُ وَلَدٌ وَوَرِثَهُ أَبَوَاهُ فَلِأُمِّهِ الثُّلُثُ ۚ فَإِنْ كَانَ لَهُ إِخْوَةٌ فَلِأُمِّهِ السُّدُسُ ۚ مِنْ بَعْدِ وَصِيَّةٍ يُوصِي بِهَا أَوْ دَيْنٍ ۗ آبَاؤُكُمْ وَأَبْنَاؤُكُمْ لَا تَدْرُونَ أَيُّهُمْ أَقْرَبُ لَكُمْ نَفْعًا ۚ فَرِيضَةً مِنَ اللَّهِ ۗ إِنَّ اللَّهَ كَانَ عَلِيمًا حَكِيمًا ﴾ [سورة النساء: ١١]"],"en":["Allah the Exalted said:","“And for his parents, to each one of them is a sixth of what he leaves if he had a child. But if he had no child and his parents alone inherit from him, then for his mother is one-third. But if he had brothers or sisters, then for his mother is one-sixth, after any bequest he may have made or debt. Your fathers and your sons—you do not know which of them are nearest to you in benefit. This is an obligation from Allah. Indeed, Allah is Ever-Knowing, All-Wise.” [Surat al-Nisa’: 11]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6739,"lafz":true}],"full":1},{"num":6083,"demo":false,"sanad":"","matn":["عَنْ تَمِيمٍ الدَّارِيِّ، قَالَ: سُئِلَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  عَنِ الرَّجُلِ يُسْلِمُ عَلَى يَدَيِ الرَّجُلِ، فَقَالَ: هُوَ أَوْلَى النَّاسِ بِمَحْيَاهُ وَمَمَاتِهِ."],"takhrij":"صحيح: رواه الطحاوي في مشكله (2852)، والدارمي (3076)، والبيهقي (10/296) كلهم من حديث أبي نعيم، حدثنا عبد العزيز بن عمر بن عبدالعزيز، عن عبدالله بن موهب قال: سمعت تميـما الداري فذكره.","grade":"صحيح","chapter_ar":"باب ميراث الذي يسلم على يدي الرجل","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tahawi in Mushkil al-Athar (2852), al-Darimi (3076), and al-Bayhaqi (10/296).","chapter_en":"The inheritance of the one who accepts Islam at the hands of a man","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Tamim al-Dari said: I asked the Messenger of Allah ﷺ about a man who accepts Islam at the hands of another man. He said, “He is the most entitled of people to him in his life and in his death.”"]}},"tuhfa":{},"refs":[{"key":"sh22547","label":"الطحاوي في مشكل الآثار","number":2852},{"key":"darimi","label":"الدارمي","number":3076,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":10}],"full":1,"dr":1},{"num":6084,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ جَاءَتِ امْرَأَةُ سَعْدِ بْنِ الرَّبِيعِ بِابْنَتَىْ سَعْدٍ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ يَا رَسُولَ اللَّهِ هَاتَانِ ابْنَتَا سَعْدٍ قُتِلَ مَعَكَ يَوْمَ أُحُدٍ وَإِنَّ عَمَّهُمَا أَخَذَ جَمِيعَ مَا تَرَكَ أَبُوهُمَا وَإِنَّ الْمَرْأَةَ لاَ تُنْكَحُ إِلاَّ عَلَى مَالِهَا. فَسَكَتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى أُنْزِلَتْ آيَةُ الْمِيرَاثِ فَدَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَا سَعْدِ بْنِ الرَّبِيعِ فَقَالَ أَعْطِ ابْنَتَىْ سَعْدٍ ثُلُثَىْ مَالِهِ وَأَعْطِ امْرَأَتَهُ الثُّمُنَ وَخُذْ أَنْتَ مَا بَقِيَ."],"takhrij":"حسن: رواه ابن ماجه (2720) من حديث سفيان بن عيينة، عن عبدالله بن محمد بن عقيل، عن جابر بن عبد الله فذكره.","grade":"حسن","chapter_ar":"باب فرض الابنتين فصاعدا","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2720), al-Tirmidhi (2092) who authenticated it, Ahmad (14798), and al-Hakim (4/333).","chapter_en":"The fixed share of two daughters and more","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":20,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The wife of Sa‘d ibn al-Rabi‘ came to the Prophet ﷺ with Sa‘d’s two daughters and said, “O Messenger of Allah ﷺ, these are the two daughters of Sa‘d. He was killed with you on the Day of Uhud, and their uncle has taken all that their father left, while a woman is only married for her wealth.” So the Messenger of Allah ﷺ remained silent until the verse of inheritance was revealed. Then the Messenger of Allah ﷺ called the brother of Sa‘d ibn al-Rabi‘ and said, “Give the two daughters of Sa‘d two-thirds of his wealth, give his wife one-eighth, and take what remains yourself.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2720,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":2092},{"key":"hakim","label":"الحاكم","number":4},{"key":"ahmad","label":"مسند الإمام أحمد","number":14798,"n":14798}],"full":1,"dr":1},{"num":6085,"demo":false,"sanad":"","matn":["عَنْ قَبِيصَةَ بْنِ ذُؤَيْبٍ، أَنَّهُ قَالَ جَاءَتِ الْجَدَّةُ إِلَى أَبِي بَكْرٍ الصِّدِّيقِ تَسْأَلُهُ مِيرَاثَهَا فَقَالَ مَا لَكِ فِي كِتَابِ اللَّهِ تَعَالَى شَىْءٌ وَمَا عَلِمْتُ لَكِ فِي سُنَّةِ نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَيْئًا فَارْجِعِي حَتَّى أَسْأَلَ النَّاسَ. فَسَأَلَ النَّاسَ فَقَالَ الْمُغِيرَةُ بْنُ شُعْبَةَ حَضَرْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَعْطَاهَا السُّدُسَ. فَقَالَ أَبُو بَكْرٍ هَلْ مَعَكَ غَيْرُكَ فَقَامَ مُحَمَّدُ بْنُ مَسْلَمَةَ فَقَالَ مِثْلَ مَا قَالَ الْمُغِيرَةُ بْنُ شُعْبَةَ فَأَنْفَذَهُ لَهَا أَبُو بَكْرٍ ثُمَّ جَاءَتِ الْجَدَّةُ الأُخْرَى إِلَى عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ تَسْأَلُهُ مِيرَاثَهَا فَقَالَ مَا لَكِ فِي كِتَابِ اللَّهِ تَعَالَى شَىْءٌ وَمَا كَانَ الْقَضَاءُ الَّذِي قُضِيَ بِهِ إِلاَّ لِغَيْرِكِ وَمَا أَنَا بِزَائِدٍ فِي الْفَرَائِضِ وَلَكِنْ هُوَ ذَلِكَ السُّدُسُ فَإِنِ اجْتَمَعْتُمَا فِيهِ فَهُوَ بَيْنَكُمَا وَأَيَّتُكُمَا خَلَتْ بِهِ فَهُوَ لَهَا."],"takhrij":"حسن: رواه مالك في الفرائض (4) عن ابن شهاب، عن عثمان بن إسحاق بن خرشة، عن قبيصة بن ذؤيب فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الجدة والجد","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Malik (4), Abu Dawud (2894), al-Tirmidhi (2101), and Ibn Majah (2724).","chapter_en":"What has been reported regarding the grandmother and the grandfather","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Qabisah ibn Dhu’ayb said: A grandmother came to Abu Bakr al-Siddiq asking for her inheritance. He said, “I do not find anything for you in the Book of Allah, and I do not know anything for you in the Sunnah of the Prophet ﷺ, so go back until I ask the people.” He asked the people, and al-Mughirah ibn Shu‘bah said, “I was present when the Messenger of Allah ﷺ gave her one-sixth.” Abu Bakr said, “Do you have anyone besides yourself?” Then Muhammad ibn Maslamah stood up and said the same as al-Mughirah ibn Shu‘bah, so Abu Bakr awarded it to her. Then the other grandmother came to ‘Umar ibn al-Khattab asking him for her inheritance. He said, “You have nothing specifically in the Book of Allah, and the judgment that was given was only for someone other than you. I am not going to add anything to the fixed shares. Rather, it is that same one-sixth. If both of you are present, then it is between you; and whichever of you is alone in receiving it, then it is hers.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":4,"lafz":true},{"key":"abudawud","label":"أبو داود","number":2894},{"key":"tirmidhi","label":"الترمذي","number":2101},{"key":"ibnmajah","label":"ابن ماجه","number":2724}],"full":1,"dr":1},{"num":6086,"demo":false,"sanad":"","matn":["عَنِ ابْنِ بُرَيْدَةَ، عَنْ أَبِيهِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَعَلَ لِلْجَدَّةِ السُّدُسَ إِذَا لَمْ تَكُنْ دُونَهَا أُمٌّ."],"takhrij":"حسن: رواه أبو داود (2895)، والنسائي في الكبرى (6338) كلاهما من حديث عبيدالله بن عبدالله أبي المنيب العتكي، عن ابن بريدة، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الجدة والجد","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2895) and al-Nasa’i in al-Kubra (6338).","chapter_en":"What has been reported regarding the grandmother and the grandfather","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Buraydah ibn al-Husayb narrated that the Prophet ﷺ gave the grandmother one-sixth if there was no mother between her and the deceased."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2895,"lafz":true},{"key":"kubranasai","label":"النسائي في الكبرى","number":6338}],"full":1,"dr":1},{"num":6087,"demo":false,"sanad":"","matn":["عَنْ مَعْقِلِ بْنِ يَسَارٍ الْمُزَنِيِّ، قَالَ سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِفَرِيضَةٍ فِيهَا جَدٌّ فَأَعْطَاهُ ثُلُثًا أَوْ سُدُسًا."],"takhrij":"حسن: رواه ابن ماجه (2722) عن أبي بكر بن أبي شيبة قال: حدثنا شبابة قال: حدثنا يونس بن أبي إسحاق، عن أبي إسحاق، عن عمرو بن ميمون، عن معقل بن يسار المزني قال:فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الجدة والجد","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2722) and Ibn Abi Shaybah (11/291).","chapter_en":"What has been reported regarding the grandmother and the grandfather","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Ma‘qil ibn Yasar al-Muzani said: I heard that a case of inheritance involving a grandfather was brought to the Prophet ﷺ, and he gave him either one-third or one-sixth."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2722,"lafz":true},{"key":"sh9944","label":"ابن أبي شيبة","number":11},{"key":"sh9944","label":"المصنف لابن أبي شيبة","number":31214,"n":31196}],"full":1,"dr":1},{"num":6088,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِذَا اسْتَهَلَّ الْمَوْلُودُ وُرِّثَ."],"takhrij":"حسن: رواه أبو داود (2920) ومن طريقه البيهقي (6/257) عن حسين بن معاذ، حدثنا عبدالأعلى، حدثنا محمد -يعنى ابن إسحاق-، عن يزيد بن عبد الله بن قسيط، عن أبى هريرة فذكره.","grade":"حسن","chapter_ar":"باب توريث المولود إذا استهل","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2920) and al-Bayhaqi (6/257).","chapter_en":"Inheriting for the newborn if he cries out at birth","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “If the newborn gives a cry at birth, he is to inherit.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2920,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":6,"n":202},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":12485,"n":12608}],"full":1,"dr":1},{"num":6089,"demo":false,"sanad":"","matn":["عَنِ الْمِسْوَرِ بْنِ مَخْرَمَةَ، وَجَابِرٍ قَالَا: قَالَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يَرِثُ الصَّبِيُّ حَتَّى يَسْتَهِلَّ صَارِخًا وَاسْتِهْلَالُهُ أَنْ يَصِيحَ أَوْ يَعْطِسَ أَوْ يَبْكِيَ. رَوَاهُ."],"takhrij":"حسن: رواه الطبراني في الكبير (2/20-21)، والأوسط (4596) –كما في \"مجمع البحرين\" (4/134)- عن عبدان بن أحمد، ثنا العباس بن الوليد الخلال الدمشقي، ثنا مروان بن محمد الطاطري، ثنا سليمان بن بلال، عن يحيى بن سعيد، عن سعيد بن المسيب، عن المسور بن مخرمة وجابر بن عبدالله فذكراه.","grade":"حسن","chapter_ar":"باب توريث المولود إذا استهل","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (2/20–21) and al-Awsat (4596), as cited in Majma‘ al-Bahrayn (4/134).","chapter_en":"Inheriting for the newborn if he cries out at birth","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Al-Miswar ibn Makhramah and Jabir ibn ‘Abd Allah said: The Messenger of Allah ﷺ said, “The infant does not inherit until he cries out. His crying out is that he shouts, or cries, or sneezes.”"]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":2},{"key":"sh28171","label":"الأوسط","number":4596,"n":4587},{"key":"sh1352","label":"كما في مجمع البحرين","number":4,"lafz":true}],"full":1,"dr":1},{"num":6090,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُلُّ قَسْمٍ قُسِمَ فِي الْجَاهِلِيَّةِ فَهُوَ عَلَى مَا قُسِمَ لَهُ وَكُلُّ قَسْمٍ أَدْرَكَهُ الإِسْلاَمُ فَهُوَ عَلَى قَسْمِ الإِسْلاَمِ."],"takhrij":"حسن: رواه أبو داود (2914)، وابن ماجه (2485) كلاهما من حديث موسى بن داود قال: حدثنا محمد بن مسلم الطائفي، عن عمرو بن دينار، عن أبي الشعثاء، عن ابن عبا س فذكره.","grade":"حسن","chapter_ar":"باب فيمن أسلم على ميراث","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2914) and Ibn Majah (2485).","chapter_en":"Regarding one who becomes Muslim while an inheritance is pending","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":23,"content":{"translation":{"en":["Ibn ‘Abbas said: The Prophet ﷺ said, “Every division that was made in the pre-Islamic period remains upon the way it was divided, and every division that Islam reached is to be according to the division of Islam.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2914,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2485}],"full":1,"dr":1},{"num":6091,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ، قَالَ إِنَّ أَهْلَ الإِسْلاَمِ لاَ يُسَيِّبُونَ، وَإِنَّ أَهْلَ الْجَاهِلِيَّةِ كَانُوا يُسَيِّبُونَ."],"takhrij":"رواه البخاري في الفرائض (6753) عن قبيصة بن عقبة، حدثنا سفيان، عن أبي قيس، عن هزيل، عن عبد الله فذكره موقوفا.","grade":"صحيح","chapter_ar":"باب ميراث السائبة","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6753).","chapter_en":"The inheritance of the one set free without retaining wala’","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":24,"content":{"translation":{"en":["‘Abd Allah said: The people of Islam do not practice sa’ibah, whereas the people of the pre-Islamic period used to do so."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6753,"lafz":true}],"full":1,"dr":1},{"num":6092,"demo":false,"sanad":"","matn":["عن عُمَرَ بن الْخَطَّابِ يَقُولُ الدِّيَةُ لِلْعَاقِلَةِ وَلاَ تَرِثُ الْمَرْأَةُ مِنْ دِيَةِ زَوْجِهَا شَيْئًا حَتَّى قَالَ لَهُ الضَّحَّاكُ بْنُ سُفْيَانَ كَتَبَ إِلَىَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ أُوَرِّثَ امْرَأَةَ أَشْيَمَ الضِّبَابِيِّ مِنْ دِيَةِ زَوْجِهَا."],"takhrij":"صحيح: رواه أبو داود (2927)، والترمذي (2110)، وابن ماجه (2642)، وأحمد (15745) كلهم من حديث الزهري، عن سعيد بن المسيب أن عمر بن الخطاب قال:فذكره.","grade":"صحيح","chapter_ar":"باب في المرأة ترث من دية زوجها","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2927), al-Tirmidhi (2110), Ibn Majah (2642), and Ahmad (15745).","chapter_en":"A woman inheriting from the blood money of her husband","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":25,"content":{"translation":{"en":["‘Umar ibn al-Khattab used to say: The blood money belongs to the ‘aqilah, and a woman does not inherit anything from the blood money of her husband. Then al-Dahhak ibn Sufyan told him: “The Messenger of Allah ﷺ wrote to me instructing me to give the wife of Ashyam al-Dibabi inheritance from the blood money of her husband.”"]},"buhuth":{"en":["“Ashyam” is pronounced with a fathah on the hamzah and a sukun on the shin. “Al-Dibabi” is pronounced with a kasrah on the dad, meaning one affiliated with Dibab."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2927,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":2110},{"key":"ibnmajah","label":"ابن ماجه","number":2642},{"key":"ahmad","label":"مسند الإمام أحمد","number":15745,"n":15745}],"full":1,"dr":1},{"num":6093,"demo":false,"sanad":"","matn":["عَنْ زَيْنَبَ أنها كَانَتْ تَفْلي رَأْسَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَعِنْدَهُ امْرَأَةُ عُثْمَانَ بْنِ مَظْعُونٍ، وَنِسَاءٌ مِنَ الْمُهَاجِرَاتِ يَشْكُونَ مَنَازِلَهُنَّ، وَأَنَّهُنَّ يَخْرُجْنَ مِنْهُ، وَيُضَيَّقُ عَلَيْهِنَّ فِيهِ، فَتَكَلَّمَتْ زَيْنَبُ، وَتَرَكَتْ رَأْسَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنَّكِ لَسْتِ تَكَلَّمِينَ بِعَيْنَيْكِ، تَكَلَّمِي وَاعْمَلِي عَمَلَكِ. فَأَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَئِذٍ أَنْ يُوَرَّث مِنَ الْمُهَاجِرِينَ النِّسَاءُ. فَمَاتَ عَبْدُ اللَّهِ فَوَرِثَتْهُ امْرَأَتُهُ دَارًا بِالْمَدِينَةِ."],"takhrij":"حسن: رواه أبو داود (3080)، والبيهقي (6/156) من طريقه، وأحمد (27050) -واللفظ له- كلهم من حديث عبدالواحد بن زياد، حدثنا الأعمش، عن جامع بن شداد، عن كلثوم، عن زينب فذكرته.","grade":"حسن","chapter_ar":"باب توريث نساء المهاجرين منازل أزواجهن","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3080) and Ahmad (27050), and this is his wording. Ahmad also narrated it (27049) in another shorter form: that the Prophet ﷺ gave the women inheritance rights in their allocated properties.","chapter_en":"Women of the Emigrants inheriting the homes of their husbands","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["Zaynab said: I was picking lice from the head of the Messenger of Allah ﷺ, and with him was the wife of ‘Uthman ibn ‘Affan and some of the emigrant women, who were complaining about their dwellings, that they were being turned out of them and that things had become tight for them. Zaynab spoke while she had left the hair of the Messenger of Allah ﷺ, so the Messenger of Allah ﷺ said, “You are not speaking with your eyes; speak, and continue your work.” On that day, the Messenger of Allah ﷺ ordered that the houses of the Emigrants should be inherited by the women. So when ‘Abd Allah ibn Mas‘ud died, his wife inherited a house in Madinah."]},"buhuth":{"en":["His statement, “their allocated properties,” refers to plots of land marked out as owned property, like designated land grants for ownership, whether for the state or for individuals."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3080,"lafz":true},{"key":"ahmad","label":"اللفظ له. ورواه أحمد أيضًا","number":27049,"n":27050},{"key":"ahmad","label":"مسند الإمام أحمد","number":27050,"n":27050}],"full":1,"dr":1},{"num":6094,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ تُوُفِّيَ أَبِي وَعَلَيْهِ دَيْنٌ، فَعَرَضْتُ عَلَى غُرَمَائِهِ أَنْ يَأْخُذُوا التَّمْرَ بِمَا عَلَيْهِ، فَأَبَوْا وَلَمْ يَرَوْا أَنَّ فِيهِ وَفَاءً، فَأَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرْتُ ذَلِكَ لَهُ، فَقَالَ إِذَا جَدَدْتَهُ فَوَضَعْتَهُ فِي الْمِرْبَدِ آذَنْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَجَاءَ وَمَعَهُ أَبُو بَكْرٍ وَعُمَرُ فَجَلَسَ عَلَيْهِ، وَدَعَا بِالْبَرَكَةِ ثُمَّ قَالَ ادْعُ غُرَمَاءَكَ، فَأَوْفِهِمْ. فَمَا تَرَكْتُ أَحَدًا لَهُ عَلَى أَبِي دَيْنٌ إِلاَّ قَضَيْتُهُ، وَفَضَلَ ثَلاَثَةَ عَشَرَ وَسْقًا سَبْعَةٌ عَجْوَةٌ، وَسِتَّةٌ لَوْنٌ أَوْ سِتَّةٌ عَجْوَةٌ وَسَبْعَةٌ لَوْنٌ، فَوَافَيْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَغْرِبَ فَذَكَرْتُ ذَلِكَ لَهُ فَضَحِكَ فَقَالَ ائْتِ أَبَا بَكْرٍ وَعُمَرَ فَأَخْبِرْهُمَا. فَقَالاَ لَقَدْ عَلِمْنَا إِذْ صَنَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا صَنَعَ أَنْ سَيَكُونُ ذَلِكَ."],"takhrij":"صحيح: رواه البخاري في الصلح (2709) عـن محمد بن بشار، حـدثنا عبد الوهاب، حدثنا عبيد الله، عن وهب بن كيسان، عن جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب الصلح بين الغرماء وأصحاب الميراث","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2709).","chapter_en":"Reconciliation between creditors and the heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":27,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: My father died while he owed a debt. I offered his creditors that they take dates in place of what was owed to them, but they refused, not thinking that it would cover the debt. So I came to the Prophet ﷺ and mentioned that to him. He said, “When you gather the dates and place them in the drying area, then inform the Messenger of Allah ﷺ.” He came, along with Abu Bakr and ‘Umar, sat upon it, and prayed for blessing. Then he said, “Call your creditors and pay them.” I did not leave anyone to whom my father owed anything except that I paid him in full, and there remained thirteen wasqs: seven of ‘ajwah dates and six of lawn dates, or six of ‘ajwah and seven of lawn. Then I met the Messenger of Allah ﷺ at the sunset prayer and told him about it, and he smiled and said, “Go to Abu Bakr and ‘Umar and inform them.” They said, “We knew, when the Messenger of Allah ﷺ did what he did, that this would happen.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2709,"lafz":true}],"full":1},{"num":6095,"demo":false,"sanad":"","matn":["عن ابن عباس في قوله عزَّ وجلَّ: ﴿يُوصِيكُمُ اللَّهُ فِي أَوْلَادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ﴾ [سورة النساء: 11] قال: كان الميراث للولد، وكانت الوصية للوالدين والأقربين، فنسخ الله من ذلك ما أحب، فجعل للولد الذكر مثل حظ الأنثيين، وجعل للوالدين لكل واحد منهما السدس، وجعـل للمرأة الثمن والربع، وللزوج الشطر والربع."],"takhrij":"صحيح: رواه البخاري في الوصايا (2747) عن محمد بن يوسف، عن ورقاء، عن ابن أبي نجيح، عن عطاء، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في نسخ الوصية بآية الميراث","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2747). In another narration (4578): “And He made for the two parents, for each of them, one-sixth and one-third.”","chapter_en":"What has been reported regarding the abrogation of the bequest by the verse of inheritance","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Ibn ‘Abbas said regarding the saying of Allah, Most High: “Allah instructs you concerning your children: for the male is a share equal to that of two females” [Surat al-Nisa’: 11]: Inheritance used to belong to the children, and the bequest was for the parents and the close relatives. Then Allah abrogated from that whatever He willed. He made for the male child the share of two female children, made for each parent one-sixth, made for the wife one-eighth or one-fourth, and for the husband one-half or one-fourth."]},"intro":{"ar":["قال اللّٰه عز وجل:","﴿ كُتِبَ عَلَيْكُمْ إِذَا حَضَرَ أَحَدَكُمُ الْمَوْتُ إِنْ تَرَكَ خَيْرًا الْوَصِيَّةُ لِلْوَالِدَيْنِ وَالْأَقْرَبِينَ بِالْمَعْرُوفِ حَقًّا عَلَى الْمُتَّقِينَ ۝ فَمَنْ بَدَّلَهُ بَعْدَ مَا سَمِعَهُ فَإِنَّمَا إِثْمُهُ عَلَى الَّذِينَ يُبَدِّلُونَهُ ۚ إِنَّ اللَّهَ سَمِيعٌ عَلِيمٌ ۝ فَمَنْ خَافَ مِنْ مُوصٍ جَنَفًا أَوْ إِثْمًا فَأَصْلَحَ بَيْنَهُمْ فَلَا إِثْمَ عَلَيْهِ ۚ إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ ﴾","[سورة البقرة: ١٨٠-١٨٢]"],"en":["Allah, Mighty and Majestic, said:","“It is prescribed for you, when death approaches one of you, if he leaves wealth, that he make a bequest for parents and close relatives according to what is acceptable, as a duty upon the righteous. Then whoever alters it after hearing it, the sin is only upon those who alter it. Indeed, Allah is All-Hearing, All-Knowing. But whoever fears from the testator some error or sin and brings about reconciliation between them, there is no sin upon him. Indeed, Allah is Most Forgiving, Most Merciful.”","[Surat al-Baqarah: 180–182]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2747,"lafz":true},{"key":"وفی_روایہ","label":". وفي رواية","number":4578}],"full":1,"dr":1},{"num":6096,"demo":false,"sanad":"","matn":["عن ابن عباس قال: إِنْ تَرَكَ خَيْرًا الْوَصِيَّةُ لِلْوَالِدَيْنِ وَالْأَقْرَبِينَ فكانت الوصية كذلك حتى نسختها آية الميراث."],"takhrij":"حسن: رواه أبو داود (2869)، ومن طريقه البيهقي (6/265) عن أحمد بن محمد بن ثابت المروزي، حدثني علي بن حسين بن واقد، عن أبيه، عن يزيد النحوي، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في نسخ الوصية بآية الميراث","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2869) and al-Bayhaqi (6/265).","chapter_en":"What has been reported regarding the abrogation of the bequest by the verse of inheritance","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Ibn ‘Abbas said: “If he leaves wealth, then a bequest for the parents and close relatives…” This ruling remained as such until the verse of inheritance abrogated it."]},"buhuth":{"en":["Before the revelation of the inheritance verse, the bequest was obligatory. Then it was abrogated for the heirs, while it remained recommended for non-heirs, and this is the view of the majority of scholars. However, if a person owes a debt, or has a trust, or property held in safekeeping, then he must make a bequest about it in order to preserve the rights of others."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2869,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":6},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":12546,"n":12669}],"full":1,"dr":1},{"num":6097,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا حقُّ امْرِئٍ مُسْلِمٍ لَهُ شَىْءٌ يُرِيدُ أَنَّ يُوصِي فِيهِ يَبِيتُ لَيْلَتَيْنِ إِلاَّ وَوَصِيَّتُهُ مَكْتُوبَةٌ عِنْدَهُ."],"takhrij":"متفق عليه: رواه مـالك في الوصية (1) عن نافع، عـن عبد الله بن عمر فذكره.ورواه البخاري في الوصايا (2738) من طريق مالك.","grade":"متفق عليه","chapter_ar":"باب استحباب الوصية لغير الوارث","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (1), al-Bukhari (2738), and Muslim (1627).","chapter_en":"The recommendation of making a bequest for one who is not an heir","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Ibn ‘Umar narrated that the Messenger of Allah ﷺ said: “It is not proper for a Muslim who has something he wishes to bequeath to stay for two nights except that his will is written and kept with him.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":1,"lafz":true},{"key":"bukhari","label":"البخاري","number":2738},{"key":"muslim","label":"مسلم","number":1627}],"full":1,"dr":1},{"num":6098,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الرَّجُلَ لَيَعْمَلُ بِعَمَلِ أَهْلِ الْخَيْرِ سَبْعِينَ سَنَةً، فَإِذَا أَوْصَى حَافَ فِي وَصِيَّتِهِ، فَيُخْتَمُ لَهُ بِشَرِّ عَمَلِهِ، فَيَدْخُلُ النَّارَ، وَإِنَّ الرَّجُلَ لَيَعْمَلُ بِعَمَلِ أَهْلِ الشَّرِّ سَبْعِينَ سَنَةً، فَيَعْدِلُ فِي وَصِيَّتِهِ، فَيُخْتَمُ لَهُ بِخَيْرِ عَمَلِهِ، فَيَدْخُلُ الْجَنَّةَ.","قال أبو هريرة: اقرؤوا إن شئتم تِلْكَ حُدُودُ اللَّهِ إلى قوله وَلَهُ عَذَابٌ مُهِينٌ [سورة النساء:13-14]"],"takhrij":"حسن: رواه أبو داود (2867)، وابن ماجه (2703)، والترمذي (2117)، وأحمد (7743) واللفظ لأحمد، كلهم من حديث أشعث بن عبدالله، عن شهر بن حوشب، عن أبي هريرة فذكره. قال الترمذي: \"حسن غريب\".","grade":"حسن","chapter_ar":"باب كراهية الإضرار في الوصية","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2867), Ibn Majah (2703), al-Tirmidhi (2117), who graded it Hasan, and Ahmad (7743). The wording is Ahmad’s.","chapter_en":"The reprehensibility of causing harm in a bequest","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “A man may perform the deeds of the people of goodness for seventy years, but when he makes a bequest he behaves unjustly in his bequest, so the end of his deeds is sealed with evil and he enters the Fire. And a man may perform the deeds of the people of evil for seventy years, but he is just in his bequest, so the end of his deeds is sealed with good and he enters Paradise.” Abu Hurayrah said: Recite, if you wish: “These are the limits set by Allah…” to His saying, “…and for him is a humiliating punishment.” [Surat al-Nisa’: 13–14]"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2867,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2703,"n":2704},{"key":"tirmidhi","label":"الترمذي","number":2117},{"key":"ahmad","label":"مسند الإمام أحمد","number":7742,"n":7742},{"key":"ahmad","label":"احمد","number":7743,"n":7742}],"full":1,"dr":1},{"num":6099,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ الْبَاهِلِيِّ، قَالَ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي خُطْبَتِهِ عَامَ حَجَّةِ الْوَدَاعِ إِنَّ اللَّهَ قَدْ أَعْطَى كُلَّ ذِي حَقٍّ حَقَّهُ فَلاَ وَصِيَّةَ لِوَارِثٍ."],"takhrij":"صحيح: رواه أبو داود (2870)، والترمذي (2120)، وابن ماجه (2713)، وأحمد (22294)، والبيهقي (6/72، 264) من طريق إسماعيل بن عياش، ثنا شرحبيل بن مسلم الخولاني قال: سمعت أبا أمامة الباهلي يقول فذكره.","grade":"صحيح","chapter_ar":"باب لا وصية لوارث","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2870), al-Tirmidhi (2120), Ibn Majah (2713), Ahmad (22294), and al-Bayhaqi (6/264, 272).","chapter_en":"There is no bequest for an heir","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abu Umamah said: I heard the Messenger of Allah ﷺ say in his sermon during the Farewell Pilgrimage: “Allah has given every person entitled to a right his due right, so there is no bequest for an heir.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2870,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":2120},{"key":"ibnmajah","label":"ابن ماجه","number":2713},{"key":"kubrabayhaqi","label":"البيهقي","number":6},{"key":"ahmad","label":"مسند الإمام أحمد","number":22294,"n":22294}],"full":1,"dr":1},{"num":6100,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ خَارِجَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَطَبَهُمْ وَهُوَ عَلَى رَاحِلَتِهِ وَإِنَّ رَاحِلَتَهُ لَتَقْصَعُ بِجِرَّتِهَا وَإِنَّ لُغَامَهَا لَيَسِيلُ بَيْنَ كَتِفَىَّ قَالَ إِنَّ اللَّهَ قَسَمَ لِكُلِّ وَارِثٍ نَصِيبَهُ مِنَ الْمِيرَاثِ فَلاَ يَجُوزُ لِوَارِثٍ وَصِيَّةٌ."],"takhrij":"حسن: رواه الترمذي (2121)، والنسائي (6/247)، وابن ماجه (2712)، وأحمد (17669) كلهم من طرق عن قتادة، عن شهر بن حوشب، عن عبد الرحمن بن غَنْم، عن عمرو بن خارجة، فذكره في حديث طويل تم تخريجه في العيدين.","grade":"حسن","chapter_ar":"باب لا وصية لوارث","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (2121), al-Nasa’i (6/247), Ibn Majah (2712), and Ahmad (17669).","chapter_en":"There is no bequest for an heir","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["‘Amr ibn Kharijah narrated: The Prophet ﷺ addressed them while on his mount, and its cud was moving in its mouth, and its saliva was flowing between my shoulders. He said: “Allah has apportioned to every heir his share of the inheritance, so a bequest is not valid for an heir.”"]},"buhuth":{"en":["Al-Tirmidhi said: “Hasan Sahih.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":2121,"lafz":true},{"key":"nasai","label":"النسائي","number":6},{"key":"ibnmajah","label":"ابن ماجه","number":2712},{"key":"ahmad","label":"مسند الإمام أحمد","number":17669,"n":17669}],"full":1,"dr":1},{"num":6101,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: إِنِّي لَتَحْتَ نَاقَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسِيلُ علي لُعَابُهَا، فَسَمِعْتُهُ يَقُولُ: إِنَّ اللَّهَ جَعَلَ لِكُلِّ ذِي حَقٍّ حَقَّهُ، أَلاَ لاَ وَصِيَّةَ لِوَارِثٍ...."],"takhrij":"صحيح: رواه ابن ماجه (2714) عن هشام بن عمار قال: حدثنا محمد بن شعيب بن شابور قال: حدثنا عبد الرحمن بن يزيد بن جابر، عن سعيد بن أبي سعيد، أنه حدثه عن أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب لا وصية لوارث","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (2714).","chapter_en":"There is no bequest for an heir","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Anas ibn Mālik reported: I was beneath the she-camel of the Messenger of Allah ﷺ while its saliva was dripping upon me, and I heard him say: “Indeed, Allah has assigned to every person entitled to a right his due right. Indeed, there is no bequest for an heir…”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2714,"lafz":true}],"full":1,"dr":1},{"num":6102,"demo":false,"sanad":"","matn":["عن عبد الله بن عمرو بن العاص أن رسول الله صلى الله عليه وسلم قال: لا تجوز وصية لوارث، والولد للفراش، وللعاهر حجر."],"takhrij":"حسن: رواه ابن عدي في الكامل (2/817) عن ابن ذُرَيح، ثنا عبد الأعلى بن حماد، ثنا حماد بن سلمة، عن حبيب المعلم، عن عمرو بن شعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب لا وصية لوارث","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn ‘Adi in al-Kamil (2/817).","chapter_en":"There is no bequest for an heir","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["‘Abd Allah ibn ‘Amr ibn al-‘As narrated that the Messenger of Allah ﷺ said: “A bequest for an heir is not valid; the child belongs to the bed, and the fornicator gets the stone [i.e., nothing].”"]}},"tuhfa":{},"refs":[{"key":"sh12579","label":"ابن عدي في الكامل","number":2,"lafz":true}],"full":1,"dr":1},{"num":6103,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بن أَبِي وَقَّاصٍ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعُودُنِي عَامَ حَجَّةِ الْوَدَاعِ مِنْ وَجَع اشْتَدَّ بِي، فَقُلْتُ: إِنِّي قَدْ بَلَغَ بِي مِنَ الْوَجَعِ، وَأَنَا ذُو مَالٍ، وَلاَ يَرِثُنِي إِلاَّ ابْنَةٌ، أَفَأَتَصَدَّقُ بثلثي مَالِي؟ قَالَ: لاَ. فَقُلْتُ: بِالشَّطْرِ؟ فَقَالَ: لاَ. ثُمَّ قَالَ: الثُّلُثُ، وَالثُّلْثُ كَبِيرٌ أَوْ كَثِيرٌ، إِنَّكَ أَنْ تَذَرَ وَرَثَتَكَ أَغْنِيَاءَ خَيْرٌ مِنْ أَنْ تَذَرَهُمْ عَالَةً يَتَكَفَّفُونَ النَّاسَ."],"takhrij":"متفق عليه: رواه مالك في الوصية (4) عن ابن شهاب، عن عامر بن سعد بن أبي وقاص، عن أبيه فذكره.","grade":"متفق عليه","chapter_ar":"باب الوصية بالثلث","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (4), al-Bukhari (1295), and Muslim (1628).","chapter_en":"Making a bequest of one-third","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Sa‘d ibn Abi Waqqas said: The Messenger of Allah ﷺ came to visit me during the Farewell Pilgrimage because of an illness that had become severe. I said, “O Messenger of Allah ﷺ, my illness has reached a serious state, and I am a man of wealth, and none inherits from me except one daughter. Shall I give two-thirds of my wealth in charity?” He said, “No.” I said, “Then half?” He said, “No.” Then he said, “One-third, and one-third is much—or great. To leave your heirs wealthy is better than to leave them poor, begging from people.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":4,"lafz":true},{"key":"bukhari","label":"البخاري","number":1295},{"key":"muslim","label":"مسلم","number":1628}],"full":1,"dr":1},{"num":6104,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ لَوْ أَنَّ النَّاسَ، غَضُّوا مِنَ الثُّلُثِ إِلَى الرُّبُعِ فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ الثُّلُثُ وَالثُّلُثُ كَثِيرٌ."],"takhrij":"متفق عليه: رواه البخاري في الوصايا (2743)، ومسلم في الوصية (1629) كلاهما من حديث هشام بن عروة، عن أبيه، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب الوصية بالثلث","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2743) and Muslim (1629).","chapter_en":"Making a bequest of one-third","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn ‘Abbas said: If people would reduce the bequest from one-third to one-fourth, that would be better, for the Messenger of Allah ﷺ said: “One-third, and one-third is much.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2743,"lafz":true},{"key":"muslim","label":"مسلم","number":1629}],"full":1},{"num":6105,"demo":false,"sanad":"","matn":["عن حَنْظَلَةَ بن حِذْيم جَدِّي، أَنَّ جَدَّهُ حَنِيفَةَ، قَالَ لِحِذْيَمٍ: اجْمَعْ لِي بَنِيَّ، فَإِنِّي أُرِيدُ أَنْ أُوصِيَ، فَجَمَعَهُمْ، فَقَالَ: إِنَّ أَوَّلَ مَا أُوصِي أَنَّ لِيَتِيمِي هَذَا الَّذِي فِي حِجْرِي مِائَةً مِنَ الْإِبِلِ، الَّتِي كُنَّا نُسَمِّيهَا فِي الْجَاهِلِيَّةِ: الْمُطَيَّبَةَ، فَقَالَ حِذْيَمٌ: يَا أَبَتِ، إِنِّي سَمِعْتُ بَنِيكَ يَقُولُونَ: إِنَّمَا نُقِرُّ بِهَذَا عِنْدَ أَبِينَا، فَإِذَا مَاتَ رَجَعْنَا فِيهِ، قَالَ: فَبَيْنِي وَبَيْنَكُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ حِذْيَمٌ: رَضِينَا، فَارْتَفَعَ حِذْيَمٌ، وَحَنِيفَةُ، وحَنْظَلَةُ مَعَهُمْ غُلَامٌ، وَهُوَ رَدِيفٌ لِحِذْيَمٍ، فَلَمَّا أَتَوُا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، سَلَّمُوا عَلَيْهِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، مَا رَفَعَكَ يَا أَبَا حِذْيَمٍ؟ قَالَ: هَذَا، وَضَرَبَ بِيَدِهِ عَلَى فَخِذِ حِذْيَمٍ، فَقَالَ: إِنِّي خَشِيتُ أَنْ يَفْجَأَنِي الْكِبَرُ، أَوِ الْمَوْتُ، فَأَرَدْتُ أَنْ أُوصِيَ، وَإِنِّي قُلْتُ: إِنَّ أَوَّلَ مَا أُوصِي أَنَّ لِيَتِيمِي هَذَا الَّذِي فِي حِجْرِي مِائَةً مِنَ الْإِبِلِ، كُنَّا نُسَمِّيهَا فِي الْجَاهِلِيَّةِ: الْمُطَيَّبَةَ، فَغَضِبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، حَتَّى رَأَيْنَا الْغَضَبَ فِي وَجْهِهِ، وَكَانَ قَاعِدًا فَجَثَا عَلَى رُكْبَتَيْهِ، وَقَالَ: لَا، لَا، لَا الصَّدَقَةُ خَمْسٌ، وَإِلَّا فَعَشْرٌ، وَإِلَّا فَخَمْسَ عَشْرَةَ، وَإِلَّا فَعِشْرُونَ، وَإِلَّا فَخَمْسٌ وَعِشْرُونَ، وَإِلَّا فَثَلَاثُونَ، وَإِلَّا فَخَمْسٌ وَثَلَاثُونَ، فَإِنْ كَثُرَتْ فَأَرْبَعُونَ.","قال: فودَّعوه، ومع اليتيم عصا، وهو يضرب جملا، فقـال النبي صلى الله عليه وسلم: عظُمت هذه هِراوة يتيم.","قال حنظلة: فدنا بي إلى النبي صلى الله عليه وسلم، فقال: إن لي بنين ذوي لحى، ودون ذلك، وإن ذا أصغرهم، فادع الله له، فمسح رأسه، وقال: بارك الله فيك، أو بورك فيه.","قال ذيال: فلقد رأيت حنظلة يؤتى بالإنسان الوارم وجهه، أو البهيمة الوارمة الضرع، فيتفُل على يديه، ويقول: بسم الله، ويضع يده على رأسه، ويقول: على موضع كف رسول الله صلى الله عليه وسلم، فيمسحه عليه، وقال ذيال: فيذهب الورم."],"takhrij":"صحيح: رواه أحمد (20665) عن أبي سعيد مولى بني هاشم، حدثنا ذيَّال بن عبيد بن حنظلة قال: سمعت حنظلة بن حِذيم جدي قال فذكره.","grade":"صحيح","chapter_ar":"باب الوصية بالثلث","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (20665).","chapter_en":"Making a bequest of one-third","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Hanzalah ibn Hidhaym narrated from his grandfather Hunayfah: He said to Hidhaym, “Gather my sons for me, for I want to make a bequest.” So he gathered them, and he said, “The first thing I bequeath is one hundred camels to this orphan of mine who is under my care—camels that we used to call in the pre-Islamic period al-mutayyabah.” Hidhaym said, “Father, I have heard your sons saying: we only acknowledge this while our father is alive, but when he dies we will go back on it.” He said, “Then the Messenger of Allah ﷺ will judge between me and you.” Hidhaym said, “We accept.” So Hidhaym, Hunayfah, and Hanzalah, along with a boy riding behind Hidhaym, went to the Prophet ﷺ. When they came to him and greeted him, the Prophet ﷺ said, “What has brought you here, O Abu Hidhaym?” He replied, pointing to Hidhaym’s thigh with his hand, “This one. I feared that old age or death might come upon me suddenly, so I wanted to make a bequest. I said that the first thing I bequeath is one hundred camels to this orphan of mine who is under my care, camels we used to call in the pre-Islamic period al-mutayyabah.” The Messenger of Allah ﷺ became angry until we saw anger in his face. He had been sitting, then he dropped to his knees and said: “No, no, no. Charity is five, or ten, or fifteen, or twenty, or twenty-five, or thirty, or thirty-five, and if it is more, then forty.” Then they took leave of him, and the orphan had a stick with which he was striking a camel. The Prophet ﷺ said, “This is quite a large staff for an orphan.” Hanzalah said: Then he brought me close to the Prophet ﷺ and said, “I have sons with beards, and others younger than that, and this is the youngest of them, so supplicate to Allah for him.” He wiped his head and said, “May Allah bless you,” or “May he be blessed.”","Dhiyal said: I indeed saw Hanzalah brought to a person whose face was swollen, or to an animal whose udder was swollen, and he would spit lightly on his hands, say “In the name of Allah,” place his hand upon his head and say, “Upon the place where the palm of the Messenger of Allah ﷺ rested,” then wipe over it. Dhiyal said: “Then the swelling would go away.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":20665,"n":20665,"lafz":true}],"full":1,"dr":1},{"num":6106,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ، بْنِ حُصَيْنٍ. أَنَّ رَجُلاً، أَعْتَقَ سِتَّةَ مَمْلُوكِينَ لَهُ عِنْدَ مَوْتِهِ لَمْ يَكُنْ لَهُ مَالٌ غَيْرُهُمْ فَدَعَا بِهِمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَزَّأَهُمْ أَثْلاَثًا ثُمَّ أَقْرَعَ بَيْنَهُمْ فَأَعْتَقَ اثْنَيْنِ وَأَرَقَّ أَرْبَعَةً وَقَالَ لَهُ قَوْلاً شَدِيدًا."],"takhrij":"صحيح: رواه مسلم في البيوع (1668) من طرق عن إسماعيل بن علية، عن أيوب، عن أبي قلابة، عن أبي المهلب، عن عمران بن حصين فذكره.","grade":"صحيح","chapter_ar":"باب الوصية بالثلث","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1668).","chapter_en":"Making a bequest of one-third","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["‘Imran ibn Husayn narrated that a man freed six slaves of his at the time of his death, and he had no other wealth besides them. The Messenger of Allah ﷺ called for them, divided them into three groups, then cast lots among them, freed two, and left four in slavery, and he spoke sternly to him."]},"buhuth":{"en":["His statement, “and he spoke sternly to him,” is explained in the Sunan as: “Had I been present before he was buried, he would not have been buried in the graveyards of the Muslims.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1668,"lafz":true}],"full":1,"dr":1,"rep":[6765]},{"num":6107,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَجُلًا كَانَ لَهُ سِتَّةُ أَعْبُدٍ، فَأَعْتَقَهُمْ عِنْدَ مَوْتِهِ، فَأَقْرَعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَهُمُ، فَأَعْتَقَ مِنْهُمُ اثْنَيْنِ، وَأَرَقَّ أَرْبَعَةً."],"takhrij":"صحيح: رواه ابن أبي شيبة (23847، 37239) عن عبيد الله بن موسى، عن إسرائيل، عن عبد الله بن المختار، عن محمد بن زياد، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب الوصية بالثلث","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Abi Shaybah (23847, 37239).","chapter_en":"Making a bequest of one-third","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah narrated that a man had six slaves and freed them at his death, so the Prophet ﷺ cast lots among them, freed two of them, and left four in slavery."]}},"tuhfa":{},"refs":[{"key":"sh9944","label":"ابن أبي شيبة","number":23847,"lafz":true},{"key":"sh9944","label":"المصنف لابن أبي شيبة","number":23381,"n":23364},{"key":"sh9944","label":"ابن ابي شيبه","number":37239}],"full":1,"dr":1},{"num":6108,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ مَا تَرَكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دِينَارًا وَلاَ دِرْهَمًا وَلاَ شَاةً وَلاَ بَعِيرًا وَلاَ أَوْصَى بِشَىْءٍ."],"takhrij":"صحيح: رواه مسلم في الوصية (1635) من طرق عن الأعمش، عن أبي وائل، عن مسروق، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ما ترك رسول الله ﷺ دينارًا ولا درهمًا حتى يوصي به","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1635).","chapter_en":"The Messenger of Allah ﷺ did not leave behind a dinar or a dirham to make a bequest concerning","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ did not leave behind a dinar, nor a dirham, nor a sheep, nor a camel, nor did he make a bequest concerning anything."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1635,"lafz":true}],"full":1,"rep":[9387]},{"num":6109,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ الْحَارِثِ، خَتَنِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخِي جُوَيْرِيَةَ بِنْتِ الْحَارِثِ قَالَ مَا تَرَكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ مَوْتِهِ دِرْهَمًا وَلاَ دِينَارًا وَلاَ عَبْدًا وَلاَ أَمَةً وَلاَ شَيْئًا، إِلاَّ بَغْلَتَهُ الْبَيْضَاءَ وَسِلاَحَهُ وَأَرْضًا جَعَلَهَا صَدَقَةً."],"takhrij":"صحيح: رواه البخاري في الوصايا (2739) عن إبراهيم بن الحارث، حدثنا يحيى بن أبي بكير، حدثنا زهير بن معاوية الجعفي، حدثنا أبو إسحاق، عن عمرو بن الحارث فذكره.","grade":"صحيح","chapter_ar":"باب ما ترك رسول الله ﷺ دينارًا ولا درهمًا حتى يوصي به","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2739).","chapter_en":"The Messenger of Allah ﷺ did not leave behind a dinar or a dirham to make a bequest concerning","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["‘Amr ibn al-Harith, the brother of Juwayriyyah bint al-Harith and the brother-in-law of the Messenger of Allah ﷺ, said: The Messenger of Allah ﷺ did not leave behind at his death a dirham, nor a dinar, nor a male slave, nor a female slave, nor anything at all, except his white mule, his weapons, and some land which he had made into charity."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2739,"lafz":true}],"full":1,"rep":[9385]},{"num":6110,"demo":false,"sanad":"","matn":["عن طَلْحَةَ بن مصرف قَالَ سَأَلْتُ عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى رَضِيَ اللَّهُ عَنْهُمَا هَلْ كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوْصَى فَقَالَ لاَ. فَقُلْتُ كَيْفَ كُتِبَ عَلَى النَّاسِ الْوَصِيَّةُ أَوْ أُمِرُوا بِالْوَصِيَّةِ قَالَ أَوْصَى بِكِتَابِ اللَّهِ."],"takhrij":"متفق عليه: رواه البخاري في الوصايا (2740) من طريق مالك، عن طلحة بن مصرف فذكره. وليس في رواية موطأ يحيى الليثي.","grade":"متفق عليه","chapter_ar":"باب الوصية بالتمسك بالكتاب والسنة","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2740) and Muslim (1636).","chapter_en":"The bequest to hold firmly to the Book and the Sunnah","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Talhah ibn Musarrif said: I asked ‘Abd Allah ibn Abi Awfa, “Did the Prophet ﷺ make a bequest?” He said, “No.” I said, “Then how was bequest prescribed for people, or how were they commanded to make a bequest?” He said, “He made a bequest with the Book of Allah.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2740,"lafz":true},{"key":"muslim","label":"مسلم","number":1636}],"full":1,"dr":1},{"num":6111,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ، عَلَيْهِ السَّلاَمُ قَالَ كَانَ آخِرُ كَلاَمِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الصَّلاَةَ الصَّلاَةَ اتَّقُوا اللَّهَ فِيمَا مَلَكَتْ أَيْمَانُكُمْ."],"takhrij":"حسن: رواه أبو داود (5156)، وابن ماجه (2698) كلاهما من حديث محمد بن فضيل، عن مغيرة، عن أم موسى، عن علي فذكره.","grade":"حسن","chapter_ar":"باب في آخر وصية أوصى بها النبي ﷺ","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (5156) and Ibn Majah (2698).","chapter_en":"The last advice given by the Prophet ﷺ","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["‘Ali said: The last words of the Messenger of Allah ﷺ were: “Prayer, prayer, and fear Allah regarding those whom your right hands possess.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":5156,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2698},{"key":"sh13058","label":"المحتضرين لابن أبي الدنيا","number":29,"n":29}],"full":1,"dr":1,"rep":[9340]},{"num":6112,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ قَالَ يَوْمُ الْخَمِيسِ، وَمَا يَوْمُ الْخَمِيسِ ثُمَّ بَكَى حَتَّى خَضَبَ دَمْعُهُ الْحَصْبَاءَ فَقَالَ اشْتَدَّ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَجَعُهُ يَوْمَ الْخَمِيسِ فَقَالَ ائْتُونِي بِكِتَابٍ أَكْتُبْ لَكُمْ كِتَابًا لَنْ تَضِلُّوا بَعْدَهُ أَبَدًا. فَتَنَازَعُوا وَلاَ يَنْبَغِي عِنْدَ نَبِيٍّ تَنَازُعٌ فَقَالُوا هَجَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ دَعُونِي فَالَّذِي أَنَا فِيهِ خَيْرٌ مِمَّا تَدْعُونِي إِلَيْهِ. وَأَوْصَى عِنْدَ مَوْتِهِ بِثَلاَثٍ أَخْرِجُوا الْمُشْرِكِينَ مِنْ جَزِيرَةِ الْعَرَبِ، وَأَجِيزُوا الْوَفْدَ بِنَحْوِ مَا كُنْتُ أُجِيزُهُمْ. وَنَسِيتُ الثَّالِثَةَ.","قال يعقوب بن محمد: سألت المغيرة بن عبد الرحمن عن جزيرة العرب، فقال: مكة، والمدينة، واليمامة، واليمن.","وقال يعقوب: والعرج أول تهامة."],"takhrij":"متفق عليه: رواه البخاري في الجهاد (3053)، ومسلم في الوصية (1637) كلاهما من حديث سفيان بن عيينة، عن سليمان الأحول، عن سعيد بن جبير، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب وصية رسول الله ﷺ في المصلحة العامة","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3053) and Muslim (1637).","chapter_en":"The Prophet’s bequest concerning the public welfare","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ibn ‘Abbas said: Thursday — and what was Thursday? Then he wept until his tears soaked the pebbles. He said: The pain of the Messenger of Allah ﷺ became severe on Thursday, and he said, “Bring me writing material so I may write for you a document after which you will never go astray.” Then they disputed, and disputing should not take place in the presence of a prophet. They said, “Has the Messenger of Allah ﷺ become delirious?” He said, “Leave me, for what I am engaged in is better than what you are calling me to.” At his death he gave three instructions: “Expel the polytheists from the Arabian Peninsula, and treat the delegations as generously as I used to treat them.” And I forgot the third. Ya‘qub ibn Muhammad said: I asked al-Mughirah ibn ‘Abd al-Rahman about the Arabian Peninsula, and he said: Makkah, Madinah, al-Yamamah, and Yemen. Ya‘qub said: And al-‘Arj is the beginning of Tihamah."]},"buhuth":{"en":["His statement, “Has the Messenger of Allah ﷺ become delirious?” In Sahih Muslim it is recorded as: “Has he become delirious? Ask him.” Al-Qadi ‘Iyad said: This wording is more accurate than the narration that states it plainly as “He is delirious,” because that would not be sound concerning him ﷺ, since the meaning of that word is incoherent speech. Rather, this came as a question from the speaker, expressing disapproval of those who said, “Do not write,” meaning: do not neglect the command of the Messenger of Allah ﷺ and treat it like the speech of someone speaking irrationally, for he ﷺ did not speak irrationally.","His statement, “Leave me, for what I am engaged in is better,” means: leave me from the dispute and noise that you have begun. What I am engaged in — being mindful of Allah and preparing to meet Him — is better than what you are occupied with.","His statement, “Treat the delegations generously,” is an instruction from the Messenger of Allah ﷺ to honor visiting delegations, host them, and show them generosity, in order to win their hearts and encourage others among those whose hearts were to be reconciled and others like them, because in the final days of the Messenger of Allah ﷺ many delegations were coming from all regions to enter Islam.","His statement, “I forgot the third,” and in another narration, “He remained silent about the third, or he mentioned it and I was caused to forget it,” means that Ibn ‘Abbas remained silent and did not mention the third. As for “or he mentioned it and I was caused to forget it,” that was said by Sa‘id ibn Jubayr. It was also said that the third instruction was the dispatch of Usamah’s army."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3053,"lafz":true},{"key":"muslim","label":"مسلم","number":1637}],"full":1,"dr":1,"rep":[9335]},{"num":6113,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّهُ قَالَ يَوْمُ الْخَمِيسِ وَمَا يَوْمُ الْخَمِيسِ. ثُمَّ جَعَلَ تَسِيلُ دُمُوعُهُ حَتَّى رَأَيْتُ عَلَى خَدَّيْهِ كَأَنَّهَا نِظَامُ اللُّؤْلُؤِ. قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ائْتُونِي بِالْكَتِفِ وَالدَّوَاةِ - أَوِ اللَّوْحِ وَالدَّوَاةِ - أَكْتُبْ لَكُمْ كِتَابًا لَنْ تَضِلُّوا بَعْدَهُ أَبَدًا. فَقَالُوا إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَهْجُرُ."],"takhrij":"صحيح: رواه مسلم في الوصية (1637: 21) عن إسحاق بن إبراهيم، أخبرنا وكيع، عن مالك بن مغول، عن طلحة بن مصرف، عن سعيد بن جبير، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب وصية رسول الله ﷺ في المصلحة العامة","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (21:1637).","chapter_en":"The Prophet’s bequest concerning the public welfare","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ibn ‘Abbas said: Thursday — and what was Thursday? Then his tears began to flow until I saw them on his cheeks like strings of pearls. He said: The Messenger of Allah ﷺ said, “Bring me a shoulder blade and an inkwell — or a tablet and an inkwell — so I may write for you a document after which you will never go astray.” Then they said: The Messenger of Allah ﷺ is delirious."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":21,"lafz":true},{"key":"muslim","label":"مسلم في الوصيه","number":1637,"n":4233}],"full":1},{"num":6114,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ لَمَّا حُضِرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَفِي الْبَيْتِ رِجَالٌ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَلُمُّوا أَكْتُبْ لَكُمْ كِتَابًا لاَ تَضِلُّوا بَعْدَهُ. فَقَالَ بَعْضُهُمْ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ غَلَبَهُ الْوَجَعُ وَعِنْدَكُمُ الْقُرْآنُ، حَسْبُنَا كِتَابُ اللَّهِ. فَاخْتَلَفَ أَهْلُ الْبَيْتِ وَاخْتَصَمُوا، فَمِنْهُمْ مَنْ يَقُولُ قَرِّبُوا يَكْتُبُ لَكُمْ كِتَابًا لاَ تَضِلُّوا بَعْدَهُ. وَمِنْهُمْ مَنْ يَقُولُ غَيْرَ ذَلِكَ، فَلَمَّا أَكْثَرُوا اللَّغْوَ وَالاِخْتِلاَفَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُومُوا.","قال عبيد الله: فكان يقول ابن عباس: إن الرزية كل الرزية ما حال بين رسول الله صلى الله عليه وسلم وبين أن يكتب لهم ذلك الكتاب لاختلافهم ولغَطهم."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4432)، ومسلم في الوصية (1637: 22) كلاهما من حديث عبد الرزاق، أخبرنا معمر، عن الزهري، عن عبيد الله بن عبد الله بن عتبة، عن ابن عباس فذكره، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب وصية رسول الله ﷺ في المصلحة العامة","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4432) and Muslim (22:1637), with the wording of al-Bukhari.","chapter_en":"The Prophet’s bequest concerning the public welfare","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ibn ‘Abbas said: When the Messenger of Allah ﷺ was in his final illness, and there were men in the house, the Prophet ﷺ said, “Come, I will write for you a document after which you will not go astray.” Some of them said: The pain has overwhelmed the Messenger of Allah ﷺ, and you have the Qur’an, so the Book of Allah is sufficient for us. Then the people in the house differed and disputed. Some of them were saying: Bring it near so he may write for you a document after which you will not go astray. Others said something else. When their vain talk and disagreement increased, the Messenger of Allah ﷺ said, “Get up.” ‘Ubayd Allah said: Ibn ‘Abbas used to say: The true calamity, all calamity, was what prevented the Messenger of Allah ﷺ from writing that document for them because of their disagreement and noise."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4432,"lafz":true},{"key":"muslim","label":"مسلم","number":22},{"key":"muslim","label":"مسلم في الوصيه","number":1637,"n":4234}],"full":1,"dr":1},{"num":6115,"demo":false,"sanad":"","matn":["عَنِ الأَسْوَدِ، قَالَ ذَكَرُوا عِنْدَ عَائِشَةَ أَنَّ عَلِيًّا رَضِيَ اللَّهُ عَنْهُمَا كَانَ وَصِيًّا. فَقَالَتْ مَتَى أَوْصَى إِلَيْهِ وَقَدْ كُنْتُ مُسْنِدَتَهُ إِلَى صَدْرِي ـ أَوْ قَالَتْ حَجْرِي ـ فَدَعَا بِالطَّسْتِ، فَلَقَدِ انْخَنَثَ فِي حَجْرِي، فَمَا شَعَرْتُ أَنَّهُ قَدْ مَاتَ، فَمَتَى أَوْصَى إِلَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في الوصايا (2741)، ومسلم في الوصية (1636) كلاهما من حديث إسماعيل بن علية، عن ابن عون، عن إبراهيم، عن الأسود فذكره.","grade":"متفق عليه","chapter_ar":"باب لم يكن عليٌّ وصيًّا","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2741) and Muslim (1636).","chapter_en":"‘Ali was not appointed as executor","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Al-Aswad ibn Yazid said: It was mentioned in the presence of ‘A’ishah that ‘Ali had been appointed as executor, so she said: When did he appoint him? I had him resting against my chest — or she said: in my lap — and he asked for a basin. He then leaned heavily in my lap, and I did not even realize that he had died. So when did he appoint him?"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2741,"lafz":true},{"key":"muslim","label":"مسلم","number":1636}],"full":1},{"num":6116,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنَّ الْعَاصَ بْنَ وَائِلٍ، أَوْصَى أَنْ يُعْتَقَ، عَنْهُ مِائَةُ رَقَبَةٍ فَأَعْتَقَ ابْنُهُ هِشَامٌ خَمْسِينَ رَقَبَةً فَأَرَادَ ابْنُهُ عَمْرٌو أَنْ يَعْتِقَ عَنْهُ الْخَمْسِينَ الْبَاقِيَةَ فَقَالَ حَتَّى أَسْأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ أَبِي أَوْصَى بِعِتْقِ مِائَةِ رَقَبَةٍ وَإِنَّ هِشَامًا أَعْتَقَ عَنْهُ خَمْسِينَ وَبَقِيَتْ عَلَيْهِ خَمْسُونَ رَقَبَةً أَفَأُعْتِقُ عَنْهُ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّهُ لَوْ كَانَ مُسْلِمًا فَأَعْتَقْتُمْ عَنْهُ أَوْ تَصَدَّقْتُمْ عَنْهُ أَوْ حَجَجْتُمْ عَنْهُ بَلَغَهُ ذَلِكَ."],"takhrij":"حسن: رواه أبو داود (2883)، وأحمد (6704)، والبيهقي (6/279) كلهم من طرق عن عمرو بن شعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب لا تنفع تنفيذ وصية من مات كافرًا","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2883), Ahmad (6704), and al-Bayhaqi (6/279).","chapter_en":"Carrying out the bequest of one who died a disbeliever does not benefit him","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["‘Abd Allah ibn ‘Amr ibn al-‘As narrated: Al-‘As ibn Wa’il made a bequest that one hundred slaves be freed on his behalf. His son Hisham freed fifty slaves for him. Then his son ‘Amr wanted to free the remaining fifty on his behalf, but he said: Let me ask the Messenger of Allah ﷺ first. So he came to the Prophet ﷺ and said: O Messenger of Allah ﷺ, my father made a bequest that one hundred slaves be freed on his behalf, and Hisham has freed fifty for him, and fifty remain. Shall I free them on his behalf? The Messenger of Allah ﷺ said: “If he had been a Muslim, then if you had freed slaves on his behalf, or given charity on his behalf, or performed pilgrimage on his behalf, that would have reached him.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2883,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":6},{"key":"ahmad","label":"مسند الإمام أحمد","number":6704,"n":6704},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":12637,"n":12760}],"full":1,"dr":1,"rep":[4108]},{"num":6117,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: أَصَابَ عمر أَرْضًا بِخَيْبَرَ، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَأْمِرُهُ فِيهَا، فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي أَصَبْتُ أَرْضًا بِخَيْبَرَ، لَمْ أُصِبْ مَالاً قَطُّ هُوَ أَنْفَسَ عِنْدِي مِنْهُ، فَمَا تَأْمُرُنِي بِهِ؟ قَالَ: إِنْ شِئْتَ حَبَسْتَ أَصْلَهَا، وَتَصَدَّقْتَ بِهَا.","قال: فتصدق بها عمر أنه لا يباع أصلها، ولا يبتاع، ولا يورث، ولا يوهب. قال: فتصدق عمر في الفقراء، وفى القربى، وفى الرقاب، وفى سبيل الله، وابن السبيل، والضيف. لا جناح على من وليها أن يأكل منها بالمعروف، أو يطعم صديقا غير متمول فيه.","قال فحدثت به ابن سيرين، فقال: غير متأثل مالا."],"takhrij":"متفق عليه: رواه البخاري في الشروط (2737) ومسلم في الوصية (1632) كلاهما من حديث ابن عون، عن نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب الوقف للغني والفقير والضيف، وأنه من وليه فليأكل بالمعروف بقدر عمله","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2737) and Muslim (1632).","chapter_en":"Endowment for the rich, the poor, and the guest, and that the one who oversees it may eat from it in a fair manner according to his work","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿUmar reported: ʿUmar acquired a piece of land at Khaybar. He came to the Prophet ﷺ seeking his instruction regarding it and said: “O Messenger of Allah ﷺ, I have acquired land at Khaybar, and I have never acquired any wealth more precious to me than it. What do you command me to do with it?” He said: “If you wish, retain the original property and give its benefit in charity.” So ʿUmar gave it in charity on the condition that its original property would neither be sold, purchased, inherited, nor gifted.","ʿUmar dedicated it for the poor, relatives, the freeing of slaves, the cause of Allah, the stranded traveler, and guests. There is no blame upon the person administering it if he eats from it according to what is reasonable or feeds a friend, provided that he does not seek to accumulate wealth from it. He said: I narrated this to Ibn Sīrīn, and he said:","“Without accumulating wealth from it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2737,"lafz":true},{"key":"muslim","label":"مسلم","number":1632}],"full":1,"dr":1},{"num":6118,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى رَجُلاً يَسُوقُ بَدَنَةً، فَقَالَ ارْكَبْهَا. قَالَ إِنَّهَا بَدَنَةٌ. قَالَ ارْكَبْهَا. قَالَ إِنَّهَا بَدَنَةٌ. قَالَ ارْكَبْهَا. وَيْلَكَ."],"takhrij":"متفق عليه: رواه مالك في الحج (144) عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره. ورواه البخاري في الحج (1689)،ومسلم في الحج (1322) كلاهما من طريق مالك.","grade":"متفق عليه","chapter_ar":"باب هل ينتفع الواقف بوقفه","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (144), al-Bukhari (1689), and Muslim (1322).","chapter_en":"May the endower benefit from his endowment?","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Anas ibn Malik narrated that the Prophet ﷺ saw a man driving a sacrificial camel and said, “Ride it.” The man said: It is a sacrificial camel. He said, “Ride it.” He said: It is a sacrificial camel. He said, “Ride it,” three times."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":144},{"key":"bukhari","label":"البخاري","number":1689,"lafz":true},{"key":"muslim","label":"مسلم","number":1322}],"full":1,"rep":[14635]},{"num":6119,"demo":false,"sanad":"","matn":["عن كَعْبِ بن مَالِكٍ ـ رَضِيَ اللَّهُ عَنْهُ. قُلْتُ يَا رَسُولَ اللَّهِ، إِنَّ مِنْ تَوْبَتِي أَنْ أَنْخَلِعَ مِنْ مَالِي صَدَقَةً إِلَى اللَّهِ وَإِلَى رَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ أَمْسِكْ عَلَيْكَ بَعْضَ مَالِكَ فَهُوَ خَيْرٌ لَكَ. قُلْتُ فَإِنِّي أُمْسِكُ سَهْمِي الَّذِي بِخَيْبَرَ."],"takhrij":"صحيح: رواه البخاري في الوصايا (2757) عن يحيى بن بكير، حدثنا الليث، عن عقيل، عن ابن شهاب قال: أخبرني عبد الرحمن بن عبد الله بن كعب أن عبد الله بن كعب قال: سمعت كعب بن مالك قال فذكره.","grade":"صحيح","chapter_ar":"باب من الأفضل للواقف أن يمسك بعض أمواله","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2757).","chapter_en":"It is better for the one giving away property to keep some of his wealth","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Ka‘b ibn Malik said: I said: O Messenger of Allah ﷺ, part of my repentance is that I give away all my wealth in charity for Allah and His Messenger ﷺ. He said: “Keep some of your wealth, for that is better for you.” I said: Then I will keep my share at Khaybar."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2757,"lafz":true}],"full":1},{"num":6120,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ أَنَّ سَعْدَ بْنَ عُبَادَةَ رَضِيَ اللَّهُ عَنْهُمْ أَخَا بَنِي سَاعِدَةَ تُوُفِّيَتْ أُمُّهُ وَهْوَ غَائِبٌ، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ أُمِّي تُوُفِّيَتْ وَأَنَا غَائِبٌ عَنْهَا، فَهَلْ يَنْفَعُهَا شَىْءٌ إِنْ تَصَدَّقْتُ بِهِ عَنْهَا قَالَ نَعَمْ. قَالَ فَإِنِّي أُشْهِدُكَ أَنَّ حَائِطِي الْمِخْرَافَ صَدَقَةٌ عَلَيْهَا."],"takhrij":"صحيح: رواه البخاري في الوصايا (2762) عن إبراهيم بن موسى، أخبرنا هشام بن يوسف، أن ابن جريج أخبرهم قال: أخبرني يعلى أنه سمع عكرمة مولى ابن عباس يقول: أنبأنا ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب الإشهاد في الوقف والصدقة","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2762).","chapter_en":"Having witnesses for an endowment and charity","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Ibn ‘Abbas narrated that Sa‘d ibn ‘Ubadah, the brother of Banu Sa‘idah, lost his mother while he was absent. He came to the Prophet ﷺ and said: O Messenger of Allah ﷺ, my mother has died while I was absent. Will anything benefit her if I give charity on her behalf? He said, “Yes.” He said: Then I make you witness that my garden al-Mikhraf is charity on her behalf."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2762,"lafz":true}],"full":1},{"num":6121,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ لَمَّا قَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ أَمَرَ بِالْمَسْجِدِ وَقَالَ يَا بَنِي النَّجَّارِ ثَامِنُونِي بِحَائِطِكُمْ هَذَا. قَالُوا لاَ وَاللَّهِ لاَ نَطْلُبُ ثَمَنَهُ إِلاَّ إِلَى اللَّهِ."],"takhrij":"متفق عليه: رواه البخاري في الوصايا (2774)، ومسلم في المساجد (524) كلاهما من حديث عبد الوارث، عن أبي التياح الضبعي قال: حدثني أنس بن مالك فذكره، واللفظ للبخاري. ولفظ مسلم نحوه.","grade":"متفق عليه","chapter_ar":"باب وقف الأرض للمسجد","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2774) and Muslim (524), with the wording of al-Bukhari.","chapter_en":"Endowing land for a mosque","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Anas ibn Malik said: When the Messenger of Allah ﷺ arrived in Madinah, he ordered that the mosque be established and said: “O Banu al-Najjar, name me a price for this orchard of yours.” They said: No, by Allah, we seek no price for it except from Allah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2774,"lafz":true},{"key":"muslim","label":"مسلم","number":524}],"full":1},{"num":6122,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عَمْرِو بْنِ الْعَاصِ أَنَّ رَجُلاً أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَقَالَ: إِنِّي فَقِيرٌ، وَلَيْسَ لِي شَىْءٌ، وَلِي يَتِيمٌ، فَقَالَ: كُلْ مِنْ مَالِ يَتِيمِكَ غَيْرَ مُسْرِفٍ، وَلاَ مبذر أَوْ مُبَادِرٍ، وَلاَ مُتَأَثِّلٍ."],"takhrij":"حسن: رواه أبو داود (2872)، والنسائي (6/256)، وابن ماجه (2718)، وأحمد (2/186)، والبيهقي (6/284) كلهم من طرق عن عمرو بن شعيب، عن أبيه، عن جده قال: فذكره.","grade":"حسن","chapter_ar":"باب من ولي مال اليتيم ينال من ماله بقدر حاجته","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2872), al-Nasa’i (6/256), Ibn Majah (2718), and Ahmad (2/186).","chapter_en":"The guardian of an orphan’s wealth may take from it according to his need","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["‘Abd Allah ibn ‘Amr ibn al-‘As narrated that a man came to the Prophet ﷺ and said: I am poor and I have nothing, but I have an orphan under my care. He said: “Eat from the wealth of your orphan without excess, without wastefulness or haste, and without building up wealth for yourself from it.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2872,"lafz":true},{"key":"nasai","label":"النسائي","number":6},{"key":"ibnmajah","label":"ابن ماجه","number":2718},{"key":"ahmad","label":"أحمد","number":2}],"full":1,"dr":1},{"num":6123,"demo":false,"sanad":"","matn":["لِي أَبُو هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَيُّمَا رَجُلٍ أَعْتَقَ امْرَأً مُسْلِمًا اسْتَنْقَذَ اللَّهُ بِكُلِّ عُضْوٍ مِنْهُ عُضْوًا مِنْهُ مِنَ النَّارِ.","قال سعيد بن مرجانة: فانطلقت به إلى علي بن حسين، فعمد علي بن حسين -رضي لله عنهما- إلى عبد له قد أعطاه به عبد الله بن جعفر عشرة آلاف درهم أو ألف دينار، فأعتقه."],"takhrij":"متفق عليه: رواه البخاري في العتق (2517)، ومسلم في العتق (1509: 24) كلاهما من طريق عاصم بن محمد العمري، حدثني واقد بن محمد (يعني أخاه)، حدثني سعيد بن مُرجانة صاحب علي بن حسين قال: قال لي أبو هريرة رضي الله عنه فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في فضل العتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2517) and Muslim (1509:24). Ahmad (9441), Ibn al-Jarud (968), and al-Bayhaqi (6/273) narrated it through another chain and added: “So much so that for the hand he frees a hand, for the foot a foot, and for the private part the private part.”","chapter_en":"Chapter on the virtue of freeing slaves","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ said, “Whoever frees a Muslim slave, Allah will save from the Fire a limb of his for every limb of that slave.” Sa‘id ibn Marjanah said: I took this report to ‘Ali ibn al-Husayn, and ‘Ali ibn al-Husayn — may Allah be pleased with them both — went to a slave of his for whom ‘Abd Allah ibn Ja‘far had offered him ten thousand dirhams or one thousand dinars, and he set him free."]},"intro":{"ar":["قال اللّٰه تعالى:","(فَكُّ رَقَبَةٍ ۝ أَوْ إِطْعَامٌ فِي يَوْمٍ ذِي مَسْغَبَةٍ ۝ يَتِيمًا ذَا مَقْرَبَةٍ) [البلد: ١٣ - ١٥]."],"en":["Allah Most High said:","“Freeing a slave, or feeding on a day of severe hunger, an orphan of near kin.” [Surah al-Balad, 90:13–15]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2517,"lafz":true},{"key":"muslim","label":"مسلم","number":24},{"key":"ahmad","label":". ورواه أحمد","number":9441},{"key":"sh13071","label":"ابن الجارود","number":968},{"key":"kubrabayhaqi","label":"البيهقي","number":273},{"key":"muslim","label":"مسلم في العتق","number":1509}],"full":1,"dr":1},{"num":6124,"demo":false,"sanad":"","matn":["عَنْ أَبِي نَجِيحٍ السُّلَمِيِّ، قَالَ حَاصَرْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَصْرِ الطَّائِفِ - قَالَ مُعَاذٌ سَمِعْتُ أَبِي يَقُولُ بِقَصْرِ الطَّائِفِ بِحِصْنِ الطَّائِفِ كُلُّ ذَلِكَ - فَسَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ مَنْ بَلَغَ بِسَهْمٍ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ فَلَهُ دَرَجَةٌ. وَسَاقَ الْحَدِيثَ وَسَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ أَيُّمَا رَجُلٍ مُسْلِمٍ أَعْتَقَ رَجُلاً مُسْلِمًا فَإِنَّ اللَّهَ عَزَّ وَجَلَّ جَاعِلٌ وِقَاءَ كُلِّ عَظْمٍ مِنْ عِظَامِهِ عَظْمًا مِنْ عِظَامِ مُحَرَّرِهِ مِنَ النَّارِ وَأَيُّمَا امْرَأَةٍ أَعْتَقَتِ امْرَأَةً مُسْلِمَةً فَإِنَّ اللَّهَ جَاعِلٌ وِقَاءَ كُلِّ عَظْمٍ مِنْ عِظَامِهَا عَظْمًا مِنْ عِظَامِ مُحَرَّرِهَا مِنَ النَّارِ يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه أبو داود (3965)، والترمذي (1638)، والنسائي (3143)، وصحّحه ابن حبان (4615)، والحاكم (2/95، 3/49-50)، والبيهقي (10/272)، وأحمد (17022) كلهم من طرق عن هشام بن أبي عبد الله، عن قتادة، عن سالم بن أبى الجعد، عن معدان بن أبى طلحة، عن أبى نجيح السلمى قال فذكره، ومنهم من اختصره.","grade":"صحيح","chapter_ar":"باب ما جاء في فضل العتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3965), al-Tirmidhi (1638), who authenticated it, al-Nasa’i (3143), and Ibn Hibban, who authenticated it (4615).","chapter_en":"Chapter on the virtue of freeing slaves","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu Najih al-Sulami, who is ‘Amr ibn ‘Abasah, said: We laid siege alongside the Messenger of Allah ﷺ at the fortress of al-Ta’if. Mu‘adh said: I heard my father say, “At the palace of al-Ta’if,” “at the fortress of al-Ta’if” — all of that was said. I heard the Messenger of Allah ﷺ say, “Whoever causes an arrow to reach its mark in the cause of Allah, Mighty and Majestic, will have one degree for it.” Then he mentioned the rest of the narration. And I heard the Messenger of Allah ﷺ say, “Any Muslim man who frees a Muslim man, Allah, Mighty and Majestic, will make each bone of the freed person a protection for each bone of his from the Fire. And any Muslim woman who frees a Muslim woman, Allah will make each bone of the freed woman a protection for each bone of her from the Fire on the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3965,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1638},{"key":"nasai","label":"النسائي","number":3143},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":4615},{"key":"ahmad","label":"احمد","number":17022}],"full":1,"dr":1},{"num":6125,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ وَغَيْرِهِ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ أَيُّمَا امْرِئٍ مُسْلِمٍ أَعْتَقَ امْرَأً مُسْلِمًا كَانَ فَكَاكَهُ مِنْ النَّارِ يُجْزِي كُلُّ عُضْوٍ مِنْهُ عُضْوًا مِنْهُ وَأَيُّمَا امْرِئٍ مُسْلِمٍ أَعْتَقَ امْرَأَتَيْنِ مُسْلِمَتَيْنِ كَانَتَا فَكَاكَهُ مِنْ النَّارِ يُجْزِي كُلُّ عُضْوٍ مِنْهُمَا عُضْوًا مِنْهُ وَأَيُّمَا امْرَأَةٍ مُسْلِمَةٍ أَعْتَقَتْ امْرَأَةً مُسْلِمَةً كَانَتْ فَكَاكَهَا مِنْ النَّارِ يُجْزِي كُلُّ عُضْوٍ مِنْهَا عُضْوًا مِنْهَا."],"takhrij":"حسن: رواه الترمذي (1547) عن محمد بن عبد الأعلى، حدثنا عمران بن عيينة أخو سفيان بن عيينة، عن حصين، عن سالم بن أبي الجعد، عن أبي أمامة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في فضل العتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1547).","chapter_en":"Chapter on the virtue of freeing slaves","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu Umamah and others among the Companions of the Prophet ﷺ narrated from the Prophet ﷺ that he said: “Any Muslim man who frees a Muslim man, that will be his ransom from the Fire; each limb of the slave will count for one of his limbs. Any Muslim man who frees two Muslim women, they will be his ransom from the Fire; each limb of the two will count for one of his limbs. And any Muslim woman who frees a Muslim woman, she will be her ransom from the Fire; each limb of the freed woman will count for one of her limbs.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1547,"lafz":true}],"full":1,"dr":1},{"num":6126,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب، عن رسول الله صلى الله عليه وسلم قال: من أعتق رقبة مؤمنة وقى الله تعالى بكل عضو منها عضوا منه من النار."],"takhrij":"حسن: رواه النسائي في الكبرى (4877)، والطحاوي في مشكله (715) كلاهما من حديث أبي نعيم، حدثنا الحكم بن أبي نُعم البجلي، حدثتني فاطمة بنت علي قالت: قال أبي عن رسول الله صلى الله عليه وسلم فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء في فضل العتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i in al-Kubra (4877) and al-Tahawi in Mushkil al-Athar (715).","chapter_en":"Chapter on the virtue of freeing slaves","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["‘Ali ibn Abi Talib narrated from the Messenger of Allah ﷺ that he said: “Whoever frees a believing slave, Allah Most High will protect from the Fire one of his limbs for every limb of that slave.”"]}},"tuhfa":{},"refs":[{"key":"kubranasai","label":"النسائي في الكبرى","number":4877,"lafz":true},{"key":"sh22547","label":"الطحاوي في مشكله","number":715}],"full":1,"dr":1},{"num":6127,"demo":false,"sanad":"","matn":["عَنِ الْغَرِيفِ بْنِ الدَّيْلَمِيِّ، قَالَ أَتَيْنَا وَاثِلَةَ بْنَ الأَسْقَعِ فَقُلْنَا لَهُ حَدِّثْنَا حَدِيثًا، لَيْسَ فِيهِ زِيَادَةٌ وَلاَ نُقْصَانٌ فَغَضِبَ وَقَالَ إِنَّ أَحَدَكُمْ لَيَقْرَأُ وَمُصْحَفُهُ مُعَلَّقٌ فِي بَيْتِهِ فَيَزِيدُ وَيَنْقُصُ. قُلْنَا إِنَّمَا أَرَدْنَا حَدِيثًا سَمِعْتَهُ مِنَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ أَتَيْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي صَاحِبٍ لَنَا أَوْجَبَ - يَعْنِي - النَّارَ بِالْقَتْلِ فَقَالَ أَعْتِقُوا عَنْهُ يُعْتِقِ اللَّهُ بِكُلِّ عُضْوٍ مِنْهُ عُضْوًا مِنْهُ مِنَ النَّارِ."],"takhrij":"صحيح: رواه أبو داود (3964)، عن عيسى بن محمد الرملي، حدثنا ضمرة، عن إبراهيم بن أبى عبلة، عن الغريف بن الديلمي فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في فضل العتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3964), Ahmad (16012), al-Hakim (2/212), and al-Bayhaqi (8/132–133).","chapter_en":"Chapter on the virtue of freeing slaves","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Al-Ghurayf ibn al-Daylami said: We came to Wathilah ibn al-Asqa‘ and said to him: Narrate to us a report with neither addition nor omission. He became upset and said: One of you recites while his written copy hangs in his house, yet he still adds and omits. We said: We only want a report you heard from the Prophet ﷺ. He said: We came to the Messenger of Allah ﷺ concerning one of our companions who had made the Fire mandatory upon himself — meaning by killing — and he said: “Free a slave on his behalf, and Allah will free for every limb of that slave one of his limbs from the Fire.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3964,"lafz":true},{"key":"hakim","label":"الحاكم","number":212},{"key":"kubrabayhaqi","label":"البيهقي","number":8},{"key":"ahmad","label":"مسند الإمام أحمد","number":16012,"n":16012}],"full":1,"dr":1},{"num":6128,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ، قَالَ: جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، أَخْبِرْنِي بِعَمَلٍ يُدْخِلُنِي الْجَنَّةَ. قَالَ: لَئِنْ قَصَّرْتَ فِي الْخُطْبَةِ لَقَدْ عَرَّضْتَ الْمَسْأَلَةَ! أَعْتِقِ النَّسَمَةَ وَفُكَّ الرَّقَبَةَ، قَالَ: يَا رَسُولَ اللَّهِ، أَوَمَا هُمَا سَوَاءٌ؟ قَالَ: لَا، عِتْقُ النَّسَمَةِ أَنْ تَفَرَّدَ بِهَا، وَفَكُّ الرَّقَبَةِ أَنْ تُعِينَ فِي ثَمَنِهَا، وَالْمِنْحَةُ الْوَكُوفُ، وَالْفَيْءُ عَلَى ذِي الرَّحِمِ الظَّالِمِ، قَالَ: فَمَنْ لَمْ يُطِقْ ذَلِكَ؟ قَالَ: فَأَطْعِمِ الْجَائِعَ وَاسْقِ الظَّمْآنَ، قَالَ: فَإِنْ لَمْ أَسْتَطِعْ؟ قَالَ: مُرْ بِالْمَعْرُوفِ وَانْهَ عَنِ الْمُنْكَرِ، قَالَ: فَمَنْ لَمْ يُطِقْ ذَاكَ؟ قَالَ: فَكُفَّ لِسَانَكَ إِلَّا مِنْ خَيْرٍ."],"takhrij":"صحيح: رواه أحمد (18647)، وأبو داود الطيالسي (775)، والبخاري في الأدب المفرد (69)، وابن حبان (374)، والحاكم (2/217)، والبيهقي (10/272-273) كلهم من حديث عيسى بن عبد الرحمن، عن طلحة اليامي، عن عبد الرحمن بن عوسجة، عن البراء فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في فضل العتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (18647), Abu Dawud al-Tayalisi (775), al-Bukhari in al-Adab al-Mufrad (69), and Ibn Hibban (374).","chapter_en":"Chapter on the virtue of freeing slaves","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Al-Bara’ said: A Bedouin came to the Prophet ﷺ and said: O Messenger of Allah ﷺ, tell me of a deed that will admit me into Paradise. He said, “Though you made the speech brief, you have put the question clearly. Free a person from bondage and help free another from bondage.” He said: O Messenger of Allah ﷺ, are they not the same? He said: “No. Freeing a person from bondage means that you do it by yourself entirely, while helping free a person means that you assist in paying his price. Also, lending a milking animal, and showing kindness to a relative even when he is oppressive.” He said: What if I cannot do that? He said: “Then feed the hungry and give drink to the thirsty.” He said: What if I cannot? He said: “Then command what is right and forbid what is wrong.” He said: What if I cannot do that? He said: “Then restrain your tongue from everything except good.”"]}},"tuhfa":{},"refs":[{"key":"tayalisi","label":"أبو داود الطيالسي","number":775,"lafz":true},{"key":"adab","label":"البخاري في الأدب المفرد","number":69},{"key":"ibnhibban","label":"ابن حبان","number":374},{"key":"ahmad","label":"مسند الإمام أحمد","number":18647,"n":18647}],"full":1},{"num":6129,"demo":false,"sanad":"","matn":["عن أَبِي بُرْدَةَ بن أَبِي مُوسَى فَقَالَ: أَيْ بَنِيَّ أَلَا أُحَدِّثُكُمْ حَدِيثًا حَدَّثَنِي أَبِي، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أَعْتَقَ رَقَبَةً أَعْتَقَ اللهُ عَزَّ وَجَلَّ بِكُلِّ عُضْوٍ مِنْهَا عُضْوًا مِنْهُ مِنَ النَّارِ."],"takhrij":"حسن: رواه أحمد (19623)، والحاكم (2/211)، والبيهقي في الكبرى(10/272) كلهم من حديث سفيان بن عيينة، حدثنا شعبة الكوفي قال: كنا عند أبي بردة بن أبي موسى فقال فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في فضل العتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (19623), al-Hakim (2/211), and al-Bayhaqi (10/272).","chapter_en":"Chapter on the virtue of freeing slaves","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu Burdah ibn Abi Musa said: My son, shall I not tell you a report that my father told me from the Messenger of Allah ﷺ? He said: “Whoever frees a slave, Allah, Mighty and Majestic, will free one of his limbs from the Fire for every limb of that slave.”"]}},"tuhfa":{},"refs":[{"key":"hakim","label":"الحاكم","number":211},{"key":"kubrabayhaqi","label":"البيهقي","number":10},{"key":"ahmad","label":"مسند الإمام أحمد","number":19623,"n":19623,"lafz":true}],"full":1,"dr":1},{"num":6130,"demo":false,"sanad":"","matn":["عن عائشة قالت: قال رسول الله صلى الله عليه وسلم: من أعتق رقبة أعتق الله بكل عضو منه عضوا."],"takhrij":"صحيح: رواه الطحاوي في مشكله (716) عن أبي أمية، حدثنا أبو عاصم، عن عثمان بن مرة، عن القاسم، عن عائشة، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في فضل العتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tahawi in Mushkil al-Athar (716).","chapter_en":"Chapter on the virtue of freeing slaves","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ said, “Whoever frees a slave, Allah will free a limb of his for every limb of that slave.”"]}},"tuhfa":{},"refs":[{"key":"sh22547","label":"الطحاوي في مشكله","number":716,"lafz":true}],"full":1,"dr":1},{"num":6131,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ يَجْزِي وَلَدٌ وَالِدًا إِلاَّ أَنْ يَجِدَهُ مَمْلُوكًا فَيَشْتَرِيَهُ فَيُعْتِقَهُ."],"takhrij":"صحيح: رواه مسلم في العتق (1510) من طريق جرير، عن سهيل، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب فضل عتق الوالد","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1510).","chapter_en":"Chapter on the virtue of freeing one’s parent","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said, “A child cannot fully repay his parent except if he finds him enslaved, buys him, and sets him free.”"]},"buhuth":{"en":["His statement, “then he buys him and frees him,” means that emancipation takes effect immediately upon purchase, and no separate declaration of freedom is needed. A separate declaration would imply that the parent remained under his ownership for some period if he wished, and no scholar has said that a father remains owned by his child until the child later frees him."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1510,"lafz":true}],"full":1,"dr":1},{"num":6132,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ سَأَلْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَىُّ الْعَمَلِ أَفْضَلُ، قَالَ إِيمَانٌ بِاللَّهِ، وَجِهَادٌ فِي سَبِيلِهِ. قُلْتُ فَأَىُّ الرِّقَابِ أَفْضَلُ قَالَ أَغْلاَهَا ثَمَنًا، وَأَنْفَسُهَا عِنْدَ أَهْلِهَا. قُلْتُ فَإِنْ لَمْ أَفْعَلْ. قَالَ تُعِينُ صَانِعًا أَوْ تَصْنَعُ لأَخْرَقَ. قَالَ فَإِنْ لَمْ أَفْعَلْ. قَالَ تَدَعُ النَّاسَ مِنَ الشَّرِّ، فَإِنَّهَا صَدَقَةٌ تَصَدَّقُ بِهَا عَلَى نَفْسِكَ."],"takhrij":"متفق عليه: رواه البخاري في العتق (2518)، ومسلم في الإيمان (136: 84) كلاهما من طريق هشام بن عروة، عن أبيه، عن أبي مُراوح الليثي، عن أبي ذر فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل عتق الرقاب الثمينة والنفيسة","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2518) and Muslim (136:84).","chapter_en":"Chapter on the virtue of freeing valuable and precious slaves","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Abu Dharr said: I asked the Prophet ﷺ: Which deed is best? He said, “Faith in Allah and striving in His path.” I said: Then which slaves are best to free? He said, “Those most expensive in price and most precious to their owners.” I said: What if I cannot do that? He said: “Help a worker, or work on behalf of one who is unskilled.” He said: What if I cannot do that? He said: “Then refrain from harming people, for that is a charity you give on your own behalf.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2518,"lafz":true},{"key":"muslim","label":"مسلم","number":84},{"key":"muslim","label":"مسلم في الايمان","number":136}],"full":1,"rep":[226,13940]},{"num":6133,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ قَالَتْ: أَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْعَتَاقَةِ فِي كُسُوفِ الشَّمْسِ. وَفِي لفظ: كُنَّا نُؤْمَرُ عِنْدَ الخسوف بِالْعَتَاقَةِ."],"takhrij":"صحيح: رواه البخاري في العتق (2519) عن موسى بن مسعود، حدثنا زائدة بن قدامة، عن هشام بن عروة، عن فاطمة بنت المنذر، عن أسماء بنت أبي بكر، فذكرته. واللفظ الآخر عنده أيضا (2520) عن محمد بن أبي بكر، حدثنا عَثّام، حدثنا هشام به.","grade":"صحيح","chapter_ar":"باب الترغيب في العتق عند الكسوف والخسوف","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2519).","chapter_en":"Chapter on encouraging emancipation during a solar or lunar eclipse","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Asma’ bint Abi Bakr said: The Prophet ﷺ commanded emancipation during a solar eclipse. In another wording: We were commanded to free slaves during an eclipse."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2519,"lafz":true}],"full":1},{"num":6134,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ أَعْتَقَ شِرْكًا لَهُ فِي عَبْدٍ، فَكَانَ لَهُ مَالٌ يَبْلُغُ ثَمَنَ الْعَبْدِ قُوِّمَ الْعَبْدُ قِيمَةَ عَدْلٍ، فَأَعْطَى شُرَكَاءَهُ حِصَصَهُمْ وَعَتَقَ عَلَيْهِ، وَإِلاَّ فَقَدْ عَتَقَ مِنْهُ مَا عَتَقَ."],"takhrij":"متفق عليه: رواه مالك في العتق والولاء (1) عن نافع، عن عبد الله بن عمر فذكره. ورواه البخاري في العتق (2522)، ومسلم في العتق (1501: 1)، وفي الأيمان والنذور (1501: 47) كلاهما من طريق مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب العبد إذا كان بين شريكين فأكثر","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (1), al-Bukhari (2522), and Muslim (1501:1 and 1501:47).","chapter_en":"Chapter on a slave jointly owned by two or more partners","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar narrated that the Messenger of Allah ﷺ said: “Whoever frees his share in a slave, and has enough wealth to cover the price of the slave, then the slave is appraised fairly against him, he pays his partners their shares, and the slave becomes fully free through him. Otherwise, the portion already freed remains free.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":1},{"key":"bukhari","label":"البخاري","number":2522,"lafz":true},{"key":"muslim","label":"مسلم","number":1},{"key":"وفی","label":"وفي","number":47},{"key":"muslim","label":"مسلم في العتق","number":1501,"n":4325}],"full":1},{"num":6135,"demo":false,"sanad":"","matn":["اللَّهِ، عَنْ أَبِيهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ أَعْتَقَ عَبْدًا بَيْنَهُ وَبَيْنَ آخَرَ قُوِّمَ عَلَيْهِ فِي مَالِهِ قِيمَةَ عَدْلٍ لاَ وَكْسَ وَلاَ شَطَطَ ثُمَّ عَتَقَ عَلَيْهِ فِي مَالِهِ إِنْ كَانَ مُوسِرًا."],"takhrij":"متفق عليه: رواه البخاري في العتق (2521)، ومسلم في الأيمان والنذور (1501: 50) كلاهما من طريق سفيان بن عيينة، عن عمرو (هو ابن دينار)، عن سالم، عن أبيه، فذكره. والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"باب العبد إذا كان بين شريكين فأكثر","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2521) and Muslim (1501:50). The wording is that of Muslim.","chapter_en":"Chapter on a slave jointly owned by two or more partners","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn ‘Umar narrated that the Messenger of Allah ﷺ said: “Whoever frees a slave jointly owned between him and another, the slave is appraised against him according to a fair value from his wealth, with neither undervaluation nor overvaluation, and then the slave becomes fully free through his wealth if he is well-off.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2521,"lafz":true},{"key":"muslim","label":"مسلم","number":50},{"key":"muslim","label":"مسلم في الايمان والنذور","number":1501,"n":4329}],"full":1},{"num":6136,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ كَانَ يُفْتِي فِي الْعَبْدِ أَوِ الأَمَةِ يَكُونُ بَيْنَ شُرَكَاءَ، فَيُعْتِقُ أَحَدُهُمْ نَصِيبَهُ مِنْهُ، يَقُولُ قَدْ وَجَبَ عَلَيْهِ عِتْقُهُ كُلِّهِ، إِذَا كَانَ لِلَّذِي أَعْتَقَ مِنَ الْمَالِ مَا يَبْلُغُ، يُقَوَّمُ مِنْ مَالِهِ قِيمَةَ الْعَدْلِ، وَيُدْفَعُ إِلَى الشُّرَكَاءِ أَنْصِبَاؤُهُمْ، وَيُخَلَّى سَبِيلُ الْمُعْتَقِ. يُخْبِرُ ذَلِكَ ابْنُ عُمَرَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه البخاري في العتق (2525) عن أحمد بن مقدام، حدثنا الفضيل بن سليمان، حدثنا موسى بن عقبة، أخبرني نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب العبد إذا كان بين شريكين فأكثر","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2525).","chapter_en":"Chapter on a slave jointly owned by two or more partners","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn ‘Umar used to give legal rulings concerning a male or female slave jointly owned by partners, when one of them freed his share, saying: “It becomes binding upon him to free all of it if the one who freed his share has sufficient wealth. A fair valuation is made from his wealth, the partners are given their shares, and the freed person is released.” Ibn ‘Umar related this from the Prophet ﷺ."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2525,"lafz":true}],"full":1},{"num":6137,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أَعْتَقَ نَصِيبًا لَهُ فِي مَمْلُوكٍ، كُلِّفَ أَنْ يُتِمَّ عِتْقَهُ بِقِيمَةِ عَدْلٍ."],"takhrij":"صحيح: رواه أحمد في المسند (4451) عن هشيم، أخبرنا يحيى بن سعيد، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب العبد إذا كان بين شريكين فأكثر","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (4451), and also by him in (5474), with the addition: “If he does not have wealth by which to free him completely, then what he has freed is valid.”","chapter_en":"Chapter on a slave jointly owned by two or more partners","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn ‘Umar narrated that the Messenger of Allah ﷺ said: “Whoever frees a share he owns in a slave is required to complete his emancipation at a fair price.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":4451,"n":4451,"lafz":true}],"full":1,"dr":1},{"num":6138,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ فِي الْمَمْلُوكِ بَيْنَ الرَّجُلَيْنِ فَيُعْتِقُ أَحَدُهُمَا قَالَ يَضْمَنُ."],"takhrij":"صحيح: رواه مسلم في العتق (1502) من طريق محمد بن جعفر، حدثنا شعبة، عن قتادة، عن النضر بن أنس، عن بشير بن نهيك، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب العبد إذا كان بين شريكين فأكثر","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1502).","chapter_en":"Chapter on a slave jointly owned by two or more partners","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ concerning a slave jointly owned by two men, one of whom frees his share. He said: “He is liable for the remainder.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1502,"lafz":true}],"full":1},{"num":6139,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أَعْتَقَ عَبْدًا وَلَهُ فِيهِ شِرْكٌ، وَلَهُ وَفَاءٌ فَهُوَ حُرٌّ، وَيَضْمَنُ نَصِيبَ شُرَكَائِهِ بِقِيمَةِ عَدْلٍ لِمَا أَسَاءَ مُشَارَكَتَهُمْ، وَلَيْسَ عَلَى الْعَبْدِ شَيْءٌ."],"takhrij":"حسن: رواه النسائي في الكبرى (4942)، وابن حبان في صحيحه (4317) كلاهما من طريق الوليد بن مسلم، حدثنا أبو مُعيد حفص بن غيلان، عن سليمان بن موسى، عن نافع، عن ابن عمر، وعن عطاء، عن جابر قال: فذكره.","grade":"حسن","chapter_ar":"باب العبد إذا كان بين شريكين فأكثر","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i in al-Kubra (4942) and Ibn Hibban in his Sahih (4317).","chapter_en":"Chapter on a slave jointly owned by two or more partners","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Jabir, together with Ibn ‘Umar, narrated that the Messenger of Allah ﷺ said: “Whoever frees a slave in whom another person shares ownership, and he has the means, then the slave is free. He must guarantee the shares of his partners at a fair value because he has affected their partnership, and nothing is due from the slave.”"]}},"tuhfa":{},"refs":[{"key":"kubranasai","label":"النسائي في الكبرى","number":4942,"lafz":true},{"key":"ibnhibban","label":"ابن حبان في صحيحه","number":4317},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4041,"n":4037}],"full":1,"dr":1},{"num":6140,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ أَعْتَقَ نَصِيبًا أَوْ شَقِيصًا فِي مَمْلُوكٍ، فَخَلاَصُهُ عَلَيْهِ فِي مَالِهِ إِنْ كَانَ لَهُ مَالٌ، وَإِلاَّ قُوِّمَ عَلَيْهِ، فَاسْتُسْعِيَ بِهِ غَيْرَ مَشْقُوقٍ عَلَيْهِ."],"takhrij":"متفق عليه: رواه البخـاري في العتق (2527)، ومسلم في العتق (1503: 3)، كلاهما من طريق سعيد بن أبي عروبة، عن قتادة، عن النضر بن أنس، عن بشير بن نهيك، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الاستسعاء","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2527) and Muslim (1503:3). His statement, “or a portion,” means part of him.","chapter_en":"Chapter on the slave being required to earn his freedom","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said: “Whoever frees a share, or a portion, in a slave, then the completion of his freedom is due from his wealth if he has wealth. Otherwise, the slave is fairly valued, and he is required to work to earn his freedom without hardship being imposed on him.”"]},"buhuth":{"en":["The meaning is that if the emancipating partner has sufficient wealth, he must pay the fair value of his co-owner’s share, and the slave becomes fully free. If he does not have sufficient wealth, the slave is fairly valued and required to work toward paying the value of the remaining share, without undue hardship."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2527,"lafz":true},{"key":"muslim","label":"مسلم","number":3},{"key":"muslim","label":"مسلم في العتق","number":1503}],"full":1,"dr":1},{"num":6141,"demo":false,"sanad":"","matn":["عَنْ سَلْمَانَ، قَالَ: كَاتَبْتُ أَهْلِي عَلَى أَنْ أَغْرِسَ لَهُمْ خَمْسَ مِائَةِ فَسِيلَةٍ، فَإِذَا عَلِقَتْ فَأَنَا حُرٌّ، قَالَ: فَأَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرْتُ ذَلِكَ لَهُ قَالَ: اغْرِسْ وَاشْتَرِطْ لَهُمْ، فَإِذَا أَرَدْتَ أَنْ تَغْرِسَ فَآذِنِّي قَالَ: فَآذَنْتُهُ، قَالَ: فَجَاءَ، فَجَعَلَ يَغْرِسُ بِيَدِهِ إِلَّا وَاحِدَةً غَرَسْتُهَا بِيَدَيَّ، فَعَلِقْنَ إِلَّا الْوَاحِدَةَ."],"takhrij":"حسن: رواه أحمد (23730) عن عفان، حدثنا حماد بن سلمة، أخبرنا علي بن زيد، عن أبي عثمان النهدي، عن سلمان فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في إعانة المكاتب","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (23730), al-Hakim (2/217–218), and al-Bayhaqi (10/321).","chapter_en":"Chapter on helping the contract slave","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Salman said: I made a contract with my masters that I would plant five hundred date-palms for them, and when they took root I would be free. He said: I came to the Prophet ﷺ and mentioned that to him. He said, “Plant them, and make the condition for them. When you want to plant them, inform me.” He said: So I informed him. He came and began planting them with his own hand, except for one which I planted with my own hand. They all took root except that one."]},"intro":{"ar":["قال الله عز وجل:","(وَٱلَّذِينَ يَبْتَغُونَ ٱلْكِتَابَ مِمَّا مَلَكَتْ أَيْمَٰنُكُمْ فَكَاتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْرًا) [النور: ٣٣]."],"en":["Allah, Mighty and Majestic, said:","“And those among your slaves who seek a contract of emancipation, then make such a contract with them if you know there is good in them.” [Surah al-Nur, 24:33]"]}},"tuhfa":{},"refs":[{"key":"kubrabayhaqi","label":"البيهقي","number":321},{"key":"ahmad","label":"مسند الإمام أحمد","number":23730,"n":23730,"lafz":true},{"key":"hakim","label":"المستدرك على الصحيحين","number":2862,"n":2848},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":21624,"n":21781}],"full":1,"dr":1},{"num":6142,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ الْمُكَاتَبُ عَبْدٌ مَا بَقِيَ عَلَيْهِ مِنْ مُكَاتَبَتِهِ دِرْهَمٌ.","وفي لفظ: أيما عبد كاتب على مائة أوقية فأداها إلا عشرة أواق، فهو عبد، وأيما عبد كاتب على مائة دينار، فأداها إلا عشرة دنانير، فهو عبد."],"takhrij":"حسن: رواه أبو داود (3926، 3927)، والترمذي (1260)، وابن ماجه (2519)، وأحمد (6666)، والبيهقي (10/324) كلهم من طرق عن عمرو بن شعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب المكاتب لا يزال عبدا ما بقي عليه درهم","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3926, 3927), al-Tirmidhi (1260), Ibn Majah (2519), and Ahmad (6666).","chapter_en":"Chapter that the contract slave remains a slave so long as even one dirham remains unpaid","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["‘Amr ibn Shu‘ayb narrated from his father, from his grandfather, from the Prophet ﷺ that he said: “The contract slave remains a slave as long as even one dirham remains from his contracted amount.” In another wording: “Any slave who contracts for one hundred ounces and pays all but ten ounces is still a slave; and any slave who contracts for one hundred dinars and pays all but ten dinars is still a slave.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3927,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1260},{"key":"ibnmajah","label":"ابن ماجه","number":2519},{"key":"ahmad","label":"مسند الإمام أحمد","number":6666,"n":6726},{"key":"abudawud","label":"ابو داود","number":3926,"n":3927}],"full":1,"dr":1},{"num":6143,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِنَّمَا الْوَلاَءُ لِمَنْ أَعْتَقَ."],"takhrij":"صحيح: رواه البخاري في الفرائض (6752) عن إسماعيل بن عبد الله قال: حدثني مالك، عن نافع، عن عبد الله بن عمر فذكره.","grade":"صحيح","chapter_ar":"باب إنما الولاء لمن أعتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6752).","chapter_en":"Chapter that clientship belongs only to the one who emancipates","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ibn ‘Umar narrated from the Prophet ﷺ that he said: “Clientship belongs only to the one who emancipates.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6752,"lafz":true}],"full":1},{"num":6144,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ عَائِشَةَ أُمَّ الْمُؤْمِنِينَ، أَرَادَتْ أَنْ تَشْتَرِيَ جَارِيَةً تُعْتِقُهَا فَقَالَ أَهْلُهَا نَبِيعُكِهَا عَلَى أَنَّ وَلاَءَهَا لَنَا. فَذَكَرَتْ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لاَ يَمْنَعُكِ ذَلِكِ، فَإِنَّمَا الْوَلاَءُ لِمَنْ أَعْتَقَ."],"takhrij":"متفق عليه: رواه مالك في العتق والولاء (18) عن نافع، عن عبد الله بن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب إنما الولاء لمن أعتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (18), al-Bukhari (2562), and Muslim (1504:5).","chapter_en":"Chapter that clientship belongs only to the one who emancipates","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ibn ‘Umar said: The Mother of the Believers, ‘A’ishah, wanted to buy a slave girl in order to set her free, but her owners said: We will sell her to you on condition that her clientship remains with us. She mentioned that to the Messenger of Allah ﷺ, and he said, “That should not prevent you, for clientship belongs only to the one who emancipates.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":18,"lafz":true},{"key":"bukhari","label":"البخاري","number":2562},{"key":"muslim","label":"مسلم","number":5}],"full":1,"dr":1},{"num":6145,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أنها قَالَتْ: جَاءَتْ بَرِيرَةُ، فَقَالَتْ: إِنِّي كَاتَبْتُ أَهْلِي عَلَى تِسْعِ أَوَاقٍ، فِي كُلِّ عَامٍ أُوقِيَّةٌ، فَأَعِينِينِي، فَقَالَتْ عَائِشَةُ: إِنْ أحب أهلك أَنْ أَعُدَّهَا لَهُمْ عنك عددتها، وَيَكُونَ لِي وَلاَؤُكِ، فَعَلْتُ. فَذَهَبَتْ بَرِيرَةُ إِلَى أَهْلِهَا، فَقَالَتْ لَهُمْ ذَلِكَ، فَأَبَوْا عَلَيْهَا، فَجَاءَتْ مِنْ عِنْدِ أَهْلِهَا وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسٌ، فَقَالَتْ لِعَائِشَةَ: إِنِّي قَدْ عَرَضْتُ عَلَيْهِمْ ذَلِكَ، فَأَبَوْا علي إِلاَّ أَنْ يَكُونَ الْوَلاَءُ لَهُمْ، فَسَمِعَ ذَلِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فسألها، فأخبرته عَائِشَةُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: خُذِيهَا، وَاشْتَرِطِي لَهُمُ الْوَلاَءَ، فَإِنَّمَا الْوَلاَءُ لِمَنْ أَعْتَقَ. فَفَعَلَتْ عَائِشَةُ، ثُمَّ قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي النَّاسِ، فَحَمِدَ اللَّهَ، وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: أما بَعْدُ، فَمَا بَالُ رِجَالٍ يَشْتَرِطُونَ شُرُوطًا لَيْسَتْ فِي كِتَابِ اللَّهِ، مَا كَانَ مِنْ شَرْطٍ لَيْسَ فِي كِتَابِ اللَّهِ فَهْوَ بَاطِلٌ، وَإِنْ كَانَ مِائَةَ شَرْطٍ، قَضَاءُ اللَّهِ أَحَقُّ، وَشَرْطُ اللَّهِ أَوْثَقُ، وَإِنَّمَا الْوَلاَءُ لِمَنْ أَعْتَقَ."],"takhrij":"متفق عليه: رواه مالك في العتق والولاء (17) عن هشام بن عروة، عن أبيه، عن عائشة فذكرته. ورواه البخاري في الشروط (2729) من طريق مالك، به، مثله. ورواه مسلم في العتق (1504: 8) من طريق أبي أسامة، حدثنا هشام بن عروة، به.","grade":"متفق عليه","chapter_ar":"باب إنما الولاء لمن أعتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (17), al-Bukhari (2729), and Muslim (1504:8).","chapter_en":"Chapter that clientship belongs only to the one who emancipates","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["‘A’ishah, the wife of the Prophet ﷺ, said: Barirah came and said: I have made a contract with my family for nine ounces, one ounce each year, so help me. ‘A’ishah said: If your family would like me to count it out for them on your behalf, and your clientship will be mine, I will do it. So Barirah went to her family and told them that, but they refused. She returned while the Messenger of Allah ﷺ was sitting there and said to ‘A’ishah: I presented that to them, but they refused unless the clientship remains theirs. The Messenger of Allah ﷺ heard that and asked about it, so ‘A’ishah informed him. The Messenger of Allah ﷺ said: “Take her and stipulate clientship for them, for clientship belongs only to the one who emancipates.” So ‘A’ishah did that. Then the Messenger of Allah ﷺ stood before the people, praised Allah and extolled Him, then said: “Now then, what is the matter with people who make conditions not found in the Book of Allah? Any condition that is not in the Book of Allah is invalid, even if it be a hundred conditions. The decree of Allah has more right to be followed, and the condition of Allah is firmer. Clientship belongs only to the one who emancipates.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":17,"lafz":true},{"key":"bukhari","label":"البخاري","number":2729},{"key":"muslim","label":"مسلم","number":8},{"key":"muslim","label":"مسلم في العتق","number":1504}],"full":1},{"num":6146,"demo":false,"sanad":"","matn":["عَنْ عُرْوَةَ، أَنَّ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَخْبَرَتْهُ أَنَّ بَرِيرَةَ جَاءَتْ تَسْتَعِينُهَا فِي كِتَابَتِهَا، وَلَمْ تَكُنْ قَضَتْ مِنْ كِتَابَتِهَا شَيْئًا، قَالَتْ لَهَا عَائِشَةُ ارْجِعِي إِلَى أَهْلِكِ، فَإِنْ أَحَبُّوا أَنْ أَقْضِيَ عَنْكِ كِتَابَتَكِ، وَيَكُونَ وَلاَؤُكِ لِي فَعَلْتُ. فَذَكَرَتْ ذَلِكَ بَرِيرَةُ لأَهْلِهَا فَأَبَوْا وَقَالُوا إِنْ شَاءَتْ أَنْ تَحْتَسِبَ عَلَيْكِ فَلْتَفْعَلْ، وَيَكُونَ وَلاَؤُكِ لَنَا، فَذَكَرَتْ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ابْتَاعِي فَأَعْتِقِي، فَإِنَّمَا الْوَلاَءُ لِمَنْ أَعْتَقَ. قَالَ ثُمَّ قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ مَا بَالُ أُنَاسٍ يَشْتَرِطُونَ شُرُوطًا لَيْسَتْ فِي كِتَابِ اللَّهِ مَنِ اشْتَرَطَ شَرْطًا لَيْسَ فِي كِتَابِ اللَّهِ فَلَيْسَ لَهُ، وَإِنْ شَرَطَ مِائَةَ مَرَّةٍ، شَرْطُ اللَّهِ أَحَقُّ وَأَوْثَقُ."],"takhrij":"متفق عليه: رواه البخاري في المكاتب (2561)، ومسلم في العتق (1504: 6) كلاهما عن قتيبة بن سعيد، حدثنا ليث، عن ابن شهاب، عن عروة أن عائشة أخبرته فذكرته.","grade":"متفق عليه","chapter_ar":"باب إنما الولاء لمن أعتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2561) and Muslim (1504:6).","chapter_en":"Chapter that clientship belongs only to the one who emancipates","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["‘Urwah said: ‘A’ishah told him that Barirah came to ‘A’ishah seeking her help with her contract of emancipation, and she had not yet paid anything of it. ‘A’ishah said to her: Return to your family; if they wish that I settle your contract for you and your clientship be mine, I will do so. Barirah mentioned that to her family, but they refused and said: If she wants to spend it for your sake as charity, let her do that, but your clientship will belong to us. She mentioned that to the Messenger of Allah ﷺ, and the Messenger of Allah ﷺ said to her: “Buy her and free her, for clientship belongs only to the one who emancipates.” Then the Messenger of Allah ﷺ stood and said: “What is the matter with people who stipulate conditions not found in the Book of Allah? Whoever stipulates a condition not found in the Book of Allah has no right to it, even if he stipulates it a hundred times. The condition of Allah is more rightful and more binding.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2561,"lafz":true},{"key":"muslim","label":"مسلم","number":6},{"key":"muslim","label":"مسلم في العتق","number":1504,"n":3777}],"full":1},{"num":6147,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ كَانَ فِي بَرِيرَةَ ثَلاَثُ قَضِيَّاتٍ أَرَادَ أَهْلُهَا أَنْ يَبِيعُوهَا وَيَشْتَرِطُوا وَلاَءَهَا فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ اشْتَرِيهَا وَأَعْتِقِيهَا فَإِنَّ الْوَلاَءَ لِمَنْ أَعْتَقَ.","قالت: وعتقت، فخيرها رسول الله صلى الله عليه وسلم، فاختارت نفسها.","قالت: وكان الناس يتصدقون عليها، وتهدى لنا. فذكرت ذلك للنبيصلى الله عليه وسلم، فقال: هو عليها صدقة، وهو لكم هدية، فكلوه."],"takhrij":"صحيح: رواه مسلم في العتق (1504: 10) من طرق عن أبي معاوية، حدثنا هشام بن عروة، عن عبد الرحمن بن القاسم، عن أبيه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب إنما الولاء لمن أعتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1504:10).","chapter_en":"Chapter that clientship belongs only to the one who emancipates","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["‘A’ishah said: In the case of Barirah there were three rulings. Her owners wanted to sell her while stipulating that her clientship remain theirs, so I mentioned that to the Prophet ﷺ and he said: “Buy her and free her, for clientship belongs to the one who emancipates.” She was then freed, and the Messenger of Allah ﷺ gave her the choice, so she chose herself. She said: People used to give charity to her, and she would give some of it to us as a gift. I mentioned that to the Prophet ﷺ, and he said: “For her it is charity, and for you it is a gift, so eat it.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":10,"lafz":true},{"key":"muslim","label":"مسلم في العتق","number":1504,"n":3781}],"full":1},{"num":6148,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ،. أَنَّهَا اشْتَرَتْ بَرِيرَةَ مِنْ أُنَاسٍ مِنَ الأَنْصَارِ. وَاشْتَرَطُوا الْوَلاَءَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْوَلاَءُ لِمَنْ وَلِيَ النِّعْمَةَ. وَخَيَّرَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَكَانَ زَوْجُهَا عَبْدًا وَأَهْدَتْ لِعَائِشَةَ لَحْمًا فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَوْ صَنَعْتُمْ لَنَا مِنْ هَذَا اللَّحْمِ. قَالَتْ عَائِشَةُ تُصُدِّقَ بِهِ عَلَى بَرِيرَةَ. فَقَالَ هُوَ لَهَا صَدَقَةٌ وَلَنَا هَدِيَّةٌ."],"takhrij":"متفق عليه: رواه مسلم في العتق (1504: 11) عن أبي بكر بن أبى شيبة، حدثنا حسين بن على، عن زائدة، عن سماك، عن عبد الرحمن بن القاسم، عن أبيه، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب إنما الولاء لمن أعتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (1504:11) and al-Bukhari (2578).","chapter_en":"Chapter that clientship belongs only to the one who emancipates","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["‘A’ishah said: She bought Barirah from some of the Ansar, and they stipulated the clientship. The Messenger of Allah ﷺ said: “Clientship belongs to the one who bestowed the favor of emancipation.” The Messenger of Allah ﷺ gave her the choice, and her husband was a slave. Barirah gave meat as a gift to ‘A’ishah, so the Messenger of Allah ﷺ said: “If only you had prepared some of this meat for us.” ‘A’ishah said: It was given in charity to Barirah. He said: “For her it is charity, and for us it is a gift.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":11,"lafz":true},{"key":"bukhari","label":"البخاري","number":2578},{"key":"muslim","label":"مسلم في العتق","number":1504,"n":3782}],"full":1,"dr":1},{"num":6149,"demo":false,"sanad":"","matn":["عن أَيْمَنَ قَالَ دَخَلْتُ عَلَى عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا فَقُلْتُ كُنْتُ غُلاَمًا لِعُتْبَةَ بْنِ أَبِي لَهَبٍ، وَمَاتَ وَوَرِثَنِي بَنُوهُ، وَإِنَّهُمْ بَاعُونِي مِنَ ابْنِ أَبِي عَمْرٍو، فَأَعْتَقَنِي ابْنُ أَبِي عَمْرٍو، وَاشْتَرَطَ بَنُو عُتْبَةَ الْوَلاَءَ. فَقَالَتْ دَخَلَتْ بَرِيرَةُ وَهْىَ مُكَاتَبَةٌ فَقَالَتِ اشْتَرِينِي وَأَعْتِقِينِي. قَالَتْ نَعَمْ. قَالَتْ لاَ يَبِيعُونِي حَتَّى يَشْتَرِطُوا وَلاَئِي. فَقَالَتْ لاَ حَاجَةَ لِي بِذَلِكَ. فَسَمِعَ بِذَلِكَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوْ بَلَغَهُ، فَذَكَرَ لِعَائِشَةَ، فَذَكَرَتْ عَائِشَةُ مَا قَالَتْ لَهَا، فَقَالَ اشْتَرِيهَا وَأَعْتِقِيهَا، وَدَعِيهِمْ يَشْتَرِطُونَ مَا شَاءُوا. فَاشْتَرَتْهَا عَائِشَةُ فَأَعْتَقَتْهَا وَاشْتَرَطَ أَهْلُهَا الْوَلاَءَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْوَلاَءُ لِمَنْ أَعْتَقَ، وَإِنِ اشْتَرَطُوا مِائَةَ شَرْطٍ."],"takhrij":"صحيح: رواه البخاري في المكاتب (2565) عن أبي نعيم، حدثنا عبدالواحد بن أيمن، حدثني أبي أيمن فذكره.","grade":"صحيح","chapter_ar":"باب إنما الولاء لمن أعتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2565).","chapter_en":"Chapter that clientship belongs only to the one who emancipates","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ayman said: I entered upon ‘A’ishah — may Allah be pleased with her — and said: I was a slave of ‘Utbah ibn Abi Lahab. He died, and his sons inherited me. They sold me to Ibn Abi ‘Amr, and Ibn Abi ‘Amr freed me, but the sons of ‘Utbah stipulated clientship. She said: Barirah once came in while she was under a contract of emancipation and said: Buy me and free me. I said: Yes. She said: They will not sell me unless they stipulate my clientship. So I said: I have no need for that. The Prophet ﷺ heard of this, or it reached him, and he mentioned it to ‘A’ishah. ‘A’ishah then told him what she had said to Barirah, so he said: “Buy her and free her, and let them stipulate whatever they wish.” So ‘A’ishah bought her and freed her, and her family stipulated the clientship. The Prophet ﷺ then said: “Clientship belongs to the one who emancipates, even if they stipulate a hundred conditions.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2565,"lafz":true}],"full":1},{"num":6150,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ أَرَادَتْ عَائِشَةُ أَنْ تَشْتَرِيَ، جَارِيَةً تُعْتِقُهَا فَأَبَى أَهْلُهَا إِلاَّ أَنْ يَكُونَ لَهُمُ الْوَلاَءُ فَذَكَرَتْ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لاَ يَمْنَعُكِ ذَلِكِ فَإِنَّمَا الْوَلاَءُ لِمَنْ أَعْتَقَ."],"takhrij":"صحيح: رواه مسلم في العتق (1505) عن أبي بكر بن أبى شيبة، حدثنا خالد بن مخلد، عن سليمان بن بلال، حدثنى سهيل بن أبى صالح، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب إنما الولاء لمن أعتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1505).","chapter_en":"Chapter that clientship belongs only to the one who emancipates","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah said: ‘A’ishah wanted to buy a slave girl in order to free her, but her family refused unless the clientship remained theirs. She mentioned that to the Messenger of Allah ﷺ, and he said: “That should not prevent you, for clientship belongs only to the one who emancipates.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1505,"lafz":true}],"full":1,"rep":[5859]},{"num":6151,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتِ اشْتَرَيْتُ بَرِيرَةَ فَاشْتَرَطَ أَهْلُهَا وَلاَءَهَا، فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ أَعْتِقِيهَا، فَإِنَّ الْوَلاَءَ لِمَنْ أَعْطَى الْوَرِقَ. فَأَعْتَقْتُهَا، فَدَعَاهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَخَيَّرَهَا مِنْ زَوْجِهَا فَقَالَتْ لَوْ أَعْطَانِي كَذَا وَكَذَا مَا ثَبَتُّ عِنْدَهُ. فَاخْتَارَتْ نَفْسَهَا."],"takhrij":"صحيح: رواه البخاري في العتق (2536) عن عثمان بن أبي شيبة، حدثنا جرير، عن منصور، عن إبراهيم، عن الأسود، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب إنما الولاء لمن أعتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2536). In another narration in al-Bukhari (6760), it says: “Clientship belongs to the one who paid the silver and bestowed the favor.”","chapter_en":"Chapter that clientship belongs only to the one who emancipates","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["‘A’ishah said: I bought Barirah, and her family stipulated her clientship. I mentioned that to the Prophet ﷺ and he said: “Free her, for clientship belongs to the one who paid the silver.” So I freed her. Then the Prophet ﷺ called her and gave her the choice regarding her husband. She said: Even if he gave me such-and-such, I would not stay with him, so she chose herself."]},"buhuth":{"en":["His statement, “bestowed the favor,” means: the one who emancipated.","This hadith is evidence that clientship belongs to every emancipator, whether male or female, and this is a matter of scholarly consensus."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2536,"lafz":true},{"key":"bukhari","label":". وفي رواية عند البخاري","number":6760,"n":6758}],"full":1,"dr":1},{"num":6152,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ دِينَارٍ، عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ بَيْعِ الْوَلاَءِ وَعَنْ هِبَتِهِ."],"takhrij":"متفق عليه: رواه مالك في العتق والولاء (20) عن عبد الله بن دينار، عن عبد الله بن عمر فذكره. ورواه البخاري في العتق (2535) من طريق شعبة-، ومسلم في العتق (1506) من طريق سليمان بن بلال، وغيره، كلهم عن عبدالله بن دينار به.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الولاء وهبته","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (20), al-Bukhari (2535), and Muslim (1506).","chapter_en":"Chapter on the prohibition of selling or gifting clientship","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar said: The Messenger of Allah ﷺ forbade selling clientship and forbade gifting it."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":20,"lafz":true,"n":160},{"key":"bukhari","label":"البخاري","number":2535},{"key":"muslim","label":"مسلم","number":1506}],"full":1,"dr":1},{"num":6153,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْوَلَاءُ لُحْمَةٌ كَلُحْمَةِ النَّسَبِ، لَا يُبَاعُ، وَلَا يُوهَبُ."],"takhrij":"صحيح: رواه ابن حبان (4950) عن أبي يعلى قال: قرئ على بشر بن الوليد، عن يعقوب بن إبراهيم، عن عبيدالله بن عمر، عن عبد الله بن دينار، عن ابن عمر فذكره. وإسناده صحيح. ويعقوب بن إبراهيم هو أبو يوسف القاضي، صاحب أبي حنيفة.","grade":"صحيح","chapter_ar":"باب النهي عن بيع الولاء وهبته","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Hibban (4950).","chapter_en":"Chapter on the prohibition of selling or gifting clientship","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ said, “Clientship is a bond like the bond of kinship; it is not to be sold and not to be gifted.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1896,"n":1893},{"key":"ibnhibban","label":"ابن حبان","number":4950,"lafz":true}],"full":1,"dr":1,"rep":[6068]},{"num":6154,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ مَا عِنْدَنَا شَىْءٌ إِلاَّ كِتَابُ اللَّهِ، وَهَذِهِ الصَّحِيفَةُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةُ حَرَمٌ، مَا بَيْنَ عَائِرٍ إِلَى كَذَا، مَنْ أَحْدَثَ فِيهَا حَدَثًا، أَوْ آوَى مُحْدِثًا، فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلاَئِكَةِ وَالنَّاسِ أَجْمَعِينَ، لاَ يُقْبَلُ مِنْهُ صَرْفٌ وَلاَ عَدْلٌ. وَقَالَ ذِمَّةُ الْمُسْلِمِينَ وَاحِدَةٌ، فَمَنْ أَخْفَرَ مُسْلِمًا فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلاَئِكَةِ وَالنَّاسِ أَجْمَعِينَ، لاَ يُقْبَلُ مِنْهُ صَرْفٌ وَلاَ عَدْلٌ، وَمَنْ تَوَلَّى قَوْمًا بِغَيْرِ إِذْنِ مَوَالِيهِ، فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلاَئِكَةِ وَالنَّاسِ أَجْمَعِينَ، لاَ يُقْبَلُ مِنْهُ صَرْفٌ وَلاَ عَدْلٌ."],"takhrij":"متفق عليه: رواه البخاري في فضائل المدينة (1870)، ومسلم في العتق (1370: 20) من طريق الأعمش، عن إبراهيم التيمي، عن أبيه، عن علي فذكره. والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب الترهيب من أن ينتسب العتيق إلى غير مواليه","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1870) and Muslim (1370:20). The wording is that of al-Bukhari.","chapter_en":"Chapter on the stern warning against a freed slave affiliating himself to other than his rightful patrons","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["‘Ali ibn Abi Talib said: We have nothing except the Book of Allah and this document from the Prophet ﷺ: “Madinah is a sanctuary between ‘Air and such-and-such. Whoever introduces an innovation in it or shelters an innovator, upon him is the curse of Allah, the angels, and all people together. No compulsory act nor voluntary ransom will be accepted from him.” And he said: “The protection granted by the Muslims is one. Whoever violates the protection of a Muslim, upon him is the curse of Allah, the angels, and all people together. No compulsory act nor voluntary ransom will be accepted from him. And whoever affiliates himself with a people without the permission of his patrons, upon him is the curse of Allah, the angels, and all people together. No compulsory act nor voluntary ransom will be accepted from him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1870,"lafz":true},{"key":"muslim","label":"مسلم","number":20},{"key":"muslim","label":"مسلم في العتق","number":1370}],"full":1},{"num":6155,"demo":false,"sanad":"","matn":["عن جابر بْنِ عبدالله يَقُولُ كَتَبَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى كُلِّ بَطْنٍ عُقُولَهُ ثُمَّ كَتَبَ أَنَّهُ لاَ يَحِلُّ لِمُسْلِمٍ أَنْ يَتَوَالَى مَوْلَى رَجُلٍ مُسْلِمٍ بِغَيْرِ إِذْنِهِ. ثُمَّ أُخْبِرْتُ أَنَّهُ لَعَنَ فِي صَحِيفَتِهِ مَنْ فَعَلَ ذَلِكَ."],"takhrij":"صحيح: رواه مسلم في العتق (1507) عن محمد بن رافع، حدثنا عبدالرزاق، أخبرنا ابن جريج، أخبرنى أبو الزبير أنه سمع جابرا يقول فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من أن ينتسب العتيق إلى غير مواليه","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1507).","chapter_en":"Chapter on the stern warning against a freed slave affiliating himself to other than his rightful patrons","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The Prophet ﷺ prescribed the blood-money liabilities for every clan, then wrote: “It is not lawful for a Muslim to affiliate himself with the freedman of another Muslim without his permission.” Then I was informed that he cursed in his written document whoever does that."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1507,"lafz":true}],"full":1,"rep":[8701]},{"num":6156,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ تَوَلَّى قَوْمًا بِغَيْرِ إِذْنِ مَوَالِيهِ فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلاَئِكَةِ لاَ يُقْبَلُ مِنْهُ عَدْلٌ وَلاَ صَرْفٌ."],"takhrij":"صحيح: رواه مسلم في العتق (1508: 18) عن قتيبة بن سعيد، حدثنا يعقوب بن عبد الرحمن القاري، عن سهيل، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من أن ينتسب العتيق إلى غير مواليه","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1508:18).","chapter_en":"Chapter on the stern warning against a freed slave affiliating himself to other than his rightful patrons","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever affiliates himself with a people without the permission of his patrons, upon him is the curse of Allah and the angels. No voluntary ransom nor obligatory compensation will be accepted from him.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":18,"lafz":true},{"key":"muslim","label":"مسلم في العتق","number":1508}],"full":1},{"num":6157,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ رَجُلاً، مِنَ الأَنْصَارِ أَعْتَقَ غُلاَمًا لَهُ عَنْ دُبُرٍ لَمْ يَكُنْ لَهُ مَالٌ غَيْرُهُ فَبَلَغَ ذَلِكَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ مَنْ يَشْتَرِيهِ مِنِّي. فَاشْتَرَاهُ نُعَيْمُ بْنُ عَبْدِ اللَّهِ بِثَمَانِمِائَةِ دِرْهَمٍ فَدَفَعَهَا إِلَيْهِ.","قال عمرو: سمعت جابر بن عبدالله يقول: عبدا قبطيا مات عام أول."],"takhrij":"متفق عليه: رواه البخاري في العتق (2534) من طريق شعبة-، ومسلم في الأيمان والنذزر (997: 58) من طريق حماد بن زيد- كلاهما عن عمرو بن دينار، عن جابر بن عبد الله فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في بيع المدبر","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2534) and Muslim (997:58). The wording is that of Muslim.","chapter_en":"Chapter on selling a slave whose freedom is tied to the owner’s death","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: A man from the Ansar declared that his slave would be free after his death, and he had no wealth other than him. That reached the Prophet ﷺ, so he said: “Who will buy him from me?” Nu‘aym ibn ‘Abd Allah bought him for eight hundred dirhams, and he handed the money to the man. ‘Amr said: I heard Jabir ibn ‘Abd Allah say: He was a Coptic slave who died the previous year."]},"buhuth":{"en":["His statement, “after his death,” means that he made the slave’s freedom conditional upon his death, because death comes at the end of life."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2534,"lafz":true},{"key":"muslim","label":"مسلم","number":58},{"key":"muslim","label":"مسلم في الايمان والنذزر","number":997,"n":4338}],"full":1,"dr":1},{"num":6158,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ أَعْتَقَ رَجُلٌ مِنْ بَنِي عُذْرَةَ عَبْدًا لَهُ عَنْ دُبُرٍ، فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ أَلَكَ مَالٌ غَيْرُهُ. فَقَالَ لاَ. فَقَالَ مَنْ يَشْتَرِيهِ مِنِّي. فَاشْتَرَاهُ نُعَيْمُ بْنُ عَبْدِ اللَّهِ الْعَدَوِيُّ بِثَمَانِمِائَةِ دِرْهَمٍ فَجَاءَ بِهَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَدَفَعَهَا إِلَيْهِ ثُمَّ قَالَ ابْدَأْ بِنَفْسِكَ فَتَصَدَّقْ عَلَيْهَا فَإِنْ فَضَلَ شَىْءٌ فَلأَهْلِكَ فَإِنْ فَضَلَ عَنْ أَهْلِكَ شَىْءٌ فَلِذِي قَرَابَتِكَ فَإِنْ فَضَلَ عَنْ ذِي قَرَابَتِكَ شَىْءٌ فَهَكَذَا وَهَكَذَا. يَقُولُ فَبَيْنَ يَدَيْكَ وَعَنْ يَمِينِكَ وَعَنْ شِمَالِكَ."],"takhrij":"متفق عليه: رواه مسلم في الزكاة (997) عن قتيبة بن سعيد، عن الليث، عن أبى الزبير، عن جابر فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في بيع المدبر","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (997), with al-Bukhari (2534) reporting the core incident.","chapter_en":"Chapter on selling a slave whose freedom is tied to the owner’s death","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Jabir said: A man from Banu ‘Udhrah declared his slave free after his death. That reached the Messenger of Allah ﷺ, so he said: “Do you have any wealth besides him?” He said: No. He said: “Who will buy him from me?” Nu‘aym ibn ‘Abd Allah al-‘Adawi bought him for eight hundred dirhams. The Messenger of Allah ﷺ brought the money and handed it to him, then said: “Begin with yourself and spend in charity on it. If anything remains, then it is for your family. If anything remains beyond your family, then for your relatives. If anything remains beyond your relatives, then like this and like this,” meaning in front of you, to your right, and to your left."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":997,"lafz":true},{"key":"bukhari","label":"البخاري","number":2534},{"key":"sh13075","label":"النفقة على العيال لابن أبي الدنيا","number":10,"n":9}],"full":1,"dr":1},{"num":6159,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ يَقُولُ كُنَّا نَبِيعُ سَرَارِينَا وَأُمَّهَاتِ أَوْلاَدِنَا وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِينَا حَىٌّ لاَ نَرَى بِذَلِكَ بَأْسًا."],"takhrij":"صحيح: رواه عبدالرزاق (13211)، وعنه أحمد (14446)، وابن ماجه (2517)، وابن حبان (4323)، والدارقطني (4/135)، والبيهقي (10/348) كلهم عن ابن جريج قال: أخبرني أبو الزبير، أنه سمع جابر بن عبد الله يقول فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب بيع أمهات الأولاد","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by ‘Abd al-Razzaq (13211), from him Ahmad (14446), Ibn Majah (2517), and Ibn Hibban (4323).","chapter_en":"Chapter on selling slave mothers who bore children","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: We used to sell our slave women and the slave mothers of our children while the Prophet ﷺ was among us, and we saw no harm in that."]},"buhuth":{"en":["Abu Dawud (3950) also narrated it through another route from Jabir ibn ‘Abd Allah, who said: We sold slave mothers during the time of the Messenger of Allah ﷺ and Abu Bakr, but when ‘Umar came, he forbade us, so we stopped."]}},"tuhfa":{},"refs":[{"key":"abdrazzaq","label":"عبدالرزاق","number":13211,"lafz":true},{"key":"ahmad","label":"عنه أحمد","number":14446},{"key":"ibnmajah","label":"ابن ماجه","number":2517},{"key":"ibnhibban","label":"ابن حبان","number":4323}],"full":1,"dr":1},{"num":6160,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: كُنَّا نَبِيعُ أُمَّهَاتِ الأَوْلَادِ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبِي بَكْرٍ، فَلَمَّا كَانَ عُمَرُ نَهَى عَنْ بَيْعِهِنَّ."],"takhrij":"صحيح: رواه أبو داود (3954)، وابن حبان (4324)، والحاكم (2/18-19)، والبيهقي (10/347) كلهم من طرق عن حماد بن سلمة، عن قيس بن سعد، عن عطاء بن أبي رباح، عن جابر فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء أن عمر بن الخطاب هو الذي نهى عن بيع أمهات الأولاد","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3954), Ibn Hibban (4324), al-Hakim (2190), and al-Bayhaqi (10/347).","chapter_en":"Chapter stating that ‘Umar ibn al-Khattab was the one who forbade selling slave mothers","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: We used to sell slave mothers during the time of the Messenger of Allah ﷺ and Abu Bakr. Then when ‘Umar came, he forbade selling them."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3954,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":10},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":5968,"n":5965},{"key":"hakim","label":"المستدرك على الصحيحين","number":2190,"n":2182},{"key":"ibnhibban","label":"ابن حبان","number":4324}],"full":1,"dr":1},{"num":6161,"demo":false,"sanad":"","matn":["عن حَكِيمِ بْنِ حِزَامٍ رَضِيَ اللَّهُ عَنْهُ أَعْتَقَ فِي الْجَاهِلِيَّةِ مِائَةَ رَقَبَةٍ، وَحَمَلَ عَلَى مِائَةِ بَعِيرٍ، فَلَمَّا أَسْلَمَ حَمَلَ عَلَى مِائَةِ بَعِيرٍ وَأَعْتَقَ مِائَةَ رَقَبَةٍ، قَالَ فَسَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ يَا رَسُولَ اللَّهِ، أَرَأَيْتَ أَشْيَاءَ كُنْتُ أَصْنَعُهَا فِي الْجَاهِلِيَّةِ، كُنْتُ أَتَحَنَّثُ بِهَا، يَعْنِي أَتَبَرَّرُ بِهَا، قَالَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَسْلَمْتَ عَلَى مَا سَلَفَ لَكَ مِنْ خَيْرٍ."],"takhrij":"متفق عليه: رواه البخاري في العتق (2538)، ومسلم في الإيمان (123: 195) كلاهما من طريق هشام بن عروة، عن أبيه، عن حكيم بن حزام فذكره، والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب من أعتق في الجاهلية، ثم أسلم","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2538) and Muslim (123:195). The wording here is that of al-Bukhari.","chapter_en":"Chapter on one who freed slaves in the pre-Islamic period, then accepted Islam","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Hakim ibn Hizam reported that he freed one hundred slaves in the pre-Islamic period and provided one hundred camels for riding. Then when he accepted Islam, he again provided one hundred camels and freed one hundred slaves. He said: So I asked the Messenger of Allah ﷺ and said: O Messenger of Allah ﷺ, what do you think of things I used to do in the pre-Islamic period by which I sought devotion, meaning acts of righteousness? The Messenger of Allah ﷺ said: “You accepted Islam upon the good that had already passed for you.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2538,"lafz":true},{"key":"muslim","label":"مسلم","number":195},{"key":"muslim","label":"مسلم في الايمان","number":123}],"full":1,"dr":1},{"num":6162,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ بَنِي الْمُصْطَلِقِ، فَأَصَبْنَا سَبْيًا مِنْ سبي الْعَرَبِ، فَاشْتَهَيْنَا النِّسَاءَ، وَاشْتَدَّتْ عَلَيْنَا الْعُزْبَةُ، وَأَحْبَبْنَا الفداء، فَأَرَدْنَا أَنْ نَعْزِلَ، فَقُلْنَا: نَعْزِلُ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ أَظْهُرِنَا قَبْلَ أَنْ نَسْأَلَهُ، فَسَأَلْنَاهُ عَنْ ذَلِكَ، فَقَالَ: مَا عَلَيْكُمْ أَنْ لاَ تَفْعَلُوا، مَا مِنْ نَسَمَةٍ كَائِنَةٍ إِلَى يَوْمِ الْقِيَامَةِ إِلاَّ وَهِيَ كَائِنَةٌ."],"takhrij":"متفق عليه: رواه مالك في الطلاق (95) عن ربيعة بن أبي عبد الرحمن، عن محمد بن يحيى بن حَبَّان، عن ابن مُحَيريز أنه قال: دخلت المسجد، فرأيت أبا سعيد الخدري، فجلست إليه، فسألته عن العزل، فقال أبو سعيد الخدري فذكره. ورواه البخاري في العتق (2542)، ومسلم في النكاح (1438: 127) كلاهما من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب اتخاذ الرقيق من العرب","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (95), al-Bukhari (2542), and Muslim (1438:127).","chapter_en":"Chapter on taking slaves from among the Arabs","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: We went out with the Messenger of Allah ﷺ on the expedition of Banu al-Mustaliq, and we captured some Arab prisoners. We desired women, celibacy had become difficult for us, and we wanted ransom money, so we intended to practice withdrawal. Then we said: Shall we practice withdrawal while the Messenger of Allah ﷺ is among us before asking him? So we asked him about that, and he said: “There is no blame upon you if you do not do it. No soul that is to exist until the Day of Resurrection except that it will surely come into existence.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":95,"lafz":true},{"key":"bukhari","label":"البخاري","number":2542},{"key":"muslim","label":"مسلم","number":127},{"key":"muslim","label":"مسلم في النكاح","number":1438}],"full":1,"dr":1},{"num":6163,"demo":false,"sanad":"","matn":["عن ابْنِ عَوْنٍ قَالَ كَتَبْتُ إِلَى نَافِعٍ فَكَتَبَ إِلَىَّ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَغَارَ عَلَى بَنِي الْمُصْطَلِقِ وَهُمْ غَارُّونَ وَأَنْعَامُهُمْ تُسْقَى عَلَى الْمَاءِ، فَقَتَلَ مُقَاتِلَتَهُمْ، وَسَبَى ذَرَارِيَّهُمْ، وَأَصَابَ يَوْمَئِذٍ جُوَيْرِيَةَ. حَدَّثَنِي بِهِ عَبْدُ اللَّهِ بْنُ عُمَرَ، وَكَانَ فِي ذَلِكَ الْجَيْشِ."],"takhrij":"متفق عليه: رواه البخاري في العتق (2541) من طريق عبد الله بن المبارك-، ومسلم في الجهاد والسير (1730) من طريق سليم بن أخضر-، كلاهما عن ابن عون قال فذكره. والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب اتخاذ الرقيق من العرب","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2541) and Muslim (1730). The wording here is that of al-Bukhari.","chapter_en":"Chapter on taking slaves from among the Arabs","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Ibn ‘Awn said: I wrote to Nafi‘, and he wrote back to me that the Prophet ﷺ raided Banu al-Mustaliq while they were heedless and their livestock were being watered at the water source. He killed their fighters, took their children captive, and Juwayriyyah was taken that day. ‘Abd Allah ibn ‘Umar told me this, and he was in that army."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2541,"lafz":true},{"key":"muslim","label":"مسلم","number":1730}],"full":1},{"num":6164,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ لَمَّا أَقْبَلَ يُرِيدُ الإِسْلاَمَ وَمَعَهُ غُلاَمُهُ، ضَلَّ كُلُّ وَاحِدٍ مِنْهُمَا مِنْ صَاحِبِهِ، فَأَقْبَلَ بَعْدَ ذَلِكَ وَأَبُو هُرَيْرَةَ جَالِسٌ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَا أَبَا هُرَيْرَةَ، هَذَا غُلاَمُكَ قَدْ أَتَاكَ. فَقَالَ أَمَا إِنِّي أُشْهِدُكَ أَنَّهُ حُرٌّ. قَالَ فَهُوَ حِينَ يَقُولُ يَا لَيْلَةً مِنْ طُولِهَا وَعَنَائِهَا عَلَى أَنَّهَا مِنْ دَارَةِ الْكُفْرِ نَجَّتِ."],"takhrij":"صحيح: رواه البخاري في العتق (2530) عن محمد بن عبد الله بن نمير، عن محمد بن بشر، عن إسماعيل، عن قيس، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب الإشهاد في العتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2530).","chapter_en":"Chapter on having witnesses for emancipation","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Abu Hurayrah reported that when he was coming to accept Islam, and his servant was with him, each of them lost the other. Later the servant came while Abu Hurayrah was sitting with the Prophet ﷺ, and the Prophet ﷺ said: “O Abu Hurayrah, this is your servant; he has come to you.” So he said: I make you my witness that he is free. Then he began reciting: “What a night of its length and hardship, yet it has been saved from the abode of disbelief.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2530,"lafz":true}],"full":1},{"num":6165,"demo":false,"sanad":"","matn":["عن جرير بن عبد الله البجلي قال: قال رسول الله صلى الله عليه وسلم: أيما عبد أبق من مواليه فقد كفر حتى يرجع إليهم.","وفي لفظ: أيما عبد أبق فقد برئت منه الذمة.","وفي لفظ آخر: إذا أبق العبد لم تقبل له صلاة."],"takhrij":"صحيح: رواه مسلم في الإيمان (68) من طريق إسماعيل ابن علية، عن منصور بن عبد الرحمن، عن الشعبي، عن جرير فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الوعيد الشديد في العبد الآبق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (68). The second wording is also in Muslim (69), and the last wording is likewise in Muslim (70).","chapter_en":"Chapter on the severe warning concerning the runaway slave","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["Jarir ibn ‘Abd Allah al-Bajali reported that the Messenger of Allah ﷺ said: “Any slave who runs away from his masters has committed disbelief until he returns to them.” In another wording: “Any slave who runs away is free of protection.” In yet another wording: “When a slave runs away, his prayer is not accepted.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":68,"lafz":true},{"key":"muslim","label":"اللفظ الثاني عنده","number":69},{"key":"اللفظ_الاخیر_عندہ_ایضا","label":"اللفظ الأخير عنده أيضا","number":70}],"full":1,"dr":1},{"num":6166,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَدُ الزِّنَا شَرُّ الثَّلاَثَةِ. وَقَالَ أَبُو هُرَيْرَةَ لأَنْ أُمَتِّعَ بِسَوْطٍ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ أَحَبُّ إِلَىَّ مِنْ أَنْ أَعْتِقَ وَلَدَ زِنْيَةٍ."],"takhrij":"صحيح: رواه أبو داود (3963) عن إبراهيم بن موسى، أخبرنا جرير، عن سهيل بن أبي صالح، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب عتق ولد الزنا","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3963), Ahmad (8098), al-Hakim (2/214), and al-Bayhaqi (10/57, 59).","chapter_en":"Chapter on freeing the child of fornication","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “The child of fornication is the worst of the three.” Abu Hurayrah said: That I provide a whip for use in the path of Allah is more beloved to me than that I free a child born of fornication."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3963,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":10},{"key":"ahmad","label":"مسند الإمام أحمد","number":8098,"n":8098},{"key":"hakim","label":"المستدرك على الصحيحين","number":2853,"n":2839},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":19991,"n":20149}],"full":1,"dr":1},{"num":6167,"demo":false,"sanad":"","matn":["عَنْ أَبِي حَبِيبَةَ الطَّائِيِّ، قَالَ أَوْصَى إِلَىَّ أَخِي بِطَائِفَةٍ مِنْ مَالِهِ فَلَقِيتُ أَبَا الدَّرْدَاءِ فَقُلْتُ إِنَّ أَخِي أَوْصَى إِلَىَّ بِطَائِفَةٍ مِنْ مَالِهِ فَأَيْنَ تَرَى لِي وَضْعَهُ فِي الْفُقَرَاءِ أَوِ الْمَسَاكِينِ أَوِ الْمُجَاهِدِينَ فِي سَبِيلِ اللَّهِ فَقَالَ أَمَّا أَنَا فَلَوْ كُنْتُ لَمْ أَعْدِلْ بِالْمُجَاهِدِينَ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ مَثَلُ الَّذِي يُعْتِقُ عِنْدَ الْمَوْتِ كَمَثَلِ الَّذِي يُهْدِي إِذَا شَبِعَ."],"takhrij":"حسن: رواه أبو داود (3968)، والترمذي (2123)، والنسائي (6/238)، وأحمد (21718، 21719)،وصحّحه ابن حبان (3336)، والحاكم (2/213)، والبيهقي (10/273) كلهم من طرق عن أبي إسحاق، عن أبي حُبيبة الطائي فذكره. ومنهم من اختصره بدون القصة.","grade":"حسن","chapter_ar":"باب فضل العتق في الصحة","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3968), al-Tirmidhi (2123), al-Nasa’i (6/238), and Ahmad (21718, 21719).","chapter_en":"Chapter on the virtue of freeing slaves while one is healthy","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":20,"content":{"translation":{"en":["Abu Habibah al-Ta’i said: My brother entrusted me with disposing of part of his wealth, so I met Abu al-Darda’ and said: My brother entrusted me with part of his wealth; where do you think I should place it: among the poor, the needy, or the fighters in the path of Allah? He said: As for me, if it were my choice, I would not prefer anyone over the fighters in the path of Allah. I heard the Messenger of Allah ﷺ say: “The one who frees a slave at the time of death is like one who gives a gift after becoming full.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3968,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":2123},{"key":"nasai","label":"النسائي","number":6},{"key":"ahmad","label":"مسند الإمام أحمد","number":21718,"n":21719},{"key":"ahmad","label":"احمد","number":21719},{"key":"ibnhibban","label":"ابن حبان","number":3336}],"full":1,"dr":1},{"num":6168,"demo":false,"sanad":"","matn":["عَنْ سَفِينَةَ أَبِي عَبْدِ الرَّحْمَنِ، قَالَ أَعْتَقَتْنِي أُمُّ سَلَمَةَ وَاشْتَرَطَتْ عَلَىَّ أَنْ أَخْدُمَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا عَاشَ."],"takhrij":"حسن: رواه أبو داود (3932)، وابن ماجه (2526)، وأحمد (21927)، والحاكم (2/213-214)، والبيهقي (10/291) كلهم من طرق عن سعيد بن جمهان، عن سفينة فذكره. قال الحاكم\" صحيح الإسناد\".","grade":"حسن","chapter_ar":"باب من أعتق عبدا واشترط خدمته","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3932), Ibn Majah (2526), Ahmad (21927), and al-Hakim (2/213–214).","chapter_en":"Chapter on one who frees a slave and stipulates his service","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Safinah Abu ‘Abd al-Rahman said: Umm Salamah freed me, but stipulated that I would serve the Prophet ﷺ as long as he lived."]},"buhuth":{"en":["Conditions are of two kinds:","A condition that the slave would fulfill whether it was stipulated or not. It is reported from Safinah that he said: I was owned by Umm Salamah, and she said: I free you, but I stipulate that you serve the Messenger of Allah ﷺ as long as you live. So I said: Even if you did not make that condition upon me, I would never leave the Messenger of Allah ﷺ as long as I lived. So she freed me.","And a condition that conflicts with the freedom of the slave, such as stipulating that he must pay a certain amount of money every month for life, or that he may not marry. This is an invalid condition whether he accepts it or not. Once freedom is declared, he becomes free immediately, and he is not required to fulfill such a condition, because the basic rule regarding a human being is freedom. (See Sharh al-Sunnah, 9/77)."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3932,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2526},{"key":"ahmad","label":"مسند الإمام أحمد","number":21927,"n":21927},{"key":"hakim","label":"المستدرك على الصحيحين","number":6549,"n":6547}],"full":1,"dr":1},{"num":6169,"demo":false,"sanad":"","matn":["عَنْ زَاذَانَ أَبِي عُمَرَ، قَالَ أَتَيْتُ ابْنَ عُمَرَ وَقَدْ أَعْتَقَ مَمْلُوكًا - قَالَ - فَأَخَذَ مِنَ الأَرْضِ عُودًا أَوْ شَيْئًا فَقَالَ مَا فِيهِ مِنَ الأَجْرِ مَا يَسْوَى هَذَا إِلاَّ أَنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ مَنْ لَطَمَ مَمْلُوكَهُ أَوْ ضَرَبَهُ فَكَفَّارَتُهُ أَنْ يُعْتِقَهُ."],"takhrij":"صحيح: رواه مسلم في النذر (1657) عن أبي كامل فضيل بن حسين الجحدرى، حدثنا أبو عوانة، عن فراس، عن ذكوان أبى صالح، عن زاذان فذكره.ورواه شعبة عن فراس، وقال فيه: من ضرب غلاما له حدا لم يأته.","grade":"صحيح","chapter_ar":"باب كفارة من ظلم غلامه أن يعتقه","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1657).","chapter_en":"Chapter that the expiation for one who wrongs his servant is to free him","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Zadhan Abu ‘Umar said: I came to Ibn ‘Umar after he had freed a slave. He picked up a twig or something from the ground and said: The reward in it does not equal even this, except that I heard the Messenger of Allah ﷺ say: “Whoever slaps his slave or beats him, then the expiation for that is to free him.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1657,"lafz":true}],"full":1,"rep":[14006]},{"num":6170,"demo":false,"sanad":"","matn":["عَنْ مُعَاوِيَةَ بْنِ سُوَيْدٍ، قَالَ لَطَمْتُ مَوْلًى لَنَا فَهَرَبْتُ ثُمَّ جِئْتُ قُبَيْلَ الظُّهْرِ فَصَلَّيْتُ خَلْفَ أَبِي فَدَعَاهُ وَدَعَانِي ثُمَّ قَالَ امْتَثِلْ مِنْهُ. فَعَفَا ثُمَّ قَالَ كُنَّا بَنِي مُقَرِّنٍ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْسَ لَنَا إِلاَّ خَادِمٌ وَاحِدَةٌ فَلَطَمَهَا أَحَدُنَا فَبَلَغَ ذَلِكَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ أَعْتِقُوهَا. قَالُوا لَيْسَ لَهُمْ خَادِمٌ غَيْرُهَا قَالَ فَلْيَسْتَخْدِمُوهَا فَإِذَا اسْتَغْنَوْا عَنْهَا فَلْيُخَلُّوا سَبِيلَهَا."],"takhrij":"صحيح: رواه مسلم في النذر (1658) من طرق عن عبد الله بن نمير، حدثنا سفيان، عن سلمة بن كهيل، عن معاوية بن سويد فذكره.","grade":"صحيح","chapter_ar":"باب كفارة من ظلم غلامه أن يعتقه","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1658).","chapter_en":"Chapter that the expiation for one who wrongs his servant is to free him","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Mu‘awiyah ibn Suwayd said: I slapped a servant of ours, so I fled. Then I returned shortly before noon and prayed behind my father. He called him and called me, then said: Let him retaliate against you. But the servant forgave me. Then he said: We, the family of Muqarrin, only had one servant during the time of the Messenger of Allah ﷺ, and one of us slapped her. That reached the Prophet ﷺ, so he said: “Free her.” They said: They have no servant besides her. He said: “Then let them employ her, and when they no longer need her, let them set her free.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1658,"lafz":true}],"full":1,"dr":1,"rep":[14009]},{"num":6171,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَسْعُودٍ الأَنْصَارِيِّ، قَالَ كُنْتُ أَضْرِبُ غُلاَمًا لِي فَسَمِعْتُ مِنْ خَلْفِي صَوْتًا اعْلَمْ أَبَا مَسْعُودٍ لَلَّهُ أَقْدَرُ عَلَيْكَ مِنْكَ عَلَيْهِ. فَالْتَفَتُّ فَإِذَا هُوَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ يَا رَسُولَ اللَّهِ هُوَ حُرٌّ لِوَجْهِ اللَّهِ. فَقَالَ أَمَا لَوْ لَمْ تَفْعَلْ لَلَفَحَتْكَ النَّارُ أَوْ لَمَسَّتْكَ النَّارُ."],"takhrij":"صحيح: رواه مسلم في النذر (1659: 35) عن أبي كريب محمد بن العلاء، حدثنا أبو معاوية، حدثنا الأعمش، عن إبراهيم التيمي، عن أبيه، عن أبي مسعود فذكره.","grade":"صحيح","chapter_ar":"باب كفارة من ظلم غلامه أن يعتقه","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1659:35). In another narration: “Know, O Abu Mas‘ud, Allah has more power over you than you have over this servant.”","chapter_en":"Chapter that the expiation for one who wrongs his servant is to free him","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Abu Mas‘ud al-Ansari said: I was beating a servant of mine when I heard a voice from behind me saying: “Know, O Abu Mas‘ud, Allah has more power over you than you have over him.” I turned and it was the Messenger of Allah ﷺ. So I said: O Messenger of Allah ﷺ, he is free for the sake of Allah. He said: “Had you not done so, the Fire would have scorched you,” or, “the Fire would have touched you.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":35,"lafz":true},{"key":"muslim","label":"مسلم في النذر","number":1659,"n":4308}],"full":1,"dr":1,"rep":[14007]},{"num":6172,"demo":false,"sanad":"","matn":["عن عَمْرِو بْنِ شُعَيْبٍ عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَارِخًا فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا لَكَ. قَالَ سَيِّدِي رَآنِي أُقَبِّلُ جَارِيَةً لَهُ فَجَبَّ مَذَاكِيرِي. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَىَّ بِالرَّجُلِ. فَطُلِبَ فَلَمْ يُقْدَرْ عَلَيْهِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اذْهَبْ فَأَنْتَ حُرٌّ. قَالَ عَلَى مَنْ نُصْرَتِي يَا رَسُولَ اللَّهِ قَالَ يَقُولُ أَرَأَيْتَ إِنِ اسْتَرَقَّنِي مَوْلاَىَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى كُلِّ مُؤْمِنٍ أَوْ مُسْلِمٍ."],"takhrij":"حسن: رواه أبو داود (4519)، وابن ماجه (2680) كلاهما من حديث أبي حمزة الصيرفي قال: حدثني عمرو بن شعيب بإسناده فذكره.","grade":"حسن","chapter_ar":"باب كفارة من ظلم غلامه أن يعتقه","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4519) and Ibn Majah (2680).","chapter_en":"Chapter that the expiation for one who wrongs his servant is to free him","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["‘Amr ibn Shu‘ayb narrated from his father, from his grandfather: A man came to the Prophet ﷺ shouting. The Messenger of Allah ﷺ said to him: “What is the matter with you?” He said: My master saw me kissing a slave-girl of his, so he cut off my private parts. The Prophet ﷺ said: “Bring me the man.” They searched for him but could not find him. So the Messenger of Allah ﷺ said: “Go, for you are free.” He said: Upon whom is my support, O Messenger of Allah ﷺ? He meant: What if my master enslaves me again? The Messenger of Allah ﷺ said: “Upon every believer,” or, “every Muslim.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4519,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2680}],"full":1,"dr":1},{"num":6173,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ أَعْتَقَ عَبْدًا وَلَهُ مَالٌ فَمَالُ الْعَبْدِ لَهُ إِلاَّ أَنْ يَشْتَرِطَ السَّيِّدُ مَالَهُ فَيَكُونَ لَهُ."],"takhrij":"صحيح: رواه أبو داود (3962) من حديث عبدالله بن وهب، أخبرني ابن لهيعة، والليث بن سعد، عن عبيدالله بن أبي جعفر، عن بكير بن الأشج، عن نافع، عن ابن عمر فذكره. ورواه ابن ماجه (2529) من طريق ابن وهب، عن ابن لهيعة، ومن طريق سعيد بن أبي مريم، عن الليث، كلاهما عن عبيد الله بن أبي جعفر به.","grade":"صحيح","chapter_ar":"باب من أعتق عبدا وله مال","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3962) and Ibn Majah (2529).","chapter_en":"Chapter on one who frees a slave who owns property","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":23,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ said: “Whoever frees a slave who owns property, then the property of the slave belongs to the slave, unless the master stipulates his property, in which case it belongs to him.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3962},{"key":"ibnmajah","label":"ابن ماجه","number":2529,"lafz":true}],"full":1,"dr":1},{"num":6174,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْحَمْدَ لِلَّهِ نَحْمَدُهُ وَنَسْتَعِينُهُ ونعوذ بالله من شرور أنفسنا، وَمَنْ سيئات أعمالنا، مَنْ يَهْدِهِ اللَّهُ فَلاَ مُضِلَّ لَهُ، وَمَنْ يُضْلِلْ فَلاَ هَادِيَ لَهُ، وَأَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، أَمَّا بَعْدُ:."],"takhrij":"صحيح: رواه مسلم في الجمعة (868) من طرق عن عبد الأعلى (وهو أبو همام)، حدثنا داود (بن أبي هند) عن عمرو بن سعيد، عن سعيد بن جبير، عن ابن عباس فذكره، وفيه قصة.","grade":"صحيح","chapter_ar":"باب خطبة النكاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (868).","chapter_en":"Chapter on the marriage sermon","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Ibn ‘Abbas reported that the Prophet ﷺ said: “All praise is for Allah. We praise Him and seek His help. Whomever Allah guides, none can misguide; and whomever He leaves astray, none can guide. I bear witness that there is no god except Allah alone, without partner, and that Muhammad is His servant and His Messenger. To proceed:”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":868,"lafz":true}],"full":1},{"num":6175,"demo":false,"sanad":"","matn":["عن عبدالله بن مسعود قال: أوتي رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جوامع الخير، وخواتمه، أو قال فواتح الخير، فعلمنا خطبة الصلاة وخطبة الحاجة، خطبة الصلاة: التحيات الله والصلوات والطيبات، السلام عليك أيها النبي ورحمة الله وبركاته. السلام علينا وعلى عباد الله الصالحين، أشهد أن لا إله إلا الله وأشهد أن محمدًا عبده ورسوله، وخطبة الحاجة: أن الحمد لله نحمده ونستعينه ونستغفره ونعوذ بالله من شرور أنفسنا ومن سيئات أعمالنا، من يهده الله فلا مضل له، ومن يضلل فلا هادي له، وأشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أن محمدا عبده ورسوله، ثم تصل خطبتك بثلاث آيات من كتاب الله ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ وَلَا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ﴾ [آل عمران: ١٠٢] ﴿يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَاءً وَاتَّقُوا اللَّهَ الَّذِي تَسَاءَلُونَ بِهِ وَالْأَرْحَامَ إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا﴾ [النساء:١] ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَقُولُوا قَوْلًا سَدِيدًا (70) يُصْلِحْ لَكُمْ أَعْمَالَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ﴾ [ الأحزاب: 70-71 ]"],"takhrij":"صحيح: رواه أبو داود (2118)، والترمذي (1105) والنسائي (3277) وابن ماجه (1892) كلهم من طرق عن أبي إسحاق، عن أبي الأحوص، عن عبدالله بن مسعود فذكره.","grade":"صحيح","chapter_ar":"باب خطبة النكاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (2118), al-Tirmidhī (1105), who graded it Hasan, al-Nasāʾī (3277), and Ibn Mājah (1892).","chapter_en":"Chapter on the marriage sermon","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Ibn Masʿūd reported: The Messenger of Allah ﷺ was given comprehensive expressions of goodness and their conclusions—or he said, their beginnings. He taught us the tashahhud of prayer and the sermon of need. The tashahhud of prayer is: “All greetings are for Allah, as are the prayers and all good things. Peace be upon you, O Prophet, and the mercy of Allah and His blessings. Peace be upon us and upon the righteous servants of Allah. I bear witness that there is no god except Allah, and I bear witness that Muhammad is His servant and Messenger.” The sermon of need is: “Indeed, all praise belongs to Allah. We praise Him, seek His help, and seek His forgiveness. We seek refuge in Allah from the evils within ourselves and from our bad deeds. Whomever Allah guides, none can misguide; and whomever He leaves astray, none can guide. I bear witness that there is no god except Allah alone, without partner, and I bear witness that Muhammad is His servant and Messenger.” Then connect your sermon with three verses from the Book of Allah: “O you who believe, fear Allah as He should truly be feared, and do not die except as Muslims.” [Āl ʿImrān: 102] “O mankind, fear your Lord, who created you from a single soul, and created from it its mate, and spread from the two many men and women. And fear Allah, through whom you ask one another, and the ties of kinship. Indeed, Allah is ever Watchful over you.” [al-Nisāʾ: 1] “O you who believe, fear Allah and speak words that are right. He will set right your deeds for you and forgive your sins. And whoever obeys Allah and His Messenger has certainly attained a great triumph.” [al-Aḥzāb: 70–71]"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2118,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1105},{"key":"nasai","label":"النسائي","number":3277},{"key":"ibnmajah","label":"ابن ماجه","number":1892}],"full":1,"dr":1},{"num":6176,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ كُلُّ خُطْبَةٍ لَيْسَ فِيهَا تَشَهُّدٌ فَهِيَ كَالْيَدِ الْجَذْمَاءِ."],"takhrij":"حسن: رواه أبو داود (4841) والترمذي (1118) وأحمد (8018) وابن حبان في صحيحه (2796) كلهم من طرق عن عاصم بن كليب، قال: حدثني أبي، قال: سمعت أبا هريرة فذكره.","grade":"حسن","chapter_ar":"باب خطبة النكاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4841), al-Tirmidhi (1118), Ahmad (8018), and Ibn Hibban in his Sahih (2796).","chapter_en":"Chapter on the marriage sermon","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah reported from the Prophet ﷺ that he said: “Every sermon in which there is no declaration of faith is like a severed hand.”"]},"buhuth":{"en":["“Severed” means cut off, meaning a hand from which no benefit is taken."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4841,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1118,"n":1106},{"key":"ibnhibban","label":"ابن حبان في صحيحه","number":2796},{"key":"ahmad","label":"مسند الإمام أحمد","number":8018,"n":7879},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4626,"n":4622}],"full":1,"dr":1,"rep":[3293]},{"num":6177,"demo":false,"sanad":"","matn":["عن أنس قَالَ: جَاءَ ثَلاَثَةُ رَهْطٍ إِلَى بُيُوتِ أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْأَلُونَ عَنْ عِبَادَةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمَّا أُخْبِرُوا كَأَنَّهُمْ تَقَالُّوهَا فَقَالُوا وَأَيْنَ نَحْنُ مِنَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَمَا تَأَخَّرَ. قَالَ أَحَدُهُمْ أَمَّا أَنَا فَإِنِّي أُصَلِّي اللَّيْلَ أَبَدًا. وَقَالَ آخَرُ أَنَا أَصُومُ الدَّهْرَ وَلاَ أُفْطِرُ. وَقَالَ آخَرُ أَنَا أَعْتَزِلُ النِّسَاءَ فَلاَ أَتَزَوَّجُ أَبَدًا. فَجَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ أَنْتُمُ الَّذِينَ قُلْتُمْ كَذَا وَكَذَا أَمَا وَاللَّهِ إِنِّي لأَخْشَاكُمْ لِلَّهِ وَأَتْقَاكُمْ لَهُ، لَكِنِّي أَصُومُ وَأُفْطِرُ، وَأُصَلِّي وَأَرْقُدُ وَأَتَزَوَّجُ النِّسَاءَ، فَمَنْ رَغِبَ عَنْ سُنَّتِي فَلَيْسَ مِنِّي."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5063) عن طريق حميد بن أبي حُميد الطويل أنه سمع أنس بن مالك يقول (فذكره). واللفظ له. ورواه مسلم في النكاح (1401) من طريق حماد بن سلمة، عن ثابت، عن أنس، به، بمعناه.","grade":"متفق عليه","chapter_ar":"باب الزواج من سنن المرسلين والمتقين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5063) and Muslim (1401).","chapter_en":"Chapter on marriage being from the practice of the messengers and the righteous","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Malik said: Three men came to the houses of the wives of the Prophet ﷺ asking about the worship of the Prophet ﷺ. When they were informed, they seemed to think it little. They said: Where are we compared to the Prophet ﷺ, when Allah has forgiven his past and future sins? One of them said: As for me, I will pray all night forever. Another said: I will fast continuously and never break my fast. Another said: I will keep away from women and never marry. Then the Messenger of Allah ﷺ came and said: “Are you the ones who said such and such? By Allah, I am the one among you who fears Allah most and is most mindful of Him, but I fast and I break the fast, I pray and I sleep, and I marry women. So whoever turns away from my way is not of me.”"]},"intro":{"ar":["قال الله تعالى: (وَلَقَدْ أَرْسَلْنَا رُسُلًا مِنْ قَبْلِكَ وَجَعَلْنَا لَهُمْ أَزْوَاجًا وَذُرِّيَّةً) [الرعد: ٣٨]","وقال تعالى: (وَالَّذِينَ يَقُولُونَ رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا) [الفرقان: ٧٤]"],"en":["Allah Most High said:","“And We certainly sent messengers before you, and We made for them wives and offspring.” [Al-Ra‘d: 38]","And He said:","“And those who say: Our Lord, grant us from our spouses and our offspring comfort to our eyes, and make us leaders for the righteous.” [Al-Furqan: 74]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5063,"lafz":true},{"key":"muslim","label":"مسلم","number":1401}],"full":1,"rep":[15693]},{"num":6178,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ جُبَيْرٍ قَالَ: قَالَ لِي ابْنُ عَبَّاسٍ: هَلْ تَزَوَّجْتَ؟ قُلْتُ: لَا، قَالَ: فَتَزَوَّجْ؛ فَإِنَّ خَيْرَ هَذِهِ الْأُمَّةِ أَكْثَرُهَا نِسَاءً."],"takhrij":"صحيح: رواه البخاري في النكاح (5069) عن علي بن الحكم الأنصاري، حدثنا أبو عوانة، عن رقبة (هو ابن مصقلة العبدي)، عن طلحة اليامي، عن سعيد بن جبير فذكره.","grade":"صحيح","chapter_ar":"باب الزواج من سنن المرسلين والمتقين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5069).","chapter_en":"Chapter on marriage being from the practice of the messengers and the righteous","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Sa‘id ibn Jubayr said: Ibn ‘Abbas said to me: Have you married? I said: No. He said: Then marry, for the best of this community were those who had the most wives."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5069,"lafz":true}],"full":1,"rep":[6180]},{"num":6179,"demo":false,"sanad":"","matn":["عَنْ عَلْقَمَةَ، قَالَ كُنْتُ أَمْشِي مَعَ عَبْدِ اللَّهِ بِمِنًى فَلَقِيَهُ عُثْمَانُ فَقَامَ مَعَهُ يُحَدِّثُهُ فَقَالَ لَهُ عُثْمَانُ يَا أَبَا عَبْدِ الرَّحْمَنِ أَلاَ نُزَوِّجُكَ جَارِيَةً شَابَّةً لَعَلَّهَا تُذَكِّرُكَ بَعْضَ مَا مَضَى مِنْ زَمَانِكَ. قَالَ فَقَالَ عَبْدُ اللَّهِ لَئِنْ قُلْتَ ذَاكَ لَقَدْ قَالَ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَا مَعْشَرَ الشَّبَابِ مَنِ اسْتَطَاعَ مِنْكُمُ الْبَاءَةَ فَلْيَتَزَوَّجْ فَإِنَّهُ أَغَضُّ لِلْبَصَرِ وَأَحْصَنُ لِلْفَرْجِ وَمَنْ لَمْ يَسْتَطِعْ فَعَلَيْهِ بِالصَّوْمِ فَإِنَّهُ لَهُ وِجَاءٌ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5065) من طريق حفص بن غياث، ومسلم في النكاح (1:1400) من طريق أبي معاوية كلاهما عن الأعمش، حدثني إبراهيم (وهو النخعي)، عن علقمة، فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5065) and Muslim (1400:1). The wording here is that of Muslim.","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["‘Alqamah said: I was walking with ‘Abd Allah at Mina when ‘Uthman met him and stood speaking with him. ‘Uthman said to him: O Abu ‘Abd al-Rahman, shall we not marry you to a young woman? Perhaps she may remind you of some of what has passed from your earlier days. ‘Abd Allah said: If you say that, then indeed the Messenger of Allah ﷺ said to us: “O company of young men, whoever among you is able to marry, let him marry, for it is more effective in lowering the gaze and better in guarding chastity. And whoever is not able, then he should fast, for it is a restraint for him.”"]},"buhuth":{"en":["The word used here means sexual ability. Originally it refers to the place where a person resides, and marriage was called by this term because whoever marries a woman settles her in a home. (Sharh al-Sunnah, 4/9)"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5065,"lafz":true},{"key":"muslim","label":"مسلم","number":1}],"full":1,"dr":1},{"num":6180,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ قَالَ لِي ابْنُ عَبَّاسٍ هَلْ تَزَوَّجْتَ قُلْتُ لاَ. قَالَ فَتَزَوَّجْ فَإِنَّ خَيْرَ هَذِهِ الأُمَّةِ أَكْثَرُهَا نِسَاءً."],"takhrij":"صحيح: رواه البخاري في النكاح (5069) عن علي بن الحكم الأنصاري، حدثنا أبو عوانة، عن رقبة (هو ابن مصقلة العبدي)، عن طلحة اليامي، عن سعيد بن جبير قال: قال لي ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari in the Book of Marriage (5069).","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Sa‘id ibn Jubayr said: Ibn ‘Abbas said to me: Have you married? I said: No. He said: Then marry, for the best of this nation were those with the most wives."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري في النكاح","number":5069,"lafz":true}],"full":1,"dr":1,"rep":[6178]},{"num":6181,"demo":false,"sanad":"","matn":["عن عبد الله بن مسعود قال: كنا نغزو مع رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وليس لنا شيء، فقلنا: ألا نستخصي؟ فنهانا عن ذلك، ثم رخص لنا أن ننكح المرأة بالثوب، ثم قرأ علينا ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تُحَرِّمُوا طَيِّبَاتِ مَا أَحَلَّ اللَّهُ لَكُمْ وَلَا تَعْتَدُوا إِنَّ اللَّهَ لَا يُحِبُّ الْمُعْتَدِينَ﴾ [المائدة: ٨٧]"],"takhrij":"متفق عليه: رواه البخاري في النكاح (5075)، ومسلم في النكاح (1404) كلاهما من طريق جرير، عن إسماعيل بن أبي خالد، عن قيس (هو ابن أبي حازم ) قال سمعت عبد الله يقول (فذكره). واللفظ للبخاري .","grade":"متفق عليه","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5075) and Muslim (1404). The wording here is that of al-Bukhari.","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["‘Abd Allah ibn Mas‘ud said: We used to go out in battle with the Messenger of Allah ﷺ while we had nothing, so we said: Should we not castrate ourselves? He forbade us from that. Then he permitted us to marry a woman in exchange for a garment. Then he recited to us: “O you who believe, do not forbid the good things Allah has made lawful for you, and do not transgress. Surely Allah does not love the transgressors.” [Al-Ma’idah: 87]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5075,"lafz":true},{"key":"muslim","label":"مسلم","number":1404}],"full":1},{"num":6182,"demo":false,"sanad":"","matn":["عن سَعْدِ بن أَبِي وَقَّاصٍ يَقُولُ رَدَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى عُثْمَانَ بْنِ مَظْعُونٍ التَّبَتُّلَ، وَلَوْ أَذِنَ لَهُ لاَخْتَصَيْنَا."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5073)، ومسلم في النكاح (7:1402) كلاهما من طريق إبراهيم بن سعد، أخبرنا ابن شهاب، سمع سعيد بن المسيب يقول، سمعت سعد بن أبي وقاص يقول (فذكره).","grade":"متفق عليه","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5073) and Muslim (1402:7).","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Sa‘d ibn Abi Waqqas said: The Messenger of Allah ﷺ rejected celibacy for ‘Uthman ibn Maz‘un, and if he had allowed him, we would have castrated ourselves."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5073,"lafz":true},{"key":"muslim","label":"مسلم","number":7}],"full":1},{"num":6183,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ، قَالَ: لَمَّا كَانَ مِنْ أَمْرِ عُثْمَانَ بْنِ مَظْعُونٍ الَّذِي كَانَ مِنْ تَرْكِ النِّسَاءِ، بَعَثَ إِلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا عُثْمَانُ إِنِّي لَمْ أُومَرْ بِالرَّهْبَانِيَّةِ أَرَغِبْتَ عَنْ سُنَّتِي؟، قَالَ: لَا، يَا رَسُولَ اللَّهِ، قَالَ: إِنَّ مِنْ سُنَّتِي أَنْ أُصَلِّي، وَأَنَام، وَأَصُومَ، وَأَطْعَمَ، وَأَنْكِحَ، وَأُطَلِّقَ، فَمَنْ رَغِبَ عَنْ سُنَّتِي، فَلَيْسَ مِنِّي يَا عُثْمَانُ، إِنَّ لِأَهْلِكَ عَلَيْكَ حَقًّا، وَلِنَفْسِكَ عَلَيْكَ حَقًّا.","قال سعد: فوالله لقد كان أجمع رجال من المسلمين على أن رسول الله صلى الله عليه وسلم إن هو أقر عثمان على ما هو عليه أن نختصي فنتبتل."],"takhrij":"حسن: رواه الدارمي (2215) عن محمد بن يزيد الحزامي، حدثنا يونس بن بكير، حدثني ابن إسحاق، حدثني الزهري، عن سعيد بن المسيب، عن سعد بن أبي وقاص، فذكره. وإسناده حسن من أجل تصريح ابن إسحاق.","grade":"حسن","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Darimi (2215).","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Sa‘d ibn Abi Waqqas said: When the matter of ‘Uthman ibn Maz‘un occurred regarding his leaving women aside, the Messenger of Allah ﷺ sent for him and said: “O ‘Uthman, I was not commanded with monasticism. Have you turned away from my way?” He said: No, O Messenger of Allah. He said: “Part of my way is that I pray and I sleep, I fast and I eat, and I marry and divorce. Whoever turns away from my way is not of me. O ‘Uthman, your family has a right over you, and your own self has a right over you.” Sa‘d said: By Allah, the Muslim men were on the verge of agreeing that if the Messenger of Allah ﷺ had approved ‘Uthman in what he was doing, we would have castrated ourselves and lived in celibacy."]},"buhuth":{"en":["His statement, “celibacy,” originally means cutting off. What is meant is cutting oneself off from women and leaving marriage in order to devote oneself entirely to worship of Allah.","His statement, “we would have castrated ourselves,” means removing the two testicles by cutting the skin covering them."]}},"tuhfa":{},"refs":[{"key":"darimi","label":"سنن الدارمي","number":2104,"n":2104},{"key":"darimi","label":"الدارمي","number":2215,"lafz":true,"n":2104}],"full":1,"dr":1,"rep":[2781,13634]},{"num":6184,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنِّي رَجُلٌ شَابٌّ وَأَنَا أَخَافُ عَلَى نَفْسِي الْعَنَتَ وَلاَ أَجِدُ مَا أَتَزَوَّجُ بِهِ النِّسَاءَ، فَسَكَتَ عَنِّي، ثُمَّ قُلْتُ مِثْلَ ذَلِكَ، فَسَكَتَ عَنِّي ثُمَّ قُلْتُ مِثْلَ ذَلِكَ، فَسَكَتَ عَنِّي ثُمَّ قُلْتُ مِثْلَ ذَلِكَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَا أَبَا هُرَيْرَةَ جَفَّ الْقَلَمُ بِمَا أَنْتَ لاَقٍ، فَاخْتَصِ عَلَى ذَلِكَ أَوْ ذَرْ."],"takhrij":"صحيح: رواه البخاري في النكاح (5076) فقال: وقال أصبغ: أخبرني ابنُ وهب، عن يونس بن يزيد، عن ابن شهاب، عن أبي سلمة، عن أبي هريرة قال ( فذكره ).","grade":"صحيح","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5076).","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Abu Hurayrah said: I said: O Messenger of Allah, I am a young man, and I fear hardship for myself, and I do not find what I can marry women with. He remained silent toward me. Then I said the same again, and he remained silent. Then I said it again, and he remained silent. Then I said it again, so the Prophet ﷺ said: “O Abu Hurayrah, the pen has dried regarding what you are going to meet, so castrate yourself on that basis or leave it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5076,"lafz":true}],"full":1,"dr":1},{"num":6185,"demo":false,"sanad":"","matn":["عَنْ أنَسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ عَلَى فِتْيَةٍ مِنْ شَبَابِ قُرَيْشٍ، فَقَالَ: يَا مَعْشَرَ الشَّبَابِ، مَنِ اسْتَطَاعَ مِنْكُمُ الطَّوْلَ فَلْيَنْكِحْ، أَوْ فَلْيَتَزَوَّجْ، وَإِلَّا فَعَلَيْهِ بِالصَّوْمِ، فَإِنَّهُ لَهُ وِجَاءٌ."],"takhrij":"صحيح: رواه البزار – كشف الأستار( 1398) عن محمد بن الليث، ثنا علي بن عبد الحميد، ثنا سليمان بن المغيرة، عن ثابت، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bazzar in Kashf al-Astar (1398).","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Anas reported that the Prophet ﷺ came out to a group of young men from Quraysh and said: “O company of young men, whoever among you has the means, let him marry; otherwise he should fast, for it is a restraint for him.”"]}},"tuhfa":{},"refs":[{"key":"sh12862","label":"البزار - كشف الأستار","number":1398,"lafz":true}],"full":1,"dr":1},{"num":6186,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُ بِالْبَاءَةِ، وَيَنْهَى عَنِ التَّبَتُّلِ نَهْيًا شَدِيدًا، وَيَقُولُ: تَزَوَّجُوا الْوَدُودَ الْوَلُودَ، إِنِّي مُكَاثِرٌ الْأَنْبِيَاءَ يَوْمَ الْقِيَامَةِ."],"takhrij":"حسن: رواه أحمد (12613) عن حسين وعفان، والبزار -كشف الأستار (1400)- من طريق محمد بن معاوية، وابن حبان في صحيحه (4028) من طريق قتيبة بن سعيد، والبيهقي (7/81-82) من طريق إبراهيم بن أبي العباس، كلهم عن خلف بن خليفة، قال: حدثني حفص بن عمر، عن أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (12613) and al-Bazzar in Kashf al-Astar (1400).","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ used to command marriage and strongly forbid celibacy, and he would say: “Marry the loving and fertile woman, for I will boast of your numbers before the prophets on the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"sh12862","label":"البزار - كشف الأستار","number":1400},{"key":"ahmad","label":"مسند الإمام أحمد","number":12613,"n":12613,"lafz":true},{"key":"ibnhibban","label":"ابن حبان في صحيحه","number":4028}],"full":1,"dr":1},{"num":6187,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا شَبَابَ قُرَيْشٍ، لا تَزْنُوا، احْفَظُوا فُرُوجَكُمْ، أَلَا مَنْ حَفِظَ فَرْجَهُ، فَلَهُ الْجَنَّةُ."],"takhrij":"حسن: رواه البزار – كشف الأستار (1401) والطبراني في الكبير (12/165) والأوسط، من حديث مسلم بن إبراهيم، ثنا شداد بن سعيد، ثنا سعيد الجريري، عن أبي نضرة، عن ابن عباس فذكره واللفظ للبزار.","grade":"حسن","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzar in Kashf al-Astar (1401) and al-Tabarani in al-Kabir (12/165). The wording here is that of al-Bazzar.","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Ibn ‘Abbas said: The Messenger of Allah ﷺ said: “O youth of Quraysh, do not commit fornication. Guard your private parts. Indeed, whoever guards his chastity will have Paradise.”"]}},"tuhfa":{},"refs":[{"key":"sh12862","label":"البزار - كشف الأستار","number":1401,"lafz":true},{"key":"mujamkabir","label":"الطبراني في الكبير","number":12}],"full":1,"dr":1},{"num":6188,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ التَّبَتُّلِ."],"takhrij":"صحيح: رواه الترمذي (1082) وابن ماجة (1849) والنسائي (3214) وأحمد (20192) وابن الجارود (673) كلهم من طريق معاذ بن هشام، عن أبيه، عن قتادة، عن الحسن، عن سمرة، فذكره.","grade":"صحيح","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1082), Ibn Majah (1849), al-Nasa’i (3214), and Ahmad (20192).","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Samurah reported that the Prophet ﷺ forbade celibacy."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1082,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":1849},{"key":"nasai","label":"النسائي","number":3214,"n":3213},{"key":"ahmad","label":"مسند الإمام أحمد","number":20192,"n":20192},{"key":"sh13071","label":"ابن الجارود","number":673,"n":700}],"full":1,"dr":1,"rep":[13636]},{"num":6189,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ التَّبَتُّلِ."],"takhrij":"صحيح: رواه النسائي (3214) وأحمد (24943) كلاهما من حديث خالد بن الحارث، قال: حدثنا أشعث، عن الحسن، عن سعد بن هشام، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3213) and Ahmad (24943).","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["‘A’ishah reported that the Prophet ﷺ forbade celibacy."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3213,"lafz":true,"n":3213},{"key":"ahmad","label":"مسند الإمام أحمد","number":24943,"n":24943},{"key":"nasai","label":"النسائي","number":3214,"n":3213}],"full":1,"dr":1},{"num":6190,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: دَخَلَتِ امْرَأَةُ عُثْمَانَ بْنِ مَظْعُونٍ، وَأسْمُهَا خَوْلَةُ بِنْتُ حَكِيمٍ عَلَى عَائِشَةَ، وَهِيَ بَاذَّةُ الْهَيْئَةِ، فَسَأَلَتْهَا: مَا شَأْنُكِ؟ فَقَالَتْ: زَوْجِي يَقُومُ اللَّيْلَ، وَيَصومُ النَّهَارَ، فَدَخَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَتْ ذَلِكَ لَهُ عَائِشَةُ، فَلَقِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عُثْمَانَ فَقَالَ: يَا عُثْمَانُ، إِنَّ الرَّهْبَانِيَّةَ لَمْ تُكْتَبْ عَلَيْنَا، أَمَا لَكَ فِيَّ أُسْوَةٌ؟ فَوَاللَّهِ إِنَّ أَخْشَاكُمْ لِلهِ وَأَحْفَظَكُمْ لِحُدُودِهِ لأَنَا."],"takhrij":"صحيح: رواه عبد الرزاق (10375) عن معمر، عن الزهري، عن عروة وعمرة، عن عائشة قالت: فذكرته. ومن هذا الطريق رواه البزار- كشف الأستار (1458) وابن حبان (9) ولكن عن عروة وحده.","grade":"صحيح","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by ‘Abd al-Razzaq (10375), al-Bazzar in Kashf al-Astar (1458), and Ibn Hibban (9).","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["‘A’ishah said: The wife of ‘Uthman ibn Maz‘un, whose name was Khawlah bint Hakim, came to ‘A’ishah while she was in poor appearance. She asked her: What is the matter with you? She said: My husband stands in prayer all night and fasts all day. Then the Prophet ﷺ came in, and ‘A’ishah mentioned that to him. So the Prophet ﷺ met ‘Uthman and said: “O ‘Uthman, monasticism has not been prescribed for us. Do you not have an example in me? By Allah, I am the one among you who fears Allah most and guards His limits best.”"]}},"tuhfa":{},"refs":[{"key":"abdrazzaq","label":"عبد الرزاق","number":10375,"lafz":true},{"key":"sh12862","label":"البزار - كشف الأستار","number":1458},{"key":"abdrazzaq","label":"المصنف لعبد الرزاق","number":11217,"n":11309},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4658,"n":4654},{"key":"ibnhibban","label":"ابن حبان","number":9}],"full":1,"dr":1,"rep":[15272]},{"num":6191,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَتْ امْرَأَةُ عُثْمَانَ بْنِ مَظْعُونٍ تَخْتَضِبُ وتطَّيَّب، فَتَرَكَتْهُ، فَدَخَلَتْ عليّ، فَقُلْتُ لَهَا: أ مُشْهِدٌ أَمْ مُغِيبٌ؟ فَقَالَتْ: مُشْهِدٌ كَمُغِيبٍ. قُلْتُ لَهَا: مالك؟ قَالَتْ: عُثْمَانُ لَا يُرِيدُ الدُّنْيَا، وَلَا يُرِيدُ النِّسَاءَ. قَالَتْ عَائِشَةُ: فَدَخَلَ عليّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرْتُهُ بِذَلِكَ. فَلَقِيَ عُثْمَانَ فَقَالَ: يَا عُثْمَانُ! أَتُؤْمِنُ بِمَا نُؤْمِنُ بِهِ؟ قَالَ: نَعَمْ يَا رَسُولَ اللَّهِ قَالَ: فاصنعْ كَمَا نصنعُ."],"takhrij":"حسن: رواه الإمام أحمد (24754) عن مؤمل، حدثنا حماد، حدثنا إسحاق بن سويد، عن أبي فاختة، عن عائشة فذكرت.","grade":"حسن","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (24754) and Abu Nu‘aym in al-Hilyah (6/257).","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["‘A’ishah said: The wife of ‘Uthman ibn Maz‘un used to apply henna and perfume, then she stopped doing so. She came to me, and I said to her: Is your husband present or absent? She said: Present like absent. I said to her: What is wrong with you? She said: ‘Uthman has no desire for worldly life and no desire for women. ‘A’ishah said: Then the Messenger of Allah ﷺ came to me and I informed him of that. He met ‘Uthman and said: “O ‘Uthman, do you believe in what we believe in?” He said: Yes, O Messenger of Allah. He said: “Then do as we do.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":24754,"lafz":true,"n":24753},{"key":"sh10495","label":"أبو نعيم في الحلية","number":6}],"full":1,"dr":1},{"num":6192,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَحَقُّ الشُّرُوطِ أَنْ تُوفُوا بِهِ مَا اسْتَحْلَلْتُمْ بِهِ الْفُرُوجَ."],"takhrij":"متفق عليه: رواه البخاري في الشروط (2721) ومسلم في النكاح (1418) كلاهما من حديث يزيد بن أبي حبيب، عن أبي الخير، عن عقبة بن عامر فذكره.","grade":"متفق عليه","chapter_ar":"باب في الوفاء بالشروط في عقد النكاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2721) and Muslim (1418).","chapter_en":"Chapter on fulfilling conditions in the marriage contract","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["‘Uqbah ibn ‘Amir reported that the Messenger of Allah ﷺ said: “The conditions most deserving to be fulfilled are those by which you made private relations lawful.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2721,"lafz":true},{"key":"muslim","label":"مسلم","number":1418}],"full":1,"dr":1,"rep":[6503]},{"num":6193,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَلاَثَةٌ كُلُّهُمْ حَقٌّ عَلَى اللَّهِ عَوْنُهُ الْغَازِي فِي سَبِيلِ اللَّهِ وَالْمُكَاتَبُ الَّذِي يُرِيدُ الأَدَاءَ وَالنَّاكِحُ الَّذِي يُرِيدُ التَّعَفُّفَ."],"takhrij":"حسن: رواه الترمذي (1655) والنسائي (3120، 3218) وابن ماجة (2518) وأحمد (7416) وصحّحه ابن حبان (4030) والحاكم (2/160) كلهم من طريق ابن عجلان، عن سعيد بن أبي سعيد، عن أبي هرير فذكره.","grade":"حسن","chapter_ar":"باب عون الله تعالى للناكح الذي يريد العفاف","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1655), who graded it Hasan, al-Nasa’i (3218, 3120), Ibn Majah (2518), and Ahmad (7416).","chapter_en":"Chapter on Allah’s help for the one who marries seeking chastity","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Three people all have a right upon Allah that He help them: the fighter in the path of Allah, the contracted slave who wants to complete his payment, and the one who marries seeking chastity.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1655,"lafz":true},{"key":"nasai","label":"النسائي","number":3218},{"key":"ibnmajah","label":"ابن ماجه","number":2518},{"key":"ahmad","label":"مسند الإمام أحمد","number":7416,"n":7416},{"key":"nasai","label":"النسائي","number":3120},{"key":"ibnhibban","label":"ابن حبان","number":4030}],"full":1,"dr":1},{"num":6194,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِذَا دَخَلْتَ لَيْلاً فَلاَ تَدْخُلْ عَلَى أَهْلِكَ حَتَّى تَسْتَحِدَّ الْمُغِيبَةُ وَتَمْتَشِطَ الشَّعِثَةُ.","قال: قال رسول الله صلى الله عليه وسلم: فعليك بالكَيْس الكَيْس."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5246) من طريق شعبة- ومسلم في الرضاع (57:715) من طريق هُشيم- كلاهما عن سيّار، عن الشعبي، عن جابر بن عبد الله فذكره.","grade":"متفق عليه","chapter_ar":"باب الحث على طلب الولد بالزواج، والترغيب في تزوج الولود الودود","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5246) and Muslim (715:57).","chapter_en":"Chapter on encouraging the seeking of children through marriage and encouraging marriage to a loving, fertile woman","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah reported that the Prophet ﷺ said: “If you arrive at night, do not enter upon your family until the woman whose husband was absent removes her unwanted hair and the disheveled woman combs her hair.” Jabir said: The Messenger of Allah ﷺ said: “So hold fast to good sense, hold fast to good sense.”"]},"buhuth":{"en":["His statement, “So hold fast to good sense,” was explained by al-Bukhari in the preceding narration as referring to children, meaning seeking offspring. Ibn al-A‘rabi said: the word can mean intercourse. It also means intelligence. What is meant here is encouraging him to seek children. See Sharh Muslim by al-Nawawi (10/54)."]},"intro":{"ar":["قال الله تعالى: (هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُ ۖ قَالَ رَبِّ هَبْ لِي مِنْ لَدُنْكَ ذُرِّيَّةً طَيِّبَةً ۖ إِنَّكَ سَمِيعُ الدُّعَاءِ) [آل عمران: ٣٨]"],"en":["Allah Most High said:","“Thereupon Zechariah called upon his Lord. He said: My Lord, grant me from Yourself good offspring. Surely You are the Hearer of supplication.” [Aal ‘Imran: 38]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5246,"lafz":true},{"key":"muslim","label":"مسلم","number":57}],"full":1,"dr":1},{"num":6195,"demo":false,"sanad":"","matn":["عَنْ مَعْقِلِ بْنِ يَسَارٍ، قَالَ جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ إِنِّي أَصَبْتُ امْرَأَةً ذَاتَ حَسَبٍ وَجَمَالٍ وَإِنَّهَا لاَ تَلِدُ أَفَأَتَزَوَّجُهَا قَالَ لاَ. ثُمَّ أَتَاهُ الثَّانِيَةَ فَنَهَاهُ ثُمَّ أَتَاهُ الثَّالِثَةَ فَقَالَ تَزَوَّجُوا الْوَدُودَ الْوَلُودَ فَإِنِّي مُكَاثِرٌ بِكُمُ."],"takhrij":"حسن: رواه أبو داود (2050) والنسائي (3227) كلاهما من حديث يزيد بن هارون قال: أنبأنا المستلم بن سعيد – ابن أخت منصور بن راذان – عن منصور، يعني – ابن راذان – عن معاوية بن قرة، عن معقل بن يسار فذكره. ومن هذا الطريق رواه ابن حبان ( 4056) والحاكم (2/162) قال الحاكم: \"صحيح الإسناد\".","grade":"حسن","chapter_ar":"باب الحث على طلب الولد بالزواج، والترغيب في تزوج الولود الودود","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2050) and al-Nasa’i (3227).","chapter_en":"Chapter on encouraging the seeking of children through marriage and encouraging marriage to a loving, fertile woman","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Ma‘qil ibn Yasar said: A man came to the Prophet ﷺ and said, “I have found a woman of noble lineage and beauty, but she does not bear children. Should I marry her?” He said, “No.” Then he came to him a second time, and he forbade him. Then he came a third time, and he said, “Marry the loving, fertile women, for I will boast of your numbers.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2050,"lafz":true},{"key":"nasai","label":"النسائي","number":3227,"n":3227}],"full":1,"dr":1},{"num":6196,"demo":false,"sanad":"","matn":["عن ابن عمر أنه تزوج امرأة فأصابها شمطاء فطلقها. وقال: حصير في بيت خير من امرأة لا تلد. والله ما أقربكن شهوة، ولكني سمعت رسول الله صلى الله عليه وسلم يقول: تزوجوا الودود الولود، فإني مكاثر بكم الأمم يوم القيامة."],"takhrij":"صحيح: رواه الخطيب في تاريخ بغداد (6782) في ترجمة \"الفضل بن أحمد بن منصور بن الذيّال الزبيدي\" عن الحسن بن أبي طالب، قال: حدثنا أبو محمد عبيد الله بن أحمد بن معروف القاضي، قال: حدثنا الفضل بن أحمد بن منصور الزبيدي، إملاء من حفظه، قال: حدثنا زياد بن أيوب، قال: حدثنا إسماعيل بن عُلية، عن أيوب، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب الحث على طلب الولد بالزواج، والترغيب في تزوج الولود الودود","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Khatib in Tarikh Baghdad (6782).","chapter_en":"Chapter on encouraging the seeking of children through marriage and encouraging marriage to a loving, fertile woman","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Ibn ‘Umar reported that he married a woman, then found her gray-haired, so he divorced her. He said: “A mat in the house is better than a woman who does not bear children. By Allah, it is not desire for women that brings me near to you, but I heard the Messenger of Allah ﷺ say: ‘Marry the loving, fertile women, for I will boast of your numbers before the nations on the Day of Resurrection.’”"]}},"tuhfa":{},"refs":[{"key":"sh23764","label":"الخطيب في تاريخ بغداد","number":6782,"lafz":true,"n":6485}],"full":1,"dr":1},{"num":6197,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ قَفَلْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ غَزْوَةٍ فَتَعَجَّلْتُ عَلَى بَعِيرٍ لِي قَطُوفٍ، فَلَحِقَنِي رَاكِبٌ مِنْ خَلْفِي، فَنَخَسَ بَعِيرِي بِعَنَزَةٍ كَانَتْ مَعَهُ، فَانْطَلَقَ بَعِيرِي كَأَجْوَدِ مَا أَنْتَ رَاءٍ مِنَ الإِبِلِ، فَإِذَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ مَا يُعْجِلُكَ. قُلْتُ كُنْتُ حَدِيثَ عَهْدٍ بِعُرُسٍ. قَالَ بِكْرًا أَمْ ثَيِّبًا. قُلْتُ ثَيِّبٌ. قَالَ فَهَلاَّ جَارِيَةً تُلاَعِبُهَا وَتُلاَعِبُكَ. قَالَ فَلَمَّا ذَهَبْنَا لِنَدْخُلَ قَالَ أَمْهِلُوا حَتَّى تَدْخُلُوا لَيْلاً ـ أَىْ عِشَاءً ـ لِكَىْ تَمْتَشِطَ الشَّعِثَةُ وَتَسْتَحِدَّ الْمُغِيبَةُ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5079) ومسلم في الرضاع (1466: 57) كلاهما من طريق هُشيم، حدثنا سيّار، عن الشعبي، عن جابر بن عبد الله، قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب تفضيل نكاح الأبكار على الثيبات إلا للمصلحة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5079) and Muslim (715/57).","chapter_en":"Chapter on preferring marriage to virgins over previously married women, except when there is a benefit in doing otherwise","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported: We were returning with the Prophet ﷺ from an expedition. I hurried ahead on a camel of mine that was slow in walking. A rider caught up with me from behind and prodded my camel with a stick that he had, whereupon my camel began moving as well as the best camel you could see. It was the Prophet ﷺ. He asked: “What is making you hurry?” I replied: “I have recently been married.” He asked: “A virgin or a previously married woman?” I replied: “A previously married woman.” He said: “Why not a young virgin whom you could play with and who could play with you?” When we were about to enter Madinah, he said: “Wait until you enter at night—that is, in the evening—so that the woman whose hair is disheveled may comb it, and the woman whose husband has been absent may remove her unwanted hair.”"]},"buhuth":{"en":["“Qaṭūf” means slow in walking.","“Al-shaʿithah” means a woman whose hair is disordered, so that she may beautify herself for her husband."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5079,"lafz":true},{"key":"muslim","label":"مسلم","number":715},{"key":"muslim","label":"مسلم في الرضاع","number":1466}],"full":1,"dr":1},{"num":6198,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ هَلَكَ أَبِي وَتَرَكَ سَبْعَ بَنَاتٍ أَوْ تِسْعَ بَنَاتٍ فَتَزَوَّجْتُ امْرَأَةً ثَيِّبًا فَقَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَزَوَّجْتَ يَا جَابِرُ. فَقُلْتُ نَعَمْ. فَقَالَ بِكْرًا أَمْ ثَيِّبًا. قُلْتُ بَلْ ثَيِّبًا. قَالَ فَهَلاَّ جَارِيَةً تُلاَعِبُهَا وَتُلاَعِبُكَ، وَتُضَاحِكُهَا وَتُضَاحِكُكَ. قَالَ فَقُلْتُ لَهُ إِنَّ عَبْدَ اللَّهِ هَلَكَ وَتَرَكَ بَنَاتٍ، وَإِنِّي كَرِهْتُ أَنْ أَجِيئَهُنَّ بِمِثْلِهِنَّ، فَتَزَوَّجْتُ امْرَأَةً تَقُومُ عَلَيْهِنَّ وَتُصْلِحُهُنَّ. فَقَالَ بَارَكَ اللَّهُ لَكَ. أَوْ قَالَ خَيْرًا.","وفي لفظ: فكرهت أن أجمع إليهن جارية خرقاء مثلهنّ، ولكن امرأة تمشطهن وتقوم عليهن."],"takhrij":"متفق عليه: رواه البخاري في النفقات (5367)، ومسلم في الرضاع (1466: 56) كلاهما من طريق حماد بن يزيد، عن عمرو بن دينار، عن جابر بن عبد الله، فذكره.","grade":"متفق عليه","chapter_ar":"باب تفضيل نكاح الأبكار على الثيبات إلا للمصلحة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5367) and Muslim (715:56). The alternate wording is in al-Bukhari in the Book of Military Expeditions (4052).","chapter_en":"Chapter on preferring marriage to virgins over previously married women, except when there is a benefit in doing otherwise","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: My father died and left behind seven daughters, or nine daughters, so I married a previously married woman. The Messenger of Allah ﷺ said to me, “Have you married, O Jabir?” I said, “Yes.” He said, “A virgin or a previously married woman?” I said, “Rather, a previously married woman.” He said, “Why not a young virgin, so that you may play with her and she may play with you, and make her laugh and she make you laugh?” He said: I said to him, “ ‘Abd Allah died and left daughters, and I disliked bringing them someone like themselves, so I married a woman who would look after them and set their affairs right.” He said, “May Allah bless you,” or he said, “Good.” And in another wording: “I disliked bringing together with them a young inexperienced girl like them; rather I wanted a woman who would comb their hair and take care of them.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5367,"lafz":true},{"key":"muslim","label":"مسلم","number":56},{"key":"bukhari","label":". واللفظ الآخر للبخاري في المغازي","number":4052},{"key":"muslim","label":"مسلم في الرضاع","number":1466}],"full":1,"dr":1},{"num":6199,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ، عَبْدِ اللَّهِ قَالَ تَزَوَّجْتُ امْرَأَةً فَقَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَلْ تَزَوَّجْتَ. قُلْتُ نَعَمْ. قَالَ أَبِكْرًا أَمْ ثَيِّبًا. قُلْتُ ثَيِّبًا. قَالَ فَأَيْنَ أَنْتَ مِنَ الْعَذَارَى وَلِعَابِهَا.","قال شعبة: فذكرته لعمرو بن دينار. فقال: قد سمعته من جابر.","وإنما قال: فهلا جارية تلاعبها وتلاعبك؟."],"takhrij":"متفق عليه: رواه البخاري في النكاح ( 5080) ومسلم في الرضاع (1466: 55) كلاهما من طريق شعبة، حدّثنا محارب قال: سمعت جابر بن عبد الله يقول: فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب تفضيل نكاح الأبكار على الثيبات إلا للمصلحة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5080) and Muslim (715:55). The wording here is that of Muslim.","chapter_en":"Chapter on preferring marriage to virgins over previously married women, except when there is a benefit in doing otherwise","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Jabir said: I married a woman, and the Messenger of Allah ﷺ said to me, “Have you married?” I said, “Yes.” He said, “A virgin or a previously married woman?” I said, “A previously married woman.” He said, “Then where are you with young virgins and their playfulness?” Shu‘bah said: I mentioned this to ‘Amr ibn Dinar, and he said: I heard it from Jabir, and he only said: “Why not a young girl that you may play with her and she may play with you?”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5080,"lafz":true},{"key":"muslim","label":"مسلم","number":55},{"key":"muslim","label":"مسلم في الرضاع","number":1466,"n":3637}],"full":1,"dr":1,"rep":[6202,6331]},{"num":6200,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ أَرَأَيْتَ لَوْ نَزَلْتَ وَادِيًا وَفِيهِ شَجَرَةٌ قَدْ أُكِلَ مِنْهَا، وَوَجَدْتَ شَجَرًا لَمْ يُؤْكَلْ مِنْهَا، فِي أَيِّهَا كُنْتَ تُرْتِعُ بَعِيرَكَ قَالَ فِي الَّذِي لَمْ يُرْتَعْ مِنْهَا. تَعْنِي أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَتَزَوَّجْ بِكْرًا غَيْرَهَا."],"takhrij":"صحيح: رواه البخاري في النكاح (5077) عن إسماعيل بن عبد الله، قال: حدثني أخي، عن سليمان ( هو ابن بلال )، عن هشام بن عروة، عن أبيه، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب تفضيل نكاح الأبكار على الثيبات إلا للمصلحة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5077).","chapter_en":"Chapter on preferring marriage to virgins over previously married women, except when there is a benefit in doing otherwise","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["‘A’ishah, the wife of the Prophet ﷺ, said: I said, “O Messenger of Allah, if you were to camp in a valley in which there was a tree that had already been grazed from, and you found trees that had not been grazed from, which would you let your camel graze from?” He said, “From the one that has not been grazed from.” Meaning that the Messenger of Allah ﷺ did not marry any virgin besides her."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5077,"lafz":true}],"full":1,"dr":1,"rep":[10393]},{"num":6201,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ تُنْكَحُ الْمَرْأَةُ لأَرْبَعٍ لِمَالِهَا وَلِحَسَبِهَا وَجَمَالِهَا وَلِدِينِهَا، فَاظْفَرْ بِذَاتِ الدِّينِ تَرِبَتْ يَدَاكَ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5090)، ومسلم في الرضاع (1466: 53) كلاهما من طريق يحيى بن سعيد (وهو القطان)، عن عبيد الله، حدثني سعيد بن أبي سعيد، عن أبيه، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء أن الكفاءة هي الدين وحده، والترغيب في اختيار الزوجة الصالحة ذات الدين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5090) and Muslim (1466:53).","chapter_en":"Chapter on what has been reported that compatibility is in religion alone, and encouraging the choice of a righteous, religious wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah reported from the Prophet ﷺ that he said: “A woman is married for four things: for her wealth, her lineage, her beauty, and her religion. So attain the one with religion, may your hands be covered with dust.”"]},"intro":{"ar":["قال الله تعالى: (وَالَّذِينَ يَقُولُونَ رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ) [الفرقان: ٧٤]"],"en":["Allah Most High said:","“And those who say: Our Lord, grant us from our spouses and our offspring comfort to our eyes.” [Al-Furqan: 74]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5090,"lafz":true},{"key":"muslim","label":"مسلم","number":53},{"key":"muslim","label":"مسلم في الرضاع","number":1466}],"full":1,"dr":1},{"num":6202,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ، عَبْدِ اللَّهِ قَالَ تَزَوَّجْتُ امْرَأَةً فَقَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَلْ تَزَوَّجْتَ. قُلْتُ نَعَمْ. قَالَ أَبِكْرًا أَمْ ثَيِّبًا. قُلْتُ ثَيِّبًا. قَالَ فَأَيْنَ أَنْتَ مِنَ الْعَذَارَى وَلِعَابِهَا.","قال شعبة: فذكرته لعمرو بن دينار. فقال: قد سمعته من جابر. وإنما قال: فهلا جارية تُلاعبها وتُلاعبك؟."],"takhrij":"متفق عليه: رواه البخاري في النكاح ( 5080) ومسلم في الرضاع (715: 55) كلاهما من طريق شعبة، حدّثنا محارب قال: سمعت جابر بن عبد الله يقول: فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء أن الكفاءة هي الدين وحده، والترغيب في اختيار الزوجة الصالحة ذات الدين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5080) and Muslim (715:55).","chapter_en":"Chapter on what has been reported that compatibility is in religion alone, and encouraging the choice of a righteous, religious wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: I married a woman, so the Messenger of Allah ﷺ said to me, “Have you married?” I said, “Yes.” He said, “A virgin or a previously married woman?” I said, “A previously married woman.” He said, “Then where are you with young virgins and their playfulness?” Shu‘bah said: I mentioned it to ‘Amr ibn Dinar, and he said: I heard it from Jabir, and he only said: “Why not a young girl that you may play with her and she may play with you?”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5080,"lafz":true},{"key":"muslim","label":"مسلم","number":55},{"key":"muslim","label":"مسلم في الرضاع","number":715,"n":3637}],"full":1,"dr":1,"rep":[6199,6331]},{"num":6203,"demo":false,"sanad":"","matn":["عَنْ عَطَاءٍ، أَخْبَرَنِي جَابِرُ بْنُ عَبْدِ اللَّهِ، قَالَ تَزَوَّجْتُ امْرَأَةً فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَقِيتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ يَا جَابِرُ تَزَوَّجْتَ. قُلْتُ نَعَمْ. قَالَ بِكْرٌ أَمْ ثَيِّبٌ. قُلْتُ ثَيِّبٌ. قَالَ فَهَلاَّ بِكْرًا تُلاَعِبُهَا. قُلْتُ يَا رَسُولَ اللَّهِ إِنَّ لِي أَخَوَاتٍ فَخَشِيتُ أَنْ تَدْخُلَ بَيْنِي وَبَيْنَهُنَّ. قَالَ فَذَاكَ إِذًا. إِنَّ الْمَرْأَةَ تُنْكَحُ عَلَى دِينِهَا وَمَالِهَا وَجَمَالِهَا فَعَلَيْكَ بِذَاتِ الدِّينِ تَرِبَتْ يَدَاكَ."],"takhrij":"صحيح: رواه مسلم في الرضاع (54:715) عن محمد بن عبد الله بن نُمير، حدثنا أبي، حدثنا عبد الملك بن أبي سليمان، عن عطاء، أخبرني جابر بن عبد الله، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء أن الكفاءة هي الدين وحده، والترغيب في اختيار الزوجة الصالحة ذات الدين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (715:54).","chapter_en":"Chapter on what has been reported that compatibility is in religion alone, and encouraging the choice of a righteous, religious wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Jabir said: I married a woman during the time of the Messenger of Allah ﷺ, and the Prophet ﷺ met me and said, “O Jabir, have you married?” I said, “Yes.” He said, “A virgin or a previously married woman?” I said, “A previously married woman.” He said, “Why not a virgin, so that you may play with her?” I said, “O Messenger of Allah, I have sisters, and I feared that she would come between me and them.” He said, “Then that is fine. A woman is married for her religion, her wealth, and her beauty, so hold fast to the one with religion, may your hands be covered with dust.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":54,"lafz":true}],"full":1},{"num":6204,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تُنْكَحُ الْمَرْأَةُ عَلَى إِحْدَى خِصَالٍ ثَلَاثٍ: تُنْكَحُ الْمَرْأَةُ عَلَى مَالِهَا، وَتُنْكَحُ الْمَرْأَةُ عَلَى جَمَالِهَا، وَتُنْكَحُ الْمَرْأَةُ عَلَى دِينِهَا، فَخُذْ ذَاتَ الدِّينِ وَالْخُلُقِ تَرِبَتْ يَمِينُكَ."],"takhrij":"حسن: رواه أحمد ( 11765) وأبو يعلى (1012) والبزار – كشف الأستار (1403) وصحّحه ابن حبان (4037) والحاكم (2/161) كلهم من طريق محمد بن موسى الفطري المدني، عن سعد بن إسحاق، عن عمته، عن أبي سعيد الخدري فذكره.","grade":"حسن","chapter_ar":"باب ما جاء أن الكفاءة هي الدين وحده، والترغيب في اختيار الزوجة الصالحة ذات الدين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (11765), Abu Ya‘la (1012), al-Bazzar in Kashf al-Astar (1403), and authenticated by Ibn Hibban (4037).","chapter_en":"Chapter on what has been reported that compatibility is in religion alone, and encouraging the choice of a righteous, religious wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: The Messenger of Allah ﷺ said, “A woman is married for one of three qualities: she is married for her wealth, she is married for her beauty, and she is married for her religion. So take the one with religion and good character, may your right hand be covered with dust.”"]}},"tuhfa":{},"refs":[{"key":"sh12520","label":"أبو يعلى","number":1012},{"key":"sh12862","label":"البزار - كشف الأستار","number":1403},{"key":"ibnhibban","label":"صححه ابن حبان","number":4037},{"key":"ahmad","label":"مسند الإمام أحمد","number":11765,"n":11765,"lafz":true},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1219,"n":1216}],"full":1,"dr":1},{"num":6205,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ الدُّنْيَا مَتَاعٌ وَخَيْرُ مَتَاعِ الدُّنْيَا الْمَرْأَةُ الصَّالِحَةُ."],"takhrij":"صحيح: رواه مسلم في الرضاع (1467) عن محمد بن عبد الله بن نُمير الهَمْدانيّ، حدّثنا حَيْوة، أخبرني شرحبيل بن شريك، أنه سمع أبا عبد الرحمن الحبليّ يحدّث عن عبدالله بن عمروبن العاص فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء أن الكفاءة هي الدين وحده، والترغيب في اختيار الزوجة الصالحة ذات الدين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1467).","chapter_en":"Chapter on what has been reported that compatibility is in religion alone, and encouraging the choice of a righteous, religious wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["‘Abd Allah ibn ‘Amr reported that the Messenger of Allah ﷺ said: “This world is a temporary enjoyment, and the best enjoyment of this world is a righteous woman.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1467,"lafz":true,"n":3643}],"full":1},{"num":6206,"demo":false,"sanad":"","matn":["عَنْ سَهْلٍ، قَالَ مَرَّ رَجُلٌ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ مَا تَقُولُونَ فِي هَذَا. قَالُوا حَرِيٌّ إِنْ خَطَبَ أَنْ يُنْكَحَ، وَإِنْ شَفَعَ أَنْ يُشَفَّعَ، وَإِنْ قَالَ أَنْ يُسْتَمَعَ. قَالَ ثُمَّ سَكَتَ فَمَرَّ رَجُلٌ مِنَ فُقَرَاءِ الْمُسْلِمِينَ فَقَالَ مَا تَقُولُونَ فِي هَذَا. قَالُوا حَرِيٌّ إِنْ خَطَبَ أَنْ لاَ يُنْكَحَ وَإِنْ شَفَعَ أَنْ لاَ يُشَفَّعَ، وَإِنْ قَالَ أَنْ لاَ يُسْتَمَعَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَذَا خَيْرٌ مِنْ مِلْءِ الأَرْضِ مِثْلَ هَذَا."],"takhrij":"صحيح: رواه البخاري في النكاح (5091) عن إبراهيم بن حمزة، حدثنا ابن أبي حازم، عن أبيه، عن سهل، قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء أن الكفاءة هي الدين وحده، والترغيب في اختيار الزوجة الصالحة ذات الدين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5091).","chapter_en":"Chapter on what has been reported that compatibility is in religion alone, and encouraging the choice of a righteous, religious wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Sahl ibn Sa‘d said: A man passed by the Messenger of Allah ﷺ, and he said, “What do you say about this one?” They said: He is deserving, if he proposes, to be married to; if he intercedes, to have his intercession accepted; and if he speaks, to be listened to. Then he remained silent. Then a poor man from among the Muslims passed by, and he said, “What do you say about this one?” They said: He is deserving, if he proposes, not to be married to; if he intercedes, not to have his intercession accepted; and if he speaks, not to be listened to. So the Messenger of Allah ﷺ said, “This one is better than the whole earth filled with the likes of that one.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5091,"lafz":true}],"full":1},{"num":6207,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بن أَبِي وَقَّاصٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَرْبَعٌ مِنَ السَّعَادَةِ! الْمَرْأَةُ الصَّالِحَةُ، وَالْمَسْكَنُ الْوَاسِعُ، وَالْجَارُ الصَّالِحُ، وَالْمَرْكَبُ الْهَنِيءُ، وَأَرْبَعٌ مِنَ الشَّقَاوَةِ: الْجَارُ السُّوءُ، وَالْمَرْأَةُ السُّوءُ، وَالْمَسْكَنُ الضِّيقُ، وَالْمَرْكَبُ السُّوءُ."],"takhrij":"صحيح: رواه ابن حبان في صحيحه (4032) عن محمد بن إسحاق بن إبراهيم مولى ثقيف، قال: حدثنا محمد بن عبد العزيز بن أبي رِزقة، قال: حدثنا الفضل بن موسى، عن عبد الله بن سعيد بن أبي هند، عن إسماعيل بن محمد بن سعد، عن أبيه، عن جده فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء أن الكفاءة هي الدين وحده، والترغيب في اختيار الزوجة الصالحة ذات الدين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Hibban in his Sahih (4032).","chapter_en":"Chapter on what has been reported that compatibility is in religion alone, and encouraging the choice of a righteous, religious wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Sa‘d ibn Abi Waqqas said: The Messenger of Allah ﷺ said, “Four things are from happiness: a righteous wife, a spacious home, a good neighbor, and a comfortable mount. And four things are from misery: a bad neighbor, a bad wife, a cramped home, and a bad mount.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"ابن حبان في صحيحه","number":4032,"lafz":true},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4542,"n":4538}],"full":1,"dr":1,"rep":[14182]},{"num":6208,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ من أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: تَبًّا لِلذَّهَبِ وَالْفِضَّةِ قَالَ: فَانْطَلَقْتُ مَعَ عُمَرَ بْنِ الْخَطَّابِ فَقَالَ: يَا رَسُولَ اللَّهِ! قَوْلُكَ: تَبًّا لِلذَّهَبِ وَالْفِضَّةِ مَاذَا؟ فَقَالَ: لِسَانًا ذَاكِرًا وَقَلْبًا شَاكِرًا، زوجة تُعِينُ عَلَى الْآخِرَةِ."],"takhrij":"حسن: رواه أحمد (23101) عن محمد بن جعفر، حدثنا شعبة، حدثنا سَلْم قـال: سمعت عبد الله بن أبي الهذيل قـال: حدثني صاحب لي أن رسول الله صلى الله عليه وسلم قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء أن الكفاءة هي الدين وحده، والترغيب في اختيار الزوجة الصالحة ذات الدين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (23101).","chapter_en":"Chapter on what has been reported that compatibility is in religion alone, and encouraging the choice of a righteous, religious wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["A man from among the Companions of the Prophet ﷺ reported that the Messenger of Allah ﷺ said: “Woe to gold and silver.” He said: So I went with ‘Umar ibn al-Khattab, and he said: O Messenger of Allah, your statement, “Woe to gold and silver” - then what should one have? He said: “A tongue that remembers Allah, a grateful heart, a wife who helps one toward the Hereafter.”"]},"buhuth":{"en":["His statement, “Woe to gold and silver,” means destruction for the one who hoards them and does not pay their due alms.","His statement, “then what?” means: then what should we acquire, as in the narration of Thawban that comes later."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":23101,"n":23101,"lafz":true}],"full":1,"dr":1},{"num":6209,"demo":false,"sanad":"","matn":["عن فَاطِمَةَ بنت قَيْسٍ أَنَّ أَبَا عمرو بْنِ حفص طلقها البتة فذكرت الْحَدِيثَ. قَالَتْ: فَلَمَّا حَلَلْتُ ذَكَرْتُ لَهُ أَنَّ مُعَاوِيَةَ بْنَ أَبِي سُفْيَانَ وَأَبَا جَهْمِ بْنَ هِشَامٍ خَطَبَانِي. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَّا أَبُو جَهْمٍ فَلاَ يَضَعُ عَصَاهُ عَنْ عَاتِقِهِ وَأَمَّا مُعَاوِيَةُ فَصُعْلُوكٌ لاَ مَالَ لَهُ انْكِحِي أُسَامَةَ بْنَ زَيْدٍ. قَالَتْ فَكَرِهْتُهُ ثُمَّ قَالَ انْكِحِي أُسَامَةَ بْنَ زَيْدٍ. فَنَكَحْتُهُ فَجَعَلَ اللَّهُ فِي ذَلِكَ خَيْرًا وَاغْتَبَطْتُ بِهِ."],"takhrij":"صحيح: رواه مالك في الطلاق (73) عن عبد الله بن يزيد مولى الأسود بن سفيان، عن أبي سلمة، بن عبد الرحمن بن عوف، عن فاطمة بنت قيس فذكرته. ومن طريق مالك رواه مسلم في الطلاق (1480)","grade":"صحيح","chapter_ar":"باب تزوج المولى العربية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (73) and Muslim (1480).","chapter_en":"Chapter on a freedman marrying an Arab woman","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Fatimah bint Qays reported that Abu ‘Amr ibn Hafs divorced her irrevocably. She mentioned the rest of the narration and said: When my waiting period ended, I mentioned to the Prophet ﷺ that Mu‘awiyah ibn Abi Sufyan and Abu Jahm ibn Hisham had proposed to me. The Messenger of Allah ﷺ said: “As for Abu Jahm, he does not put down his staff from his shoulder; and as for Mu‘awiyah, he is poor and has no wealth. Marry Usamah ibn Zayd.” She said: I disliked him. Then he said: “Marry Usamah ibn Zayd.” So I married him, and Allah placed much good in that, and I was pleased with it."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":73,"lafz":true},{"key":"muslim","label":"مسلم","number":1480}],"full":1,"dr":1},{"num":6210,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ أَبَا حُذَيْفَةَ بْنَ عُتْبَةَ بْنِ رَبِيعَةَ بْنِ عَبْدِ شَمْسٍ،، وَكَانَ، مِمَّنْ شَهِدَ بَدْرًا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَبَنَّى سَالِمًا، وَأَنْكَحَهُ بِنْتَ أَخِيهِ هِنْدَ بِنْتَ الْوَلِيدِ بْنِ عُتْبَةَ بْنِ رَبِيعَةَ وَهْوَ مَوْلًى لاِمْرَأَةٍ مِنَ الأَنْصَارِ."],"takhrij":"صحيح: رواه البخاري في النكاح ( 5088) عن أبي اليمان، أخبرنا شُعيب عن الزهري، قال: أخبرني عروة بن الزبير، عن عائشة فذكرته مثله.","grade":"صحيح","chapter_ar":"باب تزوج المولى العربية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5088).","chapter_en":"Chapter on a freedman marrying an Arab woman","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["‘A’ishah reported that Abu Hudhayfah ibn ‘Utbah ibn Rabi‘ah ibn ‘Abd Shams - and he was among those who witnessed Badr with the Prophet ﷺ - had adopted Salim and married him to the daughter of his brother, Hind bint al-Walid ibn ‘Utbah ibn Rabi‘ah, and he was the freedman of a woman from the Ansar."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5088,"lafz":true}],"full":1},{"num":6211,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ أَبَا هِنْدٍ، حَجَمَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْيَافُوخِ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَا بَنِي بَيَاضَةَ أَنْكِحُوا أَبَا هِنْدٍ وَانْكِحُوا إِلَيْهِ. قَالَ وَإِنْ كَانَ فِي شَىْءٍ مِمَّا تَدَاوَوْنَ بِهِ خَيْرٌ فَالْحِجَامَةُ.","وفي رواية: كان حجاماً."],"takhrij":"حسن: رواه أبو داود (2102) عن عبد الواحد بن غياث، حدثنا حماد، حدثنا محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب لا يرد نكاح غير الكفء إذا رضيت المرأة ووليها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2102), al-Daraqutni (3/300–301), Ibn Hibban (4067), and al-Hakim (2/164).","chapter_en":"Chapter on not rejecting the marriage of one who is not socially equal if the woman and her guardian are pleased","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah reported that Abu Hind cupped the Prophet ﷺ on the crown of his head, so the Prophet ﷺ said to him: “O Banu Bayadah, marry Abu Hind [to your women], and seek his daughters in marriage.” And he said: “If there is any good in what you use for treatment, then it is cupping.” And in one narration: “He was a cupper.”"]},"buhuth":{"en":["His statement, “and seek marriage from him,” means: ask for his daughters in marriage."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2102,"lafz":true},{"key":"sh9771","label":"الدارقطني","number":3},{"key":"ibnhibban","label":"ابن حبان","number":4067},{"key":"hakim","label":"الحاكم","number":2}],"full":1,"dr":1},{"num":6212,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّهَا قَالَتْ: كَانَ فِي بَرِيرَةَ ثَلاَثُ سُنن، فَكَانَتْ إِحْدَى السُّنَنِ الثلاث أَنَّهَا أُعْتِقَتْ فخُيِّرتْ فِي زَوْجِهَا. وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْوَلاَءُ لِمَنْ أَعْتَقَ وَدَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالْبُرْمَةُ تَفُورُ بِلَحْمٍ فقُرّب إِلَيْهِ خُبْزٌ وَأُدْمٌ مِنْ أُدْمِ الْبَيْتِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَلَمْ أَرَ الْبُرْمَةَ فِيهَا لَحْمٌ؟ فقالو: بَلَى. يَا رَسُولُ اللَّهِ. وَلَكِنْ لَحْمٌ تُصُدِّقَ بِهِ عَلَى بَرِيرَةَ، وَأَنْتَ لاَ تَأْكُلُ الصَّدَقَةَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هُوَ عَلَيْهَا صَدَقَةٌ، وهو لَنَا هَدِيَّةٌ."],"takhrij":"متفق عليه: رواه مالك في الطلاق (29) عن ربيعة بن أبي عبد الرحمن، عن القاسم بن محمد، عن عائشة فذكرته. ورواه البخاري في الطلاق (5279)، ومسلم في الطلاق (1504: 14) كلاهما من طريق مالك، به.","grade":"متفق عليه","chapter_ar":"باب اعتبار الحرية في الكفاءة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (29), al-Bukhari (5279), and Muslim (1504:14).","chapter_en":"Chapter on considering freedom in compatibility","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["‘A’ishah said: There were three legal rulings connected to Barirah. One of those three rulings was that when she was freed, she was given the choice regarding her husband. And the Messenger of Allah ﷺ said: “The right of patronage belongs to the one who frees.” The Messenger of Allah ﷺ entered while a cooking pot was boiling with meat, and bread and ordinary household seasoning were brought near to him. The Messenger of Allah ﷺ said: “Did I not see the pot with meat in it?” They said: Yes, O Messenger of Allah, but it is meat that was given in charity to Barirah, and you do not eat charity. So the Messenger of Allah ﷺ said: “For her it is charity, and for us it is a gift.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":29,"lafz":true},{"key":"bukhari","label":"البخاري","number":5279},{"key":"muslim","label":"مسلم","number":14},{"key":"muslim","label":"مسلم في الطلاق","number":1504}],"full":1},{"num":6213,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، فِي قِصَّةِ بَرِيرَةَ قَالَتْ كَانَ زَوْجُهَا عَبْدًا فَخَيَّرَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَاخْتَارَتْ نَفْسَهَا وَلَوْ كَانَ حُرًّا لَمْ يُخَيِّرْهَا."],"takhrij":"صحيح: رواه مسلم في الطلاق (1504: 9) من طرق عن جرير بن عبد الحميد، عن هشام بن عروة، عن أبيه، عن عائشة فذكرته","grade":"صحيح","chapter_ar":"باب اعتبار الحرية في الكفاءة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1504:9).","chapter_en":"Chapter on considering freedom in compatibility","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["‘A’ishah, the wife of the Prophet ﷺ, said: The husband of Barirah was a slave, so the Messenger of Allah ﷺ gave her the choice, and she chose herself. If he had been a free man, he would not have given her that choice."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":9,"lafz":true},{"key":"muslim","label":"مسلم في الطلاق","number":1504,"n":3780}],"full":1,"dr":1},{"num":6214,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ زَوْجَ، بَرِيرَةَ كَانَ عَبْدًا يُقَالُ لَهُ مُغِيثٌ كَأَنِّي أَنْظُرُ إِلَيْهِ يَطُوفُ خَلْفَهَا يَبْكِي، وَدُمُوعُهُ تَسِيلُ عَلَى لِحْيَتِهِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِعَبَّاسٍ يَا عَبَّاسُ أَلاَ تَعْجَبُ مِنْ حُبِّ مُغِيثٍ بَرِيرَةَ، وَمِنْ بُغْضِ بَرِيرَةَ مُغِيثًا. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَوْ رَاجَعْتِهِ. قَالَتْ يَا رَسُولَ اللَّهِ تَأْمُرُنِي قَالَ إِنَّمَا أَنَا أَشْفَعُ. قَالَتْ لاَ حَاجَةَ لِي فِيهِ."],"takhrij":"صحيح: رواه البخاري في الطلاق (5283) عن محمد، أخبرنا عبدالوهاب حدثنا خالد، عن عكرمة، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب اعتبار الحرية في الكفاءة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5283).","chapter_en":"Chapter on considering freedom in compatibility","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Ibn ‘Abbas reported that the husband of Barirah was a slave named Mughith. It is as if I can still see him going around behind her, weeping, with tears flowing down his beard. Then the Prophet ﷺ said to al-‘Abbas: “O ‘Abbas, are you not amazed at the love of Mughith for Barirah, and the dislike of Barirah for Mughith?” Then the Prophet ﷺ said: “Why do you not return to him?” She said: O Messenger of Allah, are you commanding me? He said: “I am only interceding.” She said: I have no need of him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5283,"lafz":true}],"full":1,"rep":[6735]},{"num":6215,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ ذَاكَ مُغِيثٌ عَبْدُ بَنِي فُلاَنٍ ـ يَعْنِي زَوْجَ بَرِيرَةَ ـ كَأَنِّي أَنْظُرُ إِلَيْهِ يَتْبَعُهَا فِي سِكَكِ الْمَدِينَةِ، يَبْكِي عَلَيْهَا."],"takhrij":"صحيح: رواه البخاري في الطلاق (5281) عن عبد الأعلى بن حماد، حدثنا وُهيب، حدثنا أيوب، عن عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب اعتبار الحرية في الكفاءة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5281).","chapter_en":"Chapter on considering freedom in compatibility","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Ibn ‘Abbas said: That was Mughith, the slave of such-and-such people - meaning the husband of Barirah. It is as though I can still see him following her through the streets of Madinah, weeping over her."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5281,"lafz":true}],"full":1},{"num":6216,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ زَوْجَ بَرِيرَةَ كَانَ عَبْدًا أَسْوَدَ يُسَمَّى مُغِيثًا، قَالَ: فَكُنْتُ أَرَاهُ يَتْبَعُهَا فِي سِكَكِ الْمَدِينَةِ، يَعْصِرُ عَيْنَيْهِ عَلَيْهَا، قَالَ: وَقَضَى فِيهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَرْبَعَ قَضِيَّاتٍ: إِنَّ مَوَالِيَهَا اشْتَرَطُوا الْوَلاءَ، فَقَضَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْوَلاءَ لِمَنْ أَعْتَقَ وَخَيَّرَهَا، فَاخْتَارَتْ نَفْسَهَا، فَأَمَرَهَا أَنْ تَعْتَدَّ، قَالَ: وَتُصُدِّقَ عَلَيْهَا بِصَدَقَةٍ، فَأَهْدَتْ مِنْهَا إِلَى عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا، فَذَكَرَتْ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: هُوَ عَلَيْهَا صَدَقَةٌ، وَإِلَيْنَا هَدِيَّةٌ."],"takhrij":"صحيح: رواه أحمد (2542) والطبراني (11826) والبيهقي (7/221-222) كلهم من حديث همام قال: أخبرنا قتادة، عن عكرمة، عن ابن عباس فذكره. وإسناده صحيح، وهو من هذا الوجه في صحيح البخاري (5280) مختصرا بقول ابن عباس: رأيته عبداً- يعني زوج بريرة.","grade":"صحيح","chapter_ar":"باب اعتبار الحرية في الكفاءة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (2542), al-Tabarani (11826), and al-Bayhaqi (7/221–222).","chapter_en":"Chapter on considering freedom in compatibility","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Ibn ‘Abbas reported that the husband of Barirah was a black slave named Mughith. He said: I used to see him following her through the streets of Madinah, crying over her. He said: The Prophet ﷺ gave four rulings regarding her case: her masters had stipulated that the right of patronage would remain with them, so the Prophet ﷺ ruled, “The right of patronage belongs to the one who frees.” He gave her the choice, and she chose herself. He ordered her to observe her waiting period. And charity was given to her, then she gifted some of it to ‘A’ishah, and when that was mentioned to the Prophet ﷺ he said, “For her it is charity, and for us it is a gift.”"]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني","number":11826},{"key":"kubrabayhaqi","label":"البيهقي","number":222},{"key":"ahmad","label":"مسند الإمام أحمد","number":2542,"n":2542,"lafz":true},{"key":"bukhari","label":"من هذا الوجه في صحيح البخاري","number":5280}],"full":1},{"num":6217,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيَّرَ بَرِيرَةَ."],"takhrij":"صحيح: رواه ابن ماجة (2078) عن إسماعيل بن ثوبة، حدثنا عباد بن العوّام، عن يحيى بن أبي إسحاق، عن عبدالرحمن بن أُذَينة، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب اعتبار الحرية في الكفاءة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2078).","chapter_en":"Chapter on considering freedom in compatibility","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ gave Barirah the choice."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2078,"lafz":true}],"full":1},{"num":6218,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ عَدْوَى وَلاَ طِيَرَةَ وَلاَ هَامَةَ وَلاَ صَفَرَ، وَفِرَّ مِنَ الْمَجْذُومِ كَمَا تَفِرُّ مِنَ الأَسَدِ."],"takhrij":"صحيح: رواه البخاري في الطب (5807) قال: وقال عفان، حدثنا سليم بن حيان، حدثنا سعيد بن ميناء قال: سمعت أبا هريرة يقول: فذكره","grade":"صحيح","chapter_ar":"باب اعتبار السلامة من العيوب في الكفاءة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5707).","chapter_en":"Chapter on considering freedom from defects in suitability","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said, “There is no contagious transmission by itself, no evil omen, no owl-omen, and no bad luck in Safar; and flee from the leper as you would flee from a lion.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5707},{"key":"bukhari","label":"البخاري في الطب","number":5807,"lafz":true,"n":5707}],"full":1,"rep":[11635,11651]},{"num":6219,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  لاَ يُورِدُ الْمُمْرِضُ عَلَى الْمُصِحِّ."],"takhrij":"متفق عليه: رواه البخاري في الطب (5774) ومسلم في السلام، كلاهما من حديث ابن شهاب، عن أبي سلمة بن عبدالله بن عوف، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب اعتبار السلامة من العيوب في الكفاءة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5774) and Muslim (2221) in the Book of Greetings.","chapter_en":"Chapter on considering freedom from defects in suitability","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said, “A diseased animal should not be brought to one that is healthy.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5774,"lafz":true,"n":5533},{"key":"muslim","label":"مسلم","number":2221,"n":5792}],"full":1,"dr":1,"rep":[11650]},{"num":6220,"demo":false,"sanad":"","matn":["عن فَاطِمَةَ بنت قَيْسٍ تَقُولُ إِنَّ زَوْجَهَا طَلَّقَهَا ثَلاَثًا فَلَمْ يَجْعَلْ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُكْنَى وَلاَ نَفَقَةً قَالَتْ قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا حَلَلْتِ فَآذِنِينِي. فَآذَنْتُهُ فَخَطَبَهَا مُعَاوِيَةُ وَأَبُو جَهْمٍ وَأُسَامَةُ بْنُ زَيْدٍ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَّا مُعَاوِيَةُ فَرَجُلٌ تَرِبٌ لاَ مَالَ لَهُ وَأَمَّا أَبُو جَهْمٍ فَرَجُلٌ ضَرَّابٌ لِلنِّسَاءِ وَلَكِنْ أُسَامَةُ بْنُ زَيْدٍ."],"takhrij":"صحيح: رواه مسلم في الطلاق (1480: 47) عن أبي بكر بن أبي شيبة، حدثنا وكيع، حدثنا سفيان، عن أبي بكر بن الجهم بن صُخير العدوى قـال: سمعت فاطمة بنت قيس تقول: فذكرته.","grade":"صحيح","chapter_ar":"باب الترغيب في اختيار الزوج الصالح سواء كان له مال أم لا","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1480:47).","chapter_en":"Chapter on encouraging the choice of a righteous husband whether he has wealth or not","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Fatimah bint Qays said: Her husband divorced her with a final triple divorce, and the Messenger of Allah ﷺ did not assign for her housing or maintenance. She said: The Messenger of Allah ﷺ said to me, “When your waiting period ends, inform me.” So I informed him. Then Mu‘awiyah, Abu Jahm, and Usamah ibn Zayd proposed to her, and the Messenger of Allah ﷺ said, “As for Mu‘awiyah, he is a poor man with no wealth. As for Abu Jahm, he is a man who beats women. But Usamah ibn Zayd…”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":47,"lafz":true},{"key":"muslim","label":"مسلم في الطلاق","number":1480,"n":3712}],"full":1},{"num":6221,"demo":false,"sanad":"","matn":["عَنْ أَبِيهِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ أَحْسَابَ أَهْلِ الدُّنْيَا الَّذِي يَذْهَبُونَ إِلَيْهِ هَذَا الْمَالُ."],"takhrij":"حسن: رواه النسائي (3225) وأحمد (22990) والقضاعي في مسند الشهاب (982) وصحّحه ابن حبان (699، 700) والحاكم (2/163) والبيهقي (7/135) كلهم من حديث حسين بن واقد قال: حدثني عبد الله بن بريدة، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب الترغيب في اختيار الزوج الصالح سواء كان له مال أم لا","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (3225), Ahmad (22990), and authenticated by Ibn Hibban (699).","chapter_en":"Chapter on encouraging the choice of a righteous husband whether he has wealth or not","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Buraydah said: The Messenger of Allah ﷺ said, “What the people of this world regard as status is this wealth.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3225,"lafz":true,"n":3225},{"key":"ibnhibban","label":"صححه ابن حبان","number":699,"n":4552},{"key":"ahmad","label":"مسند الإمام أحمد","number":22990,"n":22990},{"key":"ibnhibban","label":"ابن حبان","number":700}],"full":1,"dr":1,"rep":[15243]},{"num":6222,"demo":false,"sanad":"","matn":["عن مسروق وعمرو بن عتبة أنهما كتبا إلى سبيعة بنت الحارث يسألانها عن أمرها، فكتبتْ لهما ...-الحديث مطوّلا كما سيأتي-، وفي آخره أن رسول الله صلى الله عليه وسلم قال: إنْ وجدتِّ زوجاً صالحًا فتزوّجي."],"takhrij":"صحيح: رواه ابن ماجه (2028) عن أبي بكر بن أبي شيبة، حدثنا علي بن مسهر، عن داود بن أبي هند، عن الشعبي، عن مسروق وعمرو بن عتبة فذكراه. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب الترغيب في اختيار الزوج الصالح سواء كان له مال أم لا","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2028).","chapter_en":"Chapter on encouraging the choice of a righteous husband whether he has wealth or not","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Masruq and ‘Amr ibn ‘Utbah wrote to Subay‘ah bint al-Harith asking her about her case - and she wrote back to them the full narration, which will come later - and at its end the Messenger of Allah ﷺ said: “If you find a righteous husband, then marry.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2028,"lafz":true}],"full":1},{"num":6223,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ خَيْرُ نِسَاءٍ رَكِبْنَ الإِبِلَ صَالِحُو نِسَاءِ قُرَيْشٍ، أَحْنَاهُ عَلَى وَلَدٍ فِي صِغَرِهِ وَأَرْعَاهُ عَلَى زَوْجٍ فِي ذَاتِ يَدِهِ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5082) ومسلم في فضائل الصحابة (2527) كلاهما من حديث أبي الزناد، عن الأعرج، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب ذكر صفات خير النساء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5082) and Muslim (2527).","chapter_en":"Chapter on mentioning the qualities of the best women","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["Abu Hurayrah reported from the Prophet ﷺ that he said: “The best women who have ridden camels are the righteous women of Quraysh: the most compassionate toward a child in his young age, and the most careful regarding her husband’s wealth.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5082,"lafz":true},{"key":"muslim","label":"مسلم","number":2527,"n":6460}],"full":1,"rep":[6325]},{"num":6224,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَطَبَ أُمَّ هَانِئٍ بِنْتَ أَبِي طَالِبٍ. فَقَالَتْ: يَا رَسُولَ اللَّهِ إِنِّي قَدْ كَبِرْتُ وَلِيَ عِيَالٌ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: خَيْرُ نِسَاءٍ رَكِبْنَ الإِبِلَ، نِسَاءٍ قُرَيْشٍ، أَحْنَاهُ عَلَى وَلَدٍ فِي صِغَرِهِ."],"takhrij":"صحيح: رواه مسلم في فضائل الصحابة (2527: 201) من طريق عبد الرزاق، أخبرنا معمر، عن الزهري، عن ابن المسيب، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ذكر صفات خير النساء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2527:201).","chapter_en":"Chapter on mentioning the qualities of the best women","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ proposed to Umm Hani’ bint Abi Talib. She said: “O Messenger of Allah, I have grown old and I have dependents.” So the Messenger of Allah ﷺ said, “The best women who have ridden camels are the women of Quraysh, the most compassionate toward a child in his young age.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":201,"lafz":true},{"key":"muslim","label":"مسلم في فضائل الصحابه","number":2527,"n":6459}],"full":1,"dr":1,"rep":[10462]},{"num":6225,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قِيلَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَىُّ النِّسَاءِ خَيْرٌ قَالَ الَّتِي تَسُرُّهُ إِذَا نَظَرَ وَتُطِيعُهُ إِذَا أَمَرَ وَلاَ تُخَالِفُهُ فِي نَفْسِهَا وَمَالِهَا بِمَا يَكْرَهُ."],"takhrij":"حسن: رواه النسائي (3231) عن قتيبة بن سعيد، حدثنا الليث، عن ابن عجلان، عن سعيد بن أبي سعيد المقبري، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ذكر صفات خير النساء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (3231), Ahmad (7421), and al-Bayhaqi (7/82).","chapter_en":"Chapter on mentioning the qualities of the best women","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["Abu Hurayrah said: It was said, “O Messenger of Allah, which women are best?” He said, “The one who pleases him when he looks at her, obeys him when he commands her, and does not oppose him concerning herself or his wealth in a way he dislikes.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3231,"lafz":true,"n":3231},{"key":"kubrabayhaqi","label":"البيهقي","number":82},{"key":"ahmad","label":"مسند الإمام أحمد","number":7421,"n":7421}],"full":1,"dr":1},{"num":6226,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن سلاّم أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: خَيْرُ النِّسَاءِ تَسُرُّكَ إِذَا أَبْصَرْتَ وَتُطِيعُكَ إِذَا أَمَرْتَ وَتَحْفَظُ غَيْبَتَكَ فِي نَفْسِهَا وَمَالِكَ."],"takhrij":"حسن: رواه الطبراني في الكبير (14/338 رقم 14969) عن العباس بن الفضل الأسفاطي، حدثنا موسى بن إسماعيل، حدثنا زُريك بن أبي زُريك، عن معاوية بن قُرّة، عن عبدالله بن سلاّم قال: فذكره.","grade":"حسن","chapter_ar":"باب ذكر صفات خير النساء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Mu‘jam al-Kabir (14/338, no. 14969).","chapter_en":"Chapter on mentioning the qualities of the best women","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["‘Abd Allah ibn Salam reported that the Messenger of Allah ﷺ said: “The best of women is the one who pleases you when you see her, obeys you when you command her, and guards your absence regarding herself and your wealth.”"]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":338,"lafz":true}],"full":1,"dr":1},{"num":6227,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: قَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أيهما امْرَأَةٍ تزوجتْ بِغَيْرِ إِذْنِ وَلِيِّهَا فَنِكَاحُهَا بَاطِلٌ، فَإِنْ دَخَلَ بِهَا فَلَهَا الْمَهْرُ بِمَا اسْتَحَلَّ مِنْ فَرْجِهَا، وَإِنْ اشْتَجَرُوا فَالسُّلْطَانُ وَلِيُّ مَنْ لاَ وَلِيَّ لَهُ."],"takhrij":"حسن: رواه أبو داود (2083) والترمذي (1102) وابن ماجة (1879) وصحّحه ابن حبان (4074) والحاكم (2/168) والبيهقي (7/105) كلهم من حديث ابن جريج، قال: أخبرني سليمان بن موسى أن ابن شهاب أخبره، أن عروة أخبره أن عائشة أخبرته أن النبي صلى الله عليه وسلم قال: فذكرته.","grade":"حسن","chapter_ar":"باب لا نكاح إلا بولي","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2083), al-Tirmidhi (1102), Ibn Majah (1879), and authenticated by Ibn Hibban (4074).","chapter_en":"There is no marriage except with a guardian","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":17,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ said, “Any woman who marries without the permission of her guardian, then her marriage is invalid. If he has consummated the marriage with her, then she is entitled to the dowry because he made her private part lawful for himself. And if they dispute, then the ruler is the guardian of the one who has no guardian.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2083,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1102},{"key":"ibnmajah","label":"ابن ماجه","number":1879},{"key":"ibnhibban","label":"صححه ابن حبان","number":4074}],"full":1,"dr":1},{"num":6228,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى الأشعري قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ نِكَاحَ إِلاَّ بِوَلِيٍّ."],"takhrij":"صحيح: رواه أبو داود (2085) والترمذي (1101) وابن ماجة (1881) وصحّحه ابن حبان (4077، 4078) والحاكم (2/169) والبيهقي (7/107) كلهم من طريق أبي إسحاق الهمداني، عن أبي بردة، عن أبي موسى فذكره.","grade":"صحيح","chapter_ar":"باب لا نكاح إلا بولي","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2085), al-Tirmidhi (1101), Ibn Majah (1881), and authenticated by Ibn Hibban (4078, 4077).","chapter_en":"There is no marriage except with a guardian","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":17,"content":{"translation":{"en":["Abu Musa al-Ash‘ari said: The Messenger of Allah ﷺ said, “There is no marriage except with a guardian.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2085,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1101},{"key":"ibnmajah","label":"ابن ماجه","number":1881},{"key":"ibnhibban","label":"صححه ابن حبان","number":4078,"n":4070},{"key":"ibnhibban","label":"ابن حبان","number":4077}],"full":1,"dr":1},{"num":6229,"demo":false,"sanad":"","matn":["عَنْ أُمِّ حَبِيبَةَ، أَنَّهَا كَانَتْ عِنْدَ ابْنِ جَحْشٍ فَهَلَكَ عَنْهَا - وَكَانَ فِيمَنْ هَاجَرَ إِلَى أَرْضِ الْحَبَشَةِ - فَزَوَّجَهَا النَّجَاشِيُّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهِيَ عِنْدَهُمْ."],"takhrij":"صحيح: رواه أبو داود (2086) عن محمد بن يحيى بن فارس، حدثنا عبد الرزاق، عن معمر، عن الزهري، عن عروة بن الزبير، عن أم حبيبة فذكرته.","grade":"صحيح","chapter_ar":"باب لا نكاح إلا بولي","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2086).","chapter_en":"There is no marriage except with a guardian","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":17,"content":{"translation":{"en":["Umm Habibah reported that she had been married to Ibn Jahsh, then he died while they were among those who had migrated to Abyssinia. Then the Negus married her to the Messenger of Allah ﷺ while she was there with them."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2086,"lafz":true}],"full":1,"dr":1},{"num":6230,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا نِكَاحَ إِلَاّ بِوَلِيٍّ وَشَاهِدَيْ عَدْلٍ، وَمَا كَانَ مِنْ نِكَاحٍ عَلَى غَيْرِ ذَلِكَ، فَهُوَ بَاطِلٌ، فَإِنْ تَشَاجَرُوا فَالسُّلْطَانُ وَلِيُّ مَنْ لَا وَلِيَّ لَهُ."],"takhrij":"حسن: رواه ابن حبان (4075) عن عمر بن محمد الهمداني من أصل كتابه، حدثنا سعيد بن يحيى بن سعيد الأموي، حدثنا حفص بن غياث، عن ابن جريج، عن سليمان بن موسى، عن الزهري، عن عروة، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب لا نكاح إلا بشاهدين عدلين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Hibban (4075).","chapter_en":"There is no marriage except with two just witnesses","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ said, “There is no marriage except with a guardian and two just witnesses. Any marriage other than that is invalid. If they dispute, then the ruler is the guardian of the one who has no guardian.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1364,"n":1361},{"key":"ibnhibban","label":"ابن حبان","number":4075,"lafz":true}],"full":1,"dr":1},{"num":6231,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ أَيُّمَا امْرَأَةٍ زَوَّجَهَا وَلِيَّانِ فَهِيَ لِلأَوَّلِ مِنْهُمَا وَأَيُّمَا رَجُلٍ بَاعَ بَيْعًا مِنْ رَجُلَيْنِ فَهُوَ لِلأَوَّلِ مِنْهُمَا."],"takhrij":"صحيح: رواه أبو داود (2088) والترمذي (1110) وابن ماجة (2190) وأحمد (20085) والحاكم (2/174-175) والبيهقي (7/139-141) كلهم من طرق عن قتادة، عن الحسن، عن سمرة، عن النبي صلى الله عليه وسلم فذكره.","grade":"صحيح","chapter_ar":"باب إذا نكح وليّان","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2088), al-Tirmidhi (1110), Ibn Majah (2190), and Ahmad (20085).","chapter_en":"If two guardians marry off the same woman","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Samurah reported from the Prophet ﷺ that he said: “Any woman whom two guardians marry off, then she belongs to the first of them. And any man who sells one sale to two men, it belongs to the first of them.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2088,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1110},{"key":"ibnmajah","label":"ابن ماجه","number":2190},{"key":"ahmad","label":"مسند الإمام أحمد","number":20085,"n":20085}],"full":1,"dr":1},{"num":6232,"demo":false,"sanad":"","matn":["عن سالم بن عَبْدِ اللَّهِ أَنَّهُ سَمِعَ عَبْدَ اللَّهِ بْنَ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا يُحَدِّثُ أَنَّ عُمَرَ بْنَ الْخَطَّابِ حِينَ تَأَيَّمَتْ حَفْصَةُ بِنْتُ عُمَرَ مِنْ خُنَيْسِ بْنِ حُذَافَةَ السَّهْمِيِّ ـ وَكَانَ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَتُوُفِّيَ بِالْمَدِينَةِ ـ فَقَالَ عُمَرُ بْنُ الْخَطَّابِ أَتَيْتُ عُثْمَانَ بْنَ عَفَّانَ فَعَرَضْتُ عَلَيْهِ حَفْصَةَ فَقَالَ سَأَنْظُرُ فِي أَمْرِي. فَلَبِثْتُ لَيَالِيَ ثُمَّ لَقِيَنِي فَقَالَ قَدْ بَدَا لِي أَنْ لاَ أَتَزَوَّجَ يَوْمِي هَذَا. قَالَ عُمَرُ فَلَقِيتُ أَبَا بَكْرٍ الصِّدِّيقَ فَقُلْتُ إِنْ شِئْتَ زَوَّجْتُكَ حَفْصَةَ بِنْتَ عُمَرَ. فَصَمَتَ أَبُو بَكْرٍ فَلَمْ يَرْجِعْ إِلَىَّ شَيْئًا، وَكُنْتُ أَوْجَدَ عَلَيْهِ مِنِّي عَلَى عُثْمَانَ، فَلَبِثْتُ لَيَالِيَ ثُمَّ خَطَبَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَنْكَحْتُهَا إِيَّاهُ، فَلَقِيَنِي أَبُو بَكْرٍ فَقَالَ لَعَلَّكَ وَجَدْتَ عَلَىَّ حِينَ عَرَضْتَ عَلَىَّ حَفْصَةَ فَلَمْ أَرْجِعْ إِلَيْكَ شَيْئًا. قَالَ عُمَرُ قُلْتُ نَعَمْ. قَالَ أَبُو بَكْرٍ فَإِنَّهُ لَمْ يَمْنَعْنِي أَنْ أَرْجِعَ إِلَيْكَ فِيمَا عَرَضْتَ عَلَىَّ إِلاَّ أَنِّي كُنْتُ عَلِمْتُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ ذَكَرَهَا، فَلَمْ أَكُنْ لأُفْشِيَ سِرَّ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَوْ تَرَكَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَبِلْتُهَا."],"takhrij":"صحيح: رواه البخاري في النكاح (5122) عن عبد العزيز بن عبد الله، حدّثنا إبراهيم بن سعد، عن صالح بن كيسان، عن ابن شهاب قال: أخبرني سالم بن عبد الله، به.","grade":"صحيح","chapter_ar":"باب عرض الإنسان ابنته أو أخته على أهل الصلاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5122).","chapter_en":"Chapter on a man offering his daughter or sister to righteous people","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":20,"content":{"translation":{"en":["Salim ibn ‘Abd Allah reported that he heard ‘Abd Allah ibn ‘Umar narrating: When Hafsah bint ‘Umar became widowed after Khunays ibn Hudhafah al-Sahmi - who had been one of the Companions of the Messenger of Allah ﷺ and had died in Madinah - ‘Umar ibn al-Khattab said: I went to ‘Uthman ibn ‘Affan and offered Hafsah to him, and he said: “I will consider my matter.” A few nights passed, then he met me and said: “It seems to me that I should not marry at this time.” ‘Umar said: Then I met Abu Bakr al-Siddiq and said: “If you wish, I will marry Hafsah bint ‘Umar to you.” Abu Bakr remained silent and gave me no reply, and I was more upset with him than with ‘Uthman. Then a few nights passed, and the Messenger of Allah ﷺ proposed to her, so I married her to him. Then Abu Bakr met me and said: “Perhaps you were upset with me when you offered Hafsah to me and I gave you no response?” ‘Umar said: I said, “Yes.” Abu Bakr said: “Nothing prevented me from replying to you except that I knew the Messenger of Allah ﷺ had mentioned her, and I would never disclose the secret of the Messenger of Allah ﷺ. Had the Messenger of Allah ﷺ left her, I would have accepted her.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5122,"lafz":true}],"full":1,"rep":[9412]},{"num":6233,"demo":false,"sanad":"","matn":["عَنْ أُمِّ حَبِيبَةَ بِنْتِ أَبِي سُفْيَانَ، قَالَتْ دَخَلَ عَلَىَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ لَهُ هَلْ لَكَ فِي أُخْتِي بِنْتِ أَبِي سُفْيَانَ فَقَالَ أَفْعَلُ مَاذَا. قُلْتُ تَنْكِحُهَا. قَالَ أَوَتُحِبِّينَ ذَلِكَ. قُلْتُ لَسْتُ لَكَ بِمُخْلِيَةٍ وَأَحَبُّ مَنْ شَرِكَنِي فِي الْخَيْرِ أُخْتِي."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5101) من طريق الزهري، ومسلم في الرضاع (1449: 15) من طريق هشام ( هو ابن عروة)- كلاهما عن عروة بن الزبير، عن زينب بنت أم سلمة، عن أم حبيبة بنت أبي سفيان، قالت فذكرته، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب عرض الإنسان ابنته أو أخته على أهل الصلاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5101) and Muslim (1449:15), and this wording is that of Muslim.","chapter_en":"Chapter on a man offering his daughter or sister to righteous people","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":20,"content":{"translation":{"en":["Umm Habibah bint Abi Sufyan said: The Messenger of Allah ﷺ entered upon me, and I said to him, “Would you like my sister, the daughter of Abu Sufyan?” He said, “What would I do?” I said, “Marry her.” He said, “Would you like that?” I said, “I am not the only one for you, and the one I would most love to share in good with me is my sister…”"]},"buhuth":{"en":["Her saying, “I am not the only one for you,” means: I am not alone with you and not free from having a co-wife."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5101,"lafz":true},{"key":"muslim","label":"مسلم","number":15},{"key":"muslim","label":"مسلم في الرضاع","number":1449}],"full":1,"dr":1},{"num":6234,"demo":false,"sanad":"","matn":["عَنْ سَهْلٍ، أَنَّ امْرَأَةً، عَرَضَتْ نَفْسَهَا عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لَهُ رَجُلٌ يَا رَسُولَ اللَّهِ زَوِّجْنِيهَا. فَقَالَ مَا عِنْدَكَ. قَالَ مَا عِنْدِي شَىْءٌ. قَالَ اذْهَبْ فَالْتَمِسْ وَلَوْ خَاتَمًا مِنْ حَدِيدٍ. فَذَهَبَ ثُمَّ رَجَعَ فَقَالَ لاَ وَاللَّهِ مَا وَجَدْتُ شَيْئًا، وَلاَ خَاتَمًا مِنْ حَدِيدٍ، وَلَكِنْ هَذَا إِزَارِي وَلَهَا نِصْفُهُ ـ قَالَ سَهْلٌ وَمَا لَهُ رِدَاءٌ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَا تَصْنَعُ بِإِزَارِكَ إِنْ لَبِسْتَهُ لَمْ يَكُنْ عَلَيْهَا مِنْهُ شَىْءٌ، وَإِنْ لَبِسَتْهُ لَمْ يَكُنْ عَلَيْكَ مِنْهُ شَىْءٌ. فَجَلَسَ الرَّجُلُ حَتَّى إِذَا طَالَ مَجْلَسُهُ قَامَ فَرَآهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَدَعَاهُ أَوْ دُعِي لَهُ فَقَالَ مَاذَا مَعَكَ مِنَ الْقُرْآنِ. فَقَالَ مَعِي سُورَةُ كَذَا وَسُورَةُ كَذَا لِسُوَرٍ يُعَدِّدُهَا. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمْلَكْنَاكَهَا بِمَا مَعَكَ مِنَ الْقُرْآنِ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5121)، ومسلم في النكاح (1425) من طريق أبي حازم، عن سهل بن سعد، فذكره. واللفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب عرض المرأة نفسها على النبي ﷺ","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5121) and Muslim (1425). The wording here is that of al-Bukhari.","chapter_en":"Chapter on a woman offering herself to the Prophet ﷺ","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":21,"content":{"translation":{"en":["Sahl ibn Sa‘d reported that a woman offered herself to the Prophet ﷺ. Then a man said to him: “O Messenger of Allah, marry her to me.” He said, “What do you have?” He said, “I have nothing.” He said, “Go and look, even if only for an iron ring.” So he went and returned and said, “No, by Allah, I found nothing, not even an iron ring. But this is my waist-wrapper, and she may have half of it.” Sahl said: He did not even have an upper garment. So the Prophet ﷺ said, “What would she do with your waist-wrapper? If you wear it, she will have nothing of it, and if she wears it, you will have nothing of it.” The man sat until his sitting became long, then he stood up. The Prophet ﷺ saw him and called him - or he was called for. He said to him, “What do you have from the Qur’an?” He said, “I have such-and-such surah and such-and-such surah,” listing several surahs. Then the Prophet ﷺ said, “We have married her to you in exchange for what you have of the Qur’an.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5121,"lafz":true},{"key":"muslim","label":"مسلم","number":1425}],"full":1,"rep":[13085]},{"num":6235,"demo":false,"sanad":"","matn":["عَنْ أنس بْنِ مَالِكٍ قَالَ: جَاءَتِ امْرَأَةٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَعْرِضُ عَلَيْهِ نَفْسَهَا قَالَتْ: يَا رَسُولَ اللَّهِ، أَلَكَ بِي حَاجَةٌ؟ فَقَالَتْ بِنْتُ أَنَسٍ: مَا أقلّ حَيَاءَهَا وَاسَوْأَتَاهْ. قَالَ: هِيَ خَيْرٌ مِنْكِ. رَغِبَتْ فِي النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَعَرَضَتْ عَلَيْهِ نَفْسَهَا."],"takhrij":"صحيح: رواه البخاري في النكاح (5120) عن علي بن عبدالله، حدّثنا مرحوم، قال سمعت ثابتاً البناني قال: كنتُ عند أنسٍ وعنده ابنة له، قال أنس: فذكره.","grade":"صحيح","chapter_ar":"باب عرض المرأة نفسها على النبي ﷺ","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5120).","chapter_en":"Chapter on a woman offering herself to the Prophet ﷺ","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":21,"content":{"translation":{"en":["Anas ibn Malik said: A woman came to the Messenger of Allah ﷺ offering herself to him. She said, “O Messenger of Allah, do you have any need of me?” The daughter of Anas said, “How little modesty she had! What a shame!” He said: She was better than you; she desired the Prophet ﷺ, so she offered herself to him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5120,"lafz":true}],"full":1},{"num":6236,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كُنْتُ أَغَارُ عَلَى اللاَّتِي وهَبْن أَنْفُسَهُنَّ لِرَسُولِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَقُولُ: تهب الْمَرْأَةُ نَفْسَهَا؟ فَلَمَّا نَزَلَ قوله تَعَالَى: ﴿تُرْجِي مَنْ تَشَاءُ مِنْهُنَّ وَتُؤْوِي إِلَيْكَ مَنْ تَشَاءُ وَمَنِ ابْتَغَيْتَ مِمَّنْ عَزَلْتَ﴾ [ الأحزاب: ٥١] قَالَتْ: قُلْتُ: وَاللَّهِ مَا أَرَى رَبَّكَ إِلاَّ يُسَارِعُ لَكَ فِي هَوَاكَ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4788) ومسلم في الرضاع (1463) كلاهما من حديث أبي أسامة، عن هشام، عن أبيه، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب عرض المرأة نفسها على النبي ﷺ","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4788) and Muslim (1463).","chapter_en":"Chapter on a woman offering herself to the Prophet ﷺ","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":21,"content":{"translation":{"en":["‘A’ishah said: I used to feel jealous of those women who offered themselves to the Messenger of Allah ﷺ, and I would say, “Does a woman offer herself?” Then when the saying of Allah Most High was revealed: “You may defer whom you will of them and take to yourself whom you will, and whomever you desire of those you had set aside - there is no blame upon you.” [Al-Ahzab: 51] she said: I said, “By Allah, I see that your Lord hastens to fulfill what pleases you.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4788,"lafz":true},{"key":"muslim","label":"مسلم","number":1463,"n":3631}],"full":1},{"num":6237,"demo":false,"sanad":"","matn":["عَنْ أَبِيهِ، قَالَ كَانَتْ خَوْلَةُ بِنْتُ حَكِيمٍ مِنَ اللاَّئِي وَهَبْنَ أَنْفُسَهُنَّ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ عَائِشَةُ أَمَا تَسْتَحِي الْمَرْأَةُ أَنْ تَهَبَ نَفْسَهَا لِلرَّجُلِ فَلَمَّا نَزَلَتْ {تُرْجِئُ مَنْ تَشَاءُ مِنْهُنَّ} قُلْتُ يَا رَسُولَ اللَّهِ مَا أَرَى رَبَّكَ إِلاَّ يُسَارِعُ فِي هَوَاكَ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5113) عن محمد بن سلام، حدثنا ابن فُضيل، حدثنا هشام بن عروة، عن أبيه فذكره.","grade":"متفق عليه","chapter_ar":"باب عرض المرأة نفسها على النبي ﷺ","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5113) and Muslim (1464/50).","chapter_en":"Chapter on a woman offering herself to the Prophet ﷺ","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":21,"content":{"translation":{"en":["ʿUrwah reported: Khawlah bint Ḥakīm was among the women who offered themselves in marriage to the Prophet ﷺ. ʿĀʾishah said: “Does a woman not feel shy to offer herself to a man?” Then when the verse was revealed: “You may defer whom you wish of them…” [al-Aḥzāb: 51] I said: “O Messenger of Allah, I see that your Lord hastens to fulfill what pleases you.”"]},"buhuth":{"en":["The word “turjī” means: you may defer whichever of the women who offered themselves you wish.","“And you may take in” means: you may accept whichever of them you wish and put aside whichever you wish; and even one whom you previously put aside remains subject to your choice afterward—if you wish, you may return to her and accept her.","Her expression “what you desire” means what pleases you. Jealousy caused her to phrase it in that manner; attributing mere personal whim to the Prophet ﷺ is not intended literally, because he does not speak from whim nor act from whim."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5113,"lafz":true},{"key":"muslim","label":"مسلم","number":1464}],"full":1,"dr":1,"rep":[13089]},{"num":6238,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ قَالَ: خَطَبَ أَبُو بَكْرٍ وَعُمَرُ فَاطِمَةَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّهَا صَغِيرَةٌ فَخَطَبَهَا عليٌّ، فَزَوَّجَهَا مِنْهُ."],"takhrij":"حسن: رواه النسائي (3221) عن الحسين بن حريث، قال: ثنا الفضل بن موسى، عن الحسين بن واقد، عن عبد الله بن بريدة، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب استحباب تزوج المرأة مثلها في السن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (3221).","chapter_en":"Chapter on the recommendation of marrying a woman near one’s age","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":22,"content":{"translation":{"en":["Buraydah said: Abu Bakr and ‘Umar proposed marriage to Fatimah, and the Messenger of Allah ﷺ said, “She is young.” Then ‘Ali proposed to her, and he married her to him."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3221,"lafz":true,"n":3221}],"full":1,"dr":1,"rep":[9424]},{"num":6239,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: تَزَوَّجَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا بِنْتُ ست سِنِينَ، وَبَنَى بِي وَأَنَا بِنْتُ تِسْعِ سِنِينَ، قَالَتْ: فَقَدِمْنَا الْمَدِينَةَ، فَنَزَلْنَا فِي بَنِي الْحَارِثِ بْنُ خزرج، فَوُعِكْتُ فتمزّق شَعْرِي، فَوَفَى جُمَيْمَةً، فَأَتَتْنِي أُمِّي أُمُّ رُومَانَ، وَأَنَا عَلَى أُرْجُوحَةٍ، وَمَعِي صَوَاحِبِي، فَصَرَخَتْ بِي فَأَتَيْتُهَا، لا أَدْرِي مَا تُرِيدُ بِي، فَأَخَذَتْ بِيَدِي حَتَّى أوقفتني عَلَى الْبَابِ. فَقُلْتُ: هَهْ هَهْ، حَتَّى ذَهَبَ نَفَسي فَأَدْخَلَتْنِي بَيْتًا، فَإِذَا نِسْوَةٌ مِنَ الأَنْصَارِ، فَقُلْنَ: عَلَى الْخَيْرِ وَالْبَرَكَةِ، وَعَلَى خَيْرِ طَائِرٍ، فَأَسْلَمَتْنِي إِلَيْهِنَّ، فَغَسَلْنَ رَأْسِي وأصْلَحْنَني، فَلَمْ يَرُعْني إِلاَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ضحىً. فَأَسْلَمَتْنِي إِلَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في المناقب (3894) ومسلم في النكاح (1422) كلاهما عن هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في نكاح الصغيرة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3894) and Muslim (1422).","chapter_en":"Chapter on the Marriage of a Young Girl","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["ʿAʾishah reported: “The Messenger of Allah ﷺ married me when I was six years old and consummated the marriage with me when I was nine years old. We then came to Madinah and stayed among Banu al-Harith ibn Khazraj. I fell ill and my hair fell out, then it grew back to around ear-length. My mother, Umm Ruman, came to me while I was on a swing with some girl companions. She called me, so I went to her without knowing what she wanted. She took me by the hand until she made me stand at the door. I said, ‘Hah, hah,’ until my breath settled, then she brought me into a house. There were women from the Ansar inside, and they said: ‘With goodness and blessing, and with good fortune.’ She handed me over to them, and they washed my head and prepared me. Nothing startled me except the Messenger of Allah ﷺ coming in the forenoon. Then she handed me over to him.”"]},"buhuth":{"en":["Her saying, “Jamima,” is the diminutive of “jamma,” which refers to hair that falls to the ears and the like—meaning it had grown to this length after having","fallen out due to illness."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3894,"lafz":true},{"key":"muslim","label":"مسلم","number":1422}],"full":1,"dr":1},{"num":6240,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَزَوَّجَهَا وَهْىَ بِنْتُ سَبْعِ سِنِينَ وَزُفَّتْ إِلَيْهِ وَهِيَ بِنْتُ تِسْعِ سِنِينَ وَلُعَبُهَا مَعَهَا وَمَاتَ عَنْهَا وَهِيَ بِنْتُ ثَمَانَ عَشْرَةَ."],"takhrij":"صحيح: رواه مسلم في النكاح (1422: 71) عن عبد بن حميد، أخبرنا عبد الرزاق، أخبرنا معمر، عن الزهري، عن عروة، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في نكاح الصغيرة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (71:1422).","chapter_en":"Chapter on the Marriage of a Young Girl","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["ʿAʾishah, the wife of the Prophet ﷺ, reported that the Prophet ﷺ married her when she was seven years old, and she was brought to him as a bride when she was nine years old, with her playthings with her, and he died when she was eighteen years old."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":71,"lafz":true},{"key":"muslim","label":"مسلم في النكاح","number":1422,"n":3481}],"full":1,"dr":1},{"num":6241,"demo":false,"sanad":"","matn":["عن أَبِي سَلَمَةَ ويحيى قالا: لَمَّا هلكت خديجة، جاءت خولة بنت حكيم امرأة عُثْمَانَ بن مَظْعُونٍ قَالَتْ: يَا رَسُولَ اللَّهِ أَلَا تَزَوَّجُ؟ قَالَ: مَنْ؟ قَالَتْ: إِنْ شِئْتَ بِكْرًا، وَإِنْ شِئْتَ ثَيِّبًا؟ قَالَ: فَمَنِ الْبِكْرُ؟ قَالَتْ: ابْنَةُ أَحَبِّ خَلْقِ اللهِ عَزَّ وَجَلَّ إِلَيْكَ عَائِشَةُ بِنْتُ أَبِي بَكْرٍ، قَالَ: وَمَنِ الثَّيِّبُ؟ قَالَتْ: سَوْدَةُ بِنْتُ زَمْعَةَ، آَمَنَتْ بِكَ، وَاتَّبَعَتْكَ عَلَى مَا تَقُولُ ، قَالَ: فَاذْهَبِي فَاذْكُرِيهِمَا عَلَيَّ ، فَدَخَلَتْ بَيْتَ أَبِي بَكْرٍ، فَقَالَتْ: يَا أُمَّ رُومَانَ مَاذَا أَدْخَلَ اللَّهُ عَزَّ وَجَلَّ عَلَيْكُمْ مِنَ الْخَيْرِ وَالْبَرَكَةِ؟ قَالَتْ: وَمَا ذَاكَ؟ قَالَتْ: أَرْسَلَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخْطُبُ عَلَيْهِ عَائِشَةَ، قَالَتْ: انْتَظِرِي أَبَا بَكْرٍ حَتَّى يَأْتِيَ، فَجَاءَ أَبُو بَكْرٍ، فَقَالَتْ: يَا أَبَا بَكْرٍ مَاذَا أَدْخَلَ اللَّهُ عَزَّ وَجَلَّ عَلَيْكُمْ مِنَ الْخَيْرِ وَالْبَرَكَةِ؟ قَالَ: وَمَا ذَاكَ؟ قَالَتْ: أَرْسَلَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخْطُبُ عَلَيْهِ عَائِشَةَ، قَالَ: وَهَلْ تَصْلُحُ لَهُ؟ إِنَّمَا هِيَ ابْنَةُ أَخِيهِ، فَرَجَعَتْ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَتْ ذَلِكَ لَهُ، قَالَ: ارْجِعِي إِلَيْهِ فَقُولِي لَهُ: أَنَا أَخُوكَ، وَأَنْتَ أَخِي فِي الْإِسْلَامِ، وَابْنَتُكَ تَصْلُحُ لِي، فَرَجَعَتْ فَذَكَرَتْ ذَلِكَ لَهُ، قَالَ: انْتَظِرِي وَخَرَجَ، قَالَتْ أُمُّ رُومَانَ: إِنَّ مُطْعِمَ بْنَ عَدِيٍّ قَدْ كَانَ ذَكَرَهَا عَلَى ابْنِهِ، فَوَاللهِ مَا وَعَدَ وَعْدًا قَطُّ، فَأَخْلَفَهُ لِأَبِي بَكْرٍ، فَدَخَلَ أَبُو بَكْرٍ عَلَى مُطْعِمِ بْنِ عَدِيٍّ وَعِنْدَهُ امْرَأَتُهُ أُمُّ الْفَتَى، فَقَالَتْ يَا ابْنَ أَبِي قُحَافَةَ لَعَلَّكَ مُصْبِئُ صَاحِبَنَا مُدْخِلُهُ فِي دِينِكَ الَّذِي أَنْتَ عَلَيْهِ، إِنْ تَزَوَّجَ إِلَيْكَ، قَالَ أَبُو بَكْرٍ لِلْمُطْعِمِ بْنِ عَدِيٍّ: أَقَوْلُ هَذِهِ تَقُولُ، قَالَ: إِنَّهَا تَقُولُ ذَلِكَ، فَخَرَجَ مِنْ عِنْدِهِ، وَقَدْ أَذْهَبَ اللهُ عَزَّ وَجَلَّ مَا كَانَ فِي نَفْسِهِ مِنْ عِدَتِهِ الَّتِي وَعَدَهُ فَرَجَعَ، فَقَالَ لِخَوْلَةَ: ادْعِي لِي رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَدَعَتْهُ فَزَوَّجَهَا إِيَّاهُ وَعَائِشَةُ يَوْمَئِذٍ بِنْتُ سِتِّ سِنِينَ، ثُمَّ خَرَجَتْ فَدَخَلَتْ عَلَى سَوْدَةَ بِنْتِ زَمْعَةَ، فَقَالَتْ: مَاذَا أَدْخَلَ اللَّهُ عَزَّ وَجَلَّ عَلَيْكِ مِنَ الْخَيْرِ وَالْبَرَكَةِ؟ قَالَتْ: مَا ذَاكَ؟ قَالَتْ: أَرْسَلَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخْطُبُكِ عَلَيْهِ، قَالَتْ: وَدِدْتُ ادْخُلِي إِلَى أَبِي فَاذْكُرِي ذَاكَ لَهُ، وَكَانَ شَيْخًا كَبِيرًا، قَدْ أَدْرَكَتْهُ السِّنُّ، قَدْ تَخَلَّفَ عَنِ الْحَجِّ، فَدَخَلَتْ عَلَيْهِ، فَحَيَّتْهُ بِتَحِيَّةِ الْجَاهِلِيَّةِ، فَقَالَ: مَنْ هَذِهِ؟ فَقَالَتْ: خَوْلَةُ بِنْتُ حَكِيمٍ، قَالَ: فَمَا شَأْنُكِ؟ قَالَتْ: أَرْسَلَنِي مُحَمَّدُ بْنُ عَبْدِ اللَّهِ أَخْطُبُ عَلَيْهِ سَوْدَةَ، قَالَ: كُفْءٌ كَرِيمٌ، مَاذَا تَقُولُ صَاحِبَتُكِ؟ قَالَتْ: تُحِبُّ ذَاكَ، قَالَ: ادْعُهَا لِي فَدَعَتْهَا، فَقَالَ: أَيْ بُنَيَّةُ إِنَّ هَذِهِ تَزْعُمْ أَنَّ مُحَمَّدَ بْنَ عَبْدِ اللَّهِ بْنِ عَبْدِ الْمُطَّلِبِ قَدْ أَرْسَلَ يَخْطُبُكِ، وَهُوَ كُفْءٌ كَرِيمٌ، أَتُحِبِّينَ أَنْ أُزَوِّجَكِ بِهِ، قَالَتْ: نَعَمْ، قَالَ: ادْعِيهِ لِي، فَجَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَيْهِ فَزَوَّجَهَا إِيَّاهُ، فَجَاءَهَا أَخُوهَا عَبْدُ بْنُ زَمْعَةَ مِنَ الْحَجِّ، فَجَعَلَ يَحْثِي عَلَى رَأْسِهِ التُّرَابَ، فَقَالَ بَعْدَ أَنْ أَسْلَمَ: لَعَمْرُكَ إِنِّي لَسَفِيهٌ يَوْمَ أَحْثِي فِي رَأْسِي التُّرَابَ أَنْ تَزَوَّجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَوْدَةَ بِنْتَ زَمْعَةَ.","قالت عائشة: فقدمنا المدينة، فنزلنا في بني الحارث من الخزرج في السُّنْح، قالت: فجاء رسول الله صلى الله عليه وسلم فدخل بيتنا، واجتمع إليه رجال من الأنصار ونساء، فجاءت بي أمي، وإني لفي أرجوجة بين عَذْقين ترجُح بي، فأنزلتني من الأرجوحة، ولي جُميمةٌ، ففرقتها، ومسحتْ وجهي بشيء من ماء، ثم أقبلت تقودني حتى وقفت بي عند الباب، وإني لأنهج، حتى سكن من نفسي، ثم دخلت بي، فإذا رسول الله صلى الله عليه وسلم جالس على سرير في بيتنا، وعنده رجال ونساء من الأنصار، فأجلستني في حِجْرِه، ثم قالت: هؤلاء أهلك، فبارك الله لك فيهم، وبارك لهم فيك، فوثب الرجال والنساء، فخرجوا وبنى بي رسول الله صلى الله عليه وسلم في بيتنا، ما نُحِرت عليّ جزور، ولا ذُبحت عليّ شاة حتى أرسل إلينا سعد بن عبادة بجفنة كان يرسل بها إلى رسول الله صلى الله عليه وسلم إذا دار إلى نسائه، وأنا يومئذ بنت تسع سنين."],"takhrij":"حسن: رواه الإمام أحمد (25769) عن محمد بن بشر، قال: حدثنا محمد بن عمرو، قال: حدثنا أبو سلمة ويحيى قالا: فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في نكاح الصغيرة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (25769).","chapter_en":"Chapter on the Marriage of a Young Girl","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["Abu Salamah and Yahya said: When Khadijah died, Khawlah bint Hakim, the wife of ‘Uthman ibn Maz‘un, came and said: O Messenger of Allah, will you not marry? He said, “Whom?” She said: If you wish, a virgin; and if you wish, a previously married woman. He said, “Who is the virgin?” She said: The daughter of the most beloved of Allah’s creation to you: ‘A’ishah daughter of Abu Bakr. He said, “And who is the previously married woman?” She said: Sawdah bint Zam‘ah. She believed in you and followed what you brought. He said, “Go and mention them to me.” So she entered the house of Abu Bakr and said: O Umm Ruman, what goodness and blessing Allah has brought to your household. She said: And what is that? She said: The Messenger of Allah ﷺ has sent me to ask for ‘A’ishah in marriage for him. She said: Wait until Abu Bakr comes. When Abu Bakr came, she said: O Abu Bakr, what goodness and blessing Allah has brought to your household. He said: And what is that? She said: The Messenger of Allah ﷺ has sent me to ask for ‘A’ishah in marriage for him. He said: Is she suitable for him? She is the daughter of his brother. So she returned to the Messenger of Allah ﷺ and mentioned that to him. He said: “Go back to him and say: I am your brother and you are my brother in Islam, and your daughter is lawful for me.” So she went back and mentioned that to him. He said: Wait. Then he went out. Umm Ruman said: Mut‘im ibn ‘Adi had already mentioned her for his son, and by Allah he had never made a promise to Abu Bakr and broken it. So Abu Bakr went to Mut‘im ibn ‘Adi, and with him was the boy’s mother. She said: O son of Abu Quhafah, perhaps you will turn our companion away from his religion and enter him into your religion if he marries into you. Abu Bakr said to Mut‘im ibn ‘Adi: Is this what she is saying? He said: She is saying that. So he left him, and Allah removed from his heart the matter of the promise he had made to him. Then he returned and said to Khawlah: Call the Messenger of Allah ﷺ for me. So she called him, and he married her to him, and ‘A’ishah was then six years old. Then she went out and entered upon Sawdah bint Zam‘ah and said: What goodness and blessing Allah has brought to you. She said: And what is that? She said: The Messenger of Allah ﷺ has sent me to ask for you in marriage for him. She said: I would like that. Go in to my father and mention it to him. He was a very old man who had advanced in age and had stayed behind from Hajj. She entered upon him and greeted him with the greeting of the pre-Islamic period. He said: Who is this? She said: Khawlah bint Hakim. He said: What is your matter? She said: Muhammad ibn ‘Abdullah has sent me; he is asking for Sawdah in marriage. He said: A noble and suitable match. What does your companion say? She said: She would like that. He said: Call her for me. So she called her. He said: My daughter, this woman claims that Muhammad ibn ‘Abdullah ibn ‘Abd al-Muttalib has sent to ask for your hand, and he is a noble and suitable match. Do you wish that I marry you to him? She said: Yes. He said: Call him for me. So the Messenger of Allah ﷺ came to him and he married her to him. Then her brother ‘Abd ibn Zam‘ah came back from Hajj and began throwing dust upon his own head. After he accepted Islam, he said: By your life, I was indeed foolish on the day I threw dust on my head because the Messenger of Allah ﷺ married Sawdah bint Zam‘ah. ‘A’ishah said: Then we came to Madinah and stayed among Banu al-Harith of al-Khazraj at al-Sunh. She said: Then the Messenger of Allah ﷺ came and entered our house, and men and women from the Ansar gathered there. My mother came to me while I was on a swing between two branches, swinging on it. She brought me down from the swing, and my hair had grown to around ear-length. She combed and arranged it and wiped my face with some water. Then she came leading me until she made me stand at the door while I was breathing heavily, until I calmed down. Then she took me in, and there was the Messenger of Allah ﷺ seated on a bed in our house, with men and women from the Ansar around him. She seated me in his lap, then said: These are your family. May Allah bless you in them, and bless them through you. Then the men and women stood up and left. The Messenger of Allah ﷺ consummated the marriage with me in our house. No camel was slaughtered for me and no sheep was slaughtered for me, until Sa‘d ibn ‘Ubadah sent us a large bowl which he used to send to the Messenger of Allah ﷺ whenever he was with one of his wives. I was nine years old at that time."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":25769,"lafz":true}],"full":1,"dr":1},{"num":6242,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى الأشعري قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ثَلاَثَةٌ لَهُمْ أَجْرَانِ، رَجُلٌ مِنْ أَهْلِ الْكِتَابِ آمَنَ بِنَبِيِّهِ، وَآمَنَ بِمُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَالْعَبْدُ الْمَمْلُوكُ إِذَا أدّى حَقَّ اللَّهِ وَحَقَّ مَوَالِيهِ، وَرَجُلٌ كَانَتْ عِنْدَهُ أَمَةٌ، فَأَدَّبَهَا فَأَحْسَنَ تَأْدِيبَهَا، وَعَلَّمَهَا فَأَحْسَنَ تَعْلِيمَهَا، ثُمَّ أَعْتَقَهَا فَتَزَوَّجَهَا فَلَهُ أَجْرَانِ."],"takhrij":"متفق عليه: رواه البخاري في العلم (97) ومسلم في الإيمان (154) كلاهما من حديث صالح بن حيان، قال عامر الشعبي: حدثني أبو بردة، عن أبيه (أبي موسى) فذكره.","grade":"متفق عليه","chapter_ar":"باب أجر من أعتق أمته ثم تزوجها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (97) and Muslim (154).","chapter_en":"Chapter on the reward of the one who frees his female slave and then marries her","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":24,"content":{"translation":{"en":["Abu Musa al-Ash‘ari said: The Messenger of Allah ﷺ said: “Three people will have a double reward: a man from the People of the Book who believed in his prophet and then believed in Muhammad ﷺ; a slave who fulfills the right of Allah and the right of his masters; and a man who has a slave woman, teaches her manners and does so well, and teaches her knowledge and does so well, then frees her and marries her. For him are two rewards.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":97,"lafz":true},{"key":"muslim","label":"مسلم","number":154}],"full":1,"dr":1,"rep":[12966]},{"num":6243,"demo":false,"sanad":"","matn":["عن جابر قال: قال لي رسول الله صلى الله عليه وسلم: تزوجت يا جابر فقلت نعم، وفي آخره فقال: بارك الله لك أو قال: خيراً."],"takhrij":"متفق عليه: رواه البخاري في النفقات (5367)، ومسلم في الرضاع (715: 56) كلاهما من طريق حماد بن زيد، عن عمرو بن دينار، عن جابر فذكره في سياق طويل.","grade":"متفق عليه","chapter_ar":"باب ما جاء في صيغ تهنئة النكاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5367) and Muslim (56:715).","chapter_en":"Chapter on the reported forms of congratulating someone on marriage","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said to me, “Have you married, O Jabir?” I said: Yes. And at the end of the narration he said: “May Allah bless you,” or he said: “Good.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5367,"lafz":true},{"key":"muslim","label":"مسلم","number":56},{"key":"muslim","label":"مسلم في الرضاع","number":715}],"full":1,"dr":1},{"num":6244,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ رَأَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ أَثَرَ صُفْرَةٍ فَقَالَ مَهْيَمْ. أَوْ مَهْ. قَالَ تَزَوَّجْتُ امْرَأَةً عَلَى وَزْنِ نَوَاةٍ مِنْ ذَهَبٍ. فَقَالَ بَارَكَ اللَّهُ لَكَ أَوْلِمْ وَلَوْ بِشَاةٍ."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6386) ومسلم في النكاح (1427: 79) كلاهما من حديث حماد بن زيد، عن ثابت عن أنس فذكره واللفظ للبخاري، ولفظ مسلم مثله غير أنه لم يذكر مَهْيم أو مه","grade":"متفق عليه","chapter_ar":"باب ما جاء في صيغ تهنئة النكاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6386) and Muslim (79:1427). The wording is that of al-Bukhari.","chapter_en":"Chapter on the reported forms of congratulating someone on marriage","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet ﷺ saw on ‘Abd al-Rahman a trace of yellow perfume and said: “What is this?” or: “What happened?” He said: I married a woman for the weight of a date-stone of gold. He said: “May Allah bless you. Give a wedding feast, even if only with one sheep.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6386,"lafz":true},{"key":"muslim","label":"مسلم","number":79},{"key":"muslim","label":"مسلم في النكاح","number":1427}],"full":1,"rep":[11155]},{"num":6245,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: تَزَوَّجَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَدْخَلَتْنِي أُمِّي بَيْتًا فَإِذَا نِسْوَةٌ مِنَ الأَنْصَارِ قُلْنَ: عَلَى الْخَيْرِ وَالْبَرَكَةِ، وَعَلَى خَيْرِ طَائِرٍ."],"takhrij":"متفق عليه: رواه البخاري في المناقب (3894) ومسلم في النكاح (1422) كلاهما عن هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في صيغ تهنئة النكاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3894) and Muslim (1422).","chapter_en":"Chapter on the reported forms of congratulating someone on marriage","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ married me, and my mother brought me into a house where there were women from the Ansar. They said: “With goodness and blessing, and with the best fortune.”"]},"buhuth":{"en":["Her statement, “with the best fortune,” means: with the best share and good lot."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3894,"lafz":true},{"key":"muslim","label":"مسلم","number":1422}],"full":1,"dr":1,"rep":[11160]},{"num":6246,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا رَفَّأَ الإِنْسَانَ إِذَا تَزَوَّجَ قَالَ بَارَكَ اللَّهُ لَكَ وَبَارَكَ عَلَيْكَ وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ."],"takhrij":"حسن: رواه أبو داود (2130) والترمذي (1091) وابن ماجة (1905) وأحمد (8956) والدارمي (2220) وصحّحه ابن حبان (4052) والحاكم (2/183) كلهم من حديث عبد العزيز بن محمد الدراوردي ، عن سهيل بن أبي صالح، عن أبيه، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في صيغ تهنئة النكاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2130), al-Tirmidhi (1091), and Ahmad (8956). Al-Tirmidhi said: Hasan Sahih.","chapter_en":"Chapter on the reported forms of congratulating someone on marriage","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Abu Hurayrah said: When the Prophet ﷺ congratulated a person upon marriage, he would say: “May Allah bless you, and send blessing upon you, and join you both together in goodness.”"]},"buhuth":{"en":["The phrase meaning “congratulated” refers to the old customary formula used in the pre-Islamic period. It was later discouraged, as in the next narration, because it singled out sons and excluded daughters in line with pre-Islamic dislike of girls."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2130,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1091},{"key":"ahmad","label":"مسند الإمام أحمد","number":8956,"n":8957},{"key":"ibnmajah","label":"ابن ماجه","number":1905},{"key":"darimi","label":"الدارمي","number":2220,"n":2108},{"key":"ibnhibban","label":"ابن حبان","number":4052}],"full":1,"dr":1,"rep":[11157]},{"num":6247,"demo":false,"sanad":"","matn":["عَنِ الْحَسَنِ، قَالَ تَزَوَّجَ عَقِيلُ بْنُ أَبِي طَالِبٍ امْرَأَةً مِنْ بَنِي جُشَمٍ فَقِيلَ لَهُ بِالرِّفَاءِ وَالْبَنِينِ. قَالَ قُولُوا كَمَا قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَارَكَ اللَّهُ فِيكُمْ وَبَارَكَ لَكُمْ."],"takhrij":"صحيح: رواه النسائي (3371) واللفظ له، وابن ماجة (1906) وأحمد (1739) والبيهقي (7/148) والدارمي (2119) كلهم من طرق عن الحسن قال فذكره. ولفظ البيهقي: قدم عقيل بن أبي طالب البصرة","grade":"صحيح","chapter_ar":"باب ما جاء في صيغ تهنئة النكاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3371), and this is his wording, also Ibn Majah (1906), Ahmad (1739), and al-Bayhaqi (7/148).","chapter_en":"Chapter on the reported forms of congratulating someone on marriage","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Al-Hasan said: ‘Aqil ibn Abi Talib married a woman from Banu Jusham, and people said to him: “May you have harmony and sons.” He said: Say instead what the Messenger of Allah ﷺ said: “May Allah bless you, and bless for you.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3371,"lafz":true,"n":3371},{"key":"ibnmajah","label":"ابن ماجه","number":1906},{"key":"kubrabayhaqi","label":"البيهقي","number":148},{"key":"ahmad","label":"مسند الإمام أحمد","number":1739,"n":1739},{"key":"darimi","label":"الدارمي","number":2119}],"full":1,"dr":1,"rep":[11158]},{"num":6248,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ قَالَ: قَالَ نَفَرٌ مِنَ الْأَنْصَارِ لِعَلِيٍّ: عِنْدَكَ فَاطِمَةُ. فَأَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَسَلَّمَ عَلَيْهِ فَقَالَ: مَا حَاجَةُ ابْنِ أَبِي طَالِبٍ؟ قَالَ: ذَكَرْتُ فَاطِمَةَ بِنْتَ مُحَمَّدٍ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَرْحَبًا وَأَهْلًا. لَمْ يَزِدْهُ عَلَيْهِمَا. فَخَرَجَ عَلِيُّ عَلَى أُولَئِكَ الرَّهْطِ مِنَ الْأَنْصَارِ يَنْتَظِرُونَهُ. قَالُوا: مَا وَرَاءَكَ؟ قَالَ: مَا أَدْرِي غَيْرَ أَنَّهُ قَالَ لِي: مَرْحَبًا وَأَهْلًا. قَالُوا: يَكْفِيكَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِحْدَاهُمَا. أَعْطَاكَ الْأَهْلَ أَعْطَاكَ المرحب، فَلَمَّا كَانَ بَعْدَمَا زَوَّجَهُ قَالَ: يَا عَلِيُّ إِنَّهُ لَا بُدَّ لِلْعَرُوسِ مِنْ وَلِيمَةٍ فَقَالَ سَعْدٌ: عِنْدِي كَبْشٌ، وَجَمَعَ لَهُ رهط مِنَ الْأَنْصَارِ آصعاً مِنْ ذُرَةٍ. فَلَمَّا كَانَ لَيْلَةُ الْبِنَاءِ قَالَ: لَا تُحْدِثْ شَيْئًا حَتَّى تَلْقَانِي. قَالَ: فَدَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِإِنَاءٍ فَتَوَضَّأَ مِنْهُ، ثُمَّ أَفْرَغَهُ على علي، ثُمَّ قَالَ: اللَّهُمَّ بَارِكْ فِيهِمَا، وَبَارِكْ عَلَيْهِمَا وَبَارِكْ لَهُمَا فِي نسلهما."],"takhrij":"حسن: رواه ابن سعد (8/21) والطبراني في الكبير (2/4) والطحاوي في مشكله (5947) والنسائي في اليوم والليلة (258) وأحمد (23035) مختصرا كلهم من حديث عبد الكريم بن سليط عن ابن بريدة، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في صيغ تهنئة النكاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Sa‘d (8/21), al-Tabarani in al-Kabir (2/4), and al-Tahawi in Mushkil al-Athar (5947).","chapter_en":"Chapter on the reported forms of congratulating someone on marriage","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Buraydah said: Some men from the Ansar said to ‘Ali: You have a chance with Fatimah. So he came to the Messenger of Allah ﷺ and greeted him, and he said: “What does the son of Abu Talib seek?” He said: I mentioned Fatimah, the daughter of Muhammad, the Messenger of Allah ﷺ. The Messenger of Allah ﷺ said: “Welcome and greetings,” and said nothing more. Then ‘Ali came out to those men from the Ansar who were waiting for him. They said: What happened? He said: I do not know except that he said to me: “Welcome and greetings.” They said: One of those two from the Messenger of Allah ﷺ is enough for you. He gave you family ties and welcome. Then after he married him to her, he said: “O ‘Ali, a bridegroom must have a wedding feast.” Sa‘d said: I have a sheep. And some men from the Ansar gathered several measures of grain for him. When it was the night of the marriage, he said: “Do not do anything until you meet me.” Then the Messenger of Allah ﷺ called for a vessel and performed ablution from it, then poured it over ‘Ali and said: “O Allah, bless them both, send blessing upon them, and bless them in their offspring.”"]}},"tuhfa":{},"refs":[{"key":"sh146","label":"ابن سعد","number":8,"lafz":true},{"key":"mujamkabir","label":"الطبراني في الكبير","number":2},{"key":"sh22547","label":"الطحاوي في مشكل الآثار","number":5947},{"key":"nasai","label":"النسائي في اليوم والليله","number":258},{"key":"ahmad","label":"احمد","number":23035}],"full":1,"dr":1},{"num":6249,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ تَزَوَّجَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي شَوَّالٍ وَبَنَى بِي فِي شَوَّالٍ فَأَىُّ نِسَاءِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ أَحْظَى عِنْدَهُ مِنِّي.","قال: وكانت عائشة تستحب أن تُدخِلَ نساءها في شوال."],"takhrij":"صحيح: رواه مسلم في النكاح (1423) من طريق وكيع، حدثنا سفيان، عن إسماعيل بن أمية، عن عبد الله بن عروة، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب استحباب التزوج في شوال والدخول فيه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1423).","chapter_en":"Chapter on the recommendation of marrying and consummating the marriage in Shawwal","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":26,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ married me in Shawwal and consummated the marriage with me in Shawwal. So which of the wives of the Messenger of Allah ﷺ was more favored by him than me? She said: And ‘A’ishah used to like that the women under her care be brought to their husbands in Shawwal."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1423,"lafz":true}],"full":1,"dr":1},{"num":6250,"demo":false,"sanad":"","matn":["عَنْ خَنْسَاءَ بِنْتِ خِذَامٍ الأَنْصَارِيَّةِ، أَنَّ أَبَاهَا، زَوَّجَهَا وَهْىَ ثَيِّبٌ، فَكَرِهَتْ ذَلِكَ فَأَتَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَدَّ نِكَاحَهُ."],"takhrij":"صحيح: رواه مالك في النكاح (25) عن عبد الرحمن بن القاسم، عن أبيه، عن عبد الرحمن ومُجمّع ابني يزيد بن جارية الأنصاري، عن خنساء بنت خِدام الأنصارية، فذكرته.","grade":"صحيح","chapter_ar":"باب ردّ زواج الثيب الكارهة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (25) and al-Bukhari (5138).","chapter_en":"Chapter on annulling the marriage of a previously married woman who dislikes it","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":27,"content":{"translation":{"en":["Khansa’ bint Khidam al-Ansariyyah said that her father married her off while she had previously been married, and she disliked that. So she came to the Messenger of Allah ﷺ, and he annulled that marriage."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":25,"lafz":true},{"key":"bukhari","label":"البخاري","number":5138}],"full":1,"dr":1},{"num":6251,"demo":false,"sanad":"","matn":["أَنَّ امْرَأَةً، مِنْ وَلَدِ جَعْفَرٍ تَخَوَّفَتْ أَنْ يُزَوِّجَهَا وَلِيُّهَا وَهْىَ كَارِهَةٌ فَأَرْسَلَتْ إِلَى شَيْخَيْنِ مِنَ الأَنْصَارِ عَبْدِ الرَّحْمَنِ وَمُجَمِّعٍ ابْنَىْ جَارِيَةَ قَالاَ فَلاَ تَخْشَيْنَ، فَإِنَّ خَنْسَاءَ بِنْتَ خِذَامٍ أَنْكَحَهَا أَبُوهَا وَهْىَ كَارِهَةٌ، فَرَدَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَلِكَ.","قال سفيان: وأما عبدالرحمن فسمعته يقول عن أبيه: إن خنساء."],"takhrij":"صحيح: رواه البخاري في الحيل (6969) عن علي بن عبد الله، حـدثنا","grade":"صحيح","chapter_ar":"باب تخيير البكر البالغ زوجها أبوها وهي كارهة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6969).","chapter_en":"Chapter on giving an adult virgin the choice if her father marries her off while she dislikes it","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":28,"content":{"translation":{"en":["A woman from the descendants of Ja‘far feared that her guardian would marry her off while she disliked it, so she sent to two elderly men from the Ansar: ‘Abd al-Rahman and Mujamma‘, the two sons of Jariyah. They said: Do not be afraid, for Khansa’ bint Khidam was married off by her father while she disliked it, and the Prophet ﷺ nullified that. Sufyan said: As for ‘Abd al-Rahman, I heard him say from his father: “Indeed Khansa’…”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6969,"lafz":true}],"full":1,"dr":1},{"num":6252,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ جَارِيَةً، بِكْرًا أَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَتْ أَنَّ أَبَاهَا زَوَّجَهَا وَهِيَ كَارِهَةٌ فَخَيَّرَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه أبو داود (2096) وابن ماجة (1875) وأحمد (2469) والدارقطني (3/234 – 345) والبيهقي (7/117) كلهم من طريق الحسين بن محمد المروزي، حدثني جرير بن حازم، عن أيوب، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب تخيير البكر البالغ زوجها أبوها وهي كارهة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2096), Ibn Majah (1875), Ahmad (2469), and al-Daraqutni (3/234–235).","chapter_en":"Chapter on giving an adult virgin the choice if her father marries her off while she dislikes it","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":28,"content":{"translation":{"en":["Ibn ‘Abbas narrated that a virgin young woman came to the Prophet ﷺ and told him that her father had married her off while she disliked it, so the Prophet ﷺ gave her the choice."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2096,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":1875},{"key":"sh9771","label":"الدارقطني","number":3},{"key":"ahmad","label":"مسند الإمام أحمد","number":2469,"n":2469}],"full":1,"dr":1},{"num":6253,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ تُنْكَحُ الأَيِّمُ حَتَّى تُسْتَأْمَرَ، وَلاَ تُنْكَحُ الْبِكْرُ حَتَّى تُسْتَأْذَنَ. قَالُوا: يَا رَسُولَ اللَّهِ وَكَيْفَ إِذْنُهَا؟ قَالَ: أَنْ تَسْكُتَ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5136)، ومسلم في النكاح (1419) كلاهما من طريق هشام، عن يحيى بن أبي كثير، حدّثنا أبو سلمة، حدّثنا أبو هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب الأيم أحق بنفسها، والبكر تستأذن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5136) and Muslim (1419).","chapter_en":"Chapter on the previously married woman having more right over herself, and the virgin being asked for permission","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":29,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said: “A previously married woman must not be married until she is consulted, and a virgin must not be married until her permission is sought.” They said: O Messenger of Allah, how is her permission given? He said: “By her silence.”"]},"buhuth":{"en":["Women are of two types: previously married and virgin. Mentioning “the previously married woman” in contrast to the virgin shows that what is meant here by al-ayyim is the previously married woman. The silence of the virgin when asked for permission is taken as a sign of her approval, because she may feel shy about stating it openly and expressing interest in marriage. As for the previously married woman, she may openly express whether she wants marriage or not, since the shyness of a virgin is no longer present, so she speaks and instructs her guardian to marry her as she wishes."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5136,"lafz":true},{"key":"muslim","label":"مسلم","number":1419}],"full":1,"dr":1},{"num":6254,"demo":false,"sanad":"","matn":["عَلَيْهِ وَسَلَّمَ. قَالَتْ أَرْسَلَ إِلَىَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَاطِبَ بْنَ أَبِي بَلْتَعَةَ يَخْطُبُنِي لَهُ فَقُلْتُ إِنَّ لِي بِنْتًا وَأَنَا غَيُورٌ. فَقَالَ أَمَّا ابْنَتُهَا فَنَدْعُو اللَّهَ أَنْ يُغْنِيَهَا عَنْهَا وَأَدْعُو اللَّهَ أَنْ يَذْهَبَ بِالْغَيْرَةِ."],"takhrij":"صحيح: رواه مسلم في الجنائز (3:918) من طريق إسماعيل بن جعفر، أخبرني سعد بن سعيد، عن عمر بن كثير بن أفلح، عن ابن سفينة، عن أم سلمة، فذكرته بطوله.","grade":"صحيح","chapter_ar":"باب الأيم أحق بنفسها، والبكر تستأذن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (3:918).","chapter_en":"Chapter on the previously married woman having more right over herself, and the virgin being asked for permission","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":29,"content":{"translation":{"en":["Umm Salamah said: The Messenger of Allah ﷺ sent Hatib ibn Abi Balta‘ah to propose to me on his behalf. I said: I have a daughter, and I am a jealous woman. He said: “As for her daughter, we ask Allah to make her independent of her mother, and I ask Allah to remove jealousy.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":3,"lafz":true}],"full":1},{"num":6255,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْجَارِيَةِ يُنْكِحُهَا أَهْلُهَا، أَتُسْتَأْمَرُ أَمْ لاَ؟ فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : نَعَمْ تُسْتَأْمَرُ فَقَالَتْ عَائِشَةُ: فَقُلْتُ لَهُ: فَإِنَّهَا تستحي. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَذَلِكَ إِذْنُهَا إِذَا هِيَ سكتَتْ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5137) من طريق الليث.","grade":"متفق عليه","chapter_ar":"باب الأيم أحق بنفسها، والبكر تستأذن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5137) and Muslim (1420). The wording is that of Muslim.","chapter_en":"Chapter on the previously married woman having more right over herself, and the virgin being asked for permission","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":29,"content":{"translation":{"en":["‘A’ishah said: I asked the Messenger of Allah ﷺ about a young woman whose family wants to marry her off: should her permission be sought or not? The Messenger of Allah ﷺ said to her: “Yes, her permission should be sought.” ‘A’ishah said: I said to him: But she feels shy. The Messenger of Allah ﷺ said: “That is her permission when she remains silent.”"]},"buhuth":{"en":["The wording in al-Bukhari is: She said, O Messenger of Allah, the virgin feels shy. He said: “Her consent is her silence.”","In other narrations: “Seek the women’s permission concerning their marriage.” Narrated by Ibn Hibban in his Sahih (4080)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5137,"lafz":true},{"key":"muslim","label":"مسلم","number":1420}],"full":1,"dr":1},{"num":6256,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ عَبَّاسٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الأَيِّمُ أَحَقُّ بِنَفْسِهَا مِنْ وَلِيِّهَا، وَالْبِكْرُ تُسْتَأْذَنُ فِي نَفْسِهَا، وَإِذْنُهَا صُمَاتُهَا."],"takhrij":"صحيح: رواه مالك في النكاح (4) عن عبد الله بن الفضل، عن نافع بن جبير بن مطعم، عن عبد الله بن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب الأيم أحق بنفسها، والبكر تستأذن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (4) and Muslim (66:1421).","chapter_en":"Chapter on the previously married woman having more right over herself, and the virgin being asked for permission","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":29,"content":{"translation":{"en":["Ibn ‘Abbas narrated that the Messenger of Allah ﷺ said: “The previously married woman has more right over herself than her guardian, and the virgin is asked for permission regarding herself, and her permission is her silence.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":4,"lafz":true},{"key":"muslim","label":"مسلم","number":66}],"full":1,"dr":1},{"num":6257,"demo":false,"sanad":"","matn":["عَنْ العُرس بن عَمِيرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: آمِرُوا النِّسَاءَ لتعرب الثَّيِّبُ عَنْ نَفْسِهَا، وَإِذْنُ الْبِكْرِ صماتها."],"takhrij":"حسن: رواه الطبراني في الكبير (17/138) من طريق سفيان بن عامر، والطحاوي في شرح المعاني (4/368) من طريق يحيى بن أيوب كلاهما عن عبد الله بن عبد الرحمن، عن عدي بن عدي، عن أبيه، عن العرس بن عميرة فذكره واللفظ للطبراني.","grade":"حسن","chapter_ar":"باب الأيم أحق بنفسها، والبكر تستأذن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (17/138), and al-Tahawi in Sharh al-Ma‘ani (4/368). The wording is that of al-Tabarani.","chapter_en":"Chapter on the previously married woman having more right over herself, and the virgin being asked for permission","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":29,"content":{"translation":{"en":["Al-‘Urs ibn ‘Umayrah said: The Messenger of Allah ﷺ said: “Consult the women, so that the previously married woman may express her own view, and the permission of the virgin is her silence.”"]},"buhuth":{"en":["The wording of al-Tahawi is: “The previously married woman expresses her own view, and the approval of the virgin is her silence.”","Legal understanding of this chapter: The narrations in this chapter show that marrying off a previously married woman is not permissible except with her permission.","His statement ﷺ, “The previously married woman has more right over herself,” means that she has more right than her guardian in choosing whichever husband she wishes. So she may say, for example: I approve of so-and-so, and I do not approve of so-and-so. The guardian must marry her according to her choice, but she does not personally conduct her own marriage contract.","As for using these narrations as proof that a marriage is valid without a guardian, that is not correct."]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":17,"lafz":true},{"key":"sh21108","label":"الطحاوي في شرح المعاني","number":4}],"full":1,"dr":1},{"num":6258,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ قَالَ: تُوُفِّيَ عُثْمَانُ بْنُ مَظْعُونٍ، وَتَرَكَ ابْنَةً لَهُ مِنْ خُوَيْلَةَ بِنْتِ حَكِيمِ بْنِ أُمَيَّةَ بْنِ حَارِثَةَ بْنِ الْأَوْقَصِ قَالَ: وَأَوْصَى إِلَى أَخِيهِ قُدَامَةَ بْنِ مَظْعُونٍ، قَالَ عَبْدُ اللَّهِ: وَهُمَا خَالَايَ، قَالَ: فَخَطَبْتُ إِلَى قُدَامَةَ بْنِ مَظْعُونٍ ابْنَةَ عُثْمَانَ بْنِ مَظْعُونٍ فَزَوَّجَنِيهَا، وَدَخَلَ الْمُغِيرَةُ بْنُ شُعْبَةَ - يَعْنِي إِلَى أُمِّهَا - فَأَرْغَبَهَا فِي الْمَالِ فَحَطَّتْ إِلَيْهِ، وَحَطَّتْ الْجَارِيَةُ إِلَى هَوَى أُمِّهَا، فَأَبَيَا حَتَّى ارْتَفَعَ أَمْرُهُمَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ قُدَامَةُ بْنُ مَظْعُونٍ: يَا رَسُولَ اللَّهِ، ابْنَةُ أَخِي أَوْصَى بِهَا إِلَيَّ، فَزَوَّجْتُهَا ابْنَ عَمَّتِهَا عَبْدَ اللَّهِ بْنَ عُمَرَ، فَلَمْ أُقَصِّرْ بِهَا فِي الصَّلَاحِ، وَلَا فِي الْكَفَاءَةِ، وَلَكِنَّهَا امْرَأَةٌ، وَإِنَّمَا حَطَّتْ إِلَى هَوَى أُمِّهَا، قَالَ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هِيَ يَتِيمَةٌ، وَلَا تُنْكَحُ إِلَّا بِإِذْنِهَا قَالَ: فَانْتُزِعَتْ وَاللهِ مِنِّي بَعْدَ أَنْ مَلَكْتُهَا، فَزَوَّجُوهَا الْمُغِيرَةَ."],"takhrij":"حسن: رواه الإمام أحمد (6136) عن يعقوب، حدثنا أبي، عن ابن إسحاق، حدثني عمر بن حسين بن عبد الله مولى آل حاطب، عن نافع مولى عبد الله بن عمر، عن عبد الله بن عمر فذكره.","grade":"حسن","chapter_ar":"باب أن اليتيمة لا تنكح إلا بإذنها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6136).","chapter_en":"Chapter on the orphan girl not being married except with her permission","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":30,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar said: ‘Uthman ibn Maz‘un died and left behind a daughter from Khawlah bint Hakim ibn Umayyah ibn Harithah ibn al-Awqas. He said: And he entrusted her to his brother Qudamah ibn Maz‘un. ‘Abdullah said: They are both my maternal uncles. He said: So I proposed to Qudamah ibn Maz‘un for the daughter of ‘Uthman ibn Maz‘un, and he married her to me. Then al-Mughirah ibn Shu‘bah approached her mother and encouraged her with wealth, so the mother inclined toward him, and the girl followed the desire of her mother, and they both refused, until their matter was brought to the Messenger of Allah ﷺ. Qudamah ibn Maz‘un said: O Messenger of Allah, she is my brother’s daughter, and he entrusted her to me. I married her to her cousin ‘Abdullah ibn ‘Umar, and I was not lacking regarding her in righteousness or suitability, but she is a woman, and she merely followed the preference of her mother. The Messenger of Allah ﷺ then said: “She is an orphan girl, and she is not to be married except with her permission.” He said: By Allah, she was taken away from me after I had been given her in marriage, and they married her to al-Mughirah."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":6136,"lafz":true}],"full":1,"dr":1},{"num":6259,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تُسْتَأْمَرُ الْيَتِيمَةُ فِي نَفْسِهَا، فَإِنْ سَكَتَتْ فَقَدْ أَذِنَتْ، وَإِنْ أَبَتْ لَمْ تُكْرَهْ."],"takhrij":"حسن: رواه أحمد (9516) والبزار – كشف الأستار (1423) وصحّحه ابن حبان (4085) والحاكم (2/166) وعنه البيهقي (7/122) كلهم من حديث يونس بن أبي إسحاق، عن أبي بردة، عن أبيه أبي موسى فذكره.","grade":"حسن","chapter_ar":"باب أن اليتيمة لا تنكح إلا بإذنها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (19516), al-Bazzar in Kashf al-Astar (1423), authenticated by Ibn Hibban (4085), and al-Hakim (2702).","chapter_en":"Chapter on the orphan girl not being married except with her permission","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":30,"content":{"translation":{"en":["Abu Musa said: The Messenger of Allah ﷺ said: “The orphan girl is asked for her permission regarding herself. If she remains silent, then she has given permission, and if she refuses, she is not to be forced.”"]}},"tuhfa":{},"refs":[{"key":"sh12862","label":"البزار - كشف الأستار","number":1423},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":4085},{"key":"ahmad","label":"مسند الإمام أحمد","number":19516,"n":19516},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1422,"n":1423},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4073,"n":4069},{"key":"hakim","label":"المستدرك على الصحيحين","number":2702,"n":2688},{"key":"ahmad","label":"احمد","number":9516,"lafz":true}],"full":1,"dr":1},{"num":6260,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : واليتيمة تُسْتَأْمَرُ فِي نَفْسِهَا، فَإِنْ صَمَتَتْ فَهُوَ إِذْنُهَا، وأن أبتْ فَلاَ جَوَازَ عَلَيْهَا يَعْنِي إِذَا أَدْرَكَتْ فردّتْ."],"takhrij":"حسن: رواه أبو داود (2093) والترمذي (1109) والنسائي (237) وأحمد (7572) وصحّحه ابن حبان (4086،4079) كلهم رووه عن جماعة عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب أن اليتيمة لا تنكح إلا بإذنها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2093), al-Tirmidhi (1109), al-Nasa’i (3270), and Ahmad (7519).","chapter_en":"Chapter on the orphan girl not being married except with her permission","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":30,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “The orphan girl is asked for permission regarding herself. If she remains silent, that is her permission, and if she refuses, she is not to be forced.” Meaning: when she reaches maturity and rejects it."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2093,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1109},{"key":"nasai","label":"النسائي","number":3270,"n":3270},{"key":"ahmad","label":"أحمد","number":7519,"n":7527},{"key":"nasai","label":"النسائي","number":237},{"key":"ahmad","label":"احمد","number":7572,"n":7527},{"key":"ibnhibban","label":"ابن حبان","number":4086},{"key":"ibnhibban","label":"ابن حبان","number":4079}],"full":1,"dr":1},{"num":6261,"demo":false,"sanad":"","matn":["اللهِ بْنِ عَبَّاسٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْأَيِّمُ أَوْلَى بِأَمْرِهَا، وَالْيَتِيمَةُ تُسْتَأْمَرُ فِي نَفْسِهَا، وَإِذْنُهَا صُمَاتُهَا."],"takhrij":"حسن: رواه النسائي (3262) عن أحمد بن سعيد الرباطي، قال: حدثنا يعقوب، قال: حدثني أبي، عن ابن إسحاق قال: حدثني صالح بن كيسان، عن عبد الله بن الفضل بن عباس بن ربيعة، عن نافع بن جبير بن مطعم، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب أن اليتيمة لا تنكح إلا بإذنها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (3262), Ahmad (2365), Ibn Abi Shaybah (4/136), and al-Daraqutni (3/238–239).","chapter_en":"Chapter on the orphan girl not being married except with her permission","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":30,"content":{"translation":{"en":["Ibn ‘Abbas narrated that the Messenger of Allah ﷺ said: “The previously married woman has more right concerning her affair, and the orphan girl is asked for permission regarding herself, and her permission is her silence.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3262,"lafz":true},{"key":"sh9944","label":"ابن أبي شيبة","number":4},{"key":"sh9771","label":"الدارقطني","number":3},{"key":"ahmad","label":"مسند الإمام أحمد","number":2365,"n":2365},{"key":"sh9771","label":"سنن الدارقطني","number":3575,"n":3588}],"full":1,"dr":1},{"num":6262,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ تَسْأَلِ الْمَرْأَةُ طَلاَقَ أُخْتِهَا لِتَسْتَفْرِغَ صَحْفَتَهَا، وَلْتَنْكِحْ، فَإِنَّ لَهَا مَا قُدِّرَ لَهَا."],"takhrij":"متفق عليه: رواه مالك في القدر (7) عن أبي الزّناد، عن الأعرج، عن أبي هريرة، فذكره. ورواه البخاري في القدر (6601) من طريق مالك، به.","grade":"متفق عليه","chapter_ar":"باب اشتراط المرأة أن يطلق الزوجُ زوجتَه الأولى","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (7), al-Bukhari (6601), and Muslim (38:1408).","chapter_en":"Chapter on a woman stipulating that a husband divorce his first wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":31,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “A woman must not ask for her sister to be divorced so that she may empty her bowl. Let her marry, for she will only have what has been decreed for her.”"]},"buhuth":{"en":["His saying, “her bowl,” refers to a dish from the dishes used for food."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":7},{"key":"bukhari","label":"البخاري","number":6601,"lafz":true},{"key":"muslim","label":"مسلم","number":38}],"full":1,"dr":1},{"num":6263,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ التَّلَقِّي، وَأَنْ يَبْتَاعَ الْمُهَاجِرُ لِلأَعْرَابِيِّ، وَأَنْ تَشْتَرِطَ الْمَرْأَةُ طَلاَقَ أُخْتِهَا، وَأَنْ."],"takhrij":"صحيح: رواه البخاري في الشروط (2727) عن محمد بن عرعرة، حدثنا شعبة، عن عدي بن ثابت، عن أبي حازم، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب اشتراط المرأة أن يطلق الزوجُ زوجتَه الأولى","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2727).","chapter_en":"Chapter on a woman stipulating that a husband divorce his first wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":31,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ forbade meeting traders before they reached the market, forbade a townsman from buying on behalf of a Bedouin, and forbade a woman from stipulating the divorce of her sister… the rest of the hadith."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2727,"lafz":true}],"full":1},{"num":6264,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتِ: اخْتَصَمَ سَعْدُ بْنُ أَبِي وَقَّاصٍ وَعَبْدُ بْنُ زَمْعَةَ فِي غُلاَمٍ. فَقَالَ سَعْدٌ: هَذَا يَا رَسُولَ اللَّهِ ابْنُ أَخِي عُتْبَةَ بْنِ أَبِي وَقَّاصٍ عَهد إليَّ أَنَّهُ ابْنُهُ. انْظُرْ إِلَى شَبَهِهِ، وَقَالَ عَبْدُ بْنُ زَمْعَةَ: هَذَا أَخِي يَا رَسُولَ اللَّهِ وُلِدَ عَلَى فِرَاشِ أَبِي مِنْ وَلِيدَتِهِ. فَنَظَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى شَبَهِهِ فَرَأَى شَبَهًا بَيِّنًا بعُتْبة فَقَالَ: هُوَ لَكَ يَا عَبْدُ بن زَمْعَةَ، الْوَلَدُ لِلْفِرَاشِ، وَلِلْعَاهِرِ الْحَجَرُ وَاحْتَجِبِي مِنْهُ يَا سَوْدَةُ بِنْتَ زَمْعَةَ فَلَمْ تَرَهُ قَطُّ، وَفِي رِوَايَةِ زيادة: هُوَ أَخُوكَ يَا عَبْدُ."],"takhrij":"متفق عليه: رواه مالك في الأقضية (22) عن ابن شهاب، عن عروة، عن عائشة فذكرته. ورواه البخاري في البيوع (2218) ومسلم في الرضاعة (1457) كلاهما عن قتيبة بن سعيد، حدثنا الليث، عن ابن شهاب بإسناده مثله.","grade":"متفق عليه","chapter_ar":"باب اشتراط المرأة أن يطلق الزوجُ زوجتَه الأولى","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (22), al-Bukhari (2218), and Muslim (1457).","chapter_en":"Chapter on a woman stipulating that a husband divorce his first wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":31,"content":{"translation":{"en":["‘A’ishah said: Sa‘d ibn Abi Waqqas and ‘Abdullah ibn Zam‘ah disputed over a boy. Sa‘d said: O Messenger of Allah, this is the son of my brother ‘Utbah ibn Abi Waqqas. He entrusted me that he was his son. Look at his resemblance. ‘Abd ibn Zam‘ah said: This is my brother, O Messenger of Allah. He was born on my father’s bed from his slave-woman. The Messenger of Allah ﷺ looked at his resemblance and saw a clear resemblance to ‘Utbah, so he said: “He is yours, O ‘Abd ibn Zam‘ah. The child belongs to the marriage bed, and the adulterer gets the stone. And veil yourself from him, O Sawdah bint Zam‘ah.” So she never saw him again. In another narration there is the addition: “He is your brother, O ‘Abd.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":22,"lafz":true},{"key":"bukhari","label":"البخاري","number":2218},{"key":"muslim","label":"مسلم","number":1457}],"full":1,"dr":1},{"num":6265,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ،. أَنَّ رَجُلاً، مِنْ أَهْلِ الْبَادِيَةِ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ امْرَأَتِي وَلَدَتْ عَلَى فِرَاشِي غُلاَمًا أَسْوَدَ وَإِنَّا أَهْلُ بَيْتٍ لَمْ يَكُنْ فِينَا أَسْوَدُ قَطُّ. قَالَ هَلْ لَكَ مِنَ إِبِلٍ. قَالَ نَعَمْ. قَالَ فَمَا أَلْوَانُهَا. قَالَ حُمْرٌ. قَالَ هَلْ فِيهَا أَسْوَدُ. قَالَ لاَ. قَالَ فَهَلْ فِيهَا أَوْرَقُ. قَالَ نَعَمْ. قَالَ فَأَنَّى كَانَ ذَلِكَ. قَالَ عَسَى أَنْ يَكُونَ نَزَعَهُ عِرْقٌ. قَالَ فَلَعَلَّ ابْنَكَ هَذَا نَزَعَهُ عِرْقٌ."],"takhrij":"حسن: رواه ابن ماجه (2003) عن أبي كريب، قال: حدثنا عبادة بن كليب الليثي أبو غسان، عن جويرية بن أسماء، عن نافع، عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب اشتراط المرأة أن يطلق الزوجُ زوجتَه الأولى","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2003).","chapter_en":"Chapter on a woman stipulating that a husband divorce his first wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":31,"content":{"translation":{"en":["Ibn ‘Umar narrated that a man from the desert came to the Prophet ﷺ and said: O Messenger of Allah, my wife has given birth on my bed to a black boy, and we are a household in which there has never been any black person. He said: “Do you have camels?” He said: Yes. He said: “What are their colors?” He said: Red. He said: “Are there any black among them?” He said: No. He said: “Are there any grayish ones among them?” He said: Yes. He said: “How did that happen?” He said: Perhaps some inherited trait drew it out. He said: “Then perhaps this son of yours was likewise drawn out by an inherited trait.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2003,"lafz":true}],"full":1,"dr":1},{"num":6266,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قـال: قـال النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْوَلَدُ لِلْفِرَاشِ وَلِلْعَاهِرِ الْحَجَرُ."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6818) عن آدم، حدثنا شعبة، حدثنا محمد بن زياد، قال: سمعت أبا هريرة يقول: فذكره. ورواه مسلم في الرضاع (1458) من أوجه أخرى عن أبي هريرة مثله.","grade":"متفق عليه","chapter_ar":"باب اشتراط المرأة أن يطلق الزوجُ زوجتَه الأولى","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6818) and Muslim (1458).","chapter_en":"Chapter on a woman stipulating that a husband divorce his first wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":31,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ said: “The child belongs to the marriage bed, and the adulterer gets the stone.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6818,"lafz":true},{"key":"muslim","label":"مسلم","number":1458}],"full":1},{"num":6267,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ الْوَلَدُ لِلْفِرَاشِ وَلِلْعَاهِرِ الْحَجَرُ."],"takhrij":"صحيح: رواه النسائي (3486) وابن حبان (4104) كلاهما من حديث جرير، عن مغيرة، عن أبي وائل، عن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب اشتراط المرأة أن يطلق الزوجُ زوجتَه الأولى","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3486) and Ibn Hibban (4104).","chapter_en":"Chapter on a woman stipulating that a husband divorce his first wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":31,"content":{"translation":{"en":["Ibn Mas‘ud said: The Messenger of Allah ﷺ said: “The child belongs to the marriage bed, and the adulterer gets the stone.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3486,"lafz":true,"n":3486},{"key":"ibnhibban","label":"ابن حبان","number":4104}],"full":1,"dr":1},{"num":6268,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى بِالْوَلَدِ لِلْفِرَاشِ."],"takhrij":"صحيح: رواه ابن ماجة (2005) وأحمد (173) كلاهما من حديث سفيان بن عيينة، عن عبيد الله بن أبي يزيد، عن أبيه، عن عمر فذكره.","grade":"صحيح","chapter_ar":"باب اشتراط المرأة أن يطلق الزوجُ زوجتَه الأولى","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2005) and Ahmad (173).","chapter_en":"Chapter on a woman stipulating that a husband divorce his first wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":31,"content":{"translation":{"en":["‘Umar narrated that the Messenger of Allah ﷺ ruled that the child belongs to the marriage bed."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2005,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":173,"n":173}],"full":1,"dr":1},{"num":6269,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ قَامَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ فُلاَنًا ابْنِي عَاهَرْتُ بِأُمِّهِ فِي الْجَاهِلِيَّةِ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ دِعْوَةَ فِي الإِسْلاَمِ ذَهَبَ أَمْرُ الْجَاهِلِيَّةِ الْوَلَدُ لِلْفِرَاشِ وَلِلْعَاهِرِ الْحَجَرُ."],"takhrij":"حسن: رواه أبو داود (2274) عن زهير بن حرب، حدثنا يزيد بن هارون، أخبرنا حسين المعلم، عن عمرو بن شعيب بإسناده فذكره.","grade":"حسن","chapter_ar":"باب اشتراط المرأة أن يطلق الزوجُ زوجتَه الأولى","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2274) and Imam Ahmad (6933).","chapter_en":"Chapter on a woman stipulating that a husband divorce his first wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":31,"content":{"translation":{"en":["‘Abdullah ibn ‘Amr ibn al-‘As said: A man stood up and said: O Messenger of Allah, so-and-so is my son; I committed fornication with his mother in the pre-Islamic period. The Messenger of Allah ﷺ said: “There is no such claim in Islam. The matter of the pre-Islamic period has passed. The child belongs to the marriage bed, and the adulterer gets the stone.”"]},"buhuth":{"en":["The word translated here as “claim” refers to a man attributing himself to someone other than his real father and tribe. They used to do that in the pre-Islamic period. Islam prohibited it and assigned the child to the marriage bed."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2274,"lafz":true},{"key":"ahmad","label":"الإمام أحمد","number":6933}],"full":1,"dr":1},{"num":6270,"demo":false,"sanad":"","matn":["عن أبي أمامة الباهلي يقول: سمعت رسول الله صلى الله عليه وسلم يقول في خطبة عام حجة الواداع: الولد للفراش وللعاهر الحجر."],"takhrij":"حسن: رواه الترمذي (2120) وأبو داود (3565) وابن ماجة (2007) وأحمد (22294) كلهم من حديث إسماعيل بن عياش قال:حدثنا شُرحبيل بن مسلم قال: سمعت أبا أمامة الباهلي فذكر الحديث في سياق طويل وفيه هذا الجزء، إلا أن أبا داود لم يذكره.","grade":"حسن","chapter_ar":"باب اشتراط المرأة أن يطلق الزوجُ زوجتَه الأولى","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (2120), Abu Dawud (3565), Ibn Majah (2007), and Ahmad (22294).","chapter_en":"Chapter on a woman stipulating that a husband divorce his first wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":31,"content":{"translation":{"en":["Abu Umamah al-Bahili said: I heard the Messenger of Allah ﷺ say in the sermon of the Farewell Pilgrimage: “The child belongs to the marriage bed, and the adulterer gets the stone.”"]},"buhuth":{"en":["Legal understanding of this chapter: It was among the customs of the pre-Islamic period to attach lineage through fornication. They used to hire slave women for intercourse, and if the mother acknowledged that the child belonged to a certain man, they would attach him to him. Islam came and abolished that, and commanded that the child be attributed to the marriage bed. This is what occurred in the dispute between Sa‘d ibn Abi Waqqas and ‘Abd ibn Zam‘ah ibn al-Aswad over a boy. ‘Utbah ibn Abi Waqqas had intercourse with the slave woman of Zam‘ah ibn al-Aswad, so she became pregnant and gave birth to a boy. When ‘Utbah was on his deathbed, he instructed his brother Sa‘d to take this boy and attribute him to him. ‘Utbah then died as a polytheist. After that, Sa‘d and ‘Abd ibn Zam‘ah disputed about the boy. Sa‘d argued for attributing the boy to his brother ‘Utbah according to their old custom of attributing children through fornication, while ‘Abd ibn Zam‘ah relied on his father’s marriage bed. So the Prophet ﷺ ruled: “The child belongs to the marriage bed,” and cut off attribution through fornication by saying: “and the adulterer gets the stone.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":2120,"lafz":true},{"key":"abudawud","label":"أبو داود","number":3565},{"key":"ibnmajah","label":"ابن ماجه","number":2007},{"key":"ahmad","label":"مسند الإمام أحمد","number":22294,"n":22294}],"full":1,"dr":1},{"num":6271,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَىَّ مَسْرُورًا تَبْرُقُ أَسَارِيرُ وَجْهِهِ فَقَالَ أَلَمْ تَرَىْ أَنَّ مُجَزِّزًا نَظَرَ آنِفًا إِلَى زَيْدِ بْنِ حَارِثَةَ وَأُسَامَةَ بْنِ زَيْدٍ، فَقَالَ إِنَّ هَذِهِ الأَقْدَامَ بَعْضُهَا مِنْ بَعْضٍ."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6770) ومسلم في الرضاع (1459) كلاهما عن قتيبة بن سعيد، حدثنا الليث، عن ابن شهاب، عن عروة، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب ثبوت النسب بالقافة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6770) and Muslim (1459).","chapter_en":"Chapter on establishing lineage through expert resemblance-tracing","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":32,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ entered upon me happy, with the lines of his face shining, and said: “Did you not see that Mujazziz just now looked at Zayd ibn Harithah and Usamah ibn Zayd and said: These feet belong to one another?”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6770,"lafz":true},{"key":"muslim","label":"مسلم","number":1459}],"full":1,"dr":1},{"num":6272,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ   قَالَ لاَ يَخْطُبُ أَحَدُكُمْ عَلَى خِطْبَةِ أَخِيهِ.","وزاد في رواية: حَتَّى يَتْرُكَ الْخَاطِبُ قَبْلَهُ، أَوْ يَأْذَنَ لَهُ الْخَاطِبُ."],"takhrij":"متفق عليه: رواه مالك في النكاح (2) عن نافع، عن عبد الله بن عمر، فذكره. ورواه البخاري في النكاح (5142) من طريق ابن جريج. والزيادة المذكورة له. ومسلم في النكاح (1412) من طريق الليث (هو ابن سعد)، وعبيد الله ( هو ابن عمر) وأيوب أربعتهم عن نافع، به، نحوه وزاد في أوله النهي عن بيع الرجل عن بيع أخيه.","grade":"متفق عليه","chapter_ar":"باب النهي أن يخطب الرّجل على خِطبة أخيه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (2), al-Bukhari (5142), and Muslim (1412).","chapter_en":"Chapter on the prohibition of a man proposing over his brother’s proposal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Ibn ‘Umar reported that the Messenger of Allah ﷺ said: “None of you should propose over the proposal of his brother.” In another narration there is an addition: “Until the first suitor leaves it or gives him permission.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":2,"lafz":true},{"key":"bukhari","label":"البخاري","number":5142},{"key":"muslim","label":"مسلم","number":1412}],"full":1},{"num":6273,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قَالَ لاَ يَخْطُبْ أَحَدُكُمْ عَلَى خِطْبَةِ أَخِيهِ حَتَّى يَنْكِحَ أَوْ يَتْرُكَ."],"takhrij":"متفق عليه: رواه مالك في النكاح (1) عن محمد بن يحيى بن حبّان، عن الأعرج، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي أن يخطب الرّجل على خِطبة أخيه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (1), al-Bukhari (5143), and Muslim (1413).","chapter_en":"Chapter on the prohibition of a man proposing over his brother’s proposal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “None of you should propose over the proposal of his brother.” In another narration there is an addition: “Until he marries or leaves it.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":1,"lafz":true},{"key":"bukhari","label":"البخاري","number":5143,"n":5026},{"key":"muslim","label":"مسلم","number":1413,"n":3461}],"full":1,"dr":1},{"num":6274,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرِ بْنِ أَبِي، الْجَهْمِ بْنِ صُخَيْرٍ الْعَدَوِيِّ قَالَ سَمِعْتُ فَاطِمَةَ بِنْتَ قَيْسٍ، تَقُولُ إِنَّ زَوْجَهَا طَلَّقَهَا ثَلاَثًا فَلَمْ يَجْعَلْ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُكْنَى وَلاَ نَفَقَةً قَالَتْ قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا حَلَلْتِ فَآذِنِينِي. فَآذَنْتُهُ فَخَطَبَهَا مُعَاوِيَةُ وَأَبُو جَهْمٍ وَأُسَامَةُ بْنُ زَيْدٍ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَّا مُعَاوِيَةُ فَرَجُلٌ تَرِبٌ لاَ مَالَ لَهُ وَأَمَّا أَبُو جَهْمٍ فَرَجُلٌ ضَرَّابٌ لِلنِّسَاءِ وَلَكِنْ أُسَامَةُ بْنُ زَيْدٍ. فَقَالَتْ بِيَدِهَا هَكَذَا أُسَامَةُ أُسَامَةُ فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَاعَةُ اللَّهِ وَطَاعَةُ رَسُولِهِ خَيْرٌ لَكِ. قَالَتْ فَتَزَوَّجْتُهُ فَاغْتَبَطْتُ."],"takhrij":"صحيح: رواه مسلم في الطلاق (47:1480) عن أبي بكر بن أبي شيبة، حدثنا وكيع، حدثنا سليمان، عن أبي بكر بن أبي الجهم فذكره.","grade":"صحيح","chapter_ar":"باب النهي أن يخطب الرّجل على خِطبة أخيه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (47:1480). His saying “tārib” means poor, because from the severity of his poverty he is as though attached to the dust.","chapter_en":"Chapter on the prohibition of a man proposing over his brother’s proposal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abu Bakr ibn Abi al-Jahm ibn Sukhayr al-‘Adawi said: I heard Fatimah bint Qays say that her husband divorced her three times, and the Messenger of Allah ﷺ did not assign for her any housing or maintenance. She said: The Messenger of Allah ﷺ said to me, “When you become lawful for marriage, inform me.” So I informed him. Then Mu‘awiyah, Abu Jahm, and Usamah ibn Zayd proposed to her. The Messenger of Allah ﷺ said: “As for Mu‘awiyah, he is a poor man with no wealth. As for Abu Jahm, he is a man who beats women. Rather, marry Usamah ibn Zayd.” She gestured with her hand like this and said: Usamah? Usamah? So the Messenger of Allah ﷺ said to her: “Obedience to Allah and obedience to His Messenger are better for you.” She said: So I married him and was greatly pleased."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":47,"lafz":true}],"full":1,"dr":1},{"num":6275,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَلَمَةَ، أَنَّ فَاطِمَةَ بِنْتَ قَيْسٍ – أُخْتَ الضَّحَّاكِ بْنِ قَيْسٍ-أَخْبَرَتْهُ أنّ أَبَا حَفْصِ ابن الْمُغِيرَةِ الْمَخْزُومِيَّ طَلَّقَهَا ثَلاَثًا. ثُمَّ انْطَلَقَ إِلَى الْيَمَنِ. فَقَالَ لَهَا أَهْلُهُ: لَيْسَ لَكِ عَلَيْنَا نَفَقَةٌ فَانْطَلَقَ خَالِدُ بْنُ الْوَلِيدِ فِي نَفَرٍ، فَأَتَوْا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَيْتِ مَيْمُونَةَ. فَقَالُوا: إِنَّ أَبَا حَفْصٍ طلّق امْرَأَتَهُ ثَلاَثًا، فَهَلْ لَهَا مِنْ نَفَقَةٍ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَيْسَتْ لَهَا نَفَقَةٌ، وَعَلَيْهَا الْعِدَّةُ وَأَرْسَلَ إِلَيْهَا: أَنْ لاَ تَسْبِقِينِي بِنَفْسِكِ ... الحديث. وَفِي لفظ : لاَ تفوتينا بِنَفْسِكِ."],"takhrij":"صحيح: رواه مسلم في الطلاق (38:1480) عن محمد بن رافع، حدّثنا حسين بن محمد، حدّثنا شيبان، عن يحيى ( وهو ابن كثير)، أخبرني أبو سلمة، فذكره.","grade":"صحيح","chapter_ar":"باب التعريض لخطبة المرأة المتوفى عنها زوجها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (38:1480). His saying “Do not get ahead of us regarding yourself” contains an indirect indication of proposing.","chapter_en":"Chapter on indirect mention of proposing to a woman whose husband has died","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Abu Salamah reported that Fatimah bint Qays, the sister of al-Dahhak ibn Qays, informed him that Abu Hafs ibn al-Mughirah al-Makhzumi divorced her three times, then left for Yemen. His family said to her: You have no maintenance due from us. So Khalid ibn al-Walid went with a group to the Messenger of Allah ﷺ in the house of Maymunah and said: Abu Hafs has divorced his wife three times, so does she have any maintenance? The Messenger of Allah ﷺ said: “She has no maintenance, but she must observe the waiting period.” And he sent word to her: “Do not get ahead of us regarding yourself…” in the rest of the hadith. In another wording: “Do not let us miss the chance regarding yourself.”"]},"intro":{"ar":["قال الله تعالى: ﴿ وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا عَرَّضْتُمْ بِهِ مِنْ خِطْبَةِ النِّسَاءِ أَوْ أَكْنَنْتُمْ فِي أَنْفُسِكُمْ ﴾ [البقرة: ٢٣٥]","قال ابن عباس: ( فِيمَا عَرَّضْتُمْ ) يقول:  إني أريد التزويج، ولوددتُ أنه يُيسَّر لي امرأة صالحة .","صحيح: رواه البخاري (٥١٢٤)."],"en":["Allah Most High said: “There is no blame upon you for what you indirectly allude to concerning a proposal to women, or what you keep concealed within yourselves.” [al-Baqarah: 235]","Ibn ‘Abbas said regarding “what you indirectly allude to”: It means saying, “I wish to marry, and I would like for a righteous woman to be made easy for me.”","Authentic: Narrated by al-Bukhari (5124)."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":38,"lafz":true}],"full":1,"dr":1},{"num":6276,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعَلِّمُنَا الاِسْتِخَارَةَ فِي الأُمُورِ كَمَا يُعَلِّمُنَا السُّورَةَ مِنَ الْقُرْآنِ يَقُولُ إِذَا هَمَّ أَحَدُكُمْ بِالأَمْرِ فَلْيَرْكَعْ رَكْعَتَيْنِ مِنْ غَيْرِ الْفَرِيضَةِ ثُمَّ لِيَقُلِ اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلاَ أَقْدِرُ وَتَعْلَمُ وَلاَ أَعْلَمُ وَأَنْتَ عَلاَّمُ الْغُيُوبِ، اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي ـ أَوْ قَالَ عَاجِلِ أَمْرِي وَآجِلِهِ ـ فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي ثُمَّ بَارِكْ لِي فِيهِ، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي ـ أَوْ قَالَ فِي عَاجِلِ أَمْرِي وَآجِلِهِ ـ فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِي الْخَيْرَ حَيْثُ كَانَ ثُمَّ أَرْضِنِي بِهِ ـ قَالَ ـ وَيُسَمِّي حَاجَتَهُ."],"takhrij":"صحيح: رواه البخاري في التهجد (1162) عن قتيبة قال: حدثنا عبد الرحمن بن أبي الموالِ، عن محمد بن المنكدر، عن جابر بن عبدالله فذكره.","grade":"صحيح","chapter_ar":"باب الاستخارة في الخِطبة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (1162).","chapter_en":"Chapter on seeking guidance in betrothal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported: The Messenger of Allah ﷺ used to teach us istikhārah concerning all matters just as he would teach us a surah from the Qurʾān. He would say: “When one of you intends to undertake a matter, let him pray two rakʿahs other than the obligatory prayer, then say: ‘O Allah, I seek the better choice from You by Your knowledge, and I seek ability from You by Your power, and I ask You from Your immense bounty. You are able and I am not; You know and I do not know; and You are the Knower of the unseen. O Allah, if You know that this matter is good for me in my religion, my livelihood, and the outcome of my affair—or he said: in the immediate and later parts of my affair—then decree it for me, make it easy for me, and then bless it for me. And if You know that this matter is bad for me in my religion, my livelihood, and the outcome of my affair—or he said: in the immediate and later parts of my affair—then turn it away from me and turn me away from it, decree good for me wherever it may be, and then make me content with it.’” He said: “And he should mention his particular need.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1162,"lafz":true,"n":1166}],"full":1},{"num":6277,"demo":false,"sanad":"","matn":["عَنْ أَيُّوبَ بْنِ خَالِدِ بْنِ أَبِي أَيُّوبَ الْأَنْصَارِيِّ، حَدَّثَهُ عَنْ أَبِيهِ، عَنْ جَدِّهِ أَبِي أَيُّوبَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: اكْتُمِ الْخِطْبَةَ، ثُمَّ تَوَضَّأْ فَأَحْسِنْ وُضُوءَكَ، ثُمَّ صلِّ مَا كَتَبَ اللَّهُ لَكَ، ثُمَّ احْمَدْ ربّك، وَمَجِّدْهُ ثُمَّ قُلْ: اللهُمَّ إِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ، وَتَعْلَمُ وَلَا أَعْلَمُ، وَأَنْتَ عَلَّامُ الْغُيُوبِ، فَإِنْ رَأَيْتَ فِي فُلَانَةَ – تُسَمِّيهَا بِاسْمِهَا-خَيْرًا لِي فِي دِينِي وَدُنْيَايَ وَآخِرَتِي فَاقْدِرْهَا لِي، وَإِنْ كَانَ غَيْرُهَا خَيْرًا لِي مِنْهَا فِي دِينِي وَدُنْيَايَ وَآخِرَتِي فَاقْضِ لِي ذَلِكَ."],"takhrij":"حسن: رواه أحمد (23597) وابن خزيمة (1220) وابن حبان (4040) والحاكم (1/314) والبيهقي (7/147-148) وابن المنذر في الأوسط (8/233) كلهم من طريق ابن وهب، أخبرني حيوة، أن الوليد بن الوليد أخبره، أن أيوب بن خالد بن أبي أيوب حدثه بإسناده ومعناه. قال الحاكم: هذه سنة صلاة الاستخارة عزيزة تفرد بها أهل مصر، ورواته عن أخرهم ثقات، ولم يخرجاه.","grade":"حسن","chapter_ar":"باب الاستخارة في الخِطبة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (23597), Ibn Khuzaymah (1220), Ibn Hibban (4040), and al-Hakim (1181).","chapter_en":"Chapter on seeking guidance in betrothal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Ayyub ibn Khalid ibn Abi Ayyub al-Ansari narrated from his father, from his grandfather Abu Ayyub, that the Messenger of Allah ﷺ said: “Keep the proposal concealed, then perform ablution and do it well, then pray whatever Allah has prescribed for you, then praise your Lord and glorify Him, then say: O Allah, You are able and I am not able, and You know and I do not know, and You are the Knower of the unseen. If You know that there is good for me in so-and-so — naming her by name — in my religion, my worldly life, and my Hereafter, then decree her for me. And if someone other than her is better for me than her in my religion, my worldly life, and my Hereafter, then decree that for me.”"]}},"tuhfa":{},"refs":[{"key":"ibnkhuzaymah","label":"ابن خزيمة","number":1220},{"key":"ahmad","label":"مسند الإمام أحمد","number":23596,"n":23596,"lafz":true},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1747,"n":1744},{"key":"hakim","label":"المستدرك على الصحيحين","number":1181,"n":1174},{"key":"ahmad","label":"احمد","number":23597,"n":23596},{"key":"ibnhibban","label":"ابن حبان","number":4040}],"full":1,"dr":1},{"num":6278,"demo":false,"sanad":"","matn":["عَنْ سهيل بن سَعْدٍ: أَنَّ امْرَأَةً جَاءَتْ إِلَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ، جئتُ لأَهَبَ لَكَ نَفْسِي! فَنَظَرَ إِلَيْهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَعَّدَ النَّظَرَ إِلَيْهَا وَصَوَّبَهُ، ثُمَّ طَأْطَأَ رَأْسَهُ. فَلَمَّا رَأَتِ الْمَرْأَةُ أَنَّهُ لَمْ يَقْضِ فِيهَا شَيْئًا جَلَسَتْ.....الحديث."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5126) ومسلم في النكاح(76:1425)كلاهما عن قتيبة بن سعيد الثقفي، حدّثنا يعقوب ( يعني ابن عبدالرحمن القاريّ)، عن أبي حازم، عن سهل بن سعد، فذكره.","grade":"متفق عليه","chapter_ar":"باب النظر إلى المخطوبة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5126) and Muslim (1425/76).","chapter_en":"Chapter on looking at the woman one intends to marry","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Sahl ibn Saʿd reported: A woman came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, I have come to offer myself to you.” The Messenger of Allah ﷺ looked at her, looking her up and down, then lowered his head. When the woman saw that he had not made any decision concerning her, she sat down… the remainder of the hadith."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5126,"lafz":true},{"key":"muslim","label":"مسلم","number":1425},{"key":"muslim","label":"مسلم في النكاح","number":76}],"full":1},{"num":6279,"demo":false,"sanad":"","matn":["عَنْ أَبِي، هُرَيْرَةَ قَالَ كُنْتُ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَتَاهُ رَجُلٌ فَأَخْبَرَهُ أَنَّهُ تَزَوَّجَ امْرَأَةً مِنَ الأَنْصَارِ فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَظَرْتَ إِلَيْهَا. قَالَ لاَ. قَالَ فَاذْهَبْ فَانْظُرْ إِلَيْهَا فَإِنَّ فِي أَعْيُنِ الأَنْصَارِ شَيْئًا."],"takhrij":"صحيح: رواه مسلم في النكاح (1424: 74) عن ابن أبي عمر، حدّثنا سفيان، عن يزيد بن كيسان، عن أبي حازم، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب النظر إلى المخطوبة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (74:1424). His statement “there is something in the eyes of the Ansar” was said by some to mean smallness, and by others to mean a bluish tint.","chapter_en":"Chapter on looking at the woman one intends to marry","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah said: I was with the Prophet ﷺ when a man came to him and informed him that he had married a woman from the Ansar. The Messenger of Allah ﷺ said to him: “Did you look at her?” He said: No. He said: “Then go and look at her, for there is something in the eyes of the Ansar.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":74,"lafz":true},{"key":"muslim","label":"مسلم في النكاح","number":1424}],"full":1,"dr":1},{"num":6280,"demo":false,"sanad":"","matn":["عَنْ أَبِي حُمَيْدٍ أَوْ أَبِي حُمَيْدَةَ - وَقَدْ رَأَى رسول اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا خَطَبَ أَحَدُكُمْ امْرَأَةً فَلَا جُنَاحَ عَلَيْهِ أَنْ يَنْظُرَ إِلَيْهَا، إِذَا كَانَ إِنَّمَا يَنْظُرُ لِخِطْبَةٍ، وَإِنْ كَانَتْ لَا تَعْلَمُ."],"takhrij":"صحيح: رواه أحمد (23603) عن أبي كامل، حدثنا زهير، حدثنا عبدالله بن عيسى، حدثني موسى بن عبدالله بن يزيد، عن أبي حُميد أو أبي حميدة فذكره.","grade":"صحيح","chapter_ar":"باب النظر إلى المخطوبة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (23602).","chapter_en":"Chapter on looking at the woman one intends to marry","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Abu Humayd, or Abu Humaydah — and he had seen the Messenger of Allah ﷺ — said: The Messenger of Allah ﷺ said: “When one of you proposes to a woman, there is no blame on him if he looks at her, so long as he is only looking for the sake of marriage, even if she does not know.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":23602,"n":23602,"lafz":true},{"key":"ahmad","label":"احمد","number":23603}],"full":1,"dr":1},{"num":6281,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ، قَالَ أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرْتُ لَهُ امْرَأَةً أَخْطُبُهَا فَقَالَ اذْهَبْ فَانْظُرْ إِلَيْهَا فَإِنَّهُ أَجْدَرُ أَنْ يُؤْدَمَ بَيْنَكُمَا. فَأَتَيْتُ امْرَأَةً مِنَ الأَنْصَارِ فَخَطَبْتُهَا إِلَى أَبَوَيْهَا وَأَخْبَرْتُهُمَا بِقَوْلِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَكَأَنَّهُمَا كَرِهَا ذَلِكَ. قَالَ فَسَمِعَتْ ذَلِكَ الْمَرْأَةُ وَهِيَ فِي خِدْرِهَا فَقَالَتْ إِنْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَكَ أَنْ تَنْظُرَ فَانْظُرْ. وَإِلاَّ فَإِنِّي أَنْشُدُكَ كَأَنَّهَا أَعْظَمَتْ ذَلِكَ. قَالَ فَنَظَرْتُ إِلَيْهَا فَتَزَوَّجْتُهَا. فَذَكَرَ مِنْ مُوَافَقَتِهَا."],"takhrij":"صحيح: رواه الترمذي (1087) والنسائي (3235) وابن ماجة (1866) وأحمد (18137) واللفظ له، والبيهقي (7/84-85) وابن الجارود (675) كلهم من حديث بكر بن عبد الله المزني، عن المغيرة بن شعبة فذكره. واختصر البعض. وزاد البيهقي: فما وقعت عندي امرأة بمنزلتها، ولقد تزوجت سبعين، أو بضع وسبعين امرأة.","grade":"صحيح","chapter_ar":"باب النظر إلى المخطوبة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1087), al-Nasa’i (3235), Ibn Majah (1866), and Ahmad (18137). The wording is that of Ahmad.","chapter_en":"Chapter on looking at the woman one intends to marry","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Al-Mughirah ibn Shu‘bah said: I came to the Prophet ﷺ and mentioned to him a woman whom I intended to propose to. He said: “Go and look at her, for that is more likely to bring harmony between you.” He said: So I went to a woman from the Ansar and proposed to her through her parents, and I informed them of the statement of the Messenger of Allah ﷺ. It was as if they disliked that. Then the woman heard that while she was in her private chamber, and she said: If the Messenger of Allah ﷺ commanded you to look, then look; otherwise, I place you under a solemn appeal. It was as though she regarded the matter as weighty for him. He said: So I looked at her and married her, and he mentioned her good compatibility."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1087,"lafz":true},{"key":"nasai","label":"النسائي","number":3235},{"key":"ibnmajah","label":"ابن ماجه","number":1866},{"key":"ahmad","label":"مسند الإمام أحمد","number":18137,"n":18137},{"key":"sh13071","label":"ابن الجارود","number":675}],"full":1,"dr":1},{"num":6282,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِذَا خَطَبَ أَحَدُكُمُ الْمَرْأَةَ، فَقَدِرَ أَنْ يَرَى مِنْهَا بَعْضَ مَا يَدْعُوهُ إِلَيْهَا، فَلْيَفْعَلْ."],"takhrij":"حسن: رواه الإمام أحمد (14869) عن يعقوب، حدثنا أبي، عن ابن إسحاق، حدثني داود بن الحصين مولى عمرو بن عثمان، عن واقد بن عمرو بن سعد بن معاذ، عن جابر بن عبدالله فذكره.","grade":"حسن","chapter_ar":"باب النظر إلى المخطوبة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (14869).","chapter_en":"Chapter on looking at the woman one intends to marry","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah al-Ansari said: I heard the Messenger of Allah ﷺ say: “When one of you proposes to a woman, if he is able to see something of her that will encourage him to marry her, then let him do so.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":14869,"lafz":true}],"full":1,"dr":1},{"num":6283,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ كَتَبَ عَلَى ابْنِ آدَمَ حَظَّهُ مِنَ الزِّنَا، أَدْرَكَ ذَلِكَ لاَ مَحَالَةَ، فَزِنَا الْعَيْنِ النَّظَرُ، وَزِنَا اللِّسَانِ الْمَنْطِقُ، وَالنَّفْسُ تمني وَتَشْتَهِي، وَالْفَرْجُ يُصَدِّقُ ذَلِكَ كُلَّهُ وَيُكَذِّبُهُ."],"takhrij":"متفق عليه: رواه البخاري في الإستئذان (6243) ومسلم في القدر (2657) كلاهما من حديث عبد الرزاق، أخبرنا معمر، عن ابن طاوس، عن أبيه، عن ابن عباس قال: ما رأيت شيئاً أشبه باللمم مما قال قال أبو هريرة، عن النبي صلى الله عليه وسلم فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب في غض البصر وتحريم النظر إلى الأجنبية بغير قصد الخطبة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6243) and Muslim (2657).","chapter_en":"Chapter on lowering the gaze and the prohibition of looking at a non-related woman without the intention of betrothal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ said: “Allah has decreed for the son of Adam his share of adultery, and he will inevitably reach it. The adultery of the eye is looking, the adultery of the tongue is speaking, and the soul wishes and desires, while the private part confirms all of that or denies it.”"]},"intro":{"ar":["قال اللّٰه تعالى: ﴿ قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ذَٰلِكَ أَزْكَى لَهُمْ إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ ﴾ [النور: ٣٠]"],"en":["Allah Most High said: “Tell the believing men to lower their gaze and guard their private parts. That is purer for them. Indeed Allah is fully aware of what they do.” [Al-Nur: 30]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6243,"lafz":true},{"key":"muslim","label":"مسلم","number":2657}],"full":1},{"num":6284,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ كُتِبَ عَلَى ابْنِ آدَمَ نَصِيبُهُ مِنَ الزِّنَى مُدْرِكٌ ذَلِكَ لاَ مَحَالَةَ فَالْعَيْنَانِ زِنَاهُمَا النَّظَرُ وَالأُذُنَانِ زِنَاهُمَا الاِسْتِمَاعُ وَاللِّسَانُ زِنَاهُ الْكَلاَمُ وَالْيَدُ زِنَاهَا الْبَطْشُ وَالرِّجْلُ زِنَاهَا الْخُطَا وَالْقَلْبُ يَهْوَى وَيَتَمَنَّى وَيُصَدِّقُ ذَلِكَ الْفَرْجُ وَيُكَذِّبُهُ."],"takhrij":"صحيح: رواه مسلم في القدر (21:2657) عن إسحاق بن منصور، أخبرنا أبو هشام المخزومي، حدثنا وُهيب، حدثنا سهيل بن أبي صالح، عن أبيه، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب في غض البصر وتحريم النظر إلى الأجنبية بغير قصد الخطبة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (21:2657).","chapter_en":"Chapter on lowering the gaze and the prohibition of looking at a non-related woman without the intention of betrothal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ: “The share of adultery decreed for the son of Adam will inevitably reach him. The adultery of the eyes is looking, the adultery of the ears is listening, the adultery of the tongue is speech, the adultery of the hand is grasping, the adultery of the foot is walking, and the heart desires and wishes, while the private part confirms that or denies it.”"]},"buhuth":{"en":["Abu Dawud (2152) narrated it through another route and added: “And the mouth commits adultery, and its adultery is kissing.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":21,"lafz":true}],"full":1,"dr":1,"rep":[12868]},{"num":6285,"demo":false,"sanad":"","matn":["عَنْ جَرِيرِ بْنِ عَبْدِ اللَّهِ، قَالَ سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ نَظَرِ الْفُجَاءَةِ فَأَمَرَنِي أَنْ أَصْرِفَ بَصَرِي."],"takhrij":"صحيح: رواه مسلم في الآداب (2159) من طرق عن عمرو بن سعيد، عن أبي زرعة، عن جرير بن عبد الله، فذكره.","grade":"صحيح","chapter_ar":"باب في غض البصر وتحريم النظر إلى الأجنبية بغير قصد الخطبة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2159).","chapter_en":"Chapter on lowering the gaze and the prohibition of looking at a non-related woman without the intention of betrothal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Jarir ibn ‘Abd Allah said: I asked the Messenger of Allah ﷺ about the accidental glance, and he ordered me to turn my gaze away."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2159,"lafz":true}],"full":1,"rep":[12865,14186]},{"num":6286,"demo":false,"sanad":"","matn":["عَنِ ابْنِ بُرَيْدَةَ، عَنْ أَبِيهِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِعَلِيٍّ رَضِيَ اللَّهُ عَنْهُ: يَا عَلِيُّ، لَا تُتْبِعِ النَّظْرَةَ النَّظْرَةَ، فَإِنَّ لَكَ الْأُولَى، وَلَيْسَتْ لَكَ الْآخِرَةُ."],"takhrij":"حسن: رواه أبو داود (2148) والترمذي (2777) والحاكم (2/194) والبيهقي (7/90) وأحمد (22974) والطحاوي في مشكله (1866) كلهم من حديث شريك، عن أبي ربيعة، عن ابن بريدة، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب في غض البصر وتحريم النظر إلى الأجنبية بغير قصد الخطبة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2148), al-Tirmidhi (2777), who graded it Hasan, al-Hakim (2788), and Ahmad (22974).","chapter_en":"Chapter on lowering the gaze and the prohibition of looking at a non-related woman without the intention of betrothal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Ibn Buraydah narrated from his father that the Messenger of Allah ﷺ said: “O ‘Ali, do not follow one look with another, for you are allowed the first, but not the second.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2148,"lafz":true,"n":2149},{"key":"tirmidhi","label":"الترمذي","number":2777},{"key":"hakim","label":"المستدرك على الصحيحين","number":2788,"n":2774},{"key":"ahmad","label":"مسند الإمام أحمد","number":22974,"n":22974},{"key":"sh13078","label":"الورع لابن أبي الدنيا","number":69,"n":36},{"key":"sh22547","label":"الطحاوي في مشكله","number":1866}],"full":1,"dr":1,"rep":[12866]},{"num":6287,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ، رَضِيَ اللَّهُ عَنْهُ، قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تُتْبِعِ النَّظَرَ النَّظَرَ، فَإِنَّ الْأُولَى لَكَ وَلَيْسَتْ لَكَ الْآخِرَةُ."],"takhrij":"حسن: رواه أحمد (1369) والبزار – كشف الأستار (907) والدارمي (2751) والطحاوي في مشكله (1865) وابن حبان (5570) والحاكم (3/123) كلهم من طرق عن حماد بن سلمة، عن محمد بن إسحاق، عن محمد بن إبراهيم، عن سلمة بن أبي الطفيل، عن علي فذكره.","grade":"حسن","chapter_ar":"باب في غض البصر وتحريم النظر إلى الأجنبية بغير قصد الخطبة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (1369), al-Bazzar in Kashf al-Astar (907), al-Darimi (2751), and al-Tahawi in Mushkil al-Athar (1865).","chapter_en":"Chapter on lowering the gaze and the prohibition of looking at a non-related woman without the intention of betrothal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["‘Ali ibn Abi Talib said: The Messenger of Allah ﷺ said to me: “Do not follow one look with another, for the first is for you, but the second is not for you.”"]}},"tuhfa":{},"refs":[{"key":"sh12862","label":"البزار - كشف الأستار","number":907},{"key":"darimi","label":"الدارمي","number":2751},{"key":"sh22547","label":"الطحاوي في مشكله","number":1865,"n":2073},{"key":"ahmad","label":"مسند الإمام أحمد","number":1369,"n":1369,"lafz":true},{"key":"ibnhibban","label":"ابن حبان","number":5570}],"full":1,"dr":1},{"num":6288,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَرْزَةَ الْأَسْلَمِيِّ، أَنَّ جُلَيْبِيبًا كَانَ امْرَأً يَدْخُلُ عَلَى النِّسَاءِ، يَمُرُّ بِهِنَّ وَيُلَاعِبُهُنَّ فَقُلْتُ لِامْرَأَتِي: لَا يَدْخُلَنَّ عَلَيْكُمْ جُلَيْبِيبٌ؛ فَإِنَّهُ إِنْ دَخَلَ عَلَيْكُمْ، لَأَفْعَلَنَّ وَلَأَفْعَلَنَّ. قَالَ: وَكَانَتِ الْأَنْصَارُ إِذَا كَانَ لِأَحَدِهِمْ أَيِّمٌ لَمْ يُزَوِّجْهَا حَتَّى يَعْلَمَ هَلْ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهَا حَاجَةٌ؟ أَمْ لَا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِرَجُلٍ مِنَ الْأَنْصَارِ: زَوِّجْنِي ابْنَتَكَ. فَقَالَ: نِعِمَّ وَكَرَامَةٌ يَا رَسُولَ اللَّهِ وَنُعْمَ عَيْنِي. قَالَ: إِنِّي لَسْتُ أُرِيدُهَا لِنَفْسِي. قَالَ: فَلِمَنْ يَا رَسُولَ اللَّهِ؟ قَالَ: لِجُلَيْبِيبٍ.: قَالَ: فَقَالَ: يَا رَسُولَ اللَّهِ، أُشَاوِرُ أُمَّهَا فَأَتَى أُمَّهَا فَقَالَ: رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ ابْنَتَكِ. فَقَالَتْ: نِعِمَّ. وَنُعْمَةُ عَيْنِي. فَقَالَ: إِنَّهُ لَيْسَ يَخْطُبُهَا لِنَفْسِهِ إِنَّمَا يَخْطُبُهَا لِجُلَيْبِيبٍ. فَقَالَتْ: أَجُلَيْبِيبٌ إنية؟ أَجُلَيْبِيبٌ إنية؟ أَجُلَيْبِيبٌ إنية؟ لَا. لَعَمْرُ اللهِ لَا نُزَوَّجُهُ. فَلَمَّا أَرَادَ أَنْ يَقُومَ لِيَأْتِيَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيُخْبِرَهُ بِمَا قَالَتْ أُمُّهَا: قَالَتِ الْجَارِيَةُ: مَنْ خَطَبَنِي إِلَيْكُمْ؟ فَأَخْبَرَتْهَا أُمُّهَا فَقَالَتْ: أَتَرُدُّونَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمْرَهُ؟ ادْفَعُونِي؛ فَإِنَّهُ لَمْ يُضَيِّعْنِي. فَانْطَلَقَ أَبُوهَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ فَقَالَ: شَأْنَكَ بِهَا فَزَوَّجَهَا جُلَيْبِيبًا."],"takhrij":"صحيح: رواه الإمام أحمد (19784) عن عفان، حدثنا حماد بن سلمة، عن ثابت، عن كنانة بن نُعيم العَدوي، عن أبي برزة الأسلمي فذكره. قال أحمد: ما حدّث به في الدنيا أحد إلا حماد بن سلمة ما أحسنه من حديث.","grade":"صحيح","chapter_ar":"باب للإمام أن يخطب إلى من أحب على من أحب من رعيته","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (19784).","chapter_en":"Chapter on the leader proposing on behalf of whomever he wishes among his subjects","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Abu Barzah al-Aslami reported that Julaybib was a man who used to enter among the women and joke with them, so I said to my wife: Do not let Julaybib enter upon you, for if he enters, I will certainly do such-and-such. He said: The Ansar, if one of them had an unmarried woman, would not marry her until they knew whether the Prophet ﷺ had any interest in her or not. So the Messenger of Allah ﷺ said to a man from the Ansar: “Marry your daughter to me.” He said: Yes, with honor, O Messenger of Allah, and gladly. He said: “I do not want her for myself.” He said: Then for whom, O Messenger of Allah? He said: “For Julaybib.” He said: So he said: O Messenger of Allah, let me consult her mother. He went to her mother and said: The Messenger of Allah ﷺ is proposing for your daughter. She said: Yes, gladly and with full welcome. He said: He is not proposing for himself; he is proposing for Julaybib. She said: Julaybib? Him? Julaybib? Him? Julaybib? Him? No, by Allah, we will not marry her to him. When the father was about to leave to go to the Messenger of Allah ﷺ and tell him what her mother had said, the girl said: Who has proposed for me through you? Her mother told her. She said: Are you rejecting the command of the Messenger of Allah ﷺ? Give me in marriage, for he will not neglect me. So her father went to the Messenger of Allah ﷺ and informed him, and he said: “The matter is yours with her.” So he married her to Julaybib."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":19784,"lafz":true}],"full":1,"dr":1},{"num":6289,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ جَلَسَ إِحْدَى عَشْرَةَ امْرَأَةً، فَتَعَاهَدْنَ وَتَعَاقَدْنَ أَنْ لاَ يَكْتُمْنَ مِنْ أَخْبَارِ أَزْوَاجِهِنَّ شَيْئًا. قَالَتِ الْأُولَى زَوْجِي لَحْمُ جَمَلٍ، غَثٌّ عَلَى رَأْسِ جَبَلٍ، لاَ سَهْلٍ فَيُرْتَقَى، وَلاَ سَمِينٍ فَيُنْتَقَلُ. قَالَتِ الثَّانِيَةُ زَوْجِي لاَ أَبُثُّ خَبَرَهُ، إِنِّي أَخَافُ أَنْ لاَ أَذَرَهُ، إِنْ أَذْكُرْهُ أَذْكُرْ عُجَرَهُ وَبُجَرَهُ. قَالَتِ الثَّالِثَةُ زَوْجِي الْعَشَنَّقُ، إِنْ أَنْطِقْ أُطَلَّقْ وَإِنْ أَسْكُتْ أُعَلَّقْ. قَالَتِ الرَّابِعَةُ زَوْجِي كَلَيْلِ تِهَامَةَ، لاَ حَرٌّ، وَلاَ قُرٌّ، وَلاَ مَخَافَةَ، وَلاَ سَآمَةَ. قَالَتِ الْخَامِسَةُ زَوْجِي إِنْ دَخَلَ فَهِدَ، وَإِنْ خَرَجَ أَسِدَ، وَلاَ يَسْأَلُ عَمَّا عَهِدَ. قَالَتِ السَّادِسَةُ زَوْجِي إِنْ أَكَلَ لَفَّ، وَإِنْ شَرِبَ اشْتَفَّ، وَإِنِ اضْطَجَعَ الْتَفَّ، وَلاَ يُولِجُ الْكَفَّ لِيَعْلَمَ الْبَثَّ، قَالَتِ السَّابِعَةُ زَوْجِي غَيَايَاءُ أَوْ عَيَايَاءُ طَبَاقَاءُ، كُلُّ دَاءٍ لَهُ دَاءٌ، شَجَّكِ أَوْ فَلَّكِ أَوْ جَمَعَ كُلاًّ لَكِ. قَالَتِ الثَّامِنَةُ زَوْجِي الْمَسُّ مَسُّ أَرْنَبٍ، وَالرِّيحُ رِيحُ زَرْنَبٍ. قَالَتِ التَّاسِعَةُ زَوْجِي رَفِيعُ الْعِمَادِ، طَوِيلُ النِّجَادِ، عَظِيمُ الرَّمَادِ، قَرِيبُ الْبَيْتِ مِنَ النَّادِ. قَالَتِ الْعَاشِرَةُ زَوْجِي مَالِكٌ وَمَا مَالِكٌ، مَالِكٌ خَيْرٌ مِنْ ذَلِكِ، لَهُ إِبِلٌ كَثِيرَاتُ الْمَبَارِكِ قَلِيلاَتُ الْمَسَارِحِ، وَإِذَا سَمِعْنَ صَوْتَ الْمِزْهَرِ أَيْقَنَّ أَنَّهُنَّ هَوَالِكُ. قَالَتِ الْحَادِيَةَ عَشْرَةَ زَوْجِي أَبُو زَرْعٍ فَمَا أَبُو زَرْعٍ أَنَاسَ مِنْ حُلِيٍّ أُذُنَىَّ، وَمَلأَ مِنْ شَحْمٍ عَضُدَىَّ، وَبَجَّحَنِي فَبَجِحَتْ إِلَىَّ نَفْسِي، وَجَدَنِي فِي أَهْلِ غُنَيْمَةٍ بِشِقٍّ، فَجَعَلَنِي فِي أَهْلِ صَهِيلٍ وَأَطِيطٍ وَدَائِسٍ وَمُنَقٍّ، فَعِنْدَهُ أَقُولُ فَلاَ أُقَبَّحُ وَأَرْقُدُ فَأَتَصَبَّحُ، وَأَشْرَبُ فَأَتَقَنَّحُ، أُمُّ أَبِي زَرْعٍ فَمَا أُمُّ أَبِي زَرْعٍ عُكُومُهَا رَدَاحٌ، وَبَيْتُهَا فَسَاحٌ، ابْنُ أَبِي زَرْعٍ، فَمَا ابْنُ أَبِي زَرْعٍ مَضْجِعُهُ كَمَسَلِّ شَطْبَةٍ، وَيُشْبِعُهُ ذِرَاعُ الْجَفْرَةِ، بِنْتُ أَبِي زَرْعٍ فَمَا بِنْتُ أَبِي زَرْعٍ طَوْعُ أَبِيهَا، وَطَوْعُ أُمِّهَا، وَمِلْءُ كِسَائِهَا، وَغَيْظُ جَارَتِهَا، جَارِيَةُ أَبِي زَرْعٍ، فَمَا جَارِيَةُ أَبِي زَرْعٍ لاَ تَبُثُّ حَدِيثَنَا تَبْثِيثًا، وَلاَ تُنَقِّثُ مِيرَتَنَا تَنْقِيثًا، وَلاَ تَمْلأُ بَيْتَنَا تَعْشِيشًا، قَالَتْ خَرَجَ أَبُو زَرْعٍ وَالأَوْطَابُ تُمْخَضُ، فَلَقِيَ امْرَأَةً مَعَهَا وَلَدَانِ لَهَا كَالْفَهْدَيْنِ يَلْعَبَانِ مِنْ تَحْتِ خَصْرِهَا بِرُمَّانَتَيْنِ، فَطَلَّقَنِي وَنَكَحَهَا، فَنَكَحْتُ بَعْدَهُ رَجُلاً سَرِيًّا، رَكِبَ شَرِيًّا وَأَخَذَ خَطِّيًّا وَأَرَاحَ عَلَىَّ نَعَمًا ثَرِيًّا، وَأَعْطَانِي مِنْ كُلِّ رَائِحَةٍ زَوْجًا وَقَالَ كُلِي أُمَّ زَرْعٍ، وَمِيرِي أَهْلَكِ. قَالَتْ فَلَوْ جَمَعْتُ كُلَّ شَىْءٍ أَعْطَانِيهِ مَا بَلَغَ أَصْغَرَ آنِيَةِ أَبِي زَرْعٍ. قَالَتْ عَائِشَةُ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُنْتُ لَكِ كَأَبِي زَرْعٍ لأُمِّ زَرْعٍ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5189) ومسلم في فضائل الصحابة (2448) كلاهما عن علي بن حُجر، أخبرنا عيسى بن يونس، حدّثنا هشام بن عروة، عن عبد الله بن عروة، عن عروة، عن عائشة، فذكرته موقوفا إلا الجملة الأخيرة وهي قول النبي صلى الله عليه وسلم: كُنْتُ لَكِ كَأَبِي زَرْعٍ لأُمِّ زَرْعٍ فهو مرفوع.","grade":"متفق عليه","chapter_ar":"باب حسن المعاشرة مع الأهل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5189) and Muslim (2448).","chapter_en":"Chapter on good companionship with one’s family","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["ʿĀʾishah reported: Eleven women sat together and pledged to one another that they would conceal nothing concerning their husbands. The first said: “My husband is like the meat of a lean camel on top of a mountain: the mountain is not easy to climb, nor is the meat fat enough to be worth carrying away.” The second said: “I will not disclose the story of my husband, for I fear that if I begin, I will not finish. If I mention him, I will have to mention all his outward and inward faults.” The third said: “My husband is tall and foolish. If I speak, I will be divorced; if I remain silent, I will be left suspended.” The fourth said: “My husband is like the night of Tihāmah: neither hot nor cold, and there is neither fear nor weariness with him.” The fifth said: “When my husband enters, he is like a leopard; when he goes out, he is like a lion, and he does not ask about what he has left behind.” The sixth said: “When my husband eats, he devours everything; when he drinks, he drains it all; when he lies down, he wraps himself up, and he does not extend his hand to discover what troubles me.” The seventh said: “My husband is foolish, helpless, and stupid. Every kind of defect is found in him. He may wound you, break you, or combine both against you.” The eighth said: “The touch of my husband is like the touch of a rabbit, and his fragrance is like the fragrance of sweet basil.” The ninth said: “My husband is lofty in his pillars, long in his sword-belt, great in his ashes, and his house is near the gathering place.” The tenth said: “My husband is Mālik. And what is Mālik? Mālik is better than all that. He has many camels that remain near the house and few that are sent out to pasture. Whenever they hear the sound of the lute, they know that they are about to be slaughtered for guests.” The eleventh said: “My husband is Abū Zarʿ. And what is Abū Zarʿ? He filled my ears with jewelry and filled my upper arms with flesh. He made me rejoice until I became pleased with myself. He found me among a poor family possessing only a few sheep in a narrow place, then brought me into a household of horses, camels, grain-threshing, and grain-cleaning. With him I speak and am not rebuked; I sleep until late in the morning; and I drink until I am completely satisfied. The mother of Abū Zarʿ—and what is the mother of Abū Zarʿ? Her storage bags are large and full, and her house is spacious. The son of Abū Zarʿ—and what is the son of Abū Zarʿ? His sleeping place is as slender as a drawn blade, and the foreleg of a young goat is enough to satisfy him. The daughter of Abū Zarʿ—and what is the daughter of Abū Zarʿ? She is obedient to her father and obedient to her mother, fills out her garment, and causes her co-wife to feel jealous. The servant-girl of Abū Zarʿ—and what is the servant-girl of Abū Zarʿ? She does not spread our secrets, does not waste our provisions, and does not fill our house with refuse. Abū Zarʿ went out while the milk-skins were being churned and met a woman who had two children like little leopards, playing beneath her waist with two pomegranates. He divorced me and married her. After him I married a noble man who rode a fine horse, carried an Indian spear, brought me abundant livestock, and gave me a pair of every kind. He said: ‘Eat, O Umm Zarʿ, and give provisions to your family.’ But even if I gathered together everything he gave me, it would not equal the smallest vessel of Abū Zarʿ.” ʿĀʾishah said that the Messenger of Allah ﷺ said to her: “I am to you as Abū Zarʿ was to Umm Zarʿ.”"]},"intro":{"ar":["قال تعالى: (وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ) [سورة النساء: ١٩]"],"en":["Allah Most High said: “And live with them in kindness.” [Surat al-Nisa’: 19]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5189,"lafz":true},{"key":"muslim","label":"مسلم","number":2448}],"full":1,"dr":1},{"num":6290,"demo":false,"sanad":"","matn":["عَنِ النُّعْمَانِ بْنِ بَشِيرٍ، قَالَ اسْتَأْذَنَ أَبُو بَكْرٍ رَحْمَةُ اللَّهِ عَلَيْهِ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَمِعَ صَوْتَ عَائِشَةَ عَالِيًا فَلَمَّا دَخَلَ تَنَاوَلَهَا لِيَلْطِمَهَا وَقَالَ لاَ أَرَاكِ تَرْفَعِينَ صَوْتَكِ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَعَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَحْجُزُهُ وَخَرَجَ أَبُو بَكْرٍ مُغْضَبًا فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ خَرَجَ أَبُو بَكْرٍ كَيْفَ رَأَيْتِنِي أَنْقَذْتُكِ مِنَ الرَّجُلِ. قَالَ فَمَكَثَ أَبُو بَكْرٍ أَيَّامًا ثُمَّ اسْتَأْذَنَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَوَجَدَهُمَا قَدِ اصْطَلَحَا فَقَالَ لَهُمَا أَدْخِلاَنِي فِي سِلْمِكُمَا كَمَا أَدْخَلْتُمَانِي فِي حَرْبِكُمَا. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ فَعَلْنَا قَدْ فَعَلْنَا."],"takhrij":"صحيح: رواه أبو داود (4999) وأحمد (18394) كلاهما من حديث أبي إسحاق، عن العيزار بن حريث، عن النعمان بن بشير، فذكره، واللفظ لأبي داود. ولم يذكر أحمد قوله: قد فعلنا، قد فعلنا.","grade":"صحيح","chapter_ar":"باب حسن المعاشرة مع الأهل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (4999) and Ahmad (18394). The wording is that of Abu Dawud. Ahmad did not mention the words, “We have done so, we have done so.”","chapter_en":"Chapter on good companionship with one’s family","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Al-Nu‘man ibn Bashir said: Abu Bakr asked permission to enter upon the Prophet ﷺ and heard the voice of ‘A’ishah raised. When he entered, he moved toward her to slap her and said: Do I see you raising your voice over the Messenger of Allah ﷺ? The Prophet ﷺ began restraining him, and Abu Bakr left angry. When Abu Bakr left, the Prophet ﷺ said: “How did you find that I rescued you from the man?” He said: Abu Bakr stayed away for some days, then asked permission to enter upon the Messenger of Allah ﷺ and found that the two had reconciled. So he said to them: Let me enter into your peace just as you made me enter into your conflict. The Prophet ﷺ said: “We have done so, we have done so.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4999,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":18394,"n":18394}],"full":1,"dr":1},{"num":6291,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ امْرَأَتِي لاَ تَمْنَعُ يَدَ لاَمِسٍ. فَقَالَ: غَرِّبْها إِنَّ شئت. قَالَ: إِنِّي أَخَافُ أَنْ تَتْبَعَهَا نَفْسِي، قَالَ: استمتع بِهَا."],"takhrij":"حسن: رواه أبو داود (2049) والنسائي (3464) والبيهقي (7/154) من طريق أبي داود – كلاهما عن حسين بن حُريث المروزي، ثنا الفضل بن موسى، عن الحسين بن واقد، عن عمارة بن أبي حفصة، عن عكرمة، عن ابن عباس فذكره. غير إن أبا داود قال: كتب إليّ حسينُ بن حريث المروزي – يعني أنه رواه عنه كتابة.","grade":"حسن","chapter_ar":"باب حسن المعاشرة مع الأهل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2049), al-Nasa’i (3464), and al-Bayhaqi (7/154).","chapter_en":"Chapter on good companionship with one’s family","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Ibn ‘Abbas said: A man came to the Prophet ﷺ and said: My wife does not refuse the hand of one who touches. He said: “Divorce her if you wish.” The man said: I fear that my soul will still follow after her. He said: “Then continue to live with her.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2049,"lafz":true},{"key":"nasai","label":"النسائي","number":3464,"n":3464},{"key":"kubrabayhaqi","label":"البيهقي","number":7}],"full":1,"dr":1},{"num":6292,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَجُلًا أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا رَسُولَ اللَّهِ إِنَّ لِيَ امْرَأَةً وَهِيَ لَا تَدْفَعُ يَدَ لَامِسٍ قَالَ: طَلِّقْهَا قَالَ: إِنِّي أُحِبُّهَا وَهِيَ جَمِيلَةٌ قَالَ: فَاسْتَمْتِعْ بِهَا."],"takhrij":"حسن: رواه البيهقي في السنن الكبرى (7/154-155) من طرق عن أبي الزبير، عن جابر بن عبد الله فذكره.","grade":"حسن","chapter_ar":"باب حسن المعاشرة مع الأهل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bayhaqi in al-Sunan al-Kubra (7/154–155).","chapter_en":"Chapter on good companionship with one’s family","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah reported that a man came to the Messenger of Allah ﷺ and said: O Messenger of Allah, I have a wife and she does not push away the hand of one who touches. He said: “Divorce her.” The man said: I love her and she is beautiful. He said: “Then continue to live with her.”"]},"buhuth":{"en":["His statement, “she does not prevent the hand of one who touches,” means that suspicion had entered the man’s heart regarding her, while at the same time he could not bear to part from her. So the Prophet ﷺ instructed him to remain with her and be patient, in hopes that her condition might improve.","The Prophet’s ﷺ statement, “continue to live with her,” is an indication of increasing intimacy with her in order to restrain her desire. And Allah Most High knows best."]}},"tuhfa":{},"refs":[{"key":"kubrabayhaqi","label":"البيهقي في السنن الكبرى","number":7,"lafz":true},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":13873,"n":14001}],"full":1,"dr":1},{"num":6293,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: حُبِّبَ إِلَيَّ النِّسَاءُ وَالطِّيبُ، وَجُعِلَ قُرَّةُ عَيْنِي فِي الصَّلَاةِ."],"takhrij":"حسن: رواه النسائي (3939) وأحمد (13057) والبيهقي (7/78) كلهم من حديث سلام أبي المنذر، عن ثابت، عن أنس فذكره واللفظ لأحمد.","grade":"حسن","chapter_ar":"باب حب النبي ﷺ للنساء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (3939), Ahmad (13057), and al-Bayhaqi (7/78).","chapter_en":"Chapter on the Prophet’s love for women","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ said: “Women and perfume have been made beloved to me, and the comfort of my eye has been placed in prayer.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3939,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":7},{"key":"ahmad","label":"مسند الإمام أحمد","number":13057,"n":13057}],"full":1,"dr":1},{"num":6294,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ كُنْتُ أَلْعَبُ بِالْبَنَاتِ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَكَانَ لِي صَوَاحِبُ يَلْعَبْنَ مَعِي، فَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا دَخَلَ يَتَقَمَّعْنَ مِنْهُ، فَيُسَرِّبُهُنَّ إِلَىَّ فَيَلْعَبْنَ مَعِي."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6130) ومسلم في فضائل الصحابة (2440) كلاهما من طريق هشام، عن أبيه، عن عائشة فذكرته، واللفظ للبخاري ولفظ مسلم نحوه.","grade":"متفق عليه","chapter_ar":"باب انبساط الرجل إلى زوجته","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6130) and Muslim (2440).","chapter_en":"Chapter on a man being open and easy with his wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["‘A’ishah said: I used to play with dolls in the presence of the Prophet ﷺ, and I had girl-friends who played with me. When the Messenger of Allah ﷺ entered, they would hide from him, and he would send them to me so they could play with me."]},"buhuth":{"en":["Her statement, “I used to play with dolls,” shows the permissibility of playing with dolls.","Her statement, “they would hide,” means they would withdraw out of modesty and awe toward him.","Her statement, “he would send them,” means he would send them over and let them come to me."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6130,"lafz":true},{"key":"muslim","label":"مسلم","number":2440}],"full":1,"dr":1,"rep":[14738,15630]},{"num":6295,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَإِذَا شَهِدَ أَمْرًا فَلْيَتَكَلَّمْ بِخَيْرٍ أَوْ لِيَسْكُتْ وَاسْتَوْصُوا بِالنِّسَاءِ فَإِنَّ الْمَرْأَةَ خُلِقَتْ مِنْ ضِلَعٍ وَإِنَّ أَعْوَجَ شَىْءٍ فِي الضِّلَعِ أَعْلاَهُ إِنْ ذَهَبْتَ تُقِيمُهُ كَسَرْتَهُ وَإِنْ تَرَكْتَهُ لَمْ يَزَلْ أَعْوَجَ اسْتَوْصُوا بِالنِّسَاءِ خَيْرًا."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5185-5186)، ومسلم في الرضاع (60:1468) كلاهما من طريق حسين بن علي الجُعفي، عن ميسرة، عن أبي حازم، عن أبي هريرة، فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب الوصية بالنساء خيرا ومداراتهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5185–5186) and Muslim (1468/60). This is Muslim’s wording.","chapter_en":"Chapter on enjoining good treatment of women and dealing gently with them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ said: “Whoever believes in Allah and the Last Day, when he is present at a matter, let him speak good or remain silent. Treat women well, for woman was created from a rib, and the most crooked part of the rib is its upper part. If you try to straighten it, you will break it; and if you leave it, it will remain crooked. So treat women well.”"]},"buhuth":{"en":["Muslim also narrated through another route:","“Woman is like a rib. If you try to straighten her, you will break her; and if you leave her, you may enjoy life with her while crookedness remains in her.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5185,"lafz":true},{"key":"muslim","label":"مسلم","number":1468},{"key":"muslim","label":"مسلم في الرضاع","number":60}],"full":1,"dr":1},{"num":6296,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ الْمَرْأَةَ خُلِقَتْ مِنْ ضِلَعٍ لَنْ تَسْتَقِيمَ لَكَ عَلَى طَرِيقَةٍ فَإِنِ اسْتَمْتَعْتَ بِهَا اسْتَمْتَعْتَ بِهَا وَبِهَا عِوَجٌ وَإِنْ ذَهَبْتَ تُقِيمُهَا كَسَرْتَهَا وَكَسْرُهَا طَلاَقُهَا."],"takhrij":"متفق عليه: رواه مسلم في الرضاع (1468/61) من طرق عن سفيان، عن أبي الزناد، عن الأعرج، عن أبي هريرة، فذكره، واللفظ له.","grade":"متفق عليه","chapter_ar":"باب الوصية بالنساء خيرا ومداراتهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (61:1468) and al-Bukhari (5184).","chapter_en":"Chapter on enjoining good treatment of women and dealing gently with them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Woman was created from a rib. She will never become completely straight for you upon one manner. If you enjoy life with her, you enjoy life with her while some crookedness remains in her. And if you try to straighten her, you will break her, and breaking her is divorcing her.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":61,"lafz":true},{"key":"bukhari","label":"البخاري","number":5184}],"full":1,"dr":1,"rep":[12120]},{"num":6297,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ يَفْرَكْ مُؤْمِنٌ مُؤْمِنَةً إِنْ كَرِهَ مِنْهَا خُلُقًا رَضِيَ مِنْهَا آخَرَ. أَوْ قَالَ غَيْرَهُ."],"takhrij":"صحيح: رواه مسلم في الرضاع (1469) عن إبراهيم بن موسى الرّازي، حدّثنا عيسى بن يونس، حدّثنا عبد الحميد بن جعفر، عن عمران بن أبي أنس، عن عمر بن الحكم، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب الوصية بالنساء خيرا ومداراتهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1469).","chapter_en":"Chapter on enjoining good treatment of women and dealing gently with them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “A believing man should not hate a believing woman. If he dislikes one trait in her, he will be pleased with another,” or he said, “with a different one.”"]},"buhuth":{"en":["His statement, “should not hate,” means should not loathe or detest. It is said in Arabic: he hated him, meaning he came to dislike him."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1469,"lafz":true,"n":3648}],"full":1,"dr":1},{"num":6298,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَلَوْلاَ بَنُو إِسْرَائِيلَ لَمْ يخبث الطّعام، وَلَمْ يَخْنَزِ اللَّحْمُ، وَلَوْلاَ حَوَّاءُ لَمْ تَخُنْ أُنْثَى زَوْجَهَا أبدَ الدَّهْرَ."],"takhrij":"متفق عليه: رواه البخاري في أحاديث الأنبياء (3330)، ومسلم في الرضاع (63:1470) كلاهما من طريق معمر، عن همام بن منبّه قال: هذا ما حدّثنا أبو هريرة عن رسول الله صلى الله عليه وسلم، فذكر أحاديث، منها هذا الحديث واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب الوصية بالنساء خيرا ومداراتهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3330) and Muslim (63:1470), with this wording from Muslim.","chapter_en":"Chapter on enjoining good treatment of women and dealing gently with them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Were it not for the Children of Israel, food would not spoil, and meat would not rot. And were it not for Hawwa’, no woman would ever betray her husband for all time.”"]},"buhuth":{"en":["His statement, “and meat would not rot,” means it would not become foul-smelling and change."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3330,"lafz":true},{"key":"muslim","label":"مسلم","number":63}],"full":1,"dr":1},{"num":6299,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جُنْدُبٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الْمَرْأَةَ خُلِقَتْ مِنْ ضِلَعٍ، فَإِنْ أَقَمْتَهَا كَسَرْتَهَا فَدَارِهَا تَعِشْ بِهَا."],"takhrij":"صحيح: رواه البزار – كشف الأستار (1476) والطبراني (6992) وابن حبان (4178) والحاكم (4/174) كلهم من طريق عوف بن أبي جميلة، عن أبي رجاء العطاردي، عن سمرة بن جندب فذكره.","grade":"صحيح","chapter_ar":"باب الوصية بالنساء خيرا ومداراتهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bazzar in Kashf al-Astar (1476), al-Tabarani (6992), Ibn Hibban (4178), and al-Hakim (4/174).","chapter_en":"Chapter on enjoining good treatment of women and dealing gently with them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Samurah ibn Jundub said: the Messenger of Allah ﷺ said: “Woman was created from a rib. If you try to straighten her, you will break her, so treat her gently and you will live with her.”"]}},"tuhfa":{},"refs":[{"key":"sh12862","label":"البزار - كشف الأستار","number":1476,"lafz":true},{"key":"mujamkabir","label":"الطبراني","number":6992},{"key":"hakim","label":"الحاكم","number":174},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1620,"n":1617},{"key":"ibnhibban","label":"ابن حبان","number":4178}],"full":1,"dr":1},{"num":6300,"demo":false,"sanad":"","matn":["عَنْ جابر بْنِ عَبْدِ اللَّهِ قَالَ فِي حَدِيثِ حَجَّةِ الْوَدَاعِ: حَتَّى إِذَا زَاغَتِ الشَّمْسُ أَمَرَ بِالْقَصْوَاءِ، فرُحلتْ لَهُ، فَأَتَى بَطْنَ الْوَادِي، فَخَطَبَ النَّاسَ وَقَالَ: إِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ حَرَامٌ عَلَيْكُمْ كَحُرْمَةِ يَوْمِكُمْ هَذَا فِي شَهْرِكُمْ هَذَا فِي بَلَدِكُمْ هَذَا، أَلاَ كُلُّ شيءٍ مِنْ أمرِ الْجَاهِلِيَّةِ تَحْتَ قدميَّ مَوْضُوعٌ، وَدِمَاءُ الْجَاهِلِيَّةِ مَوْضُوعَةٌ، وَإِنَّ أوَّلَ دمٍ أضعُ مِنْ دِمَائِنَا دمُ ابْنِ رَبِيعَةَ بْنِ الْحَارِثِ -كَانَ مُسْتَرْضِعًا فِي بَنِي سَعْدٍ، فَقَتَلَتْهُ هُذَيْلٌ- وَرِبَا الْجَاهِلِيَّةِ مَوْضُوعٌ، وَأَوَّلُ رِبًا أضعُ رِبَانَا رِبا عَبَّاسِ بْنِ عبدالمطلب فَإِنَّهُ مَوْضُوعٌ كُلُّهُ، فَاتَّقُوا اللَّهَ فِي النِّسَاءِ، فَإِنَّكُمْ أَخَذْتُمُوهُنَّ بِأَمَانِ اللَّهِ، وَاسْتَحْلَلْتُمْ فُرُوجَهُنَّ بِكَلِمَةِ اللَّهِ، وَلَكُمْ عَلَيْهِنَّ أَنْ لاَ يُوطِئْنَ فُرُشَكم أَحَدًا تَكْرَهُونَهُ، فإنْ فَعَلْنَ ذَلِكَ فَاضْرِبُوهُنَّ ضَرْبًا غَيْرَ مُبَرِّح، وَلَهُنَّ عَلَيْكُمْ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِالْمَعْرُوفِ... "],"takhrij":"صحيح: رواه مسلم في الحج (1218) من طريق حاتم بن إسماعيل، عن جعفر بن محمد، عن أبيه، عن جابر في الحديث الطويل في صفة حجة النبي صلى الله عليه وسلم.","grade":"صحيح","chapter_ar":"باب الوصية بالنساء خيرا ومداراتهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"Chapter on enjoining good treatment of women and dealing gently with them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported in the hadith of the Farewell Pilgrimage: When the sun had passed its zenith, the Prophet ﷺ ordered that al-Qaṣwāʾ be saddled for him. He came to the middle of the valley and addressed the people, saying: “Your blood and your wealth are sacred to one another, just as this day of yours is sacred, in this month of yours, in this land of yours. Everything from the affairs of the pre-Islamic period is placed beneath my feet and abolished. The blood claims of the pre-Islamic period are abolished, and the first blood claim of ours that I abolish is that of the son of Rabīʿah ibn al-Ḥārith—he had been sent to be nursed among Banū Saʿd and was killed by Hudhayl. The usury of the pre-Islamic period is abolished, and the first usury of ours that I abolish is that of al-ʿAbbās ibn ʿAbd al-Muṭṭalib. All of it is abolished. Fear Allah regarding women, for you have taken them under the trust of Allah and made marital relations with them lawful by the word of Allah. Your right over them is that they do not allow onto your bedding anyone whom you dislike. If they do so, then strike them in a manner that is not severe. Their right over you is that you provide them with food and clothing according to what is reasonable…”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218,"lafz":true,"n":2951}],"full":1},{"num":6301,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ كُنْتُ أَشْرَبُ وَأَنَا حَائِضٌ، ثُمَّ أُنَاوِلُهُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَيَضَعُ فَاهُ عَلَى مَوْضِعِ فِيَّ فَيَشْرَبُ وَأَتَعَرَّقُ الْعَرْقَ وَأَنَا حَائِضٌ ثُمَّ أُنَاوِلُهُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَيَضَعُ فَاهُ عَلَى مَوْضِعِ فِيَّ."],"takhrij":"صحيح: رواه مسلم في الحيض (300) من طرق عن وكيع، عن مسعر وسفيان، عن المقدام بن شريح، عن أبيه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب الوصية بالنساء خيرا ومداراتهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (300).","chapter_en":"Chapter on enjoining good treatment of women and dealing gently with them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["‘A’ishah said: I would drink while menstruating, then hand it to the Prophet ﷺ, and he would place his mouth where mine had been and drink. And I would gnaw meat from a bone while menstruating, then hand it to the Prophet ﷺ, and he would place his mouth where mine had been."]},"buhuth":{"en":["The word ‘irq with a silent ra’ means a bone from which most of the meat has been taken, and its plural is ‘iraq. It was also said that it means a bone that still has some meat on it. In this is the Prophet’s ﷺ gentle companionship in eating and drinking with his family."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":300,"lafz":true}],"full":1,"dr":1,"rep":[1515]},{"num":6302,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: سَابَقَنِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَبَقْتُهُ، فَلَبِثْنَا حَتَّى إِذَا أَرْهَقَنِي اللَّحْمُ سَابَقَنِي فَسَبَقَنِي. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَذِهِ بِتِلْكَ."],"takhrij":"صحيح: رواه أبو داود (2578) وابن ماجة (1979) وصحّحه ابن حبان (4691) كلهم من حديث هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب الوصية بالنساء خيرا ومداراتهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2578), Ibn Majah (1979), and authenticated by Ibn Hibban (4691).","chapter_en":"Chapter on enjoining good treatment of women and dealing gently with them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["‘A’ishah said: The Prophet ﷺ raced me, and I beat him. Then time passed until I had put on weight, and he raced me and beat me. So the Prophet ﷺ said: “This is for that.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2578,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":1979},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":4691},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":5495,"n":5491}],"full":1,"dr":1},{"num":6303,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: خَرَجْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَعْضِ أَسْفَارِهِ وَأَنَا جَارِيَةٌ لَمْ أَحْمِلِ اللَّحْمَ وَلَمْ أَبْدُنْ، فَقَالَ لِلنَّاسِ: تَقَدَّمُوا فَتَقَدَّمُوا، ثُمَّ قَالَ لِي: تَعَالَيْ حَتَّى أُسَابِقَكِ فَسَابَقْتُهُ فَسَبَقْتُهُ، فَسَكَتَ عَنِّي، حَتَّى إِذَا حَمَلْتُ اللَّحْمَ وَبَدُنْتُ وَنَسِيتُ، خَرَجْتُ مَعَهُ فِي بَعْضِ أَسْفَارِهِ، فَقَالَ لِلنَّاسِ: تَقَدَّمُوا فَتَقَدَّمُوا، ثُمَّ قَالَ: تَعَالَيْ حَتَّى أُسَابِقَكِ فَسَابَقْتُهُ، فَسَبَقَنِي، فَجَعَلَ يَضْحَكُ، وَهُوَ يَقُولُ: هَذِهِ بِتِلْكَ."],"takhrij":"حسن: رواه أحمد (26277) عن عمر أبي حفص المعيطي، قال: حدثنا هشام، عن أبيه، عن عائشة، فذكرته.","grade":"حسن","chapter_ar":"باب الوصية بالنساء خيرا ومداراتهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (26277).","chapter_en":"Chapter on enjoining good treatment of women and dealing gently with them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["‘A’ishah said: I went out with the Prophet ﷺ on one of his journeys while I was still a young girl, not carrying flesh and not heavy in body. He said to the people: “Go ahead,” so they went ahead. Then he said to me: “Come, so I may race you.” So I raced him and beat him. He said nothing to me about it until later, when I had put on flesh, gained weight, and forgotten about it. Then I went out with him on another journey, and he said to the people: “Go ahead,” so they went ahead. Then he said: “Come, so I may race you.” So I raced him and he beat me, and he began laughing, saying: “This is for that.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":26277,"n":26277,"lafz":true}],"full":1,"dr":1},{"num":6304,"demo":false,"sanad":"","matn":["عن عَائِشَةَ قَالَتْ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِخَزِيرَةٍ قَدْ طَبَخْتُهَا لَهُ، فَقُلْتُ لِسَوْدَةَ - وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنِي وَبَيْنَهَا ـ: كُلِي، فَأَبَتْ، فَقُلْتُ: لَتَأْكُلِنَّ أَوْ لَأُلَطِّخَنَّ وَجْهَكِ، فَأَبَتْ، فَوَضَعْتُ يَدِي فِي الْخَزِيرَةِ، فَطَلَيْتُ وَجْهَهَا، فَضَحِكَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَوَضَعَ بِيَدِهِ لَهَا، وَقَالَ لَهَا: الْطَخِي وَجْهَهَا، فَضَحِكَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَهَا، فَمَرَّ عُمَرُ، فَقَالَ: يَا عَبْدَ اللَّهِ، يَا عَبْدَ اللَّهِ، فَظَنَّ أَنَّهُ سَيَدْخُلُ، فَقَالَ: قُومَا فَاغْسِلَا وُجُوهَكُمَا.","قالت عائشة: فما زلتُ أهاب عمر لهيبة رسول الله صلى الله عليه وسلم."],"takhrij":"حسن: رواه أبو يعلى (4476) وأبو بكر الشافعي في الغيلانيات (117) كلاهما من حديث حماد، عن محمد بن عمرو، عن يحيى بن عبد الرحمن بن حاطب ( ابن أبي بلتعة) أن عائشة قالت: فذكره.","grade":"حسن","chapter_ar":"باب الوصية بالنساء خيرا ومداراتهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Ya‘la (4476) and Abu Bakr al-Shafi‘i in al-Ghaylaniyyat (117).","chapter_en":"Chapter on enjoining good treatment of women and dealing gently with them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["‘A’ishah said: I brought the Messenger of Allah ﷺ some khazirah that I had cooked for him, and I said to Sawdah—while the Prophet ﷺ was between me and her—“Eat.” She refused. I said: “Either you eat, or I will smear your face.” She still refused, so I put my hand in the khazirah and smeared her face. The Prophet ﷺ laughed, then he put his hand for her and said to her: “Smear her face.” So the Prophet ﷺ laughed with her. Then ‘Umar passed by and said: “O servant of Allah, O servant of Allah!” and he thought that he would come in. So he said: “Get up and wash your faces.” ‘A’ishah said: I continued to stand in awe of ‘Umar because of the Messenger of Allah’s ﷺ awe of him."]},"buhuth":{"en":["Khazirah is a food cooked from meat and flour, somewhat like a thick porridge."]}},"tuhfa":{},"refs":[{"key":"sh12520","label":"أبو يعلى","number":4476,"lafz":true},{"key":"rb449","label":"أبو بكر الشافعي في الغيلانيات","number":117}],"full":1,"dr":1},{"num":6305,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ أَعْظَمَ الذُّنُوبِ عِنْدَ اللَّهِ رَجُلٌ تَزَوَّجَ امْرَأَةً، فَلَمَّا قَضَى حَاجَتَهُ مِنْهَا، طَلَّقَهَا، وَذَهَبَ بِمَهْرِهَا، وَرَجُلٌ اسْتَعْمَلَ رَجُلًا، فَذَهَبَ بِأُجْرَتِهِ، وَآخَرُ يَقْتُلُ دَابَّةً عَبَثًا."],"takhrij":"حسن: رواه الحاكم (2/182) عن أبي عمرو بن إسماعيل، ثنا أبو بكر محمد بن إسحاق الإمام، ثنا عبد الوارث بن عبد الصمد بن عبد الوارث العنبري، حدثني أبي، عن عبد الرحمن بن عبد الله بن دينار، عن محمد بن سيرين، عن ابن عمر، فذكره.","grade":"حسن","chapter_ar":"باب الوصية بالنساء خيرا ومداراتهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ḥākim (2743).","chapter_en":"Chapter on enjoining good treatment of women and dealing gently with them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Ibn ʿUmar reported that the Messenger of Allah ﷺ said: “Among the gravest sins in the sight of Allah is that a man marries a woman, then, after satisfying his desire with her, divorces her and takes away her dowry; that a man employs another man and then deprives him of his wages; and that a person kills an animal for no purpose.”"]}},"tuhfa":{},"refs":[{"key":"hakim","label":"المستدرك على الصحيحين","number":2743,"n":2729,"lafz":true}],"full":1,"dr":1},{"num":6306,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، عَنْ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: فِي بُضع أَحَدِكُمْ صَدَقَةٌ قَالُوا: يَا رَسُولَ اللَّهِ! أَيَأْتِي أَحَدُنَا شَهْوَتَهُ، وَيَكُونُ لَهُ فِيهِ أَجْرٌ. فَقَالَ: أَرَأَيْتُمْ لَوْ وَضَعَهَا فِي الحرام أَكَانَ عَلَيْهِ وزْر. فَكَذَلِكَ إِذَا وَضَعَهَا فِي الْحَلاَلِ، كَانَ لَهُ أَجْرٌ."],"takhrij":"صحيح: رواه مسلم في الزكاة (1006) عن عبد الله بن محمد بن أسماء الضُبعي، حدثنا مهدي بن ميمون، حدثنا واصل مولى أبي عُيينة، عن يحيى بن عُقيل، عن يحيى بن يعمر، عن أبي الأسود الديلي، عن أبي ذر فذكره.","grade":"صحيح","chapter_ar":"باب إن الله عزوجل جعل مواقعة أهله صدقة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in The Book of Zakāh (1006).","chapter_en":"Chapter that Allah, Mighty and Majestic, has made intimacy with one’s wife an act of charity","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Abū Dharr reported that the Prophet ﷺ said: “And in the sexual intimacy of each one of you there is an act of charity.” They said, “O Messenger of Allah! Does one of us fulfill his desire and receive a reward for it?” He ﷺ said: “Tell me, if he were to satisfy it in what is unlawful, would he bear a sin for that? Likewise, when he satisfies it in what is lawful, he receives a reward.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم في الزكاة","number":1006,"lafz":true}],"full":1,"dr":1},{"num":6307,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن عمرو بْنِ الْعَاصِ قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَا عَبْدَ اللَّهِ أَلَمْ أُخْبَرْ أَنَّكَ تَصُومُ النَّهَارَ وَتَقُومُ اللَّيْلَ. قُلْتُ بَلَى يَا رَسُولَ اللَّهِ. قَالَ فَلاَ تَفْعَلْ، صُمْ وَأَفْطِرْ، وَقُمْ وَنَمْ، فَإِنَّ لِجَسَدِكَ عَلَيْكَ حَقًّا، وَإِنَّ لِعَيْنِكَ عَلَيْكَ حَقًّا، وَإِنَّ لِزَوْجِكَ عَلَيْكَ حَقًّا."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5199)، من طريق الأوزاعي، حدثني يحيى بن أبي كثير، حدثني أبو سلمة بن عبدالرحمن قال: حدثني عبدالله بن عمرو بن العاص فذكره.","grade":"متفق عليه","chapter_ar":"باب حق الزوجة على الزوج","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5199) and Muslim (1159).","chapter_en":"Chapter on the wife’s right over the husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["‘Abd Allah ibn ‘Amr ibn al-‘As said: The Messenger of Allah ﷺ said: “O ‘Abd Allah, have I not been told that you fast by day and stand in prayer by night?” I said: Yes, O Messenger of Allah. He said: “Do not do that. Fast and break your fast. Stand in prayer and sleep. For your body has a right over you, your eyes have a right over you, and your wife has a right over you.”"]},"intro":{"ar":["قال تعالى: (وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ) [البقرة: ٢٢٨]"],"en":["Allah Most High said: “And for them is the like of what is upon them, according to what is fair.” [al-Baqarah: 228]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5199,"lafz":true},{"key":"muslim","label":"مسلم","number":1159}],"full":1,"dr":1},{"num":6308,"demo":false,"sanad":"","matn":["عن أَبِي جُحَيْفَةَ عَنْ أَبِيهِ، قَالَ آخَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ سَلْمَانَ، وَأَبِي الدَّرْدَاءِ، فَزَارَ سَلْمَانُ أَبَا الدَّرْدَاءِ، فَرَأَى أُمَّ الدَّرْدَاءِ مُتَبَذِّلَةً. فَقَالَ لَهَا مَا شَأْنُكِ قَالَتْ أَخُوكَ أَبُو الدَّرْدَاءِ لَيْسَ لَهُ حَاجَةٌ فِي الدُّنْيَا. فَجَاءَ أَبُو الدَّرْدَاءِ، فَصَنَعَ لَهُ طَعَامًا. فَقَالَ كُلْ. قَالَ فَإِنِّي صَائِمٌ. قَالَ مَا أَنَا بِآكِلٍ حَتَّى تَأْكُلَ. قَالَ فَأَكَلَ. فَلَمَّا كَانَ اللَّيْلُ ذَهَبَ أَبُو الدَّرْدَاءِ يَقُومُ. قَالَ نَمْ. فَنَامَ، ثُمَّ ذَهَبَ يَقُومُ. فَقَالَ نَمْ. فَلَمَّا كَانَ مِنْ آخِرِ اللَّيْلِ قَالَ سَلْمَانُ قُمِ الآنَ. فَصَلَّيَا، فَقَالَ لَهُ سَلْمَانُ إِنَّ لِرَبِّكَ عَلَيْكَ حَقًّا، وَلِنَفْسِكَ عَلَيْكَ حَقًّا، وَلأَهْلِكَ عَلَيْكَ حَقًّا، فَأَعْطِ كُلَّ ذِي حَقٍّ حَقَّهُ. فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ ذَلِكَ لَهُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَدَقَ سَلْمَانُ."],"takhrij":"صحيح: رواه البخاري في الصوم (1968)، عن محمد بن بشّار، حدّثنا جعفر بن عون، حدّثنا أبو العُميس، عن عَون بن أبي جحيفة، عن أبيه، فذكره.","grade":"صحيح","chapter_ar":"باب حق الزوجة على الزوج","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1968).","chapter_en":"Chapter on the wife’s right over the husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["Abu Juhayfah said: The Prophet ﷺ made Salman and Abu al-Darda’ brothers. Salman visited Abu al-Darda’ and saw Umm al-Darda’ in worn clothing, so he said to her: What is the matter with you? She said: Your brother Abu al-Darda’ has no interest in worldly things. Then Abu al-Darda’ came and prepared food for him. Abu al-Darda’ said: Eat, for I am fasting. Salman said: I will not eat until you eat. So Abu al-Darda’ ate. When night came, Abu al-Darda’ got up to pray, but Salman said: Sleep. So he slept. Then he got up again, and Salman said: Sleep. Then at the end of the night Salman said: Now get up. So they prayed. Then Salman said to him: Your Lord has a right over you, your self has a right over you, and your family has a right over you, so give each possessor of a right his right. Then Abu al-Darda’ came to the Prophet ﷺ and mentioned that to him, and the Prophet ﷺ said: “Salman has spoken the truth.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1968,"lafz":true}],"full":1,"rep":[15271]},{"num":6309,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ زَمْعَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ يَجْلِدُ أَحَدُكُمُ امْرَأَتَهُ جَلْدَ الْعَبْدِ، ثُمَّ يُجَامِعُهَا فِي آخِرِ الْيَوْمِ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5204)، ومسلم في الجنة وصفة نعيمها وأهلها (2855) من طريق هشام بن عروة، عن أبيه، عن عبد الله بن زمعة، فذكره، واللفظ للبخاري، هو عند مسلم بسياق أطول.","grade":"متفق عليه","chapter_ar":"باب حق الزوجة على الزوج","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5204) and Muslim (2855), with the wording from al-Bukhari.","chapter_en":"Chapter on the wife’s right over the husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["‘Abd Allah ibn Zam‘ah reported that the Prophet ﷺ said: “Let none of you flog his wife like the flogging of a slave and then have relations with her at the end of the day.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5204,"lafz":true},{"key":"muslim","label":"مسلم","number":2855}],"full":1},{"num":6310,"demo":false,"sanad":"","matn":["عَنْ حَكِيمِ بْنِ مُعَاوِيَةَ الْقُشَيْرِيِّ، عَنْ أَبِيهِ، قَالَ قُلْتُ يَا رَسُولَ اللَّهِ مَا حَقُّ زَوْجَةِ أَحَدِنَا عَلَيْهِ قَالَ أَنْ تُطْعِمَهَا إِذَا طَعِمْتَ وَتَكْسُوَهَا إِذَا اكْتَسَيْتَ - أَوِ اكْتَسَبْتَ - وَلاَ تَضْرِبِ الْوَجْهَ وَلاَ تُقَبِّحْ وَلاَ تَهْجُرْ إِلاَّ فِي الْبَيْتِ."],"takhrij":"حسن: رواه أبو داود (2142) وابن ماجة (1850) وصحّحه ابن حبان (4175) والحاكم (2/187-188) كلهم من طريق أبي قزعة عن حكيم بن معاوية، فذكره.","grade":"حسن","chapter_ar":"باب حق الزوجة على الزوج","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2142), Ibn Majah (1850), authenticated by Ibn Hibban (4175), and al-Hakim (2764).","chapter_en":"Chapter on the wife’s right over the husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["Hakim ibn Mu‘awiyah al-Qushayri reported from his father that he said: O Messenger of Allah, what is the right of one of our wives over him? He said: “That you feed her when you eat, clothe her when you clothe yourself, do not strike the face, do not revile her, and do not forsake her except within the house.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2142,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":1850},{"key":"ibnhibban","label":"صححه ابن حبان","number":4175},{"key":"hakim","label":"المستدرك على الصحيحين","number":2764,"n":2750}],"full":1,"dr":1},{"num":6311,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ جَاءَتْ هِنْدٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ يَا رَسُولَ اللَّهِ وَاللَّهِ مَا كَانَ عَلَى ظَهْرِ الأَرْضِ أَهْلُ خِبَاءٍ أَحَبَّ إِلَىَّ مِنْ أَنْ يُذِلَّهُمُ اللَّهُ مِنْ أَهْلِ خِبَائِكَ وَمَا عَلَى ظَهْرِ الأَرْضِ أَهْلُ خِبَاءٍ أَحَبَّ إِلَىَّ مِنْ أَنْ يُعِزَّهُمُ اللَّهُ مِنْ أَهْلِ خِبَائِكَ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَيْضًا وَالَّذِي نَفْسِي بِيَدِهِ. ثُمَّ قَالَتْ يَا رَسُولَ اللَّهِ إِنَّ أَبَا سُفْيَانَ رَجُلٌ مُمْسِكٌ فَهَلْ عَلَىَّ حَرَجٌ أَنْ أُنْفِقَ عَلَى عِيَالِهِ مِنْ مَالِهِ بِغَيْرِ إِذْنِهِ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ حَرَجَ عَلَيْكِ أَنْ تُنْفِقِي عَلَيْهِمْ بِالْمَعْرُوفِ."],"takhrij":"متفق عليه: رواه البخاري في مناقب الأنصـار (3825)، ومسلم في الأقضيــة (1714: 8) كلاهما من حديث الزهري، عن عروة، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب حق الزوجة على الزوج","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3825) and Muslim (8:1714), with this wording from Muslim. Al-Bukhari’s wording is close to it.","chapter_en":"Chapter on the wife’s right over the husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["‘A’ishah said: Hind bint ‘Utbah came to the Prophet ﷺ and said: O Messenger of Allah, by Allah, there was no household on the face of the earth more beloved to me that Allah should disgrace than your household, and now there is no household on the face of the earth more beloved to me that Allah should honor than your household. The Prophet ﷺ said: “And also, by the One in whose hand is my soul.” Then she said: O Messenger of Allah, Abu Sufyan is a stingy man. Is there any sin upon me if I spend on his dependents from his wealth without his permission? The Prophet ﷺ said: “There is no sin upon you to spend on them in a fair manner.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3825,"lafz":true},{"key":"muslim","label":"مسلم","number":8},{"key":"muslim","label":"مسلم في الاقضيه","number":1714,"n":4479}],"full":1,"dr":1},{"num":6312,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَكْمَلُ الْمُؤْمِنِينَ إِيمَانًا أَحْسَنُهُمْ خُلُقًا وَخِيَارُكُمْ خِيَارُكُمْ لِنِسَائِهِمْ."],"takhrij":"حسن: رواه الترمذي (1162)، وأبو داود (4682) وصحّحه ابن حبان (4176) والحاكم (1/3) كلهم من طريق محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكر الحديث واللفظ للترمذي وابن حبان.","grade":"حسن","chapter_ar":"باب ما جاء في قوله: خياركم خياركم لأهله","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1162), Abu Dawud (4682), authenticated by Ibn Hibban (4176), and al-Hakim (1).","chapter_en":"Chapter on the saying: the best of you are the best to their families","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “The most complete of the believers in faith are those best in character, and the best of you are the best of you to their women.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1162,"lafz":true},{"key":"abudawud","label":"أبو داود","number":4682},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":4176},{"key":"hakim","label":"المستدرك على الصحيحين","number":1,"n":1}],"full":1,"dr":1},{"num":6313,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْرُكُمْ خَيْرُكُمْ لأَهْلِهِ وَأَنَا خَيْرُكُمْ لأَهْلِي وَإِذَا مَاتَ صَاحِبُكُمْ فَدَعُوهُ."],"takhrij":"صحيح: رواه الترمذي (3895) وصحّحه ابن حبان (4177) وأبو نعيم في الحلية (7/138) كلهم من حديث محمد بن يوسف، عن الثوري، عن هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في قوله: خياركم خياركم لأهله","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (3895), authenticated by Ibn Ḥibbān (4177), and narrated by Abū Nuʿaym in al-Ḥilyah (7/138).","chapter_en":"Chapter on the saying: the best of you are the best to their families","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":7,"content":{"translation":{"en":["ʿĀʾishah reported that the Messenger of Allah ﷺ said: “The best of you are those who are best to their families, and I am the best of you to my family. When your companion dies, leave him alone.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":3895,"lafz":true},{"key":"ibnhibban","label":"صححه ابن حبان","number":4177},{"key":"sh10495","label":"أبو نعيم في الحلية","number":7},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":635,"n":635}],"full":1,"dr":1},{"num":6314,"demo":false,"sanad":"","matn":["عن أُمِّ سَلَمَةَ أَخْبَرَتْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَلَفَ لاَ يَدْخُلُ عَلَى بَعْضِ أَهْلِهِ شَهْرًا، فَلَمَّا مَضَى تِسْعَةٌ وَعِشْرُونَ يَوْمًا غَدَا عَلَيْهِنَّ أَوْ رَاحَ فَقِيلَ لَهُ يَا نَبِيَّ اللَّهِ حَلَفْتَ أَنْ لاَ تَدْخُلَ عَلَيْهِنَّ شَهْرًا قَالَ إِنَّ الشَّهْرَ يَكُونُ تِسْعَةً وَعِشْرِينَ يَوْمًا."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5202)، ومسلم في الصيام (25:1085) من طريق ابن جريج قال: أخبرني يحيى بن عبد الله بن صيفيّ، أن عكرمة بن عبد الرحمن بن الحارث أخبره، أن أم سلمة أخبرته، فذكرته.","grade":"متفق عليه","chapter_ar":"باب حق الزوج على الزوجة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5202) and Muslim (25:1085).","chapter_en":"The husband’s right over his wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Umm Salamah reported that the Prophet ﷺ swore that he would not enter upon some of his wives for one month. Then when twenty-nine days had passed, he came to them in the morning or evening. It was said to him: O Prophet of Allah, you swore that you would not enter upon them for a month. He said: “The month may be twenty-nine days.”"]},"intro":{"ar":["قال الله تعالى: ﴿وَاللَّاتِي تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَاهْجُرُوهُنَّ فِي الْمَضَاجِعِ وَاضْرِبُوهُنَّ فَإِنْ أَطَعْنَكُمْ فَلَا تَبْغُوا عَلَيْهِنَّ سَبِيلًا إِنَّ اللَّهَ كَانَ عَلِيًّا كَبِيرًا﴾ [النساء: ٣٤]"],"en":["Allah Most High said: “As for those women whose disobedience you fear, admonish them, leave them in the beds, and strike them. But if they obey you, then seek no way against them. Indeed, Allah is Most High, Most Great.” [Surat al-Nisa’: 34]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5202,"lafz":true},{"key":"muslim","label":"مسلم","number":25}],"full":1,"rep":[4326,6645]},{"num":6315,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِذَا دَعَا الرَّجُلُ امْرَأَتَهُ إِلَى فِرَاشِهِ فَأَبَتْ أَنْ تَجِيءَ لَعَنَتْهَا الْمَلاَئِكَةُ حَتَّى تُصْبِحَ.","وفي رواية: إذا باتت المرأة مهاجرةً فراش زوجها، لعنتها الملائكة حتى ترجع."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5193)، ومسلم في النكاح (12:1436) كلاهما عن سليمان الأعمش، عن أبي حازم، عن أبي هريرة، فذكره، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب حق الزوج على الزوجة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5193) and Muslim (12:1436), with the wording from al-Bukhari.","chapter_en":"The husband’s right over his wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “If a man calls his wife to his bed and she refuses to come, the angels curse her until morning.” In another narration: “If a woman spends the night forsaking her husband’s bed, the angels curse her until she returns.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5193,"lafz":true},{"key":"muslim","label":"مسلم","number":12}],"full":1,"dr":1},{"num":6316,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ يَحِلُّ لِلْمَرْأَةِ أَنْ تَصُومَ وَزَوْجُهَا شَاهِدٌ إِلاَّ بِإِذْنِهِ، وَلاَ تَأْذَنَ فِي بَيْتِهِ إِلاَّ بِإِذْنِهِ، وَمَا أَنْفَقَتْ مِنْ نَفَقَةٍ عَنْ غَيْرِ أَمْرِهِ فَإِنَّهُ يُؤَدَّى إِلَيْهِ شَطْرُهُ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5195)، من طريق أبي الزناد، عن الأعرج، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب حق الزوج على الزوجة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5195) and Muslim (1026).","chapter_en":"The husband’s right over his wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “It is not lawful for a woman to fast while her husband is present except with his permission, and she must not allow anyone into his house except with his permission. Whatever she spends without his instruction, half of its reward goes to him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5195,"lafz":true},{"key":"muslim","label":"مسلم","number":1026}],"full":1,"dr":1},{"num":6317,"demo":false,"sanad":"","matn":["عن طلق بن عَلِيٍّ قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا الرَّجُلُ دَعَا زَوْجَتَهُ لِحَاجَتِهِ فَلْتَأْتِهِ وَإِنْ كَانَتْ عَلَى التَّنُّورِ."],"takhrij":"حسن: رواه الترمذي (1160) وابن حبان في صحيحه (4165) والبيهقي (7/294) كلهم من طريق ملازم بن عمرو، حدثنا عبد الله بن بدر، عن قيس بن طلق، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب حق الزوج على الزوجة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1160), who graded it Hasan, Ibn Hibban in his Sahih (4165), and al-Bayhaqi (7/294).","chapter_en":"The husband’s right over his wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Talq ibn ‘Ali said that the Messenger of Allah ﷺ said: “If a man calls his wife for his need, she should come to him, even if she is at the oven.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1160,"lafz":true},{"key":"ibnhibban","label":"ابن حبان في صحيحه","number":4165},{"key":"kubrabayhaqi","label":"البيهقي","number":294}],"full":1,"dr":1},{"num":6318,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ أَرْقَمَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: إِذَا دَعَا الرَّجُلُ امْرَأَتَهُ فَلْتُجِبْ وَإِنْ كَانَتْ عَلَى ظَهْرِ قَتْبٍ."],"takhrij":"حسن: رواه البزار- كشف الأستار (1472) والطبراني في المعجم الأوسط (7429) كلاهما من حديث محمد بن سواء، ثنا سعيد، عن قتادة، عن القاسم الشيباني، عن زيد بن أرقم، فذكره، ولفظهما سواء.","grade":"حسن","chapter_ar":"باب حق الزوج على الزوجة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzar in Kashf al-Astar (1472) and al-Tabarani in al-Mu‘jam al-Awsat (7429).","chapter_en":"The husband’s right over his wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Zayd ibn Arqam reported that the Messenger of Allah ﷺ said: “If a man calls his wife, she should respond, even if she is on the back of a saddle.”"]}},"tuhfa":{},"refs":[{"key":"sh12862","label":"البزار - كشف الأستار","number":1472,"lafz":true},{"key":"sh28171","label":"الطبراني في المعجم الأوسط","number":7429}],"full":1,"dr":1},{"num":6319,"demo":false,"sanad":"","matn":["عَنِ الْحُصَيْنِ بْنِ مِحْصَنٍ، أَنَّ عَمَّةً لَهُ أَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَاجَةٍ، فَفَرَغَتْ مِنْ حَاجَتِهَا، فَقَالَ لَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَذَاتُ زَوْجٍ أَنْتِ؟ قَالَتْ: نَعَمْ، قَالَ: كَيْفَ أَنْتِ لَهُ؟ قَالَتْ: مَا آلُوهُ إِلَّا مَا عَجَزْتُ عَنْهُ، قَالَ: فَانْظُرِي أَيْنَ أَنْتِ مِنْهُ، فَإِنَّمَا هُوَ جَنَّتُكِ وَنَارُكِ."],"takhrij":"صحيح: رواه الإمام أحمد (19003) والطبراني في الكبير (25/183) والأوسط (532) والحاكم (2/189) وعنه البيهقي (7/291) والنسائي في الكبرى (8963) كلهم من حديث يحيى بن سعيد الأنصاري، عن بُشير بن يسار، عن الحصين بن محصن فذكره. وقال الحاكم: صحيح.","grade":"صحيح","chapter_ar":"باب حق الزوج على الزوجة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (19003), al-Tabarani in al-Kabir (25/183), al-Awsat (532), and al-Hakim (3/189).","chapter_en":"The husband’s right over his wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Al-Husayn ibn Mihsan reported that an aunt of his came to the Prophet ﷺ regarding a need. When she had finished her need, the Prophet ﷺ said to her: “Do you have a husband?” She said: Yes. He said: “How are you with him?” She said: I do not fail him except in what I am unable to do. He said: “Then look at where you stand with respect to him, for he is your Paradise and your Fire.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":19003,"lafz":true},{"key":"mujamkabir","label":"الطبراني في الكبير","number":183},{"key":"sh28171","label":"الأوسط","number":532},{"key":"hakim","label":"الحاكم","number":189},{"key":"sh13075","label":"النفقة على العيال لابن أبي الدنيا","number":529,"n":523},{"key":"sh13152","label":"مداراة الناس لابن أبي الدنيا","number":174,"n":174},{"key":"kubranasai","label":"النسائي في الكبري","number":8963}],"full":1,"dr":1},{"num":6320,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَوْ كُنْتُ آمِرًا أَحَدًا أَنْ يَسْجُدَ لأَحَدٍ لأَمَرْتُ الْمَرْأَةَ أَنْ تَسْجُدَ لِزَوْجِهَا."],"takhrij":"حسن: رواه الترمذي (1159) والبيهقي (7/291) وابن أبي الدنيا في العيال (534) كلهم من حديث النضر بن شميل، أنا محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكره. وإسناده حسن من أجل محمد بن عمرو وهو ابن علقمة الليثي فإنه حسن الحديث.","grade":"حسن","chapter_ar":"باب حق الزوج على الزوجة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1159), al-Bayhaqi (7/291), and Ibn Abi al-Dunya in al-‘Iyal (534).","chapter_en":"The husband’s right over his wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah reported from the Prophet ﷺ that he said: “If I were to command anyone to prostrate to anyone, I would have commanded the woman to prostrate to her husband.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1159,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":291},{"key":"sh13075","label":"ابن أبي الدنيا في العيال","number":534},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":14704,"n":14851}],"full":1,"dr":1,"rep":[12572]},{"num":6321,"demo":false,"sanad":"","matn":["عن سراقة بن مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَوْ كُنْتُ آمِرًا أَحَدًا أَنْ يَسْجُدَ لِأَحَدٍ لَأَمَرْتُ الْمَرْأَةَ أَنْ تَسْجُدَ لِزَوْجِهَا."],"takhrij":"صحيح: رواه الطبراني في الكبير (7/152) وابن أبي الدنيا في العيال (537) موسوعة ابن أبي الدنيا – كلاهما من حديث وهب بن جرير بن حازم، حدثنا موسى بن عُلّى، عن أبيه، عن سراقة بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب حق الزوج على الزوجة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tabarani in al-Kabir (7/152) and Ibn Abi al-Dunya in al-‘Iyal (537).","chapter_en":"The husband’s right over his wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Suraqah ibn Malik said that the Messenger of Allah ﷺ said: “If I were to command anyone to prostrate to anyone, I would have commanded the woman to prostrate to her husband.”"]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":152,"lafz":true},{"key":"sh13075","label":"ابن أبي الدنيا في العيال","number":537}],"full":1,"dr":1,"rep":[12571]},{"num":6322,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَوْ أَمَرْتُ أَحَدًا أَنْ يَسْجُدَ لأَحَدٍ لأَمَرْتُ الْمَرْأَةَ أَنْ تَسْجُدَ لِزَوْجِهَا وَلَوْ أَنَّ رَجُلاً أَمَرَ امْرَأَةً أَنْ تَنْقُلَ مِنْ جَبَلٍ أَحْمَرَ إِلَى جَبَلٍ أَسْوَدَ وَمِنْ جَبَلٍ أَسْوَدَ إِلَى جَبَلٍ أَحْمَرَ - لَكَانَ نَوْلُهَا أَنْ تَفْعَلَ."],"takhrij":"حسن: رواه ابن ماجة (1852) عن ابن أبي شيبة وهو في مصنفه (4/206) وأحمد (24471) كلهم من طريق عفان، قال: حدثنا حماد بن سلمة، عن علي بن زيد، عن سعيد بن المسيب، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب حق الزوج على الزوجة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (1852), Ibn Abi Shaybah in his Musannaf (4/206), and Ahmad (24471).","chapter_en":"The husband’s right over his wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["‘A’ishah reported that the Messenger of Allah ﷺ said: “If I were to command anyone to prostrate to anyone, I would have commanded the woman to prostrate to her husband. And if a man were to command his wife to move from a red mountain to a black mountain, and from a black mountain to a red mountain, it would be her duty to do so.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":1852,"lafz":true},{"key":"sh9944","label":"ابن أبي شيبة في مصنفه","number":206},{"key":"ahmad","label":"مسند الإمام أحمد","number":24471,"n":24471}],"full":1,"dr":1},{"num":6323,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ ثَلاَثَةٌ لاَ تَرْتَفِعُ صَلاَتُهُمْ فَوْقَ رُءُوسِهِمْ شِبْرًا رَجُلٌ أَمَّ قَوْمًا وَهُمْ لَهُ كَارِهُونَ، وَامْرَأَةٌ بَاتَتْ وَزَوْجُهَا عَلَيْهَا سَاخِطٌ وَأَخَوَانِ مُتَصَارِمَانِ."],"takhrij":"حسن: رواه ابن ماجه (971) قال: حدثنا محمد بن عمر بن هيَّاج، قال: حدثنا يحيى بن عبدالرحمن الأرحبي، قال: حدثنا عبيدة بن الأسود، عن القاسم بن الوليد، عن المنهال بن عمرو، عن سعيد بن جبير، عن ابن عباس فذكر الحديث.","grade":"حسن","chapter_ar":"باب حق الزوج على الزوجة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (971).","chapter_en":"The husband’s right over his wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Ibn ‘Abbas reported that the Messenger of Allah ﷺ said: “Three persons’ prayer does not rise even a handspan above their heads: a man who leads people in prayer while they dislike him, a woman who spends the night while her husband is angry with her, and two brothers who are in estrangement with one another.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":971,"lafz":true}],"full":1,"dr":1,"rep":[2254]},{"num":6324,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يَنْظُرُ اللَّهُ إِلَى امْرَأَةٍ لَا تَشْكَرُ لِزَوْجِهَا وَهِيَ لَا تَسْتَغْنِي عَنْهُ."],"takhrij":"صحيح: رواه النسائي في الكبرى (9086) عن عمرو بن منصور، قال: حدثنا محمد بن محبوب، قال: حدثنا سَرَّار بن مجشِّر بن قبيصة البصري-ثقة-، عن سعيد بن أبي عروبة، عن قتادة، عن سعيد بن المسيب، عن عبدالله بن عمرو، فذكره.","grade":"صحيح","chapter_ar":"باب استحباب شكر المرأة لزوجها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i in al-Kubra (9086).","chapter_en":"The recommendation that a woman be grateful to her husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["‘Abd Allah ibn ‘Amr ibn al-‘As said: the Messenger of Allah ﷺ said: “Allah does not look at a woman who is ungrateful to her husband while she cannot do without him.”"]}},"tuhfa":{},"refs":[{"key":"kubranasai","label":"النسائي في الكبرى","number":9086,"lafz":true}],"full":1,"dr":1},{"num":6325,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ خَيْرُ نِسَاءٍ رَكِبْنَ الإِبِلَ صَالِحُو نِسَاءِ قُرَيْشٍ، أَحْنَاهُ عَلَى وَلَدٍ فِي صِغَرِهِ وَأَرْعَاهُ عَلَى زَوْجٍ فِي ذَاتِ يَدِهِ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5082) ومسلم في فضائل الصحابة (200:2527) كلاهما من طريق أبي الزناد، عن الأعرج، عن أبي هريرة فذكره،","grade":"متفق عليه","chapter_ar":"باب رعاية المرأة لزوجها وولدها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5082) and Muslim (200:2527), with the wording from al-Bukhari.","chapter_en":"A woman’s care for her husband and her child","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":10,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “The best women who rode camels are the righteous women of Quraysh: the most tender toward a child in his young age, and the most careful in safeguarding her husband’s property.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5082,"lafz":true},{"key":"muslim","label":"مسلم","number":200}],"full":1,"dr":1,"rep":[6223]},{"num":6326,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَتْ تَزَوَّجَنِي الزُّبَيْرُ، وَمَا لَهُ فِي الأَرْضِ مِنْ مَالٍ، وَلاَ مَمْلُوكٍ، وَلاَ شَىْءٍ غَيْرَ نَاضِحٍ، وَغَيْرَ فَرَسِهِ، فَكُنْتُ أَعْلِفُ فَرَسَهُ، وَأَسْتَقِي الْمَاءَ، وَأَخْرِزُ غَرْبَهُ وَأَعْجِنُ، وَلَمْ أَكُنْ أُحْسِنُ أَخْبِزُ، وَكَانَ يَخْبِزُ جَارَاتٌ لِي مِنَ الأَنْصَارِ وَكُنَّ نِسْوَةَ صِدْقٍ، وَكُنْتُ أَنْقُلُ النَّوَى مِنْ أَرْضِ الزُّبَيْرِ الَّتِي أَقْطَعَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى رَأْسِي، وَهْىَ مِنِّي عَلَى ثُلُثَىْ فَرْسَخٍ، فَجِئْتُ يَوْمًا وَالنَّوَى عَلَى رَأْسِي فَلَقِيتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَعَهُ نَفَرٌ مِنَ الأَنْصَارِ فَدَعَانِي ثُمَّ قَالَ إِخْ إِخْ. لِيَحْمِلَنِي خَلْفَهُ، فَاسْتَحْيَيْتُ أَنْ أَسِيرَ مَعَ الرِّجَالِ، وَذَكَرْتُ الزُّبَيْرَ وَغَيْرَتَهُ، وَكَانَ أَغْيَرَ النَّاسِ، فَعَرَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنِّي قَدِ اسْتَحْيَيْتُ فَمَضَى، فَجِئْتُ الزُّبَيْرَ فَقُلْتُ لَقِيَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَى رَأْسِي النَّوَى، وَمَعَهُ نَفَرٌ مِنْ أَصْحَابِهِ، فَأَنَاخَ لأَرْكَبَ، فَاسْتَحْيَيْتُ مِنْهُ وَعَرَفْتُ غَيْرَتَكَ. فَقَالَ وَاللَّهِ لَحَمْلُكِ النَّوَى كَانَ أَشَدَّ عَلَىَّ مِنْ رُكُوبِكِ مَعَهُ. قَالَتْ حَتَّى أَرْسَلَ إِلَىَّ أَبُو بَكْرٍ بَعْدَ ذَلِكَ بِخَادِمٍ يَكْفِينِي سِيَاسَةَ الْفَرَسِ، فَكَأَنَّمَا أَعْتَقَنِي."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5224)، ومسلم في السلام (2182) كلاهما من حديث أبي أسامة، حدّثنا هشام، قال: أخبرني أبي، عن أسماء بنت أبي بكر رضي الله عنهما، فذكرته.","grade":"متفق عليه","chapter_ar":"باب رعاية المرأة لزوجها وولدها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5224) and Muslim (2182).","chapter_en":"A woman’s care for her husband and her child","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":10,"content":{"translation":{"en":["Asma’ bint Abi Bakr said: Al-Zubayr married me when he had no wealth on earth, no servant, and nothing except a camel for drawing water and his horse. So I used to feed his horse, fetch water, stitch his water-skin, and knead dough. I was not good at baking bread, and some neighbor women from the Ansar used to bake for me, and they were truthful women. I used to carry date-stones on my head from the land of al-Zubayr that the Messenger of Allah ﷺ had granted him, and it was about two-thirds of a farsakh away. One day I came carrying date-stones on my head, and I met the Messenger of Allah ﷺ with a group of the Ansar. He called me and then said, “Ikh, ikh,” to make me ride behind him. But I felt shy to go with the men, and I remembered al-Zubayr and his jealousy, and he was the most jealous of people. So the Messenger of Allah ﷺ realized that I was shy and continued on. Then I came to al-Zubayr and said: The Messenger of Allah ﷺ met me while I had date-stones on my head, and he had some of his Companions with him, and he made his camel kneel so I could ride, but I felt shy before him and remembered your jealousy. He said: By Allah, your carrying date-stones on your head was harder on me than your riding with him. She said: Then later Abu Bakr sent me a servant who relieved me of tending the horse, and it was as if he had freed me."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5224,"lafz":true},{"key":"muslim","label":"مسلم","number":2182}],"full":1,"dr":1},{"num":6327,"demo":false,"sanad":"","matn":["عن عليّ أَنَّ فَاطِمَةَ ـ عَلَيْهِمَا السَّلاَمُ ـ أَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَشْكُو إِلَيْهِ مَا تَلْقَى فِي يَدِهَا مِنَ الرَّحَى، وَبَلَغَهَا أَنَّهُ جَاءَهُ رَقِيقٌ فَلَمْ تُصَادِفْهُ، فَذَكَرَتْ ذَلِكَ لِعَائِشَةَ، فَلَمَّا جَاءَ أَخْبَرَتْهُ عَائِشَةُ ـ قَالَ ـ فَجَاءَنَا وَقَدْ أَخَذْنَا مَضَاجِعَنَا، فَذَهَبْنَا نَقُومُ فَقَالَ عَلَى مَكَانِكُمَا. فَجَاءَ فَقَعَدَ بَيْنِي وَبَيْنَهَا حَتَّى وَجَدْتُ بَرْدَ قَدَمَيْهِ عَلَى بَطْنِي فَقَالَ أَلاَ أَدُلُّكُمَا عَلَى خَيْرٍ مِمَّا سَأَلْتُمَا، إِذَا أَخَذْتُمَا مَضَاجِعَكُمَا ـ أَوْ أَوَيْتُمَا إِلَى فِرَاشِكُمَا ـ فَسَبِّحَا ثَلاَثًا وَثَلاَثِينَ، وَاحْمَدَا ثَلاَثًا وَثَلاَثِينَ، وَكَبِّرَا أَرْبَعًا وَثَلاَثِينَ، فَهْوَ خَيْرٌ لَكُمَا مِنْ خَادِمٍ."],"takhrij":"متفق عليه: رواه البخاري في النفقات ( 5361) ومسلم في الذكر والدعاء (2727) كلاهما من طريق شعبة، قال: حدثني الحكم، عن ابن أبي ليلى، حدّثنا علي، فذكره.","grade":"متفق عليه","chapter_ar":"باب رعاية المرأة لزوجها وولدها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5361) and Muslim (2727).","chapter_en":"A woman’s care for her husband and her child","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":10,"content":{"translation":{"en":["‘Ali ibn Abi Talib reported that Fatimah came to the Prophet ﷺ complaining about what her hands suffered from grinding with the millstone. News had reached her that some captives had come to him, but she did not find him, so she mentioned it to ‘A’ishah. When he came, ‘A’ishah informed him. He said: So he came to us after we had gone to our beds, and we started to get up, but he said: “Stay where you are.” Then he came and sat between me and her until I felt the coolness of his feet on my stomach. Then he said: “Shall I not direct you to something better than what you asked for? When you go to your beds, or lie down in your bed, say ‘Subhan Allah’ thirty-three times, ‘Alhamdulillah’ thirty-three times, and ‘Allahu Akbar’ thirty-four times. That is better for you than a servant.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5361,"lafz":true},{"key":"muslim","label":"مسلم","number":2727}],"full":1,"dr":1},{"num":6328,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ كُلُّكُمْ رَاعٍ، وَكُلُّكُمْ مَسْئُولٌ عَنْ رَعِيَّتِهِ، وَالأَمِيرُ رَاعٍ، وَالرَّجُلُ رَاعٍ عَلَى أَهْلِ بَيْتِهِ، وَالْمَرْأَةُ رَاعِيَةٌ عَلَى بَيْتِ زَوْجِهَا وَوَلَدِهِ، فَكُلُّكُمْ رَاعٍ وَكُلُّكُمْ مَسْئُولٌ عَنْ رَعِيَّتِهِ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5200) من طريق موسى بن عُقبة، ومسلم في الإمارة (20:1829) من طريق الليث – كلاهما عن نافع، عن ابن عمر.وزاد مسلم: والعبدُ راعٍ على مال سيّده، وهو مسؤول عنه.","grade":"متفق عليه","chapter_ar":"باب رعاية المرأة لزوجها وولدها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5200) and Muslim (20:1829).","chapter_en":"A woman’s care for her husband and her child","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":10,"content":{"translation":{"en":["Ibn ‘Umar reported from the Prophet ﷺ that he said: “Each of you is a shepherd, and each of you is responsible for his flock. The ruler is a shepherd. A man is a shepherd over the people of his household. A woman is a shepherd over the house of her husband and his child. So each of you is a shepherd, and each of you is responsible for his flock.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5200,"lafz":true},{"key":"muslim","label":"مسلم","number":20}],"full":1},{"num":6329,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رضي الله عنه قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : كُلُّ نَفْسٍ مِنْ بَنِي آدَمَ سَيِّدٌ، فَالرَّجُلُ سَيِّدُ أَهْلِهِ، وَالْمَرْأَةُ سَيِّدَةُ بَيْتِهَا."],"takhrij":"حسن: رواه ابنُ السنّي في عمل اليوم والليلة (389)، وابنُ عدي في الكامل (4/1520)-ترجمة عبد الله بن وهب المصري- كلاهما من طرقٍ عن أحمد بن عمرو بن السرح، حدثنا ابنُ وهب، أخبرني عمرو بن الحارث، عن أبي يونس (واسمه سليم بن جبير مولى أبي هريرة)، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب رعاية المرأة لزوجها وولدها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn al-Sunni in ‘Amal al-Yawm wa al-Laylah (389), and Ibn ‘Adi in al-Kamil (4/1520).","chapter_en":"A woman’s care for her husband and her child","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":10,"content":{"translation":{"en":["Abu Hurayrah said: the Messenger of Allah ﷺ said: “Every soul from the children of Adam is a master. So the man is the master of his family, and the woman is the lady of her house.”"]}},"tuhfa":{},"refs":[{"key":"sh13132","label":"ابنُ السنّي في عمل اليوم والليلة","number":389,"lafz":true,"n":379},{"key":"sh12579","label":"ابنُ عدي في الكامل","number":1520},{"key":"amalyawm","label":"ابن السني في عمل اليوم والليله","number":389}],"full":1,"dr":1},{"num":6330,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنِّي لأَعْلَمُ إِذَا كُنْتِ عَنِّي رَاضِيَةً، وَإِذَا كُنْتِ عَلَىَّ غَضْبَى. قَالَتْ فَقُلْتُ مِنْ أَيْنَ تَعْرِفُ ذَلِكَ فَقَالَ أَمَّا إِذَا كُنْتِ عَنِّي رَاضِيَةً فَإِنَّكِ تَقُولِينَ لاَ وَرَبِّ مُحَمَّدٍ، وَإِذَا كُنْتِ غَضْبَى قُلْتِ لاَ وَرَبِّ إِبْرَاهِيمَ. قَالَتْ قُلْتُ أَجَلْ وَاللَّهِ يَا رَسُولَ اللَّهِ، مَا أَهْجُرُ إِلاَّ اسْمَكَ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5228)، ومسلم في فضائل الصحابة (80:2439) كلاهما من طريق أبي أسامة، عن هشام، عن أبيه، عن عائشة، فذكرته.","grade":"متفق عليه","chapter_ar":"باب غضب المرأة على زوجها وهجرها له","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5228) and Muslim (80:2439).","chapter_en":"A wife’s anger with her husband and her forsaking him","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":11,"content":{"translation":{"en":["‘A’ishah said: the Messenger of Allah ﷺ said to me: “I certainly know when you are pleased with me and when you are angry with me.” She said: I said: How do you know that? He said: “When you are pleased with me, you say: ‘No, by the Lord of Muhammad,’ and when you are angry, you say: ‘No, by the Lord of Ibrahim.’” She said: I replied: Yes, by Allah, O Messenger of Allah, I do not forsake except your name."]},"buhuth":{"en":["The anger meant here is the jealousy that affected the wives of the Prophet ﷺ. As for anger in the sense of hatred, that cannot be imagined from ‘A’ishah toward the Prophet ﷺ, because that would be a grave matter and ruinous to deeds. As for someone other than the Prophet ﷺ, that is possible."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5228,"lafz":true},{"key":"muslim","label":"مسلم","number":80}],"full":1,"dr":1,"rep":[10391]},{"num":6331,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ، عَبْدِ اللَّهِ قَالَ تَزَوَّجْتُ امْرَأَةً فَقَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَلْ تَزَوَّجْتَ. قُلْتُ نَعَمْ. قَالَ أَبِكْرًا أَمْ ثَيِّبًا. قُلْتُ ثَيِّبًا. قَالَ فَأَيْنَ أَنْتَ مِنَ الْعَذَارَى وَلِعَابِهَا.","قال شعبة: فذكرته لعمرو بن دينار. فقال: قد سمعته من جابر. وإنما قال: فهلا جارية تلاعبُها وتلاعبُك؟."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5080)، ومسلم في الرضاع (55:1466) كلاهما من طريق شعبة، حدّثنا محارب قال: سمعت جابر بن عبد الله يقول: فذكره","grade":"متفق عليه","chapter_ar":"باب ملاعبة الزوجة ومضاحكتها والانبساط إليها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5080) and Muslim (55:715), and the wording is that of Muslim.","chapter_en":"Playing with one’s wife, joking with her, and being relaxed and cheerful with her","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":12,"content":{"translation":{"en":["Jabir said: I married a woman, so the Messenger of Allah ﷺ said to me: “Have you married?” I said: Yes. He said: “A virgin or a previously married woman?” I said: A previously married woman. He said: “Then why not a young virgin, so you could play with her and she could play with you?” Shu‘bah said: I mentioned it to ‘Amr ibn Dinar, and he said: I heard it from Jabir. Rather, he said: “Why not a young girl whom you could amuse and who could amuse you?”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5080,"lafz":true},{"key":"muslim","label":"مسلم","number":55}],"full":1,"dr":1,"rep":[6199,6202]},{"num":6332,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ قَالَ: كُنَّا نَتَّقِي الْكَلاَمَ وَالاِنْبِسَاطَ إِلَى نِسَائِنَا عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَيْبَةَ أَنْ يُنْزَلَ فِينَا شيء، فَلَمَّا تُوُفِّيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَكَلَّمْنَا وَانْبَسَطْنَا."],"takhrij":"صحيح: رواه البخاري في النكاح (5187) عن أبي نعيم، حدثنا سفيان، عن عبد الله بن دينار، عن ابن عمر رضي الله عنهما. فذكره.","grade":"صحيح","chapter_ar":"باب ملاعبة الزوجة ومضاحكتها والانبساط إليها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5187).","chapter_en":"Playing with one’s wife, joking with her, and being relaxed and cheerful with her","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":12,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar said: During the lifetime of the Prophet ﷺ, we used to avoid speaking freely and being relaxed with our wives out of fear that something might be revealed concerning us. But when the Prophet ﷺ passed away, we spoke more openly and became relaxed."]},"buhuth":{"en":["His saying, “When he passed away…” Ibn Hajar said: This indicates that what they had been leaving off was originally permissible under the basic presumption of permissibility. They had feared that a prohibition might be revealed concerning it. After the Prophet ﷺ passed away, they felt safe and did it, holding to the original presumption of permissibility."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5187,"lafz":true}],"full":1,"dr":1},{"num":6333,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ امْرَأَةً، مِنَ الأَنْصَارِ زَوَّجَتِ ابْنَتَهَا فَتَمَعَّطَ شَعَرُ رَأْسِهَا، فَجَاءَتْ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَتْ ذَلِكَ لَهُ، فَقَالَتْ إِنَّ زَوْجَهَا أَمَرَنِي أَنْ أَصِلَ فِي شَعَرِهَا. فَقَالَ لاَ إِنَّهُ قَدْ لُعِنَ الْمُوصِلاَتُ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5205)، ومسلم في اللباس والزينة (118:2123) كلاهما من طريق إبراهيم بن نافع، أخبرني الحسن بن مسلم ابن ينّاق، عن صفية بنت شيبة، عن عائشة، فذكرته. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب النهي عن وصل شعر المرأة، وإن أمر به زوجها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5205) and Muslim (118:2123), with the wording from al-Bukhari.","chapter_en":"The prohibition of adding hair to a woman’s hair, even if her husband commands it","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":13,"content":{"translation":{"en":["‘A’ishah reported that a woman from the Ansar married off her daughter, and the hair of her head fell out. So she came to the Prophet ﷺ and mentioned that to him, and said: Her husband has ordered me to add hair to hers. He said: “No. Indeed, those who add hair have been cursed.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5205,"lafz":true},{"key":"muslim","label":"مسلم","number":118}],"full":1},{"num":6334,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ يَطْرُقُ أَهْلَهُ، كَانَ لاَ يَدْخُلُ إِلاَّ غُدْوَةً أَوْ عَشِيَّةً."],"takhrij":"متفق عليه: رواه البخاري في الحج (1800)، ومسلم في الإمارة (1928-180) كلاهما من حديث همام بن يحيى، حدثنا إسحاق بن عبد الله بن أبي طلحة، عن أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي أن يطرق الرجل أهله ليلاً","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1800) and Muslim (180:1928).","chapter_en":"The prohibition of a man arriving suddenly to his family at night","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":14,"content":{"translation":{"en":["Anas said: The Prophet ﷺ would not come suddenly upon his family at night. He would only enter in the morning or in the evening."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1800,"lafz":true},{"key":"muslim","label":"مسلم","number":180},{"key":"muslim","label":"مسلم في الاماره","number":1928}],"full":1},{"num":6335,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزَاةٍ فَلَمَّا قَدِمْنَا الْمَدِينَةَ ذَهَبْنَا لِنَدْخُلَ فَقَالَ أَمْهِلُوا حَتَّى نَدْخُلَ لَيْلاً - أَىْ عِشَاءً - كَىْ تَمْتَشِطَ الشَّعِثَةُ وَتَسْتَحِدَّ الْمُغِيبَةُ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5079)، ومسلم في الإمارة (1928: 181) كلاهما من طريق هُشيم، حدثنا سيّار، عن الشعبي، عن جابر، فذكره، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي أن يطرق الرجل أهله ليلاً","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5079) and Muslim (181:1928), with the wording from Muslim.","chapter_en":"The prohibition of a man arriving suddenly to his family at night","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":14,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: We were with the Messenger of Allah ﷺ on an expedition. When we arrived at Madinah and were about to enter, he said: “Wait until we enter at night — meaning in the evening — so that the woman with disheveled hair may comb herself, and the woman whose husband has been absent may remove her unwanted hair.”"]},"buhuth":{"en":["In a narration in al-Bukhari (5244): “If one of you has been away for a long time, he should not come to his family suddenly at night.”","And in a narration in Abu Dawud (2777) by another chain: “The best way for a man to enter upon his family when returning from a journey is at the beginning of the night.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5079,"lafz":true,"n":5247},{"key":"muslim","label":"مسلم","number":181},{"key":"muslim","label":"مسلم في الاماره","number":1928,"n":4964}],"full":1,"dr":1},{"num":6336,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: كان النبي صلى الله عليه وسلم يكره أن يأتي الرجل أهله طروقاً. وزاد في رواية: يتخوّنهم أو يلتمِسُ عثراتهم."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5243)، ومسلم في الإمارة (185:1928) كلاهما من طريق شعبة، حدثنا محارب بن دثار، قال: سمعت جابر بن عبد الله، فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب النهي أن يطرق الرجل أهله ليلاً","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5243) and Muslim (185:1928), with the wording from al-Bukhari.","chapter_en":"The prohibition of a man arriving suddenly to his family at night","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":14,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The Prophet ﷺ disliked that a man should come upon his family suddenly at night. And in another narration there is an addition: seeking to suspect them of betrayal or looking for their faults."]},"buhuth":{"en":["His saying, “suspecting them…” means searching for betrayal and whether she is chaste or not. But the basic assumption regarding a believing woman is that she is chaste, so it is not permissible to spy concerning her chastity. This is one of the wisdoms behind the prohibition of entering upon women suddenly at night."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5243,"lafz":true},{"key":"muslim","label":"مسلم","number":185}],"full":1,"dr":1},{"num":6337,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر قال: كنا في غزوة، فقال رسول الله صلى الله عليه وسلم: لا تطرقوا النساءَ، وأرسلَ من يؤذِنُ الناسَ أنهم قادمون الغداة."],"takhrij":"صحيح: رواه ابن خزيمة كما في إتحاف المهرة (9/249)، وأبو عوانة في مسنده (7536)، والبيهقي في الكبرى (9/174) كلهم من طريق ابن وهب، قال: حدثني عمر بن محمد بن زيد، عن نافع، عن عبد الله بن عمر قال: فذكره.","grade":"صحيح","chapter_ar":"باب النهي أن يطرق الرجل أهله ليلاً","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Khuzaymah as cited in Ithaf al-Maharah (9/249), Abu ‘Awanah (7536), and al-Bayhaqi (9/174).","chapter_en":"The prohibition of a man arriving suddenly to his family at night","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":14,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar said: We were on an expedition, and the Messenger of Allah ﷺ said: “Do not come suddenly upon the women.” And he sent someone to announce to the people that they would be arriving the next morning."]}},"tuhfa":{},"refs":[{"key":"ibnkhuzaymah","label":"ابن خزيمة كما في إتحاف المهرة","number":249,"lafz":true},{"key":"sh21618","label":"أبو عوانة","number":7536},{"key":"kubrabayhaqi","label":"البيهقي","number":174}],"full":1,"dr":1},{"num":6338,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عَبَّاسٍ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنِّي رَأَيْتُ الْجَنَّةَ فَتَنَاوَلْتُ مِنْهَا عُنْقُودًا، وَلَوْ أَخَذْتُهُ لأَكَلْتُمْ مِنْهُ مَا بَقِيَتِ الدُّنْيَا، وَرَأَيْتُ النَّارَ فَلَمْ أَرَ كَالْيَوْمِ مَنْظَرًا قظ أَفْظَعَ وَرَأَيْتُ أكثرها النِّسَاءَ قَالُوا: لِمَ يَا رَسُولَ اللَّهِ؟ قَالَ: لِكُفْرِهِنَّ قِيلَ: أَيَكْفُرْنَ بِاللَّهِ؟ قَالَ: وَيَكْفُرْنَ الْعَشِيرَ، وَيَكْفُرْنَ الإِحْسَانَ، لَوْ أَحْسَنْتَ إِلَيْهَا الدَّهْرَ كُلَّهُ، ثُمَّ رَأَتْ مِنْكَ شَيْئًا، قَالَتْ: مَا رَأَيْتُ مِنْكَ خَيْرًا قَطُّ."],"takhrij":"متفق عليه: رواه مالك في صلاة الكسوف (2) عن زيد بن أسلم، عن عطاء بن يسار، عن عبد الله بن عباس، فذكره بتمامه في صلاة الكسوف.","grade":"متفق عليه","chapter_ar":"باب نهي النساء عن كفر العشير","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (2), al-Bukhārī (5197), and Muslim (907).","chapter_en":"Warning women against ingratitude toward the husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Ibn ʿAbbās reported that the Messenger of Allah ﷺ said: “I saw Paradise and reached for a cluster from it. Had I taken it, you would have continued eating from it for as long as this world remained. I also saw the Fire, and I have never seen a sight more terrifying than it today, and I saw that most of its inhabitants were women.” They asked: “Why, O Messenger of Allah?” He said: “Because of their ingratitude.” It was asked: “Do they disbelieve in Allah?” He replied: “They are ungrateful to their husbands and ungrateful for kindness. If you were good to one of them for an entire lifetime, then she saw one thing from you that displeased her, she would say: ‘I have never seen any good from you at all.’”"]},"buhuth":{"en":["The word al-ʿashīr means the husband.","The expression “they commit kufr” means that they deny or show ingratitude. This demonstrates that the word kufr may be used for ingratitude toward rights without thereby making a person a disbeliever in Allah Most High. The detailed discussion appears in the Book of Faith.","The word “cluster” refers to grapes or similar fruit gathered together on a single stem; it is also called a qiṭf."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":2,"lafz":true},{"key":"bukhari","label":"البخاري","number":5197},{"key":"muslim","label":"مسلم","number":907}],"full":1,"dr":1},{"num":6339,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي أَضْحًى ـ أَوْ فِطْرٍ ـ إِلَى الْمُصَلَّى، فَمَرَّ عَلَى النِّسَاءِ فَقَالَ يَا مَعْشَرَ النِّسَاءِ تَصَدَّقْنَ، فَإِنِّي أُرِيتُكُنَّ أَكْثَرَ أَهْلِ النَّارِ. فَقُلْنَ وَبِمَ يَا رَسُولَ اللَّهِ قَالَ تُكْثِرْنَ اللَّعْنَ، وَتَكْفُرْنَ الْعَشِيرَ، مَا."],"takhrij":"متفق عليه: رواه البخاري في الحيض (304)، ومسلم في الإيمان (80) من طريق سعيد بن أبي مريم، أخبرنا محمد بن جعفر، أخبرني زيد بن أسلم، عن عياض بن عبد الله، عن أبي سعيد الخدري، فذكره. واللفظ للبخاري. ولم يذكر مسلم لفظه وإنما حال فيه على حديث ابن عمر رضي الله عنهما، وهو الآتي:","grade":"متفق عليه","chapter_ar":"باب نهي النساء عن كفر العشير","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (304) and Muslim (80), and the wording is from al-Bukhari.","chapter_en":"Warning women against ingratitude toward the husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: The Messenger of Allah ﷺ went out on the Day of Adha or Fitr to the prayer-place. He passed by the women and said: “O gathering of women, give charity, for I saw that you are the majority of the people of the Fire.” They said: Why is that, O Messenger of Allah? He said: “You frequently curse, and you are ungrateful to the husband…” to the end of the hadith."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":304,"lafz":true},{"key":"muslim","label":"مسلم","number":80}],"full":1,"rep":[16503]},{"num":6340,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ شَهِدْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الصَّلاَةَ يَوْمَ الْعِيدِ فَبَدَأَ بِالصَّلاَةِ قَبْلَ الْخُطْبَةِ بِغَيْرِ أَذَانٍ وَلاَ إِقَامَةٍ ثُمَّ قَامَ مُتَوَكِّئًا عَلَى بِلاَلٍ فَأَمَرَ بِتَقْوَى اللَّهِ وَحَثَّ عَلَى طَاعَتِهِ وَوَعَظَ النَّاسَ وَذَكَّرَهُمْ ثُمَّ مَضَى حَتَّى أَتَى النِّسَاءَ فَوَعَظَهُنَّ وَذَكَّرَهُنَّ فَقَالَ تَصَدَّقْنَ فَإِنَّ أَكْثَرَكُنَّ حَطَبُ جَهَنَّمَ فَقَامَتْ امْرَأَةٌ مِنْ سِطَةِ النِّسَاءِ سَفْعَاءُ الْخَدَّيْنِ فَقَالَتْ لِمَ يَا رَسُولَ اللَّهِ قَالَ لِأَنَّكُنَّ تُكْثِرْنَ الشَّكَاةَ وَتَكْفُرْنَ الْعَشِيرَ قَالَ فَجَعَلْنَ يَتَصَدَّقْنَ مِنْ حُلِيِّهِنَّ يُلْقِينَ فِي ثَوْبِ بِلَالٍ مِنْ أَقْرِطَتِهِنَّ وَخَوَاتِمِهِنَّ."],"takhrij":"متفق عليه: رواه مسلم في صلاة العيدين (4:885) عن محمد بن عبدا لله بن نمير، حدثنا أبي، حدّثنا عبدالملك بن أبي سليمان، عن عطاء، عن جابر، فذكره.","grade":"متفق عليه","chapter_ar":"باب نهي النساء عن كفر العشير","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (4:885) and al-Bukhari (978).","chapter_en":"Warning women against ingratitude toward the husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: I witnessed the Eid prayer with the Messenger of Allah ﷺ. He began with the prayer before the sermon, without adhan or iqamah. Then he stood, leaning on Bilal, and commanded the people to fear Allah, urged them to obey Him, admonished them, and reminded them. Then he moved on until he came to the women, and he admonished and reminded them, saying: “Give charity, for most of you are the fuel of Hell.” Then a woman from the middle of the women stood up, with darkened cheeks, and said: Why, O Messenger of Allah? He said: “Because you complain much and are ungrateful to the husband.” He said: Then they began giving charity from their jewelry, throwing into Bilal’s cloth their earrings and rings."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":4,"lafz":true},{"key":"bukhari","label":"البخاري","number":978}],"full":1,"dr":1},{"num":6341,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: يَا مَعْشَرَ النِّسَاءِ تصدَّقْنَ وأكثِرْنَ الاِسْتِغْفَارَ، فَإِنِّي رَأَيْتُكُنَّ أَكْثَرَ أَهْلِ النَّارِ، فَقَالَتِ امْرَأَةٌ مِنْهُنَّ، جَزْلَةٌ: وَمَا لَنَا يَا رَسُولَ اللَّهِ أَكْثَرَ أَهْلِ النَّارِ؟ قَالَ: تُكْثِرْنَ اللَّعْنَ، وتكفُرْنَ الْعَشِيرَ الحديث."],"takhrij":"صحيح: رواه مسلم في الإيمان (79) عن محمد بن رُمح بن المهار المصريّ، أخبرنا الليث (هو ابن سعد)، عن ابن الهاد، عن عبدالله بن دينار، عن عبدالله بن عمر، فذكره.","grade":"صحيح","chapter_ar":"باب نهي النساء عن كفر العشير","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (79).","chapter_en":"Warning women against ingratitude toward the husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar reported that the Messenger of Allah ﷺ said: “O gathering of women, give charity and seek forgiveness often, for I saw that you are the majority of the people of the Fire.” A strong-minded woman among them said: Why are we, O Messenger of Allah, the majority of the people of the Fire? He said: “You curse frequently and you are ungrateful to the husband,” to the end of the hadith."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":79,"lafz":true}],"full":1,"rep":[16504]},{"num":6342,"demo":false,"sanad":"","matn":["عن أبي هـريرة، عن النـبي صلى الله عليه وسلم بمثـل معـنى حديث ابن عمر عن النبي صلى الله عليه وسلم كما قال مسلم."],"takhrij":"صحيح: رواه مسلم في الإيمان (80) من طريق إسماعيل( هو ابن جعفر) عن عمرو بن أبي عمرو، عن المقبري، عن أبي هريرة، عن النبي صلى الله عليه وسلم ولم يذكر مسلم لفظه وإنما أحال فيه على حديث ابن عمر السابق.","grade":"صحيح","chapter_ar":"باب نهي النساء عن كفر العشير","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (80).","chapter_en":"Warning women against ingratitude toward the husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ something with the same meaning as the hadith of Ibn ‘Umar from the Prophet ﷺ, as stated by Muslim."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":80,"lafz":true}],"full":1,"dr":1},{"num":6343,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ يَزِيدَ –إِحْدَى نساء بني عَبْدِ الأشهل- تَقُولُ: مَرَّ بِنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ فِي نِسْوَةٍ، فسلَّم عَلَيْنَا، وَقَالَ: إِيَّاكُنَّ وَكُفْرَ الْمُنَعَّمِينَ، فَقُلْنَا: يَا رَسُولَ اللَّهِ، وَمَا كُفْرُ الْمُنَعَّمِينَ؟ قَالَ: لَعَلَّ إِحْدَاكُنَّ أَنْ تَطُولَ أَيْمَتُهَا بَيْنَ أَبَوَيْهَا، وَتَعْنُسَ، فَيَرْزُقَهَا اللهُ عَزَّ وَجَلَّ زَوْجًا، وَيَرْزُقَهَا مِنْهُ مَالًا وَوَلَدًا، فَتَغْضَبَ الْغَضْبَةَ، فَتَقُولُ: مَا رَأَيْتُ مِنْهُ يَوْمًا خَيْرًا قَطُّ."],"takhrij":"حسن: رواه أحمد (27561) والطبراني في الكبير (24/164) كلاهما من حديث شهر يقول: سمعت أسماء تقول: فذكرته.","grade":"حسن","chapter_ar":"باب نهي النساء عن كفر العشير","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (27561) and al-Ṭabarānī in al-Kabīr (24/164).","chapter_en":"Warning women against ingratitude toward the husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Asmāʾ bint Yazīd, one of the women of Banū ʿAbd al-Ashhal, reported: The Messenger of Allah ﷺ passed by us while we were with a group of women. He greeted us and said: “Beware of ingratitude toward those who bestow favors upon you.” We asked: “O Messenger of Allah, what is ingratitude toward those who bestow favors?” He said: “One of you may remain unmarried for a long time in the house of her parents and grow older, then Allah, Mighty and Majestic, provides her with a husband and grants her through him wealth and children. Then she becomes angry on one occasion and says: ‘I have never seen any good from him at all.’”"]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":24},{"key":"ahmad","label":"مسند الإمام أحمد","number":27561,"n":27561,"lafz":true}],"full":1,"dr":1},{"num":6344,"demo":false,"sanad":"","matn":["عَنْ مُعَاذِ بْنِ جَبَلٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ تُؤْذِي امْرَأَةٌ زَوْجَهَا فِي الدُّنْيَا إِلاَّ قَالَتْ زَوْجَتُهُ مِنَ الْحُورِ الْعِينِ لاَ تُؤْذِيهِ قَاتَلَكِ اللَّهُ فَإِنَّمَا هُوَ عِنْدَكِ دَخِيلٌ يُوشِكُ أَنْ يُفَارِقَكِ إِلَيْنَا."],"takhrij":"حسن: رواه الترمذي (1174) وابن ماجة (2014) وأحمد (22101) كلهم من حديث إسماعيل بن عياش، عن بَحير بن سعد، عن خالد بن معدان، عن كثير بن مرة، عن معاذ بن جبل فذكره.","grade":"حسن","chapter_ar":"باب النهي عن إيذاءِ المرأةِ زوجَها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1174), who graded it Hasan, Ibn Majah (2014), and Ahmad (22101).","chapter_en":"The prohibition of a woman harming her husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":16,"content":{"translation":{"en":["Mu‘adh ibn Jabal said: the Messenger of Allah ﷺ said: “No woman harms her husband except that his wife from the women of Paradise says: ‘Do not harm him, may Allah fight you. He is only a temporary guest with you, and soon he will leave you and come to us.’”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1174,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2014},{"key":"ahmad","label":"مسند الإمام أحمد","number":22101,"n":22101}],"full":1,"dr":1},{"num":6345,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، عن النبي صلى الله عليه وسلم قال: إذا استأذنت امرأة أحدكم المسجد فلا يمنعها.","وزاد في رواية: فقال بلال بن عبد الله: والله لنمنعهنّ، قال: فأقبل عليه عبد الله فسبّه سبّاً سيئاً، ما سمعته سبّه مثله قط، وقال: أخبرُك عن رسول الله صلى الله عليه وسلم وتقول: والله لنمنعهنّ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5238)، ومسلم في الصلاة (134:442) كلاهما من طريق ابن عيينة، حدثنا الزهري، سمع سالماً يحدّث عن أبيه، فذكره.","grade":"متفق عليه","chapter_ar":"باب الإذن للنساء في الخروج إلى المسجد وقضاء حوائجهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5238) and Muslim (134:442), and the addition is in Muslim (135:442).","chapter_en":"Permission for women to go out to the mosque and to fulfill their needs","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":17,"content":{"translation":{"en":["Ibn ‘Umar reported from the Prophet ﷺ that he said: “If the wife of one of you asks permission to go to the mosque, he should not prevent her.” And in an added narration: Bilal ibn ‘Abd Allah said: By Allah, we will surely prevent them. So ‘Abd Allah turned to him and rebuked him harshly, with a rebuke the like of which I had never heard from him, and said: I inform you from the Messenger of Allah ﷺ and you say: By Allah, we will surely prevent them?"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5238,"lafz":true},{"key":"muslim","label":"مسلم","number":134},{"key":"muslim","label":"الزيادة في رواية مسلم","number":135}],"full":1,"dr":1},{"num":6346,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ خَرَجَتْ سَوْدَةُ بِنْتُ زَمْعَةَ لَيْلاً فَرَآهَا عُمَرُ فَعَرَفَهَا فَقَالَ إِنَّكِ وَاللَّهِ يَا سَوْدَةُ مَا تَخْفَيْنَ عَلَيْنَا، فَرَجَعَتْ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَتْ ذَلِكَ لَهُ، وَهْوَ فِي حُجْرَتِي يَتَعَشَّى، وَإِنَّ فِي يَدِهِ لَعَرْقًا، فَأُنْزِلَ عَلَيْهِ فَرُفِعَ عَنْهُ وَهُوَ يَقُولُ قَدْ أَذِنَ لَكُنَّ أَنْ تَخْرُجْنَ لِحَوَائِجِكُنَّ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5237) من طريق علي بن مُسهر- ومسلم في السلام (17:2170) من طريق أبي أسامة – كلاهما عن هشام بن عروة، عن أبيه، عن عائشة، فذكرته، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب الإذن للنساء في الخروج إلى المسجد وقضاء حوائجهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5237) and Muslim (2170/17). This is the wording of al-Bukhārī.","chapter_en":"Permission for women to go out to the mosque and to fulfill their needs","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":17,"content":{"translation":{"en":["ʿĀʾishah reported: Sawdah bint Zamʿah went out at night. ʿUmar saw her and recognized her, and said: “By Allah, O Sawdah, you cannot remain unrecognized by us.” She returned to the Prophet ﷺ and mentioned this to him while he was eating supper in my apartment, with a bone containing some meat still in his hand. Revelation came down upon him. When it had ended, he said: “Permission has been granted to you women to go out for your needs.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5237,"lafz":true},{"key":"muslim","label":"مسلم","number":2170},{"key":"muslim","label":"من طريق علي بن مسهر- ومسلم في السلام","number":17}],"full":1},{"num":6347,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ تُبَاشِرِ الْمَرْأَةُ الْمَرْأَةَ فَتَنْعَتَهَا لِزَوْجِهَا، كَأَنَّهُ يَنْظُرُ إِلَيْهَا."],"takhrij":"صحيح: رواه البخاري في النكاح (5240) عن محمد بن يوسف، حدثنا سفيان، عن منصور، عن أبي وائل، عن عبد الله بن مسعود فذكره ورواه أيضا (5241) من وجه آخر عن أبي وائل مثله.","grade":"صحيح","chapter_ar":"باب لا تباشر المرأة المرأة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5240).","chapter_en":"A woman must not closely expose another woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":18,"content":{"translation":{"en":["‘Abd Allah ibn Mas‘ud said: the Prophet ﷺ said: “A woman should not closely examine another woman and then describe her to her husband as though he were looking at her.”"]},"buhuth":{"en":["His saying, “describe her to her husband,” is because of the fear that the husband may become taken by that description, then divorce his wife or become infatuated with the woman being described."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5240,"lafz":true}],"full":1,"dr":1},{"num":6348,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تُبَاشِرِ الْمَرْأَةُ الْمَرْأَةَ، وَلَا الرَّجُلُ الرَّجُلَ."],"takhrij":"حسن: رواه أحمد (8318) والطبراني في الصغير (653) والطحاوي في مشكله (3258) كلهم من حديث أبي بكر، عن هشام، عن ابن سيرين، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب لا تباشر المرأة المرأة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (8318), al-Tabarani in al-Saghir (653), and al-Tahawi in Mushkil al-Athar (3258).","chapter_en":"A woman must not closely expose another woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":18,"content":{"translation":{"en":["Abu Hurayrah said: the Messenger of Allah ﷺ said: “A woman should not lie in close bodily contact with another woman, and a man should not lie in close bodily contact with another man.”"]}},"tuhfa":{},"refs":[{"key":"sh13068","label":"الطبراني في الصغير","number":653,"n":674},{"key":"sh22547","label":"الطحاوي في مشكل الآثار","number":3258,"n":3475},{"key":"ahmad","label":"مسند الإمام أحمد","number":8318,"n":8318,"lafz":true}],"full":1,"dr":1},{"num":6349,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يُبَاشِرِ الرَّجُلُ الرَّجُلَ، وَلا الْمَرْأَةُ الْمَرْأَةَ."],"takhrij":"صحيح: رواه الإمام أحمد (2773) والطبراني في الكبير (11728) والبزار – كشف الأستار- (2074) وابن حبان (5582) كلهم من حديث إسرائيل، عن سماك بن حرب، عن عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب لا تباشر المرأة المرأة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (2773), al-Tabarani in al-Kabir (11728), and al-Bazzar in Kashf al-Astar (2074).","chapter_en":"A woman must not closely expose another woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":18,"content":{"translation":{"en":["Ibn ‘Abbas said: the Messenger of Allah ﷺ said: “A man should not lie in close bodily contact with another man, and a woman should not lie in close bodily contact with another woman.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":2773,"lafz":true},{"key":"mujamkabir","label":"الطبراني في الكبير","number":11728},{"key":"sh12862","label":"البزار - كشف الأستار -","number":2074},{"key":"ibnhibban","label":"ابن حبان","number":5582}],"full":1,"dr":1},{"num":6350,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَنْهَى أَنْ يُبَاشِرَ الرَّجُلُ الرَّجُلَ فِي ثَوْبٍ وَاحِدٍ وَالْمَرْأَةُ الْمَرْأَةُ فِي ثَوْبٍ وَاحِدٍ."],"takhrij":"حسن: رواه الحاكم (4/287) من حديث عبد الرحمن بن أبي الزناد، عن موسى بن عقبة، عن أبي الزبير، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب لا تباشر المرأة المرأة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Hakim (4/287).","chapter_en":"A woman must not closely expose another woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":18,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: I heard the Messenger of Allah ﷺ forbid that a man closely join another man under one garment, and that a woman closely join another woman under one garment."]}},"tuhfa":{},"refs":[{"key":"hakim","label":"المستدرك على الصحيحين","number":7775,"n":7779,"lafz":true}],"full":1,"dr":1},{"num":6351,"demo":false,"sanad":"","matn":["عن أَبِي سَعِيدٍ الْخُدْرِيِّ عَنْ أَبِيهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ يَنْظُرُ الرَّجُلُ إِلَى عَوْرَةِ الرَّجُلِ وَلاَ الْمَرْأَةُ إِلَى عَوْرَةِ الْمَرْأَةِ وَلاَ يُفْضِي الرَّجُلُ إِلَى الرَّجُلِ فِي ثَوْبٍ وَاحِدٍ وَلاَ تُفْضِي الْمَرْأَةُ إِلَى الْمَرْأَةِ فِي الثَّوْبِ الْوَاحِدِ."],"takhrij":"صحيح: رواه مسلم في الحيض (338) عن أبي بكر بن أبي شيبة، حدثنا زيد بن الحُباب، عن الضحاك بن عثمان قال: أخبرني زيد بن أسلم، عن عبد الرحمن بن أبي سعيد، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب تحريم النظر إلى العورات","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (338).","chapter_en":"The prohibition of looking at the private parts","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":19,"content":{"translation":{"en":["Abu Sa‘id al-Khudri reported that the Messenger of Allah ﷺ said: “A man must not look at the private part of another man, and a woman must not look at the private part of another woman. A man must not lie closely with another man under one garment, and a woman must not lie closely with another woman under one garment.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":338,"lafz":true}],"full":1,"dr":1},{"num":6352,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ مِنْ أشرّ النَّاسِ يَوْمَ الْقِيَامَةِ، الرَّجُلَ يُفْضِي إِلَى امْرَأَتِهِ، وَتُفْضِي إِلَيْهِ ثُمَّ يَنْشُرُ سِرَّهَا.","وفي لفظ: إن من أعظم الأمانة عند الله يوم القيامة، الرجل يفضي إلى امرأته وتفضي إليه، ثم ينشر سرّها."],"takhrij":"حسن: رواه مسلم في النكاح (123:1437) عن أبي بكر بن أبي شيبة، حدثنا مروان بن معاوية، عن عمر بن حمزة العمري، حدّثنا عبد الرحمن بن سعد، قال: سمعت أبا سعيد الخدري يقول:فذكره.","grade":"حسن","chapter_ar":"باب تحريم إفشاء أسرار الجماع بين الزوجين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Muslim (123:1437).","chapter_en":"The prohibition of disclosing the secrets of intimacy between spouses","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":20,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: the Messenger of Allah ﷺ said: “Among the worst of people on the Day of Resurrection is a man who goes in unto his wife and she goes in unto him, then he spreads her secret.” And in another wording: “Among the greatest betrayals of trust before Allah on the Day of Resurrection is that a man goes in unto his wife and she goes in unto him, then he spreads her secret.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":123,"lafz":true}],"full":1,"dr":1},{"num":6353,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: أَلَا عَسَى أَحَدُكُمْ أَنْ يَخْلُوَ بِأَهْلِهِ يُغْلِقُ بَابًا، ثُمَّ يُرْخِي سِتْرًا، ثُمَّ يَقْضِي حَاجَتَهُ، ثُمَّ إِذَا خَرَجَ حَدَّثَ أَصْحَابَهُ بِذَلِكَ، أَلَا عَسَى إِحْدَاكُنَّ أَنْ تُغْلِقَ بَابَهَا، وَتُرْخِي سِتْرَهَا، فَإِذَا قَضَيْتَ حَاجَتَهَا، حَدَّثَتْ صَوَاحِبَهَا، فَقَالَتِ امْرَأَةٌ سَفْعَاءُ الْخَدَّيْنِ: وَاللَّهِ يَا رَسُولَ اللَّهِ، إِنَّهُنَّ لَيَفْعَلْنَ، وَإِنَّهُمْ لَيَفْعَلُونَ، قَالَ: فَلا تَفْعَلُوا، فَإِنَّهُ مِثْلُ ذَلِكَ مِثْلُ الشَّيْطَانِ لَقِيَ شَيْطَانَةً عَلَى قَارِعَةِ الطَّرِيقِ فَقَضَى حَاجَتَهُ مِنْهَا، ثُمَّ انْصَرَفَ وَتَرَكَهَا."],"takhrij":"حسن: رواه البزار – كشف الأستار (1450) عن روح بن حاتم أبي غسّان، ثنا مهدي بن عيسى، ثنا عباد بن عباد المهلبي، ثنا سعيد بن يزيد أبو مسلمة، عن أبي نضرة، عن أبي سعيد فذكره.","grade":"حسن","chapter_ar":"باب تحريم إفشاء أسرار الجماع بين الزوجين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzar in Kashf al-Astar (1450).","chapter_en":"The prohibition of disclosing the secrets of intimacy between spouses","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":20,"content":{"translation":{"en":["Abu Sa‘id narrated from the Prophet ﷺ that he said: “Perhaps one of you is alone with his wife, closes the door, lets down the curtain, then fulfills his need, and when he comes out he tells his companions about it. And perhaps one of you women closes her door and lets down her curtain, then when she fulfills her need, she tells her female companions.” A dark-cheeked woman said: By Allah, O Messenger of Allah, the women do that, and the men do that too. He said: “Then do not do that, for the likeness of that is the likeness of a devil who met a she-devil on the roadside, fulfilled his need with her, then went away and left her.”"]}},"tuhfa":{},"refs":[{"key":"sh12862","label":"البزار - كشف الأستار","number":1450,"lafz":true}],"full":1,"dr":1},{"num":6354,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ -فِي حَدِيثِ طَوِيلٍ كَمَا ذُكِر-، وَجَاءَ فِيهِ:  هَلْ فِيكُمْ رجـل إِذَا أَتَى أَهْلَهُ أَغْلَقَ بَابَهُ، وَأَرْخَى سِتْرَهُ، ثُمَّ يَخْرُجُ فَيُحَدِّثُ فَيَقُولُ: فَعَلْتُ بِأَهْلِي كَذَا، وَفَعَلْتُ بِأَهْلِي كَذَا فَسَكَتُوا، فَأَقْبَلَ عَلَى النِّسَاءِ فَقَالَ: هَلْ مِنْكُنَّ تُحَدِّثُ، فَجَثَتْ فَتَاةٌ كَعَابٌ عَلَى إِحْدَى رُكْبَتَيْهَا، وَتَطَالَتْ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيَرَاهَا وَيَسْمَعَ كَلَامَهَا، فَقَالَتْ: إِي وَاللهِ إِنَّهُمْ ليتحدثون، وَإِنَّهُنَّ لَيُحَدِّثْنَ، قَالَ: فَهَلْ تَدْرُونَ مَا مَثَلُ مَنْ فَعَلَ ذَلِكَ؟ إِنَّ مَثَلَ ذَلِكَ، مَثَلُ شَيْطَانٍ وَشَيْطَانَةٍ لَقِيَ أَحَدُهُمَا صَاحِبَهُ بِالسِّكَّةِ، فَقَضَى حَاجَتَهُ مِنْهَا وَالنَّاسُ يَنْظُرُونَ إِلَيْهِ."],"takhrij":"حسن: رواه أحمد (10977) وأبو داود (2174) والترمذي (2787) والنسائي (5118،5117) وابن السني (615) كلهم من حديث سعيد الجريري، عن أبي نضرة، عن الطفاوي، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب تحريم إفشاء أسرار الجماع بين الزوجين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (10977), Abu Dawud (2174), and al-Khara’iti in Masawi’ al-Akhlaq (430).","chapter_en":"The prohibition of disclosing the secrets of intimacy between spouses","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":20,"content":{"translation":{"en":["Abu Hurayrah narrated — in a long hadith as previously mentioned — and in it there came: “Is there among you any man who, when he goes to his wife, closes his door and lets down his curtain, then goes out and says: I did such-and-such with my wife, and I did such-and-such with my wife?” They remained silent. Then he turned to the women and said: “Is there any among you who speaks of such things?” Then a young full-breasted girl knelt on one of her knees and stretched herself up so that the Messenger of Allah ﷺ could see her and hear her words. She said: Yes, by Allah, the men certainly speak of it, and the women certainly speak of it too. He said: “Do you know what the likeness of the one who does that is? The likeness of that is like a male devil and a female devil who met one another in the street, then he fulfilled his desire with her while the people were watching.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2174},{"key":"rb393","label":"الخرائطي في مساوئ الأخلاق","number":430},{"key":"ahmad","label":"مسند الإمام أحمد","number":10977,"n":10977,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":2787},{"key":"nasai","label":"النسائي","number":5118},{"key":"nasai","label":"النسائي","number":5117},{"key":"sh13132","label":"ابن السني","number":615}],"full":1,"dr":1},{"num":6355,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عمرو، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا تَزَوَّجَ أَحَدُكُمُ امْرَأَةً، أَوِ اشْتَرَى خَادِمًا فَلْيَقُلِ: اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَخَيْرَ مَا جَبَلْتَها عَلَيْهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَمِنْ شَرِّ مَا جَبَلْتَها عَلَيْهِ، وَإِذَا اشْتَرَى بَعِيرًا فَلْيَأْخُذْ بِذِرْوَةِ سَنانه وَلْيَقُلْ مِثْلَ ذَلِكَ.","وفي لفظ: إذا أفاد أحدُكم امرأةً، أو خادماً، أو دابّةً، فليأخذ بناصيتها، وليقُلْ: فذكر الحديث."],"takhrij":"حسن: رواه أبو داود (2160) وابن ماجة (1918) وابن السني (100) والحاكم (2/185) والبيهقي (7/148) كلهم من حديث محمد بن عجلان، عن عمرو بن شعيب، بإسناده مثله.","grade":"حسن","chapter_ar":"باب ما يقول الرجل إذا دخل على عروسه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2160), Ibn Majah (1918), Ibn al-Sunni (100), and al-Hakim (2/185).","chapter_en":"What a man says when he enters upon his bride","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":21,"content":{"translation":{"en":["‘Abd Allah ibn ‘Amr narrated from the Prophet ﷺ that he said: “When one of you marries a woman or buys a servant, let him say: O Allah, I ask You for her good and the good upon which You created her, and I seek refuge in You from her evil and the evil upon which You created her. And if he buys a camel, let him take hold of the top of its hump and say the same.” And in another wording: “When one of you acquires a wife, a servant, or a riding beast, let him take hold of its forelock,” then let him say the supplication just mentioned."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2160,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":1918},{"key":"sh13132","label":"ابن السني","number":100},{"key":"hakim","label":"الحاكم","number":185}],"full":1,"dr":1},{"num":6356,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَا لَوْ أَنَّ أَحَدَهُمْ يَقُولُ حِينَ يَأْتِي أَهْلَهُ بِاسْمِ اللَّهِ، اللَّهُمَّ جَنِّبْنِي الشَّيْطَانَ، وَجَنِّبِ الشَّيْطَانَ مَا رَزَقْتَنَا، ثُمَّ قُدِّرَ بَيْنَهُمَا فِي ذَلِكَ، أَوْ قُضِيَ وَلَدٌ، لَمْ يَضُرَّهُ شَيْطَانٌ أَبَدًا.","وفي لفظ: لو أن أحدهم إذا أراد أن يأتي أهله..."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5165)، ومسلم في النكاح (116:1434) كلاهما من طريق منصور، عن سالم بن أبي الجعد، عن كُريب، عن ابن عباس، فذكره.","grade":"متفق عليه","chapter_ar":"باب استحباب التسمية عند الجماع","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5165) and Muslim (116:1434). The first wording is from al-Bukhari, and the second from Muslim.","chapter_en":"The recommendation to mention Allah’s name before intercourse","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":22,"content":{"translation":{"en":["Ibn ‘Abbas said: the Prophet ﷺ said: “If one of you were to say when he goes to his wife: In the name of Allah. O Allah, keep Satan away from me, and keep Satan away from what You provide us, then if it is decreed that a child be conceived between them in that act, Satan will never harm him.” And in another wording: “If one of them, when he intends to go to his wife…”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5165,"lafz":true},{"key":"muslim","label":"مسلم","number":116}],"full":1,"dr":1},{"num":6357,"demo":false,"sanad":"","matn":["عَنْ بَهْزِ بْنِ حَكِيمٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ قُلْتُ يَا رَسُولَ اللَّهِ عَوْرَاتُنَا مَا نَأْتِي مِنْهَا وَمَا نَذَرُ قَالَ احْفَظْ عَوْرَتَكَ إِلاَّ مِنْ زَوْجَتِكَ أَوْ مَا مَلَكَتْ يَمِينُكَ. قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِذَا كَانَ الْقَوْمُ بَعْضُهُمْ فِي بَعْضٍ قَالَ إِنِ اسْتَطَعْتَ أَنْ لاَ يَرَيَنَّهَا أَحَدٌ فَلاَ يَرَيَنَّهَا. قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِذَا كَانَ أَحَدُنَا خَالِيًا قَالَ اللَّهُ أَحَقُّ أَنْ يُسْتَحْيَا مِنْهُ مِنَ النَّاسِ."],"takhrij":"حسن: رواه أبو داود (4017) والترمذي (2794،2769) وابن ماجة (1920) والحاكم (4/179-180) والبيهقي (1/199) كلهم من هذا الوجه. وإسناده حسن من أجل بهز بن حكيم وأبيه حكيم بن معاوية فإنهما صدوقان.","grade":"حسن","chapter_ar":"باب استحباب التستر عند الجماع","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4017), al-Tirmidhi (2769, 2794), Ibn Majah (1920), and al-Hakim (7358).","chapter_en":"The recommendation of concealment during intercourse","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":23,"content":{"translation":{"en":["Bahz ibn Hakim, from his father, from his grandfather, said: I said: O Messenger of Allah, regarding our private parts, what may we uncover and what must we conceal? He said: “Guard your private part except from your wife or from what your right hand possesses.” I said: O Messenger of Allah, what if the people are among one another? He said: “If you are able that no one should see it, then let no one see it.” I said: O Messenger of Allah, what if one of us is alone? He said: “Then Allah has more right that one should be shy before Him than before people.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4017,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":2769,"n":2794},{"key":"ibnmajah","label":"ابن ماجه","number":1920},{"key":"hakim","label":"المستدرك على الصحيحين","number":7358,"n":7361},{"key":"tirmidhi","label":"الترمذي","number":2794}],"full":1,"dr":1,"rep":[1496,12870]},{"num":6358,"demo":false,"sanad":"","matn":["عن جابر قال: كانت اليهود تقول: إذا أتى الرجلُ امرأته من دُبُرها في قُبلها، كان الولد أحول فنزلت: ﴿نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ﴾ [سورة البقرة: 223] "],"takhrij":"متفق عليه: رواه البخاري في التفسير (4528)، ومسلم في النكاح (117:1435) كلاهما من طريق سفيان (هو الثوري)، عن ابن المنكدر، سمع جابراً يقول (فذكره).","grade":"متفق عليه","chapter_ar":"باب إتيان المرأة في قبلها كيف ما شاء، إذا تجنب الإتيان في الدبر","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari in al-Tafsir (4528) and Muslim in al-Nikah (117:1435), both by the route of Sufyan — that is, al-Thawri — from Ibn al-Munkadir, who heard Jabir say it.","chapter_en":"Going to one’s wife in her front as one wishes, so long as anal intercourse is avoided","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":24,"content":{"translation":{"en":["Jabir said: The Jews used to say: If a man comes to his wife from behind while entering in her front, the child will be cross-eyed. So this verse was revealed: “Your wives are a place of cultivation for you, so go to your place of cultivation however you wish.”"]},"intro":{"ar":["قال الله تعالى: (نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ) [البقرة: ٢٢٣]"],"en":["Allah Most High said: “Your wives are a place of cultivation for you, so go to your place of cultivation however you wish.” [al-Baqarah: 223]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري في التفسير","number":4528,"lafz":true},{"key":"muslim","label":"مسلم في النكاح","number":117}],"full":1},{"num":6359,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: قَالَتِ الْيَهُودُ: إِنَّ الرَّجُلَ إِذَا أَتَى امْرَأَتَهُ وَهِيَ مُجَبِّيَةٌ جَاءَ وَلَدُهُ أَحْوَلَ، فَنَزَلَتْ: ﴿نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ﴾ [البقرة: ٢٢٣] إِنْ شَاءَ مُجَبِّيَةً وَإِنْ شَاءَ غَيْرَ مُجَبِّيَةٍ إِذَا كَانَ فِي صِمَامٍ وَاحِدٍ."],"takhrij":"صحيح: رواه مسلم في النكاح (119:1435) وابن حبان في صحيحه (4166) كلاهما من حديث وهب بن جرير، قال: حدثنا أبي، قال: سمعت النعمان بن راشد، يحدث عن الزهري، عن محمد بن المنكدر، عن جابر فذكره واللفظ لابن حبان. وأما مسلم فلم يذكر لفظ الحديث كاملا، وإنما أحال على السابق وقال: وزاد في حديث النعمان عن الزهري: \"وإن شاء مُجبّية وإن شاء غير مجَبّية غير أن ذلك في صمام واحد\".","grade":"صحيح","chapter_ar":"باب إتيان المرأة في قبلها كيف ما شاء، إذا تجنب الإتيان في الدبر","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (119:1435) and Ibn Hibban in his Sahih (4166), and the wording is that of Ibn Hibban.","chapter_en":"Going to one’s wife in her front as one wishes, so long as anal intercourse is avoided","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":24,"content":{"translation":{"en":["Jabir said: The Jews said: If a man comes to his wife while she is bent forward, the child will come out cross-eyed. So the verse was revealed: “Your wives are a place of cultivation for you, so go to your place of cultivation however you wish” [al-Baqarah: 223] — whether bent forward or otherwise, so long as it is in one opening."]},"buhuth":{"en":["His saying, “mujabbiyah,” means bent over on her face, resembling the posture of prostration. And his saying, “one opening,” means one orifice, namely the front passage."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":119,"lafz":true},{"key":"ibnhibban","label":"ابن حبان في صحيحه","number":4166},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4290,"n":4286}],"full":1,"dr":1},{"num":6360,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ جَاءَ عُمَرُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ يَا رَسُولَ اللَّهِ هَلَكْتُ قَالَ وَمَا أَهْلَكَكَ. قَالَ حَوَّلْتُ رَحْلِي اللَّيْلَةَ. قَالَ فَلَمْ يَرُدَّ عَلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَيْئًا قَالَ فَأَنْزَلَ اللَّهُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَذِهِ الآيَةَ: ﴿نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ﴾ [سورة البقرة: 223] ) أَقْبِلْ وَأَدْبِرْ وَاتَّقِ الدُّبُرَ وَالْحِيضَةَ."],"takhrij":"حسن: رواه الترمذي (2980) وأحمد (2703) والبيهقي (7/197) وصحّحه ابن حبان (4202) كلهم من طريق يعقوب بن عبد الله القمي، قال: حدثنا جعفر بن المغيرة، عن سعيد بن جبير، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب إتيان المرأة في قبلها كيف ما شاء، إذا تجنب الإتيان في الدبر","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (2980), Ahmad (2703), al-Bayhaqi (7/197), and authenticated by Ibn Hibban (4202).","chapter_en":"Going to one’s wife in her front as one wishes, so long as anal intercourse is avoided","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":24,"content":{"translation":{"en":["Ibn ‘Abbas said: ‘Umar came to the Messenger of Allah ﷺ and said: O Messenger of Allah, I am ruined. He said: “What has ruined you?” He said: I changed my position on my mount last night. He said: The Messenger of Allah ﷺ did not answer him with anything. Then this verse was revealed to the Messenger of Allah ﷺ: “Your wives are a place of cultivation for you, so go to your place of cultivation however you wish” — from the front or from behind, but avoid the anus and menstruation."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":2980,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":7},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":4202},{"key":"ahmad","label":"مسند الإمام أحمد","number":2703,"n":2703},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4291,"n":4287}],"full":1,"dr":1,"rep":[12003]},{"num":6361,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ إِنَّ ابْنَ عُمَرَ - وَاللَّهُ يَغْفِرُ لَهُ - أَوْهَمَ إِنَّمَا كَانَ هَذَا الْحَىُّ مِنَ الأَنْصَارِ - وَهُمْ أَهْلُ وَثَنٍ - مَعَ هَذَا الْحَىِّ مِنْ يَهُودَ - وَهُمْ أَهْلُ كِتَابٍ - وَكَانُوا يَرَوْنَ لَهُمْ فَضْلاً عَلَيْهِمْ فِي الْعِلْمِ فَكَانُوا يَقْتَدُونَ بِكَثِيرٍ مِنْ فِعْلِهِمْ وَكَانَ مِنْ أَمْرِ أَهْلِ الْكِتَابِ أَنْ لاَ يَأْتُوا النِّسَاءَ إِلاَّ عَلَى حَرْفٍ وَذَلِكَ أَسْتَرُ مَا تَكُونُ الْمَرْأَةُ فَكَانَ هَذَا الْحَىُّ مِنَ الأَنْصَارِ قَدْ أَخَذُوا بِذَلِكَ مِنْ فِعْلِهِمْ وَكَانَ هَذَا الْحَىُّ مِنْ قُرَيْشٍ يَشْرَحُونَ النِّسَاءَ شَرْحًا مُنْكَرًا وَيَتَلَذَّذُونَ مِنْهُنَّ مُقْبِلاَتٍ وَمُدْبِرَاتٍ وَمُسْتَلْقِيَاتٍ فَلَمَّا قَدِمَ الْمُهَاجِرُونَ الْمَدِينَةَ تَزَوَّجَ رَجُلٌ مِنْهُمُ امْرَأَةً مِنَ الأَنْصَارِ فَذَهَبَ يَصْنَعُ بِهَا ذَلِكَ فَأَنْكَرَتْهُ عَلَيْهِ وَقَالَتْ إِنَّمَا كُنَّا نُؤْتَى عَلَى حَرْفٍ فَاصْنَعْ ذَلِكَ وَإِلاَّ فَاجْتَنِبْنِي حَتَّى شَرِيَ أَمْرُهُمَا فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ﴿نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ﴾ [سورة البقرة: 223] } أَىْ مُقْبِلاَتٍ وَمُدْبِرَاتٍ وَمُسْتَلْقِيَاتٍ يَعْنِي بِذَلِكَ مَوْضِعَ الْوَلَدِ."],"takhrij":"حسن: رواه أبو داود (2164) عن عبد العزيز بن يحيى أبي الأصبغ حدثني محمد – يعني ابن سلمة – عن محمد بن إسحاق، عن أبان بن صالح، عن مجاهد، عن ابن عباس قال:فذكره.","grade":"حسن","chapter_ar":"باب إتيان المرأة في قبلها كيف ما شاء، إذا تجنب الإتيان في الدبر","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (2164).","chapter_en":"Going to one’s wife in her front as one wishes, so long as anal intercourse is avoided","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":24,"content":{"translation":{"en":["Ibn ʿAbbās reported: Ibn ʿUmar—may Allah forgive him—was mistaken. This group of the Anṣār had formerly been idol worshippers and lived alongside a group of Jews who were People of the Book. The Anṣār regarded them as superior to themselves in knowledge and therefore followed many of their practices. Among the practices of the People of the Book was that they would approach women in only one position, considering that to be the most concealing position for the woman. The Anṣār had adopted this practice from them. The people of Quraysh, however, used to engage with women in a variety of positions, enjoying them facing them, from behind, and while lying down. When the Emigrants came to Madinah, one of them married a woman from the Anṣār and wished to approach her in that way. She objected and said: “We were approached only in one position. Either do that or keep away from me.” Their dispute became serious and intensified, and the matter reached the Messenger of Allah ﷺ. Allah, Mighty and Majestic, then revealed: “Your wives are a place of cultivation for you, so approach your place of cultivation however you wish.”  [al-Baqarah: 223] Meaning: facing them, from behind, or while they are lying down, provided that it is in the place from which children are born."]},"buhuth":{"en":["The phrase “their matter became serious” means that their dispute became grave and intensified."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2164,"lafz":true}],"full":1,"dr":1},{"num":6362,"demo":false,"sanad":"","matn":["عن خزيمة بن ثابت قال: إن سائلا سأل رسول الله صلى الله عليه وسلم عن إتيان النساء في أدبارهن. فقال رسول الله صلى الله عليه وسلم: حلال ثم دعاه، أو أمر به، فدُعي فقال: كيف قلت في أي الخربتين، أو في أي الخرزتين، أو في الخصفين؟ أ من دبرها في قبلها فنعم، أم من دبرها في دبرها فلا، إن الله لا يستحي من الحق، لا تأتوا النساء في أدبارهن."],"takhrij":"صحيح: رواه الشافعي في الأم (5/94) قال: أخبرنا عمي محمد بن علي بن شافع، عن عبد الله بن علي بن السائب، عن عمرو بن أحيحة أو ابن فلان ابن أحيحة بن فلان الأنصار. قال: قال محمد بن علي وكان ثقة – عن خزيمة بن ثابت فذكره.","grade":"صحيح","chapter_ar":"باب إتيان المرأة في قبلها كيف ما شاء، إذا تجنب الإتيان في الدبر","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Shafi‘i in al-Umm (5/94).","chapter_en":"Going to one’s wife in her front as one wishes, so long as anal intercourse is avoided","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":24,"content":{"translation":{"en":["Khuzaymah ibn Thabit said: A questioner asked the Messenger of Allah ﷺ about going to women in their backsides. The Messenger of Allah ﷺ said: “Lawful.” Then he called him back — or ordered that he be called — and when he was brought, he said: “How did you say it? In which of the two openings? Or which of the two parts? Or which of the two places? If from her back into her front, then yes. But if from her back into her back, then no. Indeed Allah is not shy of the truth. Do not go to women in their backsides.”"]}},"tuhfa":{},"refs":[{"key":"sh1655","label":"الشافعي في الأم","number":5,"lafz":true}],"full":1,"dr":1},{"num":6363,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ يَنْظُرُ اللَّهُ إِلَى رَجُلٍ جَامَعَ امْرَأَتَهُ فِي دُبُرِهَا."],"takhrij":"حسن: رواه أبو داود (2162) وابن ماجه (1923) وأحمد (7684) وعبد الرزاق (20952) والبيهقي (7/198) كلهم من حديث سهيل بن أبي صالح، عن الحارث بن مُخلّد، عن أبي هريرة فذكره. ولفظ أبي داود: «مَلْعونٌ مَنْ أتى امرأتَه في دُبُرِها»","grade":"حسن","chapter_ar":"باب إتيان المرأة في قبلها كيف ما شاء، إذا تجنب الإتيان في الدبر","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2162), Ibn Majah (1923), and Ahmad (7684).","chapter_en":"Going to one’s wife in her front as one wishes, so long as anal intercourse is avoided","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":24,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ: “Allah will not look at a man who has intercourse with his wife in her anus.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2162,"lafz":true,"n":2033},{"key":"ibnmajah","label":"ابن ماجه","number":1923},{"key":"ahmad","label":"مسند الإمام أحمد","number":7684,"n":7682},{"key":"abdrazzaq","label":"عبد الرزاق","number":20952}],"full":1,"dr":1},{"num":6364,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ يَنْظُرُ اللَّهُ إِلَى رَجُلٍ أَتَى رَجُلاً أَوِ امْرَأَةً فِي الدُّبُرِ."],"takhrij":"حسن: رواه الترمذي (1165) وأبو بكر بن أبي شيبة (4/251-252) وصحّحه ابن حبان (4418، 4204 ،4203) وابن الجارود (729) كلهم من حديث أبي خالد الأحمر، عن الضحاك بن عثمان، عن مخرمة بن سليمان، عن كُريب، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب إتيان المرأة في قبلها كيف ما شاء، إذا تجنب الإتيان في الدبر","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1165), Abu Bakr ibn Abi Shaybah (4/251–252), and authenticated by Ibn Hibban (4418).","chapter_en":"Going to one’s wife in her front as one wishes, so long as anal intercourse is avoided","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":24,"content":{"translation":{"en":["‘Abd Allah ibn ‘Abbas said: the Messenger of Allah ﷺ said: “Allah will not look at a man who goes to a man, or to a woman, in the anus.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1165,"lafz":true},{"key":"sh9944","label":"أبو بكر بن أبي شيبة","number":4},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":4418},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2922,"n":2919},{"key":"ibnhibban","label":"ابن حبان","number":4204},{"key":"ibnhibban","label":"ابن حبان","number":4203,"n":2919},{"key":"sh13071","label":"ابن الجارود","number":729,"n":758}],"full":1,"dr":1},{"num":6365,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ مَحَاشِّ النِّسَاءِ."],"takhrij":"حسن: رواه الطبراني في الأوسط –مجمع البحرين (2308) عن محمد بن عيسى بن السكن، ثنا علي بن بحر، عن ابن أبي فُديك، عن الضحاك بن عثمان، عن محمد بن المنكدر، عن جابر بن عبد الله قال: فذكره.","grade":"حسن","chapter_ar":"باب إتيان المرأة في قبلها كيف ما شاء، إذا تجنب الإتيان في الدبر","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Awsat — Majma‘ al-Bahrayn (2308).","chapter_en":"Going to one’s wife in her front as one wishes, so long as anal intercourse is avoided","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":24,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah reported that the Prophet ﷺ forbade approaching the buttocks of women."]}},"tuhfa":{},"refs":[{"key":"sh1352","label":"الطبراني في الأوسط - مجمع البحرين","number":2308,"lafz":true},{"key":"sh28171","label":"الطبراني في الاوسط –مجمع البحرين","number":2308}],"full":1,"dr":1},{"num":6366,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَعَنَ اللَّهُ الَّذِينَ يَأْتُونَ النِّسَاءَ فِي مَحَاشِّهِنَّ."],"takhrij":"حسن: رواه الطبراني في الأوسط –مجمع البحرين (2309) من طريق عبد الصمد بن الفضل، عن عبد الله بن وهب، أخبرني ابنُ لهعية، عن مِشرح بن هاعان، عن عقبة بن عامر الجهني قال: فذكره.","grade":"حسن","chapter_ar":"باب إتيان المرأة في قبلها كيف ما شاء، إذا تجنب الإتيان في الدبر","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Awsaṭ — Majmaʿ al-Baḥrayn (2309).","chapter_en":"Going to one’s wife in her front as one wishes, so long as anal intercourse is avoided","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":24,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir al-Juhanī reported that the Messenger of Allah ﷺ said: “May Allah curse those who have intercourse with women in their anuses.”"]},"buhuth":{"en":["Ibn al-Qayyim said in al-Ṭibb al-Nabawī (p. 313):","“As for intercourse through the anus, it was never made permissible upon the tongue of any prophet. Whoever attributes to some of the early Muslims the view that intercourse with one’s wife through the anus is permissible has wrongly attributed that view to them.”","He also said:","“If Allah prohibited intercourse in the vagina because of temporary harm, then what should be thought of a place that is inherently a place of constant harm, in addition to the further corruption of exposing oneself to the cessation of offspring?”"]}},"tuhfa":{},"refs":[{"key":"sh1352","label":"الطبراني في الأوسط - مجمع البحرين","number":2309,"lafz":true},{"key":"sh28171","label":"الطبراني في الاوسط –مجمع البحرين","number":2309}],"full":1,"dr":1},{"num":6367,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ كَانَتْ إِحْدَانَا إِذَا كَانَتْ حَائِضًا، فَأَرَادَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُبَاشِرَهَا، أَمَرَهَا أَنْ تَتَّزِرَ فِي فَوْرِ حَيْضَتِهَا ثُمَّ يُبَاشِرُهَا. قَالَتْ وَأَيُّكُمْ يَمْلِكُ إِرْبَهُ كَمَا كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمْلِكُ إِرْبَهُ."],"takhrij":"متفق عليه: رواه البخاري في الحيض (302) ومسلم في الحيض (293) كلاهما من طريق علي بن مسهرن قال: أخبرنا أبو إسحاق الشيباني، عن عبدالرحمن بن الأسود، عن أبيه، عن عائشة، فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في مباشرة الحائض دون الجماع","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (302) and Muslim (293).","chapter_en":"What has been reported about intimacy with a menstruating wife short of intercourse","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":25,"content":{"translation":{"en":["‘A’ishah said: When one of us was menstruating and the Messenger of Allah ﷺ wanted to enjoy her, he would command her to wrap a waistcloth around herself at the beginning of her menstruation, then he would enjoy her. She said: Which of you can control his desire as the Messenger of Allah ﷺ controlled his desire?"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":302,"lafz":true},{"key":"muslim","label":"مسلم","number":293,"n":680}],"full":1,"rep":[1521]},{"num":6368,"demo":false,"sanad":"","matn":["عن مَيْمُونَةَ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَرَادَ أَنْ يُبَاشِرَ امْرَأَةً مِنْ نِسَائِهِ أَمَرَهَا فَاتَّزَرَتْ وَهْىَ حَائِضٌ."],"takhrij":"متفق عليه: رواه البخاري في الحيض (303) ومسلم في الحيض (294) كلاهما من طريق الشيباني، عن عبدالله بن شداد، قال: سمعت ميمونة، قالت: فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في مباشرة الحائض دون الجماع","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (303) and Muslim (294).","chapter_en":"What has been reported about intimacy with a menstruating wife short of intercourse","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":25,"content":{"translation":{"en":["Maymunah said: When the Messenger of Allah ﷺ wished to enjoy one of his wives, he would command her to wrap herself in a waistcloth while she was menstruating."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":303,"lafz":true},{"key":"muslim","label":"مسلم","number":294}],"full":1,"rep":[1522]},{"num":6369,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ الْيَهُودَ، كَانُوا إِذَا حَاضَتِ الْمَرْأَةُ فِيهِمْ لَمْ يُؤَاكِلُوهَا وَلَمْ يُجَامِعُوهُنَّ فِي الْبُيُوتِ فَسَأَلَ أَصْحَابُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَنْزَلَ اللَّهُ تَعَالَى ﴿وَيَسْأَلُونَكَ عَنِ الْمَحِيضِ قُلْ هُوَ أَذًى فَاعْتَزِلُوا النِّسَاءَ فِي الْمَحِيضِ} إِلَى﴾ [سورة البقرة: 222] آخِرِ الآيَةِ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اصْنَعُوا كُلَّ شَىْءٍ إِلاَّ النِّكَاحَ. فَبَلَغَ ذَلِكَ الْيَهُودَ فَقَالُوا مَا يُرِيدُ هَذَا الرَّجُلُ أَنْ يَدَعَ مِنْ أَمْرِنَا شَيْئًا إِلاَّ خَالَفَنَا فِيهِ فَجَاءَ أُسَيْدُ بْنُ حُضَيْرٍ وَعَبَّادُ بْنُ بِشْرٍ فَقَالاَ يَا رَسُولَ اللَّهِ إِنَّ الْيَهُودَ تَقُولُ كَذَا وَكَذَا. فَلاَ نُجَامِعُهُنَّ فَتَغَيَّرَ وَجْهُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى ظَنَنَّا أَنْ قَدْ وَجَدَ عَلَيْهِمَا فَخَرَجَا فَاسْتَقْبَلَهُمَا هَدِيَّةٌ مِنْ لَبَنٍ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَرْسَلَ فِي آثَارِهِمَا فَسَقَاهُمَا فَعَرَفَا أَنْ لَمْ يَجِدْ عَلَيْهِمَا."],"takhrij":"صحيح: رواه مسلم في الحيض (302) عن زهير بن حرب، حدثنا عبدالرحمن بن مهدي، حدَّثنا حمَّاد بن سلمة، حدثنا ثابت، عن أنسٍ، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في مباشرة الحائض دون الجماع","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (302).","chapter_en":"What has been reported about intimacy with a menstruating wife short of intercourse","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":25,"content":{"translation":{"en":["Anas said: The Jews, when a woman among them menstruated, would not eat with her and would not live with her in the houses. So the Companions of the Prophet ﷺ asked the Prophet ﷺ, and Allah Most High revealed: “And they ask you about menstruation. Say: It is harm, so keep away from women during menstruation” to the end of the verse [al-Baqarah: 222]. So the Messenger of Allah ﷺ said: “Do everything except intercourse.” That reached the Jews, and they said: This man does not want to leave anything from our affairs except that he opposes us in it. Then Usayd ibn Hudayr and ‘Abbad ibn Bishr came and said: O Messenger of Allah, the Jews say such-and-such; should we then have intercourse with them? The face of the Messenger of Allah ﷺ changed until we thought that he was angry with them. Then they went out, and a gift of milk for the Prophet ﷺ met them, so he sent after them and gave them drink, and they knew that he had not been angry with them."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":302,"lafz":true}],"full":1,"dr":1},{"num":6370,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مُحَيْرِيزٍ، أَنَّهُ قَالَ دَخَلْتُ الْمَسْجِدَ فَرَأَيْتُ أَبَا سَعِيدٍ الْخُدْرِيَّ فَجَلَسْتُ إِلَيْهِ فَسَأَلْتُهُ عَنِ الْعَزْلِ،، قَالَ أَبُو سَعِيدٍ خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ بَنِي الْمُصْطَلِقِ، فَأَصَبْنَا سَبْيًا مِنْ سَبْىِ الْعَرَبِ، فَاشْتَهَيْنَا النِّسَاءَ وَاشْتَدَّتْ عَلَيْنَا الْعُزْبَةُ، وَأَحْبَبْنَا الْعَزْلَ، فَأَرَدْنَا أَنْ نَعْزِلَ، وَقُلْنَا نَعْزِلُ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ أَظْهُرِنَا قَبْلَ أَنْ نَسْأَلَهُ فَسَأَلْنَاهُ عَنْ ذَلِكَ فَقَالَ مَا عَلَيْكُمْ أَنْ لاَ تَفْعَلُوا، مَا مِنْ نَسَمَةٍ كَائِنَةٍ إِلَى يَوْمِ الْقِيَامَةِ إِلاَّ وَهْىَ كَائِنَةٌ."],"takhrij":"متفق عليه: رواه مالك في الطلاق (95)، عن ربيعة بن عبد الرحمن، عن محمد بن يحيى بن حبان، عن ابن محيريز، فذكره. ورواه البخاري في العتق (2542) عن عبد الله بن يوسف، عن مالك بإسناده.","grade":"متفق عليه","chapter_ar":"باب ما جاء في العزل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (95), al-Bukhari (2542), and Muslim (125:1438).","chapter_en":"What has been reported concerning withdrawal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":27,"content":{"translation":{"en":["Ibn Muhayriz said: I entered the mosque and saw Abu Sa‘id al-Khudri, so I sat with him and asked him about withdrawal. He said: We went out with the Messenger of Allah ﷺ on the expedition of Banu al-Mustaliq, and we obtained female captives from the Arab captives. We desired women, celibacy had become hard on us, and we wanted ransom money, so we intended to practice withdrawal. We said: Shall we practice withdrawal while the Messenger of Allah ﷺ is among us before asking him? So we asked him about that, and he said: “There is no blame upon you if you do not do it. There is no soul that will exist until the Day of Resurrection except that it will surely come into existence.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":95},{"key":"bukhari","label":"البخاري","number":2542,"lafz":true},{"key":"muslim","label":"مسلم","number":125}],"full":1,"dr":1,"rep":[8897]},{"num":6371,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ أَصَبْنَا سَبْيًا فَكُنَّا نَعْزِلُ فَسَأَلْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ أَوَإِنَّكُمْ لَتَفْعَلُونَ قَالَهَا ثَلاَثًا مَا مِنْ نَسَمَةٍ كَائِنَةٍ إِلَى يَوْمِ الْقِيَامَةِ إِلاَّ هِيَ كَائِنَةٌ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5210)، ومسلم في النكاح (127:1438) كلاهما عن عبد الله بن محمد، حدثنا جويرية، عن مالك، عن الزهري، عن ابن مُحيريز، عن أبي سعيد الخدري، قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في العزل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5210) and Muslim (1438:127).","chapter_en":"What has been reported concerning withdrawal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":27,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: We captured female prisoners, and we used to practice withdrawal, so we asked the Messenger of Allah about it. He said: “Do you really do that?” He said it three times. “There is no soul that is destined to exist until the Day of Resurrection except that it will surely come into existence.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5210,"lafz":true},{"key":"muslim","label":"مسلم","number":127}],"full":1},{"num":6372,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّ رَجُلاً، قَالَ يَا رَسُولَ اللَّهِ إِنَّ لِي جَارِيَةً وَأَنَا أَعْزِلُ عَنْهَا وَأَنَا أَكْرَهُ أَنْ تَحْمِلَ وَأَنَا أُرِيدُ مَا يُرِيدُ الرِّجَالُ وَإِنَّ الْيَهُودَ تُحَدِّثُ أَنَّ الْعَزْلَ مَوْءُودَةُ الصُّغْرَى. قَالَ كَذَبَتْ يَهُودُ لَوْ أَرَادَ اللَّهُ أَنْ يَخْلُقَهُ مَا اسْتَطَعْتَ أَنْ تَصْرِفَهُ."],"takhrij":"حسن: روى عن أبي سعيد الخدري من طرق:","grade":"حسن","chapter_ar":"باب ما جاء في العزل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2171), Ahmad (11477, 11288), and al-Tahawi in Mushkil al-Athar (1917).","chapter_en":"What has been reported concerning withdrawal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":27,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that a man said: O Messenger of Allah, I have a slave-girl, and I withdraw from her. I dislike that she should become pregnant, though I desire what men desire. The Jews say that withdrawal is minor infanticide. He said: “The Jews have lied. If Allah intended to create it, you would not be able to turn it away.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2171,"lafz":true},{"key":"sh22547","label":"الطحاوي في مشكل الآثار","number":1917},{"key":"ahmad","label":"مسند الإمام أحمد","number":11477,"n":11477}],"full":1,"dr":1},{"num":6373,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ، أن رجلاً أَتَى رسول اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ لِي جَارِيَةً هِيَ خَادِمُنَا وَسَانِيَتُنَا وَأَنَا أَطُوفُ عَلَيْهَا وَأَنَا أَكْرَهُ أَنْ تَحْمِلَ. فَقَالَ اعْزِلْ عَنْهَا إِنْ شِئْتَ فَإِنَّهُ سَيَأْتِيهَا مَا قُدِّرَ لَهَا. فَلَبِثَ الرَّجُلُ ثُمَّ أَتَاهُ فَقَالَ إِنَّ الْجَارِيَةَ قَدْ حَبِلَتْ. فَقَالَ قَدْ أَخْبَرْتُكَ أَنَّهُ سَيَأْتِيهَا مَا قُدِّرَ لَهَا."],"takhrij":"صحيح: رواه مسلم في النكاح (1439) عن أحمد بن عبد الله بن يونس، حدّثنا زهير، أخبرنا أبو الزبير، عن جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في العزل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1439). In another narration: “That will not prevent anything Allah has intended.” Then the man came and said: O Messenger of Allah, the slave-girl I mentioned to you has become pregnant. So the Messenger of Allah ﷺ said: “I am the servant of Allah and His Messenger.”","chapter_en":"What has been reported concerning withdrawal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":27,"content":{"translation":{"en":["Jabir ibn ʿAbdullah narrated that a man came to the Messenger of Allah ﷺ and said: “I have a slave-girl who serves us and waters our land, and I have relations with her, but I dislike that she should become pregnant.” He said: “Practice withdrawal from her if you wish, for what has been decreed for her will come to her.” The man stayed away for some time, then came back and said: The slave-girl has become pregnant. He said: “I told you that what had been decreed for her would come to her.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1439,"lafz":true}],"full":1,"dr":1},{"num":6374,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ كُنَّا نَعْزِلُ وَالْقُرْآنُ يَنْزِلُ. زَادَ إِسْحَاقُ قَالَ سُفْيَانُ لَوْ كَانَ شَيْئًا يُنْهَى عَنْهُ لَنَهَانَا عَنْهُ الْقُرْآنُ.","وفي لفظ: كنا نعزل على عهد رسول الله صلى الله عليه وسلم."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5208)، ومسلم في النكاح (1440) كلاهما من طريق سفيان (هو ابن عيينة)، عن عمرو (هو ابن دينار) أخبرني عطاء، أنه سمع جابراً، فذكره. واللفظ الآخر عند البخاري (5207) من طريق ابن جريج، ومسلم من طريق معقل- كلاهما عن عطاء، عن جابر.","grade":"متفق عليه","chapter_ar":"باب ما جاء في العزل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5208) and Muslim (1440).","chapter_en":"What has been reported concerning withdrawal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":27,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: We used to practice withdrawal while the Qur’an was being revealed. If it had been something forbidden, the Qur’an would have forbidden us from it. And in another wording: We used to practice withdrawal during the time of the Messenger of Allah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري في النكاح","number":5208,"lafz":true},{"key":"muslim","label":"مسلم في النكاح","number":1440},{"key":"bukhari","label":"اللفظ الاخر عند البخاري","number":5207}],"full":1,"dr":1},{"num":6375,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ كُنَّا نَعْزِلُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَلَغَ ذَلِكَ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمْ يَنْهَنَا."],"takhrij":"صحيح: رواه مسلم في النكاح (138:1439) عن أبي غسّان المِسْمعي، حدّثنا معاذ بن هشام، حدثني أبي، عن أبي الزبير، عن جابر، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في العزل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1440:163).","chapter_en":"What has been reported concerning withdrawal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":27,"content":{"translation":{"en":["Jabir said: We used to practice withdrawal during the time of the Messenger of Allah ﷺ, and that reached the Prophet of Allah ﷺ, yet he did not forbid us."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":163,"lafz":true},{"key":"muslim","label":"مسلم في النكاح","number":138}],"full":1},{"num":6376,"demo":false,"sanad":"","matn":["عَنْ عَامِرِ بْنِ سَعْدٍ، أَنَّ أُسَامَةَ بْنَ زَيْدٍ، أَخْبَرَ وَالِدَهُ، سَعْدَ بْنَ أَبِي وَقَّاصٍ أَنَّ رَجُلاً، جَاءَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَقَالَ إِنِّي أَعْزِلُ عَنِ امْرَأَتِي. فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  لِمَ تَفْعَلُ ذَلِكَ. فَقَالَ الرَّجُلُ أُشْفِقُ عَلَى وَلَدِهَا أَوْ عَلَى أَوْلاَدِهَا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  لَوْ كَانَ ذَلِكَ ضَارًّا ضَرَّ فَارِسَ وَالرُّومَ."],"takhrij":"صحيح: رواه مسلم في النكاح (143:1443) من طريق عبد الله بن يزيد المقبري، حدّثنا حيوة، حدثني عيّاش بن عباس، أن أبا النضر حدّثه عن عامر بن سعد، به، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في العزل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1443:143).","chapter_en":"What has been reported concerning withdrawal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":27,"content":{"translation":{"en":["ʿAmir ibn Saʿd narrated that Usamah ibn Zayd informed his father Saʿd ibn Abi Waqqas that a man came to the Messenger of Allah ﷺ and said: I practice withdrawal from my wife. Allah’s Messenger ﷺ said to him: “Why do you do that?” The man said: I fear for her child, or for her children. So the Messenger of Allah ﷺ said: “If it were harmful, it would have harmed the Persians and the Romans.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم في النكاح","number":143,"lafz":true}],"full":1},{"num":6377,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَكَ فِي جِمَاعِ زَوْجَتِكَ أَجْرٌ، فَقِيلَ: يَا رَسُولَ اللَّهِ، وَفِي شَهْوَةٍ يَكُونُ مِنْ أَجْرٍ؟ قَالَ: نَعَمْ، أَرَأَيْتَ لَوْ كَانَ لَكَ وَلَدٌ قَدْ أَدْرَكَ ثُمَّ مَاتَ أَكُنْتَ مُحْتَسِبَهُ؟ قَالَ: نَعَمْ، قَالَ: أَنْتَ كُنْتَ خَلَقْتَهُ؟ قَالَ: بَلِ اللَّهُ خَلَقَهُ، قَالَ: أَنْتَ كُنْتَ هَدَيْتَهُ؟ قَالَ: بَلِ اللَّهُ هَدَاهُ، قَالَ: أَكُنْتَ تَرْزُقُهُ؟ قَالَ: بَلِ اللَّهُ كَانَ رَزَقَهُ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَضَعْهُ فِي حَلَالِهِ وَجَنِّبْهُ حَرَامَهُ وَأَقْرِرْهُ، فَإِنْ شَاءَ اللَّهُ أَحْيَاهُ وَإِنْ شَاءَ اللَّهُ أَمَاتَهُ وَلَكَ أَجْرٌ."],"takhrij":"حسن: رواه ابن حبان (4192)، عن ابن سلم، قال: حدثنا حرملة، قال: حدثنا ابن وهب، قال: أخبرني عمرو بن الحارث، أن سعيد بن أبي هلال حدّثه عن أبي سعيد مولى المهري، عن أبي ذر فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في العزل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Hibban (4192).","chapter_en":"What has been reported concerning withdrawal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":27,"content":{"translation":{"en":["Abu Dharr narrated that the Messenger of Allah ﷺ said: “You have a reward in having intercourse with your wife.” It was said: O Messenger of Allah ﷺ, does one of us fulfill his desire and still get a reward for it? He said: “Yes. Tell me, if you had a child who reached maturity and then died, would you hope for reward for that?” He said: Yes. He said: “Did you create him?” He said: Rather, Allah created him. He said: “Did you guide him?” He said: Rather, Allah guided him. He said: “Did you provide for him?” He said: Rather, Allah provided for him. The Messenger of Allah ﷺ said: “Then place it in its lawful place, keep it away from what is unlawful, and let it take its course. If Allah wills, He will give it life, and if He wills, He will cause it to die, and you will have a reward.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2432,"n":2429},{"key":"ibnhibban","label":"ابن حبان","number":4192,"lafz":true}],"full":1,"dr":1},{"num":6378,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ أَنَّهُ قَالَ: عَلَى كُلِّ نَفْسٍ فِي كُلِّ يَوْمٍ طَلَعَتْ فِيهِ الشَّمْسُ صَدَقَةٌ مِنْهُ عَلَى نَفْسِهِ. قُلْتُ: يَا رَسُولَ اللَّهِ، مِنْ أَيْنَ أَتَصَدَّقُ وَلَيْسَ لَنَا أَمْوَالٌ؟ قَالَ: لأنّ مِنْ أَبْوَابِ الصَّدَقَةِ التَّكْبِيرَ، وَسُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَأَسْتَغْفِرُ اللهَ، وَتَأْمُرُ بِالْمَعْرُوفِ وَتَنْهَى عَنِ الْمُنْكَرِ، وَتَعْزِلُ الشَّوْكَةَ عَنْ طَرِيقِ النَّاسِ وَالْعَظْمَ وَالْحَجَرَ، وَتَهْدِي الْأَعْمَى، وَتُسْمِعُ الصم وَالْأَبْكَمَ حَتَّى يَفْقَهَ، وَتُدِلُّ الْمُسْتَدِلَّ عَلَى حَاجَةٍ لَهُ قَدْ عَلِمْتَ مَكَانَهَا، وَتَسْعَى بِشِدَّةِ سَاقَيْكَ إِلَى اللهْفَانِ الْمُسْتَغِيثِ، وَتَرْفَعُ بِشِدَّةِ ذِرَاعَيْكَ مَعَ الضَّعِيفِ، كُلُّ ذَلِكَ مِنْ أَبْوَابِ الصَّدَقَةِ مِنْكَ عَلَى نَفْسِكَ، وَلَكَ فِي جِمَاعِكَ زَوْجَتَكَ أَجْرٌ قـال أَبُو ذَرٍّ: كَيْفَ يَكُونُ لِي أَجْرٌ فِي شَهْوَتِي؟! فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَرَأَيْتَ لَوْ كَانَ لَكَ وَلَدٌ فَأَدْرَكَ وَرَجَوْتَ خَيْرَهُ فَمَاتَ، أَكُنْتَ تَحْتَسِبُ بِهِ؟ قُلْتُ: نَعَمْ. قَالَ: فَأَنْتَ خَلَقْتَهُ؟ قَالَ: بَلِ اللَّهُ خَلَقَهُ. قَالَ: فَأَنْتَ هَدَيْتَهُ؟ قَالَ: بَلِ اللَّهُ هَدَاهُ، قَالَ: فَأَنْتَ تَرْزُقُهُ؟ قَالَ: بَلِ اللَّهُ كَانَ يَرْزُقُهُ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : كَذَلِكَ فَضَعْهُ فِي حَلَالِهِ وَجَنِّبْهُ حَرَامَهُ، فَإِنْ شَاءَ اللَّهُ أَحْيَاهُ، وَإِنْ شَاءَ أَمَاتَهُ، وَلَكَ أَجْرٌ."],"takhrij":"صحيح: رواه أحمد (21484) عن عبدالملك بن عمرو، حدثنا علي- يعني ابن المبارك، عن يحيى، عن زيد بن سلاّم، عن أبي سلاّم، قال: قال أبو ذر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في العزل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (21484).","chapter_en":"What has been reported concerning withdrawal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":27,"content":{"translation":{"en":["Abū Dharr reported: Every person owes a charity on behalf of himself on every day upon which the sun rises. I asked: “O Messenger of Allah, how can I give charity when we have no wealth?” He said: “Among the doors of charity are saying ‘Allahu Akbar,’ ‘Subḥān Allah,’ ‘al-ḥamdu lillāh,’ ‘lā ilāha illā Allah,’ and ‘astaghfirullāh’; commanding what is right and forbidding what is wrong; removing a thorn, a bone, or a stone from the path of the people; guiding the blind; helping the deaf and mute understand; directing someone seeking guidance to a need whose location you know; hurrying with the strength of your legs to aid a distressed person calling for help; and using the strength of your arms to assist someone weak. All of these are doors of charity that you perform on behalf of yourself, and you also receive a reward for intercourse with your wife.” Abū Dharr asked: “How can I receive a reward for fulfilling my desire?” The Messenger of Allah ﷺ said: “Suppose you had a child who reached maturity and you hoped for good from him, then he died. Would you seek reward from Allah for him?” I said: “Yes.” He asked: “Did you create him?” He replied: “Rather, Allah created him.” He asked: “Did you guide him?” He replied: “Rather, Allah guided him.” He asked: “Did you provide for him?” He replied: “Rather, Allah provided for him.” The Messenger of Allah ﷺ said: “Likewise, place your desire in what is lawful and keep it away from what is unlawful. If Allah wills, He gives life, and if He wills, He causes death, and you receive a reward.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":21484,"n":21484,"lafz":true}],"full":1,"dr":1},{"num":6379,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْعَزْلِ قَالُوا: إِنَّ الْيَهُودَ تَزْعُمُ أَنَّ الْعَزْلَ هِيَ الْمَوْؤُدَةُ الصُّغْرَى قَالَ: كَذَبَتِ الْيَهُودُ."],"takhrij":"حسن: رواه البزار – كشف الأستار (1451) والبيهقي (7/230) كلاهما من حديث محمد بن عمرو، ثنا أبو سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في العزل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzar, Kashf al-Astar (1451), and al-Bayhaqi (7/230).","chapter_en":"What has been reported concerning withdrawal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":27,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ was asked about withdrawal. They said: The Jews claim that withdrawal is minor infanticide. He said: “The Jews have lied.”"]},"buhuth":{"en":["Jurisprudence of this chapter: Regarding the ruling on withdrawal, I do not know of anyone who said it is forbidden. As for it being disliked, yes, some jurists held that view. The basic principle is that it is permissible, based on what we know from the approval of the Qur’an and the Sunnah.","Women are of three types:","If she is owned, then the harm in her becoming pregnant and giving birth is that she becomes an umm walad, and an umm walad may not be sold.","If she is a female slave and bondwoman, then the harm in not practicing withdrawal from her is that if she becomes pregnant and gives birth, her child will be a slave following his mother.","If she is his free wife, then withdrawal with her is not permitted except with her permission, such as if she is ill and allows withdrawal for fear of pregnancy. But without her permission, that is not allowed, because it is her right to enjoy intimacy, become pregnant, and bear children."]}},"tuhfa":{},"refs":[{"key":"sh12862","label":"البزار - كشف الأستار","number":1451,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":7},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":14315,"n":14456}],"full":1,"dr":1},{"num":6380,"demo":false,"sanad":"","matn":["عن جدامة بنت وهب أخت عكاشة بن وهب قالت: حضرت رسول الله صلى الله عليه وسلم وسألوه عن العزل فقال: الوأد الخفي."],"takhrij":"صحيح: رواه مسلم في النكاح (141:1442) من طريق عن عبد الله بن يزيد المقرئ، حدثنا سعيد بن أبي أيوب، حدثني أبو الأسود، عن عروة، عن عائشة، عن جدامة بنت وهب فذكرته.","grade":"صحيح","chapter_ar":"باب ماجاء في كراهية العزل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1442:141).","chapter_en":"What Has Been Reported Regarding the Dislike of Withdrawal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":28,"content":{"translation":{"en":["Judamah bint Wahb, the sister of ʿUkkashah ibn Wahb, said: I was present with the Messenger of Allah ﷺ, and they asked him about withdrawal, so he said: “It is hidden infanticide.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم في النكاح","number":141,"lafz":true}],"full":1,"dr":1},{"num":6381,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أُمِّ الْمُؤْمِنِينَ، عَنْ جُدَامَةَ بِنْتِ وَهْبٍ الأَسَدِيَّةِ، أَنَّهَا أَخْبَرَتْهَا أَنَّهَا، سَمِعَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ لَقَدْ هَمَمْتُ أَنْ أَنْهَى عَنِ الْغِيلَةِ حَتَّى ذَكَرْتُ أَنَّ الرُّومَ وَفَارِسَ يَصْنَعُونَ ذَلِكَ فَلاَ يَضُرُّ أَوْلاَدَهُمْ."],"takhrij":"صحيح: رواه مالك في الرضاع (16) عن محمد بن عبد الرحمن بن نوفل أنه قال: أخبرني عروة بن الزبير، عن عائشة أم المؤمنين، به.","grade":"صحيح","chapter_ar":"باب ما جاء في الغيلة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (16) and Muslim (1442:140).","chapter_en":"What Has Been Reported Regarding Ghilah","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":29,"content":{"translation":{"en":["ʿA’ishah narrated from Judamah bint Wahb al-Asadiyyah that she informed her that she heard the Messenger of Allah ﷺ say: “I had intended to forbid ghilah, until I remembered that the Romans and Persians do that, and it does not harm their children.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك في الرضاع","number":16,"lafz":true}],"full":1,"dr":1},{"num":6382,"demo":false,"sanad":"","matn":["عَنْ جُدَامَةَ بِنْتِ وَهْبٍ، أُخْتِ عُكَّاشَةَ قَالَتْ حَضَرْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ   فِي أُنَاسٍ وَهُوَ يَقُولُ لَقَدْ هَمَمْتُ أَنْ أَنْهَى عَنِ الْغِيلَةِ فَنَظَرْتُ فِي الرُّومِ وَفَارِسَ فَإِذَا هُمْ يُغِيلُونَ أَوْلاَدَهُمْ فَلاَ يَضُرُّ أَوْلاَدَهُمْ ذَلِكَ شَيْئًا. ثُمَّ سَأَلُوهُ عَنِ الْعَزْلِ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ   ذَلِكَ الْوَأْدُ الْخَفِيُّ.","زاد في رواية: ﴿وَإِذَا الْمَوْءُودَةُ سُئِلَتْ﴾[التكوير: ٨]"],"takhrij":"صحيح: رواه مسلم في النكاح (141،1442) من طريق المقرئ، حدثنا سعيد بن أبي أيوب، حدثني أبو الأسود، عن عروة، عن عائشة، عن جدامة بنت وهب فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في الغيلة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1442:141).","chapter_en":"What Has Been Reported Regarding Ghilah","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":29,"content":{"translation":{"en":["Judamah bint Wahb, the sister of ʿUkkashah, said: I was present with the Messenger of Allah ﷺ among some people while he was saying: “I had intended to forbid ghilah, but I looked at the Romans and Persians, and they practice ghilah with their children, yet that does not harm their children at all.” Then they asked him about withdrawal, so the Messenger of Allah ﷺ said: “That is hidden infanticide.” In one narration there is the addition: “And when the buried girl is asked” [Surat al-Takwir: 8]."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم في النكاح","number":141,"lafz":true},{"key":"muslim","label":"مسلم في النكاح","number":1442,"n":3565}],"full":1},{"num":6383,"demo":false,"sanad":"","matn":["عَنْ عَطَاءٍ، عَنِ ابْنِ عَبَّاسٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَنِ الْغَيْلِ، فَقَالَ: لَوْ كَانَ ضَارًّا أَحَدًا ضَرَّ فَارِسَ وَالرُّومَ."],"takhrij":"صحيح: رواه البزار – كشف الأستار (1454) عن محمد بن أبي غالب، ثنا صفوان بن صالح، ثنا عيسى بن يونس، ثنا ابن جريج، عن عطاء، عن عبد عبد الله بن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الغيلة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bazzar, Kashf al-Astar (1454).","chapter_en":"What Has Been Reported Regarding Ghilah","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":29,"content":{"translation":{"en":["ʿAbd Allah ibn ʿAbbas narrated that the Messenger of Allah ﷺ was asked about ghayl, and he said: “If it were harmful to anyone, it would have harmed the Persians and the Romans.”"]}},"tuhfa":{},"refs":[{"key":"sh12862","label":"البزار - كشف الأستار","number":1454,"lafz":true}],"full":1,"dr":1},{"num":6384,"demo":false,"sanad":"","matn":["عن عطاء قَالَ حَضَرْنَا مَعَ ابْنِ عَبَّاسٍ جَنَازَةَ مَيْمُونَةَ بِسَرِفَ، فَقَالَ ابْنُ عَبَّاسٍ هَذِهِ زَوْجَةُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَإِذَا رَفَعْتُمْ نَعْشَهَا فَلاَ تُزَعْزِعُوهَا وَلاَ تُزَلْزِلُوهَا وَارْفُقُوا، فَإِنَّهُ كَانَ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تِسْعٌ، كَانَ يَقْسِمُ لِثَمَانٍ وَلاَ يَقْسِمُ لِوَاحِدَةٍ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5067) من طريق هشام بن يوسف، ومسلم في الرضاع (51:1465)من طريق محمد بن بكر – كلاهما عن ابن جريج قال: أخبرني عطاء، فذكره. وزاد مسلم: قال عطاء: التي لا يقسم لها صفية بنت حييّ بن أخطب.","grade":"متفق عليه","chapter_ar":"باب العدل بين الزوجات في القسم إلا من وهبت نوبتها لضرتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5067) and Muslim (1465:51).","chapter_en":"Justice Between Wives in Allotment, Except for the One Who Gives Her Turn to Her Co-Wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":30,"content":{"translation":{"en":["ʿAta’ said: We attended the funeral of Maymunah at Sarif with Ibn ʿAbbas, and Ibn ʿAbbas said: This is the wife of the Prophet ﷺ, so when you lift her bier, do not shake it or jolt it; be gentle, for the Prophet ﷺ had nine wives. He used to divide his time among eight and did not divide for one of them."]},"intro":{"ar":["قال الله تعالى: (فَانكِحُوا مَا طَابَ لَكُم مِّنَ النِّسَاءِ مَثْنَىٰ وَثُلَاثَ وَرُبَاعَ ۖ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً أَوْ مَا مَلَكَتْ أَيْمَانُكُمْ ۚ ذَٰلِكَ أَدْنَىٰ أَلَّا تَعُولُوا) [النساء: ٣]\\n\\nوقال تعالى: (وَلَن تَسْتَطِيعُوا أَن تَعْدِلُوا بَيْنَ النِّسَاءِ وَلَوْ حَرَصْتُمْ فَلَا تَمِيلُوا كُلَّ الْمَيْلِ فَتَذَرُوهَا كَالْمُعَلَّقَةِ) [النساء: ١٢٩] قال ابن عباس: أي في الحب والجماع."],"en":["Allah the Exalted said: “Marry those women who are lawful for you, two, three, or four; but if you fear that you will not be just, then one, or those whom your right hands possess. That is more likely that you will not commit injustice.” [Surat al-Nisa’: 3]\\n\\nAnd He said: “You will never be able to be completely just between wives, even if you are eager. So do not incline completely toward one and leave another hanging.” [Surat al-Nisa’: 129]\\n\\nIbn ʿAbbas said: This means in love and intercourse."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري في النكاح","number":5067,"lafz":true},{"key":"muslim","label":"مسلم في الرضاع","number":51}],"full":1,"dr":1},{"num":6385,"demo":false,"sanad":"","matn":["عَنْ صَفِيَّةَ بِنْتِ حُيَيٍّ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَجَّ بِنِسَائِهِ، فَلَمَّا كَانَ فِي بَعْضِ الطَّرِيقِ نَزَلَ رَجُلٌ، فَسَاقَ بِهِنَّ، فَأَسْرَعَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَذَاكَ سَوْقُكَ بِالْقَوَارِيرِ يَعْنِي النِّسَاءَ، فَبَيْنَا هُمْ يَسِيرُونَ بَرَكَ بِصَفِيَّةَ بِنْتِ حُيَيٍّ جَمَلُهَا، وَكَانَتْ مِنْ أَحْسَنِهِنَّ ظَهْرًا، فَبَكَتْ، وَجَاءَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ أُخْبِرَ بِذَلِكَ، فَجَعَلَ يَمْسَحُ دُمُوعَهَا بِيَدِهِ، وَجَعَلَتْ تَزْدَادُ بُكَاءً، وَهُوَ يَنْهَاهَا، فَلَمَّا أَكْثَرَتْ، زَبَرَهَا، وَانْتَهَرَهَا، وَأَمَرَ النَّاسَ بِالنُّزُولِ، فَنَزَلُوا، وَلَمْ يَكُنْ يُرِيدُ أَنْ يَنْزِلَ، قَالَتْ: فَنَزَلُوا، وَكَانَ يَوْمِي، فَلَمَّا نَزَلُوا، ضُرِبَ خِبَاءُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَدَخَلَ فِيهِ، قَالَتْ: فَلَمْ أَدْرِ عَلَامَ أُهْجَمُ مِنْ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَخَشِيتُ أَنْ يَكُونَ فِي نَفْسِهِ شَيْءٌ مِنِّي، فَانْطَلَقْتُ إِلَى عَائِشَةَ، فَقُلْتُ لَهَا: تَعْلَمِينَ أَنِّي لَمْ أَكُنْ أَبِيعُ يَوْمِي مِنْ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشَيْءٍ أَبَدًا، وَإِنِّي قَدْ وَهَبْتُ يَوْمِي لَكِ عَلَى أَنْ تُرْضِي رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِّي، قَالَتْ: نَعَمْ، قَالَ: فَأَخَذَتْ عَائِشَةُ خِمَارًا لَهَا، قَدْ ثَرَدَتْهُ بِزَعْفَرَانٍ، فَرَشَّتْهُ بِالمَاءِ لِيُذَكِّيَ رِيحَهُ، ثُمَّ لَبِسَتْ ثِيَابَهَا، ثُمَّ انْطَلَقَتْ إِلَى رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَرَفَعَتْ طَرَفَ الْخِبَاءِ، فَقَالَ لَهَا: مَا لَكِ يَا عَائِشَةُ؟ إِنَّ هَذَا لَيْسَ بِيَوْمِكِ، قَالَتْ: ذَلِكَ فَضْلُ الله يُؤْتِيهِ مَنْ يَشَاءُ، فَقَالَ مَعَ أَهْلِهِ، فَلَمَّا كَانَ عِنْدَ الرَّوَاحِ، قَالَ لِزَيْنَبَ بِنْتِ جَحْشٍ: يَا زَيْنَبُ أَفْقِرِي أُخْتَكِ صَفِيَّةَ جَمَلًا، وَكَانَتْ مِنْ أَكْثَرِهِنَّ ظَهْرًا، فَقَالَتْ: أَنَا أُفْقِرُ يَهُودِيَّتَكَ، فَغَضِبَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ سَمِعَ ذَلِكَ مِنْهَا، فَهَجَرَهَا، فَلَمْ يُكَلِّمْهَا حَتَّى قَدِمَ مَكَّةَ، وَأَيَّامَ مِنًى فِي سَفَرِهِ، حَتَّى رَجَعَ إِلَى المَدِينَةِ، وَالمُحَرَّمَ، وَصَفَرَ، فَلَمْ يَأْتِهَا وَلَمْ يَقْسِمْ لَهَا، وَيَئِسَتْ مِنْهُ، فَلَمَّا كَانَ شَهْرُ رَبِيعٍ الْأَوَّلِ دَخَلَ عَلَيْهَا، فَرَأَتْ ظِلَّهُ، فَقَالَتْ: إِنَّ هَذَا لَظِلُّ رَجُلٍ، وَمَا يَدْخُلُ عَلَيَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَمَنْ هَذَا؟ فَدَخَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا رَأَتْهُ، قَالَتْ: يَا رَسُولَ الله مَا أَدْرِي مَا أَصْنَعُ حِينَ دَخَلْتَ عَلَيَّ، قَالَتْ: وَكَانَتْ لَهَا جَارِيَةٌ، وَكَانَتْ تَخْبَؤُهَا مِنْ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَتْ: فُلَانَةُ لَكَ، فَمَشَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى سَرِيرِ زَيْنَبَ، وَكَانَ قَدْ رُفِعَ، فَوَضَعَهُ بِيَدِهِ، ثُمَّ أَصَابَ أَهْلَهُ، وَرَضِيَ عَنْهُمْ."],"takhrij":"حسن: رواه الإمام أحمد (26866) عن عبد الرزاق، قال: حدثنا جعفر بن سليمان، عن ثابت، قال: حدثتني شميسة أو سمية -قال عبد الرزاق هو في كتابي سمية- عن صفية بنت حُيي فذكرته.","grade":"حسن","chapter_ar":"باب العدل بين الزوجات في القسم إلا من وهبت نوبتها لضرتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (26866).","chapter_en":"Justice Between Wives in Allotment, Except for the One Who Gives Her Turn to Her Co-Wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":30,"content":{"translation":{"en":["Safiyyah bint Huyayy narrated that the Prophet ﷺ performed Hajj with his wives. During part of the journey, a man came down and drove them on quickly, so the Prophet ﷺ said: “Take care when driving these glass vessels,” meaning the women. While they were traveling, Safiyyah bint Huyayy’s camel knelt down, and she was one of those with the best mounts, so she cried. The Messenger of Allah ﷺ came when he was informed of that and began wiping her tears with his hand, but she cried even more while he was trying to calm her. When she cried excessively, he rebuked her and scolded her, then ordered the people to halt, though he had not intended to stop. She said: So they stopped, and it was my day. The Prophet’s tent was pitched and he entered it. She said: I did not know why the Messenger of Allah had withdrawn from me, and I feared that something about me was in his heart. So I went to ʿA’ishah and said to her: You know that I would never give up my day with the Messenger of Allah for anything, but I have given my day to you on condition that you make the Messenger of Allah pleased with me. She said: Yes. She said: Then ʿA’ishah took a head-covering of hers which she had perfumed with saffron, sprinkled it with water so that its fragrance would be stronger, then put on her clothes and went to the Messenger of Allah and lifted the edge of the tent. He said to her: “What is the matter, O ʿA’ishah? This is not your day.” She said: That is the bounty of Allah; He gives it to whom He wills. So he remained with his family. Then when it was time to set out, he said to Zaynab bint Jahsh: “O Zaynab, lend your sister Safiyyah a camel.” Zaynab had more riding animals than any of them, but she said: Shall I lend my camel to your Jewish woman? The Prophet became angry when he heard that from her, and he forsook her and did not speak to her until he arrived in Makkah, and through the days of Mina on his journey, then until he returned to Madinah through Muharram and Safar. He did not go to her and did not allot her a turn, and she despaired of him. Then when the month of Rabiʿ al-Awwal came, he entered upon her. She saw his shadow and said: This is surely the shadow of a man, but the Prophet does not enter upon me, so who is this? Then the Prophet entered, and when she saw him, she said: O Messenger of Allah, I do not know what to do now that you have entered upon me. She said: She had a slave-girl whom she used to hide from the Prophet, so she said: So-and-so is yours. Then the Prophet went to Zaynab’s bed, which had been raised, lowered it with his own hand, then went in to his wife, and became pleased with them."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":26866,"lafz":true}],"full":1,"dr":1},{"num":6386,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ حَدَّثَهُمْ أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَطُوفُ عَلَى نِسَائِهِ فِي اللَّيْلَةِ الْوَاحِدَةِ، وَلَهُ يَوْمَئِذٍ تِسْعُ نِسْوَةٍ.","وفي رواية: كان النبي صلى الله عليه وسلم يدور على نسائه في الساعة الواحدة من الليل والنهار وهن إحدى عشرة. قال: قلتُ لأنس: أو كان يطيقه؟ قال: كنا نتحدث أنه أُعطي قوة ثلاثين."],"takhrij":"صحيح: رواه البخاري في النكاح (5215) عن عبدالأعلى بن حماد، حدّثنا يزيد بن زريع، حدثنا سعيد، عن قتادة، أن أنس بن مالك حدّثهم، فذكره.","grade":"صحيح","chapter_ar":"باب العدل بين الزوجات في القسم إلا من وهبت نوبتها لضرتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5215) and (268).","chapter_en":"Justice Between Wives in Allotment, Except for the One Who Gives Her Turn to Her Co-Wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":30,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet of Allah ﷺ used to go around to his wives in a single night, and at that time he had nine wives. In another narration: The Prophet ﷺ used to go around to his wives in a single hour of the night and day, and they were eleven. I said to Anas: Was he able to do that? He said: We used to say that he had been given the strength of thirty men."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري في النكاح","number":5215,"lafz":true}],"full":1,"dr":1},{"num":6387,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ كَانَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تِسْعُ نِسْوَةٍ فَكَانَ إِذَا قَسَمَ بَيْنَهُنَّ لاَ يَنْتَهِي إِلَى الْمَرْأَةِ الْأُولَى إِلاَّ فِي تِسْعٍ فَكُنَّ يَجْتَمِعْنَ كُلَّ لَيْلَةٍ فِي بَيْتِ الَّتِي يَأْتِيهَا فَكَانَ فِي بَيْتِ عَائِشَةَ فَجَاءَتْ زَيْنَبُ فَمَدَّ يَدَهُ إِلَيْهَا فَقَالَتْ هَذِهِ زَيْنَبُ. فَكَفَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَهُ. فَتَقَاوَلَتَا حَتَّى اسْتَخَبَتَا وَأُقِيمَتِ الصَّلاَةُ فَمَرَّ أَبُو بَكْرٍ عَلَى ذَلِكَ فَسَمِعَ أَصْوَاتَهُمَا فَقَالَ اخْرُجْ يَا رَسُولَ اللَّهِ إِلَى الصَّلاَةِ وَاحْثُ فِي أَفْوَاهِهِنَّ التُّرَابَ. فَخَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ عَائِشَةُ الآنَ يَقْضِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلاَتَهُ فَيَجِيءُ أَبُو بَكْرٍ فَيَفْعَلُ بِي وَيَفْعَلُ. فَلَمَّا قَضَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلاَتَهُ أَتَاهَا أَبُو بَكْرٍ فَقَالَ لَهَا قَوْلاً شَدِيدًا وَقَالَ أَتَصْنَعِينَ هَذَا."],"takhrij":"صحيح: رواه مسلم في الرضاع (1462) عن أبي بكر بن أبي شيبة، حدّثنا شبابة بن سوّار، حدّثنا سليمان بن المغيرة، عن ثابت، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب العدل بين الزوجات في القسم إلا من وهبت نوبتها لضرتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1462).","chapter_en":"Justice Between Wives in Allotment, Except for the One Who Gives Her Turn to Her Co-Wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":30,"content":{"translation":{"en":["Anas said: The Prophet ﷺ had nine wives. When he divided his time among them, he would not return to the first wife until nine days had passed. They used to gather every night in the house of the one whose turn it was. It happened in the house of ʿA’ishah. Then Zaynab came, and the Prophet ﷺ extended his hand toward her. ʿA’ishah said: This is Zaynab. So the Prophet ﷺ withdrew his hand. Then the two exchanged words until their voices rose. The prayer was called, and Abu Bakr passed by and heard their voices, so he said: Go out, O Messenger of Allah, to the prayer, and throw dust into their mouths. The Prophet went out, and ʿA’ishah said: Now the Prophet will finish his prayer, and then Abu Bakr will come and do such-and-such to me. When the Prophet finished his prayer, Abu Bakr came to her, spoke to her harshly, and said: Do you do this?"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم في الرضاع","number":1462,"lafz":true}],"full":1,"dr":1},{"num":6388,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَرَادَ سَفَرًا أَقْرَعَ بَيْنَ نِسَائِهِ، فَأَيَّتُهُنَّ خَرَجَ سَهْمُهَا خَرَجَ بِهَا مَعَهُ، وَكَانَ يَقْسِمُ لِكُلِّ امْرَأَةٍ مِنْهُنَّ يَوْمَهَا وَلَيْلَتَهَا، غَيْرَ أَنَّ سَوْدَةَ بِنْتَ زَمْعَةَ وَهَبَتْ يَوْمَهَا وَلَيْلَتَهَا، لِعَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَبْتَغِي بِذَلِكَ رِضَا رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه البخاري في الهبة (2593) عن حِبّان بن موسى، أخبرنا عبد الله، أخبرنا يونس، عن الزهري، عن عروة، عن عائشة، قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب العدل بين الزوجات في القسم إلا من وهبت نوبتها لضرتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2593).","chapter_en":"Justice Between Wives in Allotment, Except for the One Who Gives Her Turn to Her Co-Wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":30,"content":{"translation":{"en":["ʿĀʾishah reported: Whenever the Messenger of Allah ﷺ intended to travel, he would draw lots among his wives. Whichever wife’s lot was drawn, he would take her with him. He would allot each of his wives her own day and night, except that Sawdah bint Zamʿah gave her day and night to ʿĀʾishah, the wife of the Prophet ﷺ, seeking thereby the pleasure of the Messenger of Allah ﷺ."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2593,"lafz":true}],"full":1},{"num":6389,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ مَا رَأَيْتُ امْرَأَةً أَحَبَّ إِلَىَّ أَنْ أَكُونَ فِي مِسْلاَخِهَا مِنْ سَوْدَةَ بِنْتِ زَمْعَةَ مِنِ امْرَأَةٍ فِيهَا حِدَّةٌ قَالَتْ فَلَمَّا كَبِرَتْ جَعَلَتْ يَوْمَهَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِعَائِشَةَ قَالَتْ يَا رَسُولَ اللَّهِ قَدْ جَعَلْتُ يَوْمِي مِنْكَ لِعَائِشَةَ. فَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْسِمُ لِعَائِشَةَ يَوْمَيْنِ يَوْمَهَا وَيَوْمَ سَوْدَةَ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5212)، ومسلم في الرضاع (47:1463) كلاهما من طريق هشام بن عروة، عن أبيه، عن عائشة، فذكرته، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب العدل بين الزوجات في القسم إلا من وهبت نوبتها لضرتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5212) and Muslim (1463:47). The wording is from Muslim.","chapter_en":"Justice Between Wives in Allotment, Except for the One Who Gives Her Turn to Her Co-Wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":30,"content":{"translation":{"en":["ʿA’ishah said: I never saw a woman in whose place I would have preferred to be more than Sawdah bint Zamʿah, a woman who had some sharpness in her nature. When she grew older, she gave her day with the Messenger of Allah ﷺ to ʿA’ishah. She said: O Messenger of Allah, I have given my day with you to ʿA’ishah. So the Messenger of Allah ﷺ used to allot two days to ʿA’ishah: her own day and the day of Sawdah."]},"buhuth":{"en":["Her words, “in her skin,” mean: in her place, meaning that I would be she."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5212,"lafz":true},{"key":"muslim","label":"مسلم","number":47}],"full":1,"dr":1,"rep":[9411]},{"num":6390,"demo":false,"sanad":"","matn":["عَنْ مُعَاذَةَ، عَنْ عَائِشَةَ ـ رَضِيَ اللَّهُ عَنْهَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَسْتَأْذِنُ فِي يَوْمِ الْمَرْأَةِ مِنَّا بَعْدَ أَنْ أُنْزِلَتْ هَذِهِ الآيَةُ ﴿تُرْجِئُ مَنْ تَشَاءُ مِنْهُنَّ وَتُؤْوِي إِلَيْكَ مَنْ تَشَاءُ وَمَنِ ابْتَغَيْتَ مِمَّنْ عَزَلْتَ فَلاَ جُنَاحَ عَلَيْكَ﴾ [سورة الأحزاب: 51]}. فَقُلْتُ لَهَا مَا كُنْتِ تَقُولِينَ قَالَتْ كُنْتُ أَقُولُ لَهُ إِنْ كَانَ ذَاكَ إِلَىَّ فَإِنِّي لاَ أُرِيدُ يَا رَسُولَ اللَّهِ أَنْ أُوثِرَ عَلَيْكَ أَحَدًا."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4789) ومسلم في الطلاق (1476) كلاهما من حديث عاصم الأحول، عن معاذة فذكرته.","grade":"متفق عليه","chapter_ar":"باب العدل بين الزوجات في القسم إلا من وهبت نوبتها لضرتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4789) and Muslim (1476).","chapter_en":"Justice Between Wives in Allotment, Except for the One Who Gives Her Turn to Her Co-Wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":30,"content":{"translation":{"en":["Muʿadhah narrated from ʿA’ishah that the Messenger of Allah ﷺ used to ask permission on the day of each one of us, after this verse had been revealed: “You may defer whom you will of them and take to yourself whom you will, and whomever you desire of those you had set aside—there is no blame upon you.” [al-Ahzab: 51] I said to her: What did you used to say? She said: I used to say to him: If that were left to me, then, O Messenger of Allah, I would not wish to prefer anyone over you."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4789,"lafz":true},{"key":"muslim","label":"مسلم","number":1476}],"full":1,"rep":[13090]},{"num":6391,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: يَا ابْنَ أُخْتِي كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ يُفضّل بَعْضَنَا عَلَى بَعْضٍ فِي الْقَسْمِ، مِنْ مُكْثِهِ عِنْدَنَا، وَكَانَ قلّ يَوْمٌ إِلاَّ وَهُوَ يَطُوفُ عَلَيْنَا جَمِيعًا، فَيَدْنُو مِنْ كُلِّ امْرَأَةٍ مِنْ غَيْرِ مَسِيسٍ حَتَّى يَبْلُغَ إِلَى الَّتِي هُوَ يَوْمُهَا فَيَبِيتُ عِنْدَهَا. وَلْقَدْ قَالَتْ سَوْدَةُ بِنْتُ زَمْعَةَ حِينَ أَسَنَّتْ، وَفَرِقَتْ أَنْ يُفَارِقَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَا رَسُولَ اللَّهِ يَوْمِي لِعَائِشَةَ، فَقَبِلَ ذَلِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْهَا. قَالَتْ: نَقُولُ فِي ذَلِكَ: أَنْزَلَ اللَّهُ عزوجل وَفِي أَشْبَاهِهَا أُرَاهُ قَالَ: ﴿وَإِنِ امْرَأَةٌ خَافَتْ مِنْ بَعْلِهَا نُشُوزًا﴾ [النساء: ١٢٨]"],"takhrij":"حسن: رواه أبو داود (2135) ومن طريقه البيهقي (7/47) والحاكم (2/186) كلاهما من طريق أحمد بن يونس، حدثنا عبد الرحمن بن أبي الزناد، عن هشام بن عروة، عن أبيه قال: قالت عائشة فذكرته.","grade":"حسن","chapter_ar":"باب العدل بين الزوجات في القسم إلا من وهبت نوبتها لضرتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2135), and through him al-Bayhaqi (7/47), and al-Hakim (2/186).","chapter_en":"Justice Between Wives in Allotment, Except for the One Who Gives Her Turn to Her Co-Wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":30,"content":{"translation":{"en":["ʿA’ishah said: O son of my sister, the Messenger of Allah ﷺ did not favor some of us over others in how long he stayed with us when dividing his time. There was hardly a day when he would not go around to all of us, drawing near to each woman without intimacy, until he reached the one whose day it was, and then he would spend the night with her. Sawdah bint Zamʿah, when she grew old and feared that the Messenger of Allah ﷺ might separate from her, said: O Messenger of Allah, my day is for ʿA’ishah. So the Messenger of Allah ﷺ accepted that from her. She said: We say that regarding this, and similar cases, Allah the Mighty and Majestic revealed, as I think: “And if a woman fears ill-treatment or aversion from her husband…” [al-Nisa’: 128]"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2135,"lafz":true},{"key":"kubrabayhaqi","label":"ومن طريقه البيهقي","number":47},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":13434,"n":13562},{"key":"hakim","label":"المستدرك على الصحيحين","number":2760,"n":2746}],"full":1,"dr":1},{"num":6392,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعِنْدَهُ تِسْعُ نِسْوَةٍ يُصِيبُهُنَّ إِلاَّ سَوْدَةَ فَإِنَّهَا وَهَبَتْ يَوْمَهَا وَلَيْلَتَهَا لِعَائِشَةَ."],"takhrij":"صحيح: رواه النسائي (3197) عن إبراهيم بن يعقوب، قال: ثنا ابن أبي مريم، قال: أخبرنا سفيان قال: حدثني عمرو بن دينار، عن عطاء، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب العدل بين الزوجات في القسم إلا من وهبت نوبتها لضرتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3197).","chapter_en":"Justice Between Wives in Allotment, Except for the One Who Gives Her Turn to Her Co-Wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":30,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ died while he had nine wives with whom he had marital relations, except Sawdah, for she had given her day and night to ʿA’ishah."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3197,"lafz":true,"n":3197}],"full":1,"dr":1},{"num":6393,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ كَانَتْ لَهُ امْرَأَتَانِ يَمِيلُ مَعَ إِحْدَاهُمَا عَلَى الأُخْرَى جَاءَ يَوْمَ الْقِيَامَةِ وَأَحَدُ شِقَّيْهِ سَاقِطٌ."],"takhrij":"صحيح: رواه أبو داود (2133) والترمذي (1141) والنسائي (3942) وابن ماجة (1969) وابن الجارود (722) وصحّحه ابن حبان (4207) والحاكم (2/186) كلهم من حديث همام بن يحيى، عن قتادة، عن النضر بن أنس، عن بشير بن نَهيك، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء فيمن لم يعدل بين نسائه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2133), al-Tirmidhi (1141), al-Nasa’i (3942), Ibn Majah (1969), and Ibn al-Jarud (722).","chapter_en":"What Has Been Reported About One Who Does Not Deal Justly Between His Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":31,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “Whoever has two wives and inclines toward one over the other will come on the Day of Resurrection with one side of his body fallen.”"]},"buhuth":{"en":["His words, “inclines toward one over the other,” mean in the rights of companionship, such as food, drink, and clothing, not the inclination of the heart, for hearts are not under one’s control."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2133,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1141},{"key":"nasai","label":"النسائي","number":3942},{"key":"ibnmajah","label":"ابن ماجه","number":1969},{"key":"sh13071","label":"ابن الجارود","number":722},{"key":"sh13075","label":"النفقة على العيال لابن أبي الدنيا","number":513,"n":508},{"key":"ibnhibban","label":"ابن حبان","number":4207}],"full":1,"dr":1},{"num":6394,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا {وَإِنِ امْرَأَةٌ خَافَتْ مِنْ بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًا} قَالَتْ هِيَ الْمَرْأَةُ تَكُونُ عِنْدَ الرَّجُلِ، لاَ يَسْتَكْثِرُ مِنْهَا فَيُرِيدُ طَلاَقَهَا، وَيَتَزَوَّجُ غَيْرَهَا، تَقُولُ لَهُ أَمْسِكْنِي وَلاَ تُطَلِّقْنِي، ثُمَّ تَزَوَّجْ غَيْرِي، فَأَنْتَ فِي حِلٍّ مِنَ النَّفَقَةِ عَلَىَّ وَالْقِسْمَةِ لِي، فَذَلِكَ قَوْلُهُ تَعَالَى ﴿فَلاَ جُنَاحَ عَلَيْهِمَا أَنْ يَصَّالَحَا بَيْنَهُمَا صُلْحًا وَالصُّلْحُ خَيْرٌ﴾ [سورة النساء: 128]}"],"takhrij":"متفق عليه: رواه البخاري في النكاح (5206) عن ابن سلام، أخبرنا أبو معاوية، عن هشام، عن أبيه، عن عائشة فذكرته. ورواه مسلم في التفسير (3021) من وجهين آخرين عن هشام مختصراً.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تصالح الزوجين على عدم النفقة والقسمة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5206) and Muslim (3021).","chapter_en":"What Has Been Reported About a Husband and Wife Reconciling Over Waiving Maintenance and Division","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":33,"content":{"translation":{"en":["ʿA’ishah said concerning the verse, “And if a woman fears ill-treatment or aversion from her husband…” [al-Nisa’: 128]: It refers to a woman who is with a man who no longer has much desire for her, so he wants to divorce her and marry another. She says to him: Keep me and do not divorce me, then marry someone else; you are released from spending on me and from dividing your time for me. That is the meaning of His saying, Exalted is He: “Then there is no sin upon them if they make terms of settlement between them, and settlement is best.” [al-Nisa’: 128]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5206,"lafz":true},{"key":"muslim","label":"مسلم","number":3021}],"full":1},{"num":6395,"demo":false,"sanad":"","matn":["عن ابن عباس قال: خشيت سودة أن يُطلِّقها النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فقالت: لا تُطلقني، وأمسِكني، واجعلْ يومي لعائشة. ففعل. فنزلت: ﴿فَلَا جُنَاحَ عَلَيْهِمَا أَنْ يُصْلِحَا بَيْنَهُمَا صُلْحًا وَالصُّلْحُ خَيْرٌ﴾ [ النساء: ١٢٨]"],"takhrij":"حسن: رواه الترمذي (3040) حدثنا محمد بن المثنى، حدثنا أبو داود الطيالسي، حدثنا سليمان بن معاذ، عن سماك، عن عكرمة، عن ابن عباس فذكره. والحديث في مسند أبي داود (2805) ومن طريقه أخرجه أيضا البيهقي (7/297)","grade":"حسن","chapter_ar":"باب ما جاء في تصالح الزوجين على عدم النفقة والقسمة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (3040) and al-Bayhaqi (7/297). Al-Tirmidhi said: “Hasan sahih gharib.”","chapter_en":"What Has Been Reported About a Husband and Wife Reconciling Over Waiving Maintenance and Division","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":33,"content":{"translation":{"en":["Ibn ʿAbbas said: Sawdah feared that the Prophet ﷺ might divorce her, so she said: Do not divorce me; keep me, and give my day to ʿA’ishah. So he did that. Then the verse was revealed: “Then there is no sin upon them if they make terms of settlement between them, and settlement is best.” [al-Nisa’: 128]"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":3040,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":297},{"key":"abudawud","label":"الحديث في مسند ابي داود","number":2805}],"full":1,"dr":1},{"num":6396,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ عَنْ عُمَرَ رَضِيَ اللَّهُ عَنْهُمْ دَخَلَ عَلَى حَفْصَةَ فَقَالَ يَا بُنَيَّةِ لاَ يَغُرَّنَّكِ هَذِهِ الَّتِي أَعْجَبَهَا حُسْنُهَا حُبُّ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِيَّاهَا ـ يُرِيدُ عَائِشَةَ ـ فَقَصَصْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَتَبَسَّمَ."],"takhrij":"متفق عليه: أخرجه البخاري في النكاح (5218) عن عبد العزيز بن عبدالله، حدثنا سليمان، عن يحيى، عن عُبيد بن حُنين، سمع ابن عباس، فذكره. وأخرجه مسلم في الطلاق (1479/31) من وجه آخر عن سليمان بن بلال بإسناده مطولا.","grade":"متفق عليه","chapter_ar":"باب جواز حب الرجل بعض زوجاته أكثر من بعض","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5218) and Muslim (1479:31).","chapter_en":"The Permissibility of a Man Loving Some of His Wives More Than Others","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":34,"content":{"translation":{"en":["Ibn ʿAbbas narrated from ʿUmar that he entered upon Hafsah and said: O my daughter, do not let that one whose beauty and the Messenger of Allah’s love for her have impressed her deceive you — meaning ʿA’ishah. I related that to the Messenger of Allah ﷺ, and he smiled."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5218,"lafz":true},{"key":"muslim","label":"مسلم","number":31}],"full":1},{"num":6397,"demo":false,"sanad":"","matn":["عن عَائِشَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ أَرْسَلَ أَزْوَاجُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاطِمَةَ بِنْتَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاسْتَأْذَنَتْ عَلَيْهِ وَهُوَ مُضْطَجِعٌ مَعِي فِي مِرْطِي فَأَذِنَ لَهَا فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ أَزْوَاجَكَ أَرْسَلْنَنِي إِلَيْكَ يَسْأَلْنَكَ الْعَدْلَ فِي ابْنَةِ أَبِي قُحَافَةَ وَأَنَا سَاكِتَةٌ - قَالَتْ - فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَىْ بُنَيَّةُ أَلَسْتِ تُحِبِّينَ مَا أُحِبُّ. فَقَالَتْ بَلَى. قَالَ فَأَحِبِّي هَذِهِ. قَالَتْ فَقَامَتْ فَاطِمَةُ حِينَ سَمِعَتْ ذَلِكَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَجَعَتْ إِلَى أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَتْهُنَّ بِالَّذِي قَالَتْ وَبِالَّذِي قَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْنَ لَهَا مَا نُرَاكِ أَغْنَيْتِ عَنَّا مِنْ شَىْءٍ فَارْجِعِي إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُولِي لَهُ إِنَّ أَزْوَاجَكَ يَنْشُدْنَكَ الْعَدْلَ فِي ابْنَةِ أَبِي قُحَافَةَ. فَقَالَتْ فَاطِمَةُ وَاللَّهِ لاَ أُكَلِّمُهُ فِيهَا أَبَدًا. قَالَتْ عَائِشَةُ فَأَرْسَلَ أَزْوَاجُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ زَيْنَبَ بِنْتَ جَحْشٍ زَوْجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهِيَ الَّتِي كَانَتْ تُسَامِينِي مِنْهُنَّ فِي الْمَنْزِلَةِ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَمْ أَرَ امْرَأَةً قَطُّ خَيْرًا فِي الدِّينِ مِنْ زَيْنَبَ وَأَتْقَى لِلَّهِ وَأَصْدَقَ حَدِيثًا وَأَوْصَلَ لِلرَّحِمِ وَأَعْظَمَ صَدَقَةً وَأَشَدَّ ابْتِذَالاً لِنَفْسِهَا فِي الْعَمَلِ الَّذِي تَصَدَّقُ بِهِ وَتَقَرَّبُ بِهِ إِلَى اللَّهِ تَعَالَى مَا عَدَا سَوْرَةً مِنْ حَدٍّ كَانَتْ فِيهَا تُسْرِعُ مِنْهَا الْفَيْئَةَ قَالَتْ فَاسْتَأْذَنَتْ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَعَ عَائِشَةَ فِي مِرْطِهَا عَلَى الْحَالَةِ الَّتِي دَخَلَتْ فَاطِمَةُ عَلَيْهَا وَهُوَ بِهَا فَأَذِنَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ أَزْوَاجَكَ أَرْسَلْنَنِي إِلَيْكَ يَسْأَلْنَكَ الْعَدْلَ فِي ابْنَةِ أَبِي قُحَافَةَ. قَالَتْ ثُمَّ وَقَعَتْ بِي فَاسْتَطَالَتْ عَلَىَّ وَأَنَا أَرْقُبُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَرْقُبُ طَرْفَهُ هَلْ يَأْذَنُ لِي فِيهَا - قَالَتْ - فَلَمْ تَبْرَحْ زَيْنَبُ حَتَّى عَرَفْتُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ يَكْرَهُ أَنْ أَنْتَصِرَ - قَالَتْ - فَلَمَّا وَقَعْتُ بِهَا لَمْ أَنْشَبْهَا حِينَ أَنْحَيْتُ عَلَيْهَا - قَالَتْ - فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَتَبَسَّمَ إِنَّهَا ابْنَةُ أَبِي بَكْرٍ."],"takhrij":"صحيح: رواه مسلم في فضائل الصحابة (2442) من طريق يعقوب بن إبراهيم بن سعد، حدثني أبي، عن صالح، عن ابن شهاب، أخبرني محمد بن عبد الرحمن بن الحارث بن هشام، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب جواز حب الرجل بعض زوجاته أكثر من بعض","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2442).","chapter_en":"The Permissibility of a Man Loving Some of His Wives More Than Others","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":34,"content":{"translation":{"en":["ʿA’ishah, the wife of the Prophet ﷺ, said: The wives of the Prophet ﷺ sent Fatimah, the daughter of the Messenger of Allah ﷺ, to the Messenger of Allah ﷺ. She asked permission to enter while he was lying with me under my wrap, and he permitted her. She said: O Messenger of Allah, your wives have sent me to ask you to be fair regarding the daughter of Abu Quhafah. I remained silent. The Messenger of Allah ﷺ said to her: “O my daughter, do you not love whom I love?” She said: Yes. He said: “Then love this one.” So Fatimah got up when she heard that from the Messenger of Allah ﷺ. She returned to the wives of the Prophet ﷺ and informed them of what she had said and what the Messenger of Allah ﷺ had said to her. They said to her: We do not think you helped us at all. Go back to the Messenger of Allah ﷺ and tell him: Your wives ask you for fairness regarding the daughter of Abu Quhafah. Fatimah said: By Allah, I will never speak to him about her again. ʿA’ishah said: Then the wives of the Prophet ﷺ sent Zaynab bint Jahsh, the wife of the Prophet ﷺ, and she was the one among them who rivaled me in standing with the Messenger of Allah ﷺ. I never saw a woman better in religion than Zaynab, more mindful of Allah, more truthful in speech, more dutiful to kinship ties, greater in charity, and more willing to exert herself in deeds by which she gave charity and sought nearness to Allah the Exalted — except for some sharpness in her nature from which she would quickly return. She asked permission to enter upon the Messenger of Allah ﷺ while he was with ʿA’ishah under her wrap, in the same condition in which Fatimah had found him, and the Messenger of Allah ﷺ gave her permission. She said: O Messenger of Allah, your wives have sent me to ask you to be fair regarding the daughter of Abu Quhafah. Then she began attacking me and speaking at length against me, while I watched the Messenger of Allah ﷺ and watched his eyes to see whether he would allow me to answer her. Zaynab did not stop until I knew that the Messenger of Allah ﷺ would not dislike my defending myself. Then once I turned on her, I quickly silenced her. The Messenger of Allah ﷺ smiled and said: “She is the daughter of Abu Bakr.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2442,"lafz":true}],"full":1,"dr":1},{"num":6398,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ نِسَاءَ، رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُنَّ حِزْبَيْنِ فَحِزْبٌ فِيهِ عَائِشَةُ وَحَفْصَةُ وَصَفِيَّةُ وَسَوْدَةُ، وَالْحِزْبُ الآخَرُ أُمُّ سَلَمَةَ وَسَائِرُ نِسَاءِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ الْمُسْلِمُونَ قَدْ عَلِمُوا حُبَّ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَائِشَةَ، فَإِذَا كَانَتْ عِنْدَ أَحَدِهِمْ هَدِيَّةٌ يُرِيدُ أَنْ يُهْدِيَهَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَّرَهَا، حَتَّى إِذَا كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَيْتِ عَائِشَةَ بَعَثَ صَاحِبُ الْهَدِيَّةِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَيْتِ عَائِشَةَ، فَكَلَّمَ حِزْبُ أُمِّ سَلَمَةَ، فَقُلْنَ لَهَا كَلِّمِي رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُكَلِّمُ النَّاسَ، فَيَقُولُ مَنْ أَرَادَ أَنْ يُهْدِيَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَدِيَّةً فَلْيُهْدِهِ إِلَيْهِ حَيْثُ كَانَ مِنْ بُيُوتِ نِسَائِهِ، فَكَلَّمَتْهُ أُمُّ سَلَمَةَ بِمَا قُلْنَ، فَلَمْ يَقُلْ لَهَا شَيْئًا، فَسَأَلْنَهَا. فَقَالَتْ مَا قَالَ لِي شَيْئًا. فَقُلْنَ لَهَا فَكَلِّمِيهِ. قَالَتْ فَكَلَّمَتْهُ حِينَ دَارَ إِلَيْهَا أَيْضًا، فَلَمْ يَقُلْ لَهَا شَيْئًا، فَسَأَلْنَهَا. فَقَالَتْ مَا قَالَ لِي شَيْئًا. فَقُلْنَ لَهَا كَلِّمِيهِ حَتَّى يُكَلِّمَكِ. فَدَارَ إِلَيْهَا فَكَلَّمَتْهُ. فَقَالَ لَهَا لاَ تُؤْذِينِي فِي عَائِشَةَ، فَإِنَّ الْوَحْىَ لَمْ يَأْتِنِي، وَأَنَا فِي ثَوْبِ امْرَأَةٍ إِلاَّ عَائِشَةَ. قَالَتْ فَقَالَتْ أَتُوبُ إِلَى اللَّهِ مِنْ أَذَاكَ يَا رَسُولَ اللَّهِ. ثُمَّ إِنَّهُنَّ دَعَوْنَ فَاطِمَةَ بِنْتَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَرْسَلْنَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَقُولُ إِنَّ نِسَاءَكَ يَنْشُدْنَكَ اللَّهَ الْعَدْلَ فِي بِنْتِ أَبِي بَكْرٍ. فَكَلَّمَتْهُ. فَقَالَ يَا بُنَيَّةُ، أَلاَ تُحِبِّينَ مَا أُحِبُّ. قَالَتْ بَلَى. فَرَجَعَتْ إِلَيْهِنَّ، فَأَخْبَرَتْهُنَّ. فَقُلْنَ ارْجِعِي إِلَيْهِ. فَأَبَتْ أَنْ تَرْجِعَ، فَأَرْسَلْنَ زَيْنَبَ بِنْتَ جَحْشٍ، فَأَتَتْهُ فَأَغْلَظَتْ، وَقَالَتْ إِنَّ نِسَاءَكَ يَنْشُدْنَكَ اللَّهَ الْعَدْلَ فِي بِنْتِ ابْنِ أَبِي قُحَافَةَ. فَرَفَعَتْ صَوْتَهَا، حَتَّى تَنَاوَلَتْ عَائِشَةَ. وَهْىَ قَاعِدَةٌ، فَسَبَّتْهَا حَتَّى إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيَنْظُرُ إِلَى عَائِشَةَ هَلْ تَكَلَّمُ قَالَ فَتَكَلَّمَتْ عَائِشَةُ تَرُدُّ عَلَى زَيْنَبَ، حَتَّى أَسْكَتَتْهَا. قَالَتْ فَنَظَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى عَائِشَةَ، وَقَالَ إِنَّهَا بِنْتُ أَبِي بَكْرٍ."],"takhrij":"صحيح: رواه البخاري في الهبة (2581) عن إسماعيل، قال حدثني أخي، عن سليمان، عن هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب جواز حب الرجل بعض زوجاته أكثر من بعض","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2581).","chapter_en":"The Permissibility of a Man Loving Some of His Wives More Than Others","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":34,"content":{"translation":{"en":["ʿA’ishah said: The wives of the Messenger of Allah ﷺ were two parties. One party included ʿA’ishah, Hafsah, Safiyyah, and Sawdah; and the other party was Umm Salamah and the rest of the wives of the Messenger of Allah ﷺ. The Muslims knew of the Messenger of Allah’s love for ʿA’ishah, so if one of them had a gift he wanted to present to the Messenger of Allah ﷺ, he would delay it until the Messenger of Allah ﷺ was in the house of ʿA’ishah. Then the giver would send the gift to the Messenger of Allah while he was in the house of ʿA’ishah. The party of Umm Salamah spoke to her and said: Speak to the Messenger of Allah ﷺ so that he may tell the people: Whoever wants to give a gift to the Messenger of Allah ﷺ should give it to him wherever he may be among the houses of his wives. Umm Salamah spoke to him with what they had said, but he said nothing to her. They asked her, and she said: He said nothing to me. They said: Speak to him again. She said: So I spoke to him again when it was her turn, and he said nothing to me. They asked her, and she said: He said nothing to me. They said: Keep speaking to him until he answers you. So when it was again her turn, she spoke to him, and he said to her: “Do not hurt me concerning ʿA’ishah, for revelation has never come to me while I was under the covering of any woman except ʿA’ishah.” She said: So Umm Salamah said: I repent to Allah from hurting you, O Messenger of Allah. Then they called Fatimah, the daughter of the Messenger of Allah ﷺ, and she sent word to the Messenger of Allah ﷺ saying: Your wives ask you by Allah to be fair regarding the daughter of Abu Bakr. He said to her: “O my daughter, do you not love whom I love?” She said: Yes. Then she returned to them and informed them. They said to her: Go back to him. But she refused to return. Then they sent Zaynab bint Jahsh, who came and spoke harshly, saying: Your wives ask you by Allah to be fair regarding the daughter of Ibn Abi Quhafah. She raised her voice until she turned on ʿA’ishah while she was sitting and insulted her, while the Messenger of Allah ﷺ was looking at ʿA’ishah to see whether she would respond. Then ʿA’ishah answered Zaynab until she silenced her. The Prophet ﷺ looked at ʿA’ishah and said: “She is the daughter of Abu Bakr.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2581,"lafz":true}],"full":1,"dr":1,"rep":[5977]},{"num":6399,"demo":false,"sanad":"","matn":["عن عَائِشَةَ قَالَتْ: مَا عَلِمْتُ حَتَّى دَخَلَتْ عَلَىَّ زَيْنَبُ بِغَيْرِ إِذْنٍ وَهِيَ غَضْبَى. ثُمَّ قَالَتْ يَا رَسُولَ اللَّهِ أَحَسْبُكَ إِذَا قَلَبَتْ لَكَ بُنَيَّةُ أَبِي بَكْرٍ ذُرَيْعَتَيْهَا. ثُمَّ أَقْبَلَتْ عَلَىَّ فَأَعْرَضْتُ عَنْهَا حَتَّى قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دُونَكِ فَانْتَصِرِي. فَأَقْبَلْتُ عَلَيْهَا حَتَّى رَأَيْتُهَا وَقَدْ يَبِسَ رِيقُهَا فِي فِيهَا مَا تَرُدُّ عَلَىَّ شَيْئًا فَرَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَهَلَّلُ وَجْهُهُ."],"takhrij":"حسن: رواه ابن ماجة (1981) والإمام أحمد (24620) والبخاري في الأدب المفرد (558) كلهم من طريق خالد بن سلمة، عن البهي، عن عروة بن الزبير، قال: قالت عائشة فذكرته. واللفظ لهما، واختصره البخاري بقوله: دونك فانتصري","grade":"حسن","chapter_ar":"باب جواز حب الرجل بعض زوجاته أكثر من بعض","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (1981), Imam Ahmad (24620), and al-Bukhari in al-Adab al-Mufrad (558).","chapter_en":"The Permissibility of a Man Loving Some of His Wives More Than Others","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":34,"content":{"translation":{"en":["ʿA’ishah said: Before I realized it, Zaynab entered upon me without permission while she was angry. Then she said: O Messenger of Allah, is it enough for you that the young daughter of Abu Bakr waves her hands in front of you? Then she turned against me. I ignored her until the Prophet ﷺ said: “Go ahead and defend yourself.” So I turned on her until I saw that the saliva in her mouth had dried up and she was unable to answer me at all. Then I saw the Prophet’s face light up with joy."]},"buhuth":{"en":["Her word “dhurayʿatayha” is the diminutive form of dhiraʿ (arm)."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":1981,"lafz":true},{"key":"ahmad","label":"الإمام أحمد","number":24620},{"key":"adab","label":"البخاري في الأدب المفرد","number":558}],"full":1,"dr":1},{"num":6400,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَمْكُثُ عِنْدَ زَيْنَبَ بِنْتِ جَحْشٍ وَيَشْرَبُ عِنْدَهَا عَسَلاً، فَتَوَاصَيْتُ أَنَا وَحَفْصَةُ أَنَّ أَيَّتَنَا دَخَلَ عَلَيْهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلْتَقُلْ: إِنِّي أَجِدُ فِيكَ رِيحَ مَغَافِيرَ، أَكَلْتَ مَغَافِيرَ؟ فَدَخَلَ عَلَى إِحْدَاهُمَا، فَقَالَتْ لَهُ ذَلِكَ، فَقَالَ: بَلْ شَرِبْتُ عَسَلاً عِنْدَ زَيْنَبَ بِنْتِ جَحْشٍ، وَلَنْ أَعُودَ لَهُ فَنَزَلَتْ: ﴿يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاتَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ﴾ [التحريم: ١] لِعَائِشَةَ وَحَفْصَةَ ﴿وَإِذْ أَسَرَّ النَّبِيُّ إِلَى بَعْضِ أَزْوَاجِهِ﴾ [التحريم:3] لِقَوْلِهِ بَلْ شَرِبْتُ عَسَلاً ."],"takhrij":"متفق عليه: رواه البخاري في الطلاق (5267)، ومسلم في الطلاق (20:1474) كلاهما من طريق حجاج بن محمد، عن ابن جريج، قال: زعم عطاء أنه سمع عبيد بن عمير يقول: سمعت عائشة، فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في غيرة الضرائر ومنافستهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5267) and Muslim (1474:20).","chapter_en":"What Has Been Reported About the Jealousy and Rivalry of Co-Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":35,"content":{"translation":{"en":["ʿA’ishah said: The Prophet ﷺ used to stay with Zaynab bint Jahsh and drink honey at her house. So Hafsah and I agreed that whichever of us the Prophet ﷺ entered upon should say: I smell on you the odor of maghafir; have you eaten maghafir? He entered upon one of them, and she said that to him. He said: “Rather, I drank honey at the house of Zaynab bint Jahsh, and I will never return to it.” Then the verse was revealed: “O Prophet, why do you forbid what Allah has made lawful for you…” [al-Tahrim: 1] up to His saying: “If you both repent to Allah…” [al-Tahrim: 4] referring to ʿA’ishah and Hafsah, and “And when the Prophet confided a statement to one of his wives…” [al-Tahrim: 3] referring to his saying: “Rather, I drank honey.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5267,"lafz":true},{"key":"muslim","label":"مسلم","number":20}],"full":1},{"num":6401,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا خَرَجَ أَقْرَعَ بَيْنَ نِسَائِهِ فَطَارَتِ الْقُرْعَةُ عَلَى عَائِشَةَ وَحَفْصَةَ فَخَرَجَتَا مَعَهُ جَمِيعًا وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا كَانَ بِاللَّيْلِ سَارَ مَعَ عَائِشَةَ يَتَحَدَّثُ مَعَهَا فَقَالَتْ حَفْصَةُ لِعَائِشَةَ أَلاَ تَرْكَبِينَ اللَّيْلَةَ بَعِيرِي وَأَرْكَبُ بَعِيرَكِ فَتَنْظُرِينَ وَأَنْظُرُ قَالَتْ بَلَى. فَرَكِبَتْ عَائِشَةُ عَلَى بَعِيرِ حَفْصَةَ وَرَكِبَتْ حَفْصَةُ عَلَى بَعِيرِ عَائِشَةَ فَجَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى جَمَلِ عَائِشَةَ وَعَلَيْهِ حَفْصَةُ فَسَلَّمَ ثُمَّ صَارَ مَعَهَا حَتَّى نَزَلُوا فَافْتَقَدَتْهُ عَائِشَةُ فَغَارَتْ فَلَمَّا نَزَلُوا جَعَلَتْ تَجْعَلُ رِجْلَهَا بَيْنَ الإِذْخِرِ وَتَقُولُ يَا رَبِّ سَلِّطْ عَلَىَّ عَقْرَبًا أَوْ حَيَّةً تَلْدَغُنِي رَسُولُكَ وَلاَ أَسْتَطِيعُ أَنْ أَقُولَ لَهُ شَيْئًا."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5211)، ومسلم في فضائل الصحابة (2445) كلاهما عن أبي نعيم، حدّثنا عبد الواحد بن أيمن، حدّثني ابن أبي مُليكة، عن القاسم بن محمد، عن عائشة قالت (فذكرته) والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في غيرة الضرائر ومنافستهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5211) and Muslim (2445). The wording is from Muslim.","chapter_en":"What Has Been Reported About the Jealousy and Rivalry of Co-Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":35,"content":{"translation":{"en":["ʿA’ishah said: Whenever the Messenger of Allah ﷺ went out on a journey, he would cast lots among his wives. The lot fell to ʿA’ishah and Hafsah, so they both went with him. At night the Messenger of Allah ﷺ would travel with ʿA’ishah and speak with her. So Hafsah said to ʿA’ishah: Will you ride my camel tonight and I ride your camel, so you may look around and I may look around? She said: Yes. So ʿA’ishah rode on Hafsah’s camel, and Hafsah rode on ʿA’ishah’s camel. Then the Messenger of Allah ﷺ came to the camel of ʿA’ishah, but Hafsah was on it. He greeted her and traveled with her until they stopped. Then ʿA’ishah missed him and became jealous. When they stopped, she began putting her feet among the idhkhir grass and saying: O Lord, send against me a scorpion or a snake to bite me. He is Your Messenger, and I cannot say anything to him."]},"buhuth":{"en":["Her words “Your Messenger” are in the nominative, as the predicate of an omitted subject, meaning: He is Your Messenger, and I cannot say anything concerning him. It is as though she was overcome, so because of the intensity of her jealousy for the Messenger of Allah ﷺ, she ended up supplicating against herself and said nothing against Hafsah, since Hafsah had only done so after ʿA’ishah willingly agreed, so she turned the blame back upon herself."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5211,"lafz":true},{"key":"muslim","label":"مسلم","number":2445}],"full":1,"dr":1,"rep":[10396]},{"num":6402,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُحِبُّ الْعَسَلَ وَالْحَلْوَاءَ، وَكَانَ إِذَا انْصَرَفَ مِنَ الْعَصْرِ دَخَلَ عَلَى نِسَائِهِ، فَيَدْنُو مِنْ إِحْدَاهُنَّ، فَدَخَلَ عَلَى حَفْصَةَ بِنْتِ عُمَرَ، فَاحْتَبَسَ أَكْثَرَ مَا كَانَ يَحْتَبِسُ، فَغِرْتُ فَسَأَلْتُ عَنْ ذَلِكَ فَقِيلَ لِي أَهْدَتْ لَهَا امْرَأَةٌ مِنْ قَوْمِهَا عُكَّةً مِنْ عَسَلٍ، فَسَقَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْهُ شَرْبَةً، فَقُلْتُ أَمَا وَاللَّهِ لَنَحْتَالَنَّ لَهُ. فَقُلْتُ لِسَوْدَةَ بِنْتِ زَمْعَةَ إِنَّهُ سَيَدْنُو مِنْكِ، فَإِذَا دَنَا مِنْكِ فَقُولِي أَكَلْتَ مَغَافِيرَ فَإِنَّهُ سَيَقُولُ لَكِ لاَ. فَقُولِي لَهُ مَا هَذِهِ الرِّيحُ الَّتِي أَجِدُ مِنْكَ فَإِنَّهُ سَيَقُولُ لَكِ سَقَتْنِي حَفْصَةُ شَرْبَةَ عَسَلٍ فَقُولِي لَهُ جَرَسَتْ نَحْلُهُ الْعُرْفُطَ. وَسَأَقُولُ ذَلِكَ، وَقُولِي أَنْتِ يَا صَفِيَّةُ ذَاكِ. قَالَتْ تَقُولُ سَوْدَةُ فَوَاللَّهِ مَا هُوَ إِلاَّ أَنْ قَامَ عَلَى الْبَابِ، فَأَرَدْتُ أَنْ أُبَادِيَهُ بِمَا أَمَرْتِنِي بِهِ فَرَقًا مِنْكِ، فَلَمَّا دَنَا مِنْهَا قَالَتْ لَهُ سَوْدَةُ يَا رَسُولَ اللَّهِ أَكَلْتَ مَغَافِيرَ قَالَ لاَ. قَالَتْ فَمَا هَذِهِ الرِّيحُ الَّتِي أَجِدُ مِنْكَ. قَالَ سَقَتْنِي حَفْصَةُ شَرْبَةَ عَسَلٍ. فَقَالَتْ جَرَسَتْ نَحْلُهُ الْعُرْفُطَ فَلَمَّا دَارَ إِلَىَّ قُلْتُ لَهُ نَحْوَ ذَلِكَ، فَلَمَّا دَارَ إِلَى صَفِيَّةَ قَالَتْ لَهُ مِثْلَ ذَلِكَ فَلَمَّا دَارَ إِلَى حَفْصَةَ قَالَتْ يَا رَسُولَ اللَّهِ أَلاَ أَسْقِيكَ مِنْهُ. قَالَ لاَ حَاجَةَ لِي فِيهِ. قَالَتْ تَقُولُ سَوْدَةُ وَاللَّهِ لَقَدْ حَرَمْنَاهُ. قُلْتُ لَهَا اسْكُتِي."],"takhrij":"متفق عليه: رواه البخاري في الطلاق (5268) من طريق علي بن مسهر، ومسلم في الطلاق (21:1474) من طريق أبي أسامة – كلاهما عن هشام بن عروة، عن أبيه، عن عائشة، فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في غيرة الضرائر ومنافستهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5268) and Muslim (1474:21). Her word “jarasat” means: it ate.","chapter_en":"What Has Been Reported About the Jealousy and Rivalry of Co-Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":35,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ loved honey and sweets. When he finished the ʿAsr prayer, he would go to his wives and draw near to one of them. He entered upon Hafsah bint ʿUmar and stayed longer than he usually stayed, so I became jealous and asked about that. It was said: A woman from her people had gifted her a small skin container of honey, and she gave the Prophet ﷺ a drink from it. I said: By Allah, we will devise a plan for him. So I said to Sawdah bint Zamʿah: He will come near you, and when he comes near you, say: “Have you eaten maghafir?” He will say to you: “No.” Then say to him: “What is this smell I notice from you?” He will say: “Hafsah gave me a drink of honey.” Then say to him: “The bee must have fed on the ʿurfut shrub.” I will say that too, and you too, O Safiyyah, say the same. Sawdah said: By Allah, as soon as he stood at the door I wanted to confront him with what you had instructed me, out of fear of you. When he drew near to her, Sawdah said: O Messenger of Allah, have you eaten maghafir? He said: “No.” She said: Then what is this smell I notice from you? He said: “Hafsah gave me a drink of honey.” She said: The bee must have fed on the ʿurfut shrub. Then when he came to me, I said something similar to him, and when he went to Safiyyah, she said the same to him. Then when he went to Hafsah, she said: O Messenger of Allah, shall I give you more of it to drink? He said: “I have no need for it.” Sawdah said: By Allah, we have made him forbid it. I said to her: Be quiet."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5268,"lafz":true},{"key":"muslim","label":"مسلم","number":21}],"full":1,"dr":1},{"num":6403,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ مِنْ عِنْدِهَا لَيْلاً قَالَتْ: فَغِرْتُ عَلَيْهِ فَجَاءَ فَرَأَى مَا أَصْنَعُ فَقَالَ: مالكِ؟ يَا عَائِشَةُ أَغِرْتِ؟ فَقُلْتُ: وَمَا لِي لاَ يَغَارُ مِثْلِي عَلَى مِثْلِكَ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَقَدْ جَاءَكِ شَيْطَانُكِ؟ قَالَتْ: يَا رَسُولَ اللَّهِ أَوْ معي شَيْطَانٌ؟ قَالَ: نَعَمْ، قُلْتُ: وَمَعَ كُلِّ إِنْسَانٍ؟ قَالَ: نَعَمْ. قُلْتُ: وَمَعَكَ يَا رَسُولَ اللَّهِ؟ قَالَ: نَعَمْ، وَلَكِنْ رَبِّي أَعَانَنِي عَلَيْهِ حَتَّى أَسْلَمَ."],"takhrij":"صحيح: رواه مسلم في صفة القيامة والجنة والنار (2815) عن هارون بن سعيد الأيلي، حدثنا ابن وهب، أخبرني أبو صخر، عن ابن قسيط، حدثه أن عروة، حدثه أن عائشة زوج النبي صلى الله عليه وسلم حدثته فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في غيرة الضرائر ومنافستهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2815).","chapter_en":"What Has Been Reported About the Jealousy and Rivalry of Co-Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":35,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ went out from her at night. She said: I became jealous over him. Then he returned and saw what I was doing and said: “What is the matter, O ʿA’ishah? Have you become jealous?” I said: Why should someone like me not be jealous over someone like you? The Messenger of Allah ﷺ said: “Has your devil come to you?” She said: O Messenger of Allah, do I have a devil with me? He said: “Yes.” I said: And with every person? He said: “Yes.” I said: Even with you, O Messenger of Allah? He said: “Yes, but my Lord helped me against him until he submitted.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2815,"lafz":true}],"full":1},{"num":6404,"demo":false,"sanad":"","matn":["عن عَائِشَةَ قَالَتِ الْتَمَسْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَدْخَلْتُ يَدِي فِي شَعْرِهِ فَقَالَ قَدْ جَاءَكِ شَيْطَانُكِ. فَقُلْتُ أَمَا لَكَ شَيْطَانٌ فَقَالَ بَلَى وَلَكِنَّ اللَّهَ أَعَانَنِي عَلَيْهِ فَأَسْلَمَ."],"takhrij":"صحيح: رواه النسائي (3960) عن قتيبة قال: حدثنا الليث، عن يحيى وهو ابن سعيد الأنصاري، عن عبادة بن الوليد بن عبادة بن الصامت، أن عائشة قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في غيرة الضرائر ومنافستهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasāʾī (3960).","chapter_en":"What Has Been Reported About the Jealousy and Rivalry of Co-Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":35,"content":{"translation":{"en":["ʿĀʾishah reported: I looked for the Messenger of Allah ﷺ and put my hand into his hair. He said: “Your devil has come to you.” I asked: “Do you also have a devil?” He replied: “Yes, but Allah helped me against him, so he submitted.”"]},"buhuth":{"en":["Her statement, “I put my hand into his hair,” means that she wanted to determine whether his hair was wet from bathing or not.","His statement, “Your devil has come to you,” means that the devil caused her to think that he had gone to one of his other wives during her allotted turn and night."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3960,"lafz":true}],"full":1,"dr":1},{"num":6405,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّهَا قَالَتْ مَا غِرْتُ عَلَى امْرَأَةٍ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَمَا غِرْتُ عَلَى خَدِيجَةَ، لِكَثْرَةِ ذِكْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِيَّاهَا وَثَنَائِهِ عَلَيْهَا، وَقَدْ أُوحِيَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُبَشِّرَهَا بِبَيْتٍ لَهَا فِي الْجَنَّةِ مِنْ قَصَبٍ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5229)، ومسلم في فضائل الصحابة (74:2435) كلاهما من طريق هشام بن عروة قال: أخبرني أبي، عن عائشة، فذكرته واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في غيرة الضرائر ومنافستهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5229) and Muslim (2435:74). The wording is from al-Bukhari.","chapter_en":"What Has Been Reported About the Jealousy and Rivalry of Co-Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":35,"content":{"translation":{"en":["ʿA’ishah said: I was never jealous of any wife of the Messenger of Allah ﷺ as much as I was jealous of Khadijah, because the Messenger of Allah ﷺ mentioned her often and praised her greatly. And it was revealed to the Messenger of Allah ﷺ that he should give her glad tidings of a house for her in Paradise made of qasab."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5229,"lafz":true},{"key":"muslim","label":"مسلم","number":2435},{"key":"muslim","label":"مسلم في فضائل الصحابه","number":74}],"full":1},{"num":6406,"demo":false,"sanad":"","matn":["عن عَائِشَةَ قَالَتْ: أَلاَ أُحَدِّثُكُمْ عَنِّي وَعَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قُلْنَا بَلَى. قَالَ قَالَتْ لَمَّا كَانَتْ لَيْلَتِيَ الَّتِي كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهَا عِنْدِي انْقَلَبَ فَوَضَعَ رِدَاءَهُ وَخَلَعَ نَعْلَيْهِ فَوَضَعَهُمَا عِنْدَ رِجْلَيْهِ وَبَسَطَ طَرَفَ إِزَارِهِ عَلَى فِرَاشِهِ فَاضْطَجَعَ فَلَمْ يَلْبَثْ إِلاَّ رَيْثَمَا ظَنَّ أَنْ قَدْ رَقَدْتُ فَأَخَذَ رِدَاءَهُ رُوَيْدًا وَانْتَعَلَ رُوَيْدًا وَفَتَحَ الْبَابَ فَخَرَجَ ثُمَّ أَجَافَهُ رُوَيْدًا فَجَعَلْتُ دِرْعِي فِي رَأْسِي وَاخْتَمَرْتُ وَتَقَنَّعْتُ إِزَارِي ثُمَّ انْطَلَقْتُ عَلَى إِثْرِهِ حَتَّى جَاءَ الْبَقِيعَ فَقَامَ فَأَطَالَ الْقِيَامَ ثُمَّ رَفَعَ يَدَيْهِ ثَلاَثَ مَرَّاتٍ ثُمَّ انْحَرَفَ فَانْحَرَفْتُ فَأَسْرَعَ فَأَسْرَعْتُ فَهَرْوَلَ فَهَرْوَلْتُ فَأَحْضَرَ فَأَحْضَرْتُ فَسَبَقْتُهُ فَدَخَلْتُ فَلَيْسَ إِلاَّ أَنِ اضْطَجَعْتُ فَدَخَلَ فَقَالَ مَا لَكِ يَا عَائِشُ حَشْيَا رَابِيَةً. قَالَتْ قُلْتُ لاَ شَىْءَ. قَالَ لَتُخْبِرِينِي أَوْ لَيُخْبِرَنِّي اللَّطِيفُ الْخَبِيرُ. قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ بِأَبِي أَنْتَ وَأُمِّي. فَأَخْبَرْتُهُ قَالَ فَأَنْتِ السَّوَادُ الَّذِي رَأَيْتُ أَمَامِي. قُلْتُ نَعَمْ. فَلَهَدَنِي فِي صَدْرِي لَهْدَةً أَوْجَعَتْنِي ثُمَّ قَالَ أَظَنَنْتِ أَنْ يَحِيفَ اللَّهُ عَلَيْكِ وَرَسُولُهُ. قَالَتْ مَهْمَا يَكْتُمِ النَّاسُ يَعْلَمْهُ اللَّهُ نَعَمْ. قَالَ فَإِنَّ جِبْرِيلَ أَتَانِي حِينَ رَأَيْتِ فَنَادَانِي فَأَخْفَاهُ مِنْكِ فَأَجَبْتُهُ فَأَخْفَيْتُهُ مِنْكِ وَلَمْ يَكُنْ يَدْخُلُ عَلَيْكِ وَقَدْ وَضَعْتِ ثِيَابَكِ وَظَنَنْتُ أَنْ قَدْ رَقَدْتِ فَكَرِهْتُ أَنْ أُوقِظَكِ وَخَشِيتُ أَنْ تَسْتَوْحِشِي فَقَالَ إِنَّ رَبَّكَ يَأْمُرُكَ أَنْ تَأْتِيَ أَهْلَ الْبَقِيعِ فَتَسْتَغْفِرَ لَهُمْ. قَالَتْ قُلْتُ كَيْفَ أَقُولُ لَهُمْ يَا رَسُولَ اللَّهِ قَالَ قُولِي السَّلاَمُ عَلَى أَهْلِ الدِّيَارِ مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ وَيَرْحَمُ اللَّهُ الْمُسْتَقْدِمِينَ مِنَّا وَالْمُسْتَأْخِرِينَ وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَلاَحِقُونَ."],"takhrij":"صحيح: رواه مسلم في الجنائز (103:974) عن هارون بن سعيد الأيلي، حدثنا عبدالله بن وهب، أخبرنا ابن جريج، عن عبد الله بن كثير بن المطلب، أنه سمع محمد بن قيس يقول: سمعت عائشة فقالت: فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في غيرة الضرائر ومنافستهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (974:103). His word “hashyā” means, with the letter shīn: breathing heavily, as happens to one who walks quickly. “Rābiyah” means with the belly rising and falling. His words “that Allah and His Messenger would deal unjustly with you” come from ḥayf, meaning injustice — that the Messenger would go to another wife during your allotted turn. This is something impossible from the Prophet ﷺ, who is the example for all believers. This also indicates that division of turns was obligatory upon him, since abandoning it would not be called injustice unless it were obligatory.","chapter_en":"What Has Been Reported About the Jealousy and Rivalry of Co-Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":35,"content":{"translation":{"en":["ʿA’ishah said: Shall I not tell you about myself and the Messenger of Allah ﷺ? We said: Yes. She said: On my night, when the Prophet ﷺ was with me, he turned over, placed down his cloak, removed his sandals and placed them by his feet, spread the edge of his lower garment over his bed, and lay down. He stayed only until he thought I had fallen asleep. Then he took his cloak gently, put on his sandals gently, opened the door and went out, then closed it gently. I put my outer garment over my head, covered myself, and wrapped my waistcloth tightly, then went after him until he came to al-Baqiʿ. He stood for a long time, then raised his hands three times. Then he turned away, and I turned away. He hurried, and I hurried. He jogged, and I jogged. He went faster, and I went faster. Then I got there before him, entered, and had just lain down when he entered. He said: “What is the matter, O ʿA’ishah? Are you out of breath and heaving?” She said: I said: Nothing. He said: “You will tell me, or the Subtle, the All-Aware will tell me.” She said: I said: O Messenger of Allah, may my father and mother be sacrificed for you, and then I told him. He said: “So you were the dark figure I saw ahead of me?” I said: Yes. Then he struck me on the chest in a way that hurt me and said: “Did you think that Allah and His Messenger would deal unjustly with you?” She said: However much people hide, Allah knows it — yes. He said: “Jibril came to me when you saw me, and he called me quietly so that you would not hear, and I answered him quietly so that you would not hear. He would not enter upon you while you had taken off your clothes. I thought that you had gone to sleep, so I disliked waking you and feared that you might feel lonely. He said: Your Lord commands you to go to the people of al-Baqiʿ and seek forgiveness for them.” She said: I said: How should I speak to them, O Messenger of Allah? He said: “Say: Peace be upon the people of these dwellings from among the believers and Muslims. May Allah have mercy on those of us who have gone ahead and those who come later. And we, if Allah wills, will join you.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":974,"lafz":true,"n":2256},{"key":"muslim","label":"مسلم في الجنائز","number":103}],"full":1,"dr":1},{"num":6407,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتِ افْتَقَدْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ فَظَنَنْتُ أَنَّهُ ذَهَبَ إِلَى بَعْضِ نِسَائِهِ فَتَحَسَّسْتُ ثُمَّ رَجَعْتُ فَإِذَا هُوَ رَاكِعٌ أَوْ سَاجِدٌ يَقُولُ سُبْحَانَكَ وَبِحَمْدِكَ لاَ إِلَهَ إِلاَّ أَنْتَ. فَقُلْتُ بِأَبِي أَنْتَ وَأُمِّي إِنِّي لَفِي شَأْنٍ وَإِنَّكَ لَفِي آخَرَ."],"takhrij":"صحيح: رواه مسلم في الصلاة (485)، من طريق عبد الرزاق، أخبرنا ابن جريج، قال: قلت لعطاء: كيف تقول أنت في الركوع؟ قال: أما سبحانك وبحمدك لا إله إلا أنت، فأخبرني ابن أبي مليكة، عن عائشة به.","grade":"صحيح","chapter_ar":"باب ما جاء في غيرة الضرائر ومنافستهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (485).","chapter_en":"What Has Been Reported About the Jealousy and Rivalry of Co-Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":35,"content":{"translation":{"en":["ʿA’ishah said: I missed the Prophet ﷺ one night and thought that he had gone to one of his wives. So I began searching, then returned, and there he was bowing or prostrating, saying: “Glory be to You and praise be to You; there is no god but You.” So I said: May my father and mother be sacrificed for you — I was occupied with one matter while you were occupied with another."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":485,"lafz":true}],"full":1,"rep":[2122,10998]},{"num":6408,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ جَاءَ زَيْدُ بْنُ حَارِثَةَ يَشْكُو فَجَعَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ اتَّقِ اللَّهَ، وَأَمْسِكْ عَلَيْكَ زَوْجَكَ. قَالَتْ عَائِشَةُ لَوْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَاتِمًا شَيْئًا لَكَتَمَ هَذِهِ. قَالَ فَكَانَتْ زَيْنَبُ تَفْخَرُ عَلَى أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَقُولُ زَوَّجَكُنَّ أَهَالِيكُنَّ، وَزَوَّجَنِي اللَّهُ تَعَالَى مِنْ فَوْقِ سَبْعِ سَمَوَاتٍ."],"takhrij":"صحيح: رواه البخاري في التوحيد (7420)، عن أحمد، حدثنا محمد بن أبي بكر المقدمي، حدثنا حماد بن زيد، عن ثابت، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في غيرة الضرائر ومنافستهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7420).","chapter_en":"What Has Been Reported About the Jealousy and Rivalry of Co-Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":35,"content":{"translation":{"en":["Anas said: Zayd ibn Harithah came complaining, and the Prophet ﷺ kept saying to him: “Fear Allah and keep your wife.” ʿA’ishah said: If the Messenger of Allah ﷺ were to have concealed anything, he would have concealed this. Anas said: Zaynab used to boast to the wives of the Prophet ﷺ, saying: Your families married you off, but Allah married me from above seven heavens."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7420,"lafz":true}],"full":1,"rep":[9415]},{"num":6409,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ بَعْضِ نِسَائِهِ فَأَرْسَلَتْ إِحْدَى أُمَّهَاتِ الْمُؤْمِنِينَ بِصَحْفَةٍ فِيهَا طَعَامٌ، فَضَرَبَتِ الَّتِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَيْتِهَا يَدَ الْخَادِمِ فَسَقَطَتِ الصَّحْفَةُ فَانْفَلَقَتْ، فَجَمَعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِلَقَ الصَّحْفَةِ، ثُمَّ جَعَلَ يَجْمَعُ فِيهَا الطَّعَامَ الَّذِي كَانَ فِي الصَّحْفَةِ وَيَقُولُ غَارَتْ أُمُّكُمْ، ثُمَّ حَبَسَ الْخَادِمَ حَتَّى أُتِيَ بِصَحْفَةٍ مِنْ عِنْدِ الَّتِي هُوَ فِي بَيْتِهَا، فَدَفَعَ الصَّحْفَةَ الصَّحِيحَةَ إِلَى الَّتِي كُسِرَتْ صَحْفَتُهَا، وَأَمْسَكَ الْمَكْسُورَةَ فِي بَيْتِ الَّتِي كَسَرَتْ فِيه."],"takhrij":"صحيح: رواه البخاري في النكاح (5225)، عن علي، حدثنا ابن علية، عن حُميد، عن أنس قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في غيرة الضرائر ومنافستهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5225).","chapter_en":"What Has Been Reported About the Jealousy and Rivalry of Co-Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":35,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet ﷺ was with one of his wives when one of the Mothers of the Believers sent a bowl containing food. The wife in whose house the Prophet ﷺ was struck the servant’s hand, so the bowl fell and broke. The Prophet ﷺ gathered the broken pieces of the bowl and began collecting into it the food that had been in it, saying: “Your mother became jealous.” Then he kept the servant until another bowl was brought from the house of the wife with whom he was staying. He gave the sound bowl to the one whose bowl had been broken, and kept the broken one in the house where it had been broken."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5225,"lafz":true}],"full":1,"dr":1},{"num":6410,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ، أَنَّهَا - يَعْنِي - أَتَتْ بِطَعَامٍ فِي صَحْفَةٍ لَهَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابِهِ فَجَاءَتْ عَائِشَةُ مُتَّزِرَةً بِكِسَاءٍ وَمَعَهَا فِهْرٌ فَفَلَقَتْ بِهِ الصَّحْفَةَ فَجَمَعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ فِلْقَتَىِ الصَّحْفَةِ وَيَقُولُ كُلُوا غَارَتْ أُمُّكُمْ. مَرَّتَيْنِ ثُمَّ أَخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَحْفَةَ عَائِشَةَ فَبَعَثَ بِهَا إِلَى أُمِّ سَلَمَةَ وَأَعْطَى صَحْفَةَ أُمِّ سَلَمَةَ عَائِشَةَ."],"takhrij":"صحيح: رواه النسائي (3965)، عن الربيع بن سليمان، قال: حدثنا أسد بن موسى، حدثنا حمـاد بن سلمة، عن ثابت، عن أبي المتوكل، عن أم سلمة فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في غيرة الضرائر ومنافستهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3965).","chapter_en":"What Has Been Reported About the Jealousy and Rivalry of Co-Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":35,"content":{"translation":{"en":["Umm Salamah brought food in a bowl of hers to the Messenger of Allah ﷺ and his companions. Then ʿA’ishah came wrapped in a garment, carrying a stone, and she split the bowl with it. The Prophet ﷺ gathered the two broken pieces of the bowl together and said: “Eat; your mother has become jealous,” twice. Then the Messenger of Allah ﷺ took ʿA’ishah’s bowl and sent it to Umm Salamah, and gave Umm Salamah’s bowl to ʿA’ishah."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3965,"lafz":true}],"full":1,"dr":1},{"num":6411,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْغَيْرَةِ مَا يُحِبُّ اللَّهُ وَمِنْهَا مَا يَكْرَهُ اللَّهُ فَأَمَّا مَا يُحِبُّ فَالْغَيْرَةُ فِي الرِّيبَةِ وَأَمَّا مَا يَكْرَهُ فَالْغَيْرَةُ فِي غَيْرِ رِيبَةٍ."],"takhrij":"حسن: رواه ابن ماجه (1996) عن محمد بن إسماعيل، قال: حدثنا وكيع، عن شيبان أبي معاوية، عن يحيى بن أبي كثير، عن أبي سهْم- أبي شهم- عن أبي هريرة قال: فذكره وإسناده صحيح.","grade":"حسن","chapter_ar":"باب ما جاء في غيرة الضرائر ومنافستهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (1996).","chapter_en":"What Has Been Reported About the Jealousy and Rivalry of Co-Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":35,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “Some jealousy is loved by Allah, and some of it is disliked by Allah. As for the jealousy that Allah loves, it is jealousy where there is reason for suspicion. As for the jealousy that Allah dislikes, it is jealousy where there is no reason for suspicion.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":1996,"lafz":true}],"full":1,"dr":1},{"num":6412,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: لَمَّا ثَقُلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَاشْتَدَّ بِهِ وَجَعُهُ، اسْتَأْذَنَ أَزْوَاجَهُ أَنْ يُمَرَّضَ فِي بَيْتِي، فَأَذِنَّ لَهُ، فَخَرَجَ وَهْوَ بَيْنَ الرَّجُلَيْنِ تحط رِجْلاَهُ فِي الأَرْضِ، بَيْنَ عَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ، وَبَيْنَ رَجُلٍ آخَرَ.","قال عبيد الله: فأخبرت عبد الله بالذي قالت عائشة، فقال لي عبدالله بن عباس: هل تدري من الرجل الآخر الذي لم تسم عائشة؟ قال: قلت: لا، قال ابن عباس: هو علي."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4442) من طريق عُقيل-، ومسلم في الصلاة (91:418) من طريق معمر– كلاهما عن الزهري، قال: أخبرني عبيدالله بن عبدالله بن عتبة بن مسعود، عن عائشة، فذكرته والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب استئذان الرجل نساءه أن يمرض عند إحداهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4442) and Muslim (418:91). The wording is from al-Bukhari.","chapter_en":"A Man Seeking His Wives’ Permission to Be Nursed During Illness in the House of One of Them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":36,"content":{"translation":{"en":["ʿA’ishah said: When the Messenger of Allah ﷺ became seriously ill and his pain intensified, he sought permission from his wives to be nursed in my house, and they gave him permission. So he went out between two men, his feet dragging on the ground, between al-ʿAbbas ibn ʿAbd al-Muttalib and another man. ʿUbaydullah said: I informed ʿAbdullah of what ʿA’ishah had said, and ʿAbdullah ibn ʿAbbas said to me: Do you know who the other man was whom ʿA’ishah did not name? I said: No. Ibn ʿAbbas said: It was ʿAli."]},"buhuth":{"en":["And in Muslim she said: “The Messenger of Allah ﷺ first became ill in the house of Maymunah, then he sought permission from his wives to be nursed in my house.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4442,"lafz":true},{"key":"muslim","label":"مسلم","number":418,"n":938},{"key":"muslim","label":"مسلم في الصلاه","number":91}],"full":1,"dr":1},{"num":6413,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَسْأَلُ فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ أَيْنَ أَنَا غَدًا أَيْنَ أَنَا غَدًا. يُرِيدُ يَوْمَ عَائِشَةَ، فَأَذِنَ لَهُ أَزْوَاجُهُ يَكُونُ حَيْثُ شَاءَ، فَكَانَ فِي بَيْتِ عَائِشَةَ حَتَّى مَاتَ عِنْدَهَا.","قالت عائشة: فمات في اليوم الذي كان يدور عليّ فيه في بيتي، فقبضه الله وإن رأسه بين نحري وسحري، وخالط ريقه ريقي."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5217) عن إسماعيل، قال حدثني سليمان بن بلال، قال هشام بن عروة: أخبرني أبي عن عائشة، فذكرته. ورواه مسلم في فضائل الصحابة (2443) من وجه آخر عن هشام بإسناده نحوه.","grade":"متفق عليه","chapter_ar":"باب استئذان الرجل نساءه أن يمرض عند إحداهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5217) and Muslim (2443).","chapter_en":"A Man Seeking His Wives’ Permission to Be Nursed During Illness in the House of One of Them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":36,"content":{"translation":{"en":["ʿA’ishah, the wife of the Prophet ﷺ, said: During the illness in which he died, the Messenger of Allah ﷺ would ask: “Where will I be tomorrow? Where will I be tomorrow?” wanting the day of ʿA’ishah. So his wives gave him permission to stay wherever he wished, and he remained in the house of ʿA’ishah until he died there. She said: He died on the day that was mine, in my house. Allah took his soul while his head was between my chest and my throat, and his saliva mixed with mine."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5217,"lafz":true},{"key":"muslim","label":"مسلم","number":2443}],"full":1},{"num":6414,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ مِنَ السُّنَّةِ إِذَا تَزَوَّجَ الرَّجُلُ الْبِكْرَ عَلَى الثَّيِّبِ أَقَامَ عِنْدَهَا سَبْعًا وَقَسَمَ، وَإِذَا تَزَوَّجَ الثَّيِّبَ عَلَى الْبِكْرِ أَقَامَ عِنْدَهَا ثَلاَثًا ثُمَّ قَسَمَ. قَالَ أَبُو قِلاَبَةَ وَلَوْ شِئْتُ لَقُلْتُ إِنَّ أَنَسًا رَفَعَهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5214) ومسلم في الرضاع (45:1416) كلاهما من طريق سفيان، حدثنا أيوب، وخالد الحذاء، عن أبي قلابة، عن أنس، فذكره،","grade":"متفق عليه","chapter_ar":"باب إقامة الزوج سبعًا عند البكر على الثيب، وثلاثًا عند الثيب على البكر، ثم بدء القسم","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5214) and Muslim (1461:45). The wording is from al-Bukhari.","chapter_en":"The Husband Staying Seven Days with a Virgin over a Previously Married Wife, and Three Days with a Previously Married Wife over a Virgin, Then Beginning the Regular Division","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":37,"content":{"translation":{"en":["Anas said: It is from the Sunnah that when a man marries a virgin while already married to a previously married woman, he stays with her for seven days and then begins division. And if he marries a previously married woman while already married to a virgin, he stays with her for three days and then begins division. Abu Qilabah said: If I wished, I could say that Anas attributed it to the Prophet ﷺ."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5214,"lafz":true},{"key":"muslim","label":"مسلم","number":1461},{"key":"muslim","label":"مسلم في الرضاع","number":45}],"full":1,"dr":1},{"num":6415,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ لِلثَّيِّبِ ثَلاَثًا وَلِلْبِكْرِ سَبْعًا."],"takhrij":"صحيح: رواه ابن ماجة (1916) والدارمي (2255) كلاهما من حديث محمد بن إسحاق، عن أيوب، عن أبي قلابة، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب إقامة الزوج سبعًا عند البكر على الثيب، وثلاثًا عند الثيب على البكر، ثم بدء القسم","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (1916), al-Darimi (2255), and Ibn Hibban in his Sahih (4208).","chapter_en":"The Husband Staying Seven Days with a Virgin over a Previously Married Wife, and Three Days with a Previously Married Wife over a Virgin, Then Beginning the Regular Division","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":37,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ said: “The previously married woman has three days, and the virgin has seven.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":1916,"lafz":true},{"key":"darimi","label":"الدارمي","number":2255,"n":2334},{"key":"ibnhibban","label":"ابن حبان في صحيحه","number":4208,"n":1551}],"full":1,"dr":1},{"num":6416,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ لَمَّا أَخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَفِيَّةَ أَقَامَ عِنْدَهَا ثَلاَثًا."],"takhrij":"صحيح: رواه أبو داود (2123) عن وهب بن بقية وعثمان بن أبي شيبة، عن هُشيم، عن حميد، عن أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب إقامة الزوج سبعًا عند البكر على الثيب، وثلاثًا عند الثيب على البكر، ثم بدء القسم","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2123).","chapter_en":"The Husband Staying Seven Days with a Virgin over a Previously Married Wife, and Three Days with a Previously Married Wife over a Virgin, Then Beginning the Regular Division","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":37,"content":{"translation":{"en":["Anas ibn Malik said: When the Messenger of Allah ﷺ took Safiyyah, he stayed with her for three days."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2123,"lafz":true}],"full":1,"dr":1},{"num":6417,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الْمَلِكِ، بْنِ أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ عَنْ أَبِيهِ، عَنْ أُمِّ سَلَمَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا تَزَوَّجَ أُمَّ سَلَمَةَ أَقَامَ عِنْدَهَا ثَلاَثًا وَقَالَ إِنَّهُ لَيْسَ بِكِ عَلَى أَهْلِكِ هَوَانٌ إِنْ شِئْتِ سَبَّعْتُ لَكِ وَإِنْ سَبَّعْتُ لَكِ سَبَّعْتُ لِنِسَائِي."],"takhrij":"صحيح: رواه مسلم في الرضاع (41:1460) من طريق يحي بن سعيد (هو القطان) عن سفيان ( هو الثوري)، عن محمد بن أبي بكر، عن عبد الملك بن أبي بكر بن عبد الرحمن بن الحارث بن هشام، عن أبيه، عن أم سلمة.","grade":"صحيح","chapter_ar":"باب إقامة الزوج سبعًا عند البكر على الثيب، وثلاثًا عند الثيب على البكر، ثم بدء القسم","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1460:41).","chapter_en":"The Husband Staying Seven Days with a Virgin over a Previously Married Wife, and Three Days with a Previously Married Wife over a Virgin, Then Beginning the Regular Division","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":37,"content":{"translation":{"en":["ʿAbd al-Malik ibn Abi Bakr ibn ʿAbd al-Rahman ibn al-Harith ibn Hisham narrated from his father, from Umm Salamah, that when the Messenger of Allah ﷺ married Umm Salamah, he stayed with her for three days and said: “You are not held in low esteem by your husband. If you wish, I will stay seven days with you; but if I stay seven days with you, I will also stay seven days with my other wives.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1460,"lafz":true},{"key":"muslim","label":"مسلم في الرضاع","number":41}],"full":1,"dr":1},{"num":6418,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن زَمْعَةَ أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ وَذَكَرَ النَّاقَةَ وَالَّذِي عَقَرَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ {إِذِ انْبَعَثَ أَشْقَاهَا} انْبَعَثَ لَهَا رَجُلٌ عَزِيزٌ عَارِمٌ، مَنِيعٌ فِي رَهْطِهِ، مِثْلُ أَبِي زَمْعَةَ. وَذَكَرَ النِّسَاءَ فَقَالَ يَعْمِدُ أَحَدُكُمْ يَجْلِدُ امْرَأَتَهُ جَلْدَ الْعَبْدِ، فَلَعَلَّهُ يُضَاجِعُهَا مِنْ آخِرِ يَوْمِهِ. ثُمَّ وَعَظَهُمْ فِي ضَحِكِهِمْ مِنَ الضَّرْطَةِ وَقَالَ لِمَ يَضْحَكُ أَحَدُكُمْ مِمَّا يَفْعَلُ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4942) ومسلم في كتاب الجنة (2855) كلاهما من حديث هشام، عن أبيه، عن عبد الله بن زمعة فذكره. واللفظ للبخاري، وفي لفظ مسلم: إلام يجلد أحدكم امرأته؟ وفي رواية: جلد الأمة.","grade":"متفق عليه","chapter_ar":"باب النهي عن ضرب النساء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4942) and Muslim (2855). The wording is from al-Bukhari.","chapter_en":"The Prohibition of Striking Women","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":38,"content":{"translation":{"en":["ʿAbdullah ibn Zamʿah said that he heard the Prophet ﷺ delivering a sermon and he mentioned the she-camel and the one who hamstrung it. The Messenger of Allah ﷺ said concerning the verse, “When the most wretched of them rose up” [al-Shams: 12]: A powerful, fierce man arose against it, strong among his people, like Abu Zamʿah. Then he mentioned women and said: “One of you beats his wife like a slave, then perhaps he will sleep with her at the end of the same day.” Then he admonished them about laughing at flatulence and said: “Why does one of you laugh at what he himself does?”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4942,"lafz":true},{"key":"muslim","label":"مسلم","number":2855}],"full":1,"dr":1},{"num":6419,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ مَا ضَرَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَيْئًا قَطُّ بِيَدِهِ وَلاَ امْرَأَةً وَلاَ خَادِمًا إِلاَّ أَنْ يُجَاهِدَ فِي سَبِيلِ اللَّهِ وَمَا نِيلَ مِنْهُ شَىْءٌ قَطُّ فَيَنْتَقِمَ مِنْ صَاحِبِهِ إِلاَّ أَنْ يُنْتَهَكَ شَىْءٌ مِنْ مَحَارِمِ اللَّهِ فَيَنْتَقِمَ لِلَّهِ عَزَّ وَجَلَّ."],"takhrij":"صحيح: رواه مسلم في كتاب الرؤيا (2328) عن أبي كريب، حدثنا أبو أسامة، عن هشام، عن أبيه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب النهي عن ضرب النساء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2328).","chapter_en":"The Prohibition of Striking Women","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":38,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ never struck anything with his hand at all — neither a woman nor a servant — except while striving in the path of Allah. And nothing was ever done against him personally such that he took revenge on the one who did it, unless one of the sacred limits of Allah was violated, in which case he would take revenge for the sake of Allah, Mighty and Majestic."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2328,"lafz":true}],"full":1,"rep":[9512,14017]},{"num":6420,"demo":false,"sanad":"","matn":["عَنْ إِيَاسِ بْنِ أَبِي ذُبَابٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تَضْرِبُوا إِمَاءَ اللَّهِ، قَالَ: فَذَئِرَ النِّسَاءُ وَسَاءَتْ أَخْلَاقُهُنَّ عَلَى أَزْوَاجِهِنَّ، فَقَالَ عُمَرُ بْنُ الْخَطَّابِ: قَدْ ذَئِرَ النِّسَاءُ وَسَاءَتْ أَخْلَاقُهُنَّ عَلَى أَزْوَاجِهِنَّ مُنْذُ نَهَيْتَ عَنْ ضَرْبِهِنَّ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَاضْرِبُوا، قَالَ: فَضَرَبَ النَّاسُ نِسَاءَهُمْ تِلْكَ اللَّيْلَةَ، فَأَتَى نِسَاءٌ كَثِيرٌ يَشْتَكِينَ الضَّرْبَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ أَصْبَحَ: لَقَدْ طَافَ بِآلِ مُحَمَّدٍ اللَّيْلَةَ سَبْعُونَ امْرَأَةً كُلُّهُنَّ يَشْتَكِينَ الضَّرْبَ، وَايْمُ اللَّهِ لَا تَجِدُونَ أُولَئِكَ خِيَارَكُمْ."],"takhrij":"صحيح: رواه ابو داود (2145) وابن ماجه (1985) وصحّحه ابن حبان (4189) والحاكم (2/191،188) والبيهقي (7/304) كلهم من حديث سفيان بن عيينة، عن الزهري، عن عبد الله بن عبد الله بن عمر بن الخطاب، عن إياس بن أبي ذباب فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن ضرب النساء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (2146) and Ibn Mājah (1985), and authenticated by Ibn Ḥibbān (4189) and al-Ḥākim (2/188–191).","chapter_en":"The Prohibition of Striking Women","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":38,"content":{"translation":{"en":["Iyās ibn Abī Dhubāb reported that the Messenger of Allah ﷺ said: “Do not strike the female servants of Allah.” He said: The women then became emboldened, and their conduct toward their husbands worsened. ʿUmar ibn al-Khaṭṭāb said: “The women have become emboldened, and their conduct toward their husbands has worsened since you prohibited striking them.” The Prophet ﷺ then said: “Then strike them.” So some men struck their wives that night, and many women came complaining about being struck. The following morning, the Prophet ﷺ said: “Seventy women have gone around the household of Muhammad tonight, all of them complaining about being struck. By Allah, you will not find those men to be the best among you.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2146},{"key":"ibnmajah","label":"ابن ماجه","number":1985},{"key":"ibnhibban","label":"صححه ابن حبان","number":4189,"lafz":true},{"key":"hakim","label":"الحاكم","number":2},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2060,"n":2057},{"key":"abudawud","label":"ابو داود","number":2145}],"full":1,"dr":1},{"num":6421,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ أَنَّ امْرَأَةَ الْوَلِيدِ بْنِ عُقْبَةَ أَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ إِنَّ الْوَلِيدَ يَضْرِبُهَا فَقَالَ لَهَا: قُولِي لَهُ – قَدْ أَجَارَنِي قَالَ عَلِيٌّ: فَلَمْ تَلْبَثْ إِلا يَسِيرًا حَتَّى رَجَعَتْ فَقَالَتْ: مَا زَادَنِي إِلا ضَرْبًا، فَأَخَذَ هُدْبَةً مِنْ ثَوْبِهِ، فَدَفَعَهَا إِلَيْهَا وَقَالَ: قُولِي لَهُ – إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ أَجَارَنِي فَلَمْ تَلْبَثْ إِلا يَسِيرًا حَتَّى رَجَعَتْ فَقَالَتْ: مَا زَادَنِي إِلا ضَرْبًا. فَرَفَعَ يَدَيْهِ وَقَالَ: اللهُمَّ عَلَيْكَ الْوَلِيدَ، أثِمَ بِي مَرَّتَيْنِ."],"takhrij":"حسن: رواه الإمام أحمد (1304) وأبو يعلى (351) والبزار -كشف الأستار (767) كلهم من حديث عبد الله بن داود، عن نعيم بن حكيم، عن أبي مريم، عن علي فذكره.","grade":"حسن","chapter_ar":"باب النهي عن ضرب النساء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Imām Aḥmad (1304), Abū Yaʿlā (351), and al-Bazzār in Kashf al-Astār (767).","chapter_en":"The Prohibition of Striking Women","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":38,"content":{"translation":{"en":["ʿAlī said: The wife of al-Walīd ibn ʿUqbah came to the Prophet ﷺ and said: O Messenger of Allah, al-Walīd beats me. So he said to her, “Say to him: The Messenger of Allah has granted me protection.” ʿAlī said: She stayed away only a little while, then returned and said: He only beat me more. So the Prophet took a fringe from his garment and gave it to her and said, “Say to him: The Messenger of Allah ﷺ has granted me protection.” She stayed away only a little while, then returned and said: He only beat me more. So he raised his hands and said, “O Allah, deal with al-Walīd. He has sinned against me twice.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":1304,"lafz":true},{"key":"sh12520","label":"أبو يعلى","number":351},{"key":"sh12862","label":"البزار -كشف الأستار","number":767}],"full":1,"dr":1},{"num":6422,"demo":false,"sanad":"","matn":["عَنْ جابر، عن النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ فِي خطبة حَجَّةِ الْوَدَاعِ: اتقوا اللَّهَ فِي النِّسَاءِ، فَإِنَّكُمْ أَخَذْتُمُوهُنَّ بِأَمَانِ اللَّهِ، وَاسْتَحْلَلْتُمْ فُرُوجَهُنَّ بِكَلِمَةِ اللَّهِ، وَلَكُمْ عَلَيْهِنَّ أَنْ لاَ يُوطِئْنَ فُرُشَكُمْ أَحَدًا تَكْرَهُونَهُ، فَإِنْ فَعَلْنَ ذَلِكَ فَاضْرِبُوهُنَّ ضَرْبًا غَيْرَ مُبَرِّحٍ."],"takhrij":"صحيح: رواه مسلم في الحج (1218) من طرق عن حاتم بن إسماعيل المدني، عن جعفر بن محمد، عن أبيه، عن جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في النشوز","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"What Has Been Related Regarding Marital Rebellion","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":39,"content":{"translation":{"en":["Jābir reported that the Prophet ﷺ said during the sermon of the Farewell Pilgrimage: “Fear Allah regarding women, for you have taken them under the trust of Allah and have made marital relations with them lawful by the word of Allah. Your right over them is that they do not allow anyone whom you dislike onto your bedding. If they do that, then strike them in a manner that is not severe.”"]},"intro":{"ar":["قال الله تعالى: ( الرِّجَالُ قَوَّامُونَ عَلَى النِّسَاءِ بِمَا فَضَّلَ اللَّهُ بَعْضَهُمْ عَلَى بَعْضٍ وَبِمَا أَنْفَقُوا مِنْ أَمْوَالِهِمْ ۚ فَالصَّالِحَاتُ قَانِتَاتٌ حَافِظَاتٌ لِّلْغَيْبِ بِمَا حَفِظَ اللَّهُ ۚ وَاللَّاتِي تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَاهْجُرُوهُنَّ فِي الْمَضَاجِعِ وَاضْرِبُوهُنَّ ۖ فَإِنْ أَطَعْنَكُمْ فَلَا تَبْغُوا عَلَيْهِنَّ سَبِيلًا ۗ إِنَّ اللَّهَ كَانَ عَلِيًّا كَبِيرًا ۝ وَإِنْ خِفْتُمْ شِقَاقَ بَيْنِهِمَا فَابْعَثُوا حَكَمًا مِنْ أَهْلِهِ وَحَكَمًا مِنْ أَهْلِهَا إِنْ يُرِيدَا إِصْلَاحًا ) [النساء: ٣٤-٣٥]"],"en":["Allah the Exalted said: “Men are caretakers of women because Allah has given one more than the other and because they spend from their wealth. So righteous women are devoutly obedient, guarding in the husband’s absence what Allah would have them guard. As for those from whom you fear rebellion, admonish them, leave them in the beds, and strike them. But if they obey you, then do not seek a way against them. Indeed, Allah is Most High, Most Great. And if you fear a breach between them, appoint an arbiter from his family and an arbiter from her family, if they both desire reconciliation…” [Surat al-Nisā’, 34–35]"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218,"lafz":true,"n":2951}],"full":1,"dr":1},{"num":6423,"demo":false,"sanad":"","matn":["عَنْ علي قَالَ: لَمَّا تَزَوَّجْتُ فَاطِمَةَ فَقُلْتُ يَا رَسُولَ اللَّهِ ابْنِ لِي، قَالَ: أَعْطِهَا شَيْئًا قُلْتُ: مَا عِنْدِي مِنْ شيء. قَالَ: فَأَيْنَ دِرْعُكَ الْحُطَمِيَّةُ قُلْتُ: هِيَ عِنْدِي. قَالَ: فَأَعْطِهَا إِيَّاهُ."],"takhrij":"صحيح: رواه النسائي (3375) البيهقي (7/252) كلاهما من حديث هشام بن عبد الملك، قال: حدثنا حماد، عن أيوب، عن عكرمة، عن ابن عباس، أن عليًّا قال: فذكره. وإسناده صحيح. وحماد هو ابن سلمة.","grade":"صحيح","chapter_ar":"باب ما جاء في النشوز","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (3375) and al-Bayhaqī (7/252).","chapter_en":"What Has Been Related Regarding Marital Rebellion","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":39,"content":{"translation":{"en":["ʿAlī said: When I married Fāṭimah, I said: O Messenger of Allah, permit me to consummate the marriage. He said, “Give her something.” I said: I do not have anything. He said, “Where is your Ḥuṭamiyyah armor?” I said: I have it. He said, “Then give it to her.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3375,"lafz":true,"n":3375},{"key":"kubrabayhaqi","label":"البيهقي","number":252}],"full":1},{"num":6424,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عَبَّاسٍ قَالَ: لَمَّا تَزَوَّجَ عَلِيٌّ فَاطِمَةَ قَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَعْطِهَا شَيْئًا. قَالَ: ماعندي شيء. قَالَ: أَيْنَ دِرْعُكَ الْحُطَمِيَّةُ؟"],"takhrij":"صحيح: رواه أبو داوود (2125) والنسائي (3376) كلاهما من حديث عبدة ، عن سعيد ، عن أيوب ، عن عكرمة ، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب لا يدخل بأهله قبل أن يُعطيها شيئا","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (2125) and al-Nasā’ī (3376).","chapter_en":"A man should not enter upon his wife before giving her something","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":40,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās said: When ʿAlī married Fāṭimah, the Messenger of Allah ﷺ said to him, “Give her something.” He said: I do not have anything. He said, “Where is your Ḥuṭamiyyah armor?”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2125,"lafz":true},{"key":"nasai","label":"النسائي","number":3376}],"full":1,"dr":1},{"num":6425,"demo":false,"sanad":"","matn":["عَنْ الْمِسْوَرِ بن مَخْرَمَةَ أن عَلِيَّ بْنَ أَبِي طَالِبٍ خَطَبَ بِنْتَ أَبِي جَهْلٍ عَلَى فَاطِمَةَ. فَسَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَخْطُبُ النَّاسَ فِي ذَلِكَ، عَلَى مِنْبَرِهِ هَذَا، وَأَنَا يَوْمَئِذٍ مُحْتَلِمٌ، فَقَالَ: إِنَّ فَاطِمَةَ مِنِّي، وَإِنِّي أَتَخَوَّفُ أَنْ تُفْتَنَ فِي دِينِهَا.","قال: ثم ذكر صهراً له من بني عبد شمس، فأثنى عليه في مُصاهرته إياه فأحسن. قال: حدثني فصدقَني ووعدَني فأوفى لي. وإني لست أحرم حلالاً ولا أحل حراما. ولكن والله لا تجتمع بنت رسول الله صلى الله عليه وسلم وبنت عدو الله مكانا واحدا أبدا."],"takhrij":"متفق عليه: رواه البخاري في فرض الخمس (3110) ومسلم في فضائل الصحابة (2449-95) كلاهما من طريق يعقوب بن إبراهيم ثنا أبي عن الوليد بن كثير ثني محمد بن عمرو بن حلحلة الدُّؤلي، أن ابن شهاب حدثه أن علي بن الحسين حدثه عن المسور بن مخرمة. فذكره وفيه قصة. وهذا لفظ مسلم، ولفظ البخاري نحوه.","grade":"متفق عليه","chapter_ar":"باب ذبّ الرجل عن ابنته في الغيرة وطلب الإنصاف لها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3110) and Muslim (2449:95).","chapter_en":"A Man Defending His Daughter Out of Protective Jealousy and Seeking Fairness for Her","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":41,"content":{"translation":{"en":["Al-Miswar ibn Makhramah said: ʿAlī ibn Abī Ṭālib proposed to the daughter of Abū Jahl while married to Fāṭimah. I heard the Messenger of Allah ﷺ addressing the people about that from this pulpit of his, and at that time I had reached puberty. He said: “Fāṭimah is a part of me, and I fear that she may be tested in her religion.” Then he mentioned a son-in-law of his from Banū ʿAbd Shams and praised him highly regarding his marriage tie with him. He said: “He spoke to me and told me the truth, and he promised me and fulfilled his promise. I do not forbid what is lawful, nor do I make lawful what is forbidden. But by Allah, the daughter of the Messenger of Allah ﷺ and the daughter of the enemy of Allah will never be joined together in one place.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3110,"lafz":true},{"key":"muslim","label":"مسلم","number":2449,"n":6309}],"full":1,"rep":[10429]},{"num":6426,"demo":false,"sanad":"","matn":["عَنِ الْمِسْوَرِ بْنِ مَخْرَمَةَ، قَالَ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ وَهْوَ عَلَى الْمِنْبَرِ إِنَّ بَنِي هِشَامِ بْنِ الْمُغِيرَةِ اسْتَأْذَنُوا فِي أَنْ يُنْكِحُوا ابْنَتَهُمْ عَلِيَّ بْنَ أَبِي طَالِبٍ فَلاَ آذَنُ، ثُمَّ لاَ آذَنُ، ثُمَّ لاَ آذَنُ، إِلاَّ أَنْ يُرِيدَ ابْنُ أَبِي طَالِبٍ أَنْ يُطَلِّقَ ابْنَتِي وَيَنْكِحَ ابْنَتَهُمْ، فَإِنَّمَا هِيَ بَضْعَةٌ مِنِّي، يُرِيبُنِي مَا أَرَابَهَا وَيُؤْذِينِي مَا آذَاهَا."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5230)، ومسلم في الفضائل (2249: 93) كلاهما من حديث الليث بن سعد، عن ابن أبي مليكة، عن المسور بن مخرمة فذكره.","grade":"متفق عليه","chapter_ar":"باب ذبّ الرجل عن ابنته في الغيرة وطلب الإنصاف لها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5230) and Muslim (2449/93).","chapter_en":"A Man Defending His Daughter Out of Protective Jealousy and Seeking Fairness for Her","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":41,"content":{"translation":{"en":["Al-Miswar ibn Makhramah reported: I heard the Messenger of Allah ﷺ say while standing on the pulpit: “The family of Hishām ibn al-Mughīrah have sought permission to marry their daughter to ʿAlī ibn Abī Ṭālib. I do not give permission, then I do not give permission, then I do not give permission—unless Ibn Abī Ṭālib wishes to divorce my daughter and marry their daughter. She is a part of me. Whatever troubles her troubles me, and whatever harms her harms me.”"]},"buhuth":{"en":["The words “their daughter” refer to the daughter of Abū Jahl, whose name was ʿAmr ibn Hishām ibn al-Mughīrah, the enemy of Allah and His Messenger. His two brothers, al-Ḥārith ibn Hishām and Salamah ibn Hishām, accepted Islam in the year of the Conquest, and their Islam was good."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5230,"lafz":true},{"key":"muslim","label":"مسلم","number":2449},{"key":"muslim","label":"مسلم في الفضائل","number":2249}],"full":1,"dr":1,"rep":[10427]},{"num":6427,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى امْرَأَةً فَأَتَى امْرَأَتَهُ زَيْنَبَ وَهْىَ تَمْعَسُ مَنِيئَةً لَهَا فَقَضَى حَاجَتَهُ ثُمَّ خَرَجَ إِلَى أَصْحَابِهِ فَقَالَ إِنَّ الْمَرْأَةَ تُقْبِلُ فِي صُورَةِ شَيْطَانٍ وَتُدْبِرُ فِي صُورَةِ شَيْطَانٍ فَإِذَا أَبْصَرَ أَحَدُكُمُ امْرَأَةً فَلْيَأْتِ أَهْلَهُ فَإِنَّ ذَلِكَ يَرُدُّ مَا فِي نَفْسِهِ."],"takhrij":"صحيح: رواه مسلم في النكاح (1403) عن عمرو بن علي، حدثنا عبد الأعلى، حدثنا هشام بن أبي عبد الله، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ندب من رأى امرأة، فوقعت في نفسه أن يأتي امرأته أو جاريته فيقضي حاجته","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1403). In another wording: “Then let him go intentionally to his wife and have intercourse with her, for that will repel what is in his heart.”","chapter_en":"Recommendation for one who sees a woman and feels desire to go to his wife or slave woman and fulfill his need","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":42,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: The Prophet ﷺ saw a woman, so he went to his wife Zaynab while she was tanning a hide for her, and he fulfilled his need. Then he came out to his companions and said: “A woman comes in the form of a devil and goes away in the form of a devil. So if one of you sees a woman, let him go to his wife, for that will repel what is in his heart.”"]},"buhuth":{"en":["His words “she was tamʿasu manī’atan lahā” mean: al-maʿs is rubbing, and al-manī’ah is the first stage of tanning the hide."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1403,"lafz":true}],"full":1,"dr":1},{"num":6428,"demo":false,"sanad":"","matn":["عن أَبِي كَبْشَةَ الأنصاري قَالَ: قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسًا فِي أَصْحَابِهِ فَدَخَلَ، ثُمَّ خَرَجَ وَقَدِ اغْتَسَلَ، فَقُلْنَا: يَا رَسُولَ اللَّهِ قَدْ كَانَ شَيْءٌ قَالَ: أَجَلْ، مَرَّتْ بِي فُلَانَةُ، فَوَقَعَ فِي قَلْبِي شَهْوَةُ النِّسَاءِ، فَأَتَيْتُ بَعْضَ أَزْوَاجِي فَأَصَبْتُهَا، فَكَذَلِكَ فَافْعَلُوا، فَإِنَّهُ مِنْ أَمَاثِلِ أَعْمَالِكُمْ إِتْيَانُ الْحَلَالِ."],"takhrij":"حسن: رواه الإمام أحمد (18028) والطبراني في الكبير (22/338-339) وفي الأوسط (3275) كلهم من طريق معاوية بن صالح، عن أزهر بن سعيد الحرازي، قال: سمعت أبا كبشة فذكره.","grade":"حسن","chapter_ar":"باب ندب من رأى امرأة، فوقعت في نفسه أن يأتي امرأته أو جاريته فيقضي حاجته","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Imām Aḥmad (18028), al-Ṭabarānī in al-Kabīr (22/338–339), and in al-Awsaṭ (3275).","chapter_en":"Recommendation for one who sees a woman and feels desire to go to his wife or slave woman and fulfill his need","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":42,"content":{"translation":{"en":["Abū Kabshah al-Anṣārī said: The Messenger of Allah ﷺ was sitting among his companions. Then he went in, and later came out having bathed. So we said: O Messenger of Allah, did something happen? He said: “Yes. A certain woman passed by me, and desire for women came into my heart. So I went to one of my wives and had relations with her. So do likewise, for among your best deeds is coming to the lawful.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":18028,"lafz":true,"n":18027},{"key":"mujamkabir","label":"الطبراني في الكبير","number":22},{"key":"sh28171","label":"وفي الأوسط","number":3275},{"key":"ahmad","label":"مسند الإمام أحمد","number":18027,"n":18027}],"full":1,"dr":1},{"num":6429,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ يَقُولُ سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ يَقُولُ لاَ يَخْلُوَنَّ رَجُلٌ بِامْرَأَةٍ إِلاَّ وَمَعَهَا ذُو مَحْرَمٍ وَلاَ تُسَافِرِ الْمَرْأَةُ إِلاَّ مَعَ ذِي مَحْرَمٍ. فَقَامَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ امْرَأَتِي خَرَجَتْ حَاجَّةً وَإِنِّي اكْتُتِبْتُ فِي غَزْوَةِ كَذَا وَكَذَا. قَالَ انْطَلِقْ فَحُجَّ مَعَ امْرَأَتِكَ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5233)، ومسلم في الحج (1314) كلاهما من طريق سفيان بن عيينة، حدثنا عمرو بن دينار، عن أبي معبد، قال سمعت ابن عباس يقول:فذكره. والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"باب تحريم الخلوة بالأجنبية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5233) and Muslim (1341). The wording is from Muslim.","chapter_en":"The Prohibition of Seclusion with a Non-Mahram Woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":43,"content":{"translation":{"en":["Ibn ʿAbbās said: I heard the Prophet ﷺ giving a sermon saying: “No man should be alone with a woman unless she has a mahram with her, and no woman should travel except with a mahram.” Then a man stood and said: O Messenger of Allah, my wife has gone out for Hajj, and I have enlisted in such-and-such expedition. He said: “Go and perform Hajj with your wife.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5233,"lafz":true},{"key":"muslim","label":"مسلم","number":1341},{"key":"muslim","label":"مسلم في الحج","number":1314,"n":3272}],"full":1},{"num":6430,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِيَّاكُمْ وَالدُّخُولَ عَلَى النِّسَاءِ. فَقَالَ رَجُلٌ مِنَ الأَنْصَارِ يَا رَسُولَ اللَّهِ أَفَرَأَيْتَ الْحَمْوَ. قَالَ الْحَمْوُ الْمَوْتُ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5232)، ومسلم في السلام (2172) كلاهما عن قتيبة بن سعد، حدثنا ليث، عن يزيد بن أبي حبيب، عن أبي الخير، عن عقبة بن عامر، قال:فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم الخلوة بالأجنبية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5232) and Muslim (2172).","chapter_en":"The Prohibition of Seclusion with a Non-Mahram Woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":43,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir said that the Messenger of Allah ﷺ said: “Beware of entering upon women.” A man from the Anṣār said: O Messenger of Allah, what about the in-law? He said: “The in-law is death.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5232,"lafz":true},{"key":"muslim","label":"مسلم","number":2172}],"full":1,"rep":[6543]},{"num":6431,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن عمرو بْنِ الْعَاصِ حَدَّثَهُ أَنَّ نَفَرًا مِنْ بَنِي هَاشِمٍ دَخَلُوا عَلَى أَسْمَاءَ بِنْتِ عُمَيْسٍ فَدَخَلَ أَبُو بَكْرٍ الصِّدِّيقُ وَهِيَ تَحْتَهُ يَوْمَئِذٍ فَرَآهُمْ فَكَرِهَ ذَلِكَ فَذَكَرَ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَالَ لَمْ أَرَ إِلاَّ خَيْرًا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ اللَّهَ قَدْ بَرَّأَهَا مِنْ ذَلِكَ. ثُمَّ قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْمِنْبَرِ فَقَالَ لاَ يَدْخُلَنَّ رَجُلٌ بَعْدَ يَوْمِي هَذَا عَلَى مُغِيبَةٍ إِلاَّ وَمَعَهُ رَجُلٌ أَوِ اثْنَانِ."],"takhrij":"صحيح: رواه مسلم في السلام (2173) من طريق عبد الله بن وهب، عن عمرو بن الحارث، أن بكر بن سوادة حدثه، أن عبد الرحمن بن جُبير حدثه، أن عبد الله بن عمرو بن العاص حدثه، فذكره.","grade":"صحيح","chapter_ar":"باب تحريم الخلوة بالأجنبية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2173).","chapter_en":"The Prohibition of Seclusion with a Non-Mahram Woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":43,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ said: A group from Banū Hāshim entered upon Asmā’ bint ʿUmays. Then Abū Bakr al-Ṣiddīq entered — and she was his wife — and he disliked that. So he mentioned it to the Messenger of Allah ﷺ and said: I saw nothing but good. Then the Messenger of Allah ﷺ said: “Allah has declared her innocent of that.” Then the Messenger of Allah ﷺ stood upon the pulpit and said: “After this day, no man should enter upon a woman whose husband is absent unless he is accompanied by one or two men.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2173,"lafz":true}],"full":1,"rep":[6547]},{"num":6432,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَلاَ لاَ يَبِيتَنَّ رَجُلٌ عِنْدَ امْرَأَةٍ ثَيِّبٍ إِلاَّ أَنْ يَكُونَ نَاكِحًا أَوْ ذَا مَحْرَمٍ."],"takhrij":"صحيح: رواه مسلم في السلام (2171) من طريق هشيم، أخبرنا أبو الزبير، عن جابر، قال:فذكره.","grade":"صحيح","chapter_ar":"باب تحريم الخلوة بالأجنبية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2171).","chapter_en":"The Prohibition of Seclusion with a Non-Mahram Woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":43,"content":{"translation":{"en":["Jābir said: The Messenger of Allah ﷺ said: “No man should spend the night with a previously married woman unless he is her husband or a mahram.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2171,"lafz":true}],"full":1,"rep":[6544]},{"num":6433,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عَبَّاسٍ أَنَّ رَجُلا قَدِمَ مِنْ سَفَرٍ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : نَزَلْتَ عَلَى فُلانَةٍ، وَأَغْلَقْتَ عَلَيْكَ بَابَهَا قَالَ: نَعَمْ، فَكَرِهَ ذَلِكَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه البزار – كشف الأستار (1488) عن محمد بن معمر، ثنا أبو عاصم، قال: ثنا محمد بن مسلم، عن عمرو بن دينار، عن عكرمة، عن عبد الله بن عباس فذكره.","grade":"صحيح","chapter_ar":"باب تحريم الخلوة بالأجنبية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bazzār in Kashf al-Astār (1488).","chapter_en":"The Prohibition of Seclusion with a Non-Mahram Woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":43,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās said that a man returned from a journey, and the Prophet ﷺ said to him: “You stayed with a certain woman and closed the door upon yourselves?” He said: Yes. So the Prophet ﷺ disliked that."]}},"tuhfa":{},"refs":[{"key":"sh12862","label":"البزار - كشف الأستار","number":1488,"lafz":true}],"full":1,"dr":1},{"num":6434,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ يَقُولُ جَاءَتِ امْرَأَةٌ مِنَ الأَنْصَارِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ - فَخَلاَ بِهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَالَ وَالَّذِي نَفْسِي بِيَدِهِ إِنَّكُمْ لأَحَبُّ النَّاسِ إِلَىَّ. ثَلاَثَ مَرَّاتٍ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5234) ومسلم في فضائل الصحابة (2509/175) كلاهما عن محمد بن بشار، حدثنا محمد بن جعفر غندر، حدثنا شعبة، عن هشام بن زيد، قال: سمعت أنس بن مالك، قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب جواز الخلوة بالمرأة عند الحاجة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5234) and Muslim (2509:175). His words “he was alone with her” mean: he moved away from the gathering of people.","chapter_en":"The Permissibility of Private Conversation with a Woman When There Is a Need","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":44,"content":{"translation":{"en":["Anas ibn Mālik said: A woman from the Anṣār came to the Messenger of Allah ﷺ. He said: Then the Messenger of Allah ﷺ spoke privately with her and said, “By the One in Whose hand is my soul, you are the most beloved people to me,” three times."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5234,"lafz":true},{"key":"muslim","label":"مسلم","number":2509}],"full":1,"dr":1},{"num":6435,"demo":false,"sanad":"","matn":["عن أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا دَخَلَ عَلَىَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعِنْدِي مُخَنَّثٌ فَسَمِعْتُهُ يَقُولُ لِعَبْدِ اللَّهِ بْنِ أَبِي أُمَيَّةَ يَا عَبْدَ اللَّهِ أَرَأَيْتَ إِنْ فَتَحَ اللَّهُ عَلَيْكُمُ الطَّائِفَ غَدًا فَعَلَيْكَ بِابْنَةِ غَيْلاَنَ، فَإِنَّهَا تُقْبِلُ بِأَرْبَعٍ وَتُدْبِرُ بِثَمَانٍ. وَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ يَدْخُلَنَّ هَؤُلاَءِ عَلَيْكُنَّ."],"takhrij":"متفق عليه: رواه البخاري (5887) ومسلم (2180)","grade":"متفق عليه","chapter_ar":"باب منع دخول المخنث على النساء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5887) and Muslim (2180).","chapter_en":"Preventing the Effeminate Man from Entering upon Women","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":45,"content":{"translation":{"en":["Umm Salamah said: The Messenger of Allah ﷺ entered upon me while an effeminate man was with me. I heard him saying to ʿAbdullāh ibn Abī Umayyah, the brother of Umm Salamah: O ʿAbdullāh, if Allah grants you victory over Ṭā’if tomorrow, then take the daughter of Ghaylān, for she comes with four and goes with eight. Then the Prophet ﷺ said: “These people must not enter upon you.”"]},"buhuth":{"en":["Abū ʿAbdullāh al-Bukhārī said: “His words ‘she comes with four’ mean the four folds of her belly, so she comes with them; and his words ‘she goes with eight’ mean the ends of those four folds, because they extend around both sides until they meet.” I say: ʿukan are the folds in the belly caused by fatness."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5887,"lafz":true},{"key":"muslim","label":"مسلم","number":2180}],"full":1,"dr":1},{"num":6436,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ كَانَ يَدْخُلُ عَلَى أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُخَنَّثٌ فَكَانُوا يَعُدُّونَهُ مِنْ غَيْرِ أُولِي الإِرْبَةِ - قَالَ - فَدَخَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا وَهُوَ عِنْدَ بَعْضِ نِسَائِهِ وَهُوَ يَنْعَتُ امْرَأَةً قَالَ إِذَا أَقْبَلَتْ أَقْبَلَتْ بِأَرْبَعٍ وَإِذَا أَدْبَرَتْ أَدْبَرَتْ بِثَمَانٍ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَلاَ أَرَى هَذَا يَعْرِفُ مَا هَا هُنَا لاَ يَدْخُلَنَّ عَلَيْكُنَّ. قَالَتْ فَحَجَبُوهُ."],"takhrij":"صحيح: رواه مسلم في السلام (2181) عن عبد الله بن حميد، أخبرنا عبد الرزاق، عن معمر، عن الزهري، عن عروة، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب منع دخول المخنث على النساء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2181).","chapter_en":"Preventing the Effeminate Man from Entering upon Women","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":45,"content":{"translation":{"en":["ʿA’ishah said: An effeminate man used to enter upon the wives of the Messenger of Allah ﷺ, and they used to count him among those who had no desire for women. One day the Prophet ﷺ entered while he was with one of his wives, and he was describing a woman, saying: When she comes forward, she comes with four, and when she turns away, she turns away with eight. So the Prophet ﷺ said: “Do I not see that this one knows what is here? He must not enter upon you.” She said: So they screened him off."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2181,"lafz":true}],"full":1,"dr":1,"rep":[12875]},{"num":6437,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ لَعَنَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمُخَنَّثِينَ مِنَ الرِّجَالِ، وَالْمُتَرَجِّلاَتِ مِنَ النِّسَاءِ وَقَالَ أَخْرِجُوهُمْ مِنْ بُيُوتِكُمْ. قَالَ فَأَخْرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فُلاَنًا، وَأَخْرَجَ عُمَرُ فُلاَنًا."],"takhrij":"صحيح: رواه البخاري في اللباس (5886) عن معاذ بن فضالة، حدثنا هشام، عن يحيى، عن عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن التشبه بالنساء والعكس","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5886). In another wording with him (5885): “the men who imitate women and the women who imitate men.”","chapter_en":"The Prohibition of Men Resembling Women and Women Resembling Men","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":46,"content":{"translation":{"en":["Ibn ʿAbbās said: The Prophet ﷺ cursed the effeminate men and the women who imitate men. And he said: “Expel them from your houses.” He said: So the Prophet ﷺ expelled a certain man, and ʿUmar expelled a certain man."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5886,"lafz":true},{"key":"bukhari","label":". وفي رواية عنده","number":5885,"n":5886}],"full":1,"dr":1,"rep":[15034]},{"num":6438,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ لَعَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الرَّجُلَ يَلْبَسُ لِبْسَةَ الْمَرْأَةِ وَالْمَرْأَةَ تَلْبَسُ لِبْسَةَ الرَّجُلِ."],"takhrij":"صحيح: رواه أبو داوود (4098) وابن ماجة (1903) وأحمد (8309) وصحّحه ابن حبان (5751) والحاكم (4/194) كلهم من طريق سهيل بن أبي صالح، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن التشبه بالنساء والعكس","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4098), Ibn Mājah (1903), and Aḥmad (8309), and authenticated by Ibn Ḥibbān (5751).","chapter_en":"The Prohibition of Men Resembling Women and Women Resembling Men","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":46,"content":{"translation":{"en":["Abū Hurairah said: The Messenger of Allah ﷺ cursed the man who wears women’s clothing and the woman who wears men’s clothing."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4098,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":1903},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":5751},{"key":"ahmad","label":"مسند الإمام أحمد","number":8309,"n":8309},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2888,"n":2885}],"full":1,"dr":1,"rep":[15527]},{"num":6439,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ثلاثة لَا يَدْخُلُونَ الْجَنَّةَ، وَلَا يَنْظُرُ اللَّهُ إِلَيْهِمْ يَوْمَ الْقِيَامَةِ: الْعَاقُّ بِوَالِدَيْهِ، وَالْمَرْأَةُ الْمُتَرَجِّلَةُ الْمُتَشَبِّهَةُ بِالرِّجَالِ، وَالدَّيُّوثُ. وَثَلَاثَةٌ لَا يَنْظُرُ اللَّهُ إِلَيْهِمْ يَوْمَ الْقِيَامَةِ: الْعَاقُّ بِوَالِدَيْهِ، وَالْمُدْمِنُ الْخَمْرَ، وَالْمَنَّانُ بِمَا أَعْطَى."],"takhrij":"حسن: رواه النسائي (2562)، وأحمد (6180) والبزار – كشف الأستار (1876) وأبو يعلى (5551) وصحّحه ابن حبان (7340) والحاكم (1/72) كلهم من حديث عبد الله بن يسار مولى ابن عمر، قال: أشهد لقد سمعت سالماً يقول: قال عبد الله: فذكره.","grade":"حسن","chapter_ar":"باب النهي عن التشبه بالنساء والعكس","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī (2562), Aḥmad (6180), al-Bazzār in Kashf al-Astār (1876), and Abū Yaʿlā (5551).","chapter_en":"The Prohibition of Men Resembling Women and Women Resembling Men","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":46,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ said: “Three will not enter Paradise, and Allah will not look at them on the Day of Resurrection: the one undutiful to his parents, the woman who imitates men, and the dayyūth. And three Allah will not look at on the Day of Resurrection: the one undutiful to his parents, the habitual drinker of alcohol, and the one who reminds others of what he has given them.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":2562,"lafz":true},{"key":"sh12862","label":"البزار - كشف الأستار","number":1876},{"key":"sh12520","label":"أبو يعلى","number":5551,"n":5561},{"key":"ahmad","label":"مسند الإمام أحمد","number":6180,"n":6180},{"key":"ibnhibban","label":"ابن حبان","number":7340}],"full":1,"dr":1},{"num":6440,"demo":false,"sanad":"","matn":["عن صَفِيَّةَ بنت حيي زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخْبَرَتْهُ أَنَّهَا جَاءَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَزُورُهُ وَهْوَ مُعْتَكِفٌ فِي الْمَسْجِدِ فِي الْعَشْرِ الْغَوَابِرِ مِنْ رَمَضَانَ، فَتَحَدَّثَتْ عِنْدَهُ سَاعَةً مِنَ الْعِشَاءِ ثُمَّ قَامَتْ تَنْقَلِبُ، فَقَامَ مَعَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْلِبُهَا حَتَّى إِذَا بَلَغَتْ باب الْمَسْجِدِ الَّذِي عِنْدَ مَسْكَنِ أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِهِمَا رَجُلاَنِ مِنَ الأَنْصَارِ فَسَلَّمَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ نَفَذَا، فَقَالَ لَهُمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى رِسْلِكُمَا، إِنَّمَا هِيَ صَفِيَّةُ بِنْتُ حُيَىٍّ. قَالاَ سُبْحَانَ اللَّهِ يَا رَسُولَ اللَّهِ. وَكَبُرَ عَلَيْهِمَا. قَالَ إِنَّ الشَّيْطَانَ يَجْرِي مِنِ ابْنِ آدَمَ مَبْلَغَ الدَّمِ، وَإِنِّي خَشِيتُ أَنْ يَقْذِفَ فِي قُلُوبِكُمَا."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6219) ومسلم في السلام (2175/25) كلاهما من طريق أبي اليمان، أخبرنا شعيب، عن الزهري، أخبرنا علي بن الحسين، أن صفية زوج النبي صلى الله عليه وسلم أخبرته، فذكرته.","grade":"متفق عليه","chapter_ar":"باب سمر النبي ﷺ بنسائه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6219) and Muslim (2175:25).","chapter_en":"The Prophet ﷺ Spending the Evening in Conversation with His Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":47,"content":{"translation":{"en":["Ṣafiyyah bint Ḥuyayy, the wife of the Prophet ﷺ, said that she came to the Messenger of Allah ﷺ to visit him while he was in iʿtikāf in the mosque during the last ten nights of Ramadan. She spoke with him for a while after ʿIshā’, then she stood to leave, and the Prophet ﷺ stood with her to escort her back. When she reached the door of the mosque near the dwelling of Umm Salamah, the wife of the Prophet ﷺ, two men from the Anṣār passed by her. They greeted the Messenger of Allah ﷺ and then continued on. The Messenger of Allah ﷺ said to them: “Slow down. This is only Ṣafiyyah bint Ḥuyayy.” They said: Glory be to Allah, O Messenger of Allah. What he said seemed very serious to them. He said: “Satan runs through the son of Adam as blood runs, and I feared that he might cast something into your hearts.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6219,"lafz":true},{"key":"muslim","label":"مسلم","number":2175}],"full":1,"dr":1,"rep":[14624]},{"num":6441,"demo":false,"sanad":"","matn":["عَنْ أُمِّ كُلْثُومٍ بنت عقبة أَنَّهَا سَمِعَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَيْسَ الْكَذَّابُ الَّذِي يُصْلِحُ بَيْنَ النَّاسِ، فَيَنْمِي خَيْرًا أَوْ يَقُولُ خَيْرًا."],"takhrij":"متفق عليه: رواه البخاري في الصلح (2692)، ومسلم في البر والصلة والآداب (2605) كلاهما من طريق صالح، عن ابن شهاب، أن حميد بن عبد الرحمن أخبره، أن أمّه أمّ كلثوم بنت عقبة أخبرته، فذكرته، والسياق للبخاري، ولم يسق مسلم متنه، وإنما أحال فيه على حديث يونس عن ابن شهاب وقال مثله.","grade":"متفق عليه","chapter_ar":"باب الترخيص في الكذب من أجل الإصلاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2692) and Muslim (2605). The wording is from al-Bukhārī.","chapter_en":"The Concession of Using Untrue Speech for the Sake of Reconciliation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":48,"content":{"translation":{"en":["Umm Kulthūm bint ʿUqbah said that she heard the Messenger of Allah ﷺ say: “The one who reconciles between people and conveys good or says good is not a liar.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2692,"lafz":true},{"key":"muslim","label":"مسلم","number":2605}],"full":1,"dr":1},{"num":6442,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر أن رسول الله صلى الله عليه وسلم قال: كلكم راع، وكلكم مسئول عن رعيته، والمرأة راعية في بيت زوجها، ومسؤولة عن رعيتها."],"takhrij":"متفق عليه: رواه البخاري في الجمعة (893) ومسلم في الإمارة (1829) كلاهما من حديث عبد الله بن وهب، عن يونس، عن ابن شهاب، عن سالم، عن عبد الله بن عمر فذكره في حديث طويل وهو مذكور في موضعه.","grade":"متفق عليه","chapter_ar":"باب إن المرأة راعية البيت","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (893) and Muslim (1829).","chapter_en":"The Woman Is a Shepherd Over the Home","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":49,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar said that the Messenger of Allah ﷺ said: “Each of you is a shepherd, and each of you will be questioned about his flock. And the woman is a shepherd in her husband’s house, and she is responsible for her flock.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":893,"lafz":true},{"key":"muslim","label":"مسلم","number":1829}],"full":1},{"num":6443,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ أَنَّ امْرَأَةً قَالَتْ يَا رَسُولَ اللَّهِ: صلّ عليّ وَعَلَى زَوْجِي صَلَّى اللَّهُ عَلَيْكِ. فَقَالَ: صَلَّى اللَّهُ عَلَيْكِ وَعَلَى زَوْجِكِ."],"takhrij":"صحيح: رواه أبو داوود (1533) وأحمد (15281) كلاهما من حديث أبي عوانة، عن الأسود بن قيس، عن نُبيح العنزي، عن جابر فذكره اختصره أبو داود واللفظ له، وأطاله أحمد، وإسناده صحيح، ونُبيح – مصغرا – ابن عبد الله العنزي ثقة، وثّقه أبو زرعة والعجلي، وذكره ابن حبان في \"الثقات\".","grade":"صحيح","chapter_ar":"باب شفقة رسول الله ﷺ للنساء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (1533) and Aḥmad (15281).","chapter_en":"The Compassion of the Messenger of Allah ﷺ Toward Women","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":50,"content":{"translation":{"en":["Jābir said: A woman said: O Messenger of Allah, pray for me and for my husband — may Allah send blessings upon you. So he said: “May Allah send blessings upon you and upon your husband.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1533,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":15281,"n":15281}],"full":1},{"num":6444,"demo":false,"sanad":"","matn":["عن عُرْوَةَ بن الزُّبَيْرِ أَنَّ عَائِشَةَ، زَوْجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخْبَرَتْهُ أَنَّ النِّكَاحَ فِي الْجَاهِلِيَّةِ كَانَ عَلَى أَرْبَعَةِ أَنْحَاءٍ فَنِكَاحٌ مِنْهَا نِكَاحُ النَّاسِ الْيَوْمَ، يَخْطُبُ الرَّجُلُ إِلَى الرَّجُلِ وَلِيَّتَهُ أَوِ ابْنَتَهُ، فَيُصْدِقُهَا ثُمَّ يَنْكِحُهَا، وَنِكَاحٌ آخَرُ كَانَ الرَّجُلُ يَقُولُ لاِمْرَأَتِهِ إِذَا طَهُرَتْ مِنْ طَمْثِهَا أَرْسِلِي إِلَى فُلاَنٍ فَاسْتَبْضِعِي مِنْهُ. وَيَعْتَزِلُهَا زَوْجُهَا، وَلاَ يَمَسُّهَا أَبَدًا، حَتَّى يَتَبَيَّنَ حَمْلُهَا مِنْ ذَلِكَ الرَّجُلِ الَّذِي تَسْتَبْضِعُ مِنْهُ، فَإِذَا تَبَيَّنَ حَمْلُهَا أَصَابَهَا زَوْجُهَا إِذَا أَحَبَّ، وَإِنَّمَا يَفْعَلُ ذَلِكَ رَغْبَةً فِي نَجَابَةِ الْوَلَدِ، فَكَانَ هَذَا النِّكَاحُ نِكَاحَ الاِسْتِبْضَاعِ، وَنِكَاحٌ آخَرُ يَجْتَمِعُ الرَّهْطُ مَا دُونَ الْعَشَرَةِ فَيَدْخُلُونَ عَلَى الْمَرْأَةِ كُلُّهُمْ يُصِيبُهَا. فَإِذَا حَمَلَتْ وَوَضَعَتْ، وَمَرَّ عَلَيْهَا لَيَالِيَ بَعْدَ أَنْ تَضَعَ حَمْلَهَا، أَرْسَلَتْ إِلَيْهِمْ فَلَمْ يَسْتَطِعْ رَجُلٌ مِنْهُمْ أَنْ يَمْتَنِعَ حَتَّى يَجْتَمِعُوا عِنْدَهَا تَقُولُ لَهُمْ قَدْ عَرَفْتُمُ الَّذِي كَانَ مِنْ أَمْرِكُمْ، وَقَدْ وَلَدْتُ فَهُوَ ابْنُكَ يَا فُلاَنُ. تُسَمِّي مَنْ أَحَبَّتْ بِاسْمِهِ، فَيَلْحَقُ بِهِ وَلَدُهَا، لاَ يَسْتَطِيعُ أَنْ يَمْتَنِعَ بِهِ الرَّجُلُ. وَنِكَاحُ الرَّابِعِ يَجْتَمِعُ النَّاسُ الْكَثِيرُ فَيَدْخُلُونَ عَلَى الْمَرْأَةِ لاَ تَمْتَنِعُ مِمَّنْ جَاءَهَا وَهُنَّ الْبَغَايَا كُنَّ يَنْصِبْنَ عَلَى أَبْوَابِهِنَّ رَايَاتٍ تَكُونُ عَلَمًا فَمَنْ أَرَادَهُنَّ دَخَلَ عَلَيْهِنَّ، فَإِذَا حَمَلَتْ إِحْدَاهُنَّ وَوَضَعَتْ حَمْلَهَا جُمِعُوا لَهَا وَدَعَوْا لَهُمُ الْقَافَةَ ثُمَّ أَلْحَقُوا وَلَدَهَا بِالَّذِي يَرَوْنَ فَالْتَاطَ بِهِ، وَدُعِيَ ابْنَهُ لاَ يَمْتَنِعُ مِنْ ذَلِكَ، فَلَمَّا بُعِثَ مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْحَقِّ هَدَمَ نِكَاحَ الْجَاهِلِيَّةِ كُلَّهُ، إِلاَّ نِكَاحَ النَّاسِ الْيَوْمَ."],"takhrij":"صحيح: رواه البخاري في النكاح (5127) من طريق ابن وهب، وعنبسة – كلاهما عن يونس ( هو ابن يزيد الأيلي )، عن ابن شهاب قال أخبرني عروة بن الزبير، فذكره.","grade":"صحيح","chapter_ar":"باب أنكحة أهل الجاهلية التي أقرها الإسلام","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5127). Her words “faltāṭat-hu” mean: she attached him to him as his child. The root meaning of lawṭ is attachment or sticking.","chapter_en":"The Forms of Marriage in the Pre-Islamic Period That Islam Approved","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":1,"content":{"translation":{"en":["ʿUrwah ibn al-Zubayr narrated that ʿA’ishah, the wife of the Prophet ﷺ, informed him that marriage in the pre-Islamic period was of four types. One type was like the marriage of people today: a man would propose to another man for his ward or daughter, give her a dowry, and then marry her. Another type was that a man would say to his wife, when she became pure from her menstruation: Send to so-and-so and seek seed from him. Her husband would then stay away from her and not touch her at all until her pregnancy from that man became clear. When it became clear that she was pregnant, her husband would have relations with her if he wished. They only did that out of desire for noble offspring. This marriage was called nikāḥ al-istibḍāʿ. Another type of marriage was that a group of men, fewer than ten, would gather and all go to one woman and have intercourse with her. If she became pregnant and then gave birth, and some nights passed after she had delivered, she would send for them, and no man among them could refuse until they had gathered with her. She would say to them: You know what happened among you, and now I have given birth, so he is your son, O so-and-so — naming whichever of them she wished — and her child would then be attached to him, and the man could not refuse. The fourth type of marriage was that many men would gather and enter upon a woman, and she would not prevent any who came to her. These were the prostitutes. They used to set up flags over their doors as a sign, and whoever wanted them entered upon them. If one of them became pregnant and then gave birth, they would gather for her and summon the physiognomists, then they would attribute her child to whichever man they thought fit. She would then attach him to that man, and he would be called his son, and he could not refuse that. But when Muhammad ﷺ was sent with the truth, he abolished all the forms of marriage from the pre-Islamic period except the marriage of people today."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5127,"lafz":true}],"full":1,"dr":1},{"num":6445,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ يُجْمَعُ بَيْنَ الْمَرْأَةِ وَعَمَّتِهَا، وَلاَ بَيْنَ الْمَرْأَةِ وَخَالَتِهَا."],"takhrij":"متفق عليه: رواه مالك في النكاح (20) عن أبي الزناد، عن الأعرج، عن أبي هريرة، فذكره. ورواه البخاري في النكاح (5109)، ومسلم في النكاح (33:1408) كلاهما من طريق مالك، به، مثله.","grade":"متفق عليه","chapter_ar":"باب النهي عن الجمع بين المرأة وعمتها أو خالتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (20), al-Bukhari (5109), and Muslim (1408 no. 33).","chapter_en":"The Prohibition of Combining a Woman with Her Paternal Aunt or Maternal Aunt in Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Abu Hurairah narrated that the Messenger of Allah ﷺ said: “A woman must not be joined in marriage with her paternal aunt, nor with her maternal aunt.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":20},{"key":"bukhari","label":"البخاري","number":5109,"lafz":true},{"key":"muslim","label":"مسلم","number":33}],"full":1,"dr":1},{"num":6446,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: نهى رسول الله صلى الله عليه وسلم أن تنكح المرأة على عمتها أو خالتها."],"takhrij":"صحيح: رواه البخاري في النكاح (5108) عن عبدان، أخبرنا عبد الله، أخبرنا عاصم، عن الشعبي، سمع جابراً يقول: فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الجمع بين المرأة وعمتها أو خالتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5108).","chapter_en":"The Prohibition of Combining a Woman with Her Paternal Aunt or Maternal Aunt in Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["From Jabir ibn ʿAbdullah: The Messenger of Allah ﷺ forbade that a woman be married together with her paternal aunt or her maternal aunt."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5108,"lafz":true}],"full":1,"dr":1},{"num":6447,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ تُنْكَحَ الْمَرْأَةُ عَلَى عَمَّتِهَا أَوِ الْعَمَّةُ عَلَى ابْنَةِ أَخِيهَا أَوِ الْمَرْأَةُ عَلَى خَالَتِهَا أَوِ الْخَالَةُ عَلَى بِنْتِ أُخْتِهَا لاَ تُنْكَحُ الصُّغْرَى عَلَى الْكُبْرَى وَلاَ الْكُبْرَى عَلَى الصُّغْرَى."],"takhrij":"صحيح: رواه أبو داوود (2065) والترمذي (1126) والنسائي (3296) وابن أبي شيبة (4/246) وابن نصر المروزي في السنة (239) وابن الجارود (685) و ابن حبان (4117) كلهم من حديث داود بن أبي هند حدثنا عامر الشعبي، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الجمع بين المرأة وعمتها أو خالتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2065), al-Tirmidhi (1126), and al-Nasa’i (3296). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"The Prohibition of Combining a Woman with Her Paternal Aunt or Maternal Aunt in Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Abu Hurairah narrated from the Prophet ﷺ that he forbade that a woman be married together with her paternal aunt, or that the aunt be married together with her brother’s daughter, or that a woman be married together with her maternal aunt, or that the maternal aunt be married together with her sister’s daughter. And the younger must not be married together with the elder, nor the elder together with the younger."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2065,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1126},{"key":"nasai","label":"النسائي","number":3296},{"key":"sh13071","label":"ابن الجارود","number":685,"n":712},{"key":"ibnhibban","label":"و ابن حبان","number":4117}],"full":1,"dr":1},{"num":6448,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عَبَّاسٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ تُزَوَّجَ الْمَرْأَةُ عَلَى عَمَّتِهَا، أَوْ عَلَى خَالَتِهَا."],"takhrij":"صحيح: رواه الترمذي (1125) عن نصر بن علي، ثنا عبد الأعلى بن عبد الأعلى، حدثنا سعيد بن أبي عروبة، عن أبي حَريز، عن عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الجمع بين المرأة وعمتها أو خالتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1125). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"The Prohibition of Combining a Woman with Her Paternal Aunt or Maternal Aunt in Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbas narrated that the Prophet ﷺ forbade that a woman be married together with her paternal aunt or her maternal aunt."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1125,"lafz":true}],"full":1,"dr":1},{"num":6449,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده قال: لما فُتحت مكة على رسول الله صلى الله عليه وسلم قال: فذكر الحديث بطوله وفيه ولا تُنكح المرأة على عمتها، ولا على خالتها."],"takhrij":"حسن: رواه أحمد (6681، 6712) وابن أبي شيبة (4/247) وعبد الرزاق (10750) والمروزي في السنة (246،245) كلهم من حديث عمرو بن شعيب بإسناده.","grade":"حسن","chapter_ar":"باب النهي عن الجمع بين المرأة وعمتها أو خالتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6712, 6681), Ibn Abi Shaybah (4/247), and ʿAbd al-Razzaq (10750).","chapter_en":"The Prohibition of Combining a Woman with Her Paternal Aunt or Maternal Aunt in Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb, from his father, from his grandfather, said: When Mecca was opened to the Messenger of Allah ﷺ, he said — then he mentioned the hadith in full, and in it was: “A woman must not be married together with her paternal aunt, nor together with her maternal aunt.”"]}},"tuhfa":{},"refs":[{"key":"sh9944","label":"ابن أبي شيبة","number":247},{"key":"abdrazzaq","label":"عبد الرزاق","number":10750},{"key":"ahmad","label":"مسند الإمام أحمد","number":6712,"n":6681,"lafz":true},{"key":"ahmad","label":"احمد","number":6681}],"full":1,"dr":1},{"num":6450,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى أَنْ يَجْمَعَ بَيْنَ الْمَرْأَةِ وَخَالَتِهَا، وَبَيْنَ الْمَرْأَةِ وَعَمَّتِهَا."],"takhrij":"حسن: رواه ابن ماجة (1930) وأحمد (11637) وابن نصر المروزي في السنة (242) وابن أبي شيبة (4/246) كلهم من حديث محمد بن إسحاق، عن يعقوب بن عبد الله بن عتبة، عن سليمان بن يسار، عن أبي سعيد الخدري فذكره في حديث طويل.","grade":"حسن","chapter_ar":"باب النهي عن الجمع بين المرأة وعمتها أو خالتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (1930), Ahmad (11637), and Ibn Nasr al-Marwazi in al-Sunnah (242).","chapter_en":"The Prohibition of Combining a Woman with Her Paternal Aunt or Maternal Aunt in Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: I heard the Messenger of Allah ﷺ forbidding that a woman be combined in marriage with her maternal aunt, and that a woman be combined with her paternal aunt."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":1930,"lafz":true},{"key":"rb295","label":"ابن نصر المروزي في السنة","number":242},{"key":"ahmad","label":"مسند الإمام أحمد","number":11637,"n":11637}],"full":1,"dr":1},{"num":6451,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّهَا قَالَتْ: وَجَدْتُ فِي قَائِمِ سَيْفِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كِتَابًا: إِنَّ أَشَدَّ النَّاسِ عُتُوًّا مَنْ ضَرَبَ غَيْرَ ضَارِبِهِ، وَرَجُلٌ قَتَلَ غَيْرَ قَاتِلِهِ، وَرَجُلٌ تَوَلَّى غَيْرَ أَهْلِ نِعْمَتِهِ، فَمَنْ فَعَلَ ذَلِكَ فَقَدْ كَفَرَ بِاللَّهِ وَرَسُولِهِ لَا يَقْبَلُ اللَّهُ مِنْهُ صَرْفًا وَلَا عَدْلًا، وَفِي الْأَجْرِ الْمُؤْمِنُونَ تَكَافَأُ دِمَاؤُهُمْ وَيَسْعَى بِذِمَّتِهِمْ أَدْنَاهُمْ. لَا يُقْتَلُ مُسْلِمٌ بِكَافِرٍ وَلَا ذُو عَهْدٍ فِي عَهْدِهِ، وَلَا يَتَوَارَثُ أَهْلُ مِلَّتَيْنِ، وَلَا تُنْكَحُ الْمَرْأَةُ عَلَى عَمَّتِهَا وَلَا عَلَى خَالَتِهَا، وَلَا صَلَاةَ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ، وَلَا تُسَافِرُ امْرَأَةٌ ثَلَاثَ لَيَالٍ مَعَ غَيْرِ ذِي مَحْرَمٍ."],"takhrij":"حسن: رواه أبو يعلى (4757) والدارقطني (3/131) والحاكم (4/349) والبيهقي (8/29-30) والمروزي في السنة (248) كلهم من طرق عن عبيد الله بن عبد الرحمن بن موهب، قال: سمعت مالك بن محمد بن عبد الرحمن، قال: سمعت عمرة بنت عبد الرحمن، عن عائشة قالت: فذكرته واختصره البعض.","grade":"حسن","chapter_ar":"باب النهي عن الجمع بين المرأة وعمتها أو خالتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Yaʿla (4757), al-Daraqutni (3/131), al-Hakim (4/349), and al-Bayhaqi (8/29–30).","chapter_en":"The Prohibition of Combining a Woman with Her Paternal Aunt or Maternal Aunt in Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["ʿA’ishah said: I found in the hilt of the sword of the Messenger of Allah ﷺ a written statement: “Among the most severe of people in transgression are: a man who strikes someone other than the one who struck him, a man who kills someone other than his killer, and a man who allies himself with people other than those who bestowed their patronage upon him. Whoever does that has disbelieved in Allah and His Messenger. Allah will accept from him neither compensation nor ransom. In retaliation, the believers’ blood is equal, and even the least of them may grant protection on their behalf. A Muslim is not to be killed for a disbeliever, nor one under covenant while he is under his covenant. The people of two different religions do not inherit from one another. A woman must not be married together with her paternal aunt, nor with her maternal aunt. There is no prayer after ʿAsr until the sun sets, and a woman must not travel for three nights without a mahram.”"]},"buhuth":{"en":["As for His statement, after mentioning the women forbidden in marriage: “And lawful to you is whatever is beyond that” [Surat al-Nisa’ 4:24], this general wording is specified by the hadiths of this chapter, and no one has differed over that. Al-Shafiʿi reported from all the jurists that combining those mentioned in the hadiths of this chapter is forbidden.","As for combining a man’s wife with his daughter from another woman, there is no harm in that, just as ʿAbdullah ibn Jaʿfar combined Zaynab daughter of ʿAli — and in another narration, Umm Kulthum daughter of ʿAli — together with ʿAli’s wife, who was Layla bint Masʿud al-Nahshaliyyah. Likewise, there is no harm in combining two female cousins from paternal uncles. Al-Hasan ibn al-Hasan ibn ʿAli combined two daughters of paternal uncles in one night.","(All of this was mentioned by al-Bukhari in suspended form in the Book of Marriage, Chapter 24: What is lawful of women and what is forbidden.)"]}},"tuhfa":{},"refs":[{"key":"sh12520","label":"أبو يعلى","number":4757,"lafz":true},{"key":"sh9771","label":"الدار قطني","number":131},{"key":"hakim","label":"الحاكم","number":349},{"key":"kubrabayhaqi","label":"البيهقي","number":30}],"full":1,"dr":1,"rep":[6080,6857]},{"num":6452,"demo":false,"sanad":"","matn":["عن أُمِّ حَبِيبَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حدثتها أَنَّهَا قَالَتْ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَا رَسُولَ اللَّهِ انْكِحْ أُخْتِي عَزَّةَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَتُحِبِّينَ ذَلِكِ. فَقَالَتْ نَعَمْ يَا رَسُولَ اللَّهِ لَسْتُ لَكَ بِمُخْلِيَةٍ وَأَحَبُّ مَنْ شَرِكَنِي فِي خَيْرٍ أُخْتِي. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَإِنَّ ذَلِكِ لاَ يَحِلُّ لِي. قَالَتْ فَقُلْتُ يَا رَسُولَ اللَّهِ فَإِنَّا نَتَحَدَّثُ أَنَّكَ تُرِيدُ أَنْ تَنْكِحَ دُرَّةَ بِنْتَ أَبِي سَلَمَةَ. قَالَ بِنْتَ أَبِي سَلَمَةَ. قَالَتْ نَعَمْ. قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَوْ أَنَّهَا لَمْ تَكُنْ رَبِيبَتِي فِي حَجْرِي مَا حَلَّتْ لِي إِنَّهَا ابْنَةُ أَخِي مِنَ الرَّضَاعَةِ أَرْضَعَتْنِي وَأَبَا سَلَمَةَ ثُوَيْبَةُ فَلاَ تَعْرِضْنَ عَلَىَّ بَنَاتِكُنَّ وَلاَ أَخَوَاتِكُنَّ."],"takhrij":"متفق عليه: رواه مسلم في الرضاعة (16:1449) عن محمد بن رمح بن المهاجر، أخبرنا الليث، عن يزيد بن أبي حببيب، أن محمد بن شهاب كتب يذكر أن عروة حدثه، أن زينب بنت أبي سلمة حدثته، أن أم حبيبـة زوج النبي صلى الله عليه وسلم حدثتها فذكرته.","grade":"متفق عليه","chapter_ar":"باب النهي عن الجمع بين الأختين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (1449 no. 16) and al-Bukhari (5107).","chapter_en":"The Prohibition of Combining Two Sisters in Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":4,"content":{"translation":{"en":["Umm Habibah, the wife of the Prophet ﷺ, narrated that she said to the Messenger of Allah ﷺ: O Messenger of Allah, marry my sister ʿAzzah. The Messenger of Allah ﷺ said: “Would you like that?” She said: Yes, O Messenger of Allah. I am not exclusive to you, and the one I most love to share in good with me is my sister. The Messenger of Allah ﷺ said: “That is not lawful for me.” She said: Then I said: O Messenger of Allah, we hear that you want to marry Durrah, the daughter of Abu Salamah. He said: “The daughter of Abu Salamah?” She said: Yes. The Messenger of Allah ﷺ said: “If she were not my stepdaughter in my care, she still would not be lawful for me. She is the daughter of my brother through nursing. Thuwaybah nursed me and Abu Salamah. So do not offer your daughters or your sisters to me.”"]},"intro":{"ar":["قال الله تعالى: ( وَأَن تَجْمَعُوا بَيْنَ ٱلْأُخْتَيْنِ ) [النساء: ٢٣]"],"en":["Allah the Exalted said: “And that you combine two sisters in marriage.” [Surat al-Nisa’ 4:23]"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":16,"lafz":true},{"key":"bukhari","label":"البخاري","number":5107}],"full":1,"dr":1,"rep":[6456]},{"num":6453,"demo":false,"sanad":"","matn":["عَنْ الْبَرَاءِ بْنِ عَازِبٍ قَالَ: لَقِيتُ عَمِّي وَمَعَهُ رَايَةٌ، فَقُلْتُ لَهُ: أَيْنَ تُرِيدُ؟ قَالَ: بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى رَجُلٍ نَكَحَ امْرَأَةَ أَبِيهِ، فَأَمَرَنِي أَنْ أَضْرِبَ عُنُقَهُ، وَآخُذَ مَالَهُ."],"takhrij":"صحيح: رواه أبو داوود (4457) والنسائي (3332) وابن الجارود (681) والحاكم (4/357) ومن طريقه البيهقي (7/162) والدارقطني في \"العلل\" (6/22) كلهم من طريق زيد بن أبي أنيسة، عن عدي بن ثابت، عن يزيد بن البراء، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن نكاح ما نكح الآباءُ","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (4457), al-Nasa’i (3332), Ibn al-Jarud (681), and al-Hakim (4/357).","chapter_en":"The Prohibition of Marrying the Women Whom One’s Fathers Married","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":6,"content":{"translation":{"en":["Al-Bara’ ibn ʿAzib said: I met my uncle while he had a banner with him, so I said to him: Where are you going? He said: The Messenger of Allah ﷺ sent me to a man who had married his father’s wife, and he ordered me to strike off his neck and take his wealth."]},"buhuth":{"en":["His saying “my uncle,” and in another narration “my maternal uncle,” do not conflict. He may have been his paternal uncle by lineage and his maternal uncle by nursing. Since his name appears explicitly as al-Harith ibn ʿAmr, or Abu Burdah ibn Niyar, the more apparent view is that he was his maternal uncle, not his paternal uncle."]},"intro":{"ar":["قال الله تعالى: ( وَلَا تَنكِحُوا مَا نَكَحَ ءَابَآؤُكُم مِّنَ ٱلنِّسَآءِ إِلَّا مَا قَدْ سَلَفَ ) [النساء: ٢٢]","كان أهل الجاهلية يتزوجون بأزواج آبائهم، ويعدون ذلك من الإرث، فجاء النهي عن هذا وهو للتحريم."],"en":["Allah the Exalted said: “And do not marry those women whom your fathers married, except what has already passed.” [Surat al-Nisa’ 4:22]","The people of the pre-Islamic period used to marry the wives of their fathers and regarded that as part of inheritance. Then the prohibition came regarding this, and it is a prohibition of unlawfulness."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4457,"lafz":true},{"key":"nasai","label":"النسائي","number":3332,"n":3332},{"key":"sh13071","label":"ابن الجارود","number":681},{"key":"hakim","label":"المستدرك على الصحيحين","number":8056,"n":8062}],"full":1,"dr":1},{"num":6454,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ، قَالَ بَيْنَا أَنَا أَطُوفُ، عَلَى إِبِلٍ لِي ضَلَّتْ إِذْ أَقْبَلَ رَكْبٌ أَوْ فَوَارِسُ مَعَهُمْ لِوَاءٌ فَجَعَلَ الأَعْرَابُ يُطِيفُونَ بِي لِمَنْزِلَتِي مِنَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ أَتَوْا قُبَّةً فَاسْتَخْرَجُوا مِنْهَا رَجُلاً فَضَرَبُوا عُنُقَهُ فَسَأَلْتُ عَنْهُ فَذَكَرُوا أَنَّهُ أَعْرَسَ بِامْرَأَةِ أَبِيهِ."],"takhrij":"صحيح: رواه أبو داوود (4456) وأحمد (18609) والطحاوي في شرحه (3/149) وسعيد بن منصور (943) كلهم من حديث مطرف، عن أبي الجهم، عن البراء بن عازب فذكره مثله. إلا عند أحمد: دخل بأم امرأته.","grade":"صحيح","chapter_ar":"باب النهي عن نكاح ما نكح الآباءُ","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4456), Aḥmad (18609), al-Ṭaḥāwī in Sharḥ Maʿānī al-Āthār (3/149), and Saʿīd ibn Manṣūr (943).","chapter_en":"The Prohibition of Marrying the Women Whom One’s Fathers Married","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":6,"content":{"translation":{"en":["Al-Barāʾ ibn ʿĀzib reported: While I was going around looking for some camels of mine that had strayed, a caravan—or some horsemen—approached carrying a banner. The Bedouins began gathering around me because of my position with the Prophet ﷺ. They came to a domed structure, brought a man out of it, and struck off his neck. I asked about him, and they told me that he had married his father’s wife."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4456,"lafz":true},{"key":"sh21108","label":"الطحاوي في شرح معاني الآثار","number":3},{"key":"sh13122","label":"سعيد بن منصور","number":943},{"key":"ahmad","label":"مسند الإمام أحمد","number":18609,"n":18609}],"full":1,"dr":1},{"num":6455,"demo":false,"sanad":"","matn":["عَنْ قرة قَالَ: بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى رَجُلٍ تَزَوَّجَ امْرَأَةَ أَبِيهِ، أَنْ أَضْرِبَ عُنُقَهُ، وأُصفّي مَالَهُ."],"takhrij":"حسن: رواه ابن ماجة (2608) والدارقطني (3/200) والبيهقي (8/208) كلهم من حديث عبدالله بن إدريس، عن خالد بن أبي كريمة، عن معاوية بن قرة، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب النهي عن نكاح ما نكح الآباءُ","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2608), al-Daraqutni (3/200), and al-Bayhaqi (8/208).","chapter_en":"The Prohibition of Marrying the Women Whom One’s Fathers Married","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":6,"content":{"translation":{"en":["Qurrah said: The Messenger of Allah ﷺ sent me to a man who had married his father’s wife, ordering me to strike off his neck and confiscate his wealth."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2608,"lafz":true},{"key":"sh9771","label":"الدار قطني","number":200},{"key":"kubrabayhaqi","label":"البيهقي","number":208}],"full":1,"dr":1},{"num":6456,"demo":false,"sanad":"","matn":["عن أُمِّ حَبِيبَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حدثتها أَنَّهَا قَالَتْ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَا رَسُولَ اللَّهِ انْكِحْ أُخْتِي عَزَّةَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَتُحِبِّينَ ذَلِكِ. فَقَالَتْ نَعَمْ يَا رَسُولَ اللَّهِ لَسْتُ لَكَ بِمُخْلِيَةٍ وَأَحَبُّ مَنْ شَرِكَنِي فِي خَيْرٍ أُخْتِي. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَإِنَّ ذَلِكِ لاَ يَحِلُّ لِي. قَالَتْ فَقُلْتُ يَا رَسُولَ اللَّهِ فَإِنَّا نَتَحَدَّثُ أَنَّكَ تُرِيدُ أَنْ تَنْكِحَ دُرَّةَ بِنْتَ أَبِي سَلَمَةَ. قَالَ بِنْتَ أَبِي سَلَمَةَ. قَالَتْ نَعَمْ. قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَوْ أَنَّهَا لَمْ تَكُنْ رَبِيبَتِي فِي حَجْرِي مَا حَلَّتْ لِي إِنَّهَا ابْنَةُ أَخِي مِنَ الرَّضَاعَةِ أَرْضَعَتْنِي وَأَبَا سَلَمَةَ ثُوَيْبَةُ فَلاَ تَعْرِضْنَ عَلَىَّ بَنَاتِكُنَّ وَلاَ أَخَوَاتِكُنَّ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5107) ومسلم في الرضاعة (16:1449) كلاهما من طريق محمد بن شهاب الزهري، أن عروة أخبره أن زينب بنت أبي سلمة أخبرته أن أم حبيبة قالت: فذكرته.","grade":"متفق عليه","chapter_ar":"باب تحريم نكاح الربيبات","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5107) and Muslim (1449/16).","chapter_en":"The Prohibition of Marrying Stepdaughters","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":7,"content":{"translation":{"en":["Umm Ḥabībah, the wife of the Prophet ﷺ, reported that she said to the Messenger of Allah ﷺ: “O Messenger of Allah, marry my sister ʿAzzah.” The Messenger of Allah ﷺ asked: “Would you like that?” She replied: “Yes, O Messenger of Allah. I am not your only wife, and the person I would most love to share this good with me is my sister.” The Messenger of Allah ﷺ said: “That is not lawful for me.” She said: “I said: O Messenger of Allah, we have been told that you intend to marry Durrah, the daughter of Abū Salamah.” He asked: “The daughter of Abū Salamah?” She replied: “Yes.” The Messenger of Allah ﷺ said: “Even if she were not my stepdaughter under my care, she would not be lawful for me. She is the daughter of my foster-brother. Thuwaybah nursed both me and Abū Salamah. So do not offer your daughters or your sisters to me.”"]},"buhuth":{"en":["Thus, the Prophet ﷺ, Abū Salamah, and Ḥamzah were brothers through breastfeeding."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5107,"lafz":true},{"key":"muslim","label":"مسلم","number":1449,"n":3588},{"key":"muslim","label":"مسلم في الرضاعه","number":16}],"full":1,"dr":1,"rep":[6452]},{"num":6457,"demo":false,"sanad":"","matn":["عَنْ عُرْوَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَطَبَ عَائِشَةَ إِلَى أَبِي بَكْرٍ فَقَالَ لَهُ أَبُو بَكْرٍ إِنَّمَا أَنَا أَخُوكَ، فَقَالَ أَنْتَ أَخِي فِي دِينِ اللَّهِ وَكِتَابِهِ وَهْىَ لِي حَلاَلٌ."],"takhrij":"صحيح: رواه البخاري في النكاح (5081) عن عبد الله بن يوسف، حدثنا الليث، عن يزيد، عن عراك، عن عروة فذكره.","grade":"صحيح","chapter_ar":"باب بنت الأخ في الدين لا تحرم","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5081).","chapter_en":"The daughter of one’s brother in religion is not forbidden in marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["ʿUrwah narrated that the Prophet ﷺ proposed for ʿA’ishah to Abu Bakr. Abu Bakr said to him: I am only your brother. He said: “You are my brother in the religion of Allah and His Book, and she is lawful for me.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5081,"lafz":true}],"full":1,"dr":1,"rep":[10402]},{"num":6458,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ غَيْلَانَ بْنَ سَلَمَةَ الثَّقَفِيَّ أَسْلَمَ وَعِنْدَهُ عَشْرُ نِسْوَةٍ، فَأَمَرَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُمْسِكَ مِنْهُنَّ أَرْبَعًا. فَلَمَّا كَانَ زَمَانُ عُمَرَ طَلَّقَهُنَّ فَأَمَرَهُ عُمَرُ أَنْ يَرْتَجِعَهُنَّ، وَقَالَ: لَوْ مُتَّ لَوَرَّثْتُهُنَّ مِنْكَ وَلَأَمَرْتُ بِقَبْرِكَ يُرْجَمُ كَمَا رُجِمَ قَبْرُ أَبِي رِغَالٍ."],"takhrij":"حسن: رواه النسائي كما ذكره الحافظ في التلخيص (3/169) ولم أجده في \"الكبرى\" ولا في \"المجتبى\" كما لم يذكره أيضا ابن الملقن في \"البدر المنير\" ورواه الدارقطني (3/271) والبيهقي (7/183) كلهم من طريق سيف بن عبيد الله الجرمي، حدثنا سرّار بن مُجشّر أبو عبيدة العنزي، عن أيوب، عن نافع وسالم، عن ابن عمر فذكره واللفظ للدارقطني.","grade":"حسن","chapter_ar":"باب من أسلم وتحته أكثر من أربع نسوة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i as cited by al-Hafiz in al-Talkhis (3/169), al-Daraqutni (3/271), and al-Bayhaqi (7/183).","chapter_en":"One Who Accepts Islam While Married to More Than Four Women","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿUmar narrated that Ghaylan ibn Salamah al-Thaqafi accepted Islam while he had ten wives, so the Prophet ﷺ ordered him to keep four of them. Then during the time of ʿUmar he divorced them, and ʿUmar ordered him to take them back. He said: If you were to die, they would inherit from you, and I would order your grave to be stoned just as the grave of Abu Righal was stoned."]},"buhuth":{"en":["His saying: “the grave of Abu Righal” — with the letter ra’ read with kasrah — refers to a man from Thamud. He was in the sanctuary when the cry struck his people. When he left the sanctuary, destruction struck him just as it struck his people. He was buried there between Mecca and Ta’if. He had been a tax collector in earlier times, so people stoned his grave. Jarir said:","“When al-Farazdaq dies, stone him","just as you stone the grave of Abu Righal.”"]},"intro":{"ar":["قال الله تعالى: ( فَٱنكِحُوا مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثْنَىٰ وَثُلَٰثَ وَرُبَٰعَ ) [سورة النساء: ٣]"],"en":["Allah the Exalted said: “Then marry what seems good to you of women: two, three, or four.” [Surat al-Nisa’ 4:3]"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي كما ذكره الحافظ في التلخيص","number":169,"lafz":true},{"key":"sh9771","label":"الدار قطني","number":271},{"key":"kubrabayhaqi","label":"البيهقي","number":183},{"key":"sh9771","label":"سنن الدارقطني","number":3694,"n":3706}],"full":1,"dr":1},{"num":6459,"demo":false,"sanad":"","matn":["عن عبدالله بن مسعود قال: كنا نغزو مع رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ليس لنا نساء، فقلنا: ألا نستخصي؟ فنهانا عن ذلك. ثم رخّص لنا أن ننْكح المرأة بالثوب إلى أجل. ثم قرأ عبد الله ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تُحَرِّمُوا طَيِّبَاتِ مَا أَحَلَّ اللَّهُ لَكُمْ وَلَا تَعْتَدُوا إِنَّ اللَّهَ لَا يُحِبُّ الْمُعْتَدِينَ﴾ [سورة المائدة: ٨٧]"],"takhrij":"متفق عليه: رواه البخاري في النكاح (5075) ومسلم في النكاح (11:1404) كلاهما من طريق إسماعيل (هو ابن أبي خالد)، عن قيس، قال: سمعت عبد الله يقول: فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5075) and Muslim (1404 no. 11). The wording is that of Muslim.","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Ibn Masʿud said: We used to go out in battle with the Messenger of Allah ﷺ while we had no women with us, so we said: Shall we castrate ourselves? He forbade us from that. Then he gave us permission to marry a woman for a fixed term in exchange for a garment. Then ʿAbdullah recited: “O you who believe, do not forbid the good things Allah has made lawful for you, and do not transgress. Indeed, Allah does not love the transgressors.” [Surat al-Ma’idah 5:87]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5075,"lafz":true},{"key":"muslim","label":"مسلم","number":11}],"full":1,"dr":1,"rep":[12274]},{"num":6460,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ قَالَ: كُنَّا نَغْزُو مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَتَطُولُ غُربتنا. فَقُلْنَا: أَلَا نستخصي يَا رَسُولَ اللَّهِ! فَنَهَانَا، ثُمَّ رَخَّصَ أَنْ نَتَزَوَّجَ الْمَرْأَةَ إِلَى أَجَلٍ بِالشَّيءِ، ثُمَّ نَهَانَا عَنْهَا يَوْمَ خَيْبَرَ، وَعَنْ لُحُومِ الْحُمُرِ الأهلية."],"takhrij":"صحيح: رواه عبد الرزاق (14048) عن ابن عيينة، عن إسماعيل، عن قيس، عن عبد الله بن مسعود فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by ʿAbd al-Razzaq (14048). The permission for temporary marriage was before Khaybar.","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Ibn Masʿud said: We used to go out in battle with the Messenger of Allah ﷺ and our absence would become long. So we said: O Messenger of Allah, shall we castrate ourselves? He forbade us from that. Then he permitted us to marry a woman for a fixed term in exchange for something, then he forbade it on the day of Khaybar, and also forbade the meat of domesticated donkeys."]}},"tuhfa":{},"refs":[{"key":"abdrazzaq","label":"عبد الرزاق","number":14048,"lafz":true},{"key":"abdrazzaq","label":"المصنف لعبد الرزاق","number":14981,"n":15074}],"full":1,"dr":1},{"num":6461,"demo":false,"sanad":"","matn":["عَنْ قَيْسٍ، عَنِ ابْنِ مَسْعُودٍ، قَالَ: كُنَّا نَغْزُو مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ شَبَابٌ، وَلَيْسَ لَنَا نِسَاءٌ، فَقُلْنَا: يَا رَسُولَ اللَّهِ، أَلَا نَسْتَخْصِي؟ فَنَهَانَا عَنْ ذَلِكَ."],"takhrij":"صحيح: رواه أحمد (3706) عن يزيد، حدثنا إسماعيل، عن قيس، عن ابن مسعود فذكره. ورواه مسلم (12:1404) عن أبي بكر بن أبي شيبة، حدثنا وكيع، عن إسماعيل بإسناده مثله غير أنه لم يقل فيه: نغزو","grade":"صحيح","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (3706).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["ʿAbdullah ibn Masʿud said: We used to go out in battle with the Messenger of Allah ﷺ while we were young men and had no women with us, so we said: O Messenger of Allah, shall we castrate ourselves? He forbade us from that."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":3706,"n":3706,"lafz":true},{"key":"muslim","label":"مسلم","number":12}],"full":1,"dr":1},{"num":6462,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ مُتْعَةِ النِّسَاءِ يَوْمَ خَيْبَرَ، وَعَنْ أَكْلِ الْحُمُرِ الإِنْسِيَّةِ."],"takhrij":"متفق عليه: رواه مالك في النكاح (41) عن ابن شهاب، عن عبد الله والحسن ابْني محمد بن علي بن أبي طالب، عن أبيهما، عن علي بن أبي طالب، فذكره. ورواه البخاري في المغازي (4216)، ومسلم في النكاح (29:1407) كلاهما من طريق مالك، به، مثله.","grade":"متفق عليه","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (41), al-Bukhari (4216), and Muslim (1407 no. 29).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["ʿAli ibn Abi Talib narrated that the Messenger of Allah ﷺ forbade temporary marriage with women on the day of Khaybar, and also forbade eating the meat of domesticated donkeys."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":41},{"key":"bukhari","label":"البخاري","number":4216,"lafz":true},{"key":"muslim","label":"مسلم","number":29}],"full":1,"dr":1,"rep":[7418]},{"num":6463,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ، أَنَّهُ سَمِعَ ابْنَ عَبَّاسٍ، يُلَيِّنُ فِي مُتْعَةِ النِّسَاءِ فَقَالَ مَهْلاً يَا ابْنَ عَبَّاسٍ فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْهَا يَوْمَ خَيْبَرَ وَعَنْ لُحُومِ الْحُمُرِ الإِنْسِيَّةِ."],"takhrij":"متفق عليه: رواه مسلم في النكاح (31:1407) عن محمد بن عبد الله ابن نمير، قال: حدثنا أبي، حدثنا عبد الله، عـن ابن شهاب، عن الحسـن وعبد الله ابني محمد بن علي، عن أبيهما، عن علي فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (1407 no. 31) and al-Bukhari (6961).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["ʿAli ibn Abi Talib heard Ibn ʿAbbas speaking leniently about temporary marriage with women, so he said: Take it easy, O Ibn ʿAbbas, for the Messenger of Allah ﷺ forbade it on the day of Khaybar, and he also forbade the meat of domesticated donkeys."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":31,"lafz":true},{"key":"bukhari","label":"البخاري","number":6961}],"full":1,"dr":1},{"num":6464,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب يقول لابن عباس: إنك رجل تائه، إن رسول الله صلى الله عليه وسلم نهى عن متعة النساء."],"takhrij":"صحيح: رواه الطحاوي في شرحه (3/24) من طريق جويرية عن مالك، عن الزهري، أن عبد الله بن محمد بن علي بن أبي طالب، والحسن بن محمد بن علي أخبراه، أن أباهما أخبرهما، أنه سمع علي بن أبي طالب يقول ذلك فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tahawi in his Sharh (3/24).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["ʿAli ibn Abi Talib said to Ibn ʿAbbas: You are a man who has erred. The Messenger of Allah ﷺ forbade temporary marriage with women."]}},"tuhfa":{},"refs":[{"key":"sh21108","label":"الطحاوي في شرحه","number":24,"lafz":true}],"full":1},{"num":6465,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ وَسَلَمَةَ بْنِ الأَكْوَعِ قَالاَ: كُنَّا فِي جَيْشٍ، فَأَتَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّهُ قَدْ أُذِنَ لَكُمْ أَنْ تَسْتَمْتِعُوا فَاسْتَمْتِعُوا. زَادَ مسلم: يَعْنِي متعة النِّسَاءِ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5118،5117) من طريق سفيان، ومسلم في النكاح (13:1405) من طريق شعبة- كلاهما عن عمرو بن دينار، قال: سمعت الحسن بن محمد يحدّث عن جابر بن عبد الله وسلمة بن الأكوع. فذكراه، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5117, 5118) and Muslim (1405 no. 13). The wording is that of al-Bukhari.","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Jabir ibn ʿAbd Allah and Salamah ibn al-Akwaʿ said: We were in an army, and the Messenger of Allah ﷺ came to us and said: “Permission has been given to you to contract temporary marriage, so do so.” Muslim added: “meaning temporary marriage with women.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5117,"lafz":true},{"key":"muslim","label":"مسلم","number":13},{"key":"bukhari","label":"البخاري في النكاح","number":5118}],"full":1},{"num":6466,"demo":false,"sanad":"","matn":["عَنْ إِيَاسِ بْنِ سَلَمَةَ، عَنْ أَبِيهِ، قَالَ رَخَّصَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ أَوْطَاسٍ فِي الْمُتْعَةِ ثَلاَثًا ثُمَّ نَهَى عَنْهَا."],"takhrij":"صحيح: رواه مسلم في النكاح (18:1405) عن أبي بكر بن أبي شيبة، حدثنا يونس بن محمد، حدثنا عبدالواحد بن زياد، حدثنا أبو عُميس، عن إياس بن سلمة، عن أبيه قال:فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1405 no. 18).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Salamah ibn al-Akwaʿ said: The Messenger of Allah ﷺ allowed temporary marriage during the year of Awtas for three days, then forbade it."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":18,"lafz":true}],"full":1,"dr":1},{"num":6467,"demo":false,"sanad":"","matn":["عن سلمة بن الأكوع، أن النبي صلى الله عليه وسلم قال: أيما رجل وامرأة أيم تراضيا بعشرتهما ثلاث ليال، فإن أرادا أن يتزايدا تزايدا، وإن أرادا أن يتشاركا شاركا."],"takhrij":"صحيح: رواه الطبراني في \"المعجم الكبير\" (7/27) من طريق محمد بن عباد المكي، ثنا حاتم بن إسماعيل، عن ابن أبي ذئب، عن إياس بن سلمة بن الأكوع، عن أبيه، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tabarani in al-Muʿjam al-Kabir (7/27).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Salamah ibn al-Akwaʿ narrated that the Prophet ﷺ said: “Any man and woman without spouses who mutually agree to live together for three nights, then if they wish to extend it, they may extend it, and if they wish to separate, they may separate.”"]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في “المعجم الكبير”","number":27,"lafz":true}],"full":1,"dr":1},{"num":6468,"demo":false,"sanad":"","matn":["عَنْ سَبْرَةَ الجهني أَنَّهُ أَذِنَ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْمُتْعَةِ، فَانْطَلَقْتُ أَنَا وَرَجُلٌ إِلَى امْرَأَةٍ مِنْ بَنِي عَامِرٍ، كَأَنَّهَا بَكْرَةٌ عَيْطَاءُ، فَعَرَضْنَا عَلَيْهَا أَنْفُسَنَا. فَقَالَتْ: مَا تُعْطِي؟ فَقُلْتُ: رِدَائِي. وَقَالَ صَاحِبِي: رِدَائِي، وَكَانَ رِدَاءُ صَاحِبِي أَجْوَدَ مِنْ رِدَائِي. وَكُنْتُ أشبّ مِنْهُ، فَإِذَا نَظَرَتْ إِلَى رِدَاءِ صَاحِبِي أَعْجَبَهَا، وَإِذَا نَظَرَتْ إِلَى أَعْجَبْتُهَا. ثُمَّ قَالَتْ: أَنْتَ وَرِدَاؤُكَ يَكْفِينِي، فَمَكَثْتُ مَعَهَا ثَلاَثًا. ثُمَّ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ كَانَ عِنْدَهُ شيء مِنْ هَذِهِ النِّسَاءِ الَّتِي يَتَمَتَّعُ، فَلْيُخَلِّ سَبِيلَهَا."],"takhrij":"صحيح: رواه مسلم في النكاح (19:1406) عن قتيبة بن سعيد، حدثنا ليث، عن الربيع بن سبرة الجهني، عن أبيه سبرة، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1406 no. 19).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Sabrah al-Juhani said: The Messenger of Allah ﷺ gave us permission for temporary marriage. So I and another man went out to a woman from Banu ʿAmir, and she was like a young tall camel in beauty and stature. We offered ourselves to her. She said: What will you give? I said: My cloak. And my companion said: My cloak. My companion’s cloak was better than mine, but I was younger than him. When she looked at my companion’s cloak, she liked it, and when she looked at me, she liked me. Then she said: You and your cloak are enough for me. So I stayed with her for three nights. Then the Messenger of Allah ﷺ said: “Whoever has any of these women with whom he contracted temporary marriage, let him release her.”"]},"buhuth":{"en":["His saying, “as though she were a young tall camel”: al-bakrah means a young strong woman, and al-ʿayṭa’ means one with a long neck in proportion and fine form."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":19,"lafz":true}],"full":1,"dr":1},{"num":6469,"demo":false,"sanad":"","matn":["عَنِ الرَّبِيعِ بْنِ سَبْرَةَ، أَنَّ أَبَاهُ، غَزَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَتْحَ مَكَّةَ قَالَ فَأَقَمْنَا بِهَا خَمْسَ عَشْرَةَ - ثَلاَثِينَ بَيْنَ لَيْلَةٍ وَيَوْمٍ - فَأَذِنَ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مُتْعَةِ النِّسَاءِ فَخَرَجْتُ أَنَا وَرَجُلٌ مِنْ قَوْمِي وَلِي عَلَيْهِ فَضْلٌ فِي الْجَمَالِ وَهُوَ قَرِيبٌ مِنَ الدَّمَامَةِ مَعَ كُلِّ وَاحِدٍ مِنَّا بُرْدٌ فَبُرْدِي خَلَقٌ وَأَمَّا بُرْدُ ابْنِ عَمِّي فَبُرْدٌ جَدِيدٌ غَضٌّ حَتَّى إِذَا كُنَّا بِأَسْفَلِ مَكَّةَ أَوْ بِأَعْلاَهَا فَتَلَقَّتْنَا فَتَاةٌ مِثْلُ الْبَكْرَةِ الْعَنَطْنَطَةِ فَقُلْنَا هَلْ لَكِ أَنْ يَسْتَمْتِعَ مِنْكِ أَحَدُنَا قَالَتْ وَمَاذَا تَبْذُلاَنِ فَنَشَرَ كُلُّ وَاحِدٍ مِنَّا بُرْدَهُ فَجَعَلَتْ تَنْظُرُ إِلَى الرَّجُلَيْنِ وَيَرَاهَا صَاحِبِي تَنْظُرُ إِلَى عِطْفِهَا فَقَالَ إِنَّ بُرْدَ هَذَا خَلَقٌ وَبُرْدِي جَدِيدٌ غَضٌّ. فَتَقُولُ بُرْدُ هَذَا لاَ بَأْسَ بِهِ. ثَلاَثَ مِرَارٍ أَوْ مَرَّتَيْنِ ثُمَّ اسْتَمْتَعْتُ مِنْهَا فَلَمْ أَخْرُجْ حَتَّى حَرَّمَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه مسلم في النكاح (20:1406) عن أبي كامل فضيل بن حُسين الجحدري، حدثنا بشر (ابن مفضل) حدثنا عمارة بن غزية، عن الربيع بن سبرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1406 no. 20).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Al-Rabiʿ ibn Sabrah narrated that his father fought with the Messenger of Allah ﷺ in the conquest of Mecca. He said: We stayed there for fifteen days — thirty, counting nights and days — and the Messenger of Allah ﷺ permitted us temporary marriage with women. So I and a man from my people went out. I was more handsome than him, while he was somewhat unattractive. Each of us had a cloak. My cloak was worn out, while my cousin’s cloak was new and fresh. When we were in the lower or upper part of Mecca, a girl met us, like a tall young camel in beauty. We said: Would one of us suit you for temporary marriage? She said: What will you give? Each of us spread out his cloak. She began looking at the two men, while my companion saw her looking to her side. So he said: This man’s cloak is worn out, but my cloak is new and fresh. Yet she would say: This man’s cloak is acceptable. She said that two or three times. Then I contracted temporary marriage with her. I had not yet left until the Messenger of Allah ﷺ forbade it."]},"buhuth":{"en":["His saying, “al-damamah,” means ugliness of appearance. “Khalaq” means worn and close to being shabby, that is, old. “Al-ʿanṭanṭah” means tall in stature."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":20,"lafz":true}],"full":1,"dr":1},{"num":6470,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الْمَلِكِ بْنِ الرَّبِيعِ بْنِ سَبْرَةَ الْجُهَنِيِّ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْمُتْعَةِ عَامَ الْفَتْحِ حِينَ دَخَلْنَا مَكَّةَ ثُمَّ لَمْ نَخْرُجْ مِنْهَا حَتَّى نَهَانَا عَنْهَا."],"takhrij":"صحيح: رواه مسلم في النكاح (22:1406) عن إسحاق بن إبراهيم، أخبرنا يحيى بن آدم، حدثنا إبراهيم بن سعيد، عن عبد الملك بن الربيع بن سبرة الجهني بإسناده فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1406 no. 22).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["ʿAbd al-Malik ibn al-Rabiʿ ibn Sabrah al-Juhani, from his father, from his grandfather, said: The Messenger of Allah ﷺ ordered us to contract temporary marriage in the year of the Conquest when we entered Mecca, then we did not leave it before he forbade us from it."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":22,"lafz":true}],"full":1},{"num":6471,"demo":false,"sanad":"","matn":["عَنْ سَبْرَةَ الجهني أَنَّهُ كَانَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا أَيُّهَا النَّاسُ، إِنِّي قَدْ كُنْتُ أَذِنْتُ لَكُمْ فِي الاِسْتِمْتَاعِ مِنَ النِّسَاءِ. وَإِنَّ اللَّهَ قَدْ حَرَّمَ ذَلِكَ إِلَى يَوْمِ الْقِيَامَةِ، فَمَنْ كَانَ عِنْدَهُ مِنْهُنَّ شيء فَلْيُخَلِّ سَبِيلَهُ، وَلاَ تَأْخُذُوا مِمَّا آتَيْتُمُوهُنَّ شَيْئًا.","وفي لفظ: رأيت رسول الله صلى الله عليه وسلم قائما بين الركن والباب، وهو يقول: فذكره."],"takhrij":"صحيح: رواه مسلم في النكاح (21:1406) عن محمد بن عبد الله بن نمير، حدثنا أبي، حدثنا عبد العزيز بن عمر، حدثني الربيع بن سبرة الجهني أن أباه حدثه، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1406 no. 21).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Sabrah al-Juhani said that he was with the Messenger of Allah ﷺ, and he said: “O people, I had previously permitted you temporary marriage with women, but Allah has now forbidden that until the Day of Resurrection. So whoever has any of them with him, let him release her, and do not take back anything from what you gave them.” And in another wording: I saw the Messenger of Allah ﷺ standing between the Corner and the Door saying this."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":21,"lafz":true}],"full":1,"dr":1},{"num":6472,"demo":false,"sanad":"","matn":["عن عُرْوَةَ بن الزُّبَيْرِ أَنَّ عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ، قَامَ بِمَكَّةَ فَقَالَ إِنَّ نَاسًا - أَعْمَى اللَّهُ قُلُوبَهُمْ كَمَا أَعْمَى أَبْصَارَهُمْ - يُفْتُونَ بِالْمُتْعَةِ - يُعَرِّضُ بِرَجُلٍ - فَنَادَاهُ فَقَالَ إِنَّكَ لَجِلْفٌ جَافٍ فَلَعَمْرِي لَقَدْ كَانَتِ الْمُتْعَةُ تُفْعَلُ عَلَى عَهْدِ إِمَامِ الْمُتَّقِينَ - يُرِيدُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - فَقَالَ لَهُ ابْنُ الزُّبَيْرِ فَجَرِّبْ بِنَفْسِكَ فَوَاللَّهِ لَئِنْ فَعَلْتَهَا لأَرْجُمَنَّكَ بِأَحْجَارِكَ.","قال ابن شهاب: فأخبرني خالد بن المهاجر بن سيف الله، أنه بينما هو جالس عند رجل. فاستفتاه في المتعة. فأمره بها. فقال له ابن أبي عمْرة الأنصاري: مهلاً! قال: ما هي؟ والله لقد فُعِلتْ في عهد إمام المتقين. قال ابن أبي عمرة: إنها كانت رخصة في أول الإسلام لمن اضطرّ إليها كالميتة والدم ولحم الخنزير، ثم أحكم الله الدين ونهى عنها."],"takhrij":"صحيح: رواه مسلم في النكاح (27:1406) عن حرملة بن يحيى، أخبرنا ابن وهب، أخبرني يونس، قال ابن شهاب: أخبرني عروة بن الزبير، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1406/27).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["ʿUrwah ibn al-Zubayr reported: ʿAbdullāh ibn al-Zubayr stood in Makkah and said: “There are people whose hearts Allah has blinded just as He has blinded their eyes, and they issue rulings permitting temporary marriage”—alluding to a certain man. That man called out to him: “You are a coarse and harsh man. By my life, temporary marriage was practiced during the lifetime of the leader of those who fear Allah,” meaning the Messenger of Allah ﷺ. Ibn al-Zubayr said to him: “Then try it yourself. By Allah, if you do it, I will stone you with your own stones.” Ibn Shihāb said: Khālid ibn al-Muhājir ibn Sayf Allah informed me that while he was sitting with a man, that man was asked for a ruling concerning temporary marriage and permitted it.","Ibn Abī ʿAmrah al-Anṣārī said to him: “Wait!” He said: “What is the matter? By Allah, it was practiced during the time of the leader of those who fear Allah.” Ibn Abī ʿAmrah said: “It was only a concession during the early period of Islam for someone compelled by necessity, like carrion, blood, and pork. Then Allah perfected the religion and prohibited it.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1406,"lafz":true,"n":3429},{"key":"muslim","label":"مسلم في النكاح","number":27}],"full":1},{"num":6473,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ لَمَّا وَلِيَ عُمَرُ بْنُ الْخَطَّابِ خَطَبَ النَّاسَ فَقَالَ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَذِنَ لَنَا فِي الْمُتْعَةِ ثَلاَثًا ثُمَّ حَرَّمَهَا وَاللَّهِ لاَ أَعْلَمُ أَحَدًا تَمَتَّعَ وَهُوَ مُحْصَنٌ إِلاَّ رَجَمْتُهُ بِالْحِجَارَةِ إِلاَّ أَنْ يَأْتِيَنِي بِأَرْبَعَةٍ يَشْهَدُونَ أَنَّ رَسُولَ اللَّهِ أَحَلَّهَا بَعْدَ إِذْ حَرَّمَهَا."],"takhrij":"حسن: رواه ابن ماجة (1963) عن محمد بن خلف العسقلاني، قال: حدثنا الفريابي، عن أبان بن أبي حازم، عن أبي بكر بن حفص، عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (1963).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿUmar said: When ʿUmar ibn al-Khattab became leader, he addressed the people and said: The Messenger of Allah ﷺ permitted temporary marriage three times, then he forbade it. By Allah, I do not know of anyone who engages in temporary marriage while married except that I would stone him, unless he brought me four witnesses testifying that the Messenger of Allah ﷺ made it lawful after having forbidden it."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":1963,"lafz":true}],"full":1,"dr":1},{"num":6474,"demo":false,"sanad":"","matn":["عن سالم بن عَبْدِ اللَّهِ أَنَّ رَجُلًا سَأَلَ عَبْدَ اللَّهِ بْنَ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا عَنِ الْمُتْعَةِ فَقَالَ: حَرَامٌ، قَالَ: فَإِنَّ فُلَانًا يَقُولُ فِيهَا، فَقَالَ: وَاللهِ لَقَدْ عُلِمَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَرَّمَهَا يَوْمَ خَيْبَرَ وَمَا كُنَّا مُسَافِحِينَ."],"takhrij":"صحيح: رواه البيهقي (7/202) من طرق عن أبي العباس محمد بن يعقوب، أنبأ محمد بن عبد الله بن عبد الحكم، أنبأ ابن وهب، أخبرني عمر بن محمد بن زيد بن عبد الله بن عمر بن الخطاب، عن ابن شهاب قال: أخبرني سالم بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bayhaqi (7/202).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Salim ibn ʿAbd Allah narrated that a man asked ʿAbd Allah ibn ʿUmar about temporary marriage, and he said: It is forbidden. The man said: But so-and-so gives a ruling about it. He said: By Allah, it is certainly known that the Messenger of Allah ﷺ forbade it on the day of Khaybar, and we were not fornicators."]}},"tuhfa":{},"refs":[{"key":"kubrabayhaqi","label":"البيهقي","number":202,"lafz":true},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":14148,"n":14284}],"full":1,"dr":1},{"num":6475,"demo":false,"sanad":"","matn":["عَنْ سَالِمِ بْنِ عَبْدِ اللَّهِ، قَالَ: أَتَى عَبْدُ اللَّهِ بْنُ عُمَرَ، فَقِيلَ لَهُ: إِنَّ ابْنَ عَبَّاسٍ يَأْمُرُ بِنِكَاحِ الْمُتْعَةِ، فَقَالَ ابْنُ عُمَرَ: سُبْحَانَ اللَّهِ، مَا أَظُنُّ ابْنَ عَبَّاسٍ يَفْعَلُ هَذَا، قَالُوا: بَلَى، إِنَّهُ يَأْمُرُ بِهِ، فَقَالَ: وَهَلْ كَانَ ابْنُ عَبَّاسٍ إِلَّا غُلَامًا صَغِيرًا إِذْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ قَالَ ابْنُ عُمَرَ: نَهَانَا عَنْهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَمَا كُنَّا مُسَافِحِينَ."],"takhrij":"حسن: رواه الطبراني في الأوسط (9291) عن هاشم بن مرثد قال: حدثنا المعافي بن سليمان، قال حدثنا موسى بن أعين، عن إسحاق بن راشد، عن الزهري، عن سالم بن عبدالله فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Awsat (9291).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Salim ibn ʿAbd Allah said: ʿAbd Allah ibn ʿUmar was approached and told: Ibn ʿAbbas orders temporary marriage. Ibn ʿUmar said: Glory be to Allah. I do not think Ibn ʿAbbas would do this. They said: Yes, he does order it. So Ibn ʿUmar said: Was Ibn ʿAbbas anything but a young boy when the Messenger of Allah ﷺ was alive? Then Ibn ʿUmar said: The Messenger of Allah ﷺ forbade it, and we were not fornicators."]}},"tuhfa":{},"refs":[{"key":"sh28171","label":"الطبراني في الأوسط","number":9291,"lafz":true,"n":9280},{"key":"sh28171","label":"المعجم الأوسط للطبراني","number":9295,"n":9280}],"full":1,"dr":1},{"num":6476,"demo":false,"sanad":"","matn":["أَخْبَرَنِي أَبُو الزُّبَيْرِ، قَالَ سَمِعْتُ جَابِرَ بْنَ عَبْدِ اللَّهِ، يَقُولُ كُنَّا نَسْتَمْتِعُ بِالْقُبْضَةِ مِنَ التَّمْرِ وَالدَّقِيقِ الأَيَّامَ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبِي بَكْرٍ حَتَّى نَهَى عَنْهُ عُمَرُ فِي شَأْنِ عَمْرِو بْنِ حُرَيْثٍ."],"takhrij":"صحيح: رواه مسلم في النكاح (16:1405) عن محمد بن رافع، حدثنا عبد الرزاق، أخبرنا ابن جريج، قال: أخبرني أبو الزبير فذكره.","grade":"صحيح","chapter_ar":"باب من قال: إن عمر بن الخطاب هو الذي نهى عن المتعة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1405 no. 16).","chapter_en":"Those Who Said That ʿUmar ibn al-Khattab Was the One Who Forbade Temporary Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":12,"content":{"translation":{"en":["Abu al-Zubayr said: I heard Jabir ibn ʿAbd Allah say: We used to contract temporary marriage for a handful of dates and flour for a number of days during the time of the Messenger of Allah ﷺ and Abu Bakr, until ʿUmar forbade it in the case of ʿAmr ibn Hurayth."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":16,"lafz":true}],"full":1,"dr":1},{"num":6477,"demo":false,"sanad":"","matn":["عَنْ عَاصِمٍ، عَنْ أَبِي نَضْرَةَ، قَالَ كُنْتُ عِنْدَ جَابِرِ بْنِ عَبْدِ اللَّهِ فَأَتَاهُ آتٍ فَقَالَ ابْنُ عَبَّاسٍ وَابْنُ الزُّبَيْرِ اخْتَلَفَا فِي الْمُتْعَتَيْنِ فَقَالَ جَابِرٌ فَعَلْنَاهُمَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ نَهَانَا عَنْهُمَا عُمَرُ فَلَمْ نَعُدْ لَهُمَا."],"takhrij":"صحيح: رواه مسلم في النكاح (17:1405) عن حامد بن عمر البكراوي، حدثنا عبد الواحد (يعني ابن زياد) عن عاصم، عن أبي نضرة، فذكره.","grade":"صحيح","chapter_ar":"باب من قال: إن عمر بن الخطاب هو الذي نهى عن المتعة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1405 no. 17).","chapter_en":"Those Who Said That ʿUmar ibn al-Khattab Was the One Who Forbade Temporary Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":12,"content":{"translation":{"en":["ʿAsim ibn Abi Nadrah said: I was with Jabir ibn ʿAbd Allah when someone came to him and said: Ibn ʿAbbas and Ibn al-Zubayr have differed concerning the two temporary matters. Jabir said: We did both of them with the Messenger of Allah ﷺ, then ʿUmar forbade us from them, and we did not return to them."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":17,"lafz":true}],"full":1,"dr":1},{"num":6478,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الشِّغَارِ. وَالشِّغَارُ أَنْ يُزوّج الرَّجُلُ ابْنَتَهُ عَلَى أَنْ يُزوّجه الآخَرُ ابْنَتَهُ. لَيْسَ بَيْنَهُمَا صَدَاقٌ."],"takhrij":"متفق عليه: رواه مالك في النكاح (24) عن نافع، عن عبد الله بن عمر، فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن نكاح الشغار","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (24), al-Bukhari (5112), and Muslim (1415 no. 57).","chapter_en":"The Prohibition of Shighar Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["ʿAbd Allah ibn ʿUmar narrated that the Messenger of Allah ﷺ forbade shighar. Shighar is when a man marries off his daughter on condition that the other man marries him his daughter, with no dowry between them."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":24,"lafz":true},{"key":"bukhari","label":"البخاري","number":5112},{"key":"muslim","label":"مسلم","number":57}],"full":1,"dr":1},{"num":6479,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الشِّغَارِ.","زاد ابن نُمير: والشغار أن يقول الرجل للرجل: زوِّجني ابنتك، وأزوّجك ابنتي، أو زوّجني أختَك، وأزوّجك أختي."],"takhrij":"صحيح: رواه مسلم في النكاح (1416) عن أبي بكر بن أبي شيبة، حدثنا ابن نمير وأبو أسامة، عن عبيدالله، عن أبي الزناد، عن الأعرج، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن نكاح الشغار","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1416).","chapter_en":"The Prohibition of Shighar Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ forbade shighar. Ibn Numayr added: Shighar is that a man says to another man: Marry your daughter to me and I will marry my daughter to you; or marry your sister to me and I will marry my sister to you."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1416,"lafz":true}],"full":1,"dr":1},{"num":6480,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُحَاقَلَةِ."],"takhrij":"صحيح: رواه مسلم في النكاح (1417) من طريق حجاج بن محمد، وعبد الرزاق – فرقهما – كلاهما عن ابن جريج، أخبرني أبو الزبير، أنه سمع جابر بن عبد الله يقول: فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن نكاح الشغار","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1417).","chapter_en":"The Prohibition of Shighar Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["Jabir ibn ʿAbd Allah said: The Messenger of Allah ﷺ forbade shighar."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1417,"lafz":true}],"full":1},{"num":6481,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ شِغَارَ فِي الإِسْلاَمِ."],"takhrij":"صحيح: رواه ابن ماجة (1885) عن الحُسين بن مهدي، قال: أنبانا عبد الرزاق، عن معمر، عن ثابت، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن نكاح الشغار","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (1885) and Ibn Hibban in his Sahih (4154).","chapter_en":"The Prohibition of Shighar Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ said: “There is no shighar in Islam.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":1885,"lafz":true},{"key":"ibnhibban","label":"ابن حبان في صحيحه","number":4154}],"full":1,"dr":1},{"num":6482,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا شِغَارَ فِي الْإِسْلَامِ."],"takhrij":"صحيح: رواه الإمام أحمد (19962) عن إبراهيم بن خالد، حدثنا رباح، عن معمر، عن ابن سيرين، عن عمران بن حصين فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن نكاح الشغار","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (19962).","chapter_en":"The Prohibition of Shighar Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["ʿImran ibn Husayn narrated that the Messenger of Allah ﷺ said: “There is no shighar in Islam.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":19962,"lafz":true}],"full":1,"dr":1},{"num":6483,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ: قَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا شِغَارَ فِي الْإِسْلَامِ."],"takhrij":"حسن: رواه أحمد (7027) عن يعقوب وسعد قالا: حدثنا أبي، عن ابن إسحاق – يعني محمداً – حدثني عبد الرحمن بن الحارث، عن عمرو بن شعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب النهي عن نكاح الشغار","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (7027).","chapter_en":"The Prohibition of Shighar Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb, from his father, from his grandfather, said: The Messenger of Allah ﷺ ruled: “There is no shighar in Islam.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":7027,"n":7027,"lafz":true}],"full":1,"dr":1},{"num":6484,"demo":false,"sanad":"","matn":["عن العباس بن عبد الله بن عباس أنه أنكح عبدالرحمن بن الحكم ابنته، وأنكحه عبدالرحمن ابنته، وقد كانا جعلا صداقاً. فكتب معاوية بن أبي سفيان -وهو خليفة– إلى مروان يأمره بالتفريق بينهما. وقال في كتابه: هذا الشغار الذي نهى عنه رسول الله صلى الله عليه وسلم ."],"takhrij":"حسن: رواه أبو داود (2075) ومن طريقه البيهقي (7/200) عن محمد بن يحيى بن فارس، حدثنا يعقوب بن إبراهيم، حدثنا أبي، عن ابن إسحاق، حدثني عبد الرحمن بن هرمز الأعرج، أن العباس بن عبد الله بن عباس أنكح عبد الرحمن بن الحكم ابنته فذكره بقية القصة.","grade":"حسن","chapter_ar":"باب النهي عن نكاح الشغار","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (2075).","chapter_en":"The Prohibition of Shighar Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["Al-ʿAbbās ibn ʿAbdullāh ibn ʿAbbās reported: He married his daughter to ʿAbd al-Raḥmān ibn al-Ḥakam, and ʿAbd al-Raḥmān married his daughter to him, and they had stipulated a dowry. Muʿāwiyah ibn Abī Sufyān, who was the caliph at the time, wrote to Marwān ordering him to separate the two marriages. He wrote: “This is the shighār that the Messenger of Allah ﷺ prohibited.”"]},"buhuth":{"en":["The statement, “they had stipulated a dowry,” means that they included a dowry together with the shighār arrangement. However, if each man marries his daughter to the other while each marriage has its own proper dowry, then it no longer falls under the prohibited form of shighār."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2075,"lafz":true}],"full":1,"dr":1},{"num":6485,"demo":false,"sanad":"","matn":["عَنْ نُبَيْهِ بْنِ وَهْبٍ، أَخِي بَنِي عَبْدِ الدَّارِ أَنَّ عُمَرَ بْنَ عُبَيْدِ اللَّهِ، أَرْسَلَ إِلَى أَبَانَ بْنِ عُثْمَانَ - وَأَبَانُ يَوْمَئِذٍ أَمِيرُ الْحَاجِّ وَهُمَا مُحْرِمَانِ - إِنِّي قَدْ أَرَدْتُ أَنْ أُنْكِحَ طَلْحَةَ بْنَ عُمَرَ بِنْتَ شَيْبَةَ بْنِ جُبَيْرٍ وَأَرَدْتُ أَنْ تَحْضُرَ. فَأَنْكَرَ ذَلِكَ عَلَيْهِ أَبَانُ وَقَالَ سَمِعْتُ عُثْمَانَ بْنَ عَفَّانَ يَقُولُ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ يَنْكِحِ الْمُحْرِمُ وَلاَ يُنْكِحْ وَلاَ يَخْطُبْ."],"takhrij":"صحيح: رواه مالك في الحج (70) عن نافع، عن نبيه بن وهب، به، فذكره. وروا مسلم في النكاح (1409) من طريق مالك، به.","grade":"صحيح","chapter_ar":"باب النهي عن نكاح المحرم وخطبته","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (70) and Muslim (1409).","chapter_en":"The Prohibition of Marriage and Betrothal While in Ihram","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["Nubayh ibn Wahb — the ally of Banu ʿAbd al-Dar — said: ʿUmar ibn ʿUbayd Allah sent a message to Aban ibn ʿUthman — and Aban was then the leader of the pilgrims — while both of them were in ihram: I wish to marry Talhah ibn ʿUmar to the daughter of Shaybah ibn Jubayr, and I want you to attend. Aban objected to that and said: I heard ʿUthman ibn ʿAffan say: The Messenger of Allah ﷺ said: “The one in ihram must neither marry, nor have someone married on his behalf, nor propose.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":70,"lafz":true},{"key":"muslim","label":"مسلم","number":1409}],"full":1,"rep":[4847]},{"num":6486,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يَنْكِحِ الْمُحْرِمُ، وَلَا يَخْطُبْ وَلَا يُخْطَبْ عَلَيْهِ، وَلَا يَبِعْ أَحَدُكُمْ عَلَى بَيْعِ أَخِيهِ، وَلَا يَخْطُبْ عَلَى خِطْبَةِ أَخِيهِ حَتَّى يَأْذَنَ لَهُ."],"takhrij":"صحيح: رواه الطبراني في الأوسط (514) عن أحمد بن القاسم، ثنا محمد بن يوسف الغَضِيضي، قال: حدثنا عبد الله بن وهب، عن عمر بن محمد، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن نكاح المحرم وخطبته","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tabarani in al-Awsat (514).","chapter_en":"The Prohibition of Marriage and Betrothal While in Ihram","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “The one in ihram must neither marry nor propose, nor should a proposal be made on his behalf. And none of you should sell over the sale of his brother, nor propose over the proposal of his brother until he gives him permission.”"]}},"tuhfa":{},"refs":[{"key":"sh28171","label":"الطبراني في الأوسط","number":514,"lafz":true,"n":504},{"key":"sh28171","label":"المعجم الأوسط للطبراني","number":510,"n":504}],"full":1,"dr":1},{"num":6487,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ جَاءَتِ امْرَأَةُ رِفَاعَةَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ كُنْتُ عِنْدَ رِفَاعَةَ فَطَلَّقَنِي فَبَتَّ طَلاَقِي فَتَزَوَّجْتُ عَبْدَ الرَّحْمَنِ بْنَ الزَّبِيرِ وَإِنَّ مَا مَعَهُ مِثْلُ هُدْبَةِ الثَّوْبِ فَتَبَسَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ أَتُرِيدِينَ أَنْ تَرْجِعِي إِلَى رِفَاعَةَ لاَ حَتَّى تَذُوقِي عُسَيْلَتَهُ وَيَذُوقَ عُسَيْلَتَكِ.","قالت: وأبو بكر عنده، وخالد بالباب ينتظر أن يؤذن له. فنادى: يا أبا بكر، ألا تسمعُ هذه ما تجهر به عند رسول الله صلى الله عليه وسلم."],"takhrij":"متفق عليه: رواه البخاري في الطلاق (5260)، ومسلم في النكاح (111:1433) كلاهما من طريق الزهري، قال أخبرني عروة بن الزبير، أن عائشة أخبرته، فذكرته.","grade":"متفق عليه","chapter_ar":"باب تحريم نكاح المطلقة البتة حتى تتزوج زوجا غيره ويطأها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5260) and Muslim (1433 no. 111). The wording is that of Muslim.","chapter_en":"The Prohibition of Remarrying a Woman Divorced Irrevocably Until She Marries Another Husband and He Has Intercourse with Her","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":15,"content":{"translation":{"en":["ʿA’ishah said: The wife of Rifaʿah came to the Prophet ﷺ and said: I was married to Rifaʿah, and he divorced me with a final irrevocable divorce. Then I married ʿAbd al-Rahman ibn al-Zubayr, but what he has is like the fringe of a garment. The Messenger of Allah ﷺ smiled and said: “Do you want to return to Rifaʿah? No, not until you taste his sweetness and he tastes your sweetness.” She said: Abu Bakr was with him, and Khalid was at the door waiting to be given permission. So he called out: O Abu Bakr, do you not hear what this woman says openly in front of the Messenger of Allah ﷺ?"]},"buhuth":{"en":["ʿAbd al-Rahman ibn al-Zubayr ibn Bata al-Qurazi had a father who was killed during the campaign of Banu Qurayzah. ʿAbd al-Rahman was a young Companion, and I have not found mention of him outside this hadith.","As for Rifaʿah, he was Rifaʿah ibn Samu’al al-Qurazi."]},"intro":{"ar":["قال الله تعالى: ( فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنكِحَ زَوْجًا غَيْرَهُ ) [البقرة: ٢٣٠]","قوله: ( حَتَّى تَنكِحَ زَوْجًا غَيْرَهُ ) مطلق، ويقيده حديث عائشة بأن المراد به الوطء على رأي الجمهور، ومن خالفه لا يعتد به."],"en":["Allah the Exalted said: “Then if he divorces her, she is not lawful for him afterward until she marries another husband.” [Surat al-Baqarah 2:230]","His statement, “until she marries another husband,” is general, and the hadith of ʿA’ishah qualifies it by showing that what is meant, according to the majority, is actual intercourse. The view of those who disagree is not given weight."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5260,"lafz":true},{"key":"muslim","label":"مسلم","number":111}],"full":1,"dr":1},{"num":6488,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ طَلَّقَ رَجُلٌ امْرَأَتَهُ ثَلاَثًا فَتَزَوَّجَهَا رَجُلٌ ثُمَّ طَلَّقَهَا قَبْلَ أَنْ يَدْخُلَ بِهَا فَأَرَادَ زَوْجُهَا الأَوَّلُ أَنْ يَتَزَوَّجَهَا فَسُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ فَقَالَ لاَ حَتَّى يَذُوقَ الآخِرُ مِنْ عُسَيْلَتِهَا مَا ذَاقَ الأَوَّلُ."],"takhrij":"متفق عليه: رواه البخاري في الطلاق (5261)، ومسلم في النكاح (115:1433) كلاهما من طريق عبيد الله بن عمر، قال: حدثني القاسم بن محمد، عن عائشة، فذكرته، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب تحريم نكاح المطلقة البتة حتى تتزوج زوجا غيره ويطأها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5261) and Muslim (1433 no. 115). The wording is that of Muslim.","chapter_en":"The Prohibition of Remarrying a Woman Divorced Irrevocably Until She Marries Another Husband and He Has Intercourse with Her","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":15,"content":{"translation":{"en":["ʿA’ishah said: A man divorced his wife three times, then another man married her and divorced her before consummating the marriage. Her first husband wanted to marry her again, so the Messenger of Allah ﷺ was asked about that, and he said: “No, not until the latter tastes of her sweetness what the former tasted.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5261,"lafz":true},{"key":"muslim","label":"مسلم","number":115}],"full":1,"dr":1},{"num":6489,"demo":false,"sanad":"","matn":["عَنْ عِكْرِمَةَ، أَنَّ رِفَاعَةَ، طَلَّقَ امْرَأَتَهُ، فَتَزَوَّجَهَا عَبْدُ الرَّحْمَنِ بْنُ الزَّبِيرِ الْقُرَظِيُّ، قَالَتْ عَائِشَةُ وَعَلَيْهَا خِمَارٌ أَخْضَرُ. فَشَكَتْ إِلَيْهَا، وَأَرَتْهَا خُضْرَةً بِجِلْدِهَا، فَلَمَّا جَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالنِّسَاءُ يَنْصُرُ بَعْضُهُنَّ بَعْضًا قَالَتْ عَائِشَةُ مَا رَأَيْتُ مِثْلَ مَا يَلْقَى الْمُؤْمِنَاتُ، لَجِلْدُهَا أَشَدُّ خُضْرَةً مِنْ ثَوْبِهَا. قَالَ وَسَمِعَ أَنَّهَا قَدْ أَتَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَاءَ وَمَعَهُ ابْنَانِ لَهُ مِنْ غَيْرِهَا. قَالَتْ وَاللَّهِ مَا لِي إِلَيْهِ مِنْ ذَنْبٍ، إِلاَّ أَنَّ مَا مَعَهُ لَيْسَ بِأَغْنَى عَنِّي مِنْ هَذِهِ. وَأَخَذَتْ هُدْبَةً مِنْ ثَوْبِهَا، فَقَالَ كَذَبَتْ وَاللَّهِ يَا رَسُولَ اللَّهِ، إِنِّي لأَنْفُضُهَا نَفْضَ الأَدِيمِ، وَلَكِنَّهَا نَاشِزٌ تُرِيدُ رِفَاعَةَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَإِنْ كَانَ ذَلِكَ لَمْ تَحِلِّي لَهُ ـ أَوْ لَمْ تَصْلُحِي لَهُ ـ حَتَّى يَذُوقَ مِنْ عُسَيْلَتِكِ. قَالَ وَأَبْصَرَ مَعَهُ ابْنَيْنِ فَقَالَ بَنُوكَ هَؤُلاَءِ. قَالَ نَعَمْ. قَالَ هَذَا الَّذِي تَزْعُمِينَ مَا تَزْعُمِينَ، فَوَاللَّهِ لَهُمْ أَشْبَهُ بِهِ مِنَ الْغُرَابِ بِالْغُرَابِ."],"takhrij":"صحيح: رواه البخاري في اللباس (5825) عن محمد بن بشار، حدثنا عبد الوهاب، أخبرنا أيوب، عن عكرمة، به.","grade":"صحيح","chapter_ar":"باب تحريم نكاح المطلقة البتة حتى تتزوج زوجا غيره ويطأها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5825).","chapter_en":"The Prohibition of Remarrying a Woman Divorced Irrevocably Until She Marries Another Husband and He Has Intercourse with Her","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":15,"content":{"translation":{"en":["ʿIkrimah narrated that Rifaʿah divorced his wife, and then ʿAbd al-Rahman ibn al-Zubayr al-Qurazi married her. ʿA’ishah said: She was wearing a green veil, and she complained to her and showed her the green bruising on her skin. When the Messenger of Allah ﷺ came, and women were supporting one another, ʿA’ishah said: I have not seen anything like what believing women suffer; indeed, the skin of this woman was greener than her garment. He said: He heard that she had come to the Messenger of Allah ﷺ, so he came, and he had with him two sons from another wife. She said: By Allah, I have no complaint against him except that what he has is no more useful to me than this, and she took a fringe from her garment. He said: You have lied, by Allah, O Messenger of Allah. Indeed I satisfy her fully like the shaking of a leather skin, but she is defiant and wants Rifaʿah. So the Messenger of Allah ﷺ said: “If that is so, then you are not lawful for him,” or, “you are not suitable for him, until he tastes your sweetness.” Then he saw that the man had two sons with him, so he said: “Are these your sons?” He said: Yes. He said: “This is the one about whom you are claiming what you are claiming? By Allah, they resemble him more than one crow resembles another crow.” Her statement, “and she showed her the green bruising on her skin,” means that this had been caused by ʿAbd al-Rahman beating her, and in it is evidence that a husband may strike his wife when she is defiantly disobedient. And his statement, “By Allah, they resemble him more than one crow resembles another crow,” means that the two sons resembled ʿAbd al-Rahman more than one crow resembles another. So the Prophet ﷺ established the ruling here by evidence, since he used their resemblance to him as proof that she was lying in her claim. And in it is evidence for judging by physical resemblance, and this is the view of the majority of the scholars. And in it is also evidence that marrying a virgin is recommended, because she assumes all men are alike, unlike a previously married woman."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5825,"lafz":true}],"full":1,"dr":1,"rep":[6579]},{"num":6490,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ: كَانَ الْمُشْرِكُونَ عَلَى مَنْزِلَتَيْنِ مِنَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالْمُؤْمِنِينَ، كَانُوا مُشْرِكِي أَهْلِ حَرْبٍ يُقَاتِلُهُمْ وَيُقَاتِلُونَهُ، وَمُشْرِكِي أَهْلِ عَهْدٍ لاَ يُقَاتِلُهُمْ وَلاَ يُقَاتِلُونَهُ. وَكَانَ إِذَا هَاجَرَتِ امْرَأَةٌ مِنْ أَهْلِ الْحَرْبِ لَمْ تُخْطَبْ حَتَّى تَحِيضَ وَتَطْهُرَ، فَإِذَا طَهُرَتْ حَلَّ لَهَا النِّكَاحُ، فَإِنْ هَاجَرَ زَوْجُهَا قَبْلَ أَنْ تَنْكِحَ رُدّت إِلَيْهِ، وَإِنْ هَاجَرَ عَبْدٌ مِنْهُ أَوْ أَمَةٌ فَهُمَا حُرّان، وَلَهُمَا مَا لِلْمُهَاجِرِينَ، وَإِنْ هَاجَرَ عَبْدٌ أَوْ أَمَةٌ لِلْمُشْرِكِينَ أَهْلِ الْعَهْدِ لَمْ يُرَدُّوا، ورُدّت أَثْمَانُهُمْ."],"takhrij":"صحيح: رواه البخاري في الطلاق (5286) عن إبراهيم بن موسى، أخبرنا هشام، عن ابن جريج. وقال عطاء عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب جواز نكاح المشركة إذا أسلمت بعد انقضاء العدة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5286).","chapter_en":"The Permissibility of Marrying a Polytheist Woman If She Accepts Islam After the Waiting Period Ends","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":16,"content":{"translation":{"en":["Ibn ʿAbbas said: The polytheists were of two categories in relation to the Prophet ﷺ and the believers. They were either polytheists from the people of war, whom he fought and who fought him, or polytheists from the people of treaty, whom he did not fight and who did not fight him. If a woman emigrated from the people of war, she would not be proposed to until she menstruated and then became pure. Once she became pure, marriage to her became lawful. If her husband emigrated before she married, she was returned to him. If a male slave or female slave from them emigrated, then both became free and had the same rights as the emigrants. But if a male slave or female slave belonging to the treaty polytheists emigrated, they were not returned, though their price was returned."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5286,"lafz":true}],"full":1,"dr":1},{"num":6491,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ أَتَى بِامْرَأَةٍ مُجِحٍّ عَلَى بَابِ فُسْطَاطٍ فَقَالَ لَعَلَّهُ يُرِيدُ أَنْ يُلِمَّ بِهَا. فَقَالُوا نَعَمْ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَقَدْ هَمَمْتُ أَنْ أَلْعَنَهُ لَعْنًا يَدْخُلُ مَعَهُ قَبْرَهُ كَيْفَ يُوَرِّثُهُ وَهُوَ لاَ يَحِلُّ لَهُ كَيْفَ يَسْتَخْدِمُهُ وَهُوَ لاَ يَحِلُّ لَهُ."],"takhrij":"صحيح: رواه مسلم في النكاح (1441) عن محمد بن المثنى، حدثنا محمد ابن جعفر، حدثنا شعبة، عن يزيد بن خُمير، قال: سمعت عبد الرحمن بن جُبير يحدّث عن أبيه، عن أبي الدراداء، فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن وطء الحامل من السبايا والجارية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1441).","chapter_en":"The Prohibition of Having Intercourse with a Pregnant Captive or Slave Woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":18,"content":{"translation":{"en":["Abu al-Darda’ narrated that the Prophet ﷺ came upon a woman who was heavily pregnant at the door of a tent, and he said: “Perhaps he intends to have intercourse with her?” They said: Yes. So the Messenger of Allah ﷺ said: “I nearly cursed him with a curse that would enter with him into his grave. How can he make him inherit from him when he is not lawful for him? How can he enslave him when he is not lawful for him?”"]},"buhuth":{"en":["His statement, “mujih,” means a woman whose pregnancy is advanced. In this is clarification that intercourse with pregnant female captives is not permissible until they give birth."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1441,"lafz":true}],"full":1,"dr":1},{"num":6492,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، الْخُدْرِيِّ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ حُنَيْنٍ بَعَثَ جَيْشًا إِلَى أَوْطَاسٍ فَلَقُوا عَدُوًّا فَقَاتَلُوهُمْ فَظَهَرُوا عَلَيْهِمْ وَأَصَابُوا لَهُمْ سَبَايَا فَكَأَنَّ نَاسًا مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَحَرَّجُوا مِنْ غِشْيَانِهِنَّ مِنْ أَجْلِ أَزْوَاجِهِنَّ مِنَ الْمُشْرِكِينَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ فِي ذَلِكَ ﴿وَالْمُحْصَنَاتُ مِنَ النِّسَاءِ إِلاَّ مَا مَلَكَتْ أَيْمَانُكُمْ﴾ [سورة النساء: 24]} أَىْ فَهُنَّ لَكُمْ حَلاَلٌ إِذَا انْقَضَتْ عِدَّتُهُنَّ."],"takhrij":"صحيح: رواه مسلم في الرضاع (1456) عن عبيد الله بن عمر بن ميسرة القواريري، حدثنا يزيد بن زُريع، حدثنا سعيد بن أبي عروبة، عن قتادة، عن صالح أبي الخليل، عن أبي علقمة الهاشمي، عن أبي سعيد الخدري، فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن وطء الحامل من السبايا والجارية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1456).","chapter_en":"The Prohibition of Having Intercourse with a Pregnant Captive or Slave Woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":18,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that on the Day of Hunayn the Messenger of Allah ﷺ sent an army to Awtas. They met the enemy, fought them, prevailed over them, and took female captives from them. It was as though some of the Companions of the Messenger of Allah ﷺ felt uneasy about having intercourse with them because of their polytheist husbands. Then Allah, Mighty and Majestic, revealed concerning that: “And married women are forbidden to you except those whom your right hands possess” [al-Nisa’ 4:24], meaning that they become lawful for you once their waiting period has ended."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1456,"lafz":true}],"full":1},{"num":6493,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعِ الْمَغَانِمِ حَتَّى تُقْسَمَ وَعَنِ الْحَبَالَى أَنْ يُوطَأْنَ حَتَّى يَضَعْنَ مَا فِي بُطُونِهِنَّ وَعَنْ لَحْمِ كُلِّ ذِي نَابٍ مِنَ السِّبَاعِ."],"takhrij":"حسن: رواه النسائي (4645) والدراقطني (3/68-69) والحاكم (2/137) كلهم من حديث أحمد بن حفص بن عبد الله، حدثني أبي، حدثني إبراهيم بن طهمان، عن يحيى بن سعيد أنصاري، عن عمرو بن شعيب، عن عبد الله بن أبي نَجيح، عن مجاهد، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب النهي عن وطء الحامل من السبايا والجارية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4645), al-Daraqutni (3/68–69), and al-Hakim (2/137).","chapter_en":"The Prohibition of Having Intercourse with a Pregnant Captive or Slave Woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":18,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ forbade the sale of war booty before it is divided, and he forbade pregnant women from being had intercourse with until they deliver what is in their wombs, and he forbade the meat of every beast with fangs."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4645,"lafz":true,"n":4645},{"key":"sh9771","label":"الدراقطني","number":69},{"key":"hakim","label":"المستدرك على الصحيحين","number":2611,"n":2597}],"full":1,"dr":1,"rep":[5902]},{"num":6494,"demo":false,"sanad":"","matn":["عن رويفع بن ثابت الأنصاري عن النبي صلى الله عليه وسلم قال: لا يحل لامرئ يؤمن بالله واليوم الآخر أن يقع على امرأة من السبي حتى يستبرئها."],"takhrij":"حسن: رواه أبو داود (2708) والترمذي (1131) وأحمد (16992) وابن حبان (4850) والبيهقي (7/449) وسعيد بن منصور في سننه (2722) كلهم من طرق عن رويفع فذكره في سياق أطول وهو مخرج في كتاب البيوع.","grade":"حسن","chapter_ar":"باب النهي عن وطء الحامل من السبايا والجارية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2708), al-Tirmidhi (1131), who graded it hasan, Ahmad (16992), and Ibn Hibban (4850).","chapter_en":"The Prohibition of Having Intercourse with a Pregnant Captive or Slave Woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":18,"content":{"translation":{"en":["Ruwayfiʿ ibn Thabit al-Ansari narrated from the Prophet ﷺ that he said: “It is not lawful for a man who believes in Allah and the Last Day to have intercourse with a woman from the captives until he establishes that her womb is clear.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2708,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1131},{"key":"ibnhibban","label":"ابن حبان","number":4850},{"key":"ahmad","label":"مسند الإمام أحمد","number":16992,"n":16992},{"key":"sh13122","label":"سعيد بن منصور في سننه","number":2722}],"full":1,"dr":1},{"num":6495,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنَّ مَرْثَدَ بْنَ أَبِي مَرْثَدٍ الْغَنَوِيَّ، - وَكَانَ رَجُلاً شَدِيدًا - وَكَانَ يَحْمِلُ الأُسَارَى مِنْ مَكَّةَ إِلَى الْمَدِينَةِ. قَالَ فَدَعَوْتُ رَجُلاً لأَحْمِلَهُ وَكَانَ بِمَكَّةَ بَغِيٌّ يُقَالُ لَهَا عَنَاقُ وَكَانَتْ صَدِيقَتَهُ خَرَجَتْ فَرَأَتْ سَوَادِي فِي ظِلِّ الْحَائِطِ فَقَالَتْ مَنْ هَذَا مَرْثَدٌ مَرْحَبًا وَأَهْلاً يَا مَرْثَدُ انْطَلِقِ اللَّيْلَةَ فَبِتْ عِنْدَنَا فِي الرَّحْلِ. قُلْتُ يَا عَنَاقُ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَرَّمَ الزِّنَا. قَالَتْ يَا أَهْلَ الْخِيَامِ هَذَا الدُّلْدُلُ هَذَا الَّذِي يَحْمِلُ أُسَرَاءَكُمْ مِنْ مَكَّةَ إِلَى الْمَدِينَةِ. فَسَلَكْتُ الْخَنْدَمَةَ فَطَلَبَنِي ثَمَانِيَةٌ فَجَاءُوا حَتَّى قَامُوا عَلَى رَأْسِي فَبَالُوا فَطَارَ بَوْلُهُمْ عَلَىَّ وَأَعْمَاهُمُ اللَّهُ عَنِّي فَجِئْتُ إِلَى صَاحِبِي فَحَمَلْتُهُ فَلَمَّا انْتَهَيْتُ بِهِ إِلَى الأَرَاكِ فَكَكْتُ عَنْهُ كَبْلَهُ فَجِئْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ يَا رَسُولَ اللَّهِ أَنْكِحُ عَنَاقَ فَسَكَتَ عَنِّي فَنَزَلَتِ ﴿الزَّانِيَةُ لاَ يَنْكِحُهَا إِلاَّ زَانٍ أَوْ مُشْرِكٌ﴾ [سورة النور: 3] } فَدَعَانِي فَقَرَأَهَا عَلَىَّ وَقَالَ لاَ تَنْكِحْهَا."],"takhrij":"حسن: رواه أبو داود (2051) مختصرا ، والنسائي (3228) والترمذي (3176) والطحاوي في مشكله (4552) والبيهقي (7/153) كلهم من حديث عبيد الله بن الأخنس، عن عمرو بن شعيب بإسناده فذكره.","grade":"حسن","chapter_ar":"باب النهي عن نكاح الزانية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (2051), al-Nasāʾī (3228), al-Tirmidhī (3176), who graded it Hasan, and al-Ṭaḥāwī in Mushkil al-Āthār (4552).","chapter_en":"The Prohibition of Marrying a Fornicating Woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":19,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb reported from his father, from his grandfather: Marthad ibn Abī Marthad al-Ghanawī was a strong man who used to carry Muslim captives from Makkah to Madinah. He said: I arranged to carry a man out, and in Makkah there was a prostitute called ʿAnāq who had formerly been my companion. She came out and saw my silhouette in the shadow of the wall and said: “Who is this? Marthad? Welcome, Marthad! Come tonight and spend the night with us at the camp.” I replied: “O ʿAnāq, the Messenger of Allah ﷺ has forbidden fornication.” She cried out: “O people of the tents! This is the duldul who carries your captives from Makkah to Madinah!” I took the route of al-Khandamah, and eight men pursued me. They came until they stood directly above my head and urinated, and their urine splashed upon me, but Allah blinded them to my presence. I then went to my companion and carried him away. When I reached al-Arāk, I removed his shackles. Then I came to the Messenger of Allah ﷺ and asked: “O Messenger of Allah, may I marry ʿAnāq?” He remained silent until the verse was revealed: “The fornicatress is not married except by a fornicator or a polytheist.”  [al-Nūr: 3] He recited it to me and said: “Do not marry her.”"]},"buhuth":{"en":["Al-Azraqī said:","Al-duldul means a hedgehog, which most often appears at night and conceals its head.","Al-Khandamah is a mountain behind Abū Qubays."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2051,"lafz":true},{"key":"nasai","label":"النسائي","number":3228,"n":3228},{"key":"tirmidhi","label":"الترمذي","number":3176},{"key":"sh22547","label":"الطحاوي في مشكل الآثار","number":4552}],"full":1,"dr":1},{"num":6496,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، أَنَّ رَجُلًا، مِنَ الْمُسْلِمِينَ اسْتَأْذَنَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي امْرَأَةٍ يُقَالُ لَهَا: أُمُّ مَهْزُولٍ، وَكَانَتْ تُسَافِحُ، وَتَشْتَرِطُ لَهُ أَنْ تُنْفِقَ عَلَيْهِ، قَالَ: فَاسْتَأْذَنَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوْ ذَكَرَ لَهُ أَمْرَهَا؟ قَالَ: فَقَرَأَ عَلَيْهِ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ﴿الزَّانِيَةُ لَا يَنْكِحُهَا إِلَّا زَانٍ أَوْ مُشْرِكٌ﴾ [النور:"],"takhrij":"حسن: رواه أحمد (6480) والحاكم (2/193-194) والبيهقي (7/153) كلهم عن معتمر بن سليمان، قال أبي: حدثنا الحضرمي، عن القاسم بن محمد، عن عبدالله بن عمرو فذكره.","grade":"حسن","chapter_ar":"باب النهي عن نكاح الزانية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6480), al-Hakim (2/193–194), and al-Bayhaqi (7/153).","chapter_en":"The Prohibition of Marrying a Fornicating Woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":19,"content":{"translation":{"en":["ʿAbd Allah ibn ʿAmr narrated that a Muslim man sought the permission of the Messenger of Allah ﷺ regarding a woman named Umm Mahzul. She used to commit fornication, and she would stipulate to any man who married her that she would suffice him financially. So he sought the permission of the Messenger of Allah ﷺ, or her matter was mentioned to him. He said: Then the Prophet of Allah ﷺ recited to him: “The fornicatress — none marries her except a fornicator or a polytheist” [al-Nur 24:3]."]}},"tuhfa":{},"refs":[{"key":"hakim","label":"الحاكم","number":194},{"key":"kubrabayhaqi","label":"البيهقي","number":153},{"key":"ahmad","label":"مسند الإمام أحمد","number":6480,"n":6480,"lafz":true}],"full":1,"dr":1},{"num":6497,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ يَنْكِحُ الزَّانِي الْمَجْلُودُ إِلاَّ مِثْلَهُ."],"takhrij":"حسن: رواه أبو داود (2052) وأحمد (8300) والحاكم (2/166) ومن طريقه البيهقي (7/156)كلهم من حديث عبد الوارث، عن حبيب المعلم، عن عمرو بن شعيب، عن سعيد بن أبي سعيد المقبري، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب النهي عن نكاح الزانية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2052), Ahmad (8300), and al-Hakim (2/166).","chapter_en":"The Prohibition of Marrying a Fornicating Woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":19,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “A flogged fornicator marries none but one like himself.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2052,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":8300,"n":8300},{"key":"hakim","label":"المستدرك على الصحيحين","number":2700,"n":2686}],"full":1,"dr":1,"rep":[12840]},{"num":6498,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ أَيُّمَا عَبْدٍ تَزَوَّجَ بِغَيْرِ إِذْنِ سَيِّدِهِ فَهُوَ عَاهِرٌ."],"takhrij":"حسن: رواه أبو داود (2078) والترمذي (1112،1111) وابن ماجة (1959) وصحّحه الحاكم (2/194) كلهم من حديث عبد الله بن محمد بن عقيل، عن جابر فذكره إلا ابن ماجة فقال فيه \"عن ابن عمر\" وهو غير محفوظ.","grade":"حسن","chapter_ar":"باب لا يصح نكاح العبد بغير إذن سيده","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2078), al-Tirmidhi (1111, 1112), Ibn Majah (1959), and authenticated by al-Hakim (2/194).","chapter_en":"The Marriage of a Slave Is Not Valid Without the Permission of His Master","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":20,"content":{"translation":{"en":["Jabir ibn ʿAbd Allah said: The Prophet ﷺ said: “Any slave who marries without the permission of his master is a fornicator.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2078,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1111},{"key":"ibnmajah","label":"ابن ماجه","number":1959},{"key":"hakim","label":"صحّحه الحاكم","number":194},{"key":"tirmidhi","label":"الترمذي","number":1112}],"full":1,"dr":1},{"num":6499,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ، تَزَوَّجَ امْرَأَةً عَلَى وَزْنِ نَوَاةٍ، فَرَأَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَشَاشَةَ الْعُرْسِ فَسَأَلَهُ فَقَالَ إِنِّي تَزَوَّجْتُ امْرَأَةً عَلَى وَزْنِ نَوَاةٍ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5148)، ومسلم في النكاح (82:1427) كلاهما من طريق شعبة، حدثنا عبد العزيز بن صهيب قال: سمعت أنسا يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب وجوب الصداق وأنه لا حد لأكثره ولا لأقله وجوازه بتعليم القرآن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5148) and Muslim (1427 no. 82). Al-Bukhari added: the weight of a date-stone of gold.","chapter_en":"The Obligation of the Dowry, That There Is No Fixed Maximum or Minimum for It, and the Permissibility of Making Teaching the Qur’an a Dowry","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Anas narrated that ʿAbd al-Rahman ibn ʿAwf married a woman for the weight of a date-stone. The Prophet ﷺ saw the signs of marriage happiness on him and asked him, and he said: I have married a woman for the weight of a date-stone."]},"buhuth":{"en":["A date-stone was valued at five dirhams. In another narration, Anas said: I indeed saw that after his death, one hundred thousand was apportioned to each of his wives."]},"intro":{"ar":["قال الله تعالى: (وَءَاتُوا النِّسَاءَ صَدُقَاتِهِنَّ نِحْلَةً) [النساء: ٤]","وقال تعالى: (وَإِنْ أَرَدتُّمُ ٱسْتِبْدَالَ زَوْجٍ مَّكَانَ زَوْجٍ وَءَاتَيْتُمْ إِحْدَىٰهُنَّ قِنطَارًا فَلَا تَأْخُذُواْ مِنْهُ شَيْـًٔا) [النساء: ٢٠]","وقال تعالى: (وَإِن طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ وَقَدْ فَرَضْتُمْ لَهُنَّ فَرِيضَةً فَنِصْفُ مَا فَرَضْتُمْ) [البقرة: ٢٣٧]"],"en":["Allah the Exalted said: “Give the women their dowries graciously.” [al-Nisa’ 4:4]","And He said: “And if you intend to replace one wife with another and you have given one of them a great amount, do not take anything from it.” [al-Nisa’ 4:20]","And He said: “And if you divorce them before you have touched them, while you have already specified for them an obligation, then half of what you specified is due.” [al-Baqarah 2:237]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5148,"lafz":true},{"key":"muslim","label":"مسلم","number":82}],"full":1,"dr":1},{"num":6500,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ قَالَ: جَاءَتِ امْرَأَةٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ، جئتُ أهبُ لَكَ نَفْسِي. فَنَظَرَ إِلَيْهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَعَّدَ النَّظَرَ فِيهَا وَصَوَّبَهُ، ثُمَّ طَأْطَأَ رَأْسَهُ، فَلَمَّا رَأَتِ الْمَرْأَةُ أَنَّهُ لَمْ يَقْضِ فِيهَا شَيْئًا جَلَسَتْ، فَقَامَ رجلٌ مِنْ أَصْحَابِهِ فَقَالَ: يَا رَسُولَ اللَّهِ! إِنْ لَمْ يكنْ لَكَ بِهَا حَاجَةٌ فَزَوِّجْنِيهَا فَقَالَ: هَلْ عِنْدَكَ شيء؟ قَالَ: لاَ وَاللَّهِ يَا رَسُولَ اللَّهِ. قَالَ: اذْهَبْ إِلَى أَهْلِكَ فَانْظُرْ هَلْ تَجِدُ شَيْئًا؟ فَذَهَبَ ثُمَّ رَجَعَ، فَقَالَ: لاَ وَاللَّهِ، مَا وَجَدْتُ شَيْئًا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: انْظُرْ وَلَوْ خَاتَمًا مِنْ حَدِيدٍ، فَذَهَبَ ثُمَّ رَجَعَ، فَقَالَ: لاَ وَاللَّهِ يَا رَسُولَ اللَّهِ وَلاَ خَاتَمًا مِنْ حَدِيدٍ، وَلَكِنْ هَذَا إِزَارِي – قَالَ سَهْلٌ: مَا لَهُ رِدَاءٌ – فَلَهَا نِصْفُهُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا تَصْنَعُ بِإِزَارِكَ، إِنْ لَبِسْتَهُ لَمْ يَكُنْ عَلَيْهَا مِنْهُ شيء، وَإِنْ لَبِسَتْهُ لَمْ يَكُنْ عَلَيْكَ مِنْهُ شيء. فَجَلَسَ الرَّجُلُ حَتَّى إِذَا طَالَ مَجْلِسُهُ قَامَ، فَرَآهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُوَلِّيًا، فَأَمَرَ بِهِ فَدُعِيَ لَهُ، فَلَمَّا جَاءَ، قَالَ: مَا مَعَكَ مِنَ الْقُرْآنِ؟ قَالَ: مَعِي سُورَةُ كَذَا، وَسُورَةُ كَذَا عَدَّدَهَا. فَقَالَ: تَقْرَؤُهُنَّ عَنْ ظَهْرِ قلب؟ قَالَ: نَعَمْ. قَالَ: اذْهَبْ لَقَدْ مَلَّكْتُكَهَا بِمَا معكَ مِنَ الْقُرْآنِ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5087) ومسلم في النكاح (1425) كلاهما عن قتيبة بن سعيد الثقفي، حدثنا عبد العزيز بن أبي حازم، عن أبيه، عن سهل بن سعد الساعدي فذكره. ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب وجوب الصداق وأنه لا حد لأكثره ولا لأقله وجوازه بتعليم القرآن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5087) and Muslim (1425).","chapter_en":"The Obligation of the Dowry, That There Is No Fixed Maximum or Minimum for It, and the Permissibility of Making Teaching the Qur’an a Dowry","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Sahl ibn Saʿd reported: A woman came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, I have come to offer myself to you.” The Messenger of Allah ﷺ looked at her, raising and lowering his gaze, then lowered his head. When the woman saw that he had made no decision concerning her, she sat down. A man from among his Companions stood up and said: “O Messenger of Allah, if you have no need of her, then marry her to me.” He asked: “Do you have anything?” He replied: “No, by Allah, O Messenger of Allah.” He said: “Go to your family and see whether you can find anything.” He went and then returned and said: “No, by Allah, I found nothing.” The Messenger of Allah ﷺ said: “Look, even if it is only an iron ring.” He went and returned and said: “No, by Allah, O Messenger of Allah, not even an iron ring. But I have this lower garment”—Sahl said that he had no upper garment—“and she may have half of it.” The Messenger of Allah ﷺ said: “What would she do with your lower garment? If you wear it, she will have none of it; and if she wears it, you will have none of it.” The man sat down. After he had remained seated for a long time, he got up to leave. The Messenger of Allah ﷺ saw him turning away and ordered that he be called back. When he returned, he asked: “What do you know of the Qurʾān?” He replied: “I know such-and-such surah and such-and-such surah,” and he listed them. He asked: “Do you recite them from memory?” He replied: “Yes.” He said: “Go. I have married her to you for what you know of the Qurʾān.”"]},"buhuth":{"en":["In Muslim’s wording:","“Go, for I have married her to you, so teach her from the Qurʾān.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5087,"lafz":true},{"key":"muslim","label":"مسلم","number":1425}],"full":1,"dr":1,"rep":[15592]},{"num":6501,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ إِنِّي تَزَوَّجْتُ امْرَأَةً مِنَ الأَنْصَارِ. فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَلْ نَظَرْتَ إِلَيْهَا فَإِنَّ فِي عُيُونِ الأَنْصَارِ شَيْئًا. قَالَ قَدْ نَظَرْتُ إِلَيْهَا. قَالَ عَلَى كَمْ تَزَوَّجْتَهَا. قَالَ عَلَى أَرْبَعِ أَوَاقٍ. فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى أَرْبَعِ أَوَاقٍ كَأَنَّمَا تَنْحِتُونَ الْفِضَّةَ مِنْ عُرْضِ هَذَا الْجَبَلِ مَا عِنْدَنَا مَا نُعْطِيكَ وَلَكِنْ عَسَى أَنْ نَبْعَثَكَ فِي بَعْثٍ تُصِيبُ مِنْهُ. قَالَ فَبَعَثَ بَعْثًا إِلَى بَنِي عَبْسٍ بَعَثَ ذَلِكَ الرَّجُلَ فِيهِمْ."],"takhrij":"صحيح: رواه مسلم في النكاح (75:1424) عن يحيى بن معين، حدّثنا مروان بن معاوية الفزاري، حدثنا يزيد بن كيسان، عن أبي حازم، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب وجوب الصداق وأنه لا حد لأكثره ولا لأقله وجوازه بتعليم القرآن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1424 no. 75). In this is evidence for the dislike of an excessive dowry relative to the husband’s condition.","chapter_en":"The Obligation of the Dowry, That There Is No Fixed Maximum or Minimum for It, and the Permissibility of Making Teaching the Qur’an a Dowry","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Abu Hurairah said: A man came to the Prophet ﷺ and said: I have married a woman from the Ansar. The Prophet ﷺ said to him: “Did you look at her? For indeed there is something in the eyes of the Ansar.” He said: I did look at her. He said: “For how much did you marry her?” He said: For four uqiyyahs. The Prophet ﷺ said to him: “For four uqiyyahs? It is as though you are carving silver from the side of this mountain. We do not have anything to give you, but perhaps we may send you on an expedition from which you may obtain something.” He said: Then he sent an expedition to Banu ʿAbs, and sent that man among them."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":75,"lafz":true}],"full":1,"dr":1},{"num":6502,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: كَانَ الصداق إِذْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِينَا عشرة أَوَاقٍ. وَطَبَّقَ بِيَدَيْهِ وَذَلِكَ أَرْبَعُ مِائَةٍ."],"takhrij":"صحيح: رواه النسائي (3348) وأحمد (8807) والدارقطني (3/222) وصحّحه ابن حبان (4097) والحاكم (2/175) كلهم من طريق داود بن قيس، عن موسى بن يسار، عن أبي هريرة. فذكره، واختصره البعض إلى قوله: عشرة أواق. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب وجوب الصداق وأنه لا حد لأكثره ولا لأقله وجوازه بتعليم القرآن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3348), Ahmad (8807), al-Daraqutni (3/222), and authenticated by Ibn Hibban (4097).","chapter_en":"The Obligation of the Dowry, That There Is No Fixed Maximum or Minimum for It, and the Permissibility of Making Teaching the Qur’an a Dowry","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Abu Hurairah said: The dowry, when the Messenger of Allah ﷺ was among us, was ten uqiyyahs. And he clapped his hands together, and that was four hundred."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3348,"lafz":true,"n":3348},{"key":"sh9771","label":"الدار قطني","number":222},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":4097},{"key":"ahmad","label":"مسند الإمام أحمد","number":8807,"n":8807}],"full":1,"dr":1},{"num":6503,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَحَقُّ الشُّرُوطِ أَنْ تُوفُوا بِهِ مَا اسْتَحْلَلْتُمْ بِهِ الْفُرُوجَ."],"takhrij":"صحيح: رواه البخاري في الشروط (2721) عن عبد الله بن يوسف، حدثنا الليث قال: حدثني يزيد بن أبي حبيب، عن أبي الخير، عن عقبة بن عامر فذكره.","grade":"صحيح","chapter_ar":"باب وجوب الصداق وأنه لا حد لأكثره ولا لأقله وجوازه بتعليم القرآن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2721). That is, among the conditions connected to dowries and marriage arrangements.","chapter_en":"The Obligation of the Dowry, That There Is No Fixed Maximum or Minimum for It, and the Permissibility of Making Teaching the Qur’an a Dowry","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["ʿUqbah ibn ʿAmir said: The Messenger of Allah ﷺ said: “The conditions most deserving to be fulfilled are those by which you made the private parts lawful.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2721,"lafz":true}],"full":1,"dr":1,"rep":[6192]},{"num":6504,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ، أَنَّهُ قَالَ سَأَلْتُ عَائِشَةَ زَوْجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَمْ كَانَ صَدَاقُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ كَانَ صَدَاقُهُ لأَزْوَاجِهِ ثِنْتَىْ عَشْرَةَ أُوقِيَّةً وَنَشًّا. قَالَتْ أَتَدْرِي مَا النَّشُّ قَالَ قُلْتُ لاَ. قَالَتْ نِصْفُ أُوقِيَّةٍ. فَتِلْكَ خَمْسُمِائَةِ دِرْهَمٍ فَهَذَا صَدَاقُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لأَزْوَاجِهِ."],"takhrij":"صحيح: رواه مسلم في النكاح (1426) من طريق يزيد بن عبدالله بن أسامة بن الهاد، عن محمد بن إبراهيم، عن أبي سلمة بن عبدالرحمن فذكره.","grade":"صحيح","chapter_ar":"باب ما يستحب من القصد في الصداق","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1426). His statement, “nashsh,” is a term for twenty dirhams, or it means half of something.","chapter_en":"What Is Recommended of Moderation in the Dowry","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Abu Salamah ibn ʿAbd al-Rahman said: I asked ʿA’ishah, the wife of the Prophet ﷺ, how much the dowry of the Messenger of Allah ﷺ was. She said: His dowry to his wives was twelve uqiyyahs and a nashsh. She said: Do you know what a nashsh is? I said: No. She said: Half an uqiyyah. So that amounted to five hundred dirhams. That was the dowry of the Messenger of Allah ﷺ for his wives."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1426,"lafz":true}],"full":1,"dr":1},{"num":6505,"demo":false,"sanad":"","matn":["عَنْ أُمِّ حَبِيبَةَ أَنَّهَا كَانَتْ تَحْتَ عُبَيْدِ اللَّهِ بْنِ جَحْشٍ فَمَاتَ بِأَرْضِ الْحَبَشَةِ فَزَوَّجَهَا النَّجَاشِيُّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَأَمْهَرَهَا عَنْهُ أَرْبَعَةَ آلاَفٍ، وَبَعَثَ بِهَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَعَ شُرَحْبِيلَ بْنِ حَسَنَةَ. وَلَمْ يبعث إِلَيْهَا رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بشيء، وَكَانَ مهر نِسَائِهِ أربعمائة درهم.","قال أبو داود: حسنة هي أمه."],"takhrij":"صحيح: رواه أبو داود (2107) والنسائي (3350) وأحمد (27408) والحاكم (2/181) والبيهقي (7/232) كلهم من حديث معمر، عن الزهري، عن عروة، عن أم حبيبة فذكرته.","grade":"صحيح","chapter_ar":"باب ما يستحب من القصد في الصداق","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2107), al-Nasa’i (3350), Ahmad (27408), al-Hakim (2/181), and al-Bayhaqi (7/232).","chapter_en":"What Is Recommended of Moderation in the Dowry","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Umm Habibah had been married to ʿUbayd Allah ibn Jahsh, and he died in the land of Abyssinia. Then the Negus married her to the Prophet ﷺ and gave her, on his behalf, a dowry of four thousand. He sent her to the Messenger of Allah ﷺ with Sharhabil ibn Hasanah. The Messenger of Allah ﷺ did not send her anything, while the dowries of his other wives were four hundred dirhams. Abu Dawud said: Hasanah was his mother."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2107,"lafz":true},{"key":"nasai","label":"النسائي","number":3350},{"key":"hakim","label":"الحاكم","number":181},{"key":"kubrabayhaqi","label":"البيهقي","number":232},{"key":"ahmad","label":"مسند الإمام أحمد","number":27408,"n":27408}],"full":1,"dr":1,"rep":[9416,10417]},{"num":6506,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَزَا، فَصَلَّيْنَا عِنْدَهَا صَلاَةَ الْغَدَاةِ بِغَلَسٍ، فَرَكِبَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَرَكِبَ أَبُو طَلْحَةَ، وَأَنَا رَدِيفُ أَبِي طَلْحَةَ، فَأَجْرَى نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي زُقَاقِ خَيْبَرَ، وإنَّ رُكْبَتِي لتمسُّ فخـذ نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، ثُمَّ حسَر الإِزَارَ عَنْ فَخِذِهِ، حَتَّى إِنِّي أَنْظُرُ إِلَى بَيَاضِ فَخِذِ نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَلَمَّا دَخَلَ الْقَرْيَةَ قَالَ: اللَّهُ أَكْبَرُ خَرِبَتْ خَيْبَرُ، إِنَّا إِذَا نَزَلْنَا بِسَاحَةِ قومٍ، فَسَاءَ صَبَاحُ الْمُنْذَرِينَ. قَالَهَا ثَلاَثًا، قَالَ: وَخَرَجَ الْقَوْمُ إِلَى أَعْمَالِهِمْ، فَقَالُوا: مُحَمَّدٌ – قَالَ عَبْدُ الْعَزِيزِ، وَقَالَ بَعْضُ أَصْحَابِنَا: وَالْخَمِيسُ، يَعْنِي الْجَيْشَ – فَأَصَبْنَاهَا عَنْوةً، فجُمعَ السبيُ، فَجَاءَ دِحْيَةُ، فَقَالَ: يَا نَبِيَّ اللَّهِ، أَعْطِنِي جَارِيَةً مِنَ السبْي، قَالَ: اذْهَبْ فخُذْ جَارِيَةً فَأَخَذَ صَفِيَّةَ بِنْتَ حُيَيّ، فَجَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا نَبِيَّ اللَّهِ، أَعْطَيْتَ دِحْيَةَ صَفِيَّةَ بِنْتَ حيي، سَيِّدَةَ قُرَيْظَةَ وَالنَّضِيرِ؟ لاَ تَصْلُحُ إِلاَّ لَكَ، قَالَ: ادْعُوهُ بِهَا فَجَاءَ بِهَا، فَلَمَّا نَظَرَ إِلَيْهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: خُذْ جَارِيَةً مِنَ السبْي غَيْرَهَا قَالَ: فَأَعْتَقَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَتَزَوَّجَهَا. فَقَالَ لَهُ ثَابِتٌ: يَا أَبَا حَمْزَةَ، مَا أَصْدَقَهَا؟ قَالَ: نَفْسَهَا، أَعْتَقَهَا وَتَزَوَّجَهَا، حَتَّى إِذَا كَانَ بِالطَّرِيقِ جَهَّزَتْهَا لَهُ أمُّ سُلَيْمٍ، فَأَهْدَتْهَا لَهُ مِنَ اللَّيْلِ، فَأَصْبَحَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَرُوسًا فَقَالَ: مَنْ كَانَ عِنْدَهُ شيء فليجيءْ بِهِ وَبَسَطَ نِطْعا، فَجَعَلَ الرَّجُلُ يَجِيءُ بالأقِط، وَجَعَلَ الرَّجُلُ يَجِيءُ بِالتَّمْرِ، وَجَعَلَ الرَّجُلُ يَجِيءُ بِالسَّمْنِ، قَالَ: وَأَحْسِبُهُ قَدْ ذَكَرَ السَّوِيقَ، قَالَ: فَحَاسُوا حَيْسًا، فَكَانَتْ وَلِيمَةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ."],"takhrij":"متفق عليه: رواه البخاري الصلاة (371)، ومسلم في النكاح (84:1365) كلاهما من طريق إسماعيل بن علية، حدثنا عبد العزيز بن صهيب، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب جعل العتق صداقا","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (371) and Muslim (1365 no. 84).","chapter_en":"Making Emancipation the Dowry","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["Anas narrated that the Messenger of Allah ﷺ went out on a military expedition, and we prayed the dawn prayer there in the darkness before daylight. The Prophet of Allah ﷺ rode, and Abu Talhah rode, and I was riding behind Abu Talhah. The Prophet of Allah ﷺ urged his mount through the lanes of Khaybar, and my knee was touching the thigh of the Prophet of Allah ﷺ. Then he uncovered his thigh from his waist-wrapper until I could see the whiteness of the Prophet’s thigh. When he entered the town, he said, “Allah is the Greatest! Khaybar is ruined. When we descend in the courtyard of a people, evil is the morning of those who were warned.” He said this three times. The people had gone out to their work, and they said, “Muhammad!” ʿAbd al-ʿAziz said, and some of our companions said, “and the army,” meaning the army. So we conquered it by force, and the captives were gathered. Dihyah came and said, “O Prophet of Allah, give me a slave girl from the captives.” He said, “Go and take a slave girl.” So he took Safiyyah bint Huyayy. Then a man came to the Prophet ﷺ and said, “O Prophet of Allah, you gave Dihyah Safiyyah bint Huyayy, the chief lady of Qurayzah and al-Nadir. She is suitable for no one but you.” He said, “Bring him with her.” So he brought her. When the Prophet ﷺ looked at her, he said, “Take another slave girl from the captives besides her.” Then the Prophet ﷺ freed her and married her. Thabit said to him: O Abu Hamzah, what did he give her as her dowry? He said: Her own self. He freed her and married her. Then when they were on the road, Umm Sulaym prepared her for him and sent her to him at night. By morning, the Prophet ﷺ was a bridegroom, and he said, “Whoever has anything, let him bring it.” He spread out a leather cloth, and one man brought dried curds, another brought dates, and another brought clarified butter. I think he also mentioned roasted flour. Then they mixed it into a dish of hays, and that was the wedding feast of the Messenger of Allah ﷺ."]},"buhuth":{"en":["Al-hays is a type of food made from dried curds, dates, and clarified butter, mixed and kneaded together, and sometimes roasted flour is also mixed into it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":371,"lafz":true},{"key":"muslim","label":"مسلم","number":84}],"full":1,"dr":1},{"num":6507,"demo":false,"sanad":"","matn":["عن أنس قال: صَارَتْ صَفِيَّةُ لِدِحْيَةَ فِى مَقْسَمِهِ، وَجَعَلُوا يَمْدَحُونَهَا عِنْدَ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَيَقُولُونَ مَا رَأَيْنَا فِي السَّبْىِ مِثْلَهَا، قَالَ: فَبَعَثَ إِلَى دِحْيَةَ فَأَعْطَاهُ بِهَا مَا أَرَادَ، ثُمَّ دَفَعَهَا إِلَى أُمِّي، فَقَالَ: أَصْلِحِيهَا.","قَالَ: ثُمَّ خَرَجَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ خَيْبَرَ حَتَّى إِذَا جَعَلَهَا فِى ظَهْرِهِ، نَزَلَ، ثُمَّ ضَرَبَ عَلَيْهَا الْقُبَّةَ، فَلَمَّا أَصْبَحَ قَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ كَانَ عِنْدَهُ فَضْلُ زَادٍ فَلْيَأْتِنَا بِهِ. قَالَ: فَجَعَلَ الرَّجُلُ يَجِىءُ بِفَضْلِ التَّمْرِ وَفَضْلِ السَّوِيقِ حَتَّى جَعَلُوا مِنْ ذَلِكَ سَوَادًا حَيْسًا، فَجَعَلُوا يَأْكُلُونَ مِنْ ذَلِكَ الْحَيْسِ وَيَشْرَبُونَ مِنْ حِيَاضٍ إِلَى جَنْبِهِمْ مِنْ مَاءِ السَّمَاءِ، قَالَ: فَقَالَ أَنَسٌ: فَكَانَتْ تِلْكَ وَلِيمَةَ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَيْهَا، قَالَ: فَانْطَلَقْنَا حَتَّى إِذَا رَأَيْنَا جُدُرَ المَدِينَةِ هَشِشْنَا إِلَيْهَا فَرَفَعْنَا مَطِيَّنَا وَرَفَعَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَطِيَّتَهُ، قَالَ: وَصَفِيَّةُ خَلْفَهُ قَدْ أَرْدَفَهَا رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: فَعَثَرَتْ مَطِيَّةُ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَصُرِعَ وَصُرِعَتْ، قَالَ: فَلَيْسَ أَحَدٌ مِنَ النَّاسِ يَنْظُرُ إِلَيْهِ وَلاَ إِلَيْهَا حَتَّى قَامَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَتَرَهَا، قَالَ: فَأَتَيْنَاهُ، فَقَالَ:لَمْ نُضَرَّ. قَالَ: فَدَخَلْنَا المَدِينَةَ، فَخَرَجَ جَوَارِى نِسَائِهِ يَتَرَاءَيْنَهَا وَيَشْمَتْنَ بِصَرْعَتِهَا."],"takhrij":"صحيح: رواه مسلم في النكاح (1365: 88) عن أبي بكر بن أبي شيبة، حدثنا شبابة، حدثنا سليمان، عن ثابت، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب جعل العتق صداقا","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in the Book of Marriage (1365 no. 88).","chapter_en":"Making Emancipation the Dowry","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["Anas said: Safiyyah fell to Dihyah in his allotted share, and they began praising her before the Messenger of Allah ﷺ, saying: We have not seen anyone like her among the captives. So he sent for Dihyah and gave him in exchange what he wished, then he handed her over to my mother and said, “Prepare her.” Then the Messenger of Allah ﷺ left Khaybar, and when he placed her behind him on his mount, he stopped and set up a tent over her. When morning came, the Messenger of Allah ﷺ said, “Whoever has extra provisions, let him bring them to us.” Then one man would bring extra dates, and another extra roasted flour, until they made from that a large amount of hays. They began eating from that hays and drinking from pools beside them filled with rainwater. Anas said: That was the wedding feast of the Messenger of Allah ﷺ for her. Then we proceeded on until, when we saw the walls of Madinah, we became eager for it and hastened our mounts, and the Messenger of Allah ﷺ also hastened his mount. Safiyyah was behind him, for the Messenger of Allah ﷺ had seated her behind him. Then the mount of the Messenger of Allah ﷺ stumbled, and he fell and she fell. No one among the people looked at him or at her until the Messenger of Allah ﷺ stood and covered her. Then we came to him, and he said, “We have not been harmed.” Then we entered Madinah, and the servant girls of his wives came out looking at her and gloating over her fall."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم في النكاح","number":88,"lafz":true},{"key":"muslim","label":"مسلم في النكاح","number":1365,"n":3501}],"full":1,"dr":1,"rep":[9073]},{"num":6508,"demo":false,"sanad":"","matn":["عن جُوَيْرِيَةَ بنت الْحَارِثِ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ أَزْوَاجَكَ يَفْخَرْنَ عَلَيَّ يَقُلْنَ: لَمْ يَتَزَوَّجْكِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّمَا أَنْتِ مِلْكُ يَمِينٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَلَمْ أُعَظِّمْ صَدَاقَكِ، أَلَمْ أُعْتِقَ أَرْبَعِينَ رَقَبَةً مِنْ قَوْمِكِ."],"takhrij":"صحيح: رواه إسحاق في مسنده (4/255) عن سفيان، عن ابن أبي نجيح، عن مجاهد، قال: قالت جويرية بنت الحارث فذكره.","grade":"صحيح","chapter_ar":"باب جعل العتق صداقا","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ishaq in his Musnad (4/255), ʿAbd al-Razzaq (7/271–272), and al-Hakim (4/25).","chapter_en":"Making Emancipation the Dowry","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["Juwayriyyah bint al-Harith said to the Messenger of Allah ﷺ: Your wives boast over me and say: The Messenger of Allah did not really marry you; you are only a bondwoman. So the Messenger of Allah ﷺ said, “Did I not make your dowry great? Did I not free forty of your people?”"]}},"tuhfa":{},"refs":[{"key":"اسحاق/مسندہ","label":"إسحاق في مسنده","number":255,"lafz":true},{"key":"abdrazzaq","label":"عبد الرزاق","number":272},{"key":"hakim","label":"المستدرك على الصحيحين","number":6778,"n":6776}],"full":1,"dr":1},{"num":6509,"demo":false,"sanad":"","matn":["عن أبي موسى قال: قال رسول الله صلى الله عليه وسلم: ثلاثة لهم أجران منهم: رجل كانت عنده أمةٌ فأدّبَها فأحسن تأديبها، وعلّمها فأحسن تعليمها، ثم أعتَقها، فتزوَّجها، فله أجران."],"takhrij":"متفق عليه: رواه البخاري في العلم (97) ومسلم في الإيمان (154) كلاهما عن الشعبي، عن أبي بردة بن أبي موسى، عن أبيه فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل من أعتق ثم تزوجها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari in the Book of Knowledge (97) and Muslim in the Book of Faith (154).","chapter_en":"The Virtue of One Who Frees a Slave Woman and Then Marries Her","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Abu Musa said: The Messenger of Allah ﷺ said, “Three people will have a double reward.” Among them is: “A man who had a slave woman, disciplined her and did so well, taught her and taught her well, then freed her and married her — he will have two rewards.”"]},"buhuth":{"en":["His statement, “then married her,” means with a dowry."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري في العلم","number":97,"lafz":true},{"key":"muslim","label":"مسلم في الإيمان","number":154}],"full":1,"dr":1},{"num":6510,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: أتتْ جُوَيْرِيَةُ بِنْتُ الْحَارِثِ رسولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَسْتَعِينُهُ فِي كِتَابَتِهَا، فو اللهِ مَا هُوَ إِلَاّ أَنْ وَقَفَتْ عَلَى بَابِ الْحُجْرَةِ. فَرَأَيْتُهَا فَكَرِهْتُ مكانها. وَعَرَفْتُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَيَرَى مِنْهَا مِثْلَ مَا رَأَيْتُ. فَقَالَتْ جُوَيْرِيَةُ: يَا رَسُولَ اللَّهِ كَانَ مِنَ الأَمْرِ مَا قَدْ عَرَفْتَ. فَكَاتَبْتُ نَفْسِي فَجِئْتُ أَسْتَعِينُهُ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَوَ مَا هُوَ خَيْرٌ مِنْ ذَلِكَ؟ قَالَتْ: مَا هُوَ؟ قَالَ: أَتَزَوَّجُكِ وأقضى عَنْكِ كِتَابَتَكِ فَقَالَتْ: نَعَمْ. قَالَ: قَدْ فَعَلْتُ قَالَتْ: فَبَلَغَ الْمُسْلِمِينَ ذَلِكَ فَقَالُوا: أَصْهَارُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَرْسَلُوا مَا كَانَ فِي أَيْدِيهِمْ مِنْ سَبَايَا بَنِي الْمُصْطَلِقِ. قَالَتْ: فَلَقَدْ عُتِق بِتَزْوِيجِهِ مِائَةُ أَهْلِ بَيْتٍ مِنْ بَنِي الْمُصْطَلِقِ. قَالَتْ: فَمَا أَعْلَمُ امْرَأَةً كَانَتْ أَعْظَمَ بَرَكَةً عَلَى قَوْمِهَا مِنْهَا."],"takhrij":"حسن: رواه أبو داود (3931) وأحمد (26365) وابن حبان (4054) والحاكم (4/26) كلهم من حديث محمد بن إسحاق قال: حدثني محمد بن جعفر بن الزبير، عن عروة، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب جعل الصداق أداء ما كوتبت عليه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3931), Ahmad (26365), Ibn Hibban (4054), and al-Hakim (4/26).","chapter_en":"Making the Dowry the Payment of What She Had Contracted for Her Emancipation","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":5,"content":{"translation":{"en":["ʿA’ishah said: Juwayriyyah bint al-Harith came to the Messenger of Allah ﷺ seeking his help regarding her emancipation contract. By Allah, as soon as she stood at the door of the room, I saw her and disliked her place there, for I knew that the Messenger of Allah ﷺ would see in her what I had seen. Juwayriyyah said: O Messenger of Allah, you know what has happened to me. I made a contract for my freedom, and I have come seeking your help. The Messenger of Allah ﷺ said, “Shall I not offer you something better than that?” She said: What is it? He said, “I will marry you and pay off your contract for you.” She said: Yes. He said: “I have done so.” She said: When the Muslims heard that, they said: They are the relatives by marriage of the Messenger of Allah ﷺ. So they released whatever captives of Banu al-Mustaliq were in their hands. She said: One hundred households of Banu al-Mustaliq were freed because of his marriage to her. She said: I do not know of any woman who brought a greater blessing upon her people than she did."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3931,"lafz":true},{"key":"hakim","label":"الحاكم","number":26},{"key":"ahmad","label":"مسند الإمام أحمد","number":26365,"n":26365},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":5658,"n":5654},{"key":"ibnhibban","label":"ابن حبان","number":4054}],"full":1,"dr":1},{"num":6511,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: خَيْرُ النِّكَاحِ أَيْسَرُهُ."],"takhrij":"صحيح: رواه أبو داود (2117) وابن حبان في صحيحه (4072) والحاكم (2/181-182) وعنه البيهقي (7/232) والقُضاعي في مسند الشهاب (1226) كلهم من حديث محمد بن سلمة، عن أبي عبد الرحيم خالد بن أبي يزيد، عن زيد بن أبي أنيسة، عن يزيد بن أبي حبيب، عن مرثد بن عبد الله، عن عقبة بن عامر فذكره.","grade":"صحيح","chapter_ar":"باب خير النكاح أيسره نفقة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2117), Ibn Hibban in his Sahih (4072), and al-Hakim (2/181–182).","chapter_en":"The Best Marriage Is the One with the Least Expense","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":6,"content":{"translation":{"en":["ʿUqbah ibn ʿAmir said: The Messenger of Allah ﷺ said, “The best marriage is the easiest one.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2117,"lafz":true},{"key":"ibnhibban","label":"ابن حبان في صحيحه","number":4072},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":5659,"n":5655},{"key":"hakim","label":"المستدرك على الصحيحين","number":2841,"n":2827}],"full":1,"dr":1},{"num":6512,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ مِنْ يُمْنِ الْمَرْأَةِ تَيْسِيرَ خِطْبَتِهَا، وَتَيْسِيرَ صَدَاقِهَا، وَتَيْسِيرَ رَحِمِهَا."],"takhrij":"حسن: رواه أحمد (24478) والبزار – كشف الأستار (1417) وابن حبان (4095) والحاكم (2/181) وعنه البيهقي (7/235) كلهم من حديث أسامة بن زيد، عن صفوان بن سليم، عن عروة، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب خير النكاح أيسره نفقة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (24478), al-Bazzar in Kashf al-Astar (1417), Ibn Hibban (4095), and al-Hakim (2/181).","chapter_en":"The Best Marriage Is the One with the Least Expense","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":6,"content":{"translation":{"en":["ʿA’ishah narrated that the Messenger of Allah ﷺ said, “Part of a woman’s blessing is the ease of her proposal, the ease of her dowry, and the ease of her womb.”"]}},"tuhfa":{},"refs":[{"key":"sh12862","label":"البزار - كشف الأستار","number":1417},{"key":"ibnhibban","label":"ابن حبان","number":4095},{"key":"hakim","label":"الحاكم","number":181},{"key":"ahmad","label":"مسند الإمام أحمد","number":24478,"n":24478,"lafz":true}],"full":1,"dr":1},{"num":6513,"demo":false,"sanad":"","matn":["عَنْ أَبِي الْعَجْفَاءِ السُّلَمِيِّ، قَالَ خَطَبَنَا عُمَرُ رَحِمَهُ اللَّهُ فَقَالَ أَلاَ لاَ تُغَالُوا بِصُدُقِ النِّسَاءِ فَإِنَّهَا لَوْ كَانَتْ مَكْرُمَةً فِي الدُّنْيَا أَوْ تَقْوَى عِنْدَ اللَّهِ لَكَانَ أَوْلاَكُمْ بِهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا أَصْدَقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ امْرَأَةً مِنْ نِسَائِهِ وَلاَ أُصْدِقَتِ امْرَأَةٌ مِنْ بَنَاتِهِ أَكْثَرَ مِنْ ثِنْتَىْ عَشْرَةَ أُوقِيَّةً."],"takhrij":"حسن: رواه أبو داود (2106) والنسائي (3349) والترمذي (1114) وابن ماجة (1887) وأحمد (340) وصحّحه ابن حبان (4620) والحاكم (2/175-176) والبيهقي (7/234) كلهم من حديث محمد بن سيرين، عن أبي العجفاء السلمي فذكره.","grade":"حسن","chapter_ar":"باب النهي عن الغلاء في المهور","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2106), al-Nasa’i (3349), al-Tirmidhi (1114), Ibn Majah (1887), and Ahmad (340).","chapter_en":"The Prohibition of Exaggeration in Dowries","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":7,"content":{"translation":{"en":["Abu al-ʿAjfa’ al-Sulami said: ʿUmar addressed us and said: Do not be excessive in the dowries of women, for if that were an honor in this world or a sign of piety before Allah, then the Prophet ﷺ would have been more entitled to it than you. The Messenger of Allah ﷺ did not give any of his wives as dowry, nor was any of his daughters given in marriage for more than twelve uqiyyahs."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2106,"lafz":true},{"key":"nasai","label":"النسائي","number":3349,"n":3349},{"key":"tirmidhi","label":"الترمذي","number":1114},{"key":"ibnmajah","label":"ابن ماجه","number":1887},{"key":"ahmad","label":"مسند الإمام أحمد","number":340,"n":285},{"key":"ibnhibban","label":"ابن حبان","number":4620}],"full":1,"dr":1},{"num":6514,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِرَجُلٍ: أَتَرْضَى أَنْ أُزَوِّجَكَ فُلاَنَةَ؟. قَالَ: نَعَمْ، وَقَالَ لِلْمَرْأَةِ: أَتَرْضِينَ أَنْ أُزَوِّجَكِ فُلاَنًا قَالَتْ: نَعَمْ، فَزَوَّجَ أَحَدُهُمَا صَاحِبَهُ، فَدَخَلَ بِهَا الرَّجُلُ، وَلَمْ يَفْرِضْ لَهَا صَدَاقًا. وَلَمْ يُعْطِهَا شَيْئًا. وَكَانَ مِمَّنْ شَهِدَ الْحُدَيْبِيَةَ لَهُ سَهْمٌ خيبر. فَلَمَّا حَضَرَتْهُ الْوَفَاةُ قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ زَوَّجَنِي فُلاَنَةَ، وَلَمْ أَفْرِضْ لَهَا صَدَاقًا، وَلَمْ أُعْطِهَا شَيْئًا. وَإِنِّي أُشْهِدكم أَنِّي أَعْطَيْتُهَا مِنْ صَدَاقِهَا سَهْمِي بِخَيْبَرَ، فَأَخَذَتْ سَهْمًا فَبَاعَتْهُ بِمِائَةِ أَلْفٍ."],"takhrij":"صحيح: رواه أبو داود (2117) وصحّحه ابن حبان (4072) والحاكم (2/181-182) وعنه البيهقي (7/232) كلهم من طريق محمد بن سلمة، عن أبي عبد الرحيم خالد بن أبي يزيد، عن زيد بن أبي أنيسة، عن يزيد بن أبي حبيب، عن مرثد بن عبد الله، عن عقبة بن عامر فذكره.","grade":"صحيح","chapter_ar":"باب ينعقد النكاح بغير مهر","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2117), and authenticated by Ibn Hibban (4072) and al-Hakim (2/181–182).","chapter_en":"A Marriage Contract Is Valid Even Without Naming a Dowry","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["ʿUqbah ibn ʿAmir narrated that the Prophet ﷺ said to a man, “Are you pleased that I marry so-and-so to you?” He said: Yes. And he said to the woman, “Are you pleased that I marry so-and-so to you?” She said: Yes. So he married one of them to the other. The man consummated the marriage with her, but he had not specified any dowry for her and had not given her anything. He was among those who had witnessed al-Hudaybiyah and thus had a share from Khaybar. When death approached him, he said: The Messenger of Allah ﷺ married me to so-and-so, and I did not specify any dowry for her, nor did I give her anything. I make you witnesses that I have given her my share from Khaybar as her dowry. So she took the share and sold it for one hundred thousand."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2117,"lafz":true},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":4072},{"key":"hakim","label":"المستدرك على الصحيحين","number":2742,"n":2728}],"full":1,"dr":1},{"num":6515,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ، فِي رَجُلٍ تَزَوَّجَ امْرَأَةً فَمَاتَ عَنْهَا وَلَمْ يَدْخُلْ بِهَا وَلَمْ يَفْرِضْ لَهَا الصَّدَاقَ فَقَالَ لَهَا الصَّدَاقُ كَامِلاً وَعَلَيْهَا الْعِدَّةُ وَلَهَا الْمِيرَاثُ.","قال معقل بن سنان: سمعتُ رسول الله صلى الله عليه وسلم قضى في بروَع بنت واشق."],"takhrij":"صحيح: رواه أبو داود (2114) والنسائي (3356) وابن ماجة (1891) وصحّحه ابن حبان (4098) والحاكم (2/180-181) كلهم من حديث عبد الرحمن بن مهدي، عن سفيان، عن فراس، عن الشعبي، عن مسروق، عن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب فيمن تزوج ولم يسم صداقاً حتى مات","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2114), al-Nasa’i (3356), Ibn Majah (1891), and authenticated by Ibn Hibban.","chapter_en":"Concerning One Who Married Without Naming a Dowry, Then Died","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":9,"content":{"translation":{"en":["ʿAbd Allah ibn Masʿud gave judgment concerning a man who married a woman and then died before consummating the marriage and before specifying a dowry for her. He said: She is entitled to the full dowry, she must observe the waiting period, and she is entitled to inheritance. Maʿqil ibn Sinan said: I heard the Messenger of Allah ﷺ give judgment concerning Barwaʿ bint Washiq in that way."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2114,"lafz":true},{"key":"nasai","label":"النسائي","number":3356},{"key":"ibnmajah","label":"ابن ماجه","number":1891},{"key":"ibnhibban","label":"ابن حبان","number":4098}],"full":1,"dr":1,"rep":[12011]},{"num":6516,"demo":false,"sanad":"","matn":["عن عُرْوَةَ بن الزُّبَيْرِ يُحَدِّثُ أَنَّهُ سَأَلَ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا {وَإِنْ خِفْتُمْ أَنْ لاَ تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ} قَالَتْ هِيَ الْيَتِيمَةُ فِي حَجْرِ وَلِيِّهَا، فَيَرْغَبُ فِي جَمَالِهَا وَمَالِهَا، وَيُرِيدُ أَنْ يَتَزَوَّجَهَا بِأَدْنَى مِنْ سُنَّةِ نِسَائِهَا، فَنُهُوا عَنْ نِكَاحِهِنَّ، إِلاَّ أَنْ يُقْسِطُوا لَهُنَّ فِي إِكْمَالِ الصَّدَاقِ، وَأُمِرُوا بِنِكَاحِ مَنْ سِوَاهُنَّ مِنَ النِّسَاءِ.","قالت عائشة: ثم استفتى الناس رسول الله صلى الله عليه وسلم بعد: فأنزل الله عز وجل: ﴿وَيَسْتَفْتُونَكَ فِي النِّسَاءِ قُلِ اللَّهُ يُفْتِيكُمْ فِيهِنَّ﴾ [النساء:١٢٧] قالت: فبين الله في هذه أن اليتيمة إذ كانت ذات جمال ومال، ورغبوا في نكاحها، ولم يُلحقوها بسنتها بإكمال الصداق، فإذاً كانت مرغوبة عنها في قلة المال والجمال تركوها، والتمسوا غيرها من النساء. قال: فكما يتركونها حين يرغبون عنها، فليس لهم أن ينكحِوها إذا رغبوا فيها. إلا أن يُقسِطوا لها الأوفىَ من الصداق، ويُعطوها حقها."],"takhrij":"متفق عليه: رواه البخاري في الوصايا (2763) ومسلم في التفسير (6:3018) كلاهما من حديث الزهري، قال: أخبرني عروة بن الزبير، أنه سأل عائشة فأخبرته. واللفظ للبخاري، ولفظ مسلم نحوه.","grade":"متفق عليه","chapter_ar":"باب إن كان الولي هو الخاطب فعليه أن يعدل في الصداق","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2763) and Muslim (3018 no. 6). The wording is that of al-Bukhari.","chapter_en":"If the Guardian Himself Wishes to Marry Her, He Must Be Fair Regarding the Dowry","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":10,"content":{"translation":{"en":["ʿUrwah ibn al-Zubayr narrated that he asked ʿA’ishah about the verse: “And if you fear that you will not deal justly with the orphan girls, then marry those women who seem good to you” [al-Nisa’ 4:3]. She said: This refers to an orphan girl under the care of her guardian. He may be attracted to her beauty and wealth and want to marry her for less than the dowry normally given to women like her. So they were forbidden from marrying such girls unless they deal justly with them by giving them the full dowry, and they were instructed to marry other women besides them. ʿA’ishah said: Then the people sought a ruling from the Messenger of Allah ﷺ after that, so Allah the Mighty and Majestic revealed: “And they ask you for a ruling concerning women. Say: Allah gives you a ruling concerning them” [al-Nisa’ 4:127]. She said: Allah made clear in this verse that when the orphan girl possessed beauty and wealth, they desired to marry her, but they would not give her what women like her deserved in full dowry. Yet when she was not desired because of little wealth or beauty, they would leave her and seek other women instead. So just as they leave her when they have no desire for her, they have no right to marry her when they do desire her unless they are fully just with her in the dowry and give her her due."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2763,"lafz":true},{"key":"muslim","label":"مسلم","number":6}],"full":1},{"num":6517,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ جَاءَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَبِهِ أَثَرُ صُفْرَةٍ، فَسَأَلَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ أَنَّهُ تَزَوَّجَ. فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَمْ سُقت إِلَيْهَا؟. فَقَالَ: زِنَةَ نَوَاةٍ مِنْ ذَهَبٍ. فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أوْلِمْ وَلَوْ بِشَاةٍ."],"takhrij":"متفق عليه: رواه مالك في النكاح (47) عن حميد الطويل، عن أنس بن مالك، فذكره. ورواه البخاري في النكاح (5153) من طريق مالك، به. ورواه مسلم في النكاح (81:1427) من طريق شعبة، عن قتادة وحميد عن أنس، نحوه.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الوليمة بالشاة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (47), al-Bukhari (5153), and Muslim (1427 no. 81).","chapter_en":"What Has Been Related About Holding the Wedding Feast with a Sheep","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Malik narrated that ʿAbd al-Rahman ibn ʿAwf came to the Messenger of Allah ﷺ with a trace of yellow perfume on him. The Messenger of Allah ﷺ asked him, and he informed him that he had married. So the Messenger of Allah ﷺ said to him, “What did you give her?” He said: The weight of a date-stone of gold. The Messenger of Allah ﷺ said to him, “Give a wedding feast, even if only with one sheep.”"]},"buhuth":{"en":["His statement, “What did you bring to her?” means: What did you give as her dowry? The dowry was called “bringing” because the Arabs’ wealth was mostly livestock, so when a man married, he would bring camels or sheep to her as dowry.","In this hadith is a concession for the bridegroom to use yellow coloring from saffron and similar things."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":47,"lafz":true},{"key":"bukhari","label":"البخاري","number":5153},{"key":"muslim","label":"مسلم","number":81}],"full":1,"dr":1},{"num":6518,"demo":false,"sanad":"","matn":["عن عبدالرَّحْمَنِ بْنُ عَوْفٍ قال: لمَّا قَدِمْنَا المَدِينَةَ آخَى رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنِي وَبَيْنَ سَعْدِ بْنِ الرَّبِيعِ، فَقَالَ سَعْدُ بْنُ الرَّبِيعِ: إِنِّي أَكْثَرُ الْأَنْصَارِ مَالًا، فَأَقْسِمُ لَكَ نِصْفَ مَالِي، وَانْظُرْ أَيَّ زَوْجَتَيَّ هَوِيتَ، نَزَلْتُ لَكَ عَنْهَا، فَإِذَا حَلَّتْ تَزَوَّجْتَهَا، قَالَ: فَقَالَ لَهُ عَبْدُ الرَّحْمَنِ: لَا حَاجَةَ لِي فِي ذَلِكَ، هَلْ مِنْ سُوقٍ فِيهِ تِجَارَةٌ؟ قَالَ: سُوقُ قَيْنُقَاعٍ، قَالَ: فَغَدَا إِلَيْهِ عَبْدُ الرَّحْمَنِ، فَأَتَى بِأَقِطٍ وَسَمْنٍ، قَالَ: ثُمَّ تَابَعَ الْغُدُوَّ، فَمَا لَبِثَ أَنْ جَاءَ عَبْدُ الرَّحْمَنِ عَلَيْهِ أَثَرُ صُفْرَةٍ، فَقَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَزَوَّجْتَ؟ قَالَ: نَعَمْ قَالَ: وَمَنْ؟ قَالَ: امْرَأَةً مِنْ الْأَنْصَارِ. قَالَ: كَمْ سُقْتَ؟ قَالَ: زِنَةَ نَوَاةٍ مِنْ ذَهَبٍ أَوْ نَوَاةً مِنْ ذَهَبٍ. فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَوْلِمْ وَلَوْ بِشَاةٍ."],"takhrij":"صحيح: رواه البخاري في البيوع (2048) عن عبد العزيز بن عبد الله، حدثنا إبراهيم بن سعد، عن أبيه، عن جده قال: قال عبدالرحمن بن عوف: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الوليمة بالشاة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2048).","chapter_en":"What Has Been Related About Holding the Wedding Feast with a Sheep","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["ʿAbd al-Rahman ibn ʿAwf said: When we came to Madinah, the Messenger of Allah ﷺ established brotherhood between me and Saʿd ibn al-Rabiʿ. Saʿd ibn al-Rabiʿ said: I am one of the wealthiest of the Ansar, so I will divide my wealth in half for you, and look at whichever of my two wives you prefer, and I will part from her for you, and when her waiting period is over, you may marry her. ʿAbd al-Rahman said to him: I have no need of that. Is there a market where trade is conducted? He said: The market of Banu Qaynuqaʿ. He said: So ʿAbd al-Rahman went there in the morning and returned with dried curds and clarified butter. Then he kept going in the mornings, and before long ʿAbd al-Rahman came with a trace of yellow on him. The Messenger of Allah ﷺ said: “Have you married?” He said: Yes. He said: “Whom?” He said: A woman from the Ansar. He said: “How much did you give?” He said: The weight of a date-stone of gold, or a date-stone of gold. So the Prophet ﷺ said to him: “Give a wedding feast, even if only with one sheep.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2048,"lafz":true}],"full":1,"dr":1},{"num":6519,"demo":false,"sanad":"","matn":["عَنْ ثَابِتٍ، قَالَ ذُكِرَ تَزْوِيجُ زَيْنَبَ ابْنَةِ جَحْشٍ عِنْدَ أَنَسٍ فَقَالَ مَا رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوْلَمَ عَلَى أَحَدٍ مِنْ نِسَائِهِ مَا أَوْلَمَ عَلَيْهَا أَوْلَمَ بِشَاةٍ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5171) ومسلم في النكاح (90:1428) كلاهما من طريق حماد بن زيد، عن ثابت، به.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الوليمة بالشاة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5171) and Muslim (1428 no. 90). The wording is that of al-Bukhari.","chapter_en":"What Has Been Related About Holding the Wedding Feast with a Sheep","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Thabit said: The marriage of Zaynab bint Jahsh was mentioned in the presence of Anas, and he said: I did not see the Prophet ﷺ give a wedding feast for any of his wives as he did for her. He gave a feast with one sheep."]},"buhuth":{"en":["In the wording of Muslim: The Messenger of Allah ﷺ did not give a larger or better wedding feast for any of his wives than the one he gave for Zaynab. Thabit al-Bunani asked: With what did he give the feast? He said: He fed them bread and meat until they left it. Its detail in al-Bukhari (4793) is: The Prophet ﷺ consummated his marriage with Zaynab, and bread and meat were served. I went calling people to the food. A group would come, eat, and leave; then another group would come, eat, and leave. I continued inviting until I could no longer find anyone to invite. So I said: O Prophet of Allah, I cannot find anyone else to invite. He said: “Remove your food.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5171,"lafz":true},{"key":"muslim","label":"مسلم","number":90}],"full":1,"dr":1},{"num":6520,"demo":false,"sanad":"","matn":["عن صَفِيَّةَ بنت شَيْبَةَ قَالَتْ أَوْلَمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى بَعْضِ نِسَائِهِ بِمُدَّيْنِ مِنْ شَعِيرٍ."],"takhrij":"صحيح: رواه البخاري في النكاح (5172) عن محمد بن يوسف (هو الفريابي)، حدثنا سفيان، عن منصور بن صفية، عن أمه صفية بنت شيبة، فذكرته.","grade":"صحيح","chapter_ar":"باب من أولم بأقل من شاة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5172).","chapter_en":"One Who Gave a Wedding Feast with Less than a Sheep","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["Safiyyah bint Shaybah said: The Prophet ﷺ gave a wedding feast for one of his wives with two mudd measures of barley."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5172,"lafz":true}],"full":1,"dr":1},{"num":6521,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوْلَمَ عَلَى صَفِيَّةَ بِسَوِيقٍ وَتَمْرٍ."],"takhrij":"حسن: رواه أبو داود (3744) والترمذي (1095) وابن ماجة (1909) وصحّحه ابن حبان (4061) كلهم من حديث سفيان، عن وائل بن داود، عن ابنه بكر بن وائل، عن الزهري، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب من أولم بأقل من شاة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3744), al-Tirmidhi (1095), who graded it Hasan, Ibn Majah (1909), and authenticated by Ibn Hibban (4061).","chapter_en":"One Who Gave a Wedding Feast with Less than a Sheep","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["Anas narrated that the Prophet ﷺ held a wedding feast for Safiyyah with roasted flour and dates."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3744,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1095},{"key":"ibnmajah","label":"ابن ماجه","number":1909},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":4061},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1221,"n":1218}],"full":1,"dr":1},{"num":6522,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، تَزَوَّجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَفِيَّةَ وَجَعَلَ عِتْقَهَا صَدَاقَهَا، وَجَعَلَ الْوَلِيمَةَ ثَلَاثَةَ أَيَّامٍ، وَبَسَطَ نِطَعًا جَاءَتْ بِهِ أُمُّ سُلَيْمٍ، وَأَلْقَى عَلَيْهِ أَقِطًا وَتَمْرًا، وَأَطْعَمَ النَّاسَ ثَلَاثَةَ أَيَّامٍ."],"takhrij":"حسن: رواه أبو يعلى (3834) عن إبراهيم بن سعيد الجوهري، حدثنا أبو النضر، حدثنا أبو جعفر الرازي، عن حميد، عن أنس، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الوليمة أكثر من يوم","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Yaʿla (3834).","chapter_en":"What Has Been Related About the Wedding Feast Lasting More Than One Day","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Anas said: The Prophet ﷺ married Safiyyah, made her emancipation her dowry, and made the wedding feast last three days. Umm Sulaym brought a leather mat, which he spread out, and he placed dried curds and dates on it, and he fed the people for three days."]}},"tuhfa":{},"refs":[{"key":"sh12520","label":"أبو يعلى","number":3834,"lafz":true}],"full":1,"dr":1},{"num":6523,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ أَقَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ خَيْبَرَ وَالْمَدِينَةِ ثَلاَثًا يُبْنَى عَلَيْهِ بِصَفِيَّةَ بِنْتِ حُيَىٍّ فَدَعَوْتُ الْمُسْلِمِينَ إِلَى وَلِيمَتِهِ فَمَا كَانَ فِيهَا مِنْ خُبْزٍ وَلاَ لَحْمٍ، أُمِرَ بِالأَنْطَاعِ فَأَلْقَى فِيهَا مِنَ التَّمْرِ وَالأَقِطِ وَالسَّمْنِ فَكَانَتْ وَلِيمَتَهُ."],"takhrij":"صحيح: رواه البخاري في النكاح (5085) عن قتيبة، حدثنا إسماعيل بن جعفر، عن حميد، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الوليمة أكثر من يوم","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5085).","chapter_en":"What Has Been Related About the Wedding Feast Lasting More Than One Day","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Anas said: The Prophet ﷺ stayed between Khaybar and Madinah for three days while consummating his marriage to Safiyyah bint Huyayy. I invited the Muslims to his wedding feast. There was neither bread nor meat in it. He ordered that leather cloths be spread, then dates, dried curds, and clarified butter were placed on them, and that was his wedding feast."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5085,"lafz":true}],"full":1,"dr":1},{"num":6524,"demo":false,"sanad":"","matn":["عَنْ أنس بْنِ مَالِكٍ قَالَ: أعتق النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَفِيَّةَ بِنْتَ حيي سَيِّدِ قُرَيْظَةَ وَالنَّضِيرِ، وَتَزَوَّجَهَا فَأَصْبَحَ عَرُوسًا فَقَالَ: مَنْ كَانَ عِنْدَهُ شيء فليجيء بِهِ. قَالَ: وَبَسَطَ نِطْعاً قَالَ: فَجَعَلَ الرَّجُلُ يَجِيءُ بِالأَقِطِ، وَجَعَلَ الرَّجُلُ يَجِيءُ بِالتَّمْرِ، وَجَعَلَ الرَّجُلُ يَجِيءُ بِالسَّمْنِ فَحَاسُوا حَيْسًا. فَكَانَتْ وَلِيمَةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (371) ومسلم في النكاح (1365-84) كلاهما من حديث إسماعيل بن علية،حدثنا عبد العزيز بن صُهيب عن أنس فذكره في سياق طويل.","grade":"متفق عليه","chapter_ar":"باب التعاون في إقامة الوليمة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (371) and Muslim (1365 no. 84).","chapter_en":"Cooperation in Holding the Wedding Feast","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":4,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet ﷺ freed Safiyyah bint Huyayy, the chief lady of Qurayzah and al-Nadir, and married her. In the morning, when he was a bridegroom, he said, “Whoever has anything, let him bring it.” He spread out a leather mat, and one man brought dried curds, another brought dates, and another brought clarified butter, and they mixed it into hays. That was the wedding feast of the Messenger of Allah ﷺ."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":371,"lafz":true},{"key":"muslim","label":"مسلم","number":84},{"key":"muslim","label":"مسلم في النكاح","number":1365,"n":3497}],"full":1},{"num":6525,"demo":false,"sanad":"","matn":["عَنْ أنس قَالَ: بَنَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِامْرَأَةٍ، فَأَرْسَلَنِي فَدَعَوْتُ رِجَالاً إِلَى الطَّعَامِ."],"takhrij":"صحيح: رواه البخاري في النكاح (5170) عن مالك بن إسماعيل، حدثا زهير، عن بيان، قال: سمعت أنسا يقول: فذكره.","grade":"صحيح","chapter_ar":"باب وقت الوليمة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5170).","chapter_en":"The Time of the Wedding Feast","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":5,"content":{"translation":{"en":["Anas said: The Prophet ﷺ consummated marriage with a woman, then sent me, and I invited men to the food."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5170,"lafz":true}],"full":1,"dr":1},{"num":6526,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِذَا دُعِيَ أَحَدُكُمْ إِلَى الْوَلِيمَةِ فَلْيَأْتِهَا.","وفي لفظ: إذا دعي أحدكم إلى وليمة عُرس فليُجِبْ.","وفي آخر: إذا دعا أحدُكم أخاه فليُجِبْ عُرسا كان أو نحوه."],"takhrij":"متفق عليه: رواه مالك في النكاح (49) عن نافع، عن عبد الله بن عمر، فذكره. ورواه البخاري في النكاح (5173)، ومسلم في النكاح (96:1429) كلاهما من طريق مالك، به، مثله.","grade":"متفق عليه","chapter_ar":"باب إجابة الدعوة إلى وليمة العُرس","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (49), al-Bukhari (5173), and Muslim (1429 no. 96).","chapter_en":"Accepting the Invitation to the Wedding Feast","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ said, “If one of you is invited to a wedding feast, let him attend it.” In another wording: “If one of you is invited to a wedding feast, let him respond.” And in another: “When one of you invites his brother, let him accept, whether it is for a wedding or something similar.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":49},{"key":"bukhari","label":"البخاري","number":5173,"lafz":true},{"key":"muslim","label":"مسلم","number":96}],"full":1,"dr":1},{"num":6527,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا يَقُولُ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَجِيبُوا هَذِهِ الدَّعْوَةَ إِذَا دُعِيتُمْ لَهَا. قَالَ كَانَ عَبْدُ اللَّهِ يَأْتِي الدَّعْوَةَ فِي الْعُرْسِ وَغَيْرِ الْعُرْسِ وَهْوَ صَائِمٌ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5179)، ومسلم في النكاح (103:1429) كلاهما من طريق حجاج بن محمد، عن ابن جريج، أخبرني موسى بن عقبة، عن نافع قال: سمعت عبدالله بن عمر، فذكره.","grade":"متفق عليه","chapter_ar":"باب إجابة دعوة الوليمة لمن كان صائما","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5179) and Muslim (1429 no. 103).","chapter_en":"Responding to the Wedding Feast Invitation Even If One Is Fasting","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":7,"content":{"translation":{"en":["ʿAbd Allah ibn ʿUmar said: The Messenger of Allah ﷺ said, “Respond to this invitation when you are invited to it.” He said: ʿAbd Allah used to attend invitations, both for weddings and other than weddings, while fasting."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5179,"lafz":true},{"key":"muslim","label":"مسلم","number":103}],"full":1,"dr":1},{"num":6528,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ رَسُولُ الرَّجُلِ إِلَى الرَّجُلِ إِذْنُهُ."],"takhrij":"صحيح: رواه أبو داود (5189) والبخاري في الأدب المفرد (1076) كلاهما عن موسى بن إسماعيل، حدثنا حماد بن سلمة، عن حبيب وهشام، عن محمد، عن أبي هريرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب إجابة دعوة الوليمة لمن كان صائما","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (5189) and al-Bukhari in al-Adab al-Mufrad (1076).","chapter_en":"Responding to the Wedding Feast Invitation Even If One Is Fasting","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ: “A man’s messenger to another man is his permission.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":5189,"lafz":true},{"key":"adab","label":"البخاري في الأدب المفرد","number":1076}],"full":1,"dr":1,"rep":[14205]},{"num":6529,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّهُ كَانَ يَقُولُ شَرُّ الطَّعَامِ طَعَامُ الْوَلِيمَةِ يُدْعَى لَهَا الأَغْنِيَاءُ وَيُتْرَكُ الْمَسَاكِينُ وَمَنْ لَمْ يَأْتِ الدَّعْوَةَ فَقَدْ عَصَى اللَّهَ وَرَسُولَهُ."],"takhrij":"متفق عليه: رواه مالك في النكاح (50) عن ابن شهاب، عن الأعرج، عن أبي هريرة، فذكره. ورواه البخاري في النكاح (5177) ومسلم في النكاح (197:1432) كلاهما من طريق مالك، به، مثله.","grade":"متفق عليه","chapter_ar":"باب شرّ الطعام الذي يُدعى إليه الأغنياء دون الفقراء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (50), al-Bukhari (5177), and Muslim (1432 no. 197).","chapter_en":"The Worst Food Is the Wedding Feast to Which the Rich Are Invited While the Poor Are Left Out","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah used to say: “The worst food is the food of the wedding feast: the rich are invited to it, while the poor are left out. And whoever does not come to the invitation has disobeyed Allah and His Messenger.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":50,"lafz":true},{"key":"bukhari","label":"البخاري","number":5177},{"key":"muslim","label":"مسلم","number":197}],"full":1,"dr":1},{"num":6530,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ شَرُّ الطَّعَامِ طَعَامُ الْوَلِيمَةِ يُمْنَعُهَا مَنْ يَأْتِيهَا وَيُدْعَى إِلَيْهَا مَنْ يَأْبَاهَا وَمَنْ لَمْ يُجِبِ الدَّعْوَةَ فَقَدْ عَصَى اللَّهَ وَرَسُولَهُ."],"takhrij":"صحيح: رواه مسلم في النكاح (110:1432) عن ابن أبي عمر، حدثنا سفيان (هو ابن عيينة)، سمعت زياد بن سعد قال: سمعت ثابتاً الأعرج، يحدّث عن أبي هريرة، أن النبيصلى الله عليه وسلم قال (فذكره).","grade":"صحيح","chapter_ar":"باب شرّ الطعام الذي يُدعى إليه الأغنياء دون الفقراء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1432 no. 110).","chapter_en":"The Worst Food Is the Wedding Feast to Which the Rich Are Invited While the Poor Are Left Out","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said: “The worst food is the food of the wedding feast: the one who wants to come is prevented from it, and the one who refuses it is invited to it. And whoever does not answer the invitation has disobeyed Allah and His Messenger.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":110,"lafz":true}],"full":1,"dr":1},{"num":6531,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ أَبْصَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نِسَاءً وَصِبْيَانًا مُقْبِلِينَ مِنْ عُرْسٍ، فَقَامَ مُمْتَنًّا فَقَالَ اللَّهُمَّ أَنْتُمْ مِنْ أَحَبِّ النَّاسِ إِلَىَّ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5180) ومسلم في فضائل الصحابة (174:2508) من طريق عبد العزيز بن صهيب، عن أنس بن مالك، قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب دعوة النساء والصبيان إلى وليمة العُرس","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5180) and Muslim (2508 no. 174).","chapter_en":"Inviting Women and Children to the Wedding Feast","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet ﷺ saw women and children coming from a wedding, so he stood up in honor and said, “By Allah, you are among the most beloved people to me.”"]},"buhuth":{"en":["His statement, “he stood up in honor,” means out of esteem and graciousness. Whoever the Prophet ﷺ stood for and honored in this way was honored with something beyond compare."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5180,"lafz":true},{"key":"muslim","label":"مسلم","number":174}],"full":1,"dr":1},{"num":6532,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَسْعُودٍ الأنصاري قَالَ: جَاءَ رَجُلٌ مِنَ الأَنْصَارِ، يُكْنَى أَبَا شُعَيْبٍ فَقَالَ لِغُلاَمٍ لَهُ قَصَّابٍ – وَفِي رِوَايَةِ – لحّام، اجْعَلْ لِي طَعَامًا يَكْفِي خَمْسَةً، فَإِنِّي أُرِيدُ أَنْ أَدْعُوَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَامِسَ خَمْسَةٍ. فَإِنِّي قَدْ عَرَفْتُ فِي وَجْهِهِ الْجُوعَ، فَدَعَاهُمْ، فَجَاءَ مَعَهُمْ رَجُلٌ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ هَذَا قَدْ تَبِعَنَا، فَإِنْ شِئْتَ أَنْ تَأْذَنَ لَهُ، فأذِنَ لَهُ، وَإِنْ شِئْتَ أَنْ يَرْجِعَ رَجَعَ. فَقَالَ: لاَ، بَلْ قَدْ أَذِنْتُ لَهُ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2081) ومسلم في الأشربة (2036) كلاهما من حديث الأعمش، قال: حدثني شفيق، عن أبي مسعود الأنصار قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب فيمن جاء إلى الوليمة من غير دعوة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2081) and Muslim (2036).","chapter_en":"Concerning One Who Comes to the Wedding Feast Without an Invitation","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":10,"content":{"translation":{"en":["Abū Masʿūd al-Anṣārī reported: A man from the Anṣār known as Abū Shuʿayb said to a servant of his who was a butcher—and in another narration, a meat seller: “Prepare food for me sufficient for five people, for I wish to invite the Prophet ﷺ as one of five, because I have noticed hunger in his face.” He invited them, and another man came along with them. The Prophet ﷺ said: “This man has followed us. If you wish, you may give him permission to enter; and if you wish, he may return.” The host replied: “No, rather I give him permission.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2081,"lafz":true},{"key":"muslim","label":"مسلم","number":2036}],"full":1},{"num":6533,"demo":false,"sanad":"","matn":["عَنْ سَهْلٍ، قَالَ لَمَّا عَرَّسَ أَبُو أُسَيْدٍ السَّاعِدِيُّ دَعَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابَهُ، فَمَا صَنَعَ لَهُمْ طَعَامًا وَلاَ قَرَّبَهُ إِلَيْهِمْ إِلاَّ امْرَأَتُهُ أُمُّ أُسَيْدٍ، بَلَّتْ تَمَرَاتٍ فِي تَوْرٍ مِنْ حِجَارَةٍ مِنَ اللَّيْلِ، فَلَمَّا فَرَغَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الطَّعَامِ أَمَاثَتْهُ لَهُ فَسَقَتْهُ، تُتْحِفُهُ بِذَلِكَ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5182) ومسلم في الأشربة (87:2006) كلاهما من طريق سعيد بن أبي مريم، حدثنا محمد أبو غسان، حدثني أبو حازم، عن سهل قال:فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء من قيام العروس على خدمة المدعوين عند الضرورة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5182) and Muslim (2006/87).","chapter_en":"What Has Been Related About the Bride Serving the Invited Guests When Necessary","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":11,"content":{"translation":{"en":["Sahl reported: When Abū Usayd al-Sāʿidī got married, he invited the Prophet ﷺ and his Companions. No one prepared food for them or served it to them except his wife, Umm Usayd. She had soaked some dates overnight in a stone vessel. When the Prophet ﷺ finished eating, she dissolved and mixed them for him, then gave it to him to drink as a special offering."]},"buhuth":{"en":["The word “amāthathu” means that she dissolved or thoroughly mixed it.","The expression “tuḥtifuhu” means that she presented it to him as a special gift or offering."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5182,"lafz":true},{"key":"muslim","label":"مسلم","number":2006},{"key":"muslim","label":"مسلم في الاشربه","number":87}],"full":1,"dr":1,"rep":[7543]},{"num":6534,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ، أَنَّهُ صَنَعَ طَعَامًا، فَدَعَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَاءَ فَرَأَى فِي الْبَيْتِ سِتْرًا فِيهِ تَصَاوِيرُ، فَرَجَعَ، قَالَ: فَقُلْتُ: يَا رَسُولَ اللَّهِ مَا رَجَعَكَ بِأَبِي أَنْتَ وَأُمِّي؟ قَالَ: إِنَّ فِي الْبَيْتِ سِتْرًا فِيهِ تَصَاوِيرُ، وَإِنَّ الْمَلَائِكَةَ لَا تَدْخُلُ بَيْتًا فِيهِ تَصَاوِيرُ."],"takhrij":"صحيح: رواه النسائي (5351) واللفظ له، وابن ماجة (3359) وأبو يعلى (436) كلهم من حديث وكيع، عن هشام الدستوائي، عن قتادة، عن سعيد بن المسيب، عن علي فذكره، وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ترك حضور الوليمة التي فيها معصية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (5351), and this is his wording, also Ibn Majah (3359) and Abu Yaʿla (436).","chapter_en":"Refraining from Attending a Wedding Feast in Which There Is Disobedience","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["ʿAli said: I prepared food and invited the Prophet ﷺ. He came and entered, then saw a curtain with images on it and turned back. I said: O Messenger of Allah, what made you return? May my father and mother be sacrificed for you. He said, “There is a curtain in the house containing images, and the angels do not enter a house in which there are images.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":5351,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":3359},{"key":"sh12520","label":"أبو يعلى","number":436}],"full":1},{"num":6535,"demo":false,"sanad":"","matn":["حَدَّثَنَا سَفِينَةُ أَبُو عَبْدِ الرَّحْمَنِ، أَنَّ رَجُلاً، أَضَافَ عَلِيَّ بْنَ أَبِي طَالِبٍ فَصَنَعَ لَهُ طَعَامًا فَقَالَتْ فَاطِمَةُ لَوْ دَعَوْنَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَكَلَ مَعَنَا. فَدَعَوْهُ فَجَاءَ فَوَضَعَ يَدَهُ عَلَى عِضَادَتَىِ الْبَابِ فَرَأَى قِرَامًا فِي نَاحِيَةِ الْبَيْتِ فَرَجَعَ فَقَالَتْ فَاطِمَةُ لِعَلِيٍّ الْحَقْ فَقُلْ لَهُ مَا رَجَعَكَ يَا رَسُولَ اللَّهِ قَالَ إِنَّهُ لَيْسَ لِي أَنْ أَدْخُلَ بَيْتًا مُزَوَّقًا."],"takhrij":"حسن: رواه أبو داود (3755) وابن ماجة (3360) وصحّحه ابن حبان (6345) والحاكم (2/186) كلهم من حديث حماد بن سلمة، قال: حدثنا سعيد بن جمهان قال: حدثنا سفينة فذكره.","grade":"حسن","chapter_ar":"باب ترك حضور الوليمة التي فيها معصية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3755), Ibn Majah (3360), and authenticated by Ibn Hibban (6345) and al-Hakim (2/186).","chapter_en":"Refraining from Attending a Wedding Feast in Which There Is Disobedience","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Safinah Abu ʿAbd al-Rahman narrated that a man hosted ʿAli ibn Abi Talib and prepared food for him. Fatimah said: If only we would invite the Prophet ﷺ to eat with us. So they invited him, and he came. He placed his hand on the side-posts of the door, then saw a decorated curtain in one part of the house and turned back. Fatimah said to ʿAli: Go after him and ask him, O Messenger of Allah, what made you return? He said, “It is not for me to enter a decorated house.”"]},"buhuth":{"en":["Al-qiram means a patterned curtain, and al-muzawwaq means adorned or decorated."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3755,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":3360},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":6345},{"key":"hakim","label":"الحاكم","number":186}],"full":1,"dr":1},{"num":6536,"demo":false,"sanad":"","matn":["عَنْ مُحَمَّدِ بْنِ حَاطِبٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصْلُ مَا بَيْنَ الْحَلاَلِ وَالْحَرَامِ الدُّفُّ وَالصَّوْتُ فِي النِّكَاحِ."],"takhrij":"حسن: رواه الترمذي (1088) والنسائي (3369) وابن ماجة (1896) وصحّحه الحاكم (2/184) والبيهقي (7/289) كلهم من حديث أبي بلْج، عن محمد بن حاطب قال:فذكره.","grade":"حسن","chapter_ar":"باب الإعلان بالنكاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1088), who graded it Hasan, al-Nasa’i (3369), Ibn Majah (1896), and authenticated by al-Hakim (2/184).","chapter_en":"Publicizing the Marriage","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["Muhammad ibn Hatib said: The Messenger of Allah ﷺ said, “What distinguishes the lawful from the unlawful is the beating of the drum and the raising of the voice in marriage.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1088,"lafz":true},{"key":"nasai","label":"النسائي","number":3369,"n":3369},{"key":"ibnmajah","label":"ابن ماجه","number":1896},{"key":"hakim","label":"صحّحه الحاكم","number":184}],"full":1,"dr":1},{"num":6537,"demo":false,"sanad":"","matn":["عَنْ الرُّبَيع بنت معوذ بن عَفْرَاءَ قَالَتْ: جَاءَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَدَخَلَ حِينَ بُنِيَ عليّ، فَجَلَسَ عَلَى فِرَاشِي كَمَجْلِسِكَ مِنِّي. فَجَعَلَتْ جُوَيْرِيَاتٌ لَنَا يَضْرِبْنَ بِالدُّفِّ، ويندُبْنَ مَنْ قُتِلَ مِنْ آبَائِي يَوْمَ بَدْرٍ، إِذْ قَالَتْ إِحْدَاهُنَّ: وَفِينَا نَبِيٌّ يَعْلَمُ مَا فِي غَدٍ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: دَعِي هَذِهِ، وَقُولِي بِالَّذِي كنتِ تَقُولِينَ."],"takhrij":"صحيح: رواه البخاري في النكاح (5147) عن مسدد، حدثنا بشر بن المفضل، حدثنا خالد بن ذكوان، قال: قالت الربيع بنت معوذ فذكرته.","grade":"صحيح","chapter_ar":"باب يُستحبّ اللهو، وضرب الدف في الزفاف","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5147).","chapter_en":"Amusement and Beating the Duff at the Wedding Procession Are Recommended","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":14,"content":{"translation":{"en":["Al-Rubayyiʿ bint Muʿawwidh ibn ʿAfra’ said: The Prophet ﷺ came and entered when my marriage was consummated, and he sat on my bedding as you are sitting near me. Then some young girls of ours began beating the duff and singing elegies for those of my forefathers who had been killed at Badr, until one of them said: “And among us is a Prophet who knows what will happen tomorrow.” The Prophet ﷺ said, “Leave this and say what you were saying before.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5147,"lafz":true}],"full":1},{"num":6538,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّهَا زَفَّتِ امْرَأَةً إِلَى رَجُلٍ مِنَ الأَنْصَارِ فَقَالَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَا عَائِشَةُ مَا كَانَ مَعَكُمْ لَهْوٌ فَإِنَّ الأَنْصَارَ يُعْجِبُهُمُ اللَّهْوُ."],"takhrij":"صحيح: رواه البخاري في النكاح (5162) عن الفضل بن يعقوب، حدثنا محمد بن سابق، حدثنا إسرائيل، عن هشام بن عروة، عن أبيه، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب يُستحبّ اللهو، وضرب الدف في الزفاف","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5162).","chapter_en":"Amusement and Beating the Duff at the Wedding Procession Are Recommended","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":14,"content":{"translation":{"en":["ʿA’ishah narrated that she escorted a woman of the Ansar to her husband. The Prophet ﷺ said, “O ʿA’ishah, was there no amusement with you? For the Ansar are pleased by amusement.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5162,"lafz":true}],"full":1},{"num":6539,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: إن النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَمِعَ أُنَاسًا يُغنُّون فِي عُرْسٍ، وَهُمْ يَقُولُونَ: وَأَهْدَى لَهَا أَكْبُشًا تُبَحْبَحُ فِي الْمِرْبَدِ وَزَوْجُكِ فِي المنادي وَيَعْلَمُ مَا فِي غدِ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : لَا يَعْلَمُ مَا فِي غَدٍ إِلَّا اللَّهُ عَزَّ وَجَلَّ."],"takhrij":"حسن: رواه الطبراني في الصغير (343) والحاكم (2/175-186) وعنه البيهقي (7/289) من طريق إسماعيل بن أبي أويس، حدثني أبي، عن يحيى بن سعيد الأنصاري، عن عمرة، عن عائشة فذكرته. قال الحاكم: \"صحيح على شرط مسلم\".","grade":"حسن","chapter_ar":"باب يُستحبّ اللهو، وضرب الدف في الزفاف","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Saghir (343), al-Hakim (2/175–186), and al-Bayhaqi (7/289).","chapter_en":"Amusement and Beating the Duff at the Wedding Procession Are Recommended","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":14,"content":{"translation":{"en":["ʿA’ishah said: The Prophet ﷺ heard some people singing at a wedding, saying: “He gave her some rams, that frolic in the pen, and your husband is in the gathering, and knows what is in tomorrow.” So the Prophet ﷺ said, “No one knows what is in tomorrow except Allah, the Mighty and Majestic.”"]}},"tuhfa":{},"refs":[{"key":"sh13068","label":"الطبراني في الصغير","number":343,"lafz":true},{"key":"hakim","label":"الحاكم","number":186},{"key":"kubrabayhaqi","label":"البيهقي","number":289}],"full":1,"dr":1},{"num":6540,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِبَعْضِ الْمَدِينَةِ فَإِذَا هُوَ بِجَوَارٍ يَضْرِبْنَ بِدُفِّهِنَّ وَيَتَغَنَّيْنَ وَيَقُلْنَ نَحْنُ جَوَارٍ مِنْ بَنِي النَّجَّارِ يَا حَبَّذَا مُحَمَّدٌ مِنْ جَارِ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعْلَمُ اللَّهُ إِنِّي لأُحِبُّكُنَّ."],"takhrij":"حسن: رواه ابن ماجة (1899) عن هشام بن عمار قال: حدثنا عيسى بن يونس، قال: حدثنا عوف، عن ثمامة بن عبد الله، عن أنس بن مالك فذكره. وإسناده حسن من أجل ثمامة بن عبد الله فإنه حسن الحديث.","grade":"حسن","chapter_ar":"باب يُستحبّ اللهو، وضرب الدف في الزفاف","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (1899).","chapter_en":"Amusement and Beating the Duff at the Wedding Procession Are Recommended","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":14,"content":{"translation":{"en":["Anas ibn Malik narrated that the Prophet ﷺ passed by part of Madinah and saw some young girls beating their duffs, singing and saying: “We are girls of Banu al-Najjar, how wonderful Muhammad is as a neighbor.” So the Prophet ﷺ said, “Allah knows that I truly love you.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":1899,"lafz":true}],"full":1},{"num":6541,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِعَائِشَةَ: أَهَدَيْتُمُ الْجَارِيَةَ إِلَى بَيْتِهَا؟ قَالَتْ: نَعَمْ. قَالَ: فَهَلَّا بَعَثْتُمْ مَعَهُمْ مَنْ يُغَنِّيهِمْ يَقُولُ: أَتَيْنَاكُمْ أَتَيْنَاكُمْ فَحَيُّونَا نُحَيَّاكُمْ فَإِنَّ الْأَنْصَارَ قَوْمٌ فِيهِمْ غَزَلٌ."],"takhrij":"حسن: رواه أحمد (15209) والبزار – كشف الأستار (1432) كلاهما من حديث أجلح، عن أبي الزبير، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب يُستحبّ اللهو، وضرب الدف في الزفاف","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (15209) and al-Bazzar in Kashf al-Astar (1432).","chapter_en":"Amusement and Beating the Duff at the Wedding Procession Are Recommended","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":14,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said to ʿA’ishah, “Have you escorted the young bride to her home?” She said: Yes. He said, “Why did you not send with her some who would sing, saying: ‘We have come to you, we have come to you, so greet us and we will greet you, for the Ansar are a people among whom there is love poetry.’”"]}},"tuhfa":{},"refs":[{"key":"sh12862","label":"البزار - كشف الأستار","number":1432},{"key":"ahmad","label":"مسند الإمام أحمد","number":15209,"n":15209,"lafz":true}],"full":1,"dr":1},{"num":6542,"demo":false,"sanad":"","matn":["عن عَامِرِ بن سَعْدٍ البجلي يَقُولُ: شَهِدْتُ ثَابِتَ بْنَ وَدِيعَةَ وَقَرَظَةَ بْنَ كَعْبٍ الْأَنْصَارِيَّ فِي عُرْسٍ، وَإِذَا غِنَاءٌ، فَقُلْتُ لَهُمَا فِي ذَلِكَ، فَقَالَا: إِنَّهُ رُخِّصَ فِي الْغِنَاءِ فِي الْعُرْسِ وَالْبُكَاءِ عَلَى الْمَيِّتِ فِي غَيْرِ نِيَاحَةٍ."],"takhrij":"صحيح: رواه أبو داود الطيالسي (1317) ومن طريقه البيهقي (7/289) عن شعبة، عن أبي إسحاق، قال: سمعت عامر بن سعد البجلي، يقول: فذكر الحديث.","grade":"صحيح","chapter_ar":"باب يُستحبّ اللهو، وضرب الدف في الزفاف","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud al-Tayalisi (1317) and al-Bayhaqi (7/289).","chapter_en":"Amusement and Beating the Duff at the Wedding Procession Are Recommended","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":14,"content":{"translation":{"en":["ʿAmir ibn Saʿd al-Bajali said: I was present with Thabit ibn Wadiʿah and Qurzah ibn Kaʿb al-Ansari at a wedding, and there was singing. I spoke to them about that, and they said: Singing has been permitted at weddings, and weeping for the dead without wailing."]}},"tuhfa":{},"refs":[{"key":"tayalisi","label":"أبو داود الطيالسي","number":1317,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":289},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":14692,"n":14839}],"full":1,"dr":1},{"num":6543,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِيَّاكُمْ وَالدُّخُولَ عَلَى النِّسَاءِ. فَقَالَ رَجُلٌ مِنَ الأَنْصَارِ يَا رَسُولَ اللَّهِ أَفَرَأَيْتَ الْحَمْوَ. قَالَ الْحَمْوُ الْمَوْتُ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5232) ومسلم في السلام (2172) كلاهما عن قتيبة بن سعيد، حدثنا ليث، عن يزيد بن أبي حبيب، عن أبي الخير، عن عقبة بن عامر قال:فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في كراهية الدخول على المغيبات","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5232) and Muslim (2172).","chapter_en":"What Has Been Related About the Dislike of Entering Upon Women Whose Husbands Are Absent","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":15,"content":{"translation":{"en":["ʿUqbah ibn ʿAmir narrated that the Messenger of Allah ﷺ said, “Beware of entering upon women.” A man from the Ansar said: O Messenger of Allah, what about the in-law? He said, “The in-law is death.”"]},"buhuth":{"en":["Al-hamw means the husband’s male relatives other than his fathers and sons. Al-Nawawi said: What is meant here are the husband’s relatives other than his fathers and sons. As for fathers and sons, they are unmarriageable kin to the wife, and seclusion with them is permissible, so they are not described as “death.” Rather, what is meant is the brother, the brother’s son, the uncle, the uncle’s son, and the like among those who are not unmarriageable kin."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5232,"lafz":true},{"key":"muslim","label":"مسلم","number":2172}],"full":1,"dr":1,"rep":[6430]},{"num":6544,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَلاَ لاَ يَبِيتَنَّ رَجُلٌ عِنْدَ امْرَأَةٍ ثَيِّبٍ إِلاَّ أَنْ يَكُونَ نَاكِحًا أَوْ ذَا مَحْرَمٍ."],"takhrij":"صحيح: رواه مسلم في السلام (2171) من طريق هُشيم، عن أبي الزبير، عن جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في كراهية الدخول على المغيبات","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2171).","chapter_en":"What Has Been Related About the Dislike of Entering Upon Women Whose Husbands Are Absent","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":15,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said, “No man must spend the night with a previously married woman unless he is her husband or one who is a mahram to her.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2171,"lafz":true}],"full":1,"dr":1,"rep":[6432]},{"num":6545,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا مِنْكُمْ مِنْ أَحَدٍ إِلاَّ وَقَدْ وُكِّلَ بِهِ قَرِينُهُ مِنَ الْجِنِّ.","قالوا: وإياك يا رسول الله قال: وإياي إلا أن الله أعانني عليه فأسلم فلا يأمرني إلا بخير."],"takhrij":"صحيح: رواه مسلم في صفة القيامة (2814) من طرق عن جرير، عن منصور، عن سالم بن أبي الجعد، عن أبيه، عن عبد الله بن مسعود فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في كراهية الدخول على المغيبات","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2814).","chapter_en":"What Has Been Related About the Dislike of Entering Upon Women Whose Husbands Are Absent","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":15,"content":{"translation":{"en":["ʿAbd Allah ibn Masʿud said: The Messenger of Allah ﷺ said, “There is none among you except that his companion from among the jinn has been assigned to him.” They said: Even you, O Messenger of Allah? He said, “Even me, except that Allah helped me against him and he accepted Islam, so he does not command me except with good.”"]},"buhuth":{"en":["His statement, “he accepted Islam,” is understood by the majority of scholars literally as Islam, not merely safety. Sufyan ibn ʿUyaynah explained it as “I am safe from him,” meaning the Prophet ﷺ was protected from Satan flowing through him like blood, and no one shares that with him."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2814,"lafz":true}],"full":1,"dr":1,"rep":[8233,13825]},{"num":6546,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ يَقُولُ سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ يَقُولُ لاَ يَخْلُوَنَّ رَجُلٌ بِامْرَأَةٍ إِلاَّ وَمَعَهَا ذُو مَحْرَمٍ."],"takhrij":"متفق عليه: رواه مسلم في الحج (1341) والبخاري في الجهاد (3006) كلاهما من حديث سفيان بن عيينة، حدثنا عمرو بن دينار، عن أبي معبد، قال: سمعت ابن عباس يقول: فذكره في حديث أطول من هذا، واللفظ لمسلم، ولفظ البخاري نحوه.","grade":"متفق عليه","chapter_ar":"باب ما جاء في كراهية الدخول على المغيبات","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (1341) and al-Bukhari (3006), and the wording is that of Muslim.","chapter_en":"What Has Been Related About the Dislike of Entering Upon Women Whose Husbands Are Absent","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":15,"content":{"translation":{"en":["Ibn ʿAbbas said: I heard the Prophet ﷺ say, “No man should be alone with a woman unless she has with her a mahram.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1341,"lafz":true},{"key":"bukhari","label":"البخاري","number":3006}],"full":1},{"num":6547,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن عمرو بْنِ الْعَاصِ حَدَّثَهُ أَنَّ نَفَرًا مِنْ بَنِي هَاشِمٍ دَخَلُوا عَلَى أَسْمَاءَ بِنْتِ عُمَيْسٍ فَدَخَلَ أَبُو بَكْرٍ الصِّدِّيقُ وَهِيَ تَحْتَهُ يَوْمَئِذٍ فَرَآهُمْ فَكَرِهَ ذَلِكَ فَذَكَرَ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَالَ لَمْ أَرَ إِلاَّ خَيْرًا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ اللَّهَ قَدْ بَرَّأَهَا مِنْ ذَلِكَ. ثُمَّ قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْمِنْبَرِ فَقَالَ لاَ يَدْخُلَنَّ رَجُلٌ بَعْدَ يَوْمِي هَذَا عَلَى مُغِيبَةٍ إِلاَّ وَمَعَهُ رَجُلٌ أَوِ اثْنَانِ."],"takhrij":"صحيح: رواه مسلم في السلام (2173) من طرق عن عمرو بن الحارث أن بكر بن سوادة حدّثه، أن عبد الرحمن بن جبير حدثه أن عبد الله بن عمرو بن العاص حدثه فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في كراهية الدخول على المغيبات","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2173).","chapter_en":"What Has Been Related About the Dislike of Entering Upon Women Whose Husbands Are Absent","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":15,"content":{"translation":{"en":["ʿAbd Allah ibn ʿAmr ibn al-ʿAs narrated that a group from Banu Hashim entered upon Asma’ bint ʿUmays. Then Abu Bakr al-Siddiq entered, and she was his wife at that time, and he saw them and disliked that. He mentioned that to the Prophet ﷺ and said: I saw nothing but good. So the Messenger of Allah ﷺ said, “Allah has declared her free of that.” Then the Messenger of Allah ﷺ stood upon the pulpit and said, “No man is to enter upon a woman whose husband is absent after this day unless he is accompanied by one or two men.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2173,"lafz":true}],"full":1,"rep":[6431]},{"num":6548,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَيُّمَا امْرَأَةٍ نُكِحَتْ عَلَى صَدَاقٍ أَوْ حِبَاءٍ أَوْ عِدَةٍ قَبْلَ عِصْمَةِ النِّكَاحِ فَهُوَ لَهَا وَمَا كَانَ بَعْدَ عِصْمَةِ النِّكَاحِ فَهُوَ لِمَنْ أُعْطِيَهُ وَأَحَقُّ مَا أُكْرِمَ عَلَيْهِ الرَّجُلُ ابْنَتُهُ أَوْ أُخْتُهُ."],"takhrij":"حسن: رواه أبو داود (2129) وابن ماجة (1955) والنسائي (3353) وأحمد (6709) كلهم من حديث ابن جريج، قال: قال عمرو بن شعيب، عن أبيه، عن جده، فذكره.","grade":"حسن","chapter_ar":"باب أن أحقَّ ما أُكرم عليه الرجلُ ابنتُه أو أختُه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2129), Ibn Majah (1955), al-Nasa’i (3353), and Ahmad (6709).","chapter_en":"The One Most Deserving That a Man Be Honored Through Is His Daughter or His Sister","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":16,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb, from his father, from his grandfather, said: The Messenger of Allah ﷺ said, “Any woman who is married upon a dowry, or a gift, or a promise before the marriage bond is concluded, then it belongs to her. Whatever is given after the marriage bond is concluded belongs to the one to whom it is given. And the one most deserving that a man be honored through is his daughter or his sister.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2129,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":1955},{"key":"nasai","label":"النسائي","number":3353,"n":3353},{"key":"ahmad","label":"مسند الإمام أحمد","number":6709,"n":6709}],"full":1,"dr":1},{"num":6549,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ، قَالَ: جَهَّزَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاطِمَةَ فِي خَمِيلٍ، وَقِرْبَةٍ، وَوِسَادَةِ أَدَمٍ حَشْوُهَا لِيفُ الْإِذْخِرِ."],"takhrij":"صحيح: رواه النسائي (3384) وأحمد (643) كلاهما من حديث أبي أسامة، عن زائدة بن قدامة، عن عطاء بن السائب، عن أبيه، عن علي فذكره.","grade":"صحيح","chapter_ar":"باب جهاز الرجل ابنته","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3384) and Ahmad (643).","chapter_en":"A Man Preparing His Daughter’s Marriage Outfit","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":17,"content":{"translation":{"en":["ʿAli said: The Messenger of Allah ﷺ prepared Fatimah with a velvet cloth, a waterskin, and a leather pillow stuffed with fibers of idhkhir grass."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3384,"lafz":true,"n":3384},{"key":"ahmad","label":"مسند الإمام أحمد","number":643,"n":643}],"full":1,"dr":1,"rep":[9425]},{"num":6550,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَلْ لَكُمْ مِنْ أَنْمَاطٍ. قُلْتُ وَأَنَّى يَكُونُ لَنَا الأَنْمَاطُ قَالَ أَمَا إِنَّهُ سَيَكُونُ لَكُمُ الأَنْمَاطُ.","قال جابر: فأنا أقول لها -يعني امرأته- أخِّري عني أنماطكِ، فتقول: ألم يقل النبي صلى الله عليه وسلم: إنها ستكونُ لكم الأنماط؟ فأدعُها."],"takhrij":"متفق عليه: رواه البخاري في المناقب (3631) ومسلم في اللباس (2083) كلاهما من حديث عبد الرحمن بن مهدي، حدثنا سفيان، عن محمد بن المنكدر، عن جابر فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب اتخاذ الأنماط ونحوها للعروس عند البناء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3631) and Muslim (2083), and the wording is that of al-Bukhari.","chapter_en":"Using Carpets and Similar Things for the Bride at the Time of Consummation","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":18,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said to me, “Do you have carpets?” I said: How could we have carpets? He said, “But you will indeed have carpets.” Jabir said: So I say to her — meaning his wife — “Keep your carpets away from me,” and she says: Did not the Prophet ﷺ say, “You will indeed have carpets”? So I leave her alone."]},"buhuth":{"en":["Al-anmat are a kind of carpet or mat with a thin layer, generally used on the wedding night and the nights after it to receive the bride."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3631,"lafz":true},{"key":"muslim","label":"مسلم","number":2083}],"full":1,"dr":1},{"num":6551,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْسَ مِنَّا مَنْ خَبَّبَ امْرَأَةً عَلَى زَوْجِهَا أَوْ عَبْدًا عَلَى سَيِّدِهِ."],"takhrij":"صحيح: رواه أبو داود (2175) وأحمد (9157) وصحّحه ابن حبان (5560،568) والحاكم (2/196) والبيهقي (8/13) كلهم من طريق عمار بن رزيق، عن عبد الله بن عيسى، عن عكرمة، عن يحيى بن يعمر، عن أبي هريرة فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب فيمن أفسد امرأة على زوجها","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2175), Ahmad (9157), and authenticated by Ibn Hibban (5560, 568) and al-Hakim (2/196).","chapter_en":"Concerning One Who Corrupts a Woman Against Her Husband","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ said, “He is not one of us who turns a woman against her husband, or a slave against his master.”"]},"buhuth":{"en":["His saying, “turns against,” means: corrupts and deceives. In some other narrations, the wording “corrupts” is used."]},"intro_kitab":{"ar":["بتميّزُ الإسلامُ في جميع شؤون الحياة بمميزاتٍ كثيرةٍ منها:","مشروعية الطلاق: فإنّ الأديانَ السابقةَ على الإسلام لا تعرِفُ الطلاقَ، بل إذا تزوّجَ الرجُلُ بامرأةٍ فعليهما أن يعيشا حياةً أبديةً، لا رجعةً فيها، ولو كانت الحياةُ فيها شقاوةٌ وبؤسّ، فإنهم كانوا يقولون: مَنْ ارتبطَ في الأرض فكأنها ارتبطَ في السماء .","فجاء الإسلامُ، وألْغَى هذه الأغلالَ ليتحرّر كلُّ من الزوجين عن الآخر إذا كانت الحياةُ لا ستقيمُ، فيبدأ كلِّ منهما حياةً جديدةً، وقد انتقدَ كثيرٌ من الباحثين غير المسلمين مشروعية الطلاق في الإسلام، لأنهم لم يعرفوا مقاصد الشريعة في مشروعية الطلاق، ثم إنّ الطلاق في الإسلام ليس بأمرٍ سهل كما يتصوّره البعض إلا أن تصرّف بعض الناس أساء إلى مشروعية الطلاق.","في الأسطر القادمة أوضَحُ لكم أن الطلاق لم يُشرع في الإسلام إلا في ظروفٍ معيّنةٍ ضيّقةٍ، ليس للزّوج مخرَجٌ منها إلا بالطلاق، فمن المعلوم أن عقد النكاح يتمَّ بالإيجاب والقبول مع الصداق والشاهدين، بخلاف الطلاق الشرعي فله عدّةُ مراحل، لَوْ لُوْحِظَتْ لقلَّما يقعُ الطلاقُ بين الزوجين، ومن هذه المراحل:","إنّ المفارقة بين الزوجين لا تكون بطلاقٍ واحدٍ، بل لا بد أن يطلق مرّتين، ثم لا تَبِيْنُ المرأةُ على الزوج حتى يطلّقَها الطلاقَ الثالثَ.","ومن شروط الطلاق أن يطلّق الزوج في طهر لم يجامع فيه، ويطلّق طلاقًا واحدًا رجعيًّا، وتبقى المرأة في بيت زوجها، ولا يجوز إخراجها منه، ثم على المرأة أيضًا أن لا تخرج إلى بيت أهلها، بل تبقى في بيت زوجها حتى تنقضي عدتها. قال تعالى: ﴿يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا الْعِدَّةَ وَاتَّقُوا اللَّهَ رَبَّكُمْ لَا تُخْرِجُوهُنَّ مِنْ بُيُوتِهِنَّ وَلَا يَخْرُجْنَ﴾ [الطلاق: ١].","في قضاء العدة في بيت الزوج حكمةً من الله تعالى، وهي أن يشعر الإنسان بخطئه، أو يتصالحان على نزاعهما، فيرجع عنه الزوجُ قبل انقضاء العدة، ولا يُقدِم على الطلاق الثاني.","إنْ أدركَ الزوجُ أنه إنْ طلَّقَ الطلاقَ الثالثَ، فالزوجةُ تبِيْنُ منه، ولا تحلُّ له حتى تنكحَ زوجًا آَخْرُ إنّ أرادَ الرجوعَ، فغيرتُه قد تمنعُ من إيقاع الطلاق الثالث، فيرجع قبل انقضاء العدة في الطلاق الثاني، وله أن يتزوّج بعد العدّة بنكاحِ جديدٍ وبمهر جديدٍ.","إذا كان للزوجين مولودٌ، فالغالب أنه يكون حِصنًا منيعًا من مفارقة الأبوين.","ومن أهم مراحل الطلاق إذا وقع الخصام بين الزوجين، فأمر الله تعالى بالإصلاح في قوله: ﴿وَإِنْ خِفْتُمْ شِقَاقَ بَيْنِهِمَا فَابْعَثُوا حَكَمًا مِنْ أَهْلِهِ وَحَكَمًا مِنْ أَهْلِهَا إِنْ يُرِيدَا إِصْلَاحًا يُوَفِّقِ اللَّهُ بَيْنَهُمَا إِنَّ اللَّهَ كَانَ عَلِيمًا خَبِيرًا﴾ [النساء: ٣٥].","من الخطأ الذي يقع في الطلاق أن المرأة إذا طلقت تطليقة واحدة، تخرج من بيت زوجها إلى أهلها، ونساءُ أهلها يُنفّرنَ من الزوج، ويُقبّحن العمل الذي وقعَ منه، فلم يتمكّن الزوجُ من الرجوع عن طلاقه الأول لعدم وجود المرأة في بيته مما يزيده تنافرًا.","ومن الخطأ الشائع أيضا أن الزوج يطلّقها ثلاثا دفعةً واحدةً، ويُفَوِّت الفرصةَ للرجوع عن طلاقه فهو مخالفٌ لأمرين من أمر الله تعالى:","أولاً: أنه طلّق ثلاث تطليقات مرة واحدة، والله تعالى يقول: ﴿الطَّلَاقُ مَرَّتَانِ﴾ [البقرة: ٢٢٩].","ثانيا: أنه فوّتَ البقاء مع زوجها بعد طلاقه الأول.","ولا شك لو طُبّقت هذه الشروط لقلّما يقعُ الطلاق بين الزوجين. والله الموفق"],"en":["Islam is distinguished in all areas of life by many unique features, among them:","The lawfulness of divorce: the religions before Islam did not recognize divorce. Rather, if a man married a woman, they were expected to live together permanently with no return, even if that life was full of misery and hardship. They used to say: whoever is joined on earth is as though joined in heaven.","Then Islam came and removed these shackles, so that each spouse may be freed from the other if the marriage cannot continue, and each may begin a new life. Many non-Muslim researchers criticized the lawfulness of divorce in Islam because they did not understand the objectives of the Sacred Law in permitting divorce. Also, divorce in Islam is not something easy as some imagine, although some people’s conduct has harmed the proper understanding of its lawfulness.","In the coming lines, I will explain that divorce was only legislated in Islam in certain narrow circumstances in which the husband has no way out except divorce. It is known that the marriage contract is concluded by offer and acceptance along with the dowry and two witnesses. By contrast, a valid Islamic divorce has several stages, which, if observed, would make divorce between spouses very rare. Among these stages are:","Separation between spouses is not finalized with a single divorce. Rather, he must divorce twice, and the woman does not become fully separated from her husband until he gives the third divorce.","Among the conditions of divorce is that the husband divorce her in a state of purity in which he has not had intercourse with her, and that he give only one revocable divorce. The woman remains in her husband’s house, and it is not permissible to turn her out of it. Likewise, the woman should not leave to her family’s home, but remain in her husband’s home until her waiting period ends. Allah the Exalted said: “O Prophet, when you divorce women, divorce them for their waiting period, and count the waiting period, and fear Allah your Lord. Do not turn them out of their houses, nor should they leave…” [Surat al-Talaq: 1]","In completing the waiting period in the husband’s home, there is wisdom from Allah the Exalted: a person may realize his mistake, or the two may reconcile in their dispute, so the husband takes her back before the waiting period ends and does not proceed to the second divorce.","If the husband realizes that, should he pronounce the third divorce, the wife will become fully separated from him and will not be lawful for him until she marries another husband if he wants her back, then his jealousy may prevent him from issuing the third divorce. So he may take her back before the waiting period ends after the second divorce. After the waiting period, he may also remarry her through a new marriage contract and a new dowry.","If the couple have a child, that usually becomes a strong barrier against the parents separating.","Among the most important stages regarding divorce is when conflict occurs between the spouses. Allah the Exalted commanded reconciliation in His statement: “And if you fear a breach between them, appoint an arbitrator from his family and an arbitrator from her family. If they both desire reconciliation, Allah will cause harmony between them. Indeed, Allah is Knowing and Aware.” [Surat al-Nisa’: 35]","One mistake that occurs in divorce is that when a woman is given one divorce, she leaves her husband’s house and goes to her family, and the women of her family turn her away from her husband and make his action seem worse, so the husband is unable to take back his first divorce because the woman is no longer in his house, and this only increases estrangement.","Another common mistake is that the husband divorces her three times at once and loses the opportunity to take her back. In doing so, he opposes two commands of Allah the Exalted:","First: he pronounced three divorces in one sitting, while Allah the Exalted says: “Divorce is twice.”","Second: he lost the opportunity of remaining with his wife after the first divorce.","Without doubt, if these conditions were applied, divorce between spouses would rarely occur. And Allah is the Granter of success."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2175,"lafz":true},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":568},{"key":"ahmad","label":"مسند الإمام أحمد","number":9157,"n":9157},{"key":"hakim","label":"المستدرك على الصحيحين","number":2795,"n":2781},{"key":"ibnhibban","label":"ابن حبان","number":5560}],"full":1,"dr":1,"rep":[14019]},{"num":6552,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ، عَنْ أَبِيهِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَيْسَ مِنَّا مَنْ حَلَفَ بِالْأَمَانَةِ، وَمَنْ خَبَّبَ عَلَى امْرِئٍ زَوْجَتَهُ أَوْ مَمْلُوكَهُ."],"takhrij":"صحيح: رواه أبو داود (3253) وأحمد (22980) وصحّحه ابن حبان (4363) والحاكم (4/298) والبيهقي (10/30) كلهم من حديث الوليد بن ثعلبة الطائي، عن عبدالله بن بريدة، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب فيمن أفسد امرأة على زوجها","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3253), Ahmad (22980), and authenticated by Ibn Hibban (4363) and al-Hakim (4/298).","chapter_en":"Concerning One Who Corrupts a Woman Against Her Husband","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Buraydah ibn al-Husayb said: The Messenger of Allah ﷺ said, “He is not one of us who swears by trust, or who turns a man’s wife or slave against him.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"ابو داود","number":3253,"lafz":true},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":4363},{"key":"hakim","label":"الحاكم","number":298},{"key":"ahmad","label":"مسند الإمام أحمد","number":22980,"n":22980}],"full":1,"dr":1},{"num":6553,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ قَالَ: كَانَتْ تَحْتِي امْرَأَةٌ، وَكُنْتُ أُحِبُّهَا، وَكَانَ عُمَرُ يَكْرَهُهَا، فَقَالَ لِي: طلِّقْهـا، فَأَبَيْتُ، فَأَتَى عُمَرُ رسول اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ ذَلِكَ لَهُ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: طلِّقها.","وفي رواية: أطعْ أباك."],"takhrij":"حسن: رواه أبو داود (5138)، والترمذي (1189)، وابن ماجة (2088)، وأحمد (4711) وصحّحه ابن حبان (426)، والحاكم (2/197، 4/152) كلهم من حديث ابن أبي ذئب، عن خاله الحارث بن عبدالرحمن، عن حمزة بن عبدالله، عن عبدالله بن عمر فذكره.","grade":"حسن","chapter_ar":"باب طلاق المرء امرأته بأمر أبيه إذا لم يكن فيه مفسدة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (5138), al-Tirmidhi (1189), Ibn Majah (2088), and Ahmad (4711). Al-Tirmidhi said: Hasan Sahih.","chapter_en":"A Man Divorcing His Wife at His Father’s Command If There Is No Harm in It","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["ʿAbd Allah ibn ʿUmar said: I had a wife whom I loved, but ʿUmar disliked her. He told me, “Divorce her,” but I refused. Then ʿUmar came to the Messenger of Allah ﷺ and mentioned that to him. The Prophet ﷺ said, “Divorce her.” In another narration: “Obey your father.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":5138,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1189},{"key":"ibnmajah","label":"ابن ماجه","number":2088},{"key":"ahmad","label":"مسند الإمام أحمد","number":4711,"n":4711},{"key":"ibnhibban","label":"ابن حبان","number":426}],"full":1,"dr":1},{"num":6554,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ، أَنَّ رَجُلاً، أَتَاهُ فَقَالَ إِنَّ لِي امْرَأَةً وَإِنَّ أُمِّي تَأْمُرُنِي بِطَلاَقِهَا.","قال أبو الدرداء: سمعت رسول الله صلى الله عليه وسلم يقول: الوالد أوسط أبواب الجنة، فإن شئت فأضِعْ ذلك البابَ، أو احفظْه."],"takhrij":"صحيح: رواه الترمذي (1900) وأحمد (27511) والحاكم (4/152) كلهم من طريق سفيان بن عيينة، عن عطاء بن السائب، عن أبي عبد الرحمن السلمي عن أبي الدرداء فذكره.","grade":"صحيح","chapter_ar":"باب طلاق المرء امرأته بأمر أبيه إذا لم يكن فيه مفسدة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1900), Ahmad (27511), and al-Hakim (4/152). Al-Tirmidhi said: “This is an authentic hadith.”","chapter_en":"A Man Divorcing His Wife at His Father’s Command If There Is No Harm in It","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Abu al-Darda’ narrated that a man came to him and said: I have a wife, and my mother commands me to divorce her. Abu al-Darda’ said: I heard the Messenger of Allah ﷺ say, “The parent is the middle gate of Paradise, so if you wish, neglect that gate, or preserve it.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1900,"lafz":true},{"key":"hakim","label":"الحاكم","number":152},{"key":"ahmad","label":"مسند الإمام أحمد","number":27511,"n":27511}],"full":1,"dr":1,"rep":[14030]},{"num":6555,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ إِبْلِيسَ يَضَعُ عَرْشَهُ عَلَى الْمَاءِ ثُمَّ يَبْعَثُ سَرَايَاهُ فَأَدْنَاهُمْ مِنْهُ مَنْزِلَةً أَعْظَمُهُمْ فِتْنَةً يَجِيءُ أَحَدُهُمْ فَيَقُولُ فَعَلْتُ كَذَا وَكَذَا فَيَقُولُ مَا صَنَعْتَ شَيْئًا قَالَ ثُمَّ يَجِيءُ أَحَدُهُمْ فَيَقُولُ مَا تَرَكْتُهُ حَتَّى فَرَّقْتُ بَيْنَهُ وَبَيْنَ امْرَأَتِهِ - قَالَ - فَيُدْنِيهِ مِنْهُ وَيَقُولُ نِعْمَ أَنْتَ."],"takhrij":"صحيح: رواه مسلم في صفة القيامة (2812/67) من طرق عن أبي معاوية، حدثنا الأعمش، عن أبي سفيان، عن جابر، فذكره.","grade":"صحيح","chapter_ar":"باب من أعظم فتنة الشيطان التفريق بين المرء وزوجه","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2812 no. 67).","chapter_en":"One of Satan’s Greatest Trials Is Causing Separation Between a Man and His Wife","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said, “Iblis places his throne upon the water, then sends out his detachments. The closest of them to him in rank is the one who causes the greatest trial. One of them comes and says: I did such-and-such. He says: You have done nothing. Then another comes and says: I did not leave him until I separated him from his wife. Then he draws him near and says: You are excellent.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":67,"lafz":true}],"full":1},{"num":6556,"demo":false,"sanad":"","matn":["عَنْ نَافِعٍ، عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ طَلَّقَ امْرَأَتَهُ وَهْىَ حَائِضٌ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَ عُمَرُ بْنُ الْخَطَّابِ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُرْهُ فَلْيُرَاجِعْهَا، ثُمَّ لِيُمْسِكْهَا حَتَّى تَطْهُرَ ثُمَّ تَحِيضَ، ثُمَّ تَطْهُرَ، ثُمَّ إِنْ شَاءَ أَمْسَكَ بَعْدُ وَإِنْ شَاءَ طَلَّقَ قَبْلَ أَنْ يَمَسَّ، فَتِلْكَ الْعِدَّةُ الَّتِي أَمَرَ اللَّهُ أَنْ تُطَلَّقَ لَهَا النِّسَاءُ."],"takhrij":"متفق عليه: رواه مالك في الطلاق (53) عن نافع، به.","grade":"متفق عليه","chapter_ar":"باب طلاق السنة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (53), al-Bukhari (5251), and Muslim (1471 no. 1).","chapter_en":"Divorce According to the Sunnah","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Nafiʿ narrated that ʿAbd Allah ibn ʿUmar divorced his wife while she was menstruating during the time of the Messenger of Allah ﷺ. So ʿUmar ibn al-Khattab asked the Messenger of Allah ﷺ about that. The Messenger of Allah ﷺ said, “Command him to take her back, then keep her until she becomes pure, then menstruates, then becomes pure. Then if he wishes, he may keep her after that, or if he wishes, he may divorce her before touching her. That is the waiting period for which Allah commanded that women be divorced.”"]},"buhuth":{"en":["Muslim also narrated it through another route from Ibn ʿUmar, who said: I divorced my wife during the time of the Messenger of Allah ﷺ while she was menstruating. ʿUmar mentioned that to the Messenger of Allah ﷺ, and he said: “Command him to take her back, then let her remain until she becomes pure, then menstruates another menstruation. Then when she becomes pure, let him divorce her before having relations with her, or keep her, for that is the waiting period for which Allah commanded that women be divorced.”"]},"intro":{"ar":["قال الله تعالى: ﴿يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ﴾ [الطلاق: ١].","أي إذا أردتم تطليق النساء فطلقوهن مستقبلات العدة. والمطلقة تستقبل العدة إذا طلقت بعد أن تطهر من الحيض والنفاس قبل أن يمسها زوجها. وقيل: إن الحكمة في منع الطلاق في الحيض أو النفاس تطويل العدة، إن كانت الأقراء هي الأطهار. واللفظ الوارد في حديث عبد الله بن عمر جاء على أوجه:","الوجه الأول: “ثم يمسكها حتى تطهر، ثم تحيض، ثم تطهر، ثم إن شاء أمسك وإن شاء طلق قبل أن يمسها”.","ممن رواه عن عبد الله بن عمر الوجه الأول:"],"en":["Allah the Exalted said: “O Prophet, when you divorce women, divorce them for their waiting period” [Surat al-Talaq: 1]","Meaning: if you intend to divorce women, then divorce them at a time when they are beginning their waiting period. A divorced woman begins her waiting period properly if she is divorced after becoming pure from menstruation or postnatal bleeding and before her husband has relations with her. It is also said that the wisdom behind forbidding divorce during menstruation or postnatal bleeding is to prevent lengthening the waiting period, if the periods are counted as states of purity. The wording reported in the hadith of ʿAbd Allah ibn ʿUmar came in different forms:","First wording: “Then he should keep her until she becomes pure, then menstruates, then becomes pure, then if he wishes he may keep her, and if he wishes he may divorce her before touching her.”","Among those who narrated this first wording from ʿAbd Allah ibn ʿUmar:"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":53,"lafz":true},{"key":"bukhari","label":"البخاري","number":5251},{"key":"muslim","label":"مسلم","number":1}],"full":1,"dr":1},{"num":6557,"demo":false,"sanad":"","matn":["عن سالم بن عَبْدِ اللَّهِ أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ، قَالَ طَلَّقْتُ امْرَأَتِي وَهْىَ حَائِضٌ فَذَكَرَ ذَلِكَ عُمَرُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَتَغَيَّظَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ قَالَ مُرْهُ فَلْيُرَاجِعْهَا حَتَّى تَحِيضَ حَيْضَةً أُخْرَى مُسْتَقْبَلَةً سِوَى حَيْضَتِهَا الَّتِي طَلَّقَهَا فِيهَا فَإِنْ بَدَا لَهُ أَنْ يُطَلِّقَهَا فَلْيُطَلِّقْهَا طَاهِرًا مِنْ حَيْضَتِهَا قَبْلَ أَنْ يَمَسَّهَا فَذَلِكَ الطَّلاَقُ لِلْعِدَّةِ كَمَا أَمَرَ اللَّهُ. وَكَانَ عَبْدُ اللَّهِ طَلَّقَهَا تَطْلِيقَةً وَاحِدَةً فَحُسِبَتْ مِنْ طَلاَقِهَا وَرَاجَعَهَا عَبْدُ اللَّهِ كَمَا أَمَرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4908)، ومسلم في الطلاق (4:1471) كلاهما من طريق الزهري، قال: أخبرني سالم به، فذكره.","grade":"متفق عليه","chapter_ar":"باب طلاق السنة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4908) and Muslim (1471 no. 4), and the wording is that of Muslim.","chapter_en":"Divorce According to the Sunnah","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Salim ibn ʿAbd Allah narrated that ʿAbd Allah ibn ʿUmar said: I divorced my wife while she was menstruating. ʿUmar mentioned that to the Prophet ﷺ. The Messenger of Allah ﷺ became angry, then said, “Command him to take her back until she menstruates another menstrual cycle, different from the one in which he divorced her. Then if he decides to divorce her, let him divorce her while she is pure from that menstruation before touching her. That is the divorce for the waiting period as Allah commanded.” Ibn ʿUmar had divorced her with one divorce, and it was counted as part of her divorces, and ʿAbd Allah took her back as the Messenger of Allah ﷺ commanded him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4908,"lafz":true},{"key":"muslim","label":"مسلم","number":4}],"full":1,"dr":1},{"num":6558,"demo":false,"sanad":"","matn":["عَبْدُ اللَّهِ بْنُ دِينَارٍ، عَنِ ابْنِ عُمَرَ، أَنَّهُ طَلَّقَ امْرَأَتَهُ وَهْىَ حَائِضٌ فَسَأَلَ عُمَرُ عَنْ ذَلِكَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ مُرْهُ فَلْيُرَاجِعْهَا حَتَّى تَطْهُرَ ثُمَّ تَحِيضَ حَيْضَةً أُخْرَى ثُمَّ تَطْهُرَ ثُمَّ يُطَلِّقَ بَعْدُ أَوْ يُمْسِكَ."],"takhrij":"صحيح: رواه مسلم (6:1471) عن أحمد بن عثمان بن حكيم الأودي، حدثنا خالد بن مخلد، حدثني سليمان (هو ابن بلال) حدثني عبدالله بن دينار فذكره.","grade":"صحيح","chapter_ar":"باب طلاق السنة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1471 no. 6).","chapter_en":"Divorce According to the Sunnah","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿAbd Allah ibn Dinar narrated from Ibn ʿUmar that he divorced his wife while she was menstruating. ʿUmar asked the Messenger of Allah ﷺ about that, and he said, “Command him to take her back until she becomes pure, then menstruates, then becomes pure, then after that he may divorce her or keep her.”"]},"buhuth":{"en":["Second wording: he commanded that she be taken back, and when she becomes pure, he may divorce her in that state of purity."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":6,"lafz":true}],"full":1,"dr":1},{"num":6559,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ، سِيرِينَ قَالَ سَأَلْتُ ابْنَ عُمَرَ عَنِ امْرَأَتِهِ الَّتِي، طَلَّقَ فَقَالَ طَلَّقْتُهَا وَهْىَ حَائِضٌ فَذُكِرَ ذَلِكَ لِعُمَرَ فَذَكَرَهُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ مُرْهُ فَلْيُرَاجِعْهَا فَإِذَا طَهَرَتْ فَلْيُطَلِّقْهَا لِطُهْرِهَا. قَالَ فَرَاجَعْتُهَا ثُمَّ طَلَّقْتُهَا لِطُهْرِهَا. قُلْتُ فَاعْتَدَدْتَ بِتِلْكَ التَّطْلِيقَةِ الَّتِي طَلَّقْتَ وَهْىَ حَائِضٌ قَالَ مَا لِيَ لاَ أَعْتَدُّ بِهَا وَإِنْ كُنْتُ عَجَزْتُ وَاسْتَحْمَقْتُ."],"takhrij":"متفق عليه: رواه البخاري في الطلاق (5252) ومسلم في الطلاق (1471-12) كلاهما من طريق شعبة، عن أنس بن سيرين فذكره.","grade":"متفق عليه","chapter_ar":"باب طلاق السنة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5252) and Muslim (1471 no. 12), and the wording is that of Muslim.","chapter_en":"Divorce According to the Sunnah","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Sirin said: I asked Ibn ʿUmar about the wife whom he had divorced. He said: I divorced her while she was menstruating, and that was mentioned to ʿUmar, who mentioned it to the Prophet ﷺ. He said, “Command him to take her back, then when she becomes pure let him divorce her in her purity.” He said: So I took her back, then divorced her in her purity. I said: Did you count that divorce in which you divorced her while she was menstruating? He said: “Why would I not count it, even though I acted foolishly and ignorantly?”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5252,"lafz":true},{"key":"muslim","label":"مسلم","number":12},{"key":"muslim","label":"مسلم في الطلاق","number":1471,"n":3666}],"full":1,"dr":1},{"num":6560,"demo":false,"sanad":"","matn":["أَخْبَرَنِي أَبُو الزُّبَيْرِ، أَنَّهُ سَمِعَ عَبْدَ الرَّحْمَنِ بْنَ أَيْمَنَ، مَوْلَى عَزَّةَ يَسْأَلُ ابْنَ عُمَرَ وَأَبُو الزُّبَيْرِ يَسْمَعُ ذَلِكَ كَيْفَ تَرَى فِي رَجُلٍ طَلَّقَ امْرَأَتَهُ حَائِضًا فَقَالَ طَلَّقَ ابْنُ عُمَرَ امْرَأَتَهُ وَهْىَ حَائِضٌ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَ عُمَرُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ إِنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ طَلَّقَ امْرَأَتَهُ وَهْىَ حَائِضٌ. فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيُرَاجِعْهَا. فَرَدَّهَا وَقَالَ إِذَا طَهَرَتْ فَلْيُطَلِّقْ أَوْ لِيُمْسِكْ.","قال ابن عمر: وقرأ النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ﴿يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ﴾ [الطلاق:1]"],"takhrij":"صحيح: رواه مسلم في الطلاق (14:1471) عن هارون بن عبد الله، حدثنا حجاج بن محمد، قال: قال ابن جريج، أخبرني أبو الزبير، به، فذكره.","grade":"صحيح","chapter_ar":"باب طلاق السنة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1471 no. 14).","chapter_en":"Divorce According to the Sunnah","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abu al-Zubayr heard ʿAbd Allah ibn ʿAbd al-Rahman ibn Ayman, the freedman of ʿAzzah, asking Ibn ʿUmar — while Abu al-Zubayr was listening —: What do you think about a man who divorces his wife while she is menstruating? He replied: Ibn ʿUmar divorced his wife while she was menstruating in the time of the Messenger of Allah ﷺ. So ʿUmar asked the Messenger of Allah ﷺ and said: ʿAbd Allah ibn ʿUmar divorced his wife while she was menstruating. The Messenger of Allah ﷺ said, “Let him take her back.” So he returned her and said, “When she becomes pure, then let him divorce her or keep her.” Ibn ʿUmar said: The Prophet ﷺ recited: “O Prophet, when you divorce women, divorce them for their waiting period.” [Surat al-Talaq: 1]"]},"buhuth":{"en":["Third wording: concise, which is that he divorced his wife while she was menstruating, so he was ordered to take her back, as in the following narration:"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":14,"lafz":true}],"full":1,"dr":1},{"num":6561,"demo":false,"sanad":"","matn":["عَنِ ابْنِ، سِيرِينَ قَالَ مَكَثْتُ عِشْرِينَ سَنَةً يُحَدِّثُنِي مَنْ لاَ أَتَّهِمُ أَنَّ ابْنَ عُمَرَ طَلَّقَ امْرَأَتَهُ ثَلاَثًا وَهْىَ حَائِضٌ فَأُمِرَ أَنْ يُرَاجِعَهَا فَجَعَلْتُ لاَ أَتَّهِمُهُمْ وَلاَ أَعْرِفُ الْحَدِيثَ حَتَّى لَقِيتُ أَبَا غَلاَّبٍ يُونُسَ بْنَ جُبَيْرٍ الْبَاهِلِيَّ. وَكَانَ ذَا ثَبَتٍ فَحَدَّثَنِي أَنَّهُ سَأَلَ ابْنَ عُمَرَ فَحَدَّثَهُ أَنَّهُ طَلَّقَ امْرَأَتَهُ تَطْلِيقَةً وَهْىَ حَائِضٌ فَأُمِرَ أَنْ يَرْجِعَهَا.","قال: قلت: أفحسبت عليه؟ قال: فمه، أو إن عجز واستحمق؟"],"takhrij":"متفق عليه: رواه البخاري في الطلاق (5333) من طريق يزيد بن إبراهيم ومسلم في الطلاق (7:1471) من طريق أيوب، كلاهما عن ابن سيرين، به. واللفظ لمسلم وهو عند البخاري مختصر لم يذكر أول القصة.","grade":"متفق عليه","chapter_ar":"باب طلاق السنة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5333) and Muslim (1471 no. 7), and the wording is that of Muslim.","chapter_en":"Divorce According to the Sunnah","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn Sirin said: For twenty years, trustworthy people told me that Ibn ʿUmar divorced his wife three times while she was menstruating, and that he was ordered to take her back. I did not suspect them, but I did not know the hadith properly until I met Abu Ghallab Yunus ibn Jubayr al-Bahili, who was reliable and precise. He told me that he had asked Ibn ʿUmar, and Ibn ʿUmar told him that he divorced his wife with one divorce while she was menstruating, and he was ordered to take her back. He said: I asked, Was it counted against him? He replied: “Of course — unless one is incapable and foolish?”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5333,"lafz":true},{"key":"muslim","label":"مسلم","number":7}],"full":1,"dr":1},{"num":6562,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ، أَنَّهُ قَالَ طَلاَقُ السُّنَّةِ تَطْلِيقَةٌ وَهِيَ طَاهِرٌ فِي غَيْرِ جِمَاعٍ فَإِذَا حَاضَتْ وَطَهُرَتْ طَلَّقَهَا أُخْرَى فَإِذَا حَاضَتْ وَطَهُرَتْ طَلَّقَهَا أُخْرَى ثُمَّ تَعْتَدُّ بَعْدَ ذَلِكَ بِحَيْضَةٍ."],"takhrij":"صحيح: رواه النسائي (3394) - واللفظ له-، وابن ماجة (2021) كلاهما من حديث حفص بن غياث، قال: حدثنا الأعمش، عن أبي إسحاق، عن أبي الأحوص، عن عبدالله فذكره.","grade":"صحيح","chapter_ar":"باب طلاق السنة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3394), and this is his wording, and Ibn Majah (2021).","chapter_en":"Divorce According to the Sunnah","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿAbd Allah said: Divorce according to the Sunnah is one divorce while she is pure and without intercourse. Then if she menstruates and becomes pure, he divorces her a second time. Then if she menstruates and becomes pure, he divorces her a third time. Then after that she observes her waiting period with one menstrual cycle."]},"buhuth":{"en":["According to the Imams, divorce according to the Sunnah is when four conditions are met:","1. She is in a state of purity.","2. He has not had intercourse with her in that state of purity.","3. He divorces her with one single divorce.","4. He does not follow it with another divorce until the waiting period has ended."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3394,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2021}],"full":1,"dr":1},{"num":6563,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ طَلاَقَ إِلاَّ فِيمَا تَمْلِكُ وَلاَ عِتْقَ إِلاَّ فِيمَا تَمْلِكُ وَلاَ بَيْعَ إِلاَّ فِيمَا تَمْلِكُ. زَادَ ابْنُ الصَّبَّاحِ وَلاَ وَفَاءَ نَذْرٍ إِلاَّ فِيمَا تَمْلِكُ."],"takhrij":"حسن: رواه أبو داود (2190) والترمذي (1181) والنسائي (4613) وابن ماجة (2047) وأحمد (6769) وابن الجارود (743) والحاكم (2/205) كلهم من طرق كثيرة، عن عمرو بن شعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب لا طلاق قبل النكاح","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2190), al-Tirmidhi (1181), and al-Nasa’i (4613). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"There Is No Divorce Before Marriage","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb, from his father, from his grandfather, said: The Messenger of Allah ﷺ said, “There is no divorce except regarding one whom you possess, no emancipation except of what you possess, no sale except of what you possess, and no fulfillment of a vow except regarding what you possess.”"]},"intro":{"ar":["قال الله تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نَكَحْتُمُ الْمُؤْمِنَاتِ ثُمَّ طَلَّقْتُمُوهُنَّ مِنْ قَبْلِ أَنْ تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا﴾ [الأحزاب: ٤٩].","عن ابن عباس قال: “جعل الله الطلاق بعد النكاح”. ذكره البخاري تعليقا في الطلاق (٣٨١/٩-مع الفتح)"],"en":["Allah the Exalted said: “O you who believe, when you marry believing women and then divorce them before you have touched them, then there is no waiting period for you to count against them.” [Surat al-Ahzab: 49]","Ibn ʿAbbas said: “Allah placed divorce after marriage.” Al-Bukhari mentioned it in a suspended form in the Book of Divorce (9/381 with al-Fath)."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2190,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1181},{"key":"nasai","label":"النسائي","number":4613},{"key":"ibnmajah","label":"ابن ماجه","number":2047},{"key":"ahmad","label":"احمد","number":6769},{"key":"sh13071","label":"ابن الجارود","number":743}],"full":1,"dr":1},{"num":6564,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ اللَّهَ تَجَاوَزَ لأُمَّتِي مَا حَدَّثَتْ بِهِ أَنْفُسَهَا مَا لَمْ يَتَكَلَّمُوا أَوْ يَعْمَلُوا."],"takhrij":"متفق عليه: رواه البخاري في العتق (2528) ومسلم في الإيمان (127) كلاهما من حديث مسعر، عن قتادة، عن زرارة بن أوفى، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب الوسوسة في الطلاق","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2528) and Muslim (127).","chapter_en":"Misgivings and Whisperings Regarding Divorce","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said, “Allah has pardoned my nation for what their souls whisper to them, so long as they do not speak of it or act upon it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2528,"lafz":true},{"key":"muslim","label":"مسلم","number":127}],"full":1},{"num":6565,"demo":false,"sanad":"","matn":["عن عَائِشَةَ تَقُولُ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ لاَ طَلاَقَ وَلاَ عَتَاقَ فِي غَلاَقٍ."],"takhrij":"حسن: له طرق منها ما رواه أبو داود (2193) وابن ماجة (2046) والدارقطني (4/36) والحاكم (2/198) والبيهقي (7/357) كلهم من حديث محمد بن إسحاق، قال: حدثني ثور بن يزيد الكلاعي – وكان ثقة – عن محمد بن عبيد بن أبي صالح المكي قال: حججتُ مع عدي بن عدي الكندي، فبعثني إلى صفية بنت شيبة بن عثمان صاحب الكعبة أسألها عن أشياء سمعتْها من عائشة عن رسول الله صلى الله عليه وسلم. فكان فيما حدثتني أنها سمعتْ عائشة تقول: فذكرت الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في طلاق المُكرَه","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan through supporting narrations: Narrated by Abu Dawud (2193), Ibn Majah (2046), al-Daraqutni (4/36), and al-Hakim (2/198).","chapter_en":"What Has Been Related About the Divorce of One Who Is Forced","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["ʿA’ishah said: I heard the Messenger of Allah ﷺ say, “There is no divorce and no emancipation in a state of coercion.”"]},"buhuth":{"en":["His saying, “in a state of coercion,” was explained as compulsion, because the compelled person is constrained in his judgment and action. It was also said to mean that the door is shut on him, he is confined, and pressured until he divorces. Al-Khattabi said: “The meaning of ‘closure’ is compulsion.” And ʿUmar ibn al-Khattab, ʿAli ibn Abi Talib, Ibn ʿUmar, and Ibn ʿAbbas, may Allah be pleased with them, did not regard the divorce of the compelled person as valid."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2193,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2046},{"key":"sh9771","label":"الدار قطني","number":36},{"key":"hakim","label":"المستدرك على الصحيحين","number":2802,"n":2788}],"full":1,"dr":1},{"num":6566,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ،. أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ رُفِعَ الْقَلَمُ عَنْ ثَلاَثَةٍ عَنِ النَّائِمِ حَتَّى يَسْتَيْقِظَ وَعَنِ الصَّغِيرِ حَتَّى يَكْبَرَ وَعَنِ الْمَجْنُونِ حَتَّى يَعْقِلَ أَوْ يُفِيقَ."],"takhrij":"حسن: رواه أبو داود (4398) والنسائي (6/156) وابن ماجة (2041) وابن الجارود (148) وأحمد (24694) وصحّحه ابن حبان (142) والحاكم (2/59) كلهم من حديث حماد بن سلمة، عن حماد، عن إبراهيم، عن الأسود، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب طلاق النائم والصغير والمعتوه","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4398), al-Nasa’i (6/156), Ibn Majah (2041), and Ahmad (24694).","chapter_en":"The Divorce of the Sleeper, the Minor, and the Mentally Unsound","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["ʿA’ishah narrated that the Messenger of Allah ﷺ said, “The pen has been lifted from three: from the sleeper until he wakes, from the child until he grows up, and from the insane person until he regains reason or recovers.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4398,"lafz":true},{"key":"nasai","label":"النسائي","number":156},{"key":"ibnmajah","label":"ابن ماجه","number":2041},{"key":"ahmad","label":"مسند الإمام أحمد","number":24694,"n":24694},{"key":"sh13071","label":"ابن الجارود","number":148,"n":156},{"key":"ibnhibban","label":"ابن حبان","number":142}],"full":1,"dr":1},{"num":6567,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ ثَلاَثٌ جِدُّهُنَّ جِدٌّ وَهَزْلُهُنَّ جِدٌّ النِّكَاحُ وَالطَّلاَقُ وَالرَّجْعَةُ."],"takhrij":"حسن: رواه أبو داود (2194) والترمذي (1184) وابن ماجة (2039) وابن الجارود (712) والدارقطني (3/257) والحاكم (2/198) كلهم من حديث عبد الرحمن بن حبيب بن أردك المدني، عن عطاء، عن ابن ماهك، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الجد والهزل في الطلاق","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2194), al-Tirmidhi (1184), who graded it Hasan, Ibn Majah (2039), and Ibn al-Jarud (712).","chapter_en":"What Has Been Related About Seriousness and Jesting in Divorce","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said, “Three matters whose seriousness is serious and whose joking is serious: marriage, divorce, and taking back one’s wife.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2194,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1184},{"key":"ibnmajah","label":"ابن ماجه","number":2039},{"key":"sh13071","label":"ابن الجارود","number":712,"n":741}],"full":1,"dr":1},{"num":6568,"demo":false,"sanad":"","matn":["عن عِمْرَانَ بْنِ حُصَيْنٍ سُئِلَ عَنِ الرَّجُلِ، يُطَلِّقُ امْرَأَتَهُ ثُمَّ يَقَعُ بِهَا وَلَمْ يُشْهِدْ عَلَى طَلاَقِهَا وَلاَ عَلَى رَجْعَتِهَا فَقَالَ طَلَّقْتَ لِغَيْرِ سُنَّةٍ. وَرَاجَعْتَ لِغَيْرِ سُنَّةٍ أَشْهِدْ عَلَى طَلاَقِهَا وَعَلَى رَجْعَتِهَا وَلاَ تَعُدْ."],"takhrij":"حسن: رواه أبو داود (2186) وابن ماجة (2025) كلاهما عن بشر بن هلال الصواف، قال: حدثنا جعفر بن سليمان الضُبعي، عن يزيد الرِشك، عن مطرف بن عبد الله بن الشخير، أن عمران بن حصين سئل فذكره.","grade":"حسن","chapter_ar":"باب الإشهاد على الطلاق والمراجعة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (2186) and Ibn Mājah (2025).","chapter_en":"Having Witnesses for Divorce and Taking Back One’s Wife","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn was asked about a man who divorced his wife and then resumed marital relations with her without taking witnesses either for the divorce or for taking her back. He said: “You divorced contrary to the Sunnah, and you took her back contrary to the Sunnah. Take witnesses to her divorce and to taking her back, and do not do this again.”"]},"buhuth":{"en":["Allah Most High says:","“And call to witness two just men from among you.”","[al-Ṭalāq: 2]","This applies to both acts: divorce and taking the wife back. The command is understood as a recommendation, like His saying:","“And take witnesses when you conduct a transaction.”","[al-Baqarah: 282]","And His saying:","“Then when you hand over their wealth to them, take witnesses over them.”","[al-Nisāʾ: 6]","Since taking witnesses in a sale is not obligatory, likewise it is not obligatory in divorce and taking a wife back."]},"intro":{"ar":["قال تعالى: ﴿فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ فَارِقُوهُنَّ بِمَعْرُوفٍ وَأَشْهِدُوا ذَوَيْ عَدْلٍ مِنْكُمْ﴾ [الطلاق: ٢]."],"en":["Allah the Exalted said: “Then retain them in a fair manner or part with them in a fair manner, and call to witness two just men from among you.” [Surat al-Talaq: 2]"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2186,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2025}],"full":1,"dr":1,"rep":[13577]},{"num":6569,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ كَانَ الطَّلاَقُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبِي بَكْرٍ وَسَنَتَيْنِ مِنْ خِلاَفَةِ عُمَرَ طَلاَقُ الثَّلاَثِ وَاحِدَةً فَقَالَ عُمَرُ بْنُ الْخَطَّابِ إِنَّ النَّاسَ قَدِ اسْتَعْجَلُوا فِي أَمْرٍ قَدْ كَانَتْ لَهُمْ فِيهِ أَنَاةٌ فَلَوْ أَمْضَيْنَاهُ عَلَيْهِمْ. فَأَمْضَاهُ عَلَيْهِمْ."],"takhrij":"صحيح: رواه مسلم في الطلاق (1472) من طريق عبد الرزاق، أخبرنا معمر، عن ابن طاوس، عن أبيه، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب عدد الطلاق في عهد النبي ﷺ والخلفاء الراشدين","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1472).","chapter_en":"The Number of Divorces During the Time of the Prophet ﷺ and the Rightly Guided Caliphs","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿAbbas said: During the time of the Messenger of Allah ﷺ, Abu Bakr, and the first two years of ʿUmar’s caliphate, a threefold divorce counted as one. Then ʿUmar ibn al-Khattab said: “People have rushed into a matter in which they previously had time to reflect, so if we enforce it upon them…” So he enforced it upon them."]},"buhuth":{"en":["In the statement of Ibn ʿAbbas there is an indication of the consensus of the Companions during the time of Abu Bakr — which lasted two years and some months — and for two years of the caliphate of ʿUmar, that a triple divorce counted as one. Then ʿUmar ibn al-Khattab enforced it and made the three count as three. However, the Muslim community did not unanimously agree upon this. Among the Companions who differed with him and issued rulings contrary to it were al-Zubayr ibn al-ʿAwwam, ʿAbd al-Rahman ibn ʿAwf, ʿAli ibn Abi Talib, and Ibn Masʿud; among the Followers were ʿIkrimah and Tawus; and among those after them were Muhammad ibn Ishaq, some companions of Malik, some companions of Abu Hanifah, and some companions of Ahmad. As for those who came later, they are too numerous to count, among them Shaykh al-Islam Ibn Taymiyyah, his student Ibn al-Qayyim, and others."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1472,"lafz":true}],"full":1,"dr":1},{"num":6570,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: طَلَّقَ رُكَانَةُ بْنُ عَبْدِ يَزِيدَ أَخُو بَنِي الْمُطَّلِبِ امْرَأَتَهُ ثَلَاثًا فِي مَجْلِسٍ وَاحِدٍ، فَحَزِنَ عَلَيْهَا حُزْنًا شَدِيدًا، قَالَ: فَسَأَلَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَيْفَ طَلَّقْتَهَا؟ قَالَ: طَلَّقْتُهَا ثَلَاثًا، قَالَ: فَقَالَ: فِي مَجْلِسٍ وَاحِدٍ؟ قَالَ: نَعَمْ قَالَ: فَإِنَّمَا تِلْكَ وَاحِدَةٌ فَأَرْجِعْهَا إِنْ شِئْتَ قَالَ: فَرَجَعَهَا فَكَانَ ابْنُ عَبَّاسٍ: يَرَى أَنَّمَا الطَّلَاقُ عِنْدَ كُلِّ طُهْرٍ."],"takhrij":"حسن: رواه أحمد (2387) وأبو يعلى (2500) والبيهقي (7/339) كلهم من طريق محمد بن إسحاق، حدثني داود بن الحصين، عن عكرمة مولى ابن عباس، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب عدد الطلاق في عهد النبي ﷺ والخلفاء الراشدين","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (2387), Abu Yaʿla (2500), and al-Bayhaqi (7/339).","chapter_en":"The Number of Divorces During the Time of the Prophet ﷺ and the Rightly Guided Caliphs","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿAbbas said: Rukanah ibn ʿAbd Yazid, the brother of Banu al-Muttalib, divorced his wife three times in one sitting, then became deeply grieved over her. The Messenger of Allah ﷺ asked him, “How did you divorce her?” He said: I divorced her three times. He said, “In one sitting?” He said: Yes. He said, “That counts only as one, so take her back if you wish.” So he took her back. Ibn ʿAbbas held that divorce is to be given at each state of purity."]},"buhuth":{"en":["Its chain is Hasan because of Muhammad ibn Ishaq.","The two routes together strengthen the report because they agree that he pronounced three divorces in one sitting, the Prophet ﷺ treated them as one, and ordered him to take her back. Al-Hafiz Ibn Hajar preferred Ibn Ishaq’s narration and said that this hadith is explicit on the issue and does not admit the interpretation applied to other reports.","Ibn Hajar also transmitted this view from ʿAli, Ibn Masʿud, ʿAbd al-Rahman ibn ʿAwf, and al-Zubayr, while Ibn al-Mundhir transmitted it from students of Ibn ʿAbbas such as ʿAta’, Tawus, and ʿAmr ibn Dinar.","The differing verdicts of Ibn ʿAbbas:","Mujahid said: I was with Ibn ʿAbbas when a man came to him and said: He divorced his wife three times. Ibn ʿAbbas remained silent until I thought he would send her back to him, then he said: “One of you goes and behaves foolishly, then says: O Ibn ʿAbbas, O Ibn ʿAbbas! Allah says: ‘And whoever fears Allah, He will make for him a way out’ [al-Talaq: 2], but you did not fear Allah, so I find no way out for you. You disobeyed your Lord, and your wife has become separated from you. And Allah says: ‘O Prophet, when you divorce women, divorce them for their waiting period’ [al-Talaq: 1].” Narrated by Abu Dawud (2197), and its chain is authentic.","The meaning of this is that there are two views reported from him in this issue:","The first view: as narrated by most of his students, that he counted triple divorce uttered as three.","The second view: that the three do not take effect as three, as in the narration from ʿIkrimah from him. It is possible to reconcile the two by saying that at first he held that three were to be enforced as three, then it became clear to him that they count as one, so he returned to that view, just as he changed his opinion in another legal matter.","Important benefits:","Divorce is of three types:","Revocable divorce: in which he may take her back without her choice, and if one of them dies during the waiting period, the other inherits.","Irrevocable divorce: in which he remains only a suitor to her, and she is not lawful for him except through a new marriage contract.","Final prohibiting divorce: after which she is not lawful for him until she marries another husband.","Divorce in one state of purity with one expression or several expressions:","For example: “You are divorced three times.”","Or: “You are divorced, divorced, divorced.”","Or: “You are divorced, then divorced, then divorced.”","Or: “You are divorced three times, or a hundred times, or a thousand times.”","The scholars have two opinions on this:","The first: that it counts as three binding divorces.","This was held by Abu Hanifah, Malik, al-Shafiʿi, and Ahmad in one narration from him, and most of his companions chose it. It was also held by many of the early generations among the Companions, the Followers, and those after them.","The second: that it counts only as one divorce.","This was held by some companions of Abu Hanifah, Malik, and Ahmad. It is also reported from a group among the early and later scholars, including some of the Companions of the Messenger of Allah ﷺ, such as ʿAli, Ibn Masʿud, al-Zubayr ibn al-ʿAwwam, and ʿAbd al-Rahman ibn ʿAwf. Shaykh al-Islam mentioned this in his legal verdicts.","What is correct in this issue is that it is best for every person to refer to the official legal authority in his own country so that he does not fall into contradiction and confusion in his affair. And Allah guides to the straight path."]}},"tuhfa":{},"refs":[{"key":"sh12520","label":"أبو يعلى","number":2500},{"key":"kubrabayhaqi","label":"البيهقي","number":339},{"key":"ahmad","label":"مسند الإمام أحمد","number":2387,"n":2387,"lafz":true},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":14987,"n":15134}],"full":1,"dr":1},{"num":6571,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ خَيَّرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاخْتَرْنَا اللَّهَ وَرَسُولَهُ، فَلَمْ يَعُدَّ ذَلِكَ عَلَيْنَا شَيْئًا."],"takhrij":"متفق عليه: رواه البخاري في الطلاق (5262)، ومسلم في الطلاق (28:1477) من طريق الأعمش، حدثنا مسلم (أبو الضحى) عن مسروق، عن عائشة، فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الخيار","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5262) and Muslim (1477 no. 28).","chapter_en":"What Has Been Related About Choice","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ gave us the choice, and we chose Allah and His Messenger, and he did not count that as anything against us."]},"buhuth":{"en":["Al-Bukhari also narrated it (5263), and Muslim (no. 25), through another route from Masruq, who said: It does not matter to me whether I give my wife the choice once, a hundred times, or a thousand times, so long as she chooses me. I asked ʿA’ishah, and she said: The Messenger of Allah ﷺ gave us the choice — was that divorce? Meaning: it was not divorce."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5262,"lafz":true},{"key":"muslim","label":"مسلم","number":28}],"full":1,"dr":1,"rep":[13060]},{"num":6572,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ دَخَلَ أَبُو بَكْرٍ يَسْتَأْذِنُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَوَجَدَ النَّاسَ جُلُوسًا بِبَابِهِ لَمْ يُؤْذَنْ لأَحَدٍ مِنْهُمْ - قَالَ - فَأُذِنَ لأَبِي بَكْرٍ فَدَخَلَ ثُمَّ أَقْبَلَ عُمَرُ فَاسْتَأْذَنَ فَأُذِنَ لَهُ فَوَجَدَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسًا حَوْلَهُ نِسَاؤُهُ وَاجِمًا سَاكِتًا - قَالَ - فَقَالَ لأَقُولَنَّ شَيْئًا أُضْحِكُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ يَا رَسُولَ اللَّهِ لَوْ رَأَيْتَ بِنْتَ خَارِجَةَ سَأَلَتْنِي النَّفَقَةَ فَقُمْتُ إِلَيْهَا فَوَجَأْتُ عُنُقَهَا. فَضَحِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَالَ هُنَّ حَوْلِي كَمَا تَرَى يَسْأَلْنَنِي النَّفَقَةَ. فَقَامَ أَبُو بَكْرٍ إِلَى عَائِشَةَ يَجَأُ عُنُقَهَا فَقَامَ عُمَرُ إِلَى حَفْصَةَ يَجَأُ عُنُقَهَا كِلاَهُمَا يَقُولُ تَسْأَلْنَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا لَيْسَ عِنْدَهُ. فَقُلْنَ وَاللَّهِ لاَ نَسْأَلُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَيْئًا أَبَدًا لَيْسَ عِنْدَهُ ثُمَّ اعْتَزَلَهُنَّ شَهْرًا أَوْ تِسْعًا وَعِشْرِينَ ثُمَّ نَزَلَتْ عَلَيْهِ هَذِهِ الآيَةُ { يَا أَيُّهَا النَّبِيُّ قُلْ لأَزْوَاجِكَ} حَتَّى بَلَغَ { لِلْمُحْسِنَاتِ مِنْكُنَّ أَجْرًا عَظِيمًا} قَالَ فَبَدَأَ بِعَائِشَةَ فَقَالَ يَا عَائِشَةُ إِنِّي أُرِيدُ أَنْ أَعْرِضَ عَلَيْكَ أَمْرًا أُحِبُّ أَنْ لاَ تَعْجَلِي فِيهِ حَتَّى تَسْتَشِيرِي أَبَوَيْكِ. قَالَتْ وَمَا هُوَ يَا رَسُولَ اللَّهِ فَتَلاَ عَلَيْهَا الآيَةَ قَالَتْ أَفِيكَ يَا رَسُولَ اللَّهِ أَسْتَشِيرُ أَبَوَىَّ بَلْ أَخْتَارُ اللَّهَ وَرَسُولَهُ وَالدَّارَ الآخِرَةَ وَأَسْأَلُكَ أَنْ لاَ تُخْبِرَ امْرَأَةً مِنْ نِسَائِكَ بِالَّذِي قُلْتُ. قَالَ لاَ تَسْأَلُنِي امْرَأَةٌ مِنْهُنَّ إِلاَّ أَخْبَرْتُهَا إِنَّ اللَّهَ لَمْ يَبْعَثْنِي مُعَنِّتًا وَلاَ مُتَعَنِّتًا وَلَكِنْ بَعَثَنِي مُعَلِّمًا مُيَسِّرًا."],"takhrij":"صحيح: رواه مسلم في الطلاق (1478) عن زهير بن حرب، حدثنا روح ابن عبادة، حدثنا زكريا بن إسحاق، حدثنا أبو الزبير، عن جابر بن عبـد الله فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الخيار","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1478).","chapter_en":"What Has Been Related About Choice","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Jabir ibn ʿAbd Allah said: Abu Bakr came seeking permission to enter upon the Messenger of Allah ﷺ and found people sitting at his door, with none of them having been granted permission. Permission was granted to Abu Bakr, so he entered. Then ʿUmar came and sought permission, and it was granted to him. He found the Prophet ﷺ sitting silently and distressed, with his wives around him. He said: I will say something to make the Prophet ﷺ laugh. So he said: O Messenger of Allah, if only you had seen the daughter of Kharijah! She asked me for spending money, so I got up and struck her neck. The Messenger of Allah ﷺ laughed and said, “They are around me as you see, asking me for spending.” Then Abu Bakr stood up to strike ʿA’ishah on the neck, and ʿUmar stood up to strike Hafsah on the neck, both saying: You ask the Messenger of Allah ﷺ for what he does not have. They said: By Allah, we will never ask the Messenger of Allah ﷺ again for something he does not have. Then he stayed away from them for a month or twenty-nine days. Then this verse was revealed to him: “O Prophet, say to your wives…” until he reached: “…for the women among you who do good is a great reward.” [Surat al-Ahzab: 28–29] He began with ʿA’ishah and said, “O ʿA’ishah, I want to present you with a matter, and I would prefer that you do not hasten in it until you consult your parents.” She said: What is it, O Messenger of Allah? Then he recited the verse to her. She said: About you, O Messenger of Allah, should I consult my parents? Rather, I choose Allah, His Messenger, and the Hereafter. But I ask you not to tell any of your wives what I said. He said, “No woman among them asks me except that I tell her. Allah did not send me to be harsh or difficult, but He sent me as a teacher who makes matters easy.”"]},"buhuth":{"en":["It is understood from this hadith that if a man gives his wife the choice and she chooses him, then nothing results from that, as shown by the hadith of ʿA’ishah. It is also understood from it that if she had chosen herself, would that have counted as divorce or not? The correct view is that it would count as divorce. They differed if she chose herself: the majority said it is one divorce, and he has the best right to take her back. Some said it is three. They also differed regarding the duration of the choice. The correct view, held by most scholars, is that the choice lasts only until she rises from her sitting place; once she rises, the option ends."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1478,"lafz":true}],"full":1,"dr":1,"rep":[13059]},{"num":6573,"demo":false,"sanad":"","matn":["عَنْ كَعْبِ بن مَالِكٍ قَالَ فِي حَدِيثِهِ الطويل: حَتَّى إِذَا مَضَتْ أَرْبَعُونَ لَيْلَةً مِنَ الْخَمْسِينَ إِذَا رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْتِينِي فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُكَ أَنْ تَعْتَزِلَ امْرَأَتَكَ، فَقُلْتُ: أُطَلِّقُهَا أَمْ مَاذَا أَفْعَلُ؟ قَالَ: لاَ، بَلِ اعْتَزِلْهَا وَلاَ تَقْرَبْهَا. وَأَرْسَلَ إِلَى صَاحِبِي مِثْلَ ذَلِكَ، فَقُلْتُ لاِمْرَأَتِي: الْحَقِي بِأَهْلِكِ، فَتَكُونِي عِنْدَهُمْ حَتَّى يَقْضِيَ اللَّهُ فِي هَذَا الأَمْرِ... الْحَدِيثِ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4418)، ومسلم في التوبة (2769) كلاهما من طريق ابن شهاب الزهري. أخبرني عبد الرحمـن بن عبـد الله بن كعب بن مالك، عن أبيه، عن جده.","grade":"متفق عليه","chapter_ar":"باب إذا قال: فارقتك، أو سرّحتك، أو الحقي بأهلك، ونحو ذلك فهو طلاق إن نوى به ذلك","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4418) and Muslim (2769).","chapter_en":"If He Says: “I Have Left You,” or “I Have Released You,” or “Go Back to Your Family,” and Similar Expressions, Then It Counts as Divorce If He Intended It","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Kaʿb ibn Mālik said in his lengthy hadith: When forty nights out of the fifty had passed, a messenger of the Messenger of Allah ﷺ came to me and said: “The Messenger of Allah ﷺ commands you to keep away from your wife.” I asked: “Should I divorce her, or what should I do?” He replied: “No. Rather, keep away from her and do not approach her.” The same instruction was sent to my two companions. So I said to my wife: “Go to your family and remain with them until Allah decides this matter…” the remainder of the hadith."]},"intro":{"ar":["قال الله تعالى: ﴿وَسَرِّحُوهُنَّ سَرَاحًا جَمِيلًا﴾ [الأحزاب: ٤٩].","وقال تعالى: ﴿فَإِمْسَاكٌ بِمَعْرُوفٍ أَوْ تَسْرِيحٌ بِإِحْسَانٍ﴾ [البقرة: ٢٢٩].","وقال تعالى: ﴿أَوْ فَارِقُوهُنَّ بِمَعْرُوفٍ﴾ [الطلاق: ٢]."],"en":["Allah the Exalted said: “And release them with a gracious release.” [Surat al-Ahzab: 49]","And He said: “Then retain them in a fair manner or release them with excellence.” [Surat al-Baqarah: 229]","And He said: “Or part with them in a fair manner.” [Surat al-Talaq: 2]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4418,"lafz":true},{"key":"muslim","label":"مسلم","number":2769,"n":7018}],"full":1},{"num":6574,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ ابْنَةَ الْجَوْنِ لَمَّا أُدْخِلَتْ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَدَنَا مِنْهَا قَالَتْ أَعُوذُ بِاللَّهِ مِنْكَ. فَقَالَ لَهَا لَقَدْ عُذْتِ بِعَظِيمٍ، الْحَقِي بِأَهْلِكِ."],"takhrij":"صحيح: رواه البخاري في الطلاق (5254) عن الحميدي، حدثنا الوليد، حدثنا الأوزاعي، قال: سألت الزهري: أي أزواج النبي صلى الله عليه وسلم استعاذت منه؟ قال: أخبرني عروة عن عائشة رضي الله عنها، فذكرته.","grade":"صحيح","chapter_ar":"باب إذا قال: فارقتك، أو سرّحتك، أو الحقي بأهلك، ونحو ذلك فهو طلاق إن نوى به ذلك","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5254).","chapter_en":"If He Says: “I Have Left You,” or “I Have Released You,” or “Go Back to Your Family,” and Similar Expressions, Then It Counts as Divorce If He Intended It","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["ʿA’ishah narrated that when the daughter of al-Jawn was brought to the Messenger of Allah ﷺ and he approached her, she said: I seek refuge in Allah from you. So he said to her, “You have sought refuge with the Greatest. Go back to your family.”"]},"buhuth":{"en":["Her saying, “I seek refuge in Allah from you,” indicates the woman’s lack of sound judgment."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5254,"lafz":true}],"full":1,"dr":1,"rep":[9420]},{"num":6575,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ ذُكِرَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ امْرَأَةٌ مِنَ الْعَرَبِ، فَأَمَرَ أَبَا أُسَيْدٍ السَّاعِدِيَّ أَنْ يُرْسِلَ إِلَيْهَا فَأَرْسَلَ إِلَيْهَا، فَقَدِمَتْ فَنَزَلَتْ فِي أُجُمِ بَنِي سَاعِدَةَ، فَخَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى جَاءَهَا فَدَخَلَ عَلَيْهَا فَإِذَا امْرَأَةٌ مُنَكِّسَةٌ رَأْسَهَا، فَلَمَّا كَلَّمَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ أَعُوذُ بِاللَّهِ مِنْكَ. فَقَالَ قَدْ أَعَذْتُكِ مِنِّي. فَقَالُوا لَهَا أَتَدْرِينَ مَنْ هَذَا قَالَتْ لاَ. قَالُوا هَذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَاءَ لِيَخْطُبَكِ. قَالَتْ كُنْتُ أَنَا أَشْقَى مِنْ ذَلِكَ.","قال سهل: فأقبل رسول الله صلى الله عليه وسلم يومئذ حتى جلس في سقيفة بني ساعدة هو وأصحابه. ثم قال: اسقِنا لسهل. قال: فأخرجت لهم هذا القدحَ فأسقيتهم فيه.","قال أبو حازم: فأخرج لنا سهل ذلك القدح فشربنا فيه. قال: ثم استوهبه بعد ذلك عمرُ بن عبد العزيز، فوهبه له."],"takhrij":"متفق عليه: رواه البخاري في الأشربة (5637)، ومسلم في الأشربة (2007) كلاهما من طريق سعيد بن أبي مريم، حدثنا محمد بن مطرف أبو غسّان، حدثني أبو حازم، عن سهل بن سعد، فذكره.","grade":"متفق عليه","chapter_ar":"باب إذا قال: فارقتك، أو سرّحتك، أو الحقي بأهلك، ونحو ذلك فهو طلاق إن نوى به ذلك","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5637) and Muslim (2007).","chapter_en":"If He Says: “I Have Left You,” or “I Have Released You,” or “Go Back to Your Family,” and Similar Expressions, Then It Counts as Divorce If He Intended It","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Sahl ibn Saʿd said: A woman from among the Arabs was mentioned to the Messenger of Allah ﷺ, so he ordered Abu Usayd to send for her. He sent for her, and she came and stayed in the enclosure of Banu Saʿidah. The Messenger of Allah ﷺ went out until he came to her. He entered upon her and found a woman with her head lowered. When the Messenger of Allah ﷺ spoke to her, she said: “I seek refuge in Allah from you.” He said: “You have been granted refuge from me.” They said to her: “Do you know who this is?” She said: “No.” They said: “This is the Messenger of Allah ﷺ. He came to propose marriage to you.” She said: “I am more wretched than that.” Sahl said: So the Messenger of Allah ﷺ came that day and sat in the shelter of Banu Saʿidah with his companions. Then he said to Sahl: “Give us something to drink.” He said: So I brought out for them this cup and gave them drink in it.","Abu Hazim said: Sahl brought out that cup for us and we drank from it. Then later ʿUmar ibn ʿAbd al-ʿAziz asked him to gift it to him, and he gave it to him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5637,"lafz":true},{"key":"muslim","label":"مسلم","number":2007}],"full":1},{"num":6576,"demo":false,"sanad":"","matn":["عن ابن عبــاس قال: إذا حرّم امرأتـه ليس بشيء وقال: ﴿لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ﴾ [الأحزاب: ٢١]."],"takhrij":"متفق عليه: رواه البخاري في الطلاق (5266)، ومسلم في الطلاق (19:1473) كلاهما من طريق معاوية بن سلام، عن يحيى بن أبي كثير، أن يعلى بن حكيم أخبره، أن سعيد بن جبير، أخبره أنه سمع ابن عباس يقول: فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب من قال لامرأته : أنت علي حرام ولم ينو الطلاق","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5266) and Muslim (1473 no. 19). This is the wording of al-Bukhari.","chapter_en":"Whoever Says to His Wife, “You Are Forbidden to Me,” Without Intending Divorce","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["ʿAbd Allah ibn ʿAbbas said: If a man declares his wife forbidden to himself, it is nothing. And he recited: “Indeed, in the Messenger of Allah you have an excellent example.” [Surat al-Ahzab: 21]"]},"buhuth":{"en":["In the wording of Muslim: “If a man makes his wife forbidden to himself, then it is an oath for which he must offer expiation.”"]},"intro":{"ar":["قال للّه تمالى: (ويَا  لَ  الَ لَهَلَ تِي يَات أروَيِكَ وَلّه عُوْ تَعِر ) (العرم :١)"],"en":["Allah the Exalted said: “O Prophet, why do you forbid what Allah has made lawful for you, seeking the pleasure of your wives?” [Surat al-Tahrim: 1]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5266,"lafz":true},{"key":"muslim","label":"مسلم","number":19}],"full":1,"dr":1},{"num":6577,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَنَّ رَجُلاً طلّق امْرَأَتَهُ ثَلاَثًا، فَتَزَوَّجَتْ فَطَلَّقَ، فَسُئِلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ تحل لِلأَوَّلِ؟ قـال: لاَ حَتَّى يَذُوقَ عُسَيْلَتَهَا كَمَا ذَاقَ الأَوَّلُ."],"takhrij":"متفق عليه: رواه البخاري في الطلاق (5261)، ومسلم في النكاح (115:1433) كلاهما من طريق عبيد الله بن عمر، عن القاسم بن محمد، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب لا تحل المبتوتة حتى تنكح زوجا غيره","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5261) and Muslim (1433 no. 115).","chapter_en":"The Woman Irrevocably Divorced Does Not Become Lawful Until She Marries Another Husband","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["ʿA’ishah narrated that a man divorced his wife three times, then she married another man and he divorced her. The Prophet ﷺ was asked whether she would become lawful for the first husband. He said: “No, not until he tastes her sweetness just as the first one tasted it.”"]},"buhuth":{"en":["The general meaning of Allah’s statement, “If he divorces her, then she is not lawful for him afterward until she marries another husband” [al-Baqarah: 230], allows the first husband to marry her again after she has married another husband. The Sunnah explained that she does not become lawful for the first husband until intercourse takes place between her and the second husband, expressed as tasting the sweetness, and then she is separated from him by divorce or death. Then she becomes lawful for the first husband."]},"intro":{"ar":["قال الله تعالى: ﴿فَإِنْ طَلَّقَهَا فَلَا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنْكِحَ زَوْجًا غَيْرَهُ﴾ [البقرة: ٢٣٠]."],"en":["Allah the Exalted said: “If he divorces her, then she is not lawful for him afterward until she marries another husband.” [Surat al-Baqarah: 230]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5261,"lafz":true},{"key":"muslim","label":"مسلم","number":115}],"full":1,"dr":1},{"num":6578,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا جَاءَتِ امْرَأَةُ رِفَاعَةَ الْقُرَظِيِّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ كُنْتُ عِنْدَ رِفَاعَةَ فَطَلَّقَنِي فَأَبَتَّ طَلاَقِي، فَتَزَوَّجْتُ عَبْدَ الرَّحْمَنِ بْنَ الزَّبِيرِ، إِنَّمَا مَعَهُ مِثْلُ هُدْبَةِ الثَّوْبِ. فَقَالَ أَتُرِيدِينَ أَنْ تَرْجِعِي إِلَى رِفَاعَةَ لاَ حَتَّى تَذُوقِي عُسَيْلَتَهُ وَيَذُوقَ عُسَيْلَتَكِ."],"takhrij":"متفق عليه: رواه البخاري في الشهادات (2639) ومسلم في النكاح (1433) كلاهما من حديث سفيان، عن الزهري، عن عروة، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب لا تحل المبتوتة حتى تنكح زوجا غيره","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2639) and Muslim (1433).","chapter_en":"The Woman Irrevocably Divorced Does Not Become Lawful Until She Marries Another Husband","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["ʿA’ishah said: The wife of Rifaʿah al-Qurazi came to the Prophet ﷺ and said: “I was married to Rifaʿah and he divorced me irrevocably. Then I married ʿAbd al-Rahman ibn al-Zubayr, but he has nothing more than something like the fringe of a garment.” So he said: “Do you want to return to Rifaʿah? No, not until you taste his sweetness and he tastes your sweetness.”"]},"buhuth":{"en":["In another narration: “By Allah, he has nothing except like the fringe,” and she took hold of a fringe of her garment. The Messenger of Allah ﷺ smiled and laughed."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2639,"lafz":true},{"key":"muslim","label":"مسلم","number":1433}],"full":1,"dr":1},{"num":6579,"demo":false,"sanad":"","matn":["عَنْ عِكْرِمَةَ، أَنَّ رِفَاعَةَ، طَلَّقَ امْرَأَتَهُ، فَتَزَوَّجَهَا عَبْدُ الرَّحْمَنِ بْنُ الزَّبِيرِ الْقُرَظِيُّ، قَالَتْ عَائِشَةُ وَعَلَيْهَا خِمَارٌ أَخْضَرُ. فَشَكَتْ إِلَيْهَا، وَأَرَتْهَا خُضْرَةً بِجِلْدِهَا، فَلَمَّا جَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالنِّسَاءُ يَنْصُرُ بَعْضُهُنَّ بَعْضًا قَالَتْ عَائِشَةُ مَا رَأَيْتُ مِثْلَ مَا يَلْقَى الْمُؤْمِنَاتُ، لَجِلْدُهَا أَشَدُّ خُضْرَةً مِنْ ثَوْبِهَا. قَالَ وَسَمِعَ أَنَّهَا قَدْ أَتَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَاءَ وَمَعَهُ ابْنَانِ لَهُ مِنْ غَيْرِهَا. قَالَتْ وَاللَّهِ مَا لِي إِلَيْهِ مِنْ ذَنْبٍ، إِلاَّ أَنَّ مَا مَعَهُ لَيْسَ بِأَغْنَى عَنِّي مِنْ هَذِهِ. وَأَخَذَتْ هُدْبَةً مِنْ ثَوْبِهَا، فَقَالَ كَذَبَتْ وَاللَّهِ يَا رَسُولَ اللَّهِ، إِنِّي لأَنْفُضُهَا نَفْضَ الأَدِيمِ، وَلَكِنَّهَا نَاشِزٌ تُرِيدُ رِفَاعَةَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَإِنْ كَانَ ذَلِكَ لَمْ تَحِلِّي لَهُ ـ أَوْ لَمْ تَصْلُحِي لَهُ ـ حَتَّى يَذُوقَ مِنْ عُسَيْلَتِكِ. قَالَ وَأَبْصَرَ مَعَهُ ابْنَيْنِ فَقَالَ بَنُوكَ هَؤُلاَءِ. قَالَ نَعَمْ. قَالَ هَذَا الَّذِي تَزْعُمِينَ مَا تَزْعُمِينَ، فَوَاللَّهِ لَهُمْ أَشْبَهُ بِهِ مِنَ الْغُرَابِ بِالْغُرَابِ."],"takhrij":"صحيح: رواه البخاري في اللباس (5825) عن محمد بن بشار، حدثنا عبد الوهاب، أخبرنا أيوب، عن عكرمة فذكره.","grade":"صحيح","chapter_ar":"باب لا تحل المبتوتة حتى تنكح زوجا غيره","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5825).","chapter_en":"The Woman Irrevocably Divorced Does Not Become Lawful Until She Marries Another Husband","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["ʿIkrimah narrated that Rifaʿah divorced his wife, and then ʿAbd al-Rahman ibn al-Zubayr al-Qurazi married her. ʿA’ishah said: She was wearing a green veil, and she complained to her and showed her green marks on her skin. When the Messenger of Allah ﷺ came — and women support one another — ʿA’ishah said: I have never seen anything like what believing women suffer; her skin was greener than her garment. He heard that she had come to the Messenger of Allah ﷺ, so he came with two sons of his from another wife. She said: By Allah, I have no complaint against him except that what he has is no more useful to me than this — and she took hold of a fringe of her garment. He said: She is lying, by Allah, O Messenger of Allah. I truly shake her like leather is shaken, but she is disobedient and wants Rifaʿah. So the Messenger of Allah ﷺ said: “If that is the case, then you are not lawful for him — or: you are not fit for him — until he tastes your sweetness.” Then he saw two sons with him and said: “Are these your sons?” He said: Yes. He said: “Yet this is what she claims? By Allah, they resemble him more than one crow resembles another crow.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5825,"lafz":true}],"full":1,"rep":[6489]},{"num":6580,"demo":false,"sanad":"","matn":["عَنِ الزُّبَيْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الزَّبِيرِ، أَنَّ رِفَاعَةَ بْنَ سِمْوَالٍ، طَلَّقَ امْرَأَتَهُ تَمِيمَةَ بِنْتَ وَهْبٍ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  ثَلاَثًا فَنَكَحَتْ عَبْدَ الرَّحْمَنِ بْنَ الزَّبِيرِ فَاعْتَرَضَ عَنْهَا فَلَمْ يَسْتَطِعْ أَنْ يَمَسَّهَا فَفَارَقَهَا فَأَرَادَ رِفَاعَةُ أَنْ يَنْكِحَهَا - وَهُوَ زَوْجُهَا الأَوَّلُ الَّذِي كَانَ طَلَّقَهَا - فَذَكَرَ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَنَهَاهُ عَنْ تَزْوِيجِهَا وَقَالَ لاَ تَحِلُّ لَكَ حَتَّى تَذُوقَ الْعُسَيْلَةَ."],"takhrij":"حسن: رواه ابن الجارود في المنقى (682) عن محمد بن عبد الله بن عبد الحكم، أن ابن وهب أخبرهم قال: أخبرني مالك بن أنس، عن المسور بن رفاعة القرظي، عن الزبير بن عبد الرحمن بن الزَّبِيرِ، عن أبيه فذكره. وهذا إسناده حسن.","grade":"حسن","chapter_ar":"باب لا تحل المبتوتة حتى تنكح زوجا غيره","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn al-Jarud in al-Muntaqa (682).","chapter_en":"The Woman Irrevocably Divorced Does Not Become Lawful Until She Marries Another Husband","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Al-Zubayr ibn ʿAbd al-Rahman ibn al-Zubayr narrated from his father that Rifaʿah ibn Samwal divorced his wife Tamimah bint Wahb during the time of the Messenger of Allah ﷺ. Then ʿAbd al-Rahman ibn al-Zubayr married her, but he turned away from her and was unable to have intercourse with her. Then he divorced her without touching her. Rifaʿah wanted to marry her again, and he was the husband who had divorced her before ʿAbd al-Rahman. This was mentioned to the Messenger of Allah ﷺ, and he forbade him from marrying her, saying: “She is not lawful for you until you taste the sweetness.”"]},"buhuth":{"en":["After gathering these narrations, the following conclusions are drawn:","The woman did not enable him to have intercourse, or something prevented him from it, such as illness or something similar.","The man was not impotent, because if his impotence had been established before the Prophet ﷺ, he would not have instructed that each of them must taste the other’s sweetness.","As for the woman’s statement in the Two Sahihs — al-Bukhari (5265) and Muslim (1433 no. 114) — “He did not approach me except once,” this is in the wording of al-Bukhari and not mentioned by Muslim. In a narration with Ahmad (25920): “except one leap,” and “leap” refers to the mounting of the male and his attempt at intercourse. Its meaning is that he approached her one time, as explained by al-Khattabi in Gharib al-Hadith (1/546).","The apparent wording of the prophetic report seems to oppose this, because the Prophet ﷺ said: “until you taste his sweetness and he tastes your sweetness.” If the man had actually managed intercourse even once, the Prophet ﷺ would not have given this instruction, but would have allowed her to return after his divorce.","So the correct meaning — and Allah knows best — is that this one attempt did not produce the known “sweetness” that is sufficient for the divorce to count as making her lawful again for the first husband. It is as though the man attempted intercourse, but a temporary weakness occurred, so the Prophet ﷺ instructed her to wait until he tastes her sweetness and she tastes his.","And impotence was negated from him, due to the proof in the Prophet’s saying: “This one about whom you claim what you claim — by Allah, they resemble him more than one crow resembles another.”","“ʿUsaylah” is the diminutive of honey, and what is meant is the sweetness of intercourse. It may be that the man ejaculated before full penetration, so he did not taste the sweetness of his wife, just as she did not taste his sweetness.","The scholars among the Companions of the Prophet ﷺ and others acted upon this hadith, that the intercourse of the second husband does not make the woman lawful for the first husband unless it takes place with full arousal. If it is not so, or if the husband is impotent, or is a child, then it is not sufficient according to the sounder of the two scholarly opinions.","His saying, “until you taste his sweetness…” is a figurative expression for intercourse, which means the entry of the tip of the man’s organ into the woman’s private part, whether ejaculation occurs or not. The “tasting” is achieved by mere penetration, even though its completion is only with ejaculation.","And in his saying, “until you taste his sweetness and he tastes your sweetness,” there is an indication that both spouses share in experiencing the pleasure of intercourse. For this reason, some scholars said that if he had intercourse with her while she was asleep or unconscious, she would not become lawful for the first husband, because she did not taste the sweetness since she did not perceive it.","These hadiths specify the general wording of Allah’s statement, “until she marries another husband.” A mere marriage contract can be described as marriage, yet no scholar held that the mere contract makes her lawful to return to the first husband except Saʿid ibn al-Musayyib, who held that the contract alone permits her return to the first husband. The majority held that the pleasure of intercourse must occur, whether ejaculation takes place or not; al-Hasan al-Basri alone stipulated ejaculation.","And the phrase “the fringe of a garment” means the edge of a garment, and it is a figurative expression meaning that the man’s organ was like a limp fringe, without firmness or arousal."]}},"tuhfa":{},"refs":[{"key":"sh13071","label":"ابن الجارود في المنتقى","number":682,"lafz":true,"n":709}],"full":1,"dr":1},{"num":6581,"demo":false,"sanad":"","matn":["عَنْ عُبَيْدِ اللَّهِ بْنِ الْعَبَّاسِ، قَالَ: جَاءَتِ الْغُمَيْصَاءُ - أَوِ الرُّمَيْصَاءُ - إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، تَشْكُو زَوْجَهَا، وَتَزْعُمُ أَنَّهُ لَا يَصِلُ إِلَيْهَا، فَمَا كَانَ إِلا يَسِيرًا. حَتَّى جَاءَ زَوْجُهَا، فَزَعَمَ أَنَّهَا كَاذِبَةٌ، وَلَكِنَّهَا تُرِيدُ أَنْ تَرْجِعَ إِلَى زَوْجِهَا الْأَوَّلِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَيْسَ لَكِ ذَلِكَ حَتَّى يَذُوقَ عُسَيْلَتَكِ رَجُلٌ غَيْرُهُ."],"takhrij":"صحيح: رواه النسائي (3411) وأحمد (1837) كلاهما من حديث هُشيم، قال: أنبانا يحيى بن أبي إسحاق، عن سليمان بن يسار، عن عبـيدالله بن العباس فذكره.","grade":"صحيح","chapter_ar":"باب لا تحل المبتوتة حتى تنكح زوجا غيره","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3413) and Ahmad (1837), and this is the wording of Ahmad.","chapter_en":"The Woman Irrevocably Divorced Does Not Become Lawful Until She Marries Another Husband","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["ʿUbayd Allah ibn ʿAbbas said: Al-Ghumaysa’ — or al-Rumaysa’ — came to the Messenger of Allah ﷺ complaining about her husband, claiming that he could not reach her. It was only a short while before her husband came and claimed that she was lying, but that she wanted to return to her first husband. So the Messenger of Allah ﷺ said: “That is not possible for you until another man tastes your sweetness.”"]},"buhuth":{"en":["In the wording of al-Nasa’i: “No, not until another man tastes her sweetness as the first did,” and its chain is authentic."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3413,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":1837,"n":1837},{"key":"nasai","label":"النسائي","number":3411}],"full":1,"dr":1},{"num":6582,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ رَجُلٍ طلّق امْرَأَتَهُ الْبَتَّةَ، - يَعْنِي ثَلَاثًا، فَتَزَوَّجَتْ رَجُلًا، فَطَلَّقَهَا قَبْلَ أَنْ يَدْخُلَ بِهَا، أَتَرْجِعُ إِلَى الْأَوَّلِ؟ فَقَالَ: لَا حَتَّى يَذُوقَ مِنْ عُسَيْلَتِهَا مَا ذَاقَ صَاحِبُهُ."],"takhrij":"صحيح: رواه أبو يعلى (4066) عن عبد الله بن عمر، حدثنا يحيى بن زكريا، عن يحيى بن سعيد، عن نافع، عن ابن عمر مثله.","grade":"صحيح","chapter_ar":"باب لا تحل المبتوتة حتى تنكح زوجا غيره","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Yaʿla (4066).","chapter_en":"The Woman Irrevocably Divorced Does Not Become Lawful Until She Marries Another Husband","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["ʿAbd Allah ibn ʿUmar narrated that the Messenger of Allah ﷺ was asked about a man who divorced his wife completely — meaning three times — then she married another man, and he divorced her before consummating the marriage. Would she return to the first husband? He said: “No, not until he tastes from her sweetness what the first husband tasted.”"]}},"tuhfa":{},"refs":[{"key":"sh12520","label":"أبو يعلى","number":4066,"lafz":true},{"key":"sh12520","label":"مسند أبي يعلى","number":4964,"n":4969}],"full":1,"dr":1},{"num":6583,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَدَّ ابْنَتَهُ عَلَى أَبِي الْعَاصِ بْنِ الرَّبِيعِ بَعْدَ سَنَتَيْنِ بِنِكَاحِهَا الأَوَّلِ.","وفي رواية: بعد ست سنين."],"takhrij":"حسن: رواه أبو داود (2240) والترمذي (1144،1143) وابن ماجة (2009) وأحمد (1876) والحاكم (3/237) كلهم من حديث محمد بن إسحاق، عن داود بن الحصين، عن عكرمة، عن ابن عباس، فذكره.","grade":"حسن","chapter_ar":"باب إذا أسلم أحد الزوجين وتأخر الآخر","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2240), al-Tirmidhi (1143, 1144), Ibn Majah (2009), and Ahmad (1876).","chapter_en":"If One of the Spouses Accepts Islam and the Other Delays","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["Ibn ʿAbbas narrated that the Messenger of Allah ﷺ returned his daughter to Abu al-ʿAs ibn al-Rabiʿ after two years with her first marriage contract. In another narration: after six years."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2240,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1143},{"key":"ibnmajah","label":"ابن ماجه","number":2009},{"key":"ahmad","label":"مسند الإمام أحمد","number":1876,"n":1876},{"key":"tirmidhi","label":"الترمذي","number":1144}],"full":1,"dr":1},{"num":6584,"demo":false,"sanad":"","matn":["عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ، أَنَّ امْرَأَةً، جَاءَتْ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَسْلَمَتْ. فَتَزَوَّجَهَا رَجُلٌ. قَالَ فَجَاءَ زَوْجُهَا الأَوَّلُ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي قَدْ كُنْتُ أَسْلَمْتُ مَعَهَا وَعَلِمَتْ بِإِسْلاَمِي. قَالَ فَانْتَزَعَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ زَوْجِهَا الآخَرِ وَرَدَّهَا إِلَى زَوْجِهَا الأَوَّلِ."],"takhrij":"حسن: رواه أبو داود (2239،2238) والترمذي (1144) وابن ماجة (2008) وابن حبان (4159) وابن الجارود (757) والحاكم (2/200) كلهم من حديث سماك، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب إذا أسلم أحد الزوجين وتأخر الآخر","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2238, 2239), al-Tirmidhi (1144), who authenticated it, Ibn Majah (2008), and Ibn Hibban (4159).","chapter_en":"If One of the Spouses Accepts Islam and the Other Delays","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["ʿAbd Allah ibn ʿAbbas narrated that a woman came to the Prophet ﷺ and accepted Islam, then another man married her. Her first husband came and said: “O Messenger of Allah, I had accepted Islam with her, and she knew of my Islam.” So the Messenger of Allah ﷺ took her away from the second husband and returned her to the first husband."]},"buhuth":{"en":["Al-Hafiz Ibn al-Qayyim said in Zad al-Maʿad (5/137): “We do not know of anyone who renewed a marriage because of Islam at all. Rather, what actually occurred was one of two things: either they separated and she married someone else, or she remained with him even if her Islam or his Islam came later.” For more, see al-Minnah al-Kubra (6/180)."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2238,"lafz":true,"n":2239},{"key":"tirmidhi","label":"الترمذي","number":1144},{"key":"ibnmajah","label":"ابن ماجه","number":2008},{"key":"abudawud","label":"ابو داود","number":2239},{"key":"ibnhibban","label":"ابن حبان","number":4159},{"key":"sh13071","label":"ابن الجارود","number":757}],"full":1,"dr":1},{"num":6585,"demo":false,"sanad":"","matn":["عن رَافِعِ بن سنان أَنَّهُ أَسْلَمَ وَأَبَتِ امْرَأَتُهُ أَنْ تُسْلِمَ فَأَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتِ ابْنَتِي وَهِيَ فَطِيمٌ أَوْ شِبْهُهُ وَقَالَ رَافِعٌ ابْنَتِي. فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اقْعُدْ نَاحِيَةً. وَقَالَ لَهَا اقْعُدِي نَاحِيَةً. قَالَ وَأَقْعَدَ الصَّبِيَّةَ بَيْنَهُمَا ثُمَّ قَالَ ادْعُوَاهَا. فَمَالَتِ الصَّبِيَّةُ إِلَى أُمِّهَا فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اللَّهُمَّ اهْدِهَا. فَمَالَتِ الصَّبِيَّةُ إِلَى أَبِيهَا فَأَخَذَهَا."],"takhrij":"صحيح: رواه أبو داود (2244) وأحمد (2375) والحاكم (2/206) وعنه البيقهي (8/3) كلهم من طرق عن عيسى بن يونس، أخبرنا عبد الحميد بن جعفر، أخبرني عن جدي رافع بن سنان فذكره.","grade":"صحيح","chapter_ar":"باب إذا أسلم أحد الأبوين مع من يكون الولد","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2244), Ahmad (23757), al-Hakim (2/206), and al-Bayhaqi (8/3).","chapter_en":"If One of the Parents Accepts Islam, With Whom Does the Child Remain","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Rafiʿ ibn Sinan accepted Islam, but his wife refused to accept Islam. She came to the Prophet ﷺ and said: “My daughter — and she is newly weaned,” or something similar. Rafiʿ said: “My daughter.” The Prophet ﷺ said to him: “Sit to one side,” and to her: “Sit to one side,” and he seated the young girl between them. Then he said: “Call her.” The child inclined toward her mother. So the Prophet ﷺ said: “O Allah, guide her.” Then she inclined toward her father, and he took her."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2244,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":3},{"key":"ahmad","label":"مسند الإمام أحمد","number":23757,"n":23757},{"key":"hakim","label":"المستدرك على الصحيحين","number":2828,"n":2814},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":15760,"n":15918},{"key":"ahmad","label":"احمد","number":2375}],"full":1,"dr":1},{"num":6586,"demo":false,"sanad":"","matn":["عَنْ أَبِي ميمونة سُلمى – مولى من أَهْلِ الْمَدِينَةِ، رَجُلَ صِدْقٍ- قَالَ: بَيْنَمَا أَنَا جَالِسٌ مَعَ أَبِي هُرَيْرَةَ، جَاءَتْ امْرَأَةٌ فَارِسِيَّةٌ مَعَهَا ابْنٌ لَهَا فَادَّعَيَاهُ. وَقَدْ طَلَّقَهَا زَوْجُهَا فَقَالَتْ: يَا أَبَا هُرَيْرَةَ – وَرَطَنَتْ بِالْفَارِسِيَّةِ – زَوْجِي يُرِيدُ أَنْ يَذْهَبَ بِابْنِي؟ فَقَالَ أَبُو هُرَيْرَةَ: اسْتَهِمَا عَلَيْهِ. وَرَطَنَ لَهَا بِذَلِكَ. فَجَاءَ زَوْجُهَا فَقَالَ: مَنْ يُحَاقِّني فِي وَلَدِي؟ فَقَالَ أَبُو هُرَيْرَةَ: اللَّهُمَّ إِنِّي لاَ أَقُولُ هَذَا إِلاَّ أَنِّي سَمِعْتُ امْرَأَةً جَاءَتْ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا قَاعِدٌ عِنْدَهُ– فَقَالَتْ: يَا رَسُولَ اللَّهِ! إِنَّ زَوْجِي يُرِيدُ أَنْ يَذْهَبَ بِابْنِي، وَقَدْ سَقَانِي مِنْ بِئْرِ أَبِي عِنَبَةَ، وَقَدْ نَفَعَنِي. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اسْتَهِمَا عَلَيْهِ فَقَالَ زَوْجُهَا: مَنْ يُحَاقِّني فِي وَلَدِي؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَذَا أَبُوكَ، وَهَذِهِ أُمُّكَ، فَخُذْ بِيَدِ أَيِّهِمَا شِئْتَ فَأَخَذَ بِيَدِ أُمِّهِ فَانْطَلَقَتْ بِهِ."],"takhrij":"صحيح: رواه أبو داود (2277) والنسائي (3496) وصحّحه الحاكم (4/97) والبيهقي (38) كلهم من حديث ابن جريج، قال: أخبرني زياد، عن هلال بن أسامة، أن أبا ميمونة سُلمى قال: فذكره.","grade":"صحيح","chapter_ar":"باب تخيير الصبي بين أبويه الذين اقترقا","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2277), al-Nasa’i (3496), and authenticated by al-Hakim (4/97). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"Giving a Child the Choice Between His Separated Parents","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":20,"content":{"translation":{"en":["Abu Maymunah Sulma — a client from the people of Madinah and a truthful man — said: While I was sitting with Abu Hurayrah, a Persian woman came with a son of hers, and both parents claimed him. Her husband had divorced her, and she said, speaking in Persian: “My husband wants to take my son.” Abu Hurayrah said: “Draw lots over him,” and he said that to her in Persian. Then her husband came and said: “Who will dispute with me about my child?” Abu Hurayrah said: O Allah, I only say this because I heard a woman come to the Messenger of Allah ﷺ while I was sitting with him, and she said: “O Messenger of Allah, my husband wants to take my son, though he has given me water from the well of Abu ʿInabah and benefited me.” The Messenger of Allah ﷺ said: “Draw lots over him.” Her husband said: “Who will dispute with me about my child?” So the Prophet ﷺ said: “This is your father, and this is your mother, so take the hand of whichever of them you wish.” So he took his mother’s hand, and she left with him."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2277,"lafz":true},{"key":"nasai","label":"النسائي","number":3496},{"key":"hakim","label":"صحّحه الحاكم","number":97},{"key":"kubrabayhaqi","label":"البيهقي","number":38}],"full":1,"dr":1},{"num":6587,"demo":false,"sanad":"","matn":["عن عَمْرِو بْنِ شُعَيْبٍ عَنْ أَبِيهِ، عَنْ جَدِّهِ عَبْدِ اللَّهِ بْنِ عَمْرٍو، أَنَّ امْرَأَةً، قَالَتْ يَا رَسُولَ اللَّهِ إِنَّ ابْنِي هَذَا كَانَ بَطْنِي لَهُ وِعَاءً وَثَدْيِي لَهُ سِقَاءً وَحِجْرِي لَهُ حِوَاءً وَإِنَّ أَبَاهُ طَلَّقَنِي وَأَرَادَ أَنْ يَنْتَزِعَهُ مِنِّي فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْتِ أَحَقُّ بِهِ مَا لَمْ تَنْكِحِي."],"takhrij":"حسن: رواه أبو داود (2276) وأحمد (6707) والدارقطني (3/305) والحاكم (2/207) وعنه البيقهي (8/4-5) كلهم من طرق عن عمرو بن شعيب، عن أبيه، عن جده فذكره. قال الحاكم: \"صحيح الإسناد\".","grade":"حسن","chapter_ar":"باب حضانة الأم المطلقة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2276), Ahmad (6707), al-Daraqutni (3/305), al-Hakim (2/207), and al-Bayhaqi (8/4–5), all through routes from ʿAmr ibn Shuʿayb, from his father, from his grandfather.","chapter_en":"The Custody of the Divorced Mother","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["ʿAbd Allah ibn ʿAmr ibn al-ʿAs narrated that a woman said: “O Messenger of Allah, this son of mine — my womb was a vessel for him, my breasts were a drink for him, and my lap was a shelter for him. But now his father has divorced me and wants to take him away from me.” So the Messenger of Allah ﷺ said: “You have more right to him so long as you do not marry.”"]},"buhuth":{"en":["There is no disagreement among the scholars that the mother has custody of the child so long as she does not marry. If she marries, then she no longer has the right of custody.","If her mother is present, then her mother takes her place, and then the maternal grandmothers have more right to him, so long as even one of them remains."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2276,"lafz":true},{"key":"sh9771","label":"الدار قطني","number":305},{"key":"kubrabayhaqi","label":"وعن البيهقي","number":5},{"key":"ahmad","label":"مسند الإمام أحمد","number":6707,"n":6707},{"key":"hakim","label":"المستدرك على الصحيحين","number":2830,"n":2816},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":15763,"n":15921}],"full":1,"dr":1},{"num":6588,"demo":false,"sanad":"","matn":["عَنْ الْبَرَاءِ قَالَ: اعْتَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي ذِي الْقَعْدَةِ... الحديث وَفِيهِ قصة ابْنَةُ حَمْزَةَ وأنها تبعتهم حِينَ الخروج مِنْ مَكَّةَ، فَتَنَاوَلَهَا عليّ فَأَخَذَ بِيَدِهَا وَقَالَ لِفَاطِمَةَ: دُونَكِ ابْنَةَ عَمِّكِ احْمِلِيهَا، فَاخْتَصَمَ فِيهَا عَلِيٌّ، وَزَيْدٌ، وَجَعْفَرٌ، فَقَالَ عَلِيٌّ: أَنَا أَحَقُّ بِهَا، وهي ابْنَةُ عَمِّي، وَقَالَ جَعْفَرٌ: ابْنَةُ عَمِّي وَخَالَتُهَا تَحْتِي، وَقَالَ زَيْدٌ: ابْنَةُ أَخِي، فَقَضَى بِهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِخَالَتِهَا وَقَالَ: الْخَالَةُ بِمَنْزِلَةِ الأُمِّ وَقَالَ لِعَلِيٍّ: أَنْتَ مِنِّي وَأَنَا مِنْكَ وَقَالَ لِجَعْفَرٍ: أَشْبَهْتَ خَلْقي وخُلُقي، وَقَالَ لِزَيْدٍ: أَنْتَ أَخُونَا وَمَوْلاَنَا."],"takhrij":"صحيح: رواه البخاري في الصلح (2699) عن عبيد الله بن موسى، عن إسرائيل، عن أبي إسحاق، عن البراء قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في حضانة الخالة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2699).","chapter_en":"What Has Been Reported Regarding the Maternal Aunt Having Custody","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Al-Barāʾ reported: The Prophet ﷺ performed ʿUmrah in Dhū al-Qaʿdah… the hadith includes the story of Ḥamzah’s daughter, who followed them as they were leaving Makkah. ʿAlī took hold of her hand and said to Fāṭimah: “Here is your cousin; take her.” Then ʿAlī, Zayd, and Jaʿfar disputed over who should have custody of her. ʿAlī said: “I have the greatest right to her, for she is my paternal uncle’s daughter.” Jaʿfar said: “She is my paternal uncle’s daughter, and her maternal aunt is my wife.” Zayd said: “She is my brother’s daughter.” The Prophet ﷺ awarded her custody to her maternal aunt and said: “The maternal aunt is in the position of the mother.” He said to ʿAlī: “You are from me and I am from you.” He said to Jaʿfar: “You resemble me in appearance and character.” And he said to Zayd: “You are our brother and our freedman.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2699,"lafz":true}],"full":1,"rep":[10042]},{"num":6589,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ، قَالَ: لَمَّا خَرَجْنَا مِنْ مَكَّةَ اتَّبَعَتْنَا ابْنَةُ حَمْزَةَ تُنَادِي: يَا عَمِّ، يَا عَمِّ. قَالَ: فَتَنَاوَلْتُهَا بِيَدِهَا، فَدَفَعْتُهَا إِلَى فَاطِمَةَ، فَقُلْتُ: دُونَكِ ابْنَةَ عَمِّكِ. قَالَ: فَلَمَّا قَدِمْنَا الْمَدِينَةَ اخْتَصَمْنَا فِيهَا أَنَا وَجَعْفَرٌ وَزَيْدُ بْنُ حَارِثَةَ، فَقَالَ جَعْفَرٌ: ابْنَةُ عَمِّي وَخَالَتُهَا عِنْدِي - يَعْنِي أَسْمَاءَ بِنْتَ عُمَيْسٍ - وَقَالَ زَيْدٌ: ابْنَةُ أَخِي. وَقُلْتُ: أَنَا أَخَذْتُهَا وَهِيَ ابْنَةُ عَمِّي. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَمَّا أَنْتَ يَا جَعْفَرُ، فَأَشْبَهْتَ خَلْقِي وَخُلُقِي، وَأَمَّا أَنْتَ يَا عَلِيُّ، فَمِنِّي وَأَنَا مِنْكَ، وَأَمَّا أَنْتَ يَا زَيْدُ، فَأَخُونَا وَمَوْلَانَا، وَالْجَارِيَةُ عِنْدَ خَالَتِهَا، فَإِنَّ الْخَالَةَ وَالِدَةٌ قُلْتُ: يَا رَسُولَ اللَّهِ، أَلَا تَزَوَّجُهَا؟ قَالَ: إِنَّهَا ابْنَةُ أَخِي مِنَ الرَّضَاعَةِ."],"takhrij":"حسن: رواه أبو داود (2280) وأحمد (770)، وصحّحه الحاكم (3/120) كلهم من طريق أبي إسحاق، عن هانئ بن هانئ وهبيرة بن يريم، عن علي فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في حضانة الخالة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2280) and Ahmad (770), and authenticated by al-Hakim (3/120).","chapter_en":"What Has Been Reported Regarding the Maternal Aunt Having Custody","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["ʿAli said: When we left Makkah, Hamzah’s daughter followed us calling, “O uncle, O uncle.” He said: So I took her by the hand and handed her to Fatimah, saying: “Take your cousin.” When we arrived in Madinah, Jaʿfar, Zayd ibn Harithah, and I disputed over her. Jaʿfar said: “She is my uncle’s daughter, and her maternal aunt is with me,” meaning Asma’ bint ʿUmays. Zayd said: “She is my brother’s daughter.” And I said: “I took her, and she is my uncle’s daughter.” So the Messenger of Allah ﷺ said: “As for you, Jaʿfar, you resemble me in appearance and character. As for you, ʿAli, you are from me and I am from you. As for you, Zayd, you are our brother and our freedman. The girl is with her maternal aunt, for the maternal aunt is like a mother.” I said: “O Messenger of Allah, will you not marry her?” He said: “She is the daughter of my brother through breastfeeding.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2280,"lafz":true},{"key":"hakim","label":"صحّحه الحاكم","number":120},{"key":"ahmad","label":"مسند الإمام أحمد","number":770,"n":770}],"full":1,"dr":1,"rep":[10043]},{"num":6590,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ قَالَ فِي هَذِهِ الآية: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا يَحِلُّ لَكُمْ أَنْ تَرِثُوا النِّسَاءَ كَرْهًا وَلَا تَعْضُلُوهُنَّ﴾ [سورة النساء: 19] [النِّسَاءَ: ١٩] كَانُوا إِذَا مَاتَ الرَّجُلُ كَانَ أَوْلِيَاؤُهُ أحقّ بِامْرَأَتِهِ. إِنْ شَاءَ بَعْضُهُمْ تَزَوَّجَهَا، وَإِنْ شاؤوا زوّجوها، وَإِنْ شاؤوا لَمْ يُزوّجوها، فَهُمْ أَحَقُّ بِهَا مِنْ أَهْلِهَا. فَنَزَلَتْ هَذِهِ الآيَةُ بِذَلِكَ."],"takhrij":"صحيح: رواه البخاري في الإكراه (6948)، عن حسين بن منصور، حدثنا أسباط بن محمد، حدثنا الشيباني سليمان بن فيروز، عن عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب قوله تعالى: ( لَا يَحِلَّ لَكُمْ أَن تَرِنُواْ النِّسَآءَ كَرَهَا وَلَا تَتْضُلُوهُنَّ (التساء: ١٩)","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6948).","chapter_en":"The Saying of Allah the Exalted: “It is not lawful for you to inherit women by compulsion, nor should you prevent them” [al-Nisa’: 19]","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":23,"content":{"translation":{"en":["Ibn ʿAbbas said regarding this verse, “O you who believe, it is not lawful for you to inherit women by compulsion, nor should you prevent them” [al-Nisa’: 19]: When a man died, his heirs had more right to his wife. If one of them wished, he married her. If they wished, they married her off. If they wished, they did not marry her off at all. They had more right to her than her own family, so this verse was revealed concerning that."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6948,"lafz":true}],"full":1,"dr":1},{"num":6591,"demo":false,"sanad":"","matn":["عن مَعْقِلِ بن يَسَارٍ كَانَتْ أُخْتُهُ تَحْتَ رَجُلٍ فَطَلَّقَهَا، ثُمَّ خَلَّى عَنْهَا حَتَّى انْقَضَتْ عِدَّتُهَا، ثُمَّ خَطَبَهَا فَحَمِيَ مَعْقِلٌ مِنَ ذَلِكَ أَنَفًا فَقَالَ خَلَّى عَنْهَا وَهْوَ يَقْدِرُ عَلَيْهَا، ثُمَّ يَخْطُبُهَا فَحَالَ بَيْنَهُ وَبَيْنَهَا، فَأَنْزَلَ اللَّهُ ﴿وَإِذَا طَلَّقْتُمُ النِّسَاءَ فَبَلَغْنَ أَجَلَهُنَّ فَلاَ تَعْضُلُوهُنَّ﴾ [سورة البقرة: 232]} إِلَى آخِرِ الآيَةِ، فَدَعَاهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَرَأَ عَلَيْهِ، فَتَرَكَ الْحَمِيَّةَ وَاسْتَقَادَ لأَمْرِ اللَّهِ."],"takhrij":"صحيح: رواه البخاري في الطلاق (5331) عن محمد بن المثنى، حدثنا عبد الأعلى، حدثنا سعيد، عن قتادة، حدثنا الحسن، أن معقل بن يسار قال: فذكره.","grade":"صحيح","chapter_ar":"باب قوله تعالى: ( لَا يَحِلَّ لَكُمْ أَن تَرِنُواْ النِّسَآءَ كَرَهَا وَلَا تَتْضُلُوهُنَّ (التساء: ١٩)","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5331).","chapter_en":"The Saying of Allah the Exalted: “It is not lawful for you to inherit women by compulsion, nor should you prevent them” [al-Nisa’: 19]","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":23,"content":{"translation":{"en":["Maʿqil ibn Yasar said: His sister was married to a man who divorced her, then left her until her waiting period ended. After that he proposed to her again, but Maʿqil became angry about that. He said: “He left her while he had the ability to keep her, then he comes to propose to her again?” So he prevented him from marrying her. Then Allah revealed: “And when you divorce women and they have reached the end of their waiting period, do not prevent them” [al-Baqarah: 232] to the end of the verse. The Messenger of Allah ﷺ called him and recited it to him, so he gave up his anger and submitted to the command of Allah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5331,"lafz":true}],"full":1},{"num":6592,"demo":false,"sanad":"","matn":["عن ابن عباس في قوله: ﴿مَا نَنْسَخْ مِنْ آيَةٍ أَوْ نُنْسِهَا نَأْتِ بِخَيْرٍ مِنْهَا أَوْ مِثْلِهَا﴾ [البقرة: ١٠٦] وقال: ﴿وَإِذَا بَدَّلْنَا آيَةً مَكَانَ آيَةٍ وَاللَّهُ أَعْلَمُ بِمَا يُنَزِّلُ﴾ [النحل: ١٠١] الآية وقال: ﴿يَمْحُو اللَّهُ مَا يَشَاءُ وَيُثْبِتُ وَعِنْدَهُ أُمُّ الْكِتَابِ﴾ [الرعد: ٣٩] فأول ما نسخ من القرآن القبلة، وقال: يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ ثَلَاثَةَ قُرُوءٍ [البقرة: ٢٢٨] وقال: ﴿وَاللَّائِي يَئِسْنَ مِنَ الْمَحِيضِ مِنْ نِسَائِكُمْ إِنِ ارْتَبْتُمْ فَعِدَّتُهُنَّ ثَلَاثَةُ أَشْهُرٍ﴾ [الطلاق:٤] فنسخ من ذلك فقال تعالى: ﴿ثُمَّ طَلَّقْتُمُوهُنَّ مِنْ قَبْلِ أَنْ تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا﴾ [الأحزاب: ٤٩]."],"takhrij":"حسن: رواه النسائي (3499) واللفظ له، وأبو داود (2282) كلاهما من حديث علي بن الحسين بن واقد، عن أبيه، عن يزيد النحوي، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب عدة المطلقات في صورها المختلفة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (3499), and this is his wording, and Abu Dawud (2282).","chapter_en":"The Waiting Period of Divorced Women in Their Different Situations","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":24,"content":{"translation":{"en":["Ibn ʿAbbas said regarding the verse, “Whatever verse We abrogate or cause to be forgotten, We bring one better than it or similar to it” [al-Baqarah: 106], and the verse, “And when We replace one verse with another — and Allah knows best what He sends down” [al-Nahl: 101], and the verse, “Allah erases what He wills and confirms, and with Him is the Mother of the Book” [al-Raʿd: 39]: The first thing to be abrogated from the Qur’an was the qiblah. And Allah said, “Divorced women shall wait by themselves for three menstrual cycles” [al-Baqarah: 228], and He said, “And those who have despaired of menstruation among your women, if you doubt, then their waiting period is three months” [al-Talaq: 4]. Then from that was excepted His saying: “Then if you divorce them before you have touched them, then there is no waiting period for you to count against them” [al-Ahzab: 49]."]},"intro":{"ar":["قال الله تعالى: ﴿وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ ثَلَاثَةَ قُرُوءٍ﴾ [البقرة: ٢٢٨]. هذه لعموم المطلقات.","وعِدّة الحامل المطلقة أو المتوفى عنها زوجها: ﴿وَأُولَاتُ الْأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ﴾ [الطلاق: ٤].","وعِدّة الآيسة والصغيرة: ﴿وَاللَّائِي يَئِسْنَ مِنَ الْمَحِيضِ مِنْ نِسَائِكُمْ إِنِ ارْتَبْتُمْ فَعِدَّتُهُنَّ ثَلَاثَةُ أَشْهُرٍ وَاللَّائِي لَمْ يَحِضْنَ﴾ [الطلاق: ٤].","وعِدّةُ المطلقة قبل الدخول بها: ( إِذَا نَكَحْتُمُ المُؤْمِنَٰتِ ثُمَّطَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةِ تَعْتَدُّونَهَا ) [الأحزاب: ٤٩]."],"en":["Allah the Exalted said: “Divorced women shall wait by themselves for three menstrual cycles” [al-Baqarah: 228], and this applies generally to divorced women.","The waiting period of a pregnant woman, whether divorced or whose husband has died, is: “And for those who are pregnant, their term is until they deliver their burdens” [al-Talaq: 4].","The waiting period of the woman who no longer menstruates and the young girl is: “And those of your women who have despaired of menstruation, if you doubt, then their waiting period is three months, as well as those who have not menstruated” [al-Talaq: 4].","The waiting period of a divorced woman before consummation is: “If you marry believing women and then divorce them before you have touched them, then there is no waiting period for you to count against them” [al-Ahzab: 49]."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3499,"lafz":true,"n":3499},{"key":"abudawud","label":"أبو داود","number":2282}],"full":1,"dr":1},{"num":6593,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ سَيِّدِي زَوَّجَنِي أَمَتَهُ وَهُوَ يُرِيدُ أَنْ يُفَرِّقَ بَيْنِي وَبَيْنَهَا. قَالَ فَصَعِدَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمِنْبَرَ فَقَالَ يَا أَيُّهَا النَّاسُ مَا بَالُ أَحَدِكُمْ يُزَوِّجَ عَبْدَهُ أَمَتَهُ ثُمَّ يُرِيدُ أَنْ يُفَرِّقَ بَيْنَهُمَا إِنَّمَا الطَّلاَقُ لِمَنْ أَخَذَ بِالسَّاقِ."],"takhrij":"حسن: رواه ابن ماجة (2081) عن محمد بن يحيى، قال: حدثنا يحيى بن عبدالله بن بكير، حدثنا ابن لهيعة، عن موسى بن أيوب الغافقي، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب طلاق العبد","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2081), al-Daraqutni (4/37), and al-Bayhaqi (7/360).","chapter_en":"The Divorce of a Slave","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":25,"content":{"translation":{"en":["Ibn ʿAbbas said: A man came to the Prophet ﷺ and said: “O Messenger of Allah, my master married me to his slave woman, and now he wants to separate me from her.” So the Messenger of Allah ﷺ ascended the pulpit and said: “O people, why is it that one of you marries his slave to his slave woman, then wants to separate them? Divorce belongs only to the one who has taken hold of the leg.”"]},"buhuth":{"en":["His statement, “Divorce belongs to the one who has taken hold of the leg,” means that divorce is the husband’s right, the one who has marital access to the woman, and it is not the right of the master."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2081,"lafz":true},{"key":"sh9771","label":"الدارقطني","number":37},{"key":"kubrabayhaqi","label":"البيهقي","number":360}],"full":1,"dr":1},{"num":6594,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن مَسْعُودٍ قَالَ: لَعَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ المُحِلّ والمُحَلَّل لَهُ."],"takhrij":"صحيح: رواه الترمذي (1120) والنسائي (3416) وأحمد (4248) والبيهقي (7/208) كلهم من حديث سفيان الثوري، عن أبي قيس، عن هُزيل، عن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في المحلّ والمحَلّل له","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1120), al-Nasa’i (3416), and Ahmad (4248). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"What Has Been Reported Regarding the Muhallil and the One for Whom He Is Made Muhallil","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":27,"content":{"translation":{"en":["Ibn Masʿud said: The Messenger of Allah ﷺ cursed the muhallil and the one for whom it is done."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1120,"lafz":true},{"key":"nasai","label":"النسائي","number":3416},{"key":"ahmad","label":"مسند الإمام أحمد","number":3737,"n":3737},{"key":"ahmad","label":"احمد","number":4248,"n":4327}],"full":1,"dr":1},{"num":6595,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: لَعَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ المُحِلّ وَالْمُحَلَّلَ لَهُ."],"takhrij":"حسن: رواه أحمد (8287) وابن الجارود (684) والبزار- كشف الأستار (1442) والبيهقي (7/208) والترمذي في العلل الكبير (1/437) من حديث عبد الله بن جعفر المخزومي، عن عثمان بن محمد الأخنسي، عن المقبري، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في المحلّ والمحَلّل له","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (8287), Ibn al-Jarud (684), al-Bazzar in Kashf al-Astar (1442), and al-Bayhaqi (7/208).","chapter_en":"What Has Been Reported Regarding the Muhallil and the One for Whom He Is Made Muhallil","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":27,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ cursed the muhallil and the one for whom it is done."]}},"tuhfa":{},"refs":[{"key":"sh13071","label":"ابن الجارود","number":684},{"key":"sh12862","label":"البزار - كشف الاستار","number":1442},{"key":"kubrabayhaqi","label":"البيهقي","number":208},{"key":"ahmad","label":"مسند الإمام أحمد","number":8287,"n":8287,"lafz":true}],"full":1,"dr":1},{"num":6596,"demo":false,"sanad":"","matn":["عن عُقْبَةَ بن عَامِرٍ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَلاَ أُخْبِرُكُمْ بِالتَّيْسِ الْمُسْتَعَارِ. قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ هُوَ الْمُحَلِّلُ لَعَنَ اللَّهُ الْمُحَلِّلَ وَالْمُحَلَّلَ لَهُ."],"takhrij":"حسن: رواه ابن ماجة (1936) عن يحيى بن عثمان بن صالح المصري قال: حدثنا أبي، قال: سمعت الليث بن سعد يقول: قال لي أبو مصعب مشرح بن هاعان، قال عقبة بن عامر فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في المحلّ والمحَلّل له","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (1936) and al-Hakim (2/198–199).","chapter_en":"What Has Been Reported Regarding the Muhallil and the One for Whom He Is Made Muhallil","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":27,"content":{"translation":{"en":["ʿUqbah ibn ʿAmir said: The Messenger of Allah ﷺ said: “Shall I not tell you about the billy goat hired for use?” They said: “Yes, O Messenger of Allah.” He said: “It is the muhallil. Allah has cursed the muhallil and the one for whom it is done.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":1936,"lafz":true},{"key":"hakim","label":"و الحاكم","number":199}],"full":1,"dr":1},{"num":6597,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بْنِ نَافِعٍ، عَنْ أَبِيهِ، أَنَّهُ قَالَ: جَاءَ رَجُلٌ إِلَى ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُ فَسَأَلَهُ عَنْ رَجُلٍ طَلَّقَ امْرَأَتَهُ ثَلَاثًا، فَتَزَوَّجَهَا أَخٌ لَهُ عَنْ غَيْرِ مُؤَامَرَةٍ مِنْهُ لِيُحِلَّهَا لِأَخِيهِ لَهُ تَحِلُّ لِلْأَوَّلِ قَالَ: لَا إِلَّا نِكَاحَ رَغْبَةٍ، كُنَّا نَعُدُّ هَذَا سِفَاحًا عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه الطبراني في الأوسط – مجمع البحرين (2367)، والحاكم (2/199) -وعنه البيهقي (7/208)- من طريق أبي غسان محمد بن مطرف، عن عمر بن نافع، عن أبيه قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في المحلّ والمحَلّل له","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tabarani in al-Awsat, Majmaʿ al-Bahrayn (2367), al-Hakim (2/199), and al-Bayhaqi (7/208).","chapter_en":"What Has Been Reported Regarding the Muhallil and the One for Whom He Is Made Muhallil","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":27,"content":{"translation":{"en":["Nafiʿ said: A man came to Ibn ʿUmar and asked him about a man who divorced his wife three times, then his brother married her without prior agreement with him in order to make her lawful again for his brother. Would she become lawful for the first husband? He said: “No, not unless it is a genuine marriage of desire. We used to regard this as fornication during the time of the Messenger of Allah ﷺ.”"]}},"tuhfa":{},"refs":[{"key":"sh1352","label":"الطبراني في الأوسط - مجمع البحرين","number":2367},{"key":"kubrabayhaqi","label":"البيهقي","number":208,"lafz":true},{"key":"hakim","label":"المستدرك على الصحيحين","number":2806,"n":2792},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":14189,"n":14326}],"full":1,"dr":1},{"num":6598,"demo":false,"sanad":"","matn":["عن ابن عباس قال: ﴿وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ ثَلَاثَةَ قُرُوءٍ وَلَا يَحِلُّ لَهُنَّ أَنْ يَكْتُمْنَ مَا خَلَقَ اللَّهُ فِي أَرْحَامِهِنَّ﴾ [البقرة:٢٢٨] وذلك أن الرجل كان إذا طلق امرأته فهو أحق برجعتها وإن طلقها ثلاثا، فنسخ ذلك فقال: الطَّلَاقُ مَرَّتَانِ [البقرة: ٢٢٩]"],"takhrij":"حسن: رواه أبو داود (2195) ومن طريقه البيهقي (7/337) والنسائي (3554) من حديث علي بن حسين بن واقد، عن أبيه، عن يزيد النحوي، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب نسخ المراجعة بعد التطليقات الثلاث","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2195), al-Bayhaqi (7/337), and al-Nasa’i (3554).","chapter_en":"The Abrogation of Taking Back One’s Wife After Three Divorces","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["Ibn ʿAbbas said regarding the verse, “Divorced women shall wait by themselves for three menstrual cycles, and it is not lawful for them to conceal what Allah has created in their wombs” [al-Baqarah: 228]: A man, if he divorced his wife, had more right to take her back even if he divorced her three times. Then that was abrogated by His saying: “Divorce is twice” [al-Baqarah: 229]."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2195,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":337},{"key":"nasai","label":"النسائي","number":3554,"n":3554},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":14975,"n":15122}],"full":1,"dr":1},{"num":6599,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُسَيْدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ خَرَجْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى انْطَلَقْنَا إِلَى حَائِطٍ يُقَالُ لَهُ الشَّوْطُ، حَتَّى انْتَهَيْنَا إِلَى حَائِطَيْنِ فَجَلَسْنَا بَيْنَهُمَا فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اجْلِسُوا هَا هُنَا. وَدَخَلَ وَقَدْ أُتِيَ بِالْجَوْنِيَّةِ، فَأُنْزِلَتْ فِي بَيْتٍ فِي نَخْلٍ فِي بَيْتٍ أُمَيْمَةُ بِنْتُ النُّعْمَانِ بْنِ شَرَاحِيلَ وَمَعَهَا دَايَتُهَا حَاضِنَةٌ لَهَا، فَلَمَّا دَخَلَ عَلَيْهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ هَبِي نَفْسَكِ لِي. قَالَتْ وَهَلْ تَهَبُ الْمَلِكَةُ نَفْسَهَا لِلسُّوقَةِ. قَالَ فَأَهْوَى بِيَدِهِ يَضَعُ يَدَهُ عَلَيْهَا لِتَسْكُنَ فَقَالَتْ أَعُوذُ بِاللَّهِ مِنْكَ. فَقَالَ قَدْ عُذْتِ بِمَعَاذٍ. ثُمَّ خَرَجَ عَلَيْنَا، فَقَالَ يَا أَبَا أُسَيْدٍ اكْسُهَا رَازِقِيَّتَيْنِ وَأَلْحِقْهَا بِأَهْلِهَا."],"takhrij":"صحيح: رواه البخاري في الطلاق (5255) أبي نعيم، حدثنا عبد الرحمن بن غَسيل، عن حمزة بن أبي أسيد، عن أبي أسيد فذكره.","grade":"صحيح","chapter_ar":"باب متعة المطلقة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5255).","chapter_en":"The Consolatory Gift for a Divorced Woman","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Abu Usayd said: We went out with the Prophet ﷺ until we came to a garden called al-Shawt. When we reached two gardens, he sat between them and said: “Sit here.” Then he entered, and al-Jawniyyah had been brought and lodged in a house among date palms in the home of Umaymah bint al-Nuʿman ibn Sharahil, with her nurse caring for her. When the Prophet ﷺ entered upon her, he said: “Give yourself to me.” She said: “Does a queen give herself to a commoner?” He then moved his hand toward her to calm her. She said: “I seek refuge in Allah from you.” He said: “You have sought refuge with the One who grants refuge.” Then he came out to us and said: “O Abu Usayd, clothe her in two Raziqi garments (white linen garments) and send her back to her family.”"]},"buhuth":{"en":["The word داية is an Arabized term used for a nurse or midwife. What is meant here is the woman who was with her to arrange her affairs. Her statement للسوقة means: to one of the common people. She did not know that he was the Prophet of Allah ﷺ. When she later learned that, she regretted it and said: “I was deceived, and I am wretched.”"]},"intro":{"ar":["قال الله تعالى: ﴿وَلِلْمُطَلَّقَاتِ مَتَاعٌ بِالْمَعْرُوفِ حَقًّا عَلَى الْمُتَّقِينَ﴾ [البقرة: ٢٤١]."],"en":["Allah the Exalted said: “And for divorced women is a provision according to what is fair, a duty upon the righteous.” [al-Baqarah: 241]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5255,"lafz":true}],"full":1,"dr":1,"rep":[13084]},{"num":6600,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَمَّا طَلَّقَ حَفْصُ بْنُ الْمُغِيرَةِ امْرَأَتَهُ فَاطِمَةَ فَأَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لِزَوْجِهَا: مَتِّعْهَا قَالَ: لَا أَجِدُ مَا أُمَتِّعُهَا، قَالَ: فَإِنَّهُ لَا بُدَّ مِنَ الْمَتَاعِ قَالَ: مَتِّعْهَا وَلَوْ نِصْفِ صَاعٍ مِنْ تَمْرٍ."],"takhrij":"حسن: رواه البيهقي (7/257) عن أبي عبدالله الحافظ، أنبا أبو بكر أحمد بن إسحاق، أنبا علي بن عبدالصمد، ثنا أبو همام الوليد بن شجاع السكوني، ثنا مصعب بن سلَّام، ثنا شعبة، عن عبدالله بن محمد بن عقيل، عن جابر، فذكره.","grade":"حسن","chapter_ar":"باب متعة المطلقة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bayhaqi (7/257).","chapter_en":"The Consolatory Gift for a Divorced Woman","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Jabir ibn ʿAbd Allah said: When Hafs ibn al-Mughirah divorced his wife Fatimah, she came to the Prophet ﷺ, and he said to her husband: “Give her a parting gift.” He said: “I do not find anything with which to give her a gift.” He said: “A gift is still necessary.” He said: “Give her a gift, even if it is half a saʿ of dates.”"]},"buhuth":{"en":["Saʿid ibn al-Musayyib said: ʿUmar and ʿUthman ruled concerning the missing person that his wife should wait for four years, then observe a waiting period of four months and ten days after that, and then she may marry. If her first husband returns, he is given the choice between the dowry and his wife.","Narrated by ʿAbd al-Razzaq (12317) from Maʿmar, from al-Zuhri, from Ibn al-Musayyib with this wording. Its chain is authentic.","This is the strongest report narrated in this chapter, and this was also the view of Ibn ʿUmar, Ibn ʿAbbas, and Ibn Masʿud. Ibn al-Mundhir chose setting a time period because five of the Companions agreed upon it.","The period is counted from the day the matter is presented to the judge, and this time period mentioned by ʿUmar and ʿUthman applies to journeys in which safety is usually expected.","As for when he goes out for fighting, Saʿid ibn al-Musayyib said: “If he goes missing in battle lines, she waits one year, and if he goes missing outside battle lines, then four years.” Narrated by ʿAbd al-Razzaq (12326) from al-Thawri, from Dawud ibn Abi Hind, from Ibn al-Musayyib. Its chain is also authentic.","Some scholars said that setting the time period returns to the judgment of the ruler.","The Malikis hold that if the woman marries after the end of her waiting period, then the first husband returns, he has no right over her.","There is disagreement among the scholars on this matter, and its detailed discussion is found in the books of fiqh.","For more, see: al-Minnah al-Kubra (6/481)."]}},"tuhfa":{},"refs":[{"key":"kubrabayhaqi","label":"البيهقي","number":257,"lafz":true},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":14493,"n":14638}],"full":1,"dr":1},{"num":6601,"demo":false,"sanad":"","matn":["عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ،. أَنَّ امْرَأَةَ، ثَابِتِ بْنِ قَيْسٍ أَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ يَا رَسُولَ اللَّهِ ثَابِتُ بْنُ قَيْسٍ مَا أَعْتُبُ عَلَيْهِ فِي خُلُقٍ وَلاَ دِينٍ، وَلَكِنِّي أَكْرَهُ الْكُفْرَ فِي الإِسْلاَمِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَتَرُدِّينَ عَلَيْهِ حَدِيقَتَهُ. قَالَتْ نَعَمْ. قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اقْبَلِ الْحَدِيقَةَ وَطَلِّقْهَا تَطْلِيقَةً."],"takhrij":"صحيح: رواه البخاري في الطلاق (5273) عن أزهر بن جميل، حدثنا عبد الوهاب الثقفي، حدثنا خالد، عن عكرمة، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب في جواز الخلع","chapter_ur":"","part_ar":"كتاب الخلع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5273). ʿAbd al-Razzaq (11759) also narrated from Maʿmar, who said: “It reached me that she said: O Messenger of Allah, you can see the beauty I have, while Thabit is an unattractive man.”","chapter_en":"Chapter on the Permissibility of Khulʿ","part_en":"The Book of Khulʿ","group_ar":"","group_en":"","part_no":26,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas reported that the wife of Thabit ibn Qays came to the Prophet ﷺ and said: “O Messenger of Allah, I do not fault Thabit ibn Qays in his character or religion, but I dislike ingratitude in Islam.” So the Messenger of Allah ﷺ said: “Will you return his garden to him?” She said: “Yes.” The Messenger of Allah ﷺ said: “Accept the garden and divorce her with one divorce.”"]},"buhuth":{"en":["“Unattractive” means not handsome."]},"intro":{"ar":["قال الله تعالى: ( فَإِنْ خِفْتُمْ أَلَّا يُقِيمَاحُدُودَ اللَّهِ لَا جُنَاحَ عَلَيْهِمَا فِيمَا أَقْتَدَتْ بِهِ ) (البقرة: ٢٢٩]"],"en":["Allah the Exalted said: “But if you fear that they will not keep within the limits of Allah, then there is no blame upon either of them concerning that by which she ransoms herself.” [al-Baqarah: 229]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5273,"lafz":true},{"key":"abdrazzaq","label":". وأخرج عبد الرزاق","number":11759}],"full":1,"dr":1},{"num":6602,"demo":false,"sanad":"","matn":["عَنْ حَبِيبَةَ بِنْتِ سَهْلٍ الأَنْصَارِيَّةِ، أَنَّهَا كَانَتْ تَحْتَ ثَابِتِ بْنِ قَيْسِ بْنِ شَمَّاسٍ وَأَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ إِلَى الصُّبْحِ فَوَجَدَ حَبِيبَةَ بِنْتَ سَهْلٍ عِنْدَ بَابِهِ فِي الْغَلَسِ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ هَذِهِ. فَقَالَتْ أَنَا حَبِيبَةُ بِنْتُ سَهْلٍ. قَالَ مَا شَأْنُكِ. قَالَتْ لاَ أَنَا وَلاَ ثَابِتُ بْنُ قَيْسٍ. لِزَوْجِهَا فَلَمَّا جَاءَ ثَابِتُ بْنُ قَيْسٍ قَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَذِهِ حَبِيبَةُ بِنْتُ سَهْلٍ. وَذَكَرَتْ مَا شَاءَ اللَّهُ أَنْ تَذْكُرَ وَقَالَتْ حَبِيبَةُ يَا رَسُولَ اللَّهِ كُلُّ مَا أَعْطَانِي عِنْدِي. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِثَابِتِ بْنِ قَيْسٍ خُذْ مِنْهَا. فَأَخَذَ مِنْهَا وَجَلَسَتْ هِيَ فِي أَهْلِهَا."],"takhrij":"صحيح: رواه مالك في الطلاق (21) عن يحيى بن سعيد، عن عمرة بنت عبد الرحمن، أنها أخبرته عن حبيبة بنت سهل الأنصاري، فذكرته.","grade":"صحيح","chapter_ar":"باب في جواز الخلع","chapter_ur":"","part_ar":"كتاب الخلع","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (21), Ahmad (27444), Abu Dawud (2227), al-Nasa’i (3462).","chapter_en":"Chapter on the Permissibility of Khulʿ","part_en":"The Book of Khulʿ","group_ar":"","group_en":"","part_no":26,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Habibah bint Sahl al-Ansariyyah reported that she was married to Thabit ibn Qays ibn Shammās. The Messenger of Allah ﷺ went out for the dawn prayer and found Habibah bint Sahl at his door in the darkness before dawn. The Messenger of Allah ﷺ said to her: “Who is this?” She replied: “I am Habibah bint Sahl, O Messenger of Allah.” He said: “What is the matter?” She said: “Neither I nor Thabit ibn Qays can continue as husband and wife.” When her husband Thabit ibn Qays came, the Messenger of Allah ﷺ said to him: “This is Habibah bint Sahl, and she has mentioned what Allah willed her to mention.” Habibah said: “O Messenger of Allah, everything he gave me is still with me.” So the Messenger of Allah ﷺ said to Thabit ibn Qays: “Take it from her.” So he took it from her, and she stayed in her family’s home."]},"buhuth":{"en":["In the phrase “she stayed in her family’s home” there is evidence that a woman who obtains khulʿ is not entitled to housing from the husband."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":21,"lafz":true},{"key":"abudawud","label":"أبو داود","number":2227},{"key":"nasai","label":"النسائي","number":3462,"n":3462},{"key":"ahmad","label":"مسند الإمام أحمد","number":27444,"n":27444}],"full":1,"dr":1},{"num":6603,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ حَبِيبَةَ بِنْتَ سَهْلٍ، كَانَتْ عِنْدَ ثَابِتِ بْنِ قَيْسِ بْنِ شَمَّاسٍ فَضَرَبَهَا فَكَسَرَ بَعْضَهَا فَأَتَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْدَ الصُّبْحِ فَاشْتَكَتْهُ إِلَيْهِ فَدَعَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَابِتًا فَقَالَ خُذْ بَعْضَ مَالِهَا وَفَارِقْهَا. فَقَالَ وَيَصْلُحُ ذَلِكَ يَا رَسُولَ اللَّهِ قَالَ نَعَمْ. قَالَ فَإِنِّي أَصْدَقْتُهَا حَدِيقَتَيْنِ وَهُمَا بِيَدِهَا فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خُذْهُمَا فَفَارِقْهَا. فَفَعَلَ."],"takhrij":"صحيح: رواه أبو داود (2228) عن محمد بن معمر، حدثنا أبو عامر عبد الملك بن عمرو، حدثنا أبو عمرو السدوسي المديني، عن عبد الله بن أبي بكر بن محمد بن عمرو بن حزم، عن عمرة، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب في جواز الخلع","chapter_ur":"","part_ar":"كتاب الخلع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2228).","chapter_en":"Chapter on the Permissibility of Khulʿ","part_en":"The Book of Khulʿ","group_ar":"","group_en":"","part_no":26,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿA’ishah reported that Habibah bint Sahl was married to Thabit ibn Qays ibn Shammās. He struck her and broke one of her bones. So she came to the Prophet ﷺ after dawn and complained about him. The Prophet ﷺ called him and said: “Take some of her wealth and separate from her.” He said: “Is that acceptable, O Messenger of Allah?” He said: “Yes.” He said: “I gave her two gardens as her bridal gift, and they are in her possession.” So the Prophet ﷺ said: “Take them both and separate from her.” So he did that."]},"buhuth":{"en":["In his saying, “Take them both and separate from her,” there is evidence that a man may take back all that he gave her. But in the second narration he took one of them, so perhaps he first took both and then returned one out of scrupulousness."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2228,"lafz":true}],"full":1,"dr":1},{"num":6604,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَيُّمَا امْرَأَةٍ سَأَلَتْ زَوْجَهَا طَلاَقًا فِي غَيْرِ مَا بَأْسٍ فَحَرَامٌ عَلَيْهَا رَائِحَةُ الْجَنَّةِ."],"takhrij":"صحيح: رواه أبو داود (2226) والترمذي (1187) وابن ماجة (2055) وابن الجارود (748) وصحّحه ابن حبان (4184) والحاكم (2/200) والبيهقي (7/316) كلهم من طرق عن أيوب، عن أبي قلابة، عن أبي أسماء، عن ثوبان فذكره. وإسناده صحيح، وأبو أسماء اسمه: عمرو بن مرثد الرحبي إلا أن الترمذي رواه عن أبي قلابة، عمن حدّثه، عن ثوبان. وقال: \"هذا حديث حسن، ويروى هذا الحديث عن أيوب عن أبي قلابة، عن أبي أسماء، عن ثوبان، ورواه بعضهم عن أيوب بهذا الإسناد، ولم يرفعه\" انتهى.","grade":"صحيح","chapter_ar":"باب كراهية الخلع للمرأة","chapter_ur":"","part_ar":"كتاب الخلع","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (2226), al-Tirmidhī (1187), Ibn Mājah (2055), and Ibn al-Jārūd (748).","chapter_en":"Chapter on the Dislike of Khulʿ for a Woman","part_en":"The Book of Khulʿ","group_ar":"","group_en":"","part_no":26,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Thawbān reported that the Messenger of Allah ﷺ said: “Any woman who asks her husband for divorce without there being any valid harm or cause, the fragrance of Paradise is forbidden to her.”"]},"buhuth":{"en":["His statement, “asks her husband for divorce,” refers here to khulʿ, because divorce is in the husband’s hand and is one of his rights, which he may exercise when necessary.","Khulʿ is among the rights of a woman. If she sees that married life cannot continue properly, she may ask her husband for khulʿ. The husband may ask her to return what he gave her as dowry, because Allah Most High says:","“But if you fear that they will not keep within the limits of Allah, then there is no blame upon either of them concerning that by which she ransoms herself.”","[al-Baqarah: 229]"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2226,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1187},{"key":"ibnmajah","label":"ابن ماجه","number":2055},{"key":"sh13071","label":"ابن الجارود","number":748,"n":777},{"key":"ibnhibban","label":"ابن حبان","number":4184}],"full":1,"dr":1},{"num":6605,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ جَمِيلَةَ بِنْتَ سَلُولَ، أَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ وَاللَّهِ مَا أَعْتِبُ عَلَى ثَابِتٍ فِي دِينٍ وَلاَ خُلُقٍ. وَلَكِنِّي أَكْرَهُ الْكُفْرَ فِي الإِسْلاَمِ لاَ أُطِيقُهُ بُغْضًا. فَقَالَ لَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَتَرُدِّينَ عَلَيْهِ حَدِيقَتَهُ. قَالَتْ نَعَمْ. فَأَمَرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَأْخُذَ مِنْهَا حَدِيقَتَهُ وَلاَ يَزْدَادَ."],"takhrij":"حسن: رواه ابن ماجة (2056) عن أزهر بن مروان، قال: حدثنا عبد الأعلى بن عبدالأعلى، قال: حدثنا سعيد بن أبي عروبة، عن قتادة، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب لا يجوز للزوج أن يأخذ أكثر مما أعطاها","chapter_ur":"","part_ar":"كتاب الخلع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2056) and al-Bayhaqi (7/313).","chapter_en":"The Husband May Not Take More Than What He Gave Her","part_en":"The Book of Khulʿ","group_ar":"","group_en":"","part_no":26,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbas reported that Jamilah bint Salul came to the Prophet ﷺ and said: “By Allah, I do not fault Thabit in religion or character, but I dislike ingratitude in Islam. I cannot bear him out of dislike.” So the Prophet ﷺ said to her: “Will you return his garden to him?” She said: “Yes.” Then the Prophet ﷺ ordered him to take back his garden from her and not take any more."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2056,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":313}],"full":1,"dr":1},{"num":6606,"demo":false,"sanad":"","matn":["عَنِ الرُّبَيِّعِ بِنْتِ مُعَوِّذِ بْنِ عَفْرَاءَ أَنَّهَا اخْتَلَعَتْ عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : فَأَمَرَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوْ أُمِرَتْ أَنْ تَعْتَدَّ بِحَيْضَةٍ."],"takhrij":"صحيح: رواه الترمذي (1185) عن محمود بن غيلان قال: أخبرنا الفضل بن موسى، عن سفيان، قال: أخبرنا محمد بن عبد الرحمن وهو مولى آل طلحة، عن سليمان بن يسار. عن الرُبيع فذكرته.","grade":"صحيح","chapter_ar":"باب عدة المختلعة","chapter_ur":"","part_ar":"كتاب الخلع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1185), who authenticated it.","chapter_en":"The Waiting Period of the Woman Who Obtains Khulʿ","part_en":"The Book of Khulʿ","group_ar":"","group_en":"","part_no":26,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Al-Rubayyiʿ bint Muʿawwidh ibn ʿAfra’ reported that she obtained khulʿ during the time of the Prophet ﷺ, and the Prophet ﷺ ordered her, or she was ordered, to observe a waiting period of one menstrual cycle."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1185,"lafz":true}],"full":1,"dr":1},{"num":6607,"demo":false,"sanad":"","matn":["عن عُبَادَةَ بْنِ الْوَلِيدِ بن عُبَادَةَ بْنِ الصَّامِتِ عَنِ الرُّبَيِّعِ بِنْتِ مُعَوِّذِ ابْنِ عَفْرَاءَ، قَالَ قُلْتُ لَهَا حَدِّثِينِي حَدِيثَكِ،. قَالَتِ اخْتَلَعْتُ مِنْ زَوْجِي ثُمَّ جِئْتُ عُثْمَانَ. فَسَأَلْتُ مَاذَا عَلَىَّ مِنَ الْعِدَّةِ فَقَالَ لاَ عِدَّةَ عَلَيْكِ إِلاَّ أَنْ يَكُونَ حَدِيثَ عَهْدٍ بِكِ فَتَمْكُثِينَ عِنْدَهُ حَتَّى تَحِيضِينَ حَيْضَةً. قَالَتْ وَإِنَّمَا تَبِعَ فِي ذَلِكَ قَضَاءَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَرْيَمَ الْمَغَالِيَّةِ. وَكَانَتْ تَحْتَ ثَابِتِ بْنِ قَيْسٍ فَاخْتَلَعَتْ مِنْهُ."],"takhrij":"حسن: رواه النسائي (3498) وابن ماجة (2058) كلاهما من حديث إبراهيم بن سعد، عن محمد بن إسحاق قال: حدثني عبادة بن الوليد بن عبادة بن الصامت فذكره. وإسناده حسن من أجل محمد بن إسحاق.","grade":"حسن","chapter_ar":"باب عدة المختلعة","chapter_ur":"","part_ar":"كتاب الخلع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (3498) and Ibn Majah (2058).","chapter_en":"The Waiting Period of the Woman Who Obtains Khulʿ","part_en":"The Book of Khulʿ","group_ar":"","group_en":"","part_no":26,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿUbadah ibn al-Walid ibn ʿUbadah ibn al-Samit reported from al-Rubayyiʿ bint Muʿawwidh ibn ʿAfra’ that he said to her: “Tell me your story.” She said: “I obtained khulʿ from my husband, then I came to ʿUthman and asked: What waiting period is required of me?” He said: “There is no waiting period upon you unless you were recently with him, in which case remain until you menstruate one cycle.” He said: “I am following in this the ruling of the Messenger of Allah ﷺ regarding Maryam al-Mughaliyyah, who had been married to Thabit ibn Qays and obtained khulʿ from him.”"]},"buhuth":{"en":["His statement, “There is no waiting period upon you unless he has only recently been with you,” means that the woman who obtains khulʿ does not have a waiting period like that of a divorced woman, except one menstrual cycle for womb clearance if the marriage was recently consummated or intercourse had occurred, in which case she stays until she menstruates once. Otherwise there is no waiting period upon her. But this is opposed by what appears in the hadith of Ibn ʿAbbas in Abu Dawud and others, that she was ordered to observe one menstrual cycle, so this is understood according to the usual case that intercourse had occurred, and therefore she observes one cycle for womb clearance."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3498,"lafz":true,"n":3498},{"key":"ibnmajah","label":"ابن ماجه","number":2058}],"full":1,"dr":1},{"num":6608,"demo":false,"sanad":"","matn":["عن الربيع بنت معوذ بن عَفْرَاءَ أخبرت ابْنِ عَفْرَاءَ، أَخْبَرَتْهُ أَنَّ ثَابِتَ بْنَ قَيْسِ بْنِ شَمَّاسٍ ضَرَبَ امْرَأَتَهُ فَكَسَرَ يَدَهَا وَهِيَ جَمِيلَةُ بِنْتُ عَبْدِ اللَّهِ بْنِ أُبَىٍّ فَأَتَى أَخُوهَا يَشْتَكِيهِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَرْسَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى ثَابِتٍ فَقَالَ لَهُ خُذِ الَّذِي لَهَا عَلَيْكَ وَخَلِّ سَبِيلَهَا. قَالَ نَعَمْ. فَأَمَرَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تَتَرَبَّصَ حَيْضَةً وَاحِدَةً فَتَلْحَقَ بِأَهْلِهَا."],"takhrij":"صحيح: رواه النسائي (3497) عن أبي علي محمد بن يحيى المروزي، قال: أخبرني شاذان بن عثمان أخو عبدان، قال: حدثنا أبي، قال: حدثنا علي بن المبارك، عن يحيى بن أبي كثير قال: أخبرني محمد بن عبد الرحمن، أن الربيع بنت معوذ أخبرته فذكره.","grade":"صحيح","chapter_ar":"باب عدة المختلعة","chapter_ur":"","part_ar":"كتاب الخلع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3497).","chapter_en":"The Waiting Period of the Woman Who Obtains Khulʿ","part_en":"The Book of Khulʿ","group_ar":"","group_en":"","part_no":26,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Al-Rubayyiʿ bint Muʿawwidh ibn ʿAfra’ reported that Thabit ibn Qays ibn Shammās struck his wife and broke her arm. She was Jamilah bint ʿAbdullah ibn Ubayy. Her brother came to complain about him to the Messenger of Allah ﷺ, so the Messenger of Allah ﷺ sent for Thabit and said to him: “Take what belongs to you from her and let her go.” He said: “Yes.” Then the Messenger of Allah ﷺ ordered her to wait for one menstrual cycle and then return to her family."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3497,"lafz":true,"n":3497}],"full":1,"dr":1},{"num":6609,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ أَنَّ امْرَأَةَ ثَابِتِ بْنِ قَيْسٍ اخْتَلَعَتْ مِنْ زَوْجِهَا عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَمَرَهَا أَنْ تَعْتَدَّ بِحَيْضَةٍ."],"takhrij":"حسن: رواه أبو داود (2229) والترمذي (1185 المكرر) والحاكم (2/206) كلهم من طريق هشام بن يوسف، عن معمر، عن عمرو بن مسلم، عن عكرمة، عن ابن عباس فذكره. قال الترمذي: \"حسن غريب\".","grade":"حسن","chapter_ar":"باب عدة المختلعة","chapter_ur":"","part_ar":"كتاب الخلع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2229), al-Tirmidhi (1185, repeated), and al-Hakim (2/206).","chapter_en":"The Waiting Period of the Woman Who Obtains Khulʿ","part_en":"The Book of Khulʿ","group_ar":"","group_en":"","part_no":26,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas reported that the wife of Thabit ibn Qays obtained khulʿ from her husband during the time of the Messenger of Allah ﷺ, and he ordered her to observe a waiting period of one menstrual cycle."]},"buhuth":{"en":["Al-Tirmidhi said: “Hasan Gharib.”","Shaykh al-Islam Ibn Taymiyyah, may Allah have mercy on him, said: Whoever considers this view will find that it accords with the principles of the Shariʿah. The waiting period was made three menstrual cycles only so that the time for possible return would be extended, the husband could reconsider, and he would be able to take her back during the waiting period. But when there is no right of return over her, then the purpose is only to make sure her womb is free from pregnancy, and one menstrual cycle is sufficient for that, just like womb clearance."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2229,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1185},{"key":"hakim","label":"الحاكم","number":206}],"full":1,"dr":1},{"num":6610,"demo":false,"sanad":"","matn":["عن سهل بْنِ سَعْدٍ السَّاعِدِيِّ أَخْبَرَهُ أَنَّ عُوَيْمِرًا الْعَجْلاَنِيَّ جَاءَ إِلَى عَاصِمِ بْنِ عَدِيٍّ الأَنْصَارِيِّ، فَقَالَ لَهُ يَا عَاصِمُ أَرَأَيْتَ رَجُلاً وَجَدَ مَعَ امْرَأَتِهِ رَجُلاً، أَيَقْتُلُهُ فَتَقْتُلُونَهُ، أَمْ كَيْفَ يَفْعَلُ سَلْ لِي يَا عَاصِمُ عَنْ ذَلِكَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَ عَاصِمٌ عَنْ ذَلِكَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَكَرِهَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَسَائِلَ وَعَابَهَا حَتَّى كَبُرَ عَلَى عَاصِمٍ مَا سَمِعَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمَّا رَجَعَ عَاصِمٌ إِلَى أَهْلِهِ جَاءَ عُوَيْمِرٌ فَقَالَ يَا عَاصِمُ مَاذَا قَالَ لَكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ عَاصِمٌ لَمْ تَأْتِنِي بِخَيْرٍ، قَدْ كَرِهَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَسْأَلَةَ الَّتِي سَأَلْتُهُ عَنْهَا. قَالَ عُوَيْمِرٌ وَاللَّهِ لاَ أَنْتَهِي حَتَّى أَسْأَلَهُ عَنْهَا فَأَقْبَلَ عُوَيْمِرٌ حَتَّى أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَسَطَ النَّاسِ فَقَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ رَجُلاً وَجَدَ مَعَ امْرَأَتِهِ رَجُلاً، أَيَقْتُلُهُ فَتَقْتُلُونَهُ، أَمْ كَيْفَ يَفْعَلُ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ أَنْزَلَ اللَّهُ فِيكَ وَفِي صَاحِبَتِكَ فَاذْهَبْ فَأْتِ بِهَا. قَالَ سَهْلٌ فَتَلاَعَنَا وَأَنَا مَعَ النَّاسِ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمَّا فَرَغَا قَالَ عُوَيْمِرٌ كَذَبْتُ عَلَيْهَا يَا رَسُولَ اللَّهِ، إِنْ أَمْسَكْتُهَا، فَطَلَّقَهَا ثَلاَثًا قَبْلَ أَنْ يَأْمُرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.","قال مالك: قال ابن شهاب: فكانت تلك، بعد، سنة المتلاعنين."],"takhrij":"متفق عليه: رواه مالك في الطلاق (34) عن ابن شهاب، أن سهل بن سعد الساعدي، فذكره. ورواه البخاري في الطلاق (5259)، ومسلم في اللعان (1:1492) كلاهما من طريق مالك، به، مثله.","grade":"متفق عليه","chapter_ar":"باب ما جاء في اللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (34), al-Bukhari (5259), and Muslim (1492/1).","chapter_en":"Chapter on What Has Been Narrated Regarding Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Sahl ibn Saʿd al-Saʿidi reported to him that ʿUwaymir al-ʿAjlani came to ʿAsim ibn ʿAdi al-Ansari and said to him: “O ʿAsim, what do you think of a man who finds another man with his wife? Should he kill him so that you would kill him in retaliation, or what should he do? Ask the Messenger of Allah ﷺ about that for me.” So ʿAsim asked the Messenger of Allah ﷺ about it. The Messenger of Allah ﷺ disliked such questions and disapproved of them, until what ʿAsim heard from the Messenger of Allah ﷺ weighed heavily on him. When ʿAsim returned to his family, ʿUwaymir came to him and said: “O ʿAsim, what did the Messenger of Allah ﷺ say to you?” ʿAsim said to ʿUwaymir: “You did not bring me any good. The Messenger of Allah ﷺ disliked the question I asked him about.” So ʿUwaymir said: “By Allah, I will not stop until I ask him about it myself.” Then ʿUwaymir went until he came to the Messenger of Allah ﷺ among the people and said: “O Messenger of Allah, what do you think of a man who finds another man with his wife? Should he kill him so that you would kill him, or what should he do?” The Messenger of Allah ﷺ said: “Revelation has been sent down concerning you and your wife, so go and bring her.” Sahl said: So they performed liʿān while I was with the people in the presence of the Messenger of Allah ﷺ. When they finished their mutual oaths, ʿUwaymir said: “I would have lied against her, O Messenger of Allah, if I kept her.” Then he divorced her three times before the Messenger of Allah ﷺ commanded him. Malik said: Ibn Shihab said: That thereafter became the established practice concerning those who engage in liʿān."]},"intro":{"ar":["قال الله تعالى: ﴿وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ وَلَمْ يَكُنْ لَهُمْ شُهَدَاءُ إِلَّا أَنْفُسُهُمْ فَشَهَادَةُ أَحَدِهِمْ أَرْبَعُ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنَ الصَّادِقِينَ ۝ وَالْخَامِسَةُ أَنَّ لَعْنَتَ اللَّهِ عَلَيْهِ إِنْ كَانَ مِنَ الْكَاذِبِينَ ۝ وَيَدْرَأُ عَنْهَا الْعَذَابَ أَنْ تَشْهَدَ أَرْبَعَ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنَ الْكَاذِبِينَ ۝ وَالْخَامِسَةَ أَنَّ غَضَبَ اللَّهِ عَلَيْهَا إِنْ كَانَ مِنَ الصَّادِقِينَ﴾ [النور: ٦-٩]."],"en":["Allah the Exalted said: “And those who accuse their wives and have no witnesses except themselves, then the testimony of one of them shall be four testimonies by Allah that he is surely of the truthful, and the fifth that the curse of Allah be upon him if he is of the liars. And it shall avert the punishment from her if she bears witness four times by Allah that he is surely of the liars, and the fifth that the wrath of Allah be upon her if he is of the truthful.” [Surat al-Nur: 6–9]"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":34},{"key":"bukhari","label":"البخاري","number":5259,"lafz":true},{"key":"muslim","label":"مسلم","number":1}],"full":1,"dr":1},{"num":6611,"demo":false,"sanad":"","matn":["عن سهل بْنِ سَعْدٍ أخى بَنِي سَاعِدَةَ أَنَّ رَجُلاً، مِنَ الأَنْصَارِ جَاءَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ رَجُلاً وَجَدَ مَعَ امْرَأَتِهِ رَجُلاً، أَيَقْتُلُهُ أَمْ كَيْفَ يَفْعَلُ فَأَنْزَلَ اللَّهُ فِي شَأْنِهِ مَا ذَكَرَ فِي الْقُرْآنِ مِنْ أَمْرِ الْمُتَلاَعِنَيْنِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ قَضَى اللَّهُ فِيكَ وَفِي امْرَأَتِكَ. قَالَ فَتَلاَعَنَا فِي الْمَسْجِدِ وَأَنَا شَاهِدٌ، فَلَمَّا فَرَغَا قَالَ كَذَبْتُ عَلَيْهَا يَا رَسُولَ اللَّهِ إِنْ أَمْسَكْتُهَا. فَطَلَّقَهَا ثَلاَثًا قَبْلَ أَنْ يَأْمُرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ فَرَغَا مِنَ التَّلاَعُنِ، فَفَارَقَهَا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ ذَاكَ تَفْرِيقٌ بَيْنَ كُلِّ مُتَلاَعِنَيْنِ."],"takhrij":"متفق عليه: رواه البخاري في الطلاق (5309) ومسلم في اللعان (1492: 3) كلاهما من طريق عبد الرزاق. أخبرنا ابن جريج، قال: أخبرني ابن شهاب عن الملاعنة وعن السنة فيها عن حديث سهل بن سعد، فذكره. والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في اللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5309) and Muslim (1492/3). The wording is that of al-Bukhari.","chapter_en":"Chapter on What Has Been Narrated Regarding Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Sahl ibn Saʿd, the brother of Banu Saʿidah, reported that a man from the Ansar came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, what do you think of a man who finds another man with his wife? Should he kill him, or what should he do?” So Allah sent down concerning his case what is mentioned in the Qur’an regarding those who perform liʿān. Then the Prophet ﷺ said: “Allah has judged regarding you and your wife.” He said: So they performed liʿān in the mosque while I was present as a witness. When they finished, he said: “I would have lied against her, O Messenger of Allah, if I kept her,” so he divorced her three times before the Messenger of Allah ﷺ instructed him. Thus he separated from her in the presence of the Prophet ﷺ, who said: “That is the separation between every pair who perform liʿān.”"]},"buhuth":{"en":["The unnamed man from the Ansar was ʿUwaymir al-ʿAjlani.","His saying, “That is the separation between every pair who perform liʿān,” indicates that two people who have performed liʿān never reunite."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري في الطلاق","number":5309,"lafz":true},{"key":"muslim","label":"مسلم في اللعان","number":1492}],"full":1,"dr":1},{"num":6612,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ، قَالَ إِنَّا لَيْلَةَ الْجُمُعَةِ فِي الْمَسْجِدِ إِذْ جَاءَ رَجُلٌ مِنَ الأَنْصَارِ فَقَالَ لَوْ أَنَّ رَجُلاً وَجَدَ مَعَ امْرَأَتِهِ رَجُلاً فَتَكَلَّمَ جَلَدْتُمُوهُ أَوْ قَتَلَ قَتَلْتُمُوهُ وَإِنْ سَكَتَ سَكَتَ عَلَى غَيْظٍ وَاللَّهِ لأَسْأَلَنَّ عَنْهُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَلَمَّا كَانَ مِنَ الْغَدِ أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَهُ فَقَالَ لَوْ أَنَّ رَجُلاً وَجَدَ مَعَ امْرَأَتِهِ رَجُلاً فَتَكَلَّمَ جَلَدْتُمُوهُ أَوْ قَتَلَ قَتَلْتُمُوهُ أَوْ سَكَتَ سَكَتَ عَلَى غَيْظٍ. فَقَالَ اللَّهُمَّ افْتَحْ. وَجَعَلَ يَدْعُو فَنَزَلَتْ آيَةُ اللِّعَانِ ﴿وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ وَلَمْ يَكُنْ لَهُمْ شُهَدَاءُ إِلاَّ أَنْفُسُهُمْ﴾ [سورة النور: 6]} هَذِهِ الآيَاتُ فَابْتُلِيَ بِهِ ذَلِكَ الرَّجُلُ مِنْ بَيْنِ النَّاسِ فَجَاءَ هُوَ وَامْرَأَتُهُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَتَلاَعَنَا فَشَهِدَ الرَّجُلُ ﴿أَرْبَعَ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنَ الصَّادِقِينَ﴾ [سورة النور: 6] ثُمَّ لَعَنَ الْخَامِسَةَ أَنَّ لَعْنَةَ اللَّهِ عَلَيْهِ إِنْ كَانَ مِنَ الْكَاذِبِينَ فَذَهَبَتْ لِتَلْعَنَ فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَهْ. فَأَبَتْ فَلَعَنَتْ فَلَمَّا أَدْبَرَا قَالَ لَعَلَّهَا أَنْ تَجِيءَ بِهِ أَسْوَدَ جَعْدًا. فَجَاءَتْ بِهِ أَسْوَدَ جَعْدًا."],"takhrij":"صحيح: رواه مسلم في اللعان (1495) من طريق الأعمش، عن إبراهيم، عن علقمة، عن عبد الله (هو ابن مسعود) فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في اللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1495).","chapter_en":"Chapter on What Has Been Narrated Regarding Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullah reported: We were in the mosque on Friday night when a man from the Ansar came and said: “If a man found another man with his wife and spoke about it, you would flog him; if he killed him, you would kill him; and if he remained silent, he would remain silent in rage. By Allah, I will ask the Messenger of Allah ﷺ about it.” The next day he went to the Messenger of Allah ﷺ and asked him, saying: “If a man found another man with his wife and spoke, you would flog him; if he killed him, you would kill him; and if he remained silent, he would remain silent in rage.” The Prophet ﷺ said: “O Allah, clarify,” and he kept supplicating. Then the verse of liʿān was revealed: “And those who accuse their wives…” [al-Nur: 6], these verses. Then that very man was tested with it from among the people. So he and his wife came to the Messenger of Allah ﷺ and performed liʿān. The man testified four times by Allah that he was indeed telling the truth, then on the fifth he invoked the curse of Allah upon himself if he were lying. Then she went to invoke her oath, so the Messenger of Allah ﷺ said to her: “Stop.” But she refused and proceeded. When they turned away, he said: “Perhaps she will bring forth a black, curly-haired child,” and she indeed gave birth to a black, curly-haired child."]},"buhuth":{"en":["The unnamed man from the Ansar was ʿUwaymir al-ʿAjlani."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1495,"lafz":true}],"full":1,"dr":1},{"num":6613,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ هِلاَلَ بْنَ أُمَيَّةَ، قَذَفَ امْرَأَتَهُ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشَرِيكِ بْنِ سَحْمَاءَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْبَيِّنَةَ أَوْ حَدٌّ فِي ظَهْرِكَ. فَقَالَ يَا رَسُولَ اللَّهِ إِذَا رَأَى أَحَدُنَا عَلَى امْرَأَتِهِ رَجُلاً يَنْطَلِقُ يَلْتَمِسُ الْبَيِّنَةَ. فَجَعَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ الْبَيِّنَةَ وَإِلاَّ حَدٌّ فِي ظَهْرِكَ فَقَالَ هِلاَلٌ وَالَّذِي بَعَثَكَ بِالْحَقِّ إِنِّي لَصَادِقٌ، فَلَيُنْزِلَنَّ اللَّهُ مَا يُبَرِّئُ ظَهْرِي مِنَ الْحَدِّ، فَنَزَلَ جِبْرِيلُ، وَأَنْزَلَ عَلَيْهِ {وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ} فَقَرَأَ حَتَّى بَلَغَ {إِنْ كَانَ مِنَ الصَّادِقِينَ} فَانْصَرَفَ."],"takhrij":"صحيح: رواه البخاري في التفسير (4747) عن محمدبن بشار، حدثنا ابن أبي عدي، عن هشام بن حسان، حدثنا عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في اللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (4747).","chapter_en":"Chapter on What Has Been Narrated Regarding Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Ibn ʿAbbās reported: Hilāl ibn Umayyah accused his wife before the Prophet ﷺ of committing adultery with Sharīk ibn Saḥmāʾ. The Prophet ﷺ said: “Produce evidence, otherwise the prescribed punishment will be carried out upon your back.” Hilāl said: “O Messenger of Allah, if one of us sees a man with his wife, is he then expected to go off looking for evidence?” The Prophet ﷺ continued saying: “Evidence, otherwise the prescribed punishment will be upon your back.” Hilāl said: “By the One who sent you with the truth, I am certainly truthful, and Allah will surely reveal something that will clear my back from the prescribed punishment.” Then Jibrīl descended and revealed: “And those who accuse their wives…” [al-Nūr: 6] The Prophet ﷺ recited the verses until he reached: “…if he is among the truthful.” [al-Nūr: 9]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4747,"lafz":true}],"full":1,"rep":[6631]},{"num":6614,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ إِنَّ أَوَّلَ لِعَانٍ كَانَ فِي الإِسْلاَمِ أَنَّ هِلاَلَ بْنَ أُمَيَّةَ قَذَفَ شَرِيكَ ابْنَ السَّحْمَاءِ بِامْرَأَتِهِ فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ بِذَلِكَ فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَرْبَعَةَ شُهَدَاءَ وَإِلاَّ فَحَدٌّ فِي ظَهْرِكَ. يُرَدِّدُ ذَلِكَ عَلَيْهِ مِرَارًا فَقَالَ لَهُ هِلاَلٌ وَاللَّهِ يَا رَسُولَ اللَّهِ إِنَّ اللَّهَ عَزَّ وَجَلَّ لَيَعْلَمُ أَنِّي صَادِقٌ وَلَيُنْزِلَنَّ اللَّهُ عَزَّ وَجَلَّ عَلَيْكَ مَا يُبَرِّئُ ظَهْرِي مِنَ الْجَلْدِ. فَبَيْنَمَا هُمْ كَذَلِكَ إِذْ نَزَلَتْ عَلَيْهِ آيَةُ اللِّعَانِ { وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ } إِلَى آخِرِ الآيَةِ فَدَعَا هِلاَلاً فَشَهِدَ ﴿أَرْبَعَ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنَ الصَّادِقِينَ وَالْخَامِسَةُ أَنَّ﴾ [سورة النور: 6، 7] لَعْنَةَ اللَّهِ عَلَيْهِ إِنْ كَانَ مِنَ الْكَاذِبِينَ ثُمَّ دُعِيَتِ الْمَرْأَةُ فَشَهِدَتْ أَرْبَعَ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنَ الْكَاذِبِينَ فَلَمَّا أَنْ كَانَ فِي الرَّابِعَةِ أَوِ الْخَامِسَةِ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقِّفُوهَا فَإِنَّهَا مُوجِبَةٌ. فَتَلَكَّأَتْ حَتَّى مَا شَكَكْنَا أَنَّهَا سَتَعْتَرِفُ ثُمَّ قَالَتْ لاَ أَفْضَحُ قَوْمِي سَائِرَ الْيَوْمِ. فَمَضَتْ عَلَى الْيَمِينِ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ انْظُرُوهَا فَإِنْ جَاءَتْ بِهِ أَبْيَضَ سَبِطًا قَضِيءَ الْعَيْنَيْنِ فَهُوَ لِهِلاَلِ بْنِ أُمَيَّةَ وَإِنْ جَاءَتْ بِهِ آدَمَ جَعْدًا رَبْعًا حَمْشَ السَّاقَيْنِ فَهُوَ لِشَرِيكِ ابْنِ السَّحْمَاءِ. فَجَاءَتْ بِهِ آدَمَ جَعْدًا رَبْعًا حَمْشَ السَّاقَيْنِ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَوْلاَ مَا سَبَقَ فِيهَا مِنْ كِتَابِ اللَّهِ لَكَانَ لِي وَلَهَا شَأْنٌ."],"takhrij":"صحيح: رواه مسلم (1496)، والنسائي (3469) وأحمد (12450) وصحّحه ابن حبان (4451) كلهم من حديث هشام بن حسان، عن ابن سيرين، عن أنس فذكره، واللفظ للنسائي، وعند أحمد مختصر.","grade":"صحيح","chapter_ar":"باب ما جاء في اللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasāʾī (3469), Aḥmad (12450), and authenticated by Ibn Ḥibbān (4451).","chapter_en":"Chapter on What Has Been Narrated Regarding Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Anas reported: The first case of liʿān in Islam occurred when Hilāl ibn Umayyah accused his wife of committing adultery with Sharīk ibn al-Saḥmāʾ. He came to the Prophet ﷺ and informed him. The Prophet ﷺ said to him: “Four witnesses, otherwise the prescribed punishment will be upon your back.” He repeated this to him several times. Hilāl said: “By Allah, O Messenger of Allah, Allah, Mighty and Majestic, knows that I am truthful, and Allah will surely reveal to you something that will clear my back from being flogged.” While they were in that state, the verse of liʿān was revealed: “And those who accuse their wives…” [al-Nūr: 6] to the end of the verses. The Prophet ﷺ called Hilāl, and he testified four times by Allah that he was among the truthful, and the fifth time that the curse of Allah would be upon him if he were among the liars. Then the woman was called. She testified four times by Allah that he was among the liars. When she reached the fourth or fifth oath, the Messenger of Allah ﷺ said: “Stop her, for this one is decisive.” She hesitated until we almost thought she would confess. Then she said: “I will not disgrace my people for the rest of this day.” So she completed the oath. The Messenger of Allah ﷺ said: “Watch her. If she gives birth to a child who is fair-skinned, straight-haired, and with deeply set eyes, then he is from Hilāl ibn Umayyah. But if she gives birth to one who is dark-complexioned, curly-haired, of medium stature, and thin-legged, then he is from Sharīk ibn al-Saḥmāʾ.” She gave birth to a dark-complexioned, curly-haired, medium-sized child with thin legs. The Messenger of Allah ﷺ then said: “Had it not been for what has already preceded concerning her in the Book of Allah, I would have had a matter with her.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3469,"n":3469},{"key":"ibnhibban","label":"صححه ابن حبان","number":4451},{"key":"ahmad","label":"مسند الإمام أحمد","number":12450,"n":12450},{"key":"muslim","label":"مسلم","number":1496,"lafz":true}],"full":1,"dr":1},{"num":6615,"demo":false,"sanad":"","matn":["عَنْ مُحَمَّدٍ، قَالَ سَأَلْتُ أَنَسَ بْنَ مَالِكٍ وَأَنَا أُرَى، أَنَّ عِنْدَهُ، مِنْهُ عِلْمًا. فَقَالَ إِنَّ هِلاَلَ بْنَ أُمَيَّةَ قَذَفَ امْرَأَتَهُ بِشَرِيكِ ابْنِ سَحْمَاءَ وَكَانَ أَخَا الْبَرَاءِ بْنِ مَالِكٍ لأُمِّهِ وَكَانَ أَوَّلَ رَجُلٍ لاَعَنَ فِي الإِسْلاَمِ - قَالَ - فَلاَعَنَهَا فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَبْصِرُوهَا فَإِنْ جَاءَتْ بِهِ أَبْيَضَ سَبِطًا قَضِيءَ الْعَيْنَيْنِ فَهُوَ لِهِلاَلِ بْنِ أُمَيَّةَ وَإِنْ جَاءَتْ بِهِ أَكْحَلَ جَعْدًا حَمْشَ السَّاقَيْنِ فَهُوَ لِشَرِيكِ ابْنِ سَحْمَاءَ. قَالَ فَأُنْبِئْتُ أَنَّهَا جَاءَتْ بِهِ أَكْحَلَ جَعْدًا حَمْشَ السَّاقَيْنِ."],"takhrij":"صحيح: رواه مسلم في اللعان (11:1496) عن محمد بن المثنى، حدثنا عبد الأعلى، حدثنا هشام، عن محمد، قال: فذكر الحديث.","grade":"صحيح","chapter_ar":"باب قذف الرجل زوجتَه برجل بعينه","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1496).","chapter_en":"A Man Accusing His Wife of Adultery with a Specific Man","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Muhammad ibn Sirin said: I asked Anas ibn Malik, thinking that he had knowledge of it. He said: Hilal ibn Umayyah accused his wife concerning Sharik ibn Sahma’, who was the maternal brother of al-Bara’ ibn Malik, and he was the first man to perform liʿān in Islam. He said: So he performed liʿān with her. Then the Messenger of Allah ﷺ said: “Watch her. If she brings forth a white child with straight hair and sunken eyes, then it belongs to Hilal ibn Umayyah. But if she brings forth a dark-eyed, curly-haired child with thin legs, then it belongs to Sharik ibn Sahma’.” He said: “I was informed that she gave birth to a dark-eyed, curly-haired child with thin legs.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1496,"lafz":true},{"key":"muslim","label":"مسلم في اللعان","number":11}],"full":1},{"num":6616,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ، أَنَّ رَجُلاً، أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ يَا رَسُولَ اللَّهِ، أَرَأَيْتَ رَجُلاً رَأَى مَعَ امْرَأَتِهِ رَجُلاً أَيَقْتُلُهُ فَتَقْتُلُونَهُ أَمْ كَيْفَ يَفْعَلُ فَأَنْزَلَ اللَّهُ فِيهِمَا مَا ذُكِرَ فِي الْقُرْآنِ مِنَ التَّلاَعُنِ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ قُضِيَ فِيكَ وَفِي امْرَأَتِكَ. قَالَ فَتَلاَعَنَا، وَأَنَا شَاهِدٌ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَفَارَقَهَا فَكَانَتْ سُنَّةً أَنْ يُفَرَّقَ بَيْنَ الْمُتَلاَعِنَيْنِ وَكَانَتْ حَامِلاً، فَأَنْكَرَ حَمْلَهَا وَكَانَ ابْنُهَا يُدْعَى إِلَيْهَا، ثُمَّ جَرَتِ السُّنَّةُ فِي الْمِيرَاثِ أَنْ يَرِثَهَا، وَتَرِثَ مِنْهُ مَا فَرَضَ اللَّهُ لَهَا."],"takhrij":"صحيح: رواه البخاري في التفسير (4746) عن سليمان بن داود أبي الربيع، حدثنا فُليح، عن الزهري، عن سهل بن سعد فذكره.","grade":"صحيح","chapter_ar":"باب في الملاعنة على الزنا ونفي الحمل","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4746).","chapter_en":"Chapter on Liʿān for Adultery and the Denial of Pregnancy","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Sahl ibn Saʿd reported that a man came to the Prophet ﷺ and said: “O Messenger of Allah, what do you think of a man who sees another man with his wife? Should he kill him so that you would kill him, or what should he do?” So Allah revealed concerning them what is mentioned in the Qur’an. Then the Messenger of Allah ﷺ said to him: “Judgment has been given regarding you and your wife.” He said: So they performed liʿān while I was a witness in the presence of the Messenger of Allah ﷺ, and he separated from her. Then it became the established practice that those who perform liʿān are to be separated. She was pregnant, and he denied her pregnancy. Her son was then attributed to her. After that, the established practice in inheritance was that he would inherit from her, and she would inherit from him whatever Allah had assigned for her."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4746,"lafz":true}],"full":1},{"num":6617,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ يَقُولُ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاعَنَ بَيْنَ الْعَجْلانِيِّ وَامْرَأَتِهِ، قَالَ: وَكَانَتْ حُبْلَى، فَقَالَ: وَاللهِ مَا قَرَبْتُهَا مُنْذُ عَفَرْنَا - قالَ: وَالْعَفْرُ: أَنْ يُسْقَى النَّخْلُ بَعْدَ أَنْ يُتْرَكَ مِنَ السَّقْيِ، بَعْدَ الْإِبَارِ بِشَهْرَيْنِ."],"takhrij":"صحيح: رواه الإمام أحمد (3106) عن عبد الملك بن عمرو، حدثنا المغيرة بن عبدالرحمن، عن أبي الزناد، عن القاسم بن محمد، أنه سمع ابن عباس فذكره في حديث طويل. ورواه النسائي (3467) من وجه آخر عن أبي الزناد، وأصله في الصحيحين بغير هذا اللفظ.","grade":"صحيح","chapter_ar":"باب في الملاعنة على الزنا ونفي الحمل","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (3106) and al-Nasa’i (3467).","chapter_en":"Chapter on Liʿān for Adultery and the Denial of Pregnancy","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbas reported that the Messenger of Allah ﷺ conducted liʿān between al-ʿAjlani and his wife. He said: She was pregnant. So he said: “By Allah, I have not come near her since we fertilized the palm trees.” He said: And al-ʿafr is that the palm trees are watered after being left without watering for two months after pollination."]},"buhuth":{"en":["In this hadith there is evidence that liʿān took place both for adultery and for denying pregnancy. The apparent meaning of his denial of the pregnancy is that the pregnancy was old, and the man had been suspicious of his wife. Then when it became clear to him that she had committed adultery, he denied the pregnancy.","There is further detail in this matter: if the pregnancy was already present and he had not doubted it, and he only performed liʿān because of her adultery after seeing her commit it, then the child is his, because the child belongs to the marriage bed, and it is not permissible to deny the child through liʿān. But if he did not know of her pregnancy at the time of the adultery for which he accused her, then this is to be examined: if she gives birth less than six months after the adultery, the child is his and is not negated by his liʿān. But if she gives birth after more than six months and he denies the child, then the child is attributed to the mother. The final ruling returns to the judge."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":3106,"lafz":true},{"key":"nasai","label":"النسائي","number":3467}],"full":1,"dr":1},{"num":6618,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ، جُبَيْرٍ قَالَ سُئِلْتُ عَنِ الْمُتَلاَعِنَيْنِ، فِي إِمْرَةِ مُصْعَبٍ أَيُفَرَّقُ بَيْنَهُمَا قَالَ فَمَا دَرَيْتُ مَا أَقُولُ فَمَضَيْتُ إِلَى مَنْزِلِ ابْنِ عُمَرَ بِمَكَّةَ فَقُلْتُ لِلْغُلاَمِ اسْتَأْذِنْ لِي. قَالَ إِنَّهُ قَائِلٌ فَسَمِعَ صَوْتِي. قَالَ ابْنُ جُبَيْرٍ قُلْتُ نَعَمْ. قَالَ ادْخُلْ فَوَاللَّهِ مَا جَاءَ بِكَ هَذِهِ السَّاعَةَ إِلاَّ حَاجَةٌ فَدَخَلْتُ فَإِذَا هُوَ مُفْتَرِشٌ بَرْذَعَةً مُتَوَسِّدٌ وِسَادَةً حَشْوُهَا لِيفٌ قُلْتُ أَبَا عَبْدِ الرَّحْمَنِ الْمُتَلاَعِنَانِ أَيُفَرَّقُ بَيْنَهُمَا قَالَ سُبْحَانَ اللَّهِ نَعَمْ إِنَّ أَوَّلَ مَنْ سَأَلَ عَنْ ذَلِكَ فُلاَنُ بْنُ فُلاَنٍ قَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ أَنْ لَوْ وَجَدَ أَحَدُنَا امْرَأَتَهُ عَلَى فَاحِشَةٍ كَيْفَ يَصْنَعُ إِنْ تَكَلَّمَ تَكَلَّمَ بِأَمْرٍ عَظِيمٍ. وَإِنْ سَكَتَ سَكَتَ عَلَى مِثْلِ ذَلِكَ قَالَ فَسَكَتَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمْ يُجِبْهُ فَلَمَّا كَانَ بَعْدَ ذَلِكَ أَتَاهُ فَقَالَ إِنَّ الَّذِي سَأَلْتُكَ عَنْهُ قَدِ ابْتُلِيتُ بِهِ. فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ هَؤُلاَءِ الآيَاتِ فِي سُورَةِ النُّورِ { وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ} فَتَلاَهُنَّ عَلَيْهِ وَوَعَظَهُ وَذَكَّرَهُ وَأَخْبَرَهُ أَنَّ عَذَابَ الدُّنْيَا أَهْوَنُ مِنْ عَذَابِ الآخِرَةِ قَالَ لاَ وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا كَذَبْتُ عَلَيْهَا. ثُمَّ دَعَاهَا فَوَعَظَهَا وَذَكَّرَهَا وَأَخْبَرَهَا أَنَّ عَذَابَ الدُّنْيَا أَهْوَنُ مِنْ عَذَابِ الآخِرَةِ. قَالَتْ لاَ وَالَّذِي بَعَثَكَ بِالْحَقِّ إِنَّهُ لَكَاذِبٌ فَبَدَأَ بِالرَّجُلِ فَشَهِدَ أَرْبَعَ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنَ الصَّادِقِينَ وَالْخَامِسَةُ أَنَّ لَعْنَةَ اللَّهِ عَلَيْهِ إِنْ كَانَ مِنَ الْكَاذِبِينَ ثُمَّ ثَنَّى بِالْمَرْأَةِ فَشَهِدَتْ ﴿أَرْبَعَ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنَ الْكَاذِبِينَ وَالْخَامِسَةُ أَنَّ غَضَبَ اللَّهِ عَلَيْهَا إِنْ كَانَ مِنَ الصَّادِقِينَ﴾ [سورة النور: 8، 9] ثُمَّ فَرَّقَ بَيْنَهُمَا."],"takhrij":"صحيح: رواه مسلم في اللعان (4:1493) من طرق عن عبد الملك بن أبي سليمان، عن سعيد بن جبير، قال: فذكره.","grade":"صحيح","chapter_ar":"باب استحباب وعظ المتلاعنين وتذكيرهما بالله عند إرادة التلاعن","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1493/4).","chapter_en":"Chapter on the Recommendation to Admonish the Two Who Perform Liʿān and Remind Them of Allah When They Intend to Do So","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Saʿid ibn Jubayr said: I was asked about two spouses who perform liʿān during the rule of Musʿab: are they to be separated? I did not know what to say, so I went to the home of Ibn ʿUmar in Makkah. I said to the servant: Ask permission for me. He said: He is resting at midday. Then he heard my voice and said: Ibn Jubayr? I said: Yes. He said: Enter. By Allah, nothing has brought you at this hour except some need. So I entered, and there he was reclining on a saddle-cloth, using a cushion stuffed with fiber as a pillow. I said: O Abu ʿAbd al-Rahman, the two who perform liʿān, are they separated? He said: Subhan Allah, yes. The first one to ask about that was so-and-so son of so-and-so. He said: O Messenger of Allah, what if one of us finds his wife committing an indecency? If he speaks, he speaks of a grave matter, and if he remains silent, he remains silent upon the like of it. The Prophet ﷺ remained silent and did not answer him. Then after that he came to him again and said: What I asked you about, I have now been tested with it. So Allah the Mighty and Majestic revealed these verses in Surat al-Nur: “And those who accuse their wives…” [al-Nur: 6]. Then he recited them to him, admonished him and reminded him, and informed him that the punishment of this world is lighter than the punishment of the Hereafter. He said: No, by the One who sent you with the truth, I have not lied against her. Then he called her, admonished her, reminded her, and informed her that the punishment of this world is lighter than the punishment of the Hereafter. She said: No, by the One who sent you with the truth, he is surely lying. So he began with the man, and he testified four times by Allah that he was surely of the truthful, and the fifth that the curse of Allah be upon him if he were lying. Then he turned to the woman, and she testified four times by Allah that he was surely of the liars, and the fifth that the wrath of Allah be upon her if he were of the truthful. Then he separated them."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":4,"lafz":true}],"full":1},{"num":6619,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ قُلْتُ لاِبْنِ عُمَرَ رَجُلٌ قَذَفَ امْرَأَتَهُ فَقَالَ فَرَّقَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ أَخَوَىْ بَنِي الْعَجْلاَنِ، وَقَالَ اللَّهُ يَعْلَمُ أَنَّ أَحَدَكُمَا كَاذِبٌ، فَهَلْ مِنْكُمَا تَائِبٌ. فَأَبَيَا. وَقَالَ اللَّهُ يَعْلَمُ أَنَّ أَحَدَكُمَا كَاذِبٌ، فَهَلْ مِنْكُمَا تَائِبُ. فَأَبَيَا. فَقَالَ اللَّهُ يَعْلَمُ أَنَّ أَحَدَكُمَا كَاذِبٌ، فَهَلْ مِنْكُمَا تَائِبٌ فَأَبَيَا فَفَرَّقَ بَيْنَهُمَا.","قال أيوب: فقال لي عمر بن دينار: إن في الحديث شيئا لا أراك تحدثه؟ قال: قال الرجل: مالي؟ قال: قيل: لا مال لك إن كنت صادقا فقد دخلت بها، وإن كنت كاذبا فهو أبعد منك."],"takhrij":"صحيح: رواه البخاري في الطلاق (5311) عن عمرو بن زرارة، أخبرنا إسماعيل، عن أيوب، عن سعيد بن جبير، فذكره.","grade":"صحيح","chapter_ar":"باب استحباب وعظ المتلاعنين وتذكيرهما بالله عند إرادة التلاعن","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5311).","chapter_en":"Chapter on the Recommendation to Admonish the Two Who Perform Liʿān and Remind Them of Allah When They Intend to Do So","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Saʿid ibn Jubayr said: I said to Ibn ʿUmar: A man accused his wife. He said: The Prophet ﷺ separated the two brothers from Banu al-ʿAjlan and said: “Allah knows that one of you is lying, so is either of you willing to repent?” But they refused. He then said: “Allah knows that one of you is lying, so is either of you willing to repent?” But they refused. Then he said: “Allah knows that one of you is lying, so is either of you willing to repent?” But they refused, so he separated them. Ayyub said: ʿAmr ibn Dinar said to me: There is something in the hadith that I do not see you narrating. He said: The man asked: “What about my property?” It was said: “You have no claim to property. If you were truthful, then you have already consummated the marriage with her; and if you were lying, then it is even farther from you.”"]},"buhuth":{"ar":["فأنبئت أنها جاءت به أكحل جعداً حمش الساقين.","صحيح: رواه مسلم (١١:١٤٩٦)."],"en":["And I was informed that she gave birth to a dark-eyed, curly-haired child with thin legs.","Authentic: Narrated by Muslim (1496/11)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5311,"lafz":true}],"full":1},{"num":6620,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ رَجُلاً حِينَ أَمَرَ الْمُتَلاَعِنَيْنِ أَنْ يَتَلاَعَنَا أَنْ يَضَعَ يَدَهُ عَلَى فِيهِ عِنْدَ الْخَامِسَةِ يَقُولُ إِنَّهَا مُوجِبَةٌ."],"takhrij":"حسن: رواه أبو داود (2255) والنسائي (3472) والبيهقي (7/405) كلهم من حديث سفيان، عن عاصم بن كليب، عن أبيه، عن ابن عباس فذكره. وإسناده حسن من أجل عاصم بن كليب فإنه حسن الحديث. وكذا أبوه كليب بن شهاب الجرمي.","grade":"حسن","chapter_ar":"باب وضع اليد على فم الرجل عند الخامسة","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2255), al-Nasa’i (3472), and al-Bayhaqi (7/405). It is not established in the Sunan collections that the hand was placed over the woman’s mouth.","chapter_en":"Chapter on Placing the Hand over the Man’s Mouth at the Fifth Oath","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿAbbas said: The Prophet ﷺ instructed a man, when he commanded the two spouses to perform liʿān, to place his hand over his mouth at the fifth oath, saying: “It is decisive.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2255,"lafz":true},{"key":"nasai","label":"النسائي","number":3472,"n":3472},{"key":"kubrabayhaqi","label":"البيهقي","number":405}],"full":1,"dr":1},{"num":6621,"demo":false,"sanad":"","matn":["عَنِ الْمُتَلاَعِنَيْنِ،، فَقَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلْمُتَلاَعِنَيْنِ حِسَابُكُمَا عَلَى اللَّهِ أَحَدُكُمَا كَاذِبٌ، لاَ سَبِيلَ لَكَ عَلَيْهَا. قَالَ مَالِي قَالَ لاَ مَالَ لَكَ، إِنْ كُنْتَ صَدَقْتَ عَلَيْهَا، فَهْوَ بِمَا اسْتَحْلَلْتَ مِنْ فَرْجِهَا، وَإِنْ كُنْتَ كَذَبْتَ عَلَيْهَا، فَذَاكَ أَبْعَدُ لَكَ."],"takhrij":"متفق عليه: رواه البخاري في الطلاق (5312)، ومسلم في اللعان (5:1492) كلاهما من طريق سفيان بن عيينة، عن عمرو (هو ابن دينار) سمعت سعيد بن جبير قال: سألت ابن عمر عن المتلاعنين فقال: قال النبي صلى الله عليه وسلم للمتلاعنين، فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم أخذ صداق الملاعِنة","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5312) and Muslim (1492/5).","chapter_en":"Chapter on the Prohibition of Taking the Dowry of the Woman Involved in Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: The Messenger of Allah ﷺ said to the two who performed liʿān: “Your reckoning is with Allah. One of you is lying. You have no right over her.” He said: “O Messenger of Allah, what about my property?” He said: “You have no claim to any property. If you were truthful against her, then it was in exchange for what you had lawfully enjoyed of her private part. And if you lied against her, then that makes her even farther from you.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5312,"lafz":true},{"key":"muslim","label":"مسلم","number":5}],"full":1},{"num":6622,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّهُ ذُكِرَ التَّلاَعُنُ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ عَاصِمُ بْنُ عَدِيٍّ فِي ذَلِكَ قَوْلاً، ثُمَّ انْصَرَفَ، فَأَتَاهُ رَجُلٌ مِنْ قَوْمِهِ يَشْكُو إِلَيْهِ أَنَّهُ وَجَدَ مَعَ امْرَأَتِهِ رَجُلاً، فَقَالَ عَاصِمٌ مَا ابْتُلِيتُ بِهَذَا إِلاَّ لِقَوْلِي، فَذَهَبَ بِهِ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ بِالَّذِي وَجَدَ عَلَيْهِ امْرَأَتَهُ وَكَانَ ذَلِكَ الرَّجُلُ مُصْفَرًّا قَلِيلَ اللَّحْمِ سَبْطَ الشَّعَرِ، وَكَانَ الَّذِي ادَّعَى عَلَيْهِ أَنَّهُ وَجَدَهُ عِنْدَ أَهْلِهِ خَدْلاً آدَمَ كَثِيرَ اللَّحْمِ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اللَّهُمَّ بَيِّنْ. فَجَاءَتْ شَبِيهًا بِالرَّجُلِ الَّذِي ذَكَرَ زَوْجُهَا أَنَّهُ وَجَدَهُ، فَلاَعَنَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَهُمَا. قَالَ رَجُلٌ لاِبْنِ عَبَّاسٍ فِي الْمَجْلِسِ هِيَ الَّتِي قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَوْ رَجَمْتُ أَحَدًا بِغَيْرِ بَيِّنَةٍ رَجَمْتُ هَذِهِ. فَقَالَ لاَ تِلْكَ امْرَأَةٌ كَانَتْ تُظْهِرُ فِي الإِسْلاَمِ السُّوءَ قَالَ أَبُو صَالِحٍ وَعَبْدُ اللَّهِ بْنُ يُوسُفَ خَدِلاً."],"takhrij":"متفق عليه: رواه البخاري في الطلاق (5310)، ومسلم في اللعان (12:1497) كلاهما من طريق الليث، عن يحيى بن سعيد، عن عبد الرحمن بن القاسم، عن القاسم بن محمد، عن ابن عباس، فذكره.","grade":"متفق عليه","chapter_ar":"باب لا تُرجم المرأةُ ولو كانتِ الأمارةُ تدل على كذبها في اللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5310) and Muslim (1497/12).","chapter_en":"Chapter on the Woman Not Being Stoned Even If the Indications Suggest She Lied in Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbās reported: Liʿān was mentioned in the presence of the Prophet ﷺ, and ʿĀṣim ibn ʿAdī said something regarding it and then left. A man from his people came to him complaining that he had found another man with his wife. ʿĀṣim said: “I have only been afflicted with this because of what I said.” So he took the man to the Prophet ﷺ, and he informed him of what he had found concerning his wife. The husband was yellowish in complexion, thin in build, and straight-haired, while the man whom he accused of being with his wife was dark-complexioned, well-built, and fleshy. The Prophet ﷺ said: “O Allah, make the matter clear.” The Prophet ﷺ then conducted liʿān between the two of them. She later gave birth to a child resembling the man whom her husband had said he found with her. A man in the gathering asked Ibn ʿAbbās: “Was she the woman concerning whom the Prophet ﷺ said, ‘If I were to stone anyone without evidence, I would have stoned this woman’?” He replied: “No. That was another woman who openly displayed evil conduct in Islam.” Abū Ṣāliḥ and ʿAbdullāh ibn Yūsuf said: “khadlan.”"]},"buhuth":{"en":["The words “the Prophet ﷺ conducted liʿān between them” belong immediately after the statement that the man was taken to the Prophet ﷺ and informed him of what he had found concerning his wife. The wording contains an inversion in sequence, because liʿān took place before the birth, as shown by the preceding hadiths; there would be no reason to postpone liʿān until after childbirth."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5310,"lafz":true},{"key":"muslim","label":"مسلم","number":1497},{"key":"muslim","label":"مسلم في اللعان","number":12}],"full":1,"dr":1},{"num":6623,"demo":false,"sanad":"","matn":["عن سهل بْنِ سَعْدٍ أخي بَنِي سَاعِدَةَ أَنَّ رَجُلاً، مِنَ الأَنْصَارِ جَاءَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ رَجُلاً وَجَدَ مَعَ امْرَأَتِهِ رَجُلاً، أَيَقْتُلُهُ أَمْ كَيْفَ يَفْعَلُ فَأَنْزَلَ اللَّهُ فِي شَأْنِهِ مَا ذَكَرَ فِي الْقُرْآنِ مِنْ أَمْرِ الْمُتَلاَعِنَيْنِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ قَضَى اللَّهُ فِيكَ وَفِي امْرَأَتِكَ. قَالَ فَتَلاَعَنَا فِي الْمَسْجِدِ وَأَنَا شَاهِدٌ، فَلَمَّا فَرَغَا قَالَ كَذَبْتُ عَلَيْهَا يَا رَسُولَ اللَّهِ إِنْ أَمْسَكْتُهَا. فَطَلَّقَهَا ثَلاَثًا قَبْلَ أَنْ يَأْمُرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ فَرَغَا مِنَ التَّلاَعُنِ، فَفَارَقَهَا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ ذَاكَ تَفْرِيقٌ بَيْنَ كُلِّ مُتَلاَعِنَيْنِ.","قال ابن جريج، عن ابن شهاب، عن سهل بن سعد الساعدي في هذا الحديث إن النبي صلى الله عليه وسلم قال: إن جاءت به أحمر قصيراً، كأنه وحرة، فلا أراها إلا قد صدقتْ، وكذب عليها. وإن جاءت به أسود أعين، ذا أليتين فلا أراه إلا قد صدق عليها فجاءت به على المكروه من ذلك."],"takhrij":"متفق عليه: رواه البخاري في الطلاق (5309) ومسلم في اللعان (3:1492) كلاهما من طريق عبد الرزاق. أخبرنا ابن جريج، قال: أخبرني ابن شهاب عن الملاعنة وعن السنة فيها عن حديث سهل بن سعد، فذكره. والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب لا تُرجم المرأةُ ولو كانتِ الأمارةُ تدل على كذبها في اللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5309) and Muslim (1492/3). The wording is that of al-Bukhari.","chapter_en":"Chapter on the Woman Not Being Stoned Even If the Indications Suggest She Lied in Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Sahl ibn Saʿd, the brother of Banu Saʿidah, said that a man from the Ansar came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, what do you think of a man who finds another man with his wife? Should he kill him, or what should he do?” So Allah revealed concerning him what was mentioned in the Qur’an regarding those who perform liʿān. Then the Prophet ﷺ said: “Allah has judged concerning you and your wife.” He said: So they performed liʿān in the mosque while I was a witness. When they finished, he said: “I have lied against her, O Messenger of Allah, if I keep her,” so he divorced her three times before the Messenger of Allah ﷺ commanded him when they had finished the liʿān. Thus he separated from her in the presence of the Prophet ﷺ, who said: “That is the separation between every two who perform liʿān.” Ibn Jurayj said, from Ibn Shihab, from Sahl ibn Saʿd al-Saʿidi in this hadith, that the Prophet ﷺ said: “If she brings him forth reddish and short, as though he were a small lizard, then I only see that she has spoken the truth and he has lied against her. But if she brings him forth black, large-eyed, and with fleshy buttocks, then I only see that he has spoken truthfully against her.” Then she gave birth in the manner that was disliked of those two descriptions."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5309,"lafz":true},{"key":"muslim","label":"مسلم","number":3}],"full":1},{"num":6624,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عَمْرِو بْنِ الْعَاصِ عَنْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَنَّ رَجُلًا مِنَ الْأَنْصَارِ مِنْ بَنِي زُرَيْقٍ قَذَفَ امْرَأَتَهُ، فَأَتَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فردّدَ ذَلِكَ أَرْبَعَ مَرَّاتٍ على رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَأَنْزَلَ اللَّهُ آيَةَ الْمُلَاعَنَةِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَيْنَ السَّائِلُ، إنه قَدْ نَزَلَ مِنَ اللَّهِ أَمْرٌ عَظِيمٌ، فَأَبَى الرَّجُلُ إِلَّا أَنْ يُلَاعِنَهَا، وَأَبَتْ إِلَّا أَنْ تَدْرَأَ عَنْ نَفْسِهَا الْعَذَابَ، فَتَلَاعَنَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إما هِيَ تَجِيءُ بِهِ أُصَيْفِرَ أُخَيْنِسَ منشول الْعِظَامِ فَهُوَ لِلْمُلَاعِنْ، وإما تَجِيءُ بِهِ أَسْوَدَ كَالْجَمَلِ الْأَوْرَقِ فَهُوَ لِغَيْرِهِ، فَجَاءَتْ بِهِ أَسْوَدَ كَالْجَمَلِ الْأَوْرَقِ فَدَعَا بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَعَلَهُ لِعَصَبَةِ أُمِّهِ، وَقَالَ: لَوْ مَا الْأَيْمَانُ الَّتِي مضتْ لَكَانَ لِي فِيهِ كَذَا وَكَذَا."],"takhrij":"حسن: رواه النسائي في الكبرى (6328) وعنه الطحاوي في شرح المشكل (5146)، والدارقطني (3703) كلهم من طريق محمد بن عائذ قال: حدثنا الهيثم بن حميد قال: أخبرني ثور بن يزيد، عن عمرو بن شعيب، عن أبيه، عن جده قال: فذكره.","grade":"حسن","chapter_ar":"باب لا تُرجم المرأةُ ولو كانتِ الأمارةُ تدل على كذبها في اللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (6328), al-Tahawi in Sharh al-Mushkil (5146), and al-Daraqutni (3703).","chapter_en":"Chapter on the Woman Not Being Stoned Even If the Indications Suggest She Lied in Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs reported from the Messenger of Allah ﷺ that a man from the Ansar of Banu Zurayq accused his wife, so he came to the Messenger of Allah ﷺ and repeated that four times to him. Then Allah revealed the verse of liʿān. The Messenger of Allah ﷺ said: “Where is the questioner? A tremendous matter has indeed come down from Allah.” But the man insisted on performing liʿān against her, and she insisted on warding off the punishment from herself, so they performed liʿān. Then the Messenger of Allah ﷺ said: “Either she will bring him forth yellowish, with a small nose, thin-boned, and then he belongs to the man who performed liʿān, or she will bring him forth black like a gray camel, and then he belongs to someone else.” Then she gave birth to him black like a gray camel, so the Messenger of Allah ﷺ summoned him and assigned him to his mother’s relatives, and said: “Were it not for the oaths that have already passed, I would have had such-and-such to do regarding him.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":6328},{"key":"sh22547","label":"الطحاوي في شرح المشكل","number":5146},{"key":"sh9771","label":"الدار قطني","number":3703},{"key":"kubranasai","label":"النسائي في الكبري","number":6328,"lafz":true}],"full":1,"dr":1},{"num":6625,"demo":false,"sanad":"","matn":["عن عَبَّاسِ بن سهل عَنْ أَبِيهِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِعَاصِمِ بْنِ عَدِيٍّ أَمْسِكِ الْمَرْأَةَ عِنْدَكَ حَتَّى تَلِدَ."],"takhrij":"حسن: رواه أبو داود (2246) عن عبد العزيز بن يحيى، حدثنا محمد – يعني ابن سلمة، عن محمد بن إسحاق، حدثني عباس بن سهل، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب السكنى للحامل الملاعنة","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2246).","chapter_en":"Chapter on Housing for the Pregnant Woman Involved in Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["ʿAbbas ibn Sahl, from his father, reported that the Prophet ﷺ said to ʿAsim ibn ʿAdi: “Keep the woman with you until she gives birth.”"]},"buhuth":{"en":["The correct view in this matter is that if the liʿān concerns the pregnancy, then there is no maintenance or housing for her. But if the liʿān concerns something other than the pregnancy, then the pregnant woman has maintenance and housing, because the pregnancy belongs to him, so its maintenance is upon him. Thus she is like a pregnant woman divorced with an irrevocable divorce."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2246,"lafz":true}],"full":1,"dr":1},{"num":6626,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ لَمْ يُفَرِّقِ الْمُصْعَبُ بَيْنَ الْمُتَلاَعِنَيْنِ. قَالَ سَعِيدٌ فَذُكِرَ ذَلِكَ لِعَبْدِ اللَّهِ بْنِ عُمَرَ. فَقَالَ فَرَّقَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ أَخَوَىْ بَنِي الْعَجْلاَنِ."],"takhrij":"صحيح: رواه مسلم في اللعان (7:1493)، والنسائي (3474) كلاهما من حديث محمد بن المثنى واللفظ له قالا: حدثنا معاذ بن هشام، حدثني أبي، عن قتادة، عن عزرة، عن سعيد بن جبير فذكره.","grade":"صحيح","chapter_ar":"باب تفريق الإمام بين المتلاعنين، وأنهما لا يجتمعان أبدا","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1493/7) and al-Nasa’i (3474).","chapter_en":"Chapter on the Ruler Separating the Two Who Perform Liʿān, and That They Never Reunite","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Saʿid ibn Jubayr said: Musʿab did not separate between the two who had performed liʿān. Saʿid said: That was mentioned to Ibn ʿUmar, so he said: The Messenger of Allah ﷺ separated the two brothers from Banu al-ʿAjlan."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":7,"lafz":true},{"key":"nasai","label":"النسائي","number":3474,"n":3474}],"full":1,"dr":1},{"num":6627,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ قَالَ: فَطَلَّقَهَا ثَلاَثَ تَطْلِيقَاتٍ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَنْفَذَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ . وَكَانَ مَا صُنع عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُنَّةً.","قال سهل: حضرت هذا عند رسول الله صلى الله عليه وسلم فمضت السنّةُ بعد في المتلاعنين أن يفرق بينهما، ثم لا يجتمعان أبداً."],"takhrij":"حسن: رواه أبو داود (2250)، ومن طريقه البيهقي (7/401) عن أحمد بن عمرو بن السرح، حدثنا ابن وهب، عن عياض بن عبد الله الفِهري وغيره، عن ابن شهاب، عن سهل بن سعد في خبره فذكره.","grade":"حسن","chapter_ar":"باب من قال: يقع التفريق باللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2250), and through him by al-Bayhaqi (7/401).","chapter_en":"Chapter on Those Who Said That Separation Takes Place by Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Sahl ibn Saʿd said: He divorced her with three divorces in the presence of the Messenger of Allah ﷺ, and the Messenger of Allah ﷺ let it stand. What was done in the presence of the Prophet ﷺ became established practice. Sahl said: I was present for this with the Messenger of Allah ﷺ, and thereafter the established practice among those who perform liʿān was that they are separated and then never reunite."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2250,"lafz":true},{"key":"kubrabayhaqi","label":"ومن طريقه البيهقي","number":401},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":15322,"n":15473}],"full":1,"dr":1},{"num":6628,"demo":false,"sanad":"","matn":["عن سهل بن سعد أن رسول الله صلى الله عليه وسلم لاعن بين عويمر وبين امرأته. فقال عويمر: إنْ انطلقتُ بها يا رسول الله لقد كذبتُ عليها. قال: ففارَقَها قبل أن يأمره رسول الله صلى الله عليه وسلم فصارت سنة المتلاعنين."],"takhrij":"صحيح: رواه الإمام أحمد (22830) عن أبي كامل، حدثنا إبراهيم بن سعد، حدثنا ابن شهاب، عن سعد بن سهل فذكره في حديث طويل. وأصله في الصحيحين وغيرهما.","grade":"صحيح","chapter_ar":"باب من قال: يقع التفريق باللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (22830).","chapter_en":"Chapter on Those Who Said That Separation Takes Place by Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Sahl ibn Saʿd reported that the Messenger of Allah ﷺ made liʿān take place between ʿUwaymir and his wife. Then ʿUwaymir said: “If I go away with her, O Messenger of Allah, then I have lied against her.” He said: So he separated from her before the Messenger of Allah ﷺ commanded him, and that became the established practice for those who perform liʿān."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":22830,"lafz":true}],"full":1,"dr":1},{"num":6629,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ، أَنَّ رَجُلاً لاَعنَ امْرَأَتَهُ فِي زَمَانِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَانْتَفَلَ مِنْ وَلَدِهَا، ففرَّقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَهَا، وَأَلْحَقَ الْوَلَدَ بِالْمَرْأَةِ."],"takhrij":"متفق عليه: رواه مالك في الطلاق (35) عن نافع، عن عبد الله بن عمر، فذكره. ورواه البخاري في الطلاق (5315)، ومسلم في اللعان (8:1494) كلاهما من طريق مالك، به.","grade":"متفق عليه","chapter_ar":"باب إلحاق الولد بأمه في الملاعنة، وأنه يُدعى بها","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (35), al-Bukhari (5315), and Muslim (1494/8).","chapter_en":"Chapter on Attributing the Child to His Mother in Liʿān, and That He Is Called by Her Name","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿUmar reported that a man performed liʿān against his wife in the time of the Messenger of Allah ﷺ and disowned her child. So the Messenger of Allah ﷺ separated them and attributed the child to the woman."]},"buhuth":{"en":["His saying, “wantaffala,” means that he disowned him. In al-Bukhari it appears as: “fantafā.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":35,"lafz":true},{"key":"bukhari","label":"البخاري","number":5315},{"key":"muslim","label":"مسلم","number":8}],"full":1,"dr":1},{"num":6630,"demo":false,"sanad":"","matn":["عن سهل بن سعد أن رجلاً أتى النبي صلى الله عليه وسلم فذكر الحديث وقال فيه: وكانت حاملاً. فأنكر حملها، وكان ابنها يُدعى إليها."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4746) عن سليمان بن داود أبي الربيع، حدثنا فليح، عن الزهري، عن سهل بن سعد فذكره.","grade":"متفق عليه","chapter_ar":"باب إلحاق الولد بأمه في الملاعنة، وأنه يُدعى بها","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4746) and Muslim (1492/2). In Sunan Abi Dawud (2247), Sahl said: I was present at her liʿān before the Messenger of Allah ﷺ when I was fifteen years old, and he narrated the hadith. In it he said: Then she left while pregnant, and the child used to be called by his mother.","chapter_en":"Chapter on Attributing the Child to His Mother in Liʿān, and That He Is Called by Her Name","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Sahl ibn Saʿd reported that a man came to the Prophet ﷺ, and he mentioned the hadith, saying in it: She was pregnant, and he denied her pregnancy, and her son used to be attributed to her."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4746,"lafz":true},{"key":"muslim","label":"مسلم","number":2},{"key":"abudawud","label":". وفي سنن أبي داود","number":2247}],"full":1,"dr":1},{"num":6631,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ هِلاَلَ بْنَ أُمَيَّةَ، قَذَفَ امْرَأَتَهُ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشَرِيكِ بْنِ سَحْمَاءَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْبَيِّنَةَ أَوْ حَدٌّ فِي ظَهْرِكَ. فَقَالَ يَا رَسُولَ اللَّهِ إِذَا رَأَى أَحَدُنَا عَلَى امْرَأَتِهِ رَجُلاً يَنْطَلِقُ يَلْتَمِسُ الْبَيِّنَةَ. فَجَعَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ الْبَيِّنَةَ وَإِلاَّ حَدٌّ فِي ظَهْرِكَ فَقَالَ هِلاَلٌ وَالَّذِي بَعَثَكَ بِالْحَقِّ إِنِّي لَصَادِقٌ، فَلَيُنْزِلَنَّ اللَّهُ مَا يُبَرِّئُ ظَهْرِي مِنَ الْحَدِّ، فَنَزَلَ جِبْرِيلُ، وَأَنْزَلَ عَلَيْهِ {وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ} فَقَرَأَ حَتَّى بَلَغَ {إِنْ كَانَ مِنَ الصَّادِقِينَ} فَانْصَرَفَ."],"takhrij":"صحيح: رواه البخاري في التفسير (4747) عن محمد بن بشار، حدثنا ابن أبي عدي، عن هشام بن حسان، حدثنا عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب أن الزوج يُحَدّ إذا كذّب نفسه وتراجع عن اللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (4747).","chapter_en":"Chapter on the Husband Being Punished If He Declares Himself a Liar and Retracts from Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿAbbās reported: Hilāl ibn Umayyah accused his wife before the Prophet ﷺ of committing adultery with Sharīk ibn Saḥmāʾ. The Prophet ﷺ said to him: “Produce evidence, otherwise the prescribed punishment will be upon your back.” He said: “O Messenger of Allah, if one of us sees a man with his wife, is he expected to go and search for evidence?” The Prophet ﷺ continued saying: “Evidence, otherwise the prescribed punishment will be upon your back.” Hilāl said: “By the One who sent you with the truth, I am certainly truthful, and Allah will surely reveal something that will clear my back from the prescribed punishment.” Then Jibrīl descended and revealed: “And those who accuse their wives…” [al-Nūr: 6] until he reached: “…if he is among the truthful.” [al-Nūr: 9]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4747,"lafz":true}],"full":1,"rep":[6613]},{"num":6632,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: جَاءَ رَجُلٌ مِنْ بَنِي فَزَارَةَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ امْرَأَتِي وَلَدَتْ غُلاَمًا أَسْوَدَ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : هَلْ لَكَ مِنْ إِبِلٍ؟ قَالَ: نَعَمْ. قَالَ: فَمَا أَلْوَانُهَا؟ قَالَ: حُمْرٌ. قَالَ: هَلْ فِيهَا مِنْ أَوْرَقَ؟ قَالَ: إِنَّ فِيهَا لَوُرْقًا. قَالَ: فَأَنَّى أَتَاهَا ذَلِكَ؟ قَالَ: عَسَى أَنْ يَكُونَ نَزَعَهُ عِرْقٌ. قَالَ: وَهَذَا عَسَى أَنْ يَكُونَ نَزَعَهُ عِرْقٌ. وَزَادَ فِي رِوَايَةِ: وَلَمْ يرخّص لَهُ فِي الانتفاء مِنْهُ."],"takhrij":"متفق عليه: رواه البخاري في الطلاق (5305) من طريق مالك، ومسلم في اللعان (1500) من طريق سفيان بن عيينة، كلاهما عن الزهري، عن سعيد بن المسيب، عن أبي هريرة، فذكره. والسياق لمسلم، وكذا الزيادة له أيضاً من طريق معمر عن الزهري.","grade":"متفق عليه","chapter_ar":"باب أن الزوج يُحَدّ إذا كذّب نفسه وتراجع عن اللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5305) and Muslim (1500). The wording is that of Muslim.","chapter_en":"Chapter on the Husband Being Punished If He Declares Himself a Liar and Retracts from Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah said: A man from Banu Fazarah came to the Prophet ﷺ and said: “My wife has given birth to a black boy.” The Prophet ﷺ said: “Do you have camels?” He said: “Yes.” He said: “What colors are they?” He said: “Red.” He said: “Are there any grayish ones among them?” He said: “Indeed among them are some grayish ones.” He said: “How did that come about?” He said: “Perhaps a trait drew it out from ancestry.” He said: “And this too may have been drawn out by ancestry.” And in one narration there is the addition: “And he did not permit him to disown him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5305,"lafz":true},{"key":"muslim","label":"مسلم","number":1500}],"full":1},{"num":6633,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: بينما نحن عند رسول الله صلى الله عليه وسلم قام رجل فقال: يا رسول الله! إني وُلِدَ لي غلامٌ أسودُ. فقال رسول الله صلى الله عليه وسلم فذكر الحديث مثله. وجاء فيه: فمن أجله قضى رسول الله صلى الله عليه وسلم هذا: لا يجوز لرجل أن ينتفي مِن ولدٍ وُلِدَ على فراشه إلا أن يزعم: أنه رأى فاحشة."],"takhrij":"صحيح: رواه النسائي (3480) عن أحمد بن محمد بن المغيرة، قال: حدثنا أبو حيوة حمصي، قال: حدثنا شعيب بن أبي حمزة، عن الزهري، عن سعيد بن المسيب، عن أبي هريرة فذكره. وإسناده صحيح، وأبوحيوة حمصي هو: شُريح بن يزيد. وفي بعض النسخ: \"أبو حية\" والصحيح الأول.","grade":"صحيح","chapter_ar":"باب أن الزوج يُحَدّ إذا كذّب نفسه وتراجع عن اللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3480).","chapter_en":"Chapter on the Husband Being Punished If He Declares Himself a Liar and Retracts from Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah said: While we were with the Messenger of Allah ﷺ, a man stood up and said: “O Messenger of Allah, a black boy has been born to me.” The Messenger of Allah ﷺ said: “How did that happen?” He said: “I do not know.” He said: “Do you have camels?” He said: “Yes.” He said: “What colors are they?” He said: “Red.” He said: “Are there any grayish camels among them?” He said: “There are grayish camels among them.” He said: “How did that happen?” He said: “I do not know, O Messenger of Allah, except that perhaps a hereditary strain brought it out.” He said: “And perhaps this one too was brought out by a hereditary strain.” Because of this, the Messenger of Allah ﷺ ruled: “It is not permissible for a man to disown a child born on his marriage bed unless he claims that he witnessed an indecency.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3480,"lafz":true,"n":3480}],"full":1},{"num":6634,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ كُفْرٌ بِامْرِئٍ ادِّعَاءُ نَسَبٍ لاَ يَعْرِفُهُ أَوْ جَحْدُهُ وَإِنْ دَقَّ."],"takhrij":"حسن: رواه ابن ماجة (2744) عن محمد بن يحي، قـال: حـدثنا عبـد العزيز بن عبد الله، قال: حدثنا سليمان بن بلال، عن يحيى بن سعيد، عن عمرو بن شعيب فذكره.","grade":"حسن","chapter_ar":"باب التغليظ في الانتفاءِ من الولد","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2744) and Ahmad (7019).","chapter_en":"Chapter on the Severe Warning Regarding Disowning One’s Child","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb, from his father, from his grandfather, reported that the Prophet ﷺ said: “It is an act of disbelief for a person to claim a lineage he does not know, or to deny it, even if slight.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2744,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":7019,"n":6967}],"full":1,"dr":1},{"num":6635,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ حِينَ نَزَلَتْ آيَةُ الْمُتَلاَعِنَيْنِ أَيُّمَا امْرَأَةٍ أَدْخَلَتْ عَلَى قَوْمٍ مَنْ لَيْسَ مِنْهُمْ فَلَيْسَتْ مِنَ اللَّهِ فِي شَىْءٍ وَلَنْ يُدْخِلَهَا اللَّهُ جَنَّتَهُ وَأَيُّمَا رَجُلٍ جَحَدَ وَلَدَهُ وَهُوَ يَنْظُرُ إِلَيْهِ احْتَجَبَ اللَّهُ مِنْهُ وَفَضَحَهُ عَلَى رُءُوسِ الأَوَّلِينَ وَالآخِرِينَ."],"takhrij":"حسن: رواه أبو داود (2263) والنسائي (3481) وصحّحه ابن حبان (4108) والحاكم (2/202) كلهم من حديث يزيد بن عبدالله بن الهاد، عن عبدالله بن يونس، أنه سمع سعيد بن أبي سعيد المقبري، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب التغليظ في الانتفاءِ من الولد","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2263), al-Nasa’i (3481), authenticated by Ibn Hibban (4108), and Ibn Majah (2743).","chapter_en":"Chapter on the Severe Warning Regarding Disowning One’s Child","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Abu Hurayrah said that he heard the Messenger of Allah ﷺ say when the verse of liʿān was revealed: “Any woman who introduces into a people one who is not from them, she has nothing to do with Allah, and Allah will not admit her into His Paradise. And any man who denies his child while he is looking at him, Allah the Exalted will screen Himself from him and disgrace him before the first and the last.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2263,"lafz":true},{"key":"nasai","label":"النسائي","number":3481,"n":3481},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":4108},{"key":"ibnmajah","label":"ابن ماجه","number":2743},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2917,"n":2914}],"full":1,"dr":1},{"num":6636,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنِ انْتَفَى مِنْ وَلَدِهِ لِيَفْضَحَهُ فِي الدُّنْيَا، فَضَحَهُ اللهُ يَوْمَ الْقِيَامَةِ عَلَى رُءُوسِ الْأَشْهَادِ قِصَاصٌ بِقِصَاصٍ."],"takhrij":"حسن: رواه الإمام أحمد (4795) ومن طريقه الطبراني في الكبير (400:12) عن وكيع، عن أبيه، عن عبد الله بن أبي المجالد، عن مجاهد، عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب التغليظ في الانتفاءِ من الولد","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (4795) and al-Tabarani in al-Kabir (12/400).","chapter_en":"Chapter on the Severe Warning Regarding Disowning One’s Child","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ said: “Whoever disowns his child in order to disgrace him in this world, Allah will disgrace him on the Day of Resurrection before the heads of all witnesses, requital for requital.”"]},"buhuth":{"en":["His saying, “requital for requital,” means that retribution will be taken from him in the Hereafter corresponding to what he did to his child by denying his lineage and disgracing him in this world."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":4795,"lafz":true},{"key":"mujamkabir","label":"الطبراني في الكبير","number":400}],"full":1,"dr":1},{"num":6637,"demo":false,"sanad":"","matn":["عن عائشة قالت: الحمد لله الذي وسِعَ سمعُه الأصواتَ، لقد جاءتْ خولةُ بنتُ ثعلبة إلى رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تشكو زوجَها، فكان يخفَى عليَّ كلامُهما، فأنزل الله عز وجل: ﴿قَدْ سَمِعَ اللَّهُ قَوْلَ الَّتِي تُجَادِلُكَ فِي زَوْجِهَا وَتَشْتَكِي إِلَى اللَّهِ وَاللَّهُ يَسْمَعُ تَحَاوُرَكُمَا إِنَّ اللَّهَ سَمِيعٌ بَصِيرٌ﴾ [سورة المجادلة:١]"],"takhrij":"صحيح: رواه النسائي (3460) وابن ماجة (188) (2063) والإمام أحمد (24195) والحاكم (2/481) كلهم من طريق الأعمش، عن تميم بن سلمة، عن عروة، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في الظهار","chapter_ur":"","part_ar":"كتاب الظهار والإيلاء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3460), Ibn Majah (2063), Ahmad (24195), and al-Hakim (2/481).","chapter_en":"Chapter on What Has Been Reported Regarding Zihār","part_en":"Book of Zihār and Īlāʾ","group_ar":"","group_en":"","part_no":28,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿA’ishah said: Praise be to Allah whose hearing encompasses all voices. Khawlah bint Thaʿlabah came to the Messenger of Allah ﷺ complaining about her husband, and some of their conversation was hidden from me. Then Allah, Mighty and Exalted, revealed: “Allah has certainly heard the statement of the woman who disputes with you concerning her husband and complains to Allah, and Allah hears your exchange. Indeed, Allah is All-Hearing, All-Seeing.” [Surat al-Mujādilah: 1]"]},"buhuth":{"en":["Al-Hakim added at the beginning part of the woman’s words that ʿA’ishah heard: “O Messenger of Allah, he consumed my youth and I bore children for him. Then when I became old and my childbearing ended for him, he pronounced zihār against me. O Allah, I complain to You.”"]},"intro":{"ar":["قال الله تعالى: ( وَٱلَّذِينَ يُظَهِرُونَ مِن نِسَآئِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُواْ فَتَحْرِيرُ رَقَبَةٍ مِن قَبْلِ أَن بَتَمَاسَّا) [سورة المجادلة: ٣]"],"en":["Allah the Exalted said: “Those who pronounce zihār against their wives and then go back on what they said must free a slave before the two touch one another.” [Surat al-Mujādilah: 3]"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3460,"lafz":true,"n":3460},{"key":"ibnmajah","label":"ابن ماجه","number":2063},{"key":"ahmad","label":"الإمام أحمد","number":24195},{"key":"ibnmajah","label":"ابن ماجه","number":188}],"full":1,"dr":1},{"num":6638,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ جَمِيلَةَ كَانَتِ امْرَأَةَ أَوْسِ بْنِ الصَّامِتِ، وَكَانَ أَوْسٌ امْرَءًا بِهِ لَمَمٌ، فَإِذَا اشْتَدَّ لَمَمُهُ ظَاهَرَ مِنَ امْرَأَتِهِ، فَأَنْزَلَ اللَّهُ فِيهِ كَفَّارَةَ الظِّهَارِ."],"takhrij":"صحيح: رواه أبو داود (2220) والحاكم (2/481) والبيهقي (7/382) كلهم من طريق محمد بن الفضل أبي النعمان، ثنا حماد بن سلمة، عن هشام بن عروة، عن أبيه، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في الظهار","chapter_ur":"","part_ar":"كتاب الظهار والإيلاء","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2220), al-Hakim (2/481), and al-Bayhaqi (7/382).","chapter_en":"Chapter on What Has Been Reported Regarding Zihār","part_en":"Book of Zihār and Īlāʾ","group_ar":"","group_en":"","part_no":28,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿA’ishah said that Jamilah was the wife of Aws ibn al-Samit, and Aws was a man who had a mental disturbance. Whenever his condition worsened, he would pronounce zihār against his wife. Then Allah revealed regarding him the expiation for zihār."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2220,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":382},{"key":"hakim","label":"المستدرك على الصحيحين","number":3792,"n":3779},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":15244,"n":15395}],"full":1,"dr":1},{"num":6639,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عَبَّاسٍ: أَنَّ رَجُلاً ظَاهَرَ مِنِ امْرَأَتِهِ، فغَشِيَها قَبْلَ أَنْ يُكفِّر، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَذَكَرَ ذَلِكَ، فَقَالَ: مَا حَمَلَكَ عَلَى ذَلِكَ؟ فَقَالَ: يَا رَسُولَ اللَّهِ! رَأَيْتُ بَيَاضَ حِجْلَيْها فِي الْقَمَرِ، فَلَمْ أَمْلِكْ نَفْسِي أَنْ وَقَعْتُ عَلَيْهَا، فضحِكَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَمَرَهُ أَلاَّ يَقْرَبَهَا حَتَّى يُكفِّرَ."],"takhrij":"حسن: رواه الترمذي (1199) وابن ماجة (2065) والنسائي (3457) وأبو داود (2225،2223) (إلا أنه لم يذكر لفظ الحديث)، والحاكم (2/204) والبيهقي (7/386) كلهم من حديث الحكم بن أبان، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب المظاهر يجامع قبل أن يكفر","chapter_ur":"","part_ar":"كتاب الظهار والإيلاء","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1199), Ibn Majah (2065), al-Nasa’i (3457), and Abu Dawud (2223, 2225).","chapter_en":"Chapter on the One Who Pronounces Zihār Having Intercourse Before Making Expiation","part_en":"Book of Zihār and Īlāʾ","group_ar":"","group_en":"","part_no":28,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿAbbas reported that a man pronounced zihār against his wife, then had intercourse with her before making expiation. He came to the Prophet ﷺ and mentioned that, and he said: “What led you to do that?” He said: “O Messenger of Allah, I saw the whiteness of her anklets in the moonlight, and I could not control myself, so I fell upon her.” The Prophet ﷺ laughed and ordered him not to go near her until he had made expiation."]},"buhuth":{"en":["Al-Tirmidhi said: “Hasan, gharib, sahih.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1199,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2065},{"key":"nasai","label":"النسائي","number":3457},{"key":"abudawud","label":"أبو داود","number":2223},{"key":"abudawud","label":"ابو داود","number":2225}],"full":1,"dr":1},{"num":6640,"demo":false,"sanad":"","matn":["عَنْ خَوْلَةَ بِنْتِ ثَعْلَبَةَ قَالَتْ: فِيَّ - وَاللهِ - وَفِي أَوْسِ بْنِ صَامِتٍ أَنْزَلَ اللَّهُ عَزَّ وَجَلَّ صَدْرَ سُورَةِ الْمُجَادَلَةِ قَالَتْ: كُنْتُ عِنْدَهُ وَكَانَ شَيْخًا كَبِيرًا قَدْ سَاءَ خُلُقُهُ وَضَجِرَ، قَالَتْ: فَدَخَلَ عَلَيَّ يَوْمًا فَرَاجَعْتُهُ بِشَيْءٍ فَغَضِبَ، فَقَالَ: أَنْتِ عَلَيَّ كَظَهْرِ أُمِّي، قَالَتْ: ثُمَّ خَرَجَ فَجَلَسَ فِي نَادِي قَوْمِهِ سَاعَةً، ثُمَّ دَخَلَ عَلَيَّ، فَإِذَا هُوَ يُرِيدُنِي عَلَى نَفْسِي، قَالَتْ: فَقُلْتُ: كَلَّا وَالَّذِي نَفْسُ خُوَيْلَةَ بِيَدِهِ، لَا تَخْلُصُ إِلَيَّ وَقَدْ قُلْتَ مَا قُلْتَ حَتَّى يَحْكُمَ اللَّهُ وَرَسُولُهُ فِينَا بِحُكْمِهِ، قَالَتْ: فَوَاثَبَنِي وَامْتَنَعْتُ مِنْهُ، فَغَلَبْتُهُ بِمَا تَغْلِبُ بِهِ الْمَرْأَةُ الشَّيْخَ الضَّعِيفَ، فَأَلْقَيْتُهُ عَنِّي، قَالَتْ: ثُمَّ خَرَجْتُ إِلَى بَعْضِ جَارَاتِي فَاسْتَعَرْتُ مِنْهَا ثِيَابَهَا، ثُمَّ خَرَجْتُ حَتَّى جِئْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَلَسْتُ بَيْنَ يَدَيْهِ، فَذَكَرْتُ لَهُ مَا لَقِيتُ مِنْهُ، فَجَعَلْتُ أَشْكُو إِلَيْهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا أَلْقَى مِنْ سُوءِ خُلُقِهِ، قَالَتْ: فَجَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يَا خُوَيْلَةُ، ابْنُ عَمِّكِ شَيْخٌ كَبِيرٌ فَاتَّقِي اللهَ فِيهِ، قَالَتْ: فَوَاللهِ مَا بَرِحْتُ حَتَّى نَزَلَ فِيَّ الْقُرْآنُ، فَتَغَشَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا كَانَ يَتَغَشَّاهُ، ثُمَّ سُرِّيَ عَنْهُ فَقَالَ لِي: يَا خُوَيْلَةُ، قَدْ أَنْزَلَ اللَّهُ فِيكِ وَفِي صَاحِبِكِ، ثُمَّ قَرَأَ عَلَيَّ: ﴿قَدْ سَمِعَ اللَّهُ قَوْلَ الَّتِي تُجَادِلُكَ فِي زَوْجِهَا وَتَشْتَكِي إِلَى اللَّهِ، وَاللهُ يَسْمَعُ تَحَاوُرَكُمَا، إِنَّ اللَّهَ سَمِيعٌ بَصِيرٌ﴾ [المجادلة: ١] إِلَى قَوْلِهِ: ﴿وَلِلْكَافِرِينَ عَذَابٌ أَلِيمٌ﴾ [البقرة: ١٠٤]، فَقَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مُرِيهِ فَلْيُعْتِقْ رَقَبَةً، قَالَتْ: فَقُلْتُ: وَاللهِ يَا رَسُولَ اللَّهِ مَا عِنْدَهُ مَا يُعْتِقُ، قَالَ: فَلْيَصُمْ شَهْرَيْنِ مُتَتَابِعَيْنِ، قَالَتْ: فَقُلْتُ: وَاللهِ يَا رَسُولَ اللَّهِ إِنَّهُ شَيْخٌ كَبِيرٌ مَا بِهِ مِنْ صِيَامٍ، قَالَ: فَلْيُطْعِمْ سِتِّينَ مِسْكِينًا، وَسْقًا مِنْ تَمْرٍ، قَالَتْ: فَقُلْتُ: وَاللهِ يَا رَسُولَ اللَّهِ مَا ذَاكَ عِنْدَهُ، قَالَتْ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَإِنَّا سَنُعِينُهُ بِعَرَقٍ مِنْ تَمْرٍ، قَالَتْ: فَقُلْتُ: وَأَنَا يَا رَسُولَ اللَّهِ سَأُعِينُهُ بِعَرَقٍ آخَرَ، قَالَ: قَدْ أَصَبْتِ وَأَحْسَنْتِ، فَاذْهَبِي فَتَصَدَّقِي عَنْهُ، ثُمَّ اسْتَوْصِي بِابْنِ عَمِّكِ خَيْرًا، قَالَتْ: فَفَعَلْتُ.","قال عبد الله: قال أبي: قال سعد: العرق: الصن."],"takhrij":"حسن: رواه أحمد (27319) واللفظ له، وأبو داود (2215،2214) وابن الجارود (746) وصحّحه ابن حبان (4279) والبيهقي (7/389) كلهم من حديث محمد بن إسحاق، حدّثني معمر بن عبد الله بن حنظلة، عن يوسف بن عبد الله بن سلام، عن خولة بنت مالك بن ثعلبة فذكرته.","grade":"حسن","chapter_ar":"باب المظاهر يجامع قبل أن يكفر","chapter_ur":"","part_ar":"كتاب الظهار والإيلاء","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (27319), and this is his wording, Abu Dawud (2214, 2215), and authenticated by Ibn Hibban (4279).","chapter_en":"Chapter on the One Who Pronounces Zihār Having Intercourse Before Making Expiation","part_en":"Book of Zihār and Īlāʾ","group_ar":"","group_en":"","part_no":28,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Khawlah bint Thaʿlabah said: By Allah, the opening of Surat al-Mujādilah was revealed concerning me and Aws ibn Samit. She said: I was with him, and he was an old man whose character had become bad and who had become irritable. One day he came in to me, and I answered him back about something, so he became angry and said: “You are to me like my mother’s back.” Then he went out and sat for a while in the gathering place of his people. Then he came back to me and wanted me physically. I said: No, by the One in whose hand is the soul of Khuwaylah, you shall not have access to me after what you have said, until Allah and His Messenger judge between us with His judgment. She said: He tried to force himself on me, and I resisted him, and I overcame him in the way a woman overcomes a weak old man, and I pushed him away from me. Then I went to one of my neighbors and borrowed her clothes, then went until I came to the Messenger of Allah ﷺ and sat before him. I mentioned to him what I had suffered from him, and I kept complaining to him about his bad character. The Messenger of Allah ﷺ kept saying: “O Khawlah, your cousin is an old man, so fear Allah regarding him.” She said: By Allah, I had not moved when the Qur’an was revealed. The Messenger of Allah ﷺ was overtaken by what used to overtake him, then it was lifted from him, and he said to me: “O Khawlah, Allah has revealed concerning you and your companion.” Then he recited to me: “Allah has certainly heard the statement of the woman who disputes with you concerning her husband…” up to His saying: “And for the disbelievers is a painful punishment.” [al-Mujādilah: 1–4] Then the Messenger of Allah ﷺ said to me: “Command him to free a slave.” She said: I said, “By Allah, O Messenger of Allah, he has nothing with which to free a slave.” He said: “Then let him fast two consecutive months.” She said: I said, “By Allah, O Messenger of Allah, he is an old man and unable to fast.” He said: “Then let him feed sixty poor people a wasq of dates.” She said: I said, “By Allah, O Messenger of Allah, he does not have that.” She said: Then the Messenger of Allah ﷺ said: “We will help him with a basket of dates.” I said: “And I, O Messenger of Allah, will help him with another basket.” He said: “You have done right and done well. Go, then give charity on his behalf, and advise your cousin well.” She said: So I did. ʿAbdullah said: My father said: Saʿd said: al-ʿaraq means al-ṣann (a large basket)."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2214},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":4279},{"key":"ahmad","label":"مسند الإمام أحمد","number":27319,"n":27319,"lafz":true},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":7191,"n":7191},{"key":"abudawud","label":"ابو داود","number":2215},{"key":"sh13071","label":"ابن الجارود","number":746}],"full":1,"dr":1,"rep":[10438,13503]},{"num":6641,"demo":false,"sanad":"","matn":["عَنْ سَلَمَةَ بْنِ صَخْرٍ الْبَيَاضِيِّ، قَالَ كُنْتُ امْرَأً أَسْتَكْثِرُ مِنَ النِّسَاءِ لاَ أُرَى رَجُلاً كَانَ يُصِيبُ مِنْ ذَلِكَ مَا أُصِيبُ فَلَمَّا دَخَلَ رَمَضَانُ ظَاهَرْتُ مِنِ امْرَأَتِي حَتَّى يَنْسَلِخَ رَمَضَانُ فَبَيْنَمَا هِيَ تُحَدِّثُنِي ذَاتَ لَيْلَةٍ انْكَشَفَ لِي مِنْهَا شَىْءٌ فَوَثَبْتُ عَلَيْهَا فَوَاقَعْتُهَا فَلَمَّا أَصْبَحْتُ غَدَوْتُ عَلَى قَوْمِي فَأَخْبَرْتُهُمْ خَبَرِي وَقُلْتُ لَهُمْ سَلُوا لِي رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَالُوا مَا كُنَّا لِنَفْعَلَ إِذًا يُنْزِلَ اللَّهُ فِينَا كِتَابًا أَوْ يَكُونَ فِينَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَوْلٌ فَيَبْقَى عَلَيْنَا عَارُهُ وَلَكِنْ سَوْفَ نُسَلِّمُكَ لِجَرِيرَتِكَ اذْهَبْ أَنْتَ فَاذْكُرْ شَأْنَكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ فَخَرَجْتُ حَتَّى جِئْتُهُ فَأَخْبَرْتُهُ الْخَبَرَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْتَ بِذَاكَ. فَقُلْتُ أَنَا بِذَاكَ وَهَا أَنَا يَا رَسُولَ اللَّهِ صَابِرٌ لِحُكْمِ اللَّهِ عَلَىَّ. قَالَ فَأَعْتِقْ رَقَبَةً. قَالَ قُلْتُ وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا أَصْبَحْتُ أَمْلِكُ إِلاَّ رَقَبَتِي هَذِهِ. قَالَ فَصُمْ شَهْرَيْنِ مُتَتَابِعَيْنِ. قَالَ قُلْتُ يَا رَسُولَ اللَّهِ وَهَلْ دَخَلَ عَلَىَّ مَا دَخَلَ مِنَ الْبَلاَءِ إِلاَّ بِالصَّوْمِ قَالَ فَتَصَدَّقْ وَأَطْعِمْ سِتِّينَ مِسْكِينًا. قَالَ قُلْتُ وَالَّذِي بَعَثَكَ بِالْحَقِّ لَقَدْ بِتْنَا لَيْلَتَنَا هَذِهِ مَا لَنَا عَشَاءٌ. قَالَ فَاذْهَبْ إِلَى صَاحِبِ صَدَقَةِ بَنِي زُرَيْقٍ فَقُلْ لَهُ فَلْيَدْفَعْهَا إِلَيْكَ وَأَطْعِمْ سِتِّينَ مِسْكِينًا وَانْتَفِعْ بِبَقِيَّتِهَا."],"takhrij":"حسن: رواه أبو داود (2213) وابن ماجة (2062) والترمذي مطولا (3299) ومختصرا (1198) وصحّحه ابن خزيمة (2378) والحاكم (2/203) كلهم من حديث محمد بن إسحاق، عن محمد بن عمرو بن عطاء، عن سليمان بن يسار، عن سلمة بن صخر فذكره.","grade":"حسن","chapter_ar":"باب المظاهر يجامع قبل أن يكفر","chapter_ur":"","part_ar":"كتاب الظهار والإيلاء","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2213), Ibn Majah (2062), al-Tirmidhi (3299), who graded it hasan, and authenticated by Ibn Khuzaymah (2378).","chapter_en":"Chapter on the One Who Pronounces Zihār Having Intercourse Before Making Expiation","part_en":"Book of Zihār and Īlāʾ","group_ar":"","group_en":"","part_no":28,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Salamah ibn Sakhr al-Bayadi said: I was a man very given to women; I do not think any man had as much desire in that regard as I had. When Ramadan entered, I pronounced zihār against my wife until Ramadan was over. Then one night while she was speaking to me, something of her became uncovered to me, so I sprang upon her and had intercourse with her. When morning came, I went early to my people and informed them of my situation, and I said to them: Ask the Messenger of Allah ﷺ for me. They said: We will not do that, lest Allah reveal something concerning us, or a statement about us come from the Messenger of Allah ﷺ and its disgrace remain upon us. Rather, we will leave you to bear your own offense. Go yourself and mention your case to the Messenger of Allah ﷺ. So I went until I came to him and informed him of the matter. The Messenger of Allah ﷺ said: “Was it you who did that?” I said: It was I, and here I am, O Messenger of Allah, content to bear Allah’s judgment upon me. He said: “Then free a slave.” I said: By the One who sent you with the truth, I own nothing this morning except this neck of mine. He said: “Then fast two consecutive months.” I said: O Messenger of Allah, was it not from fasting that what befell me befell me? He said: “Then give charity or feed sixty poor people.” I said: By the One who sent you with the truth, we spent this night without any supper. He said: “Go to the custodian of the charity of Banu Zurayq and tell him to give it to you. Feed sixty poor people, and benefit from what remains.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2213,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2062},{"key":"tirmidhi","label":"الترمذي","number":3299},{"key":"ibnkhuzaymah","label":"ابن خزيمه","number":2378}],"full":1,"dr":1},{"num":6642,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ لَمْ يَكْذِبْ إِبْرَاهِيمُ ـ عَلَيْهِ السَّلاَمُ ـ إِلاَّ ثَلاَثَ كَذَبَاتٍ ثِنْتَيْنِ مِنْهُنَّ فِي ذَاتِ اللَّهِ عَزَّ وَجَلَّ، قَوْلُهُ {إِنِّي سَقِيمٌ."],"takhrij":"متفق عليه: رواه البخاري في أحاديث الأنبياء (3358) ومسلم في الفضائل (2371) كلاهما من حديث أيوب، عن محمد بن سيرين، عن أبي هريرة فذكره في سياق أطول كما هو مذكور في أخبار الأنبياء.","grade":"متفق عليه","chapter_ar":"باب ليس من الظهار أن يقول الرجل لامرأته : يا أختي","chapter_ur":"","part_ar":"كتاب الظهار والإيلاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3358) and Muslim (2371).","chapter_en":"Chapter on It Not Being Zihār for a Man to Say to His Wife: “My Sister”","part_en":"Book of Zihār and Īlāʾ","group_ar":"","group_en":"","part_no":28,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Ibrahim, peace be upon him, did not utter an untruth except three times, two of them for the sake of Allah, Mighty and Exalted. And one of them was his statement to Sarah: ‘She is my sister.’”"]},"buhuth":{"en":["The legal understanding is that whoever says to his wife, “You are my sister,” without intending zihār, but rather intending honor, respect, or indirect speech, then it is not zihār. But if he intends zihār, then it is like his saying: “You are like my mother.”","As for Ibrahim’s “untruth,” it is understood as indirect speech. People found it difficult that it was called a lie although the speaker intended by the wording the meaning he meant, so how could it be a lie? The correct understanding is that it was a lie in relation to what the listener understood, not in relation to the speaker’s intended meaning. Speech has two relations: one to the speaker and one to the listener. So when the one speaking indirectly intended the listener to understand something other than what he meant by his wording, it was called a lie from that perspective, even though the speaker was truthful in terms of his intention and meaning. This was stated by al-Hafiz Ibn al-Qayyim in Tahdhib al-Sunan (3/137)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3358,"lafz":true},{"key":"muslim","label":"مسلم","number":2371}],"full":1,"dr":1},{"num":6643,"demo":false,"sanad":"","matn":["عَنْ نَافِعٍ، أَنَّ ابْنَ عُمَرَ، رَضِيَ اللَّهُ عَنْهُمَا كَانَ يَقُولُ فِي الإِيلاَءِ الَّذِي سَمَّى اللَّهُ لاَ يَحِلُّ لأَحَدٍ بَعْدَ الأَجَلِ إِلاَّ أَنْ يُمْسِكَ بِالْمَعْرُوفِ، أَوْ يَعْزِمَ بِالطَّلاَقِ، كَمَا أَمَرَ اللَّهُ عَزَّ وَجَلَّ."],"takhrij":"صحيح: رواه البخاري في الطلاق (5290) عن قتيبة، حدثنا الليث، عن نافع، أن ابن عمر كان يقول: وعنه أيضا قال: إذا مضتْ أربعةُ أشهرٍ يُوقَفُ حتى يطلّق، ولا يقع عليه الطلاق حتى يُطلِّق.","grade":"صحيح","chapter_ar":"باب ما جاء في الإيلاء","chapter_ur":"","part_ar":"كتاب الظهار والإيلاء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5290).","chapter_en":"Chapter on What Has Been Reported Regarding Īlāʾ","part_en":"Book of Zihār and Īlāʾ","group_ar":"","group_en":"","part_no":28,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar used to say regarding the īlāʾ that Allah mentioned: “It is not lawful for anyone after the period has ended except that he either keep her honorably or resolve upon divorce as Allah, Mighty and Exalted, has commanded.”"]},"buhuth":{"en":["Īlāʾ means swearing an oath, and its plural is alayā. It is for a man to swear that he will not go in to his wife. Allah made the maximum period four months. During this period, he must either go back on his oath and make expiation, or divorce. It is not permissible for him to leave the woman suspended, neither having intercourse with her nor divorcing her. If he refuses both, then the judge divorces on his behalf or annuls the marriage."]},"intro":{"ar":["قال الله تعالى: ( لَِّذِينَ يُؤْلُونَ مِن نسَآبِهِمْ تَرْبُصُ أَرْبَعَةِ أَشْهُرِ فَإِن فَآءُو فَإِنَّ اللَّهَ غَفُورٌ زَحِيمٌ (٦) وَانْ عَزَمُوا الطَّلَقَ فَإِنَّ للَّهَ سَمِيعٌ عَلِيمٌ } [البقرة: ٢٢٧ - ٢٢٦ ]"],"en":["Allah the Exalted said: “For those who swear abstinence from their wives is a waiting period of four months. But if they return, then indeed Allah is Forgiving, Merciful. And if they resolve upon divorce, then indeed Allah is All-Hearing, All-Knowing.” [al-Baqarah: 226–227]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5290,"lafz":true}],"full":1,"dr":1},{"num":6644,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ قَالَ: لَمْ أَزَلْ حَرِيصًا عَلَى أَنْ أَسْأَلَ عُمَرَ بْنَ الْخَطَّابِ عَنِ الْمَرْأَتَيْنِ مِنْ أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اللَّتَيْنِ قَالَ اللَّهُ تَعَالَى: ﴿إِنْ تَتُوبَا إِلَى اللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا﴾ [التحريم: ٤ ] حَتَّى حجَّ وَحَجَجْتُ مَعَهُ، وَعَدَلَ وَعَدَلْتُ مَعَهُ بِإِدَاوَةٍ، فَتَبَرَّزَ ثُمَّ جَاءَ فَسَكَبْتُ عَلَى يَدَيْهِ مِنْهَا فَتَوَضَّأَ، فَقُلْتُ لَهُ: يَا أَمِيرَ الْمُؤْمِنِينَ! مَن الْمَرْأَتَانِ مِنْ أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اللَّتَانِ قَالَ اللَّهُ تَعَالَى ﴿إِنْ تَتُوبَا إِلَى اللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا﴾ [التحريم: ٤ ]؟ قَالَ: وَاعَجَبًا لَكَ يَا ابْنَ عَبَّاسٍ، هُمَا عَائِشَةُ وَحَفْصَةُ، ثُمَّ اسْتَقْبَلَ عُمَرُ الْحَدِيثَ يَسُوقُهُ قَالَ: كُنْتُ أَنَا وَجَارٌ لِي مِنَ الأَنْصَارِ فِي بَنِي أُمَيَّةَ ين زَيْدٍ وَهُمْ مِنْ عَوَالِي الْمَدِينَةِ، وَكُنَّا نَتَنَاوَبُ النُّزُولَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَيَنْزِلُ يَوْمًا وَأَنْزِلُ يَوْمًا، فَإِذَا نَزَلْتُ جِئْتُهُ بِمَا حَدَثَ مِنْ خَبَرِ ذَلِكَ الْيَوْمِ مِنَ الوحي أَوْ غَيْرِهِ، وَإِذَا نَزَلَ فَعَلَ مِثْلَ ذَلِكَ، وَكُنَّا مَعْشَرَ قُرَيْشٍ نَغْلِبُ النِّسَاءَ، فَلَمَّا قَدِمْنَا عَلَى الأَنْصَارِ، إِذَا قَوْمٌ تَغْلِبُهُمْ نِسَاؤُهُمْ، فَطَفِقَ نِسَاؤُنَا يَأْخُذْنَ مِنْ أَدَبِ نِسَاءِ الأَنْصَارِ. فصَخِبْتُ عَلَى امْرَأَتِي فَرَاجَعَتْنِي، فَأَنْكَرْتُ أَنْ تُرَاجِعَنِي قَالَتْ: وَلِمَ تُنْكِرُ أَنْ أُرَاجِعَكَ؟ فو الله إِنَّ أَزْوَاجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيُرَاجِعْنَهُ، وَإِنَّ إِحْدَاهُنَّ لَتَهْجُرُهُ الْيَوْمَ حَتَّى اللَّيْلِ. فَأَفْزَعَنِي ذَلِكَ فَقُلْتُ لَهَا: قَدْ خَابَ مَنْ فَعَلَ ذَلِكَ مِنْهُنَّ. ثُمَّ جَمَعْتُ علي ثِيَابِي، فَنَزَلْتُ حَتَّى دخلتُ عَلَى حَفْصَةَ فَقُلْتُ لَهَا: أي حَفْصَةُ أ تُغاضب إِحْدَاكُنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْيَوْمَ حَتَّى اللَّيْلِ؟ قَالَتْ: نَعَمْ، فَقُلْتُ: قَدْ خبتِ وَخَسِرْتِ، أَفَتَأْمَنِينَ أَنْ يَغْضَبَ اللَّهُ لِغَضَبِ رسول اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَتَهْلِكِي؟ لاَ تَسْتَكْثِرِي النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلاَ تُرَاجِعِيهِ فِي شيء وَلاَ تَهْجُرِيهِ، وَسَلِينِي مَا بَدَا لكِ، وَلاَ يَغُرَّنَّكِ أَنْ كَانَتْ جَارَتُكِ أَوْضَأَ مِنْكِ، وَأَحَبَّ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، -يُرِيدُ عَائِشَةَ- قَالَ عُمَرُ: وَكُنَّا قَدْ تَحَدَّثْنَا أَنَّ غَسَّانَ تُنْعل الْخَيْلَ لتغزونا، فَنَزَلَ صَاحِبِي الأَنْصَارِيُّ يومَ نَوْبَتِهِ، فَرَجَعَ إِلَيْنَا عِشَاءً فَضَرَبَ بَابِي ضَرْبًا شَدِيدًا وَقَالَ: أَثَمَّ هُوَ؟ فَفَزِعْتُ فَخَرَجْتُ إِلَيْهِ، فَقَالَ: قَدْ حدثَ الْيَوْمَ أمرٌ عَظِيمٌ، قُلْتُ: مَا هُوَ؟ أَجَاءَ غَسَّانُ؟ قَالَ: لاَ، بَلْ أَعْظَمُ مِنْ ذَلِكَ وَأَهْوَلُ، طلّق النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نِسَاءَهُ.","وقال عبيد بن حنين: سمع ابن عباس عن عمر فقال: اعتزل النبيصلى الله عليه وسلم أزواجه، فقلت: خابت حفصةُ وخسرتْ، وقد كنت أظنُّ هذا يوشك أن يكون، فجمعتُ عليّ ثيابي، فصليتُ صلاة الفجر مع النبي صلى الله عليه وسلم، فدخل النبي صلى الله عليه وسلم مشربةً له فاعتزل فيها، ودخلت على حفصة فإذا هي تبكي، فقلت: ما يُبكيك؟ ألم أكن حذّرتك هذا، أطلّقكن النبي صلى الله عليه وسلم؟ قالت: لا أدري، ها هو ذا معتزل في المشربة. فخرجت فجئت إلى المنبر فإذا حوله رهط يبكي بعضهم، فجلستُ معهم قليلا، ثم غلبني ما أجد فجئتُ المشربةَ التي فيها النبي صلى الله عليه وسلم، فقلتُ لغلام أسود: استأذنْ لعمر. فدخل الغلام فكلّم النبي صلى الله عليه وسلم ثم رجع فقال: كلّمتُ النبي صلى الله عليه وسلم وذكرتُك له فصمتَ، فانصرفتُ حتى جلستُ مع الرهط الذين عند المنبر. ثم غلبني ما أجدُ فجئت فقلت للغلام: استأذن لعمر، فدخل ثم رجع فقال: قد ذكرتك له فصمتَ، فرجعتُ فجلست مع الرهط مع المنبر، ثم غلبني ما أجد، فجئت الغلام فقلت: استأذن لعمر، فدخل ثم رجع إليَّ فقال: قد ذكرتك له فصمَتَ، فلمّا ولَّيتُ منصرفا قال: إذا الغلام يدعوني فقال: قد أذنَ لك النبي صلى الله عليه وسلم. فدخلت على رسول الله صلى الله عليه وسلم فإذا هو مُضطجع على رمال حصير ليس بينه وبينه فراش قد أثّر الرمال بجنبه، متكئا على وسادة من أدم حشوها ليف، فسلّمتُ عليه. ثم قلت وأنا قائم: يا رسول الله أطلقتَ نساءك؟ فرفع إليَّ بصره فقال: لا. فقلت: الله أكبر. ثم قلت وأنا قائم أستأنس: يا رسولَ الله لو رأيتني وكنا معشر قريش نغلبُ النساءَ، فلما قدمنا المدينة إذا قوم تغلبهم نساؤُهم، فتبسّم النبي صلى الله عليه وسلم ثم قلت: يا رسول الله لو رأيتني ودخلت على حفصة فقلت لها: لا يغرنّك أن كانت جارتُك أوضأ منك وأحب إلى النبي صلى الله عليه وسلم يريد عائشة. فتبسّم النبي صلى الله عليه وسلم تبسمة أخرى. فجلستُ حين رأيته تبسَّم، فرفعت بصري في بيته فو الله ما رأيت في بيته شيئا يرد البصر غير أهبة ثلاثة، فقلت: يا رسول الله! ادع الله فليُوسّع على أمتك، فإن فارس والروم قد وُسّعَ عليهم، وأعطوا الدنيا وهم لا يعبدون الله. فجلس النبيصلى الله عليه وسلم وكان متكئا فقال: أوفي هذا أنت يا ابن الخطاب؟ إن أولئك قوم قد عُجِّلُوا طيباتهم في الحياة الدنيا فقلت: يا رسول الله استغفر لي.","فاعتزل النبي صلى الله عليه وسلم نساءَه من أجل ذلك الحديث حين أفشته حفصةُ إلى عائشة تسعا وعشرين ليلة، وكان قال: ما أنا بداخل عليهن شهراً من شدة موجدتِه عليهن حين عاتبه الله عز وجل، فلما مضت تسعٌ وعشرون ليلة دخل على عائشة فبدأ بها، فقالت له عائشة: يا رسول الله! إنك كنتَ قد أقسمتَ أن لا تدخل علينا شهرا، وإنما أصبحت من تسع وعشرين ليلة أعدها عداً، فقال: الشهر تسع وعشرون ليلة، فكان ذلك الشهر تسعا وعشرين ليلة، قالت عائشة: ثم أنزل الله تعالى آية التخيير فبدأ بي أوّل امرأة من نسائه فاخترتُه، ثم خيّر نساءه كلهن فقلن مثل ما قالت عائشة."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5191) من طريق شعيب، عن الزهري قال: أخبرني عبيد الله بن عبد الله بن أبي ثور، عن ابن عباس، فذكره. ورواه مسلم (34:1479) من طريق معمر، عن الزهري، به. مثله إلى قوله: حين عاتبه الله عز وجل  وفي مسلم حتى عاتبه الله عز وجل  ثم قال مسلم (35:1475) قال الزهري: فأخبرني عروة، عن عائشة قالت: لما مضى تسع وعشرون ليلة...  وذكرت بقية الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الإيلاء","chapter_ur":"","part_ar":"كتاب الظهار والإيلاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5191) and Muslim (1479/34).","chapter_en":"Chapter on What Has Been Reported Regarding Īlāʾ","part_en":"Book of Zihār and Īlāʾ","group_ar":"","group_en":"","part_no":28,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Ibn ʿAbbas said: I remained eager to ask ʿUmar ibn al-Khattab about the two women among the wives of the Prophet ﷺ concerning whom Allah the Exalted said: “If you two repent to Allah, then indeed your hearts have inclined.” [al-Tahrim: 4] This continued until he went for Hajj and I went with him. He moved aside and I moved aside with him carrying a water vessel. He relieved himself, then came back, and I poured water from it over his hands, and he performed wudu’. Then I said to him: O Commander of the Believers, who are the two women among the wives of the Prophet ﷺ concerning whom Allah the Exalted said: “If you two repent to Allah, then indeed your hearts have inclined”? He said: How strange of you, O Ibn ʿAbbas. They are ʿA’ishah and Hafsah. Then ʿUmar began narrating the story. He said: I and a neighbor of mine from the Ansar among Banu Umayyah ibn Zayd, from the high area of Madinah, used to alternate going down to the Prophet ﷺ. He would go down one day and I another day. When I went down, I would bring him the news of that day—revelation or anything else—and when he went down he would do the same. We, the Quraysh, used to dominate women, but when we came to the Ansar, they were a people whose women dominated them. Our women then began to adopt the manners of the women of the Ansar. I shouted at my wife and she answered me back, and I objected that she would answer me back. She said: Why do you object that I answer you back? By Allah, the wives of the Prophet ﷺ answer him back, and one of them may avoid him the whole day until night. That alarmed me, and I said to her: Whoever among them does that has failed. Then I gathered my clothes and went down until I entered upon Hafsah and said to her: O Hafsah, does one of you anger the Prophet ﷺ the whole day until night? She said: Yes. I said: You have failed and lost. Do you feel safe that Allah may become angry because of the anger of the Messenger of Allah ﷺ and you be ruined? Do not ask too much of the Prophet ﷺ, do not answer him back in anything, and do not abandon him. Ask me for whatever you need. And do not let it deceive you that your neighbor is more beautiful than you and more beloved to the Prophet ﷺ—meaning ʿA’ishah. ʿUmar said: We had been speaking that Ghassan were shoeing their horses to attack us. Then my Ansari companion came down on his day and returned to us at evening, striking my door violently and saying: Is he there? I was alarmed and went out to him. He said: Today a great matter has occurred. I said: What is it? Have Ghassan come? He said: No, rather greater and more serious than that: the Prophet ﷺ has divorced his wives. ʿUbayd ibn Hunayn said: Ibn ʿAbbas heard from ʿUmar, and he said: The Prophet ﷺ withdrew from his wives, so I said: Hafsah has failed and lost, and I had thought this was likely to happen. I gathered my clothes, prayed Fajr with the Prophet ﷺ, then the Prophet ﷺ entered an upper room of his and secluded himself there. I entered upon Hafsah and found her weeping. I said: Why are you weeping? Did I not warn you about this? Has the Prophet ﷺ divorced you? She said: I do not know. There he is, withdrawn in the upper room. So I went out and came to the pulpit, and around it was a group, some of whom were weeping. I sat with them for a little while, then what I felt overcame me, so I came to the upper room where the Prophet ﷺ was and said to a black servant: Ask permission for ʿUmar. The servant entered and spoke to the Prophet ﷺ, then returned and said: I mentioned you to the Prophet ﷺ and he remained silent. So I went back and sat with the people near the pulpit. Then what I felt overcame me again, so I came and said to the servant: Ask permission for ʿUmar. He entered and then returned and said: I mentioned you to him and he remained silent. So I returned and sat again with the group near the pulpit. Then what I felt overcame me once more, so I came to the servant and said: Ask permission for ʿUmar. He entered, then returned to me and said: I mentioned you to him and he remained silent. As I turned to leave, the servant called me and said: The Prophet ﷺ has given you permission.","So I entered upon the Messenger of Allah ﷺ, and there he was lying on a woven mat with no mattress between him and it, and the marks of the mat had appeared on his side. He was reclining on a leather pillow stuffed with palm fiber. I greeted him, then I said while standing: O Messenger of Allah, have you divorced your wives? He raised his gaze to me and said: “No.” I said: Allah is greatest. Then I said while still standing, trying to bring ease: O Messenger of Allah, if only you had seen me. We Quraysh used to dominate women, but when we came to Madinah we found a people whose women dominated them. So the Prophet ﷺ smiled. Then I said: O Messenger of Allah, if only you had seen me when I entered upon Hafsah and said to her: Do not let it deceive you that your neighbor is more beautiful than you and more beloved to the Prophet ﷺ—meaning ʿA’ishah. The Prophet ﷺ smiled a second time. When I saw him smile, I sat down. Then I raised my eyes in his room, and by Allah, I saw nothing in his room that could draw the eye except three tanned hides. So I said: O Messenger of Allah, supplicate to Allah to grant abundance to your nation, for Persia and Rome have been given abundance and granted the worldly life while they do not worship Allah. The Prophet ﷺ sat up, having been reclining, and said: “Are you in this state of mind, O son of al-Khattab? Those are a people whose good things have been hastened for them in the worldly life.” I said: O Messenger of Allah, ask forgiveness for me. The Prophet ﷺ withdrew from his wives because of that matter when Hafsah disclosed it to ʿA’ishah for twenty-nine nights. He had said: “I will not enter upon them for a month,” because of how angry he was with them when Allah the Exalted reproved him. Then when twenty-nine nights had passed, he entered upon ʿA’ishah and began with her. ʿA’ishah said to him: O Messenger of Allah, you had sworn not to enter upon us for a month, but you came after twenty-nine nights, which I counted carefully. He said: “The month is twenty-nine nights.” And that month was twenty-nine nights. ʿA’ishah said: Then Allah the Exalted revealed the verse of giving the choice, so he began with me, the first of his wives, and I chose him. Then he gave all his wives the choice, and they all said what ʿA’ishah said."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5191,"lafz":true},{"key":"muslim","label":"مسلم","number":34},{"key":"muslim","label":"حين عاتبه الله عز وجل وفي مسلم حتي عاتبه الله عز وجل ثم قال مسلم","number":35}],"full":1,"dr":1},{"num":6645,"demo":false,"sanad":"","matn":["عن أُمِّ سَلَمَةَ أَخْبَرَتْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَلَفَ لاَ يَدْخُلُ عَلَى بَعْضِ أَهْلِهِ شَهْرًا، فَلَمَّا مَضَى تِسْعَةٌ وَعِشْرُونَ يَوْمًا غَدَا عَلَيْهِنَّ أَوْ رَاحَ فَقِيلَ لَهُ يَا نَبِيَّ اللَّهِ حَلَفْتَ أَنْ لاَ تَدْخُلَ عَلَيْهِنَّ شَهْرًا قَالَ إِنَّ الشَّهْرَ يَكُونُ تِسْعَةً وَعِشْرِينَ يَوْمًا."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5202) ومسلم في الصيام (1085) من طريق ابن جريج، أخبرني يحيى بن عبد الله بن محمد بن صيفي، أن عكرمة بن عبد الرحمن بن الحارث أخبره، أن أم سلمة أخبرته، فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الإيلاء","chapter_ur":"","part_ar":"كتاب الظهار والإيلاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5202) and Muslim (1085).","chapter_en":"Chapter on What Has Been Reported Regarding Īlāʾ","part_en":"Book of Zihār and Īlāʾ","group_ar":"","group_en":"","part_no":28,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Umm Salamah reported that the Prophet ﷺ swore that he would not enter upon some of his wives for a month. Then when twenty-nine days had passed, he went to them in the morning—or in the afternoon. It was said to him: O Prophet of Allah, you swore not to enter upon them for a month. He said: “A month may be twenty-nine days.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5202,"lafz":true},{"key":"muslim","label":"مسلم","number":1085}],"full":1,"rep":[4326,6314]},{"num":6646,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ بْنِ مَالِكٍ قَالَ: آلَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ نِسَائِهِ، وَكَانَ انفكَّتْ رِجْلُهُ، فَأَقَامَ فِي مَشْرُبَةٍ لَهُ تِسْعًا وَعِشْرِينَ، ثُمَّ نَزَلَ، فَقَالُوا: يَا رَسُولَ اللَّهِ، آلَيْتَ شَهْرًا؟ فَقَالَ: الشَّهْرَ يَكُونُ تسع وَعِشْرُونَ."],"takhrij":"صحيح: رواه البخاري في الطلاق (5289) عن إسماعيل بن أبي أويس، عن أخيه، عن سليمان، عن حميد الطويل، أنه سمع أنس بن مالك يقول: فذكره. ورواه في كتاب الصلاة(378)من وجه آخر عن حميد الطويل مطولاً.","grade":"صحيح","chapter_ar":"باب ما جاء في الإيلاء","chapter_ur":"","part_ar":"كتاب الظهار والإيلاء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5289).","chapter_en":"Chapter on What Has Been Reported Regarding Īlāʾ","part_en":"Book of Zihār and Īlāʾ","group_ar":"","group_en":"","part_no":28,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ made īlāʾ from his wives, and his leg had become injured, so he stayed in an upper room for twenty-nine days. Then he came down, and they said: O Messenger of Allah, you took an oath for a month. He said: “The month may be twenty-nine days.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5289,"lafz":true}],"full":1},{"num":6647,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، رَضِيَ اللَّهُ عَنْهُ أَنَّهُ قَالَ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اعْتَزَلَ نِسَاءَهُ شَهْرًا فَخَرَجَ إِلَيْنَا فِي تِسْعٍ وَعِشْرِينَ فَقُلْنَا إِنَّمَا الْيَوْمُ تِسْعٌ وَعِشْرُونَ. فَقَالَ إِنَّمَا الشَّهْرُ. وَصَفَّقَ بِيَدَيْهِ ثَلاَثَ مَرَّاتٍ وَحَبَسَ إِصْبَعًا وَاحِدَةً فِي الآخِرَةِ."],"takhrij":"صحيح: رواه مسلم في الصوم (1084) من طرق عن الليث، عن أبي الزبير، عن جابر، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الإيلاء","chapter_ur":"","part_ar":"كتاب الظهار والإيلاء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1084).","chapter_en":"Chapter on What Has Been Reported Regarding Īlāʾ","part_en":"Book of Zihār and Īlāʾ","group_ar":"","group_en":"","part_no":28,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ withdrew from his wives for a month. Then he came out to us after twenty-nine days, and we said: It is only the twenty-ninth day. He said: “The month is like this,” and he clapped his hands three times, withholding one finger on the last time."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1084,"lafz":true}],"full":1},{"num":6648,"demo":false,"sanad":"","matn":["عَنِ الزُّهْرِيِّ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَقْسَمَ أَنْ لاَ يَدْخُلَ عَلَى أَزْوَاجِهِ شَهْرًا - قَالَ الزُّهْرِيُّ - فَأَخْبَرَنِي عُرْوَةُ عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ لَمَّا مَضَتْ تِسْعٌ وَعِشْرُونَ لَيْلَةً أَعُدُّهُنَّ دَخَلَ عَلَىَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَتْ بَدَأَ بِي - فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّكَ أَقْسَمْتَ أَنْ لاَ تَدْخُلَ عَلَيْنَا شَهْرًا وَإِنَّكَ دَخَلْتَ مِنْ تِسْعٍ وَعِشْرِينَ أَعُدُّهُنَّ فَقَالَ إِنَّ الشَّهْرَ تِسْعٌ وَعِشْرُونَ."],"takhrij":"صحيح: رواه مسلم في الصيام (1083) عن عبد بن حميد، أخبرنا عبد الرزاق، أخبرنا معمر، عن الزهري فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الإيلاء","chapter_ur":"","part_ar":"كتاب الظهار والإيلاء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1083).","chapter_en":"Chapter on What Has Been Reported Regarding Īlāʾ","part_en":"Book of Zihār and Īlāʾ","group_ar":"","group_en":"","part_no":28,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Al-Zuhri said: The Prophet ﷺ swore that he would not enter upon his wives for a month. Al-Zuhri said: ʿUrwah informed me from ʿA’ishah that when twenty-nine nights had passed, counting them carefully, the Messenger of Allah ﷺ entered upon me. She said: He began with me. So I said: O Messenger of Allah, you swore that you would not enter upon us for a month, yet you entered after twenty-nine nights which I counted. He said: “The month is twenty-nine.”"]},"buhuth":{"en":["And he said: Īlāʾ is for a man to swear that he will not approach his wife for four months or more."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1083,"lafz":true}],"full":1,"dr":1},{"num":6649,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَلَمَةَ قَالَ: جَاءَ رَجُلٌ إِلَى ابْنِ عَبَّاسٍ، وَأَبُو هُرَيْرَةَ جَالِسٌ عِنْدَهُ فَقَالَ: أفْتِني فِي امْرَأَةٍ وَلَدَتْ بَعْدَ زَوْجِهَا بِأَرْبَعِينَ لَيْلَةً، فَقَالَ ابْنُ عَبَّاسٍ: آخِرُ الأَجَلَيْنِ. قُلْتُ أَنَا: ﴿وَأُولَاتُ الْأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ﴾ [الطلاق: ٤ ] قَالَ أَبُو هُرَيْرَةَ: أَنَا مَعَ ابْنِ أَخِي، يَعْنِي أَبَا سَلَمَةَ، فَأَرْسَلَ ابْنُ عَبَّاسٍ كُريباً إِلَى أُمِّ سَلَمَةَ، يَسْأَلُهَا، فَقَالَتْ: قُتل زوجُ سُبَيْعة الأَسْلَمِيَّةِ وهي حُبْلَى، فَوَضَعَتْ بَعْدَ مَوْتِهِ بِأَرْبَعِينَ لَيْلَةً، فخُطِبتْ، فَأَنْكَحَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَكَانَ أَبُو السَّنَابِلِ فِيمَنْ خَطَبَها."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4909) عن سعد بن حفص، حدثنا شيبان، عن يحيى (هو ابن أبي كثير) قال: أخبرني أبو سلمة، فذكره.","grade":"متفق عليه","chapter_ar":"باب عدّة الحامل المطلقة والمتوفى عنها زوجها وضع الحمل","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4909) and Muslim (1485).","chapter_en":"The waiting period of a pregnant divorced woman and a pregnant widow is until delivery","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu Salamah said: A man came to Ibn ʿAbbas, while Abu Hurayrah was sitting with him, and said: “Give me a ruling about a woman who gave birth forty nights after her husband died.” Ibn ʿAbbas said: “The later of the two terms.” I said: “But Allah says: ‘And for those who are pregnant, their term is until they deliver their burden.’” [al-Talaq: 4] Abu Hurayrah said: “I am with my nephew,” meaning Abu Salamah. So Ibn ʿAbbas sent Kurayb to Umm Salamah to ask her, and she said: “The husband of Subayʿah al-Aslamiyyah was killed while she was pregnant, and she gave birth forty nights after his death. Then she was proposed to, and the Messenger of Allah ﷺ married her off. Abu al-Sanabil was among those who proposed to her.”"]},"intro":{"ar":["قال الله تعالى: (وَأُولَٰتُ ٱلْأَحْمَالِ أَجَلُهُنَّ أَن يَضَعْنَ حَمْلَهُنَّ) [سورة الطلاق: ٤]","الآية شاملة للحامل المطلقة، والحامل المتوفى عنها زوجُها فعدتُهن وضع حملهن على أي صفة كان حيا","أو ميتا، تام الخِلقة أو ناقصُها."],"en":["Allah the Exalted said: “And for those who are pregnant, their term is until they deliver their burden.” [Surat al-Talaq: 4]","This verse includes both the pregnant divorced woman and the pregnant woman whose husband has died. Their waiting period ends when they deliver their pregnancy, in whatever form it may be: alive or dead, fully formed or incompletely formed."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4909,"lafz":true},{"key":"muslim","label":"مسلم","number":1485}],"full":1,"dr":1},{"num":6650,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ، أَنَّهُ قَالَ سُئِلَ عَبْدُ اللَّهِ بْنُ عَبَّاسٍ وَأَبُو هُرَيْرَةَ عَنِ الْمَرْأَةِ الْحَامِلِ يُتَوَفَّى عَنْهَا زَوْجُهَا فَقَالَ ابْنُ عَبَّاسٍ آخِرَ الأَجَلَيْنِ. وَقَالَ أَبُو هُرَيْرَةَ إِذَا وَلَدَتْ فَقَدْ حَلَّتْ. فَدَخَلَ أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ عَلَى أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَهَا عَنْ ذَلِكَ فَقَالَتْ أُمُّ سَلَمَةَ وَلَدَتْ سُبَيْعَةُ الأَسْلَمِيَّةُ بَعْدَ وَفَاةِ زَوْجِهَا بِنِصْفِ شَهْرٍ فَخَطَبَهَا رَجُلاَنِ أَحَدُهُمَا شَابٌّ وَالآخَرُ كَهْلٌ فَحَطَّتْ إِلَى الشَّابِّ فَقَالَ الشَّيْخُ لَمْ تَحِلِّي بَعْدُ. وَكَانَ أَهْلُهَا غَيَبًا وَرَجَا إِذَا جَاءَ أَهْلُهَا أَنْ يُؤْثِرُوهُ بِهَا فَجَاءَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ قَدْ حَلَلْتِ فَانْكِحِي مَنْ شِئْتِ."],"takhrij":"صحيح: رواه مالك في الطلاق (83) عن عبد ربه بن سعد بن فيس، عن أبي سلمة بن عبد الرحمن، فذكره.","grade":"صحيح","chapter_ar":"باب عدّة الحامل المطلقة والمتوفى عنها زوجها وضع الحمل","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (83) and al-Nasa’i (3510).","chapter_en":"The waiting period of a pregnant divorced woman and a pregnant widow is until delivery","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu Salamah ibn ʿAbd al-Rahman said: Ibn ʿAbbas and Abu Hurayrah were asked about a pregnant woman whose husband dies. Ibn ʿAbbas said: “The later of the two terms.” Abu Hurayrah said: “Once she gives birth, she becomes lawful to marry.” Then Abu Salamah ibn ʿAbd al-Rahman entered upon Umm Salamah, the wife of the Prophet ﷺ, and asked her about that. Umm Salamah said: “Subayʿah al-Aslamiyyah gave birth half a month after her husband’s death. Then two men proposed to her, one young and the other older. She inclined toward the younger man, so the older man said: ‘You have not yet become lawful.’ Her family was absent, and he hoped that when her family arrived they would prefer him for her. So she came to the Messenger of Allah ﷺ and he said: ‘You have become lawful, so marry whomever you wish.’”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":83,"lafz":true},{"key":"nasai","label":"النسائي","number":3510,"n":3510}],"full":1,"dr":1},{"num":6651,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ: أَنَّ امْرَأَةً مِنْ أَسْلَمَ يُقَالُ لَهَا سُبَيْعة كَانَ تَحْتَ زَوْجِهَا تُوُفِّيَ عَنْهَا وهي حُبْلَى، وخطبها أَبُو السَّنَابِلِ بْنُ بَعْكَكٍ، فَأَبَتْ أَنْ تَنْكِحَهُ، فَقَالَ: وَاللَّهِ مَا يَصْلُحُ أَنْ تَنْكِحيه حَتَّى تعتدِّيْ آخِرَ الأَجَلَيْنِ، فَمَكُثَتْ قَرِيبًا مِنْ عَشْرِ لَيَالٍ، ثُمَّ جَاءَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: انْكِحِي."],"takhrij":"صحيح: رواه البخاري في الطلاق (5318) عن يحيى بن بكير، حدثنا الليث، عن جعفر بن ربيعة، عن عبد الرحمن بن هرمز الأعرج، قال: أخبرني أبو سلمة بن عبد الرحمن أن زينب ابنة أبي سلمة أخبرته عن أمها أم سلمة زوج النبي صلى الله عليه وسلم فذكرته.","grade":"صحيح","chapter_ar":"باب عدّة الحامل المطلقة والمتوفى عنها زوجها وضع الحمل","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5318).","chapter_en":"The waiting period of a pregnant divorced woman and a pregnant widow is until delivery","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Umm Salamah reported that a woman from Aslam named Subayʿah had been married to a husband who died while she was pregnant. Abu al-Sanabil ibn Baʿkak proposed to her, but she refused to marry him. He said: “By Allah, it is not proper for you to marry until you observe the later of the two terms.” So she remained for around ten nights, then she came to the Prophet ﷺ, and he said: “Marry.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5318,"lafz":true}],"full":1},{"num":6652,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن عُتْبَةَ بن مَسْعُودٍ أَنَّ أَبَاهُ، كَتَبَ إِلَى عُمَرَ بْنِ عَبْدِ اللَّهِ بْنِ الأَرْقَمِ الزُّهْرِيِّ يَأْمُرُهُ أَنْ يَدْخُلَ، عَلَى سُبَيْعَةَ بِنْتِ الْحَارِثِ الأَسْلَمِيَّةِ فَيَسْأَلَهَا عَنْ حَدِيثِهَا وَعَمَّا قَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ اسْتَفْتَتْهُ فَكَتَبَ عُمَرُ بْنُ عَبْدِ اللَّهِ إِلَى عَبْدِ اللَّهِ بْنِ عُتْبَةَ يُخْبِرُهُ أَنَّ سُبَيْعَةَ أَخْبَرَتْهُ أَنَّهَا كَانَتْ تَحْتَ سَعْدِ ابْنِ خَوْلَةَ وَهُوَ فِي بَنِي عَامِرِ بْنِ لُؤَىٍّ وَكَانَ مِمَّنْ شَهِدَ بَدْرًا فَتُوُفِّيَ عَنْهَا فِي حَجَّةِ الْوَدَاعِ وَهْىَ حَامِلٌ فَلَمْ تَنْشَبْ أَنْ وَضَعَتْ حَمْلَهَا بَعْدَ وَفَاتِهِ فَلَمَّا تَعَلَّتْ مِنْ نِفَاسِهَا تَجَمَّلَتْ لِلْخُطَّابِ فَدَخَلَ عَلَيْهَا أَبُو السَّنَابِلِ بْنُ بَعْكَكٍ - رَجُلٌ مِنْ بَنِي عَبْدِ الدَّارِ - فَقَالَ لَهَا مَا لِي أَرَاكِ مُتَجَمِّلَةً لَعَلَّكِ تَرْجِينَ النِّكَاحَ إِنَّكِ وَاللَّهِ مَا أَنْتِ بِنَاكِحٍ حَتَّى تَمُرَّ عَلَيْكِ أَرْبَعَةُ أَشْهُرٍ وَعَشْرٌ. قَالَتْ سُبَيْعَةُ فَلَمَّا قَالَ لِي ذَلِكَ جَمَعْتُ عَلَىَّ ثِيَابِي حِينَ أَمْسَيْتُ فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلْتُهُ عَنْ ذَلِكَ فَأَفْتَانِي بِأَنِّي قَدْ حَلَلْتُ حِينَ وَضَعْتُ حَمْلِي وَأَمَرَنِي بِالتَّزَوُّجِ إِنْ بَدَا لِي.","قال ابن شهاب: فلا أرى بأسا أن تتزوج حين وضعتْ. وإن كانت في دمها. غير أن لا يقربها زوجُها حتى تطهر."],"takhrij":"متفق عليه: رواه البخاري في الطلاق (5319) من طريق يزيد- ومسلم في الطلاق (1484) من طريق يونس ين يزيد – كلاهما عن ابن شهاب الزهري، حدثني عبيد الله بن عبد الله بن عتبة بن مسعود أن أباه كتب إلى عمر بن عبد الله بن الأرقم الزهري، فذكره واللفظ لمسلم، وعند البخاري مختصرا جداً.","grade":"متفق عليه","chapter_ar":"باب عدّة الحامل المطلقة والمتوفى عنها زوجها وضع الحمل","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5319) and Muslim (1484), and this is the wording of Muslim.","chapter_en":"The waiting period of a pregnant divorced woman and a pregnant widow is until delivery","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullah ibn ʿUtbah ibn Masʿud reported that his father wrote to ʿUmar ibn ʿAbdullah ibn al-Arqam al-Zuhri, instructing him to enter upon Subayʿah bint al-Harith al-Aslamiyyah and ask her about her account and what the Messenger of Allah ﷺ said to her when she asked him for a ruling. So ʿUmar ibn ʿAbdullah wrote back to ʿAbdullah ibn ʿUtbah informing him that Subayʿah told him that she had been married to Saʿd ibn Khawlah, from Banu ʿAmir ibn Lu’ayy, and he had been among those who witnessed Badr. He died during the Farewell Pilgrimage while she was pregnant. Soon after his death, she delivered her child. When she became pure from her postnatal bleeding, she beautified herself for suitors. Abu al-Sanabil ibn Baʿkak, a man from Banu ʿAbd al-Dar, entered upon her and said: “Why do I see you beautified? Perhaps you are hoping for marriage. By Allah, you are not to marry until four months and ten days have passed over you.” Subayʿah said: “When he said that to me, I gathered my clothes around me that evening and went to the Messenger of Allah ﷺ and asked him about that. He gave me the ruling that I had become lawful when I delivered my pregnancy, and he ordered me to marry if I wished.” Ibn Shihab said: “So I see no harm in her marrying once she has delivered, even if she is still in her blood, except that her husband should not approach her until she becomes pure.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5319,"lafz":true},{"key":"muslim","label":"مسلم","number":1484}],"full":1,"dr":1},{"num":6653,"demo":false,"sanad":"","matn":["عَنْ مُحَمَّدِ بْنِ سِيرِينَ، قَالَ جَلَسْتُ إِلَى مَجْلِسٍ فِيهِ عُظْمٌ مِنَ الأَنْصَارِ وَفِيهِمْ عَبْدُ الرَّحْمَنِ بْنُ أَبِي لَيْلَى، فَذَكَرْتُ حَدِيثَ عَبْدِ اللَّهِ بْنِ عُتْبَةَ فِي شَأْنِ سُبَيْعَةَ بِنْتِ الْحَارِثِ، فَقَالَ عَبْدُ الرَّحْمَنِ وَلَكِنَّ عَمَّهُ كَانَ لاَ يَقُولُ ذَلِكَ. فَقُلْتُ إِنِّي لَجَرِيءٌ إِنْ كَذَبْتُ عَلَى رَجُلٍ فِي جَانِبِ الْكُوفَةِ. وَرَفَعَ صَوْتَهُ، قَالَ ثُمَّ خَرَجْتُ فَلَقِيتُ مَالِكَ بْنَ عَامِرٍ أَوْ مَالِكَ بْنَ عَوْفٍ قُلْتُ كَيْفَ كَانَ قَوْلُ ابْنِ مَسْعُودٍ فِي الْمُتَوَفَّى عَنْهَا زَوْجُهَا وَهْىَ حَامِلٌ فَقَالَ قَالَ ابْنُ مَسْعُودٍ أَتَجْعَلُونَ عَلَيْهَا التَّغْلِيظَ، وَلاَ تَجْعَلُونَ لَهَا الرُّخْصَةَ لَنَزَلَتْ سُورَةُ النِّسَاءِ الْقُصْرَى بَعْدَ الطُّولَى."],"takhrij":"صحيح: رواه البخاري في التفسير (4532) عن حبان، حدثنا عبد الله، أخبرنا عبد الله بن عون، عن محمد بن سيرين فذكره.","grade":"صحيح","chapter_ar":"باب عدّة الحامل المطلقة والمتوفى عنها زوجها وضع الحمل","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4532).","chapter_en":"The waiting period of a pregnant divorced woman and a pregnant widow is until delivery","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Muhammad ibn Sirin said: I sat in a gathering in which there were leading men from the Ansar, among them ʿAbd al-Rahman ibn Abi Layla, and I mentioned the hadith of ʿAbdullah ibn ʿUtbah concerning Subayʿah bint al-Harith. ʿAbd al-Rahman said: “But his uncle did not used to say that.” I said: “How bold I would be if I lied against a man in the region of Kufah,” and I raised my voice. Then I went out and met Malik ibn ʿAmir—or Malik ibn ʿAwf. I said: “What was Ibn Masʿud’s opinion concerning a woman whose husband dies while she is pregnant?” He said: Ibn Masʿud said: “Do you make things more difficult for her and do not give her the concession? The shorter Surat al-Nisa’ was revealed after the longer one.”"]},"buhuth":{"en":["His statement, “his uncle did not used to say that,” refers to ʿAbdullah ibn Masʿud. It means that he was reported not to have given the ruling of Subayʿah bint al-Harith. But this report from him is not correct, for Ibn Masʿud actually held the opposite view. Perhaps he first held one opinion and then changed it, or the narrator erred regarding him, as Ibn Hajar said.","And “the shorter Surat al-Nisa’” means Surat al-Talaq, while “the longer one” means Surat al-Baqarah.","In Surat al-Baqarah is: “And those among you who die and leave wives behind—they shall wait by themselves for four months and ten days.” [al-Baqarah: 234]","And in Surat al-Talaq is: “And for those who are pregnant, their term is until they deliver their burden.”","Ibn Masʿud intended that there had been abrogation, so the later verse would be the abrogating one. This is what Ibn Masʿud pointed to by his statement: “Whoever wishes, I will invoke mutual imprecation with him that the shorter Surat al-Nisa’ was revealed after the verse of four months and ten.” Here, mulaʿanah means mutual invocation. This was narrated by Abu Dawud (2307) and Ibn Majah (2030) with an authentic chain.","Al-Hafiz Ibn Hajar said: “But the correct view is that there is no abrogation here. Rather, the general wording of the verse in al-Baqarah is specified by the verse of al-Talaq.” (Fath al-Bari, 8/656)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4532,"lafz":true}],"full":1,"dr":1,"rep":[13581]},{"num":6654,"demo":false,"sanad":"","matn":["عَنِ الْمِسْوَرِ بْنِ مَخْرَمَةَ، أَنَّهُ أَخْبَرَهُ أَنَّ سُبَيْعَةَ الأَسْلَمِيَّةَ نُفِسَتْ بَعْدَ وَفَاةِ زَوْجِهَا بِلَيَالٍ فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ حَلَلْتِ فَانْكِحِي مَنْ شِئْتِ."],"takhrij":"صحيح: رواه مالك في الطلاق (58) عن هشام بن عروة، عن أبيه، عن المسور بن مخرمة، به، فذكره. ورواه البخاري في الطلاق (5320) من طريق مالك، به، بنحوه.","grade":"صحيح","chapter_ar":"باب عدّة الحامل المطلقة والمتوفى عنها زوجها وضع الحمل","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5320).","chapter_en":"The waiting period of a pregnant divorced woman and a pregnant widow is until delivery","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Al-Miswar ibn Makhramah reported that Subayʿah al-Aslamiyyah gave birth a few nights after her husband’s death, and the Messenger of Allah ﷺ said to her: “You have become lawful, so marry whomever you wish.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5320},{"key":"malik","label":"مالك في الطلاق","number":58,"lafz":true}],"full":1,"rep":[12012]},{"num":6655,"demo":false,"sanad":"","matn":["عَنْ أُمِّ الطفيل امرأة أَبِي بن كَعْبٍ قَالَتْ: إنها سَمِعَتْ عُمَرَ بْنَ الْخَطَّابِ وَأُبَيَّ بْنَ كَعْبٍ يَخْتَصِمَانِ، فَقَالَتْ أُمُّ الطُّفَيْلِ: أَفَلَا يَسْأَلُ عمرُ بْنُ الْخَطَّابِ سُبَيْعَةَ الْأَسْلَمِيَّةَ؟ تُوُفِّيَ عَنْهَا زَوْجُهَا وَهِيَ حَامِلٌ، فَوَضَعَتْ بَعْدَ ذَلِكَ بِأَيَّامٍ، فَأَنْكَحَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ."],"takhrij":"حسن: رواه أحمد (27109) عن يحيى بن إسحاق وقتيبة بن سعيد، قالا: حدثنا ابن لهيعة، عن بكير بن عبدالله بن الأشج، عن بسر بن سعيد، قال: سمعت أم الطفيل، فذكرته. وإسناده حسن من أجل ابن لهيعة، فإن سماع قتيبة بن سعيد كان قبل اختلاطه.","grade":"حسن","chapter_ar":"باب عدّة الحامل المطلقة والمتوفى عنها زوجها وضع الحمل","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (27109).","chapter_en":"The waiting period of a pregnant divorced woman and a pregnant widow is until delivery","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Umm al-Tufayl, the wife of Ubayy ibn Kaʿb, said: She heard ʿUmar ibn al-Khattab and Ubayy ibn Kaʿb disputing, so Umm al-Tufayl said: “Why does ʿUmar ibn al-Khattab not ask Subayʿah al-Aslamiyyah? Her husband died while she was pregnant, then she gave birth a few days later, and the Messenger of Allah ﷺ married her off.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":27109,"n":27109,"lafz":true}],"full":1},{"num":6656,"demo":false,"sanad":"","matn":["عَنْ أَبِي السَّنَابِلِ بْنِ بَعْكَكٍ، قَالَ وَضَعَتْ سُبَيْعَةُ بَعْدَ وَفَاةِ زَوْجِهَا بِثَلاَثَةٍ وَعِشْرِينَ أَوْ خَمْسَةٍ وَعِشْرِينَ يَوْمًا فَلَمَّا تَعَلَّتْ تَشَوَّفَتْ لِلنِّكَاحِ فَأُنْكِرَ عَلَيْهَا ذَلِكَ فَذُكِرَ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ إِنْ تَفْعَلْ فَقَدْ حَلَّ أَجَلُهَا."],"takhrij":"صحيح: رواه الترمذي (1193) والنسائي (3508) وابن ماجة (2027) وأحمد (18713) وصحّحه ابن حبان (4299) كلهم من حديث منصور، عن إبراهيم، عن الأسود، عن أبي السنابل فذكره.","grade":"صحيح","chapter_ar":"باب عدّة الحامل المطلقة والمتوفى عنها زوجها وضع الحمل","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1193), al-Nasa’i (3508), Ibn Majah (2027), and Ahmad (18713).","chapter_en":"The waiting period of a pregnant divorced woman and a pregnant widow is until delivery","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu al-Sanabil ibn Baʿkak said: Subayʿah gave birth twenty-three or twenty-five days after her husband’s death. When she became pure, she desired marriage, and I objected to that. Then that was mentioned to the Prophet ﷺ and he said: “If she does so, then her term has indeed ended.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1193,"lafz":true},{"key":"nasai","label":"النسائي","number":3508},{"key":"ibnmajah","label":"ابن ماجه","number":2027},{"key":"ahmad","label":"مسند الإمام أحمد","number":18713,"n":18714},{"key":"ibnhibban","label":"ابن حبان","number":4299}],"full":1,"dr":1},{"num":6657,"demo":false,"sanad":"","matn":["عَنْ مَسْرُوقٍ، وَعَمْرِو بْنِ عُتْبَةَ، أَنَّهُمَا كَتَبَا إِلَى سُبَيْعَةَ بِنْتِ الْحَارِثِ يَسْأَلاَنِهَا عَنْ أَمْرِهَا، فَكَتَبَتْ إِلَيْهِمَا إِنَّهَا وَضَعَتْ بَعْدَ وَفَاةِ زَوْجِهَا بِخَمْسَةٍ وَعِشْرِينَ فَتَهَيَّأَتْ تَطْلُبُ الْخَيْرَ فَمَرَّ بِهَا أَبُو السَّنَابِلِ بْنُ بَعْكَكٍ فَقَالَ قَدْ أَسْرَعْتِ اعْتَدِّي آخِرَ الأَجَلَيْنِ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا. فَأَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ يَا رَسُولَ اللَّهِ اسْتَغْفِرْ لِي. قَالَ وَمِمَّ ذَاكَ. فَأَخْبَرْتُهُ. فَقَالَ إِنْ وَجَدْتِ زَوْجًا صَالِحًا فَتَزَوَّجِي."],"takhrij":"صحيح: رواه ابن ماجه (2028) حدثنا أبو بكر بن أبي شيبة، قال: حدثنا علي بن مسهر، عن داود بن أبي هند، عن الشعبي، عن مسروق وعمرو بن عتبة، فذكراه.","grade":"صحيح","chapter_ar":"باب عدّة الحامل المطلقة والمتوفى عنها زوجها وضع الحمل","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2028).","chapter_en":"The waiting period of a pregnant divorced woman and a pregnant widow is until delivery","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Masruq and ʿAmr ibn ʿUtbah wrote to Subayʿah bint al-Harith asking her about her case. She wrote back to them that she had given birth twenty-five days after her husband’s death. Then she prepared herself seeking marriage. Abu al-Sanabil ibn Baʿkak passed by her and said: “You have hastened. Observe the later of the two terms: four months and ten days.” So I went to the Prophet ﷺ and said: “O Messenger of Allah, ask forgiveness for me.” He said: “And why is that?” So I informed him, and he said: “If you find a righteous husband, then marry.”"]},"buhuth":{"en":["His statement, “taʿallat”, means she rose up, meaning she became pure from postnatal bleeding. And “fatashawwafat” means she longed and hoped for marriage.","The ruling of a pregnant divorced woman is the same as that of a pregnant widow. Mourning follows the waiting period, so if a woman whose husband died is in the early months of pregnancy, then her mourning continues until delivery, even if that reaches nine months or more."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2028,"lafz":true}],"full":1,"dr":1},{"num":6658,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ وحفصة زَوْجِي النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، أَنْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ يحلُّ لاِمْرَأَةٍ تُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ أَنْ تُحِدَّ عَلَى ميتٍ فَوْقَ ثَلاَثٍ لَيَالٍ إِلاَّ عَلَى زَوْجٍ."],"takhrij":"صحيح: رواه مالك في الطلاق (104) عن نافع، عن صفية بنت أبي عبيد، عن عائشة وحفصة، فذكرتاه. ورواه مسلم في الطلاق (1490) من طريق الليث بن سعد، عن نافع، به، مثله.","grade":"صحيح","chapter_ar":"باب الإحداد ثلاثة أيام، إلا على الزوج فهي أربعة أشهر وعشراً","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (104) and Muslim (1490). In another narration there is the addition: “For she mourns him for four months and ten days.”","chapter_en":"Mourning is three days, except for a husband, in which case it is four months and ten days","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["ʿA’ishah and Hafsah, the two wives of the Prophet ﷺ, reported that the Messenger of Allah ﷺ said: “It is not lawful for a woman who believes in Allah and the Last Day to mourn for a deceased person for more than three nights, except for a husband.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":104,"lafz":true},{"key":"muslim","label":"مسلم","number":1490}],"full":1,"dr":1},{"num":6659,"demo":false,"sanad":"","matn":["عَنْ زَيْنَبَ ابْنَةِ أَبِي سَلَمَةَ، قَالَتْ لَمَّا جَاءَ نَعْىُ أَبِي سُفْيَانَ مِنَ الشَّأْمِ دَعَتْ أُمُّ حَبِيبَةَ رَضِيَ اللَّهُ عَنْهَا بِصُفْرَةٍ فِي الْيَوْمِ الثَّالِثِ، فَمَسَحَتْ عَارِضَيْهَا وَذِرَاعَيْهَا وَقَالَتْ إِنِّي كُنْتُ عَنْ هَذَا لَغَنِيَّةً، لَوْلاَ أَنِّي سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ لاَ يَحِلُّ لاِمْرَأَةٍ تُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ أَنْ تُحِدَّ عَلَى مَيِّتٍ فَوْقَ ثَلاَثٍ، إِلاَّ عَلَى زَوْجٍ، فَإِنَّهَا تُحِدُّ عَلَيْهِ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1280) ومسلم في الطلاق (1486) كلاهما من حديث سفيان، حدثنا أيوب بن موسى، قال: أخبرني حميد بن نافع، عن زينب ابنة أبي سلمة فذكرت مثله، ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب الإحداد ثلاثة أيام، إلا على الزوج فهي أربعة أشهر وعشراً","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1280) and Muslim (1486).","chapter_en":"Mourning is three days, except for a husband, in which case it is four months and ten days","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Zaynab, the daughter of Abū Salamah, reported: When news of Abū Sufyān’s death came from Syria, Umm Ḥabībah called for some yellow perfume on the third day. She applied it to her cheeks and forearms and said: “I had no need for this, were it not that I heard the Prophet ﷺ say: ‘It is not lawful for a woman who believes in Allah and the Last Day to mourn for a deceased person for more than three days, except for her husband, for whom she must mourn for four months and ten days.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1280,"lafz":true},{"key":"muslim","label":"مسلم","number":1486}],"full":1},{"num":6660,"demo":false,"sanad":"","matn":["عَنْ أُمِّ عَطِيَّةَ ـ قَالَتْ كُنَّا نُنْهَى أَنْ نُحِدَّ عَلَى مَيِّتٍ فَوْقَ ثَلاَثٍ، إِلاَّ عَلَى زَوْجٍ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا، وَلاَ نَكْتَحِلَ وَلاَ نَتَطَيَّبَ وَلاَ نَلْبَسَ ثَوْبًا مَصْبُوغًا إِلاَّ ثَوْبَ عَصْبٍ، وَقَدْ رُخِّصَ لَنَا عِنْدَ الطُّهْرِ إِذَا اغْتَسَلَتْ إِحْدَانَا مِنْ مَحِيضِهَا فِي نُبْذَةٍ مِنْ كُسْتِ أَظْفَارٍ، وَكُنَّا نُنْهَى عَنِ اتِّبَاعِ الْجَنَائِزِ.","وفي رواية: عن محمد بن سيرين قال: تُوفي ابن لأم عطية. فلما كان اليوم الثالث دعتْ بصفرةٍ فتمسحتْ به وقالت: نُهينا أن نُحِدّ أكثر من ثلاثٍ إلا بزوج."],"takhrij":"متفق عليه: رواه البـخاري في الحيـض (313) عن عـبد الله بن عبـد الوهاب، قال: حدثنا حماد بن زيد، عن أيوب، عن حفـصة.","grade":"متفق عليه","chapter_ar":"باب الإحداد ثلاثة أيام، إلا على الزوج فهي أربعة أشهر وعشراً","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (313) and Muslim (938). The second narration is in al-Bukhari (1279).","chapter_en":"Mourning is three days, except for a husband, in which case it is four months and ten days","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Umm ʿAtiyyah said: We were forbidden to mourn for a deceased person for more than three days, except for a husband: four months and ten days. We were not to apply kohl, use perfume, or wear dyed garments except a striped cloth. We were allowed, when one of us became pure and had washed after her menstruation, to use a small amount of costus and azfar. We were also forbidden from following funerals. And in another narration, Muhammad ibn Sirin said: A son of Umm ʿAtiyyah died. On the third day she called for yellow perfume, wiped herself with it, and said: “We were forbidden to mourn more than three days except for a husband.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":313,"lafz":true},{"key":"muslim","label":"مسلم","number":938},{"key":"bukhari","label":"الرواية الثانية عند البخاري","number":1279}],"full":1,"dr":1},{"num":6661,"demo":false,"sanad":"","matn":["عَنْ حُمَيْدِ بْنِ نَافِعٍ، عَنْ زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ، أَنَّهَا أَخْبَرَتْهُ هَذِهِ الأَحَادِيثَ الثَّلاَثَةَ.","قالت زينب: دخلتُ على أم حبيبة، زوج النبي صلى الله عليه وسلم حين توفي أبوها أبو سفيان بن حرب. فدعتْ أمُّ حبيبة بطيب فيه صفرةٌ خلوقٌ أو غيره. فدهنتْ به جاريةً. ثم مسحتْ بعارضَيْها. ثم قالت: والله، ما لي بالطيب من حاجةٍ، غير أني سمعت رسول الله صلى الله عليه وسلم يقول: لا يحل لامرأة تؤمن بالله واليوم الآخر أن تُحِدَّ على ميت فوق ثلاث ليال. إلا على زوج أربعة أشهرٍ وعشراً (هذا أولها)","قالت زينب: ثم دخلت على زينب بنت جحش، زوج النبي صلى الله عليه وسلم حين تُوُفّي أخوها، فدعتْ بطيب فمسّتْ منه. ثم قالت: والله ما لي بالطيب من حاجة غير أني سمعتُ رسول الله صلى الله عليه وسلم يقول: لا يحل لامرأة تُؤمن بالله واليوم الآخر أن تُحِدَّ على ميت فوق ثلاث ليال، إلا على زوج أربعة أشهر وعشراً (هذا ثانيها)"],"takhrij":"متفق عليه: رواه مالك في الطلاق (101-102) عن عبد الله بن أبي بكر ابن محمد بن عمرو بن حزم، عن حُميد بن نافع، به، فذكره.","grade":"متفق عليه","chapter_ar":"باب الإحداد ثلاثة أيام، إلا على الزوج فهي أربعة أشهر وعشراً","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (101–102), al-Bukhari (5334, 5335), and Muslim (1486–1489).","chapter_en":"Mourning is three days, except for a husband, in which case it is four months and ten days","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Humayd ibn Nafiʿ narrated from Zaynab bint Abi Salamah that she told him these three hadiths. Zaynab said: I entered upon Umm Habibah, the wife of the Prophet ﷺ, when her father Abu Sufyan ibn Harb had died. Umm Habibah called for perfume containing yellow khaluq or something else. She applied it to a servant girl, then wiped some on her own cheeks. Then she said: “By Allah, I have no need for perfume, except that I heard the Messenger of Allah ﷺ say: ‘It is not lawful for a woman who believes in Allah and the Last Day to mourn for a deceased person for more than three nights, except for a husband: four months and ten days.’” (This is the first of them.)","Zaynab said: Then I entered upon Zaynab bint Jahsh, the wife of the Prophet ﷺ, when her brother died. She called for perfume and touched some of it. Then she said: “By Allah, I have no need for perfume, except that I heard the Messenger of Allah ﷺ say: ‘It is not lawful for a woman who believes in Allah and the Last Day to mourn for a deceased person for more than three nights, except for a husband: four months and ten days.’” (This is the second of them.)"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":102,"lafz":true},{"key":"bukhari","label":"البخاري","number":5334},{"key":"muslim","label":"مسلم","number":1489},{"key":"malik","label":"مالك في الطلاق","number":101}],"full":1,"dr":1},{"num":6662,"demo":false,"sanad":"","matn":["عَنْ زَيْنَبَ قَالَتْ: سَمِعْتُ أُمِّي أُمَّ سَلَمَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَقُولُ: جَاءَتِ امْرَأَةٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ. إِنَّ ابْنَتِي تُوفّي عَنْهَا زَوْجُهَا. وَقَدِ اشْتَكَتْ عينَيْها. أفتَكْحَلُهما؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : لاَ مَرَّتَيْنِ أَوْ ثَلاَثًا. كُلَّ ذَلِكَ يَقُولُ: لاَ ثُمَّ قَالَ: إِنَّمَا هِيَ أَرْبَعَةُ أَشْهُرٍ وَعَشْرًا. وَقَدْ كَانَتْ إِحْدَاكُنَّ فِي الْجَاهِلِيَّةِ تَرْمِي بِالْبَعَرَةِ عَلَى رَأْسِ الْحَوْلِ.","قال حميد: فقلت لزينب: وما ترمي البعرة على رأس الحول؟ فقالت زينب: كانت المرأة إذا توفي عنها زوجُها. دخلت حِفْشاً ولبستْ شر ثيابها. ولم تمس طيباً ولا شيئاً حتى تمر بها سنة، ثم تؤتى بدابةٍ، حمارٍ أو شاةٍ أو طيرٍ، فتفتضُّ به، فقلما تفتضُّ بشيء إلا مات، ثم تخرج، فتُعـطى بعـرة فترمي بها، ثم تُراجـع بعـد ما شاءت من طيبٍ أو غيره. (وهذا ثالثُها)"],"takhrij":"متفق عليه: رواه مالك في الطلاق (103) عن عبد الله بن أبي بكر بن محمد بن عمرو بن حزم، عن حميد بن نافع، عن زينب بنت أبي سلمة تقول: فذكرته. ورواه البخاري في الطلاق (5336) ومسلم في الطلاق (1488) كلاهما من حديث مالك به.","grade":"متفق عليه","chapter_ar":"باب النهي عن الاكتحال في الإحداد","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (103), al-Bukhari (5336), and Muslim (1488).","chapter_en":"The prohibition of using kohl during mourning","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Zaynab said: I heard my mother, Umm Salamah, the wife of the Prophet ﷺ, say: A woman came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, my daughter’s husband has died, and her eyes are hurting. May she apply kohl to them?” The Messenger of Allah ﷺ said: “No,” two or three times, each time saying: “No.” Then he said: “It is only four months and ten days, whereas in the pre-Islamic period one of you used to throw dung at the end of a year.” Humayd said: I said to Zaynab: “What does ‘throwing dung at the end of the year’ mean?” Zaynab said: When a woman’s husband died, she would enter a shabby shelter and wear her worst clothes. She would not touch perfume or anything else until a year had passed. Then an animal would be brought to her—a donkey, a sheep, or a bird—and she would rub herself with it, and whatever she rubbed herself with would hardly survive. Then she would come out and be given a piece of dung which she would throw away. After that, she could return to using whatever perfume or other things she wished. (This is the third of them.)"]},"buhuth":{"en":["Malik said: al-hifsh means a poor-quality house, and taftaddu—with a doubled dad—means she would rub her skin with it like a cleansing rite. That is, she would take a bird, wipe her private area with it, and cast it away, and it would hardly survive after that, as stated in al-Nihayah."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":103,"lafz":true},{"key":"bukhari","label":"البخاري","number":5336},{"key":"muslim","label":"مسلم","number":1488,"n":3728}],"full":1,"dr":1},{"num":6663,"demo":false,"sanad":"","matn":["عن أُمِّ سَلَمَةَ عَنْ أُمِّهَا، أَنَّ امْرَأَةً، تُوُفِّيَ زَوْجُهَا فَخَشُوا عَلَى عَيْنَيْهَا فَأَتَوْا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاسْتَأْذَنُوهُ فِي الْكُحْلِ فَقَالَ لاَ تَكَحَّلْ قَدْ كَانَتْ إِحْدَاكُنَّ تَمْكُثُ فِي شَرِّ أَحْلاَسِهَا أَوْ شَرِّ بَيْتِهَا، فَإِذَا كَانَ حَوْلٌ فَمَرَّ كَلْبٌ رَمَتْ بِبَعَرَةٍ، فَلاَ حَتَّى تَمْضِيَ أَرْبَعَةُ أَشْهُرٍ وَعَشْرٌ."],"takhrij":"متفق عليه: رواه البخاري في الطلاق (5338) ومسلم في الطلاق (60:1488) كلاهما من حديث شعبة، عن حميد بن نافع، قال: سمعت زينب بنت أم سلمة، تحدث عن أمها أم سلمة فذكرته.","grade":"متفق عليه","chapter_ar":"باب النهي عن الاكتحال في الإحداد","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5338) and Muslim (60:1488).","chapter_en":"The prohibition of using kohl during mourning","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Umm Salamah reported that a woman’s husband died, and they became concerned about her eyes, so they came to the Messenger of Allah and asked his permission for her to use kohl. He said: “She must not apply kohl. In the pre-Islamic period one of you would remain in her worst clothes, or in the worst part of her house, and when a year passed and a dog went by, she would throw dung. No, not until four months and ten days have passed.”"]},"buhuth":{"en":["Her statement: “the worst of her coverings” means her worst garments. The word refers to the cloth placed on a camel’s back."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5338,"lafz":true},{"key":"muslim","label":"مسلم","number":60}],"full":1,"dr":1},{"num":6664,"demo":false,"sanad":"","matn":["عَنْ أُمِّ عَطِيَّةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ تُحِدُّ المرأة عَلَى مَيِّتٍ فَوْقَ ثَلاَثٍ، إِلاَّ عَلَى زَوْجٍ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا، وَلاَ تَلْبَسُ ثَوْبًا مَصْبُوغًا إِلاَّ ثَوْبَ عَصْبٍ، وَلاَ تَكْتَحِل، وَلاَ تَمَسُّ طِيبًا، إِلاَّ عِنْدَ طهرها حِينَ تطهر: نُبْذَةً مِنْ قُسْطٍ وأظفار."],"takhrij":"متفق عليه: رواه البخاري في الحيض (313) ومسلم في الطلاق (938) كلاهما من حديث هشان بن حسان، عن حفصة، عن أم عطية فذكرته.","grade":"متفق عليه","chapter_ar":"باب اجتناب الحادة من الثياب المصبغة","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (313) and Muslim (938).","chapter_en":"The mourning woman must avoid dyed clothing","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Umm ʿAtiyyah reported that the Messenger of Allah ﷺ said: “A woman must not mourn for a deceased person for more than three days, except for a husband: four months and ten days. She must not wear dyed clothing except striped Yemeni cloth, must not apply kohl, and must not touch perfume, except when she becomes pure after menstruation, when she may use a small amount of costus and aromatic nail-like incense.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":313,"lafz":true},{"key":"muslim","label":"مسلم","number":938,"n":3740}],"full":1},{"num":6665,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ، زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ الْمُتَوَفَّى عَنْهَا زَوْجُهَا لاَ تَلْبَسُ الْمُعَصْفَرَ مِنَ الثِّيَابِ وَلاَ الْمُمَشَّقَةَ وَلاَ الْحُلِيَّ وَلاَ تَخْتَضِبُ وَلاَ تَكْتَحِلُ."],"takhrij":"صحيح: رواه أبو داود (2304) والنسائي (3535) وأحمد (26581) وصحّحه ابن حبان (4306) كلهم من حديث يحيى بن أبي بكير، حدثنا إبراهيم بن طهمان، قال: حدثني بُديل، عن الحسن بن مسلم، عن صفية بنت شيبة، عن أم سلمة فذكرته.","grade":"صحيح","chapter_ar":"باب اجتناب الحادة من الثياب المصبغة","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2304), al-Nasa’i (3535), Ahmad (26581), and authenticated by Ibn Hibban (4306).","chapter_en":"The mourning woman must avoid dyed clothing","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet, reported that the Prophet ﷺ said: “A woman whose husband has died must not wear safflower-dyed clothing, nor yellow-dyed clothing, nor jewelry, nor apply henna, nor use kohl.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2304,"lafz":true},{"key":"nasai","label":"النسائي","number":3535,"n":3535},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":4306},{"key":"ahmad","label":"مسند الإمام أحمد","number":26581,"n":26581},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2093,"n":2090}],"full":1,"dr":1},{"num":6666,"demo":false,"sanad":"","matn":["عَنْ زَيْنَبَ بنت كعب بن عُجْرة، أَنَّ الْفُرَيْعَةَ بِنْتَ مَالِكِ بْنِ سِنَانٍ، وَهِيَ أُخْتُ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَخْبَرَتْهَا، أَنَّهَا جَاءَتْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَسْأَلُهُ أَنْ تَرْجِعَ إِلَى أَهْلِهَا فِي بَنِي خُدْرَةَ، وأن زَوْجَهَا خَرَجَ فِي طَلَبِ أَعْبُدٍ لَهُ أَبَقُوا، حَتَّى إِذَا كَانَ بِطَرَفِ الْقَدُّومِ لَحِقهم فَقَتَلُوهُ. قَالَتْ: فَسَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ أَرْجِعَ إِلَى أَهْلِي، فَإِنَّ زَوْجِي لَمْ يَتْرُكْ لِي مسكنا يَمْلِكُهُ، وَلاَ نَفَقَةٍ. قَالَتْ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : نَعَمْ قَالَتْ: فانصرفت، حَتَّى إِذَا كنتُ فِي الْحُجْرَةِ أَوْ فِي الْمَسْجِدِ ناداني رسولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، أَوْ أَمَرَ بِي فنوديتُ لَهُ، فَقَالَ: كَيْفَ قُلْتِ؟ قَالَتْ: فَرَدَدْتُ عَلَيْهِ الْقِصَّةَ الَّتِي ذَكَرْتُ لَهُ مِنْ شَأْنِ زَوْجِي. قَالَ: امْكُثِي فِي بَيْتِكِ حَتَّى يَبْلُغَ الْكِتَابُ أَجَلَهُ قَالَتْ: فَاعْتَدَدْتُ فِيهِ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا. قَالَتْ: فَلَمَّا كَانَ عُثْمَانُ، أَرْسَلَ إليَّ فَسَأَلَنِي عَنْ ذَلِكَ فَأَخْبَرْتُهُ، فَاتَّبَعَهُ وَقَضَى بِهِ."],"takhrij":"صحيح: رواه مالك في الطلاق (96) عن سعد بن إسحاق بن كعب بن عُجرة، عن عمته زينب بنت كعب بن عُجرة فأخبرته، أن الفُريعة بنت مالك أخبرتها أنها جاءت إلى النبي صلى الله عليه وسلم فذكرته.","grade":"صحيح","chapter_ar":"باب اعتداد المتوفّى عنها زوجها في البيت الذي جاء فيه نعيُه","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (96), Abu Dawud (2300), al-Tirmidhi (1204), Ibn Majah (2031), and al-Nasa’i (3528).","chapter_en":"A widow observes her waiting period in the house where the news of her husband’s death reached her","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Zaynab bint Kaʿb ibn ʿUjrah reported that al-Furayʿah bint Malik ibn Sinan, the sister of Abu Saʿid al-Khudri, told her that she came to the Messenger of Allah ﷺ asking permission to return to her family among Banu Khudrah, because her husband had gone out seeking some runaway servants of his, and when he reached the edge of al-Qadum they caught up with him and killed him. She said: “I asked the Messenger of Allah ﷺ if I could return to my family, for my husband had not left me a house he owned nor any maintenance.” The Messenger of Allah ﷺ said: “Yes.” She said: “So I turned away, until when I was in the courtyard or in the mosque, the Messenger of Allah ﷺ called me back, or ordered that I be called, and he said: ‘What did you say?’ I repeated to him the story I had mentioned about my husband. He said: ‘Remain in your house until the prescribed term reaches its end.’ So I observed my waiting period there for four months and ten days.” She said: Then during the caliphate of ʿUthman, he sent for me and asked me about that, so I informed him, and he followed it and ruled by it."]},"buhuth":{"en":["Legal note: A woman observes her waiting period in her husband’s house, and her family may not remove her from it. But if she leaves for a need or necessity, such as fearing for her safety, or if the house is rented, or due to other necessary excuses, then she may leave and move from her husband’s house. Allah the Exalted said: “Then there is no blame upon you for what they do concerning themselves in an appropriate manner.” In such a case, her family may not prevent her."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":96,"lafz":true},{"key":"abudawud","label":"أبو داود","number":2300},{"key":"tirmidhi","label":"الترمذي","number":1204},{"key":"ibnmajah","label":"ابن ماجه","number":2031}],"full":1,"dr":1},{"num":6667,"demo":false,"sanad":"","matn":["عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ، أَنَّ أَبَا عَمْرِو بْنَ حَفْصٍ، طَلَّقَهَا الْبَتَّةَ وَهُوَ غَائِبٌ فَأَرْسَلَ إِلَيْهَا وَكِيلُهُ بِشَعِيرٍ فَسَخِطَتْهُ فَقَالَ وَاللَّهِ مَا لَكِ عَلَيْنَا مِنْ شَىْءٍ. فَجَاءَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَتْ ذَلِكَ لَهُ فَقَالَ لَيْسَ لَكِ عَلَيْهِ نَفَقَةٌ. فَأَمَرَهَا أَنْ تَعْتَدَّ فِي بَيْتِ أُمِّ شَرِيكٍ ثُمَّ قَالَ تِلْكَ امْرَأَةٌ يَغْشَاهَا أَصْحَابِي اعْتَدِّي عِنْدَ ابْنِ أُمِّ مَكْتُومٍ فَإِنَّهُ رَجُلٌ أَعْمَى تَضَعِينَ ثِيَابَكِ فَإِذَا حَلَلْتِ فَآذِنِينِي. قَالَتْ فَلَمَّا حَلَلْتُ ذَكَرْتُ لَهُ أَنَّ مُعَاوِيَةَ بْنَ أَبِي سُفْيَانَ وَأَبَا جَهْمٍ خَطَبَانِي. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَّا أَبُو جَهْمٍ فَلاَ يَضَعُ عَصَاهُ عَنْ عَاتَقِهِ وَأَمَّا مُعَاوِيَةُ فَصُعْلُوكٌ لاَ مَالَ لَهُ انْكِحِي أُسَامَةَ بْنَ زَيْدٍ. فَكَرِهْتُهُ ثُمَّ قَالَ انْكِحِي أُسَامَةَ. فَنَكَحْتُهُ فَجَعَلَ اللَّهُ فِيهِ خَيْرًا وَاغْتَبَطْتُ بِهِ."],"takhrij":"صحيح: رواه مالك في الطلاق (67) عن عبد الله بن يزيد مولى الأسود ابن سفيان، عن أبي سلمة بن عبد الرحمن بن عوف، عن فاطمةَ بنت قيس، فذكرتْه. ورواه مسلم في الطلاق (36:1480) من طريق مالك، به، مثله.","grade":"صحيح","chapter_ar":"باب قصة فاطمة بنت قيس: لا نفقة لها ولا سكنى","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (67) and Muslim (36:1480). Muslim also narrated it through another route with the wording: “You have no maintenance and no housing.” And through another route: “She has no maintenance, but she must observe the waiting period.” His statement regarding Abu Jahm, “he does not put down his staff from his shoulder,” is a metaphor for his harshness toward women and his beating them, as is explicitly stated in some narrations.","chapter_en":"The story of Fatimah bint Qays: she has no maintenance and no housing","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Fatimah bint Qays reported that Abu ʿAmr ibn Hafs gave her an irrevocable divorce while he was absent in Syria, and he sent his agent to her with barley. She was displeased with it. The agent said: “By Allah, you have no right against us to anything.” So she came to the Messenger of Allah ﷺ and mentioned that to him. He said: “You have no maintenance from him.” He ordered her to observe her waiting period in the house of Umm Sharik, then said: “That is a woman frequently visited by my companions. Observe your waiting period with ʿAbdullah ibn Umm Maktum, for he is a blind man, and you may place your garments there. When you become lawful, inform me.” She said: “When I became lawful, I informed him that Muʿawiyah ibn Abi Sufyan and Abu Jahm ibn Hisham had proposed to me.” The Messenger of Allah ﷺ said: “As for Abu Jahm, he never puts down his staff from his shoulder. As for Muʿawiyah, he is poor and has no wealth. Marry Usamah ibn Zayd.” She said: “I disliked him.” Then he said: “Marry Usamah ibn Zayd.” So I married him, and Allah placed much good in that for me, and I was pleased with it."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":67,"lafz":true},{"key":"muslim","label":"مسلم","number":36},{"key":"muslim","label":". رواه مسلم","number":37}],"full":1,"dr":1},{"num":6668,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرِ بْنِ أَبِي الْجَهْمِ قَالَ: سَمِعْتُ فَاطِمَةَ بِنْتَ قَيْسٍ تَقُولُ: أَرْسَلَ إليَّ زَوْجِي أَبُو عَمْرِو بْنُ حَفْصِ بْنِ الْمُغِيرَةِ بن عَيَّاشَ بْنَ أَبِي رَبِيعَةَ بِطَلاَقِي، وَأَرْسَلَ إليّ بخمس آصُعِ تَمْرٍ، وخمسِ آصُعِ شَعِيرٍ. فَقُلْتُ: مَا لِي نَفَقَةٌ إِلاَّ هَذَا؟ وَلاَ أَعْتَدُّ فِي بيتكم؟ قَالَ: لاَ. فَشَدَدْتُ عليّ ثِيَابِي، ثُمَّ أَتَيْتُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فذكرتُ لَهُ ذَلِكَ، فَقَالَ: كَمْ طلَّقَكِ؟ قُلْتُ: ثَلاَثًا، قَالَ: صَدَقَ، لَيْسَ لكِ نَفَقَةٌ، واعتدِّي فِي بَيْتِ ابْنِ عَمِّكِ ابْنِ أُمِّ مَكْتُومٍ، فَإِنَّهُ ضَرِيرُ الْبَصَرِ، تلقين ثيابكِ عنكِ، فَإِذَا انْقَضَتْ عدّتُكِ فَآذِنِينِي قَالَتْ: فَخَطَبَنِي خُطّابٌ، فيهم مُعَاوِيَةُ وأبوجهم، فَقَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنَّ مُعَاوِيَةَ تَرِبٌ خَفِيفُ الْحَالِ، وأبوجهم يَضْرِبُ النساء – أي – فِيهِ شِدَّةٌ عَلَى النِّسَاءِ – وَلَكِنْ عَلَيْكِ أسامةَ بْنِ زَيْدٍ. أَوْ قَالَ: انكحيْ أُسَامَةَ بن زَيْدٍ."],"takhrij":"صحيح: رواه مسلم في الطلاق (48:1480)، عن إسحاق بن منصور، حدثنا عبد الرحمن، عن سفيان، عن أبي بكر بن أبي الجهم فذكره.","grade":"صحيح","chapter_ar":"باب قصة فاطمة بنت قيس: لا نفقة لها ولا سكنى","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (48:1480).","chapter_en":"The story of Fatimah bint Qays: she has no maintenance and no housing","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu Bakr ibn Abi al-Jahm said: I heard Fatimah bint Qays say: My husband Abu ʿAmr ibn Hafs ibn al-Mughirah ibn ʿAyyash ibn Abi Rabiʿah sent me my divorce, and he sent me five measures of dates and five measures of barley. I said: “Do I have no maintenance except this? And am I not to observe my waiting period in your house?” He said: “No.” So I wrapped my clothes around me, then I came to the Prophet ﷺ and mentioned that to him. He said: “How many times did he divorce you?” I said: “Three.” He said: “He has spoken the truth. You have no maintenance. Observe your waiting period in the house of your cousin Ibn Umm Maktum, for he is blind, and you may remove your garments there. When your waiting period ends, inform me.” She said: Then suitors proposed to me, among them Muʿawiyah and Abu Jahm, so the Messenger of Allah ﷺ said: “Muʿawiyah is poor and in straitened means, and Abu Jahm beats women—that is, he is harsh with women—but you should marry Usamah ibn Zayd.” Or he said: “Marry Usamah ibn Zayd.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":48,"lafz":true}],"full":1,"dr":1},{"num":6669,"demo":false,"sanad":"","matn":["عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ، قَالَتْ طَلَّقَنِي زَوْجِي ثَلاَثًا فَلَمْ يَجْعَلْ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُكْنَى وَلاَ نَفَقَةً."],"takhrij":"صحيح: رواه مسلم في الطلاق (51:1480) عن حسن بن علي الحُلواني، حدثنا يحيى بن آدم، حدثنا حسن بن صالح، عن السدي، عن البهي، عن فاطمة بنت قيس فذكرته.","grade":"صحيح","chapter_ar":"باب قصة فاطمة بنت قيس: لا نفقة لها ولا سكنى","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (51:1480).","chapter_en":"The story of Fatimah bint Qays: she has no maintenance and no housing","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Fatimah bint Qays said: My husband divorced me three times, and the Messenger of Allah ﷺ did not assign for me any housing or maintenance."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":51,"lafz":true}],"full":1},{"num":6670,"demo":false,"sanad":"","matn":["عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْمُطَلَّقَةِ ثَلاَثًا قَالَ لَيْسَ لَهَا سُكْنَى وَلاَ نَفَقَةٌ."],"takhrij":"صحيح: رواه مسلم في الطلاق (44:1480) من طرق عن عبد الرحمن بن مهدي، حدثنا سفيان، عن سلمة بن كهيل، عن الشعبي، عن فاطمة بنت قيس فذكرته.","grade":"صحيح","chapter_ar":"باب قصة فاطمة بنت قيس: لا نفقة لها ولا سكنى","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (44:1480).","chapter_en":"The story of Fatimah bint Qays: she has no maintenance and no housing","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Fatimah bint Qays reported from the Prophet ﷺ concerning a woman divorced three times: “She has no housing and no maintenance.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":44,"lafz":true}],"full":1,"dr":1},{"num":6671,"demo":false,"sanad":"","matn":["عَنْ عُرْوَةَ قَالَ: تَزَوَّجَ يَحْيَى بْنُ سَعِيدِ بْنِ الْعَاصِ بنتَ عبدالرحمن بْنِ الْحَكَمِ، فَطَلَّقَهَا، فَأَخْرَجَهَا مِنْ عِنْدِهِ، فَعَابَ ذَلِكَ عَلَيْهِمْ عُرْوَةُ. فَقَالُوا: إِنَّ فَاطِمَةَ قَدْ خَرَجَتْ. قَالَ عُرْوَةُ: فَأَتَيْتُ عَائِشَةَ فَأَخْبَرْتُهَا بِذَلِكَ، فَقَالَتْ: مَا لِفَاطِمَةَ بِنْتِ قَيْسٍ خَيْرٌ فِي أَنْ تَذْكُرَ هَذَا الْحَدِيثَ."],"takhrij":"متفق عليه: رواه مسلم في الطلاق (52:1481)، عن أبي كُريب، حدثنا أبو أسامة، عن هشام، حدثني أبي قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب من أنكر على فاطمة بنت قيس وقال: إن المبتوتة لها النفقةُ والسُّكنى","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (52:1481) and al-Bukhari (5324, 5326).","chapter_en":"Those who objected to the report of Fatimah bint Qays and said that a woman with an irrevocable divorce is entitled to maintenance and housing","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["ʿUrwah said: Yahya ibn Saʿid ibn al-ʿAs married the daughter of ʿAbd al-Rahman ibn al-Hakam, then divorced her, and he turned her out from his place. ʿUrwah criticized them for that. They said: “Fatimah had gone out.” ʿUrwah said: So I went to ʿA’ishah and told her about that, and she said: “There is no good for Fatimah bint Qays in mentioning this hadith.”"]},"buhuth":{"en":["Regarding the verse, “unless they commit a clear indecency,” Ibn ʿAbbas said: It means that she speaks offensively to her household, and if she does so, then it becomes lawful for them to remove her. This was mentioned by al-Bayhaqi (7/431)."]},"intro":{"ar":["قال الله تعالى: (أَسْكِنُوهُنَّ مِنْ حَيْثُ سَكَنْتُمْ مِنْ وُجْدِكُمْ وَلَا تُضَارُّوهُنَّ لِتُضَيِّقُوا عَلَيْهِنَّ) [الطلاق: ٦]"],"en":["Allah the Exalted said: “Lodge them [during their waiting period] where you dwell, according to your means, and do not harm them in order to oppress them.” [al-Talaq: 6]"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":52,"lafz":true},{"key":"bukhari","label":"البخاري","number":5324}],"full":1,"dr":1},{"num":6672,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّهَا قَالَتْ مَا لِفَاطِمَةَ أَلاَ تَتَّقِي اللَّهَ، يَعْنِي فِي قَوْلِهَا لاَ سُكْنَى وَلاَ نَفَقَةَ."],"takhrij":"متفق عليه: رواه البخاري في الطلاق (5323) ومسلم في الطلاق (54:1481) كلاهما من حديث شعبة، عن عبد الرحمن بن القاسم، عن أبيه، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب من أنكر على فاطمة بنت قيس وقال: إن المبتوتة لها النفقةُ والسُّكنى","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5323) and Muslim (54:1481).","chapter_en":"Those who objected to the report of Fatimah bint Qays and said that a woman with an irrevocable divorce is entitled to maintenance and housing","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["ʿA’ishah said: “What is the matter with Fatimah—does she not fear Allah?” meaning in her statement: “There is no housing and no maintenance.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5323,"lafz":true},{"key":"muslim","label":"مسلم","number":54}],"full":1},{"num":6673,"demo":false,"sanad":"","matn":["عَنِ الْقَاسِمِ بْنِ مُحَمَّدٍ، وسليمان بن يَسَارٍ، أَنَّهُ سَمِعَهما يذكُران، أَنَّ يَحْيَى بْنَ سَعِيدِ بْنِ الْعَاصِ طلّق ابنة عَبْدِ الرَّحْمَنِ بْنِ الْحَكَمِ البتة. فَانْتَقَلَهَا عَبْدُ الرَّحْمَنِ بن الْحَكَمِ. فَأَرْسَلَتْ عَائِشَةُ أُمُّ الْمُؤْمِنِينَ إِلَى مَرْوَانَ بن الْحَكَمِ- وَهْوَ يَوْمَئِذٍ أَمِيرُ الْمَدِينَةِ- فقالت: اتقِ اللَّهَ واردد المرأة إِلَى بَيْتِهَا. فَقَالَ مَرْوَانُ -فِي حَدِيثِ سُلَيْمَانَ-: إِنَّ عَبْدَ الرَّحْمَنِ غَلَبَنِي. وَقَالَ مروان -فِي حَدِيثِ الْقَاسِمُ-: أَوْ مَا بَلَغَكِ شَأْنُ فَاطِمَةَ بِنْتِ قَيْسٍ؟ فقالت عَائِشَةُ: لاَ يَضُرُّكَ أَنْ لاَ تَذْكُرَ حَدِيثَ فَاطِمَةَ. فَقَالَ مَرْوَانُ: إِنْ كَانَ بِكِ الشرُّ فَحَسْبُكِ مَا بَيْنَ هَذَيْنِ مِنَ الشَّرِّ."],"takhrij":"صحيح: رواه مالك في الطلاق (36) عن يحيى بن سعيد، عن القاسم بن محمد به، فذكره. ورواه البخاري في الطلاق (5322،5321) من طريق مالك، به، مثله.","grade":"صحيح","chapter_ar":"باب من أنكر على فاطمة بنت قيس وقال: إن المبتوتة لها النفقةُ والسُّكنى","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (36) and al-Bukhari (5321, 5322).","chapter_en":"Those who objected to the report of Fatimah bint Qays and said that a woman with an irrevocable divorce is entitled to maintenance and housing","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Al-Qasim ibn Muhammad and Sulayman ibn Yasar reported that they heard that Yahya ibn Saʿid ibn al-ʿAs divorced the daughter of ʿAbd al-Rahman ibn al-Hakam with an irrevocable divorce. Then ʿAbd al-Rahman ibn al-Hakam moved her away. So ʿA’ishah, the Mother of the Believers, sent to Marwan ibn al-Hakam, who was then the governor of Madinah, saying: “Fear Allah and return the woman to her house.” Marwan said, in Sulayman’s narration: “ʿAbd al-Rahman overpowered me.” And Marwan said in al-Qasim’s narration: “Has the matter of Fatimah bint Qays not reached you?” ʿA’ishah said: “It will not harm you not to mention the hadith of Fatimah.” Marwan said: “If you mean that Fatimah moved because of the harm involved, then the harm between these two is sufficient justification.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":36,"lafz":true},{"key":"bukhari","label":"البخاري","number":5321},{"key":"bukhari","label":"البخاري في الطلاق","number":5322}],"full":1,"dr":1},{"num":6674,"demo":false,"sanad":"","matn":["عَنْ أَبِي إِسْحَاقَ، قَالَ كُنْتُ مَعَ الأَسْوَدِ بْنِ يَزِيدَ جَالِسًا فِي الْمَسْجِدِ الأَعْظَمِ وَمَعَنَا الشَّعْبِيُّ فَحَدَّثَ الشَّعْبِيُّ بِحَدِيثِ فَاطِمَةَ بِنْتِ قَيْسٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَجْعَلْ لَهَا سُكْنَى وَلاَ نَفَقَةً ثُمَّ أَخَذَ الأَسْوَدُ كَفًّا مِنْ حَصًى فَحَصَبَهُ بِهِ. فَقَالَ وَيْلَكَ تُحَدِّثُ بِمِثْلِ هَذَا قَالَ عُمَرُ لاَ نَتْرُكُ كِتَابَ اللَّهِ وَسُنَّةَ نَبِيِّنَا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِقَوْلِ امْرَأَةٍ لاَ نَدْرِي لَعَلَّهَا حَفِظَتْ أَوْ نَسِيَتْ لَهَا السُّكْنَى وَالنَّفَقَةُ قَالَ اللَّهُ عَزَّ وَجَلَّ ﴿لاَ تُخْرِجُوهُنَّ مِنْ بُيُوتِهِنَّ وَلاَ يَخْرُجْنَ إِلاَّ أَنْ يَأْتِينَ بِفَاحِشَةٍ مُبَيِّنَةٍ﴾ [سورة الطلاق: 1]}"],"takhrij":"صحيح: رواه مسلم (46:1480) عن محمد بن عمرو بن جبلة، حدثنا أبو أحمد، حدثنا عمار بن رُزَيق، عن أبي إسحاق، به، فذكره.","grade":"صحيح","chapter_ar":"باب من أنكر على فاطمة بنت قيس وقال: إن المبتوتة لها النفقةُ والسُّكنى","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (46:1480).","chapter_en":"Those who objected to the report of Fatimah bint Qays and said that a woman with an irrevocable divorce is entitled to maintenance and housing","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abu Ishaq said: I was sitting with al-Aswad ibn Yazid in the main mosque, and al-Shaʿbi was with us. Al-Shaʿbi narrated the hadith of Fatimah bint Qays, that the Messenger of Allah ﷺ did not assign for her housing or maintenance. Then al-Aswad took a handful of pebbles and threw them at him and said: “Woe to you! You narrate something like this?” ʿUmar said: “We do not leave the Book of Allah and the Sunnah of our Prophet ﷺ because of the statement of a woman when we do not know whether she remembered correctly or forgot. She has housing and maintenance.” Allah the Exalted said: “Do not turn them out of their houses, nor should they leave, unless they commit a clear indecency.” [Surat al-Talaq: 1]"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":46,"lafz":true}],"full":1,"dr":1},{"num":6675,"demo":false,"sanad":"","matn":["عَنِ الشَّعْبِيِّ، عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ، قَالَتْ طَلَّقَنِي زَوْجِي فَأَرَدْتُ النُّقْلَةَ فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ انْتَقِلِي إِلَى بَيْتِ ابْنِ عَمِّكِ عَمْرِو ابْنِ أُمِّ مَكْتُومٍ فَاعْتَدِّي فِيهِ. فَحَصَبَهُ الأَسْوَدُ وَقَالَ وَيْلَكَ لِمَ تُفْتِي بِمِثْلِ هَذَا. قَالَ عُمَرُ إِنْ جِئْتِ بِشَاهِدَيْنِ يَشْهَدَانِ أَنَّهُمَا سَمِعَاهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَإِلاَّ لَمْ نَتْرُكْ كِتَابَ اللَّهِ لِقَوْلِ امْرَأَةٍ { لاَ تُخْرِجُوهُنَّ مِنْ بُيُوتِهِنَّ وَلاَ يَخْرُجْنَ إِلاَّ أَنْ يَأْتِينَ بِفَاحِشَةٍ مُبَيِّنَةٍ }."],"takhrij":"صحيح: رواه النسائي (3549) والدارقطني ومن طريقه البيهقي (7/431) كلهم من حديث عمار بن رُزيق، عن أبي إسحاق، عن الشعبي فذكره.","grade":"صحيح","chapter_ar":"باب من أنكر على فاطمة بنت قيس وقال: إن المبتوتة لها النفقةُ والسُّكنى","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (3549), al-Dāraquṭnī, and through him al-Bayhaqī (7/431).","chapter_en":"Those who objected to the report of Fatimah bint Qays and said that a woman with an irrevocable divorce is entitled to maintenance and housing","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Al-Shaʿbī reported from Fāṭimah bint Qays that she said: “My husband divorced me, and I wanted to move. So I came to the Messenger of Allah ﷺ, and he said: ‘Move to the house of your cousin ʿAmr ibn Umm Maktūm and observe your waiting period there.’” Al-Aswad threw pebbles at him and said: “Woe to you! Why do you give a ruling like this?” ʿUmar said: “If you bring two witnesses who testify that they heard this from the Messenger of Allah ﷺ, then we will accept it. Otherwise, we will not abandon the Book of Allah because of the statement of one woman: ‘Do not turn them out of their houses, nor should they leave, unless they commit a clear indecency.’” [al-Ṭalāq: 1]"]},"buhuth":{"en":["ʿUmar ibn al-Khaṭṭāb’s objection to the report of Fāṭimah bint Qays was based on his caution in accepting reports of the Prophetic Sunnah, which is why he sought supporting witnesses; it was not because he rejected the Sunnah. Some scholars also held that this statement from him was not authentically established, as Abū Dāwūd transmitted from Imām Aḥmad in Masāʾil Aḥmad (p. 184)."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3549,"lafz":true,"n":3549},{"key":"kubrabayhaqi","label":"ومن طريقه البيهقي","number":7}],"full":1,"dr":1},{"num":6676,"demo":false,"sanad":"","matn":["عَنْ عُبَيْدِ اللَّهِ بْنِ عُتْبَةَ، أَنَّ أَبَا عَمْرِو بْنَ حَفْصِ بْنِ الْمُغِيرَةِ، خَرَجَ مَعَ عَلِيِّ بْنِ أَبِي طَالِبٍ إِلَى الْيَمَنِ فَأَرْسَلَ إِلَى امْرَأَتِهِ فَاطِمَةَ بِنْتِ قَيْسٍ بِتَطْلِيقَةٍ كَانَتْ بَقِيَتْ مِنْ طَلاَقِهَا وَأَمَرَ لَهَا الْحَارِثَ بْنَ هِشَامٍ وَعَيَّاشَ بْنَ أَبِي رَبِيعَةَ بِنَفَقَةٍ فَقَالاَ لَهَا وَاللَّهِ مَا لَكِ نَفَقَةٌ إِلاَّ أَنْ تَكُونِي حَامِلاً. فَأَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَتْ لَهُ قَوْلَهُمَا. فَقَالَ لاَ نَفَقَةَ لَكِ. فَاسْتَأْذَنَتْهُ فِي الاِنْتِقَالِ فَأَذِنَ لَهَا."],"takhrij":"صحيح: رواه مسلم في الطلاق (41:1480) من طرق عن عبدالرزاق، أخبرنا معمر، عن الزهري، عن عبيد الله بن عبد الله بن عتبة فذكره.","grade":"صحيح","chapter_ar":"باب من أنكر على فاطمة بنت قيس وقال: إن المبتوتة لها النفقةُ والسُّكنى","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (41:1480).","chapter_en":"Those who objected to the report of Fatimah bint Qays and said that a woman with an irrevocable divorce is entitled to maintenance and housing","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["ʿUbaydullah ibn ʿAbdullah ibn ʿUtbah reported that Abu ʿAmr ibn Hafs ibn al-Mughirah went out with ʿAli ibn Abi Talib to Yemen and sent to his wife Fatimah bint Qays the final divorce that remained from his divorces. He instructed al-Harith ibn Hisham and ʿAyyash ibn Abi Rabiʿah to give her maintenance, but they said to her: “By Allah, you have no maintenance unless you are pregnant.” So she came to the Prophet ﷺ and mentioned their statement to him. He said: “You have no maintenance.” Then she asked his permission to move, and he permitted her."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":41,"lafz":true}],"full":1,"dr":1},{"num":6677,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ يَقُولُ طُلِّقَتْ خَالَتِي فَأَرَادَتْ أَنْ تَجُدَّ نَخْلَهَا فَزَجَرَهَا رَجُلٌ أَنْ تَخْرُجَ فَأَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ بَلَى فَجُدِّي نَخْلَكِ فَإِنَّكِ عَسَى أَنْ تَصَدَّقِي أَوْ تَفْعَلِي مَعْرُوفًا."],"takhrij":"صحيح: رواه مسلم في الطلاق (1483)، من طرق عن ابن جريج، أخبرني أبو الزبير، أنه سمع جابر بن عبد الله، فذكره.","grade":"صحيح","chapter_ar":"باب في خروج المعتدة من بيتها للحاجة","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1483).","chapter_en":"A woman in her waiting period may leave her house for a need","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: My maternal aunt was divorced, and she wanted to cut the dates from her palm trees, but a man scolded her for going out. So she came to the Prophet ﷺ, and he said: “Rather, go and cut your palm trees, for perhaps you may give charity or do some good.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1483,"lafz":true}],"full":1},{"num":6678,"demo":false,"sanad":"","matn":["عَنْ فَاطِمَةَ، بِنْتِ قَيْسٍ قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ زَوْجِي طَلَّقَنِي ثَلاَثًا وَأَخَافُ أَنْ يُقْتَحَمَ عَلَىَّ. قَالَ فَأَمَرَهَا فَتَحَوَّلَتْ."],"takhrij":"صحيح: رواه مسلم في الطلاق (1482) عن محمد بن المثنى، حدثنا حفص بن غياث، حدثنا هشام، عن أبيه، عن فاطمة بنت قيس، فذكرته.","grade":"صحيح","chapter_ar":"باب في خروج المعتدة من بيتها للحاجة","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1482).","chapter_en":"A woman in her waiting period may leave her house for a need","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Fatimah bint Qays said: I said, “O Messenger of Allah, my husband has divorced me three times, and I fear that someone may force his way in upon me.” So he ordered her, and she moved."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1482,"lafz":true}],"full":1,"dr":1},{"num":6679,"demo":false,"sanad":"","matn":["عن عَائِشَةَ وَقَالَتْ إِنَّ فَاطِمَةَ كَانَتْ فِي مَسْكَنٍ وَحْشٍ فَخِيفَ عَلَيْهَا فَلِذَلِكَ أَرْخَصَ لَهَا رَسُولُ اللَّهِ ـ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"حسن: رواه أبو داود (2292) وابن ماجة (2032) كلاهما من حديث عبد الرحمن بن أبي الزناد، عن هشام بن عروة، عن أبيه، قال: دخلتُ على مروان، فقلت له: امرأة من أهلك طلّقت، فمررتُ عليها، وهي تنتقل. فقالت: أمرتْنا فاطمةُ بنت قيس، وأخبرتْنا أن رسول الله صلى الله عليه وسلم أمرها أن تنتقل. فقال مروان: هي أمرتهم بذلك.","grade":"حسن","chapter_ar":"باب في خروج المعتدة من بيتها للحاجة","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2292) and Ibn Majah (2032).","chapter_en":"A woman in her waiting period may leave her house for a need","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["ʿA’ishah said: Fatimah was living in a lonely place, and there was fear for her safety. For that reason, the Messenger of Allah ﷺ allowed her the concession."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2292,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2032}],"full":1,"dr":1},{"num":6680,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أم الْمُؤْمِنِينَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَحْرُمُ مِنَ الرَّضَاعَةِ مَا يَحْرُمُ مِنَ الْوِلاَدَةِ."],"takhrij":"صحيح: رواه مالك في الرضاع (16) عن عبدالله بن دينار، عن سليمان بن يسار وعن عروة بن الزبير، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب النساء اللاتي يحرم نكاحهن بالنسب والمصاهرة","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (16), Abu Dawud (2055), and al-Tirmidhi (1147). Al-Tirmidhi said: “This is a hasan sahih hadith.”","chapter_en":"Women whose marriage is forbidden due to blood relation and marital relation","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿA’ishah, the Mother of the Believers, reported that the Messenger of Allah ﷺ said: “Breastfeeding makes unlawful what birth makes unlawful.”"]},"intro":{"ar":["قال الله تعالى: ﴿حُرِّمَتْ عَلَيْكُمْ أُمَّهَاتُكُمْ وَبَنَاتُكُمْ وَأَخَوَاتُكُمْ وَعَمَّاتُكُمْ وَخَالَاتُكُمْ وَبَنَاتُ الْأَخِ وَبَنَاتُ الْأُخْتِ وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ وَأَخَوَاتُكُمْ مِنَ الرَّضَاعَةِ وَأُمَّهَاتُ نِسَائِكُمْ وَرَبَائِبُكُمُ اللَّاتِي فِي حُجُورِكُمْ مِنْ نِسَائِكُمُ اللَّاتِي دَخَلْتُمْ بِهِنَّ فَإِنْ لَمْ تَكُونُوا دَخَلْتُمْ بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْ وَحَلَائِلُ أَبْنَائِكُمُ الَّذِينَ مِنْ أَصْلَابِكُمْ وَأَنْ تَجْمَعُوا بَيْنَ الْأُخْتَيْنِ إِلَّا مَا قَدْ سَلَفَ إِنَّ اللَّهَ كَانَ غَفُورًا رَحِيمًا﴾ [النساء: ٢٣].","قال ابن عباس: “حرُمَ من النسب سبعٌ، ومن الصهر سبعٌ، ثم قرأ (حُرِّمَتْ عَلَيْكُمْ أُمَّهَٰتُكُمْ)","[سورة النساء: ٢٣] رواه البخاري (٥١٠٥)"],"en":["Allah the Exalted said: “Forbidden to you are your mothers, your daughters, your sisters, your paternal aunts, your maternal aunts, the daughters of your brother, the daughters of your sister, your mothers who nursed you, your sisters through nursing, the mothers of your wives, your stepdaughters under your care born of your wives with whom you have consummated marriage—though if you have not consummated marriage with them, there is no blame upon you—the wives of your sons who are from your own loins, and that you combine two sisters in marriage, except what has already passed. Indeed, Allah is Ever-Forgiving, Most Merciful.” [Surat al-Nisa’: 23]","Ibn ʿAbbas said: “Seven are forbidden through blood relation, and seven through marriage relation,” then he recited: “Forbidden to you are your mothers…” [Surat al-Nisa’: 23].","Narrated by al-Bukhari (5105)."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":16,"lafz":true,"n":98},{"key":"abudawud","label":"أبو داود","number":2055},{"key":"tirmidhi","label":"الترمذي","number":1147}],"full":1,"dr":1},{"num":6681,"demo":false,"sanad":"","matn":["عن أُمِّ حَبِيبَةَ بنت أَبِي سُفْيَانَ أَخْبَرَتْهَا أَنَّهَا، قَالَتْ يَا رَسُولَ اللَّهِ انْكِحْ أُخْتِي بِنْتَ أَبِي سُفْيَانَ فَقَالَ أَوَتُحِبِّينَ ذَلِكَ. فَقُلْتُ نَعَمْ، لَسْتُ لَكَ بِمُخْلِيَةٍ، وَأَحَبُّ مَنْ شَارَكَنِي فِي خَيْرٍ أُخْتِي. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ ذَلِكَ لاَ يَحِلُّ لِي. قُلْتُ فَإِنَّا نُحَدَّثُ أَنَّكَ تُرِيدُ أَنْ تَنْكِحَ بِنْتَ أَبِي سَلَمَةَ. قَالَ بِنْتَ أُمِّ سَلَمَةَ. قُلْتُ نَعَمْ. فَقَالَ لَوْ أَنَّهَا لَمْ تَكُنْ رَبِيبَتِي فِي حَجْرِي مَا حَلَّتْ لِي إِنَّهَا لاَبْنَةُ أَخِي مِنَ الرَّضَاعَةِ، أَرْضَعَتْنِي وَأَبَا سَلَمَةَ ثُوَيْبَةُ فَلاَ تَعْرِضْنَ عَلَىَّ بَنَاتِكُنَّ وَلاَ أَخَوَاتِكُنَّ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5101) ومسلم في الرضاعة (16:1449) كلاهما من حديث الزهري، قال: أخبرني عروة بن الزبير، أن زينب بنت أبي سلمة أخبرته، أن أم حبيبة بنت أبي سفيان أخبرتها فذكرتها واللفظ للبخاري. ولفظ مسلم نحوه.","grade":"متفق عليه","chapter_ar":"باب في تحريم ابنة الأخ من الرضاعة","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5101) and Muslim (16:1449), and this wording is from al-Bukhari.","chapter_en":"The prohibition of marrying a niece through breastfeeding","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Umm Habibah bint Abi Sufyan said: “O Messenger of Allah, marry my sister, the daughter of Abu Sufyan.” He said: “Would you like that?” I said: “Yes. I am not the only one with you, and I would most like that my sister share with me in goodness.” The Prophet ﷺ said: “That is not lawful for me.” I said: “But we hear that you want to marry the daughter of Abu Salamah.” He said: “The daughter of Umm Salamah?” I said: “Yes.” He said: “Even if she were not my stepdaughter under my care, she would still not be lawful for me. She is the daughter of my brother through breastfeeding. Thuwaybah nursed me and Abu Salamah. So do not offer your daughters or your sisters to me.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5101,"lafz":true},{"key":"muslim","label":"مسلم","number":16}],"full":1,"dr":1},{"num":6682,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ قِيلَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ   أَلاَ تَزَوَّجُ ابْنَةَ حَمْزَةَ قَالَ إِنَّهَا ابْنَةُ أَخِي مِنَ الرَّضَاعَةِ.","وزاد في رواية: وَإِنَّهُ يَحْرُمُ مِنَ الرَّضَاعَةِ مَا يَحْرُمُ مِنَ النَّسَبِ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5100)، ومسلم في الرضاع (13،1447) كلاهما من طريق شعبة، عن قتادة، عن جابر بن زيد، عن ابن عباس، فذكره.","grade":"متفق عليه","chapter_ar":"باب في تحريم ابنة الأخ من الرضاعة","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5100) and Muslim (13:1447). This wording is from al-Bukhari, and the additional wording is in Muslim.","chapter_en":"The prohibition of marrying a niece through breastfeeding","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿAbbas said: It was said to the Prophet ﷺ, “Will you not marry the daughter of Hamzah?” He said: “She is the daughter of my brother through breastfeeding.” In another narration he added: “Breastfeeding makes unlawful what lineage makes unlawful.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5100,"lafz":true},{"key":"muslim","label":"مسلم","number":13},{"key":"muslim","label":"مسلم في الرضاع","number":1447}],"full":1},{"num":6683,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ، قَالَ قُلْتُ يَا رَسُولَ اللَّهِ مَا لَكَ تَنَوَّقُ فِي قُرَيْشٍ وَتَدَعُنَا فَقَالَ وَعِنْدَكُمْ شَىْءٌ. قُلْتُ نَعَمْ بِنْتُ حَمْزَةَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّهَا لاَ تَحِلُّ لِي إِنَّهَا ابْنَةُ أَخِي مِنَ الرَّضَاعَةِ."],"takhrij":"صحيح: رواه مسلم في الرضاع (1446) من طريق أبي معاوية، عن الأعمش، عن سعد بن عبيدة، عن أبي عبد الرحمن ، عن علي، فذكره.","grade":"صحيح","chapter_ar":"باب في تحريم ابنة الأخ من الرضاعة","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1446).","chapter_en":"The prohibition of marrying a niece through breastfeeding","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["ʿAlī reported: I said: “O Messenger of Allah, why do you carefully choose from among Quraysh and leave us?” He asked: “Do you have someone?” I replied: “Yes, the daughter of Ḥamzah.” The Messenger of Allah ﷺ said: “She is not lawful for me. She is the daughter of my brother through breastfeeding.”"]},"buhuth":{"en":["The word “tanawwaqu” means to choose carefully and with particular preference from among Quraysh, while leaving us—that is, Banū Hāshim.","Some scholars vocalized it as “tatūqu,” from tawq, meaning longing and inclination."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1446,"lafz":true}],"full":1,"dr":1},{"num":6684,"demo":false,"sanad":"","matn":["عن أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَقُولُ قِيلَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَيْنَ أَنْتَ يَا رَسُولَ اللَّهِ عَنِ ابْنَةِ حَمْزَةَ. أَوْ قِيلَ أَلاَ تَخْطُبُ بِنْتَ حَمْزَةَ بْنِ عَبْدِ الْمُطَّلِبِ قَالَ إِنَّ حَمْزَةَ أَخِي مِنَ الرَّضَاعَةِ."],"takhrij":"صحيح: رواه مسلم في الرضاع (1448) من طريق ابن وهب، أخبرني مخرمة بن بكير، عن أبيه، قال: سمعت عبد الله بن مسلم يقول: سمعت محمد بن مسلم يقول: سمعت حميد بن عبدالرحمن يقول: سمعت أم سلمة تقول: فذكرته.","grade":"صحيح","chapter_ar":"باب في تحريم ابنة الأخ من الرضاعة","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1448).","chapter_en":"The prohibition of marrying a niece through breastfeeding","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet ﷺ, said: It was said to the Messenger of Allah ﷺ, “Why do you not marry the daughter of Hamzah?” Or it was said: “Will you not propose to the daughter of Hamzah, daughter of ʿAbd al-Muttalib?” He said: “Hamzah is my brother through breastfeeding.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1448,"lafz":true}],"full":1},{"num":6685,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أم الْمُؤْمِنِينَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ عِنْدَهَا، وَأَنَّهَا سَمِعَتْ صَوْتَ رَجُلٍ يَسْتَأْذِنُ فِي بَيْتِ حَفْصَةَ. قَالَتْ عَائِشَةُ: فَقُلْتُ: يَا رَسُولَ اللَّهِ، هَذَا رجلٌ يَسْتَأْذِنُ فِي بَيْتِكَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أُرَاهُ فُلاَنًا. لعمٍّ لحفصةَ مِنَ الرَّضَاعَةِ. فَقَالَتْ عَائِشَةُ: يَا رَسُولَ اللَّهِ، لَوْ كَانَ فُلاَنٌ حَيًّا – لعمِّها مِنَ الرَّضَاعَةِ – دَخَلَ عليّ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : نَعَمْ، إِنَّ الرَّضَاعَةَ تُحرِّم مَا تُحرِّم الْوِلاَدَةِ."],"takhrij":"متفق عليه: رواه مالك في الرضاع (1) عن عبد الله بن أبي بكر، عن عمرة بنت عبدالرحمن، أن عائشة أم المؤمنين أخبرتها، فذكرته.","grade":"متفق عليه","chapter_ar":"باب في لبن الفحل","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik in the chapter of breastfeeding (1), al-Bukhari (2646), and Muslim (1:1444).","chapter_en":"Concerning the milk of the husband","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["ʿA’ishah, the Mother of the Believers, reported that the Messenger of Allah ﷺ was with her, and she heard the voice of a man asking permission to enter Hafsah’s house. ʿA’ishah said: I said, “O Messenger of Allah, this is a man asking permission to enter your house.” The Messenger of Allah ﷺ said: “I think he is so-and-so,” the paternal uncle of Hafsah through breastfeeding. ʿA’ishah said: “O Messenger of Allah, if so-and-so were alive”—meaning her own uncle through breastfeeding—“would he be allowed to enter upon me?” The Messenger of Allah ﷺ said: “Yes. Breastfeeding makes unlawful what birth makes unlawful.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك في الرضاع","number":1,"lafz":true},{"key":"bukhari","label":"البخاري","number":2646},{"key":"muslim","label":"مسلم","number":1}],"full":1,"dr":1},{"num":6686,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أم الْمُؤْمِنِينَ قَالَتْ: جَاءَ عَمِّي مِنَ الرَّضَاعَةِ يَسْتَأْذِنُ عليّ، فَأَبَيْتُ أَنْ آذَنَ لَهُ عليّ، حَتَّى أَسْأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ. فَجَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلْتُهُ عَنْ ذَلِكَ. فَقَالَ: إِنَّهُ عَمُّكِ فَأْذَنِي لَهُ قَالَتْ: فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّمَا أرْضَعتْني الْمَرْأَةُ وَلَمْ يُرضِعْني الرَّجُلُ. فَقَالَ: إِنَّهُ عَمُّكِ فليَلِج عَلَيْكِ .","قالت عائشة: وذلك بعد ما ضرب علينا الحجاب.","وقالت عائشة: يَحرُم من الرضاعة ما يَحرُم من الولادة."],"takhrij":"متفق عليه: رواه مالك في الرضاع (2) عن هشام بن عروة، عن أبيه، عن عائشة أم المؤمنين، قالت: فذكرته.","grade":"متفق عليه","chapter_ar":"باب في لبن الفحل","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (2), al-Bukhari (5239), and Muslim (7:1445).","chapter_en":"Concerning the milk of the husband","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["ʿA’ishah, Mother of the Believers, said: My uncle through breastfeeding came asking permission to enter upon me, but I refused to allow him until I asked the Messenger of Allah about it. When the Messenger of Allah came, I asked him about that. He said: “He is your uncle, so allow him.” She said: I said, “O Messenger of Allah, it was the woman who nursed me; the man did not nurse me.” He said: “He is your uncle, so let him enter upon you.” ʿA’ishah said: That was after hijab had been made obligatory upon us. And ʿA’ishah said: What is unlawful through breastfeeding is unlawful just as through birth."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":2,"lafz":true},{"key":"bukhari","label":"البخاري","number":5239},{"key":"muslim","label":"مسلم","number":7}],"full":1,"dr":1},{"num":6687,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتِ اسْتَأْذَنَ عَلَىَّ أَفْلَحُ بْنُ قُعَيْسٍ فَأَبَيْتُ أَنْ آذَنَ، لَهُ فَأَرْسَلَ إِنِّي عَمُّكِ أَرْضَعَتْكِ امْرَأَةُ أَخِي. فَأَبَيْتُ أَنْ آذَنَ لَهُ فَجَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَذَكَرْتُ ذَلِكَ لَهُ فَقَالَ لِيَدْخُلْ عَلَيْكِ فَإِنَّهُ عَمُّكِ."],"takhrij":"صحيح: رواه مسلم في الرضاع (1445: 10) عن عبيد الله بن معاذ العنبري، حدثنا ابي، حدثنا شعبة، عن الحكم، عن عراك بن مالك، عن عروة، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب في لبن الفحل","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in the chapter of breastfeeding (10:1445).","chapter_en":"Concerning the milk of the husband","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["ʿA’ishah said: Aflah ibn Quʿays asked permission to enter upon me, but I refused. He sent word: “I am your uncle. The wife of my brother nursed you.” But I still refused to allow him. Then the Messenger of Allah came, and I mentioned that to him. He said: “Let him enter upon you, for he is your uncle.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم في الرضاع","number":10,"lafz":true},{"key":"muslim","label":"مسلم في الرضاع","number":1445,"n":3580}],"full":1},{"num":6688,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّهَا أَخْبَرَتْهُ أَنَّ أَفْلَحَ - أَخَا أَبِي الْقُعَيْسِ - جَاءَ يَسْتَأْذِنُ عَلَيْهَا وَهُوَ عَمُّهَا مِنَ الرَّضَاعَةِ بَعْدَ أَنْ أُنْزِلَ الْحِجَابُ قَالَتْ فَأَبَيْتُ أَنْ آذَنَ لَهُ فَلَمَّا جَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخْبَرْتُهُ بِالَّذِي صَنَعْتُ فَأَمَرَنِي أَنْ آذَنَ لَهُ عَلَىَّ."],"takhrij":"متفق عليه: رواه مالك في الرضاع (3) عن ابن شهاب، عن عروة بن الزبير، عن عائشة أم المؤمنين، فذكرته. ورواه البخاري في النكاح (5103)، ومسلم في الرضاع (3:1445) كلاهما من طريق مالك، به، مثله.","grade":"متفق عليه","chapter_ar":"باب في لبن الفحل","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (3), al-Bukhari (5103), and Muslim (3:1445).","chapter_en":"Concerning the milk of the husband","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["ʿA’ishah, the Mother of the Believers, reported that Aflah, the brother of Abu al-Quʿays, came asking permission to enter upon her—and he was her uncle through breastfeeding—after hijab had been revealed. She said: I refused to allow him in. When the Messenger of Allah came, I told him what I had done, and he ordered me to let him enter."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":3,"lafz":true},{"key":"bukhari","label":"البخاري","number":5103},{"key":"muslim","label":"مسلم","number":3}],"full":1,"dr":1},{"num":6689,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهَا قَالَتْ: كَانَ فِيمَا أُنْزِلَ مِنَ الْقُرْآنِ- عشرُ رَضَعَاتٍ مَعْلُومَاتٍ يحرِّمْنَ، ثُمَّ نُسِخْنَ بِخَمْسٍ مَعْلُومَاتٍ، فَتُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وهو فِيمَا يُقْرَأُ مِنَ الْقُرْآنِ."],"takhrij":"صحيح: رواه مالك في الرضاع (17) عن عبد الله بن أبي بكر بن حزم، عن عمرة بنت عبد الرحمن، عن عائشة زوج النبي صلى الله عليه وسلم أنها قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء أن الرضعات المحرّمة هي الخمس للصغير دون الحولين","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (17) and Muslim (24:1452).","chapter_en":"The breastfeeding that causes prohibition is five feedings for the young child under two years","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿA’ishah, the wife of the Prophet ﷺ, said: Among what was revealed in the Qur’an was that ten known feedings made marriage unlawful, then that was abrogated by five known feedings. The Messenger of Allah ﷺ passed away while that was still being recited in the Qur’an."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":17,"lafz":true},{"key":"muslim","label":"مسلم","number":24}],"full":1,"dr":1},{"num":6690,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: قـال رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ تُحرِّمُ المصَّـةُ وَالْمَصَّتَانِ."],"takhrij":"صحيح: رواه مسلم في الرضاع (1450) من طريق أيوب، عن ابن أبي مُليكة، عن عبد الله بن الزبير، عن عائشة قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء أن الرضعات المحرّمة هي الخمس للصغير دون الحولين","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1450).","chapter_en":"The breastfeeding that causes prohibition is five feedings for the young child under two years","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ said: “One suckling and two sucklings do not make marriage unlawful.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1450,"lafz":true}],"full":1},{"num":6691,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: دَخَلَ عليّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعِنْدِي رَجُلٌ قَاعِدٌ، فَاشْتَدَّ ذَلِكَ عَلَيْهِ، وَرَأَيْتُ الْغَضَبَ فِي وَجْهِهِ، قَالَتْ: فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّهُ أَخِي مِنَ الرَّضَاعَةِ. قَالَتْ: فَقَالَ: انْظُرْنَ إِخْوَتَكُنَّ مِنَ الرَّضَاعَةِ، فَإِنَّمَا الرَّضَاعَةُ مِنَ الْمَجَاعَةِ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5102)، ومسلم في الرضاع (1455) من طريق أشعث بن أبي الشعثاء، عن أبيه، عن مسروق. قال: قالت عائشة: فذكرته، والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء أن الرضعات المحرّمة هي الخمس للصغير دون الحولين","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5102) and Muslim (1455), and this wording is from Muslim.","chapter_en":"The breastfeeding that causes prohibition is five feedings for the young child under two years","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ entered upon me while a man was sitting with me. He disliked that strongly, and I saw anger on his face. I said: “O Messenger of Allah, he is my brother through breastfeeding.” He said: “Be careful in identifying who your brothers through breastfeeding are, for breastfeeding only counts when it is due to hunger.”"]},"buhuth":{"en":["His statement, “Breastfeeding only counts when it is due to hunger,” means that the breastfeeding which establishes prohibition and allows seclusion is when the child is still an infant, and the milk serves as nourishment and satisfies hunger. This is during the first two years of the child’s life, as Allah said: “Mothers shall breastfeed their children for two complete years for whoever wishes to complete the nursing period” [al-Baqarah: 233], together with His saying: “And his weaning is in two years” [Luqman: 14]. The hadith of Umm Salamah also indicates this."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5102,"lafz":true},{"key":"muslim","label":"مسلم","number":1455}],"full":1,"dr":1},{"num":6692,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: قـال رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ تُحَرِّمُ الخطفـةُ والخطفتان."],"takhrij":"صحيح: رواه النسائي (3311) عن محمد بن عبد الله بن بَزيع،-بالباء المفتوحة والزاء المكسورة- قال ثنا يزيد – يعني ابن زريع-، قال: ثنا سعيد، عن قتادة قال: كتبنا إلى إبراهيم بن يزيد النخعي نسأله عن الرضاع. فكتب أن شُريحاً حدثنا أن عليّاً وابنَ مسعود كانا يقولان: يحرمُ من الرضاع قليلُه وكثيرُه. وكان في كتابه: أن أبا الشعثاء المحاربي، ثنا، أن عائشة حدّثته أن نبي الله صلى الله عليه وسلم قال: فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء أن الرضعات المحرّمة هي الخمس للصغير دون الحولين","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3311).","chapter_en":"The breastfeeding that causes prohibition is five feedings for the young child under two years","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ said: “One quick suckling and two quick sucklings do not make marriage unlawful.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3311,"lafz":true,"n":3310}],"full":1,"dr":1},{"num":6693,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يُحَرِّمُ مِنَ الرَّضَاعَةِ الْمَصَّةُ، وَالْمَصَّتَانِ."],"takhrij":"صحيح: رواه النسائي (3309) وأحمد (16110) وعبد الرزاق (7/469) والبيهقي (7/454) والمروزي في السنة (283،280،279) كلهم من طرق عن عروة بن الزبير، عن أخيه عبد الله بن الزبير فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء أن الرضعات المحرّمة هي الخمس للصغير دون الحولين","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3309), Ahmad (16110), ʿAbd al-Razzaq (7/469), and al-Bayhaqi (7/454).","chapter_en":"The breastfeeding that causes prohibition is five feedings for the young child under two years","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullah ibn al-Zubayr reported that the Prophet ﷺ said: “One suckling and two sucklings do not make marriage unlawful through breastfeeding.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3309,"lafz":true,"n":3309},{"key":"abdrazzaq","label":"عبد الرزاق","number":469},{"key":"kubrabayhaqi","label":"البيهقي","number":454},{"key":"ahmad","label":"مسند الإمام أحمد","number":16110,"n":16110}],"full":1,"dr":1},{"num":6694,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ رَضَاعَ إِلاَّ مَا فَتَقَ الأَمْعَاءَ."],"takhrij":"حسن: رواه ابن ماجة (1946) عن حرملة بن يحيى، قال: حدثنا عبد الله بن وهب، قال: أخبرني ابن لهيعة، عن أبي الأسود، عن عروة، عن عبد الله بن الزبير فذكره.","grade":"حسن","chapter_ar":"باب ما جاء أن الرضعات المحرّمة هي الخمس للصغير دون الحولين","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (1946).","chapter_en":"The breastfeeding that causes prohibition is five feedings for the young child under two years","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullah ibn al-Zubayr reported that the Messenger of Allah ﷺ said: “There is no breastfeeding that counts except that which fills the stomach.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":1946,"lafz":true}],"full":1,"dr":1},{"num":6695,"demo":false,"sanad":"","matn":["عَنْ أُمِّ الْفَضْلِ، قَالَتْ دَخَلَ أَعْرَابِيٌّ عَلَى نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ فِي بَيْتِي فَقَالَ يَا نَبِيَّ اللَّهِ إِنِّي كَانَتْ لِي امْرَأَةٌ فَتَزَوَّجْتُ عَلَيْهَا أُخْرَى فَزَعَمَتِ امْرَأَتِي الْأُولَى أَنَّهَا أَرْضَعَتِ امْرَأَتِي الْحُدْثَى رَضْعَةً أَوْ رَضْعَتَيْنِ. فَقَالَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ تُحَرِّمُ الإِمْلاَجَةُ وَالإِمْلاَجَتَانِ."],"takhrij":"صحيح: رواه مسلم في الرضاع (18:1451) من طريق المعتمر بن سليمان. عن أيوب، يحدث عن أبي الخليل، عن عبد الله بن الحارث، عن أم الفضل: فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء أن الرضعات المحرّمة هي الخمس للصغير دون الحولين","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (18:1451).","chapter_en":"The breastfeeding that causes prohibition is five feedings for the young child under two years","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Umm al-Fadl said: A bedouin entered upon the Prophet ﷺ while he was in my house and said: “O Prophet of Allah, I had a wife, then I married another woman besides her. My first wife claims that she nursed my new wife once or twice.” The Prophet ﷺ said: “One suckling or two sucklings do not make marriage unlawful.”"]},"buhuth":{"en":["In another narration: “One feeding or two feedings, or one suckling or two sucklings, do not make marriage unlawful.”","In another narration: “Nor do two feedings and two sucklings make marriage unlawful.”","And in another narration: “Does one single feeding make marriage unlawful?” He said: “No.”","His statement, “imlajah,” means one suckling. It is said: the child “malaja” his mother when he suckled from her, and “amljat-hu ummuhu” means his mother nursed him."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":18,"lafz":true}],"full":1,"dr":1},{"num":6696,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ، قَالَتْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ يُحَرِّمُ مِنَ الرَّضَاعَةِ إِلاَّ مَا فَتَقَ الأَمْعَاءَ فِي الثَّدْىِ وَكَانَ قَبْلَ الْفِطَامِ."],"takhrij":"صحيح: رواه الترمذي (1152) والنسائي في الكبرى (5441) كلاهما عن قُتيبة، حدثنا أبو عوانة، عن هشام بن عروة، عن أبيه، عن فاطمة بنت المنذر، عن أم سلمة فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء أن الرضعات المحرّمة هي الخمس للصغير دون الحولين","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (1152) and al-Nasā’ī in al-Sunan al-Kubrā (5441). Al-Tirmidhī said: Hasan Sahih.","chapter_en":"The breastfeeding that causes prohibition is five feedings for the young child under two years","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Umm Salamah reported that the Messenger of Allah ﷺ said: “Breastfeeding does not establish the prohibition of marriage except that which reaches and nourishes the intestines during the period of breastfeeding and occurs before weaning.”"]},"buhuth":{"en":["The phrase “opens the intestines” means that the milk enters them in such a way that it becomes nourishment for the child.","The phrase “during breastfeeding” means during the nursing period.","Al-Ḥāfiẓ Ibn al-Qayyim said in Zād al-Maʿād (5/580):","“This is a well-known expression among the Arabs. They say, ‘So-and-so died while at the breast,’ meaning during the nursing period before weaning.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1152,"lafz":true},{"key":"kubranasai","label":"النسائي في الكبرى","number":5441}],"full":1,"dr":1},{"num":6697,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّ أَبَا حُذَيْفَةَ بْنَ عُتْبَةَ بْنِ رَبِيعَةَ بْنِ عَبْدِ شَمْسٍ – وَكَانَ مِمَّنْ شَهِدَ بَدْرًا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – تبنّىَ سَالِمًا، وَأَنْكَحَهُ بنتَ أَخِيهِ هِنْدَ بِنْتَ الْوَلِيدِ بْنِ عُتْبَةَ بْنِ رَبِيعَةَ، وَهْوَ مَوْلًى لاِمْرَأَةٍ مِنَ الأَنْصَارِ، كَمَا تَبَنَّى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ زَيْدًا، وَكَانَ مَنْ تَبَنَّى رَجُلاً فِي الْجَاهِلِيَّةِ دَعَاهُ النَّاسُ إِلَيْهِ، وَوَرِثَ مِنْ مِيرَاثِهِ حَتَّى أَنْزَلَ اللَّهُ: ﴿ادْعُوهُمْ لِآبَائِهِمْ هُوَ أَقْسَطُ عِنْدَ اللَّهِ فَإِنْ لَمْ تَعْلَمُوا آبَاءَهُمْ فَإِخْوَانُكُمْ فِي الدِّينِ وَمَوَالِيكُمْ﴾ [الأحزاب: ٥] فَرُدُّوا إِلَى آبَائِهِمْ، فَمَنْ لَمْ يُعْلَمْ لَهُ أَبٌ كَانَ مَوْلًى وَأَخًا فِي الدِّينِ، فَجَاءَتْ سَهْلَةُ بِنْتُ سُهَيْلِ بْنِ عَمْرٍو الْقُرَشِيِّ، ثُمَّ السامري، - وَهْوَ امْرَأَةُ أَبِي حُذَيْفَةَ بن عُتْبَةَ – إِلَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ! إِنَّا كُنَّا نَرَى سَالِمًا وَلَدًا، وَقَدْ أَنْزَلَ اللَّهُ فِيهِ مَا قَدْ عَلِمْتَ\" فذكرت الْحَدِيثَ."],"takhrij":"صحيح: رواه البخاري في النكاح (5088) عن أبي اليمان، أخبرنا شعيب، عن الزهري، قال: أخبرني عروة بن الزبير، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في رضاعة الكبير","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5088).","chapter_en":"Chapter on what has been reported concerning the breastfeeding of an adult","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿA’ishah reported that Abu Hudhayfah ibn ʿUtbah ibn Rabiʿah ibn ʿAbd Shams—who was among those who witnessed Badr with the Prophet ﷺ—had adopted Salim, and married him to the daughter of his brother, Hind bint al-Walid ibn ʿUtbah ibn Rabiʿah. Salim had been the freed slave of a woman from the Ansar, just as the Prophet had adopted Zayd. In the pre-Islamic period, when a man adopted someone, people would call him by the adopter’s name and he would inherit from him, until Allah revealed: “Call them by their fathers’ names; that is more just in the sight of Allah. But if you do not know their fathers, then they are your brothers in religion and your clients.” [al-Ahzab: 5] So they were returned to their fathers, and whoever had no known father was regarded as a client and a brother in faith. Then Sahlah bint Suhayl ibn ʿAmr al-Qurashiyyah al-ʿAmiriyyah—the wife of Abu Hudhayfah ibn ʿUtbah—came to the Prophet and said: “O Messenger of Allah, we used to regard Salim as a son, and Allah has now revealed concerning him what you know,” and then she mentioned the rest of the hadith."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5088,"lafz":true}],"full":1,"dr":1},{"num":6698,"demo":false,"sanad":"","matn":["عَنِ ابْنِ شِهَابٍ قَالَ: أَخْبَرَنِي عُرْوَةُ بْنُ الزُّبَيْرِ، أَنَّ أَبَا حُذَيْفَةَ بْنَ عُتْبَةَ بْنِ رَبِيعَةَ، وَكَانَ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَكَانَ قَدْ شَهد بَدْرًا. وَكَانَ تَبَنَّى سَالِمًا الَّذِي يُقَالُ لَهُ: سَالِمٌ مَوْلَى أَبِي حُذَيْفَةَ، كَمَا تَبَنَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ زيدَ بْنَ حَارِثَةَ، وَأَنْكَحَ أَبُو حُذَيْفَةَ سَالِمًا، وَهُوَ يَرَى أَنَّهُ ابْنُهُ، أَنْكَحَهُ بنتَ أَخِيهِ فَاطِمَةَ بِنْتَ الْوَلِيدِ بْنِ عُتْبَةَ بْنِ رَبِيعَةَ، وَهِيَ يَوْمَئِذٍ مِنَ الْمُهَاجِرَاتِ الأُوَل. وَهِيَ مِنْ أَفْضَلِ أَيَامَى قُرَيْشٍ. فَلَمَّا أَنْزَلَ اللَّهُ فِي كِتَابِهِ ﴿ادْعُوهُمْ لِآبَائِهِمْ هُوَ أَقْسَطُ عِنْدَ اللَّهِ فَإِنْ لَمْ تَعْلَمُوا آبَاءَهُمْ فَإِخْوَانُكُمْ فِي الدِّينِ وَمَوَالِيكُمْ﴾ [الأحزاب: ٥] رُدَّ كلُّ وَاحِدٍ مِنْ أُولَئِكَ إِلَى أَبِيهِ، فَإِنْ لَمْ يُعْلَمْ أَبُوهُ رُدَّ إِلَى مَوْلاَهُ. فَجَاءَتْ سَهْلَةُ بِنْتُ سُهَيْلٍ -وَهِيَ امْرَأَةُ أَبِي حُذَيْفَةَ، وَهِيَ مِنْ بَنِي عَامِرِ بْنِ لؤي- إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ! كُنَّا نَرَى سَالِمًا وَلَدًا وَكَانَ يَدْخُلُ عليَّ، وَأَنَا فُضُلٌ وَلَيْسَ لَنَا إِلاَّ بَيْتٌ وَاحِدٌ. فَمَاذَا تَرَى فِي شَأْنِهِ؟ فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَرْضِعِيهِ خمسَ رَضَعَاتٍ فيَحرُمُ بِلَبَنِهَا وَكَانَتْ تَرَاهُ ابْنًا مِنَ الرَّضَاعَةِ. فَأَخَذَتْ بِذَلِكَ عَائِشَةُ أُمُّ الْمُؤْمِنِينَ. فِيمَنْ كَانَتْ تُحب أَنْ يَدْخُلَ عَلَيْهَا مِنَ الرِّجَالِ. فَكَانَتْ تَأْمُرُ أُخْتَهَا أُمَّ كُلْثُومٍ بِنْتَ أَبِي بَكْرٍ الصِّدِّيقِ. وَبَنَاتِ أَخِيهَا أَنْ يُرضعنَ مَنْ أَحَبَّتْ أَنْ يَدْخُلَ عَلَيْهَا مِنَ الرِّجَالِ. وَأَبَى سَائِرُ أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَدْخُلَ عَلَيْهِنَّ بِتِلْكَ الرَّضَاعَةِ أَحَدٌ مِنَ النَّاسِ. وَقُلْنَ: لاَ، مَا نَرَى الَّذِي أَمَرَ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلاَّ رُخْصَةً مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي رَضَاعَةِ سَالِمٍ وَحْدَهُ. لاَ. وَاللَّهِ، لاَ يَدْخُلُ عَلَيْنَا بِهَذِهِ الرَّضَاعَةِ أَحَدٌ. فَعَلَى هَذَا كَانَ أَزْوَاجُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي رَضَاعَةِ الْكَبِيرِ بأنه خاص بسالم."],"takhrij":"صحيح: رواه مالك في الرضاع (12) عن ابن شهاب، أنه سئل عن رضاعة الكبير، فقال: أخبرني عروة بن الزبير، به.","grade":"صحيح","chapter_ar":"باب ما جاء في رضاعة الكبير","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (12) and ʿAbd al-Razzaq (13886).","chapter_en":"Chapter on what has been reported concerning the breastfeeding of an adult","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn Shihab said: ʿUrwah ibn al-Zubayr informed me that Abu Hudhayfah ibn ʿUtbah ibn Rabiʿah, who was among the Companions of the Messenger of Allah and had witnessed Badr, had adopted Salim, who was known as Salim the freed slave of Abu Hudhayfah, just as the Messenger of Allah had adopted Zayd ibn Harithah. Abu Hudhayfah, regarding Salim as his son, married him to the daughter of his brother, Fatimah bint al-Walid ibn ʿUtbah ibn Rabiʿah, who was then among the earliest female emigrants and one of the finest unmarried women of Quraysh. When Allah revealed in His Book: “Call them by their fathers’ names; that is more just in the sight of Allah. But if you do not know their fathers, then they are your brothers in religion and your clients” [al-Ahzab: 5], each of them was returned to his real father, and whoever had no known father was returned to his patron. Then Sahlah bint Suhayl—the wife of Abu Hudhayfah, who was from Banu ʿAmir ibn Lu’ayy—came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, we used to regard Salim as a son. He used to enter upon me while I was in an informal state of dress, and we have only one house. What do you think about his case?” The Messenger of Allah ﷺ said to her: “Breastfeed him five times, and he will become unlawful to you through that milk.” So she regarded him as a son through breastfeeding. ʿA’ishah, Mother of the Believers, adopted that view regarding those men whom she wished to be able to enter upon her. She would instruct her sister Umm Kulthum bint Abi Bakr al-Siddiq and the daughters of her brother to breastfeed those whom she wished to enter upon her among the men. But the rest of the wives of the Prophet refused to allow anyone to enter upon them through such breastfeeding, and they said: “No, by Allah, we do not regard what the Messenger of Allah ordered except as a special concession from the Messenger of Allah concerning Salim alone. No, by Allah, no one will enter upon us through this kind of breastfeeding.” So based on this, the wives of the Prophet held that the breastfeeding of an adult was specific to Salim."]},"buhuth":{"en":["As for the statement of Sahlah bint Suhayl, “He used to enter upon me while I was in an informal state of dress,” Ibn ʿAbd al-Barr said: “The meaning of the hadith, in my view, is that he used to enter upon her while some part of her was uncovered, such as the hair, hand, and face.” He also said regarding how an adult would be breastfed: the milk would be expressed for him and then given to him to drink. As for the woman putting her breast directly in his mouth as is done with an infant, that is not lawful according to a group of scholars. End quote."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":12,"lafz":true},{"key":"abdrazzaq","label":"عبد الرزاق","number":13886}],"full":1,"dr":1},{"num":6699,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ جَاءَتْ سَهْلَةُ بِنْتُ سُهَيْلٍ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ يَا رَسُولَ اللَّهِ إِنِّي أَرَى فِي وَجْهِ أَبِي حُذَيْفَةَ مِنْ دُخُولِ سَالِمٍ - وَهُوَ حَلِيفُهُ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَرْضِعِيهِ. قَالَتْ وَكَيْفَ أُرْضِعُهُ وَهُوَ رَجُلٌ كَبِيرٌ فَتَبَسَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَالَ قَدْ عَلِمْتُ أَنَّهُ رَجُلٌ كَبِيرٌ.","وفي رواية: أرْضِعيه تحرُمي عليه، ويذهبُ الذي في نفس أبي حذيفة فرجعت فقالت: إني قد أرضعتُه، فذهب الذي في نفس أبي حذيفة."],"takhrij":"صحيح: رواه مسلم في الرضاع (1453) من طريق سفيان بن عيينة، عن عبد الرحمن بن القاسم، عن أبيه، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في رضاعة الكبير","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1453).","chapter_en":"Chapter on what has been reported concerning the breastfeeding of an adult","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿA’ishah said: Sahlah bint Suhayl came to the Prophet ﷺ and said: “O Messenger of Allah, I can see displeasure on the face of Abu Hudhayfah because of Salim entering upon us, and he is his client.” So the Prophet ﷺ said: “Breastfeed him.” She said: “How can I breastfeed him when he is a grown man?” The Messenger of Allah ﷺ smiled and said: “I know that he is a grown man.” In another narration: “Breastfeed him, and he will become unlawful for you, and what is in the heart of Abu Hudhayfah will go away.” She then returned and said: “I have breastfed him, and what was in the heart of Abu Hudhayfah has gone away.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1453,"lafz":true}],"full":1,"dr":1},{"num":6700,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: جَاءَتْ سَهْلَةُ بِنْتُ سُهَيْلٍ إِلَى رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَقَالَتْ: يَا رَسُولَ اللهِ، إِنَّ سَالِمًا يُدْعَى لأَبِي حُذَيْفَةَ وَيَأْوِي مَعَهُ، وَيَدْخُلُ عَلَيَّ فَيَرَانِي فُضُلًا، وَنَحْنُ فِي مَنْزِلٍ ضَيِّقٍ، وَقَالَ اللهُ: ﴿ادْعُوهُمْ لآبَائِهِمْ هُوَ أَقْسَطُ عِنْدَ اللهِ﴾ [الأحزاب: ٥]، فَقَالَ رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَرْضِعِيهِ تَحْرُمِي عَلَيْهِ."],"takhrij":"صحيح: رواه عبد الرزاق (13885) عن معمر، عن الزهري، عن عروة، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في رضاعة الكبير","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by ʿAbd al-Razzaq (13885).","chapter_en":"Chapter on what has been reported concerning the breastfeeding of an adult","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿA’ishah said: Sahlah bint Suhayl came to the Messenger of Allah and said: “O Messenger of Allah, Salim is attributed to Abu Hudhayfah, lives with him, and enters upon me while I am in an informal state of dress, and we live in a small dwelling. And Allah the Exalted has said: ‘Call them by their fathers’ names; that is more just in the sight of Allah.’” [al-Ahzab: 5] So he said: “Breastfeed him, and he will become unlawful for you.”"]},"buhuth":{"en":["Al-Zuhri said: “Some of the wives of the Prophet said: We do not know; perhaps this was a special concession for Salim alone.”","Al-Zuhri also said: “ʿA’ishah continued to give legal rulings that breastfeeding after weaning could establish prohibition until she died.”","Her statement, “fudul,” means dressed informally, that is, when a woman is wearing her ordinary working clothes."]}},"tuhfa":{},"refs":[{"key":"abdrazzaq","label":"عبد الرزاق","number":13885,"lafz":true}],"full":1,"dr":1},{"num":6701,"demo":false,"sanad":"","matn":["عَنْ زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ، قَالَتْ قَالَتْ أُمُّ سَلَمَةَ لِعَائِشَةَ إِنَّهُ يَدْخُلُ عَلَيْكِ الْغُلاَمُ الأَيْفَعُ الَّذِي مَا أُحِبُّ أَنْ يَدْخُلَ عَلَىَّ. قَالَ فَقَالَتْ عَائِشَةُ أَمَا لَكِ فِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُسْوَةٌ قَالَتْ إِنَّ امْرَأَةَ أَبِي حُذَيْفَةَ قَالَتْ يَا رَسُولَ اللَّهِ إِنَّ سَالِمًا يَدْخُلُ عَلَىَّ وَهُوَ رَجُلٌ وَفِي نَفْسِ أَبِي حُذَيْفَةَ مِنْهُ شَىْءٌ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَرْضِعِيهِ حَتَّى يَدْخُلَ عَلَيْكِ."],"takhrij":"صحيح: رواه مسلم في الرضاع (29:1453) عن محمد بن المثنى، حدثنا محمد بن جعفر، حدثنا شعبة، عن حميد بن نافع، عن زينب بنت أم سلمة، قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في رضاعة الكبير","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (29:1453).","chapter_en":"Chapter on what has been reported concerning the breastfeeding of an adult","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Zaynab bint Umm Salamah said: Umm Salamah said to ʿA’ishah: “A nearly grown boy enters upon you, and I would not like such a one to enter upon me.” ʿA’ishah said: “Do you not have in the Messenger of Allah ﷺ an example?” The wife of Abu Hudhayfah said: “O Messenger of Allah, Salim enters upon me while he is a grown man, and Abu Hudhayfah feels something about that.” So the Messenger of Allah said: “Breastfeed him so that he may enter upon you.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":29,"lafz":true}],"full":1,"dr":1},{"num":6702,"demo":false,"sanad":"","matn":["عن أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَتْ تَقُولُ أَبَى سَائِرُ أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُدْخِلْنَ عَلَيْهِنَّ أَحَدًا بِتِلْكَ الرَّضَاعَةِ وَقُلْنَ لِعَائِشَةَ وَاللَّهِ مَا نَرَى هَذَا إِلاَّ رُخْصَةً أَرْخَصَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِسَالِمٍ خَاصَّةً فَمَا هُوَ بِدَاخِلٍ عَلَيْنَا أَحَدٌ بِهَذِهِ الرَّضَاعَةِ وَلاَ رَائِينَا."],"takhrij":"صحيح: رواه مسلم في الرضاع (1454) عن عبد الملك بن شعيب بن الليث، حدثني أبي، عن جدّي، حدثني عقيل بن خالد، عن ابن شهاب أنه قال: أخبرني أبو عبيدة بن عبدالله بن زمعة، أن أمه زينب بنت أبي سلمة أخبرته، أن أمّها أم سلمة زوج النبي صلى الله عليه وسلم كانت تقول: فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في رضاعة الكبير","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1454).","chapter_en":"Chapter on what has been reported concerning the breastfeeding of an adult","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet ﷺ, used to say: The rest of the wives of the Prophet ﷺ refused to allow anyone to enter upon them through that kind of breastfeeding, and they said to ʿA’ishah: “By Allah, we do not see this except as a special concession given by the Messenger of Allah ﷺ for Salim alone. No one will enter upon us through such breastfeeding, nor will we hold that view.”"]},"buhuth":{"en":["The hadiths of this chapter indicate that prohibition is not established by the breastfeeding of an adult, and the story of Salim, the freed slave of Abu Hudhayfah, was specific to him. It was a special concession granted by the Messenger of Allah for Salim. ʿA’ishah held that adult breastfeeding established prohibition, but the rest of the Mothers of the Believers disagreed with her, and no other Companion agreed with her on that."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1454,"lafz":true}],"full":1,"dr":1},{"num":6703,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ الْحَارِثِ قَالَ: تَزَوَّجْتُ امْرَأَةً، فَجَاءَتْنَا امْرَأَةٌ سَوْدَاءُ. فَقَالَتْ: أَرْضَعْتُكُمَا. فَأَتَيْتُ النبيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: تَزَوَّجْتُ فُلاَنَةَ بِنْتَ فُلاَنٍ، فَجَاءَتْنَا امْرَأَةٌ سَوْدَاءُ فَقَالَتْ لِي: إِنِّي قَدْ أَرْضَعْتُكُمَا، وهي كَاذِبَةٌ، فَأَعْرَضَ، فَأَتَيْتُهُ مِنْ قِبَلِ وَجْهِهِ، قُلْتُ: إِنَّهَا كَاذِبَةٌ، قَالَ: كَيْفَ بِهَا وَقَدْ زَعَمَتْ أَنَّهَا قَدْ أَرْضَعَتْكُمَا دَعْهَا عَنْكَ."],"takhrij":"صحيح: رواه البخاري في النكاح (5104) عن علي بن عبد الله، حدثنا إسماعيل بن إبراهيم، أخبرنا أيوب، عن عبد الله بن أبي مليكة. قال: حدثني عبيد بن أبي مريم، عن عقبة بن الحارث قال: وقد سمعته من عقبة، لكني لحديث عبيد أحفظ قال: فذكر الحديث.","grade":"صحيح","chapter_ar":"باب شهادة المرضِعة","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5104).","chapter_en":"The testimony of the woman who breastfed","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["ʿUqbah ibn al-Harith said: I married a woman, then a black woman came to us and said: “I breastfed both of you.” So I came to the Prophet ﷺ and said: “I married so-and-so, daughter of so-and-so, and a black woman came to us and told me that she had breastfed both of us, but she is lying.” He turned away. Then I came to him again from the other side and said: “She is lying.” He said: “How can you remain with her after she has claimed that she breastfed both of you? Leave her.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5104,"lafz":true}],"full":1,"dr":1},{"num":6704,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ سَبْعَةٌ يُظِلُّهُمُ اللَّهُ يَوْمَ الْقِيَامَةِ فِي ظِلِّهِ، يَوْمَ لاَ ظِلَّ إِلاَّ ظِلُّهُ إِمَامٌ عَادِلٌ، وَشَابٌّ نَشَأَ فِي عِبَادَةِ اللَّهِ، وَرَجُلٌ ذَكَرَ اللَّهَ فِي خَلاَءٍ فَفَاضَتْ عَيْنَاهُ، وَرَجُلٌ قَلْبُهُ مُعَلَّقٌ فِي الْمَسْجِدِ، وَرَجُلاَنِ تَحَابَّا فِي اللَّهِ، وَرَجُلٌ دَعَتْهُ امْرَأَةٌ ذَاتُ مَنْصِبٍ وَجَمَالٍ إِلَى نَفْسِهَا قَالَ إِنِّي أَخَافُ اللَّهَ. وَرَجُلٌ تَصَدَّقَ بِصَدَقَةٍ فَأَخْفَاهَا، حَتَّى لاَ تَعْلَمَ شِمَالُهُ مَا صَنَعَتْ يَمِينُهُ."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6806)، ومسلم في الزكاة (91:1031) كلاهما من طريق عبيدالله بن عمر، عن خُبيب بن عبدالرحمن، عن حفص بن عاصم، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب العدل في القضاء","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6806) and Muslim (1031:91).","chapter_en":"Justice in Judgement","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said: “There are seven whom Allah will shade in His Shade on the Day of Resurrection when there is no shade except His Shade: a just ruler; a youth who grew up in the worship of Allah; a man who remembered Allah in private and his eyes overflowed with tears; a man whose heart is attached to the mosque; two men who love each other for the sake of Allah; a man whom a woman of position and beauty invited to herself, and he said, ‘Indeed, I fear Allah’; and a man who gave charity and hid it so that his left hand did not know what his right hand had spent.”"]},"intro":{"ar":["قال تعالى: ( إِنَّ اللَّهَ يَأْمُرُكُمْ أَن تُؤَدُّوا الْأَمَانَاتِ إِلَىٰ أَهْلِهَا وَإِذَا حَكَمْتُم بَيْنَ النَّاسِ أَن تَحْكُمُوا بِالْعَدْلِ) [النساء: ٥٨]","وقال لنبيه: ﴿وَأَنِ احْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ وَاحْذَرْهُمْ أَن يَفْتِنُوكَ عَن بَعْضِ مَا أَنزَلَ اللَّهُ إِلَيْكَ﴾ [المائدة: ٤٩]","وقال تعالى: ( وَلَا يَجْرِمَنَّكُمْ شَنَآنُ قومٍ عَلَىٰ أَلَّا تَعْدِلُوا ۚ اعْدِلُوا هُوَ أَقْرَبُ لِلتَّقْوَىٰ) [المائدة: ٨]"],"en":["Allah the Exalted said: “Indeed, Allah commands you to render trusts to their owners and when you judge between people to judge with justice.” [Surat al-Nisa’: 58]","And He said to His Prophet ﷺ: “And judge between them by what Allah has revealed and do not follow their inclinations and beware of them, lest they tempt you away from some of what Allah has revealed to you.” [Surat al-Ma’idah: 49]","And the Exalted said: “And do not let the hatred of a people lead you to not be just. Be just; that is nearer to righteousness.” [Surat al-Ma’idah: 8]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6806,"lafz":true},{"key":"muslim","label":"مسلم","number":1031},{"key":"muslim","label":"مسلم في الزكاه","number":91}],"full":1,"rep":[6929,13597]},{"num":6705,"demo":false,"sanad":"","matn":["عن عبـدالله بن عمرو قَالَ: قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ الْمُقْسِطِينَ عِنْدَ اللَّهِ عَلَى مَنَابِرَ مِنْ نُورٍ عَنْ يَمِينِ الرَّحْمَنِ عَزَّ وَجَلَّ وَكِلْتَا يَدَيْهِ يَمِينٌ الَّذِينَ يَعْدِلُونَ فِي حُكْمِهِمْ وَأَهْلِيهِمْ وَمَا وَلُوا."],"takhrij":"صحيح: رواه مسلم في الإمارة (1827) من طريق سفيان بن عيينة، عن عمرو بن دينار، عن عمرو بن أوس، عن عبدالله بن عمرو، فذكره.","grade":"صحيح","chapter_ar":"باب العدل في القضاء","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1827).","chapter_en":"Justice in Judgement","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr said: The Messenger of Allah ﷺ said: “Indeed, the just will be with Allah on thrones of light, at the right hand of the Most Merciful, the Mighty and Sublime—and both of His hands are right hands—those who are just in their ruling, with their families, and in what they have been placed in charge of.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1827,"lafz":true}],"full":1,"rep":[7587,13347]},{"num":6706,"demo":false,"sanad":"","matn":["عن عياض بن حمار المجاشعي أن نبي الله صلى الله عليه وسلم قال ذات يوم في خطبته فذكر الحديث: قال: أهل الجنة ثلاثة: ذو سلطان مقسط متصدق موفق، ورجل رحيم رقيق القلب لكل ذي قربى ومسلم، وعفيف متعفف ذو عيال...  فذكر الحديث."],"takhrij":"صحيح: رواه مسلم في كتاب الجنة (2865) من طرق عن معاذ بن هشام، حدثني أبي، عن قتادة، عن مطرف بن عبدالله بن الشخير، عن عياض ابن حمار المجاشعي فذكره.","grade":"صحيح","chapter_ar":"باب العدل في القضاء","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2865).","chapter_en":"Justice in Judgement","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["ʿIyad ibn Himar al-Mujashiʿi narrated that the Prophet of Allah ﷺ said one day in his sermon, and he mentioned the hadith: He said: “The people of Paradise are three types: a person of authority who is just, gives charity, and is guided to success; a merciful man who is soft-hearted to every relative and Muslim; and a chaste man who refrains from begging despite having a family…” and he mentioned the rest of the hadith."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2865,"lafz":true}],"full":1},{"num":6707,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ثَلاَثَةٌ لاَ تُرَدُّ دَعْوَتُهُمُ: الإمام الْعَادِلُ، والصائم حَتَّى يُفْطِرَ، وَدَعْوَةُ الْمَظْلُومِ تحمل عَلَى الْغَمَامِ، وتُفتح لَهَا أَبْوَابَ السَّمَاءِ، وَيَقُولُ الرَّبُّ: وَعِزَّتِي لأَنْصُرَنَّكَ وَلَوْ بَعْدَ حِينٍ."],"takhrij":"حسن: رواه الترمذي (3598)، وابن ماجه (1752)، وأبوداود الطيالسي (2707) وصحّحه ابن حبان (3428) كلهم من حديث سعد أبي مجاهد الطائي (قال ابن ماجه: وكان ثقة) عن أبي مدلة (قال ابن ماجه: وكان ثقة) عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب العدل في القضاء","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (3598), Ibn Majah (1752), and Abu Dawud al-Tayalisi (2707), and graded authentic (Sahih) by Ibn Hibban (3428).","chapter_en":"Justice in Judgement","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “There are three whose supplication is not rejected: the just ruler, the fasting person until he breaks his fast, and the supplication of the oppressed person, which is raised above the clouds and the gates of heaven are opened for it, and the Lord says: ‘By My Might, I will surely grant you victory, even if it is after some time.’”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":3598,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":1752},{"key":"tayalisi","label":"أبوداود الطيالسي","number":2707},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":3428},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":5179,"n":5175}],"full":1,"dr":1},{"num":6708,"demo":false,"sanad":"","matn":["عَنْ أَبِي أَيُّوبَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَدُ اللهِ مَعَ الْقَاضِي حِينَ يَقْضِي، وَيَدُ اللَّهِ مَعَ الْقَاسِمِ حِينَ يَقْسِمُ."],"takhrij":"حسن: رواه أحمد (23511) عن علي بن إسحاق، أخبرنا عبدالله، أخبرنا ابن لهيعة، عن عبيدالله بن أبي جعفر، حدثه عن عمرو بن الأسود، عن أبي أيوب فذكره.","grade":"حسن","chapter_ar":"باب العدل في القضاء","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (23511). His saying, “The hand of Allah is with the judge,” means when he judges with justice.","chapter_en":"Justice in Judgement","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Ayyub said: The Messenger of Allah ﷺ said: “The hand of Allah is with the judge when he judges, and the hand of Allah is with the distributor when he distributes.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":23511,"n":23511,"lafz":true}],"full":1,"dr":1},{"num":6709,"demo":false,"sanad":"","matn":["عَنْ ابْنِ مَسْعُودٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ حَسَدَ إِلاَّ فِي اثْنَتَيْنِ: رَجُلٌ آتَاهُ اللَّهُ مَالاً، فَسَلَّطَهُ عَلَى هَلَكَتِهِ فِي الْحَقِّ، وَآخَرُ آتَاهُ اللَّهُ حِكْمَةً فَهْوَ يَقْضِي بِهَا وَيُعَلِّمُهَا."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7141)، ومسلم في صلاة المسافرين وقصرها (816) كلاهما من طريق إسماعيل، عن قيس، عن عبدالله ابن مسعود فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل من أوتي الحكمة فقضى بها","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7141) and Muslim (816).","chapter_en":"The virtue of one who is granted wisdom and judges by it","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Ibn Masʿud said: The Messenger of Allah ﷺ said: “There is no envy except in two cases: a man whom Allah has given wealth and empowered him to spend it entirely in the cause of truth, and a man whom Allah has given wisdom and he judges by it and teaches it.”"]},"buhuth":{"en":["Al-Hafiz (Ibn Hajar) said: “In this hadith, there is an encouragement to assume the position of judgeship for whoever meets its conditions, is strong enough to implement the truth, and finds helpers for it, because it involves enjoining what is right, assisting the oppressed, delivering rights to those entitled to them, restraining the hand of the oppressor, and making peace between people. All of these are acts of drawing near to Allah. For this reason, it was undertaken by the Prophets and after them by the Rightly Guided Caliphs. Hence, they agreed that it is a communal obligation (Fard Kifayah), because the affairs of people cannot be set straight without it.” Fath al-Bari (13/121)."]},"intro":{"ar":["قال اللّٰه تعالى: ( يُؤْتَى الْحِكْمَةَ مَن يَشَاءُ ۚ وَمَن يُؤْتَ الْحِكْمَةَ فَقَدْ أُوتِيَ خَيْرًا كَثِيرًا ) [البقرة: ٢٦٩]"],"en":["Allah the Exalted said: “He gives wisdom to whom He wills, and whoever has been given wisdom has certainly been given much good.” [Surat al-Baqarah: 269]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7141,"lafz":true},{"key":"muslim","label":"مسلم","number":816}],"full":1,"dr":1},{"num":6710,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن أَبِي أَوْفَى قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ مَعَ الْقَاضِي مَا لَمْ يَجُر، فَإِذَا جَارَ تَخَلَّى عَنْهُ، وَلَزِمَهُ الشَّيْطَانُ."],"takhrij":"حسن: رواه الترمذي (1330)، وصحّحه ابن حبان (5062)، والحاكم (4/93) والبيهقي (10/88) كلهم من حديث عمرو بن عاصم قال: حدثنا عمران القطان، عن أبي إسحاق الشيباني، عن عبدالله بن أبي أوفى فذكره. واللفظ للترمذي واختصره ابن حبان.","grade":"حسن","chapter_ar":"باب أن الله مع القاضي العدل، فإذا جار تخلّى عنه","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1330) who graded it Hasan, and authenticated (Sahih) by Ibn Hibban (5062), al-Hakim (4/93), and al-Bayhaqi (10/88).","chapter_en":"Indeed, Allah is with the just judge, but if he acts unjustly, Allah leaves him","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullah ibn Abi Awfa said: The Messenger of Allah ﷺ said: “Indeed, Allah is with the judge as long as he does not tyrannize. If he acts unjustly, Allah leaves him and the Devil stays with him.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1330,"lafz":true},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":5062},{"key":"hakim","label":"الحاكم","number":93},{"key":"kubrabayhaqi","label":"البيهقي","number":88},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":20451,"n":20609}],"full":1,"dr":1},{"num":6711,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عمرو قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَعْنَةُ اللَّهِ عَلَى الرَّاشِي وَالْمُرْتَشِي."],"takhrij":"حسن: رواه أبوداود (3850)، والترمذي (1337)، وابن ماجه (2313)، وأحمد (6532)، وابن الجارود (586)، وصحّحه ابن حبان (5077)، والحاكم (4/102-103)، والبيهقي (10/138-139) كلهم من حديث ابن أبي ذئب، عن خاله الحارث بن عبدالرحمن، عن أبي سلمة، عن عبدالله بن عمرو فذكره.","grade":"حسن","chapter_ar":"باب التغليظ من قبول الرشوة في الحكم","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3580), al-Tirmidhi (1337), and Ibn Majah (2313). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"The severe warning against accepting bribes in judgment","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr said: The Messenger of Allah ﷺ said: “The curse of Allah is upon the one who offers a bribe and the one who takes it.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3580,"lafz":true,"n":3504},{"key":"tirmidhi","label":"الترمذي","number":1337,"n":1074},{"key":"ibnmajah","label":"ابن ماجه","number":2313},{"key":"abudawud","label":"ابو داود","number":3850},{"key":"ahmad","label":"احمد","number":6532,"n":6531},{"key":"sh13071","label":"ابن الجارود","number":586},{"key":"ibnhibban","label":"ابن حبان","number":5077}],"full":1,"dr":1},{"num":6712,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ لَعَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الرَّاشِي وَالْمُرْتَشِي فِي الْحُكْمِ."],"takhrij":"حسن: رواه الترمذي (1336)، وأحمد (9023)، وابن الجارود (585) وصحّحه ابن حبان (5076) والحاكم (4/103) كلهم من حديث عمر بن أبي سلمة، عن أبيه، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب التغليظ من قبول الرشوة في الحكم","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1336), Ahmad (9023), and Ibn al-Jarud (585), and authenticated (Sahih) by Ibn Hibban (5076).","chapter_en":"The severe warning against accepting bribes in judgment","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ cursed the one who offers a bribe and the one who takes it in judgment."]},"buhuth":{"en":["His saying: “‘al-Rashi’ (the briber) is the giver, and ‘al-Murtashi’ (the bribed) is the taker. The punishment only applies to both of them together when they are equal in intent and will, meaning the giver offers the bribe to obtain something false or to commit an injustice. However, if he gives it to reach a right or to fend off an injustice from himself, then he is not included in this threat.” This was mentioned by al-Khattabi."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1336,"lafz":true},{"key":"sh13071","label":"ابن الجارود","number":585},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":5076,"n":2885},{"key":"ahmad","label":"مسند الإمام أحمد","number":9023,"n":9023}],"full":1,"dr":1},{"num":6713,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ وُلِّيَ الْقَضَاءَ فَقَدْ ذُبِحَ بِغَيْرِ سِكِّينٍ."],"takhrij":"حسن: رواه أبوداود (3571)، والترمذي (1325)، والدارقطني (4/204)، والبيهقي (10/96) كلهم من طريق فضيل بن سليمان، عن عمرو بن أبي عمرو مولى المطلب، عن سعيد المقبري، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب الترهيب من تولى القضاء لمن لا يثق بنفسه","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3571), and al-Tirmidhi (1325) who graded it Hasan, al-Daraqutni (4/204), and al-Bayhaqi (10/96).","chapter_en":"Warning against assuming judgeship for one who does not trust himself","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever is appointed as a judge has been slaughtered without a knife.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبوداود","number":3571,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1325},{"key":"sh9771","label":"الدارقطني","number":204,"n":207},{"key":"kubrabayhaqi","label":"البيهقي","number":96,"n":149},{"key":"sh9771","label":"سنن الدارقطني","number":4462,"n":4474},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":20220,"n":20678}],"full":1,"dr":1},{"num":6714,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ الْعَاصِ، أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ إِذَا حَكَمَ الْحَاكِمُ فَاجْتَهَدَ ثُمَّ أَصَابَ فَلَهُ أَجْرَانِ، وَإِذَا حَكَمَ فَاجْتَهَدَ ثُمَّ أَخْطَأَ فَلَهُ أَجْرٌ."],"takhrij":"متفق عليه: رواه البخاري في الاعتصام بالكتاب والسنة (7352) ومسلم في الأقضية (15:1716) كلاهما من طريق يزيد بن عبدالله بن أسامة ابن الهاد، عن محمد بن إبراهيم ابن الحارث، عن بُسر بن سعيد، عن أبي قيس مولى عمرو بن العاص، عن عمرو بن العاص فذكره.","grade":"متفق عليه","chapter_ar":"باب في القاضي يخطئ","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari in the Chapter of Adherence to the Book and Sunnah (7352) and Muslim in the Chapter of Judgments (1716:15).","chapter_en":"Regarding the judge who makes a mistake","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["ʿAmr ibn al-ʿAs narrated that he heard the Messenger of Allah ﷺ saying: “If a judge passes judgment having striven to reach the correct decision (ijtihad) and is correct, he will have a double reward; and if he passes judgment having striven to reach the correct decision and makes a mistake, he will have a single reward.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري في الاعتصام بالكتاب والسنة","number":7352,"lafz":true},{"key":"muslim","label":"مسلم في الأقضية","number":1716},{"key":"muslim","label":"مسلم في الاقضيه","number":15}],"full":1,"dr":1},{"num":6715,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا حَكَمَ الْحَاكِمُ فَاجْتَهَدَ فَأَصَابَ فَلَهُ أَجْرَانِ وَإِذَا حَكَمَ فَأَخْطَأَ فَلَهُ أَجْرٌ وَاحِدٌ."],"takhrij":"صحيح: رواه الترمذي (1326)، والنسائي (5381)، وابن الجارود (996)، وصحّحه ابن حبان (5060)، والدارقطني (4/204)، والبيهقي (10/119) كلهم من حديث عبدالرزاق، قال:أخبرنا معمر، عن سفيان الثوري، عن يحيى بن سعيد، عن أبي بكر بن عمرو بن حزم، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب في القاضي يخطئ","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1326) who graded it Hasan, al-Nasa’i (5381), Ibn al-Jarud (996), and authenticated (Sahih) by Ibn Hibban (5060).","chapter_en":"Regarding the judge who makes a mistake","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “If a judge passes judgment having striven to reach the correct decision and is correct, he will have a double reward; and if he passes judgment and makes a mistake, he will have a single reward.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1326,"lafz":true},{"key":"nasai","label":"النسائي","number":5381},{"key":"sh13071","label":"ابن الجارود","number":996},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":5060},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":720,"n":720}],"full":1,"dr":1},{"num":6716,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الحُصيب عَنْ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْقُضَاةُ ثَلاَثَةٌ، واحد فِي الْجَنَّةِ، واثنان فِي النَّارِ، فأما الَّذِي فِي الْجَنَّةِ فَرَجُلٌ عرف الْحَقَّ فَقَضَى بِهِ، وَرَجُلٌ عرف الْحَقَّ فجار فِي الْحُكْمِ فَهُوَ فِي النَّارِ، وَرَجُلٌ قَضَى لِلنَّاسِ عَلَى جَهْلٍ فَهُوَ فِي النَّارِ."],"takhrij":"حسن: رواه أبوداود (3573)، وابن ماجه (2315)، والطحاوي في مشكله (55)، والبيهقي (10/116) كلهم من حديث خلف بن خليفة، عن أبي هاشم، عن ابن بريدة، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب في القاضي يخطئ","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3573), Ibn Majah (2315), al-Tahawi in Mushkil al-Athar (55), and al-Bayhaqi (10/116).","chapter_en":"Regarding the judge who makes a mistake","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Buraydah ibn al-Husayb narrated that the Prophet ﷺ said: “Judges are of three types: one will be in Paradise and two in the Fire. As for the one in Paradise, he is a man who knew the truth and judged according to it. A man who knew the truth but acted unjustly in his judgment will be in the Fire. And a man who judged for the people out of ignorance will be in the Fire.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبوداود","number":3573,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2315},{"key":"sh22547","label":"الطحاوي في مشكله","number":55},{"key":"kubrabayhaqi","label":"البيهقي","number":116}],"full":1,"dr":1},{"num":6717,"demo":false,"sanad":"","matn":["عَبْدُ الرَّحْمَنِ بْنُ سَمُرَةَ، قَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَا عَبْدَ الرَّحْمَنِ بْنَ سَمُرَةَ لاَ تَسْأَلِ الإِمَارَةَ، فَإِنَّكَ إِنْ أُوتِيتَهَا عَنْ مَسْأَلَةٍ وُكِلْتَ إِلَيْهَا، وَإِنْ أُوتِيتَهَا مِنْ غَيْرِ مَسْأَلَةٍ أُعِنْتَ عَلَيْهَا."],"takhrij":"متفق عليه: رواه البخاري في الأيمان والنذور (6622) ومسلم في الأيمان (1652) كلاهما من حديث جـريز بن حازم، حدثنا الحـسن، حدثنا عبـد الرحمن بن سمرة فذكره.","grade":"متفق عليه","chapter_ar":"باب من ولي القضاء بدون طلب منه","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6622) and Muslim (1652).","chapter_en":"One who is appointed to judgeship without requesting it","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["ʿAbd al-Rahman ibn Samurah said: The Prophet ﷺ said: “O ʿAbd al-Rahman ibn Samurah, do not ask for leadership, for if you are given it as a result of asking, you will be left to deal with it alone; but if you are given it without asking, you will be helped in it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6622,"lafz":true},{"key":"muslim","label":"مسلم","number":1652}],"full":1},{"num":6718,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَرَادَ اللَّهُ بِالأَمِيرِ خَيْرًا جَعَلَ لَهُ وَزِيرَ صِدْقٍ إِنْ نَسِيَ ذَكَّرَهُ وَإِنْ ذَكَرَ أَعَانَهُ وَإِذَا أَرَادَ اللَّهُ بِهِ غَيْرَ ذَلِكَ جَعَلَ لَهُ وَزِيرَ سُوءٍ إِنْ نَسِيَ لَمْ يُذَكِّرْهُ وَإِنْ ذَكَرَ لَمْ يُعِنْهُ."],"takhrij":"صحيح: رواه أبو داود (2932) واللفظ له، والنسائي (4204) وأحمد (24414) وابن حبان (4494) والبيهقي (10/111-112) كلهم من طرق عن القاسم بن محمد، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب من ولي القضاء بدون طلب منه","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2932) and the wording is his, al-Nasa’i (4204), Ahmad (24414), and Ibn Hibban (4494).","chapter_en":"One who is appointed to judgeship without requesting it","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["ʿAishah said: The Messenger of Allah ﷺ said: “If Allah intends good for a leader, He appoints for him a truthful minister (advisor); if he forgets, he reminds him, and if he remembers, he helps him. But if Allah intends otherwise for him, He appoints for him an evil minister; if he forgets, he does not remind him, and if he remembers, he does not help him.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2932,"lafz":true},{"key":"nasai","label":"النسائي","number":4204},{"key":"ahmad","label":"مسند الإمام أحمد","number":24414,"n":24414},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4517,"n":4513},{"key":"ibnhibban","label":"ابن حبان","number":4494}],"full":1,"dr":1,"rep":[7706]},{"num":6719,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّهَا قَالَتْ: كَانَ عُتْبَةُ بْنُ أَبِي وَقَّاصٍ، عَهِدَ إِلَى أَخِيهِ سَعْدِ بْنِ أَبِي وَقَّاصٍ، أَنَّ ابْنَ وَلِيدَةِ زَمْعَةَ مِنِّي، فَاقْبِضْهُ إِلَيْكَ، قَالَتْ: فَلَمَّا كَانَ عَامُ الْفَتْحِ أَخَذَهُ سَعْدٌ. وَقَالَ: ابْنُ أَخِي. قَدْ كَانَ عَهِدَ إِلَى فِيهِ. فَقَامَ إِلَيْهِ عَبْدُ بْنُ زَمْعَةَ فَقَالَ: أَخِي. وَابْنُ وَلِيدَةِ أَبِي. وُلِدَ عَلَى فِرَاشِهِ. فَتَسَاوَقَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ سَعْدٌ: يَا رَسُولَ اللَّهِ. ابْنُ أَخِي، قَدْ كَانَ عَهِدَ إليّ فِيهِ. وَقَالَ عَبْدُ بْنُ زَمْعَةَ: أَخِي. وَابْنُ وَلِيدَةِ أَبِي. وُلِدَ عَلَى فِرَاشِهِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : هُوَ لَكَ يَا عَبْدُ بْنَ زَمْعَةَ ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : الْوَلَدُ لِلْفِرَاشِ وَلِلْعَاهِرِ الْحَجَرُ ثُمَّ قَالَ لِسَوْدَةَ بِنْتِ زَمْعَةَ: احْتَجِبِي مِنْهُ لِمَا رَأَى مِنْ شَبَهِهِ بِعُتْبَةَ بن أَبِي وَقَّاصٍ. قَالَتْ: فَمَا رَآهَا حَتَّى لَقِيَ اللَّهَ عَزَّ وَجَلَّ."],"takhrij":"متفق عليه: رواه مالك في الأقضية (20) عن ابن شهاب، عن عروة بن الزبير، عن عائشة، فذكرته.","grade":"متفق عليه","chapter_ar":"باب حكم القاضي لا يُحِلّ حراماً، ولا يُحَرِّمُ حلالاً","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (20), al-Bukhari (7182), and Muslim (1457:36).","chapter_en":"The judge’s ruling does not make a forbidden thing lawful, nor does it make a lawful thing forbidden","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["ʿAishah said: ʿUtbah ibn Abi Waqqas entrusted his brother, Saʿd ibn Abi Waqqas, saying, “The son of the slave-girl of Zamʿah is my son, so take custody of him.” She said: In the year of the Conquest (of Makkah), Saʿd took him and said, “He is my nephew; my brother entrusted him to me.” ʿAbd ibn Zamʿah stood up and said, “He is my brother and the son of my father’s slave-girl, born on his bed.” They both rushed to the Messenger of Allah ﷺ. Saʿd said, “O Messenger of Allah ﷺ! He is my nephew; my brother entrusted him to me.” And ʿAbd ibn Zamʿah said, “He is my brother and the son of my father’s slave-girl, born on his bed.” The Messenger of Allah ﷺ said, “He is for you, O ʿAbd ibn Zamʿah.” Then the Messenger of Allah ﷺ said, “The child belongs to the bed (marriage), and for the adulterer is the stone.” Then he said to Sawdah bint Zamʿah, “Observe hijab before him,” due to the resemblance he saw in him to ʿUtbah ibn Abi Waqqas. She said: He never saw her until he met Allah, the Mighty and Sublime."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":20,"lafz":true},{"key":"bukhari","label":"البخاري","number":7182},{"key":"muslim","label":"مسلم","number":36}],"full":1,"dr":1},{"num":6720,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّمَا أَنَا بَشَرٌ، وَإِنَّكُمْ تَخْتَصِمُونَ إليّ، فلعل بَعْضَكُمْ أَنْ يَكُونَ أَلْحَنَ بِحُجَّتِهِ مِنْ بَعْضٍ، فَأَقْضِي لَهُ على نَحْوَ مَا أَسْمَعُ مِنْهُ، فَمَنْ قَضَيْتُ لَهُ بشيء مِنْ حَقِّ أَخِيهِ، فَلاَ يأخذن مِنْهُ شَيْئًا، فَإِنَّمَا أَقْطَعُ لَهُ قِطْعَةً مِنَ النَّارِ."],"takhrij":"متفق عليه: رواه مالك في الأقضية (1) عن هشام بن عروة، عن أبيه، عن زينب بنت أبي سلمة، عن أم سلمة، فذكرته.","grade":"متفق عليه","chapter_ar":"باب حكم القاضي لا يُحِلّ حراماً، ولا يُحَرِّمُ حلالاً","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (1), al-Bukhari (7169), and Muslim (1713:4).","chapter_en":"The judge’s ruling does not make a forbidden thing lawful, nor does it make a lawful thing forbidden","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet ﷺ, narrated that the Messenger of Allah ﷺ said: “I am only a human being, and you bring your disputes to me. Perhaps some of you are more eloquent in presenting their argument than others, so I judge in his favor based on what I hear from him. Therefore, if I judge in anyone’s favor concerning something that belongs to his brother, he must not take any of it, for I am only cutting out for him a piece of the Fire.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":1,"lafz":true},{"key":"bukhari","label":"البخاري","number":7169},{"key":"muslim","label":"مسلم","number":4}],"full":1,"dr":1},{"num":6721,"demo":false,"sanad":"","matn":["عن أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخْبَرَتْهَا عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ سَمِعَ خُصُومَةً بِبَابِ حُجْرَتِهِ فَخَرَجَ إِلَيْهِمْ فَقَالَ إِنَّمَا أَنَا بَشَرٌ، وَإِنَّهُ يَأْتِينِي الْخَصْمُ، فَلَعَلَّ بَعْضَكُمْ أَنْ يَكُونَ أَبْلَغَ مِنْ بَعْضٍ، فَأَحْسِبُ أَنَّهُ صَادِقٌ فَأَقْضِي لَهُ بِذَلِكَ، فَمَنْ قَضَيْتُ لَهُ بِحَقِّ مُسْلِمٍ، فَإِنَّمَا هِيَ قِطْعَةٌ مِنَ النَّارِ، فَلْيَأْخُذْهَا أَوْ لِيَتْرُكْهَا."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7181)، ومسلم في الأقضية (5:1713) كلاهما من طريق ابن شهاب الزهري، أخبرني عروة بن الزبير، أن زينب ابنة أبي سلمة أخبرته، أن أم سلمة زوج النبي صلى الله عليه وسلم أخبرته، فذكرته.","grade":"متفق عليه","chapter_ar":"باب حكم القاضي لا يُحِلّ حراماً، ولا يُحَرِّمُ حلالاً","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7181) and Muslim (1713:5).","chapter_en":"The judge’s ruling does not make a forbidden thing lawful, nor does it make a lawful thing forbidden","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet ﷺ, narrated that the Messenger of Allah ﷺ heard a dispute at the door of his room, so he came out to them and said: “I am only a human being, and disputants come to me. Perhaps some of you are more eloquent than others, so I think he is truthful and judge in his favor accordingly. Therefore, if I judge in anyone’s favor concerning the right of a Muslim, it is only a piece of the Fire, so let him take it or leave it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7181,"lafz":true},{"key":"muslim","label":"مسلم","number":5}],"full":1},{"num":6722,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: جَاءَ رَجُلَانِ مِنَ الْأَنْصَارِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْتَصِمَانِ فِي مَوَارِيثَ بَيْنَهُمَا قَدْ دُرِسَتْ، لَيْسَ بَيْنَهُمَا بَيِّنَةٌ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّكُمْ تَخْتَصِمُونَ إِلَيَّ، وَإِنَّمَا أَنَا بَشَرٌ، وَلَعَلَّ بَعْضَكُمْ أَنْ يَكُونَ أَلْحَنُ بِحُجَّتِهِ مِنْ بَعْضٍ، وَإِنَّمَا أَقْضِي بَيْنَكُمْ عَلَى نَحْوِ مَا أَسْمَعُ مِنْكُمْ، فَمَنْ قَضَيْتُ لَهُ مِنْ أَخِيهِ شَيْئًا فَلَا يَأْخُذْهُ، فَإِنَّمَا أَقْطَعُ لَهُ قِطْعَةً مِنَ النَّارِ، يَأْتِي بِهِ إِسْطَامًا فِي عُنُقِهِ يَوْمَ الْقِيَامَةِ، قَالَ: فَبَكَى الرَّجُلَانِ، وَقَالَ كُلُّ وَاحِدٍ مِنْهُمَا: حَقِّي لِأَخِي، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ :أَمَا إِذْ فعلتما هَذَا، فَاذْهَبَا فَاقْتَسِمَا وتوخيا الْحَقَّ ثُمَّ اسْتَهِمَا، ثُمَّ يتحلل كُلُّ وَاحِدٍ مِنْكُمَا صَاحِبَهُ."],"takhrij":"حسن: رواه أبو داود (3585،3584) وأحمد (26717) والدارقطني (4/238-239) والحاكم (4/95) وابن الجارود (1000) والبيهقي (10/26) والطحاوي في مشكله (755) كلهم من حديث أسامة بن زيد، ثنا عبد الله بن رافع مولى أم سلمة، عن أم سلمة فذكرته واللفظ لأحمد. قال الحاكم: \"صحيح على شرط مسلم\".","grade":"حسن","chapter_ar":"باب حكم القاضي لا يُحِلّ حراماً، ولا يُحَرِّمُ حلالاً","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3584, 3585), Ahmad (26717), al-Daraqutni (4/238-239), and al-Hakim (4/95).","chapter_en":"The judge’s ruling does not make a forbidden thing lawful, nor does it make a lawful thing forbidden","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Umm Salamah said: Two men from the Ansar came to the Messenger of Allah ﷺ disputing over old inheritance shares between them that had worn away, and they had no proof. The Prophet ﷺ said: “You bring your disputes to me, and I am only a human being. Perhaps some of you are more eloquent in presenting their argument than others, and I only judge between you based on what I hear from you. Therefore, if I judge in anyone’s favor concerning something belonging to his brother, he must not take it, for I am only cutting out for him a piece of the Fire, which he will bring as a yoke around his neck on the Day of Resurrection.” She said: The two men wept, and each of them said, “My right is for my brother.” The Messenger of Allah ﷺ said: “Since you have done this, go and divide it, seek what is right, then draw lots, and let each of you declare the other free of blame.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3584,"lafz":true},{"key":"sh9771","label":"الدارقطني","number":238},{"key":"hakim","label":"الحاكم","number":95},{"key":"ahmad","label":"مسند الإمام أحمد","number":26717,"n":26717},{"key":"abudawud","label":"ابو داود","number":3585},{"key":"sh13071","label":"ابن الجارود","number":1000,"n":1037},{"key":"sh22547","label":"الطحاوي في مشكله","number":755}],"full":1,"dr":1},{"num":6723,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ كَانَتِ امْرَأَتَانِ مَعَهُمَا ابْنَاهُمَا، جَاءَ الذِّئْبُ فَذَهَبَ بِابْنِ إِحْدَاهُمَا فَقَالَتْ لِصَاحِبَتِهَا إِنَّمَا ذَهَبَ بِابْنِكِ. وَقَالَتِ الأُخْرَى إِنَّمَا ذَهَبَ بِابْنِكِ. فَتَحَاكَمَتَا إِلَى دَاوُدَ ـ عَلَيْهِ السَّلاَمُ ـ فَقَضَى بِهِ لِلْكُبْرَى، فَخَرَجَتَا عَلَى سُلَيْمَانَ بْنِ دَاوُدَ ـ عَلَيْهِمَا السَّلاَمُ ـ فَأَخْبَرَتَاهُ فَقَالَ ائْتُونِي بِالسِّكِّينِ أَشُقُّهُ بَيْنَهُمَا. فَقَالَتِ الصُّغْرَى لاَ تَفْعَلْ يَرْحَمُكَ اللَّهُ. هُوَ ابْنُهَا. فَقَضَى بِهِ لِلصُّغْرَى."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6769)، ومسلم في الأقضية (1720) كلاهما من حديث أبي الزناد، عن الأعرج، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب نقض حكم القاضي إذا ظهر الحق بخلافه","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6769) and Muslim (1720).","chapter_en":"Overturning the judge’s ruling if the truth appears contrary to it","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “There were two women who had their two sons with them. A wolf came and took away the son of one of them. She said to her companion, ‘It took your son!’ The other said, ‘No, it took your son!’ So they took their case to David (peace be upon him), and he judged in favor of the elder woman. They left and went to Solomon, the son of David (peace be upon them both), and informed him. He said, ‘Bring me a knife so I may cut him in half between the two of you.’ The younger woman said, ‘Do not do that, may Allah have mercy on you! It is her son.’ So he judged in favor of the younger woman.”"]},"buhuth":{"en":["Ibn al-Jawzi said: “Solomon deduced the truth when he saw the matter was ambiguous, and he did excellently. Both of them judged by independent reasoning (ijtihad), because if David had judged based on a direct textual revelation, it would not have been permissible for Solomon to judge contrary to it.” Fath al-Bari (6/465)."]},"intro":{"ar":["قال اللّٰه تعالى: ﴿وَدَاوُودَ وَسُلَيْمَانَ إِذْ يَحْكُمَانِ فِي الْحَرْثِ إِذْ نَفَشَتْ فِيهِ غَنَمُ الْقَوْمِ وَكُنَّا لِحُكْمِهِمْ شَاهِدِينَ ۝ فَفَهَّمْنَاهَا سُلَيْمَانَ ۚ وَكُلًّا آتَيْنَا حُكْمًا وَعِلْمًا﴾ [الأنبياء: ٧٨-٧٩]"],"en":["Allah the Exalted said: “And David and Solomon, when they gave judgment concerning the field when the sheep of a people pastured therein at night, and We were witness to their judgment. And We gave understanding of the case to Solomon, and to each of them We gave judgment and knowledge.” [Surat al-Anbiya’: 78-79]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6769,"lafz":true},{"key":"muslim","label":"مسلم","number":1720}],"full":1,"dr":1},{"num":6724,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّمَا أَنَا بَشَرٌ وَلَعَلَّ بَعْضَكُمْ أَنْ يَكُونَ أَلْحَنَ بِحُجَّتِهِ مِنْ بَعْضٍ فَمَنْ قَطَعْتُ لَهُ مِنْ حَقِّ أَخِيهِ قِطْعَةً فَإِنَّمَا أَقْطَعُ لَهُ قِطْعَةً مِنَ النَّارِ."],"takhrij":"حسن: رواه ابن ماجة (2318) وأحمد (8394) وصحّحه ابن حبان (5071) كلهم من حديث محمد بن عمرو، عن أبي سلمة بن عبد الرحمن، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب نقض حكم القاضي إذا ظهر الحق بخلافه","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2318) and Ahmad (8394), and authenticated (Sahih) by Ibn Hibban (5071).","chapter_en":"Overturning the judge’s ruling if the truth appears contrary to it","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “I am only a human being, and perhaps some of you are more eloquent in presenting their argument than others. Therefore, if I cut off a piece from the right of his brother for him, I am only cutting out for him a piece of the Fire.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2318,"lafz":true},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":5071},{"key":"ahmad","label":"مسند الإمام أحمد","number":8394,"n":8394},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2045,"n":2042}],"full":1,"dr":1},{"num":6725,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، قَالَ قُلْتُ يَا رَسُولَ اللَّهِ أَلاَ تَسْتَعْمِلُنِي قَالَ فَضَرَبَ بِيَدِهِ عَلَى مَنْكِبِي ثُمَّ قَالَ يَا أَبَا ذَرٍّ إِنَّكَ ضَعِيفٌ وَإِنَّهَا أَمَانَةٌ وَإِنَّهَا يَوْمَ الْقِيَامَةِ خِزْىٌ وَنَدَامَةٌ إِلاَّ مَنْ أَخَذَهَا بِحَقِّهَا وَأَدَّى الَّذِي عَلَيْهِ فِيهَا."],"takhrij":"صحيح: رواه مسلم في الإمارة (1825) عن عبد الملك بن شعيب بن الليث، حدثني أبي، شعيب بن الليث، حدثني الليث بن سعد، حدثني يزيد بن أبي حبيب، عن بكر بن عمرو، عن الحارث بن يزيد الحضرمي، عن ابن حُجيرة الأكبر، عن أبي ذر فذكره.","grade":"صحيح","chapter_ar":"باب في التوجيهات النبوية لمن يطلب القضاء","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1825).","chapter_en":"Regarding prophetic directives for whoever seeks judgeship","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Abu Dharr said: I said, “O Messenger of Allah ﷺ! Will you not appoint me to a position of authority?” He tapped my shoulder with his hand and then said: “O Abu Dharr, you are weak, and it is a trust, and on the Day of Resurrection it will be a cause of disgrace and regret, except for the one who takes it rightfully and fulfills the duty imposed upon him therein.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1825,"lafz":true}],"full":1,"rep":[7609]},{"num":6726,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ يَا أَبَا ذَرٍّ إِنِّي أَرَاكَ ضَعِيفًا وَإِنِّي أُحِبُّ لَكَ مَا أُحِبُّ لِنَفْسِي لاَ تَأَمَّرَنَّ عَلَى اثْنَيْنِ وَلاَ تَوَلَّيَنَّ مَالَ يَتِيمٍ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1826) من طرق عن عبد الله بن يزيد المقرئ، حدثنا سعيد بن أبي أيوب، عن عبيد الله بن أبي جعفر القرشي، عن سالم بن أبي سالم الجيشاني، عن أبيه، عن أبي ذر فذكره.","grade":"صحيح","chapter_ar":"باب في التوجيهات النبوية لمن يطلب القضاء","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1826). Al-Nawawi said: “This hadith is a great foundational principle for avoiding public offices, especially for one who is weak in carrying out the duties of that position. As for the disgrace and regret, it applies to whoever is not qualified for it, or was qualified but failed to act with justice; Allah the Exalted will disgrace and expose him on the Day of Resurrection, and he will regret what he neglected. However, whoever is qualified for leadership and acts with justice will have an immense virtue, as supported by numerous authentic hadiths.” End quote.","chapter_en":"Regarding prophetic directives for whoever seeks judgeship","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Abu Dharr narrated that the Messenger of Allah ﷺ said: “O Abu Dharr, I see that you are weak, and I love for you what I love for myself: do not rule over even two people, and do not manage the property of an orphan.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1826,"lafz":true}],"full":1,"dr":1,"rep":[7611,12653]},{"num":6727,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَجِدُونَ النَّاسَ كَإِبِلٍ مِائَةٍ لاَ يَجِدُ الرَّجُلُ فِيهَا رَاحِلَةً."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6498) ومسلم في فضائل الصحابة (2547) كلاهما من حديث الزهري، عن سالم بن عبدالله، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب لا فضل لشريف على مشروف في الدين","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6498) and Muslim (2547).","chapter_en":"No virtue for a person of noble status over a common person in the rulings of the religion","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ said: “People are like a hundred camels; a man can hardly find a single riding camel among them.”"]},"buhuth":{"en":["Al-Bayhaqi said (10/135): “This hadith may be interpreted to mean that people are equal in the rulings of religion; there is no preference therein for a person of noble status over a common person, nor for an elevated person over a lowly one, just like a hundred camels in which there is no riding camel—which is the submissive camel that is saddled and ridden, and the active participle ‘raahilah’ here functions as a passive participle meaning ridden. And it was said: its meaning is that people are many, but those who are pleasing among them are few, as stated by Ibn Battal, meaning those who carry the burdens of people and relieve their distress are few.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6498,"lafz":true,"n":6548},{"key":"muslim","label":"مسلم","number":2547}],"full":1,"dr":1},{"num":6728,"demo":false,"sanad":"","matn":["عن عَبْدِ الرَّحْمَنِ بن أَبِي بَكْرَةَ قَالَ كَتَبَ أَبُو بَكْرَةَ إِلَى ابْنِهِ وَكَانَ بِسِجِسْتَانَ بِأَنْ لاَ تَقْضِيَ بَيْنَ اثْنَيْنِ وَأَنْتَ غَضْبَانُ، فَإِنِّي سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ لاَ يَقْضِيَنَّ حَكَمٌ بَيْنَ اثْنَيْنِ وَهْوَ غَضْبَانُ."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7158)، ومسلم في الأقضية (16:1717) من طريق عبدالملك بن عمير، عن عبدالرحمن بن أبي بكرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب كراهة قضاء القاضي في حال الغضب","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7158) and Muslim (1717:16).","chapter_en":"The detestability of a judge passing judgment while angry","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["ʿAbd al-Rahman ibn Abi Bakrah said: Abu Bakrah wrote to his son—who was in Sijistan—instructing him not to judge between two people while being angry, saying, “For I heard the Prophet ﷺ saying: ‘A judge must not pass judgment between two people while he is angry.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7158,"lafz":true},{"key":"muslim","label":"مسلم","number":1717},{"key":"muslim","label":"مسلم في الاقضيه","number":16}],"full":1},{"num":6729,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ، زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا ابْتُلِيَ أَحَدُكُمْ بِالْقَضَاءِ بَيْنَ الْمُسْلِمِينَ فَلَا يَقْضِ وَهُوَ غَضْبَانُ، فَلْيُسَوِّ بَيْنَهُمْ بِالنَّظَرِ وَالْمَجْلِسِ وَالْإِشَارَةِ، وَلَا يَرْفَعْ صَوْتَهُ عَلَى أَحَدِ الْخَصْمَيْنِ."],"takhrij":"حسن: رواه الدارقطني (4/205) والبيهقي (10/135) وأبو يعلى (5867) والطبراني في الكبير (23/284) كلهم من طرق عن عباد بن كثير، عن أبي عبدالله، عن عطاء بن يسار، عن أم سلمة فذكرته. وبعضهم اختصره.","grade":"حسن","chapter_ar":"باب التسوية في النظر والإشارة","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by al-Daraqutni (4/205), al-Bayhaqi (10/135), Abu Yaʿla (5867), and Ishaq ibn Rahwayh (1846).","chapter_en":"Maintaining equality in gaze and gesturing","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet ﷺ, narrated that the Prophet ﷺ said: “If one of you is tested with judging between Muslims, he must not judge while he is angry, and he must treat them equally in his gaze, his seating arrangement, and his gesturing, and he must not raise his voice against one of the two disputants.”"]}},"tuhfa":{},"refs":[{"key":"sh9771","label":"الدارقطني","number":205,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":135},{"key":"sh12520","label":"أبو يعلى","number":5867},{"key":"sh13159","label":"إسحاق بن راهويه","number":1846}],"full":1,"dr":1},{"num":6730,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ، عَلَيْهِ السَّلاَمُ قَالَ بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْيَمَنِ قَاضِيًا فَقُلْتُ يَا رَسُولَ اللَّهِ تُرْسِلُنِي وَأَنَا حَدِيثُ السِّنِّ وَلاَ عِلْمَ لِي بِالْقَضَاءِ فَقَالَ إِنَّ اللَّهَ سَيَهْدِي قَلْبَكَ وَيُثَبِّتُ لِسَانَكَ فَإِذَا جَلَسَ بَيْنَ يَدَيْكَ الْخَصْمَانِ فَلاَ تَقْضِيَنَّ حَتَّى تَسْمَعَ مِنَ الآخَرِ كَمَا سَمِعْتَ مِنَ الأَوَّلِ فَإِنَّهُ أَحْرَى أَنْ يَتَبَيَّنَ لَكَ الْقَضَاءُ. قَالَ فَمَا زِلْتُ قَاضِيًا أَوْ مَا شَكَكْتُ فِي قَضَاءٍ بَعْدُ."],"takhrij":"حسن: رواه أبو داود (3582) واللفظ له، والترمذي (1331) والبيهقي (10/137) كلهم من طرق عن حنش، عن علي فذكره.","grade":"حسن","chapter_ar":"باب لا يقضي القاضي حتى يسمع من الخصمين","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3582) and the wording is his, al-Tirmidhi (1331), and al-Bayhaqi (10/137).","chapter_en":"A judge must not pass judgment until he hears from both disputants","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["ʿAli ibn Abi Talib said: The Messenger of Allah ﷺ sent me to Yemen as a judge. I said, “O Messenger of Allah ﷺ! You are sending me while I am young in age and have no knowledge of judging?” He said: “Indeed, Allah the Mighty and Sublime will guide your heart and make your tongue firm. When the two disputants sit before you, do not judge until you hear from the second one just as you heard from the first. For that is more likely to make the correct judgment clear to you.” ʿAli said: After that, I never ceased to be a judge, or I never doubted a judgment since."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3582,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1331},{"key":"kubrabayhaqi","label":"البيهقي","number":137},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":20487,"n":20645}],"full":1,"dr":1},{"num":6731,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، وَزَيْدِ بْنِ خَالِدٍ، أَنَّهُمَا أَخْبَرَاهُ أَنَّ رَجُلَيْنِ اخْتَصَمَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ أَحَدُهُمَا اقْضِ بَيْنَنَا بِكِتَابِ اللَّهِ. وَقَالَ الآخَرُ وَهْوَ أَفْقَهُهُمَا أَجَلْ يَا رَسُولَ اللَّهِ فَاقْضِ بَيْنَنَا بِكِتَابِ اللَّهِ، وَائْذَنْ لِي أَنْ أَتَكَلَّمَ. قَالَ تَكَلَّمْ. قَالَ إِنَّ ابْنِي كَانَ عَسِيفًا عَلَى هَذَا ـ قَالَ مَالِكٌ وَالْعَسِيفُ الأَجِيرُ ـ زَنَى بِامْرَأَتِهِ، فَأَخْبَرُونِي أَنَّ عَلَى ابْنِي الرَّجْمَ، فَافْتَدَيْتُ مِنْهُ بِمِائَةِ شَاةٍ وَجَارِيَةٍ لِي، ثُمَّ إِنِّي سَأَلْتُ أَهْلَ الْعِلْمِ فَأَخْبَرُونِي أَنَّ مَا عَلَى ابْنِي جَلْدُ مِائَةٍ وَتَغْرِيبُ عَامٍ، وَإِنَّمَا الرَّجْمُ عَلَى امْرَأَتِهِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَا وَالَّذِي نَفْسِي بِيَدِهِ لأَقْضِيَنَّ بَيْنَكُمَا بِكِتَابِ اللَّهِ، أَمَّا غَنَمُكَ وَجَارِيَتُكَ فَرَدٌّ عَلَيْكَ. وَجَلَدَ ابْنَهُ مِائَةً وَغَرَّبَهُ عَامًا، وَأُمِرَ أُنَيْسٌ الأَسْلَمِيُّ أَنْ يَأْتِيَ امْرَأَةَ الآخَرِ، فَإِنِ اعْتَرَفَتْ رَجَمَهَا، فَاعْتَرَفَتْ فَرَجَمَهَا."],"takhrij":"متفق عليه: رواه مالك في الحدود (6) عن ابن شهاب، عن عبيد الله بن عبد الله بن عتبة بن مسعود، عن أبي هريرة وزيد بن خالد الجهني، فذكراه.","grade":"متفق عليه","chapter_ar":"باب في ردّ الحكم إلى الكتاب والسنة معاً","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (6), al-Bukhari (6633, 6634), and Muslim (1697, 1698).","chapter_en":"Referring judgment back to both the Book and the Sunnah together","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["Abu Hurayrah and Zayd ibn Khalid al-Juhani narrated that they informed him that two men brought a dispute to the Messenger of Allah ﷺ. One of them said, “O Messenger of Allah ﷺ! Judge between us according to the Book of Allah.” The other, who was the wiser of the two, said, “Yes, O Messenger of Allah ﷺ, judge between us according to the Book of Allah, and permit me to speak.” He said, “Speak.” The man said, “My son was hired as a laborer by this man and he committed adultery with his wife. I was told that my son was to be stoned to death, so I ransomed him with one hundred sheep and a slave-girl of mine. Afterward, I asked the people of knowledge, and they informed me that my son is only to receive one hundred lashes and a year of exile, and they informed me that stoning is only for his wife.” The Messenger of Allah ﷺ said: “By the One in Whose Hand is my soul, I will surely judge between you according to the Book of Allah. As for your sheep and your slave-girl, they are to be returned to you.” Then he ordered his son to be lashed one hundred times and exiled for a year. He then commanded Unays al-Aslami to go to the wife of the other man, and if she confessed, to stone her. She confessed, so he stoned her."]},"intro":{"ar":["قال اللّٰه عز وجل: (يَأَيُّهَا الَّذِينَ ءَامَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُوْلِي الْأَمْرِ مِنْكُمْ فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرَدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنْتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا ) [النساء: ٥٩]","والمراد بالسنة: السنة الصحيحة الثابتة، وأما الضعيفة والمنكرة والموضوعة فلا يجوز الردّ إليها."],"en":["Allah the Mighty and Sublime said: “O you who have believed, obey Allah and obey the Messenger and those in authority among you. And if you disagree over anything, refer it back to Allah and the Messenger, if you should believe in Allah and the Last Day. That is the best way and best in result.” [Surat al-Nisa’: 59]","What is meant by the Sunnah is the authentic, established Sunnah; as for the weak (daʿif), rejected (munkar), and fabricated (mawdu’) narrations, it is not permissible to refer back to them."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":6,"lafz":true},{"key":"bukhari","label":"البخاري","number":6633},{"key":"muslim","label":"مسلم","number":1697}],"full":1,"dr":1},{"num":6732,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اللَّهُمَّ إِنِّي أُحَرِّجُ حَقَّ الضَّعِيفَيْنِ: الْيَتِيمِ وَالْمَرْأَةِ. وَفِي رِوَايَةِ: مال الضَّعِيفَيْنِ."],"takhrij":"حسن: رواه ابن ماجة (3678) وصحّحه ابن حبان (5565) والحاكم (1/63، 4/128) والبيهقي (10/134) وأحمد (9666) كلهم من حديث ابن عجلان، عن سعيد المقبري، عن أبي هريرة فذكره. قال الحاكم: \"صحيح على شرط مسلم\".","grade":"حسن","chapter_ar":"باب الحفاظ على حقوق الأيتام والنساء","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (3678), and authenticated (Sahih) by Ibn Hibban (5565), al-Hakim (4/128, 1/63), and Ahmad (9666).","chapter_en":"Safeguarding the rights of orphans and women","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":16,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “O Allah, I declare inviolable the right of the two weak ones: the orphan and the woman.” And in another narration: “the property of the two weak ones.”"]},"buhuth":{"en":["His saying: “‘Uharriju’ (I declare inviolable) the right of the two weak ones” means: I make their wealth forbidden to whoever oppresses them."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":3678,"lafz":true},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":5565},{"key":"hakim","label":"الحاكم","number":128,"n":210},{"key":"ahmad","label":"مسند الإمام أحمد","number":9666,"n":9759}],"full":1,"dr":1},{"num":6733,"demo":false,"sanad":"","matn":["عَنْ شُرَيْحِ بْنِ هَانِئٍ، عَنْ أَبِيهِ، هَانِئٍ أَنَّهُ لَمَّا وَفَدَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَمِعَهُ وَهُمْ يَكْنُونَ هَانِئًا أَبَا الْحَكَمِ فَدَعَاهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لَهُ إِنَّ اللَّهَ هُوَ الْحَكَمُ وَإِلَيْهِ الْحُكْمُ فَلِمَ تُكَنَّى أَبَا الْحَكَمِ. فَقَالَ إِنَّ قَوْمِي إِذَا اخْتَلَفُوا فِي شَىْءٍ أَتَوْنِي فَحَكَمْتُ بَيْنَهُمْ فَرَضِيَ كِلاَ الْفَرِيقَيْنِ. قَالَ مَا أَحْسَنَ مِنْ هَذَا فَمَا لَكَ مِنَ الْوُلْدِ. قَالَ لِي شُرَيْحٌ وَعَبْدُ اللَّهِ وَمُسْلِمٌ. قَالَ فَمَنْ أَكْبَرُهُمْ. قَالَ شُرَيْحٌ. قَالَ فَأَنْتَ أَبُو شُرَيْحٍ. فَدَعَا لَهُ وَلِوَلَدِهِ."],"takhrij":"صحيح: رواه النسائي (5387)، عن قتيبة قال: حدثنا يزيد وهو ابن المقدام بن شريح، عن أبيه، عن شريح بن هانئ، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب القضاء بالتحكيم","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (5387). Arbitration has been established in the matter of spouses (in marital discord), the compensation for hunting (while in Ihram), and the arbitration of Saʿd in the case of Banu Qurayzah.","chapter_en":"Passing judgment through arbitration","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":17,"content":{"translation":{"en":["Shurayh ibn Hani narrated on the authority of his father that when he came as a delegate to the Messenger of Allah ﷺ, the Prophet ﷺ heard them calling Hani by the kunyah (honorific nickname) ‘Abu al-Hakam’. So the Messenger of Allah ﷺ called him and said to him, “Indeed, Allah is the Judge (al-Hakam), and to Him belongs all judgment, so why are you called Abu al-Hakam?” He said, “When my people dispute over something, they come to me and I judge between them, and both parties are pleased.” He said, “How excellent this is! What do you have of children?” He replied, “I have Shurayh, ʿAbdullah, and Muslim.” He said, “Who is the eldest of them?” He replied, “Shurayh.” He said, “Then you are Abu Shurayh,” and he supplicated for him and his children."]},"buhuth":{"en":["Arbitration is permissible but not legally binding; rather, it is like a legal advisory for both parties—if they wish, they may accept it, and if they do not wish, they may resort to the ruler (ruling authority)."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":5387,"lafz":true,"n":5387}],"full":1,"dr":1},{"num":6734,"demo":false,"sanad":"","matn":["عَنْ وَائِلِ بْنِ حُجْرٍ قَالَ: إِنِّي لَقَاعِدٌ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ جَاءَ رَجُلٌ يَقُودُ آخَرَ بِنِسْعَةٍ فَقَالَ: يَا رَسُولَ اللَّهِ! هَذَا قَتَلَ أَخِي. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَقَتَلْتَهُ؟ قَالَ: نَعَمْ قَتَلْتُهُ. قَالَ: كَيْفَ قَتَلْتَهُ؟ قَالَ: كُنْتُ أَنَا وَهُوَ نتخبط مِنْ شَجَرَةٍ، فَسَبَّنِي فَأَغْضَبَنِي فَضَرَبْتُهُ بِالْفَأْسِ عَلَى قَرْنِهِ فَقَتَلْتُهُ. فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : هَلْ لَكَ مِنْ شيء تُؤَدِّيهِ عَنْ نَفْسِكَ؟ قَالَ: مَا لِي إِلاَّ كِسَائِي وَفَأْسِي. قَالَ: فَتَرَى قَوْمَكَ يَشْتَرُونَكَ؟ قَالَ: أَنَا أَهْوَنُ عَلَى قَوْمِي مِنْ ذَاكَ. فَرَمَى إِلَيْهِ بِنِسْعَتِهِ وَقَالَ: دُونَكَ صَاحِبَكَ فَانْطَلَقَ بِهِ الرَّجُلُ. فَلَمَّا ولّى قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنْ قَتَلَهُ فَهُوَ مِثْلُهُ فَرَجَعَ فَقَالَ: يَا رَسُولَ اللَّهِ إِنَّهُ بَلَغَنِي أَنَّكَ قُلْتَ: إِنْ قَتَلَهُ فَهُوَ مِثْلُهُ، وَأَخَذْتُهُ بِأَمْرِكَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَمَا تُرِيدُ أَنْ يَبُوءَ بِإِثْمِكَ وَإِثْمِ صَاحِبِكَ؟. قَالَ: يَا نَبِيَّ اللَّهِ، بَلَى. قَالَ: فَإِنَّ ذَاكَ كَذَاكَ قَالَ: فَرَمَى بِنِسْعَتِهِ وَخَلَّى سَبِيلَهُ."],"takhrij":"صحيح: رواه مسلم في القسامة (1680) عن عبيد الله بن معاذ العنبري، حدثنا أبي، حدثنا أبو يونس، عن سماك بن حرب، عن علقمة بن وائل، حدثه أن أباه حدثه فذكره.","grade":"صحيح","chapter_ar":"باب طلب الحاكم من الخصم العفو","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1680). His saying: “‘nisʿah’” refers to a rope made of leather strips. His saying: “‘natakhabat’” means: we were gathering ‘khabt’, which is tree leaves. His saying: “‘If he kills him, he will be just like him’” means: neither of them will hold any virtue or favor over the other because he has fully exacted his right from him—unlike the case if he were to pardon him, for then he would have the virtue, favor, immense reward in the Hereafter, and beautiful praise in this world.","chapter_en":"The judge requesting the disputant to grant a pardon","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["Wa’il ibn Hujr said: I was sitting with the Prophet ﷺ when a man came leading another man with a leather strap and said, “O Messenger of Allah ﷺ! This man killed my brother.” The Messenger of Allah ﷺ said, “Did you kill him?” He replied, “Yes, I killed him.” He asked, “How did you kill him?” He replied, “He and I were hitting a tree to shake down its leaves, then he insulted me and made me angry, so I struck him with the axe on his temple and killed him.” The Prophet ﷺ said to him, “Do you have anything to pay as blood money for yourself?” He replied, “I have nothing except my cloak and my axe.” He asked, “Do you think your people will ransom you?” He replied, “I am of less value to my people than that.” So the Prophet ﷺ threw his strap to the claimant and said, “Take your companion.” The man went away with him. When he turned back, the Messenger of Allah ﷺ said, “If he kills him, he will be just like him.” The man returned and said, “O Messenger of Allah ﷺ! It has reached me that you said, ‘If he kills him, he will be just like him,’ yet I took him by your command.” The Messenger of Allah ﷺ said, “Do you not want him to bear your sin and the sin of your companion (brother)?” He said, “O Prophet of Allah, yes indeed.” He said, “Then let it be so.” The man then threw away the strap and let him go his way."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1680,"lafz":true}],"full":1,"dr":1},{"num":6735,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ زَوْجَ، بَرِيرَةَ كَانَ عَبْدًا يُقَالُ لَهُ مُغِيثٌ كَأَنِّي أَنْظُرُ إِلَيْهِ يَطُوفُ خَلْفَهَا يَبْكِي، وَدُمُوعُهُ تَسِيلُ عَلَى لِحْيَتِهِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِعَبَّاسٍ يَا عَبَّاسُ أَلاَ تَعْجَبُ مِنْ حُبِّ مُغِيثٍ بَرِيرَةَ، وَمِنْ بُغْضِ بَرِيرَةَ مُغِيثًا. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَوْ رَاجَعْتِهِ. قَالَتْ يَا رَسُولَ اللَّهِ تَأْمُرُنِي قَالَ إِنَّمَا أَنَا أَشْفَعُ. قَالَتْ لاَ حَاجَةَ لِي فِيهِ."],"takhrij":"صحيح: رواه البخاري في الطلاق (5283) عن محمد، أخبرنا عبد الوهاب، حدثنا خالد، عن عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب شفاعة الحاكم","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5283).","chapter_en":"The intercession of the judge","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Ibn ʿAbbas said: The husband of Barirah was a slave called Mughith. It is as if I can see him walking behind her, weeping, with his tears flowing down his beard. The Prophet ﷺ said to ʿAbbas, “O ʿAbbas, are you not amazed by Mughith’s love for Barirah and Barirah’s hatred for Mughith?” Then the Prophet ﷺ said to her, “If only you would go back to him.” She said, “O Messenger of Allah ﷺ, are you commanding me?” He said, “I am only interceding.” She said, “I have no need for him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5283,"lafz":true}],"full":1,"rep":[6214]},{"num":6736,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ قَالَ: سَمِعْتُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ حَالَتْ شَفَاعَتُهُ دُونَ حَدٍّ مِنْ حُدُودِ اللَّهِ فَهُوَ مُضَادُّ لِلَّهِ فِي أَمْرِهِ."],"takhrij":"صحيح: رواه أبو داود (3597) وأحمد (5385) والحاكم (2/27) كلهم من طريق زهير بن معاوية، ثنا عمارة بن غزية، عن يحيى بن راشد قال: جلسنا لعبد الله بن عمر، فخرج إلينا فجلس فقال: سمعت رسول الله صلى الله عليه وسلم يقول: فذكر الحديث في سياق أطول وجاء فيه: ومن مات وعليه دين فليس بالدينار ولا بالدرهم ولكنها الحسنات والسيئات. ومن خاصم في باطل وهو يعلمه لم يزل في سخط الله حتى ينزع، ومن قال في مؤمن ما ليس فيه أسكنه الله ردغة الخبال حتى يخرج مما قال وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب شفاعة الحاكم","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3597), Ahmad (5385), and al-Hakim (2/27). And in it (the narration) it adds: “And whoever dies while owing a debt, it will not be paid with dinars or dirhams, but rather with good deeds and bad deeds. And whoever disputes in a falsehood while he knows it, he remains under the wrath of Allah until he desists. And whoever speaks about a believer that which is not true, Allah will lodge him in the mud of discharge (Radghat al-Khabal) until he retracts what he said.”","chapter_en":"The intercession of the judge","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Ibn ʿUmar said: I heard the Messenger of Allah ﷺ saying: “Whoever’s intercession prevents one of the prescribed punishments (hudud) of Allah from being executed, he has opposed Allah in His command.”"]},"buhuth":{"en":["His saying: “‘Whoever’s intercession prevents’” means: whoever has a prescribed punishment of Allah proven against him, and it has reached the ruler. However, before reaching the ruler, or in matters concerning human rights, it is permissible for the judge to intercede; rather, it is recommended for him to do so, even by spending wealth, just as the Prophet ﷺ used to do. It was said to ʿAli, when he interceded for a thief, “Do you intercede for a thief?” He replied, “Yes, that may be done as long as it has not reached the ruler. But if it has reached the ruler, then may Allah not forgive him if he forgives him.” Narrated by Ibn Abi Shaybah (28659). And on the authority of al-Zubayd ibn al-Salt, who said: I heard Abu Bakr al-Siddiq saying, “If I caught a drinker, I would prefer that Allah conceals him, and if I caught a thief, I would prefer that Allah conceals him.” Narrated by Ibn Abi Shaybah (28664)."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3597,"lafz":true},{"key":"hakim","label":"الحاكم","number":27},{"key":"ahmad","label":"مسند الإمام أحمد","number":5385,"n":5385}],"full":1,"dr":1},{"num":6737,"demo":false,"sanad":"","matn":["عَنْ بَهْزِ بْنِ حَكِيمِ بْنِ مُعَاوِيَةَ، عَنْ أَبِيهِ، عَنْ جَدِّهِ قَالَ: أَخَذَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَاسًا مِنْ قَوْمِي فِي تُهْمَةٍ فَحَبَسَهُمْ، فَجَاءَ رَجُلٌ مِنْ قَوْمِي إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَخْطُبُ، فَقَالَ: يَا مُحَمَّدُ عَلَامَ تَحْبِسُ جِيرَتِي؟ فَصَمَتَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْهُ فَقَالَ: إِنَّ نَاسًا لَيَقُولُونَ إِنَّكَ تَنْهَى عَنِ الشَّرِّ، وَتَسْتَخْلِي بِهِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا يَقُولُ؟ قَالَ: فَجَعَلْتُ أَعْرِضُ بَيْنَهُمَا بِالْكَلَامِ مَخَافَةَ أَنْ يَسْمَعَهَا، فَيَدْعُوَ عَلَى قَوْمِي دَعْوَةً، لَا يُفْلِحُونَ بَعْدَهَا أَبَدًا، فَلَمْ يَزَلِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِهِ حَتَّى فَهِمَهَا فَقَالَ: قَدْ قَالُوهَا أَوْ قَائِلُهَا مِنْهُمْ، وَاللهِ لَوْ فَعَلْتُ لَكَانَ عَلَيَّ، وَمَا كَانَ عَلَيْهِمْ خَلُّوا لَهُ عَنْ جِيرَانِهِ."],"takhrij":"حسن: رواه أبو داود (3630)، والترمذي (1417)، والنسائي (4875)، وأحمد (20019)، والحاكم (1/125)، والبيهقي (6/53) كلهم من حديث معمر، عن بهز بن حكيم بن معاوية، عن أبيه، عن جده قال: فذكره. واختصره البعض.","grade":"حسن","chapter_ar":"باب ما جاء في اتخاذ السجن","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3630), al-Tirmidhi (1417), al-Nasa’i (4875), and Ahmad (20019).","chapter_en":"What has been narrated regarding establishing a prison","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":20,"content":{"translation":{"en":["Bahz ibn Hakim ibn Muʿawiyah narrated on the authority of his father, from his grandfather, who said: The Prophet ﷺ detained some people from my tribe on suspicion and imprisoned them. A man from my tribe came to the Prophet ﷺ while he was delivering a sermon and said, “O Muhammad! On what grounds are you detaining my neighbors?” The Prophet ﷺ remained silent. The man then said, “Some people say that you forbid evil but practice it in private!” The Prophet ﷺ said, “What is he saying?” The narrator said: I began to obscure the words between them, fearing that the Prophet ﷺ would hear it and supplicate against my tribe a supplication from which they would never prosper. But the Prophet ﷺ kept questioning him until he understood it, so he said, “Have they really said it, or is the one saying it from among them? By Allah, if I were to do that, the sin would be upon me and not upon them. Release his neighbors for him.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3630,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1417},{"key":"nasai","label":"النسائي","number":4875},{"key":"ahmad","label":"مسند الإمام أحمد","number":20019,"n":20019}],"full":1,"dr":1,"rep":[6922]},{"num":6738,"demo":false,"sanad":"","matn":["عن عُمَرَ بن الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ يَقُولُ إِنَّ أُنَاسًا كَانُوا يُؤْخَذُونَ بِالْوَحْىِ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَإِنَّ الْوَحْىَ قَدِ انْقَطَعَ، وَإِنَّمَا نَأْخُذُكُمُ الآنَ بِمَا ظَهَرَ لَنَا مِنْ أَعْمَالِكُمْ، فَمَنْ أَظْهَرَ لَنَا خَيْرًا أَمِنَّاهُ وَقَرَّبْنَاهُ، وَلَيْسَ إِلَيْنَا مِنْ سَرِيرَتِهِ شَىْءٌ، اللَّهُ يُحَاسِبُهُ فِي سَرِيرَتِهِ، وَمَنْ أَظْهَرَ لَنَا سُوءًا لَمْ نَأْمَنْهُ وَلَمْ نُصَدِّقْهُ، وَإِنْ قَالَ إِنَّ سَرِيرَتَهُ حَسَنَةٌ."],"takhrij":"صحيح: رواه البخاري في الشهادات (2641) عن الحكم بن نافع، أخبرنا شعيب، عن الزهري، قال: حدثني حميد بن عبد الرحمن بن عوف، أن عبد الله بن عتبة، قال: سمعت عمر بن الخطاب، قال: فذكره.","grade":"صحيح","chapter_ar":"باب اشتراط العدالة في الشهادة","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2641).","chapter_en":"The condition of upright character (ʿadalah) in testimony","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["ʿUmar ibn al-Khattab said: People used to be judged by the revelation during the lifetime of the Messenger of Allah ﷺ, but now the revelation has ceased. We judge you now only by what is manifest to us of your deeds. Whoever shows us good, we will trust him and bring him close, and we have nothing to do with his inner secrets; Allah will call him to account for his inner secrets. But whoever shows us evil, we will not trust him and we will not believe him, even if he claims that his inner secret is good."]},"intro":{"ar":["قال اللّٰه تعالى: ( وَأَشْهِدُوا ذَوَيْ عَدْلٍ مِنْكُمْ وَأَقِيمُوا الشَّهَادَةَ لِلَّهِ ذَٰلِكُمْ يُوعَظُ بِهِ مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ) [الطلاق: ٢ ]","وقال تعالى: (يَأَيُّهَا الَّذِينَ ءَامَنُوا شَهَادَةُ بَيْنِكُمْ إِذَا حَضَرَ أَحَدَكُمُ الْمَوْتُ حِينَ الْوَصِيَّةِ اثْنَانِ ذَوَا عَدْلٍ مِنْكُمْ ) [المائدة: ١٠٦ ]"],"en":["Allah the Exalted said: “And take to witness two just men from among you and establish the testimony for [the acceptance of] Allah. That is instructed to whoever should believe in Allah and the Last Day. And whoever fears Allah - He will make for him a way out.” [Surat al-Talaq: 2]","And the Exalted said: “O you who have believed, testimony [should be taken] among you when death approaches one of you at the time of bequest - two just men from among you.” [Surat al-Ma’idah: 106]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2641,"lafz":true}],"full":1},{"num":6739,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ مُرَّ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِجَنَازَةٍ، فَأَثْنَوْا عَلَيْهَا خَيْرًا فَقَالَ وَجَبَتْ. ثُمَّ مُرَّ بِأُخْرَى فَأَثْنَوْا عَلَيْهَا شَرًّا ـ أَوْ قَالَ غَيْرَ ذَلِكَ ـ فَقَالَ وَجَبَتْ. فَقِيلَ يَا رَسُولَ اللَّهِ، قُلْتَ لِهَذَا وَجَبَتْ، وَلِهَذَا وَجَبَتْ، قَالَ شَهَادَةُ الْقَوْمِ، الْمُؤْمِنُونَ شُهَدَاءُ اللَّهِ فِي الأَرْضِ."],"takhrij":"متفق عليه: رواه البخاري في الشهادات (2642)، ومسلم في الجنائز (60:949) كلاهما من طريق حماد بن زيد – وزاد مسلم غيره – عن ثابت، عن أنس، فذكره، والسياق للبخاري ولم يذكر مسلم لفظه وإنما أحال على رواية ابن علية، عن عبد العزيز بن صهيب، عن أنس، فذكره بنحوه وبسياق أطول، وفيه أن الذي سأل النبي صلى الله عليه وسلم هو عمر بن الخطاب رضي الله عنه.","grade":"متفق عليه","chapter_ar":"باب المؤمنون شهداء الله في الأرض","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2642) and Muslim (949:60), and the wording is that of al-Bukhari.","chapter_en":"The believers are the witnesses of Allah on earth","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Anas said: A funeral procession passed by the Prophet ﷺ and the people praised the deceased. He said, “It has become binding.” Then another procession passed by and they spoke ill of the deceased—or said something else—and he said, “It has become binding.” It was said, “O Messenger of Allah ﷺ, you said ‘It has become binding’ for this one and ‘It has become binding’ for that one?!” He said, “It is the testimony of the people; the believers are the witnesses of Allah on earth.”"]},"intro":{"ar":["قال اللّٰه تعالى: (وَكَذَٰلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا) [البقرة: ١٤٣]","وقال تعالى: (هُوَ سَمَّاكُمُ الْمُسْلِمِينَ مِنْ قَبْلُ وَفِي هَٰذَا لِيَكُونَ الرَّسُولُ شَهِيدًا عَلَيْكُمْ وَتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ) [الحج: ٧٨]"],"en":["Allah the Exalted said: “And thus we have made you a just community that you will be witnesses over the people and the Messenger will be a witness over you.” [Surat al-Baqarah: 143]","And the Exalted said: “He named you Muslims before and in this [revelation] that the Messenger may be a witness over you and you may be witnesses over the people.” [Surat al-Hajj: 78]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2642,"lafz":true},{"key":"muslim","label":"مسلم","number":949},{"key":"muslim","label":"مسلم في الجنائز","number":60}],"full":1},{"num":6740,"demo":false,"sanad":"","matn":["عن عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْرُكُمْ قَرْنِي، ثُمَّ الَّذِينَ يَلُونَهُمْ، ثُمَّ الَّذِينَ يَلُونَهُمْ. قَالَ عِمْرَانُ لاَ أَدْرِي أَذَكَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْدُ قَرْنَيْنِ أَوْ ثَلاَثَةً. قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ بَعْدَكُمْ قَوْمًا يَخُونُونَ وَلاَ يُؤْتَمَنُونَ، وَيَشْهَدُونَ، وَلاَ يُسْتَشْهَدُونَ وَيَنْذِرُونَ وَلاَ يَفُونَ، وَيَظْهَرُ فِيهِمُ السِّمَنُ."],"takhrij":"متفق عليه: رواه البخاري في الشهادات (2651) ومسلم في فضائل الصحابة (214:2535) كلاهما من طريق شعبة سمعت أبا حمزة، حدّثني زهدم بن مضرّب قال: سمعت عمران بن حصين، فذكره.","grade":"متفق عليه","chapter_ar":"باب في ذم المبادرة إلى الشهادة قبل أن يسألها","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2651) and Muslim (2535:214).","chapter_en":"Regarding the condemnation of rushing to give testimony before being asked for it","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["ʿImran ibn Husayn said: The Prophet ﷺ said: “The best of you is my generation, then those who follow them, then those who follow them.” ʿImran said: I do not know whether the Prophet ﷺ mentioned two or three generations after his generation. The Prophet ﷺ said: “Indeed, after you there will be a people who will betray and will not be trusted, they will bear witness without being asked to bear witness, they will make vows and not fulfill them, and obesity will appear among them.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2651,"lafz":true},{"key":"muslim","label":"مسلم","number":2535},{"key":"muslim","label":"مسلم في فضائل الصحابه","number":214}],"full":1,"rep":[9803]},{"num":6741,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ خَيْرُ النَّاسِ قَرْنِي، ثُمَّ الَّذِينَ يَلُونَهُمْ، ثُمَّ الَّذِينَ يَلُونَهُمْ، ثُمَّ يَجِيءُ أَقْوَامٌ تَسْبِقُ شَهَادَةُ أَحَدِهِمْ يَمِينَهُ، وَيَمِينُهُ شَهَادَتَهُ.","قال إبراهيم: وكانوا يضربوننا على الشهادة والعهد."],"takhrij":"متفق عليه: رواه البخاري في الشهادات (2652) ومسلم في فضائل الصحابة (21:2533) من طريق منصور، عن إبراهيم بن يزيد، عن عبيدة السلماني، عن عبدالله (هو ابن مسعود)، فذكره.","grade":"متفق عليه","chapter_ar":"باب في ذم المبادرة إلى الشهادة قبل أن يسألها","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2652) and Muslim (2533:21).","chapter_en":"Regarding the condemnation of rushing to give testimony before being asked for it","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullah ibn Masʿud narrated that the Prophet ﷺ said: “The best of people are those of my generation, then those who follow them, then those who follow them, then there will come people whose testimony will precede their oath, and their oath will precede their testimony.” Ibrahim said: They used to strike us for giving testimony and making covenants (when we were young, to teach us seriousness)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2652,"lafz":true},{"key":"muslim","label":"مسلم","number":2533,"n":6472},{"key":"muslim","label":"مسلم في فضائل الصحابه","number":21}],"full":1,"dr":1,"rep":[9806]},{"num":6742,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَلاَ أُخْبِرُكُمْ بِخَيْرِ الشُّهَدَاءِ؟ الَّذِي يَأْتِي بِشَهَادَتِهِ قَبْلَ أَنْ يُسْأَلَهَا، أَوْ يخبر بِشَهَادَتِهِ قَبْلَ أَنْ يُسْأَلَهَا."],"takhrij":"صحيح: رواه مالك في الأقضية (3) عن عبد الله بن أبي بكر بن محمد بن عمرو بن حزم، عن أبيه، عن عبد الله بن عمرو بن عثمان، عن أبي عمرة الأنصاري، عن زيد بن خالد الجهني، فذكره.","grade":"صحيح","chapter_ar":"باب خير الشهود الذي يأتي بشهادته قبل أن يُسألها خوفا من ضياع الحقوق","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (3) and Muslim (1719).","chapter_en":"The best of witnesses is the one who brings his testimony before he is asked for it out of fear of rights being lost","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Zayd ibn Khalid al-Juhani narrated that the Messenger of Allah ﷺ said: “Shall I not inform you of the best of witnesses? It is the one who brings his testimony before he is asked for it, or informs of his testimony before he is asked for it.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":3,"lafz":true},{"key":"muslim","label":"مسلم","number":1719}],"full":1,"dr":1},{"num":6743,"demo":false,"sanad":"","matn":["عَنْ ابْنِ مَسْعُودٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إن من بَيْنَ يَدَيِ السَّاعَةِ، التسليم عَلَى الْخَاصَّةِ، وَفُشُوَّ التِّجَارَةِ، وَظُهُورَ شَهَادَةِ الزُّورِ، وَكِتْمَانَ شَهَادَةِ الْحَقِّ."],"takhrij":"حسن: رواه البخاري في الأدب المفرد (1049) وأحمد (3982) والطحاوي في مشكله (1590) والحاكم (4/445) كلهم من حديث بشير بن سليمان، عن سيار أبي حمزة، عن طارق بن شهاب، عن ابن مسعود فذكره، وهذا مختصر.","grade":"حسن","chapter_ar":"باب إثم كتمان شهادة الحق","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bukhari in al-Tarikh al-Kabir (1049), Ahmad (3982), al-Tahawi in Mushkil al-Athar (1590), and al-Hakim (4/445).","chapter_en":"The sin of concealing the testimony of truth","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Ibn Masʿud narrated that the Prophet ﷺ said: “Indeed, before the Hour there will be the greeting of only those one knows, the widespread expansion of trade, the prevalence of false testimony, and the concealment of the testimony of truth.”"]},"intro":{"ar":["قال اللّٰه تعالى: (وَلَا تَكْتُمُوا الشَّهَادَةَ وَمَنْ يَكْتُمْهَا فَإِنَّهُ آثِمٌ قَلْبُهُ وَاللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌ ) [ البقرة: ٢٨٣]"],"en":["Allah the Exalted said: “And do not conceal testimony, for whoever conceals it - his heart is indeed sinful, and Allah is Knowing of what you do.” [Surat al-Baqarah: 283]"]}},"tuhfa":{},"refs":[{"key":"tarikhbukhari","label":"البخاري في التاريخ الكبير","number":1049},{"key":"sh22547","label":"الطحاوي في مشكله","number":1590},{"key":"hakim","label":"الحاكم","number":445},{"key":"ahmad","label":"مسند الإمام أحمد","number":3982,"n":3982},{"key":"adab","label":"البخاري في الادب المفرد","number":1049,"lafz":true}],"full":1,"dr":1},{"num":6744,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ سُئِلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْكَبَائِرِ قَالَ الإِشْرَاكُ بِاللَّهِ، وَعُقُوقُ الْوَالِدَيْنِ، وَقَتْلُ النَّفْسِ، وَشَهَادَةُ الزُّورِ."],"takhrij":"متفق عليه: رواه البخاري في الشهادات (2653) ومسلم في الإيمان (144:88) كلاهما من طريق شعبة، أخبرنا عبيد الله بن أبي بكر بن أنس، عن أنس، فذكره.","grade":"متفق عليه","chapter_ar":"باب الترهيب من شهادة الزور","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2653) and Muslim (88:144).","chapter_en":"Severe warning against bearing false witness","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Anas said: The Prophet ﷺ was asked about the major sins. He said: “Associating partners with Allah, disobedience to parents, killing a soul, and bearing false witness.”"]},"intro":{"ar":["قال تعالى: (وَالَّذِينَ لَا يَشْهَدُونَ الزُّورَ) [الفرقان: ٧٢]"],"en":["Allah the Exalted said: “And those who do not bear witness to falsehood.” [Surat al-Furqan: 72]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2653,"lafz":true},{"key":"muslim","label":"مسلم","number":88},{"key":"muslim","label":"مسلم في الايمان","number":144}],"full":1,"rep":[12923]},{"num":6745,"demo":false,"sanad":"","matn":["عن أَبِي بَكْرَةَ عَنْ أَبِيهِ، قَالَ كُنَّا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ أَلاَ أُنَبِّئُكُمْ بِأَكْبَرِ الْكَبَائِرِ - ثَلاَثًا - الإِشْرَاكُ بِاللَّهِ وَعُقُوقُ الْوَالِدَيْنِ وَشَهَادَةُ الزُّورِ أَوْ قَوْلُ الزُّورِ."],"takhrij":"متفق عليه: رواه البخاري في الشهادات (2654) من طريق بشر بن المفضل، ومسلم في الإيمان (143:87) من طريق إسماعيل ابن علية – كلاهما عن سعيد الجريري، حدثنا عبد الرحمن بن أبي بكرة، عن أبيه، قال (فذكره) واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب الترهيب من شهادة الزور","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2654) and Muslim (87:143), and the wording is that of Muslim.","chapter_en":"Severe warning against bearing false witness","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Abu Bakrah said: We were with the Messenger of Allah ﷺ when he said: “Shall I not inform you of the greatest of major sins? (repeating it three times): Associating partners with Allah, disobedience to parents, and bearing false witness—or speaking falsehood.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2654,"lafz":true},{"key":"muslim","label":"مسلم","number":87},{"key":"muslim","label":"مسلم في الايمان","number":143,"n":259}],"full":1,"dr":1},{"num":6746,"demo":false,"sanad":"","matn":["عن عائشة قالت في حديث الإفك: فدعا رسول الله صلى الله عليه وسلم بريرة، فقال: يا بريرة، هل رأيتِ فيها شيئا يريبكِ؟ فقالت بريرة: لا والذي بعثك بالحق، إن رأيت منها أمراً أغمصه عليها قط أكثرَ من أنها جارية حديثة السن، تنام عن العجين، فتأتي الداجن فتأكله. وجاء في آخره: وكان رسول الله صلى الله عليه وسلم يسأل زينبَ بنت جحش عن أمري، فقال: يا زينبُ، ما علمتِ ما رأيتِ؟ فقالت: يا رسول الله، أحمي سمعي وبصري، والله ما علمتُ عليها إلا خيراً، قالت (أي عائشة): وهي التي كانت تساميني، فعصمها الله بالورع."],"takhrij":"متفق عليه: رواه البخاري في الشهادات (2661)، ومسلم في التوبة (2770) من طريق الزهري، عن عروة بن الزبير، وسعيد بن المسيب، وعلقمة بن وقاص الليثي، وعبيدالله بن عبد الله بن عتبة – كلهم من عائشة رضي الله عنها زوج النبي صلى الله عليه وسلم حين قال لها أهل الإفك ما قالوا فبرّأها الله منه، فذكرت قصة الإفك بتمامها.","grade":"متفق عليه","chapter_ar":"باب تعديل النساء بعضهن بعضا","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2661) and Muslim (2770).","chapter_en":"Women verifying the upright character of one another","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["ʿAishah said in the narration of the slander (al-Ifk): The Messenger of Allah ﷺ called Barirah and said, “O Barirah, have you seen anything in her that arouses your suspicion?” Barirah said, “No, by the One Who sent you with the truth, I have never seen any fault in her for which I could blame her, other than that she is a young girl who falls asleep leaving her family’s dough, and the domestic goat comes and eats it.” And it states at the end of it: And the Messenger of Allah ﷺ used to ask Zaynab bint Jahsh about my matter, saying, “O Zaynab, what did you know? What did you see?” She replied, “O Messenger of Allah ﷺ, I protect my hearing and my sight; by Allah, I know nothing of her but good.” ʿAishah said: She was the one who used to compete with me (in status), yet Allah protected her because of her piety."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2661,"lafz":true},{"key":"muslim","label":"مسلم","number":2770}],"full":1},{"num":6747,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ يَا مَعْشَرَ النِّسَاءِ تَصَدَّقْنَ وَأَكْثِرْنَ الاِسْتِغْفَارَ فَإِنِّي رَأَيْتُكُنَّ أَكْثَرَ أَهْلِ النَّارِ. فَقَالَتِ امْرَأَةٌ مِنْهُنَّ جَزْلَةٌ وَمَا لَنَا يَا رَسُولَ اللَّهِ أَكْثَرَ أَهْلِ النَّارِ. قَالَ تُكْثِرْنَ اللَّعْنَ وَتَكْفُرْنَ الْعَشِيرَ وَمَا رَأَيْتُ مِنْ نَاقِصَاتِ عَقْلٍ وَدِينٍ أَغْلَبَ لِذِي لُبٍّ مِنْكُنَّ. قَالَتْ يَا رَسُولَ اللَّهِ وَمَا نُقْصَانُ الْعَقْلِ وَالدِّينِ قَالَ أَمَّا نُقْصَانُ الْعَقْلِ فَشَهَادَةُ امْرَأَتَيْنِ تَعْدِلُ شَهَادَةَ رَجُلٍ فَهَذَا نُقْصَانُ الْعَقْلِ وَتَمْكُثُ اللَّيَالِيَ مَا تُصَلِّي وَتُفْطِرُ فِي رَمَضَانَ فَهَذَا نُقْصَانُ الدِّينِ."],"takhrij":"صحيح: رواه مسلم في الإيمان (79) عن محمد بن رمح بن المهاجر المصريّ، أخبرنا الليث، عن ابن الهاد، عن عبد الله بن دينار، عن عبد الله بن عمر، فذكره.","grade":"صحيح","chapter_ar":"باب تعديل النساء بعضهن بعضا","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (79).","chapter_en":"Women verifying the upright character of one another","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “O assembly of women, give charity and seek forgiveness frequently, for I have seen that you form the majority of the people of the Fire.” A wise woman among them said, “Why is it, O Messenger of Allah ﷺ, that we form the majority of the people of the Fire?” He said, “You curse frequently and you are ungrateful to your husbands. I have not seen anyone deficient in intelligence and religion more capable of overcoming a wise man than one of you.” She said, “O Messenger of Allah ﷺ, what is the deficiency in intelligence and religion?” He said, “As for the deficiency in intelligence, the testimony of two women equals the testimony of one man; this is the deficiency in intelligence. And she spends nights without praying and breaks her fast in Ramadan (due to menses); this is the deficiency in religion.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":79,"lafz":true}],"full":1,"rep":[45]},{"num":6748,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ أَلَيْسَ شَهَادَةُ الْمَرْأَةِ مِثْلَ نِصْفِ شَهَادَةِ الرَّجُلِ. قُلْنَا بَلَى. قَالَ فَذَلِكَ مِنْ نُقْصَانِ عَقْلِهَا."],"takhrij":"متفق عليه: رواه البخاري في الشهادات (2658)، ومسلم في الإيمان (80) كلاهما من طريق ابن أبي مريم، أخبرنا محمد بن جعفر، أخبرني زيد بن أسلم، عن عياض بن عبدالله، عن أبي سعيد الخدري، فذكره، والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب شهادة امرأتين تعادل شهادة رجل واحد","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2658) and Muslim (80), and the wording is that of al-Bukhari.","chapter_en":"The testimony of two women equals the testimony of one man","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that the Prophet ﷺ said: “Is not the testimony of a woman equal to half the testimony of a man?” We said, “Yes.” He said, “That is due to the deficiency in her intelligence.”"]},"intro":{"ar":["قال تعالى: ( فَإِنْ لَمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌ وَامْرَأَتَانِ) [البقرة: ٢٨٢]"],"en":["Allah the Exalted said: “And if there are not two men [available], then a man and two women.” [Surat al-Baqarah: 282]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2658,"lafz":true},{"key":"muslim","label":"مسلم","number":80}],"full":1},{"num":6749,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بن الْحَارِثِ أَنَّهُ تَزَوَّجَ أُمَّ يَحْيَى بِنْتَ أَبِي إِهَابٍ، قَالَ: فَجَاءَتْ أَمَةٌ سَوْدَاءُ فَقَالَتْ: قَدْ أَرْضَعْتُكُمَا، فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَعْرَضَ عَنِّي، قَالَ: فَتَنَحَّيْتُ فَذَكَرْتُ ذَلِكَ لَهُ، قَالَ: وَكَيْفَ وَقَدْ زَعَمَتْ أَنْ قَدْ أَرْضَعَتْكُمَا فَنَهَاهُ عَنْهَا.","وفي رواية: وكيف وقد قيل! دَعْها عنك."],"takhrij":"صحيح: رواه البخاري في الشهادات (2659) من طريق ابن جريج، عن ابن أبي مليكة، عن عقبة بن الحارث.","grade":"صحيح","chapter_ar":"باب الشهادة على الرضاعة","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2659), and the other narration is also with him (2660).","chapter_en":"Bearing witness regarding breast-feeding","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["ʿUqbah ibn al-Harith narrated that he married Umm Yahya bint Abi Ihab. He said: A black slave-girl came and said, “I have breast-fed both of you.” I mentioned that to the Prophet ﷺ, but he turned his face away from me. I moved to face him and mentioned it to him again. He said, “How can you remain with her when she has claimed that she breast-fed both of you?” So he forbade him from remaining with her. And in another narration: “How can you when it has been said! Leave her.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2659,"lafz":true},{"key":"bukhari","label":"الرواية الأخرى عنده أيضا","number":2660,"n":2659}],"full":1,"dr":1},{"num":6750,"demo":false,"sanad":"","matn":["عن عَبْداللَّهِ بْنُ عُبَيْدِ الله بْنِ أَبِي مُلَيْكَةَ أَنَّ بَنِي صُهَيْبٍ مَوْلَى ابْنِ جُدْعَانَ ادَّعَوْا بَيْتَيْنِ وَحُجْرَةً أَنَّ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَعْطَى ذَلِكَ صُهَيْبًا، فَقَالَ مَرْوَانُ: مَنْ يَشْهَدُ لَكُمَا عَلَى ذَلِكَ؟ قَالُوا: ابْنُ عُمَرَ. فَدَعَاهُ، فَشَهِدَ لَأَعْطَى رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صُهَيْبًا بَيْتَيْنِ وَحُجْرَةً، فَقَضَى مَرْوَانُ بِشَهَادَتِهِ لهُمْ."],"takhrij":"صحيح: رواه البخاري في الهبة (2624) عن إبراهيم بن موسى، أخبرنا هشام بن يوسف أن ابن جريج أخبرهم قال: أخبرني عبدالله بن عبيدالله بن أبي مليكة قال: فذكره.","grade":"صحيح","chapter_ar":"باب طلب الشهادة على الهدية","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2624).","chapter_en":"Requesting testimony regarding a gift","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullah ibn ʿUbaydullah ibn Abi Mulaykah narrated that the sons of Suhayb, the freed slave of Ibn Judʿan, claimed two houses and a room, stating that the Messenger of Allah ﷺ had given that to Suhayb. Marwan asked, “Who will bear witness for you to that effect?” They said, “Ibn ʿUmar.” So Marwan called him, and he bore witness that the Messenger of Allah ﷺ had indeed given Suhayb two houses and a room. Marwan then passed judgment in their favor based on his testimony."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2624,"lafz":true}],"full":1},{"num":6751,"demo":false,"sanad":"","matn":["عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ سَأَلَتْ أُمِّي أَبِي بَعْضَ الْمَوْهِبَةِ لِي مِنْ مَالِهِ، ثُمَّ بَدَا لَهُ فَوَهَبَهَا لِي فَقَالَتْ لاَ أَرْضَى حَتَّى تُشْهِدَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَأَخَذَ بِيَدِي وَأَنَا غُلاَمٌ، فَأَتَى بِيَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ إِنَّ أُمَّهُ بِنْتَ رَوَاحَةَ سَأَلَتْنِي بَعْضَ الْمَوْهِبَةِ لِهَذَا، قَالَ أَلَكَ وَلَدٌ سِوَاهُ. قَالَ نَعَمْ. قَالَ فَأُرَاهُ قَالَ لاَ تُشْهِدْنِي عَلَى جَوْرٍ."],"takhrij":"متفق عليه: رواه البخاري في الشهادات (2650)، ومسلم في الهبات (14:1623) كلاهما من طريق أبي حيان التيمي، عن الشعبي، عن النعمان بن بشير، فذكره.","grade":"متفق عليه","chapter_ar":"باب الترهيب من الشهادة على الجور","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2650) and Muslim (1623:14).","chapter_en":"Warning against bearing witness to an injustice","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["Al-Nuʿman ibn Bashir said: My mother asked my father to grant me a gift from his wealth, then it occurred to him and he gifted it to me. She said, “I will not be pleased until you take the Prophet ﷺ as a witness.” So he took me by my hand while I was a young boy, and brought me to the Prophet ﷺ and said, “His mother, the daughter of Rawahah, asked me to grant a gift to this boy.” The Prophet ﷺ asked, “Do you have any children other than him?” He replied, “Yes.” He said, and I think he said: “Do not make me a witness to an injustice.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2650,"lafz":true},{"key":"muslim","label":"مسلم","number":1623},{"key":"muslim","label":"مسلم في الهبات","number":14}],"full":1,"rep":[5984]},{"num":6752,"demo":false,"sanad":"","matn":["عن عُرْوَةَ بن الزُّبَيْرِ أَنَّ امْرَأَةً، سَرَقَتْ فِي غَزْوَةِ الْفَتْحِ، فَأُتِيَ بِهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ أَمَرَ فَقُطِعَتْ يَدُهَا. قَالَتْ عَائِشَةُ فَحَسُنَتْ تَوْبَتُهَا وَتَزَوَّجَتْ، وَكَانَتْ تَأْتِي بَعْدَ ذَلِكَ فَأَرْفَعُ حَاجَتَهَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"متفق عليه: رواه البخاري في الشهادات (2648) ومسلم في الحدود (9:1688) كلاهما من طريق ابن وهب، عن يونس بن يزيد، عن ابن شهاب، أخبرني عروة، عن عائشة والسياق للبخاري ولفظ مسلم أتم.","grade":"متفق عليه","chapter_ar":"باب قبول شهادة الفاسق إذا تاب","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2648) and Muslim (1688:9), and the wording is that of al-Bukhari.","chapter_en":"Acceptance of the testimony of an evildoer (fasiq) if he repents","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["ʿUrwah ibn al-Zubayr narrated that a woman committed theft during the expedition of the Conquest (of Makkah). She was brought to the Messenger of Allah ﷺ, who ordered that her hand be amputated. ʿAishah said: Her repentance became excellent afterward and she married, and she used to come to me after that so that I could convey her needs to the Messenger of Allah ﷺ."]},"intro":{"ar":["قال اللّٰه تعالى: ﴿وَلَا تَقْبَلُوا لَهُمْ شَهَادَةً أَبَدًا وَأُولَٰئِكَ هُمُ الْفَاسِقُونَ ۝ إِلَّا الَّذِينَ تَابُوا﴾ [النور: ٤-٥]"],"en":["Allah the Exalted said: “And never accept their testimony, and those are the defiantly disobedient. Except for those who repent.” [Surat al-Nur: 4-5]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2648,"lafz":true},{"key":"muslim","label":"مسلم","number":1688},{"key":"muslim","label":"مسلم في الحدود","number":9}],"full":1},{"num":6753,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَدَّ شَهَادَةَ الْخَائِنِ وَالْخَائِنَةِ وَذِي الْغِمْرِ عَلَى أَخِيهِ وَرَدَّ شَهَادَةَ الْقَانِعِ لأَهْلِ الْبَيْتِ وَأَجَازَهَا لِغَيْرِهِمْ."],"takhrij":"حسن: رواه أبو داود (3600) وأحمد (6898) والدارقطني (4/243) والبيقهي (10/200) كلهم من طريق محمد بن راشد، عن سليمان بن موسى، عن عمرو بن شعيب بإسناده فذكره.","grade":"حسن","chapter_ar":"باب من ترد شهادته","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3600), Ahmad (6898), al-Daraqutni (4/243), and al-Bayhaqi (10/200).","chapter_en":"Those whose testimony is rejected","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":13,"content":{"translation":{"en":["Amr ibn Shuʿayb, from his father, from his grandfather, reported that the Messenger of Allah ﷺ rejected the testimony of a dishonest man and a dishonest woman, and of a person bearing rancor against his brother, and he rejected the testimony of a dependent servant for the household, while allowing it for others."]},"buhuth":{"en":["Abu Dawud said: al-ghimr means malice and enmity. Al-qaniʿ means the dependent hired servant, such as a personal servant."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3600,"lafz":true},{"key":"sh9771","label":"الدارقطني","number":243},{"key":"kubrabayhaqi","label":"البيهقي","number":200},{"key":"ahmad","label":"مسند الإمام أحمد","number":6898,"n":7102},{"key":"sh9771","label":"سنن الدارقطني","number":4600,"n":4612},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":20854,"n":21012}],"full":1,"dr":1},{"num":6754,"demo":false,"sanad":"","matn":["عَنْ ابْنِ مَسْعُودٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : مَنْ حَلَفَ عَلَى يَمِينٍ- وَهْوَ فِيهَا فَاجِرٌ- لِيَقْتَطِعَ بِهَا مَالَ امْرِئٍ مُسْلِمٍ لَقِيَ اللَّهَ وَهْوَ عَلَيْهِ غَضْبَانُ قَالَ: فَقَالَ الأَشْعَثُ بْنُ قَيْسٍ فيّ وَاللَّهِ كَانَ ذَلِكَ، كَانَ بَيْنِي وَبَيْنَ رَجُلٍ مِنَ الْيَهُودِ أَرْضٌ فَجَحَدَنِي، فَقَدَّمْتُهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَقَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَلَكَ بَيِّنَةٌ؟ قَالَ: فَقَالَ لِلْيَهُودِيِّ: احْلِفْ. قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ إذن يَحْلِفَ وَيَذْهَبَ بِمَالِي. قَالَ: فَأَنْزَلَ اللَّهُ تَعَالَى: ﴿إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ وَأَيْمَانِهِمْ ثَمَنًا قَلِيلًا﴾ [سورة آل عمران: 77] إِلَى آخِرِ الآيَةِ. [آل عِمْرَانَ: ٧٧] وَفِي رِوَايَةِ: شاهداك أَوْ يمينه."],"takhrij":"متفق عليه: رواه البخاري في الشهادات (2267،2666) ومسلم في الإيمان (220:138) كلاهما من طريق أبي معاوية – وعند مسلم وغيره – عن الأعمش، عن أبي وائل شقيق، عن عبد الله بن مسعود فذكره.","grade":"متفق عليه","chapter_ar":"باب البينة على المدعي واليمين على من أنكر","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2666, 2667) and Muslim (220:138).","chapter_en":"The proof is upon the claimant, and the oath is upon the one who denies","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Ibn Masʿud reported that the Messenger of Allah ﷺ said: “Whoever swears an oath while lying in it in order to unlawfully take the wealth of a Muslim will meet Allah while He is angry with him.” Al-Ashʿath ibn Qays said: By Allah, this was about me. There was a dispute between me and a Jewish man concerning land, and he denied my claim. So I brought him to the Prophet ﷺ, and the Messenger of Allah ﷺ said to me: “Do you have proof?” I said: No. He then said to the Jew: “Swear an oath.” I said: O Messenger of Allah ﷺ, then he will swear and take my property. Then Allah revealed: “Indeed, those who exchange the covenant of Allah and their oaths for a small price…” to the end of the verse [Aal Imran: 77]. In another narration: “Your two witnesses, or else his oath.”"]},"buhuth":{"en":["The other wording is in al-Bukhari (2669, 2670) and Muslim (221:138)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2666,"lafz":true},{"key":"muslim","label":"مسلم","number":220},{"key":"bukhari","label":"البخاري في الشهادات","number":2267,"n":2416}],"full":1,"dr":1},{"num":6755,"demo":false,"sanad":"","matn":["عَنْ وَائِلِ بْنِ حُجْرٍ قَالَ: جَاءَ رَجُلٌ مِنْ حضر موت وَرَجُلٌ مِنْ كِنْدَةَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ الْحَضْرَمِيُّ: يَا رَسُولَ اللَّهِ، إِنَّ هَذَا قَدْ غَلَبَنِي عَلَى أَرْضٍ كَانَتْ لأَبِي. فَقَالَ الْكِنْدِيُّ: هِيَ أَرْضِي فِي يَدِي أَزْرَعُهَا لَيْسَ لَهُ فِيهَا حَقٌّ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلْحَضْرَمِيِّ: أَلَكَ بَيِّنَةٌ؟ قَالَ: لاَ. قَالَ: فَلَكَ يَمِينُهُ قَالَ: يَا رَسُولَ اللَّهِ إِنَّ الرَّجُلَ فَاجِرٌ لاَ يُبَالِي عَلَى مَا حَلَفَ عَلَيْهِ، وَلَيْسَ يَتَوَرَّعُ مِنْ شيء. فَقَالَ: لَيْسَ لَكَ مِنْهُ إِلاَّ ذَلِكَ، فَانْطَلَقَ لِيَحْلِفَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا أَدْبَرَ: أَمَا لَئِنْ حَلَفَ عَلَى مَالِهِ لِيَأْكُلَهُ ظُلْمًا، لَيَلْقَيَنَّ اللَّهَ وَهُوَ عَنْهُ مُعْرِض."],"takhrij":"صحيح: رواه مسلم في الإيمان (223:139) من طريق أبي الأحوص، عن سماك، عن علقمة بن وائل، عن أبيه، فذكره.","grade":"صحيح","chapter_ar":"باب البينة على المدعي واليمين على من أنكر","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (223:139).","chapter_en":"The proof is upon the claimant, and the oath is upon the one who denies","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Wa’il ibn Hujr said: A man from Hadramawt and a man from Kindah came to the Prophet ﷺ. The Hadrami said: O Messenger of Allah ﷺ, this man has seized land that belonged to my father. The Kindi said: It is my land, in my possession, and I cultivate it; he has no right to it. The Messenger of Allah ﷺ said to the Hadrami: “Do you have proof?” He said: No. He said: “Then you are entitled to his oath.” He said: O Messenger of Allah ﷺ, the man is wicked; he does not care what he swears upon and he refrains from nothing. He said: “You have no right against him except that.” So the man went off to swear, and when he turned away the Messenger of Allah ﷺ said: “If he swears to seize his property unjustly, he will surely meet Allah while Allah is turned away from him.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":223,"lafz":true,"n":358}],"full":1},{"num":6756,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى قَالَ: اخْتَصَمَ رَجُلَانِ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي أَرْضٍ أَحَدُهُمَا مِنْ أَهْلِ حَضْرَمَوْتَ، قَالَ: فَجَعَلَ يَمِينَ أَحَدِهِمَا، قَالَ: فَضَجَّ الْآخَرُ، وَقَالَ: إِنَّهُ إِذًا يَذْهَبُ بِأَرْضِي. فَقَالَ: إِنْ هُوَ اقْتَطَعَهَا بِيَمِينِهِ ظُلْمًا، كَانَ مِمَّنْ لَا يَنْظُرُ اللَّهُ عَزَّ وَجَلَّ إِلَيْهِ يَوْمَ الْقِيَامَةِ، وَلَا يُزَكِّيهِ، وَلَهُ عَذَابٌ أَلِيمٌ قَالَ: وَوَرِعَ الْآخَرُ فَرَدَّهَا."],"takhrij":"صحيح: رواه أحمد (19514) والبزار –كشف الأستار (1359) وأبو يعلى (7274) كلهم من حديث حسين بن علي، عن جعفر بن برقان، عن ثابت بن الحجاج، عن أبي بردة، عن أبي موسى، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب البينة على المدعي واليمين على من أنكر","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (19514), al-Bazzar in Kashf al-Astar (1359), and Abu Yaʿla (7274).","chapter_en":"The proof is upon the claimant, and the oath is upon the one who denies","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Abu Musa said: Two men brought a dispute over land to the Prophet ﷺ, one of them being from Hadramawt. He ruled that one of them should swear an oath. The other cried out and said: Then he will take my land! He said: “If he takes it by his oath unjustly, he will be among those at whom Allah will not look on the Day of Resurrection, nor will He purify him, and he will have a painful punishment.” The other man then refrained and returned it."]}},"tuhfa":{},"refs":[{"key":"sh12862","label":"البزار -كشف الأستار","number":1359},{"key":"sh12520","label":"أبو يعلى","number":7274},{"key":"ahmad","label":"مسند الإمام أحمد","number":19514,"n":19514,"lafz":true}],"full":1},{"num":6757,"demo":false,"sanad":"","matn":["عَنِ ابْنِ أَبِي مُلَيْكَةَ، أَنَّ امْرَأَتَيْنِ، كَانَتَا تَخْرِزَانِ فِي بَيْتٍ ـ أَوْ فِي الْحُجْرَةِ ـ فَخَرَجَتْ إِحْدَاهُمَا وَقَدْ أُنْفِذَ بِإِشْفًى فِي كَفِّهَا، فَادَّعَتْ عَلَى الأُخْرَى، فَرُفِعَ إِلَى ابْنِ عَبَّاسٍ، فَقَالَ ابْنُ عَبَّاسٍ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَوْ يُعْطَى النَّاسُ بِدَعْوَاهُمْ لَذَهَبَ دِمَاءُ قَوْمٍ وَأَمْوَالُهُمْ. ذَكِّرُوهَا بِاللَّهِ وَاقْرَءُوا عَلَيْهَا ﴿إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ﴾ [سورة آل عمران: 77]}. فَذَكَّرُوهَا فَاعْتَرَفَتْ، فَقَالَ ابْنُ عَبَّاسٍ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْيَمِينُ عَلَى الْمُدَّعَى عَلَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4552)، ومسلم في الأقضية (1:177) كلاهما من طريق ابن أبي مليكة، فذكره.","grade":"متفق عليه","chapter_ar":"باب البينة على المدعي واليمين على من أنكر","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4552) and Muslim (1711/1). This is the wording of al-Bukhārī.","chapter_en":"The proof is upon the claimant, and the oath is upon the one who denies","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Ibn Abī Mulaykah reported: Two women were sewing leather in a house—or in a room—when one of them came out with an awl driven into the palm of her hand. She accused the other woman, and the matter was brought before Ibn ʿAbbās. Ibn ʿAbbās said that the Messenger of Allah ﷺ said: “If people were granted what they claimed merely on the basis of their claims, the blood and wealth of people would be lost.” He said: “Remind her of Allah and recite to her: ‘Indeed, those who exchange the covenant of Allah…’” [Āl ʿImrān: 77] They reminded her, and she confessed. Then Ibn ʿAbbās said that the Prophet ﷺ said: “The oath is upon the one against whom the claim is made.”"]},"buhuth":{"en":["The word ishfā means the pointed iron tool used for piercing leather while sewing."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4552,"lafz":true},{"key":"muslim","label":"مسلم","number":1711},{"key":"muslim","label":"مسلم في الاقضيه","number":1}],"full":1,"dr":1,"rep":[12077]},{"num":6758,"demo":false,"sanad":"","matn":["عَنِ ابْنِ أَبِي مُلَيْكَةَ، قَالَ كَتَبَ ابْنُ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى بِالْيَمِينِ عَلَى الْمُدَّعَى عَلَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في الشهادات (2668) ومسلم في الأقضية (2:1711) كلاهما من طريق نافع، عن ابن أبي مليكة، فذكره.","grade":"متفق عليه","chapter_ar":"باب البينة على المدعي واليمين على من أنكر","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2668) and Muslim (2:1711).","chapter_en":"The proof is upon the claimant, and the oath is upon the one who denies","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Ibn Abi Mulaykah said: Ibn Abbas wrote that the Prophet ﷺ judged that the oath is upon the one against whom the claim is made."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2668,"lafz":true},{"key":"muslim","label":"مسلم","number":2}],"full":1},{"num":6759,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبيهِ، عَنْ جَدِّهِ قَالَ: قَالَ رَسُولُ اللهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  -: الْمُدَّعَي عَلَيْهِ أَوْلَي بِالْيَمِينِ إِذَا لَمْ تَكُنْ بَيِّنَةٌ."],"takhrij":"حسن: رواه عبدالرزاق في المصنف (15184) عن ابن جريج، عن عمرو بن شعيب، عن أبيه، عن جده قال: فذكره.","grade":"حسن","chapter_ar":"باب البينة على المدعي واليمين على من أنكر","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Abd al-Razzaq in al-Musannaf (15184).","chapter_en":"The proof is upon the claimant, and the oath is upon the one who denies","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Amr ibn Shuʿayb, from his father, from his grandfather, reported that the Messenger of Allah ﷺ said: “The one against whom the claim is made has more right to the oath when there is no proof.”"]}},"tuhfa":{},"refs":[{"key":"abdrazzaq","label":"عبدالرزاق في المصنف","number":15184,"lafz":true}],"full":1,"dr":1},{"num":6760,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: الْمُدَّعَى عَلَيْهِ أَوْلَى بِالْيَمِينِ إِلَّا أَنْ تَقُومَ بَيِّنَةٌ."],"takhrij":"حسن: رواه ابنُ حبان (5996) في سياق طويل، والدارقطني (4511) مختصرا كلاهما من حديث سنان بن الحارث بن مصرف، عن طلحة بن مصرف، عن مجاهد، عن ابن عمر قال: فذكره.","grade":"حسن","chapter_ar":"باب البينة على المدعي واليمين على من أنكر","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Hibban (5996) in a longer narration, and al-Daraqutni (4511).","chapter_en":"The proof is upon the claimant, and the oath is upon the one who denies","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Ibn Umar reported that the Messenger of Allah ﷺ said: “The one against whom the claim is made has more right to the oath unless proof is established.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"ابنُ حبان","number":5996,"lafz":true},{"key":"sh9771","label":"الدار قطني","number":4511}],"full":1,"dr":1},{"num":6761,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى بِيَمِينٍ وَشَاهِدٍ."],"takhrij":"صحيح: رواه مسلم في الأقضية (1712) من طريق زيد بن حباب، حدثني سيف بن سليمان، أخبرني قيس بن سعد، عن عمرو بن دينار، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب القضاء باليمين والشاهد","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1712).","chapter_en":"Judging by an oath together with one witness","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["Ibn Abbas reported that the Messenger of Allah ﷺ gave judgment based on an oath and one witness."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1712,"lafz":true}],"full":1,"dr":1},{"num":6762,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى بِالْيَمِينِ مَعَ الشَّاهِدِ."],"takhrij":"صحيح: رواه أبو داود (3610) عن أحمد بن أبي بكر أبو مصعب الزهري، حدثنا الدراوردي، عن ربيعة بن أبي عبد الرحمن، عن سهيل بن أبي صالح، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب القضاء باليمين والشاهد","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3610).","chapter_en":"Judging by an oath together with one witness","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ gave judgment based on an oath together with a single witness."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3610,"lafz":true}],"full":1,"dr":1},{"num":6763,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى بِالْيَمِينِ مَعَ الشَّاهِدِ."],"takhrij":"صحيح: رواه الترمذي (1344) وابن ماجة (2369) وأحمد (14278) وابن الجارود (1008) والدراقطني (4/212) والبيهقي (10/170) كلهم من طرق عن عبدالوهاب بن عبد المجيد الثقفي قال: ثنا جعفر بن محمد، عن أبيه، عن جابر بن عبد الله فذكره. قال أبو عبد الرحمن (عبد الله بن أحمد) كان أبي قد ضرب على هذا الحديث، قال: \"ولم يوافق أحد الثقفي على جابر. فلم أزل به حتى قرأه عليّ وكتب عليه: صح\".","grade":"صحيح","chapter_ar":"باب القضاء باليمين والشاهد","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1344), Ibn Majah (2369), Ahmad (14278), and Ibn al-Jarud (1008).","chapter_en":"Judging by an oath together with one witness","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["Jabir ibn Abdullah reported that the Prophet ﷺ gave judgment based on an oath together with a witness."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1344,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2369},{"key":"sh13071","label":"ابن الجارود","number":1008,"n":914},{"key":"ahmad","label":"مسند الإمام أحمد","number":14278,"n":14278}],"full":1,"dr":1},{"num":6764,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا خَرَجَ أَقْرَعَ بَيْنَ نِسَائِهِ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5211) ومسلم في فضائل الصحابة (2445) كلاهما من حديث أبي نعيم حدثنا عبد الواحد بن أيمن، قال: حدثني ابن أبي مليكة عن القاسم بن محمد، عن عائشة فذكرته في حديث طويل.","grade":"متفق عليه","chapter_ar":"باب القضاء بالقرعة","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5211) and Muslim (2445).","chapter_en":"Judging by drawing lots","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["ʿA’ishah reported that whenever the Prophet ﷺ went on a journey, he would draw lots among his wives."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5211,"lafz":true},{"key":"muslim","label":"مسلم","number":2445}],"full":1},{"num":6765,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ، بْنِ حُصَيْنٍ. أَنَّ رَجُلاً، أَعْتَقَ سِتَّةَ مَمْلُوكِينَ لَهُ عِنْدَ مَوْتِهِ لَمْ يَكُنْ لَهُ مَالٌ غَيْرُهُمْ فَدَعَا بِهِمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَزَّأَهُمْ أَثْلاَثًا ثُمَّ أَقْرَعَ بَيْنَهُمْ فَأَعْتَقَ اثْنَيْنِ وَأَرَقَّ أَرْبَعَةً وَقَالَ لَهُ قَوْلاً شَدِيدًا."],"takhrij":"صحيح: رواه مسلم في الأيمان والنذور (56:1668) من طريق إسماعيل ابن علية، عن أيوب، عن أبي قلابة، عن أبي المهلّب، عن عمران بن حصين، فذكره.","grade":"صحيح","chapter_ar":"باب القضاء بالقرعة","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1668/56).","chapter_en":"Judging by drawing lots","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn reported: A man freed six slaves of his at the time of his death, and he had no property other than them. The Messenger of Allah ﷺ summoned them, divided them into three groups, and then drew lots among them. He freed two and kept four in servitude, and he spoke sternly concerning the man."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1668,"lafz":true},{"key":"muslim","label":"مسلم في الايمان والنذور","number":56}],"full":1,"rep":[6106]},{"num":6766,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَجُلَيْنِ، اخْتَصَمَا فِي مَتَاعٍ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْسَ لِوَاحِدٍ مِنْهُمَا بَيِّنَةٌ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اسْتَهِمَا عَلَى الْيَمِينِ مَا كَانَ أَحَبَّا ذَلِكَ أَوْ كَرِهَا."],"takhrij":"صحيح: رواه أبو داود (3616) وابن ماجة (2329) وأحمد (10347) والدارقطني (4/211) والبيهقي (10/255) كلهم من طرق عن سعيد بن أبي عروبة، عن قتادة، عن خلاس، عن أبي رافع، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب القضاء بالقرعة","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3616), Ibn Majah (2329), Ahmad (10347), and al-Daraqutni (4/211).","chapter_en":"Judging by drawing lots","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Abu Hurayrah reported that two men brought a dispute over some goods to the Prophet ﷺ, and neither of them had proof. So he said: “Draw lots regarding the oath, whatever the case may be, whether they like it or dislike it.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3616,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2329},{"key":"sh9771","label":"الدارقطني","number":211},{"key":"ahmad","label":"مسند الإمام أحمد","number":10347,"n":10347}],"full":1,"dr":1},{"num":6767,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَرَضَ عَلَى قَوْمٍ الْيَمِينَ فَأَسْرَعُوا، فَأَمَرَ أَنْ يُسْهَمَ بَيْنَهُمْ فِي الْيَمِينِ أَيُّهُمْ يَحْلِفُ."],"takhrij":"صحيح: رواه البخاري في الشهادات (2674) عن إسحاق بن نصر، حدثنا عبد الرزاق، أخبرنا معمر، عن همام بن منبه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب إذا تسارع قوم في اليمين أقرع بينهم","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2674).","chapter_en":"If several people hasten to swear an oath, lots are drawn among them","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ offered an oath to some people, and they hastened toward it, so he ordered that lots be drawn among them to determine which of them would swear."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2674,"lafz":true}],"full":1,"dr":1,"rep":[7078]},{"num":6768,"demo":false,"sanad":"","matn":["عَنْ عُمَارَةَ بْنِ خُزَيْمَةَ، أَنَّ عَمَّهُ، حَدَّثَهُ وَهُوَ، مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ابْتَاعَ فَرَسًا مِنْ أَعْرَابِيٍّ فَاسْتَتْبَعَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيَقْضِيَهُ ثَمَنَ فَرَسِهِ فَأَسْرَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَشْىَ وَأَبْطَأَ الأَعْرَابِيُّ فَطَفِقَ رِجَالٌ يَعْتَرِضُونَ الأَعْرَابِيَّ فَيُسَاوِمُونَهُ بِالْفَرَسِ وَلاَ يَشْعُرُونَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ابْتَاعَهُ فَنَادَى الأَعْرَابِيُّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ إِنْ كُنْتَ مُبْتَاعًا هَذَا الْفَرَسَ وَإِلاَّ بِعْتُهُ. فَقَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ سَمِعَ نِدَاءَ الأَعْرَابِيِّ فَقَالَ أَوَلَيْسَ قَدِ ابْتَعْتُهُ مِنْكَ. فَقَالَ الأَعْرَابِيُّ لاَ وَاللَّهِ مَا بِعْتُكَهُ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَلَى قَدِ ابْتَعْتُهُ مِنْكَ. فَطَفِقَ الأَعْرَابِيُّ يَقُولُ هَلُمَّ شَهِيدًا. فَقَالَ خُزَيْمَةُ بْنُ ثَابِتٍ أَنَا أَشْهَدُ أَنَّكَ قَدْ بَايَعْتَهُ. فَأَقْبَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى خُزَيْمَةَ فَقَالَ بِمَ تَشْهَدُ. فَقَالَ بِتَصْدِيقِكَ يَا رَسُولَ اللَّهِ. فَجَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَهَادَةَ خُزَيْمَةَ بِشَهَادَةِ رَجُلَيْنِ."],"takhrij":"صحيح: رواه أبو داود (3607)، والنسائي (4647)، وأحمد (21883)، والحاكم (2/17-18) والبيهقي (10/145-146) كلهم من طرق عن الزهري، أخبره عن عمارة بن خزيمة فذكره.","grade":"صحيح","chapter_ar":"باب جعل شهادة خزيمة بن ثابت شهادة رجلين","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3607), al-Nasa’i (4647), Ahmad (21883), and al-Hakim (2/17–18).","chapter_en":"Making the testimony of Khuzaymah ibn Thabit equal to the testimony of two men","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":18,"content":{"translation":{"en":["Umarah ibn Khuzaymah reported that his uncle—who was one of the Companions of the Prophet ﷺ—said that the Prophet ﷺ bought a horse from a Bedouin. Then the Prophet ﷺ asked him to follow so he could pay him the price of the horse. The Prophet ﷺ walked quickly while the Bedouin lagged behind. Men began approaching the Bedouin and bargaining with him over the horse, not realizing that the Prophet ﷺ had already bought it. The Bedouin then called out to the Messenger of Allah ﷺ and said: If you are buying this horse, then buy it, otherwise I will sell it. When the Prophet ﷺ heard the call of the Bedouin, he stood and said: “Have I not already bought it from you?” The Bedouin said: No, by Allah, I have not sold it to you. The Prophet ﷺ said: “Rather, I have bought it from you.” The Bedouin then kept saying: Bring a witness. Khuzaymah ibn Thabit said: I testify that you did indeed make the sale with him. The Prophet ﷺ turned to Khuzaymah and said: “On what basis do you testify?” He said: By believing you, O Messenger of Allah ﷺ. So the Prophet ﷺ made the testimony of Khuzaymah equal to the testimony of two men."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3607,"lafz":true},{"key":"nasai","label":"النسائي","number":4647,"n":4647},{"key":"hakim","label":"الحاكم","number":17},{"key":"ahmad","label":"مسند الإمام أحمد","number":21883,"n":21883}],"full":1,"dr":1,"rep":[10185]},{"num":6769,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: خَرَجَ رَجُلٌ مِنْ بَنِي سَهْم مَعَ تَمِيمٍ الدَّارِيِّ وَعَدِيِّ بْنِ بَدَّاءٍ. فَمَاتَ السَّهْمِيُّ بِأَرْضٍ لَيْسَ بِهَا مُسْلِمٌ. فَلَمَّا قَدِمَا بِتَرِكَتِهِ فَقَدُوا جَامًا مِنْ فِضَّةٍ مُخَوَّصًا بِالذَّهَبِ. فَأَحْلَفَهُمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ وَجَدُوا الْجَامُ بِمَكَّةَ، فَقِيلَ: اشتريناه مِنْ عدي وتميم. فَقَامَ رَجُلاَنِ مِنْ أولياء السَّهْمِيُّ، فَحَلَفَا بالله: لَشَهَادَتُنَا أَحَقُّ مِنْ شَهَادَتِهِمَا. وَإِنَّ الْجَامَ لِصَاحِبِهِمْ. قَالَ: وَفِيهِمْ نَزَلَتْ: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا شَهَادَةُ بَيْنِكُمْ إِذَا حَضَرَ أَحَدَكُمُ الْمَوْتُ حِينَ الْوَصِيَّةِ اثْنَانِ ذَوَا عَدْلٍ مِنْكُمْ أَوْ آخَرَانِ مِنْ غَيْرِكُمْ﴾ [المائدة: ١٠٦ ]"],"takhrij":"صحيح: رواه البخاري في الوصية (2780) وقال لي علي بن عبد الله، حدثنا يحيى بن آدم، حدثنا ابن أبي زائدة، عن محمد بن أبي القاسم، عن عبدالملك بن سعيد بن جبير، عن أبيه، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب شهادة أهل الذمة على وصية المسلم في السفر","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2780).","chapter_en":"The testimony of non-Muslim protected people concerning the will of a Muslim while traveling","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":19,"content":{"translation":{"en":["Ibn Abbas said: A man from Banu Sahm traveled with Tamim al-Dari and ʿAdi ibn Badda’. The Sahmi man died in a land where there were no Muslims. When they returned with his estate, they were found missing a silver cup ornamented with gold. The Messenger of Allah ﷺ made the two of them swear an oath. Then the cup was later found in Makkah, and it was said: We bought it from ʿAdi and Tamim. So two men from the heirs of the Sahmi stood and swore by Allah: Our testimony is more entitled to be accepted than their testimony, and the cup belongs to their relative. He said: Regarding them was revealed: “O you who believe, when death approaches one of you at the time of making a bequest, let there be two just men from among you, or two others from outside you…” [al-Ma’idah: 106]."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2780,"lafz":true}],"full":1,"dr":1},{"num":6770,"demo":false,"sanad":"","matn":["عَنِ الشَّعْبِيِّ، أَنَّ رَجُلاً، مِنَ الْمُسْلِمِينَ حَضَرَتْهُ الْوَفَاةُ بِدَقُوقَاءَ هَذِهِ وَلَمْ يَجِدْ أَحَدًا مِنَ الْمُسْلِمِينَ يُشْهِدُهُ عَلَى وَصِيَّتِهِ فَأَشْهَدَ رَجُلَيْنِ مِنْ أَهْلِ الْكِتَابِ فَقَدِمَا الْكُوفَةَ فَأَتَيَا أَبَا مُوسَى الأَشْعَرِيَّ فَأَخْبَرَاهُ وَقَدِمَا بِتَرِكَتِهِ وَوَصِيَّتِهِ. فَقَالَ الأَشْعَرِيُّ هَذَا أَمْرٌ لَمْ يَكُنْ بَعْدَ الَّذِي كَانَ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَأَحْلَفَهُمَا بَعْدَ الْعَصْرِ بِاللَّهِ مَا خَانَا وَلاَ كَذِبَا وَلاَ بَدَّلاَ وَلاَ كَتَمَا وَلاَ غَيَّرَا وَإِنَّهَا لَوَصِيَّةُ الرَّجُلِ وَتَرِكَتُهُ فَأَمْضَى شَهَادَتَهُمَا."],"takhrij":"صحيح: رواه أبو داود (3605) ومن طريقه البيهقي (10/165) عن زياد بن أيوب، حدثنا هشيم، أخبرنا زكريا، عن الشعبي فذكره.","grade":"صحيح","chapter_ar":"باب شهادة أهل الذمة على وصية المسلم في السفر","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (3605) and al-Bayhaqī (10/165).","chapter_en":"The testimony of non-Muslim protected people concerning the will of a Muslim while traveling","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":19,"content":{"translation":{"en":["Al-Shaʿbī reported: A Muslim man was near death in Daqūqāʾ and could not find any Muslims to witness his will, so he called two men from the People of the Book as witnesses. They later came to Kūfah and went to Abū Mūsā al-Ashʿarī. They informed him of what had happened and brought with them the man’s estate and his will. Al-Ashʿarī said: “This is a matter that has not occurred since the case that occurred during the lifetime of the Messenger of Allah ﷺ.” After the ʿAṣr prayer, he made the two men swear by Allah that they had neither betrayed the trust, lied, altered anything, concealed anything, nor changed anything, and that this was truly the man’s will and estate. He then accepted their testimony."]},"buhuth":{"en":["Daqūqāʾ is a town situated between Baghdad and Irbil."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3605,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":10},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":20626,"n":20784}],"full":1,"dr":1},{"num":6771,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  دَعَا رَجُلاً مِنْ عُلَمَاءِ الْيَهُودِ فَقَالَ أَنْشُدُكَ بِاللَّهِ الَّذِي أَنْزَلَ التَّوْرَاةَ عَلَى مُوسَى."],"takhrij":"صحيح: رواه مسلم في الحدود (1700) من طريق أبي معاوية، عن الأعمش، عن عبد الله بن مرة، عن البراء فذكره في قصة طويلة في رجم اليهود واليهودية.","grade":"صحيح","chapter_ar":"باب شهادة أهل الذمة على وصية المسلم في السفر","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1700).","chapter_en":"The testimony of non-Muslim protected people concerning the will of a Muslim while traveling","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":19,"content":{"translation":{"en":["Al-Bara’ ibn ʿAzib reported that the Messenger of Allah ﷺ called for a Jewish scholar and said: “I adjure you by Allah, the One who revealed the Torah to Musa.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1700,"lafz":true}],"full":1},{"num":6772,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِذَا اخْتَلَفْتُمْ فِي الطَّرِيقِ جُعِلَ عَرْضُهُ سَبْعَ أَذْرُعٍ."],"takhrij":"متفق عليه: رواه مسلم في المساقاة (1613) عن أبي كامل فُضيل بن حسين الجحدري، حدثنا عبد العزيز بن المختار، حدثنا خالد الحذاء، عن يوسف بن عبد الله، عن أبيه، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب قدر الطريق إذا اختلفوا فيه","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (1613), and al-Bukhari (2473), whose wording is: The Prophet ﷺ ruled, when they disputed over a road, that it should be seven cubits.","chapter_en":"The width of a road when people dispute over it","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أقضية النبي ﷺ","group_en":"Collection of what has come regarding the judgments of the Prophet ﷺ","part_no":31,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “If you dispute concerning the road, its width is to be made seven cubits.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1613,"lafz":true},{"key":"bukhari","label":"البخاري","number":2473}],"full":1,"dr":1},{"num":6773,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: اخْتَصَمَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلاَنِ فِي حَرِيمِ نَخْلَةٍ فَأَمَرَ بِهَا فَذُرِعَتْ فَوُجِدَتْ سَبْعَةَ أَذْرُعٍ. وَفِي رِوَايَةِ: خَمْسَةَ أَذْرُعٍ. فَقَضَى بِذَلِكَ."],"takhrij":"حسن: رواه أبو داود (3640) عن محمد بن خالد، أن محمد بن عثمان حدثهم، حدثنا عبد العزيز بن محمد، عن أبي طُوالة وعمرو بن يحيى، عن أبيه، عن أبي سعيد الخدري فذكره.","grade":"حسن","chapter_ar":"باب القضاء في حريم النخلة","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3640).","chapter_en":"Judgment concerning the protected surrounding space of a date palm","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أقضية النبي ﷺ","group_en":"Collection of what has come regarding the judgments of the Prophet ﷺ","part_no":31,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī reported: Two men brought a dispute before the Messenger of Allah ﷺ concerning the protected surrounding space of a date palm. He ordered that it be measured, and it was found to be seven cubits. In another narration: five cubits. He then gave judgment accordingly."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3640,"lafz":true}],"full":1,"dr":1},{"num":6774,"demo":false,"sanad":"","matn":["عَنْ عُمَيْرٍ مَوْلَى أَبِي اللَّحْمِ قَالَ: أَقْبَلْتُ مَعَ سَادَتِي، نُرِيدُ الْهِجْرَةَ حَتَّى أن دَنَوْنَا مِنَ الْمَدِينَةِ، قَالَ: فَدَخَلُوا الْمَدِينَةَ، وَخَلَّفُونِي فِي ظهرهم، قَالَ: قَالَ: فَأَصَابَنِي مَجَاعَةٌ شَدِيدَةٌ، قَالَ: فَمَرَّ بِي بَعْضُ مَنْ يَخْرُجُ مِنَ الْمَدِينَةِ، فَقَالُوا لِي: لَوْ دَخَلْتَ الْمَدِينَةَ، فَأَصَبْتَ مِنْ ثَمَرِ حَوَائِطِهَا، فَدَخَلْتُ حَائِطًا فَقَطَعْتُ مِنْهُ قِنْوَيْنِ، فَأَتَانِي صَاحِبُ الْحَائِطِ فَأَتَى بِي إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَأَخْبَرَهُ خَبَرِي، وعليَّ ثَوْبَانِ، فَقَالَ لِي: أَيُّهُمَا أَفْضَلُ فَأَشَرْتُ لَهُ إِلَى أَحَدِهِمَا، فَقَالَ: خُذْه وأعطى صَاحِبَ الْحَائِطِ الْآخَرَ، وخلَّى سَبِيلِي."],"takhrij":"حسن: رواه الإمام أحمد (21942) عن ربعي بن إبراهيم، حدثنا عبد الرحمن -يعني ابن إسحاق-، حدثني أبي، عن عمّه وأبي بكر بن زيد بن المهاجر، أنهما سمعا عميرًا مولى آبي اللحم قال: فذكره.","grade":"حسن","chapter_ar":"باب القضاء في حريم النخلة","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (21942).","chapter_en":"Judgment concerning the protected surrounding space of a date palm","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أقضية النبي ﷺ","group_en":"Collection of what has come regarding the judgments of the Prophet ﷺ","part_no":31,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["ʿUmayr, the freedman of Abi al-Lahm, said: I came with my masters intending hijrah, and when we drew near to Madinah, they entered the city and left me behind with their baggage. Then severe hunger struck me. Some people passing by me on their way out of Madinah said to me: “If you entered Madinah, you could get some fruit from its orchards.” So I entered an orchard and cut two clusters from it. Then the owner of the orchard came, took me to the Messenger of Allah ﷺ, and informed him of my case. I had two garments on me. He said to me: “Which of them is better?” I pointed to one of them, so he said: “Take it,” and he gave the other one to the owner of the orchard and let me go."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":21942,"lafz":true}],"full":1,"dr":1},{"num":6775,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ، أَنَّ رَجُلاً مِنَ الأَنْصَارِ خَاصَمَ الزُّبَيْرَ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي شِرَاجِ الْحَرَّةِ الَّتِي يَسْقُونَ بِهَا النَّخْلَ. فَقَالَ الأَنْصَارِيُّ: سرّح الْمَاءَ يَمُرُّ، فَأَبَى عَلَيْهِ، فَاخْتَصَمَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ . فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلزُّبَيْرِ: اسْقِ يَا زُبَيْرُ، ثُمَّ أَرْسِلِ الْمَاء إِلَى جَارِكَ. فَغَضِبَ الأَنْصَارِيُّ فَقَالَ: أَنْ كَانَ ابْنَ عَمَّتِكَ؟ فَتَلَوَّنَ وَجْهُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ قَالَ: اسْقِ يَا زُبَيْرُ، ثُمَّ احْبِسِ الْمَاءَ حَتَّى يَرْجِعَ إِلَى الْجِدَارِ فَقَالَ الزُّبَيْرُ: وَاللَّهِ إِنِّي لأَحْسِبُ هَذِهِ الآيَةَ نَزَلَتْ فِي ذَلِكَ: ﴿فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ﴾ [النساء:٦٥]"],"takhrij":"متفق عليه: رواه البخاري في المساقاة (2359) ومسلم في الفضائل (2357) كلاهما من حديث الليث، عن ابن شهاب، عن عروة، عن عبد الله بن الزبير فذكره.","grade":"متفق عليه","chapter_ar":"باب القضاء في سقي النخيل","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2359) and Muslim (2357).","chapter_en":"Judgement regarding irrigation of date palms","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أقضية النبي ﷺ","group_en":"Collection of what has come regarding the judgments of the Prophet ﷺ","part_no":31,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullāh ibn al-Zubayr reported: A man from the Anṣār disputed with al-Zubayr before the Messenger of Allah ﷺ concerning the water channels of al-Ḥarrah by which they irrigated their date palms. The Anṣārī said: “Let the water flow onward.” Al-Zubayr refused, so they brought their dispute before the Messenger of Allah ﷺ. The Messenger of Allah ﷺ said to al-Zubayr: “Water your land, O Zubayr, then release the water to your neighbor.” The Anṣārī became angry and said: “Is it because he is your maternal aunt’s son?” The face of the Messenger of Allah ﷺ changed color. He then said: “Water your land, O Zubayr, then retain the water until it reaches the wall.” Al-Zubayr said: “By Allah, I believe this verse was revealed concerning that: ‘But no, by your Lord, they will not truly believe until they make you judge concerning that over which they dispute among themselves.’” [al-Nisāʾ: 65]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2359,"lafz":true},{"key":"muslim","label":"مسلم","number":2357}],"full":1,"dr":1},{"num":6776,"demo":false,"sanad":"","matn":["عن ثَعْلَبَةَ بْنِ أَبِي مَالِكٍ أَنَّهُ سَمِعَ كُبَرَاءَهُمْ، يَذْكُرُونَ أَنَّ رَجُلاً، مِنْ قُرَيْشٍ كَانَ لَهُ سَهْمٌ فِي بَنِي قُرَيْظَةَ فَخَاصَمَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَهْزُورٍ - يَعْنِي السَّيْلَ الَّذِي يَقْتَسِمُونَ مَاءَهُ - فَقَضَى بَيْنَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ الْمَاءَ إِلَى الْكَعْبَيْنِ لاَ يَحْبِسُ الأَعْلَى عَلَى الأَسْفَلِ."],"takhrij":"حسن: رواه أبو داود (3638) عن محمد بن العلاء، حدثنا أبو أسامة، عن الوليد يعني ابن كثير، عن أبي مالك بن ثعلبة، عن أبيه ثعلبة بن مالك فذكره.","grade":"حسن","chapter_ar":"باب القضاء في سقي النخيل","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (3638) and Ibn Majah (2481).","chapter_en":"Judgement regarding irrigation of date palms","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أقضية النبي ﷺ","group_en":"Collection of what has come regarding the judgments of the Prophet ﷺ","part_no":31,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Thaʿlabah ibn Abi Malik reported that he heard their elders mention that a man from Quraysh had a share among Banu Qurayzah, and he brought a dispute before the Messenger of Allah ﷺ regarding Mahzur — meaning the floodwater whose water they divided among themselves. The Messenger of Allah ﷺ judged between them that the water should be kept up to the ankles, and that the upper landowner should not hold it back from the lower one beyond that."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3638,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2481}],"full":1,"dr":1},{"num":6777,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى فِي السَّيْلِ الْمَهْزُورِ أَنْ يُمْسَكَ حَتَّى يَبْلُغَ الْكَعْبَيْنِ ثُمَّ يُرْسِلُ الأَعْلَى."],"takhrij":"حسن: رواه أبو داود (3639) وابن ماجة (2482) عن أحمد بن عبدة، قال: أنبانا المغيرة بن عبد الرحمن، قال: حدثني أبي، عن عمرو بن شعيب فذكره.","grade":"حسن","chapter_ar":"باب القضاء في سقي النخيل","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (3639) and Ibn Majah (2482).","chapter_en":"Judgement regarding irrigation of date palms","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أقضية النبي ﷺ","group_en":"Collection of what has come regarding the judgments of the Prophet ﷺ","part_no":31,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb, from his father, from his grandfather, reported that the Messenger of Allah ﷺ judged concerning the floodwater of Mahzur that it should be held until it reached the ankles, then the water should be released."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3639,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2482}],"full":1,"dr":1},{"num":6778,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ عِنْدَ بَعْضِ نِسَائِهِ، فَأَرْسَلَتْ إِحْدَى أُمَّهَاتِ الْمُؤْمِنِينَ مَعَ خَادِمٍ بِقَصْعَةٍ فِيهَا طَعَامٌ فَضَرَبَتْ بِيَدِهَا، فَكَسَرَتِ الْقَصْعَةَ، فَضَمَّهَا، وَجَعَلَ فِيهَا الطَّعَامَ وَقَالَ كُلُوا. وَحَبَسَ الرَّسُولَ وَالْقَصْعَةَ حَتَّى فَرَغُوا، فَدَفَعَ الْقَصْعَةَ الصَّحِيحَةَ وَحَبَسَ الْمَكْسُورَةَ."],"takhrij":"صحيح: رواه البخاري في موضعين: الشركة (2481) عن مسدد، حدثنا يحيى بن سعيد، وفي النكاح (5225) عن علي، حدثنا ابن علية – كلاهما عن حميد، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب الحكم فيمن كسر شيئا","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (2481) and (5225).","chapter_en":"Judgement regarding one who breaks something","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أقضية النبي ﷺ","group_en":"Collection of what has come regarding the judgments of the Prophet ﷺ","part_no":31,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Anas reported that the Prophet ﷺ was with one of his wives, and one of the Mothers of the Believers sent, through a servant, a bowl containing food. The wife who was with him struck it with her hand and broke the bowl. He gathered its pieces together and placed the food in it, then said: “Eat.” He kept the servant and the bowl until they had finished, then he gave the sound bowl and kept the broken one."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2481,"lafz":true}],"full":1,"dr":1},{"num":6779,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ يَمْنَعُ جَارٌ جَارَهُ أَنْ يَغْرِزَ خَشَبَهُ فِي جِدَارِهِ. ثُمَّ يَقُولُ أَبُو هُرَيْرَةَ مَا لِي أَرَاكُمْ عَنْهَا مُعْرِضِينَ وَاللَّهِ لأَرْمِيَنَّ بِهَا بَيْنَ أَكْتَافِكُمْ."],"takhrij":"متفق عليه: رواه مالك في الأقضية (34) عن ابن شهاب، عن الأعرج، عن أبي هريرة فذكره.وأخرجه البخاري في المظالم (2463) ومسلم في المساقاة (1609) كلاهما من حديث مالك.","grade":"متفق عليه","chapter_ar":"باب القضاء في المرفق","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (34), al-Bukhari (2463), and Muslim (1609).","chapter_en":"Judgement regarding shared utility rights","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أقضية النبي ﷺ","group_en":"Collection of what has come regarding the judgments of the Prophet ﷺ","part_no":31,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “None of you should prevent his neighbor from placing a piece of wood into his wall.” Then Abu Hurayrah would say: “Why do I see you turning away from this? By Allah, I will surely cast it between your shoulders.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":34},{"key":"bukhari","label":"البخاري","number":2463,"lafz":true},{"key":"muslim","label":"مسلم","number":1609}],"full":1,"rep":[14180]},{"num":6780,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يَمْنَعْ أَحَدُكُمْ أخَاهُ مِرْفَقَهُ أَنْ يَضَعَهُ عَلَى جِدَارِهِ."],"takhrij":"حسن: رواه أحمد (2307) عن قتيبة بن سعيد، حدثنا ابن لهيعة، عن أبي الأسود، عن عكرمة، عن ابن عباس فذكره. وإسناده حسن من أجل ابن لهيعة فإنه صدوق إذا روى عنه العبادلة، وقتيبة بن سعيد.","grade":"حسن","chapter_ar":"باب القضاء في المرفق","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (2307) and Ibn Mājah (2337).","chapter_en":"Judgement regarding shared utility rights","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أقضية النبي ﷺ","group_en":"Collection of what has come regarding the judgments of the Prophet ﷺ","part_no":31,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿAbbās reported that the Messenger of Allah ﷺ said: “None of you should prevent his brother from making use of his wall for something from which he may benefit.”"]},"buhuth":{"en":["The wording of Ibn Mājah is:","“None of you should prevent his neighbor from placing a piece of wood upon his wall.”","The word al-mirfaq refers to anything by which benefit or practical use is obtained."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2337,"n":2599},{"key":"ahmad","label":"مسند الإمام أحمد","number":2307,"n":2307,"lafz":true}],"full":1,"dr":1},{"num":6781,"demo":false,"sanad":"","matn":["عَنْ ابْنِ مَسْعُودٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ يَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ، وَأَنِّي رَسُولُ اللَّهِ إِلاَّ بِإِحْدَى ثَلاَثٍ: النفس بِالنَّفْسِ، والثيّب الزَّانِي، وَالتَّارِكُ لِدِينِهِ الْمُفَارِقُ لِلْجَمَاعَةِ."],"takhrij":"متفق عليه: رواه البخاري في الديات (6878) ومسلم في القسامة (1676) كلاهما من طريق الأعمش، عن عبد الله بن مرة، عن مسروق، عن عبد الله بن مسعود فذكره.","grade":"متفق عليه","chapter_ar":"باب لا يحل دم امرى مسلم إلا في ثلاث","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (6878) and Muslim (1676).","chapter_en":"The blood of a Muslim is not lawful except in three cases","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Ibn Masʿūd said: The Messenger of Allah ﷺ said, “The blood of a Muslim who testifies that there is no god but Allah and that I am the Messenger of Allah ﷺ is not lawful except in one of three cases: a life for a life, a previously married adulterer, and the one who abandons his religion and separates from the community.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6878,"lafz":true},{"key":"muslim","label":"مسلم","number":1676}],"full":1},{"num":6782,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ بْنِ سَهْلٍ، قَالَ كُنَّا مَعَ عُثْمَانَ وَهُوَ مَحْصُورٌ فِي الدَّارِ وَكَانَ فِي الدَّارِ مَدْخَلٌ مَنْ دَخَلَهُ سَمِعَ كَلاَمَ مَنْ عَلَى الْبَلاَطِ فَدَخَلَهُ عُثْمَانُ فَخَرَجَ إِلَيْنَا وَهُوَ مُتَغَيِّرٌ لَوْنُهُ فَقَالَ إِنَّهُمْ لَيَتَوَاعَدُونَنِي بِالْقَتْلِ آنِفًا. قُلْنَا يَكْفِيكَهُمُ اللَّهُ يَا أَمِيرَ الْمُؤْمِنِينَ. قَالَ وَلِمَ يَقْتُلُونَنِي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ لاَ يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ إِلاَّ بِإِحْدَى ثَلاَثٍ كُفْرٌ بَعْدَ إِسْلاَمٍ أَوْ زِنًا بَعْدَ إِحْصَانٍ أَوْ قَتْلُ نَفْسٍ بِغَيْرِ نَفْسٍ. فَوَاللَّهِ مَا زَنَيْتُ فِي جَاهِلِيَّةٍ وَلاَ إِسْلاَمٍ قَطُّ وَلاَ أَحْبَبْتُ أَنَّ لِي بِدِينِي بَدَلاً مُنْذُ هَدَانِي اللَّهُ وَلاَ قَتَلْتُ نَفْسًا فَبِمَ يَقْتُلُونَنِي."],"takhrij":"صحيح: رواه أبو داود (4502) والترمذي (2158) والنسائي (4019) وابن ماجة (2533) وابن الجارود (836) وأحمد (437) وصحّحه الحاكم (4/350) كلهم من حديث حماد بن زيد، عن يحيى بن سعيد الأنصاري، عن أبي أمامة بن سهل بن حنيف قال: فذكره.","grade":"صحيح","chapter_ar":"باب لا يحل دم امرى مسلم إلا في ثلاث","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4502), al-Tirmidhī (2158), who graded it good, al-Nasā’ī (4019), and Ibn Mājah (2533).","chapter_en":"The blood of a Muslim is not lawful except in three cases","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abū Umāmah ibn Sahl reported: We were with ʿUthmān while he was besieged in his house. There was an entrance in the house through which whoever entered could hear the speech of those outside on the paved area. ʿUthmān entered it and then came out to us with his complexion changed. He said: “They have just threatened to kill me.” We said: “Allah will suffice you against them, O Commander of the Believers.” He said: “Why would they kill me? I heard the Messenger of Allah ﷺ say: ‘The blood of a Muslim is not lawful except in one of three cases: disbelief after Islam, adultery after having been married, or killing a person without a right of retaliation.’ By Allah, I never committed adultery either in the pre-Islamic period or in Islam; I have never wished to exchange my religion for another since Allah guided me; and I have never killed anyone. So for what reason would they kill me?”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4502,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":2158},{"key":"nasai","label":"النسائي","number":4019},{"key":"ibnmajah","label":"ابن ماجه","number":2533},{"key":"sh13071","label":"ابن الجارود","number":836,"n":870},{"key":"ahmad","label":"احمد","number":437}],"full":1,"dr":1},{"num":6783,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ: أَنَّ عُثْمَانَ أَشْرَفَ عَلَى أَصْحَابِهِ وَهُوَ مَحْصُورٌ، فَقَالَ: عَلامَ تَقْتُلُونِي؟ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: لَا يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ إِلَّا بِإِحْدَى ثَلاثٍ: رَجُلٌ زَنَى بَعْدَ إِحْصَانِهِ فَعَلَيْهِ الرَّجْمُ، أَوْ قَتَلَ عَمْدًا فَعَلَيْهِ الْقَوَدُ، أَوِ ارْتَدَّ بَعْدَ إِسْلامِهِ فَعَلَيْهِ الْقَتْلُ، فَوَاللهِ مَا زَنَيْتُ فِي جَاهِلِيَّةٍ وَلا إِسْلامٍ، وَلا قَتَلْتُ أَحَدًا فَأُقِيدَ نَفْسِي مِنْهُ، وَلا ارْتَدَدْتُ مُنْذُ أَسْلَمْتُ، إِنِّي أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ."],"takhrij":"حسن: رواه أحمد (452) واللفظ له، والنسائي (4057) والبزار في مسنده (2/9) وأبو عاصم في الديات (111) مختصراً- كلهم من حديث إسحاق بن سليمان الرازي، قال: سمعت المغيرة بن مسلم، يحدث عن مطر الوراق، عن نافع، عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب لا يحل دم امرى مسلم إلا في ثلاث","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Aḥmad (452), and this is his wording, al-Nasā’ī (4057), al-Bazzār in his Musnad (9/2), and Abū ʿĀṣim in al-Diyāt (111).","chapter_en":"The blood of a Muslim is not lawful except in three cases","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Ibn ʿUmar reported that ʿUthmān looked out over his companions while under siege and said, “Why are you killing me? I heard the Messenger of Allah ﷺ say: ‘The blood of a Muslim is not lawful except in one of three cases: a man who commits adultery after marriage, so he is to be stoned; one who kills deliberately, so retaliation is due from him; or one who apostasizes after Islam, so he is to be killed.’ By Allah, I never committed adultery in ignorance or in Islam, nor have I killed anyone such that retaliation would be due from me, nor have I apostatized since I accepted Islam. I testify that there is no god but Allah and that Muhammad is His servant and Messenger.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4057},{"key":"bazzar","label":"البزار في مسنده","number":9},{"key":"rb280","label":"أبو عاصم في الديات","number":111},{"key":"ahmad","label":"مسند الإمام أحمد","number":452,"n":452,"lafz":true}],"full":1,"dr":1},{"num":6784,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بن مَالِكٍ قَالَ: بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَرِيَّةً، قَالَ: فَأَغَارَتْ عَلَى قَوْمٍ، قَالَ: فَشَذَّ مِنَ الْقَوْمِ رَجُلٌ، قَالَ: فَأَتْبَعَهُ رَجُلٌ مِنَ السَّرِيَّةِ شَاهِرًا سَيْفَهُ، قَالَ: فَقَالَ الشَّاذُّ مِنَ الْقَوْمِ، إِنِّي مُسْلِمٌ، قَالَ: فَلَمْ يَنْظُرْ فِيمَا قَالَ، فَضَرَبَهُ فَقَتَلَهُ، قَالَ: فنمي الْحَدِيثُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، قَالَ: فَقَالَ فِيهِ قَوْلًا شَدِيدًا، فَبَلَغَ الْقَاتِلَ، قَالَ: فَبَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ إِذْ قَالَ الْقَاتِلُ: يَا رَسُولَ اللَّهِ، وَاللهِ مَا قَالَ الَّذِي قَالَ إِلَّا تَعَوُّذًا مِنَ الْقَتْلِ. قَالَ: فَأَعْرَضَ عَنْهُ، وَعَمَّنْ قِبَلَهُ مِنَ النَّاسِ، وَأَخَذَ فِي خُطْبَتِهِ، ثُمَّ قَالَ أَيْضًا: يَا رَسُولَ اللَّهِ، مَا قَالَ الَّذِي قَالَ إِلَّا تَعَوُّذًا مِنَ الْقَتْلِ. فَأَعْرَضَ عَنْهُ وَعَمَّنْ قِبَلَهُ مِنَ النَّاسِ وَأَخَذَ فِي خُطْبَتِهِ، ثُمَّ لَمْ يَصْبِرْ، فَقَالَ الثَّالِثَةَ: يَا رَسُولَ اللَّهِ، وَاللهِ مَا قَالَ إِلَّا تَعَوُّذًا مِنَ الْقَتْلِ. فَأَقْبَلَ عَلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – تُعْرَفُ الْمَسَاءَةُ فِي وَجْهِهِ. فَقَالَ لَهُ: إِنَّ اللَّهَ عَزَّ وَجَلَّ أَبَى عليّ أن أقتل مُؤْمِنًا."],"takhrij":"صحيح: رواه الإمام أحمد (22490) وأبو يعلى (6829) والطبراني (17/355) وابن أبي عاصم في الديات (40) وصحّحه ابن حبان (5972) كلهم من حديث سليمان بن المغيرة، حدثنا حميد بن هلال، قال: أتاني أبو العالية وصاحب لي، فقال: هلّما، فإنكما أشب شباباً، وأوعى للحديث مني. فانطلقنا حتى أتينا بشر بن عاصم الليثي. قال أبو العالية: حدّث هذين. قال بشر: حدثنا عقبة بن مالك – وكان من رهطه – قال: بعث رسول الله صلى الله عليه وسلم سرية. فذكر الحديث.","grade":"صحيح","chapter_ar":"باب لا يحل دم امرى مسلم إلا في ثلاث","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Imām Aḥmad (22490), Abū Yaʿlā (6829), al-Ṭabarānī (17/355), and Ibn Abī ʿĀṣim in al-Diyāt (40).","chapter_en":"The blood of a Muslim is not lawful except in three cases","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["ʿUqbah ibn Mālik said: The Messenger of Allah ﷺ sent a military detachment. It raided a people, and one man from them fled. A man from the detachment pursued him with his sword drawn. The fleeing man said, “I am Muslim.” But he paid no attention to what he said and struck him, killing him. The report reached the Messenger of Allah ﷺ, and he spoke very sternly about it. This reached the killer. Then while the Messenger of Allah ﷺ was delivering a sermon, the killer said, “O Messenger of Allah ﷺ, by Allah, he only said what he said to seek protection from being killed.” The Prophet ﷺ turned away from him and from the people in front of him and continued his sermon. Then he said again, “O Messenger of Allah ﷺ, he only said it to escape being killed.” The Prophet ﷺ again turned away from him and continued. Then he could not restrain himself and said it a third time. The Messenger of Allah ﷺ then turned to him, with displeasure visible on his face, and said, “Allah, Mighty and Majestic, has refused to allow me to kill a believer.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":22490,"lafz":true},{"key":"sh12520","label":"أبو يعلى","number":6829},{"key":"mujamkabir","label":"الطبراني","number":355},{"key":"rb280","label":"ابن أبي عاصم في الديات","number":40},{"key":"ibnhibban","label":"ابن حبان","number":5972}],"full":1,"dr":1},{"num":6785,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عدي الأنصاري حدّث أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَا هُوَ جَالِسٌ بَيْنَ ظَهْرَانَيِ النَّاسِ جَاءَهُ رَجُلٌ يَسْتَأْذِنُهُ – أَوْ يشاوره – يُسَارَّهُ فِي قَتْلِ رَجُلٍ مِنَ الْمُنَافِقِينَ يَسْتَأْذِنُ فِيهِ. فَجَهَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِكَلَامِهِ فَقَالَ: أَلَيْسَ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ قَالَ: بَلَى، ولكن لَا شَهَادَةَ لَهُ، قَالَ: أَلَيْسَ يَشْهَدُ أني رَسُولُ اللَّهِ؟ قَالَ: بَلَى، وَلَا شَهَادَةَ لَهُ، قَالَ: أَلَيْسَ يُصَلِّي؟ قَالَ: بَلَى، وَلَا صَلَاةَ لَهُ، قَالَ: أُولَئِكَ الَّذِينَ نُهِيتُ عَنْهُمْ."],"takhrij":"صحيح: رواه الإمام أحمد (23671) والبيهقي (8/196) وصحّحه ابن حبان (5971) كلهم من حديث عبد الرزاق (18688) عن معمر، عن الزهري، عن عطاء بن يزيد، عن عبيد الله بن عدي بن الخيار، عن عبد الله بن عدي فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب لا يحل دم امرى مسلم إلا في ثلاث","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Imām Aḥmad (23671), al-Bayhaqī (8/196), and authenticated by Ibn Ḥibbān (5971).","chapter_en":"The blood of a Muslim is not lawful except in three cases","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAdī al-Anṣārī narrated that while the Messenger of Allah ﷺ was sitting among the people, a man came to him seeking permission, or consulting him privately, about killing a certain hypocrite. The Messenger of Allah ﷺ then spoke aloud and said, “Does he not testify that there is no god but Allah?” He said, “Yes, but his testimony carries no weight.” He said, “Does he not testify that I am the Messenger of Allah ﷺ?” He said, “Yes, but his testimony carries no weight.” He said, “Does he not pray?” He said, “Yes, but there is no prayer in him.” He said, “Those are the ones I have been forbidden to kill.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":23671,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":196},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":5971},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":6502,"n":6536},{"key":"abdrazzaq","label":"عبد الرزاق","number":18688}],"full":1,"dr":1},{"num":6786,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِمُخَنَّثٍ قَدْ خَضَبَ يَدَيْهِ وَرِجْلَيْهِ بِالْحِنَّاءِ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا بَالُ هَذَا. فَقِيلَ يَا رَسُولَ اللَّهِ يَتَشَبَّهُ بِالنِّسَاءِ. فَأُمِرَ بِهِ فَنُفِيَ إِلَى النَّقِيعِ فَقَالُوا يَا رَسُولَ اللَّهِ أَلاَ نَقْتُلُهُ فَقَالَ إِنِّي نُهِيتُ عَنْ قَتْلِ الْمُصَلِّينَ."],"takhrij":"حسن: رواه أبو داود (4928) وأبو يعلى (6126) والبيهقي (8/222) كلهم من حديث أبي أسامة أخبرهم، عن مفضل بن يونس، عن الأوزاعي، عن أبي يسار القرشي، عن أبي هاشم، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب لا يحل دم امرى مسلم إلا في ثلاث","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abū Dāwūd (4928), Abū Yaʿlā (6126), and al-Bayhaqī (8/222).","chapter_en":"The blood of a Muslim is not lawful except in three cases","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ was brought a feminine man whose hands and feet had been dyed with henna. The Messenger of Allah ﷺ said, “What is the matter with this one?” It was said, “O Messenger of Allah ﷺ, he imitates women.” So he ordered that he be banished to al-Naqīʿ. They said, “O Messenger of Allah ﷺ, should we not kill him?” He said, “I have been forbidden from killing those who pray.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4928,"lafz":true},{"key":"sh12520","label":"أبو يعلى","number":6126},{"key":"kubrabayhaqi","label":"البيهقي","number":222},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":16987,"n":17145}],"full":1,"dr":1,"rep":[15032]},{"num":6787,"demo":false,"sanad":"","matn":["عن سعيد بن جبير قال: أمرني عبد الرحمن بن أبزى قال: سل ابن عباس عن هاتين الآيتــين ما أمرهمـا: ﴿وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ﴾ [الأنعام: ١٥١، الإسراء:33] وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا [النساء: ٩٣ ] فسألت ابن عباس فقال: لما أنزلت التي في الفرقان وهي قوله تعالى: ﴿وَالَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا﴾ [الفرقان:٦٨] قال مشركوا أهل مكة: فقد قتلنا النفس التي حرم الله، ودعونا مع الله إلها آخر. وقد أتينا الفواحش فأنزل الله تعالى: ﴿إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُولَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ وَكَانَ اللَّهُ غَفُورًا رَحِيمًا﴾ [الفرقان: ٧٠] فهذه لأولئك، وأما التي في النساء: [93] فالرجل إذا عرف الإسلام وشرائعه، ثم قتل فجزاؤه جهنم. فذكرته لمجاهد فقال: إلا من ندم."],"takhrij":"متفق عليه: رواه البخاري في المناقب (3855)، عن عثمان بن أبي شيبة، حدثنا جرير، عن منصور، حدثني سعيد بن جبير أو قال: حدثني الحكم عن سعيد بن جبير قال: أمرني عبد الرحمن بن أبزى فذكره.","grade":"متفق عليه","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (3855) and Muslim (3023, no. 18).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Saʿīd ibn Jubayr said: ʿAbd al-Raḥmān ibn Abzā instructed me, saying: Ask Ibn ʿAbbās about these two verses and what their ruling is: “Do not kill the soul which Allah has forbidden” [al-Anʿām: 151; al-Isrāʾ: 33] and “Whoever kills a believer intentionally…” [al-Nisāʾ: 93]. So I asked Ibn ʿAbbās. He said: When the verse in Sūrat al-Furqān was revealed—“Those who do not call upon another god with Allah, nor kill the soul which Allah has forbidden except with right, nor commit adultery…” [al-Furqān: 68]—the polytheists of Makkah said: We have killed the soul Allah has forbidden, called upon another god besides Allah, and committed immoral deeds. So Allah revealed: “Except for those who repent, believe, and do righteous deeds; for them Allah will replace their evil deeds with good deeds, and Allah is Ever-Forgiving, Most Merciful.” [al-Furqān: 70] This was for them. But as for the verse in Sūrat al-Nisāʾ [93], it concerns the man who knew Islam and its laws and then killed; his recompense is Hell. I mentioned this to Mujāhid, and he said: except the one who repents."]},"intro":{"ar":["قال اللّٰه تعالى: (وَمَن يَقَّتُّلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَآؤُهُ جَهَنَّمُ خَٰلِدًا فِيهَا وَعَضِبَ اللَّهُ عَيدِوَنَهُ وَأَعَدَّلَهُ عَذَابًا عَظِيمًا [سورة النساء: ٩٣ )","وقال تعالى: (وَٱلّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إلَهَا ءَاخَرَ وَلَا يَقْتُلُونَ ٱلنَّفْسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُنٌ وَمَن يَفْعَلْ ذَٰلِكَ يَلْقَ أَئَامًا (٦ يُضَعَفْ لَهُ ٱلْعَذَابُ يَوْمَ ٱلْقِيَمَةِ وَيَخْلُدْ فِيهِ مُهَانًا (١) إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلًا صَالِحًا) [ الفرقان: ٧٠ - ٦٨]"],"en":["Allah Most High said: “Whoever kills a believer intentionally, his recompense is Hell, abiding therein; and Allah is angry with him, has cursed him, and prepared for him a tremendous punishment.” [Sūrat al-Nisāʾ: 93]","And He said: “Those who do not call upon another god with Allah, nor kill the soul which Allah has forbidden except with right, nor commit adultery. Whoever does that will meet a penalty. The punishment will be multiplied for him on the Day of Resurrection, and he will abide therein humiliated, except for those who repent, believe, and do righteous deeds.” [Sūrat al-Furqān: 68–70]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3855,"lafz":true},{"key":"muslim","label":"مسلم","number":18}],"full":1,"dr":1},{"num":6788,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ اخْتَلَفَ أَهْلُ الْكُوفَةِ فِي هَذِهِ الآيَةِ ﴿وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ﴾ [سورة النساء: 93]} فَرَحَلْتُ إِلَى ابْنِ عَبَّاسٍ فَسَأَلْتُهُ عَنْهَا فَقَالَ لَقَدْ أُنْزِلَتْ آخِرَ مَا أُنْزِلَ ثُمَّ مَا نَسَخَهَا شَىْءٌ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4590) ومسلم في التفسير (3032) كلاهما من حديث شعبة، حدثنا مغيرة بن النعمان، قال: سمعت سعيد بن جبير فذكره.","grade":"متفق عليه","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (4590) and Muslim (3032).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Saʿīd ibn Jubayr said: The people of Kūfah differed concerning this verse: “Whoever kills a believer intentionally, his recompense is Hell…” [al-Nisāʾ: 93]. So I traveled to Ibn ʿAbbās and asked him about it. He said: It was among the last things revealed, and nothing abrogated it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4590,"lafz":true},{"key":"muslim","label":"مسلم","number":3032,"n":7541}],"full":1,"rep":[11739]},{"num":6789,"demo":false,"sanad":"","matn":["عن سعيد بن جبير قال: قلت لابن عباس: ألمن قتل مؤمنا متعمدا من توبة؟ قال: لا. قال: فتلوت عليه هذه الآية التي في الفرقان: ﴿وَالَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ﴾ [الفرقان: ٦٨] إلى آخر الآية قال: هذه آية مكية، نسختها آية مدنية  ﴿وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ خَالِدًا﴾ [سورة النساء: ٩٣]."],"takhrij":"متفق عليه: رواه مسلم في التفسير (20:3023) من طريق يحيى بن سعيد القطان، عن ابن جريج، حدثني القاسم بن أبي بزّة، عن سعيد بن جبير قال: فذكره. ورواه البخاري في التفسير (4762) من وجه آخر عن ابن جريج مختصرا.","grade":"متفق عليه","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by Muslim (3023, no. 20) and al-Bukhārī (4762).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Saʿīd ibn Jubayr said: I asked Ibn ʿAbbās, “Is there repentance for the one who kills a believer intentionally?” He said, “No.” I then recited to him the verse in Sūrat al-Furqān: “Those who do not call upon another god with Allah, nor kill the soul which Allah has forbidden except with right…” [al-Furqān: 68] through the end of the passage. He said: That is a Makkan verse, and it was superseded by the Madinan verse: “Whoever kills a believer intentionally, his recompense is Hell, abiding therein.” [al-Nisāʾ: 93]"]},"buhuth":{"en":["Al-Nawawī said in his commentary on Muslim: This is the well-known view reported from Ibn ʿAbbās. It is also reported from him that such a person may repent, and that forgiveness is possible, based on the saying of Allah Most High: “Whoever does evil or wrongs himself, then seeks Allah’s forgiveness, will find Allah Forgiving and Merciful.” [al-Nisāʾ: 110] This second narration is the position of all the people of Sunnah, the Companions, the Followers, and those after them. Whatever has been reported from some of the early Muslims contrary to this is understood as severe warning and deterrence from killing, and not as an absolute denial of repentance. Moreover, the verse cited by Ibn ʿAbbās does not explicitly state that he will certainly remain forever; it only says that Hell is his recompense, and that does not necessarily mean the recompense must be executed. Others said that the verse, “Whoever kills a believer intentionally,” is general and should be understood as referring to the one who does not repent, since the other verse is restricted by repentance. Also, Allah Most High said: “Indeed, Allah does not forgive associating partners with Him, but He forgives what is less than that for whom He wills.” [al-Nisāʾ: 48] Thus non-forgiveness is confined to polytheism alone."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":20,"lafz":true},{"key":"bukhari","label":"البخاري","number":4762}],"full":1,"dr":1},{"num":6790,"demo":false,"sanad":"","matn":["عن ابن عباس أن قوماً كانوا قتلوا – فأكثروا، وزنوا فأكثروا، وانتهكوا، فأتوا النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فقالوا: يا محمد! إن الذي تقول وتدعو إليه لحسن، أو تُخبرنا أن لما عملنا كفارةٌ. فأنزل الله عز وجل: ﴿وَالَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا (68) يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ وَيَخْلُدْ فِيهِ مُهَانًا (69) إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُولَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ﴾ [الفرقان: ٦٨ - ٧٠ ] قال: \"يبدل الله شركهم إيماناً، وزناهم إحصاناً\".","ونزلت: قُلْ يَا ﴿عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لَا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ﴾ [سورة الزمر: 53]"],"takhrij":"حسن: أخرجه النسائي (4003) عن حاجب بن سليمان المنبجي، قال: حدثنا ابن أبي روّاد، قال: حدثنا ابن جريج، عن عبد الأعلى الثعلبي، عن سعيد بن جبير، عن ابن عباس قال: فذكره.","grade":"حسن","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: recorded by al-Nasā’ī (4003) and al-Ḥākim (3522).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿAbbās said: Some people had committed many killings, much adultery, and many grave violations. Then they came to the Prophet ﷺ and said: “O Muhammad, what you say and call to is good. If only you could tell us whether there is an expiation for what we have done.” So Allah, Mighty and Majestic, revealed: “Those who do not call upon another god with Allah, nor kill the soul which Allah has forbidden except with right, nor commit adultery… except for those who repent, believe, and do righteous deeds; for them Allah will replace their evil deeds with good deeds.” [al-Furqān: 68–70] He said: Allah would replace their polytheism with faith, and their adultery with chastity. And this was also revealed: “Say: O My servants who have transgressed against themselves, do not despair of the mercy of Allah. Indeed, Allah forgives all sins. Truly He is the Forgiving, the Merciful.” [al-Zumar: 53]"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4003,"lafz":true},{"key":"hakim","label":"الحاكم","number":3522}],"full":1,"dr":1},{"num":6791,"demo":false,"sanad":"","matn":["رَضِيَ اللَّهُ عَنْهُمَا ـ قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَنْ يَزَالَ الْمُؤْمِنُ فِي فُسْحَةٍ مِنْ دِينِهِ، مَا لَمْ يُصِبْ دَمًا حَرَامًا."],"takhrij":"صحيح: رواه البخاري في الديات (6862)، عن علي (هو ابن الجعد) حدثنا إسحاق بن سعيد بن عمرو بن سعيد بن العاص، عن أبيه، عن ابن عمر، فذكره، ورواه البخاري أيضا من قول ابن عمر: إن من ورطات الأمور التي لا مخرج لمن أوقع نفسه فيها الدم الحرام بغير حله (6862)","grade":"صحيح","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhārī (6862).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar said: The Messenger of Allah ﷺ said, “A believer remains within spaciousness in his religion so long as he does not shed unlawful blood.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6862,"lafz":true}],"full":1},{"num":6792,"demo":false,"sanad":"","matn":["عن عبد الله بن عمرو قال: قال رسول الله صلى الله عليه وسلم: أكبر الكبائر الإشراك بالله، وقتل النفس، وعقوق الوالدين."],"takhrij":"صحيح: رواه البخاري في الديات (6870) عن محمد بن بشار، حدثنا محمد بن جعفر، حدثنا شعبة، عن فراس، عن الشعبي، عن عبد الله بن عمرو فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhārī (6870).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr said: The Messenger of Allah ﷺ said, “The greatest of the major sins are associating partners with Allah, killing a soul, and disobeying one’s parents.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6870,"lafz":true}],"full":1,"dr":1},{"num":6793,"demo":false,"sanad":"","matn":["عَنْ أَبِي أَيُّوبَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ جَاءَ يَعْبُدُ اللَّهَ، لَا يُشْرِكُ بِهِ شَيْئًا، وَيُقِيمُ الصَّلَاةَ، وَيُؤْتِي الزَّكَاةَ، وَيَصُومُ رَمَضَانَ، وَيَجْتَنِبُ الْكَبَائِرَ فَإِنَّ لَهُ الْجَنَّةَ وَسَأَلُوهُ ماالكبائر؟ قَالَ: الْإِشْرَاكُ بِاللهِ، وَقَتْلُ النَّفْسِ الْمُسْلِمَةِ، وَفِرَارٌ يَوِمَ الزَّحْفِ."],"takhrij":"حسن: رواه النسائي (4009) وأحمد (23502) والطحاوي في مشكله (896) كلهم من طرق عن بقية بن الوليد، حدثني بحير بن سعد، عن خالد بن معدان، حدثنا أبو رُهم السمعي، أن أبا أيوب حدّثه فذكر الحديث.","grade":"حسن","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasā’ī (4009), Aḥmad (23502), and al-Ṭaḥāwī in Mushkil al-Āthār (896).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abū Ayyūb reported that the Messenger of Allah ﷺ said, “Whoever comes worshipping Allah without associating anything with Him, establishes prayer, gives zakāh, fasts Ramadan, and avoids the major sins will have Paradise.” They asked him, “What are the major sins?” He said, “Associating partners with Allah, killing a Muslim soul, and fleeing on the day of battle.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4009,"lafz":true},{"key":"sh22547","label":"الطحاوي في مشكله","number":896},{"key":"ahmad","label":"مسند الإمام أحمد","number":23502,"n":23502}],"full":1,"dr":1},{"num":6794,"demo":false,"sanad":"","matn":["عَنِ الأَحْنَفِ بْنِ قَيْسٍ، قَالَ ذَهَبْتُ لأَنْصُرَ هَذَا الرَّجُلَ، فَلَقِيَنِي أَبُو بَكْرَةَ فَقَالَ أَيْنَ تُرِيدُ قُلْتُ أَنْصُرُ هَذَا الرَّجُلَ. قَالَ ارْجِعْ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ إِذَا الْتَقَى الْمُسْلِمَانِ بِسَيْفَيْهِمَا فَالْقَاتِلُ وَالْمَقْتُولُ فِي النَّارِ. فَقُلْتُ يَا رَسُولَ اللَّهِ هَذَا الْقَاتِلُ فَمَا بَالُ الْمَقْتُولِ قَالَ إِنَّهُ كَانَ حَرِيصًا عَلَى قَتْلِ صَاحِبِهِ."],"takhrij":"متفق عليه: رواه البخاري في الإيمان (31) ومسلم في الفتن (2888) كلاهما من حديث حماد بن زيد، حدثنا أيوب ويونس، عن الحسن، عن الأحنف بن قيس فذكره.","grade":"متفق عليه","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhārī (31) and Muslim (2888). Muslim also narrated by another route with the wording: “When two Muslims raise weapons against one another, both are on the brink of Hell; if one kills the other, they both enter it.”","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["al-Aḥnaf ibn Qays said: I went out intending to support this man, but Abū Bakrah met me and said, “Where are you going?” I said, “To support this man.” He said, “Go back, for I heard the Messenger of Allah ﷺ say: ‘When two Muslims confront each other with their swords, both the killer and the one killed are in the Fire.’” I said, “O Messenger of Allah ﷺ, this is the killer—but what about the one killed?” He said, “He was eager to kill his companion.”"]},"buhuth":{"en":["Al-Nawawī, may Allah have mercy on him, said in his commentary on Muslim: Know that the bloodshed that occurred among the Companions, may Allah be pleased with them, is not included in this warning. The position of the people of Sunnah, and the truth, is to maintain good opinion of them, refrain from discussing the conflicts that took place among them, and interpret their fighting as the result of sincere legal reasoning."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":31,"lafz":true},{"key":"muslim","label":"مسلم","number":2888}],"full":1,"dr":1},{"num":6795,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ الحِمَق الخزاعي قَالَ: سَمِعْتُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ أَمِنَ رَجُلاً عَلَى دَمِهِ، فَقَتَلَهُ، فَإِنَّهُ يَحْمِلُ لِوَاءَ غدْر يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه ابن ماجة (2688)، وأحمد (21946) كلاهما من حديث عبد الملك بن عمير، عن رفاعة بن شداد الفِتياني قال: لو لا كلمة سمعتها من عمرو بن الحمق لمشيت فيما بين رأس المختار وجسده. فذكر الحديث. هذا لفظ ابن ماجة.","grade":"صحيح","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Mājah (2688) and Aḥmad (21946), with the wording here from Ibn Mājah.","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["ʿAmr ibn al-Ḥimaq al-Khuzāʿī said: I heard the Messenger of Allah ﷺ say, “Whoever grants a man safety regarding his life and then kills him will carry the banner of treachery on the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2688,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":21946,"n":21946}],"full":1,"dr":1},{"num":6796,"demo":false,"sanad":"","matn":["عَنْ خَالِدِ بْنِ دِهْقَانَ، قَالَ كُنَّا فِي غَزْوَةِ الْقُسْطَنْطِينِيَّةِ بِذُلُقْيَةَ فَأَقْبَلَ رَجُلٌ مِنْ أَهْلِ فِلَسْطِينَ - مِنْ أَشْرَافِهِمْ وَخِيَارِهِمْ يَعْرِفُونَ ذَلِكَ لَهُ يُقَالُ لَهُ هَانِئُ بْنُ كُلْثُومِ بْنِ شَرِيكٍ الْكِنَانِيُّ - فَسَلَّمَ عَلَى عَبْدِ اللَّهِ بْنِ أَبِي زَكَرِيَّا وَكَانَ يَعْرِفُ لَهُ حَقَّهُ قَالَ لَنَا خَالِدٌ فَحَدَّثَنَا عَبْدُ اللَّهِ بْنُ أَبِي زَكَرِيَّا قَالَ سَمِعْتُ أُمَّ الدَّرْدَاءِ تَقُولُ سَمِعْتُ أَبَا الدَّرْدَاءِ يَقُولُ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ كُلُّ ذَنْبٍ عَسَى اللَّهُ أَنْ يَغْفِرَهُ إِلاَّ مَنْ مَاتَ مُشْرِكًا أَوْ مُؤْمِنٌ قَتَلَ مُؤْمِنًا مُتَعَمِّدًا. فَقَالَ هَانِئُ بْنُ كُلْثُومٍ سَمِعْتُ مَحْمُودَ بْنَ الرَّبِيعِ يُحَدِّثُ عَنْ عُبَادَةَ بْنِ الصَّامِتِ أَنَّهُ سَمِعَهُ يُحَدِّثُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ مَنْ قَتَلَ مُؤْمِنًا فَاعْتَبَطَ بِقَتْلِهِ لَمْ يَقْبَلِ اللَّهُ مِنْهُ صَرْفًا وَلاَ عَدْلاً. قَالَ لَنَا خَالِدٌ ثُمَّ حَدَّثَنِي ابْنُ أَبِي زَكَرِيَّا عَنْ أُمِّ الدَّرْدَاءِ عَنْ أَبِي الدَّرْدَاءِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ يَزَالُ الْمُؤْمِنُ مُعْنِقًا صَالِحًا مَا لَمْ يُصِبْ دَمًا حَرَامًا فَإِذَا أَصَابَ دَمًا حَرَامًا بَلَّحَ. وَحَدَّثَ هَانِئُ بْنُ كُلْثُومٍ عَنْ مَحْمُودِ بْنِ الرَّبِيعِ عَنْ عُبَادَةَ بْنِ الصَّامِتِ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِثْلَهُ سَوَاءً."],"takhrij":"صحيح: رواه أبو داود (4270) وابن حبان (5980) والحاكم (4/351) والبيهقي (8/21) وابن أبي عاصم في الديات (29) كلهم من حديث خالد بن دهقان قال:فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abū Dāwūd (4270), authenticated by Ibn Ḥibbān (5980) and al-Ḥākim (4/351), and also by Ibn Abī ʿĀṣim in al-Diyāt (29).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Khālid ibn Dihqān said: We were on the campaign to Constantinople at Dhalqiyyah when a man from the people of Palestine approached. He was one of their nobles and best men, known among them for that, and he was called Hānī ibn Kulthūm ibn Sharīk al-Kinānī. He greeted ʿAbdullāh ibn Abī Zakariyyā, who was recognized as having a right over him. Khālid said: Then ʿAbdullāh ibn Abī Zakariyyā narrated to us, saying: I heard Umm al-Dardāʾ say: I heard Abū al-Dardāʾ say: I heard the Messenger of Allah ﷺ say, “Every sin may be forgiven by Allah, except for one who dies as a polytheist, or one who kills a believer deliberately.” Then Hānī ibn Kulthūm said: I heard Maḥmūd ibn al-Rabīʿ narrating from ʿUbādah ibn al-Ṣāmit that he heard the Messenger of Allah ﷺ say, “Whoever kills a believer and is pleased with having killed him, Allah will not accept from him any compensation or ransom.” Khālid said: Then Ibn Abī Zakariyyā also narrated to me from Umm al-Dardāʾ, from Abū al-Dardāʾ, that the Messenger of Allah ﷺ said, “A believer continues advancing in goodness so long as he does not shed unlawful blood; once he sheds unlawful blood, he is ruined.” And Hānī ibn Kulthūm narrated from Maḥmūd ibn al-Rabīʿ, from ʿUbādah ibn al-Ṣāmit, from the Messenger of Allah ﷺ, something to the same effect."]},"buhuth":{"en":["The phrase “he is ruined” means that a person becomes exhausted and cut off, unable to move onward. The intended meaning is that he falls into destruction by shedding unlawful blood.","Khālid ibn Dihqān said: I asked Yaḥyā ibn Yaḥyā al-Ghassānī about the phrase “and is pleased with killing him.” He said: It refers to those who fight during civil strife, and one of them kills another while thinking he is rightly guided, so he does not seek Allah’s forgiveness for it. Abū Dāwūd mentioned this (4271) and said it means he pours out his blood deliberately."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4270,"lafz":true},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":5980},{"key":"hakim","label":"الحاكم","number":351},{"key":"rb280","label":"ابن أبي عاصم في الديات","number":29}],"full":1,"dr":1},{"num":6797,"demo":false,"sanad":"","matn":["عَنْ مُعَاوِيَةَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ يَقُولُ: كُلُّ ذَنْبٍ عَسَى اللَّهُ أَنْ يَغْفِرَهُ إِلاَّ الرَّجُلُ يَقْتُلُ الْمُؤْمِنَ مُتَعَمِّدًا، أَوِ الرَّجُلُ يَمُوتُ كَافِرًا."],"takhrij":"حسن: رواه النسائي (3984) وأحمد (16907) وابن أبي عاصم في الديات (27) وصحّحه الحاكم (4/351) كلهم من حديث صفوان بن عيسى، عن ثور، عن أبي عون، عن أبي إدريس، قال: سمعت معاوية يخطب- وكان قليل الحديث - قال: سمعته يخطب يقول: سمعت رسول الله صلى الله عليه وسلم يقول: فذكر الحديث.","grade":"حسن","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasā’ī (3984), Aḥmad (16907), and Ibn Abī ʿĀṣim in al-Diyāt (27), and authenticated by al-Ḥākim (4/351).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Muʿāwiyah said: I heard the Messenger of Allah ﷺ say, “Every sin may be forgiven by Allah except for a man who kills a believer deliberately, or a man who dies as a disbeliever.”"]},"buhuth":{"en":["The apparent meaning of this report agrees with the Qur’an, and a number of the early scholars held to it. The majority, however, understood it as severe warning, based on the verse: “Indeed, Allah does not forgive associating partners with Him, but He forgives what is less than that for whom He wills.” [al-Nisāʾ: 116]"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3984,"lafz":true},{"key":"rb280","label":"ابن أبي عاصم في الديات","number":27},{"key":"hakim","label":"صحّحه الحاكم","number":351},{"key":"ahmad","label":"مسند الإمام أحمد","number":16907,"n":16907}],"full":1,"dr":1},{"num":6798,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ لَقِيَ اللَّهَ لاَ يُشْرِكُ بِهِ شَيْئًا لَمْ يَتَنَدَّ بِدَمٍ حَرَامٍ دَخَلَ الْجَنَّةَ."],"takhrij":"صحيح: رواه ابن ماجة (2618) وأحمد (17381) وصحّحه الحاكم (4/351-352) كلهم من طريق وكيع، عن إسماعيل بن أبي خالد، عن عبد الرحمن بن عائذ، عن عقبة بن عامر فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Mājah (2618) and Aḥmad (17381), and authenticated by al-Ḥākim (4/351–352).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir al-Juhanī said: The Messenger of Allah ﷺ said, “Whoever meets Allah without associating anything with Him and without staining himself with unlawful blood will enter Paradise.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2618,"lafz":true},{"key":"hakim","label":"صحّحه الحاكم","number":352},{"key":"ahmad","label":"مسند الإمام أحمد","number":17381,"n":17381}],"full":1,"dr":1},{"num":6799,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن مَسْعُودٍ أن النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: سِبَابُ الْمُسْلِمِ فُسُوقٌ وَقِتَالُهُ كُفْرٌ."],"takhrij":"متفق عليه: رواه البخاري في الإيمان (48) ومسلم في الإيمان (64) كلاهما من حديث شعبة، عن زبيد، عن أبي وائل، عن عبد الله بن مسعود فذكره.","grade":"متفق عليه","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (48) and Muslim (64).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd reported that the Prophet ﷺ said, “Insulting a Muslim is sinful rebellion, and fighting him is disbelief.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":48,"lafz":true},{"key":"muslim","label":"مسلم","number":64}],"full":1,"rep":[164]},{"num":6800,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بن أَبِي وَقَّاصٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: قِتَالُ الْمُسْلِمِ كُفْرٌ، وَسِبَابُهُ فِسْقٌ."],"takhrij":"صحيح: رواه أحمد (1537) والبخاري في الأدب المفرد (429) وابن نصر في تعظيم قدرالصلاة (1099) كلهم من حديث زكريا بن أبي زائدة، عن أبي إسحاق، عن محمد بن سعد بن مالك، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Aḥmad (1537), al-Bukhārī in al-Adab al-Mufrad (429), and Ibn Naṣr in Taʿẓīm Qadr al-Ṣalāh (1099).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ reported that the Prophet ﷺ said, “Fighting a Muslim is disbelief, and insulting him is sinful rebellion.”"]}},"tuhfa":{},"refs":[{"key":"adab","label":"البخاري في الأدب المفرد","number":429},{"key":"ابن_نصر/تعظیم_قدر_الصلاہ","label":"ابن نصر في تعظيم قدر الصلاة","number":1099},{"key":"ahmad","label":"مسند الإمام أحمد","number":1537,"n":1537,"lafz":true}],"full":1,"dr":1},{"num":6801,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ يَجِيءُ الرَّجُلُ آخِذًا بِيَدِ الرَّجُلِ فَيَقُولُ يَا رَبِّ هَذَا قَتَلَنِي. فَيَقُولُ اللَّهُ لَهُ لِمَ قَتَلْتَهُ فَيَقُولُ قَتَلْتُهُ لِتَكُونَ الْعِزَّةُ لَكَ. فَيَقُولُ فَإِنَّهَا لِي. وَيَجِيءُ الرَّجُلُ آخِذًا بِيَدِ الرَّجُلِ فَيَقُولُ إِنَّ هَذَا قَتَلَنِي. فَيَقُولُ اللَّهُ لَهُ لِمَ قَتَلْتَهُ فَيَقُولُ لِتَكُونَ الْعِزَّةُ لِفُلاَنٍ فَيَقُولُ إِنَّهَا لَيْسَتْ لِفُلاَنٍ فَيَبُوءُ بِإِثْمِهِ."],"takhrij":"صحيح: رواه النسائي (3997) والبيهقي (8/191) كلاهما من حديث معتمر، عن أبيه، عن الأعمش، عن شقيق بن سلمة، عن عمرو بن شرحبيل، عن عبد الله بن مسعود فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasā’ī (3997) and al-Bayhaqī (8/191).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Ibn Masʿūd reported that the Prophet ﷺ said, “A man will come holding another man by the hand and say: ‘My Lord, this one killed me.’ Allah will say to him: ‘Why did you kill him?’ He will say: ‘I killed him so that honor would belong to You.’ Allah will say: ‘Indeed, it belongs to Me.’ Another man will come holding another by the hand and say: ‘This one killed me.’ Allah will say to him: ‘Why did you kill him?’ He will say: ‘So that honor would belong to so-and-so.’ Allah will say: ‘It does not belong to so-and-so,’ and he will return bearing his sin.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3997,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":191}],"full":1},{"num":6802,"demo":false,"sanad":"","matn":["عَنْ أَبِي عِمْرَانَ قَالَ: قُلْتُ لِجُنْدُبٍ: إِنِّي قَدْ بَايَعْتُ هَؤُلَاءِ - يَعْنِي ابْنَ الزُّبَيْرِ - وَإِنَّهُمْ يُرِيدُونَ أَنْ أَخْرُجَ مَعَهُمْ إِلَى الشَّامِ، فَقَالَ: أَمْسِكْ، فَقُلْتُ: إِنَّهُمْ يَأْبَوْنَ، فَقَالَ: افْتَدِ بِمَالِكَ، قَالَ: قُلْتُ: إِنَّهُمْ يَأْبَوْنَ إِلَّا أَنْ أَضْرِبَ مَعَهُمْ بِالسَّيْفِ، فَقَالَ جُنْدُبٌ، حَدَّثَنِي فُلَانٌ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَجِيءُ الْمَقْتُولُ بِقَاتِلِهِ يَوْمَ الْقِيَامَةِ فَيَقُولُ: يَا رَبِّ، سَلْ هَذَا فِيمَ قَتَلَنِي - قَالَ: شُعْبَةُ فَأَحْسِبُهُ قَالَ -: فَيَقُولُ: عَلَامَ قَتَلْتَهُ؟ فَيَقُولُ: قَتَلْتُهُ عَلَى مُلْكِ فُلَانٍ، قَالَ: فَقَالَ جُنْدُبٌ: فَاتَّقِهَا."],"takhrij":"صحيح: رواه النسائي (3998) وأحمد (16600) كلاهما من حديث حجاج بن محمد المصيصي قال: حدثنا شعبة، عن أبي عمران فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasā’ī (3998) and Aḥmad (16600), with the wording here from Aḥmad.","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abū ʿImrān said: I said to Jundub, “I have pledged allegiance to these people”—meaning Ibn al-Zubayr—“and they want me to go out with them to Syria.” He said: “Hold back.” I said: “They refuse.” He said: “Ransom yourself with your wealth.” I said: “They refuse unless I fight with them by the sword.” Jundub then said: So-and-so narrated to me that the Messenger of Allah ﷺ said, “The one who was killed will come on the Day of Resurrection holding his killer and saying: ‘My Lord, ask this one why he killed me.’” Shuʿbah said: I think he also said: “Allah will say: ‘For what did you kill him?’ He will reply: ‘I killed him for the rule of so-and-so.’” Jundub then said: “So beware of that.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3998,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":16600,"n":16600}],"full":1,"dr":1},{"num":6803,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ عَنْ رَجُلٍ قَتَلَ مُؤْمِنًا، ثُمَّ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا، ثُمَّ اهْتَدَى، قَالَ: وَيْحَكَ، وَأَنَّى لَهُ الْهُدَى، سَمِعْتُ نَبِيَّكُمْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: يَجِيءُ الْمَقْتُولُ مُتَعَلِّقًا بِالْقَاتِلِ، يَقُولُ: يَا رَبِّ، سَلْ هَذَا فِيمَ قَتَلَنِي؟ وَاللهِ لَقَدِ أَنْزَلَهَا اللهُ عَزَّ وَجَلَّ عَلَى نَبِيِّكُمْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَمَا نَسَخَهَا بَعْدَ إِذِ انْزَلَهَا، قَالَ: وَيْحَكَ، وَأَنَّى لَهُ الْهُدَى؟!"],"takhrij":"حسن: رواه ابن ماجة (2621) والنسائي (3999) وأحمد (1941) كلهم من طريق سفيان بن عيينة، عن عمار بن معاوية الدهني، عن سالم بن أبي الجعد قال: سئل ابن عباس قال: فذكره.","grade":"حسن","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Mājah (2621), al-Nasā’ī (3999), Aḥmad (1941), and al-Tirmidhī (3029), who graded it sound.","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿAbbās was asked about a man who killed a believer, then repented, believed, did righteous deeds, and was rightly guided. He said: “Woe to you—how can guidance be his after that? I heard your Prophet ﷺ say: ‘The slain person will come clinging to his killer, saying: My Lord, ask this man why he killed me.’ By Allah, Allah revealed that verse to your Prophet ﷺ, and it was never abrogated after being revealed.” Then he said again: “Woe to you—how can guidance be his?”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2621,"lafz":true},{"key":"nasai","label":"النسائي","number":3999},{"key":"tirmidhi","label":"الترمذي","number":3029},{"key":"ahmad","label":"مسند الإمام أحمد","number":1941,"n":1941}],"full":1,"dr":1},{"num":6804,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : قَتْلُ الْمُؤْمِنِ أَعْظَمُ عِنْدَ اللَّهِ مِنْ زَوَالِ الدُّنْيَا."],"takhrij":"حسن: رواه النسائي (3990) عن الحسن بن إسحاق المروزي ثقة، حدثني خالد بن خداش، قال: حدثنا حاتم بن إسماعيل، عن بشير بن المهاجر، عن عبد الله بن بريدة، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasā’ī (3990).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Buraydah said: The Messenger of Allah ﷺ said, “The killing of a believer is greater in the sight of Allah than the passing away of the whole world.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3990,"lafz":true},{"key":"sh12704","label":"الأهوال لابن أبي الدنيا","number":192,"n":188}],"full":1,"dr":1},{"num":6805,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ تُقْتَلُ نَفْسٌ ظُلْمًا إِلاَّ كَانَ عَلَى ابْنِ آدَمَ الأَوَّلِ كِفْلٌ مِنْ دَمِهَا، لأَنَّهُ أَوَّلُ مَنْ سَنَّ الْقَتْلَ."],"takhrij":"متفق عليه: رواه البخاري في الديات (6867) ومسلم في القسامة (27:1677) كلاهما من طريق الأعمش، عن عبد الله بن مرة، عن مسروق، عن عبد الله قال فذكره.","grade":"متفق عليه","chapter_ar":"باب أول من سن القتل وبيان إثمه","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (6867) and Muslim (1677, no. 27).","chapter_en":"The first one to initiate killing and the explanation of his sin","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd said: The Messenger of Allah ﷺ said, “No soul is killed unjustly except that a share of its blood is upon the first son of Adam, because he was the first to establish killing.”"]},"intro":{"ar":["قال اللّٰه تعالى: ﴿وَاتْلُ عَلَيْهِمْ نَبَأَ ابْنَيْ آدَمَ بِالْحَقِّ إِذْ قَرَّبَا قُرْبَانًا فَتُقُبِّلَ مِنْ أَحَدِهِمَا وَلَمْ يُتَقَبَّلْ مِنَ الْآخَرِ قَالَ لَأَقْتُلَنَّكَ قَالَ إِنَّمَا يَتَقَبَّلُ اللَّهُ مِنَ الْمُتَّقِينَ ۝ لَئِنْ بَسَطتَ إِلَيَّ يَدَكَ لِتَقْتُلَنِي مَا أَنَا بِبَاسِطٍ يَدِيَ إِلَيْكَ لِأَقْتُلَكَ إِنِّي أَخَافُ اللَّهَ رَبَّ الْعَالَمِينَ ۝ إِنِّي أُرِيدُ أَنْ تَبُوءَ بِإِثْمِي وَإِثْمِكَ فَتَكُونَ مِنْ أَصْحَابِ النَّارِ وَذَٰلِكَ جَزَاءُ الظَّالِمِينَ ۝ فَطَوَّعَتْ لَهُ نَفْسُهُ قَتْلَ أَخِيهِ فَقَتَلَهُ فَأَصْبَحَ مِنَ الْخَاسِرِينَ ۝ فَبَعَثَ اللَّهُ غُرَابًا يَبْحَثُ فِي الْأَرْضِ لِيُرِيَهُ كَيْفَ يُوَارِي سَوْءَةَ أَخِيهِ قَالَ يَا وَيْلَتَا أَعَجَزْتُ أَنْ أَكُونَ مِثْلَ هَٰذَا الْغُرَابِ فَأُوَارِيَ سَوْءَةَ أَخِي فَأَصْبَحَ مِنَ النَّادِمِينَ﴾ [المائدة: ٢٧-٣١]"],"en":["Allah Most High said: “And recite to them the story of the two sons of Adam in truth: when they both offered a sacrifice, and it was accepted from one of them and not accepted from the other. He said: I will surely kill you. He said: Allah only accepts from the Allah-fearing. If you stretch out your hand against me to kill me, I will not stretch out my hand against you to kill you. Indeed, I fear Allah, Lord of the worlds. I want you to return bearing my sin and your sin, so that you will be among the people of the Fire, and that is the recompense of the wrongdoers. Then his soul prompted him to kill his brother, so he killed him and became one of the losers. Then Allah sent a crow scratching in the earth to show him how to conceal the body of his brother. He said: Woe to me! Am I unable to be like this crow and hide the body of my brother? So he became one of the regretful.” [al-Māʾidah: 27–31]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6867,"lafz":true},{"key":"muslim","label":"مسلم","number":27}],"full":1},{"num":6806,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ، قَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوَّلُ مَا يُقْضَى بَيْنَ النَّاسِ فِي الدِّمَاءِ."],"takhrij":"متفق عليه: رواه البخاري في الديات (6864) ومسلم في القسامة (1678) كلاهما من طريق الأعمش، عن أبي وائل، عن ابن مسعود، فذكره.","grade":"متفق عليه","chapter_ar":"باب أن أول ما يُقضى بين الناس يوم القيامة في الدماء","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (6864) and Muslim (1678).","chapter_en":"The first matter judged among people on the Day of Resurrection will be bloodshed","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd said: The Prophet ﷺ said, “The first matter to be judged among people will be bloodshed.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6864,"lafz":true},{"key":"muslim","label":"مسلم","number":1678}],"full":1,"dr":1},{"num":6807,"demo":false,"sanad":"","matn":["عن عبد الله بن مسعود: قال رجل: يا رسول الله أي الذنب أكبر عند الله؟ قال: أن تدعو لله نداً وهو خلقك قال: ثم أي؟ قال: ثم أن تقتل ولدك خشية أن يطعم معك قال: ثم أي؟ قال: ثم أن تزاني حليلة جارك فأنزل الله تصديقها ﴿وَالَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا﴾ [الفرقان: ٦٨ ]"],"takhrij":"متفق عليه: رواه البخاري في الديات (6861) ومسلم في الإيمان (142:86) كلاهما من طريق جرير، عن الأعمش، عن أبي وائل، عن عمرو بن شرحبيل، قال عبد الله، فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم قتل الأولاد خوفا من الفقر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (6861) and Muslim (86, no. 142).","chapter_en":"The prohibition of killing children out of fear of poverty","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd reported: A man asked, “O Messenger of Allah ﷺ, which sin is greatest in the sight of Allah?” He said, “That you set up a rival to Allah while He created you.” He said, “Then what?” He said, “Then that you kill your child out of fear that he will eat with you.” He said, “Then what?” He said, “Then that you commit adultery with your neighbor’s wife.” Then Allah revealed, confirming this: “Those who do not call upon another god with Allah, nor kill the soul which Allah has forbidden except with right, nor commit adultery…” [al-Furqān: 68]"]},"intro":{"ar":["قال الله تعالى: ﴿وَلَا تَقْتُلُوا أَوْلَادَكُمْ مِنْ إِمْلَاقٍ نَحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ﴾ [الأنعام: ١٥١]","وقال تعالى: ﴿قَدْ خَسِرَ الَّذِينَ قَتَلُوا أَوْلَادَهُمْ سَفَهًا بِغَيْرِ عِلْمٍ﴾ [الأنعام: ١٤٠]"],"en":["Allah Most High said: “Do not kill your children because of poverty; We provide for you and for them.” [Sūrat al-Anʿām: 151]","And He said: “Lost indeed are those who killed their children foolishly without knowledge.” [Sūrat al-Anʿām: 140]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6861,"lafz":true},{"key":"muslim","label":"مسلم","number":142,"n":258}],"full":1},{"num":6808,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ، قَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ اللَّهَ حَرَّمَ عَلَيْكُمْ عُقُوقَ الأُمَّهَاتِ، وَوَأْدَ الْبَنَاتِ، وَمَنَعَ وَهَاتِ، وَكَرِهَ لَكُمْ قِيلَ وَقَالَ، وَكَثْرَةَ السُّؤَالِ، وَإِضَاعَةَ الْمَالِ."],"takhrij":"متفق عليه: رواه البخاري في الخصومات (2408)، ومسلم في الأقضية (12:593) كلاهما من طريق جرير، عن منصور، عن الشعبي، عن ورّاد مولى المغيرة بن شعبة، عن المغيرة بن شعبة، فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم وأد البنات وأنه من أفعال الجاهلية","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (2408) and Muslim (593, no. 12).","chapter_en":"The prohibition of burying daughters alive, and that it was among the practices of the pre-Islamic age","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["al-Mughīrah ibn Shuʿbah said: The Prophet ﷺ said, “Allah has forbidden for you disobedience to mothers, burying daughters alive, and withholding what should be given while demanding what is not yours. And He has disliked for you idle talk, excessive questioning, and wasting wealth.”"]},"buhuth":{"en":["The phrase “burying daughters alive” means burying them while they are still alive so that they die beneath the earth."]},"intro":{"ar":["قال اللّٰه تعالى: ﴿وَإِذَا بُشِّرَ أَحَدُهُمْ بِالْأُنْثَىٰ ظَلَّ وَجْهُهُ مُسْوَدًّا وَهُوَ كَظِيمٌ ۝ يَتَوَارَىٰ مِنَ الْقَوْمِ مِنْ سُوءِ مَا بُشِّرَ بِهِ أَيُمْسِكُهُ عَلَىٰ هُونٍ أَمْ يَدُسُّهُ فِي التُّرَابِ أَلَا سَاءَ مَا يَحْكُمُونَ﴾ [النحل: ٥٨-٥٩]","وقال تعالى: ﴿وَإِذَا الْمَوْءُودَةُ سُئِلَتْ ۝ بِأَيِّ ذَنْبٍ قُتِلَتْ﴾ [التكوير: ٨-٩]"],"en":["Allah Most High said: “When one of them is given news of a female child, his face darkens and he is filled with grief. He hides himself from the people because of the evil of what he was given news of: should he keep her in humiliation or bury her in the dust? Evil indeed is what they judge.” [al-Naḥl: 58–59]","And He said: “And when the girl buried alive is asked: for what sin was she killed?” [al-Takwīr: 8–9]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2408,"lafz":true},{"key":"muslim","label":"مسلم","number":12}],"full":1,"dr":1,"rep":[14040]},{"num":6809,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ اجْتَنِبُوا السَّبْعَ الْمُوبِقَاتِ. قَالُوا يَا رَسُولَ اللَّهِ وَمَا هُنَّ قَالَ الشِّرْكُ بِاللَّهِ، وَالسِّحْرُ، وَقَتْلُ النَّفْسِ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ، وَأَكْلُ الرِّبَا، وَأَكْلُ مَالِ الْيَتِيمِ، وَالتَّوَلِّي يَوْمَ الزَّحْفِ، وَقَذْفُ الْمُحْصَنَاتِ الْمُؤْمِنَاتِ الْغَافِلاَتِ."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6857)، ومسلم في الإيمان (89) كلاهما من طريق سليمان بن بلال، عن ثور بن زيد، عن أبي الغيث، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب قتل النفس بغير حق من أكبر الكبائر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (6857) and Muslim (89).","chapter_en":"Killing a soul without right is among the gravest major sins","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ said, “Avoid the seven destructive sins.” They said, “O Messenger of Allah ﷺ, what are they?” He said, “Associating partners with Allah, sorcery, killing the soul which Allah has forbidden except with right, consuming usury, consuming the wealth of an orphan, fleeing on the day of battle, and slandering chaste, believing, unsuspecting women.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6857,"lafz":true},{"key":"muslim","label":"مسلم","number":89}],"full":1,"rep":[230,5690,7001,7897,11517,12142,12362,12859]},{"num":6810,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ أَكْبَرُ الْكَبَائِرِ الإِشْرَاكُ بِاللَّهِ وَقَتْلُ النَّفْسِ، وَعُقُوقُ الْوَالِدَيْنِ، وَقَوْلُ الزُّورِ. أَوْ قَالَ وَشَهَادَةُ الزُّورِ."],"takhrij":"متفق عليه: رواه البخاري في الديات (6871) ومسلم في الإيمان (88) كلاهما من طريق شعبة، أخبرنا عبيد الله بن أبي بكر، عن أنس، فذكره.","grade":"متفق عليه","chapter_ar":"باب قتل النفس بغير حق من أكبر الكبائر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (6871) and Muslim (88).","chapter_en":"Killing a soul without right is among the gravest major sins","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Anas ibn Mālik reported that the Prophet ﷺ said, “The greatest of the major sins are associating partners with Allah, killing a soul, disobeying one’s parents, and false speech,” or he said, “false testimony.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6871,"lafz":true},{"key":"muslim","label":"مسلم","number":88}],"full":1},{"num":6811,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ أَبْغَضُ النَّاسِ إِلَى اللَّهِ ثَلاَثَةٌ مُلْحِدٌ فِي الْحَرَمِ، وَمُبْتَغٍ فِي الإِسْلاَمِ سُنَّةَ الْجَاهِلِيَّةِ، وَمُطَّلِبُ دَمِ امْرِئٍ بِغَيْرِ حَقٍّ لِيُهَرِيقَ دَمَهُ."],"takhrij":"صحيح: رواه البخاري في الديات (6882) عن أبي اليمان، أخبرنا شعيب، عن عبدالله بن أبي حسين، حدثنا نافع بن جبير، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب قتل النفس بغير حق من أكبر الكبائر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhārī (6882).","chapter_en":"Killing a soul without right is among the gravest major sins","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbās reported that the Prophet ﷺ said, “The most hateful of people to Allah are three: one who commits deviation in the Sacred Precinct, one who seeks to revive a practice of the pre-Islamic age in Islam, and one who seeks the blood of a person without right in order to shed it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6882,"lafz":true}],"full":1,"rep":[10607,12783,15701]},{"num":6812,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن مَسْعُودٍ، عَنْ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: سِبَابُ الْمُسْلِمِ فُسُوقٌ، وَقِتَالُهُ كُفْرٌ."],"takhrij":"متفق عليه: رواه البخاري في الإيمان (48) ومسلم في الإيمان (64) كلاهما من حديث شعبة، عن زبيد، عن أبي وائل، عن عبد الله بن مسعود، فذكره.","grade":"متفق عليه","chapter_ar":"باب قتل النفس بغير حق من أكبر الكبائر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (48) and Muslim (64).","chapter_en":"Killing a soul without right is among the gravest major sins","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd reported that the Prophet ﷺ said, “Insulting a Muslim is sinful rebellion, and fighting him is disbelief.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":48,"lafz":true},{"key":"muslim","label":"مسلم","number":64}],"full":1},{"num":6813,"demo":false,"sanad":"","matn":["عَنْ جَرِيرٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ فِي حَجَّةِ الْوَدَاعِ اسْتَنْصِتِ النَّاسَ فَقَالَ لاَ تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ."],"takhrij":"متفق عليه: رواه البخاري في العلم (121) ومسلم في الإيمان (65) كلاهما من حديث شعبة، قال: أخبرني علي بن مدركة، عن أبي زرعة، عن جده جرير، فذكره.","grade":"متفق عليه","chapter_ar":"باب قتل النفس بغير حق من أكبر الكبائر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (121) and Muslim (65).","chapter_en":"Killing a soul without right is among the gravest major sins","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Jarīr reported that the Prophet ﷺ said to him during the Farewell Pilgrimage, “Tell the people to listen,” then said: “Do not revert after me to disbelief, striking the necks of one another.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":121,"lafz":true},{"key":"muslim","label":"مسلم","number":65}],"full":1,"rep":[165]},{"num":6814,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ وَيْلَكُمْ ـ أَوْ وَيْحَكُمْ قَالَ شُعْبَةُ شَكَّ هُوَ ـ لاَ تَرْجِعُوا بَعْدِي كُفَّارًا، يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6166) ومسلم في الإيمان (66) كلاهما من حديث شعبة، عن واقد بن محمد، أنه سمع أباه يحدث عن عبد الله بن عمر، فذكره.","grade":"متفق عليه","chapter_ar":"باب قتل النفس بغير حق من أكبر الكبائر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (6166) and Muslim (66).","chapter_en":"Killing a soul without right is among the gravest major sins","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿUmar reported that the Prophet ﷺ said, “Woe to you,” or “May Allah have mercy on you”—Shuʿbah said he was uncertain which one—“do not revert after me to disbelief, striking the necks of one another.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6166,"lafz":true},{"key":"muslim","label":"مسلم","number":66}],"full":1},{"num":6815,"demo":false,"sanad":"","matn":["عن أبي بكرة، قال: خطبنا النبي صلى الله عليه وسلم يوم النحر، فذكر الحديث وفي آخره: قال: اللهم اشهد، فليبلغ الشاهد الغائب، فرب مبلغ أوعى من سامع، فلا ترجعوا بعدي كفاراً، يضرب بعضكم رقاب بعض."],"takhrij":"متفق عليه: رواه البخاري في الحج (1741) ومسلم في القسامة (31:1679) كلاهما من طريق أبي عامر عبدالملك بن عمر، حدثنا قرة بن خالد، حدثنا محمد بن سيرين، أخبرني عبدالرحمن بن أبي بكرة، عن أبي بكرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب قتل النفس بغير حق من أكبر الكبائر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (1741) and Muslim (1679, no. 31).","chapter_en":"Killing a soul without right is among the gravest major sins","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Abū Bakrah said: The Prophet ﷺ gave us a sermon on the Day of Sacrifice, and at the end of it he said, “O Allah, bear witness. Let the one present convey to the one absent, for perhaps the one informed may understand better than the one who heard directly. Do not revert after me to disbelief, striking the necks of one another.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1741,"lafz":true},{"key":"muslim","label":"مسلم","number":31}],"full":1},{"num":6816,"demo":false,"sanad":"","matn":["عن ابن عباس، أن رسول الله صلى الله عليه وسلم خطب الناس يوم النحر، فذكر الحديث وفي آخره: قال ابن عباس رضي الله عنهما: فو الذي نفسي بيده، إنها لوصيته إلى أمته: فليبلغ الشاهد الغائب، لا ترجعوا بعدي كفارا، يضرب بعضكم رقاب بعض."],"takhrij":"صحيح: رواه البخاري (1739) عن علي بن عبد الله (هو ابن المديني) حدثني يحيى بن سعيد (هو القطان) حدثنا فضيل بن غزوان، حدثنا عكرمة، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب قتل النفس بغير حق من أكبر الكبائر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhārī (1739).","chapter_en":"Killing a soul without right is among the gravest major sins","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbās reported that the Messenger of Allah ﷺ addressed the people on the Day of Sacrifice, and at the end of the report Ibn ʿAbbās said: By the One in whose hand is my soul, this was indeed his final instruction to his community: “Let the one present convey to the one absent. Do not revert after me to disbelief, striking the necks of one another.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1739,"lafz":true}],"full":1},{"num":6817,"demo":false,"sanad":"","matn":["أَنَّ أَبَا هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ لَمَّا تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَكَانَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ وَكَفَرَ مَنْ كَفَرَ مِنَ الْعَرَبِ فَقَالَ عُمَرُ ـ رَضِيَ اللَّهُ عَنْهُ كَيْفَ تُقَاتِلُ النَّاسَ، وَقَدْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا لاَ إِلَهَ إِلاَّ اللَّهُ. فَمَنْ قَالَهَا فَقَدْ عَصَمَ مِنِّي مَالَهُ وَنَفْسَهُ إِلاَّ بِحَقِّهِ، وَحِسَابُهُ عَلَى اللَّهِ."],"takhrij":"متفق عليه: رواه البخاري في الزكاة (1399) ومسلم في الإيمان (20) كلاهما من طريق الزهري، حدثنا عبيد الله بن عبد الله بن عتبة بن مسعود، أن أبا هريرة رضي الله عنه قال فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب تغليظ تحريم قتل الكافر إذا أسلم ونطق بالشهادتين","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (1399) and Muslim (20), with the wording here from al-Bukhārī.","chapter_en":"The severe prohibition of killing a disbeliever once he accepts Islam and pronounces the two testimonies","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah said: When the Messenger of Allah ﷺ passed away and Abū Bakr became leader, some of the Arabs fell into disbelief. ʿUmar said, “How can you fight the people when the Messenger of Allah ﷺ said: ‘I have been commanded to fight the people until they say: There is no god but Allah. Whoever says it has protected from me his wealth and his life except by its due right, and his reckoning is with Allah’?”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1399,"lafz":true},{"key":"muslim","label":"مسلم","number":20}],"full":1},{"num":6818,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا: لاَ إِلَهَ إِلاَّ اللَّهُ، فَمَنْ قَالَ: لاَ إِلَهَ إِلاَّ اللَّهُ فَقَدْ عَصَمَ مِنِّي نَفْسَهُ وَمَالَهُ إِلاَّ بِحَقِّهِ وَحِسَابُهُ عَلَى اللَّهِ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2946) ومسلم في الإيمان (21) كلاهما من طريق الزهري، حدثني سعيد بن المسيب، أن أبا هريرة أخبره، فذكره.","grade":"متفق عليه","chapter_ar":"باب تغليظ تحريم قتل الكافر إذا أسلم ونطق بالشهادتين","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2946) and Muslim (21).","chapter_en":"The severe prohibition of killing a disbeliever once he accepts Islam and pronounces the two testimonies","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “I have been commanded to fight the people until they say: There is no god but Allah. Whoever says: There is no god but Allah has protected his life and wealth from me, except by its due right, and his reckoning is with Allah.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2946,"lafz":true},{"key":"muslim","label":"مسلم","number":21}],"full":1,"rep":[7860]},{"num":6819,"demo":false,"sanad":"","matn":["عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَشْهَدُوا أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَيُقِيمُوا الصَّلاَةَ، وَيُؤْتُوا الزَّكَاةَ، فَإِذَا فَعَلُوا ذَلِكَ عَصَمُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلاَّ بِحَقِّ الإِسْلاَمِ، وَحِسَابُهُمْ عَلَى اللَّهِ."],"takhrij":"متفق عليه: رواه البخاري في الإيمان (25) ومسلم في الإيمان (22) كلاهما من طريق شعبة، عن واقد بن محمد بن زيد بن عبد الله بن عمر قال: سمعت أبي يحدث عن ابن عمر، أن رسول الله صلى الله عليه وسلم قال فذكره.","grade":"متفق عليه","chapter_ar":"باب تغليظ تحريم قتل الكافر إذا أسلم ونطق بالشهادتين","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (25) and Muslim (22).","chapter_en":"The severe prohibition of killing a disbeliever once he accepts Islam and pronounces the two testimonies","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Abdullah ibn Umar reported that the Messenger of Allah ﷺ said: “I have been commanded to fight the people until they testify that there is no god but Allah and that Muhammad is the Messenger of Allah ﷺ, establish the prayer, and give the alms. If they do that, they have protected their blood and wealth from me except by the right of Islam, and their reckoning is with Allah.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":25,"lafz":true},{"key":"muslim","label":"مسلم","number":22}],"full":1},{"num":6820,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَالِكٍ، عَنْ أَبِيهِ، قَالَ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ مَنْ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ وَكَفَرَ بِمَا يُعْبَدُ مِنْ دُونِ اللَّهِ حَرُمَ مَالُهُ وَدَمُهُ وَحِسَابُهُ عَلَى اللَّهِ."],"takhrij":"صحيح: رواه مسلم في الإيمان (23) عن سويد بن سعيد وابن أبي عمر، قالا: حدثنا مروان الفزاري، عن أبي مالك، فذكره.","grade":"صحيح","chapter_ar":"باب تغليظ تحريم قتل الكافر إذا أسلم ونطق بالشهادتين","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (23).","chapter_en":"The severe prohibition of killing a disbeliever once he accepts Islam and pronounces the two testimonies","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Abu Malik al-Ashjaʿi narrated from his father, who said: I heard the Messenger of Allah ﷺ say: “Whoever says: There is no god but Allah, and rejects whatever is worshipped besides Allah, his wealth and blood become inviolable, and his reckoning is with Allah.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":23,"lafz":true}],"full":1,"dr":1,"rep":[7866]},{"num":6821,"demo":false,"sanad":"","matn":["عن الْمِقْدَادِ بن عمرو الكندي – وَكَانَ حليفاً لِبَنِي زهرة مِمَّنْ شَهِدَ بَدْرًا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخْبَرَهُ أَنَّهُ قَالَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَرَأَيْتَ إِنْ لَقِيتُ رَجُلاً مِنَ الْكُفَّارِ فَاقْتَتَلْنَا، فَضَرَبَ إِحْدَى يَدَىَّ بِالسَّيْفِ فَقَطَعَهَا، ثُمَّ لاَذَ مِنِّي بِشَجَرَةٍ فَقَالَ أَسْلَمْتُ لِلَّهِ. آأَقْتُلُهُ يَا رَسُولَ اللَّهِ بَعْدَ أَنْ قَالَهَا فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ تَقْتُلْهُ. فَقَالَ يَا رَسُولَ اللَّهِ، إِنَّهُ قَطَعَ إِحْدَى يَدَىَّ، ثُمَّ قَالَ ذَلِكَ بَعْدَ مَا قَطَعَهَا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ تَقْتُلْهُ، فَإِنْ قَتَلْتَهُ فَإِنَّهُ بِمَنْزِلَتِكَ قَبْلَ أَنْ تَقْتُلَهُ، وَإِنَّكَ بِمَنْزِلَتِهِ قَبْلَ أَنْ يَقُولَ كَلِمَتَهُ الَّتِي قَالَ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4019) وفي الديات (6865) ومسلم في الإيمان (95) من حديث ابن شهاب الزهري، عن عطاء بن يزيد، عن عبيد الله بن عدي بن الخياري، عن المقداد بن عمرو، فذكره.","grade":"متفق عليه","chapter_ar":"باب تغليظ تحريم قتل الكافر إذا أسلم ونطق بالشهادتين","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (4019, 6865) and Muslim (95).","chapter_en":"The severe prohibition of killing a disbeliever once he accepts Islam and pronounces the two testimonies","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Al-Miqdad ibn ʿAmr al-Kindi — who was an ally of Banu Zuhrah and one of those who witnessed Badr with the Messenger of Allah ﷺ — said to the Messenger of Allah ﷺ: “What do you think if I meet a man from the disbelievers and we fight, and he strikes one of my hands with the sword and cuts it off, then takes shelter from me behind a tree and says, ‘I have submitted myself to Allah’? May I kill him after he says that, O Messenger of Allah ﷺ?” The Messenger of Allah ﷺ said: “Do not kill him.” He said: “O Messenger of Allah ﷺ, he cut off one of my hands, then only said that after cutting it off!” The Messenger of Allah ﷺ said: “Do not kill him. If you kill him, then he will be in your position before you killed him, and you will be in his position before he said the words that he said.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4019,"lafz":true},{"key":"muslim","label":"مسلم","number":95}],"full":1,"dr":1},{"num":6822,"demo":false,"sanad":"","matn":["عن أُسَامَةَ بن زَيْدٍ رَضِيَ اللَّهُ عَنْهُمَا يَقُولُ بَعَثَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْحُرَقَةِ، فَصَبَّحْنَا الْقَوْمَ فَهَزَمْنَاهُمْ وَلَحِقْتُ أَنَا وَرَجُلٌ مِنَ الأَنْصَارِ رَجُلاً مِنْهُمْ، فَلَمَّا غَشِينَاهُ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ. فَكَفَّ الأَنْصَارِيُّ، فَطَعَنْتُهُ بِرُمْحِي حَتَّى قَتَلْتُهُ، فَلَمَّا قَدِمْنَا بَلَغَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ يَا أُسَامَةُ أَقَتَلْتَهُ بَعْدَ مَا قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ قُلْتُ كَانَ مُتَعَوِّذًا. فَمَا زَالَ يُكَرِّرُهَا حَتَّى تَمَنَّيْتُ أَنِّي لَمْ أَكُنْ أَسْلَمْتُ قَبْلَ ذَلِكَ الْيَوْمِ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4269) ومسلم في الإيمان (159:96) كلاهما من طريق هشيم، أخبرنا حصين، حدثنا أبو ظبيان، قال: سمعت أسامة بن زيد بن حارثة يحدث، قال فذكره.","grade":"متفق عليه","chapter_ar":"باب تغليظ تحريم قتل الكافر إذا أسلم ونطق بالشهادتين","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (4269) and Muslim (96, no. 159).","chapter_en":"The severe prohibition of killing a disbeliever once he accepts Islam and pronounces the two testimonies","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Usamah ibn Zayd said: The Messenger sent us to al-Huraqah. We attacked the people in the morning and defeated them. I and a man from the Ansar caught up with one of them, and when we closed in on him he said: There is no god but Allah. The Ansari held back from him, but I struck him with my spear and killed him. When we returned, news of that reached the Prophet ﷺ, and he said: “O Usamah, did you kill him after he said: There is no god but Allah?” I said: “He only said it seeking protection.” He kept repeating it until I wished I had not accepted Islam before that day."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4269,"lafz":true},{"key":"muslim","label":"مسلم","number":159,"n":278}],"full":1,"rep":[194,7870]},{"num":6823,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ قَتَلَ نَفْسًا مُعَاهَدًا لَمْ يَرَحْ رَائِحَةَ الْجَنَّةِ، وَإِنَّ رِيحَهَا يُوجَدُ مِنْ مَسِيرَةِ أَرْبَعِينَ عَامًا."],"takhrij":"صحيح: رواه البخاري في الديات (6914) عن قيس بن حفص، حدثنا عبد الواحد (هو ابن زياد) حدثنا الحسن (هو ابن عمرو الفقيمي)، حدثنا مجاهد، عن عبد الله بن عمرو، فذكره.","grade":"صحيح","chapter_ar":"باب إثم من قتل ذمياً أو معاهدا","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (6914).","chapter_en":"The sin of killing a protected non-Muslim or one under covenant","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abdullah ibn Amr ibn al-As reported that the Prophet ﷺ said: “Whoever kills a person under covenant will not smell the fragrance of Paradise, though its fragrance can be found from a distance of forty years.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6914,"lafz":true}],"full":1,"rep":[16283]},{"num":6824,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ أَلاَ مَنْ قَتَلَ نَفْسًا مُعَاهِدَةً لَهُ ذِمَّةُ اللَّهِ وَذِمَّةُ رَسُولِهِ فَقَدْ أَخْفَرَ بِذِمَّةِ اللَّهِ فَلاَ يَرَحْ رَائِحَةَ الْجَنَّةِ وَإِنَّ رِيحَهَا لَيُوجَدُ مِنْ مَسِيرَةِ سَبْعِينَ خَرِيفًا."],"takhrij":"حسن: رواه الترمذي (1403) وابن ماجة (2687) كلاهما عن محمد بن بشار، حدثنا معدي بن سليمان وهو البصري، أنبانا ابن عجلان، عن أبيه، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب إثم من قتل ذمياً أو معاهدا","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Tirmidhi (1403) and Ibn Majah (2687). Al-Tirmidhi said: “This is a sound authentic hadith.”","chapter_en":"The sin of killing a protected non-Muslim or one under covenant","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “Indeed, whoever kills a person under covenant who is under the protection of Allah and the protection of His Messenger has violated the protection of Allah. He will not smell the fragrance of Paradise, though its fragrance can be found from a distance of seventy years.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1403,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2687}],"full":1,"dr":1,"rep":[16285]},{"num":6825,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ قَتَلَ مُعَاهِدًا فِي غَيْرِ كُنْهِهِ حَرَّمَ اللَّهُ عَلَيْهِ الْجَنَّةَ."],"takhrij":"حسن: رواه أبو داود (2760) والنسائي (4747) وأحمد (20377) وصححه الحاكم (2/142) والبيهقي (9/231) كلهم من طرق عن عيينة بن عبد الرحمن، عن أبيه، عن أبي بكرة فذكره.","grade":"حسن","chapter_ar":"باب إثم من قتل ذمياً أو معاهدا","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (2760), al-Nasa’i (4747), and Ahmad (20377), and authenticated by al-Hakim (2/142).","chapter_en":"The sin of killing a protected non-Muslim or one under covenant","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abu Bakrah said: The Messenger of Allah ﷺ said: “Whoever kills a person under covenant without right, Allah has forbidden Paradise for him.”"]},"buhuth":{"en":["The phrase “without right” means: without any lawful justification."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2760,"lafz":true},{"key":"nasai","label":"النسائي","number":4747,"n":4747},{"key":"hakim","label":"صححه الحاكم","number":142,"n":135},{"key":"ahmad","label":"مسند الإمام أحمد","number":20377,"n":20377},{"key":"hakim","label":"المستدرك على الصحيحين","number":2631,"n":2617}],"full":1,"dr":1},{"num":6826,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: سَيَكُونُ قَوْمٌ لَهُمْ عَهْدٌ، فَمَنْ قَتَلَ رَجُلًا مِنْهُمْ لَمْ يَرَحْ رَائِحَةَ الْجَنَّةِ، وَإِنَّ رِيحَهَا لَيُوجَدُ مِنْ مَسِيرَةِ سَبْعِينَ عَامًا."],"takhrij":"صحيح: رواه أحمد (16590) عن أبي النضر، حدثنا الأشجعي، عن سفيان، عن الأعمش، عن هلال بن يساف، عن رجل فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب إثم من قتل ذمياً أو معاهدا","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (16590).","chapter_en":"The sin of killing a protected non-Muslim or one under covenant","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["A man narrated from the Prophet ﷺ that he said: “There will be a people who have a covenant. Whoever kills a man from among them will not smell the fragrance of Paradise, though its fragrance can be found from a distance of seventy years.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":16590,"n":16590,"lafz":true}],"full":1,"rep":[16284]},{"num":6827,"demo":false,"sanad":"","matn":["عَنْ رِفَاعَةَ بْنِ شَدَّادٍ الفتياني قَالَ: لَوْ لا كَلِمَةٌ سَمِعْتُهَا مِنْ عَمْرِو بْنِ الْحَمِقِ الْخُزَاعِيِّ لَمَشَيْتُ فِيهَا بَيْنَ رَأْسِ الْمُخْتَارِ وَجَسَدِهِ، سَمِعْتُهُ يَقُولُ: مَنْ أَمِنَ رَجُلاً عَلَى دَمِهِ، فَقَتَلَهُ فَإِنَّهُ يَحْمِلُ لِوَاءَ غدْر يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه ابن ماجة (2688) وأحمد (21946) وأبو داود الطيالسي (1285) وابن حبان (5982) وابن أبي عاصم في الديات (318) كلهم من حديث رفاعة بن شداد فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب الرجل يأمن الرجل على دمه ثم يقتله","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Majah (2688), Ahmad (21946), Abu Dawud al-Tayalisi (1285), and Ibn Hibban (5982).","chapter_en":"A man grants another safety regarding his life and then kills him","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Rifaʿah ibn Shaddad al-Fityani said: Were it not for a statement I heard from ʿAmr ibn al-Hamiq al-Khuzaʿi, I would have walked between the head of al-Mukhtar and his body. I heard him say: “Whoever grants a man safety regarding his life and then kills him will carry the banner of treachery on the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2688,"lafz":true},{"key":"tayalisi","label":"أبو داود الطيالسي","number":1285},{"key":"ibnhibban","label":"ابن حبان","number":5982},{"key":"ahmad","label":"مسند الإمام أحمد","number":21946,"n":21946}],"full":1},{"num":6828,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ شَهِدْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لِرَجُلٍ مِمَّنْ يَدَّعِي الإِسْلاَمَ هَذَا مِنْ أَهْلِ النَّارِ. فَلَمَّا حَضَرَ الْقِتَالُ قَاتَلَ الرَّجُلُ قِتَالاً شَدِيدًا، فَأَصَابَتْهُ جِرَاحَةٌ فَقِيلَ يَا رَسُولَ اللَّهِ، الَّذِي قُلْتَ إِنَّهُ مِنْ أَهْلِ النَّارِ فَإِنَّهُ قَدْ قَاتَلَ الْيَوْمَ قِتَالاً شَدِيدًا وَقَدْ مَاتَ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى النَّارِ. قَالَ فَكَادَ بَعْضُ النَّاسِ أَنْ يَرْتَابَ، فَبَيْنَمَا هُمْ عَلَى ذَلِكَ إِذْ قِيلَ إِنَّهُ لَمْ يَمُتْ، وَلَكِنَّ بِهِ جِرَاحًا شَدِيدًا. فَلَمَّا كَانَ مِنَ اللَّيْلِ لَمْ يَصْبِرْ عَلَى الْجِرَاحِ، فَقَتَلَ نَفْسَهُ، فَأُخْبِرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِذَلِكَ فَقَالَ اللَّهُ أَكْبَرُ، أَشْهَدُ أَنِّي عَبْدُ اللَّهِ وَرَسُولُهُ. ثُمَّ أَمَرَ بِلاَلاً فَنَادَى بِالنَّاسِ إِنَّهُ لاَ يَدْخُلُ الْجَنَّةَ إِلاَّ نَفْسٌ مُسْلِمَةٌ، وَإِنَّ اللَّهَ لَيُؤَيِّدُ هَذَا الدِّينَ بِالرَّجُلِ الْفَاجِرِ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد (3062) ومسلم في الإيمان (111) كلاهما من حديث عبد الرزاق، أخبرنا معمر، عن الزهري، عن ابن المسيب، عن أبي هريرة، فذكر الحديث، ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب غلظ تحريم قتل الإنسان نفسه","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (3062) and Muslim (111).","chapter_en":"The severe prohibition of a person killing himself","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah said: We were present with the Messenger of Allah ﷺ at Khaybar, and he said about a man who claimed to be Muslim: “This man is among the people of the Fire.” When fighting began, the man fought fiercely and was wounded. It was said: “O Messenger of Allah ﷺ, the one you said was among the people of the Fire fought fiercely today and has died.” The Prophet ﷺ said: “To the Fire.” Some people were almost doubtful because of that. While they were in that state, it was said: “He has not died, but he has severe wounds.” When night came, he could not bear the pain of his wounds and killed himself. The Prophet ﷺ was informed of that and said: “Allah is greatest. I bear witness that I am the servant of Allah and His Messenger.” Then he ordered Bilal to call out to the people: “None enters Paradise except a Muslim soul, and Allah may support this religion through a wicked man.”"]},"intro":{"ar":["قال اللّٰه تعالى: (وَلَا تَقْتُلُواْ أَنْفُسَكُمْ نَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا ) [سورة النساء: ٢٩]","وقال تعالى: (وَلَا تُلْقُواْ بِأَيْدِيكُم إلى التَّهْلُكَةِ) [البقرة: ١٩٥]"],"en":["Allah Most High said: “Do not kill yourselves. Indeed, Allah is ever Merciful to you.” [Surat al-Nisa’: 29]","And He said: “Do not throw yourselves into destruction with your own hands.” [al-Baqarah: 195]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3062,"lafz":true},{"key":"muslim","label":"مسلم","number":111}],"full":1,"rep":[7846]},{"num":6829,"demo":false,"sanad":"","matn":["عَنْ ثَابِتِ بْنِ الضَّحَّاكِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ حَلَفَ بِمِلَّةٍ غَيْرِ الإِسْلاَمِ كَاذِبًا فَهْوَ كَمَا قَالَ، وَمَنْ قَتَلَ نَفْسَهُ بِشَىْءٍ عُذِّبَ بِهِ فِي نَارِ جَهَنَّمَ، وَلَعْنُ الْمُؤْمِنِ كَقَتْلِهِ، وَمَنْ رَمَى مُؤْمِنًا بِكُفْرٍ فَهْوَ كَقَتْلِهِ."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6105) ومسلم في الإيمان (110) كلاهما من حديث أبي قلابة، عن ثابت بن الضحاك، فذكر الحديث، واللفظ للبخاري، ولفظ مسلم مختصراً، ولم يذكر قوله: ولعن المؤمن ... الخ","grade":"متفق عليه","chapter_ar":"باب غلظ تحريم قتل الإنسان نفسه","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (6105) and Muslim (110), with the wording here from al-Bukhari.","chapter_en":"The severe prohibition of a person killing himself","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Thabit ibn al-Dahhak reported that the Prophet ﷺ said: “Whoever falsely swears by a religion other than Islam is as he said. Whoever kills himself with something will be punished with it in the Fire of Hell. Cursing a believer is like killing him, and accusing a believer of disbelief is like killing him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6105,"lafz":true},{"key":"muslim","label":"مسلم","number":110}],"full":1,"rep":[198]},{"num":6830,"demo":false,"sanad":"","matn":["عَنِ الْحَسَنِ، حَدَّثَنَا جُنْدُبُ بْنُ عَبْدِ اللَّهِ، فِي هَذَا الْمَسْجِدِ، وَمَا نَسِينَا مُنْذُ حَدَّثَنَا، وَمَا نَخْشَى أَنْ يَكُونَ جُنْدُبٌ كَذَبَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ فِيمَنْ كَانَ قَبْلَكُمْ رَجُلٌ بِهِ جُرْحٌ، فَجَزِعَ فَأَخَذَ سِكِّينًا فَحَزَّ بِهَا يَدَهُ، فَمَا رَقَأَ الدَّمُ حَتَّى مَاتَ، قَالَ اللَّهُ تَعَالَى بَادَرَنِي عَبْدِي بِنَفْسِهِ، حَرَّمْتُ عَلَيْهِ الْجَنَّةَ.","وفي رواية: خرج برجل خُرّاج - أي القرحة."],"takhrij":"متفق عليه: رواه البخاري في أحاديث الأنبياء (3463) ومسلم في الإيمان (181:113) كلاهما من طريق جرير قال: سمعت الحسن يقول، فذكره.","grade":"متفق عليه","chapter_ar":"باب غلظ تحريم قتل الإنسان نفسه","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (3463) and Muslim (113, no. 181).","chapter_en":"The severe prohibition of a person killing himself","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Al-Hasan said: Jundub ibn Abdullah narrated to us in this mosque, and we have not forgotten since he narrated to us, nor do we fear that Jundub lied against the Prophet ﷺ. He said: The Messenger of Allah ﷺ said: “Among those before you there was a man who had a wound. He became distressed, so he took a knife and cut his hand with it. The blood did not stop until he died. Allah Most High said: My servant hastened his own end before Me, so I have forbidden Paradise for him.” In another narration: it was because of a swelling or ulcer."]},"buhuth":{"en":["The phrase “the blood did not stop” means: it did not cease flowing."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3463,"lafz":true},{"key":"muslim","label":"مسلم","number":113},{"key":"muslim","label":"مسلم في الايمان","number":181}],"full":1,"dr":1},{"num":6831,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ تَرَدَّى مِنْ جَبَلٍ فَقَتَلَ نَفْسَهُ، فَهْوَ فِي نَارِ جَهَنَّمَ، يَتَرَدَّى فِيهِ خَالِدًا مُخَلَّدًا فِيهَا أَبَدًا، وَمَنْ تَحَسَّى سَمًّا فَقَتَلَ نَفْسَهُ، فَسَمُّهُ فِي يَدِهِ، يَتَحَسَّاهُ فِي نَارِ جَهَنَّمَ خَالِدًا مُخَلَّدًا فِيهَا أَبَدًا، وَمَنْ قَتَلَ نَفْسَهُ بِحَدِيدَةٍ، فَحَدِيدَتُهُ فِي يَدِهِ، يَجَأُ بِهَا فِي بَطْنِهِ فِي نَارِ جَهَنَّمَ خَالِدًا مُخَلَّدًا فِيهَا أَبَدًا."],"takhrij":"متفق عليه: رواه البخاري في الطب (5778) ومسلم في الإيمان (109) كلاهما من طريق خالد بن الحارث، حدثنا شعبة، عن سليمان (هو الأعمش)، قال: سمعت ذكوان يحدث عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب غلظ تحريم قتل الإنسان نفسه","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (5778) and Muslim (109).","chapter_en":"The severe prohibition of a person killing himself","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “Whoever throws himself from a mountain and kills himself will be falling in the Fire of Hell forever, abiding therein eternally. Whoever drinks poison and kills himself, his poison will be in his hand and he will be drinking it in the Fire of Hell forever, abiding therein eternally. Whoever kills himself with an iron weapon, his weapon will be in his hand and he will be stabbing himself in the belly with it in the Fire of Hell forever, abiding therein eternally.”"]},"buhuth":{"en":["As for the meaning of the phrase “forever, abiding therein eternally”, al-Nawawi said in his commentary on Muslim that there are several interpretations:","The first is that it applies to one who did this while declaring it lawful despite knowing it is forbidden. Such a person is a disbeliever, and this is his punishment.","The second is that permanence here means a very long stay, not actual endlessness, just as people say: “May Allah make the ruler’s kingdom everlasting.”","The third is that this is the punishment he deserves, but Allah, out of grace, has informed us that one who dies as a Muslim will not remain forever in the Fire. End quote.","The proof that a person who kills himself does not become a disbeliever is the hadith that follows."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5778,"lafz":true},{"key":"muslim","label":"مسلم","number":109}],"full":1,"dr":1,"rep":[12141]},{"num":6832,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، أَنَّ الطُّفَيْلَ بْنَ عَمْرٍو الدَّوْسِيَّ، أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ يَا رَسُولَ اللَّهِ هَلْ لَكَ فِي حِصْنٍ حَصِينٍ وَمَنَعَةٍ - قَالَ حِصْنٌ كَانَ لِدَوْسٍ فِي الْجَاهِلِيَّةِ - فَأَبَى ذَلِكَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلَّذِي ذَخَرَ اللَّهُ لِلأَنْصَارِ فَلَمَّا هَاجَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْمَدِينَةِ هَاجَرَ إِلَيْهِ الطُّفَيْلُ بْنُ عَمْرٍو وَهَاجَرَ مَعَهُ رَجُلٌ مِنْ قَوْمِهِ فَاجْتَوَوُا الْمَدِينَةَ فَمَرِضَ فَجَزِعَ فَأَخَذَ مَشَاقِصَ لَهُ فَقَطَعَ بِهَا بَرَاجِمَهُ فَشَخَبَتْ يَدَاهُ حَتَّى مَاتَ فَرَآهُ الطُّفَيْلُ بْنُ عَمْرٍو فِي مَنَامِهِ فَرَآهُ وَهَيْئَتُهُ حَسَنَةٌ وَرَآهُ مُغَطِّيًا يَدَيْهِ فَقَالَ لَهُ مَا صَنَعَ بِكَ رَبُّكَ فَقَالَ غَفَرَ لِي بِهِجْرَتِي إِلَى نَبِيِّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ مَا لِي أَرَاكَ مُغَطِّيًا يَدَيْكَ قَالَ قِيلَ لِي لَنْ نُصْلِحَ مِنْكَ مَا أَفْسَدْتَ. فَقَصَّهَا الطُّفَيْلُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اللَّهُمَّ وَلِيَدَيْهِ فَاغْفِرْ."],"takhrij":"صحيح: رواه مسلم في الإيمان (116) من طرق عن سليمان بن حرب، حدثنا حماد بن زيد، عن حجاج الصواف، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب غلظ تحريم قتل الإنسان نفسه","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (116).","chapter_en":"The severe prohibition of a person killing himself","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Jabir reported that al-Tufayl ibn Amr al-Dawsi came to the Prophet ﷺ and said: “O Messenger of Allah ﷺ, would you like a fortified stronghold and protection?” It was a fort that belonged to Daws in the pre-Islamic period. The Prophet ﷺ declined that because of what Allah had reserved for the Ansar. When the Prophet ﷺ migrated to Madinah, al-Tufayl ibn Amr also migrated there, and a man from his people migrated with him. They found Madinah difficult to live in. The man became ill and grew distressed, so he took some arrowheads and cut his finger joints with them. His hands bled profusely until he died. Al-Tufayl ibn Amr later saw him in a dream. He saw him in a good state, but with his hands covered. He said to him: “What did your Lord do with you?” He replied: “He forgave me because of my migration to His Prophet ﷺ.” He said: “Then why do I see your hands covered?” He replied: “I was told: We will not repair from you what you yourself ruined.” Al-Tufayl told this to the Messenger of Allah ﷺ, and the Messenger of Allah ﷺ said: “O Allah, forgive even his hands.”"]},"buhuth":{"en":["The phrase “they found Madinah difficult to live in” means they disliked staying there because of discomfort and a kind of illness.","Mashaqis is the plural of mishqas, an arrow with a broad blade.","Barajim is the plural of barjumah, meaning the finger joints.","His hands bled profusely means that the blood flowed strongly.","This hadith shows that whoever kills himself and dies without repentance is not a disbeliever, and it cannot be decisively said that he is in the Fire forever. Rather, his matter is subject to the divine will."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":116,"lafz":true}],"full":1,"dr":1,"rep":[9765]},{"num":6833,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: لَا أُحَدِّثُكُمْ إِلَّا مَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَمِعَتْهُ أُذُنَايَ وَوَعَاهُ قَلْبِي: إِنَّ عَبْدًا قَتَلَ تِسْعَةً وَتِسْعِينَ نَفْسًا، ثُمَّ عَرَضَتْ لَهُ التَّوْبَةُ، فَسَأَلَ عَنْ أَعْلَمِ أَهْلِ الْأَرْضِ؟ فَدُلَّ عَلَى رَجُلٍ، فَأَتَاهُ فَقَالَ: إِنِّي قَتَلْتُ تِسْعَةً وَتِسْعِينَ نَفْسًا، فَهَلْ لِي مِنْ تَوْبَةٍ؟ قَالَ: بَعْدَ قَتْلِ تِسْعَةٍ وَتِسْعِينَ نَفْسًا؟ قَالَ: فَانْتَضَى سَيْفَهُ فَقَتَلَهُ بِهِ فَأَكْمَلَ بِهِ مِائَةً، ثُمَّ عَرَضَتْ لَهُ التَّوْبَةُ، فَسَأَلَ عَنْ أَعْلَمِ أَهْلِ الْأَرْضِ؟ فَدُلَّ عَلَى رَجُلٍ فَأَتَاهُ، فَقَالَ: إِنِّي قَتَلْتُ مِائَةَ نَفْسٍ، فَهَلْ لِي مِنْ تَوْبَةٍ؟ فَقَالَ: وَمَنْ يَحُولُ بَيْنَكَ وَبَيْنَ التَّوْبَةِ، اخْرُجْ مِنَ الْقَرْيَةِ الْخَبِيثَةِ الَّتِي أَنْتَ فِيهَا إِلَى الْقَرْيَةِ الصَّالِحَةِ قَرْيَةِ كَذَا وَكَذَا، فَاعْبُدْ رَبَّكَ فِيهَا، قَالَ: فَخَرَجَ إِلَى الْقَرْيَةِ الصَّالِحَةِ فَعَرَضَ لَهُ أَجَلُهُ فِي الطَّرِيقِ، قَالَ: فَاخْتَصَمَتْ فِيهِ مَلَائِكَةُ الرَّحْمَةِ وَمَلَائِكَةُ الْعَذَابِ، قَالَ: فَقَالَ إِبْلِيسُ: أَنَا أَوْلَى بِهِ إِنَّهُ لَمْ يَعْصِنِي سَاعَةً قَطُّ، قَالَ: فَقَالَتْ مَلَائِكَةُ الرَّحْمَةِ: إِنَّهُ خَرَجَ تَائِبًا.","قال همام: فحدثني حميد الطويل، عن بكر بن عبد الله المزني، عن أبي رافع قال: فبعث الله عز وجل له ملكاً فاختصموا إليه ثم رجع إلى حديث قتادة، قال: فقال: انظروا أي القريتين كان أقرب إليه، فألحقوه بأهلها.","قال قتادة: فحدثنا الحسن قال: لما عرف الموت احتفز بنفسه، فقرب الله عز وجل منه القرية الصالحة، وباعد منه القرية الخبيثة، فألحقوه بأهل القرية الصالحة."],"takhrij":"متفق عليه: رواه البخاري في أحاديث الأنبياء (3470) ومسلم في كتاب التوبة (2766) كلاهما من حديث شعبة، عن قتادة، عن أبي الصديق الناجي، عن أبي سعيد الخدري قال: فذكره. ورواه أحمد (11154) من حديث همام بن يحيى، عن قتادة بإسناده، واللفظ له لأنه أوفى.","grade":"متفق عليه","chapter_ar":"باب توبة القاتل","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (3470) and Muslim (2766). It was also narrated by Ahmad (11154), and this is his wording because it is longer.","chapter_en":"The repentance of a killer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: I will only tell you what I heard from the Messenger of Allah ﷺ, which my ears heard and my heart retained: “A servant killed ninety-nine people. Then repentance came to his mind, so he asked about the most knowledgeable person on earth. He was directed to a man, and he came to him and said: I have killed ninety-nine people; do I have any chance of repentance? He said: After killing ninety-nine people? Then the man drew his sword and killed him, completing a hundred. Then repentance again came to his mind, so he asked about the most knowledgeable person on earth. He was directed to a man, and he came to him and said: I have killed one hundred people; do I have any chance of repentance? He said: And who can stand between you and repentance? Leave the evil town you are in and go to the righteous town, such-and-such a place, and worship your Lord there. So he set out for the righteous town, but death came to him on the way. Then the angels of mercy and the angels of punishment disputed over him. Iblis said: I have more right to him, for he never disobeyed me for even an hour. The angels of mercy said: He went out in repentance.” Hammam said: Humayd al-Tawil narrated to me from Bakr ibn Abdullah al-Muzani, from Abu Rafiʿ, who said: “So Allah sent an angel to judge between them.” Then he returned to the narration of Qatadah, who said: “He said: Look to which of the two towns he was closer, and attach him to its people.” Qatadah said: Al-Hasan narrated to us, saying: “When he realized death was near, he drew himself forward with effort, so Allah brought the righteous town nearer to him and made the evil town farther away from him, and they attached him to the people of the righteous town.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3470,"lafz":true},{"key":"muslim","label":"مسلم","number":2766},{"key":"ahmad","label":"مسند الإمام أحمد","number":11154,"n":11154}],"full":1,"dr":1},{"num":6834,"demo":false,"sanad":"","matn":["عَنْ سَلَمَةَ، قَالَ خَرَجْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى خَيْبَرَ فَقَالَ رَجُلٌ مِنْهُمْ أَسْمِعْنَا يَا عَامِرُ مِنْ هُنَيْهَاتِكَ. فَحَدَا بِهِمْ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنِ السَّائِقُ قَالُوا عَامِرٌ. فَقَالَ رَحِمَهُ اللَّهُ. فَقَالُوا يَا رَسُولَ اللَّهِ هَلاَّ أَمْتَعْتَنَا بِهِ. فَأُصِيبَ صَبِيحَةَ لَيْلَتِهِ فَقَالَ الْقَوْمُ حَبِطَ عَمَلُهُ، قَتَلَ نَفْسَهُ. فَلَمَّا رَجَعْتُ وَهُمْ يَتَحَدَّثُونَ أَنَّ عَامِرًا حَبِطَ عَمَلُهُ، فَجِئْتُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ يَا نَبِيَّ اللَّهِ فَدَاكَ أَبِي وَأُمِّي، زَعَمُوا أَنَّ عَامِرًا حَبِطَ عَمَلُهُ. فَقَالَ كَذَبَ مَنْ قَالَهَا، إِنَّ لَهُ لأَجْرَيْنِ اثْنَيْنِ، إِنَّهُ لَجَاهِدٌ مُجَاهِدٌ، وَأَىُّ قَتْلٍ يَزِيدُهُ عَلَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في الديات (6891) ومسلم في الجهاد والسير (1802) كلاهما من طريق يزيد بن أبي عبيد مولى سلمة بن الأكوع، عن سلمة بن الأكوع، فذكره.","grade":"متفق عليه","chapter_ar":"باب من قتل نفسه خطأ","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (6891) and Muslim (1802), with the wording here from al-Bukhari.","chapter_en":"One who kills himself by mistake","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Salamah said: We went out with the Prophet ﷺ to Khaybar. One of the people said: “Let us hear some of your verses, O Amir.” So he chanted for them. The Prophet ﷺ said: “Who is the one driving the camels?” They said: “Amir.” He said: “May Allah have mercy on him.” They said: “O Messenger of Allah ﷺ, if only you had allowed us to benefit from him longer.” He was then struck down the next morning. The people said: “His deeds are lost; he killed himself.” When I returned — and the people were talking that Amir’s deeds had been lost — I came to the Prophet ﷺ and said: “O Prophet of Allah, may my father and mother be sacrificed for you, they claim that Amir’s deeds are lost.” He said: “Whoever said that has lied. He will have a double reward. He was a striving fighter in the path of Allah. And what death could be greater than this for him?”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6891,"lafz":true},{"key":"muslim","label":"مسلم","number":1802}],"full":1,"dr":1},{"num":6835,"demo":false,"sanad":"","matn":["عَنْ أَبِي شُرَيْحٍ قَالَ: قَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إن أَعْتَى النَّاسِ عَلَى اللَّهِ مَنْ قَتَلَ غَيْرَ قَاتِلِهِ، ومن طَلَبَ بِدَمِ الْجَاهِلِيَّةِ مِنْ أَهْلِ الْإِسْلَامِ، ومن بصّر عَيْنَيْهِ فِي الْمَنَامِ مَا لَمْ تُبْصِر."],"takhrij":"حسن: رواه أحمد (16378) والطبراني في الكبير (22/191) وابن أبي عاصم في الديات (225) والدراقطني (3/96) والحاكم (4/349) كلهم من حديث عبد الرحمن بن إسحاق، عن الزهري، عن عطاء بن يزيد الليثي، عن أبي شريح فذكره.","grade":"حسن","chapter_ar":"باب من قتل غير قاتله","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (16378), al-Tabarani in al-Kabir (22/191), and Ibn Abi Asim in al-Diyat (225).","chapter_en":"One who kills someone other than his killer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Abu Shurayh said: The Messenger of Allah ﷺ said: “Among the most defiant people against Allah is one who kills someone other than the one who killed him, one who seeks vengeance for bloodshed from the pre-Islamic age among the people of Islam, and one who claims that his eyes saw in a dream what they did not see.”"]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":191},{"key":"rb280","label":"ابن أبي عاصم في الديات","number":225},{"key":"ahmad","label":"مسند الإمام أحمد","number":16378,"n":16378,"lafz":true}],"full":1,"dr":1},{"num":6836,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: وُجِدَ فِي قَائِمِ سَيْفِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كِتَابَانِ: إِنَّ أَشَدَّ النَّاسِ عُتُوًّا فِي الْأَرْضِ رَجُلٌ ضَرَبَ غَيْرَ ضَارِبِهِ، وَرَجُلٌ قَتَلَ غَيْرَ قَاتِلِهِ، وَرَجُلٌ تَوَلَّى غَيْرَ أَهْلِ نِعْمَتِهِ، فَمَنْ فَعَلَ ذَلِكَ فَقَدْ كَفَرَ بِاللَّهِ وَبِرُسُلِهِ، لَا يَقْبَلُ اللَّهُ مِنْهُ صَرْفًا وَلَا عَدْلًا."],"takhrij":"حسن: رواه ابن أبي عاصم في الديات (228) واللفظ له، وأبو يعلى (4757) والدارقطني (3/131) والحاكم (4/349) والبيهقي (8/29-31) كلهم من حديث عبيد الله بن عبد المجيد، نا عبيد الله بن عبد الرحمن بن موهب، قال: سمعت مالك بن محمد بن عبد الرحمن، يحدث عن عمرة، عن عائشة فذكرته في حديث أطول منه.","grade":"حسن","chapter_ar":"باب من قتل غير قاتله","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Abi Asim in al-Diyat (228), and this is his wording, as well as Abu Yaʿla (4757) and al-Daraqutni (3/131).","chapter_en":"One who kills someone other than his killer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["ʿA’ishah said: Two writings were found in the hilt of the sword of the Messenger of Allah ﷺ: “Among the people who are most defiant toward Allah are: a man who strikes someone other than the one who struck him, a man who kills someone other than the one who killed him, and a man who ascribes himself to other than those who bestowed favor upon him. Whoever does that has indeed disbelieved in Allah and His Messenger. No obligatory act or voluntary act will be accepted from him.”"]}},"tuhfa":{},"refs":[{"key":"rb280","label":"ابن أبي عاصم في الديات","number":228,"lafz":true},{"key":"sh12520","label":"أبو يعلى","number":4757},{"key":"sh9771","label":"الدارقطني","number":131},{"key":"sh9771","label":"سنن الدارقطني","number":3249,"n":3263}],"full":1,"dr":1},{"num":6837,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: كَانَ قُرَيْظَةُ وَالنَّضِيرُ. وَكَانَ النَّضِيرُ أَشْرَفَ مِنْ قُرَيْظَةَ. فَكَانَ إِذَا قَتَلَ رَجُلٌ مِنْ قُرَيْظَةَ رَجُلاً مِنَ النَّضِيرِ قُتِلَ بِهِ، وَإِذَا قَتَلَ رَجُلٌ مِنَ النَّضِيرِ فُودِيَ بمئة وَسْقٍ مِنْ تَمْرٍ، فَلَمَّا بُعِثَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَتَلَ رَجُلٌ مِنَ النَّضِيرِ رَجُلاً مِنْ قُرَيْظَةَ. فَقَالُوا: ادْفَعُوهُ إِلَيْنَا نَقْتُلْهُ. فَقَالُوا: بَيْنَنَا وَبَيْنَكُمُ النَّبِيُّ، فَأَتَوْهُ، فَنَزَلَتْ: ﴿وَإِنْ حَكَمْتَ فَاحْكُمْ بَيْنَهُمْ بِالْقِسْطِ﴾ [المائدة: ٤٢ ] وَالْقِسْطُ: النَّفْسُ بِالنَّفْسِ، ثُمَّ نَزَلَتْ: أَفَحُكْمَ الْجَاهِلِيَّةِ يَبْغُونَ [المائدة: ٥٠ ]."],"takhrij":"حسن: رواه أبو داود (4494) والنسائي (4732) وابن الجارود (772) وصحّحه ابن حبان (5057) والحاكم (4/366) كلهم من حديث عبيدالله بن موسى، عن علي بن صالح، عن سماك بن حرب، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب النفس بالنفس","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4494), al-Nasa’i (4732), and Ibn al-Jarud (772), and authenticated by Ibn Hibban (5057).","chapter_en":"A life for a life","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Ibn Abbas said: Qurayzah and Nadir were two tribes, and Nadir was nobler than Qurayzah. So when a man from Qurayzah killed a man from Nadir, he would be killed for him; but when a man from Nadir killed a man from Qurayzah, a ransom of one hundred wasqs of dates would be paid for him. Then when the Prophet ﷺ was sent, a man from Nadir killed a man from Qurayzah. They said: Hand him over to us so we may kill him. The others said: Let the Prophet ﷺ judge between us and you. So they came to him, and Allah revealed: “And if you judge, then judge between them with justice.” [al-Ma’idah: 42] And justice here means: a life for a life. Then Allah revealed: “Is it the judgment of the Age of Ignorance that they seek?” [al-Ma’idah: 50]"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4494,"lafz":true},{"key":"nasai","label":"النسائي","number":4732,"n":4732},{"key":"sh13071","label":"ابن الجارود","number":772,"n":803},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":5057},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4308,"n":4304}],"full":1,"dr":1},{"num":6838,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللَّهُ عَنْهُ قَالَ كُنَّا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَجْلِسٍ فَقَالَ بَايِعُونِي عَلَى أَنْ لاَ تُشْرِكُوا بِاللَّهِ شَيْئًا وَلاَ تَسْرِقُوا، وَلاَ تَزْنُوا. وَقَرَأَ هَذِهِ الآيَةَ كُلَّهَا فَمَنْ وَفَى مِنْكُمْ فَأَجْرُهُ عَلَى اللَّهِ وَمَنْ أَصَابَ مِنْ ذَلِكَ شَيْئًا فَعُوقِبَ بِهِ، فَهْوَ كَفَّارَتُهُ، وَمَنْ أَصَابَ مِنْ ذَلِكَ شَيْئًا، فَسَتَرَهُ اللَّهُ عَلَيْهِ، إِنْ شَاءَ غَفَرَ لَهُ، وَإِنْ شَاءَ عَذَّبَهُ."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6784) ومسلم في الحدود (41:1709) كلاهما من طريق الزهري، عن أبي إدريس الخولاني، عن عبادة بن الصامت، فذكره.","grade":"متفق عليه","chapter_ar":"باب أن القصاص والحدود كفّاراتٌ لأهلها","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (6784) and Muslim (1709, no. 41).","chapter_en":"Retaliation and prescribed punishments are expiations for those upon whom they are carried out","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Ubadah ibn al-Samit said: We were with the Prophet ﷺ in a gathering, and he said: “Pledge allegiance to me that you will not associate anything with Allah, nor steal, nor commit adultery” — and he recited the entire verse. “Whoever among you fulfills that, his reward is with Allah. Whoever does any of that and is punished for it, then it is an expiation for him. And whoever does any of that and Allah conceals it for him, then if Allah wills He will forgive him, and if He wills He will punish him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6784,"lafz":true},{"key":"muslim","label":"مسلم","number":41}],"full":1,"dr":1},{"num":6839,"demo":false,"sanad":"","matn":["عَنْ ابْنِ مَسْعُودٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : لاَ يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ يَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنِّي رَسُولُ اللَّهِ إِلاَّ بِإِحْدَى ثَلاَثٍ: النفس بِالنَّفْسِ، والثيب الزَّانِي، والمفارق لِدِينِهِ التارك لِلْجَمَاعَةِ."],"takhrij":"متفق عليه: رواه البخاري في الديات (6878)، ومسلم في القيامة (1676) كلاهما من طريق الأعمش، عن عبد الله بن مرة، عن مسروق، عن عبد الله بن مسعود، فذكره.","grade":"متفق عليه","chapter_ar":"باب القصاص في قتل العمد إلا إذا عفا أولياء المقتول","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (6878) and Muslim (1676).","chapter_en":"Retaliation in intentional killing, unless the heirs of the slain pardon","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Ibn Masud said: The Messenger of Allah ﷺ said: “The blood of a Muslim man who testifies that there is no god but Allah and that I am the Messenger of Allah ﷺ is not lawful except for one of three: a life for a life, a previously married adulterer, and one who leaves his religion and separates from the community.”"]},"intro":{"ar":["قال اللّٰه تعالى: ( أَنَّ النَّفْسَ بِالنَّفْسِ) [المائدة: ٤٥]","وقال تعالى: ( كُتِبَ عَلَيْكُمُ ٱلْقِصَاصُ فِي الْقَتْلَى) [البقرة: ١٧٨ ]"],"en":["Allah Most High said: “A life for a life.” [al-Ma’idah: 45]","And He said: “Prescribed for you is legal retaliation in cases of those killed.” [al-Baqarah: 178]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6878,"lafz":true},{"key":"muslim","label":"مسلم","number":1676}],"full":1,"dr":1},{"num":6840,"demo":false,"sanad":"","matn":["عَنْ وَائِلِ بْنِ حُجْرٍ قَالَ: إِنِّي لَقَاعِدٌ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ جَاءَ رَجُلٌ يَقُودُ آخَرَ بِنِسْعَةٍ فَقَالَ: يَا رَسُولَ اللَّهِ! هَذَا قَتَلَ أَخِي. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَقَتَلْتَهُ؟ فَقَالَ: إِنَّهُ لَوْ لَمْ يَعْتَرِفْ أَقَمْتُ عَلَيْهِ الْبَيِّنَةَ – قَالَ: نَعَمْ قَتَلْتُهُ. قَالَ: كَيْفَ قَتَلْتَهُ؟ قَالَ: كُنْتُ أَنَا وَهُوَ نَخْتَبِطُ مِنْ شَجَرَةٍ، فَسَبَّنِي فَأَغْضَبَنِي، فَضَرَبْتُهُ بِالْفَأْسِ عَلَى قَرْنِهِ فَقَتَلْتُهُ. فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : هَلْ لَكَ مِنْ شيء تُؤَدِّيهِ عَنْ نَفْسِكَ؟ قَالَ: مَا لِي مَالٌ إِلاَّ كِسَائِي وَفَأْسِي. قَالَ: فَتَرَى قَوْمَكَ يَشْتَرُونَكَ؟ قَالَ: أَنَا أَهْوَنُ عَلَى قَوْمِي مِنْ ذَاكَ. فَرَمَى إِلَيْهِ بِنِسْعَتِهِ وَقَالَ: دُونَكَ صَاحِبَكَ فَانْطَلَقَ بِهِ الرَّجُلُ. فَلَمَّا ولّى قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنْ قَتَلَهُ فَهُوَ مِثْلُهُ فَرَجَعَ. فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّهُ بَلَغَنِي أَنَّكَ قُلْتَ: إِنْ قَتَلَهُ فَهُوَ مِثْلُهُ، وَأَخَذْتُهُ بِأَمْرِكَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَمَا تُرِيدُ أَنْ يَبُوءَ بِإِثْمِكَ وَإِثْمِ صَاحِبِكَ؟. قَالَ: يَا نَبِيَّ اللَّهِ – لَعَلَّهُ قَالَ: بَلَى، قَالَ: فَإِنَّ ذَاكَ كَذَاكَ قَالَ: فَرَمَى بِنِسْعَتِهِ وَخَلَّى سَبِيلَهُ."],"takhrij":"صحيح: رواه مسلم في القسامة (1680: 32) عن عبيد الله بن معاذ العنبري، حدثنا أبي، حدثنا أبو يونس، عن سماك بن حرب، عن علقمة بن وائل، حدثه، أن أباه حدثه قال:فذكره.","grade":"صحيح","chapter_ar":"باب الترغيب في العفو عن القصاص","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1680, no. 32).","chapter_en":"Encouragement to pardon instead of demanding retaliation","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Wa’il ibn Hujr said: I was sitting with the Prophet ﷺ when a man came leading another man with a strap and said: O Messenger of Allah ﷺ, this man killed my brother. The Messenger of Allah ﷺ said: “Did you kill him?” He said: Had he not confessed, I would have produced evidence against him. He said: Yes, I killed him. He said: “How did you kill him?” He said: He and I were beating tree branches for fodder. He insulted me and made me angry, so I struck him on the head with an axe and killed him. The Prophet ﷺ said to him: “Do you have anything with which you can ransom yourself?” He said: I own nothing except my cloak and my axe. He said: “Do you think your people would buy you back?” He said: I am too insignificant among my people for that. So he threw the strap to the heir and said: “Take your companion.” The man went away with him. When he turned to leave, the Messenger of Allah ﷺ said: “If he kills him, then he is like him.” The man returned and said: O Messenger of Allah ﷺ, I was told that you said: “If he kills him, then he is like him,” yet I took him by your order. The Messenger of Allah ﷺ said: “Do you not want him to bear your sin and the sin of your companion?” He said: Yes, O Prophet of Allah. He said: “Then that is how it will be.” So he threw away the strap and let him go."]},"intro":{"ar":["قال اللّٰه تعالى: (فَمَن تَصَدَّقَ بِهِ، فَهُوَ كَفَّارَةٌ لَهُ ) [المائدة : ٤٥]"],"en":["Allah Most High said: “But whoever gives it up in charity, it will be an expiation for him.” [al-Ma’idah: 45]"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1680,"lafz":true}],"full":1,"dr":1},{"num":6841,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قُتِلَ رَجُلٌ عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرُفِعَ ذَلِكَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَدَفَعَهُ إِلَى وَلِيِّ الْمَقْتُولِ فَقَالَ الْقَاتِلُ يَا رَسُولَ اللَّهِ وَاللَّهِ مَا أَرَدْتُ قَتْلَهُ. قَالَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلْوَلِيِّ أَمَا إِنَّهُ إِنْ كَانَ صَادِقًا ثُمَّ قَتَلْتَهُ دَخَلْتَ النَّارَ. قَالَ فَخَلَّى سَبِيلَهُ. قَالَ وَكَانَ مَكْتُوفًا بِنِسْعَةٍ فَخَرَجَ يَجُرُّ نِسْعَتَهُ فَسُمِّيَ ذَا النِّسْعَةِ."],"takhrij":"صحيح: رواه أبو داود (4498)، والترمذي (1407) والنسائي (4722) وابن ماجة (2690) كلهم من حديث أبي معاوية، عن الأعمش، عن أبي صالح، عن أبي هريرة قال: فذكره. قال الترمذي: \"حسن صحيح\".","grade":"صحيح","chapter_ar":"باب الترغيب في العفو عن القصاص","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4498), al-Tirmidhi (1407), al-Nasa’i (4722), and Ibn Majah (2690). Al-Tirmidhi said: “Sound authentic.”","chapter_en":"Encouragement to pardon instead of demanding retaliation","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah said: A man was killed during the time of the Messenger of Allah ﷺ, so the matter was brought to the Prophet ﷺ, and he handed the killer over to the heir of the slain. The killer said: O Messenger of Allah ﷺ, by Allah, I did not intend to kill him. The Messenger of Allah ﷺ then said to the heir: “If he is truthful and you still kill him, you will enter the Fire.” So he let him go. He had been bound with a leather rope and left dragging it behind him, and so he was called “the man of the rope.”"]},"buhuth":{"en":["The word nisʿah means a rope."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4498,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1407},{"key":"nasai","label":"النسائي","number":4722,"n":4722},{"key":"ibnmajah","label":"ابن ماجه","number":2690}],"full":1,"dr":1},{"num":6842,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ أَتَى رَجُلٌ بِقَاتِلِ وَلِيِّهِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اعْفُ. فَأَبَى فَقَالَ خُذْ أَرْشَكَ. فَأَبَى. قَالَ اذْهَبْ فَاقْتُلْهُ فَإِنَّكَ مِثْلُهُ. قَالَ فَلُحِقَ بِهِ فَقِيلَ لَهُ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ قَالَ اقْتُلْهُ فَإِنَّكَ مِثْلُهُ. فَخَلَّى سَبِيلَهُ. قَالَ فَرُئِيَ يَجُرُّ نِسْعَتَهُ ذَاهِبًا إِلَى أَهْلِهِ. قَالَ كَأَنَّهُ قَدْ كَانَ أَوْثَقَهُ."],"takhrij":"حسن: رواه ابن ماجة (2691) والنسائي (4730) وابن أبي عاصم في الديات (221،101) كلهم من حديث ضمرة بن ربيعة، عن ابن شوذب، عن ثابت البناني، عن أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب الترغيب في العفو عن القصاص","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Majah (2691), al-Nasa’i (4730), and Ibn Abi Asim in al-Diyat (101, 221).","chapter_en":"Encouragement to pardon instead of demanding retaliation","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Malik said: A man brought the killer of his relative to the Messenger of Allah ﷺ. The Prophet ﷺ said to him: “Pardon him.” He refused. He said: “Then take the blood-money.” He refused. He said: “Then go and kill him, for you will be like him.” The man then set out with him. He was caught up with and told: The Messenger of Allah ﷺ has said: “Kill him and you will be like him.” So he let him go. He was later seen dragging his rope as he returned to his family, as though he had been tied with it."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2691,"lafz":true},{"key":"nasai","label":"النسائي","number":4730},{"key":"rb280","label":"ابن أبي عاصم في الديات","number":101}],"full":1,"dr":1},{"num":6843,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ مَا رُفِعَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَىْءٌ فِيهِ الْقِصَاصُ إِلاَّ أَمَرَ فِيهِ بِالْعَفْوِ."],"takhrij":"حسن: رواه أبو داود (4497) والنسائي (4784،4783) وابن ماجة (2692) وأحمد (13220) والبيهقي (8/54) كلهم من حديث عبد الله بن بكر المزني، حدثنا عطاء بن أبي ميمونة قال: ولا أعلمه إلا عن أنس بن مالك فذكره. وإسناده حسن من أجل عبد الله بن بكر بن عبد الله المزني البصري فإنه حسن الحديث.","grade":"حسن","chapter_ar":"باب الترغيب في العفو عن القصاص","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4497), al-Nasa’i (4783, 4784), Ibn Majah (2692), and Ahmad (13220).","chapter_en":"Encouragement to pardon instead of demanding retaliation","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Malik said: No case involving retaliation was ever brought to the Messenger of Allah ﷺ except that he would encourage pardon in it."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4497,"lafz":true},{"key":"nasai","label":"النسائي","number":4783},{"key":"ibnmajah","label":"ابن ماجه","number":2692},{"key":"ahmad","label":"مسند الإمام أحمد","number":13220,"n":13220},{"key":"nasai","label":"النسائي","number":4784}],"full":1},{"num":6844,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أُصِيبَ بِشَيْءٍ فِي جَسَدِهِ فَتَرَكَهُ لِلَّهِ كَانَ كَفَّارَةً لَهُ."],"takhrij":"حسن: رواه أحمد (23494) عن يحيى بن سعيد القطان، عن مجالد، عن عامر، عن المحرر بن أبي هريرة، عن رجل من أصحاب النبي صلى الله عليه وسلم فذكره.","grade":"حسن","chapter_ar":"باب الترغيب في العفو عن القصاص","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (23494) and Ibn Abi Shaybah in his Musnad, as cited in al-Matalib al-ʿAliyah (1908).","chapter_en":"Encouragement to pardon instead of demanding retaliation","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["A man from among the Companions of the Prophet ﷺ narrated from the Prophet ﷺ that he said: “Whoever is afflicted by an injury in his body and then forgoes retaliation for the sake of Allah, it will be an expiation for him.”"]}},"tuhfa":{},"refs":[{"key":"ابن_ابی_شیبہ/مسندہ_کما_فی_المطالب_العالیہ","label":"ابن أبي شيبة في مسنده كما في المطالب العالية","number":1908},{"key":"ahmad","label":"مسند الإمام أحمد","number":23494,"n":23494,"lafz":true}],"full":1,"dr":1},{"num":6845,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَحُثُّ فِي خُطْبَتِهِ عَلَى الصَّدَقَةِ وَيَنْهَى عَنِ الْمُثْلَةِ."],"takhrij":"صحيح: رواه النسائي (4047) وابن أبي عاصم في الديات (324) والضياء في المختارة (7/68) كلهم من حديث عبد الصمد، نا هشام، عن قتادة، عن أنس فذكره، وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب الإحسان في القصاص","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasa’i (4047), Ibn Abi Asim in al-Diyat (324), and al-Diya’ in al-Mukhtarah (7/68).","chapter_en":"Excellence and restraint in retaliation","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ used to encourage charity in his sermons and forbid mutilation."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4047,"lafz":true},{"key":"rb280","label":"ابن أبي عاصم في الديات","number":324},{"key":"sh10480","label":"الضياء في المختارة","number":7}],"full":1,"rep":[7042]},{"num":6846,"demo":false,"sanad":"","matn":["عَنِ الْحَسَنِ، قَالَ: جَاءَهُ رَجُلٌ فَقَالَ: إِنَّ عَبْدًا لَهُ أَبَقَ، وَإِنَّهُ نَذَرَ إِنْ قَدَرَ عَلَيْهِ أَنْ يَقْطَعَ يَدَهُ، فَقَالَ الْحَسَنُ: حَدَّثَنَا سَمُرَةُ، قَالَ: قَلَّمَا خَطَبَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خُطْبَةً إِلَّا أَمَرَ فِيهَا بِالصَّدَقَةِ، وَنَهَى فِيهَا عَنِ الْمُثْلَةِ."],"takhrij":"صحيح: رواه أحمد (20136) عن هشيم، حدثنا حميد، عن الحسن فذكره.","grade":"صحيح","chapter_ar":"باب الإحسان في القصاص","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (20136).","chapter_en":"Excellence and restraint in retaliation","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Al-Hasan al-Basri said: A man came to him and said: I had a slave who ran away, and I vowed that if I caught him I would cut off his hand. Al-Hasan said: Samurah narrated to us that the Prophet ﷺ rarely gave a sermon except that he encouraged charity in it and forbade mutilation."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":20136,"n":20136,"lafz":true}],"full":1,"dr":1},{"num":6847,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى بِالْقِصَاصِ فِي السِّنِّ وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كِتَابُ اللَّهِ الْقِصَاصُ."],"takhrij":"صحيح: رواه النسائي (4752) وابن أبي عاصم في الديات (126) وابن الجارود (841) كلهم من حديث أبي خالد سليمان بن حيان قال: حدثنا حُميد، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب القصاص في السِّنَّ","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasa’i (4752), Ibn Abi Asim in al-Diyat (126), and Ibn al-Jarud (841).","chapter_en":"Retaliation regarding a tooth","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Anas reported that the Messenger of Allah ﷺ ruled that retaliation applies in the case of a tooth, and the Messenger of Allah ﷺ said: “The Book of Allah prescribes retaliation.”"]},"intro":{"ar":["قال تعالى: ﴿وَكَتَبْنَا عَلَيْهِمْ فِيهَا أَنَّ النَّفْسَ بِالنَّفْسِ وَالْعَيْنَ بِالْعَيْنِ وَالْأَنْفَ بِالْأَنْفِ وَالْأُذُنَ بِالْأُذُنِ وَالسِّنَّ بِالسِّنِّ﴾ [المائدة: ٤٥]"],"en":["Allah Most High said: “And We prescribed for them in it: a life for a life, an eye for an eye, a nose for a nose, an ear for an ear, and a tooth for a tooth.” [al-Ma’idah: 45]"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4752,"lafz":true},{"key":"rb280","label":"ابن أبي عاصم في الديات","number":126},{"key":"sh13071","label":"ابن الجارود","number":841}],"full":1,"dr":1},{"num":6848,"demo":false,"sanad":"","matn":["أَنَسًا، حَدَّثَهُمْ أَنَّ الرُّبَيِّعَ ـ وَهْىَ ابْنَةُ النَّضْرِ ـ كَسَرَتْ ثَنِيَّةَ جَارِيَةٍ، فَطَلَبُوا الأَرْشَ وَطَلَبُوا الْعَفْوَ، فَأَبَوْا فَأَتَوُا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَمَرَهُمْ بِالْقِصَاصِ. فَقَالَ أَنَسُ بْنُ النَّضْرِ أَتُكْسَرُ ثَنِيَّةُ الرُّبَيِّعِ يَا رَسُولَ اللَّهِ لاَ وَالَّذِي بَعَثَكَ بِالْحَقِّ لاَ تُكْسَرُ ثَنِيَّتُهَا فَقَالَ يَا أَنَسُ كِتَابُ اللَّهِ الْقِصَاصُ. فَرَضِيَ الْقَوْمُ وَعَفَوْا فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ مِنْ عِبَادِ اللَّهِ مَنْ لَوْ أَقْسَمَ عَلَى اللَّهِ لأَبَرَّهُ.","زاد الفزاري، عن حميد، عن أنس: فرضي القوم وقبلوا الأرش."],"takhrij":"صحيح: رواه البخاري في الصلح (2703) عن محمد بن عبد الله الأنصاري قال: حدثني حميد، أن أنسا حدثهم فذكر الحديث.","grade":"صحيح","chapter_ar":"باب القصاص في السِّنَّ","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (4611, 2703).","chapter_en":"Retaliation regarding a tooth","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Anas reported that al-Rabiʿ — the daughter of al-Nadr — broke the front tooth of a young woman. They asked for compensation, and they also asked for pardon, but the people refused. So they brought the matter to the Prophet ﷺ, and he ordered retaliation. Anas ibn al-Nadr said: O Messenger of Allah ﷺ, will the tooth of al-Rabiʿ be broken? No, by the One who sent you with the truth, her tooth will not be broken. The Prophet ﷺ said: “O Anas, the Book of Allah prescribes retaliation.” Then the people were pleased and pardoned her, and the Prophet ﷺ said: “Among the servants of Allah are those who, if they swear by Allah, He fulfills it for them.” Al-Fazari added, from Humayd, from Anas: “The people were pleased and accepted the compensation.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4611},{"key":"bukhari","label":"البخاري في الصلح","number":2703,"lafz":true}],"full":1,"dr":1},{"num":6849,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ أُخْتَ الرُّبَيِّعِ أُمَّ حَارِثَةَ، جَرَحَتْ إِنْسَانًا فَاخْتَصَمُوا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْقِصَاصَ الْقِصَاصَ. فَقَالَتْ أُمُّ الرَّبِيعِ يَا رَسُولَ اللَّهِ أَيُقْتَصُّ مِنْ فُلاَنَةَ وَاللَّهِ لاَ يُقْتَصُّ مِنْهَا. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُبْحَانَ اللَّهِ يَا أُمَّ الرَّبِيعِ الْقِصَاصُ كِتَابُ اللَّهِ. قَالَتْ لاَ وَاللَّهِ لاَ يُقْتَصُّ مِنْهَا أَبَدًا. قَالَ فَمَا زَالَتْ حَتَّى قَبِلُوا الدِّيَةَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ مِنْ عِبَادِ اللَّهِ مَنْ لَوْ أَقْسَمَ عَلَى اللَّهِ لأَبَرَّهُ."],"takhrij":"صحيح (مع شذوذ فيه): رواه مسلم في القسامة (1675) عن أبي بكر بن أبي شيبة، حدثنا عفان بن مسلم، حدثنا حماد بن سلمة، أخبرنا ثابت، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب القصاص في السِّنَّ","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1675).","chapter_en":"Retaliation regarding a tooth","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Anas reported that the sister of al-Rabiʿ, the mother of Harithah, injured a person, and they took their dispute to the Prophet ﷺ. The Messenger of Allah ﷺ said: “Retaliation, retaliation.” The mother of al-Rabiʿ said: O Messenger of Allah ﷺ, will retaliation be taken from so-and-so? By Allah, retaliation will never be taken from her. The Messenger of Allah ﷺ said: “Glory be to Allah, O mother of al-Rabiʿ, retaliation is in the Book of Allah.” She said: No, by Allah, retaliation will never be taken from her. She continued until they accepted the blood-money. Then the Messenger of Allah ﷺ said: “Among the servants of Allah are those who, if they swear by Allah, He fulfills it for them.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1675,"lafz":true}],"full":1,"dr":1,"rep":[10445]},{"num":6850,"demo":false,"sanad":"","matn":["عَنْ أنس قَالَ: خَرَجَتْ جَارِيَةٌ عَلَيْهَا أَوْضَاحٌ بِالْمَدِينَةِ، قَالَ: فَرَمَاهَا يَهُودِيٌّ بِحَجَرٍ، قَالَ: فَجِيءَ بِهَا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَبِهَا رَمَقٌ، فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فُلاَنٌ قَتَلَكِ؟ فَرَفَعَتْ رَأْسَهَا، فَأَعَادَ عَلَيْهَا، قَالَ: فُلاَنٌ قَتَلَكِ؟ فَرَفَعَتْ رَأْسَهَا، فَقَالَ لَهَا فِي الثَّالِثَةِ: فُلاَنٌ قَتَلَكِ؟ فَخَفَضَتْ رَأْسَهَا، فَدَعَا بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَتَلَهُ بَيْنَ الْحَجَرَيْنِ.","وفي رواية: فأخذ فأتي به رسول الله صلى الله عليه وسلم فأمر به أن يرجم حتى يموت، فرجم حتى مات."],"takhrij":"متفق عليه: رواه البخاري في الديات (6877) ومسلم في القسامة (15:1672) كلاهما من طريق شعبة، عن هشام بن زيد، عن أنس بن مالك، فذكره.","grade":"متفق عليه","chapter_ar":"باب من القود يُقتل القاتل بمثل القتلة التي قتلها","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (6877) and Muslim (1672, no. 15). The second wording is in Muslim.","chapter_en":"In retaliation, the killer may be killed in the same manner in which he killed","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Anas ibn Malik said: A young girl wearing silver ornaments went out in Madinah, and a Jew struck her with a stone. She was brought to the Prophet ﷺ while she still had a faint sign of life. The Messenger of Allah ﷺ asked her, “Did so-and-so kill you?” She raised her head. He asked her again, “Did so-and-so kill you?” She raised her head again. Then he asked her the third time, “Did so-and-so kill you?” She lowered her head. So the Messenger of Allah ﷺ called for him, and he was crushed between two stones. In another narration: He was seized and brought to the Messenger of Allah ﷺ, who ordered that stones be thrown at him until he died, and so he was stoned until he died."]},"intro":{"ar":["قال اللّٰه تعالى: ( وَإِنْ عَاقَبْتُمْ فَعَاقِبُوا بِمِثْلِ مَا عُوقِبْتُم بِهِه وَلَيِن صَبَرْتُمْ لَهُوَ خَيْرٌ لِلصَّبِرِينَ ) [سورة النحل: ١٢٦]","وقال تعالى: (وَجَزَوُا سَيِّئَةٍ سَيِّئَةٌ مِثْلُهَا) [الشورى: ٤٠]"],"en":["Allah Most High said: “If you punish, then punish with the like of that with which you were harmed; but if you are patient, it is better for those who are patient.” [al-Nahl: 126]","And He said: “The recompense of an evil is an evil like it.” [al-Shura: 40]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6877,"lafz":true},{"key":"muslim","label":"مسلم","number":15}],"full":1,"dr":1},{"num":6851,"demo":false,"sanad":"","matn":["عن ابن عمر أَنَّ غُلَامًا قُتِلَ غِيلَةً، فَقَالَ عُمَرُ: لَوْ اشْتَرَكَ فِيهَا أَهْلُ صَنْعَاءَ لَقَتَلْتُهُمْ."],"takhrij":"صحيح: رواه البخاري في الديات (6896) فقال: قال لي ابن بشار، حدثنا يحيى، عن عبيد الله، عن نافع، عن ابن عمر قال: فذكره.","grade":"صحيح","chapter_ar":"باب إذا اشترك جماعة في القتل يُقتَصَّ منهم جميعا","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (6896).","chapter_en":"If a group shares in a killing, retaliation is taken from all of them","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["Ibn Umar reported that a boy was killed treacherously, and Umar said: “If all the people of Sana’a had shared in it, I would have killed them all for it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6896,"lafz":true}],"full":1,"dr":1},{"num":6852,"demo":false,"sanad":"","matn":["عن أَبِي جُحَيْفَةَ قَالَ: سَأَلْتُ عَلِيًّا رَضِيَ اللَّهُ عَنْهُ هَلْ عِنْدَكُمْ شَىْءٌ مِمَّا لَيْسَ فِي الْقُرْآنِ ـ وَقَالَ ابْنُ عُيَيْنَةَ مَرَّةً مَا لَيْسَ عِنْدَ النَّاسِ ـ فَقَالَ وَالَّذِي فَلَقَ الْحَبَّةَ وَبَرَأَ النَّسَمَةَ مَا عِنْدَنَا إِلاَّ مَا فِي الْقُرْآنِ إِلاَّ فَهْمًا يُعْطَى رَجُلٌ فِي كِتَابِهِ وَمَا فِي الصَّحِيفَةِ. قُلْتُ وَمَا فِي الصَّحِيفَةِ قَالَ الْعَقْلُ، وَفِكَاكُ الأَسِيرِ، وَأَنْ لاَ يُقْتَلَ مُسْلِمٌ بِكَافِرٍ."],"takhrij":"صحيح: رواه البخاري في الديات (6915) من طريق مطرّف قال: سمعت الشعبي يحدث قال: سمعت أيا جحيفة (واسمه وهب بن عبد الله السوائي) فذكره.","grade":"صحيح","chapter_ar":"باب المسلمون تتكافأ دماؤهم وذمتهم واحدة ولا يقتل مؤمن بكافر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (6915).","chapter_en":"The blood of Muslims is equal, their pledge of protection is one, and a believer is not killed for a disbeliever","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["Abu Juhayfah said: I asked Ali, may Allah be pleased with him, “Do you have anything that is not in the Qur’an?” Ibn Uyaynah once worded it, “Anything that the people do not have?” He replied, “By the One who splits the grain and creates the soul, we have nothing except what is in the Qur’an, except an understanding Allah gives a man of His Book, and what is in this written sheet.” I said, “What is in the sheet?” He said: “The blood-money, the ransom of captives, and that a Muslim is not to be killed for a disbeliever.”"]},"buhuth":{"en":["Its meaning is that a believer is not killed in retaliation for a disbeliever, because of the honor of Islam and the deficiency of disbelief. Retaliation implies equality, and there is no equality between a disbeliever and a Muslim. However, the ruler may execute a Muslim killer as a discretionary punishment in order to preserve public safety."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6915,"lafz":true}],"full":1,"dr":1},{"num":6853,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ مَا كَتَبْنَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلاَّ الْقُرْآنَ، وَمَا فِي هَذِهِ الصَّحِيفَةِ، قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةُ حَرَامٌ مَا بَيْنَ عَائِرٍ إِلَى كَذَا، فَمَنْ أَحْدَثَ حَدَثًا، أَوْ آوَى مُحْدِثًا، فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلاَئِكَةِ وَالنَّاسِ أَجْمَعِينَ، لاَ يُقْبَلُ مِنْهُ عَدْلٌ وَلاَ صَرْفٌ، وَذِمَّةُ الْمُسْلِمِينَ وَاحِدَةٌ يَسْعَى بِهَا أَدْنَاهُمْ. فَمَنْ أَخْفَرَ مُسْلِمًا فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلاَئِكَةِ وَالنَّاسِ أَجْمَعِينَ، لاَ."],"takhrij":"متفق عليه: رواه البخاري في الجزية والموادعة (3179) ومسلم في الحج (468:1370) كلاهما من طريق الأعمش، عن إبراهيم التميمي، عن أبيه، عن علي، فذكره إسحاق والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب المسلمون تتكافأ دماؤهم وذمتهم واحدة ولا يقتل مؤمن بكافر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (3179) and Muslim (1370, no. 468), with this wording from al-Bukhari.","chapter_en":"The blood of Muslims is equal, their pledge of protection is one, and a believer is not killed for a disbeliever","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["Ali ibn Abi Talib said: We did not write down from the Prophet ﷺ anything except the Qur’an and what is in this sheet. The Prophet ﷺ said: “Madinah is sacred between Ayr and such-and-such. Whoever introduces an offense there or shelters an offender, upon him is the curse of Allah, the angels, and all people. No obligatory act or voluntary act will be accepted from him. The protection granted by the Muslims is one, and even the lowest among them may grant it. Whoever violates the protection granted by a Muslim, upon him is the curse of Allah, the angels, and all people…”"]},"buhuth":{"en":["The phrase “akhfara” means: he violated his covenant."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3179,"lafz":true},{"key":"muslim","label":"مسلم","number":468}],"full":1,"dr":1},{"num":6854,"demo":false,"sanad":"","matn":["عَنْ إِبْرَاهِيمَ التَّيْمِيِّ، عَنْ أَبِيهِ قَالَ: خَطَبَنَا عَلِيُّ بْنُ أَبِي طَالِبٍ فَقَالَ: مَنْ زَعَمَ أَنَّ عِنْدَنَا شَيْئًا نَقْرَأُهُ إِلاَّ كِتَابَ اللَّهِ وَهَذِهِ الصَّحِيفَةَ فَقَدْ كَذَبَ. فِيهَا اسنان الإِبِلِ، وَأَشْيَاءُ مِنَ الْجِرَاحَاتِ، وَذِمَّةُ الْمُسْلِمِينَ واحد يَسْعَى بِهَا أَدْنَاهُمْ ...... وذكر بقية الحديث."],"takhrij":"متفق عليه: رواه البخاري في الاعتصام (7300) ومسلم في الحج (1370) كلاهما من حديث الأعمش، عن إبراهيم التيمي بإسناده فذكره.","grade":"متفق عليه","chapter_ar":"باب المسلمون تتكافأ دماؤهم وذمتهم واحدة ولا يقتل مؤمن بكافر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (7300) and Muslim (1370).","chapter_en":"The blood of Muslims is equal, their pledge of protection is one, and a believer is not killed for a disbeliever","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["Ibrahim al-Taymi narrated from his father, who said: Ali ibn Abi Talib addressed us and said: “Whoever claims that we possess anything to read besides the Book of Allah and this sheet has lied. In it are the ages and values of camels for compensation, rulings concerning certain wounds, and that the protection of the Muslims is one, and even the lowest among them may grant it…” Then he mentioned the rest of the hadith."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7300,"lafz":true},{"key":"muslim","label":"مسلم","number":1370}],"full":1},{"num":6855,"demo":false,"sanad":"","matn":["عَنْ أَبِي حَسَّانَ، أَنَّ عَلِيًّا، كَانَ يَأْمُرُ بِالْأَمْرِ فَيُؤْتَى، فَيُقَالُ: قَدْ فَعَلْنَا كَذَا وَكَذَا، فَيَقُولُ: صَدَقَ اللَّهُ وَرَسُولُهُ، قَالَ: فَقَالَ لَهُ الْأَشْتَرُ: إِنَّ هَذَا الَّذِي تَقُولُ قَدْ تَفَشَّغَ فِي النَّاسِ، أَفَشَيْءٌ عَهِدَهُ إِلَيْكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ عَلِيٌّ: مَا عَهِدَ إِلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَيْئًا خَاصَّةً دُونَ النَّاسِ، إِلا شَيْءٌ سَمِعْتُهُ مِنْهُ فَهُوَ فِي صَحِيفَةٍ فِي قِرَابِ سَيْفِي، قَالَ: فَلَمْ يَزَالُوا بِهِ حَتَّى أَخْرَجَ الصَّحِيفَةَ، قَالَ: فَإِذَا فِيهَا: مَنْ أَحْدَثَ حَدَثًا، أَوْ آوَى مُحْدِثًا فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلائِكَةِ وَالنَّاسِ أَجْمَعِينَ، لَا يُقْبَلُ مِنْهُ صَرْفٌ وَلا عَدْلٌ قَالَ: وَإِذَا فِيهَا: إِنَّ إِبْرَاهِيمَ حَرَّمَ مَكَّةَ، وَإِنِّي أُحَرِّمُ الْمَدِينَةَ، حَرَامٌ مَا بَيْنَ حَرَّتَيْهَا وَحِمَاهَا كُلُّهُ، لَا يُخْتَلَى خَلاهَا، وَلا يُنَفَّرُ صَيْدُهَا، وَلا تُلْتَقَطُ لُقَطَتُهَا، إِلا لِمَنْ أَشَارَ بِهَا، وَلا تُقْطَعُ مِنْهَا شَجَرَةٌ إِلا أَنْ يَعْلِفَ رَجُلٌ بَعِيرَهُ، وَلا يُحْمَلُ فِيهَا السِّلاحُ لِقِتَالٍ قَالَ: وَإِذَا فِيهَا: الْمُؤْمِنُونَ تَتَكَافَأُ دِمَاؤُهُمْ، وَيَسْعَى بِذِمَّتِهِمْ أَدْنَاهُمْ، وَهُمْ يَدٌ عَلَى مَنْ سِوَاهُمْ، أَلا لَا يُقْتَلُ مُؤْمِنٌ بِكَافِرٍ، وَلا ذُو عَهْدٍ فِي عَهْدِهِ."],"takhrij":"صحيح: رواه الإمام أحمد (959)- والسياق له- وأبو داود (2035) والنسائي (4745) وأحمد (959) كلهم من طريق همام، أخبرنا قتادة، عن أبي حسان فذكره.","grade":"صحيح","chapter_ar":"باب المسلمون تتكافأ دماؤهم وذمتهم واحدة ولا يقتل مؤمن بكافر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (959), al-Nasa’i (4746, 4745), and Abu Dawud (2035).","chapter_en":"The blood of Muslims is equal, their pledge of protection is one, and a believer is not killed for a disbeliever","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["Abu Hassan said: Ali, may Allah be pleased with him, would command something, and then when people came to him and said, “We have done such-and-such,” he would say, “Allah and His Messenger have spoken the truth.” Al-Ashtar said to him: “What you keep saying has spread widely among the people. Is it something the Messenger of Allah ﷺ entrusted to you in particular?” Ali, may Allah be pleased with him, said: “The Messenger of Allah ﷺ did not entrust me with anything exclusive over the people, except something I heard from him and it is written on a sheet in the sheath of my sword.” They continued asking him until he took out the sheet. In it was written: “Whoever introduces an offense or shelters an offender, upon him is the curse of Allah, the angels, and all people. No obligatory act or voluntary act will be accepted from him.” And in it was written: “Abraham made Makkah sacred, and I make Madinah sacred between its two lava tracts and all its protected land. Its fresh herbage is not to be cut, its game is not to be driven away, its lost property is not to be picked up except by one who announces it, and none of its trees are to be cut except for a man feeding his camel. Weapons are not to be carried in it for fighting.” And in it was written: “The believers’ blood is equal, the lowest among them may grant protection on behalf of them all, and they are united against others. A believer is not to be killed for a disbeliever, nor one under covenant while he remains under his covenant.” The phrase tafashshagha means: it became widespread and public."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الامام احمد","number":959,"lafz":true},{"key":"abudawud","label":"السياق له- وابو داود","number":2035},{"key":"nasai","label":"النسائي","number":4745}],"full":1,"dr":1},{"num":6856,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ يُقْتَلُ مُسْلِمٌ بِكَافِرٍ، وَقَالَ: دِيَةُ عَقْلِ الْكَافِرِ نِصْفُ دِيَةِ عَقْلِ الْمُؤْمِنِ."],"takhrij":"حسن: رواه الترمذي (1413) واللفظ له، وأحمد (6692) وغيرهما من طرق عن عمرو بن شعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب المسلمون تتكافأ دماؤهم وذمتهم واحدة ولا يقتل مؤمن بكافر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Tirmidhi (1413), and this is his wording, and Ahmad (6692).","chapter_en":"The blood of Muslims is equal, their pledge of protection is one, and a believer is not killed for a disbeliever","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["Amr ibn Shuayb narrated from his father, from his grandfather, that the Messenger of Allah ﷺ said: “A Muslim is not killed for a disbeliever.” And he also said: “The blood-money of a disbeliever is half the blood-money of a believer.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1413,"lafz":true},{"key":"ahmad","label":"احمد","number":6692,"n":6703}],"full":1,"dr":1},{"num":6857,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّهَا قَالَتْ: وَجَدْتُ فِي قَائِمِ سَيْفِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كِتَابًا: إِنَّ أَشَدَّ النَّاسِ عُتُوًّا مَنْ ضَرَبَ غَيْرَ ضَارِبِهِ، وَرَجُلٌ قَتَلَ غَيْرَ قَاتِلِهِ، وَرَجُلٌ تَوَلَّى غَيْرَ أَهْلِ نِعْمَتِهِ، فَمَنْ فَعَلَ ذَلِكَ فَقَدْ كَفَرَ بِاللَّهِ وَرَسُولِهِ لَا يَقْبَلُ اللَّهُ مِنْهُ صَرْفًا وَلَا عَدْلًا، وَفِي الْأَجْرِ الْمُؤْمِنُونَ تَكَافَأُ دِمَاؤُهُمْ وَيَسْعَى بِذِمَّتِهِمْ أَدْنَاهُمْ. لَا يُقْتَلُ مُسْلِمٌ بِكَافِرٍ وَلَا ذُو عَهْدٍ فِي عَهْدِهِ، وَلَا يَتَوَارَثُ أَهْلُ مِلَّتَيْنِ، وَلَا تُنْكَحُ الْمَرْأَةُ عَلَى عَمَّتِهَا وَلَا عَلَى خَالَتِهَا، وَلَا صَلَاةَ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ، وَلَا تُسَافِرُ امْرَأَةٌ ثَلَاثَ لَيَالٍ مَعَ غَيْرِ ذِي مَحْرَمٍ."],"takhrij":"حسن: رواه أبو يعلى (4757) عن أبي خيثمة، حدثنا عبيد الله بن عبدالمجيد، حدثنا عبيدالله بن عبد الرحمن بن موهب، سمعت مالك بن محمد بن عبدالرحمن قال: سمعت عمرة بنت عبدالرحمن، تحدث عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب المسلمون تتكافأ دماؤهم وذمتهم واحدة ولا يقتل مؤمن بكافر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Yaʿla (4757), Ibn Abi Asim in al-Diyat (107), al-Daraqutni (3/131), and al-Bayhaqi (8/29–30).","chapter_en":"The blood of Muslims is equal, their pledge of protection is one, and a believer is not killed for a disbeliever","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["ʿA’ishah said: A written document was found in the hilt of the sword of the Messenger of Allah ﷺ which said: “Among the people most defiant are: a man who strikes someone other than the one who struck him, a man who kills someone other than the one who killed him, and a man who allies himself with other than those who bestowed favor upon him. Whoever does that has disbelieved in Allah and His Messenger. Allah will accept from him neither obligatory nor voluntary deeds. In retribution, the believers’ blood is equal, and the lowest among them may grant protection on behalf of them all. A Muslim is not killed for a disbeliever, nor one under covenant while he remains under his covenant. The followers of two different religions do not inherit from one another. A woman is not married together with her paternal aunt nor with her maternal aunt. There is no prayer after the afternoon prayer until the sun sets. And no woman may travel for three nights without a close male relative.”"]},"buhuth":{"en":["The phrase “their blood is equal” means equality: the noble and the lowly are equal in retaliation. In other words, the blood of Muslims is equal in legal retaliation, so a noble person is retaliated against for killing a humble person, and an older person for a younger one. No one other than the killer is to be killed, even if the slain person was noble or wealthy. This is unlike the practice of the people of the pre-Islamic era, who would not be satisfied with killing only the killer of a nobleman, but would kill several people from the killer’s tribe.","The phrase “the lowest among them may grant protection” means that even the humblest Muslim, if he grants safety or protection, the rest may not violate it, whether that person is a slave, a woman, or otherwise.","And the phrase “the believers are united against others” means that the Muslims are brothers who support one another against disbelievers and idolaters."]}},"tuhfa":{},"refs":[{"key":"sh12520","label":"أبو يعلى","number":4757,"lafz":true},{"key":"rb280","label":"ابن أبي عاصم في الديات","number":107},{"key":"sh9771","label":"الدار قطني","number":131}],"full":1,"dr":1,"rep":[6080,6451]},{"num":6858,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنَّ رَجُلًا قَتَلَ عَبْدَهُ مُتَعَمِّدًا، فَجَلَدَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِائَةَ جَلْدَةٍ وَنَفَاهُ سَنَةً وَمَحَى سَهْمَهُ مِنَ الْمُسْلِمِينَ، وَلَمْ يُقِدْهُ بِهِ، وَأَمَرَهُ أَنْ يُعْتِقَ رَقَبَةً."],"takhrij":"حسن: رواه الدارقطني (3/143-144) وعنه البيهقي (8/36) والطحاوي في شرحه (3/137-138) كلهم من حديث محمد بن عبد العزيز الرملي، نا إسماعيل بن عياش، عن الأوزاعي، عن عمرو بن شعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب من قال : لا يقتل السيد بالعبد","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Daraqutni (3/143–144), and through him al-Bayhaqi (8/36), and al-Tahawi in his commentary (3/137–138).","chapter_en":"Those who said that the master is not killed for the slave","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["Amr ibn Shuayb narrated from his father, from his grandfather, that a man intentionally killed his slave. The Prophet ﷺ flogged him one hundred lashes, exiled him for one year, removed his share/allotment from among the Muslims, did not execute him in retaliation for the slave, and ordered him to free a slave."]}},"tuhfa":{},"refs":[{"key":"sh9771","label":"الدار قطني","number":144,"lafz":true},{"key":"kubrabayhaqi","label":"عنه البيهقي","number":36},{"key":"sh9771","label":"سنن الدارقطني","number":3282,"n":3296},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":15951,"n":16109}],"full":1,"dr":1},{"num":6859,"demo":false,"sanad":"","matn":["عن عبد الله بن عمرو قال: جاء رجل إلى النبي صلى الله عليه وسلم صارخاً. فقال له رسول الله صلى الله عليه وسلم: مالك؟ قال: سيدي رآني أقبّل جارية له، فجبّ مذاكيري، فقال النبي صلى الله عليه وسلم: علي بالرجل فطلب، فلم يقدر عليه. فقال رسول الله صلى الله عليه وسلم: اذهب فأنت حر قال: على من نُصرتي يا رسول الله! قال: يقول: أرأيت إن استرقني مولاي؟ فقال رسول الله صلى الله عليه وسلم: على كل مؤمن أو مسلم."],"takhrij":"حسن: رواه أبو داود (4519) وابن ماجة (2680) وأحمد (6710) والبيهقي (8/36) وعبد الرزاق (17932) كلهم من حديث عمرو بن شعيب، عن أبيه، عن جده فذكره وإسناده حسن من أجله.","grade":"حسن","chapter_ar":"باب من قال : لا يقتل السيد بالعبد","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4519), Ibn Majah (2680), Ahmad (6710), and Abd al-Razzaq (17932).","chapter_en":"Those who said that the master is not killed for the slave","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["Abdullah ibn Amr said: A man came to the Prophet ﷺ crying out. The Messenger of Allah ﷺ said to him, “What is wrong with you?” He said: My master saw me kissing a slave girl of his, so he cut off my private parts. The Prophet ﷺ said: “Bring me the man.” He was sought, but they could not catch him. So the Messenger of Allah ﷺ said: “Go, you are free.” The man said: Who will support me, O Messenger of Allah ﷺ? He meant: What if my master enslaves me again? The Messenger of Allah ﷺ said: “That is upon every believer,” or he said, “upon every Muslim.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"ابو داود","number":4519,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2680},{"key":"ahmad","label":"احمد","number":6710},{"key":"abdrazzaq","label":"عبد الرزاق","number":17932}],"full":1,"dr":1},{"num":6860,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ، قَالَ: نَحَلَتْ لِرَجُلٍ مِنْ بَنِي مُدْلِجٍ جَارِيَةٌ فَأَصَابَ مِنْهَا ابْنَا، فَكَانَ يَسْتَخْدِمُهَا، فَلَمَّا شَبَّ الْغُلَامُ دَعَاهَا يَوْمًا فَقَالَ: اصْنَعِي كَذَا وَكَذَا، فَقَالَ: لَا تَأْتِيكَ، حَتَّى مَتَى تَسْتَأْمِي أُمِّي؟ قَالَ: فَغَضِبَ فَحَذَفَهُ بِسَيْفِهِ فَأَصَابَ رِجْلَهُ فَنَزَفَ الْغُلَامُ فَمَاتَ، فَانْطَلَقَ فِي رَهْطٍ مِنْ قَوْمِهِ إِلَى عُمَرَ رَضِيَ اللَّهُ عَنْهُ، فَقَالَ: يَا عَدُوَّ نَفْسِهِ أَنْتَ الَّذِي قَتَلْتَ ابْنَكَ، لَوْلَا أَنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا يُقَادُ الْأَبُ مِنِ ابْنِهِ لَقَتَلْتُكَ، هَلُمَّ دِيَتَهُ. قَالَ: فَأَتَاهُ بِعِشْرِينَ أَوْ ثَلَاثِينَ وَمِائَةِ بَعِيرٍ. قَالَ: فَخِيرَ مِنْهَا مِائَةٌ فَدَفَعَهَا إِلَى وَرَثَتِهِ، وَتَرَكَ أَبَاهُ."],"takhrij":"حسن: رواه البيهقي (8/38) وابن الجارود (788) والدارقطني (3/140) كلهم من حديث محمد بن مسلم بن وارة، نا محمد بن سعيد بن سابق، نا عمرو بن أبي قيس، عن منصور، عن محمد بن عجلان، عن عمرو بن شعيب بإسناده.","grade":"حسن","chapter_ar":"باب لا يقاد الأب من ابنه","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bayhaqi (8/38), Ibn al-Jarud (788), and al-Daraqutni (3/140). This wording is from al-Bayhaqi and Ibn al-Jarud.","chapter_en":"A father is not subject to retaliation for killing his son","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["Amr ibn Shuayb narrated from his father, from Abdullah ibn Amr ibn al-As, who said: A man from Banu Mudlij was given a slave-woman as a gift, and he had a son from her. He used to make her serve him. When the boy grew up, he called her one day and said, “Do such-and-such.” The boy said, “She will not come to you. How long will you keep using my mother as a servant?” The man became angry and threw a sword at him, striking his leg. The boy bled until he died. Then the man went with a group from his people to Umar. Umar said, “Enemy of himself, you are the one who killed your own son. Had I not heard the Messenger of Allah ﷺ say, ‘A father is not executed in retaliation for his son,’ I would have killed you. Bring his blood-money.” So he brought one hundred and twenty or one hundred and thirty camels. Umar selected one hundred from them and gave them to the heirs, excluding the father."]}},"tuhfa":{},"refs":[{"key":"kubrabayhaqi","label":"البيهقي","number":38,"lafz":true},{"key":"sh13071","label":"ابن الجارود","number":788,"n":820},{"key":"sh9771","label":"الدار قطني","number":140},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":15964,"n":16122}],"full":1,"dr":1},{"num":6861,"demo":false,"sanad":"","matn":["عن ابن عباس يقول: كان في بني إسرائيل القصاص، ولم تكن فيهم الدية. فقال الله تعالى لهذه الأمة: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الْقِصَاصُ فِي الْقَتْلَى الْحُرُّ بِالْحُرِّ وَالْعَبْدُ بِالْعَبْدِ وَالْأُنْثَى بِالْأُنْثَى فَمَنْ عُفِيَ لَهُ مِنْ أَخِيهِ شَيْءٌ﴾ [البقرة:١٧٨ ] فالعفو أن يقبل الدية في العمد. ﴿فَاتِّبَاعٌ بِالْمَعْرُوفِ وَأَدَاءٌ إِلَيْهِ بِإِحْسَانٍ﴾ [البقرة: ١٧٨] يتبع المعروف ويؤدى بإحسان ذَلِكَ تَخْفِيفٌ مِنْ رَبِّكُمْ وَرَحْمَةٌ مما كتب على من كان قبلكم ﴿فَمَنِ اعْتَدَى بَعْدَ ذَلِكَ فَلَهُ عَذَابٌ أَلِيمٌ﴾ [البقرة: ١٧٨ ] أي قتل بعد قبول الدية."],"takhrij":"صحيح: رواه البخاري في التفسير (4498) عن الحميدي، حدثنا سفيان، حدثنا عمرو قال: سمعت مجاهداً قال: سمعت ابن عباس يقول: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الدية","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (4498).","chapter_en":"What has come regarding blood-money","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Ibn Abbas said: Among the Children of Israel there was retaliation, but there was no blood-money among them. Then Allah said to this nation: “O you who believe, retaliation is prescribed for you in cases of murder…” up to His saying: “whoever is pardoned anything by his brother…” [al-Baqarah: 178]. The pardon means that blood-money may be accepted in a case of intentional killing. “Then there should be a fair follow-up and payment to him with excellence” means that the claim should be pursued in a fair manner and the payment made properly. “That is a lightening from your Lord and a mercy” means in comparison to what was prescribed on those before you. “So whoever transgresses after that, for him is a painful punishment” [al-Baqarah: 178], meaning whoever kills after accepting the blood-money."]},"intro":{"ar":["قال تمالى: ( يَأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيْكُمْ ٱلْقِصَاصُ فِى الْقَتْلَ الحُرِّبِٱلْحَرِ وَٱلْعَبْدُ بِٱلْعَبْدِ وَالأُنَ","بِٱلْأُنتَى فَمَنْ عُفِى لَهُ من أَخِيهِ شَي تبَاع بِلْمَعْرُونِ وَاء لَيْهِ بإحسَن) [البقرة: ١٧٨ ]"],"en":["Allah Most High said: “O you who believe, retaliation is prescribed for you in cases of murder: the free for the free, the slave for the slave, and the female for the female. But whoever is pardoned anything by his brother, then there should be a fair follow-up and payment to him with excellence.” [al-Baqarah: 178]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري في التفسير","number":4498,"lafz":true}],"full":1},{"num":6862,"demo":false,"sanad":"","matn":["عن أَبِي جُحَيْفَةَ قَالَ: سَأَلْتُ عَلِيًّا رَضِيَ اللَّهُ عَنْهُ هَلْ عِنْدَكُمْ شَىْءٌ مَا لَيْسَ فِي الْقُرْآنِ وَقَالَ مَرَّةً مَا لَيْسَ عِنْدَ النَّاسِ فَقَالَ وَالَّذِي فَلَقَ الْحَبَّ وَبَرَأَ النَّسَمَةَ مَا عِنْدَنَا إِلاَّ مَا فِي الْقُرْآنِ، إِلاَّ فَهْمًا يُعْطَى رَجُلٌ فِي كِتَابِهِ، وَمَا فِي الصَّحِيفَةِ. قُلْتُ وَمَا فِي الصَّحِيفَةِ قَالَ الْعَقْلُ، وَفِكَاكُ الأَسِيرِ، وَأَنْ لاَ يُقْتَلَ مُسْلِمٌ بِكَافِرٍ."],"takhrij":"صحيح: رواه البخاري في الديات (6903) عن صدقة بن الفضل، أخبرنا ابن عيينة، حدّثنا مطرّف، قال: سمعت الشعبي قال: سمعت أبا جحيفة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الدية","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (6903).","chapter_en":"What has come regarding blood-money","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Abu Juhayfah said: I asked Ali, may Allah be pleased with him, “Do you have anything that is not in the Qur’an?” In another wording: “Anything the people do not have?” He replied, “By the One who splits the grain and creates the soul, we have nothing except what is in the Qur’an, except an understanding that a man may be given regarding His Book, and what is in the written sheet.” I said, “What is in the sheet?” He said: “The blood-money, the ransom of captives, and that a Muslim is not to be killed for a disbeliever.”"]},"buhuth":{"en":["The word al-aql here means blood-money. It was called that because camels used to be tied at the courtyard of the slain person’s guardian as payment, and then the term came to be used for blood-money in general, even if it was not paid in camels."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6903,"lafz":true}],"full":1,"dr":1},{"num":6863,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: لما فتح الله على رسوله مكة قام في الناس، فحمد الله وأثنى عليه ثم قال: .... ومن قتل له قتيل فهو بخير النظرين: إما أن يُفدى وإما أن يُقيد."],"takhrij":"متفق عليه: رواه البخاري في اللقطة (2434)، ومسلم في الحج (1355) كلاهما من حديث الوليد بن مسلم، حدثنا الأوزاعي، حدثني يحيى بن أبي كثير، حدثني أبو سلمة، حدثني أبو هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب ولي العمد مخير بين التل أو العفأ لدية","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2434) and Muslim (1355).","chapter_en":"The guardian in an intentional killing has the choice between retaliation or pardoning in exchange for blood-money","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah said: When Allah granted His Messenger the conquest of Makkah, he stood among the people, praised Allah, and extolled Him, then said: “Whoever has had a relative killed has the better of two choices: either he may accept compensation, or he may demand retaliation.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري في اللقطه","number":2434,"lafz":true},{"key":"muslim","label":"مسلم في الحج","number":1355}],"full":1},{"num":6864,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ قَتَلَ عَمْدًا دُفِعَ إِلَى أَوْلِيَاءِ الْقَتِيلِ فَإِنْ شَاءُوا قَتَلُوا وَإِنْ شَاءُوا أَخَذُوا الدِّيَةَ وَذَلِكَ ثَلاَثُونَ حِقَّةً وَثَلاَثُونَ جَذَعَةً وَأَرْبَعُونَ خَلِفَةً وَذَلِكَ عَقْلُ الْعَمْدِ مَا صُولِحُوا عَلَيْهِ فَهُوَ لَهُمْ وَذَلِكَ تَشْدِيدُ الْعَقْلِ."],"takhrij":"حسن: رواه الترمذي (1387) وابن ماجة (2626) وأبو داود (4506) مختصراً كلهم من حديث محمد بن راشد، قال: أخبرنا سليمان بن موسى، عن عمرو بن شعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب ولي العمد مخير بين التل أو العفأ لدية","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Tirmidhi (1387), Ibn Majah (2626), and Abu Dawud (4506). Al-Tirmidhi said: “Sound and singular.”","chapter_en":"The guardian in an intentional killing has the choice between retaliation or pardoning in exchange for blood-money","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Amr ibn Shuayb narrated from his father, from his grandfather, that the Messenger of Allah ﷺ said: “Whoever is killed intentionally, his killer is handed over to the heirs of the slain. If they wish, they may kill him, and if they wish, they may take the blood-money. That blood-money is thirty hiqqahs, thirty jadhaʿahs, and forty pregnant she-camels. That is the blood-money for intentional killing. Whatever amount they agree upon in settlement belongs to them, and that is the stricter blood-money.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1387,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2626},{"key":"abudawud","label":"أبو داود","number":4506}],"full":1,"dr":1},{"num":6865,"demo":false,"sanad":"","matn":["عَنْ أَبِي شُرَيْحٍ الكعبي يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَلاَ إِنَّكُمْ مَعْشَرَ خُزَاعَةَ قَتَلْتُمْ هَذَا الْقَتِيلَ مِنْ هُذَيْلٍ، وَإِنِّي عَاقِلُهُ. فَمَنْ قُتِلَ لَهُ بَعْدَ مَقَالَتِي هَذِهِ قَتِيلٌ فَأَهْلُهُ بَيْنَ خيرين. أَنْ يَأْخُذُوا الْعَقْلَ، أَوْ يقتلوه."],"takhrij":"صحيح: رواه أبو داود (4504) والترمذي (1439) وأحمد (27160) والدارقطني (3/95-96) كلهم من حديث يحيى بن سعيد، قال: حدثنا ابن أبي ذئب قال: حدثنا سعيد المقبري، قال: سمعت أبا شريح الكعبي فذكره.","grade":"صحيح","chapter_ar":"باب ولي العمد مخير بين التل أو العفأ لدية","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4504), al-Tirmidhi (1439), Ahmad (27160), and al-Daraqutni (3/95–96). Al-Tirmidhi said: “This is a sound authentic hadith.”","chapter_en":"The guardian in an intentional killing has the choice between retaliation or pardoning in exchange for blood-money","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Abu Shurayh al-Kaʿbi said: The Messenger of Allah ﷺ said: “O people of Khuzaʿah, you have killed this man in return for one slain from Hudhayl, and I will pay his blood-money. So whoever has someone killed after this statement of mine, his family has two choices: either they take the blood-money or they kill the killer.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4504,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1439},{"key":"sh9771","label":"الدار قطني","number":96},{"key":"ahmad","label":"مسند الإمام أحمد","number":27160,"n":27160}],"full":1,"dr":1},{"num":6866,"demo":false,"sanad":"","matn":["عن أبي شُريح الخزاعي قال: لما بعث عمرو بن سعيد إلى مكة، بعثه يغزو ابن الزبير، أتاه أبو شريـح فكلمه، وأخبره بما سمـع رسول الله صلى الله عليه وسلم فمما قال: يا معشر خزاعة ارفعوا أيديكم عن القتل، فقد كثر أن يقع، لئن قتلتم قتيلاً لأدينّه. فمن قتل بعد مقامي هذا فأهله بخير النظرين: إن شاؤوا فدم قاتله، وإن شاؤوا فعقله."],"takhrij":"حسن: رواه الإمام أحمد (16377) عن يعقوب، حدثنا أبي، عن محمد بن إسحاق، قال: حدثني سعيد بن أبي سعيد المقبري، عن أبي شريح الخزاعي فذكره في خطبة يوم الفتح الطويلة.","grade":"حسن","chapter_ar":"باب ولي العمد مخير بين التل أو العفأ لدية","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (16377).","chapter_en":"The guardian in an intentional killing has the choice between retaliation or pardoning in exchange for blood-money","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Abu Shurayh al-Khuzaʿi said: When Amr ibn Saʿid sent forces to Makkah against Ibn al-Zubayr, Abu Shurayh came to him, spoke to him, and informed him of what he had heard from the Messenger of Allah ﷺ. Among what he said was: “O people of Khuzaʿah, keep your hands back from killing, for killing has become excessive. If you kill someone, I will indeed pay his blood-money. Whoever is killed after this statement of mine, then his family has the better of two choices: if they wish, they may take the blood of his killer, and if they wish, they may take his blood-money.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":16377,"n":16377,"lafz":true}],"full":1,"dr":1},{"num":6867,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، رَفَعَهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ قَتَلَ فِي عِمِّيَّةٍ أَوْ عَصَبِيَّةٍ بِحَجَرٍ أَوْ سَوْطٍ أَوْ عَصًا فَعَلَيْهِ عَقْلُ الْخَطَإِ وَمَنْ قَتَلَ عَمْدًا فَهُوَ قَوَدٌ وَمَنْ حَالَ بَيْنَهُ وَبَيْنَهُ فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلاَئِكَةِ وَالنَّاسِ أَجْمَعِينَ لاَ يُقْبَلُ مِنْهُ صَرْفٌ وَلاَ عَدْلٌ.","وفي رواية: من قتل عمداً فقود يده."],"takhrij":"حسن: رُوي موصولا ومرسلا.","grade":"حسن","chapter_ar":"باب ولي العمد مخير بين التل أو العفأ لدية","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4540), al-Nasa’i (4789), Ibn Majah (2635), and al-Tahawi in Mushkil al-Athar (4900).","chapter_en":"The guardian in an intentional killing has the choice between retaliation or pardoning in exchange for blood-money","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Ibn Abbas reported that the Prophet ﷺ said: “Whoever is killed in blind fighting or tribal partisanship by a stone, a whip, or a stick, then the blood-money of accidental killing is due. Whoever is killed intentionally, then retaliation applies. And whoever comes between the killer and that retaliation, upon him is the curse of Allah, the angels, and all people; neither obligatory nor voluntary deeds will be accepted from him.” In another narration: “Whoever kills intentionally, then his hand is liable to retaliation.”"]},"buhuth":{"en":["The meaning of the phrase “whoever kills intentionally, then retaliation applies” is that retaliation is the original ruling. But if the heirs of the slain person waive retaliation, they may do so, either by pardoning or by accepting blood-money, so there is no contradiction between retaliation and accepting compensation.","The phrase “no sarf will be accepted from him” means no repentance, and “nor ʿadl” means no ransom."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4540,"lafz":true},{"key":"nasai","label":"النسائي","number":4789},{"key":"ibnmajah","label":"ابن ماجه","number":2635}],"full":1,"dr":1},{"num":6868,"demo":false,"sanad":"","matn":["عَنْ جابر بْنِ عبدالله يَقُولُ: كَتَبَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى كُلِّ بَطْنٍ عُقُولَهُ."],"takhrij":"صحيح: رواه مسلم في العتق (1507) عن محمد بن رافع، ثنا عبدالرزاق، أخبرنا ابن جريج، أخبرني أبو الزبير، أنه سمع جابر بن عبدالله يقول: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء من الديات على البطون","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1507).","chapter_en":"Reports regarding blood-money upon the clans","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported: The Prophet ﷺ assigned the blood-money obligations to each clan."]},"buhuth":{"en":["The word al-ʿuqūl means blood-money payments; its singular is ʿaql.","The meaning is that the blood-money for accidental killing and quasi-intentional killing is borne by the ʿāqilah, meaning the agnatic relatives, including fathers and sons, whether ascending or descending.","A baṭn is a subdivision below the tribe, and a fakhdh is a subdivision below the baṭn."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1507,"lafz":true}],"full":1,"dr":1},{"num":6869,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ امْرَأَتَيْنِ، مِنْ هُذَيْلٍ رَمَتْ إِحْدَاهُمَا الأُخْرَى، فَطَرَحَتْ جَنِينَهَا، فَقَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهَا بِغُرَّةٍ عَبْدٍ أَوْ أَمَةٍ."],"takhrij":"متفق عليه: رواه مالك في العقول (5) عن ابن شهاب، عن أبي سلمة بن عبد الرحمن بن عوف، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب دية الجنين","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (5), al-Bukhari (6904), and Muslim (1681).","chapter_en":"The blood-money for a fetus","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah reported that two women from Hudhayl fought, and one of them threw something at the other, causing her to miscarry her fetus. The Messenger of Allah ﷺ ruled that compensation for it was a male slave or a female slave."]},"buhuth":{"en":["The original meaning of ghurrah is whiteness in the face, but it came to refer to the whole person, just as “neck” is used to mean a slave."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":5,"lafz":true},{"key":"bukhari","label":"البخاري","number":6904},{"key":"muslim","label":"مسلم","number":1681}],"full":1,"dr":1},{"num":6870,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: اقْتَتَلَتِ امْرَأَتَانِ مِنْ هُذَيْلٍ، فَرَمَتْ إِحْدَاهُمَا الأُخْرَى بِحَجَرٍ فَقَتَلَتْهَا وَمَا فِي بَطْنِهَا، فَاخْتَصَمُوا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ دِيَةَ جَنِينِهَا غُرَّةٌ عبدٍ أَوْ وَلِيدَةٌ، وَقَضَى بِدِيَةِ الْمَرْأَةِ عَلَى عَاقِلَتِهَا، وَوَرَّثَهَا وَلَدَهَا وَمَنْ مَعَهُمْ. فَقَالَ حَمَلُ بْنُ النَّابِغَةِ الْهُذَلِيُّ: يَا رَسُولَ اللَّهِ، كَيْفَ أَغْرَمُ مَنْ لاَ شَرِبَ وَلاَ أَكَلَ، وَلاَ نَطَقَ وَلاَ اسْتَهَلَّ؟ فَمِثْلُ ذَلِكَ يُطلّ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنَّمَا هَذَا مِنْ إِخْوَانِ الْكُهَّانِ مِنْ أَجْلِ سَجْعِهِ الَّذِي سَجَعَ."],"takhrij":"متفق عليه: رواه البخاري في الديات (6910) ومسلم في القسامة (36:1681) كلاهما من طريق ابن وهب، أخبرني يونس، عن ابن شهاب، عن ابن المسيب وأبي سلمة بن عبد الرحمن، أن أبا هريرة رضي الله عنه قال فذكره، واللفظ لمسلم. وليس عند البخاري قال حمل بن النابغة ولا قوله: وورّثها ولدها ومن معهم","grade":"متفق عليه","chapter_ar":"باب دية الجنين","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6910) and Muslim (1681/36). This is Muslim’s wording.","chapter_en":"The blood-money for a fetus","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah reported: Two women from Hudhayl fought, and one of them threw a stone at the other, killing her and the fetus in her womb. Their dispute was brought before the Messenger of Allah ﷺ. The Messenger of Allah ﷺ ruled that the compensation for the fetus was a ghurrah—a male or female slave. He ruled that the blood-money for the woman was to be paid by the killer’s ʿāqilah, and he assigned her inheritance to her children and the other heirs with them. Ḥamal ibn al-Nābighah al-Hudhalī said: “O Messenger of Allah ﷺ, how can I be made to pay compensation for one who neither drank nor ate, neither spoke nor cried at birth? Such a case should be disregarded.” The Messenger of Allah ﷺ said: “This man is only one of the brothers of the soothsayers,” because of the rhyming manner in which he spoke."]},"buhuth":{"en":["The expression “upon her ʿāqilah” refers to the paternal relatives who form the agnatic kin. This indicates that the child is not part of the ʿāqilah, and that the ʿāqilah inherits only what remains after the fixed-share heirs.","The word “yuṭall” means that it would be left without compensation.","It also shows that the blood-money for quasi-intentional killing is borne by the ʿāqilah, whereas the blood-money for intentional killing is borne by the offender from his own wealth."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6910,"lafz":true},{"key":"muslim","label":"مسلم","number":1681,"n":4391},{"key":"muslim","label":"مسلم في القسامه","number":36}],"full":1,"dr":1},{"num":6871,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ، عَنْ عُمَرَ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ اسْتَشَارَهُمْ فِي إِمْلاَصِ الْمَرْأَةِ فَقَالَ الْمُغِيرَةُ قَضَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْغُرَّةِ عَبْدٍ أَوْ أَمَةٍ. فَقَالَ ائْتِ مَنْ يَشْهَدُ مَعَكَ، فَشَهِدَ مُحَمَّدُ بْنُ مَسْلَمَةَ أَنَّهُ شَهِدَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى بِهِ."],"takhrij":"متفق عليه: رواه البخاري في الديات (6905-6908) عن موسى بن إسماعيل، حدثنا وُهيب، حدثنا هشام، عن أبيه، عن المغيرة بن شعبة، به، وعن عبيد الله بن موسى، عن هشام، عن أبيه، أن عمر نشد الناس ... الحديث.","grade":"متفق عليه","chapter_ar":"باب دية الجنين","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6905–6908) and Muslim (1689).","chapter_en":"The blood-money for a fetus","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah reported that ʿUmar may Allah be pleased with him consulted the people concerning the case of one woman causing another woman to miscarry. Al-Mughīrah said: “The Prophet ﷺ ruled that the compensation was a ghurrah: a male or female slave.” ʿUmar said: “Bring someone who can testify along with you.” Muḥammad ibn Maslamah then testified that he had witnessed the Prophet ﷺ give that ruling."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6905,"lafz":true},{"key":"muslim","label":"مسلم","number":1689}],"full":1,"dr":1},{"num":6872,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ، قَالَ ضَرَبَتِ امْرَأَةٌ ضَرَّتَهَا بِعَمُودِ فُسْطَاطٍ وَهِيَ حُبْلَى فَقَتَلَتْهَا - قَالَ - وَإِحْدَاهُمَا لِحْيَانِيَّةٌ - قَالَ - فَجَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دِيَةَ الْمَقْتُولَةِ عَلَى عَصَبَةِ الْقَاتِلَةِ وَغُرَّةً لِمَا فِي بَطْنِهَا. فَقَالَ رَجُلٌ مِنْ عَصَبَةِ الْقَاتِلَةِ أَنَغْرَمُ دِيَةَ مَنْ لاَ أَكَلَ وَلاَ شَرِبَ وَلاَ اسْتَهَلَّ فَمِثْلُ ذَلِكَ يُطَلُّ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَسَجْعٌ كَسَجْعِ الأَعْرَابِ. قَالَ وَجَعَلَ عَلَيْهِمُ الدِّيَةَ."],"takhrij":"صحيح: رواه مسلم في القسامة (37:1682) عن إسحاق بن إبراهيم الحنظلي، أخبرنا جرير، عن منصور، عن إبراهيم، عن عُبيد بن نضيلة الخزاعي، عن المغيرة بن شعبة، فذكره.","grade":"صحيح","chapter_ar":"باب دية الجنين","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1682, no. 37).","chapter_en":"The blood-money for a fetus","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Al-Mughirah ibn Shuʿbah said: A woman struck her co-wife with a tent pole while she was pregnant and killed her. One of the two women was from Lihyan. The Messenger of Allah ﷺ ruled that the blood-money of the slain woman was upon the killer’s agnate relatives, and that there was a ghurrah for what was in her womb. A man from the killer’s agnate relatives said: “Are we to pay compensation for one who neither ate nor drank nor cried at birth? Such a thing should be disregarded.” The Messenger of Allah ﷺ said: “Rhymed speech like the rhymed speech of the Bedouins?” Then he imposed the blood-money upon them."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":37,"lafz":true}],"full":1},{"num":6873,"demo":false,"sanad":"","matn":["عَنْ أُسَامَةَ بن عُمَيْرٍ الهذلي. وَكَانَ قَدْ صَحِبَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كَانَتْ فِينَا امْرَأَتَانِ، فَضَرَبَتْ إِحْدَاهُمَا الْأُخْرَى بِعَمُودٍ، فَقَتَلَتْهَا، وَقَتَلَتْ مَا فِيهِ بَطْنِهَا، فَقَضَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْمَرْأَةِ بالدية، وَقَضَى بدية الغرة لِزَوْجِهَا، وَقَضَى بِالْعَقْلِ عَلَى عَصَبَةِ الْقَاتِلَةِ، وَقَضَى فِي الْجَنِينِ بِغُرَّةِ عَبْدٍ، أَوْ أَمَةٍ."],"takhrij":"صحيح: رواه ابن أبي عاصم في الديات (171) والطحاوي في مشكله (4521) والطبراني في الكبير (1/160) وعنه الضياء في المختارة (1416) كلهم من طرق عن سفيان بن عيينة، عن أيوب السختياني، قال: سمعت أبا المليح الهذلي ابن أسامة، عن أبيه فذكره واللفظ لأبي عاصم مثله عند الطحاوي. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب دية الجنين","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Abi Asim in al-Diyat (171), al-Tahawi in Mushkil al-Athar (4521), and al-Tabarani in al-Kabir (1/160).","chapter_en":"The blood-money for a fetus","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Usamah ibn Umair al-Hudhali, who had accompanied the Prophet ﷺ, said: There were two women among us, and one of them struck the other with a pole and killed her and the child in her womb. The Prophet ﷺ ruled that the woman’s case required blood-money, that the compensation for the fetus was for her husband, that the blood-money was due upon the killer’s agnate relatives, and that the fetus required a ghurrah, either a male slave or a female slave."]}},"tuhfa":{},"refs":[{"key":"rb280","label":"ابن أبي عاصم في الديات","number":171,"lafz":true},{"key":"sh22547","label":"الطحاوي في مشكله","number":4521},{"key":"sh10480","label":"الضياء في المختاره","number":1416}],"full":1,"dr":1},{"num":6874,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ قَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَعْقِلَ الْمَرْأَةَ عَصَبَتُهَا مَنْ كَانُوا وَلاَ يَرِثُوا مِنْهَا شَيْئًا إِلاَّ مَا فَضَلَ عَنْ وَرَثَتِهَا وَإِنْ قُتِلَتْ فَعَقْلُهَا بَيْنَ وَرَثَتِهَا فَهُمْ يَقْتُلُونَ قَاتِلَهَا."],"takhrij":"حسن: رواه ابن ماجة (2647) عن إسحاق بن منصور، قال: أنبانا يزيد بن هارون، قال: أخبرنا محمد بن راشد، عن سليمان بن موسى، عن عمرو بن شعيب فذكره.","grade":"حسن","chapter_ar":"باب عقل المرأة على عصبتها، وميراثها لورثتها","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Majah (2647).","chapter_en":"A woman’s blood-money is borne by her agnate relatives, and her estate goes to her heirs","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Amr ibn Shuayb narrated from his father, from his grandfather, that the Messenger of Allah ﷺ ruled that a woman’s blood-money liability is borne by her agnate relatives, whoever they may be, and they inherit nothing from her except what remains after her heirs have received their shares. And if she is killed, then her blood-money goes among her heirs, and they are the ones entitled to retaliation against her killer."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2647,"lafz":true}],"full":1,"dr":1},{"num":6875,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُقَوِّمُ دِيَةَ الْخَطَإِ عَلَى أَهْلِ الْقُرَى أَرْبَعَمِائَةِ دِينَارٍ أَوْ عَدْلَهَا مِنَ الْوَرِقِ يُقَوِّمُهَا عَلَى أَثْمَانِ الإِبِلِ فَإِذَا غَلَتْ رَفَعَ فِي قِيمَتِهَا وَإِذَا هَاجَتْ رُخْصًا نَقَصَ مِنْ قِيمَتِهَا وَبَلَغَتْ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا بَيْنَ أَرْبَعِمِائَةِ دِينَارٍ إِلَى ثَمَانِمِائَةِ دِينَارٍ أَوْ عَدْلَهَا مِنَ الْوَرِقِ ثَمَانِيَةَ آلاَفِ دِرْهَمٍ وَقَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى أَهْلِ الْبَقَرِ مِائَتَىْ بَقَرَةٍ وَمَنْ كَانَ دِيَةُ عَقْلِهِ فِي الشَّاءِ فَأَلْفَىْ شَاةٍ.","قال: وقضى رسول الله صلى الله عليه وسلم أن العقل ميراث بين ورثة القتيل على قرابتهم، فما فضل فللعصبة.","قال: وقضى رسول الله صلى الله عليه وسلم في الأنف إذا جدع الدية كاملة، وإن جدعت ثندوته فنصف العقل: خمسون من الإبل أو عدلها من الذهب أو الورق، أو مئة بقرة أو ألف شاة.","وفي اليد إذا قطعت نصف العقل.","وفي الرجل نصف العقل.","وفي المأمومة ثلث العقل: ثلاث وثلاثون من الإبل وثلث، أو قيمتها من الذهب أو الورق أو البقر أو الشاء.","والجائفة مثل ذلك.","وفي الأصابع في كل إصبع عشر من الإبل.","وفي الأسنان في كل سن خمس من الإبل.","وقضى رسول الله صلى الله عليه وسلم أن عقل المرأة بين عصبتها من كانوا: لا يرثون منها شيئاً إلا ما فضل عن ورثتها، وإن قتلت فعقلها بين ورثتها، وهم يقتلون قاتلهم.","وقال رسول الله صلى الله عليه وسلم: ليس للقاتل شيء، وإن لم يكن له وارث فوارثه أقرب الناس إليه، ولا يرث القاتل شيئاً.","قال محمد: هذا كله حدثني به سليمان بن موسى، عن عمرو بن شعيب، عن أبيه، عن جده، عن النبي صلى الله عليه وسلم. قال أبو داود: محمد بن راشد من أهل دمشق هرب إلى البصرة من القتل."],"takhrij":"حسن: رواه أبو داود (4564) والبيهقي (6/220) كلاهما من حديث شيبان بن فروخ، ثنا محمد بن راشد، عن سليمان بن موسى، عن عمرو بن شعيب، عن أبيه، عن جده فذكره واللفظ لأبي داود.","grade":"حسن","chapter_ar":"باب ديات الأعضاء","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4564) and al-Bayhaqī (6/220). This is the wording of Abū Dāwūd.","chapter_en":"The blood-money for body parts","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb reported from his father, from his grandfather: The Messenger of Allah ﷺ used to assess the blood-money for accidental killing for the people of settled towns at four hundred dinars, or its equivalent in silver. He assessed it according to the market value of camels: when camels became expensive, he increased the amount, and when their prices fell, he reduced it. During the lifetime of the Messenger of Allah ﷺ, it ranged from four hundred dinars to eight hundred dinars, with its equivalent in silver being eight thousand dirhams. He ruled that for people whose wealth consisted of cattle, the blood-money was two hundred cows, and for those whose wealth consisted of sheep, two thousand sheep. He ruled that blood-money is inherited among the heirs of the slain person according to their degrees of kinship, and whatever remains goes to the agnatic relatives. He ruled that if the nose is completely cut off, the full blood-money is due. If only the soft end of the nose is severed, half the blood-money is due: fifty camels, or their equivalent in gold or silver, or one hundred cows, or one thousand sheep. For a severed hand, half the blood-money is due. For one leg, half the blood-money is due. For a head wound reaching the membrane surrounding the brain, one-third of the blood-money is due: thirty-three and one-third camels, or their equivalent in gold, silver, cattle, or sheep. A penetrating wound into the body cavity carries the same amount. For each finger, ten camels are due, and for each tooth, five camels. The Messenger of Allah ﷺ also ruled that a woman’s blood-money liability is borne by her agnatic relatives, whoever they may be. They do not inherit from her except what remains after her heirs have received their shares. If she is killed, her blood-money belongs to her heirs, and they have the right of retaliation against her killer.","The Messenger of Allah ﷺ also said: “The killer receives nothing. If the deceased has no heir, then his heir is the closest person to him, and the killer inherits nothing.” Muḥammad said: “Sulaimān ibn Mūsā narrated all of this to me from ʿAmr ibn Shuʿayb, from his father, from his grandfather, from the Prophet ﷺ.” Abū Dāwūd said: “Muḥammad ibn Rāshid was from the people of Damascus and fled to Baṣrah because of a killing.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4564,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":6}],"full":1,"dr":1},{"num":6876,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى فِي الْعَيْنِ الْعَوْرَاءِ السَّادَّةِ لِمَكَانِهَا إِذَا طُمِسَتْ بِثُلُثِ دِيَتِهَا وَفِي الْيَدِ الشَّلاَّءِ إِذَا قُطِعَتْ بِثُلُثِ دِيَتِهَا وَفِي السِّنِّ السَّوْدَاءِ إِذَا نُزِعَتْ بِثُلُثِ دِيَتِهَا."],"takhrij":"حسن: رواه النسائي (4840) وأبو داود (4567) كلاهما من حديث الهيثم بن حميد، حدثنا العلاء بن الحارث، حدثني عمرو بن شعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب دية العين العوراء، واليد الشلاء، والسن السوداء","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasai (4840) and Abu Dawud (4567).","chapter_en":"The blood-money for a blind eye, a paralyzed hand, and a blackened tooth","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":7,"content":{"translation":{"en":["Amr ibn Shuayb narrated from his father, from his grandfather, that the Messenger of Allah ﷺ ruled that for the blind eye which remains in place, if it is destroyed, one-third of its blood-money is due. For a paralyzed hand, if it is cut off, one-third of its blood-money is due. And for a blackened tooth, if it is removed, one-third of its blood-money is due."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4840,"lafz":true,"n":4840},{"key":"abudawud","label":"ابو داود","number":4567}],"full":1,"dr":1},{"num":6877,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ فِي الْمَوَاضِحِ خَمْسٌ."],"takhrij":"حسن: رواه أبو داود (4566) والترمذي (1390) والنسائي (4852) وابن ماجة (2655) والبيهقي (8/81) وابن الجارود (785) وأبو عاصم في الديات (157) كلهم من طريق حسين المعلم، عن عمرو بن شعيب به مثله.","grade":"حسن","chapter_ar":"باب ما جاء في الموضحة","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4566), al-Tirmidhi (1390), who graded it sound, al-Nasai (4852), and Ibn Majah (2655).","chapter_en":"What has come regarding the wound that exposes the bone","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Amr ibn Shuayb narrated from his father, from his grandfather, that the Prophet ﷺ said: “For the wound that exposes the bone, there are five.”"]},"buhuth":{"en":["That means five camels.","A muwaddihah is a head or facial wound that exposes the bone, meaning it makes it visible. It is usually found on the face or head."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4566,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1390},{"key":"nasai","label":"النسائي","number":4852,"n":4851},{"key":"ibnmajah","label":"ابن ماجه","number":2655},{"key":"sh13071","label":"ابن الجارود","number":785,"n":584}],"full":1,"dr":1},{"num":6878,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ هَذِهِ وَهَذِهِ سَوَاءٌ، يَعْنِي الْخِنْصَرَ وَالإِبْهَامَ."],"takhrij":"صحيح: رواه البخاري في الديات (6895) عن آدم، حدثنا شعبة، عن قتادة، عن عكرمة، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب دية الأصابع","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (6895). It was also narrated by Abu Dawud (4559) and Ibn al-Jarud (783), and in that wording it says: “The fingers are equal.”","chapter_en":"The blood-money for fingers","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["Ibn Abbas narrated from the Prophet ﷺ that he said: “This and this are equal,” meaning the little finger and the thumb are equal. “The teeth are equal as well; the front tooth and the molar are equal. This and this are equal.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري في الديات","number":6895,"lafz":true}],"full":1,"dr":1},{"num":6879,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دِيَةُ الأَصَابِعِ الْيَدَيْنِ وَالرِّجْلَيْنِ سَوَاءٌ عَشْرٌ مِنَ الإِبِلِ لِكُلِّ أُصْبُعٍ."],"takhrij":"صحيح: رواه الترمذي (1391) واللفظ له، وأبو داود (4561،4560) والنسائي (4849) وابن الجارود (780) كلهم من طريق عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب دية الأصابع","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Tirmidhi (1391), and this is his wording, as well as Abu Dawud (4560, 4561), al-Nasai (4849), and Ibn al-Jarud (780).","chapter_en":"The blood-money for fingers","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["Abdullah ibn Abbas said: The Messenger of Allah ﷺ said: “The blood-money for the fingers of the hands and feet is equal: ten camels for each finger.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1391,"lafz":true},{"key":"abudawud","label":"أبو داود","number":4560},{"key":"nasai","label":"النسائي","number":4849},{"key":"abudawud","label":"ابو داود","number":4561},{"key":"sh13071","label":"ابن الجارود","number":780,"n":812}],"full":1,"dr":1},{"num":6880,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ فِي خُطْبَتِهِ وَهُوَ مُسْنِدٌ ظَهْرَهُ إِلَى الْكَعْبَةِ فِي الأَصَابِعِ عَشْرٌ عَشْرٌ."],"takhrij":"حسن: رواه أبو داود (4562) وابن ماجة (2653) والنسائي (4850) وأحمد (7013) والدارقطني (3/210) كلهم من حديث عمرو بن شعيب، عن أبيه، عن جده قال: فذكره.","grade":"حسن","chapter_ar":"باب دية الأصابع","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4562), Ibn Majah (2653), al-Nasai (4850), Ahmad (7013), and al-Daraqutni (3/210).","chapter_en":"The blood-money for fingers","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["Amr ibn Shuayb narrated from his father, from his grandfather, that the Prophet ﷺ said in his sermon, while leaning his back against the Kaʿbah: “For the fingers, ten each.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4562,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2653,"n":2655},{"key":"nasai","label":"النسائي","number":4850,"n":4851},{"key":"ahmad","label":"مسند الإمام أحمد","number":7013,"n":6797}],"full":1,"dr":1},{"num":6881,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ الأَصَابِعُ سَوَاءٌ عَشْرٌ عَشْرٌ مِنَ الإِبِلِ."],"takhrij":"حسن: رواه أبو داود (4557) وأحمد (19550) والدارقطني (3/211) والبيهقي (8/92) والدارمي (2414) وصحّحه ابن حبان (6013) كلهم من حديث شعبة، عن غالب التمَّار، عن مسروق بن أوس، عن أبي موسى فذكره.","grade":"حسن","chapter_ar":"باب دية الأصابع","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4557), Ahmad (19550), al-Daraqutni (3/211), and al-Darimi (2414). It was authenticated by Ibn Hibban (6013).","chapter_en":"The blood-money for fingers","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["Abu Musa al-Ashari narrated from the Prophet ﷺ that he said: “The fingers are equal: ten camels for each one.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"ابو داود","number":4557,"lafz":true},{"key":"ahmad","label":"احمد","number":19550},{"key":"darimi","label":"الدارمي","number":2414,"n":2388},{"key":"ibnhibban","label":"ابن حبان","number":6013}],"full":1,"dr":1},{"num":6882,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الأَسْنَانُ سَوَاءٌ وَالأَصَابِعُ سَوَاءٌ."],"takhrij":"صحيح: رواه أبو داود (4560) وأحمد (2624) والبيهقي (8/90) كلهم من حديث علي بن الحسن بن شقيق، قال: أخبرنا أبو حمزة، قال: حدثنا يزيد النحوي، عن عكرمة، عن ابن عباس فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في دية الأسنان","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4560), Ahmad (2624), and al-Bayhaqi (8/90).","chapter_en":"What has come regarding the blood-money for teeth","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":10,"content":{"translation":{"en":["Ibn Abbas said: The Messenger of Allah ﷺ said: “The teeth are equal, and the fingers are equal.”"]},"buhuth":{"en":["Ibn Majah (2651) also narrated it with the wording: “The Prophet ﷺ ruled that for a tooth there are five camels.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"ابو داود","number":4560,"lafz":true},{"key":"ahmad","label":"احمد","number":2624}],"full":1,"dr":1},{"num":6883,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عمرو أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَطَبَ يَوْمَ فَتْحِ مَكَّةَ، فَكَبَّرَ ثَلاَثًا ثُمَّ قَالَ: لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ، صَدَقَ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الأَحْزَابَ وَحْدَهُ، أَلاَ إِنَّ كُلَّ مَأْثُرَةٍ كَانَتْ فِي الْجَاهِلِيَّةِ تُذْكَرُ وَتُدْعَى مِنْ دَمٍ، أَوْ مَالٍ تَحْتَ قدمَيَّ، إِلاَّ ماكان مِنْ سِقَايَةِ الْحَاجِّ، وَسِدَانَةِ الْبَيْتِ. ثُمَّ قَالَ: أَلاَ إِنَّ دِيَةَ الخطأ شِبْهِ الْعَمْدِ مَا كَانَ بِالسَّوْطِ وَالْعَصَا مِائَةٌ مِنَ الإِبِلِ: مِنْهَا أَرْبَعُونَ فِي بُطُونِهَا أَوْلاَدُهَا."],"takhrij":"حسن: رواه أبو داود (4547) وابن ماجة (2627) والدارقطني (3/104-105) وابن الجارود (773) وصحّحه ابن حبان (6011) كلهم من طرق عن خالد الحذاء، عن القاسم بن ربيعة، عن عقبة بن أوس، عن عبدالله بن عمرو فذكره.","grade":"حسن","chapter_ar":"باب السوط والعصا خطأ شبه العمد","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4547), Ibn Majah (2627), and Ibn al-Jarud (773), and authenticated by Ibn Hibban (6011).","chapter_en":"Killing with a whip or a stick is quasi-intentional mistaken killing","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":11,"content":{"translation":{"en":["Abdullah ibn Amr reported that the Messenger of Allah ﷺ delivered a sermon on the day of the conquest of Makkah. He said the takbir three times, then said: “There is no god but Allah alone. He fulfilled His promise, gave victory to His servant, and defeated the confederates alone. Indeed, every claim of distinction from the pre-Islamic period, whether in blood or wealth, is beneath my feet, except the giving of water to the pilgrims and the custodianship of the House.” Then he said: “Indeed, the blood-money for quasi-intentional mistaken killing, when done with a whip or a stick, is one hundred camels, forty of which are pregnant.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4547,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2627},{"key":"sh13071","label":"ابن الجارود","number":773},{"key":"ibnhibban","label":"ابن حبان","number":6011}],"full":1,"dr":1},{"num":6884,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى أَنَّ مَنْ قُتِلَ خَطَأً فَدِيَتُهُ مِائَةٌ مِنَ الإِبِلِ ثَلاَثُونَ بِنْتَ مَخَاضٍ وَثَلاَثُونَ بِنْتَ لَبُونٍ وَثَلاَثُونَ حِقَّةً وَعَشْرَةٌ بَنِي لَبُونٍ ذَكَرٍ."],"takhrij":"حسن: رواه أبو داود (4541) وابن ماجة (2630) والدارقطني (3/95) ومن طريقه البيهقي (8/74) كلهم من حديث يزيد بن هارون، حدثنا محمد بن راشد، عن سليمان بن موسى، عن عمرو بن شعيب، عن أبيه، عن جده فذكره واللفظ لأبي داود.","grade":"حسن","chapter_ar":"باب دية الخطأ","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4541), Ibn Majah (2630), and al-Daraqutni (3/95). This wording is from Abu Dawud.","chapter_en":"The blood-money for accidental killing","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":12,"content":{"translation":{"en":["Amr ibn Shuayb narrated from his father, from his grandfather, that the Messenger of Allah ﷺ ruled that whoever kills by mistake, his blood-money is one hundred camels: thirty bint makhad, thirty bint labun, thirty hiqqah, and ten male banu labun."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4541,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2630},{"key":"sh9771","label":"الدار قطني","number":95}],"full":1,"dr":1},{"num":6885,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ كَانَتْ قِيمَةُ الدِّيَةِ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَمَانَمِائَةِ دِينَارٍ أَوْ ثَمَانِيَةَ آلاَفِ دِرْهَمٍ وَدِيَةُ أَهْلِ الْكِتَابِ يَوْمَئِذٍ النِّصْفُ مِنْ دِيَةِ الْمُسْلِمِينَ قَالَ فَكَانَ ذَلِكَ كَذَلِكَ حَتَّى اسْتُخْلِفَ عُمَرُ رَحِمَهُ اللَّهُ فَقَامَ خَطِيبًا فَقَالَ أَلاَ إِنَّ الإِبِلَ قَدْ غَلَتْ. قَالَ فَفَرَضَهَا عُمَرُ عَلَى أَهْلِ الذَّهَبِ أَلْفَ دِينَارٍ وَعَلَى أَهْلِ الْوَرِقِ اثْنَىْ عَشَرَ أَلْفًا وَعَلَى أَهْلِ الْبَقَرِ مِائَتَىْ بَقَرَةٍ وَعَلَى أَهْلِ الشَّاءِ أَلْفَىْ شَاةٍ وَعَلَى أَهْلِ الْحُلَلِ مِائَتَىْ حُلَّةٍ. قَالَ وَتَرَكَ دِيَةَ أَهْلِ الذِّمَّةِ لَمْ يَرْفَعْهَا فِيمَا رَفَعَ مِنَ الدِّيَةِ."],"takhrij":"حسن: رواه أبو داود (4542) عن يحيى بن حكيم، حدثنا عبد الرحمن بن عثمان، حدثنا حسين المعلم، عن عمرو بن شعيب فذكره.","grade":"حسن","chapter_ar":"باب دية الخطأ","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4542).","chapter_en":"The blood-money for accidental killing","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":12,"content":{"translation":{"en":["Amr ibn Shuayb narrated from his father, from his grandfather, who said: The value of the blood-money during the time of the Messenger of Allah ﷺ was eight hundred dinars or eight thousand dirhams, and the blood-money of the People of the Book at that time was half that of the Muslims. This remained so until Umar became caliph. Then he stood and addressed the people, saying: “Indeed, camels have become expensive.” So Umar fixed it for the people of gold at one thousand dinars, for the people of silver at twelve thousand dirhams, for the people of cattle at two hundred cows, for the people of sheep at two thousand sheep, and for the people of garments at two hundred garments. He left the blood-money of the protected non-Muslims unchanged and did not raise it as he raised the blood-money."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"ابو داود","number":4542,"lafz":true}],"full":1,"dr":1},{"num":6886,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمُسْلِمُونَ تَتَكَافَأُ دِمَاؤُهُمْ يَسْعَى بِذِمَّتِهِمْ أَدْنَاهُمْ وَيُجِيرُ عَلَيْهِمْ أَقْصَاهُمْ وَهُمْ يَدٌ عَلَى مَنْ سِوَاهُمْ يَرُدُّ مُشِدُّهُمْ عَلَى مُضْعِفِهِمْ وَمُتَسَرِّعُهُمْ عَلَى قَاعِدِهِمْ لاَ يُقْتَلُ مُؤْمِنٌ بِكَافِرٍ وَلاَ ذُو عَهْدٍ فِي عَهْدِهِ.","وفي رواية: دية عقل الكافر نصف دية عقل المؤمن."],"takhrij":"حسن: رواه أبو داود (2751) واللفظ له والترمذي (1413) والنسائي (4806) وابن ماجة (2659) وأحمد (6692) وابن الجارود (1052) والبيهقي (8/29) والبغوي (2542) كلهم من طرق عن عمرو بن شعيب به مثله، وهو جزء من خطبة النبي صلى الله عليه وسلم عام الفتح ذكره أحمد وابن الجارود والبيهقي والبغوي مطولة، وستأتي كاملة في موضعه.","grade":"حسن","chapter_ar":"باب دية أهل الذمة","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (2751), al-Tirmidhi (1413), who graded it sound, and al-Nasai (4806). The second narration is in al-Tirmidhi.","chapter_en":"The blood-money of the protected non-Muslims","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":13,"content":{"translation":{"en":["Amr ibn Shuayb narrated from his father, from his grandfather, that the Messenger of Allah ﷺ said: “The blood of the Muslims is equal. The lowest among them may grant protection on behalf of them all, and the farthest among them may guarantee protection. They are united against others. Those with quick mounts should return to those with slow mounts, and those who go out with a detachment should return to those who remain stationed. A believer is not killed in retaliation for a disbeliever, nor one under covenant while he remains under his covenant.” In another narration: “The blood-money of a disbeliever is half the blood-money of a believer.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2751,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1413},{"key":"nasai","label":"النسائي","number":4806},{"key":"ibnmajah","label":"ابن ماجه","number":2659},{"key":"ahmad","label":"احمد","number":6692},{"key":"sh13071","label":"ابن الجارود","number":1052,"n":1112}],"full":1,"dr":1},{"num":6887,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ أَبَا جَهْمِ بْنَ حُذَيْفَةَ مُصَدِّقًا، فلاجَّه رَجُلٌ فِي صَدَقَتِهِ، فَضَرَبَهُ أَبُو جَهْمٍ، فشجَّه، فَأَتَوُا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: الْقَوَدَ يَا رَسُولَ اللَّهِ! فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : لَكُمْ كَذَا وَكَذَا فَلَمْ يَرْضَوْا، فَقَالَ: لَكُمْ كَذَا وَكَذَا فَرَضُوا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنِّي خَاطِبٌ الْعَشِيَّةَ عَلَى النَّاسِ وَمُخْبِرُهُمْ بِرِضَاكُمْ؟ قَالُوا: نَعَمْ. فَخَطَبَ النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ هَؤُلاَءِ اللَّيْثِيِّينَ أَتَوْنِي يُرِيدُونَ الْقَوَدَ، فَعَرَضْتُ عَلَيْهِمْ كَذَا وَكَذَا فَرَضُوا، أَرَضِيتُمْ؟ قَالُوا: لاَ. فَهَمَّ بِهِمْ الْمُهَاجِرُونَ، فَأَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَكُفُّوا عَنْهُمْ، فَكَفُّوا، ثُمَّ دَعَاهُمْ فَزَادَهُمْ، فَقَالَ: أَرَضِيتُمْ؟ قَالُوا: نَعَمْ، قَالَ: إِنِّي خَاطِبٌ عَلَى النَّاسِ وَمُخْبِرُهُمْ بِرِضَاكُمْ قَالُوا: نَعَمْ، فَخَطَبَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَرَضِيتُمْ؟ قَالُوا: نَعَمْ."],"takhrij":"صحيح: رواه أبو داود (4534) والنسائي (4778) وابن ماجة (2638) وابن أبي عاصم في الديات (247) وصحّحه ابن حبان (4487) كلهم من حديث عبد الرزاق – وهو في مصنفه (18032)- عن معمر، عن الزهري، عن عروة، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب حثِّ الإمام على قبول الدية","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4534), al-Nasai (4778), Ibn Majah (2638), and authenticated by Ibn Hibban (4487).","chapter_en":"The ruler’s encouragement to accept blood-money","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":14,"content":{"translation":{"en":["ʿA’ishah reported that the Messenger of Allah ﷺ sent Abu Jahm ibn Hudhayfah as a collector. A man disputed with him over his due, so Abu Jahm struck him and wounded his head. They came to the Prophet ﷺ and said: “Retaliation, O Messenger of Allah ﷺ.” The Prophet ﷺ said: “You will have such-and-such,” but they were not satisfied. Then he said: “You will have such-and-such,” and they were satisfied. Then the Prophet ﷺ said: “I will address the people this evening and inform them of your acceptance. Is that agreeable to you?” They said: “Yes.” So the Prophet ﷺ addressed the people and said: “These people from Layth came to me wanting retaliation, and I offered them such-and-such and they accepted. Are you satisfied?” They said: “No.” The Emigrants moved toward them, but the Prophet ﷺ ordered them to leave them alone, so they stopped. Then he called them again and increased the offer to them, and said: “Are you satisfied?” They said: “Yes.” He said: “I will address the people and inform them of your acceptance.” They said: “Yes.” So he addressed the people and said: “Are you satisfied?” They said: “Yes.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4534,"lafz":true},{"key":"nasai","label":"النسائي","number":4778,"n":4778},{"key":"ibnmajah","label":"ابن ماجه","number":2638},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":4487},{"key":"abdrazzaq","label":"عبد الرزاق – وهو في مصنفه","number":18032}],"full":1,"dr":1},{"num":6888,"demo":false,"sanad":"","matn":["عَنْ أَبِي رِمْثة قَالَ: انْطَلَقْتُ مَعَ أَبِي نَحْوَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لأَبِي: ابْنُكَ هَذَا؟ قَالَ: إِي وَرَبِّ الْكَعْبَةِ قَالَ: حَقًّا قَالَ: أَشْهَدُ بِهِ، قَالَ: فَتَبَسَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ضَاحِكًا مِنْ ثبْت شَبَهِي فِي أَبِي. وَمِنْ حَلْفِ أَبِي عليّ. ثُمَّ قَالَ: أَمَا إِنَّهُ لاَ يَجْنِي عَلَيْكَ، لاَ تَجْنِي عَلَيْهِ وَقَرَأَ: وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [فاطر: ١٨ ]"],"takhrij":"صحيح: رواه أبو داود (4495) والنسائي (1572) والترمذي (2812) وأحمد (7109) وصحّحه ابن حبان (5995) والحاكم (2/425) كلهم من حديث عبيد الله بن إياد بن لقيط، قال: حدثنا إياد بن لقيط، عن أبي رمْثة فذكره. واللفظ لأبي داود، وقد اختصره البعض، ورواه البعض مطولاً. انظر كتاب اللباس – باب في الخضاب.","grade":"صحيح","chapter_ar":"باب لا يؤخذ أحدّ من جناية أحد ولوكان من أبيه أو أخيه","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4495), al-Nasai (1572), al-Tirmidhi (2812), and Ahmad (7109). This wording is from Abu Dawud.","chapter_en":"No one is taken for the crime of another, even if it is his father or brother","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Abu Rimthah said: I went with my father to the Prophet ﷺ. The Messenger of Allah ﷺ said to my father: “Is this your son?” He said: “Yes, by the Lord of the Kaʿbah.” He said: “Truly?” He said: “I bear witness to it.” The Messenger of Allah ﷺ smiled, laughing at my resemblance to my father and at my father’s oath concerning me. Then he said: “Indeed, he does not bear your crime, nor do you bear his crime.” Then he recited: “No bearer of burdens shall bear the burden of another.” [Fatir: 18]"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"ابو داود","number":4495,"lafz":true},{"key":"nasai","label":"النسائي","number":1572},{"key":"tirmidhi","label":"الترمذي","number":2812},{"key":"ahmad","label":"احمد","number":7109},{"key":"ibnhibban","label":"ابن حبان","number":5995}],"full":1,"dr":1},{"num":6889,"demo":false,"sanad":"","matn":["عَنِ الْخَشْخَاشِ الْعَنْبَرِيِّ، قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَعِي ابْنٌ لِي، قَالَ: فَقَالَ: ابْنُكَ هَذَا؟ قَالَ: قُلْتُ: نَعَمْ. قَالَ: لَا يَجْنِي عَلَيْكَ، وَلَا تَجْنِي عَلَيْهِ."],"takhrij":"صحيح: رواه ابن ماجة (2671) وأحمد (19031) كلاهما من طريق هشيم بن بشير، أخبرنا يونس بن عبيد، عن حصين بن أبي الحر، عن الخشخاش فذكره.","grade":"صحيح","chapter_ar":"باب لا يؤخذ أحدّ من جناية أحد ولوكان من أبيه أو أخيه","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Majah (2671) and Ahmad (19031).","chapter_en":"No one is taken for the crime of another, even if it is his father or brother","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Al-Khashkhash al-Anbari said: I came to the Prophet ﷺ with a son of mine. He said: “Is this your son?” I said: “Yes.” He said: “He does not bear your crime, and you do not bear his.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2671,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":19031,"n":19031}],"full":1,"dr":1},{"num":6890,"demo":false,"sanad":"","matn":["عَنْ طَارِقٍ الْمُحَارِبِيِّ، أَنَّ رَجُلاً، قَالَ يَا رَسُولَ اللَّهِ هَؤُلاَءِ بَنُو ثَعْلَبَةَ الَّذِينَ قَتَلُوا فُلاَنًا فِي الْجَاهِلِيَّةِ. فَخُذْ لَنَا بِثَأْرِنَا. فَرَفَعَ يَدَيْهِ حَتَّى رَأَيْتُ بَيَاضَ إِبْطَيْهِ وَهُوَ يَقُولُ لاَ تَجْنِي أُمٌّ عَلَى وَلَدٍ. مَرَّتَيْنِ."],"takhrij":"حسن: رواه النسائي (4839) وابن ماجة (2670) واللفظ لهما وصحّحه ابن حبان (6562) والحاكم (2/611-612) كلهم من حديث يزيد بن زياد بن أبي الجعد، عن جامع بن شداد، عن طارق بن عبد الله المحاربي فذكره في سياق طويل مذكور في السيرة النبوية ما لاقاه النبي صلى الله عليه وسلم من قومه.","grade":"حسن","chapter_ar":"باب لا يؤخذ أحدّ من جناية أحد ولوكان من أبيه أو أخيه","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasai (4839) and Ibn Majah (2670), and authenticated by Ibn Hibban (6562).","chapter_en":"No one is taken for the crime of another, even if it is his father or brother","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Tariq al-Muharibi reported that a man said: “O Messenger of Allah ﷺ, these are Banu Thaʿlabah who killed so-and-so in the pre-Islamic period, so take revenge for us.” The Prophet ﷺ raised his hands until I could see the whiteness of his armpits and said: “A mother is not held liable for her child twice.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4839,"lafz":true,"n":4839},{"key":"ibnmajah","label":"ابن ماجه","number":2670},{"key":"ibnhibban","label":"اللفظ لهما وصحّحه ابن حبان","number":6562}],"full":1,"dr":1},{"num":6891,"demo":false,"sanad":"","matn":["عَنْ أُسَامَةَ بْنِ شَرِيكٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ تَجْنِي نَفْسٌ عَلَى أُخْرَى."],"takhrij":"حسن: رواه ابن ماجة (2672) عن محمود بن عبد الله بن عبيد بن عقيل، قال: حدثنا عمرو بن عاصم، قال: حدثنا أبو العوّام القطان، عن محمد بن جحادة، عن زياد بن علاقة، عن أسامة بن شريك فذكره.","grade":"حسن","chapter_ar":"باب لا يؤخذ أحدّ من جناية أحد ولوكان من أبيه أو أخيه","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Majah (2672).","chapter_en":"No one is taken for the crime of another, even if it is his father or brother","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Usamah ibn Sharik said: The Messenger of Allah ﷺ said: “No soul bears the crime of another.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2672,"lafz":true}],"full":1,"dr":1},{"num":6892,"demo":false,"sanad":"","matn":["عَنْ ثَعْلَبَةَ بْنِ زَهْدَمٍ الْيَرْبُوعِيِّ، قَالَ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ فِي أُنَاسٍ مِنَ الأَنْصَارِ فَقَالُوا يَا رَسُولَ اللَّهِ هَؤُلاَءِ بَنُو ثَعْلَبَةَ بْنِ يَرْبُوعٍ قَتَلُوا فُلاَنًا فِي الْجَاهِلِيَّةِ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهَتَفَ بِصَوْتِهِ أَلاَ لاَ تَجْنِي نَفْسٌ عَلَى الأُخْرَى."],"takhrij":"صحيح: رواه النسائي (4833) عن محمود بن غيلان قال: حدثنا بشر بن السري، قال: حدثنا سفيان (وهو الثوري) عن أشعث، عن الأسود بن هلال، عن ثعلبة بن زهدم اليربوعي فذكره.","grade":"صحيح","chapter_ar":"باب لا يؤخذ أحدّ من جناية أحد ولوكان من أبيه أو أخيه","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasai (4833) and Ahmad (16613).","chapter_en":"No one is taken for the crime of another, even if it is his father or brother","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Thaʿlabah ibn Zahdam al-Yarbuʿi said: The Messenger of Allah ﷺ was delivering a sermon among some of the Ansar. They said: “O Messenger of Allah ﷺ, these are Banu Thaʿlabah ibn Yarbuʿ who killed so-and-so in the pre-Islamic period.” The Prophet ﷺ raised his voice and said: “Indeed, no soul bears the crime of another.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4833,"lafz":true,"n":4833},{"key":"ahmad","label":"مسند الإمام أحمد","number":16613,"n":16613}],"full":1,"dr":1},{"num":6893,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ، أَنَّ غُلاَمًا، لأُنَاسٍ فُقَرَاءَ قَطَعَ أُذُنَ غُلاَمٍ لأُنَاسٍ أَغْنِيَاءَ فَأَتَى أَهْلُهُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّا أُنَاسٌ فُقَرَاءُ. فَلَمْ يَجْعَلْ عَلَيْهِ شَيْئًا."],"takhrij":"صحيح: رواه أبو داود (4590) والنسائي (4751) كلاهما من حديث معاذ بن هشام، حدثنا أبي، عن قتادة، عن أبي نضرة، عن عمران بن الحصين قال: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب التماس إسقاط الدية من الغلام الصغير إذا كان أهله من الفقراء","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4590) and al-Nasā’ī (4751).","chapter_en":"Seeking to waive the blood-money for a small boy when his family is poor","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":16,"content":{"translation":{"en":["ʿImrān ibn al-Ḥuṣayn reported: A young boy belonging to some poor people cut off the ear of a boy belonging to some wealthy people. His family came to the Prophet ﷺ and said: “O Messenger of Allah ﷺ, we are poor people.” So he imposed nothing upon him."]},"buhuth":{"en":["The word ghulām means a young boy. The apparent meaning of the context is that he was free and that his offense was accidental, while his ʿāqilah were poor. The injured boy likewise appears to have been free; had he been a slave, there would have been no point in the family pleading poverty, because the ʿāqilah does not bear liability for injury to a slave, nor for an intentional offense, nor for liability established by confession, according to most scholars, as al-Khaṭṭābī stated.","Al-Nasā’ī and Abū Dāwūd understood ghulām here as meaning a slave. If that understanding is correct, then when an enslaved boy injures a slave or a free person, the liability is attached to his person, according to the majority of jurists."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4590,"lafz":true},{"key":"nasai","label":"النسائي","number":4751}],"full":1,"dr":1},{"num":6894,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ الْعَجْمَاءُ جُرْحُهَا جُبَارٌ، وَالْبِئْرُ جُبَارٌ، وَالْمَعْدِنُ جُبَارٌ، وَفِي الرِّكَازِ الْخُمُسُ."],"takhrij":"متفق عليه: رواه مالك في العقول (42) عن ابن شهاب، عن سعيد وأبي سلمة بن عبدالرحمن، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب جرح العجماء جبار","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (42), al-Bukhari (6912), and Muslim (1710).","chapter_en":"Injury caused by an animal is without liability","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":17,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “The injury caused by an animal is without liability, a well is without liability, a mine is without liability, and one-fifth is due on buried treasure.”"]},"buhuth":{"en":["The word al-ajma’ means an animal, and it is called that because it does not speak. The phrase jubar means it is not subject to compensation, with no blood-money due for it.","The phrase “a well is without liability” means that if a person digs a well on his own property or in unused land and someone falls into it, he is not liable."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":42,"lafz":true},{"key":"bukhari","label":"البخاري","number":6912},{"key":"muslim","label":"مسلم","number":1710}],"full":1,"dr":1},{"num":6895,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ، أَنَّ رَجُلاً، عَضَّ يَدَ رَجُلٍ، فَنَزَعَ يَدَهُ مِنْ فَمِهِ، فَوَقَعَتْ ثَنِيَّتَاهُ، فَاخْتَصَمُوا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ يَعَضُّ أَحَدُكُمْ أَخَاهُ كَمَا يَعَضُّ الْفَحْلُ، لاَ دِيَةَ لَكَ.","وفي لفظ: فرفع إلى النبي صلى الله عليه وسلم فأبطله، وقال: أردت أن تأكل لحمه؟!"],"takhrij":"متفق عليه: رواه البخاري في الديات (6892) ومسلم في القسامة (18:1673) كلاهما من طريق شعبة، حدثنا قتادة، قال: سمعت زرارة بن أوفى، عن عمران بن حصين، قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب إذا عض رجلا فوقعت ثناياه فلادية له","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6892) and Muslim (1673/18). The second wording was narrated by Muslim through another route.","chapter_en":"If a man bites another man and his front teeth fall out, there is no blood-money for him","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":18,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn reported: A man bit another man’s hand. The other man pulled his hand from the biter’s mouth, causing the biter’s two front teeth to fall out. They brought their dispute before the Prophet ﷺ, who said: “Would one of you bite his brother as a stallion bites? He is entitled to no blood-money.” In another wording, the matter was brought before the Prophet ﷺ, and he dismissed the claim and said: “Did you intend to eat his flesh?!”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6892,"lafz":true},{"key":"muslim","label":"مسلم","number":1673},{"key":"muslim","label":"مسلم في القسامه","number":18}],"full":1,"dr":1},{"num":6896,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ، أَنَّ رَجُلاً، عَضَّ يَدَ رَجُلٍ فَانْتَزَعَ يَدَهُ فَسَقَطَتْ ثَنِيَّتُهُ أَوْ ثَنَايَاهُ فَاسْتَعْدَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا تَأْمُرُنِي تَأْمُرُنِي أَنْ آمُرَهُ أَنْ يَدَعَ يَدَهُ فِي فِيكَ تَقْضَمُهَا كَمَا يَقْضَمُ الْفَحْلُ ادْفَعْ يَدَكَ حَتَّى يَعَضَّهَا ثُمَّ انْتَزِعْهَا."],"takhrij":"صحيح: رواه مسلم في القسامة (21:1673) عن أحمد بن عثمان النوفلي، حدثنا قريش بن أنس، عن ابن عون، عن محمد بن سيرين، عن عمران بن حصين، فذكره.","grade":"صحيح","chapter_ar":"باب إذا عض رجلا فوقعت ثناياه فلادية له","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1673/21).","chapter_en":"If a man bites another man and his front teeth fall out, there is no blood-money for him","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":18,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn reported: A man bit another man’s hand. The man pulled his hand away, causing one or more of the biter’s front teeth to fall out. The biter then sought judgment from the Messenger of Allah ﷺ. The Messenger of Allah ﷺ said: “What do you want me to order? Do you want me to order him to leave his hand in your mouth so that you may bite it as a stallion bites? Put your hand forward until he bites it, then pull it away.”"]},"buhuth":{"en":["Al-Ḥāfiẓ referred to this narration in Fatḥ al-Bārī (12/221) and stated that Abū Nuʿaym’s al-Mustakhraj, through the same route as Muslim, has the wording:","“If you wish, we will order him to let you bite his hand, then you may pull it away yourself.”","The command in Muslim’s narration indicates an option, not an obligation. The Prophet ﷺ then ruled that no compensation was due for the biter’s tooth."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1673,"lafz":true,"n":4370},{"key":"muslim","label":"مسلم في القسامه","number":21}],"full":1,"dr":1},{"num":6897,"demo":false,"sanad":"","matn":["عَنْ يَعْلَى بْنِ أُمَيَّةَ، قَالَ: أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ، وَقَدْ عضّ يَدَ رَجُلٍ، فَانْتَزَعَ يَدَهُ فَسَقَطَتْ ثَنِيَّتَاهُ (يَعْنِي الَّذِي عضّه) قَالَ: فَأَبْطَلَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَقَالَ: أَرَدْتَ أَنْ تَقْضَمَهُ كَمَا يَقْضَمُ الْفَحْلُ؟."],"takhrij":"متفق عليه: رواه البخاري في الديات (6893) ومسلم في القسامة (22:1674) كلاهما من حديث عطاء (هو ابن أبي رباح) عن صفوان بن يعلى، عن أبيه، فذكره.","grade":"متفق عليه","chapter_ar":"باب إذا عض رجلا فوقعت ثناياه فلادية له","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (6893) and Muslim (22:1674). This wording is from Muslim.","chapter_en":"If a man bites another man and his front teeth fall out, there is no blood-money for him","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":18,"content":{"translation":{"en":["Yaʿla ibn Umayyah reported that a man came to the Prophet ﷺ after he had bitten another man’s hand, and when the other man pulled his hand away, the biter’s two front teeth fell out. The Prophet ﷺ dismissed his claim and said: “Did you want to chew him as a stallion chews?”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6893,"lafz":true},{"key":"muslim","label":"مسلم","number":22}],"full":1,"dr":1},{"num":6898,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَجُلاً، اطَّلَعَ فِي بَعْضِ حُجَرِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَامَ إِلَيْهِ بِمِشْقَصٍ أَوْ بِمَشَاقِصَ وَجَعَلَ يَخْتِلُهُ لِيَطْعُنَهُ."],"takhrij":"متفق عليه: رواه البخاري في الديات (6900) ومسلم في الآداب (2158) من طريق حماد بن زيد، عن عبيد الله بن أبي بكر، عن أنس، فذكره.","grade":"متفق عليه","chapter_ar":"باب من اطلع في بيت قوم ففقؤوا عينه فلا دية له","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (6900) and Muslim (2158).","chapter_en":"Whoever peeps into people’s house and they put out his eye, there is no blood-money for him","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":19,"content":{"translation":{"en":["Anas ibn Malik reported that a man peeped into one of the rooms of the Prophet ﷺ, so the Prophet ﷺ got up toward him with a broad arrowhead, trying to catch him off guard in order to stab him."]},"buhuth":{"en":["The word mashaqis is the plural of mishqas, which is a broad arrowhead. The phrase yakhtiluhu means he was trying to catch him by surprise and outmaneuver him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6900,"lafz":true},{"key":"muslim","label":"مسلم","number":2158}],"full":1,"dr":1},{"num":6899,"demo":false,"sanad":"","matn":["عن سهل بْنِ سَعْدٍ أَخْبَرَهُ السَّاعِدِيَّ، أَخْبَرَهُ أَنَّ رَجُلاً اطَّلَعَ فِي جُحْرٍ فِي باب رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِدْرًى يَحُكُّ بِهِ رَأْسَهُ، فَلَمَّا رَآهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَوْ أَعْلَمُ أَنْ تَنْتَظِرَنِي لَطَعَنْتُ بِهِ فِي عَيْنَيْكَ. قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّمَا جُعِلَ الإِذْنُ مِنْ قِبَلِ الْبَصَرِ."],"takhrij":"متفق عليه: رواه البخاري في الديات (6901) ومسلم في الآداب (2156) كلاهما من طريق قتيبة بن سعيد، حدثنا ليث (هو ابن سعد)، عن ابن شهاب أن سهل بن سعد الساعدي أخبره، فذكره.","grade":"متفق عليه","chapter_ar":"باب من اطلع في بيت قوم ففقؤوا عينه فلا دية له","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (6901) and Muslim (2156).","chapter_en":"Whoever peeps into people’s house and they put out his eye, there is no blood-money for him","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":19,"content":{"translation":{"en":["Sahl ibn Saʿd reported that a man peeped through a hole in the door of the Messenger of Allah ﷺ while the Messenger of Allah ﷺ had a comb-like tool with which he was scratching his head. When the Messenger of Allah ﷺ saw him, he said: “Had I known that you were looking at me, I would have thrust this into your eyes.” The Messenger of Allah ﷺ also said: “Permission was only prescribed because of the gaze.”"]},"buhuth":{"en":["The word juhr means a hole or opening. The phrase “Permission was only prescribed” means that asking permission before entering was legislated in order to prevent unlawful looking. So it is not permissible for anyone to look through a door hole or any similar opening. This hadith also indicates that it is allowed to strike the eye of a peeper with something light, and if his eye is put out, there is no liability."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري في الديات","number":6901,"lafz":true},{"key":"muslim","label":"مسلم في الاداب","number":2156}],"full":1,"dr":1},{"num":6900,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ أَبُو الْقَاسِمِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : لَوْ أَنَّ امرءاً اطَّلَعَ عَلَيْكَ بِغَيْرِ إِذْنٍ فحذفته بحصاة فَفَقَأْتَ عَيْنَهُ لَمْ يَكُنْ عَلَيْكَ جُنَاحٌ."],"takhrij":"متفق عليه: رواه البخاري في الديات (6902) ومسلم في الآداب (44:2158) من طريق أبي الزناد، عن الأعرج، عن أبي هريرة.","grade":"متفق عليه","chapter_ar":"باب من اطلع في بيت قوم ففقؤوا عينه فلا دية له","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (6902) and Muslim (44:2158). Muslim also narrated through another chain in the Book of Manners: “Whoever looks into the house of people without their permission, it becomes lawful for them to put out his eye.”","chapter_en":"Whoever peeps into people’s house and they put out his eye, there is no blood-money for him","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":19,"content":{"translation":{"en":["Abu Hurayrah reported that Abu al-Qasim said: “If a person were to look at you without permission and you threw a pebble at him and put out his eye, there would be no blame upon you.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6902,"lafz":true},{"key":"muslim","label":"مسلم","number":44}],"full":1,"dr":1},{"num":6901,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِذَا دَخَلَ الْبَصَرُ فَلاَ إِذْنَ."],"takhrij":"حسن: رواه أبو داود (5173) والبخاري في الأدب المفرد (1082) والبيهقي (8/339) كلهم من حديث كثير بن زيد، عن الوليد بن رباح، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب من اطلع في بيت قوم ففقؤوا عينه فلا دية له","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (5173), al-Bukhari in al-Adab al-Mufrad (1082), and al-Bayhaqi (8/339).","chapter_en":"Whoever peeps into people’s house and they put out his eye, there is no blood-money for him","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":19,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “Once the gaze has entered, there is no permission.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":5173,"lafz":true},{"key":"adab","label":"البخاري في الأدب المفرد","number":1082},{"key":"kubrabayhaqi","label":"البيهقي","number":339,"n":382},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":17660,"n":17818}],"full":1,"dr":1,"rep":[14193]},{"num":6902,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ كَشَفَ سِتْرًا فَأَدْخَلَ بَصَرَهُ فِي الْبَيْتِ قَبْلَ أَنْ يُؤْذَنَ لَهُ فَرَأَى عَوْرَةَ أَهْلِهِ فَقَدْ أَتَى حَدًّا لاَ يَحِلُّ لَهُ أَنْ يَأْتِيَهُ لَوْ أَنَّهُ حِينَ أَدْخَلَ بَصَرَهُ اسْتَقْبَلَهُ رَجُلٌ فَفَقَأَ عَيْنَيْهِ مَا غَيَّرْتُ عَلَيْهِ وَإِنْ مَرَّ رَجُلٌ عَلَى بَابٍ لاَ سِتْرَ لَهُ غَيْرِ مُغْلَقٍ فَنَظَرَ فَلاَ خَطِيئَةَ عَلَيْهِ إِنَّمَا الْخَطِيئَةُ عَلَى أَهْلِ الْبَيْتِ."],"takhrij":"حسن: رواه الترمذي (2707) عن قتيبة، حدثنا ابن لهيعة، عن عبيد الله بن أبي جعفر، عن أبي عبد الرحمن الحُبْلى، عن أبي ذر فذكره.","grade":"حسن","chapter_ar":"باب من اطلع في بيت قوم ففقؤوا عينه فلا دية له","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Tirmidhi (2707) and Ahmad (21359, 21572).","chapter_en":"Whoever peeps into people’s house and they put out his eye, there is no blood-money for him","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":19,"content":{"translation":{"en":["Abu Dharr reported that the Messenger of Allah ﷺ said: “Whoever uncovers a curtain and looks into a house before being given permission, and sees the private part of its occupants, has committed a violation that is not lawful for him to commit. If a man were to confront him at that moment and put out his eyes, there would be no blame upon him. But if a man passes by a door that has no curtain and is not closed, and he looks in, then there is no sin upon him. The sin is only upon the people of the house.”"]},"buhuth":{"en":["The phrase “has committed a violation” means that he deserves disciplinary punishment, because he has committed a forbidden and reprehensible act.","The phrase “there would be no blame upon him” means there would be no liability or blood-money upon the one who injured him. In Musnad Ahmad the wording is: “his eye would be forfeit.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":2707,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":21359,"n":21359}],"full":1,"dr":1},{"num":6903,"demo":false,"sanad":"","matn":["عن عبدالله بن عباس قال: إِنَّ أَوَّلَ قَسَامَةٍ كَانَتْ فِي الجاهِلِيَّةِ لَفِينَا بَنِي هَاشِمٍ، كَانَ رَجُلٌ مِنْ بَنِي هَاشِمٍ اسْتَأْجَرَهُ رَجُلٌ مِنْ قُرَيْشٍ مِنْ فَخِذٍ أُخْرَى، فَانْطَلَقَ مَعَهُ فِي إِبِلِهِ، فَمَرَّ رَجُلٌ بِهِ مِنْ بَنِي هَاشِمٍ، قَدْ انْقَطَعَتْ عُرْوَةُ جُوَالِقِهِ، فَقَالَ: أَغِثْنِي بِعِقَالٍ أَشُدُّ بِهِ عُرْوَةَ جُوَالِقِي، لَا تَنْفِرُ الْإِبِلُ، فَأَعْطَاهُ عِقَالًا، فَشَدَّ بِهِ عُرْوَةَ جُوَالِقِهِ، فَلَمَّا نَزَلُوا عُقِلَت الْإِبِلُ إِلَّا بَعِيرًا وَاحِدًا، فَقَالَ الَّذِي اسْتَأْجَرَهُ: مَا شَأْنُ هَذَا الْبَعِيرِ لَمْ يُعْقَلْ مِنْ بَيْنِ الْإِبِلِ؟ قَالَ: لَيْسَ لَهُ عِقَالٌ، قَالَ: فَأَيْنَ عِقَالُهُ؟ قَالَ: فَحَذَفَهُ بِعَصًا كَانَ فِيهَا أَجَلُهُ، فَمَرَّ بِهِ رَجُلٌ مِنْ أَهْلِ الْيَمَنِ، فَقَالَ: أَتَشْهَدُ المَوْسِمَ؟ قَالَ: مَا أَشْهَدُ، وَرُبَّمَا شَهِدْتُهُ، قَالَ: هَلْ أَنْتَ مُبْلِغٌ عَنِّي رِسَالَةً مَرَّةً مِن الدَّهْرِ؟، قَالَ: نَعَمْ.","قَالَ: فَكَتَبَ إِذَا أَنْتَ شَهِدْتَ المَوْسِمَ، فَنَادِ يَا آلَ قُرَيْشٍ، فَإِذَا أَجَابُوكَ، فَنَادِ يَا آلَ بَنِي هَاشِمٍ، فَإِنْ أَجَابُوكَ، فَسَلْ عَنْ أَبِي طَالِبٍ، فَأَخْبِرْهُ: أَنَّ فُلَانًا قَتَلَنِي فِي عِقَالٍ، وَمَاتَ المسْتَأْجَرُ، فَلَمَّا قَدِمَ الَّذِي اسْتَأْجَرَهُ، أَتَاهُ أَبُو طَالِبٍ، فَقَالَ: مَا فَعَلَ صَاحِبُنَا؟ قَالَ: مَرِضَ فَأَحْسَنْتُ الْقِيَامَ عَلَيْهِ، فَوَلِيتُ دَفْنَهُ، قَالَ: قَدْ كَانَ أَهْلَ ذَاكَ مِنْكَ، فَمَكَثَ حِينًا، ثُمَّ إِنَّ الرَّجُلَ الَّذِي أَوْصَى إِلَيْهِ أَنْ يُبْلِغَ عَنْهُ وَافَى الموْسِمَ، فَقَالَ: يَا آلَ قُرَيْشٍ، قَالُوا: هَذِهِ قُرَيْشٌ، قَالَ: يَا آلَ بَنِي هَاشِمٍ، قَالُوا: هَذِهِ بَنُو هَاشِمٍ، قَالَ: أَيْنَ أَبُو طَالِبٍ؟ قَالُوا: هَذَا أَبُو طَالِبٍ، قَالَ: أَمَرَنِي فُلَانٌ أَنْ أُبْلِغَكَ رِسَالَةً: أَنَّ فُلَانًا قَتَلَهُ فِي عِقَالٍ، فَأَتَاهُ أَبُو طَالِبٍ، فَقَالَ لَهُ: اخْتَرْ مِنَّا إِحْدَى ثَلَاثٍ: إِنْ شِئْتَ أَنْ تُؤَدِّيَ مِائَةً مِنْ الْإِبِلِ، فَإِنَّكَ قَتَلْتَ صَاحِبَنَا، وَإِنْ شِئْتَ حَلَفَ خَمْسُونَ مِنْ قَوْمِكَ إِنَّكَ لَمْ تَقْتُلْهُ، فَإِنْ أَبَيْتَ قَتَلْنَاكَ بِهِ، فَأَتَى قَوْمَهُ، فَقَالُوا: نَحْلِفُ فَأَتَتْهُ امْرَأَةٌ مِنْ بَنِي هَاشِمٍ كَانَتْ تَحْتَ رَجُلٍ مِنْهُمْ، قَدْ وَلَدَتْ لَهُ، فَقَالَتْ: يَا أَبَا طَالِبٍ، أُحِبُّ أَنْ تُجِيزَ ابْنِي هَذَا بِرَجُلٍ مِن الخمْسِينَ، وَلَا تُصْبِرْ يَمِينَهُ حَيْثُ تُصْبَرُ الْأَيْمَانُ، فَفَعَلَ، فَأَتَاهُ رَجُلٌ مِنْهُمْ، فَقَالَ: يَا أَبَا طَالِبٍ أَرَدْتَ خَمْسِينَ رَجُلًا أَنْ يَحْلِفُوا مَكَانَ مِائَةٍ مِنْ الْإِبِلِ، يُصِيبُ كُلَّ رَجُلٍ بَعِيرَانِ هَذَانِ بَعِيرَانِ، فَاقْبَلْهُمَا عَنِّي، وَلَا تُصْبِرْ يَمِينِي حَيْثُ تُصْبَرُ الْأَيْمَانُ، فَقَبِلَهُمَا، وَجَاءَ ثَمَانِيَةٌ وَأَرْبَعُونَ فَحَلَفُوا، قَالَ ابْنُ عَبَّاسٍ: فَوَالَّذِي نَفْسِي بِيَدِهِ، مَا حَالَ الحوْلُ، وَمِنْ الثَّمَانِيَةِ وَأَرْبَعِينَ عَيْنٌ تَطْرِفُ."],"takhrij":"صحيح: رواه البخاري في مناقب الأنصار (3845) عن أبي معمر، حدثنا عبدالوارث، حدثنا قطن أبو الهيثم، حدثنا أبو يزيد المدني، عن عكرمة، عن ابن عباس قال: فذكره.","grade":"صحيح","chapter_ar":"باب القسامة في الجاهلية","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (3845).","chapter_en":"Al-qasamah in the pre-Islamic period","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في القسامة","group_en":"Collection of chapters on al-qasamah","part_no":32,"group_no":4,"chapter_no":1,"content":{"translation":{"en":["Abdullah ibn Abbas said: The first qasamah in the pre-Islamic period among us, Banu Hashim, was that a man from Banu Hashim had been hired by a man from Quraysh, from another clan, and he went off with him among his camels. Then a man from Banu Hashim passed by him whose saddlebag strap had snapped, and he said: “Help me with a rope with which I may tie my saddlebag, so the camels do not scatter.” So he gave him a rope, and he tied his saddlebag with it. When they camped and hobbled the camels, one camel alone remained unhobbled. The man who had hired him said: “What is the matter with this camel that it alone has not been hobbled?” He replied: “It has no rope.” He said: “Where is its rope?” Then he struck him with a staff, and that was the cause of his death. A man from Yemen passed by him, and the injured man said: “Will you attend the pilgrimage season?” He said: “Usually I do not, though I may attend it.” He said: “Will you deliver a message for me at some point?” He said: “Yes.”","He said: “When you attend the pilgrimage season, call out: O Quraysh. When they answer you, call out: O Banu Hashim. When they answer you, ask for Abu Talib and tell him that so-and-so killed me over a rope.” Then the hired man died. When the man who had hired him returned, Abu Talib came to him and said: “What happened to our companion?” He said: “He became ill, so I took good care of him and handled his burial.” Abu Talib said: “You were fit to do that.” Some time passed, then the man to whom he had entrusted the message came during the pilgrimage season and called out: “O Quraysh.” They said: “This is Quraysh.” Then he called: “O Banu Hashim.” They said: “This is Banu Hashim.” He said: “Where is Abu Talib?” They said: “Here is Abu Talib.” He said: “So-and-so told me to convey a message to you: so-and-so killed me over a rope.” Abu Talib then came to the accused and said: “Choose one of three options: either you pay one hundred camels, for you killed our companion; or fifty men from your people swear that you did not kill him; if you refuse, we will kill you in retaliation.” So he went to his people, and they said: “We will swear.” Then a woman from Banu Hashim came, married to one of those men and having borne him a child. She said: “O Abu Talib, I would like you to excuse my son from being one of the fifty and not make him swear where the oaths are sworn.” So he did. Then one of them came and said: “O Abu Talib, you wanted fifty men to swear in place of one hundred camels, which means each man’s share is two camels. Here are two camels, so accept them from me and do not make me swear where the oaths are sworn.” So he accepted them, and forty-eight men came and swore. Ibn Abbas said: By the One in whose hand is my soul, before a year had passed, not one eye among those forty-eight was still blinking."]},"intro_majmu":{"ar":["القسامة: لغةً: مصدر بمعنى القسم، أي اليمين. وشرعاً: هي الأيمان المكررة في دعوى القتل، وهي خمسون يميناً من خمسين رجلاً. والقسامة من طرق إثبات القتل أو نفيه إذا لم تتوفر وسائل الإثبات الأخرى، وهي ثابتة بالكتاب والسنة والإجماع. أما الكتاب فقوله تعالى: ﴿وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَمَنْ قُتِلَ مَظْلُومًا فَقَدْ جَعَلْنَا لِوَلِيِّهِ سُلْطَانًا﴾ [الإسراء: ٣٣]. ووكّل الله بيان هذا السلطان إلى النبي ﷺ، فبيّنه بأنه القسامة. وأما السنة فهي كثيرة كما سيأتي."],"en":["Al-qasamah in language means an oath. In legal usage, it means repeated oaths in a murder claim, namely fifty oaths from fifty men.","It is one of the legal methods for establishing or denying liability in a killing case when other means of proof are not available.","It is established by the Qur’an, the Sunnah, and consensus.","As for the Qur’an, Allah says: “Do not kill the soul which Allah has forbidden except with right, and whoever is killed wrongfully, We have given his heir authority.” [Al-Isra: 33]","Allah left the explanation of this authority to the Prophet ﷺ, and he explained that it includes al-qasamah.","As for the Sunnah, the reports on it are many, as will follow."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3845,"lafz":true}],"full":1},{"num":6904,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ   مِنَ الأَنْصَارِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ   أَقَرَّ الْقَسَامَةَ عَلَى مَا كَانَتْ عَلَيْهِ فِي الْجَاهِلِيَّةِ.","وزاد في رواية: وَقَضَى بِهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : بَيْنَ نَاسٍ مِنْ الْأَنْصَارِ فِي قَتِيلٍ ادَّعَوْهُ عَلَى الْيَهُودِ."],"takhrij":"صحيح: رواه مسلم في القسامة (1670) من طريق يونس، عن ابن شهاب، أخبرني أبو سلمة بن عبد الرحمن، وسليمان بن يسار مولى ميمونة زوج النبي صلى الله عليه وسلم عن رجل من أصحاب رسول الله صلى الله عليه وسلم، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في إقرار النبي ﷺ القسامة على ما كانت عليه في الجاهلية","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1670).","chapter_en":"What has come regarding the Prophet ﷺ’s approval of al-qasamah as it existed in the pre-Islamic period","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في القسامة","group_en":"Collection of chapters on al-qasamah","part_no":32,"group_no":4,"chapter_no":2,"content":{"translation":{"en":["A man from the Companions of the Prophet ﷺ, from the Ansar, reported that the Messenger of Allah ﷺ confirmed al-qasamah upon the way it had been in the pre-Islamic period. In another narration it adds: The Messenger of Allah ﷺ judged by it between some men of the Ansar regarding a slain man whose killing they claimed against the Jews."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1670,"lafz":true}],"full":1},{"num":6905,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ أَبِي حَثْمَةَ، أَنَّهُ أَخْبَرَهُ رجال مِنْ كُبَرَاءِ قَوْمِهِ: أَنَّ عَبْدَ اللَّهِ بْنَ سَهْلٍ وَمُحَيِّصَةَ خَرَجَا إِلَى خَيْبَرَ مِنْ جَهْدٍ أَصَابَهُمْ. فأُتي مُحَيِّصَةُ. فَأُخْبِرَ: أَنَّ عَبْدَ اللَّهِ بن سهل قَدْ قُتِلَ وَطُرِحَ فِي فَقِيرٍ بئر أوعين، فَأَتَى يَهُودَ. فَقَالَ: أَنْتُمْ وَاللَّهِ قَتَلْتُمُوهُ. فَقَالُوا: وَاللَّهِ مَا قَتَلْنَاهُ. فأقبل حَتَّى قَدِمَ عَلَى قَوْمِهِ. فَذَكَرَ لَهُمْ ذَلِكَ. ثُمَّ أَقْبَلَ هُوَ وَأَخُوهُ حُوَيِّصَةُ، وَهْوَ أَكْبَرُ مِنْهُ، وَعَبْدُ الرَّحْمَنِ. فَذَهَبَ مُحَيِّصَةُ لِيَتَكَلَّمَ، وَهْوَ الَّذِي كَانَ بِخَيْبَرَ. فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : كَبِّرْ، كَبِّرْ يُرِيدُ السِّنَّ. فَتَكَلَّمَ حُوَيِّصَةُ. ثُمَّ تَكَلَّمَ مُحَيِّصَةُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِمَّا أَنْ يَدُوا صَاحِبَكُمْ وَإِمَّا أَنْ يُؤْذِنُوا بِحَرْبٍ فَكَتَبَ إِلَيْهِمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي ذَلِكَ فكتبوا: إنا وَاللَّهِ مَا قَتَلْنَاهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِحُوَيِّصَةَ وَمُحَيِّصَةَ وَعَبْدِ الرَّحْمَنِ: أَتَحْلِفُونَ وَتَسْتَحِقُّونَ دَمَ صَاحِبِكُمْ؟ فَقَالُوا: لاَ، قَالَ: أَفَتَحْلِفُ لَكُمْ يَهُودُ؟ قَالُوا: لَيْسُوا بِمُسْلِمِينَ. فَوَدَاهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ عِنْدِهِ. فَبَعَثَ إِلَيْهِمْ بِمِائَةِ نَاقَةٍ حَتَّى أُدْخِلَتِ عليهم الدَّارَ، قَالَ سَهْلٌ: لَقَدْ ركضتني مِنْهَا نَاقَةٌ حَمْرَاءَ.","قال مالك: الفقير هو البئر."],"takhrij":"متفق عليه: رواه مالك في القسامة (1) عن أبي ليلى بن عبد الله بن عبدالرحمن بن سهل، عن سهل بن أبي حثمة فذكره.","grade":"متفق عليه","chapter_ar":"باب تبدئة أهل الدم في القسامة","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (1), al-Bukhari (7192), and Muslim (6:1669).","chapter_en":"Beginning with the claimants in al-qasamah","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في القسامة","group_en":"Collection of chapters on al-qasamah","part_no":32,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Sahl ibn Abi Hathmah reported that some of the elders of his people informed him that Abdullah ibn Sahl and Muhayyisah went out to Khaybar because of hardship that had befallen them. Then Muhayyisah was informed that Abdullah ibn Sahl had been killed and thrown into a pit or a well. He went to the Jews and said: “By Allah, you killed him.” They said: “By Allah, we did not kill him.” He returned to his people and informed them of that. Then he came with his brother Huwayyisah, who was older than him, and Abd al-Rahman. Muhayyisah, being the one who had been at Khaybar, moved to speak, but the Messenger of Allah ﷺ said to him: “Let the elder speak, let the elder speak,” meaning with respect to age. So Huwayyisah spoke, then Muhayyisah spoke. The Messenger of Allah ﷺ then said: “Either they pay blood-money for your companion, or they are notified of war.” The Messenger of Allah ﷺ wrote to them about this, and they wrote back: “By Allah, we did not kill him.” So the Messenger of Allah ﷺ said to Huwayyisah, Muhayyisah, and Abd al-Rahman: “Will you swear and thereby deserve the blood of your companion?” They said: “No.” He said: “Then will the Jews swear for you?” They said: “They are not Muslims.” So the Messenger of Allah ﷺ paid his blood-money from his own side. He sent them one hundred she-camels that were brought into their yard. Sahl said: One red she-camel among them kicked me. Malik said: al-faqir means a well."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":1,"lafz":true},{"key":"bukhari","label":"البخاري","number":7192},{"key":"muslim","label":"مسلم","number":1669,"n":4349}],"full":1,"dr":1},{"num":6906,"demo":false,"sanad":"","matn":["عَنْ بُشَيْرِ بْنِ يَسَارٍ، مَوْلَى الأَنْصَارِ عَنْ رَافِعِ بْنِ خَدِيجٍ، وَسَهْلَ بْنَ أَبِي حَثْمَةَ، أَنَّهُمَا حَدَّثَاهُ أَنَّ عَبْدَ اللَّهِ بْنَ سَهْلٍ وَمُحَيِّصَةَ بْنَ مَسْعُودٍ أَتَيَا خَيْبَرَ فَتَفَرَّقَا فِي النَّخْلِ، فَقُتِلَ عَبْدُ اللَّهِ بْنُ سَهْلٍ، فَجَاءَ عَبْدُ الرَّحْمَنِ بْنُ سَهْلٍ وَحُوَيِّصَةُ وَمُحَيِّصَةُ ابْنَا مَسْعُودٍ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَتَكَلَّمُوا فِي أَمْرِ صَاحِبِهِمْ فَبَدَأَ عَبْدُ الرَّحْمَنِ، وَكَانَ أَصْغَرَ الْقَوْمِ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَبِّرِ الْكُبْرَ. ـ قَالَ يَحْيَى لِيَلِيَ الْكَلاَمَ الأَكْبَرُ ـ فَتَكَلَّمُوا فِي أَمْرِ صَاحِبِهِمْ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَتَسْتَحِقُّونَ قَتِيلَكُمْ ـ أَوْ قَالَ صَاحِبَكُمْ ـ بِأَيْمَانِ خَمْسِينَ مِنْكُمْ. قَالُوا يَا رَسُولَ اللَّهِ أَمْرٌ لَمْ نَرَهُ. قَالَ فَتُبْرِئُكُمْ يَهُودُ فِي أَيْمَانِ خَمْسِينَ مِنْهُمْ. قَالُوا يَا رَسُولَ اللَّهِ قَوْمٌ كُفَّارٌ. فَوَدَاهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ قِبَلِهِ.","قال سهل: فأدركت ناقة من تلك الإبل، فدخلتْ مرْبداً فركضتني برجلها."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6143،6142) ومسلم في القسامة (2:1669) كلاهما من طريق حماد بن زيد، ثنا يحيى بن سعيد، عن بُشير بن يسار مولى الأنصار، به. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب تبدئة أهل الدم في القسامة","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (6142, 6143) and Muslim (2:1669). This wording is from al-Bukhari.","chapter_en":"Beginning with the claimants in al-qasamah","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في القسامة","group_en":"Collection of chapters on al-qasamah","part_no":32,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Bushayr ibn Yasar, the freedman of the Ansar, reported from Rafi ibn Khadij and Sahl ibn Abi Hathmah that Abdullah ibn Sahl and Muhayyisah ibn Masud came to Khaybar and then separated among the palm groves. Abdullah ibn Sahl was killed. Then Abd al-Rahman ibn Sahl, Huwayyisah, and Muhayyisah, the sons of Masud, came to the Prophet ﷺ and spoke regarding their companion. Abd al-Rahman began speaking, and he was the youngest of the group, so the Prophet ﷺ said: “Let the elder speak, let the elder speak.” Yahya said: This means the oldest should be the one to speak first. Then they spoke regarding their companion, and the Prophet ﷺ said: “Will you establish your claim to your slain man,” or he said, “your companion,” “by fifty oaths from among you?” They said: “O Messenger of Allah ﷺ, this is something we did not witness.” He said: “Then the Jews will clear themselves by fifty oaths from among them.” They said: “O Messenger of Allah ﷺ, they are disbelieving people.” So the Messenger of Allah ﷺ paid the blood-money himself. Sahl said: One she-camel from those camels caught up with me, entered an enclosure, and kicked me with its leg."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6142,"lafz":true},{"key":"muslim","label":"مسلم","number":1669},{"key":"bukhari","label":"البخاري في الادب","number":6143},{"key":"muslim","label":"مسلم في القسامه","number":2}],"full":1},{"num":6907,"demo":false,"sanad":"","matn":["عَنْ بُشَيْرِ بْنِ يَسَارٍ، زَعَمَ أَنَّ رَجُلاً، مِنَ الأَنْصَارِ يُقَالُ لَهُ سَهْلُ بْنُ أَبِي حَثْمَةَ أَخْبَرَهُ أَنَّ نَفَرًا مِنْ قَوْمِهِ انْطَلَقُوا إِلَى خَيْبَرَ فَتَفَرَّقُوا فِيهَا، وَوَجَدُوا أَحَدَهُمْ قَتِيلاً، وَقَالُوا لِلَّذِي وُجِدَ فِيهِمْ قَتَلْتُمْ صَاحِبَنَا. قَالُوا مَا قَتَلْنَا وَلاَ عَلِمْنَا قَاتِلاً. فَانْطَلَقُوا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا يَا رَسُولَ اللَّهِ انْطَلَقْنَا إِلَى خَيْبَرَ فَوَجَدْنَا أَحَدَنَا قَتِيلاً. فَقَالَ الْكُبْرَ الْكُبْرَ. فَقَالَ لَهُمْ تَأْتُونَ بِالْبَيِّنَةِ عَلَى مَنْ قَتَلَهُ. قَالُوا مَا لَنَا بَيِّنَةٌ. قَالَ فَيَحْلِفُونَ. قَالُوا لاَ نَرْضَى بِأَيْمَانِ الْيَهُودِ. فَكَرِهَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُبْطِلَ دَمَهُ، فَوَدَاهُ مِائَةً مِنْ إِبِلِ الصَّدَقَةِ."],"takhrij":"متفق عليه: رواه البخاري في الديات (6898) ومسلم في القسامة (5:1669) من طريق سعيد بن عُبيد، حدثنا بُشير بن يسار الأنصاري فذكره. واللفظ للبخاري، وأما مسلم فاختصره.","grade":"متفق عليه","chapter_ar":"باب تبدئة أهل الدم في القسامة","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (6898) and Muslim (5:1669).","chapter_en":"Beginning with the claimants in al-qasamah","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في القسامة","group_en":"Collection of chapters on al-qasamah","part_no":32,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Bushayr ibn Yasar claimed that a man from the Ansar called Sahl ibn Abi Hathmah informed him that some men from his people went to Khaybar and separated there. They found one of them murdered, and they said to those among whom he was found: “You killed our companion.” They said: “We did not kill him, nor do we know any killer.” So they went to the Prophet ﷺ and said: “O Messenger of Allah ﷺ, we went to Khaybar and found one of us murdered.” He said: “Let the elders speak, let the elders speak.” Then he said to them: “Will you bring proof against the one who killed him?” They said: “We have no proof.” He said: “Then they will swear.” They said: “We do not accept the oaths of the Jews.” The Messenger of Allah ﷺ disliked allowing his blood to go to waste, so he paid his blood-money with one hundred camels from the alms camels."]},"buhuth":{"en":["This report is abbreviated by some narrators. Its fuller meaning is that the Prophet ﷺ first asked the Ansar for evidence. When they said they had none, he then said: “Then you may swear and deserve the blood of your companion.” They said: “How can we swear?” So he said: “Then they will swear.” In this way, the meaning is complete and the reports do not contradict one another."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6898,"lafz":true},{"key":"muslim","label":"مسلم","number":1669},{"key":"muslim","label":"مسلم في القسامه","number":5}],"full":1,"dr":1},{"num":6908,"demo":false,"sanad":"","matn":["عَنْ أَبِي قلابة أَنَّ عُمَرَ بْنَ عَبْدِ الْعَزِيزِ أَبْرَزَ سَرِيرَهُ يَوْمًا لِلنَّاسِ، ثُمَّ أَذِنَ لَهُمْ فَدَخَلُوا، فَقَالَ: مَا تَقُولُونَ فِي الْقَسَامَةِ؟ قَالُوا: نَقُولُ: الْقَسَامَةُ الْقَوَدُ بِهَا حَقٌّ، وَقَدْ أَقَادَتْ بِهَا الْخُلَفَاءُ. قَالَ لِي: مَا تَقُولُ يَا أَبَا قِلاَبَةَ ونصبنى لِلنَّاسِ. فَقُلْتُ: يَا أَمِيرَ الْمُؤْمِنِينَ عِنْدَكَ رُءُوسُ الأَجْنَادِ، وَأَشْرَافُ الْعَرَبِ، أَرَأَيْتَ لَوْ أَنَّ خَمْسِينَ مِنْهُمْ شَهِدُوا عَلَى رَجُلٍ مُحْصَنٍ بِدِمَشْقَ أَنَّهُ قَدْ زَنَى، لَمْ يَرَوْهُ أَكُنْتَ تَرْجُمُهُ؟ قَالَ: لاَ. قُلْتُ: أَرَأَيْتَ لَوْ أَنَّ خَمْسِينَ مِنْهُمْ شَهِدُوا عَلَى رَجُلٍ بِحِمْصَ أَنَّهُ سَرَقَ أَكُنْتَ تَقْطَعُهُ وَلَمْ يَرَوْهُ؟ قَالَ: لاَ. قُلْتُ: فَوَاللَّهِ مَا قَتَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَطُّ إِلاَّ فِي إِحْدَى ثَلاَثِ خِصَالٍ: رَجُلٌ قَتَلَ بِجَرِيرَةِ نَفْسِهِ فَقُتِلَ، أَوْ رجلٌ زَنَى بَعْدَ إِحْصَانٍ، أَوْ رجلٌ حَارَبَ اللَّهَ وَرَسُولَهُ وارتدَّ عَنِ الإِسْلاَمِ. فَقَالَ الْقَوْمُ: أَوْ لَيْسَ قَدْ حَدَّثَ أَنَسُ بْنُ مَالِكٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَطَعَ فِي السَّرَقِ وَسَمَرَ الأَعْيُنَ، ثُمَّ نَبَذَهُمْ فِي الشَّمْسِ؟ فَقُلْتُ: أَنَا أُحَدِّثُكُمْ حَدِيثَ أَنَسٍ، حَدَّثَنِي أَنَسٌ أَنَّ نَفَرًا مِنْ عُكْلٍ ثَمَانِيَةً قَدِمُوا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَايَعُوهُ عَلَى الإِسْلاَمِ، فَاسْتَوْخَمُوا الأَرْضَ فَسَقِمَتْ أَجْسَامُهُمْ، فَشَكَوْا ذَلِكَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَفَلاَ تَخْرُجُونَ مَعَ رَاعِينَا فِي إِبِلِهِ، فَتُصِيبُونَ مِنْ أَلْبَانِهَا وَأَبْوَالِهَا؟ قَالُوا: بَلَى، فَخَرَجُوا فَشَرِبُوا مِنْ أَلْبَانِهَا وَأَبْوَالِهَا فَصَحُّوا، فَقَتَلُوا راعى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَأَطْرَدُوا النَّعَمَ ، فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَرْسَلَ فِي آثَارِهِمْ، فَأُدْرِكُوا فَجِيءَ بِهِمْ، فَأَمَرَ بِهِمْ، فَقُطِّعَتْ أَيْدِيهِمْ وَأَرْجُلُهُمْ، وَسَمَرَ أَعْيُنَهُمْ، ثُمَّ نَبَذَهُمْ فِي الشَّمْسِ حَتَّى مَاتُوا. قُلْتُ: وَأَىُّ شَىْءٍ أَشَدُّ مِمَّا صَنَعَ هَؤُلاَءِ؟ ارْتَدُّوا عَنِ الإِسْلاَمِ وَقَتَلُوا وَسَرَقُوا . فَقَالَ عَنْبَسَةُ بْنُ سَعِيدٍ: وَاللَّهِ إنْ سَمِعْتُ كَالْيَوْمِ قَطُّ. فَقُلْتُ أتردُّ عليَّ حديثى يَا عَنْبَسَةُ؟ قَالَ: لاَ، وَلَكِنْ جئتَ بِالْحَدِيثِ عَلَى وَجْهِهِ، وَاللَّهِ لاَ يَزَالُ هَذَا الْجُنْدُ بِخَيْرٍ مَا عَاشَ هَذَا الشَّيْخُ بَيْنَ أَظْهُرِهِمْ. قُلْتُ: وَقَدْ كَانَ فِي هَذَا سُنَّةٌ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَيْهِ نَفَرٌ مِنَ الأَنْصَارِ فَتَحَدَّثُوا عِنْدَهُ، فَخَرَجَ رَجُلٌ مِنْهُمْ بَيْنَ أَيْدِيهِمْ فَقُتِلَ، فَخَرَجُوا بَعْدَهُ، فَإِذَا هُمْ بِصَاحِبِهِمْ يَتَشَحَّطُ فِي الدَّمِ، فَرَجَعُوا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: يَا رَسُولَ اللَّهِ صَاحِبُنَا كَانَ تَحَدَّثَ مَعَنَا، فَخَرَجَ بَيْنَ أَيْدِينَا، فَإِذَا نَحْنُ بِهِ يَتَشَحَّطُ فِي الدَّمِ. فَخَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: بِمَنْ تَظُنُّونَ أَوْ تَرَوْنَ قَتَلَهُ؟ قَالُوا: نَرَى أَنَّ الْيَهُودَ قَتَلَتْهُ. فَأَرْسَلَ إِلَى الْيَهُودِ فَدَعَاهُمْ. فَقَالَ: آنْتُمْ قَتَلْتُمْ هَذَا؟. قَالُوا: لاَ. قَالَ: أَتَرْضَوْنَ نَفَلَ خَمْسِينَ مِنَ الْيَهُودِ مَا قَتَلُوهُ. فَقَالُوا: مَا يُبَالُونَ أَنْ يَقْتُلُونَا أَجْمَعِينَ ثُمَّ يَنْتَفِلُونَ. قَالَ: أَفَتَسْتَحِقُّونَ الدِّيَةَ بِأَيْمَانِ خَمْسِينَ مِنْكُمْ. قَالُوا: مَا كُنَّا لِنَحْلِفَ فَوَدَاهُ مِنْ عِنْدِهِ. قُلْتُ: وَقَدْ كَانَتْ هُذَيْلٌ خَلَعُوا خَلِيعًا لَهُمْ فِي الْجَاهِلِيَّةِ فَطَرَقَ أَهْلَ بَيْتٍ مِنَ الْيَمَنِ بِالْبَطْحَاءِ فَانْتَبَهَ لَهُ رجلٌ مِنْهُمْ فَحَذَفَهُ بِالسَّيْفِ فَقَتَلَهُ، فَجَاءَتْ هُذَيْلٌ فَأَخَذُوا اليمانى فَرَفَعُوهُ إِلَى عُمَرَ بِالْمَوْسِمِ وَقَالُوا: قَتَلَ صَاحِبَنَا. فَقَالَ: إِنَّهُمْ قَدْ خَلَعُوهُ. فَقَالَ: يُقْسِمُ خَمْسُونَ مِنْ هُذَيْلٍ مَا خَلَعُوهُ. قَالَ فَأَقْسَمَ مِنْهُمْ تِسْعَةٌ وَأَرْبَعُونَ رَجُلاً ، وَقَدِمَ رَجُلٌ مِنْهُمْ مِنَ الشام فَسَأَلُوهُ أَنْ يُقْسِمَ فَافْتَدَى يَمِينَهُ مِنْهُمْ بِأَلْفِ دِرْهَمٍ، فَأَدْخَلُوا مَكَانَهُ رَجُلاً آخَرَ، فَدَفَعَهُ إِلَى أخى الْمَقْتُولِ فَقُرِنَتْ يَدُهُ بِيَدِهِ، قَالُوا: فَانْطَلَقَا وَالْخَمْسُونَ الَّذِينَ أَقْسَمُوا حَتَّى إِذَا كَانُوا بِنَخْلَةَ، أَخَذَتْهُمُ السَّمَاءُ فَدَخَلُوا فِي غَارٍ فِي الْجَبَلِ، فَانْهَجَمَ الْغَارُ عَلَى الْخَمْسِينَ الَّذِينَ أَقْسَمُوا فَمَاتُوا جَمِيعًا، وَأَفْلَتَ الْقَرِينَانِ وَاتَّبَعَهُمَا حَجَرٌ فَكَسَرَ رِجْلَ أخى الْمَقْتُولِ، فَعَاشَ حَوْلاً ثُمَّ مَاتَ.","قلت: وقد كان عبد الملك بن مروان أقاد رجلا بالقسامة ثم ندم بعد ما صنع، فأمر بالخمسين الذين أقسموا فمُحُوا من الديوان وسيَّرهم إلى الشام."],"takhrij":"متفق عليه: رواه البخاري في الديات (6899) ومسلم في القسامة (10:1671) كلاهما من طريق ابن علية، حدثنا الحجاج بن أبي عثمان، حدثني أبو رجاء مولى أبي قلابة، عن أبي قلابة، فذكره. والسياق للبخاري. وأما مسلم فاختصره مقتصراً على قصة العرنيين.","grade":"متفق عليه","chapter_ar":"باب تبدئة أهل الدم في القسامة","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6899) and Muslim (1671/10). This is the wording of al-Bukhārī.","chapter_en":"Beginning with the claimants in al-qasamah","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في القسامة","group_en":"Collection of chapters on al-qasamah","part_no":32,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Abū Qilābah reported: One day ʿUmar ibn ʿAbd al-ʿAzīz brought out his couch for the people and then permitted them to enter. He asked: “What do you say concerning al-qasāmah?” They replied: “We hold that retaliation may validly be established through al-qasāmah, and the caliphs have carried out retaliation by means of it.” He asked me: “What do you say, O Abū Qilābah?” And he brought me forward before the people. I said: “O Commander of the Believers, you have with you the commanders of the armies and the nobles of the Arabs. Suppose fifty of them testified against a previously married man in Damascus that he had committed adultery, although they had not actually seen it. Would you stone him?” He replied: “No.” I said: “Suppose fifty of them testified against a man in Ḥimṣ that he had stolen, although they had not seen him do it. Would you cut off his hand?” He replied: “No.” I said: “By Allah, the Messenger of Allah ﷺ never put anyone to death except for one of three matters: a man who killed and was killed for his own crime; a man who committed adultery after having been married; or a man who fought Allah and His Messenger and apostatized from Islam.” The people said: “Did Anas ibn Mālik not report that the Messenger of Allah ﷺ cut off hands and branded eyes, then left those people in the sun?” I said: “I will relate to you the hadith of Anas.” Anas told me that eight men from ʿUkl came to the Messenger of Allah ﷺ and pledged allegiance to Islam. They found the climate unhealthy, and their bodies became ill, so they complained to the Messenger of Allah ﷺ. He said: “Why do you not go out with our shepherd among his camels and drink some of their milk and urine?” They replied: “Yes.” They went out, drank their milk and urine, and recovered. Then they killed the shepherd of the Messenger of Allah ﷺ and drove away the camels. When the Messenger of Allah ﷺ learned of this, he sent men after them. They were caught and brought back. He ordered that their hands and feet be cut off and their eyes branded, and then they were left in the sun until they died. I said: “What could be more serious than what these people did? They apostatized from Islam, killed, and stole.” ʿAnbasah ibn Saʿīd said: “By Allah, I have never heard anything like what I heard today.” I asked: “Are you rejecting my hadith, O ʿAnbasah?” He replied: “No. Rather, you have presented the hadith in its complete form. By Allah, this army will remain upon good so long as this old man remains among them.” I said: “There was also a precedent from the Messenger of Allah ﷺ concerning this matter. A group of the Anṣār entered upon him and spoke with him. One of them left ahead of the others and was killed. When the others went out, they found their companion writhing in his blood. They returned to the Messenger of Allah ﷺ and said: ‘O Messenger of Allah ﷺ, our companion was speaking with us, then he went out ahead of us, and we found him writhing in his blood.’ The Messenger of Allah ﷺ went out and asked: ‘Whom do you suspect—or whom do you think—killed him?’ They replied: ‘We think the Jews killed him.’ He sent for the Jews and summoned them, then asked: ‘Did you kill this man?’ They replied: ‘No.’ He asked the Anṣār: ‘Would you accept fifty Jews swearing that they did not kill him?’ They replied: ‘They would not care if they killed all of us and then swore falsely.’ He said: ‘Then will you become entitled to the blood-money by fifty oaths from among yourselves?’ They replied: ‘We would not swear.’ So the Messenger of Allah ﷺ paid his blood-money himself. I also said: “In the pre-Islamic period, Hudhayl had formally disowned one of their men. He came by night to a household from Yemen at al-Baṭḥāʾ. A man among them awoke and struck him with a sword, killing him. Hudhayl seized the Yemeni and brought him before ʿUmar during the pilgrimage season, saying: ‘He killed our companion.’ ʿUmar said: ‘They had disowned him.’ He then ordered: ‘Let fifty men from Hudhayl swear that they had not disowned him.’ Forty-nine men swore. Then a man among them arrived from Syria, and they asked him to swear. He bought himself out of taking the oath by giving them one thousand dirhams, so they substituted another man in his place. That man was handed over to the murdered man’s brother, and their hands were tied together. They set out together with the fifty men who had sworn. When they reached Nakhlah, a storm overtook them, so they entered a cave in the mountain. The cave collapsed upon the fifty men who had sworn, and all of them died. The two men tied together escaped, but a rock followed them and broke the leg of the murdered man’s brother. He lived for one year and then died.” I also said: “ʿAbd al-Malik ibn Marwān once executed a man on the basis of al-qasāmah, but afterward regretted what he had done. He ordered that the fifty men who had sworn be removed from the official register and sent away to Syria.”"]},"buhuth":{"en":["The way to reconcile this hadith with the preceding reports is that some narrators preserved details that others did not. The complete sequence is that the Prophet ﷺ first asked the claimants—the Anṣār—for evidence. When they had no evidence, he offered them the option of taking the oaths, but they refused. He then offered to have the Jews swear, but they refused to accept their oaths. The Messenger of Allah ﷺ therefore paid the blood-money himself from the public treasury. In this way the narrations do not contradict one another; they concern the same incident."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6899,"lafz":true},{"key":"muslim","label":"مسلم","number":1671},{"key":"muslim","label":"مسلم في القسامه","number":10}],"full":1,"dr":1},{"num":6909,"demo":false,"sanad":"","matn":["عن بُشير بن يَسَارٍ مولى بني حَارِثَةَ الأنصاريين أخبر أَخْبَرَهُ وَكَانَ شَيْخًا كَبِيرًا فَقِيهًا، وَكَانَ قَدْ أَدْرَكَ مِنْ أَهْلِ دَارِهِ مِنْ بَنِي حَارِثَةَ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رِجَالًا مِنْهُمْ: رَافِعُ بْنُ خَدِيجٍ، وَسَهْلُ بْنُ أَبِي حَثْمَةَ، وَسُوَيْدُ بْنُ النُّعْمَانِ، حَدَّثُوهُ أَنَّ الْقَسَامَةَ كَانَتْ فِيهِمْ فِي بَنِي حَارِثَةَ بْنِ الْحَارِثِ فِي رَجُلٍ مِنَ الْأَنْصَارِ يُدْعَى عَبْدَ اللَّهِ بْنَ سَهْلٍ، قُتِلَ بِخَيْبَرَ، وَأَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُمْ: تَحْلِفُونَ خَمْسِينَ فَتَسْتَحِقُّونَ قَاتِلَكُمْ أَوْ قَالَ: صَاحِبَكُمْ قَالُوا: يَا رَسُولَ اللَّهِ مَا شَهِدْنَا وَلَا حَضَرْنَا، فَزَعَمَ بَشِيرٌ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُمْ: فَتُبْرِئُكُمْ يَهُودُ بِخَمْسِينَ فَذَكَرَهُ."],"takhrij":"حسن: رواه البيهقي (8/119) من طريق يعقوب بن سفيان، ثنا ابن أبي أويس، حدثني أبي، عن يحيى بن سعيد، أن بُشير بن يسار أخبره فذكره.","grade":"حسن","chapter_ar":"باب تبدئة أهل الدم في القسامة","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bayhaqi (8/119).","chapter_en":"Beginning with the claimants in al-qasamah","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في القسامة","group_en":"Collection of chapters on al-qasamah","part_no":32,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Bushayr ibn Yasar, the freedman of Banu Harithah of the Ansar, who was an elderly and learned man, reported that he had met among the people of his district from Banu Harithah some Companions of the Prophet ﷺ, including Rafi ibn Khadij, Sahl ibn Abi Hathmah, and Suwayd ibn al-Nuʿman. They told him that al-qasamah was applied among them, in Banu Harithah ibn al-Harith, regarding a man from the Ansar called Abdullah ibn Sahl who was killed at Khaybar. The Messenger of Allah ﷺ said to them: “Will fifty of you swear so that you may deserve your slain man,” or he said, “your companion?” They said: “O Messenger of Allah ﷺ, we neither witnessed nor were present.” Bushayr claimed that the Messenger of Allah ﷺ then said to them: “Then the Jews will clear themselves by fifty oaths,” and then he mentioned the rest of the story."]}},"tuhfa":{},"refs":[{"key":"kubrabayhaqi","label":"البيهقي","number":8,"lafz":true},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":16435,"n":16593}],"full":1,"dr":1},{"num":6910,"demo":false,"sanad":"","matn":["عن سهل بن أبي حثمة أن رسول الله صلى الله عليه وسلم قال: تُسمون قاتلكم، ثم تحلفون عليه خمسين يمينا فتُسلمه إليكم."],"takhrij":"حسن: رواه ابن أبي عاصم في الديات (259) واللفظ له، وأحمد (16096) والبيهقي (8/126) كلهم من حديث محمد بن إسحاق، حدثني الزهري، عن سهل بن أبي حثمة فذكره ولفظهما مطولاً.","grade":"حسن","chapter_ar":"باب ماجاء في القتل بالقسامة","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abi Asim in al-Diyat (259), and this is his wording, as well as Ahmad (16096) and al-Bayhaqi (8/126).","chapter_en":"What has come regarding execution based on al-qasamah","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في القسامة","group_en":"Collection of chapters on al-qasamah","part_no":32,"group_no":4,"chapter_no":4,"content":{"translation":{"en":["Sahl ibn Abi Hathmah reported that the Messenger of Allah ﷺ said: “You will name your killer, then swear fifty oaths against him, and we will hand him over to you.”"]}},"tuhfa":{},"refs":[{"key":"rb280","label":"ابن أبي عاصم في الديات","number":259,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":8},{"key":"ahmad","label":"مسند الإمام أحمد","number":16096,"n":16096},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":16456,"n":16614}],"full":1,"dr":1},{"num":6911,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ يَزْنِي الزَّانِي حِينَ يَزْنِي وَهُوَ مُؤْمِنٌ وَلاَ يَسْرِقُ حِينَ يَسْرِقُ وَهُوَ مُؤْمِنٌ وَلاَ يَشْرَبُ الْخَمْرَ حِينَ يَشْرَبُهَا وَهُوَ مُؤْمِنٌ."],"takhrij":"متفق عليه: رواه البخاري في الأشربة (5578) ومسلم في الإيمان (57) كلاهما من حديث ابن وهب، قال: أخبرني يونس، عن ابن شهاب، قال: سمعت أبا سلمة بن عبدالرحمن وسعيد بن المسيب يقولان: قال أبو هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء من المحرمات","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5578) and Muslim (57).","chapter_en":"What Has Been Reported Regarding Forbidden Acts","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في الحدود عامة","group_en":"General Narrations Regarding Legal Punishments","part_no":33,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “The adulterer is not a believer at the moment he commits adultery, the thief is not a believer at the moment he steals, and the one who drinks intoxicants is not a believer at the moment he drinks them.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5578,"lafz":true},{"key":"muslim","label":"مسلم","number":57,"n":207}],"full":1},{"num":6912,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يَنْظُرُ اللَّهُ يَوْمَ الْقِيَامَةِ إِلَى الشَّيْخِ الزَّانِي، وَلَا إِلَى الْعَجُوزِ الزَّانِيَةِ."],"takhrij":"حسن: رواه الطبراني في الأوسط – مجمع البحرين (2448) عن موسى بن سهل، ثنا إبراهيم بن سعيد الجوهري، ثنا محمد بن ربيعة الكلابي، عن عثمان بن واقد، عن مسلم بن يسار، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من المحرمات","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Awsat – Majmaʿ al-Bahrayn (2448).","chapter_en":"What Has Been Reported Regarding Forbidden Acts","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في الحدود عامة","group_en":"General Narrations Regarding Legal Punishments","part_no":33,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Allah will not look on the Day of Resurrection at the elderly man who commits adultery, nor at the elderly woman who commits adultery.”"]}},"tuhfa":{},"refs":[{"key":"sh1352","label":"الطبراني في الأوسط - مجمع البحرين","number":2448,"lafz":true}],"full":1,"dr":1},{"num":6913,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عُمَرَ قَالَ: قَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْمُسْلِمُ أَخُو الْمُسْلِمِ، لاَ يَظْلِمُهُ، وَلاَ يُسْلِمُهُ، مَنْ كَانَ فِي حَاجَةِ أَخِيهِ كَانَ اللَّهُ فِي حَاجَتِهِ، وَمَنْ فرّج عَنْ مُسْلِمٍ كُرْبَةً، فرّج اللَّهُ عَنْهُ بِهَا كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ، وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللَّهُ يَوْمَ الْقِيَامَةِ."],"takhrij":"متفق عليه: رواه البخاري في المظالم (2442) ومسلم في البر والصلة (2580) كلاهما من حديث الليث، عن عُقيل، عن ابن شهاب، أن سالماً أخبره أن عبد الله بن عمر أخبره أن رسول الله صلى الله عليه وسلم قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الستر على المسلم","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2442) and Muslim (2580).","chapter_en":"What Has Been Reported About Concealing the Faults of a Muslim","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في الحدود عامة","group_en":"General Narrations Regarding Legal Punishments","part_no":33,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abdullah ibn Umar reported that the Messenger of Allah ﷺ said: “A Muslim is the brother of a Muslim. He does not oppress him nor abandon him. Whoever fulfills the need of his brother, Allah will fulfill his need. Whoever relieves a Muslim of a hardship, Allah will relieve him of a hardship from the hardships of the Day of Resurrection. Whoever conceals a Muslim, Allah will conceal him on the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2442,"lafz":true},{"key":"muslim","label":"مسلم","number":2580}],"full":1},{"num":6914,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللَّهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ وَمَنْ يَسَّرَ عَلَى مُعْسِرٍ يَسَّرَ اللَّهُ عَلَيْهِ فِي الدُّنْيَا وَالآخِرَةِ وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللَّهُ فِي الدُّنْيَا وَالآخِرَةِ وَاللَّهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ."],"takhrij":"صحيح: رواه مسلم في الذكر (2699) من طرق عن أبي معاوية، عن الأعمش، عن أبي صالح، عن أبي هريرة فذكره في سياق أطول منه.","grade":"صحيح","chapter_ar":"باب ما جاء في الستر على المسلم","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2699).","chapter_en":"What Has Been Reported About Concealing the Faults of a Muslim","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في الحدود عامة","group_en":"General Narrations Regarding Legal Punishments","part_no":33,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Whoever relieves a believer of a hardship from the hardships of this world, Allah will relieve him of a hardship from the hardships of the Day of Resurrection. Whoever makes things easy for one in difficulty, Allah will make things easy for him in this world and the Hereafter. Whoever conceals a Muslim, Allah will conceal him in this world and the Hereafter. Allah continues to aid the servant so long as the servant aids his brother.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2699,"lafz":true}],"full":1,"dr":1,"rep":[14131]},{"num":6915,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ بَعْدَ أَنْ رَجَمَ الْأَسْلَمِيَّ فَقَالَ: اجْتَنِبُوا هَذِهِ الْقَاذُورَةَ الَّتِي نَهَى اللَّهُ عَنْهَا، فَمَنْ أَلَمَّ فَلْيَسْتَتِرْ بِسِتْرِ اللَّهِ، وَلْيَتُبْ إِلَى اللَّهِ، فَإِنَّهُ مَنْ يَبْدُ لَنَا صفحة نُقِمْ عَلَيْهِ كِتَابَ اللَّهِ عَزَّ وَجَلَّ."],"takhrij":"صحيح: رواه الحاكم (4/244) والبيهقي (8/330) كلاهما من حديث يحيى بن سعيد الأنصاري، يقول: حدثني عبد الله بن دينار، عن ابن عمر، فذكره. إسناده صحيح.","grade":"صحيح","chapter_ar":"باب الستر على نفسه","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by al-Hakim (4/244) and al-Bayhaqi (8/330).","chapter_en":"Concealing One’s Own Sin","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في الحدود عامة","group_en":"General Narrations Regarding Legal Punishments","part_no":33,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Ibn Umar reported that after the Prophet ﷺ carried out the stoning of the man from Aslam, he stood and said: “Avoid these filthy acts which Allah has forbidden. Whoever falls into any of them should conceal himself with the concealment of Allah and repent to Allah, for whoever exposes himself to us, we will apply the Book of Allah upon him.”"]}},"tuhfa":{},"refs":[{"key":"kubrabayhaqi","label":"البيهقي","number":330},{"key":"hakim","label":"المستدرك على الصحيحين","number":8158,"n":8164,"lafz":true}],"full":1,"dr":1},{"num":6916,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ بْنِ الصَّامِتِ، قَالَ كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَجْلِسٍ فَقَالَ تُبَايِعُونِي عَلَى أَنْ لاَ تُشْرِكُوا بِاللَّهِ شَيْئًا وَلاَ تَزْنُوا وَلاَ تَسْرِقُوا وَلاَ تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ فَمَنْ وَفَى مِنْكُمْ فَأَجْرُهُ عَلَى اللَّهِ وَمَنْ أَصَابَ شَيْئًا مِنْ ذَلِكَ فَعُوقِبَ بِهِ فَهُوَ كَفَّارَةٌ لَهُ وَمَنْ أَصَابَ شَيْئًا مِنْ ذَلِكَ فَسَتَرَهُ اللَّهُ عَلَيْهِ فَأَمْرُهُ إِلَى اللَّهِ إِنْ شَاءَ عَفَا عَنْهُ وَإِنْ شَاءَ عَذَّبَهُ."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6784) ومسلم في الحدود (1709/41) كلاهما من حديث سفيان بن عيينة، عن الزهري، عن أبي إدريس، عن عبادة بن الصامت فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء أن الحدود كفارة","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6784) and Muslim (1709/41). The wording is from Muslim.","chapter_en":"What Has Been Reported That Legal Punishments Are Expiation","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في الحدود عامة","group_en":"General Narrations Regarding Legal Punishments","part_no":33,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Ubadah ibn al-Samit reported: We were with the Messenger of Allah ﷺ in a gathering and he said: “Pledge allegiance to me that you will not associate anything with Allah, nor commit adultery, nor steal, nor kill the soul that Allah has forbidden except with right. Whoever among you fulfills this, his reward is with Allah. Whoever commits any of these acts and is punished for it, then it is an expiation for him. Whoever commits any of these acts and Allah conceals him, then his matter is with Allah; if He wills He may forgive him, and if He wills He may punish him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6784,"lafz":true},{"key":"muslim","label":"مسلم","number":41}],"full":1,"rep":[13539]},{"num":6917,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ بْنِ الصَّامِتِ، قَالَ أَخَذَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَمَا أَخَذَ عَلَى النِّسَاءِ أَنْ لاَ نُشْرِكَ بِاللَّهِ شَيْئًا وَلاَ نَسْرِقَ وَلاَ نَزْنِيَ وَلاَ نَقْتُلَ أَوْلاَدَنَا وَلاَ يَعْضَهَ بَعْضُنَا بَعْضًا فَمَنْ وَفَى مِنْكُمْ فَأَجْرُهُ عَلَى اللَّهِ وَمَنْ أَتَى مِنْكُمْ حَدًّا فَأُقِيمَ عَلَيْهِ فَهُوَ كَفَّارَتُهُ وَمَنْ سَتَرَهُ اللَّهُ عَلَيْهِ فَأَمْرُهُ إِلَى اللَّهِ إِنْ شَاءَ عَذَّبَهُ وَإِنْ شَاءَ غَفَرَ لَهُ."],"takhrij":"صحيح: رواه مسلم في الحدود (1709/43) عن إسماعيل بن سالم، أخبرنا هشيم، أخبرنا خالد، عن أبي قلابة، عن أبي الأشعث الصنعاني، عن عبادة، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء أن الحدود كفارة","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1709/43).","chapter_en":"What Has Been Reported That Legal Punishments Are Expiation","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في الحدود عامة","group_en":"General Narrations Regarding Legal Punishments","part_no":33,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Ubadah ibn al-Samit reported: The Messenger of Allah ﷺ took a pledge from us just as he took a pledge from the women: that we would not associate anything with Allah, nor steal, nor commit adultery, nor kill our children, nor falsely accuse one another. “Whoever among you fulfills this, his reward is with Allah. Whoever commits an offense deserving a legal punishment and it is carried out upon him, then it is an expiation for him. Whoever Allah conceals, then his matter is with Allah; if He wills He may punish him, and if He wills He may forgive him.”"]},"buhuth":{"en":["His statement: “nor falsely accuse one another” means not to accuse someone with slander and false allegations.","This condition clarifies that the hadith does not include associating partners with Allah mentioned at the beginning of the narration, because Allah said:","“Indeed, Allah does not forgive associating partners with Him.” [Surah al-Nisa: 48]","Polytheism is therefore not subject to divine choice in this context. If a Muslim apostatizes and becomes a polytheist and is killed for apostasy, that execution is not an expiation for him. Rather, this applies specifically to a Muslim who commits offenses such as adultery, theft, false accusation, drinking intoxicants, and similar sins for which legal punishments are prescribed."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":43,"lafz":true}],"full":1,"dr":1,"rep":[13541]},{"num":6918,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ أَصَابَ حَدًّا فَعُجِّلَ عُقُوبَتُهُ فِي الدُّنْيَا فَاللَّهُ أَعْدَلُ مِنْ أَنْ يُثَنِّيَ عَلَى عَبْدِهِ الْعُقُوبَةَ فِي الآخِرَةِ وَمَنْ أَصَابَ حَدًّا فَسَتَرَهُ اللَّهُ عَلَيْهِ وَعَفَا عَنْهُ فَاللَّهُ أَكْرَمُ مِنْ أَنْ يَعُودَ فِي شَيْءٍ قَدْ عَفَا عَنْهُ."],"takhrij":"حسن: رواه الترمذي (2626) وابن ماجة (2604) وأحمد (775) والدارقطني (3/215) والطحاوي في مشكله (2181) والحاكم (2/445) والبيهقي (8/328) كلهم من حديث حجاج بن محمد، عن يونس بن أبي إسحاق، عن أبي إسحاق الهمداني، عن أبي جحيفة، عن علي فذكره.","grade":"حسن","chapter_ar":"باب ما جاء أن الحدود كفارة","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (2626), Ibn Majah (2604), Ahmad (775), and al-Daraqutni (3/215).","chapter_en":"What Has Been Reported That Legal Punishments Are Expiation","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في الحدود عامة","group_en":"General Narrations Regarding Legal Punishments","part_no":33,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Ali ibn Abi Talib reported that the Prophet ﷺ said: “Whoever commits an offense deserving a legal punishment and its punishment is hastened for him in this world, then Allah is too just to punish His servant twice in the Hereafter. And whoever commits an offense deserving a legal punishment and Allah conceals him and pardons him, then Allah is too generous to return to something He has already pardoned.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":2626,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2604},{"key":"sh9771","label":"الدار قطني","number":215},{"key":"ahmad","label":"مسند الإمام أحمد","number":775,"n":775},{"key":"sh22547","label":"الطحاوي في مشكله","number":2181}],"full":1,"dr":1},{"num":6919,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ بْنِ الصَّامِتِ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَقِيمُوا حُدُودَ اللَّهِ فِي الْقَرِيبِ وَالْبَعِيدِ وَلاَ تَأْخُذْكُمْ فِي اللَّهِ لَوْمَةُ لاَئِمٍ."],"takhrij":"حسن: رواه ابن ماجة (2540) عن عبد الله بن سالم المفلوج، قال: حدثنا عبيدة ابن الأسود، عن القاسم بن الوليد، عن أبي صادق، عن ربيعة بن ناجد، عن عبادة بن الصامت فذكره.، ومن هذا الطريق رواه عبدالله بن أحمد في زوائده (22795) مطولا، وسيأتي في كتاب الجهاد.","grade":"حسن","chapter_ar":"باب ما جاء في إقامة الحدود","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2540) and Abdullah ibn Ahmad in his Zawa’id (22795).","chapter_en":"What Has Been Reported About Establishing Legal Punishments","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في الحدود عامة","group_en":"General Narrations Regarding Legal Punishments","part_no":33,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Ubadah ibn al-Samit reported that the Messenger of Allah ﷺ said: “Establish the limits set by Allah upon both the near and the distant, and do not let the blame of any blamer prevent you regarding Allah.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2540,"lafz":true},{"key":"ahmad","label":"عبد الله بن أحمد في زوائده","number":22795}],"full":1,"dr":1},{"num":6920,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّهَا قَالَتْ مَا خُيِّرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ أَمْرَيْنِ إِلاَّ أَخَذَ أَيْسَرَهُمَا، مَا لَمْ يَكُنْ إِثْمًا، فَإِنْ كَانَ إِثْمًا كَانَ أَبْعَدَ النَّاسِ مِنْهُ، وَمَا انْتَقَمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِنَفْسِهِ، إِلاَّ أَنْ تُنْتَهَكَ حُرْمَةُ اللَّهِ فَيَنْتَقِمَ لِلَّهِ بِهَا."],"takhrij":"متفق عليه: رواه مالك في حسن الخلق (2) عن ابن شهاب، عن عروة ابن الزبير، عن عائشة، فذكرته. ورواه البخاري في المناقب (3560)، ومسلم في الفضائل (2327) كلاهما من طريق مالك، به، مثله.","grade":"متفق عليه","chapter_ar":"باب إقامة الحدود لحرمات الله","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (2), al-Bukhari (3560), and Muslim (2327).","chapter_en":"Establishing Legal Punishments for the Sacred Limits of Allah","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في الحدود عامة","group_en":"General Narrations Regarding Legal Punishments","part_no":33,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["ʿA’ishah, the wife of the Prophet ﷺ, said: “Whenever the Messenger of Allah ﷺ was given a choice between two matters, he would choose the easier of the two so long as it was not sinful. But if it was sinful, he was the furthest of people from it. And the Messenger of Allah ﷺ never took revenge for himself, except when the sacred limits of Allah were violated, in which case he would seek justice for the sake of Allah.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":2},{"key":"bukhari","label":"البخاري","number":3560,"lafz":true},{"key":"muslim","label":"مسلم","number":2327}],"full":1,"dr":1,"rep":[13236]},{"num":6921,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ قُرَيْشًا أَهَمَّهُمْ شَأْنُ الْمَرْأَةِ الَّتِي سَرَقَتْ فِي عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ الْفَتْحِ. فَقَالُوا: مَنْ يُكَلِّمُ فِيهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَكَلَّمَهُ فِيهَا أُسَامَةُ بْنُ زَيْدٍ. فَتَلَوَّنَ وَجْهُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَتَشْفَعُ فِي حَدٍّ مِنْ حُدُودِ اللَّهِ؟ فَقَالَ لَهُ أُسَامَةُ: اسْتَغْفِرْ لِي. يَا رَسُولَ اللَّهِ! فَلَمَّا كَانَ الْعَشِيُّ قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاخْتَطَبَ. فَأَثْنَى عَلَى اللَّهِ بِمَا هُوَ أَهْلُهُ. ثُمَّ قَالَ: أَمَّا بَعْدُ، فَإِنَّمَا أَهْلَكَ مِنْ كَانَ قَبْلِكُمْ، أَنَّهُمْ كَانُوا إِذَا سَرَقَ فِيهِمُ الشَّرِيفُ، تَرَكُوهُ، وَإِذَا سَرَقَ فِيهِمُ الضَّعِيفُ، أَقَامُوا عَلَيْهِ الْحَدَّ. وَإِنِّي، وَالَّذِي نَفْسِي بِيَدِهِ! لَوْ أَنَّ فَاطِمَةَ بِنْتَ مُحَمَّدٍ سَرَقَتْ لَقَطَعْتُ يَدَهَا ثُمَّ أَمَرَ بِتِلْكَ الْمَرْأَةِ الَّتِي سَرَقَتْ فَقُطِعَتْ يَدُهَا.","قال يونس: قال ابن شهاب: قال عروة: قالت عائشة: فحسنت توبتها بعد.وتزوجت. وكانت تأتيني بعد ذلك فأرفع حاجتها إلى رسول الله صلى الله عليه وسلم."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6788) ومسلم في الحدود (1688) كلاهما عن طريق الليث، عن ابن شهاب، عن عروة، عن عائشة.","grade":"متفق عليه","chapter_ar":"باب لا محاباة في إقامة الحدود","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6788) and Muslim (1688).","chapter_en":"No Favoritism in Establishing Legal Punishments","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في الحدود عامة","group_en":"General Narrations Regarding Legal Punishments","part_no":33,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["ʿA’ishah, the wife of the Prophet ﷺ, reported that the Quraysh were deeply concerned about the case of the woman who stole during the time of the Prophet ﷺ in the Conquest of Makkah. They said: “Who will speak to the Messenger of Allah ﷺ about her?” So Usamah ibn Zayd spoke to him concerning her. The face of the Messenger of Allah ﷺ changed color and he said: “Are you interceding concerning one of the prescribed punishments of Allah?” Usamah said: “Ask forgiveness for me, O Messenger of Allah ﷺ.” Then in the evening, the Messenger of Allah ﷺ stood and delivered a sermon. He praised Allah as He deserves to be praised, then said: “What destroyed those before you was that when a noble person among them stole, they left him alone, but when a weak person stole, they carried out the punishment upon him. By the One in whose hand is my soul, if Fatimah the daughter of Muhammad were to steal, I would cut off her hand.” Then he ordered that the hand of the woman who stole be cut off. Yunus said: Ibn Shihab said: Urwah said: ʿA’ishah said: “Her repentance afterward was excellent. She later married, and after that she would come to me, and I would present her needs to the Messenger of Allah ﷺ.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6788,"lafz":true},{"key":"muslim","label":"مسلم","number":1688,"n":4411}],"full":1,"dr":1},{"num":6922,"demo":false,"sanad":"","matn":["عَنْ بَهْزِ بْنِ حَكِيمِ بْنِ مُعَاوِيَةَ، عَنْ أَبِيهِ، عَنْ جَدِّهِ قَالَ: أَخَذَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَاسًا مِنْ قَوْمِي فِي تُهْمَةٍ فَحَبَسَهُمْ، فَجَاءَ رَجُلٌ مِنْ قَوْمِي إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَخْطُبُ، فَقَالَ: يَا مُحَمَّدُ عَلَامَ تَحْبِسُ جِيرَتِي؟ فَصَمَتَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْهُ فَقَالَ: إِنَّ نَاسًا لَيَقُولُونَ إِنَّكَ تَنْهَى عَنِ الشَّرِّ، وَتَسْتَخْلِي بِهِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا يَقُولُ؟ قَالَ: فَجَعَلْتُ أَعْرِضُ بَيْنَهُمَا بِالْكَلَامِ مَخَافَةَ أَنْ يَسْمَعَهَا، فَيَدْعُوَ عَلَى قَوْمِي دَعْوَةً، لَا يُفْلِحُونَ بَعْدَهَا أَبَدًا، فَلَمْ يَزَلِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِهِ حَتَّى فَهِمَهَا فَقَالَ: قَدْ قَالُوهَا أَوْ قَائِلُهَا مِنْهُمْ، وَاللهِ لَوْ فَعَلْتُ لَكَانَ عَلَيَّ، وَمَا كَانَ عَلَيْهِمْ خَلُّوا لَهُ عَنْ جِيرَانِهِ."],"takhrij":"حسن: رواه أحمد (20019) عن عبد الرزاق – وهو في مصنفه (18891) عن معمر، عن بهز بن حكيم بإسناده.","grade":"حسن","chapter_ar":"باب ما جاء في حبس المتهم للتحقيق","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (20019), Abd al-Razzaq in al-Musannaf (18891), Abu Dawud (3630), and al-Tirmidhi (1417), who graded it Hasan.","chapter_en":"What Has Been Reported About Detaining the Accused for Investigation","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في الحدود عامة","group_en":"General Narrations Regarding Legal Punishments","part_no":33,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Bahz ibn Hakim narrated from his father, from his grandfather, that the Prophet ﷺ detained some people from his tribe on suspicion. Then a man from his tribe came to the Prophet ﷺ while he was delivering a sermon and said: “O Muhammad, why are you detaining my neighbors?” The Prophet ﷺ remained silent. Then the man said: “Some people claim that you forbid wrongdoing while practicing it secretly.” The Prophet ﷺ said: “What is he saying?” The narrator said: “I began speaking indirectly between them, fearing that he might hear it and supplicate against my people with a supplication after which they would never prosper.” But the Prophet ﷺ continued until he understood what had been said. Then he said: “They have indeed said it — or one of them has said it. By Allah, if I had done that, then the blame would be upon me and not upon them. Release his neighbors for him.”"]}},"tuhfa":{},"refs":[{"key":"abdrazzaq","label":"عبد الرزاق في مصنفه","number":18891},{"key":"abudawud","label":"أبو داود","number":3630},{"key":"tirmidhi","label":"الترمذي","number":1417},{"key":"ahmad","label":"مسند الإمام أحمد","number":20019,"n":20019,"lafz":true}],"full":1,"dr":1,"rep":[6737]},{"num":6923,"demo":false,"sanad":"","matn":["عَنِ النُّعْمَانِ بْنِ بَشِيرٍ، أَنَّهُ رَفَعَ إِلَيْهِ نَفَرٌ مِنَ الْكَلاَعِيِّينَ أَنَّ حَاكَةً سَرَقُوا مَتَاعًا فَحَبَسَهُمْ أَيَّامًا ثُمَّ خَلَّى سَبِيلَهُمْ فَأَتَوْهُ فَقَالُوا خَلَّيْتَ سَبِيلَ هَؤُلاَءِ بِلاَ امْتِحَانٍ وَلاَ ضَرْبٍ. فَقَالَ النُّعْمَانُ مَا شِئْتُمْ إِنْ شِئْتُمْ أَضْرِبْهُمْ فَإِنْ أَخْرَجَ اللَّهُ مَتَاعَكُمْ فَذَاكَ وَإِلاَّ أَخَذْتُ مِنْ ظُهُورِكُمْ مِثْلَهُ. قَالُوا هَذَا حُكْمُكَ. قَالَ هَذَا حُكْمُ اللَّهِ عَزَّ وَجَلَّ وَرَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"حسن: رواه النسائي (4874) وأبو داود (4382) كلاهما من حديث بقية بن الوليد، قال حدثني صفوان بن عمرو، قال: حدثني أزهر بن عبد الله الحرازي، عن النعمان بن بشير قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في حبس المتهم للتحقيق","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4874) and Abu Dawud (4382).","chapter_en":"What Has Been Reported About Detaining the Accused for Investigation","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في الحدود عامة","group_en":"General Narrations Regarding Legal Punishments","part_no":33,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["It was reported from al-Nuʿman ibn Bashir that some people from the tribe of Kilaʿ brought a complaint to him that some weavers had stolen their belongings. He detained them for several days and then released them. They came back and said: “You released them without interrogation or beating.” Al-Nuʿman said: “As you wish. If you want, I can beat them. If Allah causes your property to appear, then that is fine. Otherwise, I will take the equivalent from your backs.” They said: “Is this your judgment?” He replied: “This is the judgment of Allah, the Mighty and Majestic, and His Messenger ﷺ.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4874,"lafz":true,"n":4874},{"key":"abudawud","label":"أبو داود","number":4382}],"full":1,"dr":1},{"num":6924,"demo":false,"sanad":"","matn":["عَنْ عَطِيَّةَ الْقُرَظِيِّ، قَالَ عُرِضْنَا عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ قُرَيْظَةَ فَكَانَ مَنْ أَنْبَتَ قُتِلَ وَمَنْ لَمْ يُنْبِتْ خُلِّيَ سَبِيلُهُ فَكُنْتُ مِمَّنْ لَمْ يُنْبِتْ فَخُلِّيَ سَبِيلِي.","وفي رواية: فكشفوا عانتي، فوجدوها لم يَنبُت فجعلوني في السبي."],"takhrij":"حسن: رواه أبو داود (4404) والترمذي (1584) وابن ماجة (2541) والنسائي (4981) وصحَّحه ابن حبان (4780) والحاكم (3/35) كلهم من طرق عن عبد الملك بن عمير، قال: سمعت عطية القُرظي يقول: فذكره.","grade":"حسن","chapter_ar":"باب الغلام الذي يقام عليه الحد","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4404), al-Tirmidhī (1584), Ibn Mājah (2541), and al-Nasā’ī (4981), and authenticated by Ibn Ḥibbān (4780).","chapter_en":"The Boy Upon Whom the Legal Punishment Is Carried Out","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في الحدود عامة","group_en":"General Narrations Regarding Legal Punishments","part_no":33,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["ʿAṭiyyah al-Quraẓī reported: We were presented before the Messenger of Allah ﷺ on the day of Qurayẓah. Whoever had grown pubic hair was killed, and whoever had not grown it was released. I was among those who had not grown it, so I was released. In another narration: “They examined my pubic area and found that the hair had not yet grown, so they placed me among the captives.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4404,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1584},{"key":"ibnmajah","label":"ابن ماجه","number":2541},{"key":"nasai","label":"النسائي","number":4981},{"key":"ibnhibban","label":"صححه ابن حبان","number":4780}],"full":1,"dr":1},{"num":6925,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِذَا ضَرَبَ أَحَدُكُمْ فَلْيَتَّقِ الْوَجْهَ."],"takhrij":"حسن: رواه أبو داود (4493) عن أبي كامل، حدثنا أبو عوانة، عن عمر بن أبي سلمة، عن أبيه، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب الغلام الذي يقام عليه الحد","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4493). Ahmad (7323) also narrated it with the addition: “For Allah created Adam upon his image.”","chapter_en":"The Boy Upon Whom the Legal Punishment Is Carried Out","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في الحدود عامة","group_en":"General Narrations Regarding Legal Punishments","part_no":33,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “When one of you strikes, let him avoid the face.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4493,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":7323,"n":7323}],"full":1,"dr":1},{"num":6926,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ، قَالَ سَأَلْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَىُّ الذَّنْبِ أَعْظَمُ عِنْدَ اللَّهِ قَالَ أَنْ تَجْعَلَ لِلَّهِ نِدًّا وَهْوَ خَلَقَكَ. قُلْتُ إِنَّ ذَلِكَ لَعَظِيمٌ، قُلْتُ ثُمَّ أَىُّ قَالَ وَأَنْ تَقْتُلَ وَلَدَكَ تَخَافُ أَنْ يَطْعَمَ مَعَكَ. قُلْتُ ثُمَّ أَىُّ قَالَ أَنْ تُزَانِيَ حَلِيلَةَ جَارِكَ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4477) ومسلم في الإيمان (86) كلاهما عن عثمان بن أبي شيبة، حدثنا جرير، عن منصور، عن أبي وائل، عن عمرو بن شُرحبيل، عن عبد الله بن مسعود فذكره.","grade":"متفق عليه","chapter_ar":"باب ماجاء في تحريم الزنا","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4477) and Muslim (86).","chapter_en":"What Has Been Narrated Regarding the Prohibition of Adultery","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abdullah ibn Masʿud said: I asked the Prophet ﷺ, “Which sin is greatest before Allah?” He said: “That you set up a rival to Allah while He created you.” I said: “Indeed that is grave.” I said: “Then what?” He said: “That you kill your child fearing that he will eat with you.” I said: “Then what?” He said: “That you commit adultery with your neighbor’s wife.”"]},"intro":{"ar":["قال اللّٰه تعالى: ﴿وَلَا تَقْرَبُوا الزِّنَىٰ إِنَّهُ كَانَ فَاحِشَةً وَسَاءَ سَبِيلًا﴾ [الإسراء: ٣٢]"],"en":["Allah the Most High said:","“And do not approach unlawful sexual intercourse. Indeed, it is an outrage and an evil path.” [Surah al-Isra’, 17:32]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4477,"lafz":true},{"key":"muslim","label":"مسلم","number":86}],"full":1,"rep":[12650]},{"num":6927,"demo":false,"sanad":"","matn":["عن سمرة بن جندب قال: كان رسول الله صلى الله عليه وسلم مما يكثر أن يقول لأصحابه: هل رأى أحد منكم من رؤيا؟ قال: فيقص عليه من شاء الله أن يقص، وإنه قال ذات غداة: إنه أتاني الليلة آتيان وإنهما ابتعثاني، وإنهما قالا لي: انطلق، وإني انطلقت معهما.. فذكر الحديث بطوله.","وفيه: فانطلقنا فأتينا على مثل التنور- قال: وأحسب أنه كان يقول: فإذا فيه لَغط وأصوات. قال: فاطلعنا فيه فإذا فيه رجال ونساء عُراة، وإذا هم يأتيهم لهب من أسفل منهم، فإذا أتاهم ذلك اللهب ضَوضَوا، قال: قلت لهما: ما هؤلاء؟ قال: قالا لي: انطلق انطلق.. ثم أخبراه بذلك فقالا: وأما الرجال والنساء العراة الذين في مثل بناء التنور فهم الزناة والزواني."],"takhrij":"متفق عليه: رواه البخاري في التعبير (7047) عن مؤمل بن هشام بن أبي هاشم، حدثنا إسماعيل بن إبراهيم، حدثنا عوف، حدثنا أبو رجاء، حدثنا سمرة بن جندب، فذكره. ورواه مسلم في الفضائل (2275/23) من وجه آخر عن أبي رجاء العطاردي مختصرا.","grade":"متفق عليه","chapter_ar":"باب ماجاء في تحريم الزنا","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7047) and Muslim (2275).","chapter_en":"What Has Been Narrated Regarding the Prohibition of Adultery","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Samurah ibn Jundub said: The Messenger of Allah ﷺ would often say to his companions: “Has any one of you seen a dream?” Then whoever Allah willed would relate a dream to him. One morning he said: “Last night two visitors came to me and woke me up, and they said to me: ‘Come.’ So I went with them…” Then he mentioned the lengthy narration. In it is: “We came to something like an oven.” He said: “I think he used to say: inside it was noise and voices. We looked inside and found naked men and women. Flames would come to them from beneath them, and when the flames reached them they cried out loudly. I said to them: ‘Who are these?’ They said to me: ‘Go on, go on…’”","Then they later informed him: “As for the naked men and women who were in the structure resembling an oven, they are the male and female adulterers.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7047,"lafz":true},{"key":"muslim","label":"مسلم","number":23}],"full":1},{"num":6928,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ قَالَ: إِنَّ فَتًى شَابًّا أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، ائْذَنْ لِي بِالزِّنَا، فَأَقْبَلَ الْقَوْمُ عَلَيْهِ فَزَجَرُوهُ وَقَالُوا: مَهْ. مَهْ. فَقَالَ: ادْنُهْ، فَدَنَا مِنْهُ قَرِيبًا. قَالَ: فَجَلَسَ قَالَ: أَتُحِبُّهُ لِأُمِّكَ؟ قَالَ: لَا. وَاللهِ جَعَلَنِي اللهُ فِدَاءَكَ. قَالَ: وَلَا النَّاسُ يُحِبُّونَهُ لِأُمَّهَاتِهِمْ. قَالَ: أَفَتُحِبُّهُ لِابْنَتِكَ؟ قَالَ: لَا. وَاللهِ يَا رَسُولَ اللَّهِ جَعَلَنِي اللهُ فِدَاءَكَ قَالَ: وَلَا النَّاسُ يُحِبُّونَهُ لِبَنَاتِهِمْ. قَالَ: أَفَتُحِبُّهُ لِأُخْتِكَ؟ قَالَ: لَا. وَاللهِ جَعَلَنِي اللهُ فِدَاءَكَ. قَالَ: وَلَا النَّاسُ يُحِبُّونَهُ لِأَخَوَاتِهِمْ. قَالَ: أَفَتُحِبُّهُ لِعَمَّتِكَ؟ قَالَ: لَا. وَاللهِ جَعَلَنِي اللهُ فِدَاءَكَ. قَالَ: وَلَا النَّاسُ يُحِبُّونَهُ لِعَمَّاتِهِمْ. قَالَ: أَفَتُحِبُّهُ لِخَالَتِكَ؟ قَالَ: لَا. وَاللهِ جَعَلَنِي اللهُ فِدَاءَكَ. قَالَ: وَلَا النَّاسُ يُحِبُّونَهُ لِخَالَاتِهِمْ. قَالَ: فَوَضَعَ يَدَهُ عَلَيْهِ وَقَالَ: اللهُمَّ اغْفِرْ ذَنْبَهُ وَطَهِّرْ قَلْبَهُ، وَحَصِّنْ فَرْجَهُ قَالَ: فَلَمْ يَكُنْ بَعْدُ ذَلِكَ الْفَتَى يَلْتَفِتُ إِلَى شَيْءٍ."],"takhrij":"صحيح: رواه أحمد (22211) والطبراني (7679) كلاهما من طريق حَريز بن عثمان، ثنا سليم بن عامر، عن أبي أمامة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ماجاء في تحريم الزنا","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (22211) and al-Tabarani (7679).","chapter_en":"What Has Been Narrated Regarding the Prohibition of Adultery","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abu Umamah narrated that a young man came to the Prophet ﷺ and said: “O Messenger of Allah ﷺ, permit me to commit adultery.” The people turned toward him and rebuked him, saying: “Stop! Stop!” But the Prophet ﷺ said: “Bring him close.” So he came near and sat down. He said: “Would you like it for your mother?” He replied: “No, by Allah, may Allah make me your ransom.” He said: “Nor do people like it for their mothers.” He said: “Would you like it for your daughter?” He replied: “No, by Allah, O Messenger of Allah ﷺ, may Allah make me your ransom.” He said: “Nor do people like it for their daughters.” He said: “Would you like it for your sister?” He replied: “No, by Allah, may Allah make me your ransom.” He said: “Nor do people like it for their sisters.” He said: “Would you like it for your paternal aunt?” He replied: “No, by Allah, may Allah make me your ransom.” He said: “Nor do people like it for their paternal aunts.” He said: “Would you like it for your maternal aunt?” He replied: “No, by Allah, may Allah make me your ransom.” He said: “Nor do people like it for their maternal aunts.” Then he placed his hand upon him and said: “O Allah, forgive his sin, purify his heart, and guard his chastity.” After that, the young man never turned toward anything sinful."]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني","number":7679},{"key":"ahmad","label":"مسند الإمام أحمد","number":22211,"n":22211,"lafz":true}],"full":1,"dr":1,"rep":[12651]},{"num":6929,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ سَبْعَةٌ يُظِلُّهُمُ اللَّهُ يَوْمَ الْقِيَامَةِ فِي ظِلِّهِ، يَوْمَ لاَ ظِلَّ إِلاَّ ظِلُّهُ إِمَامٌ عَادِلٌ، وَشَابٌّ نَشَأَ فِي عِبَادَةِ اللَّهِ، وَرَجُلٌ ذَكَرَ اللَّهَ فِي خَلاَءٍ فَفَاضَتْ عَيْنَاهُ، وَرَجُلٌ قَلْبُهُ مُعَلَّقٌ فِي الْمَسْجِدِ، وَرَجُلاَنِ تَحَابَّا فِي اللَّهِ، وَرَجُلٌ دَعَتْهُ امْرَأَةٌ ذَاتُ مَنْصِبٍ وَجَمَالٍ إِلَى نَفْسِهَا قَالَ إِنِّي أَخَافُ اللَّهَ. وَرَجُلٌ تَصَدَّقَ بِصَدَقَةٍ فَأَخْفَاهَا، حَتَّى لاَ تَعْلَمَ شِمَالُهُ مَا صَنَعَتْ يَمِينُهُ."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6806) ومسلم في الزكاة (1031) من طريق عبيد الله بن عمر، عن خُبيب بن عبد الرحمن، عن حفص بن عاصم، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل من دعي إلى الزنا فامتنع","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6806) and Muslim (1031).","chapter_en":"The Virtue of One Who Is Invited to Adultery but Refrains","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “Seven will be shaded by Allah on the Day when there will be no shade except His shade: a just ruler; a young man raised in the worship of Allah; a man who remembers Allah in solitude and his eyes overflow with tears; a man whose heart is attached to the mosque; two men who love one another for the sake of Allah; a man who is invited by a woman of status and beauty to herself, but he says: ‘Indeed, I fear Allah’; and a man who gives charity so secretly that his left hand does not know what his right hand has spent.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6806,"lafz":true},{"key":"muslim","label":"مسلم","number":1031}],"full":1,"rep":[6704,13597]},{"num":6930,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ أَنَّهُ قَالَ: جاءت الْيَهُودَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرُوا لَهُ أَنَّ رَجُلاً مِنْهُمْ وَامْرَأَةً زَنَيَا، فَقَالَ لَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا تَجِدُونَ فِي التَّوْرَاةِ فِي شَأْنِ الرَّجْمِ؟ فَقَالُوا: نَفْضَحُهُمْ وَيُجْلَدُونَ. فَقَالَ عَبْدُ اللَّهِ بْنُ سَلاَمٍ: كَذَبْتُمْ، إِنَّ فِيهَا الرَّجْمَ. فَأَتَوْا بِالتَّوْرَاةِ فنثروها، فَوَضَعَ أَحَدُهُمْ يَدَهُ عَلَى آيَةِ الرَّجْمِ، ثُمَّ قَرَأَ مَا قَبْلَهَا وَمَا بَعْدَهَا، فَقَالَ عَبْدُ اللَّهِ بْنُ سَلاَمٍ: ارْفَعْ يَدَكَ. فَرَفَعَ يَدَهُ، فَإِذَا فِيهَا آيَةُ الرَّجْمِ. فَقَالُوا: صَدَقَ يَا مُحَمَّدُ فِيهَا آيَةُ الرَّجْمِ، فَأَمَرَ بِهِمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرُجِمَا. فَقَالَ عَبْدُ اللَّهِ بن عُمَرَ: فَرَأَيْتُ الرَّجُلَ يَحْنِي عَلَى الْمَرْأَةِ، يَقِيهَا الْحِجَارَةَ."],"takhrij":"متفق عليه: رواه مالك في الحدود (1) عن نافع، عن عبد الله بن عمر، فذكره. ورواه البخاري في الحدود (6841) من طريق مالك، به، مثله.","grade":"متفق عليه","chapter_ar":"باب ثبوت رجم المحصن في التوراة","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (1), al-Bukhari (6841), and Muslim (1699).","chapter_en":"The Establishment of Stoning the Married Adulterer in the Torah","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Abdullah ibn Umar said: The Jews came to the Messenger of Allah ﷺ and informed him that a man and a woman among them had committed adultery. The Messenger of Allah ﷺ said to them: “What do you find in the Torah concerning stoning?” They said: “We disgrace them and flog them.” Abdullah ibn Salam said: “You have lied. It contains stoning.” So they brought the Torah and spread it open. One of them placed his hand over the verse of stoning and read what came before it and after it. Abdullah ibn Salam said: “Lift your hand.” When he lifted it, the verse of stoning was there. They said: “Muhammad has spoken the truth; the verse of stoning is indeed in it.” So the Messenger of Allah ﷺ ordered that they be stoned. Abdullah ibn Umar said: “I saw the man leaning over the woman, shielding her from the stones.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":1,"lafz":true},{"key":"bukhari","label":"و البخاري","number":6841},{"key":"muslim","label":"مسلم","number":26}],"full":1,"dr":1},{"num":6931,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ أَتَى نَفَرٌ مِنْ يَهُودَ فَدَعَوْا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْقُفِّ فَأَتَاهُمْ فِي بَيْتِ الْمِدْرَاسِ فَقَالُوا يَا أَبَا الْقَاسِمِ إِنَّ رَجُلاً مِنَّا زَنَى بِامْرَأَةٍ فَاحْكُمْ بَيْنَهُمْ فَوَضَعُوا لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وِسَادَةً فَجَلَسَ عَلَيْهَا ثُمَّ قَالَ ائْتُونِي بِالتَّوْرَاةِ. فَأُتِيَ بِهَا فَنَزَعَ الْوِسَادَةَ مِنْ تَحْتِهِ فَوَضَعَ التَّوْرَاةَ عَلَيْهَا ثُمَّ قَالَ آمَنْتُ بِكِ وَبِمَنْ أَنْزَلَكِ. ثُمَّ قَالَ ائْتُونِي بِأَعْلَمِكُمْ. فَأُتِيَ بِفَتًى شَابٍّ ثُمَّ ذَكَرَ قِصَّةَ الرَّجْمِ نَحْوَ حَدِيثِ مَالِكٍ عَنْ نَافِعٍ."],"takhrij":"حسن: رواه أبو داود (4449) عن أحمد بن سعيد الهمداني، حدثنا ابن وهب، حدثني هشام بن سعد، أن زيد بن أسلم حدثه عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب ثبوت رجم المحصن في التوراة","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4449).","chapter_en":"The Establishment of Stoning the Married Adulterer in the Torah","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Ibn Umar said: A group of Jews came and invited the Messenger of Allah ﷺ to al-Quff. He came to them in the study house. They said: “O Abu al-Qasim, a man among us committed adultery with a woman, so judge between them.” They placed a cushion for the Messenger of Allah ﷺ and he sat upon it. Then he said: “Bring me the Torah.” When it was brought, he removed the cushion from beneath himself and placed the Torah upon it. Then he said: “I believe in you and in the One who revealed you.” Then he said: “Bring me your most knowledgeable person.” So a young scholar was brought. Then he mentioned the story of stoning similar to the narration of Malik from Nafiʿ."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4449,"lafz":true}],"full":1,"dr":1},{"num":6932,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ، قَالَ: مرّ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَهُودِيٍّ مُحمماً مَجْلُودًا: فَدَعَاهُمْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: هَكَذَا تَجِدُونَ حَدَّ الزَّانِي فِي كِتَابِكُمْ؟ قَالُوا: نَعَمْ. فَدَعَا رَجُلاً مِنْ عُلَمَائِهِمْ. فَقَالَ: أَنْشُدُكَ بِاللَّهِ الَّذِي أَنْزَلَ التَّوْرَاةَ عَلَى مُوسَى! أَهَكَذَا تَجِدُونَ حَدَّ الزَّانِي فِي كِتَابِكُمْ؟ قَالُوا: لاَ. وَلَوْلاَ أَنَّكَ نَشَدْتَنِي بِهَذَا لَمْ أُخْبِرْكَ. نَجِدُهُ الرَّجْمَ. وَلَكِنَّهُ كَثُرَ فِي أَشْرَافِنَا. فَكُنَّا، إِذَا أَخَذْنَا الشَّرِيفَ تَرَكْنَاهُ. وَإِذَا أَخَذْنَا الضَّعِيفَ، أَقَمْنَا عَلَيْهِ الْحَدَّ، قُلْنَا: تَعَالَوْا فَلْنَجْتَمِعْ عَلَى شيء نُقِيمُهُ عَلَى الشَّرِيفِ وَالْوَضِيعِ. فَجَعَلْنَا التَّحْمِيمَ وَالْجَلْدَ مَكَانَ الرَّجْمِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اللَّهُمَّ! إِنِّي أَوَّلُ مَنْ أَحْيَا أَمْرَكَ إِذَا أَمَاتُوهُ فَأَمَرَ بِهِ فَرُجِمَ. فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ: يَا ﴿أَيُّهَا الرَّسُولُ لَا يَحْزُنْكَ الَّذِينَ يُسَارِعُونَ فِي الْكُفْرِ﴾ [المائدة: ٤١] إِلَى قَوْلِهِ: إِنْ أُوتِيتُمْ هَذَا فَخُذُوهُ [المائدة: ٤١ ] يَقُولُ: ائْتُوا مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَإِنْ أَمَرَكُمْ بِالتَّحْمِيمِ وَالْجَلْدِ فَخُذُوهُ. وَإِنْ أَفْتَاكُمْ بِالرَّجْمِ فَاحْذَرُوا. فَأَنْزَلَ اللَّهُ تَعَالَى: ﴿وَمَنْ لَمْ يَحْكُمْ بِمَا أَنْزَلَ اللَّهُ فَأُولَئِكَ هُمُ الْكَافِرُونَ﴾ [المائدة:٤٤] ﴿وَمَنْ لَمْ يَحْكُمْ بِمَا أَنْزَلَ اللَّهُ فَأُولَئِكَ هُمُ الْفَاسِقُونَ﴾ [المائدة: ٤٧] فِي الْكُفَّارِ كُلُّهَا."],"takhrij":"صحيح: رواه مسلم في الحدود (1700) من طريق أبي معاوية (هو الضرير) عن الأعمش، عن عبد الله بن مرة، عن البراء بن عازب، فذكره.","grade":"صحيح","chapter_ar":"باب ثبوت رجم المحصن في التوراة","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1700).","chapter_en":"The Establishment of Stoning the Married Adulterer in the Torah","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Al-Bara’ ibn ʿAzib said: A Jewish man who had been blackened and flogged was brought past the Prophet ﷺ. He called them and said: “Is this how you find the punishment of the adulterer in your Book?” They said: “Yes.” So he called one of their scholars and said: “I adjure you by Allah who revealed the Torah to Musa: is this how you find the punishment of the adulterer in your Book?” He replied: “No. Had you not adjured me by this, I would not have informed you. We find that it is stoning. But adultery became widespread among our nobles, so when we caught a noble person we left him, and when we caught a weak person we carried out the punishment on him. So we said: let us agree upon something that we can apply equally to both the noble and the weak. Thus we replaced stoning with blackening the face and flogging.” So the Messenger of Allah ﷺ said: “O Allah, I am the first to revive Your command after they had caused it to die.” Then he ordered that the man be stoned. Then Allah the Mighty and Majestic revealed: “O Messenger, do not be grieved by those who hasten into disbelief…” [Surah al-Ma’idah: 41] up to His saying: “If you are given this, then take it.” [Surah al-Ma’idah: 41] Meaning: “Go to Muhammad ﷺ; if he gives you the ruling of blackening and flogging, then accept it, but if he gives you the ruling of stoning, then beware.” Then Allah revealed: “And whoever does not judge by what Allah has revealed — then they are the disbelievers.” [Surah al-Ma’idah: 44] “And whoever does not judge by what Allah has revealed — then they are the wrongdoers.” [Surah al-Ma’idah: 45] “And whoever does not judge by what Allah has revealed — then they are the defiantly disobedient.” [Surah al-Ma’idah: 47] All concerning the disbelievers."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1700,"lafz":true}],"full":1},{"num":6933,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله يقول: رجم النبي صلى الله عليه وسلم رجلاً من أسلم، ورجلا من اليهود وامرأته. وفي رواية: وامرأة."],"takhrij":"صحيح: رواه مسلم في الحدود (1701) عن هارون بن عبد الله حدثنا الحجاج بن محمد، قال: قال ابن جريح، أخبرني أبو الزبير، أنه سمع جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب ثبوت رجم المحصن في التوراة","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1701).","chapter_en":"The Establishment of Stoning the Married Adulterer in the Torah","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Jabir ibn Abdullah said: The Prophet ﷺ stoned a man from Aslam, and a Jewish man together with his wife. In another narration: “and a woman.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1701,"lafz":true}],"full":1,"dr":1},{"num":6934,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجَمَ يَهُودِيًّا وَيَهُودِيَّةً."],"takhrij":"حسن: رواه الترمذي (1437) وابن ماجة (2557) وأحمد (20856) كلهم من طريق شريك، عن سماك، عن جابر بن سمرة فذكره.","grade":"حسن","chapter_ar":"باب ثبوت رجم المحصن في التوراة","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1437), Ibn Majah (2557), Ahmad (20856), and Abu Dawud al-Tayalisi (812).","chapter_en":"The Establishment of Stoning the Married Adulterer in the Torah","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Jabir ibn Samurah narrated that the Prophet ﷺ stoned a Jewish man and a Jewish woman."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1437,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2557},{"key":"tayalisi","label":"أبو داود الطيالسي","number":812},{"key":"ahmad","label":"مسند الإمام أحمد","number":20856,"n":20856}],"full":1,"dr":1},{"num":6935,"demo":false,"sanad":"","matn":["قَالَ: الشَّيْبَانِيُّ أَخْبَرَنِي قَالَ: قُلْتُ: لِابْنِ أَبِي أَوْفَى رَجَمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: نَعَمْ. يَهُودِيًّا وَيَهُودِيَّةً . قَالَ: قُلْتُ: بَعْدَ نُزُولِ النُّورِ أَوْ قَبْلَهَا؟ قَالَ: لَا أَدْرِي."],"takhrij":"صحيح: رواه أحمد (19126) وابن حبان (4433) كلاهما من حديث هُشيم بن بشير، قال: قال الشيباني فذكره.","grade":"صحيح","chapter_ar":"باب ثبوت رجم المحصن في التوراة","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (19126) and Ibn Hibban (4433).","chapter_en":"The Establishment of Stoning the Married Adulterer in the Torah","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Al-Shaybani said: I asked Ibn Abi Awfa: “Did the Messenger of Allah ﷺ carry out stoning?” He said: “Yes, upon a Jewish man and a Jewish woman.” I said: “Was that after the revelation of Surah al-Nur or before it?” He replied: “I do not know.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"ابن حبان","number":4433},{"key":"ahmad","label":"مسند الإمام أحمد","number":19126,"n":19126,"lafz":true}],"full":1,"dr":1},{"num":6936,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: أَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِرَجْمِ الْيَهُودِيِّ وَالْيَهُودِيَّةِ، عِنْدَ بَابِ مَسْجِدِهِ، فَلَمَّا وَجَدَ الْيَهُودِيُّ مَسَّ الْحِجَارَةِ قَامَ عَلَى صَاحِبَتِهِ، فَجَنَا عَلَيْهَا يَقِيهَا مَسَّ الْحِجَارَةِ، حَتَّى قُتِلا جَمِيعًا، فَكَانَ مِمَّا صَنَعَ اللهُ عَزَّ وَجَلَّ لِرَسُولِهِ فِي تَحْقِيقِ الزِّنَا مِنْهُمَا."],"takhrij":"حسن: رواه الإمام أحمد (2368) عن يعقوب وسعد، قالا: حدثنا أبي، عن ابن إسحاق، قال: وحدثني محمد بن طلحة بن يزيد بن ركانة، عن إسماعيل بن إبراهيم الشيباني، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب ثبوت رجم المحصن في التوراة","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (2368), al-Tabarani in al-Kabir (10/403), and al-Hakim (4/365).","chapter_en":"The Establishment of Stoning the Married Adulterer in the Torah","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Ibn Abbas said: The Messenger of Allah ﷺ ordered the Jewish man and woman to be stoned at the door of his mosque. When the Jewish man felt the impact of the stones, he bent over his companion, shielding her from the stones until they both died. This was among the ways Allah the Mighty and Majestic made clear the reality of their adultery to His Messenger ﷺ."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":2368,"lafz":true},{"key":"mujamkabir","label":"الطبراني في الكبير","number":403},{"key":"hakim","label":"الحاكم","number":365}],"full":1,"dr":1},{"num":6937,"demo":false,"sanad":"","matn":["عَبْدِ اللَّهِ بْنِ عَبَّاسٍ، أَنَّهُ قَالَ سَمِعْتُ عُمَرَ بْنَ الْخَطَّابِ، يَقُولُ الرَّجْمُ فِي كِتَابِ اللَّهِ حَقٌّ عَلَى مَنْ زَنَى مِنَ الرِّجَالِ وَالنِّسَاءِ إِذَا أُحْصِنَ إِذَا قَامَتِ الْبَيِّنَةُ أَوْ كَانَ الْحَبَلُ أَوْ الاِعْتِرَافُ."],"takhrij":"متفق عليه: رواه مالك في الحدود (8) عن ابن شهاب، عن عبيدالله بن عبدالله بن عتبة بن مسعود، عن عبد الله بن عباس، فذكره.","grade":"متفق عليه","chapter_ar":"باب ثبوت رجم المحصن في كتاب الله وسنة رسول اللّٰه ﷺ","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (8), al-Bukhari (6830), and Muslim (1691).","chapter_en":"The Establishment of Stoning the Married Adulterer in the Book of Allah and the Sunnah of the Messenger of Allah ﷺ","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Ibn Abbas said: I heard Umar ibn al-Khattab say: “Stoning is a true ruling in the Book of Allah upon married men and women who commit adultery, when proof is established, or pregnancy occurs, or there is confession.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":8,"lafz":true},{"key":"bukhari","label":"البخاري","number":6830},{"key":"muslim","label":"مسلم","number":15}],"full":1,"dr":1},{"num":6938,"demo":false,"sanad":"","matn":["عَنْ كَثِيرِ بْنِ الصَّلْتِ قَالَ: كَانَ ابْنُ الْعَاصِ وَزَيْدُ بْنُ ثَابِتٍ يَكْتُبَانِ المَصَاحِفَ، فَمَرُّوا عَلَى هَذِهِ الْآيَةِ، فَقَالَ زَيْدٌ: سَمِعْتُ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: الشَّيْخُ وَالشَّيْخَةُ إِذَا زَنَيَا فَارْجُمُوهُمَا الْبَتَّةَ فَقَالَ عُمَرُ: لمَّا أُنْزِلَتْ هَذِهِ أَتَيْتُ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ: أَكْتِبْنِيهَا.","قَالَ شُعْبَةُ: فَكَأَنَّهُ كَرِهَ ذَلِكَ، فَقَالَ عُمَرُ: أَلَا تَرَى أَنَّ الشَّيْخَ إِذَا لَمْ يُحْصَنْ جُلِدَ، وَأَنَّ الشَّابَّ إِذَا زَنَى وَقَدْ أُحْصِنَ رُجِمَ."],"takhrij":"صحيح: رواه أحمد (21596) عن محمد بن جعفر، حدثنا شعبة، عن قتادة، عن يونس بن جبير، عن كثير بن الصلت قال: فذكره.","grade":"صحيح","chapter_ar":"باب ثبوت رجم المحصن في كتاب الله وسنة رسول اللّٰه ﷺ","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (21596).","chapter_en":"The Establishment of Stoning the Married Adulterer in the Book of Allah and the Sunnah of the Messenger of Allah ﷺ","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Kathir ibn al-Salt said: Ibn al-ʿAs and Zayd ibn Thabit were writing copies of the Mushaf when they came across this verse. Zayd said: “I heard the Messenger of Allah ﷺ say: ‘The elderly man and elderly woman, if they commit adultery, stone them completely.’” Umar said: “When this was revealed, I came to the Messenger of Allah ﷺ and said: ‘Let me write it down.’” Shuʿbah said: “It was as though he disliked that.” Then Umar said: “Do you not see that an old person, if unmarried, is flogged, while a young person, if married and commits adultery, is stoned?”"]},"buhuth":{"en":["Perhaps the statement, “The elderly man and elderly woman, if they commit adultery…” was from revelation of the Sunnah and not from the recited Qur’an."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":21596,"n":21596,"lafz":true}],"full":1,"dr":1},{"num":6939,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ بْنِ الصَّامِتِ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خُذُوا عَنِّي خُذُوا عَنِّي قَدْ جَعَلَ اللَّهُ لَهُنَّ سَبِيلاً الْبِكْرُ بِالْبِكْرِ جَلْدُ مِائَةٍ وَنَفْىُ سَنَةٍ وَالثَّيِّبُ بِالثَّيِّبِ جَلْدُ مِائَةٍ وَالرَّجْمُ."],"takhrij":"صحيح: رواه مسلم في الحدود (12:1690) عن يحيى بن يحيى التميمي، أخبرنا هُشيم، عن منصور، عن الحسن، عن حِطّان بن عبد الله الرقاشي، عن عبادة بن الصامت قال: فذكره.","grade":"صحيح","chapter_ar":"باب ثبوت رجم المحصن في كتاب الله وسنة رسول اللّٰه ﷺ","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1690).","chapter_en":"The Establishment of Stoning the Married Adulterer in the Book of Allah and the Sunnah of the Messenger of Allah ﷺ","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["ʿUbadah ibn al-Samit said: The Messenger of Allah ﷺ said: “Take from me, take from me. Allah has now made a way for them: the unmarried man with the unmarried woman — one hundred lashes and exile for one year; and the married man with the married woman — one hundred lashes and stoning.”"]},"buhuth":{"en":["His statement, “Allah has now made a way for them,” is a reference to the saying of Allah the Exalted:","“Confine them to houses until death takes them or Allah makes for them a way.” [Surah al-Nisa’: 15]"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":12,"lafz":true}],"full":1,"dr":1},{"num":6940,"demo":false,"sanad":"","matn":["عن ابن عباس قال: وَاللَّاتِي ﴿يَأْتِينَ الْفَاحِشَةَ مِنْ نِسَائِكُمْ فَاسْتَشْهِدُوا عَلَيْهِنَّ أَرْبَعَةً مِنْكُمْ فَإِنْ شَهِدُوا فَأَمْسِكُوهُنَّ فِي الْبُيُوتِ حَتَّى يَتَوَفَّاهُنَّ الْمَوْتُ أَوْ يَجْعَلَ اللَّهُ لَهُنَّ سَبِيلًا﴾ [النساء: ١٥] وذكر الرجل بعد المرأة، ثم جمعهما فقال: وَاللَّذَانِ ﴿يَأْتِيَانِهَا مِنْكُمْ فَآذُوهُمَا فَإِنْ تَابَا وَأَصْلَحَا فَأَعْرِضُوا عَنْهُمَا﴾ [النساء: ١٦] نسخ ذلك بآية الجلد فقال: ﴿الزَّانِيَةُ وَالزَّانِي فَاجْلِدُوا كُلَّ وَاحِدٍ مِنْهُمَا مِائَةَ جَلْدَةٍ وَلَا تَأْخُذْكُمْ بِهِمَا رَأْفَةٌ فِي دِينِ اللَّهِ إِنْ كُنْتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَلْيَشْهَدْ عَذَابَهُمَا طَائِفَةٌ مِنَ الْمُؤْمِنِينَ﴾ [النور:٢ ]"],"takhrij":"حسن: رواه أبو داود (4413) ومن طريقه البيهقي (8/210) عن أحمد بن محمد بن ثابت المروزي، حدثني علي بن الحسين عن أبيه، عن يزيد النحوي، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب ثبوت رجم المحصن في كتاب الله وسنة رسول اللّٰه ﷺ","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4413) and al-Bayhaqi (8/210).","chapter_en":"The Establishment of Stoning the Married Adulterer in the Book of Allah and the Sunnah of the Messenger of Allah ﷺ","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Ibn Abbas said regarding the verse: “And those among your women who commit immorality — call four witnesses against them from among you. If they testify, then confine them to houses until death takes them or Allah makes for them a way.” [Surah al-Nisa’: 15] Then He mentioned the man after the woman, and then combined them together in His saying: “And the two among you who commit it, harm them both. But if they repent and reform, then leave them alone.” [Surah al-Nisa’: 16] This was later abrogated by the verse of flogging: “The female adulterer and the male adulterer — flog each one of them with one hundred lashes, and let not pity for them overcome you in the religion of Allah, if you believe in Allah and the Last Day. And let a group of the believers witness their punishment.” [Surah al-Nur: 2]"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4413,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":210}],"full":1,"dr":1},{"num":6941,"demo":false,"sanad":"","matn":["عَنْ أَبِي، إِسْحَاقَ الشَّيْبَانِيِّ قَالَ سَأَلْتُ عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى هَلْ رَجَمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ نَعَمْ. قَالَ قُلْتُ بَعْدَ مَا أُنْزِلَتْ سُورَةُ النُّورِ أَمْ قَبْلَهَا قَالَ لاَ أَدْرِي."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6812) من طريق خالد (هو ابن عبد الله) ومسلم في الحدود (1702) من طريق علي بن مُسهر، كلاهما عن أبي إسحاق الشيباني، قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ثبوت رجم المحصن في كتاب الله وسنة رسول اللّٰه ﷺ","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (6812), Muslim (1702).","chapter_en":"The Establishment of Stoning the Married Adulterer in the Book of Allah and the Sunnah of the Messenger of Allah ﷺ","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Abu Isḥāq al-Shaybānī said: I asked ʿAbdullāh ibn Abī Awfā: “Did the Messenger of Allah ﷺ ever carry out stoning?” He said: “Yes.” I said: “Was that after Sūrat al-Nūr was revealed or before it?” He said: “I do not know.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6812,"lafz":true,"n":6813},{"key":"muslim","label":"مسلم","number":1702}],"full":1},{"num":6942,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ، رَضِيَ اللَّهُ عَنْهُ حِينَ رَجَمَ الْمَرْأَةَ يَوْمَ الْجُمُعَةِ وَقَالَ قَدْ رَجَمْتُهَا بِسُنَّةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه البخاري في الحدود (6812) عن آدم، حدثنا شعبة، حدثنا سلمة بن كهيل، قال: سمعت الشعبي يحدّث عن علي رضي الله عنه فذكره.","grade":"صحيح","chapter_ar":"باب ثبوت رجم المحصن في كتاب الله وسنة رسول اللّٰه ﷺ","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhārī (6811).","chapter_en":"The Establishment of Stoning the Married Adulterer in the Book of Allah and the Sunnah of the Messenger of Allah ﷺ","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["ʿAlī (may Allah be pleased with him), when he stoned a woman on Friday, said: “I have stoned her according to the Sunnah of the Messenger of Allah ﷺ.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6811,"n":6812},{"key":"bukhari","label":"البخاري في الحدود","number":6812,"lafz":true}],"full":1},{"num":6943,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ يَقُولُ رَجَمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلاً مِنْ أَسْلَمَ وَرَجُلاً مِنَ الْيَهُودِ وَامْرَأَتَهُ."],"takhrij":"صحيح: رواه مسلم في الحدود (28:1701) عن هارون بن عبد الله، حدثنا حجاج بن محمد قال: قال ابن جريج: أخبرني أبو الزبير أنه سمع جابر بن عبد الله، فذكره.","grade":"صحيح","chapter_ar":"باب ثبوت رجم المحصن في كتاب الله وسنة رسول اللّٰه ﷺ","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1701). The phrase “and his wife” refers to a Jewish woman.","chapter_en":"The Establishment of Stoning the Married Adulterer in the Book of Allah and the Sunnah of the Messenger of Allah ﷺ","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Jābir said: The Prophet ﷺ stoned a man from Aslam, and a man from the Jews, and his wife."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1701,"lafz":true},{"key":"muslim","label":"مسلم في الحدود","number":28}],"full":1,"dr":1},{"num":6944,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ أَتَى رَجُلٌ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهْوَ فِي الْمَسْجِدِ فَنَادَاهُ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي زَنَيْتُ. فَأَعْرَضَ عَنْهُ، حَتَّى رَدَّدَ عَلَيْهِ أَرْبَعَ مَرَّاتٍ، فَلَمَّا شَهِدَ عَلَى نَفْسِهِ أَرْبَعَ شَهَادَاتٍ، دَعَاهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ أَبِكَ جُنُونٌ. قَالَ لاَ. قَالَ فَهَلْ أَحْصَنْتَ. قَالَ نَعَمْ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اذْهَبُوا بِهِ فَارْجُمُوهُ.","قال ابن شهاب: فأخبرني من سمع من جابر بن عبد الله قال: فكنت فيمن رجمه، فرجمناه بالمصلى، فلما أذلقته الحجارة هرب، فأدركناه بالحرة فرجمناه."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6815-6816) ومسلم في الحدود (16:1691) كلاهما من طريق الليث بن سعد، حدثني عقيل، عن ابن شهاب، عن أبي سلمة بن عبد الرحمن بن عوف، وسعيد بن المسيب، عن أبي هريرة أنه قال فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في رجم ماعز بن مالك","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6815–6816) and Muslim (1691).","chapter_en":"What has come regarding the stoning of Māʿiz ibn Mālik","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah reported: A man from Aslam came to the Messenger of Allah ﷺ while he was in the mosque and called out: “O Messenger of Allah ﷺ, I have committed adultery.” The Prophet ﷺ turned away from him until he repeated his confession four times. After he had testified against himself four times, the Prophet ﷺ called him and asked: “Are you insane?” He replied: “No.” He asked: “Have you previously been married?” He replied: “Yes.” The Prophet ﷺ then said: “Take him away and stone him.” Ibn Shihāb said: Someone who heard Jābir ibn ʿAbdullāh informed me that Jābir said: “I was among those who stoned him. We stoned him at the prayer place. When the stones caused him severe pain, he fled. We caught up with him at al-Ḥarrah and stoned him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6815,"lafz":true},{"key":"muslim","label":"مسلم","number":1691,"n":4420},{"key":"muslim","label":"مسلم في الحدود","number":16}],"full":1,"dr":1},{"num":6945,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: جَاءَ مَاعِزُ بْنُ مَالِكٍ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنِّي زَنَيْتُ. فَأَعْرَضَ عَنْهُ. ثُمَّ قَالَ: إِنِّي زَنَيْتُ، فَأَعْرَضَ عَنْهُ، ثُمَّ قَالَ: إِنِّي زَنَيْتُ، فَأَعْرَضَ عَنْهُ، ثُمَّ قَالَ: إِنِّي زَنَيْتُ، فَأَعْرَضَ عَنْهُ حَتَّى قَالَ أَرْبَعَ مَرَّاتٍ. فَأَمَرَ بِهِ أَنْ يُرْجَمَ. فَلَمَّا أَصَابَتْهُ الْحِجَارَةُ أَدْبَرَ يَشْتَدُّ، فَلَقِيَهُ رَجُلٌ بِيَدِهِ لَحْيُ جملٍ، فَضَرَبَهُ فَصَرَعَهُ. فَذُكِرَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِرَارُهُ حِينَ مَسَّتْهُ الْحِجَارَةُ فَقَالَ: فَهَلاَّ تَرَكْتُمُوهُ؟"],"takhrij":"حسن: رواه الترمذي (1428) وابن ماجة (2554) وأحمد (9809) وابن الجارود (819) وصحّحه ابن حبان (4439) والحاكم (4/363) والبيهقي (8/228) كلهم من طرق عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكره، وإسناده حسن من أجل محمد بن عمرو وهو ابن علقمة الليثي حسن الحديث. وحسّنه أيضا الترمذي.","grade":"حسن","chapter_ar":"باب ما جاء في رجم ماعز بن مالك","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: narrated by al-Tirmidhī (1428), Ibn Mājah (2554), Aḥmad (9809), Ibn al-Jārūd (819), Ibn Ḥibbān (4439), al-Ḥākim (363/4), al-Bayhaqī (228/8).","chapter_en":"What has come regarding the stoning of Māʿiz ibn Mālik","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah said: Māʿiz ibn Mālik came to the Prophet ﷺ and said: “I have committed adultery.” The Prophet ﷺ turned away from him. Then he repeated it, and the Prophet ﷺ turned away again. Then he repeated it again, and again the Prophet ﷺ turned away, until he said it four times. The Prophet ﷺ then ordered that he be stoned. When the stones struck him, he fled in panic. A man met him holding a jawbone of a camel and struck him, knocking him down. This was mentioned to the Prophet ﷺ regarding his attempt to escape when the stones struck him, and he said: “Why did you not leave him alone?”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1428,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2554},{"key":"sh13071","label":"ابن الجارود","number":819},{"key":"ibnhibban","label":"صححه ابن حبان","number":4439},{"key":"hakim","label":"الحاكم","number":363},{"key":"kubrabayhaqi","label":"البيهقي","number":228},{"key":"ahmad","label":"مسند الإمام أحمد","number":9809,"n":9809}],"full":1,"dr":1},{"num":6946,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: جَاءَ مَاعِزُ بْنُ مَالِكٍ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَرْبَعَ مَرَّاتٍ كُلَّ ذَلِكَ يَرُدَّهُ وَيَقُولُ: أَخْبَرْتَ أَحَدًا غَيْرِي ثُمَّ أَمَرَ بِرَجْمِهِ فَذَهَبُوا بِهِ إِلَى مَكَانٍ يَبْلُغُ صَدْرَهَ إِلَى حَائِطٍ فَذَهَبَ يَثِبُ فَرَمَاهُ رَجُلٌ فَأَصَابَ أَصْلَ أُذُنَيْهِ، فَصُرِعَ فَقَتَلَهُ."],"takhrij":"حسن: رواه النسائي في الكبرى (7163) عن أحمد بن حرب قال: ثنا قاسم بن يزيد -وهو أبو يزيد الجرمي لا بأس به-، عن سفيان، عن سلمة بن كهيل، قال: حدثني أبو مالك، عن رجل من أصحاب النبي صلى الله عليه وسلم قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في رجم ماعز بن مالك","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī in al-Kubrā (7163).","chapter_en":"What has come regarding the stoning of Māʿiz ibn Mālik","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["A man from the Companions of the Prophet ﷺ said: Maʿiz ibn Mālik came to the Prophet ﷺ four times, and each time he would turn him away, saying: “Have you informed anyone other than me?” Then he ordered that he be stoned. They took him to a place where a wall reached up to his chest. He tried to leap away, but a man struck him, hitting the base of his ears, so he fell and was killed."]}},"tuhfa":{},"refs":[{"key":"kubranasai","label":"النسائي في الكبرى","number":7163,"lafz":true}],"full":1,"dr":1},{"num":6947,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، أَنَّ رَجُلاً، مِنْ أَسْلَمَ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهْوَ فِي الْمَسْجِدِ فَقَالَ إِنَّهُ قَدْ زَنَى. فَأَعْرَضَ عَنْهُ، فَتَنَحَّى لِشِقِّهِ الَّذِي أَعْرَضَ فَشَهِدَ عَلَى نَفْسِهِ أَرْبَعَ شَهَادَاتٍ، فَدَعَاهُ فَقَالَ هَلْ بِكَ جُنُونٌ هَلْ أُحْصِنْتَ. قَالَ نَعَمْ. فَأَمَرَ بِهِ أَنْ يُرْجَمَ بِالْمُصَلَّى، فَلَمَّا أَذْلَقَتْهُ الْحِجَارَةُ جَمَزَ حَتَّى أُدْرِكَ بِالْحَرَّةِ فَقُتِلَ."],"takhrij":"متفق عليه: رواه البخاري في الطلاق (5270) ومسلم في الحدود (1691) كلاهما من حديث ابن شهاب، قال: أخبرني أبو سلمة، عن جابر فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في رجم ماعز بن مالك","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5270) and Muslim (1691).","chapter_en":"What has come regarding the stoning of Māʿiz ibn Mālik","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported that a man from Aslam came to the Prophet ﷺ while he was in the mosque and said: “I have committed adultery.” The Prophet ﷺ turned away from him. He then moved to the side where the Prophet ﷺ had turned away from him, and he bore witness against himself four times. The Prophet ﷺ then called him and said: “Are you insane? Have you been previously married?” He said: “Yes.” So the Prophet ﷺ ordered that he be stoned at the place of prayer. When the stones struck him severely, he fled, but he was caught at al-Ḥarrah and killed."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5270,"lafz":true},{"key":"muslim","label":"مسلم","number":1691}],"full":1,"dr":1},{"num":6948,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ، قَالَ رَأَيْتُ مَاعِزَ بْنَ مَالِكٍ حِينَ جِيءَ بِهِ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ قَصِيرٌ أَعْضَلُ لَيْسَ عَلَيْهِ رِدَاءٌ فَشَهِدَ عَلَى نَفْسِهِ أَرْبَعَ مَرَّاتٍ أَنَّهُ زَنَى فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَعَلَّكَ. قَالَ لاَ وَاللَّهِ إِنَّهُ قَدْ زَنَى الأَخِرُ - قَالَ - فَرَجَمَهُ ثُمَّ خَطَبَ فَقَالَ أَلاَ كُلَّمَا نَفَرْنَا غَازِينَ فِي سَبِيلِ اللَّهِ خَلَفَ أَحَدُهُمْ لَهُ نَبِيبٌ كَنَبِيبِ التَّيْسِ يَمْنَحُ أَحَدُهُمُ الْكُثْبَةَ أَمَا وَاللَّهِ إِنْ يُمْكِنِّي مِنْ أَحَدِهِمْ لأُنَكِّلَنَّهُ عَنْهُ."],"takhrij":"صحيح: رواه مسلم في الحدود (1692) عن أبي كامل فُضيل بن حسين الجحدري، حدثنا أبو عوانة، عن سماك بن حرب، عن جابر بن سمرة، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في رجم ماعز بن مالك","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1692).","chapter_en":"What has come regarding the stoning of Māʿiz ibn Mālik","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Jābir ibn Samurah said: I saw Maʿiz ibn Mālik when he was brought to the Prophet ﷺ, a short, strongly built man with no cloak. He testified against himself four times that he had committed adultery. The Messenger of Allah ﷺ said: “Perhaps you…” He said: “No, by Allah, this wretch has committed adultery.” So he stoned him. Then he delivered a sermon saying: “Whenever we go out fighting in the path of Allah, one of them stays behind with a bleating like the bleating of a ram, one of them gives a handful… By Allah, if Allah enables me over one of them, I will make an example of him.”"]},"buhuth":{"en":["Meaning: “ʿAḍal” means strongly built. “al-ākhir” means the worst or most base."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1692,"lafz":true}],"full":1,"dr":1},{"num":6949,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِمَاعِزِ بْنِ مَالِكٍ أَحَقٌّ مَا بَلَغَنِي عَنْكَ. قَالَ وَمَا بَلَغَكَ عَنِّي قَالَ بَلَغَنِي أَنَّكَ وَقَعْتَ بِجَارِيَةِ آلِ فُلاَنٍ. قَالَ نَعَمْ. قَالَ فَشَهِدَ أَرْبَعَ شَهَادَاتٍ. ثُمَّ أَمَرَ بِهِ فَرُجِمَ."],"takhrij":"صحيح: رواه مسلم في الحدود (1693) من طريق أبي عوانة، عن سماك، عن سعيد بن جبير، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في رجم ماعز بن مالك","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1693).","chapter_en":"What has come regarding the stoning of Māʿiz ibn Mālik","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿAbbās reported that the Prophet ﷺ said to Maʿiz ibn Mālik: “Is it true what has reached me about you?” He said: “What has reached you about me?” He said: “It has reached me that you had intercourse with the slave girl of so-and-so.” He said: “Yes.” So he bore witness four times, and then the Prophet ﷺ ordered him to be stoned."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1693,"lafz":true}],"full":1},{"num":6950,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ لَمَّا أَتَى مَاعِزُ بْنُ مَالِكٍ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ لَعَلَّكَ قَبَّلْتَ أَوْ غَمَزْتَ أَوْ نَظَرْتَ. قَالَ لاَ يَا رَسُولَ اللَّهِ. قَالَ أَنِكْتَهَا. لاَ يَكْنِي. قَالَ فَعِنْدَ ذَلِكَ أَمَرَ بِرَجْمِهِ."],"takhrij":"صحيح: رواه البخاري في الحدود (6824) عن عبدالله بن محمد الجعفي، حدثنا وهب بن جرير، حدثنا أبي، قال: سمعت يعلى بن حكيم، عن عكرمة، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في رجم ماعز بن مالك","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6824).","chapter_en":"What has come regarding the stoning of Māʿiz ibn Mālik","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿAbbās said: When Maʿiz ibn Mālik came to the Prophet ﷺ, he said to him: “Perhaps you kissed, or touched, or looked?” He said: “No, O Messenger of Allah ﷺ.” He said: “Did you have intercourse with her?”—he spoke directly without euphemism. At that point he ordered that he be stoned."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6824,"lafz":true}],"full":1,"dr":1},{"num":6951,"demo":false,"sanad":"","matn":["عَنْ أَبِيهِ، أَنَّ مَاعِزَ بْنَ مَالِكٍ الأَسْلَمِيَّ، أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي قَدْ ظَلَمْتُ نَفْسِي وَزَنَيْتُ وَإِنِّي أُرِيدُ أَنْ تُطَهِّرَنِي. فَرَدَّهُ فَلَمَّا كَانَ مِنَ الْغَدِ أَتَاهُ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي قَدْ زَنَيْتُ. فَرَدَّهُ الثَّانِيَةَ فَأَرْسَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى قَوْمِهِ فَقَالَ أَتَعْلَمُونَ بِعَقْلِهِ بَأْسًا تُنْكِرُونَ مِنْهُ شَيْئًا. فَقَالُوا مَا نَعْلَمُهُ إِلاَّ وَفِيَّ الْعَقْلِ مِنْ صَالِحِينَا فِيمَا نُرَى فَأَتَاهُ الثَّالِثَةَ فَأَرْسَلَ إِلَيْهِمْ أَيْضًا فَسَأَلَ عَنْهُ فَأَخْبَرُوهُ أَنَّهُ لاَ بَأْسَ بِهِ وَلاَ بِعَقْلِهِ فَلَمَّا كَانَ الرَّابِعَةَ حَفَرَ لَهُ حُفْرَةً ثُمَّ أَمَرَ بِهِ فَرُجِمَ."],"takhrij":"صحيح: رواه مسلم في الحدود (23:1695) من طريق عبد الله بن نمير، حدثنا بشير بن المهاجر، حدثنا عبد الله بن بريدة، عن أبيه، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في رجم ماعز بن مالك","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1695).","chapter_en":"What has come regarding the stoning of Māʿiz ibn Mālik","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Buraydah ibn al-Ḥuṣayb reported that Maʿiz ibn Mālik al-Aslamī came to the Messenger of Allah ﷺ and said: “O Messenger of Allah ﷺ, I have wronged myself and committed adultery, and I want you to purify me.” He turned him away. The next day he came again and said the same, and he turned him away a second time. The Messenger of Allah ﷺ then sent to his people and said: “Do you find anything wrong with his mind? Do you deny anything about him?” They said: “We do not know anything about him except that he is among our best and most sound in mind.” He came a third time, and he again sent to them and they informed him the same. When it was the fourth time, a pit was dug for him and then he was ordered to be stoned."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1695,"lafz":true,"n":4432},{"key":"muslim","label":"مسلم في الحدود","number":23}],"full":1},{"num":6952,"demo":false,"sanad":"","matn":["عَنْ أَبِي، سَعِيدٍ أَنَّ رَجُلاً، مِنْ أَسْلَمَ يُقَالُ لَهُ مَاعِزُ بْنُ مَالِكٍ أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ إِنِّي أَصَبْتُ فَاحِشَةً فَأَقِمْهُ عَلَىَّ. فَرَدَّهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِرَارًا قَالَ ثُمَّ سَأَلَ قَوْمَهُ فَقَالُوا مَا نَعْلَمُ بِهِ بَأْسًا إِلاَّ أَنَّهُ أَصَابَ شَيْئًا يَرَى أَنَّهُ لاَ يُخْرِجُهُ مِنْهُ إِلاَّ أَنْ يُقَامَ فِيهِ الْحَدُّ - قَالَ - فَرَجَعَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَمَرَنَا أَنْ نَرْجُمَهُ - قَالَ - فَانْطَلَقْنَا بِهِ إِلَى بَقِيعِ الْغَرْقَدِ - قَالَ - فَمَا أَوْثَقْنَاهُ وَلاَ حَفَرْنَا لَهُ - قَالَ - فَرَمَيْنَاهُ بِالْعَظْمِ وَالْمَدَرِ وَالْخَزَفِ - قَالَ - فَاشْتَدَّ فَاشْتَدَدْنَا خَلْفَهُ حَتَّى أَتَى عُرْضَ الْحَرَّةِ فَانْتَصَبَ لَنَا فَرَمَيْنَاهُ بِجَلاَمِيدِ الْحَرَّةِ - يَعْنِي الْحِجَارَةَ - حَتَّى سَكَتَ - قَالَ - ثُمَّ قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَطِيبًا مِنَ الْعَشِيِّ فَقَالَ أَوَكُلَّمَا انْطَلَقْنَا غُزَاةً فِي سَبِيلِ اللَّهِ تَخَلَّفَ رَجُلٌ فِي عِيَالِنَا لَهُ نَبِيبٌ كَنَبِيبِ التَّيْسِ عَلَىَّ أَنْ لاَ أُوتَى بِرَجُلٍ فَعَلَ ذَلِكَ إِلاَّ نَكَّلْتُ بِهِ. قَالَ فَمَا اسْتَغْفَرَ لَهُ وَلاَ سَبَّهُ."],"takhrij":"صحيح: رواه مسلم في الحدود (20:1694) عن محمد بن المثنى، حدثني عبد الأعلى، حدثنا داود، عن أبي نضرة، عن أبي سعيد، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في رجم ماعز بن مالك","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1694).","chapter_en":"What has come regarding the stoning of Māʿiz ibn Mālik","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Abū Saʿīd reported that a man from Aslam called Maʿiz ibn Mālik came to the Messenger of Allah ﷺ and said: “I have committed an indecent act, so carry out the punishment on me.” The Prophet ﷺ turned him away repeatedly. Then he asked his people about him. They said: “We know nothing wrong about him except that he did something from which he believes nothing will purify him except the prescribed punishment.” So the Prophet ﷺ ordered that he be stoned. We went with him to Baqīʿ al-Gharqad. We did not bind him or dig for him. We threw bones, clods of earth, and pieces of pottery at him, and he ran and we chased him until he reached Ḥarrah. Then he stood firm, and we stoned him with large stones. Then the Messenger of Allah ﷺ delivered a sermon saying: “Whenever we go out on expeditions in the path of Allah, one of them stays behind among our families, with a bleating like the bleating of a ram. I will not be brought a man who does that except that I will make an example of him.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1694,"lafz":true},{"key":"muslim","label":"مسلم في الحدود","number":20}],"full":1,"dr":1},{"num":6953,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ قَالَ: بَيْنَمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْمَسْجِدِ، وَنَحْنُ قُعُودٌ مَعَهُ، إِذْ جَاءَ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ إِنِّي أَصَبْتُ حدّاً فَأَقِمْهُ عليّ، فَسَكَتَ عَنْهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأُقِيمَتِ الصَّلاَةُ، فَلَمَّا انْصَرَفَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ أَبُو أُمَامَةَ: فَاتَّبَعَ الرَّجُلُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ انْصَرَفَ. وَاتَّبَعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْظُرُ مَا يَرُدُّ عَلَى الرَّجُلِ، فَلَحِقَ الرَّجُلُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ إِنِّي أَصَبْتُ حَدًّا فَأَقِمْهُ علي. قَالَ أَبُو أُمَامَةَ: فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَرَأَيْتَ حِينَ خَرَجْتَ مِنْ بَيْتِكَ، أَلَيْسَ قَدْ تَوَضَّأْتَ فَأَحْسَنْتَ الْوُضُوءَ؟ قَالَ: بَلَى يَا رَسُولَ اللَّهِ! قَالَ: ثُمَّ شَهِدْتَ الصَّلاَةَ مَعَنَا؟ فَقَالَ: نَعَمْ يَا رَسُولَ اللَّهِ. قَالَ: فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَإِنَّ اللَّهَ قَدْ غَفَرَ لَكَ حَدَّكَ – أَوْ قَالَ: ذَنْبَكَ."],"takhrij":"صحيح: رواه مسلم في التوبة (2765) من طريق عمر بن يونس، حدثنا عكرمة بن عمّار، حدثنا شدّاد، حدثنا أبو أمامة قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في رجم ماعز بن مالك","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2765).","chapter_en":"What has come regarding the stoning of Māʿiz ibn Mālik","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Abū Umāmah reported: While the Messenger of Allah ﷺ was in the mosque, a man came and said: “O Messenger of Allah ﷺ, I have committed a prescribed sin, so carry out the punishment on me.” The Prophet ﷺ remained silent. Prayer was established, and when he finished, the Prophet ﷺ said: “When you left your house, did you not perform ablution properly?” He said: “Yes.” He said: “Then you prayed with us?” He said: “Yes.” He said: “Then Allah has forgiven you your prescribed sin—or your sin.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2765,"lafz":true}],"full":1},{"num":6954,"demo":false,"sanad":"","matn":["عن يَزِيدَ بْنِ نعيم بن هزال عَنْ أَبِيهِ، قَالَ كَانَ مَاعِزُ بْنُ مَالِكٍ يَتِيمًا فِي حِجْرِ أَبِي. فَأَصَابَ جَارِيَةً مِنَ الْحَىِّ فَقَالَ لَهُ أَبِي ائْتِ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبِرْهُ بِمَا صَنَعْتَ لَعَلَّهُ يَسْتَغْفِرُ لَكَ وَإِنَّمَا يُرِيدُ بِذَلِكَ رَجَاءَ أَنْ يَكُونَ لَهُ مَخْرَجًا فَأَتَاهُ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي زَنَيْتُ فَأَقِمْ عَلَىَّ كِتَابَ اللَّهِ. فَأَعْرَضَ عَنْهُ فَعَادَ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي زَنَيْتُ فَأَقِمْ عَلَىَّ كِتَابَ اللَّهِ. حَتَّى قَالَهَا أَرْبَعَ مِرَارٍ. قَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّكَ قَدْ قُلْتَهَا أَرْبَعَ مَرَّاتٍ فَبِمَنْ. قَالَ بِفُلاَنَةَ. قَالَ هَلْ ضَاجَعْتَهَا. قَالَ نَعَمْ. قَالَ هَلْ بَاشَرْتَهَا. قَالَ نَعَمْ. قَالَ هَلْ جَامَعْتَهَا. قَالَ نَعَمْ. قَالَ فَأَمَرَ بِهِ أَنْ يُرْجَمَ فَأُخْرِجَ بِهِ إِلَى الْحَرَّةِ. فَلَمَّا رُجِمَ فَوَجَدَ مَسَّ الْحِجَارَةِ جَزِعَ فَخَرَجَ يَشْتَدُّ فَلَقِيَهُ عَبْدُ اللَّهِ بْنُ أُنَيْسٍ وَقَدْ عَجَزَ أَصْحَابُهُ فَنَزَعَ لَهُ بِوَظِيفِ بَعِيرٍ فَرَمَاهُ بِهِ فَقَتَلَهُ ثُمَّ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ ذَلِكَ لَهُ فَقَالَ هَلاَّ تَرَكْتُمُوهُ لَعَلَّهُ أَنْ يَتُوبَ فَيَتُوبَ اللَّهُ عَلَيْهِ."],"takhrij":"حسن: رواه أبو داود (4419) عن محمد بن سليمان الأنباري، حدثنا وكيع، عن هشام بن سعد، قال: أخبرني يزيد بن نعيم بن هزال، عن أبيه، قال: كان ماعز بن مالك يتيما في حجر أبي.","grade":"حسن","chapter_ar":"باب ما جاء في رجم ماعز بن مالك","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4419).","chapter_en":"What has come regarding the stoning of Māʿiz ibn Mālik","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Yazīd ibn Nuʿaym ibn Hazzāl, from his father, reported: Maʿiz ibn Mālik was an orphan in my father’s care. He committed indecency with a girl from the tribe, so my father said to him: “Go to the Messenger of Allah ﷺ and inform him of what you have done; perhaps he will seek forgiveness for you.” So he went and said: “O Messenger of Allah ﷺ, I have committed adultery, so carry out upon me the Book of Allah.” He turned away from him, then he returned and repeated it four times. The Prophet ﷺ said: “With whom?” He said: “So-and-so.” He said: “Did you lie with her?” He said: “Yes.” He said: “Did you have intimate contact?” He said: “Yes.” He said: “Did you have intercourse?” He said: “Yes.” So he ordered that he be stoned. He was taken out to al-Ḥarrah, and when the stones struck him he panicked and ran. Then ʿAbdullāh ibn Unays met him and struck him with a camel bone and killed him. Then the Prophet ﷺ said: “Why did you not leave him—perhaps he would have repented, and Allah would have accepted his repentance.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4419,"lafz":true}],"full":1,"dr":1},{"num":6955,"demo":false,"sanad":"","matn":["عَنْ أَبِي الْهَيْثَمِ بْنِ نَصْرِ بْنِ دَهْرٍ الْأَسْلَمِيِّ، عَنْ أَبِيهِ قَالَ: كُنْتُ فِيمَنْ رَجَمَهُ فَلَمَّا وَجَدَ مَسَّ الْحِجَارَةِ جَزِعَ جَزَعًا شَدِيدًا فَذَكَرْنَا ذَلِكَ لِرَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ   قَالَ: فَهَلَّا تَرَكْتُمُوهُ؟.","قَالَ مُحَمَّدٌ: فَذَكَرْتُ ذَلِكَ مِنْ حَدِيثِهِ حِينَ سَمِعْتُهُ، أَلَا تَرَكْتُمُوهُ؟ لِعَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ، فَقَالَ لِي: حَدَّثَنِي حُسْنُ بْنُ مُحَمَّدِ بْنِ عَلِيِّ بْنِ أَبِي طَالِبٍ، قَالَ: حَدَّثَنِي ذَلِكَ مِنْ قَوْلِ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  أَلَا تَرَكْتُمُوهُ؟ لِمَاعِزِ بْنِ مَالِكٍ، مَنْ شِئْتَ مِنْ رِجَالِ أَسْلَمَ مِمَّنْ لَا أَتَّهِمُ، وَلَمْ أَعْرِفْ وَجْهَ الْحَدِيثِ فَجِئْتُ جَابِرَ بْنَ عَبْدِ اللهِ، فَقُلْتُ: إِنَّ رِجَالَ أَسْلَمَ يُحَدِّثُونِي أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، قَالَ لَهُمْ حِينَ ذَكَرُوا جَزَعَ مَاعِزٍ مِنَ الْحِجَارَةِ حِينَ أَصَابَتْهُ: فَهَلَّا تَرَكْتُمُوهُ؟، وَمَا أَتَّهِمُ الْقَوْمَ وَمَا أَعْرِفُ الْحَدِيثَ قَالَ: يَا ابْنَ أَخِي أَنَا أَعْلَمُ النَّاسِ بِهَذَا الْحَدِيثِ؛ كُنْتُ فِيمَنْ رَجَمَ الرَّجُلَ إِنَّا لَمَّا خَرَجْنَا بِهِ فَرَجَمْنَاهُ فَوَجَدَ مَسَّ الْحِجَارَةِ صَرَخَ بِنَا يَا قَوْمُ رُدُّونِي إِلَى رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَإِنَّ قَوْمِي قَتَلُونِي وَغَرُّونِي مِنْ نَفْسِي، وَأَخْبَرُونِي أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  غَيْرُ قَاتِلٍ فَلَمْ نَنْزِعْ عَنْهُ حَتَّى قَتَلْنَاهُ فَلَمَّا رَجَعْنَا إِلَى رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قَالَ: فَهَلَّا تَرَكْتُمُ الرَّجُلَ؟ وَجِئْتُمُونِي بِهِ ، لِيَتَثَبَّتَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فِيهِ، فَأَمَّا تَرْكُ حَدٍّ فَلَا."],"takhrij":"حسن: رواه أبو داود (4420) والنسائي في الكبرى (7297) واللفظ له، والطحاوي في مشكله (434) كلهم من حديث يزيد بن زريع، حدثنا محمد بن إسحاق، حدثني محمد بن إبراهيم، عن أبي الهيثم فذكره. وزاد في أبي داود: فعرفت وجه الحديث","grade":"حسن","chapter_ar":"باب ما جاء في رجم ماعز بن مالك","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (4420), al-Nasa’i in al-Kubra (7297), wording from him, and al-Tahawi in Mushkil al-Athar (434).","chapter_en":"What has come regarding the stoning of Māʿiz ibn Mālik","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Abu al-Haytham ibn Nasr ibn Dahr al-Aslami, from his father, said: I was among those who stoned him. When he felt the touch of the stones, he became extremely distressed, and we mentioned that to the Messenger of Allah ﷺ. He said: “Why did you not leave him?” Muhammad said: I mentioned this narration when I heard it—“Why did you not leave him?”—to ʿAsim ibn ʿUmar ibn Qatadah. He said to me: Hasan ibn Muhammad ibn ʿAli ibn Abi Talib told me that he narrated this from the Messenger of Allah ﷺ: “Why did you not leave him (Maʿiz ibn Malik)?” from reliable men among the people of Aslam earlier. I did not fully understand the chain, so I went to Jabir ibn ʿAbd Allah and said: The men of Aslam narrate that the Messenger of Allah ﷺ said to them when they mentioned Maʿiz’s panic from the stones: “Why did you not leave him?” I do not accuse them, but I do not know this narration.","He said: O my nephew, I am the most knowledgeable of this hadith. I was among those who stoned the man. When we went out with him and stoned him, he felt the impact of the stones and cried out: “O people, return me to the Messenger of Allah ﷺ, for my people have killed me and deceived me about myself, and told me that the Messenger of Allah ﷺ would not kill me.” But we did not stop until we killed him. When we went to the Messenger of Allah ﷺ, he said: “Why did you not leave the man and bring him to me so that the Messenger of Allah ﷺ could verify what had reached him? As for leaving a legal punishment (ḥadd), that is not permissible.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"رَوَاهُ أَبُو دَاوُدَ","number":4420},{"key":"kubranasai","label":"َالنَّسَائِيُّ فِي الْكُبْرَى","number":7297,"lafz":true,"n":7165},{"key":"sh21108","label":"َالطَّحَاوِيُّ فِي مُشْكِلِهِ","number":434},{"key":"sh22547","label":"الطحاوي في مشكله","number":434}],"full":1},{"num":6956,"demo":false,"sanad":"","matn":["عن بريدة بن الحصيب أن ماعز بن مالك الأسلمي أتى رسول الله صلى الله عليه وسلم فقال: يا رسول الله! إني قد ظلمت نفسي وزنيت وإني أريد أن تطهرني. فرده. فلما كان من الغد أتاه فقال: يا رسول الله! إني قد زنيت. فرده الثانية. فأرسل رسول الله صلى الله عليه وسلم إلى قومه فقال: أتعلمون بعقله بأساً تنكرون منه شيئاً؟ فقالوا: ما نعلمه إلا وفي العقل. من صالحينا. فيما نرى. فأتاه الثالثة فأرسل إليهم أيضا فسأل عنه فأخبروه: أنه لا بأس به ولا بعقله. فلما كان الرابعة حفر له حفرة ثم أمر به فرجم.","قال: فجاءت الغامدية فقالت: يا رسول الله! إني قد زنيت فطهرني. وإنه ردها، فلما كان الغد قالت: يا رسول الله! لم تردني؟ لعلك أن تردني كما رددت ماعزاً. فوالله! إني لحبلى. قال: إما لا، فاذهبي حتى تلدي فلما ولدت أتته بالصبي في خرقة. قالت: هذا قد ولدته. قال: اذهبي فأرضعيه حتى تفطميه فلما فطمته أتته بالصبي في يده كسرة خبز. فقالت: هذا، يا نبي الله! قد فطمته، وقد أكل الطعام، فدفع الصبي إلى رجل من المسلمين. ثم أمر بها فحفر لها إلى صدرها، وأمر الناس فرجموها، فيقبل خالد بن الوليد بحجر، فرمى رأسها، فتنضّح الدم على وجه خالد، فسبها، فسمع نبي الله صلى الله عليه وسلم إياها، فقال: مهلا! يا خالد! فوالذي نفسي بيده! لقد تابت توبة، لو تابها صاحب مكس لغفر له ثم أمر بها فصلى عليها ودفنت."],"takhrij":"صحيح: رواه مسلم في الحدود (23:1695) من طريق عبد الله بن نمير، حدثنا من طريق عبد الله بن نمير، حدثنا بشير بن المهاجر، حدثنا عبدالله بن بريدة، عن أبيه، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في رجم ماعز بن مالك","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1695).","chapter_en":"What has come regarding the stoning of Māʿiz ibn Mālik","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Buraidah ibn al-Hasib said: Maʿiz ibn Malik al-Aslami came to the Messenger of Allah ﷺ and said: “O Messenger of Allah ﷺ, I have wronged myself and committed adultery, and I want you to purify me.” He turned him away. The next day he came again and said the same. The Messenger of Allah ﷺ sent to his people and said: “Do you find any defect in his intellect?” They said: We do not know anything wrong with him; he is among our righteous ones in intellect. He came a third time, and again they were asked and said the same. On the fourth time, the Prophet ﷺ dug a pit for him and ordered that he be stoned. Then the Ghamidiyyah woman came and said: “O Messenger of Allah ﷺ, I have committed adultery, so purify me.” He turned her away. The next day she said: “Why do you refuse me? Perhaps you will refuse me as you refused Maʿiz. By Allah, I am pregnant.” He said: “If that is so, then go until you give birth.” When she gave birth, she came with the child wrapped in cloth and said: “This is what I have given birth to.” He said: “Go and breastfeed him until you wean him.” When she weaned him, she brought him with a piece of bread in his hand and said: “I have weaned him and he is eating food.” He handed the child to a Muslim man, then ordered that she be dug up to her chest and the people stoned her. Khalid ibn al-Walid came forward with a stone and struck her head, and blood splattered onto his face, so he insulted her. The Prophet ﷺ heard him and said: “Gently, O Khalid! By the One in Whose hand is my soul, she has repented a repentance that if the tax collector (ṣāḥib maks) had repented it, he would have been forgiven.” Then he ordered that she be prayed over and buried."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"رَوَاهُ مُسْلِمٌ","number":23,"lafz":true}],"full":1,"dr":1},{"num":6957,"demo":false,"sanad":"","matn":["بْنِ بُرَيْدَةَ عَنْ أَبِيهِ، قَالَ جَاءَ مَاعِزُ بْنُ مَالِكٍ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ يَا رَسُولَ اللَّهِ طَهِّرْنِي. فَقَالَ وَيْحَكَ ارْجِعْ فَاسْتَغْفِرِ اللَّهَ وَتُبْ إِلَيْهِ. قَالَ فَرَجَعَ غَيْرَ بَعِيدٍ ثُمَّ جَاءَ فَقَالَ يَا رَسُولَ اللَّهِ طَهِّرْنِي. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَيْحَكَ ارْجِعْ فَاسْتَغْفِرِ اللَّهَ وَتُبْ إِلَيْهِ. قَالَ فَرَجَعَ غَيْرَ بَعِيدٍ ثُمَّ جَاءَ فَقَالَ يَا رَسُولَ اللَّهِ طَهِّرْنِي. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِثْلَ ذَلِكَ حَتَّى إِذَا كَانَتِ الرَّابِعَةُ قَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيمَ أُطَهِّرُكَ. فَقَالَ مِنَ الزِّنَى. فَسَأَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَبِهِ جُنُونٌ. فَأُخْبِرَ أَنَّهُ لَيْسَ بِمَجْنُونٍ. فَقَالَ أَشَرِبَ خَمْرًا. فَقَامَ رَجُلٌ فَاسْتَنْكَهَهُ فَلَمْ يَجِدْ مِنْهُ رِيحَ خَمْرٍ. قَالَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَزَنَيْتَ. فَقَالَ نَعَمْ. فَأَمَرَ بِهِ فَرُجِمَ فَكَانَ النَّاسُ فِيهِ فِرْقَتَيْنِ قَائِلٌ يَقُولُ لَقَدْ هَلَكَ لَقَدْ أَحَاطَتْ بِهِ خَطِيئَتُهُ وَقَائِلٌ يَقُولُ مَا تَوْبَةٌ أَفْضَلَ مِنْ تَوْبَةِ مَاعِزٍ أَنَّهُ جَاءَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَوَضَعَ يَدَهُ فِي يَدِهِ ثُمَّ قَالَ اقْتُلْنِي بِالْحِجَارَةِ - قَالَ - فَلَبِثُوا بِذَلِكَ يَوْمَيْنِ أَوْ ثَلاَثَةً ثُمَّ جَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُمْ جُلُوسٌ فَسَلَّمَ ثُمَّ جَلَسَ فَقَالَ اسْتَغْفِرُوا لِمَاعِزِ بْنِ مَالِكٍ. قَالَ فَقَالُوا غَفَرَ اللَّهُ لِمَاعِزِ بْنِ مَالِكٍ. - قَالَ - فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَقَدْ تَابَ تَوْبَةً لَوْ قُسِمَتْ بَيْنَ أُمَّةٍ لَوَسِعَتْهُمْ.","قال: ثم جاءته امرأة من غامد من الأزد فقالت: يا رسولَ الله طهّرني. فقال: ويحك! ارجعي فاستغفري الله وتوبي إليه فقالت: أراك تريد أن ترددني كما رددت ماعز بن مالك. قال: وما ذاك؟ قالت: إنها حبلى من الزنى. فقال: آنت؟ قالت: نعم، فقال لها: حتى تضعي ما في بطنك قال: فكفلها رجل من الأنصار حتى وضعت. قال: فأتى النبي صلى الله عليه وسلم فقال: قد وضعت الغامدية. فقال: إذاً لا نرجمها وندع ولدها صغيراً ليس له من يرضعه فقام رجل من الأنصار فقال: إليّ رضاعه، يا نبي الله، قال: فرجمها."],"takhrij":"صحيح: رواه مسلم في الحدود (22:1695) عن محمد بن العلاء الهمداني، حدثنا يحيى بن يعلى (هو ابن الحارث المحاربي) عن غيلان – وهو ابن جامع المحاربي – عن علقمة بن مرثد، عن سليمان بن بريدة، عن أبيه، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في رجم الغامدية","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1695/22).","chapter_en":"What has been reported regarding the stoning of the Ghamid woman","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Buraydah reported: Māʿiz ibn Mālik came to the Prophet ﷺ and said: “O Messenger of Allah ﷺ, purify me.” He said: “Woe to you! Go back, seek Allah’s forgiveness, and repent to Him.” He went only a short distance away, then returned and said: “O Messenger of Allah ﷺ, purify me.” The Messenger of Allah ﷺ again said: “Woe to you! Go back, seek Allah’s forgiveness, and repent to Him.” When he came for the fourth time, the Messenger of Allah ﷺ asked: “From what should I purify you?” He replied: “From adultery.” The Messenger of Allah ﷺ asked: “Is he insane?” He was informed that he was not insane. He then asked: “Has he drunk wine?” A man stood up and smelled his breath but found no odor of wine. The Messenger of Allah ﷺ asked: “Did you commit adultery?” He replied: “Yes.” So he ordered that he be stoned. The people then divided into two groups concerning him. One group said: “He has been destroyed; his sin has encompassed him.” The other said: “There is no repentance better than the repentance of Māʿiz. He came to the Prophet ﷺ, placed his hand in his hand, and said: ‘Kill me with stones.’” They continued discussing him for two or three days. Then the Messenger of Allah ﷺ came while they were sitting. He greeted them, sat down, and said: “Seek forgiveness for Māʿiz ibn Mālik.” They said: “May Allah forgive Māʿiz ibn Mālik.” The Messenger of Allah ﷺ said: “He has repented with a repentance which, if it were divided among an entire community, would suffice them.” Then a woman from Ghāmid, from the tribe of Azd, came to him and said: “O Messenger of Allah ﷺ, purify me.” He said: “Woe to you! Go back, seek Allah’s forgiveness, and repent to Him.” She said: “It seems that you want to send me back just as you sent Māʿiz ibn Mālik back.” He asked: “What is the matter?” She said: “I am pregnant from adultery.” He asked: “Are you?” She replied: “Yes.” He said: “Wait until you deliver what is in your womb.” A man from the Anṣār took responsibility for her until she gave birth.","He then came to the Prophet ﷺ and said: “The Ghāmidī woman has given birth.” The Prophet ﷺ said: “Then we cannot stone her and leave her child small with no one to nurse him.” A man from the Anṣār stood and said: “I will take responsibility for nursing him, O Prophet of Allah.” Then she was stoned."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1695,"lafz":true},{"key":"muslim","label":"مسلم في الحدود","number":22}],"full":1},{"num":6958,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، أَنَّ امْرَأَةً أَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: إِنِّي زَنَيْتُ فَأَقِمْ فِيَّ الْحَدَّ فَقَالَ: انْطَلِقِي حَتَّى تَفْطِمِي وَلَدَكِ فَلَمَّا فَطَمَتْ وَلَدَهَا أَتَتْ فَقَالَتْ: يَا رَسُولَ اللَّهِ إِنِّي زَنَيْتُ فَأَقِمْ فِيَّ الْحَدَّ فَقَالَ: هَاتِ مَنْ يَكْفُلُ وَلَدَكِ فَقَامَ رَجُلٌ فَقَالَ: أَنَا أَكْفُلُ وَلَدَهَا يَا رَسُولَ اللَّهِ، فَرَجَمَهَا."],"takhrij":"حسن: رواه النسائي في الكبرى (7149)، والدارقطني (3228)، والحاكم (4/364) كلهم من حديث أبي حمزة محمد بن ميمون المروزي السكري، عن إبراهيم الصائغ، عن أبي الزبير، عن جابر قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في رجم الغامدية","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i in al-Kubra (7149), al-Daraqutni (3228), and al-Hakim (4/364).","chapter_en":"What has been reported regarding the stoning of the Ghamid woman","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Jabir ibn Abdullah reported: A woman came to the Prophet ﷺ and said: “I committed adultery, so establish the legal punishment upon me.” He said: “Go until you wean your child.” After she had weaned her child, she returned and said: “O Messenger of Allah ﷺ, I committed adultery, so establish the legal punishment upon me.” He said: “Bring someone who will care for your child.” A man stood and said: “I will take care of her child, O Messenger of Allah ﷺ.” So he ordered that she be stoned."]}},"tuhfa":{},"refs":[{"key":"kubranasai","label":"النسائي في الكبرى","number":7149,"lafz":true},{"key":"sh9771","label":"الدار قطني","number":3228},{"key":"hakim","label":"المستدرك على الصحيحين","number":8084,"n":8090}],"full":1,"dr":1},{"num":6959,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ، بْنِ حُصَيْنٍ أَنَّ امْرَأَةً، مِنْ جُهَيْنَةَ أَتَتْ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهِيَ حُبْلَى مِنَ الزِّنَى فَقَالَتْ يَا نَبِيَّ اللَّهِ أَصَبْتُ حَدًّا فَأَقِمْهُ عَلَىَّ فَدَعَا نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلِيَّهَا فَقَالَ أَحْسِنْ إِلَيْهَا فَإِذَا وَضَعَتْ فَائْتِنِي بِهَا. فَفَعَلَ فَأَمَرَ بِهَا نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَشُكَّتْ عَلَيْهَا ثِيَابُهَا ثُمَّ أَمَرَ بِهَا فَرُجِمَتْ ثُمَّ صَلَّى عَلَيْهَا فَقَالَ لَهُ عُمَرُ تُصَلِّي عَلَيْهَا يَا نَبِيَّ اللَّهِ وَقَدْ زَنَتْ فَقَالَ لَقَدْ تَابَتْ تَوْبَةً لَوْ قُسِمَتْ بَيْنَ سَبْعِينَ مِنْ أَهْلِ الْمَدِينَةِ لَوَسِعَتْهُمْ وَهَلْ وَجَدْتَ تَوْبَةً أَفْضَلَ مِنْ أَنْ جَادَتْ بِنَفْسِهَا لِلَّهِ تَعَالَى."],"takhrij":"صحيح: رواه مسلم في الحدود (1696) عن أبي غسّان مالك بن عبدالواحد المسْمعي، حدثنا معاذ – يعني ابن هشام – حدثني أبي، عن يحيى بن أبي كثير، حدثني أبو قلابة، أن أبا المهلّب حدّثه عن عمران بن حصين، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في رجم الغامدية","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (Hadith 1696).","chapter_en":"What has been reported regarding the stoning of the Ghamid woman","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Imran ibn Husayn reported: A woman from Juhaynah came to the Prophet ﷺ while pregnant from adultery and said: “O Prophet of Allah, I have committed an offense deserving punishment, so carry it out upon me.” The Prophet ﷺ called her guardian and said: “Treat her kindly, and when she gives birth bring her to me.” He did so. Then the Prophet ﷺ ordered that her clothes be fastened tightly around her, after which he commanded that she be stoned. Then he prayed over her. Umar said to him: “O Prophet of Allah, do you pray over her while she committed adultery?” He replied: “She has repented with a repentance that, if divided among seventy people of Madinah, it would suffice them. Have you found any repentance better than that she gave herself for the sake of Allah the Exalted?”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1696,"lafz":true}],"full":1,"rep":[3739]},{"num":6960,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، وَزَيْدِ بْنِ خَالِدٍ، رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَنِ الأَمَةِ إِذَا زَنَتْ وَلَمْ تُحْصَنْ قَالَ إِذَا زَنَتْ فَاجْلِدُوهَا، ثُمَّ إِنْ زَنَتْ فَاجْلِدُوهَا، ثُمَّ إِنْ زَنَتْ فَاجْلِدُوهَا، ثُمَّ بِيعُوهَا وَلَوْ بِضَفِيرٍ.","قال ابن شهاب: \"لا أدري أبعد الثالثة أو الرابعة\"."],"takhrij":"متفق عليه: رواه مالك في الحدود (14) عن ابن شهاب، عن عبيد الله بن عبد الله بن عتبة بن مسعود، عن أبي هريرة، وزيد بن خالد الجهني، فذكراه.","grade":"متفق عليه","chapter_ar":"باب ما جاء أن للسيد إقامة الحد على رقيقه بأمر من السلطان","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (14), al-Bukhari (6837, 6838), and Muslim (1703).","chapter_en":"What has been reported that a master may carry out the legal punishment on his slave by order of the ruler","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah and Zayd ibn Khalid al-Juhani reported that the Messenger of Allah ﷺ was asked about a slave woman who commits adultery while unmarried. He said: “If she commits adultery, then flog her. Then if she commits adultery again, flog her. Then if she commits adultery again, flog her. Then sell her even for a braided rope.” Ibn Shihab said: “I do not know whether that was after the third or fourth offense.”"]},"intro":{"ar":["قال اللّٰه تعالى: ﴿فَإِذَا أُحْصِنَّ فَإِنْ أَتَيْنَ بِفَاحِشَةٍ فَعَلَيْهِنَّ نِصْفُ مَا عَلَى الْمُحْصَنَاتِ مِنَ الْعَذَابِ﴾ [النساء: ٢٥]","والعذاب هنا مائة جلدة.","وإحصان الأمة هنا بالمعنى الصحيح هو التزويج، والمحصنات بمعنى الحرة العفيفة، وأخطأ من جعل المحصنات ذات الأزواج لأن أول الآية ترد على هذا وهو قوله تعالى:","( وَمَن لَّمْ يَسْتَطِعْ مِنكُمْ طَوْلًا أَن يَنكِحَ ٱلْمُحْصَنَاتِ ٱلْمُؤْمِنَاتِ فَمِن مَّا مَلَكَتْ أَيْمَٰنُكُم ) [النساء: ٢٥]","أي الحرة العفيفة.","والآية تنص على الأمة المحصنة إذا زنت فعليها الحد، ووردت الأحاديث الصحيحة عامة في إقامة الحد على الإماء."],"en":["Allah the Exalted said:","“And if they are married and commit immorality, then upon them is half the punishment of free chaste women.” [Surat al-Nisa: 25]","The punishment here is one hundred lashes.","The correct meaning of “ihsan” regarding the slave woman here is marriage, and “al-muhsanat” means free chaste women. Those who interpreted it as married women are mistaken, because the beginning of the verse refutes that interpretation:","“And whoever among you cannot afford to marry free believing women, then marry from those whom your right hands possess.” [Surat al-Nisa: 25]","Meaning: free chaste women.","The verse states that if a married slave woman commits adultery, then the legal punishment applies to her, and authentic hadiths were also reported generally concerning carrying out the punishment upon slave women."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":14,"lafz":true},{"key":"bukhari","label":"البخاري","number":6837},{"key":"muslim","label":"مسلم","number":32}],"full":1,"dr":1},{"num":6961,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّهُ سَمِعَهُ يَقُولُ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا زَنَتِ الأَمَةُ فَتَبَيَّنَ زِنَاهَا فَلْيَجْلِدْهَا وَلاَ يُثَرِّبْ، ثُمَّ إِنْ زَنَتْ فَلْيَجْلِدْهَا وَلاَ يُثَرِّبْ، ثُمَّ إِنْ زَنَتِ الثَّالِثَةَ فَلْيَبِعْهَا وَلَوْ بِحَبْلٍ مِنْ شَعَرٍ."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6839) ومسلم في الحدود (30:1703) كلاهما من طريق الليث (هو ابن سعد)، عن سعيد بن أبي سعيد المقبري، عن أبيه، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء أن للسيد إقامة الحد على رقيقه بأمر من السلطان","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6839) and Muslim (1703).","chapter_en":"What has been reported that a master may carry out the legal punishment on his slave by order of the ruler","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah reported that he heard the Prophet ﷺ say: “If a slave woman commits adultery and her adultery becomes clear, then let her be flogged and not rebuked harshly. Then if she commits adultery again, let her be flogged and not rebuked harshly. Then if she commits adultery a third time, let her be sold even for a rope made of hair.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6839,"lafz":true},{"key":"muslim","label":"مسلم","number":30}],"full":1},{"num":6962,"demo":false,"sanad":"","matn":["عَنْ أَبِي عَبْدِ الرَّحْمَنِ، قَالَ خَطَبَ عَلِيٌّ فَقَالَ يَا أَيُّهَا النَّاسُ أَقِيمُوا عَلَى أَرِقَّائِكُمُ الْحَدَّ مَنْ أَحْصَنَ مِنْهُمْ وَمَنْ لَمْ يُحْصِنْ فَإِنَّ أَمَةً لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ زَنَتْ فَأَمَرَنِي أَنْ أَجْلِدَهَا فَإِذَا هِيَ حَدِيثُ عَهْدٍ بِنِفَاسٍ فَخَشِيتُ إِنْ أَنَا جَلَدْتُهَا أَنْ أَقْتُلَهَا فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ أَحْسَنْتَ."],"takhrij":"صحيح (دون قوله: فإنَّ أمة لرسول الله زَنَتْ): رواه مسلم في الحدود (1706) عن محمد بن أبي بكر المقدمي، حدثنا سليمان أبو داود، حدثنا زائدة، عن السدي، عن سعد بن عبيدة، عن أبي عبدالرحمن فذكره. وفي رواية زاد: اتركها حتى تماثل","grade":"صحيح","chapter_ar":"باب ما جاء أن للسيد إقامة الحد على رقيقه بأمر من السلطان","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1706).","chapter_en":"What has been reported that a master may carry out the legal punishment on his slave by order of the ruler","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Abu Abd al-Rahman reported: Ali delivered a sermon and said: “O people, carry out the legal punishment upon your slaves, whether married or unmarried. A slave woman belonging to the Messenger of Allah ﷺ committed adultery, and he ordered me to flog her. But she had recently given birth, so I feared that if I flogged her I might kill her. I mentioned that to the Prophet ﷺ and he said: ‘You did well.’” In another narration he added: “Leave her until she recovers.”"]},"buhuth":{"en":["Commentary:","The statement: “Carry out the legal punishment upon your slaves” apparently is inserted from the words of Ali and is not directly raised to the Prophet ﷺ, but it carries the ruling of a raised narration because the Messenger of Allah ﷺ appointed Ali to flog the slave woman who committed adultery.","The slave girl did not belong to the Messenger of Allah ﷺ himself; rather, she belonged to some of his relatives, because Allah purified the household of the Prophet ﷺ from impurity, as narrated by Abu Dawud (4473), Ahmad (679), and al-Bayhaqi (8/245), all through the route of Abd al-Aʿla al-Thaʿlabi from Abu Jamilah from Ali may Allah be pleased with him who said: “A slave girl belonging to the family of the Messenger of Allah ﷺ committed adultery.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1706,"lafz":true,"n":4450}],"full":1,"dr":1},{"num":6963,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، وَزَيْدِ بْنِ خَالِدٍ، أَنَّهُمَا أَخْبَرَاهُ أَنَّ رَجُلَيْنِ اخْتَصَمَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ أَحَدُهُمَا اقْضِ بَيْنَنَا بِكِتَابِ اللَّهِ. وَقَالَ الآخَرُ وَهْوَ أَفْقَهُهُمَا أَجَلْ يَا رَسُولَ اللَّهِ فَاقْضِ بَيْنَنَا بِكِتَابِ اللَّهِ، وَأْذَنْ لِي أَنْ أَتَكَلَّمَ. قَالَ تَكَلَّمْ. قَالَ إِنَّ ابْنِي كَانَ عَسِيفًا عَلَى هَذَا ـ قَالَ مَالِكٌ وَالْعَسِيفُ الأَجِيرُ ـ فَزَنَى بِامْرَأَتِهِ، فَأَخْبَرُونِي أَنَّ عَلَى ابْنِي الرَّجْمَ، فَافْتَدَيْتُ مِنْهُ بِمِائَةِ شَاةٍ وَبِجَارِيَةٍ لِي، ثُمَّ إِنِّي سَأَلْتُ أَهْلَ الْعِلْمِ فَأَخْبَرُونِي أَنَّ مَا عَلَى ابْنِي جَلْدُ مِائَةٍ وَتَغْرِيبُ عَامٍ، وَإِنَّمَا الرَّجْمُ عَلَى امْرَأَتِهِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَا وَالَّذِي نَفْسِي بِيَدِهِ لأَقْضِيَنَّ بَيْنَكُمَا بِكِتَابِ اللَّهِ، أَمَّا غَنَمُكَ وَجَارِيَتُكَ فَرَدٌّ عَلَيْكَ. وَجَلَدَ ابْنَهُ مِائَةً وَغَرَّبَهُ عَامًا، وَأَمَرَ أُنَيْسًا الأَسْلَمِيَّ أَنْ يَأْتِيَ امْرَأَةَ الآخَرِ، فَإِنِ اعْتَرَفَتْ فَارْجُمْهَا، فَاعْتَرَفَتْ فَرَجَمَهَا."],"takhrij":"متفق عليه: رواه مالك في الحدود (6) عن ابن شهاب، عن عبيد الله بن عبد الله بن عتبة بن مسعود، عن أبي هريرة، وزيد بن خالد الجهني فذكراه.","grade":"متفق عليه","chapter_ar":"باب حد الزاني البكر جلد مائة وتغريب عام","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (6), al-Bukhari (6842, 6843), and Muslim (1697, 1698).","chapter_en":"The legal punishment for the unmarried adulterer: one hundred lashes and exile for one year","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah and Zayd ibn Khalid al-Juhani reported: Two men brought a dispute before the Messenger of Allah ﷺ. One of them said: “O Messenger of Allah ﷺ, judge between us according to the Book of Allah.” The other, who was more knowledgeable, said: “Yes, O Messenger of Allah ﷺ, judge between us according to the Book of Allah, and permit me to speak.” He said: “Speak.” He said: “My son was a laborer working for this man, and he committed adultery with his wife. I was informed that my son deserved stoning, so I ransomed him with one hundred sheep and a servant girl of mine. Then I asked the people of knowledge, and they informed me that my son only deserved one hundred lashes and exile for one year, while stoning applied only to the woman.” The Messenger of Allah ﷺ said: “By the One in whose hand is my soul, I will judge between you according to the Book of Allah. Your sheep and servant girl are to be returned to you.” He then ordered that the son be lashed one hundred times and exiled for one year. He also ordered Unays al-Aslami to go to the other man’s wife and said: “If she confesses, then stone her.” She confessed, so she was stoned."]},"intro":{"ar":["قال اللّٰه تعالى: ﴿الزَّانِيَةُ وَالزَّانِي فَاجْلِدُوا كُلَّ وَاحِدٍ مِنْهُمَا مِائَةَ جَلْدَةٍ﴾ [النور: ٢]"],"en":["Allah the Exalted said:","“The female fornicator and the male fornicator — lash each one of them with one hundred lashes.” [Surat al-Nur: 2]"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":6,"lafz":true},{"key":"bukhari","label":"البخاري","number":6842},{"key":"muslim","label":"مسلم","number":1697}],"full":1,"dr":1,"rep":[12837]},{"num":6964,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ، قَالَ سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُ فِيمَنْ زَنَى وَلَمْ يُحْصَنْ جَلْدَ مِائَةٍ وَتَغْرِيبَ عَامٍ.","قال ابن شهاب: وأخبرني عروة بن الزبير: أن عمر بن الخطاب غرّب، ثم لم تزل تلك السنة."],"takhrij":"صحيح: رواه البخاري في الحدود (6832،6831) عن مالك بن إسماعيل، حدثنا عبد العزيز (هو ابن سلمة الماجشون)، أخبرنا ابن شهاب، عن عبيد الله بن عبد الله بن عتبة، عن زيد بن خالد الجهني، فذكره.","grade":"صحيح","chapter_ar":"باب حد الزاني البكر جلد مائة وتغريب عام","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6831, 6832).","chapter_en":"The legal punishment for the unmarried adulterer: one hundred lashes and exile for one year","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Zayd ibn Khalid al-Juhani said: I heard the Prophet ﷺ command regarding one who committed adultery while unmarried: “One hundred lashes and exile for one year.” Ibn Shihab said: ʿUrwah ibn al-Zubayr informed me that Umar ibn al-Khattab carried out exile, and that practice continued thereafter."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6831,"lafz":true},{"key":"bukhari","label":"البخاري في الحدود","number":6832}],"full":1,"dr":1},{"num":6965,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ، أَنَّهُ قَالَ سَمِعْتُ عُمَرَ بْنَ الْخَطَّابِ، يَقُولُ الرَّجْمُ فِي كِتَابِ اللَّهِ حَقٌّ عَلَى مَنْ زَنَى مِنَ الرِّجَالِ وَالنِّسَاءِ إِذَا أُحْصِنَ إِذَا قَامَتِ الْبَيِّنَةُ أَوْ كَانَ الْحَبَلُ أَوْ الاِعْتِرَافُ."],"takhrij":"متفق عليه: رواه مالك في الحدود (8) عن ابن شهاب، عن عبيد الله بن عبد الله بن عتبة بن مسعود، عن عبد الله بن عباس، فذكره.","grade":"متفق عليه","chapter_ar":"باب لا يُقام حد الزنا إلا بالاعتراف أو البينة أو الحمل","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (8), and also narrated by al-Bukhari and Muslim through other chains.","chapter_en":"The punishment for adultery is not carried out except through confession, clear evidence, or pregnancy","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["Ibn Abbas reported: I heard Umar ibn al-Khattab say: “Stoning is a true ruling in the Book of Allah upon married men and women who commit adultery, when evidence is established, or there is pregnancy, or confession.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":8,"lafz":true}],"full":1,"dr":1},{"num":6966,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَوْ كُنْتُ رَاجِمًا أَحَدًا بِغَيْرِ بَيِّنَةٍ لَرَجَمْتُ فُلاَنَةَ فَقَدْ ظَهَرَ فِيهَا الرِّيبَةُ فِي مَنْطِقِهَا وَهَيْئَتِهَا وَمَنْ يَدْخُلُ عَلَيْهَا."],"takhrij":"صحيح: رواه ابن ماجة (2559) عن العباس بن الوليد الدمشقي، قال: حدثنا زيد بن يحيى بن عبيد، قال: حدثنا الليث بن سعد، عن عبيد الله بن أبي جعفر، عن أبي الأسود، عن عروة، عن ابن عباس فذكره وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب لا يُقام حد الزنا إلا بالاعتراف أو البينة أو الحمل","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2559).","chapter_en":"The punishment for adultery is not carried out except through confession, clear evidence, or pregnancy","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["Ibn Abbas reported that the Messenger of Allah ﷺ said: “If I were to stone anyone without clear evidence, I would have stoned that woman. Suspicion had become apparent from her speech, her appearance, and those who entered upon her.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2559,"lafz":true}],"full":1},{"num":6967,"demo":false,"sanad":"","matn":["عَنِ الْقَاسِمِ بْنِ مُحَمَّدٍ، قَالَ قَالَ عَبْدُ اللَّهِ بْنُ شَدَّادٍ وَذُكِرَ الْمُتَلاَعِنَانِ عِنْدَ ابْنِ عَبَّاسٍ فَقَالَ ابْنُ شَدَّادٍ أَهُمَا اللَّذَانِ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَوْ كُنْتُ رَاجِمًا أَحَدًا بِغَيْرِ بَيِّنَةٍ لَرَجَمْتُهَا. فَقَالَ ابْنُ عَبَّاسٍ لاَ تِلْكَ امْرَأَةٌ أَعْلَنَتْ.","وفي رواية: لا، تلك امرأة كانت تظهر في الإسلام السوء."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6855) ومسلم في اللعان (13:1497) كلاهما من طريق سفيان بن عيينة، حدّثنا أبو الزناد، عن القاسم بن محمد، به.","grade":"متفق عليه","chapter_ar":"باب لا يُقام حد الزنا إلا بالاعتراف أو البينة أو الحمل","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6855) and Muslim (1497).","chapter_en":"The punishment for adultery is not carried out except through confession, clear evidence, or pregnancy","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["Al-Qasim ibn Muhammad reported: Abdullah ibn Shaddad mentioned the two people involved in mutual cursing before Ibn Abbas. Ibn Shaddad said: “Are these the two about whom the Prophet ﷺ said: ‘If I were to stone anyone without evidence, I would have stoned them?’” Ibn Abbas replied: “No, that was a woman who openly displayed immorality.” In another narration: “No, that was a woman who openly displayed evil in Islam.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6855,"lafz":true},{"key":"muslim","label":"مسلم","number":13}],"full":1,"dr":1},{"num":6968,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ، قَالَ قَالَ سَعْدُ بْنُ عُبَادَةَ لَوْ رَأَيْتُ رَجُلاً مَعَ امْرَأَتِي لَضَرَبْتُهُ بِالسَّيْفِ غَيْرَ مُصْفَحٍ. فَبَلَغَ ذَلِكَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ أَتَعْجَبُونَ مِنْ غَيْرَةِ سَعْدٍ، لأَنَا أَغْيَرُ مِنْهُ، وَاللَّهُ أَغْيَرُ مِنِّي."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6846) ومسلم في اللعان (17:1499) من طريق أبي عوانة، حدثنا عبد الله بن نمير، عن ورّاد كاتب المغيرة، عن المغيرة بن شعبة، قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب من وجد مع امرأته رجلاً لا يقتله حتى يبلغ السلطان","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6846) and Muslim (1499).","chapter_en":"Whoever finds a man with his wife should not kill him until the matter reaches the ruler","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["Al-Mughirah ibn Shuʿbah reported: Saʿd ibn ʿUbadah said: “If I saw a man with my wife, I would strike him with the sword, not with the flat side.” That reached the Prophet ﷺ, who said: “Are you amazed at the protective jealousy of Saʿd? By Allah, I have more protective jealousy than him, and Allah has more protective jealousy than me.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6846,"lafz":true},{"key":"muslim","label":"مسلم","number":17}],"full":1,"rep":[10205]},{"num":6969,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ سَعْدُ بْنُ عُبَادَةَ يَا رَسُولَ اللَّهِ لَوْ وَجَدْتُ مَعَ أَهْلِي رَجُلاً لَمْ أَمَسَّهُ حَتَّى آتِيَ بِأَرْبَعَةِ شُهَدَاءَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَعَمْ. قَالَ كَلاَّ وَالَّذِي بَعَثَكَ بِالْحَقِّ إِنْ كُنْتُ لأُعَاجِلُهُ بِالسَّيْفِ قَبْلَ ذَلِكَ. قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اسْمَعُوا إِلَى مَا يَقُولُ سَيِّدُكُمْ إِنَّهُ لَغَيُورٌ وَأَنَا أَغْيَرُ مِنْهُ وَاللَّهُ أَغْيَرُ مِنِّي."],"takhrij":"صحيح: رواه مسلم في اللعان (16:1498) عن أبي بكر بن أبي شيبة، حدثنا خالد بن مخلد، عن سليمان بن بلال، حدثني سهيل، عن أبيه، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب من وجد مع امرأته رجلاً لا يقتله حتى يبلغ السلطان","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1498).","chapter_en":"Whoever finds a man with his wife should not kill him until the matter reaches the ruler","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["Abu Hurayrah reported: Saʿd ibn ʿUbadah said: “O Messenger of Allah ﷺ, if I found a man with my wife, would I not touch him until I brought four witnesses?” The Messenger of Allah ﷺ said: “Yes.” Saʿd said: “No! By the One who sent you with the truth, I would hasten against him with the sword before that.” The Messenger of Allah ﷺ said: “Listen to what your leader says. He possesses protective jealousy, and I have more protective jealousy than him, and Allah has more protective jealousy than me.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":16,"lafz":true}],"full":1,"dr":1,"rep":[10206,12845]},{"num":6970,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ سَعْدَ بْنَ عُبَادَةَ، قَالَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَرَأَيْتَ لَوْ أَنِّي وَجَدْتُ مَعَ امْرَأَتِي رَجُلاً أَأُمْهِلُهُ حَتَّى آتِيَ بِأَرْبَعَةِ شُهَدَاءَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَعَمْ."],"takhrij":"صحيح: رواه مالك في الحدود (7) عن سهيل بن أبي صالح، عن أبيه، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب من وجد مع امرأته رجلاً لا يقتله حتى يبلغ السلطان","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (7) and Muslim (1498).","chapter_en":"Whoever finds a man with his wife should not kill him until the matter reaches the ruler","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["Abu Hurayrah reported that Saʿd ibn ʿUbadah said to the Messenger of Allah ﷺ: “If I found a man with my wife, should I wait until I bring four witnesses?” The Messenger of Allah ﷺ replied: “Yes.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":7,"lafz":true},{"key":"muslim","label":"مسلم","number":15}],"full":1,"dr":1},{"num":6971,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ رَجُلاً أَتَاهُ فَأَقَرَّ عِنْدَهُ أَنَّهُ زَنَى بِامْرَأَةٍ سَمَّاهَا لَهُ فَبَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْمَرْأَةِ فَسَأَلَهَا عَنْ ذَلِكَ فَأَنْكَرَتْ أَنْ تَكُونَ زَنَتْ فَجَلَدَهُ الْحَدَّ وَتَرَكَهَا."],"takhrij":"حسن: رواه أبو داود (4466،4437) عن عثمان بن أبي شيبة، ثنا طلق بن غنام، ثنا عبد السلام بن حفص، ثنا أبو حازم، عن سهل بن سعد فذكره ومن طريقه رواه البيهقي (8/228).","grade":"حسن","chapter_ar":"باب الرجل يُقِرُّ بالزنا دون المرأة","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4437, 4466) and al-Bayhaqi (8/228).","chapter_en":"A man confesses to adultery while the woman does not","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["Sahl ibn Saʿd reported that a man came to the Prophet ﷺ and confessed before him that he had relations with a woman whom he named. The Messenger of Allah ﷺ sent for the woman and asked her about it, but she denied having committed adultery. So he carried out the punishment upon the man and left her."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4437,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":228},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":17002,"n":17160},{"key":"abudawud","label":"ابو داود","number":4466}],"full":1,"dr":1},{"num":6972,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ بْنِ سهل بْنِ حُنَيْفٍ قَالَ: أَخْبَرَنِي بَعْضُ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الأَنْصَارِ أَنَّهُ اشْتَكَى رَجُلٌ مِنْهُمْ حَتَّى أُضْنيَ فَعَادَ جلده عَلَى عظْمٍ. فَدَخَلَتْ جَارِيَةٌ لِبَعْضِهِمْ، فهشّ إِلَيْهَا، فَوَقَعَ عَلَيْهَا. فَلَمَّا دَخَلَ عَلَيْهِ رِجَالُ مِنَ قَوْمِهِ يَعُودُونَهُ أَخْبَرَهُمْ بِذَلِكَ. وَقَالَ: اسْتَفْتُوا لِي رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَإِنِّي قَدْ وَقَعْتُ عَلَى جَارِيَةٍ دَخَلَتْ عليّ. فَذَكَرُوا ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: يَا رَسُولَ اللَّهِ مَا رَأَيْنَا بِأَحَدٍ مِنَ النَّاسِ مِنَ الضُّر مِثْلَ الَّذِي هُوَ بِهِ، لَوْ حملنا إِلَيْكَ لَتَفَسَّخَتْ عِظَامُهُ مَا هُوَ إِلاَّ جِلْدٌ عَلَى عظْم. فَأَمَرَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمِائَةِ شِمراخٍ، فيضربونه ضَرْبَةً وَاحِدَةً."],"takhrij":"صحيح: رواه أبو داود (4472) وابن الجارود (817) كلاهما من طريقين عن يونس، عن ابن شهاب، أخبرني أبو أمامة بن سهل بن حُنيف فذكر مثله. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب إقامة الحد على المريض","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (4472) and Ibn al-Jarud (817).","chapter_en":"Carrying out the legal punishment upon the sick person","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["Abu Umamah ibn Sahl ibn Hunayf reported: Some companions of the Messenger of Allah ﷺ from the Ansar informed me that a man among them became severely ill until his skin clung to his bones. A slave girl entered upon him, and he desired her and had relations with her. When some men from his people visited him, he informed them of what had happened and said: “Ask the Messenger of Allah ﷺ for a ruling regarding me, for I had relations with a slave girl who entered upon me.” They mentioned this to the Messenger of Allah ﷺ and said: “O Messenger of Allah ﷺ, we have never seen anyone in such hardship as him. If we carried him to you, his bones would break apart; he is nothing but skin over bone.” So the Messenger of Allah ﷺ ordered them to take one hundred palm stalks and strike him once with them."]},"buhuth":{"en":["The phrase “uḍni” means that he was afflicted with severe illness and weakness until his body wasted away."]},"intro":{"ar":["قال تعالى مخاطباً لأيوب عليه السلام: ﴿وَخُذْ بِيَدِكَ ضِغْثًا فَاضْرِبْ بِهِ وَلَا تَحْنَثْ﴾ [ص: ٤٤]"],"en":["Allah the Exalted said, addressing Ayyub peace be upon him:","“And take in your hand a bundle and strike with it, and do not break your oath.” [Surat Sad: 44]"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4472,"lafz":true},{"key":"sh13071","label":"ابن الجارود","number":817,"n":850}],"full":1,"dr":1},{"num":6973,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ وَجَدْتُمُوهُ يَعْمَلُ عَمَلَ قَوْمِ لُوطٍ فَاقْتُلُوا الْفَاعِلَ وَالْمَفْعُولَ بِهِ."],"takhrij":"حسن: رواه أبو داود (4462) والترمذي (1456) وابن ماجة (2561) وابن الجارود (820) وأحمد (2732) والحاكم (4/355) والبيهقي (8/232) كلهم من حديث عمرو بن أبي عمرو، عن عكرمة، عن ابن عباس فذكره وزاد الحاكم إتيان البهيمة كما سيأتي ذكره وقال: صحيح الإسناد.","grade":"حسن","chapter_ar":"باب ما جاء في حد من يعمل عمل قوم لوط","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4462), al-Tirmidhi (1456), Ibn Majah (2561), Ibn al-Jarud (820), and Ahmad (2732).","chapter_en":"What has been reported regarding the punishment of one who commits the act of the people of Lut","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":13,"content":{"translation":{"en":["Abdullah ibn Abbas reported that the Messenger of Allah ﷺ said: “Whoever you find committing the act of the people of Lut, then kill the one who does it and the one to whom it is done.”"]},"intro":{"ar":["قال اللّٰه تعالى: ﴿وَلُوطًا إِذْ قَالَ لِقَوْمِهِ أَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُمْ بِهَا مِنْ أَحَدٍ مِنَ الْعَالَمِينَ ۝ إِنَّكُمْ لَتَأْتُونَ الرِّجَالَ شَهْوَةً مِنْ دُونِ النِّسَاءِ بَلْ أَنْتُمْ قَوْمٌ مُسْرِفُونَ﴾ [الأعراف: ٨٠-٨١]","وقال في نزول العذاب عليهم: ﴿فَلَمَّا جَاءَ أَمْرُنَا جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِنْ سِجِّيلٍ مَنْضُودٍ ۝ مُسَوَّمَةً عِنْدَ رَبِّكَ وَمَا هِيَ مِنَ الظَّالِمِينَ بِبَعِيدٍ﴾ [هود: ٨٢-٨٣]"],"en":["Allah the Exalted said:","“And Lut, when he said to his people: ‘Do you commit such immorality as none in the worlds has preceded you in? Indeed, you approach men with desire instead of women. Rather, you are a transgressing people.’” [Surat al-Aʿraf: 80–81]","And regarding the punishment that descended upon them:","“So when Our command came, We turned the city upside down and rained upon them stones of baked clay, layered one upon another, marked from your Lord; and they are not far from the wrongdoers.” [Surat Hud: 82–83]"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4462,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1456},{"key":"ibnmajah","label":"ابن ماجه","number":2561},{"key":"sh13071","label":"ابن الجارود","number":820,"n":853},{"key":"ahmad","label":"مسند الإمام أحمد","number":2732,"n":2732}],"full":1,"dr":1},{"num":6974,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: مَرَّ عَلِيُّ بْنُ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ بِمَجْنُونَةِ بَنِي فُلَانٍ قَدْ زَنَتْ، أَمَرَ عُمَرُ بِرَجْمِهَا فَرَدَّهَا عَلِيٌّ وَقَالَ لِعُمَرَ: يَا أَمِيرَ الْمُؤْمِنِينَ، أَتَرْجُمُ هَذِهِ؟ قَالَ: نَعَمْ، قَالَ: أَوَ مَا تَذْكُرُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: رُفِعَ الْقَلَمُ عَنْ ثَلَاثَةٍ: عَنِ الْمَجْنُونِ الْمَغْلُوبِ عَلَى عَقْلِهِ، وَعَنِ النَّائِمِ حَتَّى يَسْتَيْقِظَ، وَعَنِ الصَّبِيِّ حَتَّى يَحْتَلِمَ؟ قَالَ: صَدَقْتَ، فَخَلَّى عَنْهَا."],"takhrij":"صحيح: رواه أبو داود (4401) وصحَّحه ابن خزيمة (1003) وابن حبان (143) والحاكم (4/389) وعنه البيهقي (8/264) كلهم من حديث جرير بن حازم، عن الأعمش، عن أبي ظبيان، عن ابن عباس فذكره. وإسناده صحيح. ورواه شعبة وابن نمير عن الأعمش موقوفا والحكم لمن زاد.","grade":"صحيح","chapter_ar":"باب درء الحد عن المجنونة","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4401), and authenticated by Ibn Khuzaymah (1003), Ibn Ḥibbān (143), and al-Ḥākim (4/389).","chapter_en":"Preventing the legal punishment from being carried out upon the insane woman","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Ibn ʿAbbās reported: ʿAlī ibn Abī Ṭālib passed by an insane woman from a certain tribe who had committed adultery. ʿUmar had ordered that she be stoned. ʿAlī had her brought back and said to ʿUmar: “O Commander of the Believers, will you stone this woman?” He replied: “Yes.” ʿAlī said: “Do you not remember that the Messenger of Allah ﷺ said: ‘The pen has been lifted from three: from the insane person whose reason is overcome, from the sleeping person until he awakens, and from the child until he reaches puberty’?” ʿUmar said: “You are correct.” So he released her."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4401,"lafz":true},{"key":"ibnkhuzaymah","label":"صححه ابن خزيمة","number":1003},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":3749,"n":3745},{"key":"hakim","label":"المستدرك على الصحيحين","number":949,"n":943},{"key":"ibnhibban","label":"ابن حبان","number":143}],"full":1,"dr":1},{"num":6975,"demo":false,"sanad":"","matn":["عَنْ وَائِلِ بْنِ حُجْرٍ قَالَ: خَرَجَتْ امْرَأَةً إِلَى الصَّلاَةَ، فلقيها رَجُلٌ، فَتَجَلَّلَهَا بثيابه، فَقَضَى حَاجَتَهُ مِنْهَا، فَصَاحَتْ، فَانْطَلَقَ. وَمَرَّ عَلَيْهَا رَجُلٌ فَقَالَتْ: إِنَّ ذَاكَ الرَّجُلَ فَعَلَ بِي كَذَا وَكَذَا. وَمَرَّتْ بِعِصَابَةٍ مِنَ الْمُهَاجِرِينَ. فَقَالَتْ: إِنَّ ذَاكَ الرَّجُلَ فَعَلَ بِي كَذَا وَكَذَا. فَانْطَلَقُوا فَأَخَذُوا الرَّجُلَ الَّذِي ظنّت أَنَّهُ وَقَعَ عَلَيْهَا وَأَتَوْهَا. فَقَالَتْ: نَعَمْ هُوَ هَذَا. فَأَتَوْا بِهِ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ . فَلَمَّا أَمَرَ بِهِ لِيُرْجَمَ قَامَ صَاحِبُهَا الَّذِي وَقَعَ عَلَيْهَا. فَقَالَ: يَا رَسُولَ اللَّهِ! أَنَا صَاحِبُهَا. فَقَالَ لَهَا: اذْهَبِي فَقَدْ غَفَرَ اللَّهُ لَكِ وَقَالَ لِلرَّجُلِ قَوْلاً حَسَنًا، فَقِيلَ: يَا نَبِيَّ! ألا ترجمه؟ فَقَالَ: لَقَدْ تَابَ تَوْبَةً لَوْ تَابَهَا أَهْلُ الْمَدِينَةِ لَقُبِلَ مِنْهُمْ."],"takhrij":"حسن: رواه أبو داود (4379) والترمذي (1454) وأحمد (27240) وابن الجارود في المنتقى (823) والبيهقي (8/284-285) كلهم من طريق سماك بن حرب، عن علقمة بن وائل، عن أبيه وائل بن حجر فذكره.","grade":"حسن","chapter_ar":"باب درء الحد عن المجنونة","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4379), al-Tirmidhi (1454), and Ahmad (27240).","chapter_en":"Preventing the legal punishment from being carried out upon the insane woman","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد الزنا","group_en":"Collection of Narrations Regarding the Punishment for Adultery","part_no":33,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Wa’il ibn Hujr reported: A woman went out for prayer when a man encountered her, covered her with his garments, and forced himself upon her. She cried out and he fled. Another man passed by and she said: “That man did such-and-such to me.” Then she passed by a group of Muhajirun and said: “That man did such-and-such to me.” They went and seized the man whom she thought had assaulted her and brought him to her. She said: “Yes, this is him.” They then brought him to the Messenger of Allah ﷺ. When the Prophet ﷺ ordered that he be stoned, the actual perpetrator stood up and said: “O Messenger of Allah ﷺ, I am the one who did it.” The Prophet ﷺ said to the woman: “Go, for Allah has forgiven you.” He spoke kindly to the man, and it was said: “O Prophet of Allah, will you not stone him?” He replied: “He has repented with such a repentance that if the people of Madinah had repented likewise, it would have been accepted from them.”"]},"buhuth":{"en":["Al-Tirmidhi said: “Hasan, strange, and authentic.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4379,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1454},{"key":"ahmad","label":"مسند الإمام أحمد","number":27240,"n":27240},{"key":"sh13071","label":"ابن الجارود في المنتقي","number":823}],"full":1,"dr":1},{"num":6976,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ ـ رَضِيَ اللَّهُ عَنْهَا أَنَّ قُرَيْشًا، أَهَمَّتْهُمُ الْمَرْأَةُ الْمَخْزُومِيَّةُ الَّتِي سَرَقَتْ فَقَالُوا مَنْ يُكَلِّمُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَنْ يَجْتَرِئُ عَلَيْهِ إِلاَّ أُسَامَةُ حِبُّ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَكَلَّمَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ أَتَشْفَعُ فِي حَدٍّ مِنْ حُدُودِ اللَّهِ. ثُمَّ قَامَ فَخَطَبَ قَالَ يَا أَيُّهَا النَّاسُ إِنَّمَا ضَلَّ مَنْ قَبْلَكُمْ أَنَّهُمْ كَانُوا إِذَا سَرَقَ الشَّرِيفُ تَرَكُوهُ، وَإِذَا سَرَقَ الضَّعِيفُ فِيهِمْ أَقَامُوا عَلَيْهِ الْحَدَّ، وَايْمُ اللَّهِ لَوْ أَنَّ فَاطِمَةَ بِنْتَ مُحَمَّدٍ سَرَقَتْ لَقَطَعَ مُحَمَّدٌ يَدَهَا."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6788) ومسلم في الحدود (8:1688) كلاهما من طريق الليث، عن ابن شهاب، عن عروة، عن عائشة، فذكرته.","grade":"متفق عليه","chapter_ar":"باب التسوية بين الشريف والضعيف في إقامة الحدود","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6788) and Muslim (1688).","chapter_en":"Equality between the noble and the weak in carrying out legal punishments","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في حد السرقة","group_en":"Collection of Chapters Regarding the Legal Punishment for Theft","part_no":33,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["ʿA’ishah reported: Quraysh became greatly concerned about the Makhzumi woman who had stolen. They said: “Who will speak to the Messenger of Allah ﷺ about her? And who would dare except Usamah, the beloved of the Messenger of Allah ﷺ?” So Usamah spoke to the Messenger of Allah ﷺ, and he said: “Do you intercede concerning one of the limits set by Allah?” Then he stood and delivered a sermon, saying: “O people, those before you were only destroyed because when a noble person among them stole, they left him alone, but when a weak person stole, they carried out the punishment upon him. By Allah, if Fatimah the daughter of Muhammad stole, Muhammad would cut off her hand.”"]},"intro":{"ar":["قال اللّٰه تعالى: ﴿وَالسَّارِقُ وَالسَّارِقَةُ فَاقْطَعُوا أَيْدِيَهُمَا جَزَاءً بِمَا كَسَبَا نَكَالًا مِنَ اللَّهِ وَاللَّهُ عَزِيزٌ حَكِيمٌ﴾ [المائدة: ٣٨]"],"en":["Allah the Exalted said:","“As for the male thief and the female thief, cut off their hands as a recompense for what they earned, as a deterrent from Allah. And Allah is Almighty, All-Wise.” [Surat al-Ma’idah: 38]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6788,"lafz":true},{"key":"muslim","label":"مسلم","number":8}],"full":1,"dr":1},{"num":6977,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ كَانَتِ امْرَأَةٌ مَخْزُومِيَّةٌ تَسْتَعِيرُ الْمَتَاعَ وَتَجْحَدُهُ فَأَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تُقْطَعَ يَدُهَا فَأَتَى أَهْلُهَا أُسَامَةَ بْنَ زَيْدٍ فَكَلَّمُوهُ فَكَلَّمَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهَا. ثُمَّ ذَكَرَ نَحْوَ حَدِيثِ اللَّيْثِ وَيُونُسَ."],"takhrij":"صحيح: رواه مسلم في الحدود (10:1688) من طريق عبد الرزاق، أخبرنا معمر، عن الزهري، عن عروة، عن عائشة قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب التسوية بين الشريف والضعيف في إقامة الحدود","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1688).","chapter_en":"Equality between the noble and the weak in carrying out legal punishments","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في حد السرقة","group_en":"Collection of Chapters Regarding the Legal Punishment for Theft","part_no":33,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["The Mother of the Believers, ʿA’ishah, said: A Makhzumi woman used to borrow goods and deny having taken them, so the Prophet ﷺ ordered that her hand be cut off. Her family came to Usamah ibn Zayd and spoke to him, so he spoke to the Messenger of Allah ﷺ concerning her. Then he mentioned a narration similar to the hadith of al-Layth and Yunus."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":10,"lafz":true}],"full":1,"dr":1},{"num":6978,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: كَانَتْ مَخْزُومِيَّةٌ تَسْتَعِيرُ الْمَتَاعَ وَتَجْحَدُهُ، فَأَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَطْعِ يَدِهَا."],"takhrij":"صحيح: رواه أبو داود (4395) والنسائي (4887) وأحمد (6383) كلهم من طريق عبد الرزاق – وهو في المصنف (10/202) قال: حدثنا معمر، عن أيوب، عن نافع، عن ابن عمر فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب التسوية بين الشريف والضعيف في إقامة الحدود","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4395), al-Nasā’ī (4887), Aḥmad (6383), and ʿAbd al-Razzāq in al-Muṣannaf (10/202).","chapter_en":"Equality between the noble and the weak in carrying out legal punishments","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في حد السرقة","group_en":"Collection of Chapters Regarding the Legal Punishment for Theft","part_no":33,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar reported: A woman from Banū Makhzūm used to borrow goods and then deny having received them, and the Prophet ﷺ ordered that her hand be cut off."]},"buhuth":{"en":["The phrase “she used to borrow goods and then deny them” describes the woman’s conduct. It does not mean that her hand was cut off merely because she denied borrowed property. Rather, the correct understanding is that the punishment was imposed because of theft, as indicated by the preceding hadiths.","Accordingly, the majority of scholars held that if a borrower denies having received borrowed property, the hand is not cut off, because Allah prescribed cutting the hand for the thief, whereas such a person is considered a betrayer of trust rather than technically a thief."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4395,"lafz":true},{"key":"nasai","label":"النسائي","number":4887},{"key":"abdrazzaq","label":"عبد الرزاق في المصنف","number":10},{"key":"ahmad","label":"مسند الإمام أحمد","number":6383,"n":6383},{"key":"abdrazzaq","label":"المصنف لعبد الرزاق","number":20033,"n":20143}],"full":1,"dr":1},{"num":6979,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، أَنَّ امْرَأَةً، مِنْ بَنِي مَخْزُومٍ سَرَقَتْ فَأُتِيَ بِهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَعَاذَتْ بِأُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَاللَّهِ لَوْ كَانَتْ فَاطِمَةُ لَقَطَعْتُ يَدَهَا. فَقُطِعَتْ."],"takhrij":"صحيح: رواه مسلم في الحدود (1689) عن سلمة بن شبيب، حدّثنا الحسن بن أعين، حدّثنا معْقل، عن أبي الزبير، عن جابر، فذكره.","grade":"صحيح","chapter_ar":"باب التسوية بين الشريف والضعيف في إقامة الحدود","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1689).","chapter_en":"Equality between the noble and the weak in carrying out legal punishments","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في حد السرقة","group_en":"Collection of Chapters Regarding the Legal Punishment for Theft","part_no":33,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Jabir reported: A woman from Banu Makhzum stole, and she was brought to the Prophet ﷺ. She sought protection through Umm Salamah, the wife of the Prophet ﷺ. The Prophet ﷺ said: “By Allah, if it were Fatimah, I would cut off her hand.” So her hand was cut off."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1689,"lafz":true}],"full":1},{"num":6980,"demo":false,"sanad":"","matn":["عَنْ مُحَمَّدِ بْنِ طَلْحَةَ بْنِ رُكَانَةَ، عَنْ أُمِّهِ، عَائِشَةَ بِنْتِ مَسْعُودِ بْنِ الأَسْوَدِ عَنْ أَبِيهَا، قَالَ لَمَّا سَرَقَتِ الْمَرْأَةُ تِلْكَ الْقَطِيفَةَ مِنْ بَيْتِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَعْظَمْنَا ذَلِكَ وَكَانَتِ امْرَأَةً مِنْ قُرَيْشٍ فَجِئْنَا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نُكَلِّمُهُ وَقُلْنَا نَحْنُ نَفْدِيهَا بِأَرْبَعِينَ أُوقِيَّةً. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تُطَهَّرَ خَيْرٌ لَهَا. فَلَمَّا سَمِعْنَا لِينَ قَوْلِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَتَيْنَا أُسَامَةَ فَقُلْنَا كَلِّمْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَلَمَّا رَأَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَلِكَ قَامَ خَطِيبًا فَقَالَ مَا إِكْثَارُكُمْ عَلَىَّ فِي حَدٍّ مِنْ حُدُودِ اللَّهِ عَزَّ وَجَلَّ وَقَعَ عَلَى أَمَةٍ مِنْ إِمَاءِ اللَّهِ وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ لَوْ كَانَتْ فَاطِمَةُ ابْنَةُ رَسُولِ اللَّهِ نَزَلَتْ بِالَّذِي نَزَلَتْ بِهِ لَقَطَعَ مُحَمَّدٌ يَدَهَا."],"takhrij":"حسن: رواه ابن ماجة (2548) والحاكم (4/379-380) ومن طريقه البيهقي (8/281) كلهم من حديث محمد بن إسحاق، عن محمد بن طلحة بن شداد بن ركانة بإسناده مثله.","grade":"حسن","chapter_ar":"باب التسوية بين الشريف والضعيف في إقامة الحدود","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2548) and al-Hakim (8147).","chapter_en":"Equality between the noble and the weak in carrying out legal punishments","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في حد السرقة","group_en":"Collection of Chapters Regarding the Legal Punishment for Theft","part_no":33,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Muhammad ibn Talhah ibn Rukanah narrated from his mother ʿA’ishah bint Masʿud ibn al-Aswad, from her father, who said: When that woman stole the velvet cloth from the house of the Messenger of Allah ﷺ, we considered the matter grave. She was a woman from Quraysh, so we came to the Prophet ﷺ to speak to him and said: “We will ransom her with forty uqiyyahs.” The Messenger of Allah ﷺ said: “Her purification is better for her.” When we heard the gentleness in the speech of the Messenger of Allah ﷺ, we went to Usamah and said: “Speak to the Messenger of Allah ﷺ.” When the Messenger of Allah ﷺ saw that, he stood and delivered a sermon, saying: “Why do they repeatedly speak to me concerning one of the limits set by Allah, applied to one of Allah’s female servants? By the One in whose hand is my soul, if Fatimah the daughter of the Messenger of Allah ﷺ had done what this woman did, Muhammad would cut off her hand.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2548,"lafz":true},{"key":"hakim","label":"المستدرك على الصحيحين","number":8147,"n":8153}],"full":1,"dr":1},{"num":6981,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَعَنَ اللَّهُ السَّارِقَ، يَسْرِقُ الْبَيْضَةَ فَتُقْطَعُ يَدُهُ، وَيَسْرِقُ الْحَبْلَ فَتُقْطَعُ يَدُهُ."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6783) ومسلم في الحدود (1687) كلاهما من طريق الأعمش، عن أبي صالح، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب النّصاب الذي تقطع فيه يد السّارق","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6783) and Muslim (1687).","chapter_en":"The minimum amount for which the thief’s hand is cut off","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في حد السرقة","group_en":"Collection of Chapters Regarding the Legal Punishment for Theft","part_no":33,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “May Allah curse the thief who steals an egg and his hand is cut off, and steals a rope and his hand is cut off.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6783,"lafz":true},{"key":"muslim","label":"مسلم","number":1687}],"full":1,"dr":1},{"num":6982,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تُقْطَعُ الْيَدُ فِي رُبُعِ دِينَارٍ فَصَاعِدًا.","وفي لفظ: كان رسول الله صلى الله عليه وسلم يقطع السـارق في ربع دينار فصـاعداً."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6789) ومسلم في الحدود (1684) كلاهما من طريق الزهري، عن عمرة، عن عائشة، فذكرته.","grade":"متفق عليه","chapter_ar":"باب النّصاب الذي تقطع فيه يد السّارق","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6789) and Muslim (1684). The first wording is from al-Bukhari, and the second wording is from Muslim.","chapter_en":"The minimum amount for which the thief’s hand is cut off","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في حد السرقة","group_en":"Collection of Chapters Regarding the Legal Punishment for Theft","part_no":33,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["ʿA’ishah said: The Prophet ﷺ said: “The hand is cut off for a quarter of a dinar or more.” In another wording: “The Messenger of Allah ﷺ used to cut off the hand of the thief for a quarter of a dinar or more.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6789,"lafz":true},{"key":"muslim","label":"مسلم","number":1684}],"full":1,"dr":1},{"num":6983,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: سَمِعَتْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: اقْطَعُوا فِي رُبُعِ دينار، وَلَا تَقْطَعُوا فِيمَا هُوَ أَدْنَى مِنْ ذَلِكَ. وَكَانَ رُبُعُ الدِّينَارِ يَوْمَئِذٍ ثَلَاثَةَ دَرَاهِمَ، وَالدِّينَارُ اثْني عَشَرَ دِرْهَمًا. قَالَ: وَكَانَتْ سَرِقَتُهُ دُونَ رُبُعِ الدِّينَارِ، فَلَمْ أَقْطَعْهُ."],"takhrij":"حسن: رواه الإمام أحمد (4515) عن هاشم قال: حدثنا محمد – يعني ابن راشد، عن يحيى بن يحيى الغساني، قال: قدمت المدينة. فلقيت أبا بكر بن محمد بن عمرو بن حزم وهو عامل على المدينة، قال: أتيتُ بسارقٍ، فأرسلتْ إليّ خالتي عمرة بنت عبد الرحمن أن لا تعجل في أمر هذا الرجل حتى آتيك، فأُخبرك ما سمعت عن عائشة في أمر السارق قال: فأتتني وأخبرتني أنها سمعت عائشة تقول فذكرت الحديث.","grade":"حسن","chapter_ar":"باب النّصاب الذي تقطع فيه يد السّارق","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (24515).","chapter_en":"The minimum amount for which the thief’s hand is cut off","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في حد السرقة","group_en":"Collection of Chapters Regarding the Legal Punishment for Theft","part_no":33,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["ʿA’ishah, the wife of the Prophet ﷺ, said: I heard the Messenger of Allah ﷺ say: “Cut off the hand for a quarter dinar, and do not cut it off for anything less than that.” At that time, a quarter dinar was equal to three dirhams, and a dinar was twelve dirhams. He said: “His theft was less than a quarter dinar, so I did not cut off his hand.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":24515,"lafz":true},{"key":"ahmad","label":"الامام احمد","number":4515}],"full":1,"dr":1},{"num":6984,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ لَمْ تُقْطَعْ يَدُ سَارِقٍ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي أَقَلَّ مِنْ ثَمَنِ الْمِجَنِّ حَجَفَةٍ أَوْ تُرْسٍ وَكِلاَهُمَا ذُو ثَمَنٍ."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6794)، ومسلم في الحدود (1685) كلاهما من حديث هشام بن عروة، عن أبيه، عن عائشة، فذكرته.","grade":"متفق عليه","chapter_ar":"باب النّصاب الذي تقطع فيه يد السّارق","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6794) and Muslim (1685).","chapter_en":"The minimum amount for which the thief’s hand is cut off","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في حد السرقة","group_en":"Collection of Chapters Regarding the Legal Punishment for Theft","part_no":33,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["ʿA’ishah said: During the time of the Messenger of Allah ﷺ, the hand of a thief was not cut off for less than the price of a shield — whether a small shield or a large shield — and both had value."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6794,"lafz":true},{"key":"muslim","label":"مسلم","number":1685}],"full":1},{"num":6985,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَطَعَ فِي مِجَنٍّ ثَمَنُهُ ثَلاَثَةُ دَرَاهِمَ."],"takhrij":"متفق عليه: رواه مالك في الحدود (21) عن نافع، عن عبد الله بن عمر، فذكره. ورواه البخاري في الحدود (6795) ومسلم في الحدود (6:1686) كلاهما من طريق مالك، به، مثله.","grade":"متفق عليه","chapter_ar":"باب النّصاب الذي تقطع فيه يد السّارق","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (21), al-Bukhari (6795), and Muslim (1686).","chapter_en":"The minimum amount for which the thief’s hand is cut off","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في حد السرقة","group_en":"Collection of Chapters Regarding the Legal Punishment for Theft","part_no":33,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Abdullah ibn Umar reported: The Messenger of Allah ﷺ cut off the hand for a shield worth three dirhams."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":21},{"key":"bukhari","label":"البخاري","number":6795,"lafz":true},{"key":"muslim","label":"مسلم","number":6}],"full":1},{"num":6986,"demo":false,"sanad":"","matn":["اللهِ بْنَ عُمَرَ، حَدَّثَهُمْ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَطَعَ يَدَ رَجُلٍ سَرَقَ تُرْسًا مِنْ صُفَّةِ النِّسَاءِ، ثَمَنُهُ ثَلَاثَةُ دَرَاهِمَ."],"takhrij":"صحيح: رواه أحمد (6317) عن عبد الرزاق، أخبرنا ابن جريج، أخبرني إسماعيل بن أمية، أن نافعا مولى عبد الله حدثه فذكره. ومن هذا الطريق رواه أبو داود (4386). ورواه النسائي (4909) من وجه آخر عن ابن جريج به مثله. وإسناده صحيح. والحديث في الصحيحين دون ذكر الصّفة. وفي نسخة للنسائي صنعة النساء، فلعله تحريف.","grade":"صحيح","chapter_ar":"باب النّصاب الذي تقطع فيه يد السّارق","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (6317), Abu Dawud (4386), and al-Nasa’i (4909).","chapter_en":"The minimum amount for which the thief’s hand is cut off","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في حد السرقة","group_en":"Collection of Chapters Regarding the Legal Punishment for Theft","part_no":33,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Ibn Umar reported that the Prophet ﷺ cut off the hand of a man who stole a shield from the women’s shelter area, and its value was three dirhams."]},"buhuth":{"en":["The phrase: “the women’s shelter area” appears this way in the previous sources, while in one version of al-Nasa’i it appears as: “the women’s quarters.” What is apparent from the wording “from the women’s shelter area” is that a part of the sheltered area was designated for the emigrant women. Therefore, the wording “the women’s quarters” in one manuscript of al-Nasa’i is likely a textual alteration."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4386},{"key":"nasai","label":"النسائي","number":4909,"n":4909},{"key":"ahmad","label":"مسند الإمام أحمد","number":6317,"n":6317,"lafz":true}],"full":1,"dr":1},{"num":6987,"demo":false,"sanad":"","matn":["عن رَافِعِ بن خَدِيجٍ قَالَ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ لاَ قَطْعَ فِي ثَمَرٍ وَلاَ كَثَرٍ."],"takhrij":"صحيح: رواه الترمذي (1449) والنسائي (4967) كلاهما عن قتيبة بن سعيد، حدثنا الليث، عن يحيى بن سعيد الأنصاري، عن محمد بن يحيى بن حبّان، عن عمه واسع بن حبان، عن رافع بن خديج فذكره.","grade":"صحيح","chapter_ar":"باب ما لا قطع فيه","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1449) and al-Nasa’i (4967).","chapter_en":"Cases in Which the Hand Is Not Cut Off","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في حد السرقة","group_en":"Collection of Chapters Regarding the Legal Punishment for Theft","part_no":33,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Rafiʿ ibn Khadij said: I heard the Messenger of Allah ﷺ say: “There is no cutting of the hand for stolen fruit or palm pith.”"]},"buhuth":{"en":["The word “kathar” refers to the palm pith — the soft inner core and marrow of the palm tree."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1449,"lafz":true},{"key":"nasai","label":"النسائي","number":4967}],"full":1,"dr":1},{"num":6988,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن عمرو بْنِ الْعَاصِ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ سُئِلَ عَنِ الثَّمَرِ الْمُعَلَّقِ فَقَالَ مَنْ أَصَابَ بِفِيهِ مِنْ ذِي حَاجَةٍ غَيْرَ مُتَّخِذٍ خُبْنَةً فَلاَ شَىْءَ عَلَيْهِ وَمَنْ خَرَجَ بِشَىْءٍ مِنْهُ فَعَلَيْهِ غَرَامَةُ مِثْلَيْهِ وَالْعُقُوبَةُ وَمَنْ سَرَقَ مِنْهُ شَيْئًا بَعْدَ أَنْ يُئْوِيَهُ الْجَرِينُ فَبَلَغَ ثَمَنَ الْمِجَنِّ فَعَلَيْهِ الْقَطْعُ. وَذَكَرَ فِي ضَالَّةِ الإِبِلِ وَالْغَنَمِ كَمَا ذَكَرَهُ غَيْرُهُ.","قال: وسئل عن اللقطة فقال: ما كان منها في طريق الميتاء، أو القرية الجامعة فعرّفها سنة، فإن جاء طالبها فادفعها إليه، وإن لم يأت فهي لك. وما كان في الخراب يعني ففيها وفي الركاز الخمس."],"takhrij":"حسن: رواه أبو داود (1710) والترمذي (1288) والنسائي (4958) وابن ماجة (2596) كلهم عن قتيبة بن سعيد، حدثنا الليث، عن ابن عجلان، عن عمرو بن شعيب، عن أبيه، عن جده عبد الله بن عمرو بن العاص، فذكر الحديث. إلا ابن ماجة فرواه من وجه آخر عن الوليد بن كثير، عن عمرو بن شعيب. واللفظ لأبي داود، وعند الآخرين مختصراً.","grade":"حسن","chapter_ar":"باب ما لا قطع فيه","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1710), al-Tirmidhi (1288), and al-Nasa’i (4958). The wording is from Abu Dawud.","chapter_en":"Cases in Which the Hand Is Not Cut Off","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في حد السرقة","group_en":"Collection of Chapters Regarding the Legal Punishment for Theft","part_no":33,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Abdullah ibn Amr ibn al-ʿAs reported that the Messenger of Allah ﷺ was asked about hanging fruit, and he said: “Whoever eats from it out of need without taking any away in his garment has committed no offense. But whoever carries some away, then upon him is double compensation and punishment. And whoever steals from it after it has been gathered into the storage place, and it reaches the value of a shield, then cutting of the hand applies.” He also mentioned the rulings regarding stray camels and sheep as mentioned elsewhere. He said: The Prophet ﷺ was also asked about lost property, and he said: “If it is found on a commonly traveled road or in an inhabited village, announce it for one year. If its owner comes, give it to him; otherwise it belongs to you. But what is found in ruins, or buried treasure, then one-fifth is due from it.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1710,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1288},{"key":"nasai","label":"النسائي","number":4958},{"key":"ibnmajah","label":"ابن ماجه","number":2596}],"full":1,"dr":1,"rep":[5946]},{"num":6989,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَيْسَ عَلَى خَائِنٍ وَلاَ مُنْتَهِبٍ وَلاَ مُخْتَلِسٍ قَطْعٌ."],"takhrij":"صحيح: رواه أبو داود (4393،4392،4391) والترمذي (1448) وابن ماجة (2591) والنسائي (4973) وصحّحه ابن حبان (4456) والبيهقي (8/289) كلهم من طرق ابن جريج، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما لا قطع فيه","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (4391–4393), al-Tirmidhi (1448), Ibn Majah (2591), and al-Nasa’i (4973).","chapter_en":"Cases in Which the Hand Is Not Cut Off","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في حد السرقة","group_en":"Collection of Chapters Regarding the Legal Punishment for Theft","part_no":33,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Jabir reported that the Prophet ﷺ said: “There is no cutting of the hand for the betrayer, the plunderer, or the snatcher.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4391,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1448},{"key":"ibnmajah","label":"ابن ماجه","number":2591},{"key":"nasai","label":"النسائي","number":4973,"n":4971},{"key":"abudawud","label":"ابو داود","number":4393},{"key":"abudawud","label":"ابو داود","number":4392},{"key":"ibnhibban","label":"ابن حبان","number":4456}],"full":1,"dr":1},{"num":6990,"demo":false,"sanad":"","matn":["عن عَبْدِ الرَّحْمَنِ بن عَوْفٍ عَنْ أَبِيهِ، قَالَ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ لَيْسَ عَلَى الْمُخْتَلِسِ قَطْعٌ."],"takhrij":"صحيح: رواه ابن ماجة (2592) عن محمد بن يحيى، قال: حدثنا محمد بن عاصم بن جعفر المصري، قال: حدثنا المفضّل بن فضالة، عن يونس بن يزيد، عن ابن شهاب، عن إبراهيم بن عبد الرحمن بن عوف، عن أبيه، قال: سمعت النبي صلى الله عليه وسلم يقول: فذكره.","grade":"صحيح","chapter_ar":"باب ما لا قطع فيه","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2592).","chapter_en":"Cases in Which the Hand Is Not Cut Off","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في حد السرقة","group_en":"Collection of Chapters Regarding the Legal Punishment for Theft","part_no":33,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Abd al-Rahman ibn Awf said: I heard the Messenger of Allah ﷺ say: “There is no cutting of the hand for the snatcher.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2592,"lafz":true}],"full":1,"dr":1},{"num":6991,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَيْسَ عَلَى مُنْتَهِبٍ، وَلَا مُخْتَلِسٍ، وَلَا خَائِنٍ قَطْعٌ."],"takhrij":"صحيح: رواه الطبراني في الأوسط (مجمع البحرين 2466) حدثنا أحمد بن القاسم بن المساور، ثنا أبو معمر إسماعيل بن إبراهيم، قال: أملى عليّ عبدالله بن وهب من حفظه، عن يونس، عن الزهري، عن أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب ما لا قطع فيه","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tabarani in al-Awsat (Majmaʿ al-Bahrayn 2466).","chapter_en":"Cases in Which the Hand Is Not Cut Off","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في حد السرقة","group_en":"Collection of Chapters Regarding the Legal Punishment for Theft","part_no":33,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Anas reported that the Prophet ﷺ said: “There is no cutting of the hand for the plunderer, the snatcher, or the betrayer.”"]},"buhuth":{"en":["“Snatching” refers to property taken openly and forcefully.","The “betrayer” is one who takes wealth through deception and betrayal while outwardly appearing sincere to the owner.","Al-Khattabi said: “The majority of the scholars agreed that the snatcher and betrayer do not have their hands cut off, because Allah only made cutting obligatory for the thief.”"]}},"tuhfa":{},"refs":[{"key":"sh28171","label":"الطبراني في الأوسط","number":2466,"lafz":true}],"full":1,"dr":1},{"num":6992,"demo":false,"sanad":"","matn":["عَنْ صَفْوَانَ بن أُمَيَّةَ بن خَلَفٍ أَنَّهُ قِيلَ لَهُ: هَلَكَ مَنْ لَمْ يُهَاجِرْ. قَالَ: فَقُلْتُ: لَا أَصِلُ إِلَى أَهْلِي حَتَّى آتِيَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَكِبْتُ رَاحِلَتِي، فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ . فَقُلْتُ: يَا رَسُولَ اللَّهِ، زَعَمُوا أَنَّهُ هَلَكَ مَنْ لَمْ يُهَاجِرْ؟ قَالَ: كَلَّا أَبَا وَهْبٍ، فَارْجِعْ إِلَى أَبَاطِحِ مَكَّةَ قَالَ: فَبَيْنَمَا أَنَا رَاقِدٌ إِذْ جَاءَ السَّارِقُ، فَأَخَذَ ثَوْبِي مِنْ تَحْتِ رَأْسِي، فَأَدْرَكْتُهُ. فَأَتَيْتُ بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ . فَقُلْتُ: إِنَّ هَذَا سَرَقَ ثَوْبِي. فَأَمَرَ بِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُقْطَعَ. قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ: لَيْسَ هَذَا أَرَدْتُ. هُوَ عَلَيْهِ صَدَقَةٌ. قَالَ: فَهَلَّا قَبْلَ أَنْ تَأْتِيَنِي بِهِ؟"],"takhrij":"صحيح: رواه مالك في الحدود (31) وأحمد (15303) واللفظ له، وأبو داود (4394) والنسائي (4881) وابن ماجة (2595) والحاكم (4/380) والبيهقي (8/265) كلهم من طرق عن صفوان بن أمية. ومنهم من رواه مرسلاً، ومنهم من رواه موصولا، والحديث صحيح، وصحّحه الحاكم.","grade":"صحيح","chapter_ar":"باب لا شفاعة في الحدود إذا بلغ السلطان","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (31), Ahmad (15303) — and this is his wording — Abu Dawud (4394), and al-Nasa’i (4881).","chapter_en":"No Intercession in Prescribed Punishments Once the Matter Reaches the Authority","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في حد السرقة","group_en":"Collection of Chapters Regarding the Legal Punishment for Theft","part_no":33,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Safwan ibn Umayyah ibn Khalaf reported that it was said to him: “Whoever did not migrate has perished.” He said: “So I said: I will not return to my family until I go to the Messenger of Allah ﷺ.” So I rode my mount and came to the Messenger of Allah ﷺ and said: “O Messenger of Allah ﷺ, they claim that whoever did not migrate has perished.” He said: “No, O Abu Wahb. Return to the valleys of Makkah.” He said: While I was sleeping, a thief came and took my cloak from beneath my head. I caught him and brought him to the Prophet ﷺ. I said: “This man stole my cloak.” So the Prophet ﷺ ordered that his hand be cut off. I said: “O Messenger of Allah ﷺ, that is not what I intended. It is charity from me to him.” He said: “Why did you not do that before bringing him to me?”"]},"buhuth":{"en":["Al-Khattabi said: “Those who held that there is no cutting of the hand if the stolen item becomes the property of the thief before the case is raised to the ruler used as evidence the statement: ‘Why did you not do that before bringing him to me?’ They said: This indicates that if the owner had gifted it to him or pardoned him before bringing the matter to the ruler, the punishment of cutting would be dropped.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":31,"lafz":true},{"key":"abudawud","label":"أبو داود","number":4394},{"key":"nasai","label":"النسائي","number":4881},{"key":"ahmad","label":"مسند الإمام أحمد","number":15303,"n":15303},{"key":"ibnmajah","label":"ابن ماجه","number":2595}],"full":1,"dr":1},{"num":6993,"demo":false,"sanad":"","matn":["عن ابْنِ عُمَرَ فَقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ حَالَتْ شَفَاعَتُهُ دُونَ حَدٍّ مِنْ حُدُودِ اللَّهِ عَزَّ وَجَلَّ، فَقَدْ ضَادَّ اللهَ أَمْرَهُ."],"takhrij":"صحيح: رواه أبو داود (3597) وأحمد (5385) وصحّحه الحاكم (2/27) والبيهقي (6/82) كلهم من حديث زهير بن معاوية، حدثنا عمارة بن غزية، عن يحيى بن راشد، قال: خرجنا حُجاجاً عشرة من أهل الشام، حتى آتينا مكة، فذكر الحديث. قال: فأتيناه، فخرج إلينا – يعني ابن عمر فذكر الحديث في سياق أطول منه. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب لا شفاعة في الحدود إذا بلغ السلطان","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3597), Ahmad (5385), and authenticated by al-Hakim (2/27) and al-Bayhaqi (6/82).","chapter_en":"No Intercession in Prescribed Punishments Once the Matter Reaches the Authority","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في حد السرقة","group_en":"Collection of Chapters Regarding the Legal Punishment for Theft","part_no":33,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Ibn Umar said: I heard the Messenger of Allah ﷺ say: “Whoever intercedes to prevent one of the prescribed punishments of Allah, the Mighty and Majestic, has opposed the command of Allah.”"]},"buhuth":{"en":["This applies after the matter has reached the ruler. Before it reaches the ruler, intercession is recommended in order to preserve concealment.","Ahmad said: “Intercession regarding prescribed punishments is allowed so long as it has not reached the authority.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3597,"lafz":true},{"key":"hakim","label":"صحّحه الحاكم","number":27},{"key":"kubrabayhaqi","label":"البيهقي","number":82},{"key":"ahmad","label":"مسند الإمام أحمد","number":5385,"n":5385},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":17617,"n":17775}],"full":1,"dr":1},{"num":6994,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ تَعَافَوُا الْحُدُودَ فِيمَا بَيْنَكُمْ فَمَا بَلَغَنِي مِنْ حَدٍّ فَقَدْ وَجَبَ."],"takhrij":"حسن: رواه أبو داود (4376) ومن طريقه البيهقي (8/331) والنسائي (4886) وصحّحه الحاكم (4/383) كلهم من حديث ابن وهب، سمعت ابن جريج، يحدث عن عمرو بن شعيب، عن أبيه، عن عبد الله بن عمرو فذكر الحديث. وإسناده حسن من أجل عمرو بن شعيب فإنه حسن الحديث.","grade":"حسن","chapter_ar":"باب لا شفاعة في الحدود إذا بلغ السلطان","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4376), al-Bayhaqi (8/331), and al-Nasa’i (4886), and authenticated by al-Hakim (4/383).","chapter_en":"No Intercession in Prescribed Punishments Once the Matter Reaches the Authority","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في حد السرقة","group_en":"Collection of Chapters Regarding the Legal Punishment for Theft","part_no":33,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Amr ibn Shuʿayb, from his father, from Abdullah ibn Amr, reported that the Messenger of Allah ﷺ said: “Pardon the prescribed punishments among yourselves, but whatever reaches me of a prescribed punishment has become obligatory.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4376,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":331},{"key":"nasai","label":"النسائي","number":4886,"n":4886},{"key":"hakim","label":"صحّحه الحاكم","number":383},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":17611,"n":17769},{"key":"hakim","label":"المستدرك على الصحيحين","number":8156,"n":8162}],"full":1,"dr":1},{"num":6995,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، رَضِيَ اللَّهُ عَنْهَا قَالَتْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَقِيلُوا ذَوِي الْهَيْئَاتِ عَثَرَاتِهِمْ إِلاَّ الْحُدُودَ."],"takhrij":"حسن: رواه أبو داود (4375) وأحمد (25474) والنسائي في الكبرى (7294) والبيهقي (8/334) كلهم من حديث عبد الملك بن زيد بن سعيد بن زيد بن عمرو بن نُفيل، عن محمد بن أبي بكر بن حزم، عن أبيه، عن عمرة، عن عائشة فذكرته. إلا أن أبا داود لم يذكر فيه \"عن أبيه\"، والثقات الذين رووه عن عبد الملك ذكروا فيه \"عن أبيه\".","grade":"حسن","chapter_ar":"باب لا شفاعة في الحدود إذا بلغ السلطان","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4375), Ahmad (25474), al-Nasa’i in al-Kubra (7294), and al-Bayhaqi (8/334).","chapter_en":"No Intercession in Prescribed Punishments Once the Matter Reaches the Authority","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في حد السرقة","group_en":"Collection of Chapters Regarding the Legal Punishment for Theft","part_no":33,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["ʿA’ishah reported that the Messenger of Allah ﷺ said: “Overlook the slips of people of dignity, except in the prescribed punishments.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4375,"lafz":true},{"key":"kubranasai","label":"النسائي في الكبرى","number":7294},{"key":"kubrabayhaqi","label":"البيهقي","number":334,"n":66},{"key":"ahmad","label":"مسند الإمام أحمد","number":25474,"n":25474}],"full":1,"dr":1,"rep":[1195,13933]},{"num":6996,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَطَعَ يَدَ امْرَأَةٍ. قَالَتْ عَائِشَةُ وَكَانَتْ تَأْتِي بَعْدَ ذَلِكَ، فَأَرْفَعُ حَاجَتَهَا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَتَابَتْ وَحَسُنَتْ تَوْبَتُهَا."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6800) ومسلم في الحدود (9:1688) كلاهما من طريق ابن وهب، أخبرني يونس بن يزيد، عن ابن شهاب، أخبرني عروة بن الزبير، عن عائشة، فذكرته.","grade":"متفق عليه","chapter_ar":"باب توبة السارق وقبول شهادته","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6800) and Muslim (1688/9). The wording is from al-Bukhari.","chapter_en":"The Repentance of the Thief and Acceptance of His Testimony","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في حد السرقة","group_en":"Collection of Chapters Regarding the Legal Punishment for Theft","part_no":33,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["ʿA’ishah reported that the Prophet ﷺ cut off the hand of a woman. ʿA’ishah said: “After that, she would come to me and I would present her needs to the Prophet ﷺ. She repented, and her repentance became good.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6800,"lafz":true},{"key":"muslim","label":"مسلم","number":9}],"full":1,"dr":1},{"num":6997,"demo":false,"sanad":"","matn":["عَنْ جُنَادَةَ بْنِ أَبِي أُمَيَّةَ، قَالَ كُنَّا مَعَ بُسْرِ بْنِ أَرْطَاةَ فِي الْبَحْرِ فَأُتِيَ بِسَارِقٍ يُقَالُ لَهُ مِصْدَرٌ قَدْ سَرَقَ بُخْتِيَّةً فَقَالَ قَدْ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ لاَ تُقْطَعُ الأَيْدِي فِي السَّفَرِ. وَلَوْلاَ ذَلِكَ لَقَطَعْتُهُ."],"takhrij":"صحيح: رواه أبو داود (4408) والنسائي (4979) والبيهقي (9/104) كلهم من حديث حيوة بن شريح، عن عياش بن عباس القِتْباني، عن شِيَيْم بن بَيْتان ويزيد بن صُبح الأصبحي، عن جنادة بن أبي أمية فذكره.","grade":"صحيح","chapter_ar":"باب لا يُقطع في الغزوة","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (4408), al-Nasa’i (4979), and al-Bayhaqi (9/104).","chapter_en":"The Hand Is Not Cut Off During Military Expeditions","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في حد السرقة","group_en":"Collection of Chapters Regarding the Legal Punishment for Theft","part_no":33,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["Junadah ibn Abi Umayyah said: We were with Busr ibn Abi Artat at sea when a thief who had stolen a Bukhtiyyah camel was brought to him. He said: “I heard the Messenger of Allah ﷺ say: ‘Hands are not cut off during travel.’ Had it not been for that, I would have cut it off.”"]},"buhuth":{"en":["What is intended by “travel” here is military expedition, as mentioned in the narrations of al-Tirmidhi (1450).","“Bukhtiyyah” refers to a female camel of the Bukht breed."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4408,"lafz":true},{"key":"nasai","label":"النسائي","number":4979},{"key":"kubrabayhaqi","label":"البيهقي","number":104},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":18223,"n":18381}],"full":1,"dr":1},{"num":6998,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَيْفَ أَنْتَ إِذَا أَصَابَ النَّاسَ مَوْتٌ، يَكُونُ الْبَيْتُ فِيهِ بِالْوَصِيفِ؟ – يَعْنِي الْقَبْرَ – قُلْتُ: اللَّهُ وَرَسُولُهُ أَعْلَمُ، أَوْ مَا خَارَ اللهُ وَرَسُولُهُ قَالَ: عَلَيْكَ بِالصَّبْرِ أَوْ قَالَ: تصبر."],"takhrij":"صحيح: أخرجه أبو داود (4409،4261) والحاكم (4/424) والبيهقي (8/191) كلهم من طريق حماد بن زيد، عن أبي عمران الجوني، عن المشعّب بن طريف، عن عبدالله بن الصامت، عن أبي ذر فذكر الحديث مطولا. وسيأتي في كتاب الفتن.","grade":"صحيح","chapter_ar":"باب في قطع النباش","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (4261, 4409), al-Hakim (4/424), and al-Bayhaqi (8/191).","chapter_en":"Regarding Cutting the Hand of the Grave Robber","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في حد السرقة","group_en":"Collection of Chapters Regarding the Legal Punishment for Theft","part_no":33,"group_no":3,"chapter_no":7,"content":{"translation":{"en":["Abu Dharr reported that the Messenger of Allah ﷺ said to me: “What will you do when death spreads among the people until a grave will cost the value of a servant?” — meaning the grave. I said: “Allah and His Messenger know best,” or “Whatever Allah and His Messenger choose.” He said: “Remain patient,” or he said: “Be patient.”"]},"buhuth":{"en":["The word “house” here refers to the grave, and “wasif” means a servant."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4261,"lafz":true},{"key":"hakim","label":"الحاكم","number":424},{"key":"kubrabayhaqi","label":"البيهقي","number":191},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":17238,"n":17396},{"key":"abudawud","label":"ابو داود","number":4409}],"full":1,"dr":1},{"num":6999,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا سَرَقَ الْمَمْلُوكُ فَبِعْهُ وَلَوْ بِنَشٍّ."],"takhrij":"حسن: رواه أبو داود (4412) والنسائي (4980) وابن ماجة (2589) والبخاري في الأدب المفرد (165) كلهم من حديث أبي عوانة، عن عمر بن أبي سلمة، عن أبيه، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في بيع العبد السارق","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4412), al-Nasa’i (4980), Ibn Majah (2589), and al-Bukhari in al-Adab al-Mufrad (165).","chapter_en":"What Has Been Reported Regarding Selling a Slave Who Steals","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في حد السرقة","group_en":"Collection of Chapters Regarding the Legal Punishment for Theft","part_no":33,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “If the slave steals, then sell him even for a Nish.”"]},"buhuth":{"en":["“Nish” means half of something, even if sold for half of his value."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4412,"lafz":true},{"key":"nasai","label":"النسائي","number":4980,"n":5127},{"key":"ibnmajah","label":"ابن ماجه","number":2589},{"key":"adab","label":"البخاري في الأدب المفرد","number":165}],"full":1,"dr":1},{"num":7000,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَجَّةِ الْوَدَاعِ: أَلاَ أي شَهْرٍ تَعْلَمُونَهُ أَعْظَمُ حُرْمَةً؟ قَالُوا: أَلاَ شَهْرُنَا هَذَا قَالَ: أَلاَ أي بَلَدٍ تَعْلَمُونَهُ أَعْظَمُ حُرْمَةً؟ قَالُوا: أَلاَ بَلَدُنَا هَذَا. قَالَ: أَلاَ أي يَوْمٍ تَعْلَمُونَهُ أَعْظَمُ حُرْمَةً؟ قَالُوا: أَلاَ يَوْمُنَا هَذَا. قَالَ: فَإِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى قَدْ حرّم عَلَيْكُمْ دِمَاءَكُمْ وَأَمْوَالَكُمْ وَأَعْرَاضَكُمْ – إِلاَّ بِحَقِّهَا – كَحُرْمَةِ يَوْمِكُمْ هَذَا، فِي بَلَدِكُمْ هَذَا، فِي شَهْرِكُمْ هَذَا، أَلاَ هَلْ بَلَّغْتُ (ثَلاَثًا)؟ كُلُّ ذَلِكَ يُجِيبُونَهُ: أَلاَ نَعَمْ. قَالَ: وَيْحَكُمْ- أَوْ وَيْلَكُمْ- لاَ ترجعنَّ كُفَّارًا بَعْدِي، يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6785)، ومسلم في الإيمان (66) كلاهما من طريق واقد بن محمد، عن أبيه، عن ابن عمر، فذكره.","grade":"متفق عليه","chapter_ar":"باب وجوب صيانة أعراض المسلمين والمسلمات","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6785) and Muslim (66).","chapter_en":"The Obligation of Protecting the Honor of Muslim Men and Women","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد القذف","group_en":"Chapters Regarding the Prescribed Punishment for False Accusation (Qadhf)","part_no":33,"group_no":4,"chapter_no":1,"content":{"translation":{"en":["Abdullah ibn Umar reported that the Messenger of Allah ﷺ said in the Farewell Pilgrimage: “Do you know which month is most sacred?” They said: “This month of ours.” He said: “Do you know which land is most sacred?” They said: “This land of ours.” He said: “Do you know which day is most sacred?” They said: “This day of ours.” He then said: “Indeed Allah, Blessed and Exalted, has made your blood, your wealth, and your honor sacred to one another—except by right—just as sacred as this day of yours, in this land of yours, in this month of yours. Have I conveyed?” (three times) and they replied: “Yes.” He said: “Woe to you—do not revert after me to disbelief, striking the necks of one another.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6785,"lafz":true},{"key":"muslim","label":"مسلم","number":66}],"full":1,"dr":1},{"num":7001,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ اجْتَنِبُوا السَّبْعَ الْمُوبِقَاتِ. قَالُوا يَا رَسُولَ اللَّهِ وَمَا هُنَّ قَالَ الشِّرْكُ بِاللَّهِ، وَالسِّحْرُ، وَقَتْلُ النَّفْسِ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ، وَأَكْلُ الرِّبَا، وَأَكْلُ مَالِ الْيَتِيمِ، وَالتَّوَلِّي يَوْمَ الزَّحْفِ، وَقَذْفُ الْمُحْصَنَاتِ الْمُؤْمِنَاتِ الْغَافِلاَتِ."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6857) ومسلم في الإيمان (89) كلاهما من طريق سليمان بن بلال، عن ثور بن زيد، عن أبي الغيث، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب إثم قذف المحصنات","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6857) and Muslim (89).","chapter_en":"The Sin of Accusing Chaste Women","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد القذف","group_en":"Chapters Regarding the Prescribed Punishment for False Accusation (Qadhf)","part_no":33,"group_no":4,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “Avoid the seven destructive sins.” They asked: “O Messenger of Allah ﷺ, what are they?” He said: “Associating partners with Allah, magic, killing a soul whom Allah has forbidden except by right, consuming usury, consuming the wealth of an orphan, fleeing from the battlefield, and slandering chaste believing women who are unaware of evil.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6857,"lafz":true},{"key":"muslim","label":"مسلم","number":89}],"full":1,"rep":[230,5690,6809,7897,11517,12142,12362,12859]},{"num":7002,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ هِلاَلَ بْنَ أُمَيَّةَ، قَذَفَ امْرَأَتَهُ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشَرِيكِ بْنِ سَحْمَاءَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْبَيِّنَةُ أَوْ حَدٌّ فِي ظَهْرِكَ. فَقَالَ يَا رَسُولَ اللَّهِ إِذَا رَأَى أَحَدُنَا عَلَى امْرَأَتِهِ رَجُلاً يَنْطَلِقُ يَلْتَمِسُ الْبَيِّنَةَ فَجَعَلَ يَقُولُ الْبَيِّنَةَ وَإِلاَّ حَدٌّ فِي ظَهْرِكَ. فَذَكَرَ حَدِيثَ اللِّعَانِ."],"takhrij":"صحيح: رواه البخاري في الشهادات (2671) عن محمد بن بشار، حدثنا ابن أبي عدي، عن هشام، حدثنا عكرمة، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب حد القذف ثمانين جلدة","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2671).","chapter_en":"The Prescribed Punishment for False Accusation is Eighty Lashes","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد القذف","group_en":"Chapters Regarding the Prescribed Punishment for False Accusation (Qadhf)","part_no":33,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Ibn Abbas reported that Hilal ibn Umayyah accused his wife before the Prophet ﷺ of [adultery] with Sharik ibn Sahma’. The Prophet ﷺ said: “Bring proof, otherwise the legal punishment will be upon your back.” He said: “O Messenger of Allah ﷺ, if one of us sees a man with his wife, does he go searching for proof?” The Prophet ﷺ kept saying: “Proof, or the legal punishment upon your back,” until the incident of mutual imprecation (liʿan) was revealed."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2671,"lafz":true}],"full":1},{"num":7003,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ لَمَّا نَزَلَ عُذْرِي قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْمِنْبَرِ فَذَكَرَ ذَلِكَ وَتَلاَ الْقُرْآنَ فَلَمَّا نَزَلَ أَمَرَ بِرَجُلَيْنِ وَامْرَأَةٍ فَضُرِبُوا حَدَّهُمْ."],"takhrij":"حسن: رواه أبو داود (4474) والترمذي (3181) وابن ماجة (2567) وأحمد (24066) كلهم من حديث ابن أبي عدي (وهو محمد بن إبراهيم بن أبي عدي) عن محمد بن إسحاق، عن عبد الله بن أبي بكر، عن عمرة، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب حد القذف ثمانين جلدة","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4474), al-Tirmidhi (3181), Ibn Majah (2567), and Ahmad (24066).","chapter_en":"The Prescribed Punishment for False Accusation is Eighty Lashes","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في حد القذف","group_en":"Chapters Regarding the Prescribed Punishment for False Accusation (Qadhf)","part_no":33,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["ʿA’ishah reported: When my exoneration was revealed, the Messenger of Allah ﷺ stood on the pulpit, mentioned the matter, and recited the Qur’an. When he came down from the pulpit, he ordered that two men and a woman be punished with the prescribed punishment."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4474,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":3181},{"key":"ibnmajah","label":"ابن ماجه","number":2567},{"key":"ahmad","label":"مسند الإمام أحمد","number":24066,"n":24066}],"full":1,"dr":1},{"num":7004,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ شَرِبَ الْخَمْرَ فِي الدُّنْيَا، ثُمَّ لَمْ يَتُبْ مِنْهَا، حُرِمَهَا فِي الآخِرَةِ."],"takhrij":"متفق عليه: رواه مالك في الأشربة (11) عن نافع، عن عبد الله بن عمر، فذكره. ورواه البخاري في الأشربة (5575)، ومسلم في الأشربة (2003/76) كلاهما من طريق مالك، به، مثله.","grade":"متفق عليه","chapter_ar":"باب الترهيب من شرب الخمر","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (11), al-Bukhari (5575), and Muslim (2003/76).","chapter_en":"Warning Against Drinking Intoxicants","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في شرب الخمر والحد فيه","group_en":"Chapters Regarding Drinking Intoxicants and the Prescribed Punishment","part_no":33,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Ibn Umar reported that the Messenger of Allah ﷺ said: “Whoever drinks intoxicants in this world and does not repent from them will be deprived of them in the Hereafter.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":11},{"key":"bukhari","label":"البخاري","number":5575,"lafz":true},{"key":"muslim","label":"مسلم","number":76}],"full":1,"rep":[7454]},{"num":7005,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، أَنَّ رَجُلاً، قَدِمَ مِنْ جَيْشَانَ - وَجَيْشَانُ مِنَ الْيَمَنِ - فَسَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ شَرَابٍ يَشْرَبُونَهُ بِأَرْضِهِمْ مِنَ الذُّرَةِ يُقَالُ لَهُ الْمِزْرُ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوَمُسْكِرٌ هُوَ. قَالَ نَعَمْ. قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُلُّ مُسْكِرٍ حَرَامٌ إِنَّ عَلَى اللَّهِ عَزَّ وَجَلَّ عَهْدًا لِمَنْ يَشْرَبُ الْمُسْكِرَ أَنْ يَسْقِيَهُ مِنْ طِينَةِ الْخَبَالِ. قَالُوا يَا رَسُولَ اللَّهِ وَمَا طِينَةُ الْخَبَالِ قَالَ عَرَقُ أَهْلِ النَّارِ أَوْ عُصَارَةُ أَهْلِ النَّارِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2002) عن قتيبة بن سعيد، حدثنا عبدالعزيز الدراوردي، عن عمارة بن غزية، عن أبي الزبير، عن جابر، فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من شرب الخمر","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2002).","chapter_en":"Warning Against Drinking Intoxicants","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في شرب الخمر والحد فيه","group_en":"Chapters Regarding Drinking Intoxicants and the Prescribed Punishment","part_no":33,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Jabir ibn Abdullah reported that a man came from Jayshan — a region in Yemen — and asked the Prophet ﷺ about a drink made from corn in their land called al-Mizr. The Prophet ﷺ said: “Is it intoxicating?” He replied: “Yes.” The Messenger of Allah ﷺ said: “Every intoxicant is forbidden. Allah, the Mighty and Majestic, has made a covenant that whoever drinks intoxicants will be given to drink from the mud of al-Khabal.” They asked: “O Messenger of Allah ﷺ, what is the mud of al-Khabal?” He said: “The sweat of the people of Hell, or the discharge of the people of Hell.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2002,"lafz":true}],"full":1,"rep":[7455,16466]},{"num":7006,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ شَرِبَ الْخَمْرَ وَسَكِرَ لَمْ تُقْبَلْ لَهُ صَلاَةٌ أَرْبَعِينَ صَبَاحًا وَإِنْ مَاتَ دَخَلَ النَّارَ فَإِنْ تَابَ تَابَ اللَّهُ عَلَيْهِ وَإِنْ عَادَ فَشَرِبَ فَسَكِرَ لَمْ تُقْبَلْ لَهُ صَلاَةٌ أَرْبَعِينَ صَبَاحًا فَإِنْ مَاتَ دَخَلَ النَّارَ فَإِنْ تَابَ تَابَ اللَّهُ عَلَيْهِ وَإِنْ عَادَ فَشَرِبَ فَسَكِرَ لَمْ تُقْبَلْ لَهُ صَلاَةٌ أَرْبَعِينَ صَبَاحًا فَإِنْ مَاتَ دَخَلَ النَّارَ فَإِنْ تَابَ تَابَ اللَّهُ عَلَيْهِ وَإِنْ عَادَ كَانَ حَقًّا عَلَى اللَّهِ أَنْ يَسْقِيَهُ مِنْ رَدْغَةِ الْخَبَالِ يَوْمَ الْقِيَامَةِ. قَالُوا يَا رَسُولَ اللَّهِ وَمَا رَدْغَةُ الْخَبَالِ قَالَ عُصَارَةُ أَهْلِ النَّارِ."],"takhrij":"صحيح: رواه ابن ماجه (4377) وصححه ابن حبان (5357) من طريق الوليد بن مسلم، ثنا الأوزاعي، عن ربيعة بن يزيد، عن عبدالله بن الديلمي، عن عبدالله بن عمرو بن العاص، قال: فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من شرب الخمر","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (3377), and authenticated by Ibn Hibban (5357).","chapter_en":"Warning Against Drinking Intoxicants","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في شرب الخمر والحد فيه","group_en":"Chapters Regarding Drinking Intoxicants and the Prescribed Punishment","part_no":33,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Abdullah ibn Amr reported that the Messenger of Allah ﷺ said: “Whoever drinks intoxicants and becomes drunk, his prayer will not be accepted for forty mornings. If he dies, he enters the Fire. But if he repents, Allah accepts his repentance. If he returns and drinks again until intoxicated, his prayer will not be accepted for forty mornings. If he dies, he enters the Fire. But if he repents, Allah accepts his repentance. If he returns again and drinks until intoxicated, his prayer will not be accepted for forty mornings. If he dies, he enters the Fire. But if he repents, Allah accepts his repentance. Then if he returns again, it becomes a right upon Allah to give him to drink from Radghat al-Khabal on the Day of Resurrection.” They asked: “O Messenger of Allah ﷺ, what is Radghat al-Khabal?” He said: “The discharge of the people of Hell.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":3377},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":5357},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2453,"n":2450},{"key":"ibnmajah","label":"ابن ماجه","number":4377,"lafz":true}],"full":1,"dr":1,"rep":[7456]},{"num":7007,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِرَجُلٍ قَدْ شَرِبَ الْخَمْرَ فَجَلَدَهُ بِجَرِيدَتَيْنِ نَحْوَ أَرْبَعِينَ. قَالَ وَفَعَلَهُ أَبُو بَكْرٍ فَلَمَّا كَانَ عُمَرُ اسْتَشَارَ النَّاسَ فَقَالَ عَبْدُ الرَّحْمَنِ أَخَفَّ الْحُدُودِ ثَمَانِينَ. فَأَمَرَ بِهِ عُمَرُ."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6773) ومسلم في الحدود (35:1706) كلاهما من طريق شعبة، قال: سمعتُ قتادة يحدّث عن أنس بن مالك، فذكره،","grade":"متفق عليه","chapter_ar":"باب حد شارب الخمر","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6773) and Muslim (1706/35). The wording is from Muslim.","chapter_en":"The Prescribed Punishment for Drinking Intoxicants","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في شرب الخمر والحد فيه","group_en":"Chapters Regarding Drinking Intoxicants and the Prescribed Punishment","part_no":33,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Anas reported that the Prophet ﷺ was brought a man who had drunk intoxicants, so he lashed him with two palm branches about forty times. He said: Abu Bakr did the same. Then when Umar became caliph, he consulted the people. Abd al-Rahman said: “The lightest prescribed punishment is eighty.” So Umar ordered eighty lashes."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6773,"lafz":true},{"key":"muslim","label":"مسلم","number":35}],"full":1,"dr":1},{"num":7008,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ، بْنِ مَالِكٍ أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  جَلَدَ فِي الْخَمْرِ بِالْجَرِيدِ وَالنِّعَالِ ثُمَّ جَلَدَ أَبُو بَكْرٍ أَرْبَعِينَ. فَلَمَّا كَانَ عُمَرُ وَدَنَا النَّاسُ مِنَ الرِّيفِ وَالْقُرَى قَالَ مَا تَرَوْنَ فِي جَلْدِ الْخَمْرِ فَقَالَ عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ أَرَى أَنْ تَجْعَلَهَا كَأَخَفِّ الْحُدُودِ. قَالَ فَجَلَدَ عُمَرُ ثَمَانِينَ."],"takhrij":"صحيح: رواه مسلم في الحدود (1706: 36) عن محمد بن المثنى، حدثنا معاذ بن هشام، حدثني أبي، عن قتادة، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب حد شارب الخمر","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in al-Hudud (1706/36).","chapter_en":"The Prescribed Punishment for Drinking Intoxicants","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في شرب الخمر والحد فيه","group_en":"Chapters Regarding Drinking Intoxicants and the Prescribed Punishment","part_no":33,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Malik reported that the Prophet of Allah ﷺ punished for drinking intoxicants with palm branches and sandals. Abu Bakr then lashed forty times. When Umar became caliph and people drew near from the villages and countryside, he said: “What do you think regarding the punishment for drinking intoxicants?” Abd al-Rahman ibn Awf said: “I think you should make it like the lightest prescribed punishment.” So Umar lashed eighty times."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم في الحدود","number":36,"lafz":true},{"key":"muslim","label":"مسلم في الحدود","number":1706,"n":4454}],"full":1,"dr":1},{"num":7009,"demo":false,"sanad":"","matn":["عن عُرْوَةَ بن الزُّبَيْرِ أَنَّ عُبَيْدَ اللَّهِ بْنَ عَدِيِّ بْنِ الْخِيَارِ، أَخْبَرَهُ أَنَّ الْمِسْوَرَ بْنَ مَخْرَمَةَ وَعَبْدَ الرَّحْمَنِ بْنَ الأَسْوَدِ بْنِ عَبْدِ يَغُوثَ قَالاَ لَهُ مَا يَمْنَعُكَ أَنْ تُكَلِّمَ خَالَكَ عُثْمَانَ فِي أَخِيهِ الْوَلِيدِ بْنِ عُقْبَةَ وَكَانَ أَكْثَرَ النَّاسُ فِيمَا فَعَلَ بِهِ. قَالَ عُبَيْدُ اللَّهِ فَانْتَصَبْتُ لِعُثْمَانَ حِينَ خَرَجَ إِلَى الصَّلاَةِ فَقُلْتُ لَهُ إِنَّ لِي إِلَيْكَ حَاجَةً وَهْىَ نَصِيحَةٌ. فَقَالَ أَيُّهَا الْمَرْءُ، أَعُوذُ بِاللَّهِ مِنْكَ، فَانْصَرَفْتُ، فَلَمَّا قَضَيْتُ الصَّلاَةَ جَلَسْتُ إِلَى الْمِسْوَرِ وَإِلَى ابْنِ عَبْدِ يَغُوثَ، فَحَدَّثْتُهُمَا بِالَّذِي قُلْتُ لِعُثْمَانَ وَقَالَ لِي. فَقَالاَ قَدْ قَضَيْتَ الَّذِي كَانَ عَلَيْكَ. فَبَيْنَمَا أَنَا جَالِسٌ مَعَهُمَا، إِذْ جَاءَنِي رَسُولُ عُثْمَانَ، فَقَالاَ لِي قَدِ ابْتَلاَكَ اللَّهُ. فَانْطَلَقْتُ حَتَّى دَخَلْتُ عَلَيْهِ، فَقَالَ مَا نَصِيحَتُكَ الَّتِي ذَكَرْتَ آنِفًا قَالَ فَتَشَهَّدْتُ ثُمَّ قُلْتُ إِنَّ اللَّهَ بَعَثَ مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنْزَلَ عَلَيْهِ الْكِتَابَ، وَكُنْتَ مِمَّنِ اسْتَجَابَ لِلَّهِ وَرَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَآمَنْتَ بِهِ، وَهَاجَرْتَ الْهِجْرَتَيْنِ الأُولَيَيْنِ، وَصَحِبْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَرَأَيْتَ هَدْيَهُ، وَقَدْ أَكْثَرَ النَّاسُ فِي شَأْنِ الْوَلِيدِ بْنِ عُقْبَةَ، فَحَقٌّ عَلَيْكَ أَنْ تُقِيمَ عَلَيْهِ الْحَدَّ. فَقَالَ لِي يَا ابْنَ أَخِي أَدْرَكْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ قُلْتُ لاَ، وَلَكِنْ قَدْ خَلَصَ إِلَىَّ مِنْ عِلْمِهِ مَا خَلَصَ إِلَى الْعَذْرَاءِ فِي سِتْرِهَا. قَالَ فَتَشَهَّدَ عُثْمَانُ فَقَالَ إِنَّ اللَّهَ قَدْ بَعَثَ مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْحَقِّ وَأَنْزَلَ عَلَيْهِ الْكِتَابَ، وَكُنْتُ مِمَّنِ اسْتَجَابَ لِلَّهِ وَرَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَآمَنْتُ بِمَا بُعِثَ بِهِ مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. وَهَاجَرْتُ الْهِجْرَتَيْنِ الأُولَيَيْنِ كَمَا قُلْتَ، وَصَحِبْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَبَايَعْتُهُ، وَاللَّهِ مَا عَصَيْتُهُ وَلاَ غَشَشْتُهُ حَتَّى تَوَفَّاهُ اللَّهُ، ثُمَّ اسْتَخْلَفَ اللَّهُ أَبَا بَكْرٍ فَوَاللَّهِ مَا عَصَيْتُهُ وَلاَ غَشَشْتُهُ، ثُمَّ اسْتُخْلِفَ عُمَرُ، فَوَاللَّهِ مَا عَصَيْتُهُ وَلاَ غَشَشْتُهُ، ثُمَّ اسْتُخْلِفْتُ، أَفَلَيْسَ لِي عَلَيْكُمْ مِثْلُ الَّذِي كَانَ لَهُمْ عَلَىَّ قَالَ بَلَى. قَالَ فَمَا هَذِهِ الأَحَادِيثُ الَّتِي تَبْلُغُنِي عَنْكُمْ فَأَمَّا مَا ذَكَرْتَ مِنْ شَأْنِ الْوَلِيدِ بْنِ عُقْبَةَ، فَسَنَأْخُذُ فِيهِ إِنْ شَاءَ اللَّهُ بِالْحَقِّ قَالَ فَجَلَدَ الْوَلِيدَ أَرْبَعِينَ جَلْدَةً، وَأَمَرَ عَلِيًّا أَنْ يَجْلِدَهُ، وَكَانَ هُوَ يَجْلِدُهُ."],"takhrij":"صحيح: رواه البخاري في مناقب الأنصار (3872) عن عبدالله بن محمد الجعفيّ، حدّثنا هشام، أخبرنا معمر، عن الزهري، حدثنا عروة بن الزبير، فذكره.","grade":"صحيح","chapter_ar":"باب حد شارب الخمر","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3872) and (3696).","chapter_en":"The Prescribed Punishment for Drinking Intoxicants","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في شرب الخمر والحد فيه","group_en":"Chapters Regarding Drinking Intoxicants and the Prescribed Punishment","part_no":33,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Urwah ibn al-Zubayr reported that Ubayd Allah ibn Adi ibn al-Khiyar informed him that al-Miswar ibn Makhramah and Abd al-Rahman ibn al-Aswad ibn Abd Yaghuth said to him: “What prevents you from speaking to your uncle Uthman regarding his brother al-Walid ibn Uqbah? The people have spoken much about what he did.” Ubayd Allah said: I stood before Uthman as he came out for prayer and said to him: “I have advice for you.” He replied: “O man, I seek refuge in Allah from you.” So I left. After the prayer I sat with al-Miswar and Ibn Abd Yaghuth and informed them of what had happened. They said: “You have fulfilled your duty.” While I was sitting with them, a messenger from Uthman came to me. They said: “Allah has now tested you.” So I went to him and entered upon him. He said: “What was the advice you mentioned earlier?” I testified and then said: “Allah sent Muhammad ﷺ with the truth and revealed the Book to him. You were among those who responded to Allah and His Messenger ﷺ, believed in him, made both migrations, accompanied the Messenger of Allah ﷺ, and saw his guidance. The people have spoken much regarding al-Walid ibn Uqbah, and it is your duty to establish the punishment upon him.” Uthman said to me: “My nephew, did you meet the Messenger of Allah ﷺ?” I replied: “No, but knowledge of him has reached me just as clearly as it reaches a virgin in her chamber.” Then Uthman testified and said: “Allah indeed sent Muhammad ﷺ with the truth and revealed the Book to him. I was among those who responded to Allah and His Messenger, believed in what Muhammad was sent with, made both migrations as you mentioned, accompanied the Messenger of Allah ﷺ, and pledged allegiance to him. By Allah, I never disobeyed or deceived him until Allah took him. Then Allah appointed Abu Bakr as caliph, and by Allah I never disobeyed or deceived him. Then Umar was appointed, and by Allah I never disobeyed or deceived him. Then I was appointed. Do I not deserve from you the same rights they had over me?” They said: “Yes.” He said: “As for what you mentioned regarding al-Walid ibn Uqbah, we shall deal with him according to the truth, if Allah wills.” He then lashed al-Walid forty lashes and ordered Ali to carry out the lashing, and Ali himself administered it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3872,"lafz":true}],"full":1,"dr":1},{"num":7010,"demo":false,"sanad":"","matn":["عن حصين بن المنذر أَبِي ساسان قَالَ: شَهِدْتُ عُثْمَانَ بْنَ عَفَّانَ وَأُتِيَ بِالْوَلِيدِ قَدْ صَلَّى الصُّبْحَ رَكْعَتَيْنِ ثُمَّ قَالَ أَزِيدُكُمْ فَشَهِدَ عَلَيْهِ رَجُلاَنِ أَحَدُهُمَا حُمْرَانُ أَنَّهُ شَرِبَ الْخَمْرَ وَشَهِدَ آخَرُ أَنَّهُ رَآهُ يَتَقَيَّأُ فَقَالَ عُثْمَانُ إِنَّهُ لَمْ يَتَقَيَّأْ حَتَّى شَرِبَهَا فَقَالَ يَا عَلِيُّ قُمْ فَاجْلِدْهُ. فَقَالَ عَلِيٌّ قُمْ يَا حَسَنُ فَاجْلِدْهُ. فَقَالَ الْحَسَنُ وَلِّ حَارَّهَا مَنْ تَوَلَّى قَارَّهَا - فَكَأَنَّهُ وَجَدَ عَلَيْهِ - فَقَالَ يَا عَبْدَ اللَّهِ بْنَ جَعْفَرٍ قُمْ فَاجْلِدْهُ. فَجَلَدَهُ وَعَلِيٌّ يَعُدُّ حَتَّى بَلَغَ أَرْبَعِينَ فَقَالَ أَمْسِكْ. ثُمَّ قَالَ جَلَدَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَرْبَعِينَ وَجَلَدَ أَبُو بَكْرٍ أَرْبَعِينَ وَعُمَرُ ثَمَانِينَ وَكُلٌّ سُنَّةٌ وَهَذَا أَحَبُّ إِلَىَّ."],"takhrij":"صحيح: رواه مسلم في الحدود (1707) من طرق عن إسماعيل ابن عليّة، عن ابن أبي عروبة، عن عبد الله الدّاناج.","grade":"صحيح","chapter_ar":"باب حد شارب الخمر","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1707).","chapter_en":"The Prescribed Punishment for Drinking Intoxicants","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في شرب الخمر والحد فيه","group_en":"Chapters Regarding Drinking Intoxicants and the Prescribed Punishment","part_no":33,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Husayn ibn al-Mundhir Abu Sasan said: I witnessed Uthman ibn Affan when al-Walid was brought to him after having led the dawn prayer in two rakʿahs and then said: “Shall I give you more?” Two men testified against him: one of them was Humran, who testified that he had drunk intoxicants, and another testified that he saw him vomiting. Uthman said: “He would not vomit unless he had drunk it.” Then he said: “O Ali, stand and lash him.” Ali said: “O Hasan, stand and lash him.” Hasan replied: “Let the one who enjoyed its coolness handle its heat,” as though he was upset with him. Then Ali said: “O Abdullah ibn Jaʿfar, stand and lash him.” So he lashed him while Ali counted until he reached forty. Then he said: “Stop.” Ali then said: “The Prophet ﷺ lashed forty, Abu Bakr lashed forty, and Umar lashed eighty. All are Sunnah, but this is more beloved to me.”"]},"buhuth":{"en":["The phrase “Let the one who enjoyed its coolness handle its heat” is a proverb meaning: let the one who took responsibility for the benefit also bear the burden of punishment. “Coolness” refers to ease and comfort."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1707,"lafz":true}],"full":1,"dr":1},{"num":7011,"demo":false,"sanad":"","matn":["عن علي بن أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ مَا كُنْتُ لأُقِيمَ حَدًّا عَلَى أَحَدٍ فَيَمُوتَ، فَأَجِدَ فِي نَفْسِي، إِلاَّ صَاحِبَ الْخَمْرِ، فَإِنَّهُ لَوْ مَاتَ وَدَيْتُهُ، وَذَلِكَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَسُنَّهُ."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6778) ومسلم في الحدود (39:1707) كلاهما من طريق سفيان الثوري، حدثنا أبو حصين، سمعت عمير بن سعيد النخعي قال: سمعت علي بن أبي طالب قال فذكره.","grade":"متفق عليه","chapter_ar":"باب حد شارب الخمر","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6778) and Muslim (1707/39).","chapter_en":"The Prescribed Punishment for Drinking Intoxicants","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في شرب الخمر والحد فيه","group_en":"Chapters Regarding Drinking Intoxicants and the Prescribed Punishment","part_no":33,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Ali ibn Abi Talib said: “I would not carry out a prescribed punishment on anyone and then feel regret if he died, except in the case of the drinker of intoxicants. If he died, I would pay blood money for him, because the Messenger of Allah ﷺ did not specify a fixed punishment for it.”"]},"buhuth":{"en":["The statement “the Messenger of Allah ﷺ did not specify it” means that he did not set a fixed prescribed number for the punishment."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6778,"lafz":true},{"key":"muslim","label":"مسلم","number":39}],"full":1,"dr":1},{"num":7012,"demo":false,"sanad":"","matn":["عَنْ عبدالرحمن بن أزهر قَالَ: أُتِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشَارِبٍ وَهُوَ بِحُنَيْنٍ، فحثا وَجْهِهِ فِي التُّرَابَ، ثُمَّ أَمَرَ أَصْحَابَهُ فَضَرَبُوهُ بالنعال، وَمَا كَانَ فِي أَيْدِيهِمْ. حَتَّى قَالَ لَهُمُ: ارْفَعُوا فَرَفَعُوا. فَتُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ جَلَدَ أَبُو بَكْرٍ فِي الْخَمْرِ أَرْبَعِينَ، ثُمَّ جَلَدَ عُمَرُ أَرْبَعِينَ صَدْرًا مِنْ إِمَارَتِهِ، ثُمَّ جَلَدَ عُثْمَانُ ثَمَانِينَ فِي آخِرِ خِلاَفَتِهِ، ثُمَّ جَلَدَ عُثْمَانُ الْحَدَّيْنِ كِلَيْهِمَا: ثَمَانِينَ وَأَرْبَعِينَ. ثُمَّ أَثْبَتَ مُعَاوِيَةُ الْحَدَّ ثَمَانِينَ."],"takhrij":"حسن: رواه أبو داود (4488) عن ابن السرح (وهو أحمد بن عمرو بن السرح) قال: وجدت في كتاب خالي عبد الرحمن بن عبد الحميد، عن عقيل أن ابن شهاب أخبره، عن عبد الله بن عبد الرحمن بن أزهر، أخبره عن أبيه فذكر الحديث.","grade":"حسن","chapter_ar":"باب حد شارب الخمر","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4488) and al-Nasa’i in al-Kubra (5283).","chapter_en":"The Prescribed Punishment for Drinking Intoxicants","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في شرب الخمر والحد فيه","group_en":"Chapters Regarding Drinking Intoxicants and the Prescribed Punishment","part_no":33,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Abd al-Rahman ibn Azhar said: The Prophet ﷺ was brought a man who had drunk intoxicants during the battle of Hunayn. He threw dust in his face, then ordered his companions to strike him with sandals and whatever was in their hands, until he said to them: “Stop,” so they stopped. Then the Messenger of Allah ﷺ passed away. Abu Bakr lashed forty times for drinking intoxicants. Umar lashed forty during the early part of his caliphate, then eighty during the latter part of it. Uthman applied both punishments: eighty and forty. Then Muʿawiyah established the punishment as eighty lashes."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4488,"lafz":true},{"key":"kubranasai","label":"النسائي في الكبرى","number":5283}],"full":1,"dr":1},{"num":7013,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أُتِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِرَجُلٍ قَدْ شَرِبَ قَالَ اضْرِبُوهُ. قَالَ أَبُو هُرَيْرَةَ فَمِنَّا الضَّارِبُ بِيَدِهِ، وَالضَّارِبُ بِنَعْلِهِ، وَالضَّارِبُ بِثَوْبِهِ، فَلَمَّا انْصَرَفَ قَالَ بَعْضُ الْقَوْمِ أَخْزَاكَ اللَّهُ. قَالَ لاَ تَقُولُوا هَكَذَا لاَ تُعِينُوا عَلَيْهِ الشَّيْطَانَ."],"takhrij":"صحيح: رواه البخاري في الحدود (6777) عن قتيبة، حدثنا أبو ضمرة أنس، عن يزيد بن النهار، عن محمد بن إبراهيم، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ضرب شارب الخمر بالجريد والنّعال والثوب والأيدي وغيرها، ولا يُشترط السوط والجلد","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6777).","chapter_en":"Striking the Drinker of Intoxicants with Palm Branches, Sandals, Garments, Hands, and Similar Means — A Whip Is Not Required","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في شرب الخمر والحد فيه","group_en":"Chapters Regarding Drinking Intoxicants and the Prescribed Punishment","part_no":33,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["Abu Hurayrah said: A man who had drunk intoxicants was brought to the Prophet ﷺ, and he said: “Strike him.” Abu Hurayrah said: Some of us struck him with their hands, some with their sandals, and some with their garments. When he left, some of the people said: “May Allah disgrace you.” The Prophet ﷺ said: “Do not say that. Do not help Satan against him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6777,"lafz":true}],"full":1},{"num":7014,"demo":false,"sanad":"","matn":["عَنِ السَّائِبِ بْنِ يَزِيدَ، قَالَ كُنَّا نُؤْتَى بِالشَّارِبِ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَإِمْرَةِ أَبِي بَكْرٍ وَصَدْرًا مِنْ خِلاَفَةِ عُمَرَ، فَنَقُومُ إِلَيْهِ بِأَيْدِينَا وَنِعَالِنَا وَأَرْدِيَتِنَا، حَتَّى كَانَ آخِرُ إِمْرَةِ عُمَرَ، فَجَلَدَ أَرْبَعِينَ، حَتَّى إِذَا عَتَوْا وَفَسَقُوا جَلَدَ ثَمَانِينَ."],"takhrij":"صحيح: رواه البخاري في الحدود (6779) عن مكي بن إبراهيم، عن الجعيد، عن يزيد بن خُصيفة، عن السائب بن يزيد، فذكره.","grade":"صحيح","chapter_ar":"باب ضرب شارب الخمر بالجريد والنّعال والثوب والأيدي وغيرها، ولا يُشترط السوط والجلد","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6779).","chapter_en":"Striking the Drinker of Intoxicants with Palm Branches, Sandals, Garments, Hands, and Similar Means — A Whip Is Not Required","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في شرب الخمر والحد فيه","group_en":"Chapters Regarding Drinking Intoxicants and the Prescribed Punishment","part_no":33,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["Al-Sa’ib ibn Yazid said: During the time of the Messenger of Allah ﷺ, the caliphate of Abu Bakr, and the early part of Umar’s caliphate, when a drinker was brought to us, we would strike him with our hands, sandals, and cloaks. Then toward the end of Umar’s rule, he lashed forty times, and when people became excessive and immoral, he lashed eighty times."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6779,"lafz":true}],"full":1},{"num":7015,"demo":false,"sanad":"","matn":["عَنْ مُعَاوِيَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ شَرِبَ الْخَمْرَ فَاجْلِدُوهُ فَإِنْ عَادَ فِي الرَّابِعَةِ فَاقْتُلُوهُ."],"takhrij":"حسن: رواه أبو داود (4482) والترمذي (1444) وابن ماجة (2573) وأحمد (16859) وصحّحه ابن حبان (4446) والحاكم (4/372) والبيهقي (8/313) كلهم من حديث عاصم بن بهدلة، عن أبي صالح، عن معاوية فذكره.","grade":"حسن","chapter_ar":"باب ماجاء في قتل شارب الخمر","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4482), al-Tirmidhi (1444), Ibn Majah (2573), and Ahmad (16859).","chapter_en":"What Has Been Reported Regarding Killing the One Who Repeatedly Drinks Intoxicants","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في شرب الخمر والحد فيه","group_en":"Chapters Regarding Drinking Intoxicants and the Prescribed Punishment","part_no":33,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Muʿawiyah said: The Messenger of Allah ﷺ said: “Whoever drinks intoxicants, lash him. If he returns a fourth time, then kill him.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4482,"lafz":true,"n":4484},{"key":"tirmidhi","label":"الترمذي","number":1444},{"key":"ibnmajah","label":"ابن ماجه","number":2573},{"key":"ahmad","label":"مسند الإمام أحمد","number":16859,"n":16888},{"key":"ibnhibban","label":"ابن حبان","number":4446}],"full":1,"dr":1},{"num":7016,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا سَكِرَ فَاجْلِدُوهُ ثُمَّ إِنْ سَكِرَ فَاجْلِدُوهُ ثُمَّ إِنْ سَكِرَ فَاجْلِدُوهُ فَإِنْ عَادَ الرَّابِعَةَ فَاقْتُلُوهُ."],"takhrij":"حسن: رواه أبو داود (4484) والنسائي (5662) وابن ماجة (2572) وأحمد (7911) وصحّحه ابن حبان (4447) والحاكم (4/371) والبيهقي (8/313) كلهم من حديث ابن أبي ذئب، عن الحارث بن عبد الرحمن، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ماجاء في قتل شارب الخمر","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4484), al-Nasa’i (5662), Ibn Majah (2572), and Ahmad (7911).","chapter_en":"What Has Been Reported Regarding Killing the One Who Repeatedly Drinks Intoxicants","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في شرب الخمر والحد فيه","group_en":"Chapters Regarding Drinking Intoxicants and the Prescribed Punishment","part_no":33,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “If he becomes intoxicated, lash him. Then if he becomes intoxicated again, lash him. Then if he becomes intoxicated again, lash him. If he returns a fourth time, then kill him.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4484,"lafz":true},{"key":"nasai","label":"النسائي","number":5662,"n":5662},{"key":"ibnmajah","label":"ابن ماجه","number":2572},{"key":"ahmad","label":"مسند الإمام أحمد","number":7911,"n":7911},{"key":"ibnhibban","label":"ابن حبان","number":4447}],"full":1,"dr":1},{"num":7017,"demo":false,"sanad":"","matn":["عَنْ شُرَحْبِيلَ بْنِ أَوْسٍ، - وَكَانَ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - أَنَّهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ شَرِبَ الْخَمْرَ فَاجْلِدُوهُ، فَإِنْ عَادَ فَاجْلِدُوهُ، فَإِنْ عَادَ فَاجْلِدُوهُ، فَإِنْ عَادَ فَاقْتُلُوهُ."],"takhrij":"حسن: رواه الإمام أحمد (18053) والطبراني في الكبير (1/198) و(7/366) والحاكم (4/373) كلهم من حديث حريز بن عثمان الجمحي، قال: حدثني نمران بن مخْمر، عن شرحبيل بن أوس فذكره.","grade":"حسن","chapter_ar":"باب ماجاء في قتل شارب الخمر","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (18053), al-Tabarani in al-Kabir (1/198 and 7/366), and al-Hakim (4/373).","chapter_en":"What Has Been Reported Regarding Killing the One Who Repeatedly Drinks Intoxicants","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في شرب الخمر والحد فيه","group_en":"Chapters Regarding Drinking Intoxicants and the Prescribed Punishment","part_no":33,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Sharhabil ibn Aws — who was among the companions of the Prophet ﷺ — reported that the Prophet ﷺ said: “Whoever drinks intoxicants, lash him. If he returns, lash him. If he returns again, lash him. If he returns again, then kill him.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":18053,"lafz":true},{"key":"mujamkabir","label":"الطبراني في الكبير","number":198},{"key":"hakim","label":"الحاكم","number":373}],"full":1,"dr":1},{"num":7018,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، وَنَفَرٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالُوا: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ شَرِبَ الْخَمْرَ فَاجْلِدُوهُ، ثُمَّ إِنْ شَرِبَ فَاجْلِدُوهُ، ثُمَّ إِنْ شَرِبَ فَاجْلِدُوهُ، ثُمَّ إِنْ شَرِبَ فَاجْلِدُوهُ، ثُمَّ إِنْ شَرِبَ فَاقْتُلُوهُ."],"takhrij":"حسن: رواه النسائي (5661) عن إسحاق بن إبراهيم، (ابن راهويه) قال: أنبانا جرير، عن مغيرة الضبي، عن عبد الرحمن بن أبي نُعم، عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب ماجاء في قتل شارب الخمر","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (5661), and authenticated by al-Hakim (4/371).","chapter_en":"What Has Been Reported Regarding Killing the One Who Repeatedly Drinks Intoxicants","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في شرب الخمر والحد فيه","group_en":"Chapters Regarding Drinking Intoxicants and the Prescribed Punishment","part_no":33,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Ibn Umar and a group of the companions of the Prophet ﷺ reported that the Messenger of Allah ﷺ said: “Whoever drinks intoxicants, lash him. Then if he drinks again, lash him. Then if he drinks again, lash him. Then if he drinks again, kill him.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":5661,"lafz":true,"n":5661},{"key":"hakim","label":"صحّحه الحاكم","number":371}],"full":1,"dr":1},{"num":7019,"demo":false,"sanad":"","matn":["عن ديلم الحميري أنه سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّا بِأَرْضٍ بَارِدَةٍ، وَإِنَّا لَنَسْتَعِينُ بِشَرَابٍ يُصْنَعُ لَنَا مِنَ الْقَمْحِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُسْكِرُ؟ قَالَ: نَعَمْ، قَالَ: فَلَا تَشْرَبُوهُ فَأَعَادَ عَلَيْهِ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُسْكِرُ؟ قَالَ: نَعَمْ، قَالَ: فَلَا تَشْرَبُوهُ فَأَعَادَ عَلَيْهِ الثَّالِثَةَ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُسْكِرُ؟ قَالَ: نَعَمْ قَالَ: فَلَا تَشْرَبُوهُ قَالَ: فَإِنَّهُمْ لَا يَصْبِرُونَ عَنْهُ قَالَ: فَإِنْ لَمْ يَصْبِرُوا عَنْهُ فَاقْتُلْهُمْ."],"takhrij":"صحيح: رواه أحمد (18034) والطبراني في الكبير (4/269) كلاهما من حديث عبد الحميد بن جعفر، حدثنا يزيد بن أبي حبيب، حدثنا مرثد بن عبدالله اليزني، قال: حدثنا الديلم فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ماجاء في قتل شارب الخمر","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (18034) and al-Tabarani in al-Kabir (4/269).","chapter_en":"What Has Been Reported Regarding Killing the One Who Repeatedly Drinks Intoxicants","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في شرب الخمر والحد فيه","group_en":"Chapters Regarding Drinking Intoxicants and the Prescribed Punishment","part_no":33,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Daylam al-Himyari asked the Messenger of Allah ﷺ, saying: “We live in a cold land and use a drink made from wheat.” The Messenger of Allah ﷺ said: “Does it intoxicate?” He replied: “Yes.” He said: “Then do not drink it.” He repeated the question, and the Messenger of Allah ﷺ again said: “Does it intoxicate?” He said: “Yes.” He replied: “Then do not drink it.” He repeated it a third time, and the Messenger of Allah ﷺ asked: “Does it intoxicate?” He said: “Yes.” He replied: “Then do not drink it.” He said: “They cannot do without it.” The Prophet ﷺ said: “If they cannot refrain from it, then kill them.”"]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":269},{"key":"ahmad","label":"مسند الإمام أحمد","number":18034,"n":18034,"lafz":true}],"full":1,"dr":1},{"num":7020,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْخَمْرُ إِذَا شَرِبُوهَا فَاجْلِدُوهُمْ، ثُمَّ إِذَا شَرِبُوهَا فَاجْلِدُوهُمْ، ثُمَّ إِذَا شَرِبُوهَا فَاجْلِدُوهُمْ، ثُمَّ إِذَا شَرِبُوهَا فَاقْتُلُوهُمْ، عِنْدَ الرَّابِعَةِ."],"takhrij":"حسن: رواه الإمام أحمد (6553) عن معاذ بن هشام، حدثني أبي، عن قتادة وعبد الصمد قال: حدثنا همام، حدثنا قتادة، عن شهر بن حوشب، عن عبد الله بن عمرو فذكره.","grade":"حسن","chapter_ar":"باب ماجاء في قتل شارب الخمر","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (6553), and authenticated by al-Hakim (4/372).","chapter_en":"What Has Been Reported Regarding Killing the One Who Repeatedly Drinks Intoxicants","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في شرب الخمر والحد فيه","group_en":"Chapters Regarding Drinking Intoxicants and the Prescribed Punishment","part_no":33,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Abdullah ibn Amr reported that the Prophet ﷺ said: “When they drink intoxicants, lash them. Then if they drink again, lash them. Then if they drink again, lash them. Then if they drink again, kill them upon the fourth time.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":6553,"lafz":true},{"key":"hakim","label":"صحّحه الحاكم","number":372},{"key":"hakim","label":"المستدرك على الصحيحين","number":8119,"n":8125}],"full":1,"dr":1},{"num":7021,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بْنِ الْخَطَّابِ، أَنَّ رَجُلاً، عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ اسْمُهُ عَبْدَ اللَّهِ، وَكَانَ يُلَقَّبُ حِمَارًا، وَكَانَ يُضْحِكُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ جَلَدَهُ فِي الشَّرَابِ، فَأُتِيَ بِهِ يَوْمًا فَأَمَرَ بِهِ فَجُلِدَ، فَقَالَ رَجُلٌ مِنَ الْقَوْمِ اللَّهُمَّ الْعَنْهُ مَا أَكْثَرَ مَا يُؤْتَى بِهِ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ تَلْعَنُوهُ، فَوَاللَّهِ مَا عَلِمْتُ أَنَّهُ يُحِبُّ اللَّهَ وَرَسُولَهُ."],"takhrij":"صحيح: رواه البخاري في الحدود (6780) عن يحيى بن بُكير، حدّثني الليث، قال حدثني خالد بن يزيد، عن سعيد بن أبي هلال، عن زيد بن أسلم، عن أبيه، عن عمر بن الخطاب، فذكره.","grade":"صحيح","chapter_ar":"باب نسخ قتل شارب الخمر ولو شرب مرارا","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6780).","chapter_en":"The Abrogation of Killing the Drinker of Intoxicants Even If He Drinks Repeatedly","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في شرب الخمر والحد فيه","group_en":"Chapters Regarding Drinking Intoxicants and the Prescribed Punishment","part_no":33,"group_no":5,"chapter_no":5,"content":{"translation":{"en":["Umar ibn al-Khattab reported that during the lifetime of the Prophet ﷺ there was a man named Abdullah who was nicknamed “Himar,” and he used to make the Messenger of Allah ﷺ laugh. The Prophet ﷺ had previously punished him for drinking intoxicants. One day he was brought again, and the Prophet ﷺ ordered that he be flogged. A man among the people said: “O Allah, curse him! How often he is brought for this!” The Prophet ﷺ said: “Do not curse him, for by Allah, I know nothing about him except that he loves Allah and His Messenger.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6780,"lafz":true}],"full":1,"dr":1,"rep":[10272]},{"num":7022,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللهِ، عَنْ نَبِيِّ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قَالَ: إِذَا شَرِبَ الرَّجُلُ فَاجْلِدُوهُ، فَإِنْ عَادَ فَاجْلِدُوهُ، فَإِنْ عَادَ الرَّابِعَةَ فَاقْتُلُوهُ فَأُتِيَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  بِرَجُلٍ مِنَّا فَلَمْ يَقْتُلْهُ."],"takhrij":"حسن: رواه ابن حزم في المحلى (11/368) والطحاوي في شرحه (4836) والنسائي في الكبرى (5302) كلهم من طريق شريك، عن محمد بن إسحاق، عن محمد بن المنكدر، عن جابر بن عبد الله فذكره.","grade":"حسن","chapter_ar":"باب نسخ قتل شارب الخمر ولو شرب مرارا","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Hazm in al-Muhalla (11/368) and al-Tahawi in Sharh Maʿani al-Athar (4836).","chapter_en":"The Abrogation of Killing the Drinker of Intoxicants Even If He Drinks Repeatedly","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في شرب الخمر والحد فيه","group_en":"Chapters Regarding Drinking Intoxicants and the Prescribed Punishment","part_no":33,"group_no":5,"chapter_no":5,"content":{"translation":{"en":["Jabir ibn Abdullah reported that the Prophet ﷺ said: “If someone drinks intoxicants, lash him. If he returns, lash him. If he returns again, lash him. If he returns a fourth time, kill him.” Then a man from among us was brought to the Messenger of Allah ﷺ, but he did not kill him."]}},"tuhfa":{},"refs":[{"key":"ابن_حزم/المحلی","label":"ابن حزم في المحلى","number":368},{"key":"sh21108","label":"الطحاوي في شرحه","number":4836,"lafz":true},{"key":"kubranasai","label":"النسائي في الكبري","number":5302,"n":5280}],"full":1,"dr":1},{"num":7023,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ الحارِثِ قَالَ: جِيءَ بِالنُّعَيْمَانِ أَوْ ابْنِ النُّعَيْمَانِ شَارِبًا، فَأَمَرَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ كَانَ فِي الْبَيْتِ أَنْ يَضْرِبُوا، قَالَ: فَكُنْتُ أَنَا فِيمَنْ ضَرَبَهُ، فَضَرَبْنَاهُ بِالنِّعَالِ وَالجرِيدِ."],"takhrij":"صحيح: رواه البخاري في الوكالة (2316)، وفي الحدود (6774، 6775) من طرق، عن أيوب، عن عبد الله بن أبي مُليكة، عن عقبة بن الحارث قال: فذكره.","grade":"صحيح","chapter_ar":"باب نسخ قتل شارب الخمر ولو شرب مرارا","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6775, 6774, 2316).","chapter_en":"The Abrogation of Killing the Drinker of Intoxicants Even If He Drinks Repeatedly","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في شرب الخمر والحد فيه","group_en":"Chapters Regarding Drinking Intoxicants and the Prescribed Punishment","part_no":33,"group_no":5,"chapter_no":5,"content":{"translation":{"en":["Uqbah ibn al-Harith said: Al-Nuʿayman, or Ibn al-Nuʿayman, was brought having drunk intoxicants, so the Messenger of Allah ﷺ ordered those in the house to strike him. Uqbah said: “I was among those who struck him, and we struck him with sandals and palm branches.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6775,"lafz":true},{"key":"bukhari","label":"البخاري في الوكاله","number":2316}],"full":1,"dr":1},{"num":7024,"demo":false,"sanad":"","matn":["عن أَبِي بُرْدَةَ الأنصاري قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ لاَ تَجْلِدُوا فَوْقَ عَشْرَةِ أَسْوَاطٍ إِلاَّ فِي حَدٍّ مِنْ حُدُودِ اللَّهِ.","وفي لفظ: لا يُجلد فوق عشرة جلدات إلا في حدّ من حدود الله."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6850) ومسلم في الحدود (1708) كلاهما من طريق ابن وهب، أخبرني عمرو، أن بكير بن الأشجّ حدّثه قال: بينما أنا جالسٌ عند سليمان بن يسار إذ جاء عبد الرحمن بن جابر فحدّث سليمان بن يسار، ثم أقبل علينا سليمان بن يسار، فقال: حدّثني عبدالرحمن بن جابر أن أباه حدّثه، أنه سمع أبا بردة الأنصاري قال فذكره. واللفظ للبخاري. قال أبو داود: \"أبو بردة اسمه هانئ\".","grade":"متفق عليه","chapter_ar":"باب ما جاء في التعزير","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6850) and Muslim (1708). The wording is that of al-Bukhari.","chapter_en":"What Has Been Reported Regarding Discretionary Punishment","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في التعزير وحدّ السحر","group_en":"Collection of Chapters Regarding Discretionary Punishments and the Punishment for Sorcery","part_no":33,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Abu Burdah al-Ansari said: I heard the Prophet ﷺ say: “Do not lash more than ten lashes except in one of the prescribed punishments set by Allah.” In another wording: “No one is to be lashed more than ten times except in a prescribed punishment from the punishments of Allah.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6850,"lafz":true},{"key":"muslim","label":"مسلم","number":1708}],"full":1,"dr":1},{"num":7025,"demo":false,"sanad":"","matn":["عن عَبْدِ الرَّحْمَنِ بن جَابِرٍ عَمَّنْ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ عُقُوبَةَ فَوْقَ عَشْرِ ضَرَبَاتٍ إِلاَّ فِي حَدٍّ مِنْ حُدُودِ اللَّهِ."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6849) عن عمرو بن علي، حدثنا فُضيل بن سليمان، حدثنا مسلم بن أبي مريم، حدثني عبد الرحمن بن جابر فذكره. هذا الحديث رُوي من ثلاثة أوجه:","grade":"متفق عليه","chapter_ar":"باب ما جاء في التعزير","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6849) and Muslim (1708/40).","chapter_en":"What Has Been Reported Regarding Discretionary Punishment","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في التعزير وحدّ السحر","group_en":"Collection of Chapters Regarding Discretionary Punishments and the Punishment for Sorcery","part_no":33,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Abd al-Rahman ibn Jabir narrated from someone who heard the Prophet ﷺ say: “There is no punishment exceeding ten strikes except in one of the prescribed punishments set by Allah.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6849,"lafz":true},{"key":"muslim","label":"مسلم","number":40}],"full":1,"dr":1},{"num":7026,"demo":false,"sanad":"","matn":["عن ابن عمر أنهم كانوا يُضربون على عهد رسول الله صلى الله عليه وسلم إذا اشتروا طعاماً جزافاً أن يبيعوه في مكانهم حتى يُؤووه إلى رحالهم."],"takhrij":"صحيح: رواه البخاري في الحدود (6852) عن عياش بن الوليد، حدثنا عبد الأعلى، حدثنا معمر، عن الزهري، عن سالم، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في التعزير","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6852).","chapter_en":"What Has Been Reported Regarding Discretionary Punishment","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في التعزير وحدّ السحر","group_en":"Collection of Chapters Regarding Discretionary Punishments and the Punishment for Sorcery","part_no":33,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Ibn Umar reported that during the time of the Prophet ﷺ, people would be disciplined if they bought food in bulk and sold it in the same place before moving it to their own dwellings."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6852,"lafz":true}],"full":1,"rep":[5849]},{"num":7027,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّهَا قَالَتْ مَا خُيِّرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ أَمْرَيْنِ إِلاَّ أَخَذَ أَيْسَرَهُمَا، مَا لَمْ يَكُنْ إِثْمًا، فَإِنْ كَانَ إِثْمًا كَانَ أَبْعَدَ النَّاسِ مِنْهُ، وَمَا انْتَقَمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِنَفْسِهِ، إِلاَّ أَنْ تُنْتَهَكَ حُرْمَةُ اللَّهِ فَيَنْتَقِمَ لِلَّهِ."],"takhrij":"متفق عليه: رواه مالك في حسن الخلق (2) عن ابن شهاب، عن عروة بن الزبير، عن عائشة فذكرته. ورواه البخاري في المناقب (3560) ومسلم في الفضائل (2327) كلاهما من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب ما جاء في التعزير","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (2), al-Bukhari (3560), and Muslim (2327).","chapter_en":"What Has Been Reported Regarding Discretionary Punishment","part_en":"Book of Legal Punishments","group_ar":"جموع أبواب ما جاء في التعزير وحدّ السحر","group_en":"Collection of Chapters Regarding Discretionary Punishments and the Punishment for Sorcery","part_no":33,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["The Mother of the Believers, ʿA’ishah, said: Whenever the Messenger of Allah ﷺ was given a choice between two matters, he would choose the easier of the two so long as it was not sinful. But if it was sinful, he was the farthest of people from it. And the Messenger of Allah ﷺ never took revenge for himself unless the sacred limits of Allah were violated."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":2},{"key":"bukhari","label":"البخاري","number":3560,"lafz":true},{"key":"muslim","label":"مسلم","number":2327}],"full":1,"dr":1,"rep":[9491]},{"num":7028,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن مَسْعُودٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ يحلّ دَمُ امْرِئٍ مُسْلِمٍ يَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنِّي رَسُولُ اللَّهِ إِلاَّ بِإِحْدَى ثَلاَثٍ: النفس بِالنَّفْسِ، والثيب الزَّانِي، والمفارق لِدِينِهِ التارك لِلْجَمَاعَةِ."],"takhrij":"متفق عليه: رواه البخاري في الديّات (6878) ومسلم في القسامة (1676) كلاهما من طريق الأعمش، عن عبد الله بن مرة، عن مسروق، عن عبدالله بن مسعود، فذكره.","grade":"متفق عليه","chapter_ar":"باب حكم المرتد والمرتدة واستتابتهم","chapter_ur":"","part_ar":"كتاب المرتد والمحاربين وشاتم الرسول","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6878) and Muslim (1676).","chapter_en":"The Ruling on the Male and Female Apostate and Calling Them to Repent","part_en":"The Book of the Apostate, the Highway Robbers, and the One Who Insults the Messenger","group_ar":"","group_en":"","part_no":34,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Ibn Masʿud reported that the Messenger of Allah ﷺ said: “The blood of a Muslim man who testifies that there is no god but Allah and that I am the Messenger of Allah ﷺ is not lawful except in one of three cases: a life for a life, the married adulterer, and the one who abandons his religion and separates from the community.”"]},"intro":{"ar":["قال اللّٰه تعالى: (وَمَنِ يَرْتَدِدْ مِنكُمْ عَن دِينِهِ فَيَمُتْ وَهُوَ كَافِرْ فأوْلَائِكَ حَيِطَتْ أَعْمَلُهُمْ فِي الدُّنْبَارَ الآخِرَةُ وَأَوْلَٰئِكَ أَصْحَبُ النَّارِهُمْ فِيهَا خَالِدُونَ ) (سورة البقرة: ٢١٧)","وقال تعالى: ( كَيْفَ يَهْدِى اللَّهُ قَوْمًا كَفَرُواْ بَعْدَ إِيمَٰنِهِمْ وَشَهِدُوا أَنَّ الرَّسُولَ حَقُّ رَحَآءْهُمْ ألَّيَكُ وَالَّهُ لَا يَهْدِي ٱلْقَوْمَ الظَّالِمِينَ ) (سورة آل عمران: ٨٦)"],"en":["Allah the Exalted said:","“And whoever among you turns back from his religion and dies while he is a disbeliever — their deeds have become worthless in this world and the Hereafter, and they are the companions of the Fire, abiding therein forever.”","[Surah al-Baqarah: 217]","And He said:","“How shall Allah guide a people who disbelieved after their belief and after bearing witness that the Messenger is true? And Allah does not guide the wrongdoing people.”","[Surah Aal ʿImran: 86]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6878,"lafz":true},{"key":"muslim","label":"مسلم","number":1676}],"full":1},{"num":7029,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَالَّذِي لاَ إِلَهَ غَيْرُهُ، لاَ يَحِلُّ دَمُ رَجُلٍ مُسْلِمٍ يَشْهَدُ أَنْ لاَ إِلاَّ اللَّهُ، وَأَنِّي رَسُولُ اللَّهِ، إِلاَّ ثَلاَثَةُ نَفَرٍ: التَّارِكُ للإسلام الْمُفَارِقُ لِلْجَمَاعَةِ، وَالثَّيِّبُ الزَّانِي، وَالنَّفْسُ بِالنَّفْسِ."],"takhrij":"صحيح: رواه مسلم في القسامة (26:1676) عن أحمد بن حنبل ومحمد بن المثنى قالا: حدثنا عبد الرحمن بن مهدي، عن سفيان، عن الأعمش، عن عبد الله بن مرة، عن مسروق، عن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب حكم المرتد والمرتدة واستتابتهم","chapter_ur":"","part_ar":"كتاب المرتد والمحاربين وشاتم الرسول","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1676/26).","chapter_en":"The Ruling on the Male and Female Apostate and Calling Them to Repent","part_en":"The Book of the Apostate, the Highway Robbers, and the One Who Insults the Messenger","group_ar":"","group_en":"","part_no":34,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ said: “By the One besides whom there is no deity, the blood of a Muslim man who testifies that there is no god but Allah and that I am the Messenger of Allah ﷺ is not lawful except in the case of three people: the one who abandons Islam and separates from the community, the married adulterer, and a life taken for a life.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":26,"lafz":true}],"full":1,"dr":1},{"num":7030,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ يَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ، وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ إِلاَّ بِإِحْدَى ثَلاَثٍ: رَجُلٌ زَنَى بَعْدَ إِحْصَانٍ فَإِنَّهُ يُرْجَمُ، وَرَجُلٌ خَرَجَ مُحَارِبًا لِلَّهِ وَرَسُولِهِ فَإِنَّهُ يُقْتَلُ أَوْ يُصْلَبُ، أَوْ يُنْفَى مِنَ الأَرْضِ، أَوْ يَقْتُلُ نَفْسًا فَيُقْتَلُ بِهَا وَفِي رِوَايَةِ: رَجُلٌ يَخْرُجُ مِنَ الإِسْلاَمِ يحارب الله وَرَسُولِهِ فَيُقْتَلُ."],"takhrij":"صحيح: رواه أبو داود (4353)، والنسائي (4048)، والدارقطني (3/81)، والحاكم (4/367)، والبيهقي (8/283) كلهم من طريق إبراهيم بن طهمان، عن عبد العزيز بن رفيع، عن عبيد بن عمير، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب حكم المرتد والمرتدة واستتابتهم","chapter_ur":"","part_ar":"كتاب المرتد والمحاربين وشاتم الرسول","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (4353), al-Nasa’i (4048), al-Daraqutni (3/81), and al-Hakim (4/367).","chapter_en":"The Ruling on the Male and Female Apostate and Calling Them to Repent","part_en":"The Book of the Apostate, the Highway Robbers, and the One Who Insults the Messenger","group_ar":"","group_en":"","part_no":34,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿA’ishah reported that the Messenger of Allah ﷺ said: “The blood of a Muslim who testifies that there is no god but Allah and that Muhammad is the Messenger of Allah ﷺ is not lawful except in one of three cases: a man who commits adultery after being married, in which case he is stoned; a man who goes out fighting against Allah and His Messenger, in which case he is killed, crucified, or exiled from the land; or a person who kills another soul and is killed for it.” In another narration: “A man who leaves Islam and wages war against Allah and His Messenger is killed.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4353,"lafz":true},{"key":"nasai","label":"النسائي","number":4048},{"key":"sh9771","label":"الدارقطني","number":81},{"key":"hakim","label":"الحاكم","number":367}],"full":1,"dr":1},{"num":7031,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّهَا قَالَتْ لِلْأَشْتَرِ: أَنْتَ الَّذِي أَرَدْتَ قَتْلَ ابْنِ أُخْتِي؟ قَالَ: قَدْ حَرَصْتُ عَلَى قَتْلِهِ، وَحَرَصَ عَلَى قَتْلِي. قَالَتْ: أَوَ مَا عَلِمْتَ مَا قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يَحِلُّ دَمُ رَجُلٍ إِلَّا رَجُلٌ ارْتَدَّ، أَوْ تَرَكَ الْإِسْلَامَ، أَوْ زَنَى بَعْدَ مَا أُحْصِنَ، أَوْ قَتَلَ نَفْسًا بِغَيْرِ نَفْسٍ."],"takhrij":"حسن: رواه أحمد (25477) عن عبد الرحمن (بن مهدي) عن سفيان، عن أبي إسحاق، عن عمرو بن غالب، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب حكم المرتد والمرتدة واستتابتهم","chapter_ur":"","part_ar":"كتاب المرتد والمحاربين وشاتم الرسول","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (25477), al-Nasa’i (4017), and al-Tahawi in Mushkil al-Athar (1808).","chapter_en":"The Ruling on the Male and Female Apostate and Calling Them to Repent","part_en":"The Book of the Apostate, the Highway Robbers, and the One Who Insults the Messenger","group_ar":"","group_en":"","part_no":34,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿA’ishah said to al-Ashtar: “Are you the one who wanted to kill my nephew?” He replied: “I sought to kill him, and he sought to kill me.” She said: “Do you not know what the Messenger of Allah ﷺ said? ‘The blood of a man is not lawful except in the case of a man who apostatizes or leaves Islam, or commits adultery after being married, or kills a soul unlawfully.’”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4017},{"key":"sh22547","label":"الطحاوي في مشكله","number":1808},{"key":"ahmad","label":"مسند الإمام أحمد","number":25477,"n":25477,"lafz":true}],"full":1,"dr":1},{"num":7032,"demo":false,"sanad":"","matn":["عَنْ عِكْرِمَةَ، قَالَ: أُتي عَلِيٌّ رَضِيَ اللَّهِ عَنْهُ بِزَنَادِقَةٍ فَأَحْرَقَهُمْ، فَبَلَغَ ذَلِكَ ابْنَ عَبَّاسٍ فَقَالَ: لَوْ كُنْتُ أَنَا لَمْ أُحْرِقْهُمْ، لنهي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لا تعذبوا بعذاب اللَّهِ وَلَقَتَلْتُهُمْ لِقَوْلِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ بدّل دِينَهُ فَاقْتُلُوهُ."],"takhrij":"صحيح: رواه البخاري في استتابة المرتدين (6922) عن أبي النعمان محمد بن الفضل، حدّثنا حماد بن زيد، عن أيوب، عن عكرمة، فذكره.","grade":"صحيح","chapter_ar":"باب حكم المرتد والمرتدة واستتابتهم","chapter_ur":"","part_ar":"كتاب المرتد والمحاربين وشاتم الرسول","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6922).","chapter_en":"The Ruling on the Male and Female Apostate and Calling Them to Repent","part_en":"The Book of the Apostate, the Highway Robbers, and the One Who Insults the Messenger","group_ar":"","group_en":"","part_no":34,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Ikrimah said: Apostates were brought to Ali may Allah be pleased with him and he burned them. News of that reached Ibn Abbas, who said: “Had it been me, I would not have burned them, because the Messenger of Allah ﷺ forbade that, saying: ‘Do not punish with the punishment of Allah.’ Rather, I would have killed them because of the statement of the Messenger of Allah ﷺ: ‘Whoever changes his religion, kill him.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6922,"lafz":true}],"full":1,"dr":1},{"num":7033,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن عَبَّاسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ بَدَّلَ دِينَهُ فَاقْتُلُوهُ."],"takhrij":"صحيح: رواه النسائي (4065) وأحمد (2966) وصححه ابن حبان (4475) والبيهقي (8/202) كلهم من طريق عبد الصمد بن عبد الوارث، حدثنا هشام بن أبي عبد الله، عن قتادة، عن أنس أن عليا أتي بأناس من الزُّطِّ يعبدون وثنا فأحرقهم. فقال ابن عباس فذكر الحديث. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب حكم المرتد والمرتدة واستتابتهم","chapter_ur":"","part_ar":"كتاب المرتد والمحاربين وشاتم الرسول","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (4065), Ahmad (2966), authenticated by Ibn Hibban (4475), and al-Bayhaqi (8/202).","chapter_en":"The Ruling on the Male and Female Apostate and Calling Them to Repent","part_en":"The Book of the Apostate, the Highway Robbers, and the One Who Insults the Messenger","group_ar":"","group_en":"","part_no":34,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abdullah ibn Abbas reported that the Messenger of Allah ﷺ said: “Whoever changes his religion, kill him.”"]},"buhuth":{"en":["His statement, “He burned them,” means that this was based on Ali’s own judgment and reasoning. Thus, when the narration of Ibn Abbas reached him, he approved of it and returned to that opinion."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4065,"lafz":true},{"key":"ibnhibban","label":"صححه ابن حبان","number":4475,"n":1359},{"key":"kubrabayhaqi","label":"البيهقي","number":202},{"key":"ahmad","label":"مسند الإمام أحمد","number":2966,"n":2966}],"full":1,"dr":1},{"num":7034,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى، قَالَ أَقْبَلْتُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَعِي رَجُلاَنِ مِنَ الأَشْعَرِيِّينَ، أَحَدُهُمَا عَنْ يَمِينِي، وَالآخَرُ عَنْ يَسَارِي وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَاكُ فَكِلاَهُمَا سَأَلَ. فَقَالَ يَا أَبَا مُوسَى. أَوْ يَا عَبْدَ اللَّهِ بْنَ قَيْسٍ. قَالَ قُلْتُ وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا أَطْلَعَانِي عَلَى مَا فِي أَنْفُسِهِمَا، وَمَا شَعَرْتُ أَنَّهُمَا يَطْلُبَانِ الْعَمَلَ. فَكَأَنِّي أَنْظُرُ إِلَى سِوَاكِهِ تَحْتِ شَفَتِهِ قَلَصَتْ فَقَالَ لَنْ ـ أَوْ ـ لاَ نَسْتَعْمِلُ عَلَى عَمَلِنَا مَنْ أَرَادَهُ، وَلَكِنِ اذْهَبْ أَنْتَ يَا أَبَا مُوسَى ـ أَوْ يَا عَبْدَ اللَّهِ بْنَ قَيْسٍ ـ إِلَى الْيَمَنِ. ثُمَّ أَتْبَعَهُ مُعَاذُ بْنُ جَبَلٍ، فَلَمَّا قَدِمَ عَلَيْهِ أَلْقَى لَهُ وِسَادَةً قَالَ انْزِلْ، وَإِذَا رَجُلٌ عِنْدَهُ مُوثَقٌ. قَالَ مَا هَذَا قَالَ كَانَ يَهُودِيًّا فَأَسْلَمَ ثُمَّ تَهَوَّدَ. قَالَ اجْلِسْ. قَالَ لاَ أَجْلِسُ حَتَّى يُقْتَلَ. قَضَاءُ اللَّهِ وَرَسُولِهِ. ثَلاَثَ مَرَّاتٍ، فَأَمَرَ بِهِ فَقُتِلَ، ثُمَّ تَذَاكَرْنَا قِيَامَ اللَّيْلِ، فَقَالَ أَحَدُهُمَا أَمَّا أَنَا فَأَقُومُ وَأَنَامُ، وَأَرْجُو فِي نَوْمَتِي مَا أَرْجُو فِي قَوْمَتِي."],"takhrij":"متفق عليه: رواه البخاري في استتابة المرتدين (6923) ومسلم في الإمارة (15:1733) كلاهما من طريق يحيى بن سعيد القطان، حدّثنا قرة بن خالد، حدثني حميد بن هلال، حدثني أبو بردة، قال: قال أبو موسى، فذكره.","grade":"متفق عليه","chapter_ar":"باب حكم المرتد والمرتدة واستتابتهم","chapter_ur":"","part_ar":"كتاب المرتد والمحاربين وشاتم الرسول","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6923) and Muslim (1733/15).","chapter_en":"The Ruling on the Male and Female Apostate and Calling Them to Repent","part_en":"The Book of the Apostate, the Highway Robbers, and the One Who Insults the Messenger","group_ar":"","group_en":"","part_no":34,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu Musa al-Ashʿari said: I came to the Messenger of Allah ﷺ with two men from the Ashʿaris, one on my right and the other on my left, while the Messenger of Allah ﷺ was using a tooth-stick. Both men asked for positions of authority. He said: “O Abu Musa,” or “O Abdullah ibn Qays.” I said: “By the One who sent you with the truth, they did not tell me what was in their hearts, nor did I realize they were seeking leadership.” It is as though I can still see his tooth-stick beneath his lip as it lifted. He then said: “We do not appoint to our affairs one who seeks it,” or “one who desires it. But go, O Abu Musa,” or “O Abdullah ibn Qays,” “to Yemen.” Then he sent Muʿadh ibn Jabal after him. When Muʿadh arrived, Abu Musa offered him a cushion and said: “Sit.” There was a man tied up beside him. Muʿadh asked: “What is this?” He said: “He was a Jew, then accepted Islam, then returned to Judaism.” Muʿadh said: “I will not sit until he is killed — the judgment of Allah and His Messenger,” repeating it three times. Then the man was ordered to be killed. After that they discussed night prayer, and one of them said: “As for me, I pray and sleep, and I hope for reward in my sleep just as I hope for reward in my prayer.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6923,"lafz":true},{"key":"muslim","label":"مسلم","number":15}],"full":1},{"num":7035,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ مَكَّةَ عَامَ الْفَتْحِ وَعَلَى رَأْسِهِ مِغْفَرٌ فَلَمَّا نَزَعَهُ جَاءَهُ رَجُلٌ فَقَالَ ابْنُ خَطَلٍ مُتَعَلِّقٌ بِأَسْتَارِ الْكَعْبَةِ. فَقَالَ اقْتُلُوهُ."],"takhrij":"متفق عليه: رواه مالك في الحج (262) عن ابن شهاب، عن أنس بن مالك فذكره. ورواه البخاري في الجهاد (3044) ومسلم في الحج (1357) كلاهما من حديث مالك بن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب حكم المرتد والمرتدة واستتابتهم","chapter_ur":"","part_ar":"كتاب المرتد والمحاربين وشاتم الرسول","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (262), al-Bukhari (3044), and Muslim (1357).","chapter_en":"The Ruling on the Male and Female Apostate and Calling Them to Repent","part_en":"The Book of the Apostate, the Highway Robbers, and the One Who Insults the Messenger","group_ar":"","group_en":"","part_no":34,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Anas reported that the Prophet ﷺ entered Makkah on the day of the Conquest while wearing a helmet. When he removed it, a man came and said: “Ibn Khatal is clinging to the curtains of the Kaʿbah.” The Prophet ﷺ said: “Kill him.”"]},"buhuth":{"en":["This accursed man had combined three crimes, all of which made his blood lawful: murder, apostasy, and satirical abuse."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":262,"lafz":true},{"key":"bukhari","label":"البخاري","number":3044},{"key":"muslim","label":"مسلم","number":1357}],"full":1,"dr":1,"rep":[9152]},{"num":7036,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ كَانَ عَبْدُ اللَّهِ بْنُ سَعْدِ بْنِ أَبِي سَرْحٍ يَكْتُبُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَزَلَّهُ الشَّيْطَانُ فَلَحِقَ بِالْكُفَّارِ فَأَمَرَ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُقْتَلَ يَوْمَ الْفَتْحِ فَاسْتَجَارَ لَهُ عُثْمَانُ بْنُ عَفَّانَ فَأَجَارَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"حسن: رواه أبو داود (4358) والنسائي (4069) كلاهما من حديث علي بن الحسين بن واقد، عن أبيه، عن يزيد النحوي، عن عكرمة، عن ابن عباس فذكره واللفظ لأبي داود.","grade":"حسن","chapter_ar":"باب حكم المرتد والمرتدة واستتابتهم","chapter_ur":"","part_ar":"كتاب المرتد والمحاربين وشاتم الرسول","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4358) and al-Nasa’i (4069). The wording is that of Abu Dawud.","chapter_en":"The Ruling on the Male and Female Apostate and Calling Them to Repent","part_en":"The Book of the Apostate, the Highway Robbers, and the One Who Insults the Messenger","group_ar":"","group_en":"","part_no":34,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Ibn Abbas said: Abdullah ibn Saʿd ibn Abi Sarh used to write for the Messenger of Allah ﷺ, then Satan caused him to slip, and he joined the disbelievers. The Messenger of Allah ﷺ ordered that he be killed on the day of the Conquest, but Uthman ibn Affan sought protection for him, and the Messenger of Allah ﷺ granted him protection."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4358,"lafz":true},{"key":"nasai","label":"النسائي","number":4069,"n":4069}],"full":1,"dr":1},{"num":7037,"demo":false,"sanad":"","matn":["عَنْ سَعْدٍ بن أَبِي وَقَّاصٍ قَالَ: لَمَّا كَانَ يَوْمُ فَتْحِ مَكَّةَ اخْتَبَأَ عبدالله بْنُ سَعْدِ بْنِ أَبِي سرْح عِنْدَ عُثْمَانَ بْنِ عَفَّانَ، فَجَاءَ بِهِ حَتَّى أَوْقَفَهُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ. بَايِعْ عَبْدَ اللَّهِ. فَرَفَعَ رَأْسَهُ فَنَظَرَ إِلَيْهِ ثَلاَثًا، كُلُّ ذَلِكَ يَأْبَى. فَبَايَعَهُ بَعْدَ ثَلاَثٍ، ثُمَّ أَقْبَلَ عَلَى أَصْحَابِهِ فَقَالَ: أَمَا كَانَ فِيكُمْ رَجُلٌ رَشِيدٌ يَقُومُ إِلَى هَذَا حَيْثُ رَآنِي كَفَفْتُ يَدِي عَنْ بَيْعَتِهِ فَيَقْتُلَهُ فَقَالُوا: ماندري يَا رَسُولَ اللَّهِ مَا فِي نَفْسِكَ أَلاَّ أَوْمَأْتَ إِلَيْنَا بِعَيْنِكَ! قَالَ: إِنَّهُ لاَ يَنْبَغِي لِنَبِيٍّ أَنْ تَكُونَ لَهُ خَائِنَةُ الأَعْيُنِ."],"takhrij":"صحيح: رواه أبو داود (4359) والنسائي (4067) كلاهما من حديث أحمد بن المفضل، حدثنا أسباط بن نصر، قال زعم السدي، عن مصعب بن سعد، عن سعد بن أبي وقاص فذكره. وإسناده صحيح واللفظ لأبي داود.","grade":"صحيح","chapter_ar":"باب حكم المرتد والمرتدة واستتابتهم","chapter_ur":"","part_ar":"كتاب المرتد والمحاربين وشاتم الرسول","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (4359) and al-Nasa’i (4067). The wording is that of Abu Dawud.","chapter_en":"The Ruling on the Male and Female Apostate and Calling Them to Repent","part_en":"The Book of the Apostate, the Highway Robbers, and the One Who Insults the Messenger","group_ar":"","group_en":"","part_no":34,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Saʿd ibn Abi Waqqas said: On the day of the Conquest of Makkah, Abdullah ibn Saʿd ibn Abi Sarh hid with Uthman ibn Affan. Uthman brought him and stood him before the Prophet ﷺ and said: “O Messenger of Allah ﷺ, accept the pledge of Abdullah.” The Prophet ﷺ raised his head and looked at him three times, refusing each time. Then after the third time he accepted his pledge. Afterward he turned to his companions and said: “Was there not among you a wise man who would stand up and kill this man when he saw that I withheld my hand from accepting his pledge?” They said: “We did not know what was in your mind, O Messenger of Allah ﷺ. Why did you not signal to us with your eye?” He ﷺ said: “It is not appropriate for a prophet to have deceitful eyes.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4359,"lafz":true},{"key":"nasai","label":"النسائي","number":4067,"n":4067}],"full":1,"dr":1},{"num":7038,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ كَانَ رَجُلٌ مِنَ الأَنْصَارِ أَسْلَمَ ثُمَّ ارْتَدَّ وَلَحِقَ بِالشِّرْكِ ثُمَّ تَنَدَّمَ فَأَرْسَلَ إِلَى قَوْمِهِ سَلُوا لِي رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَلْ لِي مِنْ تَوْبَةٍ فَجَاءَ قَوْمُهُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا إِنَّ فُلاَنًا قَدْ نَدِمَ وَإِنَّهُ أَمَرَنَا أَنْ نَسْأَلَكَ هَلْ لَهُ مِنْ تَوْبَةٍ فَنَزَلَتْ ﴿كَيْفَ يَهْدِي اللَّهُ قَوْمًا كَفَرُوا بَعْدَ إِيمَانِهِمْ﴾ [سورة آل عمران: 86] } إِلَى قَوْلِهِ { غَفُورٌ رَحِيمٌ }. فَأَرْسَلَ إِلَيْهِ فَأَسْلَمَ."],"takhrij":"صحيح: رواه النسائي (4068) والحاكم (4/366) كلاهما من طريق داود وهو ابن أبي هند، عن عكرمة، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في توبة المرتد","chapter_ur":"","part_ar":"كتاب المرتد والمحاربين وشاتم الرسول","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (4068) and al-Hakim (4/366).","chapter_en":"What Has Been Reported Regarding the Repentance of the Apostate","part_en":"The Book of the Apostate, the Highway Robbers, and the One Who Insults the Messenger","group_ar":"","group_en":"","part_no":34,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Ibn Abbas said: A man from the Ansar accepted Islam, then apostatized and joined polytheism. Then he regretted it and sent word to his people: “Ask the Messenger of Allah ﷺ for me whether there is repentance for me.” His people came to the Messenger of Allah ﷺ and said: “So-and-so has regretted what he did, and he has instructed us to ask you whether there is repentance for him.” Then the verse was revealed: “How shall Allah guide a people who disbelieved after their belief…” up to His saying, “Forgiving, Merciful.” [Surah Aal ʿImran: 86–89] So he sent word to him, and the man accepted Islam again."]},"intro":{"ar":["قال اللّٰه تعالى: ( كَيْفَ يَهْدِى اللَّهُ قَوْمًا كَفَرُواْ بَعْدَ إِيمَٰنِهِمْ وَشَهِدُواْ أَنَّ الرَّسُولَ حَقٌّ رَجَآءَهُمُ الْيِّنَتُ وَٱللَّهُ لَا يَهْدِى الْقَومَ الظَّيِلِمِينَ أُولَئِكَ جَزَآؤُهُمْ أَنَّ عَلَيْهِمْ لَفْنَةَ اللَّهِ وَٱلْمَلَبِكَةِ وَالنَّاسِ أَجْمَعِينَ ٧ خَلِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ ١ إِلَّا الَّذِينَ تَابُواْ مِنْ بَعْدِ ذَلِكَ وَأَصْلَحُواْ فَإِنَّ الَّهَ غَفُورٌ تَحِيرٌ) [آل عمران: ٨٩-٨٦]"],"en":["Allah the Exalted said:","“How shall Allah guide a people who disbelieved after their belief, after they had testified that the Messenger is true and clear proofs had come to them? And Allah does not guide the wrongdoing people. Their recompense is that upon them is the curse of Allah, the angels, and all people. They will remain under it; the punishment will not be lightened for them, nor will they be given respite, except those who repent after that and reform, for Allah is Forgiving, Merciful.”","[Surah Aal ʿImran: 86–89]"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4068,"lafz":true,"n":4068},{"key":"hakim","label":"الحاكم","number":366}],"full":1,"dr":1},{"num":7039,"demo":false,"sanad":"","matn":["عن أنس أَنَّ نَفَرًا، مِنْ عُكْلٍ ثَمَانِيَةً قَدِمُوا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَايَعُوهُ عَلَى الإِسْلاَمِ فَاسْتَوْخَمُوا الأَرْضَ وَسَقُمَتْ أَجْسَامُهُمْ فَشَكَوْا ذَلِكَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ أَلاَ تَخْرُجُونَ مَعَ رَاعِينَا فِي إِبِلِهِ فَتُصِيبُونَ مِنْ أَبْوَالِهَا وَأَلْبَانِهَا. فَقَالُوا بَلَى. فَخَرَجُوا فَشَرِبُوا مِنْ أَبْوَالِهَا وَأَلْبَانِهَا فَصَحُّوا فَقَتَلُوا الرَّاعِيَ وَطَرَدُوا الإِبِلَ فَبَلغَ ذَلِكَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَعَثَ فِي آثَارِهِمْ فَأُدْرِكُوا فَجِيءَ بِهِمْ فَأَمَرَ بِهِمْ فَقُطِعَتْ أَيْدِيهِمْ وَأَرْجُلُهُمْ وَسُمِرَ أَعْيُنُهُمْ ثُمَّ نُبِذُوا فِي الشَّمْسِ حَتَّى مَاتُوا.","وفي رواية: فأمر بمسامير فأُحميت فكحلهم وقطع أيديهم وأرجلهم وما حسمهم، ثم أُلقوا في الحرّة يستسقون، فما سُقوا حتى ماتوا.","قال أبو قلابة: سرقوا وقتلوا وحاربو الله ورسوله."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6804) ومسلم في القسامة (1671/10) كلاهما من طريق أبي قلابة، حدثني أنس، فذكره.","grade":"متفق عليه","chapter_ar":"باب إقامة الحدّ على المحاربين ونوعه","chapter_ur":"","part_ar":"كتاب المرتد والمحاربين وشاتم الرسول","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6804) and Muslim (1671/10). The wording is that of Muslim.","chapter_en":"Carrying Out the Legal Punishment on Those Who Wage War and Its Type","part_en":"The Book of the Apostate, the Highway Robbers, and the One Who Insults the Messenger","group_ar":"","group_en":"","part_no":34,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Anas reported that eight men from Ukl came to the Messenger of Allah ﷺ and pledged allegiance to him upon Islam. They found the climate unhealthy and their bodies became ill, so they complained of that to the Messenger of Allah ﷺ. He said: “Why do you not go out with our shepherd among his camels and drink from their urine and milk?” They said: “Yes.” So they went out, drank from their urine and milk, and recovered. Then they killed the shepherd and drove away the camels. News of that reached the Messenger of Allah ﷺ, so he sent people after them. They were caught and brought back, and he ordered that their hands and feet be cut off and their eyes branded. Then they were left in the sun until they died. In another narration: He ordered nails to be heated and used on their eyes; their hands and feet were cut off and the wounds were not cauterized. Then they were thrown into the rocky area, asking for water, but they were not given water until they died. Abu Qilabah said: They stole, killed, and waged war against Allah and His Messenger."]},"intro":{"ar":["قال اللّٰه تعالى: ( إِنَّمَا جَزَوُ ٱلَّذِينَ يُحَارِبُونَ اللَّهَ وَرَسُولَهُ وَيَسْعَوْنَ فِي الْأَرْضِ ) [المائدة: ٣٣]"],"en":["Allah the Exalted said:","“The recompense of those who wage war against Allah and His Messenger and strive to spread corruption in the land…”","[Surah al-Ma’idah: 33]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6804,"lafz":true},{"key":"muslim","label":"مسلم","number":10}],"full":1,"dr":1},{"num":7040,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: إنّ قَوْمًا أَغَارُوا عَلَى لِقَاحِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَطَّعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَيْدِيَهُمْ وَأَرْجُلَهُمْ وَسَمَلَ أَعْيُنَهُمْ."],"takhrij":"حسن: رواه النسائي (4038) وابن ماجة (2579) كلاهما عن محمد بن المثنى – وقرنه ابن ماجة بمحمد بن بشار – عن إبراهيم بن أبي الوزير، قال: حدثنا الدراوردي، عن هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب إقامة الحدّ على المحاربين ونوعه","chapter_ur":"","part_ar":"كتاب المرتد والمحاربين وشاتم الرسول","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4038) and Ibn Majah (2579).","chapter_en":"Carrying Out the Legal Punishment on Those Who Wage War and Its Type","part_en":"The Book of the Apostate, the Highway Robbers, and the One Who Insults the Messenger","group_ar":"","group_en":"","part_no":34,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["ʿA’ishah said: Some people raided the milch camels of the Messenger of Allah ﷺ, so the Prophet ﷺ cut off their hands and feet and branded their eyes."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4038,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2579}],"full":1,"dr":1},{"num":7041,"demo":false,"sanad":"","matn":["عن عبد الله بن يزيد الأنصـاري قال: نهى النبي صلى الله عليه وسلم عن النهبى والمثلة."],"takhrij":"صحيح: رواه البخاري في المظالم (2474) عن آدم بن أبي إياس، حدثنا شعبة، حدثنا عدي بن ثابت، سمعت عبد الله بن يزيد الأنصاري وهو جده أبو أمه، قال: فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن المثلة","chapter_ur":"","part_ar":"كتاب المرتد والمحاربين وشاتم الرسول","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2474).","chapter_en":"The Prohibition of Mutilation","part_en":"The Book of the Apostate, the Highway Robbers, and the One Who Insults the Messenger","group_ar":"","group_en":"","part_no":34,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abdullah ibn Yazid al-Ansari said: The Prophet ﷺ forbade plunder and mutilation."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2474,"lafz":true}],"full":1,"dr":1},{"num":7042,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَحُثُّ فِي خُطْبَتِهِ عَلَى الصَّدَقَةِ وَيَنْهَى عَنِ الْمُثْلَةِ."],"takhrij":"صحيح: رواه النسائي (4047) عن محمد بن المثنى، قال: حدثنا عبدالصمد، قال: حدثنا هشام ( هو الدستوائي)، عن قتادة، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن المثلة","chapter_ur":"","part_ar":"كتاب المرتد والمحاربين وشاتم الرسول","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (4047) and Abu Dawud (4368).","chapter_en":"The Prohibition of Mutilation","part_en":"The Book of the Apostate, the Highway Robbers, and the One Who Insults the Messenger","group_ar":"","group_en":"","part_no":34,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ used to encourage charity in his sermon and forbid mutilation."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4047,"lafz":true},{"key":"abudawud","label":"أبو داود","number":4368}],"full":1,"dr":1,"rep":[6845]},{"num":7043,"demo":false,"sanad":"","matn":["عَنِ الْهَيَّاجِ بْنِ عِمْرَانَ، أَنَّ عِمْرَانَ، أَبَقَ لَهُ غُلاَمٌ فَجَعَلَ لِلَّهِ عَلَيْهِ لَئِنْ قَدَرَ عَلَيْهِ لَيَقْطَعَنَّ يَدَهُ فَأَرْسَلَنِي لأَسْأَلَ لَهُ فَأَتَيْتُ سَمُرَةَ بْنَ جُنْدَبٍ فَسَأَلْتُهُ فَقَالَ كَانَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَحُثُّنَا عَلَى الصَّدَقَةِ وَيَنْهَانَا عَنِ الْمُثْلَةِ فَأَتَيْتُ عِمْرَانَ بْنَ حُصَيْنٍ فَسَأَلْتُهُ فَقَالَ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَحُثُّنَا عَلَى الصَّدَقَةِ وَيَنْهَانَا عَنِ الْمُثْلَةِ."],"takhrij":"حسن: رواه أبوداود (2667) عن محمد بن المثنى، حدثنا معاذ بن هشام، حدثني أبي، عن قتادة، عن الحسن، عن الهياج بن عمران فذكره.","grade":"حسن","chapter_ar":"باب النهي عن المثلة","chapter_ur":"","part_ar":"كتاب المرتد والمحاربين وشاتم الرسول","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2667).","chapter_en":"The Prohibition of Mutilation","part_en":"The Book of the Apostate, the Highway Robbers, and the One Who Insults the Messenger","group_ar":"","group_en":"","part_no":34,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Al-Hayyaj ibn Imran reported that a slave boy belonging to Imran ran away, so Imran vowed to Allah that if he caught him, he would cut off his hand. He sent me to ask about this for him. I came to Samurah ibn Jundub and asked him, and he said: “The Prophet of Allah ﷺ used to encourage us to give charity and forbid us from mutilation.” Then I came to Imran ibn Husayn and asked him, and he said: “The Messenger of Allah ﷺ used to encourage us to give charity and forbid us from mutilation.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2667,"lafz":true}],"full":1,"dr":1},{"num":7044,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ أَنَّ أَعْمَى، كَانَتْ لَهُ أُمُّ وَلَدٍ تَشْتُمُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَتَقَعُ فِيهِ فَيَنْهَاهَا فَلاَ تَنْتَهِي وَيَزْجُرُهَا فَلاَ تَنْزَجِرُ - قَالَ - فَلَمَّا كَانَتْ ذَاتَ لَيْلَةٍ جَعَلَتْ تَقَعُ فِي النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَتَشْتِمُهُ فَأَخَذَ الْمِغْوَلَ فَوَضَعَهُ فِي بَطْنِهَا وَاتَّكَأَ عَلَيْهَا فَقَتَلَهَا فَوَقَعَ بَيْنَ رِجْلَيْهَا طِفْلٌ فَلَطَخَتْ مَا هُنَاكَ بِالدَّمِ فَلَمَّا أَصْبَحَ ذُكِرَ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَمَعَ النَّاسَ فَقَالَ أَنْشُدُ اللَّهَ رَجُلاً فَعَلَ مَا فَعَلَ لِي عَلَيْهِ حَقٌّ إِلاَّ قَامَ. فَقَامَ الأَعْمَى يَتَخَطَّى النَّاسَ وَهُوَ يَتَزَلْزَلُ حَتَّى قَعَدَ بَيْنَ يَدَىِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ يَا رَسُولَ اللَّهِ أَنَا صَاحِبُهَا كَانَتْ تَشْتِمُكَ وَتَقَعُ فِيكَ فَأَنْهَاهَا فَلاَ تَنْتَهِي وَأَزْجُرُهَا فَلاَ تَنْزَجِرُ وَلِي مِنْهَا ابْنَانِ مِثْلُ اللُّؤْلُؤَتَيْنِ وَكَانَتْ بِي رَفِيقَةً فَلَمَّا كَانَتِ الْبَارِحَةَ جَعَلَتْ تَشْتِمُكَ وَتَقَعُ فِيكَ فَأَخَذْتُ الْمِغْوَلَ فَوَضَعْتُهُ فِي بَطْنِهَا وَاتَّكَأْتُ عَلَيْهَا حَتَّى قَتَلْتُهَا. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَلاَ اشْهَدُوا أَنَّ دَمَهَا هَدَرٌ."],"takhrij":"حسن: رواه أبو داود (4361) والنسائي (4070) وابن أبي عاصم في الديات (299)، والدارقطني (3/112)، والحاكم (4/354) كلهم من طريق إسرائيل، عن عثمان الشحام، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب محاكمة من سب النبي ﷺ وأساء إليه","chapter_ur":"","part_ar":"كتاب المرتد والمحاربين وشاتم الرسول","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4361), al-Nasa’i (4070), Ibn Abi Asim in al-Diyat (299), and al-Daraqutni (3/112).","chapter_en":"The Trial of One Who Insults the Prophet ﷺ and Abuses Him","part_en":"The Book of the Apostate, the Highway Robbers, and the One Who Insults the Messenger","group_ar":"","group_en":"","part_no":34,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn Abbas reported that a blind man had a slave woman who had borne him children. She used to insult the Messenger of Allah ﷺ and speak abusively about him. He would forbid her, but she would not stop; he would rebuke her, but she would not desist. One night she began speaking abusively about the Prophet ﷺ and insulting him, so he took a short sword, placed it against her abdomen, and leaned upon it until he killed her. A child fell between her legs, and the area became stained with blood. When morning came, the matter was mentioned to the Messenger of Allah ﷺ. He gathered the people and said: “I ask by Allah that the man who did what was done, and over whom I have a right, stand up.” The blind man stood, stepping over the people while trembling, until he sat before the Prophet ﷺ and said: “O Messenger of Allah ﷺ, I am the one who did it. She used to insult you and speak abusively about you. I would forbid her, but she would not stop; I would rebuke her, but she would not desist. I have two sons from her like two pearls, and she was kind to me. But last night she began insulting you and speaking abusively about you, so I took the short sword, placed it against her abdomen, and leaned upon it until I killed her.” The Prophet ﷺ said: “Bear witness that her blood is unprotected.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4361,"lafz":true},{"key":"nasai","label":"النسائي","number":4070},{"key":"rb280","label":"ابن أبي عاصم في الديات","number":299},{"key":"sh9771","label":"الدار قطني","number":112}],"full":1,"dr":1},{"num":7045,"demo":false,"sanad":"","matn":["عَنْ جابر بْنِ عَبْدِ اللَّهِ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ لِكَعْبِ بْنِ الأَشْرَفِ، فَإِنَّهُ آذَى اللَّهَ وَرَسُولَهُ؟ فَقَالَ مُحَمَّدُ بْنُ مَسْلَمَةَ: أنا يَا رَسُولَ اللَّهِ! أتحبُّ أَنْ أَقْتُلَهُ؟ قَالَ: نَعَمْ فَذَهَبَ فَقَتَلَهُ."],"takhrij":"متفق عليه: رواه البخاري في الرهن (2510) ومسلم في الجهاد (1801) كلاهما من حديث سفيان، عن عمرو، عن جابر فذكره مختصرا ومطولا.","grade":"متفق عليه","chapter_ar":"باب محاكمة من سب النبي ﷺ وأساء إليه","chapter_ur":"","part_ar":"كتاب المرتد والمحاربين وشاتم الرسول","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2510) and Muslim (1801).","chapter_en":"The Trial of One Who Insults the Prophet ﷺ and Abuses Him","part_en":"The Book of the Apostate, the Highway Robbers, and the One Who Insults the Messenger","group_ar":"","group_en":"","part_no":34,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said: “Who will deal with Kaʿb ibn al-Ashraf? He has harmed Allah and His Messenger.” Muhammad ibn Maslamah said: “I will, O Messenger of Allah ﷺ. Do you want me to kill him?” He said: “Yes.” So he went and killed him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2510,"lafz":true},{"key":"muslim","label":"مسلم","number":1801}],"full":1},{"num":7046,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَرْزَةَ، قَالَ كُنْتُ عِنْدَ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُ فَتَغَيَّظَ عَلَى رَجُلٍ فَاشْتَدَّ عَلَيْهِ فَقُلْتُ تَأْذَنُ لِي يَا خَلِيفَةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَضْرِبُ عُنُقَهُ قَالَ فَأَذْهَبَتْ كَلِمَتِي غَضَبَهُ فَقَامَ فَدَخَلَ فَأَرْسَلَ إِلَىَّ فَقَالَ مَا الَّذِي قُلْتَ آنِفًا قُلْتُ ائْذَنْ لِي أَضْرِبْ عُنُقَهُ. قَالَ أَكُنْتَ فَاعِلاً لَوْ أَمَرْتُكَ قُلْتُ نَعَمْ. قَالَ لاَ وَاللَّهِ مَا كَانَتْ لِبَشَرٍ بَعْدَ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه أبو داود (4363) والنسائي (4077) وأحمد (61) وابن أبي عاصم في الديات (302) كلهم من طريق يزيد بن زريع، عن يونس بن عبيد، عن حميد بن هلال، عن عبد الله بن مطرف، عن أبي برزة فذكره.","grade":"صحيح","chapter_ar":"باب محاكمة من سب النبي ﷺ وأساء إليه","chapter_ur":"","part_ar":"كتاب المرتد والمحاربين وشاتم الرسول","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (4363), al-Nasa’i (4077), Ahmad (61), and Ibn Abi Asim in al-Diyat (302).","chapter_en":"The Trial of One Who Insults the Prophet ﷺ and Abuses Him","part_en":"The Book of the Apostate, the Highway Robbers, and the One Who Insults the Messenger","group_ar":"","group_en":"","part_no":34,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abu Barzah said: I was with Abu Bakr may Allah be pleased with him when he became angry with a man and spoke harshly to him. I said: “Will you permit me, O successor of the Messenger of Allah ﷺ, to strike his neck?” My words caused his anger to leave him. He got up, entered his house, then sent for me and said: “What did you say just now?” I said: “Permit me to strike his neck.” He said: “Would you have done it if I had ordered you?” I said: “Yes.” He said: “No, by Allah, that was not for any human being after Muhammad ﷺ.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4363,"lafz":true},{"key":"nasai","label":"النسائي","number":4077},{"key":"rb280","label":"ابن أبي عاصم في الديات","number":302},{"key":"ahmad","label":"مسند الإمام أحمد","number":61,"n":61}],"full":1,"dr":1},{"num":7047,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: كَانَ رَجُلٌ نَصْرَانِيًّا، فَأَسْلَمَ، وَقَرَأَ الْبَقَرَةَ وَآلَ عِمْرَانَ. فَكَانَ يَكْتُبُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَعَادَ نَصْرَانِيًّا فَكَانَ يَقُولُ: مَا يَدْرِي مُحَمَّدٌ إِلاَّ مَا كَتَبْتُ لَهُ. فَأَمَاتَهُ اللَّهُ فَدَفَنُوهُ. فَأَصْبَحَ وَقَدْ لَفَظَتْهُ الأَرْضُ، فَقَالُوا: هَذَا فِعْلُ مُحَمَّدٍ وَأَصْحَابِهِ لَمَّا هَرَبَ مِنْهُمْ. نَبَشُوا عَنْ صَاحِبِنَا لَمَّا هَرَبَ مِنْهُمْ فألقوه. فَحَفَرُوا لَهُ، وَأَعْمَقُوا لَهُ فِي الأرض مَا اسْتَطَاعُوا. فَأَصْبَحَ قَدْ لَفَظَتْهُ الأَرْضُ. فَعَلِمُوا: أَنَّهُ لَيْسَ مِنَ النَّاسِ فألقوه."],"takhrij":"متفق عليه: رواه البخاري في المناقب (3617) عن أبي معمر، حدثنا عبد الوارث، حدثنا عبد العزيز، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب من افترى على النبي ﷺ والله","chapter_ur":"","part_ar":"كتاب المرتد والمحاربين وشاتم الرسول","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3617) and Muslim (2781).","chapter_en":"One Who Fabricates Lies Against the Prophet ﷺ and Allah","part_en":"The Book of the Apostate, the Highway Robbers, and the One Who Insults the Messenger","group_ar":"","group_en":"","part_no":34,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Anas said: There was a Christian man who accepted Islam and recited al-Baqarah and Aal ʿImran. He used to write for the Prophet ﷺ. Then he returned to Christianity and would say: “Muhammad knows nothing except what I wrote for him.” Allah caused him to die, and they buried him. In the morning, the earth had cast him out. They said: “This is the work of Muhammad and his companions. When he fled from them, they dug up our companion and threw him out.” So they dug a deeper grave for him. In the morning, the earth had cast him out again. They said: “This is the work of Muhammad and his companions. They dug up our companion when he fled from them and threw him out.” So they dug for him and made the grave as deep as they could. In the morning, the earth had cast him out again. Then they knew that this was not from people, so they left him."]},"buhuth":{"en":["Jurisprudence of this chapter:","Anyone who insults the Messenger ﷺ or fabricates lies against him must be referred to the proper authority; no individual may take criminal action on their own, for Islam forbids that. However, Muslims may demand, especially from Western societies, that anyone who insults the Islamic religion, the Messenger ﷺ, or the Noble Qur’an be criminalized.","The United Nations has issued a resolution requiring respect for all religions, but Western media deliberately insults Islam alone under the name of “freedom of expression,” while it is unable to insult Judaism. A number of journalists and writers who spoke about the “Holocaust” have been prosecuted, which is a double standard and unequal measure. Despite all of this, we Muslims affirm to everyone that Islam is a religion of love, peace, mercy, and guidance; that respecting all prophets and messengers is part of our faith; and that those who commit criminal acts are not accepted by Islam and do not represent Muslims. But “freedom of expression” does not permit hurting the feelings of others regarding their beliefs."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3617,"lafz":true},{"key":"muslim","label":"مسلم","number":2781}],"full":1,"dr":1},{"num":7048,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ تَزَالُ جَهَنَّمُ تَقُولُ هَلْ مِنْ مَزِيدٍ حَتَّى يَضَعَ رَبُّ الْعِزَّةِ فِيهَا قَدَمَهُ فَتَقُولُ قَطْ قَطْ وَعِزَّتِكَ. وَيُزْوَى بَعْضُهَا إِلَى بَعْضٍ."],"takhrij":"متفق عليه: رواه البخاري في الأيمان والنذور (6661) ومسلم في الجنة وصفة نعيمها (37:2848) كلاهما من طريق شيبان، عن قتادة، حدّثنا أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب في الحلف بصفة من صفات الله تعالى","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6661) and Muslim (2848).","chapter_en":"Swearing by One of the Attributes of Allah the Exalted","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Anas said: The Prophet ﷺ said: “Hellfire will continue saying: ‘Is there any more?’ until the Lord of Might places His Foot upon it, and it will say: ‘Enough, enough, by Your Might,’ and parts of it will draw together upon others.”"]},"intro":{"ar":["قال اللّٰه تعالى خبراً عن إبليس:","﴿قَالَ فَبِعِزَّتِكَ لَأُغْوِيَنَّهُمْ أَجْمَعِينَ ۝ إِلَّا عِبَادَكَ مِنْهُمُ الْمُخْلَصِينَ﴾ [سورة ص: ٨٢-٨٣]"],"en":["Allah the Exalted said, informing about Iblis:","“He said: ‘By Your Might, I will surely mislead them all, except Your sincere servants among them.’” [Surah Sad: 82–83]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6661,"lafz":true},{"key":"muslim","label":"مسلم","number":2848},{"key":"muslim","label":"مسلم في الجنه وصفه نعيمها","number":37}],"full":1,"rep":[359,16449]},{"num":7049,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ، عن النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَيَبْقَى رَجُلٌ مُقْبِلٌ بِوَجْهِهِ عَلَى النَّارِ فَيَقُولُ يَا رَبِّ قَدْ قَشَبَنِي رِيحُهَا وَأَحْرَقَنِي ذَكَاؤُهَا، فَاصْرِفْ وَجْهِي عَنِ النَّارِ فَلاَ يَزَالُ يَدْعُو اللَّهَ. فَيَقُولُ لَعَلَّكَ إِنْ أَعْطَيْتُكَ أَنْ تَسْأَلَنِي غَيْرَهُ. فَيَقُولُ لاَ وَعِزَّتِكَ لاَ أَسْأَلُكَ غَيْرَهُ. فَيَصْرِفُ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6573) ومسلم في الإيمان (299:182) كلاهما من طريق ابن شهاب الزهري، عن عطاء بن يزيد الليثي، عن أبي هريرة. فذكر الحديث بطوله.","grade":"متفق عليه","chapter_ar":"باب في الحلف بصفة من صفات الله تعالى","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6573) and Muslim (299:182).","chapter_en":"Swearing by One of the Attributes of Allah the Exalted","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “… A man will remain facing the Fire and will say: ‘My Lord, its smell has harmed me and its blaze has burned me, so turn my face away from the Fire.’ He will continue supplicating to Allah, and Allah will say: ‘Perhaps if I grant you this, you will ask Me for something else?’ He will say: ‘No, by Your Might, I will not ask You for anything else.’…” The hadith continues."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6573,"lafz":true},{"key":"muslim","label":"مسلم","number":182},{"key":"muslim","label":"مسلم في الايمان","number":299}],"full":1},{"num":7050,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَمَّا خَلَقَ اللهُ الْجَنَّةَ وَالنَّارَ، أَرْسَلَ جِبْرِيلَ – عَلَيْهِ السلام – إِلَى الْجَنَّةَ، فَقَالَ: انْظُرْ إِلَيْهَا، وَإِلَى مَا أَعْدَدْتُ لِأَهْلِهَا فِيهَا، فَنَظَرَ إِلَيْهَا، فَرَجَعَ، فقَالَ: وَعِزَّتِكَ، لَا يَسْمَعُ بِهَا أَحَدٌ إِلَّا دَخَلَهَا، فَأَمَرَ بِهَا، فَحُفَّتْ بِالْمَكَارِهِ، فَقَالَ: اذْهَبْ إِلَيْهَا، فَانْظُرْ إِلَيْهَا، وَإِلَى مَا أَعْدَدْتُ لِأَهْلِهَا فِيهَا، فَإِذَا هِيَ قَدْ حفت بِالْمَكَارِهِ، فَقَالَ: وَعِزَّتِكَ، لَقَدْ خَشِيتُ أَنْ لَا يَدْخُلَهَا أَحَدٌ، قَالَ: اذْهَبْ فَانْظُرْ إِلَى النَّارِ، وَإِلَى مَا أَعْدَدْتُ لِأَهْلِهَا فِيهَا، فَنَظَرَ إِلَيْهَا، فَإِذَا هِيَ يَرْكَبُ بَعْضُهَا بَعْضًا، فَرَجَعَ، فقَالَ: وَعِزَّتِكَ، لَا يَدْخُلَهَا أَحَدٌ، فَأَمَرَ بِهَا، فَحُفَّتْ بِالشَّهَوَاتِ، فَقَالَ: ارْجِعْ فَانْظُرْ إِلَيْهَا، فَنَظَرَ إِلَيْهَا، فَإِذَا هِيَ قَدْ حفت بِالشَّهَوَاتِ، فَرَجَعَ، وَقَالَ: وَعِزَّتِكَ، لَقَدْ خَشِيتُ أَنْ لَا يَنْجُوَ مِنْهَا أَحَدٌ إِلَّا دَخَلَهَا."],"takhrij":"حسن: رواه النسائي (3763) والترمذي (2560) وأحمد (8398) كلهم من حديث محمد بن عمرو، حدثنا أبو سلمة، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب في الحلف بصفة من صفات الله تعالى","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (3763), al-Tirmidhi (2560), and Ahmad (8398). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"Swearing by One of the Attributes of Allah the Exalted","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “When Allah created Paradise and Hellfire, He sent Jibril peace be upon him to Paradise and said: ‘Look at it and at what I have prepared in it for its people.’ So he looked at it and returned and said: ‘By Your Might, no one who hears of it will fail to enter it.’ Then Allah commanded that it be surrounded by hardships. Then He said: ‘Return to it and look at it and what I have prepared for its people in it.’ So he saw that it had been surrounded by hardships, and he said: ‘By Your Might, I fear that no one will enter it.’ Then He said: ‘Go and look at the Fire and at what I have prepared in it for its people.’ So he looked at it, and parts of it were consuming other parts. He returned and said: ‘By Your Might, no one who hears of it will enter it.’ Then Allah commanded that it be surrounded by desires. Then He said: ‘Return and look at it.’ So he returned and saw that it had been surrounded by desires. He returned and said: ‘By Your Might, I fear that no one will be saved from it except that he enters it.’”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3763,"lafz":true,"n":3763},{"key":"tirmidhi","label":"الترمذي","number":2560},{"key":"ahmad","label":"مسند الإمام أحمد","number":8398,"n":8398}],"full":1,"dr":1},{"num":7051,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْثًا وَأَمَّرَ عَلَيْهِمْ أُسَامَةَ بْنَ زَيْدٍ، فَطَعَنَ بَعْضُ النَّاسِ فِي إِمْرَتِهِ فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ إِنْ كُنْتُمْ تَطْعَنُونَ فِي إِمْرَتِهِ فَقَدْ كُنْتُمْ تَطْعَنُونَ، فِي إِمْرَةِ أَبِيهِ مِنْ قَبْلُ، وَايْمُ اللَّهِ إِنْ كَانَ لَخَلِيقًا لِلإِمَارَةِ، وَإِنْ كَانَ لَمِنْ أَحَبِّ النَّاسِ إِلَىَّ، وَإِنَّ هَذَا لَمِنْ أَحَبِّ النَّاسِ إِلَىَّ بَعْدَهُ."],"takhrij":"متفق عليه: رواه البخاري في الأيمان والنذور (6627) ومسلم في الفضائل (63:2426) كلاهما من طريق إسماعيل بن جعفر، عن عبد الله بن دينار، أنه سمع ابن عمر يقول، فذكره.","grade":"متفق عليه","chapter_ar":"باب القسم بـ «وأيم الله»","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6627) and Muslim (2426:63).","chapter_en":"Swearing by Saying “Wa Aymu Allah”","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ dispatched an expedition and appointed Usamah ibn Zayd over them. Some people criticized his leadership, so the Messenger of Allah ﷺ stood and said: “If you criticize his leadership, then you had previously criticized the leadership of his father before him. By Allah, he was truly worthy of leadership, and he was among the most beloved people to me, and this one is among the most beloved people to me after him.”"]},"buhuth":{"en":["Muslim also narrated through another chain with the wording:","“If you criticize his leadership — meaning Usamah ibn Zayd — then you had criticized the leadership of his father before him. By Allah, he was worthy of it. By Allah, he was among the most beloved people to me. By Allah, this one is worthy of it — meaning Usamah ibn Zayd — and by Allah, he is among the most beloved of them to me after him. So I advise you to treat him well, for he is among your righteous people.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6627,"lafz":true},{"key":"muslim","label":"مسلم","number":63}],"full":1,"dr":1},{"num":7052,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ سُلَيْمَانُ لأَطُوفَنَّ اللَّيْلَةَ عَلَى تِسْعِينَ امْرَأَةً، كُلُّهُنَّ تَأْتِي بِفَارِسٍ يُجَاهِدُ فِي سَبِيلِ اللَّهِ. فَقَالَ لَهُ صَاحِبُهُ إِنْ شَاءَ اللَّهُ. فَلَمْ يَقُلْ إِنْ شَاءَ اللَّهُ. فَطَافَ عَلَيْهِنَّ جَمِيعًا، فَلَمْ تَحْمِلْ مِنْهُنَّ إِلاَّ امْرَأَةٌ وَاحِدَةٌ، جَاءَتْ بِشِقِّ رَجُلٍ، وَايْمُ الَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ لَوْ قَالَ إِنْ شَاءَ اللَّهُ. لَجَاهَدُوا فِي سَبِيلِ اللَّهِ فُرْسَانًا أَجْمَعُونَ."],"takhrij":"متفق عليه: رواه البخاري في الأيمان والنذور (6639) ومسلم في الأيمان والنذور (25:1654) كلاهما من طريق عبد الرحمن بن هرمز الأعرج عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب القسم بـ «وأيم الذي نفس محمد بيده»","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6639) and Muslim (1654:25).","chapter_en":"Swearing by Saying “By the One in Whose Hand is the Soul of Muhammad”","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Sulayman said: ‘Tonight I will go around to ninety women, and each of them will give birth to a horseman who will fight in the cause of Allah.’ His companion said to him: ‘Say: If Allah wills.’ But he did not say: ‘If Allah wills.’ So he went around to all of them, but none of them conceived except one woman, who gave birth to half a man. By the One in Whose Hand is the soul of Muhammad, had he said: ‘If Allah wills,’ they all would have fought in the cause of Allah as horsemen.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6639,"lafz":true},{"key":"muslim","label":"مسلم","number":1654,"n":4289},{"key":"muslim","label":"مسلم في الايمان والنذور","number":25}],"full":1,"rep":[8459,8462,12687]},{"num":7053,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِنَّ أَهْلَ الْجَنَّةِ يَتَرَاءَيُونَ أَهْلَ الْغُرَفِ مِنْ فَوْقِهِمْ كَمَا يَتَرَاءَيُونَ الْكَوْكَبَ الدُّرِّيَّ الْغَابِرَ فِي الأُفُقِ مِنَ الْمَشْرِقِ أَوِ الْمَغْرِبِ، لِتَفَاضُلِ مَا بَيْنَهُمْ. قَالُوا يَا رَسُولَ اللَّهِ، تِلْكَ مَنَازِلُ الأَنْبِيَاءِ لاَ يَبْلُغُهَا غَيْرُهُمْ قَالَ بَلَى وَالَّذِي نَفْسِي بِيَدِهِ، رِجَالٌ آمَنُوا بِاللَّهِ وَصَدَّقُوا الْمُرْسَلِينَ."],"takhrij":"متفق عليه: رواه البخاري في بدء الخلق (3256) ومسلم في الجنة وصفة نعيمها وأهلها (2831) كلاهما من طريق مالك بن أنس، عن صفوان بن سُليم، عن عطاء بن يسار، عن أبي سعيد الخدري، فذكره.","grade":"متفق عليه","chapter_ar":"باب القسم بـ «والذي نفسي بيده»","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3256) and Muslim (2831).","chapter_en":"Swearing by Saying “By the One in Whose Hand is My Soul”","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated from the Prophet ﷺ that he said: “The people of Paradise will look at the people of the lofty chambers above them just as you look at a shining star remaining on the horizon in the east or west, because of the superiority between them.” They said: “O Messenger of Allah ﷺ, those are the ranks of the Prophets which no one else can attain.” He said: “Yes, by the One in Whose Hand is my soul, they are men who believed in Allah and believed the Messengers.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3256,"lafz":true},{"key":"muslim","label":"مسلم","number":2831,"n":7143}],"full":1,"rep":[12353,12729,13120,13501,16273]},{"num":7054,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا هَلَكَ كِسْرَى فَلاَ كِسْرَى بَعْدَهُ، وَإِذَا هَلَكَ قَيْصَرُ فَلاَ قَيْصَرَ بَعْدَهُ، وَالَّذِي نَفْسِي بِيَدِهِ، لَتُنْفَقَنَّ كُنُوزُهُمَا فِي سَبِيلِ اللَّهِ."],"takhrij":"متفق عليه: رواه البخاري في فرض الخمس (3121) ومسلم في الفتن (2919) كلاهما من حديث جرير، عن عبد الملك بن عمير، عن جابر بن سمرة فذكره.","grade":"متفق عليه","chapter_ar":"باب القسم بـ «والذي نفسي بيده»","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3121) and Muslim (2919). The wording is that of al-Bukhari.","chapter_en":"Swearing by Saying “By the One in Whose Hand is My Soul”","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Jabir ibn Samurah said: The Messenger of Allah ﷺ said: “When Kisra perishes, there will be no Kisra after him, and when Caesar perishes, there will be no Caesar after him. By the One in Whose Hand is my soul, their treasures will surely be spent in the cause of Allah.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3121,"lafz":true},{"key":"muslim","label":"مسلم","number":2919}],"full":1,"dr":1,"rep":[9733]},{"num":7055,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ قَالَ لَهَا أَهْلُ الإِفْكِ مَا قَالُوا، فَبَرَّأَهَا اللَّهُ، فَقَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاسْتَعْذَرَ مِنْ عَبْدِ اللَّهِ بْنِ أَبِي، فَقَامَ أُسَيْدُ بْنُ حُضَيْرٍ، فَقَالَ لِسَعْدِ بْنِ عُبَادَةَ: لَعَمْرُ اللَّهِ لَنَقْتُلَنَّهُ."],"takhrij":"متفق عليه: رواه البخاري في الأيمان والنذور (6662) ومسلم في التوبة (56:2770) من طريق عن الزهري، سمعت عروة بن الزبير، وسعيد بن المسيب، وعلقمة بن وقاص، وعبيد الله بن عبد الله عن حديث عائشة زوج النبي صلى الله عليه وسلم حين قال لها أهل الإفك ما قالوا، فبرأها الله، وكلّ حدثني طائفة من الحديث، فذكره والسياق للبخاري في هذا الموضع، وهو عند مسلم بطوله وتمامه.","grade":"متفق عليه","chapter_ar":"باب القسم بـ «لَعَمْرُ الله»","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6662) and Muslim (2770/56).","chapter_en":"Swearing by Saying “LaʿAmru Allah”","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["ʿĀ’ishah, the wife of the Prophet ﷺ, reported concerning the false accusation made against her, after Allah declared her innocent: The Prophet ﷺ stood and sought to be excused regarding ʿAbdullāh ibn Ubayy. Usayd ibn Ḥuḍayr then stood and said to Saʿd ibn ʿUbādah: “By the life of Allah, we will surely kill him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6662,"lafz":true},{"key":"muslim","label":"مسلم","number":2770},{"key":"muslim","label":"مسلم في التوبه","number":56}],"full":1},{"num":7056,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عُمَرَ قَالَ: كَثِيرًا مَا كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَحْلِفُ بِهَذِهِ اليمين: لاَ وَمُقَلِّبِ الْقُلُوبِ."],"takhrij":"صحيح: رواه البخاري في الأيمان والنذور (6628) عن محمد بن يوسف، عن سفيان، عن موسى بن عقبة، عن سالم، عن عبد الله بن عمر فذكره.","grade":"صحيح","chapter_ar":"باب الحلف بـ «لا ومقلب القلوب»","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6628).","chapter_en":"Swearing by Saying “No, by the Turner of Hearts”","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: The Messenger of Allah ﷺ would frequently swear with this oath: “No, by the Turner of hearts.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6628,"lafz":true}],"full":1},{"num":7057,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، قَالَ انْتَهَيْتُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ جَالِسٌ فِي ظِلِّ الْكَعْبَةِ. فَلَمَّا رَآنِي قَالَ هُمُ الأَخْسَرُونَ وَرَبِّ الْكَعْبَةِ. قَالَ فَجِئْتُ حَتَّى جَلَسْتُ فَلَمْ أَتَقَارَّ أَنْ قُمْتُ فَقُلْتُ يَا رَسُولَ اللَّهِ فِدَاكَ أَبِي وَأُمِّي مَنْ هُمْ قَالَ هُمُ الأَكْثَرُونَ أَمْوَالاً إِلاَّ مَنْ قَالَ هَكَذَا وَهَكَذَا وَهَكَذَا - مِنْ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِ وَعَنْ يَمِينِهِ وَعَنْ شِمَالِهِ -"],"takhrij":"متفق عليه: رواه البخاري في الأيمان والنذور (6638) ومسلم في الزكاة (30:990) كلاهما من طريق الأعمش، عن المعرور بن سويد، عن أبي ذر، فذكره، والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"باب القسم بـ «ورب الكعبة»","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6638) and Muslim (990:30). The wording is that of Muslim.","chapter_en":"Swearing by Saying “By the Lord of the Kaʿbah”","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Abu Dharr said: I came to the Prophet ﷺ while he was sitting in the shade of the Kaʿbah. When he saw me, he said: “They are the greatest losers, by the Lord of the Kaʿbah.” I came and sat down, but I could not remain still, so I stood and said: “O Messenger of Allah ﷺ, may my father and mother be sacrificed for you, who are they?” He said: “They are those with the most wealth, except for those who give like this and this and this” — from in front of them, behind them, to their right, and to their left — the hadith continues."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6638,"lafz":true},{"key":"muslim","label":"مسلم","number":990},{"key":"muslim","label":"مسلم في الزكاه","number":30}],"full":1},{"num":7058,"demo":false,"sanad":"","matn":["عن حَارِثَةَ بن وَهْبٍ قَالَ سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ أَلاَ أَدُلُّكُمْ عَلَى أَهْلِ الْجَنَّةِ، كُلُّ ضَعِيفٍ مُتَضَعَّفٍ، لَوْ أَقْسَمَ عَلَى اللَّهِ لأَبَرَّهُ، وَأَهْلِ النَّارِ كُلُّ جَوَّاظٍ عُتُلٍّ مُسْتَكْبِرٍ."],"takhrij":"متفق عليه: رواه البخاري في الأيمان والنذور (6657) ومسلم في الجنة (2853) كلاهما من طريق شعبة، حدثني معبد بن خالد، أنه سمع حارثة بن وهب، فذكره.","grade":"متفق عليه","chapter_ar":"باب صفة من يبرّ الله قسمه","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6657) and Muslim (2853).","chapter_en":"The Description of One Whose Oath Allah Fulfills","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Harithah ibn Wahb said: I heard the Prophet ﷺ saying: “Shall I not inform you about the people of Paradise? Every weak and humble person — if he were to swear by Allah, Allah would fulfill his oath. And the people of the Fire are every harsh, arrogant, and proud person.”"]},"buhuth":{"en":["His statement: “Every weak person” means poor.","“Considered weak” means that people regard him as weak and insignificant.","“If he were to swear by Allah, Allah would fulfill his oath” means that if he were to swear concerning something, hoping in Allah’s generosity to honor his oath, Allah would fulfill it for his sake.","“Al-Jawwaz” refers to one who is arrogant and boastful in his manner of walking."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6657,"lafz":true},{"key":"muslim","label":"مسلم","number":2853}],"full":1,"dr":1},{"num":7059,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ رُبَّ أَشْعَثَ مَدْفُوعٍ بِالأَبْوَابِ لَوْ أَقْسَمَ عَلَى اللَّهِ لأَبَرَّهُ."],"takhrij":"صحيح: رواه مسلم في البر والصلة والآداب (2622) عن سويد بن سعيد، حدثني حفص بن ميسرة، عن العلاء بن عبد الرحمن، عن أبيه، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب صفة من يبرّ الله قسمه","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2622).","chapter_en":"The Description of One Whose Oath Allah Fulfills","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “Perhaps a disheveled person, turned away from doors, if he were to swear by Allah, Allah would fulfill his oath.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2622,"lafz":true}],"full":1,"rep":[13008,14974,15117]},{"num":7060,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ أَمَرَنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِسَبْعٍ، وَنَهَانَا عَنْ سَبْعٍ أَمَرَنَا بِاتِّبَاعِ الْجَنَائِزِ، وَعِيَادَةِ الْمَرِيضِ، وَإِجَابَةِ الدَّاعِي، وَنَصْرِ الْمَظْلُومِ، وَإِبْرَارِ الْقَسَمِ، وَرَدِّ السَّلاَمِ، وَتَشْمِيتِ الْعَاطِسِ. وَنَهَانَا."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1239) ومسلم في اللباس والزينة (3:2066) كلاهما من طريق أشعث بن أبي الشعثاء، قال: سمعت معاوية بن سويد بن مقرّن، عن البراء، فذكره. واللفظ للبخاري، وزاد مسلم: أو المقْسم","grade":"متفق عليه","chapter_ar":"باب الأمر بإبرار القسم","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1239) and Muslim (2066:3). The wording is from al-Bukhari.","chapter_en":"The Command to Fulfill the Oath of One Who Swears","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Al-Bara’ ibn ʿAzib said: The Prophet ﷺ commanded us with seven things and forbade us from seven things. He commanded us to follow funerals, visit the sick, answer invitations, support the oppressed, fulfill oaths, return greetings of peace, and reply to the sneezer… the hadith."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1239,"lafz":true},{"key":"muslim","label":"مسلم","number":3}],"full":1,"rep":[14139]},{"num":7061,"demo":false,"sanad":"","matn":["عَنْ أُسَامَةَ، أَنَّ ابْنَةً لِرَسُولِ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَرْسَلَتْ إِلَيْهِ وَمَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُسَامَةُ بْنُ زَيْدٍ وَسَعْدٌ وَأُبَىٌّ أَنَّ ابْنِي قَدِ احْتُضِرَ فَاشْهَدْنَا. فَأَرْسَلَ يَقْرَأُ السَّلاَمَ وَيَقُولُ إِنَّ لِلَّهِ مَا أَخَذَ وَمَا أَعْطَى وَكُلُّ شَىْءٍ عِنْدَهُ مُسَمًّى فَلْتَصْبِرْ وَتَحْتَسِبْ. فَأَرْسَلَتْ إِلَيْهِ تُقْسِمُ عَلَيْهِ، فَقَامَ وَقُمْنَا مَعَهُ، فَلَمَّا قَعَدَ رُفِعَ إِلَيْهِ، فَأَقْعَدَهُ فِي حَجْرِهِ وَنَفْسُ الصَّبِيِّ تَقَعْقَعُ، فَفَاضَتْ عَيْنَا رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ سَعْدٌ مَا هَذَا يَا رَسُولَ اللَّهِ قَالَ هَذَا رَحْمَةٌ يَضَعُهَا اللَّهُ فِي قُلُوبِ مَنْ يَشَاءُ مِنْ عِبَادِهِ، وَإِنَّمَا يَرْحَمُ اللَّهُ مِنْ عِبَادِهِ الرُّحَمَاءَ."],"takhrij":"متفق عليه: رواه البخاري في الأيمان والنذور (6655) ومسلم في الجنائز (11:923) كلاهما من طريق عاصم الأحول، عن أبي عثمان النهدي، عن أسامة بن زيد، أن ابنة رسول الله صلى الله عليه وسلم أرسلت إليه فذكرته.","grade":"متفق عليه","chapter_ar":"باب الأمر بإبرار القسم","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6655) and Muslim (923:11).","chapter_en":"The Command to Fulfill the Oath of One Who Swears","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Usamah narrated that a daughter of the Messenger of Allah ﷺ sent for him while Usamah ibn Zayd, Saʿd, and Ubayy were with him, saying: “My son is dying, so come to us.” He sent greetings of peace and said: “To Allah belongs what He takes and what He gives, and everything with Him has an appointed term, so let her be patient and seek reward.” Then she sent again, insisting by oath that he come. So he stood, and we stood with him. When he sat, the child was lifted to him and placed in his lap while his soul was rattling. The eyes of the Messenger of Allah ﷺ overflowed with tears. Saʿd said: “What is this, O Messenger of Allah ﷺ?” He said: “This is mercy that Allah places in the hearts of whom He wills among His servants, and Allah only shows mercy to the merciful among His servants.”"]},"buhuth":{"en":["Her statement: “She insisted upon him by oath” is not considered a binding oath, because if it were an oath he would have commanded that it be fulfilled. This is also indicated by the upcoming hadith of Ibn ʿAbbas."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6655,"lafz":true},{"key":"muslim","label":"مسلم","number":11}],"full":1,"dr":1},{"num":7062,"demo":false,"sanad":"","matn":["عن ابن عباس قال: إن رجلا أتى النبي صلى الله عليه وسلم فقال: إني رأيت الليلة في المنام... فقال أبو بكر: يا رسول الله بأبي أنت والله لتدعني فأعبرها، فقال النبي صلى الله عليه وسلم: اعْبُرْ فلما عبَّرَ قال: أصبت بعضا وأخطأت بعضا فقال: فوالله لتحدثني بالذي أخطأت، قال: لا تقسم."],"takhrij":"متفق عليه: رواه البخاري في التعبير (7046) ومسلم في الرؤيا (2269) كلاهما من حديث يونس، عن ابن شهاب، أن عبيدالله بن عبدالله بن عتبة، أخبره أن ابن عباس كان يحدث أن رجلا، فذكره في حديث طويل. وهو مخرج في موضعه.","grade":"متفق عليه","chapter_ar":"باب الأمر بإبرار القسم","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7046) and Muslim (2269).","chapter_en":"The Command to Fulfill the Oath of One Who Swears","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿAbbas said: A man came to the Prophet ﷺ and said: “I saw a dream last night…” Abu Bakr then said: “O Messenger of Allah ﷺ, by my father, allow me to interpret it.” The Prophet ﷺ said: “Interpret it.” After he interpreted it, the Prophet ﷺ said: “You were correct in part of it and mistaken in part of it.” Abu Bakr said: “By Allah, you must tell me what I got wrong.” He said: “Do not swear.”"]},"buhuth":{"en":["His statement: “Do not swear” means: do not make an oath. Merely saying “I swear” or “I take an oath” is not considered an actual oath unless it is connected to Allah. Therefore, the Prophet ﷺ did not command Abu Bakr’s oath to be fulfilled. The scholars differed regarding this issue, and it is discussed in detail in the books of jurisprudence and also in Fath al-Bari (11/542)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7046,"lafz":true},{"key":"muslim","label":"مسلم","number":2269}],"full":1,"dr":1},{"num":7063,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمِينُكَ عَلَى مَا يُصَدِّقُكَ عَلَيْهِ صَاحِبُكَ.","وفي لفظ: اليمين على نيّة المستحلف."],"takhrij":"صحيح: رواه مسلم في الأيمان والنذور (1653) من طريق هشيم بن بشير، عن عبدالله بن أبي صالح، عن أبيه، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب يمين الحالف على نيّة المستحلف","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1653).","chapter_en":"The Oath of the One Swearing Is Based on the Intention of the One Requesting the Oath","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Your oath is according to what your companion understands you to mean.” And in another wording: “The oath is based on the intention of the one requesting the oath.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1653,"lafz":true}],"full":1,"dr":1},{"num":7064,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن مَسْعُودٍ قَالَ: سُئِلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أي النَّاسِ خَيْرٌ؟ قَالَ: قَرْنِي ثُمَّ الَّذِينَ يَلُونَهُمْ، ثُمَّ الَّذِينَ يَلُونَهُمْ، ثُمَّ يَجِيءُ قَوْمٌ تَسْبِقُ شَهَادَةُ أَحَدِهِمْ يَمِينَهُ، وَيَمِينُهُ شَهَادَتَهُ قَالَ إِبْرَاهِيمُ: وَكَانَ أَصْحَابُنَا يَنْهَوْنَا - وَنَحْنُ غِلْمَانٌ - أَنْ نَحْلِفَ بِالشَّهَادَةِ وَالْعَهْدِ."],"takhrij":"متفق عليه: رواه البخاري في الأيمان والنذور (6658) ومسلم في فضائل الصحابة (211:2533) كلاهما من طريق منصور، عن إبراهيم، عن عبيدة، عن عبد الله، فذكره.","grade":"متفق عليه","chapter_ar":"باب الزجر عن الحلف من غير استحلاف","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6658) and Muslim (2533:211).","chapter_en":"Warning Against Swearing Without Being Asked to Swear","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["ʿAbdullah ibn Masʿud said: The Prophet ﷺ was asked: “Which people are best?” He said: “My generation, then those who come after them, then those who come after them. Then there will come people whose testimony will precede their oaths, and whose oaths will precede their testimony.” Ibrahim said: “Our companions used to forbid us — while we were still boys — from swearing by testimony and covenant.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6658,"lafz":true},{"key":"muslim","label":"مسلم","number":211}],"full":1},{"num":7065,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اصْطَنَعَ خَاتَمًا مِنْ ذَهَبٍ وَكَانَ يَلْبَسُهُ، فَيَجْعَلُ فَصَّهُ فِي بَاطِنِ كَفِّهِ، فَصَنَعَ النَّاسُ خَوَاتِيمَ ثُمَّ إِنَّهُ جَلَسَ عَلَى الْمِنْبَرِ فَنَزَعَهُ، فَقَالَ إِنِّي كُنْتُ أَلْبَسُ هَذَا الْخَاتِمَ وَأَجْعَلُ فَصَّهُ مِنْ دَاخِلٍ. فَرَمَى بِهِ ثُمَّ قَالَ وَاللَّهِ لاَ أَلْبَسُهُ أَبَدًا. فَنَبَذَ النَّاسُ خَوَاتِيمَهُمْ."],"takhrij":"متفق عليه: رواه البخاري في الأيمان والنذور (6651) ومسلم (53:2091) كلاهما عن قتيبة حدثنا الليث، عن نافع، عن ابن عمر، فذكره.","grade":"متفق عليه","chapter_ar":"باب جواز الحلف من غير استحلاف للحاجة","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6651) and Muslim (2091:53).","chapter_en":"The Permissibility of Swearing Without Being Asked, When Needed","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ had a gold ring made and used to wear it, placing its stone toward the inside of his palm. The people then also made rings. Then one day he sat upon the pulpit and removed it, saying: “I used to wear this ring and place its stone inward.” Then he threw it away and said: “By Allah, I will never wear it again.” So the people threw away their rings as well."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6651,"lafz":true},{"key":"muslim","label":"مسلم","number":53}],"full":1},{"num":7066,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ الْكَبَائِرُ الإِشْرَاكُ بِاللَّهِ، وَعُقُوقُ الْوَالِدَيْنِ، وَقَتْلُ النَّفْسِ، وَالْيَمِينُ الْغَمُوسُ."],"takhrij":"صحيح: رواه البخاري في الأيمان والنذور (6675) عن محمد بن مقاتل، أخبرنا النضر، أخبرنا شعبة، حدثنا فراس قال: سمعت الشعبي، عن عبد الله بن عمرو، فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من اليمين الغموس","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6675).","chapter_en":"Severe Warning Against the False Immersing Oath","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs narrated that the Prophet ﷺ said: “The major sins are associating partners with Allah, disobedience to parents, killing a soul, and the false immersing oath.”"]},"buhuth":{"en":["His statement: “the immersing oath” — it was said that it is called this because it immerses the person who swears it in sin and then into the Fire. It was also said that originally, when people wished to make a binding pact, they would bring a bowl containing perfume, blood, or ashes, then swear while placing their hands into it to strengthen their covenant. Thus, when the one making such an oath betrayed it, the oath was called “immersing” because of the severity of breaking the covenant. Fath al-Bari (11/556)."]},"intro":{"ar":["قال اللّٰه تعالى:","﴿ وَلَا تَتَّخِذُوا أَيْمَانَكُمْ دَخَلًا بَيْنَكُمْ فَتَزِلَّ قَدَمٌ بَعْدَ ثُبُوتِهَا وَتَذُوقُوا السُّوءَ بِمَا صَدَدتُّمْ عَن سَبِيلِ اللَّهِ وَلَكُمْ عَذَابٌ عَظِيمٌ ﴾ [النحل: ٩٤]","قال ابن جرير الطبري: أي تجعلون أيمانكم التي تحلفون بها على أنكم موفون بالعهد لمن عاقدتموه دخلاً بينكم خديعة وغروراً ليطمئنوا إليكم وأنتم مضمرون لهم الغدر وترك الوفاء."],"en":["Allah the Exalted said:","“And do not make your oaths a means of deception among yourselves, lest a foot slip after it was firm, and you taste evil for having turned people away from the path of Allah, and for you is a great punishment.” [Surah al-Nahl: 94]","Ibn Jarir al-Tabari said: Meaning, do not make the oaths by which you swear to fulfill agreements a means of deception and betrayal among yourselves, so that people feel secure with you while you secretly intend treachery and abandonment of fulfillment."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6675,"lafz":true}],"full":1,"dr":1},{"num":7067,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ حَلَفَ عَلَى يَمِينٍ كَاذِبَةٍ مَصْبُورَةٍ مُتَعَمِّدًا فَلْيَتَبَوَّأْ بِوَجْهِهِ مَقْعَدَهُ مِنَ النَّارِ."],"takhrij":"صحيح: رواه أبو داود (3242) وأحمد (19912) والحاكم (4/294) كلهم من حديث يزيد بن هارون، أخبرنا هشام بن حسان القردوسي، عن محمد بن سيرين، عن عمران بن حصين فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب التغليظ في الأيمان الفاجرة","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3242), Ahmad (19912), and al-Hakim (7802).","chapter_en":"Severe Warning Regarding Sinful False Oaths","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["ʿImran ibn Husayn narrated that the Prophet ﷺ said: “Whoever deliberately swears a binding false oath, let him prepare his place in the Fire.”"]},"buhuth":{"en":["His statement: “binding” means an oath used to establish a judgment in one’s favor, meaning that if he swore — even falsely — judgment would be given to him."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3242,"lafz":true},{"key":"hakim","label":"الحاكم","number":7802},{"key":"ahmad","label":"مسند الإمام أحمد","number":19912,"n":19912}],"full":1,"dr":1},{"num":7068,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَلاَثَةٌ لاَ يُكَلِّمُهُمُ اللَّهُ، وَلاَ يَنْظُرُ إِلَيْهِمْ وَلاَ يُزَكِّيهِمْ، وَلَهُمْ عَذَابٌ أَلِيمٌ رَجُلٌ عَلَى فَضْلِ مَاءٍ بِطَرِيقٍ يَمْنَعُ مِنْهُ ابْنَ السَّبِيلِ، وَرَجُلٌ بَايَعَ رَجُلاً لاَ يُبَايِعُهُ إِلاَّ لِلدُّنْيَا، فَإِنْ أَعْطَاهُ مَا يُرِيدُ وَفَى لَهُ، وَإِلاَّ لَمْ يَفِ لَهُ، وَرَجُلٌ سَاوَمَ رَجُلاً بِسِلْعَةٍ بَعْدَ الْعَصْرِ، فَحَلَفَ بِاللَّهِ لَقَدْ أُعْطِيَ بِهِ كَذَا وَكَذَا، فَأَخَذَهَا."],"takhrij":"متفق عليه: رواه البخاري في الشهادات (2672)، ومسلم في الإيمان (183:108) كلاهما من حديث الأعمش، عن أبي صالح، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب الترهيب من الحلف بعد العصر كاذباً","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2672) and Muslim (183:108).","chapter_en":"Severe Warning Against Swearing Falsely After ʿAsr","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":16,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “There are three whom Allah will neither speak to, nor look at, nor purify, and for them is a painful punishment: a man who has excess water on a road but prevents the traveler from it; a man who gives allegiance to another only for worldly gain, so if he gives him what he wants he remains loyal, and if not he is disloyal; and a man who bargains with another over merchandise after ʿAsr and swears by Allah that he was offered such-and-such for it, so the buyer believes him and purchases it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2672,"lafz":true},{"key":"muslim","label":"مسلم","number":108},{"key":"muslim","label":"مسلم في الايمان","number":183}],"full":1},{"num":7069,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن مَسْعُودٍ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ حَلَفَ عَلَى يَمِينِ صَبْرٍ يَقْتَطِعُ بِهَا مَالَ امْرِئٍ مُسْلِمٍ، هُوَ فِيهَا فَاجِرٌ، لَقِيَ اللَّهَ وَهُوَ عَلَيْهِ غَضْبَانُ قَالَ، فَدَخَلَ الأَشْعَثُ بْنُ قَيْسٍ فَقَالَ: مَا يُحَدِّثُكُمْ أَبُو عَبْدِ الرَّحْمَنِ؟ قَالُوا: كَذَا وَكَذَا. قَالَ: صَدَقَ أَبُو عَبْدِ الرَّحْمَنِ، فيّ نَزَلَتْ. كَانَ بَيْنِي وَبَيْنَ رَجُلٍ أَرْضٌ بِالْيَمَنِ. فَخَاصَمْتُهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: هَلْ لَكَ مَنْ بَيِّنَةٌ؟ فَقُلْتُ: لاَ، قَالَ: فَيَمِينُهُ. قُلْتُ: إذن يَحْلِفُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ ذَلِكَ: مَنْ حَلَفَ عَلَى يَمِينِ صَبْرٍ، يَقْتَطِعُ بِهَا مَالَ امْرِئٍ مُسْلِمٍ، هُوَ فِيهَا فَاجِرٌ، لَقِيَ اللَّهَ وَهُوَ عَلَيْهِ غَضْبَانُ فَنَزَلَتْ: ﴿إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ وَأَيْمَانِهِمْ ثَمَنًا قَلِيلًا أُولَئِكَ لَا خَلَاقَ لَهُمْ فِي الْآخِرَةِ وَلَا يُكَلِّمُهُمُ اللَّهُ وَلَا يَنْظُرُ إِلَيْهِمْ يَوْمَ الْقِيَامَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ﴾ [سورة آل عمران: 77] [آل عِمْرَانَ: ٧٧]"],"takhrij":"متفق عليه: رواه البخاري في الأيمان والنذور (6659-6660) ومسلم في الإيمان (220:138) كلاهما من حديث أبي وائل، عن عبد الله (هو ابن مسعود) فذكره، والسياق لمسلم. وفي رواية عندهما: البخاري (2516،2515) ومسلم: \"شاهداك أو يمينه\".","grade":"متفق عليه","chapter_ar":"باب الوعيد بالنار لمن اقتطع حق مسلم بيمين كاذبة","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6659–6660) and Muslim (220:138). The wording is from Muslim.","chapter_en":"Threat of the Fire for One Who Takes the Right of a Muslim Through a False Oath","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":17,"content":{"translation":{"en":["ʿAbdullah ibn Masʿud narrated that the Messenger of Allah ﷺ said: “Whoever swears a binding oath by which he unlawfully takes the wealth of a Muslim while lying in it, will meet Allah while He is angry with him.” He said: Then al-Ashʿath ibn Qays entered and said: “What is Abu ʿAbd al-Rahman narrating to you?” They told him. He said: “Abu ʿAbd al-Rahman has spoken the truth; it was revealed concerning me. There was a dispute between me and another man over land in Yemen. I brought the case to the Prophet ﷺ and he said: ‘Do you have evidence?’ I said: ‘No.’ He said: ‘Then his oath.’ I said: ‘Then he will swear.’ At that point the Messenger of Allah ﷺ said: ‘Whoever swears a binding oath by which he unlawfully takes the wealth of a Muslim while lying in it, will meet Allah while He is angry with him.’ Then the verse was revealed: ‘Indeed, those who exchange the covenant of Allah and their oaths for a small price — they will have no share in the Hereafter, and Allah will neither speak to them nor look at them on the Day of Resurrection, nor purify them, and for them is a painful punishment.’ [Surah Al ʿImran: 77]"]},"buhuth":{"en":["There is no contradiction between his statement: “Do you have evidence?” and the wording: “Your two witnesses,” because two witnesses are the evidence."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6659,"lafz":true},{"key":"muslim","label":"مسلم","number":138},{"key":"muslim","label":"مسلم في الايمان","number":220,"n":355},{"key":"bukhari","label":"البخاري","number":2516},{"key":"bukhari","label":"البخاري","number":2515}],"full":1,"dr":1},{"num":7070,"demo":false,"sanad":"","matn":["عَنْ وَائِلِ بْنِ حُجْرٍ قَالَ: جَاءَ رَجُلٌ مِنْ حَضْرَمَوْتَ، وَرَجُلٌ مِنْ كِنْدَةَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ الْحَضْرَمِيُّ: يَا رَسُولَ اللَّهِ، إِنَّ هَذَا قَدْ غَلَبَنِي عَلَى أَرْضٍ لِي كَانَتْ لأَبِي. فَقَالَ الْكِنْدِيُّ: هِيَ أَرْضِي فِي يَدِي أَزْرَعُهَا لَيْسَ لَهُ فِيهَا حَقٌّ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلْحَضْرَمِيِّ: أَلَكَ بَيِّنَةٌ؟ قَالَ: لاَ. قَالَ: فَلَكَ يَمِينُهُ قَالَ: يَا رَسُولَ اللَّهِ، إِنَّ الرَّجُلَ فَاجِرٌ لاَ يُبَالِي عَلَى مَا حَلَفَ عَلَيْهِ، وَلَيْسَ يَتَوَرَّعُ مِنْ شيء. فَقَالَ: لَيْسَ لَكَ مِنْهُ إِلاَّ ذَلِكَ فَانْطَلَقَ لِيَحْلِفَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا أَدْبَرَ: أَمَا لَئِنْ حَلَفَ عَلَى مَالِهِ لِيَأْكُلَهُ ظُلْمًا، لَيَلْقَيَنَّ اللَّهَ وَهُوَ عَنْهُ مُعْرِضٌ."],"takhrij":"صحيح: رواه مسلم في الإيمان (139) من طريق أبي الأحوص، عن سماك، عن علقمة بن وائل، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب الوعيد بالنار لمن اقتطع حق مسلم بيمين كاذبة","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (139).","chapter_en":"Threat of the Fire for One Who Takes the Right of a Muslim Through a False Oath","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":17,"content":{"translation":{"en":["Wa’il ibn Hujr said: A man from Hadramawt and a man from Kindah came to the Prophet ﷺ. The man from Hadramawt said: “O Messenger of Allah ﷺ, this man has seized land belonging to me that belonged to my father.” The Kindi said: “It is my land in my possession; I cultivate it and he has no right to it.” The Messenger of Allah ﷺ said to the Hadrami: “Do you have evidence?” He said: “No.” He said: “Then you are entitled to his oath.” He said: “O Messenger of Allah ﷺ, the man is wicked and does not care what he swears to, nor does he refrain from anything.” He said: “You have no right except that.” So the man went to swear, and when he turned away the Messenger of Allah ﷺ said: “If he swears falsely in order to consume his wealth unjustly, he will meet Allah while Allah turns away from him.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":139,"lafz":true}],"full":1},{"num":7071,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنِ اقْتَطَعَ حَقَّ امْرِئٍ مُسْلِمٍ بِيَمِينِهِ حرّم اللَّهُ عَلَيْهِ الْجَنَّةَ، وأوجب لَهُ النَّارَ قَالُوا: وَإِنْ كَانَ شَيْئًا يَسِيرًا يَا رَسُولَ اللَّهِ؟ قَالَ: وَإِنْ كَانَ قَضِيبًا مِنْ أَرَاكٍ، وَإِنْ كَانَ قَضِيبًا من أَرَاكٍ، وَإِنْ كَانَ قَضِيبًا من أَرَاكٍ. قَالَهَا ثلاث مَرَّاتٍ."],"takhrij":"صحيح: رواه مالك في الأقضية (11) عن العلاء بن عبد الرحمن، عن معبد بن كعب السلمي، عن أخيه عبد الله بن كعب بن مالك الأنصاري، عن أبي أمامة، فذكره. ورواه مسلم في الإيمان (137) من طريق إسماعيل بن جعفر، عن العلاء بن عبد الرحمن، به.","grade":"صحيح","chapter_ar":"باب الوعيد بالنار لمن اقتطع حق مسلم بيمين كاذبة","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (11) and Muslim (137).","chapter_en":"Threat of the Fire for One Who Takes the Right of a Muslim Through a False Oath","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":17,"content":{"translation":{"en":["Abu Umamah narrated that the Messenger of Allah ﷺ said: “Whoever takes the right of a Muslim through his oath, Allah has forbidden Paradise for him and made the Fire obligatory upon him.” They said: “Even if it is something insignificant, O Messenger of Allah ﷺ?” He said: “Even if it is a twig of arak, even if it is a twig of arak, even if it is a twig of arak.” He repeated it three times."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":11,"lafz":true},{"key":"muslim","label":"مسلم","number":137}],"full":1},{"num":7072,"demo":false,"sanad":"","matn":["عَنْ مَعْقِلِ بْنِ يَسَارٍ أَنَّ رَجُلَيْنِ اخْتَصَمَا إِلَيْهِ فِي أَرْضٍ، فَقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ حَلَفَ عَلَى يَمِينٍ لِيَقْتَطِعَ بِهَا مَالَ أَخِيهِ لَقِيَ اللَّهَ عَزَّ وَجَلَّ وَهُوَ عَلَيْهِ غَضْبَانُ."],"takhrij":"صحيح: رواه أبو داود الطيالسي (975) عن جعفر بن سليمان، عن معلَّى الفردوسي، عن معاوية بن قرة، عن معقل بن يسار، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب الوعيد بالنار لمن اقتطع حق مسلم بيمين كاذبة","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud al-Tayalisi (975), Ahmad (20295), al-Tabarani (20/528), and al-Hakim (7801).","chapter_en":"Threat of the Fire for One Who Takes the Right of a Muslim Through a False Oath","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":17,"content":{"translation":{"en":["Maʿqil ibn Yasar narrated that two men disputed before him regarding land, so he said: I heard the Messenger of Allah ﷺ say: “Whoever swears an oath in order to unlawfully take the wealth of his brother will meet Allah while He is angry with him.”"]}},"tuhfa":{},"refs":[{"key":"tayalisi","label":"أبو داود الطيالسي","number":975,"lafz":true},{"key":"mujamkabir","label":"الطبراني","number":20},{"key":"hakim","label":"الحاكم","number":7801},{"key":"ahmad","label":"مسند الإمام أحمد","number":20295,"n":20295}],"full":1,"dr":1},{"num":7073,"demo":false,"sanad":"","matn":["عَنِ الْحَارِثِ بْنِ الْبَرْصَاءِ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَمْشِي بَيْنَ جَمْرَتَيْنِ مِنَ الْجِمَارِ يَقُولُ: مَنْ أَخَذَ شِبْرًا مِنْ مَالِ امْرِئٍ مُسْلِمٍ بِيَمِينٍ فَاجِرَةٍ، فَلْيَتَبَوَّأْ بَيْتًا مِنَ النَّارِ."],"takhrij":"صحيح: رواه ابن حبان في صحيحه (5165) عن محمد بن مكرم، قال: حدثنا عمرو بن علي الفلاس، قال: حدثنا عمر بن عبد الوهاب الرياحي، قال: حدثنا يزيد بن زريع، قال حدثنا روح بن القاسم، عن إسماعيل بن أمية، عن عمر بن عطاء، عن عبيد بن جريج، عن الحارث بن البرصاء فذكره.","grade":"صحيح","chapter_ar":"باب الوعيد بالنار لمن اقتطع حق مسلم بيمين كاذبة","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Ḥibbān in his Ṣaḥīḥ (5165) and al-Ḥākim (4/294–295).","chapter_en":"Threat of the Fire for One Who Takes the Right of a Muslim Through a False Oath","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":17,"content":{"translation":{"en":["Al-Ḥārith ibn al-Barṣāʾ reported: I heard the Messenger of Allah ﷺ saying while he was walking between two of the Jamarāt: “Whoever takes even a handspan of a Muslim’s property by means of a wicked false oath, let him prepare for himself a dwelling in the Fire.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"ابن حبان في صحيحه","number":5165,"lafz":true},{"key":"hakim","label":"الحاكم","number":4},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2825,"n":2822}],"full":1,"dr":1,"rep":[5919]},{"num":7074,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ ثَلاَثَةٌ لاَ يُكَلِّمُهُمُ اللَّهُ يَوْمَ الْقِيَامَةِ وَلاَ يَنْظُرُ إِلَيْهِمْ وَلاَ يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ قَالَ فَقَرَأَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَلاَثَ مِرَارٍ. قَالَ أَبُو ذَرٍّ خَابُوا وَخَسِرُوا مَنْ هُمْ يَا رَسُولَ اللَّهِ قَالَ الْمُسْبِلُ وَالْمَنَّانُ وَالْمُنَفِّقُ سِلْعَتَهُ بِالْحَلِفِ الْكَاذِبِ."],"takhrij":"صحيح: رواه مسلم في الإيمان (106) من طريق محمد بن جعفر، عن شعبة، عن علي بن مدْرك، عن أبي زرعة، عن خرشة بن الحرّ، عن أبي ذر، فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من إنفاق السلع بالحلف الكاذب","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (106).","chapter_en":"Warning Against Selling Goods by Means of a False Oath","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["Abu Dharr narrated that the Prophet ﷺ said: “There are three whom Allah will neither speak to on the Day of Resurrection, nor look at, nor purify, and for them is a painful punishment.” The Messenger of Allah ﷺ repeated it three times. Abu Dharr said: “They are ruined and lost! Who are they, O Messenger of Allah ﷺ?” He said: “The one who lets his garment hang below the ankles, the one who reminds others of his favors, and the one who sells his goods through false oaths.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":106,"lafz":true}],"full":1,"rep":[412,5678,15375]},{"num":7075,"demo":false,"sanad":"","matn":["عن عَائِشَةَ قَالَتْ: سَمِعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَوْتَ خُصُومٍ بِالْبَابِ عَالِيَةٍ أَصْوَاتُهُمَا، وَإِذَا أَحَدُهُمَا يَسْتَوْضِعُ الآخَرَ، وَيَسْتَرْفِقُهُ فِي شَىْءٍ وَهْوَ يَقُولُ وَاللَّهِ لاَ أَفْعَلُ. فَخَرَجَ عَلَيْهِمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ أَيْنَ الْمُتَأَلِّي عَلَى اللَّهِ لاَ يَفْعَلُ الْمَعْرُوفَ. فَقَالَ أَنَا يَا رَسُولَ اللَّهِ، وَلَهُ أَىُّ ذَلِكَ أَحَبَّ."],"takhrij":"متفق عليه: رواه البخاري في الصلح (2705) ومسلم في المساقاة والمزارعة (19:1557) من طريق إسماعيل بن أبي أويس، حدثني أخي، عن سليمان (هو ابن بلال) عن يحيى بن سعيد، عن أبي الرّجال محمد بن عبدالرحمن، أن أمه عمرة بنت عبد الرحمن، قالت: سمعت عائشة، فذكرته.","grade":"متفق عليه","chapter_ar":"باب زجر المتألي على الله بأن لا يفعل المعروف","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2705) and Muslim (1557:19).","chapter_en":"Warning Against One Who Swears by Allah That He Will Not Do Good","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ heard the voices of disputing people at the door, raising their voices. One of them was asking the other to reduce something and to show leniency regarding a matter, while the other was saying: “By Allah, I will not do it.” So the Messenger of Allah ﷺ came out to them and said: “Where is the one swearing by Allah that he will not do good?” The man said: “I am the one, O Messenger of Allah ﷺ, and he may have whichever of the two options he prefers.”"]},"buhuth":{"en":["Meaning: a reduction from the debt.","And his statement: “asking him for leniency” means requesting gentleness and ease from him.","And his statement: “the one swearing excessively” means the person who exaggerates in swearing oaths. It is derived from al-aliyah — with a fathah on the hamzah, kasrah on the lam, and a doubled ya’ — meaning an oath."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2705,"lafz":true},{"key":"muslim","label":"مسلم","number":19}],"full":1,"dr":1},{"num":7076,"demo":false,"sanad":"","matn":["عَنْ جُنْدَبٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَدَّثَ أَنَّ رَجُلاً قَالَ وَاللَّهِ لاَ يَغْفِرُ اللَّهُ لِفُلاَنٍ وَإِنَّ اللَّهَ تَعَالَى قَالَ مَنْ ذَا الَّذِي يَتَأَلَّى عَلَىَّ أَنْ لاَ أَغْفِرَ لِفُلاَنٍ فَإِنِّي قَدْ غَفَرْتُ لِفُلاَنٍ وَأَحْبَطْتُ عَمَلَكَ. أَوْ كَمَا قَالَ."],"takhrij":"صحيح: رواه مسلم في البر والصلة والآداب (2621) عن سويد بن سعيد، عن معتمر بن سليمان، عن أبيه، حدثنا أبو عمران الجوني، عن جندب، فذكره.","grade":"صحيح","chapter_ar":"باب زجر المتألي على الله بأن لا يفعل المعروف","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2621).","chapter_en":"Warning Against One Who Swears by Allah That He Will Not Do Good","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Jundub narrated that the Messenger of Allah ﷺ said: “A man said: ‘By Allah, Allah will not forgive so-and-so.’ But Allah the Exalted said: ‘Who is the one swearing by Me that I will not forgive so-and-so? Indeed, I have forgiven so-and-so and rendered your deeds worthless.’” Or as he ﷺ said."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2621,"lafz":true}],"full":1,"rep":[11421,14615]},{"num":7077,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ نَذْرَ إِلاَّ فِيمَا يُبْتَغَى بِهِ وَجْهُ اللَّهِ، وَلاَ يَمِينَ فِي قَطِيعَةِ رَحِمٍ."],"takhrij":"حسن: رواه أبو داود (3273) وأحمد (6732) كلاهما من حديث عبدالرحمن بن الحارث، عن عمرو بن شعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب لا يمين في قطيعة رحم","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3273) and Ahmad (6732). The wording is from Abu Dawud.","chapter_en":"There Is No Valid Oath in Severing Family Ties","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":20,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb, from his father, from his grandfather, narrated that the Messenger of Allah ﷺ said: “There is no vow except in that by which the Face of Allah is sought, and there is no oath involving the severing of family ties.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3273,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":6732,"n":6732}],"full":1,"dr":1},{"num":7078,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَرَضَ عَلَى قَوْمٍ الْيَمِينَ فَأَسْرَعُوا، فَأَمَرَ أَنْ يُسْهَمَ بَيْنَهُمْ فِي الْيَمِينِ أَيُّهُمْ يَحْلِفُ."],"takhrij":"صحيح: رواه البخاري في الشهادات (2674) عن إسحاق بن نصر، حدثنا عبد الرزاق، أخبرنا معمر، عن هشام، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب القرعة في اليمين","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2674).","chapter_en":"Drawing Lots Regarding an Oath","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":21,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ offered an oath to a group of people, and they hurried toward it. So he ordered that lots be drawn among them regarding the oath to determine which of them would swear."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2674,"lafz":true}],"full":1,"rep":[6767]},{"num":7079,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ كَانَ حَالِفًا فَلْيَحْلِفْ بِاللَّهِ أَوْ لِيَصْمُتْ."],"takhrij":"متفق عليه: رواه البخاري في الشهادات (2679)، ومسلم في الأيمان والنذور (3:1646) كلاهما من طريق نافع، عن ابن عمر، فذكره، والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب من كان حالفاً فليحلف بالله أو ليصمت","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2679) and Muslim (1646:3). The wording is from al-Bukhari.","chapter_en":"Whoever Swears, Let Him Swear by Allah or Remain Silent","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":22,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Prophet ﷺ said: “Whoever is going to swear, let him swear by Allah or remain silent.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2679,"lafz":true},{"key":"muslim","label":"مسلم","number":3}],"full":1},{"num":7080,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بْنِ عُبَيْدَةَ، قَالَ سَمِعَ ابْنُ عُمَرَ، رَجُلاً يَحْلِفُ لاَ وَالْكَعْبَةِ فَقَالَ لَهُ ابْنُ عُمَرَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ مَنْ حَلَفَ بِغَيْرِ اللَّهِ فَقَدْ أَشْرَكَ."],"takhrij":"صحيح: رواه أبو داود (3251) والترمذي (1535) وأحمد (5256،5222) وصحَّحه ابن حبان (4358) والحاكم (4/297) والبيهقي (10/29) كلهم من طرق عن الحسن بن عبيد الله النخعي، عن سعد بن عبيدة، قال: كنت عند ابن عمر. فحلف رجل بالكعبة. الحديث.","grade":"صحيح","chapter_ar":"باب الترهيب من الحلف بغير الله","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3251), al-Tirmidhi (1535) who graded it Hasan, Ahmad (5222, 5256), and authenticated by Ibn Hibban (4358).","chapter_en":"Severe Warning Against Swearing by Other Than Allah","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar heard a man swearing: “No, by the Kaʿbah.” Ibn ʿUmar said to him: I heard the Messenger of Allah ﷺ say: “Whoever swears by other than Allah has committed shirk.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3251,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1535},{"key":"ibnhibban","label":"صحَّحه ابن حبان","number":4358},{"key":"ahmad","label":"مسند الإمام أحمد","number":5222,"n":5222},{"key":"ahmad","label":"احمد","number":5256}],"full":1,"dr":1},{"num":7081,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ، الرَّحْمَنِ بْنِ سَمُرَةَ قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ تَحْلِفُوا بِالطَّوَاغِي وَلاَ بِآبَائِكُمْ."],"takhrij":"صحيح: رواه مسلم في الأيمان والنذور (1648) عن أبي بكر بن أبي شيبة، حدثنا عبدالأعلى، عن هشام، عن الحسن، عن عبدالرحمن بن سمرة فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من الحلف بغير الله","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1648).","chapter_en":"Severe Warning Against Swearing by Other Than Allah","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["ʿAbd al-Rahman ibn Samurah said: The Messenger of Allah ﷺ said: “Do not swear by false gods nor by your fathers.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1648,"lafz":true}],"full":1},{"num":7082,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَدْرَكَ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ وَهْوَ يَسِيرُ فِي ركْبٍ وَهْوَ يَحْلِفُ بِأَبِيهِ، فَقَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إنّ اللَّهَ يَنْهَاكُمْ أَنْ تَحْلِفُوا بِآبَائِكُمْ، فَمَنْ كَانَ حَالِفًا، فَلْيَحْلِفْ بِاللَّهِ أَوْ لِيَصْمُتْ."],"takhrij":"متفق عليه: رواه مالك في النذور والأيمان (14) عن نافع، عن عبد الله بن عمر، فذكره.ورواه البخاري في الأيمان والنذور (6646) من طريق مالك به، مثله.","grade":"متفق عليه","chapter_ar":"باب النهي عن الحلف بالآباء والأمهات وبغير الله","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (14), al-Bukhari (6646), and Muslim (1646:3,4).","chapter_en":"The Prohibition of Swearing by Fathers, Mothers, and Other Than Allah","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":24,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar narrated that the Messenger of Allah ﷺ came upon ʿUmar ibn al-Khattab while he was traveling with a group and swearing by his father. The Messenger of Allah ﷺ said: “Indeed, Allah forbids you from swearing by your fathers. Whoever wishes to swear should swear by Allah or remain silent.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":14,"lafz":true},{"key":"bukhari","label":"البخاري","number":6646},{"key":"muslim","label":"مسلم","number":1646}],"full":1,"dr":1},{"num":7083,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنَّ اللَّهَ يَنْهَاكُمْ أَنْ تَحْلِفُوا بِآبَائِكُمْ قَالَ عُمَرُ: فو الله مَا حَلَفْتُ بِهَا مُنْذُ سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاكِرًا وَلاَ آثِرًا."],"takhrij":"متفق عليه: رواه البخاري في الأيمان والنذور (6647) ومسلم في الأيمان والنذور (1:1646) كلاهما من طريق يونس، عن ابن شهاب، عن سالم بن عبد الله، عن أبيه، قال: سمعت عمر بن الخطاب، فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن الحلف بالآباء والأمهات وبغير الله","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6647) and Muslim (1646:1).","chapter_en":"The Prohibition of Swearing by Fathers, Mothers, and Other Than Allah","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":24,"content":{"translation":{"en":["ʿUmar said: The Messenger of Allah ﷺ said to me: “Indeed, Allah forbids you from swearing by your fathers.” ʿUmar said: “By Allah, I never swore by it again after hearing the Prophet ﷺ say that, neither intentionally nor quoting someone else.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6647,"lafz":true},{"key":"muslim","label":"مسلم","number":1646},{"key":"muslim","label":"مسلم في الايمان والنذور","number":1}],"full":1,"dr":1},{"num":7084,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَلاَ مَنْ كَانَ حَالِفًا فَلاَ يَحْلِفْ إِلاَّ بِاللَّهِ فَكَانَتْ قُرَيْشٌ تَحْلِفُ بِآبَائِهَا، فَقَالَ: لاَ تَحْلِفُوا بِآبَائِكُمْ."],"takhrij":"متفق عليه: رواه البخاري في مناقب الأنصار (3836) ومسلم في الأيمان والنذور (4:1646) كلاهما عن قتيبة – وزاد معه مسلم غيره – حدثنا إسماعيل بن جعفر، عن عبدالله بن دينار، عن ابن عمر، فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن الحلف بالآباء والأمهات وبغير الله","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3836) and Muslim (1646:4).","chapter_en":"The Prohibition of Swearing by Fathers, Mothers, and Other Than Allah","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":24,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar narrated that the Prophet ﷺ said: “Whoever swears should swear only by Allah.” The Quraysh used to swear by their fathers, so he ﷺ said: “Do not swear by your fathers.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3836,"lafz":true},{"key":"muslim","label":"مسلم","number":1646,"n":4259},{"key":"muslim","label":"مسلم في الايمان والنذور","number":4}],"full":1,"dr":1},{"num":7085,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ سَمِعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلاً يَحْلِفُ بِأَبِيهِ فَقَالَ لاَ تَحْلِفُوا بِآبَائِكُمْ مَنْ حَلَفَ بِاللَّهِ فَلْيَصْدُقْ وَمَنْ حُلِفَ لَهُ بِاللَّهِ فَلْيَرْضَ وَمَنْ لَمْ يَرْضَ بِاللَّهِ فَلَيْسَ مِنَ اللَّهِ."],"takhrij":"حسن: رواه ابن ماجة (2101) عن محمد بن إسماعيل بن سمرة قال: حدثنا أسباط بن محمد، عن محمد بن عجلان، عن نافع، عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب النهي عن الحلف بالآباء والأمهات وبغير الله","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2101).","chapter_en":"The Prohibition of Swearing by Fathers, Mothers, and Other Than Allah","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":24,"content":{"translation":{"en":["Ibn ʿUmar said: The Prophet ﷺ heard a man swearing by his father, so he said: “Do not swear by your fathers. Whoever swears by Allah must speak truthfully, and whoever is sworn to by Allah should be satisfied. Whoever is not satisfied with Allah is not from Allah.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2101,"lafz":true}],"full":1,"dr":1},{"num":7086,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ تَحْلِفُوا بِآبَائِكُمْ وَلاَ بِأُمَّهَاتِكُمْ وَلاَ بِالأَنْدَادِ وَلاَ تَحْلِفُوا إِلاَّ بِاللَّهِ وَلاَ تَحْلِفُوا بِاللَّهِ إِلاَّ وَأَنْتُمْ صَادِقُونَ."],"takhrij":"صحيح: رواه أبو داود (3248) والنسائي (3769) وصحّحه ابن حبان (4357) كلهم من حديث عبيد الله بن معاذ بن معاذ، حدثنا أبي، قال: حدثنا عوف، عن ابن سيرين، عن أبي هريرة فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب النهي عن الحلف بالآباء والأمهات وبغير الله","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3248), al-Nasa’i (3769), and authenticated by Ibn Hibban (4357).","chapter_en":"The Prohibition of Swearing by Fathers, Mothers, and Other Than Allah","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":24,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Do not swear by your fathers, nor by your mothers, nor by rivals to Allah. Swear only by Allah, and do not swear by Allah except while speaking truthfully.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3248,"lafz":true},{"key":"nasai","label":"النسائي","number":3769,"n":3769},{"key":"ibnhibban","label":"صححه ابن حبان","number":4357},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2224,"n":2221}],"full":1,"dr":1},{"num":7087,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ حَلَفَ فَقَالَ فِي حَلِفِهِ بِاللاَّتِ وَالْعُزَّى. فَلْيَقُلْ لاَ إِلَهَ إِلاَّ اللَّهُ. وَمَنْ قَالَ لِصَاحِبِهِ تَعَالَ أُقَامِرْكَ. فَلْيَتَصَدَّقْ."],"takhrij":"متفق عليه: رواه البخاري في الأيمان والنذور (6650) ومسلم في الأيمان والنذور (1647) كلاهما من طريق الزهري، عن حُميد بن عبد الرحمن، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب كفارة من حلف باللات والعزى وغيرها من الطواغيت","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6650) and Muslim (1647).","chapter_en":"The Expiation for One Who Swears by al-Lat, al-ʿUzza, and Other False Deities","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said: “Whoever swears and says in his oath: ‘By al-Lat and al-ʿUzza,’ let him say: ‘There is no god except Allah.’ And whoever says to his companion: ‘Come, let us gamble,’ then let him give charity.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6650,"lafz":true},{"key":"muslim","label":"مسلم","number":1647}],"full":1},{"num":7088,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بن أَبِي وَقَّاصٍ قَالَ: حَلَفْتُ بِاللاتِ وَالْعُزَّى. فَقَالَ أَصْحَابِي: قَدْ قُلْتَ هُجْراً، فَأَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: إِنَّ الْعَهْدَ كَانَ قَرِيبًا، وَإِنِّي حَلَفْتُ بِاللاتِ وَالْعُزَّى، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : قُلْ: لَا إِلَهَ إِلا اللَّهُ وَحْدَهُ، ثَلاثًا، ثُمَّ انْفُثْ عَنْ يَسَارِكَ ثَلاثًا، وَتَعَوَّذْ وَلا تعُدْ."],"takhrij":"صحيح: رواه النسائي (3776) وابن ماجة (2097) وأحمد (1589) وصحَّحه ابن حبان (4364) كلهم من طرق عن أبي إسحاق السبيعي، عن مصعب بن سعد، عن أبيه سعد بن أبي وقاص فذكره.","grade":"صحيح","chapter_ar":"باب كفارة من حلف باللات والعزى وغيرها من الطواغيت","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (3776), Ibn Mājah (2097), Aḥmad (1589), and authenticated by Ibn Ḥibbān (4364).","chapter_en":"The Expiation for One Who Swears by al-Lat, al-ʿUzza, and Other False Deities","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ reported: I swore by al-Lāt and al-ʿUzzā, and my companions said: “You have uttered an improper statement.” So I went to the Prophet ﷺ and said: “My time since leaving disbelief is still recent, and I swore by al-Lāt and al-ʿUzzā.” The Messenger of Allah ﷺ said: “Say, ‘There is no god except Allah alone,’ three times. Then lightly spit to your left three times, seek refuge in Allah, and do not do it again.”"]},"buhuth":{"en":["The meaning of the hadith is that whoever swears by al-Lāt and al-ʿUzzā has, in effect, set up a rival alongside Allah. He should therefore correct this by saying, “There is no god except Allah alone,” three times and seeking refuge in Allah from Satan the accursed. By doing so, he returns to pure monotheism and the whispering of Satan departs from him."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3776,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":2097},{"key":"ibnhibban","label":"صححه ابن حبان","number":4364},{"key":"ahmad","label":"مسند الإمام أحمد","number":1590,"n":1590},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1225,"n":1222},{"key":"ahmad","label":"احمد","number":1589,"n":1590}],"full":1,"dr":1,"rep":[11278,13426]},{"num":7089,"demo":false,"sanad":"","matn":["عن ثابت بن الضَّحَّاكِ – وَكَانَ من أَصْحَابِ الشَّجَرَةِ – حَدَّثَهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ حَلَفَ عَلَى مِلَّةٍ غَيْرِ الإِسْلاَمِ فَهْوَ كَمَا قَالَ، وَلَيْسَ عَلَى ابْنِ آدَمَ نَذْرٌ فِيمَا لاَ يَمْلِكُ، وَمَنْ قَتَلَ نَفْسَهُ بِشَىْءٍ فِي الدُّنْيَا عُذِّبَ بِهِ يَوْمَ الْقِيَامَةِ، وَمَنْ لَعَنَ مُؤْمِنًا فَهْوَ كَقَتْلِهِ، وَمَنْ قَذَفَ مُؤْمِنًا بِكُفْرٍ فَهْوَ كَقَتْلِهِ."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6047) ومسلم في الإيمان (176:110) كلاهما من حديث يحيى بن أبي كثير، عن أبي قلابة، أن ثابت بن قيس حدثه فذكره.","grade":"متفق عليه","chapter_ar":"باب من حلف بغير ملة الإسلام","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6047) and Muslim (176:110).","chapter_en":"One Who Swears by a Religion Other Than Islam","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":26,"content":{"translation":{"en":["Thabit ibn al-Dahhak — who was among those who pledged beneath the tree — narrated that the Messenger of Allah ﷺ said: “Whoever swears by a religion other than Islam is as he has said. The son of Adam has no vow concerning what he does not own. Whoever kills himself with something in this world will be punished with it on the Day of Resurrection. Whoever curses a believer is like killing him, and whoever accuses a believer of disbelief is like killing him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6047,"lafz":true},{"key":"muslim","label":"مسلم","number":110},{"key":"muslim","label":"مسلم في الايمان","number":176}],"full":1,"dr":1,"rep":[14954]},{"num":7090,"demo":false,"sanad":"","matn":["عَنْ أَبِيهِ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ حَلَفَ فَقَالَ إِنِّي بَرِيءٌ مِنَ الإِسْلاَمِ فَإِنْ كَانَ كَاذِبًا فَهُوَ كَمَا قَالَ، وَإِنْ كَانَ صَادِقًا فَلَنْ يَرْجِعَ إِلَى الإِسْلاَمِ سَالِمًا."],"takhrij":"حسن: رواه أبو داود (3258) والنسائي (3772) وابن ماجة (2100) وأحمد (23006) والبيهقي (10/30) كلهم من طريق حسين بن واقد، قال: حدثنا عبد الله بن بريدة، عن أبيه، فذكره.","grade":"حسن","chapter_ar":"باب من حلف بغير ملة الإسلام","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3258), al-Nasa’i (3772), Ibn Majah (2100), and Ahmad (23006).","chapter_en":"One Who Swears by a Religion Other Than Islam","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":26,"content":{"translation":{"en":["Buraydah ibn al-Husayb said: The Messenger of Allah ﷺ said: “Whoever swears saying: ‘I am free from Islam,’ then if he is lying, it is as he said, and if he is truthful, he will not return to Islam safely.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3258,"lafz":true},{"key":"nasai","label":"النسائي","number":3772,"n":3772},{"key":"ibnmajah","label":"ابن ماجه","number":2100},{"key":"ahmad","label":"مسند الإمام أحمد","number":23006,"n":23006},{"key":"sh13039","label":"الصمت وآداب اللسان","number":368,"n":359}],"full":1,"dr":1},{"num":7091,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ، عَنْ أَبِيهِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَيْسَ مِنَّا مَنْ حَلَفَ بِالْأَمَانَةِ، وَمَنْ خَبَّبَ عَلَى امْرِئٍ زَوْجَتَهُ أَوْ مَمْلُوكَهُ فَلَيْسَ مِنَّا."],"takhrij":"صحيح: رواه أبو داود (3253) وأحمد (22980) وصحَّحه ابن حبان (4363) والحاكم (4/298) والبيهقي (10/30) كلهم من حديث الوليد بن ثعلبة الطائي، عن عبد الله بن بريدة، عن أبيه، فذكره مطولا ومختصراً. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب كراهة الحلف بالأمانة","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3253), Ahmad (22980), authenticated by Ibn Hibban (4363) and al-Hakim (4/298).","chapter_en":"The Dislike of Swearing by Trustworthiness","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":27,"content":{"translation":{"en":["ʿAbdullah ibn Buraydah narrated from his father that the Messenger of Allah ﷺ said: “He is not from us who swears by trustworthiness, and whoever turns a man’s wife or slave against him is not from us.”"]},"buhuth":{"en":["The meaning of the hadith is that “trustworthiness” is not one of the Names of Allah the Exalted, and therefore swearing by it is prohibited."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3253,"lafz":true},{"key":"ibnhibban","label":"صححه ابن حبان","number":4363},{"key":"hakim","label":"الحاكم","number":298},{"key":"ahmad","label":"مسند الإمام أحمد","number":22980,"n":22980}],"full":1,"dr":1},{"num":7092,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا حَلَفَ أَحَدُكُمْ فَلاَ يَقُلْ مَا شَاءَ اللَّهُ وَشِئْتَ. وَلَكِنْ لِيَقُلْ مَا شَاءَ اللَّهُ ثُمَّ شِئْتَ."],"takhrij":"حسن: رواه ابن ماجة (2117) والنسائي في عمل اليوم والليلة (988) وأحمد (1839) والبيهقي (3/217) كلهم من طريق الأجلح الكندي، عن يزيد بن الأصم، عن ابن عباس فذكره واللفظ لابن ماجة.","grade":"حسن","chapter_ar":"باب النهي أن يقال: ما شاء الله وشئت","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2117), al-Nasa’i in ʿAmal al-Yawm wa al-Laylah (988), and Ahmad (1839).","chapter_en":"The Prohibition of Saying: “What Allah Willed and You Willed”","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":28,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ said: “When one of you swears an oath, let him not say: ‘What Allah willed and you willed,’ but rather let him say: ‘What Allah willed, then you willed.’”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2117,"lafz":true},{"key":"amalyawm","label":"النسائي في عمل اليوم والليلة","number":988},{"key":"ahmad","label":"مسند الإمام أحمد","number":1839,"n":1839}],"full":1,"dr":1,"rep":[464,11894]},{"num":7093,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: أُنْزِلَتْ هَذِهِ الآيَةُ فِي قَوْلِ الرَّجُلِ: لاَ وَاللَّهِ، وَبَلَى وَاللَّهِ."],"takhrij":"صحيح: رواه البخاري في التفسير (4613) عن علي بن سلمة، حدثنا مالك بن سُعير، حدثنا هشام، عن أبيه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب قوله تعالى: ( لَا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ )","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4613).","chapter_en":"The Statement of Allah the Exalted: “Allah Will Not Hold You Accountable for Unintentional Oaths”","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":29,"content":{"translation":{"en":["ʿAishah said: This verse was revealed concerning a man’s casual statements: “No, by Allah,” and “Yes, by Allah.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4613,"lafz":true}],"full":1,"dr":1},{"num":7094,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ الأَنْصَارِيِّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ حَلَفَ عَلَى مِنْبَرِي آثِمًا تَبَوَّأَ مَقْعَدَهُ مِنَ النَّارِ."],"takhrij":"حسن: رواه مالك في الأقضية (12) عن هاشم بن هاشم بن عتبة بن أبي وقاص، عن عبد الله بن نسطاس، عن جابر بن عبد الله فذكره.","grade":"حسن","chapter_ar":"باب في تعظيم اليمين على منبر النبي ﷺ","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Hasan: Narrated by Malik (12), Abu Dawud (3246), Ibn Majah (2325), and authenticated by Ibn Hibban (4368).","chapter_en":"The Gravity of Swearing an Oath at the Pulpit of the Prophet ﷺ","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":30,"content":{"translation":{"en":["Jabir ibn ʿAbdullah narrated that the Messenger of Allah ﷺ said: “Whoever swears falsely upon my pulpit, let him take his seat in the Fire.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":12,"lafz":true},{"key":"abudawud","label":"أبو داود","number":3246},{"key":"ibnmajah","label":"ابن ماجه","number":2325},{"key":"ibnhibban","label":"صححه ابن حبان","number":4368},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2826,"n":2823}],"full":1,"dr":1},{"num":7095,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ قَالَ: أَشْهَدُ لَسَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: مَا مِنْ عَبْدٍ أَوْ أَمَةٍ، يَحْلِفُ عِنْدَ هَذَا الْمِنْبَرِ عَلَى يَمِينٍ آثِمَةٍ، وَلَوْ عَلَى سِوَاكٍ رَطْبٍ، إِلَّا وَجَبَتْ لَهُ النَّارُ."],"takhrij":"صحيح: رواه ابن ماجة (2326) وأحمد (8362) وصحّحه الحاكم (4/297) كلهم من حديث أبي عاصم الضحاك بن مخلد، قال: حدثنا الحسن بن يزيد بن فرّوخ، قال: سمعت أبا سلمة يقول: سمعت أبا هريرة يقول فذكر الحديث.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب في تعظيم اليمين على منبر النبي ﷺ","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2326), Ahmad (8362), and authenticated by al-Hakim (7812).","chapter_en":"The Gravity of Swearing an Oath at the Pulpit of the Prophet ﷺ","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":30,"content":{"translation":{"en":["Abu Hurayrah said: I testify that I heard the Prophet ﷺ say: “There is no male or female servant who swears a sinful oath beside this pulpit — even concerning a fresh tooth-stick — except that the Fire becomes obligatory for him.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2326,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":8362,"n":8362},{"key":"hakim","label":"المستدرك على الصحيحين","number":7812,"n":7816}],"full":1,"dr":1},{"num":7096,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَاللَّهِ لأنْ يلجّ أَحَدُكُمْ بِيَمِينِهِ فِي أَهْلِهِ، آثَمُ لَهُ عِنْدَ اللَّهِ مِنْ أَنْ يعطى كَفَّارَتَهُ الَّتِي فَرَضَ اللَّهُ.","وفي رواية: من استلجّ في أهله بيمين فهو أعظم إثماً ليبرّ يعني: الكفارة."],"takhrij":"متفق عليه: رواه البخاري في الأيمان والنذور (6625)، ومسلم في الأيمان والنذور (1655) كلاهما من حديث عبد الرزاق، حدّثنا معمر، عن همام بن منبه قال: هذا ما حدّثنا أبو هريرة عن رسول الله صلى الله عليه وسلم فذكر أحاديث، منها، فذكره. والرواية الأخرى، رواها البخاري (6626) عن إسحاق بن إبراهيم، حدّثنا يحيى بن صالح، حدّثنا معاوية، عن يحيى، عن عكرمة، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب ترك الكفارة وعدم الحنث أشدّ إثماً من التمادي والإصرار على اليمين فيما يتأذى به أهل الحالف","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6625) and Muslim (1655).","chapter_en":"Refusing Expiation and Persisting Upon an Oath That Harms One’s Family Is More Sinful Than Breaking the Oath","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":31,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “By Allah, for one of you to persist stubbornly in an oath concerning his family is more sinful before Allah than giving the expiation Allah has made obligatory.” In another narration: “Whoever stubbornly persists in an oath concerning his family commits a greater sin than offering the expiation.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6625,"lafz":true},{"key":"muslim","label":"مسلم","number":1655},{"key":"bukhari","label":"رواها البخاري","number":6626}],"full":1},{"num":7097,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ قَالَ سُلَيْمَانُ بْنُ دَاوُدَ نَبِيُّ اللَّهِ لأَطُوفَنَّ اللَّيْلَةَ عَلَى سَبْعِينَ امْرَأَةً كُلُّهُنَّ تَأْتِي بِغُلاَمٍ يُقَاتِلُ فِي سَبِيلِ اللَّهِ. فَقَالَ لَهُ صَاحِبُهُ أَوِ الْمَلَكُ قُلْ إِنْ شَاءَ اللَّهُ. فَلَمْ يَقُلْ وَنَسِيَ. فَلَمْ تَأْتِ وَاحِدَةٌ مِنْ نِسَائِهِ إِلاَّ وَاحِدَةٌ جَاءَتْ بِشِقِّ غُلاَمٍ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَوْ قَالَ إِنْ شَاءَ اللَّهُ. لَمْ يَحْنَثْ وَكَانَ دَرَكًا لَهُ فِي حَاجَتِهِ.","وفي رواية: لو كان استثنى."],"takhrij":"متفق عليه: رواه البخاري في كفارات الأيمان (6720) ومسلم في الأيمان والنذور (1654: 23) كلاهما من طريق سفيان، عن هشام بن حُجير، عن طاوس، عن أبي هريرة فذكره. والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"باب الاستثناء في اليمين","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6720) and Muslim (1654:23). The wording is from Muslim.","chapter_en":"Making an Exception in an Oath by Saying “If Allah Wills”","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":32,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said: “Sulaiman ibn Dawud, the Prophet of Allah, said: ‘Tonight I will go around to seventy women, each of whom will give birth to a boy who will fight in the cause of Allah.’ His companion — or the angel — said to him: ‘Say: If Allah wills.’ But he did not say it and forgot. None of his wives gave birth except one, and she brought forth half of a child.” The Messenger of Allah ﷺ then said: “Had he said: ‘If Allah wills,’ he would not have broken his oath, and it would have helped him attain what he wanted.” In another narration: “Had he made the exception.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6720,"lafz":true},{"key":"muslim","label":"مسلم","number":1654,"n":4286}],"full":1,"dr":1},{"num":7098,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ حَلَفَ عَلَى يَمِينٍ فَقَالَ إِنْ شَاءَ اللَّهُ لَمْ يَحْنَثْ."],"takhrij":"صحيح: رواه الترمذي (1532) والنسائي (3855) وابن ماجة (2104) وأحمد (8088) كلهم من حديث عبد الرزاق – وهو في مصنفه (16118) عن معمر، عن ابن طاوس، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب الاستثناء في اليمين","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1532), al-Nasa’i (3855), Ibn Majah (2104), and Ahmad (8088).","chapter_en":"Making an Exception in an Oath by Saying “If Allah Wills”","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":32,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever swears an oath and says: ‘If Allah wills,’ has not broken his oath.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1532,"lafz":true},{"key":"nasai","label":"النسائي","number":3855,"n":3830},{"key":"ibnmajah","label":"ابن ماجه","number":2104,"n":2096},{"key":"ahmad","label":"مسند الإمام أحمد","number":8088,"n":8056},{"key":"abdrazzaq","label":"عبد الرزاق – وهو في مصنفه","number":16118}],"full":1,"dr":1},{"num":7099,"demo":false,"sanad":"","matn":["عن ابن عمر أن النبي صلى الله عليه وسلم قال: من حلف فقال: إن شاء، فقد استثنى، فلا حنث عليه."],"takhrij":"صحيح: رواه أبو داود (3262،3261) والترمذي (1531) والنسائي (3829) وابن ماجة (2105) وصحَّحه ابن حبان (4339) والحاكم (4/303) كلهم من حديث أيوب، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب الاستثناء في اليمين","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3261, 3262), al-Tirmidhi (1531) who graded it Hasan, and al-Nasa’i (3829).","chapter_en":"Making an Exception in an Oath by Saying “If Allah Wills”","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":32,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Prophet ﷺ said: “Whoever swears and says: ‘If Allah wills,’ has made an exception, so there is no breaking of the oath upon him.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3261,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1531},{"key":"nasai","label":"النسائي","number":3829},{"key":"abudawud","label":"ابو داود","number":3262},{"key":"ibnmajah","label":"ابن ماجه","number":2105,"n":2210},{"key":"ibnhibban","label":"ابن حبان","number":4339}],"full":1,"dr":1},{"num":7100,"demo":false,"sanad":"","matn":["عَنْ نَافِعٍ، قَالَ كَانَ ابْنُ عُمَرَ يُعْطِي زَكَاةَ رَمَضَانَ بِمُدِّ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمُدِّ الأَوَّلِ، وَفِي كَفَّارَةِ الْيَمِينِ بِمُدِّ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ أَبُو قُتَيْبَةَ قَالَ لَنَا مَالِكٌ مُدُّنَا أَعْظَمُ مِنْ مُدِّكُمْ وَلاَ نَرَى الْفَضْلَ إِلاَّ فِي مُدِّ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. وَقَالَ لِي مَالِكٌ لَوْ جَاءَكُمْ أَمِيرٌ فَضَرَبَ مُدًّا أَصْغَرَ مِنْ مُدِّ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِأَىِّ شَىْءٍ كُنْتُمْ تُعْطُونَ قُلْتُ كُنَّا نُعْطِي بِمُدِّ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ أَفَلاَ تَرَى أَنَّ الأَمْرَ إِنَّمَا يَعُودُ إِلَى مُدِّ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه البخاري في كفارات الأيمان (6713) عن منذر بن الوليد الجاروديّ، حدثنا أبو قتيبة (وهو مسلم) حدثنا مالك، عن نافع، به، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في كفارة اليمين","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6713).","chapter_en":"What Has Been Reported Regarding the Expiation of an Oath","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":33,"content":{"translation":{"en":["Nafiʿ said: Ibn ʿUmar used to give the Zakat of Ramadan using the Prophet ﷺ’s mudd — the original mudd — and he also used the Prophet ﷺ’s mudd in the expiation of oaths. Abu Qutaybah said: Malik said to us: “Our mudd is larger than yours, but we do not consider virtue to be except in the mudd of the Prophet ﷺ.” Malik also said to me: “If a ruler came to you and established a mudd smaller than the Prophet ﷺ’s mudd, by which measure would you give?” I said: “We would give according to the Prophet ﷺ’s mudd.” He said: “Do you not see that the matter only returns to the mudd of the Prophet ﷺ?”"]},"intro":{"ar":["قال اللّٰه تعالى: ﴿لَا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَٰكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الْأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلَاثَةِ أَيَّامٍ ذَٰلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ كَذَٰلِكَ يُبَيِّنُ اللَّهُ لَكُمْ آيَاتِهِ لَعَلَّكُمْ تَشْكُرُونَ﴾ [المائدة: ٨٩]"],"en":["Allah the Exalted said:","“Allah will not call you to account for what is unintentional in your oaths, but He will call you to account for what you deliberately bind yourselves to in oaths. Its expiation is feeding ten needy people from the average of what you feed your families, or clothing them, or freeing a slave. But whoever cannot find the means, then fasting three days. That is the expiation for your oaths when you swear. And guard your oaths. Thus does Allah make clear to you His verses so that you may be grateful.” [Surah al-Ma’idah: 89]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6713,"lafz":true}],"full":1,"dr":1},{"num":7101,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ تَسْأَلِ الإِمَارَةَ، فَإِنَّكَ إِنْ أُعْطِيتَهَا عَنْ غَيْرِ مَسْأَلَةٍ أُعِنْتَ عَلَيْهَا، وَإِنْ أُعْطِيتَهَا عَنْ مَسْأَلَةٍ وُكِلْتَ إِلَيْهَا، وَإِذَا حَلَفْتَ عَلَى يَمِينٍ فَرَأَيْتَ غَيْرَهَا خَيْرًا مِنْهَا، فَأْتِ الَّذِي هُوَ خَيْرٌ، وَكَفِّرْ عَنْ يَمِينِكَ.","وفي رواية: فكفّر عن يمينك، وائت الذي هو خير."],"takhrij":"متفق عليه: رواه البخاري في كفارات الأيمان (6722)، ومسلم في الأيمان والنذور (19:1652) كلاهما من طريق الحسن، حدّثنا عبد الرحمن بن سمرة، فذكره والسياق للبخاري، والرواية الثانية لمسلم.","grade":"متفق عليه","chapter_ar":"باب من حلف على يمين فرأى غيرها خيراً منها فليكفر عن يمينه ويأت الذي هو خير","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6722) and Muslim (1652:19). The wording is from al-Bukhari, while the second narration is from Muslim.","chapter_en":"Whoever Swears an Oath Then Sees Something Better Than It Should Expiate His Oath and Do What Is Better","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":34,"content":{"translation":{"en":["ʿAbd al-Rahman ibn Samurah said: The Messenger of Allah ﷺ said: “Do not ask for leadership. For if you are given it without asking, you will be helped in it; but if you are given it because of asking, you will be left to yourself in it. And when you swear an oath, then see something better than it, do what is better and expiate your oath.” In another narration: “Expiate your oath and do what is better.”"]},"intro":{"ar":["قال اللّٰه تعالى: ﴿وَلَا تَجْعَلُوا اللَّهَ عُرْضَةً لِأَيْمَانِكُمْ أَنْ تَبَرُّوا وَتَتَّقُوا وَتُصْلِحُوا بَيْنَ النَّاسِ وَاللَّهُ سَمِيعٌ عَلِيمٌ﴾ [البقرة: ٢٢٤]","وقوله: ( عُرْضَةً لِأَيْمَانِكُمْ ) أي مانعاً لكم عن البر وصلة الرحم، والاعتراض هو المنع.","فإن حلف على ترك المندوب، أو فعل مكروه، فالواجب عليه التكفير عن يمينه والإتيان بما هو خير، وإلا فحفظ الأيمان أولى لقوله تعالى: ( وَاحْفَظُوا أَيْمَانَكُمْ ) [المائدة: ٨٩] أي احفظوها من الحنث. لأن الأيمان ثلاث:","إما على ترك المندوب فيكفّر ويأتي به، أو على إتيان المكروه فيكفّر ولا يأتي به، أو يمين اللغو فليس عليه شيء."],"en":["Allah the Exalted said:","“And do not make Allah, by your oaths, an obstacle to righteousness.” [Surah al-Baqarah: 224]","His statement: “an obstacle to your oaths” means a barrier preventing you from righteousness and maintaining family ties. The word indicates prevention.","So if someone swears to abandon something recommended, or to do something disliked, then he must expiate his oath and do what is better. Otherwise, preserving oaths is preferred due to the statement of Allah: “And guard your oaths.” [Surah al-Ma’idah: 89] meaning: guard them from being broken. Oaths are of three types:","Either an oath to abandon something recommended — then one expiates and does the good deed; or an oath to do something disliked — then one expiates and avoids it; or an unintentional oath, for which there is nothing due."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6722,"lafz":true},{"key":"muslim","label":"مسلم","number":1652},{"key":"muslim","label":"مسلم في الايمان والنذور","number":19}],"full":1,"dr":1},{"num":7102,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ حَلَفَ بِيَمِينٍ فَرَأَى غَيْرَهَا خَيْرًا مِنْهَا فَلْيُكَفِّرْ عَنْ يَمِينِهِ وَلْيَفْعَلِ الَّذِي هُوَ خَيْرٌ."],"takhrij":"صحيح: رواه مالك في النذور والأيمان (11) عن سهيل بن أبي صالح، عن أبيه، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب من حلف على يمين فرأى غيرها خيراً منها فليكفر عن يمينه ويأت الذي هو خير","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (11) and Muslim (1650:12).","chapter_en":"Whoever Swears an Oath Then Sees Something Better Than It Should Expiate His Oath and Do What Is Better","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":34,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever swears an oath, then sees something better than it, should expiate his oath and do what is better.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":11,"lafz":true},{"key":"muslim","label":"مسلم","number":1650,"n":4272}],"full":1,"dr":1,"rep":[12857]},{"num":7103,"demo":false,"sanad":"","matn":["عَنْ مَالِكِ بن نضلة الجشمي قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَعَّدَ فيّ النَّظَرَ، وصوَّب، وَقَالَ: أربُّ إِبِلٍ أَنْتَ أَوْ رَبُّ غَنَمٍ؟ قَالَ: مِنْ كُلٍّ قَدْ آتَانِي اللَّهُ، فَأَكْثَرَ وَأَطْيَبَ، قَالَ: فَتُنْتِجُهَا وَافِيَةً أَعْيُنُهَا وَآذَانُهَا، فَتَجْدَعُ هَذِهِ، فَتَقُولُ صَرْمَا ثُمَّ تَكَلَّمَ سُفْيَانُ بِكَلِمَةٍ لَمْ أَفْهَمْهَا وَتَقُولُ: بَحِيرَةَ اللهِ؟ فَسَاعِدُ اللهِ أشدّ، وَمُوسَاهُ أحدُّ، وَلَوْ شَاءَ أَنْ يَأْتِيَكَ بِهَا صَرْمَا أَتَاكَ قُلْتُ: إِلَى مَا تَدْعُو؟ قَالَ: إِلَى اللَّهِ وَإِلَى الرَّحِمِ قُلْتُ: يَأْتِينِي الرَّجُلُ مِنْ بَنِي عَمِّي، فَأَحْلِفُ أَنْ لَا أُعْطِيَهُ ثُمَّ أُعْطِيهِ؟ قَالَ: فَكَفِّرْ عَنْ يَمِينِكَ، وَأْتِ الَّذِي هُوَ خَيْرٌ، أَرَأَيْتَ لَوْ كَانَ لَكَ عَبْدَانِ أَحَدُهُمَا يُطِيعُكَ وَلَا يَخُونُكَ وَلَا يَكْذِبُكَ، وَالْآخَرُ يَخُونُكَ وَيَكْذِبُكَ؟ قَالَ: قُلْتُ: لَا، بَلِ الَّذِي لَا يَخُونُنِي، وَلَا يَكْذِبُنِي، وَيَصْدُقُنِي الْحَدِيثَ أَحَبُّ إليّ. قَالَ: كَذَاكُمْ أَنْتُمْ عِنْدَ رَبِّكُمْ عَزَّ وَجَلَّ."],"takhrij":"صحيح: رواه الإمام أحمد (17228) واللفظ له، واختصره النسائي (3788) وابن ماجة (2109) كلهم من حديث سفيان بن عيينة، قال: حدثنا أبو الزعراء عمرو بن عمرو، عن عمه أبي الأحوص عوف بن مالك الجُشمي، عن أبيه مالك فذكره وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب من حلف على يمين فرأى غيرها خيراً منها فليكفر عن يمينه ويأت الذي هو خير","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (17228) with this wording, al-Nasa’i (3788), and Ibn Majah (2109).","chapter_en":"Whoever Swears an Oath Then Sees Something Better Than It Should Expiate His Oath and Do What Is Better","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":34,"content":{"translation":{"en":["Malik ibn Nadlah al-Jushami said: I came to the Prophet ﷺ and he looked me up and down and said: “Are you an owner of camels or an owner of sheep?” I said: “Allah has given me both, in abundance and of good quality.” He said: “So your animals are born with full ears and eyes, then you cut the ears of some of them and say: ‘These are set apart,’” then Sufyan mentioned a word I did not understand, “and you say: ‘These are Allah’s consecrated animals’? Yet Allah’s knife is sharper and His forearm is stronger. Had He wished, He could have caused them all to be born mutilated.” I said: “What do you call people to?” He said: “To Allah and to maintaining family ties.” I said: “A relative from my clan comes to me, and I swear not to give him anything, then later I give him?” He said: “Expiate your oath and do what is better. Tell me, if you had two servants — one obeyed you, never betrayed you, and never lied to you, while the other betrayed and lied to you — which one would be more beloved to you?” I said: “The one who does not betray or lie to me and speaks truthfully.” He said: “That is how you are before your Lord, the Mighty and Majestic.”"]},"buhuth":{"en":["In the narration of al-Nasa’i: “He ordered me to do what was better and expiate my oath.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":17228,"lafz":true},{"key":"nasai","label":"النسائي","number":3788},{"key":"ibnmajah","label":"ابن ماجه","number":2109}],"full":1,"dr":1},{"num":7104,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، قَالَ: أَفَاءَ اللَّهُ عَلَى رَسُولِهِ إِبِلًا فَفَرَّقَهَا، فَقَالَ أَبُو مُوسَى: يَا رَسُولَ اللَّهِ احْمِلْنِي، فَقَالَ: لَا، فَقَالَهُ ثَلَاثًا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : وَاللَّهِ لَا أَفْعَلُ، وَبَقِيَ أَرْبَعٌ غُرُّ الذُّرَى، فَقَالَ: يَا أَبَا مُوسَى خُذْهُنَّ، فَقَالَ: يَا رَسُولَ اللَّهِ إِنِّي اسْتَحْمَلْتُكَ فَمَنَعْتَنِي، وَحَلَفْتَ فَأَشْفَقْتُ أَنْ يَكُونَ دَخَلَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  وَهُمْ، فَقَالَ: إِنِّي إِذَا حَلَفْتُ فَرَأَيْتُ أَنَّ غَيْرَ ذَلِكَ أَفْضَلُ كَفَّرْتُ عَنْ يَمِينِي، وَأَتَيْتُ الَّذِي هُوَ خَيْرٌ."],"takhrij":"صحيح: رواه أبو عوانة (4/40) عن أبي أمية والصغاني، قالا: ثنا الحكم بن موسى، ثنا الهيثم بن حُميد، عن زيد بن واقد، عن بُسر بن عبيد الله، عن ابن عائذ، عن أبي الدرداء فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب من حلف على يمين فرأى غيرها خيراً منها فليكفر عن يمينه ويأت الذي هو خير","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Abu ʿAwanah (4/40).","chapter_en":"Whoever Swears an Oath Then Sees Something Better Than It Should Expiate His Oath and Do What Is Better","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":34,"content":{"translation":{"en":["Abu al-Darda’ narrated that Allah granted camels to His Messenger ﷺ, so he distributed them. Abu Musa said: “O Messenger of Allah ﷺ, give me a mount.” He replied: “No.” He repeated this three times. Then the Prophet ﷺ said: “By Allah, I will not do so.” Later, four camels remained, and he said: “O Abu Musa, take them.” Abu Musa said: “O Messenger of Allah ﷺ, I asked you for mounts and you refused and swore an oath, so I feared that perhaps forgetfulness had affected the Messenger of Allah ﷺ.” So he ﷺ said: “When I swear an oath and later see something else better than it, I expiate my oath and do what is better.”"]}},"tuhfa":{},"refs":[{"key":"sh21618","label":"أبو عوانة","number":4,"lafz":true}],"full":1,"dr":1},{"num":7105,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ أَعْتَمَ رَجُلٌ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ رَجَعَ إِلَى أَهْلِهِ فَوَجَدَ الصِّبْيَةَ قَدْ نَامُوا فَأَتَاهُ أَهْلُهُ بِطَعَامِهِ فَحَلَفَ لاَ يَأْكُلُ مِنْ أَجْلِ صِبْيَتِهِ ثُمَّ بَدَا لَهُ فَأَكَلَ فَأَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ ذَلِكَ لَهُ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ حَلَفَ عَلَى يَمِينٍ فَرَأَى غَيْرَهَا خَيْرًا مِنْهَا فَلْيَأْتِهَا وَلْيُكَفِّرْ عَنْ يَمِينِهِ."],"takhrij":"صحيح: رواه مسلم في الأيمان والنذور (11:1650) عن زهير بن حرب، حدثنا مروان بن معاوية الفزاري أخبرنا يزيد بن كيسان، عن أبي حازم، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب الحنث قبل التكفير","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1650:11).","chapter_en":"Breaking the Oath Before Offering the Expiation","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":35,"content":{"translation":{"en":["Abu Hurayrah said: A man stayed with the Prophet ﷺ until late at night, then returned to his family and found that the children had fallen asleep. His family brought him food, but he swore not to eat because of his children. Later he reconsidered and ate. Then he came to the Messenger of Allah ﷺ and mentioned that to him. The Messenger of Allah ﷺ said: “Whoever swears an oath and then sees something better than it should do what is better and expiate his oath.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1650,"lafz":true},{"key":"muslim","label":"مسلم في الايمان والنذور","number":11}],"full":1,"dr":1},{"num":7106,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ أَبَا بَكْرٍ رَضِيَ اللَّهُ عَنْهُ لَمْ يَكُنْ يَحْنَثُ فِي يَمِينٍ قَطُّ، حَتَّى أَنْزَلَ اللَّهُ كَفَّارَةَ الْيَمِينِ وَقَالَ لاَ أَحْلِفُ عَلَى يَمِينٍ فَرَأَيْتُ غَيْرَهَا خَيْرًا مِنْهَا، إِلاَّ أَتَيْتُ الَّذِي هُوَ خَيْرٌ، وَكَفَّرْتُ عَنْ يَمِينِي."],"takhrij":"صحيح: رواه البخاري في الأيمان والنذور (6621) عن محمد بن مقاتل أبي الحسن، أخبرنا عبدالله (ابن المبارك)، أخبرنا هشام بن عروة، عن أبيه، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب الحنث قبل التكفير","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6621).","chapter_en":"Breaking the Oath Before Offering the Expiation","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":35,"content":{"translation":{"en":["ʿAishah bint al-Siddiq said that Abu Bakr may Allah be pleased with him never used to break an oath until Allah revealed the expiation for oaths. Then he said: “I will never swear an oath and then see something better than it except that I will do what is better and expiate my oath.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6621,"lafz":true}],"full":1,"dr":1},{"num":7107,"demo":false,"sanad":"","matn":["عَنْ تَمِيمِ بْنِ طَرَفَةَ، قَالَ جَاءَ سَائِلٌ إِلَى عَدِيِّ بْنِ حَاتِمٍ فَسَأَلَهُ نَفَقَةً فِي ثَمَنِ خَادِمٍ أَوْ فِي بَعْضِ ثَمَنِ خَادِمٍ. فَقَالَ لَيْسَ عِنْدِي مَا أُعْطِيكَ إِلاَّ دِرْعِي وَمِغْفَرِي فَأَكْتُبُ إِلَى أَهْلِي أَنْ يُعْطُوكَهَا. قَالَ فَلَمْ يَرْضَ فَغَضِبَ عَدِيٌّ فَقَالَ أَمَا وَاللَّهِ لاَ أُعْطِيكَ شَيْئًا ثُمَّ إِنَّ الرَّجُلَ رَضِيَ فَقَالَ أَمَا وَاللَّهِ لَوْلاَ أَنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ مَنْ حَلَفَ عَلَى يَمِينٍ ثُمَّ رَأَى أَتْقَى لِلَّهِ مِنْهَا فَلْيَأْتِ التَّقْوَى. مَا حَنَّثْتُ يَمِينِي."],"takhrij":"صحيح: رواه مسلم في الأيمان والنذور (15:1651) عن قتيبة بن سعيد، حدثنا جرير، عن عبد العزيز بن رفيع، عن تميم بن طرفة، فذكره.","grade":"صحيح","chapter_ar":"باب الحنث قبل التكفير","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1651:15).","chapter_en":"Breaking the Oath Before Offering the Expiation","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":35,"content":{"translation":{"en":["Tamim ibn Tarfah said: A beggar came to ʿAdi ibn Hatim asking him for assistance toward the price of a servant or part of the price of a servant. ʿAdi said: “I have nothing to give you except my armor and helmet, so write to my family and they will give them to you.” The man was not satisfied, so ʿAdi became angry and said: “By Allah, I will give you nothing.” Then the man became satisfied, so ʿAdi said: “By Allah, had I not heard the Messenger of Allah ﷺ say: ‘Whoever swears an oath then sees something more pleasing to Allah than it should do what is more pleasing to Allah,’ I would not have broken my oath.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1651,"lafz":true},{"key":"muslim","label":"مسلم في الايمان والنذور","number":15}],"full":1,"dr":1},{"num":7108,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ حَلَفَ عَلَى يَمِينٍ، فَرَأَى غَيْرَهَا خَيْرًا مِنْهَا، فَلْيَأْتِ الَّذِي هُوَ خَيْرٌ، وَلْيُكَفِّرْ عَنْ يَمِينِهِ."],"takhrij":"حسن: رواه النسائي (3781) وابن ماجة (2111) وابن حبان (4347) كلهم من حديث عبد الله بن عمرو.","grade":"حسن","chapter_ar":"باب الحنث قبل التكفير","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (3781), Ibn Majah (2111), and Ibn Hibban (4347).","chapter_en":"Breaking the Oath Before Offering the Expiation","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":35,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr said: The Messenger of Allah ﷺ said: “Whoever swears an oath and then sees something better than it should do what is better and expiate his oath.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3781,"lafz":true,"n":3785},{"key":"ibnmajah","label":"ابن ماجه","number":2111,"n":2108},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":5586,"n":5582},{"key":"ibnhibban","label":"ابن حبان","number":4347}],"full":1,"dr":1},{"num":7109,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى الأشعري قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي رَهْطٍ مِنَ الأَشْعَرِيِّينَ أَسْتَحْمِلُهُ، فَقَالَ: وَاللَّهِ لاَ أَحْمِلُكُمْ وَمَا عِنْدِي مَا أَحْمِلُكُمْ عَلَيْهِ قَالَ: ثُمَّ لَبِثْنَا مَا شَاءَ اللَّهُ أَنْ نَلْبَثَ، ثُمَّ أُتي بِثَلاَثِ ذوْد غرّ الذُّرَى، فَحَمَلَنَا عَلَيْهَا، فَلَمَّا انْطَلَقْنَا قُلْنَا أَوْ قَالَ بَعْضُنَا: وَاللَّهِ لاَ يُبَارَكُ لَنَا، أَتَيْنَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَسْتَحْمِلُهُ فَحَلَفَ أَنْ لاَ يَحْمِلَنَا ثُمَّ حَمَلَنَا، فَارْجِعُوا بِنَا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَنُذَكِّرُهُ، فَأَتَيْنَاهُ، فَقَالَ: مَا أَنَا حَمَلْتُكُمْ، بَلِ اللَّهُ حَمَلَكُمْ، وَإِنِّي وَاللَّهِ – إِنْ شَاءَ اللَّهُ – لاَ أَحْلِفُ عَلَى يَمِينٍ، فَأَرَى غَيْرَهَا خَيْرًا مِنْهَا، إِلاَّ كَفَّرْتُ عَنْ يَمِينِي وَأَتَيْتُ الَّذِي هُوَ خَيْرٌ، أَوْ أَتَيْتُ الَّذِي هُوَ خَيْرٌ وَكَفَّرْتُ عَنْ يَمِينِي."],"takhrij":"متفق عليه: رواه البخاري في الأيمان والنذور (6623) ومسلم في الأيمان والنذور (7:1649) كلاهما من طريق حماد بن زيد، عن غيلان بن جرير، عن أبي بردة، عن أبي موسى الأشعري، فذكره.","grade":"متفق عليه","chapter_ar":"باب في الخيار بين تقديم الكفارة وتأخيرها","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6623) and Muslim (1649:7).","chapter_en":"The Choice Between Giving Expiation Before or After Breaking the Oath","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":36,"content":{"translation":{"en":["Abu Musa al-Ashʿari said: I came to the Prophet ﷺ with a group from al-Ashʿariyyin seeking mounts. He said: “By Allah, I will not provide mounts for you, and I have nothing upon which to mount you.” Then we remained for as long as Allah willed. Later, three fine camels with bright humps were brought, and he gave us mounts from them. As we departed, we said — or some of us said —: “By Allah, there will be no blessing for us. We came to the Prophet ﷺ asking for mounts, and he swore not to give us mounts, then he gave them to us. Return us to the Prophet ﷺ so we may remind him.” So we returned to him, and he said: “It was not I who mounted you; rather Allah mounted you. And by Allah — if Allah wills — I do not swear an oath then see something better than it except that I expiate my oath and do what is better, or do what is better and expiate my oath.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6623,"lafz":true},{"key":"muslim","label":"مسلم","number":1649},{"key":"muslim","label":"مسلم في الايمان والنذور","number":7}],"full":1},{"num":7110,"demo":false,"sanad":"","matn":["عن زهدم قَالَ: كُنَّا عِنْدَ أَبِي مُوسَى فَدَعَا بِمَائِدَتِهِ وَعَلَيْهَا لَحْمُ دَجَاجٍ فَدَخَلَ رَجُلٌ مِنْ بَنِي تَيْمِ اللَّهِ أَحْمَرُ شَبِيهٌ بِالْمَوَالِي فَقَالَ لَهُ هَلُمَّ. فَتَلَكَّأَ فَقَالَ هَلُمَّ فَإِنِّي قَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْكُلُ مِنْهُ. فَقَالَ الرَّجُلُ إِنِّي رَأَيْتُهُ يَأْكُلُ شَيْئًا فَقَذِرْتُهُ فَحَلَفْتُ أَنْ لاَ أَطْعَمَهُ فَقَالَ هَلُمَّ أُحَدِّثْكَ عَنْ ذَلِكَ إِنِّي أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي رَهْطٍ مِنَ الأَشْعَرِيِّينَ نَسْتَحْمِلُهُ فَقَالَ وَاللَّهِ لاَ أَحْمِلُكُمْ وَمَا عِنْدِي مَا أَحْمِلُكُمْ عَلَيْهِ. فَلَبِثْنَا مَا شَاءَ اللَّهُ فَأُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِنَهْبِ إِبِلٍ فَدَعَا بِنَا فَأَمَرَ لَنَا بِخَمْسِ ذَوْدٍ غُرِّ الذُّرَى قَالَ فَلَمَّا انْطَلَقْنَا قَالَ بَعْضُنَا لِبَعْضٍ أَغْفَلْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمِينَهُ لاَ يُبَارَكُ لَنَا. فَرَجَعْنَا إِلَيْهِ فَقُلْنَا يَا رَسُولَ اللَّهِ إِنَّا أَتَيْنَاكَ نَسْتَحْمِلُكَ وَإِنَّكَ حَلَفْتَ أَنْ لاَ تَحْمِلَنَا ثُمَّ حَمَلْتَنَا أَفَنَسِيتَ يَا رَسُولَ اللَّهِ قَالَ إِنِّي وَاللَّهِ إِنْ شَاءَ اللَّهُ لاَ أَحْلِفُ عَلَى يَمِينٍ فَأَرَى غَيْرَهَا خَيْرًا مِنْهَا إِلاَّ أَتَيْتُ الَّذِي هُوَ خَيْرٌ وَتَحَلَّلْتُهَا فَانْطَلِقُوا فَإِنَّمَا حَمَلَكُمُ اللَّهُ عَزَّ."],"takhrij":"متفق عليه: رواه البخاري في فرض الخمس (3133) ومسلم في الأيمان (9:1649) كلاهما من حديث حماد بن زيد، عن أيوب، عن أبي قلابة، وعن القاسم بن عاصم، عن زهدم الجرْمي.","grade":"متفق عليه","chapter_ar":"باب في الخيار بين تقديم الكفارة وتأخيرها","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3133) and Muslim (1649:9).","chapter_en":"The Choice Between Giving Expiation Before or After Breaking the Oath","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":36,"content":{"translation":{"en":["Zuhdam said: We were with Abu Musa, and he called for his table upon which was chicken meat. A man from Banu Taym Allah entered, reddish in complexion and resembling freed slaves. Abu Musa said to him: “Come eat.” The man hesitated, so he said: “Come, for I saw the Messenger of Allah ﷺ eating from it.” The man replied: “I once saw it eating something filthy, so I swore not to eat it.” Abu Musa said: “Come, and I will tell you about that. I came to the Messenger of Allah ﷺ with a group from al-Ashʿariyyin seeking mounts, and he said: ‘By Allah, I will not provide mounts for you, and I have nothing upon which to mount you.’ We remained for as long as Allah willed. Then the Messenger of Allah ﷺ received some camels, so he called for us and ordered that five fine camels with bright humps be given to us. As we departed, some of us said to others: ‘The Messenger of Allah ﷺ forgot his oath. There will be no blessing for us.’ So we returned and said: ‘O Messenger of Allah ﷺ, we came asking you for mounts, and you swore not to give us mounts, then you gave them to us. Did you forget, O Messenger of Allah ﷺ?’ He replied: ‘By Allah — if Allah wills — I do not swear an oath and then see something better than it except that I do what is better and free myself from the oath. Go, for indeed Allah the Mighty and Majestic is the One who provided your mounts.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3133,"lafz":true},{"key":"muslim","label":"مسلم","number":1649,"n":4265},{"key":"muslim","label":"مسلم في الايمان","number":9}],"full":1,"dr":1},{"num":7111,"demo":false,"sanad":"","matn":["أَنَّ أَبَا مُوسَى اسْتَحْمَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَوَافَقَ مِنْهُ شُغْلًا فَقَالَ: وَاللَّهِ لَا أَحْمِلُكَ. فَلَمَّا قَفَا دَعَاهُ فَحَمَلَهُ، فَقَالَ: يَا رَسُولَ اللَّهِ إِنَّكَ حَلَفْتَ أَنْ لَا تَحْمِلَنِي قَالَ: فَأَنَا أَحْلِفُ لَأَحْمِلَنَّكَ."],"takhrij":"صحيح: رواه أحمد (12056) والبزار –كشف الأستار (1344) وأبو يعلى (3835) كلهم من حديث حميد الطويل، عن أنس، أن أبا موسى، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب في الخيار بين تقديم الكفارة وتأخيرها","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (12056), al-Bazzar in Kashf al-Astar (1344), and Abu Yaʿla (3835).","chapter_en":"The Choice Between Giving Expiation Before or After Breaking the Oath","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في الأيمان","group_en":"Collection of Chapters Regarding Oaths","part_no":35,"group_no":1,"chapter_no":36,"content":{"translation":{"en":["Abu Musa asked the Prophet ﷺ for a mount while he was occupied, so he said: “By Allah, I will not give you a mount.” Then when Abu Musa turned away, the Prophet ﷺ called him back and gave him a mount. Abu Musa said: “O Messenger of Allah ﷺ, you swore that you would not give me a mount.” He ﷺ replied: “Then I swear that I will indeed give you a mount.”"]},"buhuth":{"en":["The meaning of his statement, “Then I swear that I will indeed give you a mount,” is: I will expiate my oath and provide you with a mount."]}},"tuhfa":{},"refs":[{"key":"sh12862","label":"البزار — كشف الأستار","number":1344},{"key":"sh12520","label":"أبو يعلى","number":3835},{"key":"ahmad","label":"مسند الإمام أحمد","number":12056,"n":12056,"lafz":true}],"full":1,"dr":1},{"num":7112,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : خَيْرُكُمْ قَرْنِي ثُمَّ الَّذِينَ يَلُونَهُمْ، ثُمَّ الَّذِينَ يَلُونَهُمْقَالَ عِمْرَانُ: لاَ أَدْرِي أَذَكَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْدُ قَرْنَيْنِ أَوْ ثَلاَثَةً، قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنَّ بَعْدَكُمْ قَوْمًا ... ينذرون وَلاَ يوفون."],"takhrij":"متفق عليه: رواه البخاري في الشهادات (2651) ومسلم في فضائل الصحابة (2535) كلاهما من حديث شعبة، حدثنا أبو حمزة، حدثني زهْدم بن مضرب، سمعت عمران بن حصين فذكره.","grade":"متفق عليه","chapter_ar":"باب الترغيب في الوفاء بالنذر","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2651) and Muslim (2535).","chapter_en":"Encouragement to Fulfill Vows","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["ʿImran ibn Husayn said: The Prophet ﷺ said: “The best of you are my generation, then those who follow them, then those who follow them.” ʿImran said: I do not know whether the Prophet ﷺ mentioned two generations after his or three. The Prophet ﷺ said: “After you there will be people who make vows but do not fulfill them.”"]},"intro":{"ar":["قال اللّٰه تعالى:","( يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا ) [الإنسان: ٧]"],"en":["Allah the Exalted said:","“They fulfill their vows and fear a Day whose evil will be widespread.” [Surah al-Insan: 7]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2651,"lafz":true},{"key":"muslim","label":"مسلم","number":2535}],"full":1},{"num":7113,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ قَالَ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَعْضِ مَغَازِيهِ، فَلَمَّا انْصَرَفَ جَاءَتْ جَارِيَةٌ سَوْدَاءُ، فَقَالَتْ: يَا رَسُولَ اللَّهِ إِنِّي كُنْتُ نَذَرْتُ إِنْ ردّك اللَّهُ سَالِمًا أَنْ أَضْرِبَ بَيْنَ يَدَيْكَ بِالدُّفِّ وَأَتَغَنَّى، فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنْ كُنْتِ نَذَرْتِ فَاضْرِبِي وَإِلاَّ فَلاَ فَجَعَلَتْ تَضْرِبُ، فَدَخَلَ أَبُو بَكْرٍ وَهِيَ تَضْرِبُ، ثُمَّ دَخَلَ عَلِيٌّ وَهِيَ تَضْرِبُ، ثُمَّ دَخَلَ عُثْمَانُ وَهِيَ تَضْرِبُ، ثُمَّ دَخَلَ عُمَرُ فَأَلْقَتِ الدُّفَّ تَحْتَ اسْتِهَا ثُمَّ قَعَدَتْ عَلَيْهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنَّ الشَّيْطَانَ لَيَخَافُ مِنْكَ يَا عُمَرُ، إِنِّي كُنْتُ جَالِسًا وَهِيَ تَضْرِبُ فَدَخَلَ أَبُو بَكْرٍ وَهِيَ تَضْرِبُ، ثُمَّ دَخَلَ عليّ وَهِيَ تَضْرِبُ، ثُمَّ دَخَلَ عُثْمَانُ وَهِيَ تَضْرِبُ. فَلَمَّا دَخَلْتَ أَنْتَ يَا عُمَرُ أَلْقَتِ الدُّفَّ."],"takhrij":"حسن: رواه الترمذي (3690) وأحمد (22989) والبيهقي (10/77) وصحّحه ابن حبان (4386) كلهم من طريق الحسين بن واقد قال: حدثني عبد الله بن بريدة، قال: سمعت أبي بريدة يقول: فذكره.","grade":"حسن","chapter_ar":"باب الترغيب في الوفاء بالنذر","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (3690), who graded it Hasan; Ahmad (22989); and authenticated by Ibn Hibban (4386).","chapter_en":"Encouragement to Fulfill Vows","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Buraydah said: The Messenger of Allah ﷺ went out on one of his military expeditions. When he returned, a Black young woman came and said: “O Messenger of Allah ﷺ, I had vowed that if Allah returned you safely, I would beat the drum in front of you and sing.” The Messenger of Allah ﷺ said to her: “If you made a vow, then beat it; otherwise, do not.” So she began beating it. Abu Bakr entered while she was beating it, then ʿAli entered while she was beating it, then ʿUthman entered while she was beating it. Then ʿUmar entered, so she threw the drum under herself and sat on it. The Messenger of Allah ﷺ said: “Indeed, Satan fears you, O ʿUmar. I was sitting while she was beating it; Abu Bakr entered while she was beating it; then ʿAli entered while she was beating it; then ʿUthman entered while she was beating it. But when you entered, O ʿUmar, she threw the drum down.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":3690,"lafz":true},{"key":"ibnhibban","label":"صححه ابن حبان","number":4386},{"key":"ahmad","label":"مسند الإمام أحمد","number":22989,"n":22989}],"full":1,"dr":1},{"num":7114,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ،: أَنَّ امْرَأَةً، أَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ إِنِّي نَذَرْتُ أَنْ أَضْرِبَ عَلَى رَأْسِكَ بِالدُّفِّ. قَالَ: أَوْفِي بِنَذْرِكِ. قَالَتْ: إِنِّي نَذَرْتُ أَنْ أَذْبَحَ بِمَكَانِ كَذَا وَكَذَا، مَكَانٌ كَانَ يَذْبَحُ فِيهِ أَهْلُ الْجَاهِلِيَّةِ. قَالَ: لِصَنَمٍ. قَالَتْ: لاَ. قَالَ: لِوَثَنٍ. قَالَتْ: لاَ. قَالَ: أَوْفِي بِنَذْرِكِ."],"takhrij":"حسن: رواه أبو داود (3312) وعنه البيهقي (10/77) عن مسدد، حدثنا الحارث بن عبيد أو قدامة، عن عبيد الله بن الأخنس، عن عمرو بن شعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب الترغيب في الوفاء بالنذر","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3312) and al-Bayhaqi (10/77).","chapter_en":"Encouragement to Fulfill Vows","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb narrated from his father, from his grandfather, that a woman came to the Prophet ﷺ and said: “O Messenger of Allah ﷺ, I vowed to beat the drum over your head.” He said: “Fulfill your vow.” She said: “I vowed to slaughter at such-and-such place” — a place where the people of the pre-Islamic period used to slaughter. He said: “For an idol?” She said: “No.” He said: “For a pagan object of worship?” She said: “No.” He said: “Fulfill your vow.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3312,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":10}],"full":1,"dr":1},{"num":7115,"demo":false,"sanad":"","matn":["عَبَّاسٍ، أَنَّ رَجُلاً، جَاءَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي نَذَرْتُ أَنْ أَنْحَرَ بِبُوَانَةَ فَقَالَ فِي نَفْسِكَ شَىْءٌ مِنْ أَمْرِ الْجَاهِلِيَّةِ. قَالَ لاَ. قَالَ أَوْفِ بِنَذْرِكَ."],"takhrij":"حسن: رواه ابن ماجة (2130) عن محمد بن يحيى وعبد الله بن إسحاق الجوهري، قالا: حدثنا عبد الله بن رجاء قال: أنبانا المسعودي، عن حبيب بن أبي ثابت، عن سعيد بن جبير، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب الترغيب في الوفاء بالنذر","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2130).","chapter_en":"Encouragement to Fulfill Vows","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas narrated that a man came to the Prophet ﷺ and said: “O Messenger of Allah ﷺ, I vowed to slaughter at Buwanah.” He said: “Is there anything in your mind connected to the practices of the pre-Islamic period?” He said: “No.” He said: “Fulfill your vow.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2130,"lafz":true}],"full":1,"dr":1},{"num":7116,"demo":false,"sanad":"","matn":["عن ثابت بن الضَّحَّاكِ قَالَ: نَذَرَ رَجُلٌ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَنْحَرَ إِبِلاً بِبُوَانَةَ، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنِّي نَذَرْتُ أَنْ أَنْحَرَ إِبِلاً بِبُوَانَةَ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَلْ كَانَ فِيهَا وَثَنٌ مِنْ أَوْثَانِ الْجَاهِلِيَّةِ يُعْبَدُ. قَالُوا: لاَ. قَالَ: هَلْ كَانَ فِيهَا عِيدٌ مِنْ أَعْيَادِهِمْ. قَالُوا: لاَ. قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَوْفِ بِنَذْرِكَ، فَإِنَّهُ لاَ وَفَاءَ لِنَذْرٍ فِي مَعْصِيَةِ اللَّهِ وَلاَ فِيمَا لاَ يَمْلِكُ ابْنُ آدَمَ."],"takhrij":"حسن: رواه أبو داود (3313) عن داود بن رُشيد، حدثنا شعيب بن إسحاق، عن الأوزاعي، عن يحيى بن أبي كثير، حدثني أبو قلابة، حدثني ثابت بن الضحاك، فذكره.","grade":"حسن","chapter_ar":"باب الترغيب في الوفاء بالنذر","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3313).","chapter_en":"Encouragement to Fulfill Vows","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Thabit ibn al-Dahhak said: A man vowed during the time of the Prophet ﷺ to slaughter camels at Buwanah. He came to the Prophet ﷺ and said: “I vowed to slaughter camels at Buwanah.” The Prophet ﷺ said: “Was there any idol from the idols of the pre-Islamic period worshipped there?” They said: “No.” He said: “Was there any festival of theirs held there?” They said: “No.” The Prophet ﷺ said: “Fulfill your vow, for there is no fulfillment of a vow in disobedience to Allah, nor in something the son of Adam does not own.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3313,"lafz":true}],"full":1,"dr":1},{"num":7117,"demo":false,"sanad":"","matn":["عَنْ مَيْمُونَةَ بِنْتِ كَرْدَمٍ الْيَسَارِيَّةِ، أَنَّ أَبَاهَا، لَقِيَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهِيَ رَدِيفَةٌ لَهُ فَقَالَ إِنِّي نَذَرْتُ أَنْ أَنْحَرَ بِبُوَانَةَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَلْ بِهَا وَثَنٌ. قَالَ لاَ. قَالَ أَوْفِ بِنَذْرِكَ."],"takhrij":"حسن: رواه ابن ماجة (2131) عن أبي بكر بن أبي شيبة قال: حدثنا مروان بن معاوية، عن عبد الله بن عبد الرحمن الطائفي، عن ميمونة بنت كردم فذكرته. ورواه من وجه آخر فأدخل بين عبد الله بن عبد الرحمن وبين ميمونة بنت كردم \"يزيد بن مقسم\" وإسناده حسن من أجل عبد الله بن عبدالرحمن الطائفي أبو يعلى الثقفي من رجال مسلم إلا أنه مختلف فيه غير أنه يقبل في المتابعات والشواهد وهذا منها.","grade":"حسن","chapter_ar":"باب الترغيب في الوفاء بالنذر","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2131).","chapter_en":"Encouragement to Fulfill Vows","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Maymunah bint Kardam al-Yasariyyah narrated that her father met the Prophet ﷺ while she was riding behind him. He said: “I vowed to slaughter at Buwanah.” The Messenger of Allah ﷺ said: “Is there an idol there?” He said: “No.” He said: “Fulfill your vow.”"]},"buhuth":{"en":["His statement “Buwanah” is pronounced with a dammah on the letter ba’, and after the alif comes the letter nun. It is a place between al-Sham and Diyar Bakr."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2131,"lafz":true}],"full":1,"dr":1},{"num":7118,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ عُمَرَ، قَالَ يَا رَسُولَ اللَّهِ إِنِّي نَذَرْتُ فِي الْجَاهِلِيَّةِ أَنْ أَعْتَكِفَ لَيْلَةً فِي الْمَسْجِدِ الْحَرَامِ. قَالَ فَأَوْفِ بِنَذْرِكَ."],"takhrij":"متفق عليه: رواه البخاري في الاعتكاف (2032) ومسلم في الأيمان والنذور (27:1656) كلاهما من طريق يحيى بن سعيد القطان، عن عبيد الله أخبرني نافع، عن ابن عمر، فذكره.","grade":"متفق عليه","chapter_ar":"باب الوفاء بالنذر الذي كان في حال الكفر إذا لم يكن فيه معصية","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2032) and Muslim (1656:27).","chapter_en":"Fulfilling a Vow Made During Disbelief If It Does Not Involve Sin","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿUmar narrated that ʿUmar said: “O Messenger of Allah ﷺ, during the pre-Islamic period I vowed to observe seclusion for one night in the Sacred Mosque.” He said: “Fulfill your vow.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2032,"lafz":true},{"key":"muslim","label":"مسلم","number":1656},{"key":"muslim","label":"مسلم في الايمان والنذور","number":27}],"full":1},{"num":7119,"demo":false,"sanad":"","matn":["عن عُمَرَ بن الْخَطَّابِ سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ بِالْجِعْرَانَةِ بَعْدَ أَنْ رَجَعَ مِنَ الطَّائِفِ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي نَذَرْتُ فِي الْجَاهِلِيَّةِ أَنْ أَعْتَكِفَ يَوْمًا فِي الْمَسْجِدِ الْحَرَامِ فَكَيْفَ تَرَى قَالَ اذْهَبْ فَاعْتَكِفْ يَوْمًا. قَالَ وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ أَعْطَاهُ جَارِيَةً مِنَ الْخُمْسِ فَلَمَّا أَعْتَقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَبَايَا النَّاسِ سَمِعَ عُمَرُ بْنُ الْخَطَّابِ أَصْوَاتَهُمْ يَقُولُونَ أَعْتَقَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ مَا هَذَا فَقَالُوا أَعْتَقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَبَايَا النَّاسِ. فَقَالَ عُمَرُ يَا عَبْدَ اللَّهِ اذْهَبْ إِلَى تِلْكَ الْجَارِيَةِ فَخَلِّ سَبِيلَهَا."],"takhrij":"متفق عليه: رواه البخاري في فرض الخمس (3144)، ومسلم في الأيمان والنذور (28:1656) كلاهما من حديث أيوب، حدثه أن نافعاً حدثه أن عمر بن الخطاب سأل فذكر الحديث واللفظ لمسلم، ولفظ البخاري نحوه إلا أن فيه: \"وأصاب عمر جاريتين من سبي حنين\".","grade":"متفق عليه","chapter_ar":"باب الوفاء بالنذر الذي كان في حال الكفر إذا لم يكن فيه معصية","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3144) and Muslim (1656:28). The wording is from Muslim.","chapter_en":"Fulfilling a Vow Made During Disbelief If It Does Not Involve Sin","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["ʿUmar ibn al-Khattab asked the Messenger of Allah ﷺ while he was at al-Ji’ranah after returning from Ta’if. He said: “O Messenger of Allah ﷺ, during the pre-Islamic period I vowed to observe seclusion for one day in the Sacred Mosque. What do you think?” He said: “Go and observe seclusion for one day.” The Messenger of Allah ﷺ had given him a slave girl from the fifth share of the spoils. When the Messenger of Allah ﷺ freed the captives, ʿUmar ibn al-Khattab heard their voices saying: “The Messenger of Allah ﷺ has freed us.” He said: “What is this?” They said: “The Messenger of Allah ﷺ has freed the captives.” So ʿUmar said: “O ʿAbdullah, go to that slave girl and let her go.”"]},"buhuth":{"en":["There is no contradiction between the two previous hadiths, for in the first there is “seclusion for one night,” and in the second “seclusion for one day.” Ibn Hibban said in his Sahih (10/226–227): “It appears that a day was intended along with its night, and a night was intended along with its day, so there is no contradiction between the two reports.” Meaning: one day and one night."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3144,"lafz":true},{"key":"muslim","label":"مسلم","number":1656,"n":4294},{"key":"muslim","label":"مسلم في الايمان والنذور","number":28}],"full":1,"dr":1},{"num":7120,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَدْرَكَ رَجُلَيْنِ وَهُمَا مُقْتَرِنَانِ، يَمْشِيَانِ إِلَى الْبَيْتِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا بَالُ الْقِرَانِ؟ قَالَا: يَا رَسُولَ اللَّهِ، نَذَرْنَا أَنْ نَمْشِيَ إِلَى الْبَيْتِ مُقْتَرِنَيْنِ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَيْسَ هَذَا نَذْرًا فَقَطَعَ قِرَانَهُمَا.","قال سُريج في حديثه: إنما النذر ما ابتغي به وجه الله عز وجل."],"takhrij":"حسن: رواه أحمد (6714)، عن الحسين بن محمد وسريج قالا: حدثنا ابن أبي الزناد، عن عبد الرحمن بن الحارث، عن عمرو بن شعيب، عن أبيه، عن جده فذكره. وإسناده حسن من أجل عمرو فإنه حسن الحديث.","grade":"حسن","chapter_ar":"باب النذر فيما يبتغى به وجه الله عز وجل","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6714).","chapter_en":"A Vow Must Be for That by Which the Face of Allah the Mighty and Majestic Is Sought","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb narrated from his father, from his grandfather, that the Messenger of Allah ﷺ came upon two men who were tied together and walking to the House. The Messenger of Allah ﷺ said: “What is the matter with this tying?” They said: “O Messenger of Allah ﷺ, we vowed to walk to the House tied together.” The Messenger of Allah ﷺ said: “This is not a vow.” So he cut their bond. Surayj said in his narration: “A vow is only that by which the Face of Allah the Mighty and Majestic is sought.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":6714,"n":6714,"lafz":true}],"full":1,"dr":1},{"num":7121,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ النَّذْرِ وَقَالَ إِنَّهُ لاَ يَرُدُّ شَيْئًا، وَلَكِنَّهُ يُسْتَخْرَجُ بِهِ مِنَ الْبَخِيلِ.","وفي لفظ: من الشحيح."],"takhrij":"متفق عليه: رواه البخاري في الأيمان والنذور (6693)، ومسلم في النذر (2:1639) كلاهما من طريق منصور، أخبرنا عبد الله بن مرة، عن عبد الله بن عمر، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في كراهية النذر","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6693) and Muslim (1639:2).","chapter_en":"What Has Been Reported Concerning the Dislike of Vows","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar narrated: The Prophet ﷺ forbade vows and said: “They do not repel anything, but through them something is extracted from the miser.” And in another wording: “From the stingy person.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6693,"lafz":true},{"key":"muslim","label":"مسلم","number":1639},{"key":"muslim","label":"مسلم في النذر","number":2}],"full":1},{"num":7122,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ الْحَارِثِ قَالَ: كُنْتُ عِنْدَ عَبْدِ اللَّهِ بن عُمَرَ بن الْخَطَّابِ إِذْ جَاءَهُ رَجُلٌ فَقَالَ: يَا أَبَا عَبْدِ الرَّحْمَنِ، إن ابْنًا لِي كَانَ بِأَرْضِ فَارِسَ، فَوَقَعَ بِهَا الطَّاعُونُ، فَنَذَرْتُ إنِ اللَّهَ نجّى لِي ابْنِي أَنْ يَمْشِيَ إِلَى الْكَعْبَةِ، وَإِنَّ ابْنِي قَدِمَ فَمَاتَ. فَقَالَ عَبْدُ اللَّهِ: أَوْفِ بِنَذْرِكَ. فَقَالَ لَهُ الرَّجُلُ: إِنَّمَا نَذَرْتُ أَنْ يَمْشِيَ ابْنِي. وَإِنَّ ابْنِي قَدْ مَاتَ. فَغَضِبَ عَبْدُ اللَّهِ وَقَالَ: أَوْ لَمْ تُنْهَوْا عَنِ النَّذْرِ؟ سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ النَّذْرَ لَا يُقَدِّمُ شَيْئًا وَلَا يُؤَخِّرُهُ، وَلَكِنَّ اللَّهَ يَنْزِعُ بِهِ مِنَ الْبَخِيلِ فَلَمَّا رَأَيْتُ ذَلِكَ قُلْتُ لِلرَّجُلِ: انْطَلِقْ إِلَى سَعِيدِ بْنِ الْمُسَيَّبِ فَسَلْهُ. فَانْطَلَقَ إِلَيْهِ، فَسَأَلَهُ، ثُمَّ رَجَعَ، فَقُلْتُ: مَا ذَا قَالَ لَكَ؟ قَالَ: امْشِ عَنِ ابْنِكَ. قَالَ: أَوْ يُجْزِئُ عَنِّي ذَلِكَ؟ فَقَالَ سَعِيدُ بْنُ الْمُسَيَّبِ: أَرَأَيْتَ لَوْ كَانَ عَلَى ابْنِكَ دَيْنٌ فَقَضَيْتَهُ، أَكَانَ يُجْزِئُ عَنْهُ؟ قُلْتُ: بَلَى، قَالَ: فَامْشِ عَنِ ابْنِكَ."],"takhrij":"حسن: رواه ابن حبان (4378)، عن الحسين بن محمد بن أبي معشر، قال: حدثنا محمد بن وهب بن أبي كريمة، قال: حدثنا محمد بن مسلمة، عن أبي عبد الرحيم، عن زيد بن أبي أنيسة، عن سعيد بن الحارث قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في كراهية النذر","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Hibban (4378) and al-Hakim (4/304).","chapter_en":"What Has Been Reported Concerning the Dislike of Vows","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Saʿid ibn al-Harith said: I was with ʿAbdullah ibn ʿUmar ibn al-Khattab when a man came to him and said: “O Abu ʿAbd al-Rahman, I had a son in the land of Persia, and the plague occurred there. I vowed that if Allah saved my son for me, he would walk to the Kaʿbah. But my son returned and then died.” ʿAbdullah said: “Fulfill your vow.” The man said to him: “I only vowed that my son would walk, but my son has died.” ʿAbdullah became angry and said: “Were you not forbidden from vows? I heard the Prophet ﷺ say: ‘A vow does not bring anything forward nor delay it, but through it Allah extracts something from the miser.’” When I saw that, I said to the man: “Go to Saʿid ibn al-Musayyib and ask him.” So he went to him and asked him, then returned. I said: “What did he say to you?” He said: “Walk on behalf of your son.” He said: “Will that be sufficient for me?” Saʿid ibn al-Musayyib said: “If your son had owed a debt and you paid it, would that be sufficient on his behalf?” I said: “Yes.” He said: “Then walk on behalf of your son.”"]}},"tuhfa":{},"refs":[{"key":"hakim","label":"الحاكم","number":4},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4624,"n":4620,"lafz":true},{"key":"ibnhibban","label":"ابن حبان","number":4378}],"full":1,"dr":1},{"num":7123,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ يَأْتِي ابْنَ آدَمَ النَّذْرُ بِشَىْءٍ لَمْ يَكُنْ قُدِّرَ لَهُ، وَلَكِنْ يُلْقِيهِ النَّذْرُ إِلَى الْقَدَرِ قَدْ قُدِّرَ لَهُ، فَيَسْتَخْرِجُ اللَّهُ بِهِ مِنَ الْبَخِيلِ، فَيُؤْتِي عَلَيْهِ مَا لَمْ يَكُنْ يُؤْتِي عَلَيْهِ مِنْ قَبْلُ.","وفي رواية: إن النذر لا يقرب من ابن آدم شيئاً لم يكن الله قدّره له، ولكن النذر يوافق القدر، فيُخرج بذلك من البخيل ما لم يكن البخيل يريد أن يخرج."],"takhrij":"متفق عليه: رواه البخاري في الأيمان والنذور (6694)، ومسلم في النذر (7:1640) كلاهما من حديث عبد الرحمن الأعرج، عن أبي هريرة،","grade":"متفق عليه","chapter_ar":"باب ما جاء في كراهية النذر","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6694) and Muslim (1640:7). The wording is from al-Bukhari.","chapter_en":"What Has Been Reported Concerning the Dislike of Vows","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ said: “A vow does not bring to the son of Adam anything that had not already been decreed for him. Rather, the vow brings him to what had already been decreed for him, and through it Allah extracts from the miser, so he gives because of it what he would not have given before.” In another narration: “A vow does not bring the son of Adam closer to anything that Allah had not already decreed for him. Rather, the vow coincides with the decree, and through it something is extracted from the miser that the miser had not wanted to give.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6694,"lafz":true},{"key":"muslim","label":"مسلم","number":1640},{"key":"muslim","label":"مسلم في النذر","number":7}],"full":1,"dr":1},{"num":7124,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يَأْتِي ابْنَ آدَمَ النَّذْرُ بِشَيْءٍ لَمْ أَكُنْ قَدَّرْتُهُ لَهُ، وَلَكِنَّهُ يَلْقِيهِ النَّذْرُ بِمَا قَدْ قَدَّرْتُهُ لَهُ، يُسْتَخْرَجُ بِهِ مِنَ الْبَخِيلِ، يُؤْتِينِي عَلَيْهِ مَا لَمْ يَكُنْ آتَانِي عَلَيْهِ مِنْ قَبْلُ."],"takhrij":"صحيح: رواه الإمام أحمد (8152)، وابن الجارود (932) كلاهما من حديث عبدالرزاق بن همام، حدثنا معمر، عن همام بن منبه قال: هذا ما حدثنا به أبو هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في كراهية النذر","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (8152) and Ibn al-Jarud (932).","chapter_en":"What Has Been Reported Concerning the Dislike of Vows","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Allah said: ‘A vow does not bring to the son of Adam anything that I had not already decreed for him. Rather, the vow brings him to what I had already decreed for him. Through it, something is extracted from the miser, and he gives to Me because of it what he would not have given to Me before.’”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":8152,"lafz":true},{"key":"sh13071","label":"ابن الجارود","number":932}],"full":1,"dr":1},{"num":7125,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ تَنْذُرُوا فَإِنَّ النَّذْرَ لاَ يُغْنِي مِنَ الْقَدَرِ شَيْئًا وَإِنَّمَا يُسْتَخْرَجُ بِهِ مِنَ الْبَخِيلِ."],"takhrij":"صحيح: رواه مسلم في النذر (5:1640)، عن قتيبة بن سعيد، حدثنا عبد العزيز (يعني الدراوردي) عن العلاء بن عبد الرحمن، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في كراهية النذر","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1640:5).","chapter_en":"What Has Been Reported Concerning the Dislike of Vows","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “Do not make vows, for a vow does not avail anything against decree. It only extracts something from the miser.”"]},"buhuth":{"en":["His statement, “Do not make vows”: Some scholars held that this prohibition indicates unlawfulness, because the thing a person vows for may be decreed for him, and then he may think it happened because of the vow. This would lead to the belief that a vow changes divine decree. But if he believes that a vow does not change divine decree, then making a vow is disliked in his case.","Its meaning is: Do not make vows thinking that through a vow you will obtain something Allah has not decreed for you, or repel from yourselves something that has already been decreed against you. But if you do make a vow, then fulfill it, because what you vowed becomes binding upon you. For more, see Sharh al-Sunnah (10/23)."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":5,"lafz":true}],"full":1,"dr":1},{"num":7126,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ، أَنَّ سَعْدَ بْنَ عُبَادَةَ الأَنْصَارِيَّ اسْتَفْتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي نَذْرٍ كَانَ عَلَى أُمِّهِ، فَتُوُفِّيَتْ قَبْلَ أَنْ تَقْضِيَهُ، فَأَفْتَاهُ أَنْ يَقْضِيَهُ عَنْهَا، فَكَانَتْ سُنَّةً بَعْدُ."],"takhrij":"متفق عليه: رواه البخاري في الأيمان والنذرو (6698)، عن أبي اليمان، أخبرنا شعيب، عن ابن شهاب الزهري، عن عبيد الله بن عبد الله، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب قضاء النذر عن الميت","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6698) and Muslim (1638:1).","chapter_en":"Fulfilling a Vow on Behalf of the Deceased","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿAbbas narrated that Saʿd ibn ʿUbadah al-Ansari sought a ruling from the Prophet ﷺ about a vow that was upon his mother, but she died before fulfilling it. He ﷺ gave him the ruling that he should fulfill it on her behalf, and this became an established practice afterward."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6698,"lafz":true},{"key":"muslim","label":"مسلم","number":1}],"full":1,"dr":1},{"num":7127,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ أَتَى رَجُلٌ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لَهُ إِنَّ أُخْتِي نَذَرَتْ أَنْ تَحُجَّ وَإِنَّهَا مَاتَتْ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَوْ كَانَ عَلَيْهَا دَيْنٌ أَكُنْتَ قَاضِيَهُ. قَالَ نَعَمْ. قَالَ فَاقْضِ اللَّهَ، فَهْوَ أَحَقُّ بِالْقَضَاءِ."],"takhrij":"صحيح: رواه البخاري في الأيمان والنذر (6699)، عن آدم، حدثنا شعبة، عن أبي بشر قال: سمعت سعيد بن جبير، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب قضاء نذر الحج عن الميت","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6699).","chapter_en":"Fulfilling a Vow of Pilgrimage on Behalf of the Deceased","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Ibn ʿAbbas said: A man came to the Prophet ﷺ and said to him: “My sister vowed to perform pilgrimage, but she died.” The Prophet ﷺ said: “If she had a debt, would you pay it off?” He said: “Yes.” He said: “Then pay the debt owed to Allah, for it is more deserving of being fulfilled.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6699,"lafz":true}],"full":1},{"num":7128,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ امْرَأَةً، جَاءَتْ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ إِنَّ أُمِّي نَذَرَتْ أَنْ تَحُجَّ فَمَاتَتْ قَبْلَ أَنْ تَحُجَّ أَفَأَحُجَّ عَنْهَا قَالَ نَعَمْ حُجِّي عَنْهَا، أَرَأَيْتِ لَوْ كَانَ عَلَى أُمِّكِ دَيْنٌ أَكُنْتِ قَاضِيَتَهُ. قَالَتْ نَعَمْ. فَقَالَ فَاقْضُوا الَّذِي لَهُ، فَإِنَّ اللَّهَ أَحَقُّ بِالْوَفَاءِ."],"takhrij":"صحيح: رواه البخاري في الاعتصام (7315)، عن مسدّد، حدثنا أبو عوانة، عن أبي بشر، عن سعيد بن جبير، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب قضاء نذر الحج عن الميت","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7315).","chapter_en":"Fulfilling a Vow of Pilgrimage on Behalf of the Deceased","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Ibn ʿAbbas narrated that a woman came to the Prophet ﷺ and said: “My mother vowed to perform pilgrimage, but she died before performing pilgrimage. Should I perform pilgrimage on her behalf?” He said: “Yes, perform pilgrimage on her behalf. Tell me, if your mother had a debt, would you pay it off?” She said: “Yes.” He said: “Then fulfill what is owed to Allah, for Allah is more deserving of fulfillment.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7315,"lafz":true}],"full":1},{"num":7129,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، رَضِيَ اللَّهُ عَنْهُمَا قَالَ جَاءَتِ امْرَأَةٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ أُمِّي مَاتَتْ وَعَلَيْهَا صَوْمُ نَذْرٍ أَفَأَصُومُ عَنْهَا قَالَ أَرَأَيْتِ لَوْ كَانَ عَلَى أُمِّكِ دَيْنٌ فَقَضَيْتِيهِ أَكَانَ يُؤَدِّي ذَلِكِ عَنْهَا. قَالَتْ نَعَمْ. قَالَ فَصُومِي عَنْ أُمِّكِ."],"takhrij":"صحيح: رواه مسلم في الصيام (156:1148)، من طريق زكريا بن عدي، أخبرنا عبدالله بن عمرو، عن زيد بن أنيسة، حدثنا الحكم بن عتيبة، عن سعيد بن جبير، عن ابن عباس، فذكره. وعلقه البخاري في الصوم عقب حديث (1953) عن عبدالله، به، مختصراً.","grade":"صحيح","chapter_ar":"باب قضاء نذر الصيام عن الميت","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1148:156).","chapter_en":"Fulfilling a Vow of Fasting on Behalf of the Deceased","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbas said: A woman came to the Messenger of Allah ﷺ and said: “O Messenger of Allah ﷺ, my mother died while she owed a vowed fast. Should I fast on her behalf?” He said: “Tell me, if your mother had a debt and you paid it off, would that discharge it from her?” She said: “Yes.” He said: “Then fast on behalf of your mother.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":156,"lafz":true},{"key":"bukhari","label":"علقه البخاري في الصوم عقب حديث","number":1953}],"full":1,"dr":1},{"num":7130,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ،: أَنَّ امْرَأَةً، رَكِبَتِ الْبَحْرَ فَنَذَرَتْ إِنْ نَجَّاهَا اللَّهُ أَنْ تَصُومَ شَهْرًا، فَنَجَّاهَا اللَّهُ فَلَمْ تَصُمْ حَتَّى مَاتَتْ، فَجَاءَتِ ابْنَتُهَا أَوْ أُخْتُهَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَمَرَهَا أَنْ تَصُومَ عَنْهَا."],"takhrij":"صحيح: رواه أبو داود (3308)، والنسائي (3816) وصحّحه ابن خزيمة (2054) كلهم من حديث سعيد بن جبير، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب قضاء نذر الصيام عن الميت","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3308), al-Nasa’i (3816), and authenticated by Ibn Khuzaymah (2054).","chapter_en":"Fulfilling a Vow of Fasting on Behalf of the Deceased","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbas narrated that a woman rode upon the sea and vowed that if Allah saved her, she would fast for a month. Allah saved her, but she did not fast until she died. Then her daughter — or her sister — came to the Messenger of Allah ﷺ, and he ordered her to fast on her behalf."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3308,"lafz":true},{"key":"nasai","label":"النسائي","number":3816},{"key":"ibnkhuzaymah","label":"صححه ابن خزيمة","number":2054}],"full":1,"dr":1},{"num":7131,"demo":false,"sanad":"","matn":["عَنْ زِيَادِ بْنِ جُبَيْرٍ، قَالَ كُنْتُ مَعَ ابْنِ عُمَرَ فَسَأَلَهُ رَجُلٌ فَقَالَ نَذَرْتُ أَنْ أَصُومَ كُلَّ يَوْمِ ثَلاَثَاءَ أَوْ أَرْبِعَاءَ مَا عِشْتُ، فَوَافَقْتُ هَذَا الْيَوْمَ يَوْمَ النَّحْرِ. فَقَالَ أَمَرَ اللَّهُ بِوَفَاءِ النَّذْرِ، وَنُهِينَا أَنْ نَصُومَ يَوْمَ النَّحْرِ. فَأَعَادَ عَلَيْهِ فَقَالَ مِثْلَهُ، لاَ يَزِيدُ عَلَيْهِ.","وفي رواية: ونهى رسول الله صلى الله عليه وسلم عن صوم هذا اليوم.","وزاد في رواية: فقال: ﴿لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ﴾ [سورة الأحزاب:21] لم يكن يصوم يوم الأضحى والفطر، ولا يرى صيامهما."],"takhrij":"متفق عليه: رواه البخاري في الأيمان والنذور (6706)، من طريق يونس، ومسلم في الصيام (1139) من طريق ابن عون – كلاهما عن زياد بن جبير، فذكره. واللفظ للبخاري، والرواية الأخرى لمسلم.","grade":"متفق عليه","chapter_ar":"باب من نذر أن يصوم صوماً فوافق يوماً نُهِيَ عن صيامه","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6705, 6706) and Muslim (1139). The wording is from al-Bukhari, and the other narration is from Muslim.","chapter_en":"One Who Vowed to Fast and It Coincided with a Day on Which Fasting Is Prohibited","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Ziyad ibn Jubayr said: I was with Ibn ʿUmar when a man asked him, saying: “I vowed to fast every Tuesday or Wednesday for as long as I live, and this day has coincided with the Day of Sacrifice.” He said: “Allah has commanded fulfillment of vows, and we have been forbidden to fast on the Day of Sacrifice.” The man repeated the question, and he gave the same answer without adding anything. In another narration: “The Messenger of Allah ﷺ forbade fasting on this day.”","Another narration adds that he said: “There has certainly been for you in the Messenger of Allah ﷺ an excellent example.” [Surah al-Ahzab: 21] He did not fast on the Day of Sacrifice or the Day of Breaking Fast, and he did not consider fasting them permissible."]},"buhuth":{"en":["Ibn ʿUmar refrained from giving a decisive answer because the evidences appeared to conflict to him. The stronger view is that he should not fast, because a prohibition takes precedence over permissibility. This is what is understood from Allah’s statement: “There has certainly been for you in the Messenger of Allah ﷺ an excellent example,” meaning that he ﷺ did not fast on the Day of Breaking Fast or the Day of Sacrifice."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6705,"n":6706},{"key":"muslim","label":"مسلم","number":1139},{"key":"bukhari","label":"البخاري في الايمان والنذور","number":6706,"lafz":true}],"full":1,"dr":1},{"num":7132,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ نَذَرَ أَنْ يُطِيعَ اللَّهَ فَلْيُطِعْهُ، وَمَنْ نَذَرَ أَنْ يَعْصِيَهُ فَلاَ يَعْصِهِ."],"takhrij":"صحيح: رواه مالك في النذور والأيمان (8) عن طلحة بن عبد الملك الأيلي، عن القاسم بن محمد بن الصديق، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب لا وفاء لنذر في المعصية","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (8) and al-Bukhari (6700).","chapter_en":"There Is No Fulfillment of a Vow in Disobedience","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["The Mother of the Believers ʿAishah narrated that the Messenger of Allah ﷺ said: “Whoever vows to obey Allah should obey Him, and whoever vows to disobey Allah must not disobey Him.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":8,"lafz":true},{"key":"bukhari","label":"البخاري","number":6700}],"full":1,"dr":1,"rep":[13657]},{"num":7133,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَىَ شَيْخًا يُهَادَى بَيْنَ ابْنَيْهِ فَقَالَ مَا بَالُ هَذَا. قَالُوا نَذَرَ أَنْ يَمْشِيَ. قَالَ إِنَّ اللَّهَ عَنْ تَعْذِيبِ هَذَا نَفْسَهُ لَغَنِيٌّ. وَأَمَرَهُ أَنْ يَرْكَبَ."],"takhrij":"متفق عليه: رواه البخاري في الأيمان والنذور (6701)، ومسلم في النذر (1642) كلاهما من طريق حميد، حدثني ثابت، عن أنس، فذكره.","grade":"متفق عليه","chapter_ar":"باب لا وفاء لنذر في المعصية","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6701) and Muslim (1642).","chapter_en":"There Is No Fulfillment of a Vow in Disobedience","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["Anas narrated that the Prophet ﷺ saw an old man being supported between his two sons. He said: “What is the matter with this man?” They said: “He vowed to walk.” He said: “Allah has no need of this man torturing himself.” And he ordered him to ride."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6701,"lafz":true},{"key":"muslim","label":"مسلم","number":1642}],"full":1},{"num":7134,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ بَيْنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ إِذَا هُوَ بِرَجُلٍ قَائِمٍ فَسَأَلَ عَنْهُ فَقَالُوا أَبُو إِسْرَائِيلَ نَذَرَ أَنْ يَقُومَ وَلاَ يَقْعُدَ وَلاَ يَسْتَظِلَّ وَلاَ يَتَكَلَّمَ وَيَصُومَ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُرْهُ فَلْيَتَكَلَّمْ وَلْيَسْتَظِلَّ وَلْيَقْعُدْ وَلْيُتِمَّ صَوْمَهُ."],"takhrij":"صحيح: رواه البخاري في الأيمان والنذور (6704)، عن موسى بن إسماعيل، حدثنا وهيب، حدثنا أيوب، عن عكرمة، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب لا وفاء لنذر في المعصية","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6704).","chapter_en":"There Is No Fulfillment of a Vow in Disobedience","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿAbbas said: While the Prophet ﷺ was delivering a sermon, he saw a man standing. He asked about him, and they said: “Abu Isra’il vowed to stand and not sit, not seek shade, not speak, and to fast.” The Prophet ﷺ said: “Tell him to speak, seek shade, sit down, and complete his fast.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6704,"lafz":true}],"full":1,"dr":1},{"num":7135,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ وَهْوَ يَطُوفُ بِالْكَعْبَةِ بِإِنْسَانٍ يَقُودُ إِنْسَانًا بِخِزَامَةٍ فِي أَنْفِهِ، فَقَطَعَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ، ثُمَّ أَمَرَهُ أَنْ يَقُودَهُ بِيَدِهِ."],"takhrij":"صحيح: رواه البخاري في الأيمان والنذور (6703) عن إبراهيم بن موسى، أخبرنا هشام أن ابن جريج أخبرهم قال: أخبرني سليمان الأحول أن طاوسا أخبره، عن ابن عباس قال: فذكره.","grade":"صحيح","chapter_ar":"باب لا وفاء لنذر في المعصية","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6703).","chapter_en":"There Is No Fulfillment of a Vow in Disobedience","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿAbbas narrated that the Prophet ﷺ, while circumambulating the Kaʿbah, passed by a person leading another person by a nose-rope in his nose. The Prophet ﷺ cut it with his own hand, then ordered him to lead him by his hand."]},"buhuth":{"en":["Al-khizamah, with a kasrah on the kha’, is what is placed in the nose of a camel, made of hair or something else, so it may be led by it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6703,"lafz":true}],"full":1,"dr":1},{"num":7136,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ أَنَّهُ قَالَ: نَذَرَتْ أُخْتِي أَنْ تَمْشِيَ إِلَى بَيْتِ اللَّهِ، وأمرتني أَنْ أَسْتَفْتِيَ لَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَاسْتَفْتَيْتُهُ، فَقَالَ: لِتَمْشِ وَلْتَرْكَبْ وَزَادَ فِي رِوَايَةِ: حَافِيَةً."],"takhrij":"متفق عليه: رواه البخاري في جزاء الصيد (1866)، ومسلم في النذر (12:1644) كلاهما من طريق ابن جريج، أخبرني سعيد بن أبي أيوب، أن يزيد بن أبي حبيب أخبره، أن أبا الخير حدّثه، عن عقبة بن عامر، فذكره.","grade":"متفق عليه","chapter_ar":"باب لا وفاء لنذر في المعصية","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1866) and Muslim (1644:12). The addition is from Muslim.","chapter_en":"There Is No Fulfillment of a Vow in Disobedience","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["ʿUqbah ibn ʿAmir said: My sister vowed to walk to the House of Allah, and she ordered me to seek a ruling from the Prophet ﷺ on her behalf. So I sought his ruling, and he said: “Let her walk and let her ride.” Another narration adds: “barefoot.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1866,"lafz":true},{"key":"muslim","label":"مسلم","number":1644},{"key":"muslim","label":"مسلم في النذر","number":12}],"full":1,"dr":1},{"num":7137,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَدْرَكَ شَيْخًا يَمْشِي بَيْنَ ابْنَيْهِ يَتَوَكَّأُ عَلَيْهِمَا فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا شَأْنُ هَذَا. قَالَ ابْنَاهُ يَا رَسُولَ اللَّهِ كَانَ عَلَيْهِ نَذْرٌ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ارْكَبْ أَيُّهَا الشَّيْخُ فَإِنَّ اللَّهَ غَنِيٌّ عَنْكَ وَعَنْ نَذْرِكَ."],"takhrij":"صحيح: رواه مسلم في النذر (1643) من طريق إسماعيل بن جعفر، عن عمرو بن أبي عمرو، عن عبد الرحمن الأعرج، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب لا وفاء لنذر في المعصية","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1643).","chapter_en":"There Is No Fulfillment of a Vow in Disobedience","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ came upon an old man walking between his two sons, leaning on them. The Prophet ﷺ said: “What is the matter with this man?” His two sons said: “O Messenger of Allah ﷺ, he had a vow.” The Prophet ﷺ said: “Ride, old man, for Allah has no need of you or your vow.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1643,"lafz":true}],"full":1},{"num":7138,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ،: أَنَّ رَجُلاً، قَامَ يَوْمَ الْفَتْحِ فَقَالَ: يَا رَسُولَ اللَّهِ إِنِّي نَذَرْتُ لِلَّهِ إِنْ فَتَحَ اللَّهُ عَلَيْكَ مَكَّةَ أَنْ أُصَلِّيَ فِي بَيْتِ الْمَقْدِسِ رَكْعَتَيْنِ. قَالَ: صَلِّ هَا هُنَا ثُمَّ أَعَادَ عَلَيْهِ فَقَالَ: صَلِّ هَا هُنَا ثُمَّ أَعَادَ عَلَيْهِ فَقَالَ: شَأْنَكَ إِذًا."],"takhrij":"صحيح: رواه أبو داود (3305)، وأحمد (14919) والحاكم (4/304) والبيهقي (10/82-83) وابن الجارود (945) كلهم من حديث حماد بن سلمة، عن حبيب المعلم، عن عطاء بن أبي رباح، عن جابر بن عبدالله فذكره.","grade":"صحيح","chapter_ar":"باب لا وفاء لنذر في المعصية","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3305), Ahmad (14919), al-Hakim (4/304), and al-Bayhaqi (10/82–83).","chapter_en":"There Is No Fulfillment of a Vow in Disobedience","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["Jabir ibn ʿAbdullah narrated that a man stood on the day of the Conquest and said: “O Messenger of Allah ﷺ, I vowed to Allah that if He granted you the conquest of Makkah, I would pray two units of prayer in Bayt al-Maqdis.” He said: “Pray here.” The man repeated it, and he said: “Pray here.” The man repeated it again, so he said: “Then it is up to you.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3305,"lafz":true},{"key":"hakim","label":"الحاكم","number":4},{"key":"kubrabayhaqi","label":"البيهقي","number":10},{"key":"ahmad","label":"مسند الإمام أحمد","number":14919,"n":14919},{"key":"sh13071","label":"ابن الجارود","number":945}],"full":1,"dr":1},{"num":7139,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عَبَّاسٍ أَنَّ رَجُلَيْنِ اخْتَصَمَا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الطَّالِبَ الْبَيِّنَةَ. فَلَمْ تَكُنْ لَهُ بَيِّنَةٌ. فَاسْتَحْلَفَ الْمَطْلُوبَ. فَحَلَفَ بِاللَّهِ الَّذِي لاَ إِلَهَ إِلاَّ هُوَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : بَلَى قَدْ فَعَلْتَ، وَلَكِنْ قَدْ غُفِرَ لَكَ بِإِخْلاَصِ قَوْلِ لاَ إِلَهَ إِلاَّ اللَّهُ.","قال أبو داود: يراد من هذا الحديث أنه لم يأمره بالكفارة."],"takhrij":"صحيح: رواه أبو داود (3275)، وأحمد (2280) والبيهقي (10/37) كلهم من حديث حماد بن سلمة، عن عطاء بن السائب، عن أبي يحيى، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب لا وفاء لنذر في المعصية","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3275), Ahmad (2280), and al-Bayhaqi (10/37).","chapter_en":"There Is No Fulfillment of a Vow in Disobedience","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas narrated that two men disputed before the Prophet ﷺ. The Prophet ﷺ asked the claimant for evidence, but he had no evidence. So he asked the defendant to swear an oath. The man swore by Allah, besides Whom there is no god. The Messenger of Allah ﷺ said: “Yes, you did do it, but you have been forgiven because of the sincerity of your statement: ‘There is no god except Allah.’” Abu Dawud said: What is intended from this hadith is that he did not order him to offer expiation."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3275,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":10},{"key":"ahmad","label":"مسند الإمام أحمد","number":2280,"n":2280}],"full":1,"dr":1},{"num":7140,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ كَفَّارَةُ النَّذْرِ كَفَّارَةُ الْيَمِينِ."],"takhrij":"صحيح: رواه مسلم في النذر (1645) من طريق ابن وهب، أخبرني عمرو بن الحارث، عن كعب بن علقمة، عن عبد الرحمن بن شماسة، عن أبي الخير، عن عقبة بن عامر، فذكره.","grade":"صحيح","chapter_ar":"باب من قال في النذر بالمعصية كفارة","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1645).","chapter_en":"Whoever Said That There Is Expiation for a Vow of Disobedience","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["ʿUqbah ibn ʿAmir narrated that the Messenger of Allah ﷺ said: “The expiation for a vow is the expiation for an oath.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1645,"lafz":true}],"full":1,"dr":1},{"num":7141,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ،: أَنَّ أُخْتَ، عُقْبَةَ بْنِ عَامِرٍ نَذَرَتْ أَنْ تَمْشِيَ، إِلَى الْبَيْتِ، فَأَمَرَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تَرْكَبَ وَتُهْدِيَ هَدْيًا."],"takhrij":"صحيح: رواه أبو داود (3296)، وأحمد (2134) والحاكم (4/302) والبيهقي (10/79) والدارمي (2335) والطحاوي في مشكله (2151) من طرق عن همام بن يحيى، عن قتادة، عن عكرمة، عن ابن عباس فذكره وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب من قال في النذر بالمعصية كفارة","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3296), Ahmad (2134), al-Hakim (4/302), al-Bayhaqi (10/79), and al-Darimi (2335).","chapter_en":"Whoever Said That There Is Expiation for a Vow of Disobedience","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿAbbas narrated that the sister of ʿUqbah ibn ʿAmir vowed to walk to the House. The Prophet ﷺ ordered her to ride and to offer a sacrificial animal."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3296,"lafz":true},{"key":"hakim","label":"الحاكم","number":4},{"key":"kubrabayhaqi","label":"البيهقي","number":10},{"key":"darimi","label":"الدارمي","number":2335},{"key":"ahmad","label":"مسند الإمام أحمد","number":2134,"n":2134},{"key":"sh22547","label":"الطحاوي في مشكله","number":2151}],"full":1,"dr":1},{"num":7142,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ، قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنَّ أُخْتِي نَذَرَتْ أَنْ تَمْشِيَ إِلَى الْبَيْتِ حَافِيَةً غَيْرَ مُخْتَمِرَةٍ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ اللَّهَ لاَ يَصْنَعُ بِشَقَاءِ أُخْتِكَ شَيْئًا فَلْتَرْكَبْ وَلْتَخْتَمِرْ وَلْتَصُمْ ثَلاَثَةَ أَيَّامٍ."],"takhrij":"حسن: رواه أبو داود (3294)، والترمذي (1544) والنسائي (3815) وابن ماجة (2134) والبيهقي (10/80) كلهم من حديث عبيد الله بن زحر، عن أبي سعيد الرُّعيني، عن عبد الله بن مالك اليحصُبي، عن عقبة بن عامر فذكره.","grade":"حسن","chapter_ar":"باب من قال في النذر بالمعصية كفارة","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3294), al-Tirmidhi (1544), who graded it Hasan, al-Nasa’i (3815), and Ibn Majah (2134).","chapter_en":"Whoever Said That There Is Expiation for a Vow of Disobedience","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["ʿUqbah ibn ʿAmir said: I said: “O Messenger of Allah ﷺ, my sister vowed to walk to the House barefoot and without covering her head.” The Prophet ﷺ said: “Allah does not benefit from your sister’s hardship in any way. Let her ride, let her cover her head, and let her fast three days.”"]},"buhuth":{"en":["His statement, “and let her fast three days,” is an additional wording, and it does not contradict the general wording in the hadith of ʿUqbah ibn ʿAmir. The matter is understood as follows: first, she should offer a camel as sacrifice; if she is unable, then she should fast three days. This reconciles the two narrations, except that the narrator summarized it, which may give the reader a mistaken impression."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3294,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1544},{"key":"nasai","label":"النسائي","number":3815},{"key":"ibnmajah","label":"ابن ماجه","number":2134}],"full":1,"dr":1},{"num":7143,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ النَّذْرَ نَذْرَانِ: فَمَا كَانَ لِلَّهِ فَكَفَّارَتُهُ الْوَفَاءُ بِهِ، وَمَا كَانَ لِلشَّيْطَانِ فَلَا وَفَاءَ لَهُ، وَعَلَيْهِ كَفَّارَةُ يَمِينٍ."],"takhrij":"حسن: رواه ابن الجارود في المنتقى (935) وعنه البيهقي (10/72) عن محمد بن يحيى، ثنا محمد بن موسى بن أيمن، ثنا خطاب، ثنا عبد الكريم، عن عطاء بن أبي رباح، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب من قال في النذر بالمعصية كفارة","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn al-Jarud in al-Muntaqa (935) and al-Bayhaqi (10/72).","chapter_en":"Whoever Said That There Is Expiation for a Vow of Disobedience","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿAbbas narrated that the Prophet ﷺ said: “Vows are of two kinds: whatever is for Allah, its expiation is fulfillment; and whatever is for Satan, there is no fulfillment of it, and upon it is the expiation of an oath.”"]}},"tuhfa":{},"refs":[{"key":"sh13071","label":"ابن الجارود في المنتقى","number":935,"n":972},{"key":"kubrabayhaqi","label":"البيهقي","number":10,"lafz":true},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":20078,"n":20236}],"full":1,"dr":1},{"num":7144,"demo":false,"sanad":"","matn":["عَنْ ثَابِتِ بْنِ الضَّحَّاكِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَيْسَ عَلَى رَجُلٍ نَذْرٌ فِيمَا لاَ يَمْلِكُ."],"takhrij":"متفق عليه: رواه مسلم في الأيمان (110-176) واللفظ له، والبخاري في الأدب (6047) كلاهما من حديث يحيى بن أبي كثير، عن أبي قلابة، أن ثابت بن الضحاك – وكان من أصحاب الشجرة – حدّث أن رسول الله صلى الله عليه وسلم قال: فذكر الحديث بطوله. إلا أن البخاري لم يذكر: \"ليس على رجل نذر فيما لا يملك\"","grade":"متفق عليه","chapter_ar":"باب لا نذر فيما لا يملك العبد","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (110), and the wording is his, and by al-Bukhari (6047).","chapter_en":"There Is No Vow Regarding What a Person Does Not Own","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["Thabit ibn al-Dahhak narrated that the Prophet ﷺ said: “A man has no vow regarding what he does not own.”"]},"buhuth":{"en":["His statement, “regarding what he does not own,” means that his vow is not binding in the first place."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":110,"lafz":true,"n":303},{"key":"bukhari","label":"البخاري","number":6047,"n":6105}],"full":1,"dr":1},{"num":7145,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ، قَالَ كَانَتْ ثَقِيفُ حُلَفَاءَ لِبَنِي عُقَيْلٍ فَأَسَرَتْ ثَقِيفُ رَجُلَيْنِ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَسَرَ أَصْحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلاً مِنْ بَنِي عُقَيْلٍ وَأَصَابُوا مَعَهُ الْعَضْبَاءَ فَأَتَى عَلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهْوَ فِي الْوَثَاقِ قَالَ يَا مُحَمَّدُ. فَأَتَاهُ فَقَالَ مَا شَأْنُكَ. فَقَالَ بِمَ أَخَذْتَنِي وَبِمَ أَخَذْتَ سَابِقَةَ الْحَاجِّ فَقَالَ إِعْظَامًا لِذَلِكَ أَخَذْتُكَ بِجَرِيرَةِ حُلَفَائِكَ ثَقِيفَ. ثُمَّ انْصَرَفَ عَنْهُ فَنَادَاهُ فَقَالَ يَا مُحَمَّدُ يَا مُحَمَّدُ. وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَحِيمًا رَقِيقًا فَرَجَعَ إِلَيْهِ فَقَالَ مَا شَأْنُكَ. قَالَ إِنِّي مُسْلِمٌ. قَالَ لَوْ قُلْتَهَا وَأَنْتَ تَمْلِكُ أَمْرَكَ أَفْلَحْتَ كُلَّ الْفَلاَحِ. ثُمَّ انْصَرَفَ فَنَادَاهُ فَقَالَ يَا مُحَمَّدُ يَا مُحَمَّدُ. فَأَتَاهُ فَقَالَ مَا شَأْنُكَ. قَالَ إِنِّي جَائِعٌ فَأَطْعِمْنِي وَظَمْآنُ فَأَسْقِنِي. قَالَ هَذِهِ حَاجَتُكَ. فَفُدِيَ بِالرَّجُلَيْنِ - قَالَ - وَأُسِرَتِ امْرَأَةٌ مِنَ الأَنْصَارِ وَأُصِيبَتِ الْعَضْبَاءُ فَكَانَتِ الْمَرْأَةُ فِي الْوَثَاقِ وَكَانَ الْقَوْمُ يُرِيحُونَ نَعَمَهُمْ بَيْنَ يَدَىْ بُيُوتِهِمْ فَانْفَلَتَتْ ذَاتَ لَيْلَةٍ مِنَ الْوَثَاقِ فَأَتَتِ الإِبِلَ فَجَعَلَتْ إِذَا دَنَتْ مِنَ الْبَعِيرِ رَغَا فَتَتْرُكُهُ حَتَّى تَنْتَهِيَ إِلَى الْعَضْبَاءِ فَلَمْ تَرْغُ قَالَ وَنَاقَةٌ مُنَوَّقَةٌ فَقَعَدَتْ فِي عَجُزِهَا ثُمَّ زَجَرَتْهَا فَانْطَلَقَتْ وَنَذِرُوا بِهَا فَطَلَبُوهَا فَأَعْجَزَتْهُمْ - قَالَ - وَنَذَرَتْ لِلَّهِ إِنْ نَجَّاهَا اللَّهُ عَلَيْهَا لَتَنْحَرَنَّهَا فَلَمَّا قَدِمَتِ الْمَدِينَةَ رَآهَا النَّاسُ. فَقَالُوا الْعَضْبَاءُ نَاقَةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَالَتْ إِنَّهَا نَذَرَتْ إِنْ نَجَّاهَا اللَّهُ عَلَيْهَا لَتَنْحَرَنَّهَا. فَأَتَوْا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرُوا ذَلِكَ لَهُ. فَقَالَ سُبْحَانَ اللَّهِ بِئْسَمَا جَزَتْهَا نَذَرَتْ لِلَّهِ إِنْ نَجَّاهَا اللَّهُ عَلَيْهَا لَتَنْحَرَنَّهَا لاَ وَفَاءَ لِنَذْرٍ فِي مَعْصِيَةٍ وَلاَ فِيمَا لاَ يَمْلِكُ الْعَبْدُ.","وفي رواية: لا نذر في معصية الله."],"takhrij":"صحيح: رواه مسلم في النذر (1641) من طرق عن إسماعيل بن إبراهيم، حدثنا أيوب، عن أبي قلابة، عن أبي المهلّب، عن عمران بن حصين فذكره.","grade":"صحيح","chapter_ar":"باب لا نذر فيما لا يملك العبد","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1641).","chapter_en":"There Is No Vow Regarding What a Person Does Not Own","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["ʿImran ibn Husayn said: Thaqif were allies of Banu ʿAqil. Thaqif captured two men from the Companions of the Messenger of Allah ﷺ, and the Companions of the Messenger of Allah ﷺ captured a man from Banu ʿAqil. They also captured al-ʿAdba’ with him. The Messenger of Allah ﷺ came to him while he was bound. He said: “O Muhammad!” So he came to him and said: “What is your matter?” He said: “Why have you taken me, and why have you taken the swift she-camel of the pilgrims?” He said — emphasizing the matter: “I took you because of the crime of your allies, Thaqif.” Then he turned away from him. The man called him and said: “O Muhammad, O Muhammad.” The Messenger of Allah ﷺ was merciful and gentle, so he returned to him and said: “What is your matter?” He said: “I am a Muslim.” He said: “If you had said that while you still had control of your own affair, you would have achieved complete success.” Then he turned away, and the man called him again, saying: “O Muhammad, O Muhammad.” He came to him and said: “What is your matter?” He said: “I am hungry, so feed me, and I am thirsty, so give me drink.” He said: “This is your need.” So he was ransomed in exchange for the two men. He said: A woman from the Ansar was captured, and al-ʿAdba’ was also captured. The woman was bound, and the people used to rest their livestock in front of their houses. One night she escaped from her bonds and came to the camels. Whenever she approached a camel, it groaned, so she left it, until she reached al-ʿAdba’. It did not groan. He said: It was a trained she-camel. She sat on its rear, then urged it on, and it set off. They noticed her and pursued her, but she escaped them. He said: She vowed to Allah that if Allah saved her upon it, she would slaughter it. When she reached Madinah, the people saw it and said: “Al-ʿAdba’, the she-camel of the Messenger of Allah ﷺ!” She said that she had vowed that if Allah saved her upon it, she would slaughter it. So they came to the Messenger of Allah ﷺ and mentioned that to him. He said: “Glory be to Allah! What a terrible reward she has given it. She vowed to Allah that if Allah saved her upon it, she would slaughter it. There is no fulfillment of a vow in disobedience, nor regarding what a servant does not own.” In another narration: “There is no vow in disobedience to Allah.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1641,"lafz":true}],"full":1},{"num":7146,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ نَذْرَ وَلاَ يَمِينَ فِيمَا لاَ يَمْلِكُ ابْنُ آدَمَ وَلاَ فِي مَعْصِيَةِ اللَّهِ وَلاَ فِي قَطِيعَةِ رَحِمٍ، وَمَنْ حَلَفَ عَلَى يَمِينٍ فَرَأَى غَيْرَهَا خَيْرًا مِنْهَا فَلْيَدَعْهَا وَلْيَأْتِ الَّذِي هُوَ خَيْرٌ، فَإِنَّ تَرْكَهَا كَفَّارَتُهَا."],"takhrij":"حسن: رواه أبو داود (3274) والنسائي (3792) وأحمد (6990) والبيهقي (10/33) كلهم من حديث عبيد الله بن الأخنس، عن عمرو بن شعيب، عن أبيه، عن جده فذكره. ورواه ابن ماجة (2111) من وجه آخر عن عمرو بن شعيب، عن أبيه، عن جده. إلا أن النسائي لم يذكر من قوله: ومن حلف على يمين... فإن تركها كفارتها","grade":"حسن","chapter_ar":"باب لا نذر فيما لا يملك العبد","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3274), al-Nasa’i (3792), Ahmad (6990), and al-Bayhaqi (10/33).","chapter_en":"There Is No Vow Regarding What a Person Does Not Own","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb narrated from his father, from his grandfather, who said: The Messenger of Allah ﷺ said: “There is no vow and no oath regarding what the son of Adam does not own, nor in disobedience to Allah, nor in severing family ties. Whoever swears an oath and then sees something better than it, let him leave it and do what is better, for leaving it is its expiation.”"]},"buhuth":{"en":["His statement, “for leaving it is its expiation,” is irregular and contradicts the authentic hadiths that obligate expiation when an oath is broken."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3274,"lafz":true},{"key":"nasai","label":"النسائي","number":3792},{"key":"kubrabayhaqi","label":"البيهقي","number":10},{"key":"ahmad","label":"مسند الإمام أحمد","number":6990,"n":6990},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":19859,"n":20017},{"key":"ibnmajah","label":"ابن ماجه","number":2111}],"full":1,"dr":1},{"num":7147,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ، أَنَّ أَخَوَيْنِ مِنَ الأَنْصَارِ كَانَ بَيْنَهُمَا مِيرَاثٌ، فَسَأَلَ أَحَدُهُمَا صَاحِبَهُ الْقِسْمَةَ، فَقَالَ: لَئِنْ عُدْتَ تَسْأَلُنِي الْقِسْمَةَ لَمْ أُكَلِّمْكَ أَبَدًا، وَكُلُّ مَالٍ لِي فِي رِتَاجِ الْكَعْبَةِ، فَقَالَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ: إِنَّ الْكَعْبَةَ لَغَنِيَّةٌ عَنْ مَالِكَ، كَفِّرْ عَنْ يَمِينِكِ، وَكَلِّمْ أَخَاكَ، فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا يَمِينَ عَلَيْكَ، وَلَا نَذْرَ فِي مَعْصِيَةٍ، وَلَا فِي قَطِيعَةِ رَحِمٍ، وَلَا فِيمَا لَا تَمْلِكُ."],"takhrij":"حسن: رواه أبو داود (3272)، وابن حبان (4355) والحاكم (4/300) والبيهقي (10/33) كلهم من طريق يزيد بن زريع، حدثنا خبيب المعلم، عن عمرو بن شعيب، عن سعيد بن المسيب فذكره. قال الحاكم: \"صحيح الإسناد\".","grade":"حسن","chapter_ar":"باب النذر في قطيعة الرحم","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3272), Ibn Hibban (4355), al-Hakim (7823), and al-Bayhaqi (10/33).","chapter_en":"A Vow Involving Severing Family Ties","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["Saʿid ibn al-Musayyib narrated that two brothers from the Ansar had inheritance between them. One of them asked the other for division of the inheritance, so he said: “If you ask me again for division, I will never speak to you, and all my wealth will be for the gate of the Kaʿbah.” ʿUmar ibn al-Khattab said: “The Kaʿbah has no need of your wealth. Expiate your oath and speak to your brother, for I heard the Messenger of Allah ﷺ say: ‘There is no binding oath upon you, and no vow in disobedience, nor in severing family ties, nor regarding what you do not own.’”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3272,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":10},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4078,"n":4074},{"key":"hakim","label":"المستدرك على الصحيحين","number":7823,"n":7827},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":20038,"n":20196},{"key":"ibnhibban","label":"ابن حبان","number":4355}],"full":1,"dr":1},{"num":7148,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا نَذْرَ إِلَّا فِيمَا ابْتُغِيَ بِهِ وَجْهُ اللَّهِ عَزَّ وَجَلَّ، وَلَا يَمِينَ فِي قَطِيعَةِ رَحِمٍ."],"takhrij":"حسن: رواه أبو داود (2373) وأحمد (6732) كلاهما من حديث عبدالرحمن بن الحارث، عن عمرو بن شعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب النذر في قطيعة الرحم","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3273) and Ahmad (6732). The wording is from Ahmad.","chapter_en":"A Vow Involving Severing Family Ties","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb narrated from his father, from his grandfather, who said: The Messenger of Allah ﷺ said: “There is no vow except in that by which the Face of Allah, the Mighty and Majestic, is sought, and there is no oath in severing family ties.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3273,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":6732,"n":6732},{"key":"abudawud","label":"ابو داود","number":2373}],"full":1,"dr":1},{"num":7149,"demo":false,"sanad":"","matn":["عَنْ أنس بْنِ مَالِكٍ أَنَّهُ سُئِلَ: هَلْ غَزَوْتَ مَعَ نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ؟ قَالَ: نَعَمْ، غَزَوْتُ مَعَهُ يَوْمَ حُنَيْنٍ، فَخَرَجَ الْمُشْرِكُونَ بِكَثْرَةٍ، فَحَمَلُوا عَلَيْنَا، حَتَّى رَأَيْنَا خَيْلَنَا وَرَاءَ ظُهُورِنَا، وَفِي الْمُشْرِكِينَ رَجُلٌ يَحْمِلُ عَلَيْنَا، فَيَدُقُّنَا وَيُحَطِّمُنَا، فَلَمَّا رَأَى ذَلِكَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَزَلَ فَهَزَمَهُمُ اللهُ فَوَلَّوْا، فَقَامَ نَبِيُّ اللَّهِ حِينَ رَأَى الْفَتْحَ، فَجَعَلَ يُجَاءُ بِهِمْ أُسَارَى رَجُلًا رَجُلًا، فَيُبَايِعُونَهُ عَلَى الْإِسْلَامِ، فَقَالَ رَجُلٌ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنَّ عليّ نَذْرًا لَئِنْ جِيءَ بِالرَّجُلِ الَّذِي كَانَ منذر الْيَوْمِ يُحَطِّمُنَا لَأَضْرِبَنَّ عُنُقَهُ. قَالَ: فَسَكَتَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَجِيءَ بِالرَّجُلِ، فَلَمَّا رَأَى نَبِيَّ اللَّهِ، قَالَ: يَا نَبِيَّ اللَّهِ، تُبْتُ إِلَى اللَّهِ، يَا نَبِيَّ اللَّهِ تُبْتُ إِلَى اللَّهِ. قَالَ: فَأَمْسَكَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَلَمْ يُبَايِعْهُ لِيُوفِيَ الْآخَرُ نَذْرَهُ، قَالَ: فَجَعَلَ يَنْظُرُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيَأْمُرَهُ بِقَتْلِهِ، وَجَعَلَ يَهَابُ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَقْتُلَهُ، فَلَمَّا رَأَى نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ لَا يَصْنَعُ شَيْئًا بَايَعَهُ. فَقَالَ: يَا نَبِيَّ اللَّهِ نَذْرِي؟ قَالَ: لَمْ أُمْسِكْ عَنْهُ مُنْذُ الْيَوْمِ إِلَّا لتوافي نَذْرَكَ فَقَالَ: يَا نَبِيَّ اللَّهِ! أَلَا أَوْمَضْتَ إليّ؟ فَقَالَ: إِنَّهُ لَيْسَ لِنَبِيٍّ أَنْ يُومِضَ."],"takhrij":"صحيح: رواه أبو داود (3194) وأحمد (12529) والطحاوي في شرحه (1513) كلهم من حديث عبد الوارث بن سعيد، قال: حدثنا أبو غالب الباهلي، عن أنس بن مالك فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب من نذر أن يقتل رجلاً من المشركين إن قدر عليه فحال بينه وبين ذلك إسلامه فلم يقتله","chapter_ur":"","part_ar":"كتاب الأيمان والنذور","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3194), Ahmad (12529), and al-Tahawi in his Sharh (1513).","chapter_en":"Whoever Vowed to Kill a Man from the Polytheists If He Gained Power Over Him, but His Islam Came Between Him and That, So He Did Not Kill Him","part_en":"The Book of Oaths and Vows","group_ar":"جموع أبواب ما جاء في النذر","group_en":"Collection of Chapters on What Has Been Reported Concerning Vows","part_no":35,"group_no":2,"chapter_no":13,"content":{"translation":{"en":["Anas ibn Malik was asked: “Did you go on campaign with the Prophet of Allah ﷺ?” He said: Yes, I went with him on the Day of Hunayn. The polytheists came out in great numbers and charged at us, until we saw our cavalry behind us. Among the polytheists there was a man who would charge at us, push us back, and break through us. When the Prophet of Allah ﷺ saw that, he dismounted, and Allah defeated them, so they turned away. When the Prophet of Allah ﷺ saw the victory, he stood, and captives were brought one by one, pledging allegiance to him upon Islam. A man from the Companions of the Messenger of Allah ﷺ said: “I have a vow upon me: if the man who kept breaking through us today is brought, I will strike his neck.” He said: The Prophet of Allah ﷺ remained silent. The man was brought, and when he saw the Prophet of Allah ﷺ, he said: “O Prophet of Allah, I repent to Allah. O Prophet of Allah, I repent to Allah.” He said: The Prophet of Allah ﷺ held back and did not accept his pledge, so that the other man could fulfill his vow. The Companion kept looking, waiting for the Prophet ﷺ to command him to kill the man, but he was hesitant to kill him in the presence of the Prophet of Allah ﷺ. When the Prophet of Allah ﷺ saw that he was not doing anything, he accepted the man’s pledge. The Companion said: “O Prophet of Allah, what about my vow?” He said: “I only held back from him from that time so that you could fulfill your vow.” He said: “O Prophet of Allah, why did you not signal to me?” He said: “It is not for a prophet to signal deceptively.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3194,"lafz":true},{"key":"sh21108","label":"الطحاوي في شرحه","number":1513},{"key":"ahmad","label":"مسند الإمام أحمد","number":12529,"n":12529}],"full":1},{"num":7150,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ مَا الْعَمَلُ فِي أَيَّامِ الْعَشْرِ أَفْضَلَ مِنَ الْعَمَلِ فِي هَذِهِ. قَالُوا وَلاَ الْجِهَادُ قَالَ وَلاَ الْجِهَادُ، إِلاَّ رَجُلٌ خَرَجَ يُخَاطِرُ بِنَفْسِهِ وَمَالِهِ فَلَمْ يَرْجِعْ بِشَىْءٍ."],"takhrij":"صحيح: رواه البخاري في العيدين (969) عن محمد بن عرعرة، قال: حدثنا شعبة، عن سليمان، عن مسلم البطين، عن سعيد بن جبير، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب فضل العمل في عشر ذي الحجة","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (969).","chapter_en":"The Virtue of Deeds During the First Ten Days of Dhu al-Hijjah","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Ibn ʿAbbas narrated from the Prophet ﷺ that he said: “No deeds done in any days are better than deeds done in these ten days.” They said: “Not even striving in the way of Allah?” He said: “Not even striving in the way of Allah, except for a man who goes out risking himself and his wealth, and returns with nothing.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":969,"lafz":true}],"full":1,"dr":1,"rep":[4434,10737,12788,13717]},{"num":7151,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ أَوَّلَ مَا نَبْدَأُ بِهِ فِي يَوْمِنَا هَذَا أَنْ نُصَلِّيَ ثُمَّ نَرْجِعَ فَنَنْحَرَ، مَنْ فَعَلَهُ فَقَدْ أَصَابَ سُنَّتَنَا، وَمَنْ.","وفي رواية: وأصاب سنة المسلمين."],"takhrij":"متفق عليه: رواه البخاري في الأضاحي (5545)، ومسلم في الأضاحي (7:1961) كلاهما من طريق محمد بن بشار- وزاد مسلم: ومحمد بن المثنى- حدثنا محمد بن جعفر(غندر)، حدثنا شعبة، عن زُبيْد الإِيَاميّ، عن الشعبي، عن البراء بن عازب فذكره.","grade":"متفق عليه","chapter_ar":"باب الأضاحي من شعائر الإسلام","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5545) and Muslim (1961:7).","chapter_en":"Sacrificial Animals Are Among the Symbols of Islam","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Al-Bara’ ibn ʿAzib said: The Prophet ﷺ said: “The first thing we begin with on this day of ours is that we pray, then we return and sacrifice. Whoever does that has followed our Sunnah.” And in another narration: “And has followed the Sunnah of the Muslims.”"]},"intro":{"ar":["قال اللّٰه تعالى:","( فَصَلِّ لِرَبِّكَ وَانْحَرْ ) [الكوثر: ٢]","عن ابن عباس قال: “اذبح يوم النحر”."],"en":["Allah the Exalted said:","“So pray to your Lord and sacrifice.” [al-Kawthar: 2]","Ibn ʿAbbas said: “Slaughter on the Day of Sacrifice.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5545,"lafz":true},{"key":"muslim","label":"مسلم","number":7}],"full":1,"dr":1},{"num":7152,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ ذَبَحَ قَبْلَ الصَّلاَةِ فَإِنَّمَا ذَبَحَ لِنَفْسِهِ، وَمَنْ ذَبَحَ بَعْدَ الصَّلاَةِ فَقَدْ تَمَّ نُسُكُهُ، وَأَصَابَ سُنَّةَ الْمُسْلِمِينَ."],"takhrij":"متفق عليه: رواه البخاري في الأضاحي (5546) عن مسدد، حدثنا إسماعيل، عن أيوب، عن محمد (هو ابن سيرين) عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب الأضاحي من شعائر الإسلام","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5546) and Muslim (1962:10).","chapter_en":"Sacrificial Animals Are Among the Symbols of Islam","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet ﷺ said: “Whoever slaughters before the prayer has only slaughtered for himself, and whoever slaughters after the prayer has completed his rite and followed the Sunnah of the Muslims.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5546,"lafz":true},{"key":"muslim","label":"مسلم","number":10}],"full":1,"dr":1},{"num":7153,"demo":false,"sanad":"","matn":["عَنْ جَبَلَةَ بْنِ سُحَيْمٍ، أَنَّ رَجُلاً، سَأَلَ ابْنَ عُمَرَ عَنِ الأُضْحِيَةِ، أَوَاجِبَةٌ هِيَ فَقَالَ ضَحَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالْمُسْلِمُونَ. فَأَعَادَهَا عَلَيْهِ فَقَالَ أَتَعْقِلُ ضَحَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالْمُسْلِمُونَ."],"takhrij":"حسن: رواه الترمذي (1506) عن أحمد بن منيع، قال: حدثنا هُشيم قال: أخبرنا حجاج بن أرطأة، عن جبلة بن سُحيم فذكره.","grade":"حسن","chapter_ar":"باب الأضاحي من شعائر الإسلام","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1506). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"Sacrificial Animals Are Among the Symbols of Islam","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Jabalah ibn Suhaym narrated that a man asked Ibn ʿUmar about the sacrifice: “Is it obligatory?” He said: “The Messenger of Allah ﷺ and the Muslims offered sacrifices.” The man repeated the question, so Ibn ʿUmar said: “Do you understand? The Messenger of Allah ﷺ and the Muslims offered sacrifices.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1506,"lafz":true}],"full":1,"dr":1},{"num":7154,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِذَا دَخَلَتِ الْعَشْرُ وَأَرَادَ أَحَدُكُمْ أَنْ يُضَحِّيَ فَلاَ يَمَسَّ مِنْ شَعَرِهِ وَبَشَرِهِ شَيْئًا.","وفي لفظ: فلا يأخذنّ شعراً، ولايقلِمَنّ ظفراً."],"takhrij":"صحيح: رواه مسلم في الأضاحي (39:1977) عن ابن أبي عمر المكي، حدثنا سفيان هو (ابن عيينة)، عن عبدالرحمن بن حُميد بن عبدالرحمن بن عوف، سمع سعيد بن المسيب يحدث عن أم سلمة فذكرته.","grade":"صحيح","chapter_ar":"باب النهي عن أخذ الشعر، وتقليم الأظافر، إذا دخلت عليه عشر ذي الحجة","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1977:39).","chapter_en":"The Prohibition of Cutting Hair and Trimming Nails When the First Ten Days of Dhu al-Hijjah Begin","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Umm Salamah narrated that the Prophet ﷺ said: “When the ten days begin, and one of you intends to offer a sacrifice, he should not touch anything of his hair or skin.” And in another wording: “He should not remove any hair or trim any nail.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":39,"lafz":true}],"full":1,"dr":1},{"num":7155,"demo":false,"sanad":"","matn":["عن أم سلمة زوج النبي صلى الله عليه وسلم قالت: قال رسول الله صلى الله عليه وسلم: من كان له ذِبْحٌ يذبَحُه، فإذا أهِلّ هلال ذي الحجة ، فلا يأخذن من شعره، ولا من أظفاره شيئا حتى يضحّي."],"takhrij":"صحيح: رواه مسلم في الأضاحي (42:1977) عن عبيدالله بن معاذ العنبري، حدثنا أبي، حدثنا محمد بن عمرو الليثي، عن عمر بن مسلم بن عمّار ابن أُكيمة الليثي قال: سمعتُ سعيد بن المسيب يقول: سمعت أم سلمة تقول فذكرته.","grade":"صحيح","chapter_ar":"باب النهي عن أخذ الشعر، وتقليم الأظافر، إذا دخلت عليه عشر ذي الحجة","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1977:42).","chapter_en":"The Prohibition of Cutting Hair and Trimming Nails When the First Ten Days of Dhu al-Hijjah Begin","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet ﷺ, said: The Messenger of Allah ﷺ said: “Whoever has a sacrificial animal that he will slaughter, then when the crescent of Dhu al-Hijjah appears, he must not take anything from his hair or nails until he offers the sacrifice.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":42,"lafz":true}],"full":1,"dr":1},{"num":7156,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ انْكَفَأَ إِلَى كَبْشَيْنِ أَقْرَنَيْنِ أَمْلَحَيْنِ فَذَبَحَهُمَا بِيَدِهِ."],"takhrij":"متفق عليه: رواه البخاري في الأضاحي (5554) عن قتيبة بن سعيد، حدثنا عبدالوهاب، عن أيوب، عن أبي قلابة، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب صفات الأضحية المرغوب فيها","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5554) and Muslim (1966:17). Muslim added: “He mentioned the Name of Allah, said Allah is the Greatest, and placed his foot on their sides.”","chapter_en":"The Desirable Qualities of the Sacrificial Animal","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Anas narrated that the Messenger of Allah ﷺ turned toward two horned, white-and-black rams and slaughtered them with his own hand."]},"buhuth":{"en":["His statement “white-and-black”: It has been said that this refers to an animal whose whiteness is more than its blackness, and it has also been said that it means pure white."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5554,"lafz":true},{"key":"muslim","label":"مسلم","number":17,"n":375}],"full":1,"dr":1},{"num":7157,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِكَبْشٍ أَقْرَنَ يَطَأُ فِي سَوَادٍ وَيَبْرُكُ فِي سَوَادٍ وَيَنْظُرُ فِي سَوَادٍ فَأُتِيَ بِهِ لِيُضَحِّيَ بِهِ فَقَالَ."],"takhrij":"صحيح: رواه مسلم في الأضاحي (19:1967) عن هارون بن معروف، حدثنا عبدالله بن وهب، قال: قال حيوة: أخبرني أبو صخْر، عن يزيد بن قُسَيْط، عن عروة بن الزبير، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب صفات الأضحية المرغوب فيها","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1967:19).","chapter_en":"The Desirable Qualities of the Sacrificial Animal","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿA’ishah narrated that the Messenger of Allah ﷺ ordered a horned ram that walked on black, knelt on black, and looked through black, and it was brought to him so that he could sacrifice it… the hadith."]},"buhuth":{"en":["Al-Khattabi said: Her statement, “it walked on black,” and so on, means that its hooves, the places where it knelt, and what surrounded the areas of its eyes and face were black, while the rest of its body was white."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":19,"lafz":true}],"full":1,"dr":1},{"num":7158,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، قَالَ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُضَحِّي بِكَبْشٍ أَقْرَنَ فَحِيلٍ يَنْظُرُ فِي سَوَادٍ وَيَأْكُلُ فِي سَوَادٍ وَيَمْشِي فِي سَوَادٍ."],"takhrij":"صحيح: رواه أبوداود (2796)، والترمذي (1496)، والنسائي (4390)، وابن ماجه (3128) من طرق عن حفص بن غياث، عن جعفر ابن محمد، عن أبيه، عن أبي سعيد الخدري فذكره.","grade":"صحيح","chapter_ar":"باب صفات الأضحية المرغوب فيها","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2796), al-Tirmidhi (1496), al-Nasa’i (4390), and Ibn Majah (3128). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"The Desirable Qualities of the Sacrificial Animal","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: The Messenger of Allah ﷺ used to sacrifice a horned, virile ram whose eye-area was black, whose mouth was black, and whose legs were black."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2796,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1496},{"key":"nasai","label":"النسائي","number":4390},{"key":"ibnmajah","label":"ابن ماجه","number":3128}],"full":1,"dr":1},{"num":7159,"demo":false,"sanad":"","matn":["عن يونس بْنِ ميسرة بن حلبس قَالَ خَرَجْنَا مَعَ أَبِي سَعِيدٍ الزُّرَقِيِّ - صَاحِبِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - إِلَى شِرَاءِ الضَّحَايَا. قَالَ يُونُسُ فَأَشَارَ أَبُو سَعِيدٍ إِلَى كَبْشٍ أَدْغَمَ لَيْسَ بِالْمُرْتَفِعِ وَلاَ الْمُتَّضِعِ فِي جِسْمِهِ فَقَالَ لِي اشْتَرِ لِي هَذَا. كَأَنَّهُ شَبَّهَهُ بِكَبْشِ رَسُولِ اللَّهِ ـ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"حسن: رواه ابن ماجه (3129) من طريق محمد بن شعيب، أخبرني سعيد بن عبدالعزيز، ثنا يونس بن ميسرة بن حلبس قال: فذكره.","grade":"حسن","chapter_ar":"باب صفات الأضحية المرغوب فيها","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (3129).","chapter_en":"The Desirable Qualities of the Sacrificial Animal","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Yunus ibn Maysarah ibn Halbas said: I went out with Abu Saʿid al-Zuraqi, the Companion of the Messenger of Allah ﷺ, to buy sacrificial animals. Abu Saʿid pointed to a ram with blackness around its ears and jaw, neither large nor small in body, and said to me: “Buy this one for me.” It was as though he was comparing it to the ram of the Messenger of Allah ﷺ."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":3129,"lafz":true}],"full":1,"dr":1},{"num":7160,"demo":false,"sanad":"","matn":["عَنْ صَفِيَّةَ بِنْتِ شَيْبَةَ أُمِّ مَنْصُورٍ قَالَتْ: أَخْبَرَتْنِي امْرَأَةٌ مِنْ بَنِي سُلَيْمٍ وَلَدَتْ عَامَّةَ أَهْلِ دَارِنَا، أَرْسَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى عُثْمَانَ بْنِ طَلْحَةَ - وَقَالَ مَرَّةً: إِنَّهَا سَأَلَتْ عُثْمَانَ بْنَ طَلْحَةَ - لِمَ دَعَاكَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: إِنِّي كُنْتُ رَأَيْتُ قَرْنَيِ الْكَبْشِ حِينَ دَخَلْتُ الْبَيْتَ، فَنَسِيتُ أَنْ آمُرَكَ أَنْ تُخَمِّرَهُمَا، فَخَمِّرْهُمَا فَإِنَّهُ لَا يَنْبَغِي أَنْ يَكُونَ فِي الْبَيْتِ شَيْءٌ يَشْغَلُ الْمُصَلِّيَ.","قال سفيان: \"لم تزل قرنا الكبش في البيت حتى احترق البيتُ فاحترقا\"."],"takhrij":"صحيح: رواه أبوداود (2030)، وأحمد (16637)-والسياق له- من طريق سفيان (هو ابن عيينة)، حدثني منصور، عن خاله مسافِع، عن صفية بنت شيبة فذكرته.","grade":"صحيح","chapter_ar":"باب صفات الأضحية المرغوب فيها","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2030) and Ahmad (16637); this wording is Ahmad’s.","chapter_en":"The Desirable Qualities of the Sacrificial Animal","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Safiyyah bint Shaybah said: A woman from Banu Sulaym who delivered most of the people of our household told me: The Messenger of Allah ﷺ sent for ʿUthman ibn Talhah. On another occasion, she said that she asked ʿUthman ibn Talhah: “Why did the Prophet ﷺ call you?” He said: “When I entered the House, I saw the two horns of the ram, but I forgot to tell you to cover them. So cover them, for there should not be anything in the House that distracts the person praying.”"]},"buhuth":{"en":["Sufyan said: “The two horns of the ram remained in the House until the House burned, and they burned with it.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2030,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":16637,"n":16637}],"full":1,"dr":1,"rep":[13168]},{"num":7161,"demo":false,"sanad":"","matn":["عَنْ أَبِي الطُّفَيْلِ قَالَ: قُلْتُ لِابْنِ عَبَّاسٍ يَزْعُمُ قَوْمُكَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَعَى بَيْنَ الصَّفَا وَالْمَرْوَةِ وَأَنَّ ذَلِكَ سُنَّةٌ؟ قَالَ: صَدَقُوا إِنَّ إِبْرَاهِيمَ لَمَّا أُمِرَ بِالْمَنَاسِكِ عَرَضَ لَهُ الشَّيْطَانُ عِنْدَ الْمَسْعَى فَسَابَقَهُ فَسَبَقَهُ إِبْرَاهِيمُ، ثُمَّ ذَهَبَ بِهِ جِبْرِيلُ إِلَى جَمْرَةِ الْعَقَبَةِ فَعَرَضَ لَهُ الشَّيْطَانُ فَرَمَاهُ بِسَبْعِ حَصَيَاتٍ حَتَّى ذَهَبَ، ثُمَّ عَرَضَ لَهُ عِنْدَ الْجَمْرَةِ الْوُسْطَى فَرَمَاهُ بِسَبْعِ حَصَيَاتٍ، وثمَ تلَّه لِلجَبِينِ، وَعَلَى إِسْمَاعِيلَ قَمِيصٌ أَبْيَضُ، فَقَالَ لَهُ: يَا أَبَتِ إِنَّهُ لَيْسَ لِي ثَوْبٌ تُكَفِّنُنِي فِيهِ غَيْرُهُ، فَاخْلَعْهُ حَتَّى تُكَفِّنَنِي فِيهِ، فَعَالَجَهُ لِيَخْلَعَهُ فَنُودِيَ مِنْ خَلْفِهِ قَدْ صَدَّقْتَ الرُّؤْيَا [سورة الصافات:105] فَالْتَفَتَ إِبْرَاهِيمُ فَإِذَا هُوَ بِكَبْشٍ أَبْيَضَ أَقْرَنَ أَعْيَنَ.","قال ابن عباس: لقد رأيتُنا نتتبع ذلك الضرب من الكباش."],"takhrij":"حسن: وهو جزء من حديث طويل رواه الإمام أحمد (2707)، وأبوداود الطيالسي (2820) من طريق حماد بن سلمة، عن أبي عاصم الغنوي، عن أبي الطفيل فذكره، وقد سبق بتمامه في كتاب الحج.","grade":"حسن","chapter_ar":"باب صفات الأضحية المرغوب فيها","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (2707) and Abu Dawud al-Tayalisi (2820).","chapter_en":"The Desirable Qualities of the Sacrificial Animal","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abu al-Tufayl said: I said to Ibn ʿAbbas: “Your people claim that the Messenger of Allah ﷺ walked between al-Safa and al-Marwah, and that this is a Sunnah.” He said: “They spoke the truth. When Ibrahim (peace be upon him) was commanded with the rites, Satan appeared to him at the place of Saʿy. Ibrahim (peace be upon him) raced him and outran him. Then Jibril took him to the large stone-throwing place, and Satan appeared to him, so he threw seven pebbles at him until he went away. Then he appeared to him at the middle stone-throwing place, so he threw seven pebbles at him. Then he laid him down on his forehead, and Ismaʿil (peace be upon him) was wearing a white shirt. He said to him: ‘My father, I have no garment in which I may be shrouded except this, so take it off so you can shroud me in it.’ He began trying to remove it, then he was called from behind: ‘You have indeed fulfilled the vision.’ [Surah al-Saffat: 105] Ibrahim (peace be upon him) turned, and there was a white, horned, wide-eyed ram.” Ibn ʿAbbas said: “I remember that we used to seek out that type of ram.”"]},"buhuth":{"en":["As for what has been narrated from Abu Hurayrah as a statement raised to the Prophet ﷺ: “Choose excellent sacrificial animals, for they will be your mounts on the Bridge,” it has no basis.","Al-Rafiʿi narrated it in al-Tadwin fi Akhbar Qazwin (3/219), and in its chain is Yahya ibn ʿUbayd Allah ibn Mawhab, who is abandoned in hadith."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":2707,"lafz":true},{"key":"tayalisi","label":"أبو داود الطيالسي","number":2820}],"full":1,"dr":1},{"num":7162,"demo":false,"sanad":"","matn":["عَنْ عُبَيْدِ بْنِ فَيْرُوزَ، قَالَ سَأَلْتُ الْبَرَاءَ بْنَ عَازِبٍ مَا لاَ يَجُوزُ فِي الأَضَاحِي فَقَالَ قَامَ فِينَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصَابِعِي أَقْصَرُ مِنْ أَصَابِعِهِ وَأَنَامِلِي أَقْصَرُ مِنْ أَنَامِلِهِ فَقَالَ أَرْبَعٌ لاَ تَجُوزُ فِي الأَضَاحِي الْعَوْرَاءُ بَيِّنٌ عَوَرُهَا وَالْمَرِيضَةُ بَيِّنٌ مَرَضُهَا وَالْعَرْجَاءُ بَيِّنٌ ظَلْعُهَا وَالْكَسِيرُ الَّتِي لاَ تَنْقَى. قَالَ قُلْتُ فَإِنِّي أَكْرَهُ أَنْ يَكُونَ فِي السِّنِّ نَقْصٌ. قَالَ مَا كَرِهْتَ فَدَعْهُ وَلاَ تُحَرِّمْهُ عَلَى أَحَدٍ."],"takhrij":"صحيح: رواه أبو داود (2802)، والنسائي (4369)، وابن ماجه (3144)، وأحمد (18510)، وابن خزيمة (2912)، وابن حبان (5922)، والحاكم (1/467-468) كلهم من طريق شعبة، قال: سمعت سليمان بن عبدالرحمن، قال: سمعت عُبيد بن فيروز، به، فذكره.","grade":"صحيح","chapter_ar":"باب ما لا يجوز من الأضاحي","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2802), al-Nasa’i (4369), Ibn Majah (3144), and Ahmad (18510).","chapter_en":"What Is Not Permissible for Sacrificial Animals","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["ʿUbayd ibn Fayruz said: I asked al-Bara’ ibn ʿAzib: “What is not permissible among sacrificial animals?” He said: The Messenger of Allah ﷺ stood among us — and my fingers are shorter than his fingers, and my fingertips are shorter than his fingertips — and said: “Four are not permissible among sacrificial animals: the one-eyed animal whose defect is clearly visible, the sick animal whose sickness is clearly visible, the lame animal whose limp is clearly visible, and the broken-down animal that has no marrow.” He said: I said: “I dislike that there be a defect in the tooth.” He said: “Whatever you dislike, leave it, but do not declare it forbidden for anyone.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2802,"lafz":true},{"key":"nasai","label":"النسائي","number":4369},{"key":"ibnmajah","label":"ابن ماجه","number":3144},{"key":"ahmad","label":"مسند الإمام أحمد","number":18510,"n":18510},{"key":"ibnkhuzaymah","label":"ابن خزيمه","number":2912},{"key":"ibnhibban","label":"ابن حبان","number":5922}],"full":1,"dr":1},{"num":7163,"demo":false,"sanad":"","matn":["7163 - عَنْ عَلِيٍّ بن أَبِي طَالِبٍ قَالَ: أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ نَسْتَشْرِفَ الْعَيْنَ وَالأُذُنَ."],"takhrij":"حسن: رواه الترمذي (1503)، والنسائي (4376)، وابن ماجه (3143)، والإمام أحمد (732، 734، 826، 1021) من طرق عن سلمة بن كهيل، عن حجية بن عدي، عن عليٍّ، فذكره.","grade":"حسن","chapter_ar":"باب استشراف عين وأذن الأضحية عند الشراء","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1503), al-Nasa’i (4376), Ibn Majah (3143), and Ahmad (734, 732, 1021, 826).","chapter_en":"Carefully Inspecting the Eye and Ear of the Sacrificial Animal When Buying It","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["ʿAli ibn Abi Talib said: The Messenger of Allah ﷺ commanded us to carefully inspect the eye and the ear."]},"buhuth":{"en":["His statement, “to carefully inspect the eye and the ear,” means to examine whether they are free of defects such as one-eyedness and having the ear cut. Careful inspection here means placing your hand over your eyebrow like someone shading himself from the sun so that the matter becomes clear."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1503,"lafz":true,"n":1519},{"key":"nasai","label":"النسائي","number":4376,"n":4372},{"key":"ibnmajah","label":"ابن ماجه","number":3143},{"key":"ahmad","label":"مسند الإمام أحمد","number":734,"n":734},{"key":"ahmad","label":"الامام احمد","number":732},{"key":"ahmad","label":"الامام احمد","number":826},{"key":"ahmad","label":"الامام احمد","number":1021}],"full":1,"dr":1},{"num":7164,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يُضَحَّى بِعَضْبَاءِ الأُذُنِ وَالْقَرْنِ."],"takhrij":"حسن: رواه أبوداود (2805)، والترمذي (1504)، والنسائي (4377)، وابن ماجه (3145)، وأحمد (633، 1048)، من طرق عن قتادة، عن جُريّ بن كُليب، عن علي، فذكره. واللفظ لأبي داود.","grade":"حسن","chapter_ar":"باب استشراف عين وأذن الأضحية عند الشراء","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2805), al-Tirmidhi (1504), al-Nasa’i (4377), Ibn Majah (3145), and Ahmad (633, 1048).","chapter_en":"Carefully Inspecting the Eye and Ear of the Sacrificial Animal When Buying It","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["ʿAli narrated that the Prophet ﷺ forbade sacrificing an animal with a cut ear or broken horn."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2805,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1504,"n":1221},{"key":"nasai","label":"النسائي","number":4377,"n":4492},{"key":"ibnmajah","label":"ابن ماجه","number":3145},{"key":"ahmad","label":"مسند الإمام أحمد","number":633,"n":812},{"key":"ahmad","label":"احمد","number":1048,"n":1159}],"full":1,"dr":1},{"num":7165,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ تَذْبَحُوا إِلاَّ مُسِنَّةً إِلاَّ أَنْ يَعْسُرَ عَلَيْكُمْ فَتَذْبَحُوا جَذَعَةً مِنَ الضَّأْنِ."],"takhrij":"صحيح: رواه مسلم في الأضاحي (1963) عن أحمد بن يونس، حدثنا زهير، حدثنا أبوالزبير، عن جابر، فذكره.","grade":"صحيح","chapter_ar":"باب الأضحية بالجذعة من الضأن","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1963).","chapter_en":"Sacrificing a Young Sheep","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: The Messenger of Allah ﷺ said: “Do not slaughter except a mature animal, unless it becomes difficult for you; then slaughter a young sheep.”"]},"buhuth":{"en":["His statement, “except a mature animal”: a mature animal is one that has reached the required age among camels, cattle, and sheep or goats."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1963,"lafz":true}],"full":1,"dr":1},{"num":7166,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ، قَالَ: ضَحَّيْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْجَذَعَ مِنَ الضَّأْنِ."],"takhrij":"حسن: رواه النسائي (4382)، وابن حبان (5904)، وابن الجارود (905) من طريق ابن وهب، أخبرني عمرو بن الحارث، عن بكير بن عبدالله ابن الأشج، حدّثه أن معاذ بن عبدالله بن خبيب الجهني حدّثه، عن عقبة بن عامر الجهني، فذكره.","grade":"حسن","chapter_ar":"باب الأضحية بالجذعة من الضأن","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4382), Ibn Hibban (5904), and Ibn al-Jarud (905).","chapter_en":"Sacrificing a Young Sheep","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["ʿUqbah ibn ʿAmir said: We offered sacrifice with the Messenger of Allah ﷺ using a young sheep."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4382,"lafz":true,"n":4382},{"key":"sh13071","label":"ابن الجارود","number":905,"n":940},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":5963,"n":5960},{"key":"ibnhibban","label":"ابن حبان","number":5904}],"full":1,"dr":1},{"num":7167,"demo":false,"sanad":"","matn":["عَنْ عَاصِمِ بْنِ كُلَيْبٍ، عَنْ أَبِيهِ، قَالَ كُنَّا مَعَ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُقَالُ لَهُ مُجَاشِعٌ مِنْ بَنِي سُلَيْمٍ فَعَزَّتِ الْغَنَمُ فَأَمَرَ مُنَادِيًا فَنَادَى أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ إِنَّ الْجَذَعَ يُوَفِّي مِمَّا يُوَفِّي مِنْهُ الثَّنِيُّ."],"takhrij":"حسن: رواه أبوداود (2799)، وابن ماجه (3140)، والحاكم (4/226) من طريق عبدالرزاق، أنبأنا الثوري، عن عاصم بن كليب، عن أبيه قال: فذكره.","grade":"حسن","chapter_ar":"باب الأضحية بالجذعة من الضأن","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2799), Ibn Majah (3140), and al-Hakim (4/226).","chapter_en":"Sacrificing a Young Sheep","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Kulayb al-Jarmi said: We were with a man from the Companions of the Prophet ﷺ named Mujashiʿ from Banu Sulaym, and sheep became scarce. So he ordered a caller to announce that the Messenger of Allah ﷺ used to say: “A young sheep suffices for what a mature animal suffices for.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2799,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":3140},{"key":"hakim","label":"الحاكم","number":4}],"full":1,"dr":1},{"num":7168,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ ضَحَّى خَالٌ لِي يُقَالُ لَهُ أَبُو بُرْدَةَ قَبْلَ الصَّلاَةِ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَاتُكَ شَاةُ لَحْمٍ. فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ عِنْدِي دَاجِنًا جَذَعَةً مِنَ الْمَعَزِ. قَالَ اذْبَحْهَا وَلَنْ تَصْلُحَ لِغَيْرِكَ.","وفي رواية: إن عندي عناق لبن."],"takhrij":"متفق عليه: رواه البخاري في الأضاحي (5556)، ومسلم في الأضاحي (4:1961) كلاهما من طريق خالد بن عبدالله، عن مطرِّف، عن عامر (هو الشعبي)، عن البراء بن عازب، فذكره.","grade":"متفق عليه","chapter_ar":"باب هل تجزئ الجذعة من المعْز؟","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5556) and Muslim (1961:4). The other narration is from Muslim (1961:5).","chapter_en":"Does a Young Goat Suffice?","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Al-Bara’ ibn ʿAzib said: A maternal uncle of mine called Abu Burdah offered his sacrifice before the prayer, so the Messenger of Allah ﷺ said to him: “Your sheep is only a sheep for meat.” He said: “O Messenger of Allah, I have a young domesticated goat.” He said: “Slaughter it, but it will not be valid for anyone besides you.” And in another narration: “I have a young milk-goat.”"]},"buhuth":{"en":["His statement, “I have a domesticated animal”: a domesticated animal is a sheep that people feed in their homes, though the term may also apply to other animals that become accustomed to houses, such as birds and the like. His statement “young” describes a specific age among grazing livestock: for sheep, it is one that has completed a year — and it has been said less than that; for goats, one that has entered its second year; for cattle, one that has completed its third year; and for camels, one that has entered its fifth year.","His statement, “a young milk-goat”: a young female goat is one that has become strong but has not completed a year; its plurals are aʿnuq and ʿunuq. His statement “a young milk-goat” means a small one close to the age of nursing."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5556,"lafz":true},{"key":"muslim","label":"مسلم","number":4},{"key":"muslim","label":". والرواية الأخرى لمسلم","number":5}],"full":1,"dr":1},{"num":7169,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ، قَالَ ذَبَحَ أَبُو بُرْدَةَ قَبْلَ الصَّلاَةِ فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَبْدِلْهَا. قَالَ لَيْسَ عِنْدِي إِلاَّ جَذَعَةٌ ـ قَالَ شُعْبَةُ وَأَحْسِبُهُ قَالَ ـ هِيَ خَيْرٌ مِنْ مُسِنَّةٍ. قَالَ اجْعَلْهَا مَكَانَهَا، وَلَنْ تَجْزِيَ عَنْ أَحَدٍ بَعْدَكَ."],"takhrij":"متفق عليه: رواه البخاري في الأضاحي (5557)، ومسلم في الأضاحي (9:1961) كلاهما عن محمد بن بشار، ثنا محمد بن جعفر، ثنا شعبة، عن سلمة، عن أبي جُحيفة، عن البراء، فذكره.","grade":"متفق عليه","chapter_ar":"باب هل تجزئ الجذعة من المعْز؟","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5557) and Muslim (1961:9).","chapter_en":"Does a Young Goat Suffice?","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Al-Bara’ ibn ʿAzib said: Abu Burdah slaughtered before the prayer, so the Prophet ﷺ said to him: “Replace it.” He said: “I only have a young goat.” Shuʿbah said: I think he said: “It is better than a mature one.” He said: “Put it in its place, but it will not suffice for anyone after you.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5557,"lafz":true},{"key":"muslim","label":"مسلم","number":9}],"full":1},{"num":7170,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ، عَنْ خَالِهِ أَبِي بُرْدَةَ أَنَّهُ قَالَ: يَا رَسُولَ اللَّهِ، إِنَّا عَجَّلْنَا شَاةَ لَحْمٍ لَنَا، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَقَبْلَ الصَّلَاةِ؟، قُلْتُ: نَعَمْ، قَالَ: تِلْكَ شَاةُ لَحْمٍ، قَالَ: يَا رَسُولَ اللَّهِ، إِنَّ عِنْدَنَا عَنَاقًا جَذَعَةً هِيَ أَحَبُّ إِلَيَّ مِنْ مُسِنَّةٍ، قَالَ: تُجْزِئُ عَنْهُ وَلَا تُجْزِئُ عَنْ أَحَدٍ بَعْدَهُ."],"takhrij":"صحيح: رواه الإمام أحمد (16485)، والطبراني في الكبير (22/194) من طريق إسرائيل (هو ابن أبي إسحاق)، عن أبي إسحاق (هو السبيعي) عن البراء، به، فذكره. وإسناد صحيح.","grade":"صحيح","chapter_ar":"باب هل تجزئ الجذعة من المعْز؟","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (16485) and al-Tabarani in al-Kabir (22/194).","chapter_en":"Does a Young Goat Suffice?","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Al-Bara’ narrated from his maternal uncle Abu Burdah that he said: “O Messenger of Allah, we hastened to slaughter a sheep for meat.” The Messenger of Allah ﷺ said: “Before the prayer?” I said: “Yes.” He said: “That is a sheep for meat.” He said: “I have a young goat that is more beloved to me than a mature animal.” He said: “It will suffice for you, but it will not suffice for anyone after you.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":16485,"lafz":true},{"key":"mujamkabir","label":"الطبراني في الكبير","number":22}],"full":1},{"num":7171,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ النَّحْرِ مَنْ كَانَ ذَبَحَ قَبْلَ الصَّلاَةِ فَلْيُعِدْ. فَقَامَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ هَذَا يَوْمٌ يُشْتَهَى فِيهِ اللَّحْمُ ـ وَذَكَرَ جِيرَانَهُ ـ وَعِنْدِي جَذَعَةٌ خَيْرٌ مِنْ شَاتَىْ لَحْمٍ. فَرَخَّصَ لَهُ فِي ذَلِكَ، فَلاَ أَدْرِي أَبَلَغَتِ الرُّخْصَةُ مَنْ سِوَاهُ أَمْ لاَ، ثُمَّ."],"takhrij":"متفق عليه: رواه البخاري في الأضاحي (5549)، ومسلم في الأضاحي (10:1962) كلاهما من طريق إبراهيم ابن علية، عن أيوب، عن محمد بن سيرين، عن أنس، فذكره.","grade":"متفق عليه","chapter_ar":"باب هل تجزئ الجذعة من المعْز؟","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5549) and Muslim (1962:10).","chapter_en":"Does a Young Goat Suffice?","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Anas said: The Prophet ﷺ said on the Day of Sacrifice: “Whoever slaughtered before the prayer must repeat it.” A man stood and said: “O Messenger of Allah, this is a day on which meat is desired” — and he mentioned his neighbors — “and I have a young goat better than two sheep for meat.” So he granted him a concession in that. I do not know whether the concession extended to anyone besides him or not… the hadith."]},"buhuth":{"en":["His statement ﷺ: “It will not be valid for anyone besides you.” Al-Bayhaqi said: “This was a young goat, and for that reason it was not valid for anyone after him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5549,"lafz":true},{"key":"muslim","label":"مسلم","number":10}],"full":1,"dr":1},{"num":7172,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ، قَالَ قَسَمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ أَصْحَابِهِ ضَحَايَا، فَصَارَتْ لِعُقْبَةَ جَذَعَةٌ. فَقُلْتُ يَا رَسُولَ اللَّهِ صَارَتْ جَذَعَةٌ. قَالَ ضَحِّ بِهَا.","وفي رواية: فبقِيَ عَتُودٌ فذكره صلى الله عليه وسلم فقال: ضحِّ أنت به."],"takhrij":"متفق عليه: رواه البخاري في الأضاحي (5547)، ومسلم في الأضاحي (16:1965) من طريق هشام الدستوائي، عن يحيى بن أبي كثير، عن بعجة الجهني، عن عقبة بن عامر الجهني، فذكره.","grade":"متفق عليه","chapter_ar":"باب هل تجزئ الجذعة من المعْز؟","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5547) and Muslim (1965:16).","chapter_en":"Does a Young Goat Suffice?","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["ʿUqbah ibn ʿAmir al-Juhani said: The Prophet ﷺ distributed sacrificial animals among his Companions, and a young goat came to ʿUqbah. I said: “O Messenger of Allah, a young goat has come to me?” He said: “Sacrifice it.” In another narration: A young male goat remained, so he mentioned it to him ﷺ and he said: “You sacrifice it.”"]},"buhuth":{"en":["His statement, “a young male goat remained”: al-Nawawi said: The scholars of language said that a young male goat is specifically from the offspring of goats, and it is one that has grazed and grown strong. Sharh Muslim (13/118), and al-Fath (10/11)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5547,"lafz":true},{"key":"muslim","label":"مسلم","number":16},{"key":"muslim","label":"العَتود من أولاد المعز خاصة وهو ما رعى وقوي. شرح مسلم","number":13},{"key":"الفتح","label":"الفتح","number":10}],"full":1,"dr":1},{"num":7173,"demo":false,"sanad":"","matn":["عَنْ بُشَيْرِ بْنِ يَسَارٍ، أَنَّ أَبَا بُرْدَةَ بْنَ نِيَارٍ، ذَبَحَ ضَحِيَّتَهُ قَبْلَ أَنْ يَذْبَحَ، رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الأَضْحَى فَزَعَمَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَهُ أَنْ يَعُودَ بِضَحِيَّةٍ أُخْرَى. قَالَ أَبُو بُرْدَةَ لاَ أَجِدُ إِلاَّ جَذَعًا يَا رَسُولَ اللَّهِ. قَالَ وَإِنْ لَمْ تَجِدْ إِلاَّ جَذَعًا فَاذْبَحْ."],"takhrij":"صحيح: رواه مالك في الضحايا (4) عن يحيى بن سعيد ( هو الأنصاري) عن بُشير بن يسار، به، فذكره. وصحّحه ابن حبان (5905) من هذا الوجه.","grade":"صحيح","chapter_ar":"باب هل تجزئ الجذعة من المعْز؟","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (4), and authenticated by Ibn Hibban (5905).","chapter_en":"Does a Young Goat Suffice?","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Bushayr ibn Yasar narrated that Abu Burdah ibn Niyar slaughtered his sacrificial animal before the Messenger of Allah ﷺ slaughtered on the Day of Sacrifice. He claimed that the Messenger of Allah ﷺ ordered him to repeat with another sacrificial animal. Abu Burdah said: “I only find a young animal, O Messenger of Allah.” He said: “Even if you only find a young animal, then slaughter it.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":4,"lafz":true},{"key":"ibnhibban","label":"صححه ابن حبان","number":5905},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1286,"n":1283}],"full":1,"dr":1},{"num":7174,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ، قَالَ قَسَمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي أَصْحَابِهِ ضَحَايَا فَأَعْطَانِي عَتُودًا جَذَعًا - قَالَ - فَرَجَعْتُ بِهِ إِلَيْهِ فَقُلْتُ لَهُ إِنَّهُ جَذَعٌ. قَالَ ضَحِّ بِهِ. فَضَحَّيْتُ بِهِ."],"takhrij":"حسن: رواه أبوداود (2798)، والإمام أحمد (21690) وصححه ابن حبان (5899) من طرق عن ابن إسحاق، حدثني عُمارة بن عبدالله بن طُعمة، عن سعيد بن المسيب، عن زيد بن خالد الجهني، فذكره.","grade":"حسن","chapter_ar":"باب هل تجزئ الجذعة من المعْز؟","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2798), Imam Ahmad (21690), and authenticated by Ibn Hibban (5899).","chapter_en":"Does a Young Goat Suffice?","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Zayd ibn Khalid al-Juhani said: The Messenger of Allah ﷺ distributed sacrificial animals among his Companions and gave me a young male goat. He said: I returned to him with it and said to him: “It is young.” He said: “Sacrifice it.” So I sacrificed it."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2798,"lafz":true},{"key":"ahmad","label":"الإمام أحمد","number":21690},{"key":"ibnhibban","label":"صححه ابن حبان","number":5899}],"full":1,"dr":1},{"num":7175,"demo":false,"sanad":"","matn":["عن أَبِي جُحَيْفَةَ عَنْ أَبِيهِ، أَنَّ رَجُلًا ذَبَحَ قَبْلَ أَنْ يُصَلِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ النَّحْرِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يُجْزِئُ عَنْكَ، فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّ عِنْدِي جَذَعَةً؟ قَالَ: تَجْزِي عَنْكَ وَلَا تَجْزِي بَعْدَكَ."],"takhrij":"حسن: رواه أبو يعلى (897)، والطبراني في الكبير (22/108) كلاهما من طريق عبيدالله بن موسى، ثنا عبدالجبار بن العباس، عن عون بن أبي جحيفة، عن أبيه، فذكره.","grade":"حسن","chapter_ar":"باب هل تجزئ الجذعة من المعْز؟","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Yaʿla (897) and al-Tabarani in al-Kabir (22/108).","chapter_en":"Does a Young Goat Suffice?","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Abu Juhayfah narrated that a man slaughtered before the Messenger of Allah ﷺ prayed on the Day of Sacrifice. The Messenger of Allah ﷺ said: “It does not suffice for you.” He said: “O Messenger of Allah, I have a young goat.” He said: “It will suffice for you, but it will not suffice after you.”"]}},"tuhfa":{},"refs":[{"key":"sh12520","label":"أبو يعلى","number":897,"lafz":true},{"key":"mujamkabir","label":"الطبراني في الكبير","number":22}],"full":1,"dr":1},{"num":7176,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ أُمِرْتُ بِيَوْمِ الأَضْحَى عِيدًا جَعَلَهُ اللَّهُ عَزَّ وَجَلَّ لِهَذِهِ الأُمَّةِ. قَالَ الرَّجُلُ أَرَأَيْتَ إِنْ لَمْ أَجِدْ إِلاَّ أُضْحِيَةً أُنْثَى أَفَأُضَحِّي بِهَا قَالَ لاَ وَلَكِنْ تَأْخُذُ مِنْ شَعْرِكَ وَأَظْفَارِكَ وَتَقُصُّ شَارِبَكَ وَتَحْلِقُ عَانَتَكَ فَتِلْكَ تَمَامُ أُضْحِيَتِكَ عِنْدَ اللَّهِ عَزَّ."],"takhrij":"حسن: رواه أبوداود (2789)، والنسائي (4365)، والإمام أحمد (6575)، وابن حبان (5914)، والحاكم (4/223) من طريق سعيد بن أبي أيوب، حدثني عياش بن عباس القتباني، عن عيسى بن هلال الصدفي، عن عبدالله بن عمرو بن العاص، فذكره.","grade":"حسن","chapter_ar":"باب من لم يجد أضحية إلا منيحة","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2789), al-Nasa’i (4365), Imam Ahmad (6575), and Ibn Hibban (5914).","chapter_en":"One Who Cannot Find a Sacrificial Animal Except a Milk-Animal Lent for Use","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs narrated that the Prophet ﷺ said: “I have been commanded regarding the Day of Sacrifice as a festival that Allah, the Mighty and Majestic, has made for this nation.” A man said: “What do you think if I find nothing except a female milk-animal lent for use; should I sacrifice it?” He said: “No. Rather, take from your hair and nails, trim your moustache, and shave your pubic hair. That will be the completion of your sacrifice before Allah, the Mighty and Majestic.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2789,"lafz":true},{"key":"nasai","label":"النسائي","number":4365},{"key":"ahmad","label":"الإمام أحمد","number":6575},{"key":"ibnhibban","label":"ابن حبان","number":5914}],"full":1,"dr":1},{"num":7177,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَيْهَا وَحَاضَتْ بِسَرِفَ، قَبْلَ أَنْ تَدْخُلَ مَكَّةَ وَهْىَ تَبْكِي فَقَالَ مَا لَكِ أَنَفِسْتِ. قَالَتْ نَعَمْ. قَالَ إِنَّ هَذَا أَمْرٌ كَتَبَهُ اللَّهُ عَلَى بَنَاتِ آدَمَ، فَاقْضِي مَا يَقْضِي الْحَاجُّ غَيْرَ أَنْ لاَ تَطُوفِي بِالْبَيْتِ. فَلَمَّا كُنَّا بِمِنًى أُتِيتُ بِلَحْمِ بَقَرٍ، فَقُلْتُ مَا هَذَا قَالُوا ضَحَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ أَزْوَاجِهِ بِالْبَقَرِ.","وفي رواية : أهدى رسول الله صلى الله عليه وسلم على نسائه البقر."],"takhrij":"متفق عليه: رواه البخاري في الأضاحي (5548)، ومسلم في الحج (119:1211)كلاهما من طريق سفيان بن عيينة، عن عبدالرحمن بن القاسم، عن أبيه، عن عائشة، فذكرته. والرواية الأخرى لمسلم (120:1211) من طريق عبدالعزيز بن أبي سلمة الماجشون، عن عبدالرحمن بن القاسم به.","grade":"متفق عليه","chapter_ar":"باب الأضحية بالبقر","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5548) and Muslim (1211:119).","chapter_en":"Sacrificing Cattle","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["ʿA’ishah narrated that the Prophet ﷺ entered upon her when she had menstruated at Sarif before entering Makkah, and she was crying. He said: “What is the matter with you? Have you begun menstruating?” She said: “Yes.” He said: “This is something Allah has decreed for the daughters of Adam. Do what the pilgrim does, except that you should not circumambulate the House.” When we were at Mina, I was brought beef, and I said: “What is this?” They said: “The Messenger of Allah ﷺ sacrificed cattle on behalf of his wives.” In another narration: The Messenger of Allah ﷺ offered cattle on behalf of his wives."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5548,"lafz":true},{"key":"muslim","label":"مسلم","number":119},{"key":"muslim","label":"الروايه الاخري لمسلم","number":120}],"full":1},{"num":7178,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّهُ قَالَ نَحَرْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ الْحُدَيْبِيَةِ الْبَدَنَةَ عَنْ سَبْعَةٍ وَالْبَقَرَةَ عَنْ سَبْعَةٍ."],"takhrij":"صحيح: رواه مالك في الضحايا (9) عن أبي الزبير المكي، عن جابر بن عبدالله، فذكره. ورواه مسلم في الحج (350:1318) من طريق مالك به مثله.","grade":"صحيح","chapter_ar":"باب اشتراك السبعة في الأضحية من الإبل والبقر","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (9) and Muslim (1318:350).","chapter_en":"Seven People Sharing in a Sacrificial Camel or Cow","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: We slaughtered with the Messenger of Allah ﷺ during the year of al-Hudaybiyah: a camel on behalf of seven, and a cow on behalf of seven."]},"buhuth":{"en":["Muslim also narrated it through another route (351): We went out with the Messenger of Allah ﷺ raising our voices for pilgrimage, and the Messenger of Allah ﷺ commanded us to share in camels and cattle, every seven of us in one camel."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":9,"lafz":true},{"key":"muslim","label":"مسلم","number":350}],"full":1,"dr":1},{"num":7179,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ، عَبْدِ اللَّهِ قَالَ كُنَّا نَتَمَتَّعُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْعُمْرَةِ فَنَذْبَحُ الْبَقَرَةَ عَنْ سَبْعَةٍ نَشْتَرِكُ فِيهَا."],"takhrij":"صحيح: رواه مسلم (355:1318) عن يحيى بن يحيى، أخبرنا هُشيم، عن عبدالملك (هو ابن أبي سليمان)، عن عطاء (هو ابن أبي رباح) عن جابر بن عبدالله، فذكره.","grade":"صحيح","chapter_ar":"باب اشتراك السبعة في الأضحية من الإبل والبقر","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1318:355).","chapter_en":"Seven People Sharing in a Sacrificial Camel or Cow","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: We used to perform tamattuʿ with the Messenger of Allah ﷺ by doing ʿumrah, and we would slaughter one cow on behalf of seven, sharing in it."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":355,"lafz":true}],"full":1,"dr":1},{"num":7180,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِكَبْشٍ أَقْرَنَ يَطَأُ فِي سَوَادٍ وَيَبْرُكُ فِي سَوَادٍ وَيَنْظُرُ فِي سَوَادٍ فَأُتِيَ بِهِ لِيُضَحِّيَ بِهِ فَقَالَ لَهَا يَا عَائِشَةُ هَلُمِّي الْمُدْيَةَ. ثُمَّ قَالَ اشْحَذِيهَا بِحَجَرٍ. فَفَعَلَتْ ثُمَّ أَخَذَهَا وَأَخَذَ الْكَبْشَ فَأَضْجَعَهُ ثُمَّ ذَبَحَهُ ثُمَّ قَالَ بِاسْمِ اللَّهِ اللَّهُمَّ تَقَبَّلْ مِنْ مُحَمَّدٍ وَآلِ مُحَمَّدٍ وَمِنْ أُمَّةِ مُحَمَّدٍ. ثُمَّ ضَحَّى بِهِ."],"takhrij":"صحيح: رواه مسلم في الأضاحي (19:1967) عن هارون بن معروف، حدثنا عبدالله بن وهب، قال: قال حيوة: أخبرني أبو صخْر، عن يزيد بن قُسيْط، عن عروة بن الزبير، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب أن الأضحية الواحدة تجزئ عن أهل البيت","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1967:19).","chapter_en":"One Sacrificial Animal Suffices for a Household","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["ʿA’ishah narrated that the Messenger of Allah ﷺ ordered a horned ram that walked on black, knelt on black, and looked through black. It was brought to him so that he could sacrifice it. He said to her: “O ʿA’ishah, bring the knife.” Then he said: “Sharpen it with a stone.” She did so. Then he took it and took the ram, laid it down, slaughtered it, and said: “In the Name of Allah. O Allah, accept this from Muhammad, the family of Muhammad, and the nation of Muhammad.” Then he sacrificed it."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":19,"lafz":true}],"full":1,"rep":[7200,7203,11139]},{"num":7181,"demo":false,"sanad":"","matn":["عن عطاء بْنِ يَسَارٍ يَقُولُ سَأَلْتُ أَبَا أَيُّوبَ الأَنْصَارِيَّ كَيْفَ كَانَتِ الضَّحَايَا عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ كَانَ الرَّجُلُ يُضَحِّي بِالشَّاةِ عَنْهُ وَعَنْ أَهْلِ بَيْتِهِ فَيَأْكُلُونَ وَيُطْعِمُونَ حَتَّى تَبَاهَى النَّاسُ فَصَارَتْ كَمَا تَرَى."],"takhrij":"صحيح: رواه الترمذي (1505)، وابن ماجه (3147) من طريق الضحاك بن عثمان، حدثني عُمارة بن عبدالله بن صياد، عن عطاء بن يسار، قال: فذكره.","grade":"صحيح","chapter_ar":"باب أن الأضحية الواحدة تجزئ عن أهل البيت","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1505) and Ibn Majah (3147). Al-Tirmidhi said: “A Hasan Sahih hadith.”","chapter_en":"One Sacrificial Animal Suffices for a Household","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["ʿAta’ ibn Yasar said: I asked Abu Ayyub al-Ansari: “How were the sacrifices during the time of the Messenger of Allah ﷺ?” He said: “A man would sacrifice one sheep on behalf of himself and his household. They would eat from it and feed others, until people began competing and boasting, so it became as you see.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1505,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":3147}],"full":1,"dr":1},{"num":7182,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَرِيحَةَ، قَالَ حَمَلَنِي أَهْلِي عَلَى الْجَفَاءِ بَعْدَمَا عَلِمْتُ مِنَ السُّنَّةِ كَانَ أَهْلُ الْبَيْتِ يُضَحُّونَ بِالشَّاةِ وَالشَّاتَيْنِ وَالآنَ يُبَخِّلُنَا جِيرَانُنَا."],"takhrij":"صحيح: رواه ابن ماجه (3148) من طريق عبدالرزاق وهو في مصنفه (8150)، عن سفيان الثوري، عن بيان، عن الشعبي، عن أبي سريحة، فذكره.","grade":"صحيح","chapter_ar":"باب أن الأضحية الواحدة تجزئ عن أهل البيت","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (3148) and ʿAbd al-Razzaq in his Musannaf (8150).","chapter_en":"One Sacrificial Animal Suffices for a Household","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Abu Surayhah said: “My family pushed me toward harshness after I had learned the Sunnah. A household used to sacrifice one sheep or two sheep, but now our neighbors accuse us of being stingy.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":3148,"lafz":true},{"key":"abdrazzaq","label":"عبد الرزاق في مصنفه","number":8150,"n":8402}],"full":1,"dr":1},{"num":7183,"demo":false,"sanad":"","matn":["عَنْ أَبِي عُقيل زُهرة بن مَعْبَدٍ، عَنْ جَدِّهِ عبدالله بْنِ هِشَامٍ-وَكَانَ قَدْ أَدْرَكَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَذَهَبَتْ بِهِ أُمُّهُ زَيْنَبُ ابْنَةُ حُمَيْدٍ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ بَايِعْهُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : هُوَ صَغِيرٌ فَمَسَحَ رَأْسَهُ وَدَعَا لَهُ وَكَانَ يُضحّي بِالشَّاةِ الْوَاحِدَةِ عَنْ جَمِيعِ أَهْلِهِ."],"takhrij":"صحيح: رواه البخاري في الأحكام (7210) عن علي بن عبدالله، حدثنا عبدالله بن يزيد، حدثنا سعيد بن أبي أيوب، حدثني أبو عَقيل زهرة بن معبد، عن جده فذكره.","grade":"صحيح","chapter_ar":"باب أن الأضحية الواحدة تجزئ عن أهل البيت","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7210).","chapter_en":"One Sacrificial Animal Suffices for a Household","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Abu ʿUqayl Zuhrah ibn Maʿbad narrated from his grandfather ʿAbdullah ibn Hisham, who had met the Prophet ﷺ. His mother, Zaynab bint Humayd, took him to the Messenger of Allah ﷺ and said: “O Messenger of Allah, accept his pledge.” The Prophet ﷺ said: “He is young.” So he wiped his head and supplicated for him. He used to sacrifice one sheep on behalf of all his family."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7210,"lafz":true}],"full":1,"dr":1},{"num":7184,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أمرَ بِكَبْشٍ أَقْرَنَ، يطأُ فِي سَوَادٍ وَيَبْرُكُ فِي سَوَادٍ، وَيَنْظُرُ فِي سَوَادٍ، فأُتِيَ بِهِ لِيُضَحِّيَ بِهِ، فَقَالَ لَهَا: يَا عَائِشَةُ هلُمّي الْمُدْيةَ ثُمَّ قَالَ: اشحَذِيْها بِحَجَرٍ فَفَعَلَتْ، ثُمَّ أَخَذَهَا، وَأَخَذَ الكبْشَ، فَأَضْجَعَهُ، ثُمَّ ذَبَحَهُ ثُمَّ قَالَ: بِاسْمِ اللَّهِ، اللَّهُمَّ تقَّبلْ مِنْ مُحَمَّدٍ، وَآلِ مُحَمَّدٍ، وَمِنْ أُمَّةِ مُحَمَّدٍ، ثُمَّ ضحَّى بِهِ."],"takhrij":"صحيح: رواه مسلم في الأضاحي (19:1967) عن هارون بن معروف، حدثنا عبدالله بن وهب، قال: قال حيوة: أخبرني أبو صخْر، عن يزيد بن قُسيْط، عن عروة بن الزبير، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب من قال بجواز الأضحية عن الميّت","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1967:19).","chapter_en":"Whoever Said That Sacrificing on Behalf of the Deceased Is Permissible","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["ʿA’ishah narrated that the Messenger of Allah ﷺ ordered a horned ram that walked on black, knelt on black, and looked through black. It was brought to him so that he could sacrifice it. He said to her: “O ʿA’ishah, bring the knife.” Then he said: “Sharpen it with a stone.” She did so. Then he took it and took the ram, laid it down, slaughtered it, and said: “In the Name of Allah. O Allah, accept this from Muhammad, the family of Muhammad, and the nation of Muhammad.” Then he sacrificed it."]},"buhuth":{"en":["Some scholars used his statement, “from the nation of Muhammad,” as evidence for the permissibility of sacrificing on behalf of the deceased, because the nation includes both the living and the dead. However, a specification has come in the wording, “on behalf of those of my nation who did not sacrifice,” as found in the following hadiths of Abu Saʿid al-Khudri and Jabir ibn ʿAbdullah."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":19,"lafz":true}],"full":1,"dr":1},{"num":7185,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِي يَوْمَ النَّحْرِ بِكَبْشَيْنِ أَمْلَحَيْنِ، فَذَبَحَ أَحَدَهُمَا فَقَالَ: هَذَا عَنْ مُحَمَّدٍ وَأَهْلِ بَيْتِهِ، وَذَبَحَ الآخَرَ وَقَالَ: هَذَا عَمَّنْ لَمْ يُضحِّ عَنْ أُمَّتِي."],"takhrij":"حسن: رواه أحمد (11051)، والبزار (1209-كشف) واللفظ له، والحاكم (4/228) من طرق عن عبدالعزيز بن محمد الدراوردي، ثنا رُبيح بن عبدالرحمن بن أبي سعيد الخدري، عن أبيه، عن جده، فذكره.","grade":"حسن","chapter_ar":"باب من قال بجواز الأضحية عن الميّت","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (11051), al-Bazzar (1209 — Kashf), with this wording, and al-Hakim (4/228).","chapter_en":"Whoever Said That Sacrificing on Behalf of the Deceased Is Permissible","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that on the Day of Sacrifice, the Messenger of Allah ﷺ was brought two white-and-black rams. He slaughtered one of them and said: “This is on behalf of Muhammad and his household.” He slaughtered the other and said: “This is on behalf of those of my nation who did not sacrifice.”"]}},"tuhfa":{},"refs":[{"key":"bazzar","label":"البزار","number":1209},{"key":"hakim","label":"الحاكم","number":228},{"key":"ahmad","label":"مسند الإمام أحمد","number":11051,"n":11051,"lafz":true},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1209,"n":1209}],"full":1,"dr":1,"rep":[7188]},{"num":7186,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ شَهِدْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الأَضْحَى بِالْمُصَلَّى فَلَمَّا قَضَى خُطْبَتَهُ نَزَلَ مِنْ مِنْبَرِهِ وَأُتِيَ بِكَبْشٍ فَذَبَحَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ وَقَالَ بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ هَذَا عَنِّي وَعَمَّنْ لَمْ يُضَحِّ مِنْ أُمَّتِي."],"takhrij":"حسن: رواه أبوداود (2810)، والترمذي (1521)، والإمام أحمد (14895) كلهم عن قتيبة بن سعيد، حدثنا يعقوب بن عبدالرحمن، عن عمرو بن أبي عمرو، عن المطلب، عن جابر بن عبدالله فذكره.","grade":"حسن","chapter_ar":"باب من قال بجواز الأضحية عن الميّت","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2810), al-Tirmidhi (1521), and Imam Ahmad (14895).","chapter_en":"Whoever Said That Sacrificing on Behalf of the Deceased Is Permissible","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: I attended the Sacrifice prayer with the Messenger of Allah ﷺ at the prayer place. When he finished his sermon, he came down from his pulpit, and a ram was brought. The Messenger of Allah ﷺ slaughtered it with his own hand and said: “In the Name of Allah, and Allah is the Greatest. This is on behalf of me and whoever did not sacrifice from my nation.”"]},"buhuth":{"en":["As for sacrificing specifically on behalf of the deceased, it is not established that the Prophet ﷺ sacrificed on behalf of his uncle Hamzah ibn ʿAbd al-Muttalib, though he was among his closest relatives. Likewise, he did not sacrifice on behalf of his son Ibrahim, nor on behalf of his wife Khadijah. Nor is it established that any of the Companions sacrificed on behalf of their deceased relatives. However, if someone does sacrifice on behalf of the deceased, he should not eat any of it, because it is like charity given on behalf of the deceased."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2810,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1521},{"key":"ahmad","label":"الإمام أحمد","number":14895}],"full":1,"dr":1,"rep":[7204,11140]},{"num":7187,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُضَحِّي بِكَبْشَيْنِ وَأَنَا أُضَحِّي بِكَبْشَيْنِ."],"takhrij":"متفق عليه: رواه البخاري في الأضاحي (5553) عن آدم بن أبي إياس، حدثنا شعبة، حدثنا عبدالعزيز بن صهيب، قال: سعت أنس بن مالك قال فذكره.","grade":"متفق عليه","chapter_ar":"باب الأضحية بكبشين","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5553) and Muslim (1966).","chapter_en":"Sacrificing Two Rams","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Anas said: The Prophet ﷺ used to sacrifice two rams, and I sacrifice two rams."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5553,"lafz":true},{"key":"muslim","label":"مسلم","number":1966}],"full":1,"dr":1},{"num":7188,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِي يَوْمَ النَّحْرِ بِكَبْشَيْنِ أَمْلَحَيْنِ، فَذَبَحَ أَحَدَهُمَا فَقَالَ: هَذَا عَنْ مُحَمَّدٍ وَأَهْلِ بَيْتِهِ، وَذَبَحَ الآخَرَ وَقَالَ: هَذَا عَمَّنْ لَمْ يُضحِّ عَنْ أُمَّتِي."],"takhrij":"حسن: رواه أحمد (11051)، والبزار (1209-كشف) واللفظ له، والحاكم (4/228) من طرق عن عبدالعزيز بن محمد الدراوردي، ثنا رُبيح بن عبدالرحمن بن أبي سعيد الخدري، عن أبيه، عن جده، فذكره.","grade":"حسن","chapter_ar":"باب الأضحية بكبشين","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (11051), al-Bazzar (1209 — Kashf), with this wording, and al-Hakim (4/228).","chapter_en":"Sacrificing Two Rams","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that on the Day of Sacrifice, the Messenger of Allah ﷺ was brought two white-and-black rams. He slaughtered one and said: “This is on behalf of Muhammad and his household.” He slaughtered the other and said: “This is on behalf of those of my nation who did not sacrifice.”"]}},"tuhfa":{},"refs":[{"key":"bazzar","label":"البزار","number":1209},{"key":"hakim","label":"الحاكم","number":228},{"key":"ahmad","label":"مسند الإمام أحمد","number":11051,"n":11051,"lafz":true},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1209,"n":1209}],"full":1,"dr":1,"rep":[7185]},{"num":7189,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ أَوَّلَ مَا نَبْدَأُ بِهِ فِي يَوْمِنَا هَذَا أَنْ نُصَلِّيَ ثُمَّ نَرْجِعَ فَنَنْحَرَ، مَنْ فَعَلَهُ فَقَدْ أَصَابَ سُنَّتَنَا، وَمَنْ ذَبَحَ قَبْلُ فَإِنَّمَا هُوَ لَحْمٌ قَدَّمَهُ لأَهْلِهِ، لَيْسَ مِنَ النُّسُكِ فِي شَىْءٍ. فَقَامَ أَبُو بُرْدَةَ بْنُ نِيَارٍ وَقَدْ ذَبَحَ فَقَالَ إِنَّ عِنْدِي جَذَعَةً. فَقَالَ اذْبَحْهَا وَلَنْ تَجْزِيَ عَنْ أَحَدٍ بَعْدَكَ."],"takhrij":"متفق عليه: رواه البخاري في الأضاحي (5545)، ومسلم في الأضاحي (7:1961) كلاهما من طريق محمد بن بشار-وزاد مسلم-:ومحمد بن المثنى- حدثنا محمد بن جعفر غندر، حدثنا شعبة، عن زُبيد الإيامي، عن الشعبي، عن البراء فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في بداية وقت ذبح الأضحية","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5545) and Muslim (1961:7).","chapter_en":"What Has Been Reported Concerning the Beginning Time for Slaughtering the Sacrifice","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Al-Bara’ ibn ʿAzib said: The Prophet ﷺ said: “The first thing we begin with on this day of ours is that we pray, then we return and sacrifice. Whoever does that has followed our Sunnah. Whoever slaughtered before that, it is only meat he has offered to his family; it has nothing to do with the rite.” Abu Burdah ibn Niyar stood up, and he had already slaughtered. He said: “I have a young animal.” He said: “Slaughter it, but it will not suffice for anyone after you.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5545,"lafz":true},{"key":"muslim","label":"مسلم","number":7}],"full":1},{"num":7190,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ صَلَّى صَلاَتَنَا وَوَجَّهَ قِبْلَتَنَا وَنَسَكَ نُسُكَنَا فَلاَ يَذْبَحْ حَتَّى يُصَلِّيَ. فَقَالَ خَالِي يَا رَسُولَ اللَّهِ قَدْ نَسَكْتُ عَنِ ابْنٍ لِي. فَقَالَ ذَاكَ شَىْءٌ عَجَّلْتَهُ لأَهْلِكَ. فَقَالَ إِنَّ عِنْدِي شَاةً خَيْرٌ مِنْ شَاتَيْنِ قَالَ ضَحِّ بِهَا فَإِنَّهَا خَيْرُ نَسِيكَةٍ."],"takhrij":"متفق عليه: رواه البخاري في الأضاحي (5563)، من طريق أبي عوانة- ومسلم في الأضاحي (6:1960) من طريق زكريا- كلاهما عن فراس، عن عامر الشعبي، عن البراء فذكره والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في بداية وقت ذبح الأضحية","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5563) and Muslim (1960:6). The wording is from Muslim.","chapter_en":"What Has Been Reported Concerning the Beginning Time for Slaughtering the Sacrifice","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Al-Bara’ said: The Messenger of Allah ﷺ said: “Whoever prays our prayer, faces our direction of prayer, and performs our rite, must not slaughter until he has prayed.” My maternal uncle said: “O Messenger of Allah, I already performed the rite on behalf of a son of mine.” He said: “That is something you hastened for your family.” He said: “I have a sheep that is better than two sheep.” He said: “Sacrifice it, for it is an excellent sacrifice.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5563,"lafz":true},{"key":"muslim","label":"مسلم","number":6}],"full":1},{"num":7191,"demo":false,"sanad":"","matn":["عن جندب بْنِ سُفْيَانَ البجلي قَالَ شَهِدْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ النَّحْرِ فَقَالَ مَنْ ذَبَحَ قَبْلَ أَنْ يُصَلِّيَ فَلْيُعِدْ مَكَانَهَا أُخْرَى، وَمَنْ لَمْ يَذْبَحْ فَلْيَذْبَحْ."],"takhrij":"متفق عليه: رواه البخاري في الأضاحي (5562)، ومسلم في الأضاحي (3:1960) كلاهما من طريق شعبة، حدثنا الأسود بن قيس، سمعت جندب ابن سفيان البجلي فذكره.","grade":"متفق عليه","chapter_ar":"باب من ذبح قبل الصلاة فليذبح مكانها أخرى","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5562) and Muslim (1960:3).","chapter_en":"Whoever Slaughtered Before the Prayer Should Slaughter Another in Its Place","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["Jundab ibn Sufyan al-Bajali said: I witnessed the Prophet ﷺ on the Day of Sacrifice, and he said: “Whoever slaughtered before praying should slaughter another in its place, and whoever has not slaughtered should slaughter.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5562,"lafz":true},{"key":"muslim","label":"مسلم","number":3}],"full":1},{"num":7192,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ ذَبَحَ قَبْلَ الصَّلاَةِ فَلْيُعِدْ."],"takhrij":"متفق عليه: رواه البخاري في الأضاحي (5561)، ومسلم في الأضاحي (1962) كلاهما من حديث إسماعيل بن إبراهيم (هو ابن علية)، عن أيوب، عن محمد (هو ابن سيرين)، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب من ذبح قبل الصلاة فليذبح مكانها أخرى","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5561) and Muslim (1962).","chapter_en":"Whoever Slaughtered Before the Prayer Should Slaughter Another in Its Place","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["Anas narrated from the Prophet ﷺ that he said: “Whoever slaughtered before the prayer should repeat it…” the hadith."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5561,"lafz":true},{"key":"muslim","label":"مسلم","number":1962,"n":5090}],"full":1},{"num":7193,"demo":false,"sanad":"","matn":["عن جابر قَالَ: صَلَّى بِنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ النَّحْرِ بِالْمَدِينَةِ فَتَقَدَّمَ رِجَالٌ فَنَحَرُوا وَظَنُّوا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ نَحَرَ فَأَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ كَانَ نَحَرَ قَبْلَهُ أَنْ يُعِيدَ بِنَحْرٍ آخَرَ وَلاَ يَنْحَرُوا حَتَّى يَنْحَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه مسلم في الأضاحي (14:1964) عن محمد بن حاتم، حدثنا محمد بن بكر، أخبرنا ابن جريج، أخبرني أبوالزبير، أنه سمع جابر بن عبدالله يقول: فذكره.","grade":"صحيح","chapter_ar":"باب من ذبح قبل الصلاة فليذبح مكانها أخرى","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1964:14).","chapter_en":"Whoever Slaughtered Before the Prayer Should Slaughter Another in Its Place","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["Jabir said: The Prophet ﷺ led us in prayer on the Day of Sacrifice in Madinah. Some men went ahead and slaughtered, thinking that the Prophet ﷺ had already slaughtered. So the Prophet ﷺ ordered whoever had slaughtered before him to repeat with another slaughter, and that they should not slaughter until the Prophet ﷺ had slaughtered."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":14,"lafz":true}],"full":1,"dr":1},{"num":7194,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّهُ قَالَ فِي يَوْمِ أَضْحَى: مَنْ كَانَ ذَبَحَ، أَحْسِبُهُ قَالَ: قَبْلَ الصَّلاةِ، فَلْيَعِدْ ذِبْحَتَهُ."],"takhrij":"حسن: رواه البزار (1205- كشف الأستار) عن محمد بن مرداس الأنصاري، ثنا بكر بن سليمان، ثنا محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب من ذبح قبل الصلاة فليذبح مكانها أخرى","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzar (1205 — Kashf al-Astar).","chapter_en":"Whoever Slaughtered Before the Prayer Should Slaughter Another in Its Place","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said on a Day of Sacrifice: “Whoever had slaughtered — I think he said: before the prayer — should repeat his slaughter.”"]}},"tuhfa":{},"refs":[{"key":"bazzar","label":"البزار","number":1205,"lafz":true},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1205,"n":1205}],"full":1,"dr":1},{"num":7195,"demo":false,"sanad":"","matn":["عن أبي الخير أن رجلا من الأنصار حدثه أن ناسا سمعوا رجّةً بالمدينة يوم الأضحى، فظنوا أن رسول الله صلى الله عليه وسلم قد صلى فذبحوا، فأرسلوا رجلا إلى رسول الله صلى الله عليه وسلم فوجدوا رسول الله صلى الله عليه وسلم قد أضجع أضحيته يذبَحُها فقال رسول الله صلى الله عليه وسلم: أعِنِّي على أضحيتي فأعانه، ثم قال له يا رسول الله صلى الله عليه وسلم: إن ناسا ظنوا أنك قد صليتَ فذبحوا ضحاياهم فما ترى في ذلك؟ قال: فليشتروا غيرها ثم ليذبحوها."],"takhrij":"صحيح: رواه الحارث بن أبي أسامة (403-بغية الباحث) عن يونس بن محمد المؤدب، ثنا ليث، عن يزيد بن أبي حبيب، عن أبي الخير به، فذكره.","grade":"صحيح","chapter_ar":"باب من ذبح قبل الصلاة فليذبح مكانها أخرى","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Harith ibn Abi Usamah (403 — Bughyat al-Bahith).","chapter_en":"Whoever Slaughtered Before the Prayer Should Slaughter Another in Its Place","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["Abu al-Khayr narrated that a man from the Ansar told him that some people heard a commotion in Madinah on the Day of Sacrifice, so they thought that the Messenger of Allah ﷺ had already prayed, and they slaughtered. They sent a man to the Messenger of Allah ﷺ, and he found the Messenger of Allah ﷺ laying down his sacrifice to slaughter it. The Messenger of Allah ﷺ said: “Help me with my sacrifice.” So he helped him. Then he said to him: “O Messenger of Allah, some people thought that you had already prayed, so they slaughtered their sacrifices. What do you think about that?” He said: “Let them buy others and then slaughter them.”"]}},"tuhfa":{},"refs":[{"key":"sh13160","label":"الحارث بن أبي أسامة","number":403,"lafz":true}],"full":1,"dr":1},{"num":7196,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر قـال: كان رسول الله صلى الله عليه وسلم يذبح، وينحر بالمصلّى."],"takhrij":"صحيح: رواه البخاري في الأضاحي (5552) عن يحيى بن بكير، حدثنا الليث، عن كثير بن فَرْقد، عن نافع، أن ابن عمر أخبره فذكره.","grade":"صحيح","chapter_ar":"باب ذبح النبي ﷺ الأضحية بالمصلى","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5552).","chapter_en":"The Prophet ﷺ Slaughtering the Sacrificial Animal at the Prayer Place","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":20,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: “The Messenger of Allah ﷺ used to slaughter sheep and camels at the prayer place.”"]},"buhuth":{"en":["The Eid prayer place was in an open area outside the mosque. It is said that it was near what is today the Mosque of al-Ghamamah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5552,"lafz":true}],"full":1,"dr":1},{"num":7197,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ ضَحَّى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِكَبْشَيْنِ أَمْلَحَيْنِ، فَرَأَيْتُهُ وَاضِعًا قَدَمَهُ عَلَى صِفَاحِهِمَا يُسَمِّي وَيُكَبِّرُ، فَذَبَحَهُمَا بِيَدِهِ."],"takhrij":"متفق عليه: رواه البخاري في الأضاحي (5558)، ومسلم في الأضاحي (18:1966) كلاهما من طريق شعبة بن الحجاج، عن قتادة، عن أنس بن مالك قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب استحباب مباشرة ذبح الأضحية بيد صاحبها","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5558) and Muslim (1966:18).","chapter_en":"The Recommendation That the Owner Personally Slaughter His Sacrifice with His Own Hand","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet ﷺ sacrificed two white-and-black rams. I saw him placing his foot on their sides, mentioning the Name of Allah and declaring Allah the Greatest, and he slaughtered them with his own hand."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5558,"lafz":true},{"key":"muslim","label":"مسلم","number":18}],"full":1,"rep":[12800]},{"num":7198,"demo":false,"sanad":"","matn":["عَنْ شَدَّادِ بْنِ أَوْسٍ، قَالَ ثِنْتَانِ حَفِظْتُهُمَا عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِنَّ اللَّهَ كَتَبَ الإِحْسَانَ عَلَى كُلِّ شَىْءٍ فَإِذَا قَتَلْتُمْ فَأَحْسِنُوا الْقِتْلَةَ وَإِذَا ذَبَحْتُمْ فَأَحْسِنُوا الذَّبْحَ وَلْيُحِدَّ أَحَدُكُمْ شَفْرَتَهُ فَلْيُرِحْ ذَبِيحَتَهُ."],"takhrij":"صحيح: رواه مسلم في الصيد والذبائح (57:1955) عن أبي بكر بن أبي شيبة، حدثنا إسماعيل ابنُ علية، عن خالد الحذاء، عن أبي قِلابة، عن أبي الأشعث، عن شدّاد بن أوس، فذكره.","grade":"صحيح","chapter_ar":"باب الأمر بإحسان الذبح وتحديد الشَّفْرَة والمُدْية","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1955:57).","chapter_en":"The Command to Slaughter Well and Sharpen the Blade and Knife","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Shaddad ibn Aws said: There are two things I memorized from the Messenger of Allah ﷺ. He said: “Allah has prescribed excellence in everything. So when you kill, kill well; and when you slaughter, slaughter well. Let one of you sharpen his blade and give comfort to his slaughtered animal.”"]},"buhuth":{"en":["The blade is the sharpened, edged piece of iron, like the edge of a sword or knife."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":57,"lafz":true}],"full":1,"dr":1},{"num":7199,"demo":false,"sanad":"","matn":["عن أنس قال: قال رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إذَا حَكَمْتُمْ فاعْدِلُوْا، وإذَا قَتَلْتُمْ فأَحْسِنُوْا، فإنّ اللهَ عزَّوجلَّ مُحْسِنٌ، يُحِبُّ المُحْسِنِيْنَ."],"takhrij":"حسن: رواه ابنُ أبي عاصم في الديات (184)، والطبراني في الأوسط –مجمع البحرين (2552)، وأبو نعيم في أخبار أصبهان (2/113) كلهم من طرقٍ عن محمد بن بلال، حدثنا عمران القطّان، عن قتادة، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب الأمر بإحسان الذبح وتحديد الشَّفْرَة والمُدْية","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abi ʿAsim in al-Diyat (184), al-Tabarani in al-Awsat — Majmaʿ al-Bahrayn (2552), and Abu Nuʿaym in Akhbar Isbahan (2/113).","chapter_en":"The Command to Slaughter Well and Sharpen the Blade and Knife","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ said: “When you judge, be just; and when you kill, do it well. For Allah, the Mighty and Majestic, is Excellent and loves those who do excellence.”"]}},"tuhfa":{},"refs":[{"key":"rb280","label":"ابن أبي عاصم في الديات","number":184,"lafz":true},{"key":"sh1352","label":"الطبراني في الأوسط — مجمع البحرين","number":2552},{"key":"sh1714","label":"أبو نعيم في أخبار أصبهان","number":2},{"key":"sh28171","label":"الطبراني في الاوسط –مجمع البحرين","number":2552}],"full":1,"dr":1},{"num":7200,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِكَبْشٍ أَقْرَنَ يَطَأُ فِي سَوَادٍ وَيَبْرُكُ فِي سَوَادٍ وَيَنْظُرُ فِي سَوَادٍ فَأُتِيَ بِهِ لِيُضَحِّيَ بِهِ فَقَالَ لَهَا يَا عَائِشَةُ هَلُمِّي الْمُدْيَةَ. ثُمَّ قَالَ اشْحَذِيهَا بِحَجَرٍ. فَفَعَلَتْ ثُمَّ أَخَذَهَا وَأَخَذَ الْكَبْشَ فَأَضْجَعَهُ ثُمَّ ذَبَحَهُ ثُمَّ قَالَ بِاسْمِ اللَّهِ اللَّهُمَّ تَقَبَّلْ مِنْ مُحَمَّدٍ وَآلِ مُحَمَّدٍ وَمِنْ أُمَّةِ مُحَمَّدٍ. ثُمَّ ضَحَّى بِهِ."],"takhrij":"صحيح: رواه مسلم في الأضاحي (19:1967) عن هارون بن معروف، حدثنا عبدالله بن وهب، قال قال حيوة: أخبرني أبو صخْر، عن يزيد بن قُسيْط، عن عروة بن الزبير، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب الأمر بإحسان الذبح وتحديد الشَّفْرَة والمُدْية","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1967:19).","chapter_en":"The Command to Slaughter Well and Sharpen the Blade and Knife","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["ʿA’ishah narrated that the Messenger of Allah ﷺ ordered a horned ram that walked on black, knelt on black, and looked through black. It was brought to him so he could sacrifice it. He said to her: “O ʿA’ishah, bring the knife.” Then he said: “Sharpen it with a stone.” She did so. Then he took it and took the ram, laid it down, then slaughtered it and said: “In the Name of Allah. O Allah, accept this from Muhammad, the family of Muhammad, and the nation of Muhammad.” Then he sacrificed it."]},"buhuth":{"en":["His statement, “Sharpen it,” means: make it sharp."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":19,"lafz":true}],"full":1,"dr":1,"rep":[7180,7203,11139]},{"num":7201,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: مَرَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى رَجُلٍ وَاضِعٍ رِجْلَهُ عَلَى صَفْحَةِ شَاةٍ وَهُوَ يُحِدُّ شَفْرَتَهُ وَهِيَ تَلْحَظُ إِلَيْهِ بِبَصَرِهَا، فَقَالَ: أَفَلَا قَبْلَ هَذَا تُرِيدُ أَنْ تُمِيتَهَا مَوْتَتَيْنِ."],"takhrij":"صحيح: رواه الطبراني في الكبير (11916)، والأوسط (3614)، والبيهقي (9/280) من طريق يوسف بن عدي، حدثني عبدالرحيم بن سليمان، عن عاصم الأحول، عن عكرمة، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب الأمر بإحسان الذبح وتحديد الشَّفْرَة والمُدْية","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tabarani in al-Kabir (11916), al-Awsat (3614), and al-Bayhaqi (9/280).","chapter_en":"The Command to Slaughter Well and Sharpen the Blade and Knife","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ passed by a man who had placed his foot on the side of a sheep while he was sharpening his blade, and the sheep was looking at him with its eyes. He said: “Could you not have done this before? Or do you want to make it die twice?”"]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":11916,"lafz":true},{"key":"sh28171","label":"الأوسط","number":3614,"n":3576},{"key":"kubrabayhaqi","label":"البيهقي","number":280},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":19141,"n":19299}],"full":1,"dr":1},{"num":7202,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ ضَحَّى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِكَبْشَيْنِ أَمْلَحَيْنِ أَقْرَنَيْنِ، ذَبَحَهُمَا بِيَدِهِ، وَسَمَّى وَكَبَّرَ وَوَضَعَ رِجْلَهُ عَلَى صِفَاحِهِمَا.","وفي لفظ: قال: باسم الله، والله أكبر."],"takhrij":"متفق عليه: رواه البخاري في الأضاحي (5565)، ومسلم في الأضاحي (17:1966) كلاهما عن قتيبة بن سعيد، حدثنا أبو عوانة، عن قتادة، عن أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب ما يقال عند ذبح الأضحية","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5565) and Muslim (1966:17).","chapter_en":"What Is Said When Slaughtering the Sacrifice","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":23,"content":{"translation":{"en":["Anas said: The Prophet ﷺ sacrificed two white-and-black, horned rams. He slaughtered them with his own hand, mentioned the Name of Allah, declared Allah the Greatest, and placed his foot on their sides. In one wording, he said: “In the Name of Allah, and Allah is the Greatest.”"]},"buhuth":{"en":["His statement, “their sides,” means the side of the neck. He did this so that the animal would be steadier and easier to control, so it would not move its head in a way that would prevent him from completing the slaughter or harm him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5565,"lafz":true},{"key":"muslim","label":"مسلم","number":17}],"full":1,"dr":1},{"num":7203,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِكَبْشٍ أَقْرَنَ يَطَأُ فِي سَوَادٍ وَيَبْرُكُ فِي سَوَادٍ وَيَنْظُرُ فِي سَوَادٍ فَأُتِيَ بِهِ لِيُضَحِّيَ بِهِ فَقَالَ لَهَا يَا عَائِشَةُ هَلُمِّي الْمُدْيَةَ. ثُمَّ قَالَ اشْحَذِيهَا بِحَجَرٍ. فَفَعَلَتْ ثُمَّ أَخَذَهَا وَأَخَذَ الْكَبْشَ فَأَضْجَعَهُ ثُمَّ ذَبَحَهُ ثُمَّ قَالَ بِاسْمِ اللَّهِ اللَّهُمَّ تَقَبَّلْ مِنْ مُحَمَّدٍ وَآلِ مُحَمَّدٍ وَمِنْ أُمَّةِ مُحَمَّدٍ. ثُمَّ ضَحَّى بِهِ."],"takhrij":"صحيح: رواه مسلم في الأضاحي (19:1967) عن هارون بن معروف، حدثنا عبدالله بن وهب، قال قال حيوة: أخبرني أبو صخْر، عن يزيد بن قُسيْط، عن عروة بن الزبير، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب ما يقال عند ذبح الأضحية","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1967:19).","chapter_en":"What Is Said When Slaughtering the Sacrifice","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":23,"content":{"translation":{"en":["ʿA’ishah narrated that the Messenger of Allah ﷺ ordered a horned ram that walked on black, knelt on black, and looked through black. It was brought to him so he could sacrifice it. He said to her: “O ʿA’ishah, bring the knife.” Then he said: “Sharpen it with a stone.” She did so. Then he took it and took the ram, laid it down, then slaughtered it and said: “In the Name of Allah. O Allah, accept this from Muhammad, the family of Muhammad, and the nation of Muhammad.” Then he sacrificed it."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":19,"lafz":true}],"full":1,"rep":[7180,7200,11139]},{"num":7204,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ شَهِدْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الأَضْحَى بِالْمُصَلَّى فَلَمَّا قَضَى خُطْبَتَهُ نَزَلَ مِنْ مِنْبَرِهِ وَأُتِيَ بِكَبْشٍ فَذَبَحَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ وَقَالَ بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ هَذَا عَنِّي وَعَمَّنْ لَمْ يُضَحِّ مِنْ أُمَّتِي."],"takhrij":"حسن: رواه أبوداود (2810)، والترمذي (1521)، والإمام أحمد (14895) كلهم عن قتيبة بن سعيد، حدثنا يعقوب بن عبدالرحمن، عن عمرو بن أبي عمرو، عن المطلب، عن جابر بن عبدالله فذكره.","grade":"حسن","chapter_ar":"باب ما يقال عند ذبح الأضحية","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2810), al-Tirmidhi (1521), and Imam Ahmad (14895).","chapter_en":"What Is Said When Slaughtering the Sacrifice","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":23,"content":{"translation":{"en":["Jabir said: I attended the Sacrifice prayer with the Messenger of Allah ﷺ at the prayer place. When he finished his sermon, he came down from his pulpit, and a ram was brought. The Messenger of Allah ﷺ slaughtered it with his own hand and said: “In the Name of Allah, and Allah is the Greatest. This is on behalf of me and whoever did not sacrifice from my nation.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2810,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1521},{"key":"ahmad","label":"الإمام أحمد","number":14895}],"full":1,"dr":1,"rep":[7186,11140]},{"num":7205,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: ذَكَاةُ الْجَنِينِ ذَكَاةُ أُمِّهِ."],"takhrij":"حسن: رواه الإمام أحمد (11343) عن أبي عُبيدة، حدثنا يونس بن أبي إسحاق، عن أبي الودّاك جبر بن نوف، عن أبي سعيد فذكره.","grade":"حسن","chapter_ar":"باب ذكاة الجنين ذكاة أمِّه","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (11343), and authenticated by Ibn Hibban (5889).","chapter_en":"The Slaughter of the Fetus Is the Slaughter of Its Mother","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":24,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated from the Prophet ﷺ that he said: “The slaughter of the fetus is the slaughter of its mother.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":11343,"lafz":true},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":5889},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4102,"n":4149}],"full":1,"dr":1,"rep":[7294]},{"num":7206,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ ذَكَاةُ الْجَنِينِ ذَكَاةُ أُمِّهِ."],"takhrij":"حسن: رواه أبوداود (2828) عن محمد بن يحيى بن فارس، حدثني إسحاق بن إبراهيم بن راهويه، حدثنا عتاب بن بشير، حدثنا عبيدالله بن أبي زياد القداح المكي، عن أبي الزبير، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب ذكاة الجنين ذكاة أمِّه","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2828).","chapter_en":"The Slaughter of the Fetus Is the Slaughter of Its Mother","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":24,"content":{"translation":{"en":["Jabir ibn ʿAbdullah narrated from the Messenger of Allah ﷺ that he said: “The slaughter of the fetus is the slaughter of its mother.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2828,"lafz":true}],"full":1,"dr":1},{"num":7207,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الحصيب قَالَ: كانَ النبيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ يَخْرُجُ يومَ الْفِطْرِ حَتَّى يَطْعَمَ، وَلاَ يَطْعَمُ يومَ الأَضْحَى حتّى يُصلِّي."],"takhrij":"حسن: رواه الترمذي (542)، وابن ماجه (1756)، وابن خزيمة (1426)، وابن حبان (2812)، والحاكم (1/294) كلهم من طريق ثَوَاب بن عُتْبة المَهري، عن عبدالله بن بريدة، عن أبيه فذكره. واللفظ للترمذي.","grade":"حسن","chapter_ar":"باب ترك الأكل يوم النحر حتى يُصلى","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (542), Ibn Majah (1756), Ibn Khuzaymah (1426), Ibn Hibban (2812), and al-Hakim (1088).","chapter_en":"Refraining from Eating on the Day of Sacrifice Until the Prayer Is Performed","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":25,"content":{"translation":{"en":["Buraydah ibn al-Husayb said: The Prophet ﷺ would not go out on the Day of Breaking Fast until he had eaten, and he would not eat on the Day of Sacrifice until he had prayed."]},"buhuth":{"en":["In the narration of al-Bayhaqi (3/283), there is an additional wording: “When he returned, he would eat from the liver of his sacrifice,” but this addition is not authentic. The statement of some scholars about eating the liver is understood to mean that it cooks faster and is lighter on the stomach, not that it is specifically recommended.","As for one who eats on the Day of Sacrifice before the sacrifice, there is no harm in that, as shown in the following hadith."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":542,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":1756,"n":1754},{"key":"ibnkhuzaymah","label":"ابن خزيمة","number":1426},{"key":"ibnhibban","label":"ابن حبان","number":2812},{"key":"hakim","label":"المستدرك على الصحيحين","number":1088,"n":1081}],"full":1,"dr":1},{"num":7208,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ خَطَبَنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الأَضْحَى بَعْدَ الصَّلاَةِ فَقَالَ مَنْ صَلَّى صَلاَتَنَا وَنَسَكَ نُسُكَنَا فَقَدْ أَصَابَ النُّسُكَ، وَمَنْ نَسَكَ قَبْلَ الصَّلاَةِ فَإِنَّهُ قَبْلَ الصَّلاَةِ، وَلاَ نُسُكَ لَهُ. فَقَالَ أَبُو بُرْدَةَ بْنُ نِيَارٍ خَالُ الْبَرَاءِ يَا رَسُولَ اللَّهِ، فَإِنِّي نَسَكْتُ شَاتِي قَبْلَ الصَّلاَةِ، وَعَرَفْتُ أَنَّ الْيَوْمَ يَوْمُ أَكْلٍ وَشُرْبٍ، وَأَحْبَبْتُ أَنْ تَكُونَ شَاتِي أَوَّلَ مَا يُذْبَحُ فِي بَيْتِي، فَذَبَحْتُ شَاتِي وَتَغَدَّيْتُ قَبْلَ أَنْ آتِيَ الصَّلاَةَ. قَالَ شَاتُكَ شَاةُ لَحْمٍ. قَالَ يَا رَسُولَ اللَّهِ، فَإِنَّ عِنْدَنَا عَنَاقًا لَنَا جَذَعَةً هِيَ أَحَبُّ إِلَىَّ مِنْ شَاتَيْنِ، أَفَتَجْزِي عَنِّي قَالَ نَعَمْ، وَلَنْ تَجْزِيَ عَنْ أَحَدٍ بَعْدَكَ."],"takhrij":"متفق عليه: رواه البخاري في العيدين (955) عن عثمان، حدثنا جرير، عن منصور، عن الشعبي، عن البراء بن عازب قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ترك الأكل يوم النحر حتى يُصلى","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (955) and Muslim (1961).","chapter_en":"Refraining from Eating on the Day of Sacrifice Until the Prayer Is Performed","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":25,"content":{"translation":{"en":["Al-Bara’ ibn ʿAzib said: The Prophet ﷺ addressed us on the Day of Sacrifice after the prayer and said: “Whoever prays our prayer and performs our rite has performed the rite correctly. Whoever performs the rite before the prayer, then it is before the prayer, and he has no rite.” Abu Burdah ibn Niyar, the maternal uncle of al-Bara’, said: “O Messenger of Allah, I sacrificed my sheep before the prayer. I knew that today is a day of eating and drinking, and I wanted my sheep to be the first thing slaughtered in my house, so I slaughtered my sheep and ate lunch before coming to the prayer.” He said: “Your sheep is only a sheep for meat.” He said: “O Messenger of Allah, we have a young female goat that is more beloved to me than two sheep. Will it suffice for me?” He said: “Yes, but it will not suffice for anyone after you.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":955,"lafz":true},{"key":"muslim","label":"مسلم","number":1961}],"full":1,"dr":1},{"num":7209,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ النَّحْرِ مَنْ كَانَ ذَبَحَ قَبْلَ الصَّلاَةِ فَلْيُعِدْ. فَقَامَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ هَذَا يَوْمٌ يُشْتَهَى فِيهِ اللَّحْمُ ـ وَذَكَرَ جِيرَانَهُ ـ وَعِنْدِي جَذَعَةٌ خَيْرٌ مِنْ شَاتَىْ لَحْمٍ. فَرَخَّصَ لَهُ فِي ذَلِكَ، فَلاَ أَدْرِي أَبَلَغَتِ الرُّخْصَةُ مَنْ سِوَاهُ أَمْ لاَ، ثُمَّ انْكَفَأَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى كَبْشَيْنِ فَذَبَحَهُمَا، وَقَامَ النَّاسُ إِلَى غُنَيْمَةٍ فَتَوَزَّعُوهَا أَوْ قَالَ فَتَجَزَّعُوهَا."],"takhrij":"متفق عليه: رواه البخاري في الأضاحي (5549)، ومسلم في الأضاحي (10:1962) كلاهما من طريق إبراهيم ابن علية، عن أيوب، عن محمد بن سيرين، عن أنس، فذكره.","grade":"متفق عليه","chapter_ar":"باب الأكل والإهداء والتصدّق من لحوم الأضاحي","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5549) and Muslim (1962:10).","chapter_en":"Eating, Giving as Gifts, and Giving Charity from the Meat of the Sacrificial Animals","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet ﷺ said on the Day of Sacrifice: “Whoever slaughtered before the prayer should repeat it.” A man stood and said: “O Messenger of Allah, this is a day on which meat is desired” — and he mentioned his neighbors — “and I have a young goat better than two sheep for meat.” So he gave him a concession in that. I do not know whether the concession extended to anyone besides him or not. Then the Prophet ﷺ turned to two rams and slaughtered them, and the people went to a small flock and divided it among themselves — or he said: they separated it into portions."]},"intro":{"ar":["قال اللّٰه تعالى:","( وَالْبُدْنَ جَعَلْنَاهَا لَكُمْ مِن شَعَائِرِ اللَّهِ لَكُمْ فِيهَا خَيْرٌ فَاذْكُرُوا اسْمَ ٱللَّهِ عَلَيْهَا صَوَافَّ فَإِذَا وَجَبَتْ جُنُوبُهَا فَكُلُوا مِنْهَا وَأَطْعِمُوا الْقَانِعَ وَالْمُعْتَرَّ كَذَٰلِكَ سَخَّرْنَاهَا لَكُمْ لَعَلَّكُمْ تَشْكُرُونَ ) [سورة الحج: ٣٦].","وقال تعالى:","( فَكُلُوا مِنْهَا وَأَطْعِمُوا الْبَائِسَ الْفَقِيرَ ) [الحج: ٢٨].","القانع: السائل، يقال: قنع قُنوعا إذا سأل. والمعتر: الذي يعتريك أي يتعرض لك لتُطعمه، ولا يسأل. الصنف الثالث: هو الفقير المسكين."],"en":["Allah the Exalted said:","“And the camels and cattle We have appointed for you as among the symbols of Allah; for you therein is good. So mention the Name of Allah over them while they are lined up. Then when they fall on their sides, eat from them and feed the one who asks and the one who presents himself without asking. Thus have We subjected them to you so that you may be grateful.” [Surah al-Hajj: 36]","And He said:","“So eat from them and feed the miserable poor.” [al-Hajj: 28]","The “one who asks” means the person who asks; it is said in Arabic that a person “qanaʿa” when he asks. The “one who presents himself without asking” means the person who comes to you or presents himself so that you may feed him, without directly asking. The third category is the poor, needy person."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5549,"lafz":true},{"key":"muslim","label":"مسلم","number":10}],"full":1},{"num":7210,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّهُمْ ذَبَحُوا شَاةً فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا بَقِيَ مِنْهَا. قَالَتْ مَا بَقِيَ مِنْهَا إِلاَّ كَتِفُهَا. قَالَ بَقِيَ كُلُّهَا غَيْرَ كَتِفِهَا."],"takhrij":"صحيح: رواه الترمذي (2470)، وأحمد (24240) من طريق يحيى (هو ابن سعيد القطان)، عن سفيان (هو الثوري)، عن أبي إسحاق (هو السبيعي)، عن أبي ميسرة ( هو عمرو بن شرحبيل الهمداني)، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب الأكل والإهداء والتصدّق من لحوم الأضاحي","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (2470) and Ahmad (24240).","chapter_en":"Eating, Giving as Gifts, and Giving Charity from the Meat of the Sacrificial Animals","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["ʿA’ishah narrated that they slaughtered a sheep, and the Prophet ﷺ said: “What remains of it?” She said: “Nothing remains of it except its shoulder.” He said: “All of it remains except its shoulder.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":2470,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":24240,"n":24240}],"full":1,"dr":1,"rep":[4159]},{"num":7211,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن زَيْدٍ، أَنَّهُ شَهِدَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ الْمَنْحَرِ-وهو رَجُلٌ مِنَ الْأَنْصَارِ – فَقَسَمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ضَحَايَا، فَلَمْ يُصِبْه وَلَا صَاحِبَهُ شَيْءٌ، وَحَلَقَ رَأْسَهُ فِي ثَوْبِهِ، فَأَعْطَاهُ وَقَسَمَ مِنْهُ عَلَى رِجَالٍ، وقلَّم أَظْفَارَهُ فَأَعْطَاهُ صَاحِبَهُ، فَإِنَّ شَعْرَهُ عِنْدَنَا لمَخْضُوبٌ بِالْحِنَّاءِ وَالْكَتَمِ."],"takhrij":"صحيح: رواه الإمام أحمد (16475)، والبيهقي (1/25) من طريق أبان العطار، عن يحيى بن أبي كثير، أن أباسلمة حدثه أن محمد بن عبدالله بن زيد أخبره، عن أبيه، فذكره.","grade":"صحيح","chapter_ar":"باب الأكل والإهداء والتصدّق من لحوم الأضاحي","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (16475) and al-Bayhaqi (1/25).","chapter_en":"Eating, Giving as Gifts, and Giving Charity from the Meat of the Sacrificial Animals","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["ʿAbdullah ibn Zayd narrated that he and a man from the Ansar witnessed the Prophet ﷺ at the slaughtering place. The Messenger of Allah ﷺ distributed sacrificial animals, but neither he nor his companion received anything. He shaved his head into his garment, then gave it and distributed some of it among men. He trimmed his nails and gave them to his companion. His hair is with us, dyed with henna and katam."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":16475,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":1}],"full":1,"dr":1},{"num":7212,"demo":false,"sanad":"","matn":["عَنْ أَبِي عُبَيْدٍ مولى ابْنِ أزهر أَنَّهُ شهِد الْعِيدَ مَعَ عُمَرَ بْنِ الْخَطَّابِ قَالَ: ثُمَّ صَلَّيْتُ مَعَ عَلِيِّ بْنِ أَبِي طَالِبٍ قَالَ: فَصَلَّى لَنَا قَبْلَ الْخُطْبَةِ، ثُمَّ خَطَبَ النَّاسَ فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ نَهَاكُمْ أَنْ تَأْكُلُوا لُحُومَ نُسُكِكُمْ فَوْقَ ثَلاَثِ لَيَالٍ فَلاَ تَأْكُلُوا."],"takhrij":"متفق عليه: رواه البخاري في الأضاحي (5573)، ومسلم في الأضاحي (25:1969) كلاهما من طريق يونس (هو ابن يزيد الأيلي)، عن ابن شهاب، حدثني أبو عبيد مولى ابن أزهر فذكره واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن ادّخار لحوم الأضاحي فوق ثلاثة أيام","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5573) and Muslim (1969:25). The wording is from Muslim.","chapter_en":"The Prohibition of Storing the Meat of Sacrificial Animals for More Than Three Days","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":27,"content":{"translation":{"en":["Abu ʿUbayd, the freedman of Ibn Azhar, narrated that he attended the Eid with ʿUmar ibn al-Khattab. He said: Then I prayed with ʿAli ibn Abi Talib. He prayed before the sermon, then addressed the people and said: “The Messenger of Allah ﷺ forbade you from eating the meat of your sacrificial animals for more than three nights, so do not eat it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5573,"lafz":true},{"key":"muslim","label":"مسلم","number":25}],"full":1,"dr":1},{"num":7213,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ تُؤْكَلَ لُحُومُ الأَضَاحِي بَعْدَ ثَلاَثٍ.","قال سالم : فكان ابن عمر لايأكل لحوم الأضاحي فوق ثلاث.","وفي رواية: وكان عبدالله يأكل بالزيت حين ينفر من منى من أجل لحوم الهدي."],"takhrij":"متفق عليه: رواه البخاري في الأضاحي (5574) من طريق ابن أخي ابن شهاب-، ومسلم في الأضاحي (27:1970) من طريق معمر- كلاهما عن الزهري، عن سالم، عن ابن عمر. واللفظ لمسلم. والرواية الأخرى للبخاري.","grade":"متفق عليه","chapter_ar":"باب النهي عن ادّخار لحوم الأضاحي فوق ثلاثة أيام","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5574) and Muslim (1970:27). The wording is from Muslim.","chapter_en":"The Prohibition of Storing the Meat of Sacrificial Animals for More Than Three Days","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":27,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ forbade eating the meat of sacrificial animals after three days. Salim said: Ibn ʿUmar would not eat the meat of sacrificial animals for more than three days. In another narration: ʿAbdullah would eat with oil when he departed from Mina because of the meat of sacrificial animals."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5574,"lafz":true},{"key":"muslim","label":"مسلم","number":27}],"full":1},{"num":7214,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتِ الضَّحِيَّةُ كُنَّا نُمَلِّحُ مِنْهُ، فَنَقْدَمُ بِهِ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْمَدِينَةِ فَقَالَ لاَ تَأْكُلُوا إِلاَّ ثَلاَثَةَ أَيَّامٍ. وَلَيْسَتْ بِعَزِيمَةٍ، وَلَكِنْ أَرَادَ أَنْ يُطْعِمَ مِنْهُ وَاللَّهُ أَعْلَمُ."],"takhrij":"صحيح: رواه البخاري في الأضاحي (5570) عن إسماعيل بن عبدالله قال: حدثني أخي، عن سليمان، عن يحيى بن سعيد، عن عمرة بنت عبدالرحمن، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب النهي عن ادّخار لحوم الأضاحي فوق ثلاثة أيام","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5570).","chapter_en":"The Prohibition of Storing the Meat of Sacrificial Animals for More Than Three Days","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":27,"content":{"translation":{"en":["ʿA’ishah said: We used to salt some of the sacrificial meat and bring it to the Prophet ﷺ in Madinah. He said: “Do not eat it except for three days.” But this was not a strict ruling; rather, he wanted us to feed others from it — and Allah knows best."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5570,"lafz":true}],"full":1},{"num":7215,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ لاَ يَأْكُلْ أَحَدٌ مِنْ لَحْمِ أُضْحِيَّتِهِ فَوْقَ ثَلاَثَةِ أَيَّامٍ."],"takhrij":"صحيح: رواه مسلم في الأضاحي (26:1970) من طريق الليث (هو ابن سعد) عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن ادّخار لحوم الأضاحي فوق ثلاثة أيام","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1970:26).","chapter_en":"The Prohibition of Storing the Meat of Sacrificial Animals for More Than Three Days","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":27,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar narrated from the Prophet ﷺ that he said: “No one should eat from the meat of his sacrificial animal for more than three days.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":26,"lafz":true}],"full":1},{"num":7216,"demo":false,"sanad":"","matn":["عَنْ سَلَمَةَ بْنِ الأَكْوَعِ، قَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ ضَحَّى مِنْكُمْ فَلاَ يُصْبِحَنَّ بَعْدَ ثَالِثَةٍ وَفِي بَيْتِهِ مِنْهُ شَىْءٌ. فَلَمَّا كَانَ الْعَامُ الْمُقْبِلُ قَالُوا يَا رَسُولَ اللَّهِ نَفْعَلُ كَمَا فَعَلْنَا عَامَ الْمَاضِي قَالَ كُلُوا وَأَطْعِمُوا وَادَّخِرُوا فَإِنَّ ذَلِكَ الْعَامَ كَانَ بِالنَّاسِ جَهْدٌ فَأَرَدْتُ أَنْ تُعِينُوا فِيهَا."],"takhrij":"متفق عليه: رواه البخاري في الأضاحي (5569)، ومسلم في الأضاحي (34:1974) كلاهما من طريق أبي عاصم، عن يزيد بن أبي عُبيد، عن سلمة ابن الأكوع فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الرخصة في أكل لحوم الأضاحي وادّخارها فوق ثلاث","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5569) and Muslim (1974:34).","chapter_en":"What Has Been Reported Concerning the Concession to Eat and Store the Meat of Sacrificial Animals for More Than Three Days","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["Salamah ibn al-Akwaʿ said: The Prophet ﷺ said: “Whoever among you offers a sacrifice should not wake up after the third day with any of it remaining in his house.” When the following year came, they said: “O Messenger of Allah, should we do as we did last year?” He said: “Eat, feed others, and store it, for that year the people were in hardship, so I wanted you to help during it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5569,"lafz":true},{"key":"muslim","label":"مسلم","number":34}],"full":1},{"num":7217,"demo":false,"sanad":"","matn":["عَنْ جابر قَالَ: كُنَّا لاَ نَأْكُلُ مِنْ لُحُومِ بُدْننا فوقَ ثَلاَثِ مِنىً، فَأَرْخَصَ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: كُلُوا وتزوَّدُوا. قلتُ لِعَطَاءٍ: قَالَ جَابِرٌ: حَتَّى جِئْنَا الْمَدِينَةَ؟ قَالَ: نَعَمْ. وَفِي رِوَايَةِ: لاَ."],"takhrij":"متفق عليه: رواه البخاري في الحج (1719)، ومسلم في الأضاحي (30:1972) كلاهما من يحيى بن سعيد، عن ابن جريج، حدثنا عطاء قال: سمعتُ جابر بن عبدالله يقول فذكره. والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الرخصة في أكل لحوم الأضاحي وادّخارها فوق ثلاث","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1719) and Muslim (1972:30). The wording is from Muslim.","chapter_en":"What Has Been Reported Concerning the Concession to Eat and Store the Meat of Sacrificial Animals for More Than Three Days","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: We used not to eat from the meat of our sacrificial camels beyond the three days of Mina, then the Messenger of Allah ﷺ granted us a concession and said: “Eat and take provisions.” I said to ʿAta’: “Did Jabir say: until we came to Madinah?” He said: “Yes.” And in another narration: “No.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1719,"lafz":true},{"key":"muslim","label":"مسلم","number":30}],"full":1,"dr":1},{"num":7218,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَابِسٍ، عَنْ أَبِيهِ، قَالَ قُلْتُ لِعَائِشَةَ أَنَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تُؤْكَلَ لُحُومُ الأَضَاحِيِّ فَوْقَ ثَلاَثٍ قَالَتْ مَا فَعَلَهُ إِلاَّ فِي عَامٍ جَاعَ النَّاسُ فِيهِ، فَأَرَادَ أَنْ يُطْعِمَ الْغَنِيُّ الْفَقِيرَ، وَإِنْ كُنَّا لَنَرْفَعُ الْكُرَاعَ فَنَأْكُلُهُ بَعْدَ خَمْسَ عَشْرَةَ. قِيلَ مَا اضْطَرَّكُمْ إِلَيْهِ فَضَحِكَتْ قَالَتْ مَا شَبِعَ آلُ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ خُبْزِ بُرٍّ مَأْدُومٍ ثَلاَثَةَ أَيَّامٍ حَتَّى لَحِقَ بِاللَّهِ."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5423)، ومسلم في الزهد والرقائق (23:2970) من طريق سفيان (هو الثوري)، عن عبدالرحمن بن عابس، عن أبيه (هو عابس بن ربيعة النخعي الكوفي) به، فذكره. والسياق للبخاري، واقتصر مسلم على قولها: \"ما شبع آل محمد صلى الله عليه وسلم ...\" الخ.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الرخصة في أكل لحوم الأضاحي وادّخارها فوق ثلاث","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5423) and Muslim (2970:23). The wording is from al-Bukhari.","chapter_en":"What Has Been Reported Concerning the Concession to Eat and Store the Meat of Sacrificial Animals for More Than Three Days","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["ʿAbd al-Rahman ibn ʿAbis narrated from his father, who said: I said to ʿA’ishah: “Did the Prophet ﷺ forbid eating the meat of sacrificial animals for more than three days?” She said: “He only did that in a year when people were hungry, so he wanted the rich to feed the poor. We would even keep the lower leg after fifteen days!” It was said: “What forced you to do that?” She laughed and said: “The family of Muhammad ﷺ never ate their fill of wheat bread with a condiment for three days until he met Allah.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5423,"lafz":true},{"key":"muslim","label":"مسلم","number":23}],"full":1,"rep":[9537]},{"num":7219,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن وَاقِدٍ أَنَّهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ أَكْلِ لُحُومِ الضَّحَايَا بَعْدَ ثَلاَثَةِ أَيَّامٍ، قَال عَبْدُ اللَّهِ بْن أَبي بكْر: فَذَكَرْتُ ذَلك لِعَمْرة بِنْت عبدالرحمن فَقَالَتْ: صَدَقَ. سَمِعْتُ عَائِشَةَ زَوْجَ النَّبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَقُولُ دَفَّ نَاسٌ مِن أَهل الْبَادِيَةِ حَضْـرةَ الأَضْحَى فِي زَمَانِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : ادَّخِرُوا لِثَلاثٍ وَتَصَدَّقُوا بِمَا بَقِيَ. قَالَتْ: فَلَمَّا كانَ بَعْدَ ذَلِك قِيلَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : لَقَدْ كَانَ النَّاسُ يَنْتَفِعُونَ بِضَحَايَاهُمْ، ويَجْمُلُونَ مِنْهَا الْوَدَكَ، وَيَتَّخِذُونَ مِنْهَا الأَسْقِيَةَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : وَمَا ذَلِكَ؟ أَوْ كَمَا قَالَ. قَالُوا: نَهَيْتَ عَنْ لُحُومِ الضَّحَايَا بَعْدَ ثَلاَثٍ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنَّمَا نَهَيْتُكم مِنْ أَجْلِ الدَّافَّةِ الَّتِي دَفَّتْ عَلَيْكُمْ، فَكُلُوا وَ تَصَدَّقُوا وَادَّخِرُوا."],"takhrij":"صحيح: رواه مالك في الضحايا (7) عن عبدالله بن أبي بكر، عن عبدالله ابن واقد فذكره. ورواه مسلم في الأضاحي (28:1971) من طريق مالك به مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في الرخصة في أكل لحوم الأضاحي وادّخارها فوق ثلاث","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (7) and Muslim (1971:28).","chapter_en":"What Has Been Reported Concerning the Concession to Eat and Store the Meat of Sacrificial Animals for More Than Three Days","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["ʿAbdullah ibn Waqid said: The Messenger of Allah ﷺ forbade eating the meat of sacrificial animals after three days. ʿAbdullah ibn Abi Bakr said: I mentioned that to ʿAmrah bint ʿAbd al-Rahman, and she said: “He has spoken the truth. I heard ʿA’ishah, the wife of the Prophet ﷺ, say: People from the desert came quickly at the time of the Sacrifice during the time of the Messenger of Allah ﷺ, so the Messenger of Allah ﷺ said: ‘Store for three days and give in charity what remains.’ She said: Later, it was said to the Messenger of Allah ﷺ: ‘People used to benefit from their sacrificial animals, render their fat, and make waterskins from them.’ The Messenger of Allah ﷺ said: ‘What is the matter with that?’ Or something similar. They said: ‘You forbade the meat of sacrificial animals after three days.’ The Messenger of Allah ﷺ said: ‘I only forbade you because of the groups that had come upon you. So eat, give in charity, and store.’”"]},"buhuth":{"en":["Her statement, “people came quickly”: the word means a quick pace with short steps. She meant that famine had brought the desert people to Madinah."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":7,"lafz":true},{"key":"muslim","label":"مسلم","number":28}],"full":1,"dr":1},{"num":7220,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سليمان قَالَتْ: دَخَلْتُ عَلَى عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلْتُهَا عَنْ لُحُومِ الْأَضَاحِيِّ؟ فَقَالَتْ: قَدْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنْهَا ثُمَّ رخّص فِيهَا، قدِمَ عليُّ بْنُ أَبِي طَالِبٍ مِنْ سَفَرٍ فَأَتَتْهُ فَاطِمَةُ بِلَحْمٍ مِنْ ضَحَايَاهَا فَقَالَ: أَوَلَمْ يَنْهَ عَنْهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ؟ فَقَالَتْ: إِنَّهُ قَدْ رَخَّصَ فِيهَا. قَالَتْ: فَدَخَلَ عليٌّ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَهُ عَنْ ذَلِكَ فَقَالَ لَهُ: كُلْها مِنْ ذِي الْحِجَّةِ إِلَى ذِي الْحِجَّةِ."],"takhrij":"حسن: رواه الإمام أحمد (26415) عن يعقوب (هو ابن إبراهيم بن سعد الزهري)، ثني أبي، عن محمد بن إسحاق قال: حدثني يزيد بن أبي حبيب، عن سليمان بن أبي سليمان، عن أمه أم سليمان –وكلاهما كان ثقة- قالت فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء في الرخصة في أكل لحوم الأضاحي وادّخارها فوق ثلاث","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (26415).","chapter_en":"What Has Been Reported Concerning the Concession to Eat and Store the Meat of Sacrificial Animals for More Than Three Days","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["Umm Sulayman said: I entered upon ʿA’ishah, the wife of the Prophet ﷺ, and asked her about the meat of sacrificial animals. She said: “The Messenger of Allah ﷺ had forbidden it, then he gave permission regarding it. ʿAli ibn Abi Talib returned from a journey, and Fatimah brought him some meat from her sacrificial animals. He said: ‘Did the Messenger of Allah ﷺ not forbid it?’ She said: ‘He has given permission regarding it.’” She said: ʿAli then entered upon the Messenger of Allah ﷺ and asked him about that, and he said to him: “Eat it from one Dhu al-Hijjah to the next Dhu al-Hijjah.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":26415,"lafz":true}],"full":1,"dr":1},{"num":7221,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ أَكْلِ لُحُومِ الضَّحَايَا بَعْدَ ثَلاَثَةِ أَيَّامٍ ثُمَّ قَالَ بَعْدُ كُلُوا وَتَصَدَّقُوا وَتَزَوَّدُوا وَادَّخِرُوا."],"takhrij":"صحيح: رواه مالك في الضحايا (6) عن أبي الزبير المكي، عن جابر بن عبدالله فذكره. رواه مسلم في الأضاحي (29:1972) من طريق مالك به.","grade":"صحيح","chapter_ar":"باب ما جاء في الرخصة في أكل لحوم الأضاحي وادّخارها فوق ثلاث","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (6) and Muslim (1972:29).","chapter_en":"What Has Been Reported Concerning the Concession to Eat and Store the Meat of Sacrificial Animals for More Than Three Days","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["Jabir narrated that the Messenger of Allah ﷺ forbade eating the meat of sacrificial animals after three days, then later said: “Eat, give in charity, take provisions, and store.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":6,"lafz":true},{"key":"muslim","label":"مسلم","number":29}],"full":1,"rep":[12791]},{"num":7222,"demo":false,"sanad":"","matn":["عَنِ ابْنِ خَبَّابٍ، أَنَّ أَبَا سَعِيدِ بْنِ مَالِكٍ الْخُدْرِيَّ رَضِيَ اللَّهُ عَنْهُ قَدِمَ مِنْ سَفَرٍ، فَقَدَّمَ إِلَيْهِ أَهْلُهُ لَحْمًا مِنْ لُحُومِ الأَضْحَى فَقَالَ مَا أَنَا بِآكِلِهِ حَتَّى أَسْأَلَ، فَانْطَلَقَ إِلَى أَخِيهِ لأُمِّهِ وَكَانَ بَدْرِيًّا قَتَادَةَ بْنِ النُّعْمَانِ فَسَأَلَهُ، فَقَالَ إِنَّهُ حَدَثَ بَعْدَكَ أَمْرٌ نَقْضٌ لِمَا كَانُوا يُنْهَوْنَ عَنْهُ مِنْ أَكْلِ لُحُومِ الأَضْحَى بَعْدَ ثَلاَثَةِ أَيَّامٍ."],"takhrij":"صحيح: رواه البخاري في المغازي (3997) عن عبدالله بن يوسف، ثنا الليث، حدثني يحيى بن سعيد، عن القاسم بن محمد، عن ابن خباب (واسمه عبدالله) فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الرخصة في أكل لحوم الأضاحي وادّخارها فوق ثلاث","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3997).","chapter_en":"What Has Been Reported Concerning the Concession to Eat and Store the Meat of Sacrificial Animals for More Than Three Days","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["Ibn Khabbab narrated that Abu Saʿid ibn Malik al-Khudri returned from a journey, and his family presented him some meat from the sacrificial animals. He said: “I will not eat it until I ask.” So he went to his maternal brother Qatadah ibn al-Nuʿman — who had participated in Badr — and asked him. He said: “After you left, something occurred that abrogated what they had been forbidden regarding eating the meat of sacrificial animals after three days.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3997,"lafz":true}],"full":1,"dr":1},{"num":7223,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ نَهَانَا أَنْ نَأْكُلَ لُحُومَ نُسُكِنَا فَوْقَ ثَلَاثٍ، قَالَ: فَخَرَجْتُ فِي سَفَرٍ، ثُمَّ قَدِمْتُ عَلَى أَهْلِي، وَذَلِكَ بَعْدَ الْأَضْحَى بِأَيَّامٍ، قَالَ: فَأَتَتْنِي صَاحِبَتِي بِسَلقٍ قَدْ جَعَلَتْ فِيهِ قَدِيدًا، فَقُلْتُ لَهَا: أَنَّى لَكِ هَذَا الْقَدِيدُ؟ فَقَالَتْ: مِنْ ضَحَايَانَا؟ قَالَ: فَقُلْتُ لَهَا: أَوَلَمْ يَنْهَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ أَنْ نَأْكُلَهَا فَوْقَ ثَلَاثٍ؟ قَالَ: فَقَالَتْ: إِنَّهُ قَدْ رَخَّصَ لِلنَّاسِ بَعْدَ ذَلِكَ، قَالَ: فَلَمْ أُصَدِّقْهَا، حَتَّى بَعَثْتُ إِلَى أَخِي قَتَادَةَ بْنِ النُّعْمَانِ، وَكَانَ بَدْرِيًّا، أَسْأَلُهُ عَنْ ذَلِكَ، قَالَ: فَبَعَثَ إِلَيَّ أَنْ كُلْ طَعَامَكَ فَقَدْ صَدَقَتْ قَدْ أَرْخَصَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلْمُسْلِمِينَ فِي ذَلِكَ."],"takhrij":"حسن: رواه أحمد (16214) عن يعقوب (هو ابن إبراهيم بن سعد الزهري)، ثنا أبي، عن محمد بن إسحاق، قال: حدثني محمد بن علي بن حسين أبو جعفر، وأبي إسحاقُ بنُ يسار، عن عبدالله بن خبّاب مولى بني عَدي بن النجّار، عن أبي سعيد الخدري فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الرخصة في أكل لحوم الأضاحي وادّخارها فوق ثلاث","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (16214).","chapter_en":"What Has Been Reported Concerning the Concession to Eat and Store the Meat of Sacrificial Animals for More Than Three Days","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: The Messenger of Allah ﷺ had forbidden us from eating the meat of our sacrificial animals for more than three days. He said: I went out on a journey, then returned to my family, and that was a few days after the Sacrifice. He said: My wife brought me beet greens in which she had placed dried meat. I said to her: “Where did you get this dried meat?” She said: “From our sacrificial animals.” He said: I said to her: “Did the Messenger of Allah ﷺ not forbid us from eating it for more than three days?” He said: She said: “He later gave the people permission regarding that.” He said: I did not believe her until I sent to my brother Qatadah ibn al-Nuʿman — who had participated in Badr — asking him about that. He sent back to me: “Eat your food, for she has spoken the truth. The Messenger of Allah ﷺ gave the Muslims permission regarding that.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":16214,"n":16214,"lafz":true}],"full":1,"dr":1},{"num":7224,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : يَا أَهْلَ الْمَدِينَةِ لاَ تَأْكُلُوا لُحُومَ الأَضَاحِيِّ فَوْقَ ثَلاَثٍ فَشَكَوْا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ لَهُمْ عِيَالاً وحَشَماً وَخَدَمًا فَقَالَ: كُلُوا وَأَطْعِمُوا وَاحْبِسُوا– أَوِ ادَّخِرُوا-."],"takhrij":"صحيح: رواه مسلم في الأضاحي (33:1973) عن أبي بكر بن أبي شيبة، حدثنا عبدالأعلى، عن الجريري، عن أبي نضرة، عن أبي سعيد، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الرخصة في أكل لحوم الأضاحي وادّخارها فوق ثلاث","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1973:33).","chapter_en":"What Has Been Reported Concerning the Concession to Eat and Store the Meat of Sacrificial Animals for More Than Three Days","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: The Messenger of Allah ﷺ said: “O people of Madinah, do not eat the meat of sacrificial animals for more than three days.” They complained to the Messenger of Allah ﷺ that they had dependents, household members, and servants. So he said: “Eat, feed others, and keep it — or store it.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":33,"lafz":true}],"full":1,"dr":1},{"num":7225,"demo":false,"sanad":"","matn":["ابْنِ بُرَيْدَةَ، عَنْ أَبِيهِ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَيْتُكُمْ عَنْ زِيَارَةِ الْقُبُورِ فَزُورُوهَا وَنَهَيْتُكُمْ عَنْ لُحُومِ الأَضَاحِيِّ فَوْقَ ثَلاَثٍ فَأَمْسِكُوا مَا بَدَا لَكُمْ وَنَهَيْتُكُمْ عَنِ النَّبِيذِ إِلاَّ فِي سِقَاءٍ فَاشْرَبُوا فِي الأَسْقِيَةِ كُلِّهَا وَلاَ تَشْرَبُوا مُسْكِرًا."],"takhrij":"صحيح: رواه مسلم في الأضاحي (37:1977) من طريق محمد بن فضيل، عن أبي سنان ضرار بن مُرّة، عن محارب بن دثار، عن عبدالله بن بريدة، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الرخصة في أكل لحوم الأضاحي وادّخارها فوق ثلاث","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1977:37).","chapter_en":"What Has Been Reported Concerning the Concession to Eat and Store the Meat of Sacrificial Animals for More Than Three Days","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["Buraydah ibn Husayb said: The Messenger of Allah ﷺ said: “I had forbidden you from visiting graves, so now visit them. I had forbidden you from the meat of sacrificial animals beyond three days, so keep whatever you wish. And I had forbidden you from infused drinks except in waterskins, so drink from all vessels, but do not drink anything intoxicating.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":37,"lafz":true}],"full":1,"rep":[3892]},{"num":7226,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الحصيب قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : كنتُ نَهَيْتُكُمْ عَنْ لُحُومِ الأَضَاحِي فَوْقَ ثَلاَثٍ لِيَتَّسِعَ ذُو الطَّوْل عَلَى مَنْ لاَ طَوْل لَهُ، فَكُلُوا مَا بَدَا لَكُمْ وَأَطْعِمُوا وَادَّخِرُوا."],"takhrij":"صحيح: رواه الترمذي (1510) من طريق أبي عاصم النبيل (هو الضحاك بن مخلد)-، والإمام أحمد (23016) عن مؤمل- كلاهما عن سفيان الثوري، عن علقمة بن مرثد، عن سليمان بن بريدة، عن أبيه فذكره. والسياق للترمذي، وهو عند أحمد مطولا بذكر زيارة القبور، والأوعية أيضا، ووقع عنده \"عن ابن بريدة\" غير مسمى.","grade":"صحيح","chapter_ar":"باب ما جاء في الرخصة في أكل لحوم الأضاحي وادّخارها فوق ثلاث","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1510) and Imam Ahmad (23016).","chapter_en":"What Has Been Reported Concerning the Concession to Eat and Store the Meat of Sacrificial Animals for More Than Three Days","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["Buraydah ibn al-Husayb said: The Messenger of Allah ﷺ said: “I had forbidden you from the meat of sacrificial animals beyond three days so that those with means would provide for those without means. So eat whatever you wish, feed others, and store it.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1510,"lafz":true},{"key":"ahmad","label":"الإمام أحمد","number":23016}],"full":1,"dr":1},{"num":7227,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ قَالَ: ذَبَحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ضَحِيَّتَهُ ثُمَّ قَالَ: يَا ثَوْبَانُ أصْلِحْ لحمَ هَذِهِ فَلَمْ أزلْ أُطْعِمُهُ مِنْهَا حَتَّى قَدِمَ الْمَدِينَةَ. وَزَادَ فِي رِوَايَةِ: فِي حجة الْوَدَاعِ."],"takhrij":"صحيح: رواه مسلم في الأضاحي (35:1975) عن زهير بن حرب، حدثنا معن بن عيسى، حدثنا معاوية بن صالح، عن أبي الزاهرية، عن جُبير بن نُفير، عن ثوبان فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الرخصة في أكل لحوم الأضاحي وادّخارها فوق ثلاث","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1975:35).","chapter_en":"What Has Been Reported Concerning the Concession to Eat and Store the Meat of Sacrificial Animals for More Than Three Days","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["Thawban said: The Messenger of Allah ﷺ slaughtered his sacrifice, then said: “O Thawban, prepare the meat of this one.” So I continued feeding him from it until he reached Madinah. Another narration adds: “during the Farewell Pilgrimage.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":35,"lafz":true}],"full":1,"dr":1},{"num":7228,"demo":false,"sanad":"","matn":["عَنْ نُبَيْشَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّا كُنَّا نَهَيْنَاكُمْ عَنْ لُحُومِهَا أَنْ تَأْكُلُوهَا فَوْقَ ثَلاَثٍ لِكَىْ تَسَعَكُمْ فَقَدْ جَاءَ اللَّهُ بِالسَّعَةِ فَكُلُوا وَادَّخِرُوا وَاتَّجِرُوا أَلاَ وَإِنَّ هَذِهِ الأَيَّامَ أَيَّامُ أَكْلٍ وَشُرْبٍ وَذِكْرِ اللَّهِ عَزَّ وَجَلَّ."],"takhrij":"صحيح: رواه أبوداود (2813)، وابن ماجه (3160)، وأحمد (20723، 20729) كلهم من طريق خالد الحذاء، عن أبي المليح بن أسامة، عن نُبيشة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الرخصة في أكل لحوم الأضاحي وادّخارها فوق ثلاث","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2813), Ibn Majah (3160), and Ahmad (20729, 20723).","chapter_en":"What Has Been Reported Concerning the Concession to Eat and Store the Meat of Sacrificial Animals for More Than Three Days","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["Nubayshah al-Hudhali said: The Messenger of Allah ﷺ said: “We had forbidden you from eating its meat for more than three days so that it would be enough for you. But Allah has now brought abundance, so eat, store, and seek reward. Indeed, these days are days of eating, drinking, and remembering Allah, the Mighty and Majestic.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2813,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":3160},{"key":"ahmad","label":"مسند الإمام أحمد","number":20729,"n":20728},{"key":"ahmad","label":"احمد","number":20723}],"full":1,"dr":1},{"num":7229,"demo":false,"sanad":"","matn":["عن نبيشة قَالَ: نَادَى رَجُلٌ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّا كُنَّا نَعْتِرُ عَتِيرَةً فِي الْجَاهِلِيَّةِ فِي رَجَبٍ فَمَا تَأْمُرُنَا قَالَ اذْبَحُوا لِلَّهِ فِي أَىِّ شَهْرٍ كَانَ وَبَرُّوا اللَّهَ عَزَّ وَجَلَّ وَأَطْعِمُوا. قَالَ إِنَّا كُنَّا نُفْرِعُ فَرَعًا فِي الْجَاهِلِيَّةِ فَمَا تَأْمُرُنَا.","قال: في كل سائمة فرع تغذوه ماشيتُك حتى إذا استحمل للحجيج ذبحته فتصدقت بلحمه.","قال خالد: أحسبه قال: على ابن السبيل؛ فإن ذلك خير.","قال خالد: قلت لأبي قلابة: كم السائمة؟ قال: مائة."],"takhrij":"صحيح: رواه أبوداود (2830)، والنسائي (4231)، وابن ماجه (3167)، والإمام أحمد (20723)، والحاكم (4/235) من طرق عن خالد (هو ابن مهران الحذاء)، عن أبي المليح، عن نُبيشة فذكره. والسياق لأبي داود، وزاد أحمد في آخره حديث الرخصة في أكل الأضاحي فوق ثلاث.","grade":"صحيح","chapter_ar":"باب ما جاء في الفرع والعتيرة","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2830), al-Nasa’i (4231), Ibn Majah (3167), Imam Ahmad (20723), and al-Hakim (4/235).","chapter_en":"What Has Been Reported Concerning the Firstborn Sacrifice and the Rajab Sacrifice","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Nubayshah said: A man called out to the Messenger of Allah ﷺ: “We used to slaughter a Rajab sacrifice during the time of ignorance in Rajab. What do you command us?” He said: “Slaughter for Allah in whichever month it may be, honor Allah, the Mighty and Majestic, and feed others.” He said: “We used to offer the firstborn sacrifice during the time of ignorance. What do you command us?” He said: “For every grazing herd, there is a firstborn animal that your livestock raises until it becomes fit to carry pilgrims; then you slaughter it and give its meat in charity.” Khalid said: I think he said: “To the traveler, for that is better.” Khalid said: I said to Abu Qilabah: “How many animals make a grazing herd?” He said: “One hundred.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2830,"lafz":true},{"key":"nasai","label":"النسائي","number":4231},{"key":"ibnmajah","label":"ابن ماجه","number":3167},{"key":"ahmad","label":"الإمام أحمد","number":20723},{"key":"hakim","label":"الحاكم","number":4}],"full":1,"dr":1},{"num":7230,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عمرو بْنِ الْعَاصِ قَالَ: قَالُوا: يَا رَسُولَ اللَّهِ، الْفَرَعَ؟ قَالَ: حَقٌّ، فَإِنْ تَرَكْتَهُ حَتَّى يَكُونَ بَكْرًا فَتَحْمِلَ عَلَيْهِ فِي سَبِيلِ اللَّهِ، أَوْ تُعْطِيَهُ أَرْمَلَةً خَيْرٌ مِنْ أَنْ تَذْبَحَهُ فَيَلْصَقَ لَحْمُهُ بِوَبَرِهِ فَتُكْفِئَ إِنَاءَكَ وتُوَلِّه نَاقَتَكَ قَالُوا: يَا رَسُولَ اللَّهِ، فَالْعَتِيرَةُ؟ قَالَ: الْعَتِيرَةُ حَقٌّ."],"takhrij":"حسن: رواه أبوداود (2842)، والنسائي (4225)، والإمام أحمد (6713)، والحاكم (4/236) كلهم من طريق أبي داود بن قيس قال: سمعت عمرو بن شعيب يحدث عن أبيه عن جده عبدالله بن عمرو فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الفرع والعتيرة","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2842), al-Nasa’i (4225), Imam Ahmad (6713), and al-Hakim (7584).","chapter_en":"What Has Been Reported Concerning the Firstborn Sacrifice and the Rajab Sacrifice","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs said: They said: “O Messenger of Allah, what about the firstborn sacrifice?” He said: “It is a right. But if you leave it until it becomes a young camel that can be ridden in the way of Allah, or you give it to a widow, that is better than slaughtering it while its flesh clings to its fur, then you overturn your vessel and distress your she-camel.” They said: “O Messenger of Allah, what about the Rajab sacrifice?” He said: “The Rajab sacrifice is a right.”"]},"buhuth":{"en":["His statement, “its flesh clings to its fur,” means that the flesh of the firstborn — meaning the young camel — clings to its fur because it is little and not fat.","His statement, “then you overturn your vessel,” means you pour out or turn over your vessel, because no milk remains for you to milk into it.","His statement, “and distress your she-camel,” with a doubled lam, al-Khattabi said: It means you grieve her by taking her child. Its root refers to loss of reason due to losing a child."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2842,"lafz":true},{"key":"nasai","label":"النسائي","number":4225,"n":4225},{"key":"ahmad","label":"الإمام أحمد","number":6713},{"key":"hakim","label":"الحاكم","number":7584}],"full":1,"dr":1},{"num":7231,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ نُعِقَّ عَنِ الْجَارِيَةِ شَاةً، وَعَنِ الْغُلَامِ شَاتَيْنِ، وَأَمَرَنَا بِالْفَرَعِ مِنْ كُلِّ خَمْسِ شِيَاهٍ شَاةٌ."],"takhrij":"حسن: رواه أحمد (25250)، وابن أبي شيبة (24789) كلاهما عن عفان، عن حماد، حدثنا عبدالله بن عثمان بن خثيم، عن يوسف بن ماهك، عن حفصة بنت عبدالرحمن، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء في الفرع والعتيرة","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (25250) and Ibn Abi Shaybah (24789).","chapter_en":"What Has Been Reported Concerning the Firstborn Sacrifice and the Rajab Sacrifice","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ commanded us to offer one sheep as the birth sacrifice for a girl, and two sheep for a boy. He also commanded us regarding the firstborn sacrifice: one sheep from every five sheep."]}},"tuhfa":{},"refs":[{"key":"sh9944","label":"ابن أبي شيبة","number":24789},{"key":"ahmad","label":"مسند الإمام أحمد","number":25250,"n":25250,"lafz":true}],"full":1,"dr":1},{"num":7232,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لافرع ولاعتيرة. وَالْفَرَعُ: أوّلُ النِّتَاجِ كَانُوا يَذْبَحُونَهُ لَطِوَاغِيتِهِمْ، وَالْعَتِيرَةُ فِي رَجَبٍ."],"takhrij":"متفق عليه: رواه البخاري في العقيقة (5473)، ومسلم في الأضاحي (38:1976) كلاهما من طريق معمر، أخبرنا الزهري، عن ابن المسيب، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في النهي عن الفرع والعتيرة","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5473) and Muslim (1976:38).","chapter_en":"What Has Been Reported Concerning the Prohibition of the Firstborn Sacrifice and the Rajab Sacrifice","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":30,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “There is no firstborn sacrifice and no Rajab sacrifice.” The firstborn sacrifice is the first offspring that they used to slaughter for their false deities, and the Rajab sacrifice was done in Rajab."]},"buhuth":{"en":["His statement, “There is no firstborn sacrifice”: the Arabic term is pronounced with an open fa’ and ra’, and its plural is firaʿ. It is explained, as mentioned at the end of the hadith, as the first offspring of camels or sheep. The people of the pre-Islamic period used to slaughter it for their idols. It was also said that in the pre-Islamic period, when a man’s camels reached one hundred, he would bring forward a young camel and slaughter it for his idol.","His statement, “and no Rajab sacrifice”: the Arabic term is pronounced ʿatirah, on the pattern of ʿazimah. It is explained in the hadith as the sheep slaughtered in the month of Rajab. Abu ʿUbayd said: The Rajab sacrifice is the animal they used to slaughter during the pre-Islamic period in Rajab, seeking closeness to their idols through it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5473,"lafz":true},{"key":"muslim","label":"مسلم","number":38}],"full":1,"dr":1},{"num":7233,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ فَرَعَةَ وَلاَ عَتِيرَةَ."],"takhrij":"صحيح: رواه ابن ماجه (3169) عن محمد بن أبي عمر العدني، ثنا سفيان بن عيينة، عن زيد بن أسلم، عن أبيه، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في النهي عن الفرع والعتيرة","chapter_ur":"","part_ar":"كتاب الأضاحي","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (3169).","chapter_en":"What Has Been Reported Concerning the Prohibition of the Firstborn Sacrifice and the Rajab Sacrifice","part_en":"Book of Sacrificial Animals","group_ar":"","group_en":"","part_no":36,"group_no":0,"chapter_no":30,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Prophet ﷺ said: “There is no firstborn sacrifice and no Rajab sacrifice.”"]},"buhuth":{"en":["The scholars differed in how to reconcile these two hadiths with the earlier hadiths that indicate the permissibility of the Rajab sacrifice or the command to perform it.","Some reconciled them by interpreting the earlier hadiths as recommendation, and the hadith of Abu Hurayrah and Ibn ʿUmar as negating obligation. Thus, his statement, “There is no firstborn sacrifice and no Rajab sacrifice,” means: there is no obligatory firstborn sacrifice and no obligatory Rajab sacrifice. This was the view of Ishaq ibn Rahawayh. After narrating the hadith of ʿA’ishah, “The Messenger of Allah ﷺ commanded the firstborn sacrifice: one from every five,” he said regarding “There is no firstborn sacrifice and no Rajab sacrifice”: We say, “not obligatory.” End quote.","This is the school of al-Shafiʿi and some of his companions. Al-Nawawi said in his commentary on Muslim (13/137): “The correct view among our companions, and it is the explicit statement of al-Shafiʿi, is that the firstborn sacrifice and the Rajab sacrifice are recommended. They answered the hadith, ‘There is no firstborn sacrifice and no Rajab sacrifice,’ in three ways:","First: the earlier answer of al-Shafiʿi, that what is meant is negation of obligation.","Second: what is meant is negating what they used to slaughter for their idols.","Third: that they are not like the sacrifice in recommendation or in the reward of shedding blood. As for distributing the meat to the poor, that is righteousness and charity. Al-Shafiʿi explicitly stated in the narrations of Harmalah that if it is easy to do every month, then it is good. This is the summary of its ruling in our school.”","The majority of scholars held that the firstborn sacrifice and the Rajab sacrifice are invalidated, and that the hadiths indicating their legislation were abrogated by the hadith of Abu Hurayrah prohibiting them. Even though the chronology is not known, the principles of preference require this, because prohibition only occurs regarding something that was being done. No one said that he forbade them and then later permitted them; rather, the final matter was the prohibition of doing them. Al-Qadi ʿIyad reported from the majority of scholars that the command of the firstborn sacrifice and the Rajab sacrifice was abrogated, and al-Nawawi transmitted this from him in his commentary on Muslim (13/137)."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":3169,"lafz":true}],"full":1,"dr":1},{"num":7234,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جُنْدُبٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ كُلُّ غُلاَمٍ رَهِينَةٌ بِعَقِيقَتِهِ تُذْبَحُ عَنْهُ يَوْمَ سَابِعِهِ وَيُحْلَقُ وَيُسَمَّى."],"takhrij":"صحيح: رواه أبو داود (2838)، والترمذي (1522)، والنسائي (4220)، وابن ماجه (3165) والإمام أحمد (20083) كلهم من طرق عن قتادة، عن الحسن، عن سمرة بن جندب فذكره.","grade":"صحيح","chapter_ar":"باب استحباب العق عن المولود وحلق شعره وتسميته في اليوم السابع","chapter_ur":"","part_ar":"كتاب العقيقة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2838), al-Tirmidhi (1522), al-Nasa’i (4220), Ibn Majah (3165), and Imam Ahmad (20083).","chapter_en":"The Recommendation of Offering a Birth Sacrifice for the Newborn, Shaving His Hair, and Naming Him on the Seventh Day","part_en":"Book of the Birth Sacrifice","group_ar":"","group_en":"","part_no":37,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Samurah ibn Jundub narrated that the Messenger of Allah ﷺ said: “Every boy is held in pledge by his birth sacrifice: it is slaughtered for him on his seventh day, his hair is shaved, and he is named.”"]},"buhuth":{"en":["His statement, “held in pledge”: this comes from the meaning of a pledge. The added ending is for emphasis, as in similar Arabic forms. Then both forms came to be used for something held as a pledge, so it is said: “He is pledged for such-and-such,” or “held in pledge for such-and-such.” The meaning of his statement, “held in pledge by his birth sacrifice,” is that the birth sacrifice is binding with respect to him and must be done; he likened its attachment to him and his not being separated from it to a pledge in the hand of the one holding it.","Al-Khattabi said: People have discussed this, and the best explanation is what Ahmad ibn Hanbal held. He said: This refers to intercession, meaning that if the birth sacrifice is not offered for him and he dies as a child, he will not intercede for his parents. It was also said that it means he is held in pledge because of the harm connected to his hair. They used as evidence his statement, “Remove the harm from him,” meaning what is attached to him from the blood of the womb. Ibn al-Athir mentioned it in al-Nihayah (2/681)."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2838,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1522,"n":1583},{"key":"nasai","label":"النسائي","number":4220,"n":4220},{"key":"ibnmajah","label":"ابن ماجه","number":3165},{"key":"ahmad","label":"الإمام أحمد","number":20083}],"full":1,"dr":1},{"num":7235,"demo":false,"sanad":"","matn":["عن سَلْمَانَ بن عَامِرٍ الضبي قَالَ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ مَعَ الْغُلاَمِ عَقِيقَةٌ، فَأَهْرِيقُوا عَنْهُ دَمًا وَأَمِيطُوا عَنْهُ الأَذَى."],"takhrij":"صحيح: رواه البخاري في كتاب العقيقة (5471) عن أبي النعمان، حدثنا حماد بن زيد، عن أيوب، عن محمد، عن سلمان بن عامر قال: مع الغلام عقيقة.","grade":"صحيح","chapter_ar":"باب في العقيقة وإماطة الأذى عن رأس المولود","chapter_ur":"","part_ar":"كتاب العقيقة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5471).","chapter_en":"The Birth Sacrifice and Removing Harm from the Newborn’s Head","part_en":"Book of the Birth Sacrifice","group_ar":"","group_en":"","part_no":37,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Salman ibn ʿAmir al-Dabbi said: I heard the Messenger of Allah ﷺ say: “With the boy is a birth sacrifice, so shed blood on his behalf and remove the harm from him.”"]},"buhuth":{"en":["His statement, “Remove the harm from him,” includes both male and female, because the harm refers to the blood of the womb. The Prophet ﷺ did not differentiate between male and female regarding shaving the hair."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5471,"lafz":true,"n":5472}],"full":1,"dr":1},{"num":7236,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عمرو قَالَ: سُئل رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْعَقِيقَةِ فَقَالَ: لايحب اللَّهُ عزوجل العقــوقَ وَكَأَنَّهُ كَرِهَ الاِسْمَ. قَالَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنَّمَا نَسْأَلُكَ أَحَدُنَا يُولَدُ لَهُ؟ قَالَ: مَنْ أَحَبَّ أَنْ يَنْسُكَ عَنْ وَلَده فَلْيَنْسُكْ عَنْهُ ؛ عَنِ الْغُلاَمِ شَاتَانِ مُكافئتان، وَعَنِ الْجَارِيَةِ شَاةٌ.","قال داود: سألت زيد بن أسلم عن المكافأتان؟ قال: الشاتان المشبهتان تُذبحان جميعا."],"takhrij":"حسن: رواه أبوداود (2842)، والنسائي (4212)، و الإمام أحمد (6713، 6822)، والحاكم (4/238) من طرق عن داود بن قيس الفرّاء، عن عمرو بن شعيب، عن أبيه عن جده فذكره. واللفظ للنسائي، وهو عند أبي داود وأحمد في الموضع الأول فيه السؤال عن الفرع والعتِيرة.","grade":"حسن","chapter_ar":"باب هل يكره تسمية النَّسيكة التي تذبح عن المولود عقيقة؟","chapter_ur":"","part_ar":"كتاب العقيقة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2842), al-Nasa’i (4212), Imam Ahmad (6822, 6713), and al-Hakim (4/238).","chapter_en":"Is It Disliked to Call the Sacrificial Rite Slaughtered for the Newborn a Birth Sacrifice?","part_en":"Book of the Birth Sacrifice","group_ar":"","group_en":"","part_no":37,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr said: The Messenger of Allah ﷺ was asked about the birth sacrifice, and he said: “Allah, the Mighty and Majestic, does not love disobedience to parents.” It was as though he disliked the name. They said to the Messenger of Allah ﷺ: “We are only asking about when one of us has a child.” He said: “Whoever loves to offer a sacrificial rite on behalf of his child, let him do so: for a boy, two equal sheep; and for a girl, one sheep.” Dawud said: I asked Zayd ibn Aslam about “two equal sheep.” He said: “Two similar sheep, slaughtered together.”"]},"buhuth":{"en":["His statement, “two equal sheep,” means equal in age and body, and they should be free from defects because they are offered as a means of drawing near to Allah. Is it a condition that they be mature, like the sacrificial animal? The apparent view is that this is not a condition, because it is not mentioned in the text. Whoever made it a condition did so by analogy with the sacrificial animal, but the first view is stronger.","His statement, “I do not love disobedience to parents”: the scholars differed in explaining it. It was said that he only disliked the name, not the legitimacy of the birth sacrifice itself, because the words for disobedience and the birth sacrifice share the same linguistic root. This explanation appears in the hadith itself."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2842,"lafz":true},{"key":"nasai","label":"النسائي","number":4212,"n":4212},{"key":"ahmad","label":"الإمام أحمد","number":6822},{"key":"hakim","label":"الحاكم","number":4},{"key":"ahmad","label":"و الامام احمد","number":6713}],"full":1,"dr":1},{"num":7237,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: كَانُوا فِي الْجَاهِلِيَّةِ إِذَا عَقُّوا عَنِ الصَّبِيِّ خَضَبُوا قُطْنَةً بِدَمِ الْعَقِيقَةِ، فَإِذَا حَلَقُوا رَأْسَ الصَّبِيِّ وَضَعُوهَا عَلَى رَأْسِهِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اجْعَلُوا مَكَانَ الدَّمِ خَلُوقًا."],"takhrij":"صحيح: رواه ابن حبان (5308) من طريق حجاج (هو ابن محمد المصيصي الأعور)-، والبزار (1239-كشف الأستار) من طريق روح بن عبادة- كلاهما عن ابن جريج، أخبرني يحيى بن سعيد (هو الأنصاري)، عن عمرة (هي بنت عبدالرحمن)، عن عائشة فذكرته. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب تلطيخ رأس الصبي بدم العقيقة هو من أعمال الجاهلية وإبداله في الإسلام بالخلوق","chapter_ur":"","part_ar":"كتاب العقيقة","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Hibban (5308) and al-Bazzar (1239 — Kashf al-Astar).","chapter_en":"Smearing the Child’s Head with the Blood of the Birth Sacrifice Is from the Practices of the Pre-Islamic Period, and Islam Replaced It with Perfume","part_en":"Book of the Birth Sacrifice","group_ar":"","group_en":"","part_no":37,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿA’ishah said: During the pre-Islamic period, when they offered a birth sacrifice for a child, they would dye a piece of cotton with the blood of the birth sacrifice. When they shaved the child’s head, they would place it on his head. So the Prophet ﷺ said: “Put perfume in place of the blood.”"]}},"tuhfa":{},"refs":[{"key":"bazzar","label":"البزار","number":1239},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1365,"n":1362},{"key":"ibnhibban","label":"ابن حبان","number":5308,"lafz":true}],"full":1},{"num":7238,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الحصيب قَالَ: كُنَّا فِي الْجَاهِلِيَّةِ إِذَا وُلِد لأَحَدِنَا غُلاَمٌ ذَبَحَ شاةً وَلَطَخَ رَأْسَهُ بِدَمِهَا، فَلَمَّا جَاءَ اللَّهُ بِالإِسْلاَمِ كُنَّا نَذْبَحُ شَاةً وَنَحْلِقُ رَأْسَهُ وَنَلْطَخُهُ بِزَعْفَرَانٍ."],"takhrij":"حسن: رواه أبوداود (2843) -ومن طريقه البيهقي (9/302-303)- والحاكم (4/238) كلهم من طريق الحسين بن واقد، عن عبدالله بن بُريدة، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب تلطيخ رأس الصبي بدم العقيقة هو من أعمال الجاهلية وإبداله في الإسلام بالخلوق","chapter_ur":"","part_ar":"كتاب العقيقة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2843), al-Bayhaqi (9/302–303), and al-Hakim (4/238).","chapter_en":"Smearing the Child’s Head with the Blood of the Birth Sacrifice Is from the Practices of the Pre-Islamic Period, and Islam Replaced It with Perfume","part_en":"Book of the Birth Sacrifice","group_ar":"","group_en":"","part_no":37,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Buraydah ibn al-Husayb said: During the pre-Islamic period, when a boy was born to one of us, he would slaughter a sheep and smear the child’s head with its blood. When Allah brought Islam, we would slaughter a sheep, shave his head, and smear it with saffron."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2843,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":9},{"key":"hakim","label":"الحاكم","number":4},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":19288,"n":19446}],"full":1,"dr":1},{"num":7239,"demo":false,"sanad":"","matn":["عَنْ ابْنِ أَبِي مُلَيْكة قَالَ: نُفِسَ لعبدالرحمن بْنِ أَبِي بَكْرٍ غُلَامٌ، فَقِيلَ لِعَائِشَةَ: يَا أُمَّ الْمُؤْمِنِينَ عُقِّي عَنْهُ جَزوراً، فَقَالَتْ: مَعَاذَ اللَّهِ، وَلَكِنْ مَا قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : شَاتَانِ مُكَافَأَتَانِ."],"takhrij":"حسن: رواه الطحاوي في شرح المشكل (1042)، والبيهقي (9/301) من طريق عبدالجبار بن ورْد المكي قال: سمعت ابن أبي مليكة قال فذكره.","grade":"حسن","chapter_ar":"باب هل تُشرعُ العقيقةُ بغير الغنم كالإبل والبقر؟","chapter_ur":"","part_ar":"كتاب العقيقة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tahawi in Sharh al-Mushkil (1042) and al-Bayhaqi (9/301).","chapter_en":"Is the Birth Sacrifice Prescribed with Animals Other Than Sheep, Such as Camels and Cattle?","part_en":"Book of the Birth Sacrifice","group_ar":"","group_en":"","part_no":37,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn Abi Mulaykah said: A boy was born to ʿAbd al-Rahman ibn Abi Bakr, so it was said to ʿA’ishah: “O Mother of the Believers, offer a camel for him as the birth sacrifice.” She said: “Allah forbid. Rather, what did the Messenger of Allah ﷺ say? ‘Two equal sheep.’”"]}},"tuhfa":{},"refs":[{"key":"sh22547","label":"الطحاوي في شرح المشكل","number":1042,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":9},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":19280,"n":19438}],"full":1,"dr":1},{"num":7240,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ عَقَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْحَسَنِ وَالْحُسَيْنِ رَضِيَ اللَّهُ عَنْهُمَا بِكَبْشَيْنِ كَبْشَيْنِ."],"takhrij":"صحيح: رواه النسائي (4219) عن أحمد بن حفص بن عبدالله قال: حدثني أبي قال: حدثني إبراهيم هو ابن طهمان، عن الحجاج بن الحجاج، عن قتادة، عن عكرمة، عن ابن عباس فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب في عقيقة النبي ﷺ عن الحسن والحسين","chapter_ur":"","part_ar":"كتاب العقيقة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (4219).","chapter_en":"The Prophet’s Birth Sacrifice for al-Hasan and al-Husayn","part_en":"Book of the Birth Sacrifice","group_ar":"","group_en":"","part_no":37,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ offered the birth sacrifice for al-Hasan and al-Husayn, may Allah be pleased with them both, with two rams each."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4219,"lafz":true,"n":4219}],"full":1,"dr":1},{"num":7241,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَقَّ عَنِ الْحَسَنِ وَالْحُسَيْنِ."],"takhrij":"حسن: رواه أبوبكر بن أبي شيبة (24714) - وعنه أبو يعلى (1933)-، والطبراني في الكبير (2573) من طريق شبابة بن سوار، عن المغيرة بن مسلم، عن أبي الزبير، عن جابر، فذكره.","grade":"حسن","chapter_ar":"باب في عقيقة النبي ﷺ عن الحسن والحسين","chapter_ur":"","part_ar":"كتاب العقيقة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Bakr ibn Abi Shaybah (24714), and from him Abu Yaʿla (1933), and al-Tabarani in al-Kabir (2573).","chapter_en":"The Prophet’s Birth Sacrifice for al-Hasan and al-Husayn","part_en":"Book of the Birth Sacrifice","group_ar":"","group_en":"","part_no":37,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Jabir narrated that the Prophet ﷺ offered the birth sacrifice for al-Hasan and al-Husayn."]}},"tuhfa":{},"refs":[{"key":"sh9944","label":"أبو بكر بن أبي شيبة","number":24714},{"key":"sh12520","label":"عنه أبو يعلى","number":1933,"lafz":true},{"key":"mujamkabir","label":"الطبراني في الكبير","number":2573,"n":2559}],"full":1,"dr":1},{"num":7242,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الحصيب: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عقَّ عَنِ الْحَسَنِ وَالْحُسَيْنِ."],"takhrij":"حسن: رواه النسائي (4213)، وأحمد (23001) من طريق حسين بن واقد، حدثني عبدالله بن بريدة، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب في عقيقة النبي ﷺ عن الحسن والحسين","chapter_ur":"","part_ar":"كتاب العقيقة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4213) and Ahmad (23001).","chapter_en":"The Prophet’s Birth Sacrifice for al-Hasan and al-Husayn","part_en":"Book of the Birth Sacrifice","group_ar":"","group_en":"","part_no":37,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Buraydah ibn al-Husayb narrated that the Messenger of Allah ﷺ offered the birth sacrifice for al-Hasan and al-Husayn."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4213,"lafz":true,"n":4213},{"key":"ahmad","label":"مسند الإمام أحمد","number":23001,"n":23001}],"full":1,"dr":1},{"num":7243,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: عَقَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ حَسَنٍ وَحُسَيْنٍ يَوْمَ السَّابِعِ وَسَمَّاهُمَا، وَأَمَرَ أَنْ يُمَاطَ عَنْ رَأْسِهِ الأَذَى."],"takhrij":"حسن: رواه ابن حبان (5311)، والحاكم (4/237)، والبيهقي (9/299-300) كلهم من طريق عبدالله بن وهب، أخبرني محمد بن عمرو، عن ابن جريج، عن يحيى بن سعيد (هو الأنصاري) عن عمرة، عن عائشة، فذكرته.","grade":"حسن","chapter_ar":"باب في عقيقة النبي ﷺ عن الحسن والحسين","chapter_ur":"","part_ar":"كتاب العقيقة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Hibban (5311), al-Hakim (7588), and al-Bayhaqi (9/299–300).","chapter_en":"The Prophet’s Birth Sacrifice for al-Hasan and al-Husayn","part_en":"Book of the Birth Sacrifice","group_ar":"","group_en":"","part_no":37,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ offered the birth sacrifice for Hasan and Husayn on the seventh day, named them, and ordered that the harm be removed from their heads."]}},"tuhfa":{},"refs":[{"key":"kubrabayhaqi","label":"البيهقي","number":9},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1368,"n":1365},{"key":"hakim","label":"المستدرك على الصحيحين","number":7588,"n":7592},{"key":"ibnhibban","label":"ابن حبان","number":5311,"lafz":true}],"full":1,"dr":1},{"num":7244,"demo":false,"sanad":"","matn":["عَنْ أُمِّ كُرْزٍ، قَالَتْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْغُلاَمِ شَاتَانِ مِثْلاَنِ وَعَنِ الْجَارِيَةِ شَاةٌ."],"takhrij":"صحيح: رواه أبو داود (2836)، وأحمد (27143) كلاهما من حديث حماد بن زيد، عن عبيدالله بن أبي يزيد، عن سباع بن ثابت، عن أم كُرْز، فذكرته.","grade":"صحيح","chapter_ar":"باب عن الغلام شاتان، وعن الجارية شاة","chapter_ur":"","part_ar":"كتاب العقيقة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2836) and Ahmad (27143).","chapter_en":"For a Boy, Two Sheep; and for a Girl, One Sheep","part_en":"Book of the Birth Sacrifice","group_ar":"","group_en":"","part_no":37,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Umm Kurz said: The Messenger of Allah ﷺ said: “For a boy, two sheep; and for a girl, one sheep.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2836,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":27143,"n":27143}],"full":1,"dr":1},{"num":7245,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ يَزِيدَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْعَقِيقَةُ عَنِ الْغُلَامِ شَاتَانِ مُكَافَأَتَانِ، وَعَنِ الْجَارِيَةِ شَاةٌ."],"takhrij":"حسن: رواه الإمام أحمد (27582)، والطبراني (24/461) من طريق إسماعيل بن عياش، عن ثابت بن عجلان، عن مجاهد، عن أسماء فذكرته.","grade":"حسن","chapter_ar":"باب عن الغلام شاتان، وعن الجارية شاة","chapter_ur":"","part_ar":"كتاب العقيقة","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (27582) and al-Tabarani (24/461).","chapter_en":"For a Boy, Two Sheep; and for a Girl, One Sheep","part_en":"Book of the Birth Sacrifice","group_ar":"","group_en":"","part_no":37,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Asma’ bint Yazid narrated from the Prophet ﷺ that he said: “The birth sacrifice for a boy is two equal sheep, and for a girl, one sheep.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":27582,"lafz":true},{"key":"mujamkabir","label":"الطبراني","number":24}],"full":1,"dr":1},{"num":7246,"demo":false,"sanad":"","matn":["أَنَّ عَائِشَةَ أَخْبَرَتْهَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَهُمْ عَنِ الْغُلاَمِ شَاتَانِ مُكَافِئَتَانِ وَعَنِ الْجَارِيَةِ شَاةٌ."],"takhrij":"حسن: رواه الترمذي (1513)، وابن ماجه (3163)، وأحمد (24028) وابن حبان (5310) كلهم من طريق عبدالله بن عثمان ابن خُثيم، عن يوسف بن ماهك أنهم دخلوا على حفصة بنت عبدالرحمن فسألوها عن العقيقة فأخبرتهم أن عائشة أخبرتها فذكرته.","grade":"حسن","chapter_ar":"باب عن الغلام شاتان، وعن الجارية شاة","chapter_ur":"","part_ar":"كتاب العقيقة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1513), Ibn Majah (3163), and Ahmad (24028), and authenticated by Ibn Hibban (5310).","chapter_en":"For a Boy, Two Sheep; and for a Girl, One Sheep","part_en":"Book of the Birth Sacrifice","group_ar":"","group_en":"","part_no":37,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["ʿA’ishah narrated that the Messenger of Allah ﷺ commanded them: for a boy, two equal sheep; and for a girl, one sheep."]},"buhuth":{"en":["Al-Tirmidhi said: “A Hasan Sahih hadith.” His statement, “two equal sheep,” means equal in age; and it was said: close to each other in age."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1513,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":3163},{"key":"ibnhibban","label":"صححه ابن حبان","number":5310},{"key":"ahmad","label":"مسند الإمام أحمد","number":24028,"n":24028},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1370,"n":1364}],"full":1,"dr":1},{"num":7247,"demo":false,"sanad":"","matn":["عَنْ أَبِي رَافِعٍ مَوْلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّ الْحَسَنَ بْنَ عَلِيٍّ لَمَّا وُلِدَ أَرَادَتْ أُمُّهُ فَاطِمَةُ أَنْ تَعُقَّ عَنْهُ بِكَبْشَيْنِ، فَقَالَ: لَا تَعُقِّي عَنْهُ، وَلَكِنْ احْلِقِي شَعْرَ رَأْسِهِ، ثُمَّ تَصَدَّقِي بِوَزْنِهِ مِنَ الْوَرِقِ فِي سَبِيلِ اللَّهِ، ثُمَّ وُلِدَ حُسَيْنٌ بَعْدَ ذَلِكَ فَصَنَعَتْ مِثْلَ ذَلِكَ."],"takhrij":"حسن: رواه الإمام أحمد (27196)، والطبراني (917، 918) والبيهقي (9/304) كلهم من طرق عن عبدالله بن محمد بن عقيل، عن علي بن الحسين، عن أبي رافع فذكره.","grade":"حسن","chapter_ar":"باب حلق شعر المولود والتصدق بوزنه فضة","chapter_ur":"","part_ar":"كتاب العقيقة","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (27196), al-Tabarani (918, 917), and al-Bayhaqi (9/304).","chapter_en":"Shaving the Newborn’s Hair and Giving Its Weight in Silver as Charity","part_en":"Book of the Birth Sacrifice","group_ar":"","group_en":"","part_no":37,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Abu Rafiʿ, the freedman of the Messenger of Allah ﷺ, narrated that when al-Hasan ibn ʿAli was born, his mother Fatimah wanted to offer two rams as a birth sacrifice for him. He said: “Do not offer the birth sacrifice for him, but shave the hair of his head, then give its weight in silver as charity in the way of Allah.” Then al-Husayn was born after that, and she did the same."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":27196,"lafz":true},{"key":"mujamkabir","label":"الطبراني","number":918},{"key":"kubrabayhaqi","label":"البيهقي","number":9}],"full":1,"dr":1},{"num":7248,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ كَانَ ابْنٌ لأَبِي طَلْحَةَ يَشْتَكِي، فَخَرَجَ أَبُو طَلْحَةَ، فَقُبِضَ الصَّبِيُّ فَلَمَّا رَجَعَ أَبُو طَلْحَةَ قَالَ مَا فَعَلَ ابْنِي قَالَتْ أُمُّ سُلَيْمٍ هُوَ أَسْكَنُ مَا كَانَ. فَقَرَّبَتْ إِلَيْهِ الْعَشَاءَ فَتَعَشَّى، ثُمَّ أَصَابَ مِنْهَا، فَلَمَّا فَرَغَ قَالَتْ وَارِ الصَّبِيَّ. فَلَمَّا أَصْبَحَ أَبُو طَلْحَةَ أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ فَقَالَ أَعْرَسْتُمُ اللَّيْلَةَ. قَالَ نَعَمْ. قَالَ اللَّهُمَّ بَارِكْ لَهُمَا. فَوَلَدَتْ غُلاَمًا قَالَ لِي أَبُو طَلْحَةَ احْفَظْهُ حَتَّى تَأْتِيَ بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَتَى بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَرْسَلَتْ مَعَهُ بِتَمَرَاتٍ، فَأَخَذَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ أَمَعَهُ شَىْءٌ. قَالُوا نَعَمْ تَمَرَاتٌ. فَأَخَذَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَمَضَغَهَا، ثُمَّ أَخَذَ مِنْ فِيهِ فَجَعَلَهَا فِي فِي الصَّبِيِّ، وَحَنَّكَهُ بِهِ، وَسَمَّاهُ عَبْدَ."],"takhrij":"متفق عليه: رواه البخاري في العقيقة (5470)، ومسلم في الآداب (23:2144) كلاهما من طريق يزيد بن هارون، أخبرنا عبدالله بن عون، عن أنس بن سيرين، عن أنس بن مالك، فذكره. والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تحنيك المولود وتسميته والدعاء له عند ولادته","chapter_ur":"","part_ar":"كتاب العقيقة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5470) and Muslim (2144:23). The wording is from al-Bukhari.","chapter_en":"What Has Been Reported Concerning Rubbing the Newborn’s Palate, Naming Him, and Supplicating for Him at Birth","part_en":"Book of the Birth Sacrifice","group_ar":"","group_en":"","part_no":37,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Anas ibn Malik said: A son of Abu Talhah was ill, and Abu Talhah went out. The child then died. When Abu Talhah returned, he said: “What happened to my son?” Umm Sulaym said: “He is calmer than he has ever been.” She brought dinner near to him, and he ate. Then he had relations with her. When he finished, she said: “Bury the child.” In the morning, Abu Talhah came to the Messenger of Allah ﷺ and informed him. He said: “Did you spend the night together?” He said: “Yes.” He said: “O Allah, bless them in their night.” She then gave birth to a boy. Abu Talhah said to me: “Keep him safe until you bring him to the Prophet ﷺ.” So he brought him to the Prophet ﷺ, and she sent some dates with him. The Prophet ﷺ took him and said: “Is there anything with him?” They said: “Yes, some dates.” The Prophet ﷺ took them, chewed them, then took from his mouth and placed it in the child’s mouth, rubbing his palate with it, and he named him: “ʿAbdullah.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5470,"lafz":true},{"key":"muslim","label":"مسلم","number":23}],"full":1,"dr":1},{"num":7249,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهَا حَمَلَتْ بِعَبْدِ اللَّهِ بْنِ الزُّبَيْرِ بِمَكَّةَ قَالَتْ فَخَرَجْتُ وَأَنَا مُتِمٌّ، فَأَتَيْتُ الْمَدِينَةَ فَنَزَلْتُ قُبَاءً فَوَلَدْتُ بِقُبَاءٍ، ثُمَّ أَتَيْتُ بِهِ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَوَضَعْتُهُ فِي حَجْرِهِ، ثُمَّ دَعَا بِتَمْرَةٍ فَمَضَغَهَا، ثُمَّ تَفَلَ فِي فِيهِ فَكَانَ أَوَّلَ شَىْءٍ دَخَلَ جَوْفَهُ رِيقُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ حَنَّكَهُ بِالتَّمْرَةِ، ثُمَّ دَعَا لَهُ فَبَرَّكَ عَلَيْهِ، وَكَانَ أَوَّلَ مَوْلُودٍ وُلِدَ فِي الإِسْلاَمِ، فَفَرِحُوا بِهِ فَرَحًا شَدِيدًا، لأَنَّهُمْ قِيلَ لَهُمْ إِنَّ الْيَهُودَ قَدْ سَحَرَتْكُمْ فَلاَ يُولَدُ لَكُمْ."],"takhrij":"متفق عليه: رواه البخاري في العقيقة (5469)، ومسلم في الآداب (26:2146) كلاهما من طريق أبي أسامة، حدثنا هشام بن عروة، عن أبيه، عن أسماء بنت أبي بكر، قالت: فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تحنيك المولود وتسميته والدعاء له عند ولادته","chapter_ur":"","part_ar":"كتاب العقيقة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5469) and Muslim (2146:26).","chapter_en":"What Has Been Reported Concerning Rubbing the Newborn’s Palate, Naming Him, and Supplicating for Him at Birth","part_en":"Book of the Birth Sacrifice","group_ar":"","group_en":"","part_no":37,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Asma’ bint Abi Bakr narrated that she became pregnant with ʿAbdullah ibn al-Zubayr in Makkah. She said: I left while I was at full term and came to Madinah, then stopped at Quba’ and gave birth at Quba’. Then I brought him to the Messenger of Allah ﷺ and placed him in his lap. He called for a date, chewed it, then spat into his mouth. So the first thing that entered his stomach was the saliva of the Messenger of Allah ﷺ. Then he rubbed his palate with the date, supplicated for him, and invoked blessing upon him. He was the first child born in Islam. They rejoiced greatly over him, because they had been told: “The Jews have cast a spell on you, so no child will be born to you.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5469,"lafz":true},{"key":"muslim","label":"مسلم","number":26}],"full":1},{"num":7250,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ أَوَّلُ مَوْلُودٍ وُلِدَ فِي الإِسْلاَمِ عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ، أَتَوْا بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخَذَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَمْرَةً فَلاَكَهَا ثُمَّ أَدْخَلَهَا فِي فِيهِ، فَأَوَّلُ مَا دَخَلَ بَطْنَهُ رِيقُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.","وفي رواية: جئنا بعبدالله بن الزبير إلى النبي صلى الله عليه وسلم يحنكه، فطلبنا تمرةً، فعزَّ علينا طلبهُا."],"takhrij":"متفق عليه: رواه البخاري في مناقب الأنصار (3910) من طريق أبي أسامة، عن هشام بن عروة، عن أبيه، عن عائشة، فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تحنيك المولود وتسميته والدعاء له عند ولادته","chapter_ur":"","part_ar":"كتاب العقيقة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3910) and Muslim (2148:28).","chapter_en":"What Has Been Reported Concerning Rubbing the Newborn’s Palate, Naming Him, and Supplicating for Him at Birth","part_en":"Book of the Birth Sacrifice","group_ar":"","group_en":"","part_no":37,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["ʿA’ishah, the wife of the Prophet ﷺ, said: The first newborn in Islam was ʿAbdullah ibn al-Zubayr. They brought him to the Prophet ﷺ, so the Prophet ﷺ took a date, chewed it, then put it into his mouth. Thus, the first thing that entered his stomach was the saliva of the Prophet ﷺ. In another narration: We brought ʿAbdullah ibn al-Zubayr to the Prophet ﷺ so he could rub his palate, and we searched for a date, but it was hard for us to find one."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3910,"lafz":true},{"key":"muslim","label":"مسلم","number":28}],"full":1,"dr":1},{"num":7251,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُؤْتَى بِالصِّبْيَانِ فَيُبَرِّكُ عَلَيْهِمْ وَيُحَنِّكُهُمْ فَأُتِيَ بِصَبِيٍّ فَبَالَ عَلَيْهِ فَدَعَا بِمَاءٍ فَأَتْبَعَهُ بَوْلَهُ وَلَمْ يَغْسِلْهُ."],"takhrij":"متفق عليه: رواه البخاري في العقيقة (5468) من طريق يحيى- ومسلم في الطهارة (101:286) من طريق عبدالله بن نمير- كلاهما عن هشام، عن أبيه، عن عائشة فذكرته. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تحنيك المولود وتسميته والدعاء له عند ولادته","chapter_ur":"","part_ar":"كتاب العقيقة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5468) and Muslim (286:101). The wording is from Muslim.","chapter_en":"What Has Been Reported Concerning Rubbing the Newborn’s Palate, Naming Him, and Supplicating for Him at Birth","part_en":"Book of the Birth Sacrifice","group_ar":"","group_en":"","part_no":37,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["ʿA’ishah, the wife of the Prophet ﷺ, narrated that children would be brought to the Messenger of Allah ﷺ, and he would invoke blessing upon them and rub their palates. A child was brought to him and urinated on him, so he called for water and poured it over the urine, but he did not wash it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5468,"lafz":true},{"key":"muslim","label":"مسلم","number":101}],"full":1,"dr":1},{"num":7252,"demo":false,"sanad":"","matn":["عن عُرْوَةَ بن الزُّبَيْرِ وفاطمة بِنْتُ المنذر بن الزُّبَيْرِ قالا أَنَّهُمَا قَالاَ خَرَجَتْ أَسْمَاءُ بِنْتُ أَبِي بَكْرٍ حِينَ هَاجَرَتْ وَهِيَ حُبْلَى بِعَبْدِ اللَّهِ بْنِ الزُّبَيْرِ فَقَدِمَتْ قُبَاءً فَنُفِسَتْ بِعَبْدِ اللَّهِ بِقُبَاءٍ ثُمَّ خَرَجَتْ حِينَ نُفِسَتْ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيُحَنِّكَهُ فَأَخَذَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْهَا فَوَضَعَهُ فِي حَجْرِهِ ثُمَّ دَعَا بِتَمْرَةٍ قَالَ قَالَتْ عَائِشَةُ فَمَكَثْنَا سَاعَةً نَلْتَمِسُهَا قَبْلَ أَنْ نَجِدَهَا فَمَضَغَهَا ثُمَّ بَصَقَهَا فِي فِيهِ فَإِنَّ أَوَّلَ شَىْءٍ دَخَلَ بَطْنَهُ لَرِيقُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ قَالَتْ أَسْمَاءُ ثُمَّ مَسَحَهُ وَصَلَّى عَلَيْهِ وَسَمَّاهُ عَبْدَ اللَّهِ ثُمَّ جَاءَ وَهُوَ ابْنُ سَبْعِ سِنِينَ أَوْ ثَمَانٍ لِيُبَايِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَمَرَهُ بِذَلِكَ الزُّبَيْرُ فَتَبَسَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ رَآهُ مُقْبِلاً إِلَيْهِ ثُمَّ بَايَعَهُ."],"takhrij":"صحيح: رواه مسلم في الآداب (25:2146) عن الحكم بن موسى أبي صالح، حدثنا شعيب بن إسحاق، أخبرني هشام بن عروة، حدثني عروة بن الزبير وفاطمة بنت المنذر بن الزبير، قال، فذكراه.","grade":"صحيح","chapter_ar":"باب ما جاء في تحنيك المولود وتسميته والدعاء له عند ولادته","chapter_ur":"","part_ar":"كتاب العقيقة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2146:25).","chapter_en":"What Has Been Reported Concerning Rubbing the Newborn’s Palate, Naming Him, and Supplicating for Him at Birth","part_en":"Book of the Birth Sacrifice","group_ar":"","group_en":"","part_no":37,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["ʿUrwah ibn al-Zubayr and Fatimah bint al-Mundhir ibn al-Zubayr said: Asma’ bint Abi Bakr left when she migrated while she was pregnant with ʿAbdullah ibn al-Zubayr. She arrived at Quba’ and gave birth to ʿAbdullah at Quba’. Then, after giving birth, she went to the Messenger of Allah ﷺ so he could rub his palate. The Messenger of Allah ﷺ took him from her and placed him in his lap, then called for a date. ‘A’ishah said: We spent some time searching for it before we found it. He chewed it, then spat it into his mouth, so the first thing that entered his stomach was the saliva of the Messenger of Allah ﷺ. Then Asma’ said: Then he wiped him, prayed for him, and named him ʿAbdullah. Then he came when he was seven or eight years old to pledge allegiance to the Messenger of Allah ﷺ. Al-Zubayr had instructed him to do that, so the Messenger of Allah ﷺ smiled when he saw him coming toward him, then accepted his pledge."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":25,"lafz":true}],"full":1},{"num":7253,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ قَالَ وُلِدَ لِي غُلاَمٌ، فَأَتَيْتُ بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَمَّاهُ إِبْرَاهِيمَ، فَحَنَّكَهُ بِتَمْرَةٍ، وَدَعَا لَهُ بِالْبَرَكَةِ وَدَفَعَهُ إِلَىَّ، وَكَانَ أَكْبَرَ وَلَدِ أَبِي مُوسَى."],"takhrij":"متفق عليه: رواه البخاري في العقيقة (5467)، ومسلم في الآداب (24:2145) كلاهما من طريق أبي أسامة، حدثني بُريد، عن أبي بُرْدة، عن أبي موسى قال: فذكره .","grade":"متفق عليه","chapter_ar":"باب ما جاء في تحنيك المولود وتسميته والدعاء له عند ولادته","chapter_ur":"","part_ar":"كتاب العقيقة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5467) and Muslim (2145:24).","chapter_en":"What Has Been Reported Concerning Rubbing the Newborn’s Palate, Naming Him, and Supplicating for Him at Birth","part_en":"Book of the Birth Sacrifice","group_ar":"","group_en":"","part_no":37,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Abu Musa al-Ashʿari said: A boy was born to me, so I brought him to the Prophet ﷺ. He named him Ibrahim, rubbed his palate with a date, supplicated for blessing for him, and handed him back to me. He was the eldest child of Abu Musa."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5467,"lafz":true},{"key":"muslim","label":"مسلم","number":24}],"full":1,"rep":[14490]},{"num":7254,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ، بْنِ مَالِكٍ قَالَ ذَهَبْتُ بِعَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ الأَنْصَارِيِّ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ وُلِدَ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي عَبَاءَةٍ يَهْنَأُ بَعِيرًا لَهُ فَقَالَ هَلْ مَعَكَ تَمْرٌ. فَقُلْتُ نَعَمْ. فَنَاوَلْتُهُ تَمَرَاتٍ فَأَلْقَاهُنَّ فِي فِيهِ فَلاَكَهُنَّ ثُمَّ فَغَرَ فَا الصَّبِيِّ فَمَجَّهُ فِي فِيهِ فَجَعَلَ الصَّبِيُّ يَتَلَمَّظُهُ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حُبُّ الأَنْصَارِ التَّمْرَ. وَسَمَّاهُ عَبْدَ."],"takhrij":"صحيح: رواه مسلم في الآداب (22:2144) عن عبدالأعلى بن حماد، حدثنا حماد بن سلمة، عن ثابت البناني، عن أنس بن مالك، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تحنيك المولود وتسميته والدعاء له عند ولادته","chapter_ur":"","part_ar":"كتاب العقيقة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2144:22).","chapter_en":"What Has Been Reported Concerning Rubbing the Newborn’s Palate, Naming Him, and Supplicating for Him at Birth","part_en":"Book of the Birth Sacrifice","group_ar":"","group_en":"","part_no":37,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Anas said: I took ʿAbdullah ibn Abi Talhah al-Ansari to the Messenger of Allah ﷺ when he was born, while the Messenger of Allah ﷺ was wearing a cloak and applying tar to a camel of his. He said: “Do you have any dates with you?” I said: “Yes,” and handed him some dates. He put them into his mouth and chewed them. Then he opened the child’s mouth and placed some of the chewed date into it, and the child began moving it around in his mouth. The Messenger of Allah ﷺ said: “The Ansar love dates.” And he named him: “ʿAbdullah.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":22,"lafz":true}],"full":1,"dr":1},{"num":7255,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وُلِدَ لِيَ اللَّيْلَةَ غُلاَمٌ فَسَمَّيْتُهُ بِاسْمِ أَبِي إِبْرَاهِيمَ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2315) من طرق عن سليمان بن المغيرة، حدثنا ثابت البناني، عن أنس بن مالك فذكره في سياق أطول.","grade":"صحيح","chapter_ar":"باب ما جاء في تعجيل اسم المولود","chapter_ur":"","part_ar":"كتاب العقيقة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2315).","chapter_en":"What Has Been Reported Concerning Naming the Newborn Early","part_en":"Book of the Birth Sacrifice","group_ar":"","group_en":"","part_no":37,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ said: “A boy was born to me tonight, and I named him with the name of my father Ibrahim.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2315,"lafz":true}],"full":1,"dr":1},{"num":7256,"demo":false,"sanad":"","matn":["عن سهل بن سعد قال: أُتِيَ بالمنذر بْن أَبي أُسَيْد إِلَى النَّبِيِّصَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حين ولِد، فوضعه علَى فخذه -وأبو أُسَيْدٍ جالس- فلهَا النَّبِيُّصَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بشيء بين يديه، فأمر أَبُو أُسَيْد بابْنه، فاحتمل من فخذ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فاستـفاق النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فقال: أَيْنَ الصَّبِيُّ؟ فقال أَبُو أُسَيْد:ٍ قَلَّبْنَاهُ يا رسول الله. قال: ما اسْمه؟ قال: فلانٌ. قال: ولكن أَسْمِهِ المُنْذِرَ فسمَّاه يومئذ المُنْذِرَ."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6119)، ومسلم في الآداب (2149)كلاهما من طريق سعيد بن أبي مريم، حدثنا أبو غسان (هو محمد بن مطرف) حدثني أبوحازم، عن سهل بن سعد فذكره.","grade":"متفق عليه","chapter_ar":"باب اختيار الاسم الحسن للمولود","chapter_ur":"","part_ar":"كتاب العقيقة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6191) and Muslim (2149).","chapter_en":"Choosing a Good Name for the Newborn","part_en":"Book of the Birth Sacrifice","group_ar":"","group_en":"","part_no":37,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Sahl ibn Saʿd said: Al-Mundhir ibn Abi Usayd was brought to the Prophet ﷺ when he was born, so he placed him on his thigh while Abu Usayd was sitting. The Prophet ﷺ became occupied with something in front of him, so Abu Usayd ordered that his son be taken away, and he was lifted from the thigh of the Prophet ﷺ. Then the Prophet ﷺ noticed and said: “Where is the child?” Abu Usayd said: “We turned him away, O Messenger of Allah.” He said: “What is his name?” He said: “So-and-so.” He said: “Rather, his name is al-Mundhir.” So he named him al-Mundhir that day."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6191,"lafz":true},{"key":"muslim","label":"مسلم","number":2149},{"key":"bukhari","label":"البخاري في الادب","number":6119,"n":6191}],"full":1,"dr":1},{"num":7257,"demo":false,"sanad":"","matn":["عَنْ أَبِي ثَعْلَبَةَ الْخُشَنِيِّ، قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ إِنَّا بِأَرْضِ قَوْمٍ أَهْلِ الْكِتَابِ، أَفَنَأْكُلُ فِي آنِيَتِهِمْ وَبِأَرْضِ صَيْدٍ، أَصِيدُ بِقَوْسِي وَبِكَلْبِي الَّذِي لَيْسَ بِمُعَلَّمٍ، وَبِكَلْبِي الْمُعَلَّمِ، فَمَا يَصْلُحُ لِي قَالَ أَمَّا مَا ذَكَرْتَ مِنْ أَهْلِ الْكِتَابِ فَإِنْ وَجَدْتُمْ غَيْرَهَا فَلاَ تَأْكُلُوا فِيهَا، وَإِنْ لَمْ تَجِدُوا فَاغْسِلُوهَا وَكُلُوا فِيهَا، وَمَا صِدْتَ بِقَوْسِكَ فَذَكَرْتَ اسْمَ اللَّهِ فَكُلْ، وَمَا صِدْتَ بِكَلْبِكَ الْمُعَلَّمِ فَذَكَرْتَ اسْمَ اللَّهِ فَكُلْ، وَمَا صِدْتَ بِكَلْبِكَ غَيْرَ مُعَلَّمٍ فَأَدْرَكْتَ ذَكَاتَهُ فَكُلْ."],"takhrij":"متفق عليه: رواه البخاري في الذبائح والصيد (5478)، ومسلم في الصيد والذبائح (1930: 8) كلاهما من طريق حيوة بن شريح، قال سمعت ربيعة بن يزيد الدمشقي يقول: أخبرني أبو إدريس عائذ الله، قال: سمعتُ أبا ثعلبة الخشني يقول فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في صيد سباع البهائم والطيور المعلّمة","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5478) and Muslim (1930:8).","chapter_en":"What Has Been Reported Concerning Hunting with Trained Beasts and Birds of Prey","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الصيد","group_en":"Collection of What Has Been Reported Concerning Hunting","part_no":38,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Thaʿlabah al-Khushani said: I said: “O Prophet of Allah, we are in the land of a people from the People of the Book. Should we eat from their vessels? And we are in a land of hunting; I hunt with my bow, with my dog that is not trained, and with my trained dog. What is proper for me?” He said: “As for what you mentioned about the People of the Book, if you find other vessels, do not eat from theirs. If you do not find other vessels, then wash them and eat from them. Whatever you hunt with your bow and mention the Name of Allah over, eat. Whatever you hunt with your trained dog and mention the Name of Allah over, eat. And whatever you hunt with your untrained dog, if you reach it in time to slaughter it, then eat.”"]},"intro_majmu":{"ar":["قال اللّٰه تعالى:","(يَا أَيُّهَا الَّذِينَ آمَنُوا لَيَبْلُوَنَّكُمُ اللَّهُ بِشَيْءٍ مِنَ الصَّيْدِ تَنَالُهُ أَيْدِيكُمْ وَرِمَاحُكُمْ لِيَعْلَمَ اللَّهُ مَنْ يَخَافُهُ بِالْغَيْبِ فَمَنِ اعْتَدَى بَعْدَ ذَٰلِكَ فَلَهُ عَذَابٌ أَلِيمٌ) [سورة المائدة: ٩٤]","وقال تعالى:","(أُحِلَّ لَكُمْ صَيْدُ الْبَحْرِ وَطَعَامُهُ مَتَاعًا لَكُمْ وَلِلسَّيَّارَةِ وَحُرِّمَ عَلَيْكُمْ صَيْدُ الْبَرِّ مَا دُمْتُمْ حُرُمًا وَاتَّقُوا اللَّهَ الَّذِي إِلَيْهِ تُحْشَرُونَ) [سورة المائدة: ٩٦]","وقال أيضًا:","(وَإِذَا حَلَلْتُمْ فَاصْطَادُوا) [سورة المائدة: ٢]"],"en":["Allah the Exalted said:","“O you who believe, Allah will surely test you with something of game that your hands and spears can reach, so that Allah may make known who fears Him unseen. Whoever transgresses after that will have a painful punishment.” [Surah al-Ma’idah: 94]","And He said:","“Lawful for you is the game of the sea and its food as provision for you and for travelers, but forbidden to you is the game of the land as long as you are in a state of consecration. And fear Allah, to whom you will be gathered.” [Surah al-Ma’idah: 96]","And He also said:","“And when you come out of the state of consecration, then hunt.” [Surah al-Ma’idah: 2]"]},"intro":{"ar":["قال اللّٰه تعالى:","(يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ وَمَا عَلَّمْتُمْ مِنَ الْجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ اللَّهُ فَكُلُوا مِمَّا أَمْسَكْنَ عَلَيْكُمْ وَاذْكُرُوا اسْمَ اللَّهِ عَلَيْهِ وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ سَرِيعُ الْحِسَابِ) [سورة المائدة: ٤]","قال ابن جرير الطبري في تفسيره (١٠٦/٨): “كل ما صاد من الطير والسباع فمن الجوارح، وأنّ صيدَ جميع ذلك حلالٌ إذا صادَ بعد التعلم، لأن اللّٰه جلَّ ثناؤه عمّ بقوله: (وَمَا عَلَّمْتُمْ مِنَ الْجَوَارِحِ مُكَلِّبِينَ) كلَّ جارحة، ولم يخصص منها شيئًا. فكلُّ جارحةٍ كانت بالصفة التي وصف اللّٰه من كل طائرٍ وسبع، فحلالٌ أكلُ صيدها”. اهـ.","قلت: ومن الطيور الصقور والبازي، ومن السباع الكلاب والفهد.","قال ابن عبد البر في الاستذكار (٢٨٩/١٥): “لا أعلم في صيد سباع الطير المعلمة خلافًا، إنه جائز كالكلب المعلم سواء إلا مجاهد بن جبر، فإنه كان يكره صيد الطير، ويقول: إنما قال اللّٰه تعالى: (وَمَا عَلَّمْتُمْ مِنَ الْجَوَارِحِ مُكَلِّبِينَ) فإنما هي الكلاب”.","وخالفه عامّةُ العلماء قديماً وحديثاً فأجازوا الاصطياد بالبازي، والشوذنين، وسائر سباع الطير المعلمة."],"en":["Allah the Exalted said:","“They ask you what has been made lawful for them. Say: Lawful for you are the good things, and what you have trained of hunting animals, training them from what Allah has taught you. So eat from what they catch for you, and mention the Name of Allah over it. And fear Allah. Indeed, Allah is swift in reckoning.” [Surah al-Ma’idah: 4]","Ibn Jarir al-Tabari said in his commentary (8/106): “Every bird or beast that hunts is included among hunting animals, and the game of all of that is lawful if it hunts after being trained, because Allah, exalted is His praise, generalized in His statement, ‘and what you have trained of hunting animals,’ every hunting animal, and He did not specify any of them. So every hunting animal that has the description Allah mentioned, whether bird or beast, its catch is lawful to eat.” End quote.","I say: Among birds are falcons and hawks, and among beasts are dogs and cheetahs.","Ibn ʿAbd al-Barr said in al-Istidhkar (15/289): “I do not know of any disagreement concerning hunting with trained birds of prey, that it is permissible just like hunting with a trained dog, except for Mujahid ibn Jabr. He disliked hunting with birds and said: Allah the Exalted only said, ‘and what you have trained of hunting animals, training them as dogs are trained,’ so it refers only to dogs.","The general body of scholars, past and present, disagreed with him and permitted hunting with hawks, trained birds, and all other trained birds of prey."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5478,"lafz":true},{"key":"muslim","label":"مسلم","number":8},{"key":"muslim","label":"مسلم في الصيد والذبائح","number":1930}],"full":1},{"num":7258,"demo":false,"sanad":"","matn":["عَنْ عَدِيِّ بْنِ حَاتِمٍ، قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنِّي أُرْسِلُ الْكِلاَبَ الْمُعَلَّمَةَ فَيُمْسِكْنَ عَلَىَّ وَأَذْكُرُ اسْمَ اللَّهِ عَلَيْهِ فَقَالَ إِذَا أَرْسَلْتَ كَلْبَكَ الْمُعَلَّمَ وَذَكَرْتَ اسْمَ اللَّهِ عَلَيْهِ فَكُلْ. قُلْتُ وَإِنْ قَتَلْنَ قَالَ وَإِنْ قَتَلْنَ مَا لَمْ يَشْرَكْهَا كَلْبٌ لَيْسَ مَعَهَا. قُلْتُ لَهُ فَإِنِّي أَرْمِي بِالْمِعْرَاضِ الصَّيْدَ فَأُصِيبُ فَقَالَ إِذَا رَمَيْتَ بِالْمِعْرَاضِ فَخَزَقَ فَكُلْهُ وَإِنْ أَصَابَهُ بِعَرْضِهِ فَلاَ تَأْكُلْهُ."],"takhrij":"متفق عليه: رواه البخاري في الذبائح والصيد (5477)، ومسلم في الصيد والذبائح (1929:1) كلاهما من طريق منصور، عن إبراهيم، عن همام بن الحارث، عن عدي بن حاتم قال فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في صيد سباع البهائم والطيور المعلّمة","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5477) and Muslim (1929:1). The wording is from Muslim.","chapter_en":"What Has Been Reported Concerning Hunting with Trained Beasts and Birds of Prey","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الصيد","group_en":"Collection of What Has Been Reported Concerning Hunting","part_no":38,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["ʿAdi ibn Hatim said: I said: “O Messenger of Allah, I send trained dogs and they catch game for me, and I mention the Name of Allah over it.” He said: “When you send your trained dog and mention the Name of Allah over it, then eat.” I said: “Even if they kill it?” He said: “Even if they kill it, so long as another dog that was not with it did not share with it.” I said to him: “I shoot game with a broad-headed arrow and hit it.” He said: “If you shoot with the broad-headed arrow and it pierces, then eat it. But if it strikes it with its side, then do not eat it.”"]},"buhuth":{"en":["His statement, “with the broad-headed arrow”: several explanations have been given for it, but the well-known explanation is that it is a heavy piece of wood ending in a stick whose head may be sharpened, and may also be unsharpened.","His statement, “if it pierces”: it is said in Arabic that an arrow pierces when it penetrates what was shot."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5477,"lafz":true},{"key":"muslim","label":"مسلم","number":1929}],"full":1,"dr":1},{"num":7259,"demo":false,"sanad":"","matn":["عَنْ عَدِيِّ بْنِ حَاتِمٍ، قَالَ سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُلْتُ إِنَّا قَوْمٌ نَصِيدُ بِهَذِهِ الْكِلاَبِ. فَقَالَ إِذَا أَرْسَلْتَ كِلاَبَكَ الْمُعَلَّمَةَ وَذَكَرْتَ اسْمَ اللَّهِ، فَكُلْ مِمَّا أَمْسَكْنَ عَلَيْكُمْ، وَإِنْ قَتَلْنَ إِلاَّ أَنْ يَأْكُلَ الْكَلْبُ، فَإِنِّي أَخَافُ أَنْ يَكُونَ إِنَّمَا أَمْسَكَهُ عَلَى نَفْسِهِ، وَإِنْ خَالَطَهَا كِلاَبٌ مِنْ غَيْرِهَا فَلاَ تَأْكُلْ."],"takhrij":"متفق عليه: رواه البخاري في الذبائح والصيد (5483)، ومسلم في الصيد والذبائح (1929: 2) كلاهما من طريق محمد بن فضيل، عن بيان، عن الشعبي، عن عدي بن حاتم، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في صيد سباع البهائم والطيور المعلّمة","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5483) and Muslim (1929:2).","chapter_en":"What Has Been Reported Concerning Hunting with Trained Beasts and Birds of Prey","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الصيد","group_en":"Collection of What Has Been Reported Concerning Hunting","part_no":38,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["ʿAdi ibn Hatim said: I asked the Messenger of Allah ﷺ, saying: “We are a people who hunt with these dogs.” He said: “When you send your trained dogs and mention the Name of Allah, then eat from what they catch for you, even if they kill it, unless the dog eats from it. For I fear that it only caught it for itself. And if other dogs mix with them, then do not eat.”"]},"buhuth":{"en":["Al-Nawawi said: “This is explicit in prohibiting eating what the hunting animal has eaten from. This was the view of most scholars, including Ibn ʿAbbas, Abu Hurayrah, ʿAta’, Saʿid ibn Jubayr, al-Hasan, al-Shaʿbi, al-Nakhaʿi, ʿIkrimah, Qatadah, Abu Hanifah and his companions, Ahmad, Ishaq, Abu Thawr, Ibn al-Mundhir, Dawud… They used as evidence the statement of Allah the Exalted: ‘So eat from what they catch for you.’ This animal did not catch it for us; rather, it caught it for itself.” End quote. Sharh Muslim (13/75)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5483,"lafz":true},{"key":"muslim","label":"مسلم","number":2},{"key":"muslim","label":"بل على نفسه”.اه. شرح مسلم","number":75},{"key":"muslim","label":"مسلم في الصيد والذبائح","number":1929,"n":4973}],"full":1,"dr":1},{"num":7260,"demo":false,"sanad":"","matn":["عَنْ عَدِيِّ بْنِ حَاتِمٍ، قَالَ قُلْتُ يَا رَسُولَ اللَّهِ أَرْمِي الصَّيْدَ فَأَجِدُ فِيهِ مِنَ الْغَدِ سَهْمِي قَالَ إِذَا عَلِمْتَ أَنَّ سَهْمَكَ قَتَلَهُ وَلَمْ تَرَ فِيهِ أَثَرَ سَبُعٍ فَكُلْ."],"takhrij":"صحيح: رواه الترمذي (1468)، والنسائي (4312) من طريق شعبة- والنسائي (4311)، وأحمد (19369) من طريق هشيم- كلاهما عن أبي بشر، عن سعيد بن جبير، عن عدي بن حاتم، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في صيد سباع البهائم والطيور المعلّمة","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1468), al-Nasa’i (4312 and 4311), and Ahmad (19369). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"What Has Been Reported Concerning Hunting with Trained Beasts and Birds of Prey","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الصيد","group_en":"Collection of What Has Been Reported Concerning Hunting","part_no":38,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["ʿAdi ibn Hatim said: I said: “O Messenger of Allah, I shoot game and find my arrow in it the next day.” He said: “If you know that your arrow killed it, and you do not see the mark of a predator on it, then eat.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1468,"lafz":true},{"key":"nasai","label":"النسائي","number":4312},{"key":"ahmad","label":"مسند الإمام أحمد","number":19369,"n":19369},{"key":"nasai","label":"من طريق شعبه- والنسائي","number":4311}],"full":1,"dr":1},{"num":7261,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عمرو: أَنَّ أَعْرَابِيًّا يُقَالُ لَهُ: أَبُو ثَعْلَبَةَ قَالَ: يَا رَسُولَ اللَّهِ! إِنَّ لِي كِلاَبًا مُكَلَّبَةً فَأَفْتِنِي فِي صَيْدِهَا. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إنْ كَانَ لَكَ كِلاَبٌ مُكَلَّبَةٌ فَكُلْ مِمَّا أَمْسَكْنَ عَلَيْكَ. قَالَ: ذَكِيًّا أَوْ غَيْرَ ذَكِيٍّ؟ قَالَ: نَعَمْ. قَالَ: فَإِنْ أَكَلَ مِنْهُ قَالَ: وَإِنْ أَكَلَ مِنْهُ. قَالَ: يَا رَسُولَ اللَّهِ أَفْتِني فِي قوسى. قَالَ: كُلْ مَا رَدَّتْ عَلَيْكَ قَوْسُكَ. قَالَ: ذَكِيًّا أَوْ غَيْرَ ذَكِيٍّ. قَالَ: وَإِنْ تَغَيَّبَ عَنِّي؟ قَالَ: وَإِنْ تَغَيَّبَ عَنْكَ مَا لَمْ يَصِلَّ أَوْ تَجِدَ فِيهِ أَثَرًا غَيْرَ سَهْمِكَ. قَالَ أَفْتِني فِي آنِيَةِ الْمَجُوسِ إِذَا اضْطُرِرْنَا إِلَيْهَا؟ قَالَ: اِغْسِلْها وكُلْ فِيهَا."],"takhrij":"حسن: رواه أبوداود (2857)، وأحمد (6725)، والدارقطني (4797) كلهم من طريق حبيب المعلم، عن عمرو بن شعيب، عن أبيه، عن جده، فذكره. وإسناده حسن من أجل الكلام في عمرو بن شعيب غير أنه حسن الحديث.","grade":"حسن","chapter_ar":"باب من قال: يُباح أكل الصيد وإن أكل منه الكلب","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2857), Ahmad (6725), and al-Daraqutni (4797).","chapter_en":"Whoever Said It Is Permissible to Eat the Game Even If the Dog Ate from It","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الصيد","group_en":"Collection of What Has Been Reported Concerning Hunting","part_no":38,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr narrated that a Bedouin called Abu Thaʿlabah said: “O Messenger of Allah, I have trained hunting dogs, so give me a ruling about their game.” The Prophet ﷺ said: “If you have trained hunting dogs, then eat from what they catch for you.” He said: “Whether it is slaughtered or not slaughtered?” He said: “Yes.” He said: “Even if the dog eats from it?” He said: “Even if it eats from it.” He said: “O Messenger of Allah, give me a ruling about my bow.” He said: “Eat whatever your bow returns to you.” He said: “Whether it is slaughtered or not slaughtered?” He said: “Even if it disappears from me?” He said: “Even if it disappears from you, so long as it does not rot, or you do not find on it a mark other than your arrow.” He said: “Give me a ruling about the vessels of the Magians when we are forced to use them.” He said: “Wash them and eat in them.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2857,"lafz":true},{"key":"sh9771","label":"الدار قطني","number":4797},{"key":"ahmad","label":"مسند الإمام أحمد","number":6725,"n":6725}],"full":1,"dr":1},{"num":7262,"demo":false,"sanad":"","matn":["عَنْ أَبِي ثَعْلَبَةَ الْخُشَنِيِّ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي صَيْدِ الْكَلْبِ إِذَا أَرْسَلْتَ كَلْبَكَ وَذَكَرْتَ اسْمَ اللَّهِ فَكُلْ وَإِنْ أَكَلَ مِنْهُ وَكُلْ مَا رَدَّتْ عَلَيْكَ يَدَاكَ."],"takhrij":"حسن: رواه أبوداود (2852) عن محمد بن عيسى، ثنا هشيم، ثنا داود بن عمرو، عن بُسر بن عبيد الله، عن أبي إدريس الخولاني، عن أبي ثعلبة الخشني فذكره. وأخرجه البيهقي (9/237) من طريق أبي داود.","grade":"حسن","chapter_ar":"باب من قال: يُباح أكل الصيد وإن أكل منه الكلب","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2852) and al-Bayhaqi (9/237).","chapter_en":"Whoever Said It Is Permissible to Eat the Game Even If the Dog Ate from It","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الصيد","group_en":"Collection of What Has Been Reported Concerning Hunting","part_no":38,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abu Thaʿlabah al-Khushani said: The Messenger of Allah ﷺ said concerning the game of the dog: “When you send your dog and mention the Name of Allah the Exalted, then eat, even if it ate from it. And eat whatever your hand returns to you.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2852,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":237},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":18883,"n":19041}],"full":1,"dr":1},{"num":7263,"demo":false,"sanad":"","matn":["عَنْ عَدِيِّ بْنِ حَاتِمٍ رَضِيَ اللَّهُ عَنْهُ قَالَ سَأَلْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ صَيْدِ الْمِعْرَاضِ قَالَ مَا أَصَابَ بِحَدِّهِ فَكُلْهُ، وَمَا أَصَابَ بِعَرْضِهِ فَهْوَ وَقِيذٌ. وَسَأَلْتُهُ عَنْ صَيْدِ الْكَلْبِ فَقَالَ مَا أَمْسَكَ عَلَيْكَ فَكُلْ، فَإِنَّ أَخْذَ الْكَلْبِ ذَكَاةٌ، وَإِنْ وَجَدْتَ مَعَ كَلْبِكَ أَوْ كِلاَبِكَ كَلْبًا غَيْرَهُ فَخَشِيتَ أَنْ يَكُونَ أَخَذَهُ مَعَهُ، وَقَدْ قَتَلَهُ، فَلاَ تَأْكُلْ، فَإِنَّمَا ذَكَرْتَ اسْمَ اللَّهِ عَلَى كَلْبِكَ وَلَمْ تَذْكُرْهُ عَلَى غَيْرِهِ."],"takhrij":"متفق عليه: رواه البخاري في الذبائح والصيد (5475)، ومسلم في الصيد والذبائح (1929: 4) كلاهما من طريق زكريا، عن عامر الشعبي، عن عدي بن حاتم فذكره.","grade":"متفق عليه","chapter_ar":"باب إذا وجد مع الصيد كلبا آخر","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5475) and Muslim (1929:4).","chapter_en":"If Another Dog Is Found with the Game","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الصيد","group_en":"Collection of What Has Been Reported Concerning Hunting","part_no":38,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["ʿAdi ibn Hatim said: I asked the Prophet ﷺ about game hunted with a broad-headed arrow. He said: “What it strikes with its sharp edge, eat; and what it strikes with its side is an animal killed by impact.” I also asked him about game hunted by a dog. He said: “What it catches for you, eat, for the dog’s catching is its slaughter. If you find with your dog or your dogs another dog, and you fear that it caught it with it and killed it, then do not eat, for you mentioned the Name of Allah over your dog, and you did not mention it over the other one.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5475,"lafz":true},{"key":"muslim","label":"مسلم","number":4},{"key":"muslim","label":"مسلم في الصيد والذبائح","number":1929,"n":4977}],"full":1},{"num":7264,"demo":false,"sanad":"","matn":["عَنْ عَدِيِّ بْنِ حَاتِمٍ، أَنَّهُ سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الصَّيْدِ فَقَالَ إِذَا أَرْسَلْتَ كَلْبَكَ فَخَالَطَتْهُ أَكْلُبٌ لَمْ تُسَمِّ عَلَيْهَا فَلاَ تَأْكُلْ فَإِنَّكَ لاَ تَدْرِي أَيَّهَا قَتَلَهُ."],"takhrij":"صحيح: رواه النسائي (4268)، وأحمد (18259) كلاهما من طريق معمر، عن عاصم بن سليمان، عن عامر الشعبي، عن عدي بن حاتم، فذكره.","grade":"صحيح","chapter_ar":"باب إذا وجد مع الصيد كلبا آخر","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (4268) and Ahmad (18259).","chapter_en":"If Another Dog Is Found with the Game","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الصيد","group_en":"Collection of What Has Been Reported Concerning Hunting","part_no":38,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["ʿAdi ibn Hatim narrated that he asked the Messenger of Allah ﷺ about hunting, and he said: “If you send your dog and other dogs over which you did not mention the Name of Allah mix with it, then do not eat, for you do not know which of them killed it.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4268,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":18259,"n":18259}],"full":1,"dr":1},{"num":7265,"demo":false,"sanad":"","matn":["عَنْ عَدِيِّ بْنِ حَاتِمٍ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِذَا أَرْسَلْتَ كَلْبَكَ وَسَمَّيْتَ فَأَمْسَكَ وَقَتَلَ، فَكُلْ، وَإِنْ أَكَلَ فَلاَ تَأْكُلْ، فَإِنَّمَا أَمْسَكَ عَلَى نَفْسِهِ، وَإِذَا خَالَطَ كِلاَبًا لَمْ يُذْكَرِ اسْمُ اللَّهِ عَلَيْهَا فَأَمْسَكْنَ وَقَتَلْنَ فَلاَ تَأْكُلْ، فَإِنَّكَ لاَ تَدْرِي أَيُّهَا قَتَلَ، وَإِنْ رَمَيْتَ الصَّيْدَ فَوَجَدْتَهُ بَعْدَ يَوْمٍ أَوْ يَوْمَيْنِ، لَيْسَ بِهِ إِلاَّ أَثَرُ سَهْمِكَ، فَكُلْ، وَإِنْ وَقَعَ فِي الْمَاءِ فَلاَ تَأْكُلْ."],"takhrij":"متفق عليه: رواه البخاري في الصيد والذبائح (5484)، ومسلم في الصيد والذبائح (1929: 6) كلاهما من طريق عاصم، عن الشعبي، عن عدي بن حاتم فذكره. واللفظ للبخاري، ولفظ مسلم : فإنْ غاب عنك يوما.","grade":"متفق عليه","chapter_ar":"باب إذا وجد مع الصيد كلبا آخر","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5484) and Muslim (1929:6). The wording is from al-Bukhari. The wording of Muslim is: “If it disappears from you for a day.”","chapter_en":"If Another Dog Is Found with the Game","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الصيد","group_en":"Collection of What Has Been Reported Concerning Hunting","part_no":38,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["ʿAdi ibn Hatim narrated from the Prophet ﷺ that he said: “When you send your dog and mention the Name of Allah, and it catches and kills, then eat. If it eats from it, then do not eat, for it only caught it for itself. If other dogs over which the Name of Allah was not mentioned mix with it, and they catch and kill, then do not eat, for you do not know which of them killed it. If you shoot game and find it after a day or two, with nothing on it except the mark of your arrow, then eat. But if it fell into water, do not eat.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5484,"lafz":true},{"key":"muslim","label":"مسلم","number":6},{"key":"muslim","label":"مسلم في الصيد والذبائح","number":1929}],"full":1,"dr":1},{"num":7266,"demo":false,"sanad":"","matn":["عَنْ عَدِيٍّ، أَنَّهُ قَالَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَرْمِي الصَّيْدَ فَيَقْتَفِرُ أَثَرَهُ الْيَوْمَيْنِ وَالثَّلاَثَةَ، ثُمَّ يَجِدُهُ مَيِّتًا وَفِيهِ سَهْمُهُ قَالَ يَأْكُلُ إِنْ شَاءَ."],"takhrij":"صحيح: رواه البخاري في الذبائح والصيد (5485) تعليقاً قال: وقال عبدالأعلى: عن داود (هو ابن أبي هند)، عن عامر (هو الشعبي) عن عدي فذكره. ووصله أبوداود (2853) عن الحسين بن معاذ بن خُليف، قال: حدثنا عبدالأعلى به مثله.","grade":"صحيح","chapter_ar":"باب إذا وجد مع الصيد كلبا آخر","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5485) in suspended form. Abu Dawud (2853) connected its chain.","chapter_en":"If Another Dog Is Found with the Game","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الصيد","group_en":"Collection of What Has Been Reported Concerning Hunting","part_no":38,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["ʿAdi said to the Prophet ﷺ: “A person shoots game and follows its track for two or three days, then finds it dead with his arrow in it?” He said: “He may eat if he wishes.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5485,"lafz":true},{"key":"abudawud","label":"تعليقاً. ووصله أبو داود","number":2853}],"full":1,"dr":1},{"num":7267,"demo":false,"sanad":"","matn":["عَنْ أَبِي ثَعْلَبَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِذَا رَمَيْتَ بِسَهْمِكَ فَغَابَ عَنْكَ فَأَدْرَكْتَهُ فَكُلْهُ مَا لَمْ يُنْتِنْ.","وفي رواية: في الذي يدرك صيده بعد ثلاث: فكُلْه ما لم يُنتِنْ.","وزاد في رواية: وسهمك فيه."],"takhrij":"صحيح: رواه مسلم في الصيد والذبائح (1931: 9) عن محمد بن مهران الرازي، حدثنا أبوعبدالله حماد بن خالد الخيّاط، عن معاوية بن صالح، عن عبدالرحمن بن جُبير، عن أبيه، عن أبي ثعلبة، فذكره.","grade":"صحيح","chapter_ar":"باب إذا وجد مع الصيد كلبا آخر","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1931:9).","chapter_en":"If Another Dog Is Found with the Game","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الصيد","group_en":"Collection of What Has Been Reported Concerning Hunting","part_no":38,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Abu Thaʿlabah al-Khushani narrated from the Prophet ﷺ that he said: “When you shoot with your arrow and it disappears from you, then you find it, eat it as long as it has not become foul.” In another narration, regarding one who finds his game after three days: “Eat it as long as it has not become foul.”","Another narration adds: “And your arrow is in it.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":9,"lafz":true},{"key":"muslim","label":"مسلم في الصيد والذبائح","number":1931}],"full":1,"dr":1},{"num":7268,"demo":false,"sanad":"","matn":["عَنْ عَدِيِّ بْنِ حَاتِمٍ، قَالَ سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الصَّيْدِ قَالَ إِذَا رَمَيْتَ سَهْمَكَ فَاذْكُرِ اسْمَ اللَّهِ فَإِنْ وَجَدْتَهُ قَدْ قَتَلَ فَكُلْ إِلاَّ أَنْ تَجِدَهُ قَدْ وَقَعَ فِي مَاءٍ فَإِنَّكَ لاَ تَدْرِي الْمَاءُ قَتَلَهُ أَوْ سَهْمُكَ."],"takhrij":"متفق عليه: رواه البخاري في الذبائح والصيد (5484)، ومسلم في الصيد (1929: 7) كلاهما من طريق عاصم، عن الشعبي، عن عدي بن حاتم، فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب الصيد يوجد ميتا في الماء","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5484) and Muslim (1929:7). The wording is from Muslim.","chapter_en":"Game Found Dead in Water","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الصيد","group_en":"Collection of What Has Been Reported Concerning Hunting","part_no":38,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["ʿAdi ibn Hatim said: I asked the Messenger of Allah ﷺ about hunting. He said: “When you shoot your arrow, mention the Name of Allah. If you find that it has killed it, then eat, unless you find that it has fallen into water, for you do not know whether the water killed it or your arrow.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5484,"lafz":true},{"key":"muslim","label":"مسلم","number":7},{"key":"muslim","label":"مسلم في الصيد","number":1929,"n":4982}],"full":1},{"num":7269,"demo":false,"sanad":"","matn":["عن عَدِيِّ بْنِ حَاتِمٍ رَضِيَ اللَّهُ عَنْهُ قَالَ سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمِعْرَاضِ فَقَالَ إِذَا أَصَبْتَ بِحَدِّهِ فَكُلْ، فَإِذَا أَصَابَ بِعَرْضِهِ فَقَتَلَ فَإِنَّهُ وَقِيذٌ، فَلاَ تَأْكُلْ."],"takhrij":"متفق عليه: رواه البخاري في الذبائح والصيد (5476)، ومسلم في الصيد والذبائح (1929: 3) كلاهما من طريق شعبة، عن عبد الله بن أبي السفر، عن الشعبي قال: سمعتُ عدي بن حاتم، فذكره.","grade":"متفق عليه","chapter_ar":"باب ماجاء في صيد المعراض والحجر","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5476) and Muslim (1929:3).","chapter_en":"What Has Been Reported Concerning Hunting with a Broad-Headed Arrow and a Stone","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الصيد","group_en":"Collection of What Has Been Reported Concerning Hunting","part_no":38,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["ʿAdi ibn Hatim said: I asked the Messenger of Allah ﷺ about the broad-headed arrow. He said: “If you hit with its sharp edge, then eat. But if it strikes with its side and kills, then it is an animal killed by impact, so do not eat.”"]},"buhuth":{"en":["His statement, “killed by impact,” is a word on the pattern of “faʿil” with the meaning of “mafʿul.” It refers to what is killed by a stick, stone, or anything without a sharp edge."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5476,"lafz":true},{"key":"muslim","label":"مسلم","number":3},{"key":"muslim","label":"مسلم في الصيد والذبائح","number":1929,"n":4974}],"full":1,"dr":1},{"num":7270,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ، أَنَّهُ رَأَى رَجُلاً يَخْذِفُ فَقَالَ لَهُ لاَ تَخْذِفْ فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْخَذْفِ ـ أَوْ كَانَ يَكْرَهُ الْخَذْفَ ـ وَقَالَ إِنَّهُ لاَ يُصَادُ بِهِ صَيْدٌ وَلاَ يُنْكَى بِهِ عَدُوٌّ، وَلَكِنَّهَا قَدْ تَكْسِرُ السِّنَّ وَتَفْقَأُ الْعَيْنَ. ثُمَّ رَآهُ بَعْدَ ذَلِكَ يَخْذِفُ فَقَالَ لَهُ أُحَدِّثُكَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ نَهَى عَنِ الْخَذْفِ. أَوْ كَرِهَ الْخَذْفَ، وَأَنْتَ تَخْذِفُ لاَ أُكَلِّمُكَ كَذَا وَكَذَا."],"takhrij":"متفق عليه: رواه البخاري في الذبائح والصيد (5479)، ومسلم في الصيد والذبائح (1954: 54) كلاهما من طريق كهمس بن الحسن، عن عبدالله بن بريدة، عن عبدالله بن مغفل فذكره.","grade":"متفق عليه","chapter_ar":"باب ماجاء في صيد المعراض والحجر","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5479) and Muslim (1954:54).","chapter_en":"What Has Been Reported Concerning Hunting with a Broad-Headed Arrow and a Stone","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الصيد","group_en":"Collection of What Has Been Reported Concerning Hunting","part_no":38,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullah ibn Mughaffal saw a man throwing small pebbles with his fingers. He said to him: “Do not throw pebbles in that way, for the Messenger of Allah ﷺ forbade it, or disliked it.” He said: “It does not hunt game, nor does it harm an enemy, but it may break a tooth and put out an eye.” Then he saw him later doing it again and said to him: “I narrate to you from the Messenger of Allah ﷺ that he forbade throwing pebbles in that way — or disliked it — and you still do it? I will not speak to you for such-and-such.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5479,"lafz":true},{"key":"muslim","label":"مسلم","number":54},{"key":"muslim","label":"مسلم في الصيد والذبائح","number":1954}],"full":1},{"num":7271,"demo":false,"sanad":"","matn":["عن هِشَامِ بن زَيْدٍ بن أَنَسٍ بْنِ مَالِكٍ قَالَ دَخَلْتُ مَعَ جَدِّي أَنَسِ بْنِ مَالِكٍ دَارَ الْحَكَمِ بْنِ أَيُّوبَ فَإِذَا قَوْمٌ قَدْ نَصَبُوا دَجَاجَةً يَرْمُونَهَا قَالَ فَقَالَ أَنَسٌ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تُصْبَرَ الْبَهَائِمُ."],"takhrij":"متفق عليه: رواه البخاري في الذبائح والصيد (5512)، ومسلم في الصيد والذبائح (1956) كلاهما من طريق شعبة قال: سمعت هشام بن يزيد بن أنس بن مالك قال فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن صبر البهائم ورميها","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5512) and Muslim (1956). The wording is from Muslim.","chapter_en":"The Prohibition of Restraining Animals and Shooting at Them","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الصيد","group_en":"Collection of What Has Been Reported Concerning Hunting","part_no":38,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Hisham ibn Zayd ibn Anas ibn Malik said: I entered with my grandfather Anas ibn Malik into the house of al-Hakam ibn Ayyub, and there were people who had tied up a chicken and were shooting at it. Anas said: “The Messenger of Allah ﷺ forbade restraining animals in order to kill them.”"]},"buhuth":{"en":["His statement, “to restrain animals,” means that they are confined so they can be shot until they die. The root meaning of the word is confinement."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5512,"lafz":true},{"key":"muslim","label":"مسلم","number":1956}],"full":1,"dr":1},{"num":7272,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ كُنْتُ عِنْدَ ابْنِ عُمَرَ فَمَرُّوا بِفِتْيَةٍ أَوْ بِنَفَرٍ نَصَبُوا دَجَاجَةً يَرْمُونَهَا، فَلَمَّا رَأَوُا ابْنَ عُمَرَ تَفَرَّقُوا عَنْهَا، وَقَالَ ابْنُ عُمَرَ مَنْ فَعَلَ هَذَا إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَعَنَ مَنْ فَعَلَ هَذَا."],"takhrij":"متفق عليه: رواه البخاري في الذبائح والصيد (5515)، ومسلم في الصيد والذبائح (1958: 59) كلاهما من طريق أبي عوانة، عن أبي بشر، عن سعيد بن جبير، قال فذكره. والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب النهي عن صبر البهائم ورميها","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5515) and Muslim (1958:59). The wording is from al-Bukhari.","chapter_en":"The Prohibition of Restraining Animals and Shooting at Them","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الصيد","group_en":"Collection of What Has Been Reported Concerning Hunting","part_no":38,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Saʿid ibn Jubayr said: I was with Ibn ʿUmar when they passed by some youths — or a group — who had tied up a chicken and were shooting at it. When they saw Ibn ʿUmar, they scattered away from it. Ibn ʿUmar said: “Who did this? The Prophet ﷺ cursed the one who does this.”"]},"buhuth":{"en":["In a wording of Muslim: Ibn ʿUmar passed by some youths from Quraysh who had tied up a bird and were shooting at it. They had made an arrangement that every arrow that missed would belong to the owner of the bird. When they saw Ibn ʿUmar, they scattered. Ibn ʿUmar said: “Who did this? May Allah curse whoever did this. The Messenger of Allah ﷺ cursed whoever takes anything that has a soul as a target.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5515,"lafz":true},{"key":"muslim","label":"مسلم","number":59},{"key":"muslim","label":"مسلم في الصيد والذبائح","number":1958}],"full":1,"dr":1},{"num":7273,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ دَخَلَ عَلَى يَحْيَى بْنِ سَعِيدٍ وَغُلاَمٌ مِنْ بَنِي يَحْيَى رَابِطٌ دَجَاجَةً يَرْمِيهَا، فَمَشَى إِلَيْهَا ابْنُ عُمَرَ حَتَّى حَلَّهَا، ثُمَّ أَقْبَلَ بِهَا وَبِالْغُلاَمِ مَعَهُ فَقَالَ ازْجُرُوا غُلاَمَكُمْ عَنْ أَنْ يَصْبِرَ هَذَا الطَّيْرَ لِلْقَتْلِ، فَإِنِّي سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ تُصْبَرَ بَهِيمَةٌ أَوْ غَيْرُهَا لِلْقَتْلِ."],"takhrij":"صحيح: رواه البخاري في الذبائح والصيد (5514) عن أحمد بن يعقوب، أخبرنا إسحاق بن سعيد بن عمرو، عن أبيه أنه سمعه يحدث عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن صبر البهائم ورميها","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5514).","chapter_en":"The Prohibition of Restraining Animals and Shooting at Them","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الصيد","group_en":"Collection of What Has Been Reported Concerning Hunting","part_no":38,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Ibn ʿUmar entered upon Yahya ibn Saʿid, while a boy from the family of Yahya had tied up a chicken and was shooting at it. Ibn ʿUmar walked to it and untied it, then came forward with it and with the boy. He said: “Rebuke your boy for restraining this bird to be killed, for I heard the Prophet ﷺ forbid that an animal or anything else be restrained for killing.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5514,"lafz":true}],"full":1,"dr":1},{"num":7274,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ أَنَّهُ: مَرَّ عَلَى قَوْمٍ، وَقَدْ نَصَبُوا دَجَاجَةً حَيَّةً يَرْمُونَهَا، فَقَالَ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَعَنَ مَنْ مَثَّلَ بِالْبَهَائِمِ."],"takhrij":"صحيح: رواه أحمد (4622) عن أبي معاوية (هو محمد بن خازم)، عن الأعمش، عن المنهال، عن سعيد بن جبير، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن صبر البهائم ورميها","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (4622).","chapter_en":"The Prohibition of Restraining Animals and Shooting at Them","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الصيد","group_en":"Collection of What Has Been Reported Concerning Hunting","part_no":38,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar passed by some people who had tied up a live chicken and were shooting at it. He said: “The Messenger of Allah ﷺ cursed whoever mutilates animals.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":4622,"n":4622,"lafz":true}],"full":1,"dr":1},{"num":7275,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ تَتَّخِذُوا شَيْئًا فِيهِ الرُّوحُ غَرَضًا."],"takhrij":"صحيح: رواه مسلم في الصيد والذبائح (1957: 58) عن عبيد الله بن معاذ، حدثنا أبي، حدثنا شعبة، عن عدي، عن سعيد بن جبير، عن ابن عباس فذكره. وعلّقه البخاري عقب حديث ابن عمر (5515) فقال: وقال عدي عن سعيد به ولم يسق متنه.","grade":"صحيح","chapter_ar":"باب النهي عن صبر البهائم ورميها","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1957:58).","chapter_en":"The Prohibition of Restraining Animals and Shooting at Them","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الصيد","group_en":"Collection of What Has Been Reported Concerning Hunting","part_no":38,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Ibn ʿAbbas narrated that the Prophet ﷺ said: “Do not take anything that has a soul as a target.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":58,"lafz":true,"n":122},{"key":"muslim","label":"مسلم في الصيد والذبائح","number":1957},{"key":"bukhari","label":"علقه البخاري عقب حديث ابن عمر","number":5515,"n":5456}],"full":1},{"num":7276,"demo":false,"sanad":"","matn":["عن جابر قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُقْتَلَ شَىْءٌ مِنَ الدَّوَابِّ صَبْرًا."],"takhrij":"صحيح: رواه مسلم في الصيد والذبائح (1959:60) من طرق عن ابن جريج، أخبرني أبوالزبير أنه سمع جابر بن عبد الله يقول: فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن صبر البهائم ورميها","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1959:60).","chapter_en":"The Prohibition of Restraining Animals and Shooting at Them","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الصيد","group_en":"Collection of What Has Been Reported Concerning Hunting","part_no":38,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ forbade that any animal be killed while restrained."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1959,"lafz":true}],"full":1},{"num":7277,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ جَعْفَرٍ، قَالَ مَرَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى أُنَاسٍ وَهُمْ يَرْمُونَ كَبْشًا بِالنَّبْلِ فَكَرِهَ ذَلِكَ وَقَالَ لاَ تَمْثُلُوا بِالْبَهَائِمِ."],"takhrij":"حسن: رواه النسائي (4440)، وأبو يعلى(6790) كلاهما من طريق عبدالعزيز بن أبي حازم، عن يزيد بن عبد الله بن الهاد، عن معاوية بن عبد الله بن جعفر، عن عبد الله بن جعفر فذكره.","grade":"حسن","chapter_ar":"باب النهي عن صبر البهائم ورميها","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4440) and Abu Yaʿla (6790).","chapter_en":"The Prohibition of Restraining Animals and Shooting at Them","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الصيد","group_en":"Collection of What Has Been Reported Concerning Hunting","part_no":38,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["ʿAbdullah ibn Jaʿfar said: The Messenger of Allah ﷺ passed by some people who were shooting arrows at a ram. He disliked that and said: “Do not mutilate animals.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4440,"lafz":true,"n":4440},{"key":"sh12520","label":"أبو يعلى","number":6790}],"full":1,"dr":1},{"num":7278,"demo":false,"sanad":"","matn":["عَنْ أَبِي الطُّفَيْلِ، قَالَ سُئِلَ عَلِيٌّ أَخَصَّكُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشَىْءٍ فَقَالَ مَا خَصَّنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشَىْءٍ لَمْ يَعُمَّ بِهِ النَّاسَ كَافَّةً إِلاَّ مَا كَانَ فِي قِرَابِ سَيْفِي هَذَا - قَالَ - فَأَخْرَجَ صَحِيفَةً مَكْتُوبٌ فِيهَا لَعَنَ اللَّهُ مَنْ ذَبَحَ لِغَيْرِ اللَّهِ وَلَعَنَ اللَّهُ مَنْ سَرَقَ مَنَارَ الأَرْضِ وَلَعَنَ اللَّهُ مَنْ لَعَنَ وَالِدَهُ وَلَعَنَ اللَّهُ مَنْ آوَى مُحْدِثًا."],"takhrij":"صحيح: رواه مسلم في الأضاحي (1978: 44) عن أبي بكر بن أبي شيبة، حدثنا أبو خالد الأحمر سليمان بن حيان، عن منصور بن حيان، عن أبي الطفيل قال: فذكره.","grade":"صحيح","chapter_ar":"باب تحريم الذبح لغير الله ولعن فاعله","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1978:44).","chapter_en":"The Prohibition of Slaughtering for Other Than Allah and the Curse upon the One Who Does It","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الذبح","group_en":"Collection of What Has Been Reported Concerning Slaughtering","part_no":38,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abu al-Tufayl said: ʿAli was asked: “Did the Messenger of Allah ﷺ give you anything special?” He said: “The Messenger of Allah ﷺ did not give us anything special that he did not give to all people, except what is in the sheath of this sword of mine.” He said: Then he took out a sheet in which it was written: “May Allah curse the one who slaughters for other than Allah. May Allah curse the one who steals the boundary markers of the land. May Allah curse the one who curses his parent. May Allah curse the one who shelters an innovating criminal.”"]},"intro":{"ar":["قال اللّٰه تعالى:","(إِنَّمَا حَرَّمَ عَلَيْكُمُ ٱلْمَيْتَةَ وَالدَّمَ وَلَحْمَ ٱلْخِنزِيرِ وَمَآ أُهِلَّ بِهِ لِغَيْرِ اللَّهِ) [البقرة: ١٧٣].","وقال أيضاً:","(حُرِّمَتْ عَلَيْكُمُ ٱلْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنزِيرِ وَمَا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ وَالْمُنْخَنِقَةُ وَٱلْمَوْقُوذَةُ وَالْمُتَرَدِّيَةُ وَالنَّطِيحَةُ وَمَا أَكَلَ السَّبُعُ إِلَّا مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى النُّصُبِ) [سورة المائدة: ٣] والإهلال في اللغة: رفع الصوت.","ومعنى قوله: (وَمَا أُهِلَّ بِهِ لِغَيْرِ اللهِ) أي ما ذُبح على الأنصاب والأنداد والأزلام ونحو ذلك باسم آلهتهم مما كانت الجاهلية يذبحون."],"en":["Allah the Exalted said:","“He has only forbidden you carrion, blood, the flesh of swine, and what has been dedicated to other than Allah.” [al-Baqarah: 173]","And He also said:","“Forbidden to you are carrion, blood, the flesh of swine, what has been dedicated to other than Allah, the strangled animal, the animal beaten to death, the animal that falls to its death, the animal gored to death, what predatory animals have eaten — except what you are able to slaughter — and what is slaughtered on stone altars.” [Surah al-Ma’idah: 3]","In the Arabic language, “dedication” here means raising the voice.","The meaning of His statement, “what has been dedicated to other than Allah,” is what was slaughtered at stone altars, for rivals, for divining arrows, and the like, in the name of their gods, as the people of the pre-Islamic period used to slaughter."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":44,"lafz":true},{"key":"muslim","label":"مسلم في الاضاحي","number":1978,"n":5126}],"full":1},{"num":7279,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن عُمَرَ يُحَدِّثُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ لَقِيَ زَيْدَ بْنَ عَمْرِو بْنِ نُفَيْلٍ بِأَسْفَلِ بَلْدَحٍ، وَذَاكَ قَبْلَ أَنْ يُنْزَلَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْوَحْىُ، فَقَدَّمَ إِلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُفْرَةً فِيهَا لَحْمٌ، فَأَبَى أَنْ يَأْكُلَ مِنْهَا، ثُمَّ قَالَ إِنِّي لاَ آكُلُ مِمَّا تَذْبَحُونَ عَلَى أَنْصَابِكُمْ، وَلاَ آكُلُ إِلاَّ مِمَّا ذُكِرَ اسْمُ اللَّهِ عَلَيْهِ.","وفي رواية: أن النبى صلى الله عليه وسلم لقى زيد بن عمرو بن نفيل بأسفل بلدح، قبل أن ينزل على النبى صلى الله عليه وسلم الوحى فقُدِّمَتْ إلى النبى صلى الله عليه وسلم سفرة، فأبى أن يأكل منها، ثم قال زيد: إنى لستُ آكل مما تذبحون على أنصابكم، ولا آكل إلا ما ذكر اسم الله عليه. وأن زيد بن عمرو كان يعيب على قريش ذبائحهم ويقول: الشاة خلقها الله، وأنزل لها من السماء الماء، وأنبت لها من الأرض، ثم تذبحونها على غير اسم الله إنكاراً لذلك، وإعظاماً له."],"takhrij":"صحيح: رواه البخاري في الذبائح والصيد (5499) عن معلى بن أسد، حدثنا عبدالعزيز بن المختار، أخبرنا موسى بن عقبة قال أخبرني سالم أنه سمع عبدالله (هو ابن عمر) فذكره.","grade":"صحيح","chapter_ar":"باب تحريم الذبح لغير الله ولعن فاعله","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5499). The other narration was also narrated by al-Bukhari (3826).","chapter_en":"The Prohibition of Slaughtering for Other Than Allah and the Curse upon the One Who Does It","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الذبح","group_en":"Collection of What Has Been Reported Concerning Slaughtering","part_no":38,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar narrated from the Messenger of Allah ﷺ that he met Zayd ibn ʿAmr ibn Nufayl at the lower part of Baldah, and that was before revelation came down to the Messenger of Allah ﷺ. The Messenger of Allah ﷺ presented to him a meal containing meat, but he refused to eat from it. Then he said: “I do not eat from what you slaughter on your stone altars, and I only eat from what the Name of Allah has been mentioned over.” In another narration: The Prophet ﷺ met Zayd ibn ʿAmr ibn Nufayl at the lower part of Baldah before revelation came down to the Prophet ﷺ. A meal was presented to the Prophet ﷺ, but he refused to eat from it. Then Zayd said: “I do not eat from what you slaughter on your stone altars, and I only eat what the Name of Allah has been mentioned over.” Zayd ibn ʿAmr used to criticize Quraysh for their slaughtered animals and say: “Allah created the sheep, sent down water for it from the sky, and brought forth vegetation for it from the earth, yet you slaughter it without the Name of Allah,” rejecting that and regarding it as serious."]},"buhuth":{"en":["The meal belonged to Quraysh; they presented it to the Prophet ﷺ, but he refused to eat from it. The Prophet ﷺ then presented it to Zayd ibn ʿAmr, thinking that he followed the customs of Quraysh, but he refused to eat from it and addressed Quraysh, who had presented it first."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5499,"lafz":true},{"key":"bukhari","label":". والرواية الأخرى رواها البخاري أيضاً","number":3826}],"full":1,"dr":1},{"num":7280,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ عَقْرَ فِي الإِسْلاَمِ."],"takhrij":"صحيح: رواه أبوداود (3222)، وأحمد (13032)، وصحَّحه ابن حبان (3146) كلهم من طريق عبد الرزاق –وهو في مصنفه (6690)- ثنا معمر، عن ثابت، عن أنس فذكره، وهو قطعة من حديث مطول، اختصره أبوداود، وهو بتمامه عند الآخرين.","grade":"صحيح","chapter_ar":"باب لا عقر في الإسلام","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3222), Ahmad (13032), and authenticated by Ibn Hibban (3146).","chapter_en":"There Is No Slaughter at Graves in Islam","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الذبح","group_en":"Collection of What Has Been Reported Concerning Slaughtering","part_no":38,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ said: “There is no slaughter at graves in Islam.”"]},"buhuth":{"en":["His statement, “There is no slaughter at graves in Islam,” was explained by ʿAbd al-Razzaq in Abu Dawud as follows: “They used to slaughter at the grave a cow or sheep — and in one wording: or something else.” End quote. Al-Khattabi said in Maʿalim al-Sunan (4/339): “The people of the pre-Islamic period used to slaughter camels at the grave of a generous man. They would say: ‘We are repaying him for what he did, because he used to slaughter them during his life and feed guests, so we slaughter them at his grave so that beasts and birds may eat them; thus, he is feeding after his death as he used to feed during his life.’” He said: “Some of them held that if his riding animal was slaughtered at his grave, he would be resurrected on the Day of Resurrection riding, and whoever did not have one slaughtered for him would be resurrected walking. This was according to the view of those among them who believed in resurrection after death.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3222,"lafz":true},{"key":"ibnhibban","label":"صحَّحه ابن حبان","number":3146,"n":2314},{"key":"ahmad","label":"مسند الإمام أحمد","number":13032,"n":13008},{"key":"abdrazzaq","label":"عبد الرزاق –وهو في مصنفه","number":6690}],"full":1,"dr":1},{"num":7281,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ أَكْلِ مُعَاقَرَةِ الأَعْرَابِ."],"takhrij":"حسن: رواه أبوداود (2820)- ومن طريقه البيهقي (9/313)- عن هارون بن عبدالله، ثنا حماد بن مسعدة، عن عوف، عن أبي ريحانة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب لا عقر في الإسلام","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2820), and through him al-Bayhaqi (9/313).","chapter_en":"There Is No Slaughter at Graves in Islam","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الذبح","group_en":"Collection of What Has Been Reported Concerning Slaughtering","part_no":38,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ forbade the competitive slaughtering of the Bedouins."]},"buhuth":{"en":["The meaning of the hadith, as al-Khattabi said, is: “Two men would compete, each trying to outdo his companion in generosity. One would slaughter a number of his camels, and the other would slaughter as well. Whichever of them slaughtered more would defeat and overcome his companion. Eating their meat was disliked so that it would not be from what was dedicated to other than Allah.”","3 — What Has Been Reported Concerning Mentioning the Name of Allah over Slaughtered Animals","Allah the Exalted said:","“For every nation We appointed a rite so that they may mention the Name of Allah over what He has provided for them of grazing livestock. Your Allah is One Allah, so submit to Him, and give good news to the humble.” [Surah al-Hajj: 34]","And He said:","“And the camels and cattle We have appointed for you as among the symbols of Allah; for you therein is good. So mention the Name of Allah over them while they are lined up. Then when they fall on their sides, eat from them and feed the one who asks and the one who presents himself without asking. Thus have We subjected them to you so that you may be grateful.” [Surah al-Hajj: 36]","And He said:","“So eat from that over which the Name of Allah has been mentioned, if you are believers in His signs.” [Surah al-Anʿam: 118]","And He said:","“Do not eat from that over which the Name of Allah has not been mentioned, for indeed it is disobedience. And indeed, the devils inspire their allies to dispute with you. If you obey them, you would indeed be associators.” [Surah al-Anʿam: 121]"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2820,"lafz":true},{"key":"kubrabayhaqi","label":"ومن طريقه البيهقي","number":9,"n":93}],"full":1,"dr":1},{"num":7282,"demo":false,"sanad":"","matn":["عَنْ رَافِعِ بْنِ خَدِيجٍ، قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنَّا لاَقُو الْعَدُوِّ غَدًا، وَلَيْسَتْ مَعَنَا مُدًى فَقَالَ اعْجَلْ أَوْ أَرِنْ مَا أَنْهَرَ الدَّمَ وَذُكِرَ اسْمُ اللَّهِ فَكُلْ، لَيْسَ السِّنَّ وَالظُّفُرَ، وَسَأُحَدِّثُكَ، أَمَّا السِّنُّ فَعَظْمٌ، وَأَمَّا الظُّفُرُ فَمُدَى الْحَبَشَةِ."],"takhrij":"متفق عليه: رواه البخاري في الذبائح والصيد ( 5498)، ومسلم في الأضاحي (1968: 20) كلاهما من طريق سعيد بن مسروق، عن عباية بن رفاعة بن رافع بن خديج، عن جده رافع بن خديج فذكره، والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"ما جاء في التسمية على الذبائح","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5498) and Muslim (1968:20). The wording is from Muslim.","chapter_en":"What Has Been Reported Concerning Mentioning the Name of Allah over Slaughtered Animals","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الذبح","group_en":"Collection of What Has Been Reported Concerning Slaughtering","part_no":38,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Rafiʿ ibn Khadij said: I said: “O Messenger of Allah, we will meet the enemy tomorrow, and we do not have knives.” He ﷺ said: “Use whatever causes the blood to flow quickly — or show me whatever causes the blood to flow — and the Name of Allah is mentioned over it, then eat, except the tooth and the nail. I will tell you: as for the tooth, it is bone; and as for the nail, it is the knife of the Abyssinians…” the hadith."]},"intro":{"ar":["قال اللّه تعالى:","(وَلِكُلِّ أُمَّةٍ جَعَلْنَا مَنسَكًا لِيَذْكُرُوا اسْمَ اللَّهِ عَلَىٰ مَا رَزَقَهُم مِنْ بَهِيمَةِ الْأَنْعَامِ فَإِلَهُكُمْ إِلَهٌ وَاحِدٌ فَلَهُ أَسْلِمُوا وَبَشِّرِ الْمُخْبِتِينَ) [سورة الحج: ٣٤]","وقال تعالى:","(وَالْبُدْنَ جَعَلْنَاهَا لَكُم مِن شَعَائِرِ اللَّهِ لَكُمْ فِيهَا خَيْرٌ فَاذْكُرُوا اسْمَ اللَّهِ عَلَيْهَا صَوَافَّ فَإِذَا وَجَبَتْ جُنُوبُهَا فَكُلُوا مِنْهَا وَأَطْعِمُوا الْقَانِعَ وَالْمُعْتَرَّ كَذَٰلِكَ سَخَّرْنَاهَا لَكُمْ لَعَلَّكُمْ تَشْكُرُونَ) [سورة الحج: ٣٦]","وقال تعالى:","(فَكُلُوا مِمَّا ذُكِرَ اسْمُ اللَّهِ عَلَيْهِ إِن كُنتُم بِآيَاتِهِ مُؤْمِنِينَ) [سورة الأنعام: ١١٨]","وقال تعالى:","(وَلَا تَأْكُلُوا مِمَّا لَمْ يُذْكَرِ اسْمُ اللَّهِ عَلَيْهِ وَإِنَّهُ لَفِسْقٌ وَإِنَّ الشَّيَاطِينَ لَيُوحُونَ إِلَىٰ أَوْلِيَائِهِمْ لِيُجَادِلُوكُمْ وَإِنْ أَطَعْتُمُوهُمْ إِنَّكُمْ لَمُشْرِكُونَ) [سورة الأنعام: ١٢١]"],"en":["Allah the Exalted said:","“For every nation We appointed a rite so that they may mention the Name of Allah over what He has provided for them of grazing livestock. Your Allah is One Allah, so submit to Him, and give good news to the humble.” [Surah al-Hajj: 34]","And He said:","“And the camels and cattle We have appointed for you as among the symbols of Allah; for you therein is good. So mention the Name of Allah over them while they are lined up. Then when they fall on their sides, eat from them and feed the one who asks and the one who presents himself without asking. Thus have We subjected them to you so that you may be grateful.” [Surah al-Hajj: 36]","And He said:","“So eat from that over which the Name of Allah has been mentioned, if you are believers in His signs.” [Surah al-Anʿam: 118]","And He said:","“Do not eat from that over which the Name of Allah has not been mentioned, for indeed it is disobedience. And indeed, the devils inspire their allies to dispute with you. If you obey them, you would indeed be associators.” [Surah al-Anʿam: 121]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5498,"lafz":true,"n":5509},{"key":"muslim","label":"مسلم","number":20},{"key":"muslim","label":"مسلم في الاضاحي","number":1968}],"full":1},{"num":7283,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، فِي قَوْلِهِ عَزَّ وَجَلَّ ﴿وَلاَ تَأْكُلُوا مِمَّا لَمْ يُذْكَرِ اسْمُ اللَّهِ عَلَيْهِ﴾ [سورة الأنعام: 121] } قَالَ خَاصَمَهُمُ الْمُشْرِكُونَ فَقَالُوا مَا ذَبَحَ اللَّهُ فَلاَ تَأْكُلُوهُ وَمَا ذَبَحْتُمْ أَنْتُمْ أَكَلْتُمُوهُ."],"takhrij":"حسن: رواه النسائي (4437)، وابن جرير في تفسيره (9/523) من طريق سفيان الثوري، ثني هارون بن عنترة، عن أبيه، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"ما جاء في التسمية على الذبائح","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4437) and Ibn Jarir in his commentary (9/523).","chapter_en":"What Has Been Reported Concerning Mentioning the Name of Allah over Slaughtered Animals","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الذبح","group_en":"Collection of What Has Been Reported Concerning Slaughtering","part_no":38,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbas said concerning the statement of Allah, the Mighty and Majestic: “Do not eat from that over which the Name of Allah has not been mentioned”: The polytheists argued with them and said: “What Allah slaughtered, you do not eat; but what you slaughter, you eat?!”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4437,"lafz":true,"n":4437},{"key":"ابن_جریر/تفسیرہ","label":"ابن جرير في تفسيره","number":9}],"full":1,"dr":1},{"num":7284,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أن قَوْمًا يَأْتُونَا بِاللَّحْمِ، لاَ نَدْرِي: أ ذُكرَ اسْمُ اللَّهِ عَلَيْهِ أَمْ لاَ؟ فَقَالَ: سَمُّوا عَلَيْهِ أَنْتُمْ وَكُلُوهُ قَالَتْ: وَكَانُوا حَدِيثِي عهدٍ بِالْكُفْرِ."],"takhrij":"صحيح: رواه البخاري في الذبائح والصيد (5507) عن محمد بن عبيدالله، حدثنا أسامة بن حفص المدني، عن هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب في التسمية على اللحم المشكوك فيه هل ذكر اسم الله عليه أو لا؟","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5507).","chapter_en":"Mentioning the Name of Allah over Meat When There Is Doubt Whether the Name of Allah Was Mentioned over It or Not","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الذبح","group_en":"Collection of What Has Been Reported Concerning Slaughtering","part_no":38,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["ʿA’ishah narrated that some people would bring them meat, and they did not know whether the Name of Allah had been mentioned over it or not. He said: “You mention the Name of Allah over it and eat it.” She said: They had recently left disbelief."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5507,"lafz":true}],"full":1,"dr":1},{"num":7285,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ، قَالَ أَصَبْتُ جِرَابًا مِنْ شَحْمٍ يَوْمَ خَيْبَرَ - قَالَ - فَالْتَزَمْتُهُ فَقُلْتُ لاَ أُعْطِي الْيَوْمَ أَحَدًا مِنْ هَذَا شَيْئًا.","قال: فالتفتُّ فإذا رسول الله صلى الله عليه وسلم مبتسماً."],"takhrij":"متفق عليه: رواه مسلم في الجهاد (1772) عن شيبان بن فرّوخ، حدثنا سليمان بن المغيرة، حدثنا حميد بن هلال، عن عبدالله بن مغفل فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في ذبائح أهل الكتاب","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (1772) and al-Bukhari (4214).","chapter_en":"What Has Been Reported Concerning the Slaughtered Animals of the People of the Book","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الذبح","group_en":"Collection of What Has Been Reported Concerning Slaughtering","part_no":38,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullah ibn Mughaffal said: I found a bag of fat on the day of Khaybar. He said: I held on to it and said: “Today I will not give anyone any of this.” He said: I turned around, and there was the Messenger of Allah ﷺ smiling."]},"intro":{"ar":["قال اللّٰه تعالى:","(يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ وَمَا عَلَّمْتُم مِّنَ الْجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ اللَّهُ فَكُلُوا مِمَّا أَمْسَكْنَ عَلَيْكُمْ وَاذْكُرُوا اسْمَ اللَّهِ عَلَيْهِ وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ سَرِيعُ الْحِسَابِ ۝ الْيَوْمَ أُحِلَّ لَكُمُ الطَّيِّبَاتُ وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَكُمْ وَطَعَامُكُمْ حِلٌّ لَّهُمْ) [سورة المائدة: ٤-٥]","أهل الكتاب هم: اليهود والنصارى. والمراد بالطعام: ذبائحهم كما قال ابن عباس وأصحابه."],"en":["Allah the Exalted said:","“They ask you what has been made lawful for them. Say: Lawful for you are the good things, and what you have trained of hunting animals, training them from what Allah has taught you. So eat from what they catch for you, and mention the Name of Allah over it. And fear Allah. Indeed, Allah is swift in reckoning. Today, the good things have been made lawful for you, and the food of those who were given the Book is lawful for you, and your food is lawful for them.” [Surah al-Ma’idah: 4–5]","The People of the Book are the Jews and Christians. What is meant by “food” is their slaughtered animals, as Ibn ʿAbbas and his companions said."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1772,"lafz":true},{"key":"bukhari","label":"البخاري","number":4214}],"full":1,"dr":1},{"num":7286,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ لَمَّا فُتِحَتْ خَيْبَرُ أُهْدِيَتْ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَاةٌ فِيهَا سُمٌّ فَقَالَ."],"takhrij":"صحيح: رواه البخاري في الجزية والموادعة (3169) عن عبد الله بن يوسف، ثنا الليث، قال: حدثني سعيد (هو ابن أبي سعيد المقبري)، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في ذبائح أهل الكتاب","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3169).","chapter_en":"What Has Been Reported Concerning the Slaughtered Animals of the People of the Book","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الذبح","group_en":"Collection of What Has Been Reported Concerning Slaughtering","part_no":38,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah said: When Khaybar was conquered, a sheep containing poison was gifted to the Prophet ﷺ… the hadith."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3169,"lafz":true}],"full":1},{"num":7287,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: يَقُولُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَرَضِهِ الَّذِي تُوُفِّيَ فِيهِ: يَا عَائِشَةُ! إِنِّي أَجِدُ أَلَمَ الطَّعَامِ الَّذِي أَكَلْتُهُ بِخَيْبَرَ، فَهَذَا أَوَانُ انْقِطَاعِ أَبْهَرِي مِنْ ذَلِكَ السُّمِّ."],"takhrij":"صحيح: رواه الحاكم (3/58) وعنه البيهقي (10/11) من حديث عنبسة، ثنا يونس، عن ابن شهاب قال: قال عروة: كانت عائشة تقول فذكرته. وذكره البخاري في المغازي (4428) معلقا بقوله: \"وقال يونس فذكره مثله\".","grade":"صحيح","chapter_ar":"باب ما جاء في ذبائح أهل الكتاب","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Hakim (4393), and from him al-Bayhaqi (10/11).","chapter_en":"What Has Been Reported Concerning the Slaughtered Animals of the People of the Book","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الذبح","group_en":"Collection of What Has Been Reported Concerning Slaughtering","part_no":38,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ would say during the illness in which he died: “O ʿA’ishah, I still feel the pain of the food that I ate at Khaybar, and this is the time when my aorta is being cut from that poison.”"]}},"tuhfa":{},"refs":[{"key":"kubrabayhaqi","label":"عنه البيهقي","number":10},{"key":"hakim","label":"المستدرك على الصحيحين","number":4393,"n":4384,"lafz":true},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":19717,"n":19875},{"key":"bukhari","label":"ذكره البخاري في المغازي","number":4428}],"full":1},{"num":7288,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ يَهُودِيًّا دَعَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى خُبْزِ شَعِيرٍ وَإِهَالَةٍ سَنِخَةٍ، فَأَجَابَهُ."],"takhrij":"صحيح: رواه أحمد (13201) عن عبد الصمد، حدثنا أبان، حدثنا قتادة، عن أنس فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في ذبائح أهل الكتاب","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (13201).","chapter_en":"What Has Been Reported Concerning the Slaughtered Animals of the People of the Book","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الذبح","group_en":"Collection of What Has Been Reported Concerning Slaughtering","part_no":38,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Malik narrated that a Jewish man invited the Prophet ﷺ to barley bread and rancid melted fat, and he accepted his invitation."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":13201,"n":13201,"lafz":true}],"full":1,"dr":1},{"num":7289,"demo":false,"sanad":"","matn":["عَنْ كَعْبِ بن مَالِكٍ- أَنَّهُ كَانَتْ لَهُمْ غَنَمٌ تَرْعَى بسلْعٍ، فَأَبْصَرَتْ جَارِيَةٌ لَنَا بِشَاةٍ مِنْ غَنَمِنَا مَوْتًا، فَكَسَرَتْ حَجَرًا فَذَبَحَتْهَا بِهِ، فَقَالَ لَهُمْ: لاَ تَأْكُلُوا حَتَّى أَسْأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، أَوْ أُرْسِلَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ يَسْأَلُهُ. وَأَنَّهُ سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَاكَ، أَوْ أَرْسَلَ، فَأَمَرَهُ بِأَكْلِهَا."],"takhrij":"صحيح: رواه البخاري في الوكالة (2304) عن إسحاق بن إبراهيم، سمع المعتمر، أنبأنا عبيد الله، عن نافع، أنه سمع ابنَ كعب بن مالك، يحدث عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب جواز ذبيحة المرأة","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2304).","chapter_en":"The Permissibility of a Woman’s Slaughtered Animal","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الذبح","group_en":"Collection of What Has Been Reported Concerning Slaughtering","part_no":38,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Kaʿb ibn Malik narrated that they had sheep grazing at Salʿ. A slave girl of theirs saw that one of their sheep was dying, so she broke a stone and slaughtered it with it. He said to them: “Do not eat until I ask the Prophet ﷺ, or send someone to the Prophet ﷺ to ask him.” He asked the Prophet ﷺ about that — or sent someone — and he ordered him to eat it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2304,"lafz":true}],"full":1,"dr":1},{"num":7290,"demo":false,"sanad":"","matn":["عن رَافِعِ بن خَدِيجٍ رَضِيَ اللَّهُ عَنْهُ قَالَ كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِذِي الْحُلَيْفَةِ مِنْ تِهَامَةَ، فَأَصَبْنَا غَنَمًا وَإِبِلاً، فَعَجِلَ الْقَوْمُ، فَأَغْلَوْا بِهَا الْقُدُورَ، فَجَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَمَرَ بِهَا فَأُكْفِئَتْ، ثُمَّ عَدَلَ عَشْرًا مِنَ الْغَنَمِ بِجَزُورٍ، ثُمَّ إِنَّ بَعِيرًا نَدَّ وَلَيْسَ فِي الْقَوْمِ إِلاَّ خَيْلٌ يَسِيرَةٌ فَرَمَاهُ رَجُلٌ فَحَبَسَهُ بِسَهْمٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ لِهَذِهِ الْبَهَائِمِ أَوَابِدَ كَأَوَابِدِ الْوَحْشِ، فَمَا غَلَبَكُمْ مِنْهَا فَاصْنَعُوا بِهِ هَكَذَا.","قال: قال جدي: يا رسول الله إنا نرجو أو نخاف أن نلقى العدو غدا، وليس معنا مدى فنذبح بالقصب؟ فقال: اعجل أو أرني، ما أنهر الدم وذكر اسم الله عليه فكلوا، ليس السنّ والظفر، وسأحدثكم عن ذلك، أما السنُّ فعظمٌ، وأما الظفرُ فمدى الحبشة."],"takhrij":"متفق عليه: رواه البخاري في الشركة (2507) ومسلم في الأضاحي (1968: 20-21) كلاهما من طريق سفيان بن سعيد بن مسروق، عن أبيه، عن عَباية بن رفاعة بن رافع بن خديج، عن جده رافع بن خديج، فذكره.","grade":"متفق عليه","chapter_ar":"باب في التذكية بكلِّ شيء حادٍّ إذا أنهر الدم غير السن والظُفر وسائر العظام","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari in al-Sharikah (2507) and Muslim in al-Adahi (1968:20–21).","chapter_en":"Slaughtering with Every Sharp Object That Causes the Blood to Flow, Except the Tooth, the Nail, and Other Bones","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الذبح","group_en":"Collection of What Has Been Reported Concerning Slaughtering","part_no":38,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Rafiʿ ibn Khadij said: We were with the Prophet ﷺ at Dhu al-Hulayfah in Tihamah, and we acquired sheep and camels. The people hurried and set the pots boiling with them. The Messenger of Allah ﷺ came and ordered that the pots be overturned. Then he equated ten sheep with one camel. A camel then ran away, while the people had only a few horses. A man shot it and stopped it with an arrow. The Messenger of Allah ﷺ said: “These animals can become wild like wild animals, so whatever of them overpowers you, deal with it in this manner.” Then my grandfather said: “O Messenger of Allah, we hope — or fear — that we may meet the enemy tomorrow, and we have no knives. May we slaughter with reeds?” He said: “Hasten — or show me — whatever causes the blood to flow and over which the Name of Allah is mentioned, then eat. But not the tooth or the nail. I will tell you about that: the tooth is bone, and the nail is the knife of the Abyssinians.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري في الشركة","number":2507,"lafz":true},{"key":"muslim","label":"مسلم في الأضاحي","number":20},{"key":"muslim","label":"مسلم في الاضاحي","number":1968}],"full":1,"dr":1},{"num":7291,"demo":false,"sanad":"","matn":["عَنْ مُحَمَّدِ بْنِ صَفْوَانَ قَالَ: أصّدتُ أَرْنَبَيْنِ فَذَبَحْتُهُمَا بِمَرْوَةٍ، فَسَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْهُمَا، فَأَمَرَنِي بِأَكْلِهِمَا\"."],"takhrij":"صحيح: رواه أبوداود (2822)، والنسائي (4313)، وابن ماجه (3175)، وأحمد (15870) وصحَّحه ابن حبان (5887) كلهم من طرق عن عاصم الأحول، عن الشعبي، عن محمد بن صفوان فذكره.","grade":"صحيح","chapter_ar":"باب في التذكية بكلِّ شيء حادٍّ إذا أنهر الدم غير السن والظُفر وسائر العظام","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2822), al-Nasa’i (4313), Ibn Majah (3175), and Ahmad (15870), and authenticated by Ibn Hibban (5887).","chapter_en":"Slaughtering with Every Sharp Object That Causes the Blood to Flow, Except the Tooth, the Nail, and Other Bones","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الذبح","group_en":"Collection of What Has Been Reported Concerning Slaughtering","part_no":38,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Muhammad ibn Safwan said: I hunted two rabbits and slaughtered them with a sharp stone. I asked the Messenger of Allah ﷺ about them, and he ordered me to eat them."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2822,"lafz":true},{"key":"nasai","label":"النسائي","number":4313},{"key":"ibnmajah","label":"ابن ماجه","number":3175},{"key":"ibnhibban","label":"صحَّحه ابن حبان","number":5887},{"key":"ahmad","label":"مسند الإمام أحمد","number":15870,"n":15870}],"full":1,"dr":1,"rep":[7326]},{"num":7292,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ، مِنْ بَنِي حَارِثَةَ أَنَّهُ كَانَ يَرْعَى لِقْحَةً بِشِعْبٍ مِنْ شِعَابِ أُحُدٍ فَأَخَذَهَا الْمَوْتُ فَلَمْ يَجِدْ شَيْئًا يَنْحَرُهَا بِهِ فَأَخَذَ وَتَدًا فَوَجَأَ بِهِ فِي لَبَّتِهَا حَتَّى أُهْرِيقَ دَمُهَا ثُمَّ جَاءَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ بِذَلِكَ فَأَمَرَهُ بِأَكْلِهَا."],"takhrij":"صحيح: رواه أبوداود (2823) –ومن طريقه البيهقي (9/281)- عن قتيبة بن سعيد، ثنا يعقوب، عن زيد بن أسلم، عن عطاء بن يسار، عن رجل من بني حارثة، فذكره.","grade":"صحيح","chapter_ar":"باب في التذكية بكلِّ شيء حادٍّ إذا أنهر الدم غير السن والظُفر وسائر العظام","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2823) and al-Bayhaqi (9/281).","chapter_en":"Slaughtering with Every Sharp Object That Causes the Blood to Flow, Except the Tooth, the Nail, and Other Bones","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الذبح","group_en":"Collection of What Has Been Reported Concerning Slaughtering","part_no":38,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["A man from Banu Harithah narrated that he was grazing a milch camel in one of the valleys of Uhud when it was overtaken by death. He did not find anything with which to slaughter it, so he took a peg and stabbed it in its upper chest until its blood flowed. Then he came to the Prophet ﷺ and told him about that, and he ordered him to eat it."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2823,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":9},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":19149,"n":19307}],"full":1,"dr":1},{"num":7293,"demo":false,"sanad":"","matn":["عَنْ عَدِيِّ بْنِ حَاتِمٍ، قَالَ قُلْتُ يَا رَسُولَ اللَّهِ أَرَأَيْتَ إِنْ أَحَدُنَا أَصَابَ صَيْدًا وَلَيْسَ مَعَهُ سِكِّينٌ أَيَذْبَحُ بِالْمَرْوَةِ وَشِقَّةِ الْعَصَا فَقَالَ أَمْرِرِ الدَّمَ بِمَا شِئْتَ وَاذْكُرِ اسْمَ اللَّهِ عَزَّ."],"takhrij":"حسن: رواه أبوداود (2824)، والنسائي (4304)، وابن ماجه (3177)، وأحمد (18250)، وصحَّحه ابن حبان (332)، والحاكم (4/240) كلهم من طرق عن سماك بن حرب قال: سمعت مريَّ بن قطري، يحدث عن عدي بن حاتم، فذكره.","grade":"حسن","chapter_ar":"باب في التذكية بكلِّ شيء حادٍّ إذا أنهر الدم غير السن والظُفر وسائر العظام","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2824), al-Nasa’i (4304), Ibn Majah (3177), and Ahmad (18250), and authenticated by Ibn Hibban (332) and al-Hakim (7600).","chapter_en":"Slaughtering with Every Sharp Object That Causes the Blood to Flow, Except the Tooth, the Nail, and Other Bones","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الذبح","group_en":"Collection of What Has Been Reported Concerning Slaughtering","part_no":38,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["ʿAdi ibn Hatim said: I said: “O Messenger of Allah, what if one of us catches game and does not have a knife? May he slaughter with a sharp stone or a split piece of wood?” He said: “Cause the blood to flow with whatever you wish, and mention the Name of Allah, the Mighty and Majestic.”"]},"buhuth":{"en":["Benefit: It is disliked in slaughtering to cut off the animal’s head immediately, because that harms the animal. However, if its head is cut off, eating it is not disliked. Al-Bukhari mentioned in the Book of Slaughtered Animals, in the chapter on slaughtering camels and other animals: Ibn ʿUmar, Ibn ʿAbbas, and Anas said: If the head is cut off, there is no harm. Al-Hafiz Ibn Hajar connected the chains of these reports in al-Fath and authenticated them."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2824,"lafz":true},{"key":"nasai","label":"النسائي","number":4304},{"key":"ibnmajah","label":"ابن ماجه","number":3177},{"key":"ibnhibban","label":"صحَّحه ابن حبان","number":332},{"key":"ahmad","label":"مسند الإمام أحمد","number":18250,"n":18250},{"key":"hakim","label":"المستدرك على الصحيحين","number":7600,"n":7604}],"full":1,"dr":1},{"num":7294,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: ذَكَاةُ الْجَنِينِ ذَكَاةُ أُمِّهِ."],"takhrij":"حسن: رواه أحمد (11343)، وصحّحه ابن حبان (5889) من طريق يونس بن أبي إسحاق، عن أبي الودّاك جبر بن نوف، عن أبي سعيد، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في ذكاة الجنين","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (11343), and authenticated by Ibn Hibban (5889).","chapter_en":"What Has Been Reported Concerning the Slaughter of the Fetus","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الذبح","group_en":"Collection of What Has Been Reported Concerning Slaughtering","part_no":38,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated from the Prophet ﷺ that he said: “The slaughter of the fetus is the slaughter of its mother.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"صحّحه ابن حبان","number":5889},{"key":"ahmad","label":"مسند الإمام أحمد","number":11343,"n":11343,"lafz":true},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4102,"n":4149}],"full":1,"dr":1,"rep":[7205]},{"num":7295,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِغُلاَمٍ يَسْلُخُ شاةً، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : تنحَّ حَتَّى أُرِيَكَ، فَأَدْخَلَ يَدَهُ بَيْنَ الْجِلْدِ وَاللَّحْمِ، فَدَحَسَ بِهَا حَتَّى تَوَارَتْ إِلَى الإِبْطِ، ثُمَّ مَضَى، فَصَلَّى لِلنَّاسِ وَلَمْ يَتَوَضَّأْ. وَزَادَ فِي رِوَايَةِ: يَا غُلاَمُ، هَكَذَا فَاسْلُخْ."],"takhrij":"حسن: رواه أبوداود (185)، وابن ماجه (3179)، وصحَّحه ابن حبان (1162) كلهم من طريق مروان بن معاوية، ثنا هلال بن ميمون الجهني، ثنا عطاء بن يزيد الليثي، قال: لا أعلمه إلا عن أبي سعيد الخدري، فذكره. والرواية الأخرى عند ابن ماجه.","grade":"حسن","chapter_ar":"باب ما جاء في سلخ الشاة","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (185), Ibn Majah (3179), and authenticated by Ibn Hibban (1162).","chapter_en":"What Has Been Reported Concerning Skinning a Sheep","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الذبح","group_en":"Collection of What Has Been Reported Concerning Slaughtering","part_no":38,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that the Prophet ﷺ passed by a boy skinning a sheep. The Messenger of Allah ﷺ said to him: “Move aside so I can show you.” He inserted his hand between the skin and the flesh, pushing it in until it disappeared up to the armpit. Then he went on and led the people in prayer without performing ablution. In another narration, he added: “O boy, skin it like this.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":185,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":3179},{"key":"ibnhibban","label":"صحَّحه ابن حبان","number":1162}],"full":1,"dr":1},{"num":7296,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ أَوْ لَيْلَةٍ فَإِذَا هُوَ بِأَبِي بَكْرٍ وَعُمَرَ، فَقَالَ: مَا أَخْرَجَكُمَا مِنْ بُيُوتِكُمَا هَذِهِ السَّاعَةَ؟ قَالاَ: الْجُوعُ يَا رَسُولَ اللَّهِ. قَالَ: وَأَنَا وَالَّذِي نَفْسِي بِيَدِهِ لأَخْرَجَنِي الَّذِي أَخْرَجَكُمَا قُومُوا. فَقَامُوا مَعَهُ، فَأَتَى رَجُلاً مِنَ الأَنْصَارِ، فَإِذَا هُوَ لَيْسَ فِي بَيْتِهِ، فَلَمَّا رَأَتْهُ الْمَرْأَةُ قَالَتْ: مَرْحَبًا وَأَهْلاً. فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَيْنَ فُلاَنٌ؟، قَالَتْ: ذَهَبَ يَسْتَعْذِبُ لَنَا مِنَ الْمَاءِ، إِذْ جَاءَ الأَنْصَارِيُّ فَنَظَرَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَصَاحِبَيْهِ، ثُمَّ قَالَ: الْحَمْدُ لِلَّهِ مَا أَحَدٌ الْيَوْمَ أَكْرَمَ أَضْيَافًا مِنِّي، قَالَ: فَانْطَلَقَ، فَجَاءَهُمْ بِعِذْقٍ، فِيهِ بُسرٌ وَتَمْرٌ وَرُطَبٌ. فَقَالَ: كُلُوا مِنْ هَذِهِ، وَأَخَذَ الْمُدْيَةَ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِيَّاكَ وَالْحَلُوبَ. فَذَبَحَ لَهُمْ فَأَكَلُوا مِنَ الشَّاةِ، وَمِنْ ذَلِكَ الْعِذْقِ وَشَرِبُوا، فَلَمَّا أَنْ شَبِعُوا وَرَوُوا قـال رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لأَبِي بَكْرٍ وَعُمَرَ: وَالَّذِي نَفْسِي بِيَدِهِ لَتُسْأَلُنَّ عَنْ هَذَا النَّعِيمِ يَوْمَ الْقِيَامَةِ، أَخْرَجَكُمْ مِنْ بُيُوتِكُمُ الْجُوعُ، ثُمَّ لَمْ تَرْجِعُوا حَتَّى أَصَابَكُمْ هَذَا النَّعِيمُ. وَفِي رِوَايَةِ: لا تذبحنَّ ذاتَ دُرٍّ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2038: 140) عن أبي بكر بن أبي شيبة، ثنا خلف بن خليفة، عن يزيد بن كيسان، عن أبي حازم، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب الاجتناب من ذبح الشاة الحلوب","chapter_ur":"","part_ar":"كتاب الصيد والذبائح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2038:140).","chapter_en":"Avoiding Slaughtering a Milk-Giving Sheep","part_en":"Book of Hunting and Slaughtered Animals","group_ar":"جموع ما جاء في الذبح","group_en":"Collection of What Has Been Reported Concerning Slaughtering","part_no":38,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ went out one day or night and found Abu Bakr and ʿUmar. He said: “What brought you out of your houses at this hour?” They said: “Hunger, O Messenger of Allah.” He said: “And I, by the One in whose Hand is my soul, what brought you out also brought me out. Get up.” So they got up with him. He came to a man from the Ansar, but he was not at home. When the woman saw him, she said: “Welcome.” The Messenger of Allah ﷺ said to her: “Where is so-and-so?” She said: “He went to bring us fresh water.” Then the Ansari came, saw the Messenger of Allah ﷺ and his two companions, and said: “Praise be to Allah; no one today has guests more honored than mine.” He went and brought them a date branch containing unripe dates, dried dates, and fresh ripe dates. He said: “Eat from this,” and he took the knife. The Messenger of Allah ﷺ said to him: “Beware of the milk-giving animal.” So he slaughtered for them. They ate from the sheep and from that date branch, and they drank. When they had eaten their fill and quenched their thirst, the Messenger of Allah ﷺ said to Abu Bakr and ʿUmar: “By the One in whose Hand is my soul, you will surely be asked about this blessing on the Day of Resurrection. Hunger brought you out of your houses, then you did not return until this blessing had reached you.” In another narration: “Do not slaughter one that gives milk.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":140,"lafz":true},{"key":"muslim","label":"مسلم في الاشربه","number":2038}],"full":1,"dr":1,"rep":[13770,16203]},{"num":7297,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبِّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ وَجَدَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَاةً مَيِّتَةً أُعْطِيَتْهَا مَوْلاَةٌ لِمَيْمُونَةَ مِنَ الصَّدَقَةِ، قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَلاَّ انْتَفَعْتُمْ بِجِلْدِهَا. قَالُوا إِنَّهَا مَيْتَةٌ. قَالَ إِنَّمَا حَرُمَ أَكْلُهَا."],"takhrij":"متفق عليه: رواه البخاري في الزكاة (1492)، ومسلم في الحيض (363: 101) كلاهما من طريق ابن وهب، أخبرني يونس، عن ابن شهاب، حدثني عبيد الله بن عبد الله بن عتبة، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب في الانتفاع بجلود الميتة إذا دُبغتْ","chapter_ur":"","part_ar":"كتاب جلود الميتة والسباع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1492) and Muslim (363:101).","chapter_en":"Benefiting from the Skins of Dead Animals When They Are Tanned","part_en":"Book of the Skins of Dead Animals and Predatory Beasts","group_ar":"","group_en":"","part_no":39,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Ibn ʿAbbas said: The Prophet ﷺ found a dead sheep that had been given in charity to a freedwoman of Maymunah. The Prophet ﷺ said: “Why did you not benefit from its skin?” They said: “It is dead.” He said: “Only eating it has been forbidden.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1492,"lafz":true},{"key":"muslim","label":"مسلم","number":101},{"key":"muslim","label":"مسلم في الحيض","number":363}],"full":1,"dr":1},{"num":7298,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ قَالَ: مرَّ النبيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بعَنْزٍ مَيْتَةٍ، فَقَالَ: مَا عَلَى أَهْلِهَا لَوِ انْتَفَعُوا بِإِهَابِهَا."],"takhrij":"صحيح: رواه البخاري في الذبائح (5532) عن خطّاب بن عثمان، حدثنا محمد بن حِمْيَر، عن ثابت بن عجلان، قال: سمعتُ سعيدَ بن جبير قال: سمعتُ ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب في الانتفاع بجلود الميتة إذا دُبغتْ","chapter_ur":"","part_ar":"كتاب جلود الميتة والسباع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5532).","chapter_en":"Benefiting from the Skins of Dead Animals When They Are Tanned","part_en":"Book of the Skins of Dead Animals and Predatory Beasts","group_ar":"","group_en":"","part_no":39,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas said: The Prophet ﷺ passed by a dead goat and said: “What harm would there be upon its owners if they benefited from its hide?”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5532,"lafz":true}],"full":1},{"num":7299,"demo":false,"sanad":"","matn":["عَنْ سَوْدَةَ، زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ مَاتَتْ لَنَا شَاةٌ فَدَبَغْنَا مَسْكَهَا ثُمَّ مَا زِلْنَا نَنْبِذُ فِيهِ حَتَّى صَارَتْ شَنًّا."],"takhrij":"صحيح: رواه البخاري في الأيمان والنذور (6686) عن محمد بن مقاتل، أخبرنا عبد الله (هو ابن المبارك)، أخبرنا إسماعيل بن أبي خالد، عن الشعبي، عن عكرمة، عن ابن عباس، عن سودة، فذكرته.","grade":"صحيح","chapter_ar":"باب في الانتفاع بجلود الميتة إذا دُبغتْ","chapter_ur":"","part_ar":"كتاب جلود الميتة والسباع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6686).","chapter_en":"Benefiting from the Skins of Dead Animals When They Are Tanned","part_en":"Book of the Skins of Dead Animals and Predatory Beasts","group_ar":"","group_en":"","part_no":39,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Sawdah, the wife of the Prophet ﷺ, said: A sheep of ours died, so we tanned its skin, and we continued to soak drinks in it until it became worn out."]},"buhuth":{"en":["Her statement, “its skin,” means its hide. Her statement, “until it became worn out,” means until it became old and worn."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6686,"lafz":true}],"full":1,"dr":1},{"num":7300,"demo":false,"sanad":"","matn":["أَنَّ مَيْمُونَةَ، أَخْبَرَتْهُ أَنَّ دَاجِنَةً كَانَتْ لِبَعْضِ نِسَاءِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَمَاتَتْ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَلاَّ أَخَذْتُمْ إِهَابَهَا فَاسْتَمْتَعْتُمْ بِهِ."],"takhrij":"صحيح: رواه مسلم (364) عن أحمد بن عثمان النوفلي، حدثنا أبو عاصم، حدثنا ابن جريج، أخبرني عمرو بن دينار، أخبرني عطاء منذ حين قال: أخبرني ابن عباس، أن ميمونة، أخبرته؛ فذكرته.","grade":"صحيح","chapter_ar":"باب في الانتفاع بجلود الميتة إذا دُبغتْ","chapter_ur":"","part_ar":"كتاب جلود الميتة والسباع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (364).","chapter_en":"Benefiting from the Skins of Dead Animals When They Are Tanned","part_en":"Book of the Skins of Dead Animals and Predatory Beasts","group_ar":"","group_en":"","part_no":39,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Maymunah narrated that a domestic sheep belonging to one of the wives of the Messenger of Allah ﷺ died. The Messenger of Allah ﷺ said: “Why did you not take its hide and benefit from it?”"]},"buhuth":{"en":["The “domestic animal” here means a sheep raised in the house."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":364,"lafz":true}],"full":1,"dr":1},{"num":7301,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ، قَالَ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ إِذَا دُبِغَ الإِهَابُ فَقَدْ طَهُرَ."],"takhrij":"صحيح: رواه مسلم في الحيض (366: 105) عن يحيى بن يحيى، أخبرنا سليمان بن بلال، عن زيد بن أسلم، أن عبد الرحمن بن وعلة أخبره، عن عبدالله بن عباس فذكره.","grade":"صحيح","chapter_ar":"باب في الانتفاع بجلود الميتة إذا دُبغتْ","chapter_ur":"","part_ar":"كتاب جلود الميتة والسباع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (366:105).","chapter_en":"Benefiting from the Skins of Dead Animals When They Are Tanned","part_en":"Book of the Skins of Dead Animals and Predatory Beasts","group_ar":"","group_en":"","part_no":39,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Ibn ʿAbbas said: I heard the Messenger of Allah ﷺ say: “When the hide is tanned, it becomes pure.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":105,"lafz":true},{"key":"muslim","label":"مسلم في الحيض","number":366}],"full":1,"dr":1},{"num":7302,"demo":false,"sanad":"","matn":["7302 - عَنْ أَبِي الخير قَالَ: رَأَيْتُ عَلَى ابنِ وَعْلَةَ السَّبَئِيِّ فَرْواً، فمَسِسْتُه فَقَالَ: مالك تَمَسُّه؟ قَدْ سَأَلْتُ عبدالله بْنَ عَبَّاسٍ، قُلْتُ: إِنَّا نَكُونُ بِالْمَغْرِبِ وَمَعَنَا الْبَرْبَرُ وَالْمَجُوسُ، نُؤْتَى بِالْكَبْشِ قَدْ ذَبَحُوهُ، وَنَحْنُ لاَ نَأْكُلُ ذَبَائِحَهُمْ، وَيَأْتُونَا بِالسِّقَاءِ يَجْعَلُونَ فِيهِ الْوَدَكَ، فَقَالَ ابْنُ عَبَّاسٍ: قَدْ سَأَلْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ؟ فَقَالَ: دِبَاغُهُ طَهُورُهُ."],"takhrij":"صحيح: رواه مسلم في الحيض (366: 106) من طريق عمرو بن الربيع، أخبرنا يحيى بن أيوب، عن يزيد بن أبي حبيب، أن أبا الخير حدّثه، فذكره.","grade":"صحيح","chapter_ar":"باب في الانتفاع بجلود الميتة إذا دُبغتْ","chapter_ur":"","part_ar":"كتاب جلود الميتة والسباع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (366:106).","chapter_en":"Benefiting from the Skins of Dead Animals When They Are Tanned","part_en":"Book of the Skins of Dead Animals and Predatory Beasts","group_ar":"","group_en":"","part_no":39,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu al-Khayr said: I saw Ibn Waʿlah al-Saba’i wearing a fur garment, so I touched it. He said: “Why are you touching it? I asked ʿAbdullah ibn ʿAbbas. I said: ‘We are in the Maghrib, and with us are Berbers and Magians. A ram they have slaughtered is brought to us, but we do not eat their slaughtered animals. They also bring us waterskins in which they put fat.’ Ibn ʿAbbas said: We asked the Messenger of Allah ﷺ about that, and he said: ‘Its tanning is its purification.’”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":106,"lafz":true},{"key":"muslim","label":"مسلم في الحيض","number":366,"n":814}],"full":1},{"num":7303,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَكَاةُ الْمَيْتَةِ دِبَاغُهَا."],"takhrij":"صحيح: رواه النسائي في الصغرى (4258)، وفي الكبرى (4559)، والطحاوي في شرح المعاني (1/470) كلهم من طريق أبي غسان مالك بن إسماعيل، ثنا إسرائيل، عن الأعمش، عن إبراهيم، عن الأسود، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب في الانتفاع بجلود الميتة إذا دُبغتْ","chapter_ur":"","part_ar":"كتاب جلود الميتة والسباع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i in al-Sughra (4258), in al-Kubra (4559), and al-Tahawi in Sharh al-Maʿani (1/470).","chapter_en":"Benefiting from the Skins of Dead Animals When They Are Tanned","part_en":"Book of the Skins of Dead Animals and Predatory Beasts","group_ar":"","group_en":"","part_no":39,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ said: “The tanning of a dead animal’s hide is its purification.”"]},"buhuth":{"en":["In one of al-Tahawi’s wordings:","“The tanning of a dead animal’s skin is its purification.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي في الصغرىٰ","number":4258,"lafz":true,"n":4247},{"key":"kubranasai","label":"وفي الكبرى","number":4559},{"key":"sh21108","label":"الطحاوي في شرح المعاني","number":1}],"full":1,"dr":1},{"num":7304,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: طَهُورُ كُلِّ أَدِيمٍ دِبَاغُهُ."],"takhrij":"حسن: رواه الدارقطني (124)، والبيهقي (1/21) كلاهما من طريق إبراهيم بن الهيثم، حدثنا علي بن عياش، حدثنا محمد بن مطرف، حدثنا زيد بن أسلم، عن عطاء بن يسار، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب في الانتفاع بجلود الميتة إذا دُبغتْ","chapter_ur":"","part_ar":"كتاب جلود الميتة والسباع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Daraqutni (124) and al-Bayhaqi (1/21).","chapter_en":"Benefiting from the Skins of Dead Animals When They Are Tanned","part_en":"Book of the Skins of Dead Animals and Predatory Beasts","group_ar":"","group_en":"","part_no":39,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿA’ishah narrated from the Prophet ﷺ that he said: “The purification of every hide is its tanning.”"]}},"tuhfa":{},"refs":[{"key":"sh9771","label":"الدارقطني","number":124,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":1,"n":68}],"full":1,"dr":1},{"num":7305,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ وَعْلَةَ، عَنِ ابْنِ عَبَّاسٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  أَيُّمَا إِهَابٍ دُبِغَ فَقَدْ طَهُرَ."],"takhrij":"حسن: رواه الدارقطني في السنن (1/48) وفي العلل (12/365) عن أبي بكر النيسابوري (واسمه عبد الله بن محمد بن زياد)-، وأبو الشيخ الأصبهاني في طبقات المحدثين بأصبهان (4/48) عن عبد الله بن الحسين بن زهير النيسابوري- كلاهما عن محمد بن عقيل بن خويلد الخزاعي، حدثنا حفص بن عبد الله، ثنا إبراهيم بن طهمان، عن أيوب، عن نافع، عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب في الانتفاع بجلود الميتة إذا دُبغتْ","chapter_ur":"","part_ar":"كتاب جلود الميتة والسباع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Daraqutni in al-Sunan (1/48) and in al-ʿIlal (12/365).","chapter_en":"Benefiting from the Skins of Dead Animals When They Are Tanned","part_en":"Book of the Skins of Dead Animals and Predatory Beasts","group_ar":"","group_en":"","part_no":39,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: The Messenger of Allah ﷺ said: “Any hide that is tanned has become pure.”"]}},"tuhfa":{},"refs":[{"key":"sh9771","label":"الدارقطني في السنن","number":1,"lafz":true,"n":113},{"key":"وفی_العلل","label":"وفي العلل","number":12}],"full":1,"dr":1},{"num":7306,"demo":false,"sanad":"","matn":["عَنْ سَلَمَةَ بْنِ الْمُحَبِّقِ، أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  مَرَّ بِبَيْتٍ بِفِنَائِهِ قِرْبَةٌ مُعَلَّقَةٌ فَاسْتَسْقَى، فَقِيلَ: إِنَّهَا مَيْتَةٌ، قَالَ: ذَكَاةُ الْأَدِيمِ دِبَاغُهُ."],"takhrij":"حسن: رواه أبو داود (4125)، والنسائي (4243) وصحَّحه ابن حبان (4522) والحاكم (4/141) كلهم من حديث همام، عن قتادة، عن الحسن، عن جَون بن قتادة، عن سلمة بن المحبق فذكره.","grade":"حسن","chapter_ar":"باب في الانتفاع بجلود الميتة إذا دُبغتْ","chapter_ur":"","part_ar":"كتاب جلود الميتة والسباع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4125) and al-Nasa’i (4243), and authenticated by Ibn Hibban (4522) and al-Hakim (4/141).","chapter_en":"Benefiting from the Skins of Dead Animals When They Are Tanned","part_en":"Book of the Skins of Dead Animals and Predatory Beasts","group_ar":"","group_en":"","part_no":39,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Salamah ibn al-Muhabbiq narrated that the Messenger of Allah ﷺ passed by a house with a water-skin hanging in its courtyard. He asked for water, and it was said: “It is from a dead animal.” He said: “The purification of the hide is its tanning.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4125,"lafz":true},{"key":"nasai","label":"النسائي","number":4243},{"key":"ibnhibban","label":"صحَّحه ابن حبان","number":4522},{"key":"hakim","label":"الحاكم","number":4}],"full":1,"dr":1},{"num":7307,"demo":false,"sanad":"","matn":["عَنْ أَبِي الْمَلِيحِ بْنِ أُسَامَةَ، عَنْ أَبِيهِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ جُلُودِ السِّبَاعِ. وَزَادَ فِي رِوَايَةِ: أَنَّ تفترش."],"takhrij":"صحيح: رواه أبوداود (4132)، والترمذي (1770)، والنسائي (4264)، وأحمد (20706)، والحاكم (1/144)، والضياء في المختارة (1379) كلهم من طرق عن سعيد بن أبي عروبة، عن قتادة، عن أبي المليح فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في النهي عن جلود السباع","chapter_ur":"","part_ar":"كتاب جلود الميتة والسباع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (4132), al-Tirmidhi (1770), al-Nasa’i (4264), Ahmad (20706), al-Hakim (1/144), and al-Diya’ in al-Mukhtarah (1395).","chapter_en":"What Has Been Reported Concerning the Prohibition of the Skins of Predatory Beasts","part_en":"Book of the Skins of Dead Animals and Predatory Beasts","group_ar":"","group_en":"","part_no":39,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Abu al-Malih ibn Usamah narrated from his father that the Messenger of Allah ﷺ forbade the skins of predatory beasts. Another narration adds: that they be used as furnishings."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4132,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1770},{"key":"nasai","label":"النسائي","number":4264},{"key":"hakim","label":"الحاكم","number":1},{"key":"sh10480","label":"الضياء في المختارة","number":1395},{"key":"ahmad","label":"مسند الإمام أحمد","number":20706,"n":20706},{"key":"sh10480","label":"الضياء في المختاره","number":1379}],"full":1,"dr":1},{"num":7308,"demo":false,"sanad":"","matn":["عَنْ مُعَاوِيَةَ بن أَبِي سُفْيَانَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : لاَ تَرْكَبُوا الخزَّ والنمارَ.","قال: وكان معاوية لا يُتّهم في الحديث عن رسول الله صلى الله عليه وسلم."],"takhrij":"صحيح: رواه أبو داود (4129)، وابن ماجة (3656) وأحمد (16840) كلهم من طريق وكيع، حدثنا أبو المعتمر، عن ابن سيرين، عن معاوية فذكره. واللفظ لأبي داود ومثله لفظ أحمد.","grade":"صحيح","chapter_ar":"باب ما جاء في النهي عن جلود السباع","chapter_ur":"","part_ar":"كتاب جلود الميتة والسباع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (4129), Ibn Majah (3656), and Ahmad (16840).","chapter_en":"What Has Been Reported Concerning the Prohibition of the Skins of Predatory Beasts","part_en":"Book of the Skins of Dead Animals and Predatory Beasts","group_ar":"","group_en":"","part_no":39,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Muʿawiyah ibn Abi Sufyan said: The Messenger of Allah ﷺ said: “Do not ride on silk brocade or leopard skins.” He said: Muʿawiyah was not accused regarding his narration from the Messenger of Allah ﷺ."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4129,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":3656},{"key":"ahmad","label":"مسند الإمام أحمد","number":16840,"n":16840}],"full":1,"dr":1},{"num":7309,"demo":false,"sanad":"","matn":["عَنْ أَبِي شَيْخٍ الْهُنَائِيِّ، قَالَ: كُنْتُ فِي مَلَأٍ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ مُعَاوِيَةَ، فَقَالَ مُعَاوِيَةُ: أَنْشُدُكُمُ اللهَ، أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لُبْسِ الْحَرِيرِ؟ قَالُوا: اللهُمَّ نَعَمْ، قَالَ: وَأَنَا أَشْهَدُ، قَالَ: أَنْشُدُكُمُ اللهَ، أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لُبْسِ الذَّهَبِ إِلَّا مُقَطَّعًا؟ قَالُوا: اللهُمَّ نَعَمْ، قَالَ: وَأَنَا أَشْهَدُ، قَالَ: أَنْشُدُكُمُ اللهَ، أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ رُكُوبِ النُّمُورِ؟ قَالُوا: اللهُمَّ نَعَمْ، قَالَ: وَأَنَا أَشْهَدُ، قَالَ: أَنْشُدُكُمُ اللهَ، أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الشُّرْبِ فِي آنِيَةِ الْفِضَّةِ؟ قَالُوا: اللهُمَّ نَعَمْ، قَالَ: وَأَنَا أَشْهَدُ، قَالَ: أَنْشُدُكُمُ اللهَ، أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ جَمْعٍ بَيْنَ حَجٍّ وَعُمْرَةٍ؟ قَالُوا: أَمَّا هَذَا، فَلَا، قَالَ: أَمَا إِنَّهَا مَعَهُنَّ."],"takhrij":"حسن: رواه أبوداود (1794)، والنسائي (5166)، وأحمد (16833) كلهم من طريق قتادة، عن أبي شيخ الهنائي به. والسياق لأحمد. واختصره أبوداود والنسائي.","grade":"حسن","chapter_ar":"باب ما جاء في النهي عن جلود السباع","chapter_ur":"","part_ar":"كتاب جلود الميتة والسباع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1794), al-Nasa’i (5166), and Ahmad (16833). The wording is from Ahmad.","chapter_en":"What Has Been Reported Concerning the Prohibition of the Skins of Predatory Beasts","part_en":"Book of the Skins of Dead Animals and Predatory Beasts","group_ar":"","group_en":"","part_no":39,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Abu Shaykh al-Huna’i said: I was among a group of the Companions of the Messenger of Allah ﷺ with Muʿawiyah. Muʿawiyah said: “I ask you by Allah, do you know that the Messenger of Allah ﷺ forbade wearing silk?” They said: “O Allah, yes.” He said: “And I bear witness.” He said: “I ask you by Allah, do you know that the Messenger of Allah ﷺ forbade wearing gold except in small pieces?” They said: “O Allah, yes.” He said: “And I bear witness.” He said: “I ask you by Allah, do you know that the Messenger of Allah ﷺ forbade riding on leopard skins?” They said: “O Allah, yes.” He said: “And I bear witness.” He said: “I ask you by Allah, do you know that the Messenger of Allah ﷺ forbade drinking from vessels of silver?” They said: “O Allah, yes.” He said: “And I bear witness.” He said: “I ask you by Allah, do you know that the Messenger of Allah ﷺ forbade combining Hajj and ʿUmrah?” They said: “As for this one, no.” He said: “Indeed, it is with them.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1794,"lafz":true},{"key":"nasai","label":"النسائي","number":5166},{"key":"ahmad","label":"مسند الإمام أحمد","number":16833,"n":16833}],"full":1,"dr":1,"rep":[15405]},{"num":7310,"demo":false,"sanad":"","matn":["عَنِ الْمِقْدَامِ بْنِ مَعْدِيكَرِبَ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْحَرِيرِ، وَالذَّهَبِ، ومياثر النُّمُورِ."],"takhrij":"حسن: رواه النسائي في الصغرى (4265)، وفي الكبرى (4566)، وأحمد (17185) من طريق بقية، عن بحير (هو ابن سعد)، عن خالد بن معدان، عن المقدام بن معديكرب.","grade":"حسن","chapter_ar":"باب ما جاء في النهي عن جلود السباع","chapter_ur":"","part_ar":"كتاب جلود الميتة والسباع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i in al-Sughra (4265), in al-Kubra (4566), and Ahmad (17185).","chapter_en":"What Has Been Reported Concerning the Prohibition of the Skins of Predatory Beasts","part_en":"Book of the Skins of Dead Animals and Predatory Beasts","group_ar":"","group_en":"","part_no":39,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Al-Miqdam ibn Maʿdikarib said: The Messenger of Allah ﷺ forbade silk, gold, and saddle-cloths made from leopard skins."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي في الصغرىٰ","number":4265,"lafz":true,"n":4254},{"key":"kubranasai","label":"وفي الكبرى","number":4566},{"key":"ahmad","label":"مسند الإمام أحمد","number":17185,"n":17185}],"full":1,"dr":1},{"num":7311,"demo":false,"sanad":"","matn":["عَنْ الْمِقْدَامِ بْنِ مَعْدِيكَرِبَ أنه قَالَ لمعاوية: أَنْشُدُكَ بِاللَّهِ، هَلْ تَعْلَمُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لُبْسِ جُلُودِ السِّبَاعِ وَالرُّكُوبِ عَلَيْهَا؟ قَالَ: نَعَمْ."],"takhrij":"حسن: رواه أبوداود (4131)، والنسائي (4266) كلاهما عن عمرو بن عثمان الحمصي، حدثنا بقية، عن بحير، عن خالد (هو ابن معدان) فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في النهي عن جلود السباع","chapter_ur":"","part_ar":"كتاب جلود الميتة والسباع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4131) and al-Nasa’i (4266). Al-Tabarani also narrated it at length in al-Kabir (20/269, no. 636).","chapter_en":"What Has Been Reported Concerning the Prohibition of the Skins of Predatory Beasts","part_en":"Book of the Skins of Dead Animals and Predatory Beasts","group_ar":"","group_en":"","part_no":39,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Al-Miqdam ibn Maʿdikarib said to Muʿawiyah: “I ask you by Allah, do you know that the Messenger of Allah ﷺ forbade wearing the skins of predatory beasts and riding on them?” He said: “Yes.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4131,"lafz":true},{"key":"nasai","label":"النسائي","number":4266,"n":4255},{"key":"mujamkabir","label":"الطبراني في الكبير","number":20}],"full":1,"dr":1},{"num":7312,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ كُنَّا نَغْزُو مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَنُصِيبُ مِنْ آنِيَةِ الْمُشْرِكِينَ وَأَسْقِيَتِهِمْ فَنَسْتَمْتِعُ بِهَا فَلاَ يَعِيبُ ذَلِكَ عَلَيْهِمْ."],"takhrij":"حسن: رواه أبوداود (3838)، والبيهقي (1/32) وأحمد (15053) من طريق عبد الأعلى بن عبد الأعلى –وزاد أبو داود: وإسماعيل (هو ابن علية)- عن بُرد بن سنان، عن عطاء (هو ابن أبي رباح)، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب جواز الانتفاع بأواني المشركين وأسقيتهم","chapter_ur":"","part_ar":"كتاب جلود الميتة والسباع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3838), al-Bayhaqi (1/32), and Ahmad (15053).","chapter_en":"The Permissibility of Benefiting from the Vessels and Water-Skins of the Polytheists","part_en":"Book of the Skins of Dead Animals and Predatory Beasts","group_ar":"","group_en":"","part_no":39,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Jabir said: We used to go on military expeditions with the Messenger of Allah ﷺ and would acquire the vessels and water-skins of the polytheists, and we would benefit from them. He did not criticize them for that."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3838,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":1,"n":128},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":128,"n":128},{"key":"ahmad","label":"مسند الإمام أحمد","number":15053,"n":15053}],"full":1,"dr":1},{"num":7313,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَيُّهَا النَّاسُ إِنَّ اللَّهَ طَيِّبٌ لاَ يَقْبَلُ إِلاَّ طَيِّبًا وَإِنَّ اللَّهَ أَمَرَ الْمُؤْمِنِينَ بِمَا أَمَرَ بِهِ الْمُرْسَلِينَ فَقَالَ ﴿يَا أَيُّهَا الرُّسُلُ كُلُوا مِنَ الطَّيِّبَاتِ وَاعْمَلُوا صَالِحًا إِنِّي بِمَا تَعْمَلُونَ عَلِيمٌ﴾ [سورة المؤمنون: 51]} وَقَالَ { يَا أَيُّهَا الَّذِينَ آمَنُوا كُلُوا مِنْ طَيِّبَاتِ مَا رَزَقْنَاكُمْ}. ثُمَّ ذَكَرَ الرَّجُلَ يُطِيلُ السَّفَرَ أَشْعَثَ أَغْبَرَ يَمُدُّ يَدَيْهِ إِلَى السَّمَاءِ يَا رَبِّ يَا رَبِّ وَمَطْعَمُهُ حَرَامٌ وَمَشْرَبُهُ حَرَامٌ وَمَلْبَسُهُ حَرَامٌ وَغُذِيَ بِالْحَرَامِ فَأَنَّى يُسْتَجَابُ لِذَلِكَ."],"takhrij":"صحيح: رواه مسلم في الزكاة (1015) عن أبي كريب محمد بن العلاء، حدثنا أبوأسامة، حدثنا فضيل بن مرزوق، حدثني عديُّ بن ثابت، عن أبي حازم، عن أبي هريرة، قال: فذكره.","grade":"صحيح","chapter_ar":"باب الحث على أكل الطيبات واجتناب الخبائث","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1015).","chapter_en":"Encouragement to Eat Good Things and Avoid Filthy Things","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “O people, Allah is Pure and accepts only what is pure. Allah commanded the believers with what He commanded the messengers, saying: ‘O messengers, eat from the good things and do righteous deeds. Indeed, I am Knowing of what you do,’ and He said: ‘O you who believe, eat from the good things We have provided for you.’ Then he mentioned a man who travels for a long time, disheveled and dusty, stretching his hands toward the sky: ‘O Lord, O Lord,’ while his food is unlawful, his drink is unlawful, his clothing is unlawful, and he has been nourished with the unlawful. So how can he be answered?”"]},"intro":{"ar":["قال اللّٰه تعالى:","(يَا أَيُّهَا الَّذِينَ آمَنُوا كُلُوا مِن طَيِّبَاتِ مَا رَزَقْنَاكُمْ وَاشْكُرُوا لِلَّهِ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ) [سورة البقرة: ١٧٢]","وقال تعالى:","(يَا أَيُّهَا الرُّسُلُ كُلُوا مِنَ الطَّيِّبَاتِ وَاعْمَلُوا صَالِحًا إِنِّي بِمَا تَعْمَلُونَ عَلِيمٌ) [سورة المؤمنون: ٥١]","وقال تعالى:","(وَيُحِلُّ لَهُمُ الطَّيِّبَاتِ وَيُحَرِّمُ عَلَيْهِمُ الْخَبَائِثَ) [الأعراف: ١٥٧]"],"en":["Allah the Exalted said:","“O you who believe, eat from the good things We have provided for you, and be grateful to Allah, if it is Him that you worship.” [Surah al-Baqarah: 172]","And He said:","“O messengers, eat from the good things and do righteous deeds. Indeed, I am Knowing of what you do.” [Surah al-Mu’minun: 51]","And He said:","“He makes lawful for them the good things and forbids for them the filthy things.” [al-Aʿraf: 157]"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1015,"lafz":true},{"key":"sh13078","label":"الورع لابن أبي الدنيا","number":115,"n":81}],"full":1,"rep":[11940]},{"num":7314,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ كَانَ أَهْلُ الْجَاهِلِيَّةِ يَأْكُلُونَ أَشْيَاءَ وَيَتْرُكُونَ أَشْيَاءَ تَقَذُّرًا فَبَعَثَ اللَّهُ تَعَالَى نَبِيَّهُ وَأَنْزَلَ كِتَابَهُ وَأَحَلَّ حَلاَلَهُ وَحَرَّمَ حَرَامَهُ فَمَا أَحَلَّ فَهُوَ حَلاَلٌ وَمَا حَرَّمَ فَهُوَ حَرَامٌ وَمَا سَكَتَ عَنْهُ فَهُوَ عَفْوٌ وَتَلاَ { قُلْ لاَ أَجِدُ فِيمَا أُوحِيَ إِلَىَّ مُحَرَّمًا } إِلَى آخِرِ الآيَةِ."],"takhrij":"صحيح: رواه أبو داود (3800)، وابن أبي حاتم في تفسيره (8000)، والحاكم (4/115) كلهم من طريق أبي نعيم الفضل بن دكين، ثنا محمد بن شريك المكي، عن عمرو بن دينار، عن أبي الشعثاء، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ما لم يذكر تحريمه في الكتاب والسنة فهو عفو","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3800), Ibn Abi Hatim in his Tafsir (8000), and al-Hakim (7113).","chapter_en":"Whatever Its Prohibition Is Not Mentioned in the Book and the Sunnah Is Pardoned","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿAbbas said: The people of the pre-Islamic period used to eat certain things and avoid certain things out of disgust. Then Allah the Exalted sent His Prophet, revealed His Book, made lawful what He made lawful, and made forbidden what He made forbidden. So whatever He made lawful is lawful, whatever He made forbidden is forbidden, and whatever He remained silent about is pardoned. Then he recited: “Say: I do not find in what has been revealed to me anything forbidden…” to the end of the verse."]},"intro":{"ar":["قال اللّه تعالى:","(قُل لَّا أَجِدُ فِي مَا أُوحِيَ إِلَيَّ مُحَرَّمًا عَلَىٰ طَاعِمٍ يَطْعَمُهُ إِلَّا أَن يَكُونَ مَيْتَةً أَوْ دَمًا مَّسْفُوحًا أَوْ لَحْمَ خِنزِيرٍ فَإِنَّهُ رِجْسٌ أَوْ فِسْقًا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ) [الأنعام: ١٤٥]"],"en":["Allah the Exalted said:","“Say: I do not find in what has been revealed to me anything forbidden to one who eats it, except that it be carrion, flowing blood, the flesh of swine — for it is filth — or a sinful offering dedicated to other than Allah.” [al-Anʿam: 145]"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3800,"lafz":true},{"key":"sh8658","label":"ابن أبي حاتم في تفسيره","number":8000},{"key":"hakim","label":"المستدرك على الصحيحين","number":7113,"n":7111}],"full":1,"dr":1},{"num":7315,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : مَا أَحَلَّ اللَّهُ فِي كِتَابِهِ فَهُوَ حَلَالٌ، وَمَا حرّم فَهُوَ حَرَامٌ، وَمَا سَكَتَ عَنْهُ فَهُوَ عَافِيَةٌ، فَاقْبَلُوا مِنَ اللَّهِ عَافَيْتَهُ، فإنَّ اللَّهَ لَمْ يَكُنْ نَسِيًّا، ثُمَّ تَلَا هَذِهِ الْآيَةَ: وَمَا كَانَ رَبُّكَ نَسِيًّا."],"takhrij":"حسن: رواه الدارقطني (2066)، والحاكم (2/375)، وعنه البيهقي (10/12) من طريق أبي نعيم الفضل بن دكين- ورواه البزار في مسنده (4087)، والطبراني في مسند الشاميين (2102) من طريق إسماعيل بن عياش- كلاهما عن عاصم بن رجاء بن حيوة، عن أبيه، عن أبي الدرداء، فذكره.","grade":"حسن","chapter_ar":"باب ما لم يذكر تحريمه في الكتاب والسنة فهو عفو","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Daraqutni (2066), al-Hakim (3419), and from him al-Bayhaqi (10/12).","chapter_en":"Whatever Its Prohibition Is Not Mentioned in the Book and the Sunnah Is Pardoned","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abu al-Darda’ said: The Messenger of Allah ﷺ said: “Whatever Allah has made lawful in His Book is lawful, whatever He has made forbidden is forbidden, and whatever He remained silent about is a pardon. So accept Allah’s pardon, for Allah is never forgetful.” Then he recited this verse: “And your Lord is never forgetful.”"]}},"tuhfa":{},"refs":[{"key":"sh9771","label":"الدارقطني","number":2066,"lafz":true},{"key":"kubrabayhaqi","label":"عنه البيهقي","number":10},{"key":"hakim","label":"المستدرك على الصحيحين","number":3419,"n":3406},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":19724,"n":19882},{"key":"sh12862","label":"من طريق ابي نعيم الفضل بن دكين- ورواه البزار في مسنده","number":4087},{"key":"sh13162","label":"الطبراني في مسند الشاميين","number":2102}],"full":1,"dr":1,"rep":[12715]},{"num":7316,"demo":false,"sanad":"","matn":["عن أَبِي ثَعْلَبَةَ الخشني قَالَ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّا بِأَرْضِ قَوْمٍ أَهْلِ الْكِتَابِ، نَأْكُلُ فِي آنِيَتِهِمْ، وَأَرْضِ صَيْدٍ أَصِيدُ بِقَوْسِي، وَأَصِيدُ بِكَلْبِي الْمُعَلَّمِ، وَالَّذِي لَيْسَ مُعَلَّمًا، فَأَخْبِرْنِي مَا الَّذِي يَحِلُّ لَنَا مِنْ ذَلِكَ فَقَالَ أَمَّا مَا ذَكَرْتَ أَنَّكَ بِأَرْضِ قَوْمٍ أَهْلِ الْكِتَابِ، تَأْكُلُ فِي آنِيَتِهِمْ، فَإِنْ وَجَدْتُمْ غَيْرَ آنِيَتِهِمْ، فَلاَ تَأْكُلُوا فِيهَا، وَإِنْ لَمْ تَجِدُوا فَاغْسِلُوهَا ثُمَّ كُلُوا فِيهَا، وَأَمَّا مَا ذَكَرْتَ أَنَّكَ بِأَرْضِ صَيْدٍ، فَمَا صِدْتَ بِقَوْسِكَ، فَاذْكُرِ اسْمَ اللَّهِ، ثُمَّ كُلْ، وَمَا صِدْتَ بِكَلْبِكَ الْمُعَلَّمِ، فَاذْكُرِ اسْمَ اللَّهِ، ثُمَّ كُلْ، وَمَا صِدْتَ بِكَلْبِكَ الَّذِي لَيْسَ مُعَلَّمًا فَأَدْرَكْتَ ذَكَاتَهُ، فَكُلْ."],"takhrij":"متفق عليه: رواه البخاريّ في الذبائح والصيد (5488)، ومسلم في الصيد والذبائح (1930) كلاهما من طريق ابن المبارك، عن حيوة بن شريح، قال: سمعت ربيعة بن يزيد، الدمشقي يقول: أخبرني أبو إدريس عائذ الله قال: سمعت أبا ثعلبة الخشني فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الأكل والشرب في أواني المشركين وأهل الكتاب وأسقيتهم","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5488) and Muslim (1930).","chapter_en":"What Has Been Reported Concerning Eating and Drinking from the Vessels and Water-Skins of the Polytheists and the People of the Book","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Abu Thaʿlabah al-Khushani said: I came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, we are in the land of a people from the People of the Book, and we eat from their vessels. It is also a land of hunting; I hunt with my bow, and I hunt with my trained dog and with my dog that is not trained. Tell me what is lawful for us from that.” He said: “As for what you mentioned about being in the land of a people from the People of the Book and eating from their vessels: if you find vessels other than theirs, do not eat from theirs. If you do not find any others, then wash them and eat from them. As for what you mentioned about being in a land of hunting: whatever you hunt with your bow, mention the Name of Allah, then eat. Whatever you hunt with your trained dog, mention the Name of Allah, then eat. And whatever you hunt with your dog that is not trained, if you reach it in time to slaughter it, then eat.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5488,"lafz":true},{"key":"muslim","label":"مسلم","number":1930}],"full":1},{"num":7317,"demo":false,"sanad":"","matn":["عن عمران بن حصين قال: شربنا ونحن أربعون رجلا عطاش من مزادة امرأة مشركة، وغسّلنا صاحبنا الجنب."],"takhrij":"متفق عليه: رواه البخاري في المناقب (3571)، ومسلم في المساجد (682) كلاهما من حديث سلْم بن زرير، قال: سمعت أبا رجاء العُطاردي قال: حدثنا عمران بن حصين.. فذكر الحديث في حديث طويل سيأتي بتمامه في دلائل النبوة.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الأكل والشرب في أواني المشركين وأهل الكتاب وأسقيتهم","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3571) and Muslim (682).","chapter_en":"What Has Been Reported Concerning Eating and Drinking from the Vessels and Water-Skins of the Polytheists and the People of the Book","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["ʿImran ibn Husayn said: We drank — while we were forty thirsty men — from the water-skin of a polytheist woman, and we washed our companion, meaning the one in a state of major ritual impurity."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3571,"lafz":true},{"key":"muslim","label":"مسلم","number":682}],"full":1},{"num":7318,"demo":false,"sanad":"","matn":["عَنْ أَبِي ثَعْلَبَةَ الْخُشَنِيِّ، أَنَّهُ سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِنَّا نُجَاوِرُ أَهْلَ الْكِتَابِ وَهُمْ يَطْبُخُونَ فِي قُدُورِهِمُ الْخِنْزِيرَ وَيَشْرَبُونَ فِي آنِيَتِهِمُ الْخَمْرَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنْ وَجَدْتُمْ غَيْرَهَا فَكُلُوا فِيهَا وَاشْرَبُوا وَإِنْ لَمْ تَجِدُوا غَيْرَهَا فَارْحَضُوهَا بِالْمَاءِ وَكُلُوا وَاشْرَبُوا."],"takhrij":"صحيح: رواه أبوداود (3839)، والطبراني في مسند الشاميين (783) كلاهما من طريق محمد بن شعيب، أخبرنا عبد الله بن العلاء بن زبر، عن أبي عبيد الله مسلم بن مشكم، عن أبي ثعلبة، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في الأكل والشرب في أواني المشركين وأهل الكتاب وأسقيتهم","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3839) and al-Tabarani in Musnad al-Shamiyyin (783). “Washing” here means cleaning with water.","chapter_en":"What Has Been Reported Concerning Eating and Drinking from the Vessels and Water-Skins of the Polytheists and the People of the Book","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Abu Thaʿlabah al-Khushani narrated that he asked the Messenger of Allah ﷺ, saying: “We live near the People of the Book, and they cook pork in their pots and drink wine from their vessels.” The Messenger of Allah ﷺ said: “If you find other than them, then eat and drink from those. If you do not find other than them, then wash them with water, and eat and drink from them.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3839,"lafz":true},{"key":"sh13162","label":"الطبراني في مسند الشاميين","number":783}],"full":1,"dr":1},{"num":7319,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عمرو:أَنَّ أَعْرَابِيًّا يُقَالُ لَهُ: أَبُو ثَعْلَبَةَ قَالَ : يَا رَسُولَ اللَّهِ إِنَّ لِي كِلاَبًا مُكَلَّبَةً، فَأَفْتِنِي فِي صَيْدِهَا فَقَالَ النَّبِيُّ صَلَّى اللَّهِ عَلَيْهِ وَسَلَّمَ : إِنْ كَانَ لَكَ كِلاَبٌ مُكَلَّبَةٌ فَكُلْ مِمَّا أَمْسَكْنَ عَلَيْكَ قَالَ: ذَكِيًّا أَوْ غَيْرَ ذَكِيٍّ؟ قَالَ: نَعَمْ قَالَ: وَإِنْ أَكَلَ مِنْهُ قَالَ: وَإِنْ أَكَلَ مِنْهُ قَالَ: يَا رَسُولَ اللَّهِ، أَفْتِنِي فِي قَوْسِي قَالَ: كُلْ مَا رَدَّتْ عَلَيْكَ قَوْسُكَ قَالَ: ذَكِيًّا وَ غَيْرَ ذَكِيٍّ قَالَ: وَإِنْ تَغَيَّبَ عَنِّي؟ قَالَ: وَإِنْ تَغَيَّبَ عَنْكَ مَا لَمْ يَصِلَّ، أَوْ تَجِدَ فِيهِ أَثَرًا غَيْرَ سَهْمِكَ قَالَ: أَفْتِنِي فِي آنِيَةِ الْمَجُوسِ إِذَا اضْطُرِرْنَا إِلَيْهَا؟ قَالَ: اغْسِلْهَا وَكُلْ فِيهَا."],"takhrij":"حسن: رواه أبوداود (2857)، وأحمد (6725) كلاهما من طريق حبيب المعلم، عن عمرو بن شعيب، عن أبيه عن جده، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الأكل والشرب في أواني المشركين وأهل الكتاب وأسقيتهم","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2857), Ahmad (6725), and al-Daraqutni (4797).","chapter_en":"What Has Been Reported Concerning Eating and Drinking from the Vessels and Water-Skins of the Polytheists and the People of the Book","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr narrated that a Bedouin called Abu Thaʿlabah said: “O Messenger of Allah, I have trained hunting dogs, so give me a ruling about their game.” The Prophet ﷺ said: “If you have trained hunting dogs, then eat from what they catch for you.” He said: “Whether it is slaughtered or not slaughtered?” He said: “Yes.” He said: “Even if it eats from it?” He said: “Even if it eats from it.” He said: “O Messenger of Allah, give me a ruling about my bow.” He said: “Eat whatever your bow returns to you.” He said: “Whether it is slaughtered or not slaughtered?” He said: “Even if it disappears from me?” He said: “Even if it disappears from you, so long as it does not rot, or you find on it no mark other than your arrow.” He said: “Give me a ruling about the vessels of the Magians if we are forced to use them.” He said: “Wash them and eat from them.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2857,"lafz":true},{"key":"sh9771","label":"الدارقطني","number":4797},{"key":"ahmad","label":"مسند الإمام أحمد","number":6725,"n":6725}],"full":1,"dr":1},{"num":7320,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي دَعْوَةٍ، فَرُفِعَ إِلَيْهِ الذِّرَاعُ، وَكَانَتْ تُعْجِبُهُ، فَنَهَسَ مِنْهَا نَهْسَةً وَقَالَ."],"takhrij":"متفق عليه: رواه البخاري في الأنبياء (3340)، ومسلم في الإيمان (194) كلاهما من طريق أبي حيان، عن أبي زرعة، عن أبي هريرة، فذكره بطوله في الشفاعة يوم الحشر.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أطاييب اللحم","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3340) and Muslim (194).","chapter_en":"What Has Been Reported Concerning the Best Parts of Meat","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: We were with the Prophet ﷺ at an invitation, and the foreleg was raised to him — and he liked it — so he took a bite from it. The hadith."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3340,"lafz":true},{"key":"muslim","label":"مسلم","number":194}],"full":1},{"num":7321,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ شَاةً، طُبِخَتْ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَعْطِنِي الذِّرَاعَ فَنَاوَلَهَا إِيَّاهُ، فَقَالَ: أَعْطِنِي الذِّرَاعَ فَنَاوَلَهَا إِيَّاهُ، ثُمَّ قَالَ: أَعْطِنِي الذِّرَاعَ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّمَا لِلشَّاةِ ذِرَاعَانِ قَالَ: أَمَا إِنَّكَ لَوِ الْتَمَسْتَهَا لَوَجَدْتَهَا."],"takhrij":"حسن: رواه الإمام أحمد (10706)، وابن حبان (6484) كلاهما من حديث ابن عجلان، عن أبيه، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في أطاييب اللحم","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (10706) and Ibn Hibban (6484).","chapter_en":"What Has Been Reported Concerning the Best Parts of Meat","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah narrated that a sheep was cooked, and the Messenger of Allah ﷺ said: “Give me the foreleg.” So he handed it to him. Then he said: “Give me the foreleg.” So he handed it to him. Then he said: “Give me the foreleg.” He said: “O Messenger of Allah, a sheep only has two forelegs!” He said: “If you had looked for it, you would have found it.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":10706,"lafz":true},{"key":"ibnhibban","label":"ابن حبان","number":6484}],"full":1,"dr":1,"rep":[9689]},{"num":7322,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ، قَالَ: كَانَ أَحَبَّ الْعُرَاقِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الذِّرَاعُ، ذِرَاعَ الشَّاةِ، وَقَدْ كَانَ سُمَّ فِيهَا، وَكَانَ يَرَى أَنَّ الْيَهُودَ سَمُّوهُ."],"takhrij":"حسن: رواه أبو داود الطيالسي (388) عن زهير، عن أبي إسحاق، عن سعد ابن عياض، عن عبد الله فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في أطاييب اللحم","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud al-Tayalisi (388), Abu Dawud (3780–3781), al-Tirmidhi in al-Shama’il (170), al-Nasa’i in al-Sunan al-Kubra (6654), and Ahmad (3733).","chapter_en":"What Has Been Reported Concerning the Best Parts of Meat","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullah ibn Masʿud said: The meat-bearing bone most beloved to the Messenger of Allah ﷺ was the foreleg — the foreleg of the sheep. Poison had been placed in it, and it was believed that the Jews had poisoned him with it."]},"buhuth":{"en":["A questioner asked me: What is lawful for us to eat from sheep, cattle, and camels?","The answer: It is lawful to eat everything except flowing blood, due to the statement of Allah the Exalted:","“Say: I do not find in what has been revealed to me anything forbidden to one who eats it, except that it be carrion, flowing blood, the flesh of swine — for it is filth — or a sinful offering dedicated to other than Allah. But whoever is compelled, neither desiring it nor transgressing, then indeed your Lord is Forgiving, Merciful.” [al-Anʿam: 145]","Some scholars regarded eating the testicles, the male reproductive organ, the female private part, and the glands as repulsive, so they considered eating them disliked.","I say: The basic ruling concerning it is permissibility. Whoever does not feel comfortable eating it should not eat it, but he should not declare it disliked, because the ruling of dislike requires a religious proof."]}},"tuhfa":{},"refs":[{"key":"tayalisi","label":"أبو داود الطيالسي","number":388,"lafz":true},{"key":"abudawud","label":"أبو داود","number":3780},{"key":"shamail","label":"الترمذي في الشمائل","number":170},{"key":"kubranasai","label":"النسائي في الكبرى","number":6654},{"key":"ahmad","label":"مسند الإمام أحمد","number":3733,"n":3733}],"full":1,"dr":1},{"num":7323,"demo":false,"sanad":"","matn":["عَنْ زَهْدَمٍ، قَالَ كُنَّا عِنْدَ أَبِي مُوسَى الأَشْعَرِيِّ، وَكَانَ بَيْنَنَا وَبَيْنَ هَذَا الْحَىِّ مِنْ جَرْمٍ إِخَاءٌ، فَأُتِيَ بِطَعَامٍ فِيهِ لَحْمُ دَجَاجٍ، وَفِي الْقَوْمِ رَجُلٌ جَالِسٌ أَحْمَرُ فَلَمْ يَدْنُ مِنْ طَعَامِهِ قَالَ ادْنُ فَقَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْكُلُ مِنْهُ. قَالَ إِنِّي رَأَيْتُهُ أَكَلَ شَيْئًا فَقَذِرْتُهُ، فَحَلَفْتُ أَنْ لاَ آكُلَهُ. فَقَالَ ادْنُ أُخْبِرْكَ ـ أَوْ أُحَدِّثْكَ ـ إِنِّي أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي نَفَرٍ مِنَ الأَشْعَرِيِّينَ، فَوَافَقْتُهُ وَهْوَ غَضْبَانُ، وَهْوَ يَقْسِمُ نَعَمًا مِنْ نَعَمِ الصَّدَقَةِ فَاسْتَحْمَلْنَاهُ فَحَلَفَ أَنْ لاَ يَحْمِلَنَا، قَالَ مَا عِنْدِي مَا أَحْمِلُكُمْ عَلَيْهِ. ثُمَّ أُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِنَهْبٍ مِنْ إِبِلٍ فَقَالَ أَيْنَ الأَشْعَرِيُّونَ أَيْنَ الأَشْعَرِيُّونَ. قَالَ فَأَعْطَانَا خَمْسَ ذَوْدٍ غُرِّ الذُّرَى، فَلَبِثْنَا غَيْرَ بَعِيدٍ، فَقُلْتُ لأَصْحَابِي نَسِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمِينَهُ، فَوَاللَّهِ لَئِنْ تَغَفَّلْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمِينَهُ لاَ نُفْلِحُ أَبَدًا. فَرَجَعْنَا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْنَا يَا رَسُولَ اللَّهِ إِنَّا اسْتَحْمَلْنَاكَ، فَحَلَفْتَ أَنْ لاَ تَحْمِلَنَا فَظَنَنَّا أَنَّكَ نَسِيتَ يَمِينَكَ. فَقَالَ إِنَّ اللَّهَ هُوَ حَمَلَكُمْ، إِنِّي وَاللَّهِ إِنْ شَاءَ اللَّهُ لاَ أَحْلِفُ عَلَى يَمِينٍ فَأَرَى غَيْرَهَا خَيْرًا مِنْهَا إِلاَّ أَتَيْتُ الَّذِي هُوَ خَيْرٌ، وَتَحَلَّلْتُهَا."],"takhrij":"متفق عليه: رواه البخاريّ في الذبائح والصيد (5518)، ومسلم في الأيمان (1649: 9) كلاهما من حديث أيوب، عن القاسم (هو ابن عاصم)، عن زهدم الجرمي فذكره. والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أكل الدجاج","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5518) and Muslim (1649:9). The wording is from al-Bukhari.","chapter_en":"What Has Been Reported Concerning Eating Chicken","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Zahdam said: We were with Abu Musa al-Ashʿari — and there was a bond of brotherhood between us and this clan of Jarm — and food containing chicken meat was brought. Among the people was a red-complexioned man who was sitting and did not come near the food. He said: “Come near, for I saw the Messenger of Allah ﷺ eating from it.” He said: “I saw it eating something, so I found it repulsive, and I swore that I would not eat it.” He said: “Come near, and I will inform you or narrate to you: I came to the Prophet ﷺ with a group of Ashʿaris, and we found him while he was angry, distributing camels from the camels of charity. We asked him for mounts, but he swore that he would not mount us, and said: ‘I have nothing on which to mount you.’ Then the Messenger of Allah ﷺ was brought some camels from war booty, and he said: ‘Where are the Ashʿaris? Where are the Ashʿaris?’ He gave us five camels with white humps. We stayed only a short while, then I said to my companions: ‘The Messenger of Allah ﷺ forgot his oath. By Allah, if we take advantage of the Messenger of Allah ﷺ forgetting his oath, we will never prosper.’ So we returned to the Prophet ﷺ and said: ‘O Messenger of Allah, we asked you for mounts and you swore that you would not mount us, and we thought you had forgotten your oath.’ He said: ‘Allah is the One who mounted you. By Allah, if Allah wills, I do not swear an oath and then see something better than it except that I do what is better and release myself from the oath.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5518,"lafz":true},{"key":"muslim","label":"مسلم","number":9},{"key":"muslim","label":"مسلم في الايمان","number":1649}],"full":1},{"num":7324,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى ـ يَعْنِي الأَشْعَرِيَّ رَضِيَ اللَّهُ عَنْهُ قَالَ رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْكُلُ دَجَاجًا."],"takhrij":"متفق عليه: رواه البخاري في الذبائح والصيد (5517) عن يحيى (هو ابن موسى البلخي)، حدثنا وكيع، عن سفيان، عن أيوب، عن أبي قلابة، عن زهدم الجرمي، عن أبي موسى فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أكل الدجاج","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5517) and Muslim (1649).","chapter_en":"What Has Been Reported Concerning Eating Chicken","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abu Musa al-Ashʿari said: “I saw the Prophet ﷺ eating chicken.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5517,"lafz":true},{"key":"muslim","label":"مسلم","number":1649}],"full":1,"dr":1},{"num":7325,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ أَنْفَجْنَا أَرْنَبًا وَنَحْنُ بِمَرِّ الظَّهْرَانِ، فَسَعَى الْقَوْمُ فَلَغَبُوا، فَأَخَذْتُهَا فَجِئْتُ بِهَا إِلَى أَبِي طَلْحَةَ فَذَبَحَهَا، فَبَعَثَ بِوَرِكَيْهَا ـ أَوْ قَالَ بِفَخِذَيْهَا ـ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ   فَقَبِلَهَا.","وزاد في رواية: قُلْتُ : وَأَكَلَ مِنْهُ؟ ، قَالَ : وَأَكَلَ مِنْهُ."],"takhrij":"متفق عليه: رواه البخاريّ في الذبائح (5535)، ومسلم في الصيد والذبائح (1953)كلاهما من طريق شعبة، عن هشام بن زيد، عن أنس بن مالك، فذكره. والرواية الأخرى عن البخاري في الهبة (2572) من طريق شعبة به.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أكل الأرنب","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5535) and Muslim (1953).","chapter_en":"What Has Been Reported Concerning Eating Rabbit","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Anas said: We stirred up a rabbit while we were at Marr al-Zahran. The people ran after it and became tired, but I caught it and brought it to Abu Talhah. He slaughtered it and sent its two hips — or he said: its two thighs — to the Prophet ﷺ, and he accepted them. In another narration, it is added: I said: “Did he eat from it?” He said: “He ate from it.”"]},"buhuth":{"en":["His statement, “we stirred up,” means we caused it to come out. It is said in Arabic that a rabbit is stirred up when it rises and runs. It is also said that the word means bristling, so the meaning is as though we made it bristle by chasing it. This is mentioned in al-Fath (9/661). “Marr al-Zahran” is the name of a place one stage from Makkah. “They became tired” means they became fatigued, both in wording and meaning."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5535,"lafz":true},{"key":"muslim","label":"مسلم","number":1953},{"key":"فکان_المعنی_جعلناہا_بطلبنا_لہا_تنتفج_کذا/الفتح","label":"فكأن المعنى جعلناها بطلبنا لها تنتفج. كذا في الفتح","number":9},{"key":"bukhari","label":"الروايه الاخري عن البخاري في الهبه","number":2572}],"full":1,"dr":1},{"num":7326,"demo":false,"sanad":"","matn":["عَنْ مُحَمَّدِ بْنِ صَفْوَانَ قَالَ:اصّدتُّ أَرْنَبَيْنِ، فَذَبَحْتُهُمَا بِمَرْوَةٍ، فَسَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهِ عَلَيْهِ وَسَلَّمَ عَنْهُمَا، فَأَمَرَنِي بِأَكْلِهِمَا."],"takhrij":"صحيح: رواه أبوداود (2822)، والنسائي (4313)، وابن ماجه (3175)، وأحمد (15870)، وصحّحه ابن حبان (5887)، والحاكم (4/235) كلهم من طرق عن الشعبي، عن محمد بن صفوان، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل الأرنب","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2822), al-Nasa’i (4313), Ibn Majah (3175), and Ahmad (15870), and authenticated by Ibn Hibban (5887) and al-Hakim (4/236).","chapter_en":"What Has Been Reported Concerning Eating Rabbit","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Muhammad ibn Safwan said: I hunted two rabbits and slaughtered them with a sharp stone. I asked the Messenger of Allah ﷺ about them, and he ordered me to eat them."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2822,"lafz":true},{"key":"nasai","label":"النسائي","number":4313},{"key":"ibnmajah","label":"ابن ماجه","number":3175},{"key":"ibnhibban","label":"صحَّحه ابن حبان","number":5887},{"key":"hakim","label":"الحاكم","number":4},{"key":"ahmad","label":"مسند الإمام أحمد","number":15870,"n":15870}],"full":1,"dr":1,"rep":[7291]},{"num":7327,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمْ قَالَ نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ خَيْبَرَ عَنْ لُحُومِ الْحُمُرِ، وَرَخَّصَ فِي لُحُومِ الْخَيْلِ."],"takhrij":"متفق عليه: رواه البخاري في الذبائح والصيد (5520)، ومسلم في الصيد والذبائح (1941: 36) كلاهم من طريق حماد بن زيد، عن عمرو بن دينار، عن محمد بن علي، عن جابر بن عبد الله فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أكل لحوم الخيل","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5520) and Muslim (1941:36).","chapter_en":"What Has Been Reported Concerning Eating Horse Meat","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Jabir said: On the day of Khaybar, the Prophet ﷺ forbade the meat of donkeys and permitted the meat of horses."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5520,"lafz":true},{"key":"muslim","label":"مسلم","number":36},{"key":"muslim","label":"مسلم في الصيد والذبائح","number":1941}],"full":1},{"num":7328,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ يَقُولُ أَكَلْنَا زَمَنَ خَيْبَرَ الْخَيْلَ وَحُمُرَ الْوَحْشِ وَنَهَانَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْحِمَارِ الأَهْلِيِّ."],"takhrij":"صحيح: رواه مسلم في الصيد والذبائح (1941: 37) عن محمد بن حاتم، حدثنا محمد بن بكر، أخبرنا ابن جريج، أخبرني أبو الزبير، أنه سمع جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل لحوم الخيل","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1941:37).","chapter_en":"What Has Been Reported Concerning Eating Horse Meat","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: During the time of Khaybar, we ate horses and wild donkeys, and the Prophet ﷺ forbade us from domestic donkeys."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":37,"lafz":true},{"key":"muslim","label":"مسلم في الصيد والذبائح","number":1941,"n":5023}],"full":1,"rep":[7333]},{"num":7329,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ ذَبَحْنَا يَوْمَ خَيْبَرَ الْخَيْلَ وَالْبِغَالَ وَالْحَمِيرَ فَنَهَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْبِغَالِ وَالْحَمِيرِ وَلَمْ يَنْهَنَا عَنِ الْخَيْلِ."],"takhrij":"صحيح: رواه أبو داود (3789)، وأحمد (14840) وصحّحه ابن حبان (5272)، والحاكم (4/235) كلهم من طرق عن حماد بن سلمة، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل لحوم الخيل","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3789) and Ahmad (14840), and authenticated by Ibn Hibban (5272) and al-Hakim (4/235).","chapter_en":"What Has Been Reported Concerning Eating Horse Meat","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: On the day of Khaybar, we slaughtered horses, mules, and donkeys. The Messenger of Allah ﷺ forbade us from mules and donkeys, but he did not forbid us from horses."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3789,"lafz":true},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":5272},{"key":"hakim","label":"الحاكم","number":4},{"key":"ahmad","label":"مسند الإمام أحمد","number":14840,"n":14840}],"full":1,"dr":1,"rep":[7431]},{"num":7330,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ كُنَّا نَأْكُلُ لُحُومَ الْخَيْلِ.","قال عطاء: والبغال؟ قال: لا."],"takhrij":"صحيح: رواه النسائي (4333)، وابن ماجه (3197) كلاهما من طريق عبد الكريم الجزري، عن عطاء، عن جابر، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل لحوم الخيل","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (4333) and Ibn Majah (3197).","chapter_en":"What Has Been Reported Concerning Eating Horse Meat","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: We used to eat horse meat. ʿAta’ said: “And mules?” He said: “No.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4333,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":3197}],"full":1,"dr":1},{"num":7331,"demo":false,"sanad":"","matn":["عن أسماء قالت: نحرنا فرسا على عهد رسول الله صلى الله عليه وسلم فأكلناه. وفي رواية قالت: \" ذبحنا\" وزاد \"ونحن بالمدينة\"."],"takhrij":"متفق عليه: رواه البخاري في الذبائح والصيد (5519)، ومسلم في الصيد والذبائح (1942) كلاهما من طريق هشام (هو ابن عروة)، عن فاطمة (هي بنت المنذر بن الزبير) عن أسماء بنت أبي بكر، فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أكل لحوم الخيل","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5519) and Muslim (1942).","chapter_en":"What Has Been Reported Concerning Eating Horse Meat","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Asma’ said: We slaughtered a horse during the time of the Messenger of Allah ﷺ and ate it. In another narration she said: “We slaughtered,” and it adds: “while we were in Madinah.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5519,"lafz":true},{"key":"muslim","label":"مسلم","number":1942}],"full":1,"dr":1},{"num":7332,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ لُحُومِ الْحُمُرِ، وَأَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِلُحُومِ الْخَيْلِ أَنْ يُؤْكَلَ."],"takhrij":"حسن: رواه الطبراني في الكبير (12/180)، والأوسط (5760)، والدارقطني (4782) من طريق محمد بن عبد الله بن سليمان الحضرمي، ثنا محمد بن عُبيد المحاربي، ثنا عمر بن عبيد، عن سماك بن حرب، عن جابر بن زيد، عن ابن عباس، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في أكل لحوم الخيل","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Muʿjam al-Kabir (12/180), al-Awsat (5760), and al-Daraqutni (4782).","chapter_en":"What Has Been Reported Concerning Eating Horse Meat","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ forbade the meat of donkeys, and the Messenger of Allah ﷺ commanded that horse meat be eaten."]},"buhuth":{"en":["Ibn ʿAbd al-Barr said: “As for the scholars of hadith, the hadith permitting horse meat is more authentic and more firmly established with them than the prohibition of eating it.”","Abu Dawud said after mentioning the hadiths prohibiting horse meat: “This is abrogated. A group of the Companions of the Prophet ﷺ ate horse meat, among them: Ibn al-Zubayr, Fadalah ibn ʿUbayd, Anas ibn Malik, and Asma’ bint Abi Bakr; and among the Followers: Suwayd ibn Ghafalah, ʿAlqamah, and others. Quraysh used to slaughter horses during the time of the Messenger of Allah ﷺ.” Sunan Abi Dawud (3792)."]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في المعجم الكبير","number":12,"lafz":true},{"key":"sh28171","label":"الأوسط","number":5760},{"key":"sh9771","label":"الدارقطني","number":4782}],"full":1,"dr":1},{"num":7333,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ يَقُولُ أَكَلْنَا زَمَنَ خَيْبَرَ الْخَيْلَ وَحُمُرَ الْوَحْشِ وَنَهَانَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْحِمَارِ الأَهْلِيِّ."],"takhrij":"صحيح: رواه مسلم (1941: 37) من طريق ابن جريج، أخبرني أبو الزبير أنه سمع جابر بن عبد الله يقول: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل لحوم حمر الوحش","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1941:37).","chapter_en":"What Has Been Reported Concerning Eating the Meat of Wild Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: During the time of Khaybar, we ate horses and wild donkeys, and the Prophet ﷺ forbade us from domestic donkeys."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":37,"lafz":true},{"key":"muslim","label":"مسلم","number":1941,"n":5023}],"full":1,"rep":[7328]},{"num":7334,"demo":false,"sanad":"","matn":["عن عبدالله بن أبي أوفى قال: غزونا مع النبي صلي الله عليه وسلم سبع غزوات أو ستا، كنا نأكل معه الجراد. وفي رواية: \"سبع غزوات\" بالجزم."],"takhrij":"متفق عليه: روا ه البخاري في الذبائح والصيد (5495)، ومسلم في الصيد والذبائح (1952) كلاهما من طريق شعبة، عن أبي يعفور، قال: سمعت ابن أبي أوفى فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أكل الجراد","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5495) and Muslim (1952). The wording is from al-Bukhari.","chapter_en":"What Has Been Reported Concerning Eating Locusts","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullah ibn Abi Awfa said: We went on seven or six military expeditions with the Prophet ﷺ, and we used to eat locusts with him. In another narration: “seven military expeditions,” stated decisively."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5495,"lafz":true},{"key":"muslim","label":"مسلم","number":1952}],"full":1,"dr":1},{"num":7335,"demo":false,"sanad":"","matn":["عَنْ أَبِي زُهَيْرٍ النُّمَيْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تَقْتُلُوا الْجَرَادَ؛ فَإِنَّهُ جُنْدٌ مِنْ جُنُودِ اللَّهِ."],"takhrij":"حسن: رواه ابن أبي عاصم في الآحاد والمثاني (1440) عن عبدالوهاب بن نجدة الحوطي، حدثنا إسماعيل بن عياش، حدثني ضمضم بن زرعة، عن شريح بن عبيد، عن أبي زهير النميري قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في أكل الجراد","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abi ʿAsim in al-Ahad wa al-Mathani (1440), al-Tabarani in al-Kabir (22/297, no. 757), al-Awsat (9277), Musnad al-Shamiyyin (1656), and Abu Nuʿaym in Maʿrifat al-Sahabah (6804).","chapter_en":"What Has Been Reported Concerning Eating Locusts","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abu Zuhayr al-Numayri said: The Messenger of Allah ﷺ said: “Do not kill locusts, for they are an army from the armies of Allah.”"]}},"tuhfa":{},"refs":[{"key":"sh9196","label":"ابن أبي عاصم في الآحاد والمثاني","number":1440,"lafz":true},{"key":"mujamkabir","label":"الطبراني في الكبير","number":22},{"key":"sh28171","label":"وفي الأوسط","number":9277},{"key":"sh13162","label":"وفي مسند الشاميين","number":1656},{"key":"sh10490","label":"أبو نعيم في معرفة الصحابة","number":6804}],"full":1,"dr":1},{"num":7336,"demo":false,"sanad":"","matn":["عن أَبِي عمار قَالَ قُلْتُ لِجَابِرٍ الضَّبُعُ صَيْدٌ هِيَ قَالَ نَعَمْ. قَالَ قُلْتُ آكُلُهَا قَالَ نَعَمْ. قَالَ قُلْتُ لَهُ أَقَالَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ نَعَمْ."],"takhrij":"صحيح: رواه الترمذي (1791)، والنسائي (2836، 4323)، وصحّحه ابن خزيمة (2645)، وابن حبان (3695)، والحاكم (1/452) كلهم من طرق عن ابن جريج قال: أخبرني عبد الله بن عبيد بن عمير، عن ابن أبي عمار قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل الضبع","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1791) and al-Nasa’i (4323, 2836), and authenticated by Ibn Khuzaymah (2645), Ibn Hibban (3965), and al-Hakim (1/452).","chapter_en":"What Has Been Reported Concerning Eating Hyena","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Abu ʿAmmar said: I said to Jabir: “Is the hyena game?” He said: “Yes.” I said: “May I eat it?” He said: “Yes.” I said to him: “Did the Messenger of Allah ﷺ say that?” He said: “Yes.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1791,"lafz":true},{"key":"nasai","label":"النسائي","number":4323},{"key":"ibnkhuzaymah","label":"صحَّحه ابن خزيمة","number":2645},{"key":"ibnhibban","label":"ابن حبان","number":3965},{"key":"hakim","label":"الحاكم","number":1},{"key":"nasai","label":"النسائي","number":2836},{"key":"ibnhibban","label":"ابن حبان","number":3695}],"full":1,"dr":1},{"num":7337,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الضَّبُعِ فَقَالَ هُوَ صَيْدٌ وَيُجْعَلُ فِيهِ كَبْشٌ إِذَا صَادَهُ الْمُحْرِمُ."],"takhrij":"صحيح: رواه أبوداود (3801)، وابن ماجه (3085)، وصحّحه ابن خزيمة (2646)، وابن حبان (3964)، والحاكم (1/452-453) كلهم من طرق عن جرير بن حازم، عن عبد الله بن عبيد، عن عبد الرحمن بن أبي عمار، عن جابر فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل الضبع","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3801) and Ibn Majah (3085), and authenticated by Ibn Khuzaymah (2646), Ibn Hibban (3964), and al-Hakim (1/452–453).","chapter_en":"What Has Been Reported Concerning Eating Hyena","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: I asked the Messenger of Allah ﷺ about the hyena, and he said: “It is game, and a ram is due for it if a person in the state of consecration hunts it.”"]},"buhuth":{"en":["This does not contradict the hadith, “Every predator with fangs,” because that hadith is general, while this one is specific. It has also been said that the hyena does not have fangs."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3801,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":3085},{"key":"ibnkhuzaymah","label":"صحَّحه ابن خزيمة","number":2646},{"key":"ibnhibban","label":"ابن حبان","number":3964},{"key":"hakim","label":"الحاكم","number":1}],"full":1,"dr":1,"rep":[4839]},{"num":7338,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ يَقُولُ أُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِضَبٍّ فَأَبَى أَنْ يَأْكُلَ مِنْهُ وَقَالَ لاَ أَدْرِي لَعَلَّهُ مِنَ الْقُرُونِ الَّتِي مُسِخَتْ."],"takhrij":"صحيح: رواه مسلم في الصيد والذبائح (1949) من طريق عبد الرزاق، عن ابن جريج، اخبرني أبو الزبير، أنه سمع جابر بن عبد الله يقول فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في كراهة أكل الضب","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1949).","chapter_en":"What Has Been Reported Concerning the Dislike of Eating Spiny-Tailed Lizard","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: A spiny-tailed lizard was brought to the Messenger of Allah ﷺ, but he refused to eat from it and said: “I do not know; perhaps it is from the generations that were transformed.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1949,"lafz":true}],"full":1},{"num":7339,"demo":false,"sanad":"","matn":["عَبْدِ الرَّحْمَنِ بْنِ شِبْلٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ أَكْلِ لَحْمِ الضَّبِّ."],"takhrij":"حسن: رواه أبو داود (3796)، والبيهقي (9/326)، وابن جرير الطبري في تهذيب الآثار (311- مسند عمر بن الخطاب) كلهم من طريق أبي اليمان الحكم بن نافع، حدثنا إسماعيل بن عياش، عن ضمضم بن زرعة، عن شريح بن عبيد، عن أبي راشد الحبراني، عن عبد الرحمن بن شبل فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في كراهة أكل الضب","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3796), al-Bayhaqi (9/326), and Ibn Jarir al-Tabari in Tahdhib al-Athar (311).","chapter_en":"What Has Been Reported Concerning the Dislike of Eating Spiny-Tailed Lizard","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["ʿAbd al-Rahman ibn Shibl narrated that the Messenger of Allah ﷺ forbade eating the meat of the spiny-tailed lizard."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3796,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":9},{"key":"rb335","label":"ابن جرير الطبري في تهذيب الآثار","number":311}],"full":1,"dr":1},{"num":7340,"demo":false,"sanad":"","matn":["عَنْ ثَابِتِ بْنِ وَدِيعَةَ، قَالَ كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي جَيْشٍ فَأَصَبْنَا ضِبَابًا - قَالَ - فَشَوَيْتُ مِنْهَا ضَبًّا فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَوَضَعْتُهُ بَيْنَ يَدَيْهِ - قَالَ - فَأَخَذَ عُودًا فَعَدَّ بِهِ أَصَابِعَهُ ثُمَّ قَالَ إِنَّ أُمَّةً مِنْ بَنِي إِسْرَائِيلَ مُسِخَتْ دَوَابَّ فِي الأَرْضِ وَإِنِّي لاَ أَدْرِي أَىُّ الدَّوَابِّ هِيَ. قَالَ فَلَمْ يَأْكُلْ وَلَمْ يَنْهَ."],"takhrij":"صحيح: رواه أبو داود (3795)، والنسائي (4320)، وابن ماجه (3238)، وأحمد (17931) من طرق عن حصين، عن زيد بن وهب الجهني، عن ثابت بن يزيد بن وديعة الأنصاري فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في كراهة أكل الضب","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3795), al-Nasa’i (4320), Ibn Majah (3238), and Ahmad (17931).","chapter_en":"What Has Been Reported Concerning the Dislike of Eating Spiny-Tailed Lizard","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Thabit ibn Wadiʿah said: We were with the Messenger of Allah ﷺ in an army, and we caught some spiny-tailed lizards. He said: I roasted one of them and brought it to the Messenger of Allah ﷺ, placing it before him. He said: He took a stick and counted his fingers with it, then said: “A nation from the Children of Israel was transformed into creatures on the earth, and I do not know which creatures they are.” He said: So he did not eat, and he did not forbid it."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3795,"lafz":true},{"key":"nasai","label":"النسائي","number":4320},{"key":"ibnmajah","label":"ابن ماجه","number":3238},{"key":"ahmad","label":"مسند الإمام أحمد","number":17931,"n":17931}],"full":1,"dr":1},{"num":7341,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ حَسَنَةَ، - قَالَ: وَكِيعٌ: الْجُهَنِيُّ - قَالَ: غَزَوْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَصَابَتْنَا مَجَاعَةٌ، فَنَزَلْنَا بِأَرْضٍ كَثِيرَةِ الضِّبَابِ، فَاتَّخَذْنَا مِنْهَا، فَطَبَخْنَا فِي قُدُورِنَا، فَسَأَلْنَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: أُمَّةٌ فُقِدَتْ، - أَوْ مُسِخَتْ، شَكَّ يَحْيَى - وَاللهُ أَعْلَمُ فَأَمَرَنَا فَأَكْفَأْنَا الْقُدُورَ قَالَ وَكِيعٌ: مُسِخَتْ، فَأَخْشَى أَنْ تَكُونَ هَذِهِ فَأَكْفَأْنَاهَا وَإِنَّا لَجِيَاعٌ."],"takhrij":"صحيح: رواه أحمد (17759، 17757)، والبزار (كشف الأستار 1217) وأبو يعلى (931) وعنه ابن حبان (5266) كلهم من طرق عن الأعمش، عن زيد بن وهب، عن عبد الرحمن بن حسنة، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في كراهة أكل الضب","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (17757, 17759), al-Bazzar (Kashf al-Astar 1217), Abu Yaʿla (931), and from him Ibn Hibban (5266).","chapter_en":"What Has Been Reported Concerning the Dislike of Eating Spiny-Tailed Lizard","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["ʿAbd al-Rahman ibn Hasanah said: We went on a military expedition with the Messenger of Allah ﷺ and were struck by hunger. We stopped in a land with many spiny-tailed lizards, so we took some of them and cooked them in our pots. We asked the Prophet ﷺ, and he said: “A nation was lost or transformed” — Yahya was uncertain — and Allah knows best. So he ordered us, and we overturned the pots. Wakiʿ said: “transformed,” meaning: I fear these may be from them. So we overturned them, even though we were hungry."]}},"tuhfa":{},"refs":[{"key":"bazzar","label":"البزار","number":1217},{"key":"sh12520","label":"أبو يعلى","number":931},{"key":"ibnhibban","label":"عنه ابن حبان","number":5266},{"key":"ahmad","label":"مسند الإمام أحمد","number":17757,"n":17759,"lafz":true},{"key":"ahmad","label":"احمد","number":17759}],"full":1,"dr":1},{"num":7342,"demo":false,"sanad":"","matn":["عن حذيفة قال: قال رسول الله صلي الله عليه وسلم: إن الضب أمة مسخت دوابا في الأرض، أو أن الضباب دواب مسخت في الأرض."],"takhrij":"صحيح: رواه البزار (2813) من طريق عبيد الله بن موسى، أنا شعبة، عن حصين، عن زيد بن وهب، عن حذيفة، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في كراهة أكل الضب","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bazzar (2813) and Imam Ahmad (23315).","chapter_en":"What Has Been Reported Concerning the Dislike of Eating Spiny-Tailed Lizard","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Hudhayfah said: The Messenger of Allah ﷺ said: “The spiny-tailed lizard is a nation that was transformed into creatures on the earth,” or, “Spiny-tailed lizards are creatures that were transformed on the earth.”"]}},"tuhfa":{},"refs":[{"key":"bazzar","label":"البزار","number":2813,"lafz":true},{"key":"ahmad","label":"الإمام أحمد","number":23315},{"key":"sh12862","label":"البزار","number":2813}],"full":1,"dr":1},{"num":7343,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جُنْدُبٍ، قَالَ: أَتَى نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَعْرَابِيٌّ وَهُوَ يَخْطُبُ، فَقَطَعَ عَلَيْهِ خُطْبَتَهُ، فَقَالَ: يَا رَسُولَ اللَّهِ، كَيْفَ تَقُولُ فِي الضَّبِّ؟ قَالَ: أُمَّةٌ مُسِخَتْ مِنْ بَنِي إِسْرَائِيلَ، فَلَا أَدْرِي أَيَّ الدَّوَابِّ مُسِخَتْ؟"],"takhrij":"حسن: رواه الإمام أحمد (20209، 20240)، والبزار (كشف الأستار1216)، والطبراني في الكبير (6788، 6790) كلهم من طريق أبي عوانة، ثنا عبد الملك بن عمير، عن حصين، عن سمرة بن جندب، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في كراهة أكل الضب","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (20240, 20209), al-Bazzar (Kashf al-Astar 1216), and al-Tabarani in al-Kabir (6790, 6788).","chapter_en":"What Has Been Reported Concerning the Dislike of Eating Spiny-Tailed Lizard","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Samurah ibn Jundub said: A Bedouin came to the Prophet of Allah ﷺ while he was delivering a sermon and interrupted his sermon. He said: “O Messenger of Allah, what do you say about the spiny-tailed lizard?” He said: “A nation from the Children of Israel was transformed, and I do not know which creatures were transformed.”"]},"buhuth":{"en":["His statement, “was transformed”: the Prophet ﷺ said this at first, so he refrained from eating it, and so did his Companions.","Then the Prophet ﷺ informed that those who were transformed have no offspring, as Muslim narrated in the Book of Divine Decree (2663:33) from the hadith of Ibn Masʿud. In it, a man said: “O Messenger of Allah, are monkeys and pigs among those who were transformed?” The Prophet ﷺ said:","“Allah, the Mighty and Majestic, did not destroy a people or punish a people and then give them offspring. Monkeys and pigs existed before that.”","So he allowed eating it, but he ﷺ did not eat it because it was not from the food of his people, and whoever is not accustomed to eating something does not find it pleasant. Here are the hadiths showing the permissibility of eating spiny-tailed lizard and that it is not forbidden."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":20240,"lafz":true,"n":20209},{"key":"bazzar","label":"البزار","number":1216},{"key":"mujamkabir","label":"الطبراني في الكبير","number":6790},{"key":"ahmad","label":"الامام احمد","number":20209},{"key":"mujamkabir","label":"الطبراني في الكبير","number":6788}],"full":1,"dr":1},{"num":7344,"demo":false,"sanad":"","matn":["عن ابن عمر قال:سئل النبي صلى الله عليه وسلم عن الضب؟ فقال: لستُ بآكله و لا بمحرمه."],"takhrij":"متفق عليه: رواه مالك في الاستئذان (11) عن عبد الله بن دينار، عن عبد الله بن عمر فذكره. ورواه البخاريّ في الذبائح والصيد (5536)، ومسلم في الصيد والذبائح (1943: 39) كلاهما من أوجه أخرى عن عبد الله بن دينار فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في جواز أكل الضب","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (11), al-Bukhari (5536), and Muslim (1943:39).","chapter_en":"What Has Been Reported Concerning the Permissibility of Eating Spiny-Tailed Lizard","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿUmar said: The Prophet ﷺ was asked about the spiny-tailed lizard, and he said: “I do not eat it, but I do not forbid it.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":11,"lafz":true},{"key":"bukhari","label":"البخاري","number":5536},{"key":"muslim","label":"مسلم","number":39},{"key":"muslim","label":"مسلم في الصيد والذبائح","number":1943}],"full":1,"dr":1},{"num":7345,"demo":false,"sanad":"","matn":["عَنْ خَالِدِ بْنِ الْوَلِيدِ بن الْمُغِيرَةِ، قَالَ: أَنَّهُ دَخَلَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْتَ مَيْمُونَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأُتِيَ بِضَبٍّ مَحْنُوذٍ، فَأَهْوَى إِلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ، فَقَالَ بَعْضُ النِّسْوَةِ اللاتي فِي بَيْتَ مَيْمُونَةَ: أَخْبِرُوا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَا يُرِيدُ أَنْ يَأْكُلَ مِنْهُ، فَقِيلَ: هُوَ ضبٌّ يَا رَسُولَ اللَّهِ، فَرَفَعَ يَدَهُ، فَقُلْتُ: أ حرام ٌ هُوَ يَا رَسُولَ اللَّهِ؟ فَقَالَ: لاَ. وَلَكِنَّهُ لَمْ يَكُنْ بِأَرْضِ قَوْمِي، فَأَجِدُنِي أَعَافُهُ قَالَ خَالِدٌ: فَاجْتَرَرْتُهُ فَأَكَلْتُهُ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْظُرُ."],"takhrij":"متفق عليه: رواه مالك في الاستئذان (10) عن ابن شهاب، عن أبي أمامة بن سهل بن حُنيف، عن عبد الله بن عباس، عن خالد بن الوليد، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في جواز أكل الضب","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (10), al-Bukhari (5537), and Muslim (1945).","chapter_en":"What Has Been Reported Concerning the Permissibility of Eating Spiny-Tailed Lizard","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Khalid ibn al-Walid ibn al-Mughirah said that he entered with the Messenger of Allah ﷺ the house of Maymunah, the wife of the Prophet ﷺ. A roasted spiny-tailed lizard was brought, and the Messenger of Allah ﷺ reached his hand toward it. Some of the women who were in Maymunah’s house said: “Tell the Messenger of Allah ﷺ what he is about to eat.” It was said: “It is a spiny-tailed lizard, O Messenger of Allah.” So he withdrew his hand. I said: “Is it forbidden, O Messenger of Allah?” He said: “No. But it was not found in the land of my people, so I find myself disliking it.” Khalid said: So I pulled it toward myself and ate it while the Messenger of Allah ﷺ was looking."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":10,"lafz":true},{"key":"bukhari","label":"البخاري","number":5537},{"key":"muslim","label":"مسلم","number":1945}],"full":1,"dr":1},{"num":7346,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ أَهْدَتْ خَالَتِي إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ضِبَابًا وَأَقِطًا وَلَبَنًا، فَوُضِعَ الضَّبُّ عَلَى مَائِدَتِهِ، فَلَوْ كَانَ حَرَامًا لَمْ يُوضَعْ وَشَرِبَ اللَّبَنَ، وَأَكَلَ الأَقِطَ."],"takhrij":"صحيح: رواه البخاري (5402) عن مسلم بن إبراهيم، حدثنا شعبة، عن أبي بشر، عن سعيد، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في جواز أكل الضب","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5402).","chapter_en":"What Has Been Reported Concerning the Permissibility of Eating Spiny-Tailed Lizard","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿAbbas said: My maternal aunt gifted the Prophet ﷺ some spiny-tailed lizards, dried yogurt, and milk. The spiny-tailed lizard was placed on his table; if it had been forbidden, it would not have been placed there. He drank the milk and ate the dried yogurt."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5402,"lafz":true}],"full":1,"dr":1},{"num":7347,"demo":false,"sanad":"","matn":["عَنْ تَوْبَةَ الْعَنْبَرِيِّ، قَالَ قَالَ لِي الشَّعْبِيُّ أَرَأَيْتَ حَدِيثَ الْحَسَنِ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَاعَدْتُ ابْنَ عُمَرَ قَرِيبًا مِنْ سَنَتَيْنِ أَوْ سَنَةٍ وَنِصْفٍ فَلَمْ أَسْمَعْهُ يُحَدِّثُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَيْرَ هَذَا قَالَ كَانَ نَاسٌ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهِمْ سَعْدٌ فَذَهَبُوا يَأْكُلُونَ مِنْ لَحْمٍ، فَنَادَتْهُمُ امْرَأَةٌ مِنْ بَعْضِ أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّهُ لَحْمُ ضَبٍّ فَأَمْسَكُوا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُلُوا ـ أَوِ اطْعَمُوا ـ فَإِنَّهُ حَلاَلٌ ـ أَوْ قَالَ لاَ بَأْسَ بِهِ. شَكَّ فِيهِ ـ وَلَكِنَّهُ لَيْسَ مِنْ طَعَامِي."],"takhrij":"متفق عليه: رواه البخاري في أخبار الآحاد (7267)، ومسلم في الصيد والذبائح (1944) كلاهما من طريق محمد بن جعفر، حدثنا شعبة، عن توبة العنبري قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في جواز أكل الضب","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7267) and Muslim (1944). The wording is from al-Bukhari.","chapter_en":"What Has Been Reported Concerning the Permissibility of Eating Spiny-Tailed Lizard","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Tawbah al-ʿAnbari said: Al-Shaʿbi said to me: “What do you think of al-Hasan’s narration from the Prophet ﷺ? I sat with Ibn ʿUmar for nearly two years, or a year and a half, and I did not hear him narrate from the Prophet ﷺ except this: Some of the Companions of the Prophet ﷺ, among whom was Saʿd, went to eat some meat. A woman from among the wives of the Prophet ﷺ called out to them: ‘It is spiny-tailed lizard meat.’ So they stopped. The Messenger of Allah ﷺ said: ‘Eat’ — or ‘Feed others’ — ‘for it is lawful,’” or he said: “There is no harm in it,” he was uncertain, “but it is not from my food.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7267,"lafz":true},{"key":"muslim","label":"مسلم","number":1944}],"full":1,"dr":1},{"num":7348,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ سَأَلَ رَجُلٌ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ عَلَى الْمِنْبَرِ عَنْ أَكْلِ الضَّبِّ فَقَالَ لاَ آكُلُهُ وَلاَ أُحَرِّمُهُ."],"takhrij":"صحيح: رواه مسلم في الصيد والذبائح (1943: 41) عن محمد بن عبد الله بن نمير، حدثنا أبي، حدثنا عبيد الله، عن نافع، عن ابن عمر، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في جواز أكل الضب","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1943:41).","chapter_en":"What Has Been Reported Concerning the Permissibility of Eating Spiny-Tailed Lizard","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: A man asked the Messenger of Allah ﷺ while he was on the pulpit about eating spiny-tailed lizard. He said: “I do not eat it, and I do not forbid it.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":41,"lafz":true},{"key":"muslim","label":"مسلم في الصيد والذبائح","number":1943,"n":5029}],"full":1},{"num":7349,"demo":false,"sanad":"","matn":["عَنْ يَزِيدَ بْنِ، الأَصَمِّ قَالَ دَعَانَا عَرُوسٌ بِالْمَدِينَةِ فَقَرَّبَ إِلَيْنَا ثَلاَثَةَ عَشَرَ ضَبًّا فَآكِلٌ وَتَارِكٌ فَلَقِيتُ ابْنَ عَبَّاسٍ مِنَ الْغَدِ فَأَخْبَرْتُهُ فَأَكْثَرَ الْقَوْمُ حَوْلَهُ حَتَّى قَالَ بَعْضُهُمْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ آكُلُهُ وَلاَ أَنْهَى عَنْهُ وَلاَ أُحَرِّمُهُ. فَقَالَ ابْنُ عَبَّاسٍ بِئْسَ مَا قُلْتُمْ مَا بُعِثَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلاَّ مُحِلاًّ وَمُحَرِّمًا إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَمَا هُوَ عِنْدَ مَيْمُونَةَ وَعِنْدَهُ الْفَضْلُ بْنُ عَبَّاسٍ وَخَالِدُ بْنُ الْوَلِيدِ وَامْرَأَةٌ أُخْرَى إِذْ قُرِّبَ إِلَيْهِمْ خِوَانٌ عَلَيْهِ لَحْمٌ فَلَمَّا أَرَادَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَأْكُلَ قَالَتْ لَهُ مَيْمُونَةُ إِنَّهُ لَحْمُ ضَبٍّ. فَكَفَّ يَدَهُ وَقَالَ هَذَا لَحْمٌ لَمْ آكُلْهُ قَطُّ. وَقَالَ لَهُمْ كُلُوا. فَأَكَلَ مِنْهُ الْفَضْلُ وَخَالِدُ بْنُ الْوَلِيدِ وَالْمَرْأَةُ. وَقَالَتْ مَيْمُونَةُ لاَ آكُلُ مِنْ شَىْءٍ إِلاَّ شَىْءٌ يَأْكُلُ مِنْهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه مسلم في الصيد والذبائح (1948) عن أبي بكر بن أبي شيبة، حدثنا علي بن مسهر، عن الشيباني، عن يزيد بن الأصم، قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في جواز أكل الضب","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1948).","chapter_en":"What Has Been Reported Concerning the Permissibility of Eating Spiny-Tailed Lizard","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Yazid ibn al-Asamm said: A bridegroom invited us in Madinah, and thirteen spiny-tailed lizards were brought near to us. Some ate, and some left them. I met Ibn ʿAbbas the next day and informed him. The people around him began speaking a lot, until some of them said: The Messenger of Allah ﷺ said: “I do not eat it, I do not forbid it, and I do not declare it unlawful.” Ibn ʿAbbas said: “How bad is what you have said. The Prophet of Allah ﷺ was only sent to declare lawful and unlawful. The Messenger of Allah ﷺ was with Maymunah, and with him were al-Fadl ibn ʿAbbas, Khalid ibn al-Walid, and another woman. A table with meat on it was brought near to them. When the Prophet ﷺ wanted to eat, Maymunah said to him: ‘It is spiny-tailed lizard meat.’ So he withdrew his hand and said: ‘This is meat that I have never eaten.’ And he said to them: ‘Eat.’ So al-Fadl, Khalid ibn al-Walid, and the woman ate from it. Maymunah said: ‘I will not eat anything except something the Messenger of Allah ﷺ eats from.’”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1948,"lafz":true}],"full":1},{"num":7350,"demo":false,"sanad":"","matn":["عَنْ أَبِي الزُّبَيْرِ، قَالَ سَأَلْتُ جَابِرًا عَنِ الضَّبِّ، فَقَالَ لاَ تَطْعَمُوهُ. وَقَذِرَهُ وَقَالَ قَالَ عُمَرُ بْنُ الْخَطَّابِ إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يُحَرِّمْهُ. إِنَّ اللَّهَ عَزَّ وَجَلَّ يَنْفَعُ بِهِ غَيْرَ وَاحِدٍ فَإِنَّمَا طَعَامُ عَامَّةِ الرِّعَاءِ مِنْهُ وَلَوْ كَانَ عِنْدِي طَعِمْتُهُ."],"takhrij":"صحيح: رواه مسلم في الصيد والذبائح (1950) عن سلمة بن شبيب، حدثنا الحسن بن أعين، حدثنا معقل، عن أبي الزبير، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في جواز أكل الضب","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1950).","chapter_en":"What Has Been Reported Concerning the Permissibility of Eating Spiny-Tailed Lizard","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Abu al-Zubayr said: I asked Jabir about the spiny-tailed lizard. He said: “Do not eat it,” and he found it repulsive. He said: ʿUmar ibn al-Khattab said: “The Prophet ﷺ did not forbid it. Allah, the Mighty and Majestic, benefits many people through it. It is the food of most shepherds. If I had some with me, I would eat it.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1950,"lafz":true}],"full":1},{"num":7351,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، قَالَ قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ إِنَّا بِأَرْضٍ مَضَبَّةٍ فَمَا تَأْمُرُنَا أَوْ فَمَا تُفْتِينَا قَالَ ذُكِرَ لِي أَنَّ أُمَّةً مِنْ بَنِي إِسْرَائِيلَ مُسِخَتْ. فَلَمْ يَأْمُرْ وَلَمْ يَنْهَ.","قال أبو سعيد: فلما كان بعد ذلك، قال عمر: إن الله عز وجل لينفع به غير واحد، وإنه لطعام عامة هذه الرعاء، ولو كان عندي لطعمته، إنما عافه رسول الله صلى الله عليه وسلم."],"takhrij":"صحيح: رواه مسلم في في الصيد والذبائح (1951: 50) عن محمد بن المثنى، حدثنا ابن أبي عدي، عن داود، عن أبي نضرة، عن أبي سعيد، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في جواز أكل الضب","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1951:50).","chapter_en":"What Has Been Reported Concerning the Permissibility of Eating Spiny-Tailed Lizard","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Abu Saʿid said: A man said: “O Messenger of Allah, we are in a land full of spiny-tailed lizards, so what do you command us?” or, “What ruling do you give us?” He said: “It was mentioned to me that a nation from the Children of Israel was transformed.” So he neither commanded nor forbade. Abu Saʿid said: Later on, ʿUmar said: “Allah, the Mighty and Majestic, benefits many people through it, and it is the food of most of these shepherds. If I had some with me, I would eat it. The Messenger of Allah ﷺ only found it distasteful.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":50,"lafz":true},{"key":"muslim","label":"مسلم في في الصيد والذبائح","number":1951}],"full":1},{"num":7352,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، أَنَّ أَعْرَابِيًّا، أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ إِنِّي فِي غَائِطٍ مَضَبَّةٍ وَإِنَّهُ عَامَّةُ طَعَامِ أَهْلِي - قَالَ - فَلَمْ يُجِبْهُ فَقُلْنَا عَاوِدْهُ. فَعَاوَدَهُ فَلَمْ يُجِبْهُ ثَلاَثًا ثُمَّ نَادَاهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الثَّالِثَةِ فَقَالَ يَا أَعْرَابِيُّ إِنَّ اللَّهَ لَعَنَ أَوْ غَضِبَ عَلَى سِبْطٍ مِنْ بَنِي إِسْرَائِيلَ فَمَسَخَهُمْ دَوَابَّ يَدِبُّونَ فِي الأَرْضِ فَلاَ أَدْرِي لَعَلَّ هَذَا مِنْهَا فَلَسْتُ آكُلُهَا وَلاَ أَنْهَى عَنْهَا."],"takhrij":"صحيح: رواه مسلم في في الصيد والذبائح (1951: 51) عن محمد بن حاتم، حدثنا بهز، حدثنا أبو عقيل الدورقي، حدثنا أبو نضرة، عن أبي سعيد فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في جواز أكل الضب","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1951:51).","chapter_en":"What Has Been Reported Concerning the Permissibility of Eating Spiny-Tailed Lizard","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that a Bedouin came to the Messenger of Allah ﷺ and said: “I live in a lowland full of spiny-tailed lizards, and it is the main food of my family.” He said: But he did not answer him. We said: “Ask him again.” So he asked him again, but he did not answer him, three times. Then the Messenger of Allah ﷺ called him on the third time and said: “O Bedouin, Allah cursed — or became angry with — a tribe from the Children of Israel and transformed them into creatures crawling on the earth. I do not know; perhaps this is among them. So I do not eat them, and I do not forbid them.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":51,"lafz":true},{"key":"muslim","label":"مسلم في في الصيد والذبائح","number":1951,"n":5044}],"full":1,"dr":1},{"num":7353,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ يَقُولُ بَعَثَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ ثَلاَثُمِائَةِ رَاكِبٍ وَأَمِيرُنَا أَبُو عُبَيْدَةَ بْنُ الْجَرَّاحِ نَرْصُدُ عِيرًا لِقُرَيْشٍ فَأَقَمْنَا بِالسَّاحِلِ نِصْفَ شَهْرٍ فَأَصَابَنَا جُوعٌ شَدِيدٌ حَتَّى أَكَلْنَا الْخَبَطَ فَسُمِّيَ جَيْشَ الْخَبَطِ فَأَلْقَى لَنَا الْبَحْرُ دَابَّةً يُقَالُ لَهَا الْعَنْبَرُ فَأَكَلْنَا مِنْهَا نِصْفَ شَهْرٍ وَادَّهَنَّا مِنْ وَدَكِهَا حَتَّى ثَابَتْ أَجْسَامُنَا - قَالَ - فَأَخَذَ أَبُو عُبَيْدَةَ ضِلَعًا مِنْ أَضْلاَعِهِ فَنَصَبَهُ ثُمَّ نَظَرَ إِلَى أَطْوَلِ رَجُلٍ فِي الْجَيْشِ وَأَطْوَلِ جَمَلٍ فَحَمَلَهُ عَلَيْهِ فَمَرَّ تَحْتَهُ قَالَ وَجَلَسَ فِي حَجَاجِ عَيْنِهِ نَفَرٌ قَالَ وَأَخْرَجْنَا مِنْ وَقْبِ عَيْنِهِ كَذَا وَكَذَا قُلَّةَ وَدَكٍ - قَالَ - وَكَانَ مَعَنَا جِرَابٌ مِنْ تَمْرٍ فَكَانَ أَبُو عُبَيْدَةَ يُعْطِي كُلَّ رَجُلٍ مِنَّا قَبْضَةً قَبْضَةً ثُمَّ أَعْطَانَا تَمْرَةً تَمْرَةً فَلَمَّا فَنِيَ وَجَدْنَا فَقْدَهُ."],"takhrij":"متفق عليه: رواه البخاريّ في الذبائح والصيد (5494)، ومسلم في الصيد والذبائح (1935: 18) كلاهما من طريق سفيان (هو ابن عيينة)، عن عمرو (هو ابن دينار) أنه سمع جابرا يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أكل صيد البحر، وطعامه متاعاً لكم وللسيارة","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5494) and Muslim (1935:18).","chapter_en":"What Has Been Reported Concerning Eating Game from the Sea, and Its Food as Provision for You and for Travelers","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: The Messenger of Allah ﷺ sent us out, and we were three hundred riders. Our commander was Abu ʿUbaydah ibn al-Jarrah. We were watching for a caravan of Quraysh. We stayed on the coast for half a month, and severe hunger struck us, until we ate leaves shaken from trees. So the army was called the Army of Leaves. Then the sea cast out for us a sea creature called al-ʿAnbar. We ate from it for half a month and rubbed ourselves with its fat until our bodies recovered. He said: Abu ʿUbaydah took one of its ribs and set it up, then looked for the tallest man in the army and the tallest camel. He mounted him on it, and he passed beneath it. He said: A group of people sat in the hollow of its eye. He said: We extracted from the hollow of its eye many jars of fat. He said: We had with us a bag of dates, and Abu ʿUbaydah used to give each man of us a handful at a time, then he gave us one date at a time. When it ran out, we felt its loss."]},"buhuth":{"en":["His statement, “until our bodies recovered,” means they became well, as in al-Bukhari.","His statement, “in the socket of its eye,” means the hollow of its eye, as in the coming narration, meaning the inside and cavity of its eye."]},"intro":{"ar":["قال اللّٰه تعالى:","(أُحِلَّ لَكُمْ صَيْدُ ٱلْبَحْرِ وَطَعَامُهُ مَتَاعاً لَّكُمْ وَلِلسَّيَّارَةِ) [المائدة: ٩٦]","قال عمر: صيده ما اصطيد، وطعامه ما تُرمى به، ذكره البخاري في الذبائح والصيد. الفتح (٩/٦١٤)."],"en":["Allah the Exalted said:","“Lawful for you is the game of the sea and its food as provision for you and for travelers.” [al-Ma’idah: 96]","ʿUmar said: “Its game is what is caught, and its food is what the sea casts out.” Al-Bukhari mentioned it in the Book of Slaughtered Animals and Hunting. Al-Fath (9/614)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5494,"lafz":true},{"key":"muslim","label":"مسلم","number":18},{"key":"muslim","label":"مسلم في الصيد والذبائح","number":1935,"n":4999}],"full":1,"dr":1},{"num":7354,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ بَعَثَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  وَأَمَّرَ عَلَيْنَا أَبَا عُبَيْدَةَ نَتَلَقَّى عِيرًا لِقُرَيْشٍ وَزَوَّدَنَا جِرَابًا مِنْ تَمْرٍ لَمْ يَجِدْ لَنَا غَيْرَهُ فَكَانَ أَبُو عُبَيْدَةَ يُعْطِينَا تَمْرَةً تَمْرَةً - قَالَ - فَقُلْتُ كَيْفَ كُنْتُمْ تَصْنَعُونَ بِهَا قَالَ نَمَصُّهَا كَمَا يَمَصُّ الصَّبِيُّ ثُمَّ نَشْرَبُ عَلَيْهَا مِنَ الْمَاءِ فَتَكْفِينَا يَوْمَنَا إِلَى اللَّيْلِ وَكُنَّا نَضْرِبُ بِعِصِيِّنَا الْخَبَطَ ثُمَّ نَبُلُّهُ بِالْمَاءِ فَنَأْكُلُهُ قَالَ وَانْطَلَقْنَا عَلَى سَاحِلِ الْبَحْرِ فَرُفِعَ لَنَا عَلَى سَاحِلِ الْبَحْرِ كَهَيْئَةِ الْكَثِيبِ الضَّخْمِ فَأَتَيْنَاهُ فَإِذَا هِيَ دَابَّةٌ تُدْعَى الْعَنْبَرَ قَالَ قَالَ أَبُو عُبَيْدَةَ مَيْتَةٌ ثُمَّ قَالَ لاَ بَلْ نَحْنُ رُسُلُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  وَفِي سَبِيلِ اللَّهِ وَقَدِ اضْطُرِرْتُمْ فَكُلُوا قَالَ فَأَقَمْنَا عَلَيْهِ شَهْرًا وَنَحْنُ ثَلاَثُ مِائَةٍ حَتَّى سَمِنَّا قَالَ وَلَقَدْ رَأَيْتُنَا نَغْتَرِفُ مِنْ وَقْبِ عَيْنِهِ بِالْقِلاَلِ الدُّهْنَ وَنَقْتَطِعُ مِنْهُ الْفِدَرَ كَالثَّوْرِ - أَوْ كَقَدْرِ الثَّوْرِ - فَلَقَدْ أَخَذَ مِنَّا أَبُو عُبَيْدَةَ ثَلاَثَةَ عَشَرَ رَجُلاً فَأَقْعَدَهُمْ فِي وَقْبِ عَيْنِهِ وَأَخَذَ ضِلَعًا مِنْ أَضْلاَعِهِ فَأَقَامَهَا ثُمَّ رَحَلَ أَعْظَمَ بَعِيرٍ مَعَنَا فَمَرَّ مِنْ تَحْتِهَا وَتَزَوَّدْنَا مِنْ لَحْمِهِ وَشَائِقَ فَلَمَّا قَدِمْنَا الْمَدِينَةَ أَتَيْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَذَكَرْنَا ذَلِكَ لَهُ فَقَالَ هُوَ رِزْقٌ أَخْرَجَهُ اللَّهُ لَكُمْ فَهَلْ مَعَكُمْ مِنْ لَحْمِهِ شَىْءٌ فَتُطْعِمُونَا. قَالَ فَأَرْسَلْنَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  مِنْهُ فَأَكَلَهُ."],"takhrij":"صحيح: رواه مسلم في الصيد والذبائح (1935: 17) من طريق أبي خيثمة زهير بن معاوية، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل صيد البحر، وطعامه متاعاً لكم وللسيارة","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1935:17).","chapter_en":"What Has Been Reported Concerning Eating Game from the Sea, and Its Food as Provision for You and for Travelers","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ sent us out and appointed Abu ʿUbaydah over us, to intercept a caravan of Quraysh. He provided us with a bag of dates, as he found nothing else for us. Abu ʿUbaydah would give us one date at a time. He said: I said: “What would you do with it?” He said: We would suck it as a child sucks, then drink water after it, and it would suffice us for our day until night. We would strike leaves from trees with our sticks, then soak them in water and eat them. He said: We went along the seashore, and something like a huge sand dune appeared to us on the coast. We came to it, and it was a sea creature called al-ʿAnbar. Abu ʿUbaydah said: “It is carrion.” Then he said: “No, rather we are the messengers of the Messenger of Allah ﷺ, and we are in the way of Allah, and you are in necessity, so eat.” He said: We stayed with it for a month, and we were three hundred, until we became fat. He said: I saw us drawing fat from the hollow of its eye with jars, and cutting pieces from it like an ox or the size of an ox. Abu ʿUbaydah took thirteen men from us and seated them in the hollow of its eye. He took one of its ribs and set it up, then saddled the largest camel with us, and it passed beneath it. We took dried strips of its meat as provisions. When we reached Madinah, we came to the Messenger of Allah ﷺ and mentioned that to him. He said: “It is provision that Allah brought out for you. Do you have any of its meat with you so that you may feed us?” He said: So we sent some of it to the Messenger of Allah ﷺ, and he ate it."]},"buhuth":{"en":["His statement, “leaves shaken from trees,” refers to what falls from tree leaves by striking and shaking.","His statement, “pieces,” means cuts of meat. His statement, “dried strips,” was said to mean dried meat, and it was also said to mean meat that is boiled briefly but not fully cooked so it does not spoil, and can be stored and carried during journeys."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم في الصيد والذبائح","number":1935,"lafz":true}],"full":1,"dr":1,"rep":[8954]},{"num":7355,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، أَنَّهُ قَالَ: أُحِلَّتْ لَنَا مَيْتَتَانِ وَدَمَانِ: الْجَرَادُ وَالْحِيتَانِ وَالْكَبِدُ وَالطِّحَالُ."],"takhrij":"صحيح: رواه البيهقي (1/254) من حديث ابن وهب، ثنا سليمان بن بلال، عن زيد بن أسلم، عن عبد الله بن عمر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل صيد البحر، وطعامه متاعاً لكم وللسيارة","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bayhaqi (1/254).","chapter_en":"What Has Been Reported Concerning Eating Game from the Sea, and Its Food as Provision for You and for Travelers","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Ibn ʿUmar said: Two dead animals and two bloods have been made lawful for us: locusts and fish, and the liver and spleen."]}},"tuhfa":{},"refs":[{"key":"kubrabayhaqi","label":"البيهقي","number":1,"lafz":true},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":1196,"n":1209}],"full":1,"dr":1,"rep":[11941]},{"num":7356,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عمرو بْنِ الْعَاصِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  مَا مِنْ إِنْسَانٍ قَتَلَ عُصْفُورًا فَمَا فَوْقَهَا بِغَيْرِ حَقِّهَا إِلاَّ سَأَلَهُ اللَّهُ عَزَّ وَجَلَّ عَنْهَا قِيلَ: يَا رَسُولَ اللَّهِ وَمَا حَقُّهَا؟ قَالَ: يَذْبَحُهَا فَيَأْكُلُهَا وَ لاَ يَقْطَعُ رَأْسَهَا يَرْمِي بِهَا."],"takhrij":"حسن: رواه النسائي (4349، 4445، والحاكم (4/233) من طريق ابن عيينة، عن عمرو بن دينار، عن صهيب مولى ابن عامر، عن عبدالله بن عمرو فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في أكل العصافير","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4349, 4445) and al-Hakim (7574).","chapter_en":"What Has Been Reported Concerning Eating Small Birds","part_en":"Book of Foods","group_ar":"جموع ما جاء في الحلال من الأطعمة","group_en":"Collection of What Has Been Reported Concerning Lawful Foods","part_no":40,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs narrated that the Messenger of Allah ﷺ said: “No person kills a small bird or anything larger than it without its right except that Allah, the Mighty and Majestic, will ask him about it.” It was said: “O Messenger of Allah, what is its right?” He said: “That he slaughter it and eat it, and not cut off its head and throw it away.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4349,"lafz":true,"n":4349},{"key":"hakim","label":"المستدرك على الصحيحين","number":7574,"n":7578}],"full":1,"dr":1},{"num":7357,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ مَا شَبِعَ آلُ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ خُبْزِ بُرٍّ مَأْدُومٍ ثَلاَثَةَ أَيَّامٍ حَتَّى لَحِقَ بِاللَّهِ."],"takhrij":"متفق عليه: رواه البخاريّ في الأيمان والنذور (6687)، ومسلم في الزهد والرقائق (2970: 23) كلاهما من طريق سفيان (هو الثوري)، عن عبد الرحمن بن عابس، عن أبيه، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في خبز البر والحنطة","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6687) and Muslim (2970:23).","chapter_en":"What Has Been Reported Concerning Wheat Bread","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["The Mother of the Believers ʿA’ishah said: The family of Muhammad ﷺ never ate their fill of wheat bread with something to accompany it for three days until he met Allah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6687,"lafz":true},{"key":"muslim","label":"مسلم","number":23},{"key":"muslim","label":"مسلم في الزهد والرقائق","number":2970}],"full":1},{"num":7358,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: والذي نفسي بيده ما أشبع رسول الله صلى الله عليه وسلم أهله ثلاثة أيام تِباعاً من خبز حنطة حتى فارق الدنيا."],"takhrij":"متفق عليه: رواه مسلم في الزهد والرقائق (2976: 32) من طريق مروان الفزاري، عن يزيد بن كيسان، عن أبي حازم، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في خبز البر والحنطة","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (2976:32) and al-Bukhari (5374).","chapter_en":"What Has Been Reported Concerning Wheat Bread","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: By the One in whose Hand is my soul, the Messenger of Allah ﷺ never fed his family their fill of wheat bread for three consecutive days until he departed this world."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":32,"lafz":true},{"key":"bukhari","label":"البخاري","number":5374},{"key":"muslim","label":"مسلم في الزهد والرقائق","number":2976}],"full":1,"dr":1},{"num":7359,"demo":false,"sanad":"","matn":["عَنْ أَبِي حَازِمٍ، قَالَ سَأَلْتُ سَهْلَ بْنَ سَعْدٍ فَقُلْتُ هَلْ أَكَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ النَّقِيَّ فَقَالَ سَهْلٌ مَا رَأَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ النَّقِيَّ مِنْ حِينَ ابْتَعَثَهُ اللَّهُ حَتَّى قَبَضَهُ اللَّهُ. قَالَ فَقُلْتُ هَلْ كَانَتْ لَكُمْ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنَاخِلُ قَالَ مَا رَأَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُنْخُلاً مِنْ حِينَ ابْتَعَثَهُ اللَّهُ حَتَّى قَبَضَهُ. قَالَ قُلْتُ كَيْفَ كُنْتُمْ تَأْكُلُونَ الشَّعِيرَ غَيْرَ مَنْخُولٍ قَالَ كُنَّا نَطْحَنُهُ وَنَنْفُخُهُ، فَيَطِيرُ مَا طَارَ وَمَا بَقِيَ ثَرَّيْنَاهُ فَأَكَلْنَاهُ."],"takhrij":"صحيح: رواه البخاري في الأطعمة (5413) عن قتيبة بن سعيد، حدثنا يعقوب، عن أبي حازم قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في خبز الشعير","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5413).","chapter_en":"What Has Been Reported Concerning Barley Bread","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Abu Hazim said: I asked Sahl ibn Saʿd: “Did the Messenger of Allah ﷺ eat fine white bread?” Sahl said: “The Messenger of Allah ﷺ never saw fine white bread from the time Allah, the Mighty and Majestic, sent him until Allah took him.” He said: I said: “Did you have sieves during the time of the Messenger of Allah ﷺ?” He said: “The Messenger of Allah ﷺ never saw a sieve from the time Allah sent him until He took him.” He said: I said: “How did you eat barley without sifting it?” He said: “We would grind it and blow into it; whatever flew away flew away, and whatever remained we moistened and ate.”"]},"buhuth":{"en":["His statement, “fine white bread,” means bread made from clean white flour. His statement, “sieves,” is the plural of sieve, which is a tool used to sift and purify wheat, barley, and the like. What remains after sifting and purification is bran."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5413,"lafz":true}],"full":1,"dr":1,"rep":[15179]},{"num":7360,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ مَرَّ بِقَوْمٍ بَيْنَ أَيْدِيهِمْ شَاةٌ مَصْلِيَّةٌ، فَدَعَوْهُ فَأَبَى أَنْ يَأْكُلَ قَالَ خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الدُّنْيَا وَلَمْ يَشْبَعْ مِنَ الْخُبْزِ الشَّعِيرِ."],"takhrij":"صحيح: رواه البخاري في الأطعمة (5414) عن إسحاق بن إبراهيم، أخبرنا روح بن عبادة، حدثنا ابن أبي ذئب، عن سعيد المقبري، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في خبز الشعير","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5414).","chapter_en":"What Has Been Reported Concerning Barley Bread","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah passed by some people who had a roasted sheep before them, and they invited him, but he refused to eat. He said: “The Messenger of Allah ﷺ left this world without ever eating his fill of barley bread.”"]},"buhuth":{"en":["His statement, “a roasted sheep,” means a grilled sheep. The word refers to roasting."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5414,"lafz":true}],"full":1,"dr":1},{"num":7361,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَبِيتُ اللَّيَالِيَ الْمُتَتَابِعَةَ طَاوِيًا وَأَهْلُهُ لاَ يَجِدُونَ عَشَاءً وَكَانَ أَكْثَرُ خُبْزِهِمْ خُبْزَ الشَّعِيرِ."],"takhrij":"حسن: رواه الترمذي (2360)، وابن ماجه (3347) وأحمد (2303) كلهم من طريق ثابت بن يزيد، ثنا هلال بن خباب، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في خبز الشعير","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (2360), Ibn Majah (3347), and Ahmad (2303). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"What Has Been Reported Concerning Barley Bread","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ would spend consecutive nights hungry, and his family would find no evening meal. Most of their bread was barley bread."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":2360,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":3347},{"key":"ahmad","label":"مسند الإمام أحمد","number":2303,"n":2303}],"full":1,"dr":1,"rep":[9538]},{"num":7362,"demo":false,"sanad":"","matn":["عَنْ قَتَادَةَ، قَالَ كُنَّا نَأْتِي أَنَسَ بْنَ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ وَخَبَّازُهُ قَائِمٌ قَالَ كُلُوا فَمَا أَعْلَمُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى رَغِيفًا مُرَقَّقًا حَتَّى لَحِقَ بِاللَّهِ، وَلاَ رَأَى شَاةً سَمِيطًا بِعَيْنِهِ قَطُّ.","وفي لفظ:ما أكل النبيصلى الله عليه وسلم خبزا مرققا،ولا شاة مسموطةً حتى لقي الله."],"takhrij":"صحيح: رواه البخاري في الأطعمة (5421) عن هدبة بن خالد، حدثنا همام بن يحيى، عن قتادة به.","grade":"صحيح","chapter_ar":"باب ما جاء في خبز الشعير","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5421).","chapter_en":"What Has Been Reported Concerning Barley Bread","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Qatadah said: We used to come to Anas ibn Malik while his baker was standing. He would say: “Eat, for I do not know that the Prophet ﷺ ever saw thin, refined bread until he met Allah, nor did he ever see a scalded sheep with his own eyes.” In another wording: The Prophet ﷺ never ate thin, refined bread, nor a scalded sheep, until he met Allah."]},"buhuth":{"en":["His statement, “a scalded sheep,” refers to an animal whose hair has been removed with hot water and then roasted with its skin or cooked. This is usually done with a young, tender animal. Al-Fath (9/531)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5421,"lafz":true},{"key":"انما_یصنع_ذلک/الصغیر_السن_الطری_الفتح","label":"إنما يصنع ذلك في الصغير السنّ الطري. الفتح","number":9}],"full":1,"dr":1},{"num":7363,"demo":false,"sanad":"","matn":["عَنْ أُمِّ أَيْمَنَ، أَنَّهَا غَرْبَلَتْ دَقِيقًا فَصَنَعَتْهُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَغِيفًا فَقَالَ مَا هَذَا. قَالَتْ طَعَامٌ نَصْنَعُهُ بِأَرْضِنَا فَأَحْبَبْتُ أَنْ أَصْنَعَ مِنْهُ لَكَ رَغِيفًا. فَقَالَ رُدِّيهِ فِيهِ ثُمَّ اعْجِنِيهِ."],"takhrij":"حسن: رواه ابن ماجه (3336) عن يعقوب بن حميد بن كاسب، حدثنا ابن وهب، أخبرني عمرو بن الحارث، أخبرني بكر بن سوادة، أن حنش بن عبد الله حدّثه، عن أم أيمن قالت: فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء في خبز الشعير","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (3336).","chapter_en":"What Has Been Reported Concerning Barley Bread","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Umm Ayman sifted flour and made a loaf for the Prophet ﷺ. He said: “What is this?” She said: “It is food we make in our land, and I wanted to make a loaf from it for you.” He said: “Put it back into it, then knead it.”"]},"buhuth":{"en":["His statement, “Put it back into it,” means that he ordered her to return the flour to its bran, then knead it and make a loaf with it.","His statement, “a refined loaf,” means one that has been sifted repeatedly. From the same root comes the term “disciples,” meaning those who were purified and cleansed from every defect."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":3336,"lafz":true}],"full":1,"dr":1},{"num":7364,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى الأَشْعَرِيِّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ كَمَلَ مِنَ الرِّجَالِ كَثِيرٌ، وَلَمْ يَكْمُلْ مِنَ النِّسَاءِ إِلاَّ مَرْيَمُ بِنْتُ عِمْرَانَ وَآسِيَةُ امْرَأَةُ فِرْعَوْنَ، وَفَضْلُ عَائِشَةَ عَلَى النِّسَاءِ كَفَضْلِ الثَّرِيدِ عَلَى سَائِرِ الطَّعَامِ."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5418)، ومسلم في فضائل الصحابة (2431) كلاهما من طريق شعبة، عن عمرو بن مرة الجملي، عن مرة الهمداني، عن أبي موسى الأشعري فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الثريد","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5418) and Muslim (2431).","chapter_en":"What Has Been Reported Concerning Tharid","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Abu Musa al-Ashʿari narrated from the Prophet ﷺ that he said: “Many men reached perfection, and none among women reached perfection except Maryam daughter of ʿImran and Asiyah, the wife of Pharaoh. The superiority of ʿA’ishah over women is like the superiority of tharid over all other food.”"]},"buhuth":{"en":["“Tharid” means bread that is crumbled into meat broth, and it may also include meat."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5418,"lafz":true},{"key":"muslim","label":"مسلم","number":2431}],"full":1,"dr":1},{"num":7365,"demo":false,"sanad":"","matn":["عَنْ سُوَيْدِ بْنِ النُّعْمَانِ، أَنَّهُ أَخْبَرَهُ أَنَّهُمْ، كَانُوا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالصَّهْبَاءِ ـ وَهْىَ عَلَى رَوْحَةٍ مِنْ خَيْبَرَ ـ فَحَضَرَتِ الصَّلاَةُ، فَدَعَا بِطَعَامٍ فَلَمْ يَجِدْهُ إِلاَّ سَوِيقًا، فَلاَكَ مِنْهُ فَلُكْنَا مَعَهُ، ثُمَّ دَعَا بِمَاءٍ فَمَضْمَضَ، ثُمَّ صَلَّى وَصَلَّيْنَا، وَلَمْ يَتَوَضَّأْ."],"takhrij":"صحيح: رواه البخاريّ في الأطعمة (5390) عن سليمان بن حرب، حدثنا حماد، عن يحيى، عن بُشير بن يسار، عن سويد بن النعمان فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل السويق","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5390).","chapter_en":"What Has Been Reported Concerning Eating Sawiq","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Suwayd ibn al-Nuʿman informed him that they were with the Prophet ﷺ at al-Sahba’, which is a day’s journey from Khaybar. The prayer time came, so he called for food but found nothing except sawiq. He chewed some of it, and we chewed with him. Then he called for water and rinsed his mouth. Then he prayed, and we prayed, and he did not perform ablution."]},"buhuth":{"en":["His statement, “except sawiq”: sawiq is food made from crushed wheat and barley. A Bedouin described it by saying: “The provision of the traveler, the food of the one in haste, and the nourishment of the sick.” Al-Fath (1/312). I say: Perhaps it is also made as a drink, as the following hadiths indicate."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5390,"lafz":true},{"key":"بلغہ_المریض_الفتح","label":"بلغة المريض. الفتح","number":1}],"full":1,"dr":1},{"num":7366,"demo":false,"sanad":"","matn":["عَنْ أَبِي بُرْدَةَ، قَالَ قَدِمْتُ الْمَدِينَةَ فَلَقِيَنِي عَبْدُ اللَّهِ بْنُ سَلاَمٍ فَقَالَ لِي انْطَلِقْ إِلَى الْمَنْزِلِ فَأَسْقِيَكَ فِي قَدَحٍ شَرِبَ فِيهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَتُصَلِّي فِي مَسْجِدٍ صَلَّى فِيهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَانْطَلَقْتُ مَعَهُ، فَسَقَانِي سَوِيقًا، وَأَطْعَمَنِي تَمْرًا، وَصَلَّيْتُ فِي مَسْجِدِهِ."],"takhrij":"صحيح: رواه البخاري في الاعتصام (7342) عن أبي كريب، حدثنا أبو أسامة، حدثنا بُريد، عن أبي بردة قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل السويق","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7342).","chapter_en":"What Has Been Reported Concerning Eating Sawiq","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Abu Burdah said: I came to Madinah, and ʿAbdullah ibn Salam met me. He said to me: “Come to the house, and I will give you drink in a cup from which the Messenger of Allah ﷺ drank, and you will pray in a mosque in which the Prophet ﷺ prayed.” So I went with him, and he gave me sawiq to drink, fed me dates, and I prayed in his mosque."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7342,"lafz":true}],"full":1,"dr":1,"rep":[9400]},{"num":7367,"demo":false,"sanad":"","matn":["عن الشَّعْبِيِّ قَالَ دَخَلْنَا عَلَى فَاطِمَةَ بِنْتِ قَيْسٍ فَأَتْحَفَتْنَا بِرُطَبِ ابْنِ طَابٍ وَسَقَتْنَا سَوِيقَ سُلْتٍ فَسَأَلْتُهَا عَنِ الْمُطَلَّقَةِ، ثَلاَثًا أَيْنَ تَعْتَدُّ قَالَتْ طَلَّقَنِي بَعْلِي ثَلاَثًا فَأَذِنَ لِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ أَعْتَدَّ فِي أَهْلِي."],"takhrij":"صحيح: رواه مسلم في الطلاق (1480: 43) عن يحيى بن حبيب، حدثنا خالد بن الحارث الهُجيمي، حدثنا قرة، حدثنا سيّار أبو الحكم، حدثنا الشعبي قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل السويق","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1480:43).","chapter_en":"What Has Been Reported Concerning Eating Sawiq","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Al-Shaʿbi said: We entered upon Fatimah bint Qays, and she honored us with fresh dates of Ibn Tab and gave us sawiq made from barley to drink. I asked her about a woman divorced three times, where should she observe her waiting period? She said: “My husband divorced me three times, and the Prophet ﷺ permitted me to observe my waiting period with my family.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":43,"lafz":true},{"key":"muslim","label":"مسلم في الطلاق","number":1480,"n":3707}],"full":1},{"num":7368,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ يَقُولُ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لأَبِي طَلْحَةَ الْتَمِسْ غُلاَمًا مِنْ غِلْمَانِكُمْ يَخْدُمُنِي. فَخَرَجَ بِي أَبُو طَلْحَةَ، يُرْدِفُنِي وَرَاءَهُ، فَكُنْتُ أَخْدُمُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُلَّمَا نَزَلَ، فَكُنْتُ أَسْمَعُهُ يُكْثِرُ أَنْ يَقُولَ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ وَضَلَعِ الدَّيْنِ، وَغَلَبَةِ الرِّجَالِ. فَلَمْ أَزَلْ أَخْدُمُهُ حَتَّى أَقْبَلْنَا مِنْ خَيْبَرَ، وَأَقْبَلَ بِصَفِيَّةَ بِنْتِ حُيَىٍّ قَدْ حَازَهَا، فَكُنْتُ أَرَاهُ يُحَوِّي وَرَاءَهُ بِعَبَاءَةٍ أَوْ بِكِسَاءٍ، ثُمَّ يُرْدِفُهَا وَرَاءَهُ، حَتَّى إِذَا كُنَّا بِالصَّهْبَاءِ صَنَعَ حَيْسًا فِي نِطَعٍ، ثُمَّ أَرْسَلَنِي فَدَعَوْتُ رِجَالاً فَأَكَلُوا، وَكَانَ ذَلِكَ بِنَاءَهُ بِهَا، ثُمَّ أَقْبَلَ حَتَّى إِذَا بَدَا لَهُ أُحُدٌ قَالَ هَذَا جَبَلٌ يُحِبُّنَا وَنُحِبُّهُ. فَلَمَّا أَشْرَفَ عَلَى الْمَدِينَةِ قَالَ اللَّهُمَّ إِنِّي أُحَرِّمُ مَا بَيْنَ جَبَلَيْهَا مِثْلَ مَا حَرَّمَ بِهِ إِبْرَاهِيمُ مَكَّةَ، اللَّهُمَّ بَارِكْ لَهُمْ فِي مُدِّهِمْ وَصَاعِهِمْ."],"takhrij":"متفق عليه: رواه البخاريّ في الأطعمة (5425) عن قتيبة، حدثنا إسماعيل بن جعفر، عن عمرو بن أبي عمرو مولى المطلب بن عبد الله بن حنطب، أنه سمع أنس بن مالك يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أكل الحيْس","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5425) and Muslim (1365).","chapter_en":"What Has Been Reported Concerning Eating Hays","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ said to Abu Talhah: “Look for a boy from among your boys to serve me.” So Abu Talhah took me out, seating me behind him on his mount. I used to serve the Messenger of Allah ﷺ whenever he stopped. I often heard him say: “O Allah, I seek refuge in You from worry, grief, incapacity, laziness, miserliness, cowardice, the burden of debt, and being overpowered by men.” I continued serving him until we returned from Khaybar, and he brought Safiyyah bint Huyayy, whom he had taken. I used to see him placing a cloak or covering behind him for her, then seating her behind him. When we reached al-Sahba’, he made hays on a leather mat, then sent me, and I invited some men, and they ate. That was the wedding meal for his marriage to her. Then he continued until Uhud appeared before him, and he said: “This is a mountain that loves us, and we love it.” When he looked over Madinah, he said: “O Allah, I declare sacred what lies between its two mountains, just as Ibrahim declared Makkah sacred. O Allah, bless them in their mudd and their saʿ.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5425,"lafz":true},{"key":"muslim","label":"مسلم","number":1365}],"full":1,"dr":1,"rep":[8380,10560]},{"num":7369,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أُمِّ الْمُؤْمِنِينَ، قَالَتْ دَخَلَ عَلَىَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ فَقَالَ هَلْ عِنْدَكُمْ شَىْءٌ. فَقُلْنَا لاَ. قَالَ فَإِنِّي إِذًا صَائِمٌ. ثُمَّ أَتَانَا يَوْمًا آخَرَ فَقُلْنَا يَا رَسُولَ اللَّهِ أُهْدِيَ لَنَا حَيْسٌ. فَقَالَ أَرِينِيهِ فَلَقَدْ أَصْبَحْتُ صَائِمًا. فَأَكَلَ."],"takhrij":"صحيح: رواه مسلم في الصيام (1154: 170) عن أبي بكر بن أبي شيبة، ثنا وكيع، عن طلحة بن يحيى، عن عمته عائشة بنت طلحة، عن عائشة أم المؤمنين قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل الحيْس","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1154:170).","chapter_en":"What Has Been Reported Concerning Eating Hays","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["The Mother of the Believers ʿA’ishah said: The Prophet ﷺ entered upon me one day and said: “Do you have anything?” We said: “No.” He said: “Then I am fasting.” Then he came to us another day, and we said: “O Messenger of Allah, some hays has been gifted to us.” He said: “Show it to me, for I began the morning fasting.” Then he ate."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":170,"lafz":true},{"key":"muslim","label":"مسلم في الصيام","number":1154,"n":2715}],"full":1,"rep":[4414]},{"num":7370,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ بُسر قَالَ: نَزَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى أَبِي، قَالَ: فَقَرَّبْنَا إِلَيْهِ طَعَامًا وَ وطبةً فَأَكَلَ مِنْهَا. الحديث."],"takhrij":"صحيح: رواه مسلم في الأشربة (2042) عن محمد بن المثنى العنزي، حدثنا محمد بن جعفر، حدثنا شعبة، عن يزيد بن خُمير، عن عبد الله بن بُسر قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل الحيْس","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2042).","chapter_en":"What Has Been Reported Concerning Eating Hays","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullah ibn Busr said: The Messenger of Allah ﷺ came as a guest to my father. He said: We brought near to him food and watbah, and he ate from it. The hadith."]},"buhuth":{"en":["His statement, “watbah”: Al-Nawawi said: This is how most narrators transmitted it, with the letter “waw,” a still “ta,” and then the letter “ba.” Watbah is hays, combining high-quality dates, crushed dried yogurt, and clarified butter.","Qadi ʿIyad transmitted from the narration of some in Muslim: “wati’ah,” with a “waw,” a kasrah on the “ta,” and then a hamzah, and he claimed that it is the correct form, as others also claimed. Among the linguists, wati’ah with a hamzah is a food made from dates, like hays. This is what they mentioned, and there is no contradiction between all of this. What is established by authentic narrations is accepted, and it is valid in the language. Allah knows best. Sharh Muslim (12/225)."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2042,"lafz":true}],"full":1,"dr":1},{"num":7371,"demo":false,"sanad":"","matn":["عن مَحْمُودِ بْنِ الرَّبِيعِ الأَنْصَارِيِّ أَنَّ عِتْبَانَ بْنَ مَالِكٍ ـ وَكَانَ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِمَّنْ شَهِدَ بَدْرًا مِنَ الأَنْصَارِ ـ أَنَّهُ أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي أَنْكَرْتُ بَصَرِي وَأَنَا أُصَلِّي لِقَوْمِي، فَإِذَا كَانَتِ الأَمْطَارُ سَالَ الْوَادِي الَّذِي بَيْنِي وَبَيْنَهُمْ، لَمْ أَسْتَطِعْ أَنْ آتِيَ مَسْجِدَهُمْ فَأُصَلِّيَ لَهُمْ، فَوَدِدْتُ يَا رَسُولَ اللَّهِ أَنَّكَ تَأْتِي فَتُصَلِّي فِي بَيْتِي، فَأَتَّخِذُهُ مُصَلًّى. فَقَالَ سَأَفْعَلُ إِنْ شَاءَ اللَّهُ. قَالَ عِتْبَانُ فَغَدَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبُو بَكْرٍ حِينَ ارْتَفَعَ النَّهَارُ، فَاسْتَأْذَنَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَذِنْتُ لَهُ فَلَمْ يَجْلِسْ حَتَّى دَخَلَ الْبَيْتَ، ثُمَّ قَالَ لِي أَيْنَ تُحِبُّ أَنْ أُصَلِّيَ مِنْ بَيْتِكَ. فَأَشَرْتُ إِلَى نَاحِيَةٍ مِنَ الْبَيْتِ فَقَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَكَبَّرَ، فَصَفَفْنَا، فَصَلَّى رَكْعَتَيْنِ، ثُمَّ سَلَّمَ وَحَبَسْنَاهُ عَلَى خَزِيرٍ صَنَعْنَاهُ، فَثَابَ فِي الْبَيْتِ رِجَالٌ مِنْ أَهْلِ الدَّارِ ذَوُو عَدَدٍ فَاجْتَمَعُوا، فَقَالَ قَائِلٌ مِنْهُمْ أَيْنَ مَالِكُ بْنُ الدُّخْشُنِ فَقَالَ بَعْضُهُمْ ذَلِكَ مُنَافِقٌ لاَ يُحِبُّ اللَّهَ وَرَسُولَهُ. قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ تَقُلْ، أَلاَ تَرَاهُ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ. يُرِيدُ بِذَلِكَ وَجْهَ اللَّهِ. قَالَ اللَّهُ وَرَسُولُهُ أَعْلَمُ. قَالَ قُلْنَا فَإِنَّا نَرَى وَجْهَهُ وَنَصِيحَتَهُ إِلَى الْمُنَافِقِينَ. فَقَالَ فَإِنَّ اللَّهَ حَرَّمَ عَلَى النَّارِ مَنْ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ. يَبْتَغِي بِذَلِكَ وَجْهَ اللَّهِ. قَالَ ابْنُ شِهَابٍ ثُمَّ سَأَلْتُ الْحُصَيْنَ بْنَ مُحَمَّدٍ الأَنْصَارِيَّ أَحَدَ بَنِي سَالِمٍ وَكَانَ مِنْ سَرَاتِهِمْ عَنْ حَدِيثِ مَحْمُودٍ فَصَدَّقَهُ.","وفي لفظ: على جشيشة صنعناها له."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5401)، ومسلم في المساجد (33: 263) كلاهما من طريق ابن شهاب قال: أخبرني محمود بن الربيع الأنصاري فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الخزيرة والجشيشة والعصيدة","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5401) and Muslim (263:33).","chapter_en":"What Has Been Reported Concerning Khazirah, Jashishah, and ʿAsidah","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Mahmud ibn al-Rabiʿ al-Ansari narrated that ʿItban ibn Malik — who was one of the Ansar Companions of the Prophet ﷺ who witnessed Badr — came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, my eyesight has become weak, and I lead my people in prayer. When it rains, the valley between me and them flows, and I am unable to come to their mosque and lead them in prayer. I would love, O Messenger of Allah, for you to come and pray in my house so that I may take it as a prayer place.” He said: “I will do so, if Allah wills.” ʿItban said: The Messenger of Allah ﷺ came in the morning, along with Abu Bakr, after the day had risen. The Prophet ﷺ asked permission, and I gave him permission. He did not sit until he entered the house. Then he said to me: “Where would you like me to pray in your house?” I pointed to a corner of the house. The Prophet ﷺ stood and said the opening declaration of prayer, and we lined up. He prayed two units, then gave salutation. We kept him for khazir that we had made. A number of men from the household came back to the house and gathered. One of them said: “Where is Malik ibn al-Dukhshun?” Some of them said: “That man is a hypocrite; he does not love Allah and His Messenger.” The Prophet ﷺ said: “Do not say that. Do you not see that he said, ‘There is no god but Allah,’ seeking by that the Face of Allah?” He said: “Allah and His Messenger know best.” He said: We said: “We see his attention and sincerity toward the hypocrites.” He said: “Indeed, Allah has forbidden the Fire for whoever says, ‘There is no god but Allah,’ seeking by that the Face of Allah.” Ibn Shihab said: Then I asked al-Husayn ibn Muhammad al-Ansari — one of Banu Salim, and one of their nobles — about the hadith of Mahmud, and he confirmed it. In another wording: “for jashishah that we had made for him.”"]},"buhuth":{"en":["His statement, “khazir that we had made,” is also said as “khazirah.”","Ibn Qutaybah said: Khazirah is meat cut into small pieces, then a large amount of water is poured over it. When it is cooked, flour is sprinkled over it. If it contains no meat, then it is porridge. In Sahih al-Bukhari, al-Nadr said: Khazirah is made from bran, while harirah is made from milk. Abu al-Haytham said likewise: If it is made from bran, it is khazirah; if it is made from flour, it is harirah. What is meant is bran containing coarse flour.","His statement in the other narration, “jashishah”: Shamir said: It is when wheat is ground coarsely, then meat or dates are put into it and cooked with it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5401,"lafz":true},{"key":"muslim","label":"مسلم","number":33,"n":1496}],"full":1,"dr":1},{"num":7372,"demo":false,"sanad":"","matn":["عَنْ لقيط بن صبرة قَالَ: اتَّبَعْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَلَمْ نَجِدْهُ، فَأَرْسَلَتْ إِلَيْنَا عَائِشَةُ بِعَصِيدَةٍ وَتَمْرٍ، وَجَاءَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَقَلَّعُ، فَقَالَ: هَلْ طَعِمْتُمْ مِنْ شَيْءٍ؟ قُلْنَا: نَعَمْ يَا رَسُولَ اللَّهِ.","وفي رواية: \"فأمرت لنا بخزيرة فصنعت لنا\"."],"takhrij":"صحيح: رواه أبوداود (143)، والنسائي في الكبرى (6665)، وأحمد (17846)، والحاكم (1/148) من طرق عن ابن جريج، ثنا إسماعيل بن كثير، عن عاصم بن لقيط بن صبِرة، عن أبيه، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الخزيرة والجشيشة والعصيدة","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (143), al-Nasa’i in al-Kubra (6665), Ahmad (17846), and al-Hakim (1/148).","chapter_en":"What Has Been Reported Concerning Khazirah, Jashishah, and ʿAsidah","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Laqit ibn Sabirah said: We followed the Messenger of Allah ﷺ, but we did not find him. ʿA’ishah sent us porridge and dates. Then the Prophet ﷺ came walking briskly with a forward-leaning gait. He said: “Have you eaten anything?” We said: “Yes, O Messenger of Allah.” In another narration: “She ordered khazirah to be made for us, and it was prepared for us.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":143,"lafz":true},{"key":"kubranasai","label":"النسائي في الكبرى","number":6665},{"key":"hakim","label":"الحاكم","number":1},{"key":"ahmad","label":"مسند الإمام أحمد","number":17846,"n":17846}],"full":1,"dr":1},{"num":7373,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهَا كَانَتْ إِذَا مَاتَ الْمَيِّتُ مِنْ أَهْلِهَا فَاجْتَمَعَ لِذَلِكَ النِّسَاءُ، ثُمَّ تَفَرَّقْنَ، إِلاَّ أَهْلَهَا وَخَاصَّتَهَا، أَمَرَتْ بِبُرْمَةٍ مِنْ تَلْبِينَةٍ فَطُبِخَتْ، ثُمَّ صُنِعَ ثَرِيدٌ فَصُبَّتِ التَّلْبِينَةُ عَلَيْهَا ثُمَّ قَالَتْ كُلْنَ مِنْهَا فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ التَّلْبِينَةُ مَجَمَّةٌ لِفُؤَادِ الْمَرِيضِ، تَذْهَبُ بِبَعْضِ الْحُزْنِ."],"takhrij":"متفق عليه: رواه البخاريّ في الأطعمة (5417)، ومسلم في السلام (2216) كلاهما من طريق الليث بن سعد، حدثني عقيل بن خالد، عن ابن شهاب، عن عروة، عن عائشة، قالت: فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في التلبينة","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5417) and Muslim (2216).","chapter_en":"What Has Been Reported Concerning Talbinah","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["ʿA’ishah, the wife of the Prophet ﷺ, narrated that when someone from her family died and women gathered for that, then they dispersed except for her family and close ones, she would order a pot of talbinah to be cooked. Then tharid would be made, and the talbinah would be poured over it. Then she would say: “Eat from it, for I heard the Messenger of Allah ﷺ say: ‘Talbinah brings comfort to the heart of the sick and removes some grief.’”"]},"buhuth":{"en":["“Talbinah” is also called “talbin.” It is a soup made from flour or bran, and honey may sometimes be added to it. It was named because of its resemblance to milk."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5417,"lafz":true},{"key":"muslim","label":"مسلم","number":2216}],"full":1,"dr":1,"rep":[3545,11613]},{"num":7374,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ كُنَّا نُخْرِجُ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الْفِطْرِ صَاعًا مِنْ طَعَامٍ. وَقَالَ أَبُو سَعِيدٍ وَكَانَ طَعَامَنَا الشَّعِيرُ وَالزَّبِيبُ وَالأَقِطُ وَالتَّمْرُ."],"takhrij":"متفق عليه: رواه البخاري في الزكاة (1510) عن معاذ بن فضالة، ثنا أبو عمر، عن زيد، عن عياض بن عبد الله بن سعد، عن أبي سعيد الخدري فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الأقط","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1510) and Muslim (985).","chapter_en":"What Has Been Reported Concerning Dried Yogurt","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: During the time of the Messenger of Allah ﷺ, on the day of the breaking of the fast, we would give out one saʿ of food. Abu Saʿid said: Our food was barley, raisins, dried yogurt, and dates."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1510,"lafz":true},{"key":"muslim","label":"مسلم","number":985}],"full":1,"dr":1},{"num":7375,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:كَانَ رَسُولُ اللَّهِ يُحِبُّ الْحَلْوَاءَ وَالْعَسَلَ."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5431)، ومسلم في الطلاق (1474: 21) كلاهما من طريق أبي أسامة، عن هشام، قال: أخبرني أبي، عن عائشة فذكرته. واللفظ للبخاري، وعند مسلم في حديث طويل.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الحلواء والخبيص","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5431) and Muslim (1474:21).","chapter_en":"What Has Been Reported Concerning Sweets and Khabis","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ used to love sweets and honey."]},"buhuth":{"en":["Khabis is a type of sweet made from dates, clarified butter, and honey."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5431,"lafz":true},{"key":"muslim","label":"مسلم","number":21},{"key":"muslim","label":"مسلم في الطلاق","number":1474,"n":3679}],"full":1,"dr":1},{"num":7376,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَأَلَ أَهْلَهُ الأُدُمَ فَقَالُوا مَا عِنْدَنَا إِلاَّ خَلٌّ. فَدَعَا بِهِ فَجَعَلَ يَأْكُلُ بِهِ وَيَقُولُ نِعْمَ الأُدُمُ الْخَلُّ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2052: 166) عن يحيى بن يحيى، أخبرنا أبو عوانة، عن أبي بشر، عن أبي سفيان، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الائتدام بالخل","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2052:166).","chapter_en":"What Has Been Reported Concerning Using Vinegar as a Condiment","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["Jabir ibn ʿAbdullah narrated that the Prophet ﷺ asked his family for a condiment. They said: “We have nothing except vinegar.” So he called for it and began eating with it, saying: “What an excellent condiment vinegar is.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":166,"lafz":true},{"key":"muslim","label":"مسلم في الاشربه","number":2052}],"full":1},{"num":7377,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ يَقُولُ أَخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِي ذَاتَ يَوْمٍ إِلَى مَنْزِلِهِ فَأَخْرَجَ إِلَيْهِ فِلَقًا مِنْ خُبْزٍ فَقَالَ مَا مِنْ أُدُمٍ. فَقَالُوا لاَ إِلاَّ شَىْءٌ مِنْ خَلٍّ. قَالَ فَإِنَّ الْخَلَّ نِعْمَ الأُدُمُ.","قال جابر: فما زلتُ أحب الخلّ منذ سمعتها من نبي الله صلى الله عليه وسلم. وقال طلحة: ما زلت أحب الخل منذ سمعتها من جابر."],"takhrij":"صحيح: رواه مسلم في الأشربة (2052: 167) عن يعقوب بن إبراهيم الدورقي، حدثنا إسماعيل بن علية، عن المثنى بن سعيد، حدثني طلحة بن نافع، أنه سمع جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الائتدام بالخل","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2052:167).","chapter_en":"What Has Been Reported Concerning Using Vinegar as a Condiment","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: One day the Messenger of Allah ﷺ took me by the hand to his house. A piece of bread was brought out to him, and he said: “Is there any condiment?” They said: “No, except some vinegar.” He said: “Indeed, vinegar is an excellent condiment.” Jabir said: I have continued to love vinegar ever since I heard it from the Prophet of Allah ﷺ. Talhah said: I have continued to love vinegar ever since I heard it from Jabir."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":167,"lafz":true},{"key":"muslim","label":"مسلم في الاشربه","number":2052,"n":5353}],"full":1},{"num":7378,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ قَالَ كُنْتُ جَالِسًا فِي دَارِي فَمَرَّ بِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَشَارَ إِلَىَّ فَقُمْتُ إِلَيْهِ فَأَخَذَ بِيَدِي فَانْطَلَقْنَا حَتَّى أَتَى بَعْضَ حُجَرِ نِسَائِهِ فَدَخَلَ ثُمَّ أَذِنَ لِي فَدَخَلْتُ الْحِجَابَ عَلَيْهَا فَقَالَ هَلْ مِنْ غَدَاءٍ. فَقَالُوا نَعَمْ. فَأُتِيَ بِثَلاَثَةِ أَقْرِصَةٍ فَوُضِعْنَ عَلَى نَبِيٍّ فَأَخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُرْصًا فَوَضَعَهُ بَيْنَ يَدَيْهِ وَأَخَذَ قُرْصًا آخَرَ فَوَضَعَهُ بَيْنَ يَدَىَّ ثُمَّ أَخَذَ الثَّالِثَ فَكَسَرَهُ بِاثْنَيْنِ فَجَعَلَ نِصْفَهُ بَيْنَ يَدَيْهِ وَنِصْفَهُ بَيْنَ يَدَىَّ ثُمَّ قَالَ هَلْ مِنْ أُدُمٍ. قَالُوا لاَ. إِلاَّ شَىْءٌ مِنْ خَلٍّ. قَالَ هَاتُوهُ فَنِعْمَ الأُدُمُ هُوَ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2052: 169) عن أبي بكر بن أبي شيبة، حدثنا يزيد بن هارون، أخبرنا حجاج بن أبي زينب، حدثني أبو سفيان طلحة بن نافع، قال: سمعت جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الائتدام بالخل","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2052:169).","chapter_en":"What Has Been Reported Concerning Using Vinegar as a Condiment","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: I was sitting in my house when the Messenger of Allah ﷺ passed by me. He gestured to me, so I stood and came to him. He took my hand, and we went until he came to one of the rooms of his wives. He entered, then gave me permission, so I entered the screened area. He said: “Is there any lunch?” They said: “Yes.” Three loaves were brought and placed on a small mat or tray. The Messenger of Allah ﷺ took one loaf and placed it in front of himself, took another loaf and placed it in front of me, then took the third and broke it into two, placing half in front of himself and half in front of me. Then he said: “Is there any condiment?” They said: “No, except some vinegar.” He said: “Bring it, for it is an excellent condiment.”"]},"buhuth":{"en":["His statement, “they were placed on a nubi”: This is how it appears in most manuscripts, and it was explained as a table made of palm leaves. Qadi ʿIyad transmitted from many narrators, or most of them, that it is “batti,” and “batt” is a garment made of hair or wool, so perhaps it was a cloth on which the food was placed. He said: Some narrated it as “bunni.” Qadi al-Kinani said: This is the correct reading, and it is a dish made of palm leaves. Al-Nawawi said this.","His statement, “I entered the screened area,” means he entered the part where the screen was, without seeing her body."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":169,"lafz":true},{"key":"muslim","label":"مسلم في الاشربه","number":2052,"n":5355}],"full":1,"dr":1},{"num":7379,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ نِعْمَ الأُدُمُ - أَوِ الإِدَامُ - الْخَلُّ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2051) عن عبد الله بن عبد الرحمن الدارمي، أخبرنا يحيى بن حسان، أخبرنا سليمان بن بلال، عن هشام بن عروة، عن أبيه، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في الائتدام بالخل","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2051).","chapter_en":"What Has Been Reported Concerning Using Vinegar as a Condiment","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["ʿA’ishah narrated that the Prophet ﷺ said: “What an excellent condiment vinegar is.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2051,"lafz":true}],"full":1,"dr":1},{"num":7380,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ جَعَلَ الْمُهَاجِرُونَ وَالأَنْصَارُ يَحْفِرُونَ الْخَنْدَقَ حَوْلَ الْمَدِينَةِ، وَيَنْقُلُونَ التُّرَابَ عَلَى مُتُونِهِمْ وَهُمْ يَقُولُونَ نَحْنُ الَّذِينَ بَايَعُوا مُحَمَّدَا عَلَى الإِسْلاَمِ مَا بَقِينَا أَبَدَا.","قال: يقول النبي صلى الله عليه وسلم وهو يجيبهم:","اللهم إنه لا خير إلا خير الآخرة فبارك في الأنصار والمهاجره.","قال: يؤتون بملْء كفي من الشعير، فيصنع لهم بإهالةٍ سنخةٍ توضع بين يدي القوم، والقوم جياع، وهي بشعة في الحلق، ولها ريح منتن."],"takhrij":"متفق عليه: رواه البخاري في المغازي ( (4101) عن أبي معمر، ثنا عبدالوارث، عن عبد العزيز، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الائتدام بالإهالة السَّنخة","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4101) and Muslim (1805).","chapter_en":"What Has Been Reported Concerning Using Rancid Fat as a Condiment","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["Anas said: The Emigrants and the Helpers began digging the trench around Madinah and carrying the soil on their backs while saying: “We are those who pledged allegiance to Muhammad upon Islam as long as we remain forever.” He said: The Prophet ﷺ would respond to them, saying: “O Allah, there is no good except the good of the Hereafter, so bless the Helpers and the Emigrants.” He said: They would be brought a handful or two of barley, and it would be prepared for them with rancid fat and placed before the people while they were hungry. It was unpleasant in the throat and had a foul smell."]},"buhuth":{"en":["His statement, “with fat,” refers to fat used as a condiment, whether oil, clarified butter, or animal fat. It was also said to mean what comes from the tail fat and fat, and it was said to mean solid grease. His statement, “rancid,” means its smell had changed because of its age."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4101,"lafz":true,"n":4100},{"key":"muslim","label":"مسلم","number":1805}],"full":1,"dr":1,"rep":[8915]},{"num":7381,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ وَلَقَدْ رَهَنَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دِرْعَهُ بِشَعِيرٍ، وَمَشَيْتُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِخُبْزِ شَعِيرٍ وَإِهَالَةٍ سَنِخَةٍ، وَلَقَدْ سَمِعْتُهُ يَقُولُ مَا أَصْبَحَ لآلِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلاَّ صَاعٌ، وَلاَ أَمْسَى. وَإِنَّهُمْ لَتِسْعَةُ أَبْيَاتٍ."],"takhrij":"صحيح: رواه البخاري في الرهن (2508) عن مسلم بن إبراهيم، ثنا هشام، ثنا قتادة، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الائتدام بالإهالة السَّنخة","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2508).","chapter_en":"What Has Been Reported Concerning Using Rancid Fat as a Condiment","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet ﷺ once pawned his armor for barley, and I walked to the Prophet ﷺ with barley bread and rancid fat. I heard him say: “The family of Muhammad ﷺ has not had one saʿ in the morning nor in the evening,” and they were nine households."]},"buhuth":{"en":["His statement, “they were nine households,” means he had nine wives, as in narration (2069), where it says:","“The family of Muhammad did not have a saʿ of wheat or a saʿ of grain in the evening,”","while he had nine wives."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2508,"lafz":true},{"key":"وانہم_لتسعہ_ابیات_ای_ان_عندہ_لتسع_نسوہ_کما/روایہ","label":"“وإنهم لتسعة أبيات” أي إن عنده لتسع نسوة كما في رواية","number":2069}],"full":1,"dr":1,"rep":[5647]},{"num":7382,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ أُمَّ سُلَيْمٍ، أُمَّهُ عَمَدَتْ إِلَى مُدٍّ مِنْ شَعِيرٍ، جَشَّتْهُ وَجَعَلَتْ مِنْهُ خَطِيفَةً، وَعَصَرَتْ عُكَّةً عِنْدَهَا، ثُمَّ بَعَثَتْنِي إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَتَيْتُهُ وَهْوَ فِي أَصْحَابِهِ فَدَعَوْتُهُ.","وفي لفظ: \"ثم عمدتْ إلى عُكة كان فيها شيء من سمنٍ\"."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5450) عن الصلت بن أحمد، ثنا حماد بن زيد، عن الجعد أبي عثمان، عن أنس.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الائتدام بالسمن","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5450) and Muslim (2040). The other wording is with Imam Ahmad (12491).","chapter_en":"What Has Been Reported Concerning Using Clarified Butter as a Condiment","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":13,"content":{"translation":{"en":["Anas narrated that his mother, Umm Sulaym, took one mudd of barley, ground it coarsely, and made from it a khatifah. She also squeezed a leather container that she had, then sent me to the Prophet ﷺ, and I came to him while he was among his Companions. The hadith. In another wording: “Then she went to a leather container in which there was some clarified butter.”"]},"buhuth":{"en":["His statement, “khatifah”: it follows the pattern and meaning of “porridge.” It was also said that its origin is that milk is taken, flour is sprinkled over it, then it is cooked and people lick it, snatching it with their fingers and spoons; so it was named that. Al-Fath (9/574)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5450,"lafz":true},{"key":"muslim","label":"مسلم","number":2040},{"key":"ahmad","label":". واللفظ الآخر عند الإمام أحمد","number":12491}],"full":1,"dr":1},{"num":7383,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، أَنَّ أُمَّ مَالِكٍ، كَانَتْ تُهْدِي لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي عُكَّةٍ لَهَا سَمْنًا فَيَأْتِيهَا بَنُوهَا فَيَسْأَلُونَ الأُدْمَ وَلَيْسَ عِنْدَهُمْ شَىْءٌ فَتَعْمِدُ إِلَى الَّذِي كَانَتْ تُهْدِي فِيهِ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَتَجِدُ فِيهِ سَمْنًا فَمَا زَالَ يُقِيمُ لَهَا أُدْمَ بَيْتِهَا حَتَّى عَصَرَتْهُ فَأَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ عَصَرْتِيهَا. قَالَتْ نَعَمْ. قَالَ لَوْ تَرَكْتِيهَا مَا زَالَ قَائِمًا."],"takhrij":"صحيح: رواه مسلم في الفضائل (2280) عن سلمة بن شبيب، ثنا الحسن بن أعين، ثنا معقل، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الائتدام بالسمن","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2280).","chapter_en":"What Has Been Reported Concerning Using Clarified Butter as a Condiment","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":13,"content":{"translation":{"en":["Jabir narrated that Umm Malik used to gift clarified butter to the Prophet ﷺ in a leather container of hers. Her children would come to her asking for a condiment, while they had nothing. She would go to the container in which she used to gift clarified butter to the Prophet ﷺ and find clarified butter in it. It continued providing condiment for her household until she squeezed it out. She came to the Prophet ﷺ, and he said: “Did you squeeze it?” She said: “Yes.” He said: “If you had left it, it would have continued.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2280,"lafz":true}],"full":1,"dr":1,"rep":[9686]},{"num":7384,"demo":false,"sanad":"","matn":["عَنْ مَيْمُونَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَنِ الْفَأْرَةِ تقعُ فِي السَّمْنِ فَقَالَ: انْزِعُوهَا وَمَا حَوْلَهَا فَاطْرَحُوهُ. وَزَادَ فِي رِوَايَةِ: وكلوا سمنكم."],"takhrij":"صحيح: رواه مالك في الاستئذان (20) عن ابن شهاب، عن عبيد الله بن عبد الله بن عتبة بن مسعود، عن عبد الله بن عباس، عن ميمونة، فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في السمن إذا وقعت فيه الفأرة","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (20) and al-Bukhari (236).","chapter_en":"What Has Been Reported Concerning Clarified Butter When a Mouse Falls into It","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Maymunah, the wife of the Prophet ﷺ, narrated that the Messenger of Allah ﷺ was asked about a mouse that falls into clarified butter. He said: “Remove it and what is around it, and throw it away.” Another narration adds: “And eat your clarified butter.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":20,"lafz":true},{"key":"bukhari","label":"البخاري","number":236}],"full":1,"dr":1},{"num":7385,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بن الْخَطَّابِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : كُلُوا الزيتَ وَادَّهِنُوا بِهِ فَإِنَّهُ مِنْ شَجَرَةٍ مُبَارَكَةٍ. وَفِي لفظ: اِئْتَدِمُوا بِالزَّيْتِ."],"takhrij":"حسن: رواه الترمذي (1851)، وابن ماجه (3319)، والحاكم (4/122) كلهم من طرق عن عبد الرزاق، عن معمر، عن زيد بن أسلم، عن أبيه، عن عمر فذكره. واللفظ للترمذي، واللفظ الآخر لابن ماجه والحاكم.","grade":"حسن","chapter_ar":"باب ما جاء في الزيتون وزيته","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1851), who graded it hasan, Ibn Majah (3319), and al-Hakim (7142). The wording is from al-Tirmidhi.","chapter_en":"What Has Been Reported Concerning Olives and Olive Oil","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["ʿUmar ibn al-Khattab said: The Messenger of Allah ﷺ said: “Eat olive oil and apply it, for it comes from a blessed tree.” In another wording: “Use olive oil as a condiment.”"]},"intro":{"ar":["قال اللّٰه تعالى:","(يُوقَدُ مِن شَجَرَةٍ مُبَارَكَةٍ زَيْتُونَةٍ لَا شَرْقِيَّةٍ وَلَا غَرْبِيَّةٍ يَكَادُ زَيْتُهَا يُضِيءُ وَلَوْلَمْ تَمْسَسْهُ نَارٌ نُورٌ عَلَى نُورٍ يَهْدِي اللَّهُ لِنُورِهِ مَن يَشَاءُ وَيَضْرِبُ اللَّهُ الْأَمْثَالَ لِلنَّاسِ وَٱللَّهُ بِكُلِّ شَيْءٍ عَلِيمٌ) [النور: ٣٥]","وقال تعالى:","(يُنبِتُ لَكُم بِهِ الزَّرْعَ وَالزَّيْتُونَ وَالنَّخِيلَ وَالْأَعْنَابَ وَمِن كُلِّ الثَّمَرَاتِ إِنَّ فِي ذَٰلِكَ لَآيَةً لِقَوْمٍ يَتَفَكَّرُونَ) [النحل: ١١]","وقال تعالى:","(وَالتِّينِ وَالزَّيْتُونِ) [التين: ١]"],"en":["Allah the Exalted said:","“It is lit from a blessed tree, an olive tree neither of the east nor of the west, whose oil almost glows even if no fire touches it. Light upon light. Allah guides to His light whom He wills. And Allah sets forth examples for people, and Allah is Knowing of all things.” [al-Nur: 35]","And He said:","“He causes crops, olives, palm trees, grapevines, and every kind of fruit to grow for you through it. Indeed, in that is a sign for people who reflect.” [al-Nahl: 11]","And He said:","“By the fig and the olive.” [al-Tin: 1]"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1851,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":3319},{"key":"hakim","label":"الحاكم","number":7142}],"full":1,"dr":1},{"num":7386,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ يَجُوعُ أَهْلُ بَيْتٍ عِنْدَهُمُ التَّمْرُ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2046) عن عبد الله بن عبد الرحمن الدارمي، أخبرنا يحيى بن حسّان، حدثنا سليمان بن بلال، عن هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في التمر وفضله","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2046).","chapter_en":"What Has Been Reported Concerning Dates and Their Virtue","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["ʿA’ishah narrated that the Prophet ﷺ said: “A household that has dates does not go hungry.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2046,"lafz":true}],"full":1,"dr":1},{"num":7387,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَا عَائِشَةُ بَيْتٌ لاَ تَمْرَ فِيهِ جِيَاعٌ أَهْلُهُ يَا عَائِشَةُ بَيْتٌ لاَ تَمْرَ فِيهِ جِيَاعٌ أَهْلُهُ أَوْ جَاعَ أَهْلُهُ. قَالَهَا مَرَّتَيْنِ أَوْ ثَلاَثًا."],"takhrij":"صحيح: رواه مسلم في الأشربة (2046: 153) عن عبد الله بن مسلمة بن قعنب، حدثنا يعقوب بن محمد بن طحلاء، عن أبي الرجال محمد بن عبد الرحمن، عن أمه (هي عمرة بنت عبد الرحمن)، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في التمر وفضله","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2046:153).","chapter_en":"What Has Been Reported Concerning Dates and Their Virtue","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ said: “O ʿA’ishah, a house in which there are no dates, its people are hungry. O ʿA’ishah, a house in which there are no dates, its people are hungry,” or, “its people have gone hungry.” He said it two or three times."]},"buhuth":{"en":["This applies specifically to those whose main staple food is dates."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":153,"lafz":true},{"key":"muslim","label":"مسلم في الاشربه","number":2046,"n":5337}],"full":1},{"num":7388,"demo":false,"sanad":"","matn":["عن سلمى أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ بَيْتٌ لاَ تَمْرَ فِيهِ كَالْبَيْتِ لاَ طَعَامَ فِيهِ."],"takhrij":"حسن: رواه ابن ماجه (3328) عن عبدالرحمن بن إبراهيم الدمشقي، ثنا ابن أبي فُديك، ثنا هشام بن سعد، عن عبيدالله بن أبي رافع، عن جدته سلمى فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء في التمر وفضله","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (3328).","chapter_en":"What Has Been Reported Concerning Dates and Their Virtue","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Salma narrated that the Prophet ﷺ said: “A house in which there are no dates is like a house in which there is no food.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":3328,"lafz":true}],"full":1,"dr":1},{"num":7389,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَسَمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا بَيْنَ أَصْحَابِهِ تَمْرًا، فَأَعْطَى كُلَّ إِنْسَانٍ سَبْعَ تَمَرَاتٍ، فَأَعْطَانِي سَبْعَ تَمَرَاتٍ إِحْدَاهُنَّ حَشَفَةٌ، فَلَمْ يَكُنْ فِيهِنَّ تَمْرَةٌ أَعْجَبَ إِلَىَّ مِنْهَا، شَدَّتْ فِي مَضَاغِي."],"takhrij":"صحيح: رواه البخاري في الأطعمة (5411) عن أبي النعمان، حدثنا حماد بن زيد، عن عباس الجريري، عن أبي عثمان النهدي، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في التمر وفضله","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5411).","chapter_en":"What Has Been Reported Concerning Dates and Their Virtue","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Abu Hurayrah said: One day the Prophet ﷺ distributed dates among his Companions. He gave each person seven dates, and he gave me seven dates, one of which was a dry, low-quality date. None of them was more pleasing to me than it, because it took more chewing in my mouth."]},"buhuth":{"en":["His statement, “hashafah”: hashaf refers to low-quality dates, when a fresh date dries on the palm before fully ripening."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5411,"lafz":true}],"full":1,"dr":1,"rep":[15199]},{"num":7390,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: أُتي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِتَمْرٍ عَتِيقٍ، فَجَعَلَ يُفَتِّشُهُ يُخْرِجُ السُّوسَ مِنْهُ. وَفِي لفظ: \"فِيهِ دود\"."],"takhrij":"صحيح: رواه أبو داود (3832)، وابن ماجه (3333) من طريق سلْم بن قتيبة أبي قتيبة، عن همام، عن إسحاق بن عبد الله بن أبي طلحة، عن أنس بن مالك فذكره. وليس عند ابن ماجه: \"يخرج السوس منه\".","grade":"صحيح","chapter_ar":"باب في تفتيش التمر المسوس عند الأكل","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3832) and Ibn Majah (3333).","chapter_en":"Inspecting Worm-Eaten Dates When Eating","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Anas ibn Malik said: Old dates were brought to the Prophet ﷺ, and he began inspecting them and removing the weevils from them. In another wording: “There were worms in them.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3832,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":3333}],"full":1,"dr":1},{"num":7391,"demo":false,"sanad":"","matn":["عَنِ ابْنَىْ، بُسْرٍ السُّلَمِيَّيْنِ قَالاَ دَخَلَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَدَّمْنَا زُبْدًا وَتَمْرًا وَكَانَ يُحِبُّ الزُّبْدَ وَالتَّمْرَ."],"takhrij":"صحيح: رواه أبو داود (3837)، وابن ماجه (3334) من طريق ابن جابر، حدثني سُليم بن عامر، عن ابنيْ بُسر فذكراه.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل التمر بالزبد","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3837) and Ibn Majah (3334).","chapter_en":"What Has Been Reported Concerning Eating Dates with Butter","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":18,"content":{"translation":{"en":["The two sons of Busr al-Sulamiyyin said: The Messenger of Allah ﷺ entered upon us, so we served him butter and dates, and he used to love butter and dates."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3837,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":3334}],"full":1,"dr":1},{"num":7392,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، رَضِيَ اللَّهُ عَنْهُمَا قَالَ كَانَ بِالْمَدِينَةِ يَهُودِيٌّ وَكَانَ يُسْلِفُنِي فِي تَمْرِي إِلَى الْجِدَادِ، وَكَانَتْ لِجَابِرٍ الأَرْضُ الَّتِي بِطَرِيقِ رُومَةَ فَجَلَسَتْ، فَخَلاَ عَامًا فَجَاءَنِي الْيَهُودِيُّ عِنْدَ الْجَدَادِ، وَلَمْ أَجُدَّ مِنْهَا شَيْئًا، فَجَعَلْتُ أَسْتَنْظِرُهُ إِلَى قَابِلٍ فَيَأْبَى، فَأُخْبِرَ بِذَلِكَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لأَصْحَابِهِ امْشُوا نَسْتَنْظِرْ لِجَابِرٍ مِنَ الْيَهُودِيِّ. فَجَاءُونِي فِي نَخْلِي فَجَعَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُكَلِّمُ الْيَهُودِيَّ فَيَقُولُ أَبَا الْقَاسِمِ لاَ أُنْظِرُهُ. فَلَمَّا رَأَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ فَطَافَ فِي النَّخْلِ، ثُمَّ جَاءَهُ فَكَلَّمَهُ فَأَبَى فَقُمْتُ فَجِئْتُ بِقَلِيلِ رُطَبٍ فَوَضَعْتُهُ بَيْنَ يَدَىِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَكَلَ ثُمَّ قَالَ أَيْنَ عَرِيشُكَ يَا جَابِرُ. فَأَخْبَرْتُهُ فَقَالَ افْرُشْ لِي فِيهِ. فَفَرَشْتُهُ فَدَخَلَ فَرَقَدَ، ثُمَّ اسْتَيْقَظَ فَجِئْتُهُ بِقَبْضَةٍ أُخْرَى فَأَكَلَ مِنْهَا، ثُمَّ قَامَ فَكَلَّمَ الْيَهُودِيَّ فَأَبَى عَلَيْهِ فَقَامَ فِي الرِّطَابِ فِي النَّخْلِ الثَّانِيَةَ ثُمَّ قَالَ يَا جَابِرُ جُدَّ وَاقْضِ. فَوَقَفَ فِي الْجَدَادِ فَجَدَدْتُ مِنْهَا مَا قَضَيْتُهُ وَفَضَلَ مِنْهُ فَخَرَجْتُ حَتَّى جِئْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَشَّرْتُهُ فَقَالَ أَشْهَدُ أَنِّي رَسُولُ اللَّهِ."],"takhrij":"صحيح: رواه البخاري في الأطعمة (5442) عن سعيد بن أبي مريم، حدثنا أبو غسّان، حدثني أبو حازم، عن إبراهيم بن عبد الرحمن بن عبد الله بن أبي ربيعة، عن جابر بن عبدالله فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الرطب","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5442).","chapter_en":"What Has Been Reported Concerning Fresh Dates","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":19,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: There was a Jewish man in Madinah, and he used to give me advance payment for my dates until harvest time. Jabir had land on the road to Rumah. A year passed in which the land produced nothing. The Jewish man came to me at harvest time, and I found nothing from it. I began asking him to give me time until the following year, but he refused. The Prophet ﷺ was informed of that, so he said to his Companions: “Go so that we may ask the Jewish man to give Jabir more time.” They came to me in my palm grove, and the Prophet ﷺ began speaking to the Jewish man, but he said: “O Abu al-Qasim, I will not give him more time.” When the Prophet ﷺ saw this, he stood and walked around the palm trees, then came back and spoke to him, but he refused. I stood and brought a few fresh dates and placed them before the Prophet ﷺ, and he ate. Then he said: “Where is your shade shelter, O Jabir?” I told him, and he said: “Spread something for me in it.” So I spread something for him, and he entered and slept. Then he woke up, and I brought him another handful, and he ate from it. Then he stood and spoke to the Jewish man, but he refused him. Then he stood among the fresh date palms a second time and said: “O Jabir, harvest and repay.” He stood at the harvest, so I harvested from it what I repaid him with, and some remained. I went out until I came to the Prophet ﷺ and gave him the good news. He said: “I bear witness that I am the Messenger of Allah.”"]},"buhuth":{"en":["His statement, “until harvest time,” refers to the time of cutting the fruit of the palm trees. His statement, “I asked him to give me time,” means I asked him to delay payment.","His statement, “your shade shelter,” refers to a place made in the garden for shade."]},"intro":{"ar":["قال اللّٰه تعالى:","(وَهُزِّي إِلَيْكِ بِجِذْعِ النَّخْلَةِ تُسَاقِطْ عَلَيْكِ رُطَبًا جَنِيًّا) [سورة مريم: ٢٥]"],"en":["Allah the Exalted said:","“Shake the trunk of the palm tree toward yourself; it will drop upon you ripe fresh dates.” [Surah Maryam: 25]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5442,"lafz":true,"n":5443}],"full":1,"dr":1},{"num":7393,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ بَيْنَا نَحْنُ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جُلُوسٌ إِذْ أُتِيَ بِجُمَّارِ نَخْلَةٍ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ مِنَ الشَّجَرِ لَمَا بَرَكَتُهُ كَبَرَكَةِ الْمُسْلِمِ. فَظَنَنْتُ أَنَّهُ يَعْنِي النَّخْلَةَ، فَأَرَدْتُ أَنْ أَقُولَ هِيَ النَّخْلَةُ يَا رَسُولَ اللَّهِ. ثُمَّ الْتَفَتُّ فَإِذَا أَنَا عَاشِرُ عَشَرَةٍ أَنَا أَحْدَثُهُمْ فَسَكَتُّ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هِيَ النَّخْلَةُ."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5444) عن عمر بن حفص بن غياث، حدثنا أبي، حدثنا الأعمش، قال: حدثتي مجاهد، عن عبد الله بن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أكل الجُمّار","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5444) and Muslim (2811).","chapter_en":"What Has Been Reported Concerning Eating Palm-Heart","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["Ibn ʿUmar said: While we were sitting with the Prophet ﷺ, palm-heart was brought. The Prophet ﷺ said: “Among trees there is a tree whose blessing is like the blessing of a Muslim.” I thought that he meant the palm tree, and I wanted to say: “It is the palm tree, O Messenger of Allah.” Then I looked around and saw that I was the tenth of ten, and I was the youngest of them, so I remained silent. Then the Prophet ﷺ said: “It is the palm tree.”"]},"buhuth":{"en":["His statement, “palm-heart,” refers to what is eaten from the heart of the palm tree, and it is soft."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5444,"lafz":true},{"key":"muslim","label":"مسلم","number":2811}],"full":1,"dr":1},{"num":7394,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ، قَالَ إِنْ كُنَّا لَنَفْرَحُ بِيَوْمِ الْجُمُعَةِ، كَانَتْ لَنَا عَجُوزٌ تَأْخُذُ أُصُولَ السِّلْقِ، فَتَجْعَلُهُ فِي قِدْرٍ لَهَا، فَتَجْعَلُ فِيهِ حَبَّاتٍ مِنْ شَعِيرٍ، إِذَا صَلَّيْنَا زُرْنَاهَا فَقَرَّبَتْهُ إِلَيْنَا، وَكُنَّا نَفْرَحُ بِيَوْمِ الْجُمُعَةِ مِنْ أَجْلِ ذَلِكَ، وَمَا كُنَّا نَتَغَدَّى وَلاَ نَقِيلُ إِلاَّ بَعْدَ الْجُمُعَةِ، وَاللَّهِ مَا فِيهِ شَحْمٌ وَلاَ وَدَكٌ."],"takhrij":"صحيح: رواه البخاري في الأطعمة (5403) عن يحيى بن بكير، حدثنا يعقوب بن عبد الرحمن، عن أبي حازم، عن سهل بن سعد فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في السِّلق","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5403).","chapter_en":"What Has Been Reported Concerning Chard","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":22,"content":{"translation":{"en":["Sahl ibn Saʿd said: We used to rejoice on Friday. We had an old woman who would take the roots of chard, put them in her pot, and put some grains of barley in it. When we had prayed, we would visit her, and she would bring it near to us. We used to rejoice on Friday because of that. We would not eat lunch or take a midday rest except after Friday prayer. By Allah, there was no fat or grease in it."]},"buhuth":{"en":["His statement, “the roots of chard,” refers to a type of green vegetable with long leaves and a root that extends into the ground. Its leaves are tender and soft, and they are eaten cooked. His statement, “nor grease,” means fat, in both wording and meaning."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5403,"lafz":true}],"full":1,"dr":1},{"num":7395,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى الأَشْعَرِيِّ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَثَلُ الْمُؤْمِنِ الَّذِي يَقْرَأُ الْقُرْآنَ كَمَثَلِ الأُتْرُجَّةِ، رِيحُهَا طَيِّبٌ وَطَعْمُهَا طَيِّبٌ، وَمَثَلُ."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5427)، ومسلم في صلاة المسافرين وقصرها (797) كلاهما عن قتيبة بن سعيد- وزاد مسلم أبا كامل الجحدري – عن أبي عوانة، عن قتادة، عن أنس فذكره بتمامه.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الأترجة","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5427) and Muslim (797).","chapter_en":"What Has Been Reported Concerning Citron","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":23,"content":{"translation":{"en":["Abu Musa al-Ashʿari said: The Messenger of Allah ﷺ said: “The example of the believer who recites the Qur’an is like the citron: its scent is pleasant and its taste is pleasant…” the hadith."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5427,"lafz":true},{"key":"muslim","label":"مسلم","number":797}],"full":1},{"num":7396,"demo":false,"sanad":"","matn":["عَنْ جابر بْنِ عَبْدِ اللَّهِ قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَرِّ الظَّهْرَانِ نَجْنِي الْكَبَاثَ، فَقَالَ: عَلَيْكُمْ بِالأَسْوَدِ مِنْهُ، فَإِنَّهُ أَيْطَبُ، فَقِيلَ: أ كنتَ تَرْعَى الْغَنَمَ؟ قَالَ: نَعَمْ. وَهَلْ مِنْ نَبِيٍّ إِلاَّ رَعَاهَا."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5453)، ومسلم في الأشربة (2050) كلاهما من طريق عبد الله بن وهب، عن يونس، عن ابن شهاب، عن أبي سلمة بن عبد الرحمن، عن جابر بن عبد الله فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الكباث","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5453) and Muslim (2050).","chapter_en":"What Has Been Reported Concerning Kabath","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":24,"content":{"translation":{"en":["Jabir said: We were with the Messenger of Allah ﷺ at Marr al-Zahran, gathering kabath. He said: “Take the black ones, for they are better.” It was said: “Did you used to herd sheep?” He said: “Yes. Was there any prophet who did not herd them?”"]},"buhuth":{"en":["“Kabath” is the ripe fruit of the arak tree. Its berries are slightly larger than coriander seeds, as mentioned in al-Muʿjam al-Wasit."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5453,"lafz":true},{"key":"muslim","label":"مسلم","number":2050}],"full":1,"dr":1},{"num":7397,"demo":false,"sanad":"","matn":["عَنْ كَلَدَةَ بْنِ حَنْبَلٍ، أَنَّ صَفْوَانَ بْنَ أُمَيَّةَ، بَعَثَهُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِلَبَنٍ وَجِدَايَةٍ وَضَغَابِيسَ - وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِأَعْلَى مَكَّةَ - فَدَخَلْتُ وَلَمْ أُسَلِّمْ فَقَالَ ارْجِعْ فَقُلِ السَّلاَمُ عَلَيْكُمْ. وَذَاكَ بَعْدَ مَا أَسْلَمَ صَفْوَانُ بْنُ أُمَيَّةَ."],"takhrij":"حسن: رواه أبو داود (5176)، والترمذي (2710)، والنسائي في الكبرى (6702)، وأحمد (15425) كلهم من طرق عن ابن جريج، أخبرني عمرو بن أبي سفيان، أن عمرو بن عبد الله بن صفوان أخبره أن كلدة بن حنبل أخبره فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الضغابيس","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (5176), al-Tirmidhi (2710), who graded it hasan, al-Nasa’i in al-Kubra (6702), and Ahmad (15425).","chapter_en":"What Has Been Reported Concerning Daghābīs","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":25,"content":{"translation":{"en":["Kaldah ibn Hanbal narrated that Safwan ibn Umayyah sent him to the Messenger of Allah ﷺ with milk, a young goat (kid), and daghābīs while the Prophet ﷺ was in the upper part of Makkah. I entered without giving greeting, so he said: “Go back and say: Peace be upon you.” That was after Safwan ibn Umayyah had embraced Islam."]},"buhuth":{"en":["He said: “Daghābīs” is an edible plant. In al-Nihayah: It refers to small cucumbers; its singular is daghbūs."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":5176,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":2710},{"key":"kubranasai","label":"النسائي في الكبرى","number":6702},{"key":"ahmad","label":"مسند الإمام أحمد","number":15425,"n":15425}],"full":1,"dr":1,"rep":[14200]},{"num":7398,"demo":false,"sanad":"","matn":["عَنْ سَعْدٍ، قَالَ رَأَيْتُنِي سَابِعَ سَبْعَةٍ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا لَنَا طَعَامٌ إِلاَّ وَرَقُ الْحُبْلَةِ ـ أَوِ الْحَبَلَةِ ـ حَتَّى يَضَعَ أَحَدُنَا مَا تَضَعُ الشَّاةُ، ثُمَّ أَصْبَحَتْ بَنُو أَسَدٍ تُعَزِّرُنِي عَلَى الإِسْلاَمِ، خَسِرْتُ إِذًا وَضَلَّ سَعْيِي."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5412)، ومسلم في الزهد والرقائق (2966: 12) كلاهما من طريق إسماعيل بن أبي خالد، عن قيس (هو ابن أبي حازم)، عن سعد (هو ابن أبي وقاص) قال: فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أكل ورق الحُبْلة","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5412) and Muslim (2966:12). The wording is from al-Bukhari.","chapter_en":"What Has Been Reported Concerning Eating the Leaves of the Hablah","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":26,"content":{"translation":{"en":["Saʿd said: I remember myself as the seventh of seven with the Prophet ﷺ, and we had no food except the leaves of the habl — or hablah — until one of us would pass stool like that of a sheep. Then the people of Banu Asad began reproaching me regarding Islam. I would indeed have lost then, and my effort would have gone astray."]},"buhuth":{"en":["His statement, “leaves of the hablah”: It was said that what is meant is the fruit of thorny desert trees and the fruit of the samur tree, which resembles cowpeas, as mentioned in al-Fath. In al-Muʿjam al-Wasit: hablah is the fruit of the legume family, such as beans, lentils, kidney beans, and the like. It has two halves and several seeds, and it opens when it ripens.","His statement, “Banu Asad,” refers to the sons of al-Zubayr ibn al-ʿAwwam. The meaning of “reproaching me” is that they were blaming him for falling short in it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5412,"lafz":true},{"key":"muslim","label":"مسلم","number":12},{"key":"muslim","label":"مسلم في الزهد والرقائق","number":2966}],"full":1,"dr":1},{"num":7399,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ فِي غَزْوَةِ خَيْبَرَ مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ ـ يَعْنِي الثُّومَ ـ فَلاَ يَقْرَبَنَّ مَسْجِدَنَا."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (853)، ومسلم في المساجد (561: 68) كلاهم من طريق يحيى القطان، عن عبيد الله، حدثني نافع، عن ابن عمر، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أكل الثوم والبصل والكراث","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (853) and Muslim (561:68).","chapter_en":"What Has Been Reported Concerning Eating Garlic, Onion, and Leek","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":27,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Prophet ﷺ said during the expedition of Khaybar: “Whoever eats from this plant” — meaning garlic — “must not come near our mosque.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":853,"lafz":true},{"key":"muslim","label":"مسلم","number":68},{"key":"muslim","label":"مسلم في المساجد","number":561}],"full":1,"rep":[3143]},{"num":7400,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الْعَزِيزِ، - وَهُوَ ابْنُ صُهَيْبٍ - قَالَ سُئِلَ أَنَسٌ عَنِ الثُّومِ، فَقَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ فَلاَ يَقْرَبَنَّا وَلاَ يُصَلِّي مَعَنَا."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5451)، ومسلم في المساجد (562) كلاهما من طريق عبد العزيز بن صهيب به. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أكل الثوم والبصل والكراث","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5451) and Muslim (562). The wording is from Muslim.","chapter_en":"What Has Been Reported Concerning Eating Garlic, Onion, and Leek","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":27,"content":{"translation":{"en":["ʿAbd al-ʿAziz ibn Suhayb said: Anas was asked about garlic, so he said: The Messenger of Allah ﷺ said: “Whoever eats from this plant must not come near us, nor pray with us.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5451,"lafz":true},{"key":"muslim","label":"مسلم","number":562}],"full":1},{"num":7401,"demo":false,"sanad":"","matn":["عَنْ جابر بْنِ عَبْدِ اللَّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أَكَلَ ثُومًا أَوْ بَصَلاً فَلْيَعْتَزِلْنَا –أَوْ ليعتزل مَسْجِدَنَا- ولتقعد فِي بَيْتِهِ، وانه أُتِيَ بِقِدْرٍ فِيهِ خَضِرَاتٌ مِنْ بُقُولٍ، فَوَجَدَ لَهَا رِيحًا، فَسَأَلَ فَأُخْبِرَ بِمَا فِيهَا مِنَ الْبُقُولِ، فَقَالَ: قَرِّبُوهَا إِلَى بَعْضِ أَصْحَابِهِ، فَلَمَّا رَآهُ كَرِهَ أَكْلَهَا، قَالَ: كُلْ فَإِنِّي أُنَاجِي مَنْ لاَ تُنَاجِي."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (855)، ومسلم في المساجد (564: 73) –والسياق له- من طريق ابن وهب، أخبرني يونس، عن ابن شهاب، حدثني عطاء بن أبي رباح، أن جابر بن عبد الله قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أكل الثوم والبصل والكراث","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (855) and Muslim (564:73). The wording is from Muslim.","chapter_en":"What Has Been Reported Concerning Eating Garlic, Onion, and Leek","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":27,"content":{"translation":{"en":["Jabir ibn ʿAbdullah narrated that the Messenger of Allah ﷺ said: “Whoever eats garlic or onion should keep away from us,” or, “keep away from our mosque, and sit in his house.” A pot containing green vegetables was brought to him, and he noticed its smell. He asked about it and was told what vegetables it contained. He said: “Bring it near to some of his Companions.” When he saw that he disliked eating it, he said: “Eat, for I converse privately with one whom you do not converse with.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":855,"lafz":true},{"key":"muslim","label":"مسلم","number":73},{"key":"muslim","label":"مسلم في المساجد","number":564,"n":1254}],"full":1},{"num":7402,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قَالَ: مَنْ أَكَلَ مِنْ هَذِهِ الْخَضْرَاوَاتِ فَلَا يَقْرَبَنَّ مَسْجِدِنَا: الثُّومِ، وَالْكُرَّاثِ، وَالْبَصَلِ، وَالْفُجْلِ، فَإِنَّ الْمَلَائِكَةَ تَتَأَذَّى مِمَّا يَتَأَذَّى مِنْهُ بَنُو آدَمَ."],"takhrij":"صحيح: رواه مسلم في المساجد (564: 74) عن محمد بن حاتم، حدثنا يحيى بن سعيد، عن ابن جريج، قال: أخبرني عطاء، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل الثوم والبصل والكراث","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (564:74).","chapter_en":"What Has Been Reported Concerning Eating Garlic, Onion, and Leek","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":27,"content":{"translation":{"en":["Jabir ibn ʿAbdullah narrated from the Prophet ﷺ that he said: “Whoever eats from this herb, garlic” — and he once said: “Whoever eats onion, garlic, and leek” — “must not come near our mosque, for the angels are harmed by what the children of Adam are harmed by.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":74,"lafz":true},{"key":"muslim","label":"مسلم في المساجد","number":564}],"full":1},{"num":7403,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ أَكْلِ الْبَصَلِ وَالْكُرَّاثِ. فَغَلَبَتْنَا الْحَاجَةُ فَأَكَلْنَا مِنْهَا فَقَالَ مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ الْمُنْتِنَةِ فَلاَ يَقْرَبَنَّ مَسْجِدَنَا فَإِنَّ الْمَلاَئِكَةَ تَأَذَّى مِمَّا يَتَأَذَّى مِنْهُ الإِنْسُ."],"takhrij":"صحيح: رواه مسلم في المساجد ومواضع الصلاة (564: 72) عن أبي بكر بن أبي شيبة، حدثنا كثير بن هشام، عن هشام الدستوائي، عن أبي الزبير فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل الثوم والبصل والكراث","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (564:72).","chapter_en":"What Has Been Reported Concerning Eating Garlic, Onion, and Leek","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":27,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ forbade eating onion and leek, but need overcame us, so we ate from them. He said: “Whoever eats from this foul-smelling plant must not come near our mosque, for the angels are harmed by what humans are harmed by.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":72,"lafz":true},{"key":"muslim","label":"مسلم في المساجد ومواضع الصلاه","number":564}],"full":1},{"num":7404,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ فَلاَ يَقْرَبَنَّ مَسْجِدَنَا وَلاَ يُؤْذِيَنَّا بِرِيحِ الثُّومِ."],"takhrij":"صحيح: رواه مسلم في المساجد (563: 71) من طريق عبد الرزاق، أخبرنا معمر، عن الزهري، عن ابن المسيب، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل الثوم والبصل والكراث","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (563:71).","chapter_en":"What Has Been Reported Concerning Eating Garlic, Onion, and Leek","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":27,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Whoever eats from this plant must not come near our mosque, nor harm us with the smell of garlic.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":71,"lafz":true},{"key":"muslim","label":"مسلم في المساجد","number":563}],"full":1,"rep":[3146]},{"num":7405,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، قَالَ لَمْ نَعْدُ أَنْ فُتِحَتْ، خَيْبَرُ فَوَقَعْنَا أَصْحَابَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي تِلْكَ الْبَقْلَةِ الثُّومِ وَالنَّاسُ جِيَاعٌ فَأَكَلْنَا مِنْهَا أَكْلاً شَدِيدًا ثُمَّ رُحْنَا إِلَى الْمَسْجِدِ فَوَجَدَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الرِّيحَ فَقَالَ مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ الْخَبِيثَةِ شَيْئًا فَلاَ يَقْرَبَنَّا فِي الْمَسْجِدِ. فَقَالَ النَّاسُ حُرِّمَتْ حُرِّمَتْ. فَبَلَغَ ذَاكَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ أَيُّهَا النَّاسُ إِنَّهُ لَيْسَ بِي تَحْرِيمُ مَا أَحَلَّ اللَّهُ لِي وَلَكِنَّهَا شَجَرَةٌ أَكْرَهُ رِيحَهَا."],"takhrij":"صحيح: رواه مسلم في المساجد (565) عن عمرو الناقد، حدثنا إسماعيل بن عُلية، عن الجُريري، عن أبي نضرة، عن أبي سعيد فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل الثوم والبصل والكراث","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (565).","chapter_en":"What Has Been Reported Concerning Eating Garlic, Onion, and Leek","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":27,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: No sooner had Khaybar been conquered than we, the Companions of the Messenger of Allah ﷺ, fell upon that herb, garlic, while the people were hungry. We ate a great deal of it, then we went to the mosque. The Messenger of Allah ﷺ noticed the smell and said: “Whoever eats anything from this foul plant must not come near us in the mosque.” The people said: “It has been forbidden, it has been forbidden.” That reached the Prophet ﷺ, so he said: “O people! I do not forbid what Allah has made lawful for me, but it is a plant whose smell I dislike.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":565,"lafz":true}],"full":1,"rep":[3148]},{"num":7406,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ عَلَى زَرَّاعَةِ بَصَلٍ هُوَ وَأَصْحَابُهُ فَنَزَلَ نَاسٌ مِنْهُمْ فَأَكَلُوا مِنْهُ وَلَمْ يَأْكُلْ آخَرُونَ فَرُحْنَا إِلَيْهِ فَدَعَا الَّذِينَ لَمْ يَأْكُلُوا الْبَصَلَ وَأَخَّرَ الآخَرِينَ حَتَّى ذَهَبَ رِيحُهَا."],"takhrij":"صحيح: رواه مسلم في المساجد (566) من طريق ابن وهب، أخبرني عمرو، عن بكير الأشج، عن ابن خباب (وهو عبد الله)، عن أبي سعيد الخدري فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل الثوم والبصل والكراث","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (566).","chapter_en":"What Has Been Reported Concerning Eating Garlic, Onion, and Leek","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":27,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that the Messenger of Allah ﷺ passed by an onion field with his Companions. Some of them stopped and ate from it, while others did not eat. Then we returned to him. He called those who had not eaten onion and delayed the others until its smell had gone away."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":566,"lafz":true}],"full":1,"dr":1,"rep":[3149]},{"num":7407,"demo":false,"sanad":"","matn":["عن معدان أبي طلحة، أن عمر بن الخطاب خطب يوم الجمعة، فذكر نبي الله صلى الله عليه وسلم، وذكر أبا بكر –وذكر خطبة طويلة- قال في آخرها: ثم إنكم أيها الناس تأكلون شجرتين لاأراهما إلا خبيثتين، هذا البصل والثوم، لقد رأيت رسول الله صلى الله عليه وسلم إذا وجد ريحهما من الرجل أمر به فأخرج إلى البقيع، فمن أكلهما فليُمِتْهما طبخاً."],"takhrij":"صحيح: رواه مسلم في المساجد (567) عن محمد بن المثنى، ثنا يحيى بن سعيد، ثنا هشام، ثنا قتادة، عن سالم بن أبي الجعد، عن معدان بن أبي طلحة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أكل الثوم والبصل مطبوخين","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (567).","chapter_en":"What Has Been Reported Concerning Eating Garlic and Onion When Cooked","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":28,"content":{"translation":{"en":["Maʿdan ibn Abi Talhah narrated that ʿUmar ibn al-Khattab delivered a sermon on Friday. He mentioned the Prophet of Allah ﷺ and mentioned Abu Bakr — and he gave a long sermon — and at the end of it he said: “Then, O people, you eat two plants that I only see as foul: this onion and garlic. I saw the Messenger of Allah ﷺ, when he found their smell from a man, order that he be taken out to al-Baqiʿ. So whoever eats them should kill their smell by cooking.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":567,"lafz":true}],"full":1},{"num":7408,"demo":false,"sanad":"","matn":["عَنْ قرة بن إياس: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ هَاتَيْنِ الشَّجَرَتَيْنِ فَقَالَ: مَنْ أَكَلَهُمَا فَلاَ يَقْرَبَنَّ مَسْجِدَنَا وَقَالَ: إِنْ كُنْتُمْ لاَ بُدَّ آكلوهما فَأَمِيتُوهُمَا طَبْخًا، قَالَ: يَعْنِي الْبَصَلَ وَالثُّومَ."],"takhrij":"حسن: رواه أبو داود (3827)، والنسائي في الكبرى (6646) والترمذي في العلل الكبير (2/765) والبيهقي في الكبرى (3/78) كلهم من طريق خالد بن ميسرة العطار، عن معاوية بن قرة، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في أكل الثوم والبصل مطبوخين","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3827), al-Nasa’i in al-Kubra (6646), al-Tirmidhi in al-ʿIlal al-Kabir (2/765), and al-Bayhaqi in al-Sunan al-Kubra (3/78).","chapter_en":"What Has Been Reported Concerning Eating Garlic and Onion When Cooked","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة من غير اللحوم","group_en":"Collection of What Has Been Reported Concerning Foods Other Than Meat","part_no":40,"group_no":2,"chapter_no":28,"content":{"translation":{"en":["Qurrah ibn Iyas narrated that the Messenger of Allah ﷺ forbade these two plants and said: “Whoever eats them must not come near our mosque.” And he said: “If you must eat them, then kill their smell by cooking.” He said: Meaning onion and garlic."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3827,"lafz":true},{"key":"kubranasai","label":"النسائي في الكبرى","number":6646},{"key":"tirmidhi","label":"الترمذي في العلل الكبير","number":2},{"key":"kubrabayhaqi","label":"البيهقي في الكبرى","number":3}],"full":1,"dr":1},{"num":7409,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ، أَنَّ رَجُلاً، نَزَلَ الْحَرَّةَ وَمَعَهُ أَهْلُهُ وَوَلَدُهُ فَقَالَ رَجُلٌ إِنَّ نَاقَةً لِي ضَلَّتْ فَإِنْ وَجَدْتَهَا فَأَمْسِكْهَا. فَوَجَدَهَا فَلَمْ يَجِدْ صَاحِبَهَا فَمَرِضَتْ فَقَالَتِ امْرَأَتُهُ انْحَرْهَا. فَأَبَى فَنَفَقَتْ فَقَالَتِ اسْلُخْهَا حَتَّى نُقَدِّدَ شَحْمَهَا وَلَحْمَهَا وَنَأْكُلَهُ. فَقَالَ حَتَّى أَسْأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَتَاهُ فَسَأَلَهُ فَقَالَ هَلْ عِنْدَكَ غِنًى يُغْنِيكَ. قَالَ لاَ. قَالَ فَكُلُوهَا. قَالَ فَجَاءَ صَاحِبُهَا فَأَخْبَرَهُ الْخَبَرَ فَقَالَ هَلاَّ كُنْتَ نَحَرْتَهَا. قَالَ اسْتَحْيَيْتُ مِنْكَ."],"takhrij":"حسن: رواه أبو داود (3816)، وأحمد (20993)، وابنه عبد الله (20903) كلهم من طرق عن حماد بن سلمة، ثنا سماك، عن جابر بن سمرة فذكره.","grade":"حسن","chapter_ar":"باب تحريم أكل الميتة وإباحتها للمضطر","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3816), Ahmad (20993), and his son ʿAbdullah (20903).","chapter_en":"The Prohibition of Eating Carrion and Its Permissibility for One Compelled by Necessity","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Jabir ibn Samurah narrated that a man settled in al-Harrah with his family and children. Another man said: “A she-camel of mine has gone missing. If you find it, hold it.” He found it but did not find its owner. It became sick, and his wife said: “Slaughter it.” He refused, and it died. She said: “Skin it so that we may dry its fat and meat and eat it.” He said: “Not until I ask the Messenger of Allah ﷺ.” So he came to him and asked him. He said: “Do you have any wealth that suffices you?” He said: “No.” He said: “Then eat it.” He said: Then its owner came, and he informed him of what had happened. He said: “Why did you not slaughter it?” He said: “I felt shy before you.”"]},"intro":{"ar":["وقال تعالى:","(حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنزِيرِ وَمَا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ وَالْمُنْخَنِقَةُ وَالْمَوْقُوذَةُ وَالْمُتَرَدِّيَةُ وَالنَّطِيحَةُ وَمَا أَكَلَ السَّبُعُ إِلَّا مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى النُّصُبِ وَأَن تَسْتَقْسِمُوا بِالْأَزْلَامِ ذَٰلِكُمْ فِسْقٌ الْيَوْمَ يَئِسَ الَّذِينَ كَفَرُوا مِن دِينِكُمْ فَلَا تَخْشَوْهُمْ وَاخْشَوْنِ الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الإِسْلَامَ دِيناً فَمَنِ اضْطُرَّ فِي مَخْمَصَةٍ غَيْرَ مُتَجَانِفٍ لِإِثْمٍ فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ) [المائدة: ٣]","والحكمة في ذلك أن أكل المحرمات المذكورة في الآية السابقة وآية البقرة (١٧٣) لا يضر أكلها إن أكلها الإنسان على المعدة الخالية، بخلاف الأكل حالة الشبع."],"en":["And He said:","“Forbidden to you are carrion, blood, the flesh of swine, that which has been dedicated to other than Allah, animals strangled, struck dead, fallen to death, gored to death, and what a predator has eaten — except what you slaughter before it dies — and what is sacrificed on stone altars, and that you seek decision through divining arrows. That is grave disobedience. Today those who disbelieve have despaired of your religion, so do not fear them, but fear Me. Today I have perfected for you your religion, completed My favor upon you, and chosen Islam for you as a religion. But whoever is compelled by severe hunger, not inclining to sin, then indeed Allah is Forgiving, Merciful.” [al-Ma’idah: 3]","The wisdom in this is that eating the forbidden things mentioned in the previous verse and in the verse of al-Baqarah (173) does not harm a person if he eats them on an empty stomach, unlike eating them while already full."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3816,"lafz":true},{"key":"ابنہ_عبد_اللہ","label":"ابنه عبد اللّٰه","number":20903},{"key":"ahmad","label":"مسند الإمام أحمد","number":20993,"n":20993}],"full":1,"dr":1},{"num":7410,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جندب، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يُجْزِئُ مِنَ الضَّرُورَةِ أَوِ الضَّارُورَةِ غَبُوقٌ أَوْ صَبُوحٌ."],"takhrij":"صحيح: رواه الحاكم (4/125) من طريق معاذ بن معاذ العنبري، ثنا ابن عون قال: قرأت عند الحسن كتاب سمرة بن جندب إلى بنيه، وفيه: أن رسول الله صلى الله عليه وسلم قال: فذكره.","grade":"صحيح","chapter_ar":"باب متى يحل أكل الميتة؟","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Hakim (7158).","chapter_en":"When Does Eating Carrion Become Permissible?","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Samurah ibn Jundub narrated that the Messenger of Allah ﷺ said: “A drink or meal in the evening, or a drink or meal in the morning, suffices for necessity.”"]},"buhuth":{"en":["His statement, “necessity,” is another linguistic form of the same word, as mentioned in al-Nihayah. His statement, “ghabuq,” refers to drinking at the end of the day, and “sabhuh” refers to drinking at its beginning. Then the terms came to be used for eating as well: the morning meal is lunch, and the evening meal is dinner."]}},"tuhfa":{},"refs":[{"key":"hakim","label":"المستدرك على الصحيحين","number":7158,"n":7156,"lafz":true}],"full":1,"dr":1},{"num":7411,"demo":false,"sanad":"","matn":["عَنْ أَبِي وَاقِدٍ اللَّيْثِيِّ قَالَ: قَدِمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ وَهُمْ يَجُبّون أَسْنِمَةَ الْإِبِلِ، وَيَقْطَعُونَ أَلْيَاتِ الْغَنَمِ، فَقَالَ: مَا قُطع مِنَ الْبَهِيمَةِ وَهِيَ حَيَّةٌ فَهِيَ مَيْتَةٌ."],"takhrij":"حسن: رواه أبو داود (2858)، والترمذي (1480) واللفظ له، وأحمد (21903)، وابن الجارود (876)، والحاكم (4/239) كلهم من طرق عن عبد الرحمن بن عبد الله بن دينار، عن زيد بن أسلم، عن عطاء بن يسار، عن أبي واقد الليثي، فذكره.","grade":"حسن","chapter_ar":"باب النهي عن أكل ما يُقطع من بهيمة الأنعام وهي حية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2858), al-Tirmidhi (1480), whose wording this is, Ahmad (21903), Ibn al-Jarud (876), and al-Hakim (7597).","chapter_en":"The Prohibition of Eating What Is Cut from Grazing Livestock While It Is Alive","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Abu Waqid al-Laythi said: The Prophet ﷺ came to Madinah while they were cutting off the humps of camels and cutting off the fat tails of sheep. He said: “Whatever is cut from an animal while it is alive is carrion.”"]},"buhuth":{"en":["His statement, “they were cutting off,” means they were severing them. His statement, “fat tails,” refers to the tail end of the sheep. Every limb cut from an animal while it is alive is not permissible to eat, because it becomes carrion when life leaves it. They used to do this in the pre-Islamic period, so they were forbidden from it."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2858,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1480},{"key":"sh13071","label":"ابن الجارود","number":876,"n":911},{"key":"ahmad","label":"مسند الإمام أحمد","number":21903,"n":21904},{"key":"hakim","label":"المستدرك على الصحيحين","number":7150,"n":7148}],"full":1,"dr":1},{"num":7412,"demo":false,"sanad":"","matn":["عَنْ أَبِي ثَعْلَبَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ أَكْلِ كُلِّ ذِي نَابٍ مِنَ السِّبَاعِ."],"takhrij":"متفق عليه: رواه مالك في الضحايا (2176-رواية أبي مصعب الزهري) عن ابن شهاب، عن أبي إدريس الخولاني، عن أبي ثعلبة الخشني فذكره. ورواه البخاري في الذبائح والصيد (5530) عن عبد الله بن يوسف، أخبرنا مالك به.","grade":"متفق عليه","chapter_ar":"باب تحريم أكل كلِّ ذي ناب من السباع، وكل ذي مخلب من الطير","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik in al-Dahaya (2176, the narration of Abu Musʿab al-Zuhri), al-Bukhari (5530), and Muslim (1932:14).","chapter_en":"The Prohibition of Eating Every Predator with Fangs and Every Bird with Talons","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Abu Thaʿlabah al-Khushani narrated that the Messenger of Allah ﷺ forbade eating every predator with fangs."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك في الضحايا","number":2176},{"key":"bukhari","label":"البخاري","number":5530,"lafz":true},{"key":"muslim","label":"مسلم","number":14}],"full":1,"dr":1},{"num":7413,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ أَكْلُ كُلِّ ذِي نَابٍ مِنَ السِّبَاعِ حَرَامٌ."],"takhrij":"صحيح: رواه مالك في الصيد (14) عن إسماعيل بن أبي حكيم، عن عبيدة بن سفيان الحضرمي، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب تحريم أكل كلِّ ذي ناب من السباع، وكل ذي مخلب من الطير","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (14) and Muslim (1933:15).","chapter_en":"The Prohibition of Eating Every Predator with Fangs and Every Bird with Talons","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “Eating every predator with fangs is forbidden.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":14,"lafz":true,"n":15},{"key":"muslim","label":"مسلم","number":15,"n":172}],"full":1,"dr":1},{"num":7414,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ كُلِّ ذِي نَابٍ مِنَ السِّبَاعِ وَعَنْ كُلِّ ذِي مِخْلَبٍ مِنَ الطَّيْرِ."],"takhrij":"صحيح: رواه مسلم في الصيد والذبائح (1934: 16) عن عبيد الله بن معاذ العنبري، حدثنا أبي، حدثنا شعبة، عن الحكم (هو ابن عيينة)، عن ميمون بن مهران، عن ابن عباس قال: فذكره.","grade":"صحيح","chapter_ar":"باب تحريم أكل كلِّ ذي ناب من السباع، وكل ذي مخلب من الطير","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1934:16).","chapter_en":"The Prohibition of Eating Every Predator with Fangs and Every Bird with Talons","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Ibn ʿAbbas said: “The Messenger of Allah ﷺ forbade every predator with fangs and every bird with talons.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":16,"lafz":true},{"key":"muslim","label":"مسلم في الصيد والذبائح","number":1934}],"full":1,"dr":1},{"num":7415,"demo":false,"sanad":"","matn":["عَنِ الْمِقْدَامِ بْنِ مَعْدِيكَرِبَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ أَلاَ لاَ يَحِلُّ ذُو نَابٍ مِنَ السِّبَاعِ وَلاَ الْحِمَارُ الأَهْلِيُّ وَلاَ اللُّقَطَةُ مِنْ مَالِ مُعَاهِدٍ إِلاَّ أَنْ يَسْتَغْنِيَ عَنْهَا وَأَيُّمَا رَجُلٍ ضَافَ قَوْمًا فَلَمْ يَقْرُوهُ فَإِنَّ لَهُ أَنْ يُعْقِبَهُمْ بِمِثْلِ قِرَاهُ."],"takhrij":"صحيح: رواه أبو داود (3804) عن محمد بن المصفّى الحمصي، ثنا محمد بن حرب، عن الزبيدي، عن مروان بن رؤبة التغلبي، عن عبد الرحمن بن أبي عوف، عن المقدام بن معديكرب فذكره.","grade":"صحيح","chapter_ar":"باب تحريم أكل كلِّ ذي ناب من السباع، وكل ذي مخلب من الطير","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (4604, 3804) and Ahmad (17174).","chapter_en":"The Prohibition of Eating Every Predator with Fangs and Every Bird with Talons","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Al-Miqdam ibn Maʿdikarib narrated from the Messenger of Allah ﷺ that he said: “Indeed, no predator with fangs is lawful, nor the domestic donkey, nor lost property from the wealth of a person under covenant unless its owner has no need of it. And any man who is a guest of a people and they do not host him, then he may take from them the equivalent of his hospitality.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4604},{"key":"ahmad","label":"مسند الإمام أحمد","number":17174,"n":17174},{"key":"abudawud","label":"ابو داود","number":3804,"lafz":true}],"full":1,"dr":1},{"num":7416,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَرَّمَ يَوْمَ خَيْبَرَ كُلَّ ذِي نَابٍ مِنَ السِّبَاعِ وَالْمُجَثَّمَةَ وَالْحِمَارَ الإِنْسِيَّ."],"takhrij":"حسن: رواه الترمذي (1795)، وأحمد (8789) من طريق زائدة، عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب تحريم أكل كلِّ ذي ناب من السباع، وكل ذي مخلب من الطير","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1795) and Ahmad (8789). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"The Prohibition of Eating Every Predator with Fangs and Every Bird with Talons","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: On the day of Khaybar, the Messenger of Allah ﷺ forbade every predator with fangs, animals tied up and shot, and the domestic donkey."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1795,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":8789,"n":8789}],"full":1,"dr":1,"rep":[7439]},{"num":7417,"demo":false,"sanad":"","matn":["عَنِ الْعِرْبَاضِ بْنِ سَارِيَةَ قَالَ: نَزَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْبَرَ، وَكَانَ صَاحِبُ خَيْبَرَ مَارِدًا مُنْكَرًا، فَأَقْبَلَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا مُحَمَّدُ، أَلْكُمْ أَنْ تَذْبَحُوا حُمُرَنَا، وَتَأْكُلُوا تَمْرَنَا، وتَدْخُلُوا بُيُوتَنَا، وَتَضْرِبُوا نِسَاءَنَا؟ فَغَضِبَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا عَبْدَ الرَّحْمَنِ، ارْكَبْ فَرَسَكَ فَنَادِ فِي النَّاسِ: إِنَّ الْجَنَّةَ لَا تَحِلُّ إِلَّا لِمُؤْمِنٍ، وَأَنِ اجْتَمِعُوا إِلَى الصَّلَاةِ، فَاجْتَمَعُوا، فَصَلَّى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ قَالَ: إِنَّ اللَّهَ لَمْ يَحِلَّ لَكُمْ أَنْ تَدْخُلُوا بُيُوتَ أَهْلِ الْكِتَابِ إِلَّا بِإِذْنٍ، وَلَا أَكَلَ أَمْوَالِهِمْ، وَلَا ضَرَبَ نِسَائِهِمْ، إِذَا أَعْطَوْكُمُ الَّذِي عَلَيْهِمْ، إِلَّا مَا طَابُوا بِهِ نَفْسًا، أَيَحْسَبُ امْرُؤٌ قَدْ شَبِعَ حَتَّى بَطِنَ، وَهُوَ مُتَّكِئٌ عَلَى أَرِيكَتِهِ، لَا يَظُنُّ أَنَّ اللَّهَ حَرَّمَ شَيْئًا إِلَّا مَا فِي هَذَا الْقُرْآنِ؟ أَلَا وَإِنِّي قَدْ وَاللَّهِ حَرَّمْتُ وَأَمَرْتُ، وَوَعَظْتُ بِأَشْيَاءَ، إِنَّهَا لَمِثْلُ الْقُرْآنِ، أَوْ أَكْثَرُ، أَلَا وَإِنَّهُ لَا يَحِلُّ لَكُمْ مِنَ السِّبَاعِ كُلُّ ذِي نَابٍ، وَلَا الْحُمُرُ الْأَهْلِيَّةُ."],"takhrij":"حسن: رواه الطبراني في الأوسط (7222)، وفي الكبير (18/ (645) مختصرا، وابن أبي عاصم في الآحاد والمثاني (1336)، ومحمد بن نصر المروزي في السنة (ص 116) كلهم من طريق أشعث بن شعبة قال: سمعت أرطاة بن المنذر قال: سمعت حكيم بن عمير، عن العرباض بن سارية فذكره.","grade":"حسن","chapter_ar":"باب تحريم أكل كلِّ ذي ناب من السباع، وكل ذي مخلب من الطير","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Awsat (7222), and in al-Kabir (18/645) in abbreviated form, Ibn Abi ʿAsim in al-Ahad wa al-Mathani (1336), and Muhammad ibn Nasr al-Marwazi in al-Sunnah (p. 116).","chapter_en":"The Prohibition of Eating Every Predator with Fangs and Every Bird with Talons","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Al-ʿIrbad ibn Sariyah said: The Prophet ﷺ stopped at Khaybar, and the leader of Khaybar was rebellious and objectionable. He came to the Prophet ﷺ and said: “O Muhammad, is it lawful for you to slaughter our donkeys, eat our dates, enter our houses, and strike our women?” The Prophet ﷺ became angry and said: “O ʿAbd al-Rahman, mount your horse and announce among the people: Paradise is not lawful except for a believer, and gather for the prayer.” So they gathered, and the Prophet ﷺ prayed. Then he said: “Allah has not made it lawful for you to enter the houses of the People of the Book except with permission, nor to eat their wealth, nor to strike their women, as long as they give you what is due from them, except what they willingly give. Does a man think, after becoming full until his belly is filled, while reclining on his couch, that Allah has not forbidden anything except what is in this Qur’an? Indeed, by Allah, I have forbidden, commanded, and admonished regarding things that are like the Qur’an or even more. Indeed, it is not lawful for you to eat every predator with fangs, nor domestic donkeys.”"]}},"tuhfa":{},"refs":[{"key":"sh28171","label":"الطبراني في الأوسط","number":7222,"lafz":true,"n":7213},{"key":"mujamkabir","label":"وفي الكبير","number":18},{"key":"sh9196","label":"ابن أبي عاصم في الآحاد والمثاني","number":1336},{"key":"rb295","label":"محمد بن نصر المروزي في السنة","number":116},{"key":"sh28171","label":"المعجم الأوسط للطبراني","number":7226,"n":7213}],"full":1,"dr":1},{"num":7418,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ مُتْعَةِ النِّسَاءِ يَوْمَ خَيْبَرَ، وَعَنْ أَكْلِ الْحُمُرِ الإِنْسِيَّةِ."],"takhrij":"متفق عليه: رواه مالك في النكاح (41) عن ابن شهاب، عن عبد الله والحسن ابنيْ محمد بن علي بن أبي طالب، عن أبيهما، عن علي بن أبي طالب فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (41), al-Bukhari (5523), and Muslim (1407:22).","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["ʿAli ibn Abi Talib narrated that the Messenger of Allah ﷺ forbade temporary marriage with women on the day of Khaybar, and forbade eating the meat of domestic donkeys."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":41,"lafz":true},{"key":"bukhari","label":"البخاري","number":5523},{"key":"muslim","label":"مسلم","number":22}],"full":1,"dr":1,"rep":[6462]},{"num":7419,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر: أن رسول الله صلى الله عليه وسلم نهى عن أكل لحوم الحمر الأهلية."],"takhrij":"متفق عليه: رواه البخاري في الذبائح (5521)، ومسلم في الصيد والذبائح (561: 24) كلاهما من طريق عبيد الله، حدثني نافع –وزاد مسلم: وسالم- عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5521) and Muslim (561:24).","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar narrated that the Messenger of Allah ﷺ forbade eating the meat of domestic donkeys."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5521,"lafz":true,"n":5530},{"key":"muslim","label":"مسلم","number":24,"n":425},{"key":"muslim","label":"مسلم في الصيد والذبائح","number":561,"n":5008}],"full":1},{"num":7420,"demo":false,"sanad":"","matn":["عَنْ أَبِي ثَعْلَبَةَ الْخُشَنِيِّ، صَاحِبِ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  أَنَّهُ قَالَ: حَرَّمَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  لُحُومَ الْحُمُرِ الْأَهْلِيَّةِ."],"takhrij":"متفق عليه: رواه البخاري في الصيد والذبائح (5527)، ومسلم في الصيد والذبائح (1936: 23) كلاهما من طريق يعقوب بن إبراهيم بن سعد، حدثنا أبي، عن صالح، عن ابن شهاب، أن أبا إدريس أخبره، ان ثعلبة قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5527) and Muslim (1936:23).","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Abu Thaʿlabah al-Khushani said: The Messenger of Allah ﷺ forbade the meat of domestic donkeys."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5527,"lafz":true},{"key":"muslim","label":"مسلم","number":23},{"key":"muslim","label":"مسلم في الصيد والذبائح","number":1936}],"full":1},{"num":7421,"demo":false,"sanad":"","matn":["عَنِ الشَّيْبَانِيِّ، قَالَ سَأَلْتُ عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى عَنْ لُحُومِ الْحُمُرِ الأَهْلِيَّةِ، فَقَالَ أَصَابَتْنَا مَجَاعَةٌ يَوْمَ خَيْبَرَ وَنَحْنُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَدْ أَصَبْنَا لِلْقَوْمِ حُمُرًا خَارِجَةً مِنَ الْمَدِينَةِ فَنَحَرْنَاهَا فَإِنَّ قُدُورَنَا لَتَغْلِي إِذْ نَادَى مُنَادِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنِ اكْفَئُوا الْقُدُورَ وَلاَ تَطْعَمُوا مِنْ لُحُومِ الْحُمُرِ شَيْئًا فَقُلْتُ حَرَّمَهَا تَحْرِيمَ مَاذَا قَالَ تَحَدَّثْنَا بَيْنَنَا فَقُلْنَا حَرَّمَهَا أَلْبَتَّةَ وَحَرَّمَهَا مِنْ أَجْلِ أَنَّهَا لَمْ تُخَمَّسْ.","وفي رواية: وقال بعضهم: نهى عنها البتة؛ لأنها كانت تأكل العَذِرة."],"takhrij":"متفق عليه: رواه البخاري في فرض الخمس (3155)، ومسلم في الصيد والذبائح (1937: 26) كلاهما من طريق الشيباني به. واللفظ لمسلم، ولفظ البخاري مثله إلا أنه زاد: وسألتُ سعيد بن جبير فقال: \"حرّمها البتة\".","grade":"متفق عليه","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3155) and Muslim (1937:26). The wording is from Muslim. The other narration is from al-Bukhari (4220).","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Al-Shaybani said: I asked ʿAbdullah ibn Abi Awfa about the meat of domestic donkeys. He said: Hunger struck us on the day of Khaybar while we were with the Messenger of Allah ﷺ, and we had captured donkeys belonging to the people outside Madinah, so we slaughtered them. Our pots were boiling when the caller of the Messenger of Allah ﷺ called out: “Overturn the pots, and do not eat anything from the meat of donkeys.” I said: “What kind of prohibition did he forbid it with?” He said: We discussed it among ourselves and said: He forbade it absolutely, and he forbade it because it had not been divided as war booty. In another narration: Some of them said: He forbade it absolutely because it used to eat filth."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3155,"lafz":true},{"key":"muslim","label":"مسلم","number":26},{"key":"bukhari","label":". واللفظ لمسلم. والرواية الأخرى للبخاري","number":4220},{"key":"muslim","label":"مسلم في الصيد والذبائح","number":1937}],"full":1,"dr":1},{"num":7422,"demo":false,"sanad":"","matn":["عن البراء وعبد الله بن أبي أوفى قالا: أصبنا حمرا، فطبخناها، فنادى منادي رسول الله صلى الله عليه وسلم: أكفئوا القدور.","وفي رواية: نهى النبي صلى الله عليه وسلم عن لحوم الحمر."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4221، 4222)، ومسلم في الصيد والذبائح (1938: 28) كلاهما من طريق شعبة، عن عدي بن ثابت، عن البراء وعبد الله بن أبي أوفى قالا: فذكراه. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4221) and Muslim (1938:28). The wording is from Muslim. The other narration is from al-Bukhari (5525).","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Al-Bara’ and ʿAbdullah ibn Abi Awfa said: We captured donkeys and cooked them. Then the caller of the Messenger of Allah ﷺ called out: “Overturn the pots.”","In another narration: “The Prophet ﷺ forbade the meat of donkeys.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4221,"lafz":true},{"key":"muslim","label":"مسلم","number":28},{"key":"bukhari","label":". واللفظ لمسلم. والرواية الأخرى للبخاري","number":5525},{"key":"bukhari","label":"البخاري في المغازي","number":4222},{"key":"muslim","label":"مسلم في الصيد والذبائح","number":1938}],"full":1,"dr":1},{"num":7423,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ أَمَرَنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ خَيْبَرَ أَنْ نُلْقِيَ الْحُمُرَ الأَهْلِيَّةَ نِيئَةً وَنَضِيجَةً، ثُمَّ لَمْ يَأْمُرْنَا بِأَكْلِهِ بَعْدُ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4226)، ومسلم في الصيد (1938: 31) كلاهما من طريق عاصم، عن عامر الشعبي، عن البراء بن عازب فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4226) and Muslim (1938:31).","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Al-Bara’ ibn ʿAzib said: During the expedition of Khaybar, the Prophet ﷺ ordered us to throw away the domestic donkeys, whether raw or cooked, and he never later ordered us to eat it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4226,"lafz":true},{"key":"muslim","label":"مسلم","number":31},{"key":"muslim","label":"مسلم في الصيد","number":1938}],"full":1},{"num":7424,"demo":false,"sanad":"","matn":["عن عَمْرِو قُلْتُ لِجَابِرِ بْنِ زَيْدٍ يَزْعُمُونَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ حُمُرِ الأَهْلِيَّةِ فَقَالَ قَدْ كَانَ يَقُولُ ذَاكَ الْحَكَمُ بْنُ عَمْرٍو الْغِفَارِيُّ عِنْدَنَا بِالْبَصْرَةِ، وَلَكِنْ أَبَى ذَاكَ الْبَحْرُ ابْنُ عَبَّاسٍ وَقَرَأَ {قُلْ لاَ أَجِدُ فِيمَا أُوحِيَ إِلَىَّ مُحَرَّمًا}"],"takhrij":"صحيح: رواه البخاري في الذبائح والصيد (5529) عن علي بن عبد الله، حدثنا سفيان، قال عمرو: قلت لجابر بن زيد: فذكره.","grade":"صحيح","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5529).","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["ʿAmr said: I said to Jabir ibn Zayd: “They claim that the Messenger of Allah ﷺ forbade domestic donkeys.” He said: “Al-Hakam ibn ʿAmr al-Ghifari used to say that among us in Basrah, but that ocean of knowledge, Ibn ʿAbbas, refused that and recited: ‘Say: I do not find in what has been revealed to me anything forbidden…’ [al-Anʿam: 145].”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5529,"lafz":true}],"full":1,"dr":1},{"num":7425,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ لاَ أَدْرِي أَنَهَى عَنْهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ أَجْلِ أَنَّهُ كَانَ حَمُولَةَ النَّاسِ، فَكَرِهَ أَنْ تَذْهَبَ حَمُولَتُهُمْ، أَوْ حَرَّمَهُ فِي يَوْمِ خَيْبَرَ، لَحْمَ الْحُمُرِ الأَهْلِيَّةِ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4227)، ومسلم في الصيد والذبائح (1939: 32) كلاهما من طريق عمر بن حفص بن غياث، حدثنا أبي، عن عاصم، عن عامر (هو الشعبي)، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4227) and Muslim (1939:32).","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿAbbas said: I do not know whether the Messenger of Allah ﷺ forbade it because it was the people’s riding and carrying animals, and he disliked that their mounts and pack animals disappear, or whether he forbade the meat of domestic donkeys on the day of Khaybar."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4227,"lafz":true},{"key":"muslim","label":"مسلم","number":32},{"key":"muslim","label":"مسلم في الصيد والذبائح","number":1939}],"full":1},{"num":7426,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ لَمَّا كَانَ يَوْمُ خَيْبَرَ جَاءَ جَاءٍ فَقَالَ يَا رَسُولَ اللَّهِ أُكِلَتِ الْحُمُرُ. ثُمَّ جَاءَ آخَرُ فَقَالَ يَا رَسُولَ اللَّهِ أُفْنِيَتِ الْحُمُرُ فَأَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَبَا طَلْحَةَ فَنَادَى إِنَّ اللَّهَ وَرَسُولَهُ يَنْهَيَانِكُمْ عَنْ لُحُومِ الْحُمُرِ فَإِنَّهَا رِجْسٌ أَوْ نَجِسٌ. قَالَ فَأُكْفِئَتِ الْقُدُورُ بِمَا فِيهَا."],"takhrij":"متفق عليه: رواه البخاري في الذبائح والصيد (5528)، ومسلم في الصيد والذبائح (1940: 35) كلاهما من طريق محمد بن سيرين، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5528) and Muslim (1940:35). The context is from Muslim. Muslim also narrated it (1940:34) from Anas with the wording: “When the Messenger of Allah ﷺ conquered Khaybar, we captured donkeys outside the village, so we cooked from them. Then the caller of the Messenger of Allah ﷺ called out…” the hadith.","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Malik said: On the day of Khaybar, someone came and said: “O Messenger of Allah, the donkeys have been eaten.” Then another came and said: “O Messenger of Allah, the donkeys have been exhausted.” So the Messenger of Allah ﷺ ordered Abu Talhah, and he called out: “Allah and His Messenger forbid you from the meat of donkeys, for it is filth or impurity.” He said: So the pots were overturned with what was in them."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5528,"lafz":true},{"key":"muslim","label":"مسلم","number":35},{"key":"muslim","label":". والسياق لمسلم. ورواه مسلم أيضاً","number":34},{"key":"muslim","label":"مسلم في الصيد والذبائح","number":1940,"n":5021}],"full":1,"dr":1},{"num":7427,"demo":false,"sanad":"","matn":["عَنْ سَلَمَةَ بْنِ الأَكْوَعِ، قَالَ خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى خَيْبَرَ ثُمَّ إِنَّ اللَّهَ فَتَحَهَا عَلَيْهِمْ فَلَمَّا أَمْسَى النَّاسُ الْيَوْمَ الَّذِي فُتِحَتْ عَلَيْهِمْ أَوْقَدُوا نِيرَانًا كَثِيرَةً فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا هَذِهِ النِّيرَانُ عَلَى أَىِّ شَىْءٍ تُوقِدُونَ قَالُوا عَلَى لَحْمٍ. قَالَ عَلَى أَىِّ لَحْمٍ. قَالُوا عَلَى لَحْمِ حُمُرٍ إِنْسِيَّةٍ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَهْرِيقُوهَا وَاكْسِرُوهَا. فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ أَوْ نُهَرِيقُهَا وَنَغْسِلُهَا قَالَ أَوْ ذَاكَ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4196)، ومسلم في الصيد والذبائح (1802: 33) كلاهما من طريق حاتم بن إسماعيل، عن يزيد بن أبي عُبيد، عن سلمة بن الأكوع قال: فذكره. والسياق لمسلم، وهو عند البخاري بسياق أطول.","grade":"متفق عليه","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4196) and Muslim (1802:33). The context is from Muslim, and it is with al-Bukhari in a longer context.","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Salamah ibn al-Akwaʿ said: We went out with the Messenger of Allah ﷺ to Khaybar. Then Allah granted him victory over it. When evening came on the day it was conquered, the people lit many fires. The Messenger of Allah ﷺ said: “What are these fires? What are you lighting them for?” They said: “For meat.” He said: “What meat?” They said: “Meat of domestic donkeys.” The Messenger of Allah ﷺ said: “Spill it out and break the pots.” A man said: “O Messenger of Allah, should we spill it out and wash them?” He said: “Or that.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4196,"lafz":true},{"key":"muslim","label":"مسلم","number":33},{"key":"muslim","label":"مسلم في الصيد والذبائح","number":1802,"n":5018}],"full":1},{"num":7428,"demo":false,"sanad":"","matn":["عن أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: أَصَبْنَا سَبَايَا يَوْمَ حُنَيْنٍ، فَكُنَّا نَعْزِلُ عَنْهُنَّ، نَلْتَمِسُ أَنْ نُفَادِيَهُنَّ مِنْ أَهْلِهِنَّ، فَقَالَ بَعْضُنَا لِبَعْضٍ: تَفْعَلُونَ هَذَا وَفِيكُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ ائْتُوهُ، فَسَلُوهُ، فَأَتَيْنَاهُ أَوْ ذَكَرْنَا ذَلِكَ لَهُ قَالَ: مَا مِنْ كُلِّ الْمَاءِ يَكُونُ الْوَلَدُ، إِذَا قَضَى اللَّهُ أَمْرًا كَانَ وَمَرَرْنَا بِالْقُدُورِ، وَهِيَ تَغْلِي، فَقَالَ لَنَا: مَا هَذَا اللَّحْمُ؟ فَقُلْنَا: لَحْمُ حُمُرٍ. فَقَالَ لَنَا: أَهْلِيَّةٍ أَوْ وَحْشِيَّةٍ؟، فَقُلْنَا لَهُ: بَلْ أَهْلِيَّةٍ. قَالَ: فَقَالَ لَنَا: فَاكْفِئُوهَا. قَالَ: فَكَفَأْنَاهَا، وَإِنَّا لَجِيَاعٌ نَشْتَهِيهِ قَالَ: وَكُنَّا نُؤْمَرُ أَنْ نُوكِئَ الْأَسْقِيَةَ."],"takhrij":"حسن: رواه الإمام أحمد (11778) عن أبي نعيم (هو الفضل بن دكين) ثنا يونس، حدثني أبو الوداك، قال: حدثني أبو سعيد فذكره. ورواه ابن أبي شيبة (24821)، وأبو يعلى (1183) من طريق يونس به بقصة الحمر الأهلية.","grade":"حسن","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (11778), Ibn Abi Shaybah (24821), and Abu Yaʿla (1183), the latter two with the report concerning the domestic donkeys.","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: We captured female prisoners on the day of Hunayn, and we practiced withdrawal with them, hoping to ransom them back to their families. Some of us said to others: “Are you doing this while the Messenger of Allah ﷺ is among you? Go to him and ask him.” So we came to him, or we mentioned that to him. He said: “Not from every emission does a child come. When Allah decrees a matter, it happens.” We passed by pots that were boiling, and he said to us: “What is this meat?” We said: “Donkey meat.” He said to us: “Domestic or wild?” We said to him: “Rather, domestic.” He said to us: “Overturn them.” He said: So we overturned them, though we were hungry and desired it. He said: And we used to be commanded to tie the mouths of water skins."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"الإمام أحمد","number":11778,"lafz":true},{"key":"sh9944","label":"ابن أبي شيبة","number":24821},{"key":"sh12520","label":"أبو يعلى","number":1183}],"full":1,"dr":1},{"num":7429,"demo":false,"sanad":"","matn":["عن ثَعْلَبَةَ بْنِ الْحَكَمِ قَالَ: أَسَرَنِي أَصْحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا يَوْمَئِذٍ شَابٌّ فَسَمِعْتُهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنِ النُّهْبَةِ وَأَمَرَ بِالْقُدُورِ فَأُكْفِئَتْ مِنْ لُحُومِ الْحُمُرِ الْأَهْلِيَّةِ."],"takhrij":"حسن: رواه الطبراني في الكبير (1375)، وأبو نعيم في معرفة الصحابة (1382) من طريق شعبة، عن سماك بن حرب، عن ثعلبة بن الحكم فذكره.","grade":"حسن","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (1375) and Abu Nuʿaym in Maʿrifat al-Sahabah (1382).","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Thaʿlabah ibn al-Hakam said: The Companions of the Messenger of Allah ﷺ captured me when I was a young man. I was with them when he forbade plunder and ordered the pots to be overturned because of the meat of domestic donkeys."]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":1375,"lafz":true},{"key":"sh10490","label":"أبو نعيم في معرفة الصحابة","number":1382,"n":1388}],"full":1,"dr":1},{"num":7430,"demo":false,"sanad":"","matn":["عن كَعْبِ بن مَالِكٍ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُتْعَةِ، وَعَنْ لُحُومِ الْحُمُرِ الْأَهْلِيَّةِ."],"takhrij":"حسن: رواه الطبراني في الكبير ( 19/ 68) عن محمد بن عبد الله الحضرمي، ثنا واصل بن عبد الأعلى، ثنا محمد بن فضيل، عن منصور بن دينار، عن الزهري، عن عبد الله بن كعب بن مالك، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب تحريم لحوم الحمر الإنسية","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (19/68).","chapter_en":"The Prohibition of the Meat of Domestic Donkeys","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Kaʿb ibn Malik said: The Messenger of Allah ﷺ forbade temporary marriage and the meat of domestic donkeys."]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":19,"lafz":true}],"full":1,"dr":1},{"num":7431,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ ذَبَحْنَا يَوْمَ خَيْبَرَ الْخَيْلَ وَالْبِغَالَ وَالْحَمِيرَ فَنَهَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْبِغَالِ وَالْحَمِيرِ وَلَمْ يَنْهَنَا عَنِ الْخَيْلِ."],"takhrij":"صحيح: رواه أبوداود (3789)، وأحمد (14840)، وابن حبان (5272)، والحاكم (4/235) من طرق عن حماد بن سلمة، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن أكل لحوم البغال","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3789), Ahmad (14840), Ibn Hibban (5272), and al-Hakim (4/235).","chapter_en":"The Prohibition of Eating Mule Meat","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: On the day of Khaybar, we slaughtered horses, mules, and donkeys. The Messenger of Allah ﷺ forbade us from mules and donkeys, but he did not forbid us from horses."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3789,"lafz":true},{"key":"ibnhibban","label":"ابن حبان","number":5272},{"key":"hakim","label":"الحاكم","number":4},{"key":"ahmad","label":"مسند الإمام أحمد","number":14840,"n":14840}],"full":1,"dr":1,"rep":[7329]},{"num":7432,"demo":false,"sanad":"","matn":["عَنْ عَطَاءٍ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ كُنَّا نَأْكُلُ لُحُومَ الْخَيْلِ. قُلْتُ فَالْبِغَالُ قَالَ لاَ."],"takhrij":"صحيح: رواه النسائي (4333)، وابن ماجه (3197) من طريق عبد الكريم الجزري، عن عطاء، عن جابر فذكره. وإسناده صيح، وعطاء هو ابن أبي رباح.","grade":"صحيح","chapter_ar":"باب النهي عن أكل لحوم البغال","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (4333) and Ibn Majah (3197).","chapter_en":"The Prohibition of Eating Mule Meat","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["ʿAta’ narrated from Jabir: We used to eat horse meat. I said: “Mules?” He said: “No.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4333,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":3197}],"full":1},{"num":7433,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ أَكْلِ الْجَلاَّلَةِ وَأَلْبَانِهَا."],"takhrij":"صحيح: رواه أبوداود (3785)، والترمذي (1824)، وابن ماجه (3189) من طرق عن محمد بن إسحاق، عن ابن أبي نجيح، عن مجاهد، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب كراهية أكل لحوم الجلالة وشرب ألبانها","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3785), al-Tirmidhi (1824), who graded it hasan, and Ibn Majah (3189).","chapter_en":"The Dislike of Eating the Meat of Animals That Feed on Filth and Drinking Their Milk","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ forbade eating animals that feed on filth and drinking their milk."]},"buhuth":{"en":["His statement, “animals that feed on filth,” refers to animals that eat dung and excrement. The word originally refers to droppings, then it was borrowed and used for excrement."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3785,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1824},{"key":"ibnmajah","label":"ابن ماجه","number":3189}],"full":1,"dr":1},{"num":7434,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لَبَنِ الْجَلاَّلَةِ."],"takhrij":"صحيح: رواه أبوداود (3786)، والترمذي (1825)، وابن ماجه (1825)، والنسائي (4448)، وأحمد (1989، 2161، 2671) وصحّحه ابن حبان (5399) والحاكم (2/102) كلهم من طريق قتادة، عن عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب كراهية أكل لحوم الجلالة وشرب ألبانها","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3786), al-Tirmidhi (1825), al-Nasa’i (4448), and Ahmad (1989, 2161, 2671). It was authenticated by Ibn Hibban (5399) and al-Hakim (2/102).","chapter_en":"The Dislike of Eating the Meat of Animals That Feed on Filth and Drinking Their Milk","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbas said: The Prophet ﷺ forbade the milk of animals that feed on filth."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3786,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1825,"n":1888},{"key":"nasai","label":"النسائي","number":4448,"n":4505},{"key":"ibnhibban","label":"صححه ابن حبان","number":5399},{"key":"hakim","label":"الحاكم","number":2},{"key":"ahmad","label":"مسند الإمام أحمد","number":1989,"n":1988},{"key":"ibnmajah","label":"ابن ماجه","number":1825,"n":1743},{"key":"ahmad","label":"احمد","number":2161},{"key":"ahmad","label":"احمد","number":2671}],"full":1,"dr":1},{"num":7435,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُجَثَّمَةِ وَالْجَلَّالَةِ."],"takhrij":"صحيح: رواه الحاكم (2/35)، والبيهقي (9/333) من طريق حماد بن سلمة، عن أيوب، عن عكرمة، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب كراهية أكل لحوم الجلالة وشرب ألبانها","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Hakim (2250) and al-Bayhaqi (9/333). Al-Bayhaqi added: “and drinking directly from the mouth of a water skin.”","chapter_en":"The Dislike of Eating the Meat of Animals That Feed on Filth and Drinking Their Milk","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ forbade animals tied up and shot, and animals that feed on filth."]}},"tuhfa":{},"refs":[{"key":"kubrabayhaqi","label":"البيهقي","number":9},{"key":"hakim","label":"المستدرك على الصحيحين","number":2250,"n":2242,"lafz":true}],"full":1,"dr":1},{"num":7436,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عمرو قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ خَيْبَرَ عَنْ لُحُومِ الْحُمُرِ الأَهْلِيَّةِ، وَعَنِ الْجَلاَّلَةِ، عَنْ رُكُوبِهَا، وَأَكْلِ لَحْمِهَا."],"takhrij":"حسن: رواه أبو داود (3811)، وأحمد (7039)، والحاكم (2/103) من طرق عن وهيب، حدثنا ابن طاوس، عن عمرو بن شعيب، عن أبيه، عن جده فذكره. وإسناده حسن من أجل عمرو بن شعيب، فإنه حسن الحديث.","grade":"حسن","chapter_ar":"باب كراهية أكل لحوم الجلالة وشرب ألبانها","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3811), Ahmad (7039), and al-Hakim (2498).","chapter_en":"The Dislike of Eating the Meat of Animals That Feed on Filth and Drinking Their Milk","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr said: On the day of Khaybar, the Messenger of Allah ﷺ forbade the meat of domestic donkeys, and he forbade animals that feed on filth: riding them and eating their meat."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3811,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":7039,"n":7039},{"key":"hakim","label":"المستدرك على الصحيحين","number":2498,"n":2487}],"full":1,"dr":1},{"num":7437,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْجَلَّالَةِ أَنْ يُؤْكَلَ لَحْمُهَا، أَوْ يُشْرَبَ لَبَنُهَا."],"takhrij":"حسن: رواه ابن أبي شيبة (8/147) عن شبابة (هو ابن سوّار)، ثنا مغيرة بن مسلم، عن أبي الزبير، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب كراهية أكل لحوم الجلالة وشرب ألبانها","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abi Shaybah (8/147).","chapter_en":"The Dislike of Eating the Meat of Animals That Feed on Filth and Drinking Their Milk","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":7,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ forbade eating the meat of animals that feed on filth or drinking their milk."]},"buhuth":{"en":["Ibn Hibban said: An animal that feeds on filth is one whose feed is mostly filth. If most of its feed is pure and good things, then it is not considered an animal that feeds on filth. Al-Ihsan (12/221).","Al-Khattabi said: “People differed regarding eating the meat and milk of animals that feed on filth. Abu Hanifah and his companions, al-Shafiʿi, and Ahmad ibn Hanbal disliked that and said: It should not be eaten until it is confined for some days and fed other feed. When its meat becomes good, then there is no harm in eating it.”"]}},"tuhfa":{},"refs":[{"key":"sh9944","label":"ابن أبي شيبة","number":8,"lafz":true},{"key":"sh9944","label":"المصنف لابن أبي شيبة","number":24604,"n":24587}],"full":1,"dr":1},{"num":7438,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْمُجَثَّمَةِ، وَعَنْ لَبَنِ الْجَلالَةِ، وَعَنِ الشُّرْبِ مِنْ فِي السِّقَاءِ."],"takhrij":"صحيح: رواه الترمذي (1825)، والنسائي (4448)، وأحمد (2162، 2671)، وابن حبان (5399) كلهم من طريق قتادة، عن عكرمة؟، عن ابن عباس فذكره. ورواه أبو داود من هذا الوجه مختصرا في النهي عن الجلالة، وقد سبق.","grade":"صحيح","chapter_ar":"باب النهي عن أكل المجثَّمة","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1825), al-Nasa’i (4448), Ahmad (2671, 2162), and Ibn Hibban (5399). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"The Prohibition of Eating Animals Tied Up and Shot","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Ibn ʿAbbas said: The Prophet ﷺ forbade animals tied up and shot, the milk of animals that feed on filth, and drinking directly from the mouth of a water skin."]},"buhuth":{"en":["His statement, “he forbade animals tied up and shot,” refers to any animal set up and shot until it is killed. This usage is common regarding birds, rabbits, and similar animals that crouch or remain attached to the ground, as mentioned in al-Nihayah. If it dies in that manner, eating it is forbidden."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1825,"lafz":true},{"key":"nasai","label":"النسائي","number":4448},{"key":"ibnhibban","label":"ابن حبان","number":5399},{"key":"ahmad","label":"مسند الإمام أحمد","number":2671,"n":2671},{"key":"ahmad","label":"احمد","number":2162,"n":2161}],"full":1,"dr":1},{"num":7439,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَرَّمَ يَوْمَ خَيْبَرَ كُلَّ ذِي نَابٍ مِنَ السِّبَاعِ وَالْمُجَثَّمَةَ وَالْحِمَارَ الإِنْسِيَّ."],"takhrij":"صحيح: رواه الترمذي (1795)، وأحمد (8789) من طريق زائدة، عن عمرو بن محمد، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن أكل المجثَّمة","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1795) and Ahmad (8789). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"The Prohibition of Eating Animals Tied Up and Shot","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah narrated that on the day of Khaybar, the Messenger of Allah ﷺ forbade every predator with fangs, animals tied up and shot, and the domestic donkey."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1795,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":8789,"n":8789}],"full":1,"dr":1,"rep":[7416]},{"num":7440,"demo":false,"sanad":"","matn":["عَنْ أَبِي ثَعْلَبَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ تَحِلُّ النُّهْبَى وَلاَ يَحِلُّ مِنَ السِّبَاعِ كُلُّ ذِي نَابٍ وَلاَ تَحِلُّ الْمُجْثَّمَةُ."],"takhrij":"حسن: رواه النسائي (4326) واللفظ له، وأحمد (17741)، والطبراني في \"الكبير\" (22/216) كلّهم من طريق بقية بن الوليد، عن بحير بن سعد، عن خالد بن معدان، عن جبير بن نفير، عن أبي ثعلبة، فذكره. وسياق أحمد والطبراني أطول.","grade":"حسن","chapter_ar":"باب النهي عن أكل المجثَّمة","chapter_ur":"","part_ar":"كتاب الأطعمة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4326), Ahmad (17741), and al-Tabarani in al-Kabir (22/216).","chapter_en":"The Prohibition of Eating Animals Tied Up and Shot","part_en":"Book of Foods","group_ar":"جموع ما جاء في الأطعمة المحرمة","group_en":"Collection of What Has Been Reported Concerning Forbidden Foods","part_no":40,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Abu Thaʿlabah al-Khushani said: The Messenger of Allah ﷺ said: “Plunder is not lawful, every predator with fangs is not lawful, and an animal tied up and shot is not lawful.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4326,"lafz":true,"n":4326},{"key":"mujamkabir","label":"الطبراني في الكبير","number":22},{"key":"ahmad","label":"مسند الإمام أحمد","number":17741,"n":17741}],"full":1,"dr":1},{"num":7441,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُمْ أَنَّهُ قَالَ أَصَبْتُ شَارِفًا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَغْنَمٍ يَوْمَ بَدْرٍ قَالَ وَأَعْطَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَارِفًا أُخْرَى، فَأَنَخْتُهُمَا يَوْمًا عِنْدَ بَابِ رَجُلٍ مِنَ الأَنْصَارِ، وَأَنَا أُرِيدُ أَنْ أَحْمِلَ عَلَيْهِمَا إِذْخِرًا لأَبِيعَهُ، وَمَعِي صَائِغٌ مِنْ بَنِي قَيْنُقَاعَ فَأَسْتَعِينَ بِهِ عَلَى وَلِيمَةِ فَاطِمَةَ، وَحَمْزَةُ بْنُ عَبْدِ الْمُطَّلِبِ يَشْرَبُ فِي ذَلِكَ الْبَيْتِ مَعَهُ قَيْنَةٌ، فَقَالَتْ أَلاَ يَا حَمْزَ لِلشُّرُفِ النِّوَاءِ. فَثَارَ إِلَيْهِمَا حَمْزَةُ بِالسَّيْفِ، فَجَبَّ أَسْنِمَتَهُمَا، وَبَقَرَ خَوَاصِرَهُمَا، ثُمَّ أَخَذَ مِنْ أَكْبَادِهِمَا. قُلْتُ لاِبْنِ شِهَابٍ وَمِنَ السَّنَامِ قَالَ قَدْ جَبَّ أَسْنِمَتَهُمَا فَذَهَبَ بِهَا. قَالَ ابْنُ شِهَابٍ قَالَ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ فَنَظَرْتُ إِلَى مَنْظَرٍ أَفْظَعَنِي فَأَتَيْتُ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعِنْدَهُ زَيْدُ بْنُ حَارِثَةَ فَأَخْبَرْتُهُ الْخَبَرَ فَخَرَجَ وَمَعَهُ زَيْدٌ، فَانْطَلَقْتُ مَعَهُ، فَدَخَلَ عَلَى حَمْزَةَ فَتَغَيَّظَ عَلَيْهِ فَرَفَعَ حَمْزَةُ بَصَرَهُ وَقَالَ هَلْ أَنْتُمْ إِلاَّ عَبِيدٌ لآبَائِي فَرَجَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُقَهْقِرُ حَتَّى خَرَجَ عَنْهُمْ، وَذَلِكَ قَبْلَ تَحْرِيمِ الْخَمْرِ."],"takhrij":"متفق عليه: رواه البخاري في المساقاة (2375)، ومسلم في الأشربة (1979: 1) كلاهما من طريق ابن جريج، حدثني ابن شهاب، عن علي بن حسين بن علي، عن أبيه حسين بن علي، عن علي بن أبي طالب فذكره.","grade":"متفق عليه","chapter_ar":"باب التدرج في تحريم الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2375) and Muslim (1979:1).","chapter_en":"The Gradual Prohibition of Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿAli ibn Abi Talib said: I received an old she-camel along with the Messenger of Allah ﷺ from the spoils on the day of Badr. He said: The Messenger of Allah ﷺ also gave me another old she-camel. One day, I made them kneel at the door of a man from the Helpers, intending to carry sweet rush on them to sell it. With me was a goldsmith from Banu Qaynuqaʿ, so that I could use him to help with the wedding feast of Fatimah. Hamzah ibn ʿAbd al-Muttalib was drinking in that house, and there was a singing girl with him. She said: “O Hamzah, go to the fat old she-camels.” Hamzah rushed to the two camels with a sword, cut off their humps, slit open their flanks, and took from their livers. I said to Ibn Shihab: “And from the hump?” He said: He had cut off their humps and taken them away. Ibn Shihab said: ʿAli said: I looked at a sight that horrified me, so I came to the Prophet of Allah ﷺ while Zayd ibn Harithah was with him, and I informed him of what had happened. He went out with Zayd, and I went with him. He entered upon Hamzah and became angry with him. Hamzah raised his gaze and said: “Are you anything but slaves of my fathers?” The Messenger of Allah ﷺ withdrew, walking backward, until he left them. This was before wine was prohibited."]},"buhuth":{"en":["The word “old she-camel” means an aged she-camel. The phrase “fat old she-camels” refers to plump old she-camels. There was no sin on Hamzah for what he did because he was intoxicated, but he was still liable to compensate for what he destroyed, even if he was intoxicated or insane. In the book of ʿUmar ibn Shabbah, it is mentioned that the Prophet ﷺ made Hamzah pay compensation for the two camels."]},"intro":{"ar":["قال الله تعالى:","(يَسْأَلُونَكَ عَنِ الْخَمْرِ وَالْمَيْسِرِ قُلْ فِيهِمَا إثْمٌ كَبِيرٌ وَمَنَافِعُ لِلنَّاسِ وَإثْمُهُمَا أَكْبَرُ مِن نَفْعِهِمَا) [سورة البقرة: ٢١٩]","وقال تعالى:","(يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَقْرَبُوا الصَّلَاةَ وَأَنْتُمْ سُكَارَىٰ حَتَّىٰ تَعْلَمُوا مَا تَقُولُونَ) [سورة النساء: ٤٣]"],"en":["Allah the Exalted said:","“They ask you about wine and gambling. Say: In them is great sin and benefits for people, but their sin is greater than their benefit.” [Surah al-Baqarah: 219]","And He said:","“O you who believe, do not approach prayer while you are intoxicated until you know what you are saying.” [Surah al-Nisa’: 43]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2375,"lafz":true},{"key":"muslim","label":"مسلم","number":1},{"key":"muslim","label":"مسلم في الاشربه","number":1979}],"full":1,"dr":1},{"num":7442,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ بِالْمَدِينَةِ قَالَ يَا أَيُّهَا النَّاسُ إِنَّ اللَّهَ تَعَالَى يُعَرِّضُ بِالْخَمْرِ وَلَعَلَّ اللَّهَ سَيُنْزِلُ فِيهَا أَمْرًا فَمَنْ كَانَ عِنْدَهُ مِنْهَا شَىْءٌ فَلْيَبِعْهُ وَلْيَنْتَفِعْ بِهِ. قَالَ فَمَا لَبِثْنَا إِلاَّ يَسِيرًا حَتَّى قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ اللَّهَ تَعَالَى حَرَّمَ الْخَمْرَ فَمَنْ أَدْرَكَتْهُ هَذِهِ الآيَةُ وَعِنْدَهُ مِنْهَا شَىْءٌ فَلاَ يَشْرَبْ وَلاَ يَبِعْ. قَالَ فَاسْتَقْبَلَ النَّاسُ بِمَا كَانَ عِنْدَهُ مِنْهَا فِي طَرِيقِ الْمَدِينَةِ فَسَفَكُوهَا."],"takhrij":"صحيح: رواه مسلم في المساقاة (1578: 67) عن عبيد الله بن عمر القواريري، حدثنا عبد الأعلى بن عبد الأعلى أبو همام، حدثنا سعيد الجريري، عن أبي نضرة، عن أبي سعيد الخدري قال: فذكره.","grade":"صحيح","chapter_ar":"باب التدرج في تحريم الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1578:67).","chapter_en":"The Gradual Prohibition of Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: I heard the Messenger of Allah ﷺ delivering a sermon in Madinah. He said: “O people! Allah the Exalted is alluding to wine, and perhaps Allah will soon reveal a ruling concerning it. Whoever has some of it should sell it and benefit from it.” He said: We remained only a short while until the Prophet ﷺ said: “Allah the Exalted has forbidden wine. Whoever this verse reaches while he has any of it should neither drink it nor sell it.” He said: The people then came out with whatever wine they had into the roads of Madinah and poured it away."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":67,"lafz":true},{"key":"muslim","label":"مسلم في المساقاه","number":1578}],"full":1,"rep":[5785]},{"num":7443,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بْنِ الْخَطَّابِ، قَالَ لَمَّا نَزَلَ تَحْرِيمُ الْخَمْرِ قَالَ عُمَرُ اللَّهُمَّ بَيِّنْ لَنَا فِي الْخَمْرِ بَيَانًا شِفَاءً فَنَزَلَتِ الآيَةُ الَّتِي فِي الْبَقَرَةِ ﴿يَسْأَلُونَكَ عَنِ الْخَمْرِ وَالْمَيْسِرِ قُلْ فِيهِمَا إِثْمٌ كَبِيرٌ﴾ [سورة البقرة: 219] } الآيَةَ قَالَ فَدُعِيَ عُمَرُ فَقُرِئَتْ عَلَيْهِ قَالَ اللَّهُمَّ بَيِّنْ لَنَا فِي الْخَمْرِ بَيَانًا شِفَاءً فَنَزَلَتِ الآيَةُ الَّتِي فِي النِّسَاءِ ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لاَ تَقْرَبُوا الصَّلاَةَ وَأَنْتُمْ سُكَارَى﴾ [سورة النساء: 43] } فَكَانَ مُنَادِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أُقِيمَتِ الصَّلاَةُ يُنَادِي أَلاَ لاَ يَقْرَبَنَّ الصَّلاَةَ سَكْرَانُ فَدُعِيَ عُمَرُ فَقُرِئَتْ عَلَيْهِ فَقَالَ اللَّهُمَّ بَيِّنْ لَنَا فِي الْخَمْرِ بَيَانًا شِفَاءً فَنَزَلَتْ هَذِهِ الآيَةُ { فَهَلْ أَنْتُمْ مُنْتَهُونَ } قَالَ عُمَرُ انْتَهَيْنَا."],"takhrij":"صحيح: رواه أبو داود (3670)، والترمذي (3049)، والنسائي (5540)، وأحمد (378)، والحاكم (4/143)، والضياء المقدسي في المختارة (256) كلهم من طرق عن إسرائيل بن يونس بن أبي إسحاق السبيعي، عن أبي إسحاق، عن أبي ميسرة عمرو بن شرحبيل، عن عمر فذكره.","grade":"صحيح","chapter_ar":"باب التدرج في تحريم الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3670), al-Tirmidhi (3049), al-Nasa’i (5540), Ahmad (378), al-Hakim (4/143), and al-Diya’ al-Maqdisi in al-Mukhtarah (256).","chapter_en":"The Gradual Prohibition of Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿUmar ibn al-Khattab said: When the prohibition of wine was revealed, ʿUmar said: “O Allah, give us a clear and decisive explanation concerning wine.” Then the verse in al-Baqarah was revealed: “They ask you about wine and gambling. Say: In them is sin…” the verse. He said: ʿUmar was called and it was recited to him. He said: “O Allah, give us a clear and decisive explanation concerning wine.” Then the verse in al-Nisa’ was revealed: “O you who believe, do not approach prayer while you are intoxicated.” When the caller of the Messenger of Allah ﷺ announced the establishment of prayer, he would call out: “Let no intoxicated person come near the prayer.” Then ʿUmar was called and it was recited to him. He said: “O Allah, give us a clear and decisive explanation concerning wine.” Then this verse was revealed: “So will you then desist?” [Surah al-Ma’idah: 91] ʿUmar said: “We have desisted.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3670,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":3049},{"key":"nasai","label":"النسائي","number":5540},{"key":"hakim","label":"الحاكم","number":4},{"key":"sh10480","label":"الضياء المقدسي في المختارة","number":256},{"key":"ahmad","label":"مسند الإمام أحمد","number":378,"n":378}],"full":1,"dr":1},{"num":7444,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب أن رجلا من الأنصار دعاه، وعبد الرحمن بن عوف فسقـاهما قبل أن تحرَّم الخمر، فأمّهم عليٌّ في المغرب، وقرأ قُلْ يَا أَيُّهَا الْكَافِرُونَ فخلط فيهما فنزلت: ﴿لَا تَقْرَبُوا الصَّلَاةَ وَأَنْتُمْ سُكَارَى حَتَّى تَعْلَمُوا مَا تَقُولُونَ﴾ [سورة النساء: 43]."],"takhrij":"صحيح: رواه أبو داود (3671)، والترمذي (3026)، والحاكم (2/207) كلهم من طريق عطاء بن السائب، عن أبي عبد الرحمن السلمي، عن علي بن أبي طالب فذكره.","grade":"صحيح","chapter_ar":"باب التدرج في تحريم الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3671), al-Tirmidhi (3026), and al-Hakim (2/207).","chapter_en":"The Gradual Prohibition of Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿAli ibn Abi Talib narrated that a man from the Helpers invited him and ʿAbd al-Rahman ibn ʿAwf and served them drink before wine was prohibited. ʿAli led them in the sunset prayer and recited: “Say: O disbelievers,” but mixed up the recitation. Then this was revealed: “Do not approach prayer while you are intoxicated until you know what you are saying.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3671,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":3026},{"key":"hakim","label":"الحاكم","number":2}],"full":1,"dr":1},{"num":7445,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: كُنْتُ أَسْقِي أَبَا عُبَيْدَةَ بْنَ الْجَرَّاحِ، وَأَبَا طَلْحَةَ الأَنْصَارِيَّ، وأبي بْنَ كَعْبٍ شَرَابًا مِنْ فَضِيخٍ وتمر، قَالَ: فَجَاءَهُمْ آتٍ فَقَالَ: إِنَّ الْخَمْرَ قَدْ حُرِّمَتْ، فَقَالَ أَبُو طَلْحَةَ: يَا أَنَسُ! قمْ إِلَى هَذِهِ الْجِرَارِ فَاكْسِرْهَا، قَالَ: فَقُمْتُ إِلَى مِهْرَاسٍ لَنَا فَضَرَبْتُهَا بِأَسْفَلِهِ حَتَّى تكسرت."],"takhrij":"متفق عليه: رواه مالك في الأشربة (13) عن إسحاق بن عبد الله بن أبي طلحة، عن أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تحريم الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (13), al-Bukhari (5582), and Muslim (1980:9).","chapter_en":"What Has Been Reported Concerning the Prohibition of Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Malik said: I was serving Abu ʿUbaydah ibn al-Jarrah, Abu Talhah al-Ansari, and Ubayy ibn Kaʿb a drink made from unripe dates and dates. He said: Then someone came to them and said: “Wine has been prohibited.” Abu Talhah said: “O Anas, go to these jars and break them.” He said: So I went to a mortar we had and struck them with its lower part until they broke."]},"intro":{"ar":["قال اللّٰه تعالى:","(يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالْأَنْصَابُ وَالْأَزْلَامُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ ۝ إِنَّمَا يُرِيدُ الشَّيْطَانُ أَنْ يُوقِعَ بَيْنَكُمُ الْعَدَاوَةَ وَالْبَغْضَاءَ فِي الْخَمْرِ وَالْمَيْسِرِ وَيَصُدَّكُمْ عَنْ ذِكْرِ اللَّهِ وَعَنِ الصَّلَاةِ فَهَلْ أَنْتُمْ مُنْتَهُونَ) [المائدة: ٩٠-٩١]"],"en":["Allah the Exalted said:","“O you who believe, wine, gambling, stone altars, and divining arrows are only filth from the work of Satan, so avoid it so that you may succeed. Satan only wants to cause enmity and hatred between you through wine and gambling and to prevent you from the remembrance of Allah and from prayer. So will you then desist?” [al-Ma’idah: 90–91]"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":13,"lafz":true},{"key":"bukhari","label":"البخاري","number":5582},{"key":"muslim","label":"مسلم","number":9}],"full":1,"dr":1},{"num":7446,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بن وعلة -رجل من أَهْلِ مِصْرَ- أَنَّهُ سَأَلَ عبدالله ابْنُ عَبَّاسٍ عَمَّا يُعْصَرُ مِنْ الْعِنَبِ؟ فَقَالَ ابْنُ عَبَّاسٍ: إِنَّ رَجُلًا أَهْدَى لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَاوِيَةَ خَمْرٍ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : هَلْ عَلِمْتَ أَنَّ اللَّهَ قَدْ حَرَّمَهَا؟ قَالَ: لَا، فسارَّ إِنْسَانًا، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : بِمَ سَارَرْتَهُ؟ فَقَالَ: أَمَرْتُهُ بِبَيْعِهَا، فَقَالَ: إِنَّ الَّذِي حرّم شُرْبَهَا حَرَّمَ بَيْعَهَا، قَالَ: فَفَتَحَ المزاد حَتَّى ذَهَبَ مَا فِيهَا."],"takhrij":"صحيح: رواه مسلم في المساقاة والمزارعة (1579: 68) عن سويد بن سعيد، حدثنا حفص بن ميسرة، عن زيد بن أسلم، عن عبد الرحمن بن وعلة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تحريم الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1579:68).","chapter_en":"What Has Been Reported Concerning the Prohibition of Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["ʿAbd al-Rahman ibn Waʿlah, a man from Egypt, asked ʿAbdullah ibn ʿAbbas about what is pressed from grapes. Ibn ʿAbbas said: A man gifted the Messenger of Allah ﷺ a container of wine. The Messenger of Allah ﷺ said to him: “Did you know that Allah has forbidden it?” He said: “No.” Then he whispered to another person. The Messenger of Allah ﷺ said to him: “What did you whisper to him?” He said: “I told him to sell it.” He said: “The One who forbade drinking it also forbade selling it.” He said: So he opened the container until everything in it flowed away."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":68,"lafz":true},{"key":"muslim","label":"مسلم في المساقاه والمزارعه","number":1579}],"full":1},{"num":7447,"demo":false,"sanad":"","matn":["عن سَعْدِ بن أَبِي وَقَّاصٍ قَالَ: أَتَيْتُ عَلَى نَفَرٍ مِنَ الأَنْصَارِ وَالْمُهَاجِرِينَ فَقَالُوا تَعَالَ نُطْعِمْكَ وَنَسْقِيكَ خَمْرًا. وَذَلِكَ قَبْلَ أَنْ تُحَرَّمَ الْخَمْرُ - قَالَ - فَأَتَيْتُهُمْ فِي حَشٍّ - وَالْحَشُّ الْبُسْتَانُ - فَإِذَا رَأْسُ جَزُورٍ مَشْوِيٌّ عِنْدَهُمْ وَزِقٌّ مِنْ خَمْرٍ - قَالَ - فَأَكَلْتُ وَشَرِبْتُ مَعَهُمْ - قَالَ - فَذُكِرَتِ الأَنْصَارُ وَالْمُهَاجِرُونَ عِنْدَهُمْ فَقُلْتُ الْمُهَاجِرُونَ خَيْرٌ مِنَ الأَنْصَارِ - قَالَ - فَأَخَذَ رَجُلٌ أَحَدَ لَحْيَىِ الرَّأْسِ فَضَرَبَنِي بِهِ فَجَرَحَ بِأَنْفِي فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرْتُهُ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ فِيَّ - يَعْنِي نَفْسَهُ - شَأْنَ الْخَمْرِ ﴿إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالأَنْصَابُ وَالأَزْلاَمُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ﴾ [سورة المائدة: 90]}"],"takhrij":"صحيح: رواه مسلم في فضائل الصحابة (1748) من طريق الحسن بن موسى، ثنا وهير، ثنا سماك بن حرب، ثنا مصعب بن سعد، عن أبيه فذكره في حديث طويل.","grade":"صحيح","chapter_ar":"باب ما جاء في تحريم الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in the Virtues of the Companions (1748) through al-Hasan ibn Musa, from Zuhayr, from Simak ibn Harb, from Musʿab ibn Saʿd, from his father, who mentioned it in a long hadith.","chapter_en":"What Has Been Reported Concerning the Prohibition of Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Saʿd ibn Abi Waqqas said: “… I came upon a group of the Helpers and the Emigrants, and they said: ‘Come, we will feed you and give you wine to drink.’ This was before wine was prohibited. He said: I came to them in a garden, and there was the roasted head of a slaughtered camel with them and a skin of wine. He said: I ate and drank with them. He said: I mentioned the Helpers and the Emigrants in their presence, and I said: ‘The Emigrants are better than the Helpers.’ He said: A man took one of the jawbones of the head and struck me with it, wounding my nose. I came to the Messenger of Allah ﷺ and informed him. Then Allah, the Mighty and Majestic, revealed concerning me — meaning himself — regarding wine: ‘Wine, gambling, stone altars, and divining arrows are only filth from the work of Satan.’”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم في فضائل الصحابة","number":1748,"lafz":true,"n":6238}],"full":1},{"num":7448,"demo":false,"sanad":"","matn":["عن ابن عباس قال: يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَقْرَبُوا الصَّلَاةَ وَأَنْتُمْ سُكَارَى و يَسْأَلُونَكَ عَنِ الْخَمْرِ وَالْمَيْسِرِ قُلْ فِيهِمَا إِثْمٌ كَبِيرٌ وَمَنَافِعُ لِلنَّاسِ نسختهما التي في المائدة إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالْأَنْصَابُ."],"takhrij":"حسن: رواه أبو داود (3672) عن أحمد بن محمد المروزي، ثنا علي بن حسين، عن أبيه، عن يزيد النحوي، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تحريم الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3672).","chapter_en":"What Has Been Reported Concerning the Prohibition of Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿAbbas said: The verses “O you who believe, do not approach prayer while you are intoxicated” and “They ask you about wine and gambling. Say: In them is great sin and benefits for people” were abrogated by the verse in al-Ma’idah: “Wine, gambling, and stone altars…”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3672,"lafz":true}],"full":1,"dr":1},{"num":7449,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: لَمَّا حُرِّمَتِ الْخَمْرِ مَشَى أَصْحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْضُهُمْ إِلَى بَعْضٍ وَقَالُوا: حُرِّمَتِ الْخَمْرُ وَجُعِلَتْ عِدْلًا لِلشِّرْكِ."],"takhrij":"حسن: رواه الطبراني في الكبير (12399)، والحاكم (4/144) كلاهما من طريق أبي شهاب الحناط، ثنا الحسن بن عمرو الفقيمي، عن طلحة بن مصرّف، عن سعيد بن جبير، عن ابن عباس فذكره. وإسناده حسن، من أجل أبي شهاب الحناط واسمه عبد ربه بن نافع الكناني فإنه حسن الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في تحريم الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (12399) and al-Hakim (7227).","chapter_en":"What Has Been Reported Concerning the Prohibition of Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿAbbas said: When wine was prohibited, the Companions of the Messenger of Allah ﷺ went to one another and said: “Wine has been prohibited and has been made equal to associating partners with Allah.”"]},"buhuth":{"en":["Their statement, “made equal to associating partners with Allah,” refers to the saying of Allah the Exalted: “O you who believe, wine, gambling, stone altars, and divining arrows are only filth from the work of Satan.” [al-Ma’idah: 90]"]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":12399,"lafz":true},{"key":"hakim","label":"المستدرك على الصحيحين","number":7227,"n":7230}],"full":1,"dr":1},{"num":7450,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ عَامَ الْفَتْحِ، وَهُوَ بِمَكَّةَ إِنَّ اللَّهَ وَرَسُولَهُ حَرَّمَ بَيْعَ الْخَمْرِ وَالْمَيْتَةِ وَالْخِنْزِيرِ وَالأَصْنَامِ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2236)، ومسلم في المساقاة (1581) كلاهما عن قتيبة بن سعيد، حدثنا ليث، عن يزيد بن أبي حبيب، عن عطاء بن أبي رباح، عن جابر بن عبد الله فذكره مطولا.","grade":"متفق عليه","chapter_ar":"باب تأكيد تحريم الخمر يوم فتح مكة","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2236) and Muslim (1581).","chapter_en":"The Confirmation of the Prohibition of Wine on the Day of the Conquest of Makkah","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Jabir ibn ʿAbdullah heard the Messenger of Allah ﷺ say in the year of the conquest while he was in Makkah: “Allah and His Messenger have forbidden the sale of wine, carrion, swine, and idols.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2236,"lafz":true},{"key":"muslim","label":"مسلم","number":1581}],"full":1,"dr":1},{"num":7451,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ كُنْتُ سَاقِيَ الْقَوْمِ فِي مَنْزِلِ أَبِي طَلْحَةَ، وَكَانَ خَمْرُهُمْ يَوْمَئِذٍ الْفَضِيخَ، فَأَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُنَادِيًا يُنَادِي أَلاَ إِنَّ الْخَمْرَ قَدْ حُرِّمَتْ. قَالَ فَقَالَ لِي أَبُو طَلْحَةَ اخْرُجْ فَأَهْرِقْهَا، فَخَرَجْتُ فَهَرَقْتُهَا، فَجَرَتْ فِي سِكَكِ الْمَدِينَةِ فَقَالَ بَعْضُ الْقَوْمِ قَدْ قُتِلَ قَوْمٌ وَهْىَ فِي بُطُونِهِمْ. فَأَنْزَلَ اللَّهُ ﴿لَيْسَ عَلَى الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ جُنَاحٌ فِيمَا طَعِمُوا﴾ [سورة المائدة: 93]} الآيَةَ."],"takhrij":"متفق عليه: رواه البخاري في المظالم (2464)، ومسلم في الأشربة (1980: 3) كلاهما من طريق حماد بن زيد، عن ثابت، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب العفو عن الذين شربوا الخمر وماتوا قبل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2464) and Muslim (1980:3).","chapter_en":"Pardon for Those Who Drank Wine and Died Before Its Prohibition","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Anas said: I was the one serving drink to the people in the house of Abu Talhah, and their wine that day was made from unripe dates. The Messenger of Allah ﷺ ordered a caller to announce: “Indeed, wine has been prohibited.” He said: Abu Talhah said to me: “Go out and pour it away.” So I went out and poured it away, and it flowed through the streets of Madinah. Some people said: “Some people were killed while it was in their bellies.” Then Allah revealed: “There is no blame upon those who believed and did righteous deeds for what they consumed.” [al-Ma’idah: 93]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2464,"lafz":true},{"key":"muslim","label":"مسلم","number":3},{"key":"muslim","label":"مسلم في الاشربه","number":1980}],"full":1,"rep":[12283]},{"num":7452,"demo":false,"sanad":"","matn":["عن جابر بن عبدالله قال: اصطبح ناسٌ الخمرَ من أصحاب النبي صلى الله عليه وسلم ثم قتلوا شهداء يوم أحد، فقالت اليهود: فقد مات بعض الذين قُتلوا وهي في بطونهم فأنزل الله تعالى: ﴿لَيْسَ عَلَى الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ جُنَاحٌ فِيمَا طَعِمُوا﴾ [سورة المائدة: 93]."],"takhrij":"صحيح: رواه البزار –كما في تفسير ابن كثير (3/186)- عن أحمد بن عبيدة، ثنا سفيان، عن عمرو بن دينار، سمع جابرا فذكره.","grade":"صحيح","chapter_ar":"باب العفو عن الذين شربوا الخمر وماتوا قبل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bazzar, as in Tafsir Ibn Kathir (3/186).","chapter_en":"Pardon for Those Who Drank Wine and Died Before Its Prohibition","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: Some of the Companions of the Prophet ﷺ drank wine in the morning and then were killed as martyrs on the day of Uhud. The Jews said: “Some of those who were killed died while it was in their bellies.” Then Allah the Exalted revealed: “There is no blame upon those who believed and did righteous deeds for what they consumed.” [al-Ma’idah: 93]"]}},"tuhfa":{},"refs":[{"key":"bazzar","label":"البزار - كما في تفسير ابن كثير","number":3,"lafz":true}],"full":1,"dr":1},{"num":7453,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: نَزَلَ تَحْرِيمُ الْخَمْرِ فِي قَبِيلَتَيْنِ مِنْ قَبَائِلِ الْأَنْصَارِ، شَرِبُوا حَتَّى إِذَا نَهِلُوا عَبَثَ بَعْضُهُمْ بِبَعْضٍ، فَلَمَّا صَحَوْا جَعَلَ الرَّجُلُ يَرَى الْأَثَرَ بِوَجْهِهِ وَبِرَأْسِهِ وَبِلِحْيَتِهِ فَيَقُولُ: قَدْ فَعَلَ بِي هَذَا أَخِي - وَكَانُوا إِخْوَةً لَيْسَ فِي قُلُوبِهِمْ ضَغَائِنُ - وَاللهِ لَوْ كَانَ رَبِّي رَؤُوفًا رَحِيمًا مَا فَعَلَ بِي هَذَا، فَوَقَعَتْ فِي قُلُوبِهِمُ الضَّغَائِنُ، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ﴿إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ﴾ [المائدة: ٩٠] إِلَى قَوْلِهِ: ﴿فَهَلْ أَنْتُمْ مُنْتَهُونَ﴾ [المائدة: ٩١] فَقَالَ نَاسٌ: هِيَ رِجْسٌ وَهِيَ فِي بَطْنِ فُلَانٍ قُتِلَ يَوْمَ بَدْرٍ، وَفُلَانٍ قُتِلَ يَوْمَ أُحُدٍ، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ﴿لَيْسَ عَلَى الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ جُنَاحٌ فِيمَا طَعِمُوا إِذَا مَا اتَّقَوْا وَآمَنُوا وَعَمِلُوا الصَّالِحَاتِ﴾"],"takhrij":"حسن: رواه النسائي في السنن الكبرى (11151)، والحاكم (2/141-142)، والطبراني في الكبير (12/56)، والضياء في المختارة (10/341) كلهم من طريق ربيعة بن كلثوم بن جبير، عن أبيه عن سعيد بن جبير، عن عبد الله بن عباس فذكره.","grade":"حسن","chapter_ar":"باب العفو عن الذين شربوا الخمر وماتوا قبل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i in al-Sunan al-Kubra (11151), al-Hakim (2/141–142), al-Tabarani in al-Kabir (12/56), and al-Diya’ in al-Mukhtarah (10/341).","chapter_en":"Pardon for Those Who Drank Wine and Died Before Its Prohibition","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Ibn ʿAbbas said: The prohibition of wine was revealed concerning two tribes from the Helpers who drank until, when they had drunk their fill, some of them began mistreating others. When they sobered up, a man would see marks on his face, head, or beard and say: “My brother did this to me.” They had been brothers with no grudges in their hearts. “By Allah, if he had been kind and merciful to me, he would not have done this to me.” So grudges fell into their hearts. Then Allah, the Mighty and Majestic, revealed: “Wine and gambling…” until His saying: “So will you then desist?” Some people said: “It is filth, and it was in the stomach of so-and-so who was killed on the day of Badr, and so-and-so who was killed on the day of Uhud.” Then Allah, the Mighty and Majestic, revealed: “There is no blame upon those who believed and did righteous deeds for what they consumed, so long as they were mindful, believed, and did righteous deeds.” [al-Ma’idah: 93]"]}},"tuhfa":{},"refs":[{"key":"kubranasai","label":"النسائي في السنن الكبرى","number":11151,"lafz":true,"n":11085},{"key":"mujamkabir","label":"الطبراني في الكبير","number":12},{"key":"sh10480","label":"الضياء في المختارة","number":10},{"key":"kubranasai","label":"السنن الكبرى للنسائي","number":11086,"n":11085},{"key":"hakim","label":"المستدرك على الصحيحين","number":7219,"n":7222},{"key":"sh10480","label":"الأحاديث المختارة للضياء","number":370,"n":4176}],"full":1,"dr":1},{"num":7454,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ شَرِبَ الْخَمْرَ فِي الدُّنْيَا، ثُمَّ لَمْ يَتُبْ مِنْهَا، حُرِمَهَا فِي الآخِرَةِ."],"takhrij":"متفق عليه: رواه مالك في الأشربة (11) عن نافع، عن عبد الله بن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الترهيب من شرب الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (11), al-Bukhari (5575), and Muslim (2003:76).","chapter_en":"What Has Been Reported Concerning the Warning Against Drinking Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “Whoever drinks wine in this world and then does not repent from it will be deprived of it in the Hereafter.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":11,"lafz":true},{"key":"bukhari","label":"البخاري","number":5575},{"key":"muslim","label":"مسلم","number":76}],"full":1,"dr":1,"rep":[7004]},{"num":7455,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، أَنَّ رَجُلاً، قَدِمَ مِنْ جَيْشَانَ - وَجَيْشَانُ مِنَ الْيَمَنِ - فَسَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ شَرَابٍ يَشْرَبُونَهُ بِأَرْضِهِمْ مِنَ الذُّرَةِ يُقَالُ لَهُ الْمِزْرُ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوَمُسْكِرٌ هُوَ. قَالَ نَعَمْ. قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُلُّ مُسْكِرٍ حَرَامٌ إِنَّ عَلَى اللَّهِ عَزَّ وَجَلَّ عَهْدًا لِمَنْ يَشْرَبُ الْمُسْكِرَ أَنْ يَسْقِيَهُ مِنْ طِينَةِ الْخَبَالِ. قَالُوا يَا رَسُولَ اللَّهِ وَمَا طِينَةُ الْخَبَالِ قَالَ عَرَقُ أَهْلِ النَّارِ أَوْ عُصَارَةُ أَهْلِ النَّارِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2002) عن قتيبة بن سعيد، حدثنا عبد العزيز الدراوردي، عن عُمارة بن غزية، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الترهيب من شرب الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2002).","chapter_en":"What Has Been Reported Concerning the Warning Against Drinking Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Jabir narrated that a man came from Jayshan — and Jayshan is in Yemen — and asked the Prophet ﷺ about a drink they made in their land from millet, called mizr. The Prophet ﷺ said: “Is it intoxicating?” He said: “Yes.” The Messenger of Allah ﷺ said: “Every intoxicant is forbidden. Allah, the Mighty and Majestic, has made a covenant concerning whoever drinks intoxicants that He will give him to drink from the mud of corruption.” They said: “O Messenger of Allah, what is the mud of corruption?” He said: “The sweat of the people of the Fire, or the discharge of the people of the Fire.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2002,"lafz":true}],"full":1,"rep":[7005,16466]},{"num":7456,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ شَرِبَ الْخَمْرَ وَسَكِرَ لَمْ تُقْبَلْ لَهُ صَلاَةٌ أَرْبَعِينَ صَبَاحًا وَإِنْ مَاتَ دَخَلَ النَّارَ فَإِنْ تَابَ تَابَ اللَّهُ عَلَيْهِ وَإِنْ عَادَ فَشَرِبَ فَسَكِرَ لَمْ تُقْبَلْ لَهُ صَلاَةٌ أَرْبَعِينَ صَبَاحًا فَإِنْ مَاتَ دَخَلَ النَّارَ فَإِنْ تَابَ تَابَ اللَّهُ عَلَيْهِ وَإِنْ عَادَ فَشَرِبَ فَسَكِرَ لَمْ تُقْبَلْ لَهُ صَلاَةٌ أَرْبَعِينَ صَبَاحًا فَإِنْ مَاتَ دَخَلَ النَّارَ فَإِنْ تَابَ تَابَ اللَّهُ عَلَيْهِ وَإِنْ عَادَ كَانَ حَقًّا عَلَى اللَّهِ أَنْ يَسْقِيَهُ مِنْ رَدْغَةِ الْخَبَالِ يَوْمَ الْقِيَامَةِ. قَالُوا يَا رَسُولَ اللَّهِ وَمَا رَدْغَةُ الْخَبَالِ قَالَ عُصَارَةُ أَهْلِ النَّارِ."],"takhrij":"صحيح: رواه ابن ماجه (4377)، وصحّحه ابن حبان (5357) كلاهما من طريق الوليد بن مسلم، ثنا الأوزاعي، عن ربيعة بن يزيد، عن عبد الله بن الديلمي، عن عبد الله بن عمرو فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الترهيب من شرب الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (3377), and authenticated by Ibn Hibban (5357).","chapter_en":"What Has Been Reported Concerning the Warning Against Drinking Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs said: The Messenger of Allah ﷺ said: “Whoever drinks wine and becomes intoxicated, his prayer will not be accepted for forty mornings. If he dies, he will enter the Fire. If he repents, Allah will accept his repentance. If he returns and drinks and becomes intoxicated, his prayer will not be accepted for forty mornings. If he dies, he will enter the Fire. If he repents, Allah will accept his repentance. If he returns and drinks and becomes intoxicated, his prayer will not be accepted for forty mornings. If he dies, he will enter the Fire. If he repents, Allah will accept his repentance. If he returns again, it will be binding upon Allah to give him drink from the mire of corruption on the Day of Resurrection.” They said: “O Messenger of Allah, what is the mire of corruption?” He said: “The discharge of the people of the Fire.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":3377},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":5357},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2453,"n":2450},{"key":"ibnmajah","label":"ابن ماجه","number":4377,"lafz":true}],"full":1,"dr":1,"rep":[7006]},{"num":7457,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو قَالَ: قَالَ رَسُولُ اللَّهِصَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  -: مَنْ مَاتَ مِنْ أُمَّتِي وَهُوَ يَشْرَبُ الْخَمْرَ حَرَّمَهَا اللَّهُ عَلَيْهِ فِي الاَخرة، وَمَنْ مَاتَ مِنْ أُمَّتِي وَهُوَ يَلْبَسُ الْحَرِيرَ حَرَّمَ اللَّهُ عَلَيْهِ لُبْسَهُ فِي الْآخِرَةِ."],"takhrij":"صحيح: رواه أبو يعلى الموصلي –كما في إتحاف الخيرة المهرة للبوصيري (5480)- من طريق عبد الأعلى بن عبد الأعلى، عن سعيد الجريري، عن ميمون بن أستاذ، عن عبد الله بن عمرو فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الترهيب من شرب الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Yaʿla al-Mawsili, as in Ithaf al-Khiyarah al-Maharah by al-Busiri (5480).","chapter_en":"What Has Been Reported Concerning the Warning Against Drinking Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs said: The Messenger of Allah ﷺ said: “Whoever from my nation dies while drinking wine, Allah will forbid it to him in the Hereafter. And whoever from my nation dies while wearing silk, Allah will forbid him from wearing it in the Hereafter.”"]}},"tuhfa":{},"refs":[{"key":"sh12520","label":"أبو يعلى الموصلي - كما في إتحاف الخيرة المهرة للبوصيري","number":5480,"lafz":true},{"key":"sh21765","label":"ابو يعلي الموصلي –كما في اتحاف الخيره المهره للبوصيري","number":5480}],"full":1,"dr":1},{"num":7458,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: مَنْ تَرَكَ الصَّلَاةَ سُكْرًا مَرَّةً وَاحِدَةً، فَكَأَنَّمَا كَانَتْ لَهُ الدُّنْيَا وَمَا عَلَيْهَا فَسُلِبَهَا، وَمَنْ تَرَكَ الصَّلَاةَ سُكْرًا أَرْبَعَ مَرَّاتٍ، كَانَ حَقًّا عَلَى اللَّهِ عَزَّ وَجَلَّ أَنْ يَسْقِيَهُ مِنْ طِينَةِ الْخَبَالِ قِيلَ: وَمَا طِينَةُ الْخَبَالِ يَا رَسُولَ اللَّهِ؟ قَالَ: عُصَارَةُ أَهْلِ جَهَنَّمَ."],"takhrij":"حسن: رواه أحمد (6659) والحاكم (4/146)، والبيهقي في السنن (1/389، 8/287)، وفي شعب الإيمان (5193) كلهم من طريق ابن وهب، حدثني عمرو بن الحارث، عن عمرو بن شعيب، عن أبيه، عن عبد الله بن عمرو فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الترهيب من شرب الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6659), al-Hakim (7233), al-Bayhaqi (8/287, 1/389), and in Shuʿab al-Iman (5193).","chapter_en":"What Has Been Reported Concerning the Warning Against Drinking Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs narrated from the Messenger of Allah ﷺ that he said: “Whoever misses prayer because of intoxication one time, it is as though he had the world and everything in it, then it was taken away from him. Whoever misses prayer because of intoxication four times, it becomes binding upon Allah, the Mighty and Majestic, to give him drink from the mud of corruption.” It was said: “What is the mud of corruption, O Messenger of Allah?” He said: “The discharge of the people of Hell.”"]}},"tuhfa":{},"refs":[{"key":"kubrabayhaqi","label":"البيهقي","number":8},{"key":"shuabiman","label":"وفي شعب الإيمان","number":5193},{"key":"ahmad","label":"مسند الإمام أحمد","number":6659,"n":6659,"lafz":true},{"key":"hakim","label":"المستدرك على الصحيحين","number":7233,"n":7236},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":17338,"n":17496}],"full":1,"dr":1,"rep":[16467]},{"num":7459,"demo":false,"sanad":"","matn":["عن طلق بن عَلِيٍّأَنَّهُ كَانَ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسًا فَجَاءَ صُحَارُ عَبَدِ الْقَيْسِ فَقَالَ: يَا رَسُولَ اللَّهِ مَا تَرَى فِي شَرَابٍ نَصْنَعُهُ بِأَرْضِنَا مِنْ ثِمَارِنَا؟ فَأَعْرَضَ عَنْهُ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى سَأَلَهُ ثَلَاثَ مَرَّاتٍ حَتَّى صَلَّى، وَلَمَّا قَضَى صَلَاتَهُ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنِ السَّائِلُ عَنِ الْمُسْكِرِ؟ لَا تَشْرَبْهُ، وَلَا تَسْقِهِ أَخَاكَ الْمُسْلِمَ، فَوَالَّذِي نَفْسِي بِيَدِهِ - أَوْ فَوَالَّذِي يُحْلَفُ بِهِ - لَا يَشْرَبُهُ رَجُلٌ ابْتِغَاءَ لَذَّةِ سُكْرِهِ، فَيَسْقِيهِ اللَّهُ الْخَمْرَ يَوْمَ الْقِيَامَةِ."],"takhrij":"حسن: رواه أحمد في مسنده -الملحق المستدرك- (24009: 32)، وابن أبي شيبة في المصنف (7/460)، والطبراني في الكبير (8259) كلهم من طريق ملازم بن عمرو، ثنا سِراج بن عقبة، عن عمته خلدة بنت طلق، عن أبيها طلق بن علي فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الترهيب من شرب الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad in his Musnad, the supplementary appendix (24009:32), Ibn Abi Shaybah (7/460), and al-Tabarani in al-Kabir (8259).","chapter_en":"What Has Been Reported Concerning the Warning Against Drinking Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Talq ibn ʿAli was sitting with the Messenger of Allah ﷺ when Suhar of ʿAbd al-Qays came and said: “O Messenger of Allah, what do you say about a drink we make in our land from our fruits?” The Prophet of Allah ﷺ turned away from him until he asked him three times. Then he stood and prayed. When he finished his prayer, the Prophet ﷺ said: “Where is the one who asked about the intoxicant? Do not drink it, and do not give it to your Muslim brother to drink. By the One in Whose Hand is my soul — or by the One by Whom oaths are sworn — no man drinks it seeking the pleasure of its intoxication and then is given wine by Allah on the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"أحمد في مسنده - الملحق المستدرك -","number":24009,"lafz":true},{"key":"sh9944","label":"ابن أبي شيبة","number":7},{"key":"mujamkabir","label":"الطبراني في الكبير","number":8259}],"full":1,"dr":1},{"num":7460,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ أَنَّ أَبَا بَكْرٍ الصِّدِّيقَ وَعُمَرَ بْنَ الْخَطَّابِ وَنَاسًا مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَلَسُوا بَعْدَ وَفَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَذَكَرُوا أَعْظَمَ الْكَبَائِرِ، فَلَمْ يَكُنْ عِنْدَهُمْ فِيهَا علمٌ، فَأَرْسَلُونِي إِلَى عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ أَسْأَلَهُ عَنْ ذَلِكَ، فَأَخْبَرَنِي: أَنَّ أَعْظَمَ الْكَبَائِرِ شُرْبَ الْخَمْرِ، فَأَتَيْتُهُمْ فَأَخْبَرْتُهُمْ، فَأَنْكَرُوا ذَلِكَ، وَوَثَبُوا إِلَيْهِ جَمِيعًا، فَأَخْبَرَهُمْ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ مَلِكًا مِنْ بَنِي إِسْرَائِيلَ أجبر رَجُلًا، فَخَيَّرَهُ بَيْنَ أَنْ يَشْرَبَ الْخَمْرَ، أَوْ يَقْتُلَ صَبِيًّا، أَوْ يَزْنِيَ، أَوْ يَأْكُلَ لَحْمَ الْخِنْزِيرِ، أَوْ يَقْتُلُوهُ إِنْ أَبَى، فَاخْتَارَ أَنَّهُ يَشْرَبُ الْخَمْرَ، وَأَنَّهُ لَمَّا شَرِبَ لَمْ يَمْتَنِعْ مِنْ شَيْءٍ أرادوهُ مِنْهُ، وَأَنَّ رَسُولَ اللَّهِ قَالَ لَنَا حِينَئِذٍ: مَا مِنْ أَحَدٍ يَشْرَبُهَا فَتُقْبَلُ لَهُ صَلَاةٌ أَرْبَعِينَ لَيْلَةً وَلَا يَمُوتُ وَفِي مَثَانَتِهِ مِنْهَا شَيْءٌ إِلَّا حُرِّمَتْ عَلَيْهِ الْجَنَّةُ، وَإِنْ مَاتَ فِي الْأَرْبَعِينَ مَاتَ مِيتَةً جَاهِلِيَّةً."],"takhrij":"حسن: رواه الطبراني في الاوسط (363) عن أحمد بن رشدين، ثنا سعيد بن أبي مريم، أخبرنا عبد العزيز بن محمد الدراوردي، ثنا داود بن صالح، عن سالم بن عبد الله بن عمر قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الترهيب من شرب الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Awsat (363).","chapter_en":"What Has Been Reported Concerning the Warning Against Drinking Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar narrated that Abu Bakr al-Siddiq, ʿUmar ibn al-Khattab, and some of the Companions of the Messenger of Allah ﷺ sat together after the death of the Messenger of Allah ﷺ and discussed the greatest major sins. They did not have knowledge concerning it, so they sent me to ʿAbdullah ibn ʿAmr ibn al-ʿAs to ask him about it. He informed me that the greatest of the major sins is drinking wine. I came to them and informed them, but they rejected that and all rushed to him. He informed them that the Messenger of Allah ﷺ said: “A king from the Children of Israel forced a man and gave him a choice between drinking wine, killing a child, committing fornication, eating pork, or being killed if he refused. He chose to drink wine, and when he drank, he did not refrain from anything they wanted from him.” And the Messenger of Allah ﷺ said to us at that time: “No one drinks it and then has his prayer accepted for forty nights; and no one dies while there is any of it in his bladder except that Paradise is forbidden to him. If he dies during the forty days, he dies a death of pre-Islamic ignorance.”"]}},"tuhfa":{},"refs":[{"key":"sh28171","label":"الطبراني في الأوسط","number":363,"lafz":true}],"full":1,"dr":1},{"num":7461,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ شَرِبَ الْخَمْرَ لَمْ تُقْبَلْ لَهُ صَلَاةٌ أَرْبَعِينَ لَيْلَةً، فَإِنْ تَابَ، تَابَ اللَّهُ عَلَيْهِ، وإن شَرِبَهَا الثانية لَمْ تُقْبَلْ لَهُ صَلَاةٌ أَرْبَعِينَ لَيْلَةً، فَإِنْ تَابَ، تَابَ اللَّهُ عَلَيْهِ، فَإِنْ شَرِبَهَا الثالثة لَمْ تُقْبَلْ لَهُ صَلَاةٌ أَرْبَعِينَ لَيْلَةً، فَإِنْ تَابَ، تَابَ اللَّهُ عَلَيْهِ، فَإِنْ شَرِبَهَا الرَّابِعَةَ لَمْ تُقْبَلْ لَهُ صَلَاةٌ أَرْبَعِينَ لَيْلَةً فَإِنْ تَابَ لَمْ يَتُبِ اللَّهُ عَلَيْهِ، وَكَانَ حَقًّا عَلَى اللَّهِ أَنْ يَسْقِيَهُ مِنْ طِينَةِ الْخَبَالِ. قِيلَ: وَمَا طِينَةُ الْخَبَالِ؟ قَالَ: صَدِيدُ أَهْلِ النَّارِ."],"takhrij":"صحيح: رواه البيهقي في الشعب (5191) واللفظ له، والطبراني في الكبير (12/392) كلاهما من طريق حماد بن زيد، حدثنا عطاء بن السائب، عن عبد الله بن عبيد بن عمير، أن ابن عمر قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الترهيب من شرب الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bayhaqi in al-Shuʿab (5191), and the wording is his, and by al-Tabarani in al-Kabir (12/392).","chapter_en":"What Has Been Reported Concerning the Warning Against Drinking Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿUmar said: I heard the Messenger of Allah ﷺ say: “Whoever drinks wine, his prayer will not be accepted for forty nights. If he repents, Allah will accept his repentance. If he drinks it a second time, his prayer will not be accepted for forty nights. If he repents, Allah will accept his repentance. If he drinks it a third time, his prayer will not be accepted for forty nights. If he repents, Allah will accept his repentance. If he drinks it a fourth time, his prayer will not be accepted for forty nights; and if he repents, Allah will not accept his repentance. It will be binding upon Allah to give him drink from the mud of corruption.” It was said: “What is the mud of corruption?” He said: “The pus of the people of the Fire.”"]}},"tuhfa":{},"refs":[{"key":"shuabiman","label":"البيهقي في الشعب","number":5191,"lafz":true},{"key":"mujamkabir","label":"الطبراني في الكبير","number":12},{"key":"kubrabayhaqi","label":"البيهقي في الشعب","number":5191}],"full":1,"dr":1},{"num":7462,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ يَدْخُلُ الْجَنَّةَ مُدْمِنُ خَمْرٍ."],"takhrij":"حسن: رواه ابن ماجه (3376) عن هشام بن عمار، ثنا سليمان بن عتبة، قال: حدثني يونس بن ميسرة بن حلبس، عن أبي إدريس، عن أبي الدرداء فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من الوعيد في مُدمن الخمر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (3376), and Ahmad (27484) also narrated it and added:","chapter_en":"What Has Been Reported of Threat Concerning the One Addicted to Wine","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu al-Darda’ narrated from the Prophet ﷺ that he said: “One who is addicted to wine will not enter Paradise.”"]},"buhuth":{"en":["“Nor one who is undutiful to parents, nor one who denies divine decree.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":3376,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":27484,"n":27484}],"full":1,"dr":1},{"num":7463,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ، قَالَ أَوْصَانِي خَلِيلِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ تَشْرَبِ الْخَمْرَ فَإِنَّهَا مِفْتَاحُ كُلِّ شَرٍّ."],"takhrij":"حسن: رواه ابن ماجه (3371) من طريق راشد أبي محمد الحماني، عن شهر بن حوشب، عن أم الدرداء، عن أبي الدرداء قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في أن الخمر مفتاح كل شرّ","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (3371) and al-Bukhari in al-Adab al-Mufrad (18).","chapter_en":"What Has Been Reported That Wine Is the Key to Every Evil","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abu al-Darda’ said: My close friend advised me: “Do not drink wine, for it is the key to every evil.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":3371,"lafz":true},{"key":"adab","label":"البخاري في الأدب المفرد","number":18}],"full":1,"dr":1},{"num":7464,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اجْتَنِبُوا الْخَمْرَ فَإِنَّهَا مِفْتَاحُ كُلِّ شَرٍّ."],"takhrij":"حسن: رواه الحاكم (4/145) وعنه البيهقي في شعب الإيمان (5199) من طريق نعيم بن حماد، ثنا عبد العزيز بن محمد الدراوردي، عن عمرو بن أبي عمرو، عن عكرمة، عن ابن عباس قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في أن الخمر مفتاح كل شرّ","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Hakim (7231) and al-Bayhaqi in Shuʿab al-Iman (5199).","chapter_en":"What Has Been Reported That Wine Is the Key to Every Evil","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ said: “Avoid wine, for it is the key to every evil.”"]}},"tuhfa":{},"refs":[{"key":"shuabiman","label":"البيهقي في شعب الإيمان","number":5199},{"key":"hakim","label":"المستدرك على الصحيحين","number":7231,"n":7234,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي في شعب الايمان","number":5199}],"full":1,"dr":1},{"num":7465,"demo":false,"sanad":"","matn":["عن أَبِي عَامِرٍ –أَوْ أَبِي مَالِكٍ- أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَيَكُونَنَّ مِنْ أُمَّتِي أَقْوَامٌ يَسْتَحِلُّونَ الْحِرَ وَالْحَرِيرَ وَالْخَمْرَ وَالْمَعَازِفَ، وَلَيَنْزِلَنَّ أَقْوَامٌ إِلَى جَنْبِ عَلَمٍ يَرُوحُ عَلَيْهِمْ بِسَارِحَةٍ لَهُمْ، يَأْتِيهِمْ ـ يَعْنِي الْفَقِيرَ ـ لِحَاجَةٍ فَيَقُولُوا ارْجِعْ إِلَيْنَا غَدًا. فَيُبَيِّتُهُمُ اللَّهُ وَيَضَعُ الْعَلَمَ، وَيَمْسَخُ آخَرِينَ قِرَدَةً وَخَنَازِيرَ إِلَى يَوْمِ الْقِيَامَةِ."],"takhrij":"صحيح: رواه البخاري في الأشربة (5590) قال: وقال هشام بن عمار، حدثنا صدقة بن خالد، حدثنا عبد الرحمن بن يزيد بن جابر، حدثنا عطية بن قيس الكلأبي، حدثنا عبد الرحمن بن غنم الأشعري قال: حدثني أبو عامر-أو أبو مالك- الأشعري والله ما كذبني سمع النبي صلى الله عليه وسلم يقول: فذكره.","grade":"صحيح","chapter_ar":"باب فيمن يستحل الخمر ويسميها بغير اسمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5590) and Ibn Hibban (6754).","chapter_en":"Concerning Those Who Declare Wine Lawful and Call It by Another Name","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Abu ʿAmir — or Abu Malik — heard the Prophet ﷺ say: “There will surely be people from my nation who will declare lawful unlawful sexual relations, silk, wine, and musical instruments. Some people will settle beside a mountain, and their shepherd will come to them in the evening with their grazing animals. A poor person will come to them for a need, and they will say: ‘Come back to us tomorrow.’ Then Allah will destroy them during the night, bring down the mountain, and transform others into monkeys and swine until the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5590,"lafz":true},{"key":"ibnhibban","label":"ابن حبان","number":6754}],"full":1,"dr":1,"rep":[15491,15918]},{"num":7466,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، عَنْ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يشرب ناسٌ مِنْ أُمَّتِي الْخَمْرَ يُسَمُّونَهَا بِغَيْرِ اسْمِهَا."],"takhrij":"صحيح: رواه النسائي (5658)، وأحمد (18073) من طريق شعبة، عن أبي بكر بن حفص، قال: سمعت ابن محيريز يحدث عن رجل من أصحاب النبي صلى الله عليه وسلم فذكره. وإسناده صحيح، وابن محيريز هو: عبد الله بن محيريز بن جنادة.","grade":"صحيح","chapter_ar":"باب فيمن يستحل الخمر ويسميها بغير اسمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (5658) and Ahmad (18073).","chapter_en":"Concerning Those Who Declare Wine Lawful and Call It by Another Name","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["A man from the Companions of the Prophet ﷺ narrated from the Prophet ﷺ that he said: “People from my nation will drink wine, calling it by a name other than its name.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":5658,"lafz":true,"n":5658},{"key":"ahmad","label":"مسند الإمام أحمد","number":18073,"n":18073}],"full":1},{"num":7467,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: إِنَّأَوَّلَ مَا يُكْفَأُ قَالَ زَيْدٌ: يَعْنِي: فِي الْإِسْلَامَ كَمَا يُكْفَأُ الْإِنَاءُ يَعْنِي: الْخَمْرِ، فَقِيلَ: كَيْفَ يَا رَسُولَ اللَّهِ وَقَدْ بَيَّنَ اللَّهُ فِيهَا مَا بَيَّنَ؟ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يُسَمُّونَهَا بِغَيْرِ اسْمِهَا فَيَسْتَحِلُّونَهَا."],"takhrij":"حسن: رواه الدارمي (2145) عن زيد بن يحيى، ثنا محمد بن راشد، عن أبي وهب الكلاعي، عن القاسم بن محمد، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب فيمن يستحل الخمر ويسميها بغير اسمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Darimi (2145).","chapter_en":"Concerning Those Who Declare Wine Lawful and Call It by Another Name","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["ʿA’ishah said: I heard the Messenger of Allah ﷺ say: “The first thing to be overturned — meaning in Islam — as a vessel is overturned, is wine.” It was said: “How, O Messenger of Allah, when Allah has made clear about it what He has made clear?” The Messenger of Allah ﷺ said: “They will call it by a name other than its name and thereby declare it lawful.”"]}},"tuhfa":{},"refs":[{"key":"darimi","label":"سنن الدارمي","number":2035,"n":2035},{"key":"darimi","label":"الدارمي","number":2145,"lafz":true,"n":2035}],"full":1,"dr":1},{"num":7468,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ أُمَّتِي يَشْرَبُونَ الْخَمْرَ فِي آخِرِ الزَّمَانِ يُسَمُّونَهَا بِغَيْرِ اسْمِهَا."],"takhrij":"حسن: رواه الطبراني في الكبير (11/118) عن الحسن بن العباس الرازي، ثنا إسماعيل بن توبة القزويني، ثنا عفان بن سيار، ثنا أبو عامر الخزّاز، عن ابن أبي مليكة، عن ابن عباس قال: فذكره.","grade":"حسن","chapter_ar":"باب فيمن يستحل الخمر ويسميها بغير اسمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (11/118).","chapter_en":"Concerning Those Who Declare Wine Lawful and Call It by Another Name","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Ibn ʿAbbas narrated that the Messenger of Allah ﷺ said: “My nation will drink wine near the end of time, calling it by a name other than its name.”"]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":11,"lafz":true}],"full":1,"dr":1},{"num":7469,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْخَمْرُ مِنْ هَاتَيْنِ الشَّجَرَتَيْنِ النَّخْلَةِ وَالْعِنَبَةِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1985: 13) عن زهير بن حرب، ثنا إسماعيل بن إبراهيم، أخبرنا الحجاج بن أبي عثمان، حدثني يحيى بن أبي كثير، أن أبا كثير حدثه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1985:13).","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “Wine is from these two trees: the palm tree and the grapevine.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":13,"lafz":true,"n":99},{"key":"muslim","label":"مسلم في الاشربه","number":1985}],"full":1,"dr":1},{"num":7470,"demo":false,"sanad":"","matn":["عَنْ أنس قَالَ: كُنْتُ قَائِمًا عَلَى الحي أَسْقِيهِمْ -عُمُومَتِي وَأَنَا أَصْغَرُهُمُ- الْفَضِيخَ، فَقِيلَ: حُرِّمَتِ الْخَمْرُ، فَقَالُوا: أَكْفِئْهَا فَكَفَأْتُهَا، قُلْتُ لأَنَسٍ: مَا شَرَابُهُمْ؟ قَالَ: رُطب وَبُسْرٌ. فَقَالَ أَبُو بَكْرِ بْنُ أَنَسٍ: وَكَانَتْ خَمْرَهُمْ، فَلَمْ يُنْكِرْ أَنَسٌ. وَحَدَّثَنِي بَعْضُ أَصْحَابِي: أَنَّهُ سَمِعَ أنس بْنُ مَالِكٍ يَقُولُ: كَانَتْ خَمْرَهُمْ يَوْمَئِذٍ."],"takhrij":"متفق عليه: رواه البخاري في الأشربة (5583)، ومسلم في الأشربة (1980: 6) كلاهما من طريق المعتمر بن سليمان، عن أبيه، قال: سمعت أنسا قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5583) and Muslim (1980:6).","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Anas said: I was standing over the people, serving them drink — my paternal uncles, while I was the youngest of them — serving them a drink made from unripe dates. It was said: “Wine has been prohibited.” They said: “Overturn it,” so I overturned it. I said to Anas: “What was their drink?” He said: “Fresh dates and unripe dates.” Abu Bakr ibn Anas said: “And that was their wine,” and Anas did not object. One of my companions narrated to me that he heard Anas ibn Malik say: “That was their wine on that day.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5583,"lafz":true},{"key":"muslim","label":"مسلم","number":6},{"key":"muslim","label":"مسلم في الاشربه","number":1980}],"full":1},{"num":7471,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ حُرِّمَتْ عَلَيْنَا الْخَمْرُ حِينَ حُرِّمَتْ وَمَا نَجِدُ ـ يَعْنِي بِالْمَدِينَةِ ـ خَمْرَ الأَعْنَابِ إِلاَّ قَلِيلاً، وَعَامَّةُ خَمْرِنَا الْبُسْرُ وَالتَّمْرُ."],"takhrij":"متفق عليه: رواه البخاري في الأشربة (5580) من طريق يونس، عن ثابت البناني، عن أنس فذكره. ورواه مسلم في الأشربة (1980: 3) من طريق حماد بن زيد، أخبرنا ثابت به، وفيه قصة تحريم الخمر، لكن جاء بلفظ: \"وما شرابهم إلا الفضيخ: البسر والتمر\"، ولم يذكر العنب.","grade":"متفق عليه","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5580) and Muslim (1980:3).","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Anas said: Wine was prohibited to us when it was prohibited, and we did not find — meaning in Madinah — much grape wine. Most of our wine was from unripe dates and dates."]},"buhuth":{"en":["His statement, “most of our wine was from unripe dates”: unripe dates are one of the stages of dates. First it is spathe, then early green fruit, then immature dates, then unripe dates, then fresh dates, then dried dates."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5580,"lafz":true},{"key":"muslim","label":"مسلم","number":3},{"key":"muslim","label":"مسلم في الاشربه","number":1980}],"full":1,"dr":1},{"num":7472,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ يَقُولُ لَقَدْ أَنْزَلَ اللَّهُ الآيَةَ الَّتِي حَرَّمَ اللَّهُ فِيهَا الْخَمْرَ وَمَا بِالْمَدِينَةِ شَرَابٌ يُشْرَبُ إِلاَّ مِنْ تَمْرٍ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1982) عن محمد بن المثنى، ثنا أبو بكر الحنفي، ثنا عبد الحميد بن جعفر، حدثني أبي أنه سمع أنس بن مالك يقول: فذكره.","grade":"صحيح","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1982).","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Anas said: Allah revealed the verse in which Allah prohibited wine, and in Madinah there was no drink being consumed except that which was made from dates."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1982,"lafz":true}],"full":1},{"num":7473,"demo":false,"sanad":"","matn":["عن عبدالله بن عمر قال: لقد حُرّمت الخمر، وما بالمدينة منها شيء."],"takhrij":"صحيح: رواه البخاري في الأشربة (5579) عن الحسن بن صباح، حدثنا محمد بن سابق، حدثنا مالك بن مغول، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5579).","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿUmar said: Wine was prohibited while there was none of it in Madinah."]},"buhuth":{"en":["His statement, “there was none of it in Madinah,” means grapes."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5579,"lafz":true}],"full":1,"dr":1},{"num":7474,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ خَطَبَ عُمَرُ عَلَى مِنْبَرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ إِنَّهُ قَدْ نَزَلَ تَحْرِيمُ الْخَمْرِ، وَهْىَ مِنْ خَمْسَةِ أَشْيَاءَ الْعِنَبِ وَالتَّمْرِ وَالْحِنْطَةِ وَالشَّعِيرِ وَالْعَسَلِ، وَالْخَمْرُ مَا خَامَرَ الْعَقْلَ، وَثَلاَثٌ وَدِدْتُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يُفَارِقْنَا حَتَّى يَعْهَدَ إِلَيْنَا عَهْدًا الْجَدُّ وَالْكَلاَلَةُ وَأَبْوَابٌ مِنْ أَبْوَابِ الرِّبَا.","قال: قلتُ: يا أبا عمرو: فشيء يُصنع بالسّند من الأرز؟ قال: ذاك لم يكن على عهد النبي صلى الله عليه وسلم، أو قال: على عهد عمر.","وفي رواية: \"الزبيب\" مكان \"العنب\"."],"takhrij":"متفق عليه: رواه البخاري في الأشربة (5588)، ومسلم في التفسير (3032: 32) كلاهما من طريق أبي حيان التيمي، عن الشعبي، عن ابن عمر قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5588) and Muslim (3032:32).","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿUmar said: ʿUmar delivered a sermon on the pulpit of the Messenger of Allah ﷺ and said: The prohibition of wine has been revealed, and it is from five things: grapes, dates, wheat, barley, and honey. Wine is whatever clouds the mind. There are three matters concerning which I wished the Messenger of Allah ﷺ had not left us until he had given us a clear instruction: the grandfather, the inheritance of one who leaves neither parent nor child, and some categories of usury. He said: I said: “O Abu ʿAmr, what about something made in Sind from rice?” He said: “That did not exist during the time of the Prophet ﷺ,” or he said: “during the time of ʿUmar.” In another narration: “raisins” appears instead of “grapes.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5588,"lafz":true},{"key":"muslim","label":"مسلم","number":32},{"key":"muslim","label":"مسلم في التفسير","number":3032}],"full":1,"dr":1},{"num":7475,"demo":false,"sanad":"","matn":["عَنِ النُّعْمَانِ بْنِ بَشِيرٍ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ مِنَ الْعِنَبِ خَمْرًا وَإِنَّ مِنَ التَّمْرِ خَمْرًا وَإِنَّ مِنَ الْعَسَلِ خَمْرًا وَإِنَّ مِنَ الْبُرِّ خَمْرًا وَإِنَّ مِنَ الشَّعِيرِ خَمْرًا."],"takhrij":"حسن: رواه أبو داود (3676)، والترمذي (1872، 1873)، وأحمد (18350) كلهم من طرق عن إسرائيل، عن إبراهيم بن المهاجر، عن عامر الشعبي، عن النعمان بن بشير قال: فذكره.","grade":"حسن","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3676), al-Tirmidhi (1873, 1872), Ahmad (18350), and Abu Dawud (3677).","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Al-Nuʿman ibn Bashir said: The Messenger of Allah ﷺ said: “From grapes there is wine, from dates there is wine, from honey there is wine, from wheat there is wine, and from barley there is wine.”"]},"buhuth":{"en":["As for the meaning of the hadith, it is not that wine only comes from these five specific things. Rather, they were mentioned specifically because they were known at that time. So everything with the same meaning, such as millet, barley-like grains, fruit, and juice, takes the same ruling. Al-Khattabi stated this."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3676,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1873},{"key":"abudawud","label":"أبو داود","number":3677,"n":3676},{"key":"ahmad","label":"مسند الإمام أحمد","number":18350,"n":18350},{"key":"tirmidhi","label":"الترمذي","number":1872}],"full":1,"dr":1},{"num":7476,"demo":false,"sanad":"","matn":["عن علي بن أَبِي طَالِبٍ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ خَاتِمِ الذَّهَبِ وَعَنِ الْقَسِّيِّ وَعَنِ الْمِيثَرَةِ وَعَنِ الْجَعَةِ."],"takhrij":"حسن: رواه الترمذي (2808)، وأبوداود (4051)، والنسائي (8/165)، وابن ماجه (3654)، وابن أبي شيبة (8/110)، وأحمد (1102) كلهم من حديث أبي الأحوص، عن أبي إسحاق، عن هبيرة، عن علي قال: فذكره.","grade":"حسن","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (2808), Abu Dawud (4051), al-Nasa’i (8/165), Ibn Majah (3654), Ibn Abi Shaybah (8/110), and Ahmad (1102).","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["ʿAli ibn Abi Talib said: The Messenger of Allah ﷺ forbade a gold ring, qassi garments, the maytharah, and jiʿah."]},"buhuth":{"en":["His statement, “maytharah,” with kasrah on the letter mim and fathah on the letter tha’, refers to a stuffed cushion placed over the saddle of a camel beneath the rider. It was the habit of arrogant people, but if it is intended to provide comfort for the weak, then there is no harm in that. His statement, “jiʿah,” with kasrah on the letter jim and sukun on the letter ʿayn, is an intoxicating drink made from barley."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":2808,"lafz":true},{"key":"abudawud","label":"أبو داود","number":4051},{"key":"nasai","label":"النسائي","number":8},{"key":"ibnmajah","label":"ابن ماجه","number":3654},{"key":"sh9944","label":"ابن أبي شيبة","number":8},{"key":"ahmad","label":"مسند الإمام أحمد","number":1102,"n":1102}],"full":1,"dr":1,"rep":[15517]},{"num":7477,"demo":false,"sanad":"","matn":["عن معقل بن يسار قال: حرمت الخمر ونحن نشرب الفضيخ، فجعلتُ أهريقُها وأقول هذا آخر العهد بالخمر."],"takhrij":"حسن: رواه أحمد في الأشربة (184) والطبراني في الكبير (20/218)كلاهما من طريق جامع بن مطر الحبطي، ثنا معاوية بن قرة، قال: قال معقل بن يسار فذكره.","grade":"حسن","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad in al-Ashribah (184) and al-Tabarani in al-Kabir (20/218). The wording is from al-Tabarani.","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Maʿqil ibn Yasar said: Wine was prohibited while we were drinking a drink made from unripe dates. I began pouring it away and saying: “This is the last time with wine.”"]},"buhuth":{"en":["His statement, “the drink made from unripe dates,” refers to a drink made from unripe dates without being heated by fire."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"أحمد في الأشربة","number":184,"lafz":true},{"key":"mujamkabir","label":"الطبراني في الكبير","number":20}],"full":1,"dr":1},{"num":7478,"demo":false,"sanad":"","matn":["عن أَبِي عبد اللَّهِ الجسري قَالَ: سَأَلْتُ مَعْقِلَ بْنَ يَسَارٍ عَنِ الشَّرَابِ، فَقَالَ: كُنَّا بِالْمَدِينَةِ وَكَانَتْ كَثِيرَةَ التَّمْرِ، فَحَرَّمَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْفَضِيخَ، وَأَتَاهُ رَجُلٌ فَسَأَلَهُ عَنْ أُمٍّ لَهُ عَجُوزٍ كَبِيرَةٍ، أَيَسْقِيهَا النَّبِيذَ، فَإِنَّهَا لَا تَأْكُلُ الطَّعَامَ؟ فَنَهَاهُ مَعْقِلٌ."],"takhrij":"صحيح: رواه أحمد (20299)، والطبراني في الكبير (20/217، 224) كلاهما من طريق المثنى بن عوف، ثنا أبو عبد الله الجسري به فذكره.","grade":"صحيح","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (20299) and al-Tabarani in al-Kabir (20/217, 224).","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Abu ʿAbdullah al-Jusari said: I asked Maʿqil ibn Yasar about drink. He said: We were in Madinah, and it had many dates, so the Messenger of Allah ﷺ forbade us from the drink made from unripe dates. A man came to him and asked him about an elderly mother of his: should he give her date drink to drink, since she did not eat food? Maʿqil forbade him from that."]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":20},{"key":"ahmad","label":"مسند الإمام أحمد","number":20299,"n":20299,"lafz":true}],"full":1,"dr":1},{"num":7479,"demo":false,"sanad":"","matn":["عَنْ أُمِّ حَبِيبَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّ نَاسًا مِنْ أَهْلِ الْيَمَنِ قَدِمُوا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَعَلَّمَهُمُ الصَّلَاةَ وَالسُّنَنَ وَالْفَرَائِضَ، فَقَالُوا: يَا رَسُولَ اللَّهِ، إِنَّ لَنَا شَرَابًا نَصْنَعُهُ مِنَ الْقَمْحِ وَالشَّعِيرِ، فَقَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْغُبَيْرَاءُ؟ قَالُوا: نَعَمْ، قَالَ: لَا تَطْعَمُوهُ، فَلَمَّا كَانَ بَعْدَ يَوْمَيْنِ ذَكَرُوهُمَا لَهُ أَيْضًا، فَقَالَ: الْغُبَيْرَاءُ؟ قَالُوا: نَعَمْ، قَالَ: لَا تَطْعَمُوهُ، فَلَمَّا أَرَادُوا أَنْ يَنْطَلِقُوا سَأَلُوهُ عَنْهُ، فَقَالَ: الْغُبَيْرَاءُ؟ قَالُوا: نَعَمْ، قَالَ: فَلَا تَطْعَمُوهُ."],"takhrij":"حسن: رواه ابن حبان (5367) عن ابن قتيبة، ثنا يزيد بن مَوْهب، ثنا ابن وهب، أخبرني عمرو بن الحارث، أن أبا السمح حدثه، أن عمر بن الحكم حدثه، عن أم حبيبة فذكرته.","grade":"حسن","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Hibban (5367).","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Umm Habibah, the wife of the Prophet ﷺ, narrated that some people from Yemen came to the Messenger of Allah ﷺ, and he taught them the prayer, the prophetic practices, and the obligations. They said: “O Messenger of Allah, we have a drink that we make from wheat and barley.” He said: “Al-Ghubayra’?” They said: “Yes.” He said: “Do not consume it.” After two days, they mentioned the two to him again, and he said: “Al-Ghubayra’?” They said: “Yes.” He said: “Do not consume it.” When they wanted to depart, they asked him about it again, and he said: “Al-Ghubayra’?” They said: “Yes.” He said: “Then do not consume it.”"]},"buhuth":{"en":["His statement, “al-Ghubayra’,” with the letter ghayn pronounced with dammah, refers to a type of wine made from millet, and it was among the wines of Abyssinia. Malik said: I asked Zayd ibn Aslam about it, and he said: “It is intoxicating drink.” In another wording: “It is al-sukarkah.” Al-Ashribah (10)."]}},"tuhfa":{},"refs":[{"key":"ہی_السکرکہ_الاشربہ","label":"هي السكركة. الأشربة","number":10},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1848,"n":1845},{"key":"ibnhibban","label":"ابن حبان","number":5367,"lafz":true}],"full":1,"dr":1},{"num":7480,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ قَالَ: كَانَتْ خمرتنا يَوْمَئِذٍ الْفَضِيخَ، وَحُرِّمَتْ يَوْمَ حُرِّمَتْ وَمَا هِيَ إِلَّا فَضِيخُكُمْ."],"takhrij":"حسن: رواه الطبراني في الكبير (11/351) عن موسى بن هارون، ثنا أحمد بن حنبل، ثنا يحيى بن سعيد، عن عثمان الشحّام، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (11/351).","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿAbbas said: Our wine on that day was the drink made from unripe dates, and it was prohibited on the day it was prohibited, and it was nothing but your drink made from unripe dates."]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":11,"lafz":true}],"full":1,"dr":1},{"num":7481,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ أَبِي الْهُذَيْلِ قَالَ: كَانَ عَبْدُ اللَّهِ يَحْلِفُ بِاللَّهِ إِنَّ الَّتِي أَمَرَ بِهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ حُرِّمَتِ الْخَمْرُ أَنْ تُكسر دَنَانُهُ، وَأَنْ تكفأ لمن التَّمْرِ وَالزَّبِيبِ."],"takhrij":"صحيح: رواه الدارقطني (4652)، وأحمد بن منيع في مسنده –كما في المطالب العالية (1825)- من طريق حسين بن محمد، ثنا شيبان، عن أشعث بن أبي الشعثاء، عن عبد الله بن أبي الهذيل فذكره.","grade":"صحيح","chapter_ar":"باب تفسير الخمر التي نزل تحريمها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Daraqutni (4652) and Ahmad ibn Maniʿ in his Musnad, as in al-Matalib al-ʿAliyah (1825).","chapter_en":"Explanation of the Wine Concerning Which the Prohibition Was Revealed","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullah ibn Abi al-Hudhayl said: ʿAbdullah used to swear by Allah that what the Messenger of Allah ﷺ commanded when wine was prohibited was that its large jars be broken and that what was made from dates and raisins be poured out."]},"buhuth":{"en":["His statement, “large jars,” is the plural of a large vessel.","Every intoxicant is forbidden, whatever type it may be, because it is the wine forbidden in the Qur’an, the Sunnah, and consensus. This is the view of the people of the Hijaz among the Companions and Followers, and among the jurists it was held by the leading scholars of legal verdicts in the regions: Malik, al-Layth, al-Shafiʿi, Ahmad, al-Awzaʿi, Abu Thawr, Ishaq, Dawud, and others. This is what the authentic reports from the Prophet ﷺ testify to, what the Arabic language testifies to regarding the meaning of wine, and what the Companions understood when the Qur’an was revealed prohibiting it. For more, see al-Minnah al-Kubra (7/355–356)."]}},"tuhfa":{},"refs":[{"key":"sh9771","label":"الدارقطني","number":4652,"lafz":true},{"key":"sh22804","label":"أحمد بن منيع في مسنده - كما في المطالب العالية","number":1825}],"full":1,"dr":1},{"num":7482,"demo":false,"sanad":"","matn":["عن عَائِشَةَ قَالَتْ سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْبِتْعِ فَقَالَ كُلُّ شَرَابٍ أَسْكَرَ فَهْوَ حَرَامٌ."],"takhrij":"متفق عليه: رواه مالك في الأشربة (9) عن ابن شهاب، عن أبي سلمة بن عبدالرحمن، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (9), al-Bukhari (5585), and Muslim (2001:67).","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ was asked about a honey-based drink. He said: “Every drink that intoxicates is forbidden.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":9,"lafz":true},{"key":"bukhari","label":"البخاري","number":5585},{"key":"muslim","label":"مسلم","number":67}],"full":1,"dr":1},{"num":7483,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى قَالَ: بَعَثَنِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  أَنَا وَمُعَاذُ بْنُ جَبَلٍ إِلَى الْيَمَنِ فَقُلْتُ: يَا رَسُولَ اللهِ، إِنَّ شَرَابًا يُصْنَعُ بِأَرْضِنَا يُقَالُ لَهُ: الْمِزْرُ مِنَ الشَّعِيرِ، وَشَرَابٌ يُقَالُ لَهُ: الْبِتْعُ مِنَ الْعَسَلِ. فَقَالَ: كُلُّ مُسْكِرٍ حَرَامٌ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4343)، ومسلم في الأشربة (1733: 70) كلاهما من طريق سعيد بن أبي بُردة، عن أبيه، عن أبي موسى قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4343) and Muslim (1733:70). The wording is from Muslim.","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Abu Musa al-Ashʿari said: The Prophet ﷺ sent me and Muʿadh ibn Jabal to Yemen. I said: “O Messenger of Allah, a drink is made in our land called mizr from barley, and another drink called bitʿ from honey.” He said: “Every intoxicant is forbidden.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4343,"lafz":true},{"key":"muslim","label":"مسلم","number":70},{"key":"muslim","label":"مسلم في الاشربه","number":1733}],"full":1,"dr":1,"rep":[9291]},{"num":7484,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُلُّ مُسْكِرٍ خَمْرٌ وَكُلُّ مُسْكِرٍ حَرَامٌ وَمَنْ شَرِبَ الْخَمْرَ فِي الدُّنْيَا فَمَاتَ وَهُوَ يُدْمِنُهَا لَمْ يَتُبْ لَمْ يَشْرَبْهَا فِي الآخِرَةِ."],"takhrij":"متفق عليه: رواه مسلم في الأشربة (2003: 73) من طريق أيوب، عن نافع، عن ابن عمر قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2003:73) and al-Bukhari (5575).","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ said: “Every intoxicant is wine, and every intoxicant is forbidden. Whoever drinks wine in this world and dies while being addicted to it, without repenting, will not drink it in the Hereafter.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":73,"lafz":true},{"key":"bukhari","label":"البخاري","number":5575},{"key":"muslim","label":"مسلم في الاشربه","number":2003}],"full":1,"dr":1,"rep":[11997]},{"num":7485,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الحصيب أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: نَهَيْتُكُمْ عَنِ الظُّرُوفِ، وَإِنَّ الظُّرُوفَ – أَوْ ظَرْفًا - لاَ يُحلُّ شَيْئًا وَ لاَ يُحَرِّمُهُ، وَكُلُّ مُسْكِرٍ حَرَامٌ."],"takhrij":"صحيح: رواه مسلم في الأشربة (977: 64) عن حجاج بن الشاعر، حدثنا ضحاك بن مخلد، عن سفيان، عن علقمة بن مرثد، عن ابن بريدة، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (977:64).","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Buraydah ibn al-Husayb narrated that the Messenger of Allah ﷺ said: “I had forbidden you from certain containers, but containers do not make anything lawful or unlawful. Every intoxicant is forbidden.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":64,"lafz":true},{"key":"muslim","label":"مسلم في الاشربه","number":977}],"full":1,"rep":[7545]},{"num":7486,"demo":false,"sanad":"","matn":["سَأَلْتُ ابْنَ عَبَّاسٍ عَنِ الْبَاذَقِ،. فَقَالَ سَبَقَ مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْبَاذَقَ، فَمَا أَسْكَرَ فَهْوَ حَرَامٌ. قَالَ الشَّرَابُ الْحَلاَلُ الطَّيِّبُ. قَالَ لَيْسَ بَعْدَ الْحَلاَلِ الطَّيِّبِ إِلاَّ الْحَرَامُ الْخَبِيثُ."],"takhrij":"صحيح: رواه البخاري في الأشربة (5598) عن محمد بن كثير، أخبرنا سفيان، عن أبي الجويرية قال: سألت ابن عباس عن الباذق فقال: فذكره.","grade":"صحيح","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5598).","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿAbbas was asked about badhiq. He said: Muhammad ﷺ already judged before badhiq appeared: whatever intoxicates is forbidden. It was said: “What about lawful, good drink?” He said: “After lawful, good drink, there is nothing except forbidden, filthy drink.”"]},"buhuth":{"en":["Badhiq is when grape juice is cooked until it becomes like the coating used on camels, and it becomes intoxicating."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5598,"lafz":true}],"full":1,"dr":1},{"num":7487,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُنْبَذَ فِي النَّقِيرِ وَالْمُزَفَّتِ وَالدُّبَّاءِ وَالْحَنْتَمَةِ وَقَالَ كُلُّ مُسْكِرٍ حَرَامٌ."],"takhrij":"حسن: رواه النسائي (5588، 5589)، وابن ماجه (3401)، وأحمد (9539، 10510)، وصحّحه ابن حبان (5408) كلهم من طرق عن محمد بن عمرو، ثنا أبو سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (5588, 5589), Ibn Majah (3401), Ahmad (9539, 10510), and authenticated by Ibn Hibban (5408).","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ forbade making date infusion in hollowed palm trunks, pitch-coated vessels, gourds, and green jars, and he said: “Every intoxicant is forbidden.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":5588,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":3401},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":5408},{"key":"ahmad","label":"مسند الإمام أحمد","number":9539,"n":9539},{"key":"nasai","label":"النسائي","number":5589},{"key":"ahmad","label":"احمد","number":10510}],"full":1,"dr":1},{"num":7488,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: كُلُّ مُسْكِرٍ حَرَامٌ، وكل مُسْكِرٍ خمر."],"takhrij":"حسن: رواه الترمذي (1864)، والنسائي (5587)، وابن ماجه (3390)، وأحمد (4644)، وصحّحه ابن حبان (5369) كلهم من طرق عن محمد بن عمرو، ثنا أبو سلمة، عن ابن عمر قال: فذكره.","grade":"حسن","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1864), al-Nasa’i (5587), Ibn Majah (3390), Ahmad (4644), and authenticated by Ibn Hibban (5369).","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿUmar said: I heard the Prophet ﷺ say: “Every intoxicant is forbidden, and every intoxicant is wine.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1864,"lafz":true},{"key":"nasai","label":"النسائي","number":5587,"n":5583},{"key":"ibnmajah","label":"ابن ماجه","number":3390},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":5369},{"key":"ahmad","label":"مسند الإمام أحمد","number":4644,"n":4605},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":5993,"n":5990}],"full":1,"dr":1},{"num":7489,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ خَطَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ آيَةَ الْخَمْرِ فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ أَرَأَيْتَ الْمِزْرَ قَالَ وَمَا الْمِزْرُ. قَالَ حَبَّةٌ تُصْنَعُ بِالْيَمَنِ. فَقَالَ تُسْكِرُ. قَالَ نَعَمْ. قَالَ كُلُّ مُسْكِرٍ حَرَامٌ."],"takhrij":"صحيح: رواه النسائي (5605) عن أبي بكر بن علي، ثنا نصر بن علي، أخبرني أبي، ثنا إبراهيم بن نافع، عن ابن طاوس، عن أبيه، عن ابن عمر قال: فذكره.","grade":"صحيح","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (5605).","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ delivered a sermon and mentioned the verse of wine. A man said: “What do you think about mizr?” He said: “What is mizr?” He said: “A drink made from grain in Yemen.” He said: “Does it intoxicate?” He said: “Yes.” He said: “Every intoxicant is forbidden.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":5605,"lafz":true,"n":5605}],"full":1,"dr":1},{"num":7490,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى الأشعري قَالَ: بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَا وَمُعَاذٌ إِلَى الْيَمَنِ، فَقَالَ مُعَاذٌ: إِنَّكَ تَبْعَثُنَا إِلَى أَرْضٍ كَثِيرٌ شَرَابُ أَهْلِهَا، فَمَا أَشْرَبُ؟ قَالَ: اشْرَبْ وَلاَ تَشْرَبْ مُسْكِرًا."],"takhrij":"صحيح: رواه النسائي (5596) عن أحمد بن عبد الله بن علي، ثنا عبد الرحمن، عن إسرائيل، عن أبي إسحاق، عن أبي بردة، عن أبيه قال: فذكره.","grade":"صحيح","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (5596).","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Abu Musa al-Ashʿari said: The Messenger of Allah ﷺ sent me and Muʿadh to Yemen. Muʿadh said: “You are sending us to a land whose people have many drinks, so what should I drink?” He said: “Drink, but do not drink anything intoxicating.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":5596,"lafz":true,"n":5596}],"full":1,"dr":1},{"num":7491,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَنْ شَرَابٍ بِالْيَمَنِ يُقَالَ لَهُ: الْبِتْعُ وَالْمِزْرُ، فَقَالَ: مَا أَسْكَرَ فَهُوَ حَرَامٌ."],"takhrij":"حسن: رواه أبو يعلى (3971) عن محمد بن إسماعيل بن أبي سمينة البصري، ثنا عبد الله بن إدريس، عن المختار بن فُلفُل، عن أنس بن مالك قال: فذكره. وسيأتي مفصلا في باب ترخيص النبي صلى الله عليه وسلم في الأوعية.","grade":"حسن","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Yaʿla (3971).","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Anas ibn Malik narrated that the Messenger of Allah ﷺ was asked about a drink in Yemen called bitʿ and mizr. He said: “Whatever intoxicates is forbidden.”"]}},"tuhfa":{},"refs":[{"key":"sh12520","label":"أبو يعلى","number":3971,"lafz":true}],"full":1,"dr":1},{"num":7492,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، أَنَّهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كُلُّ مُسْكِرٍ حَرَامٌ."],"takhrij":"حسن: رواه أحمد (6738) عن محمد بن عبد الله بن الزبير، حدثنا أبان بن عبد الله، عن عمرو بن شعيب، عن أبيه، عن جده قال: فذكره.","grade":"حسن","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6738).","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs said: The Messenger of Allah ﷺ said: “Every intoxicant is forbidden.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":6738,"n":6738,"lafz":true}],"full":1,"dr":1},{"num":7493,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن الشِّخِّيرِ عَنْ أَبِيهِ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْأَشْرِبَةِ، فَقِيلَ: إِنَّهُ لَا بُدَّ مِنْهَا، فَقَالَ: اشْرَبُوا مَا لَا يُسَفِّهُ أَحْلَامَكُمْ، وَلَا يُذْهِبُ أَمْوَالَكُمْ."],"takhrij":"حسن: رواه الطبراني ومن طريق الضياء في المختارة (9/رقم 642) عن عبدان بن أحمد، ثنا الحسين بن مهدي، ثنا عبد الرزاق، عن الثوري، عن الجريري، عن يزيد بن عبد الله، عن أبيه قال: فذكره.","grade":"حسن","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani, and through him by al-Diya’ in al-Mukhtarah (9, no. 642).","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullah ibn al-Shikhkhir said: The Messenger of Allah ﷺ forbade certain drinks. It was said: “But they are necessary.” He said: “Drink what does not corrupt your minds and does not cause your wealth to go away.”"]}},"tuhfa":{},"refs":[{"key":"sh10480","label":"ومن طريقه الضياء في المختارة","number":9,"lafz":true},{"key":"sh10480","label":"الأحاديث المختارة للضياء","number":462,"n":3717}],"full":1,"dr":1},{"num":7494,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ كُلِّ مُسْكِرٍ وَمُفَتِّرٍ."],"takhrij":"حسن: رواه أبوداود (3686)، وأحمد (26634) كلاهما من طريق الحكم بن عتيبة، عن شهر بن حوشب قال: سمعت أم سلمة فذكرته.","grade":"حسن","chapter_ar":"باب كل مسكر خمر وكل خمر حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3686) and Ahmad (26634).","chapter_en":"Every Intoxicant Is Wine, and Every Wine Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Umm Salamah said: The Messenger of Allah ﷺ forbade every intoxicant and every substance that causes bodily weakness."]},"buhuth":{"en":["His statement, “that causes bodily weakness,” refers to something which, when drunk, warms the body and produces slackness, meaning weakness and loss of vigor."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3686,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":26634,"n":26634}],"full":1,"dr":1},{"num":7495,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا أَسْكَرَ كَثِيرُهُ فَقَلِيلُهُ حَرَامٌ."],"takhrij":"حسن: رواه أبوداود (3681)، والترمذي (1865)، وابن ماجه (3393)، وأحمد (14703)، وصحّحه ابن حبان (5382) كلهم من طريق داود بن بكر بن أبي الفرات، عن محمد بن المنكدر، عن جابر بن عبد الله قال: فذكره.","grade":"حسن","chapter_ar":"باب ما أسكر كثيره فقليله حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3681), al-Tirmidhi (1865), who graded it hasan, Ibn Majah (3393), Ahmad (14703), and authenticated by Ibn Hibban (5382).","chapter_en":"Whatever Intoxicates in Large Amounts, a Small Amount of It Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: The Messenger of Allah ﷺ said: “Whatever intoxicates in large amounts, a small amount of it is forbidden.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3681,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1865},{"key":"ibnmajah","label":"ابن ماجه","number":3393},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":5382,"n":1583},{"key":"ahmad","label":"مسند الإمام أحمد","number":14703,"n":14703}],"full":1,"dr":1},{"num":7496,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، رَضِيَ اللَّهُ عَنْهَا قَالَتْ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ كُلُّ مُسْكِرٍ حَرَامٌ وَمَا أَسْكَرَ مِنْهُ الْفَرْقُ فَمِلْءُ الْكَفِّ مِنْهُ حَرَامٌ.","وفي لفظ: الحسوة منه حرام."],"takhrij":"حسن: رواه أبوداود (3687)، والترمذي (1866)، وأحمد (24423) كلهم من طريق أبي عثمان الأنصاري، قال: حدثني القاسم بن محمد بن أبي بكر، أن عائشة قالت: فذكرته.","grade":"حسن","chapter_ar":"باب ما أسكر كثيره فقليله حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3687), al-Tirmidhi (1866), who graded it hasan, and Ahmad (24423).","chapter_en":"Whatever Intoxicates in Large Amounts, a Small Amount of It Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["ʿA’ishah said: I heard the Messenger of Allah ﷺ say: “Every intoxicant is forbidden, and if a faraq of it intoxicates, then a handful of it is forbidden.” In another wording: “A sip of it is forbidden.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3687,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1866},{"key":"ahmad","label":"مسند الإمام أحمد","number":24423,"n":24423}],"full":1,"dr":1},{"num":7497,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عمرو، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا أَسْكَرَ كَثِيرُهُ فَقَلِيلُهُ حَرَامٌ."],"takhrij":"حسن: رواه النسائي (5607)، وابن ماجه (3394)، وأحمد (6674) كلهم من طريق عبيد الله بن عمر، عن عمرو بن شعيب، عن أبيه، عن جده.","grade":"حسن","chapter_ar":"باب ما أسكر كثيره فقليله حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (5607), Ibn Majah (3394), and Ahmad (6674).","chapter_en":"Whatever Intoxicates in Large Amounts, a Small Amount of It Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr narrated from the Prophet ﷺ that he said: “Whatever intoxicates in large amounts, a small amount of it is forbidden.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":5607,"lafz":true,"n":5607},{"key":"ibnmajah","label":"ابن ماجه","number":3394},{"key":"ahmad","label":"مسند الإمام أحمد","number":6674,"n":6674}],"full":1,"dr":1},{"num":7498,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بن أَبِي وَقَّاصٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَنْهَاكُمْ عَنْ قَلِيلِ مَا أَسْكَرَ كَثِيرُهُ."],"takhrij":"حسن: رواه النسائي (5608، 5609)، وأحمد في الأشربة (9)، وأبو يعـلى (694)، وصحّحه ابن حبان (53701)، والضياء في المختارة (975، 976، 977)كلهم من طرق عن الضحاك بن عثمان، عن بُكير بن عبد الله بن الأشج، عن عامر بن سعد، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب ما أسكر كثيره فقليله حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (5608, 5609), Ahmad (9), Abu Yaʿla (694), and authenticated by Ibn Hibban (5370).","chapter_en":"Whatever Intoxicates in Large Amounts, a Small Amount of It Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Saʿd ibn Abi Waqqas narrated from the Prophet ﷺ that he said: “I forbid you from a small amount of that which intoxicates in large amounts.”"]},"buhuth":{"en":["Abu ʿAbd al-Rahman al-Nasa’i said after these hadiths: “In this is evidence for the prohibition of intoxicants, both small and large amounts. It is not as those who deceive themselves say, that they forbid the last drink but permit what came before it, which is drunk from the faraq before it. There is no disagreement among the people of knowledge that intoxication as a whole does not occur from the final drink alone, apart from the first and the second before it. And success is from Allah.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":5608,"lafz":true,"n":5608},{"key":"ahmad","label":"أحمد","number":9},{"key":"sh12520","label":"أبو يعلى","number":694},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":5370,"n":2102},{"key":"nasai","label":"النسائي","number":5609,"n":5608},{"key":"ibnhibban","label":"ابن حبان","number":53701},{"key":"sh10480","label":"الضياء في المختاره","number":975,"n":976},{"key":"sh10480","label":"الضياء في المختاره","number":976},{"key":"sh10480","label":"الضياء في المختاره","number":977,"n":976}],"full":1,"dr":1},{"num":7499,"demo":false,"sanad":"","matn":["7499 - عَنْ ابْنِ عُمَرَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : كُلُّ مُسْكِرٍ حَرَامٌ، مَا أَسْكَرَ كَثِيرُهُ فَقَلِيلُهُ حَرَامٌ."],"takhrij":"حسن: رواه أحمد (5648)، وأبو يعلى (5466)، والبيهقي (8/296) كلهم من طريق أبي معشر، عن موسى بن عقبة، عن سالم بن عبد الله، عن أبيه، فذكره. واقتصر أبو يعلى على الشطر الأول.","grade":"حسن","chapter_ar":"باب ما أسكر كثيره فقليله حرام","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (5648), Abu Yaʿla (5466), al-Bayhaqi (8/296), and al-Bazzar (2917, Kashf al-Astar).","chapter_en":"Whatever Intoxicates in Large Amounts, a Small Amount of It Is Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ said: “Every intoxicant is forbidden. Whatever intoxicates in large amounts, a small amount of it is forbidden.”"]}},"tuhfa":{},"refs":[{"key":"sh12520","label":"أبو يعلى","number":5466,"n":5627},{"key":"kubrabayhaqi","label":"البيهقي","number":8},{"key":"bazzar","label":"البزار","number":2917},{"key":"ahmad","label":"مسند الإمام أحمد","number":5648,"n":5648,"lafz":true}],"full":1,"dr":1},{"num":7500,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ قَدِمَ وَفْدُ عَبْدِ الْقَيْسِ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا إِنَّا مِنْ هَذَا الْحَىِّ مِنْ رَبِيعَةَ، وَلَسْنَا نَصِلُ إِلَيْكَ إِلاَّ فِي الشَّهْرِ الْحَرَامِ، فَمُرْنَا بِشَىْءٍ نَأْخُذْهُ عَنْكَ، وَنَدْعُو إِلَيْهِ مَنْ وَرَاءَنَا. فَقَالَ آمُرُكُمْ بِأَرْبَعٍ، وَأَنْهَاكُمْ عَنْ أَرْبَعٍ الإِيمَانِ بِاللَّهِ ـ ثُمَّ فَسَّرَهَا لَهُمْ شَهَادَةُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ، وَأَنِّي رَسُولُ اللَّهِ، وَإِقَامُ الصَّلاَةِ، وَإِيتَاءُ الزَّكَاةِ، وَأَنْ تُؤَدُّوا إِلَىَّ خُمُسَ مَا غَنِمْتُمْ، وَأَنْهَى عَنِ الدُّبَّاءِ وَالْحَنْتَمِ وَالْمُقَيَّرِ وَالنَّقِيرِ.","وفي رواية: \"المزفت\" بدل \"المقير\"."],"takhrij":"متفق عليه: رواه البخاري في مواقيت الصلاة (523)، ومسلم في الأشربة (17: 39) كلاهما من طريق عباد بن عباد، عن أبي جمرة، عن ابن عباس.","grade":"متفق عليه","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (523) and Muslim (17:39). The wording is from al-Bukhari.","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿAbbas said: The delegation of ʿAbd al-Qays came to the Messenger of Allah ﷺ and said: “We are from this tribe of Rabiʿah, and we cannot reach you except in the sacred month, so command us with something that we may take from you and call those behind us to.” He said: “I command you with four and forbid you from four: belief in Allah.” Then he explained it to them: “To testify that there is no deity except Allah and that I am the Messenger of Allah, to establish prayer, to give alms, and to give me one fifth of what you acquire as spoils. And I forbid you from gourds, green jars, pitch-coated vessels, and hollowed palm trunks.” In another narration: “pitch-coated vessels (al-muzaffat)” appears in place of “tar-coated vessels (al-muqayyar).”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":523,"lafz":true},{"key":"muslim","label":"مسلم","number":39,"n":115},{"key":"muslim","label":"مسلم في الاشربه","number":17}],"full":1,"dr":1},{"num":7501,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ وَفْدَ عَبْدِ الْقَيْسِ أَتَوْا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فِيهِمُ الْأَشَجُّ أَخُو بَنِي عَصَرٍ، فَقَالُوا: يَا نَبِيَّ اللَّهِ، إِنَّا حَيٌّ مِنْ رَبِيعَةَ، وَإِنَّ بَيْنَنَا وَبَيْنَكَ كُفَّارَ مُضَرَ، وَإِنَّا لَا نَصِلُ إِلَيْكَ إِلَّا فِي الشَّهْرِ الْحَرَامِ، فَمُرْنَا بِأَمْرٍ إِذَا عَمِلْنَا بِهِ دَخَلْنَا الْجَنَّةَ، وَنَدْعُو بِهِ مَنْ وَرَاءَنَا؟ فَأَمَرَهُمْ بِأَرْبَعٍ، وَنَهَاهُمْ عَنْ أَرْبَعٍ: أَمَرَهُمْ أَنْ يَعْبُدُوا اللهَ وَلَا يُشْرِكُوا بِهِ شَيْئًا، وَأَنْ يَصُومُوا رَمَضَانَ، وَأَنْ يَحُجُّوا الْبَيْتَ، وَأَنْ يُعْطُوا الْخُمُسَ مِنَ الْمَغَانِمِ، وَنَهَاهُمْ عَنْ أَرْبَعٍ: عَنِ الشُّرْبِ فِي الْحَنْتَمِ، وَالدُّبَّاءِ، وَالنَّقِيرِ، وَالْمُزَفَّتِ، فَقَالُوا: فَفِيمَ نَشْرَبُ يَا رَسُولَ اللَّهِ؟ قَالَ: عَلَيْكُمْ بِأَسْقِيَةِ الْأَدَمِ، الَّتِي يُلَاثُ عَلَى أَفْوَاهِهَا."],"takhrij":"صحيح: رواه أبو داود ( (3694)، وأحمد (3406) والسياق له، كلاهما من طريق أبان بن يزيد العطّار، ثنا قتادة، عن عكرمة وسعيد بن المسيب، عن ابن عباس فذكره. وإسناده صحيح، غير أن ذكر حج البيت في هذا الحديث شاذ، لأنه لم يكن فُرض وقتئذ؛ لذلك لم يرد ذكره في رواية أبي جمرة عن ابن عباس التي في الصحيحين.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3694) and Ahmad (3406), and the wording is his. However, the mention of pilgrimage to the House in this hadith is irregular, because it had not yet been made obligatory at that time. Therefore, it is not mentioned in the narration of Abu Jamrah from Ibn ʿAbbas found in the two authentic collections.","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿAbbas narrated that the delegation of ʿAbd al-Qays came to the Messenger of Allah ﷺ, among them al-Ashajj, the brother of Banu ʿAsr. They said: “O Prophet of Allah, we are a tribe from Rabiʿah, and between us and you are the disbelievers of Mudar. We cannot reach you except in the sacred month. So command us with a command which, if we act upon it, we will enter Paradise, and by which we may call those behind us.” He commanded them with four and forbade them from four. He commanded them to worship Allah and not associate anything with Him, to fast Ramadan, to perform pilgrimage to the House, and to give one fifth of the spoils. He forbade them from four: drinking from green jars, gourds, hollowed palm trunks, and pitch-coated vessels. They said: “Then what should we drink from, O Messenger of Allah?” He said: “Use leather water skins whose mouths are tied.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3694,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":3406,"n":3406}],"full":1},{"num":7502,"demo":false,"sanad":"","matn":["عن سَعِيدِ بْنِ المسيب يَقُولُ سَمِعْتُ عَبْدَ اللَّهِ بْنَ عُمَرَ، يَقُولُ عِنْدَ هَذَا الْمِنْبَرِ - وَأَشَارَ إِلَى مِنْبَرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَدِمَ وَفْدُ عَبْدِ الْقَيْسِ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلُوهُ عَنِ الأَشْرِبَةِ فَنَهَاهُمْ عَنِ الدُّبَّاءِ وَالنَّقِيرِ وَالْحَنْتَمِ. فَقُلْتُ لَهُ يَا أَبَا مُحَمَّدٍ وَالْمُزَفَّتِ وَظَنَنَّا أَنَّهُ نَسِيَهُ فَقَالَ لَمْ أَسْمَعْهُ يَوْمَئِذٍ مِنْ عَبْدِ اللَّهِ بْنِ عُمَرَ وَقَدْ كَانَ يَكْرَهُ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1997: 58) عن أبي بكر بن أبي شيبة، حدثنا يزيد بن هارون، أخبرنا عبد الخالق بن سلمة، قال: سمعت سعيد بن المسيب يقول: فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1997:58).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Saʿid ibn al-Musayyib said: I heard ʿAbdullah ibn ʿUmar say near this pulpit — and he pointed to the pulpit of the Messenger of Allah ﷺ: The delegation of ʿAbd al-Qays came to the Messenger of Allah ﷺ and asked him about drinks. He forbade them from gourds, hollowed palm trunks, and green jars. I said to him: “O Abu Muhammad, and pitch-coated vessels?” We thought he had forgotten it. He said: “I did not hear it that day from ʿAbdullah ibn ʿUmar, though he used to dislike it.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":58,"lafz":true},{"key":"muslim","label":"مسلم في الاشربه","number":1997,"n":5201}],"full":1,"rep":[9770]},{"num":7503,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري: أن ناسا من عبد القيس قدموا على رسول الله... الحديث. وفيه: ففيم نشرب يا رسول الله؟ قال: في أسقية الأدم التي يلاث على أفواهها. قالوا: يا رسول الله إن أرضنا كثيرة الجرذان، ولا تبقى بها أسقية الأدم. فقال نبي الله صلي الله عليه وسلم: وإن أكلتها الجرذان، وإن أكلتها الجرذان، وإن أكلتها الجرذان."],"takhrij":"صحيح: رواه مسلم في الإيمان (18: 26) عن يحيى بن أيوب، ثنا ابن علية، ثنا سعيد بن أبي عروبة، عن قتادة قال: حدثنا من لقي الوفد الذين قدموا على رسول الله صلى الله عليه وسلم من عبدالقيس.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in the Book of Faith (18:26).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that some people from ʿAbd al-Qays came to the Messenger of Allah ﷺ … the hadith. In it: It was said: “What should we drink from, O Messenger of Allah?” He said: “From leather water skins whose mouths are tied.” They said: “O Messenger of Allah, our land has many rats, and leather water skins do not last there.” The Prophet of Allah ﷺ said: “Even if the rats eat them, even if the rats eat them, even if the rats eat them.”"]},"buhuth":{"en":["His statement, “rats,” refers to a type of mouse. His statement, “whose mouths are tied,” means that a cord is wrapped around their mouths and tied with it."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم في الإيمان","number":18,"lafz":true}],"full":1,"dr":1},{"num":7504,"demo":false,"sanad":"","matn":["أَنَّ أَبَا سَعِيدٍ الْخُدْرِيَّ أَخْبَرَهُ أَنَّ وَفْدَ عَبْدِ الْقَيْسِ لَمَّا أَتَوْا نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالُوا يَا نَبِيَّ اللَّهِ جَعَلَنَا اللَّهُ فِدَاءَكَ مَاذَا يَصْلُحُ لَنَا مِنَ الأَشْرِبَةِ فَقَالَ لاَ تَشْرَبُوا فِي النَّقِيرِ. قَالُوا يَا نَبِيَّ اللَّهِ جَعَلَنَا اللَّهُ فِدَاءَكَ أَوَتَدْرِي مَا النَّقِيرُ قَالَ نَعَمِ الْجِذْعُ يُنْقَرُ وَسَطُهُ وَلاَ فِي الدُّبَّاءِ وَلاَ فِي الْحَنْتَمَةِ وَعَلَيْكُمْ بِالْمُوكَى."],"takhrij":"صحيح: رواه مسلم في الإيمان (18: 28) عن محمد بن رافع، حدثنا عبد الرزاق –وهو في مصنفه (16929)- أخبرنا ابن جريج، قال: أخبرني أبو قزعة، أن أبا نضرة أخبره، وحسنا أخبرهما أن أبا سعيد الخدري قال: فذكر الحديث.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (18:28).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that when the delegation of ʿAbd al-Qays came to the Prophet of Allah ﷺ, they said: “O Prophet of Allah, may Allah make us your ransom, what drinks are suitable for us?” He said: “Do not drink from the hollowed palm trunk.” They said: “O Prophet of Allah, may Allah make us your ransom, do you know what the hollowed palm trunk is?” He said: “Yes, the trunk whose middle is hollowed out. And do not drink from gourds or green jars. Use tied leather water skins.”"]},"buhuth":{"en":["His statement, “use tied leather water skins,” means: make infusion in a thin leather water skin whose mouth is tied with a cord."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":18,"lafz":true,"n":120},{"key":"abdrazzaq","label":"حدثنا عبد الرزاق –وهو في مصنفه","number":16929}],"full":1,"dr":1},{"num":7505,"demo":false,"sanad":"","matn":["عن ثمامة بن حزن القشيري قَالَ لَقِيتُ عَائِشَةَ فَسَأَلْتُهَا عَنِ النَّبِيذِ، فَحَدَّثَتْنِي أَنَّ وَفْدَ عَبْدِ الْقَيْسِ قَدِمُوا عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلُوا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ النَّبِيذِ فَنَهَاهُمْ أَنْ يَنْتَبِذُوا فِي الدُّبَّاءِ وَالنَّقِيرِ وَالْمُزَفَّتِ وَالْحَنْتَمِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1995: 37) عن شيبان بن فروخ، حدثنا القاسم بن الفضل، حدثنا ثمامة بن حزن القشيري قال: فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1995:37).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Thumamah ibn Hazn al-Qushayri said: I met ʿA’ishah and asked her about date infusion. She narrated to me that the delegation of ʿAbd al-Qays came to the Prophet ﷺ and asked him about date infusion, so he forbade them from making infusion in gourds, hollowed palm trunks, pitch-coated vessels, and green jars."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1995,"lafz":true,"n":5175}],"full":1,"rep":[9769]},{"num":7506,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الدُّبَّاءِ، وَالْحَنْتَمِ، وَالنَّقِيرِ وَالْمُزَفَّتِ. وَفِي رِوَايَةِ: \"المزفت\" بدل \"المقير\"."],"takhrij":"صحيح: رواه مسلم في الأشربة (1995: 38) عن يعقوب بن إبراهيم، حدثنا ابن علية، حدثنا إسحاق بن سويد، عن معاذة، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1995:38).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ forbade gourds, green jars, hollowed palm trunks, and pitch-coated vessels. In another narration: “pitch-coated vessels (al-muzaffat)” appears in place of “tar-coated vessels (al-muqayyar).”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1995,"lafz":true,"n":5176}],"full":1,"dr":1},{"num":7507,"demo":false,"sanad":"","matn":["عَنْ إِبْرَاهِيمَ، قُلْتُ لِلأَسْوَدِ هَلْ سَأَلْتَ عَائِشَةَ أُمَّ الْمُؤْمِنِينَ عَمَّا يُكْرَهُ أَنْ يُنْتَبَذَ فِيهِ فَقَالَ نَعَمْ قُلْتُ يَا أُمَّ الْمُؤْمِنِينَ عَمَّا نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُنْتَبَذَ فِيهِ قَالَتْ نَهَانَا فِي ذَلِكَ أَهْلَ الْبَيْتِ أَنْ نَنْتَبِذَ فِي الدُّبَّاءِ وَالْمُزَفَّتِ. قُلْتُ أَمَا ذَكَرْتِ الْجَرَّ وَالْحَنْتَمَ قَالَ إِنَّمَا أُحَدِّثُكَ مَا سَمِعْتُ، أَفَأُحَدِّثُ مَا لَمْ أَسْمَعْ."],"takhrij":"متفق عليه: رواه البخاري في الأشربة (5595)، ومسلم في الأشربة (1995: 35) كلاهما من طريق جرير، عن منصور، عن إبراهيم (هو النخعي) به.","grade":"متفق عليه","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5595) and Muslim (1995:35). In a wording of Muslim: “The Prophet ﷺ forbade gourds and pitch-coated vessels.”","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Ibrahim said: I said to al-Aswad: “Did you ask ʿA’ishah, the Mother of the Believers, about what is disliked for making infusion in?” He said: “Yes.” I said: “O Mother of the Believers, inform me about what the Messenger of Allah ﷺ forbade making infusion in.” She said: “He forbade us, the household, from making infusion in gourds and pitch-coated vessels.” I said to him: “Did she not mention green jars and earthenware jars?” He said: “I only narrate to you what I heard. Should I narrate to you what I did not hear?”"]},"buhuth":{"en":["The word “earthenware jars” refers to vessels made from pottery. Concerning “green jars,” al-Nawawi said in his explanation of Muslim (1/185): “As for green jars, there is disagreement about them, but the soundest and strongest view is that they are green jars.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5595,"lafz":true},{"key":"muslim","label":"مسلم","number":1995}],"full":1,"dr":1},{"num":7508,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ تَنْبِذُوا فِي الدُّبَّاءِ وَلاَ الْمُزَفَّتِ وَلاَ النَّقِيرِ وَكُلُّ مُسْكِرٍ حَرَامٌ."],"takhrij":"صحيح: رواه النسائي (5590) عن أبي داود، ثنا محمد بن سليما، ثنا ابن زبر، عن القاسم بن محمد، عن عائشة قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (5590).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿA’ishah narrated from the Prophet ﷺ that he said: “Do not make infusion in gourds, pitch-coated vessels, or hollowed palm trunks. Every intoxicant is forbidden.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":5590,"lafz":true}],"full":1,"dr":1},{"num":7509,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِوَفْدِ عَبْدِ الْقَيْسِ أَنْهَاكُمْ عَنِ الدُّبَّاءِ وَالْحَنْتَمِ وَالنَّقِيرِ وَالْمُقَيَّرِ - وَالْحَنْتَمُ الْمَزَادَةُ الْمَجْبُوبَةُ - وَلَكِنِ اشْرَبْ فِي سِقَائِكَ وَأَوْكِهِ.","وفي لفظ: \" والحنتم والمزادة المجبوبة\"."],"takhrij":"صحيح: رواه مسلم في الأشربة (1991: 33) عن نصر بن علي الجهضمي، أخبرنا نوح بن قيس، حدثنا ابن عون، عن محمد (هو ابن سيرين)، عن أبي هريرة قال: فذكره. واللفظ الآخر لأبي داود (3693) من هذا الوجه.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1991:33). The other wording is from Abu Dawud (3693). This is the correct wording, because “water skin” is not an explanation of “green jar”; rather, the green jar is the earthenware jar, and the water skin is the leather container. His statement, “whose top has been cut off,” means one whose top has been removed so that it becomes like a large jar. The root meaning is cutting; its top is cut so that it no longer has a neck that can be tied.","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said to the delegation of ʿAbd al-Qays: “I forbid you from gourds, green jars, hollowed palm trunks, and pitch-coated vessels — and the green jar is a water skin whose top has been cut off — but drink from your leather water skin and tie it.” In another wording: “green jars and water skins whose tops have been cut off.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1991,"lafz":true,"n":5170},{"key":"abudawud","label":". واللفظ الآخر لأبي داود","number":3693}],"full":1,"dr":1},{"num":7510,"demo":false,"sanad":"","matn":["عَنْ أَبِي القموص زيد بن عَلِيٍّ قَالَ: قَالَ حَدَّثَنِي أَحَدُ الْوَفْدِ الَّذِينَ وَفَدُوا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ عَبْدِ الْقَيْسِ قَالَ: وَأَهْدَيْنَا لَهُ فِيمَا يهدى نَوْطًا أَوْ قِرْبَةً مِنْ تَعْضُوضٍ أَوْ بَرْنِيٍّ، فَقَالَ: مَا هَذَا؟ قُلْنَا: هَذِهِ هَدِيَّةٌ. قَالَ: وَأَحْسِبُهُ نَظَرَ إِلَى تَمْرَةٍ مِنْهَا فَأَعَادَهَا مَكَانَهَا وَقَالَ: أَبْلِغُوهَا آلَ مُحَمَّدٍ قَالَ: فَسَأَلَهُ الْقَوْمُ عَنْ أَشْيَاءَ حَتَّى سَأَلُوهُ عَنِ الشَّرَابِ فَقَالَ: لَا تَشْرَبُوا فِي دُبَّاءٍ، وَلَا حَنْتَمٍ، وَلَا نَقِيرٍ، وَلَا مُزَفَّتٍ، اشْرَبُوا فِي الْحَلَالِ الْمُوكَى عَلَيْهِ، فَقَالَ لَهُ قَائِلُنَا: يَا رَسُولَ اللَّهِ! وَمَا يُدْرِيكَ مَا الدُّبَّاءُ وَالْحَنْتَمُ وَالنَّقِيرُ وَالْمُزَفَّتُ؟ قَالَ: أَنَا لأدري ماهيه أَيُّ هَجَرٍ أَعَزُّ؟ قُلْنَا: الْمُشَقَّرُ، قَالَ: فَوَاللهِ لَقَدْ دَخَلْتُهَا وَأَخَذْتُ إِقْلِيدَهَا، قَالَ: وَكُنْتُ قَدْ نَسِيتُ مِنْ حَدِيثِهِ شَيْئًا، فَأَذْكَرَنِيهِ عُبَيْدُ اللَّهِ بْنُ أَبِي جَرْوَةَ، قَالَ: وَقَفْتُ عَلَى عَيْنِ الزَّارَةِ، ثُمَّ قَالَ: اللهُمَّ اغْفِرْ لِعَبْدِ الْقَيْسِ إِذْ أَسْلَمُوا طَائِعِينَ غَيْرَ كَارِهِينَ غَيْرَ خَزَايَا وَلَا مَوْتُورِينَ إِذْ بَعْضُ قَوْمِنَا لَا يسلموا حَتَّى يُخْزَوْا وَيُوتَرُوا قَالَ: وَابْتَهَلَ وَجْهُهُ ههنا مِنَ الْقِبْلَةِ حَتَّى اسْتَقْبَلَ الْقِبْلَةَ، وَقَالَ: إِنَّ خَيْرَ أَهْلِ الْمَشْرِقِ عَبْدُ الْقَيْسِ."],"takhrij":"صحيح: رواه أحمد (17829)، وأبو داود (3695) كلاهما من طريق عوف (هو ابن جميلة)، عن أبي القموص، فذكره. واللفظ لأحمد، وأما أبو داود فذكره مختصرا.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (17829) and Abu Dawud (3695).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu al-Qamus Zayd ibn ʿAli said: One of the delegates who came to the Messenger of Allah ﷺ from ʿAbd al-Qays narrated to me. He said: Among the gifts we gave him was a cluster or a water skin containing Taʿdud or Barni dates. He said: “What is this?” We said: “This is a gift.” He said: I think he looked at one date from it, then returned it to its place and said: “Deliver it to the family of Muhammad.” He said: The people asked him about many things until they asked him about drink. He said: “Do not drink from gourds, green jars, hollowed palm trunks, or pitch-coated vessels. Drink from lawful vessels that are tied.” One of us said to him: “O Messenger of Allah, how do you know what gourds, green jars, hollowed palm trunks, and pitch-coated vessels are?” He said: “I do not know what they are. Which place in Hajar is strongest?” We said: “Al-Mushaqqar.” He said: “By Allah, I entered it and took its key.” He said: I had forgotten part of his hadith, then ʿUbaydullah ibn Abi Jarwah reminded me of it. He said: “I stood at the spring of al-Zarah.” Then he said: “O Allah, forgive ʿAbd al-Qays, for they accepted Islam willingly, not unwillingly, neither disgraced nor avenged.” For some of our people do not accept Islam until they are disgraced and avenged. He said: Then he turned his face here toward the direction of prayer until he faced it, and said: “The best of the people of the east are ʿAbd al-Qays.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3695},{"key":"ahmad","label":"مسند الإمام أحمد","number":17829,"n":17829,"lafz":true}],"full":1,"dr":1},{"num":7511,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّهُ أَخْبَرَهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الدُّبَّاءِ وَالْمُزَفَّتِ أَنْ يُنْبَذَ فِيهِ."],"takhrij":"متفق عليه: رواه مسلم في الأشربة (1992: 30) عن قتيبة بن سعيد، حدثنا ليث، عن ابن شهاب، عن أنس بن مالك ققال: فذكره.","grade":"متفق عليه","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (1992:30) and al-Bukhari (5586).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Anas narrated that the Messenger of Allah ﷺ forbade making infusion in gourds and pitch-coated vessels."]},"buhuth":{"en":["The word “gourds” refers to dried gourds. The word “pitch-coated vessels” refers to vessels coated with pitch, which is a type of tar, as mentioned in al-Nihayah."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1992,"lafz":true},{"key":"bukhari","label":"البخاري","number":5586}],"full":1,"dr":1},{"num":7512,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ بن أَبِي طَالِبٍ قَالَ: نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الدُّبَّاءِ وَالْمُزَفَّتِ."],"takhrij":"متفق عليه: رواه البخاري في الأشربة (5594)، ومسلم في الأشربة (1194) كلاهما من طريق الأعمش، عن إبراهيم التيمي، عن الحارث بن سويد، عن علي قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5594) and Muslim (1994).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿAli ibn Abi Talib said: The Prophet ﷺ forbade gourds and pitch-coated vessels."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5594,"lafz":true},{"key":"muslim","label":"مسلم","number":1994,"n":5439},{"key":"muslim","label":"مسلم في الاشربه","number":1194}],"full":1},{"num":7513,"demo":false,"sanad":"","matn":["عن زينب بنت أبي سلمة قالت: نهى رسول الله صلى الله عليه وسلم عن الدباء والحنتم والمقير والمزفت. الحديث."],"takhrij":"صحيح: رواه البخاري في المناقب (3492) عن موسى (هو ابن كليب)، حدثنا عبد الواحد، حدثنا كليب، حدثتني ربيبة النبي صلى الله عليه وسلم وأظنها زينب قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3492).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Zaynab bint Abi Salamah said: The Messenger of Allah ﷺ forbade gourds, green jars, tar-coated vessels, and pitch-coated vessels. The hadith."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3492,"lafz":true}],"full":1},{"num":7514,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الدُّبَّاءِ وَالْحَنْتَمِ وَالْمُزَفَّتِ وَالنَّقِيرِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1995: 40) عن أبي بكر بن أبي شيبة، حدثنا علي بن مُسهر، عن الشيباني، عن حبيب، عن سعيد بن جبير، عن ابن عباس قال: فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1995:40).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ forbade gourds, green jars, pitch-coated vessels, and hollowed palm trunks."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1995,"lafz":true,"n":5176}],"full":1},{"num":7515,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الدُّبَّاءِ وَالْحَنْتَمِ وَالنَّقِيرِ وَالْمُزَفَّتِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1996: 44) عن يحيى بن أيوب، حدثنا ابن علية، أخبرنا سعيد بن أبي عروبة، عن قتادة، عن أبي نضرة، عن أبي سعيد الخدري قال: فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1996:44).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that the Messenger of Allah ﷺ forbade gourds, green jars, hollowed palm trunks, and pitch-coated vessels."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1996,"lafz":true,"n":5183}],"full":1},{"num":7516,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ أَشْهَدُ عَلَى ابْنِ عُمَرَ وَابْنِ عَبَّاسٍ أَنَّهُمَا شَهِدَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الدُّبَّاءِ وَالْحَنْتَمِ وَالْمُزَفَّتِ وَالنَّقِيرِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1997: 46) من طريق مروان بن معاوية، عن منصور بن حيان، عن سعيد بن جبير قال: فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1997:46).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Saʿid ibn Jubayr said: I testify concerning Ibn ʿUmar and Ibn ʿAbbas that they testified that the Messenger of Allah ﷺ forbade gourds, green jars, pitch-coated vessels, and hollowed palm trunks."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1997,"lafz":true}],"full":1},{"num":7517,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عُمَرَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَطَبَ النَّاسَ فِي بَعْضِ مَغَازِيهِ. قَالَ عَبْدُ اللَّهِ بْنُ عُمَرَ: فَأَقْبَلْتُ نَحْوَهُ، فَانْصَرَفَ قَبْلَ أَنْ أَبْلُغَهُ، فَسَأَلْتُ مَاذَا قَالَ؟ فَقِيلَ لِي: نَهَى أَنْ يُنْبَذَ فِي الدُّبَّاءِ وَالْمُزَفَّتِ.","وفي رواية: \"نهى عن المزفت والقرع\"."],"takhrij":"صحيح: رواه مالك في الأشربة (5) عن نافع، عن عبد الله بن عمر فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (5), Muslim (1997:48), and the other narration is from al-Nasa’i (5631).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ addressed the people during one of his campaigns. ʿAbdullah ibn ʿUmar said: I came toward him, but he finished before I reached him, so I asked what he had said. It was said to me: “He forbade making infusion in gourds and pitch-coated vessels.” In another narration: “He forbade pitch-coated vessels and gourds.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":5,"lafz":true},{"key":"muslim","label":"مسلم","number":1997,"n":5188},{"key":"nasai","label":"الرواية الأخرى للنسائي","number":5631}],"full":1,"dr":1},{"num":7518,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : لاَ تَنْتَبِذُوا فِي الدُّبَّاءِ وَ لاَ فِي الْمُزَفَّتِ، ثُمَّ يَقُولُ أبوهريرة: وَاجْتَنِبُوا الْحَنَاتِمَ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1993: 31) من طريق عمرو الناقد، حدثنا سفيان بن عيينة، عن الزهري قال: وأخبره أبو سلمة أنه سمع أبا هريرة يقول: فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1993:31).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Do not make infusion in gourds or pitch-coated vessels.” Then Abu Hurayrah would say: “And avoid green jars.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1993,"lafz":true}],"full":1},{"num":7519,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَنَّهُ نَهَى عَنِ الْمُزَفَّتِ وَالْحَنْتَمِ وَالنَّقِيرِ، قَالَ: قِيلَ: لأَبِي هُرَيْرَةَ: مَا الْحَنْتَمُ؟ قَالَ: الْجِرَارُ الْخُضْرُ. وَزَادَ فِي رِوَايَةِ: \"الدباء\"."],"takhrij":"صحيح: رواه مسلم في الأشربة (1993: 32) عن محمد بن حاتم، حدثنا بهز، حدثنا وهيب، عن سهيل، عن أبيه، عن أبي هريرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1993:32), and the other narration is from al-Nasa’i (5653).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he forbade pitch-coated vessels, green jars, and hollowed palm trunks. He said: It was said to Abu Hurayrah: “What are green jars?” He said: “Green earthenware jars.” In another narration, “gourds” is added."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1993,"lafz":true,"n":5169},{"key":"nasai","label":"الرواية الأخرى للنسائي","number":5653}],"full":1,"dr":1},{"num":7520,"demo":false,"sanad":"","matn":["عن ابن عمر قال: نهى رسول الله صلى الله عليه وسلم عن الحنتم والدباء والمزفت، قال: سمعته غير مرة.","وزاد في رواية قال: وأراه قال: \"والنقير\".","وفي رواية جعل \"الجر\" مكان \"الحنتم\" وزاد: انتبذوا في الأسقية."],"takhrij":"صحيح: رواه مسلم في الأشربة (1997: 54) من طريق محمد بن جعفر، حدثنا شعبة، عن محارب بن دثار قال: سمعت ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1997:54, 55).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: The Messenger of Allah ﷺ forbade green jars, gourds, and pitch-coated vessels. He said: I heard him more than once. In another narration, he added: “And I think he said: ‘hollowed palm trunks.’”","In another narration, “earthenware jars” appears in place of “green jars,” and he added: “Make infusion in leather water skins.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1997,"lafz":true}],"full":1,"dr":1},{"num":7521,"demo":false,"sanad":"","matn":["عن زَاذَانَ قَالَ قُلْتُ لاِبْنِ عُمَرَ حَدِّثْنِي بِمَا، نَهَى عَنْهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الأَشْرِبَةِ بِلُغَتِكَ وَفَسِّرْهُ لِي بِلُغَتِنَا فَإِنَّ لَكُمْ لُغَةً سِوَى لُغَتِنَا. فَقَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْحَنْتَمِ وَهِيَ الْجَرَّةُ وَعَنِ الدُّبَّاءِ وَهِيَ الْقَرْعَةُ وَعَنِ الْمُزَفَّتِ وَهُوَ الْمُقَيَّرُ وَعَنِ النَّقِيرِ وَهْىَ النَّخْلَةُ تُنْسَحُ نَسْحًا وَتُنْقَرُ نَقْرًا وَأَمَرَ أَنْ يُنْتَبَذَ فِي الأَسْقِيَةِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1997: 57) عن عبيد الله بن معاذ، حدثنا أبي، حدثنا شعبة، عن عمرو بن مرة، حدثني زاذان به.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1997:57).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Zadhan said: I said to Ibn ʿUmar: “Narrate to me what the Prophet ﷺ forbade among drinks in your language, and explain it to me in our language, for you have a language different from ours.” He said: The Messenger of Allah ﷺ forbade green jars, which are earthenware jars; gourds, which are dried gourds; pitch-coated vessels, which are coated with tar; and hollowed palm trunks, which are palm trunks stripped and hollowed out. He commanded that infusion be made in leather water skins."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1997,"lafz":true,"n":5199}],"full":1},{"num":7522,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، وَابْنِ، عُمَرَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ النَّقِيرِ وَالْمُزَفَّتِ وَالدُّبَّاءِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1998: 59) من طريق زهير أبي خيثمة، عن أبي الزبير، عن جابر وابن عمر قالا: فذكراه.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1998:59).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Jabir ibn ʿAbdullah and Ibn ʿUmar narrated that the Messenger of Allah ﷺ forbade hollowed palm trunks, pitch-coated vessels, and gourds."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1998,"lafz":true}],"full":1},{"num":7523,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يُنْبَذَ فِي الدُّبَّاءِ وَالْمُزَفَّتِ."],"takhrij":"حسن: رواه مالك في الأشربة (6) عن العلاء بن عبد الرحمن بن يعقوب، عن أبيه، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Malik (6).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ forbade making infusion in gourds and pitch-coated vessels."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":6,"lafz":true,"n":5}],"full":1,"dr":1},{"num":7524,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ بن أَبِي طَالِبٍ قَالَ: نَهَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الدُّبَّاءِ وَالْحَنْتَمِ وَالنَّقِيرِ وَالْجِعَةِ."],"takhrij":"صحيح: رواه أبو داود (3697)، والنسائي (5171، 5171) وأحمد (963، 1163) كلهم من طرق عن إسماعيل بن سُميع، ثنا مالك بن عمير، عن علي فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3697), al-Nasa’i (5171), and Ahmad (963, 1163). The wording is from Abu Dawud.","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿAli ibn Abi Talib said: The Messenger of Allah ﷺ forbade us from gourds, green jars, hollowed palm trunks, and barley beer."]},"buhuth":{"en":["His statement, “barley beer,” refers to an intoxicating drink made from barley, as mentioned in al-Nihayah."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3697,"lafz":true},{"key":"nasai","label":"النسائي","number":5171,"n":5170},{"key":"ahmad","label":"مسند الإمام أحمد","number":963,"n":924},{"key":"ahmad","label":"احمد","number":1163,"n":924}],"full":1,"dr":1},{"num":7525,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الدُّبَّاءِ."],"takhrij":"صحيح: رواه النسائي (5624) عن محمود بن غيلان، ثنا أبو داود (هو الطيالسي)، ثنا شعبة، عن إبراهيم بن ميسرة، عن طاوس، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (5624).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ forbade gourds."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":5624,"lafz":true,"n":5624}],"full":1,"dr":1},{"num":7526,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ زَيْدٍ، وَعِكْرِمَةَ، أَنَّهُمَا كَانَا يَكْرَهَانِ الْبُسْرَ وَحْدَهُ وَيَأْخُذَانِ ذَلِكَ عَنِ ابْنِ عَبَّاسٍ. وَقَالَ ابْنُ عَبَّاسٍ أَخْشَى أَنْ يَكُونَ الْمُزَّاءَ الَّذِي نُهِيَتْ عَنْهُ عَبْدُ الْقَيْسِ. فَقُلْتُ لِقَتَادَةَ مَا الْمُزَّاءُ قَالَ النَّبِيذُ فِي الْحَنْتَمِ وَالْمُزَفَّتِ."],"takhrij":"حسن: رواه أبوداود (3709) عن محمد بن بشار، ثنا معاذ بن هشام، قال: حدثني أبي، عن قتادة، عن جابر بن زيد وعكرمة به.","grade":"حسن","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3709). It was also said in explanation of “muzza’” that it is made by mixing unripe dates and dates, as mentioned in al-Nihayah.","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Jabir ibn Zayd and ʿIkrimah disliked making drink from unripe dates alone, and they took that from Ibn ʿAbbas. Ibn ʿAbbas said: “I fear that it may be the muzza’ from which ʿAbd al-Qays were forbidden.” I said to Qatadah: “What is muzza’?” He said: “Infusion made in green jars and pitch-coated vessels.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3709,"lafz":true}],"full":1,"dr":1},{"num":7527,"demo":false,"sanad":"","matn":["عَنِ الْفُضَيْلِ بْنِ زَيْدٍ الرَّقَاشِيِّ، قَالَ: كُنَّا عِنْدَ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ، قَالَ: فَتَذَاكَرْنَا الشَّرَابَ، فَقَالَ: الْخَمْرُ حَرَامٌ. قُلْتُ لَهُ: الْخَمْرُ حَرَامٌ فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ. قَالَ: فَأَيشْ تُرِيدُ، تُرِيدُ مَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنِ الدُّبَّاءِ وَالْحَنْتَمِ وَالْمُزَفَّتِ قَالَ: قُلْتُ: مَا الْحَنْتَمُ؟ قَالَ: كُلُّ خَضْرَاءَ وَبَيْضَاءَ. قَالَ: قُلْتُ: مَا الْمُزَفَّتُ؟ قَالَ: كُلُّ مُقَيَّرٍ مِنْ زِقٍّ أَوْ غَيْرِهِ."],"takhrij":"حسن: رواه أحمد (16795) عن يونس بن محمد، ثنا عبد الواحد، ثنا عاصم الأحول، عن الفضيل بن زيد الرقاشي قال: فذكره.","grade":"حسن","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (16795).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Fudayl ibn Zayd al-Raqashi said: We were with ʿAbdullah ibn Mughaffal and discussed drink. He said: “Wine is forbidden.” I said to him: “Wine is forbidden in the Book of Allah, the Mighty and Majestic.” He said: “What do you want? Do you want what I heard from the Messenger of Allah ﷺ? I heard the Messenger of Allah ﷺ forbid gourds, green jars, and pitch-coated vessels.” I said: “What are the green jars?” He said: “Every green or white jar.” I said: “What are pitch-coated vessels?” He said: “Anything coated with pitch, whether a leather water skin or something else.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":16795,"n":16795,"lafz":true}],"full":1,"dr":1},{"num":7528,"demo":false,"sanad":"","matn":["عَنْ مَيْمُونَةَ، زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّهُ قَالَ: لَا تَنْبِذُوا فِي الدُّبَّاءِ، وَلَا فِي الْمُزَفَّتِ، وَلَا فِي الْحَنْتَمِ، وَلَا فِي النَّقِيرِ قَالَ عَبْدُ الرَّحْمَنِ: وَلَا فِي الْجِرَارِ، وَكُلُّ مُسْكِرٍ حَرَامٌ."],"takhrij":"حسن: رواه أحمد (26823)، والطبراني في الكبير (23/439) من طريق زهير بن محمد، عن عبد الله بن محمد بن عقيل، عن القاسم بن محمد، عن عائشة.","grade":"حسن","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (26823) and al-Tabarani in al-Kabir (23/439).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Maymunah, the wife of the Prophet ﷺ, narrated that he said: “Do not make infusion in gourds, pitch-coated vessels, green jars, hollowed palm trunks, or earthenware jars. Every intoxicant is forbidden.”"]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":23},{"key":"ahmad","label":"مسند الإمام أحمد","number":26823,"n":26823,"lafz":true}],"full":1,"dr":1},{"num":7529,"demo":false,"sanad":"","matn":["عَنْ أَبِي شِمْرٍ الضُّبَعِيِّ، قَالَ: سَمِعْتُ عَائِذَ بْنَ عَمْرٍو، يَنْهَى عَنِ الدُّبَّاءِ، وَالْحَنْتَمِ، وَالْمُزَفَّتِ، وَالنَّقِيرِ، فَقُلْتُ لَهُ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَ: نَعَمْ."],"takhrij":"حسن: رواه أحمد (20638)، والطبراني في الكبير (18/18-19) كلاهما من طريق شعبة، عن أبي شمر الضبعي قال: فذكره.","grade":"حسن","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (20638) and al-Tabarani in al-Kabir (18/18–19).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Shamir al-Dubʿī said: I heard ʿĀ’idh ibn ʿAmr forbidding gourds, green jars, pitch-coated vessels, and hollowed palm trunks. I said to him: “Was this from the Prophet ﷺ?” He said: “Yes.”"]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":18},{"key":"ahmad","label":"مسند الإمام أحمد","number":20638,"n":20638,"lafz":true}],"full":1,"dr":1},{"num":7530,"demo":false,"sanad":"","matn":["عن عَبْدِ الرَّحْمَنِ بن جوشن، قَالَ: حَدَّثَنِي أَبِي، قَالَ: كَانَ أَبُو بَكْرَةَ يُنْتَبَذُ لَهُ فِي جَرٍّ، فَقَدِمَ أَبُو بَرْزَةَ مِنْ غَيْبَةٍ كَانَ غَابَهَا فَنَزَلَ بِمَنْزِلِ أَبِي بَكْرَةَ قَبْلَ أَنْ يَأْتِيَ مَنْزِلَهُ فَلَمْ يَجِدْ أَبَا بَكْرَةَ فِي مَنْزِلِهِ، فَوَقَفَ عَلَى امْرَأَةٍ لَهُ يُقَالُ لَهَا مَيْسَةُ، فَسَأَلَهَا عَنْ أَبِي بَكْرَةَ وَعَنْ حَالِهِ، وَنَظَرَ فَأَبْصَرَ الْجَرَّةَ الَّتِي فِيهَا النَّبِيذُ، فَقَالَ: مَا فِي هَذِهِ الْجَرَّةِ؟ قَالَتْ: نَبِيذٌ لِأَبِي بَكْرَةَ، فَقَالَ: لَوَدِدْتُ أَنَّكِ جَعَلْتِيهِ فِي سِقَاءٍ! ثُمَّ خَرَجَ، فَأَمَرَتْ بِالنَّبِيذِ فَحُوِّلَ فِي سِقَاءٍ ثُمَّ عَلَّقَتْهُ، فَجَاءَ أَبُو بَكْرَةَ فَأَخْبَرَتْهُ عَنْ أَبِي بَرْزَةَ وَعَنْ قُدُومِهِ، ثُمَّ أَبْصَرَ السِّقَاءَ فَقَالَ: مَا هَذَا السِّقَاءُ؟ فَقَالَتْ: قَالَ أَبُو بَرْزَةَ كَذَا وَكَذَا، فَحَوَّلْتُ نَبِيذَكَ فِي السِّقَاءِ. فَقَالَ: مَا أَنَا بِشَارِبٍ مِنْهُ شَيْئًا، آللهِ إِنْ جَعَلْتِ الْعَسَلَ فِي جَرٍّ لَيَحْرُمَنَّ عَلَيَّ، وَلَئِنْ جَعَلْتِ الْخَمْرَ فِي سِقَاءٍ لَيَحِلَّنَّ لِي، إِنَّا قَدْ عَرَفْنَا الَّذِي نُهِينَا عَنْهُ، نُهِينَا عَنِ الدُّبَّاءِ وَالنَّقِيرِ وَالْحَنْتَمِ وَالْمُزَفَّتِ؛ فَأَمَّا الدُّبَّاءُ فَإِنَّا مَعْشَرَ ثَقِيفَ بِالطَّائِفِ كُنَّا نَأْخُذُ الدُّبَّاءَ فَنَخْرُطُ فِيهَا عَنَاقِيدَ الْعِنَبِ ثُمَّ نَدْفِنُهَا، ثُمَّ نَتْرُكُهَا حَتَّى تَهْدِرَ ثُمَّ تَمُوتَ، وَأَمَّا النَّقِيرُ فَإِنَّ أَهْلَ الْيَمَامَةِ كَانُوا يَنْقُرُونَ أَصْلَ النَّخْلَةِ فَيَشْدَخُونَ فِيهِ الرُّطَبَ وَالْبُسْرَ، ثُمَّ يَدَعُونَهُ حَتَّى يَهْدِرَ ثُمَّ يَمُوتَ، وَأَمَّا الْحَنْتَمُ فَجِرَارٌ كَانَ يُحْمَلُ إِلَيْنَا فِيهَا الْخَمْرُ، وَأَمَّا الْمُزَفَّتُ فَهِيَ هَذِهِ الْأَوْعِيَةُ الَّتِي فِيهَا هَذَا الزِّفْتُ."],"takhrij":"حسن: رواه أبو داود الطيالسي (923)، والبزار (3689)، والبيهقي (8/309)، وابن حبان (5407) كلهم من طريق عيينة بن عبد الرحمن بن جوشن، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud al-Tayalisi (923), al-Bazzar (3689), al-Bayhaqi (8/309), and authenticated by Ibn Hibban (5407).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿAbd al-Rahman ibn Jawshan said: Infusion used to be made for Abu Bakrah in an earthenware jar. Abu Barzah returned from an absence and stopped at Abu Bakrah’s house before going to his own house. He did not find Abu Bakrah at home, so he came upon a wife of his named Maysah. He asked her about Abu Bakrah and his condition. Then he looked and saw the jar that contained the infusion. He said: “What is in this jar?” She said: “Infusion for Abu Bakrah.” He said: “I wish you had put it in a leather water skin.” Then he left. She ordered that the infusion be transferred into a leather water skin, then she hung it up. Abu Bakrah came, and she told him about Abu Barzah and his arrival. Then he saw the water skin and said: “What is this water skin?” She said: “Abu Barzah said such-and-such, so I transferred your infusion into the water skin.” He said: “I will not drink any of it. By Allah, if I put honey in an earthenware jar, would it become forbidden for me? And if I put wine in a leather water skin, would it become lawful for me? We know what we were forbidden from. We were forbidden from gourds, hollowed palm trunks, green jars, and pitch-coated vessels. As for gourds, we, the people of Thaqif in Ta’if, used to take gourds, strip clusters of grapes into them, bury them, and leave them until they fermented loudly, then settled. As for hollowed palm trunks, the people of Yamamah used to hollow out the base of a palm tree, crush fresh and unripe dates in it, and leave it until it fermented loudly, then settled. As for green jars, they were jars in which wine used to be brought to us. As for pitch-coated vessels, they are these containers that contain this pitch.”"]}},"tuhfa":{},"refs":[{"key":"tayalisi","label":"أبو داود الطيالسي","number":923,"lafz":true},{"key":"bazzar","label":"البزار","number":3689},{"key":"kubrabayhaqi","label":"البيهقي","number":8},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":5407},{"key":"sh12862","label":"البزار","number":3689}],"full":1,"dr":1},{"num":7531,"demo":false,"sanad":"","matn":["عَنِ عُيَيْنَةَ بْنِ عَبْدِ الرَّحْمَنِ، حَدَّثَنِي أَبِي، قَالَ: جَاءَ رَجُلٌ إِلَى ابْنِ عَبَّاسٍ، فَقَالَ: إِنِّي رَجُلٌ مِنْ أَهْلِ خُرَاسَانَ، وَإِنَّ أَرْضَنَا أَرْضٌ بَارِدَةٌ، فَذَكَرَ مِنْ ضُرُوبِ الشَّرَابِ، فَقَالَ: اجْتَنِبْ مَا أَسْكَرَ مِنْ زَبِيبٍ أَوْ تَمْرٍ أَوْ مَا سِوَى ذَلِكَ، قَالَ: مَا تَقُولُ فِي نَبِيذِ الْجَرِّ؟ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ نَبِيذِ الْجَرِّ."],"takhrij":"حسن: رواه النسائي (5616)، وأحمد (2009) كلاهما عن عيينة بن عبدالرحمن به فذكره. والسياق لأحمد.","grade":"حسن","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (5616) and Ahmad (2009). The wording is from Ahmad.","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿUyaynah ibn ʿAbd al-Rahman narrated from his father: A man came to Ibn ʿAbbas and said: “I am a man from Khurasan, and our land is cold,” then he mentioned different kinds of drink. He said: “Avoid whatever intoxicates, whether from raisins, dates, or anything else.” He said: “What do you say about infusion made in earthenware jars?” He said: “The Messenger of Allah ﷺ forbade infusion made in earthenware jars.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":5616,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":2009,"n":2009}],"full":1,"dr":1},{"num":7532,"demo":false,"sanad":"","matn":["عَنْ دُلْجَةَ بْنِ قَيْسٍ، أَنَّ الْحَكَمَ الْغِفَارِيَّ، قَالَ لِرَجُلٍ: أَوْ قَالَ لَهُ رَجُلٌ: أَتَذْكُرُ حِينَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ النَّقِيرِ، وَالْمُقَيَّرِ، أَوْ أَحَدِهِمَا، وَعَنِ الدُّبَّاءِ، وَالْحَنْتَمِ قَالَ: نَعَمْ، وَأَنَا أَشْهَدُ عَلَى ذَلِكَ."],"takhrij":"حسن: رواه أحمد (17860)، والطبراني في الكبير (3/235) كلاهما من طريق سليمان التيمي، عن أبي تميمة، عن دلجة بن قيس قال: فذكره.","grade":"حسن","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (17860) and al-Tabarani in al-Kabir (3/235).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Duljah ibn Qays narrated that al-Hakam al-Ghifari said to a man — or a man said to him: “Do you remember when the Messenger of Allah ﷺ forbade hollowed palm trunks and pitch-coated vessels — or one of them — as well as gourds and green jars?” He said: “Yes, and I bear witness to that.”"]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":3},{"key":"ahmad","label":"مسند الإمام أحمد","number":17860,"n":17860,"lafz":true}],"full":1,"dr":1},{"num":7533,"demo":false,"sanad":"","matn":["عن عَائِشَةَ قَالَتْ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنْ شَرَابٍ صُنِعَ فِي دُبُّاءٍ أَوْ حَنْتَمٍ أَوْ مُزَفَّتٍ لاَ يَكُونُ زَيْتًا أَوْ خَلاًّ."],"takhrij":"حسن: رواه النسائي (5636) عن سويد، أنبأنا عبد الله (هو ابن المبارك) عن عون بن صالح البارقي، عن زينب بنت نصر وجميلة بنت عباد، أنهما سمعتا عائشة فذكرته.","grade":"حسن","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (5636).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿA’ishah said: I heard the Messenger of Allah ﷺ forbidding a drink made in a gourd, green jar, or pitch-coated vessel, unless it was oil or vinegar."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":5636,"lafz":true,"n":5636}],"full":1,"dr":1},{"num":7534,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن أَبِي أَوْفَى رَضِيَ اللَّهُ عَنْهُمَا قَالَ نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْجَرِّ الأَخْضَرِ. قُلْتُ أَنَشْرَبُ فِي الأَبْيَضِ قَالَ لاَ."],"takhrij":"صحيح: رواه البخاري في الأشربة (5596) عن موسى بن إسماعيل، حدثنا عبدالواحد، ثنا الشيباني، قال: سمعت عبد الله بن أبي أوفى قال: فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5596). “Earthenware jar” refers to a vessel made from pottery.","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿAbdullah ibn Abi Awfa said: The Prophet ﷺ forbade green earthenware jars. I said: “May we drink from white ones?” He said: “No.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5596,"lafz":true}],"full":1,"dr":1},{"num":7535,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْجَرِّ أَنْ يُنْبَذَ فِيهِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1996: 43) من طريق سليمان التيمي، عن أبي نضرة، عن أبي سعيد قال: فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1996:43).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that the Messenger of Allah ﷺ forbade making infusion in earthenware jars."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1996,"lafz":true}],"full":1,"dr":1},{"num":7536,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ سَأَلْتُ ابْنَ عُمَرَ عَنْ نَبِيذِ الْجَرِّ، فَقَالَ حَرَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَبِيذَ الْجَرِّ. فَأَتَيْتُ ابْنَ عَبَّاسٍ فَقُلْتُ أَلاَ تَسْمَعُ مَا يَقُولُ ابْنُ عُمَرَ قَالَ وَمَا يَقُولُ قُلْتُ قَالَ حَرَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَبِيذَ الْجَرِّ. فَقَالَ صَدَقَ ابْنُ عُمَرَ حَرَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَبِيذَ الْجَرِّ. فَقُلْتُ وَأَىُّ شَىْءٍ نَبِيذُ الْجَرِّ فَقَالَ كُلُّ شَىْءٍ يُصْنَعُ مِنَ الْمَدَرِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1997: 47) عن شيبان بن فروخ، حدثنا جرير بن حازم، حدثنا يعلى بن حكيم، عن سعيد بن جبير قال: فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1997:47).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Saʿid ibn Jubayr said: I asked Ibn ʿUmar about infusion made in earthenware jars. He said: “The Messenger of Allah ﷺ forbade infusion made in earthenware jars.” I came to Ibn ʿAbbas and said: “Do you not hear what Ibn ʿUmar says?” He said: “What does he say?” I said: “The Messenger of Allah ﷺ forbade infusion made in earthenware jars.” He said: “Ibn ʿUmar has spoken the truth. The Messenger of Allah ﷺ forbade infusion made in earthenware jars.” I said: “What is infusion made in earthenware jars?” He said: “Anything made in clay vessels.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1997,"lafz":true,"n":5187}],"full":1,"dr":1},{"num":7537,"demo":false,"sanad":"","matn":["عَنْ ثَابِتٍ، قَالَ قُلْتُ لاِبْنِ عُمَرَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ نَبِيذِ الْجَرِّ قَالَ فَقَالَ قَدْ زَعَمُوا ذَاكَ. قُلْتُ أَنَهَى عَنْهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ قَدْ زَعَمُوا ذَاكَ.","وفي رواية: أن رجلا جاءه فقال: أ نهى النبي صلى الله عليه وسلم أن ينبذ في الجر والدباء؟ قال: نعم."],"takhrij":"صحيح: رواه مسلم في الأشربة (1997: 50) عن يحيى بن يحيى، أخبرنا حماد بن زيد، عن ثابت فذكره. والرواية الأخرى من طريق ابن جريج، أخبرني ابن طاوس، عن أبيه، عن ابن عمر.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1997:50).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Thabit said: I said to Ibn ʿUmar: “Did the Messenger of Allah ﷺ forbid infusion made in earthenware jars?” He said: “They have claimed that.” I said: “Did the Messenger of Allah ﷺ forbid it?” He said: “They have claimed that.” In another narration: A man came to him and said: “Did the Prophet ﷺ forbid making infusion in earthenware jars and gourds?” He said: “Yes.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1997,"lafz":true,"n":5190}],"full":1},{"num":7538,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الجِرار، والدباء، والظروف المزفتة."],"takhrij":"صحيح: رواه النسائي (5635)، وابن ماجه (3408)، وأحمد (10971) كلهم من طرق عن الأوزاعي، عن يحيى بن أبي كثير، عن أبي سلمة، عن أبي هريرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (5635), Ibn Majah (3408), and Ahmad (10971). The wording is from al-Nasa’i.","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ forbade earthenware jars, gourds, and pitch-coated containers."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":5635,"lafz":true,"n":5635},{"key":"ibnmajah","label":"ابن ماجه","number":3408},{"key":"ahmad","label":"مسند الإمام أحمد","number":10971,"n":10971}],"full":1,"dr":1},{"num":7539,"demo":false,"sanad":"","matn":["عَنْ قَتَادَةَ، قَالَ: سَأَلْتُ أَنَسًا عَنْ نَبِيذِ الْجَرِّ، فَقَالَ: لَمْ أَسْمَعْ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهِ شَيْئًا، قَالَ: وَكَانَ أَنَسٌ يَكْرَهُهُ."],"takhrij":"صحيح: رواه أحمد (13937)، وأبو يعلى (3241)، والبزار 7161) كلهم من طريق أبي داود (هو الطيالسي)، عن شعبة، عن قتادة فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (13937), Abu Yaʿla (3241), and al-Bazzar (7161).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Qatadah said: I asked Anas about infusion made in earthenware jars. He said: “I did not hear anything from the Messenger of Allah ﷺ concerning it.” He said: Anas used to dislike it."]}},"tuhfa":{},"refs":[{"key":"sh12520","label":"أبو يعلى","number":3241},{"key":"bazzar","label":"البزار","number":7161},{"key":"ahmad","label":"مسند الإمام أحمد","number":13937,"n":13937,"lafz":true}],"full":1,"dr":1},{"num":7540,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ، قَالَ: قَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَخَطَبَ، فَنَهَى عَنِ الدُّبَّاءِ، وَالْمُزَفَّتِ."],"takhrij":"حسن: رواه أحمد (20186)، والطبراني في الكبير (7/215) كلاهما من طريق عبد الله بن المبارك، عن وقاء بن إياس، عن علي بن ربيعة، عن سمرة بن جندب قال: فذكره.","grade":"حسن","chapter_ar":"باب في ذكر الأوعية التي نهي أن ينتبذ فيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (20186) and al-Tabarani in al-Kabir (7/215).","chapter_en":"Mention of the Containers in Which Making Infusions Was Forbidden","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Samurah ibn Jundab said: The Prophet ﷺ stood and delivered a sermon, and he forbade gourds and pitch-coated vessels."]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":7},{"key":"ahmad","label":"مسند الإمام أحمد","number":20186,"n":20186,"lafz":true}],"full":1,"dr":1},{"num":7541,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الظُّرُوفِ فَقَالَتِ الأَنْصَارُ إِنَّهُ لاَ بُدَّ لَنَا مِنْهَا. قَالَ فَلاَ إِذًا."],"takhrij":"صحيح: رواه البخاري في الأشربة (5592) عن يوسف بن موسى، حدثنا محمد بن عبد الله أبو أحمد الزبيري، حدثنا سفيان، عن منصور، عن سالم (هو ابن أبي الجعد) عن جابر قال: فذكره.","grade":"صحيح","chapter_ar":"باب ترخيص النبي ﷺ في الأوعية والظروف واجتناب المسكر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5592).","chapter_en":"The Prophet’s ﷺ Permission Concerning Vessels and Containers While Avoiding Intoxicants","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ forbade certain containers. The Ansar said: “They are necessary.” He said: “Then not, in that case.”"]},"buhuth":{"en":["His statement, “Then not, in that case,” is a response meaning: if it is necessary for you, then do not leave them."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5592,"lafz":true}],"full":1,"dr":1},{"num":7542,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ لَمَّا نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الأَسْقِيَةِ قِيلَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْسَ كُلُّ النَّاسِ يَجِدُ سِقَاءً فَرَخَّصَ لَهُمْ فِي الْجَرِّ غَيْرِ الْمُزَفَّتِ."],"takhrij":"متفق عليه: رواه البخاري في الأشربة (5593)، ومسلم في الأشربة (2000: 66) كلاهما من طريق سفيان (هو ابن عيينة)، عن سليمان بن أبي مسلم الأحول، عن مجاهد، عن أبي عياض، عن عبد الله بن عمرو قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ترخيص النبي ﷺ في الأوعية والظروف واجتناب المسكر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5593) and Muslim (2000:66).","chapter_en":"The Prophet’s ﷺ Permission Concerning Vessels and Containers While Avoiding Intoxicants","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr said: When the Prophet ﷺ forbade certain containers, it was said to the Prophet ﷺ: “Not everyone can find a leather water skin.” So he permitted them to use earthenware jars that were not pitch-coated."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5593,"lafz":true},{"key":"muslim","label":"مسلم","number":2000}],"full":1},{"num":7543,"demo":false,"sanad":"","matn":["عَنْ سَهْلٍ، قَالَ لَمَّا عَرَّسَ أَبُو أُسَيْدٍ السَّاعِدِيُّ دَعَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابَهُ، فَمَا صَنَعَ لَهُمْ طَعَامًا وَلاَ قَرَّبَهُ إِلَيْهِمْ إِلاَّ امْرَأَتُهُ أُمُّ أُسَيْدٍ، بَلَّتْ تَمَرَاتٍ فِي تَوْرٍ مِنْ حِجَارَةٍ مِنَ اللَّيْلِ، فَلَمَّا فَرَغَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الطَّعَامِ أَمَاثَتْهُ لَهُ فَسَقَتْهُ، تُتْحِفُهُ بِذَلِكَ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5182)، ومسلم في الأشربة (2006: 87) كلاهما من طريق سعيد بن أبي مريم، حدثنا محمد أبو غسّان، حدثني أبو حازم، عن سهل بن سعد قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ترخيص النبي ﷺ في الأوعية والظروف واجتناب المسكر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5182) and Muslim (2006:87).","chapter_en":"The Prophet’s ﷺ Permission Concerning Vessels and Containers While Avoiding Intoxicants","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Sahl ibn Saʿd said: When Abu Usayd al-Saʿidi got married, he invited the Prophet ﷺ and his Companions. No one prepared food for them or served it except his wife, Umm Usayd. She had soaked some dates overnight in a stone vessel. When the Prophet ﷺ finished eating, she dissolved it for him and gave it to him to drink, honoring him with it."]},"buhuth":{"en":["His statement, “dissolved it,” means she mixed it until it dissolved. The “stone vessel” is a known vessel mentioned by the Arabs, from which one drinks and from which one may perform ablution. It may be made of copper or stone, as in this hadith. His statement, “honoring him with it,” is the wording in al-Bukhari; in Sahih Muslim it says: “singling him out with it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5182,"lafz":true},{"key":"muslim","label":"مسلم","number":2006}],"full":1,"dr":1,"rep":[6533]},{"num":7544,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ:  كَانَ يُنْتَبَذُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سِقَاءٍ، فَإِذَا لَمْ يَجِدُوا سِقَاءً نُبذَ لَهُ فِي تَوْرٍ مِنْ حِجَارَةٍ، فَقَالَ بعضُ الْقَوْمِ- وَأَنَا أَسْمَعُ لأَبِي الزُّبَيْرِ-: مِنْ بِرَامٍ؟ قَالَ: مِنْ بِرَامٍ. وَزَادَ فِي رِوَايَةِ: \"ونهى رسول اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ الدُّبَّاءِ وَالنَّقِيرِ وَالْمُزَفَّتِ\"."],"takhrij":"صحيح: رواه مسلم في الأشربة (1999: 62) من طريق زهير بن أبي خيثمة، عن أبي الزبير، عن جابر قال: فذكره.","grade":"صحيح","chapter_ar":"باب ترخيص النبي ﷺ في الأوعية والظروف واجتناب المسكر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1999:62). The other narration is from al-Nasa’i (5648).","chapter_en":"The Prophet’s ﷺ Permission Concerning Vessels and Containers While Avoiding Intoxicants","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Jabir said: Infusion used to be made for the Messenger of Allah ﷺ in a leather water skin. If they did not find a leather water skin, it was made for him in a stone vessel. One of the people said — while I was listening to Abu al-Zubayr — “Made of stone pots?” He said: “Made of stone pots.” Another narration adds: “The Messenger of Allah ﷺ forbade gourds, hollowed palm trunks, and pitch-coated vessels.”"]},"buhuth":{"en":["His statement, “stone pots,” is the plural of a pot originally made from stone."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1999,"lafz":true,"n":5206},{"key":"nasai","label":". والرواية الأخرى للنسائي","number":5648}],"full":1,"dr":1},{"num":7545,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الحُصيب أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  نَهَيْتُكُمْ عَنِ الظُّرُوفِ، وَإِنَّ الظُّرُوفَ أَوْ ظَرْفًا لاَ يحلُّ شَيْئًا وَ لاَ يُحَرِّمُهُ، وَكُلُّ مُسْكِرٍ حَرَامٌ."],"takhrij":"صحيح: رواه مسلم في الأشربة (977: 64) عن حجاج بن الشاعر، ثنا ضحاك بن مخلد، عن سفيان، عن علقمة بن مرثد، عن ابن بريدة، عن أبيه قال: فذكره.","grade":"صحيح","chapter_ar":"باب ترخيص النبي ﷺ في الأوعية والظروف واجتناب المسكر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (977:64).","chapter_en":"The Prophet’s ﷺ Permission Concerning Vessels and Containers While Avoiding Intoxicants","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Buraydah ibn al-Husayb narrated that the Messenger of Allah ﷺ said: “I forbade you from certain containers, but containers — or a container — do not make anything lawful or unlawful. Every intoxicant is forbidden.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":977,"lafz":true}],"full":1,"rep":[7485]},{"num":7546,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الحصيب قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ :  نَهَيْتُكُمْ عَنِ النَّبِيذِ إِلاَّ فِي سِقَاءٍ، فَاشْرَبُوا فِي الأَسْقِيَةِ كُلِّهَا، وَ لاتشربوا مُسْكِرًا."],"takhrij":"صحيح: رواه مسلم في الأشربة (977: 63) من طريق أبي سنان ضِرار بن مرة، عن محارب بن دثار، عن عبد الله بن بريدة، عن أبيه قال: فذكره.","grade":"صحيح","chapter_ar":"باب ترخيص النبي ﷺ في الأوعية والظروف واجتناب المسكر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (977:63).","chapter_en":"The Prophet’s ﷺ Permission Concerning Vessels and Containers While Avoiding Intoxicants","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Buraydah ibn al-Husayb said: The Messenger of Allah ﷺ said: “I forbade you from date infusion except in a leather water skin. So drink from all leather water skins, but do not drink anything intoxicating.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":977,"lafz":true}],"full":1,"dr":1},{"num":7547,"demo":false,"sanad":"","matn":["عَنْ أَبِيهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَا هُوَ يَسِيرُ إِذْ حَلَّ بِقَوْمٍ فَسَمِعَ لَهُمْ لَغَطًا فَقَالَ مَا هَذَا الصَّوْتُ. قَالُوا يَا نَبِيَّ اللَّهِ لَهُمْ شَرَابٌ يَشْرَبُونَهُ. فَبَعَثَ إِلَى الْقَوْمِ فَدَعَاهُمْ فَقَالَ فِي أَىِّ شَىْءٍ تَنْتَبِذُونَ. قَالُوا نَنْتَبِذُ فِي النَّقِيرِ وَالدُّبَّاءِ وَلَيْسَ لَنَا ظُرُوفٌ. فَقَالَ لاَ تَشْرَبُوا إِلاَّ فِيمَا أَوْكَيْتُمْ عَلَيْهِ. قَالَ فَلَبِثَ بِذَلِكَ مَا شَاءَ اللَّهُ أَنْ يَلْبَثَ ثُمَّ رَجَعَ عَلَيْهِمْ فَإِذَا هُمْ قَدْ أَصَابَهُمْ وَبَاءٌ وَاصْفَرُّوا. قَالَ مَا لِي أَرَاكُمْ قَدْ هَلَكْتُمْ. قَالُوا يَا نَبِيَّ اللَّهِ أَرْضُنَا وَبِيئَةٌ وَحَرَّمْتَ عَلَيْنَا إِلاَّ مَا أَوْكَيْنَا عَلَيْهِ. قَالَ اشْرَبُوا وَكُلُّ مُسْكِرٍ حَرَامٌ."],"takhrij":"حسن: رواه النسائي (5655) عن أبي علي محمد بن يحيى بن أيوب المروزي، ثنا عبد الله بن عثمان، ثنا عيسى بن عبيد الكندي خراساني، قال: سمعت عبد الله بن بريدة، عن أبيه قال: فذكره.","grade":"حسن","chapter_ar":"باب ترخيص النبي ﷺ في الأوعية والظروف واجتناب المسكر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (5655).","chapter_en":"The Prophet’s ﷺ Permission Concerning Vessels and Containers While Avoiding Intoxicants","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Buraydah narrated that while the Messenger of Allah ﷺ was traveling, he stopped among some people and heard loud voices from them. He said: “What is this sound?” They said: “O Prophet of Allah, they have a drink that they drink.” He sent for the people and called them. He said: “In what do you make infusion?” They said: “We make infusion in hollowed palm trunks and gourds, and we do not have other containers.” He said: “Do not drink except from what you can tie closed.” He said: This remained for as long as Allah willed. Then he returned to them, and they had been afflicted by disease and had become yellow. He said: “What is the matter with me that I see you ruined?” They said: “O Prophet of Allah, our land is disease-ridden, and you forbade us from everything except what we can tie closed.” He said: “Drink, but every intoxicant is forbidden.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":5655,"lafz":true,"n":5655}],"full":1,"dr":1},{"num":7548,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِنِّي كُنْتُ نَهَيْتُكُمْ عَنْ نَبِيذِ الأَوْعِيَةِ أَلاَ وَإِنَّ وِعَاءً لاَ يُحَرِّمُ شَيْئًا كُلُّ مُسْكِرٍ حَرَامٌ."],"takhrij":"حسن: رواه ابن ماجه (3406)، وصحّحه ابن حبان (5409) كلاهما من طريق ابن وهب، أخبرنا ابن جريج، عن أيوب بن هانئ، عن مسروق الأجدع، عن ابن مسعود فذكره.","grade":"حسن","chapter_ar":"باب ترخيص النبي ﷺ في الأوعية والظروف واجتناب المسكر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (3406), and authenticated by Ibn Hibban (5409).","chapter_en":"The Prophet’s ﷺ Permission Concerning Vessels and Containers While Avoiding Intoxicants","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Ibn Masʿud narrated that the Messenger of Allah ﷺ said: “I had forbidden you from infusions made in vessels. Indeed, a vessel does not make anything forbidden, and every intoxicant is forbidden.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":3406,"lafz":true},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":5409},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2783,"n":2780}],"full":1,"dr":1},{"num":7549,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنِّي نَهَيْتُكُمْ عَنْ زِيَارَةِ الْقُبُورِ فَزُورُوهَا، فَإِنَّ فِيهَا عِبْرَةً، وَنَهَيْتُكُمْ عَنِ النَّبِيذِ فَاشْرَبُوا، وَلَا أُحِلُّ مُسْكِرًا، وَنَهَيْتُكُمْ عَنِ الْأَضَاحِيِّ فَكُلُوا."],"takhrij":"حسن: رواه أحمد (11329) عن يحيى بن آدم، ثنا ابن المبارك، عن أسامة، عن محمد بن يحيى بن حبّان، عن عمه، عن أبي سعيد الخدري قال: فذكره.","grade":"حسن","chapter_ar":"باب ترخيص النبي ﷺ في الأوعية والظروف واجتناب المسكر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (11329).","chapter_en":"The Prophet’s ﷺ Permission Concerning Vessels and Containers While Avoiding Intoxicants","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: The Messenger of Allah ﷺ said: “I had forbidden you from visiting graves, so visit them, for in them there is a lesson. I had forbidden you from date infusion, so drink, but I do not permit any intoxicant. And I had forbidden you from sacrificial meat, so eat.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":11329,"n":11329,"lafz":true}],"full":1,"dr":1,"rep":[3894]},{"num":7550,"demo":false,"sanad":"","matn":["عن طلق بن عَلِيٍّ قَالَ: جَلَسْنَا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَاءَ وَفْدُ عَبْدِ الْقَيْسِ فَقَالَ: مَا لَكُمْ قَدِ اصْفَرَّتْ أَلْوَانُكُمْ، وَعَظُمَتْ بُطُونُكُمْ، وَظَهَرَتْ عُرُوقُكُمْ؟ قَالَ: قَالُوا: أَتَاكَ سَيِّدُنَا، فَسَأَلَكَ عَنْ شَرَابٍ كَانَ لَنَا مُوَافِقًا فَنَهَيْتَهُ عَنْهُ، وَكُنَّا بِأَرْضٍ وَخِمَةٍ، قَالَ: فَاشْرَبُوا مَا طَابَ لَكُمْ."],"takhrij":"حسن: رواه ابن أبي شيبة (24368) عن ملازم بن عمرو، عن عُجيبة بن عبد الحميد، عن عمه قيس بن طلق، عن أبيه طلق بن علي قال: فذكره.","grade":"حسن","chapter_ar":"باب ترخيص النبي ﷺ في الأوعية والظروف واجتناب المسكر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abi Shaybah (24368) and al-Tabarani (8256).","chapter_en":"The Prophet’s ﷺ Permission Concerning Vessels and Containers While Avoiding Intoxicants","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Talq ibn ʿAli said: We were sitting with the Prophet ﷺ when the delegation of ʿAbd al-Qays came. He said: “What is the matter with you that your complexions have turned yellow, your bellies have grown large, and your veins have become prominent?” They said: “Our leader came to you and asked you about a drink that suited us, and you forbade him from it, while we are in a feverish land.” He said: “Then drink what is wholesome for you.”"]}},"tuhfa":{},"refs":[{"key":"sh9944","label":"ابن أبي شيبة","number":24368,"lafz":true},{"key":"mujamkabir","label":"الطبراني","number":8256},{"key":"sh9944","label":"المصنف لابن أبي شيبة","number":23898,"n":23881}],"full":1,"dr":1,"rep":[9771]},{"num":7551,"demo":false,"sanad":"","matn":["عن المختار بن فلفل قَالَ: سَأَلْتُ أَنَسَ بْنَ مَالِكٍ عَنِ الشُّرْبِ فِي الْأَوْعِيَةِ، فَقَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُزَفَّتَةِ، وَقَالَ: كُلُّ مُسْكِرٍ حَرَامٌ، قَالَ: قُلْتُ: وَمَا الْمُزَفَّتَةُ؟ قَالَ: الْمُقَيَّرَةُ. قَالَ: قُلْتُ: فَالرَّصَاصُ وَالْقَارُورَةُ؟ قَالَ: مَا بَأْسٌ بِهِمَا قَالَ: قُلْتُ: فَإِنَّ نَاسًا يَكْرَهُونَهُمَا، قَالَ: دَعْ مَا يَرِيبُكَ إِلَى مَا لَا يَرِيبُكَ، فَإِنَّ كُلَّ مُسْكِرٍ حَرَامٌ. قَالَ: قُلْتُ لَهُ: صَدَقْتَ السُّكْرُ حَرَامٌ، فَالشَّرْبَةُ وَالشَّرْبَتَانِ، عَلَى طَعَامِنَا. قَالَ: مَا أَسْكَرَ كَثِيرُهُ، فَقَلِيلُهُ حَرَامٌ، وَقَالَ: الْخَمْرُ مِنَ الْعِنَبِ، وَالتَّمْرِ، وَالْعَسَلِ، وَالْحِنْطَةِ، وَالشَّعِيرِ، وَالذُّرَةِ، فَمَا خَمَّرْتَ مِنْ ذَلِكَ فَهِيَ الْخَمْرُ."],"takhrij":"حسن: رواه أحمد (12099)، وأبو يعلى (3966) كلاهما من طريق عبد الله بن إدريس، عن المختار بن فلفل فذكره، والسياق لأحمد.","grade":"حسن","chapter_ar":"باب ترخيص النبي ﷺ في الأوعية والظروف واجتناب المسكر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (12099) and Abu Yaʿla (3966). The wording is from Ahmad.","chapter_en":"The Prophet’s ﷺ Permission Concerning Vessels and Containers While Avoiding Intoxicants","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Al-Mukhtar ibn Fulful said: I asked Anas ibn Malik about drinking from vessels. He said: “The Messenger of Allah ﷺ forbade pitch-coated vessels, and said: ‘Every intoxicant is forbidden.’” I said: “What are pitch-coated vessels?” He said: “Those coated with tar.” I said: “What about vessels made of lead and glass?” He said: “There is no harm in them.” I said: “Some people dislike them.” He said: “Leave what causes you doubt for what does not cause you doubt, for every intoxicant is forbidden.” I said to him: “You have spoken the truth. Intoxication is forbidden, but what about one drink or two drinks with our food?” He said: “Whatever intoxicates in large amounts, a small amount of it is forbidden.” And he said: “Wine is from grapes, dates, honey, wheat, barley, and millet. Whatever ferments from that is wine.”"]}},"tuhfa":{},"refs":[{"key":"sh12520","label":"أبو يعلى","number":3966},{"key":"ahmad","label":"مسند الإمام أحمد","number":12099,"n":12099,"lafz":true}],"full":1,"dr":1},{"num":7552,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَالِكٍ الْأَشْجَعِيِّ، عَنْ أَبِيهِ، قَالَ: كَانَ نَبِيذٌ لِرَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فِي تَوْرٍ مِنْ حِجَارَةٍ."],"takhrij":"حسن: رواه الطبراني في الكبير (8/379) عن محمد بن عبدوس بن كامل، ثنا أحمد بن إبراهيم الموصلي، ثنا خلف بن خليفة، عن أبي مالك الأشجعي، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب ترخيص النبي ﷺ في الأوعية والظروف واجتناب المسكر","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (8/379).","chapter_en":"The Prophet’s ﷺ Permission Concerning Vessels and Containers While Avoiding Intoxicants","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Abu Malik al-Ashjaʿi narrated from his father that infusion used to be made for the Messenger of Allah ﷺ in a stone vessel."]},"buhuth":{"en":["The conclusion of the hadiths forbidding making infusion in these vessels is that the prohibition was abrogated, and making infusion in these vessels became permitted because other containers were not available to them. The matter became limited to avoiding intoxicants, and vessels neither make anything lawful nor unlawful. Rather, what is forbidden is the intoxicant itself, however intoxication occurs."]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":8,"lafz":true}],"full":1,"dr":1},{"num":7553,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ يَقُولُ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُنْتَبَذُ لَهُ أَوَّلَ اللَّيْلِ فَيَشْرَبُهُ إِذَا أَصْبَحَ يَوْمَهُ ذَلِكَ وَاللَّيْلَةَ الَّتِي تَجِيءُ وَالْغَدَ وَاللَّيْلَةَ الأُخْرَى وَالْغَدَ إِلَى الْعَصْرِ فَإِنْ بَقِيَ شَىْءٌ سَقَاهُ الْخَادِمَ أَوْ أَمَرَ بِهِ فَصُبَّ.","وفي لفظ: كان رسول الله صلى الله عليه وسلم يُنتبذ له في سقاء من ليلة الاثنين، فيشربه يوم الاثنين والثلاثاء إلى العصر، فإن فضل منه شيءٌ سقاه الخادمَ أو صبَّه."],"takhrij":"صحيح: رواه مسلم في الأشربة (2004: 79) عن عبيد الله بن معاذ العنبري، حدثنا أبي، حدثنا شعبة، عن يحيى بن عبيد أبي عمر البهراني قال: سمعت ابن عباس يقول: فذكره. واللفظ الآخر من رواية محمد بن جعفر، عن شعبة به.","grade":"صحيح","chapter_ar":"باب في المدة التي يُشرب فيها النبيذ","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2004:79).","chapter_en":"The Period During Which Date Infusion May Be Drunk","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas said: Infusion would be made for the Messenger of Allah ﷺ at the beginning of the night, and he would drink it when morning came on that day, and the following night, and the next day, and the following night, and the next day until the afternoon. If anything remained, he would give it to the servant to drink, or he would order it to be poured away. In another wording: Infusion would be made for the Messenger of Allah ﷺ in a leather water skin from Monday night, and he would drink it on Monday and Tuesday until the afternoon. If anything remained, he would give it to the servant to drink or pour it away."]},"buhuth":{"ar":["المدة المقدرة في هذا الحديث ثلاثة أيام وليلتان، إلى عصر اليوم الثالث، ثم سقاه الخادم، والسبب في ذلك أنه لم يظهر فيه ما يقتضي إراقته وإتلافه، لكن اتقاه في خاصة نفسه، أخذاً بغاية الورع، فسقاه الخادم؛ لأنه حلال جائز."],"en":["The period described in this hadith is three days and two nights, until the afternoon of the third day. Then he gave it to the servant to drink. The reason is that nothing had appeared in it requiring it to be poured away or destroyed, but he avoided it for himself out of the highest caution, and gave it to the servant because it was lawful and permissible."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2004,"lafz":true}],"full":1},{"num":7554,"demo":false,"sanad":"","matn":["عَنْ يَحْيَى أَبِي عُمَرَ النَّخَعِيِّ، قَالَ سَأَلَ قَوْمٌ ابْنَ عَبَّاسٍ عَنْ بَيْعِ الْخَمْرِ، وَشِرَائِهَا، وَالتِّجَارَةِ فِيهَا فَقَالَ أَمُسْلِمُونَ أَنْتُمْ قَالُوا نَعَمْ. قَالَ فَإِنَّهُ لاَ يَصْلُحُ بَيْعُهَا وَلاَ شِرَاؤُهَا وَلاَ التِّجَارَةُ فِيهَا. قَالَ فَسَأَلُوهُ عَنِ النَّبِيذِ فَقَالَ خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ ثُمَّ رَجَعَ وَقَدْ نَبَذَ نَاسٌ مِنْ أَصْحَابِهِ فِي حَنَاتِمَ وَنَقِيرٍ وَدُبَّاءٍ فَأَمَرَ بِهِ فَأُهْرِيقَ ثُمَّ أَمَرَ بِسِقَاءٍ فَجُعِلَ فِيهِ زَبِيبٌ وَمَاءٌ فَجُعِلَ مِنَ اللَّيْلِ فَأَصْبَحَ فَشَرِبَ مِنْهُ يَوْمَهُ ذَلِكَ وَلَيْلَتَهُ الْمُسْتَقْبِلَةَ وَمِنَ الْغَدِ حَتَّى أَمْسَى فَشَرِبَ وَسَقَى فَلَمَّا أَصْبَحَ أَمَرَ بِمَا بَقِيَ مِنْهُ فَأُهَرِيقَ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2004: 83) عن محمد بن أحمد بن أبي خلف، حدثنا زكريا بن عدي، حدثنا عبيد الله، عن زيد، عن يحيى أبي عمر النخعي قال: فذكره.","grade":"صحيح","chapter_ar":"باب في المدة التي يُشرب فيها النبيذ","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2004:83).","chapter_en":"The Period During Which Date Infusion May Be Drunk","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Yahya Abu ʿUmar al-Nakhaʿi said: Some people asked Ibn ʿAbbas about selling wine, buying it, and trading in it. He said: “Are you Muslims?” They said: “Yes.” He said: “Then selling it, buying it, and trading in it are not valid.” He said: Then they asked him about date infusion. He said: The Messenger of Allah ﷺ went out on a journey, then returned, and some of his Companions had made infusion in green jars, hollowed palm trunks, and gourds. He ordered it to be poured away. Then he ordered that a leather water skin be brought, and raisins and water were placed in it at night. In the morning, he drank from it during that day, the following night, and the next day until evening. He drank from it and gave others to drink. Then when morning came, he ordered what remained of it to be poured away."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2004,"lafz":true,"n":5230}],"full":1},{"num":7555,"demo":false,"sanad":"","matn":["عن ثمامة بن حَزْن القُشيري قَالَ: لَقِيتُ عَائِشَةَ فَسَأَلْتُهَا عَنِ النَّبِيذِ، فَدَعَتْ عَائِشَةُ جَارِيَةً حَبَشِيَّةً فَقَالَتْ سَلْ هَذِهِ فَإِنَّهَا كَانَتْ تَنْبِذُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتِ الْحَبَشِيَّةُ كُنْتُ أَنْبِذُ لَهُ فِي سِقَاءٍ مِنَ اللَّيْلِ وَأُوكِيهِ وَأُعَلِّقُهُ فَإِذَا أَصْبَحَ شَرِبَ مِنْهُ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2005: 84) عن شيبان بن فروخ، حدثنا القاسم بن الفضل الحُدّاني، حدثنا ثمامة بن حزن القشيري فذكره.","grade":"صحيح","chapter_ar":"باب في المدة التي يُشرب فيها النبيذ","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2005:84).","chapter_en":"The Period During Which Date Infusion May Be Drunk","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Thumamah ibn Hazn al-Qushayri said: I met ʿA’ishah and asked her about date infusion. ʿA’ishah called an Abyssinian slave girl and said: “Ask this one, for she used to make infusion for the Messenger of Allah ﷺ.” The Abyssinian woman said: “I used to make infusion for him in a leather water skin at night, tie it, and hang it up. When morning came, he would drink from it.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2005,"lafz":true}],"full":1},{"num":7556,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ كُنَّا نَنْبِذُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سِقَاءٍ يُوكَى أَعْلاَهُ وَلَهُ عَزْلاَءُ نَنْبِذُهُ غُدْوَةً فَيَشْرَبُهُ عِشَاءً وَنَنْبِذُهُ عِشَاءً فَيَشْرَبُهُ غُدْوَةً."],"takhrij":"صحيح: رواه مسلم في الأشربة (2005: 85) عن محمد بن المثنى العنزي، حدثنا عبد الوهاب الثقفي، عن يونس (هو ابن عبيد)، عن الحسن (هو البصري)، عن أمه، عن عائشة قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب في المدة التي يُشرب فيها النبيذ","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2005:85).","chapter_en":"The Period During Which Date Infusion May Be Drunk","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["ʿA’ishah said: We used to make infusion for the Messenger of Allah ﷺ in a leather water skin whose top was tied and which had an outlet. We would make it in the morning and he would drink it in the evening, and we would make it in the evening and he would drink it in the morning."]},"buhuth":{"en":["Her statement, “it had an outlet,” means an opening at the bottom of the leather water skin."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2005,"lafz":true,"n":5232}],"full":1,"dr":1},{"num":7557,"demo":false,"sanad":"","matn":["عَنْ فيروز الديلمي قَالَ: أَتَيْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْنَا: يَا رَسُولَ اللَّهِ قَدْ عَلِمْتَ مَنْ نَحْنُ؟ وَمِنْ أَيْنَ نَحْنُ؟ فَإِلَى مَنْ نَحْنُ؟ قَالَ: إِلَى اللَّهِ وَإِلَى رَسُولِهِ فَقُلْنَا: يَا رَسُولَ اللَّهِ، إِنَّ لَنَا أَعْنَابًا مَا نَصْنَعُ بِهَا؟ قَالَ: زَبِّبُوهَا قُلْنَا: مَا نَصْنَعُ بِالزَّبِيبِ؟ قَالَ: انْبِذُوهُ عَلَى غَدَائِكُمْ، وَاشْرَبُوهُ عَلَى عَشَائِكُمْ، وَانْبِذُوهُ عَلَى عَشَائِكُمْ، وَاشْرَبُوهُ عَلَى غَدَائِكُمْ، وَانْبِذُوهُ فِي الشِّنَانِ، وَلاَ تَنْبِذُوهُ فِي الْقُلَلِ؛ فَإِنَّهُ إِذَا تَأَخَّرَ عَنْ عَصْرِهِ صَارَ خَلاًّ."],"takhrij":"صحيح: رواه أبو داود (3710)، والنسائي (5736) والبيهقي (8/300) كلهم من حديث السيباني، عن عبد الله بن الديلمي، عن أبيه قال: فذكره.","grade":"صحيح","chapter_ar":"باب في المدة التي يُشرب فيها النبيذ","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3710), al-Nasa’i (5736), and al-Bayhaqi (8/300).","chapter_en":"The Period During Which Date Infusion May Be Drunk","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Fayruz al-Daylami said: We came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, you know who we are, where we are from, and to whom we belong.” He said: “To Allah and to His Messenger.” We said: “O Messenger of Allah, we have grapes. What should we do with them?” He said: “Make them into raisins.” We said: “What should we do with the raisins?” He said: “Soak them for your midday meal and drink them with your evening meal; soak them for your evening meal and drink them with your midday meal. Make the infusion in worn leather water skins, and do not make it in jars, for if it remains beyond its time, it becomes vinegar.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3710,"lafz":true},{"key":"nasai","label":"النسائي","number":5736},{"key":"kubrabayhaqi","label":"البيهقي","number":8},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":17423,"n":17581}],"full":1,"dr":1},{"num":7558,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يَشْرَبُ نَبِيذًا فَوْقَ ثَلَاثٍ."],"takhrij":"صحيح: رواه أبو عوانة (8123)، والطبراني في الكبير (10/357) من طريق علي بن نصر الجهضمي، ثنا حبان بن هلال، ثنا سفيان بن حبيب، ثنا ابن جريج، عن سعيد بن ميناء، عن القاسم بن محمد، عن ابن عباس قال: فذكره.","grade":"صحيح","chapter_ar":"باب في المدة التي يُشرب فيها النبيذ","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu ʿAwanah (8123) and al-Tabarani in al-Kabir (10/357).","chapter_en":"The Period During Which Date Infusion May Be Drunk","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ would not drink date infusion after three days."]}},"tuhfa":{},"refs":[{"key":"sh21618","label":"أبو عوانة","number":8123,"lafz":true},{"key":"mujamkabir","label":"الطبراني في الكبير","number":10}],"full":1,"dr":1},{"num":7559,"demo":false,"sanad":"","matn":["عن أبي حميد الساعدي قال: أتيت النبي صلي الله عليه وسلم بقدح لبنٍ من النقيع ليس مخمرا فقال:  ألا خمّرته و لو تعرض عليه عوداً."],"takhrij":"صحيح: رواه مسلم في الأشربة (2010: 93) من طرق عن أبي عاصم، عن الضحاك، أخبرنا ابن جريج، أخبرني أبو الزبير، أنه سمع جابر بن عبدالله يقول: أخبرني أبو حميد قال: فذكره.","grade":"صحيح","chapter_ar":"باب إباحة شرب النبيذ إذا لم يشتد، والحث على تخمير الإناء","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2010:93).","chapter_en":"The Permissibility of Drinking Infusion If It Has Not Become Strong, and Encouragement to Cover the Vessel","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Abu Humayd al-Saʿidi said: I brought the Prophet ﷺ a cup of milk from al-Naqiʿ that was not covered. He said: “Why did you not cover it, even by placing a stick across it?”"]},"buhuth":{"en":["His statement, “not covered,” means uncovered. Covering is called “takhmir,” and wine is so called because it covers the mind.","His statement, “even by placing a stick across it,” means putting a stick over it even crosswise. The meaning is that if he does not cover it fully, then at least he should place something across it, for Satan does not open something closed, as will come in the hadith of Jabir in the higher manners section."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2010,"lafz":true}],"full":1,"dr":1},{"num":7560,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاسْتَسْقَى فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ أَلاَ نَسْقِيكَ نَبِيذًا فَقَالَ بَلَى. قَالَ فَخَرَجَ الرَّجُلُ يَسْعَى فَجَاءَ بِقَدَحٍ فِيهِ نَبِيذٌ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَلاَّ خَمَّرْتَهُ وَلَوْ تَعْرُضُ عَلَيْهِ عُودًا. قَالَ فَشَرِبَ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2011: 94) عن أبي بكر بن أبي شيبة وأبي كريب – واللفظ لأبي كريب- قالا: حدثنا أبو معاوية، عن الأعمش، عن أبي صالح، عن جابر بن عبد الله قال: فذكره.","grade":"صحيح","chapter_ar":"باب إباحة شرب النبيذ إذا لم يشتد، والحث على تخمير الإناء","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2011:94).","chapter_en":"The Permissibility of Drinking Infusion If It Has Not Become Strong, and Encouragement to Cover the Vessel","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: We were with the Messenger of Allah ﷺ, and he asked for something to drink. A man said: “O Messenger of Allah, shall we give you date infusion to drink?” He said: “Yes.” The man went quickly and brought a cup containing date infusion. The Messenger of Allah ﷺ said: “Why did you not cover it, even by placing a stick across it?” He said: Then he drank."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2011,"lafz":true}],"full":1,"dr":1},{"num":7561,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ لَقَدْ سَقَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَدَحِي هَذَا الشَّرَابَ كُلَّهُ الْعَسَلَ وَالنَّبِيذَ وَالْمَاءَ وَاللَّبَنَ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2008: 89) من طريق عفان، حدثنا حماد بن سلمة، عن ثابت، عن أنس قال: فذكره.","grade":"صحيح","chapter_ar":"باب إباحة شرب النبيذ إذا لم يشتد، والحث على تخمير الإناء","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2008:89).","chapter_en":"The Permissibility of Drinking Infusion If It Has Not Become Strong, and Encouragement to Cover the Vessel","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Anas ibn Malik said: I gave the Messenger of Allah ﷺ all types of drink in this cup of mine: honey drink, date infusion, water, and milk."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2008,"lafz":true}],"full":1,"rep":[7583,9623]},{"num":7562,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ عَلِمْتُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَصُومُ فَتَحَيَّنْتُ فِطْرَهُ بِنَبِيذٍ صَنَعْتُهُ فِي دُبَّاءٍ ثُمَّ أَتَيْتُهُ بِهِ فَإِذَا هُوَ يَنِشُّ فَقَالَ اضْرِبْ بِهَذَا الْحَائِطَ فَإِنَّ هَذَا شَرَابُ مَنْ لاَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ."],"takhrij":"حسن: رواه أبو داود (3716)، والنسائي (5610)، وابن ماجه (3409) كلهم من حديث زيد بن واقد، عن خالد بن عبدالله بن حسين، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب إباحة شرب النبيذ إذا لم يشتد، والحث على تخمير الإناء","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3716), al-Nasa’i (5610), and Ibn Majah (3409).","chapter_en":"The Permissibility of Drinking Infusion If It Has Not Become Strong, and Encouragement to Cover the Vessel","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Abu Hurayrah said: I knew that the Messenger of Allah ﷺ was fasting, so I waited for the time of his breaking the fast with an infusion I had made in a gourd. Then I brought it to him, and it was bubbling. He said: “Throw this against the wall, for this is the drink of one who does not believe in Allah and the Last Day.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3716,"lafz":true},{"key":"nasai","label":"النسائي","number":5610,"n":5610},{"key":"ibnmajah","label":"ابن ماجه","number":3409}],"full":1,"dr":1},{"num":7563,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ وَفْدَ عَبْدِ الْقَيْسِ، قَالُوا يَا رَسُولَ اللَّهِ فِيمَ نَشْرَبُ قَالَ لاَ تَشْرَبُوا فِي الدُّبَّاءِ وَلاَ فِي الْمُزَفَّتِ وَلاَ فِي النَّقِيرِ وَانْتَبِذُوا فِي الأَسْقِيَةِ. قَالُوا يَا رَسُولَ اللَّهِ فَإِنِ اشْتَدَّ فِي الأَسْقِيَةِ قَالَ فَصُبُّوا عَلَيْهِ الْمَاءَ. قَالُوا يَا رَسُولَ اللَّهِ. فَقَالَ لَهُمْ فِي الثَّالِثَةِ أَوِ الرَّابِعَةِ أَهْرِيقُوهُ. ثُمَّ قَالَ إِنَّ اللَّهَ حَرَّمَ عَلَىَّ أَوْ حُرِّمَ الْخَمْرُ وَالْمَيْسِرُ وَالْكُوبَةُ. قَالَ وَكُلُّ مُسْكِرٍ حَرَامٌ.","قال سفيان: فسألتُ عليَّ بن بذيمة عن الكوبة، قال: الطبل."],"takhrij":"صحيح: رواه أبو داود (3696)، وأحمد (2476)، وصحّحه ابن حبان (5365) كلهم من طريق أبي أحمد الزبيري، ثنا سفيان (هو الثوري)، عن علي بن بذيمة، ثني قيس بن حَبتر النهشلي، عن ابن عباس قال: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في إضافة الماء إلى النبيذ إذا اشتد ما لم يصل إلى حدّ الإسكار","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3696), Ahmad (2476), and authenticated by Ibn Hibban (5365).","chapter_en":"Adding Water to Infusion If It Becomes Strong, So Long as It Has Not Reached the Point of Intoxication","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas narrated that the delegation of ʿAbd al-Qays said: “O Messenger of Allah, what should we drink from?” He said: “Do not drink from gourds, pitch-coated vessels, or hollowed palm trunks. Make infusion in leather water skins.” They said: “O Messenger of Allah, what if it becomes strong in the leather water skins?” He said: “Pour water over it.” They repeated, “O Messenger of Allah.” On the third or fourth time, he said: “Pour it away.” Then he said: “Allah has forbidden to me — or He has forbidden — wine, gambling, and the drum.” He said: “Every intoxicant is forbidden.” Sufyan said: I asked ʿAli ibn Badhimah about the drum, and he said: “The drum.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3696,"lafz":true},{"key":"ibnhibban","label":"صحّحه ابن حبان","number":5365},{"key":"ahmad","label":"مسند الإمام أحمد","number":2476,"n":2476}],"full":1},{"num":7564,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ من وفد عَبْدِ الْقَيْسِ، عَنْ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ تَشْرَبُوا فِي نَقِيرٍ وَلاَ مُزَفَّتٍ وَلاَ دُبَّاءٍ، وَلاَ حَنْتَمٍ، وَاشْرَبُوا فِي الْجِلْدِ الموكأ عَلَيْهِ، فَإِنِ اشْتَدَّ فَاكْسِرُوهُ بِالْمَاءِ، فَإِنْ أَعْيَاكُمْ فَأَهْرِيقُوهُ."],"takhrij":"حسن: رواه أبو داود (3695)، والبيهقي (8/302) كلاهما من طريق عوف بن أبي جميلة، عن أبي القموص زيد بن علي، قال: حدثني رجل كان من الوفد الذين وفدوا على رسول الله صلي الله عليه وسلم من عبد القيس يحسب عوف أن اسمه قيس بن النعمان قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في إضافة الماء إلى النبيذ إذا اشتد ما لم يصل إلى حدّ الإسكار","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3695) and al-Bayhaqi (8/302).","chapter_en":"Adding Water to Infusion If It Becomes Strong, So Long as It Has Not Reached the Point of Intoxication","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["A man from the delegation of ʿAbd al-Qays narrated from the Prophet ﷺ that he said: “Do not drink from hollowed palm trunks, pitch-coated vessels, gourds, or green jars. Drink from leather that is tied closed. If it becomes strong, weaken it with water. If it overcomes you, pour it away.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3695,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":8}],"full":1,"dr":1},{"num":7565,"demo":false,"sanad":"","matn":["عن الْمُطَّلِبِ بن أَبِي وداعةأَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِإِنَاءِ نَبِيذٍ فَصَبَّ عَلَيْهِ الْمَاءَ حَتَّى تَدَفَّقَ، ثُمَّ شَرِبَ مِنْهُ."],"takhrij":"حسن: رواه الطبراني في الكبير (20/291) عن العباس بن الفضل الأسفاطي، ثنا أحمد بن يونس، ثنا أبو شهاب، عن الأعمش، عن أبي صالح، عن المطلب بن أبي وداعة قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في إضافة الماء إلى النبيذ إذا اشتد ما لم يصل إلى حدّ الإسكار","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (20/291).","chapter_en":"Adding Water to Infusion If It Becomes Strong, So Long as It Has Not Reached the Point of Intoxication","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Al-Muttalib ibn Abi Wadaʿah narrated that the Messenger of Allah ﷺ was brought a vessel of date infusion, so he poured water into it until it overflowed, then drank from it."]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":20,"lafz":true}],"full":1,"dr":1},{"num":7566,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّهُ قَالَ لِوَفْدِ عَبْدِ الْقَيْسِ: لَا تَشْرَبُوا فِي نَقِيرٍ، وَلَا مُقَيَّرٍ، وَلَا دُبَّاءٍ، وَلَا حَنْتَمٍ، وَلَا مَزَادَةٍ، وَلَكِنِ اشْرَبُوا فِي سِقَاءِ أَحَدِكُمْ غَيْرَ مُسْكِرٍ، فَإِنْ خُشِيَ شِرَّتُهُ فَلْيَصُبَّ عَلَيْهِ الْمَاءَ."],"takhrij":"حسن: رواه البيهقي (8/302) من طريق أبي الأشعث أحمد بن المقدام، ثنا نوح بن قيس، عن ابن عون، عن محمد بن سيرين، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في إضافة الماء إلى النبيذ إذا اشتد ما لم يصل إلى حدّ الإسكار","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bayhaqi (8/302).","chapter_en":"Adding Water to Infusion If It Becomes Strong, So Long as It Has Not Reached the Point of Intoxication","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Abu Hurayrah narrated from the Messenger of Allah ﷺ that he said to the delegation of ʿAbd al-Qays: “Do not drink from hollowed palm trunks, pitch-coated vessels, gourds, green jars, or large water skins whose tops have been cut off. Rather, drink from one of your leather water skins, without intoxication. If one fears its strength, let him pour water over it.”"]},"buhuth":{"en":["The conclusion from these hadiths is that it is permissible to drink infusion as long as it remains sweet. But if it remains for two days or around that and no smell or change is found in it, then do not drink it out of caution. Do as the Prophet ﷺ did: he either gave it to his servant to drink or ordered it to be poured away."]}},"tuhfa":{},"refs":[{"key":"kubrabayhaqi","label":"البيهقي","number":8,"lafz":true},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":17430,"n":17588}],"full":1,"dr":1},{"num":7567,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: نهى النبي صلى الله عليه وسلم عن الزبيب، والتمر، والبسر، والرطب.","وفي رواية: نهى رسول الله صلى الله عليه وسلم عن التمر والزبيب، ونهى عن التمر والبُسر أن يُنبذا جميعا."],"takhrij":"متفق عليه: رواه البخاري في الأشربة (5601)، ومسلم في الأشربة (1986: 18) كلاهما من طريق ابن جريج، أخبرني عطاء، أنه سمع جابرا يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5601) and Muslim (1986:18). The other narration is from al-Nasa’i (5560).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: The Prophet ﷺ forbade mixing raisins with dates, and unripe dates with fresh dates. In another narration: The Messenger of Allah ﷺ forbade dates and raisins, and he forbade dates and unripe dates from being made into infusion together."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5601,"lafz":true},{"key":"muslim","label":"مسلم","number":1986},{"key":"nasai","label":". والرواية الأخرى للنسائي","number":5560,"n":5560}],"full":1,"dr":1},{"num":7568,"demo":false,"sanad":"","matn":["عن أَبِي قَتَادَةَ عَنْ أَبِيهِ، قَالَ نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُجْمَعَ بَيْنَ التَّمْرِ وَالزَّهْوِ، وَالتَّمْرِ وَالزَّبِيبِ، وَلْيُنْبَذْ كُلُّ وَاحِدٍ مِنْهُمَا عَلَى حِدَةٍ.","وفي لفظ: لا تنتبذوا الزهو والرطب جميعا، ولا تنتبذوا الرطب والزبيب جميعا، ولكن انتبذوا كل واحد عل حدته."],"takhrij":"متفق عليه: رواه البخاري في الأشربة (5602)، ومسلم في الأشربة (1988: 24) كلاهما من طريق هشام الدستوائي، أخبرنا يحيى بن أبي كثير، عن عبد الله بن أبي قتادة، عن أبيه قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5602) and Muslim (1988:24). The wording is from al-Bukhari.","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Abu Qatadah said: The Prophet ﷺ forbade combining dates with unripe dates, and dates with raisins, and commanded that each be made into infusion separately. In another wording: “Do not make infusion from unripe dates and fresh dates together, and do not make infusion from fresh dates and raisins together. Rather, make infusion from each one separately.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5602,"lafz":true},{"key":"muslim","label":"مسلم","number":1988}],"full":1,"dr":1},{"num":7569,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ يَقُولُ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يُخْلَطَ التَّمْرُ وَالزَّهْوُ ثُمَّ يُشْرَبَ وَإِنَّ ذَلِكَ كَانَ عَامَّةَ خُمُورِهِمْ يَوْمَ حُرِّمَتِ الْخَمْرُ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1981) عن أبي الطاهر أحمد بن عمرو بن سرح، أخبرنا عبد الله بن وهب، أخبرني عمرو بن الحارث، أن قتادة بن دعامة حدثه أنه سمع أنس بن مالك قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1981).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ forbade mixing dates and unripe dates and then drinking it, and that was the common wine of the people on the day wine was forbidden."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1981,"lafz":true}],"full":1},{"num":7570,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الزَّبِيبِ وَالتَّمْرِ وَالْبُسْرِ وَالتَّمْرِ وَقَالَ يُنْبَذُ كُلُّ وَاحِدٍ مِنْهُمَا عَلَى حِدَتِهِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1989) من طريق وكيع، عن عكرمة بن عمار، عن أبي كثير الحنفي، عن أبي هريرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1989).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ forbade mixing raisins with dates, and unripe dates with dates, and said: “Each one should be made into infusion separately.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1989,"lafz":true}],"full":1},{"num":7571,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ التَّمْرِ وَالزَّبِيبِ أَنْ يُخْلَطَ بَيْنَهُمَا وَعَنِ التَّمْرِ وَالْبُسْرِ أَنْ يُخْلَطَ بَيْنَهُمَا.","وفي رواية: من شرب النبيذ منكم فليشربه زبيبا فردا، أو تمرا فردا، أو بُسرا فرداً."],"takhrij":"صحيح: رواه مسلم في الأشربة (1987) عن يحيى بن يحيى، أخبرنا يزيد بن زريع، عن التيمي، عن أبي نضرة، عن أبي سعيد قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1987).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that the Prophet ﷺ forbade mixing dates and raisins together, and mixing dates and unripe dates together. In another narration: “Whoever among you drinks infusion, let him drink it from raisins alone, or dates alone, or unripe dates alone.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1987,"lafz":true}],"full":1,"dr":1},{"num":7572,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُخْلَطَ التَّمْرُ وَالزَّبِيبُ جَمِيعًا وَأَنْ يُخْلَطَ الْبُسْرُ وَالتَّمْرُ جَمِيعًا وَكَتَبَ إِلَى أَهْلِ جُرَشَ يَنْهَاهُمْ عَنْ خَلِيطِ التَّمْرِ وَالزَّبِيبِ."],"takhrij":"صحيح: رواه مسلم (1990) عن أبي بكر بن أبي شيبة، حدثنا علي بن مسهر، عن الشيباني، عن حبيب، عن سعيد بن جبير، عن ابن عباس قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1990).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Ibn ʿAbbas said: The Prophet ﷺ forbade mixing dates and raisins together, and mixing unripe dates and dates together. He wrote to the people of Jurash forbidding them from the mixture of dates and raisins."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1990,"lafz":true}],"full":1},{"num":7573,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الدُّبَّاءِ وَالْحَنْتَمِ وَالْمُزَفَّتِ وَالنَّقِيرِ وَأَنْ يُخْلَطَ الْبَلَحُ بِالزَّهْوِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1995: 41) عن أبي بكر بن أبي شيبة، حدثنا محمد بن فضيل، عن حبيب بن أبي عمرة، عن سعيد بن جبير، عن ابن عباس قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1995:41).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ forbade gourds, green jars, pitch-coated vessels, hollowed palm trunks, and mixing green dates with dates that had begun to ripen and color."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1995,"lafz":true,"n":5180}],"full":1},{"num":7574,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّهُ كَانَ يَقُولُ قَدْ نُهِيَ أَنْ يُنْبَذَ الْبُسْرُ وَالرُّطَبُ جَمِيعًا وَالتَّمْرُ وَالزَّبِيبُ جَمِيعًا."],"takhrij":"صحيح: رواه مسلم في الأشربة (1991: 28) عن محمد بن رافع، حدثنا عبدالرزاق، أخبرنا ابن جريج، أخبرني موسى بن عقبة، عن نافع، عن ابن عمر قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1991:28).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar used to say: It has been forbidden to make infusion from unripe dates and fresh dates together, and from dates and raisins together."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1991,"lafz":true}],"full":1},{"num":7575,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ، - قَالَ حَفْصٌ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ نَهَى عَنِ الْبَلَحِ وَالتَّمْرِ وَالزَّبِيبِ وَالتَّمْرِ."],"takhrij":"صحيح: رواه أبو داود (3705)، والنسائي (5547)، وأحمد (18820) كلهم من طريق شعبة، ثنا الحكم، قال: سمعت ابن أبي ليلى، عن رجل من أصحاب النبي صلى الله عليه وسلم فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3705), al-Nasa’i (5547), and Ahmad (18820).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["A man from the Companions of the Prophet ﷺ narrated from the Prophet ﷺ that he forbade mixing unripe dates with dates, and raisins with dates."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3705,"lafz":true},{"key":"nasai","label":"النسائي","number":5547},{"key":"ahmad","label":"مسند الإمام أحمد","number":18820,"n":18820}],"full":1,"dr":1},{"num":7576,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الزَّبِيبُ وَالتَّمْرُ هُوَ الْخَمْرُ. وَزَادَ فِي رِوَايَةِ: \"يَعْنِي إِذَا انتبذ جَمِيعًا\"."],"takhrij":"صحيح: رواه النسائي (5546)، والحاكم (4/141) كلاهما من طريق عبيد الله بن موسى، عن شيبان، عن الأعمش، عن محارب بن دثار، عن جابر قال: فذكره. والزيادة للحاكم، وقال: \"صحيح على شرط الشيخين\".","grade":"صحيح","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (5546) and al-Hakim (7218).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Jabir narrated from the Prophet ﷺ that he said: “Raisins and dates are wine.” Another narration adds: “Meaning when they are made into infusion together.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":5546,"lafz":true,"n":5546},{"key":"hakim","label":"الحاكم","number":7218}],"full":1,"dr":1},{"num":7577,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُسَيْدٍ الأنصاري قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُجْمَعَ بَيْنَ التَّمْرِ وَالزَّبِيبِ."],"takhrij":"صحيح: رواه الطبراني في الكبير (19/268) عن عبيد العجلي، ثنا محمد بن حاتم المؤدب، ثنا علي بن ثابت الجزري، ثنا عبد الحميد بن جعفر (هو الأنصاري)، حدثني يزيد بن أبي حبيب المصري، عن عراك بن مالك، عن أبي أُسيد الأنصاري قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tabarani in al-Kabir (19/268).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Abu Usayd al-Ansari said: The Messenger of Allah ﷺ forbade combining dates and raisins."]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":19,"lafz":true}],"full":1,"dr":1},{"num":7578,"demo":false,"sanad":"","matn":["عَنْ مَعْبَدِ بْنِ كَعْبِ بْنِ مَالِكٍ، عَنْ أُمِّهِ، وَكَانَتْ قَدْ صَلَّتِ الْقِبْلَتَيْنِ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى أَنْ يُنْتَبَذَ التَّمْرُ وَالزَّبِيبُ جَمِيعًا وَقَالَ: انْتَبِذْ كُلَّ وَاحِدٍ مِنْهَا وَحْدَهُ."],"takhrij":"حسن: رواه أحمد (23932)، والحميدي (356)، والطبراني في الكبير (25/147) كلهم من طريق محمد بن إسحاق، أخبرنا معبد بن كعب به فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (23932), al-Humaydi (356), and al-Tabarani in al-Kabir (25/147).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Maʿbad ibn Kaʿb ibn Malik narrated from his mother, who had prayed toward both directions of prayer with the Messenger of Allah ﷺ. She said: I heard the Messenger of Allah ﷺ forbidding dates and raisins from being made into infusion together, and he said: “Make infusion from each one separately.”"]}},"tuhfa":{},"refs":[{"key":"humaydi","label":"الحميدي","number":356},{"key":"mujamkabir","label":"الطبراني في الكبير","number":25},{"key":"ahmad","label":"مسند الإمام أحمد","number":23932,"n":23932,"lafz":true}],"full":1,"dr":1},{"num":7579,"demo":false,"sanad":"","matn":["عن أَبِي طَلْحَةَ الأنصاريأَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْخَلِيطَيْنِ."],"takhrij":"حسن: رواه الطبراني في الكبير (5/102) عن زكريا بن يحيى الساجي، ثنا محمد بن عبد الملك بن أبي الشوارب، ثنا عمر بن رديح، عن عطاء بن أبي ميمونة، عن أنس، عن أبي طلحة قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (5/102).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Abu Talhah al-Ansari narrated that the Messenger of Allah ﷺ forbade the two mixed items."]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":5,"lafz":true}],"full":1,"dr":1},{"num":7580,"demo":false,"sanad":"","matn":["عَنْ أَبِي الْوَدَّاكِ، يَقُولُ: لَا أَشْرَبُ نَبِيذًا بَعْدَ مَا سَمِعْتُ أَبَا سَعِيدٍ يَقُولُ: أُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِرَجُلٍ نَشْوَانَ، فَقَالَ: إِنِّي لَمْ أَشْرَبْ خَمْرًا، إِنَّمَا شَرِبْتُ زَبِيبًا وَتَمْرًا فِي دُبَّاءَةٍ، قَالَ: فَأَمَرَ بِهِ فَنُهِزَ بِالْأَيْدِي وَخُفِقَ بِالنِّعَالِ، وَنَهَى عَنِ الدُّبَّاءِ، وَنَهَى عَنِ الزَّبِيبِ وَالتَّمْرِ يَعْنِي أَنْ يُخْلَطَا."],"takhrij":"حسن: رواه أحمد (11279)، والنسائي في الكبرى (5292)، وصحّحه الحاكم (4/374) كلهم من طرق عن شعبة، عن أبي التياح، عن أبي الوداك، عن أبي سعيد الخدري قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (11279), al-Nasa’i in al-Kubra (5292), and authenticated by al-Hakim (8129).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Abu al-Waddak said: I will not drink infusion after hearing Abu Saʿid say: A drunken man was brought to the Messenger of Allah ﷺ. He said: “I did not drink wine; I only drank raisins and dates in a gourd.” He said: He ordered that he be pushed with hands and struck with sandals. He forbade gourds, and he forbade raisins and dates, meaning that they be mixed together."]}},"tuhfa":{},"refs":[{"key":"kubranasai","label":"النسائي في الكبرى","number":5292},{"key":"hakim","label":"الحاكم","number":8129},{"key":"ahmad","label":"مسند الإمام أحمد","number":11297,"n":11297},{"key":"ahmad","label":"احمد","number":11279,"lafz":true,"n":11297}],"full":1,"dr":1},{"num":7581,"demo":false,"sanad":"","matn":["عَنِ امْرَأَةٍ، أَنَّهَا سَمِعَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا تَنْتَبِذُوا التَّمْرَ وَالزَّبِيبَ جَمِيعًا، انْبِذُوا كُلَّ وَاحِدٍ مِنْهُمَا وَحْدَهُ."],"takhrij":"حسن: رواه البيهقي (8/307) من طريق ابن وهب، أخبرني عبد الرحمن بن سلمان، عن عُقيل بن خالد، عن معبد بن كعب بن مالك، عن أخيه عبد الله بن كعب بن مالك، عن امرأة قالت: فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء في انتباذ الخليطين من نوع واحد أو من نوعين","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bayhaqi (8/307).","chapter_en":"Making Infusion from Two Mixed Items, Whether of One Type or Two Types","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["A woman narrated that she heard the Messenger of Allah ﷺ say: “Do not make infusion from dates and raisins together. Make infusion from each one separately.”"]}},"tuhfa":{},"refs":[{"key":"kubrabayhaqi","label":"البيهقي","number":8,"lafz":true},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":17462,"n":17620}],"full":1,"dr":1},{"num":7582,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَنِ الْخَمْرِ تُتَّخَذُ خَلاًّ فَقَالَ لاَ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1983) من طريق سفيان (هو الثوري)، عن السدي، عن يحيى بن عباد، عن أنس قال: فذكره.","grade":"صحيح","chapter_ar":"باب في النهي عن اتخاذ الخمر خلاً","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1983). Abu Dawud (3675) narrated it through another route with the wording: Abu Talhah asked the Prophet ﷺ about orphans who had inherited wine. He said: “Pour it away.” He said: “Shall I not make it into vinegar?” He said: “No.”","chapter_en":"The Prohibition of Turning Wine into Vinegar","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["Anas narrated that the Prophet ﷺ was asked about wine being made into vinegar. He said: “No.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1983,"lafz":true},{"key":"abudawud","label":". ورواه أبو داود","number":3675}],"full":1,"dr":1},{"num":7583,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ لَقَدْ سَقَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَدَحِي هَذَا الشَّرَابَ كُلَّهُ الْعَسَلَ وَالنَّبِيذَ وَالْمَاءَ وَاللَّبَنَ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2008) من طريق عفان، ثنا حماد بن سلمة، عن ثابت، عن أنس قال: فذكره.","grade":"صحيح","chapter_ar":"باب شرب النبيذ في القدح الذي يشرب فيه الماء وغيره","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2008).","chapter_en":"Drinking Infusion from the Cup Used for Water and Other Drinks","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Anas said: I gave the Messenger of Allah ﷺ all types of drink in this cup of mine: honey drink, date infusion, water, and milk."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2008,"lafz":true}],"full":1,"rep":[7561,9623]},{"num":7584,"demo":false,"sanad":"","matn":["عن ابْنِ عُمَرَ يَقُولُ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لُعِنَتِ الْخَمْرُ عَلَى عَشَرَةِ أَوْجُهٍ بِعَيْنِهَا وَعَاصِرِهَا وَمُعْتَصِرِهَا وَبَائِعِهَا وَمُبْتَاعِهَا وَحَامِلِهَا وَالْمَحْمُولَةِ إِلَيْهِ وَآكِلِ ثَمَنِهَا وَشَارِبِهَا وَسَاقِيهَا."],"takhrij":"حسن: رواه أبوداود (3674)، وابن ماجه (3380)، وأحمد (4787)، وابن أبي شيبة (6/447)، والبيهقي (5/327) كلهم من طريق عبد العزيز بن عمر بن عبد العزيز، عن عبد الرحمن بن عبد الله الغافقي وأبي طعمة مولاهم أنهما سمعا ابن عمر يقول: فذكره.","grade":"حسن","chapter_ar":"باب لعن الله الخمر وشاربها وساقيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3674), Ibn Majah (3380), Ahmad (4787), Ibn Abi Shaybah (6/447), and al-Bayhaqi (5/327).","chapter_en":"Allah’s Curse upon Wine, the One Who Drinks It, and the One Who Serves It","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":20,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: The Messenger of Allah ﷺ said: “Wine is cursed in ten ways: itself, the one who presses it, the one for whom it is pressed, the one who sells it, the one who buys it, the one who carries it, the one to whom it is carried, the one who consumes its price, the one who drinks it, and the one who serves it.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3674,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":3380},{"key":"sh9944","label":"ابن أبي شيبة","number":6},{"key":"kubrabayhaqi","label":"البيهقي","number":5},{"key":"ahmad","label":"مسند الإمام أحمد","number":4787,"n":4787},{"key":"sh9944","label":"المصنف لابن أبي شيبة","number":21625,"n":21608}],"full":1,"dr":1,"rep":[5790]},{"num":7585,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ لَعَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْخَمْرِ عَشَرَةً عَاصِرَهَا وَمُعْتَصِرَهَا وَشَارِبَهَا وَحَامِلَهَا وَالْمَحْمُولَةَ إِلَيْهِ وَسَاقِيَهَا وَبَائِعَهَا وَآكِلَ ثَمَنِهَا وَالْمُشْتَرِيَ لَهَا وَالْمُشْتَرَاةَ لَهُ."],"takhrij":"حسن: رواه الترمذي (1295)، وابن ماجه (3381) كلاهما من حديث أبي عاصم، عن شبيب بن بشر، عن أنس بن مالك قال: فذكره. وقال الترمذي: \"حسن غريب\".","grade":"حسن","chapter_ar":"باب لعن الله الخمر وشاربها وساقيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1295) and Ibn Majah (3381). Al-Tirmidhi said: “Hasan gharib.”","chapter_en":"Allah’s Curse upon Wine, the One Who Drinks It, and the One Who Serves It","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":20,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ cursed ten in connection with wine: the one who presses it, the one for whom it is pressed, the one who drinks it, the one who carries it, the one to whom it is carried, the one who serves it, the one who sells it, the one who consumes its price, the one who buys it, and the one for whom it is bought."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1295,"lafz":true},{"key":"ibnmajah","label":"ابن ماجه","number":3381}],"full":1,"dr":1,"rep":[5792]},{"num":7586,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عَبَّاسٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَتَانِي جِبْرِيلُ فَقَالَ: يَا مُحَمَّدُ إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ لَعَنَ الْخَمْرَ، وَعَاصِرَهَا، وَمُعْتَصِرَهَا، وَشَارِبَهَا، وَحَامِلَهَا، وَالْمَحْمُولَةَ إِلَيْهِ، وَبَائِعَهَا، وَمُبْتَاعَهَا، وَسَاقِيَهَا، وَمُسْتَقِيَهَا."],"takhrij":"حسن: رواه أحمد (2897)، والبيهقي في الشعب (5196)، وصححه ابن حبان (5356)، والحاكم (4/145) كلهم من طريق مالك بن خير الزبادي، أن مالك بن سعد التُّجيبي حدّثه، أنه سمع ابن عباس فذكره. قال الحاكم: \"هذا حديث صحيح الإسناد\".","grade":"حسن","chapter_ar":"باب لعن الله الخمر وشاربها وساقيها","chapter_ur":"","part_ar":"كتاب الأشربة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (2897), al-Bayhaqi in al-Shuʿab (5196), and authenticated by Ibn Hibban (5356) and al-Hakim (7229).","chapter_en":"Allah’s Curse upon Wine, the One Who Drinks It, and the One Who Serves It","part_en":"Book of Drinks","group_ar":"","group_en":"","part_no":41,"group_no":0,"chapter_no":20,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas said: I heard the Messenger of Allah ﷺ say: “Gabriel came to me and said: ‘O Muhammad, Allah, the Mighty and Majestic, has cursed wine, the one who presses it, the one for whom it is pressed, the one who drinks it, the one who carries it, the one to whom it is carried, the one who sells it, the one who buys it, the one who serves it, and the one who asks to be served it.’”"]}},"tuhfa":{},"refs":[{"key":"shuabiman","label":"البيهقي في الشعب","number":5196},{"key":"ibnhibban","label":"صححه ابن حبان","number":5356},{"key":"hakim","label":"الحاكم","number":7229},{"key":"ahmad","label":"مسند الإمام أحمد","number":2897,"n":2897,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي في الشعب","number":5196}],"full":1,"dr":1},{"num":7587,"demo":false,"sanad":"","matn":["عن عبدالله بن عمرو قَالَ: قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ الْمُقْسِطِينَ عِنْدَ اللَّهِ عَلَى مَنَابِرَ مِنْ نُورٍ عَنْ يَمِينِ الرَّحْمَنِ عَزَّ وَجَلَّ وَكِلْتَا يَدَيْهِ يَمِينٌ الَّذِينَ يَعْدِلُونَ فِي حُكْمِهِمْ وَأَهْلِيهِمْ وَمَا وَلُوا."],"takhrij":"صحيح: رواه مسلم في الإمارة (1827: 18) من طريق سفيان بن عيينة، عن عمرو بن دينار، عن عمرو بن أوس، عن عبد الله بن عمرو فذكره.","grade":"صحيح","chapter_ar":"باب فضل من تولى أمر المسلمين وحكم فيهم بالعدل","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1827:18).","chapter_en":"The Virtue of One Who Takes Charge of the Muslims’ Affairs and Judges Among Them with Justice","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr said: The Messenger of Allah ﷺ said: “Indeed, the just will be with Allah upon pulpits of light, to the right of the Most Merciful, the Mighty and Majestic — and both of His hands are right hands — those who are just in their judgment, with their families, and in what they are entrusted with.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1827,"lafz":true}],"full":1,"rep":[6705,13347]},{"num":7588,"demo":false,"sanad":"","matn":["عن أبي هريرة أنّ رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قال: سَبْعَةٌ يُظِلُّهُمُ الله فِى ظِلِّهِ يَوْمَ لاَ ظِلَّ إِلاَّ ظِلُّهُ: إِمَامٌ عَادِلٌ، وَشَابٌّ نَشَأَ بِعِبَادَةِ الله، وَرَجُلٌ قَلْبُهُ مُعَلَّقٌ فِى المَسَاجِدِ، وَرَجُلاَنِ تَحَابَّا فِى الله اجْتَمَعَا عَلَيْهِ وَتَفَرَّقَا عَلَيْهِ، وَرَجُلٌ دَعَتْهُ امْرَأَةٌ ذَاتُ مَنْصِبٍ وَجَمَالٍ فَقَالَ: إِنِّى أَخَافُ الله، وَرَجُلٌ تَصَدَّقَ بِصَدَقَةٍ فَأَخْفَاهَا حَتَّى لاَ تَعْلَمَ شِمَالُهُ مَا تُنْفِقُ يَمِينُهُ، وَرَجُلٌ ذَكَرَ الله خَالِيًا فَفَاضَتْ عَيْنَاهُ."],"takhrij":"متفق عليه: رواه مالك في الشعر (14) عن خبيب بن عبدالرحمن الأنصاريّ، عن حفص بن عاصم، عن أبي سعيد أو عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل من تولى أمر المسلمين وحكم فيهم بالعدل","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (14), Muslim (1031), and al-Bukhari (660).","chapter_en":"The Virtue of One Who Takes Charge of the Muslims’ Affairs and Judges Among Them with Justice","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “There are seven whom Allah will shade in His shade on the Day when there is no shade except His shade: a just leader; a young person who grew up in the worship of Allah; a man whose heart is attached to the mosques; two men who love one another for the sake of Allah, meeting upon that and parting upon that; a man whom a woman of status and beauty calls, but he says, ‘I fear Allah’; a man who gives charity and conceals it so much that his left hand does not know what his right hand spends; and a man who remembers Allah in private, so his eyes overflow with tears.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":14,"lafz":true},{"key":"muslim","label":"مسلم","number":1031},{"key":"bukhari","label":"البخاري","number":660}],"full":1,"dr":1},{"num":7589,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِنَّمَا الإِمَامُ جُنَّةٌ يُقَاتَلُ مِنْ وَرَائِهِ وَيُتَّقَى بِهِ فَإِنْ أَمَرَ بِتَقْوَى اللَّهِ عَزَّ وَجَلَّ وَعَدَلَ كَانَ لَهُ بِذَلِكَ أَجْرٌ وَإِنْ يَأْمُرْ بِغَيْرِهِ كَانَ عَلَيْهِ مِنْهُ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2957)، ومسلم في الإمارة (1841) كلاهما من حديث أبي الزناد، عن الأعرج، عن أبي هريرة فذكره. والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"باب فضل من تولى أمر المسلمين وحكم فيهم بالعدل","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2957) and Muslim (1841). The wording is from Muslim.","chapter_en":"The Virtue of One Who Takes Charge of the Muslims’ Affairs and Judges Among Them with Justice","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “The leader is only a shield behind whom fighting is done and through whom protection is sought. If he commands mindfulness of Allah, the Mighty and Majestic, and acts justly, he will have reward for that. But if he commands something other than that, then it will be against him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2957,"lafz":true},{"key":"muslim","label":"مسلم","number":1841}],"full":1,"rep":[7613]},{"num":7590,"demo":false,"sanad":"","matn":["عن سعد بن تميم الأشعري قال: قيل: يا رسول الله، ما للخليفة من بعدك؟ قال: مثل الذي لي ما عدل في الحكم، وأقسط في القسط، ورحم ذا الرحم، فمن فعل غير ذلك فليس مني، ولست منه."],"takhrij":"حسن: رواه الطبراني في الكبير (6/55)، والبخاري في التاريخ الكبير (4/46)، وابن زنجويه في الأموال (39) كلهم من طريق أبي أيوب سليمان بن عبد الرحمن الدمشقي، حدثنا الوليد بن مسلم، حدثنا عبد الله بن العلاء، وغيره أنهما سمعا بلال بن سعد يحدث عن أبيه سعد فذكره. والسياق لابن زنجويه.","grade":"حسن","chapter_ar":"باب فضل من تولى أمر المسلمين وحكم فيهم بالعدل","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (6/55), al-Bukhari in al-Tarikh al-Kabir (4/46), and Ibn Zanjawayh in al-Amwal (39).","chapter_en":"The Virtue of One Who Takes Charge of the Muslims’ Affairs and Judges Among Them with Justice","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Saʿd ibn Tamim al-Ashʿari said: It was said: “O Messenger of Allah, what belongs to the successor after you?” He said: “The same as what belongs to me, as long as he is just in judgment, fair in distributing justice, and merciful toward relatives. Whoever does otherwise is not of me, and I am not of him.”"]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":6,"lafz":true},{"key":"tarikhbukhari","label":"البخاري في التاريخ الكبير","number":4},{"key":"ابن_زنجویہ/الاموال","label":"ابن زنجويه في الأموال","number":39}],"full":1,"dr":1},{"num":7591,"demo":false,"sanad":"","matn":["عَنْ قَيْسِ بْنِ أَبِي حَازِمٍ قَالَ: دَخَلَ أَبُو بَكْرٍ عَلَى امْرَأَةٍ مِنْ أَحْمَسَ يُقَالُ لَهَا زَيْنَبُ، فَرَآهَا لَا تَكَلَّمُ، فَقَالَ: مَا لَهَا لَا تَكَلَّمُ؟ قَالُوا: حَجَّتْ مُصْمِتَةً، قَالَ لَهَا: تَكَلَّمِي فَإِنَّ هَذَا لَا يَحِلُّ، هَذَا مِنْ عَمَلِ الجَاهِلِيَّةِ، فَتَكَلَّمَتْ، فَقَالَتْ: مَنْ أَنْتَ؟ قَالَ: امْرُؤٌ مِنْ المُهَاجِرِينَ، قَالَتْ: أَيُّ المُهَاجِرِينَ؟ قَالَ: مِنْ قُرَيْشٍ. قَالَتْ: مِنْ أَيِّ قُرَيْشٍ أَنْتَ؟ قَالَ: إِنَّكِ لَسَئُولٌ، أَنَا أَبُو بَكْرٍ. قَالَتْ: مَا بَقَاؤُنَا عَلَى هَذَا الْأَمْرِ الصَّالِحِ الَّذِي جَاءَ الله بِهِ بَعْدَ الجَاهِلِيَّةِ؟ قَالَ: بَقَاؤُكُمْ عَلَيْهِ مَا اسْتَقَامَتْ بِكُمْ أَئِمَّتُكُمْ. قَالَتْ: وَمَا الْأَئِمَّةُ؟ قَالَ: أَمَا كَانَ لِقَوْمِكِ رُؤوسٌ وَأَشْرَافٌ يَأْمُرُونَهُمْ فَيُطِيعُونَهُمْ. قَالَتْ: بَلَى. قَالَ: فَهُمْ أُولَئِكِ عَلَى النَّاسِ."],"takhrij":"صحيح: رواه البخاري في مناقب الأنصار (3834) عن أبي النعمان، حدثنا أبو عوانة، عن بيانٍ أبي بشر، عن قيس بن أبي حازم قال: فذكره.","grade":"صحيح","chapter_ar":"باب فضل من تولى أمر المسلمين وحكم فيهم بالعدل","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3834).","chapter_en":"The Virtue of One Who Takes Charge of the Muslims’ Affairs and Judges Among Them with Justice","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Qays ibn Abi Hazim said: Abu Bakr entered upon a woman from Ahmas named Zaynab and saw that she was not speaking. He said: “What is wrong with her that she does not speak?” They said: “She performed pilgrimage while keeping silent.” He said to her: “Speak, for this is not lawful. This is from the practice of the pre-Islamic period.” So she spoke and said: “Who are you?” He said: “A man from the emigrants.” She said: “Which emigrants?” He said: “From Quraysh.” She said: “From which branch of Quraysh are you?” He said: “You ask many questions. I am Abu Bakr.” She said: “How long will we remain upon this righteous matter that Allah brought after the pre-Islamic period?” He said: “You will remain upon it as long as your leaders remain upright over you.” She said: “And what are the leaders?” He said: “Did your people not have chiefs and nobles who commanded them and they obeyed them?” She said: “Yes.” He said: “Those are the ones over the people.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3834,"lafz":true}],"full":1},{"num":7592,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ، بْنِ شُمَاسَةَ قَالَ أَتَيْتُ عَائِشَةَ أَسْأَلُهَا عَنْ شَىْءٍ، فَقَالَتْ مِمَّنْ أَنْتَ فَقُلْتُ رَجُلٌ مِنْ أَهْلِ مِصْرَ. فَقَالَتْ كَيْفَ كَانَ صَاحِبُكُمْ لَكُمْ فِي غَزَاتِكُمْ هَذِهِ فَقَالَ مَا نَقَمْنَا مِنْهُ شَيْئًا إِنْ كَانَ لَيَمُوتُ لِلرَّجُلِ مِنَّا الْبَعِيرُ فَيُعْطِيهِ الْبَعِيرَ وَالْعَبْدُ فَيُعْطِيهِ الْعَبْدَ وَيَحْتَاجُ إِلَى النَّفَقَةِ فَيُعْطِيهِ النَّفَقَةَ فَقَالَتْ أَمَا إِنَّهُ لاَ يَمْنَعُنِي الَّذِي فَعَلَ فِي مُحَمَّدِ بْنِ أَبِي بَكْرٍ أَخِي أَنْ أُخْبِرَكَ مَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي بَيْتِي هَذَا اللَّهُمَّ مَنْ وَلِيَ مِنْ أَمْرِ أُمَّتِي شَيْئًا فَشَقَّ عَلَيْهِمْ فَاشْقُقْ عَلَيْهِ وَمَنْ وَلِيَ مِنْ أَمْرِ أُمَّتِي شَيْئًا فَرَفَقَ بِهِمْ فَارْفُقْ بِهِ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1828) عن هارون بن سعيد الأيلي، حدثنا ابن وهب، حدثني حرملة، عن عبد الرحمن بن شمامة قال: فذكره.","grade":"صحيح","chapter_ar":"باب الترغيب في الرفق بالرعية","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1828).","chapter_en":"Encouragement to Be Gentle with the Subjects","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["ʿAbd al-Rahman ibn Shumasah said: I came to ʿA’ishah to ask her about something. She said: “Where are you from?” I said: “A man from the people of Egypt.” She said: “How was your governor toward you in this campaign of yours?” He said: “We found nothing to criticize in him. If a man’s camel died, he would give him another camel; if a man’s servant died, he would give him another servant; and if someone needed expenses, he would give him expenses.” She said: “What was done to my brother Muhammad ibn Abi Bakr does not prevent me from telling you what I heard from the Messenger of Allah ﷺ in this house of mine. He said: ‘O Allah, whoever is appointed over any matter of my nation and makes things difficult for them, make things difficult for him; and whoever is appointed over any matter of my nation and is gentle with them, be gentle with him.’”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1828,"lafz":true}],"full":1},{"num":7593,"demo":false,"sanad":"","matn":["عَنْ أَبِي وَائِلٍ قَالَ: قَالَ عَبْدُ الله بن مسعود: لَقَدْ أَتَانِي الْيَوْمَ رَجُلٌ، فَسَأَلَنِي عَنْ أَمْرٍ مَا دَرَيْتُ مَا أَرُدُّ عَلَيْهِ، فَقَالَ: أَرَأَيْتَ رَجُلًا مُؤْدِيًا نَشِيطًا يَخْرُجُ مَعَ أُمَرَائِنَا فِي المَغَازِي، فَيَعْزِمُ عَلَيْنَا فِي أَشْيَاءَ لَا نُحْصِيهَا؟ فَقُلْتُ لَهُ: وَاللهِ مَا أَدْرِي مَا أَقُولُ لَكَ، إِلَّا أَنَّا كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَعَسَى أَنْ لَا يَعْزِمَ عَلَيْنَا فِي أَمْرٍ إِلَّا مَرَّةً حَتَّى نَفْعَلَهُ، وَإِنَّ أَحَدَكُمْ لَنْ يَزَالَ بِخَيْرٍ مَا اتَّقَى الله، وَإِذَا شَكَّ فِي نَفْسِهِ شَيْءٌ سَأَلَ رَجُلًا فَشَفَاهُ مِنْهُ، وَأَوْشَكَ أَنْ لَا تَجِدُوهُ، وَالَّذِي لَا إِلَهَ إِلَّا هُوَ، مَا أَذْكُرُ مَا غَبَرَ مِنْ الدُّنْيَا إِلَّا كَالثَّغْبِ، شُرِبَ صَفْوُهُ، وَبَقِيَ كَدَرُهُ."],"takhrij":"صحيح: رواه البخاري في الجهاد (2964) عن عثمان بن أبي شيبة حدثنا جرير عن منصور عن أبي وائل قال: فذكره.","grade":"صحيح","chapter_ar":"باب عزم الإمام على الناس فيما يطيقون","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2964).","chapter_en":"The Leader’s Firm Command to the People Regarding What They Are Able to Bear","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Abu Wa’il said: ʿAbdullah ibn Masʿud said: Today a man came to me and asked me about a matter, and I did not know what to answer him. He said: “What do you think of a well-equipped, energetic man who goes out with our commanders in military campaigns, and they impose upon us things that we cannot bear?” I said to him: “By Allah, I do not know what to say to you, except that we were with the Prophet ﷺ, and perhaps he would not command us firmly in any matter more than once before we did it. One of you will continue to be upon good as long as he remains mindful of Allah. If something troubles him, he asks a man who removes that trouble from him; but soon you may not find such a person. By the One besides whom there is no god, I do not remember what has passed of this world except like a small pool: its clear part has been drunk, and its muddy part remains.”"]},"buhuth":{"en":["His phrase “well-equipped” means possessing complete equipment for war. His phrase “impose upon us” means to make matters difficult for us. His phrase “we cannot bear them” means we are unable to endure them. The “small pool” is stagnant water gathered in a low place."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2964,"lafz":true}],"full":1,"dr":1},{"num":7594,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى، قَالَ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا بَعَثَ أَحَدًا مِنْ أَصْحَابِهِ فِي بَعْضِ أَمْرِهِ قَالَ بَشِّرُوا وَلاَ تُنَفِّرُوا وَيَسِّرُوا وَلاَ تُعَسِّرُوا."],"takhrij":"صحيح: رواه مسلم في الجهاد (1732) من طرق عن أبي أسامة، عن بُريد بن عبد الله، عن أبي بُردة، عن أبي موسى فذكره.","grade":"صحيح","chapter_ar":"باب توصية الإمام لولاته وعماله بالتيسير على رعيتهم","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1732).","chapter_en":"The Leader’s Instruction to His Governors and Workers to Make Things Easy for Their Subjects","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abu Musa said: Whenever the Messenger of Allah ﷺ sent one of his Companions on some task, he would say: “Give glad tidings and do not repel people; make things easy and do not make things difficult.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1732,"lafz":true}],"full":1,"rep":[12812]},{"num":7595,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ أَبِي بُرْدَةَ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ مُعَاذًا وَأَبَا مُوسَى إِلَى الْيَمَنِ قَالَ يَسِّرَا وَلاَ تُعَسِّرَا، وَبَشِّرَا وَلاَ تُنَفِّرَا، وَتَطَاوَعَا وَلاَ تَخْتَلِفَا."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (3038)، ومسلم في الجهاد (1733) كلاهما من طريق وكيع، عن شعبة، عن سعيد بن أبي بردة، عن أبيه، عن جده (وهو أبو موسى الأشعري) فذكره.","grade":"متفق عليه","chapter_ar":"باب توصية الإمام لولاته وعماله بالتيسير على رعيتهم","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3038) and Muslim (1733).","chapter_en":"The Leader’s Instruction to His Governors and Workers to Make Things Easy for Their Subjects","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Saʿid ibn Abi Burdah narrated from his father, from his grandfather, that the Prophet ﷺ sent Muʿadh and Abu Musa to Yemen and said: “Make things easy and do not make things difficult; give glad tidings and do not repel people; cooperate with one another and do not differ.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3038,"lafz":true},{"key":"muslim","label":"مسلم","number":1733}],"full":1,"rep":[14704]},{"num":7596,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: قال رسول الله صلي الله عليه وسلم: يسّروا ولا تعسّروا، وسكنوا و لاتنفروا."],"takhrij":"متفق عليه: رواه البخاري في العلم (69)، ومسلم في الجهاد (1734) كلاهما من طرق عن شعبة، عن أبي التياح قال: سمعت أنس بن مالك يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب توصية الإمام لولاته وعماله بالتيسير على رعيتهم","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (69) and Muslim (1734).","chapter_en":"The Leader’s Instruction to His Governors and Workers to Make Things Easy for Their Subjects","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ said: “Make things easy and do not make things difficult; calm people and do not repel them.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":69,"lafz":true},{"key":"muslim","label":"مسلم","number":1734}],"full":1},{"num":7597,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ أَلاَ كُلُّكُمْ رَاعٍ، وَكُلُّكُمْ مَسْئُولٌ عَنْ رَعِيَّتِهِ، فَالإِمَامُ الَّذِي عَلَى النَّاسِ رَاعٍ وَهْوَ مَسْئُولٌ عَنْ رَعِيَّتِهِ، وَالرَّجُلُ رَاعٍ عَلَى أَهْلِ بَيْتِهِ وَهْوَ مَسْئُولٌ عَنْ رَعِيَّتِهِ، وَالْمَرْأَةُ رَاعِيَةٌ عَلَى أَهْلِ بَيْتِ زَوْجِهَا وَوَلَدِهِ وَهِيَ مَسْئُولَةٌ عَنْهُمْ، وَعَبْدُ الرَّجُلِ رَاعٍ عَلَى مَالِ سَيِّدِهِ وَهْوَ مَسْئُولٌ عَنْهُ، أَلاَ فَكُلُّكُمْ رَاعٍ وَكُلُّكُمْ مَسْئُولٌ عَنْ رَعِيَّتِهِ."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7138) من طريق مالك، عن عبدالله بن دينار، عن عبد الله بن عمر فذكره. وليس الحديث في الموطأ برواية الليثي.","grade":"متفق عليه","chapter_ar":"باب مسؤولية الراعي عن رعيته","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7138) and Muslim (1829:20).","chapter_en":"The Shepherd’s Responsibility for His Flock","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “Indeed, each of you is a shepherd, and each of you is responsible for his flock. The leader over the people is a shepherd, and he is responsible for his flock. A man is a shepherd over the people of his household, and he is responsible for his flock. A woman is a shepherd over the household of her husband and his child, and she is responsible for them. A man’s servant is a shepherd over his master’s wealth, and he is responsible for it. Indeed, each of you is a shepherd, and each of you is responsible for his flock.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7138,"lafz":true},{"key":"muslim","label":"مسلم","number":1829}],"full":1,"dr":1},{"num":7598,"demo":false,"sanad":"","matn":["عَنْ مَعْقِلِ بن يَسَارٍ الْمُزَنِيِّ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَا مِنْ عَبْدٍ اسْتَرْعَاهُ اللَّهُ رَعِيَّةً فَلَمْ يَحُطْهَا بِنَصِيحَةٍ إِلاَّ لَمْ يَجِدْ رَائِحَةَ الْجَنَّةِ.","وفي رواية: فيموت وهو غاش لهم إلا حرّم الله عليه الجنة."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7150)، ومسلم في الإمارة (142: 21) كلاهما من طريق أبي الأشهب، عن الحسن، أن عبيد الله بن زياد عاد معقل بن يسار في مرضه الذي مات فيه، فقال له معقل: إني محدثك حديثا سمعته من رسول الله صلى الله عليه وسلم، سمعت النبي صلى الله عليه وسلم يقول: فذكره. والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب مسؤولية الراعي عن رعيته","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7150, 7151) and Muslim (142:21).","chapter_en":"The Shepherd’s Responsibility for His Flock","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Maʿqil ibn Yasar al-Muzani said: I heard the Prophet ﷺ say: “There is no servant whom Allah places in charge of a people, and he does not surround them with sincere care, except that he will not find the fragrance of Paradise.” In another narration: “If he dies while deceiving them, Allah will forbid Paradise for him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7150,"lafz":true},{"key":"muslim","label":"مسلم","number":142}],"full":1,"dr":1},{"num":7599,"demo":false,"sanad":"","matn":["عن الْحَسَنِ أَنَّ عَائِذَ بْنَ عَمْرٍو، - وَكَانَ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - دَخَلَ عَلَى عُبَيْدِ اللَّهِ بْنِ زِيَادٍ فَقَالَ أَىْ بُنَىَّ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ إِنَّ شَرَّ الرِّعَاءِ الْحُطَمَةُ فَإِيَّاكَ أَنْ تَكُونَ مِنْهُمْ. فَقَالَ لَهُ اجْلِسْ فَإِنَّمَا أَنْتَ مِنْ نُخَالَةِ أَصْحَابِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ وَهَلْ كَانَتْ لَهُمْ نُخَالَةٌ إِنَّمَا كَانَتِ النُّخَالَةُ بَعْدَهُمْ وَفِي غَيْرِهِمْ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1830) عن شيبان بن فروخ، حدثنا جرير بن حازم، حدثنا الحسن به فذكره.","grade":"صحيح","chapter_ar":"باب مسؤولية الراعي عن رعيته","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1830).","chapter_en":"The Shepherd’s Responsibility for His Flock","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Al-Hasan narrated that ʿA’idh ibn ʿAmr, who was one of the Companions of the Messenger of Allah ﷺ, entered upon ʿUbaydullah ibn Ziyad and said: “My son, I heard the Messenger of Allah ﷺ say: ‘The worst shepherds are the harsh ones, so beware of being one of them.’” He said to him: “Sit down. You are only from the leftovers of the Companions of Muhammad ﷺ.” He replied: “Were there leftovers among them? Leftovers only came after them and among others.”"]},"buhuth":{"en":["The phrase “the harsh ones” refers to those who are violent with their subjects and do not show gentleness toward them. His phrase “from the leftovers” means: you are not from the virtuous Companions of the Messenger of Allah ﷺ, nor from their scholars and people of high rank, but from their lower class. “Leftovers” refers to the husks of flour."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1830,"lafz":true}],"full":1,"dr":1},{"num":7600,"demo":false,"sanad":"","matn":["عن عَمْرِو بْنِ حَزْمٍ الأنصاري قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ اللَّهَ لَمْ يَسْتَرْعِ عَبْدًا رَعِيَّةً إِلَّا وَهُوَ سَائِلُهُ عَنْهَا يَوْمَ الْقِيَامَةِ: كَيْفَ صَنَعَ فِيهَا."],"takhrij":"حسن: رواه أبو يعلى (7174) عن الحسن بن عمر بن شقيق بن أسماء الجرمي، حدثنا جعفر، عن هشام، عن محمد بن سيرين فذكر زيارة عمرو بن حزم الأنصاري لمعاوية بن أبي سفيان عندما استخلف ابنه يزيد بن أبي معاوية في قصة طويلة، وذكر أن عمرو بن حزم حدّث بهذا الحديث عند معاوية.","grade":"حسن","chapter_ar":"باب مسؤولية الراعي عن رعيته","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Yaʿla (7174).","chapter_en":"The Shepherd’s Responsibility for His Flock","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿAmr ibn Hazm al-Ansari said: I heard the Messenger of Allah ﷺ say: “Allah does not place a servant in charge of a people except that He will ask him about them on the Day of Resurrection: how did he deal with them?”"]}},"tuhfa":{},"refs":[{"key":"sh12520","label":"أبو يعلى","number":7174,"lafz":true}],"full":1,"dr":1},{"num":7601,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ رضي الله عنه قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  صِنْفَانِ مِنْ أُمَّتِي لَا تَنَالُهُمَا شَفَاعَتِي ولَنْ تَنَالَهُمَا شَفَاعَتِي أَوْ لَنْ أَشْفَعَ لَهُمَا أَمِيرٌ ظَلُومٌ غَشُومٌ عَسُوفٌ وَكُلُّ غَالٍ مَارِقٍ."],"takhrij":"حسن: رواه مسدد (2157- المطالب) عن جعفر بن سليمان، عن المعلى، عن أبي غالب، عن أبي أمامة فذكره.","grade":"حسن","chapter_ar":"باب مسؤولية الراعي عن رعيته","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Musaddad (al-Matalib, 2157) and al-Tabarani (8/337).","chapter_en":"The Shepherd’s Responsibility for His Flock","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abu Umamah said: The Messenger of Allah ﷺ said: “Two types from my nation will not receive my intercession, or I will not intercede for them: an unjust, oppressive, tyrannical ruler, and every extremist who leaves the religion.”"]}},"tuhfa":{},"refs":[{"key":"مسدد","label":"مسدد","number":2157,"lafz":true},{"key":"mujamkabir","label":"الطبراني","number":8}],"full":1,"dr":1},{"num":7602,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَرْيَمَ الأزدى أَخْبَرَهُ قَالَ: دَخَلْتُ عَلَى مُعَاوِيَةَ، فَقَالَ: مَا أَنْعَمَنَا بِكَ أَبَا فُلاَنٍ. وهى كَلِمَةٌ تَقُولُهَا الْعَرَبُ، فَقُلْتُ: حَدِيثًا سَمِعْتُهُ أُخْبِرُكَ بِهِ، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ وَلاَّهُ اللَّهُ عَزَّ وَجَلَّ شَيْئًا مِنْ أَمْرِ الْمُسْلِمِينَ، فَاحْتَجَبَ دُونَ حَاجَتِهِمْ وَخَلَّتِهِمْ وَفَقْرِهِمُ احْتَجَبَ اللَّهُ عَنْهُ دُونَ حَاجَتِهِ وَخَلَّتِهِ وَفَقْرِهِ.","قال: فجعل رجلا على حوائج الناس."],"takhrij":"صحيح: رواه أبو داود ( 2948)، والترمذي (1333)، والحاكم (4/93-94) كلهم من حديث يزيد بن أبي مريم، أن القاسم بن مخيمرة أخبره، أن أبا مريم الأزدي أخبره فذكر الحديث واللفظ لأبي داود. وسكت عليه الترمذي.","grade":"صحيح","chapter_ar":"باب الترغيب في أن يكون الإمام مهتماً بأمور رعيته","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2948), al-Tirmidhi (1333), and al-Hakim (4/93–94). The wording is from Abu Dawud.","chapter_en":"Encouragement for the Leader to Be Concerned with the Affairs of His Subjects","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu Maryam al-Azdi said: I entered upon Muʿawiyah, and he said: “How pleasant your visit is, Abu so-and-so.” This is an expression used by the Arabs. I said: “I will inform you of a hadith I heard. I heard the Messenger of Allah ﷺ say: ‘Whoever Allah, the Mighty and Majestic, appoints over any matter of the Muslims, then he blocks himself from their needs, their poverty, and their hardship, Allah will block Himself from his need, his poverty, and his hardship.’” He said: So Muʿawiyah appointed a man to handle the needs of the people."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2948,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1333},{"key":"hakim","label":"الحاكم","number":4}],"full":1,"dr":1},{"num":7603,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَا أُعْطِيكُمْ وَلاَ أَمْنَعُكُمْ، أَنَا قَاسِمٌ أَضَعُ حَيْثُ أُمِرْتُ."],"takhrij":"صحيح: رواه البخاري في فرض الخمس (3117) عن محمد بن سنان، حدثنا فُليح، حدثنا هلال، عن عبد الرحمن بن عمرة، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ولي الأمر يقدر أرزاق الولاة والعمال","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3117).","chapter_en":"The Ruler Determines the Stipends of Governors and Workers","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “I neither give you nor withhold from you by myself. I am only a distributor; I place it where I have been commanded.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3117,"lafz":true}],"full":1,"rep":[8026]},{"num":7604,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ الْعَاصِ قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنِّي أُرِيدُ أَنْ أَبْعَثَكَ عَلَى جَيْشٍ، فَيُسَلِّمَكَ اللهُ، وَيُغْنِمَكَ، وأرغب لَكَ مِنَ الْمَالِ رَغْبَةً صَالِحَةً، قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ مَا أَسْلَمْتُ مِنْ أَجْلِ الْمَالِ، وَلَكِنِّي أَسْلَمْتُ رَغْبَةً فِي الْإِسْلَامِ، وَأَنْ أَكُونَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : نِعْمًا بِالْمَالِ الصَّالِحُ لِلرَّجُلِ الصَّالِحِ."],"takhrij":"صحيح: رواه أحمد (17763)، والطبراني في الأوسط (3213)، والحاكم (2/236) كلهم من طريق موسى بن عُلَيّ بن رباح، عن أبيه قال: سمعت عمرو بن العاص فذكره. وإسناده صحيح. قال الحاكم: \"صحيح على شرط مسلم\".","grade":"صحيح","chapter_ar":"باب ولي الأمر يقدر أرزاق الولاة والعمال","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (17763), al-Tabarani in al-Awsat (3213), and al-Hakim (2926).","chapter_en":"The Ruler Determines the Stipends of Governors and Workers","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["ʿAmr ibn al-ʿAs said: The Messenger of Allah ﷺ said to me: “I want to send you over an army, so Allah will keep you safe and grant you spoils, and I desire for you a good share of wealth.” He said: I said: “O Messenger of Allah, I did not embrace Islam for wealth. Rather, I embraced Islam out of desire for Islam and to be with the Messenger of Allah ﷺ.” The Messenger of Allah ﷺ said: “How excellent is righteous wealth for a righteous man.”"]}},"tuhfa":{},"refs":[{"key":"sh28171","label":"الطبراني في الأوسط","number":3213},{"key":"ahmad","label":"مسند الإمام أحمد","number":17763,"n":17763,"lafz":true},{"key":"hakim","label":"المستدرك على الصحيحين","number":2926,"n":2912}],"full":1},{"num":7605,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ، قَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَا عَبْدَ الرَّحْمَنِ لاَ تَسْأَلِ الإِمَارَةَ، فَإِنَّكَ إِنْ أُعْطِيتَهَا عَنْ مَسْأَلَةٍ وُكِلْتَ إِلَيْهَا، وَإِنْ أُعْطِيتَهَا عَنْ غَيْرِ مَسْأَلَةٍ أُعِنْتَ عَلَيْهَا، وَإِذَا حَلَفْتَ عَلَى يَمِينٍ فَرَأَيْتَ غَيْرَهَا خَيْرًا مِنْهَا، فَكَفِّرْ يَمِينَكَ، وَأْتِ الَّذِي هُوَ خَيْرٌ."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7146)، ومسلم في الإمارة (1652: 13) كلاهما من طريق جرير بن حازم، حدثنا الحسن، حدثنا عبد الرحمن بن سمرة فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن طلب الإمارة والحرص عليها","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7146) and Muslim (1652:13).","chapter_en":"The Prohibition of Seeking Leadership and Being Eager for It","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["ʿAbd al-Rahman ibn Samurah said: The Prophet ﷺ said to me: “O ʿAbd al-Rahman ibn Samurah, do not ask for leadership. If you are given it because of asking, you will be left to it; but if you are given it without asking, you will be helped in it. And if you swear an oath, then see something else better than it, expiate your oath and do what is better.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7146,"lafz":true},{"key":"muslim","label":"مسلم","number":1652}],"full":1},{"num":7606,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى قَالَ: أَقْبَلْتُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَعِي رَجُلاَنِ مِنَ الأَشْعَرِيِّينَ، أَحَدُهُمَا عَنْ يَمِينِي، وَالآخَرُ عَنْ يَسَارِي، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَاكُ فَكِلاَهُمَا سَأَلَ الْعَمَلَ والنبي صَلَّى اللَّهِ عَلَيْهِ وَسَلَّمَ يَسْتَاكُ، فَقَالَ:  مَا تَقُولُ: يَا أَبَا مُوسَى أَوْ يَا عَبْدَ اللَّهِ بْنَ قَيْسٍ؟ فَقُلْتُ: وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا أَطْلَعَانِي عَلَى مَا فِي أَنْفُسِهِمَا، وَمَا شَعَرْتُ أَنَّهُمَا يَطْلُبَانِ الْعَمَلَ. وكأني أَنْظُرُ إِلَى سِوَاكِهِ تَحْتِ شَفَتِهِ وَقَدْ قَلَصَتْ، فَقَالَ: لَنْ -أَوْ- لاَ نَسْتَعْمِلُ عَلَى عَمَلِنَا مَنْ أَرَادَهُ، وَلَكِنِ اذْهَبْ أَنْتَ يَا أَبَا مُوسَى أَوْ يَا عَبْدَ اللَّهِ بْنَ قَيْسٍ فبعثه عَلَى الْيَمَنِ، ثُمَّ أَتْبَعَهُ مُعَاذُ بْنُ جَبَلٍ، فَلَمَّا قَدِمَ عَلَيْهِ قَالَ: انْزِلْ، وألقى لَهُ وِسَادَةً، وَإِذَا رَجُلٌ عِنْدَهُ مُوثَقٌ قَالَ: مَا هَذَا؟ قَالَ: هذاكان يَهُودِيًّا فَأَسْلَمَ ثُمَّ راجع دينه دين السوء فتهود، قَالَ: لاَ أجلس حَتَّى يُقْتَلَ، قَضَاءُ اللَّهِ وَرَسُولِهِ، فَقَالَ: اجْلِسْ، نَعَمْ، قَالَ: لاَ أَجْلِسُ حَتَّى يُقْتَلَ، قَضَاءُ اللَّهِ وَرَسُولِهِ -ثَلاَثَ مَرَّاتٍ- فَأَمَرَ بِهِ، فقُتلَ. ثُمَّ تذاكرا القيام من اللَّيْلِ فَقَالَ: أَحَدُهُمَا -مُعَاذُ- أَمَّا أَنَا فأنام وأقوم، وَأَرْجُو فِي نَوْمَتِي مَا أَرْجُو فِي قَوْمَتِي."],"takhrij":"متفق عليه: رواه البخاري في استتابة المرتدين (6923)، ومسلم في الإمارة (1733: 15) كلاهما من طريق يحيى القطان، حدثنا قرة بن خالد، حدثنا حميد بن هلال، حدثني أبو بردة قال: قال أبو موسى فذكره. والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن طلب الإمارة والحرص عليها","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6923) and Muslim (1733:15). The wording is from Muslim.","chapter_en":"The Prohibition of Seeking Leadership and Being Eager for It","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Abu Musa said: I came to the Prophet ﷺ with two men from the Ashʿaris, one on my right and the other on my left, while the Messenger of Allah ﷺ was brushing his teeth. Both of them asked for an official position while the Prophet ﷺ was brushing his teeth. He said: “What do you say, Abu Musa, or ʿAbdullah ibn Qays?” I said: “By the One who sent you with the truth, they did not inform me of what was in their hearts, and I did not know that they were seeking office.” It is as if I can still see his tooth-stick beneath his lip, which had drawn back. He said: “We will never — or we do not — appoint to our work one who desires it. But you, Abu Musa, or ʿAbdullah ibn Qays, go to Yemen.” Then he sent Muʿadh ibn Jabal after him. When Muʿadh came to him, he said: “Dismount,” and he placed a cushion for him. There was a man bound with him. Muʿadh said: “What is this?” He said: “This man was a Jew, then he embraced Islam, then he returned to his evil religion and became a Jew again.” Muʿadh said: “I will not sit until he is killed, as the judgment of Allah and His Messenger.” He said: “Sit.” He said: “Yes, but I will not sit until he is killed, as the judgment of Allah and His Messenger.” He said this three times. So he ordered that he be killed. Then they discussed standing in prayer at night. One of them, Muʿadh, said: “As for me, I sleep and I stand, and I hope for reward in my sleep as I hope for reward in my standing.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6923,"lafz":true},{"key":"muslim","label":"مسلم","number":1733,"n":4718}],"full":1},{"num":7607,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ قَالَ دَخَلْتُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَا وَرَجُلاَنِ مِنْ قَوْمِي فَقَالَ أَحَدُ الرَّجُلَيْنِ أَمِّرْنَا يَا رَسُولَ اللَّهِ. وَقَالَ الآخَرُ مِثْلَهُ. فَقَالَ إِنَّا لاَ نُوَلِّي هَذَا مَنْ سَأَلَهُ، وَلاَ مَنْ حَرَصَ عَلَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7149)، ومسلم في الإمارة (1733: 14) كلاهما عن محمد بن العلاء، حدثنا أبو أسامة، عن بريد، عن أبي بردة، عن أبي موسى قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن طلب الإمارة والحرص عليها","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7149) and Muslim (1733:14).","chapter_en":"The Prohibition of Seeking Leadership and Being Eager for It","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Abu Musa said: I entered upon the Prophet ﷺ with two men from my people. One of the two men said: “Appoint us, O Messenger of Allah.” The other said the same. He said: “We do not appoint to this matter one who asks for it, nor one who is eager for it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7149,"lafz":true},{"key":"muslim","label":"مسلم","number":1733}],"full":1},{"num":7608,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِنَّكُمْ سَتَحْرِصُونَ عَلَى الإِمَارَةِ، وَسَتَكُونُ نَدَامَةً يَوْمَ الْقِيَامَةِ، فَنِعْمَ الْمُرْضِعَةُ وَبِئْسَتِ الْفَاطِمَةُ."],"takhrij":"صحيح: رواه البخاري في الأحكام (7148) عن أحمد بن يونس حدثنا ابن أبي ذئب، عن سعيد المقبري، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن طلب الإمارة والحرص عليها","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7148).","chapter_en":"The Prohibition of Seeking Leadership and Being Eager for It","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “You will be eager for leadership, but it will be regret on the Day of Resurrection. How excellent is the nursing mother, and how terrible is the weaning mother.”"]},"buhuth":{"en":["His phrase “How excellent is the nursing mother, and how terrible is the weaning mother” means: it is excellent while it provides status, wealth, authority, and sensory and imagined pleasures during its possession; but it is terrible when one is separated from it through death or otherwise, because of the consequences that follow it in the Hereafter. Fath al-Bari (13/126)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7148,"lafz":true}],"full":1,"dr":1},{"num":7609,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، قَالَ قُلْتُ يَا رَسُولَ اللَّهِ أَلاَ تَسْتَعْمِلُنِي قَالَ فَضَرَبَ بِيَدِهِ عَلَى مَنْكِبِي ثُمَّ قَالَ يَا أَبَا ذَرٍّ إِنَّكَ ضَعِيفٌ وَإِنَّهَا أَمَانَةٌ وَإِنَّهَا يَوْمَ الْقِيَامَةِ خِزْىٌ وَنَدَامَةٌ إِلاَّ مَنْ أَخَذَهَا بِحَقِّهَا وَأَدَّى الَّذِي عَلَيْهِ فِيهَا."],"takhrij":"صحيح: رواه مسلم في الإمارة (1825) عن عبد الملك بن شعيب بن الليث، حدثني أبي شعيب بن الليث، حدثني الليث بن سعد، حدثني يزيد بن أبي حبيب، عن بكر بن عمرو، عن الحارث بن يزيد الحضرمي، عن ابن حجيرة الأكبر، عن أبي ذر قال: فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن طلب الإمارة والحرص عليها","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1825).","chapter_en":"The Prohibition of Seeking Leadership and Being Eager for It","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Abu Dharr said: I said: “O Messenger of Allah, will you not appoint me?” He struck my shoulder with his hand and said: “O Abu Dharr, you are weak, and it is a trust. On the Day of Resurrection it will be disgrace and regret, except for one who takes it with its right and fulfills what is due regarding it.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1825,"lafz":true}],"full":1,"rep":[6725]},{"num":7610,"demo":false,"sanad":"","matn":["عَنْ عَوْفُ بْنُ مَالِكٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: إِنْ شِئْتُمْ أَنْبَأْتُكُمْ عَنِ الإِمَارَةِ، وَمَا هِيَ؟ فَنَادَيْتُ بِأَعْلَى صَوْتِي ثَلاثَ مَرَّاتٍ: مَا هِيَ يَا رَسُولَ اللَّهِ؟ قَالَ: أَوَّلُهَا مَلامَةٌ، وَثَانِيهَا نَدَامَةٌ، وَثَالِثُهَا عَذَابٌ يَوْمَ الْقِيَامَةِ، إِلَّا مَنْ عَدَلَ، وَكَيْفَ يَعْدِلُ مَعَ أَقْرَبِيهِ."],"takhrij":"صحيح: رواه البزار (2756)، والطبراني في الكبير (18/ 132)، والأوسط (2533- مجمع البحرين) كلاهما من طرق عن صدقة بن خالد، عن زيد بن واقد، عن بُسر بن عبيدالله، عن يزيد الأصم، عن عوف بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن طلب الإمارة والحرص عليها","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bazzar (2756), al-Tabarani in al-Kabir (18/132), and al-Awsat (Majmaʿ al-Bahrayn 2533).","chapter_en":"The Prohibition of Seeking Leadership and Being Eager for It","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["ʿAwf ibn Malik narrated from the Prophet ﷺ that he said: “Shall I inform you about leadership and what it is?” I stood and called out at the top of my voice three times: “What is it, O Messenger of Allah?” He said: “Its beginning is blame, its second stage is regret, and its third stage is punishment on the Day of Resurrection, except for one who is just. But how can he be just with his relatives?”"]}},"tuhfa":{},"refs":[{"key":"bazzar","label":"البزار","number":2756,"lafz":true,"n":2755},{"key":"mujamkabir","label":"الطبراني في الكبير","number":18},{"key":"sh28171","label":"الأوسط","number":2533},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1597,"n":1598},{"key":"sh12862","label":"البزار","number":2756}],"full":1,"dr":1},{"num":7611,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ يَا أَبَا ذَرٍّ إِنِّي أَرَاكَ ضَعِيفًا وَإِنِّي أُحِبُّ لَكَ مَا أُحِبُّ لِنَفْسِي لاَ تَأَمَّرَنَّ عَلَى اثْنَيْنِ وَلاَ تَوَلَّيَنَّ مَالَ يَتِيمٍ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1826) من طريق عبد الله بن يزيد المقرئ، حدثنا سعيد بن أبي أيوب، عن عبيد الله بن أبي جعفر القرشي، عن سالم بن أبي سالم الجيشاني، عن أبيه، عن أبي ذر فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن طلب الإمارة والحرص عليها","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1826).","chapter_en":"The Prohibition of Seeking Leadership and Being Eager for It","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Abu Dharr narrated that the Messenger of Allah ﷺ said: “O Abu Dharr, I see that you are weak, and I love for you what I love for myself. Do not be placed in authority over even two people, and do not take charge of an orphan’s wealth.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1826,"lafz":true}],"full":1,"rep":[6726,12653]},{"num":7612,"demo":false,"sanad":"","matn":["عَنِ الْمِقْدَادِ بْنِ الْأَسْوَدِ قَالَ: بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَبْعَثًا فَلَمَّا رَجَعْتُ قَالَ لِي: كَيْفَ تَجِدُ نَفْسَكَ؟ قُلْتُ: مَا زِلْتُ حَتَّى ظَنَنْتُ أَنَّ مَنْ مَعِي خَوَلًا لِي وَايْمُ اللَّهِ لَا أَعْمَلُ عَلَى رَجُلَيْنِ بَعْدَهُمَا هَذَا."],"takhrij":"حسن: رواه النسائي في الكبرى (8695)، والطبراني في الكبير (20/258-259)، والحاكم (3/349-350) كلهم من طرق عن بشر بن المفضل، حدثنا عبد الله بن عون، عن عمير بن إسحاق، عن المقداد بن الأسود فذكره.","grade":"حسن","chapter_ar":"باب النهي عن طلب الإمارة والحرص عليها","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i in al-Kubra (8695), al-Tabarani in al-Kabir (20/258–259), and al-Hakim (5488).","chapter_en":"The Prohibition of Seeking Leadership and Being Eager for It","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Miqdad ibn al-Aswad said: The Prophet ﷺ sent me on a mission. When I returned, he said to me: “How do you find yourself?” I said: “I remained in such a state that I thought I had servants belonging to me. By Allah, I will never again take charge over two men after this.”"]},"buhuth":{"en":["His phrase “servants belonging to me” means what Allah has granted a person of blessings, male servants, female servants, and the like."]}},"tuhfa":{},"refs":[{"key":"kubranasai","label":"النسائي في الكبرى","number":8695,"lafz":true},{"key":"mujamkabir","label":"الطبراني في الكبير","number":20},{"key":"hakim","label":"المستدرك على الصحيحين","number":5488,"n":5484}],"full":1,"dr":1},{"num":7613,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِنَّمَا الإِمَامُ جُنَّةٌ يُقَاتَلُ مِنْ وَرَائِهِ وَيُتَّقَى بِهِ فَإِنْ أَمَرَ بِتَقْوَى اللَّهِ عَزَّ وَجَلَّ وَعَدَلَ كَانَ لَهُ بِذَلِكَ أَجْرٌ وَإِنْ يَأْمُرْ بِغَيْرِهِ كَانَ عَلَيْهِ مِنْهُ."],"takhrij":"متفق عليه:  رواه البخاري في الجهاد والسير (2957)، ومسلم في الإمارة (1841) كلاهما من حديث أبي الزناد، عن الأعرج، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب الإمام جُنّة يقاتل من ورائه ويتقى به","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2957) and Muslim (1841).","chapter_en":"The Leader Is a Shield Behind Whom Fighting Is Done and Through Whom Protection Is Sought","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “The leader is only a shield behind whom fighting is done and through whom protection is sought. If he commands mindfulness of Allah, the Mighty and Majestic, and acts justly, he will have reward for that. But if he commands something other than that, then it will be against him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2957,"lafz":true},{"key":"muslim","label":"مسلم","number":1841}],"full":1,"rep":[7589]},{"num":7614,"demo":false,"sanad":"","matn":["عَنْ عَوْفِ بْنِ مَالِكٍ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ خِيَارُ أَئِمَّتِكُمُ الَّذِينَ تُحِبُّونَهُمْ وَيُحِبُّونَكُمْ وَيُصَلُّونَ عَلَيْكُمْ وَتُصَلُّونَ عَلَيْهِمْ وَشِرَارُ أَئِمَّتِكُمُ الَّذِينَ تُبْغِضُونَهُمْ وَيُبْغِضُونَكُمْ وَتَلْعَنُونَهُمْ وَيَلْعَنُونَكُمْ. قِيلَ يَا رَسُولَ اللَّهِ أَفَلاَ نُنَابِذُهُمْ بِالسَّيْفِ فَقَالَ لاَ مَا أَقَامُوا فِيكُمُ الصَّلاَةَ وَإِذَا رَأَيْتُمْ مِنْ وُلاَتِكُمْ شَيْئًا تَكْرَهُونَهُ فَاكْرَهُوا عَمَلَهُ وَلاَ تَنْزِعُوا يَدًا مِنْ طَاعَةٍ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1855: 65) عن إسحاق بن إبراهيم الحنظلي أخبرنا عيسى بن يونس، حدثنا الأوزاعي، عن يزيد بن يزيد بن جابر، عن رزيق بن حيان، عن مسلم بن قرظة، عن عوف بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في صفة خيار الأئمة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1855:65).","chapter_en":"What Has Come Concerning the Description of the Best Leaders","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["ʿAwf ibn Malik narrated from the Messenger of Allah ﷺ that he said: “The best of your leaders are those whom you love and who love you, and who pray for you and for whom you pray. The worst of your leaders are those whom you hate and who hate you, and whom you curse and who curse you.” It was said: “O Messenger of Allah, should we not oppose them with the sword?” He said: “No, as long as they establish prayer among you. If you see something from your rulers that you dislike, then hate his action, but do not withdraw your hand from obedience.”"]},"intro":{"ar":["قال الله تعالى: (الَّذِينَ إِن مَّكَّنَّاهُمْ فِي الْأَرْضِ أَقَامُوا الصَّلَاةَ وَآتَوُا الزَّكَاةَ وَأَمَرُوا بِالْمَعْرُوفِ وَنَهَوْا عَنِ الْمُنكَرِ وَلِلَّهِ عَاقِبَةُ الْأُمُورِ) [سورة الحج: ٤١]"],"en":["Allah the Exalted says: “Those who, if We establish them in the land, establish prayer, give charity, command what is right, and forbid what is wrong. And to Allah belongs the outcome of all matters.” [Surah al-Hajj: 41]"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1855,"lafz":true}],"full":1},{"num":7615,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكَرَةَ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ أَكْرَمَ سُلْطَانَ اللهِ فِي الدُّنْيَا، أَكْرَمَهُ اللهُ يَوْمَ الْقِيَامَةِ، وَمَنْ أَهَانَ سُلْطَانَ اللهِ فِي الدُّنْيَا، أَهَانَهُ اللهُ يَوْمَ الْقِيَامَةِ."],"takhrij":"حسن: رواه أحمد ( 20433)، والترمذي (2224) كلاهما من طريق حميد بن مهران، عن سعيد بن أوس، عن زياد بن كسيب العدوي، عن أبي بكرة فذكره.","grade":"حسن","chapter_ar":"باب إكرام السلطان","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (20433) and al-Tirmidhi (2224), who graded it hasan. The wording is from Ahmad. In al-Tirmidhi, the beginning includes a story: Ziyad ibn Kusayb al-ʿAdawi said: I was with Abu Bakrah beneath the pulpit of Ibn ʿAmir while he was delivering a sermon, wearing thin garments. Abu Bilal said: “Look at our commander wearing the clothing of the wicked.” Abu Bakrah said: “Be quiet. I heard the Messenger of Allah ﷺ say: ‘Whoever humiliates Allah’s authority on earth, Allah will humiliate him.’”","chapter_en":"Honoring the Authority","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Abu Bakrah said: I heard the Messenger of Allah ﷺ say: “Whoever honors Allah’s authority in this world, Allah will honor him on the Day of Resurrection; and whoever humiliates Allah’s authority in this world, Allah will humiliate him on the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":2224},{"key":"ahmad","label":"مسند الإمام أحمد","number":20433,"n":20433,"lafz":true}],"full":1,"dr":1},{"num":7616,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عَبَّاسٍ: أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الْأَمْرِ مِنْكُمْ قَالَ: نَزَلَتْ فِي عَبْدِ اللَّهِ بْنِ حُذَافَةَ بْنِ قَيْسِ بْنِ عَدِيٍّ إِذْ بَعَثَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَرِيَّةٍ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4584)، ومسلم في الإمارة (1834) كلاهما من طريق حجاج بن محمد، عن ابن جريج، عن يعلى بن مسلم، عن سعيد بن جبير، عن ابن عباس قال: فذكره. والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4584) and Muslim (1834). The wording is from al-Bukhari.","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas said concerning the verse, “Obey Allah, obey the Messenger, and those in authority among you.” He said: It was revealed concerning ʿAbdullah ibn Hudhafah ibn Qays ibn ʿAdi when the Prophet ﷺ sent him in command of a military detachment."]},"intro":{"ar":["قال تعالى: (يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الْأَمْرِ مِنكُمْ) [النساء: ٥٩]"],"en":["Allah the Exalted says: “O you who believe, obey Allah, obey the Messenger, and those in authority among you.” [Surah an-Nisa’: 59]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4584,"lafz":true},{"key":"muslim","label":"مسلم","number":1834}],"full":1},{"num":7617,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ بْنِ الصَّامِتِ، قَالَ بَايَعْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى السَّمْعِ وَالطَّاعَةِ فِي الْمَنْشَطِ وَالْمَكْرَهِ. وَأَنْ لاَ نُنَازِعَ الأَمْرَ أَهْلَهُ، وَأَنْ نَقُومَ ـ أَوْ نَقُولَ ـ بِالْحَقِّ حَيْثُمَا كُنَّا لاَ نَخَافُ فِي اللَّهِ لَوْمَةَ لاَئِمٍ."],"takhrij":"متفق عليه: رواه مالك في الجهاد (5) عن يحيى بن سعيد قال: أخبرني عبادة بن الوليد بن عبادة بن الصامت، عن أبيه، عن جده فذكره.","grade":"متفق عليه","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (5), al-Bukhari (7199–7200), and Muslim (1709:41).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿUbadah ibn as-Samit said: We pledged allegiance to the Messenger of Allah ﷺ to hear and obey in ease and hardship, in what we liked and disliked, and not to dispute authority with its rightful holders, and to speak — or stand for — the truth wherever we were, not fearing the blame of any blamer for the sake of Allah."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":5,"lafz":true},{"key":"bukhari","label":"البخاري","number":7199},{"key":"muslim","label":"مسلم","number":1709,"n":4768}],"full":1,"dr":1},{"num":7618,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ كُنَّا إِذَا بَايَعْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى السَّمْعِ وَالطَّاعَةِ يَقُولُ لَنَا فِيمَا اسْتَطَعْتَ."],"takhrij":"متفق عليه: رواه مالك في البيعة (1) عن عبد الله بن دينار أن عبد الله بن عمر فذكره. ورواه البخاري في الأحكام (7202) من طريق مالك به مثله. ورواه مسلم في الإمارة (1867) من طريق إسماعيل بن جعفر، أخبرني عبد الله بن دينار به.","grade":"متفق عليه","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (1), al-Bukhari (7202), and Muslim (1867).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: When we pledged allegiance to the Messenger of Allah ﷺ to hear and obey, he would say to us: “As much as you are able.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":1},{"key":"bukhari","label":"البخاري","number":7202,"lafz":true},{"key":"muslim","label":"مسلم","number":1867}],"full":1},{"num":7619,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: السَّمْعُ وَالطَّاعَةُ عَلَى الْمَرْءِ الْمُسْلِمِ فِيمَا أَحَبَّ وَكَرِهَ مَا لَمْ يُؤْمَرْ بِمَعْصِيَةٍ، فَإِذَا أُمِرَ بِمَعْصِيَةٍ فَلاَ سَمْعَ وَلاَ طَاعَةَ."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7144)، ومسلم في الإمارة (1839: 38) كلاهما من طريق عبيد الله، حدثني نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7144) and Muslim (1839:38).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿUmar narrated from the Prophet ﷺ that he said: “Hearing and obeying are binding upon a Muslim in what he likes and dislikes, so long as he is not commanded to commit disobedience. If he is commanded to commit disobedience, then there is no hearing and no obedience.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7144,"lafz":true},{"key":"muslim","label":"مسلم","number":1839}],"full":1},{"num":7620,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ أَطَاعَنِي فَقَدْ أَطَاعَ اللَّهَ وَمَنْ يَعْصِنِي فَقَدْ عَصَى اللَّهَ وَمَنْ يُطِعِ الأَمِيرَ فَقَدْ أَطَاعَنِي وَمَنْ يَعْصِ الأَمِيرَ فَقَدْ عَصَانِي."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2957)، ومسلم في الإمارة (1835: 32) كلاهما من طريق أبي الزناد، عن الأعرج، عن أبي هريرة فذكره. والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2957) and Muslim (1835:32). The wording is from Muslim.","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “Whoever obeys me has obeyed Allah, and whoever disobeys me has disobeyed Allah. Whoever obeys the commander has obeyed me, and whoever disobeys the commander has disobeyed me.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2957,"lafz":true},{"key":"muslim","label":"مسلم","number":1835,"n":4748}],"full":1},{"num":7621,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اسْمَعُوا وَأَطِيعُوا وَإِنِ اسْتُعْمِلَ عَلَيْكُمْ عَبْدٌ حَبَشِيٌّ كَأَنَّ رَأْسَهُ زَبِيبَةٌ."],"takhrij":"صحيح: رواه البخاري في الأحكام (7142) عن مسدد، حدثنا يحيى بن سعيد، عن شعبة، عن أبي التيّاح، عن أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7142).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ said: “Hear and obey, even if an Abyssinian slave whose head is like a raisin is appointed over you.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7142,"lafz":true}],"full":1},{"num":7622,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ قَالَ: بَايَعْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى السَّمْعِ، وَالطَّاعَةِ، فَقَالَ: فِيمَا اسْتَطَعْتُمْ."],"takhrij":"حسن: رواه ابن ماجه (2868)، وأحمد (12203) من طريق وكيع قال: حدثنا شعبة، عن عتّاب مولى ابن هرمز قال: سمعت أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2868) and Ahmad (12203).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Anas ibn Malik said: We pledged allegiance to the Messenger of Allah ﷺ to hear and obey, and he said: “As much as you are able.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2868,"lafz":true},{"key":"ahmad","label":"مسند الإمام أحمد","number":12203,"n":12203}],"full":1,"dr":1},{"num":7623,"demo":false,"sanad":"","matn":["عن أُمِّ الْحُصَيْنِ قَالَ سَمِعْتُهَا تَقُولُ، حَجَجْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَجَّةَ الْوَدَاعِ - قَالَتْ - فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَوْلاً كَثِيرًا ثُمَّ سَمِعْتُهُ يَقُولُ إِنْ أُمِّرَ عَلَيْكُمْ عَبْدٌ مُجَدَّعٌ - حَسِبْتُهَا قَالَتْ - أَسْوَدُ يَقُودُكُمْ بِكِتَابِ اللَّهِ فَاسْمَعُوا لَهُ وَأَطِيعُوا."],"takhrij":"صحيح: رواه مسلم في الإمارة (1838) عن سلمة بن شبيب، حدثنا الحسن بن أعين، حدثنا معقل عن زيد بن أبي أنيسة، عن يحيى بن حصين، عن جدته أم الحصين فذكرته.","grade":"صحيح","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1838).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Umm al-Husayn said: I performed the Farewell Pilgrimage with the Messenger of Allah ﷺ. She said: The Messenger of Allah ﷺ said many things, then I heard him say: “If a mutilated slave is appointed over you — I think she said: a black slave — and he leads you by the Book of Allah, then listen to him and obey.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1838,"lafz":true,"n":4762}],"full":1},{"num":7624,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، قَالَ إِنَّ خَلِيلِي أَوْصَانِي أَنْ أَسْمَعَ وَأُطِيعَ وَإِنْ كَانَ عَبْدًا مُجَدَّعَ الأَطْرَافِ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1837) من طريق ابن إدريس، عن شعبة، عن أبي عمران، عن عبد الله بن الصامت، عن أبي ذر قال: فذكره.","grade":"صحيح","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1837).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Dharr said: My close friend advised me to listen and obey, even if he is a slave with mutilated limbs."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1837,"lafz":true}],"full":1},{"num":7625,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بن سلام، أَنَّ أَبَا سَلاَّمٍ حَدَّثَهُ أَنَّ الْحَارِثَ الأشعري حَدَّثَهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَأَنَا آمُرُكُمْ بِخَمْسٍ اللَّهُ أَمَرَنِي بِهِنَّ: السَّمْعُ، وَالطَّاعَةُ، وَالْجِهَادُ، وَالْهِجْرَةُ، وَالْجَمَاعَةُ، فَإِنَّ مَنْ فَارَقَ الْجَمَاعَةَ قِيدَ شِبْرٍ فَقَدْ خَلَعَ رِبْقَةَ الإِسْلاَمِ مِنْ عُنُقِهِ إِلاَّ أَنْ يَرْجِعَ وَمَنِ ادَّعَى دَعْوَى الْجَاهِلِيَّةِ فَإِنَّهُ مِنْ جُثَا جَهَنَّمَ فَقَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، وَإِنْ صَلَّى وَصَامَ؟ قَالَ: وَإِنْ صَلَّى وَصَامَ فَادْعُوا بِدَعْوَى اللَّهِ الَّذِي سَمَّاكُمُ الْمُسْلِمِينَ الْمُؤْمِنِينَ عِبَادَ اللَّهِ."],"takhrij":"صحيح: رواه الترمذي (2863) عن محمد بن إسماعيل (البخاري)، حدثنا موسى بن إسماعيل، حدثنا أبان بن يزيد، حدثنا يحيى بن أبي كثير، عن زيد بن سلام أن أبا سلام حدثه فذكره بطوله. وهو مذكور في أخبار يحيى بن زكريا.","grade":"صحيح","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (2863), who said: “A hasan, sahih, strange hadith.”","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Zayd ibn Salam narrated that Abu Salam told him, that al-Harith al-Ashʿari told him, that the Prophet ﷺ said: “I command you with five things which Allah commanded me with: hearing, obedience, striving, migration, and the community. Whoever separates from the community by a handspan has removed the bond of Islam from his neck unless he returns. Whoever calls with the call of the pre-Islamic period is among the heaps of Hell.” A man said: “O Messenger of Allah, even if he prays and fasts?” He said: “Even if he prays and fasts. So call with the call of Allah, who named you Muslims, believers, servants of Allah.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":2863,"lafz":true}],"full":1,"dr":1},{"num":7626,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ قَالَ: بَعَثَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَرِيَّةً، وَأَمَّرَ عَلَيْهِمْ رَجُلاً مِنَ الأَنْصَارِ، وَأَمَرَهُمْ أَنْ يُطِيعُوهُ، فَغَضِبَ عَلَيْهِمْ، وَقَالَ: أَلَيْسَ قَدْ أَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ تُطِيعُونِي؟ قَالُوا: بَلَى قَالَ: قَدْ عَزَمْتُ عَلَيْكُمْ لَمَا جَمَعْتُمْ حَطَبًا، وَأَوْقَدْتُمْ نَارًا، ثُمَّ دَخَلْتُمْ فِيهَا فَجَمَعُوا حَطَبًا، فَأَوْقَدُوا نَارًا، فَلَمَّا هَمُّوا بِالدُّخُولِ، فَقَامَ يَنْظُرُ بَعْضُهُمْ إِلَى بَعْضٍ، قَالَ بَعْضُهُمْ: إِنَّمَا تَبِعْنَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِرَارًا مِنَ النَّارِ أَفَنَدْخُلُهَا؟ فَبَيْنَمَا هُمْ كَذَلِكَ إِذْ خَمَدَتِ النَّارُ وَسَكَنَ غَضَبُهُ فَذُكِرَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: لَوْ دَخَلُوهَا مَا خَرَجُوا مِنْهَا أَبَدًا، إِنَّمَا الطَّاعَةُ فِي الْمَعْرُوفِ. وَفِي رِوَايَةِ: لا طاعة فِي معصية اللَّهِ، إِنَّمَا الطَّاعَةُ فِي الْمَعْرُوفِ."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7145)، ومسلم في الإمارة (1840: 40) من طريق الأعمش، حدثنا سعد بن عبيدة عن أبي عبدالرحمن عن علي فذكره.","grade":"متفق عليه","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7145) and Muslim (1840:40). The other wording is from Muslim.","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿAli said: The Prophet ﷺ sent a military detachment and appointed a man from the Ansar over them, and he commanded them to obey him. The commander became angry with them and said: “Did the Prophet ﷺ not command you to obey me?” They said: “Yes.” He said: “I firmly command you to gather firewood, light a fire, and then enter it.” So they gathered firewood and lit a fire. When they were about to enter it, they began looking at one another. Some of them said: “We only followed the Prophet ﷺ to flee from the Fire; shall we enter it?” While they were in that state, the fire died down and his anger subsided. This was mentioned to the Prophet ﷺ, and he said: “If they had entered it, they would never have come out of it. Obedience is only in what is right.” In another narration: “There is no obedience in disobedience to Allah; obedience is only in what is right.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7145,"lafz":true},{"key":"muslim","label":"مسلم","number":1840}],"full":1,"dr":1},{"num":7627,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ أنه قَالَ لِلْحَكَمِ بن عَمْرٍو الْغِفَارِيَّ: أَسَمِعْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا طَاعَةَ لِأَحَدٍ فِي مَعْصِيَةِ اللَّهِ تَبَارَكَ وَتَعَالَى قَالَ: نَعَمْ فَقَالَ عِمْرَانُ: لِلَّهِ الْحَمْدُ أَوِ اللهُ أَكْبَرُ."],"takhrij":"صحيح: رواه أحمد (20654) عن بهز، حدثنا سليمان بن المغيرة، حدثنا حميد -يعني ابن هلال- عن عبد الله بن الصامت قال: أراد زياد أن يبعث عمران بن حصين على خراسان فأبى عليهم فقال له أصحابه: أتركت خراسان أن تكون عليها قال: فقال: إني والله ما يسرني أن أُصلى بحرِّها وتصلون ببردها، إني أخاف إذا كنت في نحور العدو أن يأتيني كتاب من زياد، فإن أنا مضيتُ هلكتُ، وإن رجعت ضربت عنقي. قال: فأراد الحكم بن عمرو الغفاري عليها، قال: فانقاد لأمره قال: فقال عمران: ألا أحد يدعو لي الحكم؟ قال فانطلق الرسول، قال: فأقبل الحكم إليه، قال: فدخل عليه قال: فقال عمران للحكم: فذكره.","grade":"صحيح","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (20654) and al-Harith ibn Abi Usamah, as in al-Bughyah (603).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿImran ibn Husayn said to al-Hakam ibn ʿAmr al-Ghifari: “Did you hear the Messenger of Allah ﷺ say: ‘There is no obedience to anyone in disobedience to Allah, Blessed and Exalted’?” He said: “Yes.” So ʿImran said: “Praise belongs to Allah,” or “Allah is the Greatest.”"]}},"tuhfa":{},"refs":[{"key":"sh13160","label":"الحارث بن أبي أسامة كما في البغية","number":603},{"key":"ahmad","label":"مسند الإمام أحمد","number":20654,"n":20654,"lafz":true}],"full":1,"dr":1},{"num":7628,"demo":false,"sanad":"","matn":["عَنْ جَرِيرِ بْنِ عَبْدِ اللَّهِ، قَالَ بَايَعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى السَّمْعِ وَالطَّاعَةِ، فَلَقَّنَنِي، فِيمَا اسْتَطَعْتُ، وَالنُّصْحِ لِكُلِّ مُسْلِمٍ.","وفي لفظ: بايعت رسول الله صلي الله عليه وسلم على إقام الصلاة، وإيتاء الزكاة، والنصح لكل مسلم، وعلى فراق المشرك."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7204)، ومسلم في الإيمان (56: 99) عن يعقوب بن إبراهيم الدورقي –وزاد مسلم غيره- عن هشيم، أخبرنا سيّار، عن الشعبي، عن جرير بن عبد الله فذكره.","grade":"متفق عليه","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7204) and Muslim (56:99). The second wording was narrated by al-Nasa’i (4175) and Ahmad (19162).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Jarir said: I pledged allegiance to the Prophet ﷺ to hear and obey, and he prompted me to say: “As much as I am able, and sincere counsel for every Muslim.” In another wording: I pledged allegiance to the Messenger of Allah ﷺ to establish prayer, give charity, offer sincere counsel to every Muslim, and separate from the polytheist."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7204,"lafz":true},{"key":"muslim","label":"مسلم","number":56},{"key":"nasai","label":". واللفظ الثاني رواه النسائي","number":4175,"n":4189},{"key":"ahmad","label":"مسند الإمام أحمد","number":19162,"n":19162}],"full":1,"dr":1},{"num":7629,"demo":false,"sanad":"","matn":["عن أَبِي أُمَامَةَ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ فِي حَجَّةِ الْوَدَاعِ فَقَالَ اتَّقُوا اللَّهَ رَبَّكُمْ وَصَلُّوا خَمْسَكُمْ وَصُومُوا شَهْرَكُمْ وَأَدُّوا زَكَاةَ أَمْوَالِكُمْ وَأَطِيعُوا ذَا أَمْرِكُمْ تَدْخُلُوا جَنَّةَ رَبِّكُمْ."],"takhrij":"صحيح: رواه الترمذي ( 616) عن موسى بن عبد الرحمن الكندي الكوفي، حدثنا زيد بن الحباب، أخبرنا معاوية بن صالح، حدثني سليم بن عامر، قال: سمعت أبا أمامة يقول: فذكره. قال: فقلت لأبي أمامة: منذ كم سمعت من رسول الله صلى الله عليه وسلم هذا الحديث؟ قال: سمعته وأنا ابن ثلاثين سنة.","grade":"صحيح","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (616), who said: “This is a hasan, sahih hadith.” It was also narrated by Imam Ahmad (22161).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Umamah said: I heard the Messenger of Allah ﷺ delivering a sermon during the Farewell Pilgrimage, and he said: “Be mindful of Allah, your Lord; pray your five prayers, fast your month, give the charity due on your wealth, and obey the one in authority over you; you will enter the Paradise of your Lord.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":616,"lafz":true},{"key":"ahmad","label":"أيضاً الإمام أحمد","number":22161}],"full":1,"dr":1},{"num":7630,"demo":false,"sanad":"","matn":["عن مُعَاوِيَةَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ السَّامِعَ الْمُطِيعَ لَا حُجَّةَ عَلَيْهِ وَإِنَّ السَّامِعَ الْعَاصِي لَا حُجَّةَ لَهُ."],"takhrij":"صحيح: رواه ابن أبي عاصم في السنة (1090)، والطبراني في الكبير (19/366) كلاهما من حديث محمد بن عبد الرحيم صاعقة، حدثنا روح بن عبادة، حدثنا حماد بن سلمة، عن جبلة بن عطية، عن ابن محيريز، عن معاوية فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Abi ʿAsim in as-Sunnah (1090) and al-Tabarani in al-Kabir (19/366).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Muʿawiyah narrated from the Prophet ﷺ that he said: “The one who hears and obeys has no case against him, and the one who hears and disobeys has no case in his favor.”"]}},"tuhfa":{},"refs":[{"key":"sh5930","label":"ابن أبي عاصم في السنة","number":1090,"lafz":true,"n":1008},{"key":"mujamkabir","label":"الطبراني في الكبير","number":19}],"full":1},{"num":7631,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ عَلْقَمَةَ بْنَ مُجَزِّزٍ عَلَى بَعْثٍ وَأَنَا فِيهِمْ فَلَمَّا انْتَهَى إِلَى رَأْسِ غَزَاتِهِ أَوْ كَانَ بِبَعْضِ الطَّرِيقِ اسْتَأْذَنَتْهُ طَائِفَةٌ مِنَ الْجَيْشِ فَأَذِنَ لَهُمْ وَأَمَّرَ عَلَيْهِمْ عَبْدَ اللَّهِ بْنَ حُذَافَةَ بْنِ قَيْسٍ السَّهْمِيَّ فَكُنْتُ فِيمَنْ غَزَا مَعَهُ فَلَمَّا كَانَ بِبَعْضِ الطَّرِيقِ أَوْقَدَ الْقَوْمُ نَارًا لِيَصْطَلُوا أَوْ لِيَصْنَعُوا عَلَيْهَا صَنِيعًا فَقَالَ عَبْدُ اللَّهِ - وَكَانَتْ فِيهِ دُعَابَةٌ - أَلَيْسَ لِي عَلَيْكُمُ السَّمْعُ وَالطَّاعَةُ قَالُوا بَلَى. قَالَ فَمَا أَنَا بِآمِرِكُمْ بِشَىْءٍ إِلاَّ صَنَعْتُمُوهُ قَالُوا نَعَمْ. قَالَ فَإِنِّي أَعْزِمُ عَلَيْكُمْ إِلاَّ تَوَاثَبْتُمْ فِي هَذِهِ النَّارِ. فَقَامَ نَاسٌ فَتَحَجَّزُوا فَلَمَّا ظَنَّ أَنَّهُمْ وَاثِبُونَ قَالَ أَمْسِكُوا عَلَى أَنْفُسِكُمْ فَإِنَّمَا كُنْتُ أَمْزَحُ مَعَكُمْ. فَلَمَّا قَدِمْنَا ذَكَرُوا ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ أَمَرَكُمْ مِنْهُمْ بِمَعْصِيَةِ اللَّهِ فَلاَ تُطِيعُوهُ."],"takhrij":"حسن: رواه ابن ماجه (2863)، وأحمد (11639)، وابن حبان (4558) كلهم من طريق محمد بن عمرو، عن عمر بن الحكم بن ثوبان، عن أبي سعيد الخدري فذكره.","grade":"حسن","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2863), Ahmad (11639), and authenticated by Ibn Hibban (4558).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that the Messenger of Allah ﷺ sent ʿAlqamah ibn Mujazziz in command of a detachment, and I was among them. When he reached the area of his campaign, or while he was on part of the road, a group from the army sought his permission, and he granted them permission and appointed ʿAbdullah ibn Hudhafah ibn Qays as-Sahmi over them. I was among those who went with him. While they were on part of the road, the people lit a fire to warm themselves or to cook something over it. ʿAbdullah — who had some humor in him — said: “Do I not have the right of hearing and obedience over you?” They said: “Yes.” He said: “Whatever I command you to do, will you do it?” They said: “Yes.” He said: “I firmly command you to jump into this fire.” Some people stood and prepared themselves. When he thought they were about to jump, he said: “Hold back from yourselves; I was only joking with you.” When we returned, they mentioned that to the Prophet ﷺ, and the Messenger of Allah ﷺ said: “If one of them commands you to disobey Allah, then do not obey him.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2863,"lafz":true},{"key":"ibnhibban","label":"صححه ابن حبان","number":4558},{"key":"ahmad","label":"مسند الإمام أحمد","number":11639,"n":11639}],"full":1,"dr":1},{"num":7632,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول الله صلي الله عليه وسلم: طاعة الإمام حق على المرء المسلم ما لم يأمر بمعصية الله، فإذا أمر بمعصية الله فلا طاعة له."],"takhrij":"حسن: رواه تمام في فوائده (914- الروض) عن الحسن بن حبيب، حدثنا بدر بن الهيثم، حدثنا سليمان بن عبد الرحمن، حدثنا عبد الرحمن بن المغراء، عن عبيد الله بن عمر، عن سعيد بن أبي سعيد المقبري، عن أبيه، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Tammam in his Fawa’id (ar-Rawd, 914).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Obedience to the leader is a duty upon the Muslim so long as he does not command disobedience to Allah. If he commands disobedience to Allah, then there is no obedience to him.”"]}},"tuhfa":{},"refs":[{"key":"rb608","label":"تمام في فوائده","number":914,"lafz":true}],"full":1,"dr":1},{"num":7633,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن مَسْعُودٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ سَيَلِي أُمُورَكُمْ بَعْدِي رِجَالٌ يُطْفِئُونَ السُّنَّةَ وَيَعْمَلُونَ بِالْبِدْعَةِ وَيُؤَخِّرُونَ الصَّلاَةَ عَنْ مَوَاقِيتِهَا فَقُلْتُ يَا رَسُولَ اللَّهِ إِنْ أَدْرَكْتُهُمْ كَيْفَ أَفْعَلُ قَالَ تَسْأَلُنِي يَا ابْنَ أُمِّ عَبْدٍ كَيْفَ تَفْعَلُ لاَ طَاعَةَ لِمَنْ عَصَى اللَّهَ."],"takhrij":"حسن: رواه ابن ماجه (2865)، وأحمد (3790)، والبيهقي (3/124) من طرق عن عبد الله بن عثمان بن خثيم، عن القاسم بن عبد الرحمن بن عبد الله بن مسعود، عن أبيه، عن جده عبد الله بن مسعود فذكره.","grade":"حسن","chapter_ar":"باب وجوب طاعة ولاة الأمر في غير معصية الله","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2865), Ahmad (3790), and al-Bayhaqi (3/124).","chapter_en":"The Obligation of Obeying Those in Authority in Matters Other Than Disobedience to Allah","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿAbdullah ibn Masʿud narrated that the Prophet ﷺ said: “After me, men will take charge of your affairs who extinguish the practice, act according to innovation, and delay the prayer beyond its proper times.” I said: “O Messenger of Allah, if I reach them, what should I do?” He said: “You ask me, son of Umm ʿAbd, what you should do? There is no obedience to one who disobeys Allah.”"]},"buhuth":{"en":["His statement “There is no obedience to one who disobeys Allah” means in whatever contradicts the command of Allah. That is, he should perform the prayer in its time at home, then pray with them so that he is not disobedient to them either, because the time of prayer is broad.","Among the beliefs of the people of the Prophetic way is that if the people gather upon the one who has gained authority by dominance, obedience to him becomes obligatory, as Ibn ʿUmar did. He refused to pledge allegiance either to Ibn az-Zubayr or to ʿAbd al-Malik, but when ʿAbd al-Malik prevailed and authority became established for him, he pledged allegiance to him.","Harmalah said: I heard ash-Shafiʿi say: Everyone who gains the caliphate by the sword until he is called caliph and the people gather upon him, then he is a caliph. Narrated by al-Bayhaqi in Manaqib ash-Shafiʿi (1/448).","Imam Ahmad said: “The foundations of the Prophetic way according to us…” then he mentioned matters and said: “Hearing and obedience to the leaders and the commander of the believers, whether righteous or sinful, and to whoever takes charge of the caliphate and the people gather upon him and accept him, and to whoever overcomes them by the sword until he becomes caliph and is called the commander of the believers.”","He also said: “Whoever rebels against the leader of the Muslims after the people have gathered upon him and affirmed the caliphate for him by any means, whether through acceptance or dominance, then this rebel has split the unity of the Muslims and opposed the transmitted reports from the Messenger of Allah ﷺ. If the rebel dies upon that, he dies a death of the pre-Islamic period. It is not lawful for anyone among the people to fight the ruler or rebel against him. Whoever does that is an innovator, not upon the Prophetic way or the path.” See Sharh al-Iʿtiqad by al-Lalaka’i (1/160–161).","Al-Hafiz Ibn Hajar said: The jurists have unanimously agreed on the obligation of obeying the ruler who gained authority by dominance, and of striving alongside him, and that obedience to him is better than rebelling against him because that preserves blood and calms the masses. Fath al-Bari (13/7).","Shaykh al-Islam Muhammad ibn ʿAbd al-Wahhab, may Allah have mercy on him, said: The imams of every school are agreed that whoever gains dominance over a land or lands has the ruling of the leader in all matters. Ad-Durar as-Saniyyah fi al-Ajwibah an-Najdiyyah (7/239).","Imam al-Barbahari, who died in 328 after the Hijrah, said: “If you see a man supplicating against the ruler, know that he is a person of desires. If you hear a man supplicating for the ruler’s righteousness, know that he is a person of the Prophetic way, if Allah wills. Fudayl ibn ʿIyad said: If I had one supplication, I would only make it for the ruler. We were commanded to supplicate for their righteousness, and we were not commanded to supplicate against them, even if they are unjust and oppressive; for their injustice and oppression harm themselves and the Muslims, while their righteousness benefits themselves and the Muslims.” See Tabaqat al-Hanabilah by Ibn Abi Yaʿla (2/36).","In these reports — and they are very many — is the point that among the beliefs of the people of the Prophetic way and the community is that rebelling against the leaders, even if they are unjust, is forbidden, unless clear disbelief is seen from them."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2865,"lafz":true},{"key":"kubrabayhaqi","label":"البيهقي","number":3},{"key":"ahmad","label":"مسند الإمام أحمد","number":3790,"n":3790}],"full":1,"dr":1},{"num":7634,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن مَسْعُودٍ قَالَ قَالَ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّكُمْ سَتَرَوْنَ بَعْدِي أَثَرَةً وَأُمُورًا تُنْكِرُونَهَا. قَالُوا فَمَا تَأْمُرُنَا يَا رَسُولَ اللَّهِ قَالَ أَدُّوا إِلَيْهِمْ حَقَّهُمْ وَسَلُوا اللَّهَ حَقَّكُمْ."],"takhrij":"متفق عليه: رواه البخاري في القتن (7052)، ومسلم في الإمارة (1843: 45) كلاهما من طريق الأعمش، حدثنا زيد بن وهب سمعت عبد الله قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب جور الإمام واستئثاره لا يمنع من السمع والطاعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7052) and Muslim (1843:45).","chapter_en":"The Leader’s Injustice and Self-Preference Do Not Prevent Hearing and Obedience","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["ʿAbdullah ibn Masʿud said: The Messenger of Allah ﷺ said to us: “After me, you will see favoritism and matters that you disapprove of.” They said: “What do you command us, O Messenger of Allah?” He said: “Give them their right, and ask Allah for your right.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7052,"lafz":true},{"key":"muslim","label":"مسلم","number":1843}],"full":1},{"num":7635,"demo":false,"sanad":"","matn":["عَنْ جُنَادَةَ بْنِ أَبِي أُمَيَّةَ، قَالَ دَخَلْنَا عَلَى عُبَادَةَ بْنِ الصَّامِتِ وَهْوَ مَرِيضٌ قُلْنَا أَصْلَحَكَ اللَّهُ حَدِّثْ بِحَدِيثٍ، يَنْفَعُكَ اللَّهُ بِهِ سَمِعْتَهُ مِنَ النَّبِيِّ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ دَعَانَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَايَعْنَاهُ فَقَالَ فِيمَا أَخَذَ عَلَيْنَا أَنْ بَايَعَنَا عَلَى السَّمْعِ وَالطَّاعَةِ، فِي مَنْشَطِنَا وَمَكْرَهِنَا، وَعُسْرِنَا، وَيُسْرِنَا، وَأَثَرَةٍ عَلَيْنَا، وَأَنْ لاَ نُنَازِعَ الأَمْرَ أَهْلَهُ، إِلاَّ أَنْ تَرَوْا كُفْرًا بَوَاحًا، عِنْدَكُمْ مِنَ اللَّهِ فِيهِ بُرْهَانٌ."],"takhrij":"متفق عليه: رواه البخاري في الفتن (7055)، ومسلم في الإمارة (1709: 42) كلاهما من طريق عبد الله بن وهب، حدثنا عمرو بن الحارث، حدثني بكير، عن بسر بن سعيد، عن جنادة بن أبي أمية قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب جور الإمام واستئثاره لا يمنع من السمع والطاعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7055) and Muslim (1709:42).","chapter_en":"The Leader’s Injustice and Self-Preference Do Not Prevent Hearing and Obedience","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Junadah ibn Abi Umayyah said: We entered upon ʿUbadah ibn as-Samit while he was ill, and we said: “May Allah set your affair right. Narrate to us a hadith you heard from the Prophet ﷺ, by which Allah may benefit you.” He said: The Prophet ﷺ called us and we pledged allegiance to him. Among what he took from us was that we pledged allegiance to hear and obey in what we liked and disliked, in hardship and ease, and even when others were favored over us, and that we would not dispute authority with its rightful holders, “unless you see clear disbelief for which you have proof from Allah.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7055,"lafz":true},{"key":"muslim","label":"مسلم","number":1709,"n":4771}],"full":1,"dr":1},{"num":7636,"demo":false,"sanad":"","matn":["رَضِيَ اللَّهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ رَأَى مِنْ أَمِيرِهِ شَيْئًا يَكْرَهُهُ فَلْيَصْبِرْ عَلَيْهِ، فَإِنَّهُ مَنْ فَارَقَ الْجَمَاعَةَ شِبْرًا فَمَاتَ، إِلاَّ مَاتَ مِيتَةً جَاهِلِيَّةً."],"takhrij":"متفق عليه: رواه البخاري في الفتن (7054)، ومسلم في الإمارة (1849: 55) كلاهما من طريق حماد بن زيد، عن الجعد أبي عثمان، حدثني أبو رجاء العطاردي قال: سمعت ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب جور الإمام واستئثاره لا يمنع من السمع والطاعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7054) and Muslim (1849:55).","chapter_en":"The Leader’s Injustice and Self-Preference Do Not Prevent Hearing and Obedience","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas narrated from the Prophet ﷺ that he said: “Whoever sees something from his commander that he dislikes, let him be patient with it; for whoever separates from the community by a handspan and then dies, he only dies a death of the pre-Islamic period.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7054,"lafz":true},{"key":"muslim","label":"مسلم","number":1849}],"full":1},{"num":7637,"demo":false,"sanad":"","matn":["عَنْ أُسَيْدِ بْنِ حُضَيْرٍ، أَنَّ رَجُلاً، أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ يَا رَسُولَ اللَّهِ اسْتَعْمَلْتَ فُلاَنًا وَلَمْ تَسْتَعْمِلْنِي. قَالَ إِنَّكُمْ سَتَرَوْنَ بَعْدِي أَثَرَةً، فَاصْبِرُوا حَتَّى تَلْقَوْنِي."],"takhrij":"متفق عليه: رواه البخاري في الفتن (7057)، ومسلم في الإمارة (1845: 48) كلاهما من طريق شعبة، عن قتادة، عن أنس بن مالك، عن أسيد بن حضير فذكره.","grade":"متفق عليه","chapter_ar":"باب جور الإمام واستئثاره لا يمنع من السمع والطاعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7057) and Muslim (1845:48).","chapter_en":"The Leader’s Injustice and Self-Preference Do Not Prevent Hearing and Obedience","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Usayd ibn Hudayr narrated that a man came to the Prophet ﷺ and said: “O Messenger of Allah, you appointed so-and-so but did not appoint me.” He said: “After me, you will see favoritism, so be patient until you meet me.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7057,"lafz":true},{"key":"muslim","label":"مسلم","number":1845}],"full":1},{"num":7638,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَيْكَ السَّمْعَ وَالطَّاعَةَ فِي عُسْرِكَ وَيُسْرِكَ وَمَنْشَطِكَ وَمَكْرَهِكَ وَأَثَرَةٍ عَلَيْكَ."],"takhrij":"صحيح: رواه مسلم في الإمارة 1836) من طريق يعقوب بن عبد الرحمن، عن أبي حازم، عن أبي صالح السمان، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب جور الإمام واستئثاره لا يمنع من السمع والطاعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1836).","chapter_en":"The Leader’s Injustice and Self-Preference Do Not Prevent Hearing and Obedience","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “You must hear and obey in hardship and ease, in what you like and dislike, and even when others are favored over you.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1836,"lafz":true}],"full":1},{"num":7639,"demo":false,"sanad":"","matn":["عَنْ وَائِلِ بْنِ حُجْرٍ قَالَ: سَأَلَ سَلَمَةُ بْنُ يَزِيدَ الْجُعْفِيُّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا نَبِيَّ اللَّهِ، أَرَأَيْتَ إِنْ قَامَتْ عَلَيْنَا أُمَرَاءُ يَسْأَلُونَا حَقَّهُمْ وَيَمْنَعُونَا حَقَّنَا فَمَا تَأْمُرُنَا؟ فَأَعْرَضَ عَنْهُ، ثُمَّ سَأَلَهُ، فَأَعْرَضَ عَنْهُ، ثُمَّ سَأَلَهُ فِي الثَّانِيَةِ أَوْ فِي الثَّالِثَةِ فَجَذَبَهُ الأَشْعَثُ بْنُ قَيْسٍ وَقَالَ: اسْمَعُوا وَأَطِيعُوا فَإِنَّمَا عَلَيْهِمْ مَا حُمِّلُوا وَعَلَيْكُمْ مَا حُمِّلْتُمْ. وَفِي روية: فَجَذَبَهُ الأَشْعَثُ بن قَيْسٍ فَقَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : اسْمَعُوا وَأَطِيعُوا الحديث."],"takhrij":"صحيح: رواه مسلم في الإمارة (1846: 49) من طريق محمد بن جعفر، حدثنا شعبة، عن سماك بن حرب، عن علقمة بن وائل الحضرمي، عن أبيه قال: فذكره. والرواية الأخرى من طريق شبابة، حدثنا شعبة به.","grade":"صحيح","chapter_ar":"باب جور الإمام واستئثاره لا يمنع من السمع والطاعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1846:49).","chapter_en":"The Leader’s Injustice and Self-Preference Do Not Prevent Hearing and Obedience","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Wa’il ibn Hujr said: Salamah ibn Yazid al-Juʿfi asked the Messenger of Allah ﷺ: “O Prophet of Allah, what do you think if rulers stand over us, demanding their rights from us while withholding our rights from us? What do you command us?” He turned away from him. Then he asked again, and he turned away from him. Then he asked him the second or third time, so al-Ashʿath ibn Qays pulled him. He said: “Hear and obey, for upon them is what they are burdened with, and upon you is what you are burdened with.” In another narration: Al-Ashʿath ibn Qays pulled him, and the Messenger of Allah ﷺ said: “Hear and obey…”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1846,"lafz":true}],"full":1},{"num":7640,"demo":false,"sanad":"","matn":["عن عَوْفِ بْنِ مَالِكٍ الأشجعي يَقُولُ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ خِيَارُ أَئِمَّتِكُمُ الَّذِينَ تُحِبُّونَهُمْ وَيُحِبُّونَكُمْ وَتُصَلُّونَ عَلَيْهِمْ وَيُصَلُّونَ عَلَيْكُمْ وَشِرَارُ أَئِمَّتِكُمُ الَّذِينَ تُبْغِضُونَهُمْ وَيُبْغِضُونَكُمْ وَتَلْعَنُونَهُمْ وَيَلْعَنُونَكُمْ. قَالُوا قُلْنَا يَا رَسُولَ اللَّهِ أَفَلاَ نُنَابِذُهُمْ عِنْدَ ذَلِكَ قَالَ لاَ مَا أَقَامُوا فِيكُمُ الصَّلاَةَ لاَ مَا أَقَامُوا فِيكُمُ الصَّلاَةَ أَلاَ مَنْ وَلِيَ عَلَيْهِ وَالٍ فَرَآهُ يَأْتِي شَيْئًا مِنْ مَعْصِيَةِ اللَّهِ فَلْيَكْرَهْ مَا يَأْتِي مِنْ مَعْصِيَةِ اللَّهِ وَلاَ يَنْزِعَنَّ يَدًا مِنْ طَاعَةٍ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1855: 66) عن داود بن رشيد حدثنا الوليد يعني بن مسلم، حدثنا عبد الرحمن بن يزيد بن جابر، أخبرني مولى بني فزارة وهو رزيق بن حيان أنه سمع مسلم بن قرظة ابن عم عوف بن مالك الأشجعي يقول سمعت عوف بن مالك الأشجعي يقول: فذكره.","grade":"صحيح","chapter_ar":"باب جور الإمام واستئثاره لا يمنع من السمع والطاعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1855:66).","chapter_en":"The Leader’s Injustice and Self-Preference Do Not Prevent Hearing and Obedience","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["ʿAwf ibn Malik al-Ashjaʿi said: I heard the Messenger of Allah ﷺ say: “The best of your leaders are those whom you love and who love you, and for whom you pray and who pray for you. The worst of your leaders are those whom you hate and who hate you, and whom you curse and who curse you.” They said: We said: “O Messenger of Allah, should we not oppose them then?” He said: “No, as long as they establish prayer among you. No, as long as they establish prayer among you. Indeed, whoever has a ruler appointed over him and sees him doing something of disobedience to Allah, let him hate the disobedience to Allah that he does, but let him not withdraw his hand from obedience.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1855,"lafz":true,"n":4805}],"full":1},{"num":7641,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ سَتَكُونُ أُمَرَاءُ فَتَعْرِفُونَ وَتُنْكِرُونَ فَمَنْ عَرَفَ بَرِئَ وَمَنْ أَنْكَرَ سَلِمَ وَلَكِنْ مَنْ رَضِيَ وَتَابَعَ. قَالُوا أَفَلاَ نُقَاتِلُهُمْ قَالَ لاَ مَا صَلَّوْا.","وفي رواية: فمن كره فقد برئ، ومن أنكر فقد سلم. أي من كره بقلبه وأنكر بقلبه."],"takhrij":"صحيح: رواه مسلم في الإمارة (1854: 62) عن هدّاب بن خالد الأزدي، حدثنا همام بن يحيى، حدثنا قتادة، عن الحسن، عن ضبة بن محصن، عن أم سلمة فذكرته.","grade":"صحيح","chapter_ar":"باب جور الإمام واستئثاره لا يمنع من السمع والطاعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1854:62).","chapter_en":"The Leader’s Injustice and Self-Preference Do Not Prevent Hearing and Obedience","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Umm Salamah narrated that the Messenger of Allah ﷺ said: “There will be rulers, and you will recognize some things and reject some things. Whoever recognizes will be free of blame, and whoever rejects will be safe, but the one who is pleased and follows…” They said: “Should we not fight them?” He said: “No, as long as they pray.” In another narration: “Whoever hates it has become free of blame, and whoever rejects it has become safe.” That is, whoever hates it in his heart and rejects it in his heart."]},"buhuth":{"en":["His phrase “the one who is pleased and follows” means that sin and punishment are upon the one who is pleased and follows. This contains evidence that whoever is unable to remove wrongdoing does not sin merely by remaining silent; rather, he sins by being pleased with it, or by not hating it in his heart, or by following it. This was stated by an-Nawawi."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1854,"lafz":true}],"full":1,"dr":1},{"num":7642,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: سَيَكُونُ مِنْ بَعْدِي خُلَفَاءُ، يَعْمَلُونَ بِمَا يَعْلَمُونَ، وَيَفْعَلُونَ مَا يُؤْمَرُونَ، وَسَيَكُونُ مِنْ بَعْدِهِمْ خُلَفَاءُ، يَعْمَلُونَ بِمَا لَا يَعْلَمُونَ، وَيَفْعَلُونَ مَا لَا يُؤْمَرُونَ، فَمَنْ أَنْكَرَ بَرِئَ، وَمَنْ أَمْسَكَ سَلِمَ، وَلَكِنْ مَنْ رَضِيَ وَتَابَعَ."],"takhrij":"حسن: رواه ابن حبان (6659)، والبخاري في التاريخ الكبير (1/329) كلاهما من طرق عن الأوزاعي، عن إبراهيم بن مرة، عن الزهري، عن أبي سلمة، عن أبي هريرة قال:فذكره.","grade":"حسن","chapter_ar":"باب جور الإمام واستئثاره لا يمنع من السمع والطاعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Hibban (6659) and al-Bukhari in al-Tarikh al-Kabir (1/329).","chapter_en":"The Leader’s Injustice and Self-Preference Do Not Prevent Hearing and Obedience","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “After me there will be successors who act according to what they know and do what they are commanded. After them there will be successors who act according to what they do not know and do what they were not commanded. Whoever rejects will be free of blame, and whoever restrains himself will be safe, but the one who is pleased and follows…”"]}},"tuhfa":{},"refs":[{"key":"tarikhbukhari","label":"البخاري في التاريخ الكبير","number":1},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4792,"n":4788},{"key":"ibnhibban","label":"ابن حبان","number":6659,"lafz":true}],"full":1,"dr":1},{"num":7643,"demo":false,"sanad":"","matn":["عن سَلَمَةَ بن الأَكْوَعِ – فِي حَدِيثِ طَوِيلٍ- قَالَ: ثُمَّ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَعَانَا لِلْبَيْعَةِ فِي أَصْلِ الشَّجَرَةِ. قَالَ فَبَايَعْتُهُ أَوَّلَ النَّاسِ ثُمَّ بَايَعَ وَبَايَعَ حَتَّى إِذَا كَانَ فِي وَسَطٍ مِنَ النَّاسِ قَالَ بَايِعْ يَا سَلَمَةُ. قَالَ قُلْتُ قَدْ بَايَعْتُكَ يَا رَسُولَ اللَّهِ فِي أَوَّلِ النَّاسِ قَالَ وَأَيْضًا. قَالَ وَرَآنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَزِلاً - يَعْنِي لَيْسَ مَعَهُ سِلاَحٌ - قَالَ فَأَعْطَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَجَفَةً أَوْ دَرَقَةً ثُمَّ بَايَعَ حَتَّى إِذَا كَانَ فِي آخِرِ النَّاسِ قَالَ أَلاَ تُبَايِعُنِي يَا سَلَمَةُ. قَالَ قُلْتُ قَدْ بَايَعْتُكَ يَا رَسُولَ اللَّهِ فِي أَوَّلِ النَّاسِ وَفِي أَوْسَطِ النَّاسِ قَالَ وَأَيْضًا. قَالَ فَبَايَعْتُهُ الثَّالِثَةَ."],"takhrij":"متفق عليه: رواه مسلم في الجهاد والسير (1806: 131) عن قتيبة بن سعيد حدثنا حاتم يعني بن إسماعيل، عن يزيد بن أبي عبيد قال: سمعت سلمة بن الأكوع يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب مبايعة الإمام أكثر من مرة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1806:131) and al-Bukhari (7208). Al-Bukhari’s wording is: He said: We pledged allegiance to the Prophet ﷺ under the tree, and he said to me: “Salamah, will you not pledge allegiance?” I said: “O Messenger of Allah, I already pledged allegiance the first time.” He said: “And the second.”","chapter_en":"Pledging Allegiance to the Leader More Than Once","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Salamah ibn al-Akwaʿ, in a long hadith, said: Then the Messenger of Allah ﷺ called us to pledge allegiance at the base of the tree. He said: I was the first of the people to pledge allegiance to him. Then he continued accepting pledges, until when he was in the middle of the people, he said: “Pledge allegiance, Salamah.” I said: “I already pledged allegiance to you, O Messenger of Allah, among the first of the people.” He said: “Again.” He said: The Messenger of Allah ﷺ saw that I was unarmed — meaning I had no weapon — so the Messenger of Allah ﷺ gave me a small shield or a leather shield. Then he continued accepting pledges, until when he was among the last of the people, he said: “Will you not pledge allegiance to me, Salamah?” I said: “I already pledged allegiance to you, O Messenger of Allah, among the first people and among the middle of the people.” He said: “Again.” So I pledged allegiance to him a third time."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1806,"lafz":true,"n":4678},{"key":"bukhari","label":"البخاري","number":7208}],"full":1,"dr":1},{"num":7644,"demo":false,"sanad":"","matn":["عن عَوْفِ بْنِ مَالِكٍ الأشجعي قَالَ كُنَّا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تِسْعَةً أَوْ ثَمَانِيَةً أَوْ سَبْعَةً فَقَالَ أَلاَ تُبَايِعُونَ رَسُولَ اللَّهِ وَكُنَّا حَدِيثَ عَهْدٍ بِبَيْعَةٍ فَقُلْنَا قَدْ بَايَعْنَاكَ يَا رَسُولَ اللَّهِ. ثُمَّ قَالَ أَلاَ تُبَايِعُونَ رَسُولَ اللَّهِ. فَقُلْنَا قَدْ بَايَعْنَاكَ يَا رَسُولَ اللَّهِ. ثُمَّ قَالَ أَلاَ تُبَايِعُونَ رَسُولَ اللَّهِ. قَالَ فَبَسَطْنَا أَيْدِيَنَا وَقُلْنَا قَدْ بَايَعْنَاكَ يَا رَسُولَ اللَّهِ فَعَلاَمَ نُبَايِعُكَ قَالَ عَلَى أَنْ تَعْبُدُوا اللَّهَ وَلاَ تُشْرِكُوا بِهِ شَيْئًا وَالصَّلَوَاتِ الْخَمْسِ وَتُطِيعُوا - وَأَسَرَّ كَلِمَةً خَفِيَّةً - وَلاَ تَسْأَلُوا النَّاسَ شَيْئًا. فَلَقَدْ رَأَيْتُ بَعْضَ أُولَئِكَ النَّفَرِ يَسْقُطُ سَوْطُ أَحَدِهِمْ فَمَا يَسْأَلُ أَحَدًا يُنَاوِلُهُ إِيَّاهُ."],"takhrij":"صحيح: رواه مسلم في الزكاة (1043) من طريقين عن مروان (ابن محمد الدمشقي)، حدثنا سعيد (هو ابن عبد العزيز)، عن ربيعة بن يزيد، عن أبي إدريس الخولاني، عن أبي مسلم الخولاني قال: حدثني الحبيب الأمين عوف بن مالك الأشجعي فذكره.","grade":"صحيح","chapter_ar":"باب مبايعة الإمام أكثر من مرة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1043).","chapter_en":"Pledging Allegiance to the Leader More Than Once","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["ʿAwf ibn Malik al-Ashjaʿi said: We were with the Messenger of Allah ﷺ, nine, eight, or seven of us, and he said: “Will you not pledge allegiance to the Messenger of Allah?” We had only recently pledged allegiance, so we said: “We have already pledged allegiance to you, Messenger of Allah.” Then he said: “Will you not pledge allegiance to the Messenger of Allah?” We said: “We have already pledged allegiance to you, Messenger of Allah.” Then he said: “Will you not pledge allegiance to the Messenger of Allah?” He said: So we stretched out our hands and said: “We have already pledged allegiance to you, Messenger of Allah, so upon what shall we pledge allegiance to you?” He said: “That you worship Allah, associate nothing with Him, perform the five prayers, and obey.” Then he quietly said a hidden word: “And that you do not ask people for anything.” I later saw some of those people drop a whip, yet he would not ask anyone to hand it to him."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1043,"lafz":true}],"full":1,"rep":[240,4234]},{"num":7645,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَمْتَحِنُ مَنْ هَاجَرَ إِلَيْهِ مِنَ الْمُؤْمِنَاتِ بِهَذِهِ الآيَةِ بِقَوْلِ اللَّهِ: ﴿يَا أَيُّهَا النَّبِيُّ إِذَا جَاءَكَ الْمُؤْمِنَاتُ يُبَايِعْنَكَ﴾ [سورة الممتحنة: 12] إِلَى قَوْلِهِ غَفُورٌ رَحِيمٌ قَالَ عُرْوَةُ: قَالَتْ عَائِشَةُ: فَمَنْ أَقَرَّ بِهَذَا الشَّرْطِ مِنَ الْمُؤْمِنَاتِ قَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : قَدْ بَايَعْتُكِ كَلاَمًا، وَلاَ وَاللَّهِ مَا مَسَّتْ يَدُهُ يَدَ امْرَأَةٍ قَطُّ فِي الْمُبَايَعَةِ مَا يُبَايِعُهُنَّ إِلاَّ بِقَوْلِهِ: قَدْ بَايَعْتُكِ عَلَى ذَلِكَ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4891)، ومسلم في الإمارة (1866: 88) كلاهما من طريق ابن شهاب، أخبرني عروة بن الزبير، أن عائشة زوج النبيصلى الله عليه وسلم أخبرته فذكرته. والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في مبايعة النساء","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4891) and Muslim (1866:88). The wording is from al-Bukhari.","chapter_en":"What Has Been Reported Concerning the Pledge of Allegiance of Women","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["ʿA’ishah narrated that the Messenger of Allah ﷺ used to test the believing women who migrated to him with this verse, from Allah’s statement: “O Prophet, when the believing women come to you pledging allegiance to you…” up to His statement: “Forgiving, Merciful.” ʿUrwah said: ʿA’ishah said: Any believing woman who accepted this condition, the Messenger of Allah ﷺ would say to her: “I have accepted your pledge verbally.” By Allah, his hand never touched the hand of a woman during the pledge of allegiance. He only accepted their pledge by saying: “I have accepted your pledge upon that.”"]},"intro":{"ar":["قال الله تعالى: (يَا أَيُّهَا النَّبِيُّ إِذَا جَاءَكَ الْمُؤْمِنَاتُ يُبَايِعْنَكَ عَلَىٰ أَنْ لَا يُشْرِكْنَ بِاللهِ شَيْئًا وَلَا يَسْرِقْنَ وَلَا يَزْنِينَ وَلَا يَقْتُلْنَ أَوْلَادَهُنَّ وَلَا يَأْتِينَ بِبُهْتَانٍ يَفْتَرِينَهُ بَيْنَ أَيْدِيهِنَّ وَأَرْجُلِهِنَّ وَلَا يَعْصِينَكَ فِي مَعْرُوفٍ فَبَايِعْهُنَّ وَاسْتَغْفِرْ لَهُنَّ اللهَ إِنَّ اللهَ غَفُورٌ رَحِيمٌ) [الممتحنة: ١٢]"],"en":["Allah the Exalted says: “O Prophet, when the believing women come to you pledging allegiance to you that they will not associate anything with Allah, will not steal, will not commit unlawful intercourse, will not kill their children, will not bring a slander they invent between their hands and feet, and will not disobey you in what is right, then accept their pledge and seek Allah’s forgiveness for them. Indeed, Allah is Forgiving, Merciful.” [Surah al-Mumtahanah: 12]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4891,"lafz":true},{"key":"muslim","label":"مسلم","number":1866}],"full":1},{"num":7646,"demo":false,"sanad":"","matn":["عَنْ أُمِّ عَطِيَّةَ، قَالَتْ بَايَعْنَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَرَأَ عَلَىَّ {أَنْ لاَ يُشْرِكْنَ بِاللَّهِ شَيْئًا} وَنَهَانَا عَنِ النِّيَاحَةِ، فَقَبَضَتِ امْرَأَةٌ مِنَّا يَدَهَا فَقَالَتْ فُلاَنَةُ أَسْعَدَتْنِي وَأَنَا أُرِيدُ أَنْ أَجْزِيَهَا، فَلَمْ يَقُلْ شَيْئًا، ثُمَّ رَجَعَتْ، فَمَا وَفَتِ امْرَأَةٌ إِلاَّ أُمُّ سُلَيْمٍ وَأُمُّ الْعَلاَءِ، وَابْنَةُ أَبِي سَبْرَةَ امْرَأَةُ مُعَاذٍ أَوِ ابْنَةُ أَبِي سَبْرَةَ وَامْرَأَةُ مُعَاذٍ."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7215)، ومسلم في الجنائز (936: 32) كلاهما من طريق حفصة، عن أم عطية.","grade":"متفق عليه","chapter_ar":"باب ما جاء في مبايعة النساء","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7215) and Muslim (936:32). The wording is from al-Bukhari.","chapter_en":"What Has Been Reported Concerning the Pledge of Allegiance of Women","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Umm ʿAtiyyah said: We pledged allegiance to the Prophet ﷺ, and he recited to us: “that they will not associate anything with Allah,” and he forbade us from wailing over the dead. One woman among us withdrew her hand and said: “So-and-so helped me in mourning, and I want to repay her.” He said nothing, so she went, then returned. No woman fulfilled this except Umm Sulaym, Umm al-ʿAla’, the daughter of Abu Sabrah, the wife of Muʿadh — or the daughter of Abu Sabrah and the wife of Muʿadh."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7215,"lafz":true},{"key":"muslim","label":"مسلم","number":936}],"full":1,"dr":1,"rep":[13537]},{"num":7647,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُبَايِعُ النِّسَاءَ بِالْكَلاَمِ بِهَذِهِ الآيَةِ {لاَ يُشْرِكْنَ بِاللَّهِ شَيْئًا} قَالَتْ وَمَا مَسَّتْ يَدُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَ امْرَأَةٍ، إِلاَّ امْرَأَةً يَمْلِكُهَا."],"takhrij":"صحيح: رواه البخاري في الأحكام (7214) عن محمود، حدثنا عبد الرزاق، أخبرنا معمر، عن الزهري، عن عروة، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في مبايعة النساء","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7214).","chapter_en":"What Has Been Reported Concerning the Pledge of Allegiance of Women","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["ʿA’ishah said: The Prophet ﷺ used to accept the pledge of allegiance from women verbally through this verse: “that they will not associate anything with Allah.” She said: The hand of the Messenger of Allah ﷺ never touched the hand of any woman except a woman whom he lawfully possessed."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7214,"lafz":true}],"full":1},{"num":7648,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: مَا مَسَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ امْرَأَةً قَطُّ إِلاَّ أَنْ يَأْخُذَ عَلَيْهَا فَإِذَا أَخَذَ عَلَيْهَا فَأَعْطَتْهُ قَالَ: اذْهَبِي فَقَدْ بَايَعْتُكِ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1866: 89) من طريق ابن وهب، حدثني مالك، عن ابن شهاب، عن عروة أن عائشة أخبرته عن بيعة النساء قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في مبايعة النساء","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1866:89).","chapter_en":"What Has Been Reported Concerning the Pledge of Allegiance of Women","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ never touched a woman with his hand at all. Rather, he would take the pledge from her, and when he had taken it and she had given it, he would say: “Go, for I have accepted your pledge.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1866,"lafz":true,"n":4835}],"full":1},{"num":7649,"demo":false,"sanad":"","matn":["عَنْ أُمَيْمَةَ بِنْتِ رُقَيْقَةَ أَنَّها قَالَتْ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي نِسْوَةٍ بايعنه عَلَى الإسلام فَقُلْنَ: يَا رَسُولَ اللَّهِ نُبَايِعُكَ عَلَى أَنْ لَا نُشْرِكَ بِاللهِ شَيْئًا، وَلَا نَسْرِقَ، وَلَا نَزْنِيَ، وَلَا نَقْتُلَ أَوْلاَدَنَا، وَلَا نَأْتِيَ بِبُهْتَانٍ نَفْتَرِيهِ بَيْنَ أَيْدِينَا وَأَرْجُلِنَا، وَلَا نَعْصِيَكَ فِي مَعْرُوفٍ، فَقَالَ رَسُولُ اللَّهِ : صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيمَا اسْتَطَعْتُنَّ وَأَطَقْتُنَّ قَالَتْ: فَقُلْنَ: اللهُ وَرَسُولُهُ أَرْحَمُ بِنَا من أَنْفُسِنَا، هَلُمَّ نُبَايِعُكَ يَا رَسُولَ اللَّهِ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنِّي لَا أُصَافِحُ النِّسَاءَ إِنَّمَا قَوْلِي لِمِائَةِ امْرَأَةٍ كَقَوْلِي لِامْرَأَةٍ وَاحِدَةٍ أَوْ مثل قَوْلِي لِامْرَأَةٍ وَاحِدَةٍ."],"takhrij":"صحيح: رواه مالك في البيعة (2) عن محمد بن المنكدر، عن أميمة بنت رقيقة فذكرته. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في مبايعة النساء","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (2), al-Tirmidhi (1597), al-Nasa’i (4181), Ibn Majah (2874), and Ahmad (27019).","chapter_en":"What Has Been Reported Concerning the Pledge of Allegiance of Women","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Umaymah bint Ruqayqah said: I came to the Messenger of Allah ﷺ with a group of women who pledged allegiance to him upon Islam. They said: “Messenger of Allah, we pledge allegiance to you that we will not associate anything with Allah, will not steal, will not commit unlawful intercourse, will not kill our children, will not bring a slander we invent between our hands and feet, and will not disobey you in what is right.” The Messenger of Allah ﷺ said: “As much as you are able and capable.” She said: They said: “Allah and His Messenger are more merciful to us than we are to ourselves. Come, let us pledge allegiance to you, Messenger of Allah.” The Messenger of Allah ﷺ said: “I do not shake hands with women. My statement to one hundred women is only like my statement to one woman, or like my statement to a single woman.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":2,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":1597},{"key":"nasai","label":"النسائي","number":4181,"n":4181},{"key":"ibnmajah","label":"ابن ماجه","number":2874},{"key":"ahmad","label":"مسند الإمام أحمد","number":27008,"n":27008}],"full":1,"dr":1,"rep":[9182,14260]},{"num":7650,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ: جَاءَتْ أُمَيْمَةُ بِنْتُ رُقَيْقَةَ، إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تُبَايِعُهُ عَلَى الْإِسْلَامِ، فَقَالَ: أُبَايِعُكِ عَلَى أَنْ لَا تُشْرِكِي بِاللهِ شَيْئًا، وَلَا تَسْرِقِي وَلَا تَزْنِي، وَلَا تَقْتُلِي وَلَدَكِ، وَلَا تَأْتِي بِبُهْتَانٍ تَفْتَرِينَهُ بَيْنَ يَدَيْكِ وَرِجْلَيْكِ، وَلَا تَنُوحِي، وَلَا تَبَرَّجِي تَبَرُّجَ الْجَاهِلِيَّةِ الْأُولَى."],"takhrij":"حسن: رواه أحمد (6850) عن خلف بن الوليد، حدثنا ابن عياش، عن سليمان بن سليم، عن عمرو بن شعيب، عن أبيه، عن جده قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في مبايعة النساء","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6850).","chapter_en":"What Has Been Reported Concerning the Pledge of Allegiance of Women","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb narrated from his father, from his grandfather, who said: Umaymah bint Ruqayqah came to the Messenger of Allah ﷺ to pledge allegiance to him upon Islam. He said: “I accept your pledge that you will not associate anything with Allah, will not steal, will not commit unlawful intercourse, will not kill your child, will not bring a slander you invent between your hands and feet, will not wail over the dead, and will not display yourself as women displayed themselves in the earlier age of ignorance.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":6850,"n":6850,"lafz":true}],"full":1,"dr":1},{"num":7651,"demo":false,"sanad":"","matn":["عن عبدالله بن عمرو بن العاص أن رسول الله صلي الله عليه وسلم كان لا يصافح النساء في البيعة."],"takhrij":"حسن: رواه أحمد (6998) عن عتاب بن زياد، أخبرنا عبـد الله، أخبرنا أسامة بن زيد، حدثني عمرو بن شعيب، عن أبيه، عن عبد الله بن عمرو فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في مبايعة النساء","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6998).","chapter_en":"What Has Been Reported Concerning the Pledge of Allegiance of Women","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs narrated that the Messenger of Allah ﷺ did not shake hands with women during the pledge of allegiance."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":6998,"n":6998,"lafz":true}],"full":1,"dr":1,"rep":[9184]},{"num":7652,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ يَزِيدَ قَالَتْ دَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  النِّسَاءَ الْمُؤْمِنِينَ إِلَى الْبَيْعَةِ فَقَالَتْ أَسْمَاءُ يَا رَسُولَ اللَّهِ أَلَا تَحْسِرُ لَنَا عَنْ يَدِكَ فَقَالَ إِنِّي لَا أُصَافِحُ النِّسَاءَ."],"takhrij":"حسن: رواه إسحاق بن راهويه كما في المطالب (2109) –واللفظ له- وأحمد مختصرا (27594) من طريقين عن عبد الحميد بن بهرام، عن شهر بن حوشب، عن أسماء بنت يزيد فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء في مبايعة النساء","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ishaq ibn Rahwayh, as in al-Matalib (2109), and the wording is his; and by Ahmad in abridged form (27594).","chapter_en":"What Has Been Reported Concerning the Pledge of Allegiance of Women","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Asma’ bint Yazid said: The Messenger of Allah ﷺ called the believing women to pledge allegiance. Asma’ said: “Messenger of Allah, will you not uncover your hand for us?” He said: “I do not shake hands with women.”"]}},"tuhfa":{},"refs":[{"key":"sh13159","label":"إسحاق بن راهويه كما في المطالب","number":2109,"lafz":true,"n":2232},{"key":"ahmad","label":"— واللفظ له — وأحمد مختصرًا","number":27594}],"full":1,"dr":1,"rep":[14261]},{"num":7653,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ جَاءَ عَبْدٌ فَبَايَعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْهِجْرَةِ وَلَمْ يَشْعُرْ أَنَّهُ عَبْدٌ فَجَاءَ سَيِّدُهُ يُرِيدُهُ فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِعْنِيهِ. فَاشْتَرَاهُ بِعَبْدَيْنِ أَسْوَدَيْنِ ثُمَّ لَمْ يُبَايِعْ أَحَدًا بَعْدُ حَتَّى يَسْأَلَهُ أَعَبْدٌ هُوَ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1602) من طرق عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب بيعة العبد","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1602).","chapter_en":"The Pledge of Allegiance of a Slave","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Jabir said: A slave came and pledged allegiance to the Prophet ﷺ for migration, and he did not realize that he was a slave. Then his master came seeking him, so the Prophet ﷺ said to him: “Sell him to me.” He bought him for two black slaves. After that, he would not accept anyone’s pledge until he asked him: “Are you a slave?”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1602,"lafz":true}],"full":1,"rep":[5892]},{"num":7654,"demo":false,"sanad":"","matn":["عَنْ الشريد قَالَ: كَانَ فِي وَفْدِ ثَقِيفٍ رَجُلٌ مَجْذُومٌ فَأَرْسَلَ إِلَيْهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنَّا قَدْ بَايَعْنَاكَ فَارْجِعْ."],"takhrij":"صحيح: رواه مسلم في السلام (2231) من طريقين عن يعلى بن عطاء، عن عمرو بن الشريد، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب بيعة من به عاهة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2231).","chapter_en":"The Pledge of Allegiance of One Who Has an Affliction","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Ash-Sharid said: Among the delegation of Thaqif there was a man afflicted with leprosy, so the Prophet ﷺ sent word to him: “We have accepted your pledge, so return.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2231,"lafz":true}],"full":1,"rep":[9786,11652]},{"num":7655,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن هِشَامٍ وَكَانَ، قَدْ أَدْرَكَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَذَهَبَتْ بِهِ أُمُّهُ زَيْنَبُ ابْنَةُ حُمَيْدٍ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ يَا رَسُولَ اللَّهِ بَايِعْهُ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هُوَ صَغِيرٌ فَمَسَحَ رَأْسَهُ وَدَعَا لَهُ، وَكَانَ يُضَحِّي بِالشَّاةِ الْوَاحِدَةِ عَنْ جَمِيعِ أَهْلِهِ."],"takhrij":"صحيح: رواه البخاري في الأحكام (7210) عن علي بن عبد الله، حدثنا عبد الله بن يزيد، حدثنا سعيد بن أبي أيوب قال: حدثني أبو عقيل زهرة بن معبد، عن جده عبد الله بن هشام فذكره.","grade":"صحيح","chapter_ar":"باب لا تصح بيعة الصغير","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7210).","chapter_en":"The Pledge of Allegiance of a Child Is Not Valid","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["ʿAbdullah ibn Hisham, who had met the Prophet ﷺ, was taken by his mother Zaynab bint Humayd to the Messenger of Allah ﷺ. She said: “Messenger of Allah, accept his pledge.” The Prophet ﷺ said: “He is young.” He wiped his head and supplicated for him. He used to offer one sheep as a sacrifice on behalf of all his family."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7210,"lafz":true}],"full":1},{"num":7656,"demo":false,"sanad":"","matn":["عَنِ الْهِرْمَاسِ بْنِ زِيَادٍ، قَالَ مَدَدْتُ يَدِي إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا غُلاَمٌ لِيُبَايِعَنِي فَلَمْ يُبَايِعْنِي."],"takhrij":"حسن: رواه النسائي (4183) عن عبد الرحمن بن محمد بن سلام، حدثنا عمرو بن يونس، عن عكرمة بن عمار، عن الهرماس بن زياد قال: فذكره.","grade":"حسن","chapter_ar":"باب لا تصح بيعة الصغير","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4183).","chapter_en":"The Pledge of Allegiance of a Child Is Not Valid","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["Al-Hirmas ibn Ziyad said: I stretched out my hand to the Prophet ﷺ when I was a boy so that he would accept my pledge, but he did not accept my pledge."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4183,"lafz":true,"n":4183}],"full":1,"dr":1},{"num":7657,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهَ عَلَيْهِ وَسَلَّمَ قَالَ: كَانَتْ بَنُو إِسْرَائِيلَ تَسُوسُهُمُ الأَنْبِيَاءُ كُلَّمَا هلكَ نبيٌّ خَلَفَهُ نبيٌّ، وَإِنَّهُ لاَ نبيَّ بَعْدِي، وَسَيَكُونُ خُلَفَاءُ فَيَكْثُرُونَ قَالُوا: فَمَا تَأْمُرُنَا؟ قَالَ: فُوا بِبَيْعَةِ الأَوَّلِ فَالأَوَّلِ، أَعْطُوهُمْ حقَّهم، فإنّ اللَّهَ سَائِلُهُمْ عَمَّا اسْتَرْعَاهُمْ."],"takhrij":"متفق عليه: رواه البخاري في أحاديث الأنبياء (3455)، ومسلم في الإمارة (1842: 44) كلاهما عن محمد بن بشار، حدثنا محمد بن جعفر، حدثنا شعبة، عن فرات القزاز، قال: سمعت أبا حازم قال: قاعدت أبا هريرة خمس سنين فسمعته يحدث فذكره.","grade":"متفق عليه","chapter_ar":"باب الوفاء ببيعة الإمام الأول، ولا يبايع لأكثر من إمام في البلد الواحد","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3455) and Muslim (1842:44).","chapter_en":"Fulfilling the Pledge to the First Leader, and Not Pledging Allegiance to More Than One Leader in One Land","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “The Children of Israel were governed by the prophets. Whenever a prophet died, another prophet succeeded him. There will be no prophet after me, but there will be successors, and they will be many.” They said: “What do you command us?” He said: “Fulfill the pledge to the first, then the first. Give them their right, for Allah will question them about what He entrusted to them.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3455,"lafz":true},{"key":"muslim","label":"مسلم","number":1842}],"full":1,"dr":1,"rep":[750]},{"num":7658,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عمرو بْنِ الْعَاصِ قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَنَزَلْنَا مَنْزِلاً، فَمِنَّا مَنْ يُصْلِحُ خِبَاءَهُ، وَمِنَّا مَنْ يَنْتَضِلُ، وَمِنَّا مَنْ هُوَ فِي جَشَرِهِ، إِذْ نَادَى مُنَادِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : الصَّلاَةَ جَامِعَةً، فَاجْتَمَعْنَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَقَالَ: إِنَّهُ لَمْ يَكُنْ نبيٌّ قَبْلِي إِلاَّ كَانَ حَقًّا عَلَيْهِ أَنْ يدلّ أُمَّتَهُ عَلَى خَيْرِ مَا يَعْلَمُهُ لَهُمْ، وَيُنْذِرَهُمْ شَرَّ مَا يَعْلَمُهُ لَهُمْ، وإنَّ أُمَّتَكُمْ هَذِهِ جُعِلَ عَافِيَتُهَا فِي أَوَّلِهَا، وَسَيُصِيبُ آخِرَهَا بَلاَءٌ وَأُمُورٌ تُنْكِرُونَهَا، وَتَجِيءُ فِتْنَةٌ، فَيُرَقِّقُ بَعْضُهَا بَعْضُهَا، وَتَجِيءُ الْفِتْنَةُ، فَيَقُولُ الْمُؤْمِنُ: هَذِهِ مُهْلِكَتِي، ثُمَّ تَنْكَشِفُ وَتَجِيءُ الْفِتْنَةُ، فَيَقُولُ الْمُؤْمِنُ: هَذِهِ هَذِهِ، فَمَنْ أَحَبَّ أَنْ يُزَحْزَحَ عَنِ النَّارِ، وَيَدْخُلَ الْجَنَّةَ، فَلْتَأْتِهِ مَنِيَّتُهُ وَهُوَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ، وَلْيَأْتِ إِلَى النَّاسِ الَّذِي يُحِبُّ أَنْ يُؤْتَى إِلَيْهِ، وَمَنْ بَايَعَ إِمَامًا فَأَعْطَاهُ صَفْقَةَ يَدِهِ وَثَمَرَةَ قَلْبِهِ، فَلْيُطِعْهُ إِنِ اسْتَطَاعَ، فَإِنْ جَاءَ آخَرُ يُنَازِعُهُ فَاضْرِبُوا عُنُقَ الآخَرِ فَدَنَوْتُ مِنْهُ فَقُلْتُ: أَنْشُدُكَ اللَّهَ آنْتَ سَمِعْتَ هَذَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ؟ فَأَهْوَى إِلَى أُذُنَيْهِ وَقَلْبِهِ بِيَدَيْهِ، وَقَالَ: سَمِعَتْهُ أذناي وَوَعَاهُ قَلْبِي، فَقُلْتُ لَهُ: هَذَا ابْنُ عَمِّكَ مُعَاوِيَةُ يَأْمُرُنَا أَنْ نَأْكُلَ أَمْوَالَنَا بَيْنَنَا بِالْبَاطِلِ، وَنَقْتُلَ أَنْفُسَنَا، وَاللَّهُ يَقُولُ: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَأْكُلُوا أَمْوَالَكُمْ بَيْنَكُمْ بِالْبَاطِلِ إِلَّا أَنْ تَكُونَ تِجَارَةً عَنْ تَرَاضٍ مِنْكُمْ وَلَا تَقْتُلُوا أَنْفُسَكُمْ إِنَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا﴾ [سورة النساء: 29] قَالَ: فَسَكَتَ سَاعَةً، ثُمَّ قَالَ: أطِعْه فِي طَاعَةِ اللَّهِ، واعْصِه فِي مَعْصِيَةِ اللَّهِ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1844) من طريقين عن جرير، عن الأعمش، عن زيد بن وهب، عن عبدالرحمن بن عبد رب الكعبة قال: دخلتُ المسجدَ، فإذا عبدالله بن عمرو بن العاص جالس في ظلّ الكعبة، والناس مجتمعون عليه، فأتيتهم، فجلستُ إليه قال: فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الوفاء ببيعة الإمام الأول، ولا يبايع لأكثر من إمام في البلد الواحد","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in the Book of Leadership (1844).","chapter_en":"Fulfilling the Pledge to the First Leader, and Not Pledging Allegiance to More Than One Leader in One Land","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs said: We were with the Messenger of Allah ﷺ on a journey, and we stopped at a place. Some of us were repairing their tents, some were practicing archery, and some were with their grazing animals, when the caller of the Messenger of Allah ﷺ called out: “The prayer is gathering.” So we gathered around the Messenger of Allah ﷺ and he said: “There was no prophet before me except that it was his duty to guide his nation to the best of what he knew for them, and to warn them against the worst of what he knew for them. This nation of yours has had its well-being placed in its beginning, and its latter part will be afflicted by trials and matters you will disapprove of. A trial will come, and each one will make the previous one seem light. A trial will come, and the believer will say: ‘This is my destruction.’ Then it will be removed, and another trial will come, and the believer will say: ‘This, this.’ Whoever loves to be moved away from the Fire and admitted into Paradise, let death come to him while he believes in Allah and the Last Day, and let him treat people in the way he loves to be treated. Whoever pledges allegiance to a leader, giving him the clasp of his hand and the fruit of his heart, let him obey him if he is able. If another comes to challenge him, then strike the neck of the latter.” I drew near to him and said: “I ask you by Allah, did you yourself hear this from the Messenger of Allah ﷺ?” He pointed with his hands to his ears and heart and said: “My ears heard it, and my heart understood it.” I said to him: “This cousin of yours, Muʿawiyah, commands us to consume our wealth among ourselves falsely and to kill ourselves, while Allah says: ‘O you who believe, do not consume your wealth among yourselves falsely, except through trade by mutual consent among you, and do not kill yourselves. Indeed, Allah is Merciful to you.’” He remained silent for a while, then said: “Obey him in obedience to Allah, and disobey him in disobedience to Allah.”"]},"buhuth":{"en":["His word “grazing animals”: Abu ʿUbayd said it refers to people who go out to pasture with their animals. Al-Asmaʿi said: They spend the night there, and some may think it is a journey in which the prayer may be shortened, but that is not the case.","His statement, “This nation of yours has had its well-being placed in its beginning, and its latter part will be afflicted by trials and matters you will disapprove of,” refers to the beginning of the nation: the era of the Prophet ﷺ and the era of the first three caliphs until ʿUthman, may Allah be pleased with him, was killed. Those years were the time of the unity of this nation and the stability of its affair. When ʿUthman was killed, trials surged like the waves of the sea and followed one another like pieces of a dark night, and they have continued one after another until our present day.","The statement of ʿAbd al-Rahman ibn ʿAbd Rabb al-Kaʿbah, “This cousin of yours, Muʿawiyah, commands us to consume our wealth among ourselves falsely and to kill ourselves,” means that ʿAbd al-Rahman ibn ʿAbd Rabb al-Kaʿbah understood this description to apply to Muʿawiyah ibn Abi Sufyan because of his dispute with ʿAli, may Allah be pleased with him, while the pledge to ʿAli had already preceded. He therefore viewed Mu‘awiyah’s spending of wealth on his soldiers and followers in the war against ʿAli as consuming wealth falsely.","This ʿAbd al-Rahman was not known for partisanship toward ʿAli, so this statement is understood as his own conclusion, not as a textual proof that people’s wealth was being consumed falsely.","Some of the early scholars said: If lands are far apart, then it is permissible for each land to have a ruler, as is the case today."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم في الإمارة","number":1844,"lafz":true}],"full":1,"dr":1},{"num":7659,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَلاَثَةٌ لاَ يُكَلِّمُهُمُ اللَّهُ يَوْمَ الْقِيَامَةِ، وَلاَ يُزَكِّيهِمْ، وَلَهُمْ عَذَابٌ أَلِيمٌ رَجُلٌ عَلَى فَضْلِ مَاءٍ بِالطَّرِيقِ يَمْنَعُ مِنْهُ ابْنَ السَّبِيلِ، وَرَجُلٌ بَايَعَ إِمَامًا لاَ يُبَايِعُهُ إِلاَّ لِدُنْيَاهُ، إِنْ أَعْطَاهُ مَا يُرِيدُ وَفَى لَهُ، وَإِلاَّ لَمْ يَفِ لَهُ، وَرَجُلٌ يُبَايِعُ رَجُلاً بِسِلْعَةٍ بَعْدَ الْعَصْرِ فَحَلَفَ بِاللَّهِ لَقَدْ أُعْطِيَ بِهَا كَذَا وَكَذَا فَصَدَّقَهُ، فَأَخَذَهَا، وَلَمْ يُعْطَ بِهَا."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7212)، ومسلم في الإيمان (108: 173) كلاهما من طريق الأعمش، عن أبي صالح، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب إثم من لم يف بالبيعة إلا من أجل الدنيا","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7212) and Muslim (108:173).","chapter_en":"The Sin of One Who Does Not Fulfill the Pledge Except for Worldly Gain","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":20,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “There are three whom Allah will not speak to on the Day of Resurrection, will not purify, and for whom there will be a painful punishment: a man who has surplus water on the road but prevents a traveler from it; a man who pledges allegiance to a leader only for worldly gain, so if he gives him what he wants he fulfills it, and if not he does not fulfill it; and a man who sells an item to another man after the late afternoon prayer and swears by Allah that he was offered such and such for it, so the buyer believes him and takes it, though he was not offered that amount.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7212,"lafz":true},{"key":"muslim","label":"مسلم","number":108}],"full":1},{"num":7660,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ: أَنَّ أَعْرَابِيًّا بَايَعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَأَصَابَ الأَعْرَابِيَّ وَعْكٌ بِالْمَدِينَةِ، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا مُحَمَّدِ! أَقِلْنِي بَيْعَتِي، فَأَبَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ جَاءَهُ فَقَالَ: أَقِلْنِي بَيْعَتِي، فَأَبَى، ثُمَّ جَاءَهُ فَقَالَ: أَقِلْنِي بَيْعَتِي فَأَبَى، فَخَرَجَ الأَعْرَابِيُّ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنَّمَا الْمَدِينَةُ كَالْكِيرِ تَنْفِي خَبَثَهَا، وَيَنْصَعُ طِيبُهَا."],"takhrij":"متفق عليه: رواه مالك في الجامع (4) عن محمد بن المنكدر، عن جابر بن عبدالله فذكره. ورواه البخاري في الأحكام (7211)، ومسلم في الحج (383: 489) كلاهما من طريق مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب الترهيب من نقض البيعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (4), al-Bukhari (7211), and Muslim (383:489).","chapter_en":"Warning Against Breaking the Pledge of Allegiance","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Jabir ibn ʿAbdullah narrated that a Bedouin pledged allegiance to the Messenger of Allah ﷺ, then the Bedouin suffered fever in Madinah. He came to the Prophet ﷺ and said: “Muhammad, release me from my pledge.” The Messenger of Allah ﷺ refused. Then he came again and said: “Release me from my pledge.” He refused. Then he came again and said: “Release me from my pledge.” He refused. So the Bedouin left. The Messenger of Allah ﷺ said: “Madinah is only like a furnace: it removes its impurity and purifies its goodness.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":4,"lafz":true},{"key":"bukhari","label":"البخاري","number":7211},{"key":"muslim","label":"مسلم","number":383}],"full":1},{"num":7661,"demo":false,"sanad":"","matn":["عَنْ نَافِعٍ، قَالَ لَمَّا خَلَعَ أَهْلُ الْمَدِينَةِ يَزِيدَ بْنَ مُعَاوِيَةَ جَمَعَ ابْنُ عُمَرَ حَشَمَهُ وَوَلَدَهُ فَقَالَ إِنِّي سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ يُنْصَبُ لِكُلِّ غَادِرٍ لِوَاءٌ يَوْمَ الْقِيَامَةِ. وَإِنَّا قَدْ بَايَعْنَا هَذَا الرَّجُلَ عَلَى بَيْعِ اللَّهِ وَرَسُولِهِ، وَإِنِّي لاَ أَعْلَمُ غَدْرًا أَعْظَمَ مِنْ أَنْ يُبَايَعَ رَجُلٌ عَلَى بَيْعِ اللَّهِ وَرَسُولِهِ، ثُمَّ يُنْصَبُ لَهُ الْقِتَالُ، وَإِنِّي لاَ أَعْلَمُ أَحَدًا مِنْكُمْ خَلَعَهُ، وَلاَ بَايَعَ فِي هَذَا الأَمْرِ، إِلاَّ كَانَتِ الْفَيْصَلَ بَيْنِي وَبَيْنَهُ."],"takhrij":"متفق عليه: رواه البخاري في الفتن (7111) عن سليمان بن حرب، عن حماد بن زيد، عن نافع ذكره.","grade":"متفق عليه","chapter_ar":"باب الترهيب من نقض البيعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7111).","chapter_en":"Warning Against Breaking the Pledge of Allegiance","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Nafiʿ said: When the people of Madinah removed Yazid ibn Muʿawiyah, Ibn ʿUmar gathered his servants and children and said: I heard the Prophet ﷺ say: “A banner will be raised for every betrayer on the Day of Resurrection.” We have pledged allegiance to this man upon the pledge of Allah and His Messenger, and I do not know of any betrayal greater than that a man should pledge allegiance upon the pledge of Allah and His Messenger, then set up fighting against him. I do not know of anyone among you who removes him, or pledges allegiance in this affair, except that there will be separation between me and him."]},"buhuth":{"en":["His word “separation” means cutting off and abandonment. Ibn Hajar said: In this hadith is the obligation of obeying the leader whose pledge has been established, and the prohibition of revolting against him even if he is unjust in his rule, and that he is not removed by sinful conduct. Fath al-Bari (13/71)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7111,"lafz":true}],"full":1,"dr":1},{"num":7662,"demo":false,"sanad":"","matn":["عَنْ نَافِعٍ، قَالَ جَاءَ عَبْدُ اللَّهِ بْنُ عُمَرَ إِلَى عَبْدِ اللَّهِ بْنِ مُطِيعٍ حِينَ كَانَ مِنْ أَمْرِ الْحَرَّةِ مَا كَانَ زَمَنَ يَزِيدَ بْنِ مُعَاوِيَةَ فَقَالَ اطْرَحُوا لأَبِي عَبْدِ الرَّحْمَنِ وِسَادَةً فَقَالَ إِنِّي لَمْ آتِكَ لأَجْلِسَ أَتَيْتُكَ لأُحَدِّثَكَ حَدِيثًا سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُهُ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ مَنْ خَلَعَ يَدًا مِنْ طَاعَةٍ لَقِيَ اللَّهَ يَوْمَ الْقِيَامَةِ لاَ حُجَّةَ لَهُ وَمَنْ مَاتَ وَلَيْسَ فِي عُنُقِهِ بَيْعَةٌ مَاتَ مِيتَةً جَاهِلِيَّةً."],"takhrij":"صحيح: رواه مسلم في الإمارة (1851: 58) عن عبيد الله بن معاذ العنبري، حدثنا أبي، حدثنا عاصم -وهو بن محمد بن زيد- عن زيد بن محمد، عن نافع قال: فذكره.","grade":"صحيح","chapter_ar":"باب إثم من مات وليس في عنقه بيعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1851:58).","chapter_en":"The Sin of One Who Dies Without a Pledge of Allegiance Upon His Neck","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Nafiʿ said: ʿAbdullah ibn ʿUmar came to ʿAbdullah ibn Mutiʿ when the event of al-Harrah occurred during the time of Yazid ibn Muʿawiyah. He said: “Place a cushion for Abu ʿAbd al-Rahman.” He said: “I did not come to you to sit. I came to narrate to you a hadith I heard the Messenger of Allah ﷺ say. I heard the Messenger of Allah ﷺ say: ‘Whoever withdraws his hand from obedience will meet Allah on the Day of Resurrection with no proof for himself, and whoever dies without a pledge of allegiance upon his neck dies a death of the age of ignorance.’”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1851,"lafz":true}],"full":1},{"num":7663,"demo":false,"sanad":"","matn":["عَنْ جُنْدَبِ بْنِ عَبْدِ اللَّهِ الْبَجَلِيِّ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ قُتِلَ تَحْتَ رَايَةٍ عُمِّيَّةٍ يَدْعُو عَصَبِيَّةً أَوْ يَنْصُرُ عَصَبِيَّةً فَقِتْلَةٌ جَاهِلِيَّةٌ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1850: 57) عن هُريم بن عبد الأعلى، حدثنا المعتمر قال: سمعت أبي يحدث عن أبي مجلز عن جندب بن عبد الله البجلي قال: فذكره.","grade":"صحيح","chapter_ar":"باب إثم من مات وليس في عنقه بيعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1850:57).","chapter_en":"The Sin of One Who Dies Without a Pledge of Allegiance Upon His Neck","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Jundub ibn ʿAbdullah al-Bajali said: The Messenger of Allah ﷺ said: “Whoever is killed under a blind banner, calling to partisanship or supporting partisanship, then his killing is a killing of the age of ignorance.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1850,"lafz":true}],"full":1},{"num":7664,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ مَنْ خَرَجَ مِنَ الطَّاعَةِ وَفَارَقَ الْجَمَاعَةَ فَمَاتَ مَاتَ مِيتَةً جَاهِلِيَّةً وَمَنْ قَاتَلَ تَحْتَ رَايَةٍ عُمِّيَّةٍ يَغْضَبُ لِعَصَبَةٍ أَوْ يَدْعُو إِلَى عَصَبَةٍ أَوْ يَنْصُرُ عَصَبَةً فَقُتِلَ فَقِتْلَةٌ جَاهِلِيَّةٌ وَمَنْ خَرَجَ عَلَى أُمَّتِي يَضْرِبُ بَرَّهَا وَفَاجِرَهَا وَلاَ يَتَحَاشَ مِنْ مُؤْمِنِهَا وَلاَ يَفِي لِذِي عَهْدٍ عَهْدَهُ فَلَيْسَ مِنِّي وَلَسْتُ مِنْهُ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1848) عن شيبان بن فروخ، حدثنا جرير بن حازم، حدثنا غيلان بن جرير، عن أبي قيس بن رياح، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب إثم من مات وليس في عنقه بيعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1848).","chapter_en":"The Sin of One Who Dies Without a Pledge of Allegiance Upon His Neck","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “Whoever leaves obedience, separates from the community, and then dies, dies a death of the age of ignorance. Whoever fights under a blind banner, becoming angry for a faction, calling to a faction, or supporting a faction, and is killed, then his killing is a killing of the age of ignorance. Whoever rebels against my nation, striking its righteous and wicked alike, not sparing its believer, and not fulfilling the covenant of the one under covenant, then he is not from me and I am not from him.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1848,"lafz":true}],"full":1,"rep":[15013]},{"num":7665,"demo":false,"sanad":"","matn":["عَنْ رِبْعِىِّ بْنِ حِرَاشٍ قَالَ: انْطَلَقْتُ إِلَى حُذَيْفَةَ بِالْمَدَائِنِ لَيَالِيَ سَارَ النَّاسُ إِلَى عُثْمَانَ، فَقَالَ: يَا رِبْعِيُّ، مَا فَعَلَ قَوْمُكَ؟ قَالَ: قُلْتُ: عَنْ أَيِّ بَالِهِمْ تَسْأَلُ؟ قَالَ: مَنْ خَرَجَ مِنْهُمْ إِلَى هَذَا الرَّجُلِ، فَسَمَّيْتُ رِجَالًا فِيمَنْ خَرَجَ إِلَيْهِ، فَقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ فَارَقَ الْجَمَاعَةَ وَاسْتَذَلَّ الْإِمَارَةَ لَقِيَ اللَّهَ وَلَا وَجْهَ لَهُ عِنْدَهُ."],"takhrij":"حسن: رواه أحمد (23283، 23284) من طرق عن أبي النضر كثير بن أبي كثير، حدثنا ربعي بن حراش فذكره.","grade":"حسن","chapter_ar":"باب إثم من مات وليس في عنقه بيعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (23284, 23283).","chapter_en":"The Sin of One Who Dies Without a Pledge of Allegiance Upon His Neck","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Ribʿi ibn Hirash said: I went to Hudhayfah in al-Mada’in during the nights when people marched against ʿUthman. He said: “Ribʿi, what have your people done?” I said: “Which of their affairs are you asking about?” He said: “Who among them went out against this man?” So I named men among those who went out against him. He said: I heard the Messenger of Allah ﷺ say: “Whoever separates from the community and humiliates leadership will meet Allah with no standing before Him.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":23283,"n":23283,"lafz":true},{"key":"ahmad","label":"احمد","number":23284,"n":23283}],"full":1,"dr":1},{"num":7666,"demo":false,"sanad":"","matn":["عَنْ مُعَاوِيَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ مَاتَ بِغَيْرِ إِمَامٍ مَاتَ مِيتَةً جَاهِلِيَّةً."],"takhrij":"حسن: رواه أحمد (16876)، وصحّحه ابن حبان (4573) كلاهما من طرق عن أبي بكر بن عياش، عن عاصم بن أبي النجود، عن أبي صالح، عن معاوية فذكره.","grade":"حسن","chapter_ar":"باب إثم من مات وليس في عنقه بيعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (16876), graded authentic by Ibn Hibban (4573), and by Ibn Abi ʿAsim in al-Sunnah (1091).","chapter_en":"The Sin of One Who Dies Without a Pledge of Allegiance Upon His Neck","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Muʿawiyah said: The Messenger of Allah ﷺ said: “Whoever dies without a leader dies a death of the age of ignorance.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"صححه ابن حبان","number":4573},{"key":"sh5930","label":"ابن أبي عاصم في السنة","number":1091},{"key":"ahmad","label":"مسند الإمام أحمد","number":16876,"n":16876,"lafz":true}],"full":1,"dr":1},{"num":7667,"demo":false,"sanad":"","matn":["عن فَضَالَةَ بن عبيد عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: ثَلَاثَةٌ لَا تَسْأَلْ عَنْهُمْ: رَجُلٌ فَارَقَ الْجَمَاعَةَ، وَعَصَى إِمَامَهُ، وَمَاتَ عَاصِيًا، وَأَمَةٌ أَوْ عَبْدٌ أَبَقَ فَمَاتَ، وَامْرَأَةٌ غَابَ عَنْهَا زَوْجُهَا، قَدْ كَفَاهَا مُؤْنَةَ الدُّنْيَا فَتَبَرَّجَتْ بَعْدَهُ، فَلَا تَسْأَلْ عَنْهُمْ، وَثَلَاثَةٌ لَا تَسْأَلْ عَنْهُمْ: رَجُلٌ نَازَعَ اللهَ رِدَاءَهُ، فَإِنَّ رِدَاءَهُ الْكِبْرِيَاءُ وَإِزَارَهُ الْعِزَّةُ، وَرَجُلٌ شَكَّ فِي أَمْرِ اللهِ وَالْقَنُوطُ مِنْ رَحْمَةِ اللَّهِ."],"takhrij":"صحيح: رواه أحمد (23943)، وصحّحه ابن حبان (4559)، والحاكم (1/119) كلهم من طريق أبي عبد الرحمن عبد الله بن يزيد المقرئ، حدثنا حيوة، حدثنا أبو هانئ، أن أبا علي عمرو بن مالك الجنبي حدثه عن فضالة بن عبيد فذكره.","grade":"صحيح","chapter_ar":"باب إثم من مات وليس في عنقه بيعة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (23943), graded authentic by Ibn Hibban (4559), and al-Hakim (1/119).","chapter_en":"The Sin of One Who Dies Without a Pledge of Allegiance Upon His Neck","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Fadalah ibn ʿUbayd narrated from the Messenger of Allah ﷺ that he said: “There are three about whom you should not ask: a man who separates from the community, disobeys his leader, and dies in disobedience; a female slave or male slave who runs away and dies; and a woman whose husband is absent, while he has provided her with enough worldly provision, but she displays herself after him, so do not ask about them. And three about whom you should not ask: a man who contends with Allah over His cloak, for His cloak is majesty and His lower garment is might; a man who doubts the command of Allah; and one who despairs of the mercy of Allah.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"صححه ابن حبان","number":4559},{"key":"hakim","label":"الحاكم","number":119,"n":408},{"key":"ahmad","label":"مسند الإمام أحمد","number":23943,"n":23943,"lafz":true}],"full":1,"dr":1},{"num":7668,"demo":false,"sanad":"","matn":["عن محمد بن زيد بن عبد الله بن عمر قال: قال أناس لابن عمر: إنا ندخل على سلطاننا فنقول لهم خلاف ما نتكلم إذا خرجنا من عندهم قال: كنا نعدها نفاقا. وفي رواية: كنا نعدُّ هذا نفاقا على عهد النبي صلى الله عليه وسلم."],"takhrij":"صحيح: رواه البخاري في الأحكام (7178) عن أبي نعيم، حدثنا عاصم بن محمد بن زيد بن عبد الله بن عمر، عن أبيه قال: فذكره.","grade":"صحيح","chapter_ar":"باب كراهية المبالغة في مدح السلطان في وجهه والطعن عليه في غيبته","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7178). The other wording was narrated by al-Tayalisi (2067), Ibn Majah (3975), and Ahmad (5829).","chapter_en":"The Dislike of Excessively Praising the Ruler to His Face and Criticizing Him in His Absence","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":23,"content":{"translation":{"en":["Muhammad ibn Zayd ibn ʿAbdullah ibn ʿUmar said: Some people said to Ibn ʿUmar: “We enter upon our rulers and say to them the opposite of what we say when we leave them.” He said: “We used to count that as hypocrisy.” In another wording: “We used to count this as hypocrisy during the time of the Prophet ﷺ.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7178,"lafz":true},{"key":"tayalisi","label":"الرواية الأخرى رواها الطيالسي","number":2067},{"key":"ibnmajah","label":"ابن ماجه","number":3975},{"key":"ahmad","label":"مسند الإمام أحمد","number":5829,"n":5829}],"full":1,"dr":1},{"num":7669,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِكَعْبِ بْنِ عُجْرَةَ: أَعَاذَكَ اللَّهُ مِنْ إِمَارَةِ السُّفَهَاءِ، قَالَ: وَمَا إِمَارَةُ السُّفَهَاءِ؟، قَالَ: أُمَرَاءُ يَكُونُونَ بَعْدِي، لَا يَقْتَدُونَ بِهَدْيِي، وَلَا يَسْتَنُّونَ بِسُنَّتِي، فَمَنْ صَدَّقَهُمْ بِكَذِبِهِمْ، وَأَعَانَهُمْ عَلَى ظُلْمِهِمْ، فَأُولَئِكَ لَيْسُوا مِنِّي، وَلَسْتُ مِنْهُمْ، وَلَا يَرِدُوا عَلَيَّ حَوْضِي، وَمَنْ لَمْ يُصَدِّقْهُمْ بِكَذِبِهِمْ، وَلَمْ يُعِنْهُمْ عَلَى ظُلْمِهِمْ، فَأُولَئِكَ مِنِّي وَأَنَا مِنْهُمْ، وَسَيَرِدُوا عَلَيَّ حَوْضِي. يَا كَعْبُ بْنَ عُجْرَةَ، الصَّوْمُ جُنَّةٌ، وَالصَّدَقَةُ تُطْفِئُ الْخَطِيئَةَ، وَالصَّلَاةُ قُرْبَانٌ - أَوْ قَالَ: بُرْهَانٌ - يَا كَعْبُ بْنَ عُجْرَةَ، إِنَّهُ لَا يَدْخُلُ الْجَنَّةَ لَحْمٌ نَبَتَ مِنْ سُحْتٍ النَّارُ، أَوْلَى بِهِ. يَا كَعْبُ بْنَ عُجْرَةَ، النَّاسُ غَادِيَانِ: فَمُبْتَاعٌ نَفْسَهُ فَمُعْتِقُهَا، وَبَائِعٌ نَفْسَهُ فَمُوبِقُهَا."],"takhrij":"حسن: رواه أحمد (14441) عن عبد الرزاق، أخبرنا معمر، عن ابن خثيم، عن عبد الرحمن بن سابط، عن جابر بن عبد الله فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في إمارة السفهاء، والزجر عن إعانتهم على ظلمهم","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (14441) and ʿAbd al-Razzaq (20719).","chapter_en":"What Has Been Reported Concerning the Leadership of Foolish People, and the Warning Against Helping Them in Their Oppression","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":24,"content":{"translation":{"en":["Jabir ibn ʿAbdullah narrated that the Prophet ﷺ said to Kaʿb ibn ʿUjrah: “May Allah protect you from the leadership of foolish people.” He said: “What is the leadership of foolish people?” He said: “Leaders who will come after me; they will not follow my guidance and will not act according to my way. Whoever believes them in their lies and helps them in their oppression, they are not from me and I am not from them, and they will not come to my reservoir. Whoever does not believe them in their lies and does not help them in their oppression, they are from me and I am from them, and they will come to my reservoir. Kaʿb ibn ʿUjrah, fasting is a shield, charity extinguishes sin, and prayer is nearness — or he said: proof. Kaʿb ibn ʿUjrah, no flesh that grows from unlawful earnings will enter Paradise; the Fire is more deserving of it. Kaʿb ibn ʿUjrah, people go out in two ways: one buys himself and frees himself, and another sells himself and destroys himself.”"]}},"tuhfa":{},"refs":[{"key":"abdrazzaq","label":"عبد الرزاق","number":20719},{"key":"ahmad","label":"مسند الإمام أحمد","number":14441,"n":14441,"lafz":true},{"key":"abdrazzaq","label":"المصنف لعبد الرزاق","number":21796,"n":21957}],"full":1,"dr":1,"rep":[859]},{"num":7670,"demo":false,"sanad":"","matn":["عَنْ كَعْبِ بْنِ عُجْرَةَ، قَالَ خَرَجَ إِلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ تِسْعَةٌ خَمْسَةٌ وَأَرْبَعَةٌ أَحَدُ الْعَدَدَيْنِ مِنَ الْعَرَبِ وَالآخَرُ مِنَ الْعَجَمِ فَقَالَ اسْمَعُوا هَلْ سَمِعْتُمْ أَنَّهُ سَيَكُونُ بَعْدِي أُمَرَاءُ فَمَنْ دَخَلَ عَلَيْهِمْ فَصَدَّقَهُمْ بِكَذِبِهِمْ وَأَعَانَهُمْ عَلَى ظُلْمِهِمْ فَلَيْسَ مِنِّي وَلَسْتُ مِنْهُ وَلَيْسَ بِوَارِدٍ عَلَىَّ الْحَوْضَ وَمَنْ لَمْ يَدْخُلْ عَلَيْهِمْ وَلَمْ يُعِنْهُمْ عَلَى ظُلْمِهِمْ وَلَمْ يُصَدِّقْهُمْ بِكَذِبِهِمْ فَهُوَ مِنِّي وَأَنَا مِنْهُ وَهُوَ وَارِدٌ عَلَىَّ."],"takhrij":"صحيح: رواه الترمذي (2259)، والنسائي (4207، 4208)، وأحمد (18126)، وابن حبان (282، 283، 285)، والحاكم (1/79) كلهم من طريق أبي حصين، (هو عثمان بن عاصم الأسدي)، عن الشّعبيّ، عن عاصم العدويّ، عن كعب بن عُجرة، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في إمارة السفهاء، والزجر عن إعانتهم على ظلمهم","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (2259), al-Nasa’i (4208, 4207), and Ahmad (18126), graded authentic by Ibn Hibban (282, 283, 285), and narrated by al-Hakim (263).","chapter_en":"What Has Been Reported Concerning the Leadership of Foolish People, and the Warning Against Helping Them in Their Oppression","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":24,"content":{"translation":{"en":["Kaʿb ibn ʿUjrah said: The Messenger of Allah ﷺ came out to us while we were nine: five and four, one of the two numbers being Arabs and the other non-Arabs. He said: “Listen. Have you heard that there will be leaders after me? Whoever enters upon them, believes them in their lies, and helps them in their oppression, he is not from me and I am not from him, and he will not come to my reservoir. Whoever does not enter upon them, does not help them in their oppression, and does not believe them in their lies, he is from me and I am from him, and he will come to me.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":2259,"lafz":true},{"key":"nasai","label":"النسائي","number":4208,"n":4208},{"key":"ibnhibban","label":"صححه ابن حبان","number":282},{"key":"ahmad","label":"مسند الإمام أحمد","number":18126,"n":18126},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":712,"n":712},{"key":"hakim","label":"المستدرك على الصحيحين","number":263,"n":261},{"key":"nasai","label":"النسائي","number":4207,"n":4208},{"key":"ibnhibban","label":"ابن حبان","number":283},{"key":"ibnhibban","label":"ابن حبان","number":285}],"full":1,"dr":1},{"num":7671,"demo":false,"sanad":"","matn":["عن حُذَيْفَةَ بن الْيَمَانِ يَقُولُ كَانَ النَّاسُ يَسْأَلُونَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْخَيْرِ، وَكُنْتُ أَسْأَلُهُ عَنِ الشَّرِّ، مَخَافَةَ أَنْ يُدْرِكَنِي فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّا كُنَّا فِي جَاهِلِيَّةٍ وَشَرٍّ فَجَاءَنَا اللَّهُ بِهَذَا الْخَيْرِ، فَهَلْ بَعْدَ هَذَا الْخَيْرِ مِنْ شَرٍّ قَالَ نَعَمْ. قُلْتُ وَهَلْ بَعْدَ ذَلِكَ الشَّرِّ مِنْ خَيْرٍ قَالَ نَعَمْ، وَفِيهِ دَخَنٌ. قُلْتُ وَمَا دَخَنُهُ قَالَ قَوْمٌ يَهْدُونَ بِغَيْرِ هَدْىٍ، تَعْرِفُ مِنْهُمْ وَتُنْكِرُ. قُلْتُ فَهَلْ بَعْدَ ذَلِكَ الْخَيْرِ مِنْ شَرٍّ قَالَ نَعَمْ، دُعَاةٌ عَلَى أَبْوَابِ جَهَنَّمَ، مَنْ أَجَابَهُمْ إِلَيْهَا قَذَفُوهُ فِيهَا. قُلْتُ يَا رَسُولَ اللَّهِ صِفْهُمْ لَنَا. قَالَ هُمْ مِنْ جِلْدَتِنَا، وَيَتَكَلَّمُونَ بِأَلْسِنَتِنَا. قُلْتُ فَمَا تَأْمُرُنِي إِنْ أَدْرَكَنِي ذَلِكَ قَالَ تَلْزَمُ جَمَاعَةَ الْمُسْلِمِينَ وَإِمَامَهُمْ. قُلْتُ فَإِنْ لَمْ يَكُنْ لَهُمْ جَمَاعَةٌ وَلاَ إِمَامٌ قَالَ فَاعْتَزِلْ تِلْكَ الْفِرَقَ كُلَّهَا، وَلَوْ أَنْ تَعَضَّ بِأَصْلِ شَجَرَةٍ، حَتَّى يُدْرِكَكَ الْمَوْتُ، وَأَنْتَ عَلَى ذَلِكَ."],"takhrij":"متفق عليه: رواه البخاري في الفتن (7084)، ومسلم في الإمارة (1847) كلاهما عن محمد بن المثنى، حدثنا الوليد بن مسلم، حدثنا ابن جابر، حدثني بسر بن عبيدالله الحضرمي، أنه سمع أبا إدريس الخولاني، أنه سمع حذيفة بن اليمان يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب وجوب لزوم جماعة المسلمين وإمامهم","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7084) and Muslim (1847).","chapter_en":"The Obligation of Adhering to the Community of Muslims and Their Leader","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":25,"content":{"translation":{"en":["Hudhayfah ibn al-Yaman said: People used to ask the Messenger of Allah ﷺ about good, while I used to ask him about evil, fearing that it might reach me. I said: “Messenger of Allah, we were in ignorance and evil, then Allah brought us this good. Will there be evil after this good?” He said: “Yes.” I said: “Will there be good after that evil?” He said: “Yes, but in it there will be impurity.” I said: “What is its impurity?” He said: “People who guide by other than my guidance; you will recognize some of what they do and reject some.” I said: “Will there be evil after that good?” He said: “Yes, callers at the gates of Hell; whoever responds to them, they will throw him into it.” I said: “Messenger of Allah, describe them to us.” He said: “They are from our own people and speak our language.” I said: “What do you command me to do if that reaches me?” He said: “Adhere to the community of Muslims and their leader.” I said: “What if they have no community and no leader?” He said: “Then withdraw from all those groups, even if you must bite onto the root of a tree until death reaches you while you are upon that.”"]},"buhuth":{"en":["His statement in the hadith, “Adhere to the community of Muslims,” al-Tabari said: “Meaning those who are in obedience to the one whom they have collectively appointed as leader. Whoever breaks his pledge has left the community.” He said: “In the hadith is that whenever people have no leader and split into factions, one should not follow anyone into division, and should withdraw from all of them if able, out of fear of falling into evil.” See Fath al-Bari (10/37)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7084,"lafz":true},{"key":"muslim","label":"مسلم","number":1847},{"key":"sh26356","label":"العزلة والانفراد","number":197,"n":196}],"full":1,"dr":1,"rep":[15752]},{"num":7672,"demo":false,"sanad":"","matn":["عَنْ تَمِيمٍ الدَّارِيِّ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ الدِّينُ النَّصِيحَةُ قُلْنَا لِمَنْ قَالَ لِلَّهِ وَلِكِتَابِهِ وَلِرَسُولِهِ وَلأَئِمَّةِ الْمُسْلِمِينَ وَعَامَّتِهِمْ."],"takhrij":"صحيح: رواه مسلم في الإيمان (55) عن محمد بن عباد المكي، حدثنا سفيان قال: قلت لسهيل: إن عمرا حدثنا عن القعقاع، عن أبيك. قال: ورجوت أن يسقط عني رجلا قال: فقال: سمعته من الذي سمعه منه أبي -كان صديقا له بالشام- ثم حدثنا سفيان، عن سهيل، عن عطاء بن يزيد، عن تميم الداري فذكره.","grade":"صحيح","chapter_ar":"باب مناصحة الحاكم باللين والحكمة والموعظة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (55).","chapter_en":"Advising the Ruler with Gentleness, Wisdom, and Admonition","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["Tamim al-Dari narrated that the Prophet ﷺ said: “Religion is sincere counsel.” We said: “For whom?” He said: “For Allah, His Book, His Messenger, the leaders of the Muslims, and their common people.”"]},"intro":{"ar":["وقد أرسل الله تعالى موسى وهارون إلى فرعون فقال: (اذْهَبَا إِلَىٰ فِرْعَوْنَ إِنَّهُ طَغَىٰ ٤٣ فَقُولَا لَهُ قَوْلًا لَيِّنًا لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَىٰ) [طه: ٤٣-٤٤]"],"en":["Allah the Exalted sent Moses and Aaron to Pharaoh and said: “Go, both of you, to Pharaoh. Indeed, he has transgressed. And speak to him with gentle speech, that perhaps he may remember or fear.” [Surah Ta Ha: 43–44]"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":55,"lafz":true}],"full":1,"dr":1,"rep":[145]},{"num":7673,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: قَالَ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الدِّينُ النَّصِيحَةُ، قَالَ: قُلْنَا: لِمَنْ يَا رَسُولَ اللَّهِ؟، قَالَ: لِلَّهِ، وَلِرَسُولِهِ، وَلِكِتَابِهِ، وَلِأَئِمَّةِ الْمُسْلِمِينَ وَعَامَّتِهِمْ."],"takhrij":"حسن: رواه البزار – كشف الأستار (62)، والدارمي (2796)، والطحاوي في شرح المشكل (1447) كلهم من طرقٍ عن هشام بن سعد، عن زيد بن أسلم ونافع، عن ابن عمر قال: فذكره.","grade":"حسن","chapter_ar":"باب مناصحة الحاكم باللين والحكمة والموعظة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzar — Kashf al-Astar (62), al-Darimi (2796), and al-Tahawi in Sharh al-Mushkil (1447).","chapter_en":"Advising the Ruler with Gentleness, Wisdom, and Admonition","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ said to us: “Religion is sincere counsel.” He said: We said: “For whom, Messenger of Allah?” He said: “For Allah, His Messenger, His Book, the leaders of the Muslims, and their common people.”"]},"buhuth":{"en":["The meaning of sincere counsel for Allah, Glorified is He, is sound belief in His oneness and sincerity of intention in worshiping Him. Sincere counsel for the Book of Allah is to believe in it and act according to what is in it. Sincere counsel for His Messenger is to affirm his prophethood and give obedience to him in what he commanded and forbade. Sincere counsel for the leaders of the Muslims is to obey them in truth and not to consider revolt against them with the sword if they are unjust. Sincere counsel for the general Muslims is to guide them to what benefits them. This was mentioned by al-Khattabi in Maʿalim al-Sunan."]}},"tuhfa":{},"refs":[{"key":"sh12862","label":"البزار — كشف الأستار","number":62,"lafz":true},{"key":"sh22547","label":"الطحاوي في شرح المشكل","number":1447},{"key":"darimi","label":"سنن الدارمي","number":2670,"n":2670},{"key":"darimi","label":"الدارمي","number":2796,"n":2670}],"full":1,"dr":1},{"num":7674,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بن ثَابِتٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: ثَلَاثُ خِصَالٍ لَا يغلّ عَلَيْهِنَّ قَلْبُ مُسْلِمٍ أَبَدًا: إِخْلَاصُ الْعَمَلِ لِلَّهِ، وَمُنَاصَحَةُ وُلَاةِ الْأَمْرِ، وَلُزُومُ الْجَمَاعَةِ، فَإِنَّ دَعْوَتَهُمْ تُحِيطُ مِنْ وَرَائِهِمْ."],"takhrij":"صحيح: رواه أحمد (21590)، وصحّحه ابن حبان (67) كلاهما من طريق شعبة، حدثنا عمر بن سليمان من ولد عمر بن الخطاب، عن عبد الرحمن بن أبان بن عثمان، عن أبيه، عن زيد بن ثابت فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب مناصحة الحاكم باللين والحكمة والموعظة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (21590), and graded authentic by Ibn Hibban (67).","chapter_en":"Advising the Ruler with Gentleness, Wisdom, and Admonition","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["Zayd ibn Thabit said: I heard the Messenger of Allah ﷺ say: “There are three qualities over which the heart of a Muslim will never harbor rancor: making deeds sincere for Allah, sincerely advising those in authority, and adhering to the community; for their supplication surrounds those behind them.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"صححه ابن حبان","number":67},{"key":"ahmad","label":"مسند الإمام أحمد","number":21590,"n":21590,"lafz":true},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":3630,"n":3626}],"full":1,"dr":1},{"num":7675,"demo":false,"sanad":"","matn":["عن شريح بْنِ عبيد الحضرمي وَغَيْرُهُ، قَالَ: جَلَدَ عِيَاضُ بْنُ غَنْمٍ صَاحِبَ دَارَا حِينَ فُتِحَتْ، فَأَغْلَظَ لَهُ هِشَامُ بْنُ حَكِيمٍ الْقَوْلَ حَتَّى غَضِبَ عِيَاضٌ، ثُمَّ مَكَثَ لَيَالِيَ، فَأَتَاهُ هِشَامُ بْنُ حَكِيمٍ فَاعْتَذَرَ إِلَيْهِ، ثُمَّ قَالَ هِشَامٌ لِعِيَاضٍ: أَلَمْ تَسْمَعِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ مِنْ أَشَدِّ النَّاسِ عَذَابًا، أَشَدَّهُمْ عَذَابًا فِي الدُّنْيَا لِلنَّاسِ ؟ فَقَالَ عِيَاضُ بْنُ غَنْمٍ: يَا هِشَامُ بْنَ حَكِيمٍ، قَدْ سَمِعْنَا مَا سَمِعْتَ، وَرَأَيْنَا مَا رَأَيْتَ، أَوَلَمْ تَسْمَعْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ أَرَادَ أَنْ يَنْصَحَ لِسُلْطَانٍ بِأَمْرٍ، فَلَا يُبْدِ لَهُ عَلَانِيَةً، وَلَكِنْ لِيَأْخُذْ بِيَدِهِ، فَيَخْلُوَ بِهِ، فَإِنْ قَبِلَ مِنْهُ فَذَاكَ، وَإِلَّا كَانَ قَدْ أَدَّى الَّذِي عَلَيْهِ لَهُ، وَإِنَّكَ يَا هِشَامُ لَأَنْتَ الْجَرِيءُ، إِذْ تَجْتَرِئُ عَلَى سُلْطَانِ اللهِ، فَهَلَّا خَشِيتَ أَنْ يَقْتُلَكَ السُّلْطَانُ، فَتَكُونَ قَتِيلَ سُلْطَانِ اللهِ تَبَارَكَ وَتَعَالَى."],"takhrij":"حسن: رواه أحمد (15333) عن أبي المغيرة، حدثنا صفوان، حدثنا شريح بن عبيد الحضرمي وغيره فذكروه.","grade":"حسن","chapter_ar":"باب مناصحة الحاكم باللين والحكمة والموعظة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (15333).","chapter_en":"Advising the Ruler with Gentleness, Wisdom, and Admonition","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["Shurayh ibn ʿUbayd al-Hadrami and others said: ʿIyad ibn Ghanm flogged the governor of Dara when it was conquered, so Hisham ibn Hakim spoke harshly to him until ʿIyad became angry. Then some nights passed, and Hisham ibn Hakim came to him and apologized to him. Then Hisham said to ʿIyad: “Did you not hear the Prophet ﷺ say: ‘Among the people most severely punished are those who punish people most severely in this world’?” ʿIyad ibn Ghanm said: “Hisham ibn Hakim, we have heard what you heard, and we have seen what you saw. Did you not hear the Messenger of Allah ﷺ say: ‘Whoever wishes to advise a ruler regarding a matter should not do so openly. Rather, let him take him by the hand and be alone with him. If he accepts from him, then that is it; otherwise, he has fulfilled what was due from him toward him.’ Hisham, you are indeed bold, since you are bold against the authority of Allah. Did you not fear that the ruler might kill you, so that you would be killed by the authority of Allah, Blessed and Exalted?”"]},"buhuth":{"en":["The methodology of the people of the Prophetic way and the Muslim community is to advise those in authority privately, and that this should not be done upon pulpits and in public gatherings.","The Companions used to advise governors privately. It was said to Usamah ibn Zayd: “What prevents you from entering upon ʿUthman and speaking to him about what he is doing?” Usamah replied: “Do you think that I do not speak to him unless I make you hear it? I speak to him privately, without opening a door that I would not like to be the first to open.” Narrated by al-Bukhari (3267) and Muslim (2989).","His Eminence Shaykh ʿAbd al-ʿAziz ibn Baz, may Allah have mercy on him, said: “It is not from the methodology of the early generations to publicize the faults of rulers and mention that upon pulpits, because that leads to upheavals, to abandoning hearing and obeying in what is right, and to rebellion that harms and does not benefit. Rather, the way followed by the early generations was to advise privately between themselves and the ruler, to write to him, or to contact the scholars who could reach him so that he would be directed to good.” Rights of the Shepherd and the Flock, pages 27–28, the Shaykh’s verdict at the end of the mentioned treatise."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":15333,"n":15333,"lafz":true}],"full":1,"dr":1},{"num":7676,"demo":false,"sanad":"","matn":["عَنْ عرفجة قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّهُ سَتَكُونُ هَنَاتٌ وَهَنَاتٌ فَمَنْ أَرَادَ أَنْ يُفَرِّقَ أَمْرَ هَذِهِ الْأُمَّةِ، وَهِيَ جَمِيعٌ، فَاضْرِبُوهُ بِالسَّيْفِ كَائِنًا مَنْ كَانَ.","وفي لفظ: رأيت النبي صلى الله عليه وسلم على المنبر يخطب الناس، فقال: إنه سيكون بعدي هنات وهنات، فمن رأيتموه فارق الجماعة، أو يريد يفرق أمر أمة محمد صلى الله عليه وسلم كائنا من كان، فاقتلوه؛ فإن يد الله على الجماعة، فإن الشيطان مع من فارق الجماعة يركض."],"takhrij":"صحيح: رواه مسلم في الإمارة (1852) من طريق غندر، حدثنا شعبة، عن زياد بن علاقة قال: سمعت عرفجة قال فذكره.","grade":"صحيح","chapter_ar":"باب الأمر بقتل من خرج على الإمام وجماعة المسلمين","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1852). The second wording was narrated by al-Nasā’ī (4020) and authenticated by Ibn Ḥibbān (4577).","chapter_en":"The Command to Kill Whoever Rebels Against the Leader and the Community of Muslims","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":27,"content":{"translation":{"en":["ʿArfajah reported: I heard the Messenger of Allah ﷺ say: “There will be disturbances and troubles. Whoever seeks to divide the affairs of this Ummah while it is united, then strike him with the sword, whoever he may be.” In another wording: I saw the Prophet ﷺ while he was on the pulpit addressing the people, and he said: “After me there will be disturbances and troubles. Whoever you see separating from the community, or seeking to divide the affairs of the Ummah of Muḥammad ﷺ, whoever he may be, then kill him. For the Hand of Allah is over the community, and Satan runs alongside the one who separates from the community.”"]},"buhuth":{"en":["The expression “hanāt and hanāt” uses the plural of hanah, a word that may refer generally to matters or occurrences; here it means trials, disturbances, and newly arising events."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1852,"lafz":true},{"key":"nasai","label":"اللفظ الثاني رواه النسائي","number":4020},{"key":"ibnhibban","label":"صححه ابن حبان","number":4577}],"full":1,"dr":1},{"num":7677,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ رَبِّ الْكَعْبَةِ، قَالَ دَخَلْتُ الْمَسْجِدَ فَإِذَا عَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ الْعَاصِ جَالِسٌ فِي ظِلِّ الْكَعْبَةِ وَالنَّاسُ مُجْتَمِعُونَ عَلَيْهِ فَأَتَيْتُهُمْ فَجَلَسْتُ إِلَيْهِ فَقَالَ كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ فَنَزَلْنَا مَنْزِلاً فَمِنَّا مَنْ يُصْلِحُ خِبَاءَهُ وَمِنَّا مَنْ يَنْتَضِلُ وَمِنَّا مَنْ هُوَ فِي جَشَرِهِ إِذْ نَادَى مُنَادِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الصَّلاَةَ جَامِعَةً. فَاجْتَمَعْنَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ إِنَّهُ لَمْ يَكُنْ نَبِيٌّ قَبْلِي إِلاَّ كَانَ حَقًّا عَلَيْهِ أَنْ يَدُلَّ أُمَّتَهُ عَلَى خَيْرِ مَا يَعْلَمُهُ لَهُمْ وَيُنْذِرَهُمْ شَرَّ مَا يَعْلَمُهُ لَهُمْ وَإِنَّ أُمَّتَكُمْ هَذِهِ جُعِلَ عَافِيَتُهَا فِي أَوَّلِهَا وَسَيُصِيبُ آخِرَهَا بَلاَءٌ وَأُمُورٌ تُنْكِرُونَهَا وَتَجِيءُ فِتْنَةٌ فَيُرَقِّقُ بَعْضُهَا بَعْضًا وَتَجِيءُ الْفِتْنَةُ فَيَقُولُ الْمُؤْمِنُ هَذِهِ مُهْلِكَتِي. ثُمَّ تَنْكَشِفُ وَتَجِيءُ الْفِتْنَةُ فَيَقُولُ الْمُؤْمِنُ هَذِهِ هَذِهِ. فَمَنْ أَحَبَّ أَنْ يُزَحْزَحَ عَنِ النَّارِ وَيَدْخُلَ الْجَنَّةَ فَلْتَأْتِهِ مَنِيَّتُهُ وَهُوَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ وَلْيَأْتِ إِلَى النَّاسِ الَّذِي يُحِبُّ أَنْ يُؤْتَى إِلَيْهِ وَمَنْ بَايَعَ إِمَامًا فَأَعْطَاهُ صَفْقَةَ يَدِهِ وَثَمَرَةَ قَلْبِهِ فَلْيُطِعْهُ إِنِ اسْتَطَاعَ فَإِنْ جَاءَ آخَرُ يُنَازِعُهُ فَاضْرِبُوا عُنُقَ الآخَرِ. فَدَنَوْتُ مِنْهُ فَقُلْتُ لَهُ أَنْشُدُكَ اللَّهَ آنْتَ سَمِعْتَ هَذَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَهْوَى إِلَى أُذُنَيْهِ وَقَلْبِهِ بِيَدَيْهِ وَقَالَ سَمِعَتْهُ أُذُنَاىَ وَوَعَاهُ قَلْبِي. فَقُلْتُ لَهُ هَذَا ابْنُ عَمِّكَ مُعَاوِيَةُ يَأْمُرُنَا أَنْ نَأْكُلَ أَمْوَالَنَا بَيْنَنَا بِالْبَاطِلِ وَنَقْتُلَ أَنْفُسَنَا وَاللَّهُ يَقُولُ ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لاَ تَأْكُلُوا أَمْوَالَكُمْ بَيْنَكُمْ بِالْبَاطِلِ إِلاَّ أَنْ تَكُونَ تِجَارَةً عَنْ تَرَاضٍ مِنْكُمْ وَلاَ تَقْتُلُوا أَنْفُسَكُمْ إِنَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا﴾ [سورة النساء: 29]} قَالَ فَسَكَتَ سَاعَةً ثُمَّ قَالَ أَطِعْهُ فِي طَاعَةِ اللَّهِ وَاعْصِهِ فِي مَعْصِيَةِ اللَّهِ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1844: 46) من طريق جرير، عن الأعمش، عن زيد بن وهب، عن عبد الرحمن بن عبد رب الكعبة قال: فذكره.","grade":"صحيح","chapter_ar":"باب الأمر بقتل من خرج على الإمام وجماعة المسلمين","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1844:46).","chapter_en":"The Command to Kill Whoever Rebels Against the Leader and the Community of Muslims","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":27,"content":{"translation":{"en":["ʿAbd al-Rahman ibn ʿAbd Rabb al-Kaʿbah said: I entered the mosque and saw ʿAbdullah ibn ʿAmr ibn al-ʿAs sitting in the shade of the Kaʿbah, with people gathered around him. I came to them and sat with him, and he said: We were with the Messenger of Allah ﷺ on a journey, and we stopped at a place. Some of us were repairing their tents, some were practicing archery, and some were with their grazing animals, when the caller of the Messenger of Allah ﷺ called out: “The prayer is gathering.” So we gathered to the Messenger of Allah ﷺ, and he said: “There was no prophet before me except that it was a duty upon him to guide his nation to the best of what he knew for them, and to warn them of the worst of what he knew for them. The well-being of this nation of yours has been placed in its beginning, and its end will be struck by affliction and matters you will reject. A trial will come, and each one will make the one before it seem small. A trial will come and the believer will say: ‘This is my destruction,’ then it will be removed. Another trial will come and the believer will say: ‘This, this.’ So whoever loves to be moved away from the Fire and admitted into Paradise, let his death come to him while he believes in Allah and the Last Day, and let him treat people as he would love to be treated. Whoever pledges allegiance to a leader, giving him the clasp of his hand and the fruit of his heart, let him obey him if he is able. If another comes to dispute with him, strike the neck of the latter.” I came close to him and said: “I ask you by Allah, did you hear this from the Messenger of Allah ﷺ?” He pointed with his hands to his ears and his heart and said: “My ears heard it and my heart retained it.” I said to him: “This cousin of yours, Muʿawiyah, commands us to consume our wealth among ourselves falsely and to kill ourselves, while Allah says: ‘O you who believe, do not consume your wealth among yourselves falsely, except that it be trade by mutual consent among you, and do not kill yourselves. Indeed, Allah is Merciful to you.’” [Women: 29] He remained silent for a while, then said: “Obey him in obedience to Allah, and disobey him in disobedience to Allah.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1844,"lafz":true}],"full":1},{"num":7678,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا بُويِعَ لِخَلِيفَتَيْنِ فَاقْتُلُوا الآخَرَ مِنْهُمَا."],"takhrij":"صحيح: رواه مسلم في الإمارة (1853) عن وهب بن بقية الواسطي حدثنا خالد بن عبد الله عن الجريري، عن أبي نضرة، عن أبي سعيد الخدري فذكره.","grade":"صحيح","chapter_ar":"باب الأمر بقتل من خرج على الإمام وجماعة المسلمين","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1853).","chapter_en":"The Command to Kill Whoever Rebels Against the Leader and the Community of Muslims","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":27,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: The Messenger of Allah ﷺ said: “If allegiance is pledged to two caliphs, then kill the latter of them.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1853,"lafz":true}],"full":1},{"num":7679,"demo":false,"sanad":"","matn":["قَالَ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ إِذَا حَدَّثْتُكُمْ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَدِيثًا فَوَاللَّهِ، لأَنْ أَخِرَّ مِنَ السَّمَاءِ أَحَبُّ إِلَىَّ مِنْ أَنْ أَكْذِبَ عَلَيْهِ، وَإِذَا حَدَّثْتُكُمْ فِيمَا بَيْنِي وَبَيْنَكُمْ فَإِنَّ الْحَرْبَ خَدْعَةٌ، وَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ سَيَخْرُجُ قَوْمٌ فِي آخِرِ الزَّمَانِ، حُدَّاثُ الأَسْنَانِ، سُفَهَاءُ الأَحْلاَمِ، يَقُولُونَ مِنْ خَيْرِ قَوْلِ الْبَرِيَّةِ، لاَ يُجَاوِزُ إِيمَانُهُمْ حَنَاجِرَهُمْ، يَمْرُقُونَ مِنَ الدِّينِ كَمَا يَمْرُقُ السَّهْمُ مِنَ الرَّمِيَّةِ، فَأَيْنَمَا لَقِيتُمُوهُمْ فَاقْتُلُوهُمْ، فَإِنَّ فِي قَتْلِهِمْ أَجْرًا لِمَنْ قَتَلَهُمْ يَوْمَ الْقِيَامَةِ."],"takhrij":"متفق عليه: رواه البخاري في استتابة المرتدين (6930)، ومسلم في الزكاة (1066: 154) كلاهما من طريق الأعمش، حدثنا خيثمة، حدثنا سويد بن غفلة، قال علي فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في قتال الخوارج","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6930) and Muslim (1066:154).","chapter_en":"What Has Been Reported Concerning Fighting the Kharijites","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["ʿAli ibn Abi Talib said: When I narrate a hadith to you from the Messenger of Allah ﷺ, then by Allah, falling from the sky is dearer to me than lying about him. But when I speak to you concerning matters between me and you, then war is strategy. I heard the Messenger of Allah ﷺ say: “A people will emerge at the end of time, young in age and foolish in understanding. They will speak with the best speech of creation, but their faith will not pass beyond their throats. They will pass out of the religion as an arrow passes through the prey. Wherever you meet them, kill them, for in killing them there is reward on the Day of Resurrection for whoever kills them.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6930,"lafz":true},{"key":"muslim","label":"مسلم","number":1066}],"full":1},{"num":7680,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، قَالَ بَيْنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْسِمُ جَاءَ عَبْدُ اللَّهِ بْنُ ذِي الْخُوَيْصِرَةِ التَّمِيمِيُّ فَقَالَ اعْدِلْ يَا رَسُولَ اللَّهِ. فَقَالَ وَيْلَكَ مَنْ يَعْدِلُ إِذَا لَمْ أَعْدِلْ. قَالَ عُمَرُ بْنُ الْخَطَّابِ دَعْنِي أَضْرِبْ عُنُقَهُ. قَالَ دَعْهُ فَإِنَّ لَهُ أَصْحَابًا يَحْقِرُ أَحَدُكُمْ صَلاَتَهُ مَعَ صَلاَتِهِ، وَصِيَامَهُ مَعَ صِيَامِهِ، يَمْرُقُونَ مِنَ الدِّينِ كَمَا يَمْرُقُ السَّهْمُ مِنَ الرَّمِيَّةِ، يُنْظَرُ فِي قُذَذِهِ فَلاَ يُوجَدُ فِيهِ شَىْءٌ، يُنْظَرُ فِي نَصْلِهِ فَلاَ يُوجَدُ فِيهِ شَىْءٌ، ثُمَّ يُنْظَرُ فِي رِصَافِهِ فَلاَ يُوجَدُ فِيهِ شَىْءٌ، ثُمَّ يُنْظَرُ فِي نَضِيِّهِ فَلاَ يُوجَدُ فِيهِ شَىْءٌ، قَدْ سَبَقَ الْفَرْثَ وَالدَّمَ، آيَتُهُمْ رَجُلٌ إِحْدَى يَدَيْهِ ـ أَوْ قَالَ ثَدْيَيْهِ ـ مِثْلُ ثَدْىِ الْمَرْأَةِ ـ أَوْ قَالَ مِثْلُ الْبَضْعَةِ ـ تَدَرْدَرُ، يَخْرُجُونَ عَلَى حِينِ فُرْقَةٍ مِنَ النَّاسِ.","قال أبو سعيد: أشهد سمعت من النبي صلى الله عليه وسلم وأشهد أن عليا قتلهم وأنا معه جيء بالرجل على النعت الـذي نعتـه النبي صلى الله عليه وسلم قال فنزلت فيه: ﴿وَمِنْهُمْ مَنْ يَلْمِزُكَ فِي الصَّدَقَاتِ﴾ [التوبة: 58]"],"takhrij":"متفق عليه: رواه البخاري في استتابة المرتدين (6933)، ومسلم في الزكاة (1064: 148) كلاهما من حديث الزهري، عن أبي سلمة، عن أبي سعيد فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في قتال الخوارج","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6933) and Muslim (1064:148). The wording is from al-Bukhari.","chapter_en":"What Has Been Reported Concerning Fighting the Kharijites","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: While the Prophet ﷺ was distributing, ʿAbdullah ibn Dhi al-Khuwaysirah al-Tamimi came and said: “Be just, Messenger of Allah.” He said: “Woe to you! Who will be just if I am not just?” ʿUmar ibn al-Khattab said: “Let me strike his neck.” He said: “Leave him, for he will have companions. One of you would consider his prayer insignificant compared to their prayer, and his fasting compared to their fasting. They will pass out of the religion as an arrow passes through the prey. One looks at its feathers and finds nothing on them, then looks at its iron head and finds nothing on it, then looks at its binding and finds nothing on it, then looks at its shaft and finds nothing on it; it has passed through dung and blood. Their sign is a man whose one hand — or he said: one breast — is like a woman’s breast, or like a piece of flesh, moving loosely. They will emerge at a time of division among the people.” Abu Saʿid said: I testify that I heard this from the Prophet ﷺ, and I testify that ʿAli killed them while I was with him, and the man was brought according to the description that the Prophet ﷺ had given. He said: Then this was revealed about him: “And among them are those who criticize you concerning the charities.” [Repentance: 58]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6933,"lafz":true},{"key":"muslim","label":"مسلم","number":1064}],"full":1},{"num":7681,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ بَعَثَ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِذُهَيْبَةٍ فَقَسَمَهَا بَيْنَ الأَرْبَعَةِ الأَقْرَعِ بْنِ حَابِسٍ الْحَنْظَلِيِّ ثُمَّ الْمُجَاشِعِيِّ، وَعُيَيْنَةَ بْنِ بَدْرٍ الْفَزَارِيِّ، وَزَيْدٍ الطَّائِيِّ ثُمَّ أَحَدِ بَنِي نَبْهَانَ، وَعَلْقَمَةَ بْنِ عُلاَثَةَ الْعَامِرِيِّ ثُمَّ أَحَدِ بَنِي كِلاَبٍ، فَغَضِبَتْ قُرَيْشٌ وَالأَنْصَارُ، قَالُوا يُعْطِي صَنَادِيدَ أَهْلِ نَجْدٍ وَيَدَعُنَا. قَالَ إِنَّمَا أَتَأَلَّفُهُمْ. فَأَقْبَلَ رَجُلٌ غَائِرُ الْعَيْنَيْنِ مُشْرِفُ الْوَجْنَتَيْنِ، نَاتِئُ الْجَبِينِ، كَثُّ اللِّحْيَةِ، مَحْلُوقٌ فَقَالَ اتَّقِ اللَّهَ يَا مُحَمَّدُ. فَقَالَ مَنْ يُطِعِ اللَّهَ إِذَا عَصَيْتُ، أَيَأْمَنُنِي اللَّهُ عَلَى أَهْلِ الأَرْضِ فَلاَ تَأْمَنُونِي. فَسَأَلَهُ رَجُلٌ قَتْلَهُ ـ أَحْسِبُهُ خَالِدَ بْنَ الْوَلِيدِ ـ فَمَنَعَهُ، فَلَمَّا وَلَّى قَالَ إِنَّ مِنْ ضِئْضِئِ هَذَا ـ أَوْ فِي عَقِبِ هَذَا ـ قَوْمٌ يَقْرَءُونَ الْقُرْآنَ، لاَ يُجَاوِزُ حَنَاجِرَهُمْ، يَمْرُقُونَ مِنَ الدِّينِ مُرُوقَ السَّهْمِ مِنَ الرَّمِيَّةِ، يَقْتُلُونَ أَهْلَ الإِسْلاَمِ، وَيَدَعُونَ أَهْلَ الأَوْثَانِ، لَئِنْ أَنَا أَدْرَكْتُهُمْ لأَقْتُلَنَّهُمْ قَتْلَ عَادٍ."],"takhrij":"متفق عليه: رواه البخاري في الأنبياء (3344)، ومسلم في الزكاة (1064: 143) كلاهما من طريق سعيد بن مسروق، عن عبد الرحمن بن أبي نعم، عن أبي سعيد الخدري قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في قتال الخوارج","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3344) and Muslim (1064:143).","chapter_en":"What Has Been Reported Concerning Fighting the Kharijites","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: ʿAli sent a small piece of gold to the Prophet ﷺ, so he distributed it among four people: al-Aqraʿ ibn Habis al-Hanzali, then al-Mujashiʿi; ʿUyaynah ibn Badr al-Fazari; Zayd al-Ta’i, then one of Banu Nabhan; and ʿAlqamah ibn ʿUlathah al-ʿAmiri, then one of Banu Kilab. Quraysh and the Ansar became angry and said: “He gives to the chiefs of the people of Najd and leaves us!” He said: “I am only reconciling their hearts.” Then a man came forward with sunken eyes, prominent cheeks, a protruding forehead, a thick beard, and a shaved head. He said: “Fear Allah, Muhammad!” He said: “Who would obey Allah if I disobeyed Him? Allah has entrusted me over the people of the earth, yet you do not trust me?” A man asked permission to kill him — I think it was Khalid ibn al-Walid — but he prevented him. When the man turned away, he said: “From the offspring of this man, or from those who come after him, will be a people who recite the Qur’an but it will not pass beyond their throats. They will pass out of the religion as an arrow passes through the prey. They will kill the people of Islam and leave the people of idols. If I reach them, I will surely kill them with the killing of ʿAd.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3344,"lafz":true},{"key":"muslim","label":"مسلم","number":1064}],"full":1},{"num":7682,"demo":false,"sanad":"","matn":["عن زَيْدِ بن وَهْبٍ الجهني أَنَّهُ كَانَ فِي الْجَيْشِ الَّذِينَ كَانُوا مَعَ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ الَّذِينَ سَارُوا إِلَى الْخَوَارِجِ فَقَالَ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ أَيُّهَا النَّاسُ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ يَخْرُجُ قَوْمٌ مِنْ أُمَّتِي يَقْرَءُونَ الْقُرْآنَ لَيْسَ قِرَاءَتُكُمْ إِلَى قِرَاءَتِهِمْ بِشَىْءٍ وَلاَ صَلاَتُكُمْ إِلَى صَلاَتِهِمْ بِشَىْءٍ وَلاَ صِيَامُكُمْ إِلَى صِيَامِهِمْ بِشَىْءٍ يَقْرَءُونَ الْقُرْآنَ يَحْسِبُونَ أَنَّهُ لَهُمْ وَهُوَ عَلَيْهِمْ لاَ تُجَاوِزُ صَلاَتُهُمْ تَرَاقِيَهُمْ يَمْرُقُونَ مِنَ الإِسْلاَمِ كَمَا يَمْرُقُ السَّهْمُ مِنَ الرَّمِيَّةِ. لَوْ يَعْلَمُ الْجَيْشُ الَّذِينَ يُصِيبُونَهُمْ مَا قُضِيَ لَهُمْ عَلَى لِسَانِ نَبِيِّهِمْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَتَّكَلُوا عَنِ الْعَمَلِ وَآيَةُ ذَلِكَ أَنَّ فِيهِمْ رَجُلاً لَهُ عَضُدٌ وَلَيْسَ لَهُ ذِرَاعٌ عَلَى رَأْسِ عَضُدِهِ مِثْلُ حَلَمَةِ الثَّدْىِ عَلَيْهِ شَعَرَاتٌ بِيضٌ فَتَذْهَبُونَ إِلَى مُعَاوِيَةَ وَأَهْلِ الشَّامِ وَتَتْرُكُونَ هَؤُلاَءِ يَخْلُفُونَكُمْ فِي ذَرَارِيِّكُمْ وَأَمْوَالِكُمْ وَاللَّهِ إِنِّي لأَرْجُو أَنْ يَكُونُوا هَؤُلاَءِ الْقَوْمَ فَإِنَّهُمْ قَدْ سَفَكُوا الدَّمَ الْحَرَامَ وَأَغَارُوا فِي سَرْحِ النَّاسِ فَسِيرُوا عَلَى اسْمِ اللَّهِ.","قال سلمة بن كهيل: فنزلني زيد بن وهب منزلا حتى قال: مررنا على قنطرة فلما التقينا، وعلى الخوارج يومئذ عبد الله بن وهب الراسبي فقال لهم: ألقوا الرماح، وسلوا سيوفكم من جفونها، فإني أخاف أن يناشدوكم كما ناشدوكم يوم حروراء فرجعوا، فوحشوا برماحهم وسلوا السيوف، وشجرهم الناس برماحهم قال: وقتل بعضهم على بعض، وما أصيب من الناس يومئذ إلا رجلان فقال عليرضي الله عنه: التمسوا فيهم المخدج فالتمسوه، فلم يجدوه فقام علي رضي الله عنه بنفسه حتى أتى ناسا قد قتل بعضهم على بعض قال: أخروهم، فوجدوه مما يلي الأرض فكبر ثم قال: صدق الله وبلغ رسوله قال: فقام إليه عبيدة السلماني فقال: يا أمير المؤمنين! الله الذي لا إله إلا هو لسمعت هذا الحديث من رسول الله صلى الله عليه وسلم؟ فقال: إي والله الذي لا إله إلا هو حتى استحلفه ثلاثا وهو يحلف له."],"takhrij":"صحيح: رواه مسلم في الزكاة (1066: 156) عن عبد بن حميد، حدثنا عبد الرزاق بن همام، حدثنا عبد الملك بن أبي سليمان، حدثنا سلمة بن كهيل، حدثني زيد بن وهب قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في قتال الخوارج","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1066:156).","chapter_en":"What Has Been Reported Concerning Fighting the Kharijites","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["Zayd ibn Wahb al-Juhani was in the army that was with ʿAli, may Allah be pleased with him, which marched against the Kharijites. ʿAli, may Allah be pleased with him, said: “People, I heard the Messenger of Allah ﷺ say: ‘A people will emerge from my nation who recite the Qur’an. Your recitation will be nothing compared to their recitation, your prayer will be nothing compared to their prayer, and your fasting will be nothing compared to their fasting. They recite the Qur’an thinking it is for them, while it is against them. Their prayer will not pass beyond their collarbones. They will pass out of Islam as an arrow passes through the prey.’ If the army who strikes them knew what had been decreed for them upon the tongue of their Prophet ﷺ, they would rely upon that and abandon work. The sign of that is that among them is a man who has an upper arm but no forearm; at the end of his upper arm is something like the nipple of a breast, with white hairs upon it. Will you go to Muʿawiyah and the people of Syria and leave these people behind you among your children and wealth? By Allah, I hope that these are those people, for they have shed inviolable blood and raided the people’s grazing animals. So march in the name of Allah.” Salamah ibn Kuhayl said: Zayd ibn Wahb described the places to me until he said: We passed over a bridge. When we met, the Kharijites that day were led by ʿAbdullah ibn Wahb al-Rasibi. He said to them: “Throw down the spears and draw your swords from their sheaths, for I fear that they will appeal to you as they appealed to you on the day of Harura’.” So they returned, cast aside their spears, and drew their swords. The people thrust at them with spears. He said: They were killed one upon another, and only two of the people were injured that day. ʿAli, may Allah be pleased with him, said: “Search among them for the defective one.” They searched but did not find him. Then ʿAli himself stood up and came to people who had been killed piled upon one another. He said: “Move them back.” They found him beneath them, so he proclaimed greatness and said: “Allah spoke the truth, and His Messenger conveyed.” Then ʿUbaydah al-Salmani stood and said: “Commander of the believers, by Allah, besides whom there is no deity, did you truly hear this hadith from the Messenger of Allah ﷺ?” He said: “Yes, by Allah, besides whom there is no deity.” He made him swear three times, and he swore to him."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1066,"lafz":true,"n":2467}],"full":1},{"num":7683,"demo":false,"sanad":"","matn":["عن محمد بن جُبَيْرٍ بْنِ مُطْعِمٍ يُحَدِّثُ أَنَّهُ بَلَغَ مُعَاوِيَةَ وَهْوَ عِنْدَهُ فِي وَفْدٍ مِنْ قُرَيْشٍ أَنَّ عَبْدَ اللَّهِ بْنَ عَمْرٍو يُحَدِّثُ أَنَّهُ سَيَكُونُ مَلِكٌ مِنْ قَحْطَانَ فَغَضِبَ، فَقَامَ فَأَثْنَى عَلَى اللَّهِ بِمَا هُوَ أَهْلُهُ، ثُمَّ قَالَ أَمَّا بَعْدُ فَإِنَّهُ بَلَغَنِي أَنَّ رِجَالاً مِنْكُمْ يُحَدِّثُونَ أَحَادِيثَ لَيْسَتْ فِي كِتَابِ اللَّهِ، وَلاَ تُؤْثَرُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأُولَئِكَ جُهَّالُكُمْ، فَإِيَّاكُمْ وَالأَمَانِيَّ الَّتِي تُضِلُّ أَهْلَهَا، فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ إِنَّ هَذَا الأَمْرَ فِي قُرَيْشٍ، لاَ يُعَادِيهِمْ أَحَدٌ إِلاَّ كَبَّهُ اللَّهُ عَلَى وَجْهِهِ مَا أَقَامُوا الدِّينَ."],"takhrij":"صحيح: رواه البخاري في الأحكام (7139) عن أبي اليمان، أخبرنا شعيب، عن الزهري، قال: كان محمد بن جبير بن مطعم يحدث فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في خلافة قريش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7139).","chapter_en":"What Has Been Reported Concerning the Caliphate of Quraysh","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Muhammad ibn Jubayr ibn Mutʿim narrated that it reached Muʿawiyah, while he was with him in a delegation from Quraysh, that ʿAbdullah ibn ʿAmr was narrating that there would be a king from Qahtan. So he became angry, stood up, praised Allah as He deserves, then said: “As for what follows: It has reached me that some men among you narrate reports that are not in the Book of Allah and are not transmitted from the Messenger of Allah ﷺ. Those are your ignorant ones. Beware of hopes that mislead their people, for I heard the Messenger of Allah ﷺ say: ‘This affair is among Quraysh. No one opposes them except that Allah will throw him into the Fire upon his face, so long as they establish the religion.’”"]},"buhuth":{"en":["There is no disagreement among the scholars of the people of the Prophetic way and the Muslim community that the supreme leader — meaning the ruler over all Islamic lands — is required to be from Quraysh. However, the legal texts indicate that this required preference for them in leadership is conditional upon their establishing the religion and obeying Allah and His Messenger. If they oppose the command of Allah, then giving precedence to others who obey Allah the Exalted, implement His commands, and establish His prescribed limits is more appropriate.","The proof for this is his statement ﷺ: “so long as they establish the religion,” because the expression “so long as” is a time-related qualifier attached to his statement: “This affair is among Quraysh.” The meaning is: this affair remains in Quraysh for the duration that they establish the religion. Its implication is that if they do not establish the religion, then it is not for them."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7139,"lafz":true}],"full":1,"dr":1},{"num":7684,"demo":false,"sanad":"","matn":["عن مُعَاوِيَةَ قَالَ: قَالَ: وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: النَّاسُ تَبَعٌ لِقُرَيْشٍ فِي هَذَا الْأَمْرِ، خِيَارُهُمْ فِي الْجَاهِلِيَّةِ خِيَارُهُمْ فِي الْإِسْلَامِ إِذَا فَقِهُوا، وَاللهِ لَوْلَا أَنْ تَبْطَرَ قُرَيْشٌ لَأَخْبَرْتُهَا مَا لِخِيَارِهَا عِنْدَ اللَّهِ عَزَّ."],"takhrij":"صحيح: رواه أحمد (16927)، وابن أبي شيبة (33054) كلاهما عن أبي نعيم الفضل بن دكين، حدثنا عبد الله بن مبشر مولى أم حبيبة، عن زيد بن أبي عتاب، عن معاوية فذكره. وعند ابن أبي شيبة: قام معاوية على المنبر فقال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في خلافة قريش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (16927) and Ibn Abi Shaybah (33054).","chapter_en":"What Has Been Reported Concerning the Caliphate of Quraysh","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Muʿawiyah said: The Messenger of Allah ﷺ said: “People follow Quraysh in this affair. The best of them in the age of ignorance are the best of them in Islam when they gain understanding. By Allah, were it not that Quraysh might become arrogant, I would have informed them of what their best have with Allah, Mighty and Majestic.”"]}},"tuhfa":{},"refs":[{"key":"sh9944","label":"ابن أبي شيبة","number":33054},{"key":"ahmad","label":"مسند الإمام أحمد","number":16928,"n":16928},{"key":"sh9944","label":"المصنف لابن أبي شيبة","number":32387,"n":32369},{"key":"ahmad","label":"احمد","number":16927,"lafz":true,"n":16928}],"full":1,"dr":1},{"num":7685,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ النَّاسُ تَبَعٌ لِقُرَيْشٍ فِي هَذَا الشَّأْنِ، مُسْلِمُهُمْ تَبَعٌ لِمُسْلِمِهِمْ، وَكَافِرُهُمْ تَبَعٌ لِكَافِرِهِمْ."],"takhrij":"متفق عليه: رواه البخاري في المناقب (3495)، ومسلم في الإمارة (1818) كلاهما من طريق قتيبة بن سعيد، حدثنا المغيرة الحزامي، عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في خلافة قريش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3495) and Muslim (1818).","chapter_en":"What Has Been Reported Concerning the Caliphate of Quraysh","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said: “People follow Quraysh in this matter; their Muslims follow their Muslims, and their disbelievers follow their disbelievers.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3495,"lafz":true},{"key":"muslim","label":"مسلم","number":1818,"n":4702}],"full":1},{"num":7686,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ لِي عَلَى قُرَيْشٍ حَقًّا، وَإِنَّ لِقُرَيْشٍ عَلَيْكُمْ حَقًّا مَا حَكَمُوا وَعَدَلُوا، وَائْتُمِنُوا فَأَدُّوا، وَاسْتُرْحِمُوا فَرَحِمُوا، فَمَنْ لَمْ يَفْعَلْ مِنْهُمْ فَعَلَيْهِ لَعْنَةُ اللَّهِ."],"takhrij":"صحيح: رواه أحمد (7653) عن عبد الرزاق – وهو في مصنفه (19902) واللفظ له-، وصحّحه ابن حبان (4581) عن معمر، عن ابن أبي ذئب، عن سعيد المقبري، عن أبي هريرة فذكره. ولم يذكر أحمد قوله: \"فمن لم يفعل ذلك فعليه لعنة الله\".","grade":"صحيح","chapter_ar":"باب ما جاء في خلافة قريش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (7653) from ʿAbd al-Razzaq — and it is in his Musannaf (19902), with this wording — and graded authentic by Ibn Hibban (4581).","chapter_en":"What Has Been Reported Concerning the Caliphate of Quraysh","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “I have a right over Quraysh, and Quraysh has a right over you, so long as when they rule, they act justly; when they are entrusted, they fulfill the trust; and when mercy is sought from them, they show mercy. Whoever does not do that, upon him is the curse of Allah.”"]}},"tuhfa":{},"refs":[{"key":"abdrazzaq","label":"عن عبد الرزاق — وهو في مصنفه","number":19902},{"key":"ibnhibban","label":"اللفظ له — وصححه ابن حبان","number":4581},{"key":"ahmad","label":"مسند الإمام أحمد","number":7653,"n":7653,"lafz":true},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":5013,"n":5009}],"full":1,"dr":1},{"num":7687,"demo":false,"sanad":"","matn":["عن ابْنِ عُمَرَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ يَزَالُ الأَمْرُ فِي قُرَيْشٍ مَا بَقِيَ مِنْهُمُ اثْنَانِ."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7140)، ومسلم في الإمارة (1820) كلاهما عن أحمد بن عبد الله بن يونس حدثنا عاصم بن محمد بن زيد، سمعت أبي يقول: قال ابن عمر: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في خلافة قريش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7140) and Muslim (1820).","chapter_en":"What Has Been Reported Concerning the Caliphate of Quraysh","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ said: “This affair will remain among Quraysh as long as two of them remain.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7140,"lafz":true},{"key":"muslim","label":"مسلم","number":1820}],"full":1,"dr":1},{"num":7688,"demo":false,"sanad":"","matn":["عَنْ جابر بْنِ عبدالله قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : النَّاسُ تَبَعٌ لِقُرَيْشٍ فِي الْخَيْرِ وَالشَّرِّ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1819) عن يحيى بن حبيب الحارثي، حدثنا روح، حدثنا ابن جريج، حدثني أبو الزبير، عن جابر قال فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في خلافة قريش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1819).","chapter_en":"What Has Been Reported Concerning the Caliphate of Quraysh","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: The Prophet ﷺ said: “People follow Quraysh in good and in evil.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1819,"lafz":true}],"full":1},{"num":7689,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ، قَالَ سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ لاَ يَزَالُ أَمْرُ النَّاسِ مَاضِيًا مَا وَلِيَهُمُ اثْنَا عَشَرَ رَجُلاً. ثُمَّ تَكَلَّمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِكَلِمَةٍ خَفِيَتْ عَلَىَّ فَسَأَلْتُ أَبِي مَاذَا قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ كُلُّهُمْ مِنْ قُرَيْشٍ."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (722، 7223)، ومسلم في الإمارة (1821: 6) كلاهما من حديث عبد الملك بن عمير، عن جابر بن سمرة قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في خلافة قريش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7222, 7223) and Muslim (1821:6). The wording is from Muslim. Muslim also narrated it through another route with the wording: “This religion will remain mighty and protected until there have been twelve caliphs.”","chapter_en":"What Has Been Reported Concerning the Caliphate of Quraysh","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Jabir ibn Samurah said: I heard the Prophet ﷺ say: “The affair of the people will continue to proceed as long as twelve men rule them.” Then the Prophet ﷺ said a word that was unclear to me, so I asked my father: “What did the Messenger of Allah ﷺ say?” He said: “All of them are from Quraysh.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7222,"lafz":true},{"key":"muslim","label":"مسلم","number":1821,"n":4706},{"key":"bukhari","label":"البخاري في الاحكام","number":722},{"key":"bukhari","label":"البخاري في الاحكام","number":7223}],"full":1,"dr":1},{"num":7690,"demo":false,"sanad":"","matn":["عَنْ عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ، قَالَ كَتَبْتُ إِلَى جَابِرِ بْنِ سَمُرَةَ مَعَ غُلاَمِي نَافِعٍ أَنْ أَخْبِرْنِي بِشَىْءٍ، سَمِعْتَهُ مِنْ، رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ فَكَتَبَ إِلَىَّ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ جُمُعَةٍ عَشِيَّةَ رُجِمَ الأَسْلَمِيُّ يَقُولُ لاَ يَزَالُ الدِّينُ قَائِمًا حَتَّى تَقُومَ السَّاعَةُ أَوْ يَكُونَ عَلَيْكُمُ اثْنَا عَشَرَ خَلِيفَةً كُلُّهُمْ مِنْ قُرَيْشٍ. وَسَمِعْتُهُ يَقُولُ عُصَيْبَةٌ مِنَ الْمُسْلِمِينَ يَفْتَتِحُونَ الْبَيْتَ الأَبْيَضَ بَيْتَ كِسْرَى أَوْ آلِ كِسْرَى. وَسَمِعْتُهُ يَقُولُ إِنَّ بَيْنَ يَدَىِ السَّاعَةِ كَذَّابِينَ فَاحْذَرُوهُمْ. وَسَمِعْتُهُ يَقُولُ إِذَا أَعْطَى اللَّهُ أَحَدَكُمْ خَيْرًا فَلْيَبْدَأْ بِنَفْسِهِ وَأَهْلِ بَيْتِهِ. وَسَمِعْتُهُ يَقُولُ أَنَا الْفَرَطُ عَلَى الْحَوْضِ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1822: 10) من طريق حاتم بن إسماعيل عن المهاجر بن مسمار، عن عامر بن سعد بن أبي وقاص قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في خلافة قريش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1822:10).","chapter_en":"What Has Been Reported Concerning the Caliphate of Quraysh","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["ʿAmir ibn Saʿd ibn Abi Waqqas said: I wrote to Jabir ibn Samurah through my servant Nafiʿ, saying: “Inform me of something you heard from the Messenger of Allah ﷺ.” He wrote back to me: “I heard the Messenger of Allah ﷺ on a Friday, on the evening when the Aslami man was stoned, saying: ‘The religion will remain established until the Hour comes, or until there have been over you twelve caliphs, all of them from Quraysh.’ I also heard him say: ‘A small group of Muslims will conquer the White House, the house of Chosroes or the family of Chosroes.’ I heard him say: ‘Before the Hour there will be liars, so beware of them.’ I heard him say: ‘When Allah gives one of you good, let him begin with himself and his household.’ And I heard him say: ‘I will be the one who reaches the Basin before you.’”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1822,"lafz":true}],"full":1},{"num":7691,"demo":false,"sanad":"","matn":["عَنِ النُّعْمَانِ بْنِ بَشِيرٍ، قَالَ: كُنَّا قُعُودًا فِي الْمَسْجِدِ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ بَشِيرٌ رَجُلًا يَكُفُّ حَدِيثَهُ، فَجَاءَ أَبُو ثَعْلَبَةَ الْخُشَنِيُّ، فَقَالَ: يَا بَشِيرُ بْنَ سَعْدٍ أَتَحْفَظُ حَدِيثَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فِي الْأُمَرَاءِ؟ فَقَالَ حُذَيْفَةُ: أَنَا أَحْفَظُ خُطْبَتَهُ، فَجَلَسَ أَبُو ثَعْلَبَةَ، فَقَالَ حُذَيْفَةُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَكُونُ النُّبُوَّةُ فِيكُمْ مَا شَاءَ اللَّهُ أَنْ تَكُونَ، ثُمَّ يَرْفَعُهَا إِذَا شَاءَ أَنْ يَرْفَعَهَا، ثُمَّ تَكُونُ خِلَافَةٌ عَلَى مِنْهَاجِ النُّبُوَّةِ، فَتَكُونُ مَا شَاءَ اللَّهُ أَنْ تَكُونَ، ثُمَّ يَرْفَعُهَا إِذَا شَاءَ اللَّهُ أَنْ يَرْفَعَهَا، ثُمَّ تَكُونُ مُلْكًا عَاضًّا، فَيَكُونُ مَا شَاءَ اللَّهُ أَنْ يَكُونَ، ثُمَّ يَرْفَعُهَا إِذَا شَاءَ أَنْ يَرْفَعَهَا، ثُمَّ تَكُونُ مُلْكًا جَبْرِيَّةً، فَتَكُونُ مَا شَاءَ اللَّهُ أَنْ تَكُونَ، ثُمَّ يَرْفَعُهَا إِذَا شَاءَ أَنْ يَرْفَعَهَا، ثُمَّ تَكُونُ خِلَافَةً عَلَى مِنْهَاجِ نُبُوَّةٍ ثُمَّ سَكَتَ.","قال حبيب: فلما قام عمر بن عبد العزيز، وكان يزيد بن النعمان ابن بشير في صحابته، فكتبت إليه بهذا الحديث أذكره إياه، فقلت له: إني أرجو أن يكون أمير المؤمنين -يعني: عمر- بعد الملك العاض والجبرية فأدخل كتابي على عمر بن عبد العزيز، فسر به، وأعجبه."],"takhrij":"حسن: رواه أحمد (18406) عن سليمان بن داود الطيالسي حدثني داود بن إبراهيم الواسطي، حدثني حبيب بن سالم، عن النعمان بن بشير فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في خلافة قريش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (18406).","chapter_en":"What Has Been Reported Concerning the Caliphate of Quraysh","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Al-Nuʿman ibn Bashir said: We were sitting in the mosque with the Messenger of Allah ﷺ, and Bashir was a man who spoke little. Abu Thaʿlabah al-Khushani came and said: “Bashir ibn Saʿd, do you remember the hadith of the Messenger of Allah ﷺ concerning rulers?” Hudhayfah said: “I remember his sermon.” So Abu Thaʿlabah sat down, and Hudhayfah said: The Messenger of Allah ﷺ said: “Prophethood will remain among you for as long as Allah wills it to remain, then He will raise it when He wills to raise it. Then there will be caliphate upon the method of prophethood, and it will remain for as long as Allah wills it to remain, then He will raise it when Allah wills to raise it. Then there will be biting kingship, and it will remain for as long as Allah wills it to remain, then He will raise it when He wills to raise it. Then there will be coercive kingship, and it will remain for as long as Allah wills it to remain, then He will raise it when He wills to raise it. Then there will be caliphate upon the method of prophethood.” Then he became silent. Habib said: When ʿUmar ibn ʿAbd al-ʿAziz became ruler, and Yazid ibn al-Nuʿman ibn Bashir was among his companions, I wrote this hadith to him to remind him of it. I said to him: “I hope that the Commander of the Believers — meaning ʿUmar — is after the biting and coercive kingship.” My letter was brought to ʿUmar ibn ʿAbd al-ʿAziz, and he was pleased with it and admired it."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":18406,"n":18406,"lafz":true}],"full":1,"dr":1},{"num":7692,"demo":false,"sanad":"","matn":["عن أَبِي بَرْزَةَ يرفعه إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْأَئِمَّةُ مِنْ قُرَيْشٍ: إِذَا اسْتُرْحِمُوا رَحِمُوا، وَإِذَا عَاهَدُوا وَفَوْا، وَإِذَا حَكَمُوا عَدَلُوا فَمَنْ لَمْ يَفْعَلْ ذَلِكَ مِنْهُمْ فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ."],"takhrij":"حسن: رواه أحمد (19777) عن سليمان بن داود – هو الطيالسي-حدثنا سكين، حدثنا سيار بن سلامة سمع أبا برزة يرفعه إلى النبي صلى الله عليه وسلم قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في خلافة قريش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (19777).","chapter_en":"What Has Been Reported Concerning the Caliphate of Quraysh","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Abu Barzah traced it back to the Prophet ﷺ, who said: “The leaders are from Quraysh. When mercy is sought from them, they show mercy; when they make a covenant, they fulfill it; and when they judge, they judge justly. Whoever among them does not do that, upon him is the curse of Allah, the angels, and all people.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":19777,"n":19777,"lafz":true}],"full":1,"dr":1},{"num":7693,"demo":false,"sanad":"","matn":["عن الْحَارِثِ بْنِ أَبِي الحارث وَكَثِيرِ بْنِ مُرَّةَ، وَعَمْرِو بْنِ الْأَسْوَدِ، وَأَبِي أُمَامَةَ رَضِيَ اللَّهُ عَنْهُمْ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ خِيَارَ أَئِمَّةِ قُرَيْشٍ خِيَارُ أَئِمَّةِ النَّاسِ."],"takhrij":"حسن: رواه الطبراني في الكبير (8/128)، والبخاري في التاريخ الكبير (2/262) كلاهما من حديث إسماعيل بن عياش، عن ضمضم بن زرعة، عن شريح بن عبيد، عن الحارث بن ألحارث، وكثير بن مرة، وعمرو بن الأسود وأبي أمامة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في خلافة قريش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (8/128) and al-Bukhari in al-Tarikh al-Kabir (2/262).","chapter_en":"What Has Been Reported Concerning the Caliphate of Quraysh","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Al-Harith ibn Abi al-Harith, Kathir ibn Murrah, ʿAmr ibn al-Aswad, and Abu Umamah narrated from the Prophet ﷺ that he said: “The best leaders of Quraysh are the best leaders of the people.”"]}},"tuhfa":{},"refs":[{"key":"mujamkabir","label":"الطبراني في الكبير","number":8,"lafz":true},{"key":"tarikhbukhari","label":"البخاري في التاريخ الكبير","number":2}],"full":1,"dr":1},{"num":7694,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْأُمَرَاءُ مِنْ قُرَيْشٍ مَا عَمِلُوا فِيكُمْ بِثَلَاثٍ: مَا رَحِمُوا إِذَا اسْتُرْحِمُوا، وَأَقْسَطُوا إِذَا قَسَمُوا، وَعَدَلُوا إِذَا حَكَمُوا."],"takhrij":"حسن: رواه الحاكم (4/501) والبيهقي (8/144) كلاهما من حديث الصعق بن حزن، ثنا علي بن الحكم البناني، عن أنس بن مالك رضي الله عنه قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في خلافة قريش","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Hakim (8528) and al-Bayhaqi (8/144).","chapter_en":"What Has Been Reported Concerning the Caliphate of Quraysh","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ said: “The rulers are from Quraysh so long as they act among you according to three things: they show mercy when mercy is sought from them, they are fair when they distribute, and they are just when they judge.”"]}},"tuhfa":{},"refs":[{"key":"kubrabayhaqi","label":"البيهقي","number":8},{"key":"hakim","label":"المستدرك على الصحيحين","number":8528,"n":8537,"lafz":true}],"full":1,"dr":1},{"num":7695,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ جُمْهَانَ، عَنْ سَفِينَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خِلاَفَةُ النُّبُوَّةِ ثَلاَثُونَ سَنَةً ثُمَّ يُؤْتِي اللَّهُ الْمُلْكَ - أَوْ مُلْكَهُ - مَنْ يَشَاءُ.","قال سعيد: قال لي سفينة: أمسك عليك أبو بكر سنتين، وعمر عشرا وعثمان اثنتي عشر، وعلي كذا.","قال سعيد: قلت لسفينة: إن هولاء يزعمون أن عليا لم يكن بخليفة قال: كذبت أستاه بني الزرقاء- يعني بني مروان. هذا لفظ أبي داود.","ولفظ أحمد: قال رسول الله صلى الله عليه وسلم: الخلافة ثلاثون عاما، ثم يكون بعد ذلك الملك. قال سفينة: أمسك خلافة أبي بكر سنتين، وخلافة عمر عشر سنين، وخلافة عثمان اثنتي عشرة سنة، وخلافة علي ست سنين."],"takhrij":"حسن: رواه أبو داود (4646، 4647)، والترمذي (2226)، وأحمد (21919، 21923، 21928)، وصحّحه ابن حبان (6943)، والحاكم (3/71، 145) كلهم من طرق عن سعيد بن جمهان،ـ عن سفينة فذكره. ومنهم من ذكر المرفوع فقط.","grade":"حسن","chapter_ar":"باب خلافة النبوة ثلاثون سنة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4646, 4647), al-Tirmidhi (2226), who graded it good, Ahmad (21919, 21923, 21928), Ibn Hibban (6943), who authenticated it, and al-Hakim (3/71, 145).","chapter_en":"The Prophetic Caliphate Is Thirty Years","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":30,"content":{"translation":{"en":["Saʿid ibn Jumhan narrated from Safinah that the Messenger of Allah ﷺ said: “The Prophetic caliphate will last thirty years, then Allah will give kingship — or His kingship — to whom He wills.” Saʿid said: Safinah said to me: “Count Abu Bakr as two years, ʿUmar as ten, ʿUthman as twelve, and ʿAli as such-and-such.” Saʿid said: I said to Safinah: “These people claim that ʿAli was not a caliph.” He said: “The backsides of the sons of al-Zarqa’ have lied,” meaning the sons of Marwan. This is the wording of Abu Dawud. The wording of Ahmad is: The Messenger of Allah ﷺ said: “The caliphate will be thirty years, then after that there will be kingship.” Safinah said: “Count the caliphate of Abu Bakr as two years, the caliphate of ʿUmar as ten years, the caliphate of ʿUthman as twelve years, and the caliphate of ʿAli as six years.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4646,"lafz":true},{"key":"tirmidhi","label":"الترمذي","number":2226},{"key":"ibnhibban","label":"صححه ابن حبان","number":6943},{"key":"hakim","label":"الحاكم","number":3},{"key":"ahmad","label":"مسند الإمام أحمد","number":21919,"n":21919},{"key":"abudawud","label":"ابو داود","number":4647,"n":4646},{"key":"ahmad","label":"احمد","number":21923},{"key":"ahmad","label":"احمد","number":21928}],"full":1,"dr":1},{"num":7696,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ قِيلَ لِعُمَرَ أَلاَ تَسْتَخْلِفُ قَالَ إِنْ أَسْتَخْلِفْ فَقَدِ اسْتَخْلَفَ مَنْ هُوَ خَيْرٌ مِنِّي أَبُو بَكْرٍ، وَإِنْ أَتْرُكْ فَقَدْ تَرَكَ مَنْ هُوَ خَيْرٌ مِنِّي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَثْنَوْا عَلَيْهِ فَقَالَ رَاغِبٌ رَاهِبٌ، وَدِدْتُ أَنِّي نَجَوْتُ مِنْهَا كَفَافًا لاَ لِي وَلاَ عَلَىَّ لاَ أَتَحَمَّلُهَا حَيًّا وَمَيِّتًا."],"takhrij":"متفق عليه: رواه البخاري في الأحكام (7218)، ومسلم في الإمارة (1823: 11) كلاهما من طريق هشام بن عروة، عن أبيه، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب ليس للاستخلاف طريق خاص","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7218) and Muslim (1823:11).","chapter_en":"There Is No Specific Method for Appointing a Successor","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":31,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: It was said to ʿUmar: “Will you not appoint a successor?” He said: “If I appoint a successor, then one better than me appointed a successor: Abu Bakr. And if I leave it, then one better than me left it: the Messenger of Allah ﷺ.” They praised him, and he said: “One hoping and fearing. I wish that I could escape it evenly, neither for me nor against me. I do not want to bear it alive or dead.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7218,"lafz":true},{"key":"muslim","label":"مسلم","number":1823}],"full":1},{"num":7697,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ دَخَلْتُ عَلَى حَفْصَةَ فَقَالَتْ أَعَلِمْتَ أَنَّ أَبَاكَ غَيْرُ مُسْتَخْلِفٍ قَالَ قُلْتُ مَا كَانَ لِيَفْعَلَ. قَالَتْ إِنَّهُ فَاعِلٌ. قَالَ فَحَلَفْتُ أَنِّي أُكَلِّمُهُ فِي ذَلِكَ فَسَكَتُّ حَتَّى غَدَوْتُ وَلَمْ أُكَلِّمْهُ - قَالَ - فَكُنْتُ كَأَنَّمَا أَحْمِلُ بِيَمِينِي جَبَلاً حَتَّى رَجَعْتُ فَدَخَلْتُ عَلَيْهِ فَسَأَلَنِي عَنْ حَالِ النَّاسِ وَأَنَا أُخْبِرُهُ - قَالَ - ثُمَّ قُلْتُ لَهُ إِنِّي سَمِعْتُ النَّاسَ يَقُولُونَ مَقَالَةً فَآلَيْتُ أَنْ أَقُولَهَا لَكَ زَعَمُوا أَنَّكَ غَيْرُ مُسْتَخْلِفٍ وَإِنَّهُ لَوْ كَانَ لَكَ رَاعِي إِبِلٍ أَوْ رَاعِي غَنَمٍ ثُمَّ جَاءَكَ وَتَرَكَهَا رَأَيْتَ أَنْ قَدْ ضَيَّعَ فَرِعَايَةُ النَّاسِ أَشَدُّ قَالَ فَوَافَقَهُ قَوْلِي فَوَضَعَ رَأْسَهُ سَاعَةً ثُمَّ رَفَعَهُ إِلَىَّ فَقَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ يَحْفَظُ دِينَهُ وَإِنِّي لَئِنْ لاَ أَسْتَخْلِفْ فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَسْتَخْلِفْ وَإِنْ أَسْتَخْلِفْ فَإِنَّ أَبَا بَكْرٍ قَدِ اسْتَخْلَفَ. قَالَ فَوَاللَّهِ مَا هُوَ إِلاَّ أَنْ ذَكَرَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبَا بَكْرٍ فَعَلِمْتُ أَنَّهُ لَمْ يَكُنْ لِيَعْدِلَ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَحَدًا وَأَنَّهُ غَيْرُ مُسْتَخْلِفٍ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1823: 12) من طريق عبد الرزاق أخبرنا ، عن الزهري، أخبرني سالم، عن ابن عمر قال: فذكره.","grade":"صحيح","chapter_ar":"باب ليس للاستخلاف طريق خاص","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1823:12).","chapter_en":"There Is No Specific Method for Appointing a Successor","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":31,"content":{"translation":{"en":["Ibn ʿUmar said: I entered upon Hafsah, and she said: “Do you know that your father is not appointing a successor?” I said: “He would not do that.” She said: “He will.” So I swore that I would speak to him about it, but I remained silent until morning and did not speak to him. He said: It was as though I was carrying a mountain because of my oath until I returned and entered upon him. He asked me about the condition of the people, and I informed him. Then I said to him: “I heard the people saying something, and I swore that I would say it to you. They claim that you are not appointing a successor. If you had a shepherd of camels or a shepherd of sheep, then he came to you after leaving them, you would think he had neglected them. Caring for the people is even more serious.” He said: My statement agreed with him, so he lowered his head for a while, then raised it toward me and said: “Allah, Mighty and Majestic, will preserve His religion. If I do not appoint a successor, then the Messenger of Allah ﷺ did not appoint one. And if I appoint a successor, then Abu Bakr appointed one.” He said: By Allah, as soon as he mentioned the Messenger of Allah ﷺ and Abu Bakr, I knew that he would not equate anyone with the Messenger of Allah ﷺ, and that he would not appoint a successor."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1823,"lafz":true,"n":4714}],"full":1},{"num":7698,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ مَيْمُونٍ الأَوْدِيِّ، قَالَ رَأَيْتُ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ يَا عَبْدَ اللَّهِ بْنَ عُمَرَ، اذْهَبْ إِلَى أُمِّ الْمُؤْمِنِينَ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا فَقُلْ يَقْرَأُ عُمَرُ بْنُ الْخَطَّابِ عَلَيْكِ السَّلاَمَ، ثُمَّ سَلْهَا أَنْ أُدْفَنَ مَعَ صَاحِبَىَّ. قَالَتْ كُنْتُ أُرِيدُهُ لِنَفْسِي، فَلأُوثِرَنَّهُ الْيَوْمَ عَلَى نَفْسِي. فَلَمَّا أَقْبَلَ قَالَ لَهُ مَا لَدَيْكَ قَالَ أَذِنَتْ لَكَ يَا أَمِيرَ الْمُؤْمِنِينَ. قَالَ مَا كَانَ شَىْءٌ أَهَمَّ إِلَىَّ مِنْ ذَلِكَ الْمَضْجَعِ، فَإِذَا قُبِضْتُ فَاحْمِلُونِي ثُمَّ سَلِّمُوا ثُمَّ قُلْ يَسْتَأْذِنُ عُمَرُ بْنُ الْخَطَّابِ. فَإِنْ أَذِنَتْ لِي فَادْفِنُونِي، وَإِلاَّ فَرُدُّونِي إِلَى مَقَابِرِ الْمُسْلِمِينَ، إِنِّي لاَ أَعْلَمُ أَحَدًا أَحَقَّ بِهَذَا الأَمْرِ مِنْ هَؤُلاَءِ النَّفَرِ الَّذِينَ تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ عَنْهُمْ رَاضٍ، فَمَنِ اسْتَخْلَفُوا بَعْدِي فَهُوَ الْخَلِيفَةُ، فَاسْمَعُوا لَهُ وَأَطِيعُوا. فَسَمَّى عُثْمَانَ وَعَلِيًّا وَطَلْحَةَ وَالزُّبَيْرَ وَعَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ وَسَعْدَ بْنَ أَبِي وَقَّاصٍ، وَوَلَجَ عَلَيْهِ شَابٌّ مِنَ الأَنْصَارِ فَقَالَ أَبْشِرْ يَا أَمِيرَ الْمُؤْمِنِينَ بِبُشْرَى اللَّهِ، كَانَ لَكَ مِنَ الْقَدَمِ فِي الإِسْلاَمِ مَا قَدْ عَلِمْتَ، ثُمَّ اسْتُخْلِفْتَ فَعَدَلْتَ، ثُمَّ الشَّهَادَةُ بَعْدَ هَذَا كُلِّهِ. فَقَالَ لَيْتَنِي يَا ابْنَ أَخِي وَذَلِكَ كَفَافًا لاَ عَلَىَّ وَلاَ لِي أُوصِي الْخَلِيفَةَ مِنْ بَعْدِي بِالْمُهَاجِرِينَ الأَوَّلِينَ خَيْرًا، أَنْ يَعْرِفَ لَهُمْ حَقَّهُمْ، وَأَنْ يَحْفَظَ لَهُمْ حُرْمَتَهُمْ، وَأُوصِيهِ بِالأَنْصَارِ خَيْرًا الَّذِينَ تَبَوَّءُوا الدَّارَ وَالإِيمَانَ أَنْ يُقْبَلَ مِنْ مُحْسِنِهِمْ، وَيُعْفَى عَنْ مُسِيئِهِمْ، وَأُوصِيهِ بِذِمَّةِ اللَّهِ وَذِمَّةِ رَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُوفَى لَهُمْ بِعَهْدِهِمْ، وَأَنْ يُقَاتَلَ مِنْ وَرَائِهِمْ، وَأَنْ لاَ يُكَلَّفُوا فَوْقَ طَاقَتِهِمْ."],"takhrij":"صحيح: رواه البخاري في الزكاة (1392) عن قتيبة، حدثنا جرير بن عبدالحميد حدثنا حصين بن عبد الرحمن، عن عمرو بن ميمون الأودي فذكره.","grade":"صحيح","chapter_ar":"باب ليس للاستخلاف طريق خاص","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1392).","chapter_en":"There Is No Specific Method for Appointing a Successor","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":31,"content":{"translation":{"en":["ʿAmr ibn Maymun al-Awdi said: I saw ʿUmar ibn al-Khattab, may Allah be pleased with him, say: “ʿAbdullah ibn ʿUmar, go to the Mother of the Believers ʿA’ishah, may Allah be pleased with her, and say: ʿUmar ibn al-Khattab sends you greetings of peace. Then ask her that I be buried with my two companions.” She said: “I had wanted it for myself, but today I will prefer him over myself.” When he returned, ʿUmar said to him: “What do you have?” He said: “She has granted permission for you, Commander of the Believers.” He said: “Nothing was more important to me than that resting place. When I am taken in death, carry me, then give greetings of peace, then say: ʿUmar ibn al-Khattab seeks permission. If she gives permission, bury me there; otherwise return me to the graveyard of the Muslims. I do not know anyone more entitled to this affair than these individuals with whom the Messenger of Allah ﷺ was pleased when he died. Whoever they appoint after me is the caliph, so listen to him and obey.” He named ʿUthman, ʿAli, Talhah, al-Zubayr, ʿAbd al-Rahman ibn ʿAwf, and Saʿd ibn Abi Waqqas. A young man from the Ansar entered upon him and said: “Receive glad tidings, Commander of the Believers, with the glad tidings of Allah. You had precedence in Islam as you know, then you were appointed and acted justly, then martyrdom after all of this.” He said: “I wish, my nephew, that it would be just even: neither against me nor for me. I advise the caliph after me to treat the early Emigrants well, to recognize their rights and preserve their honor. I advise him to treat the Helpers well, those who settled the city and faith, to accept from those among them who do good and pardon those who do wrong. And I advise him concerning the covenant of Allah and the covenant of His Messenger ﷺ, that their agreement be fulfilled, that they be defended from behind, and that they not be burdened beyond their ability.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1392,"lafz":true}],"full":1,"rep":[3817]},{"num":7699,"demo":false,"sanad":"","matn":["عن الْمِسْوَرِ بن مَخْرَمَةَ أَخْبَرَهُ. أَنَّ الرَّهْطَ الَّذِينَ وَلاَّهُمْ عُمَرُ اجْتَمَعُوا فَتَشَاوَرُوا، قَالَ لَهُمْ عَبْدُ الرَّحْمَنِ لَسْتُ بِالَّذِي أُنَافِسُكُمْ عَلَى هَذَا الأَمْرِ، وَلَكِنَّكُمْ إِنْ شِئْتُمُ اخْتَرْتُ لَكُمْ مِنْكُمْ. فَجَعَلُوا ذَلِكَ إِلَى عَبْدِ الرَّحْمَنِ، فَلَمَّا وَلَّوْا عَبْدَ الرَّحْمَنِ أَمْرَهُمْ فَمَالَ النَّاسُ عَلَى عَبْدِ الرَّحْمَنِ، حَتَّى مَا أَرَى أَحَدًا مِنَ النَّاسِ يَتْبَعُ أُولَئِكَ الرَّهْطَ وَلاَ يَطَأُ عَقِبَهُ، وَمَالَ النَّاسُ عَلَى عَبْدِ الرَّحْمَنِ يُشَاوِرُونَهُ تِلْكَ اللَّيَالِيَ حَتَّى إِذَا كَانَتِ اللَّيْلَةُ الَّتِي أَصْبَحْنَا مِنْهَا، فَبَايَعْنَا عُثْمَانَ.","قال المسور: طرقني عبد الرحمن بعد هجع من الليل، فضرب الباب حتى استيقظت فقال: أراك نائما، فوالله ما اكتحلت هذه الليلة بكبير نوم، انطلق، فادع الزبير وسعدا فدعوتهما له فشاورهما، ثم دعاني فقال: ادع لي عليا، فدعوته، فناجاه حتى ابهار الليل، ثم قام علي من عنده وهو على طمع، وقد كان عبد الرحمن يخشى من علي شيئا، ثم قال: ادع لي عثمان، فدعوته، فناجاه حتى فرق بينهما المؤذن بالصبح، فلما صلى للناس الصبح، واجتمع أولئك الرهط عند المنبر، فأرسل إلى من كان حاضرا من المهاجرين والأنصار، وأرسل إلى أمراء الأجناد، وكانوا وافوا تلك الحجة مع عمر، فلما اجتمعوا تشهّد عبد الرحمن، ثم قال: أما بعد! يا علي، إني قد نظرت في أمر الناس، فلم أرهم يعدلون بعثمان، فلا تجعلنَّ على نفسك سبيلا، فقال: أبايعك على سنة الله ورسوله، والخليفتين من بعده، فبايعه عبد الرحمن، وبايعه الناس المهاجرون، والأنصار، وأمراء الأجناد، والمسلمون."],"takhrij":"صحيح: رواه البخاري في الأحكام (7207) عن عبد الله بن محمد بن أسماء حدثنا جويرية، عن مالك، عن الزهري، أن حميد بن عبد الرحمن، أخبره أن المسور بن مخرمة أخبره فذكره.","grade":"صحيح","chapter_ar":"باب ليس للاستخلاف طريق خاص","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7207).","chapter_en":"There Is No Specific Method for Appointing a Successor","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":31,"content":{"translation":{"en":["Al-Miswar ibn Makhramah narrated that the group whom ʿUmar appointed gathered and consulted. ʿAbd al-Rahman said to them: “I will not compete with you for this matter, but if you wish, I will choose one from among you for you.” So they entrusted that to ʿAbd al-Rahman. When they entrusted their matter to ʿAbd al-Rahman, the people turned to ʿAbd al-Rahman, until I did not see anyone among the people following that group or walking behind them. The people turned to ʿAbd al-Rahman, consulting him during those nights, until the night after which we woke and pledged allegiance to ʿUthman. Al-Miswar said: ʿAbd al-Rahman came to me after a portion of the night had passed and knocked on the door until I woke up. He said: “I see that you are sleeping. By Allah, I have not had much sleep this night. Go and call al-Zubayr and Saʿd.” So I called them for him, and he consulted them. Then he called me and said: “Call ʿAli for me.” So I called him, and he spoke privately with him until the night became very dark. Then ʿAli left him while still hoping for the matter, and ʿAbd al-Rahman had feared something from ʿAli. Then he said: “Call ʿUthman for me.” So I called him, and he spoke privately with him until the caller to prayer separated them at dawn. When he led the people in the dawn prayer and that group gathered near the pulpit, he sent for those present from the Emigrants and the Helpers, and he sent for the commanders of the armies, who had attended that pilgrimage with ʿUmar. When they gathered, ʿAbd al-Rahman testified, then said: “As for what follows: ʿAli, I have looked into the matter of the people, and I do not see them equating anyone with ʿUthman, so do not make a case against yourself.” He said: “I pledge allegiance to you upon the way of Allah and His Messenger, and the two caliphs after him.” So ʿAbd al-Rahman pledged allegiance to him, and the people pledged allegiance to him: the Emigrants, the Helpers, the commanders of the armies, and the Muslims."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7207,"lafz":true}],"full":1,"rep":[9893]},{"num":7700,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ مَيْمُونٍ قَالَ: فَلَمَّا قُبِضَ –يَعْنِي عُمَرَ بن الْخَطَّابِ- خَرَجْنَا بِهِ، فَانْطَلَقْنَا نَمْشِي، فَسَلَّمَ عَبْدُ اللَّهِ بْنُ عُمَرَ قَالَ: يَسْتَأْذِنُ عُمَرُ بْنُ الْخَطَّابِ قَالَتْ: أَدْخِلُوهُ، فَأُدْخِلَ، فَوُضِعَ هُنَالِكَ مَعَ صَاحِبَيْهِ، فَلَمَّا فُرِغَ مِنْ دَفْنِهِ اجْتَمَعَ هَؤُلاَءِ الرَّهْطُ فَقَالَ عَبْدُ الرَّحْمَنِ: اجْعَلُوا أَمْرَكُمْ إِلَى ثَلاَثَةٍ مِنْكُمْ، فَقَالَ الزُّبَيْرُ: قَدْ جَعَلْتُ أَمْرِي إِلَى عَلِيٍّ، فَقَالَ طَلْحَةُ: قَدْ جَعَلْتُ أَمْرِي إِلَى عُثْمَانَ، وَقَالَ سَعْدٌ: قَدْ جَعَلْتُ أَمْرِي إِلَى عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ فَقَالَ عَبْدُ الرَّحْمَنِ: أَيُّكُمَا تَبَرَّأَ مِنْ هَذَا الأَمْرِ، فَنَجْعَلُهُ إِلَيْهِ، وَاللَّهُ عَلَيْهِ وَالإِسْلاَمُ، لَيَنْظُرَنَّ أَفْضَلَهُمْ فِي نَفْسِهِ، فَأُسْكِتَ الشَّيْخَانِ، فَقَالَ عبدالرحمن: أَفَتَجْعَلُونَهُ إِلَى، وَاللَّهُ عَلَى أَنْ لاَ آلِ عَنْ أَفْضَلِكُمْ؟ قَالاَ: نَعَمْ فَأَخَذَ بِيَدِ أَحَدِهِمَا، فَقَالَ: لَكَ قَرَابَةٌ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَالْقَدَمُ فِي الإِسْلاَمِ مَا قَدْ عَلِمْتَ، فَاللَّهُ عَلَيْكَ لَئِنْ أَمَّرْتُكَ لَتَعْدِلَنَّ، وَلَئِنْ أَمَّرْتُ عُثْمَانَ، لَتَسْمَعَنَّ وَلَتُطِيعَنَّ، ثُمَّ خَلاَ بِالآخَرِ، فَقَالَ لَهُ: مِثْلَ ذَلِكَ، فَلَمَّا أَخَذَ الْمِيثَاقَ قَالَ: ارْفَعْ يَدَكَ يَا عُثْمَانُ، فَبَايَعَهُ فَبَايَعَ لَهُ عَلِيٌّ، وَوَلَجَ أَهْلُ الدَّارِ فَبَايَعُوهُ."],"takhrij":"صحيح: رواه البخاري في فضائل أصحاب النبي صلى الله عليه وسلم (3700) عن موسى بن إسماعيل حدثنا أبو عوانة، عن حصين، عن عمرو بن ميمون قال: فذكر الحديث بطوله، وفيه قصة مقتل عمر رضي الله عنه.","grade":"صحيح","chapter_ar":"باب ليس للاستخلاف طريق خاص","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3700).","chapter_en":"There Is No Specific Method for Appointing a Successor","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":31,"content":{"translation":{"en":["ʿAmr ibn Maymun said: When he was taken in death — meaning ʿUmar ibn al-Khattab — we went out with him and walked. ʿAbdullah ibn ʿUmar gave greetings of peace and said: “ʿUmar ibn al-Khattab seeks permission.” She said: “Bring him in.” So he was brought in and placed there with his two companions. When his burial was completed, those members of the group gathered. ʿAbd al-Rahman said: “Entrust your matter to three among you.” Al-Zubayr said: “I have entrusted my matter to ʿAli.” Talhah said: “I have entrusted my matter to ʿUthman.” Saʿd said: “I have entrusted my matter to ʿAbd al-Rahman ibn ʿAwf.” ʿAbd al-Rahman said: “Which of you two will withdraw from this matter so that we may entrust it to him, with Allah and Islam upon him, that he will surely look to the one he considers best?” The two elders remained silent. ʿAbd al-Rahman said: “Will you entrust it to me, with Allah upon me that I will not fall short in choosing the best of you?” They said: “Yes.” He took the hand of one of them and said: “You have kinship with the Messenger of Allah ﷺ and precedence in Islam as you know. By Allah, if I appoint you, you must act justly; and if I appoint ʿUthman, you must listen and obey.” Then he met privately with the other and said the same to him. When he had taken the covenant, he said: “Raise your hand, ʿUthman.” He pledged allegiance to him, ʿAli pledged allegiance to him, and the people of the house entered and pledged allegiance to him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3700,"lafz":true}],"full":1},{"num":7701,"demo":false,"sanad":"","matn":["عَنْ مَعْدَانَ بْنِ أَبِي طَلْحَةَ، أَنَّ عُمَرَ بْنَ الْخَطَّابِ، خَطَبَ يَوْمَ الْجُمُعَةِ فَذَكَرَ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَذَكَرَ أَبَا بَكْرٍ قَالَ إِنِّي رَأَيْتُ كَأَنَّ دِيكًا نَقَرَنِي ثَلاَثَ نَقَرَاتٍ وَإِنِّي لاَ أُرَاهُ إِلاَّ حُضُورَ أَجَلِي وَإِنَّ أَقْوَامًا يَأْمُرُونَنِي أَنْ أَسْتَخْلِفَ وَإِنَّ اللَّهَ لَمْ يَكُنْ لِيُضَيِّعَ دِينَهُ وَلاَ خِلاَفَتَهُ وَلاَ الَّذِي بَعَثَ بِهِ نَبِيَّهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَإِنْ عَجِلَ بِي أَمْرٌ فَالْخِلاَفَةُ شُورَى بَيْنَ هَؤُلاَءِ السِّتَّةِ الَّذِينَ تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ عَنْهُمْ رَاضٍ وَإِنِّي قَدْ عَلِمْتُ أَنَّ أَقْوَامًا يَطْعَنُونَ فِي هَذَا الأَمْرِ أَنَا ضَرَبْتُهُمْ بِيَدِي هَذِهِ عَلَى الإِسْلاَمِ فَإِنْ فَعَلُوا ذَلِكَ فَأُولَئِكَ أَعْدَاءُ اللَّهِ الْكَفَرَةُ الضُّلاَّلُ."],"takhrij":"صحيح: رواه مسلم في المساجد (567: 78) عن محمد بن المثنى حدثنا يحيى بن سعيد حدثنا هشام حدثنا قتادة عن سالم بن أبي الجعد عن معدان بن أبي طلحة فذكره.","grade":"صحيح","chapter_ar":"باب ليس للاستخلاف طريق خاص","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (567:78).","chapter_en":"There Is No Specific Method for Appointing a Successor","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":31,"content":{"translation":{"en":["Maʿdan ibn Abi Talhah narrated that ʿUmar ibn al-Khattab delivered a sermon on Friday, mentioned the Prophet of Allah ﷺ, and mentioned Abu Bakr. He said: “I saw as though a rooster pecked me three pecks, and I only see that as the coming of my death. Some people are telling me to appoint a successor. Allah would never let His religion, His caliphate, or that with which He sent His Prophet ﷺ be lost. If a matter comes quickly upon me, then the caliphate is to be decided by consultation among these six men with whom the Messenger of Allah ﷺ was pleased when he died. I know that some people will criticize this matter, though I struck them with this hand of mine for Islam. If they do that, then they are the enemies of Allah, disbelieving and misguided.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":567,"lafz":true}],"full":1},{"num":7702,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ قَدِمَ مُسَيْلِمَةُ الْكَذَّابُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَعَلَ يَقُولُ إِنْ جَعَلَ لِي مُحَمَّدٌ الأَمْرَ مِنْ بَعْدِهِ تَبِعْتُهُ. وَقَدِمَهَا فِي بَشَرٍ كَثِيرٍ مِنْ قَوْمِهِ، فَأَقْبَلَ إِلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَعَهُ ثَابِتُ بْنُ قَيْسِ بْنِ شَمَّاسٍ، وَفِي يَدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قِطْعَةُ جَرِيدٍ، حَتَّى وَقَفَ عَلَى مُسَيْلِمَةَ فِي أَصْحَابِهِ فَقَالَ لَوْ سَأَلْتَنِي هَذِهِ الْقِطْعَةَ مَا أَعْطَيْتُكَهَا، وَلَنْ تَعْدُوَ أَمْرَ اللَّهِ فِيكَ، وَلَئِنْ أَدْبَرْتَ لَيَعْقِرَنَّكَ اللَّهُ، وَإِنِّي لأَرَاكَ الَّذِي أُرِيتُ فِيكَ مَا رَأَيْتُ."],"takhrij":"متفق عليه: رواه البخاري في المناقب (3620)، ومسلم في الرؤيا (2273: 21) كلاهما من طريق أبي اليمان، أخبرنا شعيب عن عبد الله بن أبي حسين، حدثنا نافع بن جبير، عن ابن عباس رضي الله عنهما قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب طلب مسيلمة الكذاب الخلافة بعد النبي ﷺ","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3620) and Muslim (2273:21).","chapter_en":"Musaylimah the Liar’s Request for the Caliphate After the Prophet ﷺ","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":32,"content":{"translation":{"en":["Ibn ʿAbbas said: Musaylimah the Liar came during the time of the Messenger of Allah ﷺ and began saying: “If Muhammad appoints me to the affair after him, I will follow him.” He came with many people from his tribe. The Messenger of Allah ﷺ approached him, with Thabit ibn Qays ibn Shammas, and in the hand of the Messenger of Allah ﷺ was a piece of palm stalk, until he stood over Musaylimah among his companions. He said: “If you asked me for this piece, I would not give it to you. You will not go beyond what Allah has decreed for you. If you turn away, Allah will destroy you. I see that you are the one concerning whom I was shown what I saw. This is Thabit; he will answer you on my behalf.” Then he turned away from him."]},"buhuth":{"en":["His statement, “If Muhammad appoints me to the affair after him,” means the caliphate.","The Prophet’s statement ﷺ, “I see that you are the one concerning whom I was shown,” refers to the vision he saw. ʿUbaydullah ibn ʿAbdullah said: I asked ʿAbdullah ibn ʿAbbas about the vision of the Messenger of Allah ﷺ that he mentioned, and Ibn ʿAbbas said: The Messenger of Allah ﷺ told me: “While I was sleeping, I was shown that two bracelets of gold had been placed in my hands. I was disturbed by them and disliked them, then I was given permission and blew upon them, so they flew away. I interpreted them as two liars who would emerge.” ʿUbaydullah said: One of them was al-ʿAnsi, whom Fayruz killed in Yemen, and the other was Musaylimah the Liar. Al-Bukhari mentioned it (4379).","The phrase “in the house of the daughter of al-Harith, and beneath him was the daughter of al-Harith ibn Kurayz” means she was the wife of Musaylimah the Liar before she married another, and for that reason Musaylimah and his people stayed with her. Their number was seventeen men, as al-Waqidi mentioned."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3620,"lafz":true},{"key":"muslim","label":"مسلم","number":2273}],"full":1,"dr":1},{"num":7703,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَا بَعَثَ اللَّهُ مِنْ نَبِيٍّ وَلاَ اسْتَخْلَفَ مِنْ خَلِيفَةٍ، إِلاَّ كَانَتْ لَهُ بِطَانَتَانِ، بِطَانَةٌ تَأْمُرُهُ بِالْمَعْرُوفِ وَتَحُضُّهُ عَلَيْهِ، وَبِطَانَةٌ تَأْمُرُهُ بِالشَّرِّ وَتَحُضُّهُ عَلَيْهِ، فَالْمَعْصُومُ مَنْ عَصَمَ اللَّهُ تَعَالَى."],"takhrij":"صحيح: رواه البخاري في الأحكام (7198) عن أصبغ، أخبرنا ابن وهب، أخبرني يونس، عن ابن شهاب، عن أبي سلمة، عن أبي سعيد الخدري فذكره.","grade":"صحيح","chapter_ar":"باب الحث على اتخاذ البطانة الصالحة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7198).","chapter_en":"Encouragement to Take Righteous Advisers","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":33,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated from the Prophet ﷺ that he said: “Allah never sent a prophet and never appointed a caliph except that he had two inner circles: an inner circle that commands him to what is right and urges him toward it, and an inner circle that commands him to evil and urges him toward it. The protected one is the one whom Allah the Exalted protects.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7198,"lafz":true}],"full":1,"dr":1},{"num":7704,"demo":false,"sanad":"","matn":["عَنْ أَبِي أَيُّوبَ، أَنَّهُ قَالَ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ مَا بُعِثَ مِنْ نَبِيٍّ وَلاَ كَانَ بَعْدَهُ مِنْ خَلِيفَةٍ إِلاَّ وَلَهُ بِطَانَتَانِ بِطَانَةٌ تَأْمُرُهُ بِالْمَعْرُوفِ وَتَنْهَاهُ عَنِ الْمُنْكَرِ وَبِطَانَةٌ لاَ تَأْلُوهُ خَبَالاً فَمَنْ وُقِيَ بِطَانَةَ السُّوءِ فَقَدْ وُقِيَ."],"takhrij":"صحيح: رواه النسائي (4203)، والطحاوي في شرح المشكل (2112)، والطبراني في الكبير (4/156) من طرق عن الليث –هو ابن سعد- عن عبيد الله بن أبي جعفر عن صفوان –هو ابن سُليم- عن أبي سلمة، عن أبي أيوب فذكره.","grade":"صحيح","chapter_ar":"باب الحث على اتخاذ البطانة الصالحة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (4203), al-Tahawi in Sharh al-Mushkil (2112), and al-Tabarani in al-Kabir (4/156).","chapter_en":"Encouragement to Take Righteous Advisers","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":33,"content":{"translation":{"en":["Abu Ayyub said: I heard the Messenger of Allah ﷺ say: “No prophet was sent, and no caliph came after him, except that he had two inner circles: an inner circle that commands him to what is right and forbids him from what is wrong, and an inner circle that spares no effort in corrupting him. Whoever is protected from the evil inner circle has been protected.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4203,"lafz":true,"n":4203},{"key":"sh22547","label":"الطحاوي في شرح المشكل","number":2112},{"key":"mujamkabir","label":"الطبراني في الكبير","number":4}],"full":1,"dr":1},{"num":7705,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا مِنْ وَالٍ إِلاَّ وَلَهُ بِطَانَتَانِ بِطَانَةٌ تَأْمُرُهُ بِالْمَعْرُوفِ وَتَنْهَاهُ عَنِ الْمُنْكَرِ وَبِطَانَةٌ لاَ تَأْلُوهُ خَبَالاً فَمَنْ وُقِيَ شَرَّهَا فَقَدْ وُقِيَ وَهُوَ مِنَ الَّتِي تَغْلِبُ عَلَيْهِ مِنْهُمَا."],"takhrij":"صحيح: رواه النسائي (4201)، وأحمد (7239)، وصحّحه ابن حبان (6191) كلهم من حديث الزهري، عن أبي سلمة بن عبد الرحمن، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب الحث على اتخاذ البطانة الصالحة","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (4201), Ahmad (7239), and graded authentic by Ibn Hibban (6191).","chapter_en":"Encouragement to Take Righteous Advisers","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":33,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “There is no governor except that he has two inner circles: an inner circle that commands him to what is right and forbids him from what is wrong, and an inner circle that spares no effort in corrupting him. Whoever is protected from its evil has been protected, and he will be according to whichever of the two overcomes him.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4201,"lafz":true,"n":4201},{"key":"ibnhibban","label":"صححه ابن حبان","number":6191},{"key":"ahmad","label":"مسند الإمام أحمد","number":7239,"n":7239},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":3107,"n":3103}],"full":1,"dr":1},{"num":7706,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَرَادَ اللَّهُ بِالأَمِيرِ خَيْرًا جَعَلَ لَهُ وَزِيرَ صِدْقٍ إِنْ نَسِيَ ذَكَّرَهُ وَإِنْ ذَكَرَ أَعَانَهُ وَإِذَا أَرَادَ اللَّهُ بِهِ غَيْرَ ذَلِكَ جَعَلَ لَهُ وَزِيرَ سُوءٍ إِنْ نَسِيَ لَمْ يُذَكِّرْهُ وَإِنْ ذَكَرَ لَمْ يُعِنْهُ."],"takhrij":"صحيح: رواه أبو داود (2932) واللفظ له، والنسائي (4204)، وأحمد (24414)، وابن حبان (4494)، والبيهقي (10/111-112) كلهم من طرق عن القاسم بن محمد، عن عائشة فذكرته. وفي بعض طرقه ضعف يسير يتقوى بمجيئه من طرق أخرى.","grade":"صحيح","chapter_ar":"باب اتخاذ الوزير","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2932), with his wording; al-Nasa’i (4204), Ahmad (24414), Ibn Hibban (4494), and al-Bayhaqi (10/111–112). Some of its routes contain slight weakness, which is strengthened by its transmission through other routes.","chapter_en":"Taking a Minister","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":34,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ said: “When Allah intends good for a ruler, He gives him a truthful minister: if he forgets, he reminds him, and if he remembers, he helps him. And when Allah intends otherwise for him, He gives him an evil minister: if he forgets, he does not remind him, and if he remembers, he does not help him.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2932,"lafz":true},{"key":"nasai","label":"النسائي","number":4204},{"key":"kubrabayhaqi","label":"البيهقي","number":10},{"key":"ahmad","label":"مسند الإمام أحمد","number":24414,"n":24414},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4517,"n":4513},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":20320,"n":20478},{"key":"ibnhibban","label":"ابن حبان","number":4494}],"full":1,"rep":[6718]},{"num":7707,"demo":false,"sanad":"","matn":["عَنْ عَدِيِّ بْنِ عَمِيرَةَ الْكِنْدِيِّ، قَالَ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ مَنِ اسْتَعْمَلْنَاهُ مِنْكُمْ عَلَى عَمَلٍ فَكَتَمَنَا مِخْيَطًا فَمَا فَوْقَهُ كَانَ غُلُولاً يَأْتِي بِهِ يَوْمَ الْقِيَامَةِ. قَالَ فَقَامَ إِلَيْهِ رَجُلٌ أَسْوَدُ مِنَ الأَنْصَارِ كَأَنِّي أَنْظُرُ إِلَيْهِ فَقَالَ يَا رَسُولَ اللَّهِ اقْبَلْ عَنِّي عَمَلَكَ قَالَ وَمَا لَكَ. قَالَ سَمِعْتُكَ تَقُولُ كَذَا وَكَذَا. قَالَ وَأَنَا أَقُولُهُ الآنَ مَنِ اسْتَعْمَلْنَاهُ مِنْكُمْ عَلَى عَمَلٍ فَلْيَجِئْ بِقَلِيلِهِ وَكَثِيرِهِ فَمَا أُوتِيَ مِنْهُ أَخَذَ وَمَا نُهِيَ عَنْهُ انْتَهَى."],"takhrij":"صحيح: رواه مسلم في الإمارة (1833) عن أبي بكر بن أبي شيبة، حدثنا وكيع بن الجراح، حدثنا إسماعيل بن أبي خالد، عن قيس بن أبي حازم، عن عدي بن عميرة الكندي قال: فذكره.","grade":"صحيح","chapter_ar":"باب إثم من استُعمل على عمل، فسرق منه شيئًا","chapter_ur":"","part_ar":"كتاب الإمارة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1833).","chapter_en":"The Sin of One Appointed to a Task Who Steals Anything from It","part_en":"Book of Leadership","group_ar":"","group_en":"","part_no":42,"group_no":0,"chapter_no":35,"content":{"translation":{"en":["ʿAdi ibn ʿUmayrah al-Kindi said: I heard the Messenger of Allah ﷺ say: “Whoever among you we appoint over a task, and he conceals from us even a needle or anything greater than it, it will be misappropriation that he will bring on the Day of Resurrection.” He said: A black man from the Ansar stood up to him — it is as though I can still see him — and said: “Messenger of Allah, take back your appointment from me.” He said: “What is the matter with you?” He said: “I heard you say such-and-such.” He said: “And I say it now: Whoever among you we appoint over a task, let him bring its little and its much. Whatever he is given from it, he may take, and whatever he is forbidden from, he must refrain from.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1833,"lafz":true}],"full":1,"rep":[4003]}]);
